INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'Kezdetben teremté Isten az eget és a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'A föld pedig kietlen és puszta vala, és setétség vala a mélység színén, és az Isten Lelke lebeg vala a vizek felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'És monda Isten: Legyen világosság: és lőn világosság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'És látá Isten, hogy jó a világosság; és elválasztá Isten a világosságot a setétségtől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'És nevezé Isten a világosságot nappalnak, és a setétséget nevezé éjszakának: és lőn este és lőn reggel, első nap.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'És monda Isten: Legyen mennyezet a víz között, a mely elválaszsza a vizeket a vizektől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'Teremté tehát Isten a mennyezetet, és elválasztá a mennyezet alatt való vizeket, a mennyezet felett való vizektől. És úgy lőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'És nevezé Isten a mennyezetet égnek: és lőn este, és lőn reggel, második nap.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'És monda Isten: Gyűljenek egybe az ég alatt való vizek egy helyre, hogy tessék meg a száraz. És úgy lőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'És nevezé Isten a szárazat földnek; az egybegyűlt vizeket pedig tengernek nevezé. És látá Isten, hogy jó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Azután monda Isten: Hajtson a föld gyenge fűvet, maghozó fűvet, gyümölcsfát, a mely gyümölcsöt hozzon az ő neme szerint, a melyben legyen néki magva e földön. És úgy lőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'Hajta tehát a föld gyenge fűvet, maghozó fűvet az ő neme szerint, és gyümölcstermő fát, a melynek gyümölcsében mag van az ő neme szerint. És látá Isten, hogy jó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'És lőn este és lőn reggel, harmadik nap.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'És monda Isten: Legyenek világító testek az ég mennyezetén, hogy elválaszszák a nappalt az éjszakától, és legyenek jelek, és meghatározói ünnepeknek, napoknak és esztendőknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'És legyenek világítókul az ég mennyezetén hogy világítsanak a földre. És úgy lőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Teremté tehát Isten a két nagy világító testet: a nagyobbik világító testet, hogy uralkodjék nappal és a kisebbik világító testet, hogy uralkodjék éjjel; és a csillagokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'És helyezteté Isten azokat az ég mennyezetére, hogy világítsanak a földre;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'És hogy uralkodjanak a nappalon és az éjszakán, és elválaszszák a világosságot a setétségtől. És látá Isten, hogy jó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'És lőn este és lőn reggel, negyedik nap.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'És monda Isten: Pezsdűljenek a vizek élő állatok nyüzsgésétől; és madarak repdessenek a föld felett, az ég mennyezetének színén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'És teremté Isten a nagy vízi állatokat, és mindazokat a csúszó-mászó állatokat, a melyek nyüzsögnek a vizekben az ő nemök szerint, és mindenféle szárnyas repdesőt az ő neme szerint. És látá Isten, hogy jó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'És megáldá azokat Isten, mondván: Szaporodjatok, és sokasodjatok, és töltsétek be a tenger vizeit; a madár is sokasodjék a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'És lőn este és lőn reggel, ötödik nap.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Azután monda az Isten: Hozzon a föld élő állatokat nemök szerint: barmokat, csúszó-mászó állatokat és szárazföldi vadakat nemök szerint. És úgy lőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Teremté tehát Isten a szárazföldi vadakat nemök szerint, a barmokat nemök szerint, és a földön csúszó-mászó mindenféle állatokat nemök szerint. És látá Isten, hogy jó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'És monda Isten: Teremtsünk embert a mi képünkre és hasonlatosságunkra; és uralkodjék a tenger halain, az ég madarain, a barmokon, mind az egész földön, és a földön csúszó-mászó mindenféle állatokon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Teremté tehát az Isten az embert az ő képére, Isten képére teremté őt: férfiúvá és asszonynyá teremté őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'És megáldá Isten őket, és monda nékik Isten: Szaporodjatok és sokasodjatok, és töltsétek be a földet és hajtsátok birodalmatok alá; és uralkodjatok a tenger halain, az ég madarain, és a földön csúszó-mászó mindenféle állatokon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'És monda Isten: Ímé néktek adok minden maghozó fűvet az egész föld színén, és minden fát, a melyen maghozó gyümölcs van; az legyen néktek eledelül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'A föld minden vadainak pedig, és az ég minden madarainak, és a földön csúszó-mászó mindenféle állatoknak, a melyekben élő lélek van, a zöld fűveket adom eledelűl. És úgy lőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'És látá Isten, hogy minden a mit teremtett vala, ímé igen jó. És lőn este és lőn reggel, hatodik nap.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'És elvégezteték az ég és a föld, és azoknak minden serege.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'Mikor pedig elvégezé Isten hetednapon az ő munkáját, a melyet alkotott vala, megszűnék a hetedik napon minden munkájától, a melyet alkotott vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'És megáldá Isten a hetedik napot, és megszentelé azt; mivelhogy azon szűnt vala meg minden munkájától, melyet teremtve szerzett vala Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Ez az égnek és a földnek eredete, a mikor teremtettek. Mikor az Úr Isten a földet és az eget teremté,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'Még semmiféle mezei növény sem vala a földön, s még semmiféle mezei fű sem hajtott ki, mert az Úr Isten még nem bocsátott vala esőt a földre; és ember sem vala, ki a földet mívelje;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'Azonban pára szállott vala fel a földről, és megnedvesíté a föld egész színét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'És formálta vala az Úr Isten az embert a földnek porából, és lehellett vala az ő orrába életnek lehelletét. Így lőn az ember élő lélekké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'És ültete az Úr Isten egy kertet Édenben, napkelet felől, és abba helyezteté az embert, a kit formált vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'És nevele az Úr Isten a földből mindenféle fát, tekintetre kedvest és eledelre jót, az élet fáját is, a kertnek közepette, és a jó és gonosz tudásának fáját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Folyóvíz jő vala pedig ki Édenből a kert megöntözésére; és onnét elágazik és négy főágra szakad vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Az elsőnek neve Pison, ez az, a mely megkerüli Havilah egész földét, a hol az arany terem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'És annak a földnek aranya igen jó; ott van a Bdelliom és az Onix-kő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'A második folyóvíz neve pedig Gihon; ez az, a mely megkerüli az egész Khús földét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'És a harmadik folyóvíz neve Hiddekel; ez az, a mely Assiria hosszában foly. A negyedik folyóvíz pedig az Eufrátes.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'És vevé az Úr Isten az embert, és helyezteté őt az Éden kertjébe, hogy mívelje és őrizze azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'És parancsola az Úr Isten az embernek, mondván: A kert minden fájáról bátran egyél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'De a jó és gonosz tudásának fájáról, arról ne egyél; mert a mely napon ejéndel arról, bizony meghalsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'És monda az Úr Isten: Nem jó az embernek egyedül lenni; szerzek néki segítő társat, hozzá illőt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'És formált vala az Úr Isten a földből mindenféle mezei vadat, és mindenféle égi madarat, és elvivé az emberhez, hogy lássa, minek nevezze azokat; mert a mely nevet adott az ember az élő állatnak, az annak neve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'És nevet ada az ember minden baromnak, az ég madarainak, és minden mezei vadnak; de az embernek hozzá illő segítő társat nem talált vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Bocsáta tehát az Úr Isten mély álmot az emberre, és ez elaluvék. Akkor kivőn egyet annak oldalbordái közűl, és hússal tölté be annak helyét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'És alkotá az Úr Isten azt az oldalbordát, a melyet kivett vala az emberből, asszonynyá, és vivé az emberhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'És monda az ember: Ez már csontomból való csont, és testemből való test: ez asszonyembernek neveztessék, mert emberből vétetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Annakokáért elhagyja a férfiú az ő atyját és az ő anyját, és ragaszkodik feleségéhez: és lesznek egy testté.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Valának pedig mindketten mezítelenek, az ember és az ő felesége, és nem szégyenlik vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'A kígyó pedig ravaszabb vala minden mezei vadnál, melyet az Úr Isten teremtett vala, és monda az asszonynak: Csakugyan azt mondta az Isten, hogy a kertnek egy fájáról se egyetek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'És monda az asszony a kígyónak: A kert fáinak gyümölcséből ehetünk;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'De annak a fának gyümölcséből, mely a kertnek közepette van, azt mondá Isten: abból ne egyetek, azt meg se illessétek, hogy meg ne haljatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'És monda a kígyó az asszonynak: Bizony nem haltok meg;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'Hanem tudja az Isten, hogy a mely napon ejéndetek abból, megnyilatkoznak a ti szemeitek, és olyanok lésztek mint az Isten: jónak és gonosznak tudói.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'És látá az asszony, hogy jó az a fa eledelre s hogy kedves a szemnek, és kivánatos az a fa a bölcseségért: szakaszta azért annak gyümölcséből, és evék, és ada vele levő férjének is, és az is evék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'És megnyilatkozának mindkettőjöknek szemei s észrevevék, hogy mezítelenek; figefa levelet aggatának azért össze, és körülkötőket csinálának magoknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'És meghallák az Úr Isten szavát, a ki hűvös alkonyatkor a kertben jár vala; és elrejtőzék az ember és az ő felesége az Úr Isten elől a kert fái között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Szólítá ugyanis az Úr Isten az embert és monda néki: Hol vagy?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'És monda: Szavadat hallám a kertben, és megfélemlém, mivelhogy mezítelen vagyok, és elrejtezém.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'És monda Ő: Ki mondá néked, hogy mezítelen vagy? Avagy talán ettél a fáról, melytől tiltottalak, hogy arról ne egyél?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'És monda az ember: Az asszony, a kit mellém adtál vala, ő ada nékem arról a fáról, úgy evém.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'És monda az Úr Isten az asszonynak: Mit cselekedtél? Az asszony pedig monda: A kígyó ámított el engem, úgy evém.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'És monda az Úr Isten a kígyónak: Mivelhogy ezt cselekedted, átkozott légy minden barom és minden mezei vad között; hasadon járj, és port egyél életed minden napjaiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'És ellenségeskedést szerzek közötted és az asszony között, a te magod között, és az ő magva között: az neked fejedre tapos, te pedig annak sarkát mardosod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'Az asszonynak monda: Felette igen megsokasítom viselősséged fájdalmait, fájdalommal szűlsz magzatokat; és epekedel a te férjed után, ő pedig uralkodik te rajtad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Az embernek pedig monda: Mivelhogy hallgattál a te feleséged szavára, és ettél arról a fáról, a melyről azt parancsoltam, hogy ne egyél arról: Átkozott legyen a föld te miattad, fáradságos munkával élj belőle életednek minden napjaiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Töviset és bogácskórót teremjen tenéked; s egyed a mezőnek fűvét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'Orczád verítékével egyed a te kenyeredet, míglen visszatérsz a földbe, mert abból vétettél: mert por vagy te s ismét porrá leszesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Nevezte vala pedig Ádám az ő feleségét Évának, mivelhogy ő lett anyja minden élőnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'És csinála az Úr Isten Ádámnak és az ő feleségének bőr ruhákat, és felöltözteté őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'És monda az Úr Isten: Ímé az ember olyanná lett, mint mi közűlünk egy, jót és gonoszt tudván. Most tehát, hogy ki ne nyújtsa kezét, hogy szakaszszon az élet fájáról is, hogy egyék, s örökké éljen:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Kiküldé őt az Úr Isten az Éden kertjéből, hogy mívelje a földet, a melyből vétetett vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'És kiűzé az embert, és oda helyezteté az Éden kertjének keleti oldala felől a Kerúbokat és a villogó pallos lángját, hogy őrizzék az élet fájának útját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Azután ismeré Ádám az ő feleségét Évát, a ki fogad vala méhében és szűli vala Kaint, és monda: Nyertem férfiat az Úrtól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'És ismét szűlé annak atyjafiát, Ábelt. És Ábel juhok pásztora lőn, Kain pedig földmívelő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Lőn pedig idő multával, hogy Kain ajándékot vive az Úrnak a föld gyümölcséből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'És Ábel is vive az ő juhainak első fajzásából és azoknak kövérségéből. És tekinte az Úr Ábelre és az ő ajándékára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'Kainra pedig és az ő ajándékára nem tekinte, miért is Kain haragra gerjede és fejét lecsüggeszté.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'És monda az Úr Kainnak: Miért gerjedtél haragra? és miért csüggesztéd le fejedet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Hiszen, ha jól cselekszel, emelt fővel járhatsz; ha pedig nem jól cselekszel, a bűn az ajtó előtt leselkedik, és reád van vágyódása; de te uralkodjál rajta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'És szól s beszél vala Kain Ábellel, az ő atyjafiával. És lőn, mikor a mezőn valának, támada Kain Ábelre az ő atyjafiára, és megölé őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'És monda az Úr Kainnak: Hol van Ábel a te atyádfia? Ő pedig monda: Nem tudom, avagy őrizője vagyok-é én az én atyámfiának?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Monda pedig az Úr: Mit cselekedtél? A te atyádfiának vére kiált én hozzám a földről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Mostan azért átkozott légy e földön, mely megnyitotta az ő száját, hogy befogadja a te atyádfiának vérét, a te kezedből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Mikor a földet míveled, ne adja az többé néked az ő termő erejét, bujdosó és vándorló légy a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Akkor monda Kain az Úrnak: Nagyobb az én büntetésem, hogysem elhordozhatnám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Ímé elűzöl engem ma e földnek színéről, és a te színed elől el kell rejtőznöm; bujdosó és vándorló leszek a földön, és akkor akárki talál reám, megöl engemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'És monda néki az Úr: Sőt inkább, aki megöléndi Kaint, hétszerte megbüntettetik. És megbélyegzé az Úr Kaint, hogy senki meg ne ölje, a ki rátalál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'És elméne Kain az Úr színe elől, és letelepedék Nód földén, Édentől keletre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'És ismeré Kain az ő feleségét, az pedig fogada méhében, és szűlé Hánókhot. És építe várost, és nevezé azt az ő fiának nevéről Hánókhnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'És lett Hánókhnak fia, Irád: És Irád nemzé Mekhujáelt: Mekhujáel pedig nemzé Methusáelt, és Methusáel nemzé Lámekhet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Lámekh pedig vett magának két feleséget: az egyiknek neve Háda, a másiknak neve Czilla.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'És szűlé Háda Jábált. Ez volt atyjok a sátorban-lakóknak, és a barompásztoroknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Az ő atyjafiának pedig Jubál vala neve: ez volt atyja minden lantosnak és síposnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Czilla pedig szűlé Tubálkaint, mindenféle réz- és vasszerszámok kovácsolóját: és Tubálkain hugát, Nahamát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Akkor monda Lámekh az ő feleségeinek: Oh Háda és Czilla, hallgassatok szómra, Lámekh feleségei, halljátok beszédem: embert öltem, mert megsebzett; ifjat öltem, mert megütött.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Ha hétszeres a bosszú Kainért, hetvenhétszeres az Lámekhért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Ádám pedig ismét ismeré az ő feleségét, és az szűle néki fiat, és nevezé annak nevét Séthnek: mert adott úgymond, énnékem az Isten más magot Ábel helyett, kit megöle Kain.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Séthnek is született fia, és nevezé annak nevét Énósnak. Akkor kezdték segítségül hívni az Úrnak nevét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Ez az Ádám nemzetségének könyve. A mely napon teremté Isten az embert, Isten hasonlatosságára teremté azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Férfiúvá és asszonynyá teremté őket, és megáldá őket és nevezé az ő nevöket Ádámnak, a mely napon teremtetének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Élt vala pedig Ádám száz harmincz esztendőt, és nemze fiat az ő képére és hasonlatosságára és nevezé annak nevét Séthnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'És telének Ádám napjai, minekutánna Séthet nemzette, nyolczszáz esztendőre, és nemze fiakat és leányokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'És lőn Ádám egész életének ideje kilenczszáz harmincz esztendő; és meghala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Éle pedig Séth száz öt esztendőt, és nemzé Énóst.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'És éle Séth, minekutánna Énóst nemzette, nyolczszáz hét esztendeig; és nemze fiakat és leányokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'És lőn Séth egész életének ideje kilenczszáz tizenkét esztendő; és meghala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Éle pedig Énós kilenczven esztendőt, és nemzé Kénánt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'És éle Énós, minekutánna Kénánt nemzette, nyolczszáz tizenöt esztendeig, és nemze fiakat és leányokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'És lőn Énós egész életének ideje kilenczszáz öt esztendő; és meghala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Éle pedig Kénán hetven esztendőt, és nemzé Mahalálélt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'És éle Kénán, minekutánna Mahalálélt nemzette, nyolczszáz negyven esztendeig; és nemze fiakat és leányokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'És lőn Kénán egész életének ideje kilenczszáz tíz esztendő; és meghala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Éle pedig Mahalálél hatvanöt esztendőt, és nemzé Járedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'És éle Mahalálél, minekutánna Járedet nemzette, nyolczszáz harmincz esztendeig, és nemze fiakat és leányokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'És lőn Mahalálél egész életének ideje nyolczszáz kilenczvenöt esztendő; és meghala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Éle pedig Járed száz hatvankét esztendőt, és nemzé Énókhot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'És éle Járed, minekutánna Énókhot nemzette, nyolczszáz esztendőt; és nemze fiakat és leányokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'És lőn Járed egész életének ideje kilenczszáz hatvankét esztendő; és meghala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Éle pedig Énókh hatvanöt esztendőt, és nemzé Methuséláht.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'És járt Énókh az Istennel, minekutánna Methuséláht nemzette, háromszáz esztendeig; és nemze fiakat és leányokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'És lőn Énókh egész életének ideje háromszáz hatvanöt esztendő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'És mivel Énókh Istennel járt vala; eltűnék, mert Isten magához vevé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Éle pedig Methusélah száz nyolczvanhét esztendőt és nemzé Lámekhet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'És éle Methusélah, minekutánna Lámekhet nemzette, hétszáz nyolczvankét esztendőt; és nemze fiakat és leányokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'És lőn Methusélah egész életének ideje kilenczszáz hatvankilencz esztendő; és meghala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Éle pedig Lámekh száz nyolczvankét esztendőt, és nemze fiat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'És nevezé azt Noénak, mondván: Ez vígasztal meg minket munkálkodásunkban s kezünk terhes fáradozásában e földön, melyet megátkozott az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'És éle Lámekh, minekutánna Noét nemzette, ötszáz kilenczvenöt esztendőt; és nemze fiakat és leányokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'És lőn Lámekh egész életének ideje hétszázhetvenhét esztendő; és meghala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'És mikor Noé ötszáz esztendős volt, nemzé Noé Sémet, Khámot és Jáfetet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Lőn pedig, hogy az emberek sokasodni kezdének a föld színén, és leányaik születének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'És láták az Istennek fiai az emberek leányait, hogy szépek azok, és vevének magoknak feleségeket mind azok közűl, kiket megkedvelnek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'És monda az Úr: Ne maradjon az én lelkem örökké az emberben, mivelhogy ő test; legyen életének ideje száz húsz esztendő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'Az óriások valának a földön abban az időben, sőt még azután is, mikor az Isten fiai bémenének az emberek leányaihoz, és azok gyermekeket szűlének nékik. Ezek ama hatalmasok, kik eleitől fogva híres-neves emberek voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'És látá az Úr, hogy megsokasult az ember gonoszsága a földön, és hogy szíve gondolatának minden alkotása szüntelen csak gonosz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'Megbáná azért az Úr, hogy teremtette az embert a földön, és bánkódék az ő szívében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'És monda az Úr: Eltörlöm az embert, a kit teremtettem, a földnek színéről; az embert, a barmot, a csúszó-mászó állatokat, és az ég madarait; mert bánom, hogy azokat teremtettem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'De Noé kegyelmet talála az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Noénak pedig ez a története: Noé igaz, tökéletes férfiú vala a vele egykorúak között. Istennel jár vala Noé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'És nemze Noé három fiat: Sémet, Khámot és Jáfetet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'A föld pedig romlott vala Isten előtt és megtelék a föld erőszakoskodással.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Tekinte azért Isten a földre, és ímé meg vala romolva, mert minden test megrontotta vala az ő útát a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Monda azért Isten Noénak: Minden testnek vége elérkezett előttem, mivelhogy a föld erőszakoskodással telt meg általok: és ímé elvesztem őket a földdel egybe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Csinálj magadnak bárkát gófer fából, rekesztékeket csinálj a bárkában, és szurkozd meg belől és kivűl szurokkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Ekképen csináld pedig azt: A bárka hoszsza háromszáz sing legyen, a szélessége ötven sing, és a magassága harmincz sing.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Ablakot csinálj a bárkán, és egy singnyire hagyd azt felülről; a bárka ajtaját pedig oldalt csináld; alsó, közép, és harmad padlásúvá csináld azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Én pedig ímé özönvizet hozok a földre, hogy elveszessek minden testet, a melyben élő lélek van az ég alatt; valami a földön van, elvész.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'De te veled szövetséget kötök, és bemégy a bárkába, te és a te fiaid, feleséged és a te fiaidnak feleségei teveled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'És minden élőből, s minden testből, mindenből kettőt-kettőt vígy be a bárkába, hogy veled együtt életben maradjanak: hímek és nőstények legyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'A madarak közűl az ő nemök szerint, a barmok közűl az ő nemök szerint és a földnek minden csúszó-mászó állatjai közűl az ő nemök szerint; mindenből kettő-kettő menjen be hozzád, hogy életben maradjanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Te pedig szerezz magadnak mindenféle eledelt, mely megehető, és takarítsd be magadhoz, hogy neked is, azoknak is legyen eledelűl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'És úgy cselekedék Noé; a mint parancsolta vala néki Isten, mindent akképen cselekedék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Monda az Úr Noénak: Menj be te, és egész házadnépe a bárkába: mert téged láttalak igaznak előttem ebben a nemzedékben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'Minden tiszta baromból hetet-hetet vígy be, hímet és nőstényét; azokból a barmokból pedig, a melyek nem tiszták, kettőt-kettőt, hímet és nőstényét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'Az égi madarakból is hetet-hetet, hímet és nőstényét, hogy magvok maradjon az egész föld színén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Mert hét nap múlva esőt bocsátok a földre negyven nap és negyven éjjel; és eltörlök a föld színéről minden állatot, melyet teremtettem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Cselekedék azért Noé mind a szerint, a mint az Úr néki megparancsolta vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Noé pedig hatszáz esztendős vala, mikor az özönvíz volt a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Beméne azért Noé és az ő fiai, az ő felesége, és fiainak feleségei ő vele a bárkába, az özönvíz elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'A tiszta barmok közűl, és a tisztátalan barmok közűl, a madarak közűl, és minden földön csúszó-mászó állat közűl,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'Kettő-kettő méne be Noéhoz a bárkába, hím és nőstény: a mint Isten megparancsolta vala Noénak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Lőn pedig hetednapra, hogy megjöve az özönvíz a földre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'Noé életének hatszázadik esztendejében, a második hónapban, e hónap tizenhetedik napján, felfakadának ezen a napon a nagy mélység minden forrásai, és az ég csatornái megnyilatkozának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'És esék az eső a földre negyven nap és negyven éjjel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'Ugyanezen a napon ment vala be Noé és Sém és Khám és Jáfet, Noénak fiai, és Noé felesége és az ő fiainak három felesége velök együtt a bárkába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'Ők, és minden vad az ő neme szerint és minden barom az ő neme szerint és minden csúszó-mászó állat, mely csúsz-mász a földön, az ő neme szerint és minden repdeső állat az ő neme szerint, minden madár, minden szárnyas állat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'Kettő-kettő méne be Noéhoz a bárkába minden testből, melyben élő lélek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'A melyek pedig bemenének, hím és nőstény méne be minden testből, a mint parancsolta vala Isten őnéki: és az Úr bezára utána az ajtót.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Mikor az özönvíz negyven napig volt a földön, annyira nevekedének a vizek, hogy felveheték a bárkát, és az felemelkedék a földről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'A vizek pedig áradának és egyre nevekedének a földön, és a bárka jár vala a víz színén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Azután a vizek felette igen nagy erőt vevének a földön, és a legmagasabb hegyek is mind elboríttatának, melyek az egész ég alatt valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Tizenöt singgel nevekedének a vizek feljebb, minekutánna a hegyek elboríttattak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'És oda vesze minden földön járó test, madár, barom, vad, és a földön nyüzsgő minden csúszó-mászó állat; és minden ember.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Mindaz, a minek orrában élő lélek lehellete vala, a szárazon valók közűl mind meghala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'És eltörle az Isten minden állatot, a mely a föld színén vala, az embertől a baromig, a csúszó-mászó állatig, és az égi madárig; mindenek eltöröltetének a földről; és csak Noé marada meg, és azok a kik vele valának a bárkában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'És erőt vevének a vizek a földön, száz ötven napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Megemlékezék pedig az Isten Noéról, és minden vadról, minden baromról, mely ő vele a bárkában vala: és szelet bocsáta az Isten a földre, és a vizek megapadának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'És bezárulának a mélység forrásai s az ég csatornái; és megszűnt az eső az égből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'És elmenének a vizek a földről folyton fogyván, és száz ötven nap mulva megfogyatkozának a vizek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'A bárka pedig a hetedik hónapban, a hónak tizenhetedik napján, megfeneklett az Ararát hegyén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'A vizek pedig folyton fogyának a tizedik hónapig; a tizedikben, a hó első napján meglátszának a hegyek csúcsai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'És lőn negyven nap múlva, kinyitá Noé a bárka ablakát, melyet csinált vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'És kibocsátá a hollót, és az elrepűlt, meg visszaszállt, míg a vizek a földről felszáradának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Kibocsátá a galambot is, hogy meglássa, vajjon elfogytak-é a vizek a föld színéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'De a galamb nem talála lábainak nyugvóhelyet és visszatére ő hozzá a bárkába, mert víz vala az egész föld színén; ő pedig kezét kinyujtá, megfogá, és bévevé azt magához a bárkába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'És várakozék még másik hét napig, és ismét kibocsátá a galambot a bárkából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'És megjöve ő hozzá a galamb estennen, és ímé leszakasztott olajfalevél vala annak szájában. És megtudá Noé, hogy elapadt a víz a földről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'És ismét várakozék még másik hét napig, és kibocsátá a galambot, és az nem tére többé ő hozzá vissza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'És lőn a hatszáz egyedik esztendőben, az első hónak első napján, felszáradának a vizek a földről, és elfordítá Noé a bárka fedelét, és látá, hogy ímé megszikkadt a földnek színe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'A második hónapban pedig, a hónak huszonhetedik napján megszárada a föld.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'És szóla az Isten Noénak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Menj ki a bárkából te és a te feleséged, a te fiaid, és a te fiaid feleségei te veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Minden vadat, mely veled van, minden testből, madarat, barmot, és minden földön csúszó-mászó állatot vígy ki magaddal, hogy nyüzsögjenek a földön, szaporodjanak és sokasodjanak a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Kiméne azért Noé és az ő fiai, az ő felesége, és az ő fiainak feleségei ő vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Minden állat, minden csúszó-mászó, minden madár, minden a mi mozog a földön, kijöve a bárkából az ő neme szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'És oltárt építe Noé az Úrnak, és vőn minden tiszta állatból és minden tiszta madárból, és áldozék égőáldozattal az oltáron.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'És megérezé az Úr a kedves illatot, és monda az Úr az ő szívében: Nem átkozom meg többé a földet az emberért, mert az ember szívének gondolatja gonosz az ő ifjúságától fogva; és többé nem vesztem el mind az élő állatot, mint cselekedtem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Ennekutánna míg a föld lészen, vetés és aratás, hideg és meleg, nyár és tél, nap és éjszaka meg nem szünnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Azután megáldá Isten Noét és az ő fiait, és azt mondá nékik: Szaporodjatok és sokasodjatok, és töltsétek be a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'És féljen és rettegjen tőletek a földnek minden állatja az égnek minden madara: minden a mi nyüzsög a földön, és a tengernek minden hala kezetekbe adatott;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Minden mozgó állat, a mely él legyen nektek eledelűl; a mint a zöld fűvet, nektek adtam mindazokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Csak a húst az őt elevenítő vérrel meg ne egyétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'De a ti véreteket, a melyben van a ti éltetek, számon kérem; számon kérem minden állattól, azonképen az embertől, kinek-kinek atyjafiától számon kérem az ember életét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'A ki ember-vért ont, annak vére ember által ontassék ki; mert Isten a maga képére teremté az embert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Ti pedig szaporodjatok és sokasodjatok, nyüzsögjetek a földön és sokasodjatok azon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'És szóla az Isten Noénak és vele az ő fiainak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'Én pedig ímé szövetséget szerzek ti veletek és a ti magvatokkal ti utánnatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'És minden élő állattal, mely veletek van: madárral, barommal, minden mezei vaddal, mely veletek van; mindattól kezdve a mi a bárkából kijött, a földnek minden vadjáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Szövetséget kötök ti veletek, hogy soha ezután el nem vész özönvíz miatt minden test; és soha sem lesz többé özönvíz a földnek elvesztésére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'És monda az Isten: Ez a jele a szövetségnek, melyet én örök időkre szerzek közöttem és ti köztetek, és minden élő állat között, mely ti veletek van:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Az én ívemet helyeztetem a felhőkbe, s ez lesz jele a szövetségnek közöttem és a föld között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'És lészen, hogy mikor felhővel borítom be a földet, meglátszik az ív a felhőben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'És megemlékezem az én szövetségemről, mely van én közöttem és ti közöttetek, és minden testből való élő állat között; és nem lesz többé a víz özönné minden testnek elvesztésére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Azért legyen tehát az ív a felhőben, hogy lássam azt és megemlékezzem az örökkévaló szövetségről Isten között és minden testből való élő állat között, mely a földön van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'És monda Isten Noénak: Ez ama szövetségnek jele, melyet szerzettem én közöttem és minden test között, mely a földön van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Valának pedig Noé fiai, kik a bárkából kijöttek vala: Sém és Khám és Jáfet. Khám pedig Kanaánnak atyja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Ezek hárman a Noé fiai s ezektől népesedék meg az egész föld.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Noé pedig földmívelő kezde lenni, és szőlőt ültete.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'És ivék a borból, s megrészegedék, és meztelenen vala sátra közepén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Khám pedig, Kanaánnak atyja, meglátá az ő atyjának mezítelenségét, és hírűl adá künnlevő két testvérének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Akkor Sém és Jáfet ruhát ragadván, azt mindketten vállokra veték, és háttal menve takarák be atyjok mezítelenségét; s arczczal hátra meg sem láták atyjok mezítelenségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Hogy felserkene Noé mámorából, és megtudá a mit vele az ő kisebbik fia cselekedett vala:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'Monda: Átkozott Kanaán! Szolgák szolgája legyen atyjafiai közt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Azután monda: Áldott az Úr, Sémnek Istene, néki légyen szolgája Kanaán!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Terjeszsze ki Isten Jáfetet, lakozzék Sémnek sátraiban; légyen néki szolgája a Kanaán!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Éle pedig Noé az özönvíz után háromszáz ötven esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'És vala Noé egész életének ideje kilenczszáz ötven esztendő; és meghala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Ez pedig a Noé fiainak, Sémnek, Khámnak és Jáfetnek nemzetsége; és fiaik születének az özönvíz után.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Jáfetnek fiai: Gómer, Mágog, Madai, Jáván, Thubál, Mésekh és Thirász.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'A Gómer fiai pedig: Askhenáz, Rifáth, és Tógármah.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Jávánnak pedig fiai: Elisah, Thársis, Kitthim és Dodánim.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Ezekből váltak ki a szigetlakó népek az ő országaikban, mindenik a maga nyelve, családja és nemzetsége szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Khámnak pedig fiai: Khús, Miczráim, Pút és Kanaán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Khúsnak pedig fiai: Széba, Hávilah, Szábthah, Rahmáh, Szabthékah. Rahmáhnak pedig fiai: Séba és Dédán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Khús nemzé Nimródot is; ez kezde hatalmassá lenni a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Ez hatalmas vadász vala az Úr előtt, azért mondják: Hatalmas vadász az Úr előtt, mint Nimród.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Az ő birodalmának kezdete volt Bábel, Erekh, Akkád és Kálnéh a Sineár földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'E földről ment aztán Assiriába, és építé Ninivét, Rekhoboth városát, és Kaláht.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'És Reszent Ninivé között és Kaláh között: ez az a nagy város.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Miczráim pedig nemzé: Lúdimot, Anámimot, Lehábimot és Naftukhimot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'Pathruszimot és Kaszlukhimot, a honnan a Filiszteusok származtak, és Kafthorimot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Kanaán pedig nemzé Czídont, az ő elsőszülöttét, és Khétet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'Jebuzeust, Emorreust, és Girgazeust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'Khivveust, Harkeust, és Szineust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'Arvadeust, Czemareust, Hamatheust. És azután elszéledének a Kananeusok nemzetségei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'Vala pedig a Kananeusok határa, Czídonból Gérár felé menve Gázáig; Sodoma, Gomora, Ádmáh, és Czeboim felé menve Lésáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Ezek a Khám fiai családjok, nyelvök, földjök s nemzetségök szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Sémnek is lettek gyermekei; a ki Héber minden fiainak atyja, Jáfetnek testvérbátyja vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Sém fiai: Élám, Assur, Arpaksád, Lúd és Arám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Arámnak fiai pedig: Úcz, Húl, Gether és Más.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Arpaksád pedig nemzé Séláht, Séláh pedig Hébert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Hébernek is lett két fia: Az egyiknek neve Péleg, mivelhogy az ő idejében osztatott el a föld; testvérének pedig neve Joktán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Joktán pedig nemzé Almodádot, Sélefet, Haczarmávethet és Jerákhot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'Hadórámot, Úzált és Dikláth.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'Obált, Abimáélt és Sébát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'Ofirt, Havilát és Jóbábot. Ezek mind a Joktán fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'És vala ezeknek lakása, Mésától fogva Séfárba menve a napkeleti hegyekig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Ezek a Sém fiai családjok, nyelvök, földjök és nemzetségök szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Ezek a Noé fiainak családjai az ő nemzetségeik szerint, az ő népeik között, és ezektől szaporodának el a népek a földön, az özönvíz után.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Mind az egész földnek pedig egy nyelve és egyféle beszéde vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'És lőn mikor kelet felől elindultak vala, Sineár földén egy síkságot találának és ott letelepedének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'És mondának egymásnak: Jertek, vessünk téglát és égessük ki jól; és lőn nékik a tégla kő gyanánt, a szurok pedig ragasztó gyanánt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'És mondának: Jertek, építsünk magunknak várost és tornyot, melynek teteje az eget érje, és szerezzünk magunknak nevet, hogy el ne széledjünk az egész földnek színén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Az Úr pedig leszálla, hogy lássa a várost és a tornyot, melyet építenek vala az emberek fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'És monda az Úr: Ímé e nép egy, s az egésznek egy a nyelve, és munkájának ez a kezdete; és bizony semmi sem gátolja, hogy véghez ne vigyenek mindent, a mit elgondolnak magukban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Nosza szálljunk alá, és zavarjuk ott össze nyelvöket, hogy meg ne értsék egymás beszédét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'És elszéleszté őket onnan az Úr az egész földnek színére; és megszűnének építeni a várost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Ezért nevezék annak nevét Bábelnek; mert ott zavará össze az Úr az egész föld nyelvét, és onnan széleszté el őket az Úr az egész földnek színére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Ez a Sém nemzetsége: Sém száz esztendős korában nemzé Arpaksádot, két esztendővel az özönvíz után.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'És éle Sém, minekutánna nemzette Arpaksádot, ötszáz esztendeig és nemze fiakat és leányokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Arpaksád pedig harminczöt esztendős vala, és nemzé Séláht.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'És éle Arpaksád, minekutánna nemzette Séláht, négyszáz három esztendeig, és nemze fiakat és leányokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Séláh pedig harmincz esztendős vala, és nemzé Hébert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'És éle Séláh, minekutánna nemzé Hébert, négyszáz három esztendeig, és nemze fiakat és leányokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Héber pedig harmincznégy esztendős vala és nemzé Péleget.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'És éle Héber, minekutánna nemzé Péleget, négyszáz harmincz esztendeig, és nemze fiakat és leányokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Péleg pedig harmincz esztendős vala, és nemzé Réut.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'És éle Péleg, minekutánna nemzé Réut, kétszáz kilencz esztendeig, és nemze fiakat és leányokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Réu pedig harminczkét esztendős vala, és nemzé Sérugot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'És éle Réu, minekutánna nemzé Sérugot, kétszáz hét esztendeig és nemze fiakat és leányokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Sérug pedig harmincz esztendős vala, és nemzé Nákhort.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'És éle Sérug, minekutánna nemzé Nákhort, kétszáz esztendeig, és nemze fiakat és leányokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Nákhor pedig huszonkilencz esztendős vala, és nemzé Thárét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'És éle Nákhor, minekutánna nemzé Thárét, száz tizenkilencz esztendeig, és nemze fiakat és leányokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Tháré pedig hetven esztendős vala, és nemzé Ábrámot, Nákhort, Háránt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Ez a Tháré nemzetsége: Tháré nemzé Ábrámot, Nákhort és Háránt. Hárán pedig nemzé Lótot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Meghala pedig Hárán, az ő atyjának Thárénak szemei előtt, az ő születésének földjén, Úr-Kaszdimban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Ábrám pedig és Nákhor vőnek magoknak feleséget: az Ábrám feleségének neve Szárai; a Nákhor feleségének neve Milkhah, Háránnak Milkhah atyjának és Jiszkáh atyjának leánya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Szárai pedig magtalan vala; nem vala néki gyermeke.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'És felvevé Tháré Ábrámot az ő fiát, és Lótot, Háránnak fiát, az ő unokáját, és Szárait, az ő menyét, Ábrámnak az ő fiának feleségét, és kiindulának együtt Úr-Kaszdimból, hogy Kanaán földére menjenek. És eljutának Háránig, és ott letelepedének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Vala pedig Tháré kétszáz öt esztendős, és meghala Tháré Háránban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'És monda az Úr Ábrámnak: Eredj ki a te földedből, és a te rokonságod közül, és a te atyádnak házából, a földre, a melyet én mutatok néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'És nagy nemzetté tészlek, és megáldalak téged, és felmagasztalom a te nevedet, és áldás leszesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'És megáldom azokat, a kik téged áldanak, és a ki téged átkoz, megátkozom azt: és megáldatnak te benned a föld minden nemzetségei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'És kiméne Ábrám, a mint az Úr mondotta vala néki, és Lót is kiméne ő vele: Ábrám pedig hetvenöt esztendős vala, mikor kiméne Háránból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'És felvevé Ábrám az ő feleségét Szárait, és Lótot, az ő atyjafiának fiát, és minden szerzeményöket, a melyet szereztek vala, és a cselédeket, a kikre Háránban tettek vala szert, és elindulának, hogy Kanaán földére menjenek, és el is jutának a Kanaán földére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'És általméne Ábrám a földön mind Sikhem vidékéig, Móréh tölgyeséig. Akkor Kananeusok valának azon a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'És megjelenék az Úr Ábrámnak, és monda néki: A te magodnak adom ezt a földet. És Ábrám oltárt építe ott az Úrnak; a ki megjelent vala néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Onnan azután a hegység felé méne Bétheltől keletre és felüté sátorát: Béthel vala nyugatra, Hái pedig keletre, és ott oltárt építe az Úrnak, és segítségűl hívá az Úr nevét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'És tovább költözék Ábrám; folyton délfelé húzódván.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Azonban éhség lőn az országban, és Ábrám aláméne Égyiptomba, hogy ott tartózkodjék, mert nagy vala az éhség az országban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'És lőn mikor közel vala, hogy bemenjen Égyiptomba, monda feleségének Szárainak: Ímé tudom, hogy szép ábrázatú asszony vagy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'Azért mikor meglátnak téged az égyiptomiak, majd azt mondják: felesége ez; és engem megölnek, téged pedig életben tartanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Mondd azért, kérlek, hogy húgom vagy; hogy jól legyen dolgom miattad, s életben maradjak te éretted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'És lőn mikor Ábrám Égyiptomba érkezék, láták az égyiptomiak az asszonyt, hogy az nagyon szép.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Mikor megláták őt a Faraó főemberei, magasztalák a Faraó előtt és elvivék az asszonyt a Faraó udvarába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'És jól tőn érette Ábrámmal, és valának juhai, ökrei, szamarai, szolgái, szolgálói, nőstényszamarai és tevéi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'De megveré az Úr a Faraót és az ő házát nagy csapásokkal, Száraiért, Ábrám feleségéért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Hívatá azért a Faraó Ábrámot és monda: Miért mívelted ezt velem? Miért nem mondottad meg énnékem, hogy ez néked feleséged?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Miért mondottad: Húgom ő; azért vevém magamnak feleségűl. Most már imhol a te feleséged, vedd magadhoz és menj el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'És parancsola felőle a Faraó némely embereknek, a kik elbocsáták őtet és az ő feleségét, és mindenét a mije vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Feljöve azért Ábrám Égyiptomból, ő és az ő felesége, és mindene valamije vala, és Lót is ő vele, a déli tartományba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Ábrám pedig igen gazdag vala barmokkal, ezüsttel és aranynyal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'És méne helyről helyre délfelől mind Béthelig, oda a hol először vala az ő sátora, Béthel és Hái között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'Annak az oltárnak helyére, melyet ott elsőben készített vala: és segítségűl hívá ott Ábrám az Úrnak nevét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Lótnak is pedig, a ki Ábrámmal jár vala, valának juhai, ökrei és sátorai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'És nem bírá meg őket az a föld, hogy együtt lakjanak, mert sok jószáguk vala, és nem lakhatának együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Versengés is támada az Ábrám barompásztorai között, és a Lót barompásztorai között; és a Kananeusok és a Perizeusok is ott laknak vala akkor azon a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Monda azért Ábrám Lótnak: Ne legyen versengés közöttem és közötted, se az én pásztoraim között és a te pásztoraid között: hiszen atyafiak vagyunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Avagy nincsen-é előtted mind az egész föld? Válj el kérlek, tőlem; ha te balra tartasz, én jobbra megyek; ha te jobbra menéndesz, én balra térek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Felemelé azért Lót az ő szemeit, és látá, hogy a Jordán egész melléke bővizű föld; mert minekelőtte elvesztette volna az Úr Sodomát és Gomorát, mind Czoárig olyan vala az, mint az Úr kertje, mint Égyiptom földe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'És választá Lót magának a Jordán egész mellékét, és elköltözék Lót kelet felé: és elválának egymástól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Ábrám lakozik vala a Kanaán földén, Lót pedig lakozik vala a Jordán-melléki városokban, és sátoroz vala Sodomáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Sodoma lakosai pedig nagyon gonoszok és bűnösök valának az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Az Úr pedig monda Ábrámnak, minekutánna elválék tőle Lót: Emeld fel szemeidet és tekints arról a helyről, a hol vagy, északra, délre, keletre és nyugotra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'Mert mind az egész földet, a melyet látsz, néked adom, és a te magodnak örökre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'És olyanná tészem a te magodat, mint a földnek pora, hogyha valaki megszámlálhatja a földnek porát, a te magod is megszámlálható lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Kelj fel, járd be ez országot hosszában és széltében: mert néked adom azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Elébb mozdítá azért sátorát Ábrám, és elméne, és lakozék Mamré tölgyesében, mely Hebronban van, és oltárt építe ott az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Lőn pedig Amrafelnek, Sineár királyának és Ariókhnak, Elászár királyának, Khédorlaomernek, Élám királyának, és Thidálnak, a Góim királyának napjaiban:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'Hadat indítának ezek Bera, Sodoma királya ellen, Birsa, Gomora királya ellen, Sináb, Admáh királya ellen, Seméber, Czeboim királya ellen és Bélah, azaz Czoár királya ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Mind ezek a Sziddim völgyében egyesűlének; ez a Sóstenger.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Tizenkét esztendeig szolgálták vala Khédorlaomert, és a tizenharmadik esztendőben ellene támadtak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'A tizennegyedik esztendőben pedig eljöve Khédorlaomer, és a királyok, a kik ő vele valának, és megverék a Refeusokat Asztheroth Kárnajimban, és a Zuzeusokat Hámban, és az Emeusokat Sávé-Kirjáthajimban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'És a Horeusokat az ő hegyökön, a Seiren, egész Él-Páránig, mely a puszta mellett van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'És megtérének s menének Hén Mispátba, azaz Kádesbe, és elpusztíták az Amálekiták egész mezőségét, és az Emoreusokat is, kik laknak vala Háczaczon-Thámárban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Kiméne tehát Sodoma királya, Gomora királya, Admáh királya, Czeboim királya, és Bélah, azaz Czoár királya, és megütközének azokkal a Sziddim völgyében:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'Khédorlaomerrel, Élám királyával, és Thidállal, Gójim királyával, Amráfellel, Sineár királyával, és Ariókhkal, Elászár királyával: négy király öt ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'A Siddim völgye pedig tele vala szurok-forrásokkal. És megfutamodának Sodoma és Gomora királyai, és azokba esének: a megmaradottak pedig a hegységbe futának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'És elvivék Sodomának és Gomorának minden jószágát és minden eleségét; és elmenének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Elvivék Lótot is az Ábrám atyjafiának fiát jószágostól együtt, és elmenének; mert Lót Sodomában lakik vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Eljöve pedig egy menekűlt és hírűl hozá a héber Ábrámnak, a ki lakik vala az Emoreus Mamrénak, Eskol atyjafiának és Áner atyjafiának tölgyesében, a kik meg Ábrámnak szövetségesei valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'A mint meghallá Ábrám, hogy az ő atyjafia fogságba esett, felfegyverzé házában nevekedett háromszáz tizennyolcz próbált legényét és üldözve nyomula Dánig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'És csapatokra oszolván ellenök éjszaka ő és szolgái, megveré őket, és űzé őket mind Hóbáig, a mely Damaskustól balra esik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'És visszahozá mind a jószágot; Lótot is, az ő atyjafiát jószágával egybe visszahozá, meg az asszonyokat és a népet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Minekutánna pedig visszatért Khédorlaomernek és a vele volt királyoknak megveréséből, kiméne ő elébe Sodomának királya a Sáve völgyébe, azaz a király völgyébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Melkhisédek pedig Sálem királya, kenyeret és bort hoza; ő pedig a Magasságos Istennek papja vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'És megáldá őt, és monda: Áldott legyen Ábrám a Magasságos Istentől, ég és föld teremtőjétől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'Áldott a Magasságos Isten, a ki kezedbe adta ellenségeidet. És tizedet ada néki mindenből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'És monda Sodoma királya Ábrámnak: Add nékem a népet, a jószágot pedig vedd magadnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'És monda Ábrám Sodoma királyának: Felemeltem az én kezemet az Úrhoz, a Magasságos Istenhez, ég és föld teremtőjéhez:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'Hogy én egy fonalszálat, vagy egy sarukötőt sem veszek el mindabból, a mi a tiéd, hogy ne mondjad: Én gazdagítottam meg Ábrámot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'Semmi egyebet, csupán a legények élelmét, és ama férfiak részét, kik én velem eljöttek volt: Áner, Eskhol, Mamré, ők vegyék ki az ő részöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'E dolgok után lőn az Úr beszéde Ábrámhoz látomásban, mondván: Ne félj Ábrám: én paizsod vagyok tenéked, a te jutalmad felette igen bőséges.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'És monda Ábrám: Uram Isten, mit adnál énnékem, holott én magzatok nélkűl járok, és az, a kire az én házam száll, a Damaskusbeli Eliézer?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'És monda Ábrám: Ímé énnékem nem adtál magot, és ímé az én házam szolgaszülöttje lesz az én örökösöm.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'És ímé szóla az Úr ő hozzá, mondván: Nem ez lesz a te örökösöd: hanem a ki a te ágyékodból származik, az lesz a te örökösöd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'És kivivé őt, és monda: Tekints fel az égre, és számláld meg a csillagokat, ha azokat megszámlálhatod; – és monda nékie: Így lészen a te magod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'És hitt az Úrnak és tulajdoníttaték az őnéki igazságul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'És monda néki: Én vagyok az Úr, ki téged kihoztalak Úr-Kaszdimból, hogy néked adjam e földet, örökségedűl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'És monda: Uram Isten, miről tudhatom meg, hogy öröklöm azt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'És felele néki: Hozz nékem egy három esztendős üszőt, egy három esztendős kecskét, és egy három esztendős kost, egy gerliczét és egy galambfiat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Elhozá azért mind ezeket, és kétfelé hasítá azokat, és mindeniknek fele részét a másik fele része átellenébe helyezteté; de a madarakat nem hasította vala kétfelé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'És ragadozó madarak szállának e húsdarabokra, de Ábrám elűzi vala azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'És lőn naplementekor, mély álom lepé meg Ábrámot, és ímé rémülés és nagy setétség szálla ő reá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'És monda az Úr Ábrámnak: Tudván tudjad, hogy a te magod jövevény lesz a földön, mely nem övé, és szolgálatra szorítják, és nyomorgatják őket négyszáz esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'De azt a népet, melyet szolgálnak, szintén megítélem én, és annakutánna kijőnek nagy gazdagsággal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Te pedig elmégy a te atyáidhoz békességgel, eltemettetel jó vénségben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Csak a negyedik nemzedék tér meg ide; mert az Emoreusok gonoszsága még nem tölt be.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'És mikor a nap leméne és setétség lőn, ímé egy füstölgő kemencze, és tüzes fáklya, mely általmegyen vala a húsdarabok között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'E napon kötött az Úr szövetséget Ábrámmal, mondván: A te magodnak adom ezt a földet Égyiptomnak folyóvizétől fogva, a nagy folyóig, az Eufrátes folyóvízig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'A Keneusokat, Kenizeusokat, és a Kadmoneusokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'A Hittheusokat, Perizeusokat, és a Refeusokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'Az Emoreusokat, Kananeusokat, Girgazeusokat, és a Jebuzeusokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'És Szárai, az Ábrám felesége nem szűle néki; de vala néki egy Égyiptomból való szolgálója, kinek neve Hágár vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Monda azért Szárai Ábrámnak: Ímé az Úr bezárolta az én méhemet, hogy ne szűljek: kérlek, menj be az én szolgálómhoz, talán az által megépülök; és engede Ábrám a Szárai szavának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Vevé tehát Szárai, Ábrám felesége az Égyiptombeli Hágárt, az ő szolgálóját, tíz esztendővel azután, hogy Ábrám a Kanaán földén letelepedék, és adá azt Ábrámnak az ő férjének feleségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'És béméne Hágárhoz, és az fogada az ő méhében; ez pedig a mint látta, hogy terhes, nem vala becsülete az ő asszonyának ő előtte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Monda azért Szárai Ábrámnak: Bántódásom van miattad. Én adtam öledbe szolgálómat, és mivelhogy látja, hogy teherbe esett, nincsen előtte becsületem. Tegyen ítéletet az Úr én közöttem és te közötted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'És monda Ábrám Szárainak: Ímé a te szolgálód kezedben van, azt tedd vele a mit jónak látsz. Nyomorgatja vala azért Szárai, és az elfuta ő előle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'És találá őt az Úrnak angyala egy forrásnál a pusztában, annál a forrásnál, a mely a Súrba menő úton van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'És monda: Hágár, Szárai szolgálója! honnan jössz és hová mégy? És az monda: Az én asszonyomnak, Szárainak színe elől futok én.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Akkor monda néki az Úr angyala: Térj meg a te asszonyodhoz, és alázd meg magad az ő kezei alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'És monda néki az Úrnak angyala: Felettébb megsokasítom a te magodat, hogy sokasága miatt megszámlálható se legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'És monda néki az Úrnak angyala: Ímé te terhes vagy, és szűlsz fiat; és nevezd nevét Ismáelnek, mivelhogy meghallá Isten a te nyomorúságodat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Az pedig vadtermészetű ember lesz: az ő keze mindenek ellen, és mindenek keze ő ellene; és minden ő atyjafiának ellenébe üti fel sátorát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'És nevezé Hágár az Úrnak nevét, a ki ő vele szólott vala: Te vagy a látomás Istene. Mert monda: Avagy nem e helyen láttam a látomás után?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Annakokáért nevezé azt a forrást Lakhai Rói forrásának; ott van Kádes és Béred között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'És fiat szűle Hágár Ábrámnak, és nevezé Ábrám az ő fiának nevét, a kit Hágár szűl vala néki, Ismáelnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Ábrám pedig nyolczvanhat esztendős vala, a mikor Hágár Ismáelt szűlé Ábrámnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Mikor Ábrám kilenczvenkilencz esztendős vala, megjelenék az Úr Ábrámnak, és monda néki: Én a mindenható Isten vagyok, járj én előttem, és légy tökéletes.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'És megkötöm az én szövetségemet én közöttem és te közötted: és felette igen megsokasítlak téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'És arczára borúla Ábrám; az Isten pedig szóla őnéki, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, 'A mi engem illet, imhol az én szövetségem te veled, hogy népek sokaságának atyjává leszesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'És ne neveztessék ezután a te neved Ábrámnak, hanem legyen a te neved Ábrahám, mert népek sokaságának atyjává teszlek téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'És felette igen megsokasítalak téged; és népekké teszlek, és királyok is származnak tőled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'És megállapítom az én szövetségemet én közöttem és te közötted, és te utánad a te magod között annak nemzedékei szerint örök szövetségűl, hogy legyek tenéked Istened, és a te magodnak te utánad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'És adom tenéked és a te magodnak te utánnad a te bujdosásod földét, Kanaánnak egész földét, örök birtokul; és Istenök lészek nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Annakfelette monda Isten Ábrahámnak: Te pedig az én szövetségemet megőrizzed, te és a te magod te utánad az ő nemzedékei szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Ez pedig az én szövetségem, melyet meg kell tartanotok én közöttem és ti közöttetek, és a te utánnad való magod között: minden férfi körűlmetéltessék nálatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'És metéljétek körűl a ti férfitestetek bőrének elejét, és az lesz az én közöttem és ti közöttetek való szövetségnek jele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Nyolcznapos korában körűlmetéltessék nálatok minden férfigyermek nemzedékeiteknél; akár háznál született, akár pénzen vásároltatott valamely idegentől, a ki nem a te magodból való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Körűlmetéltetvén körűlmetéltessék a házadban született és a pénzeden vett; és örökkévaló szövetségűl lesz az én szövetségem a ti testeteken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'A körűlmetéletlen férfi pedig, a ki körűl nem metélteti az ő férfitestének bőrét, az ilyen lélek kivágattatik az ő népe közűl, mert felbontotta az én szövetségemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'És monda Isten Ábrahámnak: Szárainak, a te feleségednek nevét ne nevezd Szárainak, mert Sára az ő neve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'És megáldom őt, és fiat is adok ő tőle néked, és megáldom, hogy legyen népekké; nemzetek királyai származzanak ő tőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Ekkor arczára borúla Ábrahám, és nevete és gondolá az ő szívében: vajjon száz esztendős embernek lesz-é gyermeke? avagy Sára kilenczven esztendős lévén, szűlhet-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'És monda Ábrahám az Istennek: Vajha Ismáel élne te előtted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Az Isten pedig monda: Kétségnélkűl a te feleséged Sára szűl néked fiat, és nevezed annak nevét Izsáknak, és megerősítem az én szövetségemet ő vele örökkévaló szövetségűl az ő magvának ő utánna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Ismáel felől is meghallgattalak: Ímé megáldom őt, és megszaporítom őt és megsokasítom őt felette nagyon; tizenkét fejedelmet nemz, és nagy néppé teszem őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Az én szövetségemet pedig megerősítem Izsákkal, kit néked szűl Sára ez időkorban a következő esztendőben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'És elvégezé vele való beszédét, és felméne az Isten Ábrahámtól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Vevé azért Ábrahám Ismáelt az ő fiát, és háza minden szülöttét, és mind a pénzén vetteket, minden férfiat Ábrahám házanépe közűl és körűlmetélé férfitestöknek bőrét ugyanazon napon, a mikor szólott vala vele az Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Ábrahám pedig kilenczvenkilencz esztendős vala, mikor körűlmetélé az ő férfitestének bőrét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'Ismáel pedig az ő fia tizenhárom esztendős vala, mikor körűlmetélék az ő férfitestének bőrét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'Ugyanazon napon metéltetett körűl Ábrahám és Ismáel az ő fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'És házának minden férfi tagja, háza szülöttei és kik idegen embertől pénzen vásároltattak, vele együtt körűlmetéltetének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Megjelenék pedig ő néki az Úr a Mamré tölgyesében, és ő űl vala a sátor ajtajában, a hő napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'És felemelé az ő szemeit, és látá, hogy ímé három férfiú áll ő előtte. És látván, eléjök siete a sátor ajtajából, és földig meghajtá magát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'És monda: Jó Uram, ha kedves vagyok te előtted, kérlek, ne kerüld el a te szolgádat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Hadd hozzanak, kérlek, egy kevés vizet, és mossátok meg a ti lábaitokat, és dőljetek le a fa alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'Én pedig hozok egy falat kenyeret, hogy erősítsétek meg a ti szíveteket, azután menjetek tovább, mert azért tértetek be a ti szolgátokhoz. És mondának: Cselekedjél, a mint szólál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'És besiete Ábrahám a sátorba Sárához, és monda: Siess, gyúrj meg három mérték lisztlángot, és csinálj pogácsát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'A baromhoz is elfuta Ábrahám, és hoza egy gyenge kövér borjút, és adá a szolgának, az pedig siete azt elkészíteni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'És vőn vajat és tejet, és a borjút, melyet elkészített vala, és eléjök tevé: és ő mellettök áll vala a fa alatt, azok pedig evének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'És mondának néki: Hol van Sára a te feleséged? Ő pedig felele: Ímhol van a sátorban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'És monda: Esztendőre ilyenkor bizonynyal megtérek hozzád és ímé akkor a te feleségednek Sárának fia lesz. Sára pedig hallgatózik vala a sátor ajtajában, mely annak háta megett vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Ábrahám pedig és Sára élemedett korú öregek valának; megszünt vala Sáránál az asszonyi természet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Nevete azért Sára ő magában, mondván: Vénségemre lenne-é gyönyörűségem? meg az én uram is öreg!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'És monda az Úr Ábrahámnak: Miért nevetett Sára, ezt mondván: Vajjon csakugyan szűlhetek-é, holott én megvénhedtem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Avagy az Úrnak lehetetlen-é valami? Annak idején, esztendőre ilyenkor visszatérek hozzád, és fia lesz Sárának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Sára pedig megtagadá, mondván: Nem nevettem én; mivelhogy fél vala. De monda az Úr: Nem úgy van, mert bizony nevettél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Azután felkelvén onnan azok a férfiak, Sodoma felé tartanak vala. Ábrahám is velök méne, hogy elkisérje őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'És monda az Úr: Eltitkoljam-é én Ábrahámtól, a mit tenni akarok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'Holott Ábrahám nagy és hatalmas néppé lesz; és benne megáldatnak a földnek minden nemzetségei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Mert tudom róla, hogy megparancsolja az ő fiainak és az ő házanépének ő utánna, hogy megőrizzék az Úrnak útát, igazságot és törvényt tévén, hogy beteljesítse az Úr Ábrahámon, a mit szólott felőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Monda azután az Úr: Mivelhogy Sodomának és Gomorának kiáltása megsokasodott, és mivelhogy az ő bűnök felettébb megnehezedett:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Alámegyek azért és meglátom, vajjon teljességgel a hozzám felhatott kiáltás szerint cselekedtek-é vagy nem? tudni akarom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'És elfordulának onnan a férfiak, és menének Sodomába: Ábrahám pedig még az Úr előtt áll vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'És hozzá járula Ábrahám és monda: Avagy elveszted-é az igazat is a gonoszszal egybe?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Talán van ötven igaz abban a városban, avagy elveszted-é, és nem kedvezel-é a helynek az ötven igazért, a kik abban vannak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Távol legyen tőled, hogy ilyen dolgot cselekedjél, hogy megöld az igazat a gonoszszal, és úgy járjon az igaz mint a gonosz: Távol legyen tőled! Avagy az egész föld bírája nem szolgáltatna-é igazságot?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'És monda az Úr: Ha találok Sodomában a városon belől ötven igazat, mind az egész helynek megkegyelmezek azokért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'És felele Ábrahám, és monda: Immár merészkedtem szólani az én Uramnak, noha én por és hamu vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Ha az ötven igaznak talán öt híja lesz, elveszted-é az öt miatt az egész várost? És monda: Nem vesztem el, ha találok ott negyvenötöt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'És ismét szóla hozzá és monda: Hátha találtatnak ott negyvenen? És monda Ő: Nem teszem meg a negyvenért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Mégis monda: Kérlek, ne haragudjék meg az én Uram ha szólok: Hátha találtatnak ott harminczan? És Ő felele: Nem teszem meg, ha találok ott harminczat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'És ő monda: Immár merészkedtem szólani az én Uramnak: Hátha találtatnak ott húszan? Felele: Nem vesztem el a húszért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'És monda: Ne haragudjék kérlek az én Uram ha szólok még ez egyszer: Hátha találtatnak ott tízen? És Ő monda: Nem vesztem el a tízért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'És elméne az Úr, minekutánna elvégezte Ábrahámmal való beszélgetését; Ábrahám pedig megtére az ő helyére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Mikor a két angyal estére Sodomába jutott, Lót Sodoma kapujában űl vala, és a mint meglátá őket Lót, felkele eléjök, és arczczal a földre borúla.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'És monda: Ímé én Uraim kérlek, térjetek be a ti szolgátok házához, és háljatok ott, és mossátok meg lábaitokat; reggel korán felkelhettek és indulhattok útatokra. Azok pedig mondának: Nem, hanem az utczán hálunk meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'De nagyon unszolá őket, és betérének hozzá, és bemenének az ő házába; ő pedig szerze nékik vendégséget, és pogácsát is süte, és evének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Lefekvésök előtt a város férfiai, Sodoma férfiai körűlvevék a házat, ifja, örege, mind az egész község egytől egyig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'És szólíták Lótot, mondván néki: Hol vannak a férfiak, a kik te hozzád jövének az éjjel? Hozd ki azokat mi hozzánk, hadd ismerjük őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'És kiméne Lót ő hozzájok az ajtó eleibe, és bezárá maga után az ajtót.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'És monda: Kérlek atyámfiai, ne cselekedjetek gonoszságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Ímé van énnékem két leányom, a kik még nem ismertek férfiat, kihozom azokat ti hozzátok, és cselekedjetek velök a mint néktek tetszik, csakhogy ezekkel az emberekkel ne csináljatok semmit, mivelhogy az én hajlékom árnyéka alá jöttenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Azok pedig mondának: Eredj el innen. Ismét mondának: Ez egy maga nálunk a jövevény s ő szabja a törvényt? Majd gonoszbul cselekszünk veled, hogy nem azokkal. És reá rohanának a férfiúra, Lótra, felette igen, és azon valának, hogy betörik az ajtót.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'De kinyújták azok a férfiak kezeiket, és bevonák Lótot magokhoz a házba és bezárák az ajtót.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'Az embereket pedig, kik a ház ajtaja előtt valának, vaksággal verék meg kicsinytől nagyig, annyira, hogy elfáradának az ajtó keresésében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'És mondának a férfiak Lótnak: Ki van még itt hozzád tartozó? vődet, fiaidat és leányaidat, és mindenedet, a mi a tied a városban, vidd ki e helyből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'Mert mi elvesztjük e helyet, mivelhogy ezek kiáltása nagyra nőtt az Úr előtt; és az Úr küldött minket, hogy elveszítsük ezt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Kiméne azért Lót, és szóla az ő vőinek, kik az ő leányait elvették vala, és monda: Keljetek fel, menjetek ki e helyből, mert elveszti az Úr e várost; de az ő vőinek úgy tetszék, mintha tréfálna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'És mikor a hajnal feljött, sürgetik vala az Angyalok Lótot, mondván: Kelj fel, vedd a te feleségedet és jelenlevő két leányodat, hogy el ne veszsz a városnak bűne miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Mikor pedig késedelmeskedék, megragadák a férfiak az ő kezét és az ő feleségének kezét és két leánya kezét, az Úrnak iránta való irgalmából, és kivivék őt: és ott hagyák a városon kívül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'És lőn mikor kivivék őket, monda az egyik: Mentsd meg a te életedet, hátra ne tekints, és meg ne állj a környéken; a hegyre menekülj, hogy el ne veszsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'És monda Lót nékik: Ne oh Uram!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Ímé a te szolgád kegyelmet talált te előtted, és nagy a te irgalmasságod, melyet mutattál irántam, hogy életemet megtartotta: de én nem menekűlhetek a hegyre, nehogy utólérjen a veszedelem, és meghaljak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Ímhol az a város közel van, hogy oda fussak, kicsiny is, hadd menekűljek kérlek oda, lám kicsiny az; és én életben maradok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Monda azért néki: Ím tekintek rád e dologban is, és nem pusztítom el a várost, a melyről szólottál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Siess, menekülj oda, mert semmit sem tehetek addig, míg oda nem érsz. Azért nevezték annak a városnak nevét Czóárnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'A nap feljött vala a földre, mikor Lót Czóárba ére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'És bocsáta az Úr Sodomára és Gomorára kénköves és tüzes esőt az Úrtól az égből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'És elsűlyeszté ama városokat, és azt az egész vidéket, és a városok minden lakosait, és a föld növényeit is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'És hátra tekinte az ő felesége, és sóbálványnyá lőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Ábrahám pedig reggel arra a helyre indúla, a hol az Úr színe előtt állott vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'És tekinte Sodoma és Gomora felé, és az egész környék földje felé; és látá, és ímé felszálla a földnek füstje, mint a kemencze füstje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'És lőn mikor elveszté Isten annak a környéknek városait, megemlékezék az Isten Ábrahámról, és kiküldé Lótot a veszedelemből, mikor elsűlyeszté a városokat, a melyekben lakott vala Lót.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Lót pedig felméne Czóárból, és letelepedék a hegyen, és vele együtt az ő két leánya is, mert fél vala Czóárban lakni; lakozék tehát egy barlangban ő és az ő két leánya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'És monda a nagyobbik a kisebbiknek: A mi atyánk megvénhedett, és nincsen a földön férfiú, a ki mi hozzánk bejöhetne az egész föld szokása szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Jer, adjunk bort inni a mi atyánknak, és háljunk ő vele, és támaszszunk magot a mi atyánktól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Adának azért inni bort az ő atyjoknak azon éjszaka, és beméne a nagyobbik, és hála az ő atyjával, ez pedig semmit sem tuda annak sem lefekvéséről, sem fölkeléséről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'És lőn másodnapon, monda a nagyobbik a kisebbiknek: Ímé a mult éjjel én háltam atyámmal, adjunk néki bort inni ez éjjel is, és menj be te, hálj vele, és támaszszunk magot a mi atyánktól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Adának azért azon éjszaka is az ő atyjoknak bort inni, és felkele a kisebbik is és vele hála; ő pedig semmit sem tuda annak sem lefekvéséről, sem fölkeléséről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'És teherbe esének Lót leányai mindketten az ő atyjoktól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'És szűle a nagyobbik fiat, és nevezé annak nevét Moábnak; ez a Moábiták atyja mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'A kisebbik is fiat szűle és nevezé annak nevét Benamminak. Ez az Ammoniták atyja mind a mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'És elköltözék onnan Ábrahám a déli tartományba, és letelepedék Kádes és Súr között, és tartózkodék Gérárban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'És monda Ábrahám Sáráról az ő feleségéről: Én húgom ő. Elkülde azért Abimélek Gérárnak királya, és elviteté Sárát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'De Isten Abimélekhez jöve éjjeli álomban, és monda néki: Ímé meghalsz az asszonyért, a kit elvettél, holott férjnél van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Abimélek pedig nem illette vala őt, és monda: Uram, az ártatlan népet is megölöd-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Avagy nem ő mondotta-é nékem: én húgom ő; s ez is azt mondotta: én bátyám ő. Szívem ártatlanságában, és kezeim tisztaságában cselekedtem ezt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'És monda az Isten néki álomban: Én is tudom, hogy szívednek ártatlanságában mívelted ezt, azért tartóztattalak én is, hogy ne vétkezzél ellenem, azért nem engedtem, hogy illessed azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Mostan azért add vissza az embernek az ő feleségét, mert Próféta ő: és imádkozik te éretted, és élsz; hogyha pedig vissza nem adod: tudd meg, hogy halállal halsz meg te, és minden hozzád tartozó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Felkele azért Abimélek reggel, és előhívatá minden szolgáját, s fülök hallatára mindezeket elbeszélé és az emberek igen megfélemlének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'És hívatá Abimélek Ábrahámot, és monda néki: Mit cselekedtél mi velünk? És mit vétettem te ellened, hogy én reám és az én országomra ilyen nagy bűnt hoztál? A miket cselekedni nem szabad, olyan dolgokat cselekedtél ellenem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'És monda Abimélek Ábrahámnak: Mit láttál, hogy ezt a dolgot cselekedted?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Felele Ábrahám: Bizony azt gondoltam: nincsen istenfélelem e helyen, és megölnek engem az én feleségemért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'De valósággal húgom is, az én atyámnak leánya ő, csakhogy nem az én anyámnak leánya; és így lőn feleségemmé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'És lőn hogy a mikor kibujdostata engem az Isten az én atyámnak házából, azt mondám néki: Ilyen kegyességet cselekedjél én velem, mindenütt valahová megyünk, azt mondjad én felőlem: én bátyám ez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Akkor Abimélek vett juhokat, ökröket, szolgákat és szolgálókat, és adá Ábrahámnak, és vissza adá néki Sárát is az ő feleségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'És monda Abimélek: Ímé előtted van az én országom, a hol tenéked jónak tetszik, ott lakjál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Sárának pedig monda: Ímé ezer ezüst pénzt adtam a te bátyádnak, ímé az neked a szemek befedezője mindazok előtt, a kik veled vannak; és így mindenképen igazolva vagy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Könyörge azért Ábrahám az Istennek, és meggyógyítá Isten Abiméleket, és az ő feleségét, és az ő szolgálóit, és szűlének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Mert az Úr erősen bezárta vala az Abimélek háza népének méhét, Sáráért az Ábrahám feleségéért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Az Úr pedig meglátogatá Sárát, a mint mondotta vala, és akképen cselekedék az Úr Sárával, a miképen szólott vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Mert fogada Sára az ő méhében, és szűle fiat Ábrahámnak az ő vénségében, abban az időben, melyet mondott vala néki az Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'És nevezé Ábrahám az ő fiának nevét, a ki néki született vala, a kit szűlt vala néki Sára, Izsáknak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'És körűlmetélé Ábrahám az ő fiát Izsákot, nyolcznapos korában, a mint parancsolta vala néki az Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Ábrahám pedig száz esztendős vala, mikor születék néki az ő fia Izsák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'És monda Sára: Nevetést szerzett az Isten, énnékem; a ki csak hallja, nevet rajtam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Ismét monda: Ki mondotta volna Ábrahámnak, hogy Sára fiakat szoptat? s ímé fiat szűltem vénségére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'És felnevekedék a gyermek, és elválasztaték; Ábrahám pedig nagy vendégséget szerze azon a napon, a melyen Izsák elválasztaték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Mikor pedig Sára nevetgélni látá az Égyiptombéli Hágárnak fiát, kit Ábrahámnak szűlt vala,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'Monda Ábrahámnak: Kergesd el ezt a szolgálót az ő fiával egybe, mert nem lesz örökös e szolgáló fia az én fiammal, Izsákkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Ábrahámnak pedig igen nehéznek látszék e dolog, az ő fiáért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'De monda az Isten Ábrahámnak: Ne lássék előtted nehéznek a gyermeknek és a szolgálónak dolga; valamit mond néked Sára, engedj az ő szavának, mert Izsákról neveztetik a te magod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Mindazáltal a szolgálóleány fiát is néppé teszem, mivelhogy a te magod ő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Felkele azért Ábrahám jó reggel, és vőn kenyeret és egy tömlő vizet, és adá Hágárnak, és feltevé azt és a gyermeket annak vállára s elbocsátá. Az pedig elméne, és bujdosék a Beérseba pusztájában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Hogy elfogyott a víz a tömlőből, letevé a gyermeket egy bokor alá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'És elméne s leűle által ellenébe mintegy nyillövésnyi távolságra; mert azt mondja vala: Ne lássam mikor a gyermek meghal. Leűle tehát által ellenébe, és fölemelé szavát és síra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Meghallá pedig Isten a gyermeknek szavát, és kiálta az Isten angyala az égből Hágárnak, és monda néki: Mi lelt téged Hágár? ne félj, mert az Isten meghallotta a gyermeknek szavát, ott a hol van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Kelj fel, vedd fel a gyermeket, és viseld gondját, mert nagy néppé teszem őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'És megnyitá Isten az ő szemeit, és láta egy vízforrást, oda méne azért, és megtölté a tömlőt vízzel, és inni ada a gyermeknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'És vala Isten a gyermekkel, s az felnövekedék, és lakik vala a pusztában, és lőn íjászszá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Lakozék pedig Párán pusztájában, és vőn néki anyja feleséget Égyiptom földéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'És lőn abban az időben, hogy Abimélek és Pikhól annak hadvezére megszólíták Ábrahámot mondván: Az Isten van te veled mindenben, a mit cselekszel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Mostan azért esküdj meg énnékem az Istenre itt, hogy sem én ellenem, sem fiam, sem unokám ellen álnokságot nem cselekszel, hanem azzal a szeretettel, a melylyel én te irántad viseltettem, viseltetel te is én irántam és az ország iránt, a melyben jövevény voltál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'És monda Ábrahám: Én megesküszöm.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Megdorgálá pedig Ábrahám Abiméleket a kútért, melyet erővel elvettek vala az Abimélek szolgái.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'És monda Abimélek: Nem tudom kicsoda mívelte e dolgot; te sem jelentetted nekem, s én sem hallottam, hanem csak ma.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Vett azért Ábrahám juhokat, barmokat és adá Abiméleknek; és egymással szövetséget kötének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'És külön állíta Ábrahám a nyájból hét juhot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'És monda Abimélek Ábrahámnak: Mire való e hét juh, melyet külön állítál?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'És felele Ábrahám: Ezt a hét juhot vedd tőlem, hogy bizonyságul legyenek nékem, hogy én ástam ezt a kútat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Azért nevezék azt a helyet Beérsebának, mivelhogy ott esküdtek vala meg mind a ketten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'Megköték tehát a szövetséget Beérsebában, és felkele Abimélek és Pikhól annak hadvezére és visszatérének a Filiszteusok földére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Ábrahám pedig tamariskusfákat ültete Beérsebában, és segítségűl hívá ott az örökkévaló Úr Istennek nevét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'És sok ideig tartózkodék Ábrahám a Filiszteusok földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'És lőn ezeknek utána, az Isten megkisérté Ábrahámot, és monda néki: Ábrahám! S az felele: Ímhol vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'És monda: Vedd a te fiadat, ama te egyetlenegyedet, a kit szeretsz, Izsákot, és menj el Mórijának földére, és áldozd meg ott égő áldozatul a hegyek közűl egyen, a melyet mondándok néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Felkele azért Ábrahám jó reggel, és megnyergelé az ő szamarát, és maga mellé vevé két szolgáját, és az ő fiát Izsákot, és fát hasogatott az égő áldozathoz. Akkor felkele és elindula a helyre, melyet néki az Isten mondott vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Harmadnapon felemelé az ő szemeit Ábrahám, és látá a helyet messziről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'És monda Ábrahám az ő szolgáinak: Maradjatok itt a szamárral, én pedig és ez a gyermek elmegyünk amoda és imádkozunk, azután visszatérünk hozzátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Vevé azért Ábrahám az égő áldozathoz való fákat, és feltevé az ő fiára Izsákra, ő maga pedig kezébe vevé a tüzet, és a kést, és mennek vala ketten együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'És szóla Izsák Ábrahámhoz az ő atyjához, és monda: Atyám! Az pedig monda: Ímhol vagyok, fiam. És monda Izsák: Ímhol van a tűz és a fa; de hol van az égő áldozatra való bárány?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'És monda Ábrahám: Az Isten majd gondoskodik az égő áldozatra való bárányról, fiam; és mennek vala ketten együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Hogy pedig eljutának arra a helyre, melyet Isten néki mondott vala, megépíté ott Ábrahám az oltárt, és reá raká a fát, és megkötözé Izsákot az ő fiát, és feltevé az oltárra, a fa-rakás tetejére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'És kinyújtá Ábrahám az ő kezét és vevé a kést, hogy levágja az ő fiát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Akkor kiálta néki az Úrnak Angyala az égből, és monda: Ábrahám! Ábrahám! Ő pedig felele: Ímhol vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'És monda: Ne nyujtsd ki a te kezedet a gyermekre, és ne bántsd őt: mert most már tudom, hogy istenfélő vagy, és nem kedvezél a te fiadnak, a te egyetlenegyednek én érettem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'És felemelé Ábrahám az ő szemeit, és látá hogy ímé háta megett egy kos akadt meg szarvánál fogva a szövevényben. Oda méne tehát Ábrahám, és elhozá a kost, és azt áldozá meg égő áldozatul az ő fia helyett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'És nevezé Ábrahám annak a helynek nevét Jehova-jire-nek. Azért mondják ma is: Az Úr hegyén a gondviselés.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'És kiálta az Úrnak Angyala Ábrahámnak másodszor is az égből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'És monda: Én magamra esküszöm azt mondja az Úr: mivelhogy e dolgot cselekedéd, és nem kedvezél a te fiadnak, a te egyetlenegyednek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'Hogy megáldván megáldalak tégedet, és bőségesen megsokasítom a te magodat mint az ég csillagait, és mint a fövényt, mely a tenger partján van, és a te magod örökség szerint fogja bírni az ő ellenségeinek kapuját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'És megáldatnak a te magodban a földnek minden nemzetségei, mivelhogy engedtél az én beszédemnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Megtére azért Ábrahám az ő szolgáihoz, és felkelének és együtt elmenének Beérsebába, mert lakozék Ábrahám Beérsebában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'És lőn ezeknek utánna, hírt hozának Ábrahámnak mondván: Ímé Milkha is szűlt fiakat Nákhornak, a te atyádfiának:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'Úzt az ő elsőszülöttét, és Búzt annak testvérét, és Kemuélt Arámnak atyját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'És Keszedet, Házót, Pildást, Jidláfot és Bethuélt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Bethuél pedig nemzé Rebekát. Ezt a nyolczat szűlé Milkha Nákhornak az Ábrahám atyjafiának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Az ő ágyasa is, kinek neve Reuma vala, szűlé néki Tebáhot, Gakhámot, Thakhást és Mahákhát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Vala pedig Sárának élete száz huszonhét esztendő. Ezek Sára életének esztendei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'És meghala Sára Kirját-Arbában azaz Hebronban a Kanaán földén, és beméne Ábrahám, hogy gyászolja Sárát és sirassa őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Felkele azután Ábrahám az ő halottja elől, és szóla a Khéth fiainak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'Idegen és jövevény vagyok közöttetek: Adjatok nékem temetésre való örökséget ti nálatok, hadd temessem el az én halottamat én előlem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Felelének pedig a Khéth fiai Ábrahámnak, mondván őnéki:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Hallgass meg minket uram: Istentől való fejedelem vagy te mi közöttünk, a mi temetőhelyeink közűl a mely legtisztességesebb, abba temesd el a te halottadat, közűlünk senki sem tiltja meg tőled az ő temetőhelyét, hogy eltemethesd a te halottadat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'És felkele Ábrahám, és meghajtá magát a földnek népe előtt, a Khéth fiai előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'És szóla ő velök mondván: Ha azt akarjátok, hogy eltemessem az én halottamat én előlem: hallgassatok meg engemet, és esedezzetek én érettem Efron előtt, Czohár fia előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'Hogy adja nékem Makpelá barlangját, mely az övé, mely az ő mezejének szélében van: igaz árán adja nékem azt, ti köztetek temetésre való örökségűl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Efron pedig űl vala a Khéth fiai között. Felele azért Efron a Khitteus, Ábrahámnak, a Khéth fiainak és mindazoknak hallatára, a kik bemennek vala az ő városának kapuján, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'Nem úgy uram, hallgass meg engem: azt a mezőt néked adom, s a barlangot, mely abban van, azt is néked adom, népem fiainak szeme láttára adom azt néked, temesd el halottadat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'És meghajtá magát Ábrahám a földnek népe előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'És szóla Efronhoz a föld népének hallatára, mondván: Ha mégis meghallgatnál engem! megadom a mezőnek árát, fogadd el tőlem; azután eltemetem ott az én halottamat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'És felele Efron Ábrahámnak, mondván néki:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Uram! hallgass meg engemet; négyszáz ezüst siklusos föld, micsoda az én köztem és te közötted? Csak temesd el a te halottadat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Engede azért Ábrahám Efronnak és odamérte Ábrahám Efronnak az ezüstöt, a melyet mondott vala a Khéth fiainak hallatára; kalmároknál kelendő négyszáz ezüst siklust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'Így lett Efronnak Makpelában levő mezeje, mely Mamré átellenében van, a mező a benne levő barlanggal, és minden a mezőben levő fa az egész határban köröskörűl');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'Ábrahámnak birtoka, a Khéth fiainak, mind azoknak szeme előtt, a kik az ő városának kapuján bemennek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Azután eltemeté Ábrahám az ő feleségét Sárát a Makpelá mezejének barlangjába Mamréval szemben. Ez Hebron a Kanaán földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Így erősítteték meg a mező és a benne lévő barlang Ábrahámnak temetésre való örökségűl a Khéth fiaitól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Ábrahám pedig vén élemedett ember vala, és az Úr mindenben megáldotta vala Ábrahámot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Monda azért Ábrahám az ő háza öregebb szolgájának, a ki őnéki mindenében gazda vala: Tedd a kezed tomporom alá!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'Hogy megeskesselek téged az Úrra, a mennynek Istenére, és a földnek Istenére, hogy nem vészesz feleséget az én fiamnak a Kananeusok leányai közűl, a kik között lakom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'Hanem elmégysz az én hazámba, és az én rokonságim közé és onnan vészesz feleséget az én fiamnak Izsáknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Monda pedig őnéki a szolga: Hátha az a leányzó nem akar velem eljőni e földre, ugyan vissza vigyem-é a te fiadat arra a földre, a honnan kijöttél vala?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Felele néki Ábrahám: Vigyázz, az én fiamat oda vissza ne vidd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Az Úr az égnek Istene, ki engemet kihozott az én atyámnak házából, és az én rokonságimnak földéről, a ki szólt nékem, és megesküdött nékem mondván: A te magodnak adom ezt a földet; elbocsátja az ő Angyalát te előtted, hogy onnan végy az én fiamnak feleséget.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Hogyha pedig nem akar a leányzó teveled eljőni, ment lészesz az én esketésem alól; csakhogy az én fiamat oda vissza ne vidd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Veté azért a szolga az ő kezét az ő urának Ábrahámnak tompora alá, és megesküvék néki e dolog felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'És vőn a szolga tíz tevét az ő urának tevéi közűl, és elindula; (mert az urának minden gazdagsága az ő kezében vala). Felkele tehát és elméne Mésopotámiába, a Nákhor városába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'És megpihenteté a tevéket a városon kivűl egy kútfőnél, este felé, mikor a leányok vizet meríteni járnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'És monda: Uram! én uramnak Ábrahámnak Istene, hozd elém még ma, és légy kegyelmes az én uram Ábrahám iránt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Ímé én a víz forrása mellé állok és e város lakosainak leányai kijőnek vizet meríteni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Legyen azért, hogy a mely leánynak ezt mondom: Hajtsd meg a te vedredet, hogy igyam, és az azt mondándja: igyál, sőt a te tevéidet is megitatom: hogy azt rendelted légyen a te szolgádnak Izsáknak, és erről ismerjem meg, hogy irgalmasságot cselekedtél az én urammal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'És lőn, minekelőtte elvégezte volna a beszédet, ímé jő vala Rebeka, Bethuélnek leánya, a ki Milkhának, az Ábrahám testvérének Nákhor feleségének vala fia, és pedig vedrével a vállán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'A leányzó pedig felette szép ábrázatú vala; szűz, és férfi még nem ismeré őt, és aláméne a forrásra, és megtölté vedrét, és feljöve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Akkor a szolga eleibe futamodék és monda: Kérlek, adj innom nékem egy kevés vizet a te vedredből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Az pedig monda: Igyál uram! és sietve leereszté a vedret az ő kezére, és inni ada néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'És minekutána eleget adott néki innia, monda: A te tevéidnek is merítek, míg eleget nem isznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'És sietett és kiüríté vedrét a válúba és ismét elfuta a forrásra meríteni, és meríte mind az ő tevéinek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Az ember pedig álmélkodva néz vala reá, és veszteg hallgat vala, tudni akarván: vajjon szerencséssé teszi-é az Úr az ő útját, vagy nem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'És lőn, mikor a tevék már eleget ittak, elévőn az ember egy aranyfüggőt, a melynek súlya fél siklus, és két karpereczet, a melynek súlya tíz arany.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'És monda: Kinek a leánya vagy te? kérlek mondd meg nékem: van-é a te atyádnak házában hálásra való helyünk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Az pedig felele néki: Bethuél leánya vagyok a Milkha fiáé, a kit ő Nákhornak szűlt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Azt is mondá: Szalma is, abrak is bőven van minálunk, és hálásra való hely is van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Meghajtá azért magát az ember, és imádá az Urat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'És monda: Áldott az Úr az én uramnak Ábrahámnak Istene, ki nem vonta meg az ő irgalmasságát és hűségét az én uramtól. Az Úr vezérlett engem ez útamban az én uram atyjafiainak házához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Elfuta azonközben a leányzó, és elbeszélé az ő anyja házában, a mint ezek történtek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Vala pedig Rebekának egy bátyja, kinek neve Lábán vala. És kifutamodék Lábán ahhoz az emberhez a forráshoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Mert mikor látta a függőt, és a pereczeket az ő húgának karjain, és hallotta húgának Rebekának beszédét, a ki ezt mondja vala: Így szóla nékem az a férfiú; akkor méne ki a férfiúhoz; és ímé ez ott áll vala a tevék mellett a forrásnál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'És monda: Jőjj be Istennek áldott embere; mit állasz ide kinn? holott én elkészítettem a házat, és a tevéknek is van hely.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Beméne azért a férfiú a házhoz, ő pedig lenyergelé a tevéket, és ada a tevéknek szalmát és abrakot; és vizet az ő lábai megmosására és az emberek lábainak, kik ő vele valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'És enni valót tevének eleibe, de ő monda: Nem eszem, míg el nem mondom az én beszédemet. És szóla: Mondd el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Monda azért: Én az Ábrahám szolgája vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Az Úr pedig igen megáldotta az én uramat, úgy hogy nagygyá lett: mert adott néki juhokat, barmokat, ezüstöt, aranyat, szolgákat, szolgálóleányokat, tevéket, szamarakat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'És Sára az én uramnak felesége fiat szűlt az én uramnak, az ő vénségében, és annak adá mindenét, a mije van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Engem pedig megesküdtetett az én uram, mondván: Ne végy feleséget az én fiamnak a Kananeusok leányai közűl, a kiknek földjén én lakom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'Hanem menj el az én atyámnak házához, és az én rokonságom közé, hogy onnan végy feleséget az én fiamnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Mikor pedig azt mondám az én uramnak: Hátha nem akarna velem az a leányzó eljőni?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Monda nékem: Az Úr, a kinek én színe előtt jártam, elbocsátja az ő angyalát teveled, és szerencséssé teszi a te útadat, hogy feleséget vehess az én fiamnak az én nemzetségem közűl, és az én atyám házából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Csak akkor leszesz fölmentve esketésem alól, ha elmenéndesz az én nemzetségem közé; és ha nem adják oda: ment leszesz az én esketésem alól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Mikor ma a forráshoz érkezém, mondék: Uram, én uramnak, Ábrahámnak Istene, vajha szerencséssé tennéd az én útamat, melyen járok:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'Ímé én e forrás mellett állok; és legyen, hogy az a hajadon, a ki kijön vizet meríteni, s a kinek azt mondom: Adj innom nékem egy kevés vizet a te vedredből,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'És az ezt mondja nékem: Te is igyál, és a te tevéidnek is merítek; az legyen a feleség, a kit az Úr az én uram fiának rendelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Én még el sem végeztem vala az én szívemben a beszédet, és ímé kijő vala Rebeka, vedrével a vállán, és leméne a forrásra és meríte, én pedig mondék néki: Adj innom kérlek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Ő pedig sietett és leereszté az ő vedrét és monda: Igyál, sőt a te tevéidnek is inni adok; és én ivám, s a tevéknek is inni ada.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'És megkérdezém őt és mondék: Ki leánya vagy? ő pedig felele: Bethuélnek, a Nákhor fiának leánya vagyok, a kit Milkha szűlt vala őnéki. Ekkor a függőt orrába, és e pereczeket karjaira tevém.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'Meghajtván azért magamat, imádám az Urat, és áldám az Urat, az én uramnak Ábrahámnak Istenét, ki engem igaz úton vezérelt, hogy az én uram atyjafiának leányát vegyem az ő fiának feleségűl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Most azért, ha szeretettel és hűséggel akartok lenni az én uramhoz, mondjátok meg; ha pedig nem, adjátok tudtomra, hogy én vagy jobbra vagy balra forduljak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'És felele Lábán és Bethuél, és mondának: Az Úrtól van e dolog: Nem mondhatunk neked sem jót, sem rosszat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Ímé előtted van Rebeka, vegyed, menj el; és legyen felesége a te urad fiának, a mint az Úr elvégezte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'És lőn, a mint hallja vala az Ábrahám szolgája azoknak beszédét, meghajtá magát a földig az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'És hoza elő a szolga ezüst edényeket és arany edényeket és ruhákat, és adá azokat Rebekának: drága ajándékokat ada az ő bátyjának is és az ő anyjának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Evének azután és ivának, ő és a férfiak, a kik ő vele valának, és ott hálának. Mikor pedig felkelének reggel, monda: Bocsássatok el engem az én uramhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Monda pedig a leány bátyja és anyja: Maradjon velünk a leány még vagy tíz napig, azután menjen el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'A szolga pedig monda nékik: Ne késleljetek meg engem, holott az Úr szerencséssé tette az én útamat; bocsássatok el azért engem, hogy menjek az én uramhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Mondának akkor: Hívjuk elő a leányt, és kérdjük meg őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Szólíták azért Rebekát, és mondának néki: Akarsz-é elmenni e férfiúval? és monda: Elmegyek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Elbocsáták azért Rebekát, az ő húgokat, és az ő dajkáját, és az Ábrahám szolgáját, és az ő embereit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'És megáldák Rebekát, és mondák néki: Te mi húgunk! szaporodjál ezerszer való ezerig. És bírja a te magod az ő ellenségeinek kapuját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'És felkele Rebeka és az ő szolgálóleányai, és felűlének a tevékre, s követék azt a férfiút. Így vevé a szolga Rebekát, és elméne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Izsák pedig visszajő vala a Lakhai Rói forrástól; és lakik vala a déli tartományban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'És kiméne Izsák este felé elmélkedni a mezőre, és felemelé szemeit és látá, hogy ímé tevék jőnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Rebeka is felemelé szemeit s meglátá Izsákot, és leszálla a tevéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'És monda a szolgának: Kicsoda az a férfiú, a ki a mezőn előnkbe jő? A szolga pedig monda: Az én uram ő. Akkor fogta a fátyolt és elfedezé magát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Elbeszélé azután a szolga Izsáknak mindazokat a dolgokat, a melyeket cselekedett vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Izsák pedig bevivé Rebekát Sárának az ő anyjának sátorába. És elvevé Rebekát és lőn néki felesége és szereté őt. S megvigasztalódék Izsák az ő anyja halála után.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Ábrahám pedig ismét vőn magának feleséget, kinek neve Ketúráh vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'És az szűlé néki Zimránt, Joksánt, Médánt, Midiánt, Isbákot és Suakhot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Joksán pedig nemzé Sébát, és Dédánt. Dédánnak pedig fiai valának: Assurim, Letúsim és Leummim.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'S Midiánnak fiai: Éfah, Éfer, Hánok, Abida és Eldaah: Mind ezek Ketúráhnak fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Valamije pedig Ábrahámnak vala, mindazt Izsáknak adta vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'Az ágyasok fiainak pedig, a kik Ábraháméi valának, ada Ábrahám ajándékokat, és elküldé azokat az ő fia mellől, Izsák mellől még éltében napkelet felé, napkeleti tartományba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'S ezek Ábrahám élete esztendeinek napjai, melyeket élt: száz hetvenöt esztendő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'És kimúlék és meghala Ábrahám, jó vénségben, öregen és betelve az élettel, és takaríttaték az ő népéhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'És eltemeték őt Izsák és Ismáel az ő fiai a Makpelá barlangjában, Efronnak, a Khitteus Czohár fiának mezejében, mely Mamré átellenében van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'Abban a mezőben, melyet Ábrahám a Khéth fiaitól vett vala: ott temettetett el Ábrahám és az ő felesége Sára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Lőn pedig Ábrahám halála után, megáldá Isten az ő fiát Izsákot; Izsák pedig lakozék a Lakhai Rói forrásánál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Ezek pedig Ábrahám fiának Ismáelnek nemzetségei, a kit az Égyiptombeli Hágár a Sára szolgálója szűlt vala Ábrahámnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'Ezek az Ismáel fiainak nevei, nevök s nemzetségök szerint: Ismáelnek elsőszülötte Nebájót, azután Kédar, Adbeél és Mibszám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'És Misma, Dúmah és Massza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Hadar, Théma, Jetúr, Náfis és Kedmah.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Ezek az Ismáel fiai, és ezek azoknak nevei udvaraikban, falvaikban; tizenkét fejedelem az ő nemzetségök szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Ezek pedig az Ismáel életének esztendei: száz harminczkét esztendő. És kimúlék és meghala, és takaríttaték az ő népéhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Lakoztak pedig Havilától fogva Súrig, a mely Égyiptom átellenében van, a merre Assiriába mennek. Minden atyjafiával szemben esett az ő lakása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Ezek pedig Izsáknak az Ábrahám fiának nemzetségei: Ábrahám nemzé Izsákot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Izsák pedig negyven esztendős vala, a mikor feleségűl vette Rebekát a Siriából való Bethuélnek leányát, Mésopotámiából, a Siriából való Lábánnak húgát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'És könyörge Izsák az Úrnak az ő feleségéért, mivelhogy magtalan vala, és az Úr meghallgatá őt: és teherbe esék Rebeka, az ő felesége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Tusakodnak vala pedig a fiak az ő méhében. Akkor monda: Ha így van, miért vagyok én így? Elméne azért, hogy megkérdezze az Urat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'És monda az Úr őnéki: Két nemzetség van a te méhedben; és két nép válik ki a te belsődből, egyik nép a másik népnél erősebb lesz, és a nagyobbik szolgál a kisebbiknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'És betelének az ő szülésének napjai, és ímé kettősök valának az ő méhében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'És kijöve az első; vereses vala, mindenestől szőrös, mint egy lazsnak; azért nevezék nevét Ézsaúnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Azután kijöve az ő atyjafia, kezével Ézsaú sarkába fogódzva; azért nevezék nevét Jákóbnak. Izsák pedig hatvan esztendős vala, a mikor ezek születének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'És felnevekedének a gyermekek, és Ézsaú vadászathoz értő mezei ember vala; Jákób pedig szelíd ember, sátorban lakozó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Szereti vala azért Izsák Ézsaút, mert szájaíze szerint vala a vad; Rebeka pedig szereti vala Jákóbot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Jákób egyszer valami főzeléket főze, és Ézsaú megjövén elfáradva a mezőről,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Monda Ézsaú Jákóbnak: Engedd, hogy ehessem a veres ételből, mert fáradt vagyok. Ezért nevezék nevét Edomnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Jákób pedig monda: Add el hát nékem azonnal a te elsőszülöttségedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'És monda Ézsaú; Ímé én halni járok, mire való hát nékem az én elsőszülöttségem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'És monda Jákób: Esküdjél meg hát nékem azonnal, és megesküvék néki és eladá az ő elsőszülöttségét Jákóbnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'S akkor Jákób ada Ézsaúnak kenyeret, és főtt lencsét, és evék és ivék, és felkele és elméne. Így veté meg Ézsaú az elsőszülöttséget.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Lőn pedig éhség az országban, amaz első éhség után, mely Ábrahám idejében vala. Elméne azért Izsák Abimélekhez a Filiszteusok királyához Gérárba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Mert megjelent vala néki az Úr és ezt mondotta vala: Ne menj alá Égyiptomba! lakjál azon a földön, melyet mondándok tenéked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Tartózkodjál ezen a földön, és én veled leszek és megáldalak téged; mert tenéked és a te magodnak adom mind ezeket a földeket, hogy megerősítsem az esküvést, melylyel megesküdtem Ábrahámnak a te atyádnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'És megsokasítom a te magodat mint az ég csillagait, és a te magodnak adom mind ezeket a földeket: és megáldatnak a te magodban a földnek minden nemzetségei;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'Mivelhogy hallgata Ábrahám az én szavamra: és megtartotta a megtartandókat, parancsolataimat, rendeléseimet és törvényeimet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Lakozék azért Izsák Gérárban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'És mikor annak a helynek lakosai az ő felesége felől kérdezősködének, azt mondja vala: én húgom ő. Mert fél vala azt mondani: én feleségem; gondolván: nehogy megöljenek engem e helynek lakosai Rebekáért, mivelhogy szép ábrázatú ő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'És lőn idő multával, hogy Abimélek a Filiszteusok királya kitekintvén az ablakon, látá Izsákot enyelegni Rebekával az ő feleségével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Kiálta azért Abimélek Izsáknak, és monda: Ímé bizony feleséged ő; hogyan mondhattad tehát: húgom ő!? És monda neki Izsák: Mert azt gondolám, netalán még meg kell halnom miatta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'És monda Abimélek: Miért mívelted ezt mi velünk? Kevésbe múlt, hogy feleségeddel nem hált valaki a nép közűl, és bűnt hoztál volna mi reánk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Parancsola azért Abimélek mind az egész népnek, ezt mondván: A ki ezt az embert vagy ennek feleségét illeténdi, bizonynyal meg kell halnia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'És vete Izsák azon a földön, és lett néki abban az esztendőben száz annyia, mert megáldá őt az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'És gyarapodék az a férfiú, és elébb-elébb megy vala a gyarapodásban, mígnem igen nagygyá lőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'És vala néki apró és öreg barma és sok cselédje, s irigykedének ezért reá a Filiszteusok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'És mindazokat a kútakat, melyeket az ő atyjának szolgái Ábrahámnak az ő atyjának idejében ástak vala, behányák a Filiszteusok, és betölték azokat földdel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'És monda Abimélek Izsáknak: Menj el közűlünk, mert sokkal hatalmasabbá lettél nálunknál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Elméne azért onnan Izsák, és Gérár völgyében voná fel sátrait, és ott lakék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'És ismét megásá Izsák a kútakat, a melyeket ástak vala az ő atyjának Ábrahámnak idejében, de a melyeket Ábrahám holta után behánytak vala a Filiszteusok, és azokkal a nevekkel nevezé azokat, a mely neveket adott vala azoknak az ő atyja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Izsák szolgái pedig ásnak vala a völgyben, és élő víznek forrására akadának ott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Gérár pásztorai pedig versengének Izsák pásztoraival, mondván: Miénk a víz. Ezért nevezé a kútnak nevét Észeknek, mivelhogy czivakodtak vala ő vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Más kútat is ásának s azon is versengének, azért annak nevét Szitnának nevezé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'És tovább vonula onnan és ása más kútat, a mely miatt nem versengének; azért nevezé nevét Rehobóthnak, és monda: Immár tágas helyet szerzett az Úr minékünk, és szaporodhatunk a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Felméne pedig onnan Beérsebába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'És megjelenék néki az Úr azon éjszaka, és monda: Én vagyok Ábrahámnak a te atyádnak Istene: Ne félj, mert te veled vagyok, és megáldalak téged, és megsokasítom a te magodat Ábrahámért, az én szolgámért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Oltárt építe azért ott, és segítségűl hívá az Úrnak nevét, s felvoná ott az ő sátorát; Izsák szolgái pedig kútat ásának ottan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Abimélek pedig elméne ő hozzá Gérárból és Akhuzzáth az ő barátja, meg Pikhól az ő hadvezére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'És monda nékik Izsák: Miért jöttetek én hozzám, holott gyűlöltök engem s elűztetek magatok közűl?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'Ők pedig mondák: Látván láttuk, hogy az Úr van te veled, és mondánk: legyen esküvés mi közöttünk, köztünk és te közötted; és kössünk frigyet teveled,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'Hogy minket gonoszszal nem illetsz, valamint mi sem bántottunk téged, és a mint csak jót cselekedtünk veled, és békességgel bocsátottunk el magunktól. Te már az Úr áldott embere vagy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Akkor vendégséget szerze nékik és evének és ivának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Reggel pedig felkelvén, egymásnak megesküvének, és elbocsátá őket Izsák, és elmenének ő tőle békességgel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Ugyanaz nap eljövének az Izsák szolgái, és hírt hozának néki a kút felől, melyet ástak vala; és mondának néki: Találtunk vizet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'S elnevezé azt Sibáhnak: Azokáért annak a városnak neve Beérseba mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'És mikor Ézsaú negyven esztendős vala, feleségűl vevé Jehudithot, a Khitteus Beéri leányát, és Boszmátot a Khitteus Elon leányát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'És ők valának Izsáknak és Rebekának lelke keserűsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'És lőn, a mikor megvénhedett vala Izsák, és szemei annyira meghomályosodtak vala, hogy nem látott, szólítá a nagyobbik fiát Ézsaút, és monda néki: Fiam; és ez monda néki: Imhol vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'És monda: Ímé megvénhedtem; nem tudom halálom napját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Most tehát vedd fel kérlek a te fegyvereidet, tegzedet és kézívedet, és menj ki a mezőre, és vadászsz énnékem vadat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'És csinálj nékem kedvem szerint való ételt, és hozd el nékem, hogy egyem: hogy megáldjon téged az én lelkem minekelőtte meghalok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Rebeka pedig meghallá, a mit Izsák az ő fiának Ézsaúnak monda; s a mint elméne Ézsaú a mezőre, hogy vadat vadászszon és hozzon:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'Szóla Rebeka Jákóbnak az ő fiának mondván: Ímé hallám, hogy atyád szóla bátyádnak Ézsaúnak mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, 'Hozz nékem vadat, és csinálj nékem kedvem szerint való ételt, hogy egyem; és megáldjalak téged az Úr előtt, minekelőtte meghalok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Most azért fiam, hallgass az én szavamra, a mit én parancsolok néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Menj el, kérlek, a nyájhoz, és hozz nékem onnan két kecskegödölyét a javából, hogy csináljak azokból a te atyádnak kedve szerint való ételt, a mint ő szereti.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'Te pedig beviszed atyádnak, hogy egyék, azért, hogy téged áldjon meg, minekelőtte meghal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Jákób pedig monda Rebekának az ő anyjának: Ímé az én bátyám Ézsaú szőrös ember, én pedig sima vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Netalán megtapogat engem az én atyám s olyan leszek előtte, mint valami csaló, és akkor átkot és nem áldást hozok magamra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'És monda néki az ő anyja: Reám szálljon a te átkod fiam, csak hallgass az én szavamra, és menj és hozd el nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Elméne azért, és elhozá, és vivé az ő anyjának; és az ő anyja ételt készíte, a mint szereti vala az ő atyja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'És vevé Rebeka az ő nagyobbik fiának Ézsaúnak drága ruháit, melyek ő nála otthon valának, és felöltözteté Jákóbot az ő kisebbik fiát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'A kecskegödölyék bőrével pedig beborítá az ő kezeit, és nyakának simaságát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'És az ételt a melyet készített vala, kenyérrel együtt adá Jákóbnak az ő fiának kezébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'És beméne az ő atyjához és monda: Atyám! és az monda: Ímhol vagyok. Ki vagy te fiam?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Monda Jákób az ő atyjának: Én vagyok Ézsaú a te elsőszülötted, aképen cselekedtem a mint parancsolád, kelj fel, kérlek, űlj le és egyél vadászatomból, hogy megáldjon engem a te lelked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'És monda Izsák az ő fiának: Hogy van az, hogy ily hamar találtál, fiam? És felele: Mert az Úr, a te Istened hozta előmbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'És monda Izsák Jákóbnak: Jer közelebb, kérlek, hadd tapogassalak meg fiam: hogy vajjon te vagy-é az én fiam Ézsaú vagy nem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Oda méne tehát Jákób Izsákhoz az ő atyjához, a ki megtapogatván őt, monda: A szó Jákób szava, de a kezek Ézsaú kezei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'És nem ismeré meg őt, mivelhogy kezei szőrösek valának mint Ézsaúnak az ő bátyjának kezei; annakokáért megáldá őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'És monda: Te vagy fiam Ézsaú? Felele: Én vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Az pedig monda: Hozd ide, hadd egyem az én fiam vadászatából, hogy megáldjon téged az én lelkem; és oda vivé, és evék; bort is vive néki és ivék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Akkor monda néki Izsák az ő atyja: Jer közelebb fiam, és csókolj meg engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Oda méne azért, és megcsókolá őt: s megérezvén ruháinak szagát, megáldá őt, és monda: Lám az én fiamnak illatja olyan, mint a mezőnek illatja, a melyet megáldott az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Adjon az Isten tenéked az ég harmatából, és a föld kövérségéből, és gabonának és bornak bőségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Népek szolgáljanak néked és nemzetségek hajoljanak meg előtted; légy úr a te atyádfiain, és hajoljanak meg előtted a te anyádnak fiai. Átkozott, a ki téged átkoz, és a ki téged áld, legyen áldott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'És lőn a mint elvégezé Izsák Jákóbnak megáldását; és épen csakhogy kiment vala Jákób az ő atyjának Izsáknak színe elől; az ő bátyja Ézsaú is megjöve vadászásából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'És készíte ő is ételt, s vivé az ő atyja elé, és mondá az ő atyjának: Keljen fel az én atyám, és egyék az ő fia vadászatából, hogy áldjon meg engem a te lelked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'És monda néki az ő atyja Izsák: Kicsoda vagy te? És monda: Én vagyok a te elsőszülött fiad Ézsaú.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Akkor Izsák elrémüle igen nagy rémüléssel, és monda: Ki volt hát az, a ki vadat fogott és behozá nékem, és én mindenből ettem minekelőtte te megjöttél, és megáldottam őt, és áldott is lészen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'A mint hallotta vala Ézsaú az ő atyjának beszédét, nagy és igen keserves kiáltással felkiálta, és monda atyjának: Áldj meg engem is atyám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Ez pedig monda: A te öcséd jöve el álnoksággal, és ő vevé el a te áldásodat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Az pedig monda: Nem méltán hívják-é őt Jákóbnak? mert immár két ízben csalt meg engemet; elvevé elsőszülöttségemet, most pedig áldásomat vevé el. És monda: Nem tartottál-é nékem is valami áldást?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Felele Izsák és monda Ézsaúnak: Ímé uraddá tettem őt, és minden atyjafiát szolgául adtam néki, gabonával is borral is őt láttam el; mit míveljek azért immár veled fiam?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Monda Ézsaú az ő atyjának: Avagy csak az az egy áldásod van-é néked atyám? Áldj meg engem, engem is atyám; és felemelé szavát Ézsaú és sír vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Felele azért Izsák az ő atyja, és monda néki: Ímé kövér földön lesz lakásod, és részed lesz az ég harmatjából onnan felűl;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'És fegyvered után élsz, és öcsédet szolgálod. De lészen, a mikor ellene támadsz, letöröd igáját nyakadról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Gyűlöli vala azért Ézsaú Jákóbot az áldásért, a melylyel megáldotta vala őt az ő atyja, és monda Ézsaú az ő szívében: Közelgetnek az én atyámért való gyásznak napjai, és akkor megölöm az én öcsémet Jákóbot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Mikor pedig hírűl vivék Rebekának, az ő nagyobbik fiának Ézsaúnak beszédit, elkülde és magához hívatá az ő kisebbik fiát Jákóbot, és monda néki: Ímé Ézsaú a te bátyád azzal fenyeget, hogy megöl téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Most azért fiam, hallgass az én szavamra, és kelj fel és fuss Lábánhoz az én bátyámhoz Háránba,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'És maradj nála egy kevés ideig, míg a te bátyád haragja elmúlik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'Míg elfordul a te bátyád haragja te rólad, és elfelejtkezik arról a mit rajta elkövettél: akkor elküldök és haza hozatlak téged: miért fosztatnám meg mindkettőtöktől egy napon?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Izsáknak pedig monda Rebeka: Eluntam életemet a Khitteusok leányai miatt. Ha Jákób a Khitteusok leányai közűl vesz feleséget, a milyenek ezek is, ez ország leányai közűl valók; minek nékem az élet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Előhívatá azért Izsák Jákóbot, és megáldá őt, és megparancsolá néki és mondá: Ne végy feleséget a Kananeusok leányai közűl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Kelj fel, menj el Mésopotámiába, Bethuélnek a te anyád atyjának házához, és onnan végy magadnak feleséget, Lábánnak a te anyád bátyjának leányai közűl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'A mindenható Isten pedig áldjon meg, szaporítson és sokasítson meg téged, hogy népek sokaságává légy;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'És adja néked az Ábrahám áldását, tenéked, és a te magodnak te veled egybe; hogy örökség szerint bírjad a földet, melyen jövevény voltál, melyet az Isten adott vala Ábrahámnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Elbocsátá azért Izsák Jákóbot, hogy menjen Mésopotámiába Lábánhoz a Siriabeli Bethuél fiához, Rebekának, Jákób és Ézsaú anyjának bátyjához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'És látá Ézsaú, hogy Izsák megáldotta Jákóbot, és elbocsátotta őt Mésopotámiába, hogy onnan vegyen magának feleséget; és hogy mikor áldja vala, parancsola néki, és monda: Ne végy feleséget a Kananeusok leányai közűl;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'És hogy Jákób hallgata atyja és anyja szavára, és el is ment Mésopotámiába;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'És látá Ézsaú, hogy a Kananeusok leányai nem tetszenek Izsáknak az ő atyjának:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'Elméne Ézsaú Ismáelhez, és feleségűl vevé még az ő feleségeihez Ismáelnek az Ábrahám fiának leányát Mahaláthot, Nebajóthnak húgát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Jákób pedig kiindula Beérsebából, és Hárán felé tartott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'És juta egy helyre, holott meghála, mivelhogy a nap lement vala: és vőn egyet annak a helynek kövei közűl, és feje alá tevé; és lefeküvék azon a helyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'És álmot láta: Ímé egy lajtorja vala a földön felállítva, melynek teteje az eget éri vala, és ímé az Istennek Angyalai fel- és alájárnak vala azon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'És ímé az Úr áll vala azon és szóla: Én vagyok az Úr, Ábrahámnak a te atyádnak Istene, és Izsáknak Istene; ezt a földet a melyen fekszel néked adom és a te magodnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'És a te magod olyan lészen mint a földnek pora, és terjeszkedel nyugotra és keletre, északra és délre, és te benned és a te magodban áldatnak meg a föld minden nemzetségei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'És ímé én veled vagyok, hogy megőrizzelek téged valahova menéndesz, és visszahozzalak e földre; mert el nem hagylak téged, míg be nem teljesítem a mit néked mondtam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Jákób pedig fölébredvén álmából, monda: Bizonyára az Úr van e helyen, és én nem tudtam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Megrémüle annak okáért és monda: Mily rettenetes ez a hely; nem egyéb ez, hanem Istennek háza, és az égnek kapuja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'És felkele Jákób reggel, és vevé azt a követ, melyet feje alá tett vala, és oszlopul állítá fel azt, és olajat önte annak tetejére;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'És nevezé annak a helynek nevét Béthelnek, az előtt pedig Lúz vala annak a városnak neve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'És fogadást tőn Jákób, mondá: Ha az Isten velem leénd, és megőriz engem ezen az úton, a melyen most járok, és ha ételűl kenyeret s öltözetűl ruhát adánd nékem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'És békességgel térek vissza az én atyámnak házához: akkor az Úr leénd az én Istenem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'És ez a kő, a melyet oszlopul állítottam fel, Isten háza lészen, és valamit adándasz nékem, annak tizedét néked adom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Jákób azután lábára kelvén, elméne a napkeletre lakók földére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'És látá, hogy ímé egy kút van a mezőben, és hogy ott három falka juh hever vala. Mert abból a kútból itatják vala a nyájakat; de a kútnak száján nagy kő vala:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Mikor pedig ott valamennyi nyáj összeverődik, elgördítik a követ a kút szájáról és megitatják a juhokat s ismét helyére teszik a követ, a kút szájára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'És monda nékik Jákób: Honnan valók vagytok atyámfiai? És mondának: Háránból valók vagyunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'És monda nékik: Ismeritek-é Lábánt, a Nákhor fiát? s azok felelének: Ismerjük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Azután monda nékik: Egészségben van-é? s azok mondának: Egészségben van, és az ő leánya Rákhel ímhol jő a juhokkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'És monda Jákób: Ímé még nagy fenn van a nap, nincs ideje hogy betereljék a marhát: itassátok meg a juhokat, és menjetek, legeltessetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'Azok pedig felelének: Nem tehetjük míg valamennyi nyáj össze nem verődik, és el nem gördítik a követ a kút szájáról, hogy megitathassuk a juhokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Még beszélget vala velők, mikor megérkezék Rákhel az ő atyja juhaival, melyeket legeltet vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'S lőn, a mint meglátá Jákób Rákhelt, Lábánnak az ő anyja bátyjának leányát, és Lábánnak az ő anyja bátyjának juhait, odalépett Jákób és elgördíté a követ a kút szájáról, és megitatá Lábánnak az ő anyja bátyjának juhait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'És megcsókolá Jákób Rákhelt, és nagy felszóval síra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'S elbeszélé Jákób Rákhelnek, hogy ő az ő atyjának rokona és hogy Rebekának fia. Ez pedig elfuta, és megmondá az ő atyjának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'És lőn mikor Lábán Jákóbnak, az ő húga fiának hírét hallá, eleibe futa, megölelé és megcsókolá őt, és bevivé az ő házába, és az mindeneket elbeszéle Lábánnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'És monda néki Lábán: Bizony én csontom és testem vagy te! És nála lakék egy hónapig,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'És monda Lábán Jákóbnak: Avagy ingyen szolgálj-é engem azért, hogy atyámfia vagy? Mondd meg nékem, mi legyen a béred?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Vala pedig Lábánnak két leánya: a nagyobbiknak neve Lea, a kisebbiknek neve Rákhel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Leának pedig gyenge szemei valának, de Rákhel szép termetű és szép tekintetű vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Megszereti vala azért Jákób Rákhelt, és monda: Szolgállak téged hét esztendeig Rákhelért, a te kisebbik leányodért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'És monda Lábán: Jobb néked adnom őt, hogysem másnak adjam őt, maradj én nálam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Szolgála tehát Jákób Rákhelért hét esztendeig, s csak néhány napnak tetszék az neki, annyira szereti vala őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'És monda Jákób Lábánnak: Add meg nékem az én feleségemet: mert az én időm kitelt, hadd menjek be hozzá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'És begyűjté Lábán annak a helynek minden népét, és szerze lakodalmat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Estve pedig vevé az ő leányát Leát, és bevivé hozzá, a ki beméne ő hozzá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'És Lábán az ő szolgálóját Zilpát, szolgálóul adá az ő leányának Leának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'És reggelre kelve: Ímé ez Lea! Monda azért Lábánnak: Mit cselekedtél én velem? Avagy nem Rákhelért szolgáltalak-é én tégedet? Miért csaltál meg engem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Lábán pedig monda: Nem szokás nálunk, hogy a kisebbiket oda adják a nagyobbik előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Töltsd ki ennek hetét, azután amazt is néked adjuk a szolgálatért, melylyel majd szolgálsz nálam még más hét esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Jákób tehát aképen cselekedék, kitölté azt a hetet; ez pedig néki adá Rákhelt, az ő leányát feleségűl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'És adá Lábán az ő leányának Rákhelnek, az ő szolgálóját Bilhát, hogy néki szolgálója legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'És beméne Rákhelhez is, és inkább szereté Rákhelt, hogysem Leát és szolgála ő nála még más hét esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'És meglátá az Úr Lea megvetett voltát, és megnyitá annak méhét. Rákhel pedig magtalan vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Fogada azért Lea az ő méhében és szűle fiat, és nevezé nevét Rúbennek, mert azt mondja vala: Meglátta az Úr az én nyomorúságomat; most már szeretni fog engem az én férjem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Azután ismét teherbe esék és szűle fiat, és monda: Mivelhogy meghallotta az Úr megvetett voltomat, azért adta nékem ezt is; és nevezé nevét Simeonnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'És megint teherbe esék és szűle fiat, és monda: Most már ragaszkodni fog hozzám az én férjem, mert három fiat szűltem néki; azért nevezé nevét Lévinek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'És ismét teherbe esék, és fiat szűle és mondá: Most már hálákat adok az Úrnak; azért nevezé nevét Júdának, és megszűnék a szűléstől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'És látá Rákhel, hogy ő nem szűle Jákóbnak, irigykedni kezde Rákhel az ő nénjére, és monda Jákóbnak: Adj nékem gyermekeket, mert ha nem, meghalok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Felgerjede azért Jákób haragja Rákhel ellen, és monda: Avagy Isten vagyok-é én, ki megtagadta tőled a méhnek gyümölcsét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'És monda ez: Ímhol az én szolgálóm Bilha, menj be hozzá, hogy szűljön az én térdeimen, és én is megépüljek ő általa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Adá tehát néki az ő szolgálóját Bilhát feleségűl, és beméne ahhoz Jákób.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'És teherbe esék Bilha és szűle Jákóbnak fiat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'És monda Rákhel: Ítélt felőlem az Isten, és meg is hallgatta szavamat, és adott énnékem fiat: azért nevezé nevét Dánnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Ismét fogada az ő méhében, és szűle Bilha, a Rákhel szolgálója más fiat is Jákóbnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'És monda Rákhel: Nagy tusakodással tusakodtam az én nénémmel, és győztem; azért nevezé nevét Nafthalinak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Látván pedig Lea hogy ő megszűnt a szűléstől, vevé az ő szolgálóját Zilpát, és adá azt Jákóbnak feleségűl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'És szűle Zilpa, Lea szolgálója, fiat Jákóbnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'És monda Lea: Szerencsére! és nevezé nevét Gádnak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'És szűle Zilpa, Lea szolgálója, más fiat is Jákóbnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'És monda Lea: Oh én boldogságom! bizony boldognak mondanak engem az asszonyok: és nevezé nevét Ásernek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'És kiméne Rúben búzaaratáskor, és talála a mezőn mandragóra-bogyókat s vivé azokat az ő anyjának, Leának. És monda Rákhel Leának: Adj nékem kérlek a fiad mandragóra-bogyóiból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Az pedig monda néki: Talán keveselled, hogy elvetted tőlem az én férjemet, s a fiam mandragóra-bogyóit is elvennéd tőlem? És monda Rákhel: Háljon veled hát az éjjel a te fiad mandragóra-bogyóiért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Mikor Jákób este a mezőről jöve, eleibe méne Lea, és monda: Én hozzám jőjj be, mert megvettelek a fiam mandragóra-bogyóiért; és nála hála azon éjszaka.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'És meghallgatá Isten Leát, mert fogada az ő méhében és szűle Jákóbnak ötödik fiat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'És monda Lea: Megadta az Isten jutalmamat, a miért szolgálómat férjemnek adtam; azért nevezé nevét Izsakhárnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'És ismét fogada az ő méhében Lea, és szűle hatodik fiat Jákóbnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'És monda Lea: Megajándékozott az Isten engem jó ajándékkal; most már velem lakik az én férjem, mert hat fiat szűltem néki, és nevezé nevét Zebulonnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Annakutána szűle leányt, és nevezé nevét Dínának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Megemlékezék pedig az Isten Rákhelről; és meghallgatá őt az Isten és megnyitá az ő méhét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'És fogada méhében, és szűle fiat, s monda: Elvevé Isten az én gyalázatomat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'És nevezé nevét Józsefnek, mondván: Adjon ehhez az Úr nékem más fiat is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'És lőn, a mint szűlte vala Rákhel Józsefet, monda Jákób Lábánnak: Bocsáss el engemet, hadd menjek el az én helyembe, az én hazámba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Add meg nékem az én feleségeimet és magzatimat, a kikért szolgáltalak téged, hadd menjek el, mert te tudod az én szolgálatomat, a melylyel szolgáltalak téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'És monda néki Lábán: Vajha kedvet találtam volna szemeid előtt! Úgy sejtem, hogy te éretted áldott meg engem az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'És monda: Szabj bért magadnak és én megadom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Ez pedig monda: Te tudod mimódon szolgáltalak téged, és hogy mivé lett nálam a te jószágod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Mert a mi kevesed vala én előttem, sokra szaporodott, és megáldott az Úr téged az én lábam nyomán. Immár mikor tehetek valamit a magam házáért is?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'És monda Lábán: Mit adjak néked? Felele Jákób: Ne adj nékem semmit; juhaidat ismét legeltetem és őrizem, ha nekem ezt a dolgot megteszed:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Nyájaidat ma mind végig járom, minden pettyegetett és tarka bárányt kiszaggatok közűlök, és minden fekete bárányt a juhok közűl, s a tarkát és pettyegetettet a kecskék közűl, s legyen ez az én bérem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'S a mikor majd bérem iránt eljövéndesz, mi előtted lesz, becsületességemről ez felel: a mi nem pettyegetett vagy tarka a kecskék, s nem fekete a juhok közt, az mind lopott jószág nálam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'És monda Lábán: Ám legyen: Vajha a te beszéded szerint lenne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Külön választá azért azon a napon a pettyegetett és tarka kosokat, és minden csíkos lábú és tarka kecskét, mind a melyikben valami fehérség vala, és minden feketét a juhok közűl, és adá az ő fiainak keze alá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'És három napi járó földet vete maga közé és Jákób közé; Jákób pedig legelteti vala Lábán egyéb juhait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'És vőn Jákób zöld nyár-, mogyoró- és gesztenye-vesszőket, és meghántá azokat fehéresen csíkosra, hogy látható legyen a vesszők fehére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'És a vesszőket, melyeket meghántott vala, felállítá a csatornákba, az itató válúkba, melyekre a juhok inni járnak vala, szembe a juhokkal, hogy foganjanak, mikor inni jönnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'És a juhok a vesszők előtt foganának és ellenek vala csíkos lábúakat, pettyegetetteket és tarkákat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Azután külön szakasztá Jákób ezeket a bárányokat, és a Lábán nyáját arczczal fordítja vala a csíkos lábú és fekete bárányokra; így szerze magának külön falkákat, melyeket nem ereszte a Lábán juhai közé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'És lőn, hogy mikor a nyáj java részének vala párzási ideje, akkor Jákób a vesszőket oda raká a válúkba a juhok eleibe, hogy a vesszőket látva foganjanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'De mikor satnya vala a nyáj, nem rakja vala oda s ily módon Lábánéi lőnek a satnyák, a java pedig Jákóbé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'És felette igen meggazdagodék a férfiú; és vala néki sok juha, szolgálója, szolgája, tevéje és szamara.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'És meghallá a Lábán fiainak beszédét, kik ezt mondják vala: Valamije volt atyánknak, mind elvette Jákób; és atyánkéból szerezte mind e gazdagságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'És látá Jákób a Lábán orczáját, hogy ímé nem olyan ő hozzá mint annakelőtte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Monda pedig az Úr Jákóbnak: Térj meg atyáid földére, a te rokonságod közé, és veled lészek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Elkülde tehát Jákób, és kihívatá magához Rákhelt és Leát a mezőre az ő nyájához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'És monda nékik: Látom atyátok orczáját, hogy nem olyan hozzám, mint ennekelőtte; de az én atyám Istene velem volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Ti pedig tudjátok, hogy teljes erőm szerint szolgáltam atyátokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'De atyátok engem megcsalt s tízszer is megváltoztatta béremet; mindazáltal az Isten nem engedte, hogy nékem kárt tehessen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Mikor azt mondotta: A pettyegetettek legyenek a te béred, a juhok mind pettyegetetteket ellenek vala. Ha azt mondotta: A csíkos lábúak legyenek a te béred, a juhok mind csíkos lábúakat ellenek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Így vette el Isten atyátok jószágát és nékem adta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Mert lőn a juhok foganásának idejekor, szemeimet felemelém, és látom vala álomban, hogy ímé a juhokat hágó kosok csíkos lábúak, pettyegetettek és tarkák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Akkor monda nékem az Isten Angyala álomban: Jákób. És felelék: Ímhol vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'És ő monda: Emeld fel szemeidet és lásd, hogy a mely kosok a juhokat hágják, azok mind csíkos lábúak, pettyegetettek és tarkák. Mert mindazt láttam, a mit veled Lábán cselekeszik vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Én vagyok ama Béthelnek Istene, a hol emlékoszlopot kentél fel, és a hol fogadást tettél nékem. Most kelj fel, menj ki e földről, és térj vissza szülőföldedre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'És felele Rákhel és Lea, és mondának néki: Vajjon vagyon-é még nékünk valami részünk és örökségünk a mi atyánk házában?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Avagy nem úgy tartott-é minket mint idegeneket? midőn minket eladott, és értékünket is teljesen megemésztette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Mert mind ez a gazdagság, melyet Isten vett el a mi atyánktól, miénk és a mi fiainké. Most azért valamit néked az Isten mondott, azt cselekedjed.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Felkele tehát Jákób, és feltevé gyermekeit és feleségeit a tevékre;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'És elvivé minden nyáját, és minden keresményét, melyet keresett vala; minden jószágát, melyet szerzett vala Mésopotámiában, hogy elmenjen az ő atyjához Izsákhoz Kanaán földére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Lábán pedig elment vala juhait nyírni; azonközben ellopá Rákhel a házi bálványokat, melyek atyjánál valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Jákób pedig meglopá a Siriabeli Lábánnak szívét, mivelhogy nem adá tudtára, hogy szökni akar.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Megszökék tehát mindenestől, és felkelvén, általméne a folyóvízen, és Gileád hegye felé tarta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'És mikor harmad napra megmondák Lábánnak, hogy Jákób elszökött;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Maga mellé vévén az ő rokonait, hét napi járó földig űzé őket; és eléré a Gileád hegyén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Isten pedig megjelenék a Siriabeli Lábánnak éjjel álomban, és monda néki: Vigyázz magadra, Jákóbnak se jót, se rosszat ne szólj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Mikor eléré Lábán Jákóbot, s Jákób a hegyen voná fel sátorát; Lábán is a Gileád hegyén voná fel az ő rokonaival egybe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'És monda Lábán Jákóbnak: Mit cselekedtél, hogy megloptad szívemet, és leányaimat fegyverrel nyert foglyokként vitted el?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Miért futottál el titkon, s loptál meg engem? miért nem jelentetted nékem, hogy elbocsátottalak volna örömmel, énekszóval, dob- és hegedűszóval?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'És nem engedted meg, hogy megcsókoljam fiaimat és leányaimat. Ez egyszer bolondul cselekedtél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Volna erőm hozzá, hogy rosszat tegyek veletek, de a ti atyátok Istene tegnap éjszaka megszólíta engem, ezt mondván: Vigyázz magadra, Jákóbnak se jót, se rosszat ne szólj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Hogyha pedig immár el akartál menni, mivelhogy nagy kívánsággal kívánkoztál atyád házához: miért loptad el az én isteneimet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Felelvén pedig Jákób, monda Lábánnak: Mert féltem, mert gondolom vala, hogy talán elveszed a te leányaidat én tőlem erővel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'A kinél pedig megtalálod a te isteneidet, ne éljen az. Atyánkfiai előtt vizsgáld meg, mid van nálam, és vidd el. Mert nem tudja vala Jákób, hogy Rákhel lopta el azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Beméne tehát Lábán Jákób sátorába, és Lea sátorába, és a két szolgáló sátorába, és nem találá meg; akkor kiméne Lea sátorából, és méne a Rákhel sátorába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Rákhel pedig vette vala a házi bálványokat, és tette vala azokat egy tevének a nyergébe, és rájok űle; Lábán pedig felhányá az egész sátort, és nem találta vala meg azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Akkor monda az ő atyjának: Ne haragudjék az én uram, hogy fel nem kelhetek előtted, mert asszonyok baja van rajtam. Keresé tehát, de nem találá a házi bálványokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Jákób pedig haragra gerjede s feddődék Lábánnal. Megszólala Jákób és monda Lábánnak: Mi a vétkem, és mi a bűnöm, hogy üldözőbe vettél?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Bezzeg minden holmimat felhánytad, mit találtál a magad házi holmija közűl valót? add elő itt az én rokonaim és a te rokonaid előtt, hogy tegyenek ítéletet kettőnk között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Immár húsz esztendeje vagyok nálad, juhaid és kecskéid nem vetéltek el, és nyájad kosait nem ettem meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'A mit a vad megszaggatott, nem vittem hozzád, én fizettem meg azt; tőlem követelted a nappal lopottat, mint az éjjel lopottat is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'Úgy voltam hogy nappal a hőség emésztett, éjjel pedig a hideg; és az álom távol maradt szemeimtől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Immár húsz esztendeje hogy házadnál vagyok; tizennégy esztendeig szolgáltalak két leányodért, és hat esztendeig juhaidért; te pedig béremet tízszer is megváltoztattad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Ha az én atyám Istene, Ábrahám Istene, és az Izsák félelme velem nem volt volna, bizony most üresen bocsátanál el engem, de megtekintette Isten az én nyomorúságomat és kezeim munkáját, és megfeddett téged tegnap éjjel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Felele pedig Lábán és monda Jákóbnak: A leányok én leányaim és a fiak én fiaim, és a nyáj az én nyájam, s valamit látsz mind az enyim, de mit tehetek ma ezeknek az én leányaimnak, vagy az ő magzatjaiknak, a kiket szűltek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Most tehát jer, kössünk szövetséget, én meg te, hogy az légyen bizonyságul közöttem és közötted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'És vőn Jákób egy követ, és felemelé azt emlékoszlopul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'És monda Jákób az ő atyjafiainak: Szedjetek köveket! És gyűjtének köveket, és csinálának rakást; és evének ott a rakáson.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'És nevezé azt Lábán Jegár-Sahaduthának, Jákób pedig nevezé Gálhédnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'És mondja vala Lábán: E rakás bizonyság ma, közöttem és közötted, azért nevezék Gálhédnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'És Miczpának, mivelhogy mondá: Az Úr legyen vigyázó közöttem és te közötted, a mikor egymástól elválunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Ha az én leányaimat nyomorgatándod, és ha az én leányaimon kivűl több feleséget veéndesz, senki sincs ugyan velünk; de meglásd: Isten a bizonyság én közöttem és te közötted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'És monda Lábán Jákóbnak: Ímé e rakás kő és ímé ez emlékoszlop, a melyet raktam én közöttem és te közötted,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'Bizonyság legyen e rakás kő, és bizonyság ez az emlékoszlop, hogy sem én nem megyek el e rakás kő mellett te hozzád, sem te nem jössz át én hozzám e rakás kő, és ez emlékoszlop mellett gonosz végre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Az Ábrahám Istene, és a Nákhor Istene, és az ő atyjok Istene tegyenek ítéletet közöttünk: És megesküvék Jákób az ő atyjának Izsáknak félelmére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Akkor Jákób áldozatot öle ott a hegyen, és vendégségbe hívá az ő rokonait. És vendégeskedtek vala, s meghálának a hegyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'Reggel pedig felkele Lábán és megcsókolá fiait és leányait és megáldá őket. Azután elméne Lábán, és visszatére az ő helyére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Jákób tovább méne az ő útján, és szembe jövének vele az Isten Angyalai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'És monda Jákób mikor azokat látja vala: Isten tábora ez; és nevezé annak a helynek nevét Mahanáimnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Azután külde Jákób követeket maga előtt Ézsaúhoz az ő bátyjához, Széir földébe, Edóm mezőségébe,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'És parancsola azoknak mondván: Így szóljatok az én uramnak Ézsaúnak: Ezt mondja a te szolgád Jákób: Lábánnál tartózkodtam és időztem mind ekkorig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'Vannak pedig nékem ökreim és szamaraim, juhaim, szolgáim és szolgálóim, azért híradásul követséget küldök az én uramhoz, hogy kedvet találjak szemeid előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'És megtérének Jákóbhoz a követek, mondván: Elmentünk vala a te atyádfiához Ézsaúhoz, és már jön is elődbe, és négyszáz férfi van vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Igen megíjede Jákób és féltében a népet, mely vele vala, a juhokat, a barmokat és a tevéket két seregre osztá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'És monda: Ha eljön Ézsaú az egyik seregre, és azt levágja, a hátramaradt sereg megszabadul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'És monda Jákób: Óh én atyámnak Ábrahámnak Istene, és én atyámnak Izsáknak Istene, Jehova! ki azt mondád nékem: Térj vissza hazádba, a te rokonságod közé, s jól tészek veled:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'Kisebb vagyok minden te jótéteményednél és minden te hűségednél, a melyeket a te szolgáddal cselekedtél; mert csak pálczámmal mentem vala által ezen a Jordánon, most pedig két sereggé lettem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Szabadíts meg, kérlek, engem az én bátyám kezéből, Ézsaú kezéből; mert félek ő tőle, hogy rajtam üt és levág engem, az anyát a fiakkal egybe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Te pedig azt mondottad: Jól tévén jól tészek te veled, és a te magodat olyanná tészem mint a tenger fövénye, mely meg nem számláltathatik sokasága miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'És ott hála azon éjjel: és választa abból, a mi kezénél vala, ajándékot Ézsaúnak az ő bátyjának:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'Kétszáz kecskét, és húsz bakot; kétszáz juhot, és húsz kost;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'Harmincz szoptatós tevét s azok fiait; negyven tehenet, és tíz tulkot: húsz nőstény szamarat, és tíz szamár vemhet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'És szolgái kezébe adá, minden nyájat külön-külön, és monda az ő szolgáinak: Menjetek el én előttem, és közt hagyjatok nyáj és nyáj között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'És parancsola az elsőnek, mondván: Ha az én bátyám Ézsaú előtalál és megkérdez téged, mondván: Ki embere vagy? Hová mégy? És kiéi ezek előtted?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'Akkor azt mondjad: Szolgádé Jákóbé; ajándék az, a melyet küld az én uramnak Ézsaúnak, és ímé ő maga is jön utánunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'Ugyanazt parancsolá a másiknak, a harmadiknak, és mindazoknak, kik a nyájak után mennek vala, mondván: Ilyen szóval szóljatok Ézsaúnak, mikor vele találkoztok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Ezt is mondjátok: Ímé Jákób a te szolgád utánunk jő; mert így gondolkodik vala: Megengesztelem őt az ajándékkal, mely előttem megy, és azután leszek szembe vele, talán kedves lesz személyem előtte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'Előlméne tehát az ajándék; ő pedig azon éjjel a seregnél hála.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Felkele pedig ő azon éjszaka és vevé két feleségét, két szolgálóját és tizenegy gyermekét, és általméne a Jabbók révén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Vevé hát azokat és átköltözteté a vízen, azután átköltözteté mindenét valamije vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Jákób pedig egyedűl marada és tusakodik vala ő vele egy férfiú, egész a hajnal feljöveteléig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Aki mikor látá, hogy nem vehet rajta erőt, megilleté csípőjének forgócsontját, és kiméne helyéből Jákób csípőjének forgócsontja a vele való tusakodás közben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'És monda: Bocsáss el engem, mert feljött a hajnal. És monda Jákób: Nem bocsátlak el téged, míg meg nem áldasz engemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'És monda néki: Mi a te neved? És ő monda: Jákób.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Amaz pedig monda: Nem Jákóbnak mondatik ezután a te neved, hanem Izráelnek; mert küzdöttél Istennel és emberekkel, és győztél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'És megkérdé Jákób, és monda: Mondd meg, kérlek, a te nevedet. Az pedig monda: Ugyan miért kérded az én nevemet? És megáldá őt ott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Nevezé azért Jákób annak a helynek nevét Peniélnek: mert látám az Istent színről színre, és megszabadult az én lelkem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'És a nap felkél vala rajta, amint elméne Peniél mellett, ő pedig sántít vala csípőjére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Azért nem eszik Izráel fiai a csípő forgócsontjának inahúsát mind e mai napig, mivelhogy illetve vala Jákób csípője forgócsontjának inahúsa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Jákób pedig felemelé szemeit és látá, hogy ímé Ézsaú jő vala, és négyszáz férfiú ő vele; megosztá azért a gyermekeket Lea mellé, Rákhel mellé, és két szolgálója mellé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'És előreállítá a szolgálókat és azok gyermekeit, ezek után Leát és az ő gyermekeit, Rákhelt pedig és Józsefet leghátul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Maga pedig előttök megy vala, és hétszer hajtá meg magát a földig, a míg bátyjához juta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Ézsaú pedig eleibe futamodék és megölelé őt, nyakába borúla, s megcsókolá őt, és sírának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'És felemelé szemeit s látá az asszonyokat és a gyermekeket, és monda: Kicsodák ezek teveled? Ő pedig monda: A gyermekek, kikkel Isten megajándékozta a te szolgádat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'És közelítének a szolgálók, ők és gyermekeik és meghajták magokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Elérkezék Lea is az ő gyermekeivel, és meghajták magokat; utoljára érkezék József és Rákhel, és ők is meghajták magokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'És monda Ézsaú: Mire való ez az egész sereg, melyet előltalálék? És felele: Hogy kedvet találjak az én uram szemei előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'És monda Ézsaú: Van nekem elég, jó öcsém, legyen tiéd, a mi a tiéd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Monda pedig Jákób: Ne úgy, kérlek, hanem ha kedvet találtam szemeid előtt, fogadd el ajándékomat az én kezemből; mert a te orczádat úgy néztem, mintha az Isten orczáját látnám, és te kegyesen fogadál engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Vedd el kérlek az én ajándékomat, melyet hoztam néked, mivelhogy az Isten kegyelmesen cselekedett én velem, és mindenem van nékem. És unszolá őt, és elvevé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'És monda: Induljunk, menjünk el, és én előtted megyek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Felele néki Jákób: Az én uram jól tudja, hogy e gyermekek gyengék, és hogy szoptatós juhokkal és barmokkal vagyok körűl, a melyeket ha csak egy napig zaklatnak is, a nyájak mind elhullanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Menjen el azért az én uram az ő szolgája előtt, én is elballagok lassan, a jószág lépése szerint, a mely előttem van, és a gyermekek lépése szerint, míg eljutok az én uramhoz Széirbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'És monda Ézsaú: Hadd rendeljek melléd néhányat a nép közűl, mely velem van. S ez monda: Minek az? csak kedvet találjak az én uram szemei előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Visszatére tehát Ézsaú még az nap az ő útján Széir felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Jákób pedig méne Szukkóthba és építe magának házat, barmainak pedig hajlékokat csinála, s azért nevezé a hely nevét Szukkóthnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Annakutána minden bántás nélkül méne Jákób Mésopotámiából jövet Sekhem városába, mely vala a Kanaán földén, és letelepedék a város előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'És megvevé a mezőnek azt a részét, a hol sátorát felvonta vala, Khámornak a Sekhem atyjának fiaitól száz pénzen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'És oltárt állíta ott, és nevezé azt ily névvel: Isten, Izráel Istene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Kiméne pedig Dína, Leának leánya, kit Jákóbnak szűlt vala, hogy meglátogassa annak a földnek leányait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'És meglátá őt Sekhem, a Khivveus Khámornak, az ország fejedelmének fia, és elragadá őt, és vele hála és erőszakot tesz vala rajta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'És ragaszkodék az ő lelke Dínához a Jákób leányához, és megszereté a leányt és szívéhez szól vala a leánynak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Szóla pedig Sekhem Khámornak az ő atyjának, mondván: Vedd nékem feleségűl ezt a leányt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'És meghallá Jákób, hogy megszeplősítette Dínát, az ő leányát, fiai pedig a mezőn valának a barommal, azért veszteg marada Jákób, míg azok megjövének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'És kiméne Khámor, Sekhem atyja Jákóbhoz, hogy szóljon vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Mikor Jákób fiai megjövének a mezőről és meghallák a dolgot, elkeseredének s nagyon megharaguvának azok az emberek, azért hogy ocsmányságot cselekedett Izráelben, Jákób leányával hálván, a minek nem kellett volna történni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'És szóla nékik Khámor, mondván: Az én fiam Sekhem, lelkéből szereti a ti leányotokat, kérlek, adjátok azt néki feleségűl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'És szerezzetek velünk sógorságot: a ti leányaitokat adjátok nékünk, és a mi leányainkat vegyétek magatoknak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'És lakjatok velünk; a föld előttetek van, lakjátok, s kereskedjetek rajta és bírjátok azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Sekhem is monda a Dína atyjának és az ő bátyjainak: Hadd találjak kedvet előttetek, és valamit mondotok nékem, megadom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Akármily nagy jegyadományt és ajándékot kivántok, megadom a mint mondjátok nékem, csak adjátok nékem a leányt feleségűl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'A Jákób fiai pedig álnokul felelének Sekhemnek és Khámornak az ő atyjának, és szólának, mivelhogy megszeplősítette Dínát az ő húgokat,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'És mondának nékik: Nem mívelhetjük e dolgot, hogy a mi húgunkat körűlmetélkedetlen férfiúnak adjuk; mert ez nékünk gyalázat volna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Veletek csak úgy egyezünk, ha hasonlókká lesztek hozzánk, hogy minden férfiú körűlmetélkedjék ti köztetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Így a mi leányainkat néktek adjuk, és a ti leányaitokat magunknak vesszük, veletek lakozunk, és egy néppé leszünk;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Hogyha pedig nem hallgattok reánk, hogy körűlmetélkedjetek: felveszszük a mi leányunkat és elmegyünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'És tetszék azoknak beszéde Khámornak, és Sekhemnek a Khámor fiának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Nem is halasztá az ifjú a dolog véghezvitelét, mivelhogy igen szereti vala a Jákób leányát; néki pedig atyja házanépe között mindenkinél nagyobb becsűlete vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Elméne azért Khámor és Sekhem az ő fia az ő városuk kapujába; és szólának az ő városuk férfiaival, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Ezek az emberek békességesek velünk, hadd lakjanak e földön, és kereskedjenek benne, mert ímé e föld elég tágas nékik; az ő leányaikat vegyük magunknak feleségűl, és a mi leányainkat adjuk nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'De csak úgy egyeznek bele e férfiak, hogy velünk lakjanak és egy néppé legyenek velünk, ha minden férfiú körűlmetélkedik közöttünk, a miképen ők is körűl vannak metélkedve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Nyájaik, jószáguk, és minden barmuk nemde nem miéink lesznek-é? csak egyezzünk meg velök, akkor velünk laknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'És engedének Khámornak, és Sekhemnek az ő fiának mindenek, a kik az ő városa kapuján kijárnak vala, és körűlmetélkedék minden férfiú, a ki az ő városa kapuján kijár vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'És lőn harmadnapon, mikor ezek a seb fájdalmában valának, a Jákób két fia, Simeon és Lévi, Dínának bátyjai, fegyvert ragadának s bátran a városra ütének és minden férfit megölének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Khámort, és az ő fiát Sekhemet fegyver élére hányák, és elvivék Dínát a Sekhem házából, és kimenének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'A Jákób fiai a megölteknek esének és feldúlák a várost, mivelhogy megszeplősítették vala az ő húgokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Azok juhait, barmait, szamarait, és valami a városban, és a mezőn vala, elvivék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'És minden gazdagságukat, minden gyermekeiket és feleségeiket fogva vivék és elrablák, és mindent a mi a házban vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'És monda Jákób Simeonnak és Lévinek: Megháborítottatok engem, és utálatossá tettetek e föld lakosai előtt, a Kananeusok és Perizeusok előtt; én pedig kevesed magammal vagyok, és ha összegyűlnek ellenem, levágnak, és eltörölnek engem, mind házam népével egybe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Azok pedig mondának: Hát mint tisztátalan személylyel, úgy kellett-é bánni a mi húgunkkal?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Monda pedig az Isten Jákóbnak: Kelj fel, eredj fel Béthelbe és telepedjél le ott; és csinálj ott oltárt amaz Istennek, ki megjelenék néked, mikor a te bátyád Ézsaú előtt futsz vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Akkor monda Jákób az ő házanépének, és mind azoknak, kik vele valának: Hányjátok el az idegen isteneket, kik köztetek vannak, és tisztítsátok meg magatokat, és változtassátok el öltözeteiteket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'És keljünk fel, és menjünk fel Béthelbe, hogy csináljak ott oltárt annak az Istennek, ki meghallgatott engem az én nyomorúságom napján, és velem volt az úton, a melyen jártam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Átadák azért Jákóbnak mind az idegen isteneket, kik nálok valának, és füleikből a függőket, és elásá azokat Jákób a cserfa alatt, mely Sekhem mellett vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'És elindulának. De Istennek rettentése vala a körűltök való városokon, és nem üldözék a Jákób fiait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Eljuta azért Jákób Lúzba, mely Kanaán földén van, azaz Béthelbe, ő maga és az egész sokaság, mely ő vele vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'És építe ott oltárt, és nevezé a helyet Él-Béthelnek, mivelhogy ott jelent meg néki az Isten, mikor az ő bátyja előtt fut vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'És meghala Débora, a Rebeka dajkája, és eltemeték Béthelen alól egy cserfa alatt, és nevezék annak nevét Allon-Bákhutnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Az Isten pedig ismét megjelenék Jákóbnak, mikor ez jöve Mésopotámiából, és megáldá őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'És monda néki az Isten: A te neved Jákób; de ne neveztessék többé a te neved Jákóbnak, hanem Izráel légyen neved. És nevezé nevét Izráelnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'És monda néki az Isten: Én vagyok a mindenható Isten, nevekedjél és sokasodjál, nép és népek sokasága légyen te tőled; és királyok származzanak a te ágyékodból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'És a földet, melyet adtam Ábrahámnak és Izsáknak, néked adom azt, utánad pedig a te magodnak adom a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'És felméne ő tőle az Isten azon a helyen, a hol vele szólott vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Jákób pedig emlékoszlopot állíta azon a helyen, a hol szólott vele, kőoszlopot; és áldozék azon italáldozattal, és önte arra olajat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'És nevezé Jákób a hely nevét, a hol az Isten szólott vala ő vele, Béthelnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'És elindúlának Béthelből, s mikor Efratától, hogy oda érjenek, már csak egy dűlőföldre valának, szűle Rákhel, és nehéz vala az ő szűlése.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'S vajudása közben monda néki a bába: Ne félj, mert most is fiad lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'És mikor lelke kiméne, mert meghala, nevezé nevét Benóninak, az atyja pedig nevezé őt Benjáminnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'És meghala Rákhel, és eltemetteték az Efratába (azaz Bethlehembe) vivő úton.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'És emlékoszlopot állíta Jákób az ő sírja fölött. Rákhel sírjának emlékoszlopa az mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Azután tovább költözék Izráel, és a Héder tornyán túl voná fel sátorát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Lőn pedig, mikor Izráel azon a földön lakozék, elméne Rúben, és hála Bilhával, az ő atyjának ágyasával, s meghallá Izráel. Valának pedig a Jákób fiai tizenketten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Lea fiai: Jákób elsőszülötte Rúben, azután Simeon, Lévi, Júda, Izsakhár és Zebulon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Rákhel fiai: József és Benjámin.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'A Rákhel szolgálójának Bilhának fiai: Dán és Nafthali.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'A Lea szolgálójának Zilpának fiai: Gád és Áser. Ezek a Jákób fiai, a kik születtek néki Mésopotámiában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'És eljuta Jákób Izsákhoz, az ő atyjához Mamréba, Kirját-Arbába, azaz Hebronba, a hol Ábrahám és Izsák tartózkodnak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Valának pedig Izsák napjai száz nyolczvan esztendő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'És kimúlék Izsák és meghala, és takaríttaték az ő eleihez vén korban, bételvén az élettel; és eltemeték őt az ő fiai, Ézsaú és Jákób.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Ez Ézsaúnak (azaz Edómnak) nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Ézsaú a Kananeusok leányai közűl vette vala feleségeit: Adát, a Khitteus Élonnak leányát; és Oholibámát, Anáhnak leányát, a ki Khivveus Czibhón leánya vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'És Boszmáthot, az Ismáel leányát, Nebajóthnak húgát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Szűlé pedig Adá Ézsaúnak Elifázt; és Boszmáth szűlé Rehuélt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'Oholibáma pedig szűlé Jehúst, Jahlámot és Kórét. Ezek az Ézsaú fiai, kik születtek néki Kanaán földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'És felvevé Ézsaú az ő feleségeit, az ő fiait, és az ő leányait, és minden házabeli lelket, minden juhait, barmait, és minden jószágát, melyet szerzett vala Kanaán földén, és elméne más országba, az ő atyjafiának Jákóbnak színe elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Mert az ő jószáguk több vala, semhogy együtt lakhattak volna, és tartózkodásuk földe nem bírja vala meg őket az ő nyájaik miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Letelepedék tehát Ézsaú a Széir hegyén. Ézsaú pedig az Edóm.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Ez Ézsaúnak az Edomiták atyjának nemzetsége a Széir hegyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Ezek Ézsaú fiainak nevei: Elifáz, Adának Ézsaú feleségének fia. Rehuél, Boszmáthnak Ézsaú feleségének fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Elifáznak fiai valának: Thémán, Omár, Czefó, Gahtám és Kenáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Thimna pedig Elifáznak, az Ézsaú fiának ágyasa vala, ki Elifáznak szűlé Amáleket. Ezek Adának, Ézsaú feleségének fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Ezek pedig a Rehuél fiai: Nakhath, Zerakh, Sammá, Mizzá. Ezek valának Boszmáthnak, Ézsaú feleségének fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Oholibámának pedig, Ézsaú feleségének, Anáh leányának, ki Czibhón leánya volt, ezek valának fiai, kiket szűle Ézsaúnak: Jéhus, Jahlám és Korakh.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Ezek Ézsaú fiainak fejedelmei: Elifáznak, Ézsaú elsőszülöttének fiai: Thémán fejedelem, Omár fejedelem, Czefó fejedelem, Kenáz fejedelem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'Korakh fejedelem, Gahtám fejedelem, Amálek fejedelem. Ezek Elifáztól való fejedelmek Edómnak országában; ezek Adá fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Rehuélnek pedig, az Ézsaú fiának fiai ezek: Nakhath fejedelem, Zerakh fejedelem, Sammá fejedelem, Mizzá fejedelem. Ezek Rehuéltől való fejedelmek Edóm országában. Ezek Boszmáthnak, Ézsaú feleségének fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Ezek pedig Oholibámának, Ézsaú feleségének fiai: Jéhus fejedelem, Jahlám fejedelem, Korakh fejedelem. Ezek Oholibámától, Anáh leányától, Ézsaú feleségétől való fejedelmek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Ezek Ézsaú fiai, és ezek azoknak fejedelmei; ez Edóm.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'A Horeus Széirnek fiai, kik ama földön laknak vala ezek: Lótán, Sóbál, Czibhón, Anáh.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Disón, Eczer, Disán, Ezek a Horeusok fejedelmei, Széirnek fiai Edóm országában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Lótánnak pedig fiai voltak: Hóri, Hémám, és Lótánnak húga, Timna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Sóbálnak fiai ezek: Halván, Mánakháth, Hébál, Sefó, Onám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Czibhónnak pedig fiai ezek: Aja és Anáh, az az Anáh, ki meleg forrásokat talált a pusztában, mikor atyjának Czibhónnak szamarait legelteté.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Anáhnak fiai ezek: Disón és Oholibáma Anáhnak leánya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Disónnak fiai ezek: Hemdán, Esbán, Ithrán, Kherán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Eczernek fiai ezek: Bilhán, Zahaván, Hakán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Disánnak fiai ezek: Húcz és Arán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'A Horeusok közűl való fejedelmek pedig ezek: Lótán fejedelem, Sóbál fejedelem, Czibhón fejedelem, Anáh fejedelem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'Disón fejedelem, Eczer fejedelem, Disán fejedelem. Ezek a Horeusok közűl való fejedelmek az ő fejedelemségök szerint, Széir tartományában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Ezek pedig a királyok, kik uralkodtak Edóm földén minekelőtte Izráel fiai között király uralkodott volna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Király vala Edómban Bela, Behor fia, s az ő városának neve Dinhába vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'És meghala Bela, uralkodék helyette Jóbáb, Zerakh fia, ki Boczrából való volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'És meghala Jóbáb, és uralkodék helyette a Témán földéből való Khusám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'És meghala Khusám és uralkodék helyette Hadád, a Bédád fia, a ki megveré a Midiánitákat a Moáb mezején; az ő városának neve pedig Hávit vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'És meghala Hadád és uralkodék helyette a Masrekából való Szamlá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'És meghala Szamlá és uralkodék helyette Saul, a folyóvíz mellett való Rékhobóthból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'És meghala Saul és uralkodék helyette Báhál-Khanán, Akhbór fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'És meghala Báhál-Khanán, Akhbór fia, és uralkodék helyette Hadár; és az ő városának neve Pahu, az ő feleségének pedig neve Mehetábéel, a ki Mézaháb leányának Matrédnak leánya vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Ezek pedig az Ézsaú nemzetségéből való fejedelmek nevei, az ő családjok, helyök, és nevök szerint: Timná fejedelem, Halvá fejedelem, Jetéth fejedelem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'Oholibámá fejedelem, Éla fejedelem, Pinon fejedelem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'Kenáz fejedelem, Thémán fejedelem, Mibczár fejedelem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'Magdiél fejedelem, Hirám fejedelem. Ezek Edóm fejedelmei az ő lakások szerint, az ő örökségök földén. Ézsaú az Edómiták atyja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Jákób pedig lakozék az ő atyja bujdosásának földén, Kanaán földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Ezek a Jákób nemzetségének dolgai: József tizenhét esztendős korában az ő bátyjaival együtt juhokat őriz vala, bojtár vala Bilhának és Zilpának az ő atyja feleségeinek fiai mellett, és József rossz híreket hord vala felőlük az ő atyjuknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Izráel pedig minden fiánál inkább szereti vala Józsefet, mivelhogy vén korában nemzette vala őt; és czifra ruhát csináltat vala néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Mikor pedig láták az ő bátyjai, hogy atyjuk minden testvére közt őt szereti legjobban, meggyűlölik vala, és jó szót sem bírnak vala hozzá szólani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'És álmot álmodék József és elbeszélé az ő bátyjainak; és azok annál inkább gyűlölik vala őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Mert monda nékik: Hallgassátok meg, kérlek, ezt az álmot, melyet álmodtam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Ímé kévéket kötünk vala a mezőben, és ímé az én kévém felkele és felálla; a ti kévéitek pedig körűlállanak, és az én kévém előtt meghajolnak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'És mondának néki az ő bátyjai: Avagy király akarsz-é lenni felettünk? Vagy uralkodni akarsz-é rajtunk? S annál is inkább gyűlölik vala őt álmáért és beszédéért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Más álmot is álmodék, és elbeszélé azt az ő bátyjainak, mondván: ímé megint álmot álmodtam; ímé a nap és a hold, és tizenegy csillag meghajol vala én előttem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'S elbeszélé atyjának és bátyjainak, és az ő atyja megdorgálá őt, mondván néki: Micsoda álom az a melyet álmodtál? Avagy elmegyünk-é, én és a te anyád és atyádfiai, hogy meghajtsuk magunkat te előtted a földig?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Irígykednek vala azért reá az ő bátyjai; az ő atyja pedig elméjében tartja vala e dolgot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Mikor pedig az ő bátyjai elmenének Sikhembe, hogy az ő atyjok juhait őrizzék;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'Monda Izráel Józsefnek: A te bátyáid avagy nem Sikhemben legeltetnek-é? Jöszte, és én hozzájok küldelek téged. Ő pedig monda: Ímhol vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'És monda néki: Menj el, nézd meg, hogy s mint vagynak a te bátyáid és a juhok, s hozz hírt nékem. Elküldé tehát őt Hebron völgyéből, és méne Sikhembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Előtalálá pedig őt egy ember, mikor a mezőben bolyong vala, és megkérdé őt az az ember, mondván: Mit keressz?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'És monda: Az én bátyáimat keresem, kérlek, mondd meg nékem, hol legeltetnek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'És monda az ember: Elmentek innen, mert hallám, hogy mondák: Menjünk Dóthánba. Elméne azért József az ő bátyjai után, és megtalálá őket Dóthánban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Mikor távolról megláták, minekelőtte közel ért volna hozzájok, összebeszélének, hogy megölik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'És szólának egymás között: Ímhol jő az álomlátó!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Most hát jertek öljük meg őt, és vessük őt valamelyik kútba; és azt mondjuk, hogy fenevad ette meg, és meglátjuk, mi lesz az ő álmaiból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Meghallá pedig Rúben és megmenté őt kezökből, és mondá: Ne üssük őt agyon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'És mondá nékik Rúben: Ne ontsatok vért, vessétek őt ebbe a kútba, a mely itt a pusztában van, de kezet ne vessetek reá. Azért, hogy megszabadítsa őt kezökből, hogy visszavigye atyjához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'És lőn, a mint oda ére József az ő bátyjaihoz, letépték Józsefről az ő felső ruháját, a czifra ruhát, mely rajta vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'És megragadák őt és beleveték a kútba; a kút pedig üres vala, nem vala víz benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Azután leűlének kenyerezni, és felemelék szemeiket, és láták, hogy ímé egy Ismáelita karaván jő vala Gileádból, és azoknak tevéi visznek vala fűszerszámot, balzsamot és mirhát, menvén, hogy alávigyék Égyiptomba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'És monda Júda az ő atyjafiainak: Mi haszna, ha megöljük a mi atyánkfiát, és eltitkoljuk az ő vérét?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Jertek adjuk el őt az Ismáelitáknak, és ne tegyük reá kezünket, mert atyánkfia, vérünkből való ő. És hallgatának rá az ő atyjafiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'És menének arra Midiánita kereskedő férfiak, és kivonák és felhozák Józsefet a kútból, és eladák Józsefet az Ismáelitáknak húsz ezüstpénzen: azok pedig elvivék Józsefet Égyiptomba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'És visszatére Rúben a kúthoz, és ímé József nem vala a kútban, és megszaggatá ruháit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'És megtére az ő atyjafiaihoz, és monda: Nincsen a gyermek, és én, merre menjek én?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Akkor vevék a József felső ruháját, és leölének egy kecskebakot, és belemárták a felső ruhát a vérbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'És elküldék a czifra ruhát, és elvivék atyjokhoz és mondának: Ezt találtuk, ismerd meg, fiad ruhája-é vagy nem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'És megismeré azt, és monda: Fiam felső ruhája ez, fenevad ette meg őt, bizony széllyelszaggatta Józsefet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'És megszaggatá Jákób ruháit, és zsákba öltözék és gyászolá az ő fiát sokáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Felkelének pedig minden ő fiai, és minden ő leányai, hogy vígasztalják őt, de nem akara vígasztalódni, hanem monda: Sírva megyek fiamhoz a sírba; és siratá őt az atyja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'A Midiániták pedig eladák őt Égyiptomba Pótifárnak, a Faraó főemberének, a testőrök főhadnagyának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'És lőn abban az időben, hogy Júda elméne az ő atyjafiaitól, és betére egy Adullámbeli férfiúhoz, kinek neve Khira vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'És meglátá ott Júda egy Súah nevű Kanaánbeli férfiúnak leányát, és elvevé azt, és beméne hozzá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'És az fogada méhében és szűle fiat, és nevezé nevét Hérnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'És ismét fogada méhében, s fiat szűle, és nevezé nevét Ónánnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Még egyszer szűle fiat, és nevezé nevét Sélának, és mikor azt szűlé, Khezibben vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'És vőn Júda az ő elsőszülött fiának Hérnek feleséget, ennek neve Thámár vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'De Hér, Júdának elsőszülött fia gonosz vala az Úr szemei előtt, és megölé őt az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'És monda Júda Ónánnak: Eredj be a te bátyád feleségéhez, és vedd feleségűl mint sógor, és támaszsz magot bátyádnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Ónán pedig tudja vala, hogy a magzat nem lesz az övé, azért valamikor az ő bátyja feleségéhez bemegy vala, földre vesztegeti vala el a magot, hogy bátyjának magot ne támaszszon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'És gonoszságnak tetszék az Úr szemei előtt, a mit cselekeszik vala, annakokáért megölé őt is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'És monda Júda Thámárnak, az ő menyének: Maradj özvegyen addig a te atyád házában, míg az én fiam Séla felnevekedik. Mert így gondolkodik vala: Netalán ez is meghal, mint az ő bátyjai. Elméne azért Thámár, és marada az ő atyja házában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Sok idő múlva meghala Súa leánya, a Júda felesége. Júda pedig megvígasztalódék és elméne az ő juhainak nyírőihez, barátjával az Adullámbeli Khirával, Thimnába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Hírűl adák pedig Thámárnak mondván: Ím a te ipad Thimnába megy juhainak nyírésére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Leveté azért magáról özvegyi ruháját, elfátyolozá és beburkolá magát, és leűle Enajim kapujába, mely a Thimnába vezető úton van; mert látja vala, hogy felnevekedék Séla, és még sem adák őt annak feleségűl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Meglátá pedig őt Júda, és tisztátalan személynek gondolá, mivelhogy befedezte vala orczáját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'És hozzá tére az útra és monda: Engedd meg kérlek, hogy menjek be te hozzád, mert nem tudja vala, hogy az ő menye az. Ez pedig monda: Mit adsz nékem ha bejösz hozzám?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'És felele: Küldök néked az én nyájamból egy kecskefiat. És az monda: Adsz-é zálogot, míg megküldöd?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'És monda: Micsoda zálogot adjak néked? És monda: Gyűrűdet, gyűrűd zsinórját és pálczádat, mely kezedben van. Oda adá azért néki, és beméne hozzá, és teherbe ejté.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Azután felkele és elméne, és leveté magáról a fátyolt; és felvevé az ő özvegyi ruháját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'És megküldé Júda a kecskefiat az ő Adullámbeli barátjától, hogy visszavegye a zálogot az asszonytól, de nem találá azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'És megkérdé a helység férfiait, mondván: Hol van az a felavatott parázna nő, a ki Enajim mellett az útfélen vala? És azok mondának: Nem volt erre felavatott parázna nő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Visszatére tehát Júdához, és monda: Nem találám azt meg, a helység lakosai is azt mondák: Nem volt erre felavatott parázna nő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'És monda Júda: Tartsa magának, hogy csúffá ne legyünk; ímé én megküldöttem volt ezt a kecskefiat, te pedig nem találtad meg őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'És lőn mintegy három hónap múlva, jelenték Júdának, mondván: Thámár a te menyed paráználkodott, és ímé terhes is a paráznaság miatt. És monda Júda: Vigyétek ki őt, és égettessék meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Mikor pedig kivitetnék, elkülde az ő ipához, mondván: Attól a férfiútól vagyok terhes, a kiéi ezek. És mondá: Ismerd meg, kérlek, kié e gyűrű, e zsinór, és e pálcza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'És megismeré Júda és monda: Igazabb ő nálamnál, mert bizony nem adám őt az én fiamnak Sélának; de nem ismeré őt Júda többé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'És lőn az ő szűlésének idején, ímé kettősök valának az ő méhében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'És lőn, hogy szűlése közben az egyik kinyújtá kezét, és fogá a bába és veres fonalat köte reá, mondván: Ez jött ki először.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'De lőn, hogy a mikor visszavoná kezét, ímé az ő testvére jöve ki. És mondá a bába: Hogy törtél te magadnak rést? Azért nevezé nevét Pérecznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'És utána kijöve az ő testvére kinek veres fonál vala kezén; és nevezé nevét Zerákhnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'József pedig aláviteték Égyiptomba és megvevé őt az Ismáelitáktól, kik őt oda vitték vala, egy égyiptomi ember Pótifár, a Faraó főembere, a testőrök főhadnagya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'És az Úr Józseffel vala, és szerencsés ember vala és az ő égyiptomi urának házában vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Látá pedig az ő ura, hogy az Úr van ő vele, és hogy valamit cselekszik, az Úr mindent szerencséssé tesz az ő kezében:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'Kedvessé lőn azért József az ő ura előtt, és szolgál vala néki; és háza felvigyázójává tevé, és mindenét, a mije vala, kezére bízá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'És lőn az időtől fogva, hogy házának és a mije volt, mindenének gondviselőjévé tevé, megáldá az Úr az égyiptomi embernek házát Józsefért; és az Úr áldása vala mindenen, a mije csak volt a házban és a mezőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Mindent azért valamije vala József kezére bíza; és semmire sem vala gondja mellette, hanem ha az ételre, melyet megeszik vala. József pedig szép termetű és szép arczú vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'És lőn ezek után, hogy az ő urának felesége Józsefre veté szemeit, és monda: Hálj velem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Ő azonban vonakodék s monda az ő ura feleségének: Ímé az én uramnak én mellettem semmi gondja nincs az ő háza dolgaira, és a mije van, mindenét az én kezemre bízá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'Senki sincs nálamnál nagyobb az ő házában; és tőlem semmit sem tiltott meg, hanem csak téged, mivelhogy te felesége vagy; hogy követhetném hát el ezt a nagy gonoszságot és hogyan vétkezném az Isten ellen?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'És lőn, hogy az asszony mindennap azt mondogatá Józsefnek, de ő nem hallgata reá, hogy vele háljon és vele egyesüljön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Lőn azért egy napon, hogy valami dolgát végezni a házba beméne, és a háznép közűl senki sem vala ott benn a házban,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'És megragadá őt ruhájánál fogva, mondván: Hálj velem. Ő pedig ott hagyá ruháját az asszony kezében és elfuta és kiméne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'És mikor látja vala az asszony, hogy az a maga ruháját az ő kezében hagyta, és kifutott:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'Összehívá a háznépet és szóla hozzájuk, mondván: Lássátok, héber embert hozott hozzánk, hogy megcsúfoljon bennünket. Bejött hozzám, hogy velem háljon, s én fenszóval kiálték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'És lőn, a mint hallja vala, hogy fenszóval kezdék kiáltani, ruháját nálam hagyá és elfuta és kiméne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Megtartá azért az ő ruháját magánál, míg az ő ura haza jöve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'S ilyen szókkal szóla hozzá, mondván: Bejöve hozzám a héber szolga, a kit ide hoztál, hogy szégyent hozzon reám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'És mikor fenszóval kezdtem kiáltani, ruháját nálam hagyá és kifuta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'És lőn, a mint hallja az ő ura az ő feleségének beszédeit, melyeket néki beszélt, mondván: Ilyesmiket tett velem a te szolgád; haragra gerjede.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'Vevé azért Józsefet az ő ura és veté őt a tömlöczbe, melyben a király foglyai valának fogva, és ott vala a tömlöczben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'De az Úr Józseffel vala, és kiterjeszté reá az ő kegyelmességét és kedvessé tevé őt a tömlöcztartó előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'És a tömlöcztartó mind azokat a foglyokat, kik a tömlöczben valának, József kezébe adá, úgyhogy a mi ott történik vala, minden ő általa történék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'És semmi gondja nem vala a tömlöcztartónak azokra, a melyek keze alatt valának, mivelhogy az Úr vala Józseffel, és valamit cselekeszik vala, az Úr szerencséssé teszi vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'És lőn ezekután, hogy az égyiptomi király pohárnoka és sütőmestere vétkezének az ő urok ellen, az égyiptomi király ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Megharaguvék azért a Faraó az ő két főemberére, a főpohárnokra, és a fősütőmesterre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'És fogságba vetteté azokat a testőrök főhadnagyának házában levő tömlöczbe, arra a helyre, ahol fogva vala József.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'A testőrök főhadnagya pedig Józsefet rendelé melléjük és szolgála nékik. És jó ideig valának fogságban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'És az égyiptomi király pohárnoka és sütőmestere, a kik a tömlöczben fogva valának, látának álmot mindketten; mindegyik külön álmot, azon egy éjjel, mindegyik az ő álmának értelme szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'És beméne hozzájok József reggel, látá, hogy ímé bánkódnak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'És megkérdé a Faraó főembereit, a kik az ő ura házánál vele együtt fogva valának, mondván: Miért oly komor ma a ti orczátok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'És mondának néki: Álmot láttunk és nincsen a ki megfejtse azt. És monda nékik József: A megfejtés nem Isten dolga-é? mondjátok el, kérlek, nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Elbeszélé azért a főpohárnok az ő álmát Józsefnek, és monda néki: Álmomban ímé egy szőlőtő vala előttem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'És a szőlőtőn három szál vessző vala, s alighogy bimbózék, virágozék, és gerézdjei megérlelék a szőlőszemeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'A Faraó pohara pedig az én kezemben vala, és én vevém a szőlőszemeket és facsarám a Faraó poharába, és adom vala a poharat a Faraó kezébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'És monda néki József: Ez annak a megfejtése: a három vesszőszál, három nap.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Harmadnap múlva a Faraó felmagasztalja a te fejedet, és visszahelyez téged hivatalodba, és adod a Faraó kezébe az ő poharát, az elébbi tiszted szerint, mikor az ő pohárnokja valál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Csakhogy azután megemlékezzél rólam, mikor néked jól lesz dolgod, és cselekedjél, kérlek, irgalmasságot velem, emlékezzél meg rólam a Faraó előtt és szabadíts meg engem e házból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'Mert lopva hoztak el engem a héberek földéről, és itt sem cselekedtem semmit, hogy a tömlöczbe vessenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'És látá a fősütőmester, hogy jól magyaráz vala és monda Józsefnek: Álmodtam én is, hogy ímé három kosár kalács vala fejemen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'A felső kosárban pedig valának a Faraónak mindenféle süteményei, és a madarak eszik vala azokat a kosárból, az én fejemről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'És felele József és monda: Ez annak a magyarázatja: a három kosár, három nap.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Harmadnap múlva fejedet véteti a Faraó és fára akasztat fel téged, és a madarak leeszik rólad húsodat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'S lőn harmadnapon a Faraó születése napja, és vendégséget szerze minden ő szolgáinak, s akkor a főpohárnokot és a fősütőmestert is fölvevé szolgái közé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'És a főpohárnokot visszahelyezé pohárnokságába, és nyújtotta a poharat a Faraó kezébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'A fősütőmestert pedig felakasztatá; a miképen magyarázta vala nékik József.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'És nem emlékezék meg a főpohárnok Józsefről, hanem elfelejtkezék róla.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Lőn pedig két esztendő múlván, hogy a Faraó álmot láta, s ímé áll vala a folyóvíz mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'És ímé a folyóvízből hét szép és kövér tehén jő vala ki, és legel vala a nádasban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'S ímé azok után más hét tehén jő vala ki a folyóvízből, rútak és ösztövérek, és oda állanak vala ama tehenek mellé a folyóvíz partján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'És elnyelék a rút és ösztövér tehenek a hét szép és kövér tehenet; és felserkene a Faraó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'És elaluvék és másodszor is álmot láta, és ímé hét gabonafej nevekedik vala egy száron, mind teljes és szép.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'És ímé azok után hét vékony s keleti széltől kiszáradt gabonafej nevekedik vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'És elnyelék a vékony gabonafejek a hét kövér és teljes gabonafejet. És felserkene a Faraó, és ímé álom vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Reggelre kelvén, nyugtalankodék lelkében, elkülde azért és egybehívatá Égyiptom minden jövendőmondóját, és minden bölcsét és elbeszélé nékik a Faraó az ő álmát, de senki sem vala, ki azokat megmagyarázta volna a Faraónak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Szóla azért a főpohárnok a Faraónak, mondván: Az én bűneimről emlékezem e napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'A Faraó megharagudt vala az ő szolgáira, és fogságba vettetett vala engem a testőrök főhadnagyának házába, engem és a fősütőmestert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'És álmot látánk egy éjjel, én is, az is; mindegyikünk a maga álmának értelme szerint álmoda.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'És vala velünk ott egy héber ifjú, a testőrök főhadnagyának szolgája; elbeszéltük vala néki, és ő megfejté nékünk a mi álmainkat; mindegyikünknek az ő álma szerint fejté meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'És lőn, hogy a miképen megfejté nékünk, úgy lőn: engem visszahelyeze hívatalomba, amazt pedig felakasztatá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Elkülde azért a Faraó és hívatá Józsefet, és hamarsággal kihozák őt a tömlöczből, és megborotválkozék, ruhát válta és a Faraóhoz méne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'És monda a Faraó Józsefnek: Álmot láttam és nincs a ki megmagyarázza azt: Én pedig azt hallottam rólad beszélni, hogy ha meghallod az álmot, meg is magyarázod azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'És felele József a Faraónak, mondván: Nem én, Isten jelenti meg, a mi a Faraónak javára van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Monda azért a Faraó Józsefnek: Álmomban ímé állok vala a folyóvíz partján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'És ímé a folyóvízből hét kövér és szép tehén jő vala ki, és legel vala a nádasban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'S ímé azok után más hét tehén jő vala ki, nagyon ösztövérek, rútak és hitványak; egész Égyiptom földén nem láttam azokhoz hitványságra hasonlókat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'És elnyelék az ösztövér és rút tehenek, az elébbi hét kövér tehenet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'És azok gyomrukban valának, de nem tetszik vala meg, hogy gyomrukban volnának, mert külsejök oly rút vala, mint az előtt. És felserkenék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'És láttam álmomban, és ímé hét gabonafej nevekedik vala egy száron, mind teljes és szép.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'És ímé hét összeaszott, vékony, keleti széltől kiszáradt gabonafej nevekedik vala azok után,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'És elnyelék a vékony gabonafejek a hét szép gabonafejet. És elmondám az írástudóknak, de senki sincs, a ki megmagyarázza nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'És monda József a Faraónak: A Faraó álma egy és ugyanaz; a mit Isten cselekedni akar, azt jelentette meg a Faraónak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'A hét szép tehén, hét esztendő, a hét szép gabonafej az is hét esztendő; az álom egy és ugyanaz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'A hét ösztövér és rút tehén pedig, melyek amazok után jöttek ki, az is hét esztendő, és a hét vékony, keleti széltől kiszáradt gabonafej, az az éhségnek hét esztendeje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'Ez az a mit mondék a Faraónak, hogy a mit Isten cselekedni akar, megmutatta a Faraónak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Ímé hét esztendő jő, és nagy bőség lesz egész Égyiptomban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'Azok után pedig következik az éhség hét esztendeje, s minden bőséget elfelejtenek Égyiptom földén, és megemészti az éhség a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'És nem ismerszik meg az elébbi bőség e földön az utána következő éhség miatt, mert igen nagy lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Hogy pedig a Faraó álma kettős, kétszeres vala, onnan van, mert Istennél elvégezett dolog ez, és siet az Isten azt véghez vinni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Most azért szemeljen ki a Faraó egy értelmes és bölcs férfit, és tegye Égyiptom földén gondviselővé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'Cselekedje ezt a Faraó és rendeljen tiszttartókat az országnak, és szedjen ötödöt Égyiptom földén a hét bő esztendőben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'És takarítsák be a következő jó esztendők minden termését, és gyűjtsenek gabonát a Faraó keze alá, élelműl a városokban, és tartsák meg,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'És legyen az élelem tartalékban az ország számára az éhség hét esztendejére, melyek elkövetkeznek Égyiptom földére, hogy el ne vesszen e föld az éhség miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'És tetszék e beszéd a Faraónak és minden ő szolgáinak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Monda azért a Faraó az ő szolgáinak: Találhatnánk-é ehhez hasonló férfit, a kiben az Isten lelke van?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'És monda a Faraó Józsefnek: Mivelhogy Isten mind ezeket néked jelentette meg, nincs hozzád fogható értelmes és bölcs ember.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Te légy az én házamon főgondviselő, és minden népem a te szavadra hallgasson, csak a királyiszék tesz engem nálad nagyobbá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Monda továbbá a Faraó Józsefnek: Ímé fejedelemmé tettelek az egész Égyiptom földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'És levevé a Faraó a maga gyűrűjét kezéről, és adá azt József kezére; és felöltözteté őt drága gyolcs ruhába, és aranylánczot tőn az ő nyakába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'És meghordoztatá őt az ő második szekerén, és kiáltják vala ő előtte: Térdet hajtsatok! Így tevé őt fejedelemmé az egész Égyiptom földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'És monda a Faraó Józsefnek: Én vagyok a Faraó; de te nálad nélkül senki se kezét, se lábát fel ne emelhesse egész Égyiptom földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'És nevezé a Faraó József nevét Czafenát-Pahneákhnak, és adá néki feleségűl Aszenáthot, Potiferának On papjának leányát. És kiméne József Égyiptom földére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'József pedig harmincz esztendős vala, mikor a Faraó előtt, az égyiptomi király előtt álla. Kiméne tehát József a Faraó elől, és bejárá az egész Égyiptom földét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'És a föld a hét bő esztendő alatt tele marokkal ontá a termést.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'És összegyűjté a hét esztendőnek minden eleségét, mely vala Égyiptom földén, és a városokba takarítá az élelmet, minden városba a körülte levő határ élelmét takarítá be.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'És felhalmozá József a gabonát, mint a tenger fövénye, igen sokat, annyira, hogy megszűntek azt számba venni, mivelhogy száma nem vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Józsefnek pedig születék két fia az éhség esztendejének eljötte előtt, kiket szűle néki Aszenáth, Potiferának az On papjának leánya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'És nevezé József az elsőszülöttnek nevét Manassénak: mert úgymond, elfelejteté én velem Isten minden én vesződségemet, és az én atyámnak egész házát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'A másodiknak nevét pedig nevezé Efraimnak: mivel, úgymond, megszaporított engem Isten az én nyomorúságomnak földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Eltele tehát a bőség hét esztendeje, a mely vala Égyiptomnak földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'És elkezdődék az éhség hét esztendeje, mint megmondotta vala József; és lőn éhség minden országban; de Égyiptom földén mindenütt vala kenyér.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'De megéhezék egész Égyiptom földe is, és kenyérért kiált vala a nép a Faraóhoz. – Monda pedig a Faraó mind az Égyiptombelieknek: Menjetek Józsefhez, és a mit mond néktek, azt míveljétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'És az éhség mind az egész földön vala. Akkor mind megnyitá József a gabonás házakat, és árulja vala az Égyiptombelieknek; mert nagyobbodik vala az éhség Égyiptom földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'És mind az egész föld Égyiptomba megy vala Józsefhez gabonát venni; mert nagy vala az éhség az egész földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'És látá Jákób, hogy van gabona Égyiptomban és monda Jákób az ő fiainak: Mit néztek egymásra?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'És monda: Ímé hallom hogy Égyiptomban van gabona; menjetek le oda, és vegyetek onnan nékünk gabonát, hogy éljünk és ne haljunk meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Leméne azért Józsefnek tíz bátyja Égyiptomba gabonát venni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'De Benjámint a József öcscsét nem bocsátá el Jákób az ő bátyjaival; mert mondá: Netalán veszedelem érhetné.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'Elmenének tehát Izráel fiai gabonát venni az oda menőkkel együtt, mert éhség vala Kanaán földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'József pedig az ország kormányzója vala, és ő árulja vala a gabonát a föld minden népének. Eljutának azért a József bátyjai, és arczczal a földre borúlának ő előtte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Amint meglátá József az ő bátyjait, megismeré őket, de idegennek mutatá magát hozzájok, és kemény beszédekkel szóla nékik, mondván: Honnan jöttetek? Azok pedig mondának: Kanaán földéről jöttünk eleséget venni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Megismeré pedig József az ő bátyjait, de azok nem ismerék meg őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'És megemlékezék József az álmokról, a melyeket azok felől álmodott vala. És monda nékik: Kémek vagytok ti, kik azért jöttetek, hogy az ország védetlen részeit meglássátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'És mondának néki: Nem uram, hanem eleséget venni jöttek a te szolgáid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Mi mindnyájan egy ember fiai vagyunk: igaz emberek vagyunk. Soha nem voltak kémek a te szolgáid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Ismét monda: Nem úgy van, hanem azért jöttetek, hogy az ország védetlen részeit meglássátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Amazok mondának: Mi, te szolgáid, tizenketten vagyunk testvérek, egy embernek fiai, Kanaán földén; és ímé legkisebbikünk most atyánknál van, egyikünk pedig nincsen meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'József pedig monda nékik: Úgy van a mint néktek mondám: kémek vagytok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Ezzel lesztek próbára téve: Úgy éljen a Faraó, hogy ki nem mentek innen, míg ide nem jő a ti legkisebbik atyátokfia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Küldjetek el közűletek egyet, hogy hozza ide testvérteket; ti pedig fogva lesztek. Így lesz próbára téve beszédetek, hogy igaz járatban vagytok-é vagy nem? Úgy éljen a Faraó, hogy ti kémek vagytok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Annakokáért fogságban tartá őket harmadnapig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Harmadnap pedig monda nékik József: Ezt cselekedjétek, hogy éljetek; az Istent én is félem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Ha igaz emberek vagytok, maradjon fogva egyik testvéretek a ti tömlöczötökben, ti pedig menjetek el, vigyetek gabonát házaitok szükségére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'Legkisebbik atyátokfiát pedig hozzátok én hozzám, akkor igazolva lesznek beszédeitek és nem haltok meg. És aképen cselekedének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'És mondának egymásnak: Bizony vétkeztünk mi a mi atyánkfia ellen, a kinek láttuk lelki szorongását, mikor nékünk könyörög vala, de nem hallgattunk reá; azért következett reánk ez a nyomorúság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Rúben pedig felele nékik, mondván: Avagy nem mondtam-é néktek, hogy ne vétkezzetek a gyermek ellen, de ti nem hallgattatok reám. És ímé vérét is keresik rajtunk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'És nem tudják vala ők, hogy József érti őket, mert tolmács vala közöttük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'És elfordula tőlök és síra: Azután hozzájok fordula és szóla nékik, és visszatartá közűlök Simeont, és szemök láttára megkötözteté őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'És parancsola József, hogy töltsék meg edényeiket gabonával, és tegyék vissza pénzöket mindeniknek az ő zsákjába, és hogy adjanak nékik enni valót az útra; és így cselekedének velök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'És felveték gabonájokat szamaraikra és elmenének onnan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'És egyik kioldá zsákját, hogy abrakot adjon szamarának a szálláson és meglátá az ő pénzét, hogy ímé zsákja szájában van az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'És monda az ő atyjafiainak: Visszatették az én pénzemet, és ímé zsákomban van. Akkor megrettene szívök, és remegve mondának egymásnak: Micsoda ez, a mit Isten cselekedett velünk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'És eljutának atyjokhoz Jákóbhoz Kanaán földére és mindazt elbeszélék néki a mi velök történt vala, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'Az a férfiú, annak a földnek ura, keményen szóla nékünk, és úgy bánt velünk, mintha az országot kémleltük volna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'És mondánk néki: Igaz emberek vagyunk, soha nem voltunk mi kémek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Tizenketten vagyunk atyafiak, a mi atyánknak fiai, egyikünk nincs meg, legkisebbikünk pedig most atyánkkal van Kanaán földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'És monda nékünk az a férfiú, annak a földnek ura: Erről ismerem meg, hogy igaz emberek vagytok: egyik atyátokfiát hagyjátok nálam, a házaitok szükségére valót vigyétek, és menjetek el;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'És hozzátok hozzám a ti legkisebbik atyátokfiát, akkor megtudom, hogy nem vagytok kémek, hanem igaz emberek; akkor visszaadom néktek a ti atyátokfiát, és ebben az országban kereskedhettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'És lőn a mint zsákjaikat kiüresíték, ímé az ő csomó pénze mindeniknek zsákjában vala. A mint látták az ő csomó pénzeiket ők és az ő atyjok, megfélemlének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'És monda nékik az ő atyjok Jákób: Megfosztotok engem gyermekeimtől; József nincsen, Simeon sincsen. Benjámint is elviszitek? mindez engem ér!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Akkor szóla Rúben az ő atyjának, mondván: az én két fiamat öld meg, ha meg nem hozom őt néked. Bízd az én kezemre őt, és én visszahozom néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Az pedig monda: Nem megy le oda az én fiam ti veletek, mert az ő bátyja megholt és ő maga maradt meg; ha veszedelem érné őt az úton, a melyen elmentek, ősz fejemet búba borítva bocsátanátok le a koporsóba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Az éhség pedig elhatalmazott vala az országon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'És lőn mikor fogytán vala az eleség, melyet Égyiptomból hoztak vala, monda nékik az ő atyjok: Menjetek el ismét, vegyetek nékünk egy kevés eleséget.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'És felele néki Júda, mondván: Erősen fogadkozék az a férfiú, mondván: Színem elé ne kerűljetek, ha veletek nem lesz a ti atyátokfia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Ha azért elbocsátod velünk a mi öcsénket, elmegyünk, és veszünk néked eleséget;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'Ha pedig el nem bocsátod, nem megyünk, mert az a férfiú megmondá nékünk: Színem elé ne kerűljetek, ha a ti atyátokfia veletek nem lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'És monda Izráel: Miért cselekedtetek gonoszul velem, hogy megmondtátok annak a férfiúnak, hogy még van egy öcsétek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Azok pedig mondának: Nagyon tudakozódék az a férfiú felőlünk és nemzetségünk felől, mondván: Él-é még atyátok? van-é még testvéretek? És mi kérdéseihez képest feleltünk néki. Avagy tudhattuk-é mi, hogy azt mondja: Hozzátok ide a ti atyátokfiát?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'És monda Júda Izráelnek, az ő atyjának: Bocsásd el azt a fiút én velem, és mi azonnal felkelünk és elmegyünk, hogy éljünk és meg ne haljunk se mi, se te, se a mi gyermekeink.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Én leszek kezes érette, az én kezemből kérd elő. Ha vissza nem hozom őt hozzád, és elődbe nem állítom őt, mind éltig bűnös legyek előtted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Bizony ha nem késlekedünk vala, ez ideig már kétszer is megjöhettünk volna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'És monda nékik Izráel az ő atyjok: Ha csakugyan így kell lenni, akkor ezt cselekedjétek: Vegyetek e föld válogatott gyümölcseiből a ti edényeitekbe, és vigyetek ajándékot annak a férfiúnak; egy kevés balzsamot, egy kevés mézet, fűszerszámokat, mirhát, diót, mandulát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Pénzt pedig két annyit vigyetek magatokkal, sőt a mely pénzt meghoztatok a ti zsákjaitok szájában, azt is vigyétek vissza magatokkal, talán tévedés ez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Öcséteket is vegyétek, keljetek fel és menjetek vissza ahhoz a férfiúhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'A mindenható Isten pedig engedje, hogy kedvet találjatok annál a férfiúnál, és bocsássa vissza ti veletek a másik atyátokfiát, és Benjámint. Én pedig ha megfosztottnak kell lennem, hadd legyek megfosztva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Vevék azért a férfiak azt az ajándékot, és vevének kétannyi pénzt az ő kezökbe, és Benjámint, és felkelének és alámenének Égyiptomba, és megállának József előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'A mint meglátá József ő velök Benjámint, monda az ő háza gondviselőjének: Vidd be azokat az embereket a házba, és ölj barmot, s készítsd el, mert velem ebédelnek ez emberek ma délben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'És az a férfiú aképen cselekedék, amint József parancsolta vala, és bevivé az a férfiú azokat az embereket a József házába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'És megfélemlének azok az emberek, a miért bevivék őket a József házába, és mondának: A pénzért hozattatánk ide be, mely először a mi zsákjainkba tétetett volt, hogy reánk rohanjon, megtámadjon és minket rabszolgákká tegyen a mi szamarainkkal együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'És járulának József házának gondviselőjéhez, és szólának néki a ház ajtajában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'És mondának: Kérünk uram! Ennekelőtte alájöttünk vala eleséget venni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'És lőn mikor éjjeli szállásra jutánk és kioldjuk vala a mi zsákjainkat: ímé mindenikünknek pénze az ő zsákjának szájában vala, tulajdon pénzünk teljes mértéke szerint; és visszahoztuk azt magunkkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'De más pénzt is hoztunk le magunkkal eleséget venni; nem tudjuk ki tette a mi pénzünket zsákjainkba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'És monda: Legyetek békén, ne féljetek; a ti Istentek és a ti atyátok Istene adta néktek azt a kincset zsákjaitokba; pénzetek az én kezemhez jutott. És kihozá hozzájok Simeont.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Bevivé azután a férfiú azokat az embereket a József házába, és vizet hozata, és megmosák lábaikat, és abrakot is ada az ő szamaraiknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Ők pedig elkészíték az ajándékot mire József délben megjöve; mert megértették vala, hogy ott ebédelnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Mikor József haza jöve, bevivék néki az ajándékot, mely kezökben vala, a házba, és leborulának előtte a földig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'És kérdezősködék egészségök felől, s monda: Egészségben van-é a ti vén atyátok, a kiről nékem szóltatok? él-é még?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'Azok pedig mondának: Egészségben van a te szolgád, a mi atyánk, még él. És meghajták magokat és leborulának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'És felemelé szemeit és látá Benjámint az ő atyjafiát, az ő anyjának fiát, és monda: Ez-é a ti legkisebbik atyátokfia, a ki felől nékem szóltatok vala? És ismét monda: Az Isten légyen hozzád kegyelmes, fiam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Akkor elsiete onnan József, mert felgerjede szíve az ő öcscse iránt, és erőlteti vala a sírás; beméne azért szobájába, és ott síra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Azután megmosá orczáját, és kiméne, és megtartóztatá magát, és monda: Hozzatok enni valót.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'És elhozák néki külön, azoknak is külön, és az Égyiptombelieknek is, kik vele esznek vala, külön: Mert nem ehettek az Égyiptombeliek együtt a héberekkel, mert utálatos az az Égyiptombeliek előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Leűlének azért ő előtte, az elsőszülött az ő elsőszülöttsége szerint, és a fiatalabb az ő fiatalsága szerint. És az emberek álmélkodva nézének egymásra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Ő pedig részt juttata azoknak maga elől és a Benjámin része ötszörte nagyobb vala mindnyájok részénél. És ivának és megittasodának ő nála.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Azután parancsola József az ő háza gondviselőjének, mondván: Töltsd meg ez embereknek zsákjait eleséggel a mennyit elvihetnek; és mindeniknek pénzét tedd zsákja szájába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Az én poharamat pedig, az ezüst poharat, tedd a legkisebbik zsákjának szájába gabonájának árával együtt. És az József beszéde szerint cselekedék, a mint beszélt vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Reggel virradatkor, elbocsáttatának azok az emberek, szamaraikkal együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Kimenének a városból, de nem messze haladhatának, a mikor monda József az ő háza gondviselőjének: Kelj fel, siess utánuk azoknak az embereknek és ha eléred őket, mondd nékik: Miért fizettetek gonoszszal a jó helyébe?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Avagy nem abból iszik-é az én uram? és abból szokott jövendölni! Gonoszul cselekedtétek, a mit cselekedtetek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'És utóléré őket, és ilyen szavakkal szóla nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Azok pedig mondának néki: Miért szól az én uram ilyen szavakkal? Távol legyen szolgáidtól, hogy ilyen dolgot cselekedjenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Ímé a pénzt, melyet zsákjaink szájában találtunk vala, meghoztuk néked Kanaán földéről; hogy loptunk volna hát urad házából ezüstöt vagy aranyat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Akinél megtaláltatik a te szolgáid közűl, haljon meg az; sőt mi is szolgái leszünk uramnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'És monda: Mostan is legyen beszédetek szerint: a kinél megtaláltatik, az légyen nékem szolgám, ti pedig mentek legyetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'És sietének és leraká kiki az ő zsákját a földre, és kioldá kiki az ő zsákját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'És keresgéle; a legnagyobbikon kezdé s a legkissebbiken végezé, és megtalálá a poharat a Benjámin zsákjában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Azok pedig meghasogaták ruhájokat, és kiki megterhelé a maga szamarát, és visszatérének a városba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'És beméne Júda és az ő atyjafiai a József házába, ki még ott vala, és földre esének előtte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'És monda nékik József: Mi dolog ez a mit cselekedtetek? Avagy nem tudjátok-é hogy az ilyen magamféle ember jövendölni tud?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'És monda Júda: Mit mondhatunk az én uramnak? Mit szóljunk és mivel igazoljuk magunkat? Az Isten büntetése utólérte szolgáidat. Ímé mi az én uram szolgái vagyunk, mind mi, mind az, a kinek kezében a pohár találtatott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Ő pedig monda: Távol legyen tőlem, hogy azt cselekedjem: az a kinek kezében találtatott a pohár, az legyen nékem szolgám, ti pedig békességgel menjetek el a ti atyátokhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'De Júda hozzá járula és monda: Kérlek, uram, hadd szólhasson egy szót uram fülébe a te szolgád, és ne gerjedjen fel haragod a te szolgád ellen; mert hasonló vagy te a Faraóhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Az én uram kérdezte vala az ő szolgáit, mondván: Van-é atyátok, vagy testvéretek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Akkor mi azt felelénk az én uramnak: Van egy vén atyánk, és egy kis gyermek, a ki az ő vénségében lett; és ennek bátyja megholt, és csak ő maga maradt az ő anyjától, és az ő atyja szereti őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'És azt mondád a te szolgáidnak: Hozzátok én hozzám azt, hogy szemeimet reá vessem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'És mondánk az én uramnak: Nem hagyhatja el az a fiú az ő atyját; mert ha elhagyja atyját, meghal az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'És ezt mondád a te szolgáidnak: Ha a ti legkisebbik atyátokfia el nem jő veletek, színem elé se kerűljetek többé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Mikor azért felmenénk a te szolgádhoz, az én atyámhoz és tudtul adjuk vala néki az én uramnak beszédét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'És monda a mi atyánk: Menjetek vissza, és vegyetek nékünk egy kevés eleséget.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'És mondánk: Nem mehetünk le; ha a mi legkisebbik atyánkfia velünk lesz, akkor lemegyünk; mert nem mehetünk ama férfiú színe elé, ha a mi legkisebbik atyánkfia velünk nem lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'És monda a te szolgád, az én atyám, nékünk: Ti tudjátok hogy az én feleségem nékem csak két fiat szűlt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'Az egyik kiméne tőlem, és azt mondom vala: bizonyára fenevad szaggatta széllyel és attól fogva nem láttam őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Ha ezt is elviszitek szemeim elől, s veszedelem találja érni, akkor az én ősz fejemet keserűségtől borítva bocsátjátok alá a koporsóba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Ha tehát most visszamenéndek a te szolgádhoz, az én atyámhoz, és e fiú nem lesz velünk, mivelhogy annak lelke ennek lelkéhez van nőve,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'Ha meglátja, hogy nincs meg a gyermek, meghal s akkor a te szolgáid, a te szolgádnak, a mi atyánknak ősz fejét búba borítva bocsátják alá a koporsóba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Mivel a te szolgád e fiúért az ő atyjánál kezes lett, mondván: Ha vissza nem hozom őt hozzád, mind éltig bűnös legyek az én atyám előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Hadd maradjon azért e gyermek helyébe a te szolgád, az én uramnak szolgájáúl; e gyermek pedig menjen fel az ő bátyjaival.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Mert mimódon mehetnék én fel atyámhoz, ha e gyermek velem nem lenne, a nélkül, hogy ne lássam a nyomorúságot, mely atyámat érné?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'És nem tartóztathatá magát tovább József mindazok előtt, kik körűlötte állának és felkiálta: Vezessetek ki minden embert mellőlem. És nem marada senki nála, mikor megismerteté magát József az ő atyjafiaival.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'És hangos sírásra fakada, úgy hogy meghallák az Égyiptombeliek, és meghallá a Faraó háznépe is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'És monda József az ő atyjafiainak: Én vagyok József, él-e még az én atyám? És nem felelhetének néki az ő atyjafiai, mert megrettentek vala tőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Monda azért József az ő atyjafiainak: Jőjjetek közelebb hozzám! És közelebb menének. Akkor monda: Én vagyok József, a ti testvéretek, kit eladtatok vala Égyiptomba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'És most ne bánkódjatok, és ne bosszankodjatok azon, hogy engem ide eladtatok; mert a ti megmaradástokért küldött el engem Isten ti előttetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Mert immár két esztendeje, hogy éhség van e földön, de még öt esztendő van hátra, melyben sem szántás, sem aratás nem lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Az Isten küldött el engem ti előttetek, hogy míveljem a ti megmaradásotokat e földön, és hogy megmenthesselek titeket nagy szabadítással.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Nem ti küldöttetek azért engem ide, hanem az Isten, ki engem a Faraó atyjává tett, és egész házának urává, és Égyiptom egész földének fejedelmévé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Siessetek és menjetek fel atyámhoz, és mondjátok néki: Ezt mondja a te fiad József: Az Isten engem egész Égyiptomnak urává tett, jőjj le én hozzám, ne késsél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'És Gósen földén lakozol, és én hozzám közel leszesz, mind te, mind fiaid, mind fiaidnak fiai, juhaid, barmaid, és mindened, a mid van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'És eltartalak ott téged, mert még öt esztendei éhség lesz, hogy tönkre ne juss te, és házadnépe, és semmi, a mid van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'És ímé a ti szemeitek látják, és az én atyámfiának Benjáminnak szemei, hogy az én szám szól hozzátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Beszéljétek hát el atyámnak minden én dicsőségemet Égyiptomban, és mindazt, a mit láttatok. És siessetek s hozzátok ide az én atyámat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'És nyakába borúla az ő öccsének Benjáminnak és síra; Benjámin is síra az ő nyakán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'És megcsókolá mind az ő testvéreit és síra ő rajtok; azután beszédbe ereszkedének vele az ő testvérei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'És eljuta a hír a Faraó házába is, mondván: Eljöttek a József atyjafiai; és tetszék e dolog mind a Faraónak, mind az ő szolgáinak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'És monda a Faraó Józsefnek: Mondd meg a te atyádfiainak: Ezt cselekedjétek: Terheljétek meg a ti barmaitokat, és eredjetek, menjetek el Kanaán földére;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'És vegyétek fel atyátokat és házatok népét, és jőjjetek hozzám; és én néktek adom Égyiptom földének javát, hogy éljétek e földnek zsírját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Ez is parancsolatúl legyen néked: Ezt míveljétek, vigyetek magatokkal Égyiptom földéről szekereket gyermekeitek és feleségeitek számára, és vegyétek fel atyátokat és jőjjetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'A ti házi eszközeitekre pedig ne tekintsetek sóhajtva; mert egész Égyiptom földének a legjava a tiétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'És aképen cselekedének Izráel fiai; és ada nékik József szekereket a Faraó parancsolatja szerint; és enni valót is ada nékik az útra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Valamennyien valának, mindegyiknek ada egy-egy öltöző ruhát: Benjáminnak pedig ada háromszáz ezüst pénzt és öt öltöző ruhát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Atyjának pedig külde ilyenképen: tíz szamarat égyiptomi javakkal terhelve, és tíz nőstény szamarat gabonával, kenyérrel és egyéb élelemmel terhelve, az ő atyjának az útra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'És elbocsátá az ő testvéreit, és elmenének, és monda nékik: Ne háborogjatok az úton.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Feljövének azért Égyiptomból: és eljutának Kanaán földére az ő atyjokhoz, Jákóbhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'És mikor tudtára adák, mondván: József még él, és hogy uralkodik egész Égyiptom földén; az ő szíve elalélt, mert nem hisz vala nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Elbeszélék azért néki József minden beszédét, a melyeket velök beszélt vala, és látá a szekereket is, a melyeket József küldött vala, hogy őt elvigyék; akkor fölélede az ő atyjoknak, Jákóbnak lelke.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'És monda Izráel: Elég nékem, hogy József az én fiam még él: lemegyek hát, hogy meglássam őt minekelőtte meghalok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Elindula azért Izráel minden hozzá tartozóival és méne Beérsebába; és áldozék áldozatokat az ő atyja Izsák Istenének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'És szóla Isten Izráelnek éjjeli látomásban, és monda: Jákób, Jákób. Ő pedig monda: Ímhol vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'És monda: Én vagyok az Isten, a te atyádnak Istene: Ne félj lemenni Égyiptomba: mert nagy néppé teszlek ott téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Én lemegyek veled Égyiptomba, és én bizonynyal fel is hozlak; és József fogja bé a te szemeidet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Felkerekedék azért Jákób Beérsebából, és elvivék Izráel fiai Jákóbot az ő atyjokat, és gyermekeiket és feleségeiket a szekereken, melyeket a Faraó küldött vala érette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'És elvivék nyájaikat és szerzeményeiket, melyeket Kanaán földén szereztek vala, és jutának Égyiptomba Jákób és minden vele levő magva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'Az ő fiait és fiainak fiait, az ő leányait, és fiainak leányait és minden vele levő magvát elvivé magával Égyiptomba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Ezek pedig az Izráel fiainak nevei, kik bementek Égyiptomba: Jákób és az ő fiai: Jákóbnak elsőszülötte Rúben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Rúben fiai pedig: Khánokh, Pallu, Kheczrón, Khármi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Simeon fiai pedig: Jemúel, Jámin, Ohad, Jákhin, Czóhár és Saul a kanaáni asszonynak fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Lévi fiai pedig: Gerson, Kehát, Mérári.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Júda fiai pedig: Hér, Ónán, Séla, Perecz, Zerákh; de megholt vala Hér és Ónán a Kanaán földén. Perecznek fiai pedig: Kheczrón és Khámul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Izsakhár fiai pedig: Thóla, Puvah, Jób és Simrón.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Zebulon fiai pedig: Szered, Élon, Jákhleél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Ezek Lea fiai, a kiket szűlt vala Jákóbnak Mésopotámiában, Dínával az ő leányával együtt. Fiainak és leányainak összes száma: harminczhárom lélek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Gád fiai pedig: Czifjon, Khaggi, Súni, Eczbón, Héri, Aródi és Areéli.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Áser fiai pedig: Jimnáh, Jisváh, Jisvi, Beriha és Szerakh az ő húgok; Berihának fiai pedig: Khéber és Málkhiel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Ezek Zilpa fiai, kit Lábán adott vala Leának az ő leányának; és ő szűlé ezt a tizenhat lelket Jákóbnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Rákhelnek, Jákób feleségének fiai: József és Benjámin.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'És születének Józsefnek Égyiptom földén Manasse és Efráim, a kiket Asznáth, Potiferának, On papjának leánya szűlt néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'Benjámin fiai pedig: Bela, Bekher, Asbél, Géra, Nahamán, Ekhi, Rós, Muppim, Khuppim és Ard.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Ezek Rákhel fiai, kik születtek Jákóbnak, mindössze tizennégy lélek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Dán fia pedig: Khusim.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Nafthali fiai pedig: Jakhczeél, Gúni, Jéczer és Sillém.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Ezek Bilha fiai, kit adott vala Lábán Rákhelnek az ő leányának; és ezeket szűlte Jákóbnak, mindössze hét lelket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Valamennyi Jákóbbal Égyiptomba jött lélek, kik az ő ágyékából származtak, a Jákób fiainak feleségeit nem számítva, mindössze hatvanhat lélek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'József fiai pedig, kik Égyiptomban születtek, két lélek. Jákób egész házanépe, mely Égyiptomba ment vala, hetven lélek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Júdát pedig elküldé maga előtt Józsefhez, hogy útmutatója legyen Gósen felé. És eljutának Gósen földére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'És befogata József az ő szekerébe, és eleibe méne Izráelnek az ő atyjának Gósenbe; s a mint maga előtt látá, nyakába borula, és síra az ő nyakán sok ideig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'És monda Izráel Józsefnek: Immár örömest meghalok, minekutána láttam a te orczádat, hogy még élsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'József pedig monda az ő testvéreinek, és az ő atyja házanépének: Felmegyek és tudtára adom a Faraónak, és ezt mondom néki: Az én testvéreim és atyám háznépe, kik Kanaán földén valának, eljöttek én hozzám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Azok az emberek pedig juhpásztorok, mert baromtartó nép valának, és juhaikat, barmaikat, és mindenöket valamijök van, elhozták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'S ha majd a Faraó hivat titeket és azt kérdi: Mi a ti életmódotok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'Azt mondjátok: Baromtartó emberek voltak a te szolgáid gyermekségünktől fogva mind ez ideig, mi is, mint a mi atyáink, hogy lakhassatok Gósen földén; mert minden juhpásztor utálatos az Égyiptombeliek előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Elméne azért József és tudtára adá a Faraónak, és monda: Az én atyám és atyámfiai, juhaikkal, barmaikkal és mindenökkel valamijök volt, ide jöttek Kanaán földéről; és most Gósen földén vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'És vőn ötöt az ő testvérei közűl, és állítá őket a Faraó elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'És monda a Faraó a József testvéreinek: Mi a ti életmódotok? És mondának a Faraónak: Juhpásztorok a te szolgáid, mi is, mint a mi atyáink.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'És mondának a Faraónak: Azért jöttünk, hogy e földön tartózkodjunk, mert a te szolgáid barmainak nincs legelője, mivelhogy elhatalmazott az éhség Kanaán földén: hadd lakjanak azért most a te szolgáid Gósen földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'És szóla a Faraó Józsefnek, mondván: A te atyád és a te atyádfiai jöttek te hozzád.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'Égyiptom földe ímé előtted van; e föld legjobb részében telepítsd le a te atyádat és atyádfiait, lakozzanak a Gósen földén: ha pedig tudod, hogy vannak közöttök arra termett emberek, tedd azokat az én barmaim gondviselőivé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Bevivé József Jákóbot is az ő atyját, és állítá őt a Faraó elé. És köszönté Jákób a Faraót.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'És monda a Faraó Jákóbnak: Hány esztendős vagy?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Monda pedig Jákób a Faraónak: Az én bujdosásom esztendeinek napjai száz harmincz esztendő; kevesek és nyomorúságosak voltak az én életem esztendeinek napjai, és nem érték el az én atyáim élete esztendeinek napjait, a meddig ők bujdostak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'És megáldá Jákób a Faraót, és kiméne a Faraó elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Megtelepíté tehát József az ő atyját és atyjafiait, és ada nékik birtokot Égyiptom földén, annak a földnek legjobb részében a Rameszesz földén; a mint megparancsolta vala a Faraó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'És ellátja vala József az ő atyját és atyjafiait, és az ő atyjának egész házanépét kenyérrel, gyermekeik számához képest.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'És kenyér nem vala az egész föld kerekségén, mert igen nagy vala az éhség, és elalélt vala Égyiptom földe, és a Kanaán földe az éhség miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'József pedig mind összeszedé a pénzt, a mi találtatik vala Égyiptomnak és Kanaánnak földén a gabonáért, a melyet azok vesznek vala; és bévivé József a pénzt a Faraó házába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'És mikor elfogyott a pénz Égyiptom földéről is, Kanaán földéről is, egész Égyiptom Józsefhez méne, mondván: Adj nékünk kenyeret, miért haljunk meg szemed láttára, azért hogy nincs pénz?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'És monda József: Hozzátok ide barmaitokat, és adok néktek a ti barmaitokért, ha nincs pénz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'És elvivék barmaikat Józsefhez, és ada nékik József kenyeret lovakért, juhokért, ökrökért és szamarakért: és eltartá őket abban az esztendőben kenyérrel az ő barmaik összeségéért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Mikor pedig elmúlék az esztendő, menének hozzá a második esztendőben, és mondának néki: Nem titkolhatjuk el uramtól, hogy bizony elfogyott a pénz, és a barom-nyájak mind uramnál vannak, a mint látja az én uram semmi sem maradt, csak testünk és földünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Miért veszszünk el szemed láttára mind magunk, mind földünk? végy meg minket és földünket kenyéren, és mi és a mi földünk szolgái leszünk a Faraónak; csak adj magot, hogy éljünk s ne haljunk meg, és a föld ne pusztuljon el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Megvevé azért József egész Égyiptom földét a Faraó részére, mert az Égyiptombeliek mind eladák az ő földjöket, mivelhogy erőt vett vala rajtok az éhség. És a föld a Faraóé lőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'A népet pedig egyik városból a másikba telepíté Égyiptom egyik határszélétől másik széléig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Csak a papok földét nem vevé meg, mert a papoknak szabott részök vala a Faraótól és abból a szabott részből élnek vala, a mit nékik a Faraó ád vala; annak okáért, nem adák el az ő földjöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'És monda József a népnek: Ímé megvettelek titeket a mai napon, és a ti földeteket a Faraónak. Ímhol számotokra a mag, vessétek be a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'És takaráskor adjatok a Faraónak egy ötödrészt; négy rész pedig legyen a tiétek, a mező bevetésére és éléstekre, mind magatoknak, mind házatok népének, és gyermekeiteknek eledelül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'És mondának: Életünket megtartottad; hadd találjunk kegyelmet uram szemei előtt, és szolgái leszünk a Faraónak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'És törvénynyé tevé azt József mind e mai napig Égyiptom földén, hogy a Faraóé az ötödrész, csak a papok földe, egyedűl az nem volt a Faraóé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Lakozék azért Izráel Égyiptom földében a Gósen földén, és ott megöröködének, s megszaporodának és megsokasodának felette igen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Jákób pedig tizenhét esztendeig él vala Égyiptom földén, és Jákób élete esztendeinek napjai száz negyvenhét esztendő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'És elközelgetének Izráel halálának napjai, és hívatá az ő fiát Józsefet, s monda néki: Ha én te előtted kedves vagyok, kérlek tedd a kezedet tomporom alá, és légy hozzám szeretettel és hűséggel: Kérlek ne temess el engem Égyiptomban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'Midőn elaluszom az én atyáimmal, vígy ki engem Égyiptomból és temess el az ő sírjokba. És monda: Én a te beszéded szerint cselekszem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'És monda: Esküdjél meg nékem! és megesküvék néki. És leborula Izráel az ágy fejére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'És lőn ezek után, megmondák Józsefnek: Ímé a te atyád beteg; és elvivé magával az ő két fiát Manassét és Efraimot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'És tudtára adák Jákóbnak, mondván: Ímé a te fiad József hozzád jő; és összeszedé erejét Izráel, s felüle az ágyon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'És monda Jákób Józsefnek: A mindenható Isten megjelenék nékem Lúzban, a Kanaán földén, és megálda engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'És monda nékem: Ímé én megszaporítlak és megsokasítlak és népek sokaságává teszlek téged, s ezt a földet te utánnad a te magodnak adom örök birtokul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Most tehát a te két fiad, a kik néked Égyiptom földén annakelőtte születtek, hogy én hozzád jöttem vala Égyiptomba, az enyéim; Efraim és Manasse, akár csak Rúben és Simeon, az enyéim lesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Ama szülötteid pedig, kiket ő utánok nemzettél, tiéid lésznek, és az ő bátyjaik nevéről neveztessenek az ő örökségökben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Mert mikor Mésopotámiából jövék, meghala mellettem Rákhel Kanaán földén az úton, mikor még egy dűlőföldre valék Efratától, és eltemetém őt ott az Efratába (azaz Bethlehembe) vezető úton.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'És meglátá Izráel a József fiait és monda: Kicsodák ezek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'József pedig monda az ő atyjának: Az én fiaim, kiket Isten itt adott nékem. És monda: Hozd ide őket hozzám, hadd áldjam meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Mert Izráelnek szemei meghomályosodának a vénség miatt, és nem láthat vala. Közel vivé tehát őket hozzá, ő pedig megcsókolgatá és megölelgeté őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'És monda Izráel Józsefnek: Nem gondoltam, hogy orczádat megláthassam, és íme az Isten megengedte látnom magodat is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Akkor kivevé József azokat az ő atyjának térdei közül, és leborula arczczal a földre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'És fogá József mindkettejöket, Efraimot jobbkezével Izráel balkeze felől; Manassét pedig balkezével Izráelnek jobbkeze felől és közel vivé őket hozzá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Izráel pedig kinyujtá az ő jobbkezét és rátevé Efraim fejére, pedig ő a kisebbik vala, az ő balkezét pedig Manasse fejére. Tudva tevé így kezeit, mert az elsőszülött Manasse vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'És megáldá Józsefet s monda: Az Isten, a kinek előtte jártak az én atyáim Ábrahám és Izsák; az Isten a ki gondomat viselte, a mióta vagyok, mind e napig:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'Amaz Angyal, ki megszabadított engem minden gonosztól, áldja meg e gyermekeket, és viseljék az én nevemet és az én atyáimnak Ábrahámnak és Izsáknak nevét, és mint a halak szaporodjanak e földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Látván pedig József, hogy az ő atyja jobbkezét Efraim fejére tevé, nem tetszék néki, és megfogá atyja kezét, hogy Efraim fejéről Manasse fejére tegye át.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'És monda József az ő atyjának: Nem úgy atyám; mert ez az elsőszülött, ennek fejére tedd jobb kezedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Nem akará pedig az atyja és monda: Tudom fiam, tudom, ő is néppé lesz, ő is megnevekedik; de az ő öccse nálánál inkább megnevekedik, és az ő magja népek sokaságává lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'És megáldá őket azon a napon, mondván: Ha áld, téged említsen Izráel, mondván: Az Isten téged olyanná tégyen mint Efraimot s Manassét. És Efraimot eleibe tevé Manassénak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'És mondá Izráel Józsefnek: Ímé én meghalok, de az Isten veletek lesz és vissza visz titeket a ti atyáitok földére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Én pedig adok néked egy osztályrészt a te atyádfiainak része felett, melyet az Emoreustól vettem fegyveremmel és kézívemmel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'És szólítá Jákób az ő fiait, és monda: Gyűljetek egybe, hadd jelentsem meg néktek, a mi rátok következik a messze jövőben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Gyűljetek össze s hallgassatok Jákóbnak fiai! hallgassatok Izráelre, a ti atyátokra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Rúben, te elsőszülöttem, erőm, tehetségem zsengéje, első a méltóságban, első a hatalomban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Állhatatlan, mint a víz, nem leszesz első, mivel atyád ágyába léptél fel: akkor megfertőztetted! Nyoszolyámba lépett ő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Simeon és Lévi atyafiak, erőszak eszközei az ő fegyverök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'Tanácsukban ne légyen részes lelkem, gyűlésükkel ne egyesűljön dicsőségem, mert haragjokban férfit öltek, s kedvök telve inát szegték az ökörnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Átkozott haragjok, mert erőszakos, és dühök, mivel kegyetlen; eloszlatom őket Jákóbban, és elszélesztem Izráelben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Júda! téged magasztalnak atyádfiai, kezed ellenségeidnek nyakán lesz s meghajolnak előtted atyáidnak fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Oroszlánkölyök Júda; zsákmányt ejtvén, felmentél, fiam! Lehevert, lenyúgodott, mint a hím oroszlán, és mint nőstény oroszlán; ki veri őt fel?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Nem múlik el Júdától a fejedelmi bot, sem a vezéri pálcza térdei közűl; míg eljő Siló, és a népek néki engednek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Szőlőtőhöz köti szamarát, és nemes venyigéhez szamara vemhét, ruháját borban mossa, felöltőjét a szőlő vérében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Bortól veresek szemei, tejtől fehérek fogai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Zebulon a tenger partjáig lakozik, azaz a hajók kikötőjéig s határának széle Czídonig ér.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Izsakhár erős csontú szamár, a karámok közt heverész.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'S látja, hogy jó a nyugalom és hogy a föld mily kies: teher alá hajtja hátát, s robotoló szolgává lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dán ítéli az ő népét, mint Izráel akármelyik nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Dán kígyó lesz az úton, szarvaskígyó az ösvényen, mely a ló körmébe harap, hogy lovagja hanyatt esik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Szabadításodra várok Uram!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gád! had háborgatja; majd ő hág annak sarkába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'Ásernek kenyere kövér, királyi csemegét szolgáltat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Nafthali, gyorslábú szarvas, az ő beszéde kedves.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Termékeny fa József, termő ág a forrás mellett, ágazata meghaladja a kőfalat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Keserítik, lövöldözik és üldözik a nyilazók:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'De mereven marad kézíve, feszülten keze karjai, Jákób Hatalmasának kezétől, onnan, Izráel pásztorától, kősziklájától.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'Atyád Istenétől, a ki segéljen; a mindenhatótól, a ki megáldjon, az ég áldásaival, onnan felülről, a mélység áldásaival, mely alant terül, az emlők és anyaméh áldásaival.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Atyád áldásai meghaladják az ős hegyek áldásait, az örök halmok kiességeit. Szálljanak József fejére, a testvérek közűl kiválasztatottnak koponyájára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Benjámin ragadozó farkas: reggel ragadományt eszik, este pedig zsákmányt oszt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Mind ezek Izráel nemzetségei, tizenketten, és ez az a mit mondott nékik az ő atyjok, mikor őket megáldá; mindeniket tulajdon áldásával áldá meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'És parancsola nékik és monda: Én az én népemhez takaríttatom, temessetek engem az én atyáimhoz, ama barlangba, mely a Khitteus Efron mezején van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'Abba a barlangba, mely Kanaán földén Mamré átellenében Makpelahnak mezején van, melyet megvett Ábrahám a mezővel együtt a Khitteus Efrontól, temetésre való örökségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Oda temették el Ábrahámot és Sárát az ő feleségét; oda temették Izsákot és Rebekát az ő feleségét; s oda temettem el Leát is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'Szerzemény e mező és a barlang, mely abban van, a Khéth fiaitól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'És elvégezé Jákób a mit fiainak parancsolt és fölszedé lábait az ágyra, és kimúlék és az ő népéhez takaríttaték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'József pedig az ő atyja orczájára borúla és siránkozék felette és csókolgatá őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'És megparancsolá József az ő szolgáinak, az orvosoknak, hogy balzsamozzák be az ő atyját; és bebalzsamozák az orvosok Izráelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Mikor negyven nap eltelék, mert akkorra telnek be a bebalzsamozás napjai, siraták őt az Égyiptombeliek hetven napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'És elmúlának az ő siratásának napjai, és szóla József a Faraó házanépéhez, mondván: Ha kedves vagyok előttetek, szóljatok kérlek a Faraónak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Az én atyám engem megesketett, mondván: Ímé én meghalok; az én síromba, melyet Kanaán földén ástam magamnak, oda temess el engem. Most hát kérlek, hadd menjek el, és temessem el az én atyámat, azután visszatérek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'És monda a Faraó: Eredj el és temesd el a te atyádat, a mint megesketett téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Elméne azért József, hogy az ő atyját eltemesse, és vele együtt felmenének mind a Faraó szolgái, az ő házának vénei és Égyiptom földének minden vénei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'Józsefnek is egész háznépe; és az ő bátyjai, és az ő atyjának háznépe; csak gyermekeiket, juhaikat és barmaikat hagyták a Gósen földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Felmenének annakfelette ő vele szekerek is és lovagok, úgy hogy igen nagy sereg vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Mikor eljutának Atád szérűjéhez, mely a Jordánon túl van, nagy és keserves sírással sírának ott. József pedig hét napig gyászolá az ő atyját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'És láták az ország lakosai, a Kanaán népe azt a gyászt Atád szérűjénél, és mondának: Keserves gyásza ez az Égyiptombelieknek. Azért nevezék azt a helyet Ábel Miczrajimnak, mely a Jordánon túl van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Aképen cselekedének azért Jákóbbal az ő fiai, a miképen megparancsolta vala nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'Elvivék ugyanis őt az ő fiai Kanaán földére és eltemeték őt a Makpelah mezőnek barlangjába, melyet vett vala Ábrahám a mezővel együtt temetésre való örökségnek a Khitteus Efrontól Mamrénak átellenében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'És visszatére József Égyiptomba, ő, és az ő atyjafiai, és mind azok, kik vele fölmentek vala az ő atyjának temetésére, minekutána eltemette az ő atyját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'A mint láták József bátyjai, hogy az ő atyjok meghalt, ezt mondják vala: Hátha gyűlölni fog minket József, és visszaadja nékünk mindazt a gonoszt, a mit rajta elkövettünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Izenetet küldének azért Józsefhez, mondván: A te atyád megparancsolta nékünk az ő holta előtt, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'Így szóljatok Józsefhez: Kérünk téged, bocsásd meg a te atyádfiainak vétkét és bűnöket, mert gonoszul cselekedtek te ellened. Most azért bocsásd meg azoknak vétkét, a kik a te atyád Istenét szolgálják. József pedig sír vala, mikor ezt mondák néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Járulának pedig ő hozzá az ő testvérei is, és leborúlának előtte és mondának: Ímé mi a te szolgáid vagyunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'József pedig monda: Ne féljetek: avagy Isten gyanánt vagyok-é én?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Ti gonoszt gondoltatok én ellenem, de Isten azt jóra gondolta fordítani, hogy cselekedjék úgy a mint ma, hogy sok nép életét megtartsa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Most annakokáért ne féljetek: Eltartalak én titeket és a ti gyermekeiteket. És megvígasztalá őket és szívökre beszéle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'József pedig Égyiptomban lakozék; mind ő, mind az ő atyjának házanépe. És éle József száz tíz esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'És látá József Efraimtól harmad ízben való fiait. Manasse fiának Mákhirnak is születtek József térdén gyermekei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'És monda József az ő testvéreinek: Én meghalok, de Isten bizonnyal meglátogat titeket és felvisz titeket e földről arra a földre, melyet esküvel ígért meg Ábrahámnak, Izsáknak és Jákóbnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'És megesketé József Izráel fiait, mondván: Mikor az Isten titeket bizonnyal meglátogat, vigyétek fel innen az én tetemeimet magatokkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'És meghala József száz tíz esztendős korában, és bebalzsamozák, és koporsóba tevék Égyiptomban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Ezek pedig az Izráel fiainak nevei, a kik Jákóbbal Égyiptomba menének; kiki az ő házanépével méne:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Rúben, Simeon, Lévi és Júda;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Izsakhár, Zebulon és Benjámin;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dán és Nafthali, Gád és Áser.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Mindazok a lelkek pedig, a kik Jákób ágyékából származtak vala, hetvenen valának. József pedig Égyiptomban vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'És meghala József és minden ő atyjafia és az az egész nemzedék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Izráel fiai pedig szaporák valának, szaporodának és sokasodának és igen-igen elhatalmazának, úgy hogy megtelék velök az ország.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Azonközben új király támada Égyiptomban, a ki Józsefet nem ismerte vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'És monda az ő népének: Ímé az Izráel fiainak népe több, és hatalmasabb nálunknál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Nosza bánjunk okosan vele, hogy el ne sokasodjék és az ne legyen, hogy ha háború támad, ő is ellenségünkhöz adja magát és ellenünk harczoljon és az országból kimenjen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Rendelének azért föléjök robotmestereket, hogy nehéz munkákkal sanyargassák őket. És építe a Faraónak gabonatartó városokat, Pithomot és Ramszeszt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'De minél inkább sanyargatják vala őt, annál inkább sokasodik és annál inkább terjeszkedik vala, s félnek vala az Izráel fiaitól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Pedig kegyetlenűl dolgoztaták az égyiptomiak az Izráel fiait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'És kemény munkával keseríték életöket, sárcsinálással, téglavetéssel és mindenféle mezei munkával, minden munkájokkal, melyeket kegyetlenűl dolgoztatnak vala velök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'És szóla Égyiptom királya a héber bábáknak, a kik közűl egyiknek Sifra, a másiknak Puá vala neve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'És monda: Mikoron héber asszonyok körűl bábálkodtok, nézzetek a szűlőszékre: ha fiú az, azt öljétek meg, ha pedig leány az, hadd éljen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'De a bábák félék az Istent és nem cselekedének úgy a mint Égyiptom királya parancsolta vala nékik, hanem életben hagyják vala a gyermekeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Hívatá annakokáért Égyiptom királya a bábákat és monda nékik: Miért míveltétek azt, hogy életben hagytátok a gyermekeket?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'A bábák pedig mondának a Faraónak: Mert a héber asszonyok nem olyanok, mint az Égyiptombeliek: mert azok élet-erősek; minekelőtte a bába hozzájok eljutna, már szűlnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Annakokáért jól tőn Isten a bábákkal, a nép pedig sokasodék és igen elhatalmazék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'És lőn, hogy mivel a bábák félék az Istent: megépíté az ő házukat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Parancsola azért a Faraó minden ő népének, mondván: Minden fiút, a ki születik, vessetek a folyóvízbe, a leányt pedig hagyjátok mind életben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'És elméne egy Lévi nemzetségéből való férfiú és Lévi-leányt vőn feleségűl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'És fogada méhében az asszony és fiat szűle; és látá, hogy szép az és rejtegeté három hónapig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'De mikor tovább nem rejtegetheté, szerze annak egy gyékény-ládácskát, és bekené azt gyantával és szurokkal s belétevé a gyermeket és letevé a folyóvíz szélén a sás közé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Az ő nénje pedig megáll vala távolról, hogy megtudja: mi történik vele?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'És aláméne a Faraó leánya, hogy megfürödjék a folyóvízben, szolgálóleányai pedig járkálnak vala a víz partján. És meglátá a ládácskát a sás között s elküldé az ő szolgálóleányát és kihozatá azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'És kinyitá és látá a gyermeket; és ímé egy síró fiú. És könyörűle rajta és monda: A héberek gyermekei közűl való ez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Az ő nénje pedig monda a Faraó leányának: Elmenjek-é s hívjak-é egy szoptatós asszonyt a héber asszonyok közűl, hogy szoptassa néked a gyermeket?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'És a Faraó leánya monda néki: Eredj el. Elméne azért a leányzó, és elhívá a gyermek anyját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'És monda néki a Faraó leánya: Vidd el ezt a gyermeket és szoptasd fel nékem, és én megadom a te jutalmadat. És vevé az asszony a gyermeket és szoptatá azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'És felnevekedék a gyermek, és vivé őt a Faraó leányához, és fia gyanánt lőn annak, és nevezé nevét Mózesnek, és mondá: Mert a vízből húztam ki őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'Lőn pedig azokban a napokban, mikor Mózes felnevekedék, kiméne az ő atyjafiaihoz és látá az ő nehéz munkájokat s látá, hogy egy Égyiptombeli férfi üt vala egy héber férfit az ő atyjafiai közűl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Mikor ide-oda tekinte és látá hogy senki sincs, agyonüté az Égyiptombelit és elrejté azt a homokba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Másnap is kiméne és ímé két héber férfi veszekedik vala. És monda annak a ki bűnös vala: Miért vered a te atyádfiát?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Az pedig monda: Kicsoda tett téged fő emberré és bíróvá mi rajtunk? Talán engem is meg akarsz ölni, mint megöléd az égyiptomit? Mózes pedig megfélemlék és monda: Bizony kitudódott a dolog.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'A Faraó is meghallá azt a dolgot és Mózest halálra keresteti vala: de elfuta Mózes a Faraó elől és lakozék Midián földén; leűle pedig egy kútnál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Midián papjának pedig hét leánya vala, és oda menének és vizet húzának és tele merék a válúkat, hogy megitassák atyjoknak juhait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'A pásztorok is oda menének és elűzék őket. Mózes pedig felkele és segítséggel lőn nékik és megitatá juhaikat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Mikor atyjokhoz Réhuelhez menének, monda ez: Mi az oka, hogy ma ilyen hamar megjöttetek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'Ők pedig mondának: Egy égyiptombeli férfi oltalmaza minket a pásztorok ellen, annakfelette vizet is húzott nékünk, és megitatta a juhokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'S monda leányainak: És hol van ő? miért hagytátok ott azt a férfit? hívjátok el, hogy egyék kenyeret.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'És tetszék Mózesnek, hogy ott maradjon e férfiúnál, és ez feleségül adá Mózesnek az ő leányát, Czipporát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'És fiat szűle ez és nevezé nevét Gersomnak, mert mondá: Jövevény voltam az idegen földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'És lőn ama hosszú idő alatt, meghala az Égyiptom királya, Izráel fiai pedig fohászkodnak vala a szolgaság miatt, és kiáltnak vala és feljuta a szolgaság miatt való kiáltásuk Istenhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'És meghallá Isten az ő fohászkodásukat és megemlékezék Isten az Ábrahámmal, Izsákkal és Jákóbbal kötött szövetségéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'És megtekinté Isten az Izráel fiait és gondja vala rájok Istennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Mózes pedig őrzi vala az ő ipának, Jethrónak a Midián papjának juhait és hajtá a juhokat a pusztán túl és juta az Isten hegyéhez, Hórebhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'És megjelenék néki az Úr angyala tűznek lángjában egy csipkebokor közepéből, és látá, hogy ímé a csipkebokor ég vala; de a csipkebokor meg nem emésztetik vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'S monda Mózes: Oda megyek, hogy lássam e nagy csudát, miért nem ég el a csipkebokor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'És látá az Úr, hogy oda méne megnézni, és szólítá őt Isten a csipkebokorból, mondván: Mózes, Mózes. Ez pedig monda: Ímhol vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'És monda: Ne jőjj ide közel, oldd le a te saruidat lábaidról; mert a hely, a melyen állasz, szent föld.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'És monda: Én vagyok a te atyádnak Istene, Ábrahámnak Istene, Izsáknak Istene és Jákóbnak Istene. Mózes pedig elrejté az ő orczáját, mert fél vala az Istenre tekinteni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Az Úr pedig monda: Látván láttam az én népemnek nyomorúságát, a mely Égyiptomban vagyon és meghallottam az ő sanyargatóik miatt való kiáltásukat; sőt ismerem szenvedéseit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'Le is szállok, hogy megszabadítsam őt az Égyiptombeliek kezéből és felvigyem őt arról a földről, jó és tágas földre, téjjel és mézzel folyó földre, a Kananeusok, Khitteusok, Emoreusok, Perizeusok, Khivveusok és Jebuzeusok lakóhelyére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Mivel hát ímé feljutott hozzám az Izráel fiainak kiáltása és láttam is a nyomorgatást, a melylyel nyomorgatják őket az Égyiptombeliek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Most azért eredj, elküldelek téged a Faraóhoz és hozd ki az én népemet, az Izráel fiait Égyiptomból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Mózes pedig monda az Istennek: Kicsoda vagyok én, hogy elmenjek a Faraóhoz és kihozzam az Izráel fiait Égyiptomból?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'És felele: Én veled lészek! és ez lesz a jele, hogy én küldöttelek téged, hogy mikor kihozod a népet Égyiptomból, ezen a hegyen fogtok szolgálni az Istennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Mózes pedig monda az Istennek: Ímé én elmegyek az Izráel fiaihoz és ezt mondom nékik: A ti atyáitok Istene küldött engem ti hozzátok; ha azt mondják nékem: Mi a neve? mit mondjak nékik?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'És monda Isten Mózesnek: VAGYOK A KI VAGYOK. És monda: Így szólj az Izráel fiaihoz: A VAGYOK küldött engem ti hozzátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'És ismét monda Isten Mózesnek: Így szólj az Izráel fiaihoz: Az Úr, a ti atyáitoknak Istene, Ábrahámnak Istene, Izsáknak Istene és Jákóbnak Istene küldött engem ti hozzátok. Ez az én nevem mind örökké és ez az én emlékezetem nemzetségről nemzetségre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Menj el és gyűjtsd egybe az Izráel véneit és mondd ezt nékik: Az Úr, a ti atyáitok Istene, Ábrahámnak, Izsáknak és Jákóbnak Istene megjelent nékem, mondván: Megemlékeztem rólatok és arról a mit elkövettek rajtatok Égyiptomban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'És mondám: Kiviszlek titeket az égyiptomi nyomorúságból a Kananeusok, Khitteusok, Emoreusok, Perizeusok, Khivveusok és Jebuzeusok földére, téjjel és mézzel folyó földre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'És ha hallgatnak szavadra, akkor elmégy te és az Izráel vénei Égyiptom királyához, s így szóltok néki: Az Úr, a héberek Istene megjelent nékünk; most azért hadd menjünk három napi útra a pusztába, hogy áldozzunk az Úrnak a mi Istenünknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Én pedig tudom, hogy az égyiptomi király nem engedi meg néktek, hogy elmenjetek, még erőhatalomra sem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Kinyújtom azért az én kezemet és megverem Égyiptomot mindenféle csudáimmal, melyeket véghez viszek benne; így azután elbocsát titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'És kedvessé tészem e népet az Égyiptombeliek előtt, és lészen, hogy mikor kimentek, nem mentek üresen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'Kérjen azért minden asszony az ő szomszédasszonyától és háza lakó asszonyától ezüst edényeket és arany edényeket és ruhákat; és rakjátok azokat fiaitokra és leányaitokra, s így foszszátok ki Égyiptomot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Felele Mózes és monda: De ők nem hisznek nékem s nem hallgatnak szavamra, sőt azt mondják: nem jelent meg néked az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Az Úr pedig monda néki: Mi az a kezedben? S ő monda: Vessző.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Vesd azt – úgymond – a földre. És veté azt a földre és lőn kígyóvá; és Mózes elfutamodék előle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Monda pedig az Úr Mózesnek: Nyújtsd ki kezedet és fogd meg a farkát! És kinyújtá kezét és megragadá azt, és vesszővé lőn az ő kezében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'Hogy elhigyjék, hogy megjelent néked az Úr, az ő atyáik Istene, Ábrahám Istene, Izsák Istene és Jákób Istene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'És ismét monda néki az Úr: Nosza dugd kebeledbe a kezed; és kebelébe dugá kezét és kihúzá: ímé az ő keze poklos vala, olyan mint a hó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'És monda: Dugd vissza kebeledbe a kezed: és visszadugá kezét kebelébe és kivevé azt kebeléből és ímé ismét olyanná lőn mint teste.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'És ha úgy lenne, hogy nem hisznek néked és nem hallgatnak az első jel szavára, majd hisznek a második jel szavának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'És ha úgy lenne, hogy ennek a két jelnek sem hisznek és nem hallgatnak szavadra: akkor meríts vizet a folyóvízből és öntsd a szárazra, és a víz, a mit a folyóvízből merítettél, vérré lesz a szárazon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'És monda Mózes az Úrnak: Kérlek, Uram, nem vagyok én ékesenszóló sem tegnaptól, sem tegnap előttől fogva, sem azóta, hogy szólottál a te szolgáddal; mert én nehéz ajkú és nehéz nyelvű vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Az Úr pedig monda néki: Ki adott szájat az embernek? Avagy ki tesz némává vagy siketté, vagy látóvá vagy vakká? Nemde én, az Úr?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Most hát eredj és én lészek a te száddal, és megtanítlak téged arra, a mit beszélned kell.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Ő pedig monda: Kérlek, Uram, csak küldd, a kit küldeni akarsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'És felgerjede az Úr haragja Mózes ellen és monda: Nemde atyádfia néked a Lévi nemzetségből való Áron? Tudom, hogy ő ékesenszóló és ímé ő ki is jő elődbe s mihelyt meglát, örvendezni fog az ő szívében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Beszélj azért vele, és add szájába a beszédeket, és én lészek a te száddal és az ő szájával és megtanítlak titeket arra, a mit cselekedjetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'És ő beszél majd helyetted a néphez és ő lesz néked száj gyanánt, te pedig leszesz néki Isten gyanánt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Ezt a vesszőt pedig vedd kezedbe, hogy véghez vidd vele ama jeleket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'És méne Mózes és visszatére az ő ipához Jethróhoz és monda néki: Hadd menjek és térjek vissza az én atyámfiaihoz Égyiptomba, hogy meglássam, ha élnek-e még? És monda Jethró Mózesnek: Eredj el békességgel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Az Úr pedig monda Mózesnek Midiánban: Eredj, térj vissza Égyiptomba; mert meghaltak mindazok a férfiak, a kik téged halálra kerestek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'És felvevé Mózes az ő feleségét és az ő fiait és felülteté őket a szamárra és visszatére Égyiptom földére. Az Isten vesszejét pedig kezébe vevé Mózes.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'És monda az Úr Mózesnek: Mikor elindulsz, hogy visszatérj Égyiptomba, meglásd, hogy mindazokat a csudákat véghez vidd a Faraó előtt, melyeket kezedbe adtam; én pedig megkeményítem az ő szívét, és nem bocsátja el a népet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Ezt mondd azért a Faraónak: Így szólt az Úr: Elsőszülött fiam az Izráel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'Ha azt mondom néked: Bocsásd el az én fiamat, hogy szolgáljon nékem és te vonakodol elbocsátani: ímé én megölöm a te elsőszülött fiadat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'És lőn az úton, egy szálláson, eleibe álla az Úr és meg akarja vala őt ölni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'De Czippora egy éles követ veve és lemetszé az ő fiának előbőrét és lába elé veté mondván: Bizony, vérjegyesem vagy te nékem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'És békét hagya néki. Akkor monda: Vérjegyes a körűlmetélkedésért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Áronnak pedig monda az Úr: Eredj Mózes eleibe a pusztába! És elméne és találkozék vele az Isten hegyénél és megcsókolá őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Mózes pedig elbeszélé Áronnak az Úr mindama szavait, melyekkel őt elküldötte vala és mindazokat a jeleket, melyeket reá bízott vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'És méne Mózes és Áron és egybegyűjték Izráel fiainak minden véneit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'És elmondá Áron mindazokat a beszédeket, melyeket mondott vala az Úr Mózesnek és megcselekedé a jeleket a nép szemei előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'És hitt a nép, és megértette, hogy meglátogatta az Úr Izráel fiait és megtekintette nyomorúságukat. És meghajták magokat és leborulának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Annakutána pedig elmenének Mózes és Áron és mondának a Faraónak: Ezt mondá az Úr, Izráelnek Istene: Bocsásd el az én népemet, hogy ünnepet üljenek nékem a pusztában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'A Faraó pedig mondá: Kicsoda az Úr, hogy szavára hallgassak, és elbocsássam Izráelt? Nem ismerem az Urat és nem is bocsátom el Izráelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'Ők pedig mondának: A héberek Istene megjelent nékünk; hadd mehessünk hát háromnapi útra a pusztába, hogy áldozhassunk az Úrnak a mi Istenünknek, hogy meg ne verjen minket döghalállal vagy fegyverrel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Égyiptom királya pedig monda nékik: Mózes és Áron! miért vonjátok el a népet az ő munkáitól? menjetek dolgotokra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Ezt is mondja vala a Faraó: Ímé a föld népe most sok, és ti elhagyatjátok velök az ő munkáikat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Parancsolá azért a Faraó azon a napon a nép sarczoltatóinak és felvigyázóinak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'Ne adjatok többé polyvát a népnek a téglavetéshez mint ennekelőtte; hadd menjenek el ők magok és szedjenek magoknak polyvát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'De a tégla számát, mennyit ennekelőtte csináltak, vessétek ki rájok; azt le ne szállítsátok, mert restek ők és azért kiáltoznak, mondván: Menjünk el, áldozzunk a mi Istenünknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Nehezíttessék meg a szolgálat ezeken az embereken, hogy azzal legyen dolguk és ne hajtsanak hazug szóra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Kimenének azért a nép sarczoltatói és felvigyázói és ezt mondák a népnek mondván: Ezt mondja a Faraó: Nem adok néktek polyvát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Menjetek magatok, szedjetek magatoknak polyvát onnan, a hol találtok; mert semmi sem szállíttatik le szolgálatotokból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'És elszélede a nép egész Égyiptom földén, hogy tarlót szedjen polyva helyett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'A sarczoltatók pedig szorítják vala, mondván: Végezzétek el munkátokat, napjában a napi munkát, mint akkor, a mikor polyva volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'És verettetének az Izráel fiai közül való felvigyázók, a kiket a Faraó sarczoltatói rendeltek vala föléjök, mondván: Miért nem végeztétek el a rátok vetett téglaszámot sem tegnap, sem ma úgy, mint ennekelőtte?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'És elmenének az Izráel fiai közül való felvigyázók és kiáltának a Faraóhoz, mondván: Miért cselekszel így a te szolgáiddal?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Polyvát nem adnak a te szolgáidnak és azt mondják nékünk: Csináljatok téglát! És ímé a te szolgáid verettetnek, a te néped pedig vétkezik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Az pedig monda: Restek vagytok, restek, azért mondjátok: Menjünk el, áldozzunk az Úrnak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Most pedig menjetek, dolgozzatok, polyvát ugyan nem adnak néktek, de a rátok vetett tégla-számot be kell adnotok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Akkor látják vala Izráel fiainak felvigyázói, hogy bajban vannak, mivel azt kell mondaniok: a tégla-számot le ne szállítsátok; napjában a napi munka meglegyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'És mikor kijövének a Faraótól, szembe találkozának Mózessel és Áronnal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'S mondának nékik: Lásson meg titeket az Úr és ítéljen meg, kik rossz hírbe kevertetek minket a Faraó előtt és az ő szolgái előtt, fegyvert adván azok kezébe, hogy megöljenek minket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'És visszaméne Mózes az Úrhoz és monda: Uram, miért engedsz rosszul bánni ezzel a néppel! Miért küldél engem ide?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Mert attól fogva, hogy bemenék a Faraóhoz, hogy a te nevedben szóljak, rosszabbul bánik e néppel; megszabadítani pedig nem szabadítád meg a te népedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Az Úr pedig monda Mózesnek: Majd meglátod mit cselekszem a Faraóval; mert hatalmas kéz miatt kell őket elbocsátani és hatalmas kéz miatt űzi el őket az ő földéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Az Isten pedig szóla Mózeshez és monda néki: Én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Ábrahámnak, Izsáknak és Jákóbnak úgy jelentem meg mint mindenható Isten, de az én Jehova nevemen nem voltam előttük ismeretes.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Szövetséget is kötöttem velek, hogy nékik adom a Kanaán földét, az ő tartózkodásuk földét, a melyen tartózkodjanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Fohászkodását is meghallottam az Izráel fiainak a miatt, hogy az Égyiptombeliek szolgálatra szorítják őket, megemlékeztem az én szövetségemről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Annakokáért mondd meg az Izráel fiainak: Én vagyok az Úr és kiviszlek titeket Égyiptom nehéz munkái alól és megszabadítlak titeket az ő szolgálatjoktól és megmentlek titeket kinyújtott karral és nagy büntető ítéletek által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'És népemmé fogadlak titeket s Istentekké lészek néktek és megtudjátok, hogy én vagyok a ti Uratok Istentek, a ki kihoztalak titeket Égyiptom nehéz munkái alól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'És béviszlek titeket a földre, a mely felől esküre emeltem fel kezemet, hogy Ábrahámnak, Izsáknak és Jákóbnak adom azt, és néktek adom azt örökségül, én az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Eképen szóla Mózes az Izráel fiaihoz; de nem hallgatának Mózesre, a kislelkűség és a kemény szolgálat miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Az Úr pedig szóla Mózeshez mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Eredj be, szólj a Faraónak, Égyiptom királyának, hogy bocsássa el Izráel fiait az ő földéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Mózes pedig szóla az Úr előtt, mondván: Ímé Izráel fiai nem hallgatnak reám, hogy hallgatna hát reám a Faraó, holott én nehéz ajkú vagyok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'És szóla az Úr Mózeshez és Áronhoz és rendelé őket Izráel fiaihoz és a Faraóhoz, Égyiptom királyához, hogy hozzák ki az Izráel fiait Égyiptom földéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Ezek atyáik házanépének fejei: Rúbennek, Izráel elsőszülöttének fiai: Khanókh, Pallu, Kheczrón és Karmi. Ezek a Rúben nemzetségei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Simeon fiai pedig: Jemúél, Jámin, Óhad, Jákin, Czohar és Saul, a kanaánbeli asszony fiai. Ezek a Simeon nemzetségei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Ezek pedig a Lévi fiainak nevei az ő születésök szerint: Gersón, Kehát és Merári. Lévi életének esztendei pedig: száz harminczhét esztendő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Gersón fiai: Libni, Simhi, az ő nemzetségeik szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Kehát fiai pedig: Amrám, Jiczhár, Khebrón és Huzziél. Kehát életének esztendei pedig: száz harminczhárom esztendő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Merári fiai pedig: Makhli és Músi. Ezek a Lévi nemzetségei az ő születésök szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Amrám pedig feleségűl vevé magának Jókébedet, atyjának húgát s ez szűlé néki Áront és Mózest. Amrám életének esztendei pedig száz harminczhét esztendő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Jiczhár fiai pedig: Kórákh, Nefeg és Zikri.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Huzziél fiai pedig: Misáél, Elczáfán és Szithri.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Áron pedig feleségűl vevé magának Elisebát, Aminádáb leányát, Nakhsón húgát s ez szűlé néki Nádábot, Abíhut, Eleázárt és Ithámárt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Kórákh fiai pedig: Asszir, Elkánáh és Abiászáf. Ezek a Kórákh nemzetségei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Eleázár pedig az Áron fia, a Putiél leányai közűl vőn magának feleséget s ez szűlé néki Fineást. Ezek a Léviták atyáinak fejei az ő nemzetségeik szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Ez Áron és Mózes, a kiknek mondá az Úr: Hozzátok ki az Izráel fiait Égyiptom földéről, az ő seregeik szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Ők azok, a kik szóltak a Faraónak Égyiptom királyának, hogy kihozhassák az Izráel fiait Égyiptomból. Ez Mózes és Áron.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'És lőn a mikor szóla az Úr Mózesnek Égyiptom földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'Így szóla az Úr Mózesnek, mondván: Én vagyok az Úr: mondd el a Faraónak Égyiptom királyának mindazt, a mit én szólok néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Mózes pedig monda az Úr előtt: Ímé én nehéz ajakú vagyok, hogy hallgatna reám a Faraó?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Az Úr pedig monda Mózesnek: Lásd, Istenévé teszlek téged a Faraónak, Áron pedig, a te atyádfia, szószólód lészen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Te mondj el mindent, a mit néked parancsolok; Áron pedig, a te atyádfia mondja meg a Faraónak, hogy bocsássa el Izráel fiait az ő földéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Én pedig megkeményítem a Faraó szívét és megsokasítom az én jeleimet és csudáimat Égyiptom földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'És a Faraó nem hallgat reátok; akkor én kezemet Égyiptomra vetem és kihozom az én seregeimet, az én népemet, az Izráel fiait Égyiptom földéről nagy büntető ítéletek által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'S megtudják az Égyiptombeliek, hogy én vagyok az Úr, a mikor kinyujtándom kezemet Égyiptomra és kihozándom az Izráel fiait ő közülök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'És cselekedék Mózes és Áron, a mint parancsolta vala nékik az Úr; úgy cselekedének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Mózes pedig nyolczvan esztendős és Áron nyolczvanhárom esztendős vala, a mikor a Faraóval beszéltek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'És szóla az Úr Mózesnek és Áronnak mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'Ha szól hozzátok a Faraó mondván: tegyetek csudát; akkor mondd Áronnak: Vedd a te vessződet és vesd a Faraó elé; kígyóvá lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Beméne azért Mózes és Áron a Faraóhoz, és úgy cselekedének, a mint az Úr parancsolta vala; veté Áron az ő vesszejét a Faraó elé és az ő szolgái elé, és kígyóvá lőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'És előhívá a Faraó is a bölcseket és varázslókat, és azok is, Égyiptom írástudói, úgy cselekedének az ő titkos mesterségökkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'Elveté ugyanis mindenik az ő vesszejét és kígyókká lőnek; de az Áron vesszeje elnyelé azok vesszejét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'És megkeményedék a Faraó szíve és nem hallgata reájok, a mint megmondotta vala az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Az Úr pedig monda Mózesnek: Kemény a Faraó szíve, nem akarja a népet elbocsátani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Eredj a Faraóhoz reggel; ímé ő kimegy a vízhez, és állj eleibe a folyóvíz partján, és a vesszőt, a mely kígyóvá változott vala, vedd kezedbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'És mondd néki: Az Úr, a héberek Istene küldött engem hozzád, mondván: Bocsásd el az én népemet, hogy szolgáljanak nékem a pusztában; de ímé mindez ideig meg nem hallgattál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Így szólt az Úr: Erről tudod meg, hogy én vagyok az Úr: Ímé én megsujtom a vesszővel, a mely kezemben van, a vizet, a mely a folyóban van, és vérré változik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'És a hal, a mely a folyóvízben van, meghal, a folyóvíz pedig megbüdösödik és irtózni fognak az Égyiptombeliek vizet inni a folyóból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Monda azért az Úr Mózesnek: Mondd Áronnak: Vedd a te vessződet és nyujtsd ki kezedet Égyiptom vizeire; azoknak folyóvizeire, csatornáira, tavaira és minden vízfogóira, hogy vérré legyenek és vér legyen Égyiptom egész földén, mind a fa-, mind a kőedényekben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Mózes és Áron pedig úgy cselekedének, a mint az Úr parancsolta vala. És felemelé a vesszőt és megsujtá a vizet, a mely a folyóban vala a Faraó előtt és az ő szolgái előtt, és mind vérré változék a víz, a mely a folyóban vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'A hal pedig, a mely a folyóvízben vala, meghala, és megbüdösödék a folyóvíz, és nem ihatának az Égyiptombeliek a folyónak vizéből; és vér vala az egész Égyiptom földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'De úgy cselekedének Égyiptom írástudói is az ő varázslásukkal, és kemény maradt a Faraó szíve és nem hallgata reájok; a mint az Úr megmondotta vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'És elfordula a Faraó és haza méne és ezen sem indula meg az ő szíve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Az Égyiptombeliek pedig mindnyájan ássák vala a folyóvíz mellékét vízért, hogy ihassanak; mert nem ihatják vala a folyó vizét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'És hét nap telék el, a mióta az Úr megsujtotta vala a folyóvizet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'És monda az Úr Mózesnek: Menj be a Faraóhoz és mondd néki: Azt mondja az Úr: Bocsásd el az én népemet, hogy szolgáljanak nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Ha pedig te el nem akarod bocsátani, ímé én egész határodat békákkal verem meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'És a folyóvíz békáktól pozsog és felmennek és bemennek a te házadba és ágyasházadba és ágyadra és a te szolgáid házába és néped közé és a te kemenczéidbe és sütőteknőidbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'És reád és népedre s minden te szolgáidra felmennek a békák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'És monda az Úr Mózesnek: Mondd Áronnak: Nyujtsd ki kezedet a te vessződdel a folyóvizekre, csatornákra és a tavakra, és hozd fel a békákat Égyiptom földére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'És kinyujtá kezét Áron Égyiptom vizeire, és békák jövének fel és ellepék Égyiptom földét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'De az írástudók is úgy cselekedének az ő titkos mesterségökkel és felhozák a békákat Égyiptom földére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'És hívatá a Faraó Mózest és Áront és monda: Könyörögjetek az Úrnak, hogy távolítsa el rólam és az én népemről a békákat, és én elbocsátom a népet, hogy áldozzék az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Mózes pedig monda a Faraónak: Parancsolj velem: mikorra könyörögjek éretted és a te szolgáidért és a te népedért, hogy elpusztuljanak a békák tőled és házaidtól; és csak a folyóvízben maradjanak meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Felele a Faraó: Holnapra. És monda Mózes: A mint kívánod, hogy megtudd, hogy nincs hasonló a mi Urunkhoz Istenünkhöz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'És eltávoznak a békák tőled, meg a te házaidtól, szolgáidtól és a te népedtől; csak a folyóvízben maradnak meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'És kiméne Mózes és Áron a Faraótól és kiálta Mózes az Úrhoz a békák felől, a melyeket a Faraóra bocsátott vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'És az Úr Mózes beszéde szerint cselekedék és kiveszének a békák a házakból, udvarokból és mezőkről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'És rakásokba gyűjték azokat össze és a föld megbüszhödék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'S a mint látá a Faraó, hogy baja könnyebbűl, megkeményíté az ő szívét, és nem hallgata reájok, a mint megmondotta vala az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'És szóla az Úr Mózesnek: Mondd Áronnak: Nyujtsd ki a te vessződet és sujtsd meg a föld porát, hogy tetvekké legyen egész Égyiptom földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'És aképen cselekedének. Áron kinyujtá kezét az ő vesszejével és megsujtá a föld porát, és tetvek lőnek emberen és barmon; a föld minden pora tetvekké lőn egész Égyiptom földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'És úgy cselekedének az írástudók is az ő varázslásukkal, hogy tetveket hozzanak elő, de nem teheték; és valának a tetvek emberen és barmon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'És mondák az írástudók a Faraónak: Az Isten ujja ez. De kemény maradt a Faraó szíve, és nem hallgata reájok; a mint mondotta vala az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Az Úr pedig monda Mózesnek: Kelj fel reggel és állj a Faraó eleibe; ímé kimegy a vizek felé, és mondd néki: Ezt mondja az Úr: Bocsásd el az én népemet, hogy szolgáljanak nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Mert ha el nem bocsátod az én népemet, ímé én bocsátok te reád, a te szolgáidra és a te népedre és a te házaidra ártalmas bogarakat, és megtelnek az Égyiptombeliek házai ártalmas bogarakkal és a föld is, a melyen ők vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'De különválasztom azon a napon a Gósen földét, a melyen az én népem lakik, hogy ne legyenek ott ártalmas bogarak, azért, hogy megtudd, hogy én vagyok az Úr ezen a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'És különbséget tészek az én népem között és a te néped között. Holnap lészen e jelenség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'És aképen cselekedék az Úr; jövének ugyanis ártalmas bogarak a Faraó házára és az ő szolgái házára, és egész Égyiptom földén pusztává lőn a föld az ártalmas bogarak miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'És hívatá a Faraó Mózest és Áront és monda: Menjetek, áldozzatok a ti Istenteknek ezen a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Mózes pedig monda: Nincs rendén, hogy úgy cselekedjünk, hogy mi azt áldozzuk az Úrnak a mi Istenünknek, a mi utálatos az Égyiptombeliek előtt: ímé, ha azt áldozzuk az ő szemeik előtt, a mi az Égyiptombelieknek utálatos, nem köveznek-é meg minket?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Háromnapi járó földre megyünk a pusztába és úgy áldozunk a mi Urunknak Istenünknek, a mint megmondja nékünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'És monda a Faraó: Én elbocsátlak titeket, hogy áldozzatok a ti Uratoknak Istenteknek a pusztában, csak nagyon messze ne távozzatok; imádkozzatok érettem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'Mózes pedig monda: Ímé én kimegyek te tőled és imádkozom az Úrhoz és eltávoznak az ártalmas bogarak a Faraótól és az ő szolgáitól és az ő népétől holnap; csak megint el ne ámítson a Faraó, hogy el ne bocsássa a népet áldozni az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'És kiméne Mózes a Faraótól és imádkozék az Úrhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'És az Úr Mózes beszéde szerint cselekedék; s eltávozának az ártalmas bogarak a Faraótól, szolgáitól és népétől; egy sem marada.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'De a Faraó ezúttal is megkeményíté az ő szívét és nem bocsátá el a népet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'És monda az Úr Mózesnek: Menj a Faraóhoz és beszélj vele: Ezt mondja az Úr, a héberek Istene: Bocsásd el az én népemet, hogy szolgáljanak nékem:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Mert ha nem akarod elbocsátani és tovább is tartóztatod őket:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'Ímé az Úr keze lészen a te mezei barmaidon, lovakon, szamarakon, tevéken, ökrökön és juhokon; igen nagy döghalál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'De különbséget tesz az Úr az Izráel barmai között és Égyiptom barmai között, és mindabból, a mi Izráel fiaié, egy sem vész el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Időt is hagya az Úr, mondván: Holnap cselekszi az Úr ezt a dolgot a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Meg is cselekedé az Úr ezt a dolgot másodnapon, és elhulla Égyiptomnak minden barma, de az Izráel fiainak barma közül egy sem hullott el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'El is külde a Faraó, és ímé egy sem hullt vala el az Izráeliták barma közül: de a Faraó szíve kemény maradt, és nem bocsátá el a népet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Az Úr pedig monda Mózesnek és Áronnak: Vegyétek tele markaitokat kemenczehamuval, és szórja azt Mózes az ég felé a Faraó szeme láttára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'Hogy porrá legyen Égyiptomnak egész földén, s emberen és barmon hólyagosan fakadó fekéllyé legyen Égyiptomnak egész földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Vevének azért kemenczehamut és a Faraó elé állának, és Mózes az ég felé szórá azt; és lőn az emberen és barmon hólyagosan fakadó fekély.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'És az írástudók nem állhatnak vala Mózes előtt a fekély miatt; mert fekély vala az írástudókon s mind az Égyiptombelieken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'De az Úr megkeményíté a Faraó szívét, és nem hallgata reájok, a mint megmondotta vala az Úr Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'És monda az Úr Mózesnek: Kelj fel reggel és állj a Faraó eleibe és mondd néki: Ezt mondja az Úr, a héberek Istene: Bocsásd el az én népemet, hogy szolgáljanak nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Mert ezúttal minden csapásomat reá bocsátom a te szívedre, a te szolgáidra és a te népedre azért, hogy megtudd, hogy nincs én hozzám hasonló az egész földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Mert ha most kinyujtanám kezemet és megvernélek téged és a te népedet döghalállal, akkor kivágattatnál a földről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'Ámde azért tartottalak fenn tégedet, hogy megmutassam néked az én hatalmamat, és hogy hirdessék az én nevemet az egész földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Ha tovább is feltartóztatod az én népemet és nem bocsátod el őket:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'Ímé holnap ilyenkor igen nagy jégesőt bocsátok, a melyhez hasonló nem volt Égyiptomban az napságtól fogva hogy fundáltatott, mind ez ideig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Most annakokáért küldj el, hajtasd be barmaidat és mindenedet, valamid a mezőn van; minden ember és barom, a mely a mezőn találtatik és házba nem hajtatik, – jégeső szakad arra, és meghal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'A ki a Faraó szolgái közűl az Úr beszédétől megfélemedék, szolgáit és barmait házakba futtatá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'A ki pedig nem törődék az Úr beszédével, szolgáit és barmát a mezőn hagyá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Az Úr pedig monda Mózesnek: Nyújtsd ki kezedet az égre, hogy legyen jégeső Égyiptom egész földén az emberre, baromra és a mező minden fűvére, Égyiptom földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Kinyujtá azért Mózes az ő vesszejét az égre, az Úr pedig mennydörgést támaszta és jégesőt, és tűz szálla le a földre, és jégesőt bocsáta az Úr Égyiptom földére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'És lőn jégeső, és a tűz egymást éré az igen nagy jégeső közt, a melyhez hasonló nem volt az egész Égyiptom földén, mióta nép lakja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'És elveré a jégeső egész Égyiptom földén mindazt, a mi a mezőn vala, embertől baromig; a mező minden fűvét is elveré a jégeső és a mező minden fáját is egybe rontá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Csak a Gósen földén, hol Izráel fiai valának, nem volt jégeső.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'A Faraó pedig elkülde és hívatá Mózest és Áront, és monda nékik: Vétkeztem ezúttal; az Úr az igaz; én pedig és az én népem gonoszok vagyunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Imádkozzatok az Úrhoz, hogy legyen elég a mennydörgés és jégeső, és akkor elbocsátlak titeket és nem maradtok tovább.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Mózes pedig monda néki: Mihelyt kimegyek a városból, felemelem kezeimet az Úrhoz; megszűnnek a mennydörgések és nem lesz többé jégeső, hogy megtudd, hogy az Úré a föld.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'De tudom, hogy te és a te szolgáid még nem féltek az Úr Istentől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'A len pedig és az árpa elvereték, mert az árpa kalászos, a len pedig bimbós vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'De a búza és a tönköly nem vereték el, mert azok késeiek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'És kiméne Mózes a Faraótól a városból és felemelé kezeit az Úrhoz, és megszűnének a mennydörgések s a jégeső és eső sem ömlik vala a földre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Amint látá a Faraó, hogy megszűnék az eső, meg a jégeső és a mennydörgés, ismét vétkezék és megkeményíté szívét ő és az ő szolgái.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'És kemény maradt a Faraó szíve, és nem bocsátá el az Izráel fiait, a mint megmondotta vala az Úr Mózes által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'És monda az Úr Mózesnek: Menj be a Faraóhoz, mert én keményítettem meg az ő szívét és az ő szolgáinak szívét, azért hogy ezeket az én jeleimet megtegyem közöttök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'És azért, hogy elbeszéljed azt a te fiadnak és fiad fiának hallatára, a mit Égyiptomban cselekedtem, és jeleimet, a melyeket rajtok tettem, hogy megtudjátok, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'És beméne Mózes és Áron a Faraóhoz és mondának néki: Ezt mondja az Úr, a héberek Istene: Meddig nem akarod még magadat megalázni én előttem? Bocsásd el az én népemet, hogy szolgáljanak nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Mert ha te nem akarod az én népemet elbocsátani, ímé én holnap sáskát hozok a te határodra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'És elborítja a földnek színét, úgy hogy nem lesz látható a föld, és megemészti a megmenekedett maradékot, a mi megmaradt néktek a jégeső után, és megemészt minden fát, mely néktek sarjadzik a mezőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'És betöltik a te házaidat, és minden szolgáidnak házát és minden Égyiptombelinek házát, a mit nem láttak a te atyáid, sem a te atyáid atyjai, a mióta e földön vannak mind e mai napig. És megfordula s kiméne a Faraó elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'A Faraó szolgái pedig mondának őnéki: Meddig lesz még ez mi nékünk romlásunkra? Bocsásd el azokat az embereket, hogy szolgáljanak az Úrnak az ő Istenöknek. Még sem veszed-é eszedbe, hogy elvész Égyiptom?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'És visszahozák Mózest és Áront a Faraóhoz s monda ez nékik: Menjetek el, szolgáljatok az Úrnak a ti Istenteknek. Kik s kik azok, a kik elmennek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Mózes pedig monda: A mi gyermekeinkkel és véneinkkel megyünk, a mi fiainkkal és leányainkkal, juhainkkal és barmainkkal megyünk, mert az Úrnak innepet kell szentelnünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Monda azért nékik: Úgy legyen veletek az Úr, a mint elbocsátlak titeket és gyermekeiteket! Vigyázzatok, mert gonoszra igyekeztek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Nem úgy! menjetek el ti férfiak és szolgáljatok az Úrnak, mert ti is ezt kívántátok. És elűzék őket a Faraó színe elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'És monda az Úr Mózesnek: Nyújtsd ki a te kezedet Égyiptom földére a sáskáért, hogy jőjjön fel Égyiptom földére és emészsze meg a földnek minden fűvét; mindazt a mit a jégeső meghagyott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Kinyujtá azért Mózes az ő vesszejét Égyiptom földére, és az Úr egész nap és egész éjjel keleti szelet támaszta a földre. Mire reggel lőn, a keleti szél felhozá a sáskát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'És feljöve a sáska egész Égyiptom földére s nagy sokasággal szálla le Égyiptom egész határára. Annak előtte sem volt olyan sáska s ezután sem lesz olyan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'És elborítá az egész föld színét, és a föld elsötétedék, és megemészté a földnek minden fűvét és a fának minden gyümölcsét, a mit a jégeső meghagyott vala, és semmi zöld sem marada a fán, sem a mezőnek fűvén egész Égyiptom földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Akkor a Faraó siete hívatni Mózest és Áront és monda: Vétkeztem az Úr ellen, a ti Istenetek ellen és ti ellenetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Most annakokáért bocsásd meg csak ez egyszer az én vétkemet és imádkozzatok az Úrhoz a ti Istentekhez, hogy csak ezt a halált fordítsa el én tőlem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'És kiméne a Faraó elől és imádkozék az Úrhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'És fordíta az Úr igen erős nyugoti szelet, és felkapá a sáskát és veté azokat a veres tengerbe; egy sáska sem marada egész Égyiptom határán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'De az Úr megkeményíté a Faraó szívét, és nem bocsátá el az Izráel fiait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'És monda az Úr Mózesnek: Nyujtsd ki a te kezedet az ég felé, hogy legyen setétség Égyiptom földén és pedig tapintható setétség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'És kinyujtá Mózes az ő kezét az ég felé, és lőn sűrű setétség egész Égyiptom földén három napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Nem látták egymást, és senki sem kelt fel az ő helyéből három napig; de Izráel minden fiának világosság vala az ő lakhelyében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Akkor hívatá a Faraó Mózest és monda: Menjetek el, szolgáljatok az Úrnak, csak juhaitok és barmaitok maradjanak; gyermekeitek is elmehetnek véletek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Mózes pedig monda: Sőt inkább néked kell kezünkbe adnod véres áldozatra és égő-áldozatra valókat, hogy megáldozzuk a mi Urunknak Istenünknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'És velünk jőnek a mi barmaink is, egy körömnyi sem marad el, mert azokból veszünk, hogy szolgáljunk a mi Urunknak Istenünknek; magunk sem tudjuk, mivel szolgálunk az Úrnak, míg oda nem jutunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'De az Úr megkeményíté a Faraó szívét, és nem akará őket elbocsátani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'És monda néki a Faraó: Menj el előlem; vigyázz magadra, hogy többé az én orczámat ne lásd; mert a mely napon az én orczámat látod, meghalsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Mózes pedig monda: Helyesen szólál. Nem látom többé a te orczádat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Az Úr pedig monda Mózesnek: Még egy csapást hozok a Faraóra és Égyiptomra; azután elbocsát titeket innen; a mikor mindenestől elbocsát, űzve hajt el titeket innen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Szólj azért a népnek füle hallatára, hogy kérjenek a férfi az ő férfitársától, az asszony pedig az ő asszonytársától ezüst edényeket és arany edényeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Az Úr pedig kedvessé tevé a népet az Égyiptombeliek előtt. A férfiú Mózes is igen nagy vala Égyiptom földén a Faraó szolgái előtt és a nép előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'És monda Mózes: Ezt mondja az Úr: Éjfél körűl kimegyek Égyiptomba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'És meghal Égyiptom földén minden elsőszülött, a Faraónak elsőszülöttétől fogva, a ki az ő királyi székében űl, a szolgálónak első szülöttéig, a ki malmot hajt; a baromnak is minden első fajzása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'És nagy jajgatás lesz egész Égyiptom földén, a melyhez hasonló nem volt és hasonló nem lesz többé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'De Izráel fiai közűl az eb sem ölti ki nyelvét senkire, az embertől kezdve a baromig; hogy megtudjátok, hogy különbséget tett az Úr Égyiptom között és Izráel között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'És mindezek a te szolgáid lejönnek hozzám és leborulnak előttem, mondván: Eredj ki te és mind a nép, a mely téged követ, és csak azután megyek el. És nagy haraggal méne ki a Faraó elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Az Úr pedig monda Mózesnek: Azért nem hallgat reátok a Faraó, hogy az én csudáim sokasodjanak meg Égyiptom földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Mózes pedig és Áron mindezeket a csudákat megtevék a Faraó előtt; de az Úr megkeményíté a Faraó szívét. És nem bocsátá el Izráel fiait az ő földéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Szólott vala pedig az Úr Mózesnek és Áronnak Égyiptom földén, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Ez a hónap legyen néktek a hónapok elseje; első legyen ez néktek az esztendő hónapjai között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Szóljatok Izráel egész gyűlekezetének, mondván: E hónak tizedikén mindenki vegyen magának egy bárányt az atyáknak háza szerint, házanként egy bárányt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Hogyha a háznép kevés a bárányhoz, akkor a házához közel való szomszédjával együtt vegyen a lelkek száma szerint; kit-kit ételéhez képest számítsatok a bárányhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'A bárány ép, hím, egy esztendős legyen; a juhok közűl vagy a kecskék közűl vegyétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'És legyen nálatok őrizet alatt e hónap tizennegyedik napjáig, és ölje meg Izráel községének egész gyülekezete estennen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'És vegyenek a vérből, és azokban a házakban, a hol azt megeszik, hintsenek a két ajtófélre és a szemöldökfára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'A húst pedig egyék meg azon éjjel, tűzön sütve, kovásztalan kenyérrel és keserű fűvekkel egyék meg azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Ne egyetek abból nyersen, vagy vízben főtten, hanem tűzön sütve, a fejét, lábszáraival és belsejével együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'És ne hagyjatok belőle reggelre, vagy a mi megmarad belőle reggelre, tűzzel égessétek meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'És ilyen módon egyétek azt meg: Derekaitokat felövezve, saruitok lábaitokon és pálczáitok kezetekben, és nagy sietséggel egyétek azt; mert az Úr páskhája az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Mert általmégyek Égyiptom földén ezen éjszakán és megölök minden elsőszülöttet Égyiptom földén, az embertől kezdve a baromig, és Égyiptom minden istene felett ítéletet tartok, én, az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'És a vér jelül lesz néktek a házakon, a melyekben ti lesztek, s meglátom a vért és elmegyek mellettetek és nem lesz rajtatok a csapás veszedelmetekre, mikor megverem Égyiptom földét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'És legyen ez a nap néktek emlékezetül, és innepnek szenteljétek azt az Úrnak nemzetségről nemzetségre; örök rendtartás szerint ünnepeljétek azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Hét napig egyetek kovásztalan kenyeret; még az első napon takarítsátok el a kovászt házaitokból, mert valaki kovászost ejéndik az első naptól fogva a hetedik napig, az olyan lélek irtassék ki Izráelből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Az első napon pedig szent gyűléstek legyen és a hetedik napon is szent gyűléstek legyen; azokon semmi munkát ne tegyetek, egyedül csak a mi eledelére való minden embernek, azt el lehet készítenetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Megtartsátok a kovásztalan kenyér innepét; mert azon a napon hoztam ki a ti seregeiteket Égyiptom földéről; tartsátok meg hát e napot nemzetségről nemzetségre, örök rendtartás szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'Az első hónapban, a hónapnak tizennegyedik napján estve egyetek kovásztalan kenyeret, a hónap huszonegyedik napjának estvéjéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Hét napon át ne találtassék kovász a ti házaitokban; mert valaki kovászost ejéndik, az a lélek kiirtatik Izráel gyülekezetéből, akár jövevény, akár az ország szülöttje legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Semmi kovászost ne egyetek, minden lakóhelyeteken kovásztalan kenyeret egyetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Előhívá tehát Mózes Izráel minden véneit és monda nékik: Fogjatok és vegyetek magatoknak bárányt családaitok szerint és öljétek meg a páskhát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'És vegyetek egy kötés izsópot és mártsátok a vérbe, a mely az edényben van, és hintsétek meg a szemöldökfát és a két ajtófelet abból a vérből, a mely az edényben van; ti közűletek pedig senki se menjen ki az ő házának ajtaján reggelig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Mikor általmegy az Úr, hogy megverje az Égyiptombelieket és meglátja a vért a szemöldökfán és a két ajtófélen: elmegy az Úr az ajtó mellett és nem engedi, hogy a pusztító bemenjen öldökölni a ti házaitokba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Megtartsátok azért ezt a dolgot, rendtartás gyanánt, magadnak és fiaidnak mindörökre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'És mikor bementek a földre, melyet az Úr ád néktek, a mint megmondotta vala: akkor tartsátok meg ezt a szertartást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Mikor pedig a ti fiaitok mondandják néktek: Micsoda ez a ti szertartástok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'Akkor mondjátok: Páskha-áldozat ez az Úrnak, a ki elment az Izráel fiainak házai mellett Égyiptomban, mikor megverte az Égyiptombelieket, a mi házainkat pedig megoltalmazta. És a nép meghajtá magát és leborula.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'És menének és úgy cselekedének az Izráel fiai, a mint megparancsolta vala az Úr Mózesnek és Áronnak; úgy cselekedének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Lőn pedig éjfélkor, hogy megöle az Úr minden elsőszülöttet Égyiptomnak földén, a Faraónak elsőszülöttétől fogva, a ki az ő királyi székiben űl vala, a tömlöczbeli fogolynak elsőszülöttéig és a baromnak is minden első fajzását.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'És fölkele a Faraó azon az éjszakán és mind az ő szolgái és egész Égyiptom, és lőn nagy jajgatás Égyiptomban; mert egy ház sem vala, melyben halott ne lett volna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'És hívatá Mózest és Áront éjszaka és monda: Keljetek fel, menjetek ki az én népem közűl, mind ti, mind Izráel fiai és menjetek, szolgáljatok az Úrnak, a mint mondátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Juhaitokat is, barmaitokat is vegyétek, a mint mondátok és menjetek el és áldjatok engem is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'És az Égyiptombeliek erősen rajta valának, hogy a népet mentül hamarább kiküldhessék az országból; mert azt mondják vala: mindnyájan meghalunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'És a nép az ő tésztáját, minekelőtte megkelt volna, sütőteknőivel együtt ruhájába kötve, vállára veté.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Az Izráel fiai pedig Mózes beszéde szerint cselekedének és kérének az Égyiptombeliektől ezüst edényeket és arany edényeket, meg ruhákat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Az Úr pedig kedvessé tette vala a népet az Égyiptombeliek előtt, hogy kérésökre hajlának és kifoszták az Égyiptombelieket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'És elindulának Izráel fiai Rameszeszből Szukhóthba, mintegy hatszáz ezeren gyalog, csupán férfiak a gyermekeken kívül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Sok elegy nép is méne fel velök; juh is, szarvasmarha is, felette sok barom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'És sütének a tésztából, melyet Égyiptomból hoztak vala, kovásztalan pogácsákat, mert meg nem kelhet vala, mivelhogy kiűzetének Égyiptomból és nem késhetének s még eleséget sem készítének magoknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Az Izráel fiainak lakása pedig, a míg Égyiptomban laknak, négyszáz harmincz esztendő vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'És lőn a négyszáz harmincz esztendő végén, lőn pedig ugyanazon napon, hogy az Úrnak minden serege kijöve Égyiptomnak földéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Az Úr tiszteletére rendelt éjszaka ez, a melyen kihozta őket Égyiptom földéről; az Úr tiszteletére rendelt éjszaka Izráel minden fiai előtt nemzetségről nemzetségre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'És monda az Úr Mózesnek és Áronnak: Ez a Páskha rendtartása: Egy idegen származású se egyék abból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Akárkinek is pénzen vett szolgája akkor egyék abból, ha körűlmetélted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'A zsellér és a béres ne egyék abból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'Egy házban egyék meg; a házból ki ne vígy a húsból, és csontot se törjetek össze abban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Izráel egész gyülekezete készítse azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'És ha jövevény tartózkodik nálad, és páskhát akarna készíteni az Úrnak: metéltessék körűl minden férfia, és úgy foghat annak készítéséhez, és legyen olyan, mint az országnak szülötte. Egy körűlmetéletlen se egyék abból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Egy törvénye legyen az ott születettnek és a jövevénynek, a ki közöttetek tartózkodik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'És Izráel fiai mindnyájan megcselekedék; a mint parancsolta vala az Úr Mózesnek és Áronnak, úgy cselekedének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'Ugyanazon napon hozá ki az Úr az Izráel fiait Égyiptomnak földéről, az ő seregeik szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'És szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Nékem szentelj minden elsőszülöttet, valami megnyitja az ő anyjának méhét az Izráel fiai között, akár ember, akár barom, enyim legyen az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'És monda Mózes a népnek: Megemlékezzél e napról, melyen kijöttetek Égyiptomból, a szolgálatnak házából; mert hatalmas kézzel hozott ki onnan titeket az Úr; azért ne egyetek kovászost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Ma mentek ki, az Abib hónapban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'És ha majd bevisz téged az Úr a Kananeusok, meg Khittheusok, meg Emoreusok, meg Khivveusok és Jebuzeusok földére, melyről megesküdött a ti atyáitoknak, hogy néked adja azt a téjjel és mézzel folyó földet: akkor ebben a hónapban végezd ezt a szertartást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Hét napon át kovásztalan kenyeret egyél, a hetedik napon pedig innepet ülj az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Kovásztalan kenyeret egyél hét napon át, és ne láttassék nálad kovászos kenyér, se kovász ne láttassék a te egész határodban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'És add tudtára a te fiadnak azon a napon, mondván: Ez a miatt van, a mit az Úr cselekedett velem, mikor kijövék Égyiptomból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'És legyen az néked jel gyanánt a te kezeden és emlékezetül a te szemeid előtt azért, hogy az Úr törvénye a te szádban legyen, mert hatalmas kézzel hozott ki téged az Úr Égyiptomból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Tartsd meg azért ezt a rendelést annak idejében esztendőről esztendőre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'Ha pedig beviénd téged az Úr a Kananeusok földére, a miképen megesküdött néked és a te atyáidnak, és azt néked adándja:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'Az Úrnak ajánld fel akkor mindazt, a mi az ő anyjának méhét megnyitja, a baromnak is, a mi néked lesz, minden méhnyitó fajzását; a hímek az Úré.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'De a szamárnak minden első fajzását báránynyal váltsd meg; ha pedig meg nem váltod, szegd meg a nyakát. Az embernek is minden elsőszülöttét megváltsd a te fiaid közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'És ha egykor a te fiad téged megkérdez, mondván: Micsoda ez? akkor mondd néki: Hatalmas kézzel hozott ki minket az Úr Égyiptomból, a szolgálatnak házából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'És lőn, mikor a Faraó megátalkodottan vonakodék minket elbocsátani: megöle az Úr minden elsőszülöttet Égyiptom földén, az ember elsőszülöttétől a barom első fajzásáig; azért áldozok én az Úrnak minden hímet, mely anyja méhét megnyitja, és megváltom az én fiaimnak minden elsőszülöttét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Legyen azért jel gyanánt a te kezeden és homlok-kötő gyanánt a te szemeid előtt, mert hatalmas kézzel hozott ki minket az Úr Égyiptomból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'És lőn, a mikor elbocsátá a Faraó a népet, nem vivé őket Isten a Filiszteusok földje felé, noha közel vala az; mert monda az Isten: Netalán mást gondol a nép, ha harczot lát, és visszatér Égyiptomba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Kerülő úton vezeté azért Isten a népet, a veres tenger pusztájának útján; és fölfegyverkezve jövének ki Izráel fiai Égyiptom földéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'És Mózes elvivé magával a József tetemeit is, mert megesketvén megeskette vala Izráel fiait, mondván: Meglátogatván meglátogat titeket az Isten, akkor az én tetemeimet felvigyétek innen magatokkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'És elindulának Szukhótból és táborba szállának Ethámban, a puszta szélén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Az Úr pedig megy vala előttök nappal felhőoszlopban, hogy vezérelje őket az úton, éjjel pedig tűzoszlopban, hogy világítson nékik, hogy éjjel és nappal mehessenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Nem távozott el a felhőoszlop nappal, sem a tűzoszlop éjjel a nép elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'És szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Szólj az Izráel fiainak, hogy forduljanak vissza és üssenek tábort Pi-Hahiróth előtt, Migdol között és a tenger között, Baál-Czefón előtt; ezzel átellenben üssetek tábort a tenger mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Majd azt gondolja a Faraó az Izráel fiai felől: Eltévelyedtek ezek e földön; körülfogta őket a puszta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Én pedig megkeményítem a Faraó szívét, és űzőbe veszi őket, hogy megdicsőíttessem a Faraó által és minden ő serege által és megtudják az Égyiptombeliek, hogy én vagyok az Úr. És úgy cselekedének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'És hírül vivék az égyiptomi királynak, hogy elfutott a nép, és megváltozék a Faraónak és az ő szolgáinak szíve a nép iránt és mondának: Mit cselekedtünk, hogy elbocsátottuk Izráelt a mi szolgálatunkból!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Befogata tehát szekerébe és maga mellé vevé az ő népét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'És vőn hatszáz válogatott szekeret és Égyiptom minden egyéb szekerét és hárman-hárman valának mindeniken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'És megkeményíté az Úr a Faraónak, az égyiptomi királynak szivét, hogy űzőbe vegye az Izráel fiait; Izráel fiai pedig mennek vala nagy hatalommal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'És az Égyiptombeliek utánok nyomulának és elérék őket a tenger mellett, a hol táboroznak vala, a Faraónak minden lova, szekere, meg lovasai és serege Pi-Hahiróth mellett, Baál-Czefón előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'A mint közeledék a Faraó, Izráel fiai felemelék szemeiket, és ímé az Égyiptombeliek nyomukban vannak. És nagyon megfélemlének s az Úrhoz kiáltának az Izráel fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'És mondának Mózesnek: Hát nincsenek-é Égyiptomban sírok, hogy ide a pusztába hoztál minket meghalni? Mit cselekedél velünk, hogy kihoztál minket Égyiptomból?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Nem ez volt-é a szó, a mit szóltunk vala hozzád Égyiptomban, mondván: Hagyj békét nékünk, hadd szolgáljunk az Égyiptombelieknek, mert jobb volt volna szolgálnunk az Égyiptombelieknek, hogynem mint a pusztában halnunk meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Mózes pedig monda a népnek: Ne féljetek, megálljatok! és nézzétek az Úr szabadítását, a melyet ma cselekszik veletek; mert a mely Égyiptombelieket ma láttok, azokat soha többé nem látjátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Az Úr hadakozik ti érettetek; ti pedig veszteg legyetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'És monda az Úr Mózesnek: Mit kiáltasz hozzám? Szólj Izráel fiainak, hogy induljanak el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Te pedig emeld fel a te pálczádat és nyújtsd ki kezedet a tengerre és válaszd azt kétfelé, hogy Izráel fiai szárazon menjenek át a tenger közepén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Én pedig ímé megkeményítem az Égyiptombeliek szívét, hogy bemenjenek utánok, és megdicsőíttetem a Faraó által és az ő egész serege által, szekerei és lovasai által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'És megtudják az Égyiptombeliek, hogy én vagyok az Úr, ha majd megdicsőíttetem a Faraó által, az ő szekerei és lovasai által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Elindula azért az Istennek Angyala, a ki jár vala az Izráel tábora előtt, és méne mögéjök; a felhőoszlop is elindula előlök s mögéjök álla.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'És oda méne az Égyiptombeliek tábora és az Izráel tábora közé; így lőn a felhő és a setétség: az éjszakát pedig megvilágosítja vala. És egész éjszaka nem közelítettek egymáshoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'És kinyújtá Mózes az ő kezét a tengerre, az Úr pedig egész éjjel erős keleti széllel hajtá a tengert és szárazzá tevé a tengert, és kétfelé válának a vizek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'És szárazon menének az Izráel fiai a tenger közepébe, a vizek pedig kőfal gyanánt valának nékik jobbkezök és balkezök felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Az Égyiptombeliek pedig utánok nyomulának és bemenének a Faraó minden lovai, szekerei és lovasai a tenger közepébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'És lőn hajnalkor, rátekinte az Úr az Égyiptombeliek táborára a tűz- és felhő-oszlopból és megzavará az Égyiptombeliek táborát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'És megállítá szekereik kerekeit és nehezen vonszoltatá azokat. És mondának az Égyiptombeliek: Fussunk az Izráel elől, mert az Úr hadakozik érettök Égyiptom ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'És szóla az Úr Mózesnek: Nyújtsd ki kezedet a tengerre, hogy a vizek térjenek vissza az Égyiptombeliekre, az ő szekereikre s lovasaikra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'És kinyújtá Mózes az ő kezét a tengerre, és reggel felé visszatére a tenger az ő elébbi állapotjára; az Égyiptombeliek pedig eleibe futnak vala, és az Úr beleveszté az égyiptomiakat a tenger közepébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Visszatérének tehát a vizek és elboríták a szekereket és a lovasokat, a Faraónak minden seregét, melyek utánok bementek vala a tengerbe; egy sem marada meg közülök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'De Izráel fiai szárazon menének át a tenger közepén; a vizek pedig kőfal gyanánt valának nékik jobb- és balkezök felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'És megszabadítá az Úr azon a napon Izráelt az Égyiptombeliek kezéből; és látá Izráel a megholt Égyiptombelieket a tenger partján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'És látá Izráel azt a nagy dolgot, a melyet cselekedék az Úr Égyiptomban: félé azért a nép az Urat és hívének az Úrnak és Mózesnek, az ő szolgájának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Akkor éneklé Mózes és az Izráel fiai ezt az éneket az Úrnak, és szólának mondván: Éneklek az Úrnak, mert fenséges ő, lovat lovasával tengerbe vetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Erősségem az Úr és énekem, szabadítómmá lőn nekem; ez az én Istenem, őt dicsérem, atyámnak Istene, őt magasztalom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Vitéz harczos az Úr; az ő neve Jehova.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'A Faraónak szekereit és seregét tengerbe vetette, s válogatott harczosai belefúltak a veres tengerbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Elborították őket a hullámok, kő módjára merültek a mélységbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Jobbod, Uram, erő által dicsőül, jobbod, Uram, ellenséget összetör.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'Fenséged nagyságával zúzod össze támadóid, kibocsátod haragod s megemészti az őket mint tarlót.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Orrod lehelletétől feltorlódtak a vizek. És a futó habok fal módjára megálltak; a mélységes vizek megmerevültek a tenger szívében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'Az ellenség monda: Űzöm, utólérem őket, zsákmányt osztok, bosszúm töltöm rajtok. Kardomat kirántom, s kiirtja őket karom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Leheltél lehelleteddel s tenger borítá be őket: elmerültek, mint az ólom a nagy vizekben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Kicsoda az istenek közt olyan, mint te Uram? Kicsoda olyan, mint te, szentséggel dicső, félelemmel dícsérendő és csudatévő?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Kinyújtottad jobbkezedet, és elnyelé őket a föld.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Kegyelmeddel vezérled te megváltott népedet, hatalmaddal viszed be te szent lakóhelyedre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Meghallják ezt a népek és megrendülnek; Filisztea lakóit reszketés fogja el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Akkor megháborodának Edom fejedelmei, Moáb hatalmasait rettegés szállja meg, elcsügged a Kanaán egész lakossága.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Félelem és aggodalom lepi meg őket; karod hatalmától elnémulnak mint a kő, míg átvonul néped, Uram! Míg átvonul a nép, a te szerzeményed.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Beviszed s megtelepíted őket örökséged hegyén, melyet Uram, lakhelyűl magadnak készítél, szentségedbe Uram, melyet kezed építe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Az Úr uralkodik mind örökkön örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Mert bémenének a Faraó lovai, szekereivel és lovasaival együtt a tengerbe, és az Úr visszafordítá reájok a tenger vizét; Izráel fiai pedig szárazon jártak a tenger közepén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Akkor Miriám prófétaasszony, Áronnak nénje dobot vőn kezébe, és kimenének utánna mind az asszonyok dobokkal és tánczolva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'És felele nékik Miriám: Énekeljetek az Úrnak, mert fenséges ő, lovat lovasával tengerbe vetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Ennekutánna elindítá Mózes az Izráelt a veres tengertől, és menének Súr puszta felé; három napig menének a pusztában és nem találának vizet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'És eljutának Márába, de nem ihatják vala a vizet Márában, mivelhogy keserű vala. Azért is nevezék nevét Márának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'És zúgolódik vala a nép Mózes ellen, mondván: Mit igyunk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Ez pedig az Úrhoz kiálta, és mutata néki az Úr egy fát és beveté azt a vízbe, és a víz megédesedék. Ott ada néki rendtartást és törvényt és ott megkísérté.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'És monda: Ha a te Uradnak Istenednek szavára hűségesen hallgatsz és azt cselekeszed, a mi kedves az ő szemei előtt és figyelmezel az ő parancsolataira és megtartod minden rendelését: egyet sem bocsátok reád ama betegségek közül, a melyeket Égyiptomra bocsátottam, mert én vagyok az Úr, a te gyógyítód.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'És jutának Élimbe, és ott tizenkét forrás vala és hetven pálmafa; és tábort ütének ott a vizek mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'És elindulának Élimből és érkezék Izráel fiainak egész gyülekezete a Szin pusztájába, mely Élim között és Sinai között van, a második hónapnak tizenötödik napján, Égyiptom földéről való kijövetelök után.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'És zúgolódék Izráel fiainak egész gyülekezete Mózes és Áron ellen a pusztában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'S mondának nékik Izráel fiai: Bár megholtunk volna az Úr keze által Égyiptom földén, a mikor a húsos fazék mellett ülünk vala, a mikor jól lakhatunk vala kenyérrel; mert azért hoztatok ki minket ebbe a pusztába, hogy mind e sokaságot éhséggel öljétek meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'És monda az Úr Mózesnek: Ímé én esőképen bocsátok néktek kenyeret az égből; menjen ki azért a nép és szedjen naponként arra a napra valót, hogy megkísértsem: akar-é az én törvényem szerint járni, vagy nem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'A hatodik napon pedig úgy lesz, hogy mikor elkészítik a mit bevisznek, az kétannyi lesz, mint a mennyit naponként szedegettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'És monda Mózes és Áron Izráel minden fiainak: Estve megtudjátok, hogy az Úr hozott ki titeket Égyiptom földéről;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'Reggel pedig meglátjátok az Úr dicsőségét; mert meghallotta a ti zúgolódástokat az Úr ellen. De mik vagyunk mi, hogy mi ellenünk zúgolódtok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'És monda Mózes: Estve húst ád az Úr ennetek, reggel pedig kenyeret, hogy jól lakjatok; mert hallotta az Úr a ti zúgolódástokat, melylyel ellene zúgolódtatok. De mik vagyunk mi? Nem mi ellenünk van a ti zúgolódástok, hanem az Úr ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Áronnak pedig monda Mózes: Mondd meg az Izráel fiai egész gyülekezetének: Járuljatok az Úr elé; mert meghallotta a ti zúgolódástokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'És lőn, mikor beszéle Áron az Izráel fiai egész gyülekezetének, a puszta felé fordulának, és ímé az Úr dicsősége megjelenék a felhőben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'És szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'Hallottam az Izráel fiainak zúgolódását, szólj nékik mondván: Estennen húst esztek, reggel pedig kenyérrel laktok jól és megtudjátok, hogy én vagyok az Úr a ti Istentek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'És lőn, hogy estve fürjek jövének fel és ellepék a tábort, reggel pedig harmatszállás lőn a tábor körűl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Mikor pedig a harmatszállás megszűnék, ímé a pusztának színén apró gömbölyegek valának, aprók mint a dara a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'A mint megláták az Izráel fiai, mondának egymásnak: Mán ez! mert nem tudják vala mi az. Mózes pedig monda nékik: Ez az a kenyér, melyet az Úr adott néktek eledelül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Az Úr parancsolata pedig ez: Szedjen abból kiki a mennyit megehetik; fejenként egy ómert, a hozzátok tartozók száma szerint szedjen kiki azok részére, a kik az ő sátorában vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'És aképen cselekedének az Izráel fiai és szedének ki többet, ki kevesebbet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Azután megmérik vala ómerrel, és annak a ki többet szedett, nem vala fölöslege, és annak, a ki kevesebbet szedett, nem vala fogyatkozása: kiki annyit szedett, a mennyit megehetik vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Azt is mondá nékik Mózes: Senki ne hagyjon abból reggelre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'De nem hallgatának Mózesre, mert némelyek hagyának abból reggelre; és megférgesedék s megbüszhödék. Mózes pedig megharagudék reájok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Szedék pedig azt reggelenként, kiki a mennyit megehetik vala, mert ha a nap felmelegedett, elolvad vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'A hatodik napon pedig két annyi kenyeret szednek vala, két ómerrel egyre-egyre. Eljövének pedig a gyülekezet fejedelmei mindnyájan és tudtára adták azt Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Ő pedig monda nékik: Ez az, a mit az Úr mondott: A holnap nyugalom napja, az Úrnak szentelt szombat; a mit sütni akartok, süssétek meg, és a mit főzni akartok, főzzétek meg; a mi pedig megmarad, azt mind tegyétek el magatoknak reggelre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'És eltevék azt reggelre, a szerint a mint Mózes parancsolta vala, és nem büszhödék meg s féreg sem vala benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'És monda Mózes: Ma egyétek azt meg, mert ma az Úrnak szombatja van; ma nem találjátok azt a mezőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Hat napon szedjétek azt, de a hetedik napon szombat van, akkor nem lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'És lőn hetednapon: kimenének a nép közül, hogy szedjenek, de nem találának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'És monda az Úr Mózesnek: Meddig nem akarjátok megtartani az én parancsolataimat és törvényeimet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Lássátok meg! az Úr adta néktek a szombatot; azért ád ő néktek hatodnapon két napra való kenyeret. Maradjatok veszteg, kiki a maga helyén; senki se menjen ki az ő helyéből a hetedik napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'És nyugoszik vala a nép a hetedik napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Az Izráel háza pedig Mánnak nevezé azt; olyan vala az mint a kóriándrom magva, fehér; és íze, mint a mézes pogácsáé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'És monda Mózes: Ezt parancsolja az Úr: Egy teljes ómernyit tartsatok meg abból maradékaitok számára, hogy lássák a kenyeret, a mellyel éltettelek titeket a pusztában, mikor kihoztalak titeket Égyiptom földéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Áronnak pedig monda Mózes: Végy egy edényt és tégy bele egy teljes ómer Mánt és tedd azt az Úr eleibe, hogy megtartassék maradékaitok számára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'A mint parancsolta vala az Úr Mózesnek, eltevé azt Áron a bizonyságtétel ládája elé, hogy megtartassék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Az Izráel fiai pedig negyven esztendőn át evék a Mánt, míg lakó földre jutának; Mánt evének mind addig, míg a Kanaán földének határához jutának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Az ómer pedig az éfának tizedrésze.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'És elindula Izráel fiainak egész gyülekezete a Szin pusztájából, az Úr rendeléséhez képest az ő útjok rendje szerint és tábort ütének Refidimben. De a népnek nem vala inni való vize.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Verseng vala azért a nép Mózessel és mondák: Adjatok nékünk vizet, hogy igyunk. És monda nékik Mózes: Miért versengtek én velem? Miért kísértitek az Urat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'És szomjúhozik vala ott a nép a vízre és zúgolódék a nép Mózes ellen és monda: Miért hoztál ki minket Égyiptomból? hogy szomjúsággal ölj meg minket, gyermekeinket és barmainkat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Mózes pedig az Úrhoz kiálta mondván: Mit cselekedjem ezzel a néppel? Kevés hijja, hogy meg nem köveznek engemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'És az Úr monda Mózesnek: Eredj el a nép előtt és végy magad mellé Izráel vénei közűl; pálczádat is, melylyel a folyót megsujtottad, vedd kezedbe és indulj el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Ímé én oda állok te elődbe a sziklára a Hóreben, és te sujts a sziklára, és víz jő ki abból, hogy igyék a nép. És úgy cselekedék Mózes Izráel vénei szeme láttára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'És nevezé annak a helynek nevét Masszának és Méribának, Izráel fiainak versengéséért, és mert kísértették az Urat, mondván: Vajjon köztünk van-é az Úr vagy nincsen?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Eljöve pedig Amálek és hadakozék Izráel ellen Refidimben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'És monda Mózes Józsuénak: Válaszsz nékünk férfiakat és menj el, ütközzél meg Amálekkel. Holnap én a halom tetejére állok és az Isten pálczája kezemben lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'És úgy cselekedék Józsué a mint mondotta vala néki Mózes, megütközék Amálekkel: Mózes, Áron és Húr pedig felmenének a halom tetejére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'És lőn, mikor Mózes felemelé kezét, Izráel győz vala; mikor pedig leereszté kezét, Amálek győz vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Mikor azért Mózes kezei elnehezedének, követ hozának és alája tevék, hogy arra űljön; Áron pedig és Húr tartják vala az ő kezeit, egy felől az egyik, más felől a másik, és felemelve maradának kezei a nap lementéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Józsué pedig leveré Amáleket és az ő népét fegyver élivel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'És monda az Úr Mózesnek: Írd meg ezt emlékezetül könyvbe és add tudtára Józsuénak, hogy mindenestől eltörlöm Amálek emlékezetét az ég alól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'És építe Mózes oltárt és nevezé nevét Jehova-Niszszi-nek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'És monda: Megesküdött az Úr, hogy harcza lesz az Úrnak Amálek ellen nemzetségről nemzetségre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'És meghallá Jethró, Midián papja, Mózes ipa, mindazt a mit Isten Mózessel és Izráellel az ő népével cselekedett vala, hogy kihozta az Úr Izráelt Égyiptomból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'És felvevé Jethró, a Mózes ipa Czipporát, a Mózes feleségét – miután haza bocsátotta őt –');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'És az ő két fiát is, a kik közűl az egyiknek neve Gersom, mert azt mondotta vala: Bujdosó valék az idegen földön;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'A másiknak neve pedig Eliézer; mert: Az én atyám Istene segítségül volt nékem és megszabadított engem a Faraó fegyverétől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Eljuta tehát Jethró, a Mózes ipa, az ő fiaival és feleségével Mózeshez a pusztába, a hol ő táborozott vala az Isten hegye mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'És megizené Mózesnek: Én Jethró a te ipad megyek te hozzád a te feleségeddel és az ő két fia is ő vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Kiméne azért Mózes az ő ipa eleibe és meghajtá magát és megcsókolá őt; és megkérdék egymást állapotuk felől és bemenének a sátorba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'És elbeszélé Mózes az ő ipának mind azt, a mit az Úr a Faraóval és az Égyiptombeliekkel cselekedett vala Izráelért; mindazt a sok bajt, a melyek útközben érték vala őket, és mimódon szabadította meg őket az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'És örvendeze Jethró mindazon a jón, a mit az Úr az Izráellel cselekedett vala, hogy megszabadítá őt az Égyiptombeliek kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'És monda Jethró: Áldott legyen az Úr, a ki megszabadított titeket az Égyiptombeliek kezéből és a Faraó kezéből; a ki megszabadította a népet az Égyiptombeliek keze alól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Most tudom már, hogy nagyobb az Úr minden istennél; mert az lett vesztökre, a mivel ellenök vétkeztek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'És Jethró, a Mózes ipa égőáldozattal és véresáldozattal áldozék az Istennek; Áron pedig és Izráel minden vénei jövének, hogy kenyeret egyenek a Mózes ipával Isten előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'És lőn másod napon, leűle Mózes törvényt tenni a népnek; a nép pedig áll vala Mózes előtt reggeltől estig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'S a mikor látja vala Mózes ipa mind azt, a mit ő a néppel cselekedék, monda: Mi dolog az, a mit te a néppel cselekszel; miért űlsz te egymagad, mind az egész nép pedig előtted áll reggeltől estig?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'És monda Mózes az ő ipának: Mert a nép Isten akaratát tudakolni jön hozzám;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Ha ügyök-bajok van, én hozzám jőnek és törvényt teszek az ember között és felebarátja között és tudtára adom az Isten végezéseit és törvényeit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Mózes ipa pedig monda néki: Nem jó az, a mit te cselekszel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Felettébb kifáradsz te is, ez a nép is, a mely veled van; mert erőd felett való dolog ez, nem végezheted azt egymagad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Most azért hallgass az én szavamra, tanácsot adok néked és az Isten veled lesz. Te légy a népnek szószólója az Isten előtt, és te vidd az ügyeket Isten eleibe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'És tanítsd őket a rendeletekre és törvényekre és add tudtokra az útat, a melyen járniok kell és a tenni valót, a melyet tenniök kell.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'És szemelj ki magad az egész nép közűl derék, istenfélő férfiakat, igazságos férfiakat, a kik gyűlölik a haszonlesést és tedd közöttük előljárókká, ezeredesekké, századosokká, ötvenedesekké és tizedesekké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'Ezek tegyenek ítéletet a népnek minden időben, úgy hogy minden nagyobb ügyet te elődbe hozzanak, minden csekélyebb dologban pedig ők ítéljenek; így könnyítve lesz rajtad, ha azt veled együtt hordozzák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Ha ezt cselekszed és az Isten is parancsolja néked: megállhatsz és az egész nép is helyére jut békességben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'És hallgata Mózes az ő ipa szavára és mindazt megtevé, a mit mondott vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'És választa Mózes az egész Izráelből derék férfiakat és a nép fejeivé tevé őket, ezeredesekké, századosokká, ötvenedesekké, és tizedesekké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'És ítélik vala a népet minden időben; a nehéz dolgokat Mózes elé viszik vala, minden kisebb dologban pedig ők ítélnek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'És elbocsátá Mózes az ő ipát, és ez elméne hazájába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'A harmadik hónapban azután hogy kijöttek vala Izráel fiai Égyiptom földéről, azon a napon érkezének a Sinai pusztába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Refidimből elindulván, érkezének a Sinai pusztába és táborba szállának a pusztában; a hegygyel átellenben szálla pedig ott táborba az Izráel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Mózes pedig felméne az Istenhez, és szóla hozzá az Úr a hegyről, mondván: Ezt mondd a Jákób házanépének és ezt add tudtára az Izráel fiainak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'Ti láttátok, a mit Égyiptommal cselekedtem, hogy hordoztalak titeket sas szárnyakon és magamhoz bocsátottalak titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Mostan azért ha figyelmesen hallgattok szavamra és megtartjátok az én szövetségemet, úgy ti lesztek nékem valamennyi nép közt az enyéim; mert enyim az egész föld.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'És lesztek ti nékem papok birodalma és szent nép. Ezek azok az ígék, melyeket el kell mondanod Izráel fiainak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Elméne azért Mózes és egybehívá a nép véneit és eleikbe adá mindazokat a beszédeket, melyeket parancsolt vala néki az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'És az egész nép egy akarattal felele és monda: Valamit rendelt az Úr, mind megteszszük. És megvivé Mózes az Úrnak a nép beszédét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'És monda az Úr Mózesnek: Ímé én hozzád megyek a felhő homályában, hogy hallja a nép mikor beszélek veled és higyjenek néked mindörökké. És elmondá Mózes az Úrnak a nép beszédét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Az Úr pedig monda Mózesnek: Eredj el a néphez és szenteld meg őket ma, meg holnap és hogy mossák ki az ő ruháikat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'És legyenek készek harmadnapra; mert harmadnapon leszáll az Úr az egész nép szeme láttára a Sinai hegyre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'És vess határt a népnek köröskörűl, mondván: Vigyázzatok magatokra, hogy a hegyre fel ne menjetek s még a szélét se érintsétek; mindaz, a mi a hegyet érinti, halállal haljon meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Ne érintse azt kéz, hanem kővel köveztessék meg, vagy nyillal nyilaztassék le; akár barom, akár ember, ne éljen. Mikor a kürt hosszan hangzik, akkor felmehetnek a hegyre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Leszálla azért Mózes a hegyről a néphez, és megszentelé a népet, és megmosák az ő ruháikat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'És monda a népnek: Legyetek készen harmadnapra; asszonyhoz ne közelítsetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'És lőn harmadnapon virradatkor, mennydörgések, villámlások és sűrű felhő lőn a hegyen és igen erős kürtzengés; és megréműle mind az egész táborbeli nép.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'És kivezeté Mózes a népet a táborból az Isten eleibe és megállának a hegy alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Az egész Sinai hegy pedig füstölög vala, mivelhogy leszállott arra az Úr tűzben és felmegy vala annak füstje, mint a kemenczének füstje; és az egész hegy nagyon reng vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'És a kürt szava mindinkább erősödik vala; Mózes beszél vala és az Isten felel vala néki hangosan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Leszálla tehát az Úr a Sinai hegyre, a hegy tetejére, és felhívá az Úr Mózest a hegy tetejére, Mózes pedig felméne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'És monda az Úr Mózesnek: Menj alá, intsd meg a népet, hogy ne törjön előre az Urat látni, mert közűlök sokan elhullanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'És a papok is, a kik az Úr eleibe járulnak, szenteljék meg magokat, hogy reájok ne rontson az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Mózes pedig monda az Úrnak: Nem jöhet fel a nép a Sinai hegyre, mert te magad intettél minket, mondván: Vess határt a hegy körűl, és szenteld meg azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'De az Úr monda néki: Eredj, menj alá, és jőjj fel te és Áron is veled; de a papok és a nép ne törjenek előre, hogy feljőjjenek az Úrhoz; hogy reájok ne rontson.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Aláméne azért Mózes a néphez, és megmondá nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'És szólá Isten mindezeket az igéket, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, 'Én, az Úr, vagyok a te Istened, a ki kihoztalak téged Égyiptomnak földéről, a szolgálat házából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Ne legyenek néked idegen isteneid én előttem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Ne csinálj magadnak faragott képet, és semmi hasonlót azokhoz, a melyek fenn az égben, vagy a melyek alant a földön, vagy a melyek a vizekben a föld alatt vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Ne imádd és ne tiszteld azokat; mert én, az Úr a te Istened, féltőn-szerető Isten vagyok, a ki megbüntetem az atyák vétkét a fiakban, harmad és negyediziglen, a kik engem gyűlölnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'De irgalmasságot cselekszem ezeriziglen azokkal, a kik engem szeretnek, és az én parancsolatimat megtartják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Az Úrnak a te Istenednek nevét hiába fel ne vedd; mert nem hagyja azt az Úr büntetés nélkül, a ki az ő nevét hiába felveszi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Megemlékezzél a szombatnapról, hogy megszenteljed azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Hat napon át munkálkodjál, és végezd minden dolgodat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'De a hetedik nap az Úrnak a te Istenednek szombatja: semmi dolgot se tégy azon se magad, se fiad, se leányod, se szolgád, se szolgálóleányod, se barmod, se jövevényed, a ki a te kapuidon belől van;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Mert hat napon teremté az Úr az eget és a földet, a tengert és mindent, a mi azokban van, a hetedik napon pedig megnyugovék. Azért megáldá az Úr a szombat napját, és megszentelé azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Tiszteld atyádat és anyádat, hogy hosszú ideig élj azon a földön, a melyet az Úr a te Istened ád te néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Ne ölj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Ne paráználkodjál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Ne lopj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Ne tégy a te felebarátod ellen hamis tanúbizonyságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Ne kívánd a te felebarátodnak házát. Ne kívánd a te felebarátodnak feleségét, se szolgáját, se szolgálóleányát, se ökrét, se szamarát, és semmit, a mi a te felebarátodé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Az egész nép pedig látja vala a mennydörgéseket, a villámlásokat, a kürt zengését és a hegy füstölgését. És látja vala a nép, és megrémüle, és hátrább álla.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'És mondának Mózesnek: Te beszélj velünk, és mi hallgatunk; de az Isten ne beszéljen velünk, hogy meg ne haljunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Mózes pedig monda a népnek: Ne féljetek; mert azért jött az Isten, hogy titeket megkísértsen, és hogy az ő félelme legyen előttetek, hogy ne vétkezzetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Távol álla azért a nép, Mózes pedig közelebb méne a felhőhöz, melyben az Isten vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'És monda az Úr Mózesnek: Ezt mondd az Izráel fiainak: Magatok láttátok, hogy az égből beszéltem veletek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Ne csináljatok én mellém ezüst isteneket, és arany isteneket se csináljatok magatoknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Földből csinálj nékem oltárt, és azon áldozd a te égő- és hálaáldozatodat, juhaidat és ökreidet. Valamely helyen akarom, hogy az én nevemről megemlékezzetek, elmegyek tehozzád és megáldalak téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Ha pedig kövekből csinálsz nékem oltárt, ne építsd azt faragott kőből: mert a mint faragó vasadat rávetetted, megfertőztetted azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Lépcsőkön se menj fel az én oltáromhoz, hogy a te szemérmed fel ne fedeztessék azon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'Ezek pedig azok a rendeletek, a melyeket eleikbe kell terjesztened:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Ha héber szolgát vásárolsz, hat esztendeig szolgáljon, a hetedikben pedig szabaduljon fel ingyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Ha egyedűl jött, egyedűl menjen el; ha feleséges ember, menjen el vele a felesége is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Ha az ő ura adott néki feleséget, és ez fiakat vagy leányokat szűlt néki: az asszony, gyermekeivel együtt legyen az ő uráé; ő pedig egyedűl menjen el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'De ha a szolga azt mondaná: Szeretem az én uramat, az én feleségemet és fiaimat, nem akarok felszabadulni:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'Akkor vigye őt az ő ura a bírák elé, és állítsa az ajtóhoz vagy az ajtófélhez, és az ő ura fúrja által az ő fülét árral; és szolgálja őt mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'És ha valaki az ő leányát szolgálóul adja el, ne úgy menjen el, mint a szolgák mennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Ha nem tetszik az ő urának, hogy eljegyezze őt magának, akkor váltassa ki; arra, hogy idegen népnek eladja, nincs hatalma, mivel hűtelen volt hozzá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Ha pedig a fiának jegyzi el őt: a leányok törvénye szerint cselekedjék vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Ha mást vesz magának: ennek ételét, ruházatát és házasságbeli igazát alább ne szállítsa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Ha ezt a hármat nem cselekszi vele: akkor menjen az el ingyen, fizetés nélkűl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'A ki úgy megver valakit, hogy meghal, halállal lakoljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'De ha nem leselkedett, hanem Isten ejtette kezébe: úgy helyet rendelek néked, a hova meneküljön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Ha pedig valaki szándékosan tör felebarátja ellen, hogy azt orvúl megölje, oltáromtól is elvidd azt a halálra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'A ki megveri az ő atyját vagy anyját, halállal lakoljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'A ki embert lop, és eladja azt, vagy kezében kapják, halállal lakoljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'A ki szidalmazza az ő atyját vagy anyját, halállal lakoljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'És ha férfiak összevesznek, és megüti valaki az ő felebarátját kővel vagy öklével, és nem hal meg, hanem ágyba esik:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'Ha felkél, és mankóján kinn jár: ne legyen büntetve az, a ki megütötte; csupán fekvéséért fizessen és gyógyíttassa meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Ha pedig valaki úgy üti meg szolgáját vagy szolgálóját bottal, hogy az meghal keze alatt, büntettessék meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'De ha egy vagy két nap életben marad, ne büntettessék meg, mert pénze ára az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Ha férfiak veszekednek és meglöknek valamely terhes asszonyt, úgy hogy idő előtt szűl, de egyéb veszedelem nem történik: bírságot fizessen a szerint, a mint az asszony férje azt reá kiveti, de bírák előtt fizessen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'De ha veszedelem történik: akkor életért életet adj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'Szemet szemért, fogat fogért, kezet kézért, lábat lábért;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'Égetést égetésért, sebet sebért, kéket kékért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Ha valaki az ő szolgájának szemét, vagy szolgálójának szemét úgy üti meg, hogy elpusztul, bocsássa azt szabadon az ő szeméért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Ha pedig szolgájának fogát, vagy szolgálójának fogát üti ki, bocsássa azt szabadon az ő fogáért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Ha férfit vagy asszonyt öklel meg egy ökör, úgy hogy meghal: kővel köveztessék meg az ökör, és húsát meg ne egyék; de az ökörnek ura ártatlan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'De ha az ökör azelőtt is öklelős volt, és annak urát megintették, és még sem őrizte azt, és férfit vagy asszonyt ölt meg: az ökör köveztessék meg, és az ura is halállal lakoljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Ha pénzváltságot vetnek reá, fizessen lelke váltságáért annyit, a mennyit reá kivetnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Akár fiút ökleljen meg, akár leányt ökleljen meg: e szerint a rendelet szerint kell cselekedni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Ha szolgát öklel meg az ökör vagy szolgálót: adassék azok urának harmincz ezüst siklus, az ökör pedig köveztessék meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Ha pedig valaki vermet nyit meg, vagy ha valaki vermet ás, és nem fedi azt be, és ökör vagy szamár esik bele:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'A verem ura fizessen; pénzül térítse meg azok urának, a hulla pedig legyen az övé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'És ha valakinek ökre megdöfi az ő felebarátja ökrét, úgy hogy az elpusztul: adják el az eleven ökröt, és az árát osszák meg, és a hullát is osszák el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Vagy ha tudták, hogy az ökör már azelőtt öklelős volt, és nem őrizte azt annak ura: fizessen ökröt az ökörért, a hulla pedig az övé legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Ha valaki ökröt vagy bárányt lop, és levágja vagy eladja azt: öt barmot fizessen egy ökörért, és négy juhot egy bárányért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Ha ház-fölverésen kapják a tolvajt, és úgy megverik, hogy meghal, nincs vérbűn miatta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Ha reá sütött a nap, vérbűn van miatta: fizessen; ha nincs néki: adassék el tolvajságáért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Ha elevenen kapják kezében a lopott jószágot, akár ökör, akár szamár, akár juh: két annyit fizessen érette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Ha valaki mezőt vagy szőlőt étet le, úgy hogy barmát elereszti, és az a más mezején legel: mezejének javából és szőlőjének javából fizesse meg a kárt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Ha tűz támad, és tövisbe kap, és megég az asztag, vagy a lábon álló gabona, vagy a mező: fizesse meg a kárt, a ki a tüzet gyujtotta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Ha valaki pénzt vagy edényeket ád felebarátjának megőrzés végett, és ellopják annak a férfiúnak házából: ha megtalálják a tolvajt, fizessen kétannyit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Ha nem találják meg a tolvajt, a ház urát vigyék a bírák eleibe: hogy nem nyújtotta-é ki kezét az ő felebarátja vagyonára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Akármi bűn dolgában, akár ökör, akár szamár, akár juh, akár ruha, akármi elveszett jószág az, a miről azt mondja: ez az; mindkettőjük ügye a bírák eleibe menjen, és a kit a bírák bűnösnek mondanak, fizessen két annyit az ő felebarátjának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'Ha valaki szamarat, vagy ökröt, vagy bárányt, vagy akármiféle barmot ád az ő felebarátja gondviselése alá, és az elhull, vagy megsérül, vagy elhajtatik, úgy hogy senki sem látta:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'Az Úrra való esküvés legyen kettejök közt, hogy nem nyújtotta-é ki kezét felebarátja vagyonára; és ezt fogadja el annak ura, és az semmit se fizessen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Ha pedig ellopták tőle: megfizesse az urának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Ha széttépetett, hozza el azt bizonyságul; a széttépettet nem fizeti meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Ha pedig valaki kölcsön kér az ő felebarátjától, és az megsérül vagy elhull urának távollétében: fizesse meg a kárt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Ha ura vele van, nem fizet; ha bérbe adatott, bérébe megy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Ha valaki hajadont csábít el, a ki nincs eljegyezve, és vele hál: jegyajándékkal jegyezze azt el magának feleségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Ha annak atyja nem akarja azt néki adni: annyi pénzt adjon, a mennyi a hajadonok jegyajándéka.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Varázsló asszonyt ne hagyj életben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'A ki barommal közösül, halállal lakoljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'A ki isteneknek áldozik, nem csupán az Úrnak, megölettessék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'A jövevényen ne hatalmaskodjál, és ne nyomorgasd azt, mert jövevények voltatok Égyiptom földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Egy özvegyet vagy árvát se nyomorítsatok meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Ha nyomorgatod azt, és hozzám kiált, meghallgatom az ő kiáltását.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'És felgerjed haragom, és megöllek titeket fegyverrel, és a ti feleségeitek özvegyekké lésznek, a ti fiaitok pedig árvákká.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Ha pénzt adsz kölcsön az én népemnek, a szegénynek a ki veled van; ne légy hozzá olyan, mint a hitelező; ne vessetek reá uzsorát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Ha zálogba veszed a te felebarátod felső ruháját: naplemente előtt visszaadd azt néki:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'Mert egyetlen takarója, testének ruhája az: miben háljon? Bizony, ha én hozzám kiált, meghallgatom; mert én irgalmas vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'A bírákat ne szidalmazd, és néped fejedelmét ne átkozd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Gabonáddal és boroddal ne késlekedjél; fiaid elsőszülöttét nékem add.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Hasonlóképen cselekedjél ökröddel, juhoddal; hét napig legyen az ő anyjával, a nyolczadik napon nékem add azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'És szent emberek legyetek én előttem; a mezőn széttépett húst meg ne egyétek; az ebnek vessétek azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Hazug hírt ne hordj; ne fogj kezet a gonoszszal, hogy hamis tanú ne légy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Ne indulj a sokaság után a gonoszra, és peres ügyben ne vallj a sokasággal tartva, annak elfordítására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Szegénynek se kedvezz az ő peres ügyében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Ha előltalálod ellenséged eltévedt ökrét vagy szamarát: hajtsd vissza néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Ha látod, hogy annak a szamara, a ki téged gyűlöl, a teher alatt fekszik, vigyázz, rajta ne hagyd; oldd le azt ő vele együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'A te szegényednek igazságát el ne fordítsd az ő perében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'A hazug beszédtől távol tartsd magad, és az ártatlant s az igazat meg ne öld; mert én nem adok igazat a gonosznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Ajándékot el ne végy: mert az ajándék megvakítja a szemeseket, és elfordítja az igazak ügyét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'A jövevényt ne nyomorgasd; hiszen ti ismeritek a jövevény életét, mivelhogy jövevények voltatok Égyiptom földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Hat esztendeig vesd be a te földedet és takard be annak termését;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'A hetedikben pedig pihentesd azt, és hagyd úgy, hogy egyék meg a te néped szegényei; a mi pedig ezektől megmarad, egye meg a mezei vad. E képen cselekedjél szőlőddel és olajfáddal is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Hat napon át végezd dolgaidat, a hetedik napon pedig nyúgodjál, hogy nyúgodjék a te ökröd és szamarad, és megpihenjen a te szolgálód fia és a jövevény.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Mindazt, a mit néktek mondtam, megtartsátok, és idegen istenek nevét ne emlegessétek; ne hallassék az a te szádból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Háromszor szentelj nékem innepet esztendőnként.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'A kovásztalan kenyér innepét tartsd meg; hét nap egyél kovásztalan kenyeret, a mint megparancsoltam néked, az Abib hónap ideje alatt; mert akkor jöttél ki Égyiptomból: és üres kézzel senki se jelenjék meg színem előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'És az aratás innepét, munkád zsengéjét, a melyet elvetettél a mezőn; és a takarodás innepét az esztendő végén, a mikor termésedet betakarítod a mezőről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Esztendőnként háromszor jelenjék meg minden férfiad az Úr Isten színe előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Ne ontsd ki az én áldozatom vérét kovászos kenyér mellett, és ünnepi áldozatom kövére meg ne maradjon reggelig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'A te földed zsengéjének elsejét vidd el a te Uradnak Istenednek házába. Ne főzd meg a gödölyét az ő anyjának tejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Ímé én Angyalt bocsátok el te előtted, hogy megőrízzen téged az útban, és bevigyen téged arra a helyre, a melyet elkészítettem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Vigyázz magadra előtte, és hallgass az ő szavára; meg ne bosszantsd őt, mert nem szenvedi el a ti gonoszságaitokat; mert az én nevem van ő benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Mert ha hallgatándasz az ő szavára; és mindazt megcselekedénded, a mit mondok: akkor ellensége lészek a te ellenségeidnek, és szorongatom a te szorongatóidat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Mert az én Angyalom te előtted megyen és beviszen téged az Emoreusok, Khitteusok, Perizeusok, Kananeusok, Khivveusok és Jebuzeusok közé, és kiirtom azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Ne imádd azoknak isteneit és ne tiszteld azokat, és ne cselekedjél az ő cselekedeteik szerint; hanem inkább döntögesd le azokat és tördeld össze bálványaikat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'És szolgáljátok az Urat a ti Istenteket, akkor megáldja a te kenyeredet és vizedet; és eltávolítom ti közűletek a nyavalyát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'El sem vetél, meddő sem lesz a te földeden semmi; napjaid számát teljessé teszem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Az én rettentésemet bocsátom el előtted, és minden népet megrettentek, a mely közé mégy, és minden ellenségedet elfutamtatom előtted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Darazsat is bocsátok el előtted, és kiűzi előled a Khivveust, Kananeust és Khitteust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'De nem egy esztendőben űzöm őt ki előled, hogy a föld pusztává ne legyen, és meg ne sokasodjék ellened a mezei vad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Lassan-lassan űzöm őt ki előled, míg megszaporodol és bírhatod a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'És határodat a veres tengertől a Filiszteusok tengeréig vetem, és a pusztától fogva a folyóvízig: mert kezeitekbe adom annak a földnek lakosait, és kiűzöd azokat előled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Ne köss szövetséget se azokkal, se az ő isteneikkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Ne lakjanak a te földeden, hogy bűnbe ne ejtsenek téged ellenem: mert ha az ő isteneiket szolgálnád, vesztedre lenne az néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'És monda Mózesnek: Jőjj fel az Úrhoz te és Áron, Nádáb és Abihu, és az Izráel vénei közül hetvenen, és hajtsátok meg magatokat előtte távolról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'És csak Mózes közeledjék az Úrhoz, amazok pedig ne közeledjenek, és a nép se jőjjön fel vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Elméne azért Mózes, és elbeszélé a népnek az Úr minden beszédét és minden rendelését; az egész nép pedig egyező szóval felele, mondván: Mindazokat a dolgokat, a melyeket az Úr parancsolt, megcselekeszszük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Mózes pedig felírá az Úrnak minden beszédét, és felkele reggel és oltárt építe a hegy alatt, és tizenkét oszlopot, az Izráel tizenkét nemzetsége szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Azután elküldé az Izráel fiainak ifjait, és áldozának égő áldozatokat, és hálaáldozatul tulkokat ölének az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Mózes pedig vevé a vérnek felét, és tölté a medenczékbe: a vérnek másik felét pedig az oltárra hinté.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Azután vevé a szövetség könyvét, és elolvasá a nép hallatára; azok pedig mondának: Mindent megteszünk, a mit az Úr parancsolt, és engedelmeskedünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Mózes pedig vevé a vért, és ráhinté a népre, és monda: Ímé a szövetségnek vére, melyet az Úr kötött ti veletek, mindama beszédek szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Azután felméne Mózes és Áron, Nádáb és Abihu, és az Izráel vénei közül hetvenen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'És láták az Izráel Istenét, és annak lábai alatt valami zafir fényű tárgy vala, és olyan tiszta, mint maga az ég.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'És Izráel fiainak e választottjaira nem bocsátá kezét: jóllehet látták az Istent, mindazáltal ettek és ittak is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'És szóla az Úr Mózesnek: Jőjj fel én hozzám a hegyre és maradj ott. És átadom néked a kőtáblákat, és a törvényt és a parancsolatot, a melyeket írtam, hogy azokra megtaníttassanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Felkele azért Mózes és az ő szolgája Józsué, és felméne Mózes az Isten hegyére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'A véneknek pedig monda: Várjatok itt reánk, míg visszatérünk hozzátok: Ímé Áron és Húr veletek vannak; a kinek valami ügye van, ő hozzájok menjen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Akkor felméne Mózes a hegyre; és felhő borítá el a hegyet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'És az Úr dicsősége szálla alá a Sinai hegyre, és felhő borítá azt hat napon át; a hetedik napon pedig szólítá Mózest a felhő közepéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Az Úr dicsőségének jelensége pedig olyan vala az Izráel fiainak szeme előtt, mint emésztő tűz, a hegy tetején.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'És beméne Mózes a felhő közepébe, és felméne a hegyre, és negyven nap és negyven éjjel vala Mózes a hegyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'És szóla az Úr Mózeshez, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Szólj az Izráel fiainak, hogy szedjenek nékem ajándékokat; minden embertől, a kit szíve hajt arra, szedjetek nékem ajándékokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Ez pedig az az ajándék, a mit tőlök szedjetek: arany és ezüst és réz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'És kék, és bíborpiros, és karmazsinszinű fonal, meg len fonal, és kecskeszőr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'És veresre festett kosbőrök, és borzbőrök, és sittim-fa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'Mécsbe való olaj, kenet-olajhoz való arómák, és füstöléshez való fűszerek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'Ónix-kövek és foglalni való kövek, az efódhoz és a hósenhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'És készítsenek nékem szent hajlékot, hogy ő közöttök lakozzam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Mindenestől úgy csináljátok, a mint én megmutatom néked a hajléknak formáját, és annak minden edényeinek formáját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'És csináljanak egy ládát sittim-fából; harmadfél sing hosszút, másfél sing széleset, és másfél sing magasat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'Borítsd meg azt tiszta aranynyal, belől is kivül is megborítsd azt, és csinálj reá köröskörűl arany pártázatot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'És önts ahhoz négy arany karikát, és illeszd azokat a négy szegeletére; egyik oldalára is két karikát, a másik oldalára is két karikát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Csinálj rúdakat is sittim-fából, és azokat is megborítsd arannyal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'És a rúdakat dugd a láda oldalain levő karikákba, hogy azokon hordozzák a ládát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'A rúdak álljanak a láda karikáiban; ne vegyék ki azokból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'És a bizonyságot, a melyet néked adok, tedd a ládába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Csinálj fedelet is tiszta aranyból: harmadfél sing hosszút, és másfél sing széleset.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Csinálj két Kérubot is aranyból, vert aranyból csináld azokat a fedélnek két végére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'Az egyik Kérubot csináld az egyik végére innen, a másik Kérubot a másik végére onnan: a fedélből csináljátok ki a Kérubokat annak két végén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'A Kérubok pedig terjeszszék ki szárnyaikat fölfelé, betakarva szárnyaikkal a fedelet; arczaik egymásfelé legyenek; a Kérubok arczai a fedél felé forduljanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'A fedelet pedig helyezd a ládára felül, a ládába pedig tedd a bizonyságot, a melyet adok néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Ott jelenek meg néked, és szólok hozzád a fedél tetejéről, a két Kérub közül, melyek a bizonyság ládája felett vannak, mindazokról, a miket általad parancsolok az Izráel fiainak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Csinálj asztalt is sittim-fából, két sing hosszút, egy sing széleset, és másfél sing magasat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'És borítsd be azt tiszta aranynyal, és csinálj reá köröskörül arany pártázatot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Csinálj reá köröskörűl egy tenyérnyi karájt, karajára pedig csinálj köröskörűl arany pártázatot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Négy arany karikát is csinálj hozzá, és illeszd a karikákat a négy lábának négy szegletére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'A karáj mellett legyenek a karikák rúdtartókul, hogy hordozhassák az asztalt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Azokat a rúdakat is sittim-fából csináld és aranynyal borítsd be, és azokon hordozzák az asztalt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Készítsd el tálait is, csészéit is, kancsóit is, kelyheit is, a melyekkel italáldozatot áldoznak; tiszta aranyból csináld azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'És tégy az asztalra szent kenyeret, mely mindenkor előttem legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Csinálj gyertyatartót is tiszta aranyból; vert aranyból készüljön a gyertyatartó; annak szára, ága csészéi, gombjai és virágai ugyanabból legyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Hat ág jőjjön ki oldalaiból; három gyertyatartó-ág az egyik oldalból, és három gyertyatartó-ág a másik oldalból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Mandolavirág formájú három csésze az egyik ágon, gombbal és virággal; és mandolavirág formájú három csésze a másik ágon is, gombbal és virággal; így legyen a gyertyatartóból kijövő mind a hat ágon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'A gyertyatartón pedig négy mandolavirág formájú csésze legyen, gombjaival és virágaival.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'Gomb legyen a belőle kijövő két ág alatt; ismét gomb a belőle kijövő két ág alatt, és ismét gomb a belőle kijövő két ág alatt: így a gyertyatartóból kijövő mind a hat ág alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Gombjaik és ágaik magából legyenek; egy darab tiszta aranyból legyen verve az egész.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Csinálj hozzá hét mécset is, és úgy rakják fel mécseit, hogy előre világítsanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Hamvvevői és hamutartói is tiszta aranyból legyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Egy tálentom tiszta aranyból csinálják azt, mindezeket az eszközöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Vigyázz, hogy arra a formára csináld, a mely a hegyen mutattatott néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'A hajlékot pedig tíz kárpitból csináld: sodrott lenből, és kék, és bíborpiros, és karmazsin színűből, Kérubokkal, mestermunkával készítsd azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Egy-egy kárpit hossza huszonnyolcz sing legyen, egy-egy kárpit szélessége pedig négy sing; egy mértéke legyen mindenik kárpitnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Öt kárpit legyen egymással egybefoglalva, ismét öt kárpit egymással egybefoglalva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'És csinálj hurkokat kék lenből az egyik kárpit szélén, a mely az egybefoglaltak között szélről van; ugyanezt csináld a szélső kárpit szélével a másik egybefoglalásban is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Ötven hurkot csinálj az egyik kárpiton; ötven hurkot csinálj ama kárpit szélén is, a mely a másik egybefoglalásban van; egyik hurok a másiknak általellenében legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Csinálj ötven arany horgocskát is, és e horgocskákkal foglald össze egyik kárpitot a másikkal, hogy a hajlék egygyé legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Ezután csinálj kecskeszőr kárpitokat sátorul a hajlék fölé; tizenegy kárpitot csinálj ilyet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Egy kárpit hossza harmincz sing legyen, szélessége pedig egy kárpitnak négy sing; egy mértéke legyen a tizenegy kárpitnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'És foglald egybe az öt kárpitot külön, és a hat kárpitot külön; a hatodik kárpitot pedig kétrét hajtsd a sátor elejére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'És csinálj ötven hurkot az egyik kárpit szélén, a mely az egybefoglaltak között szélről van; és ötven hurkot a kárpit szélén a másik egybefoglalásban is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Csinálj ötven rézhorgocskát is, és akaszd a horgocskákat a hurkokba, és foglald egybe a sátort, hogy egygyé legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'A sátor kárpitjának fölösleges része, a fölösleges kárpitnak fele csüggjön alá a hajlék hátulján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'Egy singnyi pedig egyfelől, és egy singnyi másfelől, abból, a mi a sátor kárpitjainak hosszában fölösleges, bocsáttassék alá a hajlék oldalain egyfelől is, másfelől is, hogy befedje azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Csinálj a sátornak takarót is veresre festett kosbőrökből, és e fölé is egy takarót borzbőrökből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Csinálj a hajlékhoz deszkákat is sittim-fából, felállogatva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'A deszka hossza tíz sing legyen; egy-egy deszka szélessége pedig másfél sing.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Egy-egy deszkának két csapja legyen, egyik a másiknak megfelelő; így csináld a hajlék minden deszkáját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'A deszkákat pedig így csináld a hajlékhoz: húsz deszkát a déli oldalra, délfelé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'A húsz deszka alá pedig negyven ezüst talpat csinálj, két talpat egy-egy deszka alá, annak két csapjához képest; megint két talpat egy-egy deszka alá, a két csapjához képest.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'A hajlék másik oldalául is, észak felől húsz deszkát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'És azokhoz is negyven ezüst talpat; két talpat egy deszka alá, megint két talpat egy deszka alá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'A hajlék nyugoti oldalául pedig csinálj hat deszkát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'A hajlék szegleteiül is csinálj két deszkát a két oldalon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'Kettősen legyenek alólról kezdve, felül pedig együtt legyenek egy karikába foglalva; ilyen legyen mindkettő; a két szeglet számára legyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Legyen azért nyolcz deszka, és azokhoz tizenhat ezüst talp; két talp egy deszka alatt, megint két talp egy deszka alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Csinálj reteszrúdakat is sittim-fából; ötöt a hajlék egyik oldalának deszkáihoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'És öt reteszrúdat a hajlék másik oldalának deszkáihoz; és a hajlék nyugoti oldalának deszkáihoz is öt reteszrúdat hátulról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'A középső reteszrúd pedig a deszkák közepén az egyik végtől a másik végig érjen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'A deszkákat pedig borítsd meg aranynyal, és karikákat is aranyból csinálj azokhoz a reteszrúdak tartói gyanánt; a reteszrúdakat is megborítsd aranynyal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'A hajlékot pedig azon a módon állítsd fel, a mint néked a hegyen mutattatott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'És csinálj függönyt, kék, és bíborpiros, és karmazsinszínű, és sodrott lenből; Kérubokkal, mestermunkával készítsék azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'És tedd azt sittim-fából való, aranynyal borított négy oszlopra, a melyeknek horgai aranyból legyenek, négy ezüst talpon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'És tedd a függönyt a horgok alá, és vidd oda a függöny mögé a bizonyság ládáját és az a függöny válaszsza el néktek a szent helyet a szentek szentjétől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Azután tedd rá a fedelet a bizonyság ládájára a szentek szentjébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Az asztalt pedig helyezd a függönyön kívül, és a gyertyatartót az asztal ellenébe, a hajlék déli oldalába; az asztalt pedig tedd az északi oldalba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'És csinálj leplet a sátor nyilására is, kék, és bíborpiros, és karmazsinszínű, és sodrott lenből, hímzőmunkával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'A lepelhez pedig csinálj öt oszlopot sittim-fából, és borítsd meg azokat aranynyal; azoknak horgai aranyból legyenek, és önts azokhoz öt réztalpat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'És csináld az oltárt sittim-fából, öt sing a hossza, és öt sing a szélessége; négyszegű legyen az oltár, és magassága három sing.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Szarvakat is csinálj a négy szegletére, szarvai magából legyenek, és borítsd meg azt rézzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Csinálj ahhoz fazekakat is a hamujának, hozzá való lapátokat, medenczéket, villákat és serpenyőket; minden hozzá való edényt rézből csinálj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Csinálj ahhoz háló forma rostélyt is rézből, és csinálj a hálóra négy rézkarikát, a négy szegletére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'És tedd azt az oltár párkányzata alá alulról, úgy hogy a háló az oltár közepéig érjen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Csinálj az oltárhoz rúdakat is, sittim-fa rúdakat, és borítsd meg azokat rézzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'És dugják a rúdakat a karikákba, és legyenek azok a rúdak az oltár két oldalán, mikor azt hordozzák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Üresre csináld azt, deszkákból; a mint néked a hegyen mutattatott, úgy csinálják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Pitvart is csinálj a hajléknak; a déli oldalon a pitvarhoz szőnyegeket, sodrott lenből; száz sing legyen a hossza egy oldalnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'Ahhoz húsz oszlopot, húsz réz talpat, és az oszlopok horgait és átalkötőit ezüstből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Épen úgy az északi oldalon, hoszszában, száz sing hosszú szőnyeget; ahhoz húsz oszlopot, ezekhez húsz réztalpat, és az oszlopok horgait és átalkötőit ezüstből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'A pitvar szélességéhez pedig nyugot felől ötven sing szőnyeget; ahhoz tíz oszlopot és ezekhez tíz talpat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'A pitvarnak szélessége kelet felől is ötven sing.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'És tizenöt sing szőnyeg legyen egyik oldalról, ehhez három oszlop, ezekhez pedig három talp.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'A másik oldalról is tizenöt sing szőnyeg, ehhez három oszlop és ezekhez három talp.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'A pitvar kapuján pedig húsz sing lepel legyen, kék, és bíborpiros, és karmazsinszínű és sodrott lenből, himzőmunkával; ehhez négy oszlop, ezekhez pedig négy talp.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'A pitvar minden oszlopát ezüst átalkötők vegyék körűl, horgaik ezüstből, talpaik pedig rézből legyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'A pitvar hossza száz sing, és szélessége ötven-ötven, magassága pedig öt sing; leplei sodrott lenből, talpai pedig rézből legyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'A hajlék minden edénye, az ahhoz való mindennemű szolgálatban, és minden szege, és a pitvarnak is minden szege rézből legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Te pedig parancsold meg az Izráel fiainak, hogy hozzanak néked tiszta faolajat, a melyet a világításhoz sajtoltak, hogy szünet nélkül égő lámpát gyujthassanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'A gyülekezet sátorában a függönyön kivül, a mely a bizonyság előtt van, készítsék el azt Áron és az ő fiai, estvétől fogva reggelig az Úr előtt. Örök rendtartás legyen ez az ő nemzetségöknél Izráel fiai között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'Te pedig hívasd magadhoz a te atyádfiát Áront, és az ő fiait ő vele az Izráel fiai közűl, hogy papjaim legyenek: Áron, Nádáb, Abihu, Eleázár, Ithamár, Áronnak fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'És csinálj szent ruhákat Áronnak a te atyádfiának, dicsőségére és ékességére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'És szólj minden bölcs szívűeknek, a kiket betöltöttem a bölcseség lelkével, hogy csinálják meg az Áron ruháit, az ő felszentelésére, hogy papom legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Ezek pedig a ruhák, a melyeket készítsenek: hósen, efód, palást, koczkás köntös, süveg és öv. És csináljanak szent ruhákat Áronnak a te atyádfiának, és az ő fiainak, hogy papjaim legyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'Vegyék hát ők elő az aranyat, és a kék, és a bíborpiros, és a karmazsinszínű fonalat és a lenfonalat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'És csinálják az efódot aranyból, kék és bíborpiros, karmazsinszínű és sodrott lenből, mestermunkával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Két vállkötő is legyen hozzá kapcsolva a két végéhez, hogy összekapcsoltathassék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Átkötő öve pedig, a mely rajta van, ugyanolyan mívű és abból való legyen; aranyból, kék, és bíborpiros, és karmazsinszinű, és sodrott lenből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Annakutána végy két ónix-követ, és mesd fel azokra az Izráel fiainak neveit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'Hatnak nevét az egyik kőre, a másik hatnak nevét pedig a másik kőre, az ő születésök szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Kőmetsző munkával, a mint a pecsétet metszik, úgy metszesd e két követ az Izráel fiainak neveire; köröskörűl arany boglárokba csináld azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'És tedd e két követ az efód vállkötőire, az Izráel fiaira való emlékeztetés kövei gyanánt, hogy emlékeztetőül hordozza Áron azoknak neveit az ő két vállán az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Csinálj annakokáért arany boglárokat,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'És két lánczot tiszta aranyból; fonatékosan csináld azokat; sodrott mívűek legyenek, és tedd rá a sodrott lánczokat a boglárokra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Azután csináld meg az ítéletnek hósenét mestermunkával; úgy csináld mint az efódot csináltad: aranyból, kék, és bíborpiros, és karmazsinszínű, és sodrott lenből csináld azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Négyszögű legyen, kétrétű, egy arasznyi hosszú és egy arasznyi széles.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'És foglalj abba befoglalni való köveket; négy sor követ, ilyen sorban: szárdiusz, topáz és smaragd; ez az első sor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'A második sor pedig: karbunkulus, zafir és gyémánt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'A harmadik sor: jáczint, agát és amethiszt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'A negyedik sor: krizolith, ónix és jáspis; arany boglárokba legyenek foglalva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'A kövek tehát az Izráel fiainak nevei szerint legyenek, tizenkettő legyen az ő nevök szerint; mint a pecsét, úgy legyen metszve, mindenik a reá való névvel, a tizenkét nemzetség szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'A hósenre pedig csinálj fonatékos lánczokat, sodrott mívűeket, tiszta aranyból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'És csinálj a hósenre két arany karikát, és tedd a két karikát a hósen két szegletére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'És a két arany fonatékot fűzd a hósen két szegletén levő karikákba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'A két fonatéknak két végét pedig foglald a két boglárhoz, és tűzd az efódnak vállkötőihez, annak előrészére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Csinálj még két arany karikát, és tedd azokat a hósen két szegletére, azon a szélén, a mely befelé van az efód felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'És csinálj még két arany karikát, és tedd azokat az efód két vállkötőjére alól, annak előrésze felől egybefoglalásához közel, az efód öve felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'És csatolják a hósent az ő karikáinál fogva az efód karikáihoz, kék zsinórral, hogy az efód öve felett legyen, és el ne váljék a hósen az efódtól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'És viselje Áron az Izráel fiainak neveit az ítélet hósenén, az ő szíve felett, a mikor bemegy a szenthelyre, emlékeztetőűl az Úr előtt szüntelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Azután tedd az ítéletnek hósenébe az Urimot és Thummimot, hogy legyenek azok az Áron szíve felett, a mikor bemegy az Úr eleibe, és hordozza Áron az Izráel fiainak ítéletét az ő szívén az Úr színe előtt szüntelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'És csináld az efód palástját egészen kék lenből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'Közepén legyen nyílás a fejének; a nyílásnak szegése legyen köröskörűl, takácsmunka, olyan legyen mint a pánczél nyílása, hogy el ne szakadjon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'És ennek alsó peremére csinálj gránátalmákat, kék, és bíborpiros, és karmazsinszínű lenből, a peremére köröskörűl, és ezek közé arany csengettyűket is köröskörűl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'Arany csengettyű, meg gránátalma, arany csengettyű, meg gránátalma legyen a palást peremén köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'És legyen az Áronon, a mikor szolgál, hogy hallassék annak csengése, a mikor bemegy a szenthelybe az Úr eleibe, és mikor kijön, hogy meg ne haljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Csinálj egy lapot is tiszta aranyból, és mesd ki arra, mint a pecsétet metszik: Szentség az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'És kösd azt kék zsinórra, hogy legyen az a süvegen; a süvegnek előrészén legyen az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'És legyen az az Áronnak homlokán, hogy Áron viselje a szent áldozatok körűl elkövetett vétket, a melyeket az Izráel fiai mindenféle szent adományaikban szentelnek. Legyen azért szüntelen a homlokán, hogy kedvesekké tegye őket az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'A lenköntöst pedig koczkásan készítsd, és a süveget lenből csináld, az övet meg hímző munkával készítsd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Az Áron fiainak is csinálj köntösöket, és csinálj nékik öveket is, meg süvegeket is csinálj nékik, dicsőségökre és ékességökre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'És öltöztesd fel azokba Áront a te atyádfiát, és az ő fiait vele együtt, és kend fel őket, iktasd be őket tisztjökbe, és szenteld fel őket, hogy papjaimmá legyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Csinálj nékik lábravalókat is gyolcsból, hogy befödjék azoknak mezítelen testét, és az ágyéktól a tomporig érjenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'És legyenek azok Áronon és az ő fiain, a mikor bemennek a gyülekezet sátorába, vagy a mikor az oltárhoz járulnak, a szenthelyen való szolgálattételre, hogy bűnt ne vigyenek oda és meg ne haljanak. Örökkévaló rendtartás ez Áronnak és az ő magvának ő utána.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'Ez az, a mit ő velök cselekedjél, az ő felszentelésökre, hogy az én papjaim legyenek: Végy egy tulkot, fiatal marhát, és hiba nélkül való két kost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'És kovásztalan kenyeret, és olajjal elegyített kovásztalan kalácsokat, meg olajjal kent kovásztalan lepényeket is; búzalisztlángból készítsd azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'És tedd azokat egy kosárba, és vidd fel azokat a kosárban, a tulokkal és a két kossal együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Áront pedig és az ő fiait állítsd a gyülekezet sátorának ajtaja elé, és mosd meg őket vízzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'És vedd a ruhákat, és öltöztesd fel Áront a köntösbe, az efódhoz való palástba, és az efódba, meg a hósenbe és övezd fel őt az efód övével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'Tedd a süveget is fejére, és a szent koronát tedd a süvegre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'És vedd a kenetnek olaját, és töltsd az ő fejére, így kend fel őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Fiait is állítsd elő, és öltöztesd fel őket a köntösökbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'És övezd körűl őket övvel, Áront és az ő fiait, és tégy a fejökre süvegeket is, hogy övék legyen a papság örök rendelés szerint. Így iktasd be tisztökbe Áront és fiait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Azután állíttasd a tulkot a gyülekezet sátora elé, és Áron és az ő fiai tegyék kezeiket a tulok fejére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'És vágd le a tulkot az Úr előtt a gyülekezet sátorának ajtajánál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'Azután végy a tulok véréből, és hintsd azt ujjaiddal az oltár szarvaira; a többi vért pedig töltsd mind az oltár aljára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'És vedd a kövéréből mindazt, a mi a belet fedi, és a májon lévő hártyát, és a két vesét a rajtok lévő kövérrel együtt, és füstölögtesd el az oltáron.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'A tulok húsát, bőrét és ganéját pedig égesd el a táboron kívül: bűnért való áldozat az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Vedd az egyik kost is, és Áron és az ő fiai tegyék kezeiket a kos fejére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'Azután vágd le a kost, és vedd annak vérét, és hintsd azt az oltárra köröskörűl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'A kost pedig vagdald tagjaira, és mosd meg a belét és lábszárait, és tedd rá tagjaira és fejére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'Azután füstölögtesd el az egész kost az oltáron: égőáldozat az az Úrnak, kedves illatú tűzáldozat az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Vedd a másik kost is, és Áron és az ő fiai tegyék kezeiket a kos fejére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'Azután vágd le a kost, és végy annak véréből, és hintsd meg azzal Áron füle czimpáját és az ő fiai jobb fülének czimpáját, és az ő jobb kezök hüvelykét és jobb lábok hüvelykét; a többi vért pedig hintsd az oltárra köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Azután végy a vérből, mely az oltáron van, és a kenetnek olajából, és hintsd Áronra és az ő ruháira, s vele együtt az ő fiaira és az ő fiainak ruháira, hogy szent legyen ő és az ő ruhái, s vele együtt az ő fiai és az ő fiainak ruhái.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Azután vedd a kosból a kövérét, a farkát s a belet borító kövéret, meg a máj hártyáját, meg a két veséjét a rajtok levő kövérével, és a jobb lapoczkát; mert felavatási kos ez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'Meg egy kenyeret és egy olajos kalácsot és egy lepényt a kovásztalan kenyérnek kosarából, mely az Úr előtt van;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'És rakd mindezeket az Áron kezeire és az Áron fiainak kezeire, és lóbáltasd meg azokat az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Azután vedd le azokat kezükről, és füstölögtesd el az oltáron az égőáldozat felett kedves illatul az Úr előtt; az Úrnak tűzáldozata az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Vedd az Áron felavatási kosának szegyét is, és lóbbáld meg azt az Úr előtt; azután legyen az a te részed.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Így szenteld meg a meglóbbált szegyet és a felemelt lapoczkát, a melyet meglóbbáltak és a melyet felemeltek, Áronnak és az ő fiainak felavatási kosából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'És legyen ez Áronnak és az ő fiainak része örökké az Izráel fiaitól: mert felmutatott adomány ez, és felmutatott adomány legyen Izráel fiai részéről az ő hálaáldozataikból; az Úrnak felmutatott adomány.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'A szent öltözetek pedig, a melyek az Áronéi, legyenek ő utána az ő fiaié, hogy azokban kenettessenek fel, és azokban állíttassanak tisztökbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Hét napon öltözzék azokba, a ki az ő fiai közül ő utána pap lesz, a ki bemenendő lesz a gyülekezet sátorába, hogy a szent helyen szolgáljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'A felavatási kost pedig vedd, és főzd meg annak húsát szent helyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'És a kosnak húsát és a kenyeret, mely a kosárban van, a gyülekezet sátorának ajtajánál egye meg Áron és az ő fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'Ők egyék meg azokat, a mik által az engesztelés történt, hogy tisztökbe állíttassanak és felszenteltessenek. De idegen ne egyék azokból, mert szentek azok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Ha pedig valami megmarad az avatási húsból vagy a kenyérből reggelig, tűzzel égesd meg a maradékot; meg ne egyék, mert szent az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Áronnal tehát és az ő fiaival akképen cselekedjél, a mint megparancsoltam néked; hét napon át állítsd őket tisztökbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'És naponként készíts bűnáldozati tulkot engesztelésül, és tisztítsd meg az oltárt, mikor engesztelő áldozatot végzesz rajta, és kend meg azt, hogy megszenteltessék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Hét napon tégy engesztelő áldozatot az oltáron; és szenteld meg azt, hogy felette igen szentséges legyen az oltár. Valami illeti az oltárt, szent legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'Ez pedig az, a mit áldoznod kell az oltáron: Esztendős két bárányt mindennap szüntelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Az egyik bárányt reggel áldozd meg, a másik bárányt pedig áldozd meg estennen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'És az egyik bárányhoz végy egy tized lisztlángot, egy negyed hin-nyi sajtolt olajjal vegyítve; italáldozatul pedig egy negyed hin-nyi bort.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'A másik bárányt estennen áldozd meg, ugyanazzal az étel- és italáldozattal készítsd azt, mint reggel; kedves illatul, tűzáldozatul az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'Szüntelen égőáldozat legyen az a ti nemzetségeitek között a gyülekezet sátorának ajtajánál az Úr előtt, a hol megjelenek néktek, hogy veled ott szóljak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Ott jelenek meg az Izráel fiainak, és megszenteltetik az én dicsőségem által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'És megszentelem a gyülekezetnek sátorát és az oltárt; Áront és az ő fiait is megszentelem, hogy papjaim legyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'És az Izráel fiai között lakozom, és nékik Istenök lészek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'És megtudják, hogy én, az Úr vagyok az ő Istenök, a ki kihoztam őket Égyiptom földéről, hogy közöttök lakozhassam, én, az Úr az ő Istenök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Csinálj oltárt a füstölő szerek füstölgésére is, sittim-fából csináld azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'Egy sing hosszú, egy sing széles, négyszögű és két sing magas legyen, ugyanabból legyenek szarvai is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'És borítsd meg azt tiszta aranynyal, a tetejét és oldalait köröskörül, és szarvait is; arany pártázatot is csinálj hozzá köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Csinálj hozzá két arany karikát is, pártázata alá a két oldalán, mindkét oldalára csináld, hogy legyenek rúdtartókul, hogy azokon hordozzák azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'És a rúdakat csináld sittim-fából, és borítsd meg azokat aranynyal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'És tedd azt a függöny elé, a mely a bizonyság ládája mellett, a bizonyság fedele előtt van, a hol megjelenek néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Áron pedig füstölögtessen rajta minden reggel jó illatú füstölő szert; mikor a mécseket rendbe szedi, akkor füstölögtesse azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'És a mikor Áron estennen felrakja a mécseket, füstölögtesse azt. Szüntelen való illattétel legyen ez az Úr előtt nemzetségről nemzetségre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Ne áldozzatok azon idegen füstölőszerekkel, se égőáldozattal, se ételáldozattal; italáldozatot se öntsetek reá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'És egyszer egy esztendőben engesztelést végezzen Áron annak szarvainál az engesztelő napi áldozat véréből; egy esztendőben egyszer végezzen engesztelést azon, nemzetségről nemzetségre. Szentségek szentsége ez az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Azután szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'Mikor Izráel fiait fejenként számba veszed, adja meg kiki életének váltságát az Úrnak az ő megszámláltatásakor, hogy csapás ne legyen rajtok az ő megszámláltatásuk miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Ezt adja mindaz, a ki átesik a számláláson: fél siklust a szent siklus szerint (egy siklus húsz gera); a siklusnak fele áldozat az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Mindaz, a ki átesik a számláláson, húsz esztendőstől fogva felfelé, adja meg az áldozatot az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'A gazdag ne adjon többet, és a szegény ne adjon kevesebbet fél siklusnál, a mikor megadják az áldozatot az Úrnak engesztelésül a ti lelketekért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'És szedd be az engesztelési pénzt az Izráel fiaitól, és add azt a gyülekezet sátorának szolgálatjára, hogy az Izráel fiainak emlékezetéül legyen az az Úr előtt, engesztelésül a ti lelketekért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Azután szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'És csinálj rézmedenczét, lábát is rézből, mosakodásra; és tedd azt a gyülekezet sátora közé és az oltár közé, és tölts bele vizet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'Hogy Áron és az ő fiai abból mossák meg kezeiket és lábaikat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'A mikor a gyülekezet sátorába mennek, mosakodjanak meg vízben, hogy meg ne haljanak; vagy mikor az oltárhoz járulnak, hogy szolgáljanak és tűzáldozatot füstölögtessenek az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'Kezeiket is, lábaikat is mossák meg, hogy meg ne haljanak. És örökkévaló rendtartásuk lesz ez nékik, néki és az ő magvának nemzetségről nemzetségre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Ismét szóla az Úr Mózesnek mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'Te pedig végy drága fűszereket, híg mirhát ötszáz siklusért, jóillatú fahéjat fél ennyit, kétszáz ötvenért, és illatos kalmust is kétszáz ötvenért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'Kásiát pedig ötszázért, a szent siklus szerint, és egy hin faolajt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'És csinálj abból szent kenetnek olaját, elegyített kenetet, a kenetkészítők mestersége szerint. Legyen az szent kenő olaj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'És kend meg azzal a gyülekezet sátorát és a bizonyság ládáját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'Az asztalt is és annak minden edényét, a gyertyatartót és annak edényeit, és a füstölő oltárt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'Az egészen égőáldozatnak oltárát is, és annak minden edényit, a mosdómedenczét és annak lábát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Így szenteld meg azokat, hogy szentségek szentségévé legyenek: Valami illeti azokat, szent legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Kend fel Áront is és az ő fiait is; így szenteld fel őket papjaimmá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Az Izráel fiainak pedig így szólj: Szent kenetnek olaja legyen ez nékem, a ti nemzetségeiteknél is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Ember testét azzal meg ne kenjék, se ahhoz hasonlót, annak mértékei szerint ne csináljatok: szent az; szent legyen előttetek is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Valaki ahhoz hasonló kenetet csinál, vagy azzal idegent ken meg, kitöröltessék az ő népe közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Monda ismét az Úr Mózesnek: Végy fűszereket, csepegő gyantát, onyxot, galbánt, e fűszereket és tiszta temjént, egyenlő mértékkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'És csinálj belőlök füstölő szert, a fűszercsináló elegyítése szerint; tiszta és szent legyen az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'És abból törj apróra, és tégy belőle a bizonyság ládája elé a gyülekezet sátorában, a hol megjelenek néked. Szentségek szentsége legyen ez előttetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'És a füstölő szer, a melyet készítesz, az Úrnak szentelt legyen előtted; annak mértéke szerint magatoknak ne csináljatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Mindaz, a ki hasonló füstölőt csinál ehhez, hogy azt illatoztassa, irtassék ki az ő népe közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'És szóla az Úr Mózesnek mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'Ímé, név szerint meghívtam Bésaléelt, a Húr fiának Urinak fiát a Júda nemzetségéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'És betöltöttem őt Istennek lelkével, bölcsességgel, értelemmel és tudománynyal minden mesterséghez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'Hogy tudjon kigondolni mindent, a mit aranyból, ezüstből, rézből kell csinálni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'És foglaló köveket metszeni, fát faragni, és mindenféle munkákat végezni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'És ímé Aholiábot is, Akhiszamáknak fiát a Dán nemzetségéből, mellé adtam; és adtam minden értelmesnek szivébe bölcseséget, hogy elkészítsék mind azt, a mit néked megparancsoltam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'A gyülekezet sátorát, a bizonyság ládáját, a fölibe való fedelet, és a sátornak minden edényét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'Az asztalt és annak edényit, a tiszta gyertyatartót, és minden hozzávalót, és a füstölő oltárt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'Az egészen égőáldozat oltárát és annak minden edényit, a mosdómedenczét és annak lábát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'A szolgálathoz való ruhákat, Áron papnak szent öltözetit, és az ő fiainak öltözetit, a papi szolgálatra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'A kenetnek olaját, és a jó illatú füstölő szert a szentséghez. Mindent úgy csináljanak, a mint néked parancsoltam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Azután szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'Te szólj az Izráel fiainak, mondván: Az én szombatimat bizony megtartsátok; mert jel az én közöttem és ti köztetek nemzetségről nemzetségre, hogy megtudjátok, hogy én vagyok az Úr, a ki titeket megszentellek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Megtartsátok azért a szombatot; mert szent az ti néktek. A ki azt megrontja, halállal lakoljon. Mert valaki munkát végez azon, annak lelke írtassék ki az ő népe közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Hat napon munkálkodjanak, a hetedik nap pedig a nyugodalomnak szombatja az Úrnak szentelt nap: valaki szombatnapon munkálkodik, megölettessék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Megtartsák azért az Izráel fiai a szombatot, megszentelvén a szombatot nemzetségről nemzetségre, örök szövetségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Legyen közöttem és az Izráel fiai között örök jel ez; mert hat napon teremtette az Úr a mennyet és a földet, hetednapon pedig megszünt és megnyugodott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Mikor pedig elvégezte vele való beszédét a Sinai hegyen, által adá Mózesnek a bizonyság két tábláját, az Isten ujjával írt kőtáblákat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Mikor látá a nép, hogy Mózes késik a hegyről leszállani, egybegyűle a nép Áron ellen és mondá néki: Kelj fel, csinálj nékünk isteneket, kik előttünk járjanak; mert nem tudjuk mint lőn dolga ama férfiúnak Mózesnek, a ki minket Égyiptom földéből kihozott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'És monda nékik Áron: Szedjétek le az aranyfüggőket, a melyek feleségeitek, fiaitok és leányaitok fülein vannak, és hozzátok én hozzám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Leszedé azért mind az egész nép az aranyfüggőket füleiről, és elvivék Áronhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'És elvevé kezökből, és alakítá azt vésővel; így csinála abból öntött borjút. És szóltak: Ezek a te isteneid Izráel, a kik kihoztak téged Égyiptom földéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Mikor látta ezt Áron, oltárt építe az előtt, és kiálta Áron, mondván: Holnap az Úrnak innepe lesz!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Felkelvén azért másnapon jó reggel, áldozának égőáldozattal és hálaáldozattal is; azután leüle a nép enni és inni; azután felkelének játszani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Szóla pedig az Úr Mózesnek: Eredj menj alá; mert megromlott a te néped, a melyet kihoztál Égyiptom földéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Hamar letértek az útról, a melyet parancsoltam nékik, borjúképet öntöttek magoknak, azt tisztelik és annak áldoznak, és azt mondják: Ezek a te isteneid Izráel, a kik téged kihoztak Égyiptom földéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Monda ismét az Úr Mózesnek: Látom ezt a népet, bizony keménynyakú nép.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Azért hagyj békét nékem, hadd gerjedjen fel haragom ellenök, és törűljem el őket: Téged azonban nagy néppé teszlek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'De Mózes esedezék az Úrnak, az ő Istenének színe előtt, mondván: Miért gerjedne Uram a te haragod néped ellen, a melyet nagy erővel és hatalmas kézzel hoztál vala ki Égyiptomnak földéről?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Miért mondanák az égyiptomiak, mondván: Vesztökre vivé ki őket, hogy elveszítse a hegyek között, és eltörülje őket a föld színéről? Múljék el a te haragod tüze, és hagyd abba azt a néped ellen való veszedelmet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Emlékezzél meg Ábrahámról, Izsákról és Izráelről a te szolgáidról, kiknek megesküdtél te magadra, mondván nékik: Megsokasítom a ti magotokat mint az égnek csillagait; és azt az egész földet, melyről szóltam, a ti magotoknak adom, és örökségül bírják azt örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'És abba hagyá az Úr azt a veszedelmet, melyet akart vala bocsátani az ő népére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Megfordula azért és megindula Mózes a hegyről, kezében a bizonyság két táblája; mindkét oldalukon beírt táblák, mind egy felől, mind más felől beírva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'A táblák pedig Isten kezének csinálmányai valának, az írás is Isten írása vala, kimetszve a táblákra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Józsué pedig hallván a nép rivalgását, monda Mózesnek: Harczkiáltás van a táborban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Az pedig felele: Nem diadalmasoknak, sem meggyőzetteknek kiáltása ez, éneklés hangját hallom én.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'És mikor közeledett volna a táborhoz, látá a borjút és a tánczolást, és felgerjede Mózesnek haragja, és elveté kezéből a táblákat, és összetöré azokat a hegy alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Azután fogá a borjút, a melyet csináltak vala, tűzben megégeté, és apróra töré mígnem porrá lett, és a vízbe hintvén, itatá azt az Izráel fiaival.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'És monda Mózes Áronnak: Mit tett néked e nép, hogy ilyen nagy bűnbe keverted?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Felele Áron: Ne gerjedjen fel uram haragja: ismered e népet, hogy gonosz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Mert azt mondák nékem: Csinálj nékünk isteneket, a kik előttünk járjanak; mert ama férfiúnak Mózesnek, ki minket Égyiptom földéről kihozott, nem tudjuk mint lőn dolga.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Én pedig felelék: Kinek van aranya? Szedjétek le; és nékem ide adák, én pedig a tűzbe vetettem, és e borjú formáltaték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'És látván Mózes, hogy a nép megvadula, mert Áron megvadítá vala őket, ellenségeik csúfjára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'Megálla Mózes a tábor kapujában, és monda: A ki az Úré, ide hozzám! és gyűlének ő hozzá mind a Lévi fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'És szóla nékik: Ezt mondja az Úr, Izráel Istene: Kössön mindenitek kardot az oldalára, menjetek által és vissza a táboron, egyik kaputól a másik kapuig, és kiki ölje meg az ő attyafiát, barátját és rokonságát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'A Lévi fiai pedig a Mózes beszéde szerint cselekedének, és elhulla azon a napon a népből úgymint háromezer férfiú.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'És mondá Mózes: Ma szenteljétek kezeiteket az Úrnak, kiki az ő fia és attyafia ellen, hogy áldása szálljon ma reátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'És másnap monda Mózes a népnek: Nagy bűnt követtetek el, most azért felmegyek az Úrhoz, talán kegyelmet nyerhetek a ti bűneiteknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Megtére azért Mózes az Úrhoz, és monda: Kérlek! Ez a nép nagy bűnt követett el: mert aranyból csinált magának isteneket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'De most bocsásd meg bűnöket; ha pedig nem: törölj ki engem a te könyvedből, a melyet írtál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'És monda az Úr Mózesnek: A ki vétkezett ellenem, azt törlöm ki az én könyvemből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Most azért eredj: vezesd a népet a hová mondottam néked: Ímé, Angyalom megy előtted; és az én látogatásom napján ezt az ő bűnöket is meglátogatom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'És megverte az Úr a népet ezért is, a mit cselekedtek a borjúval, melyet Áron készített vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Szóla azután az Úr Mózesnek: Eredj, menj fel innen, te és a nép, a melyet kihoztál Égyiptom földéről, a földre, a melyről megesküdtem Ábrahámnak, Izsáknak és Jákóbnak mondván: A te magodnak adom azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'És bocsátok előtted Angyalt, és kiűzöm a Kananeusokat, Emoreusokat, Khittheusokat, Perizeusokat, Khivveusokat és Jebuzeusokat:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'A tejjel és mézzel folyó földre; de én nem megyek fel köztetek, mert te keménynyakú nép vagy, hogy meg ne emészszelek az úton.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Mikor meghallá a nép ezt a kemény beszédet, gyászba borula, és senki nem tevé fel az ékszereit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Megmondotta vala az Úr Mózesnek: Mondd meg az Izráel fiainak: Keménynyakú nép vagy te, egy szempillantásban, ha közéd mennék, megemésztenélek. Azért most vesd le a te ékességeidet magadról, azután meglátom mit cselekedjem veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'És lerakták magokról az Izráel fiai az ő ékességeket, a Hóreb hegyétől fogva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Mózes pedig vevé a sátort, és felvoná azt a táboron kívül, messze a tábortól, és nevezé azt gyülekezet sátorának, és lőn, hogy mind a ki az Urat keresi, ki kelle mennie a gyülekezet sátorához, a táboron kívül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'És lőn, hogy mikor Mózes kiméne a sátorhoz, az egész nép felkele, és kiki mind az ő sátorának ajtajában álla; nézvén Mózes után míg a sátorba beméne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'És lőn, mikor Mózes beméne a sátorba, hogy felhő-oszlop szálla alá, és megálla a sátor ajtajában, és beszéle Mózessel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'És látá az egész nép, hogy a felhő-oszlop a sátornak ajtaján áll, és felkele az egész nép, és kiki meghajlék az ő sátorának ajtajában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Az Úr pedig beszéle Mózessel színről színre, a mint szokott ember szólani barátjával; és mikor Mózes a táborba visszatére, az ő szolgája az ifjú Józsué, Núnnak fia, nem távozék el a sátorból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'És monda Mózes az Úrnak: Lásd, te azt mondod nékem, vidd el ezt a népet, de nem mutattad meg nékem kit küldesz velem; pedig azt mondtad nékem: név szerint ismerlek téged, és kedvet találtál szemeim előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Most azért ha kedvet találtam szemeid előtt, mutasd meg nékem a te útadat, hogy ismerjelek meg téged, hogy kedvet találhassak előtted. És gondold meg, hogy e nép a te néped.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'És monda: Az én orczám menjen-é veletek, hogy megnyugtassalak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Monda néki Mózes: Ha a te orczád nem jár velünk, ne vígy ki minket innen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Mert miről ismerhetjük meg, hogy én és a te néped kedvet találtunk előtted? Nem arról-é, ha velünk jársz? Így vagyunk megkülönböztetve, én és a te néped minden néptől, a mely e földnek színén van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Monda azért az Úr Mózesnek: Megteszem ezt is a mit kívántál; mert kedvet találtál szemeim előtt, és név szerint ismerlek téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'És mondá Mózes: Kérlek, mutasd meg nékem a te dicsőségedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'És monda az Úr: Megteszem, hogy az én dicsőségem a te orczád előtt menjen el, és kiáltom előtted az Úr nevét: És könyörülök, a kin könyörülök, kegyelmezek, a kinek kegyelmezek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Orczámat azonban, mondá, nem láthatod; mert nem láthat engem ember, élvén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'És monda az Úr: Ímé van hely én nálam; állj a kősziklára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'És mikor átmegy előtted az én dicsőségem, a kőszikla hasadékába állatlak téged, és kezemmel betakarlak téged, míg átvonulok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Azután kezemet elveszem rólad, és hátulról meglátsz engemet, de orczámat nem láthatod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'És monda az Úr Mózesnek: Vágj két kőtáblát, hasonlókat az előbbiekhez, hogy írjam fel azokra azokat a szavakat, a melyek az előbbi táblákon voltak, a melyeket széttörtél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'És légy készen reggelre, és jöjj fel reggel a Sinai hegyre, és állj ott előmbe a hegy tetején.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'De senki veled fel ne jöjjön, és senki ne mutatkozzék az egész hegyen; juhok és barmok se legeljenek a hegy környékén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Vágott azért két kőtáblát, az előbbiekhez hasonlókat, és felkelvén reggel, felméne Mózes a Sinai hegyre, a mint az Úr parancsolta néki, és kezébe vevé a két kőtáblát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Az Úr pedig leszálla felhőben, és ott álla ő vele, és nevén kiáltá az Urat:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'És az Úr elvonula ő előtte és kiálta: Az Úr, az Úr, irgalmas és kegyelmes Isten, késedelmes a haragra, nagy irgalmasságú és igazságú.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'A ki irgalmas marad ezeríziglen; megbocsát hamisságot, vétket és bűnt: de nem hagyja a bűnöst büntetlenül, megbünteti az atyák álnokságát a fiakban, és a fiak fiaiban harmad és negyedíziglen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'És Mózes nagy sietséggel földre borula, és lehajtá fejét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'És monda: Uram, ha előtted kedvet találtam, kérlek járjon az Úr velünk; mert keménynyakú nép ez! Kegyelmezz a mi vétkeinknek és gonoszságunknak, és fogadj minket örökségeddé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Ő pedig monda: Ímé szövetséget kötök; a te egész néped előtt csudákat teszek, a milyenek nem voltak az egész földön, sem a népek között, és meglátja az egész nép, a mely között te vagy, az Úrnak cselekedeteit; mert csudálatos az, a mit én cselekszem veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Jegyezd meg magadnak a mit ma parancsolok néked. Ímé kiűzöm előled az Emoreust, Kananeust, Khittheust, Perizeust, Khivveust, Jebuzeust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Vigyázz magadra, nehogy szövetséget köss annak a földnek lakosaival, a melybe bemégy, hogy botránkozásra ne legyen közötted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'Hanem oltáraikat rontsátok el, törjétek össze bálványaikat, és vágjátok ki berkeiket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Mert nem szabad imádnod más istent; mert az Úr, a kinek neve féltőn szerető, féltőn szerető Isten ő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Hogy valamiképen szövetséget ne köss annak a földnek lakosaival, hogy a mikor isteneiket követvén paráználkodnak, és áldoznak az ő isteneiknek, és meghívnak téged, egyél az ő áldozatukból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'És feleséget ne végy az ő leányaik közül a te fiaidnak, hogy mikor paráználkodnak az ő leányaik isteneiket követvén, a te fiaidat is paráználkodásra vigyék, az ő isteneiket követvén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Ne csinálj magadnak öntött isteneket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'A kovásztalan kenyér innepét megtartsad: hét nap egyél kovásztalan kenyeret, a mint megparancsoltam néked, az Abib hónap ideje alatt; mert Abib hónapban jöttél ki Égyiptomból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Mindaz a mi az anyja méhét megnyitja, enyém legyen, és minden hímbarmod is, a mely a te tehenednek vagy juhodnak első fajzása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'De a szamárnak első vemhét juhon váltsd meg; ha pedig nem váltod, szegd nyakát. Fiaid közül minden elsőszülöttet megválts, és ne jöjjön üresen előmbe senki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Hat napon munkálkodjál, a hetedik napon pedig pihenj; szántás és aratás idején is pihenj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'A hetek innepét is megtartsd a búza zsengének aratásakor; meg a betakarás innepét is az esztendő végén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Háromszor esztendőnként minden férfiú jelenjen meg az Úrnak, Izráel Ura Istenének színe előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Mert kiűzöm a népeket előled, és kiszélesítem határodat, és senki nem kívánja meg a te földedet, mikor felmégy, hogy a te Urad Istened előtt megjelenjél, esztendőnként háromszor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Áldozatom vérét ne ontsd ki kovász mellett, és a husvét innepének áldozatja ne maradjon meg reggelig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Földed zsengéiből az elsőt vidd fel az Úrnak a te Istenednek házába. Ne főzz gödölyét az anyja tejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'És monda az Úr Mózesnek: Írd fel ezeket a szavakat; mert ezeknek a szavaknak értelme szerint kötöttem szövetséget veled és Izráellel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'És ott vala az Úrral negyven nap és negyven éjjel: kenyeret nem evett, vizet sem ivott. És felírá a táblákra a szövetség szavait, a tíz parancsolatot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'És lőn, a mikor Mózes a Sinai hegyről leszálla, (a Mózes kezében vala a bizonyság két táblája, mikor a hegyről leszálla) Mózes nem tudta, hogy az ő orczájának bőre sugárzik, mivelhogy Ővele szólott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'És a mint Áron és az Izráel minden fiai meglátták Mózest, hogy az ő orczájának bőre sugárzik: féltek közelíteni hozzá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Mózes pedig megszólítá őket, és Áron és a gyülekezetnek fejei mind hozzá menének, és szóla velök Mózes.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Azután az Izráel fiai is mind hozzá járulának, és megparancsolá nékik mind azt, a mit az Úr mondott néki a Sinai hegyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Mikor pedig elvégezte Mózes velök a beszédet, leplet tőn orczájára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'És mikor Mózes az Úr elébe méne, hogy vele szóljon, levevé a leplet, míg kijőne. Kijövén pedig, elmondá az Izráel fiainak, a mi parancsot kapott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'És az Izráel fiai láták a Mózes orczáját, hogy sugárzik a Mózes orczájának bőre; és Mózes a leplet ismét orczájára borítá, mígnem beméne, hogy Ővele szóljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'És egybegyűjté Mózes az Izráel fiainak egész gyülekezetét, és monda nékik: Ezek azok a dolgok, a melyeket parancsolt az Úr, hogy cselekedjétek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Hat napon át munkálkodjatok; a hetedik nap pedig szent legyen előttetek, az Úr nyugodalmának szombatja. Valaki azon munkálkodik, megölettessék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Ne gerjeszszetek tüzet a ti házaitokban szombatnapon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'És szóla Mózes az Izráel fiai egész gyülekezetének, mondván: Ez az, a mit az Úr parancsolt, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Szedjetek magatok közt ajándékot az Úrnak, mind, a kinek szíve önként hajlandó arra, hozzon ajándékot az Úrnak, aranyat, és ezüstöt, és rezet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'És kék, és bíborpiros, és karmazsinszínű, és lenfonalat, és kecskeszőrt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'Veresre festett kosbőröket, és borzbőröket és sittim-fát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'Világító olajat, arómákat a kenet olajához, és fűszereket a füstöléshez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'Ónix köveket és foglalni való köveket az efódhoz és a hósenhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'És a kik ti köztetek ahhoz értők, jőjjenek elő, hogy csinálják meg mindazt, a mit az Úr parancsolt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'A hajlékot, annak sátorát és takaróját, horgait, deszkáit, reteszrúdjait, oszlopait és talpait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'A ládát és annak rúdjait, a fedéllel egybe, és a takaró függönyt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'Az asztalt és annak rúdjait, és minden edényét, és a szent kenyerekhez valókat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'A világító gyertyatartót és a hozzá való eszközöket, mécseit, és világító olajt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'A füstölő oltárt és rúdjait, a kenetnek olaját, és a jó illatú füstölőt, a hajlék ajtajára ajtótakarót.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'Az egészen égőáldozat oltárát, annak réz rostélyát, rúdjait és minden eszközeit, a mosdómedenczét és annak lábát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'A pitvar szőnyegeit, oszlopait, talpait, és a pitvar kapujának leplét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'A hajlék szegeit, a pitvar szegeit, és azoknak köteleit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'A szolgálati ruhákat, a szent hajlékban való szolgálathoz, a szent ruhákat Áron papnak, és az ő fiainak ruháit, a papi szolgálatra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Azután kiméne az Izráel fiainak egész gyülekezete Mózes elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'És eljöve mindenki, a kit a szíve indíta, és a kit lelke hajt vala, és hozának áldozatot az Úrnak, a gyülekezet hajlékának készítéséhez, és annak minden szolgálatához, és a szent ruhákhoz valókat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'És jövének férfiak és asszonyok együtt, mind, a kit szíve indított, hozának kapcsokat, függőket, gyűrűket, karpereczet, mindenféle arany eszközöket; a férfiak is, mind a kik aranyból hoztak áldozatot az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'És minden ember, kinek a mije vala, hozott kék, bíborpiros, és karmazsinszínű, és lenfonalat, kecskeszőrt, veresre festett kosbőröket és borzbőröket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Minden, a ki ezüstöt vagy rezet vihetett, felhozá azt áldozatul az Úrnak, és a kiknél sittim-fa találtaték a szolgálat különböző szükségeire, felhozák azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Az asszonyok közűl pedig mind, a kik ahhoz értettek, saját kezeikkel fonának, és felvivék azt a mit fontak, a kék, és a bíborpiros, és a karmazsinszínű, és a lenfonalat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Azok az asszonyok pedig, a kik ahhoz értettek, fonának kecskeszőrt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'A főemberek pedig hozának ónix köveket, foglalni való köveket az efódhoz és a hósenhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'Illatozó szert is és olajat, a mécsbe és a kenethez, és fűszereket a füstöléshez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Minden férfi és asszony, a kit szíve önként indíta, hogy áldozzon az egész munkára, melyet az Úr parancsolt Mózes által, hogy véghez vigyenek: mind önként hoztak ajándékot az Úrnak az Izráel fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'És monda Mózes az Izráel fiainak: Ímé az Úr név szerint hívta el Bésaléelt, a Húr fiának Urinak fiát, a Júda nemzetségéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'És betöltötte őt Istennek lelkével, bölcseséggel, értelemmel és tudománynyal minden mesterségben:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'Hogy tudjon kigondolni mindent a mit aranyból, ezüstből és rézből kell csinálni;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'És foglalásra való köveket metszeni, és fát faragni; és minden mesterséges munkát végezni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Azontúl alkalmatossá tette arra is, hogy tanítson, mind ő, mind Aholiáb az Akhiszamák fia, a Dán nemzetségéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Betöltötte őket bölcseség lelkével, hogy tudjanak mindenféle faragó, és kötő, és hímző munkát készíteni, kék és bíborpiros, karmazsinszínű és lenfonálból, és takácsmunkát, a kik készítenek ilyenféle munkát és kigondolnak mesterműveket. Azért Bésaléel és Aholiáb, és mindazok a bölcs férfiak, kiknek az Úr bölcseséget és értelmet adott, hogy meg tudják csinálni a szent hajlék szolgálatához való minden eszközöket: csinálják meg egészen úgy, a mint az Úr parancsolta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'Elhívá azért Mózes Bésaléelt, és Aholiábot, és mindazokat a bölcs férfiakat, a kiknek elméjébe tudományt adott vala az Úr, és mind a kit szíve arra indíta, hogy járuljon annak a munkának végrehajtásához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'És átvevék Mózestől mind azt az ajándékot, a mit az Izráel fiai hoztak vala, a szent hajlék felépítésének szolgálatára. Azontúl is minden reggel önkéntes ajándékot is hoztak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Eljövének azért mind azok a bölcsek, kik a szent hajlék minden munkáján dolgoztak, kiki a maga munkájától, a melyen dolgozott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'És ezt mondák Mózesnek: Többet hord a nép ajándékba, mint a mennyi kell a munka elkészítésére, a melyet parancsolt az Úr, hogy csináljunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'Parancsola azért Mózes, és hírré tevék a táborban: Se férfi, se asszony ezután ne készítsen ajándékot a szent munkára. És megszünék a nép hordani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'És az egész munka elvégzésére elég volt az adomány, még felesleges is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'És mind a bölcs szívű férfiak, kik munkálkodának, készíték a hajlékot, tíz kárpittal: sodrott lenből és kék, és bíborpiros és karmazsinszinűből, Kérubokkal, mestermunkával készíték azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'Egy-egy kárpit hossza huszonnyolcz sing, szélessége egy-egy kárpitnak négy sing vala; egy mértéke vala minden kárpitnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'És öt kárpitot foglalának egybe, és ismét a más öt kárpitot is egybefoglalák, egyiket a másikkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'És csinálának kék hurkokat az első kárpitnak szélére, a mely szélről vala az egybefoglalásban; hasonlót csinálának a külső kárpit szélére, a másik egybefoglalásban is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'Az egyik kárpiton ötven hurkot csinálának, és ötven hurkot csinálának a másik kárpit szélén is, a mely a második egybefoglalásban vala; a hurkokat egymás ellenébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Csinálának ötven arany horgocskát is, és összefoglalák a kárpitokat a horgocskákkal, egyiket a másikkal, és egygyé lőn a hajlék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Csinálának kárpitokat kecskeszőrből is, sátornak a hajlékra; tizenegy kárpitot csinálának ilyent.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Egy kárpit hossza harmincz sing, és egy kárpit szélessége négy sing; egy mértéke vala a tizenegy kárpitnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'És egybefoglalák az öt kárpitot külön, és a hat kárpitot külön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Csinálának ötven hurkot is a kárpit szélére, a mely szélről vala az egybefoglalásban; ötven hurkot csinálának a kárpit szélére a másik egybefoglalásban is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Csinálának ötven rézhorgocskát is a sátor egybefoglalására, hogy egygyé legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Csinálának takarót is a sátorra, veresre festett kosbőrökből, és azon felül egy takarót borzbőrökből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'És megcsinálák a deszkákat is a hajlékhoz sittim-fából, felállogatva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Tíz sing a deszkának hossza, másfél sing pedig egy deszkának szélessége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'Egy deszkának két csapja vala, egyik a másiknak megfelelő; így csinálták a hajlék összes deszkáit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'A deszkákat pedig így rendezék a hajlékhoz: húsz deszkát déli oldalon, délfelé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'És a húsz deszka alá negyven ezüsttalpat készítének; az egyik deszka alá két talpat, az ő két csapja szerint, a másik deszka alá is két talpat, az ő két csapja szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'A hajlék másik oldalául, az északi oldalon, szintén húsz deszkát csinálának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'És negyven ezüsttalpat azok alá, két talpat az egyik deszka alá, a másik deszka alá is két talpat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'A hajlék napnyugoti oldalául hat deszkát csinálának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'A hajlék szegleteiül pedig a két oldalra, két deszkát csinálának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'És alólról kezdve kettősök valának, felűl pedig egybe valának foglalva egy karikával; így cselekedének mind a kettővel, a két szegleten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'Nyolcz deszka vala tehát, és azoknak tizenhat ezüsttalpa, két-két talp egy-egy deszka alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Csinálának reteszrúdakat is sittim-fából, ötöt a hajlék egyik oldalának deszkáihoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'És öt reteszrúdat a hajlék másik oldalának deszkáihoz, és öt reteszrúdat a hajlék nyugoti oldalának deszkáihoz hátulról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'És megcsinálák a középső reteszrúdat is, hogy fusson a deszkák közepén, végtől-végig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'A deszkákat pedig aranynyal boríták be; a karikáikat aranyból csinálák, gyűrűk gyanánt a reteszrúdakhoz, és a reteszrúdakat is beboríták aranynyal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Megcsinálák a függönyt is, kék, és bíborpiros, és karmazsinszínű, és sodrott lenből, mestermunkával csinálák azt, Kérubokkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'És csinálának ahhoz négy oszlopot sittim-fából, és beboríták azokat aranynyal, horgaik aranyból; és öntének azokhoz négy ezüsttalpat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'És csinálának a sátor nyílására leplet kék, és bíborpiros, és karmazsinszínű, és sodrott lenből, hímzőmunkával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'És ahhoz öt oszlopot, horgaikkal együtt; és beboríták azoknak fejeit és átalkötőit aranynyal; öt talpuk pedig rézből vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'És megcsinálá Bésaléel a ládát sittim-fából; harmadfél sing a hossza, szélessége másfél sing, magassága is másfél sing.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'És beborítá azt tiszta aranynyal, mind belől, mind kivül, és csinála reá arany pártázatot köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'És önte annak négy arany karikát a négy szegletére; egyik oldalára is kettőt, másikra is kettőt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Csinála rúdakat is sittim-fából, és beborítá azokat aranynyal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'És betolá a rúdakat a láda oldalán levő karikákba, hogy a láda hordozható legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Csinála fedelet is tiszta aranyból; harmadfél sing a hossza, másfél sing a szélessége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Csinála két Kérubot is aranyból, vert aranyból csinálá azokat, a fedél két végére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'Az egyik Kérubot az egyik végére innen, a másik Kérubot a másik végére onnan; a fedélből veré ki a Kérubokat, a két végére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'A Kérubok pedig kiterjeszték szárnyaikat felfelé, betakarva szárnyaikkal a fedelet, és arczaik egymással szembe valának; a fedél felé valának a Kérubok arczai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Megcsinálá az asztalt is sittim-fából: két sing a hossza, a szélessége egy sing, magassága másfél sing.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'És beborítá azt tiszta arannyal, és csinála reá köröskörül arany pártázatot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Csinála egy tenyérnyi széles karájt is köröskörül; és a karájhoz csinála arany pártázatot köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Azután önte hozzá négy arany karikát, és a karikákat ráilleszté a négy láb négy szegletére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'A karikák a karáj mellett valának rúdtartókul, hogy az asztalt hordozhassák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Megcsinálá a rúdakat is sittim-fából, és azokat beborítá aranynyal, hogy hordozhassák az asztalt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Megcsinálá az asztalra való edényeket is: tálait, csészéit, kelyheit és kancsóit, a melyekkel italáldozatot áldoznak, tiszta aranyból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Megcsinálá a gyertyatartót is tiszta aranyból, vert aranyból csinálá a gyertyatartót; szára, ága, csészéi, gombjai és virágai ő magából valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'És hat ág jöve ki oldalaiból; egyik oldalról is három gyertyatartó-ág, másik oldalról is három gyertyatartó-ág.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'Három mandolavirágformájú csésze vala az egyik ágon, gombbal és virággal; így a másik ágon is három mandolavirágformájú csésze vala gombbal és virággal; így vala mind a hat ágon, a melyek kijövének a gyertyatartóból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'A gyertyatartón pedig négy mandolavirágformájú csésze vala, gombjaikkal és virágaikkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'És gomb vala a két ág alatt ő magából, és gomb vala a két ág alatt ő magából, és gomb vala a két ág alatt ő magából, a hat ág szerint, a mely belőle jöve ki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Gombjaik és ágaik belőle valának; az egész egy vert munka vala, tiszta aranyból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'És megcsinálá hét mécsét is, és azoknak hamvvevőit és hamutartóit, tiszta aranyból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Egy talentom tiszta aranyból csinálá azt meg hozzá tartozó eszközeit is mind.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Megcsinálá a füstölő oltárt is sittim-fából; hossza egy sing, szélessége is egy sing, négyszögű; magassága pedig két sing; ő magából valának szarvai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'És beborítá azt tiszta aranynyal, tetejét és oldalait köröskörül, és a szarvait is; és csinála hozzá arany pártázatot köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'És két arany karikát csinála hozzá, a pártázata alá, a két oldalán, mindkét oldalára, hogy legyenek rúdtartókul, hogy azokon hordozhassák azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'A rúdakat is sittim-fából csinálá meg, és azokat is beborítá aranynyal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'A szent kenetnek olaját is megcsinálá, és a tiszta fűszerekből való füstölőt a kenetkészítő mestersége szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'És megcsinálá azután az egészen égőáldozat oltárát sittim-fából; öt sing a hossza, öt sing a szélessége; négyszögű és három sing magas.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'És csinála hozzá szarvakat is, a négy szegletére; ő magából voltak a szarvai, és beborítá azt rézzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Azután minden edényét is megcsinálá: a fazekakat, a lapátokat, a medenczéket, a villákat és a szenes serpenyőket; minden edényeit rézből csinálá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Csinála az oltárhoz hálóforma rostélyt is rézből, annak párkányzata alá, alulról a közepéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'Önte négy karikát is rézrostélynak négy szegletére, rúdtartókul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'A rúdakat sittim-fából csinálá meg, és rézzel borítá be.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'És a rúdakat betolá az oltár oldalain levő karikákba, hogy azokon hordozhassák azt; deszkákból, üresre csinálá azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Megcsinálá a mosdómedenczét is rézből, és annak lábát is rézből, a szolgálattevő asszonyok tükreiből, a kik a gyülekezet sátorának nyílása előtt szolgáltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'A pitvart is megcsinálá dél felől; a déli oldalon a pitvar szőnyege száz singnyi vala sodrott lenből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'Azoknak húsz oszlopa, és húsz talpa rézből vala; az oszlopok horgai, és azoknak általkötői ezüstből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Észak felől is száz singnyi. Azoknak húsz oszlopa és húsz talpa rézből; az oszlopok horgai és általkötői ezüstből valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'Napnyugot felől pedig ötven sing szőnyeg vala. Azoknak tíz oszlopa és tíz talpa; az oszlopok horgai és általkötői ezüstből valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'A napkeleti oldalon is ötven singnyi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'Egy felől tizenöt sing szőnyeg vala; három oszlopa és azoknak három talpa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'És a másik felől is: a pitvar kapujától jobbra is, balra is tizenöt sing szőnyeg, és azoknak három oszlopa, három talpa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'A pitvarnak minden szőnyege köröskörül sodrott lenből vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'Az oszlopok talpai rézből, az oszlopok horgai és általkötői pedig ezüstből valának, azoknak fejei ezüsttel beborítva. A pitvar oszlopait is mind ezüst általkötők övezték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'A pitvar kapujának leple hímzőmunka vala, kék, és bíborpiros, és karmazsinszínű, és sodrott lenből; hossza húsz sing volt, magassága pedig szélességében öt sing, a pitvar szőnyegeinek megfelelőleg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'Azoknak négy oszlopa és négy talpa rézből, horgai ezüstből valának; fejeiknek borítása, és általkötőik is ezüstből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'A hajléknak és a pitvarnak szegei pedig köröskörűl mind rézből valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Ezek a hajléknak, a bizonyság hajlékának részei, a mint megszámláltattak a Mózes meghagyásából, a Léviták szolgálatára, Ithamár, az Áron pap fia által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'Bésaléel a Húr fiának, Urinak fia a Júda nemzetségéből, csinálta mind azt, a mit az Úr parancsolt vala Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'És vele együtt Aholiáb, Akhiszamák fia, Dán nemzetségéből a ki mester vala a faragásban, a kötő és hímzőmunkában, kék, és bíborpiros, és karmazsinszínű, és lenfonállal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Mind az az arany, a mely a munkára, a szenthelynek összes munkáira feldolgoztaték, ez az áldozati arany: huszonkilencz talentom, és hétszáz harmincz siklus vala, a szent siklus szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Az ezüst pedig, a gyülekezet megszámlált tagjaitól, száz talentom, és ezer hétszáz hetvenöt siklus, a szent siklus szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'Fejenként egy beka, vagy is fél siklus, a szent siklus szerint, mindenkitől, a ki átesett a megszámláltatáson, húsz esztendőstől fölfelé, a kik hatszáz háromezeren és ötszázötvenen valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'A száz talentom ezüstből megönték a szent helyhez való talpakat, és a függöny oszlopainak talpait; száz talpat száz talentomból, egy talentomból egy talpat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'Az ezer hétszáz hetvenöt siklusból csinálák az oszlopok horgait, és beboríták azoknak fejeit, és általfogák azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Az áldozati réz pedig hetven talentom, és kétezer négyszáz siklus vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'Abból csinálák a talpakat a gyülekezet sátorának nyílásához, és a réz oltárt, az ahhoz való réz rostélyt, és az oltárnak minden edényeit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'A pitvar talpait is köröskörül, és a pitvar kapujához való talpakat, meg a hajlék összes szegeit, és a pitvar összes szegeit köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'A kék, és bíborpiros, és karmazsinszínű fonálból pedig csinálának szolgálati ruhákat a szenthelyen való szolgálatra. Áronnak is úgy készíték a szent ruhákat, a mint az Úr parancsolta vala Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Az efódot csinálák aranyból, kék, és bíborpiros, és karmazsinszínű, és sodrott lenből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'És aranyból vékony lapokat verének, és azokat fonalakká metélék, hogy feldolgozzák a kék, és a bíborpiros, és a karmazsinszínű, és a lenfonál közé, mestermunkával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Csinálának hozzá összekötött vállkötőket: a két végükön kapcsolák össze.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Az átkötő öv is, a mely rajta vala, abból való, ugyanolyan mívű vala, mint az efód: aranyból, kék, és bíborpiros, és karmazsinszínű, és sodrott lenből, a mint az Úr parancsolta Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Megcsinálák azután az ónix köveket is, arany boglárokba foglalva, kimetszve pecsétmetszés módjára, az Izráel fiainak neveire.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'És rátették azokat az efód vállkötőire, az Izráel fiaira való emlékeztetés kövei gyanánt, a mint az Úr parancsolta vala Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Megcsinálák a hósent is mestermunkával, mint az efódot, aranyból, kék, és bíborpiros, és karmazsinszínű, és sodrott lenből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Négyszögű vala a hósen, és kétrétűre készíték azt; egy arasz vala hossza, egy arasz a szélessége is két rétben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'És négy sor követ foglalának abba, ily sorban: szárdiusz, topáz, smaragd; az első sor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'A második sor: karbunkulus, zafir és gyémánt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'A harmadik sor: jáczint, agát és amethiszt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'A negyedik sor: krizolith, ónix és jáspis, a melyek mind arany boglárokba foglaltattak a magok helyén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'A kövek pedig Izráel fiainak nevei szerint valának, tizenkettő vala az ő nevök szerint, és pecsét módjára metszve, mindenik a reá való névvel, a tizenkét nemzetség szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'És csinálának a hósenre sodrott mívű fonatékot is tiszta aranyból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Azután csinálának két arany boglárt, és két arany karikát; és a két arany karikát rá tevék a hósen két szegletére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'A két arany fonatékot pedig a hósen két szegletén levő két karikába fűzték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'És a két fonaték másik két végét oda foglalák a két boglárhoz, és azokat az efód vállkötőihez tűzék, annak előrészére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Csinálának más két arany karikát is, és oda tevék azokat a hósen két szegletére, azon a szélén, a mely befelé vala az efód felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'És csinálának még két arany karikát, és azokat az efód két vállkötőjére tevék, alól, annak előrésze felől, az összefoglalás mellett, az efód övén felül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'És a hósent az ő karikáinál fogva odacsatolák az efód karikáihoz, kék zsinórral, hogy az efódnak öve felett legyen, és el ne váljék a hósen az efódtól; a mint az Úr parancsolta vala Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'És megcsinálák az efód palástját takácsmunkával, egészen kék lenből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'És a palást közepén levő nyílás olyan vala, mint a pánczélnak nyílása; szegése vala a nyílásnak köröskörül, hogy el ne szakadjon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'És a palást alsó peremére csinálának gránátalmákat, kék, és bíborpiros, és karmazsinszinű sodrott fonálból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Csinálának csengettyűket is tiszta aranyból, és tevék a csengettyűket a gránátalmák közé, a palást peremére köröskörül a gránátalmák közé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'Csengettyű meg gránátalma, csengettyű meg gránátalma a palást peremén köröskörül, hogy abban szolgáljanak, a mint az Úr parancsolta vala Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Megcsinálák a len köntösöket is takácsmunkával, Áronnak és az ő fiainak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'A len süveget is, a süveg ékességeit is lenből, és a gyolcs lábravalókat sodrott lenből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'Az övet is sodrott lenből, és kék, bíborpiros és karmazsinszínű fonálból hímzőmunkával, a mint az Úr parancsolta vala Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'A szent koronához való lapot is megcsinálák tiszta aranyból, és felírák rá a pecsétmetsző módjára: Szentség az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'És kötének reá kék zsinórt, hogy felkössék azzal a süvegre, a mint az Úr parancsolta vala Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'Így végezteték el a gyülekezet sátora hajlékának egész munkája; és az Izráel fiai egészen úgy csinálák, a mint az Úr parancsolta vala Mózesnek, úgy csinálták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'És vivék a hajlékot Mózeshez: a sátort és annak minden eszközét, horgait, deszkáit, reteszrúdait, oszlopait, és talpait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'A veresre festett kosbőrökből készült takarót is, és a borzbőrökből készült takarót, és a takarófüggönyt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'A bizonyság ládáját, annak rúdait, és a fedelet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'Az asztalt és annak minden edényét, és a szent kenyeret.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'A tiszta gyertyatartót: annak mécseit, a felszereléshez való mécseket s minden hozzávalót, a világító olajjal együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'Az arany oltárt, a kenetnek olaját, a fűszerekből való füstölőt, és a sátor nyílására való leplet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'A réz oltárt és annak réz rostélyát, rúdait és minden edényeit, a mosdómedenczét és annak lábát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'A pitvar szőnyegeit, oszlopait, talpait: és a pitvar kapujára való leplet, annak köteleit, szegeit, és a hajlék szolgálatjára való minden eszközt a gyülekezet sátoránál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'A szolgálati ruhákat, a szenthelyen való szolgálatra, a szent ruhákat Áron papnak, és fiainak ruháit a papi tisztre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'A mint parancsolta vala az Úr Mózesnek, egészen úgy csinálának az Izráel fiai minden munkát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'És megtekinte Mózes minden munkát, és ímé elkészíték azt, úgy készíték el, a mint az Úr parancsolta vala, és megáldá őket Mózes.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'És szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'Az első hónapban, a hónap első napján, állítsd fel a gyülekezet sátorának hajlékát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'És tedd oda a bizonyság ládáját, és fedd be a ládát a fedéllel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Azután vidd be az asztalt, és hozd azt rendbe a reávalókkal. Vidd be a gyertyatartót is, és gyújtsd meg annak mécseit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'És helyheztesd a füstölő áldozat arany oltárát a bizonyság ládája elé, tedd fel a leplet a hajlék nyílására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Azután helyheztesd az egészen égőáldozat oltárát a gyülekezet sátora hajlékának nyílása elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'A mosdómedenczét pedig helyheztesd a gyülekezet sátora közé és az oltár közé, és önts belé vizet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Azután állítsd fel köröskörül a pitvart, és a pitvar kapujára tedd rá a leplet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Azután vedd a kenetnek olaját, és kend meg a hajlékot és mind azt a mi benne van: így szenteld meg azt, és minden edényét, hogy szent legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Kend meg az egészen égőáldozat oltárát is és annak minden edényét; így szenteld meg az oltárt, hogy az oltár legyen szentséges.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'A mosdómedenczét és lábát is kend meg; így szenteld meg azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Azután állítsd Áront és az ő fiait a gyülekezet sátorának nyílásához, és mosd meg őket vízzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'És öltöztesd fel Áront a szent ruhákba, és kend fel őt; így szenteld fel, és legyen papom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Fiait is állítsd elő és öltöztesd fel őket köntösökbe;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'És kend fel őket, a mint az ő atyjokat felkenéd, hogy legyenek papjaim, és lészen az ő megkenetésök nékik örökös papság, az ő nemzetségökben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'És egészen úgy cselekedék Mózes, a mint az Úr parancsolta néki, úgy cselekedék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'Lőn azért a második év első hónapjában, a hónap első napján, hogy felállíták a hajlékot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Mózes tehát felállítá a hajlékot, és letevé annak talpait, a deszkáit is felállítá, beilleszté a reteszrúdakat, és felállítá annak oszlopait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Azután kifeszíté a hajlékra a sátort, és a sátor takaróját is reá teríté felülről, a mint parancsolta vala az Úr Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'És vevé és betevé a bizonyságot is a ládába, a rúdakat pedig a ládára tevé, és a ládára felül helyezteté a fedelet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'Azután bevivé a ládát a hajlékba, és feltevé a takaró függönyt, és elfedezé a bizonyság ládáját, a mint az Úr parancsolta vala Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Az asztalt is bevivé a gyülekezet sátorába, a hajléknak északi oldalába, a függönyön kivül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'És rakott arra kenyereket sorban az Úr előtt, a mint az Úr parancsolta vala Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'És a gyertyatartót helyhezteté a gyülekezet sátorába az asztal ellenébe, a hajléknak déli oldalán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'És meggyújtá a mécseket az Úr előtt, a mint az Úr parancsolta vala Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Az arany oltárt pedig helyhezteté a gyülekezet sátorába a függöny elébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'És füstölögtete rajta fűszerekből való füstölőt, a mint az Úr parancsolta vala Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'A hajlék nyílására a leplet is felvoná.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Az egészen égőáldozat oltárát pedig helyhezteté a gyülekezet sátora hajlékának nyílása elé, és áldozék azon egészen égőáldozattal és ételáldozattal, a mint parancsolta vala az Úr Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'A mosdómedenczét pedig helyhezteté a gyülekezet sátora közé és az oltár közé, és önte abba vizet a mosdásra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'És megmosák abból Mózes és Áron és az ő fiai kezeiket és lábaikat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'Mikor a gyülekezet sátorába menének, és mikor az oltárhoz járulának, megmosdának, a mint az Úr parancsolta vala Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Azután felállítá a pitvart a hajlék és az oltár körül, és a pitvar kapujára feltevé a leplet. Így végezé el Mózes a munkát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'És a felhő befedezé a gyülekezet sátorát, és az Úrnak dicsősége betölté a hajlékot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'És Mózes nem mehete be a gyülekezet sátorába, mert a felhő rajta nyugovék, és az Úrnak dicsősége tölté be a hajlékot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'És mikor a felhő felszáll vala a hajlékról, az Izráel fiai elindulának; így lőn egész utazásuk alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'Ha pedig a felhő nem szálla fel, ők sem indulának el, míg csak fel nem szálla.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'Mert az Úrnak felhője vala a hajlékon nappal, éjjel pedig tűz vala azon, az Izráel egész háznépének láttára, egész utazásuk alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Szólítá Mózest és beszéle vele az Úr a gyülekezet sátorából, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Szólj Izráel fiainak, és mondd meg nékik: Ha valaki közületek áldozni akar az Úrnak: barmokból, tulok- és juhfélékből áldozzatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Ha tulokféléből áldozik egészen égőáldozattal: hímmel és éppel áldozzék. A gyülekezet sátorának ajtajához vigye azt, hogy kedvessé legyen az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'És tegye kezét az égőáldozat fejére, hogy kedves legyen ő érette, hogy engesztelést szerezzen az ő számára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'És ölje meg a tulkot az Úr előtt, az Áron fiai pedig, a papok, vigyék fel a vért, és hintsék a vért köröskörűl az oltárra, a mely a gyülekezet sátorának nyílásánál van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Azután vonja le az égőáldozat bőrét, azt pedig vagdalja el tagjaira.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'És az Áron pap fiai gerjeszszenek tüzet az oltáron, és rakjanak fát a tűzre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Azután rakják az Áron fiai, a papok, a tagokat: a fejet és a kövérjét a fára, a mely az oltáron lévő tűzön van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'A belét pedig és lábszárait mossa meg vízben, és füstölögtesse el a pap az egészet az oltáron egészen égőáldozatul. Ez a tűzáldozat kedves illatú az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Ha pedig a juhfélékből: bárányokból vagy kecskékből akar valaki áldozni égőáldozatul, hímmel és éppel áldozzék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'És ölje meg azt az oltár északi oldalánál az Úr előtt, az Áron fiai pedig, a papok, hintsék annak vérét az oltárra köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'Azután vagdalja el azt tagjaira, a fejével és kövérjével együtt, a pap pedig rakja azokat a fára, a mely az oltáron lévő tűzön van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'A belet és a lábszárakat mossa meg vízben, a pap pedig áldozza meg az egészet és füstölögtesse el az oltáron égőáldozatul. Ez a tűzáldozat kedves illatú az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Ha pedig madárféléből akar áldozni égőáldozatul az Úrnak, gerliczékből vagy galambfiakból áldozzék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'És vigye azt a pap az oltárhoz, és tekerje ki annak a fejét, és füstölögtesse el az oltáron, a vérét pedig bocsássa ki az oltár falára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'A begyét pedig rútságával egyben vegye ki, és vesse azt az oltár keleti oldalára, a hamu helyére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'És hasítsa meg azt a szárnyain, de el ne szakaszsza egymástól, és füstölögtesse el azt a pap az oltáron a fán, a mely a tűzőn van, égőáldozatul. Tűzáldozat ez, kedves illatú az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'Mikor valaki ételáldozatot akar áldozni az Úrnak, lisztlángból áldozzék, és öntsön arra olajat, és temjént is tegyen arra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'És vigye azt az Áron fiaihoz, a papokhoz, és vegyen ki abból egy tele marokkal; annak lisztlángjából és olajából, az egész temjénével együtt, és füstölögtesse el a pap az oltáron annak emlékeztető részéül. Ez a tűzáldozat kedves illatú az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'A mi pedig megmarad az ételáldozatból, Ároné és az ő fiaié legyen; szentséges áldozat ez az Úrnak tűzáldozatai között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Hogyha pedig ételáldozatot kemenczében sültből akar áldozni valaki lisztlángból, olajjal elegyített kovásztalan lepényei, vagy olajjal megkent kovásztalan pogácsái legyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Ha pedig a te áldozatod serpenyőben sült ételáldozat, olajjal elegyített kovásztalan lisztlángból legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'Darabold azt el, és önts reá olajat, ételáldozat ez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Ha pedig a te ételáldozatod rostélyon sült, lisztlángból, olajjal készíttessék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'És vidd el az ételáldozatot, a mi ezekből készült, az Úrnak, és azt a papnak bemutatván, az vigye azt el az oltárhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'És vegyen a pap az ételáldozatból emlékeztető részt, és füstölögtesse el az oltáron; tűzáldozat ez, kedves illatú az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'A mi pedig megmarad az ételáldozatból, Ároné és az ő fiaié legyen; szentséges áldozat ez az Úrnak tűzáldozatai között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Semmi ételáldozat, a mit az Úrnak áldoztok, kovászszal ne készüljön; mert kovászból és mézből semmit se füstölögtethettek az Úrnak a tűzáldozatok között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Zsengeáldozatul felvihetitek azokat az Úrnak, de az oltárra nem juthatnak fel kedves illatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Minden te ételáldozatodat pedig sózd meg sóval, és a te ételáldozatodból soha el ne maradjon a te Istened szövetségének sója; minden te áldozatodhoz sót adj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Ha zsengékből való ételáldozatot áldozol az Úrnak, tűznél pergelt kalászból, és zsenge gabona-darából áldozzad a te zsengéidnek áldozatát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'Adj hozzá olajat, és tégy reá tömjént; ételáldozat ez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'A pap pedig füstölögtesse el annak emlékeztető részét a darából és olajból, az egész tömjénnel együtt. Tűzáldozat ez az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'Hogyha hálaáldozattal áldozik valaki, ha tulokféléből, akár hímmel, akár nősténynyel áldozik: ép barmot vigyen az Úr elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'És tegye a kezét az ő áldozatjának fejére, és ölje meg azt a gyülekezet sátorának nyílásánál, és Áron fiai, a papok, öntsék a vért köröskörül az oltárra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Azután vigyen a hálaáldozatból tűzáldozatot az Úrnak: a kövérjét, a mely a belet takarja, és mindazt a kövérjét, a mely a belek között van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'A két vesét is, és a rajtuk lévő kövérséget, a mely a véknyaknál van, és a májon lévő hártyát a vesékkel együtt vegye el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'És füstölögtessék el azt Áron fiai az oltáron az égőáldozattal együtt a tűzön lévő fán: tűzáldozat ez, kedves illatú az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Hogyha pedig valaki juhféléből áldozik hálaáldozatot az Úrnak, akár hím, akár nőstény legyen az, épekkel áldozzék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Ha bárányt visz ő az ő áldozatául, vigye azt az Úr elébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'És tegye a kezét az ő áldozatjának fejére, azután ölje meg azt a gyülekezet sátora előtt, és az Áron fiai öntsék a vérét az oltárra köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Azután áldozzék az Úrnak e hálaáldozatból tűzáldozatot: a kövérjét, a farkát egészen, a melyet a hátagerézdi végénél vágjon el, és a belét takaró kövérjét, és minden kövérjét, a mely a belek közt van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'És a két vesét is, és a rajtuk lévő kövérséget, a mely a véknyaknál van, és a májon lévő hártyát a vesékkel együtt vegye el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'És füstölögtesse el azt a pap az oltáron: tűzáldozati eledel ez az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Hogyha kecskével áldozik valaki, azt is az Úr elé vigye.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'És tegye kezét annak fejére, és ölje meg azt a gyülekezetnek sátora előtt, és öntsék az Áron fiai annak vérét az oltárra körül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'És áldozzék abból tűzáldozatot az Úrnak: a kövérjét, a mely betakarja a belet, és mindazt a kövérjét, a mely a belek között van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'A két vesét is, és a rajtuk lévő kövérséget, a mely a véknyaknál van, és a májon lévő hártyát a vesékkel együtt vegye el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'És füstölögtesse el azokat a pap az oltáron tűzáldozati eledelül, kedves illatul. A kövérje mind az Úré legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Örökkévaló rendtartás legyen a ti nemzetségeiteknél minden ti lakhelyeteken: semmi kövért és semmi vért meg ne egyetek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Szóla ismét az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Szólj az Izráel fiainak, mondván: Ha valaki tévedésből vétkezik az Úrnak valamely parancsolata ellen, úgy a mint nem kellene cselekednie, és a parancsolatok közül valamelyiknek ellene cselekszik:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'Ha a felkent pap vétkezik, a népnek romlására: hozzon az ő bűnéért, a melyet elkövetett, egy tulkot, fiatal ép marhát az Úrnak bűnáldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'És vigye a tulkot a gyülekezet sátorának nyílásához, az Úr elé, és tegye a kezét a tuloknak fejére, és a tulkot ölje meg az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'És vegyen a felkent pap a tuloknak véréből, és vigye be azt a gyülekezet sátorába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'És mártsa be a pap az ő újját a vérbe, és hintsen a vérből hétszer az Úr előtt a szent hajléknak függönye felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'És tegyen a pap a vérből az Úr előtt a fűszerekből való füstölő oltár szarvaira, a mely ott van a gyülekezet sátorában; a tulok vérét pedig mind öntse az egészen égőáldozat oltárának aljára, a mely a gyülekezet sátorának nyílásánál van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Azután a tuloknak, a mely bűnáldozatra való, minden kövérjét szedje ki belőle: azt a kövérjét, amely betakarja a belet, és mindazt a kövérjét, a mi a belek között van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'A két vesét is, és a rajtuk lévő kövérséget, a mely a véknyaknál van, és a májon lévő hártyát a vesékkel együtt vegye el,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'A miképen kiszedik a hálaáldozatra való tulokból; és füstölögtesse el azokat a pap az égőáldozatnak oltárán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'A tuloknak pedig bőrét és minden húsát, fejével és lábszáraival együtt, bélit és ganéját,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'És mind az egész tulkot vigye ki a táboron kivül tiszta helyre, a hová a hamut öntik: és égesse el azt a fán, tűzben; ott égessék meg, a hová a hamut öntik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Hogyha pedig az Izráel fiainak egész közönsége megtéved, és a gyülekezet előtt rejtve marad e dolog; és valami olyat cselekesznek az Úrnak valamelyik parancsolatja ellen, a mit nem kellett volna cselekedni, és bűnösökké lesznek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'Mikor kitudódik a bűn, a melyet elkövettek: akkor áldozzék a gyülekezet egy tulkot, fiatal marhát a bűnért, és vigye azt a gyülekezetnek sátora elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'És a gyülekezet vénei tegyék kezeiket a tuloknak fejére az Úr előtt, és ölje meg a tulkot a pap az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Azután vigyen be a felkent pap a tulok véréből a gyülekezet sátorába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'És mártsa be a pap az ő újját a vérbe, és hintsen abból hétszer az Úr előtt a függöny felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'És tegyen a vérből az oltár szarvaira is, a mely az Úr előtt, a gyülekezet sátorában van; a vért pedig mind öntse az egészen égőáldozat oltárának aljára, a mely a gyülekezet sátorának nyílása előtt van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Minden kövérjét pedig szedje ki belőle, és füstölögtesse el az oltáron.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'És úgy cselekedjék azzal a tulokkal, mint a bűnért való tulokkal cselekvék, úgy cselekedjék vele, és engesztelést szerez számukra a pap, és megbocsáttatik nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'És vigye ki a tulkot a táboron kivül, és égesse el azt, miképen elégette az első tulkot. A gyülekezet bűnéért való áldozat ez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Ha fejedelem vétkezik, és cselekeszik valamit az Úrnak, az ő Istenének parancsolata ellen, a mit nem kellett volna cselekedni, és bűnössé lesz tévedésből:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'Ha tudtára esik néki a bűne, a melyet elkövetett, akkor vigyen áldozatul egy ép kecskebakot,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'És tegye kezét a baknak fejére, és ölje meg azt azon a helyen, a hol megölik az egészen égőáldozatot, az Úr előtt; bűnért való áldozat ez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'És vegyen a pap a bűnért való áldozatnak véréből az ő újjával, és tegyen az égőáldozat oltárának szarvaira; a vérét pedig öntse az égőáldozatok oltárának aljára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'A kövérjét pedig mind füstölögtesse el az oltáron, mint a hálaáldozatnak kövérjét. Így szerezzen néki a pap engesztelést az ő bűnéért, és megbocsáttatik néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Ha pedig a föld népe közül vétkezik valaki tévedésből, mivelhogy az Úrnak valamelyik parancsolatja ellen olyat cselekeszik, a mit nem kellett volna cselekedni, és bűnössé lesz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'Ha tudtára esik néki az ő bűne, a melyet elkövetett: vigyen áldozatul az ő bűnéért, a melyet elkövetett, egy ép nőstény kecskét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'És tegye a kezét a bűnért való áldozat fejére, és ölje meg a bűnért való áldozatot az egészen égőáldozat helyén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'És vegyen a pap annak véréből az újjával, és tegyen az égőáldozat oltárának szarvaira, a vérét pedig mind öntse az oltárnak aljára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Azután vegye el minden kövérjét, a mint elveszik a hálaáldozatnak kövérjét: és füstölögtesse el a pap az oltáron, kedves illatul az Úrnak. Ekképen szerezzen néki engesztelést a pap, és megbocsáttatik annak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Ha pedig bárányt visz az ő bűnért való áldozatául, nőstényt és épet vigyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'És tegye a kezét annak a bűnért való áldozatnak fejére, és ölje meg azt bűnért való áldozatul azon a helyen, a hol megölik az egészen égőáldozatot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'És vegyen a pap a bűnért való áldozat véréből az újjával, és tegyen az égőáldozat oltárának szarvaira; a vért pedig mind öntse az oltárnak aljára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Azután vegye el minden kövérjét, a mint elveszik a hálaáldozatra való báránynak kövérjét, és füstölögtesse el azokat a pap az oltáron az Úrnak tűzáldozataival. Ekképen szerezzen néki engesztelést a pap az ő bűnéért, a melyet elkövetett, és megbocsáttatik néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'Ha azzal vétkezik valaki, hogy hallotta a káromló beszédet, és bizonyság lehetne, hogy látta, vagy tudja: ha meg nem jelenti azt, de hordozza az ő vétségének terhét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'Vagy ha valaki illet akármely tisztátalan dolgot, akár tisztátalan vadnak, akár tisztátalan baromnak, akár tisztátalan féregnek holttestét, és nem tud arról, hogy tisztátalanná lesz és vétkezik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'Vagy ha illeti az ember tisztátalanságát, akármi tisztátalanságát, a mely tisztátalanná tesz, és nem tudta azt, hanem azután értette meg, hogy vétkezett;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'Vagy ha valaki hirtelenkedve tesz esküt az ő ajkaival rosszra vagy jóra, vagy akármi az, a mire hirtelenkedve esküszik az ember, ha nem tudott arról, de azután megértette, hogy azok közül valamelyikben vétkezett:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'Akkor, mivelhogy vétkezett ezek közül valamelyikben, vallja meg, hogy mi az, a miben bűnössé lett;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'És vigyen az ő vétkéért az Úrnak, az ő bűnéért, a melyet elkövetett, egy nőstény bárányt vagy kecskét a nyájból, bűnért való áldozatul. Ekképen szerezzen néki engesztelést a pap az ő bűnéért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Ha pedig nincsen egy bárányhoz való módja: vigyen az ő vétkéért való áldozatra két gerliczét vagy két galambfiat az Úrnak, az egyiket bűnért való áldozatul, a másikat egészen égőáldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'És vigye azokat a paphoz; az pedig áldozza meg először azt, a mely bűnért való áldozat, és tekerje ki annak fejét nyakcsigájánál, úgy, hogy el ne szakaszsza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'És hintsen a bűnért való áldozat véréből az oltár oldalára, a többi vért pedig nyomják ki az oltár aljára; bűnért való áldozat ez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'A másikat készítse el egészen égőáldozatul, úgy, a mint szokás; ekképen szerez néki engesztelést a pap az ő bűnéért, a melyet elkövetett, és megbocsáttatik néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Ha pedig nincs módja két gerliczéhez vagy két galambfihoz sem: vigyen áldozatul az, a ki vétkezett, egy efa lánglisztnek tizedrészét bűnért való áldozatul; ne tegyen ahhoz olajat, és ne adjon ahhoz tömjént, mert bűnért való áldozat ez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'És vigye azt a paphoz, és markolja ki abból a pap teli marokkal az emlékeztető részét, és füstölögtesse el az oltáron az Úrnak tűzáldozataival. Bűnért való áldozat az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'Így szerezzen néki engesztelést a pap az ő bűnéért, a melyet elkövetett valamivel ama bűnök közül, és megbocsáttatik néki. És legyen a papé, mint az ételáldozat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Azután szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'Ha valaki hűtlenséget követ el, és tévedésből vétkesen elvesz az Úrnak szentelt dolgokból: vigyen az ő vétkéért való áldozatot az Úrnak, egy ép kost a nyájból, a mint te becsülöd, ezüst siklusokban, a szent siklus szerint, vétekért való áldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'És a mit vétkesen elvett a szent dologból, azt fizesse meg, és tegye hozzá az ötödrészét, és adja azt a papnak. Így szerez néki engesztelést a pap a vétekért való áldozat kosával, és megbocsáttatik néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Hogyha vétkezik valaki, és cselekszik valamit az Úrnak valamely parancsolata ellen, a mit nem kell cselekedni, ha nem tudta is: vétkessé lesz, és hordozza az ő vétségének terhét:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'Vigyen azért a nyájból egy ép kost a paphoz, a te becslésed szerint, bűnért való áldozatul, és szerezzen néki engesztelést a pap az ő tévedéséért, a melylyel tudatlanságból tévedett, és megbocsáttatik néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Bűnért való áldozat ez, mivelhogy bűnt követett el az Úr ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Szóla ismét az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, 'Mikor vétkezik valaki, és hűtlenséget követ el az Úr ellen, tudniillik eltagadja felebarátjának reábízott vagy kezébe adott holmiját, vagy megrabolja vagy zsarolja felebarátját;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'Vagy ha elveszett holmit talált, és eltagadja, vagy valami miatt hamisan esküszik, akármi is az, a mit az ember úgy cselekszik, hogy vétkezik vele:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'Mivelhogy azért bűnössé lett és vétkezett, térítse vissza az elrablottat, a mit rabolt, vagy a zsaroltat, a mit zsarolt, vagy a reá bízottat, a mi reá bízatott, vagy az elveszettet, a mit megtalált;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'Vagy akármi legyen, a mire hamisan esküdött, fizesse meg azt teljes értéke szerint, és hozzátoldva az ötödrészét, adja azt annak, a kié volt, bűnbevallásának napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Az ő bűnéért pedig vigyen az Úrnak a nyájból egy ép kost a paphoz, a te becslésed szerint, bűnért való áldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'Így szerezzen néki engesztelést a pap az Úr előtt, és megbocsáttatik néki mindaz, a mit cselekedett, és a miben vétkezett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'Szóla ismét az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Parancsolj Áronnak és az ő fiainak, mondván: Ez az egészen égőáldozat törvénye: Legyen az egészen égőáldozat az oltáron levő tüzelőhelyen egész éjszaka, mind reggelig, és az oltárnak tüze égve maradjon azon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'A pap öltse fel az ő gyolcs ruháját, és a gyolcs lábravalót is öltse fel az ő testére, és szedje el a hamut, a mivé égette a tűz az égőáldozatot az oltáron, és töltse azt az oltár mellé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Azután vesse le azt a ruháját, és öltözzék más ruhába, és vigye ki a hamut a táboron kivül, tiszta helyre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Az oltáron lévő tűz pedig égve maradjon azon, el ne aludjék, hanem égessen fát rajta a pap minden reggel, és rakja reá az egészen égőáldozatot, és azon füstölögtesse el a hálaáldozat kövérjét is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'A tűz szüntelen égve maradjon az oltáron, és el ne aludjék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'Ez pedig az ételáldozatnak törvénye: az Áron fiai áldozzák azt az Úr előtt az oltáron.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'És vegyen valaki közülök az ételáldozat lisztlángjából egy marokkal, és annak olajából is, a tömjént pedig, a mely az ételáldozathoz való, mind; és égesse el az oltáron; annak emlékeztető része kedves illat az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'A mi pedig megmarad belőle, egyék meg Áron és az ő fiai, kovásztalanul egyék meg, szenthelyen, a gyülekezet sátorának pitvarában egyék meg azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'Ne süssék azt kovászszal, mert nékik adtam azt, részökül az én tűzáldozataimból; igen szentséges az, mint a bűnért és vétekért való áldozat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Az Áron fiai közül minden férfiú egye azt. Örökkévaló rendtartás legyen ez a ti nemzetségeiteknél az Úrnak tűzáldozatai felől. Valaki illeti azokat, szent legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Szóla ismét az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Ez Áronnak és az ő fiainak áldozatjok, a melyet az Úrnak áldozzanak, mikor felkenik őket: Egy efa lisztlángnak tizedrésze mindenkor ételáldozatul, fele reggel, fele pedig estve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'Serpenyőben készíttessék, olajjal összegyúrva vidd el azt, az ételáldozati süteményeket darabokban áldozd az Úrnak kedves illatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'A mely pap az ő helyébe kenetik fel az ő fiai közül, az mívelje ezt. Örökkévaló rendtartás ez, az Úrnak mindenestől füstölögtessék el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Mert a pap minden ételáldozatának mindenestől meg kell égettetni, nem kell abból semmit megenni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, 'Szóla ismét az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, 'Szólj Áronnak és az ő fiainak, mondván: Ez a bűnért való áldozat törvénye: a mely helyen meg szokták ölni az egészen égőáldozatot, azon a helyen öljék meg a bűnért való áldozatot az Úr előtt; igen szentséges az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, 'A mely pap megáldozza azt a bűnért, az egye meg azt, szent helyen egye meg, a gyülekezet sátorának pitvarában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, 'Valami annak a húsát érinti, szent legyen, és ha annak véréből valami a ruhájára esik valakinek, azt, a mire a vér esett, mosd meg szenthelyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, 'És a cserépedényt, a melyben azt főzték, törjék el; hogyha pedig érczfazékban főzték, súrolják meg, és mossák meg vízzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, 'A papok között minden férfiú eheti azt; igen szentséges az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, 'Valamely bűnért való áldozat véréből bevisznek a gyülekezet sátorába, a szenthelyen való engesztelés végett, az meg nem ehető: tűzzel égettessék meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'Ez pedig a vétekért való áldozatnak törvénye; igen szentséges az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'A mely helyen megölik az egészen égőáldozatot, ott öljék meg a vétekért való áldozatot is, és a vérét hintsék az oltárra köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'A kövérjét pedig áldozzák meg mind, a farkát is, és a mely kövér a belet takarja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'A két veséjét és a rajtuk lévő kövérséget, a mely a véknyaknál van, úgyszintén a májon lévő hártyát a vesékkel együtt szedje ki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'És füstölögtesse el azokat a pap az oltáron tűzáldozatul az Úrnak. Vétekért való áldozat ez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'A papok között minden férfiú eheti azt, szenthelyen egyék meg; igen szentséges az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'A milyen a bűnért való áldozat, olyan a vétekért való áldozat is, egy törvényök van nékik. Azé a papé az, a ki engesztelést szerez vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Ha a pap egészen égőáldozatot áldoz valakiért, az égőáldozat bőre, a melyet megáldoz, azé a papé legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Minden ételáldozat is, a melyet kemenczében sütnek és minden, a mit rostélyon vagy serpenyőben készítenek, a papé legyen, a ki azt áldozta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Az olajjal elegyített és száraz ételáldozat is mind az Áron fiaié legyen közösen, egyiké úgy, mint a másiké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'Ez pedig a hálaáldozat törvénye, a melyet áldoznak az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Ha dicsőítésül áldozza azt valaki, a dicsőítés áldozatjával együtt áldozzék olajjal elegyített kovásztalan lepényeket, és olajjal megkent kovásztalan pogácsákat, és lisztlángból gyúrt, olajjal elegyített lepényeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'A lepényeken kivül kovászos kenyeret is vigyen áldozatául, dicsőítő hálaáldozatjával együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'És mindezekből az áldozatokból áldozzék egyet-egyet az Úrnak felmutatott áldozatul; és legyen azé a papé, a ki a hálaáldozatnak vérét elhinti.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'És az ő dicsőítő hálaáldozatjának húsát, az ő áldozásának napján egyék meg; ne hagyjon abból reggelig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Hogyha fogadásból vagy szabadakaratból áldozza valaki az ő áldozatát, a mely napon áldozza azt, azon a napon egyék meg az ő áldozatát; a mi pedig megmarad abból, másnap egyék meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'A mi pedig annak az áldozatnak húsából tovább is megmarad, harmadnapon tűzzel égettessék meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Mert ha az ő hálaadó áldozatának húsából harmadnapon eszik valaki, nem lesz az kedves; a ki áldozta azt, annak nem számíttatik az az ő javára, sőt útálatos lesz; és valaki eszik abból, hordozza az ő vétségének terhét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Azt a húst pedig, a mely valami tisztátalanhoz ér, meg ne egyék, hanem tűzzel égessék meg. A mi különben a húst illeti, mindenki ehetik húst, a ki tiszta;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'De az, a ki eszik a békeáldozatnak húsából, a mely az Úré, noha az ő tisztátalansága rajta van, az ilyen ember gyomláltassék ki az ő népe közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Ha valaki akármi tisztátalanhoz ér, tisztátalan emberhez, vagy tisztátalan baromhoz, vagy akármihez, a mi tisztátalan útálatosság, és eszik a hálaadó áldozatnak húsából, a mely az Úré, gyomláltassék ki az az ember az ő népe közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Szóla ismét az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Szólj az Izráel fiainak, mondván: Az ökörnek, a báránynak és a kecskének semmi kövérjét meg ne egyétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'A hullott állatnak kövérje, és a vadtól megszaggatottnak kövérje, akármi munkához felhasználható, de enni meg ne egyétek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Mert akárki egyék is az aféle állatoknak kövérjéből, a melyekből tűzáldozatot visznek az Úrnak, az az ember, a ki ilyet eszik, gyomláltassék ki az ő népe közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'És semmi vért se egyetek meg bármely lakhelyeteken: se madárnak, se baromnak vérét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Valaki megeszik valami féle vért, az az ember gyomláltassék ki az ő népe közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Szóla ismét az Úr Mózesnek és monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Szólj az Izráel fiainak, mondván: A ki hálaáldozattal áldozik az Úrnak, maga vigye az Úrnak az ő áldozatát az ő hálaáldozatából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'A maga keze vigye az Úrnak tűzáldozatát: a kövérjét a szegyével együtt vigye el, a szegyét azért, hogy meglóbálják azt az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'A pap pedig füstölögtesse el azt a kövért az oltáron, a szegye pedig legyen Ároné és az ő fiaié.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'A jobblapoczkát is a papnak adjátok a hálaadó áldozatból, hogy azt felmutassa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'A ki Áron fiai közül a hálaáldozat vérét és kövérjét megáldozza, a jobblapoczka annak a része legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Mert a meglóbált szegyet és a felmutatott lapoczkát elveszem Izráel fiaitól az ő hálaadó áldozataikból, és adom azokat Áron papnak és az ő fiainak, örökre kiszabott részül, az Izráel fiaitól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'Ez az Áron felkenetési része, és az ő fiainak felkenetési része az Úrnak tűzáldozataiból, a naptól fogva, a melyen előállítá őket, hogy papi szolgálatot tegyenek az Úrnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'A melyet parancsolt az Úr, hogy adják nékik az Izráel fiai, a mely napon felkente őket, örökre kiszabott részül az ő nemzetségökben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Ez az egészen égőáldozatnak, az ételáldozatnak, a bűnért és a vétekért való áldozatnak, a felavatási áldozatnak és a hálaáldozatnak törvénye,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'A melyet parancsolt az Úr Mózesnek a Sinai hegyen, a mely napon parancsolta az Izráel fiainak a Sinai pusztában, hogy áldozzanak az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Szóla továbbá az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Vegyed Áront és az ő fiait is vele, és az öltözeteket, a kenetnek olaját, és bűnért való áldozati tulkot, két kost és egy kosár kovásztalan kenyeret.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'És az egész gyülekezetet gyűjtsd egybe a gyülekezet sátorának nyílásához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'És a képen cselekedék Mózes, a mint az Úr parancsolta vala néki, és egybe gyűle a gyülekezet a gyülekezet sátorának nyílásához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Akkor monda Mózes a gyülekezetnek: Ez a dolog, a mit az Úr parancsolt cselekedni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'És előállatá Mózes Áront és az ő fiait, és megmosá őket vízzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'És reá adá Áronra a köntöst, és felövezé őt az övvel, és reáveté a palástot, az efódot is reáadá, és felövezé az efód övével, és megerősíté azt rajta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'És feltevé arra a hósent, és betevé a hósenbe az Urimot és a Thummimot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Azután feltevé fejére a süveget, és elől odatevé a süvegre az arany lapot, a szent koronát, a mint parancsolta vala az Úr Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Vevé Mózes a kenetnek olaját is, és megkené a hajlékot minden bennevalóval egybe, és felszentelé azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'És hinte abból az oltárra is hétszer, és felkené az oltárt és annak minden edényét, a mosdómedenczét is a lábával együtt, hogy azokat megszentelje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Az Áron fejére is tölte a kenetnek olajából, és megkené őt, hogy felszentelje őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'És előállatá Mózes az Áron fiait is, és felöltözteté azokat is az ő köntöseikbe, és felövezé őket övvel, felköté nékik a süvegeket is, a mint az Úr parancsolta vala Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Azután előhoza egy tulkot a bűnért való áldozatra, és Áron az ő fiaival egybe a bűnért való áldozat tulkának fejére tevé az ő kezét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'És miután megölték azt, vőn Mózes annak véréből, és tőn az újjával az oltárnak szarvaira köröskörül, és megtisztítá az oltárt, a többi vért pedig önté az oltárnak aljára; és felszentelte azt, hogy engesztelést szerezzen rajta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Azután vevé mindazt a kövérséget, a mely annak a bélin vala, és a máj hártyáját, és a két veséjét és azoknak kövérségét, és elfüstölögteté Mózes azokat az oltáron.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'A tulkot pedig, azaz annak bőrét, húsát és ganéját megégeté tűzzel a táboron kivül, a mint az Úr parancsolta vala Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Azután előállatá az égőáldozatra való kost, és Áron és az ő fiai rátevék kezeiket a kos fejére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'És megölék azt; Mózes pedig elhinté a vért az oltárra köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'És a kost tagjaira vagdalák, és Mózes elfüstölögteté annak a fejét, a tagjait és a kövérjét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'A beleket pedig és a lábszárakat megmosta vízben, és elfüstölögteté Mózes az egész kost az oltáron. Kedves illatú égőáldozat ez, tűzáldozat ez az Úrnak, a mint megparancsolta vala az Úr Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Azután előállatá a másik kost is, a felavatási kost, és rátevék Áron és az ő fiai kezeiket a kos fejére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'És megölék azt; Mózes pedig vőn annak véréből, és tőn abból az Áron jobb fülének czimpájára, és jobb kezének hüvelykére és jobb lábának hüvelykére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Előállatá az Áron fiait is, és tőn Mózes a vérből azok jobb fülének czimpájára, és jobb kezöknek hüvelykére és jobb láboknak hüvelykére; azután oda tölté Mózes a vért az oltárra köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'És vevé a kövérjét és a farkát és mindazt a kövérjét, a mely a bélen van, továbbá a máj hártyáját, és a két vesét azoknak kövérjével egybe, és a jobb lapoczkát;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'És a kovásztalan kenyerek kosarából, a mely az Úr előtt vala, vőn egy kovásztalan lepényt, egy olajos kalácsot, és egy pogácsát, és raká azokat a kövérségekre és a jobb lapoczkára;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'És tevé mindezeket az Áron kezeire és az ő fiainak kezeire, és meglóbáltatá azokat az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Azután elvevé azokat Mózes az ő kezeikből, és elfüstölögteté az oltáron az egészen égőáldozattal egybe. Felavatási áldozatok ezek, kedves illatú tűzáldozat ez az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Elvevé pedig Mózes a szegyet, és meglóbálá azt az Úr előtt; a felavatási kosból a Mózes része lőn ez, a mint megparancsolta vala az Úr Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Azután vőn Mózes a kenetnek olajából és a vérből, a mely az oltáron vala, és meghinté Áront és az ő ruháit, az ő fiait és az ő fiainak ruháit ő vele együtt, és megszentelé Áront és az ő ruháit, és az ő fiait és az ő fiainak ruháit ő vele együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'És monda Mózes Áronnak és az ő fiainak: Főzzétek meg a húst a gyülekezet sátorának nyílásánál, és ott egyétek meg azt és a kenyeret, a mely a felavatási áldozat kosarában van, a miképen megparancsoltam, mondván: Áron és az ő fiai egyék meg azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'A mi pedig megmarad a húsból és kenyérből, tűzzel égessétek meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'De a gyülekezet sátorának nyílásán ki ne menjetek hét napig, addig a napig, a melyen betelnek a ti felavatástoknak napjai, mert hét nap avat fel benneteket az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'A miképen e napon cselekedett, úgy parancsolta az Úr hogy cselekedjünk, hogy néktek engesztelést szerezzünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'A gyülekezet sátorának nyílásánál maradjatok éjjel és nappal hét napig, és tartsátok meg, a mit megtartani rendelt az Úr, hogy meg ne haljatok; mert így parancsolta vala nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Áron azért és az ő fiai mind akképen cselekedének, a mint megparancsolta vala nékik az Úr Mózes által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'És lőn a nyolczadik napon, hogy szólítá Mózes Áront és az ő fiait, és Izráelnek véneit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'És monda Áronnak: Végy egy borjút, fiatal bikát bűnért való áldozatul, és egy kost egészen égőáldozatul, épek legyenek, és vidd az Úr elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Szólj Izráel fiainak is, mondván: Vegyetek egy kecskebakot bűnért való áldozatul, és egy esztendős borjút és bárányt, épek legyenek, egészen égőáldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'És egy ökröt és egy kost hálaáldozatul, hogy megáldozzátok az Úr előtt, és olajjal elegyített ételáldozatot; mert ma az Úr megjelenik néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Elvivék azért, a miket Mózes parancsolt vala, a gyülekezet sátora elé, és odajárula az egész gyülekezet, és megálla ott az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'És monda Mózes: Ez a dolog, a melyet az Úr parancsolt, cselekedjétek meg; és megjelenik néktek az Úr dicsősége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Áronnak pedig monda Mózes: Járulj az oltárhoz, és készítsd el a te bűnért való áldozatodat és egészen égőáldozatodat, és végezz engesztelést magadért és a népért. Készítsd el a nép áldozatát is, és végezz engesztelést érettök is, a mint megparancsolta az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Járula azért Áron az oltárhoz, és megölé a borjút, a mely az övé, bűnért való áldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Áron fiai pedig odavivék ő hozzá a vért, és ő bemártá az újját a vérbe, és tőn abból az oltár szarvaira, a többi vért pedig kiönté az oltár aljához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'A kövérjét pedig és a veséket és a máj hártyáját elfüstölögteté a bűnért való áldozatból az oltáron, a mint az Úr parancsolta vala Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'A húst pedig és a bőrt tűzzel égeté meg a táboron kivül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Azután megölé az egészen égőáldozatot, Áron fiai pedig odavivék ő hozzá a vért, és ő elhinté azt az oltáron köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Az egészen égőáldozatot is odavivék hozzá darabonként, a fejével együtt, és elfüstölögteté az oltáron.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'És megmosá a belet és a lábszárakat, és elfüstölögteté az oltáron az egészen égőáldozattal egybe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Azután megáldozá a nép áldozatát; vevé ugyanis a bűnért való áldozat bakját, a mely a népé, és megölé azt, és megáldozá azt bűnért való áldozatul, mint az előbbit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Azután előhozá az egészen égőáldozatot, és elkészíté azt szokás szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Előhozá az ételáldozatot is, és vőn abból egy teli marokkal, és elfüstölögteté az oltáron a reggeli egészen égőáldozaton kivül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Azután megölé az ökröt és a kost hálaadó áldozatul a népért, és Áron fiai odavivék ő hozzá a vért, és elhinté azt az oltáron köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Az ökörből és a kosból való kövérségeket pedig, a farkat, a béltakarót, a veséket és a máj hártyáját;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'Odahelyezték e kövérségeket a szegyekre, és elfüstölögteté e kövérségeket az oltáron.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'De a szegyeket és a jobb lapoczkát meglóbálá Áron az Úr előtt, a mint parancsolta vala Mózes.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Azután felemelé kezeit Áron a népre, és megáldá azt és leszálla, miután elvégezte vala a bűnért való áldozatot, az egészen égőáldozatot és a hálaáldozatot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'És beméne Mózes és Áron a gyülekezetnek sátorába, azután kijövének és megáldák a népet, az Úrnak dicsősége pedig megjelenék az egész népnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'Tűz jöve ugyanis ki az Úr elől, és megemészté az oltáron az égőáldozatot és a kövérségeket. És látá ezt az egész nép, és ujjongának és arczra esének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Nádáb pedig és Abihu, Áronnak fiai, vevék egyen-egyen az ő temjénezőjöket, és tőnek azokba szenet és rakának arra füstölő szert, és vivének az Úr elé idegen tüzet, a melyet nem parancsolt vala nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Tűz jöve azért ki az Úr elől, és megemészté őket, és meghalának az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'És monda Mózes Áronnak: Ez az, a mit szólt vala az Úr, mondván: A kik hozzám közel vannak, azokban kell megszenteltetnem, és az egész nép előtt megdicsőíttetnem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Áron pedig mélyen hallgata. Szólítá azért Mózes Misáelt és Elsafánt, Uzzielnek, az Áron nagybátyjának fiait, és monda nékik: Jertek ide, vigyétek ki atyátokfiait a szenthely elől, a táboron kivül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'És odamenének, és kivivék őket az ő köntöseikben a táboron kivül, a mint szólott vala Mózes.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Azután monda Mózes Áronnak és az ő fiainak, Eleázárnak és Ithamárnak: Fejeteket meg ne meztelenítsétek, ruháitokat meg ne szaggassátok, hogy meg ne haljatok és haragra ne gerjedjen az Úr az egész gyülekezet ellen; a ti atyátokfiai pedig, Izráelnek egész háza sirassák az égést, a melyet égetett az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'A gyülekezet sátorának nyílásán se menjetek ki, hogy meg ne haljatok; mert az Úr kenetének olaja van rajtatok. És cselekvének a Mózes beszéde szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Áronnak pedig szóla az Úr, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Bort és szeszes italt ne igyatok te és a te fiaid veled, mikor bementek a gyülekezet sátorába, hogy meg ne haljatok. Örökkévaló rendtartás legyen ez a ti nemzetségeitekben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'Hogy különbséget tehessetek a szent és közönséges között, a tiszta és tisztátalan között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'És hogy taníthassátok Izráel fiait mindazokra a rendelésekre, a melyeket az Úr szólott vala nékik Mózes által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Mózes pedig szóla Áronnak és az ő megmaradt fiainak, Eleázárnak és Ithamárnak: Vegyétek az ételáldozatot, a mely megmaradt az Úrnak tűzáldozatiból, és egyétek meg azt kovásztalan kenyerekkel az oltár mellett; mert igen szentséges az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Azért egyétek azt szent helyen, mert kiszabott részed, és fiaidnak is kiszabott része az, az Úrnak tűzáldozatiból; mert így parancsolta nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'A meglóbált szegyet pedig, és a felmutatott lapoczkát egyétek meg tiszta helyen, te, és a te fiaid és leányaid is veled, mert kiszabott részül adattak azok néked s kiszabott részül a te fiaidnak is, Izráel fiainak hálaadó áldozataiból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'A felmutatott lapoczkát és meglóbált szegyet a tűzáldozat kövérségeivel együtt vigyék be, hogy meglóbálják az Úr előtt, és ez lesz a te kiszabott részed, és veled a te fiaidé örökké, a mint megparancsolta vala az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Azután szorgalmatosan tudakozódék Mózes a bűnáldozatra való bak felől, de ímé elégett vala. Haragra gerjede azért Eleázár és Ithamár ellen, Áronnak megmaradt fiai ellen, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, 'Miért nem ettétek meg a bűnért való áldozatot a szenthelyen? Hiszen igen szentséges az, és néktek adta azt az Úr a gyülekezet vétkének hordozásáért, hogy engesztelést szerezzetek annak az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Ímé, nem vitetett be annak vére a szenthely belsejébe, meg kellett volna azért ennetek a szenthelyen, a mint megparancsoltam vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Áron pedig szóla Mózesnek: Ímé ma áldozták meg az ő bűnért való áldozatukat és egészen égőáldozatukat az Úr előtt, engem pedig ilyen keserűségek értek: Ha megettem volna ma a bűnért való áldozatot, vajjon jó lett volna-é az Úr előtt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Mikor ezt hallotta vala Mózes, jónak tetszék ez néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Szóla ismét az Úr Mózesnek és Áronnak, mondván nékik:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Szóljatok Izráel fiainak, mondván: Ezek azok az állatok, a melyeket megehettek minden barmok közül, a melyek vannak e földön:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Mindazt, a minek hasadt a körme, és egészen ketté hasadt körme van, és kérődző a barmok közt, megehetitek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'De a kérődzők és a hasadt körműek közül ne egyétek meg ezeket: A tevét, mert az kérődző ugyan, de nincs hasadt körme; tisztátalan ez néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'A hörcsököt, mert kérődző ugyan, de nem hasadt a körme; tisztátalan ez néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'A nyulat, mert kérődző ugyan, de nem hasadt a körme; tisztátalan ez néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'És a disznót, mert hasadt körmű ugyan és egészen ketté hasadt körme van, de nem kérődzik; tisztátalan ez néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Ezeknek húsából ne egyetek, és holttestöket se illessétek; tisztátalanok ezek néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Mindazokból, a melyek a vizekben élnek, ezeket ehetitek meg: A minek úszószárnya és pikkelye van a vizekben, tengerekben és folyóvizekben, azokat mind egyétek meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'A minek pedig nincsen úszószárnya és pikkelye a tengerekben és folyóvizekben, legyen az akármely vízben nyüzsgő, és akármely vízben élő állat; mind útálatos az néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'De legyenek is útálatosak néktek; azoknak húsából ne egyetek, és holttestöket is útáljátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'A minek nincs úszószárnya és pikkelye a vizekben, mind útálatos az néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'A szárnyas állatok közül pedig ezeket útáljátok; meg ne egyétek, útálatosak ezek: a sas, a saskeselyű és a halászó sas.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'A sólyom és a héja az ő nemével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'Minden holló az ő nemével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'A strucz, a bagoly, a kakuk és a karvaly az ő nemével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'A kuvik, a hattyú és a füles bagoly.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'A bölömbika, a pelikán és a gém.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'Az eszterág és a szarka az ő nemével, a büdös banka és a denevér.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Minden szárnyas féreg, a mely négy lábon jár, útálatos néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Csak azt ehetitek meg a négylábú szárnyas férgek közül, a melynek lábain felűl szökő-szárai vannak, hogy szökdécselhessen azokkal a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Ezeket egyétek meg azok közül: az arbé-sáskát az ő nemével, a szolám-sáskát az ő nemével, a khargol-sáskát az ő nemével és a khagab-sáskát az ő nemével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Minden egyéb négylábú szárnyas féreg pedig útálatos legyen néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'És ezekkel tisztátalanokká teszitek magatokat; mindaz, a ki illeti holttestüket, tisztátalan legyen estvéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'Mindaz pedig, a ki hordozza azoknak holttestét, mossa meg az ő ruháit, és tisztátalan legyen estvéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Minden barom, a melynek hasadt a körme, de nincs egészen ketté hasadva, és nem kérődzik, tisztátalan legyen néktek; valaki illeti azt, tisztátalan legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Minden állat, a mely a négylábúak között a talpán jár, tisztátalan legyen néktek; mindaz, a ki azoknak holttestét illeti, tisztátalan legyen estvéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'A ki pedig hordozza azoknak holttestét, mossa meg az ő ruháit, és tisztátalan legyen estvéig. Tisztátalanok azok néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'A földön csúszó-mászó állatok között pedig ezek legyenek tisztátalanok: a menyét, az egér és a gyík az ő nemével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'A sündisznó, a kaméleon, a tarka gyík, a csiga és a vakondok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Ezek tisztátalanok néktek minden csúszó-mászó között; valaki illeti ezeket holtuk után, tisztátalan legyen estvéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'És minden, a mire ezek közül holtuk után esik valamelyik, tisztátalan legyen; akármely faedény, akár ruha, vagy bőr, vagy zsák; akármely eszköz, a mivel dolgozni szoktak, vízbe tétessék, és tisztátalan legyen estvéig, ezután tiszta legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Akármely cserépedény pedig, a melybe beleesik valami azokból, mindazzal együtt, a mi benne van, tisztátalan legyen, és az edényt törjétek el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Minden megehető eledel, a melyhez az ilyen edényből víz jut, tisztátalan, és minden megiható ital is minden ilyen edényben tisztátalan legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'És minden, a mire azoknak holttestéből esik valami, tisztátalan; kemencze és tűzhely lerontassék; tisztátalanok azok és tisztátalanok legyenek néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'De a forrás, a kút, az egybegyűlt víz tiszta legyen; de a mi azoknak holttestéhez ér, tisztátalan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Hogyha azoknak holttestéből reáesik is valamely vetőmagra, a mely elvetendő, tiszta legyen az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'De ha vizet töltenek a magra, és úgy esik rá azoknak holttestéből, tisztátalan az ilyen néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Hogyha olyan hullik el a barmok közül, a mely eledeletek néktek; a ki annak holttestét illeti, tisztátalan legyen estvéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'A ki pedig eszik annak holttestéből, mossa meg az ő ruháit, és tisztátalan legyen estvéig. És mossa meg ruháit az is, a ki hordozta annak holttestét, és tisztátalan legyen estvéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Mindaz is, a mi csúszik-mászik a földön, útálatos legyen, meg ne egyétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Mindazt, a mi hason csúszik, és mindazt, a mi négy, sőt mindazt, a mi több lábon jár, a földön csúszó-mászó bármely állatot, meg ne egyétek ezeket, mert útálatosak ezek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Meg ne fertéztessétek magatokat semmiféle csúszó-mászó állattal, és meg ne tisztátalanítsátok magatokat azokkal, hogy tisztátalanokká legyetek általok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Mert én, az Úr, vagyok a ti Istenetek; szenteljétek meg azért magatokat, és szentek legyetek, mert én szent vagyok, és meg ne tisztátalanítsátok magatokat semmiféle állat által, a mely csúszik-mászik a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Mert én vagyok az Úr, a ki felhoztalak titeket Égyiptom földéből, hogy Istenetekké legyek néktek; legyetek azért szentek, mert én szent vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Ez a törvény a baromfélékről, a szárnyas állatokról, minden élő állatról, a mely nyüzsög a vizekben, és minden állatról, a mely csúszik-mászik a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'Hogy különbséget tehessetek a tisztátalan és tiszta között, az olyan állat között, a mely megehető, és az olyan állat között, a mely meg nem ehető.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Szóla ismét az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Szólj Izráel fiainak, mondván: Ha az asszony lebetegszik, és fiat szül, tisztátalan legyen hét napig; az ő havi betegségének ideje szerint legyen tisztátalan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'A nyolczadik napon pedig metéljék körül a fiú férfitestének bőrét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Azután harminczhárom napig maradjon otthon a vértől való tisztulás miatt; semmi szent dolgot ne illessen, a szent helyre se menjen be, míg el nem telnek az ő tisztulásának napjai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Ha pedig leányt szül, két hétig legyen tisztátalan, mint havi betegségekor, és hatvanhat napig maradjon otthon a vértől való tisztulása végett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Mikor pedig letelnek az ő tisztulásának napjai, fiú miatt vagy leány miatt, hozzon egészen égőáldozatul esztendős bárányt, galambfiat vagy gerliczét bűnért való áldozatul, a gyülekezet sátorának nyílása elé a paphoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'És áldozza meg azt az Úr előtt; és szerezzen néki engesztelést; így lesz tisztává az ő vérfolyása után. Ez a törvénye a fiút vagy leányt szülő asszonynak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Ha pedig nincs elég módja bárányhoz, vigyen két gerliczét vagy két galambfiat, egyiket egészen égőáldozatul, a másikat bűnért való áldozatul, és szerezzen néki engesztelést a pap, és tiszta lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Szóla ismét az Úr Mózesnek és Áronnak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'Ha valamely ember testének bőrén daganat, vagy tarjagosság, vagy fehér folt támad, és az ő testének bőrén poklos fakadékká lehet: vigyék el az ilyet Áronhoz, a paphoz, vagy egyvalamelyikhez az ő papfiai közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'És nézze meg a pap azt a test bőrén lévő fakadékot. Ha a szőr a fakadékban fehérré változott, és ha a fakadéknak felülete mélyebben van az ő testének bőrénél: akkor poklos fakadék az. Mihelyt látja ezt a pap, tisztátalannak ítélje azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Ha pedig fehér folt van a teste bőrén, de annak felülete nincs mélyebben a bőrnél, és a szőre sem változott meg fehérré, akkor rekeszsze külön a pap a fakadékos embert hét napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'A hetedik napon pedig nézze meg őt a pap, s ha szerinte a fakadék egy állapotban van, át nem terjedt tovább a fakadék a bőrön, a pap másodszor is rekeszsze őt külön hét napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Nézze meg őt azután a pap a hetedik napon másodszor is, és ha a fakadék meghalványodott, és nem terjedt tovább a bőrön a fakadék, tisztának ítélje őt a pap; tarjagosság az, mossa meg azért a ruháit és legyen tiszta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'De ha a tarjagosság tovább terjedt a bőrön, miután a papnál az ő megtisztulása végett jelentkezett: akkor másodszor is jelentse magát a papnál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'És ha látja a pap, hogy ímé tovább terjedt a tarjagosság a bőrön: ítélje azt a pap tisztátalannak, poklosság az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Ha poklos fakadék lesz az emberen, vigyék tehát azt a paphoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'És ha látja a pap, hogy ímé fehér daganat van a bőrön, és az a szőrt fehérré változtatta, és vadhús van a daganatban:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'Idűlt poklosság az az ő testének bőrén; azért tisztátalannak ítélje azt a pap, ne is rekesztesse külön azt, mert tisztátalan az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Ha pedig folyton fejlődik a poklosság a bőrön, és a poklos fakadék elborítja a fakadékosnak egész bőrét tetőtől talpig mindenfelé, a merre a pap szemei látnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'És ha látja a pap, hogy ímé elborította a poklosság annak egész testét: akkor ítélje tisztának a fakadékot; mivelhogy egészen fehérré változott az, tiszta az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'De mihelyt vadhús mutatkozik abban, tisztátalan legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'Ha meglátja a pap a vadhúst, tisztátalannak ítélje azt; a vadhús tisztátalan legyen, poklosság az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'De ha a vadhús eltűnik, és fehérré változik, akkor menjen a paphoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'És ha megnézi azt a pap, és a fakadék csakugyan fehérré változott, akkor ítélje a pap a fakadékot tisztának, tiszta az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Ha pedig valakinek a teste bőrén kelevény volt, de begyógyult,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'És a kelevény helyén fehér daganat, vagy vörhenyes fehér folt támad, jelentse magát a papnál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'És ha látja a pap, hogy íme annak felülete alább esik a bőrnél, és a szőre fehérré változott: akkor ítélje azt a pap tisztátalannak; poklos fakadék az, a mi a kelevényben fakadt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Ha pedig megnézi azt a pap, és íme nincs abban fehér szőr, és nem is esett alább a bőrnél, sőt meghalványodott az: akkor rekeszsze külön azt a pap hét napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Ha azonban tovább terjed a bőrön; akkor tisztátalannak ítélje azt a pap, poklos fakadék az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'De ha elébbi állapotában marad a folt, nem terjedt: a kelevény forradása az, azért tisztának ítélje azt a pap.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Vagy ha valaki testének bőrén égési seb lesz, és a seb helyén vörhenyesfehér folt támad vagy fehér;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'És megnézi azt a pap, és íme a szőr fehérré változott a foltban, és annak felülete mélyebben van a bőrnél: poklosság az, a mi a seben fakadt, azért ítélje azt a pap tisztátalannak, poklos fakadék az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'De ha megnézi azt a pap, és ímé nincs a foltban fehér szőr, és nem is esett az alább a bőrnél, sőt meg is halványodott az: akkor rekeszsze azt külön a pap hét napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'És nézze meg azt a pap a hetedik napon; ha tovább terjedt a bőrön, akkor tisztátalannak ítélje azt a pap, poklos fakadék az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Ha pedig elébbi állapotában van a folt, nem terjedt a bőrön, sőt meg is halványodott, égési daganat az; azért tisztának ítélje azt a pap, mert égési seb forradása az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'És ha valamely férfiúnak vagy asszonynak fakadéka támad a fején vagy a szakállában,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'És a pap megnézi a fakadékot, és íme annak felülete mélyebben van a bőrnél; és abban a szőr sárga és vékony: akkor ítélje azt a pap tisztátalannak, var az, fejnek vagy szakállnak poklossága az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Ha pedig megnézi a pap a varas fakadékot, és ímé annak felülete nincsen mélyebben a bőrnél, és nincsen abban fekete szőr: akkor rekeszsze külön a pap azt, a kinek varas fakadéka van, hét napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'És nézze meg a pap a fakadékot a hetedik napon, és ha nem terjedt a var, és nem lett benne sárga szőr, és a varnak felülete nem lett mélyebbé a bőrnél:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'Akkor borotválkozzék meg, de a varat le ne borotválja; a pap pedig másodszor is rekeszsze külön a varas embert hét napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'És a pap nézze meg a varat a hetedik napon, és ha nem terjed a var a bőrön, és annak felülete nincsen mélyebben a bőrnél: akkor tisztának ítélje azt a pap és mossa meg a ruháit, és tiszta lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'De ha tovább terjed a var a bőrön, miután tisztának ítélte azt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'És megnézi azt a pap, és csakugyan terjedt a var a bőrön: akkor ne is kutasson a pap a sárga szőr után, tisztátalan az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'De ha a var szerinte egy állapotban van, és fekete szőr indult abban, meggyógyult az a var, tiszta az; tisztának ítélje azt a pap.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Ha pedig valamely férfi vagy asszony testének bőrén foltok, fehér foltok támadnak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'És megnézi a pap, és ímé a testök bőrén lévő foltok halavány fehérek: a bőrön fakadt sömör az, tiszta az az ember.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Hogyha valamely embernek egészen elhull a haja, kopasz az, és tiszta az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'És ha előlről hull el a haja, elől kopasz az, és tiszta az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Hogyha pedig az ő egész kopasz, vagy elől kopasz fején vörhenyes fehér fakadék támad, poklos fakadék az az ő egész kopasz vagy elől kopasz fején.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Ha megnézi azt a pap, és ímé a fakadék daganata vörhenyes fehér az ő egész kopasz vagy elől kopasz fején, olyanforma, mint a test bőrén való poklosság:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'Poklos ember az, tisztátalan az, igen tisztátalannak ítélje azt a pap, mivelhogy fején van a fakadékja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'A poklos ember pedig, a kin a fakadék van, megszaggatott ruhában és mezítelen fővel legyen, és a bajuszát fedezze be, és ezt kiáltsa: Tisztátalan, tisztátalan!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Mindaddig tisztátalan legyen, a míg rajta van a fakadék, tisztátalan az; csak ő maga lakjék, a táboron kivül legyen az ő lakása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Hogyha pedig valami ruhán van a poklos fakadék, gyapjú ruhán vagy len ruhán,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'Vagy lenből és gyapjúból készült fonadékon vagy szöveten; vagy bőrön, vagy valamely bőrből való készítményen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'És ha az a fakadék zöld vagy vörhenyes színű a ruhán, vagy bőrön, vagy szöveten, vagy fonadékon, vagy akármely bőrből való eszközön: poklos fakadék az, mutassák azért meg a papnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'És nézze meg a pap a fakadékot és rekeszsze külön azt a min a fakadék van, hét napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'A hetedik napon pedig nézze meg a fakadékot. Ha terjed a fakadék a ruhán vagy szöveten, vagy fonadékon vagy bőrön, és akármely készítményen, a mivé a bőr feldolgoztatik: emésztő poklosság az a fakadék, tisztátalan az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Azért égesse meg azt a ruhát, vagy a gyapjúból vagy a lenből készült szövetet vagy fonadékot, vagy akármely bőrből való eszközt, a melyen a fakadék leend; mert emésztő poklosság az, tűzön égessék meg azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'De ha megnézi a pap, és ímé nem terjedt a fakadék a ruhán, vagy szöveten, vagy fonadékon, vagy akármely bőrből való eszközön:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'Akkor parancsolja meg a pap, hogy mossák meg azt, a min a fakadék van, és rekeszsze külön azt másodszor is hét napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Ha pedig megnézi azt a pap a mosás után, és ímé a fakadék nem változtatta meg a színét; ha nem terjedt is a fakadék, tisztátalan az, tűzben égesd meg azt; beevődés az, akár a fonákján, akár a színén legyen az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'De ha látja a pap, hogy ímé meghalványodék a fakadék a megmosatása után: akkor szakaszsza el azt a ruhától vagy bőrtől, vagy a szövettől vagy a fonadéktól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'És ha mégis mutatkozik a ruhán vagy szöveten, vagy fonadékon, vagy akármely bőrből való eszközön: akkor kiújulás az; tűzzel égesd meg azt, a min a fakadék van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Azt a ruhát pedig, vagy szövetet, vagy fonadékot, vagy akármely bőrből való eszközt, a melyet megmostál, ha eltávozik rólok a fakadék, mosd meg másodszor is, és tiszta lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Ez a törvénye a poklos fakadéknak, akár gyapjú-, akár lenruhán, akár szöveten, akár fonadékon, vagy akármely bőrből való eszközön legyen, hogy tisztának vagy tisztátalannak ítéltessék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Szóla ismét az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'Ez legyen a poklos embernek törvénye az ő megtisztulásának napján, hogy vigyék a paphoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'A pap pedig menjen ki a táboron kivül, és nézze meg a pap, és ha meggyógyult a pokloson a poklos fakadék:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'Akkor parancsolja meg a pap, hogy hozzanak a megtisztulandó emberért két élő, tiszta madarat, czédrusfát, karmazsint és izsópot;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'Azután parancsolja meg a pap, hogy az egyik madarat öljék meg cserépedényben, forrásvíz felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Az élő madarat pedig, vegye azt és a czédrusfát, a karmazsint és az izsópot; és mártsa be azokat és az élő madarat a megölt madárnak vérébe a forrásvíz felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'És hintse meg a poklosságból megtisztulandó embert hétszer, és ítélje azt tisztának; az élő madarat pedig bocsássa szabadon a mezőre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Azután a megtisztulandó ember mossa ki az ő ruháit, borotválja le minden szőrét, és mosódjék meg vízben, és tiszta lesz; így menjen be azután a táborba, de a sátorán kivül maradjon hét napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'A hetedik napon pedig borotválja le minden szőrét: a haját, szakállát, szemöldökeit és minden egyéb szőrét borotválja le, és mossa ki ruháit, és mossa meg a testét vízben, és tiszta lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'A nyolczadik napon pedig vegyen két ép bárányt, meg egy ép nőstény bárányt, egy esztendőst, és olajjal elegyített három tized efa lisztlángot ételáldozatul, és egy lóg olajt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'A pap pedig, a ki a tisztítást végzi, állassa a megtisztulandó embert mindezekkel együtt az Úr elébe, a gyülekezet sátorának nyílásához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'És vegye a pap az egyik bárányt, és áldozza meg azt vétekért való áldozatul a lóg olajjal együtt, és lóbálja meg azokat az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'A bárányt pedig ott ölje meg, a hol a bűnért való áldozatot és az egészen égőáldozatot ölik meg a szent helyen; mert a miképen a bűnért, azonképen a vétekért való áldozat is a papé; igen szentséges az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'És vegyen a pap a vétekért való áldozatnak véréből, és kenje meg azzal a megtisztulandó ember jobb fülének czimpáját, és az ő jobb kezének hüvelykét, és jobb lábának hüvelykét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Vegyen a pap a lóg olajból is, és töltsön a papnak a bal tenyerére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'És mártsa be a pap az ő jobb kezének újját az olajba, mely az ő bal tenyerén van, és hintsen az olajból az újjával hétszer az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'A maradék olajból pedig, a mely az ő tenyerén van, kenje meg a pap a megtisztulandó ember jobb fülének czimpáját, a jobb kezének hüvelykét és a jobb lábának hüvelykét a vétekért való áldozat vérén felül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'És a mi megmarad az olajból, a mely a pap tenyerén van, kenje a megtisztulandó ember fejére; így szerezzen néki engesztelést a pap az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Azután készítsen a pap bűnért való áldozatot, és szerezzen engesztelést a tisztátalanságából megtisztulónak; azután ölje meg az égőáldozatot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'És vigye fel a pap az égőáldozatot és az ételáldozatot az oltárra; így szerezzen néki engesztelést a pap, és tiszta lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Hogyha pedig szegény ő, és nincs módja azokhoz, akkor vegyen egy bárányt vétekért való áldozatul meglóbálás végett, hogy engesztelésül legyen érte; meg egy tized efa lisztlángot, olajjal elegyítve, ételáldozatul, és egy lóg olajt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'És két gerliczét vagy két galambfiat, a mint a módja engedi, és legyen az egyik bűnért való áldozat, a másik pedig egészen égőáldozat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'És vigye azokat az ő tisztulásának nyolczadik napján a paphoz, a gyülekezet sátorának nyílásához, az Úr elébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'És vegye a pap a vétekért való áldozat bárányát, és a lóg olajt, és lóbálja meg azokat a pap az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Azután ölje meg a vétekért való áldozat bárányát, és vegyen a pap a vétekért való áldozat véréből, és kenjen a megtisztulandó ember jobb fülének czimpájára, és jobb kezének hüvelykére, és jobb lábának hüvelykére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Az olajból pedig töltsön a pap a papnak baltenyerére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'És hintsen a pap az ő jobb kezének újjával az olajból, a mely az ő bal tenyerén van, hétszer az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Azután kenje meg a pap a tenyerén levő olajból a megtisztulandó jobb fülének czimpáját, a jobb kezének hüvelykét és a jobb lábának hüvelykét a vétekért való áldozat vérének helyén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'A mi pedig megmarad a pap tenyerén levő olajból, kenje a megtisztulandó fejére, hogy engesztelésül legyen érette az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'És készítse el az egyiket a gerliczék közül, vagy galambfiak közül, a melyik az ő módjától telik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'Azt, a mi kitelik az ő módjától: az egyiket bűnért való áldozatul, a másikat pedig egészen égőáldozatul az ételáldozattal egybe; így szerezzen engesztelést a pap a megtisztulandó embernek az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Ez a törvénye annak, a kin poklos fakadék van, de a kinek nincs módja az ő megtisztulásánál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Szóla ismét az Úr Mózesnek és Áronnak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'Mikor bementek majd a Kanaán földére, a melyet én adok néktek birtokul, és a ti birtokotokban levő föld valamelyik házára poklosságot bocsátok:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'Akkor menjen el az, a kié a ház, és jelentse meg a papnak, mondván: Mint a poklosság, olyan mutatkozik nálam a házban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'A pap pedig parancsolja meg, hogy takarítsák ki a házat, mielőtt oda menne a pap a poklosság megnézésére, hogy semmi se legyen tisztátalanná, a mi a házban van; és csak azután menjen be a pap a ház megnézésére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'És ha látja a poklosságot, hogy ímé a poklosság a háznak falain zöld vagy vörhenyes horpadásokban mutatkozik, és annak felülete alább esik a falnál:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'Akkor menjen ki a pap a házból, a háznak ajtaja elé, és zárja be a házat hét napra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'A hetedik napon pedig térjen vissza a pap, és ha látja, hogy ímé elterjedt a poklosság a ház falán:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'Akkor parancsolja meg a pap, hogy szedjék ki a köveket, a melyeken a poklosság van, és vessék azokat a városon kivül tisztátalan helyre;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'A házat pedig vakartassa le belül köröskörül, és a tapasztékot, a melyet levakartak, töltsék a városon kivül tisztátalan helyre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'És vegyenek elő más köveket, és illeszszék be ama kövek helyére; tapasztékot is mást vegyenek, és tapasszák be a házat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Hogyha a poklosság visszatér, és kiújul a házon, miután kiszedték a köveket, és miután levakarták a házat, és miután be is tapasztották azt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'Akkor menjen be a pap, és nézze meg, és ha ímé tovább terjedt a poklosság a házon: emésztő poklosság az a házon, tisztátalan az;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Rontsák azért le a házat köveivel együtt, és a fáit is, a háznak minden tapasztékát is; és vigyék a városon kívül tisztátalan helyre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'A ki pedig bemegy a házba akármikor, a míg az zárva van, tisztátalan legyen az estvéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'És a ki meghál abban a házban, mossa meg a ruháit, és a ki eszik abban a házban, az is mossa meg a ruháit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Ha pedig bemegy a pap és látja, hogy ímé nem terjedt a poklosság a házon, miután megtapasztották a házat: akkor tisztának ítélje a pap a házat, mert megszűnt a poklosság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'A háznak megtisztítása végett pedig vegyen elő két madarat, czédrusfát, karmazsint és izsópot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'És ölje meg az egyik madarat cserépedényben, forrásvíz felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'Azután vegye a czédrusfát, az izsópot, a karmazsint és az élő madarat, és mártsa be azokat a megölt madár vérébe és a forrásvízbe, és hintse meg azzal a házat hétszer.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'És tisztítsa meg a házat a madár vérével, a forrásvízzel, az élő madárral, a czédrusfával, az izsóppal és a karmazsinnal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'Az élő madarat pedig bocsássa el a városon kivül a mezőre, így szerezzen engesztelést a házért, és tiszta lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Ez a törvénye mindenféle poklos fakadéknak és varnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'A ruha és a ház poklosságának is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'A daganatnak, a tarjagosságnak és a fehér foltnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'Hogy megtudhassák: mikor tiszta és mikor tisztátalan valami? Ez a poklosság törvénye.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Szóla ismét az Úr Mózesnek s Áronnak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Szóljatok Izráel fiainak és mondjátok meg nékik: Ha valamely férfiúnak magfolyása támad, az ő folyása tisztátalan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'És pedig tisztátalan lesz e folyás miatt: akár folytonos az ő magfolyása, akár megreked testében ez a folyás; tisztátalanság ez ő nála.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Minden ágy, a melyen fekszik a magfolyós, tisztátalan, és minden holmi is, a melyre ráül, tisztátalan lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Valaki azért illeti az ő ágyát, mossa meg a ruháit, és mosódjék meg vízben, és tisztátalan legyen estvéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Az is, aki a holmira ül, a melyen a magfolyós ült vala, mossa meg ruháit, és mosódjék meg vízben, és tisztátalan legyen estvéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Az is, a ki illeti a magfolyósnak testét, mossa meg a ruháit, és mosódjék meg vízben, és tisztátalan legyen estvéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'És ha ráköp a magfolyós a tiszta emberre, mossa meg ez a ruháját, és mosódjék meg vízben, és tisztátalan legyen estvéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'És minden nyereg is, a melyre a magfolyós ráült, tisztátalan legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'És akárki is, a ki illet valamit, a mi annak alatta vala, tisztátalan legyen estvéig, és a ki hordozza azokat, mossa meg ruháit, és mosódjék meg vízben, és tisztátalan legyen estvéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'És mindaz, a kit illet a magfolyós, úgy hogy kezeit le nem öblíti vízzel, mossa meg ruháit, és mosódjék meg vízben, és tisztátalan legyen estvéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'A cserépedény pedig, a melyet a magfolyós illet, törettessék el, minden faedény pedig öblíttessék ki vízzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Mikor pedig megtisztul a magfolyós az ő folyásából, akkor számláljon hét napot az ő tisztulására, és mossa meg ruháit, és a testét is mossa le forrásvízben, és tiszta lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'És a nyolczadik napon vegyen elő két gerliczét vagy két galambfiat, és menjen el az Úr elé, a gyülekezet sátorának nyílásához, és adja azokat a papnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'És készítse el azokat a pap; az egyiket bűnért való áldozatul, a másikat egészen égőáldozatul; így szerezzen néki engesztelést a pap az Úr előtt az ő magfolyása miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'Ha valamely férfiúnak magömlése van, mossa meg az egész testét vízben, és tisztátalan legyen estvéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'És minden ruha, és minden bőr, a melyre a magömlés kihat, mosattassék meg vízben, és tisztátalan legyen estvéig,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'És az asszony is, a kivel férfiú hál magömléssel. Mosódjanak meg vízben, és tisztátalanok legyenek estvéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'Mikor asszony lesz magfolyóssá és véressé lesz az ő magfolyása a testén, hét napig legyen az ő havi bajában, és valaki illeti azt, tisztátalan legyen estvéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Mindaz is, a min hál az ő havi bajában, tisztátalan legyen és mindaz is, a min ül, tisztátalan legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'És mindaz, a ki illeti az ő ágyát, mossa meg ruháit, és mosódjék meg vízben, és tisztátalan legyen estvéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'És mindaz is, a ki illet bármely holmit, a melyen ült, mossa meg ruháit, és mosódjék meg vízben, és tisztátalan legyen estvéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Sőt ha valaki az ő ágyán, vagy a holmikon illet is valamit, a melyeken ő ült, tisztátalan legyen estvéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Ha pedig vele hál valaki, és reá ragad arra az ő havi baja: tisztátalan legyen hét napig, és minden ágy is, a melyen fekszik, tisztátalan legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'És hogyha sok napig tart az asszonynak az ő vérfolyása a havi bajának idején kivül, vagy ha a folyás a havi bajon túl tart: valameddig az ő tisztátalanságának folyása tart, úgy legyen, mint havi bajának idején, tisztátalan az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Minden ágy, a melyen fekszik az ő folyásának egész ideje alatt, olyan legyen, mint a havi baja idejében lévő ágya, és minden holmi is, a melyre ráül, tisztátalan legyen, mint az ő havi bajának tisztátalansága alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'És mindaz is, a ki illeti azokat, tisztátalan lesz, mossa meg azért a ruháit, és mosódjék meg vízben, és tisztátalan legyen estvéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Ha pedig megtisztul az ő folyásából: számláljon hét napot, és azután tiszta legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'A nyolczadik napon pedig vegyen elő két gerliczét vagy két galambfiat, és vigye el azokat a papnak, a gyülekezet sátorának nyílásához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'És készítse el a pap az egyiket bűnért való áldozatul, a másikat pedig egészen égőáldozatul; így szerezzen néki engesztelést a pap az Úr előtt az ő tisztátalanságának folyása miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Így tartsátok vissza Izráel fiait az ő tisztátalanságuktól, hogy meg ne haljanak az ő tisztátalanságuk miatt, megfertőztetvén az én hajlékomat, a mely közöttök van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Ez a törvénye a magfolyósnak, és annak, a kinek magömlése van, a mi által tisztátalanná lesz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'És a havi bajban szenvedőnek és a magfolyásban lévőnek, férfinak és asszonynak, és annak a férfiúnak a ki tisztátalan asszonynyal hál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'És szóla az Úr Mózesnek, az Áron két fiának halála után, a kik akkor haltak meg, a mikor az Úrhoz járultak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'És monda az Úr Mózesnek: Szólj a te atyádfiának, Áronnak, hogy ne menjen be akármikor a szenthelyre a függönyön belül a fedél elé, a mely a láda felett van, hogy meg ne haljon, mert felhőben jelenek meg a fedél felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Ezzel menjen be Áron a szenthelyre: egy fiatal tulokkal bűnért való áldozatul, és egy kossal égőáldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'Gyolcsból készült szent köntöst öltsön magára, és gyolcs lábravaló legyen a testén, gyolcs övvel övezze be magát, és gyolcs süveget tegyen fel; szent ruhák ezek; mossa meg azért a testét vízben, és úgy öltse fel ezeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Izráel fiainak gyülekezetétől pedig vegyen át két kecskebakot bűnért való áldozatul, és egy kost egészen égőáldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'És áldozza meg Áron a bűnért való áldozati tulkot, a mely az övé, és végezzen engesztelést magáért és háza népéért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Azután vegye elő a két kecskebakot, és állassa azokat az Úr elé a gyülekezet sátorának nyílásához,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'És vessen sorsot Áron a két bakra; egyik sorsot az Úrért, a másik sorsot Azázelért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'És áldozza meg Áron azt a bakot, a melyre az Úrért való sors esett, és készítse el azt bűnért való áldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Azt a bakot pedig, a melyre az Azázelért való sors esett, állassa elevenen az Úr elé, hogy engesztelés legyen általa, és hogy elküldje azt Azázelnek a pusztába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Áron pedig úgy áldozza meg a bűnért való áldozati tulkot, a mely az övé, és úgy szerezzen engesztelést magáért és háza népéért, hogy ölje meg a bűnért való áldozati tulkot, a mely az övé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'És vegye tele a tömjénezőt eleven szénnel az oltárról, a mely az Úr előtt van, és vegye tele a két markát a porrá tört fűszerekből való füstölőből, és vigye be a függönyön belől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'És vesse a füstölőt a tűzre az Úr előtt, hogy befedje a füstölő felhője a fedelet, a mely a bizonyság felett van, hogy meg ne haljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Azután vegyen a tuloknak véréből és hintsen újjával a fedél felső színére napkelet felé; a fedél előtt pedig hétszer hintsen újjával a vérből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'És ölje meg a bűnért való áldozati bakot, a mely a népé, és vigye be annak vérét a függönyön belől, és úgy cselekedjék annak vérével, a mint a tuloknak vérével cselekedett: hintse ugyanis azt a fedélre és a fedél elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'Így szerezzen engesztelést a szenthelynek Izráel fiainak tisztátalanságai és vétkei miatt; mindenféle bűnei miatt; így cselekedjék a gyülekezet sátorával is, a mely közöttök van, az ő tisztátalanságaik közepette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Senki se legyen a gyülekezet sátorában, a mikor bemegy a szenthelybe, hogy engesztelést szerezzen, egészen az ő kijöveteléig; és végezzen engesztelést magáért, házanépéért, és Izráelnek egész gyülekezetéért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Azután menjen ki az oltárhoz, a mely az Úr előtt van, és végezzen engesztelést azért is; vegyen ugyanis a tuloknak véréből és a baknak véréből, és kenje meg az oltárnak szarvait köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'És hintsen arra a vérből az ő újjával hétszer; így tegye tisztává, és így szentelje meg azt Izráel fiainak tisztátalanságaitól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Miután pedig elvégezi a szenthelyért, a gyülekezet sátoráért és az oltárért való engesztelést; hozza elő az élő bakot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'És tegye Áron mind a két kezét az élő baknak fejére, és vallja meg felette Izráel fiainak minden hamisságát és minden vétkét, mindenféle bűneit: és rakja azokat a baknak fejére, azután küldje el az arravaló emberrel a pusztába,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'Hogy vigye el magán a bak minden ő hamisságukat kietlen földre, és hogy bocsássa el a bakot a pusztában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Azután menjen be Áron a gyülekezet sátorába, és vesse le a gyolcs ruhákat, a melyeket felöltött, mikor bement a szenthelybe, és hagyja ott azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'És mossa meg a testét vízben szent helyen, és öltse fel a maga ruháit, úgy menjen ki, és készítse el a maga egészen égőáldozatát és a nép egészen égőáldozatát, és végezzen engesztelést magáért és a népért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'A bűnért való áldozat kövérjét pedig füstölögtesse el az oltáron.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Az pedig, a ki elvitte az Azázelnek való bakot, mossa meg ruháit, és a testét is mossa le vízben, és azután menjen be a táborba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'A bűnért való áldozati tulkot pedig, és a bűnért való áldozati bakot, a melyeknek vére engesztelés végett bevitetett a szenthelyre, vigye ki a táboron kivül, és égessék meg azoknak bőrét, húsát és ganéját tűzzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'És a ki elégeti ezeket, mossa meg ruháit, és a testét is mossa le vízben, és azután így menjen be a táborba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'Örökkévaló rendtartás legyen ez nálatok: a hetedik hónapban, a hónapnak tizedikén sanyargassátok meg magatokat és semmi munkát ne végezzetek, se a benszülött, se a közöttetek tartózkodó jövevény.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Mert ezen a napon engesztelés lesz értetek, hogy megtisztítson titeket; minden bűnötöktől megtisztultok az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Szombatok szombatja ez néktek, sanyargassátok meg azért magatokat; örökkévaló rendtartás ez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'És végezzen engesztelést a pap, a kit felkennek, és a kit az ő tisztére felavatnak, hogy paposkodjék az ő atyja helyett, és öltözködjék a gyolcs ruhákba, a szent ruhákba:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'És végezzen engesztelést a szentek szentjéért, és a gyülekezet sátoráért, és az oltárért is végezzen engesztelést, sőt a papokért és az egész összegyülekezett népért is engesztelést végezzen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'És örökkévaló rendtartás legyen ez nálatok, hogy egyszer egy esztendőben engesztelést végezzenek Izráel fiainak minden bűnéért. És úgy cselekedék, a mint megparancsolta vala az Úr Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Szóla ismét az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Szólj Áronnak és az ő fiainak és Izráel minden fiának, és mondd nékik: Ez az a dolog, a mit megparancsolt az Úr, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Ha valaki Izráel házából ökröt, vagy bárányt, vagy kecskét öl le a táborban, vagy a ki öl a táboron kivül,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'És nem viszi azt a gyülekezet sátorának nyílásához, hogy áldozattal járuljon az Úrhoz, az Úrnak hajléka előtt: vérontásul tulajdoníttassék az annak az embernek; vért ontott, töröltessék ki azért az ilyen ember az ő népe közűl:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'Azért hogy vigyék el Izráel fiai az ő véres áldozataikat, a melyeket áldoznak vala a mezőn, vigyék el azokat az Úrnak, a gyülekezet sátorának nyílásához, a paphoz, és áldozzák meg azokat hálaáldozatul az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'És hintse a pap a vért az Úr oltárára, a mely a gyülekezet sátorának nyílásánál van, a kövérjét pedig füstölögtesse el kedves illatul az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'És ne áldozzák többé véres áldozataikat az ördögöknek, a kikkel ők paráználkodnak. Örökkévaló rendtartás legyen ez nékik nemzetségről nemzetségre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Mondjad nékik ezt is: Valaki az Izráel házából, vagy a köztök tartózkodó jövevények közül, egészen égőáldozatot áldoz vagy véres áldozatot,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'És nem viszi azt a gyülekezet sátorának nyílásához, hogy elkészítse azt az Úrnak: irtassék ki az ilyen ember az ő népe közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'És ha valaki Izráel házából, vagy a köztök tartózkodó jövevények közül valamiféle vért megeszik: kiontom haragomat az ellen, a ki a vért megette, és kiirtom azt az ő népei közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'Mert a testnek élete a vérben van, én pedig az oltárra adtam azt néktek, hogy engesztelésül legyen a ti életetekért, mert a vér a benne levő élet által szerez engesztelést.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Azért mondtam Izráel fiainak: Egy lélek se egyék vért közületek; a köztetek tartózkodó jövevény se egye meg a vért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'És ha valaki Izráel fiai közül, vagy a köztök tartózkodó jövevények közül vadászásban vadat vagy madarat fog, a mely megehető: ontsa ki annak vérét, és fedje be azt földdel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Mert minden testnek élete az ő vére a benne levő élettel. Azért mondom Izráel fiainak: Semmiféle testnek a vérét meg ne egyétek, mert minden testnek élete az ő vére; valaki megeszi azt, irtassék ki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Ha pedig valaki elhullott, vagy vadtól megszaggatott állatot eszik, akár benszülött, akár jövevény: mossa meg ruháit, és mosódjék meg vízben, és tisztátalan legyen estvéig, azután tiszta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Hogyha meg nem mossa ruháit, sem a testét le nem mossa: viselje az ő vétségének terhét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Szóla ismét az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Szólj Izráel fiaihoz, és mondd nékik: Én vagyok az Úr, a ti Istenetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Ne cselekedjetek úgy, a mint Égyiptom földén cselekesznek, a hol laktatok; úgy se cselekedjetek, a mint Kanaán földén cselekesznek, a hová beviszlek titeket; se azoknak rendtartásai szerint ne járjatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Az én végzéseim szerint cselekedjetek, és az én rendeleteimet tartsátok meg, azok szerint járván. Én vagyok az Úr, a ti Istenetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Tartsátok meg azért az én rendeleteimet és az én végzéseimet, a melyeket ha megcselekszik az ember, él azok által. Én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Senki se közelgessen valamely vér szerint való rokonához, hogy felfedje annak szemérmét. Én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'A te atyádnak szemérmét és a te anyádnak szemérmét fel ne fedd; a te anyád ő, fel ne fedd az ő szemérmét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'A te atyád feleségének szemérmét fel ne fedd, a te atyádnak szemérme az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'A te atyád leányának, vagy a te anyád leányának, a te leánytestvérednek szemérmét, akár otthon született, akár kivül született legyen; fel ne fedd szemérmöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'A te fiad leányának szemérmét, vagy a te leányod leányáét, ezeknek szemérmét fel ne fedd, mert a te szemérmeid azok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'A te atyád felesége leányának szemérmét, a ki a te atyádnak magzatja, leánytestvéred ő, fel ne fedd ennek szemérmét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'A te atyád leánytestvérének szemérmét fel ne fedd, a te atyádnak vér szerint való rokona ő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'A te anyád leánytestvérének szemérmét fel ne fedd, mert a te anyádnak vér szerint való rokona ő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'A te atyád fiútestvérének szemérmét fel ne fedd, annak feleségéhez ne közelgess, nagynénéd ő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'A te menyednek szemérmét fel ne fedd; a te fiadnak felesége ő: ne fedd fel az ő szemérmét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'A te fiútestvéred feleségének szemérmét fel ne fedd; a te fiútestvérednek szemérme az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Valamely asszonynak és az ő leányának szemérmét fel ne fedd; az ő fiának leányát, vagy leányának leányát el ne vedd, hogy annak szemérmét felfedjed; mert vér szerint való rokonok ők; fajtalankodás ez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'De feleségül se végy senkit az ő leánytestvére mellé, hogy ellenkezés ne legyen, ha felfeded ő mellette amannak szemérmét az ő életében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Asszonyhoz ne közelgess, az ő havi tisztátalansága alatt, hogy felfedjed az ő szemérmét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'És a te felebarátodnak feleségéhez se add magad közösülésre, hogy azzal magadat megfertőztessed.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'A te magzatodból ne adj, hogy oda áldozzák a Moloknak, és meg ne szentségtelenítsd a te Istenednek nevét. Én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Férfiúval ne hálj úgy, a mint asszonynyal hálnak: útálatosság az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'És semmiféle barommal se közösülj, hogy azzal magadat megfertőztessed, és asszony se álljon meg barom előtt, hogy meghágja őt; fertelmesség az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Egyikkel se fertőztessétek meg magatokat ezek közül; mert mindezekkel ama pogányok fertőztették meg magokat, kiket én kiűzök ti előletek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'És fertőzötté lett az a föld, de meglátogatom azon az ő gonoszságát, mert kiokádja az a föld az ő lakosait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Tartsátok meg azért ti az én rendeléseimet és végzéseimet, és ez útálatosságok közül semmit meg ne cselekedjetek, se a benszülött, se a közöttetek tartózkodó jövevény:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, '(Mert mindezeket az útálatosságokat megcselekedték annak a földnek lakosai, a mely előttetek van; és fertelmessé lőn az a föld),');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'Hogy ki ne okádjon titeket az a föld, ha megfertőztetitek azt, a mint kiokádja azt a népet, a mely előttetek van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Mert a ki megcselekszik valamit ez útálatosságokból, mind kiirtatik az így cselekvő ember az ő népe közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Tartsátok meg azért a mit én megtartani rendelek, hogy egyet se kövessetek amaz útálatos szokásokból, a melyeket követtek ti előttetek, és meg ne fertőztessétek magatokat azokkal. Én, az Úr, vagyok a ti Istenetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Szóla ismét az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Szólj Izráel fiainak egész gyülekezetéhez, és mondd nékik: Szentek legyetek, mert én az Úr, a ti Istenetek szent vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Az ő anyját és atyját minden ember tisztelje, és az én szombatjaimat megtartsátok. Én vagyok az Úr, a ti Istenetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Ne hajoljatok a bálványokhoz, és ne csináljatok magatoknak öntött isteneket. Én vagyok az Úr, a ti Istenetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Hogyha hálaadó áldozatot áldoztok az Úrnak, úgy áldozzátok, hogy kedvesen fogadtassatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'A ti áldozástok napján és a következőn egyétek meg; a mi pedig harmadnapra marad, égessétek meg tűzben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Ha pedig harmadnapra eszik valaki abból, útálatos az, nem lehet kedves.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'És a ki eszi azt, viselje az ő álnokságának terhét; mivelhogy megfertőztette az Úrnak szentségét, irtassék ki az ilyen ember az ő népe közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Mikor a ti földetek termését learatjátok, ne arasd le egészen a te meződnek szélét, és az elhullott gabonafejeket fel ne szedd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Szőlődet se mezgéreld le, és elhullott szemeit se szedd fel szőlődnek, a szegénynek és a jövevénynek hagyd meg azokat. Én vagyok az Úr, a ti Istenetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Ne orozzatok, se ne hazudjatok és senki meg ne csalja az ő felebarátját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'És ne esküdjetek hamisan az én nevemre, mert megfertőzteted a te Istenednek nevét. Én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'A te felebarátodat ne zsarold, se ki ne rabold. A napszámos bére ne maradjon nálad reggelig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Siketet ne szidalmazz, és vak elé gáncsot ne vess; hanem félj a te Istenedtől. Én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Ne kövessetek el igazságtalanságot az ítéletben; ne nézd a szegénynek személyét, se a hatalmas személyét ne becsüld; igazságosan ítélj a te felebarátodnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Ne járj rágalmazóként a te néped között; ne támadj fel a te felebarátodnak vére ellen. Én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Ne gyűlöld a te atyádfiát szívedben; fedd meg a te felebarátodat nyilván, hogy ne viseljed az ő bűnének terhét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Bosszúálló ne légy, és haragot ne tarts a te néped fiai ellen, hanem szeressed felebarátodat, mint magadat. Én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Az én rendeléseimet megtartsátok: Barmodat másféle állattal ne párosítsd, szántóföldedbe kétféle magot ne vess, és kétféle szövetű ruha ne legyen rajtad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'És ha valaki asszonynyal hál és közösül, és az valamely férfi hatalma alatt lévő rabnő, és sem ki nem váltatott, sem szabadon nem bocsáttatott: büntetés érje, de meg ne ölettessenek, mert nem volt szabad az asszony.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'A férfiú pedig vigye el az ő vétkéért való áldozatát az Úrnak a gyülekezet sátorának nyílásához: egy kost vétekért való áldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'És a pap szerezzen néki engesztelést, a vétekért való áldozat kosával az Úr előtt, az ő bűnéért, a melyet elkövetett, és megbocsáttatik néki az ő bűne, a melyet elkövetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Mikor pedig bementek arra a földre, és plántáltok ott mindenféle gyümölcstermő fát, annak gyümölcsét körülmetéletlennek tartsátok, három esztendeig legyen az néktek körülmetéletlen: meg ne egyétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'A negyedik esztendőben pedig annak minden gyümölcse szent legyen, hálaáldozatul az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'Csak az ötödik esztendőben egyétek meg annak gyümölcsét, és annak termését magatoknak gyüjtsétek. Én vagyok az Úr, a ti Istenetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Ne egyetek vérrel valót, ne varázsoljatok és ne bűvészkedjetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'A ti hajatokat kerekdedre ne nyírjátok, a szakállad végét se csúfítsd el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Testeteket a holt emberért meg ne hasogassátok, se égetéssel magatokat meg ne bélyegezzétek. Én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'A te leányodat meg ne becstelenítsd, paráznaságra adván azt; hogy paráznává ne legyen a föld, és be ne teljék a föld fajtalansággal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Az én szombatjaimat megtartsátok; szenthelyemet tiszteljétek. Én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Ne menjetek ígézőkhöz, és a jövendőmondókat ne tudakozzátok, hogy magatokat azokkal megfertőztessétek. Én vagyok az Úr, a ti Istenetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Az ősz ember előtt kelj fel, és a vén ember orczáját becsüld meg, és félj a te Istenedtől. Én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Hogyha jövevény tartózkodik nálad, a ti földeteken, ne nyomorgassátok őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'Olyan legyen néktek a jövevény, a ki nálatok tartózkodik, mintha közületek való benszülött volna, és szeressed azt mint magadat, mert jövevények voltatok Égyiptom földén. Én vagyok az Úr, a ti Istenetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Ne kövessetek el igazságtalanságot az ítéletben, a hosszmértékben, súlymértékben és ürmértékben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Igaz mérték, igaz font, igaz efa, és igaz hin legyen közöttetek. Én vagyok az Úr, a ti Istenetek, a ki kihoztalak titeket Égyiptom földéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Tartsátok meg azért minden rendelésemet és minden végzésemet, és cselekedjetek azok szerint. Én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Szóla ismét az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Izráel fiainak pedig mondd meg: Valaki Izráel fiai közül és az Izráelben tartózkodó jövevények közül odaadja az ő magzatát a Moloknak, halállal lakoljon, a földnek népe kövezze agyon kővel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Én is kiontom haragomat az ilyen emberre, és kiirtom azt az ő népe közül, mivelhogy adott az ő magzatából a Moloknak, hogy megfertőztesse az én szentségemet, és megszentségtelenítse az én szent nevemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Ha pedig a föld népe behúnyja szemeit az ilyen ember előtt, a mikor az oda adja az ő magzatát a Moloknak, és azt meg nem öli:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'Akkor én ontom ki haragomat arra az emberre és annak házanépére, és kiirtom azt és mindazokat, a kik ő utána paráználkodnak, hogy a Molokkal paráználkodjanak, az ő népök közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'A mely ember pedig az ígézőkhöz és a jövendőmondókhoz fordul, hogy azok után paráználkodjék, arra is kiontom haragomat, és kiirtom azt az ő népe közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Szenteljétek meg azért magatokat, és szentek legyetek, mert én, az Úr, vagyok a ti Istenetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'És tartsátok meg az én rendeléseimet, és cselekedjétek azokat. Én vagyok az Úr, a ti megszentelőtök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Mert valaki szidalmazza az ő atyját vagy anyját, halállal lakoljon; atyját és anyját szidalmazta; vére rajta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Ha valaki más ember feleségével paráználkodik, mivelhogy az ő felebarátjának feleségével paráználkodik: halállal lakoljon a parázna férfi és a parázna nő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Ha valaki az ő atyjának feleségével hál, az ő atyjának szemérmét fedi fel: halállal lakoljanak mindketten; vérök rajtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Ha valaki az ő menyével hál, halállal lakoljanak mindketten, fertelmességet követtek el; vérök rajtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'És ha valaki férfival hál, úgy a mint asszonynyal hálnak: útálatosságot követtek el mindketten, halállal lakoljanak; vérök rajtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'És ha valaki feleségül vesz valamely asszonyt annak anyjával egybe: fajtalankodás ez; tűzzel égessék meg azt és azokat, hogy ne legyen köztetek fajtalankodás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Ha pedig valaki barommal közösül, halállal lakoljon, és a barmot is öljétek meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Ha valamely asszony akármely baromhoz járul, hogy az meghágja őt: öld meg mind az asszonyt, mind a barmot, halállal lakoljanak; vérök rajtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'És ha valaki feleségül veszi az ő leánytestvérét, atyjának leányát, vagy anyjának leányát, és meglátja annak szemérmét, és az is meglátja az ő szemérmét: gyalázatosság ez; azért irtassanak ki népök fiainak láttára, az ő leánytestvérének szemérmét fedte fel: viselje gonoszságának terhét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'És ha valaki havi bajos asszonynyal hál, és felfedi annak szemérmét, és forrását feltakarja, és az asszony is felfedi az ő vérének forrását: mindketten irtassanak ki az ő népökből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'A te anyád leánytestvérének, vagy az atyád leánytestvérének szemérmét se fedd fel; mivelhogy az ő vérrokonát takarja ki: viseljék gonoszságuk terhét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'És ha valaki az ő nagynénjével hál, az ő nagybátyjának szemérmét fedte fel: viseljék gonoszságuk terhét, magtalanul haljanak meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Ha pedig elveszi valaki az ő fiútestvérének feleségét: vérfertőzés az; az ő fiútestvérének szemérmét fedte fel; magtalanok legyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Tartsátok meg minden rendelésemet és minden végzésemet, és azokat cselekedjétek, hogy ki ne okádjon titeket az a föld, a melybe én viszlek be titeket, hogy ott lakjatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'És ne járjatok annak a népnek rendtartási szerint, a melyet kiűzök én előletek. Mivelhogy mindezeket cselekedték, azért megútáltam őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Néktek pedig mondom: Ti örökölni fogjátok az ő földüket, mert én néktek adom azt örökségül, azt a tejjel és mézzel folyó földet. Én vagyok az Úr, a ti Istenetek, a ki kiválasztottalak titeket a népek közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'Tegyetek különbséget azért a tiszta és tisztátalan barmok között, a tiszta és tisztátalan szárnyas állatok között, és ne fertőztessétek meg magatokat barommal vagy szárnyas állattal, sem semmiféle földön csúszó állattal, a melyeket megkülönböztettem előttetek, mint tisztátalanokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'És legyetek nékem szentek, mert én, az Úr, szent vagyok, a ki kiválasztottalak titeket a népek közül, hogy enyéim legyetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'És akár férfi, akár asszony, hogyha ígéző vagy jövendőmondó lesz közöttök, halállal lakoljanak; kővel kövezzétek azokat agyon; vérök rajtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Szóla ismét az Úr Mózesnek: Szólj a papoknak, Áron fiainak, és mondd meg nékik: Senki közülök meg ne fertőztesse magát halottal az ő népe között;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'Hanem ha a hozzá legközelebb álló vérrokonával: anyjával, atyjával, fiával, leányával és fiútestvérével,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'Vagy a hozzá legközelebb álló hajadon leánytestvérével, a ki még nem ment férjhez: ezt megérintheti.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Mint fő-ember ne fertőztesse meg magát az ő népe között, hogy szentségtelenné ne legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Ne nyírjanak kopaszságot a fejükön, szakálluk szélét le ne messék, és a testükbe vágásokat ne vágjanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Szentek legyenek Istenöknek, és az ő Istenöknek nevét meg ne szentségtelenítsék, mert az Úrnak tűzáldozatait, Istenöknek kenyerét ők áldozzák; azért szentek legyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Parázna és megszeplősített asszonyt el ne vegyenek, se olyan asszonyt, a ki elűzetett az ő férjétől, el ne vegyenek; mert a pap az ő Istenének van szentelve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Te is szentnek tartsad őt, mert Istenednek kenyerét ő áldozza: szent legyen azért előtted, mert szent vagyok én, az Úr, a ti megszentelőtök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Hogyha valamely papnak leánya vetemedik paráznaságra, megszentségteleníti az ő atyját, azért tűzzel égettessék meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'A ki pedig főpap az ő attyafiai között, a kinek fejére töltötték a kenetnek olaját, és a kit felavattak az ő szolgálatára, hogy a szent ruhákba felöltözzék: fejét meg ne meztelenítse, se ruháit meg ne szaggassa,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'És semmiféle holttesthez be ne menjen: atyjával és anyjával se fertőztesse meg magát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'És a szenthelyből ki ne menjen, hogy az ő Istenének szenthelyét meg ne szentségtelenítse, mert korona, az ő Istenének kenet-olaja van ő rajta. Én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Hajadont vegyen feleségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Özvegyet, elűzöttet, megszeplősítettet, paráznát: ilyeneket el ne vegyen, hanem hajadont vegyen feleségül az ő népe közül,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'Hogy meg ne fertőztesse az ő magzatát az ő népe között; mert én, az Úr vagyok az ő megszentelője.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Szóla ismét az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Szólj Áronnak, mondván: Ha lesz valaki a te magod közül, az ő nemzetségökben, a kiben fogyatkozás leend, ne áldozza áldozatul az ő Istenének kenyerét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'Mert senki sem áldozhat, a kiben fogyatkozás van: vagy vak, vagy sánta vagy csonka orrú, vagy hosszú tagú.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'Sem az, a ki törött lábú vagy törött kezű,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'Vagy púpos, vagy törpe, vagy szemfájós, vagy viszketeges, vagy sömörgös, vagy a ki megszakadott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Senki, a kiben fogyatkozás van, elő ne álljon Áronnak, a papnak fiai közül, hogy tűzáldozatot vigyen fel az Úrnak; fogyatkozás van ő benne, ne álljon elő, hogy megáldozza az ő Istenének kenyerét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Az ő Istenének kenyeréből, a legszentségesebbikből és a szentségesből ehetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'Csak a függönyhöz be ne menjen, és az oltárhoz ne közelítsen, mert fogyatkozás van ő benne, hogy meg ne fertőztesse az én szenthelyemet. Én vagyok az Úr, az ő megszentelőjök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'És elmondá Mózes Áronnak, és az ő fiainak, és Izráelnek minden fiainak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Szóla ismét az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'Szólj Áronnak és az ő fiainak, hogy tartóztassák meg magokat Izráel fiainak szent adományaitól, hogy meg ne fertőztessék az én szent nevemet azokkal, a miket nékem szentelnek. Én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Mondd meg nékik: Ha valaki a ti nemzetségetekből, a ti összes magzataitok közül hozzájárul a szent dolgokhoz, a melyeket Izráel fiai szentelnek az Úrnak, mikor rajta van az ő tisztátalansága: az ilyen ember irtassék ki én előlem. Én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Ha valaki az Áron fiai közül poklos, vagy magfolyós, a szent dolgokból ne egyék, míg meg nem tisztul. A ki pedig valamely halott által megfertőzöttet illet, vagy valakit, a kinek magömlése van,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'Vagy ha valaki valamely férget illet, a mely által tisztátalanná lesz, vagy embert, a kitől tisztátalanná lesz annak valamilyen tisztátalanságához képest:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'Az ilyen ember, a ki effélét illet, tisztátalan legyen estvéig, és a szent dolgokból ne egyék, hanem ha megmosta a testét vízzel;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'De mikor lemegy a nap, tiszta lesz, és azután ehetik a szent dolgokból, mert az ő eledele az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Elhullott vagy széttépett állatot ne egyék, hogy tisztátalanná ne legyen általa. Én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Az én rendelésemet pedig megtartsák, hogy bűnbe ne essenek miatta, és meg ne haljanak a miatt, hogy megrontották azt. Én vagyok az Úr, az ő megszentelőjök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Idegen ember ne egyék szenteltet, a papnak zsellére és bérese se egyék szenteltet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'De ha megvásárol valakit a pap a maga pénzén, az ehetik abból, és a ki házánál született: ezek ehetnek az ő eledeléből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'De a pap leánya, ha idegennek lesz a felesége, nem ehetik a szent áldozatból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Ha azonban a pap leánya özvegygyé lesz vagy elválik, de magzata nincsen, és visszatér az ő atyjának házához, mint leánykorában: akkor ehetik az ő atyjának eledeléből; de idegen nem ehetik abból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Ha pedig tévedésből eszik valaki szenteltet, tegye ahhoz annak ötödrészét; így adja meg a papnak a szenteltet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'És meg ne fertőztessék Izráel fiainak szent dolgait, a melyeket áldoznak az Úrnak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'Hogy vétkes hamissággal ne terheljék magokat, ha esznek azoknak szent dolgaiból; mert én vagyok az Úr, az ő megszentelőjök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Szóla ismét az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Szólj Áronnak és az ő fiainak és Izráel minden fiának, és mondd meg nékik: ha valaki Izráel házából, és az Izráelben levő jövevények közül felviszi a maga áldozatát, akár fogadásból akár szabad akaratból, a miket felvisznek az Úrnak egészen égőáldozatul,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'Hogy kedvesen fogadtassanak: épek és hímek legyenek, akár tulkok, akár bárányok, akár kecskék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'A miben pedig fogyatkozás van, abból semmit se áldozzatok, mert nem lesz kedvessé ti érettetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'És ha valaki hálaáldozattal áldozik az Úrnak, akár fogadásának teljesítésére, akár szabad akaratból, akár tulokféléből, akár juhféléből: ép legyen, hogy kedves legyen; semmi fogyatkozás ne legyen abban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Vakot, vagy rokkantat, vagy csonkát, vagy fekélyest, vagy viszketegest, vagy varast, ilyeneket ne áldozzatok az Úrnak, és tűzáldozatul ne tegyetek ezekből az oltárra az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Hosszú, vagy kurta tagú ökröt, vagy bárányt szabad akaratból való áldozatul vihetsz ugyan, de fogadási áldozatul nem lesz kedves.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Szétnyomott, összezúzott, megszakadt, vagy kimetszett heréjűt se áldozzatok az Úrnak. Se a ti földeteken ne cselekedjétek ezt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Se idegen ember kezéből ne áldozzatok semmi ilyenből a ti Istenetek eledeléül; mert romlás van bennök, fogyatkozás van bennök: nem fogadtatnak kedvesen érettetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Szóla ismét az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'Borjú, bárány és kecske, ha megelletett, legyen az anyja alatt hét napig, a nyolczadik naptól fogva és azon túl kedves lesz az tűzáldozatul az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'De tehenet és juhot, azt és annak fiát ne öljétek meg egy napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Hogyha dicsőítő áldozattal áldoztok az Úrnak, úgy áldozzatok, hogy kedvesen fogadtassatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'Azon a napon egyétek meg, ne hagyjatok abból reggelig. Én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Tartsátok meg azért az én parancsolataimat, és azokat cselekedjétek. Én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'És meg ne fertőztessétek az én szent nevemet, hogy megszenteltessem Izráel fiai között. Én vagyok az Úr, a ti megszentelőtök,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'A ki kihoztalak titeket Égyiptom földéből, hogy Istenetek legyek néktek. Én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Szóla ismét az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Szólj Izráel fiainak, és mondd meg nékik az Úrnak ünnepeit, a melyeken szent gyülekezésekre kell összegyülekeznetek. Ezek azok az én ünnepeim:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Hat napon át munkálkodjatok, a hetedik napon nyugodalomnak, szent gyülekezésnek szombatja van, semmi dolgot ne végezzetek: az Úrnak szombatja legyen az minden lakhelyeteken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Ezek az Úrnak ünnepei, szent gyülekezések napjai, a melyekre szabott idejökben kell összegyülekeznetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'Az első hónapban, a hónapnak tizennegyedikén, estennen az Úrnak páskhája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'E hónapnak tizenötödik napján pedig az Úr kovásztalan kenyerének ünnepe. Hét napig egyetek kovásztalan kenyeret.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Az első napon szent gyülekezéstek legyen, semmi robota munkát ne végezzetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Hét napon át pedig tűzáldozatot áldozzatok az Úrnak, és a hetedik napon szent gyülekezéstek is legyen: semmi robota munkát ne végezzetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Szóla ismét az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Szólj Izráel fiainak és mondd meg nékik: Mikor bementek a földre, a melyet én adok néktek, és megaratjátok annak vetését: a ti aratástok zsengéjének első kévéjét vigyétek a papnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'Az pedig lóbálja meg a kévét az Úr előtt, hogy kedvesen fogadtassék érettetek; a szombat után való napon lóbálja azt meg a pap.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'A mely napon pedig meglóbáltatjátok a kévét, áldozzatok az Úrnak egy ép, esztendős bárányt egészen égőáldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'Ahhoz pedig ételáldozatul két tized efa lánglisztet, olajjal elegyítve; tűzáldozatul az Úrnak, kedves illatul; italáldozatul pedig egy hin bornak negyedrészét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Új kenyeret pedig és pergelt búzaszemeket és zsenge kalászokat ne egyetek mind a napig, a míg be nem viszitek a ti Isteneteknek áldozatját. Örök rendtartás ez nemzetségről nemzetségre minden lakóhelyeteken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Számláljatok azután a szombatra következő naptól, attól a naptól, a melyen beviszitek a meglóbálni való kévét, hét hetet, egészek legyenek azok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'A hetedik hétre következő napig számláljatok ötven napot, és akkor járuljatok új ételáldozattal az Úrhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'A ti lakóhelyeitekből hozzatok fel két meglóbálni való kenyeret; két tized efa lisztlángból legyenek azok, kovászszal sütve, zsengékül az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'A kenyérrel együtt pedig áldozzatok meg hét bárányt, épeket, esztendősöket, és egy tulkot, fiatal bikát, és két kost; egészen égőáldozatul legyenek ezek az Úrnak, étel- és italáldozatjokkal egybe; kedves illatú tűzáldozat ez az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Készítsetek el egy kecskebakot is bűnért való áldozatul, és két bárányt, esztendősöket, hálaadó áldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'És lóbálja meg azokat a pap a zsengékből való kenyérrel az Úr előtt való lóbálással a két báránynyal egybe. Szentek legyenek ezek az Úrnak a pap számára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'És gyülekezzetek egybe ugyanazon a napon; szent gyülekezéstek legyen néktek, semmi robota munkát ne végezzetek. Örök rendtartás ez minden lakóhelyeteken a ti nemzetségeitek szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'Mikor pedig földetek termését learatjátok: ne arasd le egészen a meződnek széleit, és az elhullott gabonafejeket fel ne szedd; a szegénynek és jövevénynek hagyd azokat. Én vagyok az Úr, a ti Istenetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Szóla ismét az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Szólj Izráel fiaihoz, mondván: A hetedik hónapban, a hónap első napján ünnepetek legyen néktek, emlékeztető kürtzengéssel, szent gyülekezéssel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Semmi robota munkát ne végezzetek, és tűzáldozattal áldozzatok az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Szóla ismét az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'Ugyanennek a hetedik hónapnak tizedikén az engesztelés napja van: szent gyülekezéstek legyen néktek, és sanyargassátok meg magatokat, és tűzáldozattal áldozzatok az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Semmi dolgot ne végezzetek azon a napon, mert engesztelésnek napja az, hogy engesztelés legyen érettetek az Úr előtt, a ti Istenetek előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Mert ha valaki nem sanyargatja meg magát ezen a napon, irtassék ki az ő népe közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'És ha valaki valami dolgot végez ezen a napon, elvesztem az ilyent az ő népe közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Semmi dolgot ne végezzetek; örök rendtartás legyen ez nemzetségről nemzetségre minden lakhelyeteken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Ünnepek ünnepe ez néktek, sanyargassátok meg azért magatokat. A hónap kilenczedikének estvéjén, egyik estvétől a másik estvéig ünnepeljétek a ti ünnepeteket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Szóla ismét az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Szólj Izráel fiainak, mondván: Ugyanennek a hetedik hónapnak tizenötödikén a sátorok ünnepe legyen az Úrnak hét napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Az első napon szent gyülekezés legyen, semmi robota munkát ne végezzetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Hét napon áldozzatok az Úrnak tűzáldozatot, a nyolczadik napon pedig szent gyülekezéstek legyen és újra tűzáldozattal áldozzatok az Úrnak; berekesztő ünnep ez, semmi robota munkát ne végezzetek azon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Ezek az Úrnak ünnepei, a melyeken szent gyülekezésekre kell gyülekeznetek, hogy áldozzatok az Úrnak tűzáldozattal, egészen égőáldozattal, ételáldozattal, véres- és italáldozattal: minden napét a maga napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'Az Úrnak szombatjain kivül, adományaitokon kivül, fogadásból és szabad akaratból való minden ajándékaitokon kivül a melyeket adni szoktatok az Úrnak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Ugyancsak a hetedik hónapnak tizenötödik napján, a mikor a földnek termését betakarjátok, az Úrnak ünnepét ünnepeljétek hét napig: az első napon nyugodalom napja, és a nyolczadik napon is nyugodalom napja legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'És vegyetek magatoknak az első napon szép fának gyümölcsét, pálmafa ágait, sűrű levelű fa lombját, és patak mellett való fűzgalyakat, és örvendezzetek az Úr előtt, a ti Istenetek előtt hét napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'Így ünnepeljétek meg azt az Úrnak ünnepét minden esztendőben hét napig. Örökkévaló rendtartás legyen ez a ti nemzetségeiteknél; a hetedik hónapban ünnepeljétek azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'Sátorokban lakjatok hét napig, minden benszülött sátorokban lakjék Izráelben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'Hogy megtudják a ti nemzetségeitek, hogy sátorokban lakattam Izráel fiait, a mikor kihoztam őket Égyiptom földéről. Én vagyok az Úr, a ti Istenetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'És szóla Mózes Izráel fiainak az Úrnak ünnepei felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Szóla ismét az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'Parancsold meg Izráel fiainak, hogy hozzanak néked tiszta faolajat, a melyet a világításhoz sajtoltak, hogy szünet nélkül égő lámpákat gyújthassanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'A bizonyság függönyén kivül, a gyülekezet sátorában úgy helyheztesse el azokat Áron, hogy estvétől fogva reggelig az Úr előtt legyenek. Örökkévaló rendtartás legyen ez a ti nemzetségeiteknél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'A tiszta arany gyertyatartóra rakja fel a mécseket; az Úr előtt legyenek szüntelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'És végy lisztlángot, és süss abból tizenkét lepényt; két tized efából legyen egy lepény.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'És helyheztesd el azokat két rendben; hatot egy rendbe, a tiszta arany asztalra az Úr elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'És tégy mindenik rendhez tiszta tömjént, és legyen emlékeztetőül a kenyér mellett, tűzáldozatul az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Szombat napról szombat napra rakja fel azt a pap az Úr elé szüntelen; örök szövetség ez Izráel fiaival.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Azután legyen az Ároné és az ő fiaié, a kik egyék meg azokat szent helyen, mert mint igen szentséges, az övé az, az Úrnak tűzáldozataiból, örök rendelés szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Kiméne pedig egy izráelbeli asszonynak fia, a ki égyiptomi férfiútól való vala, Izráel fiai közé, és versengének a táborban az izráelbeli asszonynak fia és egy izráelbeli férfi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'És káromlá az izráelbeli asszony fia az Isten nevét és átkozódék; elvivék azért azt Mózeshez. Az ő anyjának neve pedig Selomith vala, Dibrinek leánya, Dán nemzetségéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'És őrizet alá veték azt, míg kijelentést nyernének az Úr akarata felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Szóla azért az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'Vidd ki az átkozódót a táboron kivül, és mindazok, a kik hallották, tegyék kezeiket annak fejére és kövezze agyon azt az egész gyülekezet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Izráel fiainak pedig szólj, ezt mondván: Ha valaki az ő Istenét átkozza, viselje az ő bűnének terhét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'És a ki szidalmazza az Úrnak nevét, halállal lakoljon, kövezze azt agyon az egész gyülekezet; akár jövevény, akár benszülött, ha szidalmazza az Úrnak nevét, halállal lakoljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Ha valaki agyon üt valamely embert, halállal lakoljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Ha pedig barmot üt agyon valaki, fizesse meg azt: barmot baromért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'És ha valaki sérelmet ejt a felebarátján, a mint ő cselekedett, vele is úgy cselekedjenek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'Törést törésért, szemet szemért, fogat fogért; a milyen sérelmet ő ejtett máson, olyan ejtessék rajta is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'A ki barmot üt agyon, fizesse meg azt, de a ki embert üt agyon, halállal lakoljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Egy törvény legyen nálatok: a jövevény olyan legyen, mint a benszülött, mert én vagyok az Úr, a ti Istenetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Szóla azért Mózes Izráel fiainak, és kivivék az átkozódót a táboron kivül, és agyonverék azt kővel. És úgy cselekedének Izráel fiai, a mint parancsolta vala az Úr Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Szóla ismét az Úr Mózesnek a Sinai hegyen, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Szólj Izráel fiainak és mondd meg nékik: Mikor bementek a földre, a melyet én adok néktek, nyugodjék meg a föld az Úrnak szombatja szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Hat esztendőn át vesd a te szántóföldedet, és hat esztendőn át messed a te szőlődet, és takarítsd be annak termését;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'A hetedik esztendőben pedig szombati nyugodalma legyen a földnek, az Úrnak szombatja: szántóföldedet ne vesd be, és szőlődet meg ne mesd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'A mi a te tarló földeden magától terem, le ne arasd, és a mi a te metszetlen szőlődön terem, meg ne szedjed; mert nyugalom esztendeje lesz az a földnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'És a mit a föld az ő szombatján terem, legyen az eledelül néktek: néked, szolgádnak, szolgáló leányodnak, béresednek és zsellérednek, a kik nálad tartózkodnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'A te barmodnak is és a vadnak, a mely a te földeden van, legyen annak minden termése eledelül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Számlálj azután hét szombat-esztendőt, hétszer hét esztendőt, úgy hogy a hét szombat-esztendőnek ideje negyvenkilencz esztendő legyen:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Akkor fúvasd végig a riadó kürtöt a hetedik hónapban, a hónap tizedikén; az engesztelés napján fúvasd végig a kürtöt a ti egész földeteken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'És szenteljétek meg az ötvenedik esztendőt, és hirdessetek szabadságot a földön, annak minden lakójának; kürtölésnek esztendeje legyen ez néktek, és kapja vissza kiki az ő birtokát, és térjen vissza kiki az ő nemzetségéhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Kürtölésnek esztendeje ez, az legyen néktek az ötvenedik esztendő; ne vessetek és le se arassátok, a mit önként terem a föld, és a metszetlen szőlőjét se szedjétek meg annak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Mert kürtölésnek esztendeje ez, szent legyen néktek, a mezőről egyétek meg annak termését.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'A kürtölésnek ebben az esztendejében, kapja vissza ismét kiki az ő birtokát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Ha pedig eladsz valami eladni valót a te felebarátodnak, vagy vásárolsz valamit a te felebarátodtól: egymást meg ne csaljátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'A kürtölés esztendejét követő esztendők száma szerint vásárolj a te felebarátodtól; a terméses esztendők száma szerint adjon el néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Az esztendők nagyobb számához képest nagyobb árt adj azért, a mit veszesz, az esztendők kisebb számához képest pedig kisebb árt adj azért, a mit veszesz, mert a termések számát adja ő el néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Egymást azért meg ne csaljátok, hanem félj a te Istenedtől: mert én vagyok az Úr, a ti Istenetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Ha teljesítitek azért az én rendeléseimet, és megtartjátok végzéseimet, és teljesítitek azokat, bátorságosan lakhattok a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'És megtermi a föld az ő gyümölcsét, hogy eleget ehessetek, és bátorságosan lakhattok azon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Ha pedig azt mondjátok: Mit eszünk a hetedik esztendőben, ha nem vetünk, és termésünket be nem takarítjuk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'Én rátok bocsátom majd az én áldásomat a hatodik esztendőben, hogy három esztendőre való termés teremjen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'És mikor a nyolczadik esztendőre vettek, akkor is az ó termésből esztek egészen a kilenczedik esztendeig; mindaddig ó gabonát esztek, míg ennek termése be nem jön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'A földet pedig senki el ne adja örökre, mert enyém a föld; csak jövevények és zsellérek vagytok ti nálam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Azért a ti birtokotoknak egész földén megengedjétek, hogy a föld kiváltható legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Ha elszegényedik a te atyádfia, és elad valamit az ő birtokából, akkor álljon elő az ő rokona, a ki közel van ő hozzá, és váltsa ki, a mit eladott az ő atyjafia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Ha pedig nincs valakinek kiváltó rokona, de maga tesz szert annyira, hogy elege van annak megváltásához:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'Számlálja meg az eladása óta eltelt esztendőket, a felül lévőt pedig térítse meg annak, a kinek eladta volt, és újra övé legyen az ő birtoka.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Ha pedig nincsen módjában, hogy visszatéríthesse annak, akkor maradjon az ő eladott birtoka annál, a ki megvette azt, egészen a kürtölésnek esztendejéig: a kürtölésnek esztendejében pedig szabaduljon fel, és újra övé legyen az ő birtoka.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Ha valaki lakó-házat ad el kerített városban, az kiválthatja azt az eladás esztendejének elteléséig; egy esztendőn át válthatja ki azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Ha pedig ki nem váltják az esztendőnek teljes elteléséig, akkor a ház, a mely kerített városban van, örökre azé és annak nemzetségeié marad, a ki megvette azt; nem szabadul fel a kürtölésnek esztendejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Az olyan falvak házai pedig, a melyek nincsenek körülkerítve, mezei földek gyanánt számíttassanak, kiválthatók legyenek, és a kürtölésnek esztendejében felszabaduljanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'A mi pedig a léviták városait illeti, az ő birtokukban lévő városok házai a léviták által mindenkor kiválthatók legyenek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'De a mit ki nem vált is valaki a léviták közül, szabaduljon fel a kürtölésnek esztendejében, az eladott ház, és az ő birtokának városa; mert a léviták városainak házai tulajdon birtokuk nékik Izráel fiai között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'De a városaikhoz tartozó szántóföldeket el ne adják, mert örök birtokuk az nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Ha a te atyádfia elszegényedik, és keze erőtlenné lesz melletted, segítsd meg őt, akár jövevény, akár zsellér, hogy megélhessen melletted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Ne végy ő tőle kamatot vagy uzsorát, hanem félj a te Istenedtől, hogy megélhessen melletted a te atyádfia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Pénzedet ne add néki kamatra, se uzsoráért ne add a te eleségedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Én vagyok az Úr, a ti Istenetek, a ki kihoztalak titeket Égyiptom földéről, hogy néktek adjam Kanaán földét, és Istenetek legyek néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Ha pedig elszegényedik melletted a te atyádfia, és eladja magát néked: ne szolgáltassad úgy mint rabszolgát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'Mint béres, mint zsellér legyen nálad; a kürtölésnek esztendejéig szolgáljon nálad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Azután menjen el tőled ő és vele az ő gyermekei, és térjen vissza az ő nemzetségéhez, és térjen vissza az ő atyáinak örökségébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Mert az én szolgáim ők, a kiket kihoztam Égyiptom földéről: nem adathatnak el, mint rabszolgák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Ne uralkodjál rajta kegyetlenül, hanem félj a te Istenedtől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Mind szolgád, mind szolgálóleányod, a kik lesznek néked, a körületek lévő népek közül legyenek: azokból vásárolj szolgát és szolgálóleányt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'Meg a zsellérek gyermekei közül is, a kik nálatok tartózkodnak, azokból is vásárolhattok, és azoknak nemzetségéből, a kik veletek vannak, a kiket a ti földeteken nemzettek; és legyenek a ti tulajdonotok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'És örökül hagyhatjátok azokat a ti utánnatok való fiaitoknak, hogy örökségül bírják azokat, örökké dolgoztathattok velük; de a ti atyátokfiain, az Izráel fiain, egyik a másikán senki ne uralkodjék kegyetlenül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'És ha a jövevény vagy zsellér vagyonra tesz szert melletted, a te atyádfia pedig elszegényedik mellette, és eladja magát a melletted lévő jövevénynek, zsellérnek, vagy jövevény nemzetségéből való sarjadéknak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'Mindamellett is, hogy eladta magát, megváltható legyen; akárki megválthassa azt az ő atyjafiai közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'Vagy nagybátyja, vagy nagybátyjának fia váltsa meg azt, vagy az ő nemzetségéből való vérrokona váltsa meg azt, vagy, ha módja van hozzá, maga váltsa meg őmagát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'És vessen számot azzal, a ki megvette őt, attól az esztendőtől kezdve, a melyen eladta magát annak, a kürtölésnek esztendejéig, és az ő eladásának ára az esztendők száma szerint legyen, a béres ideje szerint legyen nála.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Ha még sok esztendő van hátra, azokhoz képest térítse meg annak a váltságot az ő megvásárlásának árából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'Ha pedig kevés esztendő van hátra a kürtölésnek esztendejéig, akkor is vessen számot vele, és az évek számához képest fizesse vissza az ő váltságát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Mint esztendőről esztendőre fogadott béres legyen nála; ne uralkodjék kegyetlenül rajta te előtted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Ha pedig ilyen módon meg nem váltatik, a kürtölésnek esztendejében szabaduljon fel: ő és vele az ő gyermekei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Mert az én szolgáim Izráel fiai, az én szolgáim ők, a kiket kihoztam Égyiptom földéről. Én vagyok az Úr, a ti Istenetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'Ne csináljatok magatoknak bálványokat, se faragott képet, se oszlopot ne emeljetek magatoknak, se kőszobrokat ne állítsatok fel a ti földeteken, hogy meghajoljatok előtte, mert én vagyok az Úr, a ti Istenetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Az én szombatjaimat megtartsátok, és az én szenthelyemet tiszteljétek. Én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Ha az én rendeléseim szerint jártok, és az én parancsolataimat megtartjátok, és azokat megcselekszitek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'Esőt adok néktek idejében, és a föld megadja az ő termését, a mező fája is megtermi gyümölcsét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'És a ti csépléstek ott éri a szüretet, és a szüret ott éri a vetést, és elégségig ehetitek kenyereteket, és bátorságosan lakhattok a ti földeteken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Mert békességet adok azon a földön, hogy mikor lefeküsztök, senki fel ne rettentsen; és kipusztítom az ártalmas vadat arról a földről, és fegyver sem megy át a ti földeteken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Sőt elűzitek ellenségeiteket, és elhullanak előttetek fegyver által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'És közületek öten százat elűznek, és közületek százan elűznek tízezeret, és elhullanak előttetek a ti ellenségeitek fegyver által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'És hozzátok fordulok, és megszaporítlak titeket, és megsokasítlak titeket és szövetségemet megerősítem veletek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'És réginél régibbet ehettek, és az új elől is régit kell kihordanotok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'És az én hajlékomat közétek helyezem, és meg nem útál titeket az én lelkem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'És közöttetek járok, és a ti Istenetek leszek, ti pedig az én népem lesztek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Én vagyok az Úr, a ti Istenetek, a ki kihoztalak titeket Égyiptom földéről, hogy ne legyetek azoknak rabjai, és összetörtem a ti igátok szegeit, és egyenesen járattalak titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Ha pedig nem hallgattok reám, és mind e parancsolatokat meg nem cselekeszitek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'És ha megvetitek rendeléseimet, és ha az én végzéseimet megútálja a ti lelketek, azáltal, hogy nem cselekszitek meg minden én parancsolatomat, hanem felbontjátok az én szövetségemet:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'Bizony azt cselekszem én veletek, hogy rettenetességet bocsátok reátok: a száraz betegséget és a forrólázt, a melyek szemeket égetnek és lelket epesztenek, és a ti magotokat hiába vetitek el, mert ellenségeitek emésztik meg azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'És kiontom haragomat reátok, hogy elhulljatok a ti ellenségeitek előtt, és uralkodjanak rajtatok a ti gyűlölőitek, és fussatok, mikor senki nem kerget is titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Ha pedig ezek után sem hallgattok reám, hétszerte keményebben megostorozlak titeket a ti bűneitekért;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'És megtöröm a ti megátalkodott kevélységeteket, és olyanná teszem az eget felettetek, mint a vas, a földeteket pedig olyanná, mint a réz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'És hiába fogy a ti erőtök, mert földetek nem adja meg az ő termését, s a föld fája sem adja meg az ő gyümölcsét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Ha mégis ellenemre jártok, és nem akartok reám hallgatni: hétszeres csapást borítok reátok a ti bűneitekért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'És reátok bocsátom a mezei vadakat, hogy megfoszszanak titeket gyermekeitektől, kiirtsák barmaitokat, és elfogyaszszanak titeket, hogy pusztákká legyenek a ti útaitok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'És ha ezek által sem jobbultok meg, hanem ellenemre jártok:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'Én is bizony ellenetekre járok, és hétszeresen sújtalak titeket a ti bűneitekért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'És hozok reátok bosszuló fegyvert, a mely bosszút álljon a szövetség megrontásáért. Ha városaitokba gyülekeztek össze, akkor döghalált bocsátok reátok, és az ellenség kezébe adattok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Mikor eltöröm nálatok a kenyérnek botját, tíz asszony süti majd a ti kenyereteket egy kemenczében, és megmérve viszik vissza a ti kenyereiteket, és esztek, de nem elégesztek meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'És ha e mellett sem hallgattok reám, hanem ellenemre jártok:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'Én is ellenetekre járok búsult haragomban, és bizony hétszeresen megostorozlak titeket a ti bűneitekért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'És megeszitek a ti fiaitok húsát, és megeszitek a ti leányaitok húsát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'És lerontom a ti magaslataitokat, és kiirtom a ti nap-oszlopaitokat, és a ti holttesteiteket bálványaitok holttetemeire hányatom, és megútál titeket az én lelkem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'És városaitokat sivataggá teszem; szenthelyeiteket is elpusztítom, és nem lesz kedves nékem a ti jóillatú áldozatotok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'És elpusztítom ezt a földet, hogy álmélkodjanak rajta a ti ellenségeitek, a kik letelepednek ebbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Titeket pedig elszélesztelek a pogány népek közé, és kivont fegyverrel űzetlek titeket, és pusztasággá lesz a ti földetek, városaitok pedig sivataggá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Akkor örül a föld az ő szombatjainak az ő pusztaságának egész ideje alatt, ti pedig a ti ellenségeitek földjén lesztek; akkor nyugodni fog a föld és örül az ő szombatjainak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Pusztaságának egész ideje alatt nyugodni fog, mivelhogy nem nyugodott a ti szombatjaitokon, mikor rajta laktatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'A kik pedig megmaradnak közületek, azoknak szívébe gyávaságot öntök az ő ellenségeiknek földén, és megkergeti őket a szállongó falevél zörrenése, és futnak, mintha fegyver elől futnának, és elhullanak, ha senki nem kergeti is őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'És egymásra hullanak, mint a fegyver előtt, pedig senki sem kergeti őket, és nem lesz megállásotok a ti ellenségeitek előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'És elvesztek a pogány népek között, és a ti ellenségeitek földe megemészt titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'A kik pedig megmaradnak közületek, elsenyvednek az ő hamisságuk miatt a ti ellenségeitek földén, sőt az ő atyáiknak hamissága miatt is azokkal együtt elsenyvednek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Akkor megvallják az ő hamisságukat, és atyáiknak hamisságát az ő hűtelenségökben, a melylyel hűtelenkedtek ellenem, és hogy mivel ellenemre jártak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'Bizony én is ellenökre járok, és beviszem őket az ő ellenségeik földjére; akkor talán megalázódik az ő körülmetéletlen szívök, és akkor az ő bűnöknek büntetését békével szenvedik:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'Én pedig megemlékezem Jákóbbal kötött szövetségemről, Izsákkal kötött szövetségemről is, Ábrahámmal kötött szövetségemről is megemlékezem, és e földről is megemlékezem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'A föld tehát pusztán hagyatik tőlük, és örül az ő szombatjainak, a míg pusztán marad tőlük, ők pedig békével szenvedik bűnöknek büntetését, azért, mert megvetették az én ítéleteimet, és megútálta lelkök az én rendeléseimet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'De mindamellett is, ha az ő ellenségeik földén lesznek is, akkor sem vetem meg őket, és nem útálom meg őket annyira, hogy mindenestől elveszítsem őket, felbontván velök való szövetségemet, mert én, az Úr, az ő Istenök vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Sőt megemlékezem érettök az elődökkel kötött szövetségről, a kiket kihoztam Égyiptom földéről, a pogány népek láttára, hogy Istenök legyek nékik. Én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Ezek a rendelések, a végzések és a törvények, a melyeket szerzett az Úr ő maga között és Izráel fiai között a Sinai hegyen Mózes által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Szóla ismét az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Szólj Izráel fiainak, és mondd meg nékik: Ha valaki fogadásul a te becslésed szerint való személyeket szentel az Úrnak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'Akkor, ha férfit kell becslened, húsz esztendőstől hatvan esztendősig ötven ezüst siklusra becsüljed, a szent siklus szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'Ha pedig asszony-személy az, harmincz siklusra becsüljed.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'Ha pedig öt esztendőstől húsz esztendősig való, akkor a fiúgyermeket húsz siklusra becsüljed, a leányt pedig tíz siklusra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'Ha pedig egy hónapostól öt esztendősig való, akkor a fiút öt ezüst siklusra becsüld, a leányt pedig három ezüst siklusra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Ha pedig hatvan esztendős és azon felül való, ha férfi, akkor becsüljed tizenöt siklusra, az asszony-személyt pedig tíz siklusra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Ha pedig szegényebb az, mint te becsülted, akkor állassák a pap elé, és becsülje meg azt a pap; a szerint becsülje azt a pap, a milyen módja van a fogadást tevőnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Ha pedig olyan barom az, a miből áldozni szoktak az Úrnak: mindaz, a mit az eféléből ád valaki az Úrnak, szent legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'Ne adjon mást helyette, és ki ne cserélje azt: jót hitványért, vagy hitványat jóért; de ha mégis kicserélne barmot barommal: mind ez, mind az, a mivel kicserélte, szent legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Ha pedig valamely tisztátalan barom az, a melyből nem vihetnek áldozatot az Úrnak: állassák azt a barmot a pap elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'És becsülje meg azt a pap akár jó, akár hitvány, és a mint becsüli a pap, úgy legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Ha pedig meg akarja váltani, adja hozzá annak ötödrészét a te becsléseden felül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'És ha valaki az ő házát szenteli az Úrnak szentségül, azt is becsülje meg a pap: akár jó, akár hitvány, és a mennyire a pap becsüli azt, úgy maradjon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Ha pedig az, a ki odaszentelte, megváltja az ő házát: akkor adja ahhoz a te becslésed szerint való árnak ötödrészét, és legyen az övé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'És ha valaki az ő mezei birtokából szentel valamit az Úrnak, akkor a mag szerint becsüld meg, a mely abba megy: egy hómer árpa-mag után ötven ezüst siklusra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Ha a kürtölésnek esztendejétől szenteli oda az ő mezejét, a mint becsülted, úgy maradjon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Ha pedig a kürtölés esztendeje után szenteli oda az ő mezejét, a pap számítsa fel néki az árt az esztendők száma szerint, a melyek hátra vannak a kürtölés esztendejéig, és szállíttassék le a te becslésed.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'És ha meg akarja váltani a mezőt az, a ki odaszentelte, akkor adja ahhoz az általad becsült árnak ötödrészét, és maradjon az övé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Ha pedig nem váltja meg azt a mezőt, és ha eladja azt a mezőt más valakinek, többé meg nem válthatja azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'És az a föld, mikor a kürtölésnek esztendejében felszabadul, az Úrnak szenteltessék, mint valamely néki szentelt mező, papok birtokává legyen az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Ha pedig pénzen vett mezejét, a mi nem az ő birtokának mezejéből való, valaki az Úrnak szenteli:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'Akkor számolja fel néki a pap a te becslésed szerint való összeget a kürtölés esztendejéig, és adja oda azt, a mire te becsülted, azon a napon szentségül az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'A kürtölésnek esztendejében visszaszáll a mező arra, a kitől vette azt, a kinek birtoka volt az a föld.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'Minden becslésed pedig a szent siklus szerint legyen; húsz géra legyen a siklus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Csak elsőszülöttet, a mely elsőszülött úgyis az Úré, azt ne szenteljen a baromféléből senki; akár borjú akár bárány, az Úré az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Ha pedig tisztátalan baromból való az, váltsa meg a te becslésed szerint, és adja hozzá annak ötödrészét; ha pedig nem váltják meg, adassék el a te becslésed szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'De semmi, a mit valaki teljesen az Úrnak szentelt, mind abból a mije van, akár ember vagy barom, akár mezei birtokából való, el ne adassék, és meg se váltassék; minden, a mi teljesen néki szenteltetett, igen szentséges az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Senki, a ki teljesen az Úrnak szenteltetett az emberek közül, meg ne váltassék, hanem halálra adassék bizonynyal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'A földnek minden tizede, a föld vetéséből, a fa gyümölcséből az Úré; szentség az az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'És ha valaki meg akar valamit váltani az ő tizedéből: adja hozzá annak ötödrészét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'És minden tizede a baromnak és juhnak, mindabból, a mi a vessző alatt átmegy, a tizedik az Úrnak legyen szentelve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'Ne tudakozódjék, ha jó-e vagy hitvány, és el se cserélje azt; de ha mégis elcseréli azt, akkor az, és a mit cserébe adott azért, szent legyen, és meg se váltassék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Ezek azok a parancsolatok, a melyeket Mózes által parancsolt az Úr Izráel fiainak a Sinai hegyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Szóla pedig az Úr Mózesnek a Sinai pusztájában, a gyülekezet sátorában, a második hónapnak elsején, az Égyiptom földéből való kijövetelök után a második esztendőben, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, 'Vegyétek számba Izráel fiainak egész gyülekezetét, az ő nemzetségeik szerint, az ő atyáiknak háznépe szerint, a neveknek száma szerint, minden férfiút főről főre,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'Húsz esztendőstől fogva és feljebb, mindent, a ki hadba mehet Izráelben; számláljátok meg őket az ő seregök szerint, te és Áron.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'És legyen veletek egy-egy férfiú mindenik törzsből, mindenik feje legyen az ő atyái házának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Ezek pedig a férfiak nevei, a kik veletek legyenek: Rúbenből Elisúr, Sedeúrnak fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'Simeonból Selúmiel, Surisaddainak fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'Júdából Naasson, Amminádábnak fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'Izsakhárból Néthánéel, Suárnak fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'Zebulonból Eliáb, Hélonnak fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'József fiai közül: Efraimból Elisama, Ammihudnak fia; Manasséból Gámliel, Pédasurnak fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'Benjáminból Abidán, Gideóni fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'Dánból Ahiézer, Ammisaddai fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'Áserből Págiel, Okránnak fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'Gádból Eleásaf, Déhuelnek fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'Nafthaliból Akhira, Enánnak fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Ezek a gyülekezetnek hivatalosai, az ő atyjok törzseinek fejei, Izráel ezereinek is fejei ők.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Maga mellé vevé azért Mózes és Áron e férfiakat, a kik név szerint is előszámláltattak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'És összegyüjték az egész gyülekezetet a második hónapnak első napján; és vallást tőnek az ő születésökről, az ő nemzetségeik szerint, az ő atyáiknak háznépe szerint, a neveknek száma szerint, húsz esztendőstől fogva és feljebb főről főre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'A miképen megparancsolta vala az Úr Mózesnek, úgy számlálá meg őket a Sinai pusztájában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Valának pedig Rúbennek, Izráel elsőszülöttének fiai, azoknak szülöttei az ő nemzetségeik szerint, az ő atyáiknak háznépe szerint, a nevek száma szerint, főről főre, minden férfiú, húsz esztendőstől fogva és feljebb, minden hadba mehető;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'A kik megszámláltattak a Rúben törzséből: negyvenhat ezer és ötszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Simeon fiai közül azoknak szülöttei az ő nemzetségeik szerint, az ő atyáiknak háznépe szerint, az ő megszámláltjai, a neveknek száma szerint, főről főre, minden férfiú, húsz esztendőstől fogva és feljebb, minden hadba mehető;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'A kik megszámláltattak Simeon törzséből: ötvenkilencz ezer és háromszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Gád fiai közül azoknak szülöttei az ő nemzetségeik szerint, az ő atyáiknak háznépe szerint, a neveknek száma szerint, húsz esztendőstől fogva és feljebb, minden hadba mehető;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'A kik megszámláltattak Gád törzséből: negyvenöt ezer és hatszáz ötven.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Júda fiai közül azoknak szülöttei az ő nemzetségeik szerint, az ő atyáiknak háznépe szerint, a nevek száma szerint, húsz esztendőstől fogva és feljebb, minden hadba mehető;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'A kik megszámláltattak Júda törzséből: hetvennégy ezer és hatszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Izsakhár fiai közül azoknak szülöttei az ő nemzetségeik szerint, az ő atyáiknak háznépe szerint, a nevek száma szerint, húsz esztendőstől fogva és feljebb, minden hadba mehető;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'A kik megszámláltattak Izsakhár törzséből: ötvennégy ezer és négyszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Zebulon fiai közül azoknak szülöttei az ő nemzetségeik szerint, az ő atyáiknak háznépe szerint, a nevek száma szerint, húsz esztendőstől fogva és feljebb, minden hadba mehető;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'A kik megszámláltattak Zebulon törzséből: ötvenhét ezer és négyszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'József fiaiból Efraim fiai közül azoknak szülöttei az ő nemzetségeik szerint, az ő atyáiknak háznépe szerint, a neveknek száma szerint, húsz esztendőstől fogva és feljebb, minden hadba mehető;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'A kik megszámláltattak Efraim törzséből: negyvenezer és ötszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Manasse fiai közül azoknak szülöttei az ő nemzetségeik szerint, az ő atyáiknak háznépe szerint, a nevek száma szerint, húsz esztendőstől fogva és feljebb, minden hadba mehető;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'A kik megszámláltattak Manasse törzséből: harminczkét ezer és kétszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Benjámin fiai közül azoknak szülöttei az ő nemzetségeik szerint, az ő atyáiknak háznépe szerint, a nevek száma szerint, húsz esztendőstől fogva és feljebb, minden hadba mehető;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'A kik megszámláltattak Benjámin törzséből: harminczöt ezer és négyszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Dán fiai közül azoknak szülöttei az ő nemzetségeik szerint, az ő atyáiknak háznépe szerint, a nevek száma szerint, húsz esztendőstől fogva és feljebb, minden hadba mehető;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'A kik megszámláltattak Dán törzséből: hatvankét ezer és hétszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Áser fiai közül azoknak szülöttei az ő nemzetségeik szerint, az ő atyáiknak háznépe szerint, a neveknek száma szerint, húsz esztendőstől fogva és feljebb, minden hadba mehető;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'A kik megszámláltattak Áser törzséből: negyvenegy ezer és ötszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'A Nafthali fiainak szülöttei az ő nemzetségeik szerint, az ő atyáiknak háznépe szerint, a neveknek száma szerint, húsz esztendőstől fogva és feljebb, minden hadba mehető;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'A kik megszámláltattak a Nafthali törzséből: ötvenhárom ezer és négyszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Ezek azok a megszámláltattak, a kiket megszámláltak Mózes és Áron és Izráel fejedelmei, tizenkét férfiú; egy-egy férfiú vala az ő atyáiknak házanépéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Valának azért mindnyájan, a kik megszámláltattak az Izráel fiai közűl az ő atyáiknak háznépe szerint, húsz esztendőstől fogva és feljebb, minden hadba mehető az Izráelben;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'Valának mindnyájan a megszámláltattak: hatszáz háromezer és ötszáz ötven.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'De a léviták az ő atyáiknak háznépe szerint nem számláltattak közéjök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Mert szólott vala az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'Csak a Lévi törzsét ne vedd számba, és azokat ne számláld Izráel fiai közé;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'Hanem a lévitákat rendeld a bizonyság hajlékához, és minden edényéhez, és minden ahhoz valókhoz; ők hordozzák a hajlékot, és annak minden edényét, és ők szolgáljanak mellette, és a hajlék körül táborozzanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'És mikor a hajléknak elébb kell indulni, a léviták szedjék azt szét, mikor pedig megáll a hajlék, a léviták állassák azt fel, az idegen pedig, a ki oda járul, meghaljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'És tábort járjanak Izráel fiai kiki az ő táborában, és kiki az ő zászlója alatt, az ő seregeik szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'A léviták pedig tábort járjanak a bizonyság hajléka körül, hogy ne legyen harag Izráel fiainak gyülekezetén; és megtartsák a léviták a bizonyság hajlékának őrizetét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Cselekedének azért az Izráel fiai mind a szerint, a mint parancsolta vala az Úr Mózesnek, úgy cselekedének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'És szóla az Úr Mózesnek és Áronnak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'Az Izráel fiai, kiki az ő zászlója alatt, az ő atyáik háznépének jeleivel járjon tábort, a gyülekezet sátora körül járjon tábort annak oldalai felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Így járjanak pedig tábort: Keletre naptámadat felől Júda táborának zászlója az ő seregeivel; és Júda fiainak fejedelme Naasson, Amminádáb fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'Az ő serege pedig, vagyis az ő megszámláltjaik: hetvennégy ezer és hatszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Mellette pedig tábort járjon Izsakhár törzse, és Izsakhár fiainak fejedelme Néthánéel, Suárnak fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'Az ő serege pedig, vagyis az ő megszámláltjaik: ötvennégy ezer és négyszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'Zebulon törzse, és Zebulon fiainak fejedelme Eliáb, Hélon fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'Az ő serege pedig, vagyis az ő megszámláltjaik: ötvenhét ezer és négyszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Mindnyájan, a kik megszámlálva voltak Júda táborában: száz nyolcvanhat ezer és négyszáz, az ő seregeik szerint. Ezek induljanak előre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'Rúben táborának zászlója legyen dél felől az ő seregeivel, és Rúben fiainak fejedelme Elisúr, Sedeúr fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'Az ő serege pedig, vagyis az ő megszámláltjaik: negyvenhat ezer és ötszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Mellette pedig tábort járjon Simeon törzse, és Simeon fiainak fejedelme: Selúmiel, Surisaddai fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'Az ő serege pedig, vagyis az ő megszámláltjaik: ötvenkilencz ezer és háromszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'Azután Gád törzse, és Gád fiainak fejedelme: Eliásáf, a Réuel fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'Az ő serege pedig, vagyis az ő megszámláltjaik: negyvenöt ezer és hatszáz ötven.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Mindnyájan, a kik megszámlálva voltak Rúben táborában: száz ötvenegy ezer és négyszáz ötven az ő seregeik szerint. Ezek másodszorra induljanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Azután induljon a gyülekezet sátora, a léviták táborával, a táboroknak közepette: A miképen tábort járnak, a képen induljanak, kiki az ő helyén, az ő zászlója mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Efraim táborának zászlója az ő seregeivel nyugot felé legyen, és Efraim fiainak fejedelme: Elisáma, Ammihud fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'Az ő serege pedig, vagyis az ő megszámláltjaik: negyven ezer és ötszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'És ő mellette legyen Manasse törzse, és Manasse fiainak fejedelme Gámliel, Pédasur fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'Az ő serege pedig, vagyis az ő megszámláltjaik, harminczkét ezer és hétszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'Azután legyen Benjámin törzse és Benjámin fiainak fejedelme: Abidám, Gideóni fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'Az ő serege pedig, vagyis az ő megszámláltjaik: harminczöt ezer és négyszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Mindnyájan a kik megszámlálva voltak Efraim táborában, száz nyolczezer és száz az ő seregeik szerint. Ezek harmadszorra induljanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Dán táborának zászlója legyen észak felől az ő seregeivel, és a Dán fiainak fejedelme: Ahiézer, Ammisaddai fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'Az ő serege pedig, vagyis az ő megszámláltjaik: hatvankét ezer és hétszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Mellette pedig tábort járjon Áser törzse, és Áser fiainak fejedelme: Págiel, az Okhrán fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'Az ő serege pedig, vagyis az ő megszámláltjaik: negyvenegy ezer és ötszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'Azután legyen Nafthali törzse, és Nafthali fiainak fejedelme: Akhira, Enán fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'Az ő serege pedig, vagyis az ő megszámláltjaik: ötvenhárom ezer és négyszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Mindnyájan, a kik megszámlálva voltak Dán táborában, száz ötvenhét ezer és hatszáz; utóljára induljanak az ő zászlóik szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Ezek Izráel fiainak megszámláltjai az ő atyáiknak háznépei szerint; mindnyájan, a kik megszámlálva voltak táboronként, az ő seregeik szerint: hatszáz háromezer ötszáz és ötven.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'De a léviták nem voltak számba véve Izráel fiai között, a mint megparancsolta volt az Úr Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'És cselekedének Izráel fiai mind a szerint, a mint parancsolta volt az Úr Mózesnek: aképen járának tábort, az ő zászlóik szerint, és úgy indulának, kiki az ő nemzetsége szerint, az ő atyáiknak háznépe szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Ezek pedig Áronnak és Mózesnek szülöttei azon a napon, a melyen szólott az Úr Mózesnek a Sinai hegyen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Ezek az Áron fiainak nevei: Az elsőszülött Nádáb, azután Abihú, Eleázár és Ithamár.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Ezek Áron fiainak, a felkenetett papoknak nevei, a kiket papi szolgálatra avattak fel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'De Nádáb és Abihú meghala az Úr előtt, mikor idegen tűzzel áldozának az Úr előtt a Sinai pusztájában, fiaik pedig nem valának nékik. Eleázár és Ithamár viselék azért a papságot, Áronnak, az ő atyjoknak színe előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Szóla pedig az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'Hozd elő Lévi törzsét, és állassad Áron pap elé, hogy szolgáljanak néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'És ügyeljenek az ő ügyére, és az egész gyülekezet ügyére a gyülekezet sátora előtt, hogy végezhessék a hajlék körül való szolgálatot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'Ügyeljenek pedig a gyülekezet sátorának minden eszközére is, és Izráel fiainak ügyeire is, hogy végezhessék a hajlék körül való szolgálatot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'És adjad a lévitákat Áronnak és az ő fiainak; mert valóban néki adattak Izráel fiaitól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Áront pedig és az ő fiait rendeld föléjök, hogy őrizzék az ő papságukat; és ha idegen járulna oda, haljon meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Szóla azután az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'Ímé én kiválasztottam a lévitákat Izráel fiai közül, minden elsőszülött helyett, a mely az ő anyjának méhét megnyitja Izráel fiai között: azért legyenek a léviták enyéim.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Mert enyém minden elsőszülött; a mikor megöltem minden elsőszülöttet Égyiptom földén, magamnak szenteltem minden elsőszülöttet Izráelben; akár ember, akár barom, enyéim legyenek: én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Szóla azután az Úr Mózesnek a Sinai pusztájában, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Számláld meg Lévi fiait az ő atyáiknak háznépe szerint, az ő nemzetségeik szerint; egy hónapostól fogva, és azon felül minden fineműt számlálj meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Megszámlálá azért Mózes őket az Úr szava szerint, a miképen meghagyatott vala néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'És ezek voltak a Lévi fiai az ő neveik szerint: Gerson, Kéhát és Mérári.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Ezek pedig a Gerson fiainak nevei az ő nemzetségök szerint: Libni és Simhi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'Továbbá a Kéhát fiai az ő nemzetségök szerint: Amrám és Iczhár, Hebron és Uzziél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'A Mérári fiai pedig az ő nemzetségök szerint: Makhli és Músi. Ezek a Lévi nemzetségei, az ő atyáiknak háznépe szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'Gersontól valók a Libni nemzetsége és a Simhi nemzetsége; ezek a Gersoniták nemzetségei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Az ő megszámláltjaik, az egy hónapostól fogva és feljebb minden fineműnek száma szerint, az ő megszámláltjaik: hétezer és ötszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'A Gersoniták nemzetségei a hajlék megett járjanak tábort nyugot felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'És a Gersoniták atyái háznépének fejedelme legyen Eliásáf, a Láél fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'A Gerson fiainak tiszte pedig: ügyelni a gyülekezet sátorában, a hajlékra, a sátorra, annak takarójára, és a gyülekezet sátora nyílásának leplére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'Továbbá a pitvarnak szőnyegeire, és a pitvar nyílásának leplére, a mely van a hajlékon és az oltáron köröskörül, és annak köteleire, és minden azzal járó szolgálatra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Kéháttól való pedig az Amrám nemzetsége, az Iczhár nemzetsége, a Hebron nemzetsége és az Uzziél nemzetsége: Ezek Kéhátnak nemzetségei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Minden fineműnek száma szerint, egy hónapostól fogva és feljebb, nyolczezeren és hatszázan valának a szenthelynek őrizői.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'A Kéhát fiainak nemzetségei a hajlék oldala mellett dél felől járjanak tábort.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'És a Kéhátiták nemzetségének, az ő atyái háznépének fejedelme legyen Elisáfán, Uzziélnek fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Az ő tisztök pedig, ügyelni a ládára, az asztalra, a gyertyatartóra, az oltárokra és a szenthelynek edényeire, a melyekkel szolgálnak, és a takaróra, és minden azzal járó szolgálatra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Továbbá a léviták fejedelmeinek fejedelme legyen Eleázár, Áron pap fia: a szenthelyre ügyelőknek előljárója.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'Méráritól való a Makhli és Músi nemzetségei; ezek a Mérári nemzetségei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'Az ő megszámláltjaik pedig minden fineműnek száma szerint, egy hónapostól fogva és feljebb: hatezer és kétszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'És a Mérári nemzetségének, az ő atyái háznépének fejedelme legyen Suriel, az Abihail fia; a hajléknak észak felől való oldala mellett járjanak tábort.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'A Mérári fiainak pedig tisztök legyen felügyelni: a hajlék deszkáira, annak reteszrúdaira, oszlopaira és annak talpaira, minden edényeire és minden azzal járó szolgálatra;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'Továbbá a pitvar körül való oszlopokra és azoknak talpaira, szegeire és köteleire.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'A hajlék előtt keletre, a gyülekezet sátora előtt naptámadat felől, Mózes, Áron és az ő fiai járjanak tábort, a kik felügyelnek a szenthely szolgálatára, és Izráel fiainak ügyeire; ha pedig idegen járulna oda, haljon meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'A léviták minden megszámláltja, a kiket Mózes és Áron az Úr rendeletére nemzetségenként számláltak vala meg, minden finemű, az egy hónapostól fogva és feljebb: huszonkét ezer.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'És monda az Úr Mózesnek: Számláld meg Izráel fiainak minden finemű elsőszülöttét, egy hónapostól fogva és feljebb, és pedig névszerint számláld meg őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'És válaszd a lévitákat nékem (én vagyok az Úr) az Izráel fiai közül való minden elsőszülött helyett; és a léviták barmait, Izráel fiai barmainak minden első fajzása helyett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Megszámlálá azért Mózes, a mint parancsolta vala néki az Úr, Izráel fiainak minden elsőszülöttét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'És lőn minden finemű elsőszülött a nevek száma szerint, egy hónapostól fogva és feljebb, az ő megszámláltjaik: huszonkét ezer kétszáz és hetvenhárom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'És szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Válaszd a lévitákat az Izráel fiai közül való minden elsőszülött helyett; és a léviták barmait az ő barmaik helyett, és legyenek enyéim a léviták. Én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'A mi pedig a kétszáz és hetvenháromnak megváltását illeti, a kik felül vannak a lévitákon Izráel fiainak elsőszülöttei közül:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'Végy öt-öt siklust fejenként; a szent siklus szerint vedd azt, (húsz géra egy siklus).');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'És add azt a pénzt Áronnak és az ő fiainak, váltságul a köztök lévő számfelettiekért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Bevevé azért Mózes a váltságpénzt azoktól, a kik felül voltak a lévitáktól megváltottakon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'Izráel fiainak elsőszülöttitől vevé be e pénzt: ezer háromszáz és hatvanöt siklust, a szent siklus szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'És adá Mózes a megváltottaknak pénzét Áronnak és az ő fiainak, az Úr rendelete szerint, a miképen parancsolta az Úr Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'És szóla az Úr Mózesnek és Áronnak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'Vedd számba a Kéhát fiait Lévi fiai közül nemzetségenként, az ő atyjoknak háznépe szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'Harmincz esztendőstől és azon felül az ötven esztendősökig mindenkit, a ki szolgálatra való, hogy munkálkodjék a gyülekezet sátorában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Ez a tisztök Kéhát fiainak a gyülekezet sátorában: a legszentségesebbekről való gondviselés.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Áron és az ő fiai pedig, mikor indulni akar a tábor, menjenek be, és vegyék le a takaró függönyt, és takarják be azzal a bizonyság ládáját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'És tegyenek arra borzbőrből csinált takarót, és borítsák azt be egészen kékszínű ruhával felülről, és dugják belé a rúdjait is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'A szent kenyerek asztalát is borítsák be kékszínű ruhával, azon felül tegyék rá a tálakat, a csészéket, a kelyheket, és az italáldozathoz való kancsókat, és ama szüntelen való kenyér is rajta legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Azután borítsanak azokra karmazsinszínű ruhát, és takarják be azt borzbőrből való takaróval, és dugják belé a rúdjait is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Vegyenek azután kékszínű ruhát, és takarják be a világításra való gyertyatartót és annak mécseit, hamvvevőit, hamutartóit és minden olajos edényét, a melyekkel szolgálnak körülte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'És tegyék azt és minden edényét borzbőrből csinált takaróba, és tegyék saroglyára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Az arany oltárt is borítsák be kékszínű ruhával, és takarják be borzbőrből csinált takaróval, és dugják belé a rúdjait is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Vegyék elő azután a szolgálatnak minden eszközét, a melyekkel szolgálni fognak a szenthelyen, és tegyék kékszínű ruhába, és takarják be azokat borzbőrből csinált takaróval, és tegyék a saroglyára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Azután takarítsák el a hamvat az oltárról, és borítsanak arra bíborpiros színű ruhát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'És tegyék rá arra minden ő eszközét, a melyekkel szolgálnak azon: a szenes serpenyőket, a villákat, a lapátokat és a medenczéket, az oltárnak minden eszközét; és borítsanak arra borzbőrből csinált takarót, és dugják belé a rúdjait is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Ha pedig elvégezi Áron és az ő fiai a szenthelynek és a szenthely minden edényének betakarását, mikor el akar indulni a tábor: akkor jöjjenek el Kéhát fiai, hogy elvigyék azokat; de ne illessék a szenthelynek semmi edényét, hogy meg ne haljanak. Ezek Kéhát fiainak terhei a gyülekezet sátorában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Eleázárnak pedig, az Áron pap fiának tiszte: a világító olajra, a füstölő szerekre, a szüntelen való ételáldozatra és a kenetnek olajára; az egész hajlékra és mindenre, a mi abban van, mind a szenthelyre, mind annak edényeire való gondviselés.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Szóla azután az Úr Mózesnek és Áronnak mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'A Kéhátiták nemzetségének törzsét ne engedjétek kiirtani a léviták közül;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'Hanem ezt míveljétek ő velök, hogy éljenek és meg ne haljanak, mikor járulnak a szentségek szentségéhez: Áron és az ő fiai jöjjenek el, és rendeljék el őket, kit-kit az ő szolgálatára és az ő terhére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'Egy pillanatra se menjenek be, hogy meglássák a szenthelyet, hogy meg ne haljanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Szóla ezután az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Vedd számba a Gerson fiait is az ő atyjoknak háznépe szerint, az ő nemzetségök szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'A harmincz esztendőstől és azon felül az ötven esztendősig számláld meg őket; mindenkit, a ki szolgálatot teljesíteni való, hogy szolgáljon a gyülekezet sátorában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Ez legyen munkájok a Gersoniták nemzetségeinek a szolgálatban és a teherhordozásban:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'Hordozzák a hajlék kárpitjait és a gyülekezet sátorát, annak takaróját és a borzbőrből csinált takarót, a mely rajta van felül, és a gyülekezet sátora nyilásának leplét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'És a pitvar szőnyegeit, és a pitvar kapunyílásának leplét, a melyek a hajlékon és az oltáron köröskörül vannak, azoknak köteleit, és az ő szolgálatjokhoz való minden edényt; és mindazt, a mi tenni való azokkal, ők teljesítsék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Áronnak és az ő fiainak beszéde szerint legyen a Gersoniták fiainak minden szolgálatjok, minden terhökre és minden szolgálatjokra nézve; minden terhöket pedig az ő őrizetökre bízzátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Ez a Gersoniták fiai nemzetségének szolgálata a gyülekezet sátorában; az ő szolgálatuk pedig legyen az Áron pap fiának, Ithamárnak keze alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'A Mérári fiait is az ő nemzetségeik szerint, az ő atyjoknak háznépei szerint számláld meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'A harmincz esztendőstől és annál feljebb az ötven esztendősig számláld meg őket; mindenkit, a ki szolgálatra való, hogy szolgálatot végezzen a gyülekezet sátorában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Ezek pedig, a mikre ügyelniök kell a továbbvitelnél és a gyülekezet sátorában való minden szolgálatuknál: a hajlék deszkái, annak reteszrúdjai, oszlopai és talpai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'A pitvarnak is köröskörül való oszlopai és azok talpai, szegei és kötelei, azoknak minden szerszámai, és minden szolgálatjokhoz való. Név szerint is megszámláljátok az edényeket, a mikre a továbbvitelnél ügyelniök kell.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Ez legyen szolgálatuk a Mérári fiai nemzetségeinek, a melylyel szolgáljanak a gyülekezet sátorában, Ithamárnak, az Áron pap fiának vezetése alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'És megszámlálá Mózes és Áron és a gyülekezet fejedelmei a Kéhátiták fiait, az ő nemzetségök szerint és az ő atyjoknak háznépe szerint,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'A harmincz esztendőstől és annál feljebb, az ötven esztendősig mindenkit, a ki szolgálatra való, hogy szolgáljon a gyülekezet sátorában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'Vala pedig azoknak száma az ő nemzetségeik szerint: kétezer hétszáz és ötven.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Ezek a Kéhátiták nemzetségeinek megszámláltjai, mindazok, a kik szolgálnak vala a gyülekezet sátorában, a kiket megszámlált Mózes és Áron az Úrnak parancsolatja szerint, a Mózes keze által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'A Gerson fiainak száma az ő nemzetségeik szerint, és az ő atyáiknak háznépe szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'A harmincz esztendőstől és azon felül az ötven esztendősig mindazok, a kik szolgálatra valók, hogy szolgáljanak a gyülekezet sátorában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'Azoknak száma az ő nemzetségök szerint, az ő atyjoknak háznépe szerint: kétezer hatszáz és harmincz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Ezek a Gerson fiai nemzetségeinek megszámláltjai, a kik mindnyájan szolgálnak a gyülekezet sátorában, a kiket megszámlált Mózes és Áron az Úrnak beszéde szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'A Mérári fiai nemzetségeinek száma az ő nemzetségei szerint, az ő atyjoknak háznépe szerint;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'A harmincz esztendőstől és azon felül az ötven esztendősig mindazok, a kik szolgálatra valók, hogy szolgáljanak a gyülekezet sátorában;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'Ezeknek száma az ő nemzetségeik szerint: háromezer és kétszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Ezek a Mérári fiai nemzetségeinek megszámláltjai, a kiket megszámlált Mózes és Áron az Úrnak beszéde szerint, a Mózes keze által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Mindnyájan a megszámláltatott léviták, a kiket megszámlált Mózes és Áron, és Izráel fejedelmei az ő nemzetségeik és atyjoknak háznépe szerint;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'A harmincz esztendőstől és azon felül az ötven esztendősig, a kik csak alkalmatosak a szolgálatra, a szolgálatnak gyakorlására, és a továbbvitelnél való szolgálatra a gyülekezetnek sátorában;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'Ezeknek száma lőn nyolczezer ötszáz és nyolczvan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Az Úrnak beszéde szerint számlálták meg őket a Mózes keze által kit-kit az ő szolgálata szerint, és az ő vinni való terhe szerint. Ez az a számlálás, a melyet az Úr parancsolt vala Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'És szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'Parancsold meg Izráel fiainak, hogy űzzenek ki a táborból minden poklost, és minden magfolyóst, és mindenkit, a ki holttest miatt lett tisztátalanná.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Űzzétek azt ki akár férfi, akár asszony; a táboron kivül űzzétek őket, hogy tisztátalanná ne tegyék az ő táborukat, mivelhogy én közöttök lakozom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'És úgy cselekedének Izráel fiai, és kiűzék azokat a táboron kivül; a miképen meghagyta vala az Úr Mózesnek, úgy cselekedtek Izráel fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Szóla azután az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Szólj Izráel fiainak: Ha akár férfi, akár asszony, akármi emberi bűnt követ el, a mely által hűtelenné válik az Úrhoz; az a lélek vétkessé lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'Vallja meg azért az ő bűnét, a melyet elkövetett, és fizesse meg a kárt, a mit okozott, teljes értékében, azután toldja ahhoz annak ötödrészét, és adja annak, a kinek kárt tett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Ha pedig nincs az embernek atyjafia, a kinek megfizetné a kárt: a megtérített kár az Úré legyen a pap számára, az engesztelésre való koson kivül, a melylyel engesztelés tétetik érte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Izráel fiainak minden szent dolgaiból minden felmutatott áldozat azé a papé legyen, a kihez viszik azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'És kinek-kinek az ő szenteltje a magáé legyen; a mit pedig kiki a papnak ád, azé legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Szóla azután az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Szólj Izráel fiainak, és mondd meg nékik: Ha elhajol valakinek a felesége, és hűtelenné válik iránta;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'És hál valaki ő vele közösülve, és az ő férje előtt titok marad, és elrejtetik, hogy ő megfertőztetett; bizonyság pedig nincs ellene, sem a bűnön nem kapták;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'De felgerjed ő benne a féltékenység lelke, és féltékenykedik a feleségére, mivelhogy az megfertőztetett; vagy felgerjed ő benne a féltékenység lelke, és féltékenykedik a feleségére, jóllehet az meg nem fertőztetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'Akkor vigye a férfiú az ő feleségét a paphoz; és vigye el azzal együtt az érette való áldozatot; egy efa árpalisztnek tizedrészét; de ne öntsön arra olajt, és ne tegyen arra temjént, mert féltékenységi ételáldozat ez, emlékeztető ételáldozat ez, a mely hamisságra emlékeztet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'A pap pedig léptesse elő az asszonyt, és állassa őt az Úr elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'És vegyen a pap szent vizet cserépedénybe; a hajlék pádimentomán levő porból is vegyen a pap, és tegye azt a vízbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'És állassa a pap az asszonyt az Úr elé és fejét meztelenítse meg az asszonynak, és tegye annak kezére az emlékeztető ételáldozatot, féltékenységi ételáldozat az; és a papnak kezében legyen átokhozó keserű víz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'És eskesse meg őt a pap, és ezt mondja az asszonynak: Ha nem hált veled senki, és ha el nem hajoltál tisztátalanságra a te férjed mellett, ne ártson néked ez az átokhozó, keserű víz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Ha pedig elhajoltál a te férjed mellől, és megfertőztetted magadat, és valaki közösült veled a te férjeden kívül,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'Miután megeskette a pap az asszonyt az átoknak esküjével, ezt mondja az asszonynak: Tegyen tégedet az Úr átokká, és eskü-példává a te néped között, megszárasztván az Úr a te tomporodat, és a te méhedet dagadtá tévén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'És menjen be az átokhozó víz a te belső részeidbe, hogy megdagadjon a te méhed, és megszáradjon a te tomporod. Az asszony pedig mondja: Ámen! Ámen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'És írja fel a pap ez átkokat levélre, azután törölje le a keserű vízzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'És itassa meg az asszonynyal az átokhozó keserű vizet, hogy bemenjen ő belé az átokhozó víz az ő keserűségére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Azután vegye el a pap az asszony kezéből a féltékenységi ételáldozatot, és lóbálja meg azt az ételáldozatot az Úr előtt, és áldozzék azzal az oltáron.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'És vegyen egy marokkal a pap az ételáldozatból emlékeztetőűl, és füstölögtesse el az oltáron, és azután itassa meg az asszonynyal a vizet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'És ha megitatta vele a vizet, akkor lészen, hogy, ha megfertőztette magát, és hűtelenné lett az ő férjéhez, bemegy az az átokhozó víz ő belé az ő keserűségére, és megdagad az ő méhe, és megszárad az ő tompora, és az az asszony átokká lesz az ő népe között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Ha pedig nem fertőztette meg magát az asszony, hanem tiszta: akkor ártatlan, és termékeny lészen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Ez a féltékenységi törvény, mikor elhajol az asszony az ő férje mellől, és megfertőzteti magát;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'Vagy mikor valaki, a kiben felgerjed a féltékenység lelke annyira, hogy féltékenykedik a feleségére; az ő feleségét állatja az Úr elé. És cselekedjék vele a pap mind e törvény szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'És ártatlan lesz a férfi a bűntől, az asszony pedig viseli az ő bűnének terhét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'És szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Szólj Izráel fiainak, és mondd meg nékik: Mikor férfi vagy asszony külön fogadást tesz, nazireusi fogadást, hogy így az Úrnak szentelje magát:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'Bortól és részegítő italtól szakassza el magát; boreczetet és részegítő italból való eczetet ne igyék, és semmi szőlőből csinált italt se igyék, se új, se asszú szőlőt ne egyék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Az ő nazireusságának egész idején át semmit a félét ne igyék, a mi a szőlőtőről kerül, a szőlő magvától fogva a szőlő héjáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Az ő nazireusi fogadásának egész idején, beretva az ő fejét ne járja; míg be nem teljesednek a napok, a melyekre az Úrnak szentelte magát, szent legyen, hagyja növekedni az ő fejének hajfürteit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Az egész időn át, a melyre az Úrnak szentelte magát, megholtnak testéhez be ne menjen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Se atyjának, se anyjának, se fiú- se leánytestvéreinek holttestével meg ne fertőztesse magát, mikor meghalnak, mert az ő Istenének nazireussága van az ő fején.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Az ő nazireusságának egész idejében szent legyen az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Ha pedig meghal valaki ő nála hirtelenséggel, és megfertőzteti az ő nazireus fejét: nyírja meg a fejét az ő tisztulásának napján, a hetedik napon nyírja meg azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'A nyolczadik napon pedig vigyen két gerliczét vagy két galambfiat a papnak a gyülekezet sátorának nyílásához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'És készítse el a pap egyiket bűnért való áldozatul, a másikat pedig egészen égőáldozatul, és szerezzen néki engesztelést, a miért vétkezett a holttest miatt; és szentelje meg annak fejét azon napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'És az ő nazireusságának napjait szentelje újra az Úrnak, és vigyen az ő vétkéért való áldozatul egy esztendős bárányt; az elébbi napok pedig essenek el, mert megfertőztette az ő nazireusságát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Ez pedig a nazireus törvénye: A mely napon betelik az ő nazireusságának ideje, vigyék őt a gyülekezet sátorának nyílásához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'Ő pedig vigye fel az ő áldozatját az Úrnak: egy esztendős, ép hím bárányt egészen égőáldozatul, és egy esztendős, ép nőstény bárányt bűnért való áldozatul, és egy ép kost hálaáldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'Továbbá egy kosár kovásztalan kenyeret, olajjal elegyített lánglisztből való lepényeket, és olajjal megkent kovásztalan pogácsákat, a hozzájok való étel- és italáldozatokkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'És vigye azokat a pap az Úr elé, és készítse el annak bűnéért való áldozatát és egészen égőáldozatát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'A kost is készítse el hálaadó áldozatul az Úrnak, a kosárban lévő kovásztalan kenyerekkel egybe, és készítse el a pap az ahhoz való étel- és italáldozatot is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'A nazireus pedig nyírja meg az ő nazireus fejét a gyülekezet sátorának nyílásánál, és vegye az ő nazireus fejének haját, és tegye azt a tűzre, a mely van a hálaadó áldozat alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Vegye azután a pap a kosnak megfőtt lapoczkáját, és egy kovásztalan lepényt a kosárból, és egy kovásztalan pogácsát, és tegye a nazireus tenyerére, minekutána megnyirta az ő nazireus fejét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'És lóbálja meg a pap azokat áldozatul az Úr előtt; a papnak szenteltetett ez, a meglóbált szegyen és a felemelt lapoczkán felül. Azután igyék bort a nazireus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Ez a nazireus törvénye, a ki fogadást tett, és az ő áldozata az ő nazireusságáért az Úrnak, azonkivül, a mihez módja van. Az ő fogadása szerint, a melyet fogadott, a képen cselekedjék, az ő nazireusságának törvénye szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'És szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'Szólj Áronnak és az ő fiainak, mondván: Így áldjátok meg Izráel fiait, mondván nékik:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Áldjon meg tégedet az Úr, és őrizzen meg tégedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Világosítsa meg az Úr az ő orczáját te rajtad, és könyörüljön te rajtad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Fordítsa az Úr az ő orczáját te reád, és adjon békességet néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Így tegyék az én nevemet Izráel fiaira, hogy én megáldjam őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'És lőn, hogy a mely napon elvégezé Mózes a sátor felállítását, és felkené azt, és megszentelé azt, minden edényével egybe, és az oltárt és annak minden edényét; és felkené és megszentelé azokat:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'Akkor előjövének az Izráel fejedelmei, az ő atyjok házának fejei; ezek a törzsek fejedelmei, és ezek a megszámláltattak felügyelői:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'És vivék az ő áldozatukat az Úr elé: hat borított szekeret, és tizenkét ökröt; egy-egy szekeret két-két fejedelemért, és mindenikért egy-egy ökröt; és odavivék azokat a sátor elébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'És szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'Vedd el ő tőlök, és legyenek azok felhasználva a gyülekezet sátorának szolgálatában; és add azokat a lévitáknak, mindeniknek az ő szolgálata szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Elvevé azért Mózes a szekereket és ökröket, és adá azokat a lévitáknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Két szekeret és négy ökröt ada a Gerson fiainak, az ő szolgálatuk szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'Négy szekeret pedig és nyolcz ökröt ada a Mérári fiainak, az ő szolgálatuk szerint, Ithamárnak, Áron pap fiának keze alá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'A Kéhát fiainak pedig semmit nem ada; mert a szentség szolgálata illette vala őket, a melyet vállon hordoznak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Vivének pedig a fejedelmek az oltár felszentelésére valókat azon napon, a melyen az felkenetett, és vivék a fejedelmek az ő áldozatukat az oltár elébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'És monda az Úr Mózesnek: Egyik napon egyik fejedelem, másik napon másik fejedelem vigye az ő áldozatát az oltár felszentelésére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'És vivé első napon az ő áldozatát Naasson, az Amminádáb fia, Júda nemzetségéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'Vala pedig az ő áldozata, egy ezüst tál, száz és harmincz siklus súlyú, egy ezüst medencze hetven siklus súlyú, a szent siklus szerint, és mind a kettő telve vala olajjal elegyített lisztlánggal, ételáldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'Egy arany csésze, tíz siklus súlyú, füstölő szerekkel telve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'Egy fiatal tulok, egy kos, egy esztendős bárány egészen égőáldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'Egy kecskebak bűnért való áldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'Hálaadó áldozatul pedig két ökör, öt kos, öt kecskebak, öt bárány, esztendősök. Ez Naassonnak, Amminádáb fiának áldozata.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Másodnapon vivé Néthanéel, Suárnak fia, Izsakhár nemzetségének fejedelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Vive az ő áldozatául egy ezüst tálat, száz és harmincz siklus súlyút, egy ezüst medenczét, hetven siklus súlyút, a szent siklus szerint, mind a kettő telve vala olajjal elegyített lisztlánggal, ételáldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'Egy arany csészét, tíz siklus súlyút, füstölő szerekkel telve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'Egy fiatal tulkot, egy kost, egy esztendős bárányt egészen égőáldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'Egy kecskebakot bűnért való áldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'Hálaadó áldozatul pedig két ökröt, öt kost, öt bakot, öt bárányt, esztendősöket. Ez Néthanéelnek a Suár fiának áldozata.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'Harmadik napon a Zebulon fiainak fejedelme: Eliáb, Hélon fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'Az ő áldozata volt egy ezüst tál, száz harmincz siklus súlyú, egy ezüst medencze, hetven siklus súlyú, a szent siklus szerint, mind a kettő telve vala olajjal elegyített lisztlánggal, ételáldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 26, 'Egy arany csésze, tíz siklus súlyú füstölő szerekkel telve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 27, 'Egy fiatal tulok, egy kos, egy esztendős bárány, egészen égőáldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 28, 'Egy kecskebak, bűnért való áldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 29, 'Hálaadó áldozatul pedig két ökör, öt kos, öt bak, öt bárány, esztendősök. Ez Eliábnak, Hélon fiának áldozata.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, 'Negyedik napon a Rúben fiainak fejedelme: Elisúr, Sedeúrnak fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 31, 'Az ő áldozata volt egy ezüst tál, száz harmincz siklus súlyú, egy ezüst medencze, hetven siklus súlyú, a szent siklus szerint, mind a kettő telve vala olajjal elegyített lisztlánggal, ételáldozatul.');
