INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 35, 'Hálaadó áldozatul pedig két ökör, öt kos, öt bak, öt bárány, esztendősök. Ez Elisúrnak, Sedeúr fiának áldozata.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 36, 'Ötödnapon a Simeon fiainak fejedelme: Selúmiel, Surisaddai fia.');
