INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 66, 'Tizedik napon a Dán fiainak fejedelme: Ahiézer, az Ammisaddai fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 67, 'Az ő áldozata volt egy ezüst tál, száz harmincz siklus súlyú, egy ezüst medencze hetven siklus súlyú, a szent siklus szerint, mind a kettő telve vala olajjal elegyített lisztlánggal, ételáldozatul.');
