INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 75, 'Egy fiatal tulok, egy kos, egy esztendős bárány egészen égőáldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 76, 'Egy kecskebak bűnért való áldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 77, 'Hálaadó áldozatul pedig két ökör, öt kos, öt bak, öt bárány, esztendősök. Ez Págielnek, Okrán fiának áldozata.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, 'Tizenkettedik napon a Nafthali fiainak fejedelme: Ahira, Enán fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, 'Az ő áldozata volt egy ezüst tál, száz harmincz siklus súlyú, egy ezüst medencze, hetven siklus súlyú, a szent siklus szerint, mind a kettő telve vala olajjal elegyített lisztlánggal, ételáldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'Egy arany csésze, tíz siklus súlyú, füstölő szerekkel telve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'Egy fiatal tulok, egy kos, egy esztendős bárány egészen égőáldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'Egy kecskebak bűnért való áldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'Hálaadó áldozatul pedig két ökör, öt kos, öt bak, öt bárány, esztendősök. Ez Ahirának, az Enán fiának áldozata.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'Ez volt az áldozat az oltár felszentelésére, a napon, a melyen felkenetett, az Izráelnek fejedelmeitől. Tizenkét ezüst tál, tizenkét ezüst medencze, tizenkét arany csésze.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'Száz és harmincz siklus súlyú vala egy ezüst tál, egy ezüst medencze pedig hetven siklus súlyú; az edények minden ezüstje: kétezer négyszáz siklus, a szent siklus szerint;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'Tizenkét arany csésze, füstölő szerekkel, tíz-tíz siklus súlyú vala egy-egy csésze, a szent siklus szerint: A csészéknek minden aranya: száz húsz siklus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'Az egészen égőáldozatra való minden barom: tizenkét tulok, tizenkét kos, esztendős bárány tizenkettő, a hozzájok való ételáldozatokkal, és tizenkét kecskebak bűnért való áldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'A hálaadó áldozatra való minden barom pedig: huszonnégy tulok, hatvan kos, hatvan bak, esztendős bárány hatvan. Ez volt az oltár felszentelésére való áldozat, minekutána felkenetett volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, 'Mikor pedig bemegy vala Mózes a gyülekezet sátorába, hogy szóljon ő vele, hallja vala annak szavát, a ki szól vala vele a fedél felől, amely van a bizonyság ládáján, a két Kérub közűl; és szól vala vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'És szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, 'Szólj Áronnak és mondd meg néki: Mikor felrakod a mécseket, a gyertyatartó elé világítson a hét mécs.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'És úgy cselekedék Áron, és úgy raká fel mécseit, hogy a gyertyatartónak ellenébe tegyenek világosságot, a miképen parancsolta vala az Úr Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'A gyertyatartó pedig ilyen alkotású: vert aranyból vala mind a szára, mind a virága; vert mű az; ama forma szerint, a melyet mutatott volt az Úr Mózesnek, úgy készíték a gyertyatartót.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'Szóla továbbá az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, 'Vedd a lévitákat Izráel fiai közül, és tisztítsd meg őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'Így cselekedjél pedig velök, hogy megtisztítsad őket: hintsd reájok a tisztulás vizét, és az egész testöket beretválják meg, és mossák meg ruháikat, hogy tiszták legyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'Azután vegyenek egy fiatal tulkot és hozzávaló ételáldozatul olajjal elegyített lisztlángot; egy másik fiatal tulkot pedig vegyenek bűnért való áldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'Akkor vidd a lévitákat a gyülekezet sátora elé, és gyűjtsd egybe Izráel fiainak egész gyülekezetét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'Ezután vidd a lévitákat az Úr elé, és Izráel fiai tegyék kezeiket a lévitákra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'Áron pedig lóbálja meg a lévitákat, áldozatul az Úr előtt, Izráel fiai részéről, hogy szolgáljanak az Úr szolgálatában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'A léviták pedig tegyék kezeiket a tulkok fejére; azután készítsd el az egyiket bűnért való áldozatul, a másikat pedig egészen égőáldozatul az Úrnak, a lévitákért engesztelésül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'És állassad a lévitákat Áron elé, és az ő fiai elé, és lóbáld meg őket áldozatul az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'És válaszd külön a lévitákat Izráel fiai közül, hogy a léviták legyenek az enyéim.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, 'És azután menjenek el a léviták a gyülekezet sátorában való szolgálatra. Így tisztítsd meg őket, és lóbáld meg őket áldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'Mert bizony nékem adattak ők Izráel fiai közül; mind azok helyett, a kik az ő anyjok méhét megnyitják; Izráelnek elsőszülöttei helyett vettem őket magamnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'Mert enyém minden elsőszülött Izráel fiai között, emberből és baromból; a naptól fogva, hogy megöltem minden elsőszülöttet Égyiptom földén, magamnak szenteltem azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'A lévitákat pedig minden elsőszülött helyett vettem magamnak Izráel fiai között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'És odaadtam a lévitákat adományul Áronnak és az ő fiainak Izráel fiai közül, hogy Izráel fiainak tisztében járjanak a gyülekezet sátorában, és hogy engesztelést végezzenek Izráel fiaiért, és ne legyen Izráel fiai között csapás, ha a szenthelyhez közelednek Izráel fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'Úgy cselekedék azért Mózes és Áron, és Izráel fiainak egész gyülekezete a lévitákkal; a mint parancsolt vala az Úr Mózesnek a léviták felől, mindazt úgy cselekedék ő velök Izráel fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'És megtisztíták magokat a léviták, és megmosák ruháikat, és meglóbálá őket Áron áldozatul az Úr előtt, és engesztelést szerze nékik Áron, hogy tisztákká tegye őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'Azután pedig bemenének a léviták, hogy végezzék az ő szolgálatukat a gyülekezetnek sátorában Áron előtt és az ő fiai előtt; a miképen parancsolt vala az Úr Mózesnek a léviták felől, akképen cselekedének velök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'Szóla pedig az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, 'Ez is a lévitákra tartozik: Huszonöt esztendős korától fogva és azon felül, menjen be, hogy szolgálatot teljesítsen a gyülekezet sátorának szolgálatában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'Ötven esztendős korától pedig lépjen ki e szolgálatnak sorából, és ne szolgáljon többé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'Hanem segítse az ő atyafiait a gyülekezet sátorában, hogy azok az ő tisztökben eljárjanak; de szolgálatot ne teljesítsen. E képen cselekedjél a lévitákkal az ő szolgálatukban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'Szóla pedig az Úr Mózesnek, a Sinai pusztájában, az Égyiptom földéből való kijövetelöknek második esztendejében, az első hónapban, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, 'Izráel fiai pedig készítsék el a páskhát a maga idejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'E hónapnak tizennegyedik napján, estennen készítsék el azt a maga idejében. Minden ő rendtartása szerint, és minden ő szertartása szerint készítsétek el azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, 'Szóla azért Mózes Izráel fiainak, hogy készítsék el a páskhát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'És elkészíték a páskhát az első hónapban, a hónapnak tizennegyedik napján estennen, a Sinai pusztájában; mindent úgy cselekedének Izráel fiai, a mint az Úr parancsolta vala Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'Valának pedig némelyek, a kik tisztátalanok valának holtember illetése miatt, és nem készítheték meg a páskhát azon a napon: járulának azért Mózes elé és Áron elé azon a napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'És mondának azok az emberek néki: Mi tisztátalanok vagyunk holtember illetése miatt; miért tiltatunk meg, hogy ne vigyünk áldozatot az Úrnak a maga idejében Izráel fiai között?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'És monda nékik Mózes: Legyetek veszteg, míglen megértem: mit parancsol az Úr ti felőletek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'Szóla pedig az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, 'Szólj Izráel fiainak, mondván: Ha valaki holtember illetése miatt tisztátalan, vagy messze úton leend közületek, vagy a ti utódaitok közül, mindazáltal készítsen páskhát az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'A második hónapnak tizennegyedik napján, estennen, készítsék el azt; kovásztalan kenyérrel és keserű füvekkel egyék meg azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'Ne hagyjanak meg abból semmit reggelig, és annak csontját meg ne törjék; a páskhának minden rendtartása szerint készítsék el azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'A mely ember pedig tiszta, vagy nincs útban, és elmulasztja a páskhát elkészíteni: irtassék ki az ilyen az ő népe közül; mert az Úrnak áldozatát nem vitte fel annak idejében; viselje az ilyen ember az ő bűnének terhét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'Hogyha pedig jövevény tartózkodik köztetek, és páskhát készít az Úrnak, a páskhának rendtartása szerint és annak szertartásai szerint készítse azt; egy rendtartástok legyen néktek, mind a jövevénynek, mind a föld lakosának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, 'A hajlék felállításának napján pedig befedezé a felhő a hajlékot, a bizonyság sátorát; és estve a hajlék felett vala, tűznek ábrázatjában reggelig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'Úgy vala szüntelen: A felhő borítja vala azt; és tűznek ábrázatja éjjel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'Mihelyt pedig felszáll vala a felhő a sátorról, azonnal elindulnak vala Izráel fiai; és azon a helyen, a hol a felhő megáll vala, ott ütnek vala tábort Izráel fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'Az Úr szava szerint mennek vala Izráel fiai, és az Úr szava szerint táboroznak vala; mind addig, míg a felhő áll vala a hajlékon, táborban maradnak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'Még ha a felhő sok napig nyugszik vala a hajlékon, akkor is megtartják vala Izráel fiai az Úr rendelését, és nem indulának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'Megesék, hogy a felhő kevés napon át lőn a hajlékon: akkor is az Úr szava szerint maradnak vala táborban, és az Úr szava szerint indulnak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'Megesék, hogy a felhő estvétől fogva ott lőn reggelig; mikor azért reggel a felhő felszáll vala, akkor indulnak vala el; vagy egy nap és egy éjjel lőn ott; mikor azért a felhő felszáll vala, ők is indulának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'Vagy két napig, vagy egy hónapig, vagy hosszabb ideig lőn ott; a meddig késik vala a felhő a hajlékon, vesztegelvén azon, táborban maradnak vala Izráel fiai is, és nem indulnak vala tovább; mikor pedig az felszáll vala, ők is indulnak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'Az Úr szava szerint járnak vala tábort, és az Úr szava szerint indulnak vala. Az Úrnak rendelését megtartják vala, az Úrnak Mózes által való szava szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'Ismét szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, 'Csináltass magadnak két kürtöt, vert ezüstből csináltasd azokat, és legyenek azok néked a gyülekezet összegyűjtésére, és a táborok megindítására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'És mikor megfújják azokat, gyüljön te hozzád az egész gyülekezet, a gyülekezet sátorának nyílása elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'Ha csak egyet fújnak meg, akkor gyűljenek hozzád a fejedelmek, Izráel ezereinek fejei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'Ha pedig riadót fújtok, akkor induljon azok tábora, a kik napkelet felől táboroznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'Mikor pedig másodszor fújtok riadót, akkor induljon azok tábora, a kik dél felől táboroznak. Riadót fújjanak azok indulására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'Mikor pedig összegyűjtitek a gyülekezetet, egyszerűen kürtöljetek, és ne fújjatok riadót.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'A kürtöket pedig Áron fiai, a papok fújják; és legyen ez néktek örökkévaló rendtartás a ti nemzetségeitek között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'És mikor viadalra mentek a ti földetekben, a titeket háborító ellenségetek ellen, akkor is azokkal a kürtökkel fújjatok riadót, és emlékezetben lesztek az Úr előtt, a ti Istenetek előtt, és megszabadultok a ti ellenségeitektől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'A ti vígasságtoknak napján, és a ti ünnepeiteken, és a ti hónapjaitok kezdetén is fújjátok meg a kürtöket, a ti egészen égőáldozataitokra, és a ti hálaáldozatitokra: és lesznek néktek emlékeztetőül a ti Istenetek előtt. Én vagyok az Úr, a ti Istenetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, 'Vala pedig a második esztendőben a második hónapban, a hónapnak huszadik napján, felszálla a felhő a bizonyság hajlékáról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'És elindulának Izráel fiai az ő menésöknek rendje szerint a Sinai pusztájából; és megállapodék a felhő Párán pusztájában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'Elindulának azért először az Úrnak Mózes által való parancsolatja szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'Elindula pedig először a Júda fiai táborának zászlója az ő seregei szerint; és az ő seregének feje vala Naasson, az Amminádáb fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'Az Izsakhár fiai törzséből való seregnek feje pedig Néthanéel vala, Suárnak fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'És a Zebulon fiai törzséből való seregnek feje vala Eliáb, Hélonnak fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'És elbontatván a hajlék, elindulának Gersonnak és Mérárinak fiai, a hajlék hordozói.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'Azután indula a Rúben táborának zászlója az ő seregeik szerint, és az ő seregének feje vala Elisur, Sedeúrnak fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'A Simeon fiai törzséből való seregnek pedig feje vala Selúmiel, Surisaddainak fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'És a Gád fiai törzséből való seregnek feje vala Eliásáf, Dehuélnek fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'Elindulának a Kéhátiták is, a szentség hordozói, és amazok felállíták vala a hajlékot, míg ezek oda jutnak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'Azután elindula az Efraim fiai táborának zászlója az ő seregei szerint, és az ő seregének feje vala Elisáma, Ammihúdnak fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'A Manasse fiai törzséből való seregnek feje vala Gámliél, Pédasúrnak fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'A Benjámin fiai törzséből való seregnek feje vala Abidán, Gideóninak fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'Utolszor indula el a Dán fiai táborának zászlója, mint az egész tábornak utócsapata az ő seregei szerint; és az ő seregének feje vala Ahiézer, az Ammisaddai fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'Az Áser fiai törzséből való seregnek pedig feje vala Págiel, Okhránnak fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'És a Nafthali fiai törzséből való seregnek feje vala Akhira, az Enán fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'Ilyen vala Izráel fiainak menetele az ő seregeik szerint: ekképen mentek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'Monda pedig Mózes Hóbábnak, a ki fia vala a Midiánból való Reuélnek, a Mózes ipának: Arra a helyre indulunk mi, a mely felől azt mondta vala az Úr: néktek adom. Jer el velünk, és jól teszünk veled, mert az Úr jót igért Izráelnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, 'Az pedig felele néki: Nem megyek, hanem az én földemre és az én rokonaim közé megyek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, 'És monda Mózes: Kérlek, ne hagyj el minket: mert te tudod, hol kell megszállanunk e pusztában, és légy nékünk szemünk gyanánt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'És ha eljösz velünk, a mi jót cselekszik velünk az Úr, közöljük azt veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'Elmenének azért az Úr hegyétől háromnapi járásnyira, és az Úr szövetségének ládája megyen vala ő előttök háromnapi járásnyira, hogy kiszemelje nékik: hol kelljen megszállaniok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'És az Úr felhője vala ő rajtok nappal, mikor elindulának a táborból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'Mikor pedig el akarták indítani a ládát, ezt mondja vala Mózes: Kelj fel Uram, és széledjenek el a te ellenségeid, és fussanak el előled a te gyűlölőid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'Mikor pedig megáll vala, ezt mondja vala: Fordulj vissza Uram Izráelnek tízezerszer való ezereihez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, 'És lőn, hogy panaszolkodék a nép az Úr hallására, hogy rosszul van dolga. És meghallá az Úr, és haragra gerjede, és felgyullada ellenök az Úrnak tüze és megemészté a tábornak szélét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'Kiálta azért a nép Mózeshez, és könyörge Mózes az Úrnak, és megszünék a tűz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'És nevezé azt a helyet Thaberának; mert felgyulladt vala ellenök az Úrnak tüze.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, 'De a gyülevész nép, a mely köztök vala, kívánságba esék, és Izráel fiai is újra síránkozni kezdének, és mondának: Kicsoda ád nékünk húst ennünk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'Visszaemlékezünk a halakra, a melyeket ettünk Égyiptomban ingyen, az ugorkákra és dinnyékre, a párhagymákra, vereshagymákra és a foghagymákra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'Most pedig a mi lelkünk eleped, mindennek híjával lévén; szemünk előtt nincs egyéb mint manna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, '(A manna pedig olyan vala mint a kóriándrum magva, a színe pedig mint a bdelliomnak színe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'Kiomol vala pedig a nép, és szedik vala a mannát, és őrlik vala kézimalmokban, vagy megtörik vala mozsárban, és megfőzik vala fazékban, és csinálnak vala abból pogácsákat: az íze pedig olyan vala, mint az olajos kalácsé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'Mikor pedig a harmat leszáll vala a táborra éjjel, a manna is mindjárt leszáll vala arra.)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'És meghallá Mózes, hogy sír a nép, az ő nemzetsége szerint, kiki az ő sátorának nyílása előtt; és igen felgerjede az Úr haragja, és nem tetszék az Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'És monda Mózes az Úrnak: Miért nyomorítád meg a te szolgádat? és miért nem találék kegyelmet a te szemeid előtt, hogy ez egész népnek terhét én reám vetéd?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'Avagy tőlem fogantatott-e mind ez egész nép? avagy én szűltem-e őt, hogy azt mondod nékem: Hordozd őt a te kebleden, a miképen hordozza a dajka a csecsemőt, arra a földre, a mely felől megesküdtél az ő atyáinak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'Hol vegyek én húst, hogy adjam azt mind ez egész népnek? mert reám sírnak, mondván: Adj nékünk húst, hadd együnk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'Nem viselhetem én magam mind ez egész népet; mert erőm felett van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'Ha így cselekszel velem, kérlek ölj meg engemet, ölj meg ha kedves vagyok előtted, hogy ne lássam az én nyomorúságomat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'Monda azért az Úr Mózesnek: Gyűjts egybe nékem hetven férfiút Izráel vénei közül, a kikről tudod, hogy vénei a népnek és annak előljárói, és vidd őket a gyülekezet sátorához, és álljanak ott veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'Akkor alá szállok, és szólok ott veled, és elszakasztok abból a lélekből, a mely te benned van, és teszem ő beléjök, hogy viseljék te veled a népnek terhét, és ne viseljed te magad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'A népnek pedig mondd meg: Készítsétek el magatokat holnapra, és húst esztek; mert sírtatok az Úr hallására, mondván: Kicsoda ád nékünk húst ennünk? mert jobban vala nékünk dolgunk Égyiptomban. Azért az Úr ád néktek húst és enni fogtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'Nem csak egy napon esztek, sem két napon, sem öt napon, sem tíz napon, sem húsz napon;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, 'Hanem egy egész hónapig, míglen kijön az orrotokon, és útálatossá lesz előttetek; mivelhogy megvetettétek az Urat, a ki közöttetek van; és sírtatok ő előtte mondván: Miért jöttünk ide ki Égyiptomból?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, 'És monda Mózes: Hatszáz ezer gyalogos e nép, a mely között én vagyok, és te azt mondod: Húst adok nékik, és esznek egy egész hónapig?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'Nemde juhok és ökrök vágattatnak-é nékik, hogy elég legyen nékik? vagy a tengernek minden hala összegyűjtetik-é nékik, hogy elég legyen nékik?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'Akkor monda az Úr Mózesnek: Avagy megrövidült-é az Úrnak keze? Majd meglátod: beteljesedik-é néked az én beszédem vagy nem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'Kiméne azért Mózes, és elmondá a népnek az Úr beszédét, és összegyűjte hetven férfiút a nép vénei közül, és állatá őket a sátor körül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'Akkor leszálla az Úr felhőben, és szóla néki, és elszakaszta abból a lélekből, a mely vala ő benne, és adá a hetven vén férfiúba. Mihelyt pedig megnyugovék ő rajtok a lélek, menten prófétálának, de nem többé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'Két férfiú azonban elmaradt vala a táborban; egyiknek neve Eldád, a másiknak neve Médád, és ezeken is megnyugodott vala a lélek; mert azok is az összeírottak közül valók, de nem mentek vala el a sátorhoz, és mégis prófétálának a táborban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'Elfutamodék azért egy ifjú, és megjelenté Mózesnek, és monda: Eldád és Médád prófétálnak a táborban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'Akkor felele Józsué, a Nún fia, Mózes szolgája, az ő választottai közül való, és monda: Uram, Mózes, tiltsd meg őket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'És felele néki Mózes: Avagy érettem buzgólkodol-é? Vajha az Úrnak minden népe próféta volna, hogy adná az Úr az ő lelkét ő beléjök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'Ezután visszatére Mózes a táborba, ő és az Izráel vénei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'És szél jöve ki az Úrtól, és hoza fürjeket a tengertől, és bocsátá a táborra egynapi járásnyira egy felől, és egynapi járásnyira más felől a tábor körül, és mintegy két sing magasságnyira a földnek színén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'Akkor felkele a nép és azon az egész napon, és egész éjjel, és az egész következő napon gyűjtének magoknak fürjeket, a ki keveset gyűjtött is, gyűjtött tíz hómert, és kiteregeték azokat magoknak a tábor körül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, 'A hús még foguk között vala, és meg sem emésztették vala, a mikor az Úrnak haragja felgerjede a népre és megveré az Úr a népet igen nagy csapással.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'És elnevezék azt a helyet Kibrot-thaavának: mert ott temeték el a mohó népet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, 'Kibrot-thaavától elméne a nép Haseróthba; és ott valának Haseróthban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'Miriám pedig és Áron szólának Mózes ellen a kúsita asszony miatt, a kit feleségül vőn, mert kúsita asszonyt vett vala feleségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, 'És mondának: Avagy csak Mózes által szólott-é az Úr? avagy nem szólott-é mi általunk is? És meghallá az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, '(Az az ember pedig, Mózes, igen szelíd vala, minden embernél inkább, a kik e föld színén vannak.)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'Mindjárt monda azért az Úr Mózesnak, Áronnak és Miriámnak: Menjetek ki ti hárman a gyülekezetnek sátorába; és kimenének ők hárman.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'Akkor leszálla az Úr felhőnek oszlopában, és megálla a sátornak nyílásánál; és szólítá Áront és Miriámot, és kimenének mindketten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'És monda: Halljátok meg most az én beszédeimet: Ha valaki az Úr prófétája közöttetek, én megjelenek annak látásban, vagy álomban szólok azzal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'Nem így az én szolgámmal, Mózessel, a ki az én egész házamban hív.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'Szemtől szembe szólok ő vele, és nyilvánvaló látásban; nem homályos beszédek által, hanem az Úrnak hasonlatosságát látja. Miért nem féltetek hát szólani az én szolgám ellen, Mózes ellen?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'És felgyullada az Úr haragja ő reájok, és elméne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'És a felhő is eltávozék a sátor felül, és ímé Miriám poklos vala, fejér mint a hó; és rátekinte Áron Miriámra, és ímé poklos vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'Monda azért Áron Mózesnek: Kérlek Uram, ne tulajdonítsad nékünk e bűnt; mert bolondul cselekedtünk és vétkeztünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'Kérlek, ne legyen olyan Miriám mint a holt, a melynek húsa félig megemésztetik, mikor kijő az ő anyjának méhéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'Kiálta azért Mózes az Úrhoz, mondván: Isten, kérlek, gyógyítsd meg őt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'Az Úr pedig monda Mózesnek: Ha csak az atyja pökött volna is az ő orczájára, avagy nem kellene-é szégyenkeznie hetednapig? Rekesztessék ki hét napig a táboron kívül, és azután hívassék vissza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'Kirekeszteték azért Miriám a táboron kivül hét napig. És a nép nem indula tovább, míg vissza nem hívaték Miriám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'Azután pedig elindula a nép Haseróthból, és tábort ütének Párán pusztájában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, 'És szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'Küldj férfiakat, hogy kémleljék meg a Kanaán földét, a melyet én adok Izráel fiainak; az ő atyáiknak mindenik törzséből egy-egy férfiút küldjetek, mind olyat, a ki főember közöttök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'Elküldé azért őket Mózes Párán pusztájából az Úr rendelése szerint; és azok a férfiak mindnyájan főemberek valának Izráel fiai között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'Ezek pedig azoknak nevei: A Rúben nemzetségéből Sámmua, a Zakhúr fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'A Simeon nemzetségéből Safát, a Hóri fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'A Júda nemzetségéből Káleb, a Jefunné fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'Az Izsakhár nemzetségéből Igál, a József fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'Az Efraim nemzetségéből Hósea, a Nún fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'A Benjámin nemzetségéből Pálthi, a Rafú fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'A Zebulon nemzetségéből Gaddiel, a Szódi fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'A József nemzetségéből, a Manasse nemzetségéből Gaddi, a Szúszi fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'A Dán nemzetségéből Ammiél, a Gemálli fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'Az Áser nemzetségéből Szenthúr, a Mikaél fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'A Nafthali nemzetségéből Nahbi, a Vofszi fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, 'A Gád nemzetségéből Géuel, a Mákhi fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'Ezek ama férfiaknak nevei, a kiket elküldött Mózes a földnek megkémlelésére. És nevezé Mózes Hóseát, a Nún fiát Józsuénak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'És mikor elküldé őket Mózes a Kanaán földének megkémlelésére, monda nékik: Menjetek fel erre dél felől, és hágjatok fel a hegyre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'És nézzétek meg a földet, hogy milyen az; és a népet, a mely lakozik azon: erős-é az vagy erőtlen, kevés-é az vagy sok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'És milyen a föld, a melyben lakozik az: jó-é az vagy hitvány; és milyenek a városok, a melyekben lakozik: táborokban vagy erősségekben lakozik-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'És milyen a föld: kövér-é az, vagy sovány; van-é abban élőfa vagy nincs? És legyetek bátorságosok, és szakaszszatok a földnek gyümölcséből. Azok a napok pedig a szőlőzsendülés napjai valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'Felmenének azért, és megkémlelék a földet a Czin pusztájától fogva mind Rehóbig, odáig, a hol Hamáthba mennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'És felmenének dél felől, és jutának Hebronig; valának pedig ott Ahimán, Sésai és Thalmai, az Anák fiai: (Hebron pedig hét esztendővel építtetett elébb, mint az égyiptomi Czoán).');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'Mikor pedig eljutának Eskol völgyéig, lemetszének ott egy szőlővesszőt egy szőlőfürttel, és ketten vivék azt rúdon; és a gránátalmákból és a figékből is szakasztának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'Azt a helyet elnevezék Eskol völgyének; a szőlőfürtért, a melyet lemetszettek vala onnét Izráel fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'És visszatérének a föld megkémleléséből negyven nap mulva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, 'És menének, és jutának Mózeshez és Áronhoz, és Izráel fiainak egész gyülekezetéhez, Párán pusztájába, Kádesbe; és hírt vivének nékik és az egész gyülekezetnek, és megmutaták nékik a földnek gyümölcsét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'Így beszélének néki, és ezt mondák: Elmentünk vala arra a földre, a melyre küldöttél vala minket, és bizonyára tejjel és mézzel folyó az, és ez annak gyümölcse!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'Csakhogy erős az a nép, a mely lakja azt a földet, és a városok erősítve vannak, és felette nagyok; sőt még Anák fiait is láttuk ott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'Amálek lakik a dél felől való földön, és Khitteus, Jebuzeus és Emoreus lakik a hegyeken; a tenger mellett, és a Jordán partján pedig Kananeus lakik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'És jóllehet Káleb csendesíté a Mózes ellen háborgó népet, és azt mondja vala: Bátran felmehetünk, és elfoglalhatjuk azt a földet, mert kétség nélkül megbírunk azzal;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'Mindazáltal a férfiak, a kik felmentek vala vele, azt mondják vala: Nem mehetünk fel az ellen a nép ellen, mert erősebb az nálunknál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'És rossz hírét vivék annak a földnek, a melyet megkémleltek volt, Izráel fiaihoz, mondván: Az a föld, a melyen általmentünk, hogy megkémleljük azt, olyan föld, a mely megemészti az ő lakóit; az egész nép is, a melyet láttunk azon, szálas emberekből áll.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 34, 'És láttunk ott óriásokat is, az óriások közül való Anáknak fiait, és olyanok valánk a magunk szemében, mint a sáskák, és az ő szemeikben is olyanok valánk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'És felemelé szavát az egész gyülekezet, és síra a nép azon az éjszakán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'És mindnyájan zúgolódának Mózes ellen és Áron ellen Izráel fiai, és monda nékik az egész gyülekezet: Vajha megholtunk volna Égyiptom földén! vagy ebben a pusztában vajha meghalnánk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'Miért is visz be minket az Úr arra a földre? hogy fegyver miatt hulljunk el? feleségeink és a kicsinyeink prédára legyenek? Nem jobb volna-é nékünk visszatérnünk Égyiptomba?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'És mondának egymásnak: Szerezzünk előttünk járót, és térjünk vissza Égyiptomba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Akkor arczczal leborulának Mózes és Áron Izráel fiai gyülekezetének egész községe előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'Józsué pedig, a Nún fia, és Káleb, a Jefunné fia, a kik a földnek kémlelői közül valók valának, meghasogaták ruháikat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'És szólának Izráel fiai egész gyülekezetének, mondván: A föld, a melyen általmentünk, hogy megkémleljük azt, igen-igen jó föld.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'Ha az Úrnak kedve telik bennünk, akkor bevisz minket arra a földre, és nékünk adja azt, mely tejjel és mézzel folyó föld.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'Csakhogy ne lázongjatok az Úr ellen, se ne féljetek annak a földnek népétől; mert ők nekünk csak olyanok, mint a kenyér; eltávozott tőlök az ő oltalmok, de az Úr velünk van: ne féljetek tőlök!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'Mikor pedig az egész gyülekezet azon tanakodék, hogy megkövezze őket: megjelenék az Úrnak dicsősége a gyülekezet sátorában Izráel minden fiának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'És monda az Úr Mózesnek: Meddig gyaláz engemet ez a nép? Meddig nem hisznek nékem, mind ama csudatételeim mellett sem, a melyeket cselekedtem közöttök?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'Megverem őket döghalállal, és elvesztem őket; téged pedig nagy néppé teszlek, és ő nálánál erősebbé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'És monda Mózes az Úrnak: Ha meghallják az égyiptombeliek (mert közülök hoztad fel e népet a te hatalmad által):');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'Elmondják majd e föld lakosainak, a kik hallották, hogy te Uram e nép között vagy, hogy szemtől szembe megjelentetted magadat te Uram, és hogy a te felhőd megállott ő rajtok, és felhőoszlopban jársz te ő előttök nappal, éjjel pedig tűzoszlopban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'Hogyha mind egyig elveszted e népet, így szólanak majd e népek, a melyek hallották a te híredet, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, 'Mivelhogy nem vihette be az Úr e népet a földre, a mely felől megesküdött nékik, azért öldöste le őket a pusztában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'Most azért hadd magasztaltassék fel az Úrnak ereje, a miképen szólottál, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, 'Az Úr késedelmes a haragra, nagy irgalmasságú, megbocsát hamisságot és vétket, de a bűnöst nem hagyja büntetlenül; megbünteti az atyák álnokságait a fiakban harmad és negyed íziglen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'Kérlek, kegyelmezz meg e nép hamisságának a te irgalmasságod nagy volta szerint, a miképen megbocsátottál e népnek Égyiptomtól fogva mind eddig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'És monda az Úr: Megkegyelmeztem a te beszéded szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'De bizonnyal élek én, és betölti az Úr dicsősége az egész földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'Hogy mindazok az emberek, a kik látták az én dicsőségemet és csudáimat, a melyeket cselekedtem Égyiptomban és e pusztában, és megkisértettek engemet immár tízszer, és nem engedtek az én szómnak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'Nem látják meg azt a földet, a mely felől megesküdtem az ő atyáiknak; senki nem látja azt azok közöl, a kik gyaláztak engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'De az én szolgámat, Kálebet, mivelhogy más lélek volt vele, és tökéletességgel követett engem, beviszem őt arra a földre, a melyre bement vala, és örökségül bírja azt az ő magva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, 'De Amálek és Kananeus lakik a völgyben; holnap forduljatok meg, és induljatok a pusztába, a veres tenger útján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'Szóla annakfelette az Úr Mózesnek és Áronnak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, 'Meddig tűrjek e gonosz gyülekezetnek, a mely zúgolódik ellenem? Hallottam Izráel fiainak zúgolódásait, a kik zúgolódnak ellenem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'Mondd meg nékik: Élek én, azt mondja az Úr, hogy épen úgy cselekszem veletek, a miképen szólottatok az én füleim hallására!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'E pusztában hullanak el a ti holttesteitek, és pedig mindazok, a kik megszámláltattak a ti teljes számotok szerint, húsz esztendőstől fogva és azon felül, a kik zúgolódtatok ellenem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'És nem mentek be arra a földre, a melyre nézve felemeltem az én kezemet, hogy lakosokká teszlek abban titeket; Kálebet, a Jefunné fiát és Józsuét, a Nún fiát kivéve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'De kicsinyeiteket, a kik felől azt mondtátok, hogy prédára lesznek; őket beviszem, és megismerik azt a földet, a melyet megútáltatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'A ti holttesteitek azért a pusztában hullanak el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'A ti fiaitok pedig, mint a pásztorok, bujdosnak e pusztában negyven esztendeig, és viselik a ti paráználkodásitoknak büntetését, míglen megemésztetnek a ti holttesteitek e pusztában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'A napok száma szerint, a melyeken megkémleltétek a földet, (tudniillik negyven napon, egy-egy napért egy-egy esztendő), negyven esztendeig hordozzátok a ti hamisságotoknak büntetését, és megismeritek az én elfordulásomat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'Én, az Úr, szólottam. Bizonyára ezt mívelem az egész gonosz gyülekezettel, a mely összegyülekezett vala ellenem; ebben a pusztában emésztetnek meg, és ugyanott halnak meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'A férfiak azért, a kiket elküldött vala Mózes a földnek megkémlelésére, és visszatérének és felzúdíták ellene az egész gyülekezetet, rossz hírt terjesztvén arról a földről:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'Azok a férfiak azért, a kik rossz hírt terjesztének a földről, meghalának az Úr előtt csapás által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'Csak Józsué, a Nún fia, és Káleb, a Jefunné fia, maradának életben ama férfiak közül, a kik mentek vala a földet megkémlelni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'A mint pedig elbeszélé Mózes e beszédeket Izráel fiainak, a nép felette igen keserge.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'És felkelének reggel, és felmenének a hegy tetejére, mondván: Ímé készek vagyunk elmenni a helyre, a melyről szólott az Úr, mert vétkeztünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'És monda Mózes: Miért hágjátok át ilyen módon az Úr akaratát, holott nem sikerülhet az néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'Fel ne menjetek, mert nem lesz közöttetek az Úr, hogy el ne hulljatok a ti ellenségeitek előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'Mert az Amálek és a Kananeus van ott előttetek, és fegyver által hulltok el. Mivelhogy elfordultatok az Úrtól, nem is lesz az Úr veletek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'Mindazáltal merészkedének felmenni a hegy tetejére; de az Úr szövetségének ládája és Mózes meg sem mozdulának a táborból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'Alászálla azért az Amálek és a Kananeus, a ki lakik vala azon a hegyen, és megverék őket, és vágák őket mind Hormáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'Szóla pedig az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, 'Szólj Izráel fiainak, és mondd nékik: Mikor bementek a ti lakó földetekre, a melyet én adok néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'És tűzáldozatot akartok készíteni az Úrnak, egészen égő- vagy véres áldozatot, vagy fogadás teljesítése végett, vagy szabadakarat szerint, vagy a ti ünnepiteken, hogy tulok- vagy juhféléből kedves illatot készítsetek az Úrnak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'Akkor, a ki áldozza az ő áldozatját, vigyen az Úrnak ételáldozatul egy tizedrész efa lisztlángot, egy negyedrész hin olajjal elegyítve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'Italáldozatul pedig egy negyedrész hin bort adj az egészen égő- vagy véres áldozathoz egy-egy bárány mellé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'Vagy ha kossal áldozol, készíts ételáldozatul két tizedrész efa lisztlángot megelegyítve egy hin olajnak harmadrészével;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'Italáldozatul pedig egy hin bornak harmadrészét. Így viszel az Úrnak jóillatú áldozatot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'Hogyha fiatal tulkot akarsz készíteni egészen égő- vagy véres áldozatul fogadás teljesítése végett, vagy hálaáldozatul az Úrnak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'Akkor vígy a fiatal tulokkal egyetemben ételáldozatul három tizedrész efa lisztlángot, megelegyítve egy hin olajnak felével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'Italáldozatul pedig vigy fel fél hin bort; kedves illatú tűzáldozat ez az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'Eképpen cselekedjetek mindenik ökörnél, mindenik kosnál, mind a juhoknak, mind a kecskéknek bárányainál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'A barmok száma szerint, a melyeket áldozatra készítetek: így cselekedjetek mindenikkel, az ő számok szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Minden benszülött így cselekedjék ezekkel, hogy kedves illatú tűzáldozatot vigyen az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'Ha pedig jövevény tartózkodik nálatok, vagy lesz köztetek a ti nemzetségeitek szerint, és kedves illatú tűzáldozatot készít az Úrnak: a miképen ti cselekesztek, a képen cselekedjék az is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'Óh, község! néktek és a köztetek lakozó jövevénynek egy rendtartástok legyen; örökkévaló törvény legyen a ti nemzetségeiteknél, hogy az Úr előtt olyan legyen a jövevény, mint ti.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'Egy törvényetek legyen, és egy szabályotok néktek és a jövevénynek, a mely közöttetek lakik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'Szóla azután az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, 'Szólj Izráel fiainak, és mondd meg nékik: Mikor bementek a földre, a melyre én viszlek be titeket:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'Akkor, ha majd esztek a földnek kenyeréből, adjatok felemelt áldozatot az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'A ti tésztátok zsengéjét lepényként mutassátok fel áldozatul; mint a szérűről felemelt áldozatot, úgy mutassátok fel azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'A ti tésztátok zsengéjéből adjatok az Úrnak felemelt áldozatot, a ti nemzetségeitek szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, 'És ha megtévelyedtek, és nem cselekszitek meg mind e parancsolatokat, a melyeket szólott vala az Úr Mózesnek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'Mind azokat, a melyeket parancsolt az Úr néktek Mózes által, az naptól fogva, a melyen parancsolta azokat az Úr, és azután a ti nemzetségeiteknek is:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'Akkor, hogyha a gyülekezet tudtán kivül esik a tévedés, az egész gyülekezet áldozzék egy fiatal tulkot egészen égőáldozatul, kedves illatul az Úrnak, és étel- és italáldozatot is hozzá szokás szerint, és egy kecskebakot bűnért való áldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'És végezzen engesztelést a pap Izráel fiainak egész gyülekezetéért, és megbocsáttatik nékik, mert tévedés volt az; ők pedig vigyék be az ő áldozatjokat tűzáldozatul az Úrnak, és a bűnért való áldozatjokat az Úr elé az ő tévedésökért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'És megbocsáttatik Izráel fiai egész gyülekezetének, és a közöttök tartózkodó jövevénynek; mert az egész nép tévedésben volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'Hogyha csak egy ember vétkezik tévedésből: áldozzék egy esztendős kecskét bűnért való áldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'A pap végezzen engesztelést azért a tévedő emberért, a ki tévedésből vétkezett az Úr előtt, és ha engesztelést szerez néki, megbocsáttatik néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'A benszülöttnek Izráel fiai között és a jövevénynek, a ki közöttök tartózkodik: egy törvényetek legyen néktek a felől, a ki tévedésből cselekszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'De a mely ember felemelt kézzel cselekszik, akár benszülött akár jövevény, az Urat illeti az szidalommal, vágassék ki azért az az ő népe közül;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'Mivelhogy az Úrnak szavát megvetette, és az ő parancsolatját megszegte, kiirtatván kiirtassék az az ember, az ő hamissága legyen ő rajta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'Mikor pedig Izráel fiai a pusztában valának, találának egy férfiat, ki fát szedeget vala szombatnapon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'És elvivék azt, a kik találták vala azt fát szedegetni, Mózeshez és Áronhoz és az egész gyülekezethez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'És őrizet alá adák azt, mert nem vala kijelentve, mit kelljen vele cselekedni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, 'És monda az Úr Mózesnek: Halállal lakoljon az a férfi, kövezze őt agyon az egész gyülekezet a táboron kivül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'Kivivé azért őt az egész gyülekezet a táboron kivül, és agyon kövezék őt, és meghala, a miképen parancsolta vala az Úr Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'És szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, 'Szólj Izráel fiainak, és mondjad nékik, hogy készítsenek magoknak bojtokat az ő ruháik szegleteire az ő nemzetségeik szerint, és tegyenek a szeglet bojtjára kék zsinórt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'És arra való legyen néktek a bojt, hogy mikor látjátok azt, megemlékezzetek az Úrnak minden parancsolatjáról, hogy megcselekedjétek azokat; és ne nézzetek a ti szívetek után, és a ti szemeitek után, a melyek után ti paráználkodtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'Hogy megemlegessétek, és megcselekedjétek minden én parancsolatomat, és legyetek szentek a ti Istenetek előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'Én vagyok az Úr, a ti Istenetek, a ki kihoztalak titeket Égyiptom földéből, hogy legyek néktek Istenetekké. Én vagyok az Úr, a ti Istenetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'Kóré pedig az Iczhár fia, a ki a Lévi fiának, Kéhátnak fia vala; és Dáthán és Abirám, Eliábnak fiai; és On, a Péleth fia, a kik Rúben fiai valának, fogták magokat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'És támadának Mózes ellen, és velök Izráel fiai közül kétszáz és ötven ember, a kik a gyülekezetnek fejedelmei valának, tanácsbeli híres neves emberek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'És gyülekezének Mózes ellen és Áron ellen, és mondának nékik: Sokat tulajdonítotok magatoknak, holott az egész gyülekezet, ezek mindnyájan szentek, és közöttök van az Úr: miért emelitek azért fel magatokat az Úr gyülekezete fölé?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'És mikor hallá ezt Mózes, arczra borula,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'És szóla Kórénak és az ő egész gyülekezetének, mondván: Reggel megmutatja az Úr: ki az övé és ki a szent, és kit fogadott magához; mert a kit magának választott, magához fogadja azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'Ezt cselekedjétek azért: Vegyetek magatoknak temjénezőket, Kóré és az ő egész gyülekezete!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'És tegyetek azokba tüzet, és rakjatok rá füstölő szert az Úr előtt holnap, és az a férfiú legyen szent, a kit kiválaszt az Úr. Sokat tulajdonítotok magatoknak, Lévi fiai!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'És monda Mózes Kórénak: Halljátok meg, kérlek, Lévi fiai:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'Avagy keveslitek-é azt, hogy titeket Izráel Istene külön választott Izráel gyülekezetétől, hogy magához fogadjon titeket, hogy szolgáljatok az Úr sátorának szolgálatában, hogy álljatok e gyülekezet előtt, és szolgáljatok néki?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'És hogy magának fogadott tégedet, és minden atyádfiát, a Lévi fiait te veled; hanem még a papságot is kivánjátok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'Azért hát te és a te egész gyülekezeted az Úr ellen gyülekeztetek össze; mert Áron micsoda, hogy ő ellene zúgolódtok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'Elkülde azután Mózes, hogy hívják elő Dáthánt és Abirámot, az Eliáb fiait. Azok pedig felelének: Nem megyünk fel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'Avagy kevesled-é azt, hogy felhozál minket a tejjel és mézzel folyó földről, hogy megölj minket a pusztában; hanem még uralkodni is akarsz rajtunk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'Éppen nem tejjel és mézzel folyó földre hoztál be minket, sem szántóföldet és szőlőt nem adtál nékünk örökségül! Avagy ki akarod-é szúrni az emberek szemeit? Nem megyünk fel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'Megharaguvék azért Mózes igen, és monda az Úrnak: Ne tekints az ő áldozatjokra! Egy szamarat sem vettem el tőlök, és egyet sem bántottam közülök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'Azután monda Mózes Kórénak: Te és a te egész gyülekezeted legyetek az Úr előtt; te és azok és Áron, holnap.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'És kiki vegye az ő temjénezőjét, és tegyetek abba füstölő szert, és vigyétek az Úr elé, kiki az ő temjénezőjét; kétszáz és ötven temjénezőt. Te is, és Áron is, kiki az ő temjénezőjét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'Vevé azért kiki az ő temjénezőjét, és tevének abba tüzet, és rakának arra füstölő szert, és megállának a gyülekezet sátorának nyílása előtt, Mózes is és Áron.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'Kóré pedig összegyűjtötte vala ellenök az egész gyülekezetet a gyülekezet sátorának nyílásához, és megjelenék az Úrnak dicsősége az egész gyülekezetnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'És szóla az Úr Mózesnek és Áronnak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, 'Váljatok külön e gyülekezettől, hogy megemészszem őket egy szempillantásban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'Ők pedig arczukra borulának, és mondának: Isten, minden test lelkének Istene! nem egy férfiú vétkezett-é, és az egész gyülekezetre haragszol-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'Akkor szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, 'Szólj a gyülekezetnek, mondván: Menjetek el a Kóré, Dáthán és Abirám hajléka mellől köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'Felkele azért Mózes, és elméne Dáthán és Abirám felé, követék őt Izráel vénei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'És szóla a gyülekezetnek, mondván: Kérlek, távozzatok el ez istentelen emberek sátorai mellől, és semmit ne illessetek abból, a mi az övék, hogy el ne veszszetek az ő bűneik miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'És elmenének a Kóré, Dáthán és Abirám hajlékai mellől köröskörül; Dáthán pedig és Abirám kimenének, megállván az ő sátoraiknak nyílásánál feleségeikkel, fiaikkal és kisdedeikkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'Akkor monda Mózes: Ebből tudjátok meg, hogy az Úr küldött engemet, hogy cselekedjem mind e dolgokat, hogy nem magamtól indultam:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'Ha úgy halnak meg ezek, a mint meghal minden más ember, és ha minden más ember büntetése szerint büntettetnek meg ezek: akkor nem az Úr küldött engemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'Ha pedig az Úr valami új dolgot cselekszik, és a föld megnyitja az ő száját, és elnyeli őket, és mindazt, a mi az övék, és elevenen szállanak alá pokolba: akkor megismeritek, hogy gyalázták ezek az emberek az Urat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'És lőn, a mint elvégezé mind e beszédeket, meghasada a föld alattok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'És megnyitá a föld az ő száját, és elnyelé őket és az ő háznépeiket: és minden embert, a kik Kórééi valának, és minden jószágukat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'És alászállának azok és mindaz, a mi az övék, elevenen a pokolra: és befedezé őket a föld, és elveszének a község közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'Az Izráeliták pedig, a kik körülöttök valának, mind elfutának azoknak kiáltására; mert azt mondják vala: netalán elnyel minket a föld!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'És tűz jöve ki az Úrtól, és megemészté ama kétszáz és ötven férfiút, a kik füstölő szerekkel áldoznak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 36, 'Szóla pedig az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 37, 'Mondd meg Eleázárnak, Áron pap fiának, hogy szedje ki a temjénezőket a tűzből, a tüzet pedig hintsd széjjel, mert megszenteltettek a temjénezők;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 38, 'Ezeknek temjénezői, a kik a magok lelke ellen vétkeztek. És csináljanak azokból vékonyra vert lapokat az oltár beborítására. Mivelhogy járultak azokkal az Úr elé, és megszenteltettek: legyenek jegyül Izráel fiainak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 39, 'Felszedé azért Eleázár pap a réz temjénezőket, a melyekkel a megégettek járultak vala oda, és vékonyra verette azokat az oltár beborítására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 40, 'Emlékeztetőül Izráel fiainak, hogy senki idegen, a ki nem az Áron magvából való, ne járuljon az Úr elé füstölő szerrel füstölögtetni, hogy úgy ne járjon, mint Kóré és mint az ő gyülekezete, a miképen megmondotta vala néki az Úr Mózes által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 41, 'És másnap felzúdula Izráel fiainak egész gyülekezete Mózes ellen és Áron ellen, mondván: Ti öltétek meg az Úrnak népét!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 42, 'Mikor pedig egybegyűle a gyülekezet Mózes ellen és Áron ellen, akkor fordulának a gyülekezet sátora felé: és ímé befedezte vala azt a felhő, és megjelenék az Úrnak dicsősége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 43, 'Mózes azért és Áron menének a gyülekezet sátora elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 44, 'És szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 45, 'Menjetek ki e gyülekezet közül, hogy megemészszem őket egy szempillantásban; ők pedig orczájokra borulának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 46, 'És monda Mózes Áronnak: Fogd a temjénezőt, és tégy abba tüzet az oltárról, és rakj reá füstölő szert, és vidd hamar a gyülekezethez, és végezz engesztelést értök, mert kijött az Úrtól a nagy harag, elkezdődött a csapás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 47, 'Vevé azért Áron a temjénezőt, a mint mondotta vala Mózes, és futa a község közé, és ímé elkezdődött vala a csapás a nép között. És füstölő áldozatot tőn, és engesztelést szerze a népnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 48, 'És megálla a megholtak között és élők között; és megszűnék a csapás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 49, 'És valának, a kik megholtak vala e csapás alatt, tizennégy ezer hétszázan; azokon kivül, a kik megholtak vala a Kóré dolgáért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 50, 'És visszatére Áron Mózeshez a gyülekezet sátorának nyílásához. Így szűnék meg a csapás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'És szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, 'Szólj Izráel fiainak, és végy tőlök egy-egy vesszőt az ő atyáiknak háza szerint; az ő atyáik házának valamennyi fejedelmétől tizenkét vesszőt; és kinek-kinek a nevét írd fel az ő vesszejére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'Az Áron nevét pedig írd a Lévi vesszejére: mert egy vessző esik az ő atyjok házának fejéért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, 'És tedd le azokat a gyülekezet sátorában a bizonyság ládája elé, a hol megjelenek néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'És lesz, hogy annak a férfiúnak vesszeje, a kit elválasztok, kihajt; így hárítom el magamról Izráel fiainak zúgolódásait, a melyekkel zúgolódnak ti ellenetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'Szóla azért Mózes Izráel fiainak, és adának néki mind az ő fejedelmeik egy-egy vesszőt egy-egy fejedelemért; az ő atyáiknak háza szerint tizenkét vesszőt; az Áron vesszeje is azok között a vesszők között vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'És letevé Mózes a vesszőket az Úr elé a bizonyság sátorában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'És lőn másnap, hogy beméne Mózes a bizonyság sátorába; és ímé kihajtott vala a Lévi házából való Áronnak vesszeje, és hajtást hajtott, és virágot növelt, és mandolát érlelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'És kihozá Mózes mind azokat a vesszőket az Úr színe elől mind az Izráel fiai elé, és miután megnézték vala, vevé kiki az ő vesszejét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, 'És monda az Úr Mózesnek: Vidd vissza az Áron vesszejét a bizonyság ládája elé, hogy őriztessék ott a lázadó fiaknak jegyül, hogy megszünjék az én ellenem való zúgolódások, hogy meg ne haljanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'És megcselekedé Mózes; a mint parancsolta vala az Úr néki, akképen cselekedék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'És szólának Izráel fiai Mózesnek, mondván: Ímé pusztulunk, veszünk, mi mindnyájan elveszünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'Valaki közel járul az Úrnak sátorához, meghal. Avagy mindenestől elpusztulunk-é?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'És monda az Úr Áronnak: Te és a te fiaid, és a te atyádnak háza te veled, hordozzátok a szent hajlék körül való hamisság büntetését. Te és a te fiaid te veled, hordozzátok a ti papságtok hamisságának büntetését.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'A te atyádfiait, Lévinek törzsét, a te atyádnak nemzetségét is vedd magad mellé, melletted legyenek, és néked szolgáljanak; te pedig és a te fiaid veled, szolgáljatok a bizonyság sátora előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'És ügyeljenek a te ügyedre és az egész sátornak ügyére; de a szenthajlék edényeihez és az oltárhoz ne járuljanak, hogy meg ne haljanak mind ők, mind ti.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'És melletted legyenek, és ügyeljenek a gyülekezet sátorának ügyére, a sátornak minden szolgálatja szerint; de idegen ne járuljon ti hozzátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'Ügyeljetek azért a szenthajléknak ügyére, és az oltárnak ügyére, hogy ne legyen ezután harag Izráel fiai ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'Mert íme én választottam a ti atyátokfiait, a lévitákat Izráel fiai közül, mint az Úrnak adottakat, néktek, ajándékul, hogy szolgáljanak a gyülekezet sátorának szolgálatában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'Te pedig és a te fiaid te veled, ügyeljetek a ti papságotokra mindenben, a mik az oltárhoz tartoznak, és a függönyön belől vannak, hogy azokban szolgáljatok; a ti papságotoknak tisztét adtam néktek ajándékul, azért az idegen, a ki oda járul, haljon meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'Szóla azután az Úr Áronnak: Ímé én néked adtam az én felemelt áldozataimra való ügyelést is, valamit Izráel fiai nékem szentelnek, néked és a te fiaidnak adtam azokat felkenetési díjul, örökkévaló rendelés szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'Ez legyen tiéd a legszentségesebbekből, a melyek tűzzel meg nem égettetnek: Minden ő áldozatjok, akár ételáldozatjok, akár bűnért való áldozatjok, akár pedig vétekért való áldozatjok, a miket nékem adnak, mint legszentségesebbek, tiéid legyenek és a te fiaidé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'A legszentségesebb helyen egyed meg azt, csak a férfiak egyék azt; szentség legyen tenéked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'Ez is tiéd legyen, mint felemelt áldozat az ő ajándékukból, Izráel fiainak minden meglóbált áldozataival együtt; néked adtam azokat és a te fiaidnak, és a te leányaidnak, a kik veled vannak, örökkévaló rendelés szerint; mindenki, aki tiszta a te házadban, eheti azt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'Az olajnak minden kövérjét, és minden kövérjét a mustnak és gabonának, azoknak zsengéit, a melyeket az Úrnak adnak, tenéked adtam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'Mindennek első gyümölcsei az ő földjökön, a melyeket az Úrnak visznek, tiéid legyenek; mindenki, a ki tiszta a te házadban, egye azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'Minden, a mi teljesen Istennek szenteltetik Izráelben, tiéd legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'Minden, ami az élő állatok közül az anyaméhet megnyitja, a melyet az Úrnak visznek, mind emberekből s mind barmokból a tiéd legyen; csakhogy az embernek elsőszülöttét váltasd meg, és a tisztátalan állatnak elsőszülöttét is megváltassad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'A melyek pedig váltságosok, egy hónapostól kezdve váltasd meg a te becslésed szerint, öt ezüst sikluson a szent siklus szerint: húsz géra az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'De a tehénnek első fajzását, vagy a juhnak első fajzását, vagy a kecskének első fajzását meg ne váltasd; mert szentelni valók azok; a véröket hintsd az oltárra, és azoknak kövérit füstölögtesd el kedves illatú tűzáldozatul az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'Azoknak húsa pedig tiéd legyen, a miképen a meglóbált szegy, és a mint a jobb lapoczka is tiéd lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'Minden felemelt áldozatot a szent dolgokból, a melyeket az Úrnak áldoznak Izráel fiai, néked adtam örökkévaló rendelés szerint, és a te fiaidnak, és a te leányaidnak, a kik veled vannak; sónak szövetsége ez, örökkévaló az Úr előtt, néked és a te magodnak veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'Monda pedig az Úr Áronnak: Az ő földjökből örökséged nem lesz, sem osztályrészed nem lesz néked ő közöttök: Én vagyok a te osztályrészed és a te örökséged Izráel fiai között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, 'De ímé a Lévi fiainak örökségül adtam minden tizedet Izráelben; az ő szolgálatjokért való osztályrész ez a melylyel teljesítik ők a gyülekezet sátorának szolgálatát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'És ne járuljanak ezután Izráel fiai a gyülekezetnek sátorához, hogy ne vétkezzenek, és meg ne haljanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'De a léviták teljesítsék a gyülekezet sátorának szolgálatát, és ők viseljék az ő bűnüket; örökkévaló rendelés legyen a ti nemzetségeiteknél, hogy Izráel fiai között ne birjanak örökséget.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'Mivelhogy Izráel fiainak tizedét, a mit felemelt áldozatul visznek fel az Úrnak, adtam a lévitáknak örökségül: azért végeztem ő felőlök, hogy Izráel fiai között ne birjanak örökséget.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'És szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, 'A lévitáknak pedig szólj, és mondd meg nékik: Mikor beszeditek Izráel fiaitól a tizedet, a melyet örökségtekül adtam néktek azoktól, akkor áldozzatok abból felemelt áldozatot az Úrnak; a tizedből tizedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'És ez a ti felemelt áldozatotok olyanul tulajdoníttatik néktek, mint a szérűről való gabona és mint a sajtóból kiömlő bor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'Így vigyetek ti is felemelt áldozatot az Úrnak minden ti tizedetekből, a melyet beszedtek Izráel fiaitól, és adjátok abból az Úrnak felemelt áldozatot Áronnak, a papnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'Minden ti ajándékotokból vigyétek a felemelt áldozatokat az Úrnak, mindenből a kövérjét, a mi abból szentelni való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'Mondd meg azt is nékik: Mikor a kövérjét áldozzátok abból, olyanul tulajdoníttatik az a lévitáknak, mintha a szérűről és sajtóból adnák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'Megehetitek pedig azt minden helyen, ti és a ti házatok népe; mert jutalmatok ez néktek a gyülekezet sátorában való szolgálatokért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'És nem lesztek bűnösök a miatt, ha abból a kövérjét áldozzátok: és Izráel fiainak szent dolgait sem fertőztetitek meg, és meg sem haltok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'Szóla azután az Úr Mózesnek és Áronnak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, 'Ez a törvény rendelése, a melyet parancsolt az Úr, mondván: Szólj Izráel fiainak, hogy hozzanak hozzád egy veres tehenet, épet, a melyben ne legyen hiba, a melynek nyakán iga nem volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'És adjátok azt Eleázárnak, a papnak, és ő vitesse ki azt a táboron kivül, és öljék meg azt ő előtte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'És vegyen Eleázár, a pap annak véréből az ő újjával, és hintsen a gyülekezet sátorának eleje felé annak véréből hétszer.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'Azután égessék meg azt a tehenet az ő szemei előtt; annak bőrét, húsát, és vérét a ganéjával együtt égessék meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'Akkor vegyen a pap czédrusfát, izsópot és karmazsint, és vesse a tehénnek égő részei közé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'És mossa meg a pap az ő ruháit, az ő testét is mossa le vízzel, és azután menjen be a táborba, és tisztátalan legyen a pap estvéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'Az is, a ki megégeti azt, mossa meg az ő ruháit vízzel, és az ő testét is mossa le vízzel, és tisztátalan legyen estvéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'Valamely tiszta ember pedig szedje fel annak a tehénnek hamvát, és helyezze el azt a táboron kivűl tiszta helyre, hogy legyen az Izráel fiai gyülekezetének szolgálatára a tisztulásnak vizéhez; bűnért való áldozat ez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'És az, a ki felszedi a tehénnek hamvát, mossa meg az ő ruháit, és tisztátalan legyen estvéig; és legyen ez Izráel fiainak és a köztök tartózkodó jövevénynek örök rendelésül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'A ki illeti akármely embernek a holttestét, és tisztátalanná lesz hét napig:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'Az olyan tisztítsa meg magát azzal a vízzel harmadnapon és hetednapon, és tiszta lesz; ha pedig nem tisztítja meg magát harmadnapon és hetednapon, akkor nem lesz tiszta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Valaki holtat illet, bármely embert a ki megholt, és meg nem tisztítja magát, az megfertézteti az Úrnak hajlékát; és irtassék ki az a lélek Izráelből mivelhogy tisztulásnak vize nem hintetett ő reá, tisztátalan lesz; még rajta van az ő tisztátalansága.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, 'Ez legyen a törvény, mikor valaki sátorban hal meg. Mindaz, a ki bemegy a sátorba, és mindaz, a ki ott van a sátorban, tisztátalan legyen hét napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'Minden nyitott edény is, a melyen nincs lezárható fedél, tisztátalan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'És mindaz, a ki illet a mezőn fegyverrel megöletettet, vagy megholtat, vagy emberi csontot, vagy sírt, tisztátalan legyen hét napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'És vegyenek a tisztátalanért a bűnért való megégetett áldozatnak hamvából, és töltsenek arra élő vizet edénybe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'Valamely tiszta ember pedig vegyen izsópot, és mártsa azt vízbe, és hintse meg a sátort és minden edényt, és minden embert, a kik ott lesznek; és azt is, a ki a csontot, vagy a megöltet, vagy a megholtat, vagy a koporsót illette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'Hintse pedig meg a tiszta a tisztátalant harmadnapon és hetednapon, és tisztítsa meg őt hetednapon; azután mossa meg az ő ruháit, mossa le magát is vízzel, és tiszta lesz estve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'Ha pedig valaki tisztátalanná lesz, és nem tisztítja meg magát, az a lélek irtassék ki a község közűl; mivelhogy az Úrnak szenthelyét megfertéztette, a tisztulásnak vize nem hintetett ő reá, tisztátalan az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'Ez legyen ő nálok örök rendelésül: mind az, a ki hinti a tisztulásnak vizét, mossa meg az ő ruháit; mind az, a ki illeti a tisztulásnak vizét, tisztátalan legyen estvéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'És valamit illet a tisztátalan, tisztátalan legyen az; és az a lélek is, a ki illeti azt, tisztátalan legyen estvéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'És eljutának Izráel fiai, az egész gyülekezet Czin pusztájába az első hónapban és megtelepedék a nép Kádesben, és meghala ott Miriám, és eltemetteték ott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'De nem vala vize a gyülekezetnek, összegyűlének azért Mózes és Áron ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'És feddőzék a nép Mózessel, és szólának mondván: Vajha holtunk volna meg, mikor megholtak a mi atyánkfiai az Úr előtt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'És miért hoztátok az Úrnak gyülekezetét e pusztába, hogy meghaljunk itt mi, és a mi barmaink?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'És miért hoztatok fel minket Égyiptomból, hogy e rossz helyre hozzatok minket, hol nincs vetés, sem füge, sem szőlő, sem gránátalma, és inni való víz sincsen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'Elmenének azért Mózes és Áron a gyülekezetnek színe elől, a gyülekezet sátorának nyílása elé, és arczukra borulának; és megjelenék nékik az Úrnak dicsősége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'És szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, 'Vedd ezt a vesszőt, és gyűjtsd össze a gyülekezetet te, és Áron, a te atyádfia, és szóljatok ím e kősziklának az ő szemeik előtt, hogy adjon vizet; és fakaszsz vizet nékik e kősziklából, és adj inni a gyülekezetnek és az ő barmaiknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'Vevé azért Mózes azt a vesszőt az Úrnak színe elől a mint parancsolta vala néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'És összegyűjték Mózes és Áron a gyülekezetet a kőszikla elé, és monda nékik: Halljátok meg most, ti lázadók! Avagy e kősziklából fakasszunk-é néktek vizet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'És felemelé Mózes az ő kezét, és megüté a kősziklát az ő vesszejével két ízben; és sok víz ömle ki, és ivék a gyülekezet és az ő barmai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'És monda az Úr Mózesnek és Áronnak: Mivelhogy nem hittetek nékem, hogy megdicsőítettetek volna engem Izráel fiainak szemei előtt: azért nem viszitek be e községet a földre, a melyet adtam nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'Ezek a versengésnek vizei, a melyekért feddőztek Izráel fiai az Úrral; és megdicsőítette magát ő bennök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'És külde Mózes követeket Kádesből Edom királyához, kik így szólának: Ezt mondja a te atyádfia az Izráel: Te tudod mindazt a nyomorúságot, a mely mi rajtunk esett:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'Hogy a mi atyáink alámentek Égyiptomba, és sok ideig laktunk Égyiptomban, és hogy nyomorgatának minket az égyiptombeliek, és a mi atyáinkat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'És kiáltottunk az Úrhoz, és meghallgatta a mi szónkat, és angyalt külde és kihozott minket Égyiptomból; és ímé Kádesben vagyunk a te határodnak végvárosában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'Hadd mehessünk át a te földeden! Nem megyünk át sem mezőn, sem szőlőn, és kútvizet sem iszunk; az országúton megyünk, és nem térünk sem jobbra, sem balra, míg általmegyünk a te határodon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'Felele pedig Edom: Nem mehetsz át az én földemen, hogy fegyverrel ne menjek ellened!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'És mondának néki Izráel fiai: A járt úton megyünk fel, és ha a te vizedet iszszuk, én és az én barmaim, megadom annak az árát. Nincs egyéb szándékom csak hogy gyalog mehessek át.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'Az pedig monda: Nem mégy át. És kiméne ő ellene Edom sok néppel és nagy erővel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'Mivel nem akará Edom megengedni Izráelnek, hogy általmenjen az ő országán: azért eltére Izráel ő tőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'Majd elindulának Kádesből, és jutának Izráel fiai, az egész gyülekezet a Hór hegyére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'És szóla az Úr Mózesnek és Áronnak, a Hór hegyénél, Edom földének határán, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, 'Áron az ő népeihez takaríttatik: mert nem megy be a földre, a melyet Izráel fiainak adtam, mivelhogy ellenszegültetek az én szómnak a versengésnek vizénél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'Vedd Áront és Eleázárt, az ő fiát, és vezesd fel őket a Hór hegyére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'És vetkeztesd le Áront az ő ruháiból, és öltöztesd fel azokba Eleázárt, az ő fiát; mert Áron az ő népéhez takaríttatik, és meghal ott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'És úgy cselekedék Mózes, a mint parancsolta vala az Úr, és felmenének a Hór hegyére az egész gyülekezet láttára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'És Mózes levetkezteté Áront az ő ruháiból, és felöltözteté azokba Eleázárt, az ő fiát. És meghala Áron ott a hegynek tetején, Mózes pedig és Eleázár leszálla a hegyről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'És látá az egész gyülekezet, hogy meghalt vala Áron, és siratá Áront harmincz napig Izráelnek egész háza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'Mikor pedig meghallotta a Kananeus, Arad királya, a ki lakozik vala dél felől, hogy jön Izráel a kémeknek útán: megütközék Izráellel, és foglyokat ejte közülök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'Fogadást tőn azért Izráel az Úrnak, és monda: Ha valóban kezembe adod e népet, eltörlöm az ő városait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'És meghallgatá az Úr Izráelnek szavát, és kézbe adá a Kananeust, és eltörlé őket, és azoknak városait. És nevezé azt a helyet Hormának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'És elindulának a Hór hegyétől a veres tengerhez vivő úton, hogy megkerüljék Edom földét. És a népnek lelke megkeseredék útközben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'És szóla a nép Isten ellen és Mózes ellen: Miért hoztatok fel minket Égyiptomból, hogy meghaljunk e pusztában? Mert nincsen kenyér, víz sincsen, és e hitvány eledelt útálja a mi lelkünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'Bocsáta azért az Úr a népre tüzes kígyókat, és megmardosák a népet, és sokan meghalának Izráel népéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'Akkor méne a nép Mózeshez, és mondának: Vétkeztünk, mert szólottunk az Úr ellen és te ellened; imádkozzál az Úrhoz, hogy vigye el rólunk a kígyókat. És imádkozék Mózes a népért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'És monda az Úr Mózesnek: Csinálj magadnak tüzes kígyót, és tűzd fel azt póznára: és ha valaki megmarattatik, és feltekint arra, életben maradjon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'Csinála azért Mózes rézkígyót, és feltűzé azt póznára. És lőn, hogy ha a kígyó valakit megmar vala, és az feltekinte a rézkígyóra, életben marada.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'Azután elindulának Izráel fiai, és tábort ütének Obóthban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'Obóthból is elindulának, és tábort ütének Hije-Abarimban, abban a pusztában, a mely Moáb előtt vala napkelet felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'Onnét elindulának, és tábort ütének Zéred völgyében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'Onnét elindulának, és tábort ütének az Arnon vizén túl, a mely van a pusztában, és kijő az Emoreus határából. Mert az Arnon Moábnak határa Moáb között és Emoreus között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'Azért van szó az Úr hadainak könyvében: Vahébről Szúfában, és a patakokról Arnonnál,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'És a patakok folyásáról, a mely Ar város felé hajol és Moáb határára dűl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'És onnét Béérbe menének. Ez az a kút, a melynél mondotta vala az Úr Mózesnek: Gyűjtsd össze a népet, és adok nékik vizet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Akkor éneklé az Izráel ez éneket: Jőjj fel óh kút! énekeljetek néki!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, 'Kút, a melyet fejedelmek ástak; a nép előkelői vájtak, kormánypálczával, vezérbotjaikkal. És a pusztából Mathanába menének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'És Mathanából Nahaliélbe, és Nahaliélből Bámóthba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'Bámóthból pedig abba a völgybe, a mely Moáb mezején van, onnan a Piszga tetejére, a mely a sivatagra néz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'És külde Izráel követeket Szíhonhoz, az Emoreusok királyához, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, 'Hadd mehessek át a te földeden! Nem hajlunk mezőre, sem szőlőre, kútvizet sem iszunk; az országúton megyünk, míg átmegyünk a te határodon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'De nem engedé Szíhon Izráelnek, hogy átmenjen az ő határán, sőt egybegyűjté Szíhon minden népét, és kiméne Izráel ellen a pusztába, és jöve Jaháczba; és megütközék Izráellel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'És megveré őt Izráel fegyvernek élivel, és elfoglalá annak földét Arnontól Jabbókig, az Ammon fiaiig; mert erős vala az Ammon fiainak határa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'És elfoglalá Izráel mind e városokat, és megtelepedék Izráel az Emoreusok minden városában, Hesbonban és annak minden városában;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'Mert Hesbon Szíhonnak az Emoreusok királyának városa vala, ki is hadakozott vala Moábnak előbbi királyával, és elvett vala minden földet annak kezéből Arnonig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'Azért mondják a példabeszédmondók: Jőjjetek Hesbonba! Építtessék és erősíttessék Szíhon városa!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'Mert tűz jött ki Hesbonból, láng Szíhon városából; megemésztette Art, Moábnak városát, Arnon magaslatainak urait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'Jaj néked Moáb! Elvesztél Kámosnak népe! Futásra adta ő fiait, leányait fogságra Szíhonnak, az emoreus királynak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, 'De mi lövöldöztük őket, elveszett Hesbon Dibonig, és elpusztítottuk Nofáig, a mely Medebáig ér.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'Megtelepedék azért Izráel az Emoreusok földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'És elkülde Mózes, hogy megkémleljék Jázert, és bevevék annak városait, és kiűzé az Emoreust, a ki ott vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'Majd megfordulának, és felmenének a Básánba vivő úton. És kijöve Og, Básán királya ő ellenök, ő és egész népe, hogy megütközzenek Hedreiben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'Akkor monda az Úr Mózesnek: Ne félj tőle, mert a te kezedbe adtam őt, és egész népét, és az ő földét. És úgy cselekedjél vele, a miképen cselekedtél Szíhonnal az Emoreusok királyával, a ki lakik vala Hesbonban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'Megverék azért őt és az ő fiait és egész népét annyira, hogy egy sem marada belőle; és elfoglalák az ő földét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'És tovább menének Izráel fiai, és tábort ütének Moáb mezőségen a Jordánon túl, Jérikhó ellenében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'És mikor látta Bálák, a Czippór fia mind azokat, a melyeket cselekedett vala Izráel az Emoreussal:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'Igen megrémüle Moáb a néptől, mivelhogy sok vala az, és búsula Moáb Izráel fiai miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'Monda azért Moáb Midián véneinek: Most elnyalja e sokaság minden mi környékünket, a miképen elnyalja az ökör a mezőnek pázsitját. (Bálák pedig, Czippórnak fia Moáb királya vala abban az időben.)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'Külde azért követeket Bálámhoz, a Beór fiához Péthorba, a mely vala a folyóvíz mellett, az ő népe fiainak földére, hogy hívják őt, mondván: Ímé nép jött ki Égyiptomból, és ímé ellepte e földnek színét, és megtelepszik én ellenemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'Most azért kérlek jöjj el, átkozd meg érettem e népet, mert erősebb nálamnál; talán erőt vehetek rajta, megverjük őt, és kiűzhetem őt e földből; mert jól tudom, hogy a kit megáldasz, meg lesz áldva, és a kit megátkozol, átkozott lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'Elmenének azért Moábnak vénei és Midiánnak vénei, és a jövendőmondásnak jutalma kezeikben vala, és jutának Bálámhoz, és megmondák néki Bálák izenetét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'Ő pedig monda nékik: Háljatok itt ez éjjel, és feleletet adok néktek, a miképen szól nékem az Úr. És Moábnak fejedelmei ott maradának Bálámnál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'Eljöve pedig az Isten Bálámhoz, és monda: Kicsodák ezek a férfiak te nálad?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'És monda Bálám az Istennek: Bálák, Czippór fia, Moáb királya, küldött én hozzám, ezt mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, 'Ímé e nép, a mely kijött Égyiptomból, ellepte a földnek színét; most azért jöjj el, átkozd meg azt érettem, talán megharczolhatok vele, és kiűzhetem őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'És monda Isten Bálámnak: Ne menj el ő velök, ne átkozd meg azt a népet, mert áldott az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'Felkele azért Bálám reggel, és monda a Bálák fejedelmeinek: Menjetek el a ti földetekre; mert nem akarja az Úr megengedni nékem, hogy elmenjek veletek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'És felkelének Moáb fejedelmei, és jutának Bálákhoz, és mondának: Nem akart Bálám eljönni velünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'Elkülde azért ismét Bálák több fejedelmet, amazoknál előkelőbbeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'És eljutának Bálámhoz, és mondának néki: Ezt mondja Bálák, Czippórnak fia: Kérlek, ne vonakodjál eljönni hozzám!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'Mert igen-igen megtisztellek téged, és akármit mondasz nékem, megcselekszem. Jöjj el azért kérlek, és átkozd meg értem e népet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'Bálám pedig felele és monda a Bálák szolgáinak: Ha Bálák az ő házát aranynyal és ezüsttel tele adná is nékem, nem hághatom át az Úrnak, az én Istenemnek szavát, hogy valamit míveljek; kicsinyt vagy nagyot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'Most mindazonáltal maradjatok itt kérlek ti is ez éjjel, hadd tudjam meg, mit szól ismét az Úr nékem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'És eljöve Isten Bálámhoz éjjel, és monda néki: Ha azért jöttek e férfiak, hogy elhívjanak téged: kelj fel, menj el velök; de mindazáltal azt cselekedjed, a mit mondok majd néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'Felkele azért Bálám reggel, és megnyergelé az ő szamarát, és elméne a Moáb fejedelmeivel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'De megharaguvék Isten, hogy elmegy vala ő. És megálla az Úrnak angyala az útban, hogy ellenkezzék vele; ő pedig üget vala az ő szamarán, és két szolgája vala vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'És meglátá a szamár az Úrnak angyalát, a mint áll vala az úton, és mezítelen fegyvere a kezében; letére azért a szamár az útról, és méne a mezőre; Bálám pedig veré az ő szamarát, hogy visszatérítse azt az útra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'Azután megálla az Úrnak angyala a szőlők ösvényén, holott innen is garád, onnan is garád vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'A mint meglátá a szamár az Úrnak angyalát, a falhoz szorula, és a Bálám lábát is oda szorítá a falhoz; ezért ismét megveré azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'Az Úr angyala pedig ismét tovább méne, és megálla szoros helyen, hol nem volt út a kitérésre, sem jobbra, sem balra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'A mint meglátá a szamár az Úrnak angyalát, lefeküvék Bálám alatt, azért megharaguvék Bálám, és megveré a szamarat bottal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'És megnyitá az Úr a szamárnak száját, és monda a szamár Bálámnak: Mit vétettem néked, hogy immár háromszor vertél meg engem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'Bálám pedig monda a szamárnak: Mert megcsúfoltál engem! Vajha volna fegyver a kezemben, nyilván megölnélek most téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'És monda a szamár Bálámnak: Avagy nem te szamarad vagyok-é, a melyen járni szoktál, a mióta megvagy, mind e napig? Avagy szoktam volt-é veled e képen cselekedni? Az pedig felele: Nem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'És megnyitá az Úr a Bálám szemeit, és látá az Úr angyalát, a mint áll vala az útban, és mezítelen fegyverét az ő kezében; akkor meghajtá magát és arczra borula.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'Az Úrnak angyala pedig monda néki: Miért verted meg a te szamaradat immár három ízben? Ímé én jöttem ki, hogy ellenkezzem veled, mert veszedelmes ez az út én előttem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'És meglátott engem a szamár, és kitért én előttem immár három ízben; ha ki nem tért volna előlem, most meg is öltelek volna téged, őt pedig életben hagytam volna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'Monda azért Bálám az Úr angyalának: Vétkeztem, mert nem tudtam, hogy te állasz előttem az útban. Most azért, ha nem tetszik ez néked, visszatérek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'Az Úrnak angyala pedig monda Bálámnak: Menj el e férfiakkal; mindazáltal a mit én mondok majd néked, azt mondjad. Elméne azért Bálám a Bálák fejedelmeivel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'Mikor pedig meghallá Bálák, hogy jön Bálám, kiméne elébe Moábnak egyik városába, a mely az Arnon vidékén, a határ szélén vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'És monda Bálák Bálámnak: Avagy nem küldözgettem-é hozzád, hogy hívjanak téged? Miért nem jösz vala én hozzám? Avagy valóban nem tisztelhetnélek meg téged?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, 'Bálám pedig monda Báláknak: Ímé eljöttem hozzád. Most pedig szólhatok-é magamtól valamit? A mi mondani valót Isten ád az én számba, azt mondom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'És elméne Bálám Bálákkal, és eljutának Kirjat-Husótba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'És vágata Bálák ökröket és juhokat, és küldé Bálámnak és a fejedelmeknek, a kik vele valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'Reggel pedig magához vevé Bálák Bálámot és felvivé őt a Baál magas hegyére, hogy meglássa onnét a népnek valami részét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'És monda Bálám Báláknak: Építs itt nékem hét oltárt, és készíts el ide nékem hét tulkot és hét kost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'És úgy cselekedék Bálák a miképen mondotta vala Bálám. És áldozék Bálák és Bálám mindenik oltáron egy-egy tulkot és egy-egy kost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'És monda Bálám Báláknak: Állj meg a te égőáldozatod mellett, én pedig elmegyek; talán előmbe jő az Úr nékem, és a mit mutat majd nékem, megjelentem néked. Elméne azért egy kopasz oromra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'És elébe méne Isten Bálámnak, és monda néki Bálám: A hét oltárt elrendeztem, és áldoztam mindenik oltáron egy-egy tulkot és egy-egy kost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'Az Úr pedig ígét ada Bálámnak szájába, és monda néki: Térj vissza Bálákhoz, és így szólj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'És visszatére ő hozzá, és ímé áll vala az ő égőáldozata mellett; ő maga és Moábnak minden fejedelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'És elkezdé az ő példázó beszédét, és monda: Siriából hozatott engem Bálák, Moábnak királya kelet hegyeiről, mondván: Jöjj, átkozd meg nékem Jákóbot, és jöjj, szidalmazd meg Izráelt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'Mit átkozzam azt, a kit Isten nem átkoz, és mit szidalmazzam azt, a kit az Úr nem szidalmaz?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'Mert sziklák tetejéről nézem őt, és halmokról tekintem őt; ímé oly nép, a mely maga fog lakni, és nem számláltatik a nemzetek közé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Ki számlálhatja meg a Jákób porát, és Izráel negyedrészének számát? Haljon meg az én lelkem az igazak halálával, és legyen az én utolsó napom, mint az övé!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, 'És monda Bálák Bálámnak: Mit cselekeszel én velem? Hogy megátkozzad ellenségeimet, azért hoztalak téged, és ímé igen megáldád őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'Ez pedig felele és monda: Avagy nem arra kell-é vigyáznom, hogy azt szóljam, a mit az Úr adott az én számba?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'Monda azután néki Bálák: Kérlek, jöjj velem más helyre, honnét meglássad őt, de csak valamely részét látod annak, és őt mindenestől nem látod, és átkozd meg őt onnét nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'És vivé őt az őrállók helyére, a Piszga tetejére, és építe hét oltárt, és áldozék egy-egy tulkot és egy-egy kost mindenik oltáron.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'És monda Báláknak: Állj meg itt a te égőáldozatod mellett, én pedig elébe megyek amoda.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'Elébe méne azért az Úr Bálámnak, és ígét ada az ő szájába, és monda: Térj vissza Bálákhoz, és így szólj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'Méne azért ő hozzá, és ímé ő áll vala az ő égőáldozata mellett, és Moáb fejedelmei is ő vele. És monda néki Bálák: Mit szóla az Úr?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'Akkor elkezdé az ő példázó beszédét, és monda: Kelj fel Bálák, és halljad; figyelj reám Czippórnak fia!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'Nem ember az Isten, hogy hazudjék és nem embernek fia, hogy megváltozzék. Mond-é ő valamit, hogy meg ne tenné? Igér-é valamit, hogy azt ne teljesítené?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'Ímé parancsolatot vettem, hogy áldjak; ha ő áld, én azt meg nem fordíthatom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'Nem vett észre Jákóbban hamisságot, és nem látott gonoszságot Izráelben. Az Úr, az ő Istene van ő vele; és királynak szóló rivalgás hangzik ő benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'Isten hozta ki őket Égyiptomból, az ő ereje mint a vad bivalyé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'Mert nem fog varázslás Jákóbon, sem jövendőmondás Izráelen. Idején adatik tudtára Jákóbnak és Izráelnek: mit mívelt Isten!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'Ímé e nép felkél mint nőstény oroszlán, és feltámad mint hím oroszlán; nem nyugszik, míg prédát nem eszik, és elejtettek vérét nem iszsza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'Akkor monda Bálák Bálámnak: Se ne átkozzad, se ne áldjad őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'Felele pedig Bálám, és monda Báláknak: Avagy nem szólottam volt-é néked, mondván: Valamit mond nékem az Úr, azt mívelem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'És monda Bálák Bálámnak: Jöjj, kérlek, elviszlek téged más helyre: talán tetszeni fog az Istennek, hogy megátkozzad onnét e népet én érettem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'Elvivé azért Bálák Bálámot a Peór tetejére, a mely a puszta felé néz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'És monda Bálám Báláknak: Építtess itt nékem hét oltárt, és készíts el ide nékem hét tulkot és hét kost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'Úgy cselekedék azért Bálák, a mint mondotta volt Bálám, és áldozék minden oltáron egy-egy tulkot és egy-egy kost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'Mikor pedig látta Bálám, hogy tetszik az Úrnak, hogy megáldja Izráelt, nem indula, mint az előtt, varázslatok után, hanem fordítá az ő orczáját a puszta felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'És mikor felemelte Bálám az ő szemeit, látá Izráelt, a mint letelepedett az ő nemzetségei szerint; és Istennek lelke vala ő rajta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'Akkor elkezdé az ő példázó beszédét és monda: Bálámnak, Beór fiának szózata, a megnyílt szemű embernek szózata.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'Annak szózata, a ki hallja Istennek beszédét, a ki látja a Mindenhatónak látását, leborulva, de nyitott szemekkel:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'Mily szépek a te sátoraid óh Jákób! a te hajlékaid óh Izráel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'Mint kiterjesztett völgyek, mint kertek a folyóvíz mellett, mint az Úr plántálta áloék, mint czédrusfák a vizek mellett!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'Víz ömledez az ő vedreiből, vetését bő víz öntözi; királya nagyobb Agágnál, és felmagasztaltatik az ő országa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'Isten hozta ki Égyiptomból, az ő ereje mint a vad bivalyé: megemészti a pogányokat, az ő ellenségeit; csontjaikat megtöri, és nyilaival által veri.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Lehever, nyugszik mint hím oroszlán, és mint nőstény oroszlán; ki serkenti fel őt? A ki áld téged, áldott lészen, és ki átkoz téged, átkozott lészen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'És felgerjede Báláknak haragja Bálám ellen, és egybeüté kezeit, és monda Bálák Bálámnak: Azért hívtalak téged, hogy átkozd meg ellenségeimet; és ímé igen megáldottad immár három ízben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'Most azért fuss a te helyedre. Mondottam vala, hogy igen megtisztellek téged; de ímé megfosztott téged az Úr a tisztességtől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'És monda Bálám Báláknak: A te követeidnek is, a kiket küldöttél volt hozzám, nem így szólottam-é, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, 'Ha Bálák az ő házát ezüsttel és aranynyal tele adná is nékem, az Úrnak beszédét által nem hághatom, hogy magamtól jót, vagy rosszat cselekedjem. A mit az Úr szól, azt szólom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'Most pedig én elmegyek ímé az én népemhez; jőjj, hadd jelentsem ki néked, mit fog cselekedni e nép a te népeddel, a következő időben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'És elkezdé az ő példázó beszédét, és monda: Bálámnak, Beór fiának szózata, a megnyilt szemű ember szózata,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'Annak szózata, a ki hallja Istennek beszédét, és a ki tudja a Magasságosnak tudományát, és a ki látja a Mindenhatónak látását, leborulva, de nyitott szemekkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'Látom őt, de nem most; nézem őt, de nem közel. Csillag származik Jákóbból, és királyi pálcza támad Izráelből; és általveri Moábnak oldalait, és összetöri Sethnek minden fiait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'És Edom más birtoka lesz, Szeir az ő ellensége is másnak birtoka lesz; de hatalmasan cselekszik Izráel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'És uralkodik a Jákóbtól való, és elveszti a városból a megmaradtat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'És mikor látja vala Amáleket, elkezdé az ő példázó beszédét, és monda: Amálek első a nemzetek között, de végezetre mindenestől elvész.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'És mikor látja vala a Keneust, elkezdé példázó beszédét, és monda: Erős a te lakhelyed, és sziklára raktad fészkedet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'Mégis el fog pusztulni Kain; a míg Assur téged fogva viszen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'Újra kezdé az ő példázó beszédét, és monda: Óh, ki fog élni még, a mikor véghez viszi ezt az Isten?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'És Kittim partjairól hajók jőnek, és nyomorgatják Assúrt, nyomorgatják Ébert is, és ez is mindenestől elvész.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'Felkele azért Bálám, és elméne, hogy visszatérjen az ő helyére. És Bálák is elméne az ő útján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'Mikor pedig Sittimben lakozik vala Izráel, kezde a nép paráználkodni Moáb leányaival.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'Mert hívogaták a népet az ő isteneik áldozataira; és evék a nép, és imádá azoknak isteneit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'És odaszegődék Izráel Bál-Peórhoz; az Úr haragja pedig felgerjede Izráel ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'És monda az Úr Mózesnek: Vedd elő e népnek minden főemberét, és akasztasd fel őket az Úrnak fényes nappal; hogy elforduljon az Úr haragjának gerjedezése Izráeltől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'Monda azért Mózes Izráel bíráinak: Kiki ölje meg az ő embereit, a kik odaszegődtek Bál-Peórhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'És ímé eljöve valaki Izráel fiai közül, és hoza az ő atyjafiai felé egy midiánbeli asszonyt, Mózes szeme láttára, és Izráel fiai egész gyülekezetének láttára; ők pedig sírnak vala a gyülekezet sátorának nyilásánál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'És mikor látta vala Fineás, Eleázár fia, Áron papnak unokája, felkele a gyülekezet közül, és dárdáját vevé kezébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'És beméne az izráelita férfi után a sátorba, és általdöfé mindkettőjöket, mind az izráelita férfit, mind az asszonyt hason. És megszünék a csapás Izráel fiai között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'De meghaltak vala a csapás miatt huszonnégy ezeren.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'Akkor szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, 'Fineás, Eleázár fia, Áron pap unokája, elfordította az én haragomat Izráel fiaitól, mivelhogy az én bosszúmat megállotta ő közöttök; ezért nem pusztítom ki bosszúmban Izráel fiait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'Mondd azért: Ímé én az én szövetségemet, a békesség szövetségét adom ő néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'És lészen ő nála és az ő magvánál ő utána az örökkévaló papságnak szövetsége; mivelhogy bosszút állott az ő Istenéért, és engesztelést végze Izráel fiaiért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'A megöletett izráelita férfinak neve pedig, a ki a midiánbeli asszonynyal együtt öletett meg, Zimri, a Szálu fia vala, a Simeon-nemzetség háznépének fejedelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'A megöletett midiánbeli asszony neve pedig Kozbi, Czúr leánya, a ki a Midiániták között az ő atyja háza nemzetségeinek fejedelme vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'És szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, 'Támadjátok meg a Midiánitákat, és verjétek meg őket,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'Mert ők megtámadtak titeket az ő cselszövéseikkel, a melyeket Peórért és az ő hugokért Kozbiért, a midián fejedelem leányáért szőttek ellenetek, a ki megöletett a Peór miatt való csapásnak napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'És lőn a csapás után, szóla az Úr Mózesnek és Eleázárnak, az Áron pap fiának, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, 'Vegyétek számba Izráel fiainak egész gyülekezetét, húsz esztendőstől fogva és feljebb, az ő atyáiknak háznépe szerint; mindenkit, a ki hadba mehet Izráelben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'Szóla azért velök Mózes és Eleázár, a pap, a Moáb mezőségében a Jordán mellett, Jérikhó ellenében, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, 'Vegyétek számba a népet, húsz esztendőstől fogva és feljebb, a miképen parancsolta vala az Úr Mózesnek és Izráel fiainak, a kik kijöttek volt Égyiptom földéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'Rúben elsőszülötte Izráelnek. Rúben fiai ezek: Hánoktól a Hánokiták, Pallutól a Palluiták nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'Heczrontól a Heczroniták nemzetsége, Kármitól a Kármiták nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'Ezek a Rúbeniták nemzetségei. És lőn az ő számok negyvenhárom ezer, hétszáz és harmincz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'És a Pallu fiai valának: Eliáb.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'Eliáb fiai pedig, Nemuél, Dáthán és Abirám. Ez a Dáthán és Abirám a gyülekezet előljárói valának, a kik feltámadtak vala Mózes ellen és Áron ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'És megnyitá a föld az ő száját, és elnyelé őket és Kórét, meghalván az a gyülekezet, mivelhogy megemészte a tűz kétszáz és ötven férfiút, a kik intőpéldául lőnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'Kóré fiai pedig nem halának meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'Simeon fiai az ő nemzetségeik szerint ezek: Nemuéltől a Nemuéliták nemzetsége, Jámintól a Jáminiták nemzetsége, Jákintól a Jákiniták nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'Zerákhtól a Zerákhiták nemzetsége. Saultól a Sauliták nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'Ezek a Simeoniták nemzetségei: huszonkét ezer és kétszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'Gád fiai az ő nemzetségeik szerint ezek: Sefontól a Sefoniták nemzetsége, Haggitól a Haggiták nemzetsége, Súnitól a Súniták nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'Oznitól az Ozniták nemzetsége, Éritől az Ériták nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'Arodtól az Aroditák nemzetsége, Arélitől az Aréliták nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'Ezek Gád fiainak nemzetségei; az ő számok szerint negyven ezer és ötszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'Júda fiai: Ér és Onán. És meghala Ér és Onán a Kanaán földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'Júda fiai pedig az ő nemzetségeik szerint ezek valának: Séláhtól a Séláhiták nemzetsége, Pérecztől a Pérecziták nemzetsége, Zerákhtól a Zerákhiták nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'Pérecz fiai valának pedig: Heczrontól a Heczroniták nemzetsége; Hámultól a Hámuliták nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'Ezek Júda nemzetségei az ő számok szerint: hetvenhat ezer ötszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'Izsakhár fiai az ő nemzetségeik szerint ezek: Thólától a Thóláiták nemzetsége; Puvától a Puviták nemzetsége;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'Jásubtól a Jásubiták nemzetsége; Simrontól a Simroniták nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'Ezek Izsakhár nemzetségei az ő számok szerint: hatvannégy ezer háromszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'Zebulon fiai az ő nemzetségeik szerint ezek: Szeredtől a Szerediták nemzetsége, Élontól az Éloniták nemzetsége, Jahleéltől a Jahleéliták nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'Ezek a Zebuloniták nemzetségei az ő számok szerint: hatvan ezer ötszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'József fiai az ő nemzetségeik szerint ezek: Manasse és Efraim.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'Manasse fiai: Mákirtól a Mákiriták nemzetsége. Mákir nemzé Gileádot; Gileádtól a Gileáditák nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'Ezek Gileád fiai: Jezertől a Jezeriták nemzetsége, Hélektől a Hélekiták nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'És Aszriéltől az Aszriéliták nemzetsége; Sekemtől a Sekemiták nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'És Semidától a Semidáták nemzetsége és Héfertől a Héferiták nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'Czélofhádnak pedig, a Héfer fiának nem voltak fiai, hanem leányai; és a Czélofhád leányainak nevei ezek: Makhla, Nóa, Hogla, Milkha és Thircza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'Ezek Manasse nemzetségei, és az ő számok ötvenkét ezer és hétszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'Ezek Efraim fiai az ő nemzetségeik szerint: Suthelákhtól a Suthelákhiták nemzetsége, Békertől a Békeriták nemzetsége, Tahántól a Tahániták nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'Ezek pedig a Suthelákh fiai: Érántól az Érániták nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'Ezek Efraim fiainak nemzetségei az ő számok szerint: harminczkét ezer és ötszáz. Ezek József fiai az ő nemzetségeik szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'Benjámin fiai az ő nemzetségeik szerint ezek: Belától a Belaiták nemzetsége; Asbéltől az Asbéliták nemzetsége; Ahirámtól az Ahirámiták nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'Sefufámtól a Sefufámiták nemzetsége; Hufámtól a Hufámiták nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'Bela fiai pedig valának: Ard és Naamán: Ardtól az Arditák nemzetsége; Naamántól a Naamániták nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'Ezek Benjámin fiai az ő nemzetségeik szerint, és számok: negyvenöt ezer és hatszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'Ezek Dán fiai az ő nemzetségeik szerint: Suhámtól a Suhámiták nemzetsége. Ezek Dán nemzetségei, az ő nemzetségeik szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'A Suhamiták minden nemzetsége az ő számok szerint: hatvannégy ezer és négyszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'Áser fiai az ő nemzetségeik szerint ezek: Jimnától a Jimnaiták nemzetsége; Jisvitől a Jisviták nemzetsége; Bériától a Bérihiták nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'A Béria fiaitól: Khébertől a Khéberiták nemzetsége, Malkiéltől a Malkiéliták nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'Áser leányának pedig neve vala Sérah.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'Ezek Áser fiainak nemzetségei az ő számok szerint: ötvenhárom ezer és négyszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'Nafthali fiai az ő nemzetségeik szerint ezek: Jakhczeéltől a Jakhczeéliták nemzetsége, Gúnitól a Gúniták nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'Jéczertől a Jéczeriták nemzetsége; Sillémtől a Sillémiták nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'Ezek Nafthali nemzetségei az ő nemzetségeik szerint: az ő számok pedig negyvenöt ezer és négyszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'Ezek Izráel fiainak megszámláltjai: hatszáz egyezer hétszáz harmincz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'Szóla pedig az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, 'Ezeknek osztassék el az a föld örökségül, az ő neveiknek száma szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'A nagyobb számúnak adj nagyobb örökséget, a kisebb számúnak pedig tedd kisebbé az ő örökségét; mindeniknek az ő száma szerint adattassék az ő öröksége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'De sorssal osztassék el a föld; az ő atyjok törzseinek nevei szerint örököljenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'A sors szerint osztassék el az örökség, mind a sok és mind a kevés között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'Ezek pedig Lévi megszámláltjai az ő nemzetségeik szerint: Gérsontól a Gérsoniták nemzetsége; Kéháttól a Kéhátiták nemzetsége; Méráritól a Méráriták nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'Ezek Lévi nemzetségei: a Libniták nemzetsége, a Hébroniták nemzetsége, a Makhliták nemzetsége, a Músiták nemzetsége, a Kórahiták nemzetsége. Kéhát pedig nemzé Amrámot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'Amrám feleségének neve pedig Jókebed, a Lévi leánya, a ki Égyiptomban született Lévinek; és ő szülte Amrámnak Áront, Mózest, és Miriámot, az ő leánytestvéröket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'És születének Áronnak: Nádáb és Abihu, Eleázár és Ithamár.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'És meghalának Nádáb és Abihu, mikor idegen tűzzel áldozának az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'És vala azoknak száma: huszonhárom ezer, mind férfiak, egy hónapostól fogva és feljebb; mert nem voltak beszámlálva az Izráel fiai közé, mivel nem adatott nékik örökség Izráel fiai között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'Ezek Mózesnek és Eleázárnak, a papnak megszámláltjai, a kik megszámlálák Izráel fiait a Moáb mezőségében, Jérikhó átellenében a Jordán mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'Ezek között pedig nem volt senki a Mózestől és Áron paptól megszámláltattak közűl, mikor megszámlálták vala Izráel fiait a Sinai pusztájában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, 'Mert az Úr mondotta vala nékik: Bizonynyal meghalnak a pusztában; és senki nem maradt meg azok közül, hanem csak Káleb, a Jefunné fia, és Józsué, a Nún fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, 'Előállának pedig a Czélofhád leányai, a ki Héfer fia vala, a ki Gileád fia, a ki Mákir fia, a ki Manasse fia vala, József fiának, Manassénak nemzetségei közül. Ezek pedig az ő leányainak neveik: Makhla, Nóa, Hogla, Milkha és Thircza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'És megállának Mózes előtt, és Eleázár pap előtt, és a fejedelmek előtt, és az egész gyülekezet előtt a gyülekezet sátorának nyilásánál, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, 'A mi atyánk meghalt a pusztában, de ő nem volt azoknak seregében, a kik összeseregeltek volt az Úr ellen a Kóré seregében; hanem az ő bűnéért holt meg, és fiai nem voltak néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'Miért töröltetnék el a mi atyánknak neve az ő nemzetsége közül, azért, hogy nincsen őnéki fia? Adj örökséget nékünk a mi atyánknak atyjafiai között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'Mózes pedig vivé ezeknek ügyét az Úr elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'És szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, 'Igazat szólnak a Czélofhád leányai: Adj nékik örökségi birtokot az ő atyjoknak atyjafiai között, és szállítsd rájok az ő atyjoknak örökségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'Izráel fiainak pedig szólj, mondván: Mikor valaki meghal, és fia nem leend annak, akkor adjátok annak örökségét az ő leányának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'Ha pedig nem leend néki leánya, akkor adjátok az ő örökségét az ő testvéreinek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'Ha pedig nem leendenek néki testvérei, akkor adjátok az ő örökségét az ő atyja testvéreinek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'Ha pedig nem leendenek az ő atyjának testvérei, akkor adjátok az ő örökségét annak, a ki legközelebbi atyjafia az ő nemzetségéből, és bírja azt. Legyen pedig az Izráel fiainak végezett törvényök, a miképen megparancsolta az Úr Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, 'Monda azután az Úr Mózesnek: Menj fel az Abarim hegyére, és lásd meg a földet, a melyet Izráel fiainak adtam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'Miután pedig megláttad azt, takaríttatol te is a te népedhez, a miképen oda takaríttatott Áron, a te testvéred;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'Mivelhogy nem engedétek az én beszédemnek a Czin pusztájában, a gyülekezet versengésének idején, hogy megdicsőítettetek volna engemet ama vizeknél az ő szemeik előtt. Ezek a versengésnek vizei Kádesnél a Czin pusztájában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'Szóla azért Mózes az Úrnak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, 'Az Úr, a minden test lelkének Istene, rendeljen férfiút a gyülekezet fölé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'A ki kimenjen ő előttök, és a ki bemenjen ő előttök; a ki kivigye őket, és a ki bevigye őket, hogy ne legyen az Úr gyülekezete olyan mint a juhok, a melyeknek nincsen pásztoruk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'Az Úr pedig monda Mózesnek: Vedd melléd Józsuét a Nún fiát, a férfiút, a kiben lélek van, és tedd ő reá a te kezedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'És állasd őt Eleázár pap elé, és az egész gyülekezet elé, és adj néki parancsolatokat az ő szemeik előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'És a te dicsőségedet közöld ő vele, hogy hallgassa őt Izráel fiainak egész gyülekezete.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'Azután pedig álljon Eleázár pap elé, és kérdje meg őt az Urimnak ítélete felől az Úr előtt. Az ő szava szerint menjenek ki, és az ő szava szerint menjenek be, ő és Izráel minden fia ő vele, és az egész gyülekezet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'Úgy cselekedék azért Mózes, a miképen parancsolta vala az Úr néki; mert vevé Józsuét, és állatá őt Eleázár pap elé, és az egész gyülekezet elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'És tevé az ő kezét ő reá, és ada néki parancsolatokat, a miképen szólott vala az Úr Mózes által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'És szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, 'Parancsold meg Izráel fiainak, és mondd meg nékik: Ügyeljetek, hogy az én áldozatomat, kenyeremet kedves illatú tűzáldozatul a maga idejében áldozzátok nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, 'És mondd meg nékik: Ez a tűzáldozat, a melyet áldozzatok az Úrnak: egy esztendős, ép bárányokat, naponként kettőt, szüntelen való egészen égőáldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'Egyik bárányt reggel készítsd el, a másik bárányt pedig estennen készítsd el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'És egy efa lánglisztnek tizedrészét ételáldozatul, megelegyítve egy hin sajtolt olajnak negyedrészével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, 'Ez a szüntelen való egészen égőáldozat, a mely Sinai hegyen szereztetett kedves illatú tűzáldozatul az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'Annak italáldozatja pedig egy hinnek negyedrésze egy-egy bárányhoz. A szenthelyen adj italáldozatot, jó borból az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'A másik bárányt készítsd el estennen, a reggeli ételáldozat és annak italáldozatja szerint készítsd el azt, jóillatú tűzáldozatul az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, 'Szombatnapon pedig áldozz két ép bárányt, esztendősöket, és két tized efa lisztlángot olajjal elegyített ételáldozatul, annak italáldozatjával egybe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, 'Ez a szombati egészen égőáldozat szombatonként, a szüntelen való egészen égőáldozaton és annak italáldozatján kivül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, 'A ti hónapjaitok kezdetén is áldozzatok az Úrnak egészen égőáldozatul két fiatal tulkot, egy kost, és hét egyesztendős, ép bárányt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'És egy-egy tulok mellé olajjal elegyített három tized efa lánglisztet ételáldozatul, egy-egy kos mellé pedig olajjal elegyített két tized efa lánglisztet ételáldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'És egy-egy bárány mellé egy-egy tized efa lisztlángot olajjal elegyítve ételáldozatul; égőáldozat ez, kedves illatú tűzáldozat ez az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'Az azokhoz való italáldozat pedig legyen fél hin bor egy tulok mellé, egy harmad hin egy kos mellé, és egy negyed hin egy bárány mellé. Ez a hónapos egészen égőáldozat minden hónap kezdetén, az esztendőnek hónapjai szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'És egy kecskebakot is készítsetek el bűnért való áldozatul az Úrnak, a szüntelen való egészen égőáldozaton kívül, annak italáldozatával egyben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, 'Az első hónapban pedig, a hónapnak tizennegyedik napján az Úrnak páskhája van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'És e hónapnak tizenötödik napján is ünnep van; hét napon át kovásztalan kenyeret egyetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'Első napon legyen szent gyülekezés; semmi robota munkát ne végezzetek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'Hanem tűzáldozatul egészen égőáldozatot vigyetek az Úrnak: két fiatal tulkot, egy kost, egy esztendős bárányt hetet, a melyek épek legyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'És azoknak ételáldozata olajjal elegyített lisztláng legyen; három tizedrész efát tegyetek egy tulok mellé, és két tizedrészt egy kos mellé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'Egy-egy bárány mellé egy-egy tizedrészt tegyetek, a hét bárány szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'És bűnért való áldozatul egy bakot, hogy engesztelés legyen értetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'A reggeli egészen égőáldozaton kívül, (a mely szüntelen való égőáldozat) készítsétek el ezeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'Ezek szerint készítsetek naponként hét napon át kenyeret, kedves illatú tűzáldozatul az Úrnak; a szüntelen való egészen égőáldozaton kívül készíttessék az, annak italáldozatjával egyben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'A hetedik napon is legyen néktek szent gyülekezésetek; semmi robota munkát ne végezzetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, 'A zsengék napján is, a mikor új ételáldozatot visztek az Úrnak a ti hetes ünnepeteken: szent gyülekezésetek legyen néktek; semmi robota munkát ne végezzetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'Hanem vigyetek kedves illatul egészen égőáldozatot az Úrnak: két fiatal tulkot, egy kost, és esztendős bárányt hetet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'És azokhoz való ételáldozatul olajjal elegyített háromtized efa lisztlángot egy tulok mellé, két tizedet egy kos mellé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'Egy-egy bárány mellé egy-egy tizedrészt, a hét bárány szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'Egy kecskebakot is, hogy engesztelés legyen értetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'A szüntelen való egészen égőáldozaton és annak ételáldozatján kivül készítsétek ezeket: épek legyenek, azoknak italáldozatjokkal egyben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, 'A hetedik hónapban pedig a hónapnak első napján szent gyülekezésetek legyen néktek. Semmi robota munkát ne végezzetek; kürt zengésének napja legyen az néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'És készítsetek el kedves illatul egészen égőáldozatot az Úrnak, egy fiatal tulkot, egy kost, esztendős ép bárányt hetet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'És azokhoz ételáldozatul olajjal elegyített három tized efa lisztlángot a tulok mellé, két tizedrészt a kos mellé;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'És egy-egy tizedrészt egy-egy bárány mellé, a hét bárány szerint;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'És egy kecskebakot bűnért való áldozatul, hogy engesztelés legyen értetek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, 'az újhold egészen égőáldozatján és annak ételáldozatján kivül, és a szüntelen való egészen égőáldozaton és annak ételáldozatján, és azoknak italáldozatjokon kivül, az ő rendjök szerint, kedves illatú tűzáldozatul az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, 'E hetedik hónapnak tizedik napján is szent gyülekezésetek legyen néktek; és sanyargassátok meg magatokat, semmi munkát ne végezzetek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'És vigyetek az Úrnak kedves illatú egészen égőáldozatul: egy fiatal tulkot, egy kost, esztendős bárányt hetet, épek legyenek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'És azoknak ételáldozatául olajjal elegyített három tized efa lisztlángot a tulok mellé; két tizedrészt az egy kos mellé;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'Egy-egy tizedrészt egy-egy bárány mellé, a hét bárány szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'Egy kecskebakot bűnért való áldozatul, az engesztelésre való bűnáldozaton kivül, és a szüntelen való egészen égőáldozaton, annak ételáldozatán és azoknak italáldozatjokon kivül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, 'A hetedik hónapnak tizenötödik napján is szent gyülekezésetek legyen néktek; semmi robota munkát ne végezzetek, és az Úrnak ünnepét hét napon ünnepeljétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'És vigyetek az Úrnak egészen égőáldozatot, kedves illatú tűzáldozatul: tizenhárom fiatal tulkot, két kost, esztendős bárányt tizennégyet, épek legyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'És azoknak ételáldozatául olajjal elegyített lisztlángból három tizedrész efát egy-egy tulok mellé, a tizenhárom tulok szerint, két tizedrészt egy-egy kos mellé, a két kos szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'És egy-egy tizedrészt minden bárány mellé, a tizennégy bárány szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'És egy kecskebakot bűnért való áldozatul, a szüntelen való egészen égőáldozaton, annak ételáldozatján és italáldozatján kívül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'Másodnapon pedig tizenkét fiatal tulkot, két kost, tizennégy ép bárányt, esztendősöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'És azoknak ételáldozatjokat és italáldozatjokat, a tulkok mellé, a kosok mellé, a bárányok mellé, az ő számok szerint, a szokás szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'És egy kecskebakot bűnért való áldozatul, a szüntelen való egészen égőáldozaton, annak ételáldozatján és azoknak italáldozatjokon kivül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'Harmadnap pedig tizenegy fiatal tulkot, két kost, tizennégy ép bárányt, esztendősöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'És azoknak ételáldozatjokat és italáldozatjokat, a tulkok mellé, a kosok mellé és a bárányok mellé, az ő számok szerint, a szokás szerint;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'És egy kecskebakot bűnért való áldozatul, a szüntelen való egészen égőáldozaton és annak ételáldozatján és italáldozatján kivül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'Negyednapon pedig tíz fiatal tulkot, két kost, tizennégy ép bárányt, esztendősöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'Azoknak ételáldozatjokat és italáldozatjokat a tulkok mellé, a kosok mellé és a bárányok mellé, az ő számok szerint, a szokás szerint;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'És egy kecskebakot bűnért való áldozatul, a szüntelen való egészen égőáldozaton, annak ételáldozatján és italáldozatján kívül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'És ötödnapon kilencz fiatal tulkot, két kost, tizennégy ép bárányt, esztendősöket:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'És azoknak ételáldozatjokat és italáldozatjokat, a tulkok mellé, a kosok mellé és a bárányok mellé, azoknak számok szerint, a szokás szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'És egy bakot bűnért való áldozatul, a szüntelen való egészen égőáldozaton, annak ételáldozatján és italáldozatján kívül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'És hatodnapon nyolcz tulkot, két kost, tizennégy ép bárányt, esztendősöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'És azoknak ételáldozatjokat és italáldozatjokat a tulkok mellé, a kosok mellé és a bárányok mellé, az ő számok szerint, a szokás szerint;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'És egy bakot bűnért való áldozatul, a szüntelen való egészen égőáldozaton kívül, annak ételáldozatján és italáldozatján kívül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'És hetedik napon hét tulkot, két kost, tizennégy ép bárányt, esztendősöket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'És azoknak ételáldozatjokat és italáldozatjokat a tulkok mellé, a kosok mellé és a bárányok mellé, az ő számok szerint, a szokás szerint;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'És egy bakot bűnért való áldozatul, a szüntelen való egészen égőáldozaton kívül, annak ételáldozatján és italáldozatján kívül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'Nyolczadnapon bezáró ünnepetek legyen néktek, semmi robota munkát ne végezzetek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'Hanem vigyetek az Úrnak egészen égőáldozatot, kedves illatú tűzáldozatul: egy tulkot, egy kost, hét ép bárányt, esztendősöket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'Azoknak ételáldozatjokat és italáldozatjokat, a tulok mellé, a kos mellé, és a bárányok mellé, az ő számok szerint, a szokás szerint;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'És egy bakot bűnért való áldozatul, a szüntelen való egészen égőáldozaton, annak ételáldozatján és italáldozatján kívül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, 'Ezeket áldozzátok az Úrnak a ti ünnepeiteken, azokon kívül, a miket fogadásból, és szabad akaratból áldoztok, a ti egészen égőáldozataitokul, ételáldozataitokul, italáldozataitokul, és hálaáldozataitokul. És megmondá Mózes Izráel fiainak mind azokat, a melyeket az Úr parancsolt vala Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'És szóla Mózes az Izráel fiai közt lévő törzsek fejeinek, mondván: Ez az a beszéd, a melyet parancsolt az Úr:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, 'Ha valamely férfi fogadást fogad az Úrnak, vagy esküt tesz, hogy lekötelezze magát valami kötésre: meg ne szegje az ő szavát; a mint az ő szájából kijött, egészen úgy cselekedjék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, 'Ha pedig asszony fogad fogadást az Úrnak, és kötésre kötelezi le magát az ő atyjának házában az ő fiatalságában;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, 'És hallja az ő atyja az ő fogadását, vagy kötelezését, a melylyel lekötelezte magát, és nem szól arra az ő atyja: akkor megáll minden ő fogadása, és minden kötelezés is, a melylyel lekötelezte magát, megálljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, 'Ha pedig megtiltja azt az ő atyja azon a napon, a melyen hallotta: nem áll meg semmi fogadása és kötelezése, a melylyel lekötelezte magát, és az Úr is megbocsát néki, mert az ő atyja tiltotta meg azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, 'Ha pedig férjhez megy, és így terhelik őt az ő fogadásai vagy ajkán kiszalasztott szava, a melylyel lekötelezte magát;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, 'És hallja az ő férje, és nem szól néki azon a napon, a melyen hallotta azt: akkor megállanak az ő fogadásai, és az ő kötelezései is, a melyekkel lekötelezte magát, megálljanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, 'Ha pedig azon a napon, a melyen hallja a férje, megtiltja azt: akkor erőtlenné teszi annak fogadását, a melyet magára vett, és az ő ajakinak kiszalasztott szavát, a melylyel lekötelezte magát; és az Úr is megbocsát néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, 'Az özvegy asszonynak pedig és az elváltnak minden fogadása, a melylyel lekötelezi magát, megáll.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, 'Ha pedig az ő férjének házában tesz fogadást, vagy esküvéssel kötelezi magát valami kötésre:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, 'Ha hallotta az ő férje és nem szólt arra, nem tiltotta meg azt: akkor annak minden fogadása megáll, és minden kötelezése, a melylyel lekötelezte magát, megálljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, 'De ha a férje teljesen erőtlenné teszi azokat azon a napon, a melyen hallotta: nem áll meg semmi, a mi az ő ajakin kijött, sem fogadása, sem az ő maga lekötelezése; az ő férje erőtlenné tette azokat, és az Úr megbocsát néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, 'Minden fogadását, és minden esküvéssel való kötelezését a maga megsanyargattatására, a férje teszi erőssé, és a férje teszi azt erőtlenné.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, 'Hogyha nem szólván nem szól néki a férje egy naptól fogva más napig, akkor megerősíti minden fogadását, vagy minden kötelezését, a melyeket magára vett; megerősíti azokat, mert nem szól néki azon a napon, a melyen hallotta azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, 'Ha pedig azután teszi erőtelenekké azokat, minekutána hallotta vala: ő hordozza az ő bűnének terhét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, 'Ezek azok a rendelések, a melyeket parancsolt az Úr Mózesnek, a férj és az ő felesége között, az atya és leánya között, mikor még fiatalságában az ő atyjának házában van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 17, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, 'És szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, 'Állj bosszút Izráel fiaiért a Midiánitákon, azután a te népeidhez takaríttatol.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'Szóla azért Mózes a népnek, mondván: Készítsétek fel magatok közül a viadalra való embereket, és induljanak Midián ellen, hogy bosszút álljanak az Úrért Midiánon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'Ezret-ezret egy-egy törzsből, Izráelnek minden törzséből küldjetek a hadba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'Kiválogatának azért Izráel ezereiből, ezeret törzsenként, tizenkét ezeret, viadalra készet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'És elküldé őket Mózes, törzsenként ezeret-ezeret a hadba, és velök Fineást, Eleázár papnak fiát is a hadba; és a szent edények és a riadó kürtök valának az ő keze alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'És harczolának Midián ellen, a miképen megparancsolta vala az Úr Mózesnek, és minden férfiút megölének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'A Midián királyait is megölék, azoknak levágott népeivel egybe: Evit, Rékemet, Czúrt, Húrt, és Rebát, Midiánnak öt királyát; és Bálámot a Beór fiát is megölék fegyverrel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'És fogságba vivék Izráel fiai a Midiániták feleségeit és azoknak kisdedeit, és azoknak minden barmát és minden nyáját, és minden vagyonát prédára veték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'Minden városukat pedig az ő lakhelyeik szerint, és minden falvaikat tűzzel megégeték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'És elvivének minden ragadományt és minden prédát mind emberekből, mind barmokból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'És vivék Mózeshez és Eleázár paphoz, és Izráel fiainak gyülekezetéhez a foglyokat, a prédát és a ragadományokat a táborba, a mely a Moáb mezőségén vala a Jordán mellett, Jérikhó átellenében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'Kimenének azért Mózes és Eleázár pap, és a gyülekezetnek minden fejedelme ő eléjök a táboron kívül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'És megharaguvék Mózes a hadnak vezetőire, az ezredesekre és századosokra, a kik megjöttek vala a harczról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'És monda nékik Mózes: Megtartottátok-é életben mind az asszonyokat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'Ímé ők voltak, a kik Izráel fiait Bálám tanácsából hűtlenségre bírták az Úr ellen a Peór dolgában; és lőn csapás az Úr gyülekezetén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'Most azért öljetek meg a kisdedek közül minden fineműt; és minden asszonyt is, a ki férfit ismert azzal való hálás végett, megöljetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'Minden leánygyermeket pedig, a kik nem háltak férfiúval, tartsatok életben magatoknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'Ti pedig maradjatok a táboron kivül hét napig; a ki megölt valakit, és a ki hullát érintett, mind tisztítsátok meg magatokat harmad és hetednapon, magatokat és foglyaitokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'Minden ruhát, minden bőrből való eszközt, minden kecskeszőrből való készítményt és minden faedényt; tisztítsátok meg magatokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'És monda Eleázár pap a vitézeknek, a kik elmentek vala a hadba: Ez a törvény rendelése, a melyet parancsolt vala az Úr Mózesnek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, 'Az aranyat, ezüstöt, rezet, vasat, az ónt és ólmot bizonyára;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'Minden egyebet is, a mi állja a tüzet, vigyetek át a tűzön, és megtisztíttatik, de a tisztító vízzel is tisztíttassék meg; mindazt pedig, a mi nem állja a tűzet, vízen vigyétek át.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'Ruháitokat pedig mossátok meg a hetedik napon, és tiszták lesztek: és azután bemehettek a táborba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'Újra szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, 'Vedd számba az elfoglalt prédát, mind emberben, mind baromban, te és Eleázár, a pap, és a gyülekezet atyáinak fejei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'És oszszad a prédát két részre: a hadakozók között, a kik hadba mentek, és az egész gyülekezet között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'És végy részt az Úrnak a hadakozó férfiaktól, akik hadba mentek: ötszázból egy lelket, az emberek közül, az ökrök közül, a szamarak közül, és a juhok közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'Azoknak fele részéből vegyétek, és adjad Eleázárnak, a papnak, felemelt áldozatul az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'Az Izráel fiainak járó fele részből pedig egy elfogottat végy ötvenből: emberekből, ökrökből, szamarakból, juhokból, és minden baromból; és adjad azokat a lévitáknak, a kik ügyelnek az Úr hajlékának ügyére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'És úgy cselekedék Mózes és Eleázár, a pap, a miképen parancsolta vala az Úr Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'És vala az a préda, azaz annak a zsákmánynak maradéka, a mit a hadakozó nép zsákmányolt: hatszáz hetvenöt ezer juh.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, 'És hetvenhét ezer ökör.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, 'És hatvanegy ezer szamár.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'Emberi lélek pedig: a leányok közül, a kik nem ismertek vala férfival való egyesülést, ilyen lélek összesen harminczkét ezer.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'Vala pedig az egyik fele, azoknak része, a kik hadba mentek vala: számszerint háromszáz harminczhét ezer és ötszáz juh.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'Vala pedig az Úrnak része a juhokból: hatszáz és hetvenöt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, 'Az ökör pedig: harminczhat ezer; és azokból az Úrnak része: hetvenkettő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'És a szamár: harmincz ezer és ötszáz; azokból az Úrnak része: hatvanegy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'Emberi lélek pedig tizenhat ezer; és azokból az Úrnak része: harminczhét lélek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'És adá Mózes az Úrnak részét felemelt áldozatul Eleázárnak, a papnak, a miképen parancsolta vala az Úr Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'Az Izráel fiainak eső másik fele részből pedig, a melyet elválasztott Mózes a hadakozó férfiakétól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, '(Vala pedig a gyülekezetre eső felerész juhokból: háromszáz harminczhét ezer és ötszáz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, 'Ökör: harminczhat ezer;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, 'Szamár: harmincz ezer és ötszáz:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'Emberi lélek: tizenhat ezer.)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'Az Izráel fiainak eső fele részből pedig egy elfogottat vett Mózes ötvenből, az emberekből és a barmokból; és adá azokat a lévitáknak, a kik ügyelnek az Úr hajlékának ügyére, a miképen parancsolta vala az Úr Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'És járulának Mózeshez a had ezereinek vezetői, az ezredesek és századosok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'És mondának Mózesnek: Szolgáid megszámlálták a hadakozó férfiakat, a kik a mi kezünk alatt voltak, és senki közülünk el nem veszett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'Hoztunk azért az Úrnak való áldozatul kiki a mit talált: aranyeszközöket, karlánczokat, karpereczeket, gyűrűket, fülönfüggőket, nyaklánczokat, hogy engesztelést végezzünk a mi lelkünkért az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'És elvevé Mózes és Eleázár, a pap, az aranyat ő tőlök, és a megkészített eszközöket is mind.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'És mindaz az arany, a melyet felemelt áldozatul vivének az Úrnak, tizenhat ezer hétszáz és ötven siklus vala az ezeredesektől és századosoktól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, 'A hadakozó férfiak közül kiki magának zsákmányolt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'Miután elvette vala Mózes és Eleázár, a pap, az aranyat az ezeredesektől és századosoktól, bevivék azt a gyülekezetnek sátorába, Izráel fiaira való emlékeztetőül az Úr elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'Rúben fiainak pedig és Gád fiainak igen sok barmok vala. Mikor látták a Jázér földét és a Gileád földét, hogy ímé az a hely marhatartani való hely:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'Eljövének Gád fiai és Rúben fiai, és szólának Mózesnek és Eleázárnak, a papnak, és a gyülekezet fejedelmeinek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, 'Atárót, Díbon, Jázér, Nimra, Hesbon, Elealé, Sebám, Nébó és Béon:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'A föld, a melyet megvert az Úr az Izráel fiainak gyülekezete előtt, baromtartó föld az; a te szolgáidnak pedig sok marhájok van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, 'És mondának: Hogyha kedvet találtunk a te szemeid előtt, adassék ez a föld a te szolgáidnak örökségül, ne vígy minket át a Jordánon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'Mózes pedig monda a Gád fiainak és Rúben fiainak: Avagy a ti atyátokfiai hadakozni menjenek, ti pedig itt maradjatok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'És miért idegenítitek el Izráel fiainak szívét, hogy által ne menjenek a földre, a melyet adott nékik az Úr?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'A ti atyáitok cselekedtek így, mikor elbocsátám őket Kádes-Bárneából, hogy nézzék meg azt a földet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'Mert felmentek az Eskól völgyéig, és megnézék a földet, és elidegeníték Izráel fiainak szívét, hogy be ne menjenek arra a földre, a melyet adott vala nékik az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'Azért megharaguvék az Úr azon a napon, és megesküvék, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, 'Nem látják meg azok az emberek, a kik feljöttek Égyiptomból, húsz esztendőstől fogva és feljebb, azt a földet, a mely felől megesküdtem Ábrahámnak, Izsáknak és Jákóbnak, mivelhogy nem tökéletesen jártak én utánam;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, 'Kivéve a Kenizeus Kálebet, a Jefunné fiát és Józsuét, a Nún fiát, mivelhogy tökéletesen jártak az Úr után.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'És megharaguvék az Úr Izráelre, és bujdostatá őket a pusztában negyven esztendeig; míg megemészteték az egész nemzetség, a mely gonoszt cselekedett vala az Úr szemei előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'És ímé feltámadtatok a ti atyáitok helyett, bűnös emberek maradékai, hogy az Úr haragjának tüzét még öregbítsétek Izráel ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'Hogyha elfordultok az ő utaitól, még tovább is otthagyja őt a pusztában, és elvesztitek mind az egész népet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'És járulának közelebb ő hozzá, és mondának: Barmainknak juhaklokat építünk itt, és a mi kicsinyeinknek városokat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'Magunk pedig felfegyverkezve, készséggel megyünk Izráel fiai előtt, míg beviszszük őket az ő helyökre; gyermekeink pedig a kerített városokban maradnak e földnek lakosai miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'Vissza nem térünk addig a mi házainkhoz, a míg Izráel fiai közül meg nem kapja kiki az ő örökségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'Mert nem veszünk mi részt az örökségben ő velök a Jordánon túl és tovább, mivelhogy meg van nékünk a mi örökségünk a Jordánon innen napkelet felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'És monda nékik Mózes: Ha azt cselekszitek, a mit szóltok; ha az Úr előtt készültök fel a hadra;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'És átmegy közületek minden fegyveres a Jordánon az Úr előtt, míg kiűzi az ő ellenségeit maga előtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'És csak azután tértek vissza, ha az a föld meghódol az Úr előtt: akkor ártatlanok lesztek az Úr előtt, és Izráel előtt, és az a föld birtokotokká lesz néktek az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'Hogyha nem így cselekesztek, ímé vétkeztek az Úr ellen; és gondoljátok meg, hogy a ti bűnötöknek büntetése utólér benneteket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, 'Építsetek magatoknak városokat a ti kicsinyeitek számára, és a ti juhaitoknak aklokat; de a mit fogadtatok, azt megcselekedjétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'És szólának Gád fiai és Rúben fiai Mózesnek, mondván: A te szolgáid úgy cselekesznek, a mint az én Uram parancsolja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, 'A mi kicsinyeink, feleségeink, juhaink és mindenféle barmaink ott lesznek Gileád városaiban;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'A te szolgáid pedig átmennek mindnyájan hadra felkészülve, harczolni az Úr előtt, a miképen az én Uram szól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'Parancsot ada azért ő felőlök Mózes Eleázárnak, a papnak, és Józsuénak a Nún fiának, és az Izráel fiai törzseiből való atyák fejeinek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'És monda nékik Mózes: Ha átmennek a Gád fiai és a Rúben fiai veletek a Jordánon, mindnyájan hadakozni készen az Úr előtt, és meghódol a föld ti előttetek: akkor adjátok nékik a Gileád földét birtokul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'Ha pedig nem mennek át fegyveresen veletek, akkor veletek kapjanak birtokot a Kanaán földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'És felelének a Gád fiai és a Rúben fiai, mondván: A mit mondott az Úr a te szolgáidnak, akképen cselekeszünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'Mi átmegyünk fegyveresen az Úr előtt a Kanaán földére, de miénk legyen a mi örökségünknek birtoka a Jordánon innen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'Nékik adá azért Mózes, tudniillik a Gád fiainak, a Rúben fiainak és a József fiának, Manasse féltörzsének, Szihonnak, az Emoreusok királyának országát, és Ógnak, Básán királyának országát; azt a földet az ő városaival, határaival, annak a földnek városait köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'És megépíték a Gád fiai Dibont, Ataróthot, Aroért,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'Atróth-Sofánt, Jázért, Jogbehát,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'Beth-Nimrát, és Beth-Haránt, kerített városokat juhaklokkal egyben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'A Rúben fiai pedig megépíték Hesbont, Elealét, Kirjáthaimot,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'Nébót, Baál-Meont, (változtatott néven nevezve) és Sibmát. És új neveket adának a városoknak, a melyeket építének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'Mákirnak, a Manasse fiának fiai pedig Gileádba vonulának, és bevevék azt, és kiűzék az Emoreust, a ki ott vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'Adá azért Mózes Gileádot Mákirnak, a Manasse fiának, és lakozék abban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'Jáir pedig, a Manasse fia elméne, és bevevé azoknak falvait, és hívá azokat Jáir falvainak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'Nóbah is elméne, és bevevé Kenáthot és annak városait, és hívá azt Nóbáhnak, a maga nevéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'Ezek Izráel fiainak szállásai, a kik kijövének Égyiptom földéből az ő seregeik szerint Mózes és Áron vezetése alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, '(Megírá pedig Mózes az ő kijövetelöket az ő szállásaik szerint, az Úrnak rendeletére.) Ezek az ő szállásaik, az ő kijövetelök szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'Elindulának Rameszeszből az első hónapban, az első hónap tizenötödik napján. A páskha után való napon jövének ki Izráel fiai felemelt kézzel, az egész Égyiptom láttára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, '(Az égyiptombeliek pedig temetik vala azokat a kiket megölt vala az Úr ő közöttök, minden elsőszülöttjöket; az isteneiken is ítéletet tartott vala az Úr.)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'És elindulának Izráel fiai Rameszeszből, és tábort ütének Szukkótban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'És elindulának Szukkótból, és tábort ütének Ethámban, a mely van a pusztának szélén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'És elindulának Ethámból, és fordulának Pihahiróth felé, a mely van Baál-Czefon előtt, és tábort ütének Migdol előtt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'És elindulának Pihahiróthból, és átmenének a tenger közepén a pusztába; és menének három napi járásnyira az Ethám pusztáján; és tábort ütének Márában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'És elindulának Márából, és jutának Élimbe; Élimben pedig vala tizenkét kútfő és hetven pálmafa; és tábort ütének ott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'És elindulának Élimből, és tábort ütének a Veres tenger mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'És elindulának a Veres tengertől, és tábort ütének a Szin pusztájában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'És elindulának a Szin pusztájából, és tábort ütének Dofkában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'És elindulának Dofkából, és tábort ütének Álúsban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'És elindulának Álúsból, és tábort ütének Refidimben, de nem vala ott a népnek inni való vize.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'És elindulának Refidimből, és tábort ütének a Sinai pusztájában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'És elindulának a Sinai pusztájából, és tábort ütének Kibrót-Thaavában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'És elindulának Kibrót-Thaavából, és tábort ütének Haserótban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'És elindulának Haserótból, és tábort ütének Rithmában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'És elindulának Rithmából, és tábort ütének Rimmon-Péreczben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'És elindulának Rimmon-Péreczből, és tábort ütének Libnában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'És elindulának Libnából, és tábort ütének Risszában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'És elindulának Risszából, és tábort ütének Kehélátban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'És elindulának Kehélátból, és tábort ütének a Séfer hegyénél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'És elindulának a Séfer hegyétől és tábort ütének Haradában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'És elindulának Haradából, és tábort ütének Makhélótban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'És elindulának Makhélótból, és tábort ütének Tháhátban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'És elindulának Tháhátból, és tábort ütének Thárakhban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'És elindulának Thárakhból, és tábort ütének Mitkában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'És elindulának Mitkából, és tábort ütének Hasmonában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'És elindulának Hasmonából, és tábort ütének Moszérótban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'És elindulának Moszérótból, és tábort ütének Bené-Jaakánban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'És elindulának Bené-Jaakánból, és tábort ütének Hór-Hagidgádban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'És elindulának Hór-Hagidgádból, és tábort ütének Jotbathában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'És elindulának Jotbathából, és tábort ütének Abronában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'És elindulának Abronából, és tábort ütének Eczjon-Geberben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'És elindulának Eczjon-Geberből, és tábort ütének Czin pusztájában; ez Kádes.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'És elindulának Kádesből, és tábort ütének a Hór hegyénél, az Edom földének szélén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'Felméne pedig Áron, a pap, a Hór hegyére az Úr rendelése szerint, és meghala ott a negyvenedik esztendőben, Izráel fiainak Égyiptom földéből való kijövetelök után, az ötödik hónapban, a hónap elsején.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'Áron pedig száz és huszonhárom esztendős vala, mikor meghala a Hór hegyén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'Hallott pedig a Kananeus, Arad királya (ez pedig dél felől lakozik vala a Kanaán földén) Izráel fiainak jövetele felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'És elindulának a Hór hegyétől, és tábort ütének Czalmonában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'És elindulának Czalmonából, és tábort ütének Púnonban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'És elindulának Púnonból, és tábort ütének Obothban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'És elindulának Obothból, és tábort ütének Ijé-Abárimban, a Moáb határán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'És elindulának Ijé-Abárimból, és tábort ütének Dibon-Gádban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'És elindulának Dibon-Gádból, és tábort ütének Almon-Diblathaimban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'És elindulának Almon-Diblathaimból, és tábort ütének az Abarim hegységnél, Nébó ellenében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'És elindulának az Abarim hegységétől, és tábort ütének a Moáb mezőségén, a Jordán mellett, Jérikhó ellenében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'Tábort ütének pedig a Jordán mellett, Beth-Hajjesimóthtól Abel-Hassittimig, a Moáb mezőségén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'És szóla az Úr Mózesnek a Moáb mezőségén, a Jordán mellett, Jerikhó ellenében, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, 'Szólj Izráel fiainak, és mondd meg nékik: Mikor átmentek ti a Jordánon a Kanaán földére:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'Űzzétek ki akkor a földnek minden lakosát a ti színetek elől, és veszessétek el minden írott képeiket, és minden ő öntött bálványképeiket is elveszessétek, és minden magaslataikat rontsátok el!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'Űzzétek ki a földnek lakóit, és lakozzatok abban; mert néktek adtam azt a földet, hogy bírjátok azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'Azt a földet pedig sorsvetés által vegyétek birtokotokba a ti nemzetségeitek szerint. A nagyobb számúnak nagyobbítsátok az ő örökségét, a kisebb számúnak kisebbítsd az ő örökségét. A hová a sors esik valaki számára, az legyen az övé. A ti atyáitoknak törzsei szerint vegyétek át birtokotokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'Ha pedig nem űzitek ki annak a földnek lakosait a ti színetek elől, akkor, a kiket meghagytok közülök, szálkákká lesznek a ti szemeitekben, és tövisekké a ti oldalaitokban, és ellenségeitek lesznek néktek a földön, a melyen lakoztok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'És akkor a miképen gondoltam, hogy cselekszem azokkal, úgy cselekszem majd veletek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'És szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, 'Parancsold meg Izráel fiainak, és mondd meg nékik: Hogyha bementek ti a Kanaán földére; (ez a föld, a mely örökségűl esik néktek, tudniillik a Kanaán földe az ő határai szerint),');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'Akkor legyen a ti déli oldalatok a Czin pusztájától fogva Edom határáig, és legyen a ti déli határotok a Sós tenger végétől napkelet felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'És kerüljön a határ dél felől az Akrabbim hágójáig, és menjen át Czinig, és a vége legyen Kádes-Barneától délre; és menjen tova Haczár-Adárig, és menjen át Aczmonig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'Azután kerüljön a határ Aczmontól Égyiptom patakáig, a vége pedig a tengernél legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'A napnyugoti határotok pedig legyen néktek a nagy tenger; ez legyen néktek a napnyugoti határotok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'Ez legyen pedig a ti északi határotok: a nagy tengertől fogva vonjatok határt a Hór hegyének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'A Hór hegyétől vonjatok határt a Hamáthba való bejárásig; a határnak vége pedig Czedádnál legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'És tovamenjen a határ Zifronig, a vége pedig Haczar-Enán legyen. Ez legyen néktek az északi határotok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'A napkeleti határt pedig vonjátok Haczar-Enántól Sefámig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'És hajoljon le a határ Sefámtól Ribláig, Aintól napkeletre; és újra hajoljon le a határ, és érje a Kinnéreth tenger partját napkelet felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'Azután hajoljon le a határ a Jordán felé, a vége pedig a Sós tenger legyen. Ez legyen a ti földetek az ő határai szerint köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'És parancsot ada Mózes Izráel fiainak, mondván: Ez az a föld, a melyet sors által vesztek birtokotokba, a mely felől parancsot ada az Úr, hogy adjam azt kilencz törzsnek, és fél törzsnek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'Mert megkapták a Rúbeniták fiainak törzse az ő atyáiknak háza szerint, a Gáditák fiainak törzse, az ő atyáiknak háza szerint, és a Manasse fél törzse is, megkapták az ő örökségöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'Két törzs és egy fél törzs megkapta az ő örökségét a Jordánon túl, Jérikhó ellenében napkelet felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'Szóla azután az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, 'Ezek azoknak a férfiaknak nevei, a kik örökségül fogják néktek elosztani azt a földet: Eleázár, a pap, és Józsué, a Nún fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'És törzsenként egy-egy fejedelmet vegyetek mellétek a földnek örökségül való elosztására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'Ezek a férfiaknak nevei: a Júda törzséből Káleb, a Jefunné fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'A Simeon fiainak törzséből Sámuel, az Ammihúd fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'A Benjámin törzséből Elidád, a Kiszlon fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'A Dán fiainak törzséből Bukki fejedelem, a Jógli fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'A József fia közül, a Manasse fiainak törzséből Hanniél fejedelem, az Efód fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'Az Efraim fiainak törzséből Kemuél fejedelem, a Siftán fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'És a Zebulon fiainak törzséből Eliczáfán fejedelem, a Parnák fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'És az Izsakhár fiainak törzséből Paltiél fejedelem, az Azzán fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'És az Áser fiainak törzséből Akhihúd fejedelem, a Selómi fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'És a Nafthali fiainak törzséből Pédahél fejedelem, az Ammihúd fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'Ezek azok, a kiknek megparancsolá az Úr, hogy örökséget oszszanak Izráel fiainak a Kanaán földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'És szóla az Úr Mózesnek a Moáb mezőségén a Jordán mellett, Jérikhó ellenében, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, 'Parancsold meg Izráel fiainak, hogy adjanak a lévitáknak az ő örökségi birtokukból lakásra való városokat; a városokhoz pedig adjatok azok környékén legelőt is a lévitáknak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'Hogy legyenek nékik a városok lakóhelyekül, a legelők pedig legyenek az ő barmaiknak, jószágaiknak és mindenféle állatjoknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'És azoknak a városoknak legelői, a melyeket a lévitáknak adtok, a város falától és azon kivül, ezer singnyire legyenek köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'Mérjetek azért a városon kivül, napkelet felől két ezer singet, dél felől is kétezer singet, napnyugot felől kétezer singet, és észak felől kétezer singet; és a város legyen középben. Ez legyen számukra a városok legelője.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'A városok közül pedig, a melyeket a lévitáknak adtok, hat legyen menedékváros, a melyeket azért adjatok, hogy oda szaladjon a gyilkos; és azokon kivül adjatok negyvenkét várost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'Mind a városok, a melyeket adnotok kell a lévitáknak, negyvennyolc város, azoknak legelőivel egyben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'A mely városokat pedig Izráel fiainak örökségéből adtok, azokhoz attól, a kinek több van, többet vegyetek, és attól, a kinek kevesebb van, kevesebbet vegyetek; mindenik az ő örökségéhez képest, a melyet örökül kapott, adjon az ő városaiból a lévitáknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'És szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, 'Szólj Izráel fiainak, és mondd meg nékik: Mikor átmentek ti a Jordánon a Kanaán földére:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'Válaszszatok ki magatoknak városokat, a melyek menedékvárosaitok legyenek, hogy oda szaladjon a gyilkos, a ki történetből öl meg valakit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'És legyenek azok a ti városaitok menedékül a vérbosszuló ellen, és ne haljon meg a gyilkos, míg ítéletre nem áll a gyülekezet elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'A mely városokat pedig oda adtok, azok közül hat legyen néktek menedékvárosul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'Három várost adjatok a Jordánon túl, és három várost adjatok a Kanaán földén; menedékvárosok legyenek azok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'Izráel fiainak és a jövevénynek, és az ő közöttök lakozónak menedékül legyen az a hat város, hogy oda szaladjon az, a ki történetből öl meg valakit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, 'De ha valaki vaseszközzel úgy üt meg valakit, hogy meghal, gyilkos az; halállal lakoljon a gyilkos.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'És ha kézben levő kővel, a melytől meghalhat, üti meg úgy, hogy meghal, gyilkos az; halállal lakoljon a gyilkos.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'Vagy ha kézben lévő faeszközzel, a melytől meghalhat, üti meg úgy, hogy meghal, gyilkos az; halállal lakoljon a gyilkos.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'A vérbosszuló rokon ölje meg a gyilkost; mihelyt találkozik vele, ölje meg azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'Hogyha gyűlölségből taszítja meg őt, vagy szántszándékkal úgy hajít valamit reá, hogy meghal;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'Vagy ellenségeskedésből kezével üti meg azt úgy, hogy meghal: halállal lakoljon az, a ki ütötte; gyilkos az; a vérbosszuló rokon ölje meg azt a gyilkost, mihelyt találkozik vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, 'Ha pedig hirtelenségből, ellenségeskedés nélkül taszítja meg őt; vagy nem szántszándékból hajít reá akármiféle eszközt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'Vagy akármiféle követ, a melytől meghalhat, úgy ejt valakire, a kit nem látott, hogy meghal, holott nem volt ő annak ellensége, sem nem kereste annak vesztét:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'Akkor ítéljen a gyülekezet az agyonütő között és a vérbosszuló rokon között e törvények szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'És mentse ki a gyülekezet a gyilkost a vérbosszuló rokonnak kezéből, és küldje vissza azt a gyülekezet az ő menedékvárosába, a melybe szaladott vala, és lakozzék abban, míg meghal a főpap, a ki felkenetett a szent olajjal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'Ha pedig kimegy a gyilkos az ő menedékvárosának határából, a melybe szaladott vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'És találja őt a vérbosszuló rokon az ő menedékvárosának határán kivül, és megöli az a vérbosszuló rokon a gyilkost: nem lesz annak vére ő rajta;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'Mert az ő menedékvárosában kell laknia a főpap haláláig; a főpap halála után pedig visszatérhet a gyilkos az ő örökségének földére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'És legyenek ezek néktek ítéletre való rendelések a ti nemzetségeitek szerint, minden lakhelyeteken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'Ha valaki megöl valakit, tanúk szavára gyilkolják meg a gyilkost; de egy tanú nem lehet elég tanú senki ellen, hogy meghaljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'Az olyan gyilkos életéért pedig ne vegyetek el váltságot, a ki halálra való gonosz, hanem halállal lakoljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'Attól se vegyetek váltságot, a ki az ő menedékvárosába szaladt, hogy visszamehessen és otthon lakozzék a főpap haláláig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'És meg ne fertőztessétek a földet, a melyben lesztek; mert a vér, az megfertézteti a földet, és a földnek nem szerezhető engesztelés a vér miatt, a mely kiontatott azon, csak annak vére által, a ki kiontotta azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'Ne tisztátalanítsd meg azért azt a földet, a melyben laktok, a melyben én is lakozom; mert én, az Úr, Izráel fiai között lakozom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'Járulának pedig Mózeshez az atyák fejei a Gileád fiainak nemzetségéből, a ki Mákirnak, Manasse fiának fia vala, a József fiainak nemzetségéből, és szólának Mózes előtt és Izráel fiai atyáinak fejedelmei előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, 'És mondának: Az én uramnak megparancsolta az Úr, hogy sors által adja ezt a földet örökségül Izráel fiainak; de azt is megparancsolta az Úr az én Uramnak, hogy a mi atyánkfiának, Czélofhádnak örökségét adja oda az ő leányainak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'És ha Izráel fiai közül valamely más törzs fiaihoz mennek feleségül: elszakasztatik az ő örökségök a mi atyáink örökségétől, és oda csatoltatik az annak a törzsnek örökségéhez, a melynél feleségül lesznek; a mi örökségünk pedig megkisebbedik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'És mikor Izráel fiainál a kürtzengés ünnepe lesz, az ő örökségök akkor is annak a törzsnek örökségéhez csatoltatik, a melynél feleségül lesznek. Eképen a mi atyáink törzseinek örökségéből vétetik el azok öröksége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'Parancsot ada azért Mózes Izráel fiainak az Úr rendelése szerint, mondván: A József fiainak törzse igazat szól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'Ez az, a mit parancsolt az Úr a Czélofhád leányai felől, mondván: A kihez jónak látják, ahhoz menjenek feleségül, de csak az ő atyjok törzsének háznépéből valóhoz menjenek feleségül,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'Hogy át ne szálljon Izráel fiainak öröksége egyik törzsről a másik törzsre; hanem Izráel fiai közül kiki ragaszkodjék az ő atyái törzsének örökségéhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'És minden leányzó, a ki örökséget kap Izráel fiainak törzsei közül, az ő atyja törzsebeli háznépből valóhoz menjen feleségül, hogy Izráel fiai közül kiki megtartsa az ő atyáinak örökségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'És ne szálljon az örökség egyik törzsről a másik törzsre, hanem Izráel fiainak törzsei közül kiki ragaszkodjék az ő örökségéhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'A miképen megparancsolta vala az Úr Mózesnek, a képen cselekedtek vala a Czélofhád leányai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'Mert Makhla, Thircza, Hogla, Milkha és Nóa, a Czélofhád leányai, az ő nagybátyjok fiaihoz mentek vala feleségül;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'A József fiának, Manassé fiainak nemzetségéből valókhoz mentek vala feleségül; és lőn azoknak öröksége az ő atyjok nemzetségének törzsénél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'Ezek a parancsolatok és végzések, a melyeket Mózes által parancsolt az Úr Izráel fiainak, Moáb mezőségén a Jordán mellett, Jérikhó ellenében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'Ezek az igék, a melyeket szólott Mózes az egész Izráelnek, a Jordánon túl a pusztában, a mezőségen, a Veres tenger ellenében, Párán és Tófel, és Lábán és Haczéróth, és Dizaháb között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, 'Tizenegy napi járóföldön Hórebtől fogva, a Szeir hegyének menve, Kádes-Barneáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, 'Lőn pedig a negyvenedik esztendőben, a tizenegyedik hónapban, a hónapnak első napján, szóla Mózes az Izráel fiainak mind a szerint, a mint parancsolt vala az Úr néki azok felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'Minekutána megverte vala Szihont az Emoreusok királyát, a ki lakik vala Hesbonban, és Ógot, Básánnak királyát Edreiben, a ki lakik vala Asthárótban:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'A Jordánon túl, a Moáb földén, kezdé Mózes magyarázni ezt a törvényt, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, 'Az Úr, a mi Istenünk szólott nékünk a Hóreben, ezt mondván: Elég ideig laktatok e hegy alatt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, 'Forduljatok meg, és induljatok, és menjetek az Emoreusok hegyére, és annak minden szomszéd vidékére, a mezőségen, és a hegyes-völgyes földön, és dél felé, és a tengernek partján, a Kananeusok földére és a Libánusra, a nagy folyóvízig, az Eufrates folyóig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'Ímé előtökbe adtam a földet; menjetek be, és bírjátok azt a földet, a mely felől megesküdt az Úr a ti atyáitoknak, Ábrahámnak, Izsáknak és Jákóbnak, hogy nékik adja, és ő utánok az ő magvoknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, 'És szólottam vala néktek abban az időben, ezt mondván: Nem viselhetlek egymagam titeket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'Az Úr, a ti Istenetek megsokasított titeket elannyira, hogy oly sokan vagytok ti most, mint az égnek csillagai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, 'Az Úr, a ti atyáitoknak Istene szaporítson meg titeket ezerszerte is inkább mint most vagytok, és áldjon meg titeket, a miképen igérte néktek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'Miképen viselhetném én egymagam a terheiteket és a ti bajaitokat és a ti pereiteket?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'Válaszszatok magatoknak bölcs, értelmes és a ti törzseitekben ismeretes férfiakat, és én azokat előljáróitokká teszem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'És felelétek nékem, és mondátok: Jó dolog, a mit mondál, hogy míveled azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'Vevém azért a ti törzseiteknek főbbjeit, a bölcs és ismeretes férfiakat, és tevém őket előljáróitokká: ezredesekké, századosokká, ötvenedesekké, tizedesekké és tiszttartókká, a ti törzseitek szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'És megparancsolám abban az időben a ti biráitoknak, mondván: Hallgassátok ki atyátokfiait, és ítéljetek igazságosan mindenkit, az ő atyjafiaival és jövevényeivel egyben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'Ne legyetek személyválogatók az ítéletben: kicsinyt úgy, mint nagyot hallgassatok ki; ne féljetek senkitől, mert az ítélet az Istené; a mi pedig nehéznek tetszik néktek, én előmbe hozzátok, és én meghallgatom azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'És megparancsoltam néktek abban az időben mindent, a mit cselekedjetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, 'Azután elindulánk a Hórebtől, és bejártuk ama nagy és rettenetes pusztát, a melyet láttatok, az Emoreusok hegyének menve, a miképen parancsolta volt az Úr, a mi Istenünk nékünk; és eljutánk Kádes-Barneához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'És mondám néktek: Eljutottatok az Emoreusok hegyéig, a melyet az Úr, a mi Istenünk ád nékünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'Ímé elődbe adta az Úr, a te Istened ezt a földet: menj fel, bírjad azt, a miképen megmondotta az Úr, a te atyáidnak Istene néked; ne félj, és meg ne rettenj!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'Ti pedig mindnyájan hozzám járulátok és mondátok: Küldjünk embereket előre, hogy kémleljék meg nékünk azt a földet, és hozzanak nékünk hírt az út felől, a melyen felmenjünk, és a városok felől, a melyekbe bevonuljunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'És tetszék nékem ez a beszéd, és vevék közületek tizenkét férfiút, minden törzsből egyet-egyet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, 'És fordulának és felmenének a hegyre, és eljutának az Eskól völgyéig, és kikémlelék azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'És vőnek kezeikbe annak a földnek gyümölcséből, és alá hozák hozzánk, és hírt hozának nékünk és mondának: Jó az a föld, a melyet az Úr, a mi Istenünk ád nékünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'De ti nem akartatok felmenni; hanem pártot ütétek az Úrnak, a ti Isteneteknek parancsa ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'És zúgolódátok a ti sátoraitokban, és mondátok: mivelhogy gyűlöl minket az Úr, azért hozott ki minket Égyiptom földéből, hogy adjon minket az Emoreus kezébe, és elpusztítson minket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'Hová mennénk fel mi? A mi atyánkfiai megrettenték a mi szíveinket, mondván: Az a nép nagyobb és szálasabb nálunknál; a városok nagyok és megerősíttettek az égig; még Anák fiakat is láttunk ott!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, 'Akkor mondám néktek: Ne rettegjetek és ne féljetek azoktól;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'Az Úr, a ti Istenetek, a ki előttetek megy, ő hadakozik ti érettetek mind a szerint, a mint cselekedett vala veletek Égyiptomban a ti szemeitek előtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'És a pusztában, a hol láttad, hogy úgy hordozott téged az Úr, a te Istened, a miképen hordozza az ember az ő fiát, mind az egész úton, a melyen jártatok, míg jutátok e helyre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'Mindazáltal nem hivétek az Úrnak, a ti Isteneteknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'A ki előttetek jár vala az úton, hogy helyet szemeljen ki néktek, a hol táborozzatok, éjjel tűzben, hogy megmutassa néktek az útat, a melyen járjatok, és felhőben nappal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'Meghallá pedig az Úr beszédetek szavát, és megharaguvék, és megesküvék, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, 'E gonosz nemzetségből való emberek közül egy sem látja meg azt a jó földet, a mely felől megesküdtem, hogy a ti atyáitoknak adom;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'Kivéve Kálebet, a Jefunné fiát; ő meglátja azt, és ő néki adom azt a földet, a melyet tapodott, és az ő fiainak, mert tökéletességgel követte az Urat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'Még én reám is megharaguvék az Úr miattatok, mondván: Te sem mégy oda be!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'Józsué, a Nún fia, a ki áll te előtted, ő megy be oda; azért biztassad őt, mert ő osztja el az örökséget Izráelnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'És a ti kicsinyeitek, a kikről szólátok hogy prédául lesznek, és a ti fiaitok, a kik nem tudnak most sem jót, sem gonoszt, azok mennek be oda, mert nékik adom azt, és ők bírják azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'Ti pedig forduljatok vissza, és induljatok a pusztába, a Veres tenger felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, 'És azt felelétek, és azt mondátok nékem: Vétkeztünk az Úr ellen, mi felmegyünk és hadakozunk mind a szerint, a mint parancsolta nékünk az Úr, a mi Istenünk! És felövezétek magatokat, kiki az ő harczi eszközeivel, és készek valátok felmenni a hegyre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'Monda pedig az Úr nékem: Mondd meg nékik: Ne menjetek fel, és ne harczoljatok, mert nem vagyok közöttetek: hogy meg ne verettessetek a ti ellenségeitektől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'És megmondám néktek, de nem hallgattatok rám, hanem pártot ütöttetek az Úr parancsolata ellen, és vakmerősködétek, és felmenétek a hegyre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'De kijöve az Emoreus, a ki lakik vala azon a hegyen, ti ellenetek, és megkergetének titeket, mint a méhek szokták cselekedni, és vagdaltak vala titeket Szeirtől Hormáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, 'És visszatérétek onnét, és sírátok az Úr előtt, de nem hallgatá meg az Úr a ti szavatokat, és nem figyele rátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'És sok időn át lakozátok Kádesben, a meddig ott lakozátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, 'Annakutána megfordulánk, és indulánk a pusztába a Veres tenger felé, a miképen szólott vala nékem az Úr, és kerülgettük a Szeir hegyét sok ideig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'De szóla az Úr nékem, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, 'Elég már e hegyet kerülgetnetek, forduljatok észak felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'Parancsolj azért a népnek, mondván: Mikor általmentek a ti atyátokfiainak, az Ézsaú fiainak határán, a kik Szeirben lakoznak: jóllehet félnek tőletek, mindazáltal igen vigyázzatok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, 'Ne ingereljétek őket, mert nem adok az ő földjükből néktek egy talpalatnyit sem; mert Ézsaúnak adtam a Szeir hegyét örökségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'Pénzen vásároljatok tőlük enni valót, hogy egyetek, és vizet is pénzen vegyetek tőlük, hogy igyatok,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'Mert az Úr, a te Istened megáldott téged a te kezednek minden munkájában; tudja, hogy e nagy pusztaságon jársz; immár negyven esztendeje veled van az Úr, a te Istened; nem szűkölködtél semmiben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'És általmenénk a mi atyánkfiai között, az Ézsaú fiai között, a kik lakoznak vala Szeirben, a síkság útján Eláthtól és Éczjon-Gebertől fogva. Azután megfordulánk és általmenénk a Moáb pusztájának útjára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'És monda az Úr nékem: Ne hadakozzál Moáb ellen, és ne ingereld azt hadra, mert nem adok az ő földéből néked semmi örökséget; mert a Lót fiainak adtam Art örökségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, '(Az Emeusok laktak abban annak előtte, nagy nép, sok és szálas, mint az Anákok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'Óriásoknak állíttatnak vala azok is, mint az Anákok, és a Moábiták Emeknek hívták őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'Szeirben pedig Horeusok laktak az előtt, a kiket az Ézsaú fiai kiűztek, és kiirtottak színök elől, és azoknak helyén laktak, a miképen cselekedék Izráel is az ő örökségének földén, a melyet adott néki az Úr.)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, 'Most keljetek fel, és menjetek át a Záred patakán; és átkelénk a Záred patakán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'Az idő pedig, a melyet eljáránk Kádes-Barneától, míg általmenénk a Záred patakán, harmincznyolcz esztendő, a mely alatt kiveszett a hadra való férfiak egész nemzetsége a táborból, a mint megesküdt vala az Úr nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'E felett az Úrnak keze is vala ő rajtok, hogy elveszítse őket a táborból az ő kipusztulásukig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'És lőn, hogy a mint a hadakozó férfiak mind elpusztulának, kihalván a nép közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'Így szóla az Úr nékem, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, 'Ma te általmégy a Moáb határán Ar felé,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'És mikor közel jutsz az Ammon fiaihoz, ne háborgasd őket, ne is ingereld őket, mert nem adok néked az Ammon fiainak földjéből örökséget, mert a Lót fiainak adtam azt örökségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, '(Óriások földének tartották azt is; óriások laktak azon régenten, a kiket az Ammoniták Zanzummoknak hívtak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'Ez a nép nagy, sok és szálas volt, valamint az Anákok, de kivesztette őket az Úr azok színe elől, hogy bírják azoknak örökségét, és lakjanak azoknak helyén;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'A miképen cselekedett az Ézsaú fiaival is, a kik Szeir hegyén laknak, a mikor kiveszté előlök a Horeusokat, hogy bírják azoknak örökségét, és lakjanak azoknak helyén mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'Az Avveusokat is, a kik falvakban laknak vala Gázáig, kiirtották a Káftoreusok a kik kijöttek volt Káftorból, és lakának azoknak helyén.)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, 'Keljetek fel azért, induljatok, menjetek át az Arnon patakán; lásd: kezedbe adtam Szihont, Hesbonnak királyát: az Emoreust, és annak földét; kezdj hozzá, foglald el azt, és hadakozzál ő ellene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'E napon kezdem rábocsátani a népekre, hogy féljenek és rettegjenek tőled az egész ég alatt, és a kik híredet hallják, rendüljenek meg és reszkessenek te előtted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, 'És követeket küldék a Kedemót pusztából Szihonhoz, Hesbon királyához békességes beszéddel ezt izenvén:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, 'Hadd menjek át a te földeden! Útról-útra megyek, nem térek le se jobbra, se balra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'Eleséget pénzen adj nékem, hogy egyem; vizet is pénzen adj nékem, hogy igyam; csak gyalog hadd megyek át:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, 'A miképen cselekedtek én velem az Ézsaú fiai, a kik Szeirben laknak; és a Moábiták, a kik Arban laknak; míglen átmegyek a Jordánon arra a földre, a melyet az Úr, a mi Istenünk ád nékünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'De nem akarta Szihon, Hesbon királya, hogy átmenjünk ő rajta, mert megkeményítette volt az Úr, a te Istened az ő lelkét, és engedetlenné tette az Ő szívét, hogy a te kezedbe adja őt, a mint nyilván van e mai napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, 'Monda pedig az Úr nékem: Lásd: elkezdem átadni néked Szihont és az ő földét; kezdj hozzá, foglald el azt, hogy az ő földe örököd legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, 'És kijöve Szihon mi előnkbe minden népével, hogy megvívjon velünk Jahácznál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'De az Úr, a mi Istenünk kezünkbe adá őt, és levertük őt és az ő fiait és minden ő népét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'És elfoglaltuk minden ő városát abban az időben, és fegyverre hánytuk az egész várost: férfiakat, asszonyokat, és kisdedeket; nem hagytunk menekülni senkit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'De a barmokat prédára vetettük közöttünk, és a városokból való ragadományokat, a melyeket elfoglaltunk volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'Aróertől fogva, a mely van az Arnon patakának partján, és a völgyben lévő várostól fogva Gileádig, egy város sem volt, a melylyel ne bírtunk volna. Mind azokat az Úr, a mi Istenünk adta a mi kezünkbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'De az Ammon fiainak földéhez nem közeledtél, sem a Jabbók patak egész oldalához, sem a hegyen lévő városokhoz, sem semmi olyanhoz, a melyektől eltiltott téged az Úr, a mi Istenünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, 'És megfordulánk, és felmenénk Básán felé, és kijöve előnkbe Óg, Básánnak királya, ő és minden népe, hogy megvívjon velünk Edreiben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'De az Úr monda nékem: Ne félj tőle, mert a te kezedbe adtam őt és minden ő népét és földjét; és úgy cselekedjél vele, a mint cselekedtél Szihonnal, az Emoreusok királyával, a ki Hesbonban lakik vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, 'És kezünkbe adá az Úr, a mi Istenünk Ógot is, Básánnak királyát és minden ő népét, és úgy megvertük őt, hogy menekülni való sem maradt belőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'És abban az időben elfoglaltuk minden városát; nem volt város, a melyet el nem vettünk volna tőlök: hatvan várost, Argóbnak egész vidékét, a Básenbeli Ógnak országát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'Ezek a városok mind meg valának erősítve magas kőfalakkal, kapukkal és zárokkal, kivévén igen sok kerítetlen várost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'És fegyverre hánytuk azokat, a mint cselekedtünk vala Szihonnal, Hesbon királyával, fegyverre hányván az egész várost: férfiakat, asszonyokat és a kisdedeket is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'De a barmokat és a városokból való ragadományokat mind magunk közt vetettük prédára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'És elvettük abban az időben az Emoreusok két királyának kezéből azt a földet, a mely a Jordánon túl vala, az Arnon pataktól fogva a Hermon hegyéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, '(A Sidoniak a Hermont Szirjonnak, az Emoreusok pedig Szenirnek hívják.)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'A síkságnak minden városát, és az egész Gileádot, meg az egész Básánt Szalkáig és Edreig, a melyek a Básánbeli Óg országának városai voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, 'Mert egyedül Óg, Básánnak királya maradt meg az óriások maradéka közül. Ímé az ő ágya vas-ágy, nemde Rabbátban az Ammon fiainál van-é? Kilencz sing a hosszasága és négy sing a szélessége, férfi könyök szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'Ezt a földet pedig, a melyet abban az időben örökségünkké tettünk, Aróertől fogva, a mely az Arnon patak mellett van, és a Gileád hegyének felét, és annak városait odaadtam a Rúbenitáknak és Gáditáknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'A Gileád többi részét pedig, és az egész Básánt, az Óg országát odaadtam a Manassé fél törzsének, Argóbnak egész vidékét. Ezt az egész Básánt óriások földének hívták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'Jair, Manassénak fia, kapta Argóbnak egész vidékét, a Gessuriták és Maakátiták határáig; és azokat a Básánnal együtt az ő nevéről Jair faluinak hívják mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'Mákirnak pedig adtam Gileádot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'A Rúbenitáknak és a Gáditáknak pedig adtam Gileádtól fogva Arnonnak patakáig (a határ pedig a patak közepe) és a Jabbók patakáig, a mely az Ammon fiainak határa;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'És a síkságot és határul a Jordánt, a Kinnerettől a Síkság tengeréig, a Sóstengerig, a mely a Piszga-hegy lába alatt van napkelet felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'És parancsolék abban az időben néktek, mondván: Az Úr, a ti Istenetek adta néktek ezt a földet, hogy bírjátok azt; felfegyverkezvén, menjetek át a ti atyátok fiai, Izráel fiai előtt mind, a kik hadakozásra valók vagytok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'Csak feleségeitek, kicsinyeitek és barmaitok (mert tudom, hogy sok barmotok van) maradjanak a ti városaitokban, a melyeket én adtam néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'Mindaddig, a míg nyugodalmat ád az Úr a ti atyátokfiainak, mint néktek, és azok is bírhatják a földet, a melyet az Úr, a ti Istenetek ád nékik a Jordánon túl. Azután térjetek vissza, kiki az ő örökségébe, a melyet adtam néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'Józsuénak is parancsolék abban az időben, mondván: Szemeiddel láttad mindazt, a mit cselekedett az Úr, a ti Istenetek ama két királylyal; így cselekszik az Úr minden országgal, a melyen átmégy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'Ne féljetek tőlök, mert az Úr, a ti Istenetek, maga hadakozik ti érettetek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, 'Könyörgék is az Úrnak abban az időben, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, 'Uram, Isten, te elkezdetted megmutatni a te szolgádnak a te nagyságodat és hatalmas kezedet! Mert kicsoda olyan Isten mennyben és földön, a ki cselekedhetnék a te cselekedeteid és hatalmad szerint?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'Hadd menjek át kérlek, és hadd lássam meg azt a jó földet, a mely a Jordánon túl van, és azt a jó hegyet, és a Libanont!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, 'De megharaguvék az Úr én reám ti miattatok, és nem hallgatott meg engem; hanem ezt mondá az Úr nékem: Elég ez néked, ne szólj többet már nékem e dolog felől!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'Menj fel a Piszga tetejére, és emeld fel a te szemeidet napnyugot felé és észak felé, dél felé és napkelet felé, és nézz szét a te szemeiddel, mert nem mégy át ezen a Jordánon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'Józsuénak pedig parancsolj, és bátorítsd őt, és erősítsd őt, mert ő megy át e nép előtt, és ő teszi őket örököseivé annak a földnek, a melyet meglátsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'És ott maradánk a völgyben, Beth-Peórral szemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, 'Most pedig hallgass ó Izráel a rendelésekre és végzésekre, a melyekre én tanítlak titeket, hogy azok szerint cselekedjetek, hogy élhessetek, és bemehessetek, és bírhassátok a földet, a melyet az Úr, a ti atyáitoknak Istene ád néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'Semmit se tegyetek az ígéhez, a melyet én parancsolok néktek, se el ne vegyetek abból, hogy megtarthassátok az Úrnak, a ti Isteneteknek parancsolatait, a melyeket én parancsolok néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'Szemeitekkel láttátok, a mit cselekedett az Úr Baal-Peór miatt; hogy minden embert, a ki Baal-Peór után járt, kipusztított az Úr, a te Istened te közüled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'Ti pedig, a kik ragaszkodtatok az Úrhoz, a ti Istenetekhez, mindnyájan éltek e napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'Lássátok, tanítottalak titeket rendelésekre és végzésekre, a mint megparancsolta nékem az Úr, az én Istenem, hogy azok szerint cselekedjetek azon a földön, a melybe bementek, hogy bírjátok azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'Megtartsátok azért és megcselekedjétek! Mert ez lesz a ti bölcseségtek és értelmetek a népek előtt, a kik meghallják majd mind e rendeléseket, és ezt mondják: Bizony bölcs és értelmes nép ez a nagy nemzet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'Mert melyik nagy nemzet az, a melyhez olyan közel volna az ő Istene, mint mi hozzánk az Úr, a mi Istenünk, valahányszor hozzá kiáltunk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'És melyik nagy nemzet az, a melynek olyan rendelései és igazságos végzései volnának, mint ez az egész törvény, a melyet én ma adok elétek?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, 'Csak vigyázz magadra, és őrizd jól a te lelkedet, hogy el ne felejtkezzél azokról, a melyeket láttak a te szemeid, és hogy el ne távozzanak a te szívedtől teljes életedben, hanem ismertesd meg azokat a te fiaiddal és fiaidnak fiaival.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, 'El ne felejtkezzél a napról, a melyen az Úr előtt, a te Istened előtt állottál a Hóreben, a mikor azt mondta nékem az Úr: Gyűjtsd egybe nékem a népet, hogy hallassam véle beszédeimet, hogy tanuljanak félni engem, minden időben, a míg e földön élnek, és tanítsák meg fiaikat is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'És előjárulátok, és megállátok a hegy alatt; a hegy pedig tűzben ég vala mind az ég közepéig, mindamellett sötétség, köd és homályosság vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'És szóla az Úr néktek a tűz közepéből. A szavak hangját ti is halljátok vala, de csak a hangot; alakot azonban nem láttok vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'És kijelenté néktek az ő szövetségét, a melyre nézve utasított titeket a tíz ige teljesítésére, és felírá azokat két kőtáblára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'Engem is utasított az Úr abban az időben, hogy tanítsalak meg titeket a rendelésekre és végzésekre, hogy azok szerint cselekedjetek azon a földön, a melyre átmentek, hogy bírjátok azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'Őrizzétek meg azért jól a ti lelketeket, mert semmi alakot nem láttatok akkor, a mikor a tűznek közepéből szólott hozzátok az Úr a Hóreben;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'Hogy el ne vetemedjetek, és faragott képet, valamely bálványféle alakot ne csináljatok magatoknak, férfi vagy asszony képére;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'Képére valamely baromnak, a mely van a földön; képére valamely repdeső madárnak, a mely röpköd a levegőben;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'Képére valamely földön csúszó-mászó állatnak; képére valamely halnak, a mely van a föld alatt lévő vizekben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'Se szemeidet fel ne emeld az égre, hogy meglásd a napot, a holdat és a csillagokat, az égnek minden seregét, hogy meg ne tántorodjál, és le ne borulj azok előtt, és ne tiszteljed azokat, a melyeket az Úr, a te Istened minden néppel közlött, az egész ég alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'Titeket pedig kézen fogott az Úr, és kihozott titeket a vas kemenczéből, Égyiptomból, hogy legyetek néki örökös népe, miképen e mai napon vagytok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'De én reám megharaguvék az Úr ti miattatok, és megesküvék, hogy nem megyek át a Jordánon, és hogy nem megyek be arra a jó földre, a melyet az Úr, a te Istened, ád néked örökségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'Miután én meghalok e földön, nem megyek át a Jordánon; ti pedig átmentek, és bírjátok azt a jó földet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'Vigyázzatok, hogy az Úrnak, a ti Isteneteknek szövetségéről, a melyet kötött veletek, el ne felejtkezzetek, és ne csináljatok magatoknak faragott képet, akármihez is hasonlót, a miképen megparancsolta az Úr, a te Istened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'Mert az Úr, a te Istened emésztő tűz, féltőn szerető Isten ő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, 'Hogyha majd fiakat és unokákat nemzesz, és megvénhedtek azon a földön, és elvetemedtek, és csináltok magatoknak faragott képet, akármihez is hasonlót, és gonoszt cselekesztek az Úrnak, a te Istenednek szemei előtt, haragra ingerelvén őt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'Bizonyságul hívom ti ellenetek e mai napon a mennyet és a földet, hogy elveszvén hamarsággal elvesztek a földről, a melyre átmentek a Jordánon, hogy bírjátok azt; nem laktok sok ideig azon, hanem pusztára kipusztultok róla.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'És az Úr szétszór titeket a népek közé, és szám szerint kevesen maradtok meg a népek között, a kik közé visz titeket az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'És szolgáltok ott emberi kéz által csinált isteneknek: fának és kőnek, a melyek nem látnak, nem is hallanak, nem is esznek, nem is szagolnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'De ha onnan keresed meg az Urat, a te Istenedet, akkor is megtalálod, hogyha teljes szívedből és teljes lelkedből keresed őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'Mikor nyomorúságban leéndesz, és utólérnek téged mindezek az utolsó időkben, és megtérsz az Úrhoz, a te Istenedhez, és hallgatsz az ő szavára:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, '(Mert irgalmas Isten az Úr, a te Istened), nem hágy el téged, sem el nem veszít, sem el nem felejtkezik a te atyáidnak szövetségéről, a mely felől megesküdt nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, 'Mert tudakozzál csak a régi időkről, a melyek te előtted voltak, ama naptól fogva, a melyen az Isten embert teremtett e földre, és pedig az égnek egyik szélétől az égnek másik széléig, ha történt-é e nagy dologhoz hasonló, vagy hallatszott-é ehhez fogható?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'Hallotta-é valamely nép a tűz közepéből szóló Istennek szavát, a miképen hallottad te, hogy életben maradt volna?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'Avagy próbálta-é azt Isten, hogy elmenjen és válaszszon magának népet valamely nemzetség közül, kisértésekkel: jelekkel, csudákkal, haddal, hatalmas kézzel, kinyújtott karral, és nagy rettenetességek által, a miképen cselekedte mind ezeket ti érettetek az Úr, a ti Istenetek Égyiptomban, szemeitek láttára?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'Csak néked adatott láthatóan tudnod, hogy az Úr az Isten és nincsen kivüle több!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'Az égből hallatta veled az ő szavát, hogy tanítson téged, a földön pedig mutatta néked amaz ő nagy tüzét, és hallottad beszédét a tűz közepéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'És mivel szerette a te atyáidat, és kiválasztotta az ő magvokat is ő utánok, és kihozott téged az ő orczájával Égyiptomból, az ő nagy erejével:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'Hogy kiűzzön náladnál nagyobb és erősebb népeket előled, hogy bevigyen téged, és adja néked az ő földjöket örökségül, mint a mai napon van:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'Tudd meg azért e mai napon, és vedd szívedre, hogy az Úr az Isten, fent a mennyben, és alant e földön, és nincsen több!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'Tartsd meg azért az ő rendeléseit és parancsolatait, a melyeket én parancsolok ma néked, hogy jól legyen dolgod és a te fiaidnak te utánad, és hogy mindenkor hosszú ideig élj azon a földön, a melyet az Úr, a te Istened ád néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, 'Akkor választa Mózes három várost a Jordánon túl napkelet felé;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'Hogy oda fusson a gyilkos, a ki nem akarva gyilkolta meg az ő felebarátját, a ki az előtt nem gyűlölte vala, és hogy életben maradjon, ha befutott valamelyikbe e városok közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'Tudniillik Beczert a pusztában, a sík földön a Ruben fiainak, Rámótot Gileádban a Gád fiainak, és Gólánt Básánban a Manassé fiainak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'Ez pedig a törvény, a melyet Mózes adott az Izráel fiai elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'Ezek a bizonyságtételek, a rendelések és a végzések, a melyeket szóla Mózes Izráel fiainak, mikor Égyiptomból kijöttek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 'A Jordánon túl a völgyben, Beth-Peórnak átellenében, Szihonnak, az Emoreusok királyának földjén, a ki lakozik vala Hesbonban, a kit megvert vala Mózes, az Izráel fiaival egyben, mikor Égyiptomból kijöttek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'És elfoglalák az ő földét, és Ógnak, Básán királyának földét, az Emoreusok két királyáét, a kik a Jordánon túl laknak vala napkelet felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'Aróertől fogva, mely az Arnon patakának partján van, a Sion hegyéig, a mely a Hermon;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'És az egész síkságot a Jordánon túl napkelet felé, a síkság tengeréig, a Piszga hegy aljáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'És szólítá Mózes az egész Izráelt, és monda nékik: Hallgasd meg Izráel a rendeléseket és a végzéseket, a melyeket elmondok én ma fületek hallására, és tanuljátok meg azokat, és ügyeljetek azokra, megcselekedvén azokat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'Az Úr, a mi Istenünk szövetséget kötött velünk a Hóreben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'Nem a mi atyáinkkal kötötte az Úr e szövetséget, hanem mi velünk, a kik íme itt vagyunk e mai napon mindnyájan és élünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'Színről színre szólott veletek az Úr a hegyen, a tűz közepéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, '(Én pedig az Úr között és ti közöttetek állok vala abban az időben, hogy megjelentsem néktek az Úr beszédét; mert ti a tűztől féltek vala, és nem menétek fel a hegyre) mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, 'Én, az Úr, vagyok a te Istened, a ki kihoztalak téged Égyiptomnak földéből, a szolgálatnak házából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, 'Ne legyenek néked idegen isteneid én előttem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'Ne csinálj magadnak faragott képet, és semmi hasonlót azokhoz, a melyek fenn az égben, vagy a melyek alant a földön, vagy a melyek a vizekben a föld alatt vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'Ne imádd és ne tiszteld azokat; mert én, az Úr, a te Istened, féltőn szerető Isten vagyok, a ki megbüntetem az atyák vétkét a fiakban, harmad és negyedíziglen, a kik engem gyűlölnek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'De irgalmasságot cselekeszem ezeríziglen azokkal, a kik engem szeretnek, és az én parancsolataimat megtartják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, 'Az Úrnak, a te Istenednek nevét hiába fel ne vedd; mert nem hagyja azt az Úr büntetés nélkül, a ki az ő nevét hiába felveszi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, 'Vigyázz a szombatnak napjára, hogy megszenteld azt, a miképen megparancsolta néked az Úr, a te Istened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'Hat napon át munkálkodjál, és végezd minden dolgodat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'De a hetedik nap az Úrnak, a te Istenednek szombatja: semmi dolgot se tégy azon, se magad, se fiad, se leányod, se szolgád, se szolgálóleányod, se ökröd, se szamarad, és semminémű barmod, se jövevényed, a ki a te kapuidon belől van, hogy megnyugodjék a te szolgád és szolgálóleányod, mint te magad;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'És megemlékezzél róla, hogy szolga voltál Égyiptom földén, és kihozott onnan téged az Úr, a te Istened erős kézzel és kinyújtott karral. Azért parancsolta néked az Úr, a te Istened, hogy a szombat napját megtartsad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, 'Tiszteld atyádat és anyádat, a mint megparancsolta néked az Úr, a te Istened; hogy hosszú ideig élj, és hogy jól legyen dolgod azon a földön, a melyet az Úr, a te Istened ád te néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, 'Ne ölj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, 'És ne paráználkodjál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, 'És ne lopj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, 'És ne tégy a te felebarátod ellen hamis tanubizonyságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, 'És ne kívánd a te felebarátodnak feleségét; és ne áhítsd a te felebarátodnak házát, szántóföldét; se szolgáját, se szolgálóleányát, se ökrét, se szamarát és semmit, a mi a te felebarátodé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, 'Ez ígéket szólá az Úr a ti egész gyülekezeteteknek a hegyen a tűz, a felhő és a homályosság közepéből nagy felszóval, és nem többet; és felírá azokat két kőtáblára, és adá azokat nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'És lőn, mikor a szót a setétség közepéből halljátok vala, és a hegy tűzzel ég vala, hozzám jövétek a ti törzseiteknek minden fejedelmével és vénjével;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'És mondátok: Ímé az Úr, a mi Istenünk megmutatta nékünk az ő dicsőségét és nagyságát; és az ő szavát hallottuk a tűznek közepéből; e mai napon pedig láttuk, hogy az Isten emberrel szól, és ez mégis él.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'Most hát miért haljunk meg? Mert megemészt e nagy tűz minket. Ha még tovább halljuk az Úrnak, a mi Istenünknek szavát, meghalunk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'Mert kicsoda az, az összes halandók közül, a ki a tűznek közepéből szóló élő Istennek szavát hallotta, mint mi, hogy megélt volna?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'Járulj oda te, és hallgasd meg mind azt, a mit mond az Úr, a mi Istenünk, és te majd beszéld el nékünk mind, a mit néked mond az Úr, a mi Istenünk, és mi meghallgatjuk, és megcselekeszszük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'És meghallá az Úr a ti beszédetek szavát, a mikor beszéltek vala velem, és monda nékem az Úr: Hallottam e nép beszédének szavát, a mint beszéltek vala hozzád; mind jó, a mit beszéltek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, 'Vajha így maradna az ő szívök, hogy félnének engem, és megtartanák minden parancsolatomat minden időben, hogy jól legyen dolguk nékik és az ő gyermekeiknek mindörökké!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'Menj el, és mondd meg nékik: Térjetek vissza a ti sátoraitokba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, 'Te pedig állj ide mellém, hogy elmondjam néked minden parancsolatomat, rendelésemet és végzésemet, a melyekre tanítsd meg őket, hogy cselekedjék azon a földön, a melyet én adok néktek örökségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, 'Vigyázzatok azért, hogy úgy cselekedjetek, a mint az Úr, a ti Istenetek parancsolta néktek; ne térjetek se jobbra, se balra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, 'Mindig azon az úton járjatok, a melyet az Úr, a ti Istenetek parancsolt néktek, hogy éljetek, és jó legyen dolgotok, és hosszú ideig élhessetek a földön, a melyet bírni fogtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, 'Ezek pedig a parancsolatok, a rendelések és a végzések, a melyek felől parancsolta az Úr, a ti Istenetek, hogy megtanítsam azokat néktek, hogy azok szerint cselekedjetek azon a földön, a melyre átmenőben vagytok, hogy bírjátok azt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'Hogy féljed az Urat, a te Istenedet, és megtartsad minden ő rendelését és parancsolatát, a melyeket én parancsolok néked: te és a te fiad, és a te unokád, teljes életedben, és hogy hosszú ideig élhess.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'Halld meg azért Izráel, és vigyázz, hogy megcselekedjed, hogy jól legyen dolgod, és hogy igen megsokasodjál a tejjel és mézzel folyó földön, a miképen megigérte az Úr, a te atyáidnak Istene néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'Halld Izráel: az Úr, a mi Istenünk, egy Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'Szeressed azért az Urat, a te Istenedet teljes szívedből, teljes lelkedből és teljes erődből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'És ez ígék, a melyeket e mai napon parancsolok néked, legyenek a te szívedben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'És gyakoroljad ezekben a te fiaidat, és szólj ezekről, mikor a te házadban ülsz, vagy mikor úton jársz, és mikor lefekszel, és mikor felkelsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'És kössed azokat a te kezedre jegyül, és legyenek homlokkötőül a te szemeid között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'És írd fel azokat a te házadnak ajtófeleire, és a te kapuidra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, 'És mikor bevisz téged az Úr, a te Istened a földre, a mely felől megesküdt a te atyáidnak, Ábrahámnak, Izsáknak és Jákóbnak, hogy ad néked nagy és szép városokat, a melyeket nem építettél;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'És minden jóval telt házakat, a melyeket nem te töltöttél meg, és ásott kutakat, a melyeket nem te ástál, szőlő- és olajfakerteket, a melyeket nem te plántáltál; és eszel és megelégszel:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, 'Vigyázz magadra, hogy el ne felejtkezzél az Úrról, a ki kihozott téged Égyiptom földéről, a szolgaságnak házából!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'Féljed az Urat, a te Istenedet, ő néki szolgálj, és az ő nevére esküdjél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'Ne járjatok idegen istenek után, azoknak a népeknek istenei közül, a kik körültetek vannak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, '(Mert az Úr, a te Istened féltőn szerető Isten te közötted), hogy az Úrnak, a te Istenednek haragja fel ne gerjedjen reád, és el ne törüljön téged a föld színéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, 'Meg ne kísértsétek az Urat, a ti Isteneteket, miképen megkísértettétek Maszszában!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'Szorosan megtartsátok az Úrnak, a ti Isteneteknek parancsolatait, az ő bizonyságait és rendeléseit, a melyeket parancsolt néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'És azt cselekedjed, a mi igaz és jó az Úrnak szemei előtt, hogy jól legyen dolgod, és bemehess és bírhasd azt a jó földet, a mely felől megesküdött az Úr a te atyáidnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'Hogy elűzzed minden ellenségedet a te színed elől, a mint megmondotta az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, 'Ha a te fiad megkérdez téged ezután, mondván: Mire valók e bizonyságtételek, rendelések és végzések, a melyeket az Úr, a mi Istenünk parancsolt néktek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'Akkor azt mondjad a te fiadnak: Szolgái voltunk Égyiptomban a Faraónak; de kihozott minket az Úr Égyiptomból hatalmas kézzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'És tőn az Úr Égyiptomban nagy és veszedelmes jeleket és csudákat a Faraón és az ő egész háznépén, a mi szemeink láttára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'Minket pedig kihoza onnét, hogy bevigyen minket, és nékünk adja azt a földet, a mely felől megesküdött a mi atyáinknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'És megparancsolta nékünk az Úr, hogy cselekedjünk mind e rendelések szerint, hogy féljük az Urat, a mi Istenünket, hogy jó dolgunk legyen teljes életünkben, hogy megtartson minket az életben, mint e mai napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, 'És ez lesz nékünk igazságunk, ha vigyázunk arra, hogy megtartsuk mind e parancsolatokat, az Úr előtt, a mi Istenünk előtt, a miképen megparancsolta nékünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, 'Mikor bevisz téged az Úr, a te Istened a földre, a melyre te bemenendő vagy, hogy bírjad azt; és sok népet kiűz te előled a Khitteust, a Girgazeust, az Emoreust, a Kananeust, a Perizeust, a Khivveust, és a Jebuzeust: hétféle népet, náladnál nagyobbakat és erősebbeket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'És adja őket az Úr, a te Istened a te hatalmadba, és megvered őket: mindenestől veszítsd ki őket; ne köss velök szövetséget, és ne könyörülj rajtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'Sógorságot se szerezz ő velök, a leányodat se adjad az ő fioknak, és az ő leányukat se vegyed a te fiadnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'Mert elpártoltatja a te fiadat én tőlem, és idegen isteneknek szolgálnak; és felgerjed az Úrnak haragja reátok, és hamar kipusztít titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'Hanem így cselekedjetek velök: Oltáraikat rontsátok le, oszlopaikat törjétek össze, berkeiket vágjátok ki, faragott képeiket pedig tűzzel égessétek meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'Mert az Úrnak, a te Istenednek szent népe vagy te; téged választott az Úr, a te Istened, hogy saját népe légy néki, minden nép közül e föld színén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'Nem azért szeretett titeket az Úr, sem nem azért választott titeket, hogy minden népnél többen volnátok; mert ti minden népnél kevesebben vagytok;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'Hanem mivel szeretett titeket az Úr, és hogy megtartsa az esküt, a melylyel megesküdt volt a ti atyáitoknak; azért hozott ki titeket az Úr hatalmas kézzel, és szabadított meg téged a szolgaságnak házából, az égyiptombeli Faraó királynak kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'És hogy megtudjad, hogy az Úr, a te Istened, ő az Isten, a hívséges Isten, a ki megtartja a szövetséget és az irgalmasságot ezeríziglen azok iránt, a kik őt szeretik, és az ő parancsolatait megtartják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'De megfizet azoknak személy szerint, a kik őt gyűlölik, elvesztvén őket; nem késlekedik az ellen, a ki gyűlöli őt, megfizet annak személy szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'Tartsd meg azért a parancsolatot, a rendeléseket és végzéseket, a melyeket én e mai napon parancsolok néked, hogy azokat cselekedjed.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, 'Ha pedig engedelmeskedtek e végzéseknek, és megtartjátok, és teljesítitek azokat: az Úr, a te Istened is megtartja néked a szövetséget és irgalmasságot, a mely felől megesküdött a te atyáidnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'És szeretni fog téged, és megáld téged, és megsokasít téged; és megáldja a te méhednek gyümölcsét, a te földednek gyümölcsét: gabonádat, mustodat és olajodat; teheneid fajzását és juhaidnak ellését azon a földön, a mely felől megesküdt a te atyáidnak, hogy néked adja azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'Áldottabb lészesz minden népnél; nem lészen közötted magtalan férfi és asszony, sem barmaid között meddő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'És távol tart az Úr te tőled minden betegséget, és Égyiptomnak minden gonosz nyavalyáját, a melyeket ismersz; nem veti azokat te reád, hanem mind azokra, a kik gyűlölnek téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'És megemészted mind a népeket, a melyeket néked ád az Úr, a te Istened; ne kedvezzen a te szemed nékik, és ne tiszteld az ő isteneit; mert tőr gyanánt volna az néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'Ha azt mondod a te szívedben: Többen vannak e népek, mint én, miképen űzhetem én ki őket?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'Ne félj tőlök; emlékezzél meg csak azokról, a miket cselekedett az Úr, a te Istened a Faraóval és mind az égyiptombeliekkel:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'A nagy kisértésekről, a melyeket láttak a te szemeid, és a jelekről és csudákról; az erős kézről, és a kinyujtott karról, a melylyel kihozott téged az Úr, a te Istened! Így cselekeszik az Úr, a te Istened minden néppel, a melytől te félsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'Sőt még a darázsokat is rájok bocsátja az Úr, a te Istened mind addig, míglen elvesznek azok is, a kik megmaradtak, és a kik elrejtőztek te előled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'Ne rettenj meg azok előtt, mert közötted van az Úr, a te Istened, nagy és rettenetes Isten!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'És lassan-lassan kiűzi az Úr, a te Istened e népeket te előled. Nem lehet őket hirtelen kipusztítanod, hogy a mezei vadak meg ne sokasodjanak ellened!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, 'De az Úr, a te Istened elődbe veti őket, és nagy romlással rontja meg őket, míglen elvesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'Az ő királyaikat is kezedbe adja, hogy eltöröljed az ő nevöket az ég alól; senki ellened nem állhat, míglen elveszted őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'Az ő isteneiknek faragott képeit tűzzel égesd meg; az azokon lévő ezüstöt és aranyat meg ne kívánd, és magadnak el ne vedd, hogy tőrbe ne essél miatta; mert útálatosság az az Úr előtt, a te Istened előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'Útálatosságot pedig ne vígy be a te házadba, hogy átokká ne légy, mint az, hanem megvetvén vesd meg azt, és útálván útáld meg azt, mert átkozott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, 'Mind azt a parancsolatot, a melyet én e mai napon parancsolok néked, tartsátok meg és teljesítsétek, hogy élhessetek és megsokasodhassatok, bemehessetek és bírhassátok a földet, a mely felől megesküdött az Úr a ti atyáitoknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'És emlékezzél meg az egész útról, a melyen hordozott téged az Úr, a te Istened immár negyven esztendeig a pusztában, hogy megsanyargasson és megpróbáljon téged, hogy nyilvánvaló legyen, mi van a te szívedben; vajjon megtartod-é az ő parancsolatait vagy nem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'És megsanyargata téged, és megéheztete, azután pedig enned adá a mannát, a melyet nem ismertél, sem a te atyáid nem ismertek, hogy tudtodra adja néked, hogy az ember nem csak kenyérrel él, hanem mind azzal él az ember, a mi az Úrnak szájából származik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'A te ruházatod le nem kopott rólad, sem a te lábad meg nem dagadott immár negyven esztendőtől fogva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'Gondold meg azért a te szívedben, hogy a miképen megfenyíti az ember az ő gyermekét, úgy fenyít meg téged az Úr, a te Istened;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'És őrizd meg az Úrnak, a te Istenednek parancsolatait, hogy az ő útján járj, és őt féljed.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, 'Mert az Úr, a te Istened jó földre visz be téged; bővizű patakoknak, forrásoknak és mély vizeknek földére, a melyek a völgyekben és a hegyeken fakadnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'Búza-, árpa-, szőlőtő- fige- és gránátalma-termő földre, faolaj- és méz-termő földre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'Oly földre, a melyen nem nyomorogva eszed kenyeredet, és a hol semmiben sem szűkölködöl; oly földre, a melynek kövei vas, és a melynek hegyeiből rezet vághatsz!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'Ha azért eszel majd és megelégszel: dícsérjed az Urat, a te Istenedet azért a jó földért, a melyet néked adott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, 'Vigyázz magadra, hogy el ne felejtkezzél az Úrról, a te Istenedről, meg nem tartván az ő parancsolatait, végzéseit, rendeléseit, a melyeket én parancsolok néked e mai napon;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, 'Hogy mikor eszel és jól lakol, és szép házakat építesz, és lakozol azokban;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'És mikor a te barmaid és juhaid megsokasodnak, és ezüstöd és aranyad is megsokasodik, és minden jószágod megszaporodik:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'Fel ne fuvalkodjék akkor a te szíved, és el ne felejtkezzél az Úrról, a te Istenedről, a ki kihozott téged Égyiptom földéből, a szolgaságnak házából;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'A ki vezérlett téged a tüzes kígyóknak, skorpióknak, és szomjúságnak nagy és rettenetes pusztáján, a melyben víz nem vala; a ki vizet ada néked a kemény kősziklából;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'A ki mannával étete téged a pusztában, a mit nem ismertek a te atyáid, hogy megsanyargasson és hogy megpróbáljon téged, és jól tegyen veled azután:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, 'És ne mondjad ezt a te szívedben: Az én hatalmam, és az én kezemnek ereje szerzette nékem e gazdagságot!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'Hanem emlékezzél meg az Úrról, a te Istenedről, mert ő az, a ki erőt ád néked a gazdagságnak megszerzésére, hogy megerősítse az ő szövetségét, a mely felől megesküdt a te atyáidnak, miképen e mai napon van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'Ha pedig teljesen megfelejtkezel az Úrról, a te Istenedről, és idegen istenek után jársz, és azoknak szolgálsz, és meghajtod magadat azoknak; bizonyságot tészek e mai napon ti ellenetek, hogy végképen elvesztek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'Mint azok a nemzetek, a kiket az Úr elveszt előletek, azonképen vesztek el; azért mert nem hallgattok az Úrnak, a ti Isteneteknek szavára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, 'Halljad Izráel, te általmégy ma a Jordánon, hogy bemenvén, örökségül bírj náladnál nagyobb és erősebb népeket, nagy és az égig megerősített városokat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'Nagy és szálas népet, Anák-fiakat, a kikről magad is tudod és magad is hallottad: kicsoda állhat meg Anák fiai előtt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'Tudd meg azért e mai napon, hogy az Úr, a te Istened az, a ki átmegy előtted mint emésztő tűz, ő törli el azokat, és ő alázza meg azokat te előtted; és kiűzöd, és hamar elveszted őket, a miképen az Úr megmondotta néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'Mikor azért kiűzi az Úr, a te Istened azokat te előled, ne szólj a te szívedben, mondván: Az én igazságomért hozott be engem az Úr, hogy örökségül bírjam ezt a földet; holott e népeket az ő istentelenségökért űzi ki te előled az Úr;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'Nem a te igazságodért, sem a te szívednek igaz voltáért mégy te be az ő földük bírására; hanem az Úr, a te Istened e népeknek istentelenségéért űzi ki őket előled, hogy megerősítse az ígéretet, a mely felől megesküdt az Úr a te atyáidnak: Ábrahámnak, Izsáknak és Jákóbnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'Tudd meg azért, hogy az Úr, a te Istened nem a te igazságodért adja néked ezt a jó földet birtokul, mert kemény nyakú nép vagy te!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, 'Emlékezzél meg róla, és el ne felejtsed azokat, a mikkel haragra indítottad az Urat, a te Istenedet a pusztában! A naptól fogva, a melyen kijöttél Égyiptom földéből, mind addig, míglen e helyre jutottatok, az Úr ellen tusakodtatok vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'Már a Hóreben haragra indítátok az Urat, és annyira megharaguvék reátok az Úr, hogy el akara veszteni titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'Mikor felmegyek vala a hegyre, hogy átvegyem a kőtáblákat, a szövetségnek tábláit, a melyet az Úr kötött vala veletek, és a hegyen maradtam vala negyven nap és negyven éjjel: kenyeret nem ettem, sem vizet nem ittam vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'Akkor átadá nékem az Úr a két kőtáblát, a melyek az Isten ujjával valának beírva, és rajtok valának mind amaz ígék, a melyeket mondott vala az Úr néktek a hegyen a tűz közepéből, a gyülekezésnek napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'És mikor a negyven nap és negyven éj elmultával átadá az Úr nékem a két kőtáblát, a szövetségnek tábláit;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'Akkor monda az Úr nékem: Kelj fel, hamar menj innen alá; mert elvetemedett a te néped, a kit kihoztál Égyiptomból; hamar eltértek az útról, a melyet parancsoltam vala nékik, öntött bálványt készítettek magoknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'Ismét szóla nékem az Úr, mondván: Láttam e népet, és bizony kemény nyakú nép ez!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'Hagyj békét nékem, hadd pusztítsam el őket, és töröljem el az ő nevöket az ég alól, és teszlek téged ennél nagyobb és erősebb néppé!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, 'Megfordulék azért, és alájövék a hegyről, a hegy pedig tűzzel ég vala, és a szövetségnek két táblája az én két kezemben vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'És mikor látám, hogy ímé vétkeztetek vala az Úr ellen, a ti Istenetek ellen; öntött borjút csináltatok vala magatoknak; hamar letértetek vala az útról, a melyet az Úr parancsolt vala néktek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'Akkor megragadám a két táblát, és elhajítám a két kezemből, és összetörém azokat a ti szemeitek láttára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, 'És leborulék az Úr előtt, mint annakelőtte, negyven nap és negyven éjjel, kenyeret nem ettem és vizet sem ittam; minden ti bűnötökért, a melyeket elkövettetek vala, azt cselekedvén, a mi gonosz az Úr előtt, hogy ingereljétek őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'Mert félek vala a haragtól és búsulástól, a melylyel ti reátok úgy megharagudt vala az Úr, hogy el akart vala pusztítani titeket. És meghallgata az Úr engem akkor is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'Áronra is igen megharagudt vala az Úr, és el akará őt is pusztítani; de ugyanakkor imádkozám Áronért is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, 'A ti bűnötöket pedig, a borjút, a melyet készítettetek, megragadám, és megégetém azt tűzzel; és összetörém azt, jól megőrölvén, mígnem porrá morzsolódék, azután bevetém annak porát a patakba, a mely a hegyről foly vala alá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, 'És Thaberában, Massában, és Kibrot-Taavában is haragra indítátok az Urat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'És mikor az Úr elküldött vala titeket Kádes-Barneából, mondván: Menjetek fel, és bírjátok örökségül a földet, a melyet néktek adtam: akkor is tusakodtatok vala az Úrnak, a ti Isteneteknek beszéde ellen, nem hittetek néki, és nem hallgattatok az ő szavára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'Tusakodók voltatok az Úr ellen, a mióta ismerlek titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'És leborulék az Úr előtt azon a negyven napon és negyven éjjel, a melyeken leborultam vala; mert azt mondotta vala az Úr, hogy elveszt titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'Akkor imádkozám az Úrhoz, és mondék: Uram, Isten! ne rontsd meg a te népedet, és a te örökségedet, a kit a te nagyságoddal szabadítottál meg, a kit erős kézzel hoztál ki Égyiptomból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'Emlékezzél meg a te szolgáidról: Ábrahámról, Izsákról és Jákóbról; ne nézzed e népnek keménységét, istentelenségét és bűnét!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'Hogy ne mondja a föld népe, a honnét kihoztál minket: mivelhogy az Úr nem vihette be őket a földre, a melyet igért volt nékik, és mivelhogy gyűlölte őket, azért hozta ki őket, hogy megölje őket a pusztában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'Pedig ők a te néped és a te örökséged, a melyet kihoztál a te nagy erőddel, és a te kinyujtott karoddal!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, 'Abban az időben monda az Úr nékem: Faragj magadnak két kőtáblát, az előbbiekhez hasonlókat, és jőjj fel hozzám a hegyre, és csinálj faládát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'És felírom a táblákra azokat az ígéket, a melyek az előbbi táblákon valának, a melyeket széttörtél; és tedd azokat a ládába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'Csinálék azért ládát sittim-fából, és faragék két kőtáblát is, az előbbiekhez hasonlókat; és felmenék a hegyre, és a két kőtábla kezemben vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'És felírá a táblákra az előbbi írás szerint a tíz ígét, a melyeket szólott vala az Úr ti hozzátok a hegyen, a tűznek közepéből a gyülekezésnek napján, és átadá az Úr azokat nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'Akkor megfordulék és alájövék a hegyről, és betevém a táblákat a ládába, a melyet csináltam vala, hogy ott legyenek, a miképen az Úr parancsolta vala nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, 'Izráel fiai pedig elindulának Beeróthból, a mely a Jákán fiaié, Moszérába. Ott halt meg Áron, és ugyanott el is temetteték, és Eleázár, az ő fia lőn pappá helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'Innét indulának Gudgódba, Gudgódból pedig Jotbatába, bővízű patakok földére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'Abban az időben választá ki az Úr a Lévi törzsét, hogy hordozza az Úr szövetségének ládáját, és hogy az Úr előtt álljon, és néki szolgáljon, és hogy áldjon az ő nevében mind e napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'Ezért nem volt része és öröksége a Lévinek az ő atyafiaival; az Úr az ő öröksége, a miképen megmondotta vala néki az Úr, a te Istened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, 'Én pedig ott állottam a hegyen, mint az előbbi napokban, negyven nap és negyven éjjel: és meghallgata engem az Úr akkor is, és nem akara téged elveszteni az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'És monda az Úr nékem: Kelj fel, menj és járj a nép előtt, hogy bemenjenek és bírják a földet, a mely felől megesküdtem az ő atyáiknak, hogy nékik adom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'Most pedig, óh Izráel! mit kíván az Úr, a te Istened tőled? Csak azt, hogy féljed az Urat, a te Istenedet; hogy minden ő utain járj, és szeresd őt, és tiszteljed az Urat, a te Istenedet teljes szívedből, és teljes lelkedből,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'Megtartván az Úrnak parancsolatait és rendeléseit, a melyeket én ma parancsolok néked, hogy jól legyen dolgod!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'Ímé az Úréi, a te Istenedéi az egek, és az egeknek egei, a föld, és minden, a mi rajta van!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'De egyedül a ti atyáitokat kedvelte az Úr, hogy szeresse őket, és az ő magvokat: titeket választott ki ő utánok minden nép közül, a mint e mai napon is látszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'Metéljétek azért körül a ti szíveteket, és ne legyetek ezután keménynyakúak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'Mert az Úr, a ti Istenetek, isteneknek Istene, és uraknak Ura; nagy, hatalmas és rettenetes Isten, a ki nem személyválogató, sem ajándékot el nem fogad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'Igazságot szolgáltat az árvának és az özvegynek; szereti a jövevényt, adván néki kenyeret és ruházatot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'Szeressétek azért a jövevényt; mert ti is jövevények voltatok Égyiptom földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'Az Urat, a te Istenedet féljed, őt tiszteljed, ő hozzá ragaszkodjál, és az ő nevére esküdjél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'Ő a te dícséreted, és a te Istened, a ki azokat a nagy és rettenetes dolgokat cselekedte veled, a melyeket láttak a te szemeid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'A te atyáid hetvenen mentek vala alá Égyiptomba; most pedig az Úr, a te Istened megsokasított téged, mint az égnek csillagait!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, 'Szeresd azért az Urat, a te Istenedet, tartsd meg az ő megtartani valóit: rendeléseit, végzéseit és parancsolatait minden időben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'És tudjátok meg ma (mert nem a ti fiaitokkal szólok, a kik nem tudják és nem látták) az Úrnak, a te Isteneteknek fenyítését, nagyságát, erős kezét és kinyújtott karját,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'Jeleit és cselekedeteit, a melyeket Égyiptomban cselekedett a Faraóval, az égyiptombeliek királyával, és az ő egész földével;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'És a melyeket cselekedett az égyiptombeliek seregével, lovaival és szekereivel, mivelhogy reájok árasztá a Veres tenger vizeit, mikor üldözének titeket, és elveszté őket az Úr mind e mai napig;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'És a melyeket cselekedett veletek a pusztában, a míg e helyre jutátok;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'És a melyeket cselekedett Dáthánnal és Abirámmal, Eliábnak a Rúben fiának fiaival, mikor a föld megnyitá az ő száját, és elnyelé őket háznépeikkel, sátoraikkal, és minden marhájokkal egyetemben, a mely az övék vala, az egész Izráel között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'Mert saját szemeitekkel láttátok az Úrnak minden nagy cselekedetét, a melyeket cselekedett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'Tartsátok meg azért mind a parancsolatokat, a melyeket én ma parancsolok néked, hogy megerősödjetek, bemenjetek és bírjátok a földet, a melyre átmentek, hogy bírjátok azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'És hogy sok ideig élhessetek a földön, a mely felől megesküdt az Úr a ti atyáitoknak, hogy nékik és az ő magvoknak adja azt a tejjel és mézzel folyó földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, 'Mert a föld, a melyre te bemégy, hogy bírjad azt, nem olyan az, mint Égyiptomnak földe, a honnan kijöttetek; a melyben elveted vala a te magodat és a te lábaddal kell vala megöntöznöd, mint egy veteményes kertet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'Hanem az a föld, a melyre átmentek, hogy bírjátok azt, hegyes-völgyes föld, az égnek esőjéből iszik vizet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'Oly föld az, a melyre az Úr, a te Istened visel gondot; mindenkor rajta függenek az Úrnak, a te Istenednek szemei az esztendő kezdetétől az esztendő végéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, 'Lészen azért, hogyha valóban engedelmeskedtek az én parancsolataimnak, a melyeket én ma parancsolok néktek, úgy hogy az Urat, a ti Istenteket szeretitek, és néki szolgáltok teljes szívetekből és teljes lelketekből:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, 'Esőt adok a ti földetekre alkalmatos időben: korai és kései esőt, hogy betakaríthasd a te gabonádat, borodat és olajodat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'Füvet is adok a te meződre a te barmaidnak; te pedig eszel és megelégszel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'Vigyázzatok azért, hogy a ti szívetek meg ne csalattassék, és el ne térjetek, és ne tiszteljetek idegen isteneket, és ne boruljatok le előttök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'Különben az Úrnak haragja felgerjed reátok, és bezárja az eget, hogy eső ne legyen, és a föld az ő gyümölcsét meg ne teremje; és hamarsággal elvesztek a jó földről, a melyet az Úr ád néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, 'Vegyétek azért szívetekre és lelketekre e szavaimat, és kössétek azokat jegyül a ti kezetekre, és homlokkötőkül legyenek a ti szemeitek között;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'És tanítsátok meg azokra a ti fiaitokat, szólván azokról, mikor házadban ülsz, mikor úton jársz, mikor fekszel és mikor felkelsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'És írd fel azokat a te házadnak ajtófeleire és a te kapuidra;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'Hogy megsokasodjanak a ti napjaitok és fiaitoknak napjai azon a földön, a mely felől megesküdt az Úr a ti atyáitoknak, hogy nékik adja mindaddig, a míg az ég a föld felett lészen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'Mert ha szorosan megtartjátok mind e parancsolatot, a melyet én parancsolok néktek, hogy a szerint cselekedjetek; ha szeretitek az Urat, a ti Istenteket, ha minden ő útain jártok, és ő hozzá ragaszkodtok:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'Akkor kiűzi az Úr mind azokat a nemzeteket ti előletek, és úrrá lesztek nálatoknál nagyobb és erősebb nemzeteken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'Minden hely, a melyet lábatok talpa megnyom, tiétek lesz, a pusztától a Libanonig, és a folyóvíztől, az Eufrátes folyóvizétől a nyugoti tengerig lesz a ti határotok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'Nem állhat meg senki előttetek; azt míveli az Úr, a ti Istenetek, hogy féljenek és rettegjenek titeket az egész föld színén, a melyre rátapostok, a mint megmondotta néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'Lásd, én adok ma előtökbe áldást és átkot!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'Az áldást, ha engedelmeskedtek az Úrnak, a ti Istenetek parancsolatainak, a melyeket én e mai napon parancsolok néktek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'Az átkot pedig, ha nem engedelmeskedtek az Úrnak, a ti Istenetek parancsolatainak, és letértek az útról, a melyet én ma parancsolok néktek, és idegen istenek után jártok, a kiket nem ismertetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, 'És mikor bevisz téged az Úr, a te Istened arra a földre, a melyre te bemégy, hogy bírjad azt: akkor mondd el az áldást a Garizim hegyén, az átkot pedig az Ebál hegyén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'Nemde azok túl vannak a Jordánon, a napnyugoti út megett, a Kananeusok földén, a kik a síkságon laknak Gilgálnak átellenében, a Móré tölgyei mellett?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, 'Mert ti átmentek a Jordánon, hogy bemenvén bírhassátok a földet, a melyet az Úr, a ti Istenetek ád néktek. Ha bírni fogjátok azt, és lakni fogtok abban:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'Vigyázzatok, hogy mind e rendelések és végzések szerint cselekedjetek, a melyeket én ma adok ti előtökbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, 'Ezek a rendelések és a végzések, a melyeket meg kell tartanotok, azok szerint cselekedvén azon a földön, a melyet az Úr, a te atyáidnak Istene ád néked, hogy bírjad azt minden időben a míg éltek a földön:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, 'Pusztára pusztítsátok el mind azokat a helyeket, a hol azok a nemzetek, a kiknek ti urai lesztek, szolgáltak az ő isteneiknek a magas hegyeken, a halmokon, és minden zöldelő fa alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'És rontsátok el azoknak oltárait, törjétek össze oszlopaikat, tűzzel égessétek meg berkeiket, és vagdaljátok szét az ő isteneiknek faragott képeit, a nevöket is pusztítsátok ki arról a helyről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, 'Ne cselekedjetek így az Úrral, a ti Istenetekkel;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'Hanem azt a helyet, a melyet kiválaszt az Úr, a ti Istenetek minden ti törzsetek közül, hogy az ő nevét oda helyezze és ott lakozzék, azt gyakoroljátok és oda menjetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'És oda vigyétek egészen égőáldozataitokat, véres áldozataitokat, tizedeiteket, kezeiteknek felemelt áldozatát, mind fogadásból, mind szabad akaratból való adományaitokat, és a ti barmaitoknak és juhaitoknak első fajzását.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'És ott egyetek az Úrnak, a ti Isteneteknek színe előtt, és örvendezzetek ti és a ti házatok minden népe, kezetek minden keresményének, a melyekkel megáld téged az Úr, a te Istened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'Ne cselekedjetek ott mind a szerint, a mint mi cselekszünk itt most, mindenik azt, a mi jónak látszik néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'Mert még ez ideig nem mentetek be a nyugodalmas helyre, és az örökségbe, a melyet az Úr, a te Istened ád néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'Mikor pedig átmentek a Jordánon, és lakozni fogtok azon a földön, a melyet az Úr, a ti Istenetek ád néktek örökségül, és megnyugtat titeket minden ellenségetektől, a kik körületek vannak, és bátorsággal fogtok lakozni:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'Akkor arra a helyre, a melyet kiválaszt az Úr, a ti Istenetek, hogy ott lakozzék az ő neve, oda vigyetek mindent, a mit én parancsolok néktek: egészen égőáldozataitokat, véres áldozataitokat, tizedeiteket és kezeiteknek felemelt áldozatát, és minden megkülönböztetett fogadástokat, a melyeket fogadtok az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'És örvendezzetek az Úrnak, a ti Isteneteknek színe előtt, mind ti, mind a ti fiaitok, és leányaitok, mind a ti szolgáitok és szolgálóleányaitok, mind a lévita, a ki a ti kapuitokon belől lészen; mert nincs néki része vagy öröksége ti veletek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'Vigyázz, hogy a te egészen égőáldozataidat ne áldozzad minden helyen, a melyet meglátsz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'Hanem azon a helyen, a melyet kiválaszt az Úr a te törzseid közül valamelyikben: ott áldozzad a te egészen égőáldozatidat, és ott cselekedjél mindent, a mit én parancsolok néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, 'Mindazáltal a te lelkednek teljes kívánsága szerint vághatsz barmot és ehetel húst, minden te kapuidon belől, az Úrnak, a te Istenednek áldásához képest, a melyet ád néked; mind a tisztátalan, mind a tiszta eheti azt, ép úgy mint az őzet és a szarvast.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'Csakhogy a vért meg ne egyétek; a földre öntsd azt, mint a vizet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'Nem eheted meg a te kapuidon belől sem gabonádnak, sem mustodnak, sem olajodnak tizedét, sem barmaidnak és juhaidnak első fajzását; sem semmi fogadási áldozatodat, a melyet fogadsz, sem szabad akarat szerint való adományaidat, sem a te kezednek felemelt áldozatát;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'Hanem az Úrnak a te Istenednek színe előtt egyed azokat azon a helyen, a melyet kiválaszt az Úr a te Istened: te és a te fiad, leányod, szolgád, szolgálóleányod és a lévita, a ki a te kapuidon belől van; és örvendezzél az Úrnak, a te Istenednek színe előtt mindenben, a mire kezedet veted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'Vigyázz, hogy el ne hagyjad a lévitát valameddig élsz a te földeden.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, 'Mikor az Úr, a te Istened kiszélesíti a te határodat, a miképen igérte vala néked, és ezt mondod: Húst ehetném! mivelhogy a te lelked húst kíván enni: egyél húst a te lelkednek teljes kívánsága szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'Ha messze van tőled a hely, a melyet az Úr, a te Istened választ, hogy oda helyezze az ő nevét, és leölsz, a mint parancsoltam néked, a te barmaidból és juhaidból, a melyeket az Úr ád majd néked: akkor egyél azokból a te kapuidban a te lelkednek teljes kívánsága szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'De, a mint az őzet és a szarvast eszik, úgy egyed azokat; a tisztátalan és a tiszta egyaránt ehetik abból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'Csakhogy abban állhatatos légy, hogy a vért meg ne egyed; mert a vér, az a lélek: azért a lelket a hússal együtt meg ne egyed!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'Meg ne egyed azt, a földre öntsd azt, mint a vizet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'Meg ne egyed azt, hogy jól legyen dolgod néked és a te gyermekeidnek is utánad, mivelhogy azt cselekszed, a mi igaz az Úr szemei előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'De ha valamit megszentelsz a tiéidből, vagy fogadást teszesz: vedd fel, és vidd azt arra a helyre, a melyet kiválaszt az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'És az Úrnak, a te Istenednek oltárán áldozd meg a te egészen égőáldozataidat, azoknak húsát és vérét; egyéb áldozataidnak vérét azonban öntsd az Úrnak, a te Istenednek oltárára, a húsát pedig megeheted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'Vigyázz és hallgasd meg mindezeket az ígéket, a melyeket én parancsolok néked, hogy jól legyen dolgod, néked és a te gyermekeidnek utánad mind örökké; mivelhogy azt cselekszed, a mi jó és igaz az Úrnak, a te Istenednek szemei előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, 'Mikor kiirtja előled az Úr, a te Istened a nemzeteket, a kikhez bemégy, hogy bírjad őket, és bírni fogod őket, és lakozol majd az ő földükön:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'Vigyázz magadra, hogy őket követvén tőrbe ne essél, miután már kivesztek előled; és ne tudakozzál az ő isteneik felől, mondván: Miképen tisztelik e nemzetek az ő isteneiket? én is akképen cselekszem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, 'Ne cselekedjél így az Úrral, a te Isteneddel, mert mind azt az útálatosságot, a mit gyűlöl az Úr, megcselekedték az ő isteneikkel; mert még fiaikat és leányaikat is megégetik vala tűzzel az ő isteneiknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 32, 'Mindazt, a mit én parancsolok néktek, megtartsátok, és a szerint cselekedjetek: semmit ne tégy ahhoz, és el se végy abból!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, 'Mikor te közötted jövendőmondó, vagy álomlátó támad és jelt vagy csodát ád néked;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, 'Ha bekövetkezik is az a jel vagy a csoda, a melyről szólott vala néked, mondván: Kövessünk idegen isteneket, a kiket te nem ismersz, és tiszteljük azokat:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, 'Ne hallgass efféle jövendőmondónak beszédeire, vagy az efféle álomlátóra; mert az Úr, a ti Istenetek kísért titeket, hogy megtudja, ha szeretitek-é az Urat, a ti Isteneteket teljes szívetekből, és teljes lelketekből?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'Az Urat, a ti Isteneteket kövessétek, és őt féljétek, és az ő parancsolatait tartsátok meg, és az ő szavára hallgassatok, őt tiszteljétek, és ő hozzá ragaszkodjatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'Az a jövendőmondó pedig vagy álomlátó ölettessék meg; mert pártütést hirdetett az Úr ellen, a ti Istenetek ellen, a ki kihozott titeket Égyiptom földéből, és megszabadított téged a szolgaságnak házából; hogy elfordítson téged arról az útról, a melyet parancsolt néked az Úr, a te Istened, hogy azon járj. Gyomláld ki azért a gonoszt magad közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'Ha testvéred, a te anyádnak fia, vagy a te fiad vagy leányod, vagy a kebleden lévő feleség, vagy lelki-testi barátod titkon csalogat, mondván: Nosza menjünk és tiszteljünk idegen isteneket, a kiket nem ismertetek sem te, sem atyáid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'Ama népek istenei közül, a kik körültetek vannak, közel hozzád vagy távol tőled, a földnek egyik végétől a másik végéig:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'Ne engedj néki, és ne hallgass reá, ne nézz reá szánalommal, ne kíméld és ne rejtegesd őt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'Hanem megölvén megöljed őt; a te kezed legyen először rajta az ő megölésére, azután pedig az egész népnek keze.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'Kövekkel kövezd meg őt, hogy meghaljon; mert azon igyekezett, hogy elfordítson téged az Úrtól, a te Istenedtől, a ki kihozott téged Égyiptomnak földéből, a szolgaságnak házából;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'És hallja meg az egész Izráel, és féljenek és ne cselekedjenek többé ahhoz hasonló gonoszt te közötted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, 'Ha valamelyikben a te városaid közül, a melyeket az Úr, a te Istened ád néked, hogy ott lakjál, ezt hallod mondani:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, 'Emberek jöttek ki közüled, istentelenségnek fiai, és elfordítják városuk lakosait, mondván: Nosza, menjünk és tiszteljünk idegen isteneket, a kiket nem ismertetek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, 'Akkor keress, kutass és szorgalmatosan tudakozódjál, és ha igaz, és bizonyos a dolog, és megtörtént az efféle útálatosság közötted:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'Hányd kard élére annak a városnak lakosait; áldozd fel azt mindenestől, a mi benne van; a barmát is kard élére hányd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'És a mi préda van benne, hordd mind együvé az ő piaczának közepére, és égesd meg a várost tűzzel és annak minden prédáját is teljes áldozatul az Úrnak, a te Istenednek, és legyen rom mind örökké, és soha többé fel ne építtessék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'Ne ragadjon semmi a te kezedhez abból az átokra valóból, hogy szűnjék meg az Úr haragjának búsulása, és könyörületes legyen hozzád, és könyörüljön rajtad, és megszaporítson téged, a miképen megesküdt a te atyáidnak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'Ha hallgatsz az Úrnak, a te Istenednek szavára, megtartván minden ő parancsolatát, a melyeket én ma parancsolok néked, hogy azt cselekedjed, a mi igaz az Úrnak, a te Istenednek szemei előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, 'Ti az Úrnak, a ti Isteneteknek fiai vagytok; ne vagdaljátok meg magatokat, se szemeitek között ne csináljatok kopaszságot, a halottért,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'Mert szent népe vagy te az Úrnak, a te Istenednek, és az Úr választott téged, hogy légy néki tulajdon népe minden nép közül, a melyek a föld színén vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'Semmi útálatosságot meg ne egyél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'Ezek azok az állatok, a melyeket megehettek: az ökör, juh, kecske,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'Szarvas, őz, bival, vadkecske, zerge, vad bika és jávor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'És mindazt az állatot, a melynek hasadt a körme és egészen ketté hasadt körme van, és kérődző az állatok között, megehetitek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'De a kérődzők és hasadt körműek közül ne egyétek meg ezeket: a tevét, a nyulat és hörcsököt, mert kérődznek ugyan, de körmük nem hasadt; tisztátalanok legyenek ezek néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'És a disznót, mert hasadt ugyan a körme, de nem kérődzik; tisztátalan legyen ez néktek. Ezeknek húsából ne egyetek, holttestöket se illessétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, 'Ezeket ehetitek meg mindazokból, melyek vízben élnek: a minek úszó szárnya és pikkelye van, mind megegyétek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'Valaminek pedig nincsen úszó szárnya és pikkelye, meg ne egyétek; tisztátalan az néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'Minden tiszta madarat megehettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'Ezek pedig, a melyeket meg ne egyetek közülök: a sas, a saskeselyű és a halászó sas.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, 'A keselyű, a héja és a sólyom az ő nemével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, 'Minden holló az ő nemével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'A strucz, a bagoly, a kakuk és a karvaly az ő nemével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'A kuvik, a fülesbagoly és a bölömbika.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'A pelikán, a gém és a hattyú.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'Az eszterág és a szarka az ő nemével; a büdösbanka és a denevér.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'Minden szárnyas féreg is tisztátalan legyen néktek; meg ne egyétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'Minden tiszta szárnyast megehettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, 'Semmi holttestet meg ne egyetek; a jövevénynek, a ki a te kapuidon belől van, adjad azt, hogy egye meg azt, vagy add el az idegennek, mert szent népe vagy te az Úrnak, a te Istenednek. Ne főzd a gödölyét az ő anyja tejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'Esztendőről esztendőre tizedet végy a te magodnak minden terméséből, a mely a te meződön terem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'És egyed az Úrnak, a te Istenednek színe előtt azon a helyen, a melyet kiválaszt, hogy ott lakozzék az ő neve, gabonádnak, mustodnak, olajodnak tizedét, a te barmaidnak és juhaidnak első fajzását; hogy tanuljad félni az Urat, a te Istenedet minden időben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'Ha pedig hosszabb néked az út, hogysem oda vihetnéd azokat, mivelhogy távol esik tőled az a hely, a melyet az Úr, a te Istened választ, hogy oda helyezze az ő nevét, téged pedig megáldott az Úr, a te Istened:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'Akkor add el pénzen, és kösd a kezedbe a pénzt, és menj el arra a helyre, a melyet kiválaszt az Úr, a te Istened;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'És adjad a pénzt mind azért, a mit kíván a te lelked: ökrökért, juhokért, borért és vidámító italért és mindenért, a mit megáhít néked a te lelked, és egyél ott az Úrnak, a te Istenednek színe előtt, és örvendezzél te és a te házadnak népe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'A lévitát pedig, a ki a te kapuidon belől van, ne hagyd el, mert nincsen néki része, sem öröksége veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'A harmadik esztendő végén vidd ki annak az esztendő termésének minden tizedét, és rakd le a te kapuidba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'És eljön a lévita (a kinek nincsen része és öröksége te veled), és a jövevény, árva és özvegy, a kik a te kapuidon belől vannak, és esznek és megelégesznek, hogy megáldjon téged az Úr, a te Istened a te kezednek minden munkájában, a melyet végzesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, 'A hetedik esztendő végén elengedést mívelj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'Ez pedig az elengedésnek módja: Minden kölcsönadó ember engedje el, a mit kölcsönadott az ő felebarátjának; ne hajtsa be az ő felebarátján és atyjafián; mert elengedés hirdettetett az Úrért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'Az idegenen hajtsd be; de a mid a te atyádfiánál lesz, engedje el néki a te kezed.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'De nem is lesz közötted szegény, mert igen megáld téged az Úr azon a földön, a melyet az Úr, a te Istened ád néked örökségül, hogy bírjad azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'De csak úgy lesz ez, ha hallgatsz az Úrnak, a te Istenednek szavára, megtartván és teljesítvén mind azt a parancsolatot, a melyet én ma parancsolok néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'Mert az Úr, a te Istened megáld téged, a miképen megmondotta néked; és sok népnek adsz zálogos kölcsönt, te pedig nem kérsz kölcsönt, és sok népen fogsz uralkodni, és te rajtad nem uralkodnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, 'Ha mégis szegénynyé lesz valaki a te atyádfiai közül valamelyikben a te kapuid közül a te földeden, a melyet az Úr, a te Istened ád néked: ne keményítsd meg a te szívedet, be se zárjad kezedet a te szegény atyádfia előtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'Hanem örömest nyisd meg a te kezedet néki, és örömest adj kölcsön néki, a mennyi elég az ő szükségére, a mi nélkül szűkölködik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'Vigyázz magadra, hogy ne legyen a te szívedben valami istentelenség, mondván: Közelget a hetedik esztendő, az elengedésnek esztendeje; és elfordítsd szemedet a te szegény atyádfiától, hogy ne adj néki; mert ő ellened kiált az Úrhoz, és bűn lesz benned.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'Bizonyára adj néki, és meg ne háborodjék azon a te szíved, mikor adsz néki; mert az ilyen dologért áld meg téged az Úr, a te Istened minden munkádban, és mindenben, a mire kezedet veted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'Mert a szegény nem fogy ki a földről, azért én parancsolom néked, mondván: Örömest nyisd meg kezedet a te szűkölködő és szegény atyádfiának a te földeden.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, 'Hogyha eladja magát néked a te atyádfia, a zsidó férfi és zsidó asszony, és szolgál téged hat esztendeig: a hetedik esztendőben bocsássad őt szabadon mellőled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'És mikor szabadon bocsátod őt mellőled, ne bocsásd el őt üresen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'Hanem terheld meg őt bőven a te juhaidból, a te szérűdről, és a te sajtódból; a mivel megáldott téged az Úr, a te Istened, adj néki abból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'És emlékezzél meg róla, hogy te is szolga voltál Égyiptom földén, és megszabadított téged az Úr, a te Istened; azért parancsolom én ma ezt néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'Ha pedig ezt mondja néked: Nem megyek el tőled, mert szeret téged és a te házadat, mivelhogy jól van néki te nálad dolga:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'Akkor vedd az árat, és fúrd a fülébe és az ajtóba; és legyen szolgáddá mindvégig; így cselekedjél szolgálóleányoddal is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'Ne essék nehezedre, hogy szabadon bocsátod őt mellőled; (hiszen két annyi bérre valót szolgált néked hat éven át, mint a béres-munkás) és megáld téged az Úr, a te Istened mindenben, a mit cselekszel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, 'Barmaid és juhaid első fajzásának minden hímjét az Úrnak, a te Istenednek szenteljed. Ne munkálkodjál a te tehenednek első fajzásán, és meg ne nyírjad a te juhaidnak első fajzását.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'Az Úrnak, a te Istenednek színe előtt edd meg azt esztendőről esztendőre, te és a te házad népe, azon a helyen, a melyet kiválaszt az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'Hogyha valami fogyatkozás lesz benne; sánta vagy vak lesz, vagy akármely fogyatkozásban szenvedő: meg ne áldozd azt az Úrnak, a te Istenednek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'A te kapuidon belől edd meg azt; a tisztátalan és a tiszta egyaránt, mintha őz volna az vagy szarvas.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'Csakhogy a vérét meg ne edd, hanem a földre öntsd azt, mint a vizet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, 'Ügyelj az Abib hónapra, és készíts az Úrnak, a te Istenednek páskhát; mert az Abib hónapban hozott ki téged az Úr, a te Istened Égyiptomból éjjel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'Páskha gyanánt pedig ölj az Úrnak, a te Istenednek juhot és ökröt azon a helyen, a melyet kiválaszt az Úr, a te Istened, hogy oda helyezze az ő nevét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'Ne egyél azzal semmi kovászost, hanem hét napon át egyél azzal kovásztalan lepényeket, nyomorúságnak kenyerét, (mert sietséggel jöttél ki Égyiptom földéről) hogy megemlékezzél arról a napról életednek minden idejében, a melyen kijöttél Égyiptom földéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'És ne lásson senki kovászt hét napon át sehol a te határodban; és a húsból, a melyet az első napon estve megáldozol, semmi ne maradjon reggelig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, 'Nem ölheted le a páskhát akármelyikben a te városaid közül, a melyeket az Úr, a te Istened ád néked;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'Hanem azon a helyen, a melyet kiválaszt az Úr, a te Istened, hogy az ő nevét oda helyezze: ott öld le a páskhát estve, napnyugtakor, abban az időben, a mikor kijöttél Égyiptomból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'Azon a helyen süsd és edd is meg, a melyet kiválaszt az Úr, a te Istened; reggel pedig fordulj vissza és menj haza a te hajlékodba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'Hat napon át egyél kovásztalant; hetednapon pedig az Úrnak, a te Istenednek berekesztő ünnepe lévén, ne munkálkodjál azon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'Számlálj azután magadnak hét hetet; attól fogva kezdjed számlálni a hét hetet, hogy sarlódat a vetésbe bocsátod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'És tarts hetek ünnepét az Úrnak, a te Istenednek, a te kezednek szabad akarat szerint való adományával, a melyet ahhoz képest adj, a mint megáldott téged az Úr, a te Istened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'És örvendezz az Úrnak, a te Istenednek színe előtt, te és a te fiad, és leányod, szolgád, szolgálóleányod, és a lévita, a ki a te kapuidon belől van, és a jövevény, az árva és az özvegy, a kik te közötted vannak, azon a helyen, a melyet kiválasztott az Úr, a te Istened, hogy oda helyezze az ő nevét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'És emlékezzél meg róla, hogy te is szolga voltál Égyiptomban; és tartsd meg, és teljesítsd e rendeléseket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'A sátorok ünnepét hét napig tartsd, mikor begyűjtöd a termést a te szérűdről és sajtódról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'És örvendezz a te ünnepeden, te és a te fiad, a te leányod, szolgád és szolgálóleányod, a lévita, a jövevény, az árva és az özvegy, a kik belől vannak a te kapuidon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'Hét napig ünnepelj az Úrnak, a te Istenednek azon a helyen, a melyet kiválaszt az Úr; mert megáld téged az Úr, a te Istened minden termésedben, és kezeidnek minden munkájában; azért örvendezz igen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, 'Minden esztendőben háromszor jelenjen meg közüled minden férfiú az Úrnak, a te Istenednek színe előtt azon a helyen, a melyet kiválaszt; a kovásztalan kenyerek ünnepén, a hetek ünnepén, és a sátorok ünnepén. De üres kézzel senki se jelenjen meg az Úr előtt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, 'Kiki az ő képessége szerint adjon, az Úrnak, a te Istenednek áldása szerint, a melyet ád néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, 'Bírákat és felügyelőket állíts minden kapudba, a melyeket az Úr, a te Istened ád néked, a te törzseid szerint, hogy ítéljék a népet igaz ítélettel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'El ne fordítsd az itéletet; személyt se válogass; ajándékot se végy; mert az ajándék megvakítja a bölcsek szemeit, és elfordítja az igazak beszédét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'Igazságot, igazságot kövess, hogy élhess, és örökségül bírhasd azt a földet, a melyet az Úr, a te Istened ád néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, 'Ne plántálj magadnak berket semmiféle fából, az Úrnak, a te Istenednek oltára mellé, a melyet készítesz magadnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'Oszlopot se emelj magadnak, a mit gyűlöl az Úr, a te Istened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, 'Ne áldozzál az Úrnak, a te Istenednek olyan ökröt és juhot, a melyen valami fogyatkozás van, akármi hiba; mert útálatosság az az Úrnak, a te Istenednek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, 'Hogyha találtatik közötted valamelyikben a te kapuid közül, a melyeket az Úr, a te Istened ád néked, vagy férfiú vagy asszony, a ki gonoszt cselekszik az Úrnak, a te Istenednek szemei előtt, megszegvén az ő szövetségét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'És elmegy és szolgál idegen isteneket, és imádja azokat, akár a napot, akár a holdat, vagy akármelyet az égnek seregei közül, a melyet nem parancsoltam;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'És megjelentetik néked, és meghallod: jól megtudakozd; és hogyha igaz, és bizonyos a dolog, és megtörtént ez az útálatosság Izráelben:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'Akkor vidd ki azt a férfiút vagy azt az asszonyt, a ki azt a gonoszságot mívelte, a te kapuidba, (a férfiút vagy az asszonyt) és kövezd agyon őket, hogy meghaljanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'Két tanú vagy három tanú szavára halállal lakoljon a halálra való; de egy tanú szavára meg ne haljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'A tanúk keze legyen első rajta, hogy megölettessék, és azután mind az egész nép keze. Így tisztítsd ki magad közül a gonoszt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, 'Ha megfoghatatlan valami előtted, a mikor ítélned kell vér és vér között, ügy és ügy között, sérelem és sérelem között, vagy egyéb versengések között a te kapuidban: akkor kelj fel, és menj el arra a helyre, a melyet kiválaszt az Úr, a te Istened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'És menj be a Lévita-papokhoz és a bíróhoz, a ki lesz majd abban az időben; és kérdezd meg őket, és ők tudtul adják néked az ítéletmondást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'És annak a mondásnak értelme szerint cselekedjél, a melyet tudtul adnak néked azon a helyen, a melyet kiválaszt az Úr; és vigyázz, hogy mind a szerint cselekedjél, a mint tanítanak téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'A törvény szerint cselekedjél, a melyre tanítanak téged, és az ítélet szerint, a melyet mondanak néked; el ne hajolj attól a mondástól, a melyet tudtul adnak néked, se jobbra, se balra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'Ha pedig elbizakodottságból azt cselekszi valaki, hogy nem hallgat a papra, a ki ott áll, szolgálván az Urat, a te Istenedet, vagy a bíróra: haljon meg az ilyen ember. Így tisztítsd ki a gonoszt Izráelből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'És mind az egész nép hallja, és féljen, hogy elbizakodottan senki ne cselekedjék többé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, 'Mikor bemégy arra a földre, a melyet az Úr, a te Istened ád néked, és bírod azt, és lakozol abban, és ezt mondod: Királyt teszek magam fölé, miképen egyéb népek, a melyek körültem vannak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'Azt emeld magad fölé királyul, a kit az Úr, a te Istened választ. A te atyádfiai közül emelj magad fölé királyt; nem tehetsz magad fölé idegent, a ki nem atyádfia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'Csak sok lovat ne tartson, és a népet vissza ne vigye Égyiptomba, hogy lovat sokasítson, mivelhogy az Úr megmondta néktek: Ne térjetek többé vissza azon az úton!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'Sok feleséget se tartson, hogy a szíve el ne hajoljon; se ezüstjét, se aranyát felettébb meg ne sokasítsa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'És mikor az ő országának királyi székére ül, írja le magának könyvbe e törvénynek mását a Lévita-papokéból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'És legyen az ő nála, és olvassa azt életének minden idejében, hogy tanulja félni az Urat, a te Istenedet, hogy megtartsa e törvénynek minden ígéjét, és e rendeléseket, hogy azokat cselekedje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'Fel ne fuvalkodjék az ő szíve az ő atyjafiai ellen, se el ne hajoljon a parancsolattól jobbra vagy balra, hogy hosszú ideig éljen az ő országában ő és az ő fiai Izráelben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, 'A Lévita-papoknak, a Lévi egész nemzetségének ne legyen se része, se öröksége Izráellel, hanem éljenek az Úrnak tüzes áldozatjaiból és örökségéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'Annakokáért ne legyen néki öröksége az ő atyjafiai között: Az Úr az ő öröksége, a mint megmondotta néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'És ez legyen a papoknak törvényes része a néptől, azoktól, a kik áldoznak akár ökörrel, akár juhval, hogy a papnak adják a lapoczkát, a két állat és a gyomrot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'A te gabonád, mustod és olajod zsengéjét, és a te juhaid gyapjának zsengéjét néki adjad;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'Mert őt választotta ki az Úr, a te Istened minden te nemzetséged közül, hogy álljon szolgálatra az Úrnak nevében, ő és az ő fiai minden időben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'Mikor pedig eljön a Lévita valamelyikből a te egész Izráelben lévő kapuid közül, a hol ő lakik, és bemegy az ő lelkének teljes kívánsága szerint arra a helyre, a melyet kiválaszt az Úr:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'Szolgáljon az Úrnak az ő Istenének nevében, mint az ő többi atyjafiai, a Léviták, a kik ott állanak az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'Az eledelekben egyenlőképen részesedjenek, kivéve azt, a mit eladott valaki az ő atyai örökségéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, 'Mikor te bemégy arra a földre, a melyet az Úr, a te Istened ád néked: ne tanulj cselekedni azoknak a népeknek útálatosságai szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'Ne találtassék te közötted, a ki az ő fiát vagy leányát átvigye a tűzön, se jövendőmondó, se igéző, se jegymagyarázó, se varázsló;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'Se bűbájos, se ördöngősöktől tudakozó, se titok-fejtő, se halottidéző;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'Mert mind útálja az Úr, a ki ezeket míveli, és ez ilyen útálatosságokért űzi ki őket az Úr, a te Istened te előled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'Tökéletes légy az Úrral, a te Isteneddel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'Mert ezek a nemzetek, a kiket te elűzesz, igézőkre és jövendőmondókra hallgatnak; de tenéked nem engedett ilyet az Úr, a te Istened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'Prófétát támaszt néked az Úr, a te Istened te közüled, a te atyádfiai közül, olyat mint én: azt hallgassátok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, 'Mind a szerint, amint kérted az Úrtól, a te Istenedtől a Hóreben a gyülekezésnek napján mondván: Ne halljam többé az Úrnak, az én Istenemnek szavát, és ne lássam többé ezt a nagy tüzet, hogy meg ne haljak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'Az Úr pedig monda nékem: Jól mondták a mit mondtak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'Prófétát támasztok nékik az ő atyjokfiai közül, olyat mint te, és az én ígéimet adom annak szájába, és megmond nékik mindent, a mit parancsolok néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'És ha valaki nem hallgat az én ígéimre, a melyeket az én nevemben szól, én megkeresem azon!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'De az a próféta, a ki olyat mer szólani az én nevemben, a mit én nem parancsoltam néki szólani, és a ki idegen istenek nevében szól: haljon meg az a próféta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'Ha pedig azt mondod a te szívedben: miképen ismerhetjük meg az ígét, a melyet nem mondott az Úr?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'Ha a próféta az Úr nevében szól, és nem lesz meg, és nem teljesedik be a dolog: ez az a szó, a melyet nem az Úr szólott; elbizakodottságból mondotta azt a próféta; ne félj attól!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, 'Mikor kiírtja az Úr, a te Istened a nemzeteket, a kiknek földjét néked adja az Úr, a te Istened, és bírni fogod őket, és lakozol az ő városaikban és az ő házaikban:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'Válaszsz ki magadnak három várost a te földeden, a melyet az Úr, a te Istened ád néked, hogy örököljed azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, 'Készítsd meg magadnak az utat azokhoz, és oszszad három részre a te országod határát, a melyet az Úr, a te Istened ád néked örökségül; azok arra valók legyenek, hogy minden gyilkos oda meneküljön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, 'Ez pedig a gyilkos törvénye, a ki oda menekül, hogy élve maradjon: A ki nem szándékosan öli meg az ő felebarátját, és nem gyűlöli vala azt azelőtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'A ki például elmegy az ő felebarátjával az erdőre fát vágni, és meglódul a keze a fejszével, hogy levágja a fát, és leesik a vas a nyeléről, és úgy találja az ő felebarátját, hogy az meghal: az ilyen meneküljön e városok egyikébe, hogy élve maradjon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'Különben a vérbosszuló rokon űzőbe veszi az ő szívének búsulásában, és eléri, ha az út hosszú leend, és agyon üti őt, holott nem méltó a halálra, mivel azelőtt nem gyűlölte azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'Azért én parancsolom néked, mondván: Három várost válaszsz magadnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'Ha pedig az Úr, a te Istened kiterjeszti a te határodat, a mint megesküdt a te atyáidnak, és néked adja mind az egész földet, a melynek megadását megígérte volt a te atyáidnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, '(Hogyha megtartod mind e parancsolatot, megtévén azt, a mit én ma parancsolok néked, tudniillik, hogy szeressed az Urat, a te Istenedet, és járj az ő utain minden időben): akkor e háromhoz szerezz még három várost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'Hogy ártatlan vér ne ontassék ki a te földeden, a melyet az Úr, a te Istened ád néked örökségül, és hogy a vér ne legyen rajtad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'De hogyha lesz valaki, a ki gyűlöli az ő felebarátját, és meglesi azt, és reá támad és úgy üti meg, hogy meghal, és bemenekül valamelyikbe e városok közül:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'Akkor az ő városának vénei küldjenek embereket, és vonják ki azt onnét, és adják azt a vérbosszúló rokon kezébe, hogy meghaljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'Ne nézz reá szánalommal, hanem tisztítsd ki az ártatlan vérontást Izráelből, hogy jól legyen dolgod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, 'A te felebarátodnak határát el ne told, a mely határt az ősök vetettek a te örökségedben, a melyet örökölni fogsz azon a földön, a melyet az Úr, a te Istened ád néked, hogy bírjad azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'Ne álljon elő egy tanú senki ellen semmiféle hamisság és semmiféle bűn miatt; akármilyen bűnben bűnös valaki, két tanú szavára vagy három tanú szavára álljon a dolog.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'Ha valaki ellen gonosz tanú áll elő, hogy pártütéssel vádolja őt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'Akkor álljon az a két ember, a kiknek ilyen perök van, az Úr elé, a papok és a bírák elé, a kik abban az időben lesznek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'És a bírák vizsgálják meg jól a dolgot, és ha hazug tanú lesz a tanú, a ki hazugságot szólott az ő atyjafia ellen:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'Úgy cselekedjetek azzal, a mint ő szándékozott cselekedni az ő atyjafiával. Így tisztítsd ki közüled a gonoszt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'Hogy a kik megmaradnak, hallják meg, és féljenek, és többször ne cselekedjenek te közötted ilyen gonosz dolgot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'Ne nézz reá szánalommal; lelket lélekért, szemet szemért, fogat fogért, kezet kézért, lábat lábért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, 'Mikor hadba mégy ellenséged ellen, és látsz lovakat, szekereket, náladnál nagyobb számú népet: ne félj tőlök, mert veled van az Úr, a te Istened, a ki felhozott téged Égyiptom földéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'És mikor az ütközethez készültök, álljon elő a pap, és szóljon a népnek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, 'És ezt mondja nékik: Hallgasd meg Izráel! Ti ma készültök megütközni ellenségeitekkel: A ti szívetek meg ne lágyuljon, ne féljetek, és meg ne rettenjetek, se meg ne rémüljetek előttök;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'Mert az Úr, a ti Istenetek veletek megy, hogy harczoljon érettetek a ti ellenségeitekkel, hogy megtartson titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'Az előljárók pedig szóljanak a népnek, mondván: Kicsoda az olyan férfi, a ki új házat épített, de még fel nem avatta azt? Menjen el, és térjen vissza az ő házába, hogy meg ne haljon a harczban, és más valaki avassa fel azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'És kicsoda olyan férfi, a ki szőlőt ültetett és nem vette el annak hasznát? Menjen el, és térjen vissza az ő házába, hogy meg ne haljon a harczban, és más valaki vegye el annak hasznát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'És kicsoda olyan férfi, a ki feleséget jegyzett el magának, de még el nem vette? Menjen el, és térjen vissza házába, hogy meg ne haljon a harczban, és más valaki vegye azt el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'Még tovább is szóljanak az előljárók a néphez, és ezt mondják: Kicsoda olyan férfi, a ki félénk és lágy szívű? Menjen el, és térjen vissza az ő házába, hogy az ő atyjafiainak szíve úgy meg ne olvadjon, mint az ő szíve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'És mikor elvégzik az előljárók beszédöket a néphez, állítsanak seregvezéreket a nép élére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, 'Mikor valamely város alá mégy, hogy azt megostromold, békességgel kínáld meg azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'És ha békességgel felel néked, és kaput nyit, akkor az egész nép, a mely találtatik abban, adófizetőd legyen, és szolgáljon néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'Ha pedig nem köt békességet veled, hanem harczra kél veled, akkor zárd azt körül;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'És ha az Úr, a te Istened kezedbe adja azt: vágj le abban minden fineműt fegyver élével;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'De az asszonyokat, a kis gyermekeket, a barmokat és mind azt, a mi lesz a városban, az egész zsákmányolni valót magadnak prédáljad; és fogyaszd el a te ellenségeidtől való zsákmányt, a kiket kezedbe ad néked az Úr, a te Istened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'Így cselekedjél mindazokkal a városokkal, a melyek igen messze esnek tőled, a melyek nem e nemzetek városai közül valók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'De e népek városaiban, a melyeket örökségül ad néked az Úr, a te Istened, ne hagyj élni csak egy lelket is;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'Hanem mindenestől veszítsd el őket: a Khittheust, az Emoreust, a Kananeust, a Perizeust, a Khivveust és a Jebuzeust, a mint megparancsolta néked az Úr, a te Istened;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'Azért, hogy meg ne tanítsanak titeket az ő mindenféle útálatosságaik szerint cselekedni, a melyeket ők cselekesznek az ő isteneiknek, és hogy ne vétkezzetek az Úr ellen, a ti Istenetek ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'Mikor valamely várost hosszabb ideig tartasz körülzárva, hadakozván az ellen, hogy bevegyed azt: ki ne veszítsd annak egy élőfáját sem, fejszével vágván azt; hanem egyél arról, és azt magát ki ne irtsad; mert ember-é a mezőnek fája, hogy ostrom alá jusson miattad?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'Csak a mely fáról tudod, hogy nem gyümölcstermő, azt veszítsd el és irtsd ki, és abból építs erősséget az ellen a város ellen, a mely te ellened hadakozik, mind addig, a míg leomlik az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, 'Hogyha agyonütöttet találnak azon a földön, a melyet az Úr, a te Istened ád néked birtokul, és az a mezőn fekszik, és nem tudható: ki ölte meg azt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'Akkor a te véneid és a te bíráid menjenek ki, és mérjék meg a földet a városokig, a melyek az agyonütött körül vannak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'És a mely város legközelebb esik az agyonütötthöz, annak a városnak vénei vegyenek egy üszőtinót, a melylyel még nem dolgoztattak, és a mely nem vont még jármot;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'És annak a városnak vénei vigyék az üszőt valamely folyóvíz völgyébe, a melyet nem szántanak és nem vetnek, és szegjék nyakát az üszőnek ott a völgyben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'És járuljanak oda a papok, Lévi fiai; (mert őket választotta az Úr, a te Istened, hogy szolgáljanak néki, és hogy áldjanak az Úr nevében, és az ő ítéletök szerint legyen minden per és minden sérelem).');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'És mindnyájan annak a városnak vénei, a kik legközelebb esnek az agyonütötthöz, mossák meg kezeiket a nyakaszegett üsző felett a völgyben;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'És szóljanak és mondják: A mi kezeink nem ontották ki ezt a vért, sem a mi szemeink nem látták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'Bocsáss meg a te népednek, Izráelnek, a melyet megváltottál, Uram, és ne engedd, hogy ártatlan vér ontása legyen Izráel között, a te néped között! És bocsánatot nyernek a vérért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'Te azért tisztítsd ki közüled az ártatlan vérnek kiontását, mert így cselekszed azt, a mi igaz az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, 'Mikor hadba mégy ellenségeid ellen, és kezedbe adja őket az Úr, a te Istened, és azok közül foglyokat ejtesz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'És meglátsz a foglyok között egy szép ábrázatú asszonyt, és megszereted azt, úgy hogy elvennéd feleségül:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'Vidd be őt a te házadba, hogy nyirja meg a fejét, és messe le körmeit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'És az ő fogoly ruháját vesse le magáról, és maradjon a te házadban, hogy sirassa az ő atyját és anyját egész hónapig; és csak azután menj be hozzá, és légy az ő férje, és legyen ő a te feleséged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'Hogyha pedig nem tetszik néked, bocsásd el őt az ő kivánsága szerint; de pénzért semmiképen el ne add őt; ne hatalmaskodjál rajta, miután megrontottad őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, 'Ha valakinek két felesége van, az egyik szeretett, a másik gyűlölt, és szülnek néki fiakat, mind a szeretett, mind a gyűlölt, és a gyűlöltnek fia lesz az elsőszülött:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'Azon a napon, a melyen az ő fiait örökösökké teszi a maga jószágában, nem teheti elsőszülötté a szeretettnek fiát a gyűlöltnek fia felett, a ki elsőszülött;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'Hanem az elsőszülöttet, a gyűlöltnek fiát ismerje el, két részt adván néki mindenből, a mije van; mert az az ő erejének zsengéje, övé az elsőszülöttség joga.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, 'Ha valakinek pártütő és makacs fia van, a ki az ő atyja szavára és anyja szavára nem hallgat, és ha megfenyítik, sem engedelmeskedik nékik:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'Az ilyet fogja meg az ő atyja és anyja, és vigyék azt az ő városának véneihez és az ő helységének kapujába,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'És ezt mondják a város véneinek: Ez a mi fiunk pártütő és makacs, nem hallgat a mi szónkra, tobzódó és részeges:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'Akkor az ő városának minden embere kövekkel kövezze meg azt, hogy meghaljon. Így tisztítsd ki közüled a gonoszt, és az egész Izráel hallja meg, és féljen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, 'Ha valakiben halálos ítéletre való bűn van, és megölik, és felakasztatod azt fára:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'Ne maradjon éjjel az ő holtteste a fán, hanem temesd el azt még azon a napon; mert átkozott Isten előtt a ki fán függ; és meg ne fertéztessed azt a földet, a melyet az Úr, a te Istened ád néked örökségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, 'Ne nézd el, ha a te atyádfiának ökre vagy juha tévelyeg, és ne fordulj el azoktól, hanem bizony tereld vissza azokat a te atyádfiához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'Hogyha pedig nincs közel hozzád a te atyádfia, vagy nem is ismered őt: hajtsd a barmot a magad házához, és legyen nálad, míg keresi azt a te atyádfia, és akkor add vissza néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'És ekképen cselekedjél szamarával, ekképen cselekedjél ruhájával és ekképen cselekedjél a te atyádfiának minden elveszett holmijával, a mi elveszett tőle és te megtaláltad; nem szabad félrevonulnod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'Ha látod, hogy a te atyádfiának szamara vagy ökre az úton eldűlve fekszik, ne fordulj el azoktól, hanem vele együtt emeld fel azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, 'Asszony ne viseljen férfiruházatot, se férfi ne öltözzék asszonyruhába; mert mind útálatos az Úr előtt, a te Istened előtt, a ki ezt míveli.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'Ha madárfészek akad elédbe az úton valamely fán vagy a földön, madárfiakkal vagy tojásokkal, és az anya rajta ül a fiakon vagy a tojásokon: meg ne fogd az anyát a fiakkal egyben;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'Hanem bizony bocsásd el az anyát, és a fiakat fogd el magadnak, hogy jól legyen dolgod, és hosszú ideig élj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'Ha új házat építesz, házfedeledre korlátot csinálj, hogy vérrel ne terheld a te házadat, ha valaki leesik arról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, 'Ne vess a te szőlődbe kétféle magot, hogy fertőzötté ne legyen az egész: a mag, a melyet elvetsz és a szőlőnek termése.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, 'Ne szánts ökrön és szamáron együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, 'Ne öltözzél vegyes szövésű azaz gyapjúból és lenből szőtt ruhába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'A te felsőruhádnak négy szegletére, a melyet felülre öltesz, bojtokat csinálj magadnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, 'Ha valaki feleséget vesz, és bemegy hozzá, és meggyűlöli azt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, 'És szégyenletes dolgokkal vádolja, és rossz hírbe keveri azt, mert ezt mondja: E feleséget vettem magamnak, és hozzá mentem, de nem találtam ő benne szűzességet:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'Akkor vegye azt a leánynak atyja és anyja, és vigyék a leány szűzességének jeleit a város vénei elé a kapuba;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'És mondja a leánynak atyja a véneknek: Leányomat feleségül adtam e férfiúnak, de gyűlöli őt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'És íme szégyenletes dolgokkal vádolja, mondván: Nem találtam a te leányodban szűzességet; pedig ímhol vannak az én leányom szűzességének jelei! És terítsék ki a ruhát a város vénei elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'Akkor a város vénei fogják meg azt a férfit, és ostorozzák meg őt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, 'És bírságolják meg száz ezüst siklusra, és adják ezt a leány atyjának; mert rossz hírbe kevert egy izráelita szűzet; és legyen annak felesége, és el nem bocsáthatja azt teljes életében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, 'Ha pedig igaz lesz a vádolás, és nem találtatik szűzesség a leányban:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'Akkor vigyék ki a leányt az ő atyjának háza elé, és az ő városának emberei kövezzék meg kővel, hogy meghaljon; mert gyalázatosságot cselekedett Izráelben, paráználkodván az az ő atyjának házánál. Így tisztítsd ki közüled a gonoszt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'Ha rajtakapnak valamely férfit, hogy férjes asszonynyal hál, ők mindketten is meghaljanak: a férfi, a ki az asszonynyal hált, és az asszony is. Így tisztítsd ki a gonoszt Izráelből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, 'Ha szűz leány van jegyben egy férfiúval, és megtalálja azt valaki a városban, és vele hál:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'Vigyétek ki mindkettőjöket annak a városnak kapuja elé, és kövezzétek meg őket kővel, hogy meghaljanak. A leányt azért, hogy nem kiáltott a városban, a férfit pedig azért, hogy meggyalázta az ő felebarátjának feleségét. Így tisztítsd ki a gonoszt Izráelből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'De hogyha mezőn találja a férfi a jegyben járó leányt, és erőszakoskodik rajta a férfi és vele hál: csak maga a férfi haljon meg, a ki azzal hált;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'A leányt pedig ne bántsd, mert a leánynak nincsen halálos bűne, mivel olyan ez a dolog, mint a mikor valaki felebarátjára támad és azt agyonüti.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'Mert a mezőn találta őt; kiálthatott a jegyben járó leány, de nem volt a ki megoltalmazza őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'Ha valaki el nem jegyzett szűz leánynyal találkozik, és megragadja azt, és vele hál, és rajta kapják őket:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'Akkor a férfi, a ki vele hált, adjon a leány atyjának ötven ezüst siklust, a leány pedig legyen feleségévé. Mivelhogy meggyalázta azt, nem bocsáthatja el azt teljes életében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 30, 'Ne vegye el senki az ő atyjának feleségét, és az ő atyjának takaróját fel ne takarja!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, 'Akinek szeméremteste zúzott vagy megcsonkított, ne menjen be az Úrnak községébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, 'A fattyú se menjen be az Úrnak községébe; még tizedízig se menjen be az Úrnak községébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'Az Ammoniták és Moábiták se menjenek be az Úrnak községébe; még tizedízig se menjenek be az Úrnak községébe, soha örökké:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'Azért, mert nem jöttek előtökbe kenyérrel és vízzel az úton, mikor kijöttetek Égyiptomból; és mivelhogy felbérlette ellened Bálámot, a Beór fiát, a mesopotámiabeli Péthorból valót, hogy megátkozzon téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, 'De az Úr, a te Istened nem akarta meghallgatni Bálámot; hanem fordította az Úr, a te Istened az átkot néked áldásodra, mivelhogy szeretett téged az Úr, a te Istened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'Ne keresd az ő békességöket és az ő javokat teljes életedben, soha.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'Ne útáld az Edomitát; mert atyádfia az; ne útáld az égyiptombelit, mert jövevény voltál az ő földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, 'Az olyan fiak, a kik harmadízen születnek nékik, bemehetnek az Úrnak községébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'Ha táborba szállsz a te ellenséged ellen: őrizkedjél minden gonosztól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, 'Ha volna valaki közötted, a ki nem volna tiszta valami éjszakai véletlenség miatt: menjen ki a táborból, és ne menjen vissza a táborba;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'És mikor eljő az estve, mossa meg magát vízzel, és a nap lementével menjen be a táborba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, 'A táboron kívül valami helyed is legyen, hogy kimehess oda.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'És legyen ásócskád a fegyvered mellett, hogy mikor leülsz kivül, gödröt áss azzal és ha felkelsz, betakarhassad azt, a mi elment tőled;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'Mert az Úr, a te Istened, a te táborodban jár, hogy megszabadítson téged, és elődbe vesse a te ellenségeidet: legyen azért a te táborod szent, hogy ne lásson te közted valami rútságot, és el ne forduljon tőled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'Ne add ki a szolgát az ő urának, a ki az ő urától hozzád menekült.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'Veled lakjék, te közötted, azon a helyen, a melyet választ valamelyikben a te városaid közül, a hol néki tetszik; ne nyomorgasd őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'Ne legyen felavatott paráznanő Izráel leányai közűl; se felavatott paráznaférfi ne legyen Izráel fiai közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'Ne vidd be a paráznanő bérét és az eb-bért az Úrnak, a te Istenednek házába akárminémű fogadás fejében; mert mind a kettőt útálja az Úr, a te Istened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'A te atyádfiától ne végy kamatot: se pénznek kamatját, se eleségnek kamatját, se semmi egyébnek kamatját, a mit kamatra szokás adni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'Az idegentől vehetsz kamatot, de a te atyádfiától ne végy kamatot, hogy megáldjon téged az Úr, a te Istened mindenben, a mire kinyujtod kezedet, azon a földön, a melyre bemégy, hogy bírjad azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'Ha fogadással ígérsz valamit az Úrnak, a te Istenednek: ne halogasd annak megadását; mert bizony megkeresi azt rajtad az Úr, a te Istened, és bűnül tulajdoníttatik az néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'Ha pedig nem teszesz fogadást, bűn sem tulajdoníttatik néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'Ügyelj arra, a mi ajkaidon kijön, és úgy teljesítsd, a mit száddal ígérsz, mint mikor szabad akaratból teszesz fogadást az Úrnak, a te Istenednek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'Ha bemégy a te felebarátodnak szőlőjébe, egyél szőlőt kívánságod szerint jóllakásodig, de edényedbe ne rakj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'Ha bemégy a te felebarátod vetésébe, kezeddel szaggass kalászokat, de sarlóval ne vágj be a te felebarátod vetésébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, 'Ha valaki asszonyt vesz magához, és feleségévé teszi azt, és ha azután nem találja azt kedvére valónak, mivelhogy valami illetlenséget talál benne, és ír néki váló levelet, és kezébe adja azt annak, és elküldi őt házától;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'És kimegy az ő házából, és elmegy és más férfiúé lesz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'És a második férfiú is meggyűlöli őt, és ír néki váló levelet, és kezébe adja azt, és elküldi őt házától; vagy ha meghal az a második férfi, a ki elvette azt magának feleségül;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'Az első férje, a ki elküldte őt, nem veheti őt másodszor is magához, hogy feleségévé legyen, minekutána megfertéztetett; mert útálatosság ez az Úr előtt; te pedig ne tedd bűnössé a földet, a melyet az Úr, a te Istened ád néked örökségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'Hogyha valaki újonnan vesz feleséget, ne menjen hadba, és ne vessenek reá semmiféle terhet; egy esztendeig szabad legyen az ő házában, és vidámítsa a feleségét, a kit elvett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'Zálogba senki ne vegyen kézimalmot vagy malomkövet, mert életet venne zálogba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'Hogyha rajtakapnak valakit, a ki embert lop az ő atyjafiai közül, Izráel fiai közül, és hatalmaskodik rajta, vagy eladja azt: haljon meg az a tolvaj. Így tisztítsd ki a gonoszt te közüled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'A poklosság csapásában vigyázz, hogy szorgalmatosan megtartsad és megcselekedjed mindazt, a mire a Lévita-papok tanítanak titeket; vigyázzatok, hogy a miképen megparancsoltam nékik, a képen cselekedjetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'Emlékezzél meg arról, a mit cselekedett az Úr, a te Istened Miriámmal az úton, mikor kijöttetek Égyiptomból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'Ha kölcsön adsz valamit a te felebarátodnak: ne menj be az ő házába, hogy magad végy zálogot tőle;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'Kivül állj meg, és az ember, a kinek kölcsönt adsz, maga vigye ki hozzád az ő zálogát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'Hogyha szegény ember az, ne feküdjél le az ő zálogával;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'Bizony add vissza néki azt a zálogot napnyugtakor, hogy az ő ruhájában feküdjék le, és áldjon téged. És igazságul lesz ez néked az Úr előtt, a te Istened előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'A szegény és szűkölködő napszámoson ne erőszakoskodjál, akár atyádfiai, akár a te jövevényeid azok, a kik a te földeden a te kapuid között vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'Azon a napon add meg az ő bérét, és le se menjen felette a nap; mert szegény ő, és kivánkozik az után az ő lelke, hogy ellened ne kiáltson az Úrhoz, és bűn ne legyen rajtad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'Meg ne ölettessenek az atyák a fiakért, se a fiak meg ne ölettessenek az atyákért; kiki az ő bűnéért haljon meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'A jövevénynek és az árvának igazságát el ne csavard; és az özvegynek ruháját ne vedd zálogba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'Hanem emlékezzél vissza, hogy szolga voltál Égyiptomban, és megváltott téged az Úr, a te Istened, onnét. Azért parancsolom én néked, hogy így cselekedjél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'Mikor learatod aratni valódat a te meződön, és kévét felejtesz a mezőn, ne térj vissza annak felvételére; a jövevényé, az árváé és az özvegyé legyen az, hogy megáldjon téged az Úr, a te Istened, kezeidnek minden munkájában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'Ha olajfád termését lerázod, ne szedd le, a mi még utánad marad; a jövevényé, árváé és az özvegyé legyen az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'Ha szőlődet megszeded, ne mezgeréld le, a mi utánad marad; a jövevényé, árváé és az özvegyé legyen az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'És emlékezzél vissza, hogy szolga voltál Égyiptomnak földén. Azért parancsolom néked, hogy így cselekedjél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, 'Ha per támad férfiak között, és törvény elé mennek, és megítélik őket, és igazat adnak az igaznak és bűnösnek mondják a bűnöst:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'Akkor, ha a bűnös ütleget érdemel, vonassa le azt a bíró, és üttessen arra maga előtt annak bűnössége szerint való számban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'Negyvenet üttessen rá, ne többet, hogy netalán, ha ennél több ütést üttet reá, alávalóvá legyen előtted a te atyádfia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'Ne kösd be az ökörnek száját, mikor nyomtat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, 'Ha testvérek laknak együtt, és meghal egy közülök, és nincs annak fia: a megholtnak felesége ne menjen ki a háztól idegen férfiúhoz; hanem a sógora menjen be hozzá, és vegye el őt magának feleségül, és éljen vele sógorsági házasságban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'És majd az elsőszülött, a kit szülni fog, a megholt testvér nevét kapja, hogy annak neve ki ne töröltessék Izráelből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'Hogyha a férfinak nincs kedve elvenni az ő ángyát, menjen el az ő ángya a kapuba a vénekhez, és mondja: Sógorom vonakodik fentartani az ő testvérének nevét Izráelben, nem akar velem sógorsági házasságban élni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'Akkor hívják azt az ő városának vénei, és beszéljenek vele; és ha megáll és ezt mondja: nincs kedvem őt elvenni:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'Akkor járuljon hozzá az ő ángya a vének szemei előtt, és húzza le saruját annak lábáról, és köpjön az arczába, és szóljon, és ezt mondja: Így kell cselekedni azzal a férfival, a ki nem építi az ő testvérének házát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'És „lehúzott sarujú háznép”-nek nevezzék az ő nevét Izráelben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, 'Ha két férfi összevesz egymással, és az egyiknek felesége oda járul, hogy megszabadítsa az ő férjét annak kezéből, a ki veri azt, és kinyujtja kezét, és megfogja annak szeméremtestét:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'Vágd el annak kezét, meg ne szánja szemed.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'Ne legyen a te zsákodban kétféle font: nagyobb és kisebb.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'Ne legyen a te házadban kétféle éfa: nagyobb és kisebb.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'Teljes és igaz fontod legyen néked; teljes és igaz éfád legyen néked; hogy hosszú ideig élj azon a földön, a melyet az Úr, a te Istened ád néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'Mert az Úr előtt, a te Istened előtt útálni való mindaz, a ki ezeket cselekszi; és mindaz, a ki hamisságot mível.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, 'Megemlékezzél arról, a mit Amálek cselekedett rajtad az úton, a mikor Égyiptomból kijöttetek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'Hogy reád támadt az úton, és megverte a seregnek utolsó részét, mind az erőtleneket, a kik hátul valának, a mikor magad is fáradt és lankadt voltál, és nem félte az Istent.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'Mikor azért megnyugtat majd téged az Úr, a te Istened, minden te köröskörül lévő ellenségedtől azon a földön, a melyet az Úr, a te Istened ád néked örökségül, hogy bírjad azt: töröld el Amálek emlékezetét az ég alól; el ne felejtsd!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, 'Mikor pedig bemégy arra a földre, a melyet az Úr, a te Istened ád néked örökségül, és bírni fogod azt, és lakozol abban:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'Akkor végy a föld minden gyümölcsének zsengéjéből, a melyet szerezz a te földedből, a melyet az Úr, a te Istened ád néked; és tedd kosárba és menj oda a helyre, a melyet kiválaszt az Úr, a te Istened, hogy ott lakozzék az ő neve;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'És menj be a paphoz, a ki abban az időben lesz, és mondjad néki: Vallást teszek ma az Úr előtt, a te Istened előtt, hogy bejöttem a földre, a mely felől megesküdt az Úr a mi atyáinknak, hogy nékünk adja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'És a pap vegye el a kosarat kezedből, és tegye azt az Úrnak, a te Istenednek oltára elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'És szólj, és mondjad az Úr előtt, a te Istened előtt: Veszendő mesopotámiai vala az atyám, és aláment vala Égyiptomba, és jövevény volt ott kevesed magával; nagy, erős és temérdek néppé lőn ottan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'Bosszúsággal illetének pedig minket az Égyiptombeliek, és nyomorgatának minket, és vetének reánk kemény szolgálatot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'Kiáltánk azért az Úrhoz, a mi atyáink Istenéhez, és meghallgatta az Úr a mi szónkat, és megtekintette a mi nyomorúságunkat, kínunkat és szorongattatásunkat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'És kihozott minket az Úr Égyiptomból erős kézzel, kinyújtott karral, nagy rettentéssel, jelekkel és csudákkal;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'És behozott minket e helyre, és adta nékünk ezt a földet, a tejjel és mézzel folyó földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'Most azért ímé elhoztam ama föld gyümölcsének zsengéjét, a melyet nékem adtál Uram. És rakd le azt az Úr előtt, a te Istened előtt, és imádkozzál az Úr előtt, a te Istened előtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'És örömet találj mindabban a jóban, a melyet ád néked az Úr, a te Istened, és a te házadnépének; te és a lévita, és a jövevény, a ki te közötted van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, 'Ha a harmadik esztendőben, a tizednek esztendejében, minden termésedből egészen megadod a tizedet, és adod a lévitának, a jövevénynek, az árvának és özvegynek, hogy egyenek a te kapuid között, és jól lakjanak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'Akkor ezt mondjad az Úr előtt, a te Istened előtt: Kitakarítottam a szent részt a házból, és oda adtam azt a lévitának, a jövevénynek, az árvának és az özvegynek minden te parancsolatod szerint, a melyet parancsoltál nékem; nem hágtam át egyet sem a te parancsolataidból, sem el nem felejtettem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'Nem ettem belőle gyászomban, nem pusztítottam belőle tisztátalanul, és halottra sem adtam belőle. Hallgattam az Úrnak, az én Istenemnek szavára; a szerint cselekedtem, a mint parancsoltad nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'Tekints alá a te szentségednek lakóhelyéből a mennyekből, és áldd meg Izráelt, a te népedet, és a földet, a melyet nékünk adtál, a mint megesküdtél vala a mi atyáinknak, a tejjel és mézzel folyó földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, 'E mai napon az Úr, a te Istened parancsolja néked, hogy e rendelések és végzések szerint cselekedjél: tartsd meg azért és cselekedjed azokat teljes szívedből és teljes lelkedből!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'Azt kívántad ma kimondatni az Úrral, hogy Isteneddé lesz néked, hogy járhass az ő útain, megtudhassad az ő rendeléseit, parancsolatait és végzéseit, és engedhess az ő szavának;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'Az Úr pedig azt kívánja ma kimondatni veled, hogy az ő tulajdon népévé leszesz, a miképen szólott néked, és minden ő parancsolatát megtartod,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'Hogy feljebb valóvá tegyen téged minden nemzetnél, a melyeket teremtett, dícséretben, névben és dicsőségben, és hogy szent népévé lehess az Úrnak, a te Istenednek, a mint megmondta vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'Mózes pedig és Izráel vénei parancsot adának a népnek, mondván: Tartsátok meg mind e parancsolatot, a melyet én parancsolok ma néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'És a mely napon általmentek a Jordánon arra a földre, a melyet az Úr, a te Istened ád néktek: nagy köveket állíts fel, és meszeld be azokat mészszel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'És mihelyt általmégy, írd fel azokra e törvénynek minden ígéjét, hogy bemehess arra a földre, a melyet az Úr, a te Istened ád néked, a tejjel és mézzel folyó földre, a miképen megígérte néked az Úr, a te atyáidnak Istene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'Mihelyt azért általmentek a Jordánon, állítsátok fel azokat a köveket, a melyeket én e mai napon parancsolok néktek, az Ebál hegyén; és meszeld be azokat mészszel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'És építs ott oltárt az Úrnak, a te Istenednek; olyan kövekből való oltárt, a melyeket vassal meg ne faragj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'Ép kövekből építsd az Úrnak, a te Istenednek oltárát; és áldozzál azon egészen égőáldozatokat az Úrnak, a te Istenednek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'Áldozzál hálaáldozatokat is, és egyél ott, és vigadozzál az Úr előtt, a te Istened előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'És írd fel a kövekre e törvénynek minden ígéjét igen világosan!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'És szóla Mózes és a Lévi nemzetségéből való papok az egész Izráelnek, mondván: Figyelj és hallgass Izráel! E mai napon lettél az Úrnak, a te Istenednek népévé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'Hallgass azért az Úrnak, a te Istenednek szavára, és cselekedjél az ő parancsolatai és rendelései szerint, a melyeket, én parancsolok ma néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'És parancsola Mózes azon a napon a népnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, 'Ezek álljanak fel a népnek megáldására a Garizim hegyén, mikor általmentek a Jordánon: Simeon, Lévi, Júda, Izsakhár, József és Benjámin.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'Ezek pedig az átkozásra álljanak fel az Ebál hegyén: Rúben, Gád, Áser, Zebulon, Dán és Nafthali.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'Szóljanak pedig a léviták, és ezt mondják az egész Izráel népének felszóval:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, 'Átkozott az ember, a ki faragott és öntött képet csinál, útálatára az Úrnak, mesterember kezének munkáját, és rejtve tartja azt! És feleljen az egész nép és mondja: Ámen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, 'Átkozott a ki kevésre becsüli az ő atyját vagy anyját! És mondja az egész nép: Ámen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, 'Átkozott, a ki elmozdítja az ő felebarátjának határát! És mondja az egész nép: Ámen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, 'Átkozott, a ki félrevezeti a vakot az úton! És mondja az egész nép: Ámen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, 'Átkozott, a ki elfordítja a jövevénynek, árvának és özvegynek igazságát! És mondja az egész nép: Ámen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, 'Átkozott, a ki az ő atyjának feleségével hál, mert feltakarja az ő atyjának takaróját! És mondja az egész nép: Ámen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, 'Átkozott, a ki közösül valamely barommal! És mondja az egész nép: Ámen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, 'Átkozott, a ki az ő leánytestvérével hál, az ő atyjának leányával vagy az ő anyjának leányával! És mondja az egész nép: Ámen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, 'Átkozott, a ki az ő napával hál! És mondja az egész nép: Ámen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, 'Átkozott, a ki megöli az ő felebarátját titkon! És mondja az egész nép: Ámen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, 'Átkozott, a ki ajándékot fogad el, hogy ártatlan lélek vérét ontsa! És mondja az egész nép: Ámen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, 'Átkozott, a ki meg nem tartja e törvénynek ígéit, hogy cselekedje azokat! És mondja az egész nép: Ámen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, 'Ha pedig szorgalmatosan hallgatsz az Úrnak, a te Istenednek szavára, és megtartod és teljesíted minden ő parancsolatát, a melyeket én parancsolok ma néked: akkor e földnek minden népénél feljebbvalóvá tesz téged az Úr, a te Istened;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, 'És reád szállanak mind ez áldások, és megteljesednek rajtad, ha hallgatsz az Úrnak, a te Istenednek szavára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'Áldott leszesz a városban, és áldott leszesz a mezőben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'Áldott lesz a te méhednek gyümölcse és a te földednek gyümölcse, és a te barmodnak gyümölcse, a te teheneidnek fajzása és a te juhaidnak ellése.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'Áldott lesz a te kosarad és a te sütő tekenőd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'Áldott leszesz bejöttödben, és áldott leszesz kimentedben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'Az Úr megszalasztja előtted a te ellenségeidet, a kik reád támadnak; egy úton jőnek ki reád, és hét úton futnak előled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'Áldást parancsol melléd az Úr a te csűreidben és mindenben, a mire ráteszed kezedet; és megáld téged azon a földön, a melyet az Úr, a te Istened ád néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'Az Úr felkészít téged magának szent néppé, a miképen megesküdt néked, ha megtartod az Úrnak, a te Istenednek parancsolatait, és az ő útain jársz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'És megérti majd a földnek minden népe, hogy az Úrnak nevéről neveztetel, és félnek tőled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'És bővölködővé tesz téged az Úr minden jóban: a te méhednek gyümölcsében, a te barmodnak gyümölcsében és a te földednek gyümölcsében, azon a földön, a mely felől megesküdt az Úr a te atyáidnak, hogy néked adja azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'Megnyitja néked az Úr az ő drága kincsesházát, az eget, hogy esőt adjon a te földednek alkalmas időben, és megáldja kezednek minden munkáját, és kölcsönt adsz sok népnek, te pedig nem veszesz kölcsönt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'És fejjé tesz téged az Úr és nem farkká, és mindinkább feljebbvaló leszesz és nem alábbvaló, ha hallgatsz az Úrnak, a te Istenednek parancsolataira, a melyeket én parancsolok ma néked, hogy tartsd meg és teljesítsd azokat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'És ha el nem térsz egyetlen ígétől sem, a melyeket én parancsolok néktek, se jobbra, se balra, járván idegen istenek után, hogy azokat tiszteljétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, 'Ha pedig nem hallgatsz az Úrnak, a te Istenednek szavára, hogy megtartsad és teljesítsed minden parancsolatát és rendelését, a melyeket én parancsolok ma néked: reád jőnek mind ez átkok, és megteljesednek rajtad:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'Átkozott leszesz a városban, és átkozott a mezőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'Átkozott lesz a te kosarad és a te sütő tekenőd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'Átkozott lesz a te méhednek gyümölcse és a te földednek gyümölcse, a te teheneidnek fajzása és a te juhaidnak ellése.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'Átkozott leszesz bejöttödben, és átkozott leszesz kimentedben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'Bocsát az Úr te reád átkot, bomlást és romlást mindenben, a mit kezdesz vagy cselekszel; mígnem eltöröltetel és mígnem gyorsasággal elveszesz a te cselekedeteidnek gonoszsága miatt, a melyekkel elhagytál engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'Hozzád ragasztja az Úr a döghalált, mígnem elemészt téged arról a földről, a melyre bemégy, hogy bírjad azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'Megver téged az Úr szárazbetegséggel hidegleléssel, gyulasztó és izzasztó betegséggel, aszálylyal, szárazsággal és ragyával; és üldöznek téged, mígnem elveszesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'Eged, a mely fejed felett van, rézzé, a föld pedig, a mely lábad alatt van, vassá válik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'Az Úr eső helyett port és hamut ád a te földedre; az égből száll reád, mígnem elpusztulsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'Az Úr megszalaszt téged a te ellenségeid előtt; egy úton mégy ki ő reá, és hét úton futsz előtte, és a föld minden országának rettentésére leszel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'És eledelévé lesz a te holttested az ég minden madarának és a föld vadainak, és nem lesz, a ki elűzze azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'Megver téged az Isten Égyiptomnak fekélyével, és sülylyel, varral és viszketegséggel, a melyekből ki nem gyógyíttathatol.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'Megver téged az Úr tébolyodással, vaksággal és elme-zavarodással;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'És tapogatni fogsz délben, a mint tapogat a vak a setétségben; és szerencsétlen leszel a te útaidban, sőt elnyomott és kifosztott leszel minden időben, és nem lesz, a ki megszabadítson.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'Feleséget jegyzesz magadnak, de más férfi hál azzal; házat építesz, de nem lakol benne; szőlőt ültetsz, de nem veszed annak hasznát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'A te ökröd szemed előtt vágatik le, és nem eszel abból; a te szamarad elragadtatik előled, és nem tér vissza hozzád; a te juhaid ellenségeidnek adatnak, és nem lesz, a ki megszabadítson.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'A te fiaid és leányaid más népnek adatnak, és a te szemeid néznek és epekednek utánok egész napon, és nem lesz erő a te kezedben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'A te földednek gyümölcsét, és minden fáradságos szerzeményedet oly nép emészti fel, a melyet nem ismertél, sőt elnyomott és megnyomorított leszel minden időben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'És megtébolyodol a látványtól, a melyet látni fognak a te szemeid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'Megver téged az Úr gonosz kelésekkel a te térdeiden és czombjaidon, a melyekből ki nem gyógyíttathatol, talpadtól fogva a koponyádig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'Az Úr elvisz téged és a te királyodat, a kit magad fölé emelsz, oly nép közé, a melyet nem ismertél sem te, sem a te atyáid; és szolgálni fogsz ott idegen isteneket: fát és követ.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'És iszonyattá, példabeszéddé és gúnynyá leszel minden népnél, a melyek közé elűz téged az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'Sok magot viszel ki a mezőre, de keveset takarsz be, mert felemészti azt a sáska.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'Szőlőket ültetsz és míveled azokat, de bort nem iszol, meg sem szeded, mert elemészti azokat a féreg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'Olajfáid lesznek minden határodban, de nem kened magadat olajjal, mert olajfádnak gyümölcse lehull.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'Fiakat és leányokat nemzesz, de nem lesznek tiéid; mert fogságra jutnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'Minden fádat és földednek minden gyümölcsét megemészti a sáska.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'A jövevény, a ki közötted van, feljebb-feljebb emelkedik feletted, te pedig alább-alább szállasz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'Ő fog néked kölcsönt adni, és nem te kölcsönzöl néki; ő fej lesz, te pedig fark leszel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'És ez átkok mind reád szállanak, és üldöznek téged és megteljesednek rajtad, míglen elpusztulsz; mert nem hallgattál az Úrnak, a te Istenednek szavára, hogy megtartottad volna az ő parancsolatait és rendeléseit, a melyeket parancsolt néked;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'És rajtad lesznek jelül és csudául, és a te magodon mind örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'A miatt, hogy nem szolgáltad az Urat, a te Istenedet örömmel és jó szívvel, mindennel bővölködvén:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'Szolgálod majd a te ellenségeidet, a kiket reád bocsát az Úr, éhen és szomjan, mezítelen és mindennek szűkiben; és vasigát vet a te nyakadra, míglen elpusztít téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'Hoz az Úr ellened népet meszszünnen, a földnek széléről, nem különben, a mint repül a sas; oly népet, a melynek nyelvét nem érted;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'Vad tekintetű népet, a mely nem tiszteli a vén embert, és a gyermeknek nem kedvez:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'És felemészti a te barmodnak tenyészését és a te földednek gyümölcsét, mígnem kipusztulsz; a mely nem hágy néked a te gabonádból, borodból, olajodból, és a te teheneidnek fajzásából, juhaidnak elléséből, mígnem kiveszít téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'És megszáll téged minden városodban, míglen leomolnak a te magas és erős kőfalaid, a melyekben bízol, minden te földeden: megszáll téged minden városodban, minden te földeden, a melyet az Úr, a te Istened ád néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'És megeszed a te méhednek gyümölcsét, a te fiaidnak és leányidnak húsát, a kiket ád néked az Úr, a te Istened – a megszállás és szorongattatás alatt, a melylyel megszorongat téged a te ellenséged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'A te közötted való finnyás és igen kedvére nevekedett férfi is irígy szemmel tekint az ő atyjafiára, az ő szeretett feleségére és fiainak maradékrészére, a kik megmaradtak még.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'Hogy ne kelljen adnia azok közül senkinek az ő fiainak húsából, a mit eszik, mivelhogy semmi egyebe nem marad a megszállás és szorongattatás alatt, a melylyel megszorongat téged a te ellenséged minden városodban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'A közötted való finnyás és kedvére nevekedett asszony (a ki meg se próbálta talpát a földre bocsátani az elkényesedés és finnyásság miatt) irígy szemmel tekint az ő szeretett férjére, fiára, leányára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'Az ő mássa miatt, a mely elmegy tőle és gyermekei miatt, a kiket megszül; mert megeszi ezeket titkon, mikor mindenből kifogy, a megszállás és szorongattatás alatt, a melylyel megszorongat téged a te ellenséged a te városaidban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'Hogyha meg nem tartod és nem teljesíted e törvény minden ígéjét, a melyek meg vannak írva e könyvben, hogy féljed e dicsőséges és rettenetes nevet, az Úrét, a te Istenedét:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'Csudálatosakká teszi az Úr a te csapásaidat, és a te magodnak csapásait: nagy és maradandó csapásokká, gonosz és maradandó betegségekké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'És reád fordítja Égyiptomnak minden nyavalyáját, a melyektől irtóztál vala, és hozzád ragadnak azok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'Mindazt a betegséget és mindazt a csapást is, a melyek nincsenek megírva e törvénynek könyvében, reád rakja az Úr, míglen kipusztulsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'És kevesen maradtok meg, a kik annak előtte oly sokan voltatok, mint az égnek csillagai; mivelhogy nem hallgattál az Úrnak, a te Istenednek szavára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'És a miképen örvendezett az Úr rajtatok, hogy jót tett veletek és megsokasított titeket: akképen fog örvendezni az Úr rajtatok, hogy kiveszt és kipusztít titeket; és ki fogtok gyomláltatni arról a földről, a melyre te bemégy, hogy bírjad azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'És szétszór téged az Úr minden nép közé, a földnek egyik végétől a földnek másik végéig; és szolgálni fogsz ott idegen isteneket, a kiket sem te nem ismertél, sem a te atyáid: fát és követ.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'De e nemzetek között sem pihensz meg, és nem lesz a te talpadnak nyugodalma; mert rettegő szívet, epedő szemeket és sóvárgó lelket ád ott néked az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'És a te életed kétséges lesz majd előtted: és rettegni fogsz éjjel és nappal, és nem bízol életedben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'Reggel azt mondod: Bárcsak estve volna! estve pedig azt mondod: Bárcsak reggel volna! – a te szívednek rettegései miatt, a melylyel rettegsz, és a te szemeidnek látása miatt, a melyet látsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'És visszavisz téged az Úr Égyiptomba hajókon, azon az úton, a melyről azt mondtam néked, hogy nem fogod azt többé meglátni! És áruljátok ott magatokat a ti ellenségeiteknek szolgákul és szolgálóleányokul, de nem lesz, a ki megvegyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, 'Ezek annak a szövetségnek ígéi, a mely felől megparancsolta az Úr Mózesnek, hogy kösse meg azt Izráel fiaival Moábnak földén, azon a szövetségen kivül, a melyet kötött vala velök a Hóreben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, 'És előhivatá Mózes az egész Izráelt, és monda nékik: Ti láttátok mind azt, a mit szemeitek előtt cselekedett az Úr Égyiptom földén a Faraóval és minden ő szolgájával, és egész földével:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'A nagy kísértéseket, a melyeket láttak a te szemeid, a jeleket és ama nagy csudákat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'De nem adott az Úr néktek szívet, hogy jól értsetek, szemeket, hogy lássatok, és füleket, hogy halljatok, mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, 'Mindamellett is vezérlettelek titeket a pusztában negyven esztendeig; nem koptak le a ti ruháitok rólatok, és a te sarud sem kopott le lábadról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'Kenyeret nem ettetek, sem bort, sem részegítő italt nem ittatok, hogy megtudjátok, hogy én vagyok az Úr, a ti Istenetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'És eljutottatok e helyre, és kijöve előnkbe Szíhon, Hesbonnak királya, és Óg, Básánnak királya, hogy megütközzenek velünk, de megvertük őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'És elvettük az ő földjöket, és odaadtuk örökségül a Rubenitáknak, Gáditáknak és a Manassé-törzs felének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, 'Tartsátok meg azért e szövetségnek ígéit, és a szerint cselekedjetek, hogy szerencsések legyetek mindenben, a mit cselekesztek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'Ti e napon mindnyájan az Úr előtt, a ti Istenetek előtt álltok: a ti főembereitek, törzseitek, véneitek és a ti tiszttartóitok, Izráelnek minden férfia;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'A ti kicsinyeitek, feleségeitek és a te jövevényed, a ki a te táborodban van, sőt favágóid és vízmerítőid is;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'Hogy szövetségre lépjetek az Úrral, a ti Istenetekkel, és pedig az ő esküjével erősített kötésre, a melyet ma köt meg veled az Úr, a te Istened;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'Hogy az ő népévé emeljen ma téged, ő pedig legyen néked Istened, a miképen szólott néked, és a miképen megesküdt a te atyáidnak, Ábrahámnak, Izsáknak és Jákóbnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'És nem csak ti veletek kötöm én e szövetséges, és ez esküvéses kötést,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, 'Hanem azzal, a ki itt van velünk, és itt áll e mai napon az Úr előtt, a mi Istenünk előtt, és azzal is, a ki nincsen e mai napon itt velünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, '(Mert ti tudjátok miképen laktunk Égyiptomnak földén, és miképen jöttünk által a nemzetek között, a kiken általjöttetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'És láttátok az ő undokságaikat és bálványaikat: fát és követ, ezüstöt és aranyat, a melyek nálok vannak.)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'Vajha ne lenne közöttetek férfi vagy asszony, nemzetség vagy törzs, a kinek szíve elforduljon e napon az Úrtól, a mi Istenünktől, hogy elmenjen és szolgáljon e nemzetek isteneinek; vajha ne lenne köztetek méreg- és ürömtermő gyökér!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'És ha lesz, a ki hallja ez esküvéses kötésnek ígéit, és boldognak állítja magát az ő szívében, ezt mondván: Békességem lesz nékem, ha a szívem gondolata szerint járok is, (hogy a részeg és a szomjas együtt veszszenek):');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'Nem akar majd az Úr annak megbocsátani, sőt felgerjed akkor az Úrnak haragja és búsulása az ilyen ember ellen, és rászáll arra minden átok, a mely meg van írva e könyvben, és eltörli az Úr annak nevét az ég alól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'És kiválasztja azt az Úr veszedelemre, Izráelnek minden törzse közül, a szövetségnek minden átka szerint, a melyek meg vannak írva e törvénykönyvben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, 'És ezt fogja mondani a következő nemzedék, a ti fiaitok, a kik ti utánatok támadnak, és az idegen, a ki messze földről jön el, ha látni fogják e földnek csapásait és nyomorúságait, a melyekkel megnyomorította azt az Úr:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, 'Kénkő és só égette ki egész földjét, be sem vethető, semmit nem terem, és semmi fű sem nevekedik rajta; olyan, mint Sodomának, Gomorának, Ádmának és Czeboimnak elsülyesztett helye, a melyeket elsülyesztett az Úr haragjában és búsulásában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'Azt fogják majd kérdezni mind a nemzetek: Miért cselekedett az Úr így ezzel a földdel? Micsoda nagy felgerjedése ez a haragnak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'És ezt mondják majd: Azért, mert elhagyták az Úrnak, az ő atyáik Istenének szövetségét, a melyet akkor kötött velök, a mikor kihozta őket Égyiptom földéről;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'És elmentek, és szolgáltak idegen isteneket, és imádták azokat; olyan isteneket, a kiket nem ismertek volt és nem adott nékik az Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'És felgerjedett az Úrnak haragja e föld ellen, hogy reá hozza mindazt az átkot, a mely meg van írva e könyvben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'És kigyomlálta őket az Úr az ő földjökről haragjában, búsulásában és nagy indulatjában; és vetette őket más földre, a mint mai nap is van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 29, 'A titkok az Úréi, a mi Istenünkéi; a kinyilatkoztatott dolgok pedig a miénk és a mi fiainké mind örökké, hogy e törvénynek minden ígéjét beteljesítsük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, 'És ha majd elkövetkeznek reád mind ezek: az áldás és az átok, a melyet elődbe adtam néked; és szívedre veszed azt ama nemzetek között, a kik közé oda taszított téged az Úr, a te Istened;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'És megtérsz az Úrhoz, a te Istenedhez, és hallgatsz az ő szavára mind a szerint, a mint én parancsolom néked e napon, te és a te fiaid teljes szívedből és teljes lelkedből:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'Akkor visszahozza az Úr, a te Istened a te foglyaidat, és könyörül rajtad, és visszahozván, összegyűjt majd téged minden nép közül, a kik közé oda szórt téged az Úr, a te Istened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'Ha az ég szélére volnál is taszítva, onnét is összegyűjt téged az Úr, a te Istened, és onnét is felvesz téged;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'És elhoz téged az Úr, a te Istened a földre, a melyet bírtak a te atyáid, és bírni fogod azt; és jól tesz veled, és inkább megsokasít téged, mint a te atyáidat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'És körülmetéli az Úr, a te Istened a te szívedet, és a te magodnak szívét, hogy szeressed az Urat, a te Istenedet teljes szívedből és teljes lelkedből, hogy élj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'Mind ez átkokat pedig rábocsátja az Úr, a te Istened a te ellenségeidre és gyűlölőidre, a kik üldöztek téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'Te azért térj meg, és hallgass az Úr szavára, és teljesítsd minden parancsolatát, a melyeket én e mai napon parancsolok néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'És bővölködővé tesz téged az Úr, a te Istened kezeidnek minden munkájában, a te méhednek gyümölcsében, a te barmodnak gyümölcsében és a te földednek gyümölcsében, a te jódra. Mert hozzád fordul az Úr és öröme lesz benned a te jódra, a miképen öröme volt a te atyáidban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'Hogyha hallgatsz az Úrnak, a te Istenednek szavára, megtartván az ő parancsolatait és rendeléseit, a melyek meg vannak írva e törvénykönyvben, és ha teljes szívedből és teljes lelkedből megtérsz az Úrhoz, a te Istenedhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, 'Mert e parancsolat, a melyet én e mai napon parancsolok néked, nem megfoghatatlan előtted; sem távol nincs tőled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'Nem a mennyben van, hogy azt mondanád: Kicsoda hág fel érettünk a mennybe, hogy elhozza azt nékünk, és hallassa azt velünk, hogy teljesítsük azt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'Sem a tengeren túl nincsen az, hogy azt mondanád: Kicsoda megy át érettünk a tengeren, hogy elhozza azt nékünk és hallassa azt velünk, hogy teljesítsük azt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'Sőt felette közel van hozzád ez íge: a te szádban és szívedben van, hogy teljesítsed azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, 'Lám elődbe adtam ma néked az életet és a jót: a halált és a gonoszt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 'Mikor én azt parancsolom néked ma, hogy szeressed az Urat, a te Istenedet, hogy járj az ő útain, és tartsd meg az ő parancsolatait, rendeléseit és végzéseit, hogy élj és szaporodjál, és megáldjon téged az Úr, a te Istened a földön, a melyre bemégy, hogy bírjad azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'Ha pedig elfordul a te szíved, és nem hallgatsz meg, sőt elhajolsz és idegen isteneket imádsz, és azoknak szolgálsz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'Tudtotokra adom ma néktek, hogy bizony elvesztek: nem éltek sok ideig azon a földön, a melyre a Jordánon általkelvén, bemégy, hogy bírjad azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'Bizonyságul hívom ellenetek ma a mennyet és a földet, hogy az életet és a halált adtam előtökbe, az áldást és az átkot: válaszd azért az életet, hogy élhess mind te, mind a te magod;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, 'Hogy szeressed az Urat, a te Istenedet, és hogy hallgass az ő szavára, és ragaszkodjál hozzá; mert ő a te életed és a te életednek hosszúsága; hogy lakozzál azon a földön, a mely felől megesküdt az Úr a te atyáidnak, Ábrahámnak, Izsáknak és Jákóbnak, hogy nékik adja azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'És méne Mózes, és ez ígéket mondotta vala az egész Izráelnek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, 'Monda pedig nékik: Száz és húsz esztendős vagyok ma, nem járhatok többé ki és be: az Úr pedig azt mondá nékem: Nem mégy át ezen a Jordánon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'Az Úr, a te Istened maga megy át előtted, ő pusztítja el e nemzeteket előtted, hogy bírjad őket; Józsué az, a ki átmegy előtted, a mint megmondotta az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'És akképen cselekeszik azokkal az Úr, a miképen cselekedett Szíhonnal és Óggal az Emoreusok királyaival, és azoknak földjökkel, a melyeket elpusztított vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'Ha azért előtökbe adja őket az Úr, egészen a szerint a parancsolat szerint cselekedjetek velök, a mint parancsoltam néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'Legyetek erősek és bátrak, ne féljetek és ne rettegjetek tőlök, mert az Úr, a te Istened maga megy veled; nem marad el tőled, sem el nem hágy téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'Szólítá azért Mózes Józsuét, és monda néki az egész Izráel szemei előtt: Légy erős és bátor, mert te mégy be e néppel a földre, a mely felől megesküdt az Úr az ő atyáiknak, hogy nékik adja, és te osztod el azt nékik örökségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'Az Úr, ő az, a ki előtted megy, ő lesz te veled; el nem marad tőled, sem el nem hágy téged: ne félj és ne rettegj!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'És megírá Mózes e törvényt, és adá azt a papoknak, a Lévi fiainak, a kik hordozzák az Úr szövetségének ládáját, és Izráel minden vénjének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'És megparancsolá nékik Mózes, mondván: A hetedik esztendő végén, az elengedés esztendejének idejében, a sátorok innepén;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'Mikor eljön az egész Izráel, hogy megjelenjék az Úr előtt, a te Istened előtt azon a helyen, a melyet kiválaszt: olvasd fel e törvényt az egész Izráel előtt fülök hallására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'Gyűjtsd egybe a népet, a férfiakat, az asszonyokat, a kicsinyeket és a te jövevényedet, a ki a te kapuidon belől van, hogy hallják és tanuljanak, és féljék az Urat, a ti Isteneteket, és tartsák meg és teljesítsék e törvénynek minden ígéjét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'És az ő fiaik is, a kik nem tudják még, hallják és tanulják meg, hogy az Urat, a ti Isteneteket kell félni mind addig, a míg éltek azon a földön, a melyre általkeltek a Jordánon, hogy bírjátok azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'Monda azután az Úr Mózesnek: Ímé elközelgettek a te napjaid, hogy meghalj; hívd elő Józsuét, és álljatok fel a gyülekezetnek sátorában, hogy parancsolatokat adjak néki. Elméne azért Mózes és Józsué, és felállának a gyülekezet sátorában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'És megjelenék az Úr a sátorban, felhőoszlopban, és megálla a felhőoszlop a sátor nyílása felett,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'És monda az Úr Mózesnek: Ímé te elaluszol a te atyáiddal, és ez a nép felkél, és idegen istenek után jár és paráználkodik azon a földön, a melyre bemegy, hogy lakozzék azon; és elhágy engem, és felbontja az én szövetségemet, a melyet én ő vele kötöttem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'De felgerjed az én haragom ő ellene azon a napon, és elhagyom őt, és elrejtem az én orczámat ő előle, hogy megemésztessék. És mikor utóléri a sok baj és nyomorúság, mondani fogja azon a napon: Avagy nem azért értek-é engem ezek a bajok, hogy nincsen az én Istenem én közöttem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'Én pedig valóban elrejtem az én orczámat azon a napon az ő minden gonoszsága miatt, a melyet cselekedett, mivelhogy más istenekhez fordult.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, 'Most pedig írjátok fel magatoknak ez éneket, és tanítsd meg arra Izráel fiait; adjad azt szájokba, hogy legyen nékem ez ének bizonyságul Izráel fiai ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'Mert beviszem őt arra a földre, a mely felől megesküdtem az ő atyáinak, a tejjel és mézzel folyó földre; és eszik, jóllakik és meghízik, azután pedig más istenekhez fordul, és azoknak szolgál, és meggyaláz engem, és felbontja az én szövetségemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'Mikor pedig utóléri őt a sok baj és nyomorúság: akkor szóljon ez az ének előtte bizonyságképen (mert nem megy feledésbe az ő maradékának szájából), mert tudom az ő gondolatát, a mely szerint cselekszik már most is, minekelőtte bevinném őt arra a földre, a mely felől megesküdtem vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'Megírá azért Mózes ezt az éneket azon a napon, és megtanítá arra Izráel fiait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'Azután parancsola az Úr Józsuénak, a Nún fiának, és monda: Légy erős és bátor, mert te viszed be Izráel fiait arra a földre, a mely felől megesküdtem nékik; és én veled leszek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'Mikor pedig teljesen és mind végig beírta Mózes e törvény ígéit könyvbe:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'Parancsola Mózes a lévitáknak, a kik hordozzák vala az Úr szövetségének ládáját, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, 'Vegyétek e törvénykönyvet, és tegyétek ezt az Úrnak, a ti Isteneteknek szövetségládája oldalához, és legyen ott ellened bizonyságul;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'Mert én ismerem a te pártos voltodat, és kemény nyakadat. Ímé most is, holott még köztetek élek, pártot ütöttetek az Úr ellen; mennyivel inkább halálom után?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'Gyűjtsétek én hozzám a ti törzseiteknek minden vénjét és a ti előljáróitokat, hadd mondjam el ez ígéket az ő füleik hallására, és hadd hívjam bizonyságul ellenök a mennyet és földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'Mert tudom, hogy halálom után mind inkább-inkább megromoltok és eltértek az útról, a melyet parancsoltam néktek; és utólér majd titeket a veszedelem a későbbi időben, mivelhogy gonoszt cselekesztek az Úrnak szemei előtt, bosszantván őt kezeiteknek csinálmányával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'Azután elmondá Mózes Izráel egész gyülekezetének füle hallására ez éneknek ígéit, mind végig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, 'Figyeljetek egek, hadd szóljak! Hallgassa a föld is számnak beszédeit!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'Csepegjen tanításom, mint eső; hulljon mint harmat a beszédem; mint langyos zápor a gyenge fűre, s mint permetezés a pázsitra!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, 'Mert az Úr nevét hirdetem: magasztaljátok Istenünket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'Kőszikla! Cselekedete tökéletes, mert minden ő úta igazság! Hűséges Isten és nem csalárd; igaz és egyenes ő!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, 'Gonoszak voltak hozzá, nem fiai, a magok gyalázatja; romlott és elvetemült nemzedék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'Így fizettek-é az Úrnak: balga és értelmetlen nép?! Nem atyád-é ő, a ki teremtett? Ő alkotott és erősített meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'Emlékezzél meg az ős időkről; gondoljátok el annyi nemzedék éveit! Kérdezd meg atyádat és megjelenti néked, a te véneidet és megmondják néked!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'Mikor a Felséges örökséget osztott a népeknek; mikor szétválasztá az ember fiait: megszabta a népek határait, Izráel fiainak száma szerint,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'Mert az Úrnak része az ő népe, Jákób néki sorssal jutott öröksége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'Puszta földön találta vala őt, zordon, sivatag vadonban; körülvette őt, gondja volt reá, őrizte, mint a szeme fényét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'Mint a fészkén felrebbenő sas, fiai felett lebeg, kiterjeszti felettök szárnyait, felveszi őket, és tollain emeli őket:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'Egymaga vezette őt az Úr; idegen Isten nem volt ő vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'A föld magaslatain járatta őt, mezők terméseivel étette, kősziklából is mézet szopatott vele, kovaszirtből is olajat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'Tehenek vaját, és juhok tejét bárányok kövérjével, básáni kosokat és bakkecskéket a buza java kövérjével; és szőlő vérét, bort ittál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'És meghízott Jesurun, és rúgódozott. Meghíztál, megkövéredtél, elhájasodtál. És elhagyá Istent, teremtőjét, és megveté az ő üdvösségének kőszikláját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'Idegen istenekkel ingerelték, útálatosságokkal bosszantották.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'Ördögöknek áldoztak, nem Istennek; isteneknek, a kiket nem ismertek; újaknak, a kik csak most támadtak, a kiket nem rettegtek a ti atyáitok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'A Kősziklát, a ki szült téged, elfeledted; megfelejtkeztél Istenről, a ki nemzett téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'Látta ezt az Úr és megútálta bosszúságában az ő fiait és leányait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'És monda: Elrejtem orczámat előlök, hadd látom, mi lesz a végök? Mert elzüllött nemzetség ez, fiak, a kikben nincs hűség!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'Azzal ingereltek ők, a mi nem isten; hiábavalóságaikkal bosszantottak engem; én pedig azzal ingerlem őket, a mi nem népem: bolond nemzettel bosszantom őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'Mert tűz lobban fel haragomban és leég a Seol fenekéig; megemészti a földet és gyümölcsét, és felgyújtja a hegyek alapjait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'Veszedelmeket halmozok reájok, nyilaimat mind rájok fogyasztom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'Éhségtől aszottan, láztól emésztetten és keserű dögvésztől – a vadak fogait is rájok bocsátom, a porban csúszók mérgével együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'Kivül fegyver pusztít, az ágyasházakban rettegés: ifjat és szűzet, csecsszopót a vén emberrel együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'Mondom: Elfuvom őket, eltörlöm emlékezetöket az emberek közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'Ha nem tartanék az ellenség bosszantásától, hogy szorongatóik a dolgot félremagyarázzák, és hogy ezt mondják: A mi kezünk a hatalmas, és nem az Úr cselekedte mind ezt! -');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'Mert tanács-vesztett nép ez, és nincs bennök értelem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, 'Vajha eszesek volnának, megértenék ezt, meggondolnák, hogy mi lesz a végök!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'Miképen kergethetne egy ezeret, és kettő hogyan űzhetne tízezeret, ha az ő Kősziklájok el nem adja őket, és ha az Úr kézbe nem adja őket?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'Mert a mi Kősziklánk nem olyan, mint az ő kősziklájok; ellenségeink is megítélhetik!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'Mert az ő szőlőjök Sodoma szőlője és Gomora mezősége; bogyóik mérges bogyók, keserűek a gerézdjeik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'Sárkányok mérge az ő boruk, áspiskígyóknak kegyetlen epéje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, 'Nincsen-é ez elrejtve nálam, lepecsételve az én kincseim között?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'Enyém a bosszúállás és megfizetés, a mikor lábuk megtántorodik; mert közel van az ő veszedelmök napja, és siet, a mi rájok vár!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'Mert megítéli az Úr az ő népét, és megkönyörül az ő szolgáin, ha látja, hogy elfogyott az erő, s védett és védtelen oda van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'És ezt mondja: Hol az ő istenök? a Kőszikla, a melyben bizakodtak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'A kik megették az ő véres áldozataik kövérjét, megitták az ő italáldozatuk borát: keljenek fel és segítsenek meg titeket, és oltalmazzanak meg titeket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Most lássátok meg, hogy én vagyok, és nincs Isten kivülem! Én ölök és elevenítek, én sebesítek és én gyógyítok, és nincs, a ki kezemből megszabadítson.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'Mert felemelem kezemet az égre, és ezt mondom: Örökké élek én!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'Ha megélesítem fényes kardomat és ítélethez fog kezem: bosszút állok ellenségeimen és megfizetek gyűlölőimnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'Megrészegítem nyilaimat vérrel, és kardom jól lakik hússal: a legyilkoltak és foglyok vérével, az ellenség vezéreinek fejéből!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Ujjongjatok ti nemzetek, ő népe! Mert ő megtorolja az ő szolgáinak vérét, bosszút áll az ő ellenségein, földjének és népének megbocsát!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'Elméne azért Mózes és elmondá ez éneknek minden ígéjét a nép füle hallására, ő és Józsué a Nún fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'És mikor végig elmondá Mózes mind ez ígéket az egész Izráelnek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'Monda nékik: Vegyétek szívetekre mind ezeket az ígéket, a melyekkel én bizonyságot teszek ellenetek e mai napon; és parancsoljátok meg fiaitoknak, hogy tartsák meg és teljesítsék e törvénynek minden ígéjét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'Mert nem hiábavaló íge ez néktek; hanem ez a ti életetek, és ez íge által hosszabbítjátok meg napjaitokat azon a földön, a melyre általmentek a Jordánon, hogy bírjátok azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'És ugyanezen a napon szóla az Úr Mózesnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, 'Menj fel ebbe az Abarim hegységbe, a Nébó hegyére, a mely Moáb földén van és pedig Jérikhóval átellenben; és nézd meg a Kanaán földét, a melyet én Izráel fiainak adok örökségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'És halj meg a hegyen, a melyre felmégy, és takaríttassál a te népedhez, a miképen meghalt Áron, a te testvéred a Hór hegyén, és takaríttatott az ő népeihez;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'Mivelhogy vétkeztetek ellenem Izráel fiai között a versengésnek vizénél, a Czin pusztájában Kádesnél: mert nem szenteltetek meg engem Izráel fiai között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'Mert szemközt látod a földet; de arra a földre, a melyet én adok Izráel fiainak, oda nem mégy be.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, 'Ez pedig az áldás, a melylyel megáldá Mózes, az Istennek embere, Izráel fiait az ő halála előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'Monda ugyanis: Az Úr a Sinai hegyről jött, és Szeirből támadt fel nékik; Párán hegyéről ragyogott elő, tízezer szent közül jelent meg, jobbja felől tüzes törvény vala számukra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'Bizony szereti ő a népeket! Mind kezednél vannak az ő szentjei, oda szegődnek, a te lábaidhoz, és hallgatják a te beszédeidet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'Törvényt parancsolt nékünk Mózes, örökségül Jákób községének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, 'És király lőn Jesurunban, mikor összegyűltek a népnek fejei, és együtt voltak Izráel törzsei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, 'Éljen Rúben és meg ne haljon; és száma legyen embereinek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'Ez pedig a Júda áldása; és monda: Hallgasd meg Uram a Júda szavát, és vidd be őt az ő népéhez. Az ő keze elégséges legyen néki, de légy segítsége az ő szorongatói ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'Léviről pedig monda: A te Thummimod és Urimod a te kegyes férfiadé, a kit megkísértél Masszában, a kivel perbe szálltál Mériba vizeinél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'A ki azt mondta az ő atyjáról és anyjáról: Nem láttam őt; és az ő atyjafiait nem ismerte, fiaival sem gondolt; mert megtartották a te beszédedet, és ragaszkodtak szövetségedhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'Tanítják a te végzéseidre Jákóbot, és a te törvényedre Izráelt; füstölőt tesznek a te orczád elé, és égőáldozatot a te oltárodra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'Áldd meg Uram az ő erejét, és az ő kezének munkája legyen kedves előtted! Törd meg derekukat a reá támadóknak és az ő gyűlölőinek, hogy fel ne kelhessenek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'Benjáminról monda: Az Úrnak kedveltje! Bátorságban lakozik mellette, fedezi őt minden időben, és az ő vállai között lakik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'Józsefről pedig monda: Áldott az Úrtól az ő földe az égnek kincseivel, a harmattal és az alant elterülő mélységes vizekkel;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'A nap érlelte drága terméssel, és a hold sarjasztotta drágaságokkal;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'És az ős hegyek javaival, és az örök halmok drágaságaival;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'A földnek drágaságaival és bőségével. A csipkebokorban lakozónak jó kedve szálljon Józsefnek fejére, az ő atyjafiai közül kiválasztottnak koponyájára!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, 'Tehenének első fajzása dicsőségére van; szarvai bivalyszarvak; népeket öklel azokkal mindenfelé a földnek széléig. És ezek Efraim tízezrei és Manassé ezrei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'És Zebulonról monda: Örvendj Zebulon a te kimentedben, és te Izsakhár a te sátraidban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'Népeket hívogatnak a hegyre, igaz áldozattal áldoznak ott; mert a tengerek bőségét szopják, és a fövénynek rejtett kincseit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'És Gádról monda: Áldott az, a ki kiterjeszti Gádot! Mint nőstény oroszlán, úgy lakik, és szétszaggat kart és koponyát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'Az elejét nézte ki magának, mert ott volt elrejtve a törvényadó osztályrésze. De elméne a népnek fejedelmeivel, az Úrnak igazságát cselekedte, és az ő végzését Izráellel együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'És Dánról monda: Dán oroszlánnak kölyke, a mely Básánból szökik ki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'És Nafthaliról monda: Ó Nafthali, a ki az Úrnak jó kedvével bővölködöl és áldásával vagy teljes! Vedd birtokba a tengert és a délt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'És Áserről monda: Áldott a többi fiak felett Áser! Legyen az ő atyjafiai előtt kedves, és áztassa lábát olajban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'Vas és réz legyenek a te záraid; és élteden át tartson erőd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, 'Nincs olyan, mint a Jesurun Istene! Az egeken száguld segítségedre, és fenségében a felhőkön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'Hajlék az örökkévaló Isten, alant vannak örökkévaló karjai; elűzi előled az ellenséget, és ezt mondja: Pusztítsd!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'És bátorságban lakozik Izráel, egymaga lesz Jákób forrása a gabona és a bor földén, és az ő egei harmatot csepegnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'Boldog vagy Izráel! Kicsoda olyan mint te? Nép, a kit az Úr véd, a te segítségednek pajzsa, és a ki a te dicsőségednek fegyvere! Hízelegnek majd néked a te ellenségeid, és te azoknak magaslatait taposod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, 'És felméne Mózes a Moáb mezőségéről a Nébó hegyére, a Piszga tetejére, a mely átellenben van Jérikhóval; és megmutatá néki az Úr az egész földet, a Gileádot Dánig;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'És az egész Nafthalit, Efraim és Manassé földét, az egész Júda földét a túlsó tengerig;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'És a déli tartományt, és Jérikhónak, a pálmafák városa völgyének környékét, Czoárig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, 'És monda néki az Úr: Ez a föld az, a mely felől megesküdtem Ábrahámnak, Izsáknak, Jákóbnak, mondván: a te magodnak adom azt. Megengedtem néked, hogy szemeiddel lásd, de oda nem mégy át.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'És meghala ott Mózes, az Úrnak szolgája a Moáb földén, az Úr szava szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'És eltemeték őt a völgyben, a Moáb földén, Béth-Peórral átellenben; és senki sem tudja az ő temetésének helyét e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'Mózes pedig száz és húsz esztendős volt, mikor meghalt; nem homályosodott vala meg az ő szeme, sem el nem fogyatkozott vala az ő ereje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'És siraták Izráel fiai Mózest a Moáb mezőségén harmincz napig; és eltelének a Mózes siratásának, azaz gyászolásának napjai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'Józsué, a Nún fia pedig beteljesedék bölcseségnek lelkével; mert Mózes tette vala ő reá kezeit; és hallgatának reá Izráel fiai, és úgy cselekedének, a mint parancsolta vala az Úr Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'És nem támadott többé Izráelben olyan próféta, mint Mózes, a kit ismert volna az Úr színről-színre:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, 'Mindazokban a jelekben és csudákban, a melyekért küldötte vala őt az Úr, hogy véghez vigye azokat Égyiptom földén, a Faraón, minden ő szolgáján, és az ő egész földén;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'És mindama hatalmas erőben, és mindama nagy rettenetességben, a melyeket véghez vitt Mózes az egész Izráel szemei előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'És lőn Mózesnek, az Úr szolgájának halála után, szóla az Úr Józsuénak, a Nún fiának, Mózes szolgájának, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, 'Mózes, az én szolgám meghalt; most azért kelj fel, menj át ezen a Jordánon, te és mind ez a nép arra a földre, a melyet én adok nékik, az Izráel fiainak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'Minden helyet, a melyet talpatok érint, néktek adtam, a miképen szólottam Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'A pusztától és a Libánontól fogva a nagy folyóvízig, az Eufrates folyóvízig, a Khitteusoknak egész földe és a nagy tengerig napnyugat felé lesz a ti határotok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'Meg nem áll senki előtted életednek minden idejében; a miképen Mózessel vele voltam, teveled is veled leszek; el nem hagylak téged, sem el nem maradok tőled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, 'Légy bátor és erős, mert te teszed majd e népet annak a földnek örökösévé, a mely felől megesküdtem az ő atyáiknak, hogy nékik adom azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'Csak légy bátor és igen erős, hogy vigyázz és mindent ama törvény szerint cselekedjél, a melyet Mózes, az én szolgám szabott elődbe; attól se jobbra, se balra ne hajolj, hogy jó szerencsés lehess mindenben, a miben jársz!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'El ne távozzék e törvénynek könyve a te szádtól, hanem gondolkodjál arról éjjel és nappal, hogy vigyázz és mindent úgy cselekedjél, a mint írva van abban, mert akkor leszel jó szerencsés a te utaidon és akkor boldogulsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'Avagy nem parancsoltam-é meg néked: légy bátor és erős? Ne félj, és ne rettegj, mert veled lesz az Úr, a te Istened mindenben, a miben jársz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'Parancsola azért Józsué a nép előljáróinak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, 'Menjetek által a táboron, és parancsoljátok meg a népnek, mondván: Készítsetek magatoknak útravalót, mert harmadnap mulva átmentek ti ezen a Jordánon, hogy bemenjetek és bírjátok azt a földet, a melyet az Úr, a ti Istenetek ád néktek birtokul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'A Rúben és Gád nemzetségének pedig, és a Manassé nemzetség felének szóla Józsué, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, 'Emlékezzetek meg a dologról, a mit megparancsolt néktek Mózes, az Úrnak szolgája, mondván: Az Úr, a ti Istenetek megnyugtatott titeket, és néktek adta ezt a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'Feleségeitek, gyermekeitek és barmaitok maradjanak e földön, a melyet adott néktek Mózes a Jordánon túl; ti pedig fegyveres kézzel menjetek át atyátokfiai előtt, mindnyájan, a kik közületek erős vitézek, és segéljétek meg őket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'A míg megnyugosztja az Úr a ti atyátokfiait is, mint titeket, és bírják ők is a földet, a melyet az Úr, a ti Istenetek ád nékik: akkor aztán térjetek vissza a ti örökségtek földére és bírjátok azt, a melyet Mózes, az Úr szolgája adott néktek a Jordánon túl, napkelet felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'Azok pedig felelének Józsuénak, mondván: Mindent megcselekszünk, a mit parancsoltál nékünk, és a hová küldesz minket, oda megyünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'A mint Mózesre hallgattunk, épen úgy hallgatunk majd te reád, csak legyen veled az Úr, a te Istened, a miképen vele volt Mózessel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'Mindenki, a ki ellene szegül a te szódnak, és nem hallgat a te beszédedre mindabban, a mit parancsolsz néki, megölettessék. Csak bátor légy és erős!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, 'És Józsué, a Nún fia, elkülde Sittimből titkon két férfiút kémekül, mondván: Menjetek el, tekintsétek meg azt a földet és Jérikhót. Azok pedig elmenének, és bemenének egy parázna asszonynak házába, a kinek Ráháb vala neve, és ott hálának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'Mikor pedig megjelentették ezt Jérikhó királyának, mondván: Íme, férfiak jöttek ide ez éjszaka az Izráel fiai közül e földnek kémlelésére;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'Akkor külde Jérikhó királya Ráhábhoz, mondván: Hozd ki a férfiakat, a kik bementek hozzád, a kik házadba mentek, mert azért jöttek, hogy kikémleljék az egész földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, 'Az asszony pedig fogá a két férfiút, és elrejté vala őket, és monda: Úgy van! Bejöttek hozzám a férfiak, de azt sem tudom, honnan valók voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'És kimentek e férfiak kapuzáráskor a setétben; nem tudom, hová mentek a férfiak; siessetek gyorsan utánok, mert utólérhetitek őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'Pedig ő felhágatta őket a házhéjára, és elbujtatta őket a száras len közé, a mely néki a házhéjára volt kirakva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'És utánok sietének a férfiak a Jordánhoz vivő úton a rév felé; a kaput pedig bezárták, azután, hogy kimenének azok, a kik őket üldözik vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'Ők pedig még le sem feküvének, a mikor felméne ő hozzájok az asszony a házhéjára,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, 'És monda a férfiaknak: Tudom, hogy az Úr néktek adta ezt a földet, és hogy megszállt minket a félelem miattatok, és hogy e földnek minden lakosa megolvad előttetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'Mert hallottuk, hogy megszárította az Úr a Veres tenger vizét előttetek, a mikor kijöttetek Égyiptomból, és hogy mit cselekedtetek az Emoreusok két királyával, a kik túl voltak a Jordánon, Szíhonnal és Óggal, a kiket megöltetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'És a mint hallottuk, megolvadott a mi szívünk, és nem támadt többé bátorság senkiben sem miattatok. Bizony az Úr, a ti Istenetek az Isten fenn az égben és alant a földön!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'Most azért esküdjetek meg kérlek, nékem az Úrra, hogy a mint én irgalmasságot cselekedtem veletek, ti is irgalmasságot cselekesztek majd az én atyámnak házával, és igaz jelt adtok nékem,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'Hogy életben hagyjátok az én atyámat és anyámat, férfi és nőtestvéreimet, és mindent, a mi az övék, és megmentitek a mi lelkünket a haláltól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'És mondának néki a férfiak: A mi lelkünket érje helyettetek a halál, ha meg nem jelentitek ezt a mi dolgunkat. És ha nékünk adja az Úr ezt a földet, irgalmasságot és igazságot cselekszünk veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'Alábocsátá azért őket kötélen az ablakon (mert az ő háza a kőkerítés falán vala, és ő a kőkerítésen lakik vala).');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'És monda nékik: A hegyre menjetek, hogy rátok ne találjanak az üldözők, és ott rejtőzködjetek három napig, a míg visszatérnek az üldözők; azután pedig menjetek a magatok útján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'A férfiak pedig mondának néki: Ártatlanok leszünk ezen te esketésedtől, a melylyel te megeskettél minket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'Ha bejövünk mi erre a földre, kösd e veres fonalú zsinórt ahhoz az ablakhoz, a melyen alábocsátottál minket; atyádat, anyádat és atyádfiait pedig, és atyádnak egész háznépét gyűjtsd be magadhoz a házba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, 'És akkor, ha akárki kijön a te házadnak ajtain, annak vére az ő fején lesz, mi pedig ártatlanok leszünk; mindannak vére pedig, a ki te veled lesz a házban, a mi fejünkön legyen, ha valakinek keze lenne azon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'Ha pedig megjelented ezt a mi dolgunkat, akkor mi fel leszünk oldva az eskü alól, a melylyel te megeskettél minket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'Monda pedig amaz: A mint szólottatok, úgy legyen! Ekkor elbocsátá őket, és elmenének; a veres zsinórt pedig reáköté az ablakra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'És elmenének és eljutának a hegyre, és ott maradának három nap, mígnem visszatérének az üldözők. Keresék ugyanis őket az üldözők minden úton, de nem találták vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'Akkor a két férfiú visszatére, és leszállának a hegyről, és átmenének a Jordánon, és eljutának Józsuéhoz, a Nún fiához, és elbeszélének néki mindent, a mi történt vala velök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'És mondának Józsuénak: Bizony kezünkbe adta az Úr azt az egész földet; meg is olvadt már a földnek minden lakosa miattunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'Felkele azért Józsué jó reggel, és elindulának Sittimből, és eljutának a Jordánhoz, ő és Izráel fiai mindnyájan, és meghálának ott, mielőtt általmentek volna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, 'Lőn pedig három nap mulva, hogy általmenének a vezérek a táboron;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, 'És parancsolának a népnek, mondván: Mihelyt meglátjátok az Úrnak, a ti Isteneteknek frigyládáját és a Lévi nemzetségéből való papokat, a kik hordozzák azt, ti is induljatok meg a ti helyetekről és menjetek utána.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'Csakhogy legyen köztetek és a között mintegy kétezer singnyi távolság; közel ne menjetek ahhoz, hogy megismerhessétek az útat, a melyen mennetek kell, mert nem jártatok ezen az úton soha ez előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'Józsué pedig monda a népnek: Tisztítsátok meg magatokat, mert holnap az Úr csudákat cselekszik köztetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'A papoknak is szóla Józsué, mondván: Vegyétek fel a frigyládát, és menjetek át a nép előtt. Felvevék azért a frigyládát, és mennek vala a nép előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'Az Úr pedig monda Józsuénak: E napon kezdelek téged felmagasztalni az egész Izráel szemei előtt, hogy megtudják, hogy a miképen vele voltam Mózessel, te veled is veled leszek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'Te azért parancsolj a papoknak, a kik a frigyládát hordozzák, mondván: Mikor bementek a Jordán vizének szélébe, álljatok meg a Jordánban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'Ekkor monda Józsué Izráel fiainak: Járuljatok ide, és halljátok meg az Úrnak, a ti Isteneteknek szavait!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'És monda Józsué: Ebből tudjátok meg, hogy az élő Isten van köztetek, és hogy kétség nélkül elűzi előletek a Kananeust, a Khittheust, a Khivveust, a Perizeust, a Girgazeust, az Emoreust és a Jebuzeust:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'Íme az egész föld Urának frigyládája előttetek megy át a Jordánon!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'Most azért válaszszatok magatoknak tizenkét férfiút Izráel nemzetségeiből, egy-egy férfiút egy-egy nemzetségből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'És mihelyt megnyugosznak majd a Jordán vizében a papok talpai, a kik az Úrnak, az egész föld Urának ládáját hordozzák: a Jordán vize ketté szakad, és a felülről aláfolyó víz megáll egy rakásban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'És lőn, hogy a mint megindula a nép az ő sátraiból, hogy általmenjen a Jordánon, és a papok, a frigyládának hordozói, a nép előtt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'És a mint a láda hordozói a Jordánhoz jutának, és a ládahordozó papok bemárták lábaikat a víznek szélébe (a Jordán pedig az egész aratási idő alatt telve vala minden ő partja felett):');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'Megálla a víz, a mely felülről foly vala alá, és álla egy rakásban, nagy messzire Ádám városánál, a mely Czarthan mellett vala; a puszta tengere, a Sóstenger felé aláfolyó víz pedig egészen elfuta, és általméne a nép Jérikhó előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'A papok pedig, az Úr frigyládájának hordozói, ott állának a szárazon a Jordán közepében bátorsággal, és az egész Izráel szárazon megy vala át, mindaddig, míg az egész nép teljesen általméne a Jordánon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'Mikor pedig az egész nép teljesen általment vala a Jordánon, szóla az Úr Józsuénak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, 'Vegyetek magatokhoz a népből tizenkét férfiút, egy-egy férfiút egy-egy nemzetségből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'És parancsoljátok nékik, mondván: Vegyetek fel innét a Jordán közepéből, arról a helyről, a hol bátorsággal állanak a papok lábai, tizenkét követ, és vigyétek át azokat magatokkal, és tegyétek le a szálláson, a hol megháltok ez éjszaka.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'Előhivá azért Józsué a tizenkét férfiút, a kiket az Izráel fiai közül rendelt vala, egy-egy férfiút egy-egy nemzetségből;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'És monda nékik Józsué: Menjetek át az Úrnak, a ti Isteneteknek frigyládája előtt a Jordán közepébe, s vegyen fel mindegyikőtök egy-egy követ az ő vállára, az Izráel fiai nemzetségeinek száma szerint,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'Hogy legyen ez jelül köztetek. Ha kérdezik majd ezután a ti fiaitok, mondván: Mire valók néktek ezek a kövek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'Mondjátok meg nékik, hogy kétfelé vált a Jordánnak vize az Úr frigyládája előtt, mikor általment a Jordánon; ketté vált a Jordánnak vize, és ezek a kövek emlékeztetőül lesznek az Izráel fiainak mindörökre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'És úgy cselekedének Izráel fiai, a mint megparancsolta vala Józsué, és felvevének a Jordán közepéből tizenkét követ, a mint megmondotta vala az Úr Józsuénak, az Izráel fiai nemzetségeinek száma szerint, és általhozák magokkal az éjjeli szállásra és ott letevék azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'Tizenkét követ állíta fel Józsué a Jordán közepén is, azon a helyen, a hol állottak vala a frigyládát vivő papok lábai; ott is vannak mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'A papok pedig, a ládának hordozói, állanak vala a Jordán közepén, a míg végbe mene mind az a dolog, a mit parancsolt vala az Úr Józsuénak, hogy mondja meg a népnek, egészen úgy, a mint Mózes parancsolta vala Józsuénak. A nép pedig sietett és általméne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'És a mint véget ére az egész nép általmenetele, általméne az Úr ládája is és a papok is, a nép előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'Általmentek vala a Rúben fiai, a Gád fiai és Manassé félnemzetsége is felfegyverkezve az Izráel fiai előtt, a miképen szólt vala nékik Mózes.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'Mintegy negyven ezernyi fegyveres vitéz ment vala át az Úr előtt a harczra, Jérikhónak sík mezejére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'Azon a napon felmagasztalá az Úr Józsuét az egész Izráel szemei előtt, és félék őt, a mint félték vala Mózest, életének minden napjaiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'Mert szólt vala az Úr Józsuénak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, 'Parancsold meg a papoknak, a kik a bizonyság ládáját hordozzák, hogy jőjjenek fel a Jordánból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'És parancsola Józsué a papoknak, mondván: Jőjjetek fel a Jordánból!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'És lőn, hogy a mint a papok, az Úr frigyládájának hordozói, feljöttek vala a Jordán közepéből, és érintik vala a papok talpai a szárazt: visszatére a Jordán vize az ő helyére, és folyt vala, mint az előtt, minden partja felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'A nép pedig az első hónak tizedik napján jöve fel a Jordánból, és tábort üte Gilgálban, Jérikhónak keleti határán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'Azt a tizenkét követ is, a melyeket a Jordánból hoztak vala, Gilgálban állatá fel Józsué.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'És szóla Izráel fiainak, mondván: Ha fiaitok kérdezik majd apáiktól, mondván: Mire valók ezek a kövek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'Tudassátok majd a ti fiaitokkal, mondván: Szárazon jött át Izráel ezen a Jordánon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, 'Mert kiszárította az Úr, a ti Istenetek a Jordán vizét ti előttetek, míg általjövétek rajta, a miképen cselekedett vala az Úr, a ti Istenetek a Veres tengerrel, a melyet megszárított előttünk; míg általjövénk rajta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'Hogy megismerje a földnek minden népe az Úrnak kezét, hogy bizony erős az; hogy féljétek az Urat, a ti Isteneteket minden időben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'Lőn pedig, a mint meghallák az Emoreusok minden királyai, a kik a Jordánon túl laknak napnyugot felé, és a Kananeusok minden királyai, a kik a tenger mellett laknak vala, hogy kiszáraztotta az Úr a Jordánnak vizét az Izráel fiai előtt, a míg általjöttünk vala; megolvada az ő szívök, és nem vala többé bátorság bennök Izráel fiai miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'Ez időben monda az Úr Józsuénak: Csinálj magadnak kőkéseket, és másodszor is metéld körül az Izráel fiait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'És csinála Józsué magának kőkéseket, és körülmetélé Izráel fiait a körülmetéletlenség halmán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'Az ok pedig, a miért körülmetélé őket Józsué, ez: Mindaz a nép, a mely kijött vala Égyiptomból; a férfiak, a hadakozó emberek mindnyájan meghaltak vala a pusztában, útközben, a míg jöttek vala Égyiptomból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'Mert körül volt ugyan metélve mindaz a nép, a mely kijött vala; de azt a népet, a mely a pusztában született, útközben, a míg jöttek vala Égyiptomból, nem metélték vala körül;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, 'Mert negyven esztendeig jártak Izráel fiai a pusztában, mialatt elemészteték a hadakozó férfiaknak egész népsége, a kik Égyiptomból jöttek vala ki, mivelhogy nem hallgattak vala az Úr szavára; a kiknek megesküdt az Úr, hogy nem láttatja meg velök a földet, a mely felől megesküdt vala az Úr az ő atyáiknak, hogy nékünk adja azt a tejjel és mézzel folyó földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'Fiaikat állította vala azért helyökbe, ezeket metélé körül Józsué, mert körülmetéletlenek valának, mivelhogy nem metélék vala körül őket az útban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'Miután pedig mind az egész nép körülmetéltetett vala, veszteg lőnek az ő helyökön a táborban, míglen meggyógyulának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'És monda az Úr Józsuénak: Ma fordítottam el rólatok Égyiptom gyalázatát; ezért hívják e hely nevét Gilgálnak mind a mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'És Gilgálban táborozának Izráel fiai, és megkészíték a páskhát a hónapnak tizennegyedik napján, estve, Jérikhónak mezején.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'És evének a föld terméséből a páskhának másodnapján kovásztalan kenyeret és pörkölt gabonát, ugyanezen a napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'És másnaptól kezdve, hogy ettek vala a föld terméséből, megszűnék a manna, és nem volt többé mannájok az Izráel fiainak; hanem Kanaán földének gyümölcséből evének abban az esztendőben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'Lőn pedig, a mikor Józsué Jérikhónál vala, felemelé az ő szemeit, és látá, hogy íme egy férfiú áll vala előtte meztelen karddal kezében. És hozzá méne Józsué, és monda néki: Közülünk való vagy-é te, vagy ellenségeink közül?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'Az pedig monda: Nem, mert én az Úr seregének fejedelme vagyok, most jöttem. És leborula Józsué a földre arczczal, és meghajtá magát, és monda néki: Mit szól az én Uram az ő szolgájának?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'És monda az Úr seregének fejedelme Józsuénak: Oldd le a te saruidat lábaidról, mert szent a hely, a melyen állasz. És úgy cselekedék Józsué.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, 'Jérikhó pedig be- és elzárkózott vala az Izráel fiai miatt, se ki nem jöhetett, se be nem mehetett senki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'És monda az Úr Józsuénak: Lásd! kezedbe adtam Jérikhót és királyát a sereg vitézeivel együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'Azért járjátok körül a várost mind ti hadakozó emberek, megkerülvén egyszer a várost. Így cselekedjél hat napon át.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, 'És hét pap hordozzon hét kos-szarvból való kürtöt a láda előtt; a hetedik napon azonban hétszer kerüljétek meg a várost, a papok pedig kürtöljenek a kürtökkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'És ha majd belefúnak a kos-szarvba, mihelyt meghalljátok a kürtnek szavát, kiáltson fel az egész nép nagy kiáltással, és leszakad a város kőfala magától, és felmegy arra a nép, kiki az előtte való helyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'Előhívá azért Józsué, a Nún fia, a papokat és monda nékik: Vegyétek fel a frigyládát, hét pap pedig vigyen hét kos-szarvból való kürtöt az Úr ládája előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'A népnek pedig monda: Menjetek el, és kerüljétek meg a várost, a fegyveresek pedig menjenek az Úr ládája előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'És úgy lőn, a mint mondotta vala Józsué a népnek. A hét pap ugyanis, a kik a kos-szarvból való hét kürtöt vivék, az Úr előtt megy vala, és kürtölt vala a kürtökkel, az Úrnak frigyládája pedig utánok megy vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'A fegyveresek pedig előttök mennek vala a kürtölő papoknak, és a köznép követi vala a ládát, menvén és kürtölvén kürtökkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'A népnek pedig parancsolt vala Józsué, mondván: Ne kiáltsatok, hangotokat se hallassátok, és szó se jőjjön ki szátokból addig a napig, a míg azt mondom néktek: Kiáltsatok; és akkor kiáltsatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'Körüljárák azért az Úrnak ládájával a várost, egyszer megkerülvén; azután visszatérének a táborba, és az éjszakát a táborban tölték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'Józsué pedig felkele jó reggel, és felvevék a papok az Úrnak ládáját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'És a hét pap, a kik a kos-szarvból való hét kürtöt vivék, az Úr ládája előtt megy vala folyton, és kürtöl vala a kürtökkel, a fegyveresek pedig előttök mennek vala, és a köznép követi az Úrnak ládáját, menvén és kürtökkel kürtölvén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'A második napon is egyszer kerülék meg a várost, azután visszatérének a táborba. Így cselekedének hat napon át.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'És lőn a hetedik napon, hogy felkelének, mihelyt a hajnal feljöve, és megkerülék a várost a szokott módon hétszer; csak ezen a napon kerülék meg a várost hétszer.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'És lőn, hogy a hetedik forduláskor kürtölnek vala a papok a kürtökkel, Józsué pedig monda a népnek: Kiáltsatok, mert néktek adta az Úr a várost!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'És legyen a város maga, és minden, a mi benne van, teljesen az Úrnak szentelve; csak a parázna Ráháb maradjon életben, ő és mindazok, a kik vele vannak a házban, mert elrejtette a követeket, a kiket küldöttünk volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'Mindazáltal ti óvjátok meg magatokat a teljesen Istennek szentelt dolgoktól, hogy miután néki szentelitek, el ne vegyetek a teljesen néki szentelt dolgokból, hogy Izráel táborát átkozottá ne tegyétek, és bajba ne keverjétek azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'Hanem mivel minden ezüst- és arany-, meg réz- és vasedény az Úrnak van szentelve, az Úrnak kincse közé jusson.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'Kiálta azért a nép, mihelyt kürtölének a kürtökkel. Lőn ugyanis, a mint meghallá a nép a kürtnek szavát, kiálta a nép nagy kiáltással, és leszakada a kőfal magától, és felméne a nép a városba, kiki az előtte való helyen, és bevevék a várost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'És teljesen kipusztítának mindent, a mi csak vala a városban, a férfitól az asszonyig, a gyermektől az öregig, sőt az ökörig, juhig és a szamárig, fegyver élivel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'A két férfiúnak pedig, a kik megkémlelték vala a földet, monda Józsué: Menjetek be a parázna asszonynak házába és hozzátok ki onnét az asszonyt és mindazt, a mije van, a miképen megesküdtetek néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'Bemenének azért a kémlő ifjak, és kihozák Ráhábot, és az ő atyját, anyját és az ő atyjafiait, és mindazt, a mije vala, és minden cselédjét is kihozák, és helyezék őket Izráel táborán kivül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'A várost pedig megégeték tűzzel, és mind azt, a mi benne vala; csakis az ezüstöt és aranyat és a réz- és vasedényeket rakták az Úr házának kincsei közé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'A parázna Ráhábot pedig, és az ő atyjának háznépét és mindenét, a mije vala, élni hagyta vala Józsué, és ott lakik az Izráel között mind e mai napig; mert elrejtette vala a követeket, a kiket küldött volt Józsué, hogy kikémleljék Jérikhót.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'És átkot szóla Józsué azon a napon, mondván: Átkozott legyen az Úr előtt az a férfiú, a ki felkél, hogy megépítse e várost, Jérikhót! Az ő első szülöttjére rakja le annak alapját s legifjabb fiára állítsa fel annak kapuit!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'És vala az Úr Józsuéval, és lőn híre az egész földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, 'De az Izráel fiai hűtlenül bántak vala a teljesen Istennek szentelt dolgokkal, mert elvőn a teljesen Istennek szentelt dolgokból Ákán, Kárminak fia (ki a Zabdi fia, ki a Zéra fia a Júda nemzetségéből); felgerjede azért az Úrnak haragja Izráel fiai ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'Külde ugyanis Józsué férfiakat Jérikhóból, Aiba, a mely Bethaven mellett van, Bétheltől napkelet felé, és szóla nékik, mondván: Menjetek fel és kémleljétek ki azt a földet. És felmenének a férfiak és kikémlelék Ait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'Majd visszatérének Józsuéhoz, és mondának néki: Ne menjen fel az egész nép; mintegy kétezer férfi, vagy mintegy háromezer férfi menjen fel, és megverik Ait. Ne fáraszd oda az egész népet, hiszen kevesen vannak azok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'Felméne azért oda a népből mintegy háromezer férfi; de elfutának Ai férfiai elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'És megölének közülök Ai férfiai mintegy harminczhat férfit, és üldözék őket a kaputól kezdve egész Sébarimig, és levágták őket a lejtőn. Azért megolvada a népnek szíve, és lőn olyanná, mint a víz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'Józsué pedig megszaggatá az ő ruháit, és földre borula arczczal az Úrnak ládája előtt mind estvéig, ő és Izráel vénei, és port hintének a fejökre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'És monda Józsué: Ah Uram Istenem! Miért is hozád által ezt a népet a Jordánon, hogyha az Emoreus kezébe adsz minket, hogy elveszítsen? Vajha úgy akartuk volna, hogy maradtunk volna túl a Jordánon!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'Óh Uram! mit mondjak, miután meghátrált Izráel az ő ellenségei előtt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'Ha meghallják a Kananeusok és e földnek minden lakói, és ellenünk fordulnak, és kiirtják nevünket e földről: mit cselekszel majd a te nagy nevedért?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'És monda az Úr Józsuénak: Kelj fel! Miért is borulsz te arczra?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'Vétkezett Izráel, és általhágták szövetségemet is, a melyet rendeltem nékik, mert elvettek a teljesen nékem szentelt dolgokból is, és loptak is és hazudtak is, és edényeik közé is dugdostak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'Ezért nem bírtak megállni Izráel fiai az ő ellenségeik előtt, hátat fordítottak ellenségeiknek, mert átkozottakká lettek. Nem leszek többé veletek, ha ki nem vesztitek magatok közül azt a nékem szentelt dolgot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'Kelj fel, és tisztítsd meg a népet, és mondjad: Tisztítsátok meg magatokat holnapra, mert ezt mondá az Úr, Izráelnek Istene: Istennek szentelt dolog van közötted, Izráel! Nem állhatsz meg a te ellenségeid előtt, míg el nem távolítjátok közületek az Istennek szentelt dolgot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'Azért jőjjetek elő reggel nemzetségeitek szerint; a nemzetség pedig, a melyet bűnösnek jelent az Úr, jőjjön elő családonként; a család pedig, a melyet bűnösnek jelent az Úr, jőjjön elő házanként, a ház pedig, a melyet bűnösnek jelent az Úr, jőjjön elő férfianként.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'És lészen, hogy a ki az Istennek szentelt dologban bűnösnek találtatik, tűzzel égettessék meg, ő és mindene, a mije van, mivelhogy megszegte az Úrnak szövetségét, és mivel alávaló dolgot cselekedett Izráelben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'Felkele azért Józsué és jó reggel előállítá Izráelt az ő nemzetségei szerint, és bűnösnek jelenteték a Júda nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'Ekkor előállítá a Júda családjait, és bűnösnek jelenteték a Zéra családja; azután előállítá a Zéra családját férfianként, és bűnösnek jelenteték a Zabdi háza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'És előállítá az ő házát férfianként, és bűnösnek találtaték Ákán, Kárminak fia, a ki Zabdi fia, a ki a Júda nemzetségéből való Zérának fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'Monda azért Józsué Ákánnak: Fiam, adj dicsőséget, kérlek, az Úrnak, Izráel Istenének, és tégy néki vallást, és add tudtomra, kérlek, nékem, mit cselekedtél, és el ne titkoljad tőlem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'Ákán pedig felele Józsuénak, és monda: Bizony én vétkeztem az Úr ellen, Izráel Istene ellen, és ezt s ezt cselekedtem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'Láték ugyanis a zsákmány közt egy jó babiloni köntöst, kétszáz siklus ezüstöt és egy arany vesszőt, a melynek súlya ötven siklus vala, és megkivántam ezeket, és elvevém ezeket, és ímé elrejtve vannak a földben, a sátoromnak közepében, az ezüst pedig alatta van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'Ekkor követeket külde Józsué s ezek a sátorba futának, és ímé, elrejtve vala az az ő sátorában, és az ezüst is alatta vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'Kivivék azért azokat a sátor közepéből, és vivék Józsuéhoz és Izráelnek minden fiához, és lerakák azokat az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'Józsué pedig fogá Ákánt, a Zéra fiát, az ezüstöt, a köntöst és az aranyvesszőt, az ő fiait és leányait, az ő ökreit, szamarait és juhait, sátorát és mindent, a mije vala, és vele lévén az egész Izráel is, vivék azokat Akor völgyébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'És monda Józsué: Miért rontottál meg minket? Rontson meg téged e napon az Úr! És elborítá őt egész Izráel kövekkel, és megégeték őket tűzzel, miután megkövezték vala őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'És nagy kőhalmot rakának feléje; megvan mind e napig. És megszűnék az Úr haragjának gerjedezése. Ezért nevezik ezt a helyet Akor völgyének mind e napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, 'És monda az Úr Józsuénak: Ne félj és ne rettegj! Vedd magadhoz mind a fegyverfogható népet, és kelj fel és menj fel Aiba, meglásd: kezedbe adom Ainak királyát és az ő népét, városát és földét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'Úgy cselekedjél Aival és az ő királyával, a mint cselekedtél Jérikhóval és az ő királyával; de zsákmányolni valóját és barmait magatoknak zsákmányolhatjátok! Vess lest a városnak, annak háta megett!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'Felkele azért Józsué és az egész fegyverfogható nép, hogy felmenjenek Aiba, és kiválaszta Józsué harminczezer erős férfiút és elküldé őket éjjel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'És parancsola nékik, mondván: Vigyázzatok! Ti lest vettek a városnak, a város háta megett; igen messzire ne menjetek a várostól, és mindnyájan készen legyetek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'Én pedig és az egész nép, a mely velem van, megközelítjük a várost. És ha kijönnek ellenünk, mint először, akkor megfutamodunk előttök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, 'És utánunk jönnek, mígnem elszakasztjuk őket a várostól, mert azt fogják mondani: Futnak előlünk, mint először. És a míg futunk előttök,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'Ti támadjatok elő a leshelyből, és foglaljátok el a várost, mert az Úr, a ti Istenetek adja azt a ti kezetekbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'És ha majd beveszitek a várost, gyújtsátok fel a várost tűzzel. Az Úrnak szava szerint cselekedjetek, vigyázzatok, megparancsoltam néktek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'Elküldé azért őket Józsué, és elmenének a leshelyre, és megszállának Béthel és Ai között, Aitól napnyugat felé; Józsué pedig ez éjszakán a nép között hála.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'És felkele Józsué, jó reggel, és megszemlélé a népet, és felméne ő és Izráelnek vénei a nép előtt Aiba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'És felméne a fegyverfogható nép is mind, a mely vele vala, és elközelítének és jutának a város elé, és táborba szállának Aitól északra, a völgy pedig köztök és Ai közt vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'És vőn mintegy ötezer férfiút, és lesbe állítá őket Béthel és Ai között a városnak nyugati részén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'Így állíták fel a népet, az egész tábort, a mely Aitól észak felé, utócsapatja pedig a várostól napnyugot felé vala. Józsué pedig beméne ez éjszakán a völgynek közepébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'És lőn, hogy mikor meglátta vala Ainak királya, sietve felkelének, és kijövének a város férfiai Izráel ellen a harczra; ő és egész népe a megszabott helyre, a síkság elejére, mert nem tudja vala, hogy lest vetének néki a város háta mögött.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'Józsué pedig és az egész Izráel mintha megverettek volna előttök futnak vala a puszta felé vivő úton.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'És felriasztaték az egész nép, a mely a városban vala, hogy üldözze őket. És üldözék Józsuét, és elszakadának a várostól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'És nem marada ember Aiban, sem Béthelben, a ki nem jött volna Izráel után, és ott hagyák a várost kinyitva, és üldözék Izráelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'Az Úr pedig monda Józsuénak: Emeld fel a kopját, a mely kezedben van, Ai felé, mert kezedbe adom azt. És felemelé Józsué a kopját, a mely kezében vala, a város felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'A lesben levők pedig nagy hamarsággal felkelének helyökről, és a mint felemelte vala kezét, futásnak eredének, és bemenének a városba, és bevevék azt, és nagy hamarsággal tűzbe boríták a várost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'Ai férfiai pedig hátratekintének, és láták, hogy ímé a városnak füstje felszáll vala az ég felé, és hogy nincsen módjukban imide vagy amoda elfutni, mert a nép, a mely fut vala a pusztának, visszafordul vala az üldöző felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'Józsué ugyanis és az egész Izráel látták vala, hogy a lesben levők bevették a várost, és hogy a városnak füstje felszállott vala: visszafordulának azért és vágák Ainak férfiait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'Amazok pedig a városból jövének ki ellenök, és így közben valának Izráelnek: ezek innen, amazok meg amonnan, és vágák őket mindaddig, a míg egy sem marada közülök élve, vagy a ki elszaladt volna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'Ainak királyát is elfogák élve, és elvivék őt Józsué elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'Mikor pedig leöldösé Izráel Ainak minden lakosát a mezőn, a pusztában, a hol üldözték vala őket, és mikor mindnyájan elhullottak vala az utolsóig fegyver éle alatt: visszafordula az egész Izráel Ai ellen, és vágá azt fegyver élével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'Mindazok pedig, a kik e napon elhullottak, férfiak és asszonyok együtt, tizenkét ezeren valának; Ainak minden embere.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'Józsué ugyanis nem voná vissza a kezét, a melyet a kopjával együtt felemelt vala, míglen megölék Ainak minden lakosát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'A barmot azonban és a mi zsákmányolni valója volt ennek a városnak, magának zsákmányolá el Izráel az Úr rendelete szerint. A mint utasította vala Józsuét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'Ait pedig felgyujtatá Józsué és tevé örökkévaló kőhalommá, pusztassággá mind e napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'Ainak királyát pedig felakasztá fára és ott vala estvéig; de naplementekor parancsolt Józsué, és levevék annak holttestét a fáról, és veték a város kapujának bejáratához, és nagy rakás követ hordának fölébe, mind e napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, 'Majd oltárt építe Józsué az Úrnak, Izráel Istenének Ebál hegyén,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, 'Miképen megparancsolta vala Mózes, az Úrnak szolgája Izráel fiainak, a mint meg van írva Mózes törvényének könyvében; oltárt ép kövekből, melyeket vas nem érintett és vivének arra egészen égőáldozatot az Úrnak, és áldozának hálaáldozatokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, 'És felírá ott kövekre a Mózes törvényének mását, a melyet az írt vala Izráel fiai elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'Az egész Izráel pedig és az ő vénei, vezérei és bírái ott álltak vala kétfelől a láda mellett, a Lévita-papok előtt, a kik az Úrnak frigyládáját hordozták vala, úgy a jövevény, mint a benszülött, fele a Garizim hegye felé, fele pedig Ebál hegye felé, a mint megparancsolta Mózes az Úr szolgája, hogy megáldaná az Izráel népét először.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, 'Azután pedig felolvasta a törvénynek minden ígéjét, az áldást és az átkot, mind úgy, a mint meg van írva a törvény könyvében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'Nem volt egy íge sem azok közül, a melyeket Mózes parancsolt vala, a melyet fel nem olvasott volna Józsué, az Izráelnek egész gyülekezete előtt, még az asszonyok, gyermekek, jövevények előtt is, a kik járnak vala közöttök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, 'Lőn pedig, hogy mikor ezt meghallották mind ama királyok, a kik a Jordánon túl a hegyeken és síkon és a nagy tengernek egész partja-mentén valának a Libánon ellenében: a Khittheus, az Emoreus, a Kananeus, a Perizeus, a Khivveus és a Jebuzeus:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'Egybegyülekezének, hogy megvívjanak Józsuéval és Izráellel egy akarattal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, 'De meghallák Gibeon lakosai is, a mit Józsué Jérikhóval és Aival cselekedett vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, 'És ők is ravaszul cselekedének. Elmenének ugyanis és követekül adák ki magokat. Szerzének azért szamaraikra ócska zsákokat, és ócska, megrepedezett és összekötözött boros tömlőket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, 'És ócska, megfoltozott sarukat lábaikra, és ócska ruhákat magokra; az útravaló kenyerök is mind száraz és penészes vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, 'Így menének el Józsuéhoz a táborba Gilgálba, és mondának néki, és Izráel férfiainak: Messze földről jöttünk, most azért kössetek frigyet mi velünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'Izráel férfiai pedig mondának a Khivveusnak: Hátha közöttem lakol te; hogyan kössek azért frigyet te veled?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, 'Azok pedig mondának Józsuénak: Szolgáid vagyunk mi! És monda nékik Józsué: Kik vagytok, és honnan jöttetek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, 'És mondának néki: Igen messze földről jöttek a te szolgáid, az Úrnak, a te Istenednek nevéért, mert hallottuk az ő hírét és mindazt, a mit Égyiptomban cselekedett;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'Mindazt is, a mit cselekedett az Emoreusok két királyával, a kik valának túl a Jordánon, Szíhonnal, Hesbon királyával és Óggal, Básán királyával, a ki Astarótban vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, 'Ezért szólának nékünk a mi véneink és földünk lakosai is mind, mondván: szerezzetek magatoknak eledelt az útra, és menjetek eléjök, és mondjátok nékik: Szolgáitok vagyunk mi, most azért kössetek frigyet mi velünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, 'Ez a mi kenyerünk meleg volt, a mikor eleségül elhoztuk a mi házainkból elindulván, hogy hozzátok jőjjünk; most ímé, száraz és penészes lett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'Ezek a boros tömlők is, a melyeket új korukban töltöttünk vala meg, íme, de megszakadoztak; e mi ruháink és saruink pedig megavultak az útnak igen hosszú volta miatt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, 'És vőnek a férfiak azoknak eledeléből, az Úr tanácsát pedig nem kérték vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'És békességesen bánt velök Józsué, és frigyet köte velök, hogy életben hagyja őket, a gyülekezet fejedelmei pedig megesküdének nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, 'De harmadnap múlva azután, hogy frigyet kötöttek vala velök, meghallják, hogy közel valók azok hozzájok, sőt közöttök lakoznak azok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'Elindulának azért Izráel fiai, és eljutának azoknak városaihoz harmadnapon. Városaik pedig valának: Gibeon, Kefira, Beéróth és Kirjáth-Jeárim.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, 'De nem bánták őket Izráel fiai, mivelhogy megesküdtek vala nékik a gyülekezet főemberei az Úrra, Izráel Istenére, és zúgolódék az egész gyülekezet a főemberek ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, 'Mondának azért mind a főemberek az egész gyülekezetnek: Mi megesküdtünk nékik az Úrra, Izráel Istenére, most hát nem bánthatjuk őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, 'Ezt cselekedjük velök, hogy életben hagyjuk őket, és így nem lesz harag ellenünk az esküvésért, a melylyel megesküdtünk nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, 'Mondának azért a főemberek nékik: Ám éljenek! És lőnek favágóivá és vízhordozóivá az egész gyülekezetnek, a mint szólottak vala nékik a főemberek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'Hívatá ugyanis őket Józsué, és szóla nékik, mondván: Miért csaltatok meg minket, ezt mondván: Igen messziről valók vagyunk mi tőletek, holott ti közöttünk laktok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, 'Most azért átkozottak legyetek, és ne fogyjon ki közületek a szolga, a favágó és vízhordó az én Istenemnek házába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, 'Azok pedig felelének Józsuénak, és mondának: Mivelhogy nyilván tudtokra esett a te szolgáidnak az, a mit az Úr, a ti Istenetek parancsolt vala Mózesnek, az ő szolgájának, hogy néktek adja ezt az egész földet, és hogy kiirtja előletek a földnek minden lakosát: igen féltettük tőletek a mi életünket, ezért cselekedtük ezt a dolgot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, 'És most ímé, a te kezedben vagyunk, a mint cselekedni jónak és igaznak tetszik előtted, úgy cselekedjél mivelünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'És úgy cselekedék velök, és kiszabadítá őket Izráel fiainak kezéből, és nem ölék meg őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'És tevé őket Józsué azon a napon favágókká és vízhordókká a gyülekezethez és az Úr oltárához, mind e napig, azon a helyen, a melyet választánd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'Lőn pedig, hogy a mikor meghallá Adonisédek, Jeruzsálemnek királya, hogy bevette vala Józsué Ait, és elpusztította azt, és hogy a mint cselekedett vala Jérikhóval és annak királyával, úgy cselekedett Aival és annak királyával, és hogy békességre léptek Gibeon lakói Izráellel, és közöttük vannak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'Igen megijedének, mivelhogy nagy város vala Gibeon, olyan mint egy a királyi városok közül, sőt nagyobb vala az Ainál, férfiai pedig mind vitézek valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'Külde azért Adonisédek, Jeruzsálemnek királya Hohámhoz, Hebronnak királyához és Pireámhoz Jármutnak királyához és Jáfiához, Lákisnak királyához és Debirhez, Eglonnak királyához, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, 'Jőjjetek fel hozzám, és segéljetek meg engem, és verjük meg Gibeont, mert békességre lépett Józsuéval és Izráel fiaival!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'Összegyülének azért, és felméne az Emoreusoknak öt királya: Jeruzsálemnek királya, Hebronnak királya, Jármutnak királya, Lákisnak királya, Eglonnak királya, ők magok és minden seregök, és tábort ütének Gibeonnál, és hadakozának ellene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'Küldének azért Gibeon férfiai Józsuéhoz a táborba, Gilgálba, mondván: Ne vond meg kezeidet a te szolgáidtól! Jőjj fel hozzánk hamar és ments meg minket, és segíts rajtunk, mert mind felgyűltek ellenünk az Emoreusok királyai, a kik a hegyen lakoznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'Felméne azért Józsué Gilgálból, ő maga és az egész hadakozó nép vele, és a seregnek minden vitéze.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, 'Monda pedig az Úr Józsuénak: Ne félj tőlök, mert kezedbe adtam őket; senki sem áll meg közülök előtted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'És rájok töre Józsué nagy hirtelen, miután egész éjszaka ment vala Gilgálból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'És megrettenté őket az Úr Izráel előtt, és megveré őket Gibeonnál nagy vereséggel, és űzé őket a Bethoronba vivő úton, és vágá őket egészen Azekáig és Makkedáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'Mikor pedig futnak vala ők Izráel előtt a bethoroni lejtőn, az Úr nagy köveket hullata rájok az égből egész Azekáig, és meghalának. Többen valának, a kik a jégeső kövei miatt haltak vala meg, mint azok, a kiket fegyverrel öltek meg Izráel fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'Akkor szóla Józsué az Úrnak azon a napon, a melyen odavetette az Úr az Emoreust Izráel fiai elé; ezt mondotta vala pedig Izráel szemei előtt: Állj meg nap, Gibeonban, és hold az Ajalon völgyében!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'És megálla a nap, és vesztegle a hold is, a míg bosszút álla a nép az ő ellenségein. Avagy nincsen-é ez megírva a Jásár könyvében? És megálla a nap az égnek közepén és nem sietett lenyugodni majdnem teljes egy napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'És nem volt olyan nap, mint ez, sem annakelőtte, sem annakutána, hogy ember szavának engedett volna az Úr, mert az Úr hadakozik vala Izráelért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, 'Ezután visszatére Józsué és vele az egész Izráel a táborba, Gilgálba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'Ez az öt király pedig elfutott vala, és elrejtőzék Makkedában a barlangban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'És megizenék ezt Józsuénak, mondván: Megtaláltatott az öt király, elrejtőzve a makkedai barlangban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'És monda Józsué: Hengergessetek nagy köveket a barlang szájához és rendeljetek mellé férfiakat, hogy őrizzék őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'Ti pedig meg ne álljatok, nyomuljatok ellenségeitek után és vágjátok utócsapataikat, és ne engedjétek őket bejutni az ő városaikba, mert kezetekbe adta őket az Úr, a ti Istenetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'Minekutána pedig elvégezték Józsué és Izráelnek fiai azoknak igen nagy vereséggel való verését, egészen azok megsemmisítéséig, és az élvemaradtak a megerősített városokba vonultak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'Visszatére az egész nép Józsuéhoz a táborba, Makkedába békességgel; nyelvét se mozdította senki Izráel fiai ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'És monda Józsué: Nyissátok fel a barlang száját, és hozzátok ki hozzám ezt az öt királyt a barlangból!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'És akképen cselekedének, és kihozák hozzá a barlangból ezt az öt királyt: Jeruzsálem királyát, Hebron királyát, Jármut királyát, Lákis királyát, Eglon királyát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'Mikor pedig kihozták vala ezt az öt királyt Józsuéhoz, előhívatá Józsué Izráelnek minden férfiát, és monda a hadakozó nép vezéreinek, a kik vele mentek vala: Jőjjetek elő, tegyétek lábaitokat e királyoknak nyakára. Eljövének azért és tevék lábaikat azoknak nyakára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'És monda nékik Józsué: Ne féljetek, és meg ne rettenjetek; legyetek bátrak és erősek, mert ekképen cselekszik az Úr minden ellenségetekkel, a kik ellen ti hadakoztok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'Azután pedig megveré őket Józsué, és megölé őket, és felakasztatá őket öt fára, és felakasztva maradtak a fákon mind estvéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'Lőn pedig a nap lementének idején, parancsola Józsué, és levevék őket a fákról, és behányák őket a barlangba, a melyben elbújtak vala, és nagy köveket rakának a barlang szája elé, mind e napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'Makkedát is bevevé Józsué ugyanazon a napon, és fegyver élére hányá azt és annak királyát, és megölé őket és egy lelket sem engedett menekülni azokból, a melyek benne valának. Úgy cselekedék Makkedának királyával, a mint cselekedett vala Jérikhónak királyával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'Általméne annakutána Józsué és vele az egész Izráel Makkedából Libnába, és hadakozék Libnával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'És kezébe adá az Úr azt is Izráelnek, és annak királyát; és fegyver élére hányá azt, és egy lelket sem engede menekülni azokból a melyek benne valának. És úgy cselekedék annak királyával, a mint cselekedett vala Jérikhónak királyával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'Libnából pedig általméne Józsué és vele az egész Izráel Lákisba, és táborba szálla mellette, és hadakozék ellene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'És kezébe adá az Úr Izráelnek Lákist és bevevé azt másodnapon, és fegyver élére hányá azt, és minden lelket, a mely benne vala, egészen úgy, amint cselekedett vala Libnával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'Akkor feljöve Hórám, Gézernek királya, hogy megsegélje Lákist, de megveré Józsué őt és az ő népét annyira, hogy egy menekülőt sem hagya meg néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'Lákisból pedig általméne Józsué és vele az egész Izráel Eglonba, és táborba szállának ellene, és hadakozának ellene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'És bevevék azt ugyanazon a napon, és fegyver élére hányák azt; és megöle minden lelket, a mely benne vala, ugyanazon a napon, egészen úgy, amint cselekedett vala Lákissal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'Felméne azután Józsué Eglonból és ő vele az egész Izráel Hebronba, és hadakozának az ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'És bevevék azt, és fegyver élére hányák azt, és annak királyát és minden városát, és egy lelket sem engede menekülni azokból, a melyek benne valának, egészen úgy, a mint cselekedett vala Eglonnal, elvesztvén azt és minden lelket, a mely benne vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'Fordula azután Józsué, és vele az egész Izráel Debirnek, és hadakozék az ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'És bevevé azt és annak királyát és minden városát, és fegyver élére hányá őket, és megölének minden lelket, a mely benne vala, nem hagyott menekülni valót. A miképen cselekedett vala Hebronnal, úgy cselekedék Debirrel és annak királyával, avagy a miképen Libnával és annak királyával cselekedett vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'Megveré azért Józsué az egész földet; a hegységet és a déli vidéket, a síkságot és a lejtőket és mindazoknak királyait, menekülni valót sem hagyott; és megöle minden élőt, a mint megparancsolta vala az Úr, az Izráelnek Istene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'Megveré pedig őket Józsué Kádes Barneától fogva egész Gázáig, a Gósennek is minden földét, egész Gibeonig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'És mindezeket a királyokat és azoknak földjét egy útban hódítá meg Józsué, mivelhogy az Úr, Izráelnek Istene hadakozott vala Izráelért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'Azután visszatére Józsué és vele az egész Izráel a táborba, Gilgálba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'Mikor pedig meghallotta ezt Jábin, Hásornak királya, külde Jobábhoz, Mádonnak királyához, és Simronnak királyához, és Aksáfnak királyához,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'És azokhoz a királyokhoz, a kik laknak vala észak felé a hegységben, és a pusztában Kinneróttól délre, és a síkságon, és Dór magaslatain a tenger felé;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'A Kananeushoz napkelet és napnyugat felé, és az Emoreushoz, a Khittheushoz, a Perizeushoz, a Jebuzeushoz a hegyek közé, és a Khivveushoz a Hermon alá, Mispának földére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'És kijövének ők és velök az ő egész táboruk, sok nép, olyan sok, mint a fövény, a mely a tenger partján van, és igen sok ló és szekér.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'És összegyülének mindezek a királyok, és megindulának, és táborba szállának együttesen Méromnak vizeinél, hogy hadakozzanak Izráel ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'Ekkor monda az Úr Józsuénak: Ne félj tőlök, mert holnap ilyenkorra mindnyájokat átdöfötten vetem az Izráel elé; lovaikat bénítsd meg, szekereiket pedig égesd meg tűzzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'Elméne azért Józsué és vele az egész hadakozó nép azok ellen a Mérom vizeihez nagy hirtelen, és reájok rohanának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'És adá őket az Úr Izráelnek kezébe, és verék őket és űzék őket egészen a nagy Sidonig és Miszrefót-Majimig, és Mispának völgyéig napkelet felé, és leverék őket annyira, hogy senki sem maradt közülök életben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'És úgy cselekedék velök Józsué, a mint megmondotta vala néki az Úr: az ő lovaikat megbénítá, szekereiket pedig tűzzel égeté el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'Majd visszafordula Józsué ugyanazon időben és bevevé Hásort, királyát pedig fegyverrel megölé (Hásor ugyanis mindezeknek az országoknak feje volt az előtt);');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'És levágának minden lelket, a mely benne vala, megölvén őket fegyver élével; nem maradt meg egy élő sem; Hásort pedig tűzzel égeté meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'És e királyoknak minden városát és minden királyukat is meghódoltatá Józsué, és megölé őket fegyver élével, kipusztítván őket, a mint megparancsolta vala Mózes, az Úrnak szolgája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'Csak épen azokat a városokat nem égeté meg Izráel, a melyek halmokon állottak vala, kivéve Hásort, egyedül ezt égeté meg Józsué.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'És e városoknak minden zsákmányolni valóját, és a barmokat is magoknak zsákmányolák el Izráel fiai; csak az embereket hányák mind fegyver élére, míglen kipusztíták őket. Nem hagytak meg egy élőt sem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'A mint parancsolt az Úr Mózesnek, az ő szolgájának, úgy parancsolt Mózes Józsuénak, és úgy cselekedék Józsué, semmit el nem hagyott mindabból, a mit az Úr parancsolt vala Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'És elfoglalá Józsué mindazt a földet, a hegységet, az egész déli vidéket, az egész Gósen földét, úgy a síkságot, mint a pusztát, és Izráel hegyét és annak síkságát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'A kopasz hegytől fogva, a mely Szeír felé emelkedik, egészen Baál-Gádig, a Libanon völgyében, a Hermon hegye alatt; királyaikat pedig mind elfogá és megveré és megölé őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'Sok napon át viselt hadat Józsué mindezekkel a királyokkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'Nem volt város, a mely békességre lépett volna Izráel fiaival, kivéve a Gibeonban lakó Khivveusokat; haddal vették azt meg mind.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'Mert az Úrtól volt az, hogy megkeményítvén szíveiket, haddal menjenek Izráel ellen, hogy eltörölje őket; hogy ne legyen nékik irgalom, hanem hogy elpusztítsa őket, a mint megparancsolta vala az Úr Mózesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'Majd elméne Józsué ez időben, és kiirtá az Anákokat a hegyek közül Hebronból, Debirből, Anábból és Júdának minden hegyéből, és Izráelnek minden hegyéből; városaikkal együtt törlé el őket Józsué.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'Nem maradtak Anákok Izráel fiainak földén, csak Gázában, Gáthban és Asdódban hagyattak meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'Elfoglalá azért Józsué az egész földet egészen úgy, a mint az Úr mondotta vala Mózesnek, és adá azt Józsué örökségül Izráelnek, osztályrészeikhez képest, nemzetségeik szerint. A föld pedig megnyugovék a harcztól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, 'Ezek pedig ama földnek királyai, a kiket levertek Izráelnek fiai, és a kiknek földjét birtokba vették a Jordánon túl, napkelet felé, az Arnon pataktól fogva a Hermon hegyéig, és az egész mezőséget kelet felől:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'Szíhon, az Emoreusok királya, a ki lakik vala Hesbonban, a ki uralkodik vala Aróertől fogva, a mely van az Arnon patak partján, és a patak közepétől és a Gileád felétől a Jabbok patakig, az Ammon fiainak határáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'És a mezőségtől a Kinneróth tengerig napkelet felé, és a puszta tengeréig, a Sóstengerig napkelet felé, a Béth-Jesimothi útig, és délfelé a Piszga hegyoldalainak aljáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, 'És Ógnak, a Básán királyának tartománya, a ki Refaim maradékai közül való, a ki Astarotban és Edreiben lakozik vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'És uralkodik vala Hermon hegyén, Szalkhában és az egész Básánban, a Gesurnak és Maakhátnak határáig, és a fél Gileádon, Szíhonnak, Hesbon királyának határáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'Mózes, az Úrnak szolgája és Izráelnek fiai verték le őket, és oda adta azt a földet Mózes, az Úrnak szolgája örökségül a Rúben és Gád nemzetségeknek és a Manassé nemzetség felének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'Ezek pedig ama földnek királyai, a kiket levertek vala Józsué és az Izráelnek fiai a Jordán másik oldalán napnyugat felé, Baál-Gádtól fogva, a mely van a Libánon völgyében, egészen a kopasz hegyig, a mely Szeír felé emelkedik. És oda adá azt Józsué örökségül az Izráel nemzetségeinek, az ő osztályrészeik szerint:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'A hegységben és a síkságon, a mezőségen és a hegyoldalakon, a pusztán és a déli vidéken, a Khittheus, Emoreus, Kananeus, Perizeus, Khivveus és Jebuzeusok földjét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'Jérikhónak királya egy; Ainak, a mely oldalra vala Béthel felé, királya egy;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'Jeruzsálemnek királya egy, Hebronnak királya egy;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'Jármutnak királya egy, Lákisnak királya egy;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'Eglonnak királya egy, Gézernek királya egy;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'Debirnek királya egy, Gédernek királya egy;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'Hormáhnak királya egy, Aradnak királya egy;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'Libnának királya egy; Adullámnak királya egy;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'Makkedának királya egy, Béthelnek királya egy;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'Tappuáhnak királya egy, Héfernek királya egy;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'Afeknek királya egy, Lassáronnak királya egy;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'Mádonnak királya egy, Hásornak királya egy;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'Simron Meronnak királya egy, Aksáfnak királya egy;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'Taanáknak királya egy, Megiddónak királya egy;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'Kedesnek királya egy, a Kármelen levő Jokneámnak királya egy;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'A Dór magaslatán levő Dórnak királya egy, a Gilgál népeinek királya egy;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'Tirczának királya egy; összesen harminczegy király.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'Mikor Józsué megvénhedett és igen megidősödött vala, monda az Úr néki: Te megvénhedtél, igen megidősödtél, pedig még igen sok föld maradt elfoglalni való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'Ez az a föld, a mi fennmaradt: A Filiszteusoknak minden tartománya és az egész Gesur.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'A Sikhórtól fogva, a mely Égyiptom felett foly, egészen Ekronnak határáig északra, mely a Kananeushoz számíttatik; a Filiszteusok öt fejedelemsége: a Gázáé, Asdódé, Askelóné, Gáthé, Ekroné és az Avveusoké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'Délről a Kananeusnak egész földe és Meára, a mely a Sídonbelieké, Afékáig, az Emoreusok határáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'Továbbá a Gibli földe és az egész Libanon napkelet felé, Baál-Gádtól fogva, a mely a Hermon hegy alatt van, egészen addig, a hol Hamáthba mennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'A hegységnek minden lakosát a Libanontól Miszrefóth-Majimig, a Sídoniakat mind, magam űzöm ki őket Izráel fiai elől, csak sorsold ki Izráelnek örökségül, a mint megparancsoltam néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'Mostan azért oszd el ezt a földet örökségül kilencz nemzetségnek, és a Manassé nemzetség felének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'Ő vele együtt a Rúben és Gád nemzetségek elvették örökségöket, a melyet adott vala nékik Mózes, túl a Jordánon, napkelet felé, a miképen adta vala nékik Mózes, az Úrnak szolgája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'Aróertől fogva, a mely az Arnon patak partján van, úgy a várost, a mely a völgynek közepette van, mint Medebának minden sík földét Dibonig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'És minden városát Szíhonnak, az Emoreusok királyának, a ki uralkodik vala Hesbonban, az Ammon fiainak határáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'És Gileádot és Gesurnak és Maakátnak határát, az egész Hermon hegyet és az egész Básánt Szalkáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'Básánban Ógnak egész országát, a ki uralkodik vala Astarótban és Edreiben. Ez maradt vala meg a Refaim maradékai közül, de leveré és kiűzé őket Mózes.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, 'De Izráel fiai nem űzék ki a Gesurit és a Maakhátit, és ott is lakik a Gesuri és Maakháti az Izráel között mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'Csak Lévi nemzetségének nem adott örökséget; az Úrnak, Izráel Istenének tüzes áldozatai az ő öröksége, a mint szólott vala néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'Adott vala pedig Mózes örökséget a Rúben fiai nemzetségének az ő családjaik szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'És lőn az ő határuk Aróertől fogva, a mely az Arnon folyó partján van, úgy a város, a mely a völgy közepette van, mint az egész sík föld Medeba mellett;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'Hesbon és annak minden városa, a melyek a sík földön vannak; Dibon, Bámoth-Baal és Béth-Baál-Meon;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'És Jahcza, Kedemót és Méfaát;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'És Kirjáthaim, Szibma és Czeret-Sáhár a völgy mellett való hegyen:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'És Béth-Peór, a Piszga hegyoldalai, és Béth-Jesimóth.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'És a sík föld minden városa és Szíhonnak, az Emoreusok királyának egész országa, a ki uralkodik vala Hesbonban, a kit megvert vala Mózes, őt és a Midiánnak fejedelmeit: Evit és Rékemet, Czúrt és Húrt és Rébát, Szíhonnak fejedelmeit, a kik e földön laktak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'A jövendőmondó Bálámot is, Beórnak fiát, megölék Izráel fiai fegyverrel, azokkal együtt, a kiket levágtak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'Vala tehát a Rúben fiainak határa a Jordán és melléke. Ez a Rúben fiainak öröksége az ő családjaik szerint, a városok és azoknak falui.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'A Gád nemzetségének, a Gád fiainak is adott vala örökséget Mózes, az ő családjaik szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'És lőn az ő határuk Jaázer és Gileádnak minden városa és az Ammon fiai földjének fele Aróerig, a mely Rabba felett van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'És Hesbontól fogva Ramath-Miczpéig és Betónimig, meg Mahanáimtól Debir határáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'A völgyben pedig Béth-Harám, Béth-Nimra, Szukkóth és Czáfon, Szíhonnak, Hesbon királyának maradék országa, a Jordán és melléke, a Kinnereth tenger széléig a Jordánon túl napkelet felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'Ez a Gád fiainak örökségök, az ő családjaik szerint, a városok és azoknak falui.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'A Manassé nemzetség felének is adott vala Mózes örökséget. És lőn a Manassé fiainak félágáé, az ő családjaik szerint;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'És lőn az ő határuk: Mahanáimtól fogva az egész Básán, Ógnak, Básán királyának egész országa és Jairnak minden faluja, a melyek Básánban vannak, hatvan város.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'És pedig Gileádnak fele és Astarót és Edrei, Óg országának városai Básánban, a Manassé fiának, Mákirnak fiaié, Mákir feléé, az ő családjaik szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'Ezek azok, a miket örökségül adott vala Mózes a Moáb mezőségén, a Jordánon túl Jérikhótól napkelet felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, 'A Lévi nemzetségének pedig nem adott vala Mózes örökséget. Az Úr, Izráelnek Istene az ő örökségök, a mint szólott vala nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'Ezek pedig azok, a miket örökségül vőnek el Izráel fiai a Kanaán földén, a miket örökségül adtak nékik Eleázár, a pap, Józsué, a Nún fia és az atyai fejedelmek, a kik valának Izráel fiainak nemzetségei felett;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'Sorsvetés által való örökségökül, (a mint megparancsolta vala az Úr Mózes által) a kilencz nemzetségnek és a félnemzetségnek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'Mert két nemzetségnek és fél nemzetségnek a Jordánon túl adott vala Mózes örökséget, a Lévitáknak pedig nem adott vala örökséget ő közöttök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'Mert a József fiai két nemzetség voltak: Manassé és Efraim; a Lévitáknak pedig nem adtak osztályrészt a földből, hanem csak városokat lakásul és az azokhoz való legelőket barmaik és marháik számára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'A mint megparancsolta vala az Úr Mózesnek, úgy cselekedének az Izráel fiai, és úgy oszták fel a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'Hozzámenének pedig Józsuéhoz Júdának fiai Gilgálba és monda néki a Kenizeus Káleb, Jefunné fia: Te tudod azt a dolgot, a melyet beszélt vala az Úr Mózesnek, az Isten emberének én felőlem és te felőled Kádes-Barneában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'Negyven esztendős valék én, mikor elküldött engem Mózes az Úrnak szolgája Kádes-Barneából, hogy kikémleljem a földet, és úgy hoztam néki hírt, a mint az én szívemben vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'Atyámfiai pedig, a kik feljöttek vala velem, elrémítették a népnek szívét, de én tökéletesen követtem az Urat, az én Istenemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'És megesküvék Mózes azon a napon, mondván: Bizony a föld, a melyet megtapodott a te lábad, tiéd lesz örökségül, és a te fiaidé mind örökké, mivelhogy tökéletesen követted az Urat, az én Istenemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'Most pedig, ímé megtartott engem az Úr életben, a mint szólott vala; most negyvenöt esztendeje, a mióta szólott vala az Úr e dologról Mózesnek, a mi alatt Izráel a pusztában bolyongott vala; és most ímé, nyolczvanöt esztendős vagyok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'Még ma is olyan erős vagyok, a milyen azon a napon voltam, a mikor elküldött engem Mózes; a milyen akkor volt az én erőm, most is olyan az én erőm a harczoláshoz és járásra-kelésre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'Most azért add nékem ezt a hegyet, a melyről szólt vala az Úr azon a napon; mert magad is hallottad azon a napon, hogy Anákok vannak ott, és nagy, erősített városok; hátha velem lesz az Úr, és kiűzöm őket, a mint megmondotta az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'És megáldá őt Józsué, és odaadá Hebront Kálebnek, a Jefunné fiának örökségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'Azért lőn Hebron a Kenizeus Kálebé, a Jefunné fiáé, örökségül mind e mai napig, a miért hogy tökéletesen követte vala az Urat, Izráelnek Istenét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'A Hebron neve pedig annakelőtte Kirjáth-Arba volt; a ki a legnagyobb ember volt az Anákok között. A föld pedig megnyugodott a harcztól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'A Júda fiai nemzetségének sors által való része pedig az ő családjaik szerint ez vala: Edomnak határa felé a Czin pusztája délre, a déli határnak végén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'Vala pedig az ő déli határuk a Sóstengernek szélétől, a tengernyelvtől fogva, a mely délfelé fordul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'És halad délre az Akrabbim hágónak, majd átmegy Czin felé, és felmegy délről Kádes-Barneának, átmegy Hesronnak, felmegy Adárnak és kerül Karka felé;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'Majd átmegy Asmonnak és halad Égyiptom patakának. A határ szélei pedig a tengernél vannak. Ez a ti határotok délre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'Napkelet felé pedig a Sóstenger a határ a Jordán végéig; az északi rész határa pedig a tengernyelvtől, a Jordán végétől kezdődik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'És felmegy ez a határ Béth-Hoglának, és átmegy északra Béth-Arabán majd felmegy ez a határ Rúben fiának, Bohánnak kövéhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'És felmegy ez a határ Debirbe is az Akor völgyéből, és északnak fordul Gilgál felé, a mely átellenében van az Adummim hágójának, a mely a pataktól délfelé esik. És átmegy a határ az Én-semes vizeire és tova halad a Rógel forrása felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, 'Azután felmegy a határ a Hinnom fiának völgyén, Jebuzeusnak, azaz Jeruzsálemnek déli oldala felé; felmegy továbbá e határ a hegynek tetejére, a mely átellenben van a Hinnom völgyével napnyugat felé, a mely északra van a Refaim völgyének szélén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'És hajlik e határ a hegynek tetejétől a Neftoáh víznek kútfejéhez és kimegy az Efron hegyének városai felé; majd hajlik e határ Baalának, azaz Kirjáth-Jeárimnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'Baalától pedig fordul e határ napnyugotnak a Szeír-hegy felé, és átmegy északnak a Jeárim-hegy oldala felé, azaz Kesalon felé és alámegy Béth-Semesnek és átmegy Timnának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'Majd tova megy e határ Ekron északi oldala felé, és hajlik e határ Sikkeronnak, és átmegy a Baala hegynek, és tova megy Jabnéel felé. A határ szélei pedig a tengernél vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'A napnyugati határ pedig a nagy tenger és melléke. Ez Júda fiainak határa köröskörül az ő házoknépe szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'Kálebnek, a Jefunné fiának pedig a Júda fiai között ada részt, az Úrnak Józsuéhoz való szavai szerint; Kirjáth-Arbának, Anák atyjának városát, azaz Hebront.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'És kiűzé onnan Káleb Anáknak három fiát: Sésait, Ahimánt és Tálmait, Anák gyermekeit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'És felméne innét Debir lakói ellen, Debirnek neve pedig azelőtt Kirjáth-Széfer volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'És monda Káleb: A ki megveri Kirjáth-Széfert és elfoglalja azt, néki adom Akszát, az én leányomat feleségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'Elfoglala pedig azt Othniél, Kénáznak, a Káleb testvérének fia; és néki adá Akszát, az ő leányát feleségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'És lőn, hogy a mikor eljöve az, biztatá őt, hogy kérjen az ő atyjától mezőt. Leszálla azért a szamárról; Káleb pedig monda néki: Mi bajod?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, 'Ő pedig monda: Adj áldást nékem! Mivelhogy száraz földre helyeztél engem, adj azért nékem vízforrásokat is. És néki adá a felső forrást és az alsó forrást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'Ez a Júda fiai nemzetségének öröksége az ő családjaik szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'A Júda fiai nemzetségének városai pedig a déli végtől kezdve Edom határa felé valának: Kabseél, Éder és Jágur;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'Kina, Dimóna és Adada;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'Kedes, Hásor és Ithnán;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'Zif, Télem és Bealóth;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'Hásor-Hadatha és Kerioth-Hesron, azaz Hásor;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'Amam, Séma és Móláda;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'Hasar-Gaddah, Hesmón és Béth-Pelet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'Hasar-Suál, Beer-Seba és Bizjotheja;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'Baála, Ijjim és Eczem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'Elthólád, Keszil és Hormah;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'Siklág, Madmanna és Szanszanna;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'Lebaóth, Silhim, Ain és Rimmon. Összesen huszonkilencz város és ezek falui.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, 'A síkságon: Esthaól, Czórah és Asnáh;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'Zanoah, Én-Gannim, Tappuáh és Énám;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'Jármut, Adullám, Szókó és Azéka;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'Saáraim, Adithaim, Gedéra és Gederóthaim. Tizennégy város és azok falui.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'Senán, Hadása és Migdal-Gad;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'Dilán, Miczpe és Jokteél;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'Lákis, Boczkát és Eglon;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'Kabbon, Lahmász és Kitlis;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'Gedéróth, Béth-Dágon, Naama és Makkéda. Tizenhat város és ezeknek falui.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'Libna, Ether és Asán;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'Jifta, Asná és Neczib;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'Keila, Akzib és Marésa. Kilencz város és ezeknek falui.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'Ekron, ennek mezővárosai és falui.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'Ekrontól fogva egész a tengerig mind azok, a melyek Asdód mellett vannak, és azoknak falui.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'Asdód, ennek mezővárosai és falui; Gáza, ennek mezővárosai és falui; Égyiptom patakjáig, és a nagy tenger és melléke.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, 'A hegységen pedig: Sámír, Jathír és Szókó;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'Danna, Kirjáth-Szanna, azaz Debir;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'Anáb, Estemót és Anim;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'Gósen, Hólon és Giló. Tizenegy város és ezeknek falui.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'Aráb, Dúma és Esán;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'Janum, Béth-Tappuah és Aféka;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'Humta, Kirjáth-Arba, azaz Hebron és Czihor. Kilencz város és ezeknek falui.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'Maón, Karmel, Zif és Júta;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'Jezréel, Jokdeám és Zánoah;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'Kajin, Gibea és Timna. Tíz város és ezeknek falui.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'Halhul, Béth-Czúr és Gedor;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'Maarát, Béth-Anóth és Elthekon. Hat város és ezeknek falui.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'Kirjáth-Baál, azaz Kirjáth-Jeárim, és Rabba. Két város és ezeknek falui.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, 'A pusztában: Béth-Arábá, Middin és Szekáka;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'Nibsán, Ir-Melah és Én-Gedi. Hat város és ezeknek falui.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'De a Jebuzeusokat, Jeruzsálemnek lakóit, Júda fiai nem bírták kiűzni, azért laknak ott a Jebuzeusok Júda fiaival együtt Jeruzsálemben, mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'A József fiainak sors által való része pedig juta a jérikhói Jordántól fogva, Jérikhó vizei felé napkeletnek a pusztára, a mely felmegy Jérikhótól a Béthel hegyének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'És tovamegy Béthelből Lúzba, és átmegy az Arkiták határára, Ataróthra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'Majd lemegy a tenger felé a Jafleteus határának, az alsó Bethoronnak határáig és Gézerig, a szélei pedig a tengernél vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'Elvevék azért az ő örökségöket Józsefnek fiai: Manassé és Efraim.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'Efraim fiainak határa is az ő családjaik szerint vala, és pedig az ő örökségöknek határa napkelet felé, Atróth-Adártól felső Bethoronig vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'És kimegy a határ a tengerre; Mikhmethattól észak felé, és fordul a határ kelet felé Thaanath-Silónak és átmegy azon napkelet felé Janoáhnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'Janoáhtól pedig lemegy Ataróthba és Naaróthba, és éri Jérikhót, és kimegy a Jordánnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'Tappuahtól tovamegy a határ a tenger felé a Kána patakjának, a szélei pedig a tengernél vannak. Ez az Efraim fiai nemzetségének öröksége az ő családjaik szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'És a városok, a melyek kiválasztattak Efraim fiai számára a Manassé fiai örökségének közepette, mind e városok és ezeknek falui.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'De ki nem űzék a Kananeust, a ki lakik vala Gézerben; azért ott lakik a Kananeus az Efraim között mind e napig, és lőn robotos szolgává.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'Lőn sors által való része Manassé nemzetségének is, mert ő vala elsőszülötte Józsefnek, Mákirnak, a Manassé elsőszülöttének, Gileád atyjának, mivelhogy hadakozó férfiú vala, juta néki Gileád és Básán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'Manassé többi fiainak is juta az ő családjaik szerint: Abiézer fiainak, Hélek fiainak, Aszriél fiainak, Sekem fiainak, Héfer fiainak és Sémida fiainak. Ezek Manassénak a József fiának fiúgyermekei, az ő családjaik szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'De Czélofhádnak, Héfer fiának (ez Gileád fia, ez Mákir fia, ez Manassé fia) nem valának fiai, hanem csak leányai. Ezek valának pedig leányainak nevei: Makhla, Nóa, Khogla, Milkha és Thircza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'Ezek odajárulának Eleázár pap elé, Józsuénak, a Nún fiának eleibe és a fejedelmek elé, mondván: Az Úr megparancsolta Mózesnek, hogy örökséget adjon nékünk a mi atyánkfiai között. Adott vala azért nékik örökséget az Úr beszéde szerint, az ő atyjoknak bátyjai között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'Tíz rész esék azért Manassénak, Gileád és Básán földén kívül, a melyek túl vannak a Jordánon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'Mert a Manassé leányai örökséget kaptak az ő fiai között; Gileád földe pedig a Manassé többi fiaié lőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'A Manassé határa pedig Ásertől Mikmetháth felé vala, a mely Sikem előtt van. És méne a határ jobbkéz felé, Én-Tappuahnak lakói felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, 'Manasséé volt Tappuah földe, de Tappuah a Manassé határa felé az Efraim fiaié vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'És alámegy a határ a Kána patakjára, a pataknak déli részére. Ezek a városok Efraiméi a Manassé városai között. Manassé határa pedig a pataktól észak felé és a széle a tengernél vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'Délről Efraimé, északról pedig Manasséé, és ennek határa a tenger vala. De észak felől Áserbe ütköznek, napkelet felől pedig Issakhárba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'És a Manasséé vala Issakhárban és Áserben: Béth-Seán és mezővárosai, Jibleám és mezővárosai, Dórnak lakosai és mezővárosai, Én-Dórnak lakosai és mezővárosai, Thaanaknak lakosai és mezővárosai, és Megiddó lakosai és mezővárosai, három hegyi tartomány.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'De nem bírták elfoglalni Manassénak fiai ezeket a városokat, és sikerült a Kananeusnak ott maradni azon a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'De mihelyt megerősödtek vala Izráel fiai, robot alá veték a Kananeust, de teljességgel nem űzék ki őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'József fiai pedig szóltak vala Józsuéval, mondván: Miért adtál nékem egy sors szerint való örökséget és egy osztályrészt, holott én sok nép vagyok, mivelhogy ez ideig megáldott engem az Úr?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'Józsué pedig monda nékik: Ha sok nép vagy te, menj fel az erdőre, és írts ott magadnak a Perizzeusoknak és Refaimnak földén, ha szoros néked az Efraim hegye.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'És mondának a József fiai: Nem elegendő nékünk ez a hegy, a Kananeusoknak pedig, a kik a völgyi síkon laknak, mindnek vas-szekerök van; úgy azoknak, a kik Béth-Seanban és mezővárosaiban, mint azoknak, a kik a Jezréel völgyében vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'Szóla pedig Józsué a József házának, Efraimnak és Manassénak, mondván: Sok nép vagy te és nagy erőd van néked, nem lesz néked csak egy sors szerint való részed;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'Mert hegyed lesz néked. Ha erdő az, úgy írtsd ki azt, és annak szélei is a tieid lésznek; mert kiűzöd a Kananeust, noha vas-szekere van néki, s noha erős az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'Izráel fiainak egész gyülekezete pedig összegyülekezék Silóban és oda helyhezteték a gyülekezetnek sátorát, minekutána meghódola előttök a föld.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'De maradtak vala még Izráel fiai között, akiknek nem osztották vala ki az ő örökségöket: hét nemzetség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'Monda azért Józsué Izráel fiainak: Meddig vonakodtok még elmenni, hogy elfoglaljátok a földet, a melyet néktek adott az Úr, a ti atyáitoknak Istene?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'Hozzatok elő három-három férfiút nemzetségenként, és elküldöm őket, hogy keljenek fel és járják el a földet, és írják fel azt az ő örökségük szerint, és térjenek vissza hozzám;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'Azután oszszák fel azt magok közt hét részre. Júda maradjon meg a maga határaiban dél felől, József háza pedig maradjon meg a maga határaiban észak felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'És ti írjátok le a földet hét részre, és hozzátok ide hozzám, hogy sorsot vessek itt néktek az Úr előtt, a mi Istenünk előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'Mert a Lévitáknak nincs részök ti közöttetek; mivelhogy az Úrnak papsága az ő örökségök; Gád pedig és Rúben és Manassé fél nemzetsége megkapták az ő örökségöket a Jordánon túl napkelet felé, a mit Mózes, az Úrnak szolgája adott vala nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'És felkelének azok a férfiak, és elmenének. Parancsola pedig Józsué azoknak, a kik elmenének, hogy leírják a földet, mondván: Menjetek el és járjátok el a földet, és írjátok le azt, azután térjetek vissza hozzám, és itt vetek néktek sorsot Silóban, az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'Elmenének azért a férfiak, és által menének a földön, és leírák azt városonként hét részre, könyvben, azután visszatérének Józsuéhoz a táborba, Silóba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'És sorsot vete nékik Józsué Silóban az Úr előtt, és elosztá ott Józsué a földet Izráel fiai között az ő osztályrészeik szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'És kijöve a Benjámin fiai nemzetségének sors szerint való része az ő családjaik szerint; és pedig esék az ő sors szerint való részöknek határa a Júda fiai és a József fiai közé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'Vala pedig az ő határok az északi oldalon a Jordántól fogva, és felméne a határ Jérikhó háta mögé észak felé, azután felméne a hegyre napnyugat felé, a szélei pedig Béth-Aven pusztájánál valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'Onnan pedig átmegy a határ Luz-felé, Lúznak azaz Béthelnek háta mögé dél felől; azután alámegy a határ Ataroth-Adárnak a hegyen, a mely dél felől van alsó Béth-Horontól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, 'Majd tovább megy a határ, és kerül a nyugoti oldalnak dél felé, attól a hegytől, a mely átellenben van Béth-Horonnal délről; a szélei pedig Kirjáth-Baál, azaz Kirjáth-Jeárim felé, a Júda fiainak városa felé vannak. Ez a napnyugoti határ.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'A déli oldala pedig van Kirjáth-Jeárim szélétől kezdve, és megy a határ napnyugot felé, megy a Nefthoa vizének kútfejéhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'Azután alámegy a határ a hegynek széléhez, a mely átellenben van a Hinnom fiának völgyével, a mely észak felé van a Refaim völgyében; alámegy a Hinnom völgyébe is a Jebuzeus mellett dél felé, és alámegy a Rógel forrásához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'És kerül észak felől, és megy Én-Semesnek, azután megy Gelilothnak, a mely átellenben van az Adummimba felvivő úttal; majd alámegy Bohánnak, a Rúben fiának kövéhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'És átmegy az Arabával átellenben levő oldalra észak felé, és alámegy Arabába is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'Átmegy a határ azután Béth-Hogla oldalára észak felé; a határ szélei pedig északnak a Sóstenger csúcsánál, délnek a Jordán végénél vannak. Ez a dél felé való határ.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, 'A Jordán pedig határolja azt a napkelet felől való oldalról. Ez a Benjámin fiainak öröksége az ő határaik szerint köröskörül, az ő családjaik szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'A Benjámin fiai nemzetségének városai pedig az ő családjaik szerint ezek: Jérikhó, Béth-Hogla, és Emek-Keczicz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'Béth-Arábá, Czemaraim és Béthel;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'Avvim, Pára és Ofra;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'Kefár-Amóni, Ofni és Gába. Tizenkét város és azoknak falui.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'Gibeon, Ráma és Beéroth;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'Miczpe, Kefira és Mócza;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'Rekem, Jirpeél és Thareala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'Czéla, Elef és Jebuzeus, azaz Jeruzsálem, Gibeath, Kirjáth. Tizennégy város és ezeknek falui. Ez a Benjámin fiainak öröksége az ő családjaik szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'A sors által való második rész juta Simeonnak, a Simeon fiai nemzetségének az ő családjaik szerint, és lőn az ő örökségök a Júda fiainak öröksége között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'És lőn az övék az ő örökségökül: Beer-Seba, Seba és Móláda;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'Haczar-Sual, Bála és Eczem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'Eltolád, Bethul és Horma;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'Cziklág, Béth-Markaboth és Haczar-Szusza;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'Béth-Lebaoth és Sarúhen. Tizenhárom város és ezeknek falui.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'Ain, Rimmon, Ether és Asán. Négy város és ezeknek falui;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'És mindazok a faluk, a melyek e városok körül valának Baalath-Beérig, délen Rámatig. Ez a Simeon fiai nemzetségének öröksége az ő családjaik szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'A Júda fiainak osztályrészéből lőn a Simeon fiainak örökségök, mert a Júda fiainak osztályrésze nagyobb vala mint illett volna nékik; ezért öröklének Simeon fiai azoknak öröksége között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'A sors által való harmadik rész juta a Zebulon fiainak az ő családjaik szerint, és lőn az ő örökségöknek határa Száridig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'És felmegy az ő határuk nyugotnak, Mareala felé, és éri Dabbasethet, és éri a folyóvizet is, a mely átellenben van Jokneámmal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'Száridtól pedig napkelet felé fordul Kiszloth-Tábor határára, és tova megy Daberáthnak, és felmegy Jafiának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'Innen pedig átmegy kelet felé Gittha-Héfernek és Ittha-Kaczinnak, és tova megy Rimmonnak, kerülvén Néa felé:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'És ennél kerül a határ északról Hannathonnak; a széle pedig a Jiftah-Él völgye.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, 'Továbbá Kattáth, Nahalál, Simron, Jidealá és Bethlehem. Tizenkét város és azoknak falui.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'Ez a Zebulon fiainak öröksége az ő családjaik szerint; ezek a városok és ezeknek falui.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'A sors által való negyedik rész Issakhárnak, az Issakhár fiainak juta, az ő családjaik szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'És lőn az ő határuk: Jezréel, Keszuloth és Súnem:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'Hafaráim, Sion és Anaharath;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'Rabbith, Kisjon és Ébecz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'Remeth, Én-Gannim, Én-Hadda és Béth-Paczczécz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'És éri a határ Tábort, Sahaczimát és Béth-Semest, a határuknak széle pedig a Jordán. Tizenhat város és ezeknek falui.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'Ez az Izsakhár fiai nemzetségének öröksége, az ő családjaik szerint: a városok és ezeknek falui.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'A sors által való ötödik rész pedig juta az Áser fiai nemzetségének az ő családjaik szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'És lőn az ő határuk: Helkath, Háli, Beten és Aksáf;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'Alammelek, Ameád és Misál, és éri Karmelt nyugot felé és Sihór-Libnáthot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'Azután visszafordul napkelet felé Béth-Dágonnak, és éri Zebulont és a Jiftah-Él völgyét észak felől, Béth-Émeket és Neiélt, és tovamegy Kabulnak balkéz felől;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'És Ebronnak, Rehobnak, Hammonnak és Kánának a nagy Czidonig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'Azután visszafordul a határ Rámának, Tyrusnak erős városáig; és újra fordul a határ Hósznak, a szélei pedig a tengernél vannak Akzib oldala felől;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, 'És Umma, Afék és Rehób. Huszonkét város és ezeknek falui.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'Ez az Áser fiai nemzetségének öröksége az ő családjaik szerint: ezek a városok és ezeknek falui.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'A sors által való hatodik rész juta a Nafthali fiainak, a Nafthali fiainak az ő családjaik szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'Lőn pedig a határuk: Heleftől, Elontól fogva Czaanannimnál Adámi-Nekebig és Jabneél-Lakkumig; a széle pedig a Jordán vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'Azután fordul a határ nyugot felé Aznoth-Tábornak; innen pedig tovamegy Hukkóknak, és éri Zebulont dél felől, Ásert pedig éri nyugot felől, és a Júdát is; a Jordán napkelet felé vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'Erősített városok ezek: Cziddim, Czér, Hammath, Rakkath és Kinnereth;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'Adáma, Ráma és Hásor;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'Kedes, Edrei és Én-Hásor;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'Jireon, Migdal-Él, Horem, Béth-Anath és Béth-Semes. Tizenkilencz város és ezeknek falui.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'Ez a Nafthali fiai nemzetségének öröksége az ő családjaik szerint: a városok és ezeknek falui.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'A sors által való hetedik rész juta a Dán fiai nemzetségének az ő családjaik szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'És lőn az ő örökségüknek határa: Czóra, Estháol és Ir-Semes;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'Saalabbin, Ajjálon és Jithla;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'Élon, Timnatha és Ekrón;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'Eltheké, Gibbethon és Baaláth;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'Jehud, Bené-Bárak és Gath-Rimmon;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'Mé-Jarkon és Rakkon, a Jáfó átellenében levő határral.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, 'De tovább méne ezeknél a Dán fiainak határa. Felmenének ugyanis a Dán fiai, és hadakozának Lesem ellen, és el is foglalák azt, és veték azt fegyver élére, és birtokba vevék azt, és lakozának benne, és nevezék Lesemet Dánnak, az ő atyjoknak Dánnak nevére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'Ez a Dán fiai nemzetségének öröksége az ő családjaik szerint: ezek a városok és ezeknek falui.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'Mikor pedig elvégezték vala a földnek örökbe vételét annak határai szerint, akkor adának Izráel fiai örökséget Józsuénak, a Nún fiának ő közöttök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'Az Úr rendelése szerint adák néki azt a várost, a melyet kért vala: Timnath-Szeráhot az Efraim hegyén, és megépíté azt a várost, és abban lakozék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'Ezek azok az örökségek, a melyeket örökül adának Eleázár, a pap és Józsué, a Nún fia és az atyáknak fejei az Izráel fiai nemzetségeinek sors szerint, Silóban, az Úr előtt, a gyülekezet sátorának nyílásánál. Így végezék el a földnek felosztását.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, 'Majd szóla az Úr Józsuénak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, 'Szólj az Izráel fiainak, mondván: Válaszszatok magatoknak menekülésre való városokat, a melyekről szóltam néktek Mózes által,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'Hogy oda szaladjon a gyilkos, a ki megöl valakit tévedésből, nem szándékosan, és legyenek azok menedékül nékik a vérbosszúló elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, 'A ki pedig beszalad valamelyikbe e városok közül, álljon az a város kapujába, és beszélje el az ő dolgait a város véneinek hallatára, és vegyék be őt magok közé a városba, és adjanak néki helyet, hogy velök lakozzék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, 'Hogyha pedig kergeti azt a vérbosszúló, ki ne adják a gyilkost annak kezébe, mert nem szándékosan ölte meg az ő felebarátját, és nem gyűlölte ő azt annakelőtte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'És lakozzék abban a városban mindaddig, a míg ítéletre állhat a gyülekezet elé, a míg meghal a főpap, a ki abban az időben lesz, azután térjen vissza a gyilkos, és menjen haza az ő városába és az ő házába, abba a városba, a melyből elfutott vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'És kiválaszták Kedest Galileában a Nafthali hegyén, Sikemet az Efraim hegyén és Kirjáth-Arbát, azaz Hebront a Júda hegyén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'Túl a Jordánon pedig Jérikhótól napkelet felé választák Beczert a pusztában, a sík földön Rúben nemzetségéből; Rámothot Gileádban, a Gád nemzetségéből, és Gólánt Básánban a Manassé nemzetségéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'Ezek voltak a meghatározott városok mind az Izráel fiainak, mind a jövevénynek, a ki közöttük tartózkodik vala, hogy oda szaladjon mindaz, a ki megöl valakit tévedésből, és meg ne haljon a vérbosszúlónak keze által, míg oda nem áll a gyülekezet elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, 'És hozzámenének a Léviták atyai fejedelmei Eleázárhoz, a paphoz, és Józsuéhoz, a Nún fiához és az atyai fejedelmekhez, a kik valának Izráel fiainak nemzetségei felett,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'És szólának nékik Silóban, a Kanaán földén, mondván: Az Úr megparancsolta Mózes által, hogy adjatok nékünk városokat lakóhelyül, és azokhoz való legelőket barmaink részére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'Adák azért Izráel fiai a Lévitáknak az ő örökségökből, az Úrnak rendelése szerint, ezeket a városokat és azoknak legelőit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'Esék pedig a sors a Kehátiták családjaira, és juta a Léviták közül való Áron pap fiainak a Júda nemzetségétől, a Simeon nemzetségétől és a Benjámin nemzetségétől sors szerint tizenhárom város;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'Kehát többi fiainak pedig az Efraim nemzetségének családjaitól, Dán nemzetségétől és Manassé fél nemzetségétől sors szerint tíz város.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'A Gerson fiainak pedig az Issakhár nemzetségének családjaitól, az Áser nemzetségétől, a Nafthali nemzetségétől és Manassénak Básánban levő fél nemzetségétől sors szerint tizenhárom város;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'Mérári fiainak az ő családjaik szerint a Rúben nemzetségétől, Gád nemzetségétől és Zebulon nemzetségétől tizenkét város.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'Adák azért Izráel fiai e városokat és ezeknek legelőit a Lévitáknak, a miképen megparancsolta vala az Úr Mózes által, sors szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'Adák pedig a Júda fiainak nemzetségéből és Simeon fiainak nemzetségéből ezeket a városokat, a melyek névszerint olvashatók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'És lőn, hogy esék a sors először a Lévi fiai közül való Kehátnak családjaiból az Áron fiaira.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'És adák nékik az Anák atyjának városát, Kirjáth-Arbát, azaz Hebront a Júda hegyén, és annak körülötte levő legelőit;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'A városnak szántóföldjét és faluit pedig Kálebnek, a Jefunné fiának adák birtokául.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'Az Áron pap fiainak pedig adák a gyilkosok menekülésének városát, Hebront és annak legelőjét, Libnát és annak legelőjét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'Jatthirt és annak legelőjét; Estemoát és annak legelőjét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'Holont és annak legelőjét, és Debirt és annak legelőjét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'Aint és annak legelőjét, Juttát és annak legelőjét, Béth-Semest és annak legelőjét. Kilencz várost e két nemzetségből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'A Benjámin nemzetségéből pedig Gibeont és annak legelőjét, Gébát és annak legelőjét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'Anathótot és annak legelőjét, Almont és annak legelőjét: négy várost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'Az Áron fiainak, a papoknak városai összesen tizenhárom város és azoknak legelői.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'A Kehát fiai családjainak pedig, s a Kehát fiai közül való többi Lévitáknak városai, az ő sorsuk szerint, az Efraim nemzetségéből valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'Nékik adák ugyanis a gyilkosok menekülésének városát, Sikemet és annak legelőjét az Efraim hegyén, és Gezert és annak legelőjét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'Kibczaimot és annak legelőjét, Béth-Horont és annak legelőjét: négy várost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'A Dán nemzetségéből pedig Elthekét és annak legelőjét, Gibbethont és annak legelőjét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'Ajjálont és annak legelőjét; Gath-Rimmont és annak legelőjét; négy várost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'A Manassé fél nemzetségéből pedig: Taanákot és annak legelőjét, Gath-Rimmont és annak legelőjét: két várost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'Összesen tíz várost és azoknak legelőit a Kehát fiai többi családjainak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'A Gerson fiainak pedig, a kik a Léviták családjaiból valának, adák a Manassé fél nemzetségéből a gyilkosok menekülésének városát, Gólánt Básánban és annak legelőjét, és Beesterát és annak legelőjét: két várost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'Az Issakhár nemzetségéből pedig: Kisjont és annak legelőjét, Dobráthot, és annak legelőjét,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'Jármutot és annak legelőjét, és Én-Gannimot és annak legelőjét: négy várost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'Az Áser nemzetségéből pedig: Misált és annak legelőjét, Abdont és annak legelőjét,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'Helkathot és annak legelőjét, és Rehobot és annak legelőjét: négy várost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'A Nafthali nemzetségéből pedig: a gyilkosok menekülésének városát, Kedest Galileában és annak legelőjét, Hammoth-Dórt és annak legelőjét, és Karthant és annak legelőjét: három várost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'A Gersoniták összes városai, az ő családjaik szerint, tizenhárom város és azoknak legelői.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'A Mérári fiai családjainak pedig, e még hátralevő Lévitáknak, adák a Zebulon nemzetségéből: Jokneámot és annak legelőjét, Karthát és annak legelőjét,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'Dimnát és annak legelőjét, Nahalált és annak legelőjét; négy várost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'A Rúben nemzetségéből pedig: Béczert és annak legelőjét, Jahczát és annak legelőjét,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'Kedémothot és annak legelőjét, és Méfaathot és annak legelőjét: négy várost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'A Gád nemzetségéből pedig: a gyilkosok menekülésének városát, Rámothot Gileádban és annak legelőjét, Mahanaimot és annak legelőjét,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'Hesbont és annak legelőjét; Jaézert és annak legelőjét: összesen négy várost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'A Mérári fiainak városai az ő családjaik szerint, a kik a Léviták családjai közül maradtak fel, valának az ő sorsuk szerint összesen tizenkét város.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'A Lévitáknak összes városai az Izráel fiainak birtoka között: negyvennyolcz város azoknak legelőivel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'Valának ezek a városok a tulajdonképeni város és körülöttök azoknak legelői. Így vala ez mind e városoknál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'Megadá azért az Úr Izráelnek mindazt a földet, a mely felől megesküdött vala, hogy odaadja azt az ő atyáiknak. És bírák azt, és lakozának abban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, 'Nyugodalmat is ada nékik az Úr mindenfelől, szintén úgy, a mint megesküdött vala az ő atyáiknak. És senki nem állott meg ellenökben valamennyi ellenségeik közül; minden ellenségöket kezökbe adá az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, 'Nem esett el csak egy szó is mindama jó szóból, a melyet szólott vala az Úr az Izráel házának. Mindaz betelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, 'Akkor hivatá Józsué a Rúbenitákat, a Gáditákat és a Manassé fél nemzetségét,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'És monda nékik: Ti megtartottátok mindazt, a mit Mózes, az Úrnak szolgája parancsolt néktek, és hallgattatok az én szómra mindenben, a mit parancsoltam néktek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'Nem hagytátok el a ti atyátokfiait immár sok nap óta mind e mai napig, és megtartottátok a megtartandókat, az Úrnak, a ti Isteneteknek parancsolatját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'Most pedig nyugodalmat adott az Úr, a ti Istenetek a ti atyátokfiainak, a mint megmondta vala nékik; most azért térjetek vissza, és menjetek a ti sátraitokba, a ti örökségteknek földére, a melyet Mózes, az Úrnak szolgája adott vala néktek túl a Jordánon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'Csak igen vigyázzatok, hogy teljesítsétek a parancsolatot és a törvényt, a melyet parancsolt néktek Mózes, az Úrnak szolgája, hogy szeressétek az Urat, a ti Isteneteket, és járjatok minden ő útján, és tartsátok meg az ő parancsolatait, és ragaszkodjatok hozzá, és szolgáljatok néki teljes szívetekből és teljes lelketekből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'És megáldá őket Józsué, azután elbocsátá őket, és elmenének az ő sátraikba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, 'Mert a Manassé nemzetsége felének Mózes adott vala örökséget Básánban; a másik felének pedig Józsué adott az ő atyjafiaival a Jordánon innen napnyugot felől. És a mikor elbocsátá is őket Józsué az ő sátraikba, akkor is megáldá őket,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'És szóla nékik, mondván: Nagy gazdagsággal térjetek vissza sátraitokba, és igen sok barommal, ezüsttel, arannyal, rézzel, vassal és igen sok ruhával. Az ellenségeitektől vett zsákmányt oszszátok meg a ti atyátokfiaival.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'Visszatérének azért, és elmenének a Rúben fiai, a Gád fiai és a Manassé fél nemzetsége Izráel fiaitól, Silóból, a mely Kanaán földén van, hogy menjenek Gileád földére, az ő örökségüknek földébe, a melyben örökséget vőnek az Úr rendelése szerint Mózes által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'Mikor a Jordán mellékére értek, a mely még Kanaán földén van, építének a Rúben fiai, Gád fiai és Manassé fél nemzetsége ott a Jordán mellett oltárt, nagy, láttatós oltárt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'Meghallák pedig Izráel fiai, hogy ezt mondják vala: Ímé a Rúben fiai, Gád fiai és Manassé fél nemzetsége oltárt építettek átellenben a Kanaán földével, a Jordán mellékén, Izráel fiainak oldala felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'A mint meghallák Izráel fiai, egybegyűle Izráel fiainak egész gyülekezete Silóban, hogy hadakozni induljanak fel ellenök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'Küldék pedig Izráel fiai a Rúben fiaihoz, Gád fiaihoz és a Manassé fél nemzetségéhez Gileád földére Fineást, Eleázárnak, a papnak fiát;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'Tíz fejedelmet is vele, egy-egy fejedelmet az ősök háza szerint Izráelnek minden nemzetségéből. Ezek mind fejedelmei valának az ő őseik házának, Izráelnek ezerei között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'És eljutának a Rúben fiaihoz, a Gád fiaihoz és a Manassé fél nemzetségéhez a Gileád földére, és szólának ő velök, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, 'Így szól az Úrnak egész gyülekezete: Micsoda vétek ez, a melylyel vétkeztetek Izráelnek Istene ellen, hogy immár elfordultatok az Úrtól, építvén magatoknak oltárt, hogy pártot üssetek immár az Úr ellen?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'Avagy kevés-é nékünk a Peór miatt való hamisságunk, a miből ki sem tisztultunk még mind e napig, és a miért csapás lőn az Úrnak gyülekezetén?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'És ti elfordultatok immár az Úrtól; pedig ha ti pártot üttök ma az Úr ellen: holnap majd Izráelnek egész gyülekezetére haragszik meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'Ha pedig tisztátalannak tetszik előttetek a ti örökségeteknek földje: úgy jőjjetek át az Úr örökségének földjére, a hol ott áll az Úrnak sátora, és legyetek örökösökké mi közöttünk; de az Úr ellen ne üssetek pártot, és ellenünk se üssetek pártot, építvén magatoknak oltárt, az Úrnak, a mi Istenünknek oltárán kivül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'Avagy nem Ákán, a Zéra fia vétkezék-é nagy vétekkel az Istennek szentelt dolog ellen; mégis az Izráelnek egész gyülekezete ellen lőn a harag! És az a férfiú nem egymaga halt meg az ő bűnéért!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'Felelének pedig a Rúben fiai, a Gád fiai és a Manassé fél nemzetsége, és szólának az Izráel ezereinek fejeihez:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, 'Az Istenek Istene az Úr, az Istenek Istene az Úr: ő tudja, és az Izráel is megtudja. Ha pártütésből és ha az Úr ellen való vétekből van ez: ne tartson meg minket e napon!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'Ha azért építettünk magunknak oltárt, hogy elforduljunk az Úrtól, vagy pedig hogy áldozzunk azon egészen égőáldozatot és ételáldozatot; vagy hogy tegyünk arra hálaadásnak áldozatját: – lássa meg ezt ő maga az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'Hát nem inkább a miatt való féltünkben cselekedtük-é ezt, hogy így gondolkoztunk: Maholnap így szólhatnak a ti fiaitok a mi fiainkhoz, mondván: Mi közötök van néktek az Úrhoz, Izráel Istenéhez?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'Hiszen határt vetett az Úr mi közöttünk és ti közöttetek Rúben fiai és Gád fiai – a Jordánt; nincsen néktek részetek az Úrban! És elidegeníthetnék a ti fiaitok a mi fiainkat, hogy ne féljék az Urat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'Mondottuk azért: Nosza fogjunk hozzá, hogy építsünk oltárt, se nem egészen égőáldozatra, se nem véres áldozatra;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'Hanem hogy bizonyság legyen az mi közöttünk és ti közöttetek, és a mi utánunk való nemzetségeink között, hogy szolgálni akarjuk az Urat ő előtte a mi egészen égőáldozatainkkal, véres áldozatainkkal és hálaáldozatainkkal, és hogy ne mondhassák a ti fiaitok maholnap a mi fiainknak: Nincs néktek részetek az Úrban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'Mondottuk azért: Ha így szólanának maholnap nékünk vagy a mi nemzetségeinknek, ezt mondjuk majd: Lássátok az Úr oltárának mássát, a melyet a mi atyáink készítettek, nem egészen égőáldozatra, sem nem véres áldozatra, hanem hogy bizonyság legyen mi közöttünk és ti közöttetek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'Távol legyen tőlünk, hogy pártot üssünk az Úr ellen, és elforduljunk immár az Úrtól, építvén oltárt égőáldozatra, ételáldozatra és véres áldozatra az Úrnak, a mi Istenünknek oltárán kivül, a mely az ő sátora előtt van!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'Hallván pedig Fineás, a pap és a gyülekezetnek fejedelmei és Izráel ezereinek fejei, a kik vele valának, a beszédeket, a melyeket szólottak vala a Rúben fiai, a Gád fiai és a Manassé fiai; tetszésre találtak vala előttök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'És monda Fineás, az Eleázár pap fia a Rúben fiainak, Gád fiainak és a Manassé fiainak: Ma tudtuk meg, hogy köztünk van az Úr, mivelhogy nem vétkeztetek e vétekkel az Úr ellen. Most megszabadítottátok Izráel fiait az Úr kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'Visszatére azért Fineás, az Eleázár pap fia és a fejedelmek a Rúben fiaitól, a Gád fiaitól a Gileád földéről a Kanaán földére Izráelnek fiaihoz, és megbeszélék nékik e dolgot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'És tetszésre talált e dolog Izráel fiai előtt is, és áldák az Istent Izráel fiai, és nem mondák, hogy hadakozni menjenek fel ellenök, hogy elveszessék a földet, a melyben lakoznak a Rúben fiai és a Gád fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'Az oltárt pedig így nevezék Rúben fiai és a Gád fiai: „Bizonyság ez közöttünk, hogy az Úr az Isten.”');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'Lőn pedig sok nappal azután, hogy nyugodalmat adott vala az Úr Izráelnek minden ő körülötte lévő ellenségeitől: megvénhedék Józsué és megidősödék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'Előhívá ekkor Józsué az egész Izráelt, annak véneit, fejeit, biráit és felügyelőit, és monda nékik: Én megvénhedtem és megidősödtem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'Magatok is láttatok mindent, a mit az Úr, a ti Istenetek mind eme népekkel cselekedett ti előttetek; mivelhogy maga az Úr, a ti Istenetek harczolt érettetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'Ímé elosztám néktek sors által a fennmaradt népeket örökségül a ti nemzetségeitek szerint, a Jordántól kezdve, és mindazokat a népeket, a melyeket kipusztítottam, és a nagy tengert is napnyugat felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'Az Úr pedig, a ti Istenetek kiűzi őket a ti orczátok elől, és kiűzi őket ti előletek, hogy örököseivé legyetek az ő földüknek, a mint megmondotta vala néktek az Úr, a ti Istenetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'Legyetek azért igen erősek, hogy megtartsátok és megcselekedjétek mind azt, a mi meg van írva a Mózes törvényének könyvében; hogy el ne távozzatok attól se jobbkézre, se balkézre;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'Hogy össze ne elegyedjetek ezekkel a népekkel, azokkal, a melyek fenmaradtak közöttetek; isteneiknek nevét ki se ejtsétek, azokra ne esküdjetek, se ne szolgáljatok nékik, se előttök meg ne hajoljatok;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'Hanem ragaszkodjatok az Úrhoz, a ti Istenetekhez, a miképen e mai napig cselekedtetek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'Ezért űzött ki az Úr előletek nagy és erős népeket: a mi pedig titeket illet, senki meg nem állhatott ellenetekben mind e napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'Egy férfiú közületek elűz ezeret, mert az Úr, a ti Istenetek az, a ki harczol érettetek, a miképen megmondta vala néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, 'Azért igen vigyázzatok magatokra, hogy szeressétek az Urat, a ti Isteneteket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'Mert ha elfordulván elfordultok tőle és ragaszkodtok e népek maradékaihoz, a melyek itt maradtak ti közöttetek; és sógorságot köttök ő velök és összeelegyedtek velök és ők veletek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'Bizonynyal megtudjátok majd, hogy az Úr, a ti Istenetek ki nem űzi többé e népeket ti előletek; sőt inkább lésznek ti néktek tőrré és hurokká, oldalaitokban ostorrá, szemeitekben pedig tövisekké, míglen kivesztek erről a jó földről, a melyet az Úr, a ti Istenetek adott ti néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'Én pedig ímé megyek már a minden földinek útján: Tudjátok meg azért teljes szívetek és teljes lelketek szerint, hogy egy szó sem esett el mindama jó szóból, a melyeket az Úr, a ti Istenetek szólott vala felőletek. Minden betelt rajtatok, egy szó sem esett el azokból!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'De a miképen betelt rajtatok mind az a jó szó, a melyeket az Úr, a ti Istenetek szólott vala felőletek: akképen teljesíti majd rajtatok mind a gonosz szót is az Úr, míglen kipusztít titeket e jó földről, a melyet az Úr, a ti Istenetek adott ti néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'Ha általhágjátok az Úrnak, a ti Isteneteknek szövetségét, a melyet parancsolt néktek, és elmentek és szolgáltok idegen isteneknek, és meghajoltok azok előtt: akkor felgerjed ellenetek az Úrnak haragja, és hamar kivesztek e jó földről, a melyet ő adott néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, 'Józsué pedig összegyűjté Izráelnek minden nemzetségét Síkembe, és előhívá Izráelnek véneit, fejeit, biráit és felügyelőit, és oda állának az Úr elébe,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'És monda Józsué az egész népnek: Ezt mondja az Úr, Izráelnek Istene: A folyóvizen túl lakoztak régenten a ti atyáitok: Tháré, Ábrahámnak atyja és Nákhórnak atyja, és idegen isteneknek szolgáltak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'De áthozám a ti atyátokat, Ábrahámot a folyóvíz túlsó oldaláról, és elhordozám őt az egész Kanaán földén, és megsokasítám az ő magvát; és adám néki Izsákot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'Izsáknak pedig adám Jákóbot és Ézsaut. És Ézsaunak a Szeír hegyét adám birtokul, Jákób pedig és az ő fiai alámenének Égyiptomba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'Majd elküldém Mózest és Áront, és megverém Égyiptomot úgy, a hogy cselekedtem vala közöttök; azután pedig kihoztalak vala titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'És kihoztam a ti atyáitokat Égyiptomból, és jutátok a tengerhez, és űzék az égyiptomiak a ti atyáitokat szekerekkel és lovasokkal a Veres tengerig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'Akkor az Úrhoz kiáltának, és homályt vete ti közétek és az égyiptomiak közé, és rájok vivé a tengert és elborítá őket. Szemeitek is látták azt, a mit cselekedtem vala az égyiptomiakkal; ti pedig sok ideig lakoztatok a pusztában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'Majd elhozálak titeket az Emoreusok földére, a kik túl laktak vala a Jordánon, és hadakozának ellenetek; de kezetekbe adám őket, és bírátok az ő földüket, őket pedig eltörlém a ti orczátok elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'Majd felkele Bálák, a Czippor fia, Moábnak királya, és hadakozék Izráellel, és elkülde és hivatá Bálámot, a Beór fiát, hogy átkozzon meg titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'De nem akarám meghallgatni Bálámot, ezért áldva áldott vala titeket, és megszabadítálak titeket az ő kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'Majd általjövétek a Jordánon, és jutátok Jérikhóba, és hadakozának veletek Jérikhónak urai: az Emoreus, Perizeus, Kananeus, Khittheus, Girgazeus, Khivveus és Jebuzeus; de kezetekbe adám őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'Mert elbocsátám előttetek a darázsokat, és űzék azokat előletek: az Emoreusok két királyát, de nem a te fegyvered által, de nem a te kézíved által!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'És adék néktek földet, a melyben nem munkálkodtál, és városokat, a melyeket nem építettetek vala, mégis bennök laktok; szőlőket és olajfákat, a melyeket nem ti ültettetek, de esztek azokról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'Azért hát féljétek az Urat, és szolgáljatok néki tökéletességgel és hűséggel; és hányjátok el az isteneket, a kiknek szolgáltak a ti atyáitok túl a folyóvizen és Égyiptomban, szolgáljatok az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'Hogyha pedig rossznak látjátok azt, hogy szolgáljatok az Úrnak: válaszszatok magatoknak még ma, a kit szolgáljatok; akár azokat az isteneket, a kiknek a ti atyáitok szolgáltak, a míg túl valának a folyóvizen, akár az Emoreusok isteneit, a kiknek földjén lakoztok: én azonban és az én házam az Úrnak szolgálunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'A nép pedig felele, és monda: Távol legyen tőlünk, hogy elhagyjuk az Urat, szolgálván idegen isteneknek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'Sőt inkább az Úr, a mi Istenünk az, a ki felhozott minket és atyáinkat Égyiptom földéből, a szolgák házából, és a ki ezeket a nagy jeleket tette a mi szemeink előtt, és megtartott minket minden útunkban, a melyen jártunk, és mind ama népek között, a melyek között általjöttünk;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'És kiűzött az Úr minden népet, az Emoreust is, e földnek lakóját, a mi orczánk elől: Mi is szolgálunk az Úrnak, mert ő a mi Istenünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'Józsué pedig monda a népnek: Nem szolgálhattok az Úrnak, mert szent Isten ő, féltőn szerető Isten ő; nem bocsátja meg a ti vétkeiteket és bűneiteket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'Hogyha elhagyjátok az Urat, és szolgáltok idegen isteneknek: akkor elfordul és roszszal illet benneteket, és megemészt titeket, minekutána jól cselekedett veletek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, 'Akkor monda a nép Józsuénak: Nem, mert mi az Úrnak szolgálunk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'Józsué pedig monda a népnek: Bizonyságok vagytok magatok ellen, hogy ti választottátok magatoknak az Urat, hogy néki szolgáljatok. És mondának: Bizonyságok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, 'Most azért hányjátok el az idegen isteneket, a kik köztetek vannak, és hajtsátok sziveteket az Úrhoz, Izráelnek Istenéhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'És monda a nép Józsuénak: Az Úrnak, a mi Istenünknek szolgálunk, és az ő szavára hallgatunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'Szerze azért Józsué szövetséget a néppel e napon, és ada eleibe rendelést és végzést Síkemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'És beírá Józsué e dolgokat az Isten törvényének könyvébe, és vőn egy nagy követ, és oda helyhezteté azt a cserfa alá, a mely vala az Úrnak szent házában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'És monda Józsué az egész népnek: Ímé ez a kő lesz ellenünk bizonyságul; mert ez hallotta az Úrnak minden beszédét, a melyet szólott vala nékünk; és lesz ellenetek bizonyságul, hogy ne hazudjatok a ti Istenetek ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'És elbocsátá Józsué a népet, kit-kit a maga örökségébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'És lőn e dolgok után, hogy meghala Józsué, a Nún fia, az Úrnak szolgája, száztíz esztendős korában,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'És eltemeték őt az ő örökségének határában Timnat-Szerában, a mely az Efraim hegyén van, a Gaas hegytől észak felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'Izráel pedig az Urat szolgálta vala Józsuénak minden idejében, és a véneknek is minden idejökben, a kik hosszú ideig éltek Józsué után, és a kik tudják vala minden cselekedetét az Úrnak, a melyet cselekedett vala Izráellel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'A József csontjait pedig, a melyeket felhoztak vala Izráel fiai Égyiptomból, eltemették Síkemben, a mezőnek abban a részében, a melyet szerzett vala Jákób Hámornak, a Síkem atyjának fiaitól száz pénzén; és lőnek a József fiainak örökségévé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'Meghala Eleázár is, Áronnak fia, és eltemeték őt Gibeathban, az ő fiának Fineásnak városában, a mely néki adatott az Efraim hegyén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'És lőn Józsué halála után, hogy megkérdék az Izráel fiai az Urat, mondván: Ki menjen legelőször közülünk a Kananeusra, hogy hadakozzék ő ellene?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, 'És monda az Úr: Júda menjen! Ímé az ő kezébe adtam azt a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'Ekkor monda Júda az ő atyjafiának Simeonnak: Jer velem együtt a nékem sors által jutott örökségbe, hogy hadakozzunk a Kananeus ellen, és én is elmegyek veled a néked sors által jutott örökségbe. És Simeon elméne vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'És felméne Júda, és kezökbe adá az Úr a Kananeust és a Perizeust, és levágtak közülök Bézekben tízezer embert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'És találák Adonibézeket Bézekben, és hadakozának ő ellene, és megverék a Kananeust és a Perizeust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'És megfutamodott Adonibézek, de űzőbe vevék, és elfogván őt, elvágták kezeinek és lábainak hüvelykújjait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'Ekkor monda Adonibézek: Hetven király szedeget vala asztalom alatt, a kiknek elvágattam kezeik és lábaik hüvelykujjait; a mint én cselekedtem, úgy fizetett nékem az Isten. Azután elvivék őt Jeruzsálembe, és ott meghala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'Azután Jeruzsálem ellen hadakoztak a Júda fiai, és elfoglalván azt, lakosait levágták fegyvernek élivel, a várost pedig lángba borították.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'Azután pedig alámenének a Júda fiai, hogy harczoljanak a hegységen, a déli tartományban és a lapályon lakó Kananeus ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'És elment Júda a Hebronban lakó Kananeus ellen, – Hebron neve azelőtt Kirjáth-Arba volt, – és megverték Sésait, Achimánt és Thalmáit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'Onnan pedig méne Debir lakói ellen. Debir neve pedig azelőtt Kirjáth-Széfer volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'És monda Káleb: A ki Kirjáth-Széfert megveri és elfoglalja, annak feleségül adom az én leányomat, Akszát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'És elfoglalá azt Othniel, Kénáz fia, Káleb öcscse, és néki adá Akszát, az ő leányát feleségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'És lőn, hogy a mikor eljöve az, biztatá őt, hogy kérjen mezőt az ő atyjától. Leszálla azért a szamárról, Káleb pedig monda néki: Mi bajod van?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, 'Ő pedig monda néki: Adj áldást nékem: mert déli vidékre helyheztettél engem, adj most vízforrásokat is. És néki adá Káleb a felső forrást és az alsó forrást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'És Keneusnak, a Mózes ipának fiai is felmentek a pálmák városából a Júda fiaival a Júda pusztájára, mely délre van Aradtól, és elmentek és letelepedtek a nép között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'És elment Júda az ő atyjafiával, Simeonnal, és megverék a Czéfátban lakó Kananeust, és elpusztították azt, és elnevezték a várost Hormának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'Azután elfoglalta Júda Gázát és annak határát, Askelont és annak határát, Ekront és annak határát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'Vala pedig az Úr Júdával, és kiűzé a hegység lakóit; de a völgy lakóit nem lehetett kiűzni, mert vas-szekereik voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'És Kálebnek adták Hebront, a mint meghagyta volt Mózes, és kiűzé onnan Anák három fiát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'De a Jebuzeust, Jeruzsálemnek lakóját nem űzték el a Benjámin fiai, és ezért lakik a Jebuzeus a Benjámin fiaival Jeruzsálemben még máig is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'És felméne a József háza is, Béthel ellen, és az Úr volt ő vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'És kikémlelteté a József háza Béthelt. A város neve pedig régenten Lúz volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'És látának a kémek egy férfiút, a ki a városból jött vala, és mondának néki: Mutasd meg a város bejárását, és irgalmasságot cselekszünk veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'És mikor ez megmutatta nékik a város bejárását, a várost fegyver élére hányták; de azt a férfiút és egész házanépét elbocsáták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'És elment az a férfiú a Khitteusok földére, és várost épített, és elnevezé azt Lúznak. Ez annak neve mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'És nem űzte el Manassé a lakosokat sem Béthseánból és annak mezővárosaiból, sem Taanakból és mezővárosaiból, sem Dórból és mezővárosaiból, sem a Jibleámnak és mezővárosainak lakosait, sem Megiddónak és mezővárosainak lakosait. És a Kananeusnak tetszett ott lakni azon a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'És mikor Izráel megerősödött, adófizetőjévé tette a Kananeust; de elűzni nem űzte el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'És Efraim sem űzte ki a Kananeust, a ki Gézerben lakott; hanem a Kananeus ott lakott közöttük Gézerben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'Zebulon sem űzte el sem Kitron lakosait, sem Nahalólnak lakóit, hanem közöttük lakozott a Kananeus, és adófizetőikké lettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'Áser sem űzte el sem Akkó, sem Sidon, sem Akhláb, sem Akzib, sem Helba, sem Afik, sem Rehob lakóit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'És ott lakott Áser a Kananeusok, a föld lakói között, mert nem űzte el őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'Nafthali sem űzte el sem Béth-Semes lakosait, sem Béth-Anath lakóit, hanem ott lakott a Kananeusok, a föld lakói között, és Béth-Semes és Béth-Anath lakói adófizetőikké lettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'Az Emoreusok pedig felszorították a Dán fiait a hegységbe, mert nem engedték meg, hogy lejőjjenek a völgybe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'És az Emoreusoknak tetszett ott lakni a Héresz hegységen, Ajalonban és Saalbimban; de mikor a József házának keze rájok nehezedett, adófizetőkké lettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'Az Emoreusok határa pedig az Akrabbim hágójától és Sélától fölfelé volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'Felméne pedig az Úrnak angyala Gilgálból Bókimba, és monda: Én vezettelek fel titeket Égyiptomból, és hoztalak benneteket erre a földre, a mely felől megesküdtem a ti atyáitoknak, és mondék: Nem bontom fel az én szövetségemet ti veletek soha örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'Csakhogy ti se kössetek frigyet ennek a földnek lakosival, rontsátok le az ő oltáraikat; de ti nem hallgattatok az én szómra. Miért cselekedtétek ezt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, 'Annakokáért azt mondom: Nem űzöm el őket előletek, hanem legyenek néktek mint tövisek a ti oldalaitokban, és az ő isteneik legyenek ti néktek tőr gyanánt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'És lőn, hogy mikor az Úrnak angyala ezeket mondá az Izráel minden fiainak: felemelé a nép az ő szavát és síra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'És elnevezték azt a helyet Bókimnak, és áldozának ott az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'És elbocsátá Józsué a népet, és elmenének az Izráel fiai, kiki az ő örökségébe, hogy bírják a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'És a nép az Urat szolgálta Józsuénak egész életében, és a véneknek minden napjaiban, a kik hosszú ideig éltek Józsué után, a kik látták az Úrnak minden dolgait, melyeket cselekedett vala Izráellel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'És meghalt Józsué, a Nún fia, az Úr szolgája, száztíz esztendős korában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'És eltemeték őt örökségének határában, Timnat-Héreszben, az Efraim hegyén, északra a Gaas hegyétől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'És az az egész nemzetség gyűjteték az ő atyáihoz, és támadott más nemzetség ő utánok, a mely nem ismerte sem az Urat, sem az ő cselekedeteit, melyeket cselekedett Izráellel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'És gonoszul cselekedtek az Izráel fiai az Úrnak szemei előtt, mert a Baáloknak szolgáltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'És elhagyák az Urat, atyáik Istenét, a ki kihozta őket Égyiptom földéből, és más istenek után jártak, a pogány népek istenei közül, a kik körülöttük voltak, és azok előtt hajtották meg magukat, és haragra ingerelték az Urat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'És elhagyták az Urat, és szolgáltak Baálnak és Astarótnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'És felgerjedett az Úrnak haragja Izráel ellen, és adá őket a ragadozók kezébe, és elragadozák őket, és adá őket a körülöttük való ellenségeik kezébe, és még csak megállani sem bírtak ellenségeik előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'A hova csak kivonultak, mindenütt ellenök volt az Úr keze rontásukra, a mint megmondotta volt az Úr, és a mint megesküdt volt az Úr nékik. És igen megnyomorodának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'És támasztott az Úr bírákat, a kik megszabadíták őket szorongatóiknak kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'De bíráikra sem hallgattak, hanem más istenekkel paráználkodtak, és azoknak hajtották meg magukat, és hamar letértek az útról, a melyen atyáik jártak, kik az Úrnak parancsára hallgattak; ők nem cselekedtek így.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'Mert mikor bírákat támasztott az Úr nékik, az Úr maga volt a bíróval, és megszabadította őket ellenségeik kezéből a biró egész idejére, mert megindult az Úr panaszaikon, melyeket emeltek elnyomóik és szorongatóik miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'De mihelyt a bíró meghalt, visszatértek, és jobban megromlottak, mint atyáik; más istenek után jártak, azoknak szolgáltak, és azok előtt hajtották meg magukat, föl nem hagytak cselekedeteikkel és nyakas magaviseletökkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'Ezért felgerjedett az Úrnak haragja Izráel ellen, és monda: Mivelhogy általhágta ez a nemzetség az én szövetségemet, melyet atyáiknak parancsoltam, és nem hallgatott az én szavamra:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'Én sem űzök ki többé senkit sem előlük azon pogányok közül, a kiket meghagyott Józsué, a mikor meghalt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'Hanem azok által kísértem Izráelt, ha vajjon megtartják-é az Úrnak útát, járván azon, a miképen megtartották az ő atyáik, avagy nem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'Ezért hagyta meg az Úr ezeket a pogányokat, és nem is űzte ki hamar, és nem adta őket Józsué kezébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'Ezek pedig a pogányok, a kiket meghagyott az Úr, hogy azok által kísértse Izráelt, azokat a kik nem ismerték a Kanaánért való harczokat,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, 'Csak azért, hogy az Izráel fiainak nemzetségei megismerjék, hogy tanítsa őket hadakozásra, csak azokat, a kik azelőtt ezt nem tudták:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'A Filiszteusok öt fejedelemsége, a Kananeusok mindnyájan, és a Sidoniusok, meg a Khivveusok, a kik a Libánon hegyén laknak, a Baálhermon hegyétől fogva Hamath bemeneteléig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'Kik azért hagyattak meg, hogy megkísértse általok az Úr Izráelt, hogy meglássa, vajjon engedelmeskednek-é az Úr parancsolatainak melyeket parancsolt az ő atyáiknak Mózes által?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'Így az Izráel fiai a Kananeusok, Khitteusok, Emoreusok, Perizeusok, Khivveusok és Jebuzeusok között laktak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'És azok leányait vették magoknak feleségül, a saját leányaikat pedig oda adták azok fiainak, és szolgálák azoknak isteneit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'És gonoszul cselekedtek az Izráel fiai az Úr szemei előtt, és elfelejtkezének az Úrról, az ő Istenökről, és a Baáloknak és Aseráknak szolgáltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'Ezért felgerjedett az Úrnak haragja az Izráel ellen, és adá őket Kusán-Risathaimnak, Mesopotámia királyának kezébe, és nyolcz évig szolgáltak az Izráel fiai Kusán-Risathaimnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'Ekkor az Úrhoz kiáltának az Izráel fiai, és az Úr szabadítót támasztott az Izráel fiainak, aki megszabadítá őket: Othnielt, Kénáz fiát, Káleb öcscsét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'És az Úrnak lelke vala ő rajta, és biráskodott Izráelben, és a mint kiméne a hadra, az Úr kezébe adta Kusán-Risathaimot, Mesopotámia királyát, és ránehezült keze Kusán-Risathaimra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'És megnyugovék a föld negyven esztendeig, és meghalt Othniel, a Kénáz fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'De az Izráel fiai ismét gonoszul cselekedének az Úr szemei előtt, és megerősítette az Úr Eglont, Moáb királyát Izráel ellen, azért, mert gonoszul cselekedtek az Úrnak szemei előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'Ez magához gyűjtötte Ammonnak és Amáleknek fiait, és elment, és megverte Izráelt, és elfoglalták a pálmák városát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'És szolgálák az Izráel fiai Eglont, a Moáb királyát tizennyolcz esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'Ekkor megint az Úrhoz kiáltottak Izráel fiai, és az Úr szabadítót támasztott nékik: Ehudot, Gérának fiát, ki Jemininek volt a fia, a ki suta volt. És mikor az Izráel fiai ajándékot küldének általa Eglonnak, Moáb királyának,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'Ehud szerze magának egy kétélű kardot, egy singnyi hosszút, és azt az ő ruhája alatt a jobb tomporára övezé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'És bemutatá az ajándékot Eglonnak, Moáb királyának. Eglon pedig igen kövér ember vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'És lőn, hogy mikor elvégezé az ajándék bemutatását, elbocsátá az embereket, a kik az ajándékot vitték vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'Ő maga pedig visszatért a Gilgál közelében lévő kőbányáktól és monda: Titkos beszédem van veled, óh király! És ez monda: Hallgass! és kimenének előle mindnyájan, kik állanak vala körülötte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'És Ehud akkor ment be hozzá, mikor épen az ő hűsölő felházában ült magányosan, és monda Ehud néki: Istennek beszéde van nálam te hozzád. És fölkele az a királyi székből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'Akkor kinyújtá Ehud az ő balkezét, és kirántá kardját a jobb tomporáról, és beleüté azt annak hasába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, 'És beméne még a markolatja is a vasa után és berekeszté a háj a fegyver vasát, mert nem vonta ki a kardot annak hasából, sőt átment annak vékonyán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'Általméne pedig Ehud a csarnokon, minekutána bevonta maga után a felház ajtait, és bezárta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'A mint ő kiméne, jövének annak szolgái, és láták, hogy ímé a felház ajtai be vannak zárva, és mondának: Bizonyára szükségét végzi a hűsölő kamarájában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'De mikor váltig várakoztak és ímé nem nyitotta meg a felház ajtaját, fogák a kulcsot és megnyiták: és ímé az ő urok ott feküdt a földön halva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'Ehud pedig elmenekült vala, míg azok késedelmezének, és elhaladván a kőbányák mellett, Szeiráhba futott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'És a mikor oda megérkezett, kürtjébe fújt az Efraim hegyén, és alámenének ő vele az Izráel fiai a hegyről, és ő előttük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'És monda nékik: Jertek utánam, mert kezetekbe adta az Úr a ti ellenségeteket, Moábot. És levonultak ő utána, és elfoglalák a Jordán réveit, melyek Moáb felé vezettek, és nem engedtek azokon senkit általkelni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'És leöltek a Moábiták közül akkor mintegy tízezer embert, mind erős és vitéz férfiakat, úgy hogy egy sem menekült el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'Így aláztatott meg Moáb abban az időben Izráel keze alatt. És megnyugovék a föld nyolczvan esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'Ő utána pedig Sámgár, Anáthnak fia volt bíró, a ki hatszáz Filiszteus férfiút ölt meg egy ökörösztökével, és megszabadítá ő is Izráelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'De az Izráel fiai azután is gonoszul cselekedének az Úrnak szemei előtt, mikor Ehud meghalt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'Azért adá őket az Úr Jábinnak, a Kanaán királyának kezébe, a ki Hásorban uralkodott; seregének vezére pedig Sisera volt. Ez a pogányok városában, Harósethben lakott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'És kiáltának az Izráel fiai az Úrhoz, mert kilenczszáz vas-szekere volt, és húsz esztendeig zsarnokoskodott az Izráel fiai felett erőszakkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'Ebben az időben Debora, a prófétanő, a Lappidoth felesége volt biró Izráelben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, 'És ő a Debora-pálmája alatt lakott Ráma és Béthel között, az Efraim hegyén, és ide jöttek fel hozzá az Izráel fiai törvényre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'És elkülde és hivatá Bárákot, az Abinoám fiát, Kedes-Nafthaliból, és monda néki: Avagy nem parancsolta-é meg az Úr, Izráelnek Istene: Menj és vonulj fel a Thábor hegyére, és végy magadhoz tízezer embert a Nafthali és a Zebulon fiai közül?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'És te ellened kihozom a Kison patakjához Siserát, Jábin hadvezérét, az ő szekereit és seregét, és kezedbe adom őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'És monda néki Bárák: Ha velem jösz, elmegyek; de ha nem jösz el velem, én sem megyek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, 'Ki felele: Elmenvén elmegyek te veled, csakhogy nem a tied lesz a dicsőség az útban, a melyre mégy, mert asszony kezébe adja az Úr Siserát. És felkele Debora, és elméne Bárákkal Kedes felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'Összegyűjté annakokáért Bárák Zebulont és Nafthalit Kedesbe, és elvive magával tízezer embert, és elméne vele Debora is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, 'A Keneus Héber pedig elvált a Keneusoktól, Hobábnak, a Mózes ipának fiaitól, és sátorát a Saanaim tölgyesénél vonta fel, mely Kedes mellett van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'Hírül vivék pedig Siserának, hogy Bárák, az Abinoám fia felvonult a Thábor hegyére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'Egybegyűjté azért Sisera minden szekereit, a kilenczszáz vas-szekeret, és egész népét, mely vele volt, a pogányok városából, Harósethből, a Kison patakjához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'És monda Debora Báráknak: Kelj fel, mert ez a nap az, a melyen kezedbe adja az Úr Siserát! hisz maga az Úr vezet téged! És alájöve Bárák a Thábor hegyéről, és a tízezer ember ő utána.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'És megrettenté az Úr Siserát minden szekereivel és egész táborával fegyvernek élivel Bárák előtt, anynyira, hogy Sisera leugrott szekeréről, és gyalog futott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'Bárák pedig a szekereket és a tábort egész Harósethig, a pogányok városáig űzé, és Siserának egész tábora elhulla fegyvernek éle miatt, még csak egyetlen egy sem maradt meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'Sisera pedig gyalog futott Jáhelnek, a Keneus Héber feleségének sátoráig, mert béke volt Jábin között, Hásor királya között, és a Keneus Héber háznépe között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'És kiméne Jáhel Sisera elé, és monda néki: Jőjj be Uram, jőjj be hozzám, ne félj! És betére ő hozzá a sátorba, és betakará őt lasnakkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'Az pedig monda néki: Adj kérlek innom egy kis vizet, mert szomjúhozom. És megnyita ez egy tejes tömlőt, és ada néki inni, és betakará őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'És az annakfelette monda néki: Állj a sátor ajtajába, és ha valaki jőne és kérdezne, és ezt mondaná: Van-é itt valaki? mondjad: Nincsen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'Ekkor Jáhel, a Héber felesége vevé a sátorszöget, és pőrölyt vőn kezébe, és beméne ő hozzá halkan, és beveré a szöget halántékába, úgy hogy beszegeződék a földbe. Amaz pedig nagy fáradtság miatt mélyen aludt vala, és így meghala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'És ímé, a mint Bárák űzve keresné Siserát, Jáhel kiméne elébe, és monda néki: Jöszte és megmutatom néked az embert, a kit keressz. És beméne ő hozzá, és ímé Sisera ott feküdt halva, és a szög halántékában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'Így alázá meg Isten azon a napon Jábint, a Kanaán királyát az Izráel fiai előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'Az Izráel fiainak keze pedig mind jobban ránehezedék Jábinra, a Kanaán királyára, mígnem kiirták Jábint, a Kanaán királyát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'Énekelt pedig Debora és Bárák, az Abinoám fia azon a napon, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, 'Hogy a vezérek vezettek Izráelben, Hogy a nép önként kele föl: áldjátok az Urat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'Halljátok meg királyok, figyeljetek fejedelmek! Én, én az Úrnak éneket mondok, Dícséretet zengek az Úrnak, az Izráel Istenének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'Uram, mikor Szeirből kijövél, Mikor lépdelél Edom mezejéről: Megrendült a föld, csepegett az ég, A föllegek is víztől áradának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'A hegyek megrendültek az Úrnak orczája előtt, Még ez a Sinai is, az Úrnak, az Izráel Istenének színe előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'Sámgárnak, az Anath fiának napjaiban, Jáhel idejében pihentek az utak, És az útonjárók tekervényes ösvényekre tértek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'Megszüntek a kerítetlen helyek Izráelben, megszüntek végképen, Mígnem én Debora felkelék, Felkelék Izráel anyjaként.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, 'Új isteneket ha választott a nép, Mindjárt kigyúlt a harcz a kapuk előtt; De paizs, és dárda avagy láttatott-é A negyvenezereknél az Izráel között?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'Szívem azoké, kik parancsolnak Izráelben, Kik a nép közül önként ajánlkoztak: áldjátok az Urat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'Kik ültök fehér szamarakon, Kik ültök a szőnyegeken És a kik gyalog jártok: mind énekeljetek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'Az íjászok szavával a vízmerítők között, Ott beszéljék az Úrnak igazságát, Az ő faluihoz való igazságit Izráelben. Akkor újra a kapukhoz vonul az Úr népe!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, 'Kelj fel, kelj fel Debora! Serkenj fel, serkenj fel, mondj éneket! Kelj fel Bárák és fogva vigyed foglyaidat, Abinoám fia!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'Akkor lejött a hősök maradéka; Az Úrnak népe lejött hozzám a hatalmasok ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'Efraimból, kiknek gyökere Amálekben, Utánad Benjámin, a te néped közé; Mákirból jöttek le vezérek, És Zebulonból, kik a vezéri pálczát tartják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'És Issakhár fejedelmei Deborával, És mint Issakhár, úgy Bárák A völgybe rohan követőivel. Csak a Rúben patakjainál Vannak nagy elhatározások.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, 'Miért maradtál ülve a hodályban? Hogy hallgasd nyájad bégetéseit?! Rúben patakjainál nagyok voltak az elhatározások!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'Gileád a Jordánon túl pihen. Hát Dán miért időzik hajóinál? Áser a tenger partján ül és nyugszik öbleinél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'De Zebulon, az halálra elszánt lelkű nép, És Nafthali, a mezőség magaslatain!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'Királyok jöttek, harczoltanak; Akkor harczoltak a Kanaán királyai Taanaknál, Megiddó vizénél; De egy darab ezüstöt sem vettenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'Az égből harczoltak, A csillagok az ő helyökből vívtak Siserával!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'A Kison patakja seprette el őket; Az ős patak, a Kison patakja! Végy erőt én lelkem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'Akkor csattogtak a lovak körmei A futás miatt, lovagjaik futásai miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, 'Átkozzátok Mérozt – mond az Úr követje, – Átkozva-átkozzátok annak lakosait! Mert nem jöttek az Úrnak segítségére, Az Úrnak segélyére vitézei közé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'De áldott legyen az asszonyok felett Jáhel, A Keneus Héber felesége, A sátorban lakó nők felett legyen áldott!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'Az vizet kért, ő tejet adott, Fejedelmi csészében nyújtott tejszínét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'Balját a szegre, Jobbját pedig a munkások pőrölyére nyújtotta, És ütötte Siserát, szétzúzta fejét, És összetörte, általfúrta halántékát,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'Lábainál leroskadt, elesett, feküdt, Lábai között leroskadt, elesett; A hol leroskadt, ott esett el megsemmisülve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'Kinézett az ablakon, és jajgatott Siserának anyja a rostélyzat mögül: „Miért késik megjőni szekere? Hol késlekednek kocsijának gördülései?”');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'Fejedelemasszonyinak legokosabbjai válaszolnak néki; Ő egyre csak azok szavait ismételgeti:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, '„Vajjon nem zsákmányra találtak-é, s mostan osztozkodnak? Egy-két leányt minden férfiúnak; A festett kelmék zsákmányát Siserának; Tarka szövetek zsákmányát, tarkán hímzett öltözeteket, Egy színes kendőt, két tarka ruhát nyakamra, mint zsákmányt.”');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'Így veszszenek el minden te ellenségid, Uram! De a kik téged szeretnek, tündököljenek mint a kelő nap az ő erejében! És megnyugovék a föld negyven esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'És gonoszul cselekedének az Izráel fiai az Úrnak szemei előtt, azért adá őket az Úr a Midiániták kezébe hét esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'És hatalmat vőn a Midiániták keze az Izráelen, és a Midiánitáktól való féltökben készítették magoknak az Izráel fiai azokat a barlangokat, rejtekhelyeket és erősségeket, a melyek a hegységben vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'Mert ha vetett Izráel, mindjárt ott termettek a Midiániták, az Amálekiták és a Napkeletnek fiai, és rájok törtek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'És táborba szálltak ellenök, és pusztították a földnek termését egész addig, a merre Gázába járnak, és nem hagytak élésre valót Izráelben, sem juhot, sem ökröt, sem szamarat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'Mert barmaikkal és sátoraikkal vonultak föl; csapatosan jöttek, mint a sáskák, úgy hogy sem nékik magoknak, sem tevéiknek nem volt száma, és ellepték a földet, hogy elpusztítsák azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'Mikor azért igen megnyomorodott az Izráel a Midiániták miatt, az Úrhoz kiáltának az Izráel fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'Mikor pedig kiáltottak vala az Izráel fiai az Úrhoz Midián miatt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'Prófétát külde az Úr az Izráel fiaihoz, és monda nékik: Azt mondja az Úr, Izráel Istene: Én vezettelek fel titeket Égyiptomból, és hoztalak ki titeket a szolgálatnak házából,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'És én mentettelek meg benneteket az Égyiptombeliek kezéből, és minden nyomorgatóitoknak kezökből, a kiket kiűztem előletek, és néktek adtam az ő földjüket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'És mondék néktek: Én, az Úr, vagyok a ti Istenetek; ne féljétek az Emoreusok isteneit, kiknek földén laktok; de ti nem hallgattatok az én szómra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'És eljöve az Úrnak angyala, és leüle ama cserfa alatt, a mely Ofrában van, a mely az Abiézer nemzetségéből való Joásé vala, és az ő fia Gedeon épen búzát csépelt a pajtában, hogy megmentse a Midiániták orczája elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'Ekkor megjelenék néki az Úrnak angyala, és monda néki: Az Úr veled, erős férfiú!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'Gedeon pedig monda néki: Kérlek uram, ha velünk van az Úr, miért ért bennünket mindez? és hol vannak minden ő csoda dolgai, a melyekről beszéltek nékünk atyáink, mondván: Nem az Úr hozott-é fel minket Égyiptomból?! Most pedig elhagyott minket az Úr, és adott a Midiániták kezébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'És az Úr hozzá fordula, és monda: Menj el ezzel a te erőddel, és megszabadítod Izráelt Midián kezéből. Nemde, én küldelek téged?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, 'És monda néki: Kérlek uram, miképen szabadítsam én meg Izráelt? Ímé az én nemzetségem a legszegényebb Manasséban, és én vagyok a legkisebb atyámnak házában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'És monda néki az Úr: Én leszek veled, és megvered Midiánt, mint egy embert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'Ő pedig monda néki: Ha kegyelmet találtam a te szemeid előtt, kérlek, adj nékem valamely jelt, hogy te szólasz én velem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'El ne menj kérlek innen, míg vissza nem jövök hozzád, és ki nem hozom az én áldozatomat, és le nem teszem elődbe. Az pedig monda: Én itt leszek, míg visszatérsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'Gedeon pedig elméne, és elkészíte egy kecskegödölyét és egy efa lisztből kovásztalan pogácsákat, és betevé a húst egy kosárba, és a hús levét fazékba, és kivivé hozzá a cserfa alá, és felajánlá néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'És monda néki az Isten angyala: Vegyed a húst és a kovásztalan kenyereket, és rakd erre a kősziklára, és a hús levét öntsd rá. És úgy cselekedék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'Ekkor kinyújtá az Úrnak angyala pálczájának végét, mely kezében vala, és megérinté a húst, és a kovásztalan kenyeret; és tűz jött ki a kősziklából, és megemészté a húst és a kovásztalan kenyereket. Az Úrnak angyala pedig eltünt az ő szemei elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'Látván pedig Gedeon, hogy az Úrnak angyala volt az, monda Gedeon: Jaj nékem Uram, Istenem! mert az Úrnak angyalát láttam színről színre!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'És monda néki az Úr: Békesség néked! ne félj, nem halsz meg!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'És építe ott Gedeon oltárt az Úrnak, és nevezé azt Jehova-Salomnak (azaz: az Úr a béke), mely mind e mai napig megvan az Abiézer nemzetségének városában, Ofrában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'És lőn ugyanazon éjjel, hogy monda az Úr néki: Végy egy tulkot atyádnak ökrei közül, és egy másik tulkot, a mely hét éves, és rontsd le a Baál oltárát, a mely a te atyádé és a berket, a mely a mellett van, vágd ki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'És építs oltárt az Úrnak, a te Istenednek, ennek a megerősített helynek tetején alkalmatos helyen, és vedd a második tulkot, és áldozd meg égőáldozatul a berek fájával, a melyet kivágsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'Ekkor Gedeon tíz férfiút vőn maga mellé az ő szolgái közül, és a képen cselekedék, a mint megmondotta vala néki az Úr. De miután félt atyjának háznépétől és a városnak férfiaitól ezt nappal cselekedni, éjszaka tevé meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'Mikor aztán felkeltek reggel a városnak férfiai, íme már össze volt törve a Baál oltára, és levágva a mellette levő berek, és a második tulok égőáldozatul azon az oltáron, a mely építteték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'És mondának egyik a másikának: Ki cselekedte ezt? És mikor utána kérdezősködtek és tudakozódtak, azt mondották: Gedeon, a Joás fia cselekedte ezt a dolgot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'Akkor mondának a városnak férfiai Joásnak: Add ki fiadat, meg kell halnia, mert lerontotta a Baál oltárát és mert kivágta a berket, a mely mellette volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'Joás pedig monda mindazoknak, a kik körülötte állának: Baálért pereltek ti? Avagy ti oltalmazzátok-é őtet? Valaki perel ő érette, ölettessék meg reggelig. Ha isten ő, hát pereljen ő maga, hogy oltára lerontatott!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'És azon a napon elnevezték őt Jerubbaálnak, mondván: Pereljen ő vele Baál, mert lerontotta az ő oltárát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'És mikor az egész Midián és Amálek és a Napkeletiek egybegyűlének, és általkeltek a Jordánon, és tábort jártak a Jezréel völgyében:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'Az Úrnak lelke megszállotta Gedeont, és megfúván a harsonákat, egybehívá az Abiézer házát, hogy őt kövesse.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'És követeket külde egész Manasséba, és egybegyűle az is ő utána; és követeket külde Aserbe és Zebulonba és Nafthaliba, és feljövének eleikbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'És monda Gedeon az Istennek: Ha csakugyan az én kezem által akarod megszabadítani Izráelt, a miképen mondottad,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'Íme egy fürt gyapjat teszek a szérűre, és ha csak maga a gyapjú lesz harmatos, míg az egész föld száraz leénd: erről megtudom, hogy valóban az én kezem által szabadítod meg Izráelt, a mint mondottad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'És úgy lőn. Mert mikor másnap reggel felkelt, és megszorítá a gyapjat, harmatot facsart ki a gyapjúból, egy tele csésze vizet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'És monda Gedeon az Istennek: Ne gerjedjen fel a te haragod én ellenem, hogy még egyszer szólok. Hadd tegyek kísérletet, kérlek, még egyszer e gyapjúval. Legyen, kérlek, szárazság csak a gyapjún, és harmat az egész földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'És úgy cselekedék Isten azon az éjszakán, és lőn szárazság csak magán a gyapjún, míg az egész földön harmat lőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'Felkele pedig jó reggel Jerubbaál – ez Gedeon – és az egész nép, mely vele volt, és táborba szállának a Haród kútjánál, és a Midián tábora tőle északra volt, a Moré halomtól fogva, a völgyben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'És monda az Úr Gedeonnak: Több ez a nép, mely veled van, hogysem kezébe adhatnám Midiánt; Izráel még dicsekednék velem szemben, mondván: Az én kezem szerzett szabadulást nékem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'Azért kiálts a népnek füle hallatára, mondván: A ki fél és retteg, térjen vissza, és menjen el a Gileád hegységről. És visszatérének a nép közül huszonkétezeren, és csak tizezeren maradának ott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'És monda az Úr Gedeonnak: Még ez a nép is sok; vezesd őket le a vízhez, és ott megpróbálom őket néked, és a melyikről azt mondom néked: Ez menjen el veled, az menjen el veled; de bármelyikről azt mondom: Ez ne menjen el veled, az ne is menjen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'És levezette a népet a vízhez, és monda az Úr Gedeonnak: Mindazokat, a kik nyelvökkel nyalnak a vízből, mint a hogyan nyal az eb, állítsd külön, valamint azokat is, a kik térdeikre esnek, hogy igyanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'És lőn azoknak száma, a kik kezökkel szájokhoz véve nyaldosák a vizet, háromszáz férfiú; a nép többi része pedig mind térdre esve ivott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'És monda az Úr Gedeonnak: E háromszáz férfiú által szabadítlak meg titeket, a kik nyaldosták vala a vizet, és adom Midiánt kezedbe; a többi nép pedig menjen el, kiki a maga helyére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'És ők kezökbe vevék a népnek útravalóját és kürtjeit. Az Izráel többi férfiait pedig mind elküldötte, mindeniket a maga hajlékába, és csak a háromszáz férfiút tartotta meg. A Midián tábora pedig alatta feküdt a völgyben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'És monda néki az Úr azon az éjszakán: Kelj fel, menj alá a táborba, mert kezedbe adtam őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'Ha pedig félsz lemenni, menj le te és Púra, a te szolgád a táborba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'És hallgasd meg, mit beszélnek, hogy annakutána megerősödjenek a te kezeid, és menj alá a táborba. És lement ő és Púra, az ő szolgája a fegyveresek szélső részéhez, a kik a táborban voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'És a Midiániták és az Amálekiták és a Napkeletiek minden fiai úgy feküdtek a völgyben, mint a sáskák sokasága, és tevéiknek nem volt száma sokaságuk miatt, mint a fövenynek, mely a tenger partján van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'Mikor pedig Gedeon oda ment, ímé az egyik férfiú épen álmát beszélte el a másiknak, és monda: Ímé álmot álmodtam, hogy egy sült árpakenyér hengergett alá a Midiániták táborára, és mikor a sátorig jutott, megütötte azt, úgy hogy eldőlt, és felfelé fordította azt, és a sátor ledőlt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, 'A másik aztán felele és monda: Nem egyéb ez, mint Gedeonnak, a Joás fiának, az Izráelből való férfiúnak fegyvere, az ő kezébe adta az Isten Midiánt és egész táborát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'És mikor hallotta Gedeon az álomnak elbeszélését és annak magyarázatát, meghajtá magát, és visszatére az Izráel táborába, és monda: Keljetek fel, mert kezetekbe adta az Úr a Midián táborát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'És a háromszáz embert három csapatba osztá el, és mindeniknek kezébe egy-egy kürtöt adott, és üres korsókat és fáklyákat e korsókba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'És monda nékik: Én reám vigyázzatok, és úgy cselekedjetek. És ímé én bemegyek a tábornak szélibe, és akkor, a mint én cselekszem, ti is úgy cselekedjetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'Ha én a kürtbe fúvok és mindazok, a kik velem vannak, akkor ti is fújjátok meg a kürtöket az egész tábor körül, és ezt kiáltsátok: az Úrért és Gedeonért!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'És leméne Gedeon, és az a száz férfiú, a ki vele volt, a tábor széléhez a középső éjjeli őrség kezdetén, a mikor épen az őrség felváltatott, és kürtölének a kürtökkel és összetörék a korsókat, a melyek kezökben valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'És kürtölt mind a három csapat a kürtökkel, és összetörték a korsókat, és balkezükben tartották a fáklyákat, jobb kezükben pedig a kürtöket, hogy kürtöljenek, és kiáltának: Fegyverre! Az Úrért és Gedeonért!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'És mindenik ott állott a maga helyén a tábor körül. Erre az egész tábor futásnak eredt, és kiáltozott, és menekült.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'És mikor a háromszáz ember belefújt kürtjébe, fordítá az Úr kinek-kinek fegyverét az ő felebarátja ellen az egész táborban, és egész Béth-Sittáig futott a tábor, Czererah felé, Abelmehola határáig, Tabbathon túl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'És egybegyűjtettek az Izráel férfiai Nafthaliból, Áserből és az egész Manasséből, és úgy űzék a Midiánitákat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'És követeket külde Gedeon az egész Efraim hegységbe, ezt izenvén: Jőjjetek alá a Midiániták ellen és foglaljátok el előttök a vizeket Béthbaráig, és a Jordánt. És egybegyűle Efraimnak minden férfia, és elzárák a vizeket Béthbaráig, és a Jordánt is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'És elfogák Midiánnak két fejedelmét, Orebet és Zéebet, és megölék Orebet az Oreb kőszikláján, és Zéebet megölék a Zéeb pajtájában, és űzték a Midiánitákat. Orebnek és Zéebnek fejét pedig elvivék Gedeonnak a Jordánon túl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'És mondának az Efraim férfiai néki: Miért cselekedted azt mi velünk, hogy el nem hívtál minket, mikor a Midián ellen való hadakozásra indultál? És erősen feddőzének vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'Ő pedig monda nékik: Vajjon cselekedtem-é én olyan dolgot, mint ti? Nem többet ér-é Efraim szőlőmezgerlése, mint Abiézer egész szüretje?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'Kezetekbe adta az Isten Midiánnak fejedelmeit, Orebet és Zéebet; hát mit cselekedhettem én olyat, mint ti?! Akkor lecsendesedék az ő felháborodott lelkök, mikor e beszédet mondotta vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'Mikor pedig Gedeon a Jordánhoz ére, átkele azzal a háromszáz férfiúval, a kik vele valának, az üldözéstől kifáradottan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'És monda a Sukkót férfiainak: Adjatok, kérlek, e népnek, mely engem követ, kenyeret, mert fáradtak, én pedig űzöm Zébát és Sálmunáht, Midiánnak királyait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'És mondának Sukkót előljárói: Zébának és Sálmunáhnak öklét már kezedben tartod-é, hogy kenyeret adjunk a te seregednek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'Gedeon pedig monda: Ha kezembe adja az Úr Zébát és Sálmunáht, a pusztának tüskéivel és csalánjaival csépelem meg testeteket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'És felmenvén onnan Pénuelbe, hasonlóképen szóla azoknak is, és Pénuel férfiai épen úgy feleltek néki, a mint feleltek volt a Sukkót férfiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'És szóla a Pénuel férfiainak is, mondván: Mikor békességben visszatérek, lerontom ezt a tornyot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'Zéba pedig és Sálmunáh Kárkorban valának, és az ő seregök velök, mintegy tizenötezeren, mind a kik megmaradtak a Napkeletieknek egész táborából. Az elesettek száma százhúszezer fegyverfogható férfiú volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'És felméne Gedeon a sátorban lakók útján keletre Nobahtól és Jogbehától, és szétverte a tábort, pedig a tábor biztonságban érezte magát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'És Zéba és Sálmunáh elfutottak; de ő utánok ment, és elfogta a Midián két királyát: Zébát és Sálmunáht, és szétszórta az egész tábort.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'Mikor pedig Gedeon, a Joás fia, visszatért a harczból a Heresz hágójától:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'Megfogott egy gyermeket a sukkótbeliek közül, és tudakozódott tőle. Ez pedig felírta néki Sukkótnak előljáróit és véneit, hetvenhét férfiút.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'Mikor aztán a Sukkót férfiaihoz ment vala, monda: Ímhol Zéba és Sálmunáh, a kik miatt gúnyolódtatok velem, mondván: Vajjon Zéba és Sálmunáh öklét már kezedben tartod-é, hogy kenyeret adjunk kifáradott embereidnek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'És előfogá a város véneit, és a pusztának töviseit és csalánjait vévén, megtanítá azokkal Sukkótnak férfiait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'Azután Pénuel tornyát rontá le, és a város férfiait ölte meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'És monda Zébának és Sálmunáhnak: Milyenek voltak azok a férfiak, a kiket a Thábor hegyén megöltetek? Ők pedig mondának: Mint a milyen te vagy, olyanok voltak ők is, és mindenik olyan arczú, mint egy-egy királyfi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, 'És monda: Az én atyámfiai, az én anyámnak fiai voltak azok. Él az Úr! ha életben hagytátok volna őket, én sem ölnélek meg titeket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'És monda Jéthernek, az ő elsőszülöttjének: Kelj fel, öld meg őket. De a fiú nem húzta ki kardját, mert fél vala, mivelhogy még gyermek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'És monda Zéba és Sálmunáh: Kelj fel te és te ölj meg minket, mert a milyen a férfiú, olyan az ő ereje. És felkele Gedeon, és megölé Zébát és Sálmunáht, és elvevé az ő tevéiknek nyakán levő ékességeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'És mondának az Izráel férfiai Gedeonnak: Uralkodjál felettünk te és a te fiad és a te fiadnak fia, mert megszabadítottál bennünket a Midiániták kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'És monda nékik Gedeon: Én nem uralkodom felettetek, sem az én fiam nem fog uralkodni rajtatok. Az Úr uralkodik ti felettetek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'Azután monda nékik Gedeon: Egyet kívánok csak tőletek, hogy adja nékem mindenikőtök a zsákmányul ejtett fülön függőket; mert arany fülön függőik voltak azoknak, mivelhogy Izmaeliták valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, 'És mondának: Örömest néked adjuk. És leterítettek egy ruhát, és mindenki arra dobá a fülön függőket, melyeket prédául ejtett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'Az arany fülön függőknek pedig, a melyeket elkért, súlya ezerhétszáz arany siklus volt, amaz ékességeken, függőkön és bíborruhákon kívül, a melyek a Midián királyain voltak, és az aranylánczok nélkül, a melyek tevéik nyakán valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'És készíte abból Gedeon efódot, és helyhezteté azt a maga városában, Ofrában, és ott paráználkodott azután az egész Izráel, és lőn ez Gedeonnak és házanépének tőrbeejtésére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'Így aláztattak meg a Midiániták az Izráel fiai előtt, és nem is emelték fel azután már fejüket, és megnyugovék a föld negyven esztendeig Gedeon idejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'És hazatért Jerubbaál, a Joás fia, és megtelepedett otthon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'És Gedeonnak volt hetven fia, kik az ő ágyékából származtak, mert sok felesége volt néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'És az ő ágyasa is, a ki Sikemben volt, szült néki egy fiat, és nevezé azt Abiméleknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'És meghala Gedeon, a Joás fia, késő vénségében, és eltemetteték atyjának, Joásnak sírjába, Ofrában, Abiezer városában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'Lőn pedig, hogy mikor meghalt Gedeon, elfordulának az Izráel fiai az Úrtól, és a Baálokkal paráználkodának, és a Baál-Beritet tevék istenökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'És nem emlékezének meg az Izráel fiai az Úrról, az ő Istenökről, a ki őket megszabadította minden ellenségeik kezéből köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'És nem cselekedének irgalmasságot a Jerubbaál Gedeon házával mind ama jók szerint, a melyeket ő tett vala az Izráellel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'És elméne Abimélek, a Jerubbaál fia Sikembe, az ő anyjának atyjafiaihoz, és beszélt velök, valamint az ő anyja atyjának egész nemzetségével, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, 'Mondjátok meg, kérlek, Sikem minden férfiának hallatára, melyik jobb néktek, hogy hetven férfiú uralkodjék-é rajtatok, Jerubbaálnak minden fia, vagy pedig csak egy ember uralkodjék felettetek? És emlékezzetek meg arról, hogy én a ti csontotok és a ti testetek vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'És elmondották anyjának testvérei róla mind e beszédeket Sikem minden férfiainak füle hallatára, és Abimélek felé hajlott az ő szívök, mert azt mondák: Atyánkfia ő!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'És adának néki hetven ezüst pénzt a Baál-Beritnek házából, és ezzel holmi henyélő és hiábavaló embereket fogadott magának Abimélek, a kik őt követék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'És elméne atyjának házához Ofrába, és megölé testvéreit, Jerubbaál fiait, a hetven férfiút egy kövön, és csak Jóthám maradt meg, Jerubbaálnak legkisebb fia, mert ez elrejtőzött.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'És összegyülekezék Sikemnek egész polgársága, és Millónak egész háza, és elmenének és királylyá választák Abiméleket az alatt a magas tölgy alatt, a mely Sikemben áll.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'Mikor pedig ezt elbeszélték vala Jóthámnak, elment és megállott a Garizim hegy tetején, és nagy felszóval kiálta, és így szóla hozzájuk: Hallgassatok rám, Sikem férfiai, hogy reátok is hallgasson az Isten!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Egyszer elmenvén elmentek a fák, hogy királyt válaszszanak magoknak, és mondának az olajfának: Uralkodjál felettünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'De az olajfa így felelt nékik: Elhagyjam az én kövérségemet, a melylyel tisztelnek Istent és embereket, és elmenjek, hogy ingadozzam a fák felett?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'Akkor a fügefának szólottak a fák: Jer el te, és uralkodjál rajtunk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'De a fügefa is azt mondta nékik: Elhagyjam-é édességemet és jó gyümölcseimet, és elmenjek, hogy ingadozzam a fák felett?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'Azután a szőlőtőnek mondák a fák: Jer el te, uralkodjál rajtunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'Azonban a szőlőtő is azt mondta nékik: Elhagyjam-é mustomat, a mely isteneket és embereket vidámít, és elmenjek, hogy ingadozzam a fák felett?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'Mondának végre a fák mindnyájan a galagonyabokornak: Jer el te, uralkodjál mi rajtunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'És monda a galagonyabokor a fáknak: Ha igazán királylyá kentek engem magatok felett, jőjjetek el, nyugodjatok az én árnyékomban: de hogyha nem, jőjjön tűz ki a galagonyabokorból, és égesse meg a Libanonnak czédrusait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, 'Hát ti is most igazán és becsületesen cselekedtetek-é, hogy Abiméleket tettétek királylyá, és jól cselekedtetek-é Jerubbaállal és házanépével, és úgy bántatok-é vele, a mint megérdemelte?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, 'Mert érettetek harczolt atyám, és még életével is semmit nem gondolván, mentett meg titeket a Midiánnak kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, 'Ti pedig most felkeltetek az én atyámnak háza ellen, és megöltétek gyermekeit, hetven férfiút egy kövön, és királylyá választottátok Sikem férfiai felett Abiméleket, az ő szolgálójának fiát, mert atyátokfia!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'Ha igazán és becsületesen cselekedtetek Jerubbaállal és az ő házával a mai napon, örüljetek Abiméleknek, és örüljön ő is néktek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'De hogyha nem, jőjjön tűz ki Abimélekből, és emészsze meg Sikem férfiait és Milló házát, és származzék tűz Sikem férfiaiból és Milló házából, és emészsze meg Abiméleket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'És elfutott Jóthám, és elmenekült, és elment Beérbe az ő atyjafia, Abimélek elől, és ott telepedett meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'Mikor pedig uralkodék Abimélek Izráel felett három esztendeig:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'Egy gonosz lelket bocsátott Isten Abimélek és Sikem férfiai közé, és pártot ütöttek Sikem férfiai Abimélek ellen,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'Hogy eljőjjön a Jerubbaál hetven fián elkövetett kegyetlenség büntetése, és szálljon az ő vérök Abimélekre, testvérökre, a ki megölte őket, és Sikem férfiaira, a kik az ő kezeit megerősítették, hogy megölje az ő atyjafiait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'És lest vetének néki a Sikem férfiai a hegyeknek tetején, és kiraboltak mindenkit, a ki elment mellettök az úton, mely dolgot megmondák Abiméleknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'És eljött Gaál, Ebed fia és az ő atyjafiai, és bementek Sikembe, és bízának ő hozzá Sikem férfiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'Annyira, hogy kimenvén a mezőre, leszüretelték szőlőiket, mindjárt ki is taposták, és örömünnepet ültek, és bementek az ő istenöknek házába, és ettek és ittak, és szidalmazták Abiméleket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'És monda Gaál, Ebed fia: Kicsoda Abimélek és kicsoda Sekem, hogy szolgáljunk néki? Nem Jerubbaál fia-é ő, és nem Zebul-é az ő kormányzója? Ti szolgáljátok Hámornak, Sekem atyjának férfiait; de miért szolgálnánk mi?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, 'Csak volna az én kezemben e nép, majd elűzném Abiméleket. És monda Abiméleknek: Öregbítsd meg seregedet, és jőjj ki!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'Mikor pedig meghallotta Zebul, a városnak kormányzója, Gaálnak, az Ebed fiának beszédit, nagy haragra gyulladt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'És követeket küldött Abimélekhez Thormába, ezt izenvén: Ímé Gaál, az Ebed fia és az ő testvérei Sikembe jöttek, és fellázítják a várost te ellened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'Most azért készülj fel éjszaka, te és a te néped, mely veled van, és állj lesbe a mezőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'És reggel, napfelköltekor korán kelj fel, és törj a városra, és mikor ő és az ő népe kivonul ellened: cselekedjél vele a szerint, a mint akarod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'És felkelt Abimélek és az egész nép, a mely vele volt, éjszaka, és lesbe állottak Sikem ellen négy csapatban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'És kijött Gaál, az Ebed fia és megállott a város kapujának nyílásában. És felkelt Abimélek is, meg a nép is, mely vele volt, a lesből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'És a mint meglátta Gaál a csapatot, monda Zebulnak: Ímé nép jő alá a hegyeknek tetejéről. Zebul pedig monda néki: A hegyek árnyékát nézed férfiaknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'De Gaál csak folytatta beszédét, és monda: Ímé egy másik csapat meg az ország közepéből jő alá; a harmadik csapat pedig a jós-tölgyfa útján jő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'Ekkor monda néki Zebul: Hol van most szád, melylyel mondád: Kicsoda Abimélek, hogy szolgáljunk néki? Nem ez a nép-é az, a melyet kisebbítettél? No, most vonulj ki ellene, és harczolj vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'És kivonult Gaál Sikem polgárainak élén, és megütközött Abimélekkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'De Abimélek megfutamította, úgy hogy elmenekült előle, és sok sebesült elesett a kapu bejáratáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'Abimélek pedig Arumában maradt, és Zebul elűzte Gaált és atyjafiait, hogy ne lakjanak Sikemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'És lőn, hogy másnap kiméne a nép a mezőre, és megmondák Abiméleknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'És az vette az ő népét, és három csapatra osztotta el, és lesbe állott a mezőn; és látta, hogy ímé a nép jő ki a városból. Rájok támadt, és megverte őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'És Abimélek és az a csapat, a mely vele volt, megtámadta és megszállotta a város kapuját; a másik két csapat pedig megtámadta mind a mezőn levőket, és megverte őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'És Abimélek egész nap vívta a várost, mígnem bevette a várost, és a népet, mely benne volt, leölte: a várost pedig lerombolta, és behinté azt sóval.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'Mikor pedig ezt meghallották Sikem tornyának minden férfiai, az El-Berith isten házának várába mentek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'És mikor Abiméleknek elmondották, hogy Sikem tornyának minden férfiai ott gyűltek össze:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'Felment Abimélek a Sálmon hegyére, ő és az egész nép, mely vele volt, és fejszét vett kezébe, és faágakat vágott le, és azokat felszedte, és vállára rakta, és monda a népnek, a mely vele volt: A mit láttatok, hogy cselekedtem, ti is azt tegyétek gyorsan, mint én.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'Erre az egész népből kiki vágott magának ágakat, és követték Abiméleket, és lerakták a fát a vár körül, és tűzzel rájuk gyujtották a várat, úgy hogy meghaltak a Sikem tornyának minden férfiai, közel ezer férfi és asszony.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'Abimélek pedig elment Thébesbe, és táborba szállott Thébes ellen, és bevette azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'De egy erős torony volt a város közepén, és oda menekült minden férfi és asszony, és a városnak minden lakosa; ezt magukra zárták, és a toronynak padlására mentek fel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'És Abimélek oda ment a toronyig, és ostrom alá vette azt, és egészen a torony ajtajáig közeledett, hogy azt tűzzel égesse fel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'Akkor egy asszony egy malomkődarabot gördített le Abimélek fejére, és bezúzta koponyáját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'Ki mindjárt oda hívta fegyverhordozó apródját, és monda néki: Vond ki kardodat, és ölj meg engem, hogy ne mondják felőlem: Asszony ölte meg őt! És keresztülszúrta őt az apród, és meghalt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'Mikor pedig az Izráel férfiai látták, hogy Abimélek meghalt, kiki visszatért a maga helyére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'Így fizetett meg Isten Abiméleknek azért a gonoszságért, melyet atyja ellen elkövetett, hogy megölte hetven testvérét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'És a Sikem férfiainak fejére is visszahárított Isten minden rosszat, és reájuk szállott Jóthámnak, a Jerubbaál fiának átka.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'Támada pedig Abimélek után az Izráel megszabadítására Thóla, Puának, a Dodó fiának fia, Issakhár nemzetségéből való, a ki Sámirban lakott, az Efraim hegységben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'És bíráskodék Izráelben huszonhárom esztendeig, és meghala, és eltemetteték Sámirban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'Ő utána következett Jáir, a gileádbeli, és ítélé Izráelt huszonkét esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'Ennek harmincz fia volt, kik harmincz szamárcsikón nyargaltak, és volt nékik harmincz városuk, melyeket mind e mai napig Jáir faluinak neveznek, melyek Gileád földén vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'És meghalt Jáir, és eltemetteték Kámonban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'De az Izráel fiai újra gonoszul cselekedtek az Úrnak szemei előtt, mert szolgáltak a Baáloknak és Astarótnak, és Sziria isteneinek, és Sidon isteneinek, és Moáb isteneinek, és az Ammon fiai isteneinek, és a Filiszteusok isteneinek, és elhagyták az Urat, és nem szolgáltak néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'Felgerjedett azért az Úrnak haragja Izráel ellen, és adá őket a Filiszteusoknak és az Ammon fiainak kezökbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, 'És ezek szorongatták és nyomorgatták az Izráel fiait attól az évtől fogva tizennyolcz esztendőn keresztül, Izráelnek minden fiait a kik a Jordánon túl valának az Emoreusoknak földén, mely Gileádban van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'És átkeltek az Ammon fiai a Jordánon, hogy hadakozzanak Júda és Benjámin ellen és az Efraim háza ellen, és felette igen szorongattaték az Izráel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'Akkor az Úrhoz kiáltottak az Izráel fiai, mondván: Vétkeztünk te ellened, mert elhagytuk a mi Istenünket, és szolgáltunk a Baáloknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'Az Úr pedig monda az Izráel fiainak: Nemde én szabadítottalak-é meg benneteket az Égyiptombeliektől, az Emoreusoktól, az Ammon fiaitól, a Filiszteusoktól,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'És a Sidonbeliektől, az Amálekitáktól és a Maonitáktól, mikor titeket szorongattak, és ti én hozzám kiáltottatok, megszabadítottalak titeket az ő kezökből?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'És ti mégis elhagytatok engem, és idegen isteneknek szolgáltatok; annakokáért többé nem szabadítlak meg titeket ezután.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'Menjetek és kiáltsatok azokhoz az istenekhez, a kiket választottatok, szabadítsanak meg azok benneteket a ti nyomorúságtoknak idején.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'Felelének pedig az Izráel fiai az Úrnak: Vétkeztünk, cselekedjél úgy velünk, a mint jónak látszik a te szemeid előtt, csak most az egyszer szabadíts még meg, kérünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'És elvetették maguktól az idegen isteneket, és szolgáltak az Úrnak. És megesett az ő szíve az Izráel nyomorúságán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'És összegyülekeztek az Ammon fiai, és táborba szállottak Gileádban, és összegyűltek az Izráel fiai is, és Mispában táboroztak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'És Gileád népe és fejedelmei egyik a másikától kérdezgették: Ki az a férfiú, a ki megkezdi a harczot az Ammon fiai ellen? Legyen az feje Gileád összes lakóinak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'A Gileádból való Jefte pedig nagy hős volt, és egy parázna asszonynak volt a fia, s Jeftét Gileád nemzette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'De mikor Gileádnak a felesége is szült néki fiakat, és megnőttek az ő feleségének fiai: akkor elűzték Jeftét és azt mondták néki: Nem fogsz örökösödni atyánknak házában, mert más asszonynak vagy a fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'És elfutott Jefte az ő atyjafiai elől, és Tób földén telepedett meg, és henyélő emberek gyűltek össze Jefte körül, és együtt portyáztak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'És történt napok mulva, hogy az Ammon fiai harczba keveredtek Izráellel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'És lőn, hogy a mint harczolni kezdtek az Ammon fiai Izráellel, Gileád vénei elmentek, hogy visszahozzák Jeftét a Tób földéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, 'És mondának Jeftének: Jer el, és légy nékünk fejedelmünk, és harczoljunk az Ammon fiai ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'Jefte pedig monda Gileád véneinek: Avagy nem ti vagytok-é, a kik engem meggyűlöltetek, és kiűztetek atyámnak házából? És miért jöttetek most hozzám a ti nyomorúságtoknak idején?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'És mondának Gileád vénei Jeftének: Azért fordultunk most hozzád, hogy jőjj el velünk, és hadakozzál az Ammon fiai ellen, és légy mi nékünk fejünk, és Gileád minden lakosinak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'És monda Jefte Gileád véneinek: Ha visszavisztek engem, hogy hadakozzam az Ammon fiai ellen, és kezembe adja őket az Úr: igazán fejetekké leszek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'Akkor mondának Gileád vénei Jeftének: Az Úr a tanúnk, ha a te beszéded szerint nem cselekeszünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'És elment Jefte Gileád véneivel, és a nép a maga fejévé és fejedelmévé tette őt. És megmondá Jefte minden beszédit az Úr előtt Mispában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'És követeket küldött Jefte az Ammon fiainak királyához, ezt izenvén: Mi dolgom van nékem veled, hogy hozzám jöttél, hogy hadakozzál az én földem ellen?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'És monda az Ammon fiainak királya Jefte követeinek: Mert elvette Izráel az én földemet, mikor Égyiptomból feljött, az Arnontól fogva Jabbókig és a Jordánig, most te add azokat vissza békességgel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'Ismét külde pedig Jefte követeket az Ammon fiainak királyához;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'És monda néki: Ezt izeni Jefte: Nem vette el Izráel sem a Moáb földét, sem az Ammon fiainak földét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'Mert mikor kijött Égyiptomból, a pusztában bolyongott Izráel egész a Veres tengerig, és mikor Kádesbe ért,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'Követeket küldött Izráel Edom királyához, mondván: Hadd menjek át, kérlek, országodon; de Edom királya nem hallgatta meg. Majd Moáb királyához is küldött; de ez sem engedé, és így Izráel ott maradt Kádesben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'És mikor tovább vándorolt a pusztában, megkerülte Edom földét és Moáb földét, és napkelet felől érkezett a Moáb földéhez, és ott táborozott túl az Arnonon; de Moáb határába nem ment be, mert az Arnon Moáb határa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'Ekkor követeket küldött Izráel Szihonhoz, az Emoreusok királyához, Hesbon királyához, és monda néki Izráel: Hadd menjek át, kérlek, országodon az én helyemre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'De Szihon nem hitt Izráelnek, hogy átvonul az ő határán, hanem összegyűjtötte Szihon az ő egész népét, és táborba szállott Jahásban, és harczolt az Izráel ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'Az Úr, az Izráel Istene pedig Szihont és egész népét Izráel kezébe adta, és megverték őket, és elfoglalta Izráel az Emoreusoknak, ama föld lakóinak, egész országát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'És birtokába vette az Emoreusok egész határát, az Arnontól fogva Jabbókig, és a pusztától a Jordánig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'És mikor az Úr, az Izráel Istene maga űzte ki az Emoreusokat az ő népe, az Izráel elől, most te akarnád ezt elfoglalni?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'Hát nem úgy van-é, hogy a mit bírnod adott néked Kámos, a te istened, azt bírod? Mi meg mindazoknak örökségét bírjuk, a kiket az Úr, a mi Istenünk űzött ki mi előlünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'És most vajjon mennyivel vagy te különb Báláknál, Czippor fiánál, Moáb királyánál? Avagy versengett-é ez az Izráellel, és hadakozott-é valaha ellenük?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'Míg Izráel Hesbonban és annak mezővárosaiban, Aroerben és ennek mezővárosaiban és az Arnon mellett való összes városokban háromszáz esztendőn át lakott: miért nem foglaltátok el abban az időben?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'Én nem vétettem te ellened, hanem te cselekszel velem gonoszt, hogy harczolsz ellenem. Az Úr, a biró, tegyen ma ítéletet az Izráel és az Ammon fiai között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'De az Ammon fiainak királya nem hallgatott Jefte szavaira, a melyeket izent néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'Jeftén pedig lőn az Úrnak lelke, és általméne Gileádon és Manassén, és általméne Gileád Mispén, és Gileád Mispéből felvonult az Ammon fiai ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'És fogadást tőn Jefte az Úrnak, és monda: Ha mindenestől kezembe adod az Ammon fiait:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'Akkor valami kijövénd az én házamnak ajtaján előmbe, mikor békével visszatérek az Ammon fiaitól, legyen az Úré, és megáldozom azt egészen égőáldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'És kivonult Jefte az Ammon fiai ellen, hogy hadakozzék velök, és kezébe adá néki azokat az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'És veré őket Aroertől fogva mindaddig, míg mennél Minnithbe, húsz városon át, és egész Abel-Keraminig nagy vérontással, és az Ammon fiai megaláztattak az Izráel fiai előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'Mikor pedig méne Jefte Mispába az ő házához: ímé az ő leánya jött ki eleibe dobokkal és tánczoló sereggel; ez volt az ő egyetlenegyje, mert nem volt néki kivülötte sem fia, sem leánya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'És mikor meglátta őt, megszaggatá ruháit, és monda: Óh leányom, de megszomorítottál és megháborítottál engem! Mert én fogadást tettem az Úrnak, és nem vonhatom vissza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'Az pedig monda néki: Atyám, ha fogadást tettél az Úrnak, úgy cselekedjél velem, a mint fogadtad, miután az Úr megadta az ellenségiden: az Ammon fiain való bosszút.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'És monda az ő atyjának: Csak azt az egyet tedd meg nékem; ereszsz el engem két hónapra, hadd menjek el és vonulhassak félre a hegyekre, hogy sírjak szűzességemen leánybarátaimmal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, 'És ő monda: Menj el. És elbocsátá őt két hónapra. Az pedig elment és az ő leánybarátai, és siratta az ő szűzességét a hegyeken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'És a két hónap elteltével visszatért atyjához, és betöltötte az ő felőle való fogadást, a melyet tett, és ő soha nem ismert férfiút. És szokássá lett Izráelben,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'Hogy esztendőnként elmentek az Izráel leányai, hogy dicsőítsék a gileádbeli Jefte leányát esztendőnként négy napon át.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'Összegyűlének pedig az Efraim férfiai, és általmenének északra, és mondának Jeftének: Miért szállottál harczba az Ammon fiaival, és miért nem hívtál minket is, hogy menjünk veled? Most azért a te házadat megégetjük te veled együtt tűzzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'És monda Jefte nékik: Nagy háborúságunk volt, nékem és az én népemnek, az Ammon fiaival: és hívtalak titeket; de ti nem szabadítottatok meg engem az ő kezökből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'És a mikor láttam, hogy ti nem akartok segíteni, koczkára vetém saját életemet, és általmenék az Ammon fiai ellen, az Úr pedig kezembe adta őket. És most miért jöttetek fel hozzám, hogy hadakozzatok én ellenem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'És ekkor egybegyűjté Jefte Gileádnak minden férfiait, és megtámadta Efraimot, és megverték Gileád férfiai Efraimot, mert azt mondották: Efraim szökevényei vagytok ti, kik Gileádban, Efraim és Manassé között laktok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'És elfoglalák a Gileádbeliek Efraim előtt a Jordán réveit, és lőn, hogy mikor az Efraim közül való menekülők azt mondják vala: Hadd menjek által: azt kérdezték tőlük a gileádbeli férfiak Efraimbeli vagy-é? És ha az azt mondotta: nem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'Akkor azt mondák néki: Mondd: Sibboleth! És ha Szibbolethet mondott, mert nem tudta úgy kimondani, akkor megfogták őt és megölték a Jordán réveinél, és elesett ott abban az időben az Efraimbeliek közül negyvenkétezer.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'Ítélé pedig Jefte Izráelt hat esztendeig, és meghalt Jefte, a Gileádbeli, és eltemetteték Gileád egyik városában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'És ítélé ő utána az Izráelt Ibsán, ki Bethlehemből való volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'Ennek harmincz fia volt és harmincz leányt házasított ki, és harmincz leányt hozott be kivül az ő fiainak, és itélé Izráelt hét esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'És meghala Ibsán, és eltemetteték Bethlehemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'És bíráskodék ő utána Élon Izráelben, ki a Zebulon nemzetségéből való volt, és ítélé Izráelt tíz esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'És meghalt Élon, a Zebulonbeli, és eltemetteték Ajalonban, Zebulon földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'Ő utána pedig Abdon bíráskodott Izráelben, a Pireathonita Hillel fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'Ennek negyven fia és harmincz unokája volt, kik hetven szamárcsikón nyargaltak, és ítélte Izráelt nyolcz esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'És meghalt Abdon, a Pireathonita Hillel fia, és eltemetteték Pireathonban, Efraim földén, az Amálekiták hegységén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'Az Izráel fiai pedig újra gonoszul cselekedtek az Úrnak szemei előtt, azért az Úr őket a Filiszteusoknak kezébe adá negyven esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'És élt ebben az időben egy férfiú Czórából, a Dán nemzetségéből való, névszerint Manoah, kinek felesége magtalan volt, és nem szült.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'És megjelent az Úrnak angyala az asszonynak, és monda néki: Ímé most magtalan vagy, és nem szültél; de terhes leszesz, és fiat szülsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'Azért most megójjad magad, és ne igyál se bort, se más részegítő italt, és ne egyél semmi tisztátalant.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'Mert íme terhes leszesz, és fiat szülsz, és beretva ne érintse annak fejét, mert Istennek szenteltetett lesz az a gyermek anyjának méhétől fogva, és ő kezdi majd megszabadítani Izráelt a Filiszteusok kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'És elment az asszony, és elbeszélte ezt férjének, mondván: Istennek egy embere jöve hozzám, kinek tekintete olyan volt, mint az Isten angyalának tekintete, igen rettenetes, úgy hogy meg sem mertem kérdezni, hogy honnan való, és ő sem mondotta meg nékem a nevét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, 'És monda nékem: Íme terhes leszesz, és fiat fogsz szülni; azért most se bort, se más részegítő italt ne igyál, és semmi tisztátalant ne egyél, mert Istennek szentelt lesz az a gyermek, anyja méhétől fogva halála napjáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'Manoah pedig az Úrhoz könyörgött, és monda: Kérlek, Uram! az Istennek amaz embere, a kit küldöttél volt, hadd jőjjön el ismét hozzánk, és tanítson meg minket, hogy mit cselekedjünk a születendő gyermekkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'És meghallgatá az Isten Manoah kérését, mert az Istennek angyala megint eljött az asszonyhoz, mikor az a mezőn ült, és az ő férje Manoah nem volt vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'Akkor az asszony elsietett, és elfutott, és elbeszélé férjének, és monda néki: Ímé megjelent nékem az a férfiú, a ki a multkor hozzám jött.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'És felkelt, és elment Manoah az ő felesége után, és mikor odaért ahhoz a férfiúhoz, monda néki: Te vagy-é az a férfiú, a ki ez asszonynyal beszéltél? És monda: Én vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, 'És monda Manoah: Ha beteljesedik ígéreted, miként bánjunk a gyermekkel, és mit cselekedjék ő?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'Az Úrnak angyala pedig monda Manoáhnak: Mindentől, a mit csak mondottam az asszonynak, őrizkedjék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'Mindabból, a mi csak a bortermő szőlőből származik, ne egyék, és bort és más részegítő italt ne igyék, és semmi tisztátalant ne egyék. Mindazt, a mit parancsoltam néki, tartsa meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'És monda Manoah az Úr angyalának: Kérlek, hadd tartóztassunk meg téged, hogy készítsünk néked egy kecskegödölyét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'De az Úrnak angyala így szólt Manoáhhoz: Ha megmarasztasz is, nem eszem kenyeredből, és ha áldozatot készítesz, az Úrnak áldozd azt. Mert Manoah nem tudta, hogy az Úrnak angyala vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'És monda Manoah az Úr angyalának: Kicsoda a te neved, hogy ha majd beteljesedik a te beszéded, tisztességgel illethessünk téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'És monda néki az Úrnak angyala: Miért kérdezősködöl nevem után, a mely olyan csodálatos?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'Mikor aztán Manoah a kecskegödölyét és ételáldozatot vette, és megáldozá azt egy sziklán az Úrnak: csodadolgot cselekedék Manoahnak és feleségének szeme láttára:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'Tudniillik, mikor a láng felcsapott az oltárról az ég felé, az oltár lángjában felszállott az Úrnak angyala. Mikor pedig ezt meglátták Manoah és az ő felesége, arczczal a földre borultak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'És többé nem jelent meg az Úrnak angyala Manoáhnak és feleségének. Ekkor tudta meg Manoah, hogy az Úrnak angyala volt az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, 'És monda Manoah az ő feleségének: Meghalván meghalunk, mert az Istent láttuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, 'Akkor monda néki az ő felesége: Ha meg akart volna ölni az Úr minket, nem fogadta volna el kezünkből az egészen égőáldozatot és az ételáldozatot, és nem mutatta volna nékünk mindezeket, sem pedig nem hallatott volna velünk ilyeneket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'És szült az asszony fiat, és nevezé annak nevét Sámsonnak, és felnevekedék a gyermek, és megáldá őt az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'És kezdé az Úrnak lelke őt indítani a Dán táborában, Czóra és Estháol között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'És lement Sámson Timnátba, és meglátott egy nőt Timnátban a Filiszteusok lányai közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'És mikor hazament, elbeszélte ezt atyjának és anyjának, és monda: Egy nőt láttam Timnátban a Filiszteusok leányai között, most azért vegyétek őt nékem feleségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'És monda néki az ő atyja és anyja: Hát nincsen a te atyádfiainak és az én egész népemnek leányai között nő, hogy te elmégy, hogy feleséget végy a körülmetéletlen Filiszteusok közül? És monda Sámson az ő atyjának: Őt vegyed nékem, mert csak ő kedves az én szemeim előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'Az ő atyja és anyja pedig nem tudják vala, hogy ez az Úrtól van, hogy ő alkalmatosságot keres a Filiszteusok ellen, mert abban az időben a Filiszteusok uralkodtak Izráel felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'És lement Sámson az ő atyjával és anyjával Timnátba, és mikor Timnátnak szőlőhegyéhez értek, íme egy oroszlánkölyök jött ordítva elébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'És felindítá őt az Úrnak lelke, és úgy kettészakasztá azt, mint a hogyan kettészakasztatik a gödölye; pedig semmi sem volt kezében. De atyjának és anyjának nem mondta el, a mit cselekedett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'És mikor leérkezett, beszélt a nővel, a ki kedves volt Sámson szemei előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'Mikor pedig egynéhány nappal azután visszatért, hogy őt hazavigye, lekerült, hogy megnézze az oroszlánnak holttestét: hát íme egy raj méh volt az oroszlánnak tetemében, és méz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'És kiszedte azt markaiba, és a mint ment-mendegélt, eszegetett belőle, és mikor hazaért atyjához és anyjához, adott abból nékik is, és azok is ettek; de nem mondta meg nékik, hogy az oroszlán holtteteméből vette ki a mézet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'És azután lement az ő atyja ahhoz a nőhöz, és Sámson lakodalmat tartott ott, mert úgy szoktak cselekedni az ifjak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'Mikor pedig meglátták őt a Filiszteusok, harmincz társat adtak mellé, hogy legyenek ő vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'És monda nékik Sámson: Hadd vessek előtökbe egy találós mesét, ha azt megfejtitek nékem a lakodalom hét napja alatt és kitaláljátok; adok néktek harmincz inget és harmincz öltöző ruhát;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'De ha nem tudjátok megfejteni, ti adtok nékem harmincz inget és harmincz öltöző ruhát. Azok pedig mondának néki: Add elő találós mesédet, hadd halljuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'Ő pedig monda nékik: Az evőből étek jött ki S az erősből édes jött ki. De nem tudták a találós mesét megfejteni három egész napon át.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'Lőn annakokáért heted napon, mondának Sámson feleségének: Vedd reá férjedet, hogy fejtse meg nékünk a találós mesét, hogy valamiképen meg ne égessünk téged és a te atyádnak házát tűzzel; vagy azért hívtatok ide minket, hogy koldussá tegyetek bennünket, vagy nem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'És sírt a Sámson felesége ő előtte, és monda: Bizony te gyűlölsz engem, és nem szeretsz. Egy találós mesét vetettél az én népem fiai elé és nékem sem fejtetted meg. Ő pedig monda néki: Íme még atyámnak és anyámnak sem mondtam meg, hát néked mondanám meg?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'Az pedig hét napon át sírdogált előtte, a meddig a lakodalom tartott. Végre a hetedik napon megmondá néki, mert folyvást zaklatta őt. Ő pedig aztán megfejté a találós mesét népe fiainak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'És mondának néki a város férfiai a hetedik napon, mielőtt még a nap lement volna: Mi édesebb, mint a méz, És mi erősebb, mint az oroszlán? Ki monda nékik: Ha nem az én üszőmön szántottatok volna, Mesém soha ki nem találtátok volna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'Ekkor felindítá őt az Úrnak lelke, és elment Askelonba, és megölt közülök harmincz férfiút, és elvette ruhájukat és azoknak adta ez öltöző ruhákat, a kik a találós mesét megoldották. És felgerjedett haragjában elment az ő atyjának házához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'A Sámson felesége pedig férjhez ment az ő egyik társához, a kit társaságába vett vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'Lőn pedig néhány nap múlva, a búzaaratásnak idejében, meglátogatta Sámson az ő feleségét, egy kecskegödölyét vivén néki, és monda: Bemegyek az én feleségemhez a hálóházba. De nem hagyá őt bemenni az ő atyja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, 'És monda annak atyja: Azt gondoltam, hogy gyűlölve gyűlölöd őt, azért odaadtam őt a te társadnak; de hát vajjon húga nem szebb-é nálánál? Legyen ő helyette most az a tied.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'És monda néki Sámson: Teljesen igazam lesz most a Filiszteusokkal szemben, ha kárt okozok nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'És elment Sámson, és összefogdosott háromszáz rókát, és csóvákat vévén, a rókák farkait egymáshoz kötözé, és egy-egy csóvát tett minden két rókának farka közé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'És meggyújtá tűzzel a csóvákat, és beeresztette azokat a Filiszteusok gabonájába, és felgyújtá a gabonakalangyákat, az álló vetéseket, a szőlőket és az olajfaerdőket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'Akkor mondának a Filiszteusok: Ki cselekedte ezt? És mondák: Sámson, Thimneus veje, mert elvette tőle az ő feleségét, és adta azt az ő társának. Felmenének annakokáért a Filiszteusok, és megégeték az asszonyt és annak atyját tűzzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'Sámson pedig monda nékik: Bátor ezt cselekedtétek, mégis addig nem nyugszom meg, míg bosszúmat ki nem töltöm rajtatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'És megverte őket keményen válluktól tomporukig, és lement és lakott Ethamban, a sziklabarlangban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'A Filiszteusok pedig felmentek, és megszállották Júdát, és Lehiben telepedtek le.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'Akkor mondának a Júda férfiai: Miért jöttetek fel ellenünk? Azok pedig mondának: Sámsont megkötözni jöttünk fel, hogy úgy cselekedjünk vele, mint ő cselekedett mi velünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'Ekkor háromezer ember ment le Júdából Ethamba, a sziklabarlanghoz, és monda Sámsonnak: Nem tudod-é, hogy a Filiszteusok uralkodnak mi rajtunk? Miért cselekedted ezt velünk? Ő pedig monda nékik: A miképen cselekedtek ők velem, én is úgy cselekedtem velök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'És mondának néki: Azért jöttünk le, hogy megkötözzünk, és hogy a Filiszteusok kezébe adjunk téged. Sámson pedig monda nékik: Esküdjetek meg nékem, hogy ti nem rohantok reám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, 'És azok felelének néki, mondván: Nem! csak megkötözvén megkötözünk, és kezökbe adunk; de nem ölünk meg téged. Azután megkötözték őt két új kötéllel, és felvezették őt a kőszikláról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'És mikor Lehi felé közeledett, és a Filiszteusok már ujjongtak elébe: felindítá őt az Úrnak lelke, és olyanok lettek a karján levő kötelek, mint a lenszálak, melyeket megperzsel a tűz és lemállottak a kötések kezeiről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'És egy nyers szamárállcsontot talála, és kinyújtván kezét, felvevé azt, és agyonvert vele ezer embert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'És monda Sámson: Szamár állcsontjával seregeket seregre, Szamár állcsontjával ezer férfit vertem le.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'És mikor ezt elmondotta, elvetette kezéből az állcsontot, és elnevezé azt a helyet Ramath-Lehinek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'Azután megszomjúhozék felette igen és felkiáltott az Úrhoz, és monda: Te adtad szolgád kezébe ezt a nagy győzelmet, és most szomjan kell meghalnom, és a körülmetéletlenek kezébe jutnom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'Akkor meghasítá Isten a zápfogat, mely az állcsontban volt, és víz fakadt ki abból. Ő pedig ivott, ereje megtért, és megéledett. Azért neveztetik a „segítségül hívás forrásának” e hely Lehiben mind e mai napig,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'És ítélé Sámson Izráelt a Filiszteusok idejében húsz esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'És elment Sámson Gázába, és meglátott ott egy parázna asszonyt, és bement hozzá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'A gázabelieknek pedig mikor megmondották, mondván: Ide jött Sámson! körülvevék őt, és leselkedének ő utána egész éjszakán át a város kapujában, és hallgatóztak egész éjjel, és azt mondták: Reggel, ha világos lesz, megöljük őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'És aluvék Sámson éjfélig. Éjfélkor pedig felkelt, és megfogván a város kapujának szárnyait, a kapufélfákkal és a závárokkal együtt kiszakította azokat, és vállaira vette, és felvitte a hegy tetejére, mely Hebronnal szemben fekszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'És történt azután, hogy megszeretett egy asszonyt a Sórek völgyében, a kinek neve Delila volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'És felmenének ő hozzá a Filiszteusok fejedelmei, és mondának néki: Kérdezd ki őt és tudd meg, miben áll az ő nagy ereje, és miképen vehetünk rajta erőt, hogy megkötözzük és megkínozzuk őt, és mi mindenikünk adunk néked ezerszáz ezüst siklust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'És monda Delila Sámsonnak: Mondd meg nékem, miben van a te nagy erőd és mivel kellene téged megkötni, hogy megkínozhassanak téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'És felele néki Sámson: Ha megkötöznek hét nyers gúzszsal, melyek még meg nem száradtak, akkor elgyengülök és olyan leszek, mint más ember.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'Akkor hoztak néki a Filiszteusok fejedelmei hét nyers gúzst, a mely még nem volt száraz, és megkötözé őt azzal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, 'A lesben állók pedig ott vártak annál a hálókamarában. És monda néki: Rajtad a Filiszteusok, Sámson! És elszakasztá a gúzsokat, miképen elszakad a csepűfonal, ha tűz éri, – és ki nem tudódék, miben volt az ő ereje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'És monda Delila Sámsonnak: Ímé rászedtél, és hazugságot szóltál nékem, most mondd meg igazán, hogy mivel lehet téged megkötözni?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, 'Ő pedig monda néki: Ha erősen megkötöznek új kötelekkel, melyekkel még semmi dolgot nem végeztek, akkor elgyengülök és olyan leszek, mint más ember.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'És vett Delila új köteleket, és megkötözte őt velük, és monda néki: Rajtad a Filiszteusok, Sámson! (mert ott leselkedtek utána a hálókamarában). De ő letépte azokat karjairól, mint a fonalat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'És monda Delila Sámsonnak: Meddig fogsz még rászedni engem és hazudni nékem? Mondd meg egyszer már, mivel kötöztethetel meg? – Ő pedig monda néki: Ha összeszövöd az én fejemnek hét fonatékját a nyüstfonállal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'És szeggel megerősítvén a zugolyt, monda: Rajtad a Filiszteusok, Sámson! Az pedig felébredvén álmából, kitépte a zugolyszeget és a nyüstfonalat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'Ekkor monda néki Delila: Miképen mondhatod: Szeretlek téged, ha szíved nincsen én velem? Immár három ízben szedtél rá engem, és nem mondtad meg, hogy miben van a te nagy erőd?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'Mikor aztán őt minden nap zaklatta szavaival, és gyötörte őt: halálosan belefáradt a lelke,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'És kitárta előtte egész szívét, és monda néki: Borotva nem volt soha az én fejemen, mert Istennek szentelt vagyok anyám méhétől fogva; ha megnyírattatom, eltávozik tőlem az én erőm, és megerőtlenedem, és olyan leszek, mint akármely ember.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'És mikor látta Delila, hogy kitárta volna előtte egész szívét, elküldött, és elhívatá a Filiszteusok fejedelmeit, és ezt izené: Jőjjetek fel ez egyszer, mert ő kitárta nékem egész szívét. És felmentek ő hozzá a Filiszteusok fejedelmei, és a pénzt is felvitték kezökben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'És elaltatta őt az ő térdein, és előhívott egy férfiút, és lenyíratta az ő fejének hét fonatékát, és kezdé őt kínozni. És eltávozott tőle az ő ereje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'És monda: Rajtad a Filiszteusok, Sámson! Mikor pedig az az ő álmából felserkent, monda: Kimegyek most is, mint egyébkor, és lerázom a kötelékeket; mert még nem tudta, hogy az Úr eltávozott ő tőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'De a Filiszteusok megfogták őt, és kiszúrták szemeit, és levezették őt Gázába, és ott megkötözték két vaslánczczal, és őrölnie kellett a fogházban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'De az ő fejének haja újra kezdett nőni, miután megnyíretett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'És mikor a Filiszteusok fejedelmei összegyűltek, hogy az ő istenüknek, Dágonnak nagy áldozatot áldozzanak, és hogy örvendezzenek, mondának: Kezünkbe adta a mi istenünk Sámsont, a mi ellenségünket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, 'És mikor látta őt a nép, dícsérték az ő istenöket, mert – mondának – kezünkbe adta a mi istenünk a mi ellenségünket, földünk pusztítóját, és a ki sokakat megölt mi közülünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'Lőn pedig, hogy mikor megvídámult az ő szívök, mondának: Hívjátok Sámsont, hadd játszék előttünk. És előhívák Sámsont a fogházból, és játszék ő előttük, és az oszlopok közé állították őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'Sámson pedig monda a fiúnak, a ki őt kézenfogva vezette: Ereszsz el, hadd fogjam meg az oszlopokat, a melyeken a ház nyugszik, és hadd támaszkodjam hozzájuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'A ház pedig tele volt férfiakkal és asszonyokkal, és ott voltak a Filiszteusok összes fejedelmei, és a tetőzeten közel háromezeren, férfiak és asszonyok, a Sámson játékának nézői.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'Ekkor Sámson az Úrhoz kiáltott, és monda: Uram, Isten, emlékezzél meg, kérlek, én rólam, és erősíts meg engemet, csak még ez egyszer, óh Isten! hadd álljak egyszer bosszút a Filiszteusokon két szemem világáért!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'És átfogta Sámson a két középső oszlopot, melyeken a ház nyugodott, az egyiket jobb kezével, a másikat bal kezével, és hozzájok támaszkodott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'És monda Sámson: Hadd veszszek el én is a Filiszteusokkal! És nagy erővel megrándította az oszlopokat, és rászakadt a ház a fejedelmekre és az egész népre, mely abban volt, úgy hogy többet megölt halálával, mint a mennyit megölt életében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'És lementek az ő testvérei és atyjának egész háza, és elvivék őt, és hazatérvén, eltemették Czóra és Estháol között, atyjának, Manoahnak sírjába, minekutána húsz esztendeig ítélte az Izráelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'Vala pedig egy férfiú Efraimnak hegyéről való, kinek neve Míka vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'És monda az ő anyjának: Az az ezerszáz ezüst, mely tőled elvétetett, és a mely miatt te átkozódál, és füleimbe is mondtad, ímé az az ezüst én nálam van, én vettem el azt. És monda az ő anyja: Légy megáldva, fiam, az Úrtól!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'És visszaadta az ezerszáz ezüstpénzt az ő anyjának. És monda az ő anyja: Szentelve szentelem e pénzt az Úrnak az én kezeimből fiaimért, hogy egy faragott és öntött bálvány készíttessék abból, azért most visszaadom azt tenéked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'De ő megint visszaadá a pénzt anyjának, és vőn az ő anyja kétszáz ezüstpénzt, és odaadá azt az ötvösnek, és az készített abból egy faragott és öntött bálványt. Ez azután a Míka házában volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'És a férfiúnak, Míkának volt egy temploma, és készített efódot és terafimot, és felszentele az ő fiai közül egyet, és ez lőn néki papja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'Ebben az időben nem volt király Izráelben, hanem kiki azt cselekedte, a mit jónak látott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'Vala pedig egy ifjú, Júdának Bethleheméből, a Júda nemzetségéből való, ki Lévita vala, és ott tartózkodott vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'És elméne ez a férfiú Júdának Bethlehem városából, hogy ott tartózkodjék, a hol helyet talál. Így jött az Efraim hegyére, Míka házához, vándorlása közben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'És monda néki Míka: Honnan jössz? És monda: Lévita vagyok Júdának Bethleheméből, és járok s kelek, hogy hol találnék helyet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, 'És monda néki Míka: Maradj nálam, és légy nékem atyám és papom, és én adok néked esztendőnként tíz ezüstpénzt és egy öltöző ruhát és eledelt. És a Lévita beszegődött.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'És tetszék a Lévitának, hogy megmaradjon annál a férfiúnál; és olyan lőn néki az az ifjú, mint egyik az ő fiai közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'És felszentelte Míka a Lévitát; így lett papjává az ifjú, és maradt Míka házánál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, 'És monda Míka: Most tudom, hogy jól fog velem tenni az Úr, mert e Lévita lett papom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'Ebben az időben nem volt király Izráelben, és ezekben a napokban keresett a Dán nemzetsége magának örökséget, a hol lakjék, mert nem jutott néki mind ez ideig az Izráel törzsei között osztályrész.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'És elküldöttek a Dán fiai az ő házoknépe közül öt férfiút, vitéz férfiakat a magok határaikból, Czórából és Estháolból, hogy kémleljék ki és nézzék meg jól a földet, és mondának nékik: Menjetek el, kémleljétek ki a földet. És elérkeztek az Efraim hegyéhez, a Míka házához, és ott megháltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'Mikor a Míka házánál voltak, megismerték az ifjú Lévitának hangját, és hozzá mentek, és mondának néki: Ki hozott téged ide? Mit csinálsz itt, és mi járatban vagy?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'Ő pedig monda nékik: Ezt meg ezt cselekedte velem Míka, és megfogadott engem, és papjává lettem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, 'És mondának néki: Kérdezd meg Istentől, hogy hadd tudjuk meg, ha szerencsés lesz-é a mi útunk, a melyen járunk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, 'És monda nékik a pap: Menjetek el békességgel; a ti útatok, a melyen jártok, az Úr előtt van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'És elment az öt férfiú, és Laisba jutott, és látták a népet, a mely benne volt, hogy minden félelem nélkül lakik, a Sidonbeliek szokása szerint él csendesen és bátorságosan, és nincs senki, a ki őket bántaná az országban, vagy úr volna felettök, és távol vannak a sidoniaktól, és nincs senkivel semmi dolguk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, 'És mikor visszatértek atyjokfiaihoz Czórába és Estháolba, és kérdezték tőlök az ő atyjokfiai: Mi jóval jártatok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, 'Mondának: Keljetek fel, és menjünk fel ellenök, mert láttuk a földet, hogy ímé igen jó, és ti veszteg ültök? ne legyetek restek a menetelre, hogy elmenjetek elfoglalni azt a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, 'Ha elmentek, biztonságban élő néphez mentek, és a tartomány tágas; mert Isten kezetekbe adta azt a helyet, a hol semmiben sincs hiány, a mi csak a földön van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'És elment onnét a Dán nemzetségéből, Czórából és Estháolból, hatszáz férfiú hadiszerszámokkal felkészülten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'És felvonultak, és táborba szállottak Kirjáth-Jeárimban, Júdában. Ezért hívják azt a helyet Dán táborának mind e mai napig. És ez Kirjáth-Jeárim mögött fekszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'És onnan felvonultak az Efraim hegyére, és Míka házába mentek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'És szólott az az öt férfiú, a ki elment kikémlelni Lais földét és monda atyjafiainak: Tudjátok-é, hogy ebben a házban efód és teráf, faragott és öntött bálvány van? Hát elgondolhatjátok, hogy mit cselekedjetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'És betértek oda, és az ifjú Lévitához mentek a Míka házába, és köszöntötték őt: Békességgel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'A hadiszerszámokkal felkészült hatszáz férfiú pedig, kik a Dán fiai közül valók voltak, a kapu előtt állott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'És az az öt férfiú, a ki a föld kikémlelésére ment volt el, mikor felment és megérkezett oda, elvette a faragott képet, az efódot, a teráfot és az öntött bálványt; a pap pedig ott állott a kapu előtt a hadiszerszámokkal felkészült hatszáz férfiúval.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'Mikor pedig ezek a Míka házához bementek és elvették a faragott képet, az efódot, a teráfot és az öntött bálványt, monda nékik a pap: Mit míveltek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, 'Azok pedig mondának néki: Hallgass, tedd kezed ajakadra, és jőjj el velünk, és légy nékünk atyánk és papunk. Melyik jobb, hogy egy ember házának légy papja, vagy hogy Izráelben egy nemzetségnek és háznépnek légy papja?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'És örvendett ezen a papnak szíve, és elvitte az efódot és a teráfot és a faragott képet, és velök a nép közé ment.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'És megfordulván elvonultak, magok előtt küldve a gyermekeket, a barmokat és drágaságaikat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'Mikor pedig már messze jártak a Míka házától, a férfiak, a kik a Míka házának szomszédságában laktak, összegyűltek, és utána mentek a Dán fiainak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'És utánok kiáltoztak a Dán fiainak. Azok pedig visszafordulván mondának Míkának: Mi bajod van, hogy így felsereglettél?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'És monda: Isteneimet vettétek el, a melyeket készíttettem, és papomat, és elmentetek, hát mim van még egyebem? és mégis azt mondjátok nékem: mi bajom van?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'És mondának néki a Dán fiai: Ne hallasd többé hangodat, hogy rátok ne rontsanak e felbőszített emberek, és te a magad életét és házadnépe életét el ne veszítsd!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'És elmentek a Dán fiai a magok útján, és mikor Míka látta, hogy azok erősebbek nála, megfordult, és visszatért házához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'Ők pedig elvitték, a mit Míka készíttetett, és a papot, a ki nála volt, és Lais ellen mentek, a nyugodtan és biztonságban élő nép ellen, és leölték őket fegyvernek élivel, és a várost megégették tűzzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'És nem volt senki, a ki őket megszabadította volna, mert messze volt Sidontól, és semmi dolguk nem volt senkivel. Lais pedig a Béth-Rehob völgyében feküdt és itt építették meg a várost, és telepedtek meg benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'És elnevezték a város nevét Dánnak, atyjoknak Dánnak nevéről, a ki Izráelnek született volt. Bár először Lais volt a város neve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'És felállították magoknak a Dán fiai a faragott képet, és Jonathán, a Manasse fiának Gersomnak fia és az ő fiai voltak papok a Dán nemzetségében egészen a föld fogságának idejéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'És felállítva tarták a Míka faragott képét, a melyet az készíttetett, mindaddig, míg az Istenháza Silóban volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, 'Ugyanebben az időben, a mikor nem volt király Izráelben, mint jövevény tartózkodott az Efraim hegység oldalán egy Lévita, a ki ágyas nőt szerzett magának Júda Bethleheméből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'Paráználkodék pedig nála az ő ágyasa és elméne tőle atyjának házához, Júdának Bethlehemébe, és ott maradt négy hónapig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'Ekkor felkelvén az ő férje, utána ment, hogy lelkére beszéljen, és hogy visszavigye őt. Szolgája és egy pár szamár volt vele. Az pedig bevezette őt az ő atyjának házába, és mikor meglátta őt a leánynak atyja, örvendve eléje ment.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'És ott tartóztatá őt ipa, a leánynak atyja, és ő ott maradt nála három napig, és ettek, ittak, és ott is háltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'És mikor a negyedik napon reggel korán felkeltek, és ő felkészült, hogy elmenjen, monda a leánynak atyja az ő vejének: Erősítsd meg szívedet egy falat kenyérrel, azután menjetek el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'És leültek, és mindketten együtt ettek és ittak, és monda a leány atyja a férfiúnak: Gondold meg és hálj itt az éjjel és gyönyörködjék a te szíved.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'Mikor pedig felkelt az a férfiú, hogy elmenjen, addig marasztá őt az ipa, hogy ott maradt megint éjszakára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'És felkelt azután az ötödik napon jókor reggel, hogy elmenjen, és monda a leánynak atyja: Erősítsd meg, kérlek, a te szívedet. És mulatozának, míg elhanyatlék a nap, és együtt evének mindketten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'Ekkor felkele az a férfiú, hogy elmenjen ágyasával és szolgájával; de ipa, a leánynak atyja, így szólt hozzá: Ímé a nap már lehanyatlik, hogy beesteledjék, azért háljatok meg itt; ímé nyugalomra hajlik a nap, hálj itt, és gyönyörködjék a te szíved; holnap aztán készüljetek fel jókor reggel a ti útatokra, és menj el sátorodba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'De a férfiú nem akart ott meghálni, és felkelt és elment, és egész Jebusig jutott, – ez Jeruzsálem. Egy pár megterhelt szamár és ágyasa volt vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'Mikor pedig Jebus mellett voltak, a nap már igen alászállott, és monda a szolga az ő urának: Jerünk és térjünk be a Jebuzeusok e városába, és háljunk ott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'És monda néki az ő ura: Ne térjünk be az idegenek városába, a hol senki sincs az Izráel fiai közül, inkább menjünk el Gibeáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'És monda az ő szolgájának: Siess, és menjünk e két hely valamelyikébe, és háljunk vagy Gibeában, vagy Rámában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'És tovább vonultak, és elmenének, és a nap Gibea mellett ment le felettök, a mely Benjáminé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'És oda tértek, hogy bemenjenek és megháljanak Gibeában. Mikor pedig oda bement, leült a város piaczán, mert nem volt senki, a ki őket házába behívná éjszakára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'És ímé egy öreg ember jöve a munkából a mezőről késő estve. Ez a férfiú az Efraim hegységéről való volt, és csak jövevény Gibeában, míg a helynek lakói Benjáminiták voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'És mikor felemelte szemeit, és meglátta azt az utas embert a város piaczán, monda az öreg ember néki: Hová mégy és honnan jösz?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'Ez pedig monda néki: Megyünk Júda Bethleheméből az Efraim hegység oldaláig, a honnan való vagyok. Júda Bethlehemében voltam és most az Úr házához megyek, és nincsen senki, a ki házába fogadna engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'Pedig szalmánk és abrakunk is van szamaraink számára, és kenyerem és borom is van a magam és a te szolgálód és emez ifjú számára, ki szolgáddal van, úgy hogy semmiben sem szűkölködünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, 'Ekkor monda a vén ember: Békesség néked! Mindarra, a mi nélkül csak szűkölködöl, nékem lesz gondom. Csak nem hálsz itt az utczán?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'És elvezette őt az ő házához és abrakot adott az ő szamarainak. Azután megmosták lábaikat, és ettek és ittak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'És mikor vígan laknának, ímé a város férfiai, a Béliál fiainak emberei, körülvették a házat, és az ajtót döngetve, mondának az öreg embernek, a ház urának, mondván: Hozd ki azt a férfiút, a ki házadhoz jött, hogy ismerjük meg őtet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'És kiment hozzájuk az a férfiú, a háznak ura és monda nékik: Ne, atyámfiai, ne cselekedjetek ilyen gonoszt, minekutána az a férfiú az én házamhoz jött, ne tegyétek vele azt az alávaló dolgot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'Ímé itt van hajadon leányom és az ő ágyasa, ezeket hozom ki néktek, és ezeket nyomorgassátok, és tegyétek velök azt, a mit csak tetszik, csak e férfiúval ne cselekedjétek azt az alávaló dolgot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'A férfiak azonban nem akartak reá se hallgatni. Ekkor kézen fogta az a férfiú az ő ágyasát, és kivitte nékik az utczára. Ezek pedig megszeplősíték őt, és gonoszul élének vele egész éjszaka reggelig, és csak mikor feltetszett a hajnal, akkor bocsátották el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'És elment az asszony virradat előtt és reggel ott rogyott össze annak a férfiúnak háza ajtajánál, a melyben az ő ura volt reggelig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'Mikor pedig felkelt az ő ura reggel, és kinyitotta a ház ajtaját, és kiment, hogy útnak induljon, ímé az asszony, az ő ágyasa, ott feküdt elterülve a ház ajtaja előtt, és kezei a küszöbön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, 'És monda néki: Kelj fel és menjünk el. De az nem felelt néki. Ekkor feltette őt a szamárra, és felkelt a férfiú, és elment hazájába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'És mikor hazaért, kést vett elő, és megfogta ágyasát, és tagról-tagra szétvagdalta őt tizenkét darabba, és szétküldözte Izráel minden határába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'Lőn pedig, hogy mindenki, a ki ezt látta, azt mondotta: Nem történt és nem láttatott ehhez hasonló dolog, mióta csak feljöttek az Izráel fiai Égyiptomnak földéből mind e mai napig. Gondolkodjatok e dolog felől, tartsatok tanácsot és beszéljétek meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'Erre kivonultak az Izráel minden fiai és összegyülekezett a nép, mint egy ember, Dántól fogva Bersebáig és a Gileád földéig, az Úrhoz Mispába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'És megjelentek az egész népnek főfő emberei, az Izráelnek minden nemzetségei az Isten népének gyülekezetében, négyszázezer gyalogos, fegyverfogható férfiú.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, 'De meghallották a Benjámin fiai is, hogy felmentek az Izráel fiai Mispába. Az Izráel fiai pedig mondának: Mondjátok meg, hogy mint történt ez a gonoszság?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'És felele a Lévita, a megöletett asszonynak férje, és monda: Gibeába, mely Benjáminé, mentem én és az én ágyasom, hogy ott megháljak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'És ellenem támadtak Gibeának férfiai, és körülvették miattam a házat éjjel, engem akartak megölni, de az én ágyasomat nyomorgatták meg annyira, hogy meghalt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'Ekkor fogtam ágyasomat, és szétvagdaltam őt, és szétküldöztem az Izráel örökségének minden tartományaiba, mert útálatosságot és aljasságot követtek el Izráelben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'Ímé mindnyájan, kik itt vagytok Izráel fiai, szóljatok erről és tanácskozzatok felőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'Ekkor felállott az egész nép, mint egy ember, mondván: Senki közülünk sátorába ne menjen, és senki házához ne térjen,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'Mert most Gibea ellen ezt cselekedéndjük: sorsot vetünk rá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'És választunk tíz férfiút száz közül, és százat ezer közül, és ezeret tízezer közül, Izráelnek minden nemzetségéből, hogy hordjanak élelmet a népnek, hogy ez elmenvén, cselekedjék Benjámin Gibeájával annak minden gonoszsága szerint, melyet elkövetett Izráelben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'És összegyülekezett Izráel minden férfia a város ellen, mint egy ember, egyesülten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'És követeket küldöttek az Izráel nemzetségei Benjámin minden törzseihez, mondván: Micsoda aljasság az, a mi ti közöttetek történt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'Most adjátok ki azokat a férfiakat, a Béliál fiait, a kik Gibeában vannak, hogy megöljük őket, és kitisztítsuk a gonoszt Izráelből. De a Benjámin fiai nem akartak hallgatni testvéreiknek, az Izráel fiainak szavára,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'Hanem egybegyűltek a Benjámin fiai a városokból Gibeába, hogy kimenjenek harczolni az Izráel fiaival.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'És azon a napon a Benjámin fiai, a kik a városokból jöttek fel, huszonhatezer fegyverfogható férfiút számlálának, Gibea lakóin kivül, kik szám szerint hétszázan voltak, mind válogatott férfiú.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'Ebből az egész népből volt hétszáz válogatott férfiú, a kik suták voltak. Ezek mindnyájan a parittyával hajszálnyira biztosan találtak és nem hibázták el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'Az Izráel fiai pedig szám szerint, a Benjámin fiain kivül, négyszázezeren voltak, fegyverfogható emberek, és mind hadakozó férfiak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'Ekkor felkeltek, és felmentek Béthelbe, és megkérdék az Istent, és mondának az Izráel fiai: Ki menjen fel először közülünk a Benjámin fiai ellen hadakozni? És monda az Úr: Júda először.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'Felkeltek azért az Izráel fiai reggel, és táborba szállottak Gibea előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'És kimentek Izráel emberei harczolni Benjámin ellen, és csatarendbe állottak fel ellenök az Izráel emberei Gibeánál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'És kivonultak a Benjámin fiai is Gibeából, és levertek az Izráel fiai közül az nap huszonkétezeret a földre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, 'De a nép, Izráel férfiai, megbátoríták magukat, és újra csatarendbe állottak ugyanazon a helyen, a melyen előtte való nap sorakoztak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, 'És felmenének az Izráel fiai, és ott sírtak, az Úr előtt egész estig, és megkérdezték az Urat, mondván: Vajjon elmenjek-é még harczolni az én atyámfiának, Benjáminnak fiai ellen? Az Úr pedig monda: Menjetek fel ellene!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'És mikor az Izráel fiai másnap a Benjámin fiai ellen felvonultak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'Kijött elébük Benjámin Gibeából másnap, és levert az Izráel fiai közül még tizennyolczezer embert a földre, kik mindannyian fegyverfoghatók valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'Ekkor felment Izráel minden fia és az egész nép, és elmenvén Béthelbe, sírtak, és ott maradtak az Úr előtt és bőjtöltek aznap egész estvéig, és égőáldozattal és hálaadó áldozattal áldoztak az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'És megkérdezék az Izráel fiai az Urat, – mert ott volt abban az időben az Isten frigyládája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'És Fineás, az Áron fiának Eleázárnak fia szolgált körülötte abban az időben – mondván: Vajjon még egyszer felmenjek-é harczolni az én atyámfiának Benjáminnak fiaival, vagy pedig abbanhagyjam? És monda az Úr: Menj, mert holnap kezedbe adom őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'És leseket vetett Izráel Gibea ellen köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'És felvonultak az Izráel fiai a Benjámin fiai ellen harmadnapon, és felállottak Gibea ellen úgy, mint annakelőtte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'Ekkor kijöttek a Benjámin fiai a nép ellen, elszakasztatának a várostól, és elkezdették a népet verni, és ölni, mint annakelőtte, a mezőn, a két úton, melynek egyike Béthelbe, másika Gibea felé vezet, és már megöltek mintegy harmincz férfiút Izráelből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'És mondának a Benjámin fiai: Megverettetnek ezek előttünk megint, mint először. Az Izráel fiai pedig mondának: Fussunk el és szakaszszuk el őket a várostól, ki az országútra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'És az Izráel minden fia elhagyta helyét és Baál-Thámárnál állott fel. Izráel lesei pedig előtörtek rejtekhelyeikből Maareh-Gabából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'Ekkor az egész Izráelből tízezer válogatott férfiú tört Gibea ellen, és néki búsulának a harcznak, és amazok észre sem vették, hogy veszedelemben forognak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'Így verte le az Úr Izráel előtt Benjámint, és elpusztítottak az Izráel fiai azon a napon a Benjámin fiai közül huszonötezerszáz férfiút, kik mind fegyverfoghatók voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'Benjámin fiai tehát látták, hogy megveretnek, mivel Izráel férfiai csak azért adtak helyet Benjáminnak, mert ők a lesekben bíztak, a melyeket Gibeánál helyeztek el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'És a les elősietett és előtört Gibea ellen, és a les bevonult, és leölte az egész várost fegyvernek élivel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'És abban egyeztek meg Izráel férfiai a les-csapatokkal, hogy erős füstfelleget bocsátanak fel a városból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'Mikor aztán az Izráel férfiai visszafordultak a harcz közben, és Benjámin megkezdte az öldöklést és leölt mintegy harmincz férfiút Izráelből, és azt gondolta magában: Bizony megverettetnek előttünk, mint az első ütközetben:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'Épen akkor kezdett a felhő felemelkedni a városból, mint egy füstoszlop. És mikor aztán Benjámin hátratekintett, látta, hogy íme a város lángja már feléri az eget.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'És az Izráel fiai megfordultak, és megijedének a Benjámin fiai, a kik most látták csak, hogy rajtok a veszedelem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'És elfutottak az Izráel férfiai elől a pusztába vivő útra; de a harcz ott is utólérte őket, és az út közepén ölték le a városból jövőket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'Körülvették Benjámint, üldözték őt, letiporták a pihenő helyen, egészen a Gibea előtt keletre eső vidékig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'És elesett Benjámin közül tizennyolcezer ember, mindnyájan vitéz férfiak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'Ekkor megfordultak, és a pusztába menekültek, a Rimmon sziklájához; de az útakon még megöltek közülök ötezer embert, és azután egész Gideomig mentek utánok, és megöltek közülök kétezer embert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'Azok tehát, akik elestek Benjámin közül, összesen huszonötezeren voltak, kik mindannyian fegyvert fogtak azon a napon, és mindnyájan vitéz férfiak voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, 'De hatszáz férfiú megfordult, és elmenekült a pusztába a Rimmon kősziklájára, és ott is maradt a Rimmon szikláján négy hónapig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'Az Izráel férfiai pedig visszatértek a Benjámin fiaira, és megölték őket fegyvernek élével a városokban az emberektől a barmokig, és a mi csak található volt; az összes városokat pedig, miket találtak, tűzzel égették meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'És az Izráel fiai megesküdtek Mispában, mondván: Senki mi közülünk nem adja leányát Benjáminnak feleségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'És a nép elment Béthelbe, és ott volt egész estvéig az Isten előtt, és felemelve szavát, nagy sírással sírt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, 'És mondának: Oh Uram! Izráelnek Istene! Miért történt ez Izráelben, hogy ma Izráelből egy nemzetség hiányzik?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'És lőn másnap reggel, felkele a nép és ott oltárt épített, és egészen égőáldozatot és hálaadó áldozatot áldozott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'És mondának az Izráel fiai: Kicsoda az, a ki nem jött fel a gyülekezetbe az Izráelnek minden nemzetségei közül az Úrhoz? Mert nagy esküt tettek volt egyszer a felől, a ki fel nem jött az Úrhoz Mispába, mondván: Meghalván meghaljon az!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'És megszánák az Izráel fiai Benjámint, az ő atyjokfiát, és mondának: Kivágattatott ma egy nemzetség Izráelből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'Mit cselekedjünk azokkal, a kik megmaradtak, hogy feleséget kaphassanak? Mert mi megesküdtünk az Úrra, hogy nem adjuk nékik feleségül a mi leányainkat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'És mondának: Van-é valaki az Izráel nemzetségei közül, a ki nem jött fel az Úrhoz Mispába? És íme Jábes-Gileádból nem jött fel senki a gyülekezet táborába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, 'Mert megszámlálá magát a nép, és ímé nem vala ott senki a Jábes-Gileád lakosai közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'Ekkor elküldött a gyülekezet oda tizenkétezer harczban edzett férfiút, és megparancsolták nékik, mondván: Menjetek el, és vágjátok le Jábes-Gileád lakóit fegyvernek élivel, még az asszonyokat és a gyermekeket is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'És ezt kell cselekednetek, hogy minden férfiút és minden asszonyt, a ki már férfiúval hált, öljetek meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'Találának pedig a Jábes-Gileád lakói között négyszáz szűz leányt, a kik még nem ismertek férfiút férfival való hálással, és elvitték őket a táborba Silóba, mely vala a Kanaán földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'És elküldött az egész gyülekezet, és izent a Benjámin fiainak, kik a Rimmon szikláján voltak, és békességet ígérének nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'Így tért vissza abban az időben Benjámin, és nékik adták azokat feleségül, a kiket meghagytak Jábes-Gileád asszony népei közül; de így sem lőn elég nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'És bánkódék a nép Benjámin miatt, hogy az Úr ilyen rést csinált az Izráel törzsein.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, 'Mondának azért a gyülekezet vénei: Mit tegyünk, hogy a többiek is feleséget kapjanak, mert Benjáminból kipusztíttattak az asszonyok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'És mondának: A Benjáminiták birtoka örökség szerint ezeké, a kik megmaradtak, mert nem szabad Izráelben egy nemzetségnek sem eltöröltetni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'De mi nem adhatunk nékik feleségeket leányaink közül, mert megesküdtek az Izráel fiai, mondván: Átkozott, a ki feleséget ad Benjáminnak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, 'És mondának: Ímé az Úrnak esztendőnként való ünnepnapja lesz most Silóban, a mely északra fekszik Bétheltől, napkelet felé az országút mellett, a mely Bétheltől Sikem felé visz, és délre Lebonától.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'Ezt parancsolák azért a Benjámin fiainak: Menjetek el, és leselkedjetek a szőlőkben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'És ha látjátok, hogy jőnek Siló leányai a körtánczban tánczolni, akkor jőjjetek elő a szőlőkből, és vegyetek magatoknak kiki feleséget a Siló leányai közül, és menjetek el a Benjámin földére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'Ha aztán atyjaik vagy testvéreik hozzánk jőnek perlődni, akkor azt mondjuk nékik: Könyörüljetek rajtuk mi érettünk, mert nem hozhattunk mindeniknek feleséget ama hadból, és minthogy nem ti adtátok nékik, most nem vagytok vétkesek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'És ekképen cselekedtek a Benjámin fiai, és vőnek feleségeket az ő számuk szerint a tánczolók közül, a kiket elraboltak. És elmentek, és hazatértek örökségükbe, és felépítették a városokat, és azokban laktak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'Az Izráel fiai pedig eltávoztak onnét abban az időben, mindegyik a maga nemzetségéhez és háznépéhez, és elmentek onnét kiki a maga örökségébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, 'Ebben az időben nem volt király Izráelben; azért mindenki azt cselekedte, a mi jónak látszott az ő szemei előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, 'És lőn azon napokban, a mikor a bírák bíráskodának, éhség lőn a földön. És elméne egy férfi a Júda Bethleheméből, hogy Moáb mezején tartózkodjék; ő meg a felesége, és a két fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'A férfi neve Elimélek és felesége neve Naómi; két fiok neve pedig Mahlon és Kiljon; efrataiak, a Júda Bethleheméből valók. És eljutának Moáb mezejére, és ott valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'Meghala pedig Elimélek a Naómi férje, és marada ő és az ő két fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, 'A kik Moábita leányokat vőnek feleségül; az egyiknek neve Orpa, és a másiknak neve Ruth. És ott lakozának közel tíz esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'Meghalának ők is mind a ketten, Mahlon is, Kiljon is, és marada az asszony az ő két fia és férje nélkül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'Felkele azért ő és az ő menyei, és ő visszatére Moáb mezejéről; mert hallotta vala Moáb mezején, hogy meglátogatta az Úr az ő népét, hogy adjon nékik kenyeret.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'És kiméne arról a helyről, a hol volt, és vele a két menye. És menének az úton, hogy visszatérjenek Júda földére,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, 'És monda Naómi az ő két menyének: Menjetek, térjetek vissza, kiki az ő anyjának házához. Cselekedjék az Úr irgalmasságot veletek, a miképen ti cselekedtetek a megholtakkal és én velem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'Adja az Úr tinéktek, hogy találjatok nyugodalmat, kiki az ő férje házában. És megcsókolá őket; és ők nagy felszóval sírának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, 'És mondák néki: Bizony mi veled együtt térünk a te népedhez!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'Naómi pedig mondá: Térjetek vissza leányaim! Miért jönnétek én velem? Hát ugyan vannak-é még fiak az én méhemben, a kik férjeitek lehetnének?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, 'Térjetek vissza leányaim! menjetek, mert én már vénebb vagyok, semhogy férjhez mehetnék. Még ha azt mondanám is, hogy van reménységem; még ha ez éjjel férjhez mennék is és szülnék is fiakat:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, 'Ugyan megvárhatnátok-é őket, a míg felnőnek? Ugyan megtartóztatnátok-é magatokat miattok, hogy férjhez ne menjetek? Ne, édes leányaim! Mert nagyobb az én keserüségem, mint a tietek, mert engem talált az Úrnak keze.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, 'Azok pedig nagy felszóval tovább sírának. És Orpa megcsókolá az ő napát; Ruth azonban ragaszkodék hozzá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, 'Ő pedig monda: Ímé a te sógorasszonyod visszatért az ő népéhez, és az ő isteneihez, térj vissza te is a te sógorasszonyod után.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'Ruth pedig monda: Ne unszolj, hogy elhagyjalak, hogy visszaforduljak tőled. Mert a hova te mégy, oda megyek, és a hol te megszállsz, ott szállok meg; néped az én népem, és Istened az én Istenem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, 'A hol te meghalsz, ott halok meg, ott temessenek el engem is. Úgy tegyen velem az Úr akármit, hogy csak a halál választ el engem tőled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, 'Mikor pedig látá, hogy erősködik vele menni, nem szóla néki többet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'És menének mind a ketten, míglen Bethlehembe érkezének. És lőn, hogy mikor Bethlehembe érkezének, megmozdult az egész város miattok, és mondák: Nemde nem Naómi ez?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'És ő monda nékik: Ne hívjatok engem Naóminak, hívjatok inkább Márának, mert nagy keserűséggel illetett engem a Mindenható.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, 'Többed magammal mentem el, és elárvultan hozott vissza engemet az Úr; miért hívnátok hát engem Naóminak, holott az Úr ellenem fordult, és a Mindenható nyomorúsággal illetett engemet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, 'Így tért vissza Naómi, és vele a Moábita Ruth, az ő menye, a ki hazatért Moáb mezejéről. Megérkezének pedig Bethlehembe az árpaaratás kezdetén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, 'Vala pedig Naóminak egy rokona az ő férje után, előkelő derék ember Elimélek nemzetségéből; neve Boáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, 'És monda a Moábita Ruth Naóminak: Hadd menjek, kérlek, a mezőre, hogy kalászokat szedegessek az után, a kinek szemei előtt kedvességet találok. És az monda: Menj édes leányom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, 'Elméne azért és odaérkezék, szedegete a mezőn az aratók után, és történetesen oda talált a Boáz szántóföldjére, a ki Elimélek nemzetségéből való volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, 'És ímé Boáz kijöve Bethlehemből, és monda az aratóknak: Az Úr legyen veletek! És ők mondának néki: Áldjon meg téged az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'És monda Boáz az ő szolgájának, a ki az aratók felügyelője volt: Kié ez a leányzó?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, 'És felele a szolga, az aratók felügyelője, és monda: Az a Moábita leányzó ez, a ki Naómival jött a Moáb mezejéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'A ki mondá: Hadd szedegessek, kérlek, és hadd tarlózgassak a kévék közt az aratók után. És ide jöve, és itt marada reggeltől fogva mind mostanig: és csak épen most pihent egy keveset a házban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'És mondá Boáz Ruthnak: Ugyan hallod-é édes leányom! Ne menj szedegetni más mezőre és el ne menj innen; hanem menj mindenütt szolgálóim után.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, 'Szemeid legyenek a mezőn, a melyet aratnak, és járj utánok. Ímé meghagytam a szolgáknak, hogy ne bántsanak téged, és ha megszomjúhozol, menj az edényekhez és igyál abból, a mit a szolgák merítenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, 'Akkor ez arczra borula és meghajtá magát a földig, és monda néki: Hogy-hogy találtam ilyen kedvességet a te szemeid előtt, hogy rám tekintettél, holott én idegen vagyok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'Boáz pedig felele, és monda néki: Bizony elmondtak nékem mindent, amit cselekedtél a te napaddal, férjed halála után, hogy elhagytad a te atyádat és a te anyádat és a te születésednek földét, és jöttél ahhoz a néphez, a melyet nem ismertél azelőtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'Fizessen meg az Úr a te cselekedetedért, és legyen teljes a te jutalmad az Úrtól, Izráelnek Istenétől, a kinek szárnyai alatt oltalmat keresni jöttél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, 'Ez pedig monda: Találjak kedvességet a te szemeid előtt uram, mert megvigasztaltál engem, és mert a te szolgálódnak szívéhez szóltál, holott én nem vagyok a te szolgálóleányaid közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'És az evésnek idejekor szóla néki Boáz: Jer ide, és egyél a kenyérből, és mártsd be a te falatodat az eczetes lébe. És ő leüle az aratók mellé. És pergelt gabonát nyújtott néki, és evett, s jóllakott, sőt még hagyott is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'Azután felállott, hogy szedegessen és Boáz megparancsolta az ő szolgáinak, mondván: A kévék között is hadd szedegessen, és meg ne pirongassátok őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, 'Sőt húzogassatok ki néki a kévékből is, és hagyogassatok el, hogy szedje fel, és meg ne dorgáljátok őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, 'És ő szedegete a mezőn mind estiglen, és kicsépelé, a mit szedegetett, és lett abból szinte egy efa árpa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, 'És felvevé és beméne a városba, és napaasszonya látá, a mit ő szedegetett. Aztán elővevé és odaadá néki, a mit meghagyott, minekutána jóllakott vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, 'És monda néki az ő napaasszonya: Hol szedegettél ma, és hol munkálkodtál? Áldott legyen, a ki rád tekintett. És elbeszélte az ő napaasszonyának, hogy kinél munkálkodott, és monda: Annak a férfiúnak a neve, a kinél ma munkálkodtam: Boáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'És monda Naómi az ő menyének: Áldott legyen ő az Úrtól, a ki nem vonta meg irgalmasságát az élőktől és a megholtaktól! És Naómi monda néki: Közel valónk nékünk az a férfiú; legközelebbi rokonaink közül való ő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'És szóla a Moábita Ruth: Még azt is mondta ő nékem: Menj mindenütt az én munkásaim után, a míg csak el nem végzik az én egész aratásomat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'És monda Naómi Ruthnak, az ő menyének: Jó, édes leányom, hogy az ő szolgálóival jársz, ne is találjanak téged más mezőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, 'Így járt ő mindenütt a Boáz szolgálói után, szedegetve, míg az árpaaratás és búzaaratás bevégződött; és az ő napaasszonyával lakott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, 'És monda néki Naómi, az ő napaasszonya: Édes leányom! ne keressek-é néked nyugalmat, hogy jól legyen dolgod?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, 'Avagy nem rokonunk-é Boáz, a kinek szolgálóival voltál? Ímé ő az éjjel árpát szór a szérűn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, 'Annakokáért fürödjél meg, és kend meg magadat, és vedd magadra ruháidat, és menj le a szérűre; észre ne vétesd magadat a férfiúval, a míg el nem végezi ételét és italát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, 'És majd ha lefekszik, jegyezd meg a helyet, a hol fekszik, és menj oda, és hajtsd fel a leplet lábánál, és feküdjél oda. Ő majd megmondja néked, mit cselekedjél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'És ő monda néki: Mindazt, a mit mondasz, megcselekszem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'És lement a szérűre, és mindent úgy cselekedett, a mint napaasszonya parancsolta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, 'És Boáz evett és ivott, és felvidámult az ő szíve. És elment, hogy lefeküdjék a garmada szélén; és az eljött titkon, és felhajtá lába felől a leplet, és lefeküvék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, 'Történt pedig éjfél tájon, hogy felrettent a férfiú, és odafordult. És ímé: asszony fekszik az ő lábainál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, 'És monda: Kicsoda vagy te? És az monda: Én Ruth vagyok, a te szolgálód; terjeszszed ki hát takaródat a te szolgálódra, mert te vagy a legközelebbi rokon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, 'És ő monda: Az Úrnak áldotta vagy te, édes leányom! Utóbbi szereteteddel jobbat cselekedtél, mint az elsővel: hogy nem jártál az ifjak után, sem szegény, sem gazdag után.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'Most hát, édes leányom, ne félj! Mindent, a mit mondasz, megteszek néked; mert tudja az én népemnek egész kapuja, hogy derék asszony vagy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, 'És most: bizony igaz, hogy közel rokon vagyok: de van nálamnál még közelebbi rokon is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, 'Ez éjszakán hálj itt; s majd reggel, ha az megvált téged, jó: váltson meg; ha pedig nem akar téged megváltani, akkor én váltalak meg. Él az Úr! Feküdj itt reggelig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'És feküvék az ő lábainál reggelig, és felkele, mielőtt valaki az ő felebarátját megismerheté, mert mondá: Meg ne tudja senki, hogy ez az asszony a szérűre jött.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, 'És monda: Add ide a nagy kendődet, a mely rajtad van, és tartsd. És ő oda tartotta azt. Boáz pedig mért hat mérték árpát, és feladta néki, maga pedig bement a városba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, 'És elméne az ő napaasszonyához, és az monda: Hogy vagy édes leányom? És ő elbeszélt néki mindent, a mit cselekedett vele az a férfi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, 'És monda: Ezt a hat mérték árpát adá nékem, mert monda: Ne menj üresen a te napadhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, 'És monda Naómi: Légy veszteg leányom, míg megtudod, hova dől el a dolog; mert nem nyugszik az a férfiú, míg véghez nem viszi a dolgot még ma.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, 'Boáz pedig felment a kapuba, és ott leült. És ímé arra ment az a legközelebbi rokon, a kiről Boáz beszélt vala, és monda néki: Jer csak, ülj ide atyafi. És az oda ment és leüle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'Ekkor ő maga mellé vett tíz férfiút a város vénei közül és monda: Üljetek ide! És azok leülének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, 'És ő monda a legközelebbi rokonnak: Azt a darab szántóföldet, mely a mi atyánkfiáé, Eliméleké volt, eladja Naómi, a ki haza jött a Moáb mezejéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, 'Én pedig gondoltam, hogy füledbe juttatom, mondván: Vedd meg az itt ülők előtt és az én népemnek vénei előtt. Ha megváltod: váltsd meg; és ha nem váltod meg: jelentsd ki előttem, hogy tudjam; mert rajtad kívül nincs, a ki megváltaná, és én vagyok utánad. És az monda: Én megváltom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'És monda Boáz: A mely napon megveszed a szántóföldet Naómi kezéből, akkor a Moábita Ruthtól, a megholtnak feleségétől veszed meg, hogy nevet támaszsz a megholtnak, az ő örökségében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, 'A legközelebbi rokon pedig monda: Nem válthatom meg magamnak, hogy el ne veszessem a magam örökségét; váltsd meg te magadnak az én rokoni részemet, mert én nem válthatom meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, 'Ez vala pedig a szokás régen Izráelben, a megváltás és cserélés alkalmával, minden dolognak megerősítésére: A férfi lehúzta az ő saruját és oda adta felebarátjának, és ez volt a bizonyság Izráelben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, 'Monda annakokáért a legközelebbi rokon Boáznak: Vedd meg magadnak! És lehúzta a saruját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'És monda Boáz a véneknek és az egész népnek: Ti vagytok tanui ma, hogy megvettem mindent, a mi Eliméleké volt, és mindent, a mi Kiljoné és Mahloné volt, Naómi kezéből;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, 'Sőt a Moábita Ruthot is, Mahlonnak feleségét feleségül vettem, hogy nevet támaszszak a megholtnak az ő örökségében, és ki ne veszszen a megholtnak neve az ő atyjafiai közül és az ő helységének kapujából. Tanuk vagytok ma.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, 'És monda az egész nép, mely a kapuban vala és a vének: Tanuk vagyunk! Tegye az Úr az asszonyt, a ki a te házadba megy, olyanná, mint Rákhel és Lea, a kik ketten építették fel Izráel házát, és gyűjts vagyont Efratában és szerezz nevet Bethlehemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'És a te házad legyen, miként a Pérecz háza – a kit Thámár szült Júdának – abból a magzatból, a melyet az Úr adánd néked ettől az asszonytól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, 'Elvevé annakokáért Boáz Ruthot, és lőn az néki felesége, és beméne hozzá, és megadá az Úr, hogy az fogana az ő méhében, és szült fiút.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, 'És mondák az asszonyok Naóminak: Áldott az Úr, a ki ma nem engedte meg, hogy rokon nélkül maradj; emlegessék az ő nevét Izráelben!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, 'És legyen ő a te lelkednek megvidámítója, és vénségednek istápolója, mert menyed szülte őt, az, a ki téged szeret, és a ki többet ér néked hét fiúnál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'Ekkor megfogá Naómi a gyermeket, és ölébe vevé, és dajkája lőn annak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'A szomszédasszonyok pedig nevet adának néki, mondván: Fia született Naóminak, és nevezték az ő nevét Obednek. Ez az apja Isainak, a Dávid atyjának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, 'És a Pérecz nemzetségei ezek: Pérecz nemzé Hesront;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'Hesron pedig nemzé Rámot, és Rám nemzé Amminádábot;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'Amminádáb pedig nemzé Naássont, és Naásson nemzé Sálmónt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'Sálmón pedig nemzé Boázt, és Boáz nemzé Obedet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'És Obed nemzé Isait, Isai pedig nemzé Dávidot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'Volt egy ember, Ramataim-Czofimból, az Efraim hegységéről való, és az ő neve Elkána vala, Jerohámnak fia, ki Elihu fia, ki Tohu fia, ki Sof fia volt; Efraimita vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'És két felesége volt néki; az egyiket Annának, a másikat pedig Peninnának hívták. Peninnának gyermekei valának, de Annának nem valának gyermekei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, 'És ez az ember felmegy vala esztendőnként az ő városából, hogy imádkozzék és áldozatot tegyen a Seregek Urának Silóban. Ott pedig Éli két fia, Hofni és Fineás valának az Úrnak papjai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'És azon a napon, melyen Elkána áldozni szokott, Peninnának, az ő feleségének, és minden fiának és leányának áldozati részt ád vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'Annának pedig kétakkora részt ád vala, mivel Annát igen szerette; de az Úr bezárá az ő méhét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, 'Igen bosszantja vala pedig Annát vetélkedő társa, hogy felingerelje, mivel az Úr bezárá az ő méhét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, 'És így történt ez esztendőről esztendőre; valahányszor felment az Úrnak házába, ekképen bosszantá őt, ő pedig sír vala és semmit sem evék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, 'És monda néki Elkána, az ő férje: Anna, miért sírsz, és miért nem eszel? Mi felett bánkódol szívedben? Avagy nem többet érek-é én néked tíz fiúnál?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, 'És felkele Anna, minekutána evének Silóban és minekutána ivának, (Éli pap pedig az Úrnak templomában az ajtófélnél ül vala székében),');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'És lelkében elkeseredve, könyörge az Úrnak, és igen sír vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, 'És fogadást tőn, mondván: Seregeknek Ura! ha megtekinted a te szolgáló leányodnak nyomorúságát, és megemlékezel rólam, és nem feledkezel el szolgáló leányodról, hanem fiúmagzatot adsz szolgáló leányodnak: én őt egész életére az Úrnak ajánlom, és borotva nem érinti az ő fejét soha!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'Mivelhogy pedig hosszasan imádkozék az Úr előtt: Éli figyel vala az ő szájára;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'És mivel Anna szívében könyörge (csak ajka mozgott, szava pedig nem volt hallható): Éli gondolá, hogy részeg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, 'Monda azért néki Éli: Meddig leszel részeg? Távolítsd el mámorodat magadtól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'Anna pedig felele, és monda néki: Nem, Uram! bánatos lelkű asszony vagyok én; sem bort, sem részegítő italt nem ittam, csak szívemet öntöttem ki az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, 'Ne tartsd a te szolgáló leányodat rossz asszonynak, mert az én bánatomnak és szomorúságomnak teljességéből szólottam eddig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'És felele Éli, és monda: Eredj el békességgel, és Izráelnek Istene adja meg a te kérésedet, a melyet kértél tőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'Ő pedig monda: Legyen kedves előtted a te szolgáló leányod! És elméne az asszony az ő útjára és evék, és arcza nem vala többé szomorú.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, 'És reggel felkelének, és minekutána imádkozának az Úr előtt, visszatértek, és elmenének haza Rámába. És ismeré Elkána az ő feleségét, Annát, és az Úr megemlékezék róla.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'És történt idő multával, hogy terhes lőn Anna, és szüle fiat és nevezé őt Sámuelnek, mert úgymond az Úrtól kértem őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, 'És mikor felméne a férfi, Elkána és az ő egész háznépe, hogy bemutassa az Úrnak esztendőnként való áldozatát és fogadását:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, 'Anna nem ment fel, hanem monda férjének: Mihelyt a gyermeket elválasztándom, felviszem őt, hogy az Úr előtt megjelenjen, és ott maradjon örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, 'És monda néki Elkána, az ő férje: Cselekedjél úgy, a mint néked tetszik, maradj itthon, míg elválasztod; csakhogy az Úr teljesítse be az ő beszédét! Otthon marada azért az asszony és szoptatta gyermekét, a míg elválasztá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, 'És minekutána elválasztotta, felvivé magával; három tulokkal, egy efa liszttel és egy tömlő borral, és bevivé őt az Úrnak házába, Silóban. A gyermek pedig még igen kicsiny vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, 'És levágták a tulkot, és a gyermeket Élihez vitték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'Ő pedig monda: Óh Uram! Él a te lelked, Uram, hogy én vagyok az az asszony, a ki itt állott melletted, és könyörgött az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'Ezért a fiúért könyörögtem, és az Úr megadta kérésemet, a melyet tőle kértem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, 'Most azért én is az Úrnak szentelem; teljes életére az Úrnak legyen szentelve! És imádkozának ott az Úrhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, 'És imádkozék Anna, és monda: Örvendez az én szívem az Úrban, Felmagasztaltatott az én szarvam az Úrban. Az én szám felnyílt ellenségeim ellen, Mert szabadításodnak örvendezek én!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'Senki sincs olyan szent, mint az Úr, Sőt rajtad kivül senki sincs. Nincsen olyan kőszál, mint a mi Istenünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, 'Ne szóljatok oly kevélyen, oly nagyon kevélyen; Szátokból ne jőjjön kérkedő szó, Mert mindentudó Isten az Úr, És a cselekedeteket ő ítéli meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, 'Az erős kézíjjasokat megrontja, És a roskadozókat erővel övedzi fel,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, 'A megelégedettek bérért szegődnek el, Éhezők pedig nem lesznek; S míg a magtalan hét gyermeket szül, A sok gyermekű megfogyatkozik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'Az Úr öl és elevenít, Sírba visz és visszahoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'Az Úr szegénynyé tesz és gazdagít, Megaláz s fel is magasztal;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'Felemeli a porból a szegényt, És a sárból kihozza a szűkölködőt, Hogy ültesse hatalmasok mellé, És a dicsőségnek székét adja nékik; Mert az Úré a földnek oszlopai, És azokra helyezé a föld kerekségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'Híveinek lábait megoltalmazza, De az istentelenek setétségben némulnak el, Mert nem az erő teszi hatalmassá az embert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, 'Az Úr, a kik vele versengenek, megrontja, Mennydörög felettök az égben, Az Úr megítéli a földnek határait, Királyának pedig hatalmat ad, És felemeli felkentjének szarvát!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'Elméne ezután Elkána Rámába az ő házához; a gyermek pedig az Úrnak szolgája lett Éli pap előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, 'Éli fiai azonban Béliál fiai valának, nem ismerék az Urat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, 'És a papoknak ez vala szokásuk a néppel szemben: Ha mikor valaki áldozatot tesz vala, eljött a papnak szolgája, midőn a húst főzték, és a háromágú villácska az ő kezében vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, 'És beüti vala a serpenyőbe, vagy üstbe, vagy fazékba, vagy edénybe, és mindent, a mit a villácskával kihúz, magának veszi el a pap. Így cselekesznek egész Izráellel, kik oda mennek Silóba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, 'És minekelőtte a kövérét megáldoznák, eljön a papnak szolgája és azt mondja az áldozó embernek: Adj a papnak sütni való húst, mert nem fogad el tőled főtt húst, hanem csak nyerset.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'És ha az ember azt mondja néki: Hadd gyújtsák meg most a kövérét, azután vedd el, a mint lelked kívánja: akkor azt mondják vala: Semmiképen nem, hanem most adjad, mert ha nem, erővel elveszem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, 'Igen nagy volt azért az ifjaknak bűne az Úr előtt, mert az emberek megútálják vala az Úrnak áldozatát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'Sámuel pedig szolgál vala az Úrnak, mint gyermek, gyolcs efóddal körül övezve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'És anyja kicsiny felső ruhát csinált vala néki, és felvivé néki esztendőnként, mikor férjével felment az esztendőnként való áldozat bemutatására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'És megáldá Éli Elkánát és az ő feleségét, és monda: Adjon az Úr néked magzatot ez asszonytól a helyett, a kiért könyörgött, és a kit az Úrnak kért. És haza menének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'És meglátogatá az Úr Annát, ki az ő méhében fogada, és szült három fiút és két leányt. És a gyermek Sámuel felnevekedék az Úrnál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'Éli pedig igen vén vala, és meghallá mindazt, a mit fiai cselekesznek egész Izráellel, és hogy az asszonyokkal hálnak, kik a gyülekezet sátorának nyílása előtt szolgálnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'Monda azért nékik: Miért cselekesztek ilyen dolgot? Mert hallom a ti gonosz cselekedeteiteket mind az egész néptől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'Ne tegyétek fiaim! mert nem jó hír az, melyet hallok; vétkessé teszitek az Úrnak népét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, 'Ha ember embertársa ellen vétkezik, megítéli az Isten; de ha az Úr ellen vétkezik az ember, ki lehetne érette közbenjáró? De nem hallgatának atyjok szavára, mert az Úr meg akará őket ölni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, 'A gyermek Sámuel pedig folytonosan növekedék és kedves volt mind az Úr, mind az emberek előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, 'És eljöve Istennek embere Élihez, és monda néki: Így szól az Úr: Nem jelentettem-é ki magamat atyád házának, midőn Égyiptomban a Faraó házában valának?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, 'És kiválasztám őt papnak Izráel minden nemzetségei közül magamnak, hogy áldozzon az én oltáromon; hogy füstölő szert füstölögtessen, hogy az efódot előttem viselje; és atyád házára bíztam Izráel fiainak minden tüzes áldozatait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'Miért tapossátok meg az én véres áldozatomat és ételáldozatomat, melyet rendeltem e hajlékban? És te többre becsülöd fiaidat, mint engem, hogy magatokat hízlaljátok az én népem Izráel minden áldozatának elejével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, 'Azért így szól az Úr, Izráelnek Istene, jóllehet megmondottam, hogy a te házad és atyádnak háza mindörökké én előttem jár; de most, azt mondja az Úr, távol legyen tőlem, mert a kik engem tisztelnek, azoknak tisztességet szerzek, a kik azonban engem megutálnak, megutáltatnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, 'Ímé, napok jőnek, és levágom a te karodat és atyád házának karját, hogy ne legyen vén ember a te házadban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, 'És meglátod az Isten hajlékának szorongattatását, mind a helyett, a mi jót cselekedett volna Izráellel; és nem lészen vén ember a te házadban soha.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'Mindazonáltal nem fogok mindenkit kiirtani oltárom mellől, te éretted, hogy szemeidet emészszem és lelkedet gyötörjem; de egész házadnépe férfikorban hal meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, 'És az legyen előtted a jel, a mi következik két fiadra, Hofnira és Fineásra, hogy egy napon halnak meg mind a ketten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, 'Támasztok azonban magamnak hűséges papot, ki kedvem és akaratom szerint cselekszik; és építek néki állandó házat, és az én felkentem előtt fog járni mindenkor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'És lészen, hogy mind az, a ki megmarad a te házadból, eljön, hogy leboruljon előtte egy ezüst pénzecskéért és egy darab kenyérért, és ezt mondja: ugyan helyezz el engem a papi tisztségek egyikébe, hogy ehessem egy falat kenyeret.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, 'És a gyermek Sámuel szolgál vala az Úrnak Éli előtt. És abban az időben igen ritkán volt az Úrnak kijelentése, nem vala nyilván való látomás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, 'És történt egyszer, mikor Éli az ő szokott helyén aludt, (szemei pedig homályosodni kezdének, hogy látni sem tudott),');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, 'És az Istennek szövétneke még nem oltatott el, és Sámuel az Úrnak templomában feküdt, hol az Istennek ládája volt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, 'Szólott az Úr Sámuelnek, ő pedig felele: Ímhol vagyok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'És Élihez szalada, és monda: Ímhol vagyok, mert hívtál engem; ő pedig felele: Nem hívtalak, menj vissza, feküdjél le. Elméne azért és lefeküvék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'És szólítá az Úr ismét: Sámuel! Sámuel pedig felkelvén, Élihez ment, és monda: Ímhol vagyok, mert hívtál engem. És ő felele: Nem hívtalak fiam, menj vissza, feküdjél le.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'Sámuel pedig még nem ismerte az Urat, mert még nem jelentetett ki néki az Úrnak ígéje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'És szólítá az Úr harmadszor is Sámuelt; ő pedig felkelvén, Élihez ment és monda: Ímhol vagyok, mert hívtál engem. Akkor eszébe jutott Élinek, hogy az Úr hívja a gyermeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, 'Monda azért Éli Sámuelnek: Menj el, feküdjél le, és ha szólítanak téged, ezt mondjad: Szólj Uram, mert hallja a te szolgád. Elméne azért Sámuel, és lefeküvék az ő helyére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'Akkor eljövén az Úr, oda állott és szólítá, mint annak előtte: Sámuel, Sámuel! És monda Sámuel: Szólj, mert hallja a te szolgád!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'És monda az Úr Sámuelnek: Ímé én oly dolgot cselekszem Izráelben, melyet valakik hallanak, mind a két fülök megcsendül bele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, 'Azon a napon véghez viszem Élin mind azt, a mit kijelentettem háza ellen; megkezdem és elvégezem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'Mert megjelentettem néki, hogy elítélem az ő házát mind örökre, az álnokság miatt, a melyet jól tudott, hogy miként teszik vala útálatosokká magokat az ő fiai, és ő nem akadályozta meg őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, 'Annakokáért megesküdtem az Éli háza ellen, hogy sohasem töröltetik el Éli házának álnoksága, sem véres áldozattal, sem ételáldozattal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'Aluvék azért Sámuel mind reggelig, és akkor kinyitá az Úr házának ajtait. És Sámuel nem meri vala megjelenteni Élinek a látomást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'Szólítá azért Éli Sámuelt, és monda: Fiam, Sámuel! Ő pedig felele: Ímhol vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'És monda: Mi az a dolog, melyet mondott néked az Úr? El ne titkold előttem! Úgy cselekedjék veled az Isten most és azután is, ha te valamit elhallgatsz előttem mind abból, a mit mondott néked!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'Megmondott azért Sámuel néki mindent, és semmit sem hallgatott el előtte. Ő pedig monda: Ő az Úr, cselekedjék úgy, a mint néki jónak tetszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'Sámuel pedig fölnevekedék, és az Úr vala ő vele, és semmit az ő ígéiből a földre nem hagy vala esni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'És megtudá egész Izráel Dántól Bersebáig, hogy Sámuel az Úr prófétájául rendeltetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'És az Úr kezde ismét megjelenni Silóban, mert kijelentette magát az Úr Sámuelnek Silóban, az Úrnak beszéde által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, 'És ismeretessé lett Sámuel beszéde egész Izráelben. És kiméne Izráel a Filiszteusok ellen harczolni, és tábort járának Ében-Ézernél, a Filiszteusok pedig tábort járának Áfekben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'És csatarendbe állának a Filiszteusok Izráel ellen, és megütközének, és megveretteték Izráel a Filiszteusok által, és levágának a harczmezőn mintegy négyezer embert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, 'És mikor a nép a táborba visszatért, mondának Izráel vénei: Vajjon miért vert meg minket ma az Úr a Filiszteusok előtt?! Hozzuk el magunkhoz az Úr frigyládáját Silóból, hogy jőjjön közénk az Úr, és szabadítson meg ellenségeink kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'Elkülde azért a nép Silóba, és elhozák onnan a Seregek Urának frigyládáját, a ki ül a Khérubok felett. Ott volt Éli két fia is az Isten frigyládájával, Hofni és Fineás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'És mikor az Úr frigyládája a táborba érkezék, rivalgott az egész Izráel nagy rivalgással, hogy megrendüle a föld.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'Mikor pedig meghallották a Filiszteusok a rivalgás hangját, mondának: Micsoda nagy rivalgás hangja ez a zsidók táborában? És mikor megtudták, hogy az Úrnak ládája érkezett a táborba,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'Megfélemlének a Filiszteusok, mert mondának: Isten a táborba jött! És mondának: Jaj nékünk! mert nem történt ilyen soha az előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'Jaj nékünk! Kicsoda szabadít meg minket ennek a hatalmas Istennek kezéből? Ez az az Isten, a ki Égyiptomot mindenféle csapással sújtotta a pusztában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'Legyetek bátrak és legyetek férfiak, Filiszteusok! hogy ne kelljen szolgálnotok a zsidóknak, mint a hogy ők szolgáltak néktek. Azért legyetek férfiak, és harczoljatok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'Megütközének azért a Filiszteusok, és megveretett Izráel, és kiki az ő sátorába menekült; és a vereség oly nagy volt, hogy Izráel közül harminczezer gyalog hullott el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, 'És az Isten ládája is elvétetett, és meghala Élinek mindkét fia, Hofni és Fineás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, 'Akkor elszalada a harczból egy ember a Benjámin nemzetségéből, és Silóba ment azon a napon, ruháit megszaggatván és port hintvén a fejére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, 'És ímé mikor oda ért, Éli az ő székében ült, az útfélen várakozván; mert szíve rettegésben volt az Isten ládája miatt. És mihelyt odaért az ember, hogy hírt mondjon a városban, jajveszékelt az egész város.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'És meghallotta Éli a kiáltás hangját, és monda: Micsoda nagy zajongás ez? Az az ember pedig sietve eljöve, és megmondotta Élinek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, 'Éli pedig kilenczvennyolcz esztendős volt, és szemei annyira meghomályosodtak, hogy már nem is látott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, 'És monda az ember Élinek: Én a harczból jövök, én a harczból menekültem ma. És monda: Mi dolog történt, fiam?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, 'Felele a követ, és monda: Megfutamodék Izráel a Filiszteusok előtt, és igen nagy veszteség lőn a népben, és a te két fiad is meghalt, Hofni és Fineás, és az Isten ládáját is elvették.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, 'És lőn, hogy midőn az Isten ládáját említé, hátraesék a székről a kapufélhez, és nyakát szegte és meghala, mert immár vén és nehéz ember vala. És ő negyven esztendeig ítélt Izráel felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'És az ő menye, Fineásnak felesége, várandós vala; és a mikor meghallá a hírt, hogy az Isten ládája elvétetett és az ő ipa és férje meghalának, térdre esék és szűle, mert a fájdalmak meglepték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, 'És mikor elalélt, mondának azok, akik mellette állanak vala: Ne félj, mert fiút szültél; de ő nem felelt és nem figyelt arra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, 'És nevezé a gyermeket Ikábódnak, mondván: „Oda van Izráel dicsősége”, mert elvétetett az Isten ládája, és az ő ipa és az ő férje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, 'És monda ismét: Oda van Izráel dicsősége, mert elvétetett az Isten ládája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'A Filiszteusok pedig vevék az Isten ládáját és elvitték Ében-Ézerből Asdódba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, 'És megfogták a Filiszteusok az Isten ládáját, és bevivén azt a Dágon templomába, Dágon mellé helyezték el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'És mikor az Asdódbeliek másnap korán felkelének, ímé Dágon leesett arczczal a földre az Úr ládája előtt. És felvevék Dágont, és ismét helyreállíták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'Mikor pedig másnap korán reggel felkelének, ímé Dágon ismét leesett arczczal a földre az Úr ládája előtt; és Dágonnak feje és két kezefeje letörve a küszöbön valának, csak Dágon dereka maradt meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, 'Annakokáért a Dágon papjai és mind azok, akik a Dágon templomába járnak, nem lépnek a Dágon küszöbére Asdódban mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'És az Úrnak keze az Asdódbeliekre nehezedék, és pusztítja vala őket; és megveré őket fekélyekkel, Asdódot és határait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'Mikor azért látták az Asdódbeliek, hogy így van a dolog, mondának: Ne maradjon nálunk Izráel Istenének ládája, mert reánk nehezedett az ő keze, és Dágonra, a mi istenünkre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, 'Elküldének tehát, és összegyűjték a Filiszteusoknak minden fejedelmeit, és mondának: Mit csináljunk Izráel Istenének ládájával? Azok pedig felelének: Vigyék Gáthba az Izráel Istenének ládáját. És elvivék Izráel Istenének ládáját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, 'És történt azután, hogy elvitték, az Úrnak keze igen nagy rémületére lőn a városnak; és megveré a városnak lakosait kicsinytől fogva nagyig, és fekélyek támadának rajtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, 'Elküldék azért az Istennek ládáját Ekronba. És lőn, hogy a mikor Ekronba jutott az Istennek ládája, felzúdulának az Ekronbeliek, mondván: Reám hozták Izráel Istenének ládáját, hogy megöljön engem és az én népemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'Annakokáért elküldének, és összegyűjték a Filiszteusoknak minden fejedelmeit, és mondának: Küldjétek el Izráel Istenének ládáját, hogy térjen vissza helyére, és ne öljön meg engem és az én népemet. Mert halálos rémület volt az egész városban; igen súlyos volt ott Istennek keze.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, 'És azok az emberek, a kik nem haltak meg, fekélyekkel sújtattak annyira, hogy a város jajkiáltása felhatott az égig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'És az Úrnak ládája hét hónapig volt a Filiszteusok földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'Akkor szólíták a Filiszteusok a papokat és jövendőmondókat, mondván: Mit tegyünk az Úrnak ládájával? Mondjátok meg nékünk, mi módon küldjük haza?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, 'Azok pedig felelének: Ha elkülditek Izráel Istenének ládáját, ne küldjétek azt üresen, hanem hozzatok néki vétekért való áldozatot; akkor meggyógyultok, és megtudjátok, miért nem távozik el az ő keze rólatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, 'És mondának: Micsoda az a vétekért való áldozat, melyet hoznunk kell néki? Azok pedig felelének: A Filiszteusok fejedelmeinek száma szerint öt fekélyforma arany és öt arany egér, mert ugyanazon csapás van mindeneken, a ti fejedelmeiteken is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, 'Csináljátok meg azért fekélyeiteknek képmását és egereiteknek képmását, melyek pusztítják a földet, és így adjatok Izráel Istenének dicsőséget, talán megkönnyebbedik az ő keze rajtatok, és a ti isteneteken és földeteken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, 'Miért keményítenétek meg szíveiteket, mint megkeményítették szívöket Égyiptom és a Faraó? Avagy nem úgy volt-é, hogy a mint hatalmát megmutatta rajtok, elbocsátá őket, hogy elmenjenek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'Most azért vegyetek és készítsetek egy új szekeret és két borjas tehenet, melyeken még nem volt járom; és fogjátok be a szekérbe a teheneket, borjaikat pedig vigyétek el tőlök haza;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'És vegyétek az Úrnak ládáját, és tegyétek a szekérre; az aranyszerszámokat pedig, melyeket vétekért való áldozatul hoztok néki, tegyétek egy táskába az oldalára, és bocsássátok el, hadd menjen el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'És nézzetek utána, hogy ha az ő határának útján Béth-Semes felé tart, akkor ő szerezte nékünk ezt a nagy bajt; ha pedig nem, akkor megtudjuk, hogy nem az ő keze sújtott minket, hanem csak véletlen volt az, a mi velünk történt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, 'Úgy cselekedének azért az emberek; és vettek két borjas tehenet, és befogták a szekérbe, borjaikat pedig berekeszték otthon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'És feltették az Úrnak ládáját a szekérre és a táskát az arany egerekkel és fekélyeiknek képmásával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, 'A tehenek pedig egyenesen a Béth-Semes felé vivő úton menének; egy úton mentek, folytonosan bőgve, és sem jobbra, sem balra nem térének le. És a Filiszteusok fejedelmei utánok menének Béth-Semes határáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, 'A Béth-Semesbeliek pedig búzaaratással foglalkozának a völgyben, és felemelvén szemeiket, meglátták a ládát: és örvendezének, hogy látták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, 'A szekér pedig eljutott a Béth-Semesből való Józsua mezejére, és ott megállott. Vala pedig ott egy nagy kő, és felvagdalták a szekér fáit és a teheneket megáldozták az Úrnak egészen égőáldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'Akkor a Léviták levették az Úrnak ládáját és a táskát, mely mellette volt, melyben az aranyszerszámok valának, és a nagy kőre helyezték. A Béth-Semesbeli emberek pedig azon a napon egészen égőáldozatot és véres áldozatot áldoztak az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'És mikor a Filiszteusok öt fejedelme ezt látta, visszatére azon napon Ekronba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'Az arany fekélyek pedig, melyeket a Filiszteusok vétekért való áldozatul hoztak az Úrnak, ezek: egyet Asdódért, egyet Gázáért, egyet Askelonért, egyet Gáthért, egyet Ekronért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'Az arany egerek pedig a Filiszteusok minden városainak száma szerint valának, melyek az öt fejedelem alá tartoztak, a kerített városoktól a kerítetlen helységekig. És bizonyság az a nagy kő, a melyre az Úrnak ládáját helyezték, mind a mai napig, a Béth-Semesből való Józsua mezején.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, 'És megvere az Úr a Béth-Semesbeliek közül némelyeket, mivel az Úrnak ládájába tekintének. Megvere pedig a nép közül ötvenezer és hetven embert. És a nép szomorkodott, hogy az Úr ily nagy csapással sújtotta vala a népet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'Mondának azért a Béth-Semesbeliek: Kicsoda állhat meg az Úr előtt, e szent Isten előtt? És kihez megy el mi tőlünk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'Követeket küldének akkor Kirjáth-Jeárim lakosaihoz, mondván: A Filiszteusok visszahozták az Úrnak ládáját, jőjjetek el, és vigyétek el azt magatokhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'És eljövének a Kirjáth-Jeárimbeliek, és felvitték az Úrnak ládáját, és bevivék Abinádáb házába, mely a dombon vala; és Eleázárt, az ő fiát az Úr ládájának őrizésére rendelék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, 'És lőn, hogy attól a naptól fogva, a melyen Kirjáth-Jeárimban hagyták a ládát, sok idő eltelék, tudniillik húsz esztendő. És Izráelnek egész háza síránkozék az Úr után.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, 'Sámuel pedig szóla Izráel egész házához, mondván: Ha ti teljes szívetekből megtértek az Úrhoz, és eltávolítjátok magatok közül az idegen isteneket és Astarótot, és szíveiteket elkészítitek az Úrnak, és csak néki szolgáltok: akkor megszabadít titeket a Filiszteusok kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'Elhányák azért Izráel fiai a bálványokat és Astarótot, és csak az Úrnak szolgálának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'Akkor Sámuel mondá: Gyűjtsétek össze egész Izráelt Mispába, hogy imádkozzam értetek az Úrhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'Összegyűlének azért Mispában, és vizet merítvén, kiönték az Úr előtt; és bőjtölének azon a napon, és így szólának ott: Vétkeztünk az Úr ellen. És ekképen ítélé Sámuel Izráel fiait Mispában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'Mikor pedig a Filiszteusok meghallották, hogy Izráel fiai összegyűlének Mispában, feljöttek a Filiszteusok fejedelmei Izráel ellen. És mikor ezt meghallották Izráel fiai, megrémülének a Filiszteusoktól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'És mondának Izráel fiai Sámuelnek: Ne szünjél meg érettünk könyörögni az Úrhoz, a mi Istenünkhöz, hogy szabadítson meg minket a Filiszteusok kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'Vett azért Sámuel egy szopós bárányt, és megáldozá azt egészen égőáldozatul az Úrnak. És fohászkodék Sámuel Izráelért az Úrhoz, és az Úr meghallgatá őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'És lőn, hogy a mikor Sámuel az égőáldozatot végezé, eljövének a Filiszteusok, hogy Izráel ellen harczoljanak. Az Úr pedig mennydörge nagy hangon azon a napon a Filiszteusok felett és annyira megzavarta őket, hogy megverettetének Izráel előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'Akkor kijövének Izráel emberei Mispából, és üldözték a Filiszteusokat és verték őket egészen Bethkáron alól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'Sámuel pedig vett egy követ, és felállítá Mispa és Sén között, és Ében-Háézernek nevezte el, mert mondá: Mindeddig megsegített minket az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'És megaláztatának a Filiszteusok, és nem menének többé Izráel határára. És az Úrnak keze a Filiszteusok ellen volt Sámuelnek teljes életében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'És visszavevé Izráel a városokat, a melyeket a Filiszteusok Izráeltől elvettek vala, Ekrontól fogva Gáthig, és az ő határukat megszabadítá Izráel a Filiszteusok kezéből. És békesség lőn Izráel és az Emoreusok között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'Sámuel pedig életének minden napjaiban ítéle Izráel felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, 'És elmegy vala esztendőnként, és bejárá Béthelt, Gilgált és Mispát, és ítéletet hozott vala Izráel felett mind e helyeken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, 'Annakutána visszatére Rámába, mert ott vala az ő háza, és ott is ítéletet hoza Izráel felett; és oltárt építe ott az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'És lőn, hogy a mikor Sámuel megvénhedett, az ő fiait tevé bírákká Izráel felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, 'Elsőszülött fiának pedig Joel volt a neve és a másodiknak Abia, kik Beérsebában bíráskodtak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, 'De fiai nem járának az ő útjain, hanem a telhetetlenség után indulának, és ajándékot fogadának el, és elfordíták az igaz ítéletet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, 'Összegyűlének azért Izráelnek minden vénei, és elmentek Sámuelhez Rámába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'És mondának néki: Ímé te megvénhedtél, és fiaid nem járnak útaidon; most azért válaszsz nékünk királyt, a ki ítéljen felettünk, mint minden népnél szokás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, 'Azonban Sámuelnek nem tetszék a beszéd, hogy azt mondák: Adj nékünk királyt, a ki ítéljen felettünk. És könyörge Sámuel az Úrhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'És monda az Úr Sámuelnek: Fogadd meg a nép szavát mindenben, a mit mondanak néked, mert nem téged útáltak meg, hanem engem útáltak meg, hogy ne uralkodjam felettök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, 'Mindama cselekedetek szerint, a melyeket véghez vittek attól a naptól kezdve, a melyen kihoztam őket Égyiptomból, egészen a mai napig (hogy elhagytak engem, és idegen isteneknek szolgáltak): veled is a szerint cselekesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, 'Most azért hallgass szavukra; mindazáltal tégy ellenök bizonyságot, és add tudtokra a király hatalmát, a ki uralkodni fog felettök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'És Sámuel megmondá az Úrnak minden beszédeit a népnek, mely tőle királyt kért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'És monda: A királynak, a ki uralkodni fog felettetek, ez lesz a hatalma: fiaitokat elveszi és szekér vezetőivé és lovasaivá teszi őket, és szekere előtt futnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'Ezredesekké teendi őket, és hadnagyokká ötven ember felett; velök szántatja meg barázdáit, és velök végezteti aratását, készítteti hadi szerszámait és harczi szekereihez az eszközöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'Leányaitokat pedig elviszi kenőcskészítőknek, szakácsnéknak és sütőknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, 'Elveszi legjobb szántóföldeiteket, szőlőhegyeiteket és olajfás kerteiteket, és szolgáinak adja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, 'Veteményeiteket és szőlőiteket megdézsmálja, és főbb embereinek és szolgáinak adja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'Elveszi szolgáitokat, szolgálóitokat, legszebb ifjaitokat és szamaraitokat, és a maga dolgát végezteti azokkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, 'Barmaitokat megdézsmálja, és ti szolgái lesztek néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, 'És panaszkodni fogtok annak idejében királyotok miatt, kit magatok választottatok, de az Úr nem fog meghallgatni akkor titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, 'A nép azonban nem akart Sámuel szavára hallgatni, és mondának: Nem! hanem király legyen felettünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, 'És mi is úgy legyünk, mint a többi népek, hogy királyunk ítéljen minket is, és előttünk járjon, és vezesse a mi harczainkat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'És miután Sámuel meghallgatta a népnek minden szavát, megmondta azokat az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'És monda az Úr Sámuelnek: Hallgass szavokra, és adj nékik királyt. És Sámuel monda Izráel férfiainak: Menjetek el haza, ki-ki az ő városába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, 'És volt egy ember a Benjámin nemzetségéből, kinek neve vala Kis, Abielnek fia, ki Sérornak fia, ki Bekoráthnak fia, ki Afiákhnak fia, ki Benjámin házából való volt; igen tehetős ember vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'És volt néki egy Saul nevű fia, ifjú és szép; ő nála Izráel fiai közül senki sem volt szebb; vállától felfelé magasabb vala az egész népnél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'És elvesztek vala Kisnek, a Saul atyjának szamarai, és monda Kis Saulnak, az ő fiának: Végy magad mellé egyet a szolgák közül, és kelj fel, menj el, keresd meg a szamarakat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'És bejárá az Efraim hegységét, és bejárta Salisa földét, de nem találták meg; és bejárták Sáálim földét, de nem voltak ott; és bejárá Benjámin földét, de nem találták meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'Mikor pedig a Suf földére jutottak, monda Saul az ő szolgájának, a ki vele volt: Jer, térjünk vissza, nehogy atyám elvetve a szamarak gondját, miattunk aggódjék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, 'Az pedig monda néki: Ímé az Istennek embere most e városban van, és az az ember tiszteletben áll; mind az, a mit mond, beteljesedik. Most azért menjünk el oda, talán megmondja nékünk is a mi útunkat, hogy merre menjünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'És monda Saul az ő szolgájának: Elmehetünk oda, de mit vigyünk ez embernek? mert a kenyér elfogyott tarisznyánkból, és nincsen mit vigyünk ajándékba az Isten emberének; mi van nálunk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, 'A szolga pedig felele ismét Saulnak, és monda: Ímé van nálam egy ezüst siklusnak negyedrésze, oda adom ezt az Isten emberének, hogy megmondja nékünk a mi útunkat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, 'Régen Izráelben azt mondák, mikor valaki elment Istent megkérdezni: Jertek, menjünk el a nézőhöz; mert a kit most prófétának neveznek, régen nézőnek hívták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'És Saul monda az ő szolgájának: Helyesen beszélsz; jer, menjünk el. Elmenének azért a városba, hol az Istennek embere volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'A mint pedig a város felhágóján menének, leányokkal találkozának, a kik vizet meríteni jöttek ki, és mondának nékik: Itt van-é a néző?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, 'És azok felelének nékik, és mondának: Igen, amott van előtted, siess azért, mert ma jött a városba, mivel ma lesz a népnek véres áldozata ím e hegyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, 'A mint a városba mentek, azonnal megtaláljátok, mielőtt felmenne a hegyre, hogy egyék; mert a nép nem eszik addig, míg ő el nem jön, mivel a véres áldozatot ő áldja meg, és azután esznek a meghívottak. Azért most menjetek fel, mert épen most fogjátok őt megtalálni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'Felmenének azért a városba. És mikor a városban menének, ímé akkor jöve ki Sámuel velök szemben, hogy a hegyre felmenjen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'És az Úr kijelentette Sámuelnek füleibe, egy nappal az előtt, hogy Saul eljött, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, 'Holnap ilyenkor küldök hozzád egy embert a Benjámin földéről, és kend fel őt fejedelmül az én népem, Izráel felett, hogy megszabadítsa az én népemet a Filiszteusok kezéből; mert megtekintém az én népemet, mivel felhatott az ő kiáltása hozzám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'Mikor pedig Sámuel meglátta Sault, szóla néki az Úr: Ímé ez az az ember, a kiről szólottam néked, ő uralkodjék az én népem felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'Akkor Saul a kapu alatt Sámuelhez közeledék és monda: Ugyan mondd meg nékem, hol van itt a néző háza?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'Sámuel pedig felele Saulnak, és monda: Én vagyok az a néző; menj fel előttem a hegyre, és egyetek ma én velem, reggel pedig elbocsátlak téged, és megmondom néked mind azt, a mi szívedben van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, 'A szamarak miatt pedig, melyek tőled ezelőtt három nappal elvesztek, ne aggódjál, mert megtaláltattak. És kié leend mind az, a mi Izráelben becses? Avagy nem a tiéd és a te atyádnak egész házáé?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'És Saul felele, és monda: Avagy nem Benjáminita vagyok-é én, Izráelnek legkisebb törzséből való? És az én nemzetségem nem legkisebb-é Benjámin törzsének nemzetségei között? Miért szólasz tehát hozzám ilyen módon?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'Akkor Sámuel megfogta Sault és az ő szolgáját, és bevezette őket az étkező helyre; és nékik adta a főhelyet a meghívottak között, kik mintegy harminczan valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'És monda Sámuel a szakácsnak: Hozd elő azt a darabot, melyet odaadtam néked, és a melyről azt mondám, hogy tartsd magadnál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, 'Akkor a szakács felhozta a czombot és a mi rajta volt, és Saul elé tevé. És ő monda: Ímhol a megmaradt rész, vedd magad elé és egyél, mert erre az időre tétetett az el számodra, mikor mondám: Meghívtam a népet. Evék azért Saul azon a napon Sámuellel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, 'És miután lejöttek a hegyről a városba, a felházban beszélgetett Saullal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'És korán felkelének. Történt ugyanis, hogy hajnalhasadtakor kiálta Sámuel Saulnak a felházba, mondván: Kelj fel, hogy elbocsássalak téged. És felkelt Saul, és kimenének ketten, ő és Sámuel az utczára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, 'Mikor pedig lemenének a város végére, Sámuel monda Saulnak: Mondd meg a szolgának, hogy menjen előre előttünk – és előre ment -, te pedig most állj meg, hogy megmondjam néked az Istennek beszédét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'Akkor elővevé Sámuel az olajos szelenczét, és az ő fejére tölté, és megcsókolá őt, és monda: Nem úgy van-é, hogy fejedelemmé kent fel az Úr téged az ő öröksége felett?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, 'Mikor azért te most elmégy tőlem, találkozni fogsz két emberrel a Rákhel sírja mellett, Benjámin határában, Selsáhnál, a kik azt mondják néked: Megtalálták a szamarakat, melyeknek keresésére indultál vala; és ímé, a te atyád felhagyott már a szamarakkal, és miattatok aggódik, mondván: Mit tegyek a fiamért?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, 'És mikor onnan tovább mégy, és a Thábor tölgyfájához jutsz, három ember fog téged ott találni, kik Béthelbe mennek fel Istenhez; az egyik három gödölyét visz, a másik visz három egész kenyeret, és a harmadik visz egy tömlő bort.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'És azok békességesen köszöntenek téged, és két kenyeret adnak néked; te pedig vedd el azokat kezökből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, 'Azután eljutsz az Isten hegyére, hol a Filiszteusok előőrsei vannak. Mikor pedig bemégy oda a városba, a próféták seregével fogsz találkozni, kik a hegyről jőnek le, előttök lant, dob, síp és hárfa lesz, és ők magok prófétálnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, 'Akkor az Úrnak lelke reád fog szállani, és velök együtt prófétálni fogsz, és más emberré leszesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, 'Mikor pedig mind e jelek beteljesednek rajtad, tedd meg magadért mind azt, a mi csak kezed ügyébe esik, mert az Isten veled van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, 'Most azért menj le én előttem Gilgálba, és ímé én lemegyek te hozzád, hogy égőáldozatot áldozzam és hálaáldozatot hozzak. Hét napig várakozzál, míg hozzád megyek, és akkor tudtodra adom, hogy mit cselekedjél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'És lőn, a mint hátra fordult, hogy Sámueltől eltávozzék, elváltoztatá Isten az ő szívét, és azon a napon beteljesedének mind azok a jelek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'És mikor elmenének ama hegyre, ímé a prófétáknak serege vele szembe jöve, és az Istennek lelke ő reá szálla, és prófétála ő közöttök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, 'És lőn, hogy mind azok, kik ismerték őt annakelőtte, mikor látták, hogy ímé a prófétákkal együtt prófétál, monda a nép egymás közt: Mi lelte Kisnek fiát? Avagy Saul is a próféták közt van?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, 'És felele egy közülök, és monda: Ugyan kicsoda az ő atyjuk? Azért lőn példabeszéddé: Avagy Saul is a próféták közt van?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'És mikor elvégezé a prófétálást, felment a hegyre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'Saulnak nagybátyja pedig monda néki és a szolgájának: Hol jártatok? És ő monda: A szamarakat kerestük, de mivel sehol sem láttuk, Sámuelhez menénk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'Akkor monda Saulnak a nagybátyja: Ugyan mondd meg nékem, mit mondott néktek Sámuel?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'És monda Saul a nagybátyjának: Nyilván megmondotta nékünk, hogy a szamarakat megtalálták. De a mit Sámuel a királyságról mondott, nem beszélte el néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'És összehívta Sámuel a népet Mispába az Úrhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'És monda Izráel fiainak: Így szól az Úr, Izráelnek Istene: Én hoztam ki Izráelt Égyiptomból, és én szabadítottalak meg titeket az égyiptombeliek kezéből és mind amaz országok kezéből, melyek sanyargatának titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, 'Ti pedig most megvetettétek a ti Isteneteket, a ki megszabadított titeket minden bajaitokból és nyomorúságaitokból; és azt mondottátok néki: Adj királyt nékünk. Most azért álljatok az Úr elé a ti nemzetségeitek és ezreitek szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'És mikor előállatá Sámuel Izráelnek minden nemzetségét, kiválasztaték sors által a Benjámin nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'Akkor előállatá a Benjámin nemzetségét az ő házanépei szerint, és kiválasztaték a Mátri házanépe, azután kiválasztaték Saul, Kisnek fia; és keresék őt, de nem találták meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'Megkérdezték azért ismét az Urat: Vajjon eljön-é ide az az ember? És az Úr monda: Ímé ő a holmik közé rejtőzék el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, 'Akkor elfutának, és előhozták őt onnan. És mikor a nép közé álla, kimagaslék az egész nép közül vállától kezdve felfelé;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'És Sámuel monda az egész népnek: Látjátok-é, a kit választott az Úr? hogy nincsen hozzá hasonló az egész nép között! Akkor felkiálta az egész nép, és monda: Éljen a király!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, 'Sámuel pedig előadá a nép előtt a királyság jogát, és beírá egy könyvbe, és letevé az Úr elé. És elbocsátá Sámuel az egész népet, mindenkit a maga házához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'Azután Saul is elment haza Gibeába és vele ment a sokaság, a kiknek szívét Isten megindította vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, 'Némely kaján emberek azonban azt mondák: Mit segíthet ez rajtunk? és megvetették őt és ajándékot nem vivének néki. Ő pedig olyan volt, mintha semmit sem hallott volna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, 'És feljöve az Ammonita Náhás, és tábort jára Jábes Gileád ellen. A Jábesbeliek pedig mondának mindnyájan Náhásnak: Köss velünk szövetséget, és mi szolgálni fogunk néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'És monda nékik az Ammonita Náhás: Úgy szövetséget kötök veletek, ha kivágatom mindnyájatoknak jobb szemét, és tehetem ezt egész Izráelnek gyalázatára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'Jábes vénei pedig mondának néki: Engedj nékünk hét napot, hogy követeket küldjünk Izráelnek minden határára; és ha senki sem segít meg minket, akkor kimegyünk hozzád.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, 'Elmenének azért a követek Saulhoz Gibeába, és elmondták e beszédeket a nép füle hallatára. És felemelé az egész község az ő szavát, és sírának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, 'Saul pedig épen a mezőről jött vala a barmok után; és monda Saul: Mi történt a néppel, hogy sírnak? És elmondták néki a Jábesbeliek beszédeit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'És mikor hallotta e beszédeket, az Úrnak lelke Saulra szálla, és az ő haragja nagyon felgerjede.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, 'És vett egy pár ökröt, és feldarabolá azokat, és a követektől elküldé Izráelnek minden határára, mondván: A ki nem vonul Saul után és Sámuel után, annak ökreivel így cselekesznek. És az Úrnak félelme szálla a népre, és kivonulának mind egy szálig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'És megszámlálá őket Bézekben. És Izráel fiai háromszázezeren valának, a Júdabeliek pedig harminczezeren.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, 'És mondának a követeknek, kik oda menének: Így szóljatok a Jábes-Gileádbelieknek: Holnap, mikor a nap felmelegszik, megszabadultok. És elmenének a követek, és megmondák a Jábesbelieknek, és ők örvendezének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, 'Mondának azért a Jábesbeliek: Holnap kimegyünk hozzátok, hogy egészen úgy cselekedjetek velünk, a mint néktek jónak tetszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, 'Másodnapon pedig Saul a népet három seregre osztá, és kora hajnalban a táborra ütének, és verték Ammont mindaddig, míg a nap felmelegedék; a kik pedig megmaradtak, úgy szétszórattak, hogy kettő sem maradt közülök együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, 'Akkor a nép monda Sámuelnek: Kicsoda volt az, a ki mondá: Saul fog-é rajtunk uralkodni? Adjátok elő a férfiakat, hogy megöljük őket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'Saul azonban azt mondá: Senkit se öljetek meg a mai napon, mert ma szerzett szabadulást az Úr Izráelnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, 'Sámuel pedig monda a népnek: Jertek, menjünk el Gilgálba, és újítsuk meg ott a királyságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, 'Elméne azért az egész nép Gilgálba, és ott az Úr előtt Gilgálban királylyá tették Sault; és áldoztak ott hálaáldozatot az Úr előtt, és felette örvendezének ott, Saul és Izráelnek minden férfiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, 'És monda Sámuel az egész Izráelnek: Ímé meghallgattam szavaitokat mindenben, valamit nékem mondottatok, és királyt választottam néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, 'És most ímé a király előttetek jár. Én pedig megvénhedtem és megőszültem, és az én fiaim ímé ti köztetek vannak, és én is előttetek jártam ifjúságomtól fogva mind a mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, 'Itt vagyok, tegyetek bizonyságot ellenem az Úr előtt és az ő felkentje előtt: kinek vettem el az ökrét, és kinek vettem el a szamarát, és kit csaltam meg, kit sanyargattam, és kitől fogadtam el ajándékot, hogy a miatt szemet hunyjak? és visszaadom néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, 'Ők pedig felelének: Nem csaltál meg minket, nem sanyargattál minket, és senkitől semmit el nem fogadtál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'És ő monda nékik: Legyen bizonyság az Úr ti ellenetek, és bizonyság az ő felkentje ezen a napon, hogy semmit sem találtatok kezemben! Ők pedig mondának: Legyen bizonyságul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'És monda Sámuel a népnek: Igen, az Úr, a ki rendelte Mózest és Áront, és a ki kihozta atyáitokat Égyiptom földéről!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, 'Most azért álljatok elő, hadd perlekedjem veletek az Úr előtt az Úrnak minden jótéteményei felett, a melyeket cselekedett veletek és a ti atyáitokkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'Miután Jákób Égyiptomba ment vala, atyáitok az Úrhoz kiáltának, és az Úr elküldé Mózest és Áront, a kik kihozták atyáitokat Égyiptomból, és letelepíték erre a helyre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'De ők elfeledték az Urat, az ő Istenöket, azért adá őket Siserának, a Hásor serege vezérének kezébe, és a Filiszteusok kezébe és Moáb királyának kezébe, és azok harczolának ellenök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, 'Akkor kiáltának az Úrhoz, és mondák: Vétkeztünk, mert elhagytuk az Urat, és szolgáltunk a Baáloknak és Astarótnak; most azért szabadíts meg minket ellenségeinknek kezéből, hogy néked szolgáljunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, 'És elküldé az Úr Jerubbaált és Bédánt és Jeftét és Sámuelt, és megszabadíta titeket mindenfelől ellenségeitek kezéből, és biztonságban laktatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, 'Mikor pedig láttátok, hogy Náhás, az Ammon fiainak királya ellenetek jöve, azt mondátok nékem: Semmiképen nem, hanem király uralkodjék felettünk, holott csak a ti Istenetek, az Úr a ti királyotok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, 'Most azért, ímhol a király, a kit választottatok, a kit kértetek. Ímé, az Úr királyt adott néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, 'Hogyha az Urat félitek, és néki szolgáltok; szavára hallgattok és az Úr szája ellen engedetlenek nem lesztek; és mind ti, mind pedig a király, a ki felettetek uralkodik, az Urat, a ti Isteneteket követitek: megtartattok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'Ha pedig az Úr szavára nem hallgattok, és az Úr szava ellen engedetlenek lesztek: az Úrnak keze ellenetek leend, miként a ti atyáitok ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, 'Most is azért álljatok meg, és lássátok meg azt a nagy dolgot, a melyet az Úr visz véghez szemeitek előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, 'Avagy nem búzaaratás van-é most? Kiáltani fogok az Úrhoz, és ő mennydörgést és esőt ád, hogy megtudjátok és meglássátok, mily nagy a ti gonoszságtok, melyet cselekedtetek az Úr szemei előtt, mikor királyt kértetek magatoknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'Kiálta azért Sámuel az Úrhoz, és az Úr mennydörgést és esőt adott azon a napon. És az egész nép nagyon megrettene az Úrtól és Sámueltől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, 'És monda az egész nép Sámuelnek: Könyörögj szolgáidért az Úrhoz, a te Istenedhez, hogy meg ne haljunk, mert minden bűneinket csak öregbítettük azzal a bűnnel, hogy királyt kértünk magunknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'És monda Sámuel a népnek: Ne féljetek! Ha már mind e gonoszságot véghez vittétek, most ne távozzatok el az Úrtól, hanem az Úrnak szolgáljatok teljes szívetekből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, 'Ne térjetek el a hiábavalóságok után, a melyek nem használnak, meg sem szabadíthatnak, mert hiábavalóságok azok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'Mert nem hagyja el az Úr az ő népét, az ő nagy nevéért; mert tetszett az Úrnak, hogy titeket a maga népévé válaszszon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'Sőt tőlem is távol legyen, hogy az Úr ellen vétkezzem és felhagyjak az érettetek való könyörgéssel; hanem inkább tanítani foglak titeket a jó és igaz útra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, 'Csak féljétek az Urat, és szolgáljatok néki hűségesen, teljes szívetekből; mert látjátok; mily nagy dolgot cselekedett veletek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'Ha pedig folytonos rosszat cselekesztek: mind ti, mind királyotok elvesztek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, 'Saul harmincz éves volt, mikor királylyá lett és mikor uralkodék az Izráel felett két esztendeig,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, 'Választa Saul magának az Izráel közül háromezer embert, és kétezer Saullal vala Mikmásban és Béthel hegységén, ezer pedig Jonathánnal volt Gibeában, a Benjámin városában; a népnek többi részét pedig elbocsátá, kit-kit a maga hajlékába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, 'És Jonathán megveré a Filiszteusoknak előőrsét, mely Gébában vala, és meghallották ezt a Filiszteusok; Saul pedig megfúvatta a trombitát az egész országban, mondván: Hallják meg a zsidók!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'És meghallotta egész Izráel, hogy azt mondák: Megverte Saul a Filiszteusok előőrsét, és gyűlöletessé vált Izráel a Filiszteusok előtt. A nép pedig egybegyűle Saul mellé Gilgálba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'Összegyűlének a Filiszteusok is, hogy harczoljanak Izráel ellen; harminczezer szekér és hatezer lovas volt, a nép pedig oly sok volt, mint a tenger partján lévő föveny; és feljövének és tábort ütének Mikmásnál, Béth-Aventől keletre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, 'Mikor pedig Izráel férfiai látták, hogy bajban vannak – mert a nép szorongattatott -: elrejtőzék a nép a barlangokba, a bokrok és kősziklák közé, sziklahasadékokba és vermekbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'És a zsidók közül némelyek általmenének a Jordánon, Gád és Gileád földére. Saul pedig még Gilgálban volt, és az egész nép, mely mellette vala, rettegett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'És várakozék hét napig, a Sámuel által meghagyott ideig, de Sámuel nem jött el Gilgálba, a nép pedig elszélede mellőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'Akkor monda Saul: Hozzátok ide az égőáldozatot és a hálaáldozatokat. És égőáldozatot tőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, 'És mikor elvégezte az égőáldozatot; ímé megérkezék Sámuel, és Saul eleibe ment, hogy köszöntse őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'És monda Sámuel: Mit cselekedtél?! Saul pedig felele: Mikor láttam, hogy a nép elszélede mellőlem, és te nem jöttél el a meghagyott időre, a Filiszteusok pedig összegyűlének már Mikmásban,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, 'Azt mondám: Mindjárt reám törnek a Filiszteusok Gilgálban, és én az Úrnak színe előtt még nem imádkozám; bátorságot vevék azért magamnak és megáldozám az égőáldozatot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'Akkor monda Sámuel Saulnak: Esztelenül cselekedtél; nem tartottad meg az Úrnak, a te Istenednek parancsolatját, melyet parancsolt néked, pedig most mindörökre megerősítette volna az Úr a te királyságodat Izráel felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, 'Most azonban a te királyságod nem lesz állandó. Keresett az Úr magának szíve szerint való embert, a kit az ő népe fölé fejedelmül rendelt, mert te nem tartottad meg, a mit az Úr parancsolt néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'Felkele ezután Sámuel, és elment Gilgálból Benjámin városába, Gibeába. És Saul megszámlálta a népet, mely körülötte található volt, mintegy hatszáz embert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'Saul pedig és az ő fia, Jonathán és a nép, mely körülöttök található vala, Benjámin városában, Gébában tartózkodának, és a Filiszteusok Mikmásnál táborozának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'Akkor a Filiszteusok táborából egy dúló sereg vált ki három csapatban; az egyik csapat az Ofra felé vivő útra fordult Suál földének;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, 'A másik csapat a Bethoron felé vivő útra fordula; a harmadik csapat pedig a határ felé vivő útra fordult, mely a Sebóim völgyén át a pusztáig terjed.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, 'És kovácsot egész Izráel földén nem lehetett találni, mert a Filiszteusok azt mondák: Ne csinálhassanak a zsidók szablyát vagy dárdát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, 'És egész Izráelnek a Filiszteusokhoz kellett lemenni, hogy megélesítse ki-ki a maga kapáját, szántóvasát, fejszéjét és sarlóját,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, '(Minthogy megtompulának a kapák, szántóvasak, a háromágú villa és a fejszék) és hogy az ösztökét kiegyenesítsék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, 'Azért az ütközet napján az egész népnél, mely Saullal és Jonathánnal vala, sem szablya, sem dárda nem találtaték, hanem csak Saulnál és az ő fiánál Jonathánnál volt található.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, 'És a Filiszteusok előőrse kijöve Mikmás szorosához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, 'És történt egy napon, hogy Jonathán, a Saul fia azt mondá szolgájának, a ki az ő fegyverét hordozza vala: Jer, menjünk át a Filiszteusok előőrséhez, mely amott túl van; de atyjának nem mondá meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'Saul pedig Gibea határában, a gránátfa alatt tartózkodék, mely Migron nevű mezőn van; és a nép, mely vele volt, mintegy hatszáz ember vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, 'És Ahija is, ki Silóban az efódot viseli, fia Akhitobnak, az Ikábód testvérének, Fineás fiának, a ki az Úr papjának, Élinek fia vala. És a nép nem tudta, hogy Jonathán eltávozék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, 'A szorosok között pedig, melyeken keresztül akara menni Jonathán a Filiszteusok előőrséhez, volt egy hegyes kőszikla innen, és volt egy hegyes kőszikla túlfelől. Az egyiknek Boczécz, a másiknak pedig Sené volt a neve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, 'Az egyik sziklacsúcs északra volt, Mikmás átellenében, és a másik délre, Géba átellenében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'És monda Jonathán a szolgának, a ki az ő fegyverét hordozá: Jer, menjünk át ezeknek a körülmetéletleneknek előőrséhez, talán tenni fog az Úr érettünk valamit, mert az Úr előtt nincs akadály, hogy sok vagy pedig kevés által szerezzen szabadulást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, 'És fegyverhordozója felele néki: Tégy mindent a te szíved szerint; indulj néki, ímé én veled leszek kívánságod szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'Jonathán pedig monda: Nosza menjünk fel ez emberekhez, és mutassuk meg magunkat nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'Ha azt mondják nékünk: Várjatok meg, míg oda érkezünk ti hozzátok, akkor álljunk meg helyünkön, és ne menjünk fel hozzájok;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'Ha pedig azt mondják: Jertek fel mihozzánk, akkor menjünk fel, mert az Úr kezünkbe adta őket. És ez legyen nékünk a jel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, 'Mikor pedig megmutatták magokat mind ketten a Filiszteusok előőrsének, mondának a Filiszteusok: Ímé a zsidók kijődögélnek a barlangokból, a hova rejtőzének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'És szólának némelyek az előőrs emberei közül Jonathánnak és az ő fegyverhordozójának, és mondák: Jertek fel mi hozzánk, és valamit mondunk néktek. Akkor monda Jonathán az ő fegyverhordozójának: Jőjj fel utánam, mert az Úr Izráel kezébe adta őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'És felmászott Jonathán négykézláb, és utána az ő fegyverhordozója. És hullanak vala Jonathán előtt, és fegyverhordozója is öldököl utána.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'És az első ütközet, melyben Jonathán és fegyverhordozója mintegy húsz embert ölének meg, egy hold földön egy fél barázda hosszányin volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, 'És félelem támada a táborban, a mezőn és az egész nép között; az előőrs és a dúló sereg – azok is megrémülének – és a föld megrendüle; és Istentől való rettegés lőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'És megláták a Saul őrei Benjámin városában, Gibeában, hogy a sokaság elszéledett és ide-oda elszóratott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, 'Akkor monda Saul a népnek, mely vele volt: Nosza vegyétek számba a népet, és vizsgáljátok meg, ki ment el mi közülünk; és a mikor számba vették, ímé Jonathán és az ő fegyverhordozója nem valának ott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'És monda Saul Ahijának: Hozd elő az Isten ládáját; mert az Isten ládája akkor Izráel fiainál vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'És történt, hogy a míg Saul a pappal beszéle, a Filiszteusok táborában mind nagyobb lőn a zsibongás. Monda azért Saul a papnak: Hagyd abba, a mit kezdettél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'És felkiálta Saul és a nép, mely vele volt, és elmenének az ütközetre. Ott pedig egyik a másik ellen harczola, és igen nagy zűrzavar lőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'És azok a zsidók is, kik, mint azelőtt is, a Filiszteusokkal valának, s velök együtt feljövének a táborba és a körül valának, azok is Izráel népéhez csatlakozának, mely Saul és Jonathán mellett vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, 'És Izráelnek mindazon férfiai, kik elrejtőzének Efraim hegységében, mikor meghallották, hogy a Filiszteusok menekültek, azok is üldözni kezdék őket a harczban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, 'És megsegíté az Úr azon a napon Izráelt. És a harcz Béth-Avenen túl terjede.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'És Izráel népe igen elepedett vala azon a napon, mert Saul esküvel kényszeríté a népet, mondván: Átkozott az, a ki kenyeret eszik estvéig, míg bosszút állok ellenségeimen, azért az egész nép semmit sem evék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, 'És az egész föld népe eljuta az erdőbe, hol méz vala a föld szinén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, 'Mikor pedig a nép beméne az erdőbe, jóllehet folyt a méz, mindazáltal senki sem érteté kezét szájához, mert félt a nép az eskü miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, 'Jonathán azonban nem hallotta vala, hogy atyja megesketé a népet, és kinyújtá a vessző végét, mely kezében vala, és bemártá azt a lépesmézbe, és kezét szájához vivé; és felvidulának az ő szemei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, 'Szóla pedig valaki a nép közül, és mondá: Atyád ünnepélyesen megesketé a népet, mondván: Átkozott az, a ki csak kenyeret is eszik ma, és e miatt a nép kimerüle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'És monda Jonathán: Atyám bajba vitte az országot; lássátok mennyire felvidulának szemeim, hogy ízlelék egy keveset ebből a mézből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'Hátha még a nép jól evett volna ma ellenségeinek zsákmányából, melyet talált! Vajjon nem nagyobb lett volna-é akkor a Filiszteusok veresége?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'És megverék azon a napon a Filiszteusokat Mikmástól Ajálonig. És a nép nagyon kimerüle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, 'Akkor a nép a prédának esék, és fogának juhot, ökröt és borjúkat, és megölék a földön, és megevé a nép vérestől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, 'Megjelenték azért Saulnak, és mondának: Ímé a nép vétkezik az Úr ellen, mert vérrel elegy eszik. Ő pedig monda: Hűtlenül cselekedtetek, gördítsetek azért most hozzám egy nagy követ.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'Monda továbbá Saul: Menjetek el mindenfelé a nép között, és mondjátok meg nékik, hogy mindenki a maga ökrét és mindenki a maga juhát hozza én hozzám, és itt öljétek meg és egyétek meg, és nem fogtok vétkezni az Úr ellen, vérrel elegy evén. Akkor elhozta az egész nép, kézzel fogván ki-ki a maga ökrét azon éjjel, és ott megölék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, 'Saul pedig oltárt épített az Úrnak; azt az oltárt építé először az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, 'És monda Saul: Menjünk le ez éjjel a Filiszteusok után, és foszszuk ki őket virradatig, és senkit se hagyjunk meg közülök. Azok pedig mondának: A mint néked tetszik, úgy cselekedjél mindent. De a pap azt mondá: Járuljunk ide az Istenhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'És megkérdezé Saul az Istent: Lemenjek-é a Filiszteusok után? Izráelnek kezébe adod-é őket? De ő nem felelt néki azon a napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, 'Monda azért Saul: Jertek ide mindnyájan, a népnek oszlopai, hogy megtudjátok és meglássátok, kiben volt ez a bűn ma?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'Mert él az Úr, a ki Izráelt oltalmazza, hogy ha fiamban, Jonathánban volna is, meg kell halnia; és az egész nép közül senki sem felele néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'És monda egész Izráelnek: Ti legyetek az egyik oldalon, én pedig és az én fiam, Jonathán legyünk a másik oldalon. És válaszola a nép Saulnak: A mint néked tetszik, úgy cselekedjél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'Akkor szóla Saul az Úrnak, Izráel Istenének: Szolgáltass igazságot! És kiválasztaték Jonathán és Saul, a nép pedig megmeneküle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'És monda Saul: Vessetek sorsot közöttem és fiam, Jonathán között. És kiválasztaték Jonathán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'Akkor monda Saul Jonathánnak: Mondd meg nékem, mit cselekedtél? Jonathán pedig elbeszélte néki, és monda: A pálcza végével, mely kezembe vala, ízlelék egy keveset a mézből; itt vagyok, haljak meg!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'És Saul monda: Úgy cselekedjék az Úr most és ezután is, hogy meg kell halnod Jonathán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, 'A nép azonban monda Saulnak: Jonathán haljon-é meg, a ki ezt a nagy szabadulást szerezte Izráelben? Távol legyen! Él az Úr, hogy egyetlen hajszála sem esik le fejéről a földre, mert Istennek segedelmével cselekedte ezt ma. Megváltá azért a nép Jonathánt, és nem hala meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'Akkor Saul megtére a Filiszteusok üldözéséből; a Filiszteusok pedig az ő helyökre haza menének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'Miután tehát Saul átvette a királyságot Izráel felett, hadakozék minden ellenségivel mindenfelé: Moáb ellen és Ammon fiai ellen és Edom ellen és a Czobeusok királyai ellen és a Filiszteusok ellen; és mindenütt, a hol megfordula, keményen cselekedék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'És sereget gyűjtvén, megverte Amáleket, és megszabadítá Izráelt fosztogatóinak kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'Valának pedig Saul fiai: Jonathán, Jisvi és Málkisua; és két leányának neve: az idősebbiknek Méráb, és a kisebbiknek neve Mikál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'És Saul feleségét Akhinóámnak hívták, a ki Akhimaás leánya volt. Seregének vezetőjét pedig Abnernek hívták, a ki Saul nagybátyjának, Nérnek volt a fia;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, 'Mert Kis, a Saul atyja és Nér, az Abner atyja, Abiel fiai valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'A Filiszteusok elleni háború pedig igen heves volt Saulnak egész életében; azért, a hol csak látott Saul egy-egy erős vagy egy-egy bátor férfit, azt magához fogadta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, 'És monda Sámuel Saulnak: Engem küldött el az Úr, hogy királylyá kenjelek fel téged az ő népe, az Izráel felett; most azért figyelj az Úr beszédének szavára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, 'Így szól a Seregek Ura: Megemlékeztem arról, a mit cselekedett Amálek Izráellel, hogy útját állta néki, mikor feljöve Égyiptomból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, 'Most azért menj el és verd meg Amáleket, és pusztítsátok el mindenét; és ne kedvezz néki, hanem öld meg mind a férfit, mind az asszonyt; mind a gyermeket, mind a csecsemőt; mind az ökröt, mind a juhot; mind a tevét, mind a szamarat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'És összehívá Saul a népet, és megszámlálá őket Thélaimban, kétszázezer gyalogost, és Júdából tízezer embert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'És elméne Saul Amálek városáig, és megütközék ott egy völgyben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'És monda Saul a Kéneusnak: Menjetek, távozzatok el, menjetek ki az Amálekiták közül, hogy velök együtt téged is el ne veszesselek, mert te irgalmasságot cselekedtél Izráel minden fiaival, mikor Égyiptomból feljövének. És eltávozék Kéneus az Amálekiták közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'Saul pedig megveré Amáleket Havilától fogva egészen addig, a merre Súrba mennek, mely Égyiptom átellenében van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'És Agágot, az Amálekiták királyát elfogta élve, a népet pedig mind kardélre hányatá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, 'Saul és a nép azonban megkímélte Agágot és a juhoknak, barmoknak és másodszülötteknek javát; a bárányokat és mindazt, a mi jó vala, nem akarták azokat elpusztítani, hanem a mi megvetett és értéktelen dolog volt, mindazt elpusztíták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, 'Akkor szóla az Úr Sámuelnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, 'Megbántam, hogy Sault királylyá tettem, mert eltávozott tőlem, és beszédeimet nem tartotta meg. Sámuel pedig felháborodék és kiálta az Úrhoz egész éjszaka.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'És korán felkele Sámuel, hogy találkozzék Saullal reggel; és hírül adák Sámuelnek, ezt mondván: Saul Kármelbe ment, és ímé emlékoszlopot állított magának; azután megfordula, és tovább ment és lement Gilgálba,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'És a mint Sámuel Saulhoz érkezék, monda néki Saul: Áldott vagy te az Úrtól! Én végrehajtám az Úrnak parancsolatját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'Sámuel azonban monda: Micsoda az a juhbégetés, mely füleimbe hat és az az ökörbőgés, melyet hallok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'És monda Saul: Az Amálekitáktól hozták azokat, mert a nép megkímélte a juhoknak és ökröknek javát, hogy megáldozza az Úrnak, a te Istenednek; a többit pedig elpusztítottuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'Akkor monda Sámuel Saulnak: Engedd meg, hogy megmondjam néked, a mit az Úr mondott nékem ez éjjel. Ő pedig monda néki: Beszélj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'Monda azért Sámuel: Nemde kicsiny valál te a magad szemei előtt is, mindazáltal Izráel törzseinek fejévé lettél, és az Úr királylyá kent fel téged Izráel felett?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'És elkülde az Úr téged az úton, és azt mondá: Menj el, és pusztítsd el az Amálekitákat, kik vétkezének; és hadakozzál ellenök, míg megsemmisíted őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, 'Miért nem hallgattál az Úrnak szavára, és miért estél néki a prédának, és cselekedted azt, a mi bűnös az Úr szemei előtt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'És felele Saul Sámuelnek: Én bizonyára hallgattam az Úr szavára, és azon az úton jártam, a melyre engem az Úr elküldött; és elhoztam Agágot, az Amálekiták királyát, és az Amálekitákat elpusztítottam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'A nép azonban elvette a prédából a megsemmisítésre rendelt juhoknak és ökröknek javát, hogy megáldozza az Úrnak, a te Istenednek Gilgálban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'Sámuel pedig monda: Vajjon kedvesebb-é az Úr előtt az égő- és véres áldozat, mint az Úr szava iránt való engedelmesség? Ímé, jobb az engedelmesség a véres áldozatnál és a szófogadás a kosok kövérénél!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, 'Mert, mint a varázslásnak bűne, olyan az engedetlenség; és bálványozás és bálványimádás az ellenszegülés. Mivel te megvetetted az Úrnak beszédét, ő is megvetett téged, hogy ne légy király.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'Akkor monda Saul Sámuelnek: Vétkeztem, mert megszegtem az Úrnak szavát és a te beszédedet; de mivel féltem a néptől, azért hallgattam szavokra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'Most azért bocsásd meg az én vétkemet, és térj vissza velem, hogy könyörögjek az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'Sámuel pedig monda Saulnak: Nem térek vissza veled, mert megvetetted az Úrnak beszédét, és az Úr is megvetett téged, hogy ne légy király Izráel felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'És mikor megfordula Sámuel, hogy elmenjen, megragadta felső ruhájának szárnyát, és leszakada.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'Akkor monda néki Sámuel: Elszakítá tőled az Úr a mai napon Izráelnek királyságát, és adta azt felebarátodnak, a ki jobb náladnál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'Izráelnek erőssége pedig nem hazudik, és semmit meg nem bán, mert nem ember ő, hogy valamit megbánjon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'És ő monda: Vétkeztem, mindazáltal becsülj meg engem népemnek vénei előtt és Izráel előtt, és velem térj vissza, hogy könyörögjek az Úrnak, a te Istenednek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'Visszatére azért Sámuel Saullal, és könyörgött Saul az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, 'Sámuel pedig monda: Hozzátok ide előmbe Agágot, Amálek királyát. És elméne Agág kényesen ő hozzá, és monda Agág: Bizonyára eltávozék a halál keserűsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'És monda Sámuel: Miként a te kardod asszonyokat tett gyermektelenekké, úgy legyen gyermektelenné minden asszonyok felett a te anyád! És darabokra vagdalá Sámuel Agágot az Úr előtt Gilgálban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'Ezután Sámuel elment Rámába, Saul pedig felment az ő házához Gibeába, Saul városába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, 'És Sámuel nem látogatá meg többé Sault egész halálának idejéig; de bánkódék Sámuel Saul miatt. Az Úr pedig megbánta, hogy királylyá tette Sault Izráel felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, 'És monda az Úr Sámuelnek: Ugyan meddig bánkódol még Saul miatt, holott én megvetettem őt, hogy ne uralkodjék Izráel felett? Töltsd meg a te szarudat olajjal, és eredj el; én elküldelek téged a Bethlehemben lakó Isaihoz, mert fiai közül választottam magamnak királyt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'Sámuel pedig monda: Hogyan menjek el!? Ha meghallja Saul, megöl engemet. És monda az Úr: Vígy magaddal egy üszőt, és azt mondjad: Azért jöttem, hogy az Úrnak áldozzam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'És hívd meg Isait az áldozatra, és én tudtodra adom, hogy mit cselekedjél, és kend fel számomra azt, a kit mondándok néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'És Sámuel megcselekedé, a mit az Úr mondott néki, és elment Bethlehembe. A város vénei pedig megijedének, és eleibe menvén, mondának: Békességes-é a te jöveteled?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'Ő pedig felele: Békességes; azért jöttem, hogy áldozzam az Úrnak. Szenteljétek meg azért magatokat, és jertek el velem az áldozatra. Isait és az ő fiait pedig megszentelé, és elhívá őket az áldozatra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'Mikor pedig bemenének, meglátta Eliábot, és gondolá: Bizony az Úr előtt van az ő felkentje!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'Az Úr azonban monda Sámuelnek: Ne nézd az ő külsőjét, se termetének nagyságát, mert megvetettem őt. Mert az Úr nem azt nézi, a mit az ember; mert az ember azt nézi, a mi szeme előtt van, de az Úr azt nézi, mi a szívben van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'Szólítá azért Isai Abinádábot, és elvezeté őt Sámuel előtt; ő pedig monda: Ez sem az, kit az Úr választa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'Elvezeté azután előtte Isai Sammát; ő pedig monda: Ez sem az, a kit az Úr választa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'És így elvezeté Isai Sámuel előtt mind a hét fiát; Sámuel pedig mondá Isainak: Nem ezek közül választott az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, 'Akkor monda Sámuel Isainak: Mind itt vannak-é már az ifjak? Ő pedig felele: Hátra van még a kisebbik, és ímé ő a juhokat őrzi. És monda Sámuel Isainak: Küldj el, és hozasd ide őt, mert addig nem fogunk leülni, míg ő ide nem jön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, 'Elkülde azért, és elhozatá őt. (Ő pedig piros vala, szép szemű és kedves tekintetű.) És monda az Úr: Kelj fel és kend fel, mert ő az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'Vevé azért Sámuel, az olajos szarut, és felkené őt testvérei között. És attól a naptól fogva az Úrnak lelke Dávidra szálla, és azután is. Felkele azután Sámuel és elméne Rámába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'És az Úrnak lelke eltávozék Saultól, és gonosz lélek kezdé gyötörni őt, mely az Úrtól küldetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'És mondának Saul szolgái néki: Ímé most az Istentől küldött gonosz lélek gyötör téged!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'Parancsoljon azért a mi urunk szolgáidnak, kik körülötted vannak, hogy keressenek olyan embert, a ki tudja a hárfát pengetni, és mikor az Istentől küldött gonosz lélek reád jön, pengesse kezével, hogy te megkönnyebbülj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'És monda Saul az ő szolgáinak: Keressetek tehát számomra olyan embert, a ki jól tud hárfázni, és hozzátok el hozzám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, 'Akkor felele egy a szolgák közül, és monda: Ímé én láttam a Bethlehemben lakó Isainak egyik fiát, a ki tud hárfázni, a ki erős vitéz és hadakozó férfiú, értelmes és szép ember, és az Úr vele van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'Követeket külde azért Saul Isaihoz, és monda: Küldd hozzám a fiadat, Dávidot, ki a juhok mellett van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'Isai pedig vőn egy szamarat, egy kenyeret, egy tömlő bort és egy kecskegödölyét, és elküldé Saulnak az ő fiától, Dávidtól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'Mikor pedig Dávid elméne Saulhoz és megálla előtte, az igen megszerette őt, és fegyverhordozója lőn néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'És elkülde Saul Isaihoz, mondván: Maradjon Dávid én nálam, mert igen megkedveltem őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, 'És lőn, hogy a mikor Istennek lelke Saulon vala, vette Dávid a hárfát és kezével pengeté; Saul pedig megkönnyebbüle és jobban lőn, és a gonosz lélek eltávozék tőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, 'És összegyűjték a Filiszteusok seregeiket a harczra, és összegyűlének Sokónál, mely Júdában van, és táborozának Sokó és Azéka között, Efes-Dammimnál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'Saul és az Izráeliták pedig összegyűlének, és tábort ütének az Elah völgyében; és csatarendbe állának a Filiszteusok ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'És a Filiszteusok a hegyen állottak innen, az Izráeliták pedig a hegyen állottak túlfelől, úgy hogy a völgy közöttük vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, 'És kijöve a Filiszteusok táborából egy bajnok férfiú, a kit Góliáthnak hívtak, Gáth városából való, kinek magassága hat sing és egy arasz vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, 'Fején rézsisak vala és pikkelyes pánczélba volt öltözve; a pánczél súlya pedig ötezer rézsiklusnyi vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'Lábán réz lábpánczél és vállain rézpaizs volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, 'És dárdájának nyele olyan volt, mint a takácsok zugolyfája, dárdájának hegye pedig hatszáz siklusnyi vasból volt; és előtte megy vala, ki a paizst hordozza vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'És megállván, kiálta Izráel csatarendjeinek, és monda nékik: Miért jöttetek ki, hogy harczra készüljetek? Avagy nem Filiszteus vagyok-é én és ti Saul szolgái? Válaszszatok azért magatok közül egy embert, és jőjjön le hozzám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, 'Ha azután meg bír velem vívni és engem legyőz: akkor mi a ti szolgáitok leszünk; ha pedig én győzöm le őt és megölöm: akkor ti legyetek a mi szolgáink, hogy szolgáljatok nékünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'Monda továbbá a Filiszteus: Én gyalázattal illetém a mai napon Izráel seregét, állítsatok azért ki ellenem egy embert, hogy megvívjunk egymással.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'Mikor pedig meghallotta Saul és az egész Izráel a Filiszteusnak ezt a beszédét, megrettenének és igen félnek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, 'És Dávid, Júda városából, Bethlehemből való amaz Efratita embernek volt a fia, a kit Isainak hívtak, a kinek nyolcz fia volt, és e férfiú a Saul idejében vén ember vala, emberek közt korban előhaladt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, 'És Isainak három idősebbik fia Saullal elment a háborúba. Az ő három fiának pedig, a kik a háborúba menének, ezek valának neveik: az idősebbik Eliáb, a második Abinádáb és a harmadik Samma.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, 'És Dávid volt a legkisebbik. Mikor pedig a három idősebb elment Saul után:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, 'Dávid elméne és visszatére Saultól, hogy atyjának juhait őrizze Bethlehemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, 'A Filiszteus pedig előjön vala reggel és estve, és kiáll vala negyven napon át.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, 'És monda Isai az ő fiának, Dávidnak: Vedd testvéreid számára ezt az efa pergelt búzát és ezt a tíz kenyeret, és sietve vidd el a táborba testvéreidhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, 'Ezt a tíz sajtot pedig vidd el az ezredesnek, és látogasd meg testvéreidet, hogy jól vannak-é, és hozz tőlük jelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, 'Saul pedig azokkal együtt és az egész Izráel az Elah völgyében valának, hogy harczolnának a Filiszteusok ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, 'Felkele azért Dávid korán reggel, és a nyájat egy pásztorra bízván, felvette a terhet és elment, a mint meghagyta néki Isai; és eljutott a tábor kerítéséhez; a sereg pedig, mely kivonult csatarendben, hadi zajt támasztott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, 'És csatarendbe állának Izráel és a Filiszteusok, csatarend csatarend ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, 'Akkor Dávid rábízta a holmit arra, a ki a hadi szerszámokat őrzi, és elfuta a harcztérre és odaérve, kérdezősködék testvéreinek állapota felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, 'És míg ő beszélt velök, ímé a bajnok férfi, a Góliáth nevű Filiszteus, a ki Gáthból való volt, előjöve a Filiszteusok csatarendei közül, és most is hasonlóképen beszél vala; és meghallá ezt Dávid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, 'Az Izráeliták pedig, mikor látták azt a férfit, mindnyájan elfutának előle, és igen félnek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, 'És mondának az Izráeliták: Láttátok-é azt a férfit, a ki feljöve? Mert azért jött ki, hogy gyalázattal illesse Izráelt. Ha valaki megölné őt, nagy gazdagsággal ajándékozná meg a király, leányát is néki adná, és atyjának házát szabaddá tenné Izráelben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, 'És szóla Dávid azoknak az embereknek, a kik ott állának vele, mondván: Mi történik azzal, a ki megöli ezt a Filiszteust, és elveszi a gyalázatot Izráelről? Mert kicsoda ez a körülmetéletlen Filiszteus, hogy gyalázattal illeti az élő Istennek seregét?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, 'A nép pedig e beszéd szerint felele néki, mondván: Ez történik azzal az emberrel, a ki megöli őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, 'És meghallá Eliáb az ő nagyobbik testvére, hogy az emberekkel beszéle; és nagyon megharaguvék Eliáb Dávidra, és monda: Miért jöttél ide, és kire bíztad azt a néhány juhot, a mely a pusztában van? Ismerem vakmerőségedet és szívednek álnokságát, hogy csak azért jöttél ide, hogy megnézd az ütközetet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, 'Dávid pedig felele: Ugyan mit cselekedtem én most? hiszen csak szóbeszéd volt ez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, 'És elfordula tőle egy másikhoz, és ugyan úgy szóla, mint korábban, és a nép is az előbbi beszéd szerint válaszola néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, 'És mikor meghallották azokat a szavakat, a melyeket Dávid szóla, megmondák Saulnak, ki magához hívatá őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, 'És monda Dávid Saulnak: Senki se csüggedjen el e miatt; elmegy a te szolgád és megvív ezzel a Filiszteussal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, 'Saul pedig monda Dávidnak: Nem mehetsz te e Filiszteus ellen, hogy vele megvívj, mert te gyermek vagy, ő pedig ifjúságától fogva hadakozó férfi vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, 'És felele Dávid Saulnak: Pásztor volt a te szolgád, atyjának juhai mellett; és ha eljött az oroszlán és a medve, és elragadott egy bárányt a nyáj közül:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, 'Elmentem utána és levágtam, és kiszabadítám szájából; ha pedig ellenem támadott: megragadtam szakálánál fogva, és levágtam és megöltem őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, 'A te szolgád mind az oroszlánt, mind a medvét megölte: Úgy lesz azért e körülmetéletlen Filiszteus is, mint azok közül egy, mert gyalázattal illeté az élő Istennek seregét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, 'És monda Dávid: Az Úr, a ki megszabadított engem az oroszlánnak és a medvének kezéből, meg fog szabadítani engem e Filiszteusnak kezéből is. Akkor monda Saul Dávidnak: Eredj el, és az Úr legyen veled!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, 'És felöltözteté Saul Dávidot a maga harczi ruhájába; rézsisakot tett a fejére, és felöltözteté őt pánczélba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, 'Akkor Dávid felköté kardját harczi ruhája fölé, és járni akart, mert még nem próbálta. És monda Dávid Saulnak: Nem bírok ezekben járni, mert még nem próbáltam; és leveté azokat Dávid magáról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, 'És kezébe vette botját, és kiválasztván magának a patakból öt síma kövecskét, eltevé azokat pásztori szerszámába, mely vele volt, tudniillik tarisznyájába, és parittyájával kezében közeledék a Filiszteushoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, 'Akkor elindult a Filiszteus is, és Dávidhoz közeledék, az az ember pedig, a ki a paizsát hordozza, előtte vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, 'Mikor pedig oda tekinte a Filiszteus, és meglátta Dávidot, megvetette őt, mert ifjú volt és piros, egyszersmind szép tekintetű.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, 'És monda a Filiszteus Dávidnak: Eb vagyok-é én, hogy te bottal jössz reám? És szidalmazá a Filiszteus Dávidot Istenével együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, 'Monda továbbá a Filiszteus Dávidnak: Jőjj ide hozzám, hogy testedet az égi madaraknak és a mezei vadaknak adjam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, 'Dávid pedig monda a Filiszteusnak: Te karddal, dárdával és paizszsal jössz ellenem, én pedig a Seregek Urának, Izráel seregei Istenének nevében megyek ellened, a kit te gyalázattal illetél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, 'A mai napon kezembe ad téged az Úr, és megöllek téged, és fejedet levágom rólad. A Filiszteusok seregének tetemét pedig az égi madaraknak és a mezei vadaknak fogom adni a mai napon, hogy tudja meg az egész föld, hogy van Izráelnek Istene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, 'És tudja meg ez az egész sokaság, hogy nem kard által és nem dárda által tart meg az Úr, mert az Úré a had, és ő titeket kezünkbe fog adni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, 'És mikor a Filiszteus felkészült, és elindult, és Dávid felé közeledék: Dávid is sietett és futott a viadalra a Filiszteus elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, 'És Dávid benyúlt kezével a tarisznyába és kivett onnan egy követ, és elhajítván, homlokán találta a Filiszteust, úgy, hogy a kő homlokába mélyede, és arczczal a földre esék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, 'Így Dávid erősebb volt a Filiszteusnál, parittyával és kővel. És levágta a Filiszteust és megölte őt, pedig kard nem is vala a Dávid kezében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, 'És oda futott Dávid, és reá állott a Filiszteusra, és vevé annak kardját, kirántotta hüvelyéből, és megölé őt, és fejét azzal levágta. A Filiszteusok pedig a mint meglátták, hogy az ő hősük meghalt, megfutamodának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, 'És felkelének Izráel és Júda férfiai és felkiáltának, és üldözék a Filiszteusokat egészen Gáthig és Ekron kapujáig. És hullának a Filiszteusok sebesültjei a Saraim felé vezető úton Gáthig és Ekronig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, 'Visszatérének azután Izráel fiai a Filiszteusok üldözéséből, és feldúlták azoknak táborát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, 'Dávid pedig felvevé a Filiszteusnak fejét, és elvitte Jeruzsálembe, fegyvereit pedig a maga sátorába rakta le.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, 'Saul pedig mikor látta, hogy Dávid kiment a Filiszteus elé, monda Abnernek, a sereg fővezérének: Abner! ki fia e gyermek? És felele Abner: Él a te lelked oh király, hogy nem tudom!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, 'És monda a király: Kérdezd meg tehát, hogy ki fia ez az ifjú?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, 'És a mint visszajött Dávid, miután megölte a Filiszteust, megfogá őt Abner, és Saulhoz vitte; és a Filiszteusnak feje kezében vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, 'És monda néki Saul: Ki fia vagy te, oh gyermek? Dávid pedig felele: A te szolgádnak, a Bethlehemből való Isainak a fia vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, 'Minekutána pedig elvégezte a Saullal való beszélgetést, a Jonathán lelke egybeforrt a Dávid lelkével, és Jonathán úgy szerette őt, mint a saját lelkét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, 'És Saul magához vevé őt azon a napon, és nem engedé, hogy visszatérjen atyja házához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, 'És szövetséget kötének Jonathán és Dávid egymással, mivel úgy szerette őt, mint a saját lelkét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, 'És Jonathán leveté felső ruháját, a mely rajta volt, és Dávidnak adta, sőt hadi öltözetét is, saját kardját, kézívét és övét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, 'És elméne Dávid mindenüvé, a hová Saul küldé, és magát eszesen viseli vala. És Saul a harczosok fölé tevé őt, és kedves lőn az egész nép előtt, és a Saul szolgái előtt is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, 'És a mint hazafelé jövének, mikor Dávid visszatért, miután a Filiszteusokat leverte, kimentek az asszonyok Saul király elé Izráelnek minden városaiból, hogy énekeljenek és körben tánczoljanak, dobokkal, vígassággal és tomborákkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, 'És énekelni kezdének az asszonyok, kik vígadozának és mondának: Megverte Saul az ő ezerét és Dávid is az ő tízezerét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, 'Saul pedig igen megharaguvék, és gonosznak tetszék az ő szemei előtt ez a beszéd, és monda: Dávidnak tízezeret tulajdonítanak és nékem tulajdonítják az ezeret, így hát már csak a királyság hiányzik néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, 'Saul azért attól a naptól kezdve rossz szemmel néz vala Dávidra, sőt azután is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, 'Másnap pedig megszállta Sault az Istentől küldött gonosz lélek, és prófétálni kezde a maga házában; Dávid pedig hárfázott kezével, mint naponként szokta, és a dárda Saul kezében vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, 'És elhajítá Saul a dárdát, azt gondolván: Dávidot a falhoz szegezem; de Dávid két ízben is félrehajolt előle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, 'És félni kezde Saul Dávidtól, mert az Úr vele volt, Saultól pedig eltávozék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, 'És Saul elbocsátá őt magától és ezredesévé tevé; és kimegy vala és bejő vala a nép előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, 'És Dávid minden útjában magát eszesen viseli vala, mert az Úr vele volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, 'Mikor pedig látta Saul, hogy ő igen eszesen viseli magát, félni kezde tőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, 'De az egész Izráel és Júda szereté Dávidot, mert ő előttük méne ki és jöve be.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, 'És monda Saul Dávidnak: Ímé idősebbik leányomat, Mérábot néked adom feleségül, csak légy az én vitéz fiam, és harczold az Úrnak harczait; mert azt gondolá Saul: Ne az én kezem által vesszen el, hanem a Filiszteusok keze által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, 'Dávid pedig monda Saulnak: Kicsoda vagyok én, és micsoda az én életem, és atyámnak családja Izráelben, hogy a királynak veje legyek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, 'De történt abban az időben, mikor Mérábot, a Saul leányát Dávidnak kellett volna adni, hogy a Meholáthból való Hadrielnek adták őt feleségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, 'Mikál, a Saul leánya azonban megszereté Dávidot, és mikor ezt megmondák Saulnak, tetszék néki a dolog.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, 'És monda Saul: Néki adom őt, hogy ő legyen veszedelmére és a Filiszteusok keze legyen ellene. Monda azért Saul Dávidnak másodízben: Légy tehát most az én vőm.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, 'És megparancsolá Saul az ő szolgáinak: Beszéljetek Dáviddal titokban, mondván: Ímé a király jóindulattal van irántad, és szolgái is mind szeretnek téged, légy azért veje a királynak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, 'És elmondák a szolgák Dávid előtt e beszédeket. Dávid pedig monda: Olyan kicsiny dolog előttetek, hogy a király vejévé legyen valaki, holott én szegény és megvetett ember vagyok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, 'És megmondák Saulnak az ő szolgái, mondván: Ezt meg ezt mondta Dávid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, 'Saul pedig monda: Mondjátok meg Dávidnak: Nem kiván a király más jegyajándékot, hanem csak száz Filiszteus előbőrét, hogy bosszút állj a király ellenségein; mert Saul a Filiszteusok keze által akará Dávidot elpusztítani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, 'Megmondák azért az ő szolgái Dávidnak e beszédeket; és tetszék ez a dolog Dávidnak, hogy a király veje legyen. A kitűzött napok még el sem telének,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, 'Mikor Dávid felkelt, és elment embereivel együtt, és levágott a Filiszteusok közül kétszáz férfit; és elhozá Dávid előbőreiket, és mind beadta azokat a királynak, hogy a királynak veje lehessen. És néki adá Saul az ő leányát, Mikált, feleségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, 'Mikor pedig Saul látta és megtudta, hogy az Úr Dáviddal van, és Mikál, a Saul leánya szereti őt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, 'Akkor Saul még inkább félni kezde Dávidtól. És Saul ellensége lőn Dávidnak teljes életében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, 'A Filiszteusok vezérei pedig gyakran betörnek vala, de valahányszor betörének, Dávid Saul minden szolgáinál eszesebben viselé magát; azért felette híressé lőn az ő neve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'És szóla Saul fiának, Jonathánnak, és a többi szolgáinak, hogy öljék meg Dávidot; de Jonathán, a Saul fia nagyon szereté őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'Megmondá azért Jonathán Dávidnak, mondván: Az én atyám, Saul azon van, hogy téged megöljön, azért vigyázz magadra reggel; titkos helyen tartózkodjál és rejtsd el magad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, 'Én pedig kimegyek, és atyám mellett megállok a mezőn, a hol te leszesz, és beszélni fogok atyámmal felőled, és meglátom, mint lesz, és tudtodra adom néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'És Jonathán kedvezően nyilatkozék Dávid felől az ő atyja, Saul előtt, és monda néki: Ne vétkezzék a király Dávid ellen, az ő szolgája ellen, mert ő nem vétett néked, sőt szolgálata felette hasznos volt néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, 'Mert ő koczkára tette életét és megverte a Filiszteust, és az Úr nagy szabadulást szerze az egész Izráelnek. Te láttad azt és örültél rajta; miért vétkeznél azért az ártatlan vér ellen, megölvén Dávidot ok nélkül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'És hallgatott Saul Jonathán szavára, és megesküvék Saul: Él az Úr, hogy nem fog megöletni!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'Akkor szólítá Jonathán Dávidot, és megmondá néki Jonathán mind e beszédeket; és Saulhoz vezeté Jonathán Dávidot, a ki ismét olyan lőn előtte, mint annakelőtte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, 'A háború pedig ismét megkezdődék, és Dávid kivonula, és harczola a Filiszteusok ellen, és nagy vereséget okozott nékik, és azok elfutának előle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'Az Istentől küldött gonosz lélek azonban megszállta Sault, mikor házában ült és dárdája kezében vala; Dávid pedig pengeté a hárfát kezével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'Akkor Saul a dárdával Dávidot a falhoz akará szegezni, de félrehajolt Saul elől, és a dárda a falba verődött. Dávid pedig elszalada, és elmenekült azon éjjel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'És követeket külde Saul a Dávid házához, hogy reá lessenek és reggel megöljék őt. De tudtára adá Dávidnak Mikál, az ő felesége, mondván: Ha meg nem mented életedet ez éjjel, holnap megölnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'És lebocsátá Mikál Dávidot az ablakon; ő pedig elment és elszalada, és megmenté magát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, 'És vevé Mikál a theráfot és az ágyba fekteté azt, és feje alá kecskeszőrből készült párnát tett, és betakará lepedővel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'Mikor pedig Saul elküldé a követeket, hogy Dávidot megfogják, azt mondá: Dávid beteg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'És Saul elküldé ismét a követeket, hogy megnézzék Dávidot, mondván: Ágyastól is hozzátok őt előmbe, hogy megöljem őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, 'És mikor a követek oda menének: ímé, a theráf volt az ágyban, és feje alatt a kecskeszőrből készült párna volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'Akkor monda Saul Mikálnak: Mi dolog, hogy engem úgy megcsaltál? – elbocsátád az én ellenségemet, és ő elmenekült. És felele Mikál Saulnak: Ő mondá nékem, bocsáss el engem, vagy megöllek téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'Dávid pedig elfutván, megszabadula; és elment Sámuelhez Rámába, és elbeszélte néki mindazt, a mit Saul vele cselekedett. Elméne ezután ő és Sámuel, és Nájóthban tartózkodának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'És tudtára adák Saulnak, mondván: Ímé Dávid Nájóthban van, Rámában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'Követeket külde azért Saul, hogy Dávidot fogják meg. A mint azonban meglátták a prófétáknak seregét, a kik prófétálának, és Sámuelt, a ki ott állott, mint az ő előljárójuk; akkor az Istennek lelke Saul követeire szállott, és azok is prófétálának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, 'Mikor pedig megmondták Saulnak, más követeket külde, és azok is prófétálának. Akkor harmadízben is követeket külde Saul, de azok is prófétálának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, 'Elméne azért ő maga is Rámába. És a mint a nagy kúthoz érkezék, mely Székuban van, megkérdezé, mondván: Hol van Sámuel és Dávid? És felelének: Ímé Nájóthban, Rámában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'És elméne oda Nájóthba, Rámában. És az Istennek lelke szálla ő reá is, és folytonosan prófétála, míg eljutott Nájóthba, Rámában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, 'És leveté ő is ruháit, és prófétála, ő is Sámuel előtt és ott feküvék meztelenül azon az egész napon és egész éjszakán. Azért mondják: Avagy Saul is a próféták közt van-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'Elfuta azért Dávid Nájóthból, mely Rámában van, és elméne és monda Jonathánnak: Mit cselekedtem? Mi vétkem van és mi bűnöm atyád előtt, hogy életemre tör?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'Ő pedig monda néki: Távol legyen! Te nem fogsz meghalni. Ímé az én atyám nem cselekszik sem nagy, sem kicsiny dolgot, hogy nékem meg ne mondaná. Miért titkolná el azért atyám előlem ezt a dolgot? Nem úgy van!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'Mindazáltal Dávid még megesküvék, és monda: Bizonyára tudja a te atyád, hogy te kedvelsz engem, azért azt gondolá: Ne tudja ezt Jonathán, hogy valamikép meg ne szomorodjék. De bizonyára él az Úr és él a te lelked, hogy alig egy lépés van köztem és a halál között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'És felele Jonathán Dávidnak: A mit lelked kiván, megteszem éretted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'És monda Dávid Jonathánnak: Ímé holnap újhold lesz, mikor a királylyal kellene leülnöm, hogy egyem, de te bocsáss el engem, hogy elrejtőzzem a mezőn a harmadik nap estvéjéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, 'Ha kérdezősködnék atyád utánam, ezt mondjad: Sürgősen kéredzett Dávid tőlem, hogy elmehessen Bethlehembe, az ő városába, mert ott az egész nemzetségnek esztendőnként való áldozatja van most.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, 'Ha azt fogja mondani: Jól van, úgy békessége van a te szolgádnak; ha pedig nagyon megharagudnék, úgy tudd meg, hogy a gonosz tettre elhatározta magát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, 'Cselekedjél azért irgalmasságot a te szolgáddal, mert az Úr előtt szövetséget kötöttél én velem, a te szolgáddal. Ha azonban gonoszság van bennem, ölj meg te; miért vinnél atyádhoz engemet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'Jonathán pedig felelé: Távol legyen az tőled! Ha bizonyosan megtudom, hogy atyám elhatározta magát arra, hogy a gonosz tettet rajtad végrehajtsa, avagy nem mondanám-é meg azt néked?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'És monda Dávid Jonathánnak: Kicsoda adja nékem tudtomra, hogy a mit atyád felelni fog néked, szigorú-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'És monda Jonathán Dávidnak: Jer, menjünk ki a mezőre; és kimenének mindketten a mezőre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'Akkor monda Jonathán Dávidnak: Az Úr az Izráelnek Istene; ha kipuhatolhatom atyámtól holnap ilyenkorig vagy holnapután, hogy ímé Dávid iránt jó akarattal van, tehát nem küldök-é ki akkor hozzád és jelentem-é meg néked?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'Úgy cselekedjék az Úr Jonathánnal most és azután is, ha atyámnak az tetszenék, hogy gonoszszal illessen téged: hogy tudtodra adom néked, és elküldelek téged, hogy békében elmehess. És az Úr legyen veled, mint volt az én atyámmal!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, 'És ne csak a míg én élek, és ne csak magammal cselekedjél az Úrnak irgalmassága szerint, hogy meg ne haljak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'Hanem meg ne vond irgalmasságodat az én házamtól soha, még akkor se, hogyha az Úr kiirtja Dávid ellenségeit, mindegyiket a földnek színéről!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, 'Így szerze szövetséget Jonathán a Dávid házával; mondván: vegyen számot az Úr a Dávid ellenségeitől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'És Jonathán még egyszer megesketé Dávidot, iránta való szeretetéből; mert úgy szerette őt, mint a saját lelkét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'Monda pedig néki Jonathán: Holnap újhold lesz, és kérdezősködni fognak utánad, mert helyed üres leend.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, 'A harmadik napon pedig jőjj alá gyorsan, és eredj arra a helyre, a hol elrejtőzél amaz esemény napján, és maradj ott az útmutató kő mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, 'És én három nyilat lövök oldalához, mintha magamtól czélba lőnék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'És ímé utánuk küldöm a gyermeket: Eredj, keresd meg a nyilakat. Ha azt mondom a gyermeknek: Ímé mögötted vannak emerre: hozd el azokat és jőjj elő, mert békességed van néked, és nincs baj, él az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, 'Ha pedig azt mondom a gyermeknek: Ímé előtted vannak a nyilak amarra: akkor menj el, mert elküldött téged az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, 'És erre a dologra nézve, a melyet megbeszéltünk egymás közt, ímé az Úr legyen bizonyság közöttem és közötted mind örökké!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'Elrejtőzék azért Dávid a mezőn. És mikor az újhold eljött, leült a király az ebédhez, hogy egyék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, 'És mikor leült a király a maga székébe, most is úgy, mint máskor, a fal mellett levő székbe: Jonathán felkele, és Abner ült Saul mellé; a Dávid helye pedig üres vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'És Saul semmit sem szólott azon a napon, mert azt gondolá: Valami történt vele; nem tiszta, bizonyosan nem tiszta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, 'És lőn az újhold után következő napon, a második napon, mikor ismét üres volt a Dávid helye, monda Saul az ő fiának, Jonathánnak: Isainak fia miért nem jött el az ebédre sem tegnap, sem ma?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'Jonathán pedig felele Saulnak: Elkéredzék tőlem Dávid Bethlehembe;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'És monda: Ugyan bocsáss el engem, mert nemzetségünknek áldozata van most a városban, és ezt parancsolta nékem bátyám; azért, ha kedvelsz engem, kérlek, hadd menjek el, hogy megnézzem testvéreimet. Ezért nem jött el a király asztalához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'Akkor felgerjede Saulnak haragja Jonathán ellen és monda néki: Te elfajult, engedetlen gyermek! Jól tudom, hogy kiválasztottad az Isainak fiát a magad gyalázatára és anyád szemérmének gyalázatára!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'Mert mindaddig, míg Isainak fia él a földön, nem állhatsz fenn sem te, sem a te királyságod; most azért küldj érette, és hozasd ide őt hozzám, mert ő a halál fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'Jonathán pedig felele Saulnak, az ő atyjának, és monda néki: Miért kell meghalnia, mit vétett?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'Akkor Saul utána dobta dárdáját, hogy általüsse őt. És megérté Jonathán, hogy atyja elvégezé, hogy megölje Dávidot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'És felkele Jonathán az asztaltól nagy haraggal, és semmit sem evék az újholdnak második napján, mert bánkódott Dávid miatt, mivel atyja gyalázattal illeté őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, 'És reggel kiméne Jonathán a mezőre a Dáviddal együtt meghatározott időben, és egy kis gyermek volt vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, 'És monda a gyermeknek: Eredj, keresd meg a nyilakat, a melyeket ellövök. És mikor a gyermek elfutott, ellövé a nyilat, úgy hogy rajta túl méne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, 'És mikor a gyermek arra a helyre érkezék, a hol a nyíl vala, melyet Jonathán ellőtt, a gyermek után kiálta Jonathán, és monda: Avagy nem tovább van-é a nyíl előtted?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'És kiálta Jonathán a gyermek után: Gyorsan siess, meg ne állj! És a gyermek, ki Jonathánnal vala, felszedé a nyilat és urához ment.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, 'A gyermek pedig semmit sem értett, hanem csak Jonathán és Dávid értették e dolgot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'Átadá azután Jonathán fegyverét a gyermeknek, a ki vele volt, és monda néki: Eredj el, vidd be a városba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, 'Mikor pedig elment a gyermek, felkele Dávid a kő déli oldala mellől és arczczal a földre borula, és háromszor meghajtotta magát; és megcsókolták egymást, és együtt sírtak, mígnem Dávid hangosan zokogott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'Akkor monda Jonathán Dávidnak: Eredj el békességgel! Mivelhogy megesküdtünk mind a ketten az Úrnak nevére, mondván: Az Úr legyen köztem és közted, az én magom között és a te magod között örökre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 43, 'Felkele ezután és elméne. Jonathán pedig bement a városba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'És Dávid elméne Nóbba Akhimélek paphoz. Akhimélek pedig megrettenve ment Dávid elé, és monda néki: Mi dolog, hogy csak egyedül vagy, és senki sincs veled?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, 'És monda Dávid Akhimélek papnak: A király bízott reám valamit, és monda nékem: Senki se tudja meg azt a dolgot, a miért elküldélek téged, és a mit parancsoltam néked; azért a szolgákat elküldém erre és erre a helyre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'Most azért, mi van kezednél? Adj öt kenyeret nékem, vagy egyebet, a mi van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, 'És felele a pap Dávidnak, és monda: Nincs közönséges kenyér kezemnél, hanem csak szentelt kenyér van, ha ugyan a szolgák tisztán tartották magokat, legalább az asszonytól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, 'Dávid pedig felele a papnak, és monda néki: Bizonyára el volt tiltva mi tőlünk az asszony mind tegnap, mind azelőtt, mikor elindulék, és a szolgák holmija is tiszta vala (jóllehet az út közönséges): azért bizonyára megtartatik ma szentnek az edényekben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, 'Adott azért a pap néki szentelt kenyeret, mert nem volt ott más kenyér, hanem csak szent kenyér, melyeket elvettek az Úrnak színe elől, hogy meleg kenyeret tegyenek a helyett azon a napon, a melyen az előbbit elvevék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, 'Vala pedig ott azon a napon Saul szolgái közül egy ember, ott tartózkodva az Úr előtt, a kit Doégnak hívtak, a ki Edomita volt, Saul pásztorainak számadója.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'És monda Dávid Akhiméleknek: Nincsen-é kezednél egy dárda vagy valami fegyver? mert sem kardomat, sem fegyverzetemet nem hoztam magammal, mivel a király dolga sürgős vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, 'És monda a pap: A Filiszteus Góliáthnak a kardja, a kit te megöltél az Elah völgyében, ímhol van posztóba betakarva az efód mögött; ha azt el akarod vinni, vidd el, mert azonkivül más nincsen itt. És monda Dávid: Nincs ahhoz hasonló, add ide azt nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'És felkele Dávid, és elfutott azon a napon Saul elől, és elment Ákhishoz, Gáthnak királyához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'És mondának Ákhis szolgái néki: Vajjon nem ez-é Dávid, annak az országnak királya? Vajjon nem erről énekelték-é a körtánczban, mondván: Saul megverte az ő ezerét, Dávid is az ő tízezerét?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'És mikor eszébe vevé Dávid ezeket a beszédeket, igen megrémüle Ákhistól, Gáthnak királyától.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, 'És megváltoztatá magaviseletét ő előttük, és őrjönge kezeik között, és irkál vala a kapuknak ajtain, nyálát pedig szakállán folyatja alá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'És monda Ákhis az ő szolgáinak: Ímé látjátok, hogy ez az ember megőrült, miért hoztátok őt hozzám?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, 'Szűkölködöm-e őrültekben, hogy ide hoztátok ezt, hogy bolondoskodjék előttem? Ez jőjjön-e be házamba?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, 'Elméne azért onnan Dávid, és elfutott Adullám barlangjába. És mikor meghallották testvérei és atyjának egész háza népe, oda menének hozzá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'És hozzá gyűlének mindazok, a kik nyomorúságban valának, és mindazok, a kiknek hitelezőik voltak, és minden elkeseredett ember, ő pedig vezérük lett azoknak; és mintegy négyszázan valának ő vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'És elméne onnan Dávid Miczpába, Moáb földére, és monda Moáb királyának: Hadd jőjjön ide hozzátok az én atyám és anyám, míg megtudom, hogy mit fog cselekedni velem az Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, 'És vivé őket Moáb királya elé, és ott maradának vele mindaddig, míg Dávid a várban volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, 'Gád próféta pedig monda Dávidnak: Ne maradj a várban, hanem eredj és menj el Júda földére. Elméne azért Dávid, és Héreth erdejébe ment.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, 'És meghallotta Saul, hogy előtűnt Dávid és azok az emberek, a kik vele valának; (Saul pedig Gibeában tartózkodék a hegyen a fa alatt és dárdája a kezében vala és szolgái mindnyájan mellette állának).');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'Monda azért Saul az ő szolgáinak, a kik mellette állottak: Halljátok meg Benjáminnak fiai! Isainak fia adni fog-é néktek mindnyájatoknak szántóföldeket és szőlőhegyeket, és mindnyájatokat ezredesekké és századosokká fog-é tenni,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, 'Hogy mindnyájan összeesküdtetek ellenem? És senki sincs, a ki tudósítana engem, hogy fiam szövetséget kötött Isai fiával? És senki sincs közöttetek, a ki szánakoznék felettem, és megmondaná nékem, hogy fiam fellázította szolgámat ellenem, hogy leselkedjék utánam, mint a hogy e mai napon megtetszik?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, 'Akkor felele az Edomita Doég, a ki Saul szolgái közt állott: Én láttam, hogy az Isai fia Nóbba ment vala az Akhitób fiához, Akhimélek paphoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'A ki ő érette megkérdé az Urat, és eleséget adott néki, sőt a Filiszteus Góliáth kardját is néki adá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, 'Akkor elkülde a király, hogy elhívják Akhimélek papot, az Akhitób fiát és atyjának egész házanépét, a papokat, a kik Nóbban valának; és eljövének mindnyájan a királyhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'És monda Saul: Halld meg most te, Akhitóbnak fia! Ő pedig monda: Ímhol vagyok uram.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'És monda néki Saul: Miért ütöttetek pártot ellenem, te és Isainak fia, hogy kenyeret és kardot adtál néki, és ő érette megkérdezéd az Istent, hogy fellázadjon ellenem, hogy leselkedjék, mint a hogy most történik?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'És felele Akhimélek a királynak, és monda: Minden szolgáid között kicsoda hűségesebb Dávidnál, a ki a királynak veje, és a ki akaratod szerint jár, és tisztelt ember a te házadban?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, 'Vajjon csak ma kezdém-e az Istent ő érette megkérdezni? Távol legyen tőlem! Ne tulajdonítson olyat a király szolgájának, sem atyám egész házanépének, mert erről a dologról semmit sem tud a te szolgád, sem kicsinyt, sem nagyot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, 'A király pedig monda: Meg kell halnod Akhimélek, néked és a te atyád egész házanépének!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, 'És monda a király a poroszlóknak, a kik mellette állának: Vegyétek körül és öljétek le az Úrnak papjait, mert az ő kezök is Dávid mellett vala, mert tudták, hogy ő menekül, és még sem mondták meg nékem. A király szolgái azonban nem akarták kezeiket felemelni, hogy az Úrnak papjaira rohanjanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, 'Akkor monda a király Doégnak: Fordulj nékik te, és rohanj a papokra. És ellenük fordula az Edomita Doég, és ő rohana a papokra. És azon a napon nyolczvanöt embert ölt meg, a kik gyolcs efódot viselének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'És Nóbot is, a papok városát fegyvernek élével vágatá le, mind a férfit, mind az asszonyt, mind a gyermeket, mind a csecsemőt; az ökröt és szamarat és bárányt, fegyvernek élével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'Akhitób fiának, Akhiméleknek egy fia azonban, a kit Abjáthárnak hívtak, elmenekült, és Dávid után futott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'És megmondá Abjáthár Dávidnak, hogy megölette Saul az Úrnak papjait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, 'Dávid pedig monda Abjáthárnak: Tudtam én azt már aznap, mert ott volt az Edomita Doég, hogy bizonyosan megmondja Saulnak. Én adtam okot atyád egész házanépének halálára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, 'Maradj nálam, ne félj; mert a ki az én életemet halálra keresi, az keresi a te életedet is, azért te bátorságosan lehetsz mellettem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, 'Értesíték pedig Dávidot, mondván: Ímé a Filiszteusok hadakoznak Kehilla ellen, és dúlják a szérűket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'Akkor megkérdezé Dávid az Urat, mondván: Elmenjek és leverjem-é ezeket a Filiszteusokat? És monda az Úr Dávidnak: Eredj el, és verd le a Filiszteusokat, és szabadítsd meg Kehillát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'A Dávid emberei azonban mondának néki: Ímé, mi itt Júdában is félünk, mennyivel inkább, ha Kehillába megyünk a Filiszteusok táborára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'Akkor Dávid ismét megkérdezé az Urat, az Úr pedig válaszola néki, és monda: Kelj fel, és menj el Kehillába, mert én a Filiszteusokat kezedbe adom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'Elméne azért Dávid és az ő emberei Kehillába, és harczola a Filiszteusok ellen, és elhajtá marhájokat, és felette igen megveré őket. És megszabadítá Dávid Kehilla lakosait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'Lőn pedig, hogy a mikor Abjáthár, az Akhimélek fia Dávidhoz menekült, az efódot is magával vitte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, 'Megmondák akkor Saulnak, hogy Dávid Kehillába ment; és monda Saul: Kezembe adta őt az Isten, mert ott szorult, mivel kulcsos és záros városba méne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'És összegyűjté Saul a harczra az egész népet, hogy Kehillába menjen, és körülfogja Dávidot és az ő embereit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'Mikor pedig Dávid megtudta, hogy Saul ő ellene gonoszt forral, mondá Abjáthár papnak: Hozd elő az efódot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'És monda Dávid: Uram, Izráel Istene! bizonynyal meghallotta a te szolgád, hogy Saul ide akar jőni Kehillába, hogy elpusztítsa a várost miattam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'Vajjon kezébe adnak-é engem Kehilla lakosai? Vajjon lejön-é Saul, a mint hallotta a te szolgád? Óh Uram, Izráel Istene, mondd meg a te szolgádnak! És monda az Úr: Lejön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, 'És monda Dávid: Vajjon Saul kezébe adnak-é Kehilla lakosai engem és az én embereimet? És monda az Úr: Kezébe adnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, 'Felkele azért Dávid és az ő emberei, mintegy hatszázan, és kimenének Kehillából, és ide s tova járnak vala, a hol csak járhatának. Midőn pedig Saulnak megmondák, hogy elmenekült Dávid Kehillából, felhagyott az elmenetellel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'És Dávid a pusztában tartózkodék az erős helyeken, és a Zif pusztájában levő hegységen marada. És Saul mindennap keresé, de az Isten nem adá őt kezébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'Mikor pedig Dávid látta, hogy Saul kiment, hogy élete ellen törjön; és mikor Dávid a Zif pusztájában, az erdőben vala:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'Felkele Jonathán, a Saul fia, és elment Dávidhoz az erdőbe, és megerősíté az ő kezét az Istenben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, 'És monda néki: Ne félj, mert Saulnak, az én atyámnak keze nem fog utólérni téged, és te király leszesz Izráel felett, és én második leszek te utánad, és Saul is, az én atyám, tudja, hogy így lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'És szövetséget kötének ketten az Úr előtt. És Dávid az erdőben marada, Jonathán pedig haza ment.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, 'És felmenének a Zifeusok Saulhoz Gibeába, mondván: Avagy nem nálunk lappang-é Dávid az erős helyeken az erdőben, Hakila halmán, mely a sivatagtól jobbkézre van?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, 'Most azért minthogy lelkednek főkivánsága az, hogy lejőjj, óh király, jőjj le; és a mi gondunk lesz, hogy a királynak kezébe adjuk őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'És monda Saul: Legyetek megáldva az Úrtól, hogy szánakoztok rajtam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, 'Menjetek azért el, és vigyázzatok ezután is, hogy megtudjátok és meglássátok az ő tartózkodási helyét, és hogy ki látta őt ott, mert azt mondották nékem, hogy igen ravasz ő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'Annakokáért nézzetek meg és tudjatok meg minden búvóhelyet, a hol ő lappang és minden bizonynyal térjetek vissza hozzám, hogy elmenjek veletek; és ha az országban van, kikutatom őt Júdának minden ezrei között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, 'Azok pedig felkelének, és elmenének Zifbe Saul előtt. Dávid pedig és az ő emberei Máon pusztájában valának a mezőségen, a mely a sivatagtól jobbkézre van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, 'És elméne Saul az ő embereivel együtt, hogy megkeresse őt. Dávidnak azonban megizenték, és ő leszállott a kőszikláról, és Máon pusztájában tartózkodék. Mikor pedig meghallotta Saul, üldözé Dávidot Máon pusztájában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'És Saul a hegynek egyik oldalán méne, Dávid és az ő emberei pedig a hegynek másik oldalán. És épen, mikor Dávid nagyon sietett, hogy elmenekülhessen Saul elől, és Saul és az ő emberei már körül is kerítették Dávidot és az ő embereit, hogy megfogják,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, 'Akkor érkezék egy követ Saulhoz, mondván: Siess és jőjj! mert a Filiszteusok betörtek az országba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, 'Akkor megtére Saul Dávid üldözéséből, és a Filiszteusok ellen ment. Azért hívják azt a hegyet a menekülés kősziklájának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, 'És Dávid elméne onnan, és Engedi erősségei közt tartózkodék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, 'Lőn pedig, hogy a mikor visszatért Saul a Filiszteusok üldözéséből, megizenték néki, mondván: Ímé Dávid az Engedi pusztájában van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, 'Maga mellé vőn azért Saul az egész Izráel közül háromezer válogatott embert, és elment, hogy megkeresse Dávidot és az ő embereit a vadkecskék kőszikláin.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, 'És eljutott a juhaklokhoz, a melyek az útfélen vannak, hol egy barlang volt; és beméne Saul, hogy ott szükségét végezze; Dávid pedig és az ő emberei a barlang rejtekeiben valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, 'Akkor mondák Dávidnak az ő emberei: Ímé ez az a nap, a melyről azt mondotta az Úr néked: Ímé kezedbe adom ellenségedet, hogy úgy cselekedjél vele, a mint néked tetszik. Felkele azért Dávid, és elmetszé orozva Saul ruhájának szárnyát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, 'Lőn pedig ezután, hogy megesett a Dávid szíve rajta, hogy elmetszé Saul ruhájának szárnyát;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, 'És monda az ő embereinek: Oltalmazzon meg engem az Úr attól, hogy ily dolgot cselekedjem az én urammal, az Úrnak felkentjével, hogy kezemet felemeljem ellene, mert az Úrnak felkentje ő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, 'És megfeddé Dávid kemény szókkal embereit, és nem engedte meg nékik, hogy Saul ellen támadjanak. Mikor pedig Saul felkelt a barlangból, és elment az úton:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, 'Dávid is felkelt ezután, és kiment a barlangból, és Saul után kiálta, mondván: Uram király! Mikor pedig Saul hátratekinte, Dávid arczczal a földre hajolt, és tisztességet tőn néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, 'És monda Dávid Saulnak: Miért hallgatsz az olyan ember szavaira, a ki azt mondja: Ímé Dávid romlásodra tör?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, 'Ímé a mai napon látták a te szemeid, hogy az Úr téged kezembe adott ma a barlangban, és azt mondották, hogy öljelek meg téged, de én kedvezék néked, és azt mondám: Nem emelem fel kezemet az én uram ellen, mert az Úrnak felkentje ő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, 'Azért atyám! nézd, ugyan nézd felső ruhádnak szárnyát kezemben, mert mikor levágtam felső ruhádnak szárnyát, nem öltelek meg téged! Azért tudd meg és lássad, hogy nincsen az én kezemben hamisság és semmi gonoszság és nem vétkeztem ellened, de te mégis életem után leselkedel, hogy elveszessed azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, 'Az Úr tegyen ítéletet közöttem és közötted, és álljon bosszút az Úr érettem rajtad, de az én kezem nem lesz ellened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, 'A mint a régi példabeszéd mondja: A gonoszoktól származik a gonoszság; de az én kezem nem lesz ellened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, 'Ki ellen jött ki Izráelnek királya? Kit kergetsz? Egy holt ebet, vagy egy bolhát?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, 'Legyen azért az Úr ítélőbiró, és tegyen ítéletet közöttem és közötted, és lássa meg; ő forgassa az én ügyemet, és szabadítson meg engem kezedből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, 'És lőn, hogy a mikor elmondotta Dávid e szókat Saul előtt, monda Saul: A te szavad-é ez, fiam, Dávid? És felkiálta Saul, és síra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, 'És monda Dávidnak: Te igazságosabb vagy én nálamnál, mert te jót cselekedtél velem, én pedig rosszal fizettem néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, 'És te megmondottad nékem a mai napon, minémű jót cselekedtél velem, hogy az Úr kezedbe adott engem, és te még sem öltél meg engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, 'Mert ha valaki megtalálja ellenségét, elbocsátja-é őt békében az úton? Annakokáért fizessen az Úr néked jóval azért, a mit velem ma cselekedtél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, 'Most pedig, mivel tudom, hogy te király leszesz, és Izráelnek királysága a te kezedben állandó lesz:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, 'Esküdjél meg nékem most az Úrra, hogy én utánam nem fogod kiirtani maradékomat és nevemet nem fogod kitörölni atyám házából!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 23, 'És Dávid megesküvék Saulnak. És Saul elméne haza, Dávid pedig és az ő emberei felmenének az ő erősségökbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, 'Meghala pedig Sámuel, és egybegyűle az egész Izráel, és siratták őt, és eltemették az ő házában Rámában. Dávid pedig felkelt és elment Párán pusztájába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'És volt egy ember Máonban, a kinek jószága Kármelben vala, és ez igen tehetős ember volt: háromezer juha és ezer kecskéje volt néki. És Kármelben épen juhait nyírta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, '(Azt az embert pedig Nábálnak, és feleségét Abigailnak hívták, a ki igen eszes és szép termetű asszony volt; a férfi azonban durva és rossz erkölcsű vala, a Káleb nemzetségéből való volt.)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'És meghallotta Dávid a pusztában, hogy Nábál a juhait nyírja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'Elkülde azért Dávid tíz ifjút, és monda Dávid az ifjaknak: Menjetek fel Kármelbe, és mikor Nábálhoz érkeztek, köszöntsétek őt nevemben békességesen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, 'És így szóljatok: Légy békességben az életben, legyen békességben a te házadnépe és legyen békességben mindened, a mid van!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, 'Most hallottam, hogy juhaidat nyiratod. A te pásztoraid pedig velünk valának, nem bántottuk őket, és semmijök sem hibázott az alatt az egész idő alatt, míg Kármelben valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, 'Kérdezd meg szolgáidat, ők meg fogják mondani néked. Legyenek azért ez ifjak kedvesek előtted, mert alkalmas időben jöttünk. Adj kérlek abból, a mi kezed közt van, szolgáidnak, és a te fiadnak, Dávidnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'Elmenének azért a Dávid szolgái, és szólának Nábálnak mind e beszédek szerint a Dávid nevében, és várakozának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'Nábál pedig felele a Dávid szolgáinak, és monda: Kicsoda Dávid és kicsoda Isainak fia? Mai napság sok olyan szolga van, a kik elszöknek uraiktól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, 'Vegyem azért kenyeremet és vizemet és az én levágott marhámat, a melyet nyíróimnak levágattam, hogy olyan embereknek adjam, a kikről azt sem tudom, hova valók?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'Akkor megfordulának a Dávid szolgái az ő útjokra, és visszatérének; és mikor megérkezének, értesítették őt mind e beszédek felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, 'És monda Dávid az ő embereinek: Kösse fel mindenki kardját! És felköté mindenki a kardját, Dávid is felköté az ő kardját; és felment Dávid után mintegy négyszáz ember; kétszáz pedig ott maradt a podgyásznál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, 'Abigailt pedig, a Nábál feleségét értesíté a szolgák közül egy ifjú, mondván: Ímé Dávid követeket küldött a pusztából, hogy köszöntsék a mi urunkat, de ő elűzé őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'Azok az emberek pedig igen jók voltak mi hozzánk; és nem volt bántódásunk, és semmink nem hibázott az alatt az egész idő alatt, míg velök jártunk, mikor a mezőn voltunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, 'Olyanok voltak reánk nézve, mint a kőfal, mind éjjel, mind nappal, az alatt az egész idő alatt, míg velök valánk, mikor a juhokat őriztük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'Most azért értsd meg és lássad, hogy mit kelljen cselekedned, mert jelen van a veszedelem a mi urunk és az ő egész háza ellen, ő pedig oly kegyetlen ember, hogy senki sem szólhat néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'Akkor Abigail sietve vőn kétszáz kenyeret, két tömlő bort, öt juhot elkészítve, öt mérték pergelt búzát, száz kötés aszúszőlőt és kétszáz kötés száraz fügét, és a szamarakra rakta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, 'És monda az ő szolgáinak: Menjetek el előttem, ímé én utánatok megyek; de férjének, Nábálnak nem mondá meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'És történt, hogy a mint a szamáron megy vala, és leereszkedék a hegynek egyik mellékösvényén: ímé Dávid és az ő emberei lejövének eleibe, és ő összetalálkozék velök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, 'Dávid pedig azt mondotta volt: Bizony hiába őriztem ennek mindenét, a mije van a pusztában, hogy semmi híjja nem lett mindannak, a mi az övé, mert ő a jó helyett roszszal fizet nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, 'Úgy cselekedjék az Isten Dávid ellenségeivel most és ezután is, hogy reggelig meg nem hagyok mindabból, a mi az övé, még egy ebet sem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'Mikor pedig meglátta Abigail Dávidot, sietve leszállott a szamárról, és arczczal leborula Dávid előtt, és meghajtá magát a földig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, 'És az ő lábaihoz borula, és monda: Óh uram! én magam vagyok a bűnös, mindazáltal hadd beszéljen a te szolgálóleányod te előtted, és hallgasd meg szolgálóleányodnak szavait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'Kérlek, ne törődjék az én uram Nábállal, ezzel a kegyetlen emberrel, mert a milyen a neve, olyan ő maga is; bolond az ő neve és bolondság van benne. Én azonban, a te szolgálóleányod, nem láttam az én uramnak szolgáit, a kiket elküldöttél volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'Most pedig, óh uram! él az Úr és él a te lelked, hogy az Úr akadályozott meg téged, hogy gyilkosságba ne essél, és ne saját kezeddel szerezz magadnak elégtételt. Most azért olyanok legyenek ellenségeid, mint Nábál, és valakik az én uramnak megrontására törekesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'És most ezt az ajándékot, a melyet a te szolgálóleányod hozott az én uramnak, adják a vitézeknek, a kik az én uram körül forgolódnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, 'Bocsásd meg azért a te szolgálóleányodnak vétkét; mert az én uramnak bizonyára maradandó házat épít az Úr, mert az Úrnak harczait harczolja az én uram, és gonoszság nem találtatik te benned a te életedben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, 'És ha valaki feltámadna ellened, hogy téged üldözzön és életed ellen törjön: az én uramnak lelke az élőknek csomójába leend bekötve az Úrnál a te Istenednél; ellenségeidnek lelkét pedig a parittyának öbléből fogja elhajítani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'És mikor az Úr megadja a jót az én uramnak mind a szerint, a mint megmondotta felőled, és téged fejedelmül rendel Izráel fölé:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'Akkor, óh uram, nem leend ez néked bántásodra és szívednek fájdalmára, hogy ok nélkül vért ontottál, és hogy az én uram saját maga szerzett magának elégtételt. Mikor azért jót tesz az Úr az én urammal: emlékezzél meg szolgálóleányodról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'És monda Dávid Abigailnak: Áldott legyen az Úr, Izráelnek Istene, a ki téged ma előmbe küldött!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'És áldott legyen a te tanácsod, és áldott légy te magad is, hogy a mai napon megakadályoztál engem, hogy gyilkosságba ne essem, és ne saját kezemmel szerezzek magamnak elégtételt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, 'Bizonyára él az Úr, az Izráelnek Istene, a ki megakadályozott engem, hogy veled gonoszul ne cselekedjem, mert ha te nem siettél és nem jöttél volna előmbe, úgy Nábálnak nem maradt volna meg reggelre csak egyetlen ebe sem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'És átvevé Dávid az ő kezéből, a mit hozott néki, és monda néki: Eredj el békességben a te házadhoz; lásd, hallgattam szavadra, és megbecsültem személyedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, 'Mikor pedig Abigail Nábálhoz visszaérkezék, ímé olyan lakoma volt az ő házában, mint a király lakomája, és Nábál szíve vigadozék azon, mert igen megrészegedett; azért ő semmit sem mondott meg néki, sem kicsinyt, sem nagyot egészen reggelig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, 'Reggel pedig, mikor Nábál kijózanodék, megmondá néki felesége ezeket a dolgokat; és elhala az ő szíve ő benne, és olyanná lőn, mint a kő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, 'És mintegy tíz nap mulva megveré az Úr Nábált, és meghala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'És mikor Dávid meghallotta, hogy Nábál meghalt, monda: Áldott legyen az Úr, ki bosszút állott Nábálon az én gyaláztatásomért, és szolgáját visszatartotta a gonosztól, a Nábál gonoszságát pedig visszafordítá az Úr az ő fejére! És elkülde Dávid, és izent Abigailnak, hogy elvenné őt feleségéül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'Elmenének azért Dávid szolgái Abigailhoz Kármelbe, és beszélének vele, mondván: Dávid küldött minket hozzád, hogy téged elvegyen feleségéül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'Ő pedig felálla, és meghajtotta magát arczczal a földre, és monda: Ímé a te szolgálóleányod szolgáló lesz, hogy mossa az én uram szolgáinak lábait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'És Abigail sietve felkele, és felült a szamárra és az ő öt szolgálóleánya, a kik körülötte valának, és elment Dávid követei után, és az ő felesége lőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'Ahinoát is elvevé Dávid Jezréelből, és mind a kettő felesége lőn néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, 'Saul pedig az ő leányát, Mikált, a Dávid feleségét Páltinak, a Láis fiának adá, a ki Gallimból való volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, 'És menének a Zifeusok Saulhoz Gibeába, mondván: Nemde nem a Hakila halmán lappang-é Dávid, a puszta átellenében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'Felkele azért Saul, és lement Zif pusztájába, és vele volt Izráel közül háromezer válogatott ember, hogy megkeresse Dávidot Zif pusztájában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, 'És tábort jára Saul a Hakila halmán, mely a puszta átellenében van, az úton; Dávid pedig a pusztában tartózkodék. És mikor észrevette, hogy Saul utána ment a pusztába:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'Kémeket küldött ki Dávid, és megtudta biztosan, hogy Saul eljött.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'És felkele Dávid, és elment arra a helyre, a hol Saul táborozott, és megnézte Dávid azt a helyet, a hol feküvék Saul és Abner, a Nér fia, seregének fővezére. Saul pedig a kerített táborban feküvék, és a nép körülötte táborozott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'Akkor szóla Dávid, és monda a Hitteus nemzetségéből való Akhiméleknek és Abisainak, a Seruja fiának, a ki Joábnak testvére vala, mondván: Ki jön le velem Saulhoz a táborba? És mondá Abisai: Lemegyek én veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'És elméne éjjel Dávid, és Abisai a nép közé. És ímé, Saul lefeküvén, alszik vala a kerített táborban, és dárdája a földbe volt szúrva fejénél; Abner pedig és a nép körülötte feküvének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'Akkor monda Abisai Dávidnak: Kezedbe adta a mai napon Isten a te ellenségedet; most azért, hadd szegezzem a földhöz őt a dárdával egy ütéssel, és másodszor nem ütöm át.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'Dávid azonban monda Abisainak: Ne veszesd el őt! Mert vajjon ki emelhetné fel kezét az Úrnak felkentje ellen büntetlenül?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, 'És monda Dávid: Él az Úr, hogy az Úr megveri őt! Vagy eljön az ő napja és meghal, vagy pedig harczba megy és ott vész el!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'Távoztassa el azért az Úr tőlem azt, hogy kezemet az Úrnak felkentje ellen emeljem, hanem csak vedd a dárdát, mely feje mellett van, és a vizes korsót, és menjünk el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'Akkor elvevé Dávid a dárdát és a vizes korsót Saul feje mellől, és elmenének. És senki sem volt, a ki látta volna, sem a ki észrevette volna, sem a ki felserkent volna, hanem mindnyájan aluvának, mert az Úr mély álmot bocsátott reájok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'És mikor Dávid általment a túlsó oldalra, megállott a hegy tetején messzire, úgy, hogy nagy távolság volt közöttük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'És kiálta Dávid a népnek és Abnernek, a Nér fiának, mondván: Nem felelsz-é Abner? És felele Abner, és monda: Kicsoda vagy te, hogy így kiáltasz a királynak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'Dávid pedig monda Abnernek: Avagy nem férfi vagy-é te, és kicsoda olyan, mint te Izráelben? És miért nem vigyáztál a te uradra, a királyra? Mert a nép közül oda ment egy ember, hogy elveszesse a te uradat, a királyt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, 'Nem jó dolog ez, a mit cselekedtél! Él az Úr, hogy halál fiai vagytok ti, a miért nem vigyáztatok a ti uratokra, az Úrnak felkentjére! Most azért nézd meg, hol van a király dárdája és a vizes korsó, a mely fejénél volt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'És megismeré Saul a Dávid hangját, és monda: A te hangod-é ez fiam, Dávid? Dávid pedig monda: Az én hangom, uram király!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'És monda: Miért üldözi szolgáját az én uram? Ugyan mit cselekedtem, és micsoda gonoszság van én bennem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, 'Most azért hallgassa meg az én uram, a király, az ő szolgájának szavát! Ha az Úr ingerelt fel téged ellenem: vajha jóillatú volna előtte az áldozat; ha pedig emberek: átkozottak legyenek az Úr előtt, mert kiűznek most engemet, hogy ne részesülhessek az Úrnak örökségében, azt mondván: Eredj, szolgálj idegen isteneknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'Azért ne omoljék az én vérem a földre távol az Úr színétől; mert Izráelnek királya kijött, hogy egy bolhát keressen, úgy, mint egy fogoly madarat üldöznek a hegyeken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'Saul pedig monda: Vétkeztem! térj vissza fiam, Dávid, mert többé nem cselekszem veled gonoszul, mivel az én életem kedves volt előtted a mai napon. Ímé, esztelenül cselekedtem, és igen nagyot vétettem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'És felele Dávid, és monda: Ímhol a király dárdája, jőjjön ide a szolgák közül egy, és vigye el azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'Az Úr pedig fizessen meg mindenkinek az ő igazsága és hűsége szerint, mert az Úr kezembe adott téged ma, de én nem akartam felemelni kezemet az Úrnak felkentje ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, 'És a mennyire drága volt a mai napon a te lelked én előttem, legyen annyira drága az én lelkem az Úr előtt, és szabadítson meg engem minden nyomorúságból!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'Akkor monda Saul Dávidnak: Áldott légy te, fiam Dávid, hatalmasan is fogsz cselekedni, és győzni is fogsz! És elment Dávid a maga útjára, Saul pedig visszatért az ő helyére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, 'És monda Dávid magában: Egy napon mégis el kell pusztulnom a Saul keze miatt, nincs jobb reám nézve, mintha gyorsan elmenekülök a Filiszteusok tartományába, így Saul felhagy azzal, hogy engem tovább is üldözzön Izráel egész területén, és így megszabadulok az ő kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'Felkelvén azért Dávid, elméne ő és az a hatszáz ember, a kik vele valának, Ákhishoz, a Máok fiához, Gáth királyához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'És Dávid Ákhisnál tartózkodék Gáthban, ő és az ő emberei, mindegyik a maga házanépével együtt; Dávid és az ő két felesége, a Jezréelből való Ahinoám és a Kármelből való Abigail, a Nábál felesége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'Mikor pedig Saulnak megmondották, hogy Dávid Gáthba menekült, nem üldözé tovább őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'És monda Dávid Ákhisnak: Ha kedvet találtam előtted, adj helyet nékem valamelyik vidéki városban, hogy ott lakjam: miért laknék a te szolgád veled a királyi városban?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'És néki adá Ákhis azon a napon Siklágot; lőn azért Siklág a Júda királyaié mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, 'És lőn ama napoknak száma, míg Dávid a Filiszteusok földén lakozék, egy esztendő és négy hónap.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'És felméne Dávid embereivel együtt és megtámadták a Gessureusokat, a Girzeusokat és az Amálekitákat: mert ezek voltak annak a földnek lakosai eleitől fogva, a melyen Súrba mégy egészen Égyiptom földéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'És mikor Dávid megverte az országot, sem férfit, sem asszonyt nem hagyott életben, és elvitt juhot, ökröt, szamarakat, tevéket és ruhákat, és úgy tért vissza és ment Ákhishoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'Mikor pedig Ákhis azt kérdé: Hova törtetek be most? Dávid ekként felele: Júda déli részére és Jerákhméelnek déli részére és Kéneusnak déli részére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'Dávid azonban sem férfit, sem asszonyt nem hagyott életben, hogy Gáthba vigye, mondván: Valamikép ellenünk ne nyilatkozzanak és azt mondják: Így cselekedett Dávid. Ez volt az ő szokása amaz egész idő alatt, míg a Filiszteusok földjén tartózkodék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'És Ákhis bízott Dávidban, mondván: Bizonyosan gyűlöletessé tette magát az ő népe, Izráel előtt, azért örökké az én szolgám leend.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, 'És történt abban az időben, hogy a Filiszteusok összegyűjték seregeiket a hadra, hogy harczoljanak Izráel ellen. És monda Ákhis Dávidnak: Tudd meg, hogy velem kell jőnöd a táborba, mind néked, mind embereidnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'Dávid pedig felele Ákhisnak: Meglátod bizonynyal, hogy mit fog cselekedni a te szolgád. És monda Ákhis Dávidnak: Ennélfogva fejem oltalmazójává teszlek mindenkorra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, 'Sámuel pedig meghalt vala, és siratá őt az egész Izráel, és eltemeték őt saját városában, Rámában; Saul pedig a varázslókat és jövendőmondókat kiirtá a földről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'És mikor a Filiszteusok egybegyűlvén, eljövének és tábort járának Sunemnél: egybegyűjté Saul is az egész Izráelt, és tábort járának Gilboánál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'A mint azonban Saul meglátta a Filiszteusok táborát, megfélemlék és az ő szíve nagyon megrémüle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'És megkérdezé Saul az Urat, de az Úr nem felelt néki sem álomlátás, sem az Urim, sem a próféták által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'Akkor monda Saul az ő szolgáinak: Keressetek nékem egy halottidéző asszonyt, hogy elmenjek hozzá, és megkérdezzem őt. Szolgái pedig mondának néki: Ímé, Endorban van egy halottidéző asszony.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'Másnak tetteté azért Saul magát, és más ruhákat vevén magára, elméne ő és vele két férfi; és elmenének éjjel az asszonyhoz, és monda: Mondj jövendőt nékem halottidézés által, és idézd fel nékem azt, a kit mondok néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, 'És monda az asszony néki: Ímé te jól tudod, hogy mit cselekedett Saul, hogy kiirtá a földről a varázslókat és jövendőmondókat; miért akarod azért tőrbe ejteni az én lelkemet, hogy megöless engem?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'És megesküvék néki Saul az Úrra, mondván: Él az Úr, hogy e dolog miatt büntetésed nem lészen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, 'Monda azért az asszony: Kit idézzek fel néked? És ő monda: Sámuelt idézd fel nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, 'Mikor pedig az asszony Sámuelt meglátta, hangosan felkiáltott. És szóla az asszony Saulnak, mondván: Miért csaltál meg engem? hiszen te vagy Saul!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, 'És monda néki a király: Ne félj! Ugyan mit láttál? Az asszony pedig monda Saulnak: istenfélét látok feljőni a földből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, 'És ő monda néki: Milyen ábrázata van? Ő pedig monda: Egy vén ember jő fel, és palást van rajta. És megismeré Saul, hogy az Sámuel, és meghajtá magát arczczal a föld felé, és tisztességet tőn néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'Sámuel pedig monda Saulnak: Miért háborgattál, hogy felidéztettél engemet? És felele Saul: Igen nagy szorultságban vagyok; a Filiszteusok hadakoznak ellenem, az Isten pedig eltávozék tőlem, és nem felel már nékem sem próféták által, sem álomlátás által; azért hívtalak téged, hogy megmondjad nékem, mit kelljen cselekednem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'És monda Sámuel: Ugyan miért kérdezel engemet, ha az Úr eltávozott tőled és ellenségeddé lőn?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'És a szerint cselekedett az Úr, a mint általam megmondotta vala: elvette az Úr a királyságot a te kezedből, és adta azt a te társadnak, Dávidnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, 'Mivel nem hallgattál az Úrnak szavára, és nem hajtottad végre az ő felgerjedt haragját az Amálekitákon: azért cselekszik most így veled az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'És az Úr Izráelt is veled együtt a Filiszteusok kezébe adja, te pedig holnap fiaiddal együtt velem leszesz. Izráelnek táborát is a Filiszteusok kezébe adja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'Akkor Saul a maga egész nagyságában hirtelen a földre esék, mert nagyon megrémüle Sámuel szavaitól; és semmi erő nem vala benne, mert egész nap és egész éjjel semmit sem evék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'Akkor az asszony Saulhoz ment, és mikor látta, hogy annyira megrémült, monda néki: Ímé a te szolgálóleányod hallgatott szavadra, és koczkára tettem életemet, és megfogadtam szavaidat, a melyeket mondottál nékem:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'Most azért hallgass te is szolgálóleányod szavára, hadd tegyek egy falat kenyeret elődbe, és egyél, hogy erőd legyen, mikor útra kelsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'Ő azonban vonakodék, és mondá: Nem eszem; de szolgái és az asszony is kényszeríték őt, és ő engedett szavoknak, felkelt a földről, és felüle az ágyra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, 'Vala pedig az asszony házánál egy hízott borjú, és sietve levágta azt; azután lisztet vett, és meggyúrta, és sütött kovásztalan pogácsát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'És vivé Saul elé és az ő szolgái elé, és evének; azután felkeltek és elmenének azon az éjszakán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, 'Akkor a Filiszteusok összegyűjték minden seregeiket Afeknél; Izráel pedig tábort jár vala a forrásnál, mely Jezréel mellett van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'És a Filiszteusok vezérei kivonulának, ki százzal, ki ezerrel, Dávid pedig és az ő emberei hátul menének Ákhissal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'És mondának a Filiszteusok vezérei: Mit akarnak ezek a zsidók? És monda Ákhis a Filiszteusok vezéreinek: Avagy nem ez-é Dávid, Saulnak, az Izráel királyának szolgája, a ki már napok óta, sőt évek óta nálam van, és nem találtam benne semmi rosszat attól a naptól fogva, hogy átjött, a mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'De megharaguvának ő reá a Filiszteusok vezérei, és mondának néki a Filiszteusok vezérei: Küldd vissza ezt az embert, hogy térjen vissza a helyére oda, a melyet rendeltél néki, és ne jőjjön el mi velünk a harczba, hogy ellenünk ne forduljon a harczban; mert ugyan mivel tehetné magát kedvesebbé ura előtt, hacsak nem ezeknek a vitézeknek fejeivel?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, 'Avagy nem ez-é Dávid, a kiről így énekelnek a körtánczban: Megverte Saul az ő ezerét, és Dávid is az ő tízezerét?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'Szólítá azért Ákhis Dávidot, és monda néki: Él az Úr, hogy te becsületes vagy, és kedves előttem mind kimenésed, mind bejövésed velem a táborba, mert semmi rosszat nem találtam benned attól a naptól fogva, hogy hozzám jöttél, e mai napig; de a vezérek előtt nem vagy kedves.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'Most azért térj vissza, és menj el békességben, és semmit se cselekedjél, a mi a Filiszteusok vezérei előtt helytelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'És monda Dávid Ákhisnak: Vajjon mit cselekedtem, és mit találtál a te szolgádban attól a naptól fogva, hogy nálad voltam, a mai napig, hogy ne menjek el, és ne harczoljak a királynak, az én uramnak ellenségei ellen?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'Ákhis pedig felele, és monda Dávidnak: Tudom; bizonyára kedves vagy előttem, mint az Istennek angyala; de a Filiszteusok vezérei mondák: El ne jőjjön velünk a harczba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'Azért kelj fel korán reggel uradnak szolgáival együtt, a kik veled eljövének; keljetek fel korán reggel, mihelyt megvirrad, és menjetek el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, 'Felkele azért Dávid embereivel együtt, hogy korán reggel elmenjen és visszatérjen a Filiszteusok földére. A Filiszteusok pedig felmenének Jezréelbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, 'És történt, hogy a mikor Dávid harmadnapon embereivel Siklágba megérkezék, ímé az Amálekiták betörének a déli vidékre és Siklágba, és leverték Siklágot, és felégették azt tűzzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, 'És fogságba hurczolák az asszonyokat, a kik benne valának, kicsinytől fogva nagyig; senkit sem öltek meg, hanem elhurczolták, és elmentek az ő útjokra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'Mikor azért Dávid embereivel együtt a városba érkezék; ímé az tűzzel felégettetett vala, feleségeik, fiaik és leányaik pedig fogságba hurczoltattak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'Akkor Dávid és a nép, a mely ő vele volt, felkiáltának és annyira sírának, hogy végre erejök sem volt a sírásra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'Dávidnak két felesége is fogságba hurczoltatott, a Jezréelből való Ahinoám és a Kármelből való Abigail, a Nábál felesége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, 'És Dávid igen nagy szorultságba juta, mert a nép arról beszélt, hogy megkövezi őt, mivel az egész nép lelke elkeseredett fiaik és leányaik miatt. Dávid azonban megerősíté magát az Úrban, az ő Istenében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'És monda Dávid Abjáthár papnak, az Akhimélek fiának: Hozd ide nékem az efódot. És Abjáthár oda vivé az efódot Dávidhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'És megkérdezé Dávid az Urat, mondván: Üldözzem-é ezt a sereget? Utólérem-é őket? És monda néki: Üldözzed, mert bizonyosan utóléred, és szabadulást szerzesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'Elméne azért Dávid, ő és az a hatszáz ember, a kik vele valának. És mikor a Bésor patakához jutának, ott a népnek egy része megállott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, 'Dávid azonban négyszáz emberrel tovább üldözé az ellenséget; kétszáz ember pedig ott megállott, mivel fáradtabbak valának, mintsem hogy a Bésor patakán átkelhettek volna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, 'És találának a mezőn egy égyiptomi embert, a kit Dávidhoz vivének, és adának néki kenyeret, hogy egyék, és megitatták őt vízzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'És adának néki egy csomó száraz fügét és két kötés aszuszőlőt; és miután evett, magához tért, mert három nap és három éjjel sem kenyeret nem evett, sem vizet nem ivott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'És monda néki Dávid: Ki embere vagy te, és honnan való vagy? Ő pedig monda: Égyiptomi ifjú vagyok, egy Amálekita embernek szolgája, és elhagyott engem az én uram, mivel megbetegedtem immár ma harmadnapja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, 'Mi törtünk be a Kréteusok déli vidékére, és oda, a mely Júdáé, és Kálebnek déli vidékére; és Siklágot felégettük tűzzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'És Dávid monda néki: Elvezetsz-é minket ahhoz a sereghez? És ő monda: Esküdjél meg nékem az Istenre, hogy nem ölsz meg engem, sem az én uramnak kezébe át nem adsz, és én elvezetlek téged ahhoz a sereghez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'Elvezeté azért őket; és ímé, azok elszéledének az egész vidéken, és evének, ivának és tánczolának az igen nagy zsákmány felett, a melyet a Filiszteusok tartományából és Júda tartományából hozának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'És vágta őket Dávid alkonyattól fogva másnap estvéig, és senki sem menekült meg közülök, hanem csak négyszáz ifjú ember, a kik tevékre ülének és elfutának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'És mindent megszabadított Dávid, valamit elvittek az Amálekiták; az ő két feleségét is megszabadítá Dávid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, 'És semmijök sem hiányzott, sem kicsiny, sem nagy, sem fiaik, sem leányaik, a zsákmányból sem és mindabból, a mit elvittek tőlük; Dávid mindent visszahozott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'És elvivé Dávid mind a juhokat és barmokat, melyeket tulajdon barmuk előtt hajtának, és azt mondják vala: Ez a Dávid zsákmánya!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'Midőn pedig Dávid ahhoz a kétszáz emberhez érkezék, a kik fáradtabbak valának, minthogy Dávidot követhették volna, és ott hagyta őket a Bésor patakjánál: kimenének Dávid elé és a nép elé, a mely vele volt. Dávid pedig a néphez közeledék, és köszönté őket békességgel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'Akkor mondának mind azok közül, a kik Dáviddal elmenének, így szólván: Minthogy mind a gonosz emberek és Béliál emberei nem jöttek el velünk, semmit se adjunk nékik a zsákmányból, a melyet visszaszereztünk, hanem csak kinek-kinek a maga feleségét és gyermekeit, azokat vigyék el, és menjenek el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'Dávid azonban így szóla: Ne cselekedjetek így, atyámfiai, azzal, a mit az Úr adott nékünk; ő oltalmazott minket és adá kezünkbe a sereget, a mely ellenünk jött vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, 'Vajjon kicsoda engedhetne néktek ebben a dologban? Sőt inkább, a mekkora annak a része, a ki elment a harczba, akkora legyen annak is a része, a ki a holminál marada; egyenlőképen osztozzanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'És úgy történt ez attól a naptól fogva azután is; törvénynyé és szokássá tette ezt Izráelben mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'Mikor pedig Dávid Siklágba érkezék, külde a zsákmányból Júda véneinek, az ő barátainak, mondván: Ímé az Úr ellenségeinek zsákmányából való ajándék számotokra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, 'Azoknak tudniillik, a kik Béthelben, a kik dél felé Rámóthban, és a kik Jathirban laknak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'A kik Aroerben, a kik Sifmótban és a kik Estemoában laknak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'A kik Rákálban, a kik a Jerakhméeliták városaiban és a kik a Kéneusok városaiban laknak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'A kik Hormában, a kik Kor-Asánban és a kik Athákban laknak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'A kik Hebronban és mindazon helyeken, a hol Dávid embereivel megfordult vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, 'És megütközének a Filiszteusok Izráellel, és elfutottak Izráel férfiai a Filiszteusok elől, és elhullának a seb miatt a Gilboa hegységén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'A Filiszteusok pedig utólérték Sault és az ő fiait, és megölték a Filiszteusok Jonathánt, Abinádábot és Málkisuát, a Saul fiait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, 'És a küzdelem igen heves lőn Saul ellen, mikor megtalálták őt a kézíves emberek, és igen megrettene a kézívesektől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'És mondá Saul az ő fegyverhordozójának: Húzd ki kardodat, és szúrj keresztül azzal engem, hogy valami módon reám ne jőjjenek e körülmetéletlenek, és keresztülszúrjanak engemet és gúnyt űzzenek belőlem. De fegyverhordozója nem akará, mert nagyon félt. Akkor Saul vevé a kardot és belébocsátkozék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, 'És fegyverhordozója a mint meglátta, hogy Saul meghalt, ő is belébocsátkozék az ő kardjába, és vele együtt meghala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'És meghala Saul és az ő három fia és fegyverhordozója, sőt emberei is mindnyájan egyenlőképen azon a napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'És mikor meglátták az Izráel férfiai, a kik a völgyön túl és a Jordánon túl laktak vala, hogy Izráel férfiai elfutottak, és hogy Saul és az ő fiai meghalának: elhagyták a városokat és elfutának. A Filiszteusok pedig eljövének és lakának azokban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, 'És történt másnap, mikor a Filiszteusok kimentek, hogy kirabolják az elesetteket, megtalálták Sault és az ő három fiát, a kik a Gilboa hegyén esének el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, 'És levágták fejét és fegyverzetét lehúzták, és elküldötték a Filiszteusok tartományába szerénszerte, hogy hírt mondanának bálványaiknak templomában és a nép között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'És fegyverzetét Astarot templomában helyezték el, testét pedig felfüggeszték Bethsán kerítésére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'Mikor pedig értesültek felőle Jábes-Gileád lakói, hogy mit cselekedtek a Filiszteusok Saullal:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, 'Felkelének mindnyájan a vitéz férfiak, és menének egész éjjel, és miután levették Saul testét és az ő fiainak testeit Bethsán kerítéséről, elmentek Jábesbe, és ott megégették őket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, 'Csontjaikat pedig felszedték, és eltemették a tamaris fa alatt Jábesben; és bőjtölének hét napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'És lőn Saul halála után, mikor Dávid visszatért az Amálekiták legyőzéséből, és Dávid két napig Siklágban időzött:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, 'Ímé a harmadik napon egy férfi jöve a táborból Saultól, és az ő ruhái megszaggatva valának, fején pedig föld vala; és a mikor Dávidhoz ért, leesék a földre, és meghajtá magát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'Monda pedig néki Dávid: Honnét jössz? Felele néki: Az Izráel táborából szaladék el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, 'Monda néki Dávid: Mondd meg kérlek nékem, mint lőn a dolog? Ő pedig felele: Megfutamodék a nép a harczból, és a nép közül nagy sokaság esett el, és meghalának. Sőt Saul is és Jonathán az ő fia meghalának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'Dávid pedig mondá az ifjúnak, ki néki ezt elbeszélé: Honnan tudod, hogy meghalt Saul és Jonathán az ő fia?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'Felele az ifjú, ki a hírt hozta: Történetből felmenék a Gilboa hegyére, és ímé Saul az ő dárdájára támaszkodott vala, és ímé a szekerek és lovagok utólérék őtet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, 'Hátratekintvén pedig Saul, megláta engem és szólíta, és mondék: Ímhol vagyok én.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'Monda pedig nékem: Ki vagy te? Felelék néki: Amálekita vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'Akkor monda nékem: Kérlek állj mellém és ölj meg engem, mert dermedtség fogott el engem, pedig a lélek még teljesen bennem van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, 'Annakokáért én mellé állván, megölém őtet, mert tudtam, hogy meg nem él, miután elesett, és elhozám a koronát, mely az ő fején vala, és az aranypereczet, mely az ő karján volt, és azokat ímé ide hoztam az én uramnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, 'Akkor megragadá Dávid a maga ruháit és megszaggatá, úgyszintén a többi emberek is, a kik ő vele valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, 'És nagy zokogással sírának, és bőjtölének mind estvéig, Saulon és Jonathánon, az ő fián, és az Úrnak népén és Izráelnek házán, mivelhogy fegyver által hullottak el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'És monda Dávid az ifjúnak, a ki ezt elbeszélé néki: Honnét való vagy te? Felele: Egy jövevény Amálekita férfi fia vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'Ismét monda néki Dávid: Hogy nem féltél felemelni kezedet az Úr felkentjének elvesztésére?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'És szólíta Dávid egyet az ő szolgái közül, kinek monda: Jőjj elő és öld meg őt. Ki általüté azt, és meghala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, 'És monda néki Dávid: A te véred legyen a te fejeden: mert a tennen nyelved vallása bizonyságot tesz ellened, mondván: Én öltem meg az Úrnak felkentjét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'És keservesen síra Dávid ilyen sírással, Saulon és Jonathánon, az ő fián,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, 'És monda (íjdal ez, hogy megtanulják Júda fiai, mely be van írva a Jásár könyvébe):');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, 'Izráel! a te ékességed elesett halmaidon: miként hullottak el a hősök!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, 'Meg ne mondjátok Gáthban, ne hirdessétek Askelon utczáin, hogy ne örvendjenek a Filiszteusok leányai, és ne ujjongjanak a körülmetéletlenek leányai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'Gilboa hegyei, se harmat, se eső ti reátok ne szálljon, és mezőtök ne teremjen semmi áldozatra valót; mert ott hányatott el az erős vitézek paizsa, Saulnak paizsa, mintha meg nem kenettetett volna olajjal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, 'A megöletteknek vérétől és a hősöknek kövérétől Jonathán kézíve hátra nem tért, és a Saul fegyvere hiába nem járt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'Sault és Jonathánt, a kik egymást szerették és kedvelték míg éltek, a halál sem szakította el; a saskeselyűknél gyorsabbak és az oroszlánoknál erősebbek valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'Izráel leányai! sirassátok Sault, ki karmazsinba öltöztetett gyönyörűen, és aranynyal ékesíté fel ruhátokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, 'Oh, hogy elhullottak a hősök a harczban! Jonathán halmaidon esett el!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, 'Sajnállak testvérem, Jonathán, kedves valál nékem nagyon, hozzám való szereteted csudálatra méltóbb volt az asszonyok szerelménél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, 'Oh, hogy elhullottak a hősök! És elvesztek a hadi szerszámok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, 'Ezek után lőn, hogy megkérdezé Dávid az Urat, mondván: Felmenjek-é Júdának valamelyik városába? Kinek felele az Úr: Menj fel. És monda Dávid: Hová menjek? Felele: Hebronba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'Felméne azért oda Dávid és az ő két felesége is, Ahinoám, a Jezréelből való, és Abigail, a Karmelből való, Nábál felesége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'És embereit is, a kik vele valának, felvivé Dávid, kit-kit a maga házanépével, és lakának Hebron városaiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, 'És eljövének Júda férfiai, és ott felkenék Dávidot királynak a Júda házán. Mikor pedig megjelentették Dávidnak, mondván: A Gileádból való Jábes emberei voltak azok, kik eltemették Sault;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'Követeket külde Dávid a Gileádból való Jábes embereihez, és ezt izené néki: Áldottak vagytok ti az Úrtól, kik ezt az irgalmasságot cselekedtétek a ti uratokkal, Saullal, hogy eltemettétek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'Annakokáért most az Úr cselekedjék veletek irgalmasságot és igazságot; sőt én is ezt a jót teszem veletek, hogy ezt cselekedtétek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'Most azért a ti kezeitek erősödjenek meg, és legyetek erős férfiak, mert megholt a ti uratok Saul, és immár engem felkent királynak Júda háza önmagán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, 'Abner pedig, a Nér fia, a ki Saulnak fővezére vala, felvevé Isbósetet, a Saul fiát, és elvivé Mahanáimba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'És királylyá tette őt Gileádon, Asuron és Jezréel városán, és az Efraim és Benjámin nemzetségein, és az egész Izráelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'Negyven esztendős vala Isbóset, Saul fia, mikor uralkodni kezde Izráelen, és két esztendeig uralkodék. Csak Júdának háza követé Dávidot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'Lőn pedig az időnek száma, míg Dávid király volt Hebronban Júdának házán, hét esztendő és hat hónap.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'És elméne Abner, a Nér fia, és Isbósetnek, a Saul fiának szolgái Mahanáimból Gibeonba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'Joáb is Sérujának fia, és a Dávid szolgái elmenvén, összetalálkozának azokkal a Gibeon halastavánál, és maradának ezek a halastón innét, amazok pedig a halastón túl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'Akkor monda Abner Joábnak: Nosza álljanak elő néhányan az ifjak, és viaskodjanak előttünk. És monda Joáb: Hát álljanak elő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'Felkelének azért és egyenlő számban általmenének a Benjámin nemzetéből és a Saul fiának, Isbósetnek seregéből tizenketten, és a Dávid szolgái közül is tizenketten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'És kiki az ő társának fejét megragadá, és fegyverét oldalába üté; és egyenlőképen mind elhullának; és nevezék azt a mezőt Helkáth-Hassurimnak, mely Gibeonban van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, 'És felette erős harcz lőn azon a napon, és megvereték Abner és az Izráel népe a Dávid szolgái által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, 'Három fia vala pedig ott Sérujának: Joáb, Abisai és Asáel; Asáel pedig könnyű lábú vala, mint egy vadkecske, mely a mezőn lakik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'És Asáel üldözé Abnert; és se jobbfelé, se balfelé nem tére ki Abner után való futásában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'Hátratekintvén pedig Abner, monda: Te vagy-é Asáel? Felele: Én vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'És monda néki Abner: Térj másfelé, vagy jobbkézre vagy balkézre, és fogj meg egyet az ifjak közül, és foszd ki őt mindenéből; de Asáel nem akarta őt elhagyni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'Ismét monda Abner Asáelnek: Menj el hátam mögül. Miért verjelek téged a földhöz? És micsoda orczával menjek Joábhoz, a te bátyádhoz?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, 'Mikor azért semmiképen nem akart eltérni, általüté őt Abner a dárda végével, az ötödik oldalcsontja között, és hátul jöve ki a dárda; és elesék azon a helyen, és ugyanott meghala. És lőn, hogy mindazok, a kik arra a helyre érkezének, a hol Asáel elesett és meghalt vala, megállának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'Joáb pedig és Abisai tovább üldözék Abnert; és midőn a nap lement, elérkezének az Amma halmára, mely Giah átellenében vala, a Gibeon pusztája melletti úton.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'Akkor egybegyülekezének az Abner után való Benjámin fiai, egy csoportot alkotva, és megállának egy halomnak tetején.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, 'És kiálta Abner Joábnak, és monda: Vajjon szűntelenül öldökölnie kell-é a fegyvernek? Nem tudod-é, hogy siralmas lesz ennek a vége? És meddig nem mondod a népnek, hogy térjenek vissza testvéreiknek hátukról?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'És monda Joáb: Él az Isten, hogy ha te nem szólottál volna, bizony már reggel eltávozott volna a nép, és nem kergette volna az ő atyjafiait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'Trombitát fuvata azért Joáb, és megálla az egész nép, és nem üldözék tovább Izráelt, és nem harczolának tovább.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'Abner pedig és az ő vitézei azon az egész éjszakán mennek vala a mezőségen, és általkelének a Jordánon, és az egész vidéket bejárván, jutának Mahanáimba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'Joáb pedig megtérvén Abner üldözéséből, összegyűjté az egész népet, és hiányozának Dávid szolgái közül tizenkilenczen és Asáel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'A Dávid szolgái pedig Benjámin nemzetéből, az Abner szolgái közül háromszázhatvan embert ölének meg, a kik meghalának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, 'És felvevén Asáelt, eltemeték őt atyjának sírboltjában, mely Bethlehemben vala. Joáb pedig és az ő vitézei egész éjjel menve, Hebronban virradának meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'Sok ideig tartó hadakozás lőn a Saul háznépe között és a Dávid háznépe között. Dávid pedig mind feljebb-feljebb emelkedik és erősbödik vala; a Saul háza pedig alább-alább száll és fogy vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'Fiai születének Dávidnak Hebronban, kik között elsőszülött vala Ammon, a Jezréelből való Ahinoámtól;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, 'A második pedig Kileáb, a Kármelbeli Nábál feleségétől, Abigailtól való, és a harmadik Absolon, a Máákha fia, a ki a Gessurbeli Thalmai király leánya vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, 'És a negyedik Adónia, Haggitnak fia, és az ötödik Sefátia, Abitál fia,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, 'A hatodik Ithreám, Eglától, Dávid feleségétől való: ezek születtek Dávidnak Hebronban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'Míg a hadakozás tartott a Saul házanépe és a Dávid házanépe között, Abner igen ragaszkodék a Saul házanépéhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, 'Vala pedig Saulnak egy ágyasa, kinek neve vala Rizpa, Ajának leánya; és monda Isbóset Abnernek: Miért mentél be az én atyámnak ágyasához?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'Felette igen megharaguvék azért Abner az Isbóset szaván, és monda: Ebfej vagyok-é én, ki Júdával tart? Én most nagy irgalmasságot cselekedtem a te atyádnak, Saulnak házával, az ő atyjafiaival és rokonságaival, és nem adtalak téged Dávidnak kezébe; és te mégis ez asszonynak vétkét reám fogod most.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, 'Úgy cselekedjék Isten Abnerrel most és ezután is, hogy a mint megesküdött az Úr Dávidnak, én is a szerint cselekeszem vele:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'Hogy elveszem a királyságot Saulnak házától, és megerősítem Dávidnak székét az Izráel és a Júda felett, Dántól fogva mind Bersebáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'És nem felelhete semmit erre Abnernek, mivelhogy igen fél vala tőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'Követeket külde azért Abner Dávidhoz maga helyett ilyen izenettel: Vajjon kié az ország? Azt mondván: Tégy frigyet velem, és ímé az én erőm is te melletted lesz, hogy az egész Izráelt hozzád hajtsam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, 'Kinek felele Dávid: Jó, én frigyet kötök veled. De mindazáltal egyet kérek tőled, mondván: Addig ne lássad az én arczomat, míg el nem hozod nékem Mikált, a Saul leányát, mikor ide akarsz jőni, hogy arczomat lássad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'És követeket külde Dávid Isbósethez, a Saul fiához, kik ezt mondják: Add vissza az én feleségemet, Mikált, kit én száz Filiszteus előbőrével jegyeztem el magamnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'Elkülde azért Isbóset, és elvéteté őt az ő férjétől Páltieltől, Láis fiától.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, 'És vele ment az ő férje is, sírva követvén őt Bahurimig; és ott mondá néki Abner: Eredj, menj vissza; és haza tére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, 'Annakutána Abner szóla az Izráel véneinek, mondván: Immár régtől fogva kivántátok Dávidot, hogy királyotok legyen néktek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'Azért most vigyétek véghez; mert az Úr szólott Dávidnak, ezt mondván: Az én szolgámnak, Dávidnak keze által szabadítom meg az én népemet Izráelt a Filiszteusok kezéből, és minden ellenségeinek kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'Azután szóla Abner a Benjámin nemzetségével is, és elméne Abner Dávidhoz is Hebronba, hogy megjelentse néki mindazt, a mi tetszenék Izráel népének és Benjámin egész nemzetségének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'Mikor pedig eljutott Abner Dávidhoz Hebronba és ő vele együtt húsz ember, megvendégelé Dávid Abnert és a vele volt embereket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'Ennekutána monda Abner Dávidnak: Felkelek és elmegyek, hogy az egész Izráelt ide gyűjtsem az én uram eleibe, a király eleibe, a kik frigyet kössenek te veled, és uralkodjál mindeneken úgy, a mint szívednek tetszik. És visszabocsátá Dávid Abnert, és elméne békével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, 'És ímé a Dávid szolgái és Joáb jőnek vala a táborból, és sok prédát hoznak magukkal, de Abner nem volt már Dávidnál Hebronban, mert elbocsátotta őt és békével elment vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'Joáb pedig és az egész sereg, mely ő vele vala, a mint megérkezének, értesíték Joábot e dolog felől, mondván: Ide jött Abner, Nérnek fia a királyhoz, és visszabocsátá őt, és békével hazatére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'Beméne azért Joáb a királyhoz és monda: Mit cselekedtél? Ímé Abner hozzád jött, miért bocsátád el őt, hogy elmenjen?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, 'Ismered-é Abnert, a Nér fiát? Csak azért jött volt ide, hogy megcsalhasson, és kikémlelje a te kijövésedet és bemenésedet, és megtudjon mindent, a mit te cselekszel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'És kimenvén Joáb Dávidtól, követeket külde Abner után, kik visszahozák őt a Sira kútjától; Dávid azonban nem tudja vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'Visszajövén Abner Hebronba, félreszólítá őt Joáb a kapu között, mintha titokban akarna vele beszélni, és általüté ott őt az ötödik oldalbordájánál, és meghala Asáelnek, a Joáb atyjafiának véréért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, 'Mely dolgot minekutána megtudott Dávid, monda: Ártatlan vagyok én és az én országom mindörökké az Úr előtt, Abnernek, a Nér fiának vérétől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, 'Szálljon ez Joábnak fejére, és az ő atyjának egész háznépére; és el ne fogyjon a Joáb házából a folyásos, a bélpoklos, a mankón járó, és a ki fegyver miatt vész el, és a kenyér nélkül szűkölködő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'Joáb pedig és Abisai, az ő atyjafia azért ölék meg Abnert, mivelhogy megölte vala az ő atyjokfiát, Asáelt Gibeonban a harczon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'Monda pedig Dávid Joábnak és mind az egész népnek, mely vele vala: Szaggassátok meg ruháitokat, és öltözzetek zsákba, és sírjatok Abner előtt! Dávid király pedig megy vala a koporsó után;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, 'És eltemeték Abnert Hebronban. Akkor felkiálta a király, és igen síra az Abner koporsója felett, és síra az egész nép is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, 'És a király gyászdalt szerezvén Abner felett, monda: Gaz halállal kelle kimulnia Abnernek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, 'A te kezeid nem voltak megkötve, sem lábaid békóba verve; de úgy vesztél el, mint álnok ember miatt szokott elveszni az ember! És siratá őt ismét az egész nép.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, 'Előjöve pedig mind az egész nép, hogy enni adjanak Dávidnak, mikor még a nap fenn vala, de megesküvék Dávid, ezt mondván: Úgy cselekedjék én velem az Isten most és ezután is, hogy míg a nap le nem megy, sem kenyeret, sem egyebet nem eszem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, 'Mely dolgot mikor az egész község megértett, igen tetszék nékik; valamint a többi dolga is, a mit a király cselekeszik vala, igen tetszék nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, 'És megértette azon a napon az egész nép és az egész Izráel, hogy nem a királytól volt, hogy Abnert, a Nér fiát megölték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, 'Monda pedig a király az ő szolgáinak: Nem tudjátok-é, hogy nagy fejedelem esett ma el az Izráelben?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, 'Én pedig ma erőtelen, noha felkent király vagyok; ezek pedig a Sérujának fiai hatalmasabbak nálamnál. De fizessen meg az Úr annak, a ki gonoszt cselekeszik, az ő gonoszsága szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'Mikor pedig meghallotta Saul fia, hogy meghalt Abner Hebronban, igen megfogyatkozék az ő ereje. Sőt az egész Izráel megrémüle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'Két fővezére volt a Saul fiának, egyiknek neve Bahana és a másiknak neve Rékáb, Rimmonnak fiai, ki Beerótból való vala, a Benjámin fiai közül; mert Beerót is a Benjámin városai közé számláltatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, 'Elfutottak vala pedig a Beerótbeliek Gittáimba, és lőnek ott jövevények mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'Jonathánnak pedig, a Saul fiának volt egy sánta fia (öt esztendős vala, mikor Jezréelből hír jött Saul és Jonathán felől, és felvevé őt a dajkája, hogy elszaladjon vele; lőn pedig, hogy mikor a dajka gyorsan futott, elesett, és megsántula), ennek neve vala Méfibóset.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'Elmenének azért a Beerótbeli Rimmonnak fiai, Rékáb és Bahana, és bemenének Isbósetnek házába, mikor a nap legmelegebb vala és ő déli álmát aluszsza vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'Bemenvén azért ezek a ház belsejébe, gabonát vive, általüték őt az ötödik oldalborda alatt; s Rékáb és az ő atyjafia, Bahana, elszaladának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, 'Mikor azért ezek a házba bementek, és ő hálószobájában az ágyán feküvék, megsebesítvén megölték őt, s fejét levágva, felvették az ő fejét, és egész éjjel mennek vala a sík mezőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'És elvivék Isbóset fejét Dávidhoz Hebronba, és mondának a királynak: Ímhol Isbósetnek, Saul fiának, a te ellenségednek feje; a ki üldözé a te lelkedet, és az Úr bosszút állott e mai napon az én uramért, a királyért, Saulon és az ő maradékán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'Felele pedig Dávid Rékábnak és Bahanának, az ő atyjafiának, a Beerótbeli Rimmon fiainak, és monda nékik: Él az Úr, ki az én életemet megszabadította minden nyomorúságból,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, 'Hogy én azt, a ki nékem hírt hozott vala, ezt mondván: Ímé meghalt Saul (és azt hitte, hogy azzal nékem örömet szerez), megragadván megöletém őt Siklágban, holott jutalmat kellett volna adnom néki hírmondásáért:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, 'Mennyivel inkább az istentelen embereket, kik ágyában, a maga házában ölték meg az igaz embert? Azért most vajjon ne kivánjam-é meg az ő vérét kezeitekből, hogy titeket eltöröljelek a földről?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'Parancsola azért Dávid az ő szolgáinak, hogy megöljék őket; és elvagdalák kezeiket és lábaikat; és felakaszták őket Hebronban, a halastó mellett. Isbósetnek pedig fejét felvevén, eltemeték az Abner sírboltjába, Hebronban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, 'Eljövének pedig Dávidhoz Hebronba Izráelnek minden nemzetségei, és szólának ilyenképen: Ímé mi a te csontodból és testedből valók vagyunk,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, 'Mert ennekelőtte is, mikor Saul uralkodott felettünk, te vezérelted ki s be Izráelt, és az Úr azt mondotta néked: Te legelteted az én népemet, az Izráelt, és te fejedelem leszel Izráel felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, 'Eljövének azért Izráelnek minden vénei a királyhoz Hebronba, és frigyet tőn velek Dávid király Hebronban az Úr előtt, és királylyá kenék Dávidot Izráel felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'Harmincz esztendős vala Dávid, mikor uralkodni kezde, és negyven esztendeig uralkodék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, 'Hebronban uralkodék a Júda nemzetségén hét esztendeig és hat hónapig; és Jeruzsálemben uralkodék harminczhárom esztendeig az egész Izráel és Júda nemzetségein.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, 'Felméne pedig a király és az ő népe Jeruzsálembe a Jebuzeusok ellen, kik azt a földet lakják vala, ők azonban azt mondák Dávidnak: Nem jössz ide be, hanem a sánták és vakok elűznek téged! melylyel azt jelenték: Nem jő ide be Dávid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, 'Bevevé mindazáltal Dávid a Sion várát, és az immár a Dávid városa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'Mert azt mondá Dávid ama napon: Mindenki, a ki vágja a Jebuzeusokat, menjen fel a csatornához és vágja ott a sántákat és a vakokat, a kiket gyűlöl a Dávid lelke. Ezért mondják: Vak és sánta ne menjen be a házba!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'És lakozék Dávid abban a várban, és nevezé azt Dávid városának; és megépíté Dávid köröskörül, Millótól fogva befelé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'Dávid pedig folytonosan emelkedék és növekedék, mert az Úr, a Seregeknek Istene vala ő vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'Követeket külde pedig Hirám, Tírusnak királya Dávidhoz, és czédrusfákat is, ácsmestereket és kőmíveseket, és építének házat Dávidnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'És belátta Dávid, hogy az Úr megerősítette őt az Izráel felett való királyságában, és hogy felmagasztalta az ő királyságát az ő népéért, Izráelért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'Vőn pedig még magának Dávid ágyasokat, és feleségeket Jeruzsálemből, minekutána Hebronból oda ment; és lőnek még Dávidnak fiai és leányai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'És ezek a nevei azoknak, a kik Jeruzsálemben születtek: Sammua, Sóbáb, Nátán, Salamon,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'Ibhár, Elisua, Néfeg, Jáfia,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'Elisáma, Eljada és Elifélet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, 'Mikor pedig a Filiszteusok meghallották, hogy királylyá kenték Dávidot az Izráelen; felkelének mind a Filiszteusok, hogy Dávidot megkeressék; melyet megértvén Dávid, aláméne az erősségbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'A Filiszteusok pedig elérkezének és elszéledének a Réfaim völgyében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'Megkérdé azért Dávid az Urat ilyen szóval: Elmenjek-é a Filiszteusok ellen? Kezembe adod-é őket? Felele az Úr Dávidnak: Menj el, mert kétség nélkül kezedbe adom a Filiszteusokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'Elérkezék azért Dávid Baál Perázimba, és megveré ott őket Dávid, és monda: Szétszórta az Úr ellenségimet előttem, mint a víz szokott eloszlani; azért nevezé azt a helyet Baál Perázimnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, 'És ott hagyák az ő bálványaikat, melyeket felszedének Dávid és az ő szolgái.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'Azután ismét feljövének a Filiszteusok, és elszéledének a Réfaim völgyében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'Megkérdé azért Dávid az Urat, ki ezt felelé: Ne menj most reájok; hanem kerülj a hátuk mögé és a szederfák ellenében támadd meg őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, 'És mikor a szederfák tetején indulásnak zaját fogod hallani, akkor indulj meg, mert akkor kimegy te előtted az Úr, hogy megverje a Filiszteusok táborát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, 'És úgy cselekedék Dávid, a mint megparancsolta vala néki az Úr: és vágta a Filiszteusokat Gibeától fogva, mind addig, míg Gézerbe mennél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, 'Összegyűjté ezek után Dávid az egész Izráelnek színét, harmincezer embert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'És felkelvén, elméne Dávid az egész néppel együtt, mely vele vala, Júdának városába, Bahalába, hogy elhozza onnét az Isten ládáját, mely Névről, a Seregek Urának nevéről neveztetik, ki ül a Kérubok között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'És tevék az Isten ládáját új szekérre, és elhozák azt Abinádábnak házától, mely vala a dombon, és Uzza és Ahió, Abinádáb fiai vezetik az új szekeret.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'Elvivék azért azt az Abinádáb házából, mely a dombon vala, az Isten ládájával, és Ahió a láda előtt megyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'Dávid pedig és az egész Izráel népe örvendeznek vala az Úr előtt, jegenyefából való minden szerszámokkal, hegedűkkel, lantokkal, dobokkal, sípokkal és czimbalmokkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, 'És mikor Nákonnak szérűjére jutának, kinyújtá Uzza az ő kezét az Isten ládájára, és megtartá azt; mert az ökrök félremozdították vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'Ennekokáért felgerjede az Úr haragja Uzza ellen, és megölé ott őt az Isten vakmerőségéért: és meghala ott az Isten ládája mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'És bosszankodék Dávid, hogy az Úr ilyen romlással rontotta meg Uzzát, és nevezé azt a helyet Péres Uzzának, mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, 'Megfélemlék azért Dávid azon a napon az Úrtól, és monda: Hogyan jőjjön az Úr ládája én hozzám?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'És nem akará Dávid magához vinni az Úrnak ládáját Dávidnak városába, hanem letéteté azt Dávid a Gitteus Obed Edom házánál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'És lőn az Úrnak ládája a Gitteus Obed Edom házánál három hónapig, és megáldá az Úr Obed Edomot és egész háznépét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'És megmondák Dávid királynak ilyen szóval: Megáldotta az Úr az Obed Edom házát és mindenét, a mije van, az Isten ládájáért. És elmenvén Dávid, elvivé az Isten ládáját az Obed Edom házától Dávid városába vígassággal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'Mikor pedig azok, a kik az Úr ládáját vitték, hat lépést mentek, áldozék ott egy ökröt és hízott borjút.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'Dávid pedig teljes erejéből tánczol vala az Úr előtt, és gyolcs efódot övedzett magára Dávid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'Dávid azért és Izráelnek egész háza felvivék az Úr ládáját énekléssel és trombitaszóval.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, 'Lőn pedig, hogy mikor az Úr ládája Dávid városába ért, Mikál, Saulnak leánya kinéz vala az ablakon, és látván, hogy Dávid király ugrál és tánczol az Úr előtt, megútálá őt szívében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, 'Mikor pedig bevitték az Úr ládáját, és elhelyezék azt az ő helyére a sátornak közepére, melyet számára Dávid felállíttatott: akkor áldozott Dávid egészen égőáldozatokat és hálaadó áldozatokat, az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'Mikor pedig elvégezte Dávid az egészen égőáldozatot, és a hálaadó áldozatot, megáldá a népet a Seregek Urának nevében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'És osztogattata Dávid mind az egész népnek, Izráel egész seregének, férfiaknak és asszonyoknak, mindenkinek egy-egy lepényt, egy-egy darab húst, és egy-egy kalácsot; és elméne mind az egész nép, kiki az ő házához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, 'Mikor pedig Dávid hazament, hogy megáldja az ő háznépét is: kijöve Mikál, a Saul leánya Dávid eleibe, és monda: Mily dicsőséges vala ma Izráel királya, ki az ő szolgáinak szolgálói előtt felfosztózott vala ma, mint a hogy egy esztelen szokott felfosztózni!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'És monda Dávid Mikálnak: Az Úr előtt, ki inkább engem választott, mint atyádat és az ő egész házanépét, hogy az Úr népének, Izráelnek fejedelme legyek, igen, az Úr előtt örvendezém.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, 'Sőt minél inkább megalázom magamat és minél alábbvaló leszek a magam szemei előtt: annál dicséretreméltóbb leszek a szolgálók előtt, a kikről te szólasz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, 'Ennekokáért Mikálnak, Saul leányának nem lőn soha gyermeke az ő halálának napjáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, 'Lőn pedig, hogy mikor a király az ő palotájában üle, és az Úr mindenfelől békességet adott néki minden ellenségeitől,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, 'Monda a király Nátán prófétának: Ímé lássad, én czédrusfából csinált palotában lakom, az Istennek ládája pedig a kárpitok között van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'És monda Nátán a királynak: Eredj, s valami a te szívedben van, vidd véghez, mert az Úr veled van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, 'Azonban lőn az Úr szava Nátánhoz azon éjjel, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, 'Menj el, és mondd meg az én szolgámnak, Dávidnak: Ezt mondja az Úr: Házat akarsz-é nékem építeni, hogy abban lakjam?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, 'Mert én nem laktam házban attól a naptól fogva, hogy kihoztam Izráel fiait Égyiptomból, mind e mai napig, hanem szüntelen sátorban és hajlékban jártam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, 'Valahol csak jártam Izráel fiai között, avagy szólottam-é csak egy szót is Izráel valamelyik nemzetségének, a kinek parancsoltam, hogy legeltesse az én népemet Izráelt, mondván: Miért nem építettetek nékem czédrusfából való házat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, 'Most azért ezt mondd meg az én szolgámnak, Dávidnak: Ezt mondja a Seregeknek Ura: Én hoztalak ki téged a kunyhóból, a juhok mögül, hogy légy fejedelem az én népem felett, az Izráel felett;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, 'És veled voltam mindenütt, valahová mentél, és kiirtottam minden ellenségeidet előtted; és nagy hírnevet szerzettem néked, mint a nagyoknak hírneve, a kik e földön vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, 'Helyet is szerzék az én népemnek Izráelnek, és ott elplántálám őt, és lakozék az ő helyében, és többé helyéből ki nem mozdíttatik, és nem fogják többé az álnokságnak fiai nyomorgatni őt, mint annakelőtte,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'Attól a naptól fogva, hogy bírákat rendeltem az én népem az Izráel felett. Békességet szereztem tehát néked minden ellenségeidtől. És megmondotta néked az Úr, hogy házat csinál néked az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, 'Mikor pedig a te napjaid betelnek, és elaluszol a te atyáiddal, feltámasztom utánad a te magodat, mely ágyékodból származik, és megerősítem az ő királyságát:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, 'Az fog házat építeni az én nevemnek, és megerősítem az ő királyságának trónját mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, 'Én leszek néki atyja, és ő lészen nékem fiam, a ki mikor gonoszul cselekszik, megfenyítem őt emberi veszszővel és emberek fiainak büntetésével;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'Mindazáltal irgalmasságomat nem vonom meg tőle, miképen megvonám Saultól, a kit kivágék előtted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, 'És állandó lészen a te házad, és a te országod mindörökké tiéd lészen, és a te trónod erős lészen mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'Mind e beszéd szerint, és mind e látás szerint szóla Nátán Dávidnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'Bemenvén azért Dávid király, leborula az Úr előtt, és monda: Micsoda vagyok én, Uram Isten! és micsoda az én házam népe, hogy engem ennyire elővittél?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, 'És ez még csekélynek tetszett néked, Uram Isten! hanem ímé szólasz a te szolgádnak háza felől messze időre valókat; és ez törvény az emberre nézve, Uram Isten!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'De mi szükség Dávidnak többet szólani néked, holott te jól ismered, Uram Isten, a te szolgádat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, 'A te igéretedért, és a te jóakaratod szerint cselekedted mindezeket a nagy dolgokat, hogy megjelentsd a te szolgádnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, 'Ennekokáért felmagasztaltattál, Uram Isten: mert senki sincs olyan, mint te, és rajtad kivül nincsen Isten, mind a szerint, a mint hallottuk a mi füleinkkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, 'Mert melyik nép olyan, mint a te néped, az Izráel, melyért elment volna az Isten, hogy megváltsa magának való népül, és magának nevet szerezzen, és érettetek oly nagyokat cselekedjék és országodért oly csudálatos dolgokat néped előtt, melyet megszabadítottál Égyiptomból, a pogányoktól és isteneiktől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, 'Mert megerősítetted magadnak a te népedet, az Izráelt, népedül mindörökké; és te voltál, Uram, nékik Istenök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'Most annakokáért, Uram Isten, a mit szóltál a te szolgád felől, és az ő háza felől, teljesítsd be mindörökké; és cselekedjél úgy, a mint szólottál;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, 'Hogy felmagasztaltassék a te neved mindörökké, ilyen szókkal: A Seregeknek Ura az Izráelnek Istene, és Dávidnak, a te szolgádnak háza legyen állandó te előtted!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, 'Mert megjelentetted a te szolgádnak fülébe, óh Seregeknek Ura és Izráelnek Istene, ezt mondván: Házat építek néked. Ezért készteté szolgádat az ő szíve, hogy ilyen könyörgéssel könyörögjön hozzád.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, 'Most azért, óh Uram Isten, (mert te vagy az Isten, és a te beszéded igazság, és te mondottad ezt a jót a te szolgád felől),');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, 'Legyen a te jóakaratodnak áldása a te szolgádnak házán, hogy legyen előtted mindörökké; mert te szólottál, Uram Isten, azért a te áldásoddal áldassék meg a te szolgádnak háza mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, 'Ezek után megveré Dávid a Filiszteusokat, és megalázá őket: és elfoglalá Dávid a Filiszteusok kezéből Méteg Ammát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'És megveré a Moábitákat is, és kötéllel méré meg őket, lefektetvén őket a földre; két kötéllel méré azokat, a kik megölendők, és egy teljes kötéllel azokat, a kik életben hagyandók valának; és a Moábiták Dávidnak adófizető szolgái lőnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'Megveré Dávid Hadadézert is, Réhóbnak fiát, Czóbának királyát, mikor elméne, hogy hatalmát kiterjessze az Eufrátes folyó vizéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'És foglyul ejtett Dávid közülök ezer és hétszáz lovagot, és húszezer gyalog embert; és inaikat elvagdaltatá Dávid minden szekeres lovaknak és csak száz szekérbe valót hagyott meg közülök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'Eljövének pedig a Siriabeliek Damaskusból, hogy megsegítsék Hadadézert, Czóbának királyát; és levága Dávid a Siriabeliek közül huszonkétezer férfit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'És helyeze Dávid állandó sereget a damaskusi Siriába; és a Siriabeliek Dávidnak adófizető szolgái lettek. És megoltalmazá az Úr Dávidot valahová megyen vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'És elvevé Dávid az arany paizsokat is, melyek Hadadézer szolgáin valának, és bevivé azokat Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'Hoza annakfelette Dávid király a Hadadézer városaiból, Bétákhból és Berótaiból felette igen sok rezet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, 'Mikor pedig meghallá Tói, Hamát királya, hogy megverte Dávid Hadadézernek minden seregeit;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'Küldé Tói Jórámot, az ő fiát Dávid királyhoz, hogy békességesen köszöntse őt, és áldja, hogy harczolt Hadadézer ellen és megverte őt (mert Hadadézer Tóival is hadakozik vala). És a Tói fia kezében aranyból, ezüstből és rézből való edények valának,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'Melyeket Dávid király az Úrnak szentele, azzal az ezüsttel és aranynyal együtt, a melyet az Úrnak szentele mind ama népektől, a kiket meghódoltatott;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, 'A Siriabeliektől, Moábitáktól, az Ammon fiaitól, a Filiszteusoktól, az Amálekitáktól és a Réhób fiától, Hadadézertől, Czóbának királyától nyert prédából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'És hírnevet szerze Dávid, a mikor visszatért, miután a Siriabelieket leverte a sós völgyben, tizennyolczezeret.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'Az Idumeusok közé is állandó sereget rendele, egész Idumeába állandó sereget rendele, és az Idumeusok mind Dávid szolgái lettek. És megoltalmazá az Úr Dávidot, valahová megyen vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'Uralkodék azért Dávid az egész Izráelen, és szolgáltat vala Dávid az egész nép között ítéletet és igazságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'Fővezére volt Joáb, Sérujának fia, Jósafát pedig, Ahiludnak fia, emlékíró vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'Sádók pedig, Akhitóbnak fia, és Akhimélek, Abjátárnak fia papok valának, és Sérája íródeák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'Benája Jéhójadának fia, a Kereteusok és Peleteusok előljárója, a Dávid fiai pedig fők valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, 'Monda pedig Dávid: Maradt-é még valaki a Saul házanépe közül, hogy irgalmasságot cselekedjem ő vele Jonathánért?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'Vala pedig Saul házából egy szolga, kinek neve vala Siba, kit Dávidhoz szólítának, és monda a király néki: Te vagy-é Siba? Felele: Én vagyok a te szolgád.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, 'Akkor monda a király: Maradt-é még valaki a Saul házanépe közül, hogy cselekedjem vele az Isten irgalmasságát? Felele Siba a királynak: Van még Jonathánnak egy fia, ki mind a két lábára sánta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, 'Monda néki a király: Hol van? És monda Siba a királynak: Ímé az Ammiel fiának, Mákirnak házában van Ló-Debárban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'Akkor elkülde Dávid király, és elhozatá őt a Mákirnak, az Ammiel fiának házából Ló-Debárból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'És mikor megérkezett Dávidhoz Méfibóset, Jonathánnak a Saul fiának fia, arczczal leborula, és tisztességet tőn néki; és monda Dávid: Méfibóset! ki felele: Ímhol a te szolgád.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'Monda néki Dávid: Ne félj; mert kétség nélkül irgalmasságot cselekeszem veled Jonathánért, a te atyádért; és visszaadom néked Saulnak, a te nagyatyádnak minden majorságát, és néked mindenkor asztalomnál lesz ételed.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'Akkor fejet hajta Méfibóset, és monda: Micsoda a te szolgád, hogy a holt ebre reá tekintettél, minemű én vagyok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, 'Szólítá azután a király Sibát, Saulnak szolgáját, és monda néki: Valamije volt Saulnak és egész háznépének, mindazokat a te urad fiának adtam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, 'A majorságnak azért te viseljed gondját, és a te fiaid és szolgáid, és beszolgáltassad, hogy legyen a te urad fiának kenyere, melylyel éljen. Méfibóset pedig, a te uradnak fia, az én asztalomnál eszik mindenkor. Vala pedig Sibának tizenöt fia és húsz szolgája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'Felele Siba a királynak: Valamit az én uram, a király parancsol nékem, szolgájának, a képen cselekeszik a te szolgád. És Méfibóset az én asztalomnál eszik, mint a király fiainak egyike.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'Vala pedig Méfibósetnek egy fiacskája, kinek neve Mika vala; a Siba házában lakozók pedig mindnyájan Méfibóset szolgái valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'Méfibóset tehát Jeruzsálemben lakozék, mert mindenkor a király asztalánál eszik vala; és ő mind a két lábára sánta vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, 'Lőn pedig azután, meghala az Ammon fiainak királya, és uralkodék helyette Hánon, az ő fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'És monda Dávid: Irgalmasságot teszek Hánonnal, Náhás fiával, miképen az ő atyja is velem irgalmasságot tett; és hozzá külde Dávid, hogy vigasztalja őt szolgái által atyja halála felől. Mikor Dávid szolgái Ammon fiainak földére érkezének:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'Mondának az Ammon fiainak vezérei Hánonnak, az ő uroknak: Vajjon becsüli-é Dávid ezzel előtted a te atyádat, hogy hozzád vigasztalókat küldött? Vajjon Dávid nem inkább azért küldötte-é hozzád szolgáit, hogy a várost megszemléljék és kikémleljék és teljesen elpusztítsák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, 'Elfogatá azért Hánon a Dávid szolgáit, és szakáloknak felét lenyiratá, és ruháikat félben elmetszeté az alfelekig, és elbocsátá őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, 'A mint ezt Dávidnak hírül hozták, eleikbe külde, (mert ezek az emberek igen meggyaláztattak) és ezt izené a király: Maradjatok Jerikhóban mindaddig, míg megnevekedik szakálotok; és úgy jőjjetek haza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'Látván pedig az Ammon fiai, hogy gyűlöltekké lettek Dávid előtt, követet küldének az Ammon fiai, és felfogadák Siriában a Béth-Réhóbbelieket és ugyancsak Siriában a Czóbeusokat, húszezer gyalogot, és Maakának királyát ezer emberrel, és a Tóbbelieket, tizenkétezer embert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'A mint ezt Dávid meghallá, elküldötte Joábot és a vitézeknek egész seregét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'Kivonulának az Ammon fiai is, és csatarendbe állottak a kapu bejárata előtt. A Siriabeli Czóbeusok, Réhóbbeliek, Tóbbeliek és Maaka magukban valának a mezőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'Látván pedig Joáb, hogy mind elől, mind hátul ellenség van ő ellene, kiválogatá az Izráel népének színét, és a Siriabeliek ellenében állítá fel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, 'A népnek maradékát az ő öcscsének, Abisainak vezetésére bízta, hogy felállítsa azt Ammon fiainak ellenében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'És monda: Ha erősebbek lesznek a Siriabeliek nálamnál, nékem segítségül légy. Ha pedig az Ammon fiai náladnál hatalmasabbak lesznek, elmegyek, hogy megsegítselek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, 'Légy erős és legyünk bátrak a mi nemzetségünkért és a mi Istenünknek városaiért; és az Úr cselekedjék úgy, a mint néki tetszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'Elérkezék azért Joáb és az ő vele való sereg a Siriabeliek ellen az ütközetre, és megfutamodának ő előtte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'Látván pedig az Ammon fiai, hogy megfutamodtak a Siriabeliek, megfutamodának ők is Abisai előtt, és beszaladának a városba; és megtére Joáb az Ammon fiaitól és méne Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'Mikor pedig látták a Siriabeliek, hogy megverettettek az Izráeliták által, ismét együvé gyülekezének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'És elkülde Hadadézer, és elhozatá a Siriabelieket, a kik a vizen túl valának, és jövének Helámba; és Sobák, Hadadézernek fővezére volt élükön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, 'Megizenék pedig Dávidnak, a ki egybegyűjté egész Izráelt, és általméne a Jordánon, és juta Hélámhoz: és sereget rendelének a Siriabeliek Dávid ellen, és megütközének vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'De a Siriabeliek megfutamodtak Izráel előtt, és levága Dávid a Siriabeliek közül hétszáz szekerest és negyvenezer lovagot, Sobákot is, a seregnek fővezérét megölé; és ugyanott meghala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'Mikor pedig látták mindazok a királyok, a kik Hadadézernek szolgái valának, hogy az Izráel által megverettek, békét kötöttek Izráellel és nékik szolgálának; és nem merének többé a Siriabeliek kijőni az Ammon fiainak segítségére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, 'Lőn pedig az esztendő fordulásakor, mikor a királyok hadba szoktak menni, elküldé Dávid Joábot és az ő szolgáit ő vele, és mind az egész Izráelt, hogy elveszessék az Ammon fiait, és megszállják Rabba városát; Dávid pedig Jeruzsálemben maradt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, 'És lőn estefelé, mikor felkelt Dávid az ő ágyából, és a királyi palota tetején sétála: láta a tetőről egy asszonyt fürdeni, ki igen szép termetű vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'És elkülde Dávid, és tudakozódék az asszony felől, és monda egy ember: Nemde nem ez-é Bethsabé, Eliámnak leánya, a Hitteus Uriás felesége?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'Akkor követeket külde Dávid, és elhozatá őt; ki beméne ő hozzá, és vele hála, mikor az ő tisztátalanságából megtisztult; és annakutána visszaméne az ő házához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'És fogada méhében az asszony, és elküldvén, megizené Dávidnak ilyen szóval: Teherbe estem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, 'Akkor Dávid izene Joábnak: Küldd haza hozzám a Hitteus Uriást; és elküldé Joáb Uriást Dávidhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'Mikor pedig eljutott Uriás ő hozzá, megkérdé őt Dávid Joábnak békessége felől, a népnek békessége felől és a harcz folyása felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'Ezután monda Dávid Uriásnak: Menj haza, és mosd meg lábaidat; kimenvén pedig Uriás a király házából, a király ajándékot külde utána.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, 'Uriás azonban lefeküvék a királyi palota bejárata előtt az ő urának minden szolgáival, és nem méne a maga házához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, 'És megjelenték Dávidnak, mondván: Nem ment le Uriás az ő házához. Akkor monda Dávid Uriásnak: Nemde nem útról jöttél-é? Miért nem mentél le a te házadhoz?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'Felele Uriás Dávidnak: Az Isten ládája, Izráel és Júda nemzetsége sátorokban laknak, és az én uram Joáb, és az én uramnak szolgái a nyilt mezőn táboroznak: hogy mennék én be az én házamba, hogy egyem és igyam és feleségemmel háljak? Úgy élj te és úgy éljen a te lelked, hogy nem mívelem azt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'Monda azért Dávid Uriásnak: Maradj itt ma is, és holnap elbocsátlak. Ott marada azért Uriás Jeruzsálemben az nap és más napra kelve is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'Ennekutána hivatá őt Dávid, és ő vele evék és ivék, és lerészegíté őt, és kiméne estve aludni az ő ágyára, az ő urának szolgáival együtt, de házához nem méne alá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, 'Megvirradván pedig, levelet íra Dávid Joábnak, melyet Uriástól küldött el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'Írá pedig a levélben, mondván: Állassátok Uriást legelől, a hol a harcz leghevesebb és háta mögül fussatok el, hogy megölettessék és meghaljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, 'Lőn azért, hogy mikor ostromlá Joáb a várost, állatá Uriást arra a helyre, a hol tudja vala, hogy erős vitézek vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, 'Kijövén azért a városbeli nép, megharczolának Joábbal, és elhullának egyesek a nép közül, Dávid szolgái közül, és a Hitteus Uriás is meghala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'Követet külde akkor Joáb, és megizené Dávidnak az ütközetnek egész lefolyását.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'És megparancsolá a követnek, mondván: Ha az ütközetnek egész lefolyását teljesen előadtad a királynak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, 'És ha a király haragra lobbanva azt mondja néked: Miért mentetek olyan közel a városhoz harczolni? Avagy nem tudtátok-é, hogy lelövöldöznek a kőfalról?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'Kicsoda ölte meg Abiméleket, a Jérubbóset fiát? Nemde nem egy asszony üté-é agyon a kőfalról egy malomkődarabbal és meghala Tébesben? Azért miért mentetek közel a kőfalhoz? Akkor mondd meg: A te szolgád a Hitteus Uriás is meghalt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, 'Elméne azért a követ, és mikor megérkezett, elbeszélé Dávidnak mindazt, a mivel megbízta volt őt Joáb.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, 'És monda a követ Dávidnak: Azok az emberek erőt vettek felettünk, és a mezőre kijöttek ellenünk, de mi visszaűztük őket a kapu bejáratáig;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, 'Azonban a kőfalról lövöldözének a nyilasok a te szolgáidra, és a király szolgái közül egyesek meghaltak; és a te szolgád, a Hitteus Uriás is meghalt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'Monda azért Dávid a követnek: Ezt mondjad Joábnak: Ne bánkódjál a miatt; mert a fegyver úgy megemészt egyet, mint mást. Fokozzad azért támadásodat a város ellen, hogy elpusztítsad azt. Így biztasd őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'Meghallá pedig Uriásnak felesége, hogy meghalt Uriás, az ő férje, és siratá az ő férjét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, 'És mikor a gyászolásnak ideje eltelt, érette külde Dávid és házába viteté őt és lőn néki felesége, és szüle néki egy fiat. De ez a dolog, a melyet Dávid cselekedett, nem tetszék az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'Elküldé azért az Úr Dávidhoz Nátán prófétát, ki bemenvén hozzá, monda néki: Két ember vala egy városban, egyik gazdag, a másik szegény.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, 'A gazdagnak felette sok juhai és ökrei valának;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'A szegénynek pedig semmije nem vala egyéb egy kis nőstény báránykájánál, a melyet vett és táplált vala, s felnevelkedett nála gyermekeivel együtt; saját falatjából evett és poharából ivott és keblén aludt, és néki olyan vala, mintegy leánya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, 'Mikor pedig utazó vendége érkezett a gazdagnak: sajnált az ő ökrei és juhai közül hozatni, hogy a vendégnek ételt készítsen belőle, a ki hozzá ment vala; hanem elvevé a szegénytől az ő bárányát, és azt főzeté meg a vendégnek, a ki hozzá ment.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'Akkor felgerjede Dávidnak haragja az ember ellen, és monda Nátánnak: Él az Úr, hogy halálnak fia az az ember, a ki azt cselekedte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, 'A bárányért pedig négy annyit kell adnia, mivelhogy ezt mívelte, és annak nem kedvezett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'És monda Nátán Dávidnak: Te vagy az az ember! Ezt mondja az Úr, Izráelnek Istene: Én kentelek fel téged, hogy király légy Izráel felett, és megszabadítottalak téged a Saul kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, 'És néked adtam a te urad házát, és a te uradnak feleségeit a te kebeledbe; ennek felette néked adtam Izráelnek és Júdának házát; és ha még ez kevés volt, ezt s ezt adtam volna néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, 'Miért vetetted meg az Úrnak beszédét, oly dolgot cselekedvén, mely útálatos ő előtte? A Hitteus Uriást fegyverrel ölted meg, és az ő feleségét magadnak vetted feleségül; magát pedig az Ammon fiainak fegyverével ölted meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, 'Most azért ne távozzék el a fegyver soha házadból, mivel megútáltál engem, és a Hitteus Uriás feleségét elvetted, hogy feleséged legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'Ezt mondja az Úr: Ímé én épen a saját házadból bocsátok reád csapásokat, és feleségeidet szemed láttára veszem el, és adom más felebarátodnak, és hál a te feleségeiddel fényes nappal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, 'Mert te titkon cselekedtél; de én az egész Izráel előtt és napvilágnál cselekeszem azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'Monda azért Dávid Nátánnak: Vétkeztem az Úr ellen! És monda Nátán Dávidnak: Az Úr is elvette a te bűnödet, nem fogsz meghalni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'Mindazáltal, mivel alkalmat adtál a gyalázásra az Úr ellenségeinek e dologban: a te fiad is, a ki lett néked, bizonynyal meghal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'Ezekután elméne Nátán az ő házához. És megveré az Úr a gyermeket, a kit az Uriás felesége szült vala Dávidnak; és megbetegedék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'És könyörge Dávid az Istennek a gyermekért, és bőjtöle is Dávid, és bemenvén, a földön feküvék éjjel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'Felkelének azért az ő házának vénei és menének ő hozzá, hogy felemeljék őt a földről: de nem akará, és nem is evék ő velek kenyeret.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, 'Hetednapra azért meghala a gyermek, és nem merik vala a Dávid szolgái néki megmondani, hogy meghalt a gyermek, mert ezt mondják vala: Ímé, még mikor a gyermek élt, szólottunk néki és meg sem hallotta szónkat; hogyan mondanánk meg néki, hogy meghalt a gyermek, hogy magának bajt szerezzen?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, 'Látván pedig Dávid, hogy az ő szolgái suttognak, eszébe vevé Dávid, hogy meghalt a gyermek, és monda Dávid az ő szolgáinak: Meghalt-é a gyermek? Azok mondának: Meghalt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, 'Felkelvén azért Dávid a földről, megmosdék és megkené magát és más ruhát vőn magára, és bemenvén az Úr házába, imádkozék. Azután beméne a maga házába, és kérésére kenyeret vivének eleibe, és evék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, 'Akkor mondának az ő szolgái néki: Mi dolog ez, a mit míveltél? Míg a gyermek élt, bőjtöltél és sírtál; most pedig, hogy meghalt a gyermek, felkelél és kenyeret ettél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'Monda ő: Míg a gyermek élt, addig bőjtöltem és sírtam; mert ezt mondottam: Ki tudja, talán az Úr könyörül rajtam, és megél a gyermek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'De most, hogy meghalt, vajjon miért bőjtölnék? Vajjon visszahozhatom-é azzal? Én megyek ő hozzá, de ő nem jő ide vissza én hozzám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'És megvigasztalá Dávid az ő feleségét, Bethsabét, és beméne hozzá, és vele hála. És ő szült fiat, és nevezé annak nevét Salamonnak, és az Úr szereté azt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, 'A mint megizente vala Nátán próféta által, ki nevezé az ő nevét Jedidjának, az Úrért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, 'Joáb pedig hadakozék az Ammon fiainak városa, Rabba ellen, és megvevé a királyi várost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'És követeket külde Dávidhoz Joáb ilyen követséggel: Hadakoztam Rabba ellen, és meg is vettem a városnak egyik részét, a hol a víz van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'Most azért gyűjtsd egybe a népnek maradékát, és szállj táborba a város ellen, foglald el azt, nehogy valamiképen, ha én foglalnám el, róla neveztessék az én nevem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, 'Egybegyűjté azért Dávid mind az egész népet, és aláméne Rabba ellen, és harczola ellene, és elfoglalá azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'És elvevé az ő királyuknak koronáját annak fejéről, melynek súlya egy tálentum arany volt, és drága kövekkel vala rakva, és lőn a Dávid fején, és a városból felette sok zsákmányt hozott el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'A népet pedig, mely benne vala, kihozatá; és némelyét fűrész, némelyét vasborona alá, némelyét fejsze alá vetteté; némelyeket mészkemenczén vitt által, és így cselekedék az Ammon fiainak minden városával. Haza méne azután Dávid és az egész nép Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, 'Lőn ennekutána, hogy Absolonnak, Dávid fiának igen szép huga vala, kinek neve Támár vala; és Amnon, a Dávid fia megszereté őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'Igen nagy gyötrelemben vala pedig Amnon, úgy hogy beteggé lett az ő hugáért, Támárért; mert szűz vala, és Amnon előtt lehetetlennek tünt fel, hogy rajta valamit elkövessen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, 'Vala azonban Amnonnak egy barátja, kinek Jonadáb vala neve, Simeának, Dávid testvérének fia; Jonadáb pedig igen eszes ember vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, 'Ki monda néki: Mi az oka, hogy te naponként soványodol, királynak fia? Nem mondhatnád-é meg nékem? És monda néki Amnon: Támárt, Absolon öcsémnek hugát igen szeretem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'És monda néki Jonadáb: Feküdj le ágyadba, és tedd betegnek magadat. És ha eljön atyád, hogy meglátogasson, mondd azt néki: Jőjjön ide, kérlek, Támár, az én hugom, hadd adjon ennem; és itt szemem előtt készítse el az ételt, hogy én is lássam, és az ő kezéből egyem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'Lefeküvék azért Amnon, és tetteté, mintha beteg volna; mikor azután eljött a király, hogy őt meglátogassa, monda Amnon a királynak: Kérlek, hadd jőjjön ide hozzám Támár hugom, hadd csináljon előttem egy pár bélest, és hadd egyem az ő kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, 'Elkülde azért Dávid a Támár házához, ezt izenvén: Eredj el mindjárt az Amnon bátyád házához, és készíts valami ennivalót néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'Beméne azért Támár az Amnon bátyja házába, ő pedig fekszik vala. És lisztet vévén, meggyúrá és bélest csinála ő előtte, és megfőzé a bélest.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, 'Előhozá annakutána a serpenyőt, és kitölté eleibe; de ő nem akara enni. És monda Amnon: Küldjetek ki mellőlem mindenkit; és kimenének mindnyájan előle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'Akkor monda Amnon Támárnak: Hozd be a kamarába az étket, hadd egyem kezedből; vevé azért Támár a bélest, melyet készített vala, és bevivé Amnon bátyjának az ágyasházba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'És eleibe vivé, hogy egyék, és megragadá őt, és monda néki: Jőjj, feküdj mellém, húgom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'Ő pedig monda néki: Ne, bátyám, engem meg ne ronts, mert nem szoktak így cselekedni Izráelben, ne kövess el ilyen gyalázatot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, 'És én, ugyan hová vigyem szégyenemet? Te pedig olyan leszel Izráelben, mint egy bolond. Azért kérlek, szólj a királynak, mert nem fog megtagadni engem tőled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, 'Ő azonban nem akart szavára hallgatni, hanem erősebb levén nála, erőt vett rajta, és vele feküvék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, 'És meggyűlölé őt Amnon felette igen, mert nagyobb lőn gyűlölete, melylyel gyűlölte őt, a szeretetnél, melylyel őt megszerette vala. És monda néki Amnon: Kelj fel, eredj dolgodra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'Ki felele néki: Ne kövess el nagyobb gonoszságot annál, a melyet rajtam véghezvittél, hogy elűzz engem. Ő azonban nem akart reá hallgatni,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, 'Hanem beszólítá szolgáját, a ki néki szolgál vala, és monda: Űzd ki őt gyorsan előlem, és zárd be az ajtót utána.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, 'Vala pedig ő rajta igen szép tarka szoknya, a milyenben a király leányai szoktak járni, míg szűzek valának. Kiűzé azért őt a szolga, és bezárá az ajtót utána.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'Hamut hinte azért Támár az ő fejére, és a tarka szoknyát, mely rajta volt, meghasogatá, kezét pedig fejére tevén, jajgatva jár vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, 'És monda néki a bátyja, Absolon: Talán Amnon bátyád volt veled? Azért hallgass most, hugom, mert atyádfia, ne bánkódjál azon felettébb. Lakozék azért Támár nagy árvaságban az ő bátyjának, Absolonnak házában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'Dávid király pedig hallván mindezeket, felette igen megharaguvék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'Nem szóla pedig semmit felőle Absolon Amnonnak, sem jót, sem gonoszt; mert igen gyűlöli vala Absolon Amnont, mivelhogy megszeplősítette az ő hugát, Támárt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, 'És lőn két esztendő mulva, mikor Absolonnak juhait nyírták Baál-Hásorban, mely Efraimban van, meghívá Absolon mind a király fiait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'Beméne Absolon a királyhoz is, és monda: Ímé most nyírják a te szolgádnak juhait, azért jőjjön el kérem a király és az ő szolgái a te szolgáddal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, 'Monda a király Absolonnak: Ne, fiam, ne menjünk el mindnyájan, hogy meg ne terheljünk téged. És ismét erőlteti vala őt, de nem akara elmenni, hanem megáldá őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'Monda mégis Absolon: Ha nem, úgy jőjjön el velünk Amnon, az én testvérem. Felele néki a király: Miért menne el veled?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'Mikor pedig erőltette őt Absolon, elbocsátá ő vele Amnont is és mind a király fiait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, 'Parancsola pedig Absolon az ő szolgáinak, ezt mondván: Kérlek, vigyázzatok, és mikor Amnon a bortól jókedvű lesz és mondom néktek: akkor üssétek le Amnont és öljétek meg őt, semmit ne féljetek, hiszen én parancsoltam néktek, legyetek bátrak, ne féljetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'Úgy cselekedének azért az Absolon szolgái Amnonnal, a mint Absolon parancsolta vala. A király fiai pedig mindnyájan felkelének, és ki-ki öszvérére üle, és elszaladának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, 'Mikor pedig még az útban voltak, a hír eljutott Dávidhoz, mondván: Mind megölte Absolon a király fiait, egy sem maradt meg közülök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, 'Akkor felkele a király, megszaggatá ruháit, és a földre feküvék, és az ő szolgái mindnyájan megszaggatott ruhában állanak vala előtte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'Szóla pedig Jonadáb, Simeának, a Dávid testvérének fia, és monda: Ne mondja azt az én uram, hogy a királynak minden fiait megölték, mert csak Amnon halt meg egyedül; mert attól a naptól fogva, hogy az ő hugát megszeplősítette, Absolonnak mindig szájában volt ez a dolog.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'Ne vegye azért szívére az én uram, a király, azt gondolván, hogy a királynak minden fiai meghaltak, mert csak Amnon halt meg egyedül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, 'Absolon pedig elmenekült. És felemelvén az őrálló az ő szemeit, látá, hogy sok ember jő az úton ő mögötte, a hegyoldalon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'És monda Jonadáb a királynak: Ímé jőnek a király fiai; a mint a te szolgád mondá, úgy történt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, 'És lőn, a mint megszünt beszélni, megérkezének a király fiai, és szavokat felemelvén, sírának; és maga a király is és az ő szolgái mindnyájan felette igen sírának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, 'Absolon pedig elfuta, és méne Talmaihoz, Ammihur fiához, Gessurnak királyához. És Dávid minden nap siratá az ő fiát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'Absolon pedig, minekutána elfutott és Gessurba ment, három esztendeig volt ott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, 'Dávid király pedig felhagyott azzal, hogy Absolon ellen menjen, mert megvigasztalódott Amnon felől, hogy meghalt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'Észrevévén Joáb, Sérujának fia, hogy a királynak szíve vágyakozik Absolon után,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'Elkülde Joáb Tékoa városába, és hozata onnét egy asszonyt, ki igen eszes vala, és monda néki: Kérlek tetessed, mintha nagy keserűséged volna, és öltözzél fel gyászruhába, és olajjal se kend meg magadat; és légy olyan, mint aféle asszony, ki sokáig siratta halottját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, 'És menj be a királyhoz, s így és így szólj hozzá. És Joáb szájába adta, hogy mit kelljen szólani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'Szóla azért a Tékoabeli asszony a királynak, minekutána arczczal a földre leborult, és térdet-fejet hajtott, és monda: Segíts meg, óh király!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, 'És monda néki a király: Mi bajod van? Felele az: Óh, én özvegyasszony vagyok, mert az én férjem meghalt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, 'És a te szolgálódnak két fia vala, kik összevesztek a mezőn, és mivel nem vala senki, a ki őket megvédte volna, az egyik megsérté a másikat és megölé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, 'És ímé az egész háznép ellene támadott a te szolgálóleányodnak, és ezt mondják: Add kezünkbe az ő testvérének gyilkosát, hadd öljük meg őt az ő testvérének lelkéért, a kit megölt, és veszessük el az örököst is. Így akarják eloltani a kicsiny szikrácskát, a mely nékem megmaradott, hogy az én férjemnek ne maradjon se neve, se maradéka a föld színén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, 'Monda azért a király az asszonynak: Menj el házadhoz, és parancsolok a te dolgod felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'Felele pedig a Tékoából való asszony a királynak: Uram király, én rajtam legyen a bűn súlya és az én atyámnak házán, de a király és az ő trónja ártatlan leszen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, 'Monda erre a király: A ki te ellened szól, hozd ide előmbe, és többé nem fog illetni téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, 'Akkor ő monda: Emlékezzék meg kérlek, a király az Úrról, a te Istenedről: hogy a vérbosszúló ne szaporítsa a pusztulást, és hogy az én fiamat ne veszessék el. Felele a király: Él az Úr, hogy a te fiadnak egy hajszála sem esik le a földre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, 'És monda az asszony: Kérlek, hadd szóljon a te szolgálód csak egy szót az én uramnak, a királynak; és ő monda: Szólj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, 'Akkor monda az asszony: Miért gondoltál ehhez hasonló dolgot az Isten népe ellen (mert mivel a király ezt a szót szólotta, mintegy maga is bűnös), hogy a király azt, a kit eltaszított magától, nem hívatja vissza?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, 'Mert bizonyára meg kell halnunk, és olyanok vagyunk, mint a víz, mely a földre kiöntetvén, fel nem szedhető, és az Isten egy lelket sem akar elvenni, hanem azt a gondolatot gondolja magában, hogy ne legyen számkivetve előtte az eltaszított sem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, 'Most annakokáért azért jöttem ide, hogy én szólnék a királynak, az én uramnak, noha sokan rettentettek engem ettől; mindazáltal azt mondotta a te szolgálód: Mégis beszélek a királylyal, hátha megteszi a király, a mit az ő szolgálóleánya mond.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, 'Igen, meghallgatja a király, és megszabadítja az ő szolgálóleányát annak kezéből, a ki engem el akar veszteni és velem együtt az én fiamat az Istennek örökségéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, 'Annakfelette ezt gondolta a te szolgálóleányod: Az én uramnak, a királynak beszéde szerezzen nyugodalmat, mert mint az Istennek angyala, olyan az én uram, a király, mivelhogy meghallgatja mind a jót, mind a gonoszt. És az Úr a te Istened legyen te veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, 'És felelvén a király, monda az asszonynak: Kérlek, ne tagadd meg, a mit tőled kérek. És monda az asszony: Mondja el az én uram, a király, kérlek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, 'És monda a király: Vajjon mindezekben nem a Joáb keze van-é veled? Felele az asszony, és monda: Él a te lelked, óh uram, király, hogy sem jobbra, sem balra nem lehet térni attól, a mit az én uram, a király szól; mert a te szolgád Joáb hagyta ezt nékem, és mindezeket a szókat ő adta a te szolgálóleányodnak szájába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, 'Hogy a dolognak más fordulatot adjon, azért tette ezt Joáb, a te szolgád. De az én uram bölcs, az Isten angyalának bölcsesége szerint, hogy mindent észrevegyen, a mi a földön van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, 'Akkor monda a király Joábnak: Ímé megteszem ezt a dolgot. Eredj el, és hozd haza az én fiamat, Absolont.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'És a földre arczczal leborula Joáb, és térdet-fejet hajtván, megköszöné a királynak, és monda Joáb: Ma ismerte meg, uram király, a te szolgád, hogy van valami becsületem előtted; mert az ő szolgájának beszédét megcselekedte a király.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'Felkele azért Joáb, és elméne Gessurba, és haza hozá Absolont Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, 'És monda a király: Menjen a maga házába, és az én színemet ne lássa. Tére azért Absolon az ő házába, és a királynak orczáját nem láthatá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, 'Nem vala pedig az egész Izráelben olyan szép ember, mint Absolon, ki dicséretre olyan méltó volna; tetőtől fogva talpig ő benne semmi hiba nem vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'És mikor a fejét megnyiratja (mert minden esztendőben megnyiratja vala, mivel igen nehéz volna, azért nyiratja le), az ő fejének haja nyom vala kétszáz siklust a királyi mérték szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'Lőn pedig Absolonnak három fia és egy leánya, kinek neve Támár vala; ez igen szép termetű asszony vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'Két esztendőt töltött immár Absolon Jeruzsálemben, de a királynak színét még nem látta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, 'Elkülde azért Absolon Joábhoz, hogy őt a királyhoz küldje, ki nem akara hozzá menni; és elkülde másodszor is, de ő még sem akart elmenni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'Monda azért az ő szolgáinak: Nézzétek, a Joáb gazdasága az enyém mellett van, és ott van az ő árpája: menjetek el, és gyújtsátok fel tűzzel; és meggyújták az Absolon szolgái a gazdaságot tűzzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'Felkele azért Joáb, és méne Absolonhoz az ő házába, és monda néki: Mi az oka, hogy a te szolgáid az én gazdaságomat felgyújtották tűzzel?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, 'Felele Absolon Joábnak: Azért mert hozzád küldöttem ily szóval, hogy ide jőjj, hogy a királyhoz küldjelek, hogy ezt mondjad néki: Mi szükség volt hazajőnöm Gessurból? Jobb volna most is nékem ott lennem. Most azért szeretném a király arczát látni; ha van bennem álnokság, ölessen meg engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'Elméne azért Joáb a királyhoz, és megmondá néki. És akkor hivatá a király Absolont, és elméne a királyhoz, és fejet hajtván a király előtt, arczczal a földre borula. És megcsókolá a király Absolont.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, 'Lőn pedig annakutána, szerze magának Absolon szekeret, lovakat és ötven embert, kik előtte szaladjanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'És reggelenként felkelvén Absolon, megálla az útfélen a kapuban, és mindenkit, a kinek dolga lévén, a királyhoz megy ítélet végett, megszólíta Absolon, és megkérdé: Micsoda városból való vagy te? És ha azt mondá: Izráelnek egyik nemzetségéből való a te szolgád;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'Monda néki Absolon: Ímé a te beszéded mind jó és mind igaz; de senki sincs, a ki téged meghallgatna a királynál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'Mondja vala ismét Absolon: Vajha valaki engem tenne ítélőbíróvá e földön, és én hozzám jőne minden ember, a kinek valami ügye és pere volna, igazat tennék néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'Mikor pedig valaki hozzá megy és fejet hajt vala néki, azonnal kezét nyujtja vala, és megfogván, megcsókolja vala őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'És e képen cselekedék Absolon egész Izráellel, valakik ítéletért a királyhoz mennek vala, és így Absolon az Izráel fiainak szíveket alattomban megnyeri vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, 'Lőn pedig negyven esztendő mulván, monda Absolon a királynak: Hadd menjek el, és teljesítsem Hebronban azt a fogadást, melyet fogadtam az Úrnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, 'Mert fogadást tett a te szolgád, mikor Gessurban laktam, mely Siriában van, ezt mondván: Ha valóban hazavezérel engem az Úr Jeruzsálembe, az Úrnak szolgálok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, 'Monda néki a király: Menj el békével; és felkelvén, elméne Hebronba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'Hírnököket külde pedig Absolon Izráelnek minden nemzetségéhez, hogy megmondják: Mikor a trombitaszót halljátok, azt mondjátok: Absolon uralkodik Hebronban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, 'És Absolonnal együtt kétszáz férfi is elméne Jeruzsálemből, kiket meghívott, kik jóhiszeműleg menének, semmit nem tudván a dologról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'És elküldvén Absolon, hivatá a Gilóból való Akhitófelt is, Dávidnak tanácsosát, az ő városából Gilóból, míg ő az áldozatot végezte. És igen nagy lőn az összeesküvés, és a nép gyülekezék és szaporodék Absolon mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, 'És követ méne Dávidhoz ilyen izenettel: Az Izráel népének szíve Absolon felé hajlik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'Akkor monda Dávid minden szolgáinak, kik vele valának Jeruzsálemben: Keljetek fel, és fussunk el, mert itt nincsen számunkra menekülés Absolon elől; siessetek elmenni, hogy valamikép sietve utól ne érjen minket, s ne hozzon szerencsétlenséget reánk, és a várost le ne vágja fegyvernek élével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, 'Mondának pedig a király szolgái a királynak: Minden úgy legyen, a mint tetszik a királynak, a mi urunknak, ímé itt vannak a te szolgáid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, 'Kiméne azért a király és egész háznépe ő utána, és otthon hagyá a király tíz ágyasát, hogy őrizzék a házat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, 'És kimenvén a király és egész háznépe ő utána, megállapodának a legszélső háznál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'És minden szolgái ő mellé menének; és a Kereteusok, a Peleteusok mind, a Gitteusok is mind, az a hatszáz férfi, kik vele jövének Gáthból, elvonulának a király előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, 'Monda pedig a király a Gitteus Ittainak: Miért jössz el te is mi velünk? Menj vissza, és maradj a királynál, mert te idegen vagy és vissza is költözhetel szülő helyedre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, 'Csak tegnap jöttél, és már ma zaklassalak téged, hogy velünk jőjj? Én megyek oda, a hova mehetek; te pedig térj vissza, és vidd vissza testvéredet is; irgalmasság és igazság legyen veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'És felele Ittai a királynak, mondván: Él az Úr és él az én uram, a király, hogy valahol lesz az én uram, a király, mind halálában, mind életében, ott lesz a te szolgád is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'Monda azért Dávid Ittainak: Ám jőjj el és menjünk el. És elméne a Gitteus Ittai és az ő emberei együtt, még a kicsinyek is, valakik vele valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, 'És az egész föld népe nagy jajgatással sír vala, mikor az egész nép elméne. A király azért általméne a Kedron patakán, és a nép mind átméne az útra, a puszta felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, 'És ímé vele vala Sádók is, és a Léviták mind, kik az Isten szövetségének ládáját hordozzák vala; és letevék az Isten ládáját. Azonközben Abjátár is felméne, míg a nép a városból mind kitakarodék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'És monda a király Sádóknak: Vidd vissza az Isten ládáját a városba, ha én az Úr előtt kedves leszek, engem ismét haza hoz, megmutatja nékem azt, és az ő sátorát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'Ha pedig azt mondja: Nem gyönyörködöm benned: Ímhol vagyok, cselekedjék velem úgy, a mint néki tetszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, 'Monda annakfelette a király Sádók papnak: Nemde nem próféta vagy-é te? Azért menj haza békességben a városba, Akhimás is, a te fiad, és az Abjátár fia, Jonathán, a ti két fiatok, veletek együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, 'Lássátok, ímé én itt időzöm, ennek a pusztának sík mezején, míg tőletek hír jő, és nékem izentek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'Visszavivék azért Sádók és Abjátár Jeruzsálembe az Isten ládáját, és otthon maradának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'Dávid pedig felméne az olajfáknak hegyén, mentében sírva, fejét beborítva, saru nélkül ment, és az egész nép, mely vele volt, kiki beborította fejét, és mentökben sírának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, 'Megizenék azonközben Dávidnak, hogy Akhitófel is a pártosok között van Absolonnal, és monda Dávid: Kérlek, óh Uram, hiúsítsd meg az Akhitófel tanácsát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'És a mint feljuta Dávid a hegy tetejére, hogy ott imádkozzék az Istennek, ímé eleibe jöve az Árkeából való Khúsai, ki ruháját megszaggatá és földet hinte fejére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'És monda néki Dávid: Ha eljösz velem, terhemre leszel nékem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'De ha a városba visszatérsz, és ezt mondod Absolonnak: Te szolgád vagyok, óh király; ennekelőtte a te atyád szolgája voltam, most immár a te szolgád leszek, megronthatod Akhitófelnek ellenem való tanácsát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, 'És ímé veled lesznek ott Sádók és Abjátár papok; azért minden dolgot, a mit hallándasz a király házából, mondj meg a papoknak, Sádóknak és Abjátárnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, 'Ímé ott van velök az ő két fiok is, Akhimás, a Sádók fia, és Jonathán, az Abjátár fia, kik által nékem mindjárt megizenhetitek, valamit hallotok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'Elméne azért Khúsai, a Dávid barátja a városba, Absolon pedig bevonula Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'Mikor pedig Dávid egy kevéssé alább ment a hegy tetejéről, eleibe jöve Siba, a Mefibóset szolgája, két megnyergelt szamárral, melyeken kétszáz kenyér és száz kötés aszúszőlő és száz csomó füge és egy tömlő bor vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, 'És monda a király Sibának: Mit akarsz ezzel? Felele Siba: A szamarak a király háznépéé legyenek, hogy rajtok járjanak; a kenyér pedig és a füge, hogy a szolgák megegyék, és a bor, hogy igyék, a ki megfárad a pusztában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, 'És monda a király: Hol van most a te uradnak fia? Felele Siba a királynak: Ímé Jeruzsálemben marada, mert azt mondja: Visszaadja ma nékem Izráel háznépe az én atyámnak országát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, 'És monda a király Sibának: Ímé minden tied legyen, valamije volt Mefibósetnek. Monda akkor Siba: Meghajtom magamat; vajha kegyelmet találnék előtted, óh uram király!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, 'Elméne azután Dávid király Bahurimig, és ímé onnan egy férfi jöve ki a Saul nemzetségéből való, kinek neve Sémei vala, Gérának fia, és kijövén szidalmazza vala őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, 'És kővel hajigálá Dávidot és Dávid királynak minden szolgáit, jóllehet az egész nép és az erős férfiak mindnyájan az ő jobb és balkeze felől valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'És így szóla Sémei szitkozódása közben: Eredj, eredj te vérszopó és istentelen ember!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, 'Megfizet most az Úr néked Saul egész házanépének véréért, a ki helyett te uralkodol; és adta az Úr az országot a te fiadnak, Absolonnak: és ímé te nyomorúságban vagy, mert vérszopó ember vagy!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'Monda pedig Abisai, Sérujának fia, a királynak: Hogyan szidalmazhatja ez a holt eb az én uramat, a királyt? Majd én elmegyek és fejét veszem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, 'Monda pedig a király: Mi közöm van veletek, Sérujának fiai? Hadd szidalmazzon, mert az Úr mondotta néki: Szidalmazzad Dávidot; és ki mondhatja néki: Miért míveled ezt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'És monda Dávid Abisainak és minden szolgáinak: Íme az én fiam, ki az én ágyékomból származott, kergeti az én életemet: hogyne cselekedné tehát e Benjáminita? Hagyjatok békét néki, hadd szidalmazzon; mert az Úr mondotta néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'Netalán reá tekint az Úr az én nyomorúságomra, és jóval fizet még ma nékem az Úr az ő átka helyett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, 'És megy vala Dávid és az ő népe az úton, Sémei pedig a hegyoldalon átellenében menvén, mentében átkozódik és köveket hajigál vala ő ellenébe, és port hány vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, 'Eljuta annakutána a király és az egész nép, mely vele vala, Ajefimbe, és ott megnyugovék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, 'Absolon pedig és az egész nép, Izráelnek férfiai, bemenének Jeruzsálembe, és Akhitófel is ő vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'Mikor pedig az Arkeából való Khúsai, a Dávid barátja bement Absolonhoz, monda Khúsai Absolonnak: Éljen a király, éljen a király!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'És monda Absolon Khúsainak: Ez-é a barátod iránti szereteted? Miért nem mentél el barátoddal?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, 'Felele Khúsai Absolonnak: Nem, hanem a kit az Úr és ez a nép választ, és az Izráelnek minden fiai: azé leszek és azzal maradok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, 'Azután ugyan kinek szolgálnék örömestebb, mint az én barátom fiának? A mint szolgáltam a te atyádnak, szintén olyan leszek te hozzád is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, 'Monda pedig Absolon Akhitófelnek: Adjatok tanácsot, mit cselekedjünk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'Felele Akhitófel Absolonnak: Menj be a te atyádnak ágyasaihoz, a kiket itthon hagyott, hogy őriznék a házat: és megérti az egész Izráel, hogy te atyád előtt gyűlöltté tetted magadat, és annál inkább megerősödnek mindazoknak kezeik, a kik melletted vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, 'Sátort vonának azért Absolonnak a tetőn, és beméne Absolon az ő atyjának ágyasaihoz, az egész Izráelnek szeme láttára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, 'És Akhitófel tanácsa, melyet adott, olyannak tekintetett abban az időben, mintha valaki az Isten szavát kérdezte volna; olyan volt Akhitófelnek minden tanácsa mind Dávid előtt, mind Absolon előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, 'Monda azért Akhitófel Absolonnak: Engedj kiválasztanom tizenkétezer embert, hogy felkeljek, és üldözzem Dávidot ez éjjel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, 'És megtámadom őt, míg fáradt és erőtlen kezű; megrettentem őt, és megfutamodik az egész nép, mely vele van; és a királyt magát megölöm.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, 'És visszavezetem te hozzád az egész népet, mert az egésznek visszatérése attól a férfiútól függ, a kit te üldözöl; és akkor az egész nép békességben lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, 'Igen tetszék e beszéd Absolonnak és Izráel minden véneinek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'És monda Absolon: Hívják ide mégis az Arkeabeli Khúsait is, és hallgassuk meg, mit szól ő is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'És mikor megérkezék Khúsai Absolonhoz, monda néki Absolon ilyenképen: Akhitófel ilyen tanácsot ád, megfogadjuk-é az ő szavát, vagy ne? Szólj hozzá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'Monda akkor Khúsai Absolonnak: Nem jó tanács az, a melyet Akhitófel ez egyszer adott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'És monda Khúsai: Tudod magad, hogy a te atyád és az ő emberei igen erős vitézek és igen elkeseredett szívűek, mint a kölykeitől megfosztott medve a mezőn. Annakfelette a te atyád igen hadakozó ember, ki nem alszik a néppel együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, 'Ilyenkor ő valami barlangban lappang, vagy valami más helyen, és meglehet, hogy mindjárt kezdetben elesvén némelyek közülök, valaki meghallja, és azt kezdi mondani: Megveretett az Absolon népe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'És még az erős vitéz is, kinek szíve olyan, mint az oroszlánnak szíve, igen megrémül; mert az egész Izráel tudja, hogy a te atyád igen erős vitéz, és azok is, a kik vele vannak, erős vitézek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, 'Én azért azt tanácsolom, hogy gyűjtsd magadhoz az egész Izráelt Dántól fogva mind Bersebáig, oly számban, mint a tenger partján való föveny; és magad is menj el a hadba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, 'Akkor aztán támadjuk meg őt azon a helyen, a hol található, és úgy lepjük meg őt, miként a harmat a földre esik, hogy se közüle, se azok közül, a kik vele vannak, egy se maradjon meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, 'Ha pedig városba szaladna, mind az egész Izráel köteleket húzzon a város körül, és vonjuk azt a patakba, hogy még csak egy kövecskét se találjanak ott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'És monda Absolon és Izráelnek minden férfia: Jobb az Arkeabeli Khúsainak tanácsa az Akhitófel tanácsánál. Az Úr parancsolta vala pedig, hogy az Akhitófel tanácsa elvettessék, mely jó vala, hogy veszedelmet hozzon az Úr Absolonra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, 'Monda pedig Khúsai Sádók és Abjátár papoknak: Ilyen s ilyen tanácsot adott Akhitófel Absolonnak és Izráel véneinek; én pedig ilyen s ilyen tanácsot adtam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'Azért sietve küldjetek el, és izenjétek meg Dávidnak ilyen szóval: Ne maradj ez éjjel a pusztának mezején, hanem inkább menj át, hogy valamiképen el ne nyelettessék a király és az egész nép, mely vele van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, 'Jonathán pedig és Akhimás a Rógel forrásánál állanak vala, a hová méne egy leányzó, ki megmondá ezeket nékik, és ők elmenvén, megmondák Dávid királynak, mert nem akarják vala magokat megmutatni, bemenvén a városba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'Meglátá mindazáltal őket egy szolga, és megmondá Absolonnak: Elmenének azért ők ketten sietséggel, és menének egy ember házába Bahurim városában, kinek tornáczában volt egy kút, és oda szállának alá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, 'Az asszony pedig egy terítőt vőn és beteríté a kút száját, arra pedig darált árpát hintett; és nem vevék észre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, 'Menének pedig az Absolon szolgái az asszonyhoz a házba, és mondának: Hol van Akhimás és Jonathán? Felele nékik az asszony: Általgázolának a patakon. És keresék őket, de mivel nem találták, visszatérének Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, 'Mikor pedig elmentek, kijövének a kútból, és elmenvén, megmondák ezeket Dávid királynak, és mondának Dávidnak: Keljetek fel és menjetek által gyorsan a vizen; mert ilyen tanácsot adott ti ellenetek Akhitófel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'Felkele azért Dávid és mind a vele való nép, és általkelének a Jordánon, míg megvirrada; egy sem hiányzék, a ki által nem ment volna a Jordánon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'Látván pedig Akhitófel, hogy az ő tanácsát nem hajtották végre: megnyergelé szamarát, és felkelvén elméne házához, az ő városába; és elrendezvén háznépének dolgát, megfojtá magát, és meghala; és eltemetteték az ő atyjának sírjába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, 'És midőn Dávid Mahanáimba érkezett, átkele Absolon a Jordánon, ő és Izráelnek férfiai mindnyájan ő vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'És Amasát tevé Absolon fővezérré a sereg felett Joáb helyett. Amasa pedig egy férfi fia vala, a kinek a neve az Izráelita Jithra vala, a ki beméne Abigailhoz, a Náhás leányához, ki Sérujának, a Joáb anyjának nővére vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'És tábort jára Izráel és Absolon a Gileád földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'Lőn pedig, hogy mikor Dávid Mahanáimba jutott, ímé Sóbi, az Ammoniták városából, Rabbából való Náhásnak fia, és a Ló-Debár városból való Ammielnek fia, Mákir, és a Gileád tartományában, Rógelimban lakozó Barzillai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, 'Ágyneműt, medenczéket és cserépedényeket, búzát, árpát, lisztet, pergelt búzát, babot, lencsét, pergelt árpát,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, 'Mézet, vajat, juhot, ünősajtokat hozának Dávidnak és az ő vele való népnek eleségül. Mert azt gondolják vala magokban: A nép éhes, fáradt és eltikkadt a pusztában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, 'Megszámlálá pedig Dávid a népet, a mely vele vala, s ezredeseket és századosokat rendele föléjök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'És hagyá Dávid a népnek harmadrészét Joáb keze alatt, és harmadrészét Séruja fiának, Abisainak, Joáb atyjafiának keze alatt, harmadrészét pedig bízá a Gitteus Ittai kezére. És monda a népnek a király: Bizony én magam is elmegyek veletek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'De a nép monda: Ne jőjj; mert ha netalán mi megfutamodunk is, velünk nem gondolnak, és ha felerészben meghalunk is, velünk semmit sem gondolnak; de te teszesz anynyit, mint mi tízezeren: jobb azért, hogy te a városból légy nékünk segítségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, 'Monda azért nékik a király: A mi néktek jónak tetszik, én azt mívelem. Megálla azért a király a kapuban, és az egész sereg megy vala ki százanként és ezerenként.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, 'Parancsola pedig a király Joábnak, Abisainak és Ittainak, mondván: Az én fiammal, Absolonnal én érettem kiméletesen bánjatok; hallá pedig ezt mind az egész had, mikor a király mindenik vezérnek parancsola Absolon felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, 'Kiméne azért a nép a mezőre, az Izráel ellenébe, és megütközének az Efraim erdejénél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'És megvereték ott az Izráel népe a Dávid szolgái által, és nagy veszteség volt ott azon a napon, mintegy húszezer emberé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'És kiterjedt a harcz az egész vidékre, és a nép közül sokkal többet emészte meg az erdő, mint a fegyver azon a napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, 'És találkozék Absolon Dávid szolgáival; Absolon pedig egy öszvéren ül vala. És beméne az öszvér a nagy cserfák sürű ágai alá, hol fennakadt fejénél fogva egy cserfán, függvén az ég és föld között, az öszvér pedig elszaladt alóla.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, 'Kit mikor egy ember meglátott, hírül adá Joábnak, és monda: Ímé, láttam Absolont egy cserfán függeni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'Monda pedig Joáb az embernek, a ki megmondotta vala néki: Ímé láttad, és miért nem ütötted le ott őt a földre? Az én dolgom lett volna azután, hogy megajándékozzalak tíz ezüst siklussal és egy övvel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, 'Monda az ember Joábnak: Ha mindjárt ezer ezüstpénzt adnál is kezembe, nem ölném meg a király fiát; mert a mi fülünk hallására parancsolá a király néked, Abisainak és Ittainak, ezt mondván: Kiméljétek, bárki legyen, az ifjút, Absolont.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, 'Vagy ha orozva törtem volna életére – mivel a király előtt semmi sem marad titokban – magad is ellenem támadtál volna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, 'Monda azért Joáb: Nem akarok előtted késedelmezni; és vőn három nyilat kezébe és Absolonnak szívébe lövé, minthogy még élt a cserfán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'Körülfogák akkor a Joáb fegyverhordozó szolgái tízen, és általverék Absolont, és megölék őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'Megfúvatá azután a trombitát Joáb, és megtére a nép Izráelnek űzéséből, mert kimélni akará Joáb a népet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, 'Absolont pedig felvevék, és veték őt az erdőn egy nagy verembe, és igen nagy rakás követ hányának reá. És az egész Izráel elmeneküle, kiki az ő sátorába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, 'Absolon pedig vett és még életében emelt magának emlékoszlopot, a mely a király völgyében van. Mert ezt mondja vala: Nincsen nékem oly fiam, a kin az én nevemnek emlékezete maradhatna; azért az oszlopot a maga nevére nevezé; és az Absolon oszlopának hívattatik mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, 'Monda pedig Akhimás, Sádók fia: Majd elfutok, és megmondom a királynak, hogy megszabadította őt az Úr az ő ellenségeinek kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, 'És monda néki Joáb: Ne légy ma hírmondó, hanem holnap mondd meg a hírt, ma pedig ne mondd meg; mivelhogy a király fia meghalt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'Monda azonközben Joáb Kúsinak: Eredj el, mondd meg a királynak, a mit láttál; és meghajtá magát Kúsi Joáb előtt, és elszaladt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'És szóla ismét Akhimás, Sádók fia, és monda Joábnak: Bármint legyen, hadd fussak el én is Kúsi után! Monda Joáb: Miért futnál fiam; nem néked való ez a hírmondás?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, 'Bármint legyen, hadd fussak el mégis! Ő pedig monda néki: Ám fuss el. Elfuta azért Akhimás a síkon való úton, és megelőzé Kúsit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, 'Dávid pedig ül vala a két kapu között, és az őrálló felméne a kapu tetejére, a kőfalra, és felemelvén szemeit, látá, hogy egy ember igen fut egyedül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, 'Kiálta azért az őrálló, és megmondá a királynak, és monda a király: Ha egyedül jő, hír van az ő szájában. Amaz pedig mind közelebb jöve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, 'Látá pedig az őrálló, hogy másik ember is fut, és lekiálta az őrálló a kapunállónak, mondván: Ímé más ember is fut egyedül. Akkor monda a király: Az is hírmondó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, 'Monda ismét az őrálló: A mint látom, az elsőnek olyan a futása, mint Akhimásnak, a Sádók fiának; és monda a király: Jó ember az, és jó hírrel jő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'Kiáltván azért Akhimás, monda a királynak: Békesség! És meghajtá magát arczczal a földre a király előtt, és monda: Áldott az Úr a te Istened, ki kezedbe adta az embereket, kik felemelték kezeiket az én uram ellen, a király ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, 'Monda akkor a király: Hogy van Absolon fiam? Felele Akhimás: Látám a nagy sereglést, mikor elküldé Joáb a király szolgáját és a te szolgádat; de nem tudom, mi történt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, 'És monda a király: Eredj tova, és állj meg ott; félreméne azért, és megálla ott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, 'E közben Kúsi is megérkezett, és monda Kúsi: Ezt izenik a királynak, az én uramnak, hogy az Úr megszabadított ma téged mindeneknek kezéből, a kik ellened támadtak volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, 'Monda a király Kúsinak: Hogy van Absolon fiam? Felele Kúsi: Úgy legyenek az én uramnak, a királynak minden ellenségei, és valakik te ellened gonoszul feltámadnak, mint a te fiad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 33, 'És megháborodék a király, és felméne a kapu felett való házba, és síra, és ezt mondja vala mentében: Szerelmes fiam, Absolon! édes fiam, édes fiam, Absolon! bár én haltam volna meg te helyetted, Absolon, édes fiam, szerelmes fiam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, 'És megjelenték Joábnak, hogy a király siratja és gyászolja Absolont.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, 'És gyászra fordult a szabadulás azon a napon az egész népre nézve, mert a nép azon a napon hallja vala, hogy beszélik: Így bánkódik a király az ő fián.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, 'És belopózkodék a nép azon a napon, bemenvén a városba, mint lopózkodni szokott a nép, mely szégyenli magát, hogy a harczból elmenekült.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, 'A király pedig eltakarván orczáját, fenszóval kiáltja vala a király: Édes fiam, Absolon! Absolon, édes fiam! szerelmes fiam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'Akkor méne Joáb a házba a királyhoz, és monda: Megszégyenítetted e mai napon minden te szolgáidnak orczáját, kik e mai napon a te lelkedet megszabadították, és a te fiaidnak és leányidnak lelkeit, és feleségidnek lelkeit, és ágyasidnak lelkeit;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, 'Szeretvén azokat, a kik téged gyűlölnek és gyűlölvén azokat, a kik téged szeretnek; mert kijelentetted ma, hogy előtted a vezérek és szolgák mind semmik; mert tapasztaltam ma, hogy csak élne Absolon, ha mi mindnyájan meghaltunk volna is ma, jobbnak tetszenék néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'Azért most kelj fel, menj ki, és szólj kedvök szerint a te szolgáidnak; mert esküszöm az Úrra, hogy ha ki nem jössz, ez éjjel egy ember sem marad melletted, és ez gonoszabb lesz reád nézve mindama nyomorúságnál, mely veled történt ifjúságodtól fogva, mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, 'Felkele azért a király és leüle a kapuban, és hírül adták az egész népnek, mondván: Ímé a király a kapuban ül. Akkor mind az egész nép eleibe jöve a királynak. Izráel pedig elmenekült, kiki az ő sátorába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'Mind az egész nép között pedig nagy veszekedés vala Izráelnek mindenik nemzetségében, kik ezt mondják vala: A király szabadított meg minket a mi ellenségeinknek kezéből, a Filiszteusok kezéből is ő szabadított meg; és most Absolon elől elmenekült az országból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'Absolon pedig, kit felkentünk vala, meghalt a hadban. Mit késtek azért hazahozni a királyt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'Dávid király pedig elkülde Sádók és Abjátár papokhoz, mondván: Szóljatok a júdabeli véneknek, ezt mondván: Mi az oka, hogy utolsók akartok lenni a királynak hazahozásában? Mert az egész Izráelnek szava eljutott a királynak házába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, 'Én atyámfiai vagytok, én csontom és én testem vagytok; miért lesztek tehát utolsók a királynak hazahozásában?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, 'És Amasának azt mondjátok: Nemde te is nem én csontom és testem vagy-é? Úgy cselekedjék velem az Isten és úgy segéljen, ha nem leszel a sereg fővezére minden időben én előttem Joáb helyett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'És megnyeré Júda minden emberének szívét, mint egy emberét, kik elküldének a királyhoz: Jőjj haza mind te, mind a te szolgáid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, 'Hazatére azért a király; és a mint a Jordánhoz érkezék, Júda férfiai Gilgálba menének, hogy a királynak eleibe jussanak, és általvigyék a királyt a Jordánon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, 'Siete pedig Sémei is, Gérának fia, a Bahurimból való Benjáminita, és ő is a Júda nemzetségével eleibe méne Dávid királynak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, 'És ezer ember vala ő vele Benjámin nemzetségéből, és Siba, a Saul házában való szolga, és tizenöt fia, és húsz szolgája is vele valának, és általmenének a Jordánon a király előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, 'Kompot is vivének által, hogy a király háznépét általhozzák, és hogy kedve szerint cselekedjenek. Sémei pedig Gérának fia, térdre esék a király előtt, mikor a Jordánon általment.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, 'És monda a királynak: Ne tulajdonítsa vétkül nékem az én uram az én álnokságomat; és ne emlékezzél meg arról, hogy gonoszul cselekedék veled a te szolgád azon a napon, a melyen az én uram, a király Jeruzsálemből kiméne, hogy szívére venné a király;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, 'Mert elismeri a te szolgád, hogy én vétkeztem, és ímé az egész József nemzetsége közül én jöttem ma először, hogy a királynak, az én uramnak eleibe menjek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, 'És felele Abisai, Sérujának fia és monda: Nem ölöd-é meg azért Sémeit, hogy káromlásokat szólott az Úrnak felkentje ellen?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'Monda pedig Dávid: Mi közöm van veletek, Sérujának fiai, hogy ellenkezni akartok velem ma? Ma kellene-é embert ölni Izráelben? Mintha nem tudnám, hogy ma lettem újonnan Izráel királya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, 'És monda a király Sémeinek: Nem halsz meg; és megesküvék néki a király.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, 'Méfibóset is, Saulnak fia eleibe jöve a királynak, és sem lábait, sem szakálát meg nem tisztította, sem ruháját meg nem mosatta attól a naptól fogva, hogy a király elment vala, mindama napig, a melyen békességgel haza jöve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, 'És lőn, hogy mikor Jeruzsálemből kijött eleibe a királynak, monda néki a király: Miért nem jöttél volt el velem Méfibóset?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, 'És ő felele: Uram király, az én szolgám csalt meg engem; mert azt mondotta a te szolgád: Megnyergeltetem a szamarat, és felülök rá, és elmegyek a királylyal; mert sánta a te szolgád.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'És rágalmazott engem, a te szolgádat az én uram, a király előtt; de az én uram, a király olyan, mint az Istennek angyala: azért cselekedjél úgy, a mint néked tetszik!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'Mert jóllehet az én atyámnak egész háznépe csak halált érdemlett volna az én uramtól, a királytól, mégis a te szolgádat azok közé helyezéd, a kik asztalodnál esznek. Azért micsoda követelésem és micsoda kérésem volna még a király előtt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, 'Monda néki akkor a király: Mi szükség többet szólnod? Én megmondottam, hogy te és Siba osztozzatok meg a jószágon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'És monda Méfibóset a királynak: Elveheti az egészet, csakhogy az én uram, a király békességben haza jöhete.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, 'A Gileádból való Barzillai is eljöve Rógelimból, és általméne a királylyal a Jordánon, kisérvén őt a Jordánon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'Barzillai pedig igen vén ember vala, nyolczvan esztendős, és ő táplálta vala a királyt, míg Mahanáimban lakott; mert igen gazdag ember vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, 'Monda pedig a király Barzillainak: Jere velem és eltartlak téged magamnál Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'Barzillai pedig monda a királynak: Mennyi az én életem esztendeinek napja, hogy én felmehetnék a királylyal Jeruzsálembe?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, 'Nyolczvan esztendős vagyok ma, avagy képes vagyok-é még különbséget tenni a jó és rossz között, vagy érzem-é, a te szolgád, ízét annak, a mit eszem és iszom, vagy gyönyörködhetem-é az éneklő férfiak és asszonyok hangjaiban? Miért lenne terhére a te szolgád az én uramnak, a királynak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, 'Egy kevés ideig óhajtana a Jordánon átmenni a királylyal a te szolgád; miért adna azért a király nékem ily nagy jutalmat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, 'Hadd menjen vissza, kérlek, a te szolgád, és hadd haljak meg az én városomban, az én atyámnak és anyámnak temetőhelyében. Hanem inkább ímhol a te szolgád, Kimhám, menjen el ő a királylyal, az én urammal, és cselekedjél úgy vele, a mint néked jónak tetszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, 'És monda a király: Jőjjön el velem Kimhám és azt cselekszem vele, a mi néked tetszik; és valamit tőlem kivánsz, megcselekeszem veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, 'Mikor pedig általkelt a Jordánon az egész nép, és a király is általment, megcsókolván a király Barzillait, megáldá őt, ki visszatére az ő helyére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'Általméne pedig a király Gilgálba, és Kimhám ő vele megy vala és Júdának egész népe, a kik a királyt átszállították, sőt Izráel népének is fele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, 'És ímé, Izráelnek minden férfiai eljövének a királyhoz és mondák a királynak: Miért loptak el téged a mi atyánkfiai, a Júda nemzetsége? És hozták által a királyt és az ő háznépét a Jordánon, és Dávidnak minden embereit vele egyetemben?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'Felelének pedig mindnyájan a Júda férfiai az Izráel férfiainak: Azért, mert a király közelebb áll hozzám; és miért neheztelsz ezért a dologért? Avagy megvendégelt-é azért a király? Avagy megajándékozott-é valami ajándékkal?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, 'Felelvén pedig az Izráel férfiai a Júda férfiainak, mondának: Tízszeres részem van nékem a királyhoz, és Dávidra nézve is elsőbbségem van feletted. Miért tartottál azért semminek engem? Avagy nem én tettem-é legelőször szóvá, hogy hozzuk haza a mi királyunkat? De mindazáltal erősebb lőn a Júda férfiainak szava, az Izráel férfiainak szavánál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, 'Vala pedig ott történetesen egy istentelen ember, kinek neve Séba vala, Bikrinek fia, Benjámin nemzetségéből való férfiú. Ez trombitát fuvata, és monda: Nincsen nékünk semmi közünk Dávidhoz, és semmi örökségünk nincsen az Isai fiában. Azért oh Izráel, oszoljatok el, kiki az ő sátorába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, 'Eltávozék azért mind az Izráel népe Dávidtól Séba után, Bikri fia után. A Júda nemzetségéből valók azonban mellette maradának az ő királyoknak, a Jordán vizétől fogva mind Jeruzsálemig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'Bemenvén pedig Dávid az ő házába Jeruzsálemben, előhozatá a király azt a tíz ágyasát, a kiket otthon hagyott vala a ház őrzésére; és őrizet alá rekeszté és tápláltatá azokat; de hozzájok be nem méne. És őrizet alatt lőnek haláloknak napjáig, özvegységben élvén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, 'Monda pedig a király Amasának: Gyűjtsd össze nékem a Júda nemzetségét három nap alatt, és magad is itt légy jelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'Elméne azért Amasa, hogy összegyűjtse Júdát, de több ideig késék, mint a hogy a király meghagyta vala néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, 'Monda akkor Dávid Abisainak: Ímé majd gonoszabbul cselekeszik velünk Séba, Bikrinek fia, Absolonnál: Vedd magad mellé a te uradnak szolgáit, és kergesd meg őt, nehogy erős városokat szerezzen magának, és elmeneküljön előlünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, 'Kimenének azért ő utána a Joáb emberei, és a Kereteusok és Peleteusok és az erősek mindnyájan, és kimenének Jeruzsálemből, hogy üldözzék Sébát, Bikrinek fiát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, 'Mikor pedig ama nagy kősziklánál voltak, mely Gibeonnál van, Amasa jöve eleikbe; Joáb pedig ruhájába öltözvén, az ő ruháján felül derekához övedzett fegyvere a hüvelyében vala, mely mikor Joáb ment, leesék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'És monda Joáb Amasának: Egészségben vagy-é atyámfia? És Joáb megfogá jobbkezével az Amasa szakálát, mintha meg akarná csókolni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'Amasa azonban nem őrizkedék a fegyvertől, mely Joáb kezében vala, és általüté őt az ötödik oldalborda alatt, és kiontá a bélit a földre, és noha többször nem üté által, mindazáltal meghala; Joáb pedig és Abisai, az ő atyjafia, üldözék azután Sébát, a Bikri fiát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, 'Megálla pedig az Amasa teste felett Joábnak egy szolgája, és monda: Valaki Joábbal tart és Dávidnak javát kívánja, Joáb után siessen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'Amasa pedig fetreng vala a vérben az útnak közepén; látván pedig egy ember, hogy ott mindenki megálla, kivoná Amasát az útról a mezőre, és ruhát vete ő reá; mivel látta, hogy valaki csak arra ment, mind megállott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'Minekutána pedig kivonták az útról, minden ember Joáb után siet vala, hogy üldözzék Sébát, Bikrinek fiát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, 'És általméne Séba Izráelnek minden nemzetségein, Abelán és Béth-Maakán, és egész Béreán, kik egybegyűlvén, követik vala őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'És eljövén, körülfogták őt Abelában Béth-Maaka városában, és nagy töltést emelének a város ellen, mely a kőfallal egyenlő volt; és az egész nép, mely Joábbal vala, rombolá, hogy ledöntse a kőfalat,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, 'Akkor kiálta egy eszes asszony a városból: Halljátok meg, halljátok meg! Mondjátok meg, kérlek, Joábnak: Jőjj ide hozzám, valamit mondok néked!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'Ki mikor hozzá ment, monda az asszony: Te vagy-é Joáb? Felele: Én vagyok. Ki monda néki: Hallgasd meg a te szolgálóleányodnak szavát. És felele: Meghallgatom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, 'Akkor monda az asszony: Korábban azt szokták mondani: Kérdezzék meg Abelát, és úgy végeztek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, 'Én Izráel békeszerető hívei közül való vagyok, te pedig el akarsz pusztítani egy várost és anyát Izráelben? Miért akarod elnyelni az Úrnak örökségét?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'Akkor felele Joáb, és monda: Távol legyen, távol legyen az én tőlem, hogy elnyeljem és elveszessem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, 'Nem úgy van a dolog, hanem egy ember az Efraim hegységéből való, a kinek neve Séba, a Bikri fia, felemelte kezét Dávid király ellen: adjátok kézbe azt egyedül, és elmegyek a város alól. És monda az asszony Joábnak: Ímé majd kivetjük a kőfalon a fejét néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'Elméne azért az asszony nagy eszesen az egész községhez, és elvágatá Sébának, a Bikri fiának fejét, és kiveték Joábnak. Akkor megfuvatá a trombitát, és hazaoszlának a város alól kiki az ő sátorába, Joáb pedig hazaméne Jeruzsálembe, a királyhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'Joáb pedig Izráel egész serege felett való volt, Benája pedig, Jójadának fia, a Kereteusok és Peleteusok vezére vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'Adorám pedig adószedő, és Jósafát, Ahiludnak fia, emlékíró vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'Séja íródeák, Sádók pedig és Abjátár papok valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, 'A Jairból való Ira is Dávidnak fő embere vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, 'Lőn pedig nagy éhség Dávidnak idejében három egész esztendeig egymás után, és megkeresé e miatt Dávid az Urat, és monda az Úr: Saulért és az ő vérszopó háznépéért van ez: mivelhogy megölte a Gibeonitákat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, 'Hivatá azért a király a Gibeonitákat és szóla nékik: (A Gibeoniták pedig nem az Izráel fiai közül valók valának, hanem az Emoreusok maradékából, a kiknek az Izráel fiai megesküdtek vala; Saul mindazáltal alkalmat keresett vala, hogy azokat levágassa az Izráel és Júda nemzetsége iránti buzgalmából).');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, 'És monda Dávid a Gibeonitáknak: Mit cselekedjem veletek, és mivel szerezzek engesztelést, hogy áldjátok az Úrnak örökségét?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'Felelének néki a Gibeoniták: Nincsen nékünk sem ezüstünk, sem aranyunk Saulnál és az ő házánál, és nem kell mi nékünk, hogy valaki megölettessék Izráelben. És monda: Valamit mondotok, megcselekszem veletek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, 'Akkor mondának a királynak: Annak az embernek a házából, a ki megemésztett minket, és a ki ellenünk gonoszt gondola, hogy megsemmisíttessünk, és meg ne maradhassunk Izráel egész határában;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, 'Adj nékünk hét embert az ő maradékai közül, a kiket felakaszszunk az Úr előtt, Saulnak, az Úr választottjának Gibeájában. És monda a király: Én átadom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'És kedveze a király Méfibósetnek, Jonathán fiának, ki Saul fia vala, az Úr nevére tett esküvésért, mely közöttök tétetett, Dávid és Jonathán között, a Saul fia között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'De elvevé a király Aja leányának, Rispának két fiát, kiket Saulnak szült vala, Armónit és Méfibósetet, és a Saul leányának, Mikálnak öt fiát, kiket szült Barzillai fiának, Adrielnek, a Méholátból valónak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'És adá azokat a Gibeoniták kezébe, a kik felakaszták őket a hegyen az Úr előtt. Ezek tehát egyszerre heten pusztulának el, és az aratás első napjaiban, az árpaaratás kezdetén ölettek meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'Vőn pedig Rispa, Ajának leánya egy zsákruhát, és kiteríté azt magának a kősziklán az aratás kezdetétől fogva, míg eső lőn reájok az égből: és nem engedé az égi madarakat azokra szállani nappal, sem pedig a mezei vadakat éjszaka.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, 'És megmondák Dávidnak, a mit Rispa, Ajának leánya, Saulnak ágyasa cselekedett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'Akkor elméne Dávid, és elhozá a Saul és Jonathán tetemeit a Jábes-Gileádbeliektől, kik ellopták vala azokat a Bethsánnak utczájáról, a hol őket a Filiszteusok felakasztották vala, mikor a Filiszteusok megverték Sault a Gilboa hegyén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'És elhozták onnét Saulnak és az ő fiának, Jonathánnak tetemeit, és összeszedték azoknak tetemeit is, a kik felakasztattak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'És eltemeték Saulnak és az ő fiának, Jonathánnak tetemeit a Benjámin földében, Sélában, az ő atyjának, Kisnek sírboltjában; és megtették mindazt, a mit a király parancsolt. És kiengesztelődött ez által Isten az ország iránt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'Ezután ismét háborút kezdének a Filiszteusok Izráel ellen; és elméne Dávid az ő szolgáival együtt, és harczolának a Filiszteusok ellen, annyira, hogy Dávid elfárada.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, 'Akkor Jisbi Bénób, ki az óriások maradékából való vala (kinek kopjavasa háromszáz rézsiklust nyomott, és új hadi szerszámmal volt felövezve), elhatározá magában, hogy megöli Dávidot;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'De Abisai, Sérujának fia segített néki és általüté a Filiszteust és megölé. Akkor esküvéssel fogadák néki a Dávid szolgái, ezt mondván: Soha többé velünk hadba nem jössz, hogy az Izráelnek szövétnekét el ne oltsad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, 'Lőn azután is harczuk a Filiszteusokkal Gób városánál, és Sibbékai, Husát városból való, akkor megölé Sáfot, ki az óriások maradékai közül való vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, 'Azután újra lőn háború a Filiszteusokkal Góbnál, hol Elkhanán, a Bethlehemből való Jaharé Oregimnek fia megölé a Gitteus Góliátot, kinek kopjanyele olyan vala, mint a szövőknek zugolyfája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, 'Gáthban is volt háború, hol egy óriás férfi vala, kinek kezein és lábain hat-hat ujjai valának, azaz mindenestől huszonnégy, és ez is óriástól származott vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, 'És szidalmazá Izráelt, de megölé Jonathán, Dávid bátyjának, Simeának fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, 'Ezek négyen származtak Gáthban az óriástól, kik mind Dávid keze által és az ő szolgáinak kezeik által estek el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, 'Dávid pedig ezt az éneket mondotta az Úrnak azon a napon, mikor az Úr megszabadítá őt minden ellenségeinek kezéből, és a Saul kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, 'És monda: Az Úr az én kősziklám és kőváram, és szabadítóm nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, 'Az Isten az én erősségem, ő benne bízom én. Paizsom nékem ő s idvességemnek szarva, erősségem és oltalmam. Az én idvezítőm, ki megszabadítasz az erőszakosságtól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, 'Az Úrhoz kiáltok, a ki dícséretreméltó; És megszabadulok ellenségeimtől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, 'Mert halál hullámai vettek engem körül, Az istentelenség árjai rettentettek engem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, 'A pokol kötelei vettek körül, S a halál tőrei estek reám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'Szükségemben az Urat hívtam, S az én Istenemhez kiáltottam: És meghallá lakóhelyéről szavamat, S kiáltásom eljutott füleibe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, 'Akkor rengett és remegett a föld, Az égnek fundamentumai inogtak, És megrendülének, mert haragudott Ő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, 'Füst szállt fel orrából, És emésztő tűz szájából, Izzószén gerjedt belőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, 'Lehajtá az eget és leszállt, És homály volt lábai alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'A Khérubon ment és röpült, És a szelek szárnyain tünt fel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, 'Sötétségből maga körül sátrakat emelt, Esőhullást, sürű felhőket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'Az előtte levő fényességből Izzó szenek gerjedének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'És dörgött az égből az Úr, És a Magasságos hangot adott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, 'Ellövé nyilait és szétszórta azokat, Villámot, és összekeverte azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'És meglátszottak a tenger örvényei, S a világ fundamentumai felszínre kerültek, Az Úrnak feddésétől, Orra leheletének fúvásától.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'Lenyúlt a magasságból és felvett engem, S a mélységes vizekből kihúzott engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'Hatalmas ellenségimtől megszabadított engem; Gyűlölőimtől, kik hatalmasabbak valának nálam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, 'Reámtörtek nyomorúságom napján, De az Úr gyámolóm volt nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, 'Tágas helyre vitt ki engem, Kiragadott, mert jóakaróm nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'Az Úr megfizetett nékem igazságom szerint, Kezeimnek tisztasága szerint fizetett meg nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, 'Mert megőriztem az Úrnak utait, S gonoszul nem szakadtam el Istenemtől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'Mert ítéletei mind előttem vannak, S rendeléseitől nem távoztam el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'Tökéletes voltam előtte, s őrizkedtem rosszaságomtól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, 'Ezért megfizet nékem az Úr igazságom szerint, Szemei előtt való tisztaságom szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, 'Az irgalmashoz irgalmas vagy, A tökéletes vitézhez tökéletes vagy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, 'A tisztához tiszta vagy, A visszáshoz pedig visszás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, 'Segítesz a nyomorult népen, Szemeiddel pedig megalázod a felfuvalkodottakat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'Mert te vagy az én szövétnekem, Uram, S az Úr megvilágosítja az én sötétségemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 'Mert veled harczi seregen is átfutok, Az én Istenemmel kőfalon is átugrom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, 'Az Istennek útja tökéletes; Az Úrnak beszéde tiszta; Paizsa ő mindeneknek, a kik ő benne bíznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, 'Mert kicsoda volna Isten az Úron kivül? S kicsoda kőszikla a mi Istenünkön kivül?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, 'Isten az én erős kőváram, Ki vezérli az igaznak útját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'Lábait olyanná teszi, mint a szarvasé, S magas helyekre állít engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, 'Kezeimet harczra tanítja, Hogy az érczív karjaim által törik el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, 'Idvességednek paizsát adtad nékem, S kegyelmed nagygyá tett engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, 'Lépéseimet kiszélesítetted alattam. És bokáim meg nem tántorodtak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'Üldözöm ellenségeimet és elpusztítom őket, Nem térek vissza, míg meg nem semmisítem őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'Megsemmisítem, eltiprom őket, hogy fel nem kelhetnek, Lábaim alatt hullanak el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, 'Mert te erővel öveztél fel engem a harczra, Lenyomtad azokat, kik ellenem támadtak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, 'Megadtad, hogy ellenségeim hátat fordítottak nékem, Gyülölőim, a kiket elpusztítottam én,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, 'Felnéztek, de nem volt, ki megszabadítsa, Az Úrhoz, de nem felelt nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, 'Szétmorzsolom őket, mint a föld porát, Összezúzom, mint az utcza sarát, széttaposom őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, 'Megmentettél népemnek pártoskodásaitól, Népeknek fejéül tartasz fenn engemet, Oly nép szolgál nékem, melyet nem ismertem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, 'Idegen fiak hizelkednek nékem, S egy hallásra engedelmeskednek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, 'Idegen fiak elcsüggednek, S váraikból reszketve jőnek elő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'Él az Úr és áldott az én kősziklám. Magasztaltassék az Isten, idvességem kősziklája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, 'Isten az, ki bosszút áll értem, S alám hajtja a népeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, 'Ki megment engem ellenségeimtől, Te magasztalsz fel engem az ellenem támadók fölött, S az erőszakos embertől megszabadítasz engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, 'Dícsérlek azért téged, Uram, a pogányok között, S nevednek dícséretet éneklek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, 'Nagy segítséget ad az ő királyának, Irgalmasságot cselekszik felkentjével, Dáviddal és az ő magvával mindörökké!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, 'Ezek Dávidnak utolsó beszédei. Dávidnak, Isai fiának szózata, annak a férfiúnak szózata, a ki igen felmagasztaltaték, Jákób Istenének felkentje és Izráel dalainak kedvencze.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, 'Az Úrnak lelke szólott én bennem, és az ő beszéde az én nyelvem által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'Izráelnek Istene szólott, Izráelnek kősziklája mondá nékem: A ki igazságosan uralkodik az emberek felett, a ki Isten félelmével uralkodik:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, 'Olyan az, mint a reggeli világosság, mikor a nap feljő, mint a felhőtlen reggel; napsugártól, esőtől sarjadzik a fű a földből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'Avagy nem ilyen-é az én házam Isten előtt? Mert örökkévaló szövetséget kötött velem, mindennel ellátva és állandót. Mert az én teljes idvességemet és minden kivánságomat nem sarjadoztatja-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'De az istentelenek mindnyájan olyanok, mint a kitépett tövis, melyhez kézzel nem nyúlnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, 'Hanem a ki hozzá akar nyúlni is, fejszét és rudat vesz hozzá, hogy ugyanazon helyen tűzzel égettessék meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, 'Ezek pedig a Dávid erős vitézeinek nevei: Joseb-Bassebet, a Tahkemonita, a ki a testőrök vezére; ő dárdáját forgatván, egy ízben nyolczszázat sebesített meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, 'Ő utána volt Eleázár, Dódónak fia, ki Ahóhi fia vala; ő egyike a három hősnek, a kik Dáviddal valának, mikor a Filiszteusok által kigúnyoltatának, összegyülekezvén ott a harczra, és az Izráeliták megfutamodtak volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'Ő megállván, vágta a Filiszteusokat mindaddig, míg a keze elfáradt, és a keze a fegyverhez ragadt. És nagy szabadulást szerze az Úr azon a napon, a nép pedig visszatére ő utána, de csak a fosztogatásra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, 'Ő utána volt Samma, a Harárból való Agénak fia. És összegyűlének a Filiszteusok egy seregbe ott, a hol egy darab szántóföld volt tele lencsével, a nép pedig elfutott a Filiszteusok elől:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, 'Akkor ő megálla annak a darab földnek közepén, és megoltalmazá azt, és megveré a Filiszteusokat, és az Úr nagy szabadítást szerze.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, 'A harmincz vezér közül is hárman lementek, és elérkezének aratáskor Dávidhoz az Adullám barlangjába, mikor a Filiszteusok táborban valának a Réfaim völgyében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, 'Dávid akkor a sziklavárban volt, a Filiszteusok őrsége pedig Bethlehemnél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'Vizet kivánt vala pedig Dávid, és monda: Kicsoda hozna nékem vizet innom a bethlehemi kútból, mely a kapu előtt van?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, 'Akkor a három vitéz keresztül tört a Filiszteusok táborán, és merítének vizet a bethlehemi kútból, mely a kapu előtt van, és elhozván, vivék Dávidnak. Ő azonban nem akará meginni, hanem kiönté azt az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'És monda: Távol legyen tőlem, Uram, hogy én ezt míveljem: avagy azoknak az embereknek vérét igyam-é meg, kik életöket halálra adva mentek el a vízért? És nem akará azt meginni. Ezt mívelte a három hős.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'Továbbá Abisai, Joábnak atyjafia, Sérujának fia, a ki e háromnak feje volt, a ki háromszáz ellen felemelvén dárdáját, megölé azokat; és néki nagy híre vala a három között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, 'A három között bizonyára híres volt és azoknak vezére vala, mindazáltal ama hárommal nem ért fel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'Benája is, Jójadának fia, vitéz ember, nagytehetségű, a ki Kabséelből való vala; ez ölé meg a Moábitáknak két fővitézét. Ugyanő elmenvén, az oroszlánt is megölé a veremben, télen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, 'Ugyanő ölt meg egy Égyiptomból való tekintélyes embert. Az égyiptomi kezében dárda vala, és ő csak egy pálczával méne reá; és kivevé az égyiptomi kezéből a dárdát, és megölé őt a maga dárdájával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'Ezeket cselekedé Benája, Jójadának fia, és néki is jó híre vala a három erős vitéz között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, 'Híres volt ő a harmincz között, mindazáltal ama hárommal nem ért fel. És előljáróvá tevé őt Dávid a tanácsosok között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, 'Asáel is, Joáb atyjafia, e harmincz közül való, kik ezek: Elkhanán, a bethlehemi Dódónak fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'Haród városbeli Samma; azon Haródból való Elika.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'Héles, Páltiból való; Híra, a Thékoából való Ikkes fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'Abiézer, Anathóthból; Mébunnai, Húsáthból való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'Sálmon, Ahóhitból való; Maharai, Nétofátból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'Héleb, Bahanának fia, Nétofátból való; Ittai, Ribainak fia, Gibeából való, mely Benjámin fiaié.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'Benája, Piráthonból való; Hiddai, a patak mellett való Gáhasbeli.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'Abiálbon, Árbátból való; Azmávet, Bárhumból való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'Eljáhba, Sahalbomból való; Jásen fia, Jonathán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'Samma, Harárból való; Ahiám, Arárból való Sarárnak fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'Elifélet, Ahásbainak fia, Maakátból való; Eliám, Gilóbeli Akhitófelnek fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'Hesrai, Kármelből való; Paharai, Arbiból való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'Jigeál, Sobabeli Nátánnak fia; Báni, Gádból való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'Sélek, Ammonita; Naharai, Beerótból való, Joábnak, a Séruja fiának fegyverhordozója.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'Ira, Jithriből való; Gáreb, Jithriből való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'Hitteus Uriás. Mindössze harminczheten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, 'Ismét felgerjede az Úrnak haragja Izráel ellen, és felingerlé Dávidot ő ellenek, ezt mondván: Eredj el, számláld meg Izráelt és Júdát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, 'Monda azért Dávid Joábnak, az ő serege fővezérének: Menj el, járd be Izráelnek minden nemzetségeit, Dántól fogva Beersebáig, és számláljátok meg a népet, hogy tudjam a népnek számát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'És monda Joáb a királynak: Sokasítsa meg az Úr, a te Istened a népet, s adjon még százannyit, mint a mennyi most van, és lássák azt az én uramnak, a királynak szemei: de miért akarja ezt az én uram, a király?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'Azonban hatalmasabb volt a királynak szava a Joábénál és a többi főemberekénél. Kiméne azért Joáb és a többi vezérek a király elől, hogy megszámlálják a népet, az Izráelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'És általkelének a Jordánon és tábort járának Aroer város mellett jobbkéz felől, Gád völgyében, és Jáser mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'Azután menének Gileádba, és a Hodsi alföldére. Innét menének a Dán Jáán mellé, és Sídon környékére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'Ezután menének a Tírus erős városához, és a Hivveusoknak és Kananeusoknak minden városaiba. Innét menének a Júdának dél felől való részére, Beersebába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, 'És mikor bejárták az egész országot, hazamenének Jeruzsálembe, kilencz hónap és húsz nap mulva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'És beadá Joáb a megszámlált népnek számát a királynak; és Izráelben nyolczszázezer erős fegyverfogható férfi, és Júda nemzetségében ötszázezer férfiú vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'Minekutána pedig Dávid a népet megszámlálta, megsebhedék az ő szíve, és monda Dávid az Úrnak: Igen vétkeztem abban, a mit cselekedtem. Azért most, óh Uram, vedd el, kérlek, a te szolgádnak álnokságát; mert felette esztelenül cselekedtem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'És mikor felkelt reggel Dávid, szóla az Úr Gád prófétának, a ki Dávidnak látnoka vala, ezt mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, 'Menj el, és szólj Dávidnak: Ezt mondja az Úr: Három dolgot adok elődbe, válaszd egyiket magadnak ezek közül, hogy a szerint cselekedjem veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'Elméne azért Gád Dávidhoz, és tudtára adá néki, és monda néki: Akarod-é, hogy hét esztendeig való éhség szálljon földedre? Vagy hogy három hónapig ellenségeid előtt bujdossál és ellenséged kergessen téged? Vagy hogy három napig döghalál legyen országodban? Most gondold meg és lásd meg, micsoda választ vigyek annak, a ki engem elküldött.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'És monda Dávid Gádnak: Felette igen szorongattatom; de mégis, hadd essünk inkább az Úr kezébe, mert nagy az ő irgalmassága, és ne essem ember kezébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, 'Bocsáta annakokáért az Úr döghalált Izráelre, reggeltől fogva az elrendelt ideig, és meghalának a nép közül Dántól fogva Beersebáig, hetvenezer férfiak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, 'És mikor felemelte kezét az angyal Jeruzsálem ellen is, hogy azt is elpusztítsa, megelégelé az Úr a veszedelmet, és monda az angyalnak, a ki a népet öli vala: Elég immár, hagyd el. Az Úrnak angyala pedig vala a Jebuzeus Arauna szérűje mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'És szóla Dávid az Úrnak, mikor látta az angyalt, a ki a népet vágja vala, és monda: Ímé én vétkeztem és én cselekedtem hamisságot, de ezek a juhok ugyan mit cselekedtek? Kérlek, inkább forduljon a te kezed ellenem és az én atyámnak háznépe ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, 'Méne azért Gád Dávidhoz azon a napon, és monda néki: Eredj, menj el, és rakass oltárt az Úrnak a Jebuzeus Araunának szérűjén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'És elméne Dávid Gádnak beszéde szerint, a mint az Úr megparancsolta vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'És feltekintvén Arauna, látá, hogy a király az ő szolgáival ő hozzá megy; és Arauna kimenvén, meghajtá magát a király előtt, arczczal a föld felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'És monda Arauna: Mi az oka, hogy az én uram, a király az ő szolgájához jő? Felele Dávid: Azért, hogy megvegyem tőled e szérűt, és oltárt építsek ezen az Úrnak, hogy megszünjék a csapás a nép között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'Monda Arauna Dávidnak: Vegye el hát az én uram, a király, és áldozza fel, a mi néki tetszik. Ímhol vannak az ökrök az áldozathoz; a boronák és az ökrök szerszámai pedig fa helyett;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'Arauna mindezt, óh király, a királynak adja. És monda Arauna a királynak: A te Urad Istened engeszteltessék meg általad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, 'Monda pedig a király Araunának: Nem, hanem pénzen veszem meg tőled, mert nem akarok az Úrnak, az én Istenemnek ingyen való áldozatot áldozni. Megvevé azért Dávid azt a szérűt és az ökröket ötven ezüst sikluson.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'És oltárt építe ott Dávid az Úrnak, és áldozék egészen égő és hálaáldozattal; és megkegyelmeze az Úr a földnek, és megszünék a csapás Izráelben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, 'Mikor pedig megvénhedt és megöregedett Dávid király, bár leplekkel takargatták be, mégsem bírt felmelegedni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, 'És mondának néki az ő szolgái: Keressenek az én uramnak, a királynak egy szűz leányt, a ki a király körül legyen, és őt ápolja, aludjék karjai között, és melegítse fel az én uramat, a királyt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, 'Keresének annakokáért egy szép leányt Izráelnek minden határiban; és találák a Súnem városából való Abiságot, a kit el is hozának a királyhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, 'És a leány igen szép volt, és a királyt ápolta és szolgált néki. De a király nem ismeré őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, 'Adónia pedig, Haggitnak fia, felfuvalkodék, ezt mondván: Én fogok uralkodni! És szerze magának szekereket, lovagokat és ötven előtte járó férfiakat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, 'Kit az ő atyja soha meg nem szomoríta, ezt mondván: Miért cselekszel így?! Ez is pedig igen szép férfi volt, és őt Haggit szülte volt Dávidnak Absolon után.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, 'És tanácskozék Joábbal, Séruja fiával és Abjátár pappal, kik az Adónia pártján voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'De Sádók pap, meg Benája, a Jójada fia, és Nátán próféta, és Sémei, és Réhi, és a Dávid erős vitézei nem állottak Adónia mellé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'Mikor pedig Adónia áldozatot mutatott be juhokból, ökrökből és egyéb kövér barmokból a Zohélet kősziklánál, a mely a Rógel forrása mellett volt: meghívá egész rokonságát, a király fiait, Júda minden férfiait, a király szolgáit;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'De Nátán prófétát és Benáját és amaz erős vitézeket és Salamont, az ő atyjafiát nem hívá el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, 'Szóla akkor Nátán Bethsabénak, a Salamon anyjának, mondván: Nem hallottad-é, hogy Adónia, a Haggit fia uralkodik, és a mi urunk Dávid nem tud róla semmit?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, 'Jövel azért, hadd adjak néked tanácsot, hogy megmentsd a te életedet, és a te fiadnak, Salamonnak életét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, 'Eredj, menj be Dávid királyhoz, és mondd ezt néki: Uram király, nemde nem esküdtél-é meg a te szolgálóleányodnak ilyenképen: Salamon, a te fiad uralkodik én utánam, és ő ül az én királyi székembe? Miért uralkodik hát Adónia?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'És ímé mialatt még te ott a királylyal beszélsz, én is bemegyek utánad, és kiegészítem a te beszédidet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, 'És beméne Bethsabé a királyhoz a kamarába. És a király igen megvénhedett vala, és a Súnemből való Abiság szolgál vala a királynak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'És fejet hajta Bethsabé, és meghajtá magát a királynak. És monda a király: Mit kivánsz?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'Felele néki Bethsabé: Édes uram, te megesküdtél az Úrra, a te Istenedre a te szolgálóleányodnak ilyenképen: Salamon, a te fiad uralkodik én utánam, és ő ül az én királyi székembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'És ímé mégis Adónia lett királylyá; és ímé, uram király, te nem tudsz erről semmit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, 'Mert áldozott ökrökkel és nagy sok kövér barmokkal bőségesen, és vendégekké hívta a királynak minden fiait, és Abjátár papot és Joábot, a seregnek hadnagyát, csak Salamont, a te szolgádat nem hívta meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, 'Még most te vagy, Uram, a király; az egész Izráel népének szemei reád néznek, hogy megjelentsed nékik, kicsoda fog ülni az én uramnak, a királynak székében, ő utána.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, 'De ha az én uram, a király, az ő atyáival elaluszik: akkor én és az én fiam, Salamon leszünk bűnösök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'És ímé, mikor még a királylyal szólana, Nátán próféta megérkezék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, 'És bejelenték a királynak, mondván: Itt van Nátán próféta. És bemenvén a király eleibe, meghajtá magát a király előtt, arczczal a földre leborulván.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'És monda Nátán: Uram király, te mondottad-é: Adónia legyen én utánam a király, és ő üljön az én királyi székembe?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, 'Mert ma aláment, és áldozott ökrökkel és kövér barmokkal bőségesen, és vendégekké hívta a királynak minden fiait és a seregnek hadnagyait és Abjátár papot: és ímé ők esznek és isznak ő előtte, és immár azt kiáltották: Éljen Adónia király!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'Engem pedig, a ki a te szolgád vagyok, és Sádók papot és Benáját, a Jójada fiát, és Salamont, a te szolgádat nem hívta meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, 'Avagy az én uramtól, a királytól lett-é ez a dolog, hogy nem adtad tudtára a te szolgádnak, kicsoda fogna ülni az én uramnak, a királynak székiben az ő holta után.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'És felelvén Dávid király, monda: Hívjátok hozzám Bethsabét, a ki beméne a király eleibe, és megálla a király előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, 'És megesküvék a király, mondván: Él az Úr, a ki megszabadította az én lelkemet minden nyomorúságból,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, 'Hogy a miképen megesküdtem néked az Úrra, Izráel Istenére, ezt mondván: A te fiad Salamon uralkodik én utánam, és ő ül az én királyi székembe én helyettem: ezt ma így meg is teszem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, 'És fejet hajta Bethsabé, arczczal a földre leborulván, és magát meghajtván a király előtt, monda: Éljen az én uram, Dávid király, mindörökké!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'Azután monda Dávid király: Hívjátok hozzám Sádók papot és Nátán prófétát és Benáját, Jójadának fiát. És ezek bemenének a király eleibe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, 'És monda nékik a király: Vegyétek mellétek a ti uratoknak szolgáit, és ültessétek Salamont, az én fiamat az én öszvéremre, és vigyétek alá őt Gihonba;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'És kenje őt ott Sádók pap és Nátán próféta Izráelnek királyává; és fújjátok meg a harsonákat, és kiáltsátok: Éljen Salamon király!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'És jőjjetek fel onnét ő utána; és eljövén, üljön az én királyi székembe, és ő uralkodjék én helyettem; mert immár meghagytam néki, hogy ő legyen fejedelme mind Izráelnek, mind Júdának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'Felele akkor Benája, a Jójada fia a királynak, és monda: Ámen! Így szóljon az Úr, az én uramnak, a királynak Istene is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'A miképen vele volt az Úr az én urammal, a királylyal: azonképen legyen vele Salamonnal is, és magasztalja feljebb az ő királyi székét az én uramnak, Dávid királynak királyi székénél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'Aláméne azért Sádók pap és Nátán próféta és Benája, a Jójada fia, a Kereteusok is és a Peleteusok, és felülteték Salamont a Dávid király öszvérére, és alávivék őt Gihonba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'És vevé Sádók pap az olajos szarut az Úr sátorából, és megkené Salamont; azután kürtölének, és az egész nép ezt kiáltá: Éljen Salamon király!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'És felvonult utána az egész nép, és a nép sípolt és felette ujjongott, úgy hogy a föld is megrepedne kiáltásuk zajától.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'És Adónia is meghallotta és vendégei is mind, a kik nála valának, miután a lakomát már elvégezték; és meghallá Joáb is a kürtölés szavát, és monda: Miért e zaj és mozgás a városban?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, 'És a mikor ő még szólana, ímé megérkezék Jonathán, az Abjátár pap fia. És monda Adónia: Jőjj be, mert megbízható férfiú vagy, és jó hírt mondasz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'Jonathán pedig felelvén, monda Adóniának: Igen, a mi urunk, Dávid király, Salamont tette királylyá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, 'És elküldötte ő vele Sádók papot a király és Nátán prófétát, és Benáját, a Jójada fiát, a Kereteusokat is és Peleteusokat, és őt a király öszvérére ülteték,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, 'És Sádók pap Nátán prófétával együtt királylyá kente fel őt Gihonnál, és onnét vonulnak fel örömmel; ettől zendült meg a város. Ez az a zaj, a melyet hallottatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, 'És immár be is ült Salamon az országnak királyi székibe;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, 'És a király szolgái is bemenének, hogy áldják a mi urunkat, Dávid királyt, mondván: Tegye az Isten a Salamon nevét híresebbé a te nevednél, és magasztalja feljebb az ő székit a te székednél. És meghajtá magát a király az ő ágyán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, 'És ekképen is szóla a király: Áldott az Úr, Izráel Istene, a ki adott e mai napon olyat, a ki szemeim láttára helyettem üljön az én királyi székemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'Akkor megrettenének, és felkelének mindnyájan a hivatalosok, a kik Adóniával valának, és kiki mind dolgára méne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, 'De Adónia félt Salamontól, és felkészülve elfutott, és megragadta az oltárnak szarvait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, 'Hírül adák pedig Salamonnak ilyen szókkal: Ímé Adónia Salamon királytól való féltében megfogá az oltárnak szarvait, ezt mondván: Esküdjék meg ma nékem Salamon király, hogy meg nem öli az ő szolgáját fegyverrel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'És monda Salamon: Ha jámbor lészen, egy hajszál fejéről le nem esik a földre; de ha gonoszság találtatik ő benne, meg kell halnia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'Elkülde azért Salamon király, és elhozák őt az oltártól; és eljövén meghajtá magát Salamon király előtt; és monda Salamon király: Menj el a te házadhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, 'Mikor pedig elközelgett Dávidnak ideje, hogy meghaljon, parancsot ada Salamonnak az ő fiának, ezt mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, 'Én elmegyek az egész földnek útján; erősítsd meg magad és légy férfiú.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, 'És őrízd meg az Úrnak a te Istenednek őrizetit, hogy az ő útain járj, és megőrizzed az ő rendeléseit, parancsolatit és ítéleteit, és bizonyságtételeit, a mint meg van írva a Mózes törvényében: hogy előmented legyen mindenekben, a melyeket cselekedéndesz, és mindenütt, valamerre fordulándasz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, 'Hogy megteljesítse az Úr az ő beszédét, melyet szólott nékem, mondván: Ha megőrizéndik a te fiaid az ő útjokat, járván én előttem tökéletességgel, teljes szívök és teljes lelkök szerint; ezt mondván, mondom: Soha el nem fogy a férfiú te közüled az Izráelnek királyi székiből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, 'Azt is jól tudod, mit cselekedett én velem Joáb, a Séruja fia, mit cselekedett az Izráel seregeinek két fővezérével, Abnerrel, a Nér fiával, és Amasával, a Jéter fiával, a kiket megölt, harczi vért ontván békességnek idején, és hintett harczi vért az ő derekának övére és az ő lábának saruira.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, 'Cselekedjél a te bölcseséged szerint, és ne engedd, hogy megőszülvén, békességgel menjen a koporsóba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, 'De a gileádbeli Barzillainak fiaival cselekedjél irgalmasságot, és legyenek a te asztalod vendégei, mert így közeledtek ők is hozzám, mikor Absolon, a te testvéred elől menekültem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, 'És ímé veled van Sémei, Gérának fia, a Bahurimbeli Benjáminita, a ki gyalázatosan szidalmazott akkor, mikor Mahanáimba mentem; de aztán, mikor elém alájött a Jordánhoz, megesküdtem néki az Úrra, és mondék: Nem öllek meg téged fegyverrel;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, 'Te azonban ne hagyd őt büntetés nélkül, és mivel eszes férfiú vagy, tudod, mit kelljen cselekedned vele, hogy az ő vénségét vérrel bocsássad a koporsóba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, 'Azután elaludt Dávid az ő atyáival, és eltemetteték a Dávid városában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'Az idő pedig, a melyben uralkodék Dávid Izráelen, negyven esztendő. Hebronban uralkodék hét esztendeig, Jeruzsálemben pedig uralkodék harminchárom esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'Azután Salamon ült Dávidnak, az ő atyjának királyi székibe, és megerősödék az ő királyi birodalma felette igen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, 'De Adónia, a Haggit fia beméne Bethsabéhoz, a Salamon anyjához, és az monda: Békességes-é a te jöveteled? Ki felele: Békességes.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, 'És monda: Beszédem volna veled. Monda az: Szólj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'Akkor monda Adónia: Te tudod, hogy az ország az enyém vala, és az egész Izráel reám néz vala, hogy én uralkodjam; de elvéteték az ország tőlem, és lőn az én atyámfiáé, mert az Úrtól adattaték néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, 'Most egy kérést kérek tőled, ne szégyenítsd meg orczámat. Az pedig monda: Beszélj!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, 'És monda: Beszélj, kérlek Salamon királylyal; mert ő a te kérésedet meg nem veti, hogy adja nékem a Súnemből való Abiságot feleségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'Felele Bethsabé: Jól van, majd szólok melletted a királynak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'És beméne Bethsabé Salamon királyhoz, hogy beszéljen vele Adónia érdekében; és felkele a király, és elébe menvén meghajtá magát előtte, és leüle királyi székibe; és széket tétete a király anyjának, hogy üljön az ő jobbkeze felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'És monda Bethsabé: Egy kis kérést kérek tőled, ne szégyenítsd meg orczámat. És monda néki a király: Kérj édes anyám; mert nem szégyenítem meg orczádat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, 'Monda ő: Adassék a Súnemből való Abiság Adóniának, a te testvérednek feleségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'Akkor felele Salamon király, és monda az ő anyjának: De miért kéred te a Súnembeli Abiságot Adóniának? Kérjed néki az országot is; mert ő az én bátyám, és vele egyetért Abjátár pap, és Joáb, a Séruja fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'És megesküvék Salamon király az Úrra, mondván: Úgy cselekedjék velem az Isten, és úgy segéljen, hogy Adónia a saját élete ellen szólotta ezt a beszédet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, 'Most azért él az Úr, a ki megerősített engem és ültetett engem az én atyámnak, Dávidnak királyi székibe, és a ki házat szerzett nékem, a mint megmondotta volt: ma Adóniának meg kell halnia!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'Elküldé azért Salamon király Benáját, a Jójada fiát, a ki levágá őt, és meghala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, 'Abjátár papnak pedig monda a király: Menj el Anathótba, a te jószágodba, mert halálnak fia vagy; de ma meg nem öletlek, mivel te hordoztad az Úr Istennek ládáját Dávid, az én atyám előtt, és mivel az én atyámnak minden nyomorúságaiban részes voltál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'És kiűzé Salamon Abjátárt, hogy ne legyen az Úrnak papja, hogy beteljesedjék az Úrnak beszéde, a melyet szólott vala az Éli háza felől Silóban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, 'És eljutott ez a hír Joábhoz, mert Joáb Adóniához hajlott vala, noha azelőtt nem hajlott vala Absolonhoz, és elfuta Joáb az Úrnak sátorába, és megfogá az oltárnak szarvait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'Hírül adák pedig Salamon királynak, hogy Joáb az Úrnak sátorához futott, és ímé az oltár mellett áll. Ekkor elküldé Salamon Benáját, a Jójada fiát, mondván: Menj el, vágd le őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'Mikor pedig Benája az Úrnak sátorához ért, monda néki: Ezt mondja a király: Jőjj ki. Kinek felele Joáb: Nem, itt akarok meghalni. És megvivé Benája a királynak e dolgot, mondván: Így szólott Joáb és így felelt nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, 'És monda néki a király: Cselekedjél úgy, a mint szólott; vágd le őt és temesd el, hogy elvedd az ártatlan vért, a melyet kiontott Joáb, én rólam és az én atyámnak házáról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, 'És fordítsa az Úr az ő fejére az ő vérét, a miért nálánál igazabb és jobb két férfira támadott, és megölé őket fegyverrel az én atyámnak, Dávidnak tudta nélkül, tudniillik Abnert, Nérnek fiát, az Izráel seregének fővezérét és Amasát, Jéternek fiát, Júda vitézeinek fővezérét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'Ezeknek a vére térjen Joáb fejére és az ő magvának fejére mindörökké: Dávidnak pedig és az ő magvának és az ő házának és királyi székének békessége legyen az Úrtól mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'És elméne Benája, Jójada fia, és reá rohanván megölé őt; és eltemetteték az ő házában, a pusztában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, 'Rendelé pedig a király a Jójada fiát ő helyette a sereg fölé, és Sádók papot rendelé a király Abjátár helyett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, 'És elkülde a király, és magához hivatá Sémeit, és monda néki: Építs házat magadnak Jeruzsálemben és lakjál ott; és onnét ne menj ki se ide, se tova.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, 'Mert valamely nap kimenéndesz, és általmenéndesz a Kidron patakján, tudd meg, hogy meg kell halnod, a te véred lészen tennen fejeden.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'És monda Sémei a királynak: Tetszik nékem e beszéd; a miképen szólott az én uram, a király, a képen cselekeszik a te szolgád; és sok ideig lakék Sémei Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, 'Lőn azonban három esztendő mulva, hogy Sémeinek két szolgája elszökött Ákishoz, Maaka fiához, a Gáthbeli királyhoz; és hírül adák Sémeinek, mondván: Ímé a te szolgáid Gáthban vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'Ekkor felkelt Sémei, és megnyergelé szamarát, és elméne Gáthba Ákishoz, hogy megkeresse az ő szolgáit. Oda érvén Sémei, meghozá szolgáit Gáthból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'Hírül adák pedig Salamonnak, hogy elment Sémei Jeruzsálemből Gáthba, és haza jött.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, 'Akkor elkülde a király, és magához hivatá Sémeit, és monda néki: Nemde esküvéssel kényszerítettelek-é téged az Úrra, és bizonyságot tettem néked, ezt mondván: Valamely napon kimenéndesz, s ide s tova menéndesz, bizonynyal tudjad, hogy meghalsz; és azt mondád nékem: Tetszik e beszéd, megértettem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'Miért nem tartottad hát meg az Úr előtt való esküvést, és a parancsolatot, a melyet néked parancsoltam?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, 'Monda annakfelette a király Sémeinek: Te tudod mindazt a gonoszságot, a melyről a te szíved bizonyság, és a melyet atyámmal Dáviddal cselekedtél: az Úr most mindazt a gonoszságot a saját fejedre fordította.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'Salamon király pedig áldott lészen, és Dávidnak királyi széke lészen állandó az Úr előtt mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, 'És parancsola a király Benájának, a Jójada fiának, a ki elméne, és levágá Sémeit, és meghala. És az ország megerősödék Salamon kezében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, 'Sógorságot szerze azután Salamon a Faraóval, az Égyiptombeli királylyal; és elvevé a Faraó leányát, és hozá Dávidnak városába, míg elvégezé az ő házának és az Úr házának építését és Jeruzsálemnek kőfalát köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, 'De a nép áldozik vala a magas helyeken; mert nem építtetett vala ház az Úr nevének mind ez ideig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'Szereté pedig Salamon az Urat, járván Dávidnak, az ő atyjának parancsolatiban, kivéve, hogy a magas helyeken áldozott, és ott tömjénezett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, 'És mikor Gibeonba ment a király, hogy ott áldozzék, mert ott volt a nagy magaslat, és Salamon azon az oltáron áldozott égőáldozatul ezer barmot:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'Megjelenék Gibeonban az Úr Salamonnak azon éjjel álmában, és monda az Isten: Kérj, a mit akarsz, hogy adjak néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'És monda Salamon: Te a te szolgáddal, az én atyámmal, Dáviddal nagy irgalmasságot cselekedtél, a miképen ő is járt előtted híven, igazán és hozzád egyenes szívvel, és megtartottad néki ezt a nagy irgalmasságot, hogy néki fiat adtál, a ki az ő királyi székében ül, a mint e mai napon megtetszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'És most, óh én Uram Istenem, te tetted a te szolgádat királylyá, Dávid, az én atyám helyett. Én pedig kicsiny gyermek vagyok, nem tudok kimenni és bejönni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, 'És a te szolgád a te néped között van, a melyet te magadnak választottál, nagy nép ez, a mely meg nem számláltathatik, meg sem írattathatik a sokaság miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, 'Adj azért a te szolgádnak értelmes szívet, hogy tudja ítélni a te népedet, és tudjon választást tenni a jó és gonosz között; mert kicsoda kormányozhatja ezt a te nagy népedet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, 'És tetszék e beszéd az Úrnak, hogy Salamon ilyen dolgot kért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, 'Monda azért az Isten néki: Mivelhogy ezt kérted tőlem, és nem kértél magadnak hosszú életet, sem nem kértél gazdagságot, sem pedig nem kérted a te ellenségidnek lelkét; hanem bölcseséget kértél az ítélettételre:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, 'Ímé a te beszéded szerint cselekszem, ímé adok néked bölcs és értelmes szívet, úgy hogy hozzád hasonló nem volt te előtted, és utánad sem támad olyan, mint te.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, 'Sőt még a mit nem kértél, azt is megadom néked, gazdagságot és dicsőséget: úgy hogy a királyok között nem lesz hozzád hasonló senki minden te idődben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, 'És ha az én útaimon járándasz, megőrizvén az én végzéseimet és parancsolatimat, a miképen járt a te atyád, Dávid: meghosszabbítom életed idejét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, 'És mikor felserkent Salamon, ímé álom volt. És méne Jeruzsálembe, és álla az Úr szövetségének ládája elé, és áldozék egészen égőáldozatokat, és készíte hálaáldozatokat, és szerze nagy lakomát minden szolgáinak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, 'Abban az időben jött a királyhoz két parázna asszony, és megálla ő előtte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, 'És monda az egyik asszony: Kérlek uram, én és ez az asszony egy házban laktunk, és szültem ő nála abban a házban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'És harmadnappal az én szülésem után, ez az asszony is szült, és együtt valánk, senki idegen nem volt velünk a házban, hanem csak mi ketten valánk abban a házban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, 'És ennek az asszonynak éjszaka meghalt a fia: mert ráfeküdt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, 'És felkelt éjfélkor, és elvitte az én fiamat mellőlem, mert a te szolgálóleányod aludt, és azt maga mellé fekteté, míg az ő meghalt fiát én mellém fektette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, 'Mikor pedig hajnalban felkeltem, hogy megszoptassam az én fiamat: ímé, megholt; de reggel jól megnézegetvén, látám, hogy az nem az én fiam, a kit én szültem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, 'Monda pedig a másik asszony: Nem úgy van, az én fiam az, a ki él, a te fiad pedig az, a ki meghalt. Amaz viszont monda: Nem, hanem a te fiad az, a ki meghalt, és az én fiam az, a ki él. És ekképen versengettek a király előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, 'Akkor monda a király: Ez azt mondja: Ez az én fiam, a ki él, és a te fiad az, a ki meghalt; amaz meg ezt mondja: Semmiképen nem, hanem a te fiad az, a ki meghalt, és az én fiam az, a ki él.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, 'És monda a király: Hozzatok nékem kardot! És mikor oda hozák a kardot a király elé,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, 'Monda a király: Vágjátok két részre az eleven gyermeket, és adjátok az egyik részt egyiknek, a másikat pedig a másiknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, 'Ekkor monda az az asszony, a kié vala az élő gyermek, a királynak, mert megindult szíve gyermekén: Kérlek, uram, adjátok néki az élő gyermeket, és ne öljétek meg őt. A másik pedig azt mondja vala. Se enyim, se tied ne legyen; vágjátok ketté.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, 'Akkor felele a király, és monda: Adjátok amannak az élő gyermeket, és meg ne öljétek azt, mert az az ő anyja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'És mikor hallotta az egész Izráel ezt az ítéletet, a melyet tett vala a király, félék a királynak orczáját, mert látták, hogy Isten bölcsesége van az ő szívében az ítélettételre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'És lőn Salamon király az egész Izráel felett királylyá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'Ezek valának pedig az ő főemberei: Azária, Sádók papnak fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Elihóref és Ahija, Sisának fiai íródeákok, Jósafát, az Ahilud fia, emlékíró vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'És Benája, a Jójada fia, a sereg hadnagya; Sádók pedig és Abjátár papok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'És Azáriás, a Nátán fia, a tiszttartók előljárója; és Zábud, a Nátán fia, főtanácsos és a király barátja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'És Ahisár udvarbíró; Adónirám pedig, az Abda fia, kincstartó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'Vala pedig Salamonnak tizenkét tiszttartója az egész Izráelen, a kik ellátták a királyt és az ő háznépét: esztendőnként mindeniknek egy hónapig kellett az ellátásról gondot viselnie.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'És ezek azoknak neveik: Húrnak fia az Efraim hegyén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'Dékernek fia Mákásban, Sahálbimban, Béth-Semesben és Elonban és Béth-Hanánban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'Hésednek fia Arúbotban, ő hozzá tartozott Szókó és Héfer egész földe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'Abinádáb fiaié volt Dór egész határa. A Salamon leánya, Táfát, vala néki felesége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Bahana, az Ahilud fia, bírja vala Taanákot és Megiddót és egész Béth-Seánt, mely Sartána mellett vala Jezréel alatt, Béth-Seántól fogva mind Abela Méholáig és mind Jokméámon túl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'Gébernek fia, Rámóth Gileádban: övé valának Jáirnak, a Manasse fiának falui, melyek Gileádban valának; az övé volt az Argób tartománya, mely Básánban vala, hatvan nagy város kőfallal és érczzárakkal megerősítve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Ahinádáb, Iddó fia Mahanáimban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Ahimaás Naftaliban; a Salamon leányát, Bosmátát vevé magának feleségül ő is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Bahana, Khúsai fia, Áserben és Alóthban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Jósafát, Paruákh fia, Issakhárban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'Simei, Éla fia, Benjáminban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'Géber, Uri fia, a Gileád földében, Sihonnak, az Emoreus királyának földében, és Ógnak, a Básánbeli királynak földében; és ez egy tiszttartó bírja vala azt a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, 'És Júda és Izráel megsokasodott, olyan sok volt, mint a tenger mellett való föveny, és ettek, ittak és vigadtak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 21, 'Salamon pedig uralkodék minden országokon a folyóvíztől fogva egész a Filiszteusok földéig és Égyiptomnak határáig, és ajándékokat hoznak vala, és szolgálnak vala Salamonnak, életének minden idejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 22, 'És Salamon eledele naponként ez vala: harmincz véka zsemlyeliszt és hatvan véka közönséges liszt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 23, 'Tíz hízlalt ökör, húsz füvön járt ökör és száz juh; a szarvasokon, őzeken, bivalokon és hízlalt madarakon kivül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 24, 'Mert ő uralkodék minden helyeken a folyóvizen túl Thifsától fogva egész Gázáig; minden királyokon, a kik a folyóvizen túl valának; és békessége volt néki minden alattvalóitól köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 25, 'És lakozék Júda és Izráel bátorsággal, kiki mind az ő szőlőtője és fügefája alatt. Dántól fogva Bersebáig; Salamonnak minden idejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 26, 'És Salamonnak volt negyvenezer szekérbe való lova az istállókban, és tizenkétezer lovagja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 27, 'És ezek a tiszttartók ellátták Salamon királyt és mindazokat, a kik a Salamon király asztalánál valának, kiki az ő hónapján, minden fogyatkozás nélkül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 28, 'Azután árpát és szalmát is hoztak a lovaknak és a paripáknak arra a helyre, a hol a király volt, kiki az ő rendelete szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 29, 'És az Isten adott bölcseséget Salamonnak és igen nagy értelmet és mély szívet, mint a fövény, mely a tenger partján van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 30, 'Úgy hogy a Salamon bölcsesége nagyobb volt, mint a napkelet minden fiainak bölcsesége és Égyiptomnak egész bölcsesége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 31, 'Sőt bölcsebb volt minden embereknél, még az Ezráhita Ethánnál is és Hémánnál, Kálkólnál és Dardánál, a Máhol fiainál; és híre neve vala minden nemzetségek között köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 32, 'És szerze háromezer példabeszédet, és az ő énekeinek száma ezer és öt volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 33, 'Szólott a fákról is, a Libánon czédrusfájától az izsópig, a mely a falból nevekedik ki; és szólott a barmokról, a madarakról, a csúszó-mászó állatokról és a halakról is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 34, 'És jőnek vala minden népek közül, hogy hallgassák a Salamon bölcseségét; a földnek minden királyaitól, a kik hallották vala az ő bölcseségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'És Hírám, Tírus királya elküldé az ő szolgáit Salamonhoz, mikor meghallotta, hogy őt kenték királylyá az ő atyja helyett; mert Hírám szerette Dávidot teljes életében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, 'És külde Salamon Hírámhoz, ezt izenvén néki:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, 'Te tudod, hogy Dávid, az én atyám nem építhete házat az Úrnak, az ő Istenének nevének a háborúk miatt, a melyekkel őt körülvették vala, mígnem az Úr az ő lábainak talpa alá vetette azokat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'De most az Úr, az én Istenem nékem nyugodalmat adott mindenfelől, úgy hogy semmi ellenségem és senkitől semmi bántásom nincs.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'Ímé azt gondoltam magamban, hogy házat építek az Úrnak, az én Istenemnek nevének, a miképen szólott az Úr Dávidnak, az én atyámnak, ezt mondván: A te fiad, a kit helyetted ültetek a te királyi székedbe, ő építi meg azt a házat az én nevemnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'Most azért parancsold meg, hogy vágjanak nékem czédrusfákat a Libánonon. Az én szolgáim is együtt lesznek a te szolgáiddal; a te szolgáidnak pedig jutalmát megadom néked mind a szerint, a mit mondándasz; mert tudod, hogy nincsen mi közöttünk olyan ember, a ki a favágáshoz úgy értene, mint a Sidonbeliek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'Mikor azért meghallotta Hírám a Salamon izenetét, igen megörült, és monda: Áldott legyen e mai napon az Úr, a ki Dávidnak bölcs fiat adott e nagy népen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'És elkülde Hírám Salamonhoz, ezt izenvén: Megértettem a mi felől küldöttél hozzám; én megteszem minden kivánságodat mind a czédrusfákra, mind a fenyőfákra nézve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'Az én szolgáim a Libánonról aláviszik a tengerre a fákat: én pedig azokat tutajokra rakatván, a tengeren addig a helyig vitetem, a melyet te megizentetsz nékem, és azokat ott kihányatom, és te vitesd el. Te pedig abban teljesítsd kivánságomat, hogy adj eledelt az én háznépemnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'Ada azért Hírám Salamonnak czédrusfákat és fenyőfákat, minden kivánsága szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'Salamon pedig ada Hírámnak húszezer véka búzát az ő háznépének táplálására, és húszezer kórus sajtolt olajat. Ezt adja vala Salamon Hírámnak esztendőről-esztendőre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'Az Úr azért bölcsességet ada Salamonnak, a mint megmondotta vala néki; és békesség lőn Hírám és Salamon között, és ők szövetséget tőnek egymással.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'Salamon király pedig robotosokat szedete az egész Izráelből; és harminczezer ember lőn robotossá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'A kiket aztán elkülde a Libánonra, minden hónapra tíz-tízezer ember egymás után. Egy hónapig a Libánon hegyén valának, két hónapig az ő házoknál. Adónirám vala pedig a robotosok feje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'Ezenkivül Salamonnak hetvenezer teherhordója, és nyolczvanezer kővágója volt a hegyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'A pallérok fejedelmein kivül, a kikre Salamon a munkának igazgatását bízta volt, a kik háromezeren és háromszázan valának, a kik a munkálkodó népet szorgalmaztatták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, 'És megparancsolá a király, hogy nagy és drága köveket vágjanak ki, nevezetesen faragott köveket a ház fundamentomául;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'Melyeket kifaragának a Salamon kőmívesei és a Hírám ácsai és a Gibleusok; és elkészíték a fákat és a köveket a ház építéséhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'És megépítteték az Úrnak háza az Izráel fiainak Égyiptom földéből való kijövetele után a négyszáznyolczvanadik esztendőben, Salamon Izráel felett való uralkodásának negyedik esztendejében, a Zif hónapban, mely a második hónap.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'És a ház, a melyet Salamon király az Úrnak építe, hatvan sing hosszú, húsz sing széles és harmincz sing magas volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, 'És egy tornácz vala a ház temploma előtt, a melynek a hossza húsz sing volt, a háznak szélessége szerint; a szélessége pedig tíz sing volt a ház hosszában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, 'És építe a házon ablakokat is lezárt rostélyzattal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, 'És építe a ház falaira emeleteket köröskörül, a ház falai körül a szent helyen és a szentek szentjén, és készíte mellék helyiségeket körül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, 'Az alsó emelet belső szélessége öt sing, a középső szélessége hat sing és a harmadik szélessége hét sing volt, és bemélyedéseket építe a ház körül kivülről, hogy az emeletek gerendái ne nyúljanak be a ház falaiba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, 'Mikor pedig a ház építteték, a kőbányának egészen kifaragott köveiből építtetett, úgy hogy sem kalapácsnak, sem fejszének, sem valami egyéb vasszerszámnak pengése nem hallattatott a háznak felépítésénél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, 'Az alsó emelet középső mellékhelyiségéhez egy ajtó vezetett a ház jobb oldalán, és egy csiga-grádics vitt fel a középső emeletbe, és a középsőből a harmadikba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, 'Megépíté ekként azt a házat és elvégezé, és befedé a házat gerendákkal és czédrusfadeszkákkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, 'És megépíté az emeleteket az egész ház körül, a melyeknek magasságok öt-öt sing volt, és a házhoz czédrusfagerendákkal ragasztattak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, 'És lőn az Úrnak beszéde Salamonhoz, ezt mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, 'Ez ama ház, a melyet te építesz: Ha az én rendelésimben jársz, és az én ítéletim szerint cselekszel, és megtartod minden én parancsolatimat, azokban járván: Én is bizonyára megerősítem veled az én beszédemet, a melyet szólottam Dávidnak, a te atyádnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, 'És az Izráel fiai között lakozom, és nem hagyom el az én népemet, az Izráelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, 'Megépíté azért Salamon azt a házat, és elvégezé azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, 'És megbéllelé a ház falait belől czédrusfával, a ház padlózatától egészen a padlásig beborítá belől fával; a ház padlózatát pedig beborítá fenyődeszkákkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, 'És építe a ház hátulján egy húsz sing hosszú czédrusfa falat a padlózattól egész a padlásig, és építé azt a ház hátulsó részének: szentek-szentjének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'Az előtte való szenthely hossza negyven sing volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, 'Belülről az egész ház merő czédrus volt, kivésett sártökökkel és kinyilt virágbimbókkal, úgy hogy semmi kő ki nem látszott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, 'És a szentek-szentjét építé a ház belső részében, hogy abba helyheztesse az Úr szövetségének ládáját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, 'A szentek-szentje belső részének a hossza vala húsz sing, a szélessége is húsz sing, a magassága is húsz sing, és beborítá azt finom aranynyal; az oltárt is beborítá czédrusdeszkákkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, 'És Salamon beborította a házat belől finom aranynyal, és arany lánczot vont a belső rész előtt, a melyet szintén bevont aranynyal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, 'Úgy, hogy az egész ház be volt vonva merő aranynyal, sőt az oltárt is, a mely a szentek-szentje előtt volt, egészen beborítá aranynyal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, 'És csinált a szentek-szentjébe két tíz sing magas Kérubot olajfából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, 'És öt sing volt az egyik Kérub szárnya, és öt sing a másik Kérub szárnya is, úgy, hogy az egyik szárnya végétől, a másik szárnya végéig tíz sing vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, 'A másik Kérub is tíz sing volt; és mind a két Kérubnak mind a mértéke, mind a faragása egy vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, 'Úgy, hogy az egyik Kérub magassága tíz sing, és ugyanannyi a másik Kérubé is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'És helyezteté a Kérubokat a ház belsejébe, és a mint a Kérubok kiterjeszték szárnyukat, az egyiknek szárnya a ház egyik falát, a másik Kérub szárnya pedig a másik falát érte; de a ház közepén összeért egyik szárny a másikkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, 'És beborítá a Kérubokat aranynyal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, 'És a ház összes falain köröskörül kivül és belől Kérubokat, pálmafákat és kinyilt virágokat metszetett ki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, 'És beborítá még a ház padlóját is aranynyal kivül és belől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, 'És a szentek-szentjének bemenetelén csinála ajtót olajfából, az ajtófélfák kiszögellése egy ötödrész volt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, 'És két ajtószárnyat olajfából, és metszete reájok Kérubokat, pálmafákat és kinyilt virágokat, és beborítá azokat aranynyal; a Kérubokat is és a pálmafákat is megaranyoztatá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, 'E képen csinált a templom szenthelyénél is négyszegletű ajtófélfákat olajfából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, 'És csinált két ajtót cziprusfából, és az egyik ajtón is két forgó ajtószárny volt, a másik ajtón is két forgó ajtószárny.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'És metszete azokra Kérubokat és pálmafákat és kinyilt virágokat, és beborítá aranynyal, rá alkalmaztatva azt a metszésre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'Azután felépíté a belső pitvart három rend faragott kőből és egy rend czédrusgerendából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, 'Az ő uralkodásának negyedik esztendejében fundáltaték az Úrnak háza Zif hónapban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, 'És a tizenegyedik esztendőben, Búl havában, (mely a nyolczadik hónap) végezteték el a ház, minden dolga és rendje szerint. És így építé azt hét esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, 'Azután a maga házát építé Salamon tizenhárom esztendeig, a mely alatt elvégezé az ő házát egészen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, 'Megépíté a Libánon erdő házát is, melynek hossza száz sing vala, szélessége ötven sing, magassága harmincz sing; építé azt négy rend czédrusoszlopon és az oszlopokon czédrusgerendák valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, 'És bepadlá czédrusdeszkákkal felül a gerendák felett, melyek valának negyvenöt oszlopon, mindenik renden tizenöt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'És három rend ablak rajta egymással átellenben, három-három ellenében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, 'És mind az ajtók és azoknak oldalfái négyszögűek valának az ablakokkal együtt, és egyik ablak a másiknak átellenébe volt mind a három renden.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, 'És építé az oszlopcsarnokot, a melynek hossza ötven sing és szélessége harmincz sing volt; és egy tornáczot ez elé, és oszlopokat és vastag gerendákat ezek elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, 'És építé a trón-termet, a hol ítélt, a törvényházat, a melyet czédrusfával bélelt meg a padlózattól fogva fel a padlásig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'Azután a saját házát építé, a melyben ő maga lakott, a másik udvarba befelé a teremtől, hasonlóan a másikhoz, és építe egy házat a Faraó leányának is, a kit feleségül vett Salamon, hasonlót e teremhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, 'Mindezek drágakövekből voltak, mérték szerint kifaragva, fűrészszel metszve minden oldalról, a fundamentomtól a tetőzetig, kivül is mind a nagy pitvarig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, 'Még a fundamentom is drága és nagy kövekből volt: tíz singnyi kövekből és nyolcz singnyi kövekből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, 'És ezeken felül voltak a mérték szerint faragott drágakövek és czédrusfák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, 'És a nagy pitvarban köröskörül három sor faragott kő és egy sor faragott czédrusgerenda volt, épen mint az Úr házának belső pitvara és a ház tornácza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, 'És elkülde Salamon király, és elhozatá Hírámot Tírusból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, 'Ez egy özvegy asszonynak volt a fia a Nafthali nemzetségéből; az ő atyja pedig Tírusbeli rézmíves ember vala; és ez teljes vala bölcseséggel, értelemmel és tudománynyal, hogy tudna csinálni mindenféle mívet rézből. Ki mikor Salamon királyhoz jött, minden mívet megcsinála néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, 'És formála két réz oszlopot, az egyik oszlop magassága tizennyolcz sing volt, és tizenkét sing zsinór éri vala át mind a két oszlopot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, 'És készíte két gömböt érczből öntve, hogy azokat az oszlopok tetejére tegye, és öt sing magas volt az egyik gömb és öt sing magas volt a másik gömb.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, 'Reczés mívű hálók, lánczmívű zsinórok voltak a gömbökön, a melyek az oszlopok tetején valának; hét volt az egyik gömbön, és hét volt a másik gömbön is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, 'És megkészíté az oszlopokat, és két sor díszítést tett köröskörül az egyik hálón, hogy befedje a gömböket, a melyek az oszlopfőkön voltak; és így csinálá a másik gömböt is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, 'És a gömbök, a melyek a tornáczban levő oszlopok tetején voltak, liliom formájúak voltak, négy singnyiek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, 'Gömbök voltak a két oszlopon, felül, közel a kidomborodáshoz, a mely a háló mellett volt. És kétszáz gránátalma volt sorban köröskörül a második gömbön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, 'És felállítá az oszlopokat a templom tornáczában; és felállítá a jobb oszlopot, és nevezé annak nevét Jákinnak, és felállítá a bal oszlopot, és nevezé annak nevét Boáznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, 'És az oszlopok tetején liliomok formáltattak vala. És ilyen módon végezteték el az oszlopok míve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, 'És csinála egy öntött tengert, mely egyik szélétől fogva a másik széléig tíz sing volt, köröskörül kerek, és öt sing magas, és a kerületit harmincz sing zsinór érte vala körül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, 'Valának pedig a peremén alól köröskörül formáltatva apró sártökök; tíz-tíz mindenik singben az egész tenger körül, az ilyen sártököcskék két renddel valának öntve köröskörül a maga öntésében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, 'És tizenkét ökrön állott, három északra fordulva, három nyugotra, három délre és három naptámadatra, és a tenger fölül rajtok, hátok pedig mind befelé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, 'És a vastagsága egy tenyérnyi volt, és a pereme olyan, mint a pohár ajaka, vagy a liliom virága, és kétezer báth fért bele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, 'És készíte tíz ércz-talpat, mindegyik talpat négy sing hosszúra, és négy sing szélesre, és három sing magasra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, 'És e talpak így voltak csinálva: oldalaik voltak, és az oldalak a szélpártázatok között voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, 'És az oldalakon, a melyek a pártázatok között voltak, oroszlánok, ökrök és Kérubok voltak, és a pártázatokon felül is ekként; az oroszlánok és ökrök alatt pedig czifrázatok voltak bevésett munkával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, 'És mindenik talpnak négy-négy réz kereke és réz tengelye volt, és a négy szegleten támaszok voltak; a mosdómedenczén alul voltak e támaszok öntve, és mindegyiknek oldalán czifrázatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, 'És a szája az ő kerekded fészkének belső részétől fogva oda felfelé egy singnyi volt, és a fészeknek szája kerekded vala, oszlopformára csinálva, másfél singnyi széles, és szájánál is szép metszések valának, és azoknak pártázatai négyszögűek valának, nem gömbölyűek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, 'És négy kerék volt a pártázatok alatt, és a kerekek tengelyei a talphoz voltak erősítve, és mindenik keréknek magassága másfél sing vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, 'És e kerekek hasonlóak valának a szekérnek kerekeihez, csakhogy a tengelyeik, kerékagyaik, küllőik, talpaik mind öntve valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, 'És négy vállacskát csinált mindenik talp négy szegletén; magából a talpból jöttek ki a vállacskák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, 'És e talp tetején fél singnyi kerekded magasság volt köröskörül, és a talp tetején voltak annak tartókezei és pártázatai a maga öntéséből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, 'Metsze pedig annak tábláira, tartókezeire, pártázataira Kérubokat, oroszlánokat és pálmafákat: mindeniknek az üres helye szerint, és koszorút köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, 'Így készítette a tíz talpat egy öntésből, egy mérték és forma szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, 'És csinála tíz mosdómedenczét is rézből, és mindenik mosdómedenczébe negyven báth fér vala; és mindenik mosdómedencze négy singnyi vala, és a tíz talp mindenikén egy-egy mosdómedencze vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, 'És helyhezteté a talpak ötét a ház jobbfelől való részére, és ötét a ház balfelől való részére; a tengert pedig helyhezteté a ház jobbrésze felől naptámadatra dél ellenébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'És készített Hírám még üstöket, lapátokat és medenczéket, és elvégezé az egész munkát, a melyet Salamon királynak csinált az Úr házához;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, 'Tudniillik a két oszlopot és a kerek gömböket, a melyek a két oszlop tetejére tétettek, és a két hálót a két kerek gömb befedezésére, a melyek az oszlopok tetejére tétettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, 'És a négyszáz gránátalmát a két hálóra; két rend gránátalmát minden hálóba, a két kerekded gömb befejezésére, a melyek valának az oszlopok tetején;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, 'A tíz talpat és a talpakra való tíz mosdómedenczét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, 'Az egy tengert és a tizenkét ökröt a tenger alá;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, 'Fazekakat, lapátokat és medenczéket. És mindezek az edények, a melyeket Hírám Salamon királynak az Úr háza számára készített, csiszolt rézből voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, 'A Jordán völgyében önteté ezeket a király az agyagos földben, Sukhót és Sártán között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'És mindezeket az edényeket Salamon méretlen hagyá, a réznek felettébb való sokasága miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, 'És megcsináltata Salamon minden egyéb felszerelést is, mely az Úr házához szükséges volt: az arany oltárt, az arany asztalt, melyen a szent kenyerek állottak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'És a gyertyatartókat színaranyból, ötöt jobbfelől és ötöt balfelől a szentek-szentje elé, és arany virágokat, lámpákat, és hamvvevőket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, 'Azután csészéket, késeket, medenczéket, tömjénezőket és serpenyőket színaranyból, sőt a belső ház, a szentek-szentje és a szenthely ajtainak sarkait is mind aranyból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, 'És ilyenképen elvégezteték az egész mű, a melyet Salamon király csinála az Úrnak házához. És bevivé Salamon az ő atyjától, Dávidtól az Istennek szenteltetett jószágot, az ezüstöt, aranyat és az edényeket és azokat is az Úr házának kincsei közé tevé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, 'Akkor összegyűjté Salamon az Izráel véneit és a nemzetségeknek minden fejeit, az Izráel fiai atyjaiknak fejedelmeit Salamon királyhoz Jeruzsálembe, hogy az Úr szövetségének ládáját felvigyék a Dávid városából, mely a Sion.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'És felgyűlének Salamon királyhoz az Izráel minden férfiai az Ethánim havában, az ünnepen; ez a hetedik hónap.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'Mikor pedig eljöttek mindnyájan az Izráel vénei: felvevék a papok a ládát,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'És felvivék az Úr ládáját, a gyülekezetnek sátorát, és mind a szent edényeket, melyek valának a sátorban, és felvivék azokat a papok és a Léviták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'És Salamon király és az Izráel egész gyülekezete, a mely ő hozzá gyűlt, megyen vala ő vele a láda előtt, áldozván juhokkal és ökrökkel, melyek meg sem számláltathatnának, sem pedig meg nem irattathatnának a sokaság miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'És bevivék a papok az Úr szövetségének ládáját az ő helyére a ház belső részébe, a szentek-szentjébe, a Kérubok szárnyai alá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'Mert a Kérubok kiterjesztik vala szárnyaikat a láda helye felett, és befedik vala a Kérubok a ládát és annak rúdjait felülről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, 'És a rudak olyan hosszúak voltak, hogy azok vége látható volt a szenthelyen a szentek-szentjének első része felől; azonban kivül nem voltak láthatók; és ott vannak mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'És nem volt egyéb a ládában, mint csak a két kőtábla, a melyeket Mózes a Hórebnél helyezett bele, mikor az Úr szövetséget kötött az Izráel fiaival, mikor kijövének Égyiptom földéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'Mikor pedig kijöttek a papok a szenthelyből: köd tölté be az Úrnak házát,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'Úgy, hogy meg sem állhattak a papok az ő szolgálatjokban a köd miatt; mert az Úr dicsősége töltötte vala be az Úrnak házát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, 'Akkor monda Salamon: Az Úr mondotta, hogy ő lakoznék ködben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, 'Építve építettem házat néked lakásul; helyet, a hol örökké lakjál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'Azután megfordult a király, és megáldá Izráel egész gyülekezetét és az Izráel egész gyülekezete felállott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'És monda: Áldott legyen az Úr, Izráelnek Istene, a ki szólott az ő szája által Dávidnak, az én atyámnak; és azt az ő hatalmasságával beteljesítette, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, 'Attól a naptól fogva, a melyen kihoztam az én népemet, az Izráelt Égyiptomból, soha nem választottam egyetlen várost sem az Izráel minden nemzetségei közül, hogy ott nékem házat építenének, a melyben lenne az én nevem; hanem csak Dávidot választottam, hogy ő legyen az én népem, Izráel felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, 'És ámbár az én atyám, Dávid már elvégezte volt, hogy ő épít házat az Úrnak, Izráel Istene nevének;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'De az Úr azt mondá Dávidnak, az én atyámnak: Azt, hogy arra gondoltál, hogy az én nevemnek házat építs, jól cselekedted, hogy szívedben ezt végezted;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'Mégis nem te építesz házat nékem, hanem a te fiad, a ki a te ágyékodból származik, az épít házat az én nevemnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'És beteljesíté az Úr az ő beszédét, a melyet szólott; mert felkelék az én atyám, Dávid helyett, és ülék az Izráel királyi székibe, a miképen megmondotta vala az Úr, és megépítém a házat az Úr, Izráel Istene nevének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'És helyet szerzettem ott a ládának, a melyben az Úrnak szövetsége vagyon, a melyet szerzett a mi atyáinkkal, mikor kihozta őket Égyiptom földéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'És oda állott Salamon az Úr oltára elé, az Izráel egész gyülekezetével szembe, és felemelé kezeit az ég felé,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'És monda: Uram, Izráel Istene! nincsen hozzád hasonló Isten, sem az égben ott fenn, sem a földön itt alant, a ki megtartod a szövetséget és az irgalmasságot a te szolgáidnak, a kik te előtted teljes szívvel járnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'A ki megtartottad azt, a mit a te szolgádnak, Dávidnak, az én atyámnak szólottál; mert magad szólottál néki, és a te hatalmaddal beteljesítetted, a mint e mai napon megtetszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'Most azért Uram, Izráel Istene, tartsd meg, a mit a te szolgádnak, Dávidnak, az én atyámnak igértél, ezt mondván: A te magodból való férfiú el nem fogy én előttem, a ki az Izráel királyi székibe üljön; csakhogy a te fiaid őrizzék meg az ő útjokat, hogy én előttem járjanak, a mint te én előttem jártál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'Most teljesítsd be, Izráel Istene, a te szavaidat, a melyeket szólottál a te szolgádnak, Dávidnak, az én atyámnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, 'Vajjon gondolható-é, hogy lakozhatnék az Isten a földön? Ímé az ég, és az egeknek egei be nem foghatnak téged; mennyivel kevésbbé e ház, a melyet én építettem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'De tekints a te szolgád imádságára és könyörgésére, óh Uram, én Istenem, hogy meghalljad a dicséretet és az imádságot, a melylyel a te szolgád könyörög előtted e mai napon;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'Hogy a te szemeid e házra nézzenek éjjel és nappal, e helyre, a mely felől azt mondottad: Ott lészen az én nevem; hallgasd meg ez imádságot, a melylyel könyörög a te szolgád e helyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'És hallgasd meg a te szolgádnak és a te népednek, az Izráelnek könyörgését, a kik imádkozándanak e helyen; hallgasd meg lakhelyedből, a mennyekből, és meghallgatván légy kegyelmes!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'Mikor vétkezéndik valaki felebarátja ellen, és esküre köteleztetik, hogy megesküdjék és ő ide jő, megesküszik az oltár előtt ebben a házban:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'Te hallgasd meg a mennyekből, és vidd véghez, és tégy igazat a te szolgáid között, kárhoztatván az istentelent, hogy fején teljék a mit keresett; és megigazítván az igazat, megfizetvén néki az ő igazsága szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'Mikor megverettetik a te néped, az Izráel, az ő ellenségeitől, mivel ellened vétkeztek, és hozzád megtéréndenek, és vallást teéndenek a te nevedről, és néked imádkozándanak és könyörgéndenek e házban:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'Te hallgasd meg a mennyekből, és bocsásd meg az Izráelnek, a te népednek vétkét; és hozd vissza őket arra a földre, a melyet adtál az ő atyáiknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'Mikor berekesztetik az ég, és nem lészen eső, mert ellened vétkeztek; és imádkozándanak e helyen, és vallást teéndenek a te nevedről, és megtéréndenek az ő bűnökből, mert te szorongatod őket:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'Te hallgasd meg őket a mennyekből, és légy kegyelmes a te szolgáidnak és az Izráelnek, a te népednek vétke iránt, tanítsd meg őket a jó útra, a melyen járjanak; és adj esőt a te földedre, a melyet örökségül adtál a te népednek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'Éhség ha lesz e földön, ha döghalál, aszály, ragya, sáska, cserebogár; ha ellenség szállja meg kapuit; vagy más csapás és nyavalya jövénd reájok:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'A ki akkor könyörög és imádkozik, legyen az bárki; vagy a te egész néped, az Izráel, ha elismeri kiki az ő szívére mért csapást, és kiterjeszténdi kezeit e ház felé:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'Te hallgasd meg a mennyekből, a te lakhelyedből és légy kegyelmes, és cselekedd azt, hogy kinek-kinek fizess az ő útai szerint, a mint megismerted az ő szívét, mert egyedül csak te ismered minden embernek szívét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'Hogy féljenek téged mind éltig, míg e földnek színén lakoznak, a melyet adtál a mi atyáinknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'Sőt még az idegen is, a ki nem a te néped, az Izráel közül való, ha eljövénd messze földről a te nevedért;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, '(Mert meghallják a te nagyságos nevedet és a te hatalmas kezedet és kinyújtott karodat), és eljövén imádkozánd e házban:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'Te hallgasd meg a mennyekből, a te lakhelyedből, és add meg az idegennek mindazt, a miért könyörög néked, hogy mind az egész földön való népek megismerjék a te nevedet, és féljenek úgy téged, miképen a te néped az Izráel; és ismerjék meg, hogy a te nevedről neveztetik ez a ház, a melyet én építettem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'Ha a te néped hadba megy ki az ő ellensége ellen, az úton, a melyen te küldöd el, és imádkozándik az Úrhoz, fordulván az úton e város felé, a melyet te magadnak választottál és e ház felé, a melyet építettem a te nevednek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'Hallgasd meg a mennyekből az ő imádságokat és könyörgésöket, és szerezz nékik igazságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 'Ha te ellened vétkezéndenek, – mert nincsen ember, a ki ne vétkeznék – és megharagudván reájok, ellenség kezébe adándod, és fogva elviéndik őket azok, a kiktől megfogattak, az ellenségnek földére, messze vagy közel;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'És eszökre térnek a földön, melyre fogva vitettek, és megtérvén könyörgenek néked azoknak földökön, a kiktől fogva elvitettek, mondván: Vétkeztünk, hamisan és istentelenül cselekedtünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'És megtéréndenek te hozzád teljes szívökből és lelkökből, az ő ellenségöknek földében, a kik őket fogva elvitték, és imádkozándanak hozzád az ő földöknek útja felé fordulva, a melyet adtál az ő atyáiknak, és e város felé, a melyet magadnak választottál, és e ház felé, a melyet a te nevednek építettem:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'Hallgasd meg a mennyekből, a te lakhelyedből az ő imádságokat és könyörgésöket, és szerezz nékik igazságot;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'És légy kegyelmes a te néped iránt, a kik ellened vétkezéndenek, és minden bűneik iránt, a melyekkel ellened vétkeztek; és szerezz kedvességet nékik azok előtt, a kik őket fogva tartják, hogy könyörüljenek rajtok;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'Mert ők a te néped és örökséged, a kiket kihoztál Égyiptomból, a vaskemencze közepéből,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, 'Hogy a te szemeid nézzenek a te szolgádnak imádságára és a te népednek az Izráelnek könyörgésére; meghallgatván őket mindenkor, mikor téged segítségül hívnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'Mert te különválasztottad őket magadnak örökségül a földnek minden népei közül; a miképen megmondottad volt Mózes, a te szolgád által, mikor kihoztad a mi atyáinkat Égyiptomból, Uram Isten!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'És mikor elvégezte Salamon az Úr előtt való minden imádságát és könyörgését, felkele az Úr oltára elől, és megszünék az ő térdein való állástól, és kezeinek az égbe felemelésétől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'És felállván megáldá az Izráel egész gyülekezetét, felszóval ezt mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, 'Áldott legyen az Úr, a ki nyugodalmat adott az ő népének, az Izráelnek, minden ő beszéde szerint, csak egy beszéde is hiábavaló nem volt minden ő jó beszédei közül, a melyeket szólott Mózes, az ő szolgája által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'Az Úr, a mi Istenünk, legyen velünk, a miképen volt a mi atyáinkkal, ne hagyjon el minket, el se távozzék tőlünk,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'Hanem hajtsa magához a mi szívünket, hogy járjunk minden ő útaiban, és őrizzük meg az ő parancsolatit, rendeléseit és végzésit, a melyeket a mi atyáinknak parancsolt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'És ezek a szavak, a melyekkel imádkoztam az Úr előtt, legyenek jelen az Úr előtt a mi Istenünk előtt éjjel és nappal, hogy ítéletet tegyen az ő szolgájának és az ő népének, az Izráelnek, minden időben,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'Hogy megismerjék a földön minden népek, hogy csak az Úr az Isten, és hogy ő kívülötte nincsen más.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'És a ti szívetek legyen tökéletes az Úrhoz, a mi Istenünkhöz, hogy járjatok az ő rendeléseiben, és őrizzétek meg az ő parancsolatit, miképen e mai napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'És a király és az egész Izráel ő vele, áldozatokat áldozának az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'És Salamon áldozék hálaadó áldozatul, a melyet áldozék az Úrnak: huszonkétezer ökröt, százhúszezer juhot. És e képen szentelék fel az Úr házát a király és az Izráel minden fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'Ugyanazon napon szentelé fel a király a középső pitvart, mely az Úrnak háza előtt vala; mert ott szerze egészen égőáldozatokat, ételáldozatokat és hálaáldozatok kövéreit. Mert a rézoltár, mely az Úr előtt állott, kisebb volt, mintsem reá fért volna az égőáldozat, az ételáldozat és a hálaáldozatok kövére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'És Salamon ünnepet szerze ebben az időben, és vele együtt az egész Izráel; egy nagy gyűlést Hámát határától fogva Égyiptom határáig, az Úr előtt, a mi Istenünk előtt, hét napig és újra hét napig, azaz tizennégy napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'És a nyolczadik napon elbocsátá a népet. És áldák a királyt, és elmenének az ő hajlékaikba örömmel és víg szívvel, mindama jók felett, a melyeket cselekedett az Úr az ő szolgájával, Dáviddal, és az Izráellel, az ő népével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'És lőn, mikor elvégezte Salamon az Úr házának és a király házának építését, és mindent a mit kívánt és a mit akart építeni Salamon:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'Megjelenék az Úr Salamonnak másodszor is, a miként megjelent volt néki Gibeonban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'És monda néki az Úr: Meghallgattam a te imádságodat és könyörgésedet, a melylyel könyörgöttél előttem: Megszenteltem e házat, a melyet építettél, abba helyheztetvén az én nevemet mindörökké, és ott lesznek az én szemeim, és az én szívem mindenkor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'És ha te előttem járándasz, a mint járt Dávid, a te atyád, egyenes és tökéletes szívvel, úgy cselekedvén mindenekben, a mint néked megparancsoltam, az én rendelésimet és végzésimet megtartándod;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'Megerősítem a te birodalmadnak trónját az Izráelen mindörökké, a mint megígértem volt Dávidnak a te atyádnak, mondván: Nem fogy el a te nemzetségedből való férfiú az Izráel királyi székéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'De hogyha elszakadtok ti és a ti fiaitok én tőlem, és meg nem őrizénditek az én parancsolatimat és végzéseimet, melyeket előtökbe adtam; hanem elmentek, és idegen isteneknek szolgáltok, és meghajoltok azok előtt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'Kigyomlálom az Izráelt e föld színéről, a melyet nékik adtam; e házat, melyet az én nevemnek szenteltem, elvetem szemeim elől, és az Izráel példabeszédül és meséül lészen minden nép előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'És bár e ház felséges, mégis a kik elmennek mellette, elcsodálkoznak, felkiáltanak, és azt mondják: Miért cselekedett így az Úr ezzel a földdel és ezzel a házzal?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'És azt felelik: Azért, mert elhagyták az Urat, az ő Istenöket, a ki az ő atyáikat kihozta volt Égyiptom földéből, és idegen istenekhez ragaszkodtak, és azokat imádták, és azoknak szolgáltak: ezért bocsátá ő reájok az Úr mind ezt a nyomorúságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'És lőn a húsz esztendő végén, a mialatt Salamon a két házat, az Úr házát és a király házát megépíté,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, 'A melyekhez Hírám, Tírus királya adott volt ajándékban Salamonnak czédrusfákat, fenyőfákat, aranyat egész kivánsága szerint: ada Salamon király Hírámnak húsz várost Galileának földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'És kiméne Hírám Tírusból, hogy megnézze azokat a városokat, a melyeket Salamon néki ada, de nem tetszettek azok néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'És monda: Miféle városok ezek, atyámfia, a melyeket nékem adtál? És Kábul földnek nevezé azokat mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'Küldött vala pedig Hírám a királynak százhúsz tálentom aranyat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'És ez az összege annak az adónak is, a melyet kivetett volt Salamon király, hogy megépíthesse az Úr házát, és a maga házát, és Millót, és Jeruzsálem kőfalait, és Kháczort, Megiddót és Gézert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, 'Mert a Faraó, Égyiptom királya, feljött volt, és meghódítá Gézert, és felégette tűzzel, és a Kananeusokat, a kik a városban laktak, megölte, és adá azt ajándékban az ő leányának, a Salamon feleségének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'És megépíté Salamon Gézert és az alsó Bethoront;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'Bahalátot és Thadmort a pusztában, azon a földön;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, 'És a tárházak minden városait, a melyek a Salamonéi valának, a szekerek városait, és a lovagok városait, és mindeneket, a melyeknek építéséhez Salamonnak kedve volt Jeruzsálemben és a Libánonon, és az ő birodalmának egész földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, 'És mindazt a népet, a mely megmaradott volt az Emoreusoktól, Hitteusoktól, Perizeusoktól, Hivveusoktól, Jebuzeusoktól, a kik nem valának az Izráel fiai közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, 'Azoknak fiait, a kik ő utánok azon a földön maradtak volt, a kiket az Izráeliták ki nem irthattak, Salamon jobbágyokká tette mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, 'De az Izráel fiai közül senkit nem vetett Salamon szolgálat alá, hanem ezek hadakozó férfiak voltak és ő szolgái és főemberei és hadnagyai és az ő szekereinek és lovagjainak fejei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'És a hivatalnokoknak, a kik Salamon munkáinak élén állottak, száma ötszázötven volt, a kik igazgatták a népet, a mely dolgozott a munkán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, 'És a Faraó leánya felméne a Dávid városából a maga házába, a melyet Salamon épített néki. Akkor építé meg Millót is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'És áldozék Salamon minden esztendőben háromszor, égő és hálaáldozatot azon az oltáron, a melyet épített vala az Úrnak, és áldozik vala jóillattal azon, a mely az Úr előtt vala. És elvégezé a házat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, 'És hajókat is csináltata Salamon király Esiongáberben, a mely Elót mellett van a Veres tenger partján, az Edom földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'És elküldé Hírám az ő szolgáit a hajókon, a kik jó hajósok és a tengeren jártasak valának, a Salamon szolgáival.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, 'És egész Ofirig menének, és hozának onnét négyszázhúsz tálentom aranyat, és vivék azt Salamon királyhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'A Séba királynéasszonya pedig hallván Salamonnak hírét és az Úr nevét, eljöve, hogy megkisértgesse őt nehéz kérdésekkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'És bejöve Jeruzsálembe igen nagy sereggel és tevékkel, a melyek hoznak vala fűszerszámokat, igen sok aranyat és drágaköveket, és Salamonhoz méne, és szóla vele mindenekről, a melyek szívén voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'És Salamon megfelelt néki mindenre, semmi sem volt a király előtt elrejtve, a mire ne tudott volna néki felelni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'És a mikor látta Séba királynéasszonya Salamonnak minden bölcseségét, és a házat, a melyet épített vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'És az ő asztalának étkeit, és szolgáinak lakásait, és szolgái udvarlásának módját, és azok öltözeteit, és pohárszékeit, és az ő áldozatját, a melylyel az Úrnak házában áldozott: a lélekzete is elállott;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'És monda a királynak: Mind igaz, a mit az én földemben hallottam volt a te dolgaid felől és a te bölcseségedről,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'De én hinni sem akartam azokat a beszédeket, míg én magam el nem jöttem, és szemeimmel nem láttam. És ímé nékem a felét sem beszélték el: te meghaladtad bölcseséggel és jósággal a hírt, a melyet hallottam felőled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'Boldogok a te embereid, boldogok ezek a te szolgáid, a kik udvarlanak néked mindenkor, és hallhatják a te bölcseségedet:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'Legyen az Úr, a te Istened áldott, a ki kedvelt téged, hogy az Izráel királyi székibe ültetett, mert szerette az Úr az Izráelt mindörökké, és királylyá tett téged, hogy ítéletet és igazságot szolgáltass.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'És ada a királynak száz és húsz tálentom aranyat, és igen sok fűszerszámot és drágakövet. Nem hoztak azután ilyen és ennyi sokaságú fűszerszámot, a mennyit Séba királynéasszonya ada Salamon királynak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, 'És a Hírám hajója is, mely aranyat hozott Ofirból, ébenfát is hozott Ofirból nagy bőséggel és drágaköveket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'És csinála a király az ébenfából oszlopokat az Úr házába és a király házába, és az éneklőknek hegedűket és lantokat; nem hoztak soha többé olyan ébenfákat, és nem is láttak olyanokat mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'És Salamon király ada a Séba királynéasszonyának mindent, a mit csak kívánt és kért tőle, azokon kivül, a melyeket gazdagságához képest ada Salamon király néki. Annakutána megtére, és méne az ő földébe szolgáival egyetemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, 'Vala pedig mértéke az aranynak, a mely kezéhez jő vala Salamonnak minden esztendőben, hatszáz és hatvanhat tálentom arany.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'Azonkivül, a mi jő vala az árus emberektől és a fűszerszámokkal kereskedő kalmároktól, és mind az Arábiabeli királyoktól, és annak a földnek tiszttartóitól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'És csináltata Salamon király kétszáz paizst tiszta vert aranyból; mindenik paizsra hatszáz aranyat adott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'És háromszáz kerek paizst vert aranyból, három font aranyat ada mindenik paizsra: és azokat a király helyhezteté a Libánon erdő házába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'És készíte a király elefántcsontból egy nagy királyi széket és beborítá azt finom aranynyal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, 'Hat grádicsa volt e királyi széknek és e szék teteje kerekded vala hátul, és karjai valának mindkétfelől az ülés mellett, és két oroszlán álla ott a karoknál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'És tizenkét oroszlán álla ott kétfelől a grádics hat lépésén. Senki soha olyant nem csinált egyetlen országban sem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'És Salamon királynak összes ivóedényei is aranyból voltak, és a Libánon erdő házának összes edényei tiszta aranyból; nem volt azok között semmi ezüst, mert annak semmi becse nem vala Salamon idejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'Mert a király Társis hajója, a mely a tengeren Hírám hajójával járt, minden három esztendőben egyszer fordult meg, s hozott a Társis hajó aranyat, ezüstöt, elefántcsontokat, majmokat és pávákat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'És feljebb magasztaltaték Salamon király gazdagsággal és bölcseséggel a földön való minden királyoknál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, 'És mind az egész föld kivánja vala látni Salamont, hogy hallhatnák az ő bölcseségét, melyet Isten az ő szívébe adott volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'És azok néki ajándékot hoznak vala, ezüst és arany edényeket, öltözeteket, hadi szerszámokat, fűszerszámokat, lovakat, öszvéreket, esztendőnként.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'És gyűjte Salamon szekereket és lovagokat, úgy hogy ezer és négyszáz szekere, és tizenkétezer lovagja volt néki, a kiket helyheztete a szekerek városaiba, és a király mellé Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'És felhalmozá a király Jeruzsálemben az ezüstöt mint a követ, és a czédrust, mint a vad fügefákat, a melyek nagy tömegben vannak a mezőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'És Salamonnak Égyiptomból hozának lovakat, és a király kereskedői sereggel vették volt a lovakat megszabott áron.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'És egy-egy szekér hatszáz ezüst siklusért és egy-egy ló százötven siklusért ment fel és jött ki Égyiptomból, és ugyancsak ők szállították ezeket a Hitteusok királyainak és Siria királyainak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'Salamon király pedig megszerete sok idegen asszonyt, még pedig a Faraó leányán kivül a Moábiták, Ammoniták, Edomiták, Sídonbeliek és Hitteusok leányait,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, 'Olyan népek közül, a kik felől azt mondotta volt az Úr az Izráel fiainak: Ne menjetek hozzájok, és őket se engedjétek magatokhoz jőni, bizonyára az ő isteneik után hajtják a ti szíveteket. Ezekhez ragaszkodék Salamon szeretettel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, 'És valának néki feleségei, hétszáz királynéasszony és háromszáz ágyas; és az ő feleségei elhajták az ő szívét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'És mikor megvénült Salamon, az ő feleségei elhajták az ő szívét az idegen istenek után, úgy hogy nem volt már az ő szíve tökéletes az Úrhoz, az ő Istenéhez, a mint az ő atyjának, Dávidnak szíve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, 'Mert Salamon követi vala Astoretet, a Sídonbeliek istenét, és Milkómot, az Ammoniták útálatos bálványát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'És gonosz dolgot cselekedék Salamon az Úr szemei előtt, és nem követé olyan tökéletességgel az Urat, mint Dávid, az ő atyja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'Akkor építe Salamon templomot Kámosnak, a Moábiták útálatos bálványának a hegyen, a mely Jeruzsálem átellenében van, és Moloknak, az Ammon fiai útálatos bálványának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, 'És ekképen cselekedék Salamon mind az ő idegen feleségeivel, a kik az ő isteneiknek tömjéneztek és áldoztak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'Megharaguvék azért az Úr Salamonra, hogy elhajlott az ő szíve az Úrtól, Izráel Istenétől, a ki megjelent volt néki kétszer is,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, 'És azt parancsolta volt néki, hogy ne kövessen idegen isteneket, és mégsem őrizte meg az Úr parancsolatját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'Monda azért az Úr Salamonnak: Miután ez történt veled, és nem őrizted meg az én szövetségemet és az én rendelésimet, a melyeket parancsoltam néked: elszakasztván elszakasztom tőled az országot, és adom a te szolgádnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, 'Mindazáltal míg élsz, nem cselekeszem ezt Dávidért, a te atyádért; hanem a te fiadnak kezétől szakasztom el azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, 'De nem szakasztom el az egész birodalmat; hanem egy nemzetséget adok a te fiadnak Dávidért, az én szolgámért és Jeruzsálemért, a melyet magamnak választottam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, 'És ellenséget támaszta az Úr Salamonra, az Edombeli Hadádot, a ki az Edombeli királyi nemből való vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, 'Mert mikor Dávid az Edomiták ellen ment volt, és Joáb, a sereg fővezére elment volt a megöletteknek temetésére, és levágott minden férfiú nemet Edomban, –');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, 'Mert hat hónapig volt ott Joáb az egész Izráellel, míg minden férfiúi nemet ki nem vesztett Edomban, -');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'Akkor szaladott vala el Hadád és vele együtt valami Edomiták az ő atyjának szolgái közül ő vele, bemenvén Égyiptomba. Hadád pedig akkor még kis gyermek volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, 'Kik felkelvén Midiánból, menének Páránba, és melléjök vévén a Páránbeli férfiak közül, bemenének Égyiptomba a Faraóhoz, az Égyiptombeli királyhoz, a ki házat ada néki, és ételt, italt szolgáltata néki, és jószágot is ada néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'Igen kedvében lőn azért Hadád a Faraónak, úgyannyira, hogy feleségül adá néki az ő feleségének hugát, Táfnes királyasszonynak hugát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'És a Táfnes huga szülé néki Génubátot, az ő fiát, és elválasztá azt Táfnes a Faraó házában, és Génubát ott volt a Faraó házában, a Faraó fiai között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'Mikor pedig Hadád meghallotta Égyiptomban, hogy Dávid elaludt az ő atyáival, és hogy Joáb is, a seregnek fővezére, meghalt, monda Hadád a Faraónak: Bocsáss el engem, hadd menjek el az én földembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'És felele néki a Faraó: Mi nélkül szűkölködöl én nálam, hogy a te földedbe igyekezel menni? Felele az: Semmi nélkül nem szűkölködöm, de kérlek bocsáss el engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, 'És támaszta az Isten néki más ellenséget is, Rézont, az Eljada fiát, a ki elfutott vala Hadadézertől, a Sóbabeli királytól, az ő urától.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'És hadakozó férfiakat gyűjtött maga mellé, és ő vala a sereg hadnagya, mikor megölé őket Dávid; azután Damaskusba menvén ott lakának, és uralkodának Damaskusban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'És ellensége volt Izráelnek Salamonnak egész életében, a nyomorúságon kivül, a melyet Hadád szerze, és gyűlölte Izráelt, és uralkodott Siriában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'Azután Jeroboám, a Nébát fia, Seredából való Efrateus, – a kinek anyja Sérua, egy özvegy asszony volt – a Salamon szolgája emelte fel kezét a király ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'Annak pedig, a miért felemelte kezét a király ellen, ez volt az oka: Mikor Salamon megépítette Millót, és berakatta az ő atyjának, a Dávid városának romlását;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'Jeroboám erős férfiú vala; és látván Salamon, hogy az ő szolgája az ő dolgában szorgalmatos, reá bízá a József háza gondviselésének egész terhét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'És történt ebben az időben, hogy mikor kiment egyszer Jeroboám Jeruzsálemből, találkozék az úton Ahijával, a Silóbeli prófétával, és rajta új köpönyeg volt, és csak ketten valának a mezőn együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'És megragadván Ahija az új ruhát, a mely azon volt, hasítá azt tizenkét részre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'És monda Jeroboámnak: Vedd el magadnak a tíz részt; mert ezt mondja az Úr, Izráel Istene: Ímé elszakasztom ez országot Salamon kezétől, és néked adom a tíz nemzetséget;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, 'Egy nemzetséget hagyok pedig ő nála az én szolgámért, Dávidért, és Jeruzsálem városáért, a melyet magamnak választottam az Izráel minden nemzetségei közül,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'Még pedig azért, mert elhagytak engem, és imádták Astoretet, a Sídonbeliek istenét, és Kámost, a Moábiták istenét, és Milkomot, az Ammon fiainak istenét, és nem jártak az én utaimban, hogy azt cselekedték volna, a mi tetszett volna az én szemeimnek: az én rendelésimet és végzéseimet, a mint Dávid, az ő atyja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'De nem veszem el az egész birodalmat az ő kezétől, hanem akarom, hogy fejedelem legyen életének minden idejében, Dávidért az én szolgámért, a kit választottam; mivelhogy megőrizte az én parancsolatimat és rendeléseimet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'Hanem az ő fiának kezétől már elveszem a királyságot, és néked adom azt, tudniillik a tíz nemzetséget.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'Az ő fiának pedig egy nemzetséget adok, hogy Dávidnak, az én szolgámnak legyen előttem szövétneke mindenkor Jeruzsálemben, a városban, a melyet magamnak választottam, hogy ott helyheztessem az én nevemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'Téged pedig felveszlek, és uralkodol mindenekben a te lelkednek kívánsága szerint, és király lész az Izráelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'És ha te minden parancsolatimnak engedéndesz, és járándasz az én utaimban, és azt cselekedénded, a mi tetszik nékem, megőrizvén az én rendelésimet és parancsolatimat, a mint Dávid, az én szolgám cselekedett: én veled leszek, és építek néked állandó házat, a mint Dávidnak építettem, és néked adom az Izráelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, 'És megsanyargatom ezért a Dávid magvát: de még sem örökre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'Igyekezik vala pedig Salamon megölni Jeroboámot; ezért felkelvén Jeroboám, futa Égyiptomba, Sésákhoz, az Égyiptombeli királyhoz, és ott volt Égyiptomban, Salamon haláláig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'Salamonnak egyéb dolgai pedig és minden cselekedetei, a melyeket cselekedett, és bölcsesége avagy nem írattattak-é meg a Salamon cselekedeteiről írott könyvben?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'Az az idő pedig, a melyben uralkodott Salamon Jeruzsálemben az egész Izráelen: negyven esztendő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'És elaluvék Salamon az ő atyáival, és eltemetteték az ő atyjának, Dávidnak városában. És Roboám, az ő fia uralkodék helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, 'És elméne Roboám Síkembe; mert Síkembe gyűlt fel az egész Izráel, hogy királylyá tegyék őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'Mikor pedig meghallotta ezt Jeroboám, a Nébát fia, (a ki még Égyiptomban volt, a hová futott volt Salamon király elől, és Égyiptomban tartózkodék Jeroboám,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, 'És hozzá küldvén, elhivaták őt); elmenének Jeroboám és az Izráel egész gyülekezete, és szólának Roboámnak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, 'A te atyád igen megnehezítette a mi igánkat, de te most könnyebbítsd meg atyádnak kemény szolgálatát, és a nehéz igát, a melyet mi reánk vetett, és szolgálunk néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'És monda nékik: Menjetek el, és harmadnap mulva jőjjetek vissza hozzám. És a nép elméne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'És tanácsot tarta Roboám király a vénekkel, a kik Salamon, az ő atyja előtt állottak vala életében, mondván: Micsoda tanácsot adtok ti, hogy milyen választ adjak e népnek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, 'És szólának azok, mondván: Ha e mai napon szolgája lész e népnek, és nékik szolgálsz, és választ adsz nékik, és jó szót adsz nékik: mind éltig szolgálnak néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, 'De ő megveté a vének tanácsát, a melyet néki adtak, és tanácsot tarta az ifjakkal, a kik ő vele együtt nevekedtek volt fel, és a kik ő előtte udvarlottak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, 'És monda azoknak: Micsoda tanácsot adtok ti, hogy választ adjunk e népnek, a mely nékem szólván, azt mondja: Könnyebbítsd meg az igát, a melyet reánk vetett a te atyád?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, 'És mondának néki az ifjak, a kik együtt nevekedtek volt fel ő vele: Így szólj ennek a népnek, a mely szólván néked, ezt mondja: A te atyád megnehezítette a mi igánkat, te pedig könnyebbítsd meg nékünk; e képen szólj nékik: Az én kis ujjam vastagabb az én atyám derekánál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'Most azért, ha az én atyám reátok nehéz igát vetett, én még nehezebbé teszem a ti igátokat: ha az én atyám ostorral fékezett titeket, én skorpiókkal ostorozlak benneteket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'És elméne Jeroboám és mind az egész nép Roboámhoz harmadnap, a mint meghagyta volt a király, ezt mondván: Jőjjetek hozzám harmadnapon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'És a király kemény választ adott a népnek, megvetve a vének tanácsát, a melyet adtak vala néki;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'És szóla nékik az ifjak tanácsa szerint, mondván: Ha az én atyám megnehezítette a ti igátokat, én még nehezebbé teszem azt; ha az én atyám ostorral fékezett titeket, én skorpiókkal ostorozlak benneteket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'És nem hallgatá meg a király a népet; mert ezt az Úr fordította ekként, hogy megerősítse az ő beszédét, a melyet szólott volt az Úr a Silóbeli Ahija által Jeroboámnak, a Nébát fiának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'Mikor pedig látta az egész Izráel, hogy meg nem hallgatta őket a király, felele az egész nép a királynak ekképen: Micsoda részünk van nékünk Dávidban? Nincsen nékünk örökségünk az Isai fiában: menj el a te hajlékidba, óh Izráel! Most viseld gondját immár a te házadnak, óh Dávid! Elméne azért az Izráel az ő hajlékiba;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, 'Úgy hogy Roboám csak azokon az Izráel fiain uralkodék, a kik Júda városaiban laktak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'És a mikor elküldé Roboám király Adorámot, az adószedőt, megkövezé őt az egész Izráel, és meghala, és maga Roboám király is hamarsággal szekerébe üle, hogy elmeneküljön Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, 'Így szakada el az Izráel népe Dávidnak házától mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'És lőn, mikor meghallotta az egész Izráel, hogy megjött Jeroboám, érette küldvén, hivaták őt a gyülekezetbe, és királylyá tevék őt az egész Izráelen; senki pedig nem követé Dávidnak házát, hanem csak egyedül a Júda nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'És mikor megérkezett Roboám Jeruzsálembe, összegyűjté Júda egész házát és Benjámin nemzetségét, száznyolczvanezer válogatott hadra való férfiút, hogy hadakozzanak az Izráel házával, és visszanyerjék az országot Roboámnak, a Salamon fiának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'De az Isten beszéde lőn Sémajához, az Isten emberéhez, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, 'Ezt mondjad Roboámnak, a Salamon fiának, a Júda királyának, és az egész Júda és Benjámin házának, és a többi népnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, 'Azt mondja az Úr: Fel ne menjetek, és ne hadakozzatok a ti atyátokfiai ellen, az Izráel ellen; térjetek meg kiki a maga házába, mert én tőlem lett e dolog. És ők engedének az Úr beszédének, és visszatérvén, elmenének az Úr beszéde szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, 'Jeroboám pedig megépíté Síkemet az Efraim hegyén, és abban lakék; és onnét kimenvén, építé Pénuelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'És monda Jeroboám az ő szívében: Majd visszatér ez ország a Dávid házához;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'Ha felmegy a nép, hogy áldozatot tegyen Jeruzsálemben az Úrnak házában; e népnek szíve az ő urához, Roboámhoz, a Júda királyához hajol, és engem megölnek, és visszatérnek Roboámhoz, a Júda királyához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'Tanácsot tartván azért a király, csináltata két arany borjút, és monda nékik: Sok néktek Jeruzsálembe felmennetek: Ímhol vannak a te isteneid, óh Izráel, a kik téged kihoztak Égyiptomnak földéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'És az egyiket helyhezteté Béthelbe, a másikat pedig Dánba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'És e dolog nagy bűnnek lett az okozója, mert a nép felment az egyik elé egészen Dánig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'Azután felállítá a magas helyek templomát, és papokat szerze a nép aljából, a kik nem voltak a Lévi fiai közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'És szerze Jeroboám egy ünnepet is a nyolczadik hónapban, a hónap tizenötödik napján, a Júdabeli ünnep módja szerint, és áldozék az oltáron. Hasonlóképen cselekedék Béthelben is, áldozván a borjúknak, a melyeket csinált vala, és szerze Béthelben papokat a magaslatokhoz, a melyeket csinált vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'És áldozék azon az oltáron is, a melyet Béthelben állított fel, a nyolczadik hónap tizenötödik napján, abban a hónapban, a melyet az ő szívében gondolt vala; és ünnepet szerze az Izráel fiainak, és felméne az oltárra, hogy jóillatot szerezzen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'És ímé Isten embere jöve Júdából Béthelbe, az Úrnak intésére, és Jeroboám ott állott az oltár mellett, hogy tömjént gyújtson.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'És kiálta az oltár ellen az Úr intése szerint, és monda: Oltár, oltár! ezt mondja az Úr: Ímé egy fiú születik a Dávid házából, a kinek neve Józsiás lészen, a ki megáldozza rajtad a magaslatok papjait, a kik most te rajtad tömjéneznek, és emberek csontjait égetik meg rajtad,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'És ugyanazon napon csudát tőn, mondván: E lészen jegye, hogy az Úr mondotta légyen ezt: Ímé az oltár meghasad, és kiomol a hamu, mely rajta van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'És a mikor meghallotta a király az Isten emberének beszédét, a melyet kiáltott vala az oltár ellen Béthelben, kinyújtá Jeroboám az ő kezét az oltártól, mondván: Fogjátok meg őt. És megszárada az ő keze, a melyet kinyújtott volt ellene, és nem tudta azt magához visszavonni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'És meghasadt az oltár, és kiomlott a hamu az oltárról a jel szerint, a melyet tett vala az Isten embere az Úrnak beszéde által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'És szóla a király, és monda az Isten emberének: Könyörögj az Úrnak a te Istenednek, és imádkozz érettem, hogy ismét hozzám hajoljon az én kezem. És mikor könyörgött az Isten embere az Úrnak, visszahajla a király keze, és olyan lőn, mint azelőtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'És monda a király az Isten emberének: Jere haza velem és egyél ebédet, meg akarlak ajándékozni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'És monda az Isten embere a királynak: Ha a te házadnak felét nékem adnád is, nem mennék el veled, és nem enném kenyeret, sem vizet nem innám e helyen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'Mert azt parancsolta az Úr nékem az ő beszéde által, mondván: Ne egyél ott kenyeret, vizet se igyál; vissza se térj az úton, a melyen elmenéndesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'És elméne más úton, és nem tére meg azon az úton, a melyen Béthelbe ment.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'És lakozék Béthelben egy vén próféta, a kihez eljövén az ő fia, elbeszélé az ő atyjának mindazt a dolgot, a melyet aznap az Isten embere cselekedett volt Béthelben, és a beszédeket, a melyeket szólott vala a királynak; és elbeszélék azokat az ő atyjoknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'Akkor monda nékik az ő atyjok: Mely úton ment el? És megmutaták az ő fiai az útat, a melyen elment volt az Isten embere, a ki Júdából jött.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'És monda az ő fiainak: Nyergeljétek meg nékem a szamarat; és mikor megnyergelék néki a szamarat, felüle reá,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'És elméne az Isten embere után, és megtalálá őt egy cserfa alatt ülve, és monda néki: Te vagy-é amaz Isten embere, a ki Júdából jöttél? És monda: Én vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'Akkor monda néki: Jere haza velem és egyél kenyeret.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'De az felele: Nem mehetek vissza veled, be sem mehetek veled; nem eszem kenyeret, vizet sem iszom veled e helyen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'Mert meg van nékem az Úrnak beszédével parancsolva: Ne egyél kenyeret, vizet se igyál ott, és ne térj azon az úton vissza, a melyen oda menéndesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'És felele az néki: Én is olyan próféta vagyok, mint te, és nékem angyal szólott az Úrnak beszédével, mondván: Hozd vissza őt veled a te házadba, hogy kenyeret egyék és vizet igyék. És e képen hazuda néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'Megtére azért vele, és kenyeret evék az ő házában, és vizet ivék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'Mikor pedig az asztalnál ülének: lőn az Úr beszéde a prófétához, a ki őt visszahozta vala,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'És kiálta az Isten emberének, a ki Júdából jött vala, ezt mondván: Ezt mondja az Úr: Mivelhogy engedetlen voltál az Úr szájának, és meg nem tartottad a parancsolatot, a melyet néked az Úr, a te Istened parancsolt volt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'Hanem visszatértél, és kenyeret ettél és vizet ittál azon a helyen, a mely felől azt mondotta vala néked: Ne egyél ott kenyeret, vizet se igyál: Nem temettetik a te tested a te atyáid sírjába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'És miután evett kenyeret és ivott, megnyergelék a szamarat a prófétának, a kit visszahozott vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'És mikor elment, egy oroszlán találá őt az úton, a mely megölé őt; és az ő teste az úton fekszik vala, és mind a szamár, mind az oroszlán a holttest mellett állanak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'És ímé az arra menő emberek láták az úton heverő testet, és az oroszlánt a holttest mellett állani; és elmenvén, elbeszélék a városban, a melyben a vén próféta lakott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'A mit mikor meghallott a próféta, a ki visszahozta vala őt az útról, monda: Az Isten embere az, a ki engedetlen volt az Úr szájának; ezért adta az Úr őt az oroszlánnak, és az törte össze és ölte meg őt, az Úrnak beszéde szerint, a melyet szólott volt néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'És szóla az ő fiainak, mondván: Nyergeljétek meg nékem a szamarat. És felnyergelték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'És ő elment és megtalálá a holttestet az útfélre vetve, és a szamarat és az oroszlánt a holttest mellett állva. Az oroszlán nem evett a holtból, és a szamarat sem tépte szét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'És felvevé a próféta az Isten emberének holttestét, és feltevé azt a szamárra, és visszahozá azt, és beméne a városba a vén próféta, hogy ott sirassa és eltemesse őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'És eltemeté a holtat a maga sírboltjába, és siraták őt: Ah szerelmes atyámfia!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'És miután eltemette őt, szóla az ő fiainak, mondván: Ha meghalok, ebbe a sírba temessetek engem is, a melybe az Isten embere temettetett, tetemimet tegyétek az ő tetemei mellé;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'Mert beteljesedik az, a mit kiáltott az Úrnak beszédével az oltár ellen, a mely Béthelben van, és a magas helyeken való házak ellen, a melyek Samaria városaiban vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'De még e történet után sem tért meg Jeroboám az ő gonosz útjáról, hanem ismét papokat rendele a nép aljából a magaslatokra, és a ki akarja vala, azt szentelé fel, hogy legyen a magaslatok papja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'És ez a dolog lett az oka a Jeroboám háza vétkének, és a föld színéről való kiirtatásának és megsemmisíttetésének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'Ebben az időben megbetegedék Abija, a Jeroboám fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'És monda Jeroboám az ő feleségének: Kelj fel most, és változtasd meg öltözetedet, hogy meg ne ismerjék, hogy te vagy Jeroboám felesége, és menj el Silóba: Ímé ott van Ahija próféta, a ki nékem megmondotta volt, hogy királylyá leszek e népen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'És végy magadhoz tíz kenyeret és pogácsát, és egy edényben mézet, és menj el hozzá; ő majd megmondja néked, mi történik a gyermekkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'És e képen cselekedék a Jeroboám felesége; és felkészülvén, elméne Silóba, és beméne az Ahija házába. Ahija azonban már nem látott; mert meghomályosodtak az ő szemei a vénség miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'És az Úr monda Ahijának: Ímé a Jeroboám felesége jött hozzád, hogy valamit kérdjen tőled az ő fia felől, mert beteg; te azért így s így szólj néki. És mikor bement, másnak tetteté magát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'De mikor meghallotta Ahija az ő lábainak zörejét, a mint az ajtóhoz közelgete, monda: Jőjj be Jeroboám felesége; miért tetteted magadat másnak? Én te hozzád kemény követséggel küldettem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, 'Menj el, mondd meg Jeroboámnak: Ezt mondja az Úr, Izráelnek Istene: Mivelhogy én téged e nép közül felmagasztaltalak, és téged fejedelemmé tettelek az én népemen, az Izráelen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'És elszakasztottam az országot a Dávid házától, és azt néked adtam; te azonban nem voltál olyan, mint az én szolgám, Dávid, a ki megőrizte az én parancsolatimat, és a ki engem követett teljes szívéből, csak azt cselekedvén, a mi kedves az én szemeim előtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'Hanem gonoszabbul cselekedtél mindazoknál, a kik te előtted voltak; mert elmentél és idegen isteneket csináltál magadnak, és öntött bálványokat, hogy engem haragra ingerelj, és engem hátad mögé vetettél:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'Azért ímé én veszedelmet hozok a Jeroboám házára, és kiirtom Jeroboámnak még az ebét is, és mind a berekesztettet, mind az elhagyottat Izráelben, és kihányom a Jeroboám háza maradékait, miképen a ganéjt kihányják, mígnem vége lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'A ki meghal a Jeroboám maradékai közül a városban, azt az ebek eszik meg; a ki pedig a mezőn hal meg, az égi madarak eszik meg; mert az Úr szólott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'Te pedig kelj fel, és menj haza, mert a mint belépsz a városba, meghal a gyermek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'És az egész Izráel siratja őt, és eltemeti őt, mert a Jeroboám magvából csak egyedül ő temettetik el sírba, mivel a Jeroboám háznépe közül az Úr iránt, Izráel Istene iránt csak ő benne találtatott valami jó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'És támaszt az Úr magának királyt Izráelben, a ki kigyomlálja a Jeroboám házát egy napon. De mit mondok? Már is támasztott!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'És megveri az Úr az Izráelt, mint a hogy a nád a vízben ide s tova hányattatik, és elszakasztja az Izráelt erről a jó földről, a melyet adott az ő atyáiknak, és szétszórja őket a folyóvizen túl, mivelhogy Aserákat csináltak magoknak, hogy az Urat ingereljék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'És kézbe adja az Izráelt a Jeroboám bűneiért, a ki maga is vétkezett és az Izráelt is bűnbe ejtette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'És felkészült a Jeroboám felesége, elment és juta Thirsába. És mikor a ház küszöbén belépett, meghalt a gyermek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'És eltemeték őt, és siratá őt az egész Izráel, az Úrnak beszéde szerint, a melyet szólott az ő szolgája, Ahija próféta által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'Jeroboámnak pedig egyéb cselekedetei, mimódon hadakozott és uralkodott, ímé meg vannak írva az Izráel királyainak krónika-könyvében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'És az idő, a melyben uralkodott Jeroboám, huszonkét esztendő, és elaluvék az ő atyáival, és uralkodék Nádáb, az ő fia, ő helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'Roboám pedig, a Salamon fia Júdában uralkodék: Negyvenegy esztendős volt Roboám, mikor uralkodni kezdett, és tizenhét esztendeig uralkodott Jeruzsálemben, abban a városban, a melyet az Úr választott volt magának az Izráelnek minden nemzetségei közül, hogy ott helyheztesse az ő nevét; és az ő anyjának Naama volt a neve, a ki az Ammon nemzetségéből való volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'Júda is gonoszul cselekedék az Úr szemei előtt, és sokkal nagyobb haragra indíták őt az ő vétkeikkel, a melyekkel vétkeztek, mint atyáik azokkal, a melyeket ők cselekedtek volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, 'Mert ők is építének magoknak magaslatokat, és faragott képeket és Aserákat minden magas halmon, és minden zöldellő fa alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'És valának férfi paráznák is az országban, és cselekedének a pogányok minden útálatos vétkei szerint, a kiket az Úr kiűzött volt az Izráel fiai előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'És lőn Roboám király ötödik esztendejében, feljött Sisák, az Égyiptombeli király Jeruzsálem ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'És elvivé az Úr házának kincseit, és a király házának kincseit, és mindent, a mi csak elvihető volt; elvitte mind az arany paizsokat is, a melyeket Salamon csináltatott,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'A melyek helyett Roboám király azután rézpaizsokat csináltatott, és adá azokat a testőrök fejedelmeinek kezébe, a kik a király házának kapunállói valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'És valahányszor a király bement az Úr házába, bevitték azokat a testőrök, és ismét visszahozták a testőrök házába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'Roboámnak pedig több dolgai és minden cselekedetei, nemde nem meg vannak-é írva a Júda királyainak krónika-könyvében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'És folyton hadakozás volt Roboám és Jeroboám között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'És elaluvék Roboám az ő atyáival, és eltemetteték az ő atyáival a Dávid városában; és az ő anyjának Naama volt a neve, az Ammoniták nemzetségéből való; és Abija, az ő fia, lett a király ő helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'Jeroboám királynak, a Nébát fiának tizennyolczadik esztendejében Abija lett a király Júdában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'És három esztendeig uralkodott Jeruzsálemben. Az ő anyjának neve Maaka, az Abisálom leánya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'És járt az ő atyjának minden bűneiben, a melyeket ő előtte cselekedett, és nem volt az ő szíve olyan tökéletes az ő Urához Istenéhez, mint Dávidnak, az ő atyjának szíve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'De mindazáltal Dávidért adott néki az Úr az ő Istene szövétneket Jeruzsálemben: felmagasztalván az ő fiát ő utána és Jeruzsálemet megerősítvén;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'Mert Dávid azt cselekedte, a mi kedves volt az Úr szemei előtt, és el nem távozott azoktól, a melyeket parancsolt néki az ő életének minden idejében, kivéve a Hitteus Uriás dolgát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, 'És hadakozás volt Roboám és Jeroboám között mind éltig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'Abija egyéb dolgai és minden cselekedetei pedig vajjon nincsenek-é megírva a Júda királyainak krónika-könyvében? És hadakozás volt Abija és Jeroboám között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'És elaluvék Abija az ő atyáival, és eltemeték őt a Dávid városában; és uralkodék helyette Asa, az ő fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'Jeroboámnak az Izráel királyának a huszadik esztendejében Asa lett a király Júdában,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'És uralkodék negyvenegy esztendeig Jeruzsálemben; és az ő anyjának Maaka vala neve, az Abisálom leánya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'És Asa azt cselekedé, a mi kedves volt az Úr szemei előtt, mint Dávid, az ő atyja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'Mert kiveszté a férfiú paráznákat az országból; és lerontá mind a bálványokat, a melyeket csináltak volt az ő atyái.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'És Maakát az ő anyját is megfosztá a királynéságtól, mivelhogy egy iszonyú bálványt csináltatott a berekben; és elrontá Asa az ő bálványát, és megégeté azt a Kidron pataknál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'De ha a magaslatokat nem rontották is le, mégis Asának szíve tökéletes volt az Úrhoz életének minden napjaiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'És bevitte az Úrnak házába az ezüstöt és az aranyat, és az edényeket, a melyeket az ő atyja és ő maga arra szenteltek volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'És hadakozás volt Asa és Baása, az Izráel királya között mind éltig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'Mert feljöve Baása, az Izráel királya Júda ellen, és megépíté Rámát, hogy senkit ki és be ne bocsásson Asához a Júda királyához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'És vévén Asa mind az ezüstöt és aranyat, a mely megmaradott volt mind az Úr, mind a király házának kincseiből; adá azt az ő szolgáinak kezébe, és elküldé azt Asa király Benhadádnak, Tabrimmon fiának, a ki Héczion fia volt, Siria királyának, a ki Damaskusban lakott, ezt izenvén néki:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, 'Szövetség van köztem és te közötted, az én atyám és a te atyád között. Ímé ajándékot küldök néked, ezüstöt és aranyat, bontsd fel a te szövetségedet Baásával, az Izráel királyával, hogy távozzék el tőlem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'És Benhadád engedelmeskedett Asa királynak és elküldé az ő seregeinek vezéreit az Izráel városai ellen; és bevevé Hijont és Dánt, és Abel Beth-Maakát, és az egész Kinneróthot a Nafthali egész földével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'Mikor pedig Baása ezt meghallotta, abbahagyta Ráma építését, és lakék Thirsában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'Akkor Asa király egybegyűjté az egész Júdát, senkit ki nem hagyván, és elhordák Rámának mind köveit, mind fáját, a melyekkel Baása épített volt, és építé azokból Asa király Gébát, a Benjámin nemzetségében és Mispát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'Asának minden egyéb dolgai pedig és egész uralkodása és valamit cselekedett, és a városok, a melyeket épített, vajjon nincsenek-é megírva a Júda királyainak krónika-könyvében? kivéve azt, hogy vénségében megbetegedett a lábaira.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'És elaluvék Asa az ő atyáival, és eltemetteték az ő atyáival Dávidnak, az ő atyjának városában. És Jósafát, az ő fia, uralkodék helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'Izráelben pedig Nádáb, a Jeroboám fia lett a király, Asának, a Júdabeli királynak második esztendejében; és két esztendeig uralkodék Izráelen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'És gonoszul cselekedék az Úrnak szemei előtt és jára az ő atyjának útján és annak vétkében, a melylyel bűnbe ejtette volt az Izráelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'De Baása, az Ahija fia, az Issakhár nemzetségéből, pártot ütött ellene, és megveré őt Baása Gibbethonnál a Filiszteusok városánál; mert Nádáb és az egész Izráel Gibbethonnál táboroztak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'És megölé őt Baása, Asának, a júdabeli királynak harmadik esztendejében, és uralkodék helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'És lőn, mikor uralkodni kezdett, levágá Jeroboámnak egész háznépét; egy lelket sem hagyott Jeroboám háznépéből, mígnem mind elveszté őket az Úrnak beszéde szerint, a melyet megmondott volt az ő szolgája, a Silóbeli Ahija által,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'A Jeroboám vétkeiért, a melyekkel vétkezék és az Izráelt is vétekbe ejté; és a bosszantásért, a melylyel felbosszantotta az Urat, Izráel Istenét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'Nádáb egyéb dolgai pedig és minden cselekedetei, vajjon nincsenek-é megírva az Izráel királyainak krónika-könyvében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'És hadakozás volt Asa és Baása, az Izráel királya között mind éltig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'Asának, a Júdabeli királynak harmadik esztendejében lett Baása, az Ahija fia királylyá az egész Izráelen Thirsában, huszonnégy esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'És gonoszul cselekedék az Úrnak szemei előtt, és jára a Jeroboám útján, és az ő vétkében, a melylyel bűnbe ejtette az Izráelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'Lőn azonban az Úrnak beszéde Jéhuhoz, a Hanáni fiához, Baása ellen, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, 'Mivelhogy téged felemeltelek a porból, és fejedelemmé tettelek téged az én népemen, az Izráelen, te pedig a Jeroboám útján jársz, és bűnbe ejted az én népemet, az Izráelt, hogy engem haragra indítsanak az ő vétkeikkel:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'Íme én elvetem Baása maradékait, és az ő háza maradékait, és olyanná teszem a te házadat, mint Jeroboámnak, a Nébát fiának házát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'A ki Baása maradékai közül a városban hal meg, azt az ebek eszik meg; a ki pedig a mezőn halánd meg, azt az égi madarak eszik meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'Baása több dolgai pedig, és a mit cselekedett, és az ő uralkodása vajjon nincsenek-é megírva az Izráel királyainak krónika-könyvében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'És elaluvék Baása az ő atyáival, és eltemetteték Thirsában, és az ő fia, Ela uralkodék ő utána.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'És nemcsak azért lőn az Úrnak beszéde Jéhu próféta, a Hanáni fia által Baása és az ő háza ellen és minden ő gonoszsága ellen, a melyet cselekedett volt az Úr szemei előtt, őt haragra indítván az ő kezeinek cselekedetei által, hogy olyan lesz mint a Jeroboám háza, hanem azért is, mert azt megölte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'És Asának, a Júda királyának huszonhatodik esztendejében lett királylyá Ela, a Baása fia, az Izráelen Thirsában, két esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'Azonban az ő szolgája Zimri, a szekerek fél részének feje, pártot ütött ellene. És Ela Thirsában volt, és az ital miatt igen megrészegedett az Arsa házában, a ki az ő házának Thirsában gondviselője volt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'És eljövén Zimri, megveré és megölé őt, Asának, a Júdabeli királynak huszonhetedik esztendejében, és ő uralkodék helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'Mikor pedig királylyá lett és trónját elfoglalta, kiirtá Baása egész házát minden rokonságával és barátaival együtt és nem hagyott belőle még csak egy ebet sem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'Így veszté ki Zimri a Baása egész házát, az Úrnak beszéde szerint, a melyet Baása ellen szólott Jéhu próféta által:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'Baása minden vétkeiért, és Elának, az ő fiának vétkeiért, a kik vétkeztek és vétekbe ejtették az Izráelt, haragra indítván az Urat, Izráelnek Istenét az ő bálványozásukkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'Elának egyéb dolgai pedig és minden cselekedetei, vajjon nincsenek-é megírva az Izráel királyainak krónika-könyvében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'Asának, a Júdabeli királynak huszonhetedik esztendejében, uralkodék Zimri hét napig Thirsában; a nép pedig Gibbethon előtt táborozott, a mely a Filiszteusoké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'Mikor pedig hallotta a nép a táborban beszélni, hogy pártot ütött Zimri és a királyt meg is ölte: az egész Izráel azon a napon Omrit, az Izráel seregeinek fővezérét választá királylyá a táborban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'És felvonult Omri és az egész Izráel ő vele Gibbethonból, és megszállák Thirsát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'De Zimri, a mikor látta, hogy a várost bevették, bemenvén a királyi ház palotájába, tűzzel magára gyújtá a királyi házat, és meghala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'Az ő bűneiért, a melyekkel vétkezék, gonoszul cselekedvén az Úr szemei előtt; járván a Jeroboám útjában és az ő bűnében, a melyet cselekedett volt, vétekbe ejtvén az Izráelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'Zimrinek egyéb dolgai pedig és az ő pártütése, a melyet cselekedett, vajjon nincsenek-é megírva az Izráelbeli királyok krónika-könyvében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'Akkor kétfelé hasonlék az Izráel népe: a nép egyik része Tibnit, a Ginát fiát követte és azt tette királylyá, a másik része pedig Omrihoz ragaszkodott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'De a népnek az a része, a mely Omrihoz ragaszkodott, erősebb volt, mint az a nép, a mely Tibnit, a Ginát fiát követte, és meghalván Tibni, uralkodék Omri.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'Asának, a Júdabeli királynak harminczegyedik esztendejében uralkodék Omri Izráelben tizenkét esztendeig; Thirsában uralkodék hat esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'És megvevé áron a Samaria hegyét Sémertől két tálentom ezüstön; és építe a hegyre, és nevezé a várost, a melyet építe, Sémernek, a hegy urának nevéről, Samariának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'És gonoszul cselekedék Omri az Úr szemei előtt, és gonoszságával meghaladá mind az ő előtte valókat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'És jára Jeroboámnak, a Nébát fiának minden útján és az ő bűnében, a melylyel vétekbe ejté az Izráelt, haragra indítván az Urat, Izráel Istenét az ő bálványozásai által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'Omrinak egyéb dolgai pedig és minden cselekedetei és az ő erőssége, a melylyel cselekedett, vajjon nincsenek-é megírva az Izráelbeli királyok krónika-könyvében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'És elaluvék Omri az ő atyáival, és eltemetteték Samariában, és uralkodék ő utána az ő fia, Akháb.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'Akháb pedig, az Omri fia uralkodni kezde Izráelen, Asának, a Júdabeli királynak harmincznyolczadik esztendejében; és uralkodék Akháb, az Omri fia, Izráelen Samariában huszonkét esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'És gonoszabbul cselekedék Akháb, az Omri fia az Úr szemei előtt mindazoknál, a kik ő előtte voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'Mert nem elégedék meg azzal, hogy Jeroboámnak, a Nébát fiának bűneiben járjon, hanem elméne és feleségül vevé magának Jézabelt, Ethbaálnak, a Sídonbeli királynak leányát, és elmenvén, a Baálnak szolgála, és meghajtá magát annak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'És oltárt emele a Baálnak a Baál házában, a melyet Samariában épített.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'És csinált Akháb Aserát is, és jobban haragra indítá Akháb az Urat, Izráel Istenét, mint az Izráel valamennyi királya, a kik ő előtte voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'Ennek idejében építé meg a Béthelbeli Hiel Jérikhót. Az ő elsőszülött fiának, Abirámnak élete árán veté meg annak fundamentomát, és az ő kisebbik fiának, Ségubnak élete árán állítá fel annak kapuit, az Úr beszéde szerint, a melyet szólott volt Józsué, a Nún fia által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'És szóla Thesbites Illés, a Gileád lakói közül, Akhábnak: Él az Úr, az Izráel Istene, a ki előtt állok, hogy ez esztendőkben sem harmat, sem eső nem lészen; hanem csak az én beszédem szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'És lőn az Úrnak beszéde ő hozzá, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, 'Menj el innét, és menj napkelet felé, és rejtezzél el a Kérith patakja mellett, mely a Jordán felé folyik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'És a patakból lesz néked italod; a hollóknak pedig megparancsoltam, hogy tápláljanak téged ott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'Elméne azért, és az Úrnak beszéde szerint cselekedék; és elméne és leüle a Kérith patakja mellett, a mely a Jordán felé folyik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'És a hollók hoztak néki kenyeret és húst reggel és este, és a patakból ivott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'És lőn néhány nap múlva, hogy kiszáradt a patak; mert nem volt eső a földre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'És lőn az Úrnak beszéde ő hozzá, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, 'Kelj fel, és menj el Sareptába, a mely Sídonhoz tartozik, és légy ott; ímé megparancsoltam ott egy özvegyasszonynak, hogy gondoskodjék rólad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'És felkelvén, elméne Sareptába, és mikor a város kapujához érkezett, ímé egy özvegyasszony volt ott, a ki fát szedegetett, és megszólítván azt, monda néki: Hozz, kérlek, egy kevés vizet nékem valami edényben, hogy igyam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'De mikor az elment, hogy vizet hozzon, utána kiáltott, és monda néki: Hozz, kérlek, egy falat kenyeret is kezedben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'Az pedig monda: Él az Úr, a te Istened, hogy nincs semmi sült kenyerem, csak egy marok lisztecském van a vékában, és egy kevés olajom a korsóban, és most egy kis fát szedegetek, és haza megyek, és megkészítem azt magamnak és az én fiamnak, hogy megegyük és azután meghaljunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'Monda pedig néki Illés: Ne félj, menj el, cselekedjél a te beszéded szerint; de mindazáltal nékem süss abból először egy kis pogácsát, és hozd ide; magadnak és a te fiadnak pedig azután süss;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'Mert azt mondja az Úr, Izráel Istene, hogy sem a vékabeli liszt el nem fogy, sem a korsóbeli olaj meg nem kevesül addig, míg az Úr esőt ád a földnek színére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'És ő elméne, és az Illés beszéde szerint cselekedék, és evék mind ő, mind amaz, mind annak háznépe, naponként.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'A vékabeli liszt nem fogyott el, sem pedig a korsóbeli olaj nem kevesült meg, az Úrnak beszéde szerint, a melyet szólott Illés által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'És lőn ezek után, hogy megbetegedék a ház gazdasszonyának fia, és az ő betegsége felette nagy vala, annyira, hogy már a lélekzete is elállott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'Monda azért Illésnek: Mit vétettem ellened, Istennek embere? Azért jöttél hozzám, hogy eszembe juttassad álnokságomat, és megöljed az én fiamat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'És monda néki: Add ide a te fiadat. És ő elvevé azt az ő kebeléről, és felvivé a felházba, a melyben ő lakik vala, és az ő ágyára fekteté.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'Akkor kiálta az Úrhoz, és monda: Én Uram, Istenem, nyomorúságot hozol erre az özvegyre is, a kinél én lakom, hogy az ő fiát megölöd?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'És ráborult háromszor a gyermekre, és felkiáltott az Úrhoz, mondván: Én Uram, Istenem, térítsd vissza e gyermek lelkét ő belé!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'És meghallgatta az Úr Illés szavát, és megtért a gyermekbe a lélek, és megélede.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'És felvévén Illés a gyermeket, alávivé őt a felházból a házba, és adá őt az ő anyjának, és monda Illés: Lássad, él a te fiad!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'És monda az asszony Illésnek: Most tudtam meg, hogy te Isten embere vagy, és hogy az Úrnak beszéde a te ajkadon: igazság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'És lőn sok idő multán, a harmadik esztendőben, az Úrnak beszéde Illéshez, mondván: Menj el, mutasd meg magadat Akhábnak, és esőt adok a föld színére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'És elméne Illés, hogy megmutassa magát Akhábnak. Nagy éhség volt pedig Samariában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'És Akháb hivatá Abdiást, a ki az ő házának gondviselője volt. (Abdiás pedig felette igen féli vala az Urat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'Mert mikor Jézabel megölette az Úr prófétáit, Abdiás száz prófétát vett oltalmába, és rejtette el ötvenenként egy-egy barlangba, és ott táplálta őket kenyérrel és vízzel).');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'És monda Akháb Abdiásnak: Menj el az országba szerén-szerte a vizek forrásaihoz és a patakokhoz, hogyha valami füvet találhatnánk, hogy a lovakat és öszvéreket megtarthatnánk életben, és ne hagynánk a barmokat mindenestől elpusztulni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'Eloszták azért magok közt a földet, a melyen kiki elmenjen. Akháb egyedül ment az egyik úton, és Abdiás is egyedül ment a másik úton.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'És mikor Abdiás az úton ment, ímé Illés előtalálá őt, és mikor felismerte őt, arczra borula és monda: Nem te vagy-é az, uram, Illés?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'Felele néki: Én vagyok; menj el, mondd meg a te uradnak: Ímé itt van Illés.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'Ő pedig monda: Mit vétettem ellened, hogy a te szolgádat Akháb kezébe akarod adni, hogy megöljön engem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'Él az Úr a te Istened: nincs sem nemzetség, sem ország, a hova el nem küldött volna az én uram, hogy megkeressen téged. És ha azt mondották: Nincs itt! az országot és a népet megesküdtette, hogy téged csakugyan nem találtak meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'És most te azt mondod: Menj el, mondd meg a te uradnak: Ímé itt van Illés.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'Ha most elmegyek tőled, téged pedig olyan helyre ragad el az Úrnak Lelke, a melyet én nem tudok, és én elmegyek, hogy megmondjam Akhábnak, és ha ő téged nem talál meg, engem öl meg; pedig a te szolgád féli az Urat gyermekségétől fogva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'Nem mondották-é meg az én uramnak, mit cselekedtem, mikor Jézabel megölette az Úr prófétáit? hogy hogyan rejtettem el az Úr prófétái közül száz férfiút ötvenenként egy-egy barlangba és tápláltam őket kenyérrel és vízzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'És te mégis azt mondod: Menj el és mondd meg a te uradnak: Ímé itt van Illés; hogy megöljön engemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'És felele Illés: Él a Seregeknek Ura, a ki előtt állok: e mai napon megmutatom magamat néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'Elméne azért Abdiás Akháb eleibe, és megjelenté ezt néki, és eleibe méne Akháb Illésnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'És mikor meglátta Akháb Illést, monda Akháb néki: Te vagy-é az Izráel megháborítója?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'Ő pedig monda: Nem én háborítottam meg az Izráelt, hanem te és a te atyád háza, azzal, hogy elhagytátok az Úrnak parancsolatait, és a Baál után jártatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'Most azért küldj el, gyűjtsd hozzám az egész Izráelt a Kármel hegyre, és a Baál négyszázötven prófétáját, és az Aserának négyszáz prófétáját, a kik a Jézabel asztaláról élnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'És elkülde Akháb mind az egész Izráel fiaihoz, és egybegyűjté a prófétákat a Kármel hegyre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'És odamenvén Illés az egész sokasághoz, monda: Meddig sántikáltok kétfelé? Ha az Úr az Isten, kövessétek őt; ha pedig Baál, kövessétek azt. És nem felelt néki a nép csak egy szót sem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'Akkor monda Illés a népnek: Én maradtam meg csak egyedül az Úr prófétái közül; míg a Baál prófétái négyszázötvenen vannak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'Adjatok azért nékünk két tulkot, és ők válaszszák magoknak az egyik tulkot, a melyet vagdaljanak darabokra, és rakják a fákra; de tüzet ne tegyenek alája; én pedig a másikat készítem el, a melyet a fákra rakok, de tüzet én sem teszek alája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'Akkor hívjátok segítségül a ti istenteknek nevét, és én is segítségül hívom az Úrnak nevét; és a mely isten tűz által felel, az az Isten. És felelvén az egész sokaság, monda: Jó lesz!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'És monda Illés a Baál prófétáinak: Válaszszátok el magatoknak az egyik tulkot, és készítsétek el ti először; mert ti többen vagytok, és hívjátok segítségül a ti istenteknek nevét, de tüzet ne tegyetek alája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'És vevék a tulkot, a melyet nékik adott, és azt elkészíték, és segítségül hívák a Baálnak nevét reggeltől fogva délig, mondván: Baál! hallgass meg minket! De nem jött szó, sem felelet. És ott sántikáltak az oltár körül, a melyet készítettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'Mikor pedig már dél lett, elkezdte őket gúnyolni Illés, azt mondván: Kiáltsatok hangosabban, hiszen isten! Talán elmélkedik, vagy félrement, vagy úton van, vagy talán aluszik, és felserken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'És elkezdtek hangosan kiabálni és az ő szokásuk szerint késekkel és borotvákkal metélték magokat, míg csak ki nem csordult a vérök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'Mikor pedig a dél elmúlt, prófétálni kezdtek egész az esteli áldozatig; de akkor sem lett se szó, se felelet, se meghallgattatás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'Akkor monda Illés az egész sokaságnak: Jőjjetek én hozzám. És hozzá méne az egész sokaság, és megépíté az Úr oltárát, a mely leromboltatott volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'És vőn Illés tizenkét követ, a Jákób fiai nemzetségeinek száma szerint, a kiknek az Isten azt mondotta volt: Izráel legyen a te neved;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'És oltárt építe a kövekből az Úr nevében, és egy árkot húzott az oltár körül, a melybe két véka vetni való mag férne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'És oda készíté a fát, és felvagdalá a tulkot, és felraká azt a fára;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'És monda: Töltsetek meg négy vedret vízzel, és öntsétek az égőáldozatra és a fára. Monda ismét: Tegyétek ezt még egyszer! És másodszor is azt tevék. Monda még is: Harmadszor is tegyétek meg! És harmadszor is azt mívelék;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'Úgy, hogy a víz lecsurgott az oltárról, és még az árok is tele lett vízzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'És a mikor eljött az esteli áldozás ideje, oda lépett Illés próféta, és monda: Óh Uram, Ábrahámnak, Izsáknak és Izráelnek Istene, hadd ismerjék meg e mai napon, hogy te vagy az Isten az Izráelben, és hogy én a te szolgád vagyok, és hogy mindezeket a te parancsolatodból cselekedtem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Hallgass meg engem, Uram, hallgass meg engem, hogy tudja meg e nép, hogy te, az Úr vagy az Isten, és te fordítod vissza az ő szívöket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'Akkor alászálla az Úr tüze, és megemészté az égőáldozatot, a fát, a köveket és a port, és felnyalta a vizet, a mely az árokban volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'Mikor ezt látta az egész sokaság, arczra borult, és monda: Az Úr az Isten! az Úr az Isten!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'És monda Illés nékik: Fogjátok meg a Baál prófétáit; senki el ne szaladjon közülök! És megfogák őket, és alávivé őket Illés a Kison patakja mellé, és megölé ott őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'Akkor monda Illés Akhábnak: Eredj fel, egyél és igyál, mert nagy esőnek zúgása hallszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'És felment Akháb, hogy egyék és igyék. Illés pedig felment a Kármel hegy tetejére, és leborula a földre, és az ő orczáját az ő két térde közé tevé;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'És monda az ő szolgájának: Menj fel, és nézz a tenger felé. És felment, és arrafelé nézett, és monda: Nincsen semmi. És monda Illés: Menj vissza hétszer.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'És lőn hetedúttal, monda a szolga: Ímé egy kis felhőcske, mint egy embernek a tenyere, jő fel a tengerből. Akkor monda: Menj fel, mondd meg Akhábnak: Fogj be és menj le, hogy meg ne késleljen az eső.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'És lőn azonközben, hogy besötétedett az ég a fellegektől és a széltől, és nagy eső lett. Akháb pedig szekérre ült és elment Jezréelbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'És lőn az Úr keze Illésen, és felövezvén az ő derekát, még Akháb előtt futott el Jezréel felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'És Akháb elbeszélé Jézabelnek mindazokat, a melyeket Illés cselekedett és a többek között, hogy hogyan ölte meg mind a prófétákat fegyverrel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'És követet külde Jézabel Illéshez, mondván: Ezt cselekedjék velem az istenek és úgy segéljenek, ha holnap ilyenkor úgy nem cselekszem a te életeddel, mint a hogy te cselekedtél azoknak életekkel mind egyig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'A mit mikor megértett, felkelvén elméne, vigyázván az ő életére. És méne Beersebába, a mely Júdában volt; és ott hagyá az ő szolgáját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'Ő pedig elméne a pusztába egynapi járó földre, és elmenvén leüle egy fenyőfa alá, és könyörgött, hogy hadd haljon meg, és monda: Elég! Most óh Uram, vedd el az én lelkemet; mert nem vagyok jobb az én atyáimnál!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'És lefeküvék és elaluvék a fenyőfa alatt. És ímé angyal illeté őt, és monda néki: Kelj fel, egyél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'És mikor körülnézett, ímé fejénél vala egy szén között sült pogácsa és egy pohár víz. És evék és ivék, és ismét lefeküvék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'És az Úr angyala eljött másodszor is és megilleté őt, és monda: Kelj fel, egyél; mert erőd felett való utad van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'És ő felkelt, és evett és ivott; és méne annak az ételnek erejével negyven nap és negyven éjjel egész az Isten hegyéig, Hórebig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'És beméne ott egy barlangba, és ott hála. És ímé lőn az Úrnak beszéde ő hozzá, és monda néki: Mit csinálsz itt Illés?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'Ő pedig monda: Nagy búsulásom van az Úrért, a Seregek Istenéért; mert elhagyták a te szövetségedet az Izráel fiai, a te oltáraidat lerontották, és a te prófétáidat fegyverrel megölték, és csak én egyedül maradtam, és engem is halálra keresnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'És monda: Jőjj ki és állj meg ezen a hegyen, az Úr előtt. És ímé ott az Úr volt elmenendő. És az Úr előtt megyen vala nagy erős szél, a mely a hegyeket megszaggatta és meghasogatta a kősziklákat az Úr előtt; de az Úr nem vala abban a szélben. És a szél után földindulás lett; de az Úr nem volt a földindulásban sem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'És a földindulás után tűz jöve, de nem volt az Úr a tűzben sem. És a tűz után egy halk és szelíd hang hallatszék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'És mikor Illés ezt hallotta, befedé az ő arczát palástjával, és kimenvén, megálla a barlang ajtajában, és ímé szózat lőn ő hozzá, a mely ezt mondá: Mit csinálsz itt Illés?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'És ő felele: Nagy búsulásom van az Úrért, a Seregeknek Istenéért, mert az Izráel fiai elhagyták a te szövetségedet, lerontották a te oltáraidat, és a te prófétáidat megölték fegyverrel, és én egyedül maradtam, és engem is halálra keresnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'És monda az Úr néki: Menj el, térj vissza a te utadon a pusztán át Damaskusba, és mikor oda jutándasz, kenjed királylyá Hazáelt Siriában;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'És Jéhut, a Nimsi fiát kenjed királylyá Izráelben, és Elizeust, az Abelméholabeli Sáfát fiát pedig kenjed prófétává a te helyedbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'És lészen, hogy a ki megmenekedik Hazáel fegyverétől, azt Jéhu öli meg, és a ki megmenekedik a Jéhu fegyverétől, azt Elizeus öli meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'De meghagyok Izráelben hétezer embert: minden térdet, mely meg nem hajolt a Baálnak, és minden ajkat, mely meg nem csókolta azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'És ő elmenvén onnét, megtalálá Elizeust, a Sáfát fiát, a mint szántott tizenkét járom ökörrel, és ő maga a tizenkettedikkel volt; és Illés hozzá méne, és az ő palástját reá veté.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'És ő elhagyván az ökröket, Illés után futott, és monda: Kérlek hadd csókoljam meg az én atyámat és az én anyámat, és azután követlek. És monda: Menj, térj vissza; mert mit cselekedtem tenéked?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'És elmenvén ő tőle, vőn azután egy pár ökröt, és levágá azt, és az ekéhez való szerszámokból tüzet rakván, megfőzé azok húsát, és a népnek adá, és evének; és felkelvén, elméne Illés után, és szolgála néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'És Benhadád, Siria királya összegyűjté egész seregét, és harminczkét király volt ő vele és nagyon sok ló és szekér, és felméne és megszállá Samariát, és ostromolni kezdte azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'És követeket küldött Akhábhoz, az Izráel királyához a városba;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, 'És azt izené néki: Azt mondja Benhadád: A te ezüstöd és aranyad az enyém, a te feleségeid is és a te szép fiaid is az enyémek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'És felele az Izráel királya, és monda: A mint megmondottad uram, király, tiéd vagyok mindenekkel, a melyeket bírok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'Megtérvén pedig a követek, mondának: Azt mondja Benhadád: Miután hozzád küldöttem, és azt izentem, hogy a te ezüstödet és aranyadat és a te feleségeidet és fiaidat add nékem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'Azért holnap ilyenkor elküldöm az én szolgáimat hozzád, és felkutatják a te házadat, és a te szolgáid házait; és kezekhez veszik, a mi csak kedves előtted, és elhozzák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'Akkor egybehívá az Izráel királya mind az ország véneit, és monda: Vegyétek eszetekbe, és lássátok meg, minemű gonosz szándékkal van ez; mert hozzám küldött az én feleségeimért és gyermekeimért, ezüstömért és aranyomért, és meg nem tagadtam tőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'És mondának néki a vének mindnyájan, és az egész nép: Ne engedj néki, és az ő akaratját be ne teljesítsd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'És ő monda a Benhadád követeinek: Mondjátok meg az én uramnak, a királynak: Mindazokat, a melyek felől először izentél a te szolgádnak, megcselekszem, de ezt a dolgot nem tehetem meg. Így elmenvén a követek, megmondák néki a választ.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'Akkor hozzá külde Benhadád, és monda: Úgy cselekedjenek velem az istenek és úgy segéljenek, hogy Samariának minden pora sem elég, hogy a velem való nép közül mindeniknek csak egy-egy marokkal is jusson!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'És felele az Izráel királya, mondván: Mondjátok meg néki: Ne kérkedjék úgy, a ki fegyverbe öltözik, mint a ki már leveti a fegyvert!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'Meghallván pedig ezt a választ, mikor ő ivott a királyokkal a sátorokban, monda az ő szolgáinak: Vegyétek körül a várost! És azok körülvevék azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'És ímé egy próféta méne Akhábhoz, az Izráel királyához, a ki ezt mondá: Azt mondja az Úr: Avagy nem láttad-é mindezt a nagy sokaságot: ímé e mai napon kezedbe adom azt, hogy megtudjad, hogy én vagyok az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'Monda pedig Akháb: Ki által? És felele: Azt mondja az Úr: A tartományok fejedelmeinek ifjai által. Akkor monda Akháb: Ki kezdje meg a harczot? És felele: Te!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'Megszámlálá azért a tartományok fejedelmeinek ifjait, a kik kétszázharminczketten voltak; ezekután megszámlálá mind az Izráel fiainak is minden népét, hétezer embert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'És elindulának délben. Benhadád pedig ott ivott a királyokkal a sátorokban, és lerészegedett ő és a harminczkét király, a ki segítségére jött vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'És a tartományok fejedelmeinek ifjai vonultak ki legelőször. Benhadád pedig elkülde, és megmondották néki, ezt mondván: Valami férfiak jöttek ki Samariából!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'És monda: Akár békességért jöttek ki, fogjátok meg őket elevenen; akár viadalért jöttek ki, fogjátok el őket elevenen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'De mikor kivonultak a városból a tartományok fejedelmeinek ifjai és a sereg, a mely őket követte:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'Mindenik vágni kezdte azt, a ki eléje került, és elfutottak a Siriabeliek, az Izráel pedig kergette őket, és megfutott maga Benhadád, Siria királya is lovon a lovagokkal együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'És azután kivonult az Izráel királya, és megveré mind a lovagokat, mind a szekereket, és megveré a Siriabelieket nagy csapással.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'És méne az Izráel királyához egy próféta, és ezt mondá néki: Menj el, erősítsd meg magad, és vedd eszedbe és lásd meg, mit kelljen cselekedned, mert esztendő mulva ismét feljő Siria királya ellened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'A siriabeli király szolgái pedig mondának néki: A hegyeknek istenei az ő isteneik, azért győztek le bennünket; de vívjunk csak meg velök a síkon, és meglátod, ha le nem győzzük-é őket?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'És tedd ezt: Küldd el a királyokat, mindeniket a maga helyéről; és állíts hadnagyokat helyettök,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'És szervezz magadnak olyan sereget, mint az volt, a melyet elvesztettél, és olyan lovakat és szekereket, mint amazok voltak; és vívjunk meg velök a síkon, és meglátod, ha le nem győzzük-é őket? És engede az ő szavoknak, és akképen cselekedék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'Mikor azért az esztendő elmult, rendbeszedte Benhadád a Siriabelieket, és feljöve Afekbe, hogy hadakozzék az Izráel ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'De az Izráel fiai összeszámláltattak és elláttattak élelemmel, és eleikbe menének azoknak. Táborba szállván pedig az Izráel fiai, amazokhoz képest olyanok voltak, mint két kicsiny kecskenyájacska; míg a Siriabeliek ellepték a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'Jött vala pedig egy Isten embere, és szóla az Izráel királyának, mondván: Azt mondja az Úr: Azért mert a Siriabeliek azt mondották, hogy csak a hegyeknek Istene az Úr, és nem a völgyeknek Istene is: mindezt a nagy sokaságot a te kezedbe adom, hogy megismerjétek, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'És ott táboroztak egészen velök szemben hetednapig. A hetedik napon azután megütköztek, és az Izráel fiai levágtak a Siriabeliek közül egy nap százezer gyalogost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, 'És a többiek elmenekültek Afek városába; de a falak rászakadtak a megmaradott huszonkétezer emberre, és Benhadád is elfutott és ott bolyongott a városban kamaráról-kamarára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, 'És mondának néki az ő szolgái: Ímé hallottuk, hogy az Izráel házának királyai kegyelmes királyok, azért hadd öltözzünk zsákokba, és vessünk köteleket a mi nyakunkba, és menjünk ki az Izráel királyához, talán életben hagyja a te lelkedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, 'És zsákokba öltözének, és köteleket vetének nyakokba, és elmenének az Izráel királyához, és mondának: A te szolgád, Benhadád, ezt mondja: Hagyd életben kérlek, az én lelkemet! És monda: Él-e még? én atyámfia ő!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, 'És a férfiak jó jelnek vették azt, és gyorsan megragadták a szót, és mondának: A te atyádfia Benhadád él. És monda: Menjetek, és hozzátok ide őt. Kijöve azért ő hozzá Benhadád, és felülteté őt az ő szekerébe,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'És monda néki: A városokat, a melyeket elvett volt az én atyám a te atyádtól, azokat visszaadom, és csinálj magadnak utczákat Damaskusban, mint az én atyám csinált volt Samariában; én ezzel a kötéssel bocsátlak el téged. És szövetséget kötött vele, és elbocsátá őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, 'Egy férfiú pedig a próféták fiai közül monda az ő felebarátjának az Úr beszéde szerint: Verj meg engem kérlek; de ez nem akará őt megverni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, 'Akkor monda néki: Azért, mert nem engedtél az Úr szavának: ímé mihelyt én tőlem elmégy, megöl téged az oroszlán. És a mikor elment ő tőle, találá őt egy oroszlán, és megölé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, 'Talála azután más férfiat, a kinek monda: Kérlek, verj meg engem. És megveré az annyira, hogy megsebesítette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, 'És elméne a próféta, és az útfélen a király elé álla és elváltoztatá magát szemeit bekötözvén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, 'Mikor pedig arra ment el a király, kiálta a királyhoz, és monda: A te szolgád kiment volt a hadba, és ímé egy férfiú eljövén, hoza én hozzám egy férfiút, és monda: Őrizd meg ezt a férfiút; ha elszaladánd, meg kell halnod érette, vagy egy tálentom ezüstöt fizetsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, 'És mialatt a te szolgádnak itt és amott dolga volt, az az ember már nem volt. És monda néki az Izráel királya: Az a te ítéleted; magad akartad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, 'És mindjárt elvevé a kötést az ő szeméről, és megismeré őt az Izráel királya, hogy a próféták közül való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, 'És monda néki: Ezt mondja az Úr: Mert elbocsátottad kezedből a férfiút, a kit én halálra szántam, azért lelked lészen lelkéért, és néped népéért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'És házához méne az Izráel királya szomorú és megbúsult szívvel, és méne Samariába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'És történt ezek után, hogy a Jezréelbeli Nábótnak egy szőlője volt Jezréelben, Akhábnak, Samaria királyának a háza mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'És szóla Akháb Nábótnak, mondván: Add nékem a te szőlődet, hogy legyen veteményes kertem; mert közel van az én házamhoz, és néked érette jobb szőlőt adok annál, vagy ha néked tetszik, pénzül adom meg az árát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'És felele Nábót Akhábnak: Isten őrizzen, hogy néked adjam az én atyáimtól maradt örökséget.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'Akkor haza méne Akháb nagy bánattal és haraggal a beszéd miatt, a melyet szólott néki a Jezréelbeli Nábót, mondván: Nem adom néked az én atyáimtól maradt örökséget; és lefeküvék az ő ágyára, és arczát a fal felé fordítá, és nem evék kenyeret.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'Hozzá menvén az ő felesége Jézabel, monda néki: Miért háborodott meg a te szíved, és kenyeret nem eszel?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'És ő monda néki: Mert ama Jezréelbeli Nábóttal beszéltem, és azt mondám néki: Add nékem a te szőlődet pénzért, vagy ha inkább tetszik, más szőlőt adok néked érette, ő pedig azt mondta: Nem adom néked az én szőlőmet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'Akkor monda néki Jézabel, az ő felesége: Te bírod-é most az Izráel királyságát? Kelj fel, egyél kenyeret, és a te szíved örvendezzen, én majd néked adom a Jezréelbeli Nábót szőlőjét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'És levelet írt Akháb nevével, a melyet megpecsételt az ő gyűrűjével, és elküldé azt a levelet a véneknek és a főembereknek, a kik Nábóttal egy városban laktak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'És a levélben ezt írta, mondván: Hirdessetek bőjtöt, és ültessétek Nábótot a nép élére;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'És ültessetek vele szembe két istentelen embert, a kik tanúbizonyságot tegyenek ő ellene, mondván: Megszidalmaztad az Istent és a királyt. Azután vigyétek ki, és kövezzétek meg őt, hogy meghaljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'És ekképen cselekedének a vének és a főemberek, a kik az ő városában laktak, a mint Jézabel nékik megparancsolta, és a mint a levélben megírta, a melyet nékik küldött;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'Bőjtöt hirdetének, és ülteték Nábótot a nép élére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'Előjöve azután két istentelen ember, és leült vele szemben, és tanúbizonyságot tettek ez istentelen emberek Nábót ellen a nép előtt, mondván: Megszidalmazta Nábót az Istent és a királyt. Kivivék azért őt a városból, és megkövezék, és meghala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'Azután megizenék Jézabelnek, mondván: Megköveztetett Nábót, és meghalt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'Mikor pedig meghallotta Jézabel, hogy megköveztetett Nábót és meghalt, monda Jézabel Akhábnak: Kelj fel és foglald el a Jezréelbeli Nábót szőlőjét, a melyet nem akart néked pénzért oda adni; mert nem él Nábót, hanem meghalt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'És mikor meghallotta Akháb, hogy Nábót meghalt, felkelt Akháb, hogy lemenjen a Jezréelbeli Nábót szőlőjébe, és azt elfoglalja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'Akkor szóla az Úr Thesbites Illésnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, 'Kelj fel, és menj Akhábnak, az Izráelbeli királynak eleibe, a ki Samariában lakik, ímé ott van a Nábót szőlőjében, a melybe lement, hogy azt elfoglalja;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, 'És szólj néki, ezt mondván: Így szól az Úr: Nemde megölted-é és nemde el is foglaltad-é? És szólj néki, mondván: Ezt mondja az Úr: Ugyanazon a helyen, a hol felnyalták az ebek Nábót vérét, ebek nyalják fel a te véredet is!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'És monda Akháb Illésnek: Megint rám találtál ellenségem? És ő monda: Rád találtam; mert te magadat mindenestől arra adtad, hogy gonoszságot cselekedjél az Úr szemei előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'Ímé, azt mondja az Úr: Veszedelmet hozok reád, és elvesztem a te maradékaidat, és kigyomlálom Akhábnak még az ebét is, és a berekesztettet és az elhagyatottat Izráelben;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'És olyanná teszem a te házadat, mint Jeroboámnak, a Nébát fiának házát, és mint Baásának, az Ahija fiának házát azért, a miért haragra ingerlettél engem, és a miért bűnbe ejtetted az Izráelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'És Jézabel felől is szóla az Úr, mondván: Az ebek eszik meg Jézabelt Jezréel kőfala előtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'Azt, a ki Akháb házából a városban hal meg, az ebek eszik meg; azt pedig, a ki a mezőben hal meg, az égi madarak eszik meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, 'Mert bizonyára nem volt Akhábnak mássa, a ki magát arra adta volna, hogy csak gonoszságot cselekedjék az Úr szemei előtt, a melyre az ő felesége, Jézabel ösztökélé őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'Mert igen útálatos dolgot cselekedék, követvén a bálványokat mind a szerint, a mint cselekedének az Emoreusok, a kiket az Úr kiűzött volt az Izráel fiai előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'Lőn pedig, mikor meghallotta Akháb e beszédeket, megszaggatá az ő ruháit, és zsákba öltözék és bőjtöle, és a zsákban hála, és nagy alázatossággal jár vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'És szóla az Úr Thesbites Illésnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, 'Nem láttad-é, hogy Akháb hogyan megalázta magát előttem? Mivelhogy pedig megalázta magát előttem, nem hozom reá a veszedelmet az ő életében, hanem csak az ő fia idejében hozom el a veszedelmet az ő házára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'És három esztendő lefolyt úgy, hogy nem volt hadakozás a Siriabeliek és az Izráel között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'De a harmadik esztendőben aláméne Josafát, Júda királya az Izráel királyához,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'Akkor monda az Izráel királya az ő szolgáinak: Nem tudjátok-é, hogy Rámoth Gileád a miénk? És mi hallgatunk és nem veszszük vissza azt Siria királyától?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'És monda Josafátnak: Feljössz-é velem e hadba Rámoth Gileád ellen? Felele Josafát az Izráel királyának: Úgy én, mint te, úgy az én népem, mint a te néped; úgy az én lovaim, mint a te lovaid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'És monda Josafát az Izráel királyának: Kérdezősködjél még ma az Úr beszéde után.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'És összegyűjté az Izráel királya a prófétákat, közel négyszáz férfiút, és monda nékik: Elmenjek-é Rámoth Gileád ellen hadba, vagy elhagyjam? És mondának: Menj fel; mert az Úr kezébe adja azt a királynak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'És monda Josafát: Nincs itt már több prófétája az Úrnak, hogy attól is tudakozódhatnánk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'És monda az Izráel királya Josafátnak: Még van egy férfiú, a ki által megkérdhetjük az Urat, Mikeás, a Jemla fia; de én gyűlölöm őt, mert soha nem jövendöl nékem jót, hanem mindig csak rosszat. És monda Josafát: Ne beszéljen így a király!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'És előszólíta az Izráel királya egy udvariszolgát, és monda: Hívd ide hamar Mikeást, a Jemla fiát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'És ott ült az Izráel királya és Josafát, Júda királya, ruhákba öltözötten, mindenik a maga trónusán Samaria kapuja előtt a térségen, és a próféták mind ott jövendöltek előttük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'És Sédékiás, a Kénaána fia, vasszarvakat készített, és monda: Ezt mondja az Úr: Ezekkel ökleled a Siriabelieket, míg meg nem emészted őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'És a próféták is mindnyájan ekképen jövendöltek, mondván: Menj fel Rámoth Gileád ellen, és jó szerencséd lesz; mert azt az Úr a király kezébe adja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'A követ pedig, a ki elment volt, hogy elhívja Mikeást, szóla néki, mondván: Ímé a próféták egyenlő akarattal jót jövendölnek a királynak: szólj, kérlek, te is úgy, mint azok közül egy, és jövendölj jót.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'Mikeás pedig monda: Él az Úr, hogy csak azt fogom mondani, a mit az Úr mondánd nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'És mikor a királyhoz ment, monda néki a király: Mikeás! elmenjünk-é Rámoth Gileád ellen hadba, vagy elhagyjuk? Ő pedig monda néki: Menj fel és járj szerencsével; az Úr kezébe adja azt a királynak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'És monda néki a király: Még hányszor kényszerítselek téged, hogy az igaznál egyebet ne mondj nékem az Úr nevében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'És monda: Látám az egész Izráelt szétszéledve a hegyeken, mint a juhokat, a melyeknek nincsen pásztoruk. És monda az Úr: Nincsen ezeknek urok? Térjen vissza kiki az ő házához békességben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'És monda az Izráel királya Josafátnak: Nemde nem megmondottam-é néked, hogy soha jót nékem nem jövendöl, hanem csak rosszat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'És monda Mikeás: Azért halld meg most az Úr beszédét: Látám az Urat az ő székiben ülni, és az egész mennyei sereget az ő jobb- és balkeze felől mellette állani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'És monda az Úr: Kicsoda csalja meg Akhábot, hogy felmenjen, és elvesszen Rámoth Gileádnál? És ki egyet, ki mást szól vala hozzá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'Akkor előjőve egy lélek, a ki az Úr eleibe álla, és monda: Én akarom megcsalni őt. Az Úr pedig monda néki: Miképen?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'És felele: Kimegyek és hazug lélek leszek minden ő prófétáinak szájában. Akkor monda az Úr: Csald meg és győzd meg; menj ki, és cselekedjél úgy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'Ímé az Úr a hazugságnak lelkét adta mindezeknek a te prófétáidnak szájába; és az Úr szólott veszedelmes dolgot ellened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'Akkor odalépett Sédékiás, a Kénaána fia, és arczul csapván Mikeást, monda: Hogyan? Eltávozott volna én tőlem az Úrnak lelke, hogy csak néked szólana?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'És monda Mikeás: Ímé meglátod azon a napon, a mikor az egyik kamarából a másik kamarába mégy be, hogy elrejtőzhess.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'Az Izráel királya pedig monda: Fogjad Mikeást, és vidd vissza őt Ammonhoz, a város fejedelméhez, és Joáshoz, a király fiához;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'És mondjad: Ezt mondja a király: Vessétek ezt a tömlöczbe, és tápláljátok őt a nyomorúság kenyerével és a nyomorúság vizével, míg békességgel megjövök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'Monda pedig Mikeás: Ha békességgel térsz vissza, nem az Úr szólott én általam. Azután monda: Halljátok ezt meg minden népek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'És felvonult az Izráel királya, és Josafát, a Júda királya Rámoth Gileád ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'És monda az Izráel királya Josafátnak: Megváltoztatom ruhámat, és úgy megyek a viadalra, te pedig öltözzél fel ruhádba. És elváltoztatá ruháját az Izráel királya, és úgy méne a viadalra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'Siria királya pedig megparancsolá az ő szekerei harminczkét fejedelmeinek, mondván: Ne vívjatok se kicsinynyel, se nagygyal, hanem egyedül csak az Izráel királya ellen vívjatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'És a mikor meglátták a szekerek fejedelmei Josafátot, mondának: Nyilván ez az Izráel királya; és reá rohanván vívának ellene. De Josafát elkezdett kiáltani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'Mikor pedig látták a szekerek fejedelmei, hogy nem az Izráel királya, ott hagyták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'Egy ember pedig csak úgy találomra kilövé az ő kézívét, és találá az Izráel királyát a pánczél és a kapocs között. És ő monda a kocsisának: Fordulj meg és vigy ki engem a táborból, mert megsebesültem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'És az ütközet mind erősebb lett azon a napon, és a király az ő szekerében állott a Siriabeliek ellen, és meghalt este felé, és a vér a sebből a szekérbe csorgott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'És kikiálták napnyugotkor a táborban, mondván: Minden ember menjen haza a maga városába és földjébe!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'És meghalt a király és visszavitetvén Samariába, eltemeték a királyt Samariában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'És mikor mosták az ő szekerét a Samaria mellett lévő tóban: az ebek nyalták az ő vérét, és paráznák fürödtek ott, az Úrnak beszéde szerint, a melyet szólott volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'Akhábnak egyéb dolgai pedig és minden cselekedetei, az elefántcsontból építtetett ház, és mind a városok, a melyeket épített, vajjon nincsenek-é megírva az Izráel királyainak krónika-könyvében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'És elaluvék Akháb az ő atyáival; és uralkodék ő utána fia, Akházia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'És Josafát, az Asa fia lett királylyá Júdában, Akhábnak, az Izráel királyának negyedik esztendejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'És Josafát harminczöt esztendős volt, mikor uralkodni kezdett, és huszonöt esztendeig uralkodott Jeruzsálemben. Az ő anyjának Azuba volt a neve, Silhi leánya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'És jára Asának, az ő atyjának minden útjában, és abból ki nem tére, azt cselekedvén, a mi az Úr szemei előtt kedves.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'Csakhogy a magaslatokat nem rombolták le, és a nép még áldozott és tömjénezett a magaslatokon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'És békességben élt Josafát az Izráel királyával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, 'Josafátnak egyéb dolgai pedig és az ő ereje, a melylyel cselekedett, és a melylyel hadakozott, vajjon nincsenek-é megírva a Júda királyainak krónika-könyvében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, 'A férfi paráznákat is, a kik még megmaradtak volt az ő atyjának, Asának idejéből, kiűzte az országból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'Akkor nem volt király Edomban, hanem csak helyettes király.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, 'És Josafát Társis hajókat csináltatott, hogy aranyért mennének Ofirba, de nem mehettek el; mert a hajók összetörtek Esiongáberben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'Akkor mondá Akházia, az Akháb fia, Josafátnak: Hadd menjenek el az én szolgáim a te szolgáiddal e hajókon; de Josafát nem akará.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, 'És elaluvék Josafát az ő atyáival; és eltemetteték az ő atyáival az ő atyjának, Dávidnak városában; és az ő fia, Jórám, uralkodék helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, 'Akházia pedig, az Akháb fia kezde uralkodni Izráelen Samariában, Josafátnak, a Júda királyának tizenhetedik esztendejében, és uralkodék Izráelben két esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, 'És gonoszul cselekedék az Úrnak szemei előtt, járván az ő atyjának és anyjának útján, és Jeroboámnak, a Nébát fiának útján, a ki bűnbe ejté az Izráelt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 54, 'És szolgála a Baálnak, és azt imádá és haragra indítá az Urat, Izráel Istenét, mint a hogy az ő atyja cselekedett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'És elszakadt Moáb, Akháb halála után, az Izráeltől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'És mikor Akházia kibukott az ő felházának korlátján Samariában, és megbetegedék, követeket külde el, a kiknek azt parancsolá: Menjetek el, kérdjetek tanácsot a Baálzebubtól, az Ekron istenétől, hogy meggyógyulok-é e betegségből?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'Az Úrnak angyala pedig szóla Thesbites Illésnek: Kelj fel, menj el eleibe a Samariabeli király követeinek, és szólj nékik: Nincs-é Isten Izráelben, hogy Baálzebubhoz, az Ekron istenéhez mentek tanácsot kérdeni?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'Azért azt mondja az Úr: Az ágyból, a melyben fekszel, fel nem kelsz, hanem kétség nélkül meghalsz. És elméne Illés.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'És mikor a követek visszajöttek ő hozzá, monda nékik: Miért jöttetek vissza?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'És felelének néki: Egy férfiú jöve előnkbe, és monda nékünk: Menjetek el, térjetek vissza a királyhoz, a ki titeket elküldött, és mondjátok meg néki: Ezt mondja az Úr: Nincs-é Izráelben Isten, hogy te Baálzebubhoz, Ekron istenéhez küldesz tanácsot kérdeni? Azért az ágyból, a melyben fekszel, fel nem kelsz, hanem kétség nélkül meghalsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'És monda nékik: Milyen volt az a férfiú, a ki előtökbe jött volt, és ezeket a beszédeket szólá néktek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'És felelének néki: Egy szőr-ruhás ember, derekán bőr övvel felövezve. Akkor monda: Thesbites Illés volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'És hozzá külde egy ötven ember előtt járó főembert, az alatta való ötven emberrel. És mikor ez hozzá felment, ott ült fenn a hegy tetején, és monda néki: Isten embere, a király azt parancsolja: Jőjj le!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'Felelvén Illés, monda az ötven ember előtt járó főembernek: Ha én Isten embere vagyok, szálljon tűz alá az égből, és emészszen meg téged és az alattad való ötven embert. És tűz szálla alá az égből, és megemészté őt és az ő ötven emberét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'És ismét külde ő hozzá a király más ötven ember előtt való főembert, mind az ötven férfival egybe, a ki szóla és monda néki: Isten embere, a király azt parancsolja, hogy hamar jőjj alá!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'És felele Illés, és monda nékik: Ha Isten embere vagyok, szálljon tűz az égből alá, és emészszen meg téged és a te ötven emberedet. És Istennek tüze szálla alá az égből, és megemészté őt és az ő ötven emberét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'És újra elküldött egy harmadik ötven ember előtt járó főembert is, az ő ötven emberével együtt, és felmenvén ez az ötven ember előtt járó főember, elméne és térdre borult Illés előtt, és könyörögvén néki, monda: Óh Isten embere, kérlek, legyen becsülete a te szemeid előtt az én lelkemnek, és ezeknek a te szolgáidnak, ez ötven ember lelkének!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Ímé tűz szállott le az égből és megemészté az ötven ember előtt való elébbi két főembert, az ő ötven emberével egybe: Most azért legyen becsülete az én lelkemnek a te szemeid előtt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'Ekkor szóla az Úr angyala Illésnek: Menj alá vele, ne félj semmit tőle. És ő felkelvén aláméne vele a királyhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'És szóla néki: Ezt mondja az Úr: A miért követeket küldöttél tanácsot kérdeni Baálzebubhoz, Ekron istenéhez, mintha nem volna Izráelben Isten, a kinek a beszédéből tanácsot kérdhetnél: azért fel nem kelsz ez ágyból, a melyben fekszel, hanem kétség nélkül meghalsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'És meghalt az Úrnak beszéde szerint, a melyet szólott Illés, és uralkodék Jórám ő helyette, Jórámnak, a Josafát fiának, a Júdabeli királynak második esztendejében; mert Akháziának nem volt fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'Akháziának egyéb dolgai pedig, a melyeket cselekedett, vajjon nincsenek-é megírva az Izráel királyainak krónika-könyvében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'És lőn mikor az Úr Illést fel akará vinni a szélvész által mennyekbe: elméne Illés és Elizeus Gilgálból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'És monda Illés Elizeusnak: Maradj itt, kérlek, mert az Úr Béthelbe küldött engem. És felele Elizeus: Él az Úr, és a te lelked, hogy el nem hagylak téged! És mikor lemenének Béthel felé:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'Kijövének a próféták fiai, a kik Béthelben valának, Elizeushoz, és mondának néki: Nem tudod-é, hogy e mai napon az Úr elragadja a te uradat tőled? És monda: Tudom én is, hallgassatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'És monda néki Illés: Elizeus! Maradj itt, kérlek; mert az Úr engem Jérikhóba küldött. Ő azonban monda: Él az Úr és a te lelked, hogy el nem hagylak téged. És mikor elmenének Jérikhóba:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'A próféták fiai, a kik Jérikhóban valának, Elizeushoz jövének, és mondának néki: Nem tudod-é, hogy e mai napon az Úr a te uradat elragadja tőled? És ő monda: Én is tudom, hallgassatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'Azután monda néki Illés: Maradj itt, kérlek, mert az Úr engem a Jordán mellé küldött. De ő felele: Él az Úr és a te lelked, hogy el nem hagylak téged. És elmenének együtt mindketten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'Ötven férfiú pedig a próféták fiai közül utánok menvén, velök szemben messze megállának, mikor ők ketten a Jordán mellett megállottak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'És fogá Illés az ő palástját, és összehajtva azt, megüté azzal a vizet; és az kétfelé válék; úgy hogy mind a ketten szárazon menének át rajta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'És mikor általmentek, monda Illés Elizeusnak: Kérj tőlem, mit cselekedjem veled, mielőtt tőled elragadtatom. És monda Elizeus: Legyen, kérlek, a te benned való léleknek kettős mértéke én rajtam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'És ő monda: Nehéz dolgot kértél; mégis, ha majd meglátándasz engem, mikor tőled elragadtatom, meglesz, a mit kérsz: ha pedig meg nem látándasz, nem lesz meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'És lőn, a mikor menének és menvén beszélgetének, ímé egy tüzes szekér tüzes lovakkal elválasztá őket egymástól. És felméne Illés a szélvészben az égbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'Elizeus pedig ezt látván, kiált vala: Édes atyám, édes atyám! Izráel szekerei és lovagjai! És nem látá őt többé. És vevé a maga ruháit, és két részre szakasztá azokat,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'És felemelé az Illés palástját, a mely róla leesett, és visszatért, és megállott a Jordán partján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'És vevé az Illés palástját, a mely róla leesett, és azzal megüté a vizet, és monda: Hol van az Úr, az Illés Istene? És mikor ő is megütötte a vizet, kétfelé válék az; és általméne Elizeus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'És mikor látták őt a próféták fiai, a kik átellenben Jérikhónál valának, mondának: Az Illés lelke megnyugodt Elizeuson. És eleibe menének néki, és meghajták magokat ő előtte a földig;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'És mondának néki: Ímé a te szolgáid között van ötven ember, erős férfiak, küldd el őket, hadd keressék meg a te uradat, hátha az Úrnak lelke ragadta el őt, és letette őt valamelyik hegyen, vagy völgyben. De ő monda: Ne küldjetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'De azok kényszerítették őt egész a megszégyenülésig, és monda: Hát küldjetek el! És elküldék az ötven férfiút, de harmadnapig keresvén sem találák meg őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'És mikor visszajöttek ő hozzá, mert Jérikhóban lakott, monda nékik: Nem mondottam-é, hogy ne menjetek el?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'És mondának a város férfiai Elizeusnak: Ímé e város jó lakóhely volna, a mint uram magad látod; de a vize ártalmas, és a föld gyümölcsét meg nem érleli.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'És monda: Hozzatok nékem egy új csészét, és tegyetek sót belé. És elhozák néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'Ő pedig kiment a forráshoz, és bele veté a sót, és monda: Ezt mondja az Úr: Meggyógyítottam e vizeket; nem származik ezután azokból halál és idétlen termés.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'És egészségesekké lőnek a vizek mind e mai napig, Elizeus beszéde szerint, a melyet szólott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'Felméne azután onnét Béthelbe; és mikor az úton felfelé méne, apró gyermekek jövének ki a városból, a kik őt csúfolják vala, ezt mondván: Jőjj fel, kopasz, jőjj fel, kopasz!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'És hátratekintvén és meglátván őket, megátkozá őket az Úr nevében, és az erdőből két nőstény medve jövén ki, szétszaggata közülök negyvenkét gyermeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'Onnét azután felment a Kármel hegyére; onnét pedig Samariába tért vissza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'Jórám pedig, az Akháb fia kezde uralkodni Izráelen Samariában Josafátnak, a Júda királyának tizennyolczadik esztendejében, és uralkodék tizenkét esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'És gonoszul cselekedék az Úrnak szemei előtt, de nem annyira, mint az ő atyja és anyja; mert elrontá a Baál képét, a melyet az ő atyja készíttetett volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'De mindazáltal követé Jeroboámnak, a Nébát fiának bűneit, a ki vétekbe ejtette volt az Izráelt, és el nem távozék azoktól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'És Mésának, a Moáb királyának nagyon sok juha volt, és az Izráel királyának adóban százezer bárány és százezer kos gyapját fizette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'De mikor meghalt Akháb, a Moáb királya elszakadt az Izráel királyától.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'Kiméne azért Jórám király azon a napon Samariából, és megszámlálá az egész Izráelt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'És elméne, és külde követeket Josafáthoz, Júda királyához, ezt izenvén néki: A Moáb királya elszakadt tőlem; eljösz-é velem a Moáb ellen a hadba? Felele: Felmegyek, úgy én, mint te; úgy az én népem, mint a te néped; úgy az én lovam, mint a te lovaid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'És monda: Mely úton menjünk fel? Felele: Az Edom pusztájának útján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'És elméne az Izráel királya és Júda királya és az Edom királya; és mikor hét napig bolyongtak az úton, nem volt vize sem a tábornak, sem a velök volt barmoknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'Akkor monda az Izráel királya: Jaj, jaj; az Úr azért hívta egybe e három királyt, hogy a Moáb kezébe adja őket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'És monda Josafát: Nincs itt az Úr prófétái közül egy sem, hogy általa tanácsot kérhetnénk az Úrtól? És felele egy az Izráel királyának szolgái közül, és monda: Itt van Elizeus, a Sáfát fia, a ki Illésnek kezeire vizet tölt vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'És monda Josafát: Nála van az Úrnak beszéde. És alámenének hozzá az Izráel királya és Josafát és az Edom királya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'És monda Elizeus az Izráel királyának: Mi közöm van hozzád? Menj a te atyádnak és anyádnak prófétáihoz! És monda néki az Izráel királya: Ne utasíts el; mert az Úr gyűjtötte össze ezt a három királyt, hogy a Moáb kezébe adja őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'És monda Elizeus: Él a Seregek Ura, a ki előtt állok, ha nem nézném Josafátnak, a Júda királyának személyét, bizony téged nem néznélek, és rád sem tekintenék;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'Hozzatok ide egy énekest. És mikor énekelt előtte az éneklő, az Úrnak keze lőn ő rajta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'És monda: Ezt mondja az Úr: Csináljatok itt és ott e patakon árkokat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'Mert ezt mondja az Úr: Nem láttok sem szelet, sem esőt, és mégis e patak megtelik vízzel, hogy ihattok mind ti, mind a ti nyájatok és barmaitok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'Kevés pedig még ez az Úr szemei előtt, hanem a Moábot is kezetekbe adja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'És megvesztek minden kulcsos várost és minden szép várost, és minden jótermő fát kivagdaltok, és minden kútfőt betöltötök, és minden jó szántóföldet behánytok kövekkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'És lőn reggel, a mikor áldozatot szoktak tenni, ímé vizek jőnek vala Edom útjáról, és megtelék a föld vízzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'Mikor pedig meghallotta az egész Moáb, hogy feljöttek a királyok ő ellenök harczolni, egybegyűlének mindnyájan, a kik fegyvert foghattak, és megállottak az ő tartományuk határán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'És mikor felkeltek reggel, és a nap feljött a vizekre, úgy láták a Moábiták, mintha ő ellenökbe az a víz vereslenék, mint a vér.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'És mondának: Vér ez! Megvívtak a királyok egymással, és megölte egyik a másikát. Prédára most, Moáb!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'De mikor az Izráel táborához jutottak, felkeltek az Izráeliták, és megverték a Moábitákat, és azok megfutamodtak előttök; betörtek hozzájok és leverték Moábot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'És városaikat lerontották, és a jó szántóföldekre kiki követ hányt, és elborították azt kövekkel, és minden kútfőt behánytak, és minden jótermő fát kivágtak, úgy hogy csak Kir-Haréset kőfalait hagyták fenn; de körülvevék azt is a parittyások, és lerontották.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'Látván pedig a Moáb királya, hogy legyőzettetik a viadalban, maga mellé vett hétszáz fegyverfogó férfiút, hogy keresztül törjenek az Edom királyához; de nem bírtak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'Akkor vevé az ő elsőszülött fiát, a ki ő helyette uralkodandó volt, és égőáldozatul megáldozá a kőfalon. Mely dolog felett az Izráel népe igen felháborodék, és elmenének onnét, és megtérének az ő földjökbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'És kiálta egy asszony a próféták fiainak feleségei közül Elizeushoz, és monda: A te szolgád, az én férjem meghalt; te tudod, hogy a te szolgád félte az Urat. Eljött pedig a hitelező, hogy elvigye mind a két gyermekemet, hogy néki szolgái legyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'Monda néki Elizeus: Mit cselekedjem veled? Mondd meg nékem, mi van a házadban? Monda az: A te szolgálóleányod házában nincs egyéb, csak egy korsó olaj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'Akkor monda: Menj el, kérj ott kinn minden te szomszédidtól üres edényeket, de ne keveset;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'És menj be és zárkózzál be magad a te fiaiddal, és tölts az olajból mindenik edénybe, és a tele edényt állítsd félre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'És elment ő tőle, és bezárkózott az ő fiaival, azok hordták néki az edényeket, ő maga pedig csak töltögetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'És mikor megtöltötte az edényeket, monda az ő fiának: Hozz ide még egy edényt. Felele az: Nincs több edény; és akkor megállott az olaj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'És elment, és elmondá ezt az Isten emberének. Az pedig monda: Menj el, add el az olajat, és fizesd ki hiteleződet; te pedig és a te fiaid éljetek a maradékából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'És történt ebben az időben, hogy Elizeus Súnembe ment. Ott volt egy gazdag asszony, a ki tartóztatá őt, hogy nála egyék kenyeret. És lőn, hogy valamikor csak arra járt, betért oda, hogy kenyeret egyék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'És monda az asszony a férjének: Ímé úgy veszem észre, hogy az az Isten embere, a ki szüntelen erre jár által, szent ember;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'Csináljunk, kérlek, egy kicsiny felházat, és tegyünk abba néki egy ágyat, asztalt, széket és gyertyatartót, hogy mikor hozzánk jön, hadd térjen oda.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'És történt egy napon, hogy oda ment Elizeus, és megszállott a felházban, és megpihent ott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'És monda Géházinak, az ő szolgájának: Hívd ide azt a Súnemitát. Előhívá azért azt, és eleibe álla.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'Megmondotta volt pedig néki: Mondd meg néki: Ímé nagy szorgalmatossággal szolgálsz nékünk, mit kivánsz, hogy cselekedjem veled? Nincs-é valami mondani valód a király előtt, vagy a sereg fővezére előtt? És monda az: Én az én nemzetségem között békességgel lakom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'Monda Elizeus: Mit lehetne tehát érette tennünk? Felele Géházi: Nincs fia és a férje vén ember.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'És monda: Hívd ide! És a mikor oda hívta, megállott az ajtóban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'És monda Elizeus: Esztendő ilyenkorra fiút fogsz ölelni. És monda az: Ne, édes uram, Isten embere, ne mondj képtelen dolgot a te szolgálóleányodnak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'És teherbe esék az asszony és fiat szült abban az időben, a melyet megmondott volt Elizeus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'De mikor megnőtt a gyermek, történt, hogy egy napon kiment az ő atyjához, az aratókhoz,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'És monda az ő atyjának: Jaj fejem, jaj fejem! És monda az ő atyja a szolgának: Vidd el őt az anyjához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'Ki mikor felvette őt, vivé az ő anyjához, és az az ölében tartá délig, és akkor meghalt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'És felméne az asszony, és az Isten emberének ágyára tevé őt, és az ajtót bezárván kijöve onnét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'És előhívatá az ő férjét és monda: Kérlek, küldj ide nékem egyet a szolgák közül és egy szamarat, hadd menjek el hamar az Isten emberéhez, és mindjárt megjövök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'És az monda: Miért mégy ő hozzá, ma nincs sem újhold, sem szombat? Felele az: Csak hagyd rám!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'És megnyergelé a szamarat, és monda a szolgának: Hajtsd és siess, ne késlelj engem a menésben, hanem ha mondándom néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'És elmenvén, juta az Isten emberéhez a Kármel hegyére. És mikor meglátá őt az Isten embere távolról, monda Géházinak, az ő szolgájának: Ímé a Súnemita ez!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'Fuss, kérlek, eleibe, és kérdezd meg tőle, ha békességben van-é mind ő, mind az ő férje, mind az ő gyermeke? Monda az: Békességben!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'Mikor pedig az Isten emberéhez jutott a hegyre, átölelte az ő lábait; de Géházi oda ment, hogy elűzze őt, az Isten embere azonban így szólt: Hagyj békét néki, mert megkeseredett az ő szíve, és az Úr eltitkolta tőlem, és nem jelentette meg nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'És monda az: Vajjon én kértem-é fiat az én uramtól? Nemde nem mondám-é néked: Ne csalj meg engemet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'És monda Elizeus Géházinak: Övezd fel derekadat, és vedd kezedbe az én pálczámat, és menj el, ha valakivel találkozol, ne köszönj néki, és annak is, a ki köszön néked, ne felelj, és az én pálczámat tedd a gyermek arczára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'De a gyermeknek anyja monda: Él az Úr és él a te lelked, hogy el nem hagylak téged. Felkele azért és követé őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'Géházi pedig már előttök elment volt, és a pálczát a gyermek arczára fekteté, de nem szólott és nem is eszmélt rá a gyermek. Azért visszatért eleibe, és megmondá néki, mondván: Nem támadt fel a gyermek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'És bement Elizeus a házba, és ímé a gyermek ott feküdt halva az ő ágyán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'És bement, és bezárta az ajtót magára és a gyermekre, és könyörgött az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'És az ágyra felhágván, a gyermekre feküdt, és az ő száját a gyermek szájára tevé, szemeit szemeire, kezeit kezeire, és ráborult, és megmelegedék a gyermek teste.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'Azután felállott, és egyszer alá és fel járt a házban, majd újra felment és reáborult. Akkor a gyermek prüsszente vagy hétszer, és felnyitá szemeit a gyermek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'Ő pedig szólítá Géházit, és monda: Hívd ide a Súnemitát. És oda hívá azt. És mikor oda ment, monda: Vedd a te fiadat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'Ki mikor bement, lábához esék, és leborula a földre, és az ő fiát fogván, kiméne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'Azután visszament Elizeus Gilgálba. Éhség vala pedig akkor az országban, és a próféták fiai ő vele laknak vala. És monda az ő szolgájának: Tedd fel a nagy fazekat, és főzz valami főzeléket a próféták fiainak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'Kiméne azért egy a mezőre, hogy paréjt szedjen. És holmi vad indákra találván, tele szedé az ő ruháját azokról sártökkel, és mikor hazament, belevagdalta a fazékba főzeléknek; de nem tudta, hogy mi az?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'Mikor azután feladták a férfiaknak, hogy egyenek, és ők enni kezdének a főzelékből, felkiáltának és mondának: Halál van a fazékban, Isten embere! És nem bírták megenni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'Ő pedig monda: Hozzatok lisztet. És beleveté azt a fazékba, és monda: Add fel immár a népnek, hadd egyenek. És nem volt már semmi rossz a fazékban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'Jöve pedig egy férfi Baál Sálisából, és hoz vala az Isten emberének első zsengék kenyereit, húsz árpakenyeret, és megzsendült gabonafejeket az ő ruhájában; de ő monda: Add a népnek, hadd egyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'Felele az ő szolgája: Minek adjam ezt száz embernek? Ő pedig monda ismét: Add a népnek, hadd egyenek, mert ezt mondja az Úr: Esznek és még marad is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'És ő eleikbe adá, és evének, és még maradt is belőle, az Úrnak beszéde szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'És Naámán, a siriai király seregének fővezére, az ő ura előtt igen nagy férfiú és nagyrabecsült volt, mert általa szabadította volt meg az Úr Siriát; és az a férfi vitéz hős, de bélpoklos volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'Egyszer portyázó csapatok mentek ki Siriából, és azok Izráel országából egy kis leányt vittek el foglyul, és ez Naámán feleségének szolgált.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'És monda ez az ő asszonyának: Vajha az én uram szembe lenne azzal a prófétával, a ki Samariában van, kétség nélkül meggyógyítaná őt az ő bélpoklosságából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'És Naámán beméne, és elbeszélé az ő urának, mondván: Így s így szólott az Izráel országából való leány!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'Akkor monda Siria királya: Menj el, és ím levelet küldök az Izráel királyának. Elméne azért és vőn magával tíz tálentom ezüstöt és hatezer aranyat, azon felül tíz öltöző ruhát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'És elvivé a levelet az Izráel királyának, ezt írván: Mikor e levél hozzád érkezik, ímé az én szolgámat, Naámánt azért küldöttem hozzád, hogy őt gyógyítsd meg bélpoklosságából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'De a mikor elolvasta az Izráel királya a levelet, megszaggatá az ő ruháit és monda: Isten vagyok-e én, hogy öljek és elevenítsek, hogy ez én hozzám küld, hogy gyógyítsam meg e férfiút az ő bélpoklosságából? Vegyétek eszetekbe és lássátok, hogy csak okot keres ellenem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'Mikor pedig meghallotta Elizeus, az Isten embere, hogy az Izráel királya ruháit megszaggatta, külde a királyhoz ilyen izenettel: Miért szaggattad meg a te ruháidat? Hadd jőjjön hozzám, és tudja meg, hogy van próféta Izráelben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'És elméne Naámán lovaival és szekereivel, és megálla az Elizeus házának ajtaja előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'És külde Elizeus követet ő hozzá, mondván: Menj el és fürödj meg hétszer a Jordánban, és megújul a te tested, és megtisztulsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'Akkor megharaguvék Naámán és elment, és így szólt: Íme én azt gondoltam, hogy kijő hozzám, és előállván, segítségül hívja az Úrnak, az ő Istenének nevét, és kezével megilleti a beteg helyeket, és úgy gyógyítja meg a kiütést.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'Avagy nem jobbak-é Abana és Párpár, Damaskus folyóvizei Izráel minden vizeinél? Avagy nem fürödhetném-é meg azokban, hogy megtisztuljak? Ilyen módon megfordulván, nagy haraggal elment.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'De hozzá menének az ő szolgái, és szólának néki, mondván: Atyám, ha valami nagy dolgot mondott volna e próféta neked, avagy nem tetted volna-é meg? Mennyivel inkább, a mikor csak azt mondja, hogy fürödj meg és megtisztulsz?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'Beméne azért a Jordánba, és belemeríté magát abba hétszer az Isten emberének beszéde szerint, és megújult az ő teste, mint egy kis gyermek teste, és megtisztult.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'Azután visszatért egész kiséretével az Isten emberéhez, és bemenvén megálla előtte, és monda: Ímé, most tudom már, hogy nincsen az egész földön Isten, csak Izráelben! Azért most vedd el, kérlek, ez ajándékot a te szolgádtól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'Ő pedig monda: Él az Úr, a ki előtt állok, hogy el nem veszem. Kényszeríti vala pedig őt, hogy elvegye; de ő nem akará.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'És monda Naámán: Ha nem; adj kérlek a te szolgádnak e földből annyit, a mennyit elbír két öszvér; mert a te szolgád többé égőáldozattal, vagy egyéb áldozattal nem áldozik idegen isteneknek, hanem csak az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'Ebben a dologban legyen az Úr kegyelmes a te szolgádnak, hogy mikor bemegy az én uram a Rimmon templomába, hogy ott imádkozzék, és ő az én kezemre támaszkodik, ha akkor én is meghajlok a Rimmon templomában: azt, hogy én meghajlok a Rimmon templomában, bocsássa meg az Úr a te szolgádnak ebben a dologban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'És monda néki Elizeus: Eredj el békességgel. És mikor elment ő tőle úgy egy mértföldnyire,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'Géházi, Elizeusnak, az Isten emberének szolgája azt gondolta: Ímé az én uram megkimélé ezt a Siriabeli Naámánt, és nem akará tőle elvenni, a mit hozott volt; él az Úr, hogy utána futok, és valamit kérek tőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'És utána futott Géházi Naámánnak. Látván pedig Naámán őt, hogy utána fut, leugrott a szekérből és eleibe méne és monda: Rendben van minden?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'És monda: Rendben. Az én uram küldött engem, ezt mondván: Ímé most csak ez órában jött hozzám két ifjú az Efraim hegyéről a próféták fiai közül: adj kérlek azoknak egy tálentom ezüstöt és két öltöző ruhát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'És monda Naámán: Kérlek végy két tálentomot. És kényszeríté őt és egybeköte két tálentom ezüstöt két zsákba, és két öltöző ruhát, és azokat két szolgájának adá, a kik előtte vitték azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'De mikor a dombhoz ért, elvette tőlök azokat, és elrejté egy házban, és elbocsátá a férfiakat, és elmenének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'Ő pedig bemenvén, megálla az ő ura előtt, és monda néki Elizeus: Honnét, Géházi? Felele: Nem ment a te szolgád sehová.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'Ő pedig monda néki: Nem ment-é el az én szívem veled, mikor az a férfiú leszállott szekeréből elődbe? Most az ideje, hogy szerezz ezüstöt, és hogy végy ruhákat, olajfákat, szőlőket, juhokat, barmokat, szolgákat és szolgálóleányokat?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'Azért rád és a te magodra ragad a Naámán bélpoklossága mindörökké. És kiment ő előle megpoklosodva, mint a hó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'És mondának a próféták fiai Elizeusnak: Ímé ez a hely, a hol nálad lakunk, igen szoros nékünk;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'Hadd menjünk el, kérlek, a Jordán mellé, hogy mindenikünk egy-egy fát hozzon onnét, hogy ott valami hajlékot építsünk magunknak, a melyben lakjunk. És monda: Menjetek el!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'És monda egy közülök: Nyugodj meg rajta, és jőjj el a te szolgáiddal. És monda: Én is elmegyek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'És elméne velök. És menének a Jordán mellé, és ott fákat vágtak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'És történt, hogy mikor egy közülök egy fát levágna, a fejsze beesék a vízbe. Akkor kiálta és monda: Jaj, jaj, édes uram! pedig ezt is kölcsön kértem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'És monda az Isten embere: Hová esett? És mikor megmutatta néki a helyet, levágott egy fát és utána dobta, és a fejsze feljött a víz színére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'És monda: Vedd ki. És kinyújtván kezét, kivevé azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'Siria királya pedig hadat indított Izráel ellen, és tanácsot tartván az ő szolgáival, monda: Itt meg itt lesz az én táborom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'És elkülde az Isten embere az Izráel királyához, mondván: Vigyázz, ne hagyd el azt a helyet, mert ott akarnak a siriaiak betörni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'És elkülde az Izráel királya arra a helyre, a melyről néki az Isten embere szólott, és őt megintette volt, és vigyázott magára nem egyszer, sem kétszer.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'És felháborodott ezen a siriai király szíve, és összegyűjtvén az ő szolgáit, monda nékik: Miért nem mondjátok meg nékem, ki tart közülünk az Izráel királyával?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'Akkor monda egy az ő szolgái közül: Nem úgy, uram király, hanem Elizeus próféta, a ki Izráelben van, jelenti meg az Izráel királyának a beszédeket, a melyeket te a te titkos házadban beszélsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'És monda: Menjetek el és nézzétek meg, hol van, hogy utána küldjek és elhozassam őt. És megjelenték néki, mondván: Ímé Dótánban van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'Akkor lovakat, szekereket és nagy sereget külde oda, a kik elmenének éjjel, és körülvevék a várost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'Felkelvén pedig jókor reggel az Isten emberének szolgája, kiméne, és ímé seregek vették körül a várost, és lovak és szekerek. És monda néki az ő szolgája: Jaj, jaj, édes uram! mit cselekedjünk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'Felele ő: Ne félj. Mert többen vannak, a kik velünk vannak, mint a kik ő velök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'És imádkozott Elizeus és monda: Óh Uram! nyisd meg kérlek az ő szemeit, hadd lásson. És megnyitá az Úr a szolga szemeit és láta, és ímé a hegy rakva volt tüzes lovagokkal és szekerekkel Elizeus körül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'És mikor azok hozzá lementek, könyörgött Elizeus az Úrnak, mondván: Verd meg ezt a népet vaksággal! És megveré őket vaksággal az Elizeus kivánsága szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'És monda nékik Elizeus: Nem ez az út, sem ez a város; jertek el én utánam, és ahhoz a férfiúhoz vezetlek titeket, a kit kerestek. És elvezeté őket Samariába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'És mikor bementek Samariába, monda Elizeus: Óh Uram, nyisd meg ezek szemeit, hogy lássanak. És megnyitá az Úr az ő szemeiket és látának, és ímé Samaria közepében voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'Az Izráel királya pedig mikor látta őket, monda Elizeusnak: Vágván vágassam-é őket, atyám?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'És monda: Ne vágasd. Le szoktad-é vágatni azokat, a kiket karddal vagy kézívvel fogsz el? Adj nékik kenyeret és vizet, hogy egyenek és igyanak, és elmenjenek az ő urokhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'És nagy lakomát szerzett nékik; és miután ettek és ittak, elbocsátá őket. Ők pedig elmenének az ő urokhoz; és ettől fogva többé nem jöttek a siriai portyázó csapatok az Izráel földjére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'És lőn ezek után, hogy Benhadád, Siria királya összegyűjté egész seregét, és felment és megszállotta Samariát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'És igen nagy inség lett Samariában, mert addig tartották megszállva a várost, míg egy szamárfej nyolczvan ezüst, és egy véka galambganéj öt ezüst lett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'És mikor az Izráel királya a kőfalon széjjeljára, egy asszony kiálta ő hozzá, mondván: Légy segítséggel, uram király!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'A király monda: Ha nem segít meg téged az Isten, hogyan segítselek én meg? A szérűről vagy a sajtóról?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'És monda néki a király: Mit akarsz? Monda az: Ez az asszony azt mondta nékem: Add ide a te fiadat, hogy együk meg őt ma, az én fiamat pedig holnap eszszük meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'És megfőztük az én fiamat, és megettük őt. Mikor azután másnap azt mondtam néki: Add ide a te fiadat, hogy azt is együk meg, ő elrejté az ő fiát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'Mikor pedig hallotta a király az asszonynak beszédét, megszaggatá az ő ruháit, a mint a kőfalon járt, és meglátta a nép, hogy ímé alól zsákruha van az ő testén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'És monda: Úgy cselekedjék velem az Isten és úgy segéljen, ha Elizeusnak, a Sáfát fiának feje ma rajta marad!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, 'Elizeus pedig ott ült az ő házában, és együtt ültek vele a vének. És elküldött a király egy férfiat maga előtt. Mielőtt azonban hozzá jutott volna a követ, monda Elizeus a véneknek: Látjátok-é, hogy az a gyilkos hogyan küld ide, hogy a fejemet vétesse? Vigyázzatok, hogy mikor ide ér a követ, zárjátok be az ajtót és szorítsátok meg őt az ajtóban: Ímé az ő ura lábainak dobogása követi őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'És mikor még így beszélne velök, már a követ leérkezett hozzá és nyomában a király, és monda: Ímé ilyen veszedelem származott az Úrtól; várjak-é még tovább az Úrra?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'És monda Elizeus: Halljátok meg az Úr beszédét. Ezt mondja az Úr: Holnap ilyenkor egy köböl zsemlyelisztet egy sikluson, és két köböl árpát egy sikluson vesznek Samaria kapujában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'És felelvén egy főember, a kinek kezére támaszkodott a király, az Isten emberének, monda: Hacsak az Úr ablakokat nem csinál az égen; akkor meglehet? És monda Elizeus: Ímé, te szemeiddel meg fogod látni, de nem eszel belőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'A kapu előtt pedig volt négy bélpoklos férfi, a kik mondák egymásnak: Miért maradunk itt, hogy meghaljunk éhen?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'Ha azt határozzuk is, hogy bemegyünk a városba, ott is inség van, és akkor ott halunk meg; ha pedig itt maradunk, akkor itt halunk meg; jertek el azért, szökjünk el a Siriabeliek táborába, ha meghagyják életünket, élünk, ha megölnek, meghalunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'És felkeltek alkonyatkor, hogy a Siriabeliek táborába menjenek; és mikor odaértek a Siriabeliek táborának széléhez, ímé már nem volt ott senki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'Mert az Úr azt cselekedte volt, hogy a Siriabeliek tábora szekerek zörgését és lovak dobogását, és nagy sereg robogását hallotta, és mondának egymásnak: Ímé az Izráel királya bérbe fogadta meg ellenünk a Hitteusok királyit és az Égyiptombeliek királyit, hogy ellenünk jőjjenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'És felkelvén elfutának alkonyatkor, és elhagyák mind sátoraikat, mind lovaikat, mind szamaraikat, a mint a tábor volt, és elfutának, csakhogy életöket megmenthessék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'Mikor azért e bélpoklosok a tábor széléhez értek, bemenvén egy sátorba, evének és ivának, és elvivének onnét ezüstöt, aranyat és ruhákat, és elmenvén elrejték azokat; és megtérvén más sátorba menének be, és abból is hozának és elmenvén, elrejték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'És monda egyik a másiknak: Nem igazán cselekszünk: ez a mai nap örömmondás napja, ha mi hallgatunk, és a virradatot megvárjuk, büntetés ér bennünket; most azért jertek és menjünk el, és mondjuk meg a király házának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'És elmenének, és kiáltának a város kapuján állónak, és elbeszélék nékik, mondván: Odamentünk volt a Siriabeliek táborába, és ímé már nem volt ott senki; emberek szava nem hallatszott, csak a lovak és szamarak vannak kikötve, és a sátorok úgy, a mint voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'Kiáltának azért a kapunállók, és hírré tevék ott benn a király házában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'És felkele éjszaka a király, és monda az ő szolgáinak: Megmondom néktek, mit csinálnak velünk a Siriabeliek. Tudják, hogy éhen vagyunk, és csak azért mentek ki a táborból, hogy elrejtőzzenek a mezőn, mondván: Mikor kijönnek a városból, megfogjuk őket elevenen, és bemegyünk a városba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'Akkor felele egy az ő szolgái közül, és monda: Ki kell választani a megmaradt lovak közül, a melyek a városban megmaradtak, ötöt, – ímé épen olyanok ezek, mint Izráelnek egész sokasága, a mely megmaradt; ímé épen olyanok ezek, mint Izráel egész sokasága, a mely elpusztult, – és küldjük ki, hadd lássuk meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'És vevének két szekeret lovakkal, és kiküldé a király a siriaiak táborába, mondván: Menjetek el és nézzétek meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'És mikor utánuk mentek egész a Jordánig, ímé az egész út rakva volt ruhákkal és edényekkel, a melyeket a siriaiak a sietségben elhánytak. És mikor visszajöttek a követek, és elmondák ezt a királynak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'Kiment a nép, és kirabolta a Siriabeliek táborát, és egy köböl zsemlyelisztet egy sikluson, és két köböl árpát egy sikluson vettek, az Úrnak beszéde szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'A király pedig azt a főembert, a kinek kezére szokott támaszkodni, oda rendelte a kapuhoz. És a nép eltapodá őt a kapuban, és meghala, a mint az Isten embere megmondotta, a ki megjövendölte ezt, mikor a király lement hozzá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'Úgy történt, a mint az Isten embere a királynak jövendölte: Két köböl árpát egy sikluson és egy köböl zsemlyelisztet egy sikluson adnak holnap ilyenkor Samaria kapujában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'És ezt felelte volt a főember az Isten emberének, mondván: Hacsak az Úr ablakokat nem csinál az égen; akkor meglehet? és ő azt mondotta rá: Ímé te szemeiddel meg fogod látni; de nem eszel belőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'És teljesen így történt vele, mert eltapodá őt a nép a kapuban és meghalt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'És Elizeus szólott volt annak az asszonynak, a kinek a fiát feltámasztotta volt, mondván: Kelj fel, és menj el a te házadnépével együtt, és tartózkodjál, a hol tartózkodhatol; mert az Úr éhséget hívott elő, és el is jött a földre hét esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'És felkelt az asszony, és az Isten emberének beszéde szerint cselekedék, és elment ő és az ő háznépe, és lakék a Filiszteusok földében hét esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'Mikor pedig elmult a hét esztendő, visszatért az asszony a Filiszteusok földéből, és elment, hogy panaszolkodjék a királynak az ő házáért és szántóföldeiért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'A király pedig beszélt Géházival, az Isten emberének szolgájával, mondván: Beszéld el, kérlek, nékem mindazokat a csudálatos dolgokat, a melyeket Elizeus cselekedett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'És mikor elbeszélé a királynak, mimódon támasztotta fel a halottat, ímé az asszony, a kinek a gyermekét feltámasztotta volt, éppen akkor kiáltott a királyhoz az ő házáért és szántóföldeiért; és monda Géházi: Uram király, ez az az asszony és ez az ő fia, a kit feltámasztott Elizeus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'És kikérdezé a király az asszonyt, és az elbeszélé néki; és ada a király ő mellé egy udvari szolgát, mondván: Adasd vissza néki minden jószágát, és a szántóföldnek minden hasznát attól az időtől fogva, a mióta elhagyta a földet egész mostanig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'És Elizeus elment Damaskusba, Benhadád pedig, Siria királya beteg volt, és hírül adák néki, mondván: Az Isten embere ide jött.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'És monda a király Hazáelnek: Végy ajándékot kezedbe, és menj eleibe az Isten emberének, és kérj tanácsot az Úrtól ő általa, mondván: Meggyógyulok-é ebből a betegségből?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'És eleibe ment Hazáel, és ajándékokat vitt kezében mindenféle drága damaskusi jószágból negyven teve terhét; és elment, és megállott előtte, és így szólt: A te fiad, Benhadád, Siria királya, az küldött engem hozzád, mondván: Vajjon meggyógyulok-é ebből a betegségből?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'Felele néki Elizeus: Menj el, mondd meg néki: Nem maradsz életben, mert megjelentette nékem az Úr, hogy halált hal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'És mereven ránézett Hazáelre, mígnem zavarba jött; végre sírni kezdett az Isten embere.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'És monda Hazáel: Miért sír az én uram? És felele: Mert tudom a veszedelmet, a melyet az Izráel fiaira hozol; az ő erős városait megégeted, az ő ifjait fegyverrel levágatod, és kis gyermekeit a földhöz vered, és terhes asszonyait ketté vágod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'És monda Hazáel: Kicsoda a te szolgád, ez az eb, hogy ilyen nagy dolgokat cselekednék? És felele Elizeus: Megjelentette nékem az Úr, hogy te leszel Siria királya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'És elméne Elizeustól, és beméne az ő urához, és az monda néki: Mit mondott Elizeus? és monda: Azt mondta, hogy meggyógyulsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'Másnap azonban elővett egy takarót és bemártván azt vízbe, ráteríté az ő arczára, és meghalt: és uralkodék Hazáel ő helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'És Jórámnak, az Akháb fiának, az Izráel királyának ötödik esztendejében, mikor még Josafát vala Júda királya, uralkodni kezdett Jórám, a Josafát fia, Júda királya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'Harminczkét esztendős volt, mikor uralkodni kezdett, és nyolcz esztendeig uralkodott Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'És járt az Izráel királyainak útján, a miképen cselekedtek volt az Akháb házából valók; mert az Akháb leánya volt a felesége, és gonoszul cselekedék az Úr szemei előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'De az Úr még sem akarta elveszteni Júdát Dávidért, az ő szolgájáért; a mint megigérte volt néki, hogy szövétneket ad néki és az ő fiainak mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'Az ő idejében szakadt el Edom a Júda birodalmától, és választott királyt magának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'És átment Jórám Seirbe és minden harczi szekere ő vele, s mikor éjjel felkelt és megtámadta az Edomitákat, a kik körülzárták őt, és a szekerek fejedelmeit, megfutott a nép, kiki az ő hajlékába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'És elszakadt Edom a Júda birodalmától mind e mai napig; ugyanebben az időben szakadt el Libna is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'Jórámnak egyéb dolgai pedig és minden cselekedetei, vajjon nincsenek-é megírva a Júda királyainak krónika-könyvében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'És elaluvék Jórám az ő atyáival, és eltemetteték az ő atyáival a Dávid városában, és uralkodék Akházia, az ő fia, ő helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'Jórámnak az Akháb, az Izráel királya fiának tizenkettedik esztendejében kezdett uralkodni Akházia, Jórámnak, a Júdabeli királynak fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'Huszonkét esztendős volt Akházia, mikor uralkodni kezdett, és egy esztendeig uralkodott Jeruzsálemben; az ő anyjának neve Athália volt, Omrinak, az Izráel királyának leánya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'És járt az Akháb házának útján, és gonoszul cselekedék az Úr szemei előtt, mint az Akháb háza; mert az Akháb házának veje vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'És hadba ment Jórámmal, az Akháb fiával, Siria királya, Hazáel ellen, Rámóth Gileádba; de a Siriabeliek megverték Jórámot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'Akkor visszatért Jórám király, hogy meggyógyíttassa magát Jezréelben a sebekből, a melyeket rajta a Siriabeliek Ráma alatt ütöttek, mikor Hazáel, Siria királya ellen harczolt. Akházia pedig, a Jórám fia, Júda királya aláméne, hogy meglátogassa Jórámot, az Akháb fiát Jezréelben, a hol az betegen feküdt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'Elizeus próféta pedig szólíta egyet a próféták fiai közül, és monda néki: Övezd fel derekadat, és vedd kezedbe e korsócska olajat, és menj el Rámóth Gileádba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'És menj be oda, és nézd meg, hol van Jéhu, Josafátnak, a Nimsi fiának fia. Mikor pedig oda érsz, költsd fel őt az ő atyjafiai közül, és vidd be a belső kamarába,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'És vedd elő e korsócska olajat, és töltsd az ő fejére, ezt mondván: Azt mondja az Úr: Téged kentelek királylyá Izráelen! És az ajtót kinyitván, fuss el, és semmit ott ne időzz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'És elment az ifjú, a próféta tanítványa, Rámóth Gileádba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'És mikor bement, ímé a seregek fejedelmei ott ültek együtt, és ő monda: Beszédem volna veled, fejedelem! És monda Jéhu: Kivel volna beszéded ennyiőnk közül? És monda: Te veled, fejedelem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'Felkele azért, és bement a házba, és fejére tölté az olajat, és monda néki: Azt mondja az Úr, Izráel Istene: Királylyá kentelek téged az Úrnak népén, az Izráelen,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'Hogy elveszítsed Akhábnak, a te uradnak háznépét; mert bosszút állok az én szolgáimnak, a prófétáknak véréért, és mind az Úr szolgáinak véréért Jézabelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'És kivész egészen az Akháb háza, és kigyomlálom mind az Akhábhoz tartozókat, még az ebet is, mind a berekesztettet, mind az elhagyottat Izráelben;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'És olyanná teszem az Akháb házát, mint Jeroboámnak, a Nébát fiának házát, és mint Baasának, az Ahija fiának házát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'Jézabelt pedig az ebek eszik meg Jezréel mezején, és nem lesz, a ki eltemesse őt. És kinyitván az ajtót, elfutott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'És mikor Jéhu kiment az ő urának szolgáihoz, mondának néki: Békességes-é a dolog? Miért jött e bolond hozzád? És felele nékik: Hiszen ismeritek ez embert és az ő beszédét!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'És mondának: Hazugság! Mondd meg az igazat. És monda: Így s így szóla nékem, mondván: Azt mondja az Úr: Királylyá kentelek téged Izráelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'Akkor nagy sietséggel kiki mind vevé az ő ruháját, és alája terítették a grádics felső részére és megfuvaták a harsonákat, és kikiálták: Jéhu uralkodik!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'Így ütött pártot Jéhu, Josafátnak, a Nimsi fiának fia, Jórám ellen. Jórám pedig ott táborozott volt Rámóth Gileád alatt az egész Izráellel, Hazáel, Siria királya ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'De visszatért volt Jórám király, hogy magát Jezréelben gyógyíttassa a sebekből, a melyeket a Siriabeliek ütöttek rajta, mikor Hazáel, Siria királya ellen harczolt. És monda Jéhu: Ha néktek is úgy tetszik, ne engedjetek senkit kimenni a városból, a ki elmenjen és hírül vigye ezt Jezréelbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'És befogatott Jéhu, és elment Jezréelbe, a hol Jórám feküdt, és a hova Akházia is, a Júda királya lement volt, hogy meglátogassa Jórámot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'Mikor pedig az őrálló, a ki Jezréelben a tornyon állott, meglátta Jéhu seregét, hogy jő, monda: Valami sereget látok. Akkor monda Jórám: Válaszsz egy lovast és küldj eléjök, és mondja ezt: Békességes-é a dolog?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'És oda lovagolt a lovas eléjük, és monda: Azt kérdi a király: Békességes-é a dolog? Felele Jéhu: Mi gondod van a békességgel? Kerülj a hátam mögé. Megjelenté pedig ezt az őrálló, mondván: Hozzájok ment ugyan a követ; de nem tért vissza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'Akkor elküldött egy másik lovast, a ki hozzájok ment, és monda: Azt kérdi a király: Békességes-é a dolog? Felele Jéhu: Mi gondod van a békességgel? Kerülj a hátam mögé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'Hírül adá ezt is az őrálló, mondván: Hozzájok ment ugyan; de nem jött vissza. De a hajtás olyan, mint Jéhunak, a Nimsi fiának hajtása; mert mint egy őrült, úgy hajt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'Akkor monda Jórám: Fogjatok be! És befogván az ő szekerét, kiméne Jórám, az Izráel királya, és Akházia, a Júda királya, mindenik a maga szekerén, Jéhu eleibe, és a Jezréelbeli Nábót mezején találkoztak vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'És mikor meglátta Jórám Jéhut, monda: Békességes-é a dolog, Jéhu? Felele ő: Mit békesség?! Mikor Jézabelnek, a te anyádnak paráznasága és varázslása mindig nagyobb lesz!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'Akkor megfordítá Jórám az ő kezét és futni kezde, és monda Akháziának: Árulás ez, Akházia?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'Jéhu pedig meghúzván az ívét, Jórámot hátba lövé a lapoczkák között úgy, hogy a szívén ment át a nyíl, és lerogyott a szekérben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'És monda Bidkárnak, az ő hadnagyának: Fogd meg és vesd a Jezréelbeli Nábót mezejére; mert emlékezz csak vissza, mikor mi, én és te, ketten az ő atyja, Akháb után lovagoltunk, és az Úr ő felőle ezt a fenyegetést mondotta:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, 'Bizonyára megkeresem a Nábót vérét és az ő fiainak vérét, a melyet tegnap láttam, azt mondja az Úr: Azért megfizetek néked ezen a szántóföldön, azt mondja az Úr: Most azért fogjad őt, és vesd a szántóföldre, az Úr beszéde szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'Akházia pedig, a Júda királya, mikor látta ezt, futni kezde a kert házának útján; de Jéhu utána menvén, monda: Ezt is vágjátok le a szekérben és megsebesíték őt a Gúr hágójánál, a mely Jibleám mellett van; és ő Megiddóba menekülvén, ott meghalt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'És az ő szolgái elvitték őt szekéren Jeruzsálembe, és eltemették az ő sirboltjába az ő atyáival a Dávid városában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'Akházia pedig uralkodni kezdett Júdában Jórámnak, az Akháb fiának tizenegyedik esztendejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'És mikor Jéhu Jezréelbe ment és Jézabel ezt meghallotta, arczát megékesíté kenettel, felékesítette fejét, és kitámaszkodott az ablakon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'És mikor Jéhu bevonult a kapun, monda: Békesség van-é, óh Zimri! uradnak gyilkosa?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'Ő pedig feltekintve az ablakra, monda: Ki van ott velem? Ki? És alátekintett két vagy három főember.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'És monda azoknak: Vessétek alá őt. És aláveték, és az ő vére szétfrecskendezett a falra és a lovakra, és eltapodtatá őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'Bemenvén pedig oda, evett és ivott, és monda: Nézzetek utána annak az átkozottnak és temessétek el; hiszen mégis csak király leánya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'De mikor kimentek, hogy eltemetnék őt, már semmit sem találtak belőle, csak a koponyáját, a lábait és a keze fejeit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'És visszamenvén, megmondák néki, és ő monda: Ez az Úr beszéde, a melyet szólott az ő szolgája, Thesbites Illés által, mondván: Az ebek eszik meg Jézabel testét a Jezréel földén,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'És olyan lesz Jezréel földjén a Jézabel teste, mint a mezőn a ganéj, úgy, hogy senki meg nem mondhatja: Ez Jézabel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'Akhábnak pedig hetven fia volt Samariában. És levelet írt Jéhu, és elküldé azt Samariába Jezréel fejedelmeihez, a vénekhez, és az Akháb fiainak tútoraihoz, ilyen parancsolattal:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, 'Mihelyt e levél hozzátok jut, a kiknél vannak a ti uratok fiai a szekerekkel, lovakkal, az erős városokkal és fegyverekkel együtt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'Nézzétek meg, melyik a legjobb és a legigazabb a ti uratok fiai közül, azt ültessétek az ő atyjának királyi székébe, és harczoljatok a ti uratok házáért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'És megrettenének felette igen, és mondának: Ímé már két király nem maradhatott meg ő előtte, mimódon maradhatnánk hát mi meg?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'És elküldének mind a király házának, mind a városnak fejedelmei, és a vének és a tútorok Jéhuhoz, mondván: A te szolgáid vagyunk mi, valamit parancsolsz nékünk, azt cselekeszszük; mi senkit királylyá nem teszünk, a mi néked tetszik, azt cselekedjed!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'És írt nékik levelet másodszor is, mondván: Ha velem tartotok és az én beszédemre hallgattok, vegyétek fejöket a férfiaknak, a ti uratok fiainak, és jőjjetek hozzám holnap ilyenkor Jezréelbe. És a király fiai: hetven férfiú, és a város nagyjaival tartottak, a kik nevelték őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'És mikor a levél hozzájok jutott, vevék a király fiait, és megölték a hetven férfiút, és fejeiket kosarakba rakták, és ő hozzá küldték Jezréelbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'És mikor odaérkezett a követ, és bejelenté néki, mondván: Elhozták a király fiainak fejeit, monda: Rakjátok két rakásba azokat a kapu előtt reggelig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'És mikor reggel kiment, megállott, és monda az egész népnek: Ti igazak vagytok. Ímé az én uram ellen én ütöttem pártot és én öltem meg őt; de ki ölte meg mind ezeket?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'Azért vegyétek eszetekbe ebből, hogy az Úrnak beszédéből egyetlen egy sem esik a földre, a mit az Úr az Akháb háza ellen szólott, és az Úr véghezvitte, a mit az ő szolgája, Illés által mondott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'Azután levágá Jéhu mindazokat, a kik megmaradtak volt az Akháb házából Jezréelben, és minden főemberét, egész rokonságát és minden papját, míg csak ki nem irtotta a maradékát is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'És felkelvén, elindult és elment Samariába. De útközben volt a pásztorok juhnyíró háza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'És itt Akháziának, a Júda királyának atyjafiaira talált Jéhu, és monda: Kik vagytok? És felelének azok: Akházia atyjafiai vagyunk, és alájöttünk, hogy köszöntsük a király gyermekeit és a királyné fiait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'Ő pedig monda: Fogjátok meg őket elevenen. És megfogták őket elevenen, és megölték őket a juhnyíróház kútja mellett, negyvenkét férfiút; és egyetlen egyet sem hagyott meg közülük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'És mikor elment onnét, Jonadábbal, a Rekháb fiával találkozott, a ki elébe jött, és köszönté őt, és monda néki: Vajjon olyan igaz-é a te szíved, mint az én szívem a te szívedhez? És felele Jonadáb: Olyan. Ha így van, nyújts kezet. És ő kezet nyújta, és felülteté őt maga mellé a szekérbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'És monda: Jer velem és lásd meg, mint állok bosszút az Úrért. És vele együtt vitték őt az ő szekerén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'És megérkezett Samariába, és levágta mindazokat, a kik az Akháb nemzetségéből megmaradtak volt Samariában, míg ki nem veszté azt az Úr beszéde szerint, a melyet szólott Illésnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'És Jéhu összegyűjté az egész népet, és monda néki: Akháb kevéssé szolgálta Baált; Jéhu sokkal jobban akarja szolgálni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'Most azért hívjátok hozzám a Baál minden prófétáit, minden papját és minden szolgáját; senki el ne maradjon; mert nagy áldozatot akarok tenni a Baálnak; valaki elmarad, meg kell halni annak. Jéhu pedig ezt álnokságból cselekedte, hogy elveszítse a Baál tisztelőit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'És monda Jéhu: Szenteljetek ünnepet Baálnak. És kikiálták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'És szétküldött Jéhu egész Izráelbe, és eljövének mind a Baál tisztelői, és senki el nem maradt a ki el nem jött volna, és bemenének a Baál templomába, és megtelék a Baál temploma minden zugában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'Akkor monda a ruhatárnoknak: Hozz ruhákat ki a Baál minden tisztelőinek. És hozott nékik ruhákat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'És bement Jéhu és Jonadáb, a Rekháb fia a Baál templomába, és monda a Baál tisztelőinek: Tudakozzátok meg és lássátok meg, hogy valamiképen ne legyen itt veletek az Úr szolgái közül valaki, hanem csak a Baál tisztelői.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'És mikor bementek, hogy ajándékokkal és égőáldozatokkal áldozzanak, Jéhu oda állított kivül nyolczvan embert, a kiknek azt mondta: A ki egyet elszalaszt azok közül, a kiket én kezetekbe adok, annak meg kell érette halni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'Mikor pedig elvégezték az égőáldozatot, monda Jéhu a vitézeknek és hadnagyoknak: Menjetek be, vágjátok le őket, csak egy is közülök meg ne meneküljön! És levágták őket fegyver élével, és elhányták az ő holttestöket a vitézek és a hadnagyok. Azután elmentek a Baál templomának városába,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'És kihordván a Baál templomának bálványait, megégeték azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'És lerontották a Baál képét is templomostól együtt, és azt árnyékszékké tették mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'Így veszté ki Jéhu a Baált Izráelből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'De Jeroboámnak, a Nébát fiának bűneitől, a ki vétekbe ejté az Izráelt, nem szakadt el Jéhu, az arany borjúktól, melyek Béthelben és Dánban valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'És monda az Úr Jéhunak: A miért szorgalmatosan megcselekedted azt, a mi nékem tetszett, és az én szívem kívánsága szerint cselekedtél az Akháb házával: azért a te fiaid negyedízig ülnek az Izráel királyi székiben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'De Jéhu még sem igyekezett azon, hogy az Úrnak, Izráel Istenének törvényében járjon teljes szívéből, mert nem szakadt el a Jeroboám bűneitől, a ki bűnbe ejtette az Izráelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'Abban az időben kezdett az Úr pusztítani Izráelben, és megveré őket Hazáel, Izráel minden határában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'A Jordántól egész napkeletig, a Gileádbelieknek, a Gád nemzetségének, a Rúben nemzetségének, Manasse nemzetségének egész földjét. Aroertől fogva; mely az Arnon patak mellett van, mind Gileádot, mind Básánt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'Jéhunak egyéb dolgai pedig és minden cselekedetei, és minden erőssége, vajjon nincsenek-é megírva az Izráel királyainak krónika-könyvében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'És elaluvék Jéhu az ő atyáival, és eltemeték őt Samariában. És uralkodék Joákház, az ő fia, helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'A napok pedig, a melyekben uralkodott Jéhu Izráelen Samariában, huszonnyolcz esztendő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'És Athália, Akházia anyja, mikor látta, hogy fia meghalt, felkelt és az egész királyi magot megölette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'De Jóseba, Jórám király leánya, Akházia huga, fogá Joást, Akházia fiát, és ellopván őt a király fiai közül, a kik megölettettek vala, elrejté az ő dajkájával együtt az ágyasházban; és elrejték őt Athália elől úgy, hogy ez nem öletteték meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'És elrejtve vala Joás ő vele együtt az Úr házában hat esztendeig, és Athália uralkodott az országban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'A hetedik esztendőben azonban elküldött Jójada, és magához hivatta a Káriánusok és a testőrök csapatainak vezéreit, és bevitte őket magával az Úr házába, és szövetséget kötött velök, és megesküdteté őket az Úr házában, és megmutatta nékik a király fiát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'És megparancsolta nékik, mondván: Ezt kell cselekednetek: közületek a harmadrész, a kik szombaton jőnek őrségre, tartsa a király házának őrizetét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'A harmadrésze legyen a Súr kapuban, és a harmadrésze a testőrök háta mögött való kapuban, és nagy szorgalmatossággal őrizzétek e házat, hogy senki reánk ne üthessen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'Az a két rész pedig közületek, az egész, a mely szombaton az őrszolgálatból kilép, vigyázzon az Úr házának megőrzésére a királyhoz vezető részen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'És vegyétek körül a királyt, mindenki kezében fegyverével, és a ki a sorokba benyomul, ölettessék meg, és a király körül legyetek kijövetelekor és bemenetelekor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'És a csapatok vezérei úgy cselekedtek, a mint meghagyta volt nékik Jójada pap; és mindenik maga mellé vette az ő embereit, azokat, a kik bementek szombaton az őrségre, azokkal együtt, a kiket felváltottak szombaton, és Jójada paphoz mentek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'És a pap a csapatok vezéreinek azokat a kopjákat és paizsokat adta oda, a melyek Dávid királyéi voltak és az Úr házában voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'És a testőrök ott állottak a király körül, mindenik fegyverrel kezében, a ház jobb szárnyától a bal szárnyáig, az oltár és a szenthely felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'És kivezeté Jójada a király fiát, és fejébe tevé a koronát, és kezébe adá a bizonyságtételt, és királylyá tevék őt és felkenék; és kezeikkel tapsolván, kiáltának: Éljen a király!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'Mikor pedig Athália meghallotta a testőröknek és a községnek kiáltását, bement a néphez az Úr házába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'És mikor szétnézett, ímé a király ott állott az emelvényen, a mint szokás, és a király előtt állottak a fejedelmek és a trombitások, és az egész föld népe ujjongott, és trombitáltak. Akkor megszaggatá Athália az ő ruháit, és kiáltván, monda: Összeesküvés! Összeesküvés!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'De parancsola Jójada pap a csapatok vezéreinek, a sereg hadnagyainak, és monda nékik: Vezessétek ki őt a sorok között, és ha valaki őt követné, öljétek meg fegyverrel. Mert azt mondta a pap: Ne ölettessék meg az Úr házában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'És útat nyitottak néki, és ő arra az útra ment, a merre a lovakat vezetik be a király házába, és ott megölték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'És kötést tőn Jójada az Úr, a király és a nép között, hogy ők az Úrnak népe lesznek; és külön a király és a nép között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'És elment az egész föld népe a Baál templomába, és azt lerombolta, és oltárait és bálványait teljesen összetörte, és Matthánt, a Baál papját az oltárok előtt ölték meg. És a pap gondviselőket rendele az Úr házában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'És maga mellé vévén a csapatok vezéreit, a Káriánusokat és a testőröket és az egész föld népét, elvivék a királyt az Úrnak házából, és menének a testőrök kapujának útján a király házához. És Joás üle a királyok székébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'És örvendezett mind az egész föld népe, és megnyugovék a város, miután megölték Atháliát fegyverrel a király háza mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 21, 'Joás hét esztendős volt, mikor uralkodni kezdett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'Jéhunak hetedik esztendejében tették Joást királylyá, és negyven esztendeig uralkodott Jeruzsálemben; az ő anyjának pedig Sibja vala neve, a ki Beersebából való volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'És cselekedék Joás kedves dolgot az Úr szemei előtt mindaddig, a míg Jójada pap oktatá őt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'Azonban a magaslatok oltárai nem rontattak le, a nép még mindig ott áldozott és tömjénezett a magaslatok oltárain.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'És megparancsolá Joás a papoknak, hogy minden pénzt, a mely Istennek szenteltetik és az Úr házába bevitetik, mind a megszámlálás pénzét és a személyek váltságának pénzét, mind pedig, a melyet kiki szabad akaratja szerint az Úr házához bevisz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'Vegyék magokhoz a papok, mindenik a maga ismerősétől, és építsék meg az Úr házának romlásait mindenütt, a hol romlást látnak rajta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'De mikor Joás király huszonharmadik esztendejéig sem építették meg a papok az Úr házának romlásait,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'Előhivatta Joás király Jójada papot a többi papokkal együtt, és monda nékik: Miért nem építitek meg az Úr házának romlásait? Ezután ne vegyétek a pénzt magatokhoz a ti ismerőseitektől, hanem az Úr háza romlásainak építésére adjátok azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'És a papok beleegyeztek, hogy többé semmi pénzt nem vesznek el a néptől, és nem javítják ki a ház romlásait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'És Jójada pap vett egy ládát, és annak a fedelén csinált egy nyílást, és helyhezteté azt az oltár mellé jobbfelől, a mely felől az Úr házába bemennek, hogy abba töltsenek a papok, a templom küszöbinek őrizői minden pénzt, a melyet az Úr házába hoznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'És mikor látták, hogy sok pénz van a ládában, felment a király íródeákja a főpappal együtt, csomóba kötötték és megszámlálták a pénzt, a mely az Úr házában találtatott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'És a megmért pénzt a munka vezetőinek kezeibe adták, a kik az Úr házához voltak rendelve, és ezek kiadták azt az ácsoknak és építőknek, a kik a házon dolgoztak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'És a kőmíveseknek és a kőfaragóknak, fa és faragott kő vásárlására, az Úr háza romlásainak kijavítására, és mindarra, a mi a ház javítására szükséges volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'De abból a pénzből, a melyet bevittek az Úr házába, nem csináltattak az Úr házához sem ezüst poharakat, sem késeket, sem medenczéket, sem trombitákat, sem valami egyéb arany vagy ezüst edényt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'Hanem a munkásoknak adták azt, és csak az Úr házát javították ki abból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'Számot sem vettek azoktól az emberektől, a kiknek keze által kiadták a pénzt a munkásoknak, mert híven jártak el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'De a vétekért és a bűnért való pénzt nem vitték az Úr házába; az a papoké lett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'Ebben az időben jött fel Hazáel, Siria királya, és megszállotta Gáthot, és be is vette azt; azután megfordult Hazáel, hogy Jeruzsálem ellen menjen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'De Joás, Júda királya, vevé mind a megszentelt ajándékokat, a melyeket az ő atyái, Josafát, Jórám és Akházia, Júda királyai az Úrnak szenteltek volt, és a melyeket ő maga szentelt néki, és minden aranyat, a mely találtaték mind az Úr házának, mind pedig a király házának kincsei között, és elküldé Hazáelnek, Siria királyának, és az elment Jeruzsálem alól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'Joásnak egyéb dolgai és minden cselekedetei pedig, vajjon nincsenek-é megírva a Júda királyainak krónika-könyvében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'Fellázadván pedig az ő szolgái, pártot ütének ellene, és megölték Joást Beth-Millóban, a merre Sillába megy az ember.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'Jozakhár, a Simeáth fia, és Jozadáb, a Sómer fia, az ő szolgái ölték meg őt, és meghalt és eltemették őt az ő atyáival, a Dávid városában. És Amásia, az ő fia lett a király ő helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'Joásnak, az Akházia fiának, Júda királyának huszonharmadik esztendejében lett király Joákház, a Jéhu fia Izráelen Samariában tizenhét esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'És gonoszul cselekedék az Úr szemei előtt, és követé Jeroboámnak, a Nébát fiának bűneit, a ki bűnbe ejté az Izráelt, és nem szakadt el azoktól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'És felgerjedt az Úr haragja Izráel ellen, és adá őket Hazáelnek, a Siria királyának kezébe, és Benhadádnak, a Hazáel fiának kezébe, az ő életének minden idejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'De könyörgött Joákház az Úrnak, és meghallgatá őt az Úr; mert megtekintette az Izráel nyomorúságát, hogy mikép nyomorgatja őket Siria királya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, 'És az Isten szabadítót küldött Izráelnek, a ki megmentette őket a Siriabeliek hatalmától, hogy az Izráel fiai lakhassanak az ő sátoraikban, mint azelőtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'De még sem távoztak el a Jeroboám házának bűneitől, a ki bűnbe ejté az Izráelt, hanem azokban jártak; sőt az Asera is helyén maradt Samariában;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'Pedig nem hagyattatott meg Joákháznak több nép, mint ötven lovag, tíz szekér és tízezer gyalogos; a többit mind megölte Siria királya, és olyanná tette, mint a cséplő pora.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'Joákház egyéb dolgai pedig és minden cselekedetei és az ő ereje, vajjon nincsenek-é megírva az Izráel királyainak krónika-könyvében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'És elaluvék Joákház az ő atyáival, és eltemették őt Samariában; és az ő fia, Joás, uralkodék ő helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'Joásnak, a Júda királyának harminczhetedik esztendejében lett a király Joás, a Joákház fia, Izráelen Samariában, tizenhat esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'És gonoszul cselekedék az Úr szemei előtt, és nem távozék el Jeroboámnak, a Nébát fiának semmi bűnétől, a ki az Izráelt bűnbe ejté, hanem azokban járt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'Joásnak egyéb dolgai pedig és valamit cselekedett és az ő erőssége, a melylyel Amásia, a Júda királya ellen harczolt, vajjon nincsenek-é megírva az Izráel királyainak krónika-könyvében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'És elaluvék Joás az ő atyáival, és Jeroboám ült az ő királyi székibe; és eltemetteték Joás Samariában, az Izráel királyai mellé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'És megbetegedett Elizeus olyan betegséggel, a melybe bele is halt, és lement hozzá Joás, az Izráel királya, és arczára borulván sírt és monda: Édes atyám, édes atyám! Izráel szekerei és lovagjai!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'És monda néki Elizeus: Végy kézívet és nyilakat. És ő kézívet és nyilakat vett kezébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'Akkor monda az Izráel királyának: Fogd meg kezeddel a kézívet. És ő megfogván azt kezével, Elizeus is rátette kezeit a király kezeire;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'És monda: Nyisd ki az ablakot napkelet felől. És mikor kinyitotta, monda Elizeus: Lőjj! És lőtt. Akkor monda: Az Úrnak győzedelmes nyíla ez, győzedelmes nyíl a Siriabeliek ellen; mert megvered a Siriabelieket Afekben a megsemmisülésig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'Monda azután: Vedd fel a nyilakat. És felvette. Ő pedig monda az Izráel királyának: Lőjj a földbe, és bele lőtt a földbe háromszor; azután abbahagyta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'Akkor megharaguvék reá az Isten embere, és monda: Ötször vagy hatszor kellett volna lőnöd, akkor megverted volna a Siriabelieket a megsemmisülésig; de így már csak háromszor vered meg a Siriabelieket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'Azután meghalt Elizeus, és eltemették. A moábita portyázó csapatok pedig az országba törtek a következő esztendőben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'És történt, hogy egy embert temettek, és mikor meglátták a csapatokat, gyorsan odatették azt az embert az Elizeus sírjába; de a mint odajutott és hozzáért az Elizeus tetemeihez, megelevenedett és lábaira állott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'Hazáel pedig, Siria királya nyomorgatá az Izráelt Joákház minden napjaiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'De megkegyelmezett az Úr nékik, és megkönyörült rajtok, és hozzájok tért az ő szövetségéért, a melyet kötött volt Ábrahámmal, Izsákkal és Jákóbbal, és nem akarta őket elveszíteni, sem el nem vetette őket az ő orczája elől mind ez ideig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'És meghalt Hazáel, Siria királya, és az ő fia, Benhadád lett helyette a király.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'És visszavevé Joás, a Joákház fia Benhadádnak, a Hazáel fiának kezéből a városokat, a melyeket erővel elvett volt Joákháznak, az ő atyjának kezéből. Háromszor veré meg őt Joás, és visszaszerezte Izráel városait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'Joásnak, a Joákház fiának, Izráel királyának második esztendejében kezdett uralkodni Amásia, Joásnak, a Júda királyának fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'Huszonöt esztendős volt, mikor uralkodni kezdett, és huszonkilencz esztendeig uralkodott Jeruzsálemben. Az ő anyjának pedig Joáddán volt a neve, Jeruzsálemből való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'És kedves dolgot cselekedett az Úr szemei előtt, de még sem annyira, mint Dávid, az ő atyja, hanem csak úgy tett mindent, mint az ő atyja, Joás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'Mert a magaslatokat nem rontották le, hanem a nép még mindig ott áldozott és ott tömjénezett a magaslatokon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'Mikor azután a birodalom kezében megerősödött, megölte az ő szolgáit, a kik a királyt, az ő atyját megölték volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'De a gyilkosok fiait nem ölte meg, a mint meg van írva a Mózes törvénykönyvében, a melyben az Úr megparancsolta és megmondotta: Meg ne ölettessenek az atyák a fiakért, se a fiak meg ne ölettessenek az atyákért; kiki az ő bűnéért haljon meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'Ugyanő megvert az Edomiták közül tízezeret a sós völgyben; és bevette Sélát ostrommal, és ezt nevezé Jokteélnek mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'Akkor követeket küldött Amásia Joáshoz, a Joákház fiához, a ki Jéhunak, az Izráel királyának volt a fia, ezt izenvén: Jere, nézzünk egymás szemébe!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'És elkülde Joás, Izráel királya Amásiához, Júda királyához, ezt válaszolván: A bogácskóró, mely a Libánonon van, elküldött a Libánon czédrusfájához, ezt izenvén: Add a te leányodat az én fiamnak feleségül; de a mező vadja, a mely a Libánonon van, átszaladt a bogácskórón, és eltapodta azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'Megverted az Edomitákat, azért fuvalkodtál fel szívedben. Elégedjél meg a dicsőséggel és maradj otthon; miért akarsz a szerencsétlenséggel harczra kelni, hogy elessél magad is és Júda is veled együtt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'De Amásia nem hallgatott reá, és felvonult Joás, Izráel királya, és szembe-szállottak egymással, ő és Amásia, Júda királya Bethsemesnél, amely Júdában van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'De megveretett Júda Izráeltől, és kiki elfutott az ő sátorába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'És Amásiát, Júda királyát, Joásnak, az Akházia fiának fiát is elfogta Joás, Izráel királya Bethsemesnél; és Jeruzsálem ellen ment, és lerontotta Jeruzsálem kerítését, az Efraim kapujától egész a szegletkapuig, négyszáz singre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'És elvitt minden aranyat, minden ezüstöt és minden edényt, a mely találtatott az Úr házában és a király házának kincsei között, és kezeseket is vévén, visszatért Samariába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'Joás egyéb dolgai pedig, a melyeket cselekedett, és az ő erőssége, és miképen hadakozott Amásia, a Júda királya ellen, vajjon nincsenek-é megírva az Izráel királyainak krónika-könyvében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'És elaluvék Joás az ő atyáival, és eltemetteték Samariában az Izráel királyaival együtt; és az ő fia, Jeroboám uralkodék ő helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'Amásia pedig, Joásnak, a Júda királyának fia, Joásnak, a Joákház fiának, az Izráel királyának halála után még tizenöt esztendeig élt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'És Amásiának egyéb dolgai vajjon nincsenek-é megírva a Júda királyainak krónika-könyvében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'És pártot ütöttek ő ellene Jeruzsálemben, és ő Lákisba menekült; de utána küldtek Lákisba, és megölték ott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'És visszahozták őt lovakon, és eltemetteték Jeruzsálemben, a Dávid városában az ő atyáival.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'És az egész Júda népe vevé Azáriát, a ki tizenhat esztendős volt, és őt tette királylyá, az ő atyja, Amásia helyett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'Ő építé meg Elátot, a melyet visszavett Júdának azután, hogy a király elaludt az ő atyáival.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'Amásiának, Joásnak, a Júda királya fiának tizenötödik esztendejétől fogva uralkodott Jeroboám, Joásnak, az Izráel királyának fia Samariában, negyvenegy esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'És gonoszul cselekedék az Úr szemei előtt, mert Jeroboámnak, a Nébát fiának semmi bűnétől el nem távozott, a ki bűnbe ejtette az Izráelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'Ő szerezte vissza az Izráel határát Emáthtól fogva a pusztasági tengerig, az Úrnak, Izráel Istenének beszéde szerint, a melyet szólott volt az ő szolgája, Jónás próféta, az Amittai fia által, a ki Gáth-Kéferből való volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'Mert megtekintette az Úr az Izráel igen nagy nyomorúságát, hogy a berekesztetett és az elhagyatott is semmi és nincs senki, a ki az Izráelt megszabadítaná.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'És nem mondta azt az Úr, hogy az Izráel nevét eltörli az ég alól; annakokáért megszabadította őket Jeroboám, a Joás fia által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'Jeroboám egyéb dolgai pedig és minden cselekedetei és az ő erőssége, hogy miképen hadakozott, és mi módon nyerte vissza Damaskust és a Júdához tartozó Hámátot az Izráelnek, vajjon nincsenek-é megírva az Izráel királyainak krónika-könyvében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'És elaluvék Jeroboám az ő atyáival, Izráel királyaival, és uralkodék az ő fia, Zakariás, ő helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'Jeroboámnak, az Izráel királyának huszonhetedik esztendejében kezdett uralkodni Azária, Amásiának, a Júda királyának fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'Tizenhat esztendős volt, mikor uralkodni kezdett, és ötvenkét esztendeig uralkodott Jeruzsálemben, és az ő anyjának neve Jekólia, Jeruzsálemből való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'És kedves dolgot cselekedék az Úr szemei előtt mind a szerint, a mint az ő atyja, Amásia cselekedett;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'Csakhogy a magaslatok nem rontattak le, a nép még ott áldozott és tömjénezett a magaslatokon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'És megverte az Úr a királyt, mert bélpoklos lett egész halála napjáig, és külön házban lakott, és Jótám, a király fia kormányozta a házat, és ő szolgáltatott törvényt a föld népének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'Azáriának egyéb dolgai pedig és minden cselekedetei, vajjon nincsenek-é megírva a Júda királyainak krónika-könyvében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'És elaluvék Azária az ő atyáival, és eltemeték őt az ő atyáival a Dávid városában, és az ő fia, Jótám, uralkodék ő helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'Azáriának, a Júda királyának harmincznyolczadik esztendejében kezdett uralkodni Zakariás, a Jeroboám fia Izráelen, Samariában hat hónapig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'És gonoszul cselekedék az Úr szemei előtt, miképen az ő atyái cselekedtek volt. Nem hagyta el Jeroboámnak, a Nébát fiának bűneit, a ki vétekbe ejtette az Izráelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'És összeesküdött ellene Sallum, a Jábes fia, és megölte őt a nép szeme láttára, és megölvén őt, ő uralkodott helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'Zakariásnak egyéb dolgai pedig, ímé meg vannak írva az Izráel királyainak krónika-könyvében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'Ez az Úr beszéde, a mit Jéhu felől szólott, mondván: A te fiaid negyedízig ülnek Izráel trónján. És így történt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Sallum, a Jábes fia lett a király Uzziának, Júda királyának harminczkilenczedik esztendejében, de csak egy hónapig uralkodott Samariában;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'Mert Menáhem, a Thirsabeli Gádi fia feljött, és Samariába ment, és megölte Sallumot, a Jábes fiát Samariában, és megölvén őt, ő uralkodott helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'Sallumnak egyéb dolgai pedig és összeesküvése, a melyet csinált, ímé meg vannak írva az Izráel királyainak krónika-könyvében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'Akkor verte le Menáhem Tifsáhot és mindazokat, a kik benne voltak, és egész határát Thirsától fogva, mert nem bocsátották be, azért veré le, és még a terhes asszonyokat is mind felhasogatá benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'Azáriának, Júda királyának harminczkilenczedik esztendejétől fogva uralkodott Menáhem, a Gádi fia Izráelen tíz esztendeig Samariában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'És gonoszul cselekedék az Úr szemei előtt; nem hagyta el Jeroboámnak, a Nébát fiának bűneit teljes életében, a ki vétekbe ejtette az Izráelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'És rátört Púl, Assiria királya az országra, és Menáhem Púlnak ezer tálentom ezüstöt adott azért, hogy legyen néki segítséggel az ő birodalmának megerősítésében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'És Menáhem adót vetett Izráelben a gazdagokra, ötven ezüst siklust minden egyes emberre, hogy azt Assiria királyának adja, és visszatért Assiria királya, és nem maradt ott az országban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'Menáhemnek egyéb dolgai pedig és minden cselekedetei, vajjon nincsenek-é megírva az Izráel királyainak krónika-könyvében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'És elaluvék Menáhem az ő atyáival, és uralkodék az ő fia, Pekája ő helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'És Azáriának, Júda királyának ötvenedik esztendejében kezdett uralkodni Pekája, a Menáhem fia, Izráelen Samariában két esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'És gonoszul cselekedék az Úr szemei előtt, nem távozék el Jeroboámnak, a Nébát fiának bűneitől, a ki vétekbe ejtette az Izráelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'És pártot ütött ellene Péka, a Remália fia, az ő hadnagya, és megölte őt Samariában, a király házának palotájában, Argóbbal és Arjéval és ötven emberrel a Gileádbeliek fiai közül, és megölte őt, és ő lett helyébe a király.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'Pekájának egyéb dolgai pedig és minden cselekedetei, ímé meg vannak írva az Izráel királyainak krónika-könyvében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'Azáriának, Júda királyának ötvenkettedik esztendejében kezdett uralkodni Péka, a Remália fia, Izráelen Samariában húsz esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'És gonoszul cselekedék az Úr szemei előtt; nem távozék el Jeroboámnak, a Nébát fiának bűneitől, a ki vétekbe ejtette az Izráelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'Pékának, az Izráel királyának idejében jött el Tiglát-Piléser, Assiria királya, és foglalta el Hijont, Abélt, Beth-Maakát, Jánoát, Kédest, Hásort, Gileádot, Galileát és a Nafthali egész földét, és hurczolta el őket, Assiriába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'De Hósea, az Ela fia, pártot ütött Péka, a Remália fia ellen, és levágta és megölte őt, és ő lett helyébe a király Jótámnak, az Uzzia fiának huszadik esztendejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'Pékának egyéb dolgai pedig és minden cselekedetei, ímé meg vannak írva az Izráel királyainak krónika-könyvében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'Pékának, a Remália fiának, az Izráel királyának második esztendejében kezdett uralkodni Jótám, Uzziának, a Júda királyának fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'Huszonöt esztendős volt, a mikor uralkodni kezdett, és tizenhat esztendeig uralkodott Jeruzsálemben. Az ő anyjának Jérusa volt a neve, a Sádók leánya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'És kedves dolgot cselekedék az Úr szemei előtt, mind a szerint, a mint az ő atyja, Uzzia cselekedék;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'Csak a magaslatokat nem rontották le; még ott áldozott és tömjénezett a nép a magaslatokon. Ő építette meg az Úr házának felső kapuját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'Jótámnak egyéb dolgai pedig és minden cselekedetei, vajjon nincsenek-é megírva a Júda királyainak krónika-könyvében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'Ebben az időben kezdte az Úr ráküldeni Júdára Réczint, Siria királyát, és Pékát, a Remália fiát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'És elaluvék Jótám az ő atyáival, és eltemetteték az ő atyáival, Dávidnak, az ő atyjának városában, és Akház, az ő fia, uralkodék ő helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'Pékának, a Remália fiának tizenhetedik esztendejében kezdett uralkodni Akház, Jótámnak, a Júda királyának fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'Húsz esztendős volt Akház, mikor uralkodni kezdett, és tizenhat esztendeig uralkodott Jeruzsálemben; de nem azt cselekedé, a mi az Úrnak, az ő Istenének tetszett volna, a mint Dávid, az ő atyja,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'Hanem az Izráel királyainak útjokon járt, még az ő fiát is átvitte a tűzön, a pogányok útálatosságai szerint, a kiket az Úr az Izráel fiai előtt kiűzött volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'És ott áldozott és tömjénezett a magaslatokon és a halmokon és minden zöld fa alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'Abban az időben jött fel Réczin, Siria királya, és Péka, a Remália fia, az Izráel királya, Jeruzsálemet vívatni, és körülzárták Akházt, de nem tudták legyőzni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'Akkor nyerte vissza Réczin, Siria királya Elátot a Siriabelieknek, és irtotta ki a zsidókat Elátból; és Siriabeliek jövének Elátba, és ott laknak mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'És követeket küldött Akház Tiglát-Piléserhez, Assiria királyához, ezt izenvén: Te szolgád és a te fiad vagyok; jőjj fel és szabadíts meg engem Siria királyának kezéből és az Izráel királyának kezéből, a kik reám támadtak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'És vevé Akház az ezüstöt és aranyat, és a mely találtaték az Úr házában és a király házának kincsei között, és ajándékba küldé Assiria királyának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'És engedett néki Assiria királya, és feljövén Assiria királya Damaskus ellen, bevette azt, és a benne levőket Kirbe hurczolta; Réczint pedig megölte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'És eleibe ment Akház Tiglát-Pilésernek, Assiria királyának Damaskusba, és mikor meglátta Akház király azt az oltárt, a mely Damaskusban volt, elküldte Akház király annak az oltárnak hasonlatosságát és képét minden felszerelésével Uriás paphoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'És megépítette Uriás pap az oltárt arra a formára, a melyet Akház király Damaskusból küldött, és elkészíté azt Uriás pap, mire Akház király visszajött Damaskusból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'És mikor megjött a király Damaskusból és meglátta a király az oltárt: az oltárhoz ment a király és áldozott rajta,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'És meggyújtotta az ő égőáldozatját és ételáldozatját, és áldozott italáldozattal is, és az ő hálaáldozatainak vérét elhintette az oltár körül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'És a rézoltárt, a mely az Úr előtt állott, elviteté a ház elől, hogy ne álljon az ő oltára és az Úr háza között, és helyhezteté azt az oltár szegletéhez észak felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'És megparancsolta Akház király Uriás papnak, mondván: E nagy oltáron gyújtsd meg a reggeli égőáldozatot és az esteli ételáldozatot, a király égőáldozatját is az ő ételáldozatával együtt, az egész föld népének is mind égőáldozatát, mind ételáldozatját, mind italáldozatját, és az égőáldozat minden vérét és egyéb áldozatnak minden vérét a körül hintsed el; a rézoltár felől pedig még majd gondolkozom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'És Uriás pap mind a szerint cselekedék, a mint Akház király megparancsolta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'És letörte Akház király a talpak oldalait, és lehányta azokról a mosdómedenczéket; a tengert is ledobta a rézökrökről, a melyeken állott, és kőtalapzatra tette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'És áthelyezte a szombati hajlékot, a melyet a házban építettek, és a király külső bejáró helyét az Úr házában, Assiria királya miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'Akháznak egyéb dolgai pedig, a melyeket cselekedett, vajjon nincsenek-é megírva a Júda királyainak krónika-könyvében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'És elaluvék Akház az ő atyáival, és eltemetteték az ő atyáival a Dávid városában, és uralkodék ő helyette az ő fia, Ezékiás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'Akháznak, a Júda királyának tizenkettedik esztendejében kezdett uralkodni Hóseás, az Ela fia, Samariában Izráelen, kilencz esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'És gonoszul cselekedék az Úr szemei előtt; de nem annyira, mint Izráel ama királyai, a kik előtte éltek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'Ez ellen jött fel Salmanassár, Assiria királya, és szolgájává lett Hóseás, és adót fizetett néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'De mikor Assiria királya megtudta, hogy Hóseás pártot ütött ellene és követeket küldött Suához, Égyiptom királyához, az évenkénti adót pedig nem küldötte meg Assiria királyának: elfogatta őt Assiria királya és börtönbe vetette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'És felméne az assiriai király az egész ország ellen, és feljövén Samaria ellen, azt három esztendeig ostromolta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'És Hóseásnak kilenczedik esztendejében bevette Assiria királya Samariát, és elhurczolta az Izráelt Assiriába; és Halában és Háborban a Gózán folyó mellett, és a Médek városaiban telepítette le őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'Ez pedig azért történt, mert az Izráel fiai vétkeztek az Úr ellen, az ő Istenök ellen, a ki őket kihozta Égyiptom földéből, a Faraónak, az égyiptomi királynak kezéből, és idegen isteneket tiszteltek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'És jártak a pogányok szerzésekben, a kiket az Úr kiűzött volt az Izráel fiai elől, és úgy cselekedtek, mint az Izráel királyai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'És alattomban oly dolgokat cselekedtek az Izráel fiai, a melyek ellenére voltak az Úrnak, az ő Istenöknek, és építettek magoknak magaslatokat minden városaikban, az őrtornyoktól a kerített városokig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'És emeltek magoknak faragott képeket és Aserákat minden magas halmokon és minden zöld fa alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'És ott tömjéneztek minden magaslaton, mint a pogányok, a kiket az Úr kiűzött volt előlök, és gonosz dolgokat cselekedtek, a melyekkel az Urat haragra indították.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'És a bálványoknak szolgáltak, a kik felől az Úr azt parancsolta volt nékik: Ezt ne cselekedjétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'És mikor bizonyságot tett az Úr Izráelben és Júdában minden prófétája és minden látnoka által, ezt mondván: Térjetek meg a ti gonosz útaitokról, és őrizzétek meg az én parancsolataimat és rendeléseimet, az egész törvény szerint, a melyet parancsoltam a ti atyáitoknak; és a melyet ti hozzátok küldöttem az én szolgáim, a próféták által:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'Akkor nem engedelmeskedtek, hanem megkeményítették az ő nyakokat atyáik makacssága szerint, a kik nem hittek az Úrban, az ő Istenökben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'Sőt megvetették az ő rendeléseit és szövetségét, a melyet atyáikkal kötött, és az ő bizonyságtételeit, a melyekkel megintette őket, és hiábavalóságot követvén, magok is hiábavalókká lettek, és a körültök való pogányok után indultak, a kik felől pedig azt parancsolta nékik az Úr, hogy azokat ne utánozzák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'És elhagyták az Úrnak, az ő Istenöknek minden parancsolatját, és öntött képeket csináltak magoknak, két borjút és készítettek Aserát, és meghajlottak az ég minden seregei előtt, és a Baált tisztelték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'És átvitték fiaikat és leányaikat a tűzön, jövendőket mondtak és varázslást űztek, és magokat teljesen eladták a bűnnek az Úr bosszantására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'Azért igen megharaguvék az Úr Izráelre, és elveté őt színe elől; és semmi nem maradt meg, hanem csak a Júda nemzetsége egyedül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Sőt még a Júda sem őrizte meg az Úrnak, az ő Istenének parancsolatait, hanem az Izráel szerzésiben jártak, úgy cselekedvén, mint azok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'Elidegenült azért az Úr az egész Izráel magvától, és megsanyargatta őket, és a kóborlók kezébe adta őket, mígnem mind elvetette az ő szemei elől;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'Mert elszakasztotta Izráelt a Dávid házától, és királylyá tevék Jeroboámot, a Nébát fiát. És Jeroboám elcsalta az Izráelt az Úrtól, és igen nagy vétekbe ejtette őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'És az Izráel fiai követték Jeroboám minden bűnét, a melyeket elkövetett, és nem távoztak el azoktól;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'Míglen elveté az Úr az ő színe elől az Izráelt, a mint megmondotta minden ő szolgái, a próféták által. Így hurczoltatott el fogságra az Izráel az ő földéből Assiriába mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'És más népet telepített be Assiria királya Babilóniából, Kutából, Avából, Hámátból és Sefárvaimból, és beszállítá őket Samaria városaiba az Izráel fiai helyett, a kik birtokba vették Samariát, és annak városaiban laktak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'És történt ott lakásuk kezdetén, hogy nem az Urat félték, és az Úr oroszlánokat bocsátott reájok, a melyek többet megöltek közülök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'Mondának azért Assiria királyának: A pogányok, a kiket ide hoztál és Samaria városaiba telepítettél, nem tudják e föld Istene tiszteletének módját, azért oroszlánokat bocsátott az rájok, a melyek megölik őket, mert nem tudják e föld Istene tiszteletének módját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'Parancsola azért Assiria királya, mondván: Vigyetek oda egyet a papok közül, a kiket onnét elhoztatok, a ki menjen el és lakjék ott, és tanítsa meg őket ama föld Istene tiszteletének módjára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'És elméne egy a papok közül, a kiket Samariából elvittek volt, és lakék Béthelben, és megtanította őket, hogy mikép tiszteljék az Urat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'De azért mindenik nép külön isteneket csinált magának, és behelyezték azokat a magaslatok házaiba, a melyeket a Samaritánusok építettek, mindenik nemzetség a maga városában, a melyben lakott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'A Babilonból való férfiak csinálták a Sukkót-Benótot, a Kutból való férfiak csinálták a Nérgelt, és a Hámátból való férfiak az Asimát csinálták;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'A Háveusok pedig a Nibeházt és a Tartákot csinálták, míg a Sefárvaimbeliek tűzzel égették meg az ő magzatjaikat az Adraméleknek és Anaméleknek, a Sefárvaimbeliek isteneinek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'De miután az Urat is tisztelték, a magaslatokra papokat állítottak a maguk tömegéből, a kik ő érettök áldoztak a magaslatok házaiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'Így tisztelték az Urat és szolgálták az ő isteneiket is, ama népek szokása szerint, a kik közül elhozták volt őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'És mind e mai napig az ő régi szokásuk szerint cselekesznek; nem tisztelik igazán az Urat, és nem cselekesznek az ő rendeléseik és szokásuk szerint, sem pedig ama törvény és parancsolat szerint, a melyet az Úr parancsolt a Jákób fiainak, a kiknek az Izráel nevet adta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 'És a kikkel az Úr szövetséget kötött, és megparancsolta nékik, mondván: Ne tiszteljetek idegen isteneket, és ne imádjátok őket, és ne szolgáljatok és ne áldozzatok nékik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'Hanem csak az Urat tiszteljétek, őt imádjátok és néki áldozzatok, a ki titeket kihozott az Égyiptom földéből nagy erővel és kinyújtott karral.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'És őrizzétek meg az ő rendeléseit, ítéleteit, törvényét és parancsolatját, a melyeket megírt néktek, azokat cselekedvén minden időben, és idegen isteneket ne tiszteljetek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'És el ne felejtkezzetek a kötésről, a melyet veletek tettem, és ne tiszteljetek idegen isteneket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'Hanem az Urat tiszteljétek, a ti Isteneteket, és ő megszabadít titeket minden ellenségetek kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'De ezek nem engedelmeskedtek, hanem előbbi szokásaik szerint cselekedtek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'Így tisztelték ezek a pogányok az Urat és szolgálták az ő bálványaikat, és így cselekedtek az ő fiaik és unokáik is, a mint az ő eleik cselekedtek, mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'És Hóseásnak, az Ela fiának, az Izráel királyának harmadik esztendejében kezdett uralkodni Ezékiás, Akháznak, a Júda királyának fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'Huszonöt esztendős volt, mikor uralkodni kezdett, és huszonkilencz esztendeig uralkodott Jeruzsálemben; anyjának neve Abi, a Zakariás leánya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'És kedves dolgot cselekedék az Úr szemei előtt, a mint az ő atyja, Dávid cselekedett volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'Ő rontotta le a magaslatokat, törte el az oszlopokat, és vágta ki az Aserát, és törte össze az érczkígyót is, a melyet Mózes csinált; mert mind az ideig az Izráel fiai jóillatot tettek annak, és nevezék azt Nékhustánnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'Egyedül az Úrban, Izráel Istenében bízott, és ő utána nem volt hozzá hasonló Júda minden királyai között sem azok között, a kik ő előtte voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'Mert az Úrhoz ragaszkodott, és el nem hajlott ő tőle, és megőrizte az ő parancsolatait, a melyeket az Úr Mózesnek parancsolt vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'És vele volt az Úr mindenütt és a hova csak ment, előmenetele volt. És elszakadt Assiria királyától, és nem szolgált néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'Megverte a Filiszteusokat is egész Gázáig és határukat, az őrtornyoktól a kerített városokig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'Ezékiás királynak negyedik esztendejében – a mely Hóseásnak, az Ela fiának, az Izráel királyának hetedik esztendeje – feljött Salmanassár, Assiria királya Samaria ellen, és megszállotta azt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'És elfoglalta három esztendő mulva, Ezékiás hatodik esztendejében – ez Hóseásnak, az Izráel királyának kilenczedik esztendeje – ekkor vették be Samariát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'És elhurczolta Assiria királya az Izráelt Assiriába, és letelepíté Halába, Háborba, a Gózán folyó mellé, és a Médeusok városaiba;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'Azért, mert nem hallgattak az Úrnak, az ő Istenöknek szavára, hanem megszegték az ő szövetségét, mindazokat, a melyeket Mózes, az Úr szolgája parancsolt vala; sem nem hallgattak rájok, sem nem cselekedték azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'Ezékiás királynak pedig tizennegyedik esztendejében feljött Sénakhérib, Assiria királya Júdának minden kerített városa ellen, és elfoglalta azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'Akkor elküldött Ezékiás, Júda királya Assiria királyához Lákisba, ezt izenvén: Vétkeztem, térj el én rólam; a mit rám vetsz, elviselem! És Assiria királya Ezékiásra, Júda királyára háromszáz tálentom ezüstöt és harmincz tálentom aranyat vetett ki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'És Ezékiás oda adott minden ezüstöt, a mely találtatott az Úr házában és a király házának kincsei között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'Ugyanebben az időben fosztotta meg Ezékiás az Úr templomának ajtajait és az ajtók félfáit, a melyeket Ezékiás, Júda királya maga boríttatott be, és oda adta azokat Assiria királyának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'És Assiria királya mégis oda küldte Thartánt, Rabsárist és Rabsakét Lákisból Ezékiás királyhoz igen nagy haddal Jeruzsálembe, és felmenének és jutának Jeruzsálembe, és feljövén és oda érvén, megállának a felső halastó zsilipjénél, a mely a ruhafestő útja mellett van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'És kihívaták a királyt. És kiméne hozzájok Eliákim, a Hilkia fia, ki a király házának gondviselője volt, és Sebna, az íródeák, és Joákh, az Asáf fia, az emlékíró.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'És monda nékik Rabsaké: Mondjátok meg Ezékiásnak: Ezt mondja a király, Assiria nagy királya: Micsoda bizodalom ez, a melyben te bizakodtál?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'Azt mondád: csak szóbeszéd; tanács és erő kell a hadakozáshoz; vajjon kihez bíztál, hogy fellázadtál ellenem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'Ímé, ebben a törött nádszálban bizakodol, Égyiptomban, melyhez ha ki támaszkodik, bemegy az ő kezébe és általlikasztja? Ilyen a Faraó, Égyiptom királya mindenekhez, a kik ő hozzá bíznak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'Vagy azt akarjátok nékem mondani: Mi az Úrban, a mi Istenünkben bízunk; hát nem ez-é az, a kinek magaslatait és oltárait lerontotta Ezékiás, és mind Júdának, mind Jeruzsálemnek megparancsolta: Ez oltár előtt imádkozzatok Jeruzsálemben?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'Nosza, fogadj hát az én urammal, Assiria királyával: Én néked kétezer lovat adok, ha tudsz reájok adni annyi lovast.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'Hogy verhetnél hát vissza az én uram legkisebb hadnagyai közül csak egyet is, és hogyan bízhatol Égyiptomhoz a szekerek és a lovagok miatt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Vajjon az Úr tudta nélkül jöttem-é fel e hely ellen, hogy azt elveszessem? Az Úr mondotta nékem: Menj fel e föld ellen, és veszesd el azt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'És monda Eliákim, a Hilkia fia, és Sebna és Joákh Rabsakénak: Beszélj, kérlek, a te szolgáiddal siriai nyelven, mert jól értjük; és ne beszélj velünk zsidóul e nép füle hallatára, a mely a kőfalon van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'És felele nékik Rabsaké: Vajjon a te uradhoz, vagy te hozzád küldött-é engem az én uram, hogy elmondjam e dolgokat, avagy nem inkább e férfiakhoz-é, a kik a kőfalon ülnek, hogy azután veletek együtt egyék meg a saját ganéjokat, és igyák meg a saját vizeletöket?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'És oda állott Rabsaké, és hangosan kezdett zsidóul beszélni, mondván: Halljátok meg a királynak, Assiria nagy királyának beszédit!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'Azt mondja a király: Meg ne csaljon titeket Ezékiás; mert nem szabadíthat meg titeket az ő kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'És ne biztasson titeket Ezékiás az Úrral, ezt mondván: Kétség nélkül megszabadít minket az Úr, és nem adatik e város az assiria király kezébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'Ne hallgassatok Ezékiásra; mert így szól Assiria királya: Békéljetek meg velem, és jőjjetek ki hozzám, és kiki egyék az ő szőlőjéből és fügefájáról, és igyék az ő kútjának vizéből;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'Míg eljövök és elviszlek titeket a ti földetekhez hasonló földre, gabonás és boros földre, kenyeres és szőlős földre, olajfás, és mézes földre, hogy élhessetek és meg ne haljatok. Ne higyjetek Ezékiásnak, mert félrevezet benneteket, mikor azt mondja: Az Úr megszabadít minket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Vajjon megszabadították-é a pogányok istenei, mindenik a maga földjét Assiria királyának kezéből?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'Hol vannak Hámátnak és Arphádnak istenei? Hol Sefárvaimnak, Hénának és Hivvának istenei? És Samariát is megszabadították-é az én kezemből?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Kicsoda a földön való minden istenek közül, a ki megszabadíthatta volna az ő földjét az én kezemből, hogy az Úr is kiszabadíthatná Jeruzsálemet az én kezemből?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'De a nép csak hallgatott, és nem felelt néki csak egy igét sem; mert a király megparancsolta volt, mondván: Ne feleljetek néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'És elment Eliákim, a Hilkia fia, a király házának gondviselője, és Sebna, az íródeák, és Joákh, az Asáf fia, az emlékíró, Ezékiáshoz megszaggatott ruhákban, és elmondák néki Rabsaké beszédit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'Mikor pedig ezeket hallotta Ezékiás király, megszaggatta az ő ruháit, és zsákba öltözék, és bement az Úr házába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'És elküldte Eliákimot, a király házának gondviselőjét, és Sebnát, az íródeákot, és a papoknak véneit, a kik zsákba öltöztek, Ésaiás prófétához, az Ámós fiához;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'És mondának néki: Ezt mondja Ezékiás: E nap nyomorúságnak, szidalmazásnak és káromlásnak napja; mert a fiak a szülésre jutottak, de nincs erő szüléshez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Netalán az Úr, a te Istened meghallotta Rabsakénak minden beszédit, a kit elküldött az ő ura, Assiria királya, hogy szidalommal illesse az élő Istent és káromló beszédekkel, a melyeket az Úr, a te Istened meghallott: könyörögj azért azokért, a kik még megmaradtak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'És elmenének az Ezékiás király szolgái Ésaiáshoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'És monda nékik Ésaiás: Ezt mondjátok a ti uratoknak: Ezt mondja az Úr: Ne félj a beszédektől, a melyeket hallottál, a melyekkel szidalmaztak engem Assiria királyának szolgái.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Ímé én oly lelket adok belé, hogy hírt hallván, visszatér az ő földjére és fegyverrel vágatom le őt az ő földjében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'És mikor visszatért Rabsaké, Assiria királyát Libna ellen harczolva találta, mert meghallotta volt, hogy Lákisból elment.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'És hallván Tirháka felől, a szerecsen király felől, ezt mondván: Ímé kijött, hogy hadakozzék te ellened; visszafordult és követeket küldött Ezékiáshoz, ezt izenvén:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, 'Így szóljatok Ezékiásnak, a Júda királyának, mondván: Meg ne csaljon téged a te Istened, a kiben bízol, ezt mondván: Nem adatik Assiria királyának kezébe Jeruzsálem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Ímé hallottad, mit cselekedtek Assiria királyai minden országokkal, elvesztvén azokat; és te megszabadulhatsz-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Vajjon megszabadították-é a pogányok istenei azokat, a kiket elvesztettek az én atyáim: Gózánt, Aránt, Résefet és az Eden fiait, a kik Thelasárban voltak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'Hol van Hámát királya, Arphád királya és Sefárvaim város királya? Héna és Hivva?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'És elvevé Ezékiás a levelet a követek kezéből, és elolvasá azt, és felment az Úr házába, és kiterjeszté azt Ezékiás az Úr előtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'És imádkozék Ezékiás az Úr előtt, és monda: Uram, Izráel Istene! a ki a Kérubok között lakol, te vagy egyedül e föld minden országainak Istene, te teremtetted a mennyet és a földet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'Hajtsd hozzám, Uram, a te füledet és halld meg; nyisd fel Uram, a te szemeidet és lásd meg: és halld meg a Sénakhérib beszédét, a ki ide küldött, hogy szidalommal illesse az élő Istent.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'Igaz, Uram, Assiria királyai elpusztították a pogányokat és azok országait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'És az ő isteneiket a tűzbe hányták; de azok nem voltak istenek, hanem csak emberi kéz alkotásai, fa és kő, azért vesztették el őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'Most azonban, mi Urunk, Istenünk, szabadíts meg, kérlek, minket az ő kezéből, hogy megismerje e föld minden országa, hogy te, az Úr, vagy az egyetlen Isten!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'Akkor elküldött Ésaiás, az Ámós fia, Ezékiáshoz, ezt mondván: Azt mondja az Úr, Izráel Istene: A te könyörgésedet, Assiria királya, Sénakhérib felől, meghallgattam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'Ez az, a mit az Úr ő felőle mondott: Megutál téged és megcsúfol téged Sionnak szűz leánya, utánad fejét hajtogatja Jeruzsálem leánya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'Kit szidalmaztál és kit gyaláztál? És ki ellen emelted fel a te szódat, vagy ki ellen emelted fel a te szemeidet a magasságba? Az Izráel szentje ellen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'Követeid által gúnyoltad az Urat, és mondád: Szekereim sokaságával meghágom a hegyek magasságait, a Libánon oldalait, és levágom magas czédrusait, legfelségesebb cziprusfáit, és bemegyek csúcsának lakóhelyébe, kertes erdejébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'Ástam és ittam idegen vizeket, és kiszárítom lábaim talpával Égyiptom minden folyóvizét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'Avagy nem hallottad? Régen megcsináltam, ős időktől elvégeztem ezt! Most csak véghezvittem, hogy puszta kőhalmokká döntsd össze az erős városokat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'És hogy a benne lakók erejökben megfogyatkozzanak, megrontassanak és megszégyenüljenek, és olyanok legyenek mint a mező füve, fiatal paréj, a háztető füve és mint a kalászhajtás előtt elszáradt gabona.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'És ismerem a te ülésedet, és járásodat kelésedet, és ellenem való tombolásodat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'A te ellenem való tombolásodért és a te elbizakodásodért, a mely felhatott füleimbe, az én karikámat orrodba vetem, és zabolámat szádba, és visszaviszlek azon az úton, a melyen eljöttél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'Te néked pedig, Ezékiás, legyen ez jeled: Ez esztendőben táplál a hulladék termése, a második esztendőben, a mi magától terem; de a harmadik esztendőben már vettek és arattok, szőlőket plántáltok és azok gyümölcsét eszitek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'És a Júda házából a kiszabadult és a megmaradt gyökeret ver alól, és gyümölcsöt terem felül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'Mert Jeruzsálemből fog származni a maradék, és a megszabadult a Sion hegyéről; a Seregek Urának buzgó szerelme cselekszi ezt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'Azért azt mondja az Úr Assiria királya felől: Be nem jő e városba, és nyilat sem lő bele, sem paizs nem ostromolja azt, sem sánczot nem ás mellette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'Azon az úton, a melyen jött, tér vissza, de e városba be nem jő, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, 'És megoltalmazom e várost, hogy megtartsam azt, én érettem és Dávidért, az én szolgámért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'És azon az éjszakán kijött az Úr angyala, és levágott az Assiriabeli táborban száznyolczvanötezeret, és mikor jó reggel felkeltek, ímé mindenütt holttestek hevertek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'És elindult, és elment, és visszafordult Sénakhérib, Assiria királya, és Ninivében maradt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'És lőn, mikor ő a Nisróknak, az ő Istenének templomában imádkozék, Adramélek és Sarézer, az ő fiai, levágták őt fegyverrel: magok pedig elszaladtak az Ararát földébe, és az ő fia, Esárhaddon uralkodék helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'Ebben az időben halálosan megbetegedett Ezékiás, és hozzá menvén Ésaiás próféta, az Ámós fia, monda néki: Azt mondja az Úr: Rendeld el házadat, mert meghalsz és nem élsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'Akkor arczczal a falhoz fordult, és könyörgött az Úrnak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, 'Óh Uram, emlékezzél meg róla, hogy te előtted hűséggel és tökéletes szívvel jártam, és hogy azt cselekedtem, a mi jó volt a te szemeid előtt. És sírt Ezékiás nagy sírással.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'Azonban Ésaiás még alig ért a város közepére, mikor az Úr beszéde lőn ő hozzá, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, 'Menj vissza és mondd meg Ezékiásnak, az én népem fejedelmének: Azt mondja az Úr, Dávidnak, a te atyádnak Istene: Meghallgattam a te imádságodat, láttam a te könyhullatásidat, ímé én meggyógyítlak téged, harmadnapra felmégy az Úr házába;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'És a te idődet tizenöt esztendővel meghosszabbítom, és megszabadítlak téged és e várost Assiria királyának kezéből, és megoltalmazom e várost én érettem és Dávidért, az én szolgámért,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'És monda Ésaiás: Hozzatok egy kötés száraz fügét ide. És hozának, és azt a kelevényre kötötték, és meggyógyult.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'És mikor azt kérdezé Ezékiás Ésaiástól: Mi lesz a jele, hogy meggyógyít engem az Úr, és hogy harmadnapra felmehetek az Úr házába?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'Felele Ésaiás: Ez legyen jeled az Úrtól, hogy ő megcselekeszi ezt a dolgot, a melyről szólott néked: Előremenjen-é az árnyék tíz grádicscsal, vagy visszatérjen-é tíz grádicscsal?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'És felele Ezékiás: Könnyű az árnyéknak tíz grádicscsal alábbszállani. Ne úgy, hanem menjen hátra az árnyék tíz grádicscsal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'És könyörgött Ésaiás próféta az Úrhoz, és visszatéríté az árnyékot Akház napóráján, azokon a grádicsokon, a melyeken már aláment volt, tíz grádicscsal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'Ebben az időben küldött Berodákh Baladán, Baladánnak, a babilóniai királynak fia levelet és ajándékokat Ezékiásnak; mert meghallotta, hogy Ezékiás beteg volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'És meghallgatá őket Ezékiás, és megmutatta nékik az ő egész kincsesházát, az ezüstöt, az aranyat, a fűszerszámokat, a drága kenetet és az ő fegyveres házát és mindent, a mi csak találtatott az ő kincstáraiban, és nem volt semmi az ő házában és egész birodalmában, a mit meg nem mutatott volna Ezékiás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'Ekkor jött Ésaiás próféta Ezékiás királyhoz, és monda néki: Mit mondtak ezek a férfiak, és honnét jöttek hozzád? És felele Ezékiás: Messze földről jöttek, Babilóniából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'És monda: Mit láttak a te házadban? Felele Ezékiás: Mindent láttak, a mi csak van az én házamban, és nem volt semmi az én tárházamban, a mit nékik meg ne mutattam volna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'Akkor monda Ésaiás Ezékiásnak: Halld meg az Úrnak beszédét:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, 'Ímé eljő az idő, a mikor mindaz, a mi a te házadban van, és a mit eltettek a te atyáid e mai napig, elvitetik Babilóniába, és semmi sem marad meg, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, 'És a te fiaid közül is, a kik tőled származnak és születnek, elhurczoltatnak és udvariszolgák lesznek a babilóniai király udvarában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'Ezékiás pedig monda Ésaiásnak: Jó az Úr beszéde, a melyet szólál: És monda: Nem merő jóság-é, ha békesség és hűség lesz az én napjaimban?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'Ezékiásnak egyéb dolgai pedig és minden erőssége, és hogy miképen csinálta a tavat és a vízcsöveket, a melyekkel a vizet a városba vezette, vajjon nincsenek-é megírva a Júda királyainak krónika-könyvében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'És elaluvék Ezékiás az ő atyáival, és az ő fia, Manasse uralkodék helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'Manasse tizenkét esztendős volt, mikor uralkodni kezdett, és ötvenöt esztendeig uralkodott Jeruzsálemben, és az ő anyjának Hefsiba volt a neve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'És gonoszul cselekedék az Úr szemei előtt, a pogányok útálatossága szerint, a kiket az Úr kiűzött volt az Izráel fiai elől:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'Mert újra megépítette a magaslatokat, a melyeket Ezékiás, az ő atyja lerontott, és oltárokat emelt a Baálnak, és állított Aserát, mint a hogy Akháb, az Izráel királya cselekedett volt, és imádta az összes mennyei seregeket és azoknak szolgált.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'És oltárokat is épített az Úr házában, a mely felől azt mondotta volt az Úr: Jeruzsálemben helyheztetem az én nevemet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'Oltárokat épített az egész mennyei seregnek, az Úr házának mind a két pitvarában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'És átvivé a fiát a tűzön, és igézést és jegymagyarázást űzött és ördöngösöket és titokfejtőket tartott; sok gonosz dolgot cselekedék az Úr szemei előtt, hogy őt haragra ingerelje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'És az Asera-bálványt, a melyet készített, bevitte abba a házba, a mely felől azt mondotta volt az Úr Dávidnak és az ő fiának, Salamonnak: Ebben a házban és Jeruzsálemben, a melyet magamnak választottam Izráelnek minden nemzetségei közül, helyheztetem az én nevemet mindörökké;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'És ki nem mozdítom többé Izráel lábát erről a földről, a melyet adtam az ő eleiknek, ha szorgalmatosan az én parancsolatim szerint cselekesznek, és az egész törvény szerint, a melyet nékik Mózes, az én szolgám parancsolt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Ők azonban nem engedelmeskedtek, mert tévelygésbe ejté őket Manasse, hogy még gonoszabbul viseljék magokat azoknál a pogányoknál, a kiket az Úr kivesztett az Izráel fiai elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'Akkor szóla az Úr az ő szolgái, a próféták által, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, 'Mivelhogy Manasse, Júda királya ezeket az útálatosságokat cselekedte, gonoszabb dolgokat cselekedvén mindazoknál, a melyeket az ő előtte való Emoreusok cselekedtek vala, és Júdát is vétekbe ejtette az ő bálványai által:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'Azért ezt mondja az Úr, Izráel Istene: Íme, én oly veszedelmet hozok Jeruzsálemre és Júdára, hogy mindenkinek, a ki azt hallja, megcsendül bele mind a két füle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'És kiterjesztem Jeruzsálemre a Samaria mérő-zsinórját és az Akháb házának mértékét; és kitörlöm Jeruzsálemet, mint kitörlik a tálat, és kitörölve leborítják azt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'És elhagyom az én örökségem maradékát, és adom őt ellenségei kezébe, és zsákmánya és ragadománya lesz minden ellenségeinek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'Azért, mert gonoszul cselekedtek én előttem, és engem haragra ingerlettek az ő atyáiknak Égyiptomból való kijövetelök napjától fogva, mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'És Manasse nagyon sok ártatlan vért is ontott ki, úgy hogy Jeruzsálem minden felől megtelt vele, azon a vétkén kivül, a melylyel vétekbe ejtette Júdát, gonoszul cselekedvén az Úr szemei előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'Manassénak egyéb dolgai pedig és minden cselekedetei és az ő vétke, a melyet cselekedett, vajjon nincsenek-é megírva a Júda királyainak krónika-könyvében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'És elaluvék Manasse az ő atyáival, és eltemetteték az ő háza mellett lévő kertben, az Uzza kertjében, és az ő fia, Amon uralkodék helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'Amon huszonkét esztendős volt, mikor uralkodni kezdett, és két esztendeig uralkodott Jeruzsálemben; az ő anyjának neve Mésullémet volt, a Jótbabeli Hárus leánya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'És gonoszul cselekedék az Úr szemei előtt, a mint cselekedett Manasse, az ő atyja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'És tökéletesen azon az úton járt, a melyen járt volt az ő atyja, és szolgált a bálványoknak, a kiknek szolgált volt atyja, és azokat imádta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'És elhagyta az Urat, atyái Istenét, és nem járt az Úrnak útában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'És pártot ütöttek Amon ellen a maga szolgái, és megölték a királyt az ő házában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'De a föld népe levágta mindazokat, a kik pártot ütöttek volt Amon király ellen, és a föld népe királylyá tevé az ő fiát, Jósiást, helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'Amonnak egyéb dolgai pedig, a melyeket cselekedett, vajjon nincsenek-é megírva a Júda királyainak krónika-könyvében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'És eltemeték őt az ő sírjába, Uzza kertjében, és fia, Jósiás lett a király ő helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'Nyolcz esztendős volt Jósiás, mikor uralkodni kezdett, és harminczegy esztendeig uralkodott Jeruzsálemben; az ő anyjának neve Jédida, a Boskátból való Adaja leánya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'És kedves dolgot cselekedék az Úr szemei előtt, és járt az ő atyjának, Dávidnak minden útaiban, és nem tért el sem jobbra, sem balra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'És történt Jósiás király tizennyolczadik esztendejében, elküldte a király Sáfánt, Asaliának, a Messullám fiának fiát, az íródeákot, az Úr házához, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, 'Menj fel Hilkiához, a főpaphoz, és számlálják meg az Úr házába begyült pénzt, a melyet gyűjtöttek az ajtóőrizők a néptől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'És adják azt az Úr házában való mívesek pallérainak kezébe, hogy adják a munkásoknak, a kik az Úrnak házán dolgoznak, hogy a háznak romlásait kijavítsák;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'Az ácsoknak, az építőknek és a kőmíveseknek, hogy fákat és faragott köveket vásároljanak a ház kijavítására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'De számadást nem kell tőlök venni a pénzről, a mely kezökbe adatik, mert ők azt becsülettel végzik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'És monda Hilkia, a főpap, Sáfánnak, az íródeáknak: Megtaláltam a törvénykönyvet az Úr házában. És Hilkia oda adta a könyvet Sáfánnak, hogy olvassa el azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'És elméne Sáfán, az íródeák, a királyhoz, és megvivé a királynak a választ, és monda: A te szolgáid egybeszedék a pénzt, a mely a házban találtatott, és oda adták azt az Úr házában munkálkodók pallérainak kezébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'És megmondá Sáfán, az íródeák, a királynak, mondván: Egy könyvet adott nékem Hilkia pap. És felolvasá azt Sáfán a király előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'Mikor pedig hallotta a király a törvény könyvének beszédit, megszaggatá az ő ruháit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'És megparancsolta a király Hilkia papnak és Ahikámnak, a Sáfán fiának, és Akbórnak, a Mikája fiának, és Sáfánnak, az íródeáknak, és Asájának, a király szolgájának, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, 'Menjetek el, kérdezzétek meg az Urat én érettem és a népért és az egész Júdáért, e könyvnek beszédei felől, a mely megtaláltatott; mert nagy az Úr haragja, mely felgerjedett ellenünk, mivel a mi atyáink nem engedelmeskedtek e könyv beszédeinek, hogy cselekedtek volna mindent úgy, a mint megíratott nékünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'És elméne Hilkia pap és Ahikám, Akbór, Sáfán és Asája Hulda próféta asszonyhoz, Sallumnak, a Tikva fiának – a ki Harhásnak, a ruhák őrizőjének fia volt – feleségéhez, a ki Jeruzsálem más részében lakott, és beszéltek vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'És monda nékik: Azt mondja az Úr, Izráel Istene: Mondjátok meg a férfiúnak, a ki titeket hozzám küldött;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, 'Ezt mondja az Úr: Ímé én veszedelmet hozok e helyre és e helyen lakozókra, a könyv minden beszédei szerint, a melyet olvasott a Júda királya;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'Mert elhagytak engem, és idegen isteneknek áldoztak jóillattal, hogy engem haragra indítsanak az ő kezöknek minden csinálmányával: azért felgerjed az én haragom e hely ellen, és meg sem oltatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'A Júda királyának pedig, a ki elküldött titeket, hogy megkérdezzétek az Urat, ezt mondjátok: Azt mondja az Úr, Izráel Istene: Mivelhogy e beszédekre, a melyeket hallottál,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'Meglágyult a te szíved, és magadat megaláztad az Úr előtt, hallván azokat, a miket e hely és az ezen helyen lakók ellen szólottam, hogy pusztulássá és átokká lesznek, és megszaggattad a te ruháidat, és sírtál előttem; azért én is meghallgattalak, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, 'Azért ímé én téged a te atyáidhoz gyűjtelek, és a te sírodba békességgel visznek téged, és meg nem látják a te szemeid azt a nagy veszedelmet, a melyet én e helyre hozok. És megvitték a királynak a választ.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'És elküldött a király, és hozzá gyűltek Júdának és Jeruzsálemnek minden vénei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'És felment a király az Úr házába, és Júdából minden férfi és Jeruzsálem minden lakosa vele volt; a papok, a próféták és az egész nép kicsinytől fogva nagyig. És minden beszédét elolvasá előttök a szövetség könyvének, a mely megtaláltatott az Úr házában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'És oda állott a király az emelvényre, és kötést tőn az Úr előtt, hogy ők az Urat akarják követni, és az ő parancsolatait, bizonyságtételeit és rendeléseit teljes szívből és lélekből megőrizni, és beteljesíteni e szövetség beszédeit, a melyek meg vannak írva abban a könyvben; és ráállott az egész nép a kötésre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'És megparancsolá a király Hilkiának, a főpapnak és a másod rendbeli papoknak és az ajtóőrizőknek, hogy az Úr templomából hordjanak ki minden edényt, a melyet a Baálnak, az Aserának és az egész mennyei seregnek csináltak, és megégeté azokat Jeruzsálemen kivül a Kidron völgyében, és azok hamvait Béthelbe vivé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'És kiirtá a bálvány papokat is, a kiket Júda királyai állítottak be, hogy a magaslatokon tömjénezzenek Júda városaiban és Jeruzsálem körül, és mindazokat is, a kik a Baálnak, a napnak, holdnak, égi jeleknek és az egész mennyei seregnek tömjéneztek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'Kivivé az Úr házából az Aserát is Jeruzsálemen kivül a Kidron patakja mellé, és megégeté azt a Kidron völgyében, és porrá zúzta, és annak porát a község temetőhelyére hinté.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'És lerontá a férfi paráznák házait, a melyek az Úr háza mellett voltak, és a melyekben az asszonyok kárpitokat szőttek az Aserának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'És behozatta az összes papokat Júda városaiból, és megfertéztette a magaslatokat, a melyeken a papok tömjéneztek, Gebától egész Beersebáig, és lerontotta a kapuk mellett levő magaslatokat is, a melyek Józsuénak, a város fejedelmének kapuja előtt voltak balkéz felől, a város kapujában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'De a magaslatok papjai soha sem áldoztak az Úr oltárán Jeruzsálemben, hanem a kovásztalan kenyeret az ő atyjokfiai között ették.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'Megfertőztette a Tófetet, a Hinnom fiainak völgyében, hogy senki az ő fiát, vagy leányát át ne vihesse a tűzön Moloknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'És eltávolította a lovakat, a melyeket Júda királyai a napnak szenteltek az Úr házának bemenetelénél, a Nátán-Mélek udvari szolga háza mellett, a mely a Pharvarimban volt, és a nap szekereit tűzzel elégette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'És az oltárokat, a melyek az Akház palotájának tetején voltak, a melyeket a Júda királyai csináltak, és azokat az oltárokat is, a melyeket Manasse csinált volt az Úr házának mindkét pitvarában, lerontotta a király, és lehányván, porukat a Kidron patakjába szóratta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'Azokat a magaslatokat is megfertőztette a király, a melyek Jeruzsálem előtt voltak az Olajfák hegyének jobbfelől levő oldalán, a melyeket még Salamon, az Izráel királya épített volt Astóretnek, a Sídonbeliek útálatosságának, és Kámósnak, a Moábiták útálatosságának, és Milkómnak, az Ammon fiai útálatosságának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'És összetörte az oszlopokat és kivágatta az Aserákat, és azok helyeit embercsontokkal töltötte meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'Még azt az oltárt is, a mely Béthelben volt, a magaslatot, a melyet Jeroboám, a Nébát fia csinált, a ki vétekbe ejté az Izráelt, – azt az oltárt is és azt a magaslatot is letörte, és a magaslatot felégette, porrá tette, és az Aserát megégette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'És körültekintett Jósiás, és meglátta a sírokat, a melyek ott a hegyen voltak, és elküldött és elhozatta a csontokat a sírokból, és megégette az oltáron, és megfertőztette azt az Úr beszéde szerint, a melyet mondott volt az Isten embere, a ki e dolgot megjövendölte volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'És monda: Miféle síremlék ez, a melyet látok? És felelének néki a város férfiai: Az Isten emberének sírja ez, a ki Júdából jött volt és mindezeket megjövendölte a Béthelbeli oltár felől, a miket most cselekedtél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'És monda: Hagyjatok békét néki, és senki meg ne mozdítsa az ő tetemeit. És megmentették az ő tetemeit annak a prófétának a tetemeivel együtt, a ki Samariából jött volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'És lerontotta Jósiás a magaslatok minden házát is, a melyek Samária városaiban voltak, a melyeket az Izráel királyai csináltak volt, hogy az Urat haragra ingereljék, és épen úgy cselekedett azokkal mindenekben, a mint Béthelben cselekedett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'És megáldozta a magaslatok összes papjait, a kik ott voltak, az oltárokon, és emberi csontokat égetett meg azokon, és úgy tért vissza Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'És parancsolt a király az egész népnek, és monda: Ünnepeljetek páskhát az Úrnak, a ti Istenteknek, a mint meg van írva e szövetség könyvében;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Mert nem szereztetett olyan páskha a birák idejétől fogva, a kik az Izráelt ítélték, sem pedig az Izráel és a Júda királyainak minden idejében,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'Hanem csak Jósiás király tizennyolczadik esztendejében szereztetett ilyen páskha az Úrnak Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'És kivesztette Jósiás király az ördöngösöket és a titokfejtőket, a teráfokat és a bálványokat, és mindazokat az útálatosságokat, a melyek láttattak Júda földjén és Jeruzsálemben, hogy helyreállítsa a törvény beszédit, a melyek meg valának írva a könyvben, a melyet Hilkia pap talált meg az Úr házában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'Nem is volt ő hozzá hasonló király ő előtte, a ki úgy megtért volna az Úrhoz teljes szívéből és teljes lelkéből és teljes erejéből, Mózesnek minden törvénye szerint; de utána sem támadott hozzá hasonló.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'De az Úr még sem szünt meg az ő megbúsult nagy haragjától, a melylyel megharagudott volt Júdára mindazokért a bosszantásokért, a melyekkel bosszantotta őt Manasse.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'Mert azt mondá az Úr: Júdát is elvetem szemem elől, mint a hogy az Izráelt elvetettem, és megútálom ezt a várost, a melyet választottam, Jeruzsálemet, és ezt a házat is, a melyről azt mondottam volt: Ott legyen az én nevem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'Jósiásnak egyéb dolgai pedig és minden cselekedetei, vajjon nincsenek-é megírva a Júda királyainak krónika-könyvében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'Az ő idejében jött fel Faraó-Nékó, az égyiptomi király Assiria királya ellen az Eufrátes folyóvize mellé. És Jósiás király eleibe ment, de az megölte őt Megiddóban, a mint meglátta őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'És az ő szolgái szekérre tévén őt, halva vitték el Megiddóból és Jeruzsálembe hozván, eltemeték őt az ő sírboltjába. A föld népe pedig vevé Joákházt, a Jósiás fiát, és felkenvén őt, királylyá tevé az ő atyja helyett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'Huszonhárom esztendős volt Joákház, mikor uralkodni kezdett, és három hónapig uralkodott Jeruzsálemben, és az ő anyjának neve Hamutál, a Libnabeli Jeremiás leánya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'És gonoszul cselekedék az Úr szemei előtt mind a szerint, a mint az ő atyái cselekedtek volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'De Faraó-Nékó bilincsekbe verte őt Riblában, Hámát földjén, a mikor Jeruzsálemben királylyá lett; és az országra adót vetett, száz tálentom ezüstöt és egy tálentom aranyat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'És Faraó-Nékó Eliákimot, a Jósiás fiát tette királylyá, az ő atyja, Jósiás helyett, és nevét Joákimra változtatta; Joákházt pedig magával vivé, és az Égyiptomba megérkezvén, ott hala meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'Az ezüstöt és az aranyat megadta ugyan Joákim a Faraónak, de az országot sarczoltatta meg, hogy megadhassa az ezüstöt a Faraó parancsolata szerint; a föld népe közül mindenkitől az ő értéke szerint hajtott be ezüstöt és aranyat, hogy Faraó-Nékónak adja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'Joákim huszonöt esztendős volt, mikor uralkodni kezdett, és tizenegy esztendeig uralkodott Jeruzsálemben; az ő anyjának neve Zébuda, a Rúmabeli Pedája leánya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'És gonoszul cselekedék az Úr szemei előtt mind a szerint, a mint az ő atyái cselekedtek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'Joákim idejében jött fel Nabukodonozor, Babilónia királya, és Joákim szolgája lett három esztendeig; de azután elfordult és elpártolt tőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'És ráküldé az Úr a Káldeusok seregeit, a Siriabeliek seregeit, a Moábiták seregeit és az Ammon fiainak seregeit, és ráküldte őket Júdára, hogy elveszessék őt az Úr beszéde szerint, a melyet szólott szolgái, a próféták által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'Csak az Úr beszéde szerint történt ez Júdán, hogy elvesse őt a maga orczája elől Manasse bűneiért, mind a szerint, a mint cselekedett vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'És az ártatlan vérért is, a melyet kiontott, és hogy betöltötte volt Jeruzsálemet ártatlan vérrel; ezért nem akart az Úr megbocsátani néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'Joákimnak egyéb dolgai pedig és minden cselekedetei, vajjon nincsenek-é megírva a Júda királyainak krónika-könyvében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'És elaluvék Joákim az ő atyáival, és az ő fia, Joákin uralkodék helyette,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'És Égyiptom királya többé nem jött ki az ő földéből; mert Babilónia királya mindent elvett, a mi csak az égyiptomi királyé volt, Égyiptom folyóvizétől az Eufrátes folyóvizéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'Tizennyolcz esztendős volt Joákin, mikor királylyá lett, és három hónapig uralkodott Jeruzsálemben. Az ő anyjának neve Nékhusta, a Jeruzsálembeli Elnatán leánya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'És gonoszul cselekedék az Úr szemei előtt mind a szerint, a mint az ő atyja cselekedett volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'Ebben az időben jöttek fel Nabukodonozornak, Babilónia királyának szolgái Jeruzsálem ellen, és szállották meg a várost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'Maga Nabukodonozor, Babilónia királya is feljött a város ellen, a melyet már az ő szolgái megszállottak volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'És kiment Joákin, a Júda királya Babilónia királyához az ő anyjával, szolgáival, hadnagyaival és udvariszolgáival együtt, de fogságra vetette őt Babilónia királya az ő uralkodásának nyolczadik esztendejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'És elvitte onnét az Úr házának minden kincsét és a király házának kincsét, és összevagdalt minden arany edényt, a melyet Salamon, az Izráel királya csináltatott volt az Úr templomában, a mint az Úr megmondotta volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'És elhurczolta az egész Jeruzsálemet, összes fejedelmeit és minden vitézeit, tízezer foglyot, az összes mesterembereket és lakatosokat, úgy hogy a föld szegény népén kivül senki sem maradt ott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'És elhurczolta Joákint is Babilóniába, és a király anyját, és a király feleségeit és udvariszolgáit, és az ország erős vitézeit fogságba hurczolta Jeruzsálemből Babilóniába;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'És az összes előkelő férfiakat, hétezeret, és a mesterembereket és a lakatosokat, ezeret, és az összes erős, harczra termett férfiakat fogva vitte Babilóniába Babilónia királya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'És Babilónia királya Mattaniát, nagybátyját, tette ő helyette királylyá, és nevét Sédékiásra változtatta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'Huszonegy esztendős volt Sédékiás, mikor uralkodni kezdett, és tizenegy esztendeig uralkodott Jeruzsálemben; az ő anyjának neve Hamutál, a Libnából való Jeremiás leánya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'És gonoszul cselekedék az Úr szemei előtt mind a szerint, a mint Joákim cselekedett volt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'Mert az Úr haragja miatt történt ez így Jeruzsálemmel és Júdával, míg csak el nem vetette őket az ő orczája elől. Sédékiás azonban elpártolt Babilónia királyától.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'És történt az ő uralkodásának kilenczedik esztendejében, a tizedik hónapban, és annak tizedik napján, hogy feljött Nabukodonozor, Babilónia királya minden ő seregével Jeruzsálem ellen, és táborba szállott ellene, és köröskörül ostromtornyokat építettek ellene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'És megszállva tartatott a város Sédékiás király tizenegyedik esztendejéig;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'De a negyedik hónap kilenczedik napján akkora inség lett a városban, hogy nem volt mit enni a föld népének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'És betöretett a város, és a harczosok mind futni kezdtek éjjel a kettős kőfal között levő kapu útján, a mely a király kertje mellett van; a Káldeusok pedig ott táboroztak a város körül. És a király is elfutott a puszta útján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'De a Káldeusok hada űzőbe vette a királyt, és utólérték őt Jerikhó mezején, és egész serege szétszóródott mellőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'És elfogták a királyt, és elvitték őt Babilónia királyához Riblába, a hol ítéletet tartottak fölötte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'És Sédékiás fiait saját szeme láttára vágták le; Sédékiás szemeit pedig megvakították, és lánczokba verve vitték el őt Babilóniába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'És az ötödik hónap hetedik napján – ez a Nabukodonozor, babilóniai király uralkodásának tizenkilenczedik esztendeje – feljött Nabuzár-Adán, a vitézek hadnagya, Babilónia királyának szolgája Jeruzsálembe;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'És felgyújtotta az Úr házát és a király házát, és Jeruzsálem összes házait és mind a nagy palotákat felégette tűzzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'És Jeruzsálem kőfalait köröskörül lerombolta a Káldeusok serege, a mely a vitézek hadnagyával volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'A többi népet pedig, a mely a városban még megmaradt volt, és azokat, a kik Babilónia királyához hajlottak, és a többi népet mind elhurczolta Nabuzár-Adán, a vitézek hadnagya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'A föld népének csak a szegényéből hagyott ott a vitézek hadnagya szőlőmíveseket és szántó-vető embereket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'És a rézoszlopokat, a melyek az Úr házában voltak, és a mosdómedenczék talpait és a réztengert, a mely az Úr házában volt, összetörték a Káldeusok, és azok rezét Babilóniába vitték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'Elvitték a fazekakat is, a lapátokat, a késeket, temjénezőket, és minden, szolgálatra rendelt, egyéb rézedényeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'És elvitte a vitézek hadnagya a serpenyőket, a medenczéket, a melyek közül némelyek aranyból, némelyek pedig ezüstből voltak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'A két rézoszlopot, a réztengert és a mosdómedenczék talpait, a melyeket Salamon csinált volt az Úr házában; megmérhetetlen volt mindezeknek az edényeknek a reze.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'Az egyik oszlop magassága tizennyolcz sing volt, és egy rézgömb volt rajta és a gömb három sing magas volt, a gömbön köröskörül hálózat és gránátalmák mind érczből, és ugyanilyen volt a másik oszlop is a hálózattal együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'És elhurczolta a vitézek hadnagya Serája papot is, az első rendből és Sofóniás papot, a második rendből és a három ajtónállót,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'És a városból elvitt egy főembert, ki a hadakozó férfiak előljáró hadnagya volt, és öt férfiút, a kik a király körül forgolódtak volt, a kik találtattak a városban, és a sereg hadnagyának íródeákját, a ki sereget gyűjt vala a föld népe közül, és hatvan férfiakat a föld népe közül, a kik ott találtattak a városban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'És vevé őket Nabuzár-Adán, a vitézek hadnagya, és elvitte Babilónia királyához Riblába,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'És levágta őket Babilónia királya, és megölte Riblában a Hámát földjén. És így viteték el Júda az ő földjéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'A Júda földjén megmaradt népnek pedig, a melyet meghagyott Nabukodonozor, Babilónia királya, Gedáliát, Ahikámnak, a Sáfán fiának fiát, rendelte tiszttartóul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'Mikor pedig meghallották a seregek hadnagyai mind, és az ő embereik, hogy Babilónia királya Gedáliát tette tiszttartóvá, elmentek Gedáliához Mispába, Izmáel, a Nétánia fia, és Johanán, a Kareáh fia, és Serája, a nétofáti Tánhumet fia, és Jahazánia, Maakáti fia, ők és az ő embereik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'És megesküdött nékik Gedália és az ő embereiknek, és monda nékik: Ne féljetek a Káldeusoknak való szolgálattól. Maradjatok az országban, és szolgáljatok Babilónia királyának, és jó dolgotok lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'A hetedik hónapban azonban elment Izmáel, Nétániának, az Elisáma fiának fia, a ki királyi magból volt, és vele tíz férfiú, és megölték Gedáliát és meghalt; és a Zsidókat és a Káldeusokat, a kik ő vele voltak Mispában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'És felkelt az egész nép kicsinytől nagyig és a seregek hadnagyai, és elmentek Égyiptomba; mert féltek a Káldeusoktól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'És lőn a harminczhetedik esztendőben, Joákinnak, a Júda királyának fogságba hurczoltatása után, a tizenkettedik hónap huszonhetedik napján, kivette Evil-Merodák, Babilónia királya, az ő uralkodásának első esztendejében Joákint, Júda királyát a fogházból;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'És kegyesen beszélt vele, és feljebb tette az ő székét a többi királyok székeinél, a kik nála voltak Babilóniában;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'És kicserélte fogsága ruháit, és mindenkor nála volt étele életének minden idejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'És mindenkor kijárt az ő része, a melyet a király adott néki napról-napra életének minden idejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Ádám, Séth, Énós.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Kénán, Mahalálél, Járed.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Énókh, Methuséláh, Lámekh.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Noé, Sém, Khám és Jáfet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'Jáfetnek fiai: Gómer, Mágog, Madai, Jáván, Thubál, Mésekh és Thirász.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'A Gómer fiai pedig: Askhenáz, Rifáth és Tógármah.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'Jávánnak pedig fiai: Elisah, Thársis, Kitthim és Dodánim.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'Khámnak fiai: Khús, Miczráim, Pút és Kanaán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'Khúsnak fiai: Széba, Hávilah, Szábthah, Rahmáh és Szabthékah; Rahmáhnak pedig fiai: Séba és Dédán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'Khús nemzé Nimródot is; ez kezde hatalmassá lenni a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'Miczráim pedig nemzé Lúdimot, Anámimot, Lehábimot és Naftukhimot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'Pathruszimot és Kaszlukhimot, a kiktől a Filiszteusok származtak, és Kafthorimot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'Kanaán pedig nemzé Czídont, az ő elsőszülöttét és Khétet,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'És Jebuzeust, Emorreust és Girgazeust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'Khivveust, Harkeust és Szineust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'Arvadeust, Czemareust és Hamatheust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'Sémnek fiai: Élám és Assur, Arpaksád, Lúd, Arám, Úcz, Húl, Gether és Mesek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'Arpaksád pedig nemzé Séláht és Séláh nemzé Hébert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'Hébernek is lett két fia, az egyiknek neve Péleg, mivelhogy az ő idejében osztatott el a föld; testvérének neve pedig Joktán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'Joktán pedig nemzé Almodádot és Sélefet, Haczarmávethet és Jerákhot,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'Hadórámot, Úzált és Diklát,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'És Ebált, Abimáelt és Sébát,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'Ofirt, Havilát és Jóbábot. Ezek mind Joktán fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Sém, Arpaksád, Séláh.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Héber, Péleg, Réu.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Sérug, Nákhor, Tháré.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'Abrám, ez az Ábrahám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'Ábrahám fiai: Izsák és Ismáel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'Ezeknek nemzetségei pedig ezek: Ismáel elsőszülötte Nebájót és Kédar, Adbeél és Mibszám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'Misma és Dúmah, Massza, Hadad és Théma.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Jétur, Náfis és Kedmah; ezek az Ismáel fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'Keturának pedig, az Ábrahám ágyasának fiai, kiket szüle, ezek: Zimrán, Joksán, Médán, Midián, Isbák és Suakh. És a Joksán fiai: Séba és Dédán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'És a Midián fiai: Éfah, Héfer, Hánok, Abida és Eldáh. Mindezek a Keturáh fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'Ábrahám pedig nemzé Izsákot; Izsák fiai pedig ezek: Ézsau és Izráel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'Ézsaunak fiai: Elifáz, Réhuél, Jéhus, Jahlám és Korakh.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'Elifáz fiai: Thémán, Omár, Czefi, Gahtám, Kenáz és Timna és Amálek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'Réhuél fiai: Nakhath, Zérakh, Samma és Mizza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'Széir fiai: Lótán és Sóbál, Czibhón, Haná, Disón, Eczer és Disán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'Lótán fiai pedig: Hóri és Hómám: Lótánnak huga pedig Timna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'Sóbál fiai: Alján és Mánakháth, Hébál, Sefi és Onám; Czibhón fiai pedig: Aja és Haná.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, 'Haná fia: Disón, Disón fiai pedig: Hamrán és Esbán, Ithrán és Kherán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'Eczer fiai: Bilhán és Zahaván, Jakán. Disán fiai: Húcz és Arán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'Ezek pedig a királyok, a kik uralkodának Edom földén, mielőtt az Izráel fiai között király uralkodott volna: Bela, Behor fia, az ő városának neve Dinhába vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'Bela meghalván, uralkodék helyette Jóbáb, a Boczrából való Zerakh fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'És hogy Jóbáb meghala, uralkodék helyette a Témán földéből való Khusám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'Meghala Khusám is, és uralkodék helyette Hadád, a Bédád fia, ki megveré a Midiánitákat a Moáb mezején; és az ő városának neve Hávit vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'Hadád is, hogy meghala, uralkodék helyette a Masrekából való Szamlá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'Szamlá holta után uralkodék helyette Saul, a folyóvíz mellett való Rékhobóthból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'Saul is meghala, és uralkodék helyette Báhál-Khanán, az Akhbór fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'Báhál-Khanán holta után uralkodék helyette Hadád; és az ő városának neve Páhi, feleségének pedig neve Mehetábéel, ki Mézaháb leányának Matrédnak volt a leánya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'Hadád halála után Edom fejedelmei valának: Timná fejedelem, Halvá fejedelem, Jetéth fejedelem,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'Ohólibámá fejedelem, Éla fejedelem és Pinon fejedelem,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'Kenáz fejedelem, Témán fejedelem és Mibczár fejedelem,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'Magdiél fejedelem és Hirám fejedelem. Ezek voltak Edom fejedelmei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'Ezek az Izráel fiai: Rúben, Simeon, Lévi, Júda, Issakhár és Zebulon;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Dán, József, Benjámin, Nafthali, Gád és Áser.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'Júdának fiai: Hér, Ónán és Séla; e három születék néki a Kanaánita Súahnak leányától. De Hér, Júdának elsőszülött fia gonosz vala az Úr szemei előtt, és megölé őt az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'Thámár pedig, az ő menye szülé néki Péreczet és Zerákhot. Júdának fiai mindnyájan öten valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'Pérecz fiai: Kheczrón és Khámul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'Zerákh fiai pedig: Zimri és Ethán, Hémán, Kálkól és Dára; mindenestől öten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'Kármi fiai: Ákán, Izráelnek megrontója, mivel lopott a zsákmányból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'Ethán fia: Azária.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'Kheczrón fiai, kik születtenek néki: Jérakhméel, Rám és Kélubai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'Rám nemzé Amminádábot, Amminádáb pedig nemzé Nakhsont, a Júda fiainak fejedelmét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'Nakhson nemzé Szálmát, Szálma pedig nemzé Boázt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'Boáz nemzé Obedet; Obed nemzé Isait;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'Isai pedig nemzé Eliábot, az ő elsőszülöttét, és Abinádábot, másodikat, Simeát, harmadikat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'Netanéelt, negyediket, és Raddait, ötödiket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'Osemet, hatodikat és Dávidot, a hetedik fiát;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'És nővéreiket, Séruját és Abigáilt. Sérujának pedig fiai voltak: Absai, Joáb és Asáel, e három.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'Abigáil szülé Amasát; Amasának atyja pedig az Ismáel nemzetségéből való Jéter vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'Káleb pedig, a Kheczrón fia nemzett vala az ő Azuba nevű feleségétől és Jérióttól; és ezek az ő fiai: Jéser, Sobáb és Ardon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'Azuba meghala, és Káleb vevé magának feleségül Efratát, és ez szülé néki Húrt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'Húr nemzé Urit, Uri pedig nemzé Bésaléelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'Azután beméne Kheczrón Mákirnak, Gileád atyjának leányához; mert ő ezt elvette vala hatvan esztendős korában, és szülé néki Ségubot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'Ségub pedig nemzé Jáirt, kinek huszonhárom városa vala a Gileád földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'De Gesur és Árám elvették tőlük Jáir falvait, Kenáthot és mezővárosait, hatvan várost. Mindezek Mákirnak, a Gileád atyjának fiaié.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'Minekutána pedig meghala Kheczrón Káleb-Efratában, akkor szülé néki Abija, a Kheczrón felesége, Ashúrt, Tékoa atyját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'Jérakhméelnek, a Kheczrón elsőszülöttének fiai voltak: Rám, az elsőszülött, Búna, Orem, Osem és Akhija.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'Volt más felesége is Jérakhméelnek, Atára nevű; ez az Onám anyja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'Rámnak, Jérakhméel elsőszülöttének pedig fiai voltak: Maás, Jámin és Héker.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'Onám fiai voltak: Sammai és Jáda; és Sammai fiai: Nádáb és Abisúr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'Abisúr feleségének neve Abihail, a ki szülé néki Akhbánt és Mólidot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'Nádáb fiai: Széled és Appaim: Széled magtalanul halt meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'Appaim fia: Isi; Isi fia: Sésán; Sésán fia: Ahálai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'Jáda fiai, a ki Sammai testvére volt: Jéter és Jonathán; Jéter magtalanul halt meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'Jonathán fiai: Pélet és Záza. Ezek voltak a Jérakhméel fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'Sésánnak nem voltak fiai, hanem csak leányai; de volt Sésánnak egy Égyiptombeli szolgája, Járha nevű.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'És adá Sésán e Járha nevű szolgájának az ő leányát feleségül, a ki szülé néki Athait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'Athai pedig nemzé Nátánt; Nátán nemzé Zabádot;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'Zabád nemzé Eflált; Eflál nemzé Obedet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'Obed nemzé Jéhut; Jéhu nemzé Azáriát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'Azária nemzé Hélest; Héles nemzé Elását;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'Elása nemzé Sisémait; Sisémai nemzé Sallumot;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'Sallum nemzé Jékámiát; Jékámia pedig nemzé Elisámát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'A Káleb fiai pedig, a ki Jérakhméel testvére vala: elsőszülötte Mésa; ez volt Zifnek és Marésa fiainak atyjok, Hebronnak atyja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'Hebron fiai: Kórah, Tappuah, Rékem és Séma.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'Séma pedig nemzé Rahámot, a Jorkeám atyját; és Rékem nemzé Sammait,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'A Sammai fia pedig: Máon; ez a Máon volt a Bethsúr atyja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'Efa pedig, a Káleb ágyastársa, szülé Háránt és Mósát és Gázezt; és Hárán nemzé Gázezt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'Jaddai fiai pedig: Régem, Jotám, Gésán, Pelet, Héfa és Saáf.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'A Káleb ágyasa Maaka szülé Sébert és Tirhánát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'És szülé Saáfot, Madmanna atyját, Sevát, a Makbéna atyját és Gibea atyját; és Aksza a Káleb leánya vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'Ezek voltak Káleb fiai, a ki Húrnak, az Efrata elsőszülöttének fia volt: Sobál, Kirját-Jeárim atyja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Szálma, Bethlehem atyja; Háref, Bethgáder atyja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'Voltak pedig Sobálnak is, a Kirját-Jeárim atyjának fiai: Haroé, a fél Menuhót ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'A Kirját-Jeárim háznépei: Jitreusok, Puteusok, Sumateusok, Misraiteusok; ezektől származának a Sorateusok és az Estaoliteusok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'Szálma fiai, Bethlehem és a Netofátbeliek, Atróth, Beth-Joáb, a Czórabeli Manahateusok fele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'És a Jábesben lakozó tudós emberek háznépei: a Tirateusok, Simateusok, Sukateusok. Ezek a Kineusok, a kik Hámáttól, a Rékáb házának atyjától származtak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'Ezek a Dávid fiai, a kik Hebronban születének néki: elsőszülötte vala Amnon, a Jezréelből való Ahinoámtól; második vala Dániel, a Kármelből való Abigailtól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'Harmadik Absolon, a ki Maakának, a Gessurbeli Talmai király leányának volt a fia; negyedik Adónia, Haggittól való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'Ötödik Sefátia, Abitáltól való; hatodik Jitreám, az ő feleségétől, Eglától való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'E hat fia születék néki Hebronban, a hol hét esztendeig és hat hónapig uralkodott; Jeruzsálemben pedig harminczhárom esztendeig uralkodék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'Jeruzsálemben pedig ezek születének néki: Simea, Sóbáb, Nátán és Salamon, négyen, Bathsuától, az Ammiel leányától.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'És Ibhár, Elisáma és Elifélet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'Nógah, Néfeg és Jáfia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'És Elisáma, Eljada és Elifélet, kilenczen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'Mindezek a Dávid fiai, az ő ágyastársainak fiain kivül; és ezeknek a huga, Támár.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'Salamonnak pedig fia volt Roboám; ennek fia Abija, ennek fia Asa, ennek fia Josafát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'Ennek fia Jórám, ennek fia Akházia, ennek fia Joás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'Ennek fia Amásia, ennek fia Azária; ennek fia Jótám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'Ennek fia Akház, ennek fia Ezékiás, ennek fia Manasse.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'Ennek fia Amon, ennek fia Jósiás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'Jósiásnak pedig fiai: elsőszülötte Johanán, második Jójákim, harmadik Sédékiás, Sallum negyedik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'Jójákim fiai: az ő fia Jékoniás, ennek fia Sédékiás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'Jékóniásnak fiai: Assir, ennek fia Saálthiel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'És Málkirám, Pedája, Sénasár, Jékámia, Hosáma és Nédábia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'Pedája fiai: Zerubábel és Simei. Zerubábel fiai: Mesullám, Hanánia; és az ő hugok vala Selómit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'És Hásuba, Ohel, Berekia, Hasádia és Jusáb-Hésed, ezek öten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'Hanánia fiai: Pelátia és Jésaia; és Refája fiai és Arnám fiai, Obádia fiai, Sekánia fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'És Sekánia fiai: Semája. Semája fiai: Hattus, Jigeál, Báriah, Neárja és Sáfát, ezek hatan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'Neárja fiai: Eljohénai, Ezékiás és Azrikám, ezek hárman.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'Eljohénai fiai: Hódajéva, Eliásib, Pelája, Akkub, Johanán, Delája és Anáni; ezek heten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'Júda fiai ezek: Pérecz, Kheczrón, Kármi, Húr és Sobál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'Reája pedig, a Sobál fia nemzé Jáhátot; Jáhát nemzé Ahumáit és Lahádot; ezek a Sorateusok háznépei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'Ezek Etám atyjától valók: Jezréel, Jisma, Jidbás; és az ő hugoknak neve Haslelponi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'Pénuel pedig Gedor atyja, és Ezer Húsa atyja. Ezek Efrata elsőszülöttének, Húrnak fiai, a ki Bethlehem atyja vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'Ashúrnak pedig, a Tékoa atyjának volt két felesége, Heléa és Naára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'És Naára szülé néki Ahuzámot, Héfert, Teménit és Ahastárit. Ezek a Naára fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'Heléa fiai: Séret, Jésohár, Etnán és Kócz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'Kócz pedig nemzé Hánubot, Hásobébát és Ahárhel háznépét, a ki Hárumnak fia vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'Jábes pedig testvéreinél tiszteletreméltóbb vala, és azért nevezé őt az ő anyja Jábesnek, mondván: Mivelhogy fájdalommal szülém őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'És Jábes az Izráel Istenét hívá segítségül, mondván: Ha engem megáldanál és az én határomat megszélesítenéd, és a te kezed én velem lenne, és engem minden veszedelemtől megoltalmaznál, hogy bút ne lássak! És megadá Isten néki, a mit kért vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'Kélub pedig, a Súkha testvére, nemzé Méhirt; ez az Eston atyja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'Eston nemzé Béth-Rafát, Paseákhot, Tehinnát, Ir-Náhás atyját. Ezek a Rékától való férfiak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'Kénáz fiai: Othniel és Serája; Othniel fia: Hatát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'Meonótai nemzé Ofrát; Serája pedig nemzé Joábot, a Gé-Harasimbeliek atyját, mert mesteremberek valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'Káleb fiai, ki Jefunné fia vala: Iru, Ela és Naám; és Ela fiai; és Kénáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'Jéhalélel fiai: Zif, Zifa, Tirja és Asárel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'Ezra fiai: Jéter, Méred, Efer és Jálon; és szülé Mirjámot, Sammait és Isbát, Estemóa atyját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'Ennek felesége pedig, Jehudéja szülé Jéredet, a Gedor atyját és Hébert, a Szókó atyját, Jékuthielt, a Zánoah atyját; ezek Bithiának, a Faraó leányának fiai, a kit Méred elvett vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'Hódia nevű feleségének pedig fiai, ki Nahamnak, Keila atyjának nővére vala: Hagármi és a Maakátbeli Estemóa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'Simon fiai: Amnon, Rinna, Benhanán és Thilon. Isi fiai: Zohét és Benzohét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'Júda fiának, Sélának fiai: Er, Léka atyja, és Laáda, Marésa atyja, és a gyapotszövők háznépe Béth-Asbeában;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'És Jókim és Kozeba lakosai, és Joás és Saráf, a kik Moáb urai voltak, és Jásubi, Léhem. De ezek már régi dolgok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'Ezek voltak a fazekasok, és Netaimban és Gederában laktak. A királylyal laktak ott, az ő dolgáért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'Simeon fiai: Némuel, Jámin, Járib, Zérah, Saul;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'Kinek fia Sallum, kinek fia Mibsám, kinek fia Misma.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'Misma fiai: Hammúel az ő fia, Zakkur az ő fia, Simi az ő fia;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'Siminek tizenhat fia és hat leánya volt; de testvéreinek nem volt sok fia, s általában háznépök nem volt oly népes, mint Júda fiaié.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'Lakoznak vala pedig Beersebában és Móladában és Haczar-Suálban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'Bilhában, Eczemben és Toládban,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'Bétuelben, Hormában és Cziklágban,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'Beth-Markabótban, Haczar-Szuszimban, Beth-Biriben és Saáraimban; ezek valának az ő városaik mindaddig, míg Dávid királylyá lett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'Faluik pedig ezek: Etám, Ain, Rimmon, Tóken és Asán, öt város;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'És mindazok a falvaik, a melyek e városok körül voltak Bálig; ezek valának lakóhelyeik és nemzetségeik:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'Mesobáb, Jámlek és Jósa, Amásia fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'És Jóel és Jéhu, a Jósibia fia, ki Serája fia, ki Asiel fia vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'És Eljoénai, Jaákoba, Jésohája, Asája, Adiel, Jesiméel és Benája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'Ziza, a Sifi fia, ki Alon fia, ki Jedája fia, ki Simri fia, ki Semája fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'Ezek a névszerint felsoroltak voltak a főemberek nemzetségökben, a kik igen elszaporodtak volt atyjok házában,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'Azért elindulának Gedor felé, hogy a völgy keleti részére menjenek és ott barmaiknak legelőt keressenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'Találának is zsíros és jó legeltető helyet (az a föld pedig tágas, nyugodalmas és békességes), mert Khámból valók laktak ott azelőtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'Elmenvén pedig e névszerint megnevezettek Ezékiásnak, a Júda királyának idejében, lerombolták sátoraikat, és a Maonitákat, a kiket ott találtak, kiirtották mind e mai napig, s helyökbe letelepedének, mivel ott barmaik számára legelőhelyeket találtak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'És közülök, a Simeon fiai közül, némelyek elmenének a Seir hegyére, úgymint ötszázan, a kiknek előljáróik az Isi fiai, Pelátja, Nehárja, Refája és Uzriel voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'És valakik az Amálek nemzetségéből megmaradtak vala, mind levágák azokat, és ott letelepedének mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'Rúbennek, Izráel elsőszülöttének fiai (mert ő volt az elsőszülött; mikor pedig megfertőztette az ő atyjának ágyasházát, az ő elsőszülöttségi joga a József fiainak adaték, a ki Izráel fia vala, mindazáltal nem úgy hogy ők neveztessenek származás szerint elsőszülötteknek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'Mert Júda tekintélyesebb vala az ő testvérei között, és ő belőle való volt a fejedelem, hanem az elsőszülöttségnek haszna lőn Józsefé):');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'Ezek Rúbennek, Izráel elsőszülöttének fiai: Khánokh, Pallu, Kheczrón és Kármi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'Jóel fiai: Semája ennek fia, Góg ennek fia, Simei ennek fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'Mika ennek fia, Reája ennek fia, Baál ennek fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'Beéra ennek fia, a kit fogságba vitt Tiglát-Piléser, az Assiriabeli király; ő a Rúbeniták fejedelme vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'Testvérei pedig, családjaik, nemzetségük megszámlálása szerint ezek valának: a fő Jéhiel és Zakariás,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'Bela, Azáz fia, ki Séma fia, ki Jóel fia vala, ki Aróerben lakott Nébóig és Baál-Meonig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'Napkelet felé is lakik vala a pusztában való bemenetelig, az Eufrátes folyóvíztől fogva; mert az ő barmai Gileád földén igen elszaporodtak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'Saul királynak idejében pedig támasztának hadat a Hágárénusok ellen, és elhullának azok az ő kezeik által, és lakának azoknak sátoraikban, Gileádnak napkelet felé való egész részében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'A Gád fiai pedig velök szemben a Básán földén laktak Szalkáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'Jóel vala előljárójok, Sáfám második az után; Johánai és Sáfát Básánban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'És testvéreik, családjaik szerint ezek: Mikáel, Mésullám, Séba, Jórai, Jaékán, Zia és Éber, heten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, 'Ezek az Abihail fiai, ki Húri fia, ki Jároáh fia, ki Gileád fia, ki Mikáel fia, ki Jésisai fia, ki Jahadó fia, ki Búz fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'És Ahi, a Gúni fiának, Abdielnek a fia volt a család feje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'Ezek Gileádban, Básánban és az ezekhez tartozó mezővárosokban laktak, és Sáronnak minden legelőjén, határaikig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'Kik mindnyájan megszámláltatának Jótámnak, a Júda királyának idejében, és Jeroboámnak, az Izráel királyának idejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'A Rúben fiai közül és a Gáditák közül és a Manasse félnemzetsége közül erős paizs- és fegyverhordozó férfiak, kézívesek és a hadakozásban jártasok, negyvennégyezerhétszázhatvanan harczra kész férfiak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'Hadakozának a Hágárénusok ellen, Jétúr, Náfis és Nódáb ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'És győzedelmesek levének azokon, és kezekbe adatának a Hágárénusok és mindazok, a kik ezekkel valának; mert az Istenhez kiáltának harcz közben, és ő meghallgatá őket, mert ő benne bíztak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'És elvivék az ő barmaikat, ötvenezer tevét, kétszázötvenezer juhot, kétezer szamarat és százezer embert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'A seb miatt pedig sokan elhullának; mert Istentől vala az a harcz; és azok helyén lakának a fogságig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'A Manasse nemzetsége felének fiai pedig azon a földön laktak, a mely Básántól Baál-Hermonig, Szenirig és Hermon hegyéig terjedt, mert igen megsokasodtak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'És ezek voltak az ő atyjok háznépének fejedelmei: Efer, Isi, Eliel, Azriel, Irméja, Hodávia és Jahdiel, igen erős férfiak, híres férfiak, a kik az ő atyjok háznépe között fők voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Vétkezének pedig az ő atyjoknak Istene ellen; mert a föld lakóinak bálványisteneivel paráználkodának, a kiket az Isten szemök elől elpusztított.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'Felindítá azért az Izráel Istene Pulnak, az Assiriabeli királynak szívét és Tiglát-Pilésernek, az assiriai királynak szívét, és fogva elvivé őket, a Rúbenitákat, a Gáditákat és a Manasse félnemzetségét is; és elvivé őket Haláhba és Háborba, Hárába és a Gózán folyóvizéhez mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'Lévi fiai: Gerson, Kéhát és Mérári.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'Kéhát fiai pedig: Amrám, Ishár, Hebron és Uzziel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'Amrám gyermekei: Áron, Mózes és Miriám; Áron fiai pedig: Nádáb, Abihu, Eleázár és Ithamár.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'Eleázár nemzé Fineást, Fineás nemzé Abisuát;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'Abisua pedig nemzé Bukkit, Bukki nemzé Uzzit;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'Uzzi nemzé Zeráhiát, Zeráhia nemzé Mérajótot;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'Mérajót nemzé Amáriát, Amária nemzé Ahitúbot;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'Ahitúb nemzé Sádókot; Sádók nemzé Ahimáhást;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'Ahimáhás nemzé Azáriát, Azária nemzé Jóhanánt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'Jóhanán nemzé Azáriát, ez volt a pap abban a házban, a melyet Salamon Jeruzsálemben épített vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'Azária nemzé Amáriát; Amária nemzé Ahitúbot;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'Ahitúb nemzé Sádókot, Sádók nemzé Sallumot;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'Sallum nemzé Hilkiát; Hilkia nemzé Azáriát;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'Azária nemzé Séráját, Sérája nemzé Jéhozadákot;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'Jéhozadák pedig fogságba méne, mikor az Úr Júdát és Jeruzsálemet fogságba viteté Nabukodonozor által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'Lévi fiai: Gerson, Kéhát és Mérári.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'Ezek a Gerson fiainak nevei: Libni és Simhi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'Kéhát fiai: Amrám, Jiczhár, Khebron és Huzziel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'Mérári fiai: Makhli és Musi. Ezek a Lévi háznépei az ő nemzetségeik szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'Gersonnak fiai: Ligni az ő fia, Jáhát ennek fia, Zima ennek fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'Jóah ennek fia, Iddó ennek fia, Zérah ennek fia és Jéathérai ennek fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'Kéhát fiai: Amminádáb az ő fia, Kórákh ennek fia és Asszir ennek fia;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'Elkána ennek fia, Ebiásáf ennek fia és Asszir ennek fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'Tákhát ennek fia, Uriel ennek fia, Uzzia ennek fia és Saul ennek fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'Elkána fiai: Amásai és Ahimót,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'Elkána. Elkána fia: Sófai az ő fia és Náhát ennek fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'Eliáb ennek fia, Jérohám ennek fia, Elkána ennek fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'Sámuel fiai pedig: az elsőszülött Vásni, a második Abija.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'Mérári fiai: Mahli, Libni ennek fia; Simhi ennek fia és Uzza ennek fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'Simea ennek fia, Haggija ennek fia és Asája ennek fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'Ezek azok, a kiket Dávid állított be az Úr házában az énekléshez, mikor az Isten ládája elhelyeztetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'És a míg Salamon felépíté az Úr házát Jeruzsálemben, addig a gyülekezet sátora előtt szolgáltak énekléssel és állottak szolgálatban, kiki az ő rendje szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'Ezek pedig a kik szolgáltak, és az ő fiaik: a Kéhátiták fiai közül Hémán főéneklő, Jóel fia, ki Sámuel fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'Ki Elkána fia, ki Jérohám fia, ki Eliél fia, ki Thóa fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'Ki Czúf fia, ki Elkána fia, ki Mahát fia, ki Amásai fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'Ki Elkána fia, ki Jóél fia, ki Azárja fia, ki Séfánia fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'Ki Tákhát fia, ki Asszir fia, ki Ebiásáf fia, ki Kórákh fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'Ki Jiczhár fia, ki Kéhát fia, ki Lévi fia, ki Izráel fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'És ennek testvére, Asáf, a ki jobbkeze felől áll vala; Asáf, a Berekiás fia, ki Simea fia vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'Ki Mikáel fia, ki Bahásia fia, ki Melkija fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'Ki Ethni fia, ki Zérah fia, ki Adája fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'Ki Etán fia, ki Zimma fia, ki Simhi fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'Ki Jáhát fia, ki Gerson fia, ki Lévi fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'Továbbá a Mérári fiai, a kik azokkal atyafiak valának, balkéz felől állnak vala; Etán, Kisi fia, ki Abdi fia, ki Malluk fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'Ki Kasábja fia, ki Amásia fia, ki Hilkia fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'Ki Amsi fia, ki Báni fia, ki Sémer fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'Ki Makhli fia, ki Musi fia, ki Mérári fia, ki Lévi fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'És testvéreik, a Léviták rendeltetnek vala az Isten háza hajlékának egyéb szolgálatjára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'Áron pedig és az ő fiai az egészen megégetendő áldozatnak oltára mellé, és a füstölő oltár mellé, a szentek-szentjének szolgálatja mellé, és az Izráel megszentelésére rendeltetének mind a szerint, a mint Mózes, az Isten szolgája megparancsolta volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'Áron fiai pedig ezek: Eleázár, az ő fia, ennek fia Fineás, ennek fia Abisua.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'Ennek fia Bukki, ennek fia Uzzi, ennek fia Zerája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'Ennek fia Merájót, ennek fia Amárja, ennek fia Akhitúb.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'Ennek fia Sádók, ennek fia Akhimás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'És az Áron fiainak, a Kéhátiták nemzetségéből, ezek a lakhelyeik, letelepedésük szerint az ő vidékükön, mert ez jutott volt nékik sors által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'Ők kapták Hebront, a Júda földében és a körülte való legelőket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'De e város földjeit és annak faluit Kálebnek, a Jefunné fiának adák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'Az Áron fiainak azért a Júda városai közül adák a menedékvárosokat, Hebront, Libnát és legelőit, Jatthirt és Esthemoát és ezeknek legelőit,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'És Hilent és annak legelőit, és Débirt és annak legelőit,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'Asánt és annak legelőit, és Béth-Semest és annak legelőit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'A Benjámin nemzetségéből: Gébát és annak legelőit, Allémetet és annak legelőit, Anatót várost is és annak legelőit. Ezeknek az ő nemzetségek szerint tizenhárom városuk volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'A Kéhát többi fiainak pedig az egy nemzetségnek családjaitól, és a félnemzetségből, a Manasse nemzetségének felétől, sors által tíz várost adtak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'Míg a Gerson fiainak meg az ő nemzetségök szerint az Izsakhár nemzetségéből, az Áser nemzetségéből, a Nafthali nemzetségéből és a Manasse nemzetségéből Básánban adtak tizenhárom várost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'A Mérári fiainak az ő nemzetségök szerint a Rúben nemzetségéből, a Gád nemzetségéből és a Zebulon nemzetségéből sors által tizenkét várost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'Adának tehát az Izráel fiai a Lévitáknak városokat, azoknak legelőivel együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'Sors által adták a Júda nemzetségéből, a Simeon nemzetségéből és a Benjámin nemzetségéből ezeket a névszerint megnevezett városokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'Azoknak, a kik a Kéhát fiainak családjaiból valók voltak, és a határukban levő városok az Efraim nemzetségéből valának:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 67, 'Azoknak adák a menedékvárosokat, Sikemet és annak legelőit az Efraim hegyén, Gézert és annak legelőit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 68, 'És Jokmeámot és annak legelőit, Bethoront és annak legelőit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 69, 'Ajalont és annak legelőit; Gáthrimmont is és annak legelőit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 70, 'A Manasse nemzetségének feléből Anert és annak legelőit, Bileámot és annak legelőit, a Kéhát többi fiainak családjai részére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 71, 'A Gerson fiainak pedig a Manasse félnemzetségéből Gólánt Básánban és annak legelőit, és Astarótot és annak legelőit:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 72, 'Az Izsakhár nemzetségéből adák Kédest és annak legelőit; Dobrátot és annak legelőit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 73, 'Rámótot és annak legelőit, Anémet és annak legelőit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 74, 'Az Áser nemzetségéből Másált és annak legelőit, és Abdont és annak legelőit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 75, 'Hukókot és annak legelőit; Réhobot és annak legelőit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 76, 'A Nafthali nemzetségéből Kédest Galileában és annak legelőit; Hammont és annak legelőit; és Kirjáthaimot és annak legelőit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 77, 'A Mérári többi fiainak a Zebulon nemzetségéből Rimmont és annak legelőit, és Thábort és annak legelőit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 78, 'A Jordánon túl Jérikhó ellenében a Jordánnak napkelet felől való részében a Rúben nemzetségéből Bésert a pusztában és annak legelőit; Jahását és annak legelőit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 79, 'Kedemótot és annak legelőit; Mefaátot és annak legelőit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 80, 'A Gád nemzetségéből Rámótot Gileádban és annak legelőit; Mahanaimot és annak legelőit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 81, 'Hesbont és annak legelőit; Jaázert és annak legelőit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'Izsakhár fiai: Thóla, Pua, Jásub és Simron, négyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'Thóla fiai pedig: Uzzi, Réfája, Jériel, Jakhmai, Jibsám és Sámuel, kik fejedelmek valának az ő atyjaiknak családjaiban. A Thóla fiai erős hadakozók voltak nemzetségökben, kiknek száma Dávid király idejében huszonkétezerhatszáz vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'Uzzi fiai: Izráhja; és az Izráhja fiai: Mikáel, Obádia, Joel, Issia, öten, a kik mind főemberek valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'És közöttük nemzetségeik és családjaik szerint harminczhatezer hadakozó férfi volt, mert sok feleségök volt és sok fiuk is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'Ezeknek testvéreik is, Izsakhárnak egész nemzetsége szerint erős hadakozó férfiak valának, nyolczvanhétezeren szám szerint mindenestől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'Benjámin fiai: Bela, Béker és Jediáel, hárman.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'Bela fiai: Esbon, Uzzi, Uzziel, Jérimót és Hiri, öt főember az ő nemzetségökben, erős hadakozó férfiak, a kik megszámláltatván, huszonkétezerharmincznégyen valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'Béker fiai: Zémira, Joás, Eliézer, Eljoénai, Omri, Jeremót, Abija, Anatót és Alémet; ezek mindnyájan Béker fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'Azok megszámláltatván nemzetségeik szerint, családjuk fejei és az erős hadakozó férfiak húszezerkétszázan valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'Továbbá Jédiáel fia: Bilhán; Bilhán fiai: Jéus, Benjámin, Éhud, Kénaána, Zetán, Társis és Ahisahár.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'Ezek mind Jédiáel fiai, családfők, erős hadakozó férfiak, a kik tizenhétezerkétszázan mehetnek vala ki a viadalra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'Ir fiai: Suppim és Khuppim; Húsim Ahernek fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'Nafthali fiai: Jakhcziel, Gúni, Jéczer, Sallum, a Bilha fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'Manasse fiai: Aszriel, kit szüle az ő felesége. Az ő ágyastársa pedig, a Siriabeli asszony szülé Mákirt, a Gileád atyját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'Mákir pedig vevé feleségül Khuppimnak és Suppimnak hugát, kinek neve Maáka. A másiknak neve Czélofhád. Czélofhádnak leányai voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'Maáka, a Mákir felesége szüle fiat, a kit neveze Péresnek; annak pedig öcscsét Séresnek. Ennek fiai: Ulám és Rékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'Ulám fia: Bédán. Ezek a Gileád fiai, ki Mákir fia volt, ki Manasse fia volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'Az ő huga, Moléket pedig szülé Ishodot, Abiézert és Makhlát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'Semidának fiai voltak: Ahián, Sekem, Likhi és Aniám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'Efraim fiai pedig: Sútelákh, kinek fia Béred, ennek fia Táhát, ennek fia Elhada, ennek fia Táhát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'Ennek fia Zábád, ennek fia Sútelákh, Ezer és Elhád. És megölék ezeket a Gáthbeliek, a földnek lakosai; mert alámentek vala, hogy barmaikat elhajtsák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'Efraim azért, az ő atyjok sokáig siratá őket, a kihez elmennek vala az ő atyjafiai, és őt vigasztalják vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'Beméne azért az ő feleségéhez, ki fogada méhében, és szüle fiat, és nevezé Bériának, mivelhogy szerencsétlenség történt az ő házában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'Leánya pedig Seéra vala, a ki alsó és felső Bethoront és Uzen-Seérát építé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'Réfah is az ő fia és Resef; ennek fia Théla, ennek fia Táhán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'Ennek fia Laadán, ennek fia Ammihud, ennek fia Elisáma.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'Ennek fia Nún, ennek fia Józsué.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'Ezeknek birtokuk és lakóhelyük vala: Béthel és annak mezővárosai; napkeletre Naarán, napenyészetre Gézer és ennek mezővárosai, Sikem és ennek mezővárosai, szinte Gázáig és az ehhez tartozó mezővárosokig;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'És a Manasse fiai mellett: Béth-Seán és ennek mezővárosai, Thaanák és ennek mezővárosai, Megiddó és ennek mezővárosai, Dór és ennek mezővárosai. Ezekben laktak az Izráel fiának, Józsefnek fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'Áser fiai: Jimnah, Jisvah, Jisvi, Beriha és Szerakh, az ő hugok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'Beriha fiai: Khéber és Malkhiel, a ki Birzávit atyja volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'Khéber pedig nemzé Jaflétet, Sómert, Hótámot és Suát, az ő hugokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'Jaflét fiai: Pásák, Bimhál, Asvát; ezek Jaflét fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'Sómer fiai: Ahi és Róhega, Jehubba és Arám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'Testvérének, Hélemnek fia vala: Sófákh, Jimna, Séles és Amál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'Sófákh fiai: Suákh, Harnéfer, Suál, Béri és Imra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'Béser, Hód, Samma, Silsa, Itrán és Beéra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'Jéter fiai: Jéfunné, Pispa és Ara.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'Ulla fiai: Ara, Hanniel és Risja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, 'Ezek mind Áser fiai, családfők, válogatott harczosok, a fejedelmek fejei; és megszámláltatván az ő nemzetségök rendje szerint, huszonhatezer harczra képes férfi volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'Benjámin pedig nemzé Belát, az ő elsőszülöttét, másodikat Asbélt, harmadikat Akhráhot,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'Negyediket Nóhát, és Ráját ötödiket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, '(Belának fiai voltak: Adár, Géra és Abihúd,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'Abisua, Naamán, Ahóah.)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'Gérát, Sefufánt és Hurámot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'Ezek az Ehud fiai: (Ezek voltak főemberek a Géba városában lakó nemzetség között, kiket fogságba vittek Manahátba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'Nevezetesen Naamánt és Ahiját és Gérát vitték fogságba): nemzé pedig Uzzát és Akhihúdot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'Saharáim pedig nemzé a Moáb mezején, minekutána eltaszítá feleségeit, Husimot és Baarát;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'Nemzé Hódes nevű feleségétől Jobábot és Sibját, Mésát és Malkámot,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'Jéust is, Sokját és Mirmát. Ezek az ő fiai; főemberek az ő nemzetségökben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'Husimtól nemzé Abitúbot és Elpaált.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'Elpaál fiai: Eber, Miseám és Sémer; ez építé Onót és Lódot és ennek mezővárosait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'Béria, Séma, (ezek voltak fők az Ajalonban lakozó nemzetségek közt, és ezek űzték vala el Gáthnak lakóit),');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'Ahio, Sasák, Jeremót,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'Zebádia, Arád, Ader.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'Mikáel, Ispa, Jóha, Béria fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'Zebádia, Mésullám, Hizki, Héber.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'Ismérai, Izlia és Jobáb; Elpaál fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'Jákim, Zikri, Zabdi,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'Eliénai, Silletai, Eliel,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'Adája, Berája és Simrát, Simhi fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'Jispán, Eber, Eliel,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'Abdon, Zikri, Hanán,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'Hanánja, Elám, Anatótija,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'Ifdéja, Pénuel, Sasák fiai,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'Samsérai, Sehárja, Atália.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'Jaarésia, Elia, és Zikri, Jérohám fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'Ezek voltak a családfők az ő nemzetségök szerint, főemberek és ezek laktak Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'Gibeonban pedig laktak Gibeonnak atyja; az ő feleségének neve Maaka vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'És az ő elsőszülötte Abdon, azután Súr, Kis, Baál, Nádáb;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'Gedor, Ahio és Zéker,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'És Miklót, a ki nemzé Simámot. Ezek is testvéreiknek átellenében, Jeruzsálemben laktak testvéreikkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'Nér pedig nemzé Kist; Kis nemzé Sault, Saul nemzé Jonathánt, Malkisuát, Abinádábot és Esbaált.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'Jonathán fia: Méribbaál; Méribbaál nemzé Mikát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'Mika fiai: Pitón, Mélek, Tárea és Akház.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'Akház nemzé Jehoádát. Jehoáda pedig nemzé Alémetet és Azmávetet és Zimrit; Zimri nemzé Mósát;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'Mósa pedig Binát; ennek fia Ráfa, ennek fia Elása, ennek fia Asel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'Továbbá Aselnek hat fia volt, kiknek ezek neveik: Azrikám, Bókru, Ismáel, Seárja, Obádia és Hanán; ezek mind Asel fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'Az ő testvérének Eseknek fiai ezek: Ulám az ő elsőszülötte, Jéus második és Elifélet harmadik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'És az Ulám fiai erős hadakozó férfiak, kézívesek voltak, s gyermekeik és unokáik százötvenre szaporodtak. Mindezek a Benjámin fiai közül valók voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'Az egész Izráel megszámláltatván nemzetségeik szerint, beirattak az Izráel és Júda királyainak könyvébe, a kik gonoszságukért Babilóniába vitetének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'A legelső lakosok az ő jószágaikon s városaikban, ezek: Izráeliták, papok, Léviták és Nétineusok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'Mert Jeruzsálemben laktak a Júda fiai közül s Benjámin fiai közül, Efraim és Manasse fiai közül valók:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'Utái, Ammihud fia, ki Omri fia, ki Imri fia, ki Báni fia, a Pérecz fiai közül való, ki Júda fia vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'A Silóniták közül, Asája, ki elsőszülött vala s ennek fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'A Zérah fiai közül: Jéuel és az ő atyjafiai, hatszázkilenczvenen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'A Benjámin fiai közül: Sallu, Mésullám fia, ki Hodávia fia, ki Hasénua fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'Ibnéja, Jérohám fia, és Ela, Uzzi fia, ki Mikri fia, és Mésullám, Séfátja fia, ki Reuel fia, ki Ibnija fia vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'Testvéreik, nemzetségeik szerint, kilenczszázötvenhatan valának; ezek mind családfők voltak az ő atyjok háznépe szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'A papok közül is: Jedája, Jéhojárib és Jákin.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'Azária, Hilkia fia, ki Mésullám fia, ki Sádók fia, ki Mérajót fia, ki Ahitubnak, az Isten háza főgondviselőjének fia vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'És Adája Jérohám fia, ki Pashúr fia, ki Málkija fia; Maasai, Adiel fia, ki Jahzéra fia, ki Mésullám fia, ki Mésillémit fia, ki Immer fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'Ezeknek atyjokfiai az ő családjaiknak fejei, ezerhétszázhatvanan valának, buzgók az Isten háza dolgának munkájában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'A Léviták közül Semája, Hásub fia, ki Azrikám fia, ki Hasábia fia, a Mérári fiai közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'Bakbakkár, Héres és Galál, és Mattánia, a Mika fia, ki Zikri fia, ki Asáf fia vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'Obádia, a Semája fia, Galál fia, ki Jédutun fia, és Bérékia, Asa fia, ki Elkána fia, a ki Nétofáti faluiban lakik vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'És az ajtónállók: Sallum, Akkúb, Talmon, Ahimán és ezek testvérei; Sallum pedig fő vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, '(És ennek mindez ideig a királykapun van helye napkelet felől.) Ezek az ajtónállók a Léviták rendje szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'Sallum pedig a Kóré fia, ki Ebiásáf fia, ki Kórákh fia, és ennek rokonságai a Kórakhiták családjából a szolgálat munkájában a hajlék ajtajának őrizői valának, mint az ő atyáik az Úr seregében őrizték vala a bejáratot,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'Mikor Fineás, az Eleázár fia volt egykor az ő előljárójok, kivel az Úr vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'Zakariás, a Meselémia fia, a gyülekezet sátorába való bejárat őrizője.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'Ezek mind választott ajtónállók voltak, kétszáztizenketten; kik az ő faluikban, nemzetségök szerint, megszámláltattak volt; kiket Dávid rendelt és Sámuel próféta az ő tisztökbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'Ők és fiaik őrizik vala renddel az Úr házának, a sátornak kapuit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'Négyfelé valának az őrizők: napkeletre, napnyugotra, északra és délre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'És ezeknek atyjokfiai az ő faluikban valának, de minden hetednap amazokhoz felmenének Jeruzsálembe bizonyos ideig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'De a kapunállók négy főemberének állandó megbizatásuk volt. Ezek a Léviták őrizik vala a kamarákat és az Isten házának kincseit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'És az Úrnak háza körül hálnak vala, mivelhogy az őrzés az ő tisztök volt, és minden reggel ők nyitják vala meg az ajtókat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'És ő közülök némelyek a szolgálati edényekre viselnek vala gondot; mert mind a kivitelnél, mind a visszavitelnél számon veszik vala azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'Ugyanazok közül választattak vala némelyek másféle edénynek, a szenthely minden eszközeinek, a lisztnek, bornak, olajnak, tömjénnek és fűszereknek gondviselésére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'A papok fiai közül valók csinálják vala fűszerekből a drágakenetet is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'Továbbá Mattitja, a Léviták közül való (ki elsőszülötte a Kórakhiták közül való Sallumnak), a serpenyőkre visel vala gondot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'A Kéhátiták fiai és azok atyjokfiai közül rendeltettek volt a szent kenyérnek gondviselésére, hogy minden szombaton megkészítsék azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'Ezek közül valók valának az éneklők is, a Léviták közül a családfők, a kik szabadosok valának egyéb tiszttől az ő kamarájokban; mert éjjel és nappal szolgálattal tartoznak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'Ezek a Léviták között családfők nemzetségök szerint, főemberek, és ezek Jeruzsálemben laktak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'Gibeonban pedig laktak a Gibeon atyja, Jéhiel, és az ő feleségének neve Maaka.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'Az ő elsőszülött fia Abdon, azután Súr, Kis, Baál, Nér és Nádáb.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'Gedor, Ahió, Zékária és Miklót.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'Miklót pedig nemzé Simámot. Ezek is az ő atyjokfiai átellenében laktak Jeruzsálemben az ő testvéreikkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'Nér nemzé Kist, Kis nemzé Sault, Saul pedig nemzé Jonathánt, Málkisuát, Abinádábot és Esbaált.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'Jonathán fia Méribbaál; és Méribbaál nemzé Mikát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'Mika fiai: Piton, Mélek és Táréa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'Akház pedig nemzé Jahrát, Jahra nemzé Alémetet, Azmávetet, Zimrit, Zimri pedig nemzé Mósát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'Mósa nemzé Bineát, ennek fia Réfája, ennek fia Elása, ennek fia Ásel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'Áselnek hat fia volt, kiknek neveik: Azrikám, Bókru, Ismáel, Seárja, Obádia és Hanán; ezek Ásel fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'A Filiszteusok pedig hadakoznak vala az Izráellel, és megfutamodék Izráel népe a Filiszteusok előtt, és néhányan a sebek miatt el is hullának a Gilboa hegyén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'Elérék pedig a Filiszteusok Sault és az ő fiait, és megölék a Filiszteusok Jonathánt, Abinádábot és Malkisuát, a Saul fiait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'És a viadal igen heves volt Saul körül, és rátalálván a kézívesek, nyilakkal megsebesíték őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'És monda Saul az ő fegyverhordozójának: Vond ki fegyveredet, és verj által engem vele, mert netalán eljőnek e körülmetéletlenek, és meggyaláznak engemet. De fegyverhordozója nem akará, mert igen fél vala. Ragadá azért Saul a fegyvert, és belé bocsátkozék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'Látván pedig az ő fegyverhordozója, hogy Saul immár meghalt, ő is a fegyverbe bocsátkozék, és meghala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'Meghala azért Saul és az ő három fia, és egész háznépe is egyetemben meghala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'Mikor pedig meglátták Izráelnek minden férfiai, a kik a völgyben valának, hogy ők megfutamodtak, és hogy Saul és az ő fiai megholtak: pusztán hagyák városaikat és elfutának. Akkor eljövének a Filiszteusok, és azokba beszállának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'Lőn pedig másodnap, eljövének a Filiszteusok, hogy a holtakat kifoszszák, és megtalálák Sault és az ő fiait, halva feküdvén a Gilboa hegyén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'És kifoszták őt, és elvevék fejét és az ő fegyvereit, és elküldék a Filiszteusok minden tartományába köröskörül, hogy hírül adják bálványaiknak és a népnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'Az ő fegyvereit isteneik házába helyezék el, fejét pedig Dágon templomában akasztották fel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'Mikor pedig meghallotta az egész Jábesgileád, hogy mit cselekedtek a Filiszteusok Saullal:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'Feltámadának mindnyájan az erős férfiak, és elvivék Saulnak és az ő fiainak testét; és Jábesbe vivén, eltemeték azoknak csontjaikat a tölgyfa alatt Jábesben, és bőjtölének hetednapig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'Meghala azért Saul az ő gonoszsága miatt, mivel vétkezett az Úr ellen, az Úrnak igéje ellen, melyet nem őrzött meg, sőt az ördöngöst is megkereste, hogy megkérdezze;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'És nem az Urat kérdé. Ezért elveszté őt, és adá az ő országát Dávidnak, az Isai fiának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'És gyűlének az Izráeliták mindnyájan Dávidhoz Hebronba, mondván: Ímé mi a te csontod és a te tested vagyunk;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'Ezelőtt is, még mikor Saul volt a király, te voltál az, a ki az Izráelt ki- és bevezetéd, és ezt mondotta a te Urad Istened néked: Te legelteted az én népemet, az Izráelt, és te leszel vezér az én népemen, az Izráelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'Elmenének azért mindnyájan az Izráel vénei a királyhoz Hebronba, és szövetséget tőn Dávid velök Hebronban az Úr előtt; és királylyá kenték Dávidot Izráel felett, az Úrnak Sámuel által való beszéde szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'Elméne akkor Dávid és az egész Izráel Jeruzsálembe; ez Jebus (ott a Jebuzeusok voltak a föld lakosai).');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'És mondának Jebus lakói Dávidnak: Ide be nem jössz! De megvevé Dávid a Sion várát; ez a Dávid városa;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'Mert ezt mondotta vala Dávid: A ki legelőször egy Jebuzeust levág, előljáró és vezér legyen. Felméne azért legelőször Joáb, a Séruja fia; és lőn előljáróvá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'Azután lakék Dávid a várban, azért nevezék azt Dávid városának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'És megépíté Dávid a várost Millótól fogva egészen körül; Joáb pedig megépíté a városnak maradékát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'És folytonosan emelkedék Dávid; mert a Seregek Ura vala ő vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'Ezek pedig a hősök előljárói, a kik Dávid mellett valának, a kik erősen forgolódának vele az ő királyságáért egész Izráellel, hogy királylyá válaszszák őt Izráel felett, az Úr beszéde szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'Ezek számszerint a hősök, a kik Dávid körül valának: Jásobeám, Hakhmoni fia, a harmincznak előljárója; ez emelte vala fel az ő kopjáját háromszáz ellen, a kiket egyszerre megsebesíte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'Ezután Eleázár, az Ahóhita Dódó fia; a ki a három hős közül egy vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'Ő vala Dáviddal Pasdamimban, a hová összegyűlének a Filiszteusok viadalra. Egy darab föld árpával vala tele, és a nép elmenekült a Filiszteusok elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'De ők megállának ott annak a darab földnek a közepén, és megtartották azt, és megverék a Filiszteusokat, és az Úr megszabadítá őket nagy szabadítással.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'Továbbá, mikor alámentek hárman a harmincz főember közül Dávidhoz, a kősziklához, az Adullám barlangjába; a Filiszteusok pedig tábort járának a Réfaim völgyben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, '(Dávid az erősségben vala akkor, a Filiszteusok hada pedig Bethlehemnél.)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'Kivána Dávid vizet, és monda: Óh, ki adhatna nékem innom a Bethlehem kapuja előtt való forrásnak vizéből!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'Akkor keresztülvágták magokat hárman a Filiszteusok táborán, és vizet merítének a Bethlehem forrásából, mely a kapu előtt vala, és felvivék, és menének Dávidhoz; de Dávid nem akara inni, hanem kitölté azt az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'És monda: Távoztassa el tőlem az én Istenem, hogy ezt cselekedném. Avagy e férfiaknak vérét igyam-é meg, a kik életöket halálra vetették? Mert ők ezt életök veszedelmével hozták. És semmiképen nem akara inni. Ezt cselekedé a három hős.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'És Abisai, a Joáb testvére vala e háromnak előljárója; ő ragadott vala dárdát háromszáz ellen, a kiket megsebesíte; és ő volt a leghíresebb a három között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'A három közül a kettőnél híresebb vala, azért volt azok előljárója; de azért egymaga még sem ért föl a hárommal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Benája, a Jojada fia, vitéz férfiúnak fia Kabséelből, a ki nagy dolgokat cselekedék; ő ölte meg Moáb két oroszlánját, és ő méne alá a verembe, s ölte meg az oroszlánt, mikor havas idő volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'Ugyanez ölé meg az Égyiptombeli férfit, akinek magassága öt sing volt, és oly dárda vala az Égyiptombeli férfiú kezében, mint a szövő zugoly. Szembeszálla vele egy pálczával, s kiragadá az Égyiptombeli ember kezéből a dárdát, és saját dárdájával általveré.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'Ezeket cselekedte Benája, a Jojada fia, a ki híres vala a három hős között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'Híres vala ő a harmincz között, de azzal a hárommal nem ért fel. És előljáróvá tevé őt Dávid a tanácsosok között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'A seregnek pedig ezek vitézei: Asael, a Joáb testvére; Elhanán, Dódónak fia, ki Bethlehembeli vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'Haróritból való Sammót, Pélomból való Héles,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'Tékoabeli Hira, Ikkés fia, Anatótbeli Abiézer,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'Húsatbeli Sibbékai, Ahóhitbeli Hirai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'Nétofátbeli Maharai, Nétofátbeli Héled, Bahána fia;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Ittai, Ribai fia, a Benjámin fiainak Gibea városából való; Pirátonbeli Benája;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Húrai, a Gaás völgyéből való; Arbátbeli Abiel;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'Baharumi Azmávet, Saálbonitbeli Eliáhba;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'Gisonbeli Hásem fiai: Jonathán, Hararitbeli Ságé fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'Hararitbeli Ahiám, Sákár fia; Elifál, Úr fia,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'Mekerátbeli Héfer, Pélonbeli Ahija,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'Kármelből való Hésró, Naárai, Ezbái fia,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Jóel, Nátán testvére; Mibhár, Géri fia;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'Sélek, Ammon nemzetségéből való; Berótbeli Naárai, Joábnak, a ki Séruja fia vala, fegyverhordozója;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'Itrébeli Hira, Itrébeli Gáreb,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'Hitteus Uriás, Zabád, Ahlai fia;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'Hadina, a Rúben nemzetségéből való Siza fia, ki a Rúbeniták előljárója vala, és vele harminczan valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Hanán, Maaka fia, és Mitnibeli Jósafát,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'Asterátbeli Uzzija; Sáma és Jéhiel, Aroerbeli Hótám fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Jidiháel, Simri fia, és az ő testvére, Joha, Tisibeli.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'Mihávimbeli Eliel, Jéribai és Jósávia, Elnaám fia, és Jitma, Moáb nemzetségéből való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'Eliel és Obed és Jaásiel, Mésóbájából valók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'Ezek azok, a kik Dávidhoz menének Siklágba, mikor Saul, a Kis fia miatt még számkivetésben vala, a kik a hősöknek a harczban segítői voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'Ívesek, a kik mind jobb-, mind balkézre kővel hajítanak és nyíllal lőnek vala, a kik Saul atyjafiai közül valók valának, Benjámin nemzetségéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'Előljáró vala Ahiézer és Joás, a Gibeabeli Semáa fiai és Jéziel és Pélet, Azmávet fiai, Beráka és Jéhu, Anatótból,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'És a Gibeonbeli Ismája, a harmincz közül való hős, a kiknek előljárójok is vala; Irméja, Jaháziel, Johanán és Gederátbeli Józabád,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'Elúzai, Jérimót, Behália, Semária és Hárufbeli Sefátja,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'Elkána, Isija, Azaréel, Jóézer és a Kóré nemzetéből való Jásobéám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'Joéla és Zebádja, a Gedorból való Jérohám fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'A Gáditák közül is menének Dávidhoz, mikor a pusztában vala az erősségben, erős és hadakozó férfiak, paizsosok, dárdások, a kiknek orczájok, mint az oroszlánnak orczája és gyorsaságra hasonlók a hegyen lakozó vadkecskékhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'Ézer az első, Obádia második, Eliáb harmadik,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'Mismanna negyedik, Jirméja ötödik,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'Attai hatodik, Eliel hetedik,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'Nyolczadik Johanán, kilenczedik Elzabád,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'Tizedik Jirméja, tizenegyedik Makbánnai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'Ezek voltak főemberek a seregben a Gád fiai közül; a legkisebbek egyike száz ellen, a legnagyobbak egyike ezer ellen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'Ezek azok, a kik a Jordánon átmentek volt az első hónapban, noha az árvíz a partot felülmúlta, és elűzték mindazokat, a kik a völgyben valának napkelet felől és napnyugot felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'Jövének Dávidhoz a Benjámin és a Júda fiai közül is az erősségbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'És kiméne Dávid elejökbe, és felelvén, monda nékik: Hogyha békesség okáért jöttök hozzám, hogy segítségemre legyetek, az én szívem egy lesz ti veletek; ha pedig meg akartok csalni, hogy eláruljatok az én ellenségeimnek, holott semmi gonoszságot nem követtem el: lássa meg a mi atyáink Istene és büntessen meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'A lélek pedig felindítá Amásait, a harmincznak fejedelmét, s monda: Óh Dávid, tied vagyunk és te veled leszünk, Isai fia! Békesség, békesség néked, békesség a te segítőidnek is, mert megsegít téged a te Istened! Magához fogadá azért őket Dávid, és főemberekké tevé a seregben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'Ennekfelette Manasséból is hajlának Dávidhoz, mikor a Filiszteusokkal együtt Saul ellen ment volna harczolni; de nem segéllék őket; mert tanácsot tartván, haza küldék a Filiszteusok fejedelmei, mondván: A mi fejünk veszésével fog visszamenni az ő urához, Saulhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Mikor visszatére Siklágba, hajlának ő hozzá a Manassé fiai közül Adna, Józabád, Jediháel, Mikáel, Józabád, Elihu és Sillétai, a kik a Manasse nemzetségéből való ezerek előljárói voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'És ezek Dávidnak segítségül voltak az ellenség seregei ellen; mert fejenként mind erős vitézek valának, és vezérek a seregben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'Annakfelette minden nap mennek vala Dávidhoz, hogy segítségére legyenek néki, míg serege nagygyá lőn, mint az Istennek tábora.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'Ezek pedig számszerint a viadalhoz készült előljárók, a kik Dávidhoz mentek vala Hebronban, hogy őt Saul helyett az országban királylyá válaszszák, az Isten ígérete szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'A Júda fiai közül, a kik paizst és kopját viselének hatezernyolczszáz vala harczra készen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'A Simeon fiai közül vitéz férfiak a viadalra, hétezerszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'A Lévi fiai közül négyezerhatszáz vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'Jojada is, ki az Áron fiai között előljáró vala, és ő vele háromezerhétszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'És az ifjú Sádók, a ki igen erős vala, és az ő atyja házából huszonkét főember.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'A Benjámin fiai közül, a kik Saul atyjafiai valának, háromezer; mert még azok közül sokan hűségesen őrizik vala a Saul házát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'Az Efraim fiai közül húszezernyolczszáz, igen vitézek, a kik az ő nemzetségökben híres férfiak valának;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'Manassénak félnemzetségéből pedig tizennyolczezer, kik névszerint kijelöltetének, hogy elmenjenek és Dávidot királylyá válaszszák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'Az Izsakhár fiai közül, a kik felismerék az idő alkalmatos voltát, hogy tudnák, mit kellene Izráelnek cselekednie, kétszáz főember és az ő rokonaik mind hallgatnak vala beszédjökre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'A Zebulon fiai közül a harczra kimenők, minden hadiszerszámokkal felkészülve, ötvenezeren valának, készek a viadalra állhatatos szívvel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'A Nafthali nemzetségéből ezer főember vala; és ő velek paizszsal s kopjával harminczhétezer vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'A Dániták közül, a kik a viadalhoz készek valának, huszonnyolczezerhatszázan voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'És az Áser fiai közül a hadakozók és az ütközethez készek negyvenezeren valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'A Jordánon túl lakozók közül, azaz a Rúbeniták, Gáditák és a Manasse nemzetségének fele közül, minden viadalhoz való szerszámokkal egyetemben, jöttek százhúszezeren.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'Mindezek hadakozó férfiak, a viadalra elkészülve, egy értelemmel mentek vala Hebronba, hogy Dávidot az egész Izráel felett királylyá válaszszák, sőt ezeken kivül is az egész Izráel egy szívvel azon volt, hogy Dávidot királylyá válaszszák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'És ott maradának Dáviddal harmadnapig, s esznek és isznak vala; mert az ő atyjokfiai készítettek vala nékik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'És úgy a szomszédságukban levők, mint mások Izsakhárig, Zebulonig és Nafthaliig hoznak vala kenyereket szamarakon, tevéken, öszvéreken és ökrökön, eleséget, lisztet, fügét, aszuszőlőt, bort, olajat, vágóbarmokat, juhokat számtalan sokat; mert nagy öröm vala Izráelben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'Tanácsot tarta pedig Dávid az ezredeknek és századoknak fejeivel és minden előljárókkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'És monda Dávid Izráel egész gyülekezetének: Ha néktek tetszik, és ha az Úrtól, a mi Istenünktől van: küldjünk el mindenfelé a mi atyánkfiaihoz, a kik otthon maradtak Izráel minden tartományaiban, s velök együtt a papokhoz és Lévitákhoz, az ő városaik és vidékeik szerint, hogy ők is gyűljenek hozzánk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'Hogy hozzuk ide a mi Istenünknek ládáját mi hozzánk, mert a Saul idejében nem törődtünk vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'És monda az egész gyülekezet, hogy úgy kell cselekedni; mert igaznak láttaték e dolog az egész nép előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'Összegyűjté azért Dávid mind az Izráel népét Égyiptomnak Nilus folyóvizétől fogva egészen Hámátig, hogy az Istennek ládáját elhozzák Kirjáth-Jeárimból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'Felméne azért Dávid és vele az egész Izráel Baalába vagy Kirjáth-Jeárimba, a mely Júdában van, hogy onnan elhozzák az Úr Istennek ládáját, mely az ő nevéről neveztetik, a ki a Khérubok közt ül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'És helyhezteték az Isten ládáját az Abinádáb házából egy új szekérre; Uzza és Ahió vezetik vala a szekeret.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'Dávid pedig és az egész Izráel tánczolnak vala az Isten előtt teljes erővel, énekekkel, cziterákkal, hegedűkkel, dobokkal, czimbalmokkal és kürtökkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'Mikor pedig jutottak a Kidon szérűjéhez, Uzza reá tevé kezét a ládára, hogy megtartsa, mert az ökrök félre tértek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'És az Úrnak haragja felgerjede Uzza ellen, és őt megveré, hogy reá tevé kezét a ládára, s meghala ugyanott az Isten előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'Akkor Dávid igen megdöbbene, hogy az Úr ily csapással sujtá Uzzát. Azért azt a helyet mind e mai napig Péres-Uzzának nevezik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'És félni kezde Dávid azon a napon Istentől, mondván: Miképen merjem magamhoz bevinni az Isten ládáját?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'És nem vivé be Dávid magához a ládát a Dávid városába, hanem elhelyezé azt a Gitteus Obed-Edom házában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'És az Isten ládája Obed-Edom házában volt három hónapig; és megáldá az Úr Obed-Edom házát és mindenét, valamije volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'Külde pedig Hírám, Tírus királya Dávidhoz követeket: czédrusfákat, kőmíveseket és ácsmestereket, hogy néki házat csináljanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'És megismeré Dávid, hogy az Úr őt megerősítette a királyságban Izráel felett, mivelhogy igen felmagasztaltatott vala az ő országa az ő népéért, az Izráelért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'Vőn pedig Dávid még több feleséget Jeruzsálemben, és nemze Dávid még több fiakat és leányokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'És ezek neveik azoknak, a kik születtek néki Jeruzsálemben: Sammua, Sobáb, Nátán és Salamon,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'Ibhár, Elisua és Elpélet,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'Nógah, Néfeg és Jáfia,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'Elisáma, Beheljada és Elifélet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'Megértvén pedig a Filiszteusok, hogy Dávid királylyá kenetett fel az egész Izráel felett, feljövének mind a Filiszteusok, hogy megkeressék Dávidot. Mely dolgot mikor Dávid meghallott, azonnal ellenök ment.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'A Filiszteusok pedig eljövén, elszéledének a Réfaim völgyében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'Akkor Dávid megkérdé az Istent, mondván: Felmenjek-é a Filiszteusok ellen, és kezembe adod-é őket? És monda néki az Úr: Menj fel, és kezedbe adom őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'Felmenének azért Baál-perásimba, és ott Dávid őket megveré, és monda Dávid: Az Isten eloszlatá az én ellenségeimet az én kezem által, mint a vizeknek oszlását; azért nevezék azt a helyet Baál-perásimnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'És ott hagyák az ő bálvány isteneiket, és Dávid megparancsolá, hogy megégessék azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'Ismét feltámadának a Filiszteusok és a völgyben szétterjeszkedtek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'Azért Dávid ismét megkérdé az Istent, és monda az Isten néki: Ne menj fel utánok, hanem fordulj el tőlök, és menj reájok a szederfák irányában;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'És mikor hallándod a járás dobogását a szederfák tetején, akkor menj ki a viadalra; mert az Isten te előtted megyen, hogy megverje a Filiszteusok táborát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'Dávid azért úgy cselekedék, a mint néki Isten meghagyta volt, és vágák a Filiszteusok táborát Gibeontól fogva szinte Gézerig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'És elterjede Dávid híre az országokban, és az Úr adá a tőle való félelmet minden pogányokra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'Csináltata pedig Dávid magának házakat az ő városában; és helyet készített az Isten ládájának, és annak sátort állított fel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'Akkor monda Dávid: Nem szabad másnak hordozni az Isten ládáját, hanem csak a Lévitáknak, mert az Úr őket választotta, hogy hordozzák az Isten ládáját, és néki szolgáljanak mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'Összegyűjté azért Dávid Jeruzsálembe az egész Izráel népét, hogy az Úr ládáját az ő helyére vitesse, melyet számára csináltatott vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'Összegyűjté Dávid az Áron fiait is és a Lévitákat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'A Kéhát fiai között fő vala Uriel, és az ő atyjafiai százhúszan valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'A Mérári fiai között Asája volt a fő, és az ő atyjafiai kétszázhúszan valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'A Gerson fiai között Jóel volt a fő, és az ő atyjafiai százharminczan valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'Az Elisáfán fiai között Semája volt a fő, és az ő atyjafiai kétszázan valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'A Hebron fiai között Eliel volt a fő, és az ő atyjafiai nyolczvanan valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'Az Uzziel fiai között fő vala Amminádáb, és az ő atyjafiai száztizenketten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'Hivatá akkor Dávid Sádók és Abjátár papokat, a Léviták közül pedig Urielt, Asáját, Jóelt, Sémáját, Elielt és Amminádábot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'És monda nékik: Ti vagytok a Léviták családfői. Szenteljétek meg magatokat s a ti atyátokfiait, és vigyétek az Úrnak, Izráel Istenének ládáját arra a helyre, a melyet készítettem számára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'Minthogy kezdettől fogva nem mívelték ezt, az Úr, a mi Istenünk csapást bocsátott reánk, mert nem kerestük őt a rendtartás szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'Megszentelék azért magokat a papok és a Léviták, hogy vigyék az Úrnak, Izráel Istenének ládáját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'És felvevék a Léviták fiai az Isten ládáját, úgy, a mint Mózes meghagyta volt az Úrnak beszéde szerint, a rudakkal vállaikra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'És monda Dávid a Léviták fejedelmeinek, hogy állítsanak az ő atyjokfiai közül éneklőket, éneklőszerszámokkal, lantokkal, cziterákkal és czimbalmokkal, hogy énekeljenek felemelt szóval, nagy örömmel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'Választák azért a Léviták Hémánt a Jóel fiát, és az ő atyjafiai közül Asáfot, a Berekiás fiát, és a Mérári fiai közül, a kik azoknak atyjokfiai valának, Etánt, a Kúsája fiát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'És ő velök együtt az ő atyjokfiait másod renden, Zakariást, Bént, Jeázielt, Semirámótot, Jéhielt, Unnit, Eliábot, Benáját, Maaséját, Mattithját, Elifélet, Miknéját, Obed-Edomot és Jehielt, a kik ajtónállók valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'Éneklők: Hémán, Asáf és Etán, réz czimbalmokkal, hogy zengedezzenek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'Zakariás, Aziel, Semirámót, Jéhiel, Unni, Eliáb, Maaséja és Benája lantokkal a szűzek módjára;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'Mattithja, Eliféle, Miknéja, Obed-Edom, Jéhiel és Azaziás, hogy énekeljenek cziterákkal a nyolczhúrú szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'És Kénániás volt a Léviták vezére az éneklésben, ő igazgatá az éneklést, mivel tudós vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'Berekiás és Elkána a láda előtt való ajtónállók valának:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'Sébániás pedig és Jósafát, Nétanéel, Amásai, Zakariás, Benája és Eliézer papok kürtölnek vala az Isten ládája előtt; Obed-Edom és Jéhija, a kik kapunállók valának, a láda után mennek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'Dávid pedig s az Izráel vénei és az ezredek vezérei, a kik elmenének, hogy felvigyék az Úr szövetségének ládáját az Obed-Edom házából, nagy örömben valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'Lőn pedig, mikor az Isten megsegíté a Lévitákat, akik az Úr szövetségének ládáját viszik vala, áldozának hét tulokkal és hét kossal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'Dávid pedig bíborból csinált ruhába öltözvén, valamint a Léviták mind, a kik a ládát viszik vala, az éneklők is és Kénániás, a ki az éneklés vezére vala, énekelének (Dávidon pedig gyolcsból csinált efód vala).');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'És az egész Izráel vivé az Úr szövetségének ládáját nagy örömmel, kürtökkel, trombitákkal, czimbalmokkal, zengedezvén lantokkal és cziterákkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'Mikor pedig immár az Úr szövetségének ládája a Dávid városába jutott, Mikál a Saul leánya kitekinte az ablakon, s látván, hogy Dávid király tánczol és vígad, szívében megutálá őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'Mikor pedig bevitték az Isten ládáját és elhelyezék azt a sátor közepén, a melyet Dávid annak számára felállított vala: áldozának egészen égő- és hálaáldozatokkal az Isten előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'És mikor Dávid elvégezte az egészen égőáldozatot és a hálaáldozatot, az Úr nevében megáldá a népet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'És osztogata minden Izráelitának, férfinak úgy, mint asszonynak egy-egy kenyeret, és egy-egy darab húst és egy-egy kalácsot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'És rendele az Úr ládája elé a Léviták közül szolgákat, a kik hirdessék, tiszteljék és dícsérjék az Urat, Izráel Istenét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'Asáf vala a fő, utána másodrenden Zakariás, Jéhiel, Semirámót, Jékhiel, Mattithja, Eliáb, Benája és Obed-Edom. Jéhiel lantokkal és cziterákkal, Asáf pedig czimbalmokkal énekel vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'Továbbá Benája és Jaháziel papok kürtölnek vala szüntelen az Isten szövetségének ládája előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'Azon a napon adott Dávid először éneket az Úrnak dícséretére Asáfnak és az ő atyjafiainak kezébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, 'Dícsérjétek az Urat, hívjátok segítségül az ő nevét, hirdessétek minden népek között az ő nagy dolgait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Énekeljetek néki, mondjatok dícséretet néki, beszéljetek minden csudálatos dolgairól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'Dicsekedjetek az ő szent nevében; örvendezzen szívök azoknak, a kik az Urat keresik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Keressétek az Urat és az ő erősségét; keressétek az ő orczáját szüntelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Emlékezzetek meg az ő csudálatos dolgairól, a melyeket cselekedett, az ő csudáiról és az ő szájának ítéletiről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'Óh Izráelnek, az ő szolgájának magva! Jákóbnak, az ő választottjának fiai!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'Ez az Úr, a mi Istenünk; az egész földön az ő ítéletei!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'Emlékezzetek meg örökké az ő szövetségéről, és az ő beszédéről, a melyet parancsolt, ezer nemzetségig;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'A melyet szerzett Ábrahámmal; és az Izsáknak tett esküjéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'Amelyet állíta Jákóbnak örök végzésül, Izráelnek örökkévaló szövetségül,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'Mondván: A Kanaán földét néked adom, hogy legyen néktek örökségtek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'Midőn ti számszerint kevesen valátok, igen kevesen, és zsellérek azon a földön;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'Mert járnak vala egyik nemzetségtől a másikhoz, és egyik országból más országba:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'Mégsem engedé senkinek őket bántani, sőt még a királyokat is megbünteté érettök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, 'Ezt mondván: Az én felkentjeimet ne bántsátok, prófétáimnak se ártsatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'Mind ez egész föld énekeljen az Úrnak, napról-napra hirdessétek az ő szabadítását.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'Beszéljétek a pogányok között az ő dicsőségét, minden népek között az ő csudálatos dolgait;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'Mert nagy az Úr és igen dícsérendő, és rettenetes minden istenek felett;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'Mert a pogányoknak minden isteneik csak bálványok, de az Úr teremtette az egeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'Dicsőség és tisztesség van ő előtte, erősség és vígasság az ő helyén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'Adjatok az Úrnak, népeknek nemzetségei, adjatok az Úrnak dicsőséget és erősséget!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'Adjatok az Úr nevének dicsőséget, hozzatok ajándékot, és jőjjetek eleibe, imádjátok az Urat a szentség ékességében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'Rettegjen az egész föld az ő orczájától; a föld kereksége is megerősíttetik, hogy ne ingadozzék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Örüljenek az egek, és örvendezzen a föld, és mondják a pogányok között: az Úr uralkodik!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'Zengjen a tenger és az ő teljessége; örvendezzen a mező és minden, a mi azon van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'Akkor örvendezni kezdenek az erdőnek fái az Úr előtt, mikor eljövend megítélni a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'Tiszteljétek az Urat, mert igen jó, mert örökkévaló az ő irgalmassága.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'És mondjátok: Tarts meg minket, mi szabadító Istenünk, gyűjts össze minket, és szabadíts meg a pogányoktól, hogy a te szent nevedet tisztelhessük, dicsekedhessünk a te dícséretedben!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'Áldott legyen az Úr, Izráel Istene öröktől fogva mindörökké! És monda a sokaság: Ámen! és dícséré az Urat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'Ott hagyá azért Dávid az Úr szövetségének ládájánál Asáfot és az ő atyjafiait, hogy a láda előtt szüntelen minden napon szolgáljanak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'Obed-Edomot és az ő hatvannyolcz atyjafiát (Obed-Edom pedig a Jedithun fia) és Hósát pedig ajtónállóknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'Sádók papot pedig és az ő pap atyjafiait, az Úr sátora előtt hagyá a magaslaton, mely Gibeonban vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'Hogy áldozzanak az Úrnak szüntelen égőáldozattal az égőáldozatnak oltárán minden reggel és estve, és hogy mindent a szerint cselekedjenek, a mint megiratott az Úr törvényében, melyet parancsolt vala az Izráelnek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'Hémánt is és Jédutunt velök hagyá, és többeket is választott, a kik nevök szerint megneveztettek, hogy az Urat dícsérjék, mert az ő irgalmassága örökkévaló.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'És ő velök Hémánt és Jédutunt kürtökkel, czimbalmokkal és az Isten énekének szerszámaival. A Jédutun fiait pedig kapunállókká tevé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'Akkor eltávozék az egész nép, kiki az ő házához. Dávid pedig visszatére, hogy az ő háznépét is megáldja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'Lőn pedig, mikor Dávid az ő házában ülne, monda Nátán prófétának: Ímé én czédrusfából csinált házban lakom, az Úr szövetségének ládája pedig kárpitok alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'Akkor monda Nátán Dávidnak: Valami a te szívedben van, cselekedd meg, mert az Isten veled leend.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'Azon éjjel pedig lőn az Istennek szava Nátánhoz, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, 'Menj el, és mondd meg az én szolgámnak, Dávidnak: Ezt mondja az Úr: Ne te építs nékem házat lakásul;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'Mert nem laktam én attól fogva házban, mióta az Izráel fiait kihoztam, mind e mai napig, hanem egy hajlékból más hajlékba mentem és sátorból sátorba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'A mely helyeken jártam az Izráel egész népével, szólottam-é vagy egyszer valakinek az Izráel birái közül (a kiknek parancsoltam vala, hogy az én népemet legeltessék), mondván: Miért nem csináltatok nékem czédrusfából házat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'Most azért ezt mondjad az én szolgámnak, Dávidnak: Ezt mondja a Seregek Ura: Én választottalak téged a juhok mellől a pásztorkunyhóból, hogy légy vezére az én népemnek, az Izráelnek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'És veled voltam mindenütt, valahová mentél, minden ellenségeidet is a te orczád elől elvesztettem, ennekfelette oly hírt szerzettem néked, a minemű hírök van a hatalmasoknak, a kik a földön vannak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'Lakóhelyet is adtam az én népemnek, az Izráelnek és elplántálám őt; és lakik az ő helyén, és ki nem mozdul többé, s nem fogják az álnokságnak fiai sanyargatni, mint azelőtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'És attól az időtől fogva, hogy megparancsoltam volt, hogy birák legyenek az én népem, az Izráel felett, minden te ellenségeidet megalázám, és azt is jelentém néked, hogy az Úr házat épít néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'És lészen, mikor betelnek a te életed napjai, hogy a te atyáidhoz elmenj, a te magodat feltámasztom te utánad, mely a te fiaid közül való lesz, és az ő országát megerősítem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'Ő épít nékem házat, és megerősítem az ő királyi székét mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'Én leszek néki atyja, ő pedig fiam lészen, és az én irgalmasságomat ő tőle el nem veszem, mint a hogy a te előtted valótól elvettem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'Hanem megerősítem őt az én házamban és az én országomban mindörökké, és az ő királyiszéke erős lesz mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'Mind e beszédek szerint és mind e látás szerint szóla Nátán Dávidnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'Beméne azért Dávid király, és leüle az Úr előtt, és monda: Ki vagyok én, óh Uram Isten, s micsoda az én házam is, hogy engemet eddig juttattál?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'Sőt még ez is kevés volt előtted, óh Isten! hanem ennekfelette szólál jövendőt is a te szolgád háza felől, és mint magas rangú embert, úgy tekintettél engemet, Úr Isten!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'És mit kérhetne Dávid többet te tőled, a te szolgádnak tisztességére, holott te jól ismered a te szolgádat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'Óh Uram, a te szolgádért és a te szíved szerint cselekedéd mind e nagy dolgokat, hogy kijelentéd mindezeket a csudálatos dolgokat,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, '(Óh Uram, nincsen senki hasonló hozzád, és nincsen Isten náladnál több), mind a szerint, a mint füleinkkel hallottuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'És kicsoda olyan, mint a te néped, az Izráel, egy nemzetség a földön, a melyért elment volna az Isten, hogy megváltaná magának népül; hogy magadnak nagy és rettenetes nevet szerezz, kiűzvén a pogányokat a te néped elől, a melyet Égyiptomból megszabadítál!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'És az Izráel népét a te népeddé tevéd mindörökké, és te Uram, nékik Istenök lettél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'Most azért Uram, a szó, a melyet szólál a te szolgád felől és az ő háza felől, erősíttessék meg mindörökké, és úgy cselekedjél, a mint szóltál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'Maradjon meg és magasztaltassék fel a te neved mindörökké, hogy mondhassák: A Seregek Ura az Izráel Istene, Istene Izráelnek; és Dávidnak, a te szolgádnak háza legyen állandó előtted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'Minthogy te, én Istenem, a te szolgádnak füle hallására megjelentetted, hogy néki házat csinálsz: ezokáért indula meg a te szolgád, hogy könyörgene előtted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'Most azért én Uram, te vagy az Isten, és te szólád e jó dolgot a te szolgád felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'Most azért tessék néked megáldani a te szolgádnak házát, hogy legyen állandó mindörökké előtted; mivelhogy te, Uram, megáldottad, legyen azért áldott mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'Ezek után pedig megveré Dávid a Filiszteusokat, és megalázá őket, és Gáth városát faluival együtt elvevé a Filiszteusok kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'A Moábitákat is megveré; és a Moábiták Dávidnak adófizető szolgái lettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'Továbbá megveré Dávid Hámátban Hadadézert is, Sóbának királyát, mikor elindult vala, hogy az Eufrátes folyóvízig vesse birodalmának határát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'Dávid pedig nyere ő tőle ezer szekeret és hétezer lovast és húszezer gyalogost; és minden szekeres lovaknak inait elvagdaltatá Dávid, és csak száz szekérbe valót tarta meg azokból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'És mikor eljövének Damaskusból a Siriabeliek, hogy megsegéllenék Hadadézert, a Sóba királyát: levága Dávid a Siriabeliek közül huszonkétezer férfit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'És rendele Dávid tiszttartókat Siriában, a hol Damaskus van; és lettek a Siriabeliek Dávidnak adófizető szolgái. És megsegíté az Úr Dávidot mindenütt, a merre csak ment.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'És vevé Dávid az arany paizsokat, a melyeket a Hadadézer szolgái viselének, és vivé Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'És hoza Dávid Tibhátból és Kúnból, a Hadadézer városaiból igen sok rezet. Abból csinálá Salamon a réztengert, az oszlopokat és a rézedényeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'Mikor meghallotta volna pedig Tóhu, a Hamáthbeli király, hogy Dávid megverte Hadadézernek, a Sóba királyának egész hadát:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'Küldé Dávid királyhoz az ő fiát, Hadorámot, hogy köszöntené őt és megáldaná, mivelhogy megharczolt vala Hadadézerrel és megverte vala őt; mert Tóhu is hadakozik Hadadézer ellen. És külde Dávidnak sok arany, ezüst és rézedényt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'És Dávid király ezeket is az Úrnak szentelé, az ezüsttel és az aranynyal együtt, a melyet nyert vala minden pogányoktól, az Edomitáktól, a Moábitáktól, az Ammon fiaitól, a Filiszteusoktól és Amálekitáktól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'Abisai pedig, a Séruja fia, az Edomiták közül a Sónak völgyében megvere tizennyolczezeret.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'És rendele Edomban Dávid tiszttartókat, és lettek az Edombeliek mind Dávidnak szolgái. És megsegíté az Úr Dávidot mindenütt, a merre csak ment.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'Így uralkodék Dávid az egész Izráel felett, és ítéletet és igazságot szolgáltat vala egész népének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'Joáb pedig, Séruja fia, a sereg előljárója volt, Jósafát, az Ahilud fia pedig emlékíró.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'Sádók, az Akhitub fia és Abimélek, az Abjátár fia, voltak a papok; Sausa az íródeák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'És Benája, a Jójada fia, a Kereteusok és Peleteusok előljárója volt; a Dávid fiai pedig elsők a király mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'Történt ezután, hogy meghalt Náhás, az Ammon fiainak királya, és uralkodék az ő fia helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'És monda Dávid: Minden jóval leszek a Náhás fiához, Hánunhoz; mert az ő atyja is jól tett volt velem. Ezért Dávid követeket külde ő hozzá, a kik vigasztalnák őt az ő atyjának halála miatt; és elmenének a Dávid szolgái az Ammon fiainak földére Hánunhoz, hogy őt vigasztalnák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'Akkor mondának az Ammon fiainak főemberei Hánunnak: Azt hiszed-é, hogy Dávid atyád iránti tiszteletből küldött hozzád vigasztalókat? Avagy nem azért jöttek-é az ő szolgái hozzád, hogy a földet megvizsgálják, elpusztítsák és kikémleljék?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'Megfogatá azért Hánun a Dávid szolgáit és azokat megnyiratá, és ruhájokat félig elmetszeté az ő derekukig, és úgy bocsátá el őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'Elmenének pedig és értesíték Dávidot, hogy mi történt a férfiakkal. És külde eléjök (mert azok a férfiak felette nagy gyalázattal illettettek vala) és ezt izené a király: Maradjatok Jérikhóban, míg szakállatok megnövénd, akkor jőjjetek hozzám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'Látván pedig az Ammon fiai, hogy tisztességtelen dolgot cselekedtek vala Dáviddal, küldének Hánun és az Ammon fiai ezer tálentom ezüstöt, hogy fogadjanak szekereket és lovagokat Mésopotámiából, siriai Maakából és Sóbából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'Fogadának azért magoknak harminczkétezer szekeret, Maakának királyát is az ő népével együtt, a kik eljövének és tábort járának Medeba előtt. Az Ammon fiai is összegyűlének az ő városaikból és jövének az ütközetre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'A mit mikor meghallott Dávid, elküldé Joábot és a vitézek egész seregét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'És az Ammon fiai kimenvén, csatarendbe állának a város kapuja előtt; a mely királyok pedig segítségre jöttek vala, külön valának a mezőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'Látván pedig Joáb, hogy mind elől, mind hátul ellenség állana, kiválaszta az egész Izráel harczosai közül egynéhányat, és a Siriabeliek ellen rendelé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'A nép többi részét pedig testvérére, Abisaira bízá, és ezek az Ammon fiaival állának szembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'És monda: Ha a Siriabeliek rajtam erőt vennének, légy segítségemre; ha pedig az Ammon fiai rajtad vennének erőt, én is megsegéllek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'Légy erős, sőt legyünk bátrak mindnyájan a mi népünkért és a mi Istenünk városaiért; az Úr pedig cselekedje azt, a mi néki tetszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'Harczra indula azért Joáb és az ő hada a Siriabeliek ellen, a kik ő előtte megfutamodának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'Az Ammon fiai pedig mikor látták, hogy megfutamodának a Siriabeliek: ők is megfutamodának Abisai elől az ő testvére elől, és a városba menekülének; Joáb pedig visszatért Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'Látván pedig a Siriabeliek, hogy az Izráel előtt megverettetének, követeket küldének és kihozatták a Siriabelieket, a kik a folyóvizen túl laknak vala, és Sófák, a Hadadézer seregeinek vezére volt az előljárójuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'Mikor pedig hírül adák Dávidnak, összegyűjté az egész Izráelt, és a Jordán vizén átmenvén, hozzájok érkezék és csatarendbe állott ellenök. És mikor csatarendbe állott Dávid a Siriabeliek ellen, ők is megütközének ő vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'De a Siriabeliek megfutamodának Izráel elől, és levága Dávid a Siriabeliek közül hétezer szekeret és negyvenezer gyalogot; annakfelette Sófákot, a sereg vezérét is megölé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'Mikor pedig látták a Hadadézer szolgái, hogy Izráel előtt legyőzetének: békét kötöttek Dáviddal és szolgálának néki, és nem akarák többször a Siriabeliek megsegélleni az Ammon fiait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'És lőn az esztendőnek fordulásával, mikor a királyok harczba menni szoktak, elindítá Joáb a hadat, és elpusztítá az Ammon fiainak földjét. És elmenvén megszállá Rabbát, (Dávid pedig Jeruzsálemben marada) és elfoglalá Joáb Rabbát és elrontá azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'És elvevé Dávid az ő királyuknak fejéről a koronát, mely egy tálentom arany súlyú vala, s melyben drágakövek valának. És Dávid fejére tette azt, s a városból is temérdek zsákmányt vitt el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'A város népét pedig kihozatá és fűrészszel vágatá, és vasboronákkal és fejszékkel. Így cselekedék Dávid az Ammon fiainak minden városával; azután megtére Dávid az egész néppel Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'Ezután ismét had támada Gézerben a Filiszteusok ellen; és akkor ölé meg a Husátites Sibbékai az óriások nemzetségéből való Sippait; és ilyen módon megaláztatának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'Ismét lőn had a Filiszteusok ellen, a melyben megölé Elhanán, a Jáir fia a Gáthbeli Lákhmit, a Góliát atyjafiát; és az ő dárdájának nyele hasonló vala a szövők zúgolyfájához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'Ezek után ismét versengés támadt Gáthban, hol egy magas ember vala, a kinek hat-hat, vagyis huszonnégy ujja volt; ez is óriás fia vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'És szidalommal illeté Izráelt, és megölé őt Jonathán, Dávid testvérének, Simeának fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, 'Ezek ugyanazon egy óriásnak fiai voltak Gáthban, a kik elveszének Dávidnak és az ő szolgáinak keze által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'Támada pedig a Sátán Izráel ellen, és felindítá Dávidot, hogy megszámlálja Izráelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'Monda azért Dávid Joábnak és a nép előljáróinak: Menjetek el, számláljátok meg Izráelt, Beersebától fogva Dánig: és hozzátok hozzám, hadd tudjam számát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'Akkor monda Joáb: Az Úr száz ennyivel szaporítsa meg az ő népét, a mennyien vannak. Avagy nem mind a te szolgáid-é azok, uram, király? S miért tudakozza ezt az én uram? Miért lenne Izráelnek büntetésére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'De a király szava erősebb volt a Joábénál. Elméne azért Joáb, és bejárta egész Izráelt; azután megtért Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'És megjelenté Joáb a megszámlált népnek számát Dávidnak. És volt az egész Izráel népének száma ezerszer ezer és százezer fegyverfogható férfi. A Júda fiai közül pedig négyszázhetvenezer fegyverfogható férfi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'A Lévi és Benjámin fiait azonban nem számlálta közéjök; mert sehogy sem tetszett Joábnak a király parancsolata.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'Sőt az Istennek sem tetszék e dolog, melyért meg is veré Izráelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'Monda pedig Dávid az Istennek: Igen vétkeztem, hogy ezt művelém: most azért bocsásd meg a te szolgád vétkét, mert felette esztelenül cselekedtem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'Akkor szóla az Úr Gádnak, a Dávid prófétájának, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, 'Eredj el, szólj Dávidnak ekképen: Ezt mondja az Úr: Három dolgot teszek elődbe, válaszsz magadnak azok közül egyet, hogy azt cselekedjem veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'Elméne azért Gád próféta Dávidhoz, és monda néki: Ezt mondja az Úr: válaszsz magadnak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'Vagy három esztendeig való éhséget, vagy hogy három hónapig emésztessél ellenségeid által és a te ellenséged fegyvere legyen rajtad; vagy az Úr fegyvere és a döghalál három napig kegyetlenkedjék földedben és az Úr angyala pusztítson Izráel minden határaiban! Azért lássad most, mit feleljek annak, a ki engem hozzád küldött.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'És monda Dávid Gádnak: Nagy az én szorongattatásom! Hadd essem inkább az Úr kezébe (mert igen nagy az ő irgalmassága) és ne essem emberek kezébe!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'Bocsáta azért az Úr döghalált Izráelre; és meghalának Izráel közül hetvenezeren.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'Bocsáta annakfelette angyalt az Úr Jeruzsálemre, hogy elpusztítaná azt. És mikor vágná a népet, meglátá az Úr és könyörüle az ő veszedelmökön; és monda a pusztító angyalnak: Elég immár, szünjél meg. Az Úrnak angyala pedig áll vala a Jebuzeus Ornánnak szérűjénél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'Akkor Dávid felemelé az ő szemeit, és látá az Úr angyalát állani a föld és az ég között, kivont kardja a kezében, a melyet Jeruzsálem ellen emelt vala fel. Leesék azért Dávid és a vének is, zsákba öltözvén, az ő orczájokra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'És monda Dávid az Istennek: Nemde nem én számláltattam-é meg a népet? Én vagyok, a ki vétkeztem és igen gonoszul cselekedtem! De ez a nyáj mit tett? óh én Uram Istenem forduljon ellenem a te kezed és az én házam népe ellen, és ne legyen a te népeden a csapás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'Akkor szóla az Úr angyala Gádnak, hogy megmondja Dávidnak, hogy menjen fel Dávid és építsen oltárt az Úrnak a Jebuzeus Ornán szérűjén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'Felméne azért Dávid a Gád beszéde szerint, melyet az Úr nevében szólott vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'Mikor pedig Ornán hátratekintvén, látta az angyalt, ő és az ő négy fia, a kik vele valának, elrejtőzének (Ornán pedig búzát csépel vala).');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'És juta Dávid Ornánhoz. Mikor pedig feltekintett vala Ornán, meglátta Dávidot, és kimenvén a szérűről, meghajtá magát Dávid előtt, arczczal a földre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'És monda Dávid Ornánnak: Add nékem e szérűhelyet, hogy építsek oltárt rajta az Úrnak; igaz árán adjad nékem azt, hogy megszünjék e csapás a népen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'Monda Ornán Dávidnak: Legyen a tied, és az én uram, a király azt cselekedje, a mi néki tetszik; sőt az ökröket is oda adom égőáldozatul, és fa helyett a cséplőszerszámokat, a gabonát pedig ételáldozatul; mindezeket ajándékul adom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'És monda Dávid király Ornánnak: Nem úgy, hanem igaz áron akarom megvenni tőled; mert a mi a tied, nem veszem el tőled az Úrnak és nem akarok égőáldozattal áldozni néki a máséból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'Ada azért Dávid Ornánnak a szérűért hatszáz arany siklust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'És építe ott oltárt Dávid az Úrnak, és áldozék égő- és hálaáldozatokkal és segítségül hívá az Urat, a ki meghallgatá őt, mennyből tüzet bocsátván az égőáldozat oltárára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'És parancsola az Úr az angyalnak; és betevé az ő kardját hüvelyébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'Abban az időben, mikor látta Dávid, hogy az Úr őt meghallgatta a Jebuzeus Ornán szérűjén, áldozék ott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, '(Az Úr sátora pedig, a melyet csinált vala Mózes a pusztában, és az égőáldozat oltára is akkor Gibeon magaslatán vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'És Dávid nem mehetett fel oda, hogy az Istent megengesztelje, mert igen megrettent volt az Úr angyalának kardjától.)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'Monda Dávid: Ez az Úr Istennek háza és az égőáldozatnak oltára Izráel számára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'Megparancsolá azért Dávid, hogy gyűjtsék össze az Izráel földén való jövevényeket, a kiket kővágókká tőn, hogy faragni való köveket vágnának, hogy az Isten házát megcsinálnák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'Továbbá sok vasat szerze Dávid szegeknek, az ajtókhoz és a foglalásokra; rezet is bőségesen minden mérték nélkül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'Számtalan czédrusfát is; mert a Sídon és Tírus városbeliek czédrusfákat bőségesen szállítának Dávidnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'Mert monda Dávid: Az én fiam, Salamon, gyermek és igen gyenge, az Úrnak pedig nagy házat kell építeni, mely híres legyen és ékesség az egész világon; elkészítek azért mindeneket néki. Dávid azért mindeneket nagy bőségesen megszerze, minekelőtte meghalna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'Hivatá azért Dávid az ő fiát, Salamont, és meghagyá néki, hogy az Úrnak, Izráel Istenének házat csináltasson.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'És monda Dávid Salamonnak: Édes fiam, én elgondoltam vala szívemben, hogy az Úrnak, az én Istenemnek nevének házat építsek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'De az Úr ekképen szóla nékem, mondván: Sok vért ontottál, és sokat hadakoztál; ne építs az én nevemnek házat, mert sok vért ontottál ki a földre én előttem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'Ímé fiad lészen néked, a kinek csendessége lészen, mert nyugodalmat adok néki minden körüle való ellenségeitől; azért neveztetik Salamonnak, mert békességet és nyugodalmat adok Izráelnek az ő idejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'Ő csinál az én nevemnek házat; ő lészen nékem fiam és én néki atyja leszek, és megerősítem az ő királyságának trónját Izráel felett mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'Most édes fiam legyen az Úr veled, hogy sikerüljön néked házat építeni az Úrnak, a te Istenednek, miképen szólott te felőled;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'De adjon az Úr néked értelmet és bölcseséget, mikor téged Izráel fölé helyez, hogy az Úrnak a te Istenednek törvényét megőrízzed.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'Akkor jól lesz dolgod, ha a rendeléseket és a végzéseket megtartod és teljesíted azokat, a melyeket az Úr Mózes által parancsolt volt Izráelnek. Légy bátor, légy erős, ne félj, és ne rettegj!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'Ímé én is az én szegénységemben szereztem az Úr házának építésére százezer tálentom aranyat és ezerszer ezer tálentom ezüstöt, és rezet, s vasat mérték nélkül, mert igen bőven van; fákat is, köveket is szerzettem; te is szerezz ezekhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'Van néked sok mívesed, kővágód, kő- és fafaragód és mindenféle dologban bölcs mesterembered.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'Az aranynak, ezüstnek, vasnak és réznek száma nincsen: azért kelj fel, láss hozzá, és az Úr legyen veled!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'Megparancsolá pedig Dávid Izráel összes főembereinek, hogy ők is legyenek segítségül az ő fiának, Salamonnak, ezt mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, 'Avagy nincsen-é az Úr a ti Istentek ti veletek, a ki néktek békességet adott köröskörül? Mert az én hatalmam alá adá e földnek lakosait, és meghódolt e föld az Úr előtt és az ő népe előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'No azért keressétek az Urat a ti Istenteket teljes szívetek és lelketek szerint, és felkelvén, az Úr Isten szentséges helyét csináljátok meg, hogy vigyétek az Úr szövetségének ládáját és az Istennek szentelt edényeket a házba, a mely építtetik az Úr nevének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'Megvénhedék pedig Dávid és mikor igen koros volna: királylyá tevé az ő fiát, Salamont Izráel felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'És összegyűjté Izráel összes fejedelmeit, a papokat és a Lévitákat is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'És megszámláltatának a Léviták, harmincz esztendőstől fogva, és a kik annál idősebbek valának; és azok száma fejenként, férfianként harmincznyolczezer volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, 'Ezek közül huszonnégyezeren az Úr háza teendőinek gondviselői valának, és hatezeren tiszttartók és birák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, 'Négyezeren ajtónállók; négyezeren pedig dícsérik vala az Urat minden zengő szerszámokkal, melyeket Dávid készíttetett a dícséretre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'És Dávid őket csoportokba osztá a Lévi fiai szerint: Gersonitákra, Kéhátitákra és Méráritákra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'A Gersoniták közül valók valának Lahdán és Simhi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'Lahdán fiai: Jéhiel a fő, Zétám és Joel hárman.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'És a Simhi fiai: Selómit, Hásiel és Hárán, hárman; ezek voltak a Lahdán családjának fejei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'Simhi fiai: Jahát, Zina, Jéus és Béria; ezek négyen voltak Simhi fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'Jahát volt a fő, Zina második: de Jéus és Béria, mivel nem sok fiakat nemzének, az ő családjukban csak egy ágnak vétettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'Kéhát fiai: Amrám, Ishár, Hebron és Uzziel, négyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'Amrám fiai: Áron és Mózes, Áron kiválasztatott, hogy felszenteltetnék a szentek szentje számára, ő és az ő fiai mindörökké, hogy jóillatot tennének az Úr előtt, és szolgálnának néki, s az ő nevében a népet megáldanák mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'Mózesnek, az Isten emberének fiai pedig számláltatának a Lévi nemzetségei közé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'Mózes fiai: Gerson és Eliézer.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'Gerson fiai: Sébuel a fő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'Eliézer fiai voltak: Rehábia a fő. Eliézernek nem volt több fia; de a Rehábia fiai igen megsokasodtak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'Ishár fiai: Selómit, a ki fő vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'Hebron fiai: Jéria a fő, Amárja második, Jaháziel harmadik és Jékámám negyedik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'Uzziel fiai: Mika a fő, és Isija második.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'Mérári fiai: Mákhli és Músi; Mákhli fiai: Eleázár és Kis.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'Meghala pedig Eleázár és nem voltak néki fiai, hanem leányai, a kiket a saját atyjokfiai, a Kis fiai vettek el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'Músi fiai: Mákhli, Eder és Jeremót, hárman.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'Ezek Lévi fiai családjaik szerint, a családfők, az ő megszámláltatásuk szerint, neveik száma szerint fejenként, a kik az Úr házában szolgáltak, húsz éves korban és azon felül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'Mert ezt mondotta vala Dávid: Az Úr, az Izráel Istene nyugodalmat adott az ő népének, és Jeruzsálemben lakozik mindörökké;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'Azért a Lévitáknak sem kell többé hordozni az Isten hajlékát, s mindazokat az eszközöket, a melyek az ő szolgálatához valók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'Annakokáért Dávidnak utolsó rendelése szerint megszámláltattak a Lévi fiai, húsz éves korban és azon felül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'Mert az ő helyök az Áron fiai mellett van, hogy szolgáljanak az Úr házában és annak pitvaraiban, kamaráiban, és mindenféle szent edények tisztítása és az Isten házának szolgálatja által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'És hogy gondot viseljenek a szent kenyerekre, az ételáldozathoz való lisztlángra, a kovász nélkül való lepényekre, a serpenyőben főttre és pirítottra, minden mértékre és mérőre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'És hogy álljanak az Úrnak tiszteletére és dícséretére, úgy reggel, mint este;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'És hogy áldozzanak az Úrnak minden égőáldozattal, minden szombaton, a hónapok első napjain és a szokott ünnepeken bizonyos szám szerint, a mint szükség vala, szüntelen az Úr előtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'És hogy szorgalmasan őrizzék a gyülekezet sátorát, őrizzék a szenthelyet, és hogy vigyázzanak az ő atyjokfiainak, az Áron fiainak szolgálatjánál az Úr házában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'Az Áron fiainak is voltak rendjeik. Áron fiai: Nádáb, Abihú, Eleázár és Itamár.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Nádáb és Abihú még atyjuk előtt meghaltak és fiaik nem valának, azért Eleázár és Itamár viselék a papságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'És elosztá őket Dávid és Sádók, ki az Eleázár fiai közül vala, és Ahimélek, ki az Itamár fiai közül vala, az ő tisztök szerint a szolgálatra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'Eleázár fiai között pedig több főember találtaték, mint az Itamár fiai között, mikor eloszták őket. Az Eleázár fiai között családjaik szerint tizenhat főember volt; az Itamár fiai közül, családjaik szerint, nyolcz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'Eloszták pedig őket sors által válogatás nélkül, mert a szenthelynek fejedelmei és Istennek fejedelmei valának úgy az Eleázár, mint az Itamár fiai közül valók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'És beírá őket Semája, a Nétanéel fia, a Lévi nemzetségéből való íródeák, a király előtt és a fejedelmek előtt, Sádók pap előtt; Ahimélek előtt, ki Abjátár fia vala, és a papoknak és Lévitáknak családfői előtt. Egy család sorsoltatott az Eleázár és egy az Itamár nemzetségéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'Esék pedig az első sors Jojáribra; a második Jedájára;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'Hárimra a harmadik; Seórimra a negyedik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'Málkijára az ötödik; Mijáminra a hatodik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'Hakkósra a hetedik; Abijára a nyolczadik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'Jésuára a kilenczedik; Sekániára a tizedik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'Eliásibra a tizenegyedik; Jákimra a tizenkettedik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'Huppára a tizenharmadik; Jésebeábra a tizennegyedik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'Bilgára a tizenötödik; Immérre a tizenhatodik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'Hézirre a tizenhetedik; Hápisesre a tizennyolczadik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'Petáhiára a tizenkilenczedik; Jéhezkelre a huszadik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'Jákinra a huszonegyedik; Gámulra a huszonkettedik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'Delájára a huszonharmadik; Maáziára a huszonnegyedik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'Ez az ő hivatalos rendjök szolgálatukban, hogy bejárnának az Úr házába sorban, az ő atyjoknak Áronnak rendelése szerint, a mint megparancsolta volt néki az Úr, Izráel Istene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'A mi Lévi többi fiait illeti: az Amrám fiai közül vala Subáel; a Subáel fiai közül Jehdéja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'A mi illeti Rehábiát: a Rehábia fiai közül Issija vala fő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'Az Ishár fiai közül Selómót; és a Selómót fiai közül Jahát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, 'A Hebron fiai közül első vala Jérija, Amárja második, Jaháziel harmadik, Jekámhám negyedik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'Uzziel fiai: Mika; a Mika fiai közül Sámir.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'Mika atyjafia Issija; Issija fiai közül Zekáriás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'Mérári fiai: Mákhli és Músi; Jaázija fia, Bénó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'Mérárinak Jaázijától, az ő fiától való fiai: Sohám, Zakkúr és Hibri.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'Mákhlitól vala Eleázár, és ennek nem valának fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'Kistől: a Kis fiai közül való volt Jérakhméel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'Músi fiai: Mákhli, Eder és Jérimót. Ezek a Léviták fiai az ő családjaik szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'Ezek is sorsot vetének az ő atyjokfiaival az Áron fiaival együtt Dávid király előtt, Sádók és Ahimélek előtt, és a papok és Léviták családfői előtt, a fő a kisebbekkel egyformán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'Dávid és a sereg fővezérei a szolgálatra kijelölék az Asáf, Hémán és Jédutun fiait, hogy prófétáljanak cziterákkal, lantokkal és czimbalmokkal. Azok száma, a kik e szolgálatra rendeltettek, az ő szolgálatuk szerint:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'Az Asáf fiai közül: Zakkúr, József, Nétánia és Asaréla, az Asáf fiai Asáf mellett, a ki a király mellett prófétál vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'A Jédutun fiai közül: A Jédutun fiai Gedália, Séri, Jésája, Hasábia, Mattithia és Simei, hatan cziterával az ő atyjok Jédutun mellett, a ki az Úr tiszteletére és dícséretére prófétál vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'A Hémán fiai közül: Hémán fiai: Bukkija, Mattánia, Uzziel, Sébuel, Jérimót, Hanánia, Hanáni, Eliáta, Giddálti, Romámti-Ezer, Josbekása, Mallóti, Hótir, Maháziót.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'Ezek mind Hémán fiai, a ki az Isten beszédeiben a király látnoka a hatalom szarvának emelésére. Az Isten Hémánnak tizennégy fiút és három leányt ada.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'Ezek mindnyájan az ő atyjuk mellett valának, a kik az Úr házában énekelnek vala czimbalmokkal, lantokkal és cziterákkal az Isten házának szolgálatában, a királynak, Asáfnak, Jédutunnak és Hémánnak parancsolata szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'Ezeknek száma testvéreikkel együtt, a kik jártasok valának az Úr énekében, mindnyájan tudósok, kétszáznyolczvannyolcz vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'És sorsot vetének a szolgálat sorrendjére nézve, kicsiny és nagy, tanító és tanítvány egyaránt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'És esék az első sors az Asáf fiára, Józsefre; Gedáliára a második. Ő és testvérei tizenketten valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'A harmadik Zakkúrra, kinek fiai és testvérei tizenketten valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'Negyedik Jisrire esék, kinek fiai és testvérei tizenketten valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'Ötödik Nétániára, kinek fiai és testvérei tizenketten valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'Hatodik Bukkijára, kinek fiai és testvérei tizenketten valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'Hetedik Jésarelára, kinek fiai és testvérei tizenketten valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'Nyolczadik Jésájára, kinek fiai és testvérei tizenketten valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'Kilenczedik Mattániára, kinek fiai és testvérei tizenketten valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'Tizedik Simeire, kinek fiai és testvérei tizenketten valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'Tizenegyedik Azárelre, kinek fiai és testvérei tizenketten valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'Tizenkettedik Hasábiára, kinek fiai és testvérei tizenketten valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'Tizenharmadik Subáelre, kinek fiai és testvérei tizenketten valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'Tizennegyedik Mattithiára, kinek fiai és testvérei tizenketten valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'Tizenötödik Jérimótra, kinek fiai és testvérei tizenketten valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'Tizenhatodik Hanániára, kinek fiai és testvérei tizenketten valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'Tizenhetedik Josbekására, kinek fiai és testvérei tizenketten valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'Tizennyolczadik Hanánira, kinek fiai és testvérei tizenketten valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'Tizenkilenczedik Mallótira, kinek fiai és testvérei tizenketten valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'Huszadik Eliátára, kinek fiai és testvérei tizenketten valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'Huszonegyedik Hótirra, kinek fiai és testvérei tizenketten valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'Huszonkettedik Giddáltire, kinek fiai és testvérei tizenketten valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'Huszonharmadik Maháziótra, kinek fiai és testvérei tizenketten valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'Huszonnegyedik Romámti-Ezerre, kinek fiai és testvérei tizenketten valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'Az ajtónállók rendje ez: A Kóriták közül Meselémiás, a Kóré fia, a ki az Asáf fiai közül való volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'A Meselémiás fiai közül elsőszülött Zekária, Jédiáel második, Zebádia harmadik és Játniel negyedik,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'Elám ötödik, Jóhanán hatodik, Eljehoénai hetedik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'Obed-Edom fiai közül: Semája elsőszülött, Józabád második, Jóah harmadik, Sákár negyedik, Nétanéel ötödik,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'Ammiel hatodik, Issakhár hetedik, Pehullétai nyolczadik, mert az Isten megáldotta vala őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'Az ő fiának, Semájának is születtek fiai, a kik családjukban uralkodtak, mert erős vitézek valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'Semája fiai: Othni, Refáel, Obed, Elzabád, kinek testvérei igen erős férfiak valának, Elihu és Sémákiás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Ezek mindnyájan Obed-Edom fiai közül valók; mind ő magok, mind fiaik és testvéreik derék férfiak valának, erősek a szolgálatra; hatvanketten Obed-Edomtól valók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'Meselémiásnak is fiai és testvérei tizennyolczan erős férfiak valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'Hósának is, a Mérári fiai közül, valának fiai, kik között Simri volt a fő, nem mintha elsőszülött volna, hanem mivel az ő atyja őt akará választani főnek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'Hilkiás a második, Tebáliás a harmadik, Zekária negyedik; mindnyájan a Hósa fiai és testvérei, tizenhárman.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'Ezek között osztaték el az ajtónállás tiszte a főemberek által, hogy az ő atyjokfiaival együtt vigyáznának és szolgálnának az Úr házában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'És sorsot vetének kicsiny és nagy egyaránt az ő családjaik szerint mindenik kapura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'És esék a napkelet felé való kapunak őrizete sors szerint Selémiásra; Zekáriára pedig, az ő fiára, a ki bölcs tanácsadó vala, mikor sorsot vetének, esék az északi kapu sors szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'Obed-Edomnak a déli kapu; az ő fiainak pedig a kincstartó ház.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'Suppimnak és Hósának a napnyugotra való kapu, a Salléketh kapuval együtt a felmenő töltésen, egyik őrizőhely szemben a másikkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'Napkelet felé vala hat Lévita; észak felé minden napra négy; délre is minden napra négy; a kincstartó háznál kettő-kettő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'A külső részen napnyugat felé: négy a felmenő töltésen, kettő a külső rész felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'Ezek az ajtónállók csoportjai a Kóriták és Méráriták közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'A Léviták közül: Ahija volt az Isten háza kincsének, és az Istennek szentelt kincsnek főgondviselője.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'A Lahdán fiai, Gersoniták fiai Lahdántól; a Lahdán családfői, Gersonita Jéhiéli.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'Jéhiéli fiai: Zétám és Joel az ő testvére, a kik az Úr háza kincseinek valának gondviselői.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'Az Amrám, Ishár, Hebron és Aziel nemzetségéből valók is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'Sébuel pedig Gersonnak, a Mózes fiának fia a kincs főgondviselője volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'Az ő atyjafiai pedig, Eliézertől valók, ezek: Rehábiás az ő fia, kinek fia Jésáia, kinek fia Jórám, kinek fia Zikri, kinek fia Selómit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'Ez a Selómit és az ő testvérei valának gondviselői minden megszentelt kincsnek, a melyet Dávid király, a nemzetségek fejedelmei, az ezredesek, századosok és a hadakozó nép fejedelmei szenteltek vala Istennek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'A melyet a hadban való zsákmányból szenteltek vala az Úr házának építésére,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'És a mit csak szentelt Sámuel próféta, és Saul, a Kis fia, és Abner, a Nér fia, és Joáb, a Séruja fia; és bárki szentelt is valamit Istennek: mind Selómitnak és az ő testvéreinek gondviselése alatt volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'Az Isháriták közül Kenániás és az ő fiai Izráel külső dolgaival bízattak meg, mint tiszttartók és birák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'A Hebroniták közül Hasábiás és testvérei igen erős férfiak, ezeren és hétszázan valának, a kik Izráel népe között, a Jordán vizén túl napenyészetre, gondviselők voltak az Úr minden dolgában és a király szolgálatjában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'A Hebroniták között Jerija vala a fő (a Hebroniták nemzetségeik és családjaik szerint megkerestetének a Dávid királyságának negyvenedik esztendejében és találtak bátor férfiakat Gileád-Jaézerben).');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'És az ő atyjafiai, erős férfiak, kétezerhétszázan valának, családfők; a kiket Dávid király gondviselőkké tett a Rubenitákon és Gáditákon és Manasse félnemzetségén, mind az Istennek, mind a királynak minden dolgaiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'Ezek az Izráel fiai szám szerint, családfők, ezredesek, századosok és előljáróik azoknak, a kik a király szolgálatában állottak a seregek minden dolgaiban, a kik be- és kimennek hónapról-hónapra az egész esztendőn át; a seregek egyenként huszonnégyezer emberből állának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'Az első csapatnak vezére az első hónapban Jasobeám, a Zabdiel fia vala, mely csapat huszonnégyezerből állott;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'Ő a Péres fiai közül való volt és vezére az első hónapra rendelt sereg minden előljárójának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'A második csapatnak vezére a második hónapban Dódai Ahohites vala és az ő csapatja; és Miklót az előljáró. Az ő csapatja is huszonnégyezerből állott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'A harmadik seregnek a harmadik hónapban Benája volt a vezére, a ki Jójada főpapnak volt a fia; az ő csapatja is huszonnégyezerből állott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'Ez a Benája hős volt a harmincz között, sőt a harmincz felett való volt. Csapatjának előljárója az ő fia, Ammizabád vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'A negyediknek vezére a negyedik hónapban Asáel vala, a Joáb testvére és utána az ő fia, Zebádia. Az ő csapatja is huszonnégyezerből állott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'Az ötödiknek vezére az ötödik hónapban Jizráhites Samhut vala. Az ő csapatja is huszonnégyezerből állott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'A hatodiknak vezére a hatodik hónapban a Tékoabeli Ira volt, az Ikkés fia. Az ő csapatja is huszonnégyezerből állott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'A hetediknek vezére a hetedik hónapban a Pélonbeli Héles vala, az Efraim fiai közül. Az ő csapatja is huszonnégyezerből állott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'A nyolczadiknak vezére a nyolczadik hónapban a Husátbeli Sibbékai vala, a Zárhiták közül. Az ő csapatja is huszonnégyezerből állott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'A kilenczediknek vezére a kilenczedik hónapban az Anatótbeli Abiézer vala, a Benjáminiták közül. Az ő csapatja is huszonnégyezerből állott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'A tizediknek vezére a tizedik hónapban a Nétófátbeli Maharai vala, a Zárhiták közül. Az ő csapatja is huszonnégyezerből állott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'A tizenegyediknek vezére a tizenegyedik hónapban a Pirathonbeli Benája vala, az Efraimiták közül. Az ő csapatja is huszonnégyezerből állott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'A tizenkettediknek vezére a tizenkettedik hónapban a Nétófátbeli Héldai vala, Othniel nemzetségéből való. Az ő csapatja is huszonnégyezerből állott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'Izráel nemzetségei között, a Rubeniták előljárója Eliézer, a Zikri fia; a Simeonitáké Sefátiás, a Maaka fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'Lévinek Hasábia, a Kémuel fia; Áronnak Sádók;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'Júdának Elihu, a Dávid atyjafiai közül; Izsakhárnak Omri, a Mikáel fia;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'Zebulonnak Ismája, az Obádiás fia; Nafthalinak Jérimót, Azriel fia;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'Efraim fiainak Hósea, az Azáziás fia; a Manasse félnemzetségének Jóel, a Pedája fia;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'Manasse Gileád földén való félnemzetségének Iddó, a Zekáriás fia; Benjáminnak Jaasiel, az Abner fia;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'Dánnak Azaréel, a Jérohám fia. Ezek valának az Izráel nemzetségeinek fejedelmei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'Nem számláltatá meg pedig Dávid azokat, a kik húsz esztendőn alól valának; mert az Úr megigérte, hogy megsokasítja Izráelt, mint az égnek csillagait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'Joáb, a Séruja fia megkezdé a számlálást, de véghez nem vivé, mivelhogy e miatt Istennek haragja támadt Izráel ellen. Ez okból a szám nem vétetett fel a Dávid király krónikájának száma közé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'A király kincsének gondviselője vala Azmávet, az Adiel fia; a mezőkön, a városokban, a falvakban, a várakban való kincseknek pedig Jónatán, az Uzziás fia volt a gondviselője;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'A föld művelésére rendelt mezei munkások felett volt Ezri, a Kélub fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'A szőlőmívesek felett volt a Rámátbeli Simei, és a szőlőkben levő boros tárházak felett a Sifmitbeli Zabdi;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'Az olajfák és a mezőn való fügefák mívesei felett a Gideritbeli Baálhanán; az olajos tárházak felett Joás;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'A Sáron mezején legelő barmok felett a Sáronbeli Sitrai; a völgyekben legelő barmok felett pedig Sáfát, az Adlai fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'A tevék felett az Ismáel nemzetéből való Obil; a szamarak felett a Méronótbeli Jehdéja;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'A juhok felett a Hágárénus Jaziz. Mindnyájan ezek valának a Dávid király jószágainak gondviselői.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'Jónatán, a Dávid nagybátyja főtanácsos vala, a ki értelmes és írástudó ember volt. Jéhiel, a Hakhmóni fia pedig a király fiaival vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'Akhitófel is a királynak tanácsosa volt. Arkites Khúsai pedig a király barátja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'Akhitófel után volt Jójada, a Benája fia, és Abjátár; a király hadának fővezére pedig Joáb.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'Egybehívatá pedig Dávid Jeruzsálembe az Izráel összes fejedelmeit, a nemzetségek fejedelmeit, a király szolgálatában levő csapatok előljáróit, az ezredeseket, a századosokat, a király minden jószágának és marhájának gondviselőit, a maga fiait is, udvariszolgáival, a harczosokat minden erős vitézivel egyetemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'És felálla Dávid király az ő lábaira, és monda: Halljátok meg szómat atyámfiai és én népem! Elvégezém szívem szerint, hogy az Úr szövetsége ládájának nyugodalmas házat csináltatnék és a mi Istenünk lábainak zsámolyt; hozzá is készítettem mindent az építéshez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'De az Isten monda nékem: Ne te csinálj házat az én nevemnek; mert hadakozó ember vagy, sok vért is ontottál immár.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'Engem választa az Úr, Izráel Istene az én atyámnak egész házából, hogy lennék királya az Izráel népének mindörökké; mert Júdát választotta előljárónak és a Júda törzsében az én atyámnak háznépét; az én atyámnak fiai közül pedig engem méltóztatott királylyá tenni egész Izráel felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'És minden fiaim közül (mert az Úr sok fiakat adott nékem) választotta Salamont az én fiamat, hogy ülne az Úr királyságának székében Izráel felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'És monda nékem: Salamon a te fiad építi meg az én házamat és az én pitvarimat; mert én őt magamnak fiamul választottam, és én is néki atyja leszek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'Megerősítem az ő királyságát mindörökké; ha az én parancsolatimat és ítéletimet szorgalmatosan megtartándja, a mint e mai napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'Most azért az egész Izráelnek, az Úr gyülekezetének szeme előtt és a mi Istenünk hallására: őrizzétek s keressétek az Úrnak a ti Istenteknek minden parancsolatit, hogy bírhassátok e jó földet, és hogy örökségül hagyhassátok fiaitokra is magatok után mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'Te azért, fiam, Salamon, ismerd meg a te atyád Istenét, és szolgálj néki tökéletes szívvel és jó kedvvel; mert az Úr minden szívbe belát és minden emberi gondolatot jól ért. Hogyha őt keresénded, megtalálod; ha ellenben őt elhagyándod, ő is elhagy téged mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'Most azért, mivelhogy az Úr választott téged, hogy néki szent házat építs: légy erős és készítsd meg azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'Akkor átadá Dávid az ő fiának, Salamonnak a tornácznak, annak házacskáinak, kincstartó helyeinek, felházainak és belső kamaráinak, a kegyelem táblája helyének is formáját,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'És mindennek formáját, a melyeket szívében elgondolt vala, az Úr házának pitvarai felől, az Isten háza kincsének és a szent kincseknek számára köröskörül levő minden kamarák felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'A papok és Léviták csapatjainak háza, az Úr háza szolgálatának minden munkája és az Úr háza szolgálatára való minden eszköz felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'Azután aranyat mérték szerint, a különböző szolgálatok eszközei számára; mértékkel minden ezüst eszközök és a különböző szolgálatok eszközei számára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'Vagyis aranyat mértékkel az arany gyertyatartókra és azok arany szövétnekére, mértékkel mindenik gyertyatartóra és annak szövétnekire, s az ezüst gyertyatartókra mértékkel, a gyertyatartóra és annak szövétnekire, mindegyik gyertyatartó rendeltetése szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'És aranyat mértékkel, a szent kenyerek asztalai, minden asztal számára, azonképen ezüstöt az ezüst asztalok számára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'A villákra, medenczékre és kancsókra tiszta aranyat; az arany poharakra is bizonyos mérték szerint ada aranyat, minden pohárra; és az ezüst poharakra ezüstöt bizonyos mértékkel, minden pohárra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'A füstölő oltár számára megtisztított aranyat mérték szerint; aranyat a szekérnek azaz a Kéruboknak mintázására, a kik kiterjesztett szárnyakkal az Úr szövetségének ládáját befedezik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, 'Mindezek az Úr kezétől írattattak meg, a ki engem megtanított az egész alkotmány formájára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'Monda ezek után Dávid Salamonnak, az ő fiának: Légy bátor és erős, és kezdj hozzá, semmit ne félj és ne rettegj; mert az Úr Isten, az én Istenem veled lészen, téged el nem hagy, tőled el sem távozik, míglen elvégzed az Úr háza szolgálatának minden művét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'Ímé, itt vannak a papok és Léviták csapatjai az Isten házának minden szolgálatára, veled lesznek minden munkában készségesen bölcseséggel, a fejedelmek is és az egész nép minden dolgaidra nézve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'Azután monda Dávid király az egész gyülekezetnek: Ím látjátok, hogy egyedül az én fiamat Salamont választotta Isten, a ki még gyermek és gyenge; a munka pedig nagy, mert nem emberé lészen az a ház, hanem az Úr Istené.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'Én pedig teljes tehetségem szerint az én Istenem háza számára bőségesen szereztem aranyat az arany szerszámokra, ezüstöt az ezüst szerszámokra, rezet a rézre, vasat a vasra, fákat a fákra, ónyxköveket, foglalni való köveket, veres köveket, különb-különbszínű köveket; mindenféle drágaköveket; márványköveket is bőséggel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'Ezenfölül, mivel nagy kedvem van az én Istenem házához, a mi kincsem, aranyam és ezüstöm van, oda adom az én Istenem házának szükségére, azok mellett, a melyeket szereztem a szentház számára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, 'Háromezer tálentom aranyat Ofir aranyából és hétezer tálentom tiszta ezüstöt, a házak falainak beborítására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'Aranyat az arany szerszámokra, ezüstöt az ezüstre és minden szükségre, a mesteremberek kezéhez. És ha valaki még adni akar, szabad akaratja szerint, töltse meg az ő kezét ma és adjon, a mit akar az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'Azért szabad akaratjok szerint adának ajándékokat az atyák fejedelmei, az Izráel nemzetségeinek fejedelmei, az ezredesek, századosok és a király dolgainak fejedelmei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'És adának az Isten házának szükségére ötezer tálentom aranyat és tízezer dárikot; tízezer tálentom ezüstöt és tizennyolczezer tálentom rezet és százezer tálentom vasat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'És valakinél drágakövek találtatának, adák az Úr házának kincséhez, a Gersoniták közül való Jéhiel kezébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'És örvendeze a sokaság, hogy szabad akaratjokból adának; mert tiszta szívökből adakozának az Úrnak; Dávid király is nagy örömmel örvendezett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'Hálákat ada azért Dávid az Úrnak az egész gyülekezet előtt, és monda Dávid: Áldott vagy te, Uram, Izráelnek, a mi atyánknak Istene, öröktől fogva mind örökké!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'Oh Uram, tied a nagyság, hatalom, dicsőség, örökkévalóság és méltóság, sőt minden, valami a mennyben és a földön van, tied! Tied, oh Uram, az ország, te magasztalod fel magadat, hogy légy minden fejedelmek felett!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'A gazdagság és a dicsőség mind te tőled vannak, és te uralkodol mindeneken; a te kezedben van mind az erősség és mind a birodalom; a te kezedben van mindeneknek felmagasztaltatása és megerősíttetése.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'Most azért, oh mi Istenünk, vallást teszünk előtted, és dícsérjük a te dicsőséges nevedet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'Mert micsoda vagyok én, és micsoda az én népem, hogy erőnk lehetne a szabad akarat szerint való ajándék adására, a mint tettünk? Mert tőled van minden, és a miket a te kezedből vettünk, azokat adtuk most néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'Mert mi csak jövevények vagyunk te előtted és zsellérek, a mint a mi atyáink is egyenként; a mi életünk napjai olyanok e földön, mint az árnyék, melyben állandóság nincsen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'Oh mi Urunk Istenünk! mind ez a gazdagság, a mit gyűjtöttünk, hogy néked és a te szent nevednek házat építsünk, a te kezedből való és mindazok tiéid!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'Jól tudom, oh én Istenem, hogy te a szívet vizsgálod és az igazságot szereted. Én mindezeket tiszta szívemből, nagy jó kedvvel adtam, s látom, hogy a te néped is, a mely itt jelen van, nagy örömmel, szabad akaratja szerint adta ezeket néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'Oh Uram, Ábrahámnak, Izsáknak és Izráelnek, a mi atyáinknak Istene, tartsd meg mindörökké ezt az érzést a te néped szívében, és irányítsd az ő szívöket te feléd!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'Salamonnak pedig, az én fiamnak adj tökéletes szívet, hogy a te parancsolatidat, bizonyságtételeidet és rendelésidet megőrizhesse, s hogy mindazokat megcselekedhesse, s felépíthesse azt a házat, a melyet én megindítottam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'És szóla Dávid az egész gyülekezethez: Kérlek, áldjátok az Urat, a ti Isteneteket. Áldá azért az egész gyülekezet az Urat, az ő atyáik Istenét; s leborulván, tisztelék az Urat és a királyt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'És áldozának az Úrnak áldozatokkal, és áldozának egészen égőáldozatokkal az Úrnak másnapon, ezer tulkot, ezer kost, ezer bárányt italáldozataikkal, és sokféle áldozatokkal az egész Izráelért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'S evének és ivának az Úr előtt azon a napon nagy vígasságban. Azután Salamont, a Dávid fiát másodszor is királylyá tevék és felkenék őt az Úrnak, hogy lenne fejedelem; Sádókot is fölkenék a főpapságra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'És üle Salamon az Úr székébe, mint király az ő atyjának, Dávidnak helyében, és mindenben szerencsés vala, mert engedelmeskedék néki az egész Izráel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'A fejedelmek és a hatalmasok, sőt a Dávid király fiai is mindnyájan kezet adának, hogy Salamon királynak engedelmeskedni fognak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'És igen felmagasztalá az Úr Salamont mind az egész Izráel népe előtt, és oly királyi méltóságot szerzett néki, a melyhez hasonló egy királynak sem volt ő előtte Izráelben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'Így uralkodott Dávid, az Isai fia az egész Izráel felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'Az idő pedig, a melyben uralkodék Izráel felett, negyven esztendő. Hebronban uralkodék hét esztendeig, Jeruzsálemben pedig harminczháromig uralkodék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'És meghala jó vénségben, életével, gazdagságával és minden dicsőségével megelégedve. És uralkodék az ő fia, Salamon helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'Dávid királynak pedig úgy első, mint utolsó dolgai, ímé megirattak a Sámuel próféta könyvében és a Nátán próféta könyvében és a Gád próféta könyvében;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'Az ő egész országlásával, hatalmasságával és mind azzal, a mi az ő idejében történt vele, Izráellel és a föld minden országaival.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'Megerősödék királyságában Salamon, a Dávid fia; és az Úr az ő Istene vele volt, és őt igen felmagasztalá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'És szóla Salamon az egész Izráel népének, ezredeseknek, századosoknak, a bíráknak és egész Izráel minden előljáróinak és a családfőknek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'Hogy elmennének Salamon és az egész gyülekezet ő vele a magaslatra, mely Gibeonban vala; mert ott volt az Isten gyülekezetének sátora, melyet Mózes, az Úr szolgája csinált vala a pusztában;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, 'De az Isten ládáját Dávid már felvitte volt Kirját-Jeárimból arra a helyre, melyet készített számára Dávid; mert sátort állított fel számára Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'A rézoltár azonban, melyet Bésaléel, az Uri fia csinált, a ki a Huri fia volt, ott volt az Úr sátora előtt; felkeresé tehát azt Salamon és a gyülekezet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'És áldozék ott Salamon a rézoltáron az Úr előtt, mely a gyülekezetnek sátorában vala, áldozék azon ezer égőáldozatot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'Azon éjszaka megjelenék az Isten Salamonnak, és monda néki: Kérj a mit akarsz, hogy adjak néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'És monda Salamon az Istennek: Te nagy irgalmasságot cselekedtél az én atyámmal, Dáviddal; és ő helyette engemet királylyá tettél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'Most, oh Uram Isten, legyen állandó a te beszéded, melyet szólottál volt az én atyámnak, Dávidnak; mert te választottál engem királylyá e nép felett, mely oly sok, mint a földnek pora.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'Most azért adj nékem bölcseséget és tudományt, hogy a te néped előtt mind ki-, mind bemehessek; mert vajjon kicsoda kormányozhatja ezt a te nagy népedet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'Akkor monda az Isten Salamonnak: Minthogy ez volt a te szívedben, és nem kértél tőlem gazdagságot, kincset és tisztességet, avagy a téged gyűlölőknek lelkét, sem hosszú életet magadnak nem kértél, hanem kértél magadnak bölcseséget és tudományt, hogy kormányozhasd az én népemet, mely felett királylyá tettelek téged:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'A bölcseséget és a tudományt megadtam néked, sőt gazdagságot, kincset és tisztességet is olyat adok néked, a melyhez hasonló nem volt sem az előtted, sem az utánad való királyoknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'És visszatére Salamon Jeruzsálembe a Gibeon hegyéről, a gyülekezet sátora elől és uralkodék az Izráelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'Szerze Salamon szekereket és lovagokat; és vala néki ezernégyszáz szekere és tizenkétezer lovagja, a kiket helyheztete a szekerek városaiba és Jeruzsálembe a király mellé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'És felhalmozá a király az ezüstöt és aranyat, mint a köveket, Jeruzsálemben; a czédrusfákat is felhalmozá, mint a vadfügefákat, melyek a lapályon nagy tömegben vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'És Salamonnak hoznak vala lovakat Égyiptomból; mert a király kereskedői sereggel vették volt meg a lovakat szabott áron.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'És mikor feljőnek vala, hozának Égyiptomból egy szekeret hatszáz ezüst siklusért, egy-egy lovat százötven ezüst siklusért; és ugyan csak ők szállították ezeket a Hitteusok minden királyainak és Siria királyainak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'Elvégezé Salamon magában, hogy az Úr nevének házat építene, és magának királyi palotát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'És rendele Salamon hetvenezer férfit teherhordásra, nyolczvanezer férfit favágásra a hegyen; háromezerhatszáz felügyelőt azokhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'És külde Salamon a tírusbeli Hirám királyhoz, mondván: A mint az én atyámmal, Dáviddal cselekedtél, a kinek küldöttél czédrusfákat, hogy építene magának házat, melyben laknék;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'Úgy én az én Uram Istenem nevének akarok házat építeni, hogy néki szenteljem, és abban füstölő szerekkel jó illatot gerjeszszek, hogy folytonosan szent kenyerek álljanak előtte, s minden reggel és este égőáldozatot áldozzak szombatnapokon, az új holdnak napjain, és az Úrnak a mi Istenünknek szentelt ünnepeken, melyeket örökké kell cselekedniök az Izráelitáknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'A ház pedig, a melyet építeni szándékozom, igen nagy lesz, mert a mi Istenünk nagyobb minden isteneknél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'De kinek volna annyi ereje, hogy néki házat csinálhatna? Az ég és az egeknek egei őt be nem foghatják, s ki vagyok én is, hogy néki házat csinálhassak? hanem hogy csak jóillatot tegyenek abban ő előtte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'Most azért küldj hozzám tudós mesterembert, a ki tudjon készíteni aranyból, ezüstből, rézből, vasból, bíborból, karmazsinból és kék bíborból; a ki tudjon metszéseket metszeni az én mesterembereimmel együtt, a kik Júdában és Jeruzsálemben vannak, a kiket az én atyám, Dávid szerzett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'Annakfelette küldj czédrusfákat, fenyőfákat és ébenfákat a Libánusról, mert tudom, hogy a te szolgáid tudják vágni a Libánusnak fáit; és ímé az én szolgáim is a te szolgáiddal lesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'Hogy készítsenek nékem sok fát, mert a ház, a melyet építek, nagy és csudálatos lészen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'És ímé a munkásoknak, a favágóknak, a te szolgáidnak adok húszezer véka cséplett búzát és húszezer véka árpát, húszezer báth bort és húszezer báth olajat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'Felele pedig Hírám, a Tírus királya levélben, melyet külde Salamonnak: Mivelhogy az Úr szerette az ő népét, azért adott téged nékik királyul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'Ismét monda Hírám: Áldott az Úr, az Izráel Istene, a ki mind a mennyet, mind a földet teremtette; a ki ilyen bölcs, tudós, okos és értelmes fiat adott volt Dávid királynak, a ki mind az Úrnak házat, mind magának királyi palotát akar építeni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'Ímé küldöttem azért bölcs, tudós és értelmes férfit, a ki az én atyámé, Húrámé volt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'A Dán nemzetségének leányai közül való asszony fiát (és az ő atyja Tírus városából való), a ki tud készíteni aranyból, ezüstből, rézből, vasból, kövekből, fákból, bíborból, kék bíborból, lenből és karmazsinból és mindenféle metszést metszeni és minden remekművet elkészíteni, a melyekkel megbízatik, a te tudós mesterembereiddel és az én uramnak, Dávid királynak, a te atyádnak tudós mestereivel egyben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'Azért most, a mely búzát, árpát, olajat és bort igért az én uram, küldje el az ő szolgáinak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'Mi pedig a Libánuson vágunk fát, a mennyire néked szükséged lesz, és elviszszük azokat szálakon a tengeren Joppéhoz, és te onnét vitessed Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'Megszámláltata azért Salamon minden idegen férfit az Izráel földén, az ő atyjának, Dávidnak megszámláltatása után és találtatának százötvenháromezerhatszázan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 18, 'És választa azok közül hetvenezer teherhordót, favágásra pedig a hegyen nyolczvanezeret; pallérokul, a kik a népet szorgalmaztatnák, rendele háromezerhatszázat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'Elkezdé építtetni Salamon az Úr házát Jeruzsálemben a Mórija hegyén, mely Dávidnak, az ő atyjának megmutattatott, azon a helyen, melyet készített vala Dávid a Jebuzeus Ornán szérűjén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'Elkezdé pedig az építést a második hónap második napján, királyságának negyedik esztendejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'És ilyen alapot vetett Salamon az Isten házának építésénél: hosszúsága a régi mérték szerint vala hatvan sing, szélessége húsz sing.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'És a tornácz a templom hosszában, a ház szélessége szerint, húsz sing volt, a magassága pedig százhúsz sing; és beborítá azt belől tiszta aranynyal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'A derék házat pedig megbélelteté fenyőfákkal és finom aranynyal borítá be, melyen pálmafákat és lánczokat metszete.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'És beborította a házat drágakövekkel ékességül, és az arany Párvaimból való arany volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'És beboríttatá a háznak gerendáit, ajtómellékit, falait és annak ajtait is aranynyal; és metszete a háznak falaira Kérubokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'Megcsináltatá a szentek-szentjét is, melynek hosszasága a derék háznak szélességével arányban húsz sing, szélessége is húsz sing volt, és beboríttatá azt hatszáz tálentom finom aranynyal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'A szegeknek súlya ötven arany siklus volt. A felső helyiségeket is beboríttatá aranynyal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'És csináltatott a szentek-szentjébe két Kérubot is, szoborműveket, és beboríták azokat aranynyal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'A Kérubok szárnyainak hosszúsága húsz sing vala; egyik szárnya öt sing, és a háznak falát érinté; a másik szárnya is öt sing és a másik Kérub szárnyát érinté.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'A másik Kérubnak szárnya is, a mely öt sing volt, a háznak falát érinté; a másik szárnya pedig, a mely ismét öt sing volt, a másik Kérub szárnyát érinté.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'Úgy, hogy a Kérubok szárnyai húsz singnyire valának kiterjesztve; lábaikon állának, és arczuk befelé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'Annakfelette függönyt is csináltata, kék és piros bíborból és karmazsinból és lenből, melyre Kérubokat csináltatott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'Két oszlopot is csináltata a ház előtt, a melyeknek hossza harminczöt sing vala, és gömböt felül mindenikre, a mely öt sing vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'És csináltatott lánczokat is, mint a belső részben, s az oszlopok tetejére helyhezteté; és száz gránátalmát is csináltatott, s a lánczokba helyhezteté.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'És felállítá ez oszlopokat a templom előtt: egyiket jobbfelől, a másikat balfelől. És nevezé a jobbfelől valót Jákinnak, a balfelől valót pedig Boáznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'Csináltatott rézoltárt is, melynek hosszúsága húsz sing, szélessége is húsz sing, magassága pedig tíz sing vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'Csináltatott öntött tengert is, mely egyik szélétől fogva a másik széléig tíz sing vala, köröskörül kerek, és öt sing magas, és harmincz sing zsinór érte be a kerületit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'Az alatt ökör alakok valának köröskörül, tíz lévén egy singnyire, a melyek kört alkotának a tenger körül; az ökör alakok két renddel valának öntve ugyanazon öntésből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'Tizenkét ökrön állott; három északra fordulva, három nyugotra, három délre és három napkeletre, és a tenger felül vala rajtok, hátuk pedig mind befelé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'Vastagsága egy tenyérnyi volt, és karimája olyan, mint a pohár ajaka, vagy a liliom virága; és háromezer báth fért belé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'Csináltatott annakfelette tíz mosdómedenczét, és ötöt helyheztete jobbkéz felől, ötöt pedig balkéz felől, hogy azokban mossanak, mossák azt, a mi áldozatra való; a tenger pedig a végre vala, hogy abban mosakodjanak a papok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'Csináltatott tíz arany gyertyatartót is, az utasítás szerint, és helyhezteté a templomban, ötöt jobbkéz felől, ötöt balkéz felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'Csináltatott tíz asztalt is, a melyeket helyheztete a templomban, ötöt jobbkéz felől, ötöt balkéz felől; csináltatott száz arany medenczét is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'Megcsináltatá a papok pitvarát is és a nagy tornáczot; és ajtókat a tornáczra, s azok ajtait rézzel borítá be.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'A tengert pedig helyhezteté jobbkéz felől napkeletre, délnek ellenébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'Húrám fazekakat, lapátokat és medenczéket is csinált. És elvégezé Húrám a mívet, a melyet csinálnia kellett Salamon királynak, az Isten házában;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'Tudniillik a két oszlopot és a két kerek gömböt a két oszlop tetejére, és a két hálót a két kerek gömb befedezésére, a melyek az oszlopok tetején valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'És négyszáz gránátalmát a két hálóra; két rend gránátalmát minden hálóba a két kerek gömb befedezésére, a melyek az oszlopok tetején valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'Csinála talpakat is, és azokra mosdómedenczéket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'Egy tengert és tizenkét ökröt az alá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'Fazekakat, lapátokat és villákat. Mindezen eszközöket Húrám az ő atyja tiszta rézből csinálta Salamon királynak az Úr háza számára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'A Jordán mezején önteté azokat a király az agyagos földben, Sukkót és Seredáta között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'Mindezen eszközöket Salamon nagy mennyiségben csináltatá, mert nem tekinték a réznek súlyát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'És megcsináltata Salamon minden egyéb felszerelést is, mely az Úr házához szükséges volt: az arany oltárt és az asztalokat, a melyeken a szent kenyerek voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'A gyertyatartókat és azoknak szövétnekeit is, hogy égjenek azok rendeltetésök szerint a szentek-szentje előtt, finom aranyból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'Azok virágait, szövétnekeit és hamvvevőit is aranyból, és pedig tiszta aranyból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'És az ollókat, medenczéket, tálakat és tömjénezőket finom aranyból, és a ház kapuját, a szentek-szentjéhez való bejárat belső ajtóit és a templom házának belső ajtóit aranyból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'És elvégezteték az egész mű, a melyet Salamon király csinála az Úr házához. És bevivé Salamon Dávidtól, az ő atyjától, Istennek szenteltetett jószágot, az ezüstöt, aranyat és az összes edényeket, és helyhezteté azokat az Isten házának kincsei közé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'Akkor Salamon összegyűjté az Izráel véneit és a nemzetségek összes fejedelmeit és az Izráel háznépének fejedelmeit Jeruzsálembe, hogy felvigyék az Úr szövetségének ládáját a Dávid városából, a mely a Sion.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'És felgyűlének Izráelnek minden férfiai a királyhoz, a hetedik hónak ünnepén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'Mikor pedig eljöttek volna mindnyájan az Izráel vénei: felvevék a Léviták a ládát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'És felvivék a ládát, a gyülekezet sátorát és minden szent edényeket, a melyek a sátorban valának; felvivék azokat a papok és Léviták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'Salamon király pedig és az Izráel egész gyülekezete, a mely ő hozzá gyűlt, megy vala a láda előtt, áldozván juhokkal és ökrökkel, a melyek meg sem számláltathatnának, sem meg nem irattathatnának sokaságuk miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'És bevivék a papok az Úr szövetségének ládáját az ő helyére, az Isten házának belső részébe, a szentek-szentjébe, a Kérubok szárnyai alá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'A Kérubok pedig szárnyaikat kiterjesztik vala a láda felett, és befedezik vala a Kérubok a ládát és annak rúdjait felülről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'Azután kijebb vonták annak rúdjait, úgy hogy a rudaknak végei láthatók valának a ládán kivül, a legbelső rész felől, de kivülről nem voltak láthatók. És ott volt mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'Nem volt egyéb a ládában, hanem csak Mózes két táblája, melyeket ő a Hóreb hegyén tett vala abba, a mikor az Úr szövetséget kötött Izráel fiaival, mikor kijövének Égyiptomból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'Lőn pedig, mikor a papok kijöttek a szent helyből, (mert a papok mindnyájan, a kik ott valának, magokat megszentelték vala és akkor nem kellett megtartaniok az ő sorrendjöket,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'Annakokáért az énekes Léviták mind, a mennyien valának, Asáf, Hémán, Jedutun, az ő fiaik és testvéreik fehér ruhákban, czimbalmokkal, lantokkal és cziterákkal állanak vala napkelet felől az oltárnál és ő velök százhúsz kürtölő pap;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'Mert a kürtölőknek és éneklőknek tisztök vala egyenlőképen zengeni az Úrnak dícséretére és tiszteletére.) És mikor nagy felszóval énekelnének kürtökkel, czimbalmokkal és mindenféle zengő szerszámokkal, dícsérvén az Urat, hogy ő igen jó és örökkévaló az ő irgalmassága: akkor a ház, az Úrnak háza megtelék köddel,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'Annyira, hogy meg sem állhattak a papok az ő szolgálatjukban a köd miatt, mert az Úr dicsősége töltötte vala be az Istennek házát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Akkor monda Salamon: Az Úr mondotta, hogy ő lakoznék ködben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'Én pedig lakóházat építettem néked, helyet, a hol örökké lakjál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'Azután megfordult a király, és megáldá Izráel egész gyülekezetét; és Izráel egész gyülekezete felállott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'És monda: Áldott az Úr, Izráel Istene, ki szólott volt az ő szája által az én atyámnak, Dávidnak, és hatalmas kezeivel beteljesítette, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, 'Attól a naptól fogva, a melyen kihozám az én népemet Égyiptom földéből, soha nem választottam egyetlen várost sem az Izráel minden nemzetségei közül, hogy házat építenének, a melyben lenne az én nevem, sem férfit nem választottam, hogy az én népemnek Izráelnek vezére lenne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'Hanem Jeruzsálemet választottam, hogy az én nevem abban lenne, és választám Dávidot, hogy vezére lenne az én népemnek, Izráelnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'Ámbár az én atyám, Dávid elvégezé magában, hogy házat építene az Úrnak, Izráel Istenének,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'De az Úr azt mondotta Dávidnak, az én atyámnak: Azt, hogy arra gondoltál, hogy az én nevemnek házat építs, jól tetted, hogy szívedben ezt elvégezted;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'Mégis nem te építesz házat nékem, hanem a te fiad, a ki a te ágyékodból származik, ő épít az én nevemnek házat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'És beteljesíté most az Úr az ő beszédét, a melyet szólott; mert felkelék az én atyám Dávid helyett, és ülék az Izráel királyi székébe, a mint az Úr megmondotta volt; és megépítém a házat az Úrnak, Izráel Istene nevének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'És abba helyeztem a ládát, a melyben az Úrnak szövetsége van, melyet szerzett volt az Izráel fiaival.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'És oda állott Salamon az Úr oltára elé, az Izráel egész gyülekezetével szemben, és kezeit kiterjesztette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'Salamon pedig egy széket csináltatott vala rézből, a melyet a tornácznak közepén helyeztetett el, melynek hossza öt sing, szélessége is öt sing, magassága pedig három sing vala. Felálla abba, és térdeire esvén az egész Izráel gyülekezete előtt, kezeit az ég felé kiterjeszté,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'És monda: Oh Uram, Izráelnek Istene, nincsen hozzád hasonló Isten sem mennyben, sem földön, a ki megtartod a te fogadásodat és irgalmasságodat a te szolgáidhoz, a kik te előtted teljes szívvel járnak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'Ki megtartottad a te szolgádnak, az én atyámnak, Dávidnak, a mit szólottál néki; mert te magad szólottál, és kezeiddel beteljesítéd, a mint e mai napon megtetszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'Most azért, oh Uram, Izráelnek Istene, tartsd meg, a mit a te szolgádnak, Dávidnak, az én atyámnak igértél, mondván: Nem fogy el előttem a te magodból való férfiú, a ki az Izráelnek királyiszékiben üljön; csakhogy a te fiaid őrizzék meg az ő útjokat, hogy az én törvényemben járjanak, mint te én előttem jártál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'Most azért, oh Uram, Izráelnek Istene, bizonyosodjék meg a te beszéded, melyet szólottál volt a te szolgádnak, Dávidnak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, '(Avagy lakozhatnék-é valósággal az Isten e földön az emberek között? Ím az egek és az egeknek egei téged be nem foghatnak, mennyivel kevésbbé e ház, a melyet én építettem.)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'És tekints a te szolgád könyörgésére és imádságára, oh én Uram Istenem, meghallgatván kiáltását és könyörgését, a melylyel könyörög a te szolgád előtted!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'Hogy a te szemeid éjjel és nappal figyelmezzenek e házra, e helyre, a melyről azt mondottad, hogy nevedet abba helyezénded, meghallgatván könyörgését a te szolgádnak, a mikor e helyen könyörögne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'Hallgasd meg azért a te szolgádnak és a te népednek Izráelnek könyörgését, a mikor könyörögni fognak e helyen; hallgasd meg a te mennyei lakhelyedből, és meghallgatván őket, légy kegyelmes!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Mikor valaki vétkezéndik felebarátja ellen, és esküre köteleztetik, hogy megesküdjék, és ő ide jő, megesküszik oltárod előtt ebben a házban,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'Te hallgasd meg a mennyből és vidd véghez, és tégy igaz ítéletet a te szolgáid között, az istentelent megbüntetvén, fejére fordítván az ő útját; és az igazat megigazítván, megfizetvén néki az ő igazsága szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'Mikor pedig megverettetik a te néped, az Izráel az ő ellenségeitől, mivel te ellened vétkeztek; és hozzád visszatérve vallást tesznek a te nevedről, könyörögnek és imádkoznak te előtted e házban:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'Te hallgasd meg a mennyből, és bocsásd meg a te népednek, az Izráelnek bűnét, és hozd vissza őket arra a földre, a melyet adtál nékik és az ő atyáiknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Mikor az ég berekesztetik és nem lészen eső, mivel vétkeztek te ellened; és imádkozni fognak e helyen és vallást tesznek a te nevedről és megtérnek bűneikből, mert te sanyargatod őket:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'Te hallgasd meg a mennyből, és légy kegyelmes a te szolgáidnak és a te népednek, az Izráelnek; minekutána őket megtanítándod az igaz útra, a melyen járjanak; és adj esőt a te földedre, a melyet adtál a te népednek örökségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'Éhség ha lesz a földön, ha döghalál, aszály, ragya, sáska, cserebogár; ha az ő ellensége szorongatja az ő birodalmának földében; ha bármiféle csapás és nyomorúság jövend reájok:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'A ki akkor könyörög és imádkozik, legyen az bárki; vagy a te néped, az Izráel, ha elismeri kiki az ő csapását és fájdalmát, és kezeit e házban kiterjeszténdi:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'Te hallgasd meg a mennyből, a te lakhelyedből és légy kegyelmes, és kinek-kinek fizess az ő útai szerint, a mint megismerted az ő szívét, mert egyedül csak te ismered az emberek fiainak szívét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'Hogy féljenek téged, járván a te útaidon, míg élnek e föld színén, a melyet adtál volt a mi atyáinknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'Sőt még az idegent is, a ki nem a te néped, az Izráel közül való, ha eljövend messze földről a te nagy nevedért és a te hatalmas kezedért és a te kiterjesztett karodért, mikor ide jutván, könyörögnek e házban:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'Te hallgasd meg a mennyből, a te lakóhelyedből, és add meg az idegennek mindazt, a miért könyörög hozzád, hogy megismerjék a földnek minden népei a te nevedet, és tiszteljenek téged úgy, mint a te néped, az Izráel, és ismerjék meg, hogy a te nevedről neveztetik e ház, a melyet én építettem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Ha a te néped hadba megy ki az ő ellensége ellen azon az úton, a melyen elbocsátod őket; ha könyörögnek, hozzád fordulván e város felé, a melyet választottál magadnak, és e ház felé, a melyet a te nevednek építettem:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'Te hallgasd meg az égből az ő könyörgésöket és imádságukat, és szerezz nékik igazságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'Ha vétkeznek ellened (mert nincsen ember, a ki nem vétkeznék) és reájok megharagudván, az ellenség kezébe adándod és őket fogságba viendik azok, a kiktől megfogattak, messze földre vagy közelre,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'És ha az idegen földön, a hol fogva tartatnak, magokba szállnak, és megtérvén, az ő fogságuk helyén könyörögnek hozzád, és ezt mondandják: Vétkeztünk, hamisan és gonoszul cselekedtünk;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'És megtérendenek te hozzád teljes szívökből és teljes lelkökből az ő fogságuk földében, a hol őket fogva tartják, és könyörögnek hozzád, az ő földjüknek útja felé fordulva, a melyet adtál volt az ő atyáiknak, és e város felé, a melyet választottál magadnak, és e ház felé, a melyet a te nevednek építettem:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'Hallgasd meg akkor az ő könyörgésöket és imádságukat a mennyből, a te lakhelyedről, és szerezz nékik igazságot, és bocsásd meg a te népednek, hogy ellened vétkezett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'Most azért, oh én Istenem, legyenek a te szemeid nyitva és füleid legyenek figyelmesek a könyörgésre ezen a helyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'És most kelj fel, oh Úr Isten, a te nyugodalmadba, te és a te hatalmasságodnak ládája! A te papjaid, oh Úr Isten, öltöztessenek fel üdvösséggel, és a te szenteid örvendezzenek a jóban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'Oh Úr Isten, ne utáld meg a te felkenetett királyod orczáját; emlékezzél meg Dávidhoz, a te szolgádhoz való nagy irgalmasságaidról!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'És mikor Salamon elvégezte a könyörgést, tűz szálla le az égből, és megemészté az egészen égőáldozatot és a véres áldozatot, és az Úr dicsősége betölté a házat,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'Annyira, hogy még a papok sem mehettek be az Úr házába; mert az Úr dicsősége betölté az Úr házát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'És az Izráel fiai mindnyájan látták, a mikor alászálla a tűz és az Úr dicsősége a házra, és arczczal leborulának a föld felé a padlózatra, s imádák és tisztelék az Urat, hogy jó és az ő kegyelme mindörökké való!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'A király pedig és az egész nép áldoznak vala áldozatokat az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'Áldozék Salamon király áldozatot huszonkétezer ökörrel és százhúszezer juhval; és ekképen szentelék fel az Úr házát a király és az egész nép.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'A papok pedig foglalatosok valának az ő tisztökben; a Léviták is az Úrnak minden zengő szerszámaival, a melyeket Dávid király készíttetett, hogy az Urat dícsérnék (mert örökkévaló az ő irgalmassága) a Dávid dicséretivel mely kezökbe adatott; a papok pedig trombitálának velök szemben, míg az egész Izráel ott álla.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'És felszentelé Salamon a középső pitvart, a mely az Úrnak háza előtt vala; mert ott szerze égőáldozatokat és hálaadóáldozatok kövéreit; mert a rézoltárra, a melyet Salamon készíttete, nem fér vala az égőáldozat, az ételáldozat és a hálaadóáldozat kövére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'És Salamon ünnepet szerze ebben az időben hét napig, és vele együtt az egész Izráel, nagy gyülekezet, mely összegyülekezék Hámáttól fogva az Égyiptom patakáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'A nyolczadik napon pedig gyülekezést tartának, mert az oltár felszentelését hét napon át végezték és az ünnepet is hét napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'A hetedik hónapnak huszonharmadik napján elbocsátá a népet sátoraikba, vígan és megelégedve mindama jók felett, a melyeket cselekedett az Úr Dáviddal, Salamonnal és az ő népével Izráellel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'És Salamon bevégezé az Úr házát és a királyi palotát, s mindazt, a mit magában elhatározott Salamon, hogy megcsinál az Úr házában és a maga házában; szerencsésen bevégezé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'Megjelenék pedig az Úr Salamonnak azon éjjel, s monda néki: Meghallgattam a te könyörgésedet, és e helyet magamnak áldozat házául választottam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Ímé, a mikor az eget bezárandom, hogy ne legyen eső; és a mikor parancsolok a sáskának, hogy a földet megemészsze; vagy a mikor döghalált bocsátandok az én népemre:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'És megalázza magát az én népem, a mely nevemről neveztetik, s könyörög és keresi az én arczomat, és felhagy az ő bűnös életmódjával: én is meghallgatom őket a mennyből, megbocsátom bűneiket, és megszabadítom földjüket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'Most már az én szemeim nyitva lesznek, és füleim figyelmesek lesznek e helyen a könyörgésre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'Most választottam és megszenteltem e házat, hogy az én nevem abban legyen mindörökké, és ott lesznek az én szemeim és az én szívem mindenkor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'És ha te előttem járándasz, a mint járt Dávid, a te atyád, úgy cselekedvén mindenekben, a mint neked megparancsoltam, s az én rendelésimet és ítéletimet megtartándod:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'Megerősítem a te birodalmad trónját, a mint megigértem volt Dávidnak, a te atyádnak, mondván: Nem vétetik el a te nemzetségedből való férfiú az Izráel királyiszékiből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'De hogyha ti elszakadtok, s rendelésimet és parancsaimat, a melyeket előtökbe adtam, elhagyjátok, s elmenvén, idegen isteneknek szolgálandotok és azok előtt meghajoltok:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'Kiszaggatom őket az én földemből, a melyet adtam volt nékik: és ezt a házat, a melyet az én nevemnek szenteltem, orczám elől elvetem; tanulságul és példabeszédül adom őket minden nemzetségnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'És ezen a házon, a mely felséges vala, minden elmenő álmélkodni fog, és azt mondja: Miért cselekedett így az Úr ezzel az országgal és ezzel a házzal?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'És azt felelik: Azért, mert elhagyták az Urat, atyáik Istenét, a ki őket kihozta volt Égyiptom földéből, és idegen istenekhez hajlottak, azokat imádták és azoknak szolgáltak; azért hozta reájok mind e veszedelmet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'Lőn pedig húsz esztendő mulva, a mi alatt Salamon megépíté az Úr házát és a maga palotáját:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'Azokat a városokat, a melyeket Hirám adott Salamonnak, megépíté Salamon, és Izráel fiait telepíté oda.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'Azután elméne Salamon Hámát-Sobába és azt hatalmába keríté.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'És megépíté Tádmort a pusztában, és minden kincstartó városokat, a melyeket Hámátban épített.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'Annakfelette mind a felső, mind az alsó Bethoront megépíté s megerősített városokká tette kőfalakkal, kapukkal és zárokkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'És Baalátot, s a tárházak minden városait, a melyek Salamonéi valának, a szekereknek és a lovagoknak minden városait; és mindent, a mihez Salamonnak kedve volt, megépíté Jeruzsálemben, a Libánuson és az ő egész birodalmának földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'Mindazt a népet, a mely megmaradt a Hitteusok közül, az Emoreusok, Perizeusok, Hivveusok és a Jebuzeusok közül, a kik nem az Izráel közül valók;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'Hanem azoknak fiai közül, a kik azon a földön ő utánok maradtak volt, a kiket az Izráel fiai ki nem irthattak, azokat Salamon adófizetőkké tevé mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'De az Izráel fiai közül Salamon senkit nem tett szolgává az ő külső dolgaiban; mert ezek hadakozó férfiak voltak, és az ő hadnagyinak vezérei, s szekereinek és lovagjainak vezérei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'Azok, a Salamon király seregeinek vezérei, kétszázötvenen valának, a kik uralkodnak vala a népen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'És felviteté Salamon a Faraó leányát a Dávid városából a házba, a melyet néki épített vala; mert ezt mondá: Nem lakhatik az én feleségem az Izráel királyának, Dávidnak házában; mert szentséges hely az, mivel az Úr ládája abba vitetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Akkor égőáldozatokat áldozék Salamon az Úrnak az Úr oltárán, a melyet rakatott vala a tornácz előtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'Naponként áldozának azon, Mózes parancsolatja szerint, szombatnapokon, a hónapok első napjain, és évenként a főünnepeken háromszor; tudniillik a kovásztalan kenyerek ünnepén, a hetek ünnepén és a sátorok ünnepén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'És elrendelé az ő atyjának, Dávidnak rendelése szerint a papok tisztét az ő szolgálatjokban, a Lévitákat is az ő tisztök szerint, hogy dícsérnék az Istent és szolgálnának a papok mellett naponként; az ajtónállókat is, az ő csoportjaik szerint minden kapuhoz, mert így volt az Isten emberének, Dávidnak parancsolatja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'És nem tértek el a király parancsolatjától, a melyet parancsolt vala a papoknak és Lévitáknak minden dolog és a kincsek felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'Ilyen módon bevégződött Salamonnak minden munkája azon naptól, a mikor az Úr házának alapját letették, annak befejezéséig, a mikor immár az Úr háza elkészült.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Azután elméne Salamon Esiongáberbe és Elótba, a mely a tenger partján, Edom földén volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'És külde Hirám az ő szolgái által néki hajókat és szolgákat, a kik a tengeren jártasok valának, a kik menének a Salamon szolgáival együtt Ofirba, honnan négyszázötven tálentom aranyat hozának és vivék Salamon királynak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'A Séba királynéasszonya pedig hallván Salamon hírét, eljöve, hogy megkisértse Salamont nehéz kérdésekkel, Jeruzsálembe, igen nagy sereggel és tevékkel, a melyek hoznak vala fűszereket, igen sok aranyat és drágaköveket; és Salamonhoz méne, és beszélt vele mindenekről, a melyek szívén voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'És Salamon megfelelt minden beszédeire, mert semmi sem volt Salamon elől elrejtve, a melyet meg nem mondhatott volna néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'És mikor látta Séba királynéasszonya Salamon bölcseségét és a házat, a melyet épített vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'És az ő asztalának étkeit, szolgáinak lakását és hivatalnokainak állását és öltözékeiket, pohárnokait s azoknak öltözékeit, és az ő áldozatát, a melylyel az Úrnak házában áldozott: a lélekzete is elállott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'És monda a királynak: Mind igaz volt, a mit hallottam volt az én lakóföldemben a te dolgaidról és bölcseségedről;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'De hinni sem akartam azoknak beszédeit, míg én magam el nem jöttem és szemeimmel nem láttam. És ímé nékem a felét sem beszélték el a te bölcseséged nagyságának; felülmúltad a hírt, a melyet hallottam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Boldogok a te embereid és boldogok ezek a te szolgáid, a kik szüntelen udvarlanak néked, hogy hallhatják a te bölcseségedet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'Legyen az Úr, a te Istened áldott, a ki téged annyira szeretett, hogy az ő székébe helyezett, hogy lennél az Úrnak, a te Istenednek királya; mivel a te Istened szerette Izráelt, hogy megerősítse őt mindörökké, azért tett téged királylyá felettök, hogy szolgáltass ítéletet és igazságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'És ada a királynak százhúsz tálentom aranyat és felette sok fűszerszámot és drágaköveket. Nem is volt több olyan fűszerszám, mint a milyet Séba királynéasszonya ada Salamon királynak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, 'És Hirám szolgái is és Salamon szolgái is, a kik hoztak vala aranyat Ofirból; hoztak ébenfát és drágaköveket is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'És csinála a király az ébenfából lépcsőket az Úr házába és a király házába, s cziterákat és lantokat az éneklőknek. Ezekhez hasonlókat nem láttak azelőtt Júda országában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'Salamon király pedig ada a Séba királynéasszonyának mindent, a mit csak kivánt és kért tőle, azonkivül, a mit ő a királynak hozott. Azután megtére és méne az ő földébe mind ő, mind az ő szolgái.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'Vala pedig mértéke az aranynak, a mely esztendőnként bejő vala Salamonnak, hatszázhatvanhat tálentom arany,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'Azonkivül, a mit hoznak vala a kalmárok és kereskedők; de még Arábia minden királyai és annak a földnek fejedelmei és hoznak vala aranyat és ezüstöt Salamonnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'És csináltata Salamon király kétszáz paizst vert aranyból, mindenik paizsra hatszáz vert arany siklus ment fel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'Háromszáz kerek paizst is vert aranyból; mindenik paizsra háromszáz arany siklus megy vala, a melyeket a király helyeztete a Libánon erdejének házába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'És csináltatott a király egy nagy királyiszéket elefántcsontból, és beboríttatá azt finom aranynyal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'Hat lépcsője volt a széknek, és arany zsámolya a székhez erősítve, és támaszai valának mindkét felől az ülés mellett, és két oroszlán állott a karok mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'És tizenkét oroszlán áll vala ott a hat lépcsőn mindkét felől. Senki soha olyant nem csinált egyetlen országban sem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'És Salamon királynak összes ivóedényei aranyból valának; a Libánon erdő házának is összes edényei tiszta aranyból valának; nem vala az ezüstnek semmi becse a Salamon idejében;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'Mert hajói voltak a királynak, a melyek Társisba jártak a Hirám szolgáival együtt. Minden három esztendőben egyszer menének a hajók Társisba, honnan aranyat, ezüstöt, elefántcsontot, majmokat és pávákat hoznak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'És felülmúlta Salamon király e földnek minden királyait gazdagságban és bölcseségben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'És e földnek minden királyai kivánnak vala szembe lenni Salamonnal, hogy hallhatnák az ő bölcseségét, a melyet Isten adott vala az ő szívébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'És azok mindnyájan ajándékot visznek vala néki, arany és ezüst edényeket, ruhákat, fegyvert, fűszerszámokat, lovakat és öszvéreket esztendőnként.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'És Salamonnak négyezer lóistállói, szekerei és tizenkétezer lovagjai valának, a kiket helyheztete a szekerek városaiba és a király mellé Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'És uralkodó vala minden király felett az Eufrátes folyóvíztől a Filiszteusok földéig és az Égyiptom határáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'És a király Jeruzsálemben olyanná tevé az ezüstöt, mint a köveket, és a czédrusfákat úgy elszaporítá, mint a vad fügefákat, a melyek nevekednek a mezőségen bőséggel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'Hordnak vala pedig Salamonnak lovakat Égyiptomból és minden országból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'Salamonnak egyéb dolgai, úgy az elsők, mint az utolsók, avagy nem írattak-é meg a Nátán próféta könyvében, és a Silóbeli Ahija prófécziájában, és Jehdó prófétának Jeroboám ellen, a Nébát fia ellen írt látásaiban?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'És uralkodék Salamon Jeruzsálemben az egész Izráel felett negyven esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'És elaluvék Salamon az ő atyáival egyetemben, és eltemeték őt az ő atyjának, Dávidnak városában, és uralkodék helyette az ő fia, Roboám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'Elméne Roboám Síkembe; mert Síkembe gyűlt vala az egész Izráel, hogy őt királylyá választanák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'Lőn pedig, mikor ezt meghallotta Jeroboám, a Nébát fia, a ki akkor Égyiptomban vala; mert oda futott volt Salamon király elől, visszatére Jeroboám Égyiptomból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'És hozzáküldvén, elhivaták őt. Eljöve azért Jeroboám és az egész Izráel, és szólának Roboámnak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, 'A te atyád igen megnehezítette a mi igánkat, de te most könnyebbítsd meg atyádnak kemény szolgálatát és az ő nehéz igáját, a melyet reánk vetett, és szolgálunk néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'És monda nékik: Harmadnapig gondolkodom róla, azután jőjjetek hozzám. Elméne azért a nép.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'És tanácskozék Roboám király a vén emberekkel, a kik Salamon előtt az ő atyja előtt állottak vala életében, mondván: Mit tanácsoltok, mit válaszoljak e népnek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'És azok ekképen szólának: Ha javára leendesz ennek a népnek, s kedvezel nékik és jó szóval beszélsz hozzájok; akkor te szolgáid lesznek mindenkor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'De ő megvetette a vének tanácsát, a melyet néki tanácsoltak, és tanácsot tarta az ifjakkal, a kik ő vele nevekedtek volt fel és néki udvaroltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'És monda azoknak: Ti micsoda tanácsot adtok, hogy választ adjunk e népnek, a kik nékem így szólának: Könnyebbítsd meg az igát, a melyet a te atyád reánk vetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'Akkor felelének az ifjak, a kik ő vele együtt nevekedtek vala, mondván: Így szólj a népnek, a mely szólván néked, azt mondja: A te atyád megnehezítette a mi igánkat, te pedig könnyebbítsd meg nékünk; így szólj nékik: Az én legkisebb ujjam erősebb atyám derekánál;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'Most azért, ha az én atyám nehéz igát vetett reátok, én még nehezebbé teszem igátokat; ha az én atyám ostorral vert titeket, én skorpiókkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'És elméne Jeroboám és az egész nép Roboámhoz harmadnap, a mint a király meghagyta, ezt mondván: Jőjjetek hozzám harmadnapon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'És a király kemény választ adott nékik, megvetve Roboám király a vének tanácsát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'És az ifjak tanácsa szerint szóla nékik, mondván: Ha az én atyám megnehezítette a ti igátokat, én még nehezebbé teszem azt; ha az én atyám ostorral vert titeket, én skorpiókkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'És a király nem hallgatá meg a népet; mert ezt az Úr fordította ekként, hogy megerősítené az Úr az ő beszédét, a melyet szólott vala a Silóbeli Ahija által Jeroboámnak, a Nébát fiának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'Mikor pedig az egész Izráel látta, hogy nem hallgatá meg őket a király, felele a nép a királynak, mondván: Micsoda részünk van nékünk Dávidban? Nincsen nékünk örökségünk az Isai fiában! Menj el a te hajlékidba, oh Izráel! Ám viseld gondját a te házadnak, oh Dávid! Elméne azért hajlékiba az egész Izráel;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'Úgy, hogy Roboám csak azokon az Izráel fiain uralkodék, a kik Júda városaiban laktak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'És mikor elküldé Roboám Adorámot, az adószedőt, megkövezék őt Izráel fiai, és meghala; Roboám király pedig siete szekerébe ülni, hogy Jeruzsálembe szaladjon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'Így szakada el az Izráel népe a Dávid házától, mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'Méne azért Roboám Jeruzsálembe, és összegyűjté a Júda és Benjámin házát, száznyolczvanezer válogatott hadviselőket, hogy hadakoznának Izráel ellen, és visszanyernék az országot Roboámnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'Szóla pedig az Úr Semájának, az Isten emberének, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, 'Mondd meg Roboámnak, Salamon fiának, Júda királyának és az egész Izráelnek Júdában és Benjáminban, így szólván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, 'Ezt mondja az Úr: Ne menjetek fel és ne hadakozzatok atyátokfiai ellen; térjetek meg ki-ki a maga házába, mert én tőlem lett e dolog. És engedének az Úr szavának, és megtérének a helyett, hogy Jeroboám ellen mennének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'Lakozék azért Roboám Jeruzsálemben, és megerősíté a városokat Júdában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'Így megépíté Bethlehemet, Etámot és Tékoát,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'Bethsúrt, Sókót és Adullámot,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'Gátot, Marésát és Zifet,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'Adoráimot, Lákist és Azekát,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'Sorát, Ajalont és Hebront, melyek erős városok valának Júdában és Benjáminban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'És mikor megerősítette ez erősségeket, helyezett azokba előljárókat és szerze tárházakat eleségnek és bornak és olajnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'És mindenik városban szerze paizsokat és kopjákat, és rendkivül megerősíté azokat. És az övé lőn Júda és Benjámin.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'Továbbá a papok és a Léviták, a kik az egész Izráelben valának, ő hozzá csatlakozának minden ő határukból;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'Mert a Léviták elhagyták az ő faluikat és jószágukat, és Júdába és Jeruzsálembe menének, mert kiűzte vala őket Jeroboám és az ő fiai, hogy az Úrnak ne szolgálnának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'És rendele magának papokat a magaslatokhoz, a bakokhoz és a borjúkhoz, a melyeket csináltatott vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'És utánuk Izráel minden nemzetségei közül azok, a kik szívök szerint keresték az Urat, Izráelnek Istenét, menének Jeruzsálembe, hogy áldoznának az Úrnak, az ő atyáik Istenének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'És megerősíték Júda országát, és megerősíték Roboámot, a Salamon fiát három esztendeig; mert három esztendeig járának Dávidnak és Salamonnak útján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'És feleségül vevé Roboám Mahalátát, Jérimótnak, a Dávid fiának leányát és Abihailt, Eliábnak, az Isai fiának leányát,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'A ki szüle néki fiakat: Jeust, Semáriát és Zahámot,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'És ő utána vevé Maakát, az Absolon leányát, a ki szülé néki Abiját, Attait, Zizát és Selómitot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'Legjobban szereté pedig Roboám Maakát, az Absolon leányát minden feleségei és ágyasai között; mert tizennyolcz felesége és hatvan ágyasa volt. És nemze huszonnyolcz fiút és hatvan leányt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'És Roboám Abiját, a Maaka fiát tette testvérei között vezérré és előljáróvá, mert őt akará királylyá tenni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'És okosan gondolkodván, szétosztá fiait mind Júda és Benjámin földén a megerősített városokba, a kiknek bőségesen adott eleséget és sok feleséget szerzett számukra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'Lőn pedig, mikor Roboám az ő királyságát megszilárdította és abban megerősödött: elhagyta az Úr törvényét, és vele együtt az egész Izráel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'Azért a Roboám királyságának ötödik esztendejében feljöve Sésák, az égyiptomi király Jeruzsálem ellen, (mert az Úr ellen vétkezének).');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'Ezerkétszáz fegyveres szekérrel és hatvanezer lovaggal, és megszámlálhatlan vala a nép, a mely vele Égyiptomból feljött, a Libiabeliekkel, Sukkeusokkal és Szerecsenekkel;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'És elfoglalá Júdának erős városait, azután méne Jeruzsálem alá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'Akkor Semája próféta méne Roboámhoz és a Júda fejedelmeihez, a kik Jeruzsálembe gyűltek össze Sésáktól való féltökben, és monda nékik: Ezt mondja az Úr: Mivel ti engem elhagytatok, én is a Sésák kezébe bocsátlak titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'Akkor megalázák magokat az Izráel fejedelmei és a király, s mondának: Az Úr igaz!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'És mikor az Úr látta, hogy megalázták magokat, ekképen szóla az Úr Semája prófétának: Megalázták magokat, nem vesztem el őket, hanem némi szabadulást szerzek nékik, és nem ontom ki az én haragomat Jeruzsálem ellen Sésák által;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'Mindazáltal szolgái lesznek néki, hogy megtudják a különbséget az én szolgálatom és más országok királyságainak szolgálatai között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'Feljöve azért Sésák, az égyiptomi király Jeruzsálem ellen, és elvivé az Úr házának kincsét, s a király házának kincsét; mindazokat elvivé; az arany paizsokat is elvivé, a melyeket Salamon csináltatott vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, 'Ezek helyett Roboám király rézpaizsokat csináltata, és bízá azokat a gyalogosok fejedelminek kezére, a kik őrzik a király házának ajtaját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'És mikor a király felmegy az Úr házába, mennek a gyalogosok is, és felviszik azokat, s azután visszahozzák a gyalogosok szobájába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'Mikor azért megalázta magát Roboám, eltávozék az Úr haragja ő róla, hogy meg ne semmisülne mindenestől, mert Júdában is volt még jó dolog.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'Megerősödék azért Roboám király Jeruzsálemben és uralkodék; mert negyvenegy esztendős vala Roboám, mikor uralkodni kezdett volt, és tizenhét esztendeig uralkodék Jeruzsálemben, a városban, a melyet az Úr választott vala az Izráel minden nemzetségei közül, hogy ott helyheztesse az ő nevét; és az ő anyjának neve vala Naáma, a ki Ammonita volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'Cselekedék pedig gonoszt, mert az Urat szíve szerint keresni nem akará.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'Roboámnak pedig első és utolsó dolgai avagy nincsenek-é megírva a Semája próféta könyvében, és Iddónak, a látnoknak könyvében, a nemzetségi lajstromban? És hadakozás volt Roboám és Jeroboám között egész éltökben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'És elaluvék Roboám az ő atyáival, és eltemetteték a Dávid városában; és uralkodék az ő fia, Abija, helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'Jeroboám királynak tizennyolczadik esztendejében kezde uralkodni Abija Júdában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'Három esztendeig uralkodék Jeruzsálemben. Az ő anyjának neve Mikája vala, a ki a Gibeából való Uriel leánya. És Abija és Jeroboám között háború vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'Azért felkészüle Abija a háborúra négyszázezer válogatott harczosból álló sereggel; és Jeroboám vele szembeszállott nyolczszázezer válogatott harczosból álló sereggel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'Akkor felálla Abija a Semáraim hegyének tetején, a mely az Efraim hegységében vala, és monda: Hallgassátok meg szómat, Jeroboám és az egész Izráel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'Avagy nem kellene-é néktek meggondolnotok, hogy az Úr, az Izráel Istene Dávidnak adta volt a királyságot Izráel felett örökre; néki és fiainak, sónak szövetsége által?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Mindazáltal felkele Jeroboám, a Nébát fia, Salamonnak, a Dávid fiának szolgája, és támada az ő ura ellen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'Azután gyűlének ő hozzá a haszontalan emberek, Beliál fiai, a kik ellene szegültek Roboámnak, a Salamon fiának, mikor Roboám gyermek és félénk szívű volt, és azok ellen magát nem oltalmazhatta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'És most azt gondoljátok, hogy ti ellene állhattok az Úr királyságának, a mely a Dávid fiainak kezében van, mivel sokan vagytok, s veletek vannak az aranyborjúk is, a melyeket Jeroboám öntetett néktek istenek gyanánt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'Avagy nem ti űztétek-é el az Úrnak papjait, az Áron fiait és a Lévitákat? És nem ti szerzettetek-é magatoknak papokat, mint egyéb országoknak nemzetségei, akárkit, a ki az ő szolgálatjának felszentelésére egy gyermekded tulokkal és hét kossal eljött, és lett a bálványok papja, a melyek nem istenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'Mi mellettünk van pedig az Úr, a mi Istenünk, a kit mi el nem hagytunk; a papok pedig, a kik az Úrnak szolgálnak, az Áron fiai, és vannak Léviták, a kik forgolódnak az ő tisztökben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'És áldoznak az Úrnak égőáldozattal minden reggel és minden estve, és füstölőáldozattal, és a kenyérnek a tiszta asztalra való tételére és az arany gyertyatartóra, szövétnekeivel egybe gondot viselnek, meggyújtván azokat minden estve; mert mi megtartjuk az Úrnak, a mi Istenünknek rendelését; ti pedig elhagytátok őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'Azért ímé mi velünk van az Isten vezér gyanánt, és az ő papjai a riadó kürtökkel, hogy ti ellenetek kürtöljenek. Izráel fiai! Ne harczoljatok az Úr ellen, a ti atyáitok Istene ellen, mert nem lesztek szerencsések!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'Jeroboám pedig lest vetett ellenök, hogy hátuk mögé kerüljön, s ilyen módon Júda előtt is ők legyenek, hátuk mögött is a les.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'Látván pedig Júda, hogy ímé mind elől, mind hátul megtámadtatának: kiáltának az Úrhoz, a papok pedig trombitálnak vala a trombitákkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'És kiáltának Júda férfiai; és mikor kiáltának a Júda férfiai, az Isten megveré Jeroboámot és az egész Izráelt, Abija és Júda előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'És az Izráel fiai menekülének Júda elől, de az Isten kezökbe adá őket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'Mert megveré őket Abija és az ő népe nagy csapással, úgyannyira, hogy az Izráeliták közül seb miatt ötszázezer válogatott férfi esett el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'És ilyen módon aláztatának meg az Izráel fiai abban az időben; Júda fiai pedig megerősödének, mert ők az Úrra, az ő atyáik Istenére támaszkodtak volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'És üldözé Abija Jeroboámot, és elfoglala ő tőle egynéhány várost, Béthelt és annak faluit, Jésanát és annak faluit, s Efrávint és annak faluit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'És nem jutott többé erőhöz Jeroboám Abija idejében, hanem megveré őt az Úr, és meghala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'Abija pedig hatalmassá lőn, és vett vala magának tizennégy feleséget, a kiktől nemze huszonkét fiút és tizenhat leányt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'Abijának pedig több dolgai, útai és beszédei megírattak az Iddó próféta könyvében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'Elaluvék pedig Abija az ő atyáival, és eltemeték őt a Dávid városában, s uralkodék helyette az ő fia, Asa, a kinek idejében tíz esztendeig volt békesség a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'És Asa mindazt cselekedé, a mi jó és igaz vala az Úr előtt, az ő Istene előtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'Elrontá az idegen istenek oltárait és a magaslatokat; a bálványokat eltöreté, és az Aserákat kivágatá;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'És megparancsolá Júdának, hogy az Urat, az ő atyáik Istenét keressék, és cselekedjék az Isten törvényét és parancsolatját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'Kipusztítá Júda minden városaiból a magaslatokat és a nap-oszlopokat, és az ország csendes lőn alatta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'És építtetett megerősített városokat Júdában, mivelhogy nyugodalomban volt a föld, és senki sem folytatott ellene háborút azokban az esztendőkben, mert az Úr nyugodalmat adott vala néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'Mert ezt mondja vala Júdának: Építsük meg a városokat és vegyük körül kerítéssel, tornyokkal, kapukkal, zárokkal, míg a föld birodalmunkban van; mert megkerestük az Urat, a mi Istenünket, megkerestük és nyugodalmat adott nékünk minden felől. Azért építének és lőn jó előmenetelök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'Vala pedig az Asa serege, a mely paizst és kopját visel vala, Júdából háromszázezer; és Benjáminból paizst viselők és kézívesek kétszáznyolczvanezeren valának; mindezek erős vitézek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'És kijöve ő ellenök a szerecsen Zérah, ezerszer ezer emberrel és háromszáz szekérrel, és méne Marésáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'Kiméne Asa is ő ellene, és viadalhoz készülének a Sefáta völgyben, Marésa mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'Akkor kiálta Asa az Úrhoz, az ő Istenéhez, és monda: Oh Uram, nincs különbség előtted a sok között és az erő nélkül való között, hogy megsegítsed! Segélj meg minket, oh mi Urunk Istenünk, mert benned bízunk, és a te nevedben jöttünk e sokaság ellen! oh Uram, te vagy a mi Istenünk, ne vegyen ember te rajtad erőt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'Megveré azért az Úr a szerecseneket Asa és Júda előtt, és elfutának a szerecsenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'És üldözé őket Asa az ő seregével Gerárig, és elhullának a szerecsenek közül sokan, hogy közülök senki sem marada életben, mert leverettek az Úr előtt és az ő serege előtt; és hozának nagy zsákmányt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'És Gérár környékén elpusztítának minden várost, mert az Úrtól való rettegés szállotta meg őket. És a városokat mind feldúlták, mivelhogy sok ragadomány vala azokban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 15, 'A barmok tanyáit is lerombolták, és sok juhot és tevét elhajtának, s úgy tértek vissza Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'És Azáriást, az Obed fiát felindítá az Isten lelke:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'A ki Asa elé lépett, és monda: Hallgassatok meg engem, Asa s egész Júda és Benjámin! Az Úr van veletek, ha ti is ő vele lesztek; ha őt keresénditek, megtaláljátok; de ha őt elhagyándjátok, ő is elhágy titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'Sok ideje, hogy Izráel az igaz Isten nélkül, tanító pap nélkül, és törvény nélkül van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'Ha megtért volna az ő nyomorúságában az Úrhoz, Izráel Istenéhez: megtalálták volna azok, a kik őt keresik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'De ezekben az időkben nincs békessége sem a kimenőnek, sem a hazajövőnek, mivelhogy nagy a nyomorúsága mindazoknak, a kik e földön laknak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'Annyira, hogy egy nemzetség a másik nemzetséget és egyik város a másik várost elpusztítja; mert az Isten gyötri őket minden sanyarúsággal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'Ti azért bátorságosok legyetek, kezeiteket le ne ereszszétek, mert a ti munkátoknak jutalma van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'Mikor pedig Asa meghallotta e beszédeket és az Obed prófétának prófécziáját, megbátorodék, és elpusztítá a Júda és Benjámin földéről mindenestől a bálványokat, a városokból is, a melyeket elfoglalt az Efraim hegységén, és megújítá az Úr oltárát is, a mely az Úr tornácza előtt volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'És összegyűjté az egész Júda és Benjámin nemzetségét és azokat, a kik jövevények valának köztök az Efraim, Manasse és Simeon nemzetségéből; mert az Izráel nemzetségéből sokan csatlakozának ő hozzá, látván, hogy az Úr, az ő Istene, ő vele volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'Összegyűlének azért Jeruzsálembe a harmadik hónapban, Asa királyságának tizenötödik esztendejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'És áldozának az Úrnak azon a napon a nyert zsákmányból hétszáz ökörrel és hétezer juhval;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'És fogadást tettek, hogy ezután az Urat, az ő atyáik Istenét teljes szívvel és teljes lélekkel fogják keresni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'És ha valaki nem keresné az Urat, az Izráel Istenét, megölettessék kicsinytől fogva nagyig, úgy a férfi, mint az asszony.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'És megesküvének az Úrnak felszóval, kiáltással, trombita- és kürtszókkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'És örvendezett az egész Júda az eskű felett; mert teljes szívökből esküdtek, és egyenlő akarattal keresték az Urat; és megtaláltaték általok, és az Úr nyugodalmat szerze nékik minden felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'De még Maakát, Asa király anyját is megfosztá a királynéságtól, mivel egy iszonyú bálványt emelt vala Aserának, és Asa elrontá és összetörte annak iszonyú bálványát, és a Kedron patakjánál megégeté.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'Jóllehet Izráelből a magaslatokat nem irtották ki, mindazáltal Asának tiszta szíve vala egész életében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'És bevivé az Isten házába, a mit atyja és ő megszentelének, ezüstöt, aranyat és edényeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'És nem volt háború Asa királyságának harminczötödik esztendejéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'Asa király uralkodásának harminczhatodik esztendejében feljöve Baása, az Izráel királya Júda ellen, és megépíté Rámát, hogy ne engedjen senkit se kimenni, se bemenni Asához a Júda királyához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'De Asa az Úrnak és a királynak tárházából hoza ki ezüstöt, aranyat, és küldé azt Benhadádnak, a Siriabeli királynak, a ki lakik vala Damaskusban, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, 'Szövetség van köztem és te közötted, a mint az én atyám és a te atyád között is volt azelőtt. Ímé küldök néked ezüstöt és aranyat. Menj el, bontsd fel a te szövetségedet Baásával, az Izráel királyával, hogy távozzék el tőlem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'És engedvén Benhadád Asa királynak, elküldé az ő seregének vezéreit Izráel városai ellen, és bevevé Ijont, Dánt, Abelmáimot és Nafthali minden kincses városait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'A mit mikor meghallott Baása, abbanhagyta Ráma építését és megszünteté munkáját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'Akkor Asa király felvevé az egész Júda népét, és Rámából a köveket és a fákat mind elhordák, a melyekkel Baása a várost építi vala, és azokból Gébát és Mispát építé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'Az időben méne Hanáni próféta Asához, a Júda királyához, és monda néki: Mivel a Siriabeli királyban volt bizodalmad, és nem az Úrban, a te Istenedben bízál: ezért szabadult meg a Siriabeli király hada a te kezedből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Avagy nem vala-é a Szerecseneknek és a Libiabelieknek nagy seregök, felette sok szekereik és lovagjaik? Mindazáltal, mivel az Úrban volt bizodalmad, kezedbe adá azokat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'Mert az Úr szemei forognak az egész földön, hogy hatalmát megmutassa azokhoz, a kik ő hozzá teljes szívvel ragaszkodnak; bolondul cselekedél ebben; azért mostantól kezdve háborúk lesznek te ellened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'Akkor megharaguvék Asa a prófétára, és veté őt a tömlöczházba, mert igen megharagudott vala e szóért reá; és ugyanakkor Asa a nép közül is sokat megnyomoríta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'De ímé Asának mind első, mind utolsó dolgai meg vannak írva a Júda és az Izráel királyainak könyvében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'És megbetegedék Asa, királyságának harminczkilenczedik esztendejében lábaira, annyira, hogy igen súlyos volt az ő betegsége; mindazáltal betegségében is nem az Urat keresé, hanem az orvosokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'És elaluvék Asa az ő atyáival, és meghala az ő királyságának negyvenegyedik esztendejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'És eltemeték őt az ő sírjába, a melyet magának vágatott vala a Dávid városában; és helyezék őt az ágyba, a melyet megtöltének drága fűszerekkel, s kenőcscsé feldolgozott jó illatokkal, és érette felette nagy égést rendezének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'Uralkodék pedig ő helyette az ő fia, Jósafát, és megerősíté magát Izráel ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'És sereget helyezett Júda minden erős városaiba, és őrségeket helyezett Júda országába és Efraim városaiba, a melyeket az ő atyja, Asa meghódított vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'És az Úr Jósafáttal vala, mivel az ő atyjának Dávidnak előbbi útain jára, és nem kére segítséget a bálványoktól,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'Hanem az ő atyjának Istenét kereste, és az ő parancsolatiban járt vala, és nem Izráelnek cselekedetei szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'Azért az Úr megerősíté a királyságot az ő kezében, és az egész Júda ada Jósafátnak ajándékot, s gazdagsága és dicsősége igen nagy volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'És az ő szíve felemelkedett az Úr útjain, és még jobban kiirtá Júdából a magaslatokat és az Aserákat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'Királyságának harmadik esztendejében elküldé az ő vezérei közül Benhailát, Obádiást, Zakariást, Nétanéelt és Mikáját, hogy tanítsanak a Júda városaiban,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'És velök Lévitákat: Semája, Nétánia, Zebádia, Asáel, Semirámót, Jónatán, Adónia, Tóbiás és Tóbadónia Lévitákat, és velök Elisáma és Jórám papokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'Tanítának azért Júdában, és az Úr törvényének könyve velök vala, mikor jártak vala Júda városaiban, tanítván a népet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'Ezért az Úr igen megrettenté a földnek minden országait, a melyek Júda körül valának, annyira, hogy nem merének Jósafát ellen hadakozni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'A Filiszteusoktól is hoznak vala Jósafátnak ajándékot és adópénzt; az Arábiabeliek is hoznak néki nyájakat, hétezerhétszáz kost és hétezerhétszáz bakot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'És Jósafát mindig nagyobb és hatalmasabb lőn, és építe Júdában kastélyokat és tárházakat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'És sok munkája vala néki Júda városaiban, és erős hadakozó férfiakból álló serege volt Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'Ez pedig azoknak száma nemzetségeik szerint: Júdában az ezredesek: Adna, a fővezér, és vele háromszázezer harczos.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'Mellette Johanán volt a vezér, és vele kétszáznyolczvanezer ember.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'Mellette Amásia, a Zikri fia, a ki magát szabadakaratjából az Úrnak kötelezte vala; és ő vele kétszázezer harczos.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'A Benjámin nemzetségéből vitéz harczos vala Eljada, és vele a kézívesek és paizsosok kétszázezeren.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'Mellette Józabád, és vele száznyolczvanezeren harczra felszerelve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'Ezek szolgálnak vala a királynak azokon kivül, a kiket a király egész Júdában a megerősített városokba helyezett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'Jósafátnak nagy gazdagsága és dicsősége vala. Ő sógorságot szerze Akhábbal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'Néhány esztendő mulva aláméne Akhábhoz Samariába, és levágatott Akháb az ő és a vele való nép számára sok juhot és ökröt, és rávette őt, hogy felmenjen vele Rámóth Gileádba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'Mert ezt mondá Akháb, az Izráel királya Jósafátnak, a Júda királyának: Feljösz-é velem Rámóth Gileádba? Felele néki, és monda: Úgy én, mint te; úgy az én népem, mint a te néped együtt lesz a harczban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'Azután monda Jósafát az Izráel királyának: Kérdezősködjél még ma az Úr beszéde után.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'És összegyűjté az Izráel királya a prófétákat, mintegy négyszáz férfiút, és monda nékik: Elmenjünk-é Rámóth Gileád ellen hadba, vagy elhagyjam? Felelének: Menj el, és az Isten a király kezébe adja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'És monda Jósafát: Nincsen-é itt több prófétája az Úrnak, hogy attól is tudakozódhatnánk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'És monda az Izráel királya Jósafátnak: Van még egy férfiú, a ki által az Urat megkérdezhetjük, de én gyűlölöm őt, mert soha nem jövendöl nékem jót, hanem mindig csak rosszat; ez Mikeás, a Jimla fia. És monda Jósafát: Ne beszéljen így a király!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'Szólíta azért az Izráel királya egyet az ő szolgái közül, és monda: Hívd ide hamar Mikeást, a Jimla fiát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'És az Izráel királya és Jósafát, a Júda királya ott ülnek vala, kiki az ő királyiszékében, királyi ruhákba öltözötten; ott ülnek vala Samaria kapuja előtt, a térségen; és a próféták mind prófétálnak vala ő előttök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'Csináltatott vala pedig magának Sédékiás, a Kénaána fia vasszarvakat, és monda: Ezt mondja az Úr: Ezekkel ökleled a Siriabelieket, mígnem megemészted őket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'A többi próféták is mind ekképen jövendöltek, mondván: Menj fel Rámóth Gileád ellen, szerencsés leszel; mert azt az Úr a király kezébe adja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'A követ pedig, a ki elment volt, hogy elhívná Mikeást, szóla néki, mondván: Ímé a próféták egyenlő akarattal jót jövendölnek a királynak; szólj, kérlek, te is úgy, mint azok közül egy, és jövendölj jót.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'Akkor monda Mikeás: Él az Úr, hogy csak azt fogom mondani, a mit az én Istenem nékem mondánd!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'Mikor azért a király elé jutott, akkor monda a király néki: Mikeás! elmenjünk-é Rámóth Gileád ellen hadba, vagy elhagyjam? És monda: Menjetek el, és jó szerencsétek leszen, kezetekbe adattatnak azok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'És monda a király néki: Hányszor esküdtesselek meg téged, hogy az igaznál egyebet ne mondj nékem az Úr nevében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'Akkor monda: Látám az egész Izráelt elszéledve a hegyeken, mint a juhokat, melyeknek pásztoruk nincsen. És azt mondá az Úr: Nincsen ezeknek urok. Térjen meg kiki az ő házához békességben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'És monda az Izráel királya Jósafátnak: Nemde nem megmondottam-é, hogy nem fog nékem jót jövendölni, hanem rosszat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'Ismét monda: Halljátok meg azért az Úr szavát. Látám az Urat ülni az ő királyiszékében, és az egész mennyei sereget jobb és balkeze felől mellette állani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'És monda az Úr: Kicsoda csalja meg Akhábot, az Izráel királyát, hogy felmenjen és elveszszen Rámóth Gileádban? És ki egyet, ki mást szóla.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'Akkor eljöve egy lélek, a ki megállván az Úr előtt, monda: Én akarom megcsalni őt. Az Úr pedig monda néki: Mimódon?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'És felele: Kimegyek és leszek hazug lélek az ő összes prófétái szájában. Monda azért: Csald meg és győzd meg, menj ki és cselekedjél úgy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'Ímé azért most az Úr adta a hazugságnak lelkét ezen te prófétáid szájába, és az Úr szólott veszedelmes dolgot ellened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'Akkor oda lépett Sédékiás, a Kénaána fia, s arczul csapá Mikeást, és monda: Melyik úton távozott el az Úrnak lelke tőlem, hogy csak néked szólana?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'Felele Mikeás: Ímé meglátod magad azon a napon, a mikor egyik kamarából a másik kamarába mégy, hogy elrejtőzhessél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'Akkor monda az Izráel királya: Fogjátok meg Mikeást, és vigyétek Amonhoz, a város fejedelméhez, és Joáshoz, a király fiához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'És mondjátok: Ezt mondja a király: Vessétek őt a tömlöczbe, s tápláljátok őt a nyomorúság kenyerével és a nyomorúság vizével, míg békességgel megjövök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'És monda Mikeás: Ha békével térsz vissza, akkor nem az Úr szólott én általam. Ismét monda: Halljátok meg minden népek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'És felvonult az Izráel királya és Jósafát a Júda királya Rámóth Gileád ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'És monda az Izráel királya Jósafátnak: Ruhámat megváltoztatom, és úgy megyek a viadalra; te pedig öltözzél fel ruhádba. És megváltoztatá az Izráel királya az ő ruháját, és menének viadalra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'Siria királya pedig meghagyta vala az ő szekerei fejedelmeinek, mondván: Ne harczoljatok se kicsiny, se nagy ellen, hanem csak az Izráel királya ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'És a mikor meglátták a szekerek fejedelmei Jósafátot, mondának: Ez az Izráel királya! És körülfogták őt, hogy legyőzzék. Akkor felkiálta Jósafát, és az Úr megsegéllé őt, és az Isten azokat elfordítá tőle;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'Mert mikor látták a szekerek fejedelmei, hogy nem az Izráel királya, ott hagyták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'Egy férfi pedig kifeszíté kézívét csak úgy találomra, és találá az Izráel királyát a pánczél és a kapocs között. És ő monda az ő kocsisának: Fordulj meg, és vígy ki engem a táborból, mert megsebesültem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'És az ütközet mind erősebb lett azon a napon, és az Izráel királya az ő szekerében állott a Siriabeliek ellen estvéig, és naplementekor meghala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'Megtére pedig Jósafát, a Júda királya az ő házához Jeruzsálembe békével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'És eleibe méne Jéhu próféta, a Hanáni fia, és monda Jósafát királynak: Avagy az istentelennek kellett-é segítségül lenned, és az Úrnak gyűlölőit szeretned? Ezért nagy az Úrnak haragja ellened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'Mindazáltal némi jó dolog találtatott benned, hogy e földről kivágattad az Aserákat és az Istennek keresésére adtad magadat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'És Jósafát egy ideig Jeruzsálemben tartózkodék, azután pedig kiméne a nép közé, Beersebától fogva mind az Efraim hegységéig, és megtéríté őket az Úrhoz, az ő atyáiknak Istenéhez;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'És rendele bírákat azon a földön, Júdának minden erős városaiba, városonként.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'És monda a bíráknak: Jól meglássátok, a mit cselekesztek; mert nem ember nevében ítéltek, hanem az Úrnak nevében, a ki az ítéletben veletek lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'Azért az Úr félelme legyen rajtatok, vigyázzatok arra, a mit tesztek; mert az Úrnál, a mi Istenünknél nincsen hamisság, sem személyválogatás, sem ajándékvétel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'Sőt Jeruzsálemben is beállíta némelyeket Jósafát a Léviták, papok és az Izráel nemzetségeiből való fejedelmek közül az Úr ítéletére és a perlekedésekre. És ők Jeruzsálembe visszatérének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'És meghagyá nékik, mondván: Így cselekedjetek az Úrnak félelmében hűséggel és tökéletes szívvel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'Ha valamely pert előtökbe hoznak a ti atyátokfiai, a kik lakoznak az ő városaikban, emberhalál, törvény és parancsolat, a rendtartások és ítéletek miatt: intsétek őket, hogy ne vétkezzenek az Úr ellen, és ne szálljon reátok és a ti atyátokfiaira az Úr haragja. Így cselekedjetek és ne vétkezzetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'És ímé Amária pap lesz a fő ti köztetek az Úrnak minden dolgaiban; és Zebádia, az Ismáel fia lesz a Júda házának vezére a király minden dolgában; a Léviták is előljáróitok lesznek. Legyetek azért erősek a ti tisztetekben és az Úr mellette lesz az igaznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'És lőn ezek után, eljövének a Moáb fiai és Ammon fiai, és velök mások is az Ammoniták közül, Jósafát ellen, hogy hadakozzanak vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'Eljövének pedig a hírmondók, és megmondák Jósafátnak, mondván: A tenger tulsó részéről nagy sokaság jön ellened Siriából, és már Haséson-Tamárban vannak; ez az Engedi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'Megfélemlék azért Jósafát, és az Urat kezdé keresni és hirdete az egész Júda országában bőjtöt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'Azért felgyűlének a Júdabeliek, hogy az Úr segedelmét keressék, Júdának minden városaiból is jövének, hogy az Urat megkeressék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'És megálla Jósafát Júda és Jeruzsálem gyülekezetiben, az Úr házában az új pitvar előtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'És monda: Oh Uram, mi atyáink Istene! nem te vagy-é egyedül Isten a mennyben, a ki uralkodol a pogányoknak minden országain? A te kezedben van az erő és hatalom, és senki nincsen, a ki ellened megállhatna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'Oh mi Istenünk! nem te űzéd-é ki e földnek lakóit a te néped az Izráel előtt, és nem te adád-é azt Ábrahámnak, a te barátod magvának mindörökké?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'És lakának azon, és építettek azon a te nevednek szentséges hajlékot, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, 'A mikor veszedelem jövend mi reánk, háború, ítélet, döghalál vagy éhség, megállunk e házban előtted (mert a te neved e házban van) és a mikor kiáltunk hozzád a mi nyomorúságainkban: hallgass meg és szabadíts meg minket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'És most ímé az Ammoniták, a Moábiták és a Seir hegyén lakozók, a kiknek földjén nem akarád, hogy általmenjenek az Izráel fiai, mikor Égyiptom földéből kijöttek, hanem mellettök menének el és nem pusztíták el őket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'Ímé ezért azzal fizetnek nékünk, hogy ellenünk jönnek, hogy kiűzzenek a te örökségedből, melyet örökségül adtál nékünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'Oh mi Istenünk, nem ítéled-é meg őket? Mert nincsen mi bennünk erő e nagy sokasággal szemben, mely ellenünk jön. Nem tudjuk, mit cselekedjünk, hanem csak te reád néznek a mi szemeink.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'És a Júdabeliek mindnyájan állanak vala az Úr előtt, gyermekeikkel, feleségeikkel és fiaikkal egyetemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'Akkor Jaházielre, a Zakariás fiára (ki Benája fia, ki Jéhiel fia, ki Mattániás fia vala, és az Asáf fia közül való Lévita vala) az Úrnak lelke szálla, a gyülekezet közepette,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'És monda: Mindnyájan, a kik Júdában és Jeruzsálemben lakoztok, és te Jósafát király, halljátok meg szómat! Így szól az Úr néktek: Ne féljetek és ne rettegjetek e nagy sokaság miatt; mert nem ti harczoltok velök, hanem az Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'Holnap szálljatok szembe velök! Ímé ők a Czicz hágóján fognak felmenni, és rájok találtok a völgynek szélénél, a Jeruel pusztájával szemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'Nem kell néktek harczolnotok, hanem csak álljatok veszteg, és lássátok az Úrnak szabadítását rajtatok. Júda és Jeruzsálem, ne féljetek és ne rettegjetek! Holnap menjetek ellenök, mert az Úr veletek lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'Akkor Jósafát meghajtá fejét a föld felé, s Júda és Jeruzsálem lakói leborulának az Úr előtt és imádák az Urat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'A Kéhátiták fiai közül és a Kóriták fiai közül való Léviták pedig felállának, hogy az Urat, Izráel Istenét nagy felszóval dícsérjék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'És reggel felkészülvén, kimenének a Tékoa pusztájára; és mikor kiindulnának onnan, megálla Jósafát, és monda: Halljátok meg szómat, Júda és Jeruzsálemben lakozók! Bízzatok az Úrban a ti Istentekben, és megerősíttettek; bízzatok az ő prófétáiban, és szerencsések lesztek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'Tanácsot tartván pedig a néppel, előállítá az Úr énekeseit, hogy dícsérjék a szentség ékességét, a sereg előtt menvén, és mondják: Tiszteljétek az Urat, mert örökkévaló az ő irgalmassága;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'És a mint elkezdették az éneklést és a dícséretet: az Úr ellenséget szerze az Ammon fiai és a Moábiták és a Seir hegyén lakozók ellen, a kik Júdára jövének, és megverettetének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'Mert az Ammon és a Moáb fiai a Seir hegyén lakozók ellen támadának, hogy őket levágnák és elvesztenék; és mikor mind elvesztették a Seir hegyén lakozókat, azután egymás elpusztítását segítették elő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'A Júda népe pedig méne Mispába a puszta felé, és mikor a sokaság felé fordulának: ímé csak elesett holttestek valának a földön, és senki sem menekült meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'Akkor elméne Jósafát és az ő népe, hogy azoknak jószágait megzsákmányolják, és találának nálok temérdek gazdagságot és a holttesteken drága szép ruhákat, melyeket lefosztának rólok, oly sokat, hogy alig vihették el, és harmadnapig kapdosták a zsákmányt, mert felette sok vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'Negyednapra pedig gyűlének a hálaadásnak völgyébe, mivel az Úrnak ott adának hálákat; azért azt a helyet hálaadás völgyének nevezék mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'Megtére azért Júdának és Jeruzsálemnek egész népe Jósafáttal, az ő fejedelmökkel egybe, hogy visszamenjen Jeruzsálembe nagy örömmel; mert az Úr megvigasztalta vala őket az ő ellenségeik felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'És bemenének Jeruzsálembe, lantokkal, cziterákkal és trombitákkal, az Úr házához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'És lőn az Istennek félelme az országok minden királyságain, mikor meghallották, hogy az Úr hadakozott vala az Izráel ellenségei ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'Megnyugovék azért a Jósafát országa, és békességet ada néki az ő Istene minden felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'És uralkodék Jósafát Júda felett. Harminczöt esztendős vala, mikor uralkodni kezde, és uralkodék Jeruzsálemben huszonöt esztendeig; és az ő anyjának neve Azuba vala, a Silhi leánya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'És jára Asának, az ő atyjának útján, el sem távozék attól, cselekedvén azt, a mi az Úr szeme előtt kedves dolog vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'Csakhogy még a magaslatok nem rontattak le, és a nép nem készítette az ő szívét az ő atyái Istenéhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'Jósafátnak pedig első és utolsó dolgai ímé meg vannak írva Jéhunak, a Hanáni fiának könyvében, a ki azokat beírta az Izráel királyainak könyvébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'Azután Jósafát, a Júda királya megbarátkozék Akháziával, az Izráel királyával, a ki gonoszul cselekedett vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'Mindazáltal vele megbarátkozék, hogy hajókat készítenének, melyeken Társisba mennének; és a hajókat Esiongáberben készíték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Jövendöle azért Eliézer, a Maresából való Dódava fia Jósafát ellen, mondván: Minthogy megbarátkozál Akháziával, az Úr megsemmisíti a te munkádat. És a hajók mind összetörének, és nem mehetének Társisba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'És meghala Jósafát az ő atyáival egyetemben, és eltemetteték az ő atyáival a Dávid városában; és uralkodék helyette az ő fia, Jórám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'És az ő testvérei, a Jósafát fiai ezek valának: Azária, Jéhiel, Zakariás, Azáriás, Mikáel és Sefátja. Ezek mind Jósafátnak, az Izráel királyának fiai voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'És adott nékik az ő atyjok sok ajándékot ezüstben, aranyban és drágaságokban, Júdabeli megerősített városokkal; de a királyságot Jórámnak adá, mivel ő vala elsőszülötte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'Kezde azért Jórám az ő atyjának királyságában uralkodni, és mikor immár abban megerősödött, az ő testvéreit mind megölé fegyverrel; sőt Izráel fejedelmei közül is némelyeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'Harminczkét esztendős korában kezdett vala uralkodni Jórám, és nyolcz esztendeig uralkodék Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'És jára az Izráel királyainak útján, a mint cselekszik vala az Akháb háznépe; mert az Akháb leányát vette vala magának feleségül; és az Úr szemei előtt gonosz dolgot cselekedék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'Nem akará mindazáltal az Úr a Dávid házát elveszteni a szövetségért, a melyet Dáviddal kötött, és mivel igéretet tett vala, hogy szövétneket ad néki és az ő fiainak minden időben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'Az ő idejében szakada el Edom Júda keze alól, és királyt választának magoknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'Elméne ugyan Jórám az ő vezéreivel és a szekerek mind ő vele, és felkelvén éjjel, megveré az Edomitákat, a kik őt körülvették vala, és szekereiknek fejedelmeit;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'Mindazáltal Edom elszakada Júdának keze alól mind e mai napig. Ugyanakkor elszakada Libna is az ő keze alól, mivel elhagyta az Urat, atyái Istenét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'Ő is csináltatott magaslatokat Júda hegyein, és azt művelé, hogy a Jeruzsálembeliek paráználkodának, sőt Júdát is felbiztatá erre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'Juta pedig azonközben az Illés próféta írása hozzá, mondván: Ezt mondja az Úr, a te atyádnak, Dávidnak Istene: Mivel nem járál a te atyádnak, Jósafátnak útján, sem a Júda királyának, Asának útján;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'Hanem járál az Izráel királyainak útján, és azt műveléd, hogy Júda és Jeruzsálem lakói paráználkodjanak, a mint az Akháb háza is paráználkodik; annakfelette testvéreidet, atyádnak házát megöléd, a kik jobbak voltak nálad:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'Ímé az Úr nagy csapást bocsát a te népedre, fiaidra, feleségeidre és minden jószágodra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'Te pedig súlyos betegségbe, bélbajba esel, mindaddig, míg a te béled naponként kimegy a betegség miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'Felindítá azért az Úr Jórám ellen a Filiszteusok és az Arábiabeliek elméjét, a kik a szerecsenekkel határosok valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'És feljövének Júda ellen és megtámadván őt, zsákmányul vivék mindazt a vagyont, a mi a király házában található volt, sőt fiait és feleségeit is, és nem maradt néki más fia, csak Joákház, a legkisebbik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'És mindezek után megveré őt az Úr felette nagy bélbajjal, mely gyógyíthatatlan vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'És ez így volt napról-napra, egészen a második év végéig, midőn belei kifolytak a betegség miatt, és meghala nagy kínokban: és népe nem égete néki drága illatú fűszereket, mint az ő atyáinak égettek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'Harminczkét esztendős vala, mikor uralkodni kezde, és nyolcz esztendeig uralkodék Jeruzsálemben. És mikor minden részvét nélkül kimula, eltemeték őt a Dávid városában; de nem a királyok sírjába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'És királylyá tevék Jeruzsálem lakosai helyette az ő legkisebb fiát Akháziát; mert az idősebbeket mind megölték azok, a kik az Arábiabeliekkel jöttek vala a táborba. Uralkodék azért Akházia, Jórámnak a Júda királyának fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'Akházia negyvenkét esztendős volt, mikor királylyá lett, és egy esztendeig uralkodék Jeruzsálemben. Anyjának neve Athália volt, a ki az Omri leánya vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'Ő is az Akháb házának útjain jára; mert az ő anyja vala néki tanácsadója az istentelen cselekedetre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'És gonoszul cselekedék az Úr szemei előtt, miképen az Akháb háznépe, mert azok voltak tanácsadói atyja halála után, az ő veszedelmére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'Sőt azoknak tanácsa után indulva, hadba méne Jórámmal az Akháb fiával az Izráel királyával Hazáel ellen a Siriabeli király ellen, Rámóth Gileádba; de a Siriabeliek Jórámot megverék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'Visszatért azért Jórám, hogy meggyógyíttassa magát Jezréel városában; mert sebek valának rajta, melyekkel megsebesíttetett Rámában, mikor Hazáel ellen, Siria királya ellen harczolt. Akházia pedig, Jórámnak a Júda királyának fia, aláméne, hogy meglátogatná Jórámot, az Akháb fiát Jezréelben, mert beteg vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'Hogy Akházia Jórámhoz méne, Isten akaratából, az ő romlása vala, mert odaérkezvén, elméne Jórámmal Jéhu ellen, a ki a Nimsi fia volt, a kit az Úr felkenetett, hogy kiírtaná az Akháb háznépét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'Lőn azért, mikor Jéhu az Akháb házán bosszút álla, rátalált a Júda fejedelmeire és az Akházia testvéreinek fiaira, a kik Akháziának szolgálnak vala, és megölé őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'Akháziát is keresé és megfogák őt, (ki Samariában rejtőzött vala el) és vivék őt Jéhuhoz, a ki megöleté őt. De eltemették, mert ezt mondják róla: Mégis a Jósafát fia volt, a ki teljes szívvel keresé az Urat. És nem vala immár senki az Akházia háznépe közül a ki képes lett volna a királyságra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'És Athália az Akházia anyja, látván, hogy az ő fia meghalt: felkele és megölé a Júda háznépének minden királyi sarját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'De Jósabát a király leánya vevé Joást az Akházia fiát, és kivivé őt titkon a király fiai közül, a kik megölettek, és elrejté őt és az ő dajkáját az ágyasházban. És elrejté őt Jósabát, a Jórám király leánya, a ki a Jójada pap felesége volt, (mert Akháziának huga vala) Athália elől, hogy őt meg ne ölhesse.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'És náluk vala az Úr házában elrejtve hat esztendeig. Athália pedig uralkodék az ország felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'A hetedik esztendőben pedig felbátorodván Jójada, szövetséget kötött a századosokkal, Azáriával a Jérohám fiával, Ismáellel a Jóhanán fiával, Azáriával az Obed fiával, Maaséjával az Adája fiával, és Elisafáttal a Zikri fiával;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'A kik Júda országát körüljárván, összegyűjték Júdának minden városaiból a Lévitákat és az Izráel családfőit, és jövének Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'Szövetséget tőn pedig mind az egész gyülekezet a királylyal az Isten házában, minekutána Jójada ekképen szólott nékik: Ímé a király fia fog uralkodni, a mint az Úr szólott volt a Dávid fiairól;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'Azért ez az a dolog, amit cselekednetek kell: Harmadrész közületek, a kik a szombatra szoktatok feljönni a papok és a Léviták közül, ajtónálló legyen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'Harmadrész a király házánál, és harmadrész a főkapunál álljon; az egész nép pedig legyen az Úr házának pitvariban;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'Senki ne menjen be az Úr házába, hanem csak a papok és a kik szolgálnak a Léviták közül, csak ők menjenek be, mert szent dologra rendeltettek; az egész nép tartsa magát az Úr parancsolatjához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'És a Léviták vegyék körül a királyt, fegyvere mindenkinek kezében legyen, és ha valaki bemenne a házba, ott megölettessék; és a király mellett legyetek, mikor bemegy és mikor kijön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'És mind a szerint cselekedének a Léviták és az egész Júda, a mint Jójada pap megparancsolá, és kiki maga mellé vevé az ő embereit, mindazokat, a kik felmennek vala a szombatra, mind a kik kijőnek vala szombaton; mert Jójada pap nem ereszté el a csapatokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'És Jójada pap a századosoknak azokat a dárdákat, paizsokat és pánczélokat adá, a melyek Dávid királyéi voltak, a melyek az Isten házában valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'És állítá az egész népet, mindenkinek fegyvere kezében lévén, a ház jobb oldalától fogva a ház bal oldaláig, az oltár mellett és a ház mellett a király körül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'Akkor kihozák a király fiát, és reá tevék a koronát és a bizonyságtételt, és királylyá tevék őt, és megkenék őt Jójada és az ő fiai, mondván: Éljen a király!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'Mikor pedig meghallotta Athália a futkosó nép szavát, a kik a királyt dícsérik vala; akkor ő is felméne a nép közé az Úr házába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'És mikor látta, hogy a király az ő oszlopánál áll a bejáratnál, s a fejedelmek és a trombitások a király mellett vannak, és hogy az egész föld népe örül, trombitál, s az énekesek a zengő szerszámokkal énekelnek, a kik tudósok valának az isteni dícséretben: megszaggatá Athália az ő ruháit, és monda: Árulás, árulás!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'És kiküldé Jójada pap a századosokat, a sereg előljáróit, mondván nékik: Vezessétek ki a rendek között; és ha valaki utána menne, fegyverrel ölettessék meg. Mert ezt mondja vala a pap: Ne öljétek meg őt az Úr házában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'Helyet adának azért néki, hogy kimehessen, és mikor jutott volna a király háza felé a lovak kapujáig, ott megölték őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'Szövetséget tőn pedig Jójada ő maga között, az egész nép között és a király között, hogy ők az Úr népei legyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'És beméne az egész sokaság a Baál házába, és azt elrontá, és annak mind oltárait, mind bálványait összetöré; Mattánt pedig, a Baál papját az oltárok előtt ölék meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'És gondviselőket állíta Jójada az Úr házába, a lévitai papok által, a kiket Dávid csoportokba osztott az Úr házában, hogy áldoznának égőáldozatokkal az Úrnak, a mint a Mózes törvényében megíratott, nagy vígassággal és énekszóval, a Dávid rendelése szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'És állítá az ajtónállókat az Úr házának kapuihoz, hogy be ne mehessen, a ki tisztátalan bármely dolog által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'Azután maga mellé vevé a századosokat és a főembereket és a kik a nép felett uralkodnak, s az egész ország népét, és kivezetvén a királyt az Úr házából, bemenének a király házának felső kapuján, és ülteték a királyt a királyiszékbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'És örvendezett a föld minden népe, és a város is megnyugovék; minekutána Atháliát megölék fegyverrel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'Hét esztendős vala Joás, mikor uralkodni kezde, és uralkodék Jeruzsálemben negyven esztendeig; az ő anyjának neve Sibia vala, Beersebából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'És cselekedék Joás az Úr előtt kedves dolgot, Jójada papnak teljes életében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'Vett pedig néki Jójada két feleséget, és nemze fiakat és leányokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'Ezek után elvégezé magában Joás, hogy megújítja az Úrnak házát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'És összehivatá a papokat és a Lévitákat, és monda nékik: Menjetek el a Júda városaiba, és szedjetek az Izráel népétől fejenként pénzt, hogy a ti Istentek háza esztendőnként kijavíttassék. Ti pedig siessetek e dologgal; de a Léviták nem sietének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'Akkor hivatá a király Jójadát a papifejedelmet, és monda néki: Miért nem gondoltál a Lévitákra, hogy behozzák Júdából és Jeruzsálemből az ajándékot, a melyet rendelt Mózes az Úr szolgája és az Izráel gyülekezete, a gyülekezet sátorához?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'Mert az istentelen Athália és az ő fiai elpusztították az Isten házát, és mindazt, a mi az Úr házának vala szentelve, a bálványokra költötték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'És mikor parancsolt a király, csinálának egy ládát, melyet az Úr házának kapuja előtt helyezének el, kivül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'És kihirdeték Júdában és Jeruzsálemben, hogy hozzák el az Úrnak az ajándékot, a melyet az Isten szolgája Mózes parancsolt a pusztában Izráelnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'Akkor a vezérek mindnyájan és az egész nép örömmel vivék az ő ajándékaikat és veték a ládába, míg megtelék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'És időnként a Léviták által elviteték a ládát a király gondviselőjéhez, és mikor látták, hogy sok pénz van benne, eljövén a király íródeákja és a főpap választott embere, kiüríték a ládát, s azután ismét visszavitték helyére. Ezt művelék időnként, és nagy összeg pénzt gyűjtének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'És adá azt a király és Jójada az Úr háza körül való munka felügyelőjének; és fogadának favágókat és ácsokat az Úr házának újítására, vas- és rézműveseket is az Úr házának megerősítésére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'Munkálkodának azért a művesek, és az ő kezök által a kijavítás előrehaladt, s az Úrnak házát előbbi állapotába helyezék, és megerősíték azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'Mikor pedig elvégezték, a megmaradt pénzt vivék a királynak és Jójadának, melyből csinálának az Úr háza számára edényeket, az isteni tisztelet és áldozat számára kanalakat, s arany és ezüst edényeket. És áldozának vala égőáldozatokkal szüntelen az Úrnak házában, Jójadának, teljes életében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'Megvénhedék pedig Jójada, és megelégedvén életével, meghala. Százharmincz esztendős korában hala meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'És eltemeték őt a Dávid városában a királyok között, mivel kedves dolgot cselekedett vala Izráelben mind Istennel s mind az ő házával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'Minekutána pedig meghala Jójada, eljövének a Júda fejedelmei, és meghajták magokat a király előtt; a király pedig hallgatott reájok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'És elhagyák az Úrnak, atyáik Istenének házát, és szolgálának az Aseráknak és bálványoknak; mely vétkök miatt lőn az Úrnak haragja Júda és Jeruzsálem ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'És külde hozzájuk prófétákat, hogy visszatérítenék őket az Úrhoz, a kik bizonyságot tevének ellenök, de nem hallgattak reájok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'Az Isten lelke pedig felindítá Zakariást, a Jójada pap fiát, a ki felálla a nép között, és monda nékik: Ezt mondja az Isten: Miért szegtétek meg az Úrnak parancsolatait? – mert az nem használ néktek. Ha elhagytátok az Urat, ő is elhagy titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'Amazok pedig reá támadván, ott az Úr háza pitvarában megkövezék őt a király parancsolatjából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'És nem emlékezék meg Joás király a jótéteményről, a melylyel annak atyja, Jójada vala ő hozzá éltében, hanem megöleté a fiát. Mikor pedig meghalna, ezt mondá: Látja az Úr és bosszút áll!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'És már az esztendő elmúltával feljöve ellene Siria királyának serege, és méne Júdára és Jeruzsálemre, és kiirtották a népnek minden vezéreit a nép közül, és minden zsákmányukat küldék Damaskusba a királynak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'Mert noha kevés emberrel jött vala rájok a Siriabeli had, mindazáltal az Úr kezökbe adá Júdának nagy seregét, mivel az Urat, atyáiknak Istenét elhagyták; és Joáson is bosszút állának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'És mikor tőle elmentek (súlyos betegségben hagyták hátra): pártot ütének ellene az ő szolgái, a Jójada pap fiának haláláért, és megölék őt ágyában, és meghala. És eltemeték őt a Dávid városában, de nem temeték őt a királyok sírjába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'Ezek ütöttek ellene pártot: Zabád, az Ammonbeli Simeát asszony fia, és Józabád, a Moábbeli Simrith fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'Az ő fiai, és alatta az adónak megszaporodása, s az Isten házának kijavítása, ímé meg vannak írva a királyok könyvének magyarázatában. Uralkodék helyette az ő fia, Amásia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'Huszonöt esztendős korában kezdett Amásia uralkodni, és huszonkilencz esztendeig uralkodék Jeruzsálemben; az ő anyjának neve Jéhoaddán vala, Jeruzsálemből való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'És kedves dolgot cselekedék az Úr előtt; de nem tiszta szívből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'Lőn pedig azután, hogy országában megerősödék, megölé az ő szolgáit, a kik a királyt, az ő atyját megölték vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'De azoknak fiait nem öleté meg, hanem a szerint cselekedék, a mint a törvényben, a Mózes könyvében megiratott, a melyben az Úr parancsolt volt, mondván: Meg ne ölettessenek az atyák a fiakért és a fiak se ölettessenek meg az atyákért, hanem kiki az ő saját bűnéért ölettessék meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'Összegyűjté annak felette Amásia a Júda népét, és választa közülök a nemzetségek szerint egész Júdában és Benjáminban ezredeseket és századosokat; és megszámlálá őket a húsz esztendősöktől fogva és a kik feljebb valának, és talála azok közül válogatott fegyverfoghatókat, kopjásokat és paizsosokat, háromszázezeret.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'Annakfelette az Izráeliták közül százezer erős vitézt fogadott fel, száz talentom ezüstön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'Eljöve pedig az Isten embere ő hozzá, mondván: Oh király! ne menjen el te veled Izráel serege, mert az Úr nem lesz Izráellel, Efraim minden fiaival.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'Ha nem hiszed, ám menj el, készülj a viadalhoz; de megver az Isten téged az ellenség előtt; mert az Isten hatalmában van mind a segítség, mind a megveretés.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'Akkor monda Amásia az Isten emberének: De mit tegyünk a száz talentom ezüsttel, a melyet Izráel seregének adtam? És felele az Isten embere: Az Úr néked annál sokkal többet adhat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'Kiválasztá azért Amásia azt a sereget, a mely Efraimból jött vala ő hozzá, hogy mennének helyökre; mely dologért igen megharagvának a Júda népére, és felgerjedt haraggal tértek vissza helyeikre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'Amásia pedig felbátorodván, elindítá népét, és méne a sós völgybe; és megvere a Seir fiai közül tízezeret.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'És Júda fiai tízezeret élve fogtak el, a kiket egy magas kőszikla tetejére vivének, és letaszították őket a magas kőszikláról, és mindnyájan összeroncsoltattak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'Annak a seregnek fiai pedig, a kiket visszakülde Amásia, hogy ne menjenek ő vele hadba: Júdának városaira ütének Samariától fogva mind Bethóronig; és levágván háromezeret azok közül, nagy zsákmányt vivének el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'Lőn azután, hogy Amásia megtére az Edomiták megveréséből, a Seir fiainak isteneit elhozá és Isten gyanánt tisztelé azokat, a kik előtt magát meghajtja vala, és nékik jóillatot gerjeszte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'Ezért megharaguvék az Úr Amásiára, és prófétát külde hozzá, a ki monda néki: Miért imádod annak a népnek isteneit, a kik nem szabadíthatták meg az ő népöket a te kezedből?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'Lőn pedig, mikor ekképen szólott volna néki, monda néki a király: Vajjon te tanácsosa vagy-é a királynak? Hallgass, mert rosszul jársz. Megszünék azért a próféta, minekutána ezt mondotta volna: Látom, hogy az Isten el akar téged veszteni, mivel ezt műveléd, és tanácsomat nem fogadád meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'Amásia pedig, a Júda királya, tanácsot tartván, követet külde Joáshoz, a Joákház fiához, a ki Jéhunak fia vala, az Izráel királyához, mondván: Nosza, szálljunk szembe egymással!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'Akkor Joás, az Izráel királya ilyen választ ada Amásiának, a Júda királyának: A Libánus hegyén való tövis külde a Libánuson való czédrusfához, mondván: Add a te leányodat az én fiamnak feleségül; eközben azonban arra menvén egy fenevad, a mely a Libánuson lakik vala, eltapodá azt a tövist.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Te magadban így gondolkodtál: Megveréd az Edomitákat, azért fuvalkodtál fel magadban, hogy dicsekedjél. Kérlek, maradj otthon, miért szereznél magadnak veszedelmet, hogy te és Júda elveszszen általam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'De Amásia nem nyugodhatott, mert Isten elvégezte vala, hogy az ellenség kezébe adja őket, mivel az Edomiták isteneit keresték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'Felindula azért Joás, az Izráel királya, és szembeszállának egymással ő és Amásia, a Júda királya Béth-Semesnél, a mely Júdában van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'És Júda megveretteték Izráel által, és elmenekülének mindnyájan sátoraikba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'Amásiát pedig, a Júda királyát, a Joás fiát, a ki Joákház fia volt, Joás, az Izráel királya elfogá Béth-Semesben, és vivé őt Jeruzsálembe, és Jeruzsálem kőfalát lerontá az Efraim kaputól fogva mind a szeglet kapujáig négyszáz singnyire.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'És az aranyat, az ezüstöt és mindenféle edényeket, a melyek az Isten házában, az Obed-Edom birtokában találtatának, és a király házának kincseit, s a kezesek fiait mind Samariába vivé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'Amásia, a Joás fia, a Júda királya, minekutána meghala Joás, a Joákház fia, az Izráel királya, még tizenöt esztendeig éle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'Amásiának pedig többi dolgai, az elsők és utolsók, avagy nincsenek-é megírva a Júda és az Izráel királyainak könyvében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'Azon időtől fogva pedig, hogy Amásia az Úrtól elszakada, összeesküvést szőttek ellene Jeruzsálemben; és elmeneküle Lákisba, de utána küldöttek Lákisba, és megölték ott őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'És elhozák onnét lovakon, és eltemeték őt az ő atyáival, Júdának városában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'Akkor előhozván az egész Júda nemzetsége Uzziást (ki tizenhat esztendős vala), királylyá tevék őt az ő atyja Amásia helyett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'Ő építé meg Elótot, és csatolta ismét Júdához, minekutána Amásia király meghalt az ő atyáival egybe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'Tizenhat esztendős korában kezdett vala uralkodni Uzziás, és ötvenkét esztendeig uralkodék Jeruzsálemben; az ő anyjának neve Jékólia vala, Jeruzsálemből való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'És az Úr előtt kedves dolgot cselekedék, a mint az ő atyja, Amásia is cselekedett vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'És keresi vala az Istent Zakariás próféta idejében, a ki az isteni látásokban értelmes vala; és mindaddig, míg az Urat keresé, jó előmenetelt adott néki Isten;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'Mert kimenvén, hadakozék a Filiszteusok ellen; és a Gáth kerítését, a Jabné kerítését és az Asdód kerítését letöré, és építe városokat Asdódban és a Filiszteusok tartományában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'És megsegéllé őt az Isten a Filiszteusok ellen és az Arábiabeliek ellen, a kik lakoznak vala Gúr-Baálban, és Meunimban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'És adának az Ammoniták Uzziásnak ajándékot, és elterjede az ő híre Égyiptomig; mert felette igen megnevekedett az ő hatalma;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'És építe Uzziás tornyokat Jeruzsálemben a szeglet kapuja felett, a völgy kapuja felett és a szegletek felett, és igen megerősítteté azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'A pusztában is tornyokat épített, és sok kutat ásatott; mert sok nyája vala mind a völgyekben, mind a lapályon, és szántóvető szolgái, vinczellérei a hegyeken és Kármelben, mert a földművelést kedvelte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'Uzziásnak hadakozó serege is vala, a mely harczba mehetett csapatonként, a mint megszámláltatott Jéhiel íródeák és Maaséja előljáró által Hanániás vezetése alatt, a ki a király vezérei közül való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'A családfők egész száma a hadakozó vitézek között kétezerhatszáz vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'És az ő kezök alatt levő hadakozó sereg háromszázhétezerötszáz harczosból állott, a kik képesek valának megsegíteni a királyt ellenségei ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'És készíttete Uzziás nékik, az egész sereg számára paizsokat, kopjákat, sisakokat, pánczélokat, íveket és parittyába való köveket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'Készíttete annakfelette Jeruzsálemben értelmes mesteremberek által gépezeteket a tornyok tetején és a kőfal szegletein, nyilaknak és nagy köveknek kihajigálására. És az ő híre messzire elterjede; mert csudálatosan megsegítteték, míglen megerősödék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'Mikor pedig ilyen módon megerősödött volna, felfuvalkodék, hogy megfertőztetné magát és vétkezék az Úr ellen, az ő Istene ellen. Beméne az Úr templomába, hogy a füstölő oltáron füstölne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'És beméne ő utána Azáriás pap, és vele az Úr papjai nyolczvanan, igen erősek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'És ellene állának Uzziás királynak, és mondának néki: Uzziás! nem a te dolgod az Úrnak füstölni, hanem az Áron pap fiaié, a kik felszenteltetének, hogy füstöljenek. Menj ki e szent helyből; mert igen vétkeztél és dicsőségedre nem leend az Úr Istentől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'És megharaguvék Uzziás, a kinek kezében vala a füstölő szerszám, hogy füstölne; és mikor haragudnék a papokra, bélpoklosság támada a homlokán ott a papok előtt, az Úr házában, a füstölő oltár előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'És mikor tekintett volna ő reá Azáriás főpap, és vele mind a többi papok, láták a bélpoklosságot az ő homlokán; és elűzék őt onnét, sőt maga is sietett kimenni, mert az Úr megverte vala őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'És lőn Uzziás király halála napjáig bélpoklos; és lakik vala egy elkülönített házban bélpoklosan, mert az Úr házából kivettetett vala. És Jótám, az ő fia vala a király házában, a ki ítélkezék az ország népe felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'Uzziásnak pedig első és utolsó dolgait megírta Ésaiás próféta, az Ámós fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'És meghala Uzziás az ő atyáival egybe, és eltemeték őt az ő atyáival a temetőbe, a mely a királyoké vala, mert ezt mondják felőle: bélpoklos volt. És uralkodék helyette Jótám, az ő fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'Huszonöt esztendős vala Jótám, mikor uralkodni kezde, és tizenhat esztendeig uralkodék Jeruzsálemben; az ő anyjának neve Jérusa vala, a Sádók leánya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'És kedves dolgot cselekedék az Úr előtt, mint az ő atyja, Uzziás is cselekedett vala, csakhogy nem méne az Úr templomába; a nép azonban tovább is vétkezék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'Ő építé meg az Úr házának felső kapuját; a vár kőfalán is sokat építe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'Annakfelette a Júda hegyes földén városokat építe, és a ligetekben palotákat és tornyokat építe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'Ő is hadakozott az Ammon fiainak királyai ellen, a kiket megvere; és adának néki az Ammon fiai azon esztendőben száz tálentom ezüstöt s tízezer véka búzát és tízezer véka árpát. Ezt fizették néki az Ammon fiai a második és harmadik esztendőben is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'És hatalmassá lőn Jótám, mert útjában az Úr előtt, az ő Istene előtt járt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'Jótámnak pedig több dolgait, minden hadakozásait és útjait, ímé megírták az Izráel és a Júda királyainak könyvében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'Huszonöt esztendős korában kezdett uralkodni, és tizenhat esztendeig uralkodék Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'És elaluvék Jótám az ő atyjával, és eltemeték őt a Dávid városában; és uralkodék Akház, az ő fia helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'Húsz esztendős volt Akház, mikor uralkodni kezdett, és tizenhat esztendeig uralkodék Jeruzsálemben, és nem cselekedék kedves dolgot az Úr előtt, mint Dávid, az ő atyja;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'Hanem az Izráel királyainak útján járt, és öntött bálványokat is csináltatott a Baál tiszteletére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'Annakfelette tömjéneze a Hinnom fiának völgyében; fiait is megégeté tűzben, a pogányok útálatosságai szerint, a kiket az Úr az Izráel fiai elől kiűzött volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'Áldozék és tömjéneze a magaslatokon is, a halmokon is és minden zöld fa alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'Ezért az Úr az ő Istene adá őt a Siriabeli király kezébe, és őt igen megverék, és sok foglyot hurczolának el ő tőle, a kiket Damaskusba vivének. Sőt még az Izráel királya kezébe is adaték, és az is igen megveré őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'Mert Pékah, a Rémália fia, Júdában egy nap levága százhúszezer embert, mind vitézeket; mivel elhagyták az Urat, atyáik Istenét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'Annakfelette az Efraimbeli vitéz Zikri megölé Maásiát, a király fiát, Azrikámot, az ő házának gondviselőjét, és Elkánát, a ki a király után második vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'És elvivének az Izráel fiai az ő atyjokfiai közül kétszázezer asszonyt, fiút, leányt, és nagy vagyont rablának el tőlök, és azzal a zsákmánynyal mennek vala Samariába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'Vala pedig ott az Úrnak egy prófétája, a kinek neve Odéd, a ki eleibe menvén a hadnak, a mely Samariába megy vala, monda nékik: Ímé, mivel az Úrnak, atyáitok Istenének haragja Júda ellen felgerjedett, őket kezetekbe adta, és ti sokat megölétek közülök haragotokban, a mely szintén az égig felhatott;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'És immár arra gondoltok, hogy Júdának és Jeruzsálemnek fiait megalázzátok, hogy néktek szolgáitok és szolgálóleányitok legyenek: avagy ezáltal nem teszitek-é magatokat bűnösökké az Úrnál, a ti Isteneteknél?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'Azért halljátok meg szómat: Vigyétek vissza a ti atyátokfiai közül való foglyokat, a kiket ide hoztatok; különben az Úrnak nagy haragja lészen rajtatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'Akkor felkelének némelyek az Efraimból való vezérek közül: Azáriás, a Jóhanán fia; Berékiás, a Mesillemót fia; Ezékiás, a Sallum fia, és Amása a Hadlai fia, azok ellen, a kik a viadalból jőnek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'És mondának nékik: Ne hozzátok ide be a foglyokat, mert felette igen nagy bűn lesz az, a mit akartok művelni, és ezzel a mi bűneinket és vétkeinket megsokasítjátok; mert e nélkül is sok bűnünk van, és felgerjedt a harag Izráel ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'Ott hagyá azért a sereg a foglyokat és a zsákmányt a vezérek és az egész gyülekezet előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'És felállának a névszerint megnevezett férfiak, s felvevék a foglyokat, és a kik mezítelenek valának közülök, felöltözteték a zsákmányból; felöltözteték azokat, sarukat is adának lábaikra; ételt és italt is adának nékik; sőt meg is kenék őket, és a gyengélkedőket szamarakra helyezék, és vivék őket a pálmafák városába, Jérikhóba, az ő atyjokfiaihoz; azután megtérének Samariába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'Az időben külde Akház király az Assiriabeli királyhoz, hogy megsegítené őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'Mert még az Edomiták is eljöttek vala, és a Júdabeliek közül sokat levágának, vagy rabságba hurczolának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'A Filiszteusok is mind ellepék a lapályon való városokat és Júdának dél felől való részét, és elfoglalák Béth-Semest, Ajalont, Gederótot, Sókot és annak faluit; Timnát és annak faluit; Gimzót és annak faluit, és ott laknak vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'Mert az Úr megalázta Júdát Akházért, az Izráel királyáért; mert arra indítá Júdát, hogy vétkezzék az Úr ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'Eljöve azért ő ellene Tiglát-Piléser, Assiria királya, a ki sanyargatá őt, és nem segítette meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'Mert Akház kifosztá az Úr házát, a királyét, a fejedelmekét, és az Assiriabeli királynak adá, de azért nem lőn néki segítségére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'Sőt még a szorongattatás idejében is tovább vétkezék az Úr ellen; ilyen vala Akház király.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'Mert áldozék Damaskus isteneinek, a kik őt megverték vala, ezt mondván: Mivel Siria királyainak istenei megsegítik őket, azért én is azoknak áldozom, hogy segéljenek engem is, holott mind néki, mind az egész Izráelnek azok okozták romlását.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'És összehordá Akház az Isten házának edényeit, és összetöré az Isten házának edényeit, és az Úr házának ajtait bezárá, és csinála a maga számára oltárokat Jeruzsálemnek minden szegletén;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'Júdának minden városaiban is magaslatokat építe, hogy az idegen isteneknek tömjénezzen, és haragra ingerlé az Urat, atyái Istenét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'Az ő több dolgai pedig és útjai, úgy az elsők, mint utolsók, ímé meg vannak írva a Júda és az Izráel királyainak könyvében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'Meghala pedig Akház az ő atyáival, és eltemeték őt Jeruzsálem városában; mert nem vivék őt az Izráel királyainak sírjába. És uralkodék az ő fia, Ezékiás, ő helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'Ezékiás huszonöt esztendős korában kezdett uralkodni, és uralkodék huszonkilencz esztendeig Jeruzsálemben; az ő anyjának neve vala Abija, a Zakariás leánya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'És kedves dolgot cselekedék az Úr előtt, mind a szerint, a mint Dávid, az ő atyja is cselekedett vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'És az ő királyságának első esztendejében, az első hónapban kinyitá az Úr házának ajtait, és azokat megújíttatá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'És egybehivatá a papokat és a Lévitákat, és összegyűjté őket a napkelet felől való utczában;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'És monda nékik: Hallgassatok meg engem Léviták! Most szenteljétek meg magatokat, az Úrnak, atyáitok Istenének házát is szenteljétek meg, és hordjatok ki minden tisztátalanságot a szent helyről;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'Mert vétkeztek a mi atyáink, és az Úr előtt, a mi Istenünk előtt gonoszul cselekedének, és elhagyták őt, az Úr sátorától elfordították arczukat, hátat fordítván annak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'A tornácz ajtait is bezárták, a szövétnekeket eloltották, és füstölőszert nem füstölögtettek és égőáldozatot nem áldoztak az Izráel Istenének a szent helyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'És ezért volt az Úrnak haragja Júdán és Jeruzsálemen, és adta volt őket rabságra és pusztulásra és kigunyoltatásra, a mint ti magatok is látjátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'És ímé a mi atyáink fegyver által hullottak el, fiaink, leányaink és feleségeink fogságba vitettek e dolog miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'Most azért elvégeztem magamban, hogy az Úrral, Izráel Istenével szövetséget szerzek, hogy haragját tőlünk elfordítsa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'Fiaim, most ne tévelyegjetek; mert az Úr választott titeket, hogy ő előtte állván, néki szolgáljatok; hogy szolgái legyetek néki és jóillatot szerezzetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'Felkelének azért a Léviták: Máhát az Amásai fia, Jóel az Azárja fia, a kik Kéhátiták valának; a Mérári fiai közül pedig Kis az Abdi fia, és Azária a Jéhalélel fia, és a Gersoniták közül Joah a Zimma fia, és Éden a Joah fia;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'Az Elisáfán fiai közül Simri és Jéhiel; az Asáf fiai közül Zakariás és Mattánia;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'A Hemán fiai közül Jéhiel és Simei; a Jédutun fiai közül Semája és Uzziel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'Összegyűjték az ő atyjokfiait, és megszentelék magokat, és bemenének a király parancsolatjából az Úrnak beszédei szerint, az Úr házának megtisztítására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'És bemenének a papok az Úr házának belső részébe, hogy azt megtisztítsák; kihordának belőle minden tisztátalanságot, a melyet az Úr templomában találának, az Úr házának pitvarába; és a Léviták felszedék, hogy onnan kihordják a Kidron patakába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'Elkezdék pedig a megszentelést az első hónap első napján, és a hónap nyolczadik napján bemenének az Úr házának tornáczába, és megszentelék az Úr házát nyolcz napon át, úgy hogy az első hónap tizenhatodik napján végezték be.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'És akkor bemenének Ezékiás királyhoz, és mondának: Megtisztítottuk mindenestől az Úr házát, az égőáldozat oltárát is, minden hozzá tartozó edényekkel egybe, a szent asztalt is, minden szerszámaival;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'Minden egyéb eszközöket is, a melyeket Akház király az ő királysága alatt megszentségtelenített, mikor Isten ellen vétkezett vala, helyreállítottunk és megszenteltünk, és ímé mind az Úr oltára előtt vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'Reggel azért felkele Ezékiás király, és összegyűjté a város fejedelmeit, és felméne az Úr házába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'És vivének fel hét tulkot és hét kost, hét bárányt és hét bakot bűnért való áldozatra az országért, a szent hajlékért és Júdáért, és megparancsolá az Áron fiainak, a papoknak, hogy megáldozzák az Úr oltárán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'Megölék azért a tulkokat, és a papok azoknak véröket vévén, elhinték az oltárra; hasonlatosképen megölvén a kosokat, elhinték azoknak véröket az oltárra; a bárányokat is megölvén, azoknak vérét az oltárra hinték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'Azután előhozák a bűnért való bakokat a király és a gyülekezet elé, és kezöket rájok tevék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'Minekutána a papok azokat megölték, bűnért való áldozást végeztek a vérökkel az oltáron, az egész Izráel megtisztulására; mert az egész Izráelért parancsolta vala a király az égőáldozatot és a bűnért való áldozatot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'És beállítá a Lévitákat az Úr házába czimbalmokkal, lantokkal és cziterákkal Dávidnak és Gádnak a király prófétájának, és Nátán prófétának parancsolatja szerint; mert az Úrtól volt a parancs az ő prófétái által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'Előállának azért a Léviták a Dávid zengő szerszámaival; a papok is a trombitákkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'És megparancsolá Ezékiás, hogy egészen égőáldozatot áldozzanak az oltáron. És mikor megkezdődött az áldozás ugyanakkor megkezdődött az Úrnak éneke is és a trombiták harsonája Dávidnak az Izráel királyának szerszámaival.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'És az egész gyülekezet leborula, az énekesek énekelének, és a trombitások trombitálának mindaddig, míg az egészen égőáldozatnak vége lőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'És a mikor elvégezték az áldozatokat, a király és mindnyájan a vele valók leborulván arczczal, imádkozának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'És megparancsolá Ezékiás király és a fejedelmek a Lévitáknak, hogy az Urat dícsérjék a Dávid és az Asáf próféta dicséreteivel; a kik, mikor nagy örömmel dícsérték az Urat, meghajoltak és leborulának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'Azután szóla és monda Ezékiás: Most már felavattátok magatokat az Úrnak, azért jőjjetek, és hozzatok áldozatokat és dícsérő áldozatokat az Úr házában. És az egész gyülekezet hoza áldozatokat és dícsérő áldozatokat, és mindaz a kit a szíve indított, egészen égőáldozatot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'És az égőáldozatra való barmok száma, a melyeket a gyülekezet hozott vala, ez volt: hetven tulok, száz kos, kétszáz bárány. Mindezek egészen égőáldozatul valának az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'Azonkivül szenteltek az Úrnak hatszáz tulkot és háromezer juhot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'De mivel a papok kevesen valának, és nem győzték az áldozatokat mind megnyúzni, ezért az ő atyjokfiai, a Léviták segítségökre valának nékik mindaddig, míg azt a munkát elvégezék, és míg a többi papok magokat megszentelék; mert a Léviták igazabb szívűek valának a magok megszentelésében, mint a papok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'Az egészen égőáldozat is igen sok volt a hálaáldozatok kövérivel és az egészen égőáldozatokhoz való italáldozatokkal; és ekképen helyreállíttatott az Úr házának szolgálata.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'Örvendeze azért Ezékiás és ő vele az egész gyülekezet, hogy az Isten erre hajlandóvá tette a népet; mert hirtelen történt ez a dolog.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'És külde Ezékiás az egész Izráelhez és Júdához, sőt Efraimnak és Manassénak is íra leveleket, hogy jönnének el az Úr házához Jeruzsálembe, hogy megtartanák a páskhát az Úrnak, Izráel Istenének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'És tanácsot tarta a király és fejedelmei s az egész gyülekezet Jeruzsálemben, hogy a második hónapban tartsák meg a páskhát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'Mert azt akkor nem tarthatták meg, mert a papok nem szentelhették meg magokat kellő számban, s a nép sem gyűlt vala össze Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'És e dolog igen tetszék mind a királynak, mind az egész gyülekezetnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'Elhatározták tehát, hogy kihirdetik egész Izráelben Beersebától fogva Dánig, hogy jőjjenek Jeruzsálembe páskhát szentelni az Úrnak, Izráel Istenének, mert már régóta nem tartották meg úgy, a mint megiratott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'Elmenének azért a híradók a király levelével és a fejedelmekével az egész Izráelhez és Júdához, és a király parancsolatjából ezt mondják vala: Izráel fiai! térjetek meg az Úrhoz, Ábrahámnak, Izsáknak és Izráelnek Istenéhez s ő is megtér a maradékhoz, mely megmaradt még köztetek az Assiriabeli királyok kezétől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'És ne legyetek olyanok, mint a ti atyáitok és atyátokfiai, a kik vétkeztek volt az Úr ellen, atyáik Istene ellen és elpusztította őket, a mint ti magatok látjátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'Most azért meg ne keményítsétek nyakatokat, mint a ti atyáitok; adjatok kezet az Úrnak, és bemenvén az ő szent helyébe, a melyet megszentelt örökké, szolgáljatok az Úrnak, a ti Istenteknek, és elfordul rólatok haragja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'Mert hogy ha ti megtéréndetek az Úrhoz, a ti atyátokfiai és fiaitok kegyelmet találnak azoknál a kik őket fogságba vitték, és megtérnek erre a földre, mert irgalmas és kegyelmes az Úr, a ti Istentek, és nem fordítja el orczáját tőletek, ha ő hozzá megtéréndetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'Mikor pedig a híradók városról-városra menének az Efraim és a Manasse földén, mind Zebulonig, nevetik és csúfolják vala őket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'Mindazáltal némelyek az Áser, Manasse és a Zebulon nemzetségéből megalázák magokat, és eljövének Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'Júdában is ezt cselekedé az Istennek keze, adván beléjök egy akaratot, hogy engednének a király parancsolatjának és a fejedelmekének az Úr beszéde szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'Sok nép gyűle azért Jeruzsálembe, hogy a kovásztalan kenyerek ünnepét megtartsák a második hónapban; igen nagy gyülekezet vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'És felkelének, és elronták az oltárokat, a melyek Jeruzsálemben valának, és a füstölő oltárokat is mind elronták, és a Kidron patakába hányták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'És megölék a páskhabárányt a második hónap tizennegyedik napján; s a papok és Léviták megszégyenlék és megszentelék magokat, és égőáldozatokat vittek az Úr házába;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'És kiki álla az ő helyére az ő szokások szerint és Mózesnek az Isten emberének törvénye szerint, és a papok hintik vala a vért a Léviták kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'Minthogy pedig igen sokan valának a gyülekezetben, a kik magokat meg nem szentelték vala, ezért a Léviták a páskhabárány megölésével foglalkozának azokért, a kik tisztátalanok voltak, hogy megszenteljék az Úrnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'Mert a népnek nagy része, sokan az Efraim, Manasse, Izsakhár és Zebulon nemzetségéből, nem szentelték meg magokat, mindazáltal megevék a páskhabárányt, nem úgy, a mint megiratott; de könyörge Ezékiás érettök, mondván: A kegyes Úr tisztítsa meg azt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'Mindenkit, a ki szívét elkészítette, hogy keresse az Istent, az Urat, az ő atyái Istenét, ha nem a szentségnek tisztasága szerint is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'És meghallgatá az Úr Ezékiást, és a népnek megkegyelmeze.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'Megtartották tehát az Izráel fiai, a kik Jeruzsálemben találtatának, a kovásztalan kenyerek ünnepét hét napon át nagy örömmel, és dícsérik vala az Urat minden nap a Léviták és a papok, az Úr erejét éneklő szerszámokkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'És kegyesen beszéle Ezékiás minden Lévitával, a kik értelmesek és jóindulattal valának az Úr iránt. És ünnepi lakomát tartottak hét napon át, áldozván hálaadó-áldozatokkal, és dícsérvén az Urat, atyáik Istenét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'Tanácsot tarta pedig az egész gyülekezet, hogy még hét napig szentelne ünnepet; és így még hét napot töltöttek el vígasságban;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'Mert Ezékiás, a Júda királya ada a gyülekezetnek ezer tulkot és hétezer juhot, a fejedelmek is adának a gyülekezetnek ezer tulkot és tízezer juhot; és megszentelék magokat a papok elegen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'Nagy örömben vala azért az egész Júda gyülekezete, a papok és a Léviták és azoknak egész gyülekezete, a kik Izráelből oda mentek vala; mind az idegenek, a kik az Izráel földjéről jöttek vala, mind a Júdában lakozók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'És volt nagy vígasság Jeruzsálemben; mert Salamonnak, az Izráel királyának, Dávid fiának idejétől fogva nem volt ehez hasonló ünnep Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'Ezek után felállának a papok és a Léviták, és megáldák a gyülekezetet; és meghallgatásra talált az ő szavok, és felhata az ő könyörgésök mennybe az Isten szentséges lakhelyébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'A mint mindezeknek vége lőn: kiméne az egész Izráel, a kik Júdának városaiban találtatának, s a bálványokat széttörték, az Aserákat kivagdalák, s leronták a magaslatokat és oltárokat egész Júdában, Benjáminban, Efraimban és Manasseban, mígnem befejezték; azután visszatérének az Izráel fiai mind, kiki az ő örökségébe és városaiba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'És helyreállítá Ezékiás a papok és Léviták osztályait csoportjaik szerint, kit-kit az ő szolgálata szerint, a papokat és a Lévitákat az égőáldozatokra és a hálaadó-áldozatokra, a szolgálatra, hálaadásra és dícséretre az Úr táborinak kapuiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'És rendelé a király az ő jövedelmének egy részét az égőáldozatok számára, a reggeli és estvéli égőáldozatok, a szombatnapok, az újhold és az ünnepek égőáldozatai számára, a mint megiratott az Úr törvényében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'Meghagyá a népnek is, Jeruzsálem lakosinak, hogy megadják a papok és a Léviták járandóságát, hogy az Úr törvényéhez annál inkább ragaszkodjanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'A mint ez intézkedés híre elterjedt: az Izráel fiai a búzának, a bornak és olajnak, a méznek és minden mezei termésnek zsengéjét bőséggel megadák; és mindenből a tizedet bőséggel meghozák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'És az Izráel és Júda fiai, a kik lakoznak vala a Júda városaiban, ők is elhozák a barmokból és juhokból a tizedet, és annak tizedét, a mi az Úrnak, az ő Istenöknek szenteltetett, és rakásonként felhalmozák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'A harmadik hónapban kezdék a rakásokat rakni, és a hetedik hónapban végezék el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'Oda menvén pedig Ezékiás és a fejedelmek, és látván a rakásokat: áldák az Urat és az ő népét, Izráelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'Megkérdé pedig Ezékiás a papokat és a Lévitákat a rakások felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'Kinek felelvén Azáriás, a főpap, a Sádók nemzetségéből való, monda: Mióta az Úr házába kezdék az ajándékokat hozni: eleget ettünk és sok meg is maradt belőle, mert az Úr megáldotta az ő népét; és ez a rakás, a mi megmaradt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'És monda Ezékiás, hogy az Úr házában csináljanak tárházakat, és megcsinálák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'Behordák azért az ajándékokat, a tizedeket, és a mi megszenteltetett, nagy hűséggel, és ezeknek főgondviselője Konánia Lévita vala, a második pedig ennek atyjafia, Simei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'Jéhiel pedig és Azáriás, Náhát, Asáel, Jérimot, Józabád, Eliel, Ismákia, Máhát és Benája, gondviselők valának, Konániának és atyjafiának Simeinek keze alatt, Ezékiás királynak és Azáriásnak az Isten háza előljárójának parancsolatából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'Kóré Lévita pedig, a Jemna fia, a ki ajtónálló vala napkelet felől, az Isten számára tett önkéntes adományok gondviselője volt, hogy kiadja az Úrnak és a szentek szentjének áldozatát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'Keze alatt valának: Eden, Minjámin, Jésua, Semája, Amária és Sekánia a papok városaiban, hogy hűségesen osztogassák a csapatok szerint az ő atyjokfiainak, úgy a nagynak, mint a kicsinynek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, '(Az ő nemzetségök férfiain kivül, a három esztendős fiútól fogva feljebb) mindenkinek, a kinek bejárása vala az Úr házába a maga napján, a naponként való szolgálatra, rendtartásuk és csapatjaik szerint;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'A papok nemzetségének családjaik szerint; a Lévitáknak is, a kik húsz esztendősök és feljebb valók volnának, az ő rendtartások és csapatjaik szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'És azok családjának minden kisdeddel, feleségeikkel, fiaikkal, leányaikkal, s az egész gyülekezetnek; mert az ő hitök szerint szentelték vala magokat a szentségre;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'Az Áron fiainak is, a papoknak, az ő városaikhoz tartozó vidék környékén, minden városban valának névszerint megnevezett emberek, hogy kiadják a részét minden férfinak a papok közül, és minden nemzetségnek a Léviták között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'És így cselekedék Ezékiás egész Júdában. A mi jó, igaz és helyes vala az Úr előtt, az ő Istene előtt, azt művelé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'És minden munkában, a melyet elkezdett az Isten házának szolgálatában, a törvényben és parancsolatban, keresvén az ő Istenét, teljes szívvel jár vala el, és ezért szerencsés vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'Ezen dolgok és igazságos cselekedetek után eljöve Sénakhérib, az Assiriabeli király, és Júdába menvén, megszállá a megerősített városokat, azt mondván, hogy elfoglalja azokat magának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'Mikor tehát Ezékiás látta, hogy Sénakhérib eljöve, és Jeruzsálemet meg akarná szállani:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'Tanácsot tarta vezéreivel és vitézeivel, hogy a városon kivül való forrásokat betöltsék; és azok segítségére lőnek néki;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'Mert összegyűlvén a sokaság, bedugának minden forrást és az ország közepén folyó patakot, mondván: Miért találjanak az assiriai királyok elegendő vizet, ha eljőnek?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'És felbátorodván, megépíté a város leromlott kerítését, felemelvén a tornyokig, és kivül másik kőfalat is emelt, s Millót a Dávid városában megerősíté; ennekfelette szerze sok fegyvert és paizst.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'És a nép fölé seregvezéreket tett, és maga köré gyűjtvén őket a város kapujának utczájára, szóla az ő szívök szerint ekképen:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, 'Erősek legyetek és bátrak, semmit se féljetek, meg se rettenjetek az assiriai királytól és a vele való egész sokaságtól, mert velünk többen vannak, hogynem ő vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'Ő vele testi erő van, velünk pedig az Úr a mi Istenünk, hogy megsegéljen minket és érettünk hadakozzék. És megbátorodék a nép, ezt hallván Ezékiástól, a Júda királyától.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'Ezek után elküldé szolgáit Sénakhérib, az assiriai király Jeruzsálembe (ő pedig Lákis mellett volt egész seregével) Ezékiáshoz a Júda királyához, és az egész Júdához, mely Jeruzsálemben vala, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, 'Ezt mondja Sénakhérib, az assiriai király: Kiben bíztok, hogy Jeruzsálemben maradtok a megszállás idején?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'Avagy nem Ezékiás áltatott-é el titeket, hogy éhséggel és szomjúsággal ölne meg titeket, mondván: Az Úr, a mi Istenünk megszabadít minket az Assiriabeli király kezéből!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'Avagy nem Ezékiás pusztította-é el az ő magaslatait és oltárait, mikor így szólott Júdához és Jeruzsálemhez, mondván: Csak egy oltár előtt imádkozzatok, és csak azon tömjénezzetek?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'Avagy nem tudjátok-é, mit műveltem én és az én atyáim e föld minden népeivel? Vajjon e föld nemzetségeinek istenei megszabadíthatták-é az én kezemből az ő földöket?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'És kicsoda e nemzetségek istenei közül az, a melyeket az én atyáim elvesztettek, a ki az én kezemből az ő népét megszabadíthatta volna, hogy a ti Istenetek is az én kezemből titeket megszabadíthatna?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'Most azért Ezékiás titeket el ne ámítson és meg ne csaljon ily módon; ne higyjetek néki, mert ha egy népnek és országnak istene sem szabadíthatta meg az ő népét kezemből és az én atyáim kezéből: mennyivel kevésbbé szabadíthat meg titeket a ti Istenetek az én kezemből!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'Sőt ezenkivül az ő szolgái még sokat szólának az Úr Isten ellen, és az ő szolgája Ezékiás ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'Levelet is íra, az Urat, Izráel Istenét káromlással illetvén, és szólván ellene ilyen módon: A mint e földön lakozó népek istenei meg nem szabadíthatták az ő népöket az én kezemből: ekképen az Ezékiás Istene sem szabadíthatja meg az ő népét kezemből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'És kiáltnak nagy felszóval zsidó nyelven Jeruzsálem népe ellen, mely a kerítésen vala, hogy őket megrettentenék és megháborítanák, abban a reményben, hogy így a várost elfoglalhatják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'És úgy szólának a Jeruzsálem Istenéről, mint a föld népeinek istenei felől, melyek emberi kézzel csináltattak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'Akkor Ezékiás király könyörge, és ő vele Ésaiás próféta az Ámós fia e káromlásért, és felkiáltának az égre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'És elbocsátá az Úr az ő angyalát, a ki megöle minden erős vitézt, előljárót és vezért az assiriai király táborában, és nagy szégyennel megtére az ő földébe. Bemenvén pedig az ő istenének házába, ott az ő saját fiai fegyverrel ölék meg őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'Megszabadítá azért az Úr Ezékiást és a Jeruzsálem népét Sénakhéribtől az assiriai királytól, és minden másoktól, és védelmezé őket mindenfelől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'És sokan ajándékokat hoznak vala Jeruzsálembe az Úrnak, Ezékiásnak is a Júda királyának drágaságokat, és ő felmagasztaltatott minden pogányok szemei előtt azután.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'Az időben Ezékiás halálos betegségbe esék; de könyörgött az Úrhoz, a ki szóla hozzá és csudajelt adott néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'De nem cselekedék Ezékiás az ő hozzá való jótétemény szerint, mert magában felfuvalkodék, azért Istennek haragja lőn rajta, Júdán és Jeruzsálemen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Azonban megalázta magát Ezékiás az ő felfuvalkodottságában, Jeruzsálem lakosaival egybe; ezért nem szálla többé reájok az Úrnak haragja Ezékiás életében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'És igen nagy gazdagsága és dicsősége vala Ezékiásnak. És csináltatott magának kincsesházat az ezüst, arany, drágakövek és drága fűszerszámok, paizsok és mindenféle drága szerszámok számára;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'És tárházakat jövedelmének a gabonának, bornak, olajnak számára, és mindenféle barom számára istállókat, a nyájaknak pedig aklokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'Városokat is építe magának, és szerze igen sok juhot és barmot, mert az Isten nagy gazdagságot adott néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'És Ezékiás volt az, a ki betömé a Gihon vizeinek felső forrását, és Dávid városának napnyugat felől való részén vezeté lefelé. És minden dolgában igen szerencsés vala Ezékiás;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'De mivel a Babilóniabeli fejedelmek követeivel megbarátkozék, a kik ő hozzá küldettek, hogy megtudakoznák a csudajelt, mely a földön lőn; elhagyá őt az Isten, hogy megkisértené őt és meglátná, mi volna az ő szívében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'Ezékiásnak pedig többi dolgai és jótéteményei ímé meg vannak írva az Ésaiás prófétának, az Ámós fiának látásában, és a Júda és Izráel királyainak könyvében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'Meghala pedig Ezékiás az ő atyáival, és eltemeték őt a Dávid fiainak sírjaihoz vivő feljárón, és mind az egész Júda és Jeruzsálem nagy tisztességet tettek néki az ő halálának idején. És uralkodék Manasse, az ő fia helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'Tizenkét esztendős vala Manasse, mikor uralkodni kezdett volt, és ötvenöt esztendeig uralkodott Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'És gonoszul cselekedék az Úr szemei előtt a pogányok útálatosságai szerint, a kiket az Úr az Izráel fiai elől kiűzött vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'Mert a magaslatokat ismét megépíté, a melyeket Ezékiás az ő atyja azelőtt elrontott vala, és oltárokat emele Baálnak, Aserákat is plántála, és tisztelé az ég minden seregeit, és szolgála azoknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'Sőt az Úr házában is építe oltárokat, a melyről az Úr azt mondotta volt: Jeruzsálemben lészen az én nevem örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'És építe oltárokat az ég minden seregeinek, az Úr házának mindkét pitvariban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'És fiait átvitte a tűzön a Hinnom fiának völgyében; és az időnek forgására ügyelt, jövendőmondásokat, varázslásokat és szemfényvesztéseket űzött, ördöngösöket és jövendőmondókat szerzett, és sok gonoszságot cselekedett az Úr szemei előtt, hogy őt haragra indítaná.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'A faragott bálványt, a melyet csináltatott vala, az Úr házában állítá fel, a melyről azt mondá az Isten Dávidnak, és az ő fiának, Salamonnak: E házban és Jeruzsálemben, a melyet választottam az Izráel minden nemzetségei közül, helyheztetem az én nevemet mindörökké;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'És nem űzöm ki az Izráelt e földről, melyet adtam volt a ti atyáitoknak; de csak úgy, ha ők is mind megtartándják, a melyeket nékik Mózes által parancsoltam, minden törvényt, rendeléseket és ítéleteket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'De Manasse elcsábítá Júdát és Jeruzsálem lakóit, hogy még gonoszabbul cselekedjenek, mint a pogányok, a kiket az Úr kigyomlált volt az Izráel fiai elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'És noha megszólította az Úr Manassét és az ő népét; de nem figyelmezének reá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'Reájok hozá azért az Úr az Assiriabeli király seregének vezéreit, a kik Manassét megfogták és vasba vervén megkötözék őt két lánczczal, és Babilóniába vivék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'Mikor pedig nagy nyomorúságban volna, fohászkodék az Úrhoz az ő Istenéhez, és teljesen megalázta magát az ő atyáinak Istene előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'És könyörögvén hozzá megkegyelmeze néki, és meghallgatván könyörgését, visszahozá őt Jeruzsálembe, az ő országába. Akkor ismeré meg Manasse, hogy az Úr az igaz Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'Ezek után a Dávid városának külső kőfalát felépíté Gihontól napnyugat felé a völgyben, a halkapu bemeneteléig; Ofelt is körülvéteté magas kerítéssel, és Júdának minden megerősített városaiba seregvezéreket helyeze.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'És eltávolítá az idegen isteneket és a bálványt az Úr házából, és minden oltárt, a melyet az Úr házának hegyén és Jeruzsálemben emeltetett, kihányatá azokat a városon kivül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'És megépíté az Úr oltárát, és áldozék rajta hálaadó és dicsőítő áldozatokkal, és megparancsolá Júdának, hogy szolgáljanak az Úrnak, Izráel Istenének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'Mindazáltal még akkor a nép áldozik vala a magaslatokon; de csak az Úrnak, az ő Istenének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'Manassénak pedig többi dolgai, Istenéhez való könyörgése, a próféták intése, a kik az Úrnak, Izráel Istenének nevében szólának néki, ímé meg vannak írva az Izráel királyainak dolgai között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'Az ő könyörgése pedig, és hogy az Isten mint kegyelmezett volt meg néki, s az ő minden bűne és vétke; és a helyek, a melyeken magaslatokat épített volt, s Aserákat és bálványokat állított fel, minekelőtte megalázta volna magát: ímé meg vannak írva a Hózai beszédei között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'És meghala Manasse az ő atyáival, és eltemeték őt az ő házában; és uralkodék Amon, az ő fia helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'Huszonkét esztendős vala Amon, mikor uralkodni kezdett, és két esztendeig uralkodék Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'És gonoszul cselekedék az Úr szemei előtt, miként az ő atyja Manasse cselekedett volt, mert áldozék Amon mindama bálványoknak, a melyeket az ő atyja Manasse csináltatott, és azoknak szolgál vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'Meg sem alázá magát az Úr előtt, mint az ő atyja Manasse megalázta magát; hanem még sokasítá Amon a bűnt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'Pártot ütének pedig az ő szolgái ő ellene, és őt saját házában megölék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'A föld népe pedig levágá mindazokat, a kik Amon király ellen pártot ütének, és királylyá tevé a föld népe Jósiást az ő fiát helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'Nyolcz esztendős vala Jósiás, mikor uralkodni kezdett volt, és uralkodott harminczegy esztendeig Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'És jó dolgot cselekedék az Úr előtt, és jára az ő atyjának Dávidnak útjain, és nem hajolt el sem jobbra, sem balra;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'Mert az ő királyságának nyolczadik esztendejében, mikor még gyermek volna, kezdé keresni az ő atyjának Dávidnak Istenét; tizenkettedik esztendejében pedig Júdát és Jeruzsálemet kezdé megtisztítani a magaslatoktól, Aseráktól, bálványoktól és öntött képektől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'Leronták ő előtte a Baálok oltárait és az azokon levő szobrokat lehányatá; az Aserákot is a bálványokkal és öntött képekkel egyetembe szétrombolá és apróra töreté, és elhinteté azoknak temetőhelyén, a kik azoknak áldoztak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'A papok csontjait megégeté azoknak oltárain, és megtisztítá Júdát és Jeruzsálemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'Így cselekedék Manassénak, Efraimnak és Simeonnak városaiban is, mind Nafthaliig, azoknak pusztáiban köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'Lehányatá azért az oltárokat; az Aserákat és a bálványokat összetördelé mind porrá, és minden naposzlopot elpusztított Izráel egész földén; azután megtére Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'Királyságának tizennyolczadik esztendejében pedig, minekutána a földet és a házat megtisztítá, elküldé Sáfánt az Asália fiát, és Maaséját a város előljáróját, és Joát a Joákház fiát, az emlékírót, hogy kijavíttatnák az Úrnak, az ő Istenének házát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'És menének Hilkiás főpaphoz, és átadták néki az Isten házába begyült pénzt, a melyet a Léviták, az ajtónállók gyűjtöttek Manassétól, Efraimtól és az egész Izráel maradékaitól, és egész Júdától és Benjámintól, és Jeruzsálem lakóitól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'És adák a munkavezetőknek, a kik felvigyáztak az Úr házában, hogy adják azt a munkásoknak, a kik dolgoztak az Úr házában, hogy kijavítsák és helyreállítsák a házat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'És adának pénzt az ácsoknak és a kőműveseknek, hogy vegyenek faragott köveket, és fákat a kapcsolásokra, és a házak gerendázására, a melyeket elrontottak a Júda királyai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'És az emberek hűségesen végzik vala a munkát; a kikre felügyelének Jáhát és Obádia Léviták, a Mérári fiai közül valók; és Zakariás, Mésullám, a Kéhátiták fiai közül valók, a kik szorgalmazzák vala őket. E Léviták pedig mindnyájan mesterek valának az éneklőszerszámokban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'A teherhordókat pedig (mert voltak felügyelők a munkások felett mindenféle dologban) szorgalmazák a Léviták közül való íródeákok, igazgatók és ajtónállók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'Mikor pedig kihozák azok a pénzt, a mely az Úr házában gyűlt össze: megtalálá Hilkia pap az Úr törvénykönyvét, a melyet Mózes által adott volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'Szóla pedig Hilkia, és monda Sáfánnak, az íródeáknak: A törvénykönyvet megtalálám az Úr házában. És adá Hilkia a könyvet Sáfánnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'És vivé Sáfán a könyvet a királyhoz, és elbeszélé néki a dolgot, mondván: Valamit bíztál a te szolgáidra, abban híven eljárnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'Mert az Úr házában talált pénzt összeszedvén, adák a felügyelőknek és munkásoknak kezébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'Továbbá jelenté Sáfán íródeák a királynak, mondván: Hilkia pap nékem egy könyvet ada; és olvasott abból Sáfán a király előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'Mikor pedig a király hallotta a törvény beszédit, ruháit megszaggatá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'És parancsola a király Hilkia papnak és Ahikámnak a Sáfán fiának, Abdonnak a Mika fiának, és az íródeáknak Sáfánnak, és Asájának a király szolgájának, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, 'Menjetek el, és keressétek meg az Urat én érettem, s az Izráel és Júda maradékaiért, a könyv beszédei felől, a mely megtaláltatott, mert nagy az Úr haragja, a mely mi reánk szállott azért, hogy a mi atyáink nem tartották meg az Úrnak beszédét, hogy mind a szerint cselekedtek volna, a mint e könyvben megíratott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'Elméne azért Hilkia és a király embere Húlda prófétaasszonyhoz, a Sallum feleségéhez, a ki Thókéhát fia vala, a ki Hasrának, a ruhák gondviselőjének fia vala (ő pedig Jeruzsálemben, a második utczában lakik vala) és a szerint szólának néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'Ki monda nékik: Így szól az Úr, Izráel Istene: Mondjátok meg a férfinak, a ki titeket hozzám küldött;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, 'Ezt mondja az Úr: Ímé én veszedelmet hozok e helyre és ennek lakosira, mindazokat az átkokat, a melyek meg vannak írva a könyvben, a melyet felolvastak a Júda királya előtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'Mivel elhagytak engem, és idegen isteneknek tömjéneztek, hogy engem haragra gerjeszszenek az ő kezeiknek minden cselekedetei által. Felgerjedt az én haragom e hely ellen, és el sem oltatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'A Júda királyának pedig, a ki titeket küldött, hogy az Urat megkérdjétek, így szóljatok: Így szól az Úr, Izráel Istene: A mi a beszédeket illeti, a melyeket hallottál:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'Mivel a te szíved meglágyult, és magadat megaláztad az Isten előtt, mikor hallád az ő beszédeit e hely ellen és az ő lakosai ellen; mivel magadat megaláztad előttem, és ruháidat megszaggattad és sírtál előttem: én is meghallgattalak, ezt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, 'Ímé én téged a te atyáid közé takarítlak, és tétetel a te sírodba békességben, és nem látják a te szemeid azt a veszedelmet, a melyet én hozok e helyre és ennek lakóira. És e szerint beszélték el ezt a királynak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'Akkor a király elkülde, és összegyűjteté Júdának és Jeruzsálemnek minden véneit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'És felméne a király az Úr házába, és ő vele Júdának minden férfiai, és Jeruzsálem lakosai, a papok, a Léviták és az egész nép kicsinytől fogva nagyig, és elolvasá fülök hallására a szövetség könyvének minden beszédeit, a melyet találtak vala az Úr házában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'Azután felállván a király az ő helyén, fogadást tőn az Úr előtt, hogy ő az Urat követendi, és hogy parancsolatait, bizonyságtételeit és rendeléseit teljes szívéből és teljes lelkéből megőrzendi, cselekedvén a szövetség beszédeit, a melyek megirattak abban a könyvben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'És felfogadtatá e dolgot mindazokkal, a kik Jeruzsálemből és Benjáminból valók. És Jeruzsálem lakói az Istennek, az ő atyáik Istenének szövetsége szerint cselekedének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'Akkor elpusztított Jósiás minden útálatos bálványt Izráel fiainak egész földjéről, és kényszeríte mindenkit, valaki találtatik vala Izráelben, hogy szolgáljon az Úrnak, az ő Istenöknek; és az ő egész életében nem szakadának el az Úrtól, atyáik Istenétől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'És megtartá Jósiás Jeruzsálemben a húsvétünnepet az Úrnak; és megölék a páskhabárányt az első hónap tizennegyedik napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'És állítá a papokat az őrállásukra, és buzdítá őket az Úr házának szolgálatára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'És monda a Lévitáknak, a kik az egész Izráelt oktatják, és magokat az Úrnak szentelék: Helyheztessétek a szent ládát a házba, a melyet készített volt Salamon a Dávid fia, az Izráel királya; nem kell most vállatokon hordoznotok; hanem szolgáljatok az Úrnak, a ti Istenteknek, és az ő népének az Izráelnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'És készítsétek el magatokat a ti családjaitok és csoportjaitok szerint, a mint Dávid az Izráel királya elrendelte volt, és megírta az ő fia Salamon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'És álljatok a szent helyen, a nép közül való testvéreitek családjainak csoportjai és a Léviták családjának egy-egy csoportja szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'Azután öljétek meg a páskhabárányt, és szenteljétek meg magatokat, és készítsétek el azt a ti atyátokfiainak, hogy az Úrnak Mózes által tett beszéde szerint cselekedjetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'És ada Jósiás a nép fiai számára juhokat, bárányokat és gödölyéket, mindezeket a húsvéti áldozatokra; mindenkinek, valaki ott találtatik vala, szám szerint harminczezeret, és háromezer tulkot; ezek mind a királyéból valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'Az ő fejedelmei is szabad akaratjokból a községnek, a papoknak és a Lévitáknak adakozának; Hilkia, Zakariás és Jéhiel, az Isten házának fejedelmei, adának a papoknak a húsvét áldozatira kétezerhatszáz juhot és háromszáz tulkot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'Konánia pedig és Semája és Nétanéel az ő atyjafiai, Hasábia, Jéhiel és Józabád, a Léviták fejedelmei, adának a Lévitáknak a húsvét áldozatira ötezer juhot és ötszáz tulkot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'Készen levén a szolgálat, a papok helyeikre állának, a Léviták is csapatjaik szerint, a mint a király parancsolta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'Megölék azért a páskhabárányt, és a papok hintik vala kezökből a vért, a Léviták pedig a bárányok bőrét húzzák le.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'És külön választák az egészen égőáldozatra valókat, hogy adnák azokat a nép közül való családok csoportjainak, hogy áldoznának az Úrnak, a mint a Mózes könyvében megiratott; azonképen a tulkokból is elválaszták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'És megsüték a páskhabárányt szokás szerint a tűznél; a megszenteltetett állatokat pedig megfőzék fazekakban, vasfazekakban és üstökben: és nagy hamarsággal adák az egész községnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'Ezek után magoknak és a papoknak is elkészíték a páskhabárányt, mert a papok, az Áron fiai az égőáldozatoknak és a kövérségeknek megáldozásával el valának foglalva késő éjszakáig, azért a Léviták készíték el mind magoknak, mind a papoknak, az Áron fiainak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'Az éneklők is, az Asáf fiai, szolgálatukban valának, Dávidnak, Asáfnak, Hémánnak és Jédutunnak, a király prófétájának parancsolatja szerint; az ajtónállók is mindnyájan az ajtóknál valának; nem távozhatának szolgálatukból, hanem az ő atyjokfiai, a Léviták készíték vala el nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'És elkészüle az Úrnak minden szolgálata azon a napon, hogy megtartanák a páskhát, egészen égőáldozatokkal áldozván az Úr oltárán, a Jósiás király parancsolatja szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'Megtartották tehát az Izráel fiai, a kik jelen lehetének, a páskhát abban az időben, és a kovász nélkül való kenyerek ünnepét hét napon át.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'Ehez hasonló páskhát nem tartottak Izráelben a Sámuel próféta idejétől fogva; Izráel királyai közül is senki sem tartott olyan páskhát, a milyet Jósiás tartott és a papok, a Léviták, egész Júda, és a kik Izráelből jelen voltak, és Jeruzsálem lakosai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'Jósiás királyságának tizennyolczadik évében tartatott ez a páskha.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'Mindezek után, hogy az Isten házát Jósiás helyreállítá, feljöve Nékó, Égyiptom királya, hogy az Eufrátes mellett való Kárkemis városát elfoglalná; és Jósiás ellene ment.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'És noha követeket külde ő hozzá Nékó, ezt mondván: Mi közöm te hozzád nékem, Júda királya? Mert én most nem ellened megyek, hanem az én országom ellensége ellen, és Isten parancsolta, hogy siessek; ne tusakodjál az Isten ellen, a ki én velem van, hogy el ne veszessen téged;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'Mindazáltal Jósiás nem tére ki ő előle, hanem, hogy megütköznék vele, öltözetit megváltoztatá, és nem hallgatott Nékó beszédeire, a melyek az Isten szájából származtak vala. Elméne azért, hogy megütközzék vele Megiddó mezején.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'Akkor a kézívesek nyilakat lövének Jósiás királyra, és monda a király az ő szolgáinak: Vigyetek ki engem innét; mert nagyon megsebesültem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'Levévén azért őt az ő szolgái a szekérből, másik szekerére helyezék, és vivék Jeruzsálembe: És meghala, és eltemetteték az ő atyáinak sírjába; s egész Júda és Jeruzsálem siránkozék Jósiás felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'Jerémiás is siratá Jósiást, és siralmas énekekkel siratják vala őt az éneklő férfiak és asszonyok mindnyájan mind e mai napig, a melyek szokásossá lettek Izráelben, s ímé azok meg vannak írva a Jerémiás siralmaiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'Jósiásnak pedig többi dolgai, és a szerint való jó tettei, a mint az Úrnak törvényében meg van írva;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'És az ő első és utolsó dolgai, ímé meg vannak írva az Izráel és Júda királyainak könyvében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'És előhozá a föld népe Joákházt a Jósiás fiát, és királylyá tette őt atyja helyett Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'Huszonhárom esztendős vala Joákház, mikor uralkodni kezde, és három hónapig uralkodék Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'És letevé őt Égyiptom királya Jeruzsálemben, és a földre adót vetett, száz talentom ezüstöt és egy talentom aranyat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'És Égyiptom királya Eliákimot, az ő testvérét tette királylyá Júda és Jeruzsálem felett, megváltoztatván nevét Joákimra; Joákházt pedig az ő testvérét fogá és elvivé Nékó Égyiptomba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'Huszonöt esztendős vala Joákim, mikor uralkodni kezdett, és tizenegy esztendeig uralkodék Jeruzsálemben; de gonoszul cselekedék az Úr előtt, az ő Istene előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'És feljöve ellene Nabukodonozor a babilóniai király, és kettős békót vete lábaira, hogy Babilóniába vinné őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'Az Úr házában való edények egy részét is elvivé Nabukodonozor Babilóniába, és helyezteté azokat az ő templomába, Babilóniában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'Joákimnak pedig többi dolgai és az ő útálatosságai, a melyeket cselekedett, s a melyek találtattak ő benne, ímé meg vannak írva az Izráel és Júda királyainak könyvében; és uralkodék helyette Joákin, az ő fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'Nyolcz esztendős korában kezdett uralkodni Joákin, és három hónapig és tíz napig uralkodék Jeruzsálemben; de ő is gonoszul cselekedék az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'Az esztendő fordultával pedig elkülde Nabukodonozor király, és elviteté őt Babilóniába, az Úr házának drága edényeivel együtt, és királylyá tevé az ő testvérét Sédékiást Júda és Jeruzsálem felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'Huszonegy esztendős korában kezdett uralkodni Sédékiás, és uralkodék tizenegy esztendeig Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'És gonoszul cselekedék az Úr előtt, az ő Istene előtt, és nem alázta meg magát Jeremiás próféta előtt, a ki az Úr képében szól vala néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'Sőt még Nabukodonozor király ellen is pártot ütött, a ki őt az Isten nevére megesküdtette vala, s makacscsá és önfejűvé lett, a helyett, hogy megtért volna az Úrhoz, Izráel Istenéhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'Sőt még a papok fejedelmei és a nép is, mindnyájan szaporították a bűnt a pogányok minden undokságai szerint, és megfertőztették az Úr házát, a melyet megszentelt vala Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'És az Úr, az ő atyáiknak Istene elküldé hozzájok követeit jó idején, mert kedvez vala az ő népének és az ő lakhelyének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'De ők az Isten követeit kigúnyolták, az ő beszédeit megvetették, és prófétáival gúnyt űztek; míglen az Úrnak haragja felgerjede az ő népe ellen, s többé nem vala segítség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'És reájok hozá a Káldeusok királyát, a ki fegyverrel ölé meg ifjaikat az ő szent hajlékukban, s nem kedveze sem az ifjaknak és szűzeknek, sem a vén és elaggott embereknek, mindnyájokat kezébe adá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'És az Isten házának mindenféle edényeit, nagyokat, kicsinyeket, és az Úr házának kincseit, s a királynak és az ő vezéreinek kincseit, mindezeket Babilóniába viteté.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'Az Isten házát meggyújták, Jeruzsálem kőfalait lerontották, palotáit mind elégeték tűzzel, és minden drágaságait elpusztították.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'És a kik a fegyver elől megmenekültek, azokat elhurczolta Babilóniába, és néki és fiainak szolgáivá lettek mindaddig, míg a persiai birodalom fel nem támadott;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'Hogy beteljesedjék az Úrnak Jeremiás szája által mondott beszéde, míg lerójja a föld az ő szombatjait, mert az elpusztulás egész ideje alatt nyugovék, hogy betelnének a hetven esztendők.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'És Czírus persa király első esztendejében, hogy beteljesednék az Úrnak Jeremiás szája által mondott beszéde, az Úr felindítá Czírus persa király lelkét, és ő kihirdetteté az ő egész birodalmában, élőszóval és írásban is, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, 'Így szól Czírus, a persa király: Az Úr, a mennynek Istene e föld minden országait nékem adta, és Ő parancsolta meg nékem, hogy építsek néki házat Jeruzsálemben, a mely Júdában van; valaki azért ti köztetek az ő népe közül való, legyen vele az Úr, az ő Istene, és menjen fel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'Czírus persa király első esztendejében, hogy beteljesednék az Úrnak Jeremiás szája által mondott beszéde, felindítá az Úr Czírus persa király lelkét, és ő kihirdetteté az ő egész birodalmában, élőszóval és írásban is, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, 'Így szól Czírus, a persa király: Az Úr, a mennynek Istene e föld minden országait nékem adta, és Ő parancsolta meg nékem, hogy építsek néki házat Jeruzsálemben, mely Júdában van;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'Valaki azért ti köztetek az ő népe közül való, legyen vele az ő Istene, és menjen fel Jeruzsálembe, mely Júdában van, és építse az Úrnak, Izráel Istenének házát, ő az Isten, ki Jeruzsálemben lakozik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'És mindenkit, a ki még megmaradt, minden helyről, a hol lakik, segítsék azon helynek férfiai ezüsttel, aranynyal, jószággal és barommal, azzal együtt, a mit önkénytesen adnak az Isten házának, mely Jeruzsálemben van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'Fölkelének azért Júda és Benjámin családfői és a papok és a Léviták, és mindnyájan, a kiknek felindítá az Isten lelköket, hogy felmenjenek az Úr házának építésére, mely Jeruzsálemben van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'És minden körültök lakók segíték őket ezüst edényekkel, aranynyal, jószággal, barommal, drágaságokkal, mindazon kivül, a mit önkénytesen adának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'Czírus király pedig előhozatá az Úr házának edényeit, melyeket Nabukodonozor hozatott vala el Jeruzsálemből, s az ő isteneinek házába helyezett vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'Előhozatá ezeket Czírus, a persák királya, Mithredáthes kincstartó kezeihez, a ki is átszámolá azokat Sesbassárnak, Júda fejedelmének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'És számok ez vala: harmincz arany medencze, ezer ezüst medencze, huszonkilencz kés,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, 'Harmincz arany pohár, négyszáztíz másrendbeli ezüst pohár, és ezer más edény.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'Minden arany és ezüst edényeknek száma ötezernégyszáz. Mindezt magával vivé Sesbassár, mikor a foglyok kijövének Babilóniából Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'Ezek pedig a tartománynak fiai, kik feljöttek vala a rabság foglyai közül, a kiket Nabukodonozor, Babilónia királya, fogva vitetett Babilóniába, s most visszajövének Jeruzsálembe és Júdába, kiki az ő városába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, 'Kik jövének Zorobábellel, Jésuával, Nehémiással, Serájával, Rélájával, Mordokhaival, Bilsánnal, Miszpárral, Bigvaival, Rehummal, Baanával. Izráel népe férfiainak száma ez:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'Paros fiai kétezerszázhetvenkettő;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'Sefátja fiai háromszázhetvenkettő;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'Árah fiai hétszázhetvenöt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'Pahath-Moáb fiai, Jésua és Joáb fiaitól, kétezernyolczszáztizenkettő;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'Élám fiai ezerkétszázötvennégy;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'Zattu fiai kilenczszáznegyvenöt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'Zakkai fiai hétszázhatvan;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'Báni fiai hatszáznegyvenkettő;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'Bébai fiai hatszázhuszonhárom;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'Azgád fiai ezerkétszázhuszonkettő;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'Adónikám fiai hatszázhatvanhat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'Bigvai fiai kétezerötvenhat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'Ádin fiai négyszázötvennégy;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'Áter fiai, Ezékiástól, kilenczvennyolcz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'Bésai fiai háromszázhuszonhárom;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'Jórá fiai száztizenkettő;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'Hásum fiai kétszázhuszonhárom;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'Gibbár fiai kilenczvenöt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'Bethlehem fiai százhuszonhárom;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'Netófah férfiai ötvenhat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'Anathóth férfiai százhuszonnyolcz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'Azmáveth fiai negyvenkettő;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'Kirjáth-Árim, Kefira és Beéróth fiai hétszáznegyvenhárom;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'Ráma és Géba fiai hatszázhuszonegy;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'Mikmás férfiai százhuszonkettő;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'Béthel és Ái férfiai kétszázhuszonhárom;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'Nebó fiai ötvenkettő;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'Magbis fiai százötvenhat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, 'A másik Élám fiai ezerkétszázötvennégy;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, 'Hárim fiai háromszázhúsz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, 'Lód, Hádid és Ónó fiai hétszázhuszonöt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, 'Jérikó fiai háromszáznegyvenöt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, 'Szenáa fiai háromezerhatszázharmincz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, 'A papok: Jedája fiai, Jésua családjából, kilenczszázhetvenhárom;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, 'Immér fiai ezerötvenkettő;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, 'Pashur fiai ezerkétszáznegyvenhét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, 'Hárim fiai ezertizenhét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, 'A Léviták: Jésuának és Kadmiélnek fiai, Hodávia fiaitól, hetvennégy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, 'Az énekesek: Asáf fiai százhuszonnyolcz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, 'A kapunállók fiai: Sallum fiai, Ater fiai, Talmón fiai, Akkub fiai, Hatita fiai, Sóbai fiai, összesen százharminczkilencz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, 'A Léviták szolgái: Siha fiai, Hasufa fiai, Tabbaóth fiai;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, 'Kérósz fiai, Sziaha fiai, Pádón fiai,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, 'Lebána fiai, Hagába fiai, Akkub fiai,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, 'Hágáb fiai, Salmai fiai, Hanán fiai,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, 'Giddél fiai, Gahar fiai, Reája fiai,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, 'Resin fiai, Nekóda fiai, Gazzám fiai,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, 'Uzza fiai, Pászéah fiai, Bészai fiai,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, 'Aszna fiai, Meunim fiai, Nefiszim fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, 'Bakbuk fiai, Hakufa fiai, Harhur fiai,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, 'Basluth fiai, Mehida fiai, Harsa fiai,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, 'Barkósz fiai, Sziszera fiai, Temah fiai,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, 'Nesiah fiai, Hatifa fiai;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, 'Salamon szolgáinak fiai: Szótai fiai, Haszszófereth fiai, Peruda fiai,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, 'Jaalá fiai, Darkón fiai, Giddél fiai,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, 'Sefátia fiai, Hattil fiai, Pókhereth-Hássebaim fiai, Ámi fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, 'Összesen a Léviták szolgái és a Salamon szolgáinak fiai háromszázkilenczvenkettő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, 'És ezek, a kik feljövének Tél-Melahból, Tél-Harsából, Kerub-Addán-Immérből, de nem mondhatták meg családjukat és eredetüket, hogy Izráel közül valók-é:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, 'Delája fiai, Tóbiás fiai, Nekóda fiai hatszázötvenkettő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, 'És a papok fiai közül: Habája fiai, Hakkós fiai, Barzillai fiai, ki a Gileádbeli Barzillai leányai közül vett magának feleséget, és ezek nevéről nevezteték;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, 'Ezek keresték írásukat, tudniillik a nemzetségök könyvét, de nem találák, miért is kirekesztetének a papságból;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, 'És megmondá nékik a király helytartója, hogy ne egyenek a szentséges áldozatból, mígnem pap ítél az Urimmal és Tummimmal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, 'Mind az egész gyülekezet együtt negyvenkétezerháromszázhatvan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, 'Szolgáikon és szolgálóikon kivül – ezek száma hétezerháromszázharminczhét – valának nékik énekes férfiaik és asszonyaik kétszázan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, 'Lovaik hétszázharminczhat, öszvéreik kétszáznegyvenöt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, 'Tevéik négyszázharminczöt, hatezerhétszázhúsz szamárral.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, 'A családfők közül pedig, mikor megérkezének az Úr házához, mely Jeruzsálemben van, némelyek önkénytesen adakozának az Isten házára, hogy fölépítenék azt az ő helyén;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, 'Tehetségök szerint adának az építés költségére aranyban hatvanegyezer dárikot, s ezüstben ötezer mánét, és száz papi ruhát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, 'És lakozának mind a papok, mind a Léviták, mind a nép fiai, mind az énekesek, mind a kapunállók, mind a Léviták szolgái városaikban, s így az egész Izráel a maga városaiban vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'Mikor pedig eljöve a hetedik hónap, és Izráel fiai az ő városaikban lakozának, felgyűle a nép egyenlőképen Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'És fölkele Jésua, Jósádák fia, s az ő atyjafiai, a papok, és Zorobábel, Sealtiél fia s az ő atyjafiai, és megépíték Izráel Istenének oltárát, hogy áldozzanak rajta égőáldozatokat, a mint írva van Mózesnek, az Isten emberének törvényében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'És erős fundamentomra állíták fel az oltárt, mert félnek vala a földnek népétől, és áldozának rajta égőáldozatokat az Úrnak, reggeli és estveli égőáldozatokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'És megülék a sátoros ünnepet, a mint írva van, s áldozának égőáldozatot napról-napra szám és szokás szerint minden napit az ő napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, 'És azután áldozák az állandó napi, továbbá a hónapok első napjain s az Úr minden szent ünnep napjain viendő égőáldozatot, és mindazokért valót, a kik önkénytesen ajándékozának az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'Tehát a hetedik hónap első napjától fogva kezdének égőáldozatot áldozni az Úrnak, a mikor az Úr templomának alapköve még nem tétetett le.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'És adának pénzt a kő- és favágóknak s a mesterembereknek, és ételt és italt és olajat a Sidonbelieknek és Tírusbelieknek, hogy hozzanak czédrusfákat a Libánonról a joppéi tenger felé, Czírus, persa király nékik adott engedelme szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'Második esztendőben azután, hogy fölmenének az Isten házához Jeruzsálembe, a második hónapban megkezdték az építést Zorobábel, a Sealtiél fia és Jésua, a Jósádák fia és a többi atyjafiaik, a papok és Léviták és mindnyájan, a kik a fogságból visszajöttek vala Jeruzsálembe, és rendelék a Lévitákat, a kik húsz esztendősök vagy azon felül valának, az Úr háza építésének vezetésére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, 'És előlálla Jésua, az ő fiai és atyjafiai, Kadmiél és fiai, a Júda fiai, egyenlőképen, hogy vezérei legyenek az Isten házát építő munkásoknak, továbbá Hénádád fiai, fiaik és testvéreik, – mind Léviták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'S midőn az építők letették az Úr templomának alapkövét, Jésua és Zorobábel oda állaták a papokat öltözetükben kürtökkel, s a Lévitákat, Ásáf fiait czimbalmokkal, hogy dícsérjék az Urat, Izráel királyának, Dávidnak rendelete szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'És énekelének, dícsérvén az Urat és hálát adván néki, mert jó, mert mindörökké van az ő irgalmassága Izráelen! És mind az egész nép nagy felszóval kiált vala, dícsérvén az Urat, hogy az Úr házának alapköve immáron letétetett!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'Nagy sokan pedig a papok és a Léviták és a családfők közül, a vének, a kik látták vala az első házat, mikor alapot vetnek vala most e háznak az ő szemök előtt, nagy felszóval sírnak vala, sokan pedig örömükben nagy felszóval kiáltanak vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'Úgy hogy a nép nem tudja vala megkülönböztetni az örömben való kiáltást a nép siralmának szavától, mert a nép kiált vala nagy felszóval, és ez a szó messze földre meghallatott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, 'Mikor pedig meghallák Júda és Benjámin ellenségei, hogy a kik a fogságból visszatértek, templomot építenek az Úrnak, Izráel Istenének:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, 'Menének Zorobábelhez és a családfőkhöz, s mondának nékik: Hadd építsünk együtt veletek, mert miképen ti, úgy mi is a ti Isteneteket keressük s néki áldozunk Esárhaddon, Assiria királyának idejétől fogva, a ki ide hozott fel minket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'És monda nékik Zorobábel és Jésua és Izráel családainak többi fői: Nem veletek együtt kell nékünk házat építeni a mi Istenünknek, hanem mi magunk fogunk építeni az Úrnak, Izráel Istenének, a miképen megparancsolta nékünk a király, Czírus, Persia királya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'És igyekezék e tartomány népe megkötni Júda népének kezeit és elrémíteni azt az építéstől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'És felbérelni ellene tanácsosokat, hogy semmivé tegyék szándékát Czírusnak, Persia királyának egész idejében, Dárius persa király uralkodásáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'És Ahasvérus uralkodásakor, uralkodásának kezdetén, vádolást írának Júda és Jeruzsálem lakói ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'Artaxerxes napjaiban pedig Bislám, Mithredathes és Tábeél s ennek többi társai írtak vala Artaxerxeshez a persiai királyhoz, s e levelet arám betűkkel írták, mely azután arám nyelvre fordíttatott át.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'Rehum, a helytartó és Simsai, a kanczellár, írának egy levelet Jeruzsálem ellen Artaxerxes királyhoz ekképen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, 'Írának pedig ekkor Rehum, a helytartó és Simsai, a kanczellár és ezeknek többi társaik: a Dineusok, Afársatakeusok, Tarpeleusok, Afárseusok, Arkeveusok, Babilóniabeliek, Susánkeusok, Dehaveusok és a Hélameusok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'És a többi népek, a kiket a nagy és dicsőséges Asznapár vitt el és tett lakosokká Samária városában és a többi városokban, melyek a folyóvizen túl vannak és a többi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, 'Ez mássa a levélnek, melyet hozzá, Artaxerxes királyhoz küldének: „A te szolgáid, a folyóvizen túl lévő férfiak, és a többi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, 'Tudtára légyen a királynak, hogy a zsidók, a kik feljöttek tőled, megérkezének hozzánk Jeruzsálembe; a visszavonó és gonosz várost építik, a kőfalakat készítik s a fundamentomokat javítgatják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'Mostan tudtára légyen a királynak, hogy ha ez a város megépíttetik s a kőfalak elkészülnek, adót, rovást és úti vámot nem fognak fizetni, s a királyok jövedelmét megkárosítják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'Mostan, mivel a palota savával sózunk s épen ezért a király kárát nem illik elnéznünk, ez okért küldjük e levelet és tudatjuk a királylyal,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'Hogy nézzen utána valaki atyáid történeteinek könyvében, és meg fogod találni a történetek könyvében, és megtudod, hogy e város visszavonó és királyokat és tartományokat megkárosító város volt, s hogy eleitől fogva lázadások történtek abban, ezért pusztíttatott is el e város.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'Tudatjuk mi a királylyal, hogy ha ez a város megépülend és a kőfalak elkészülnek: ennek miatta birtokod a folyóvizen túl nem lészen.”');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'A király választ küldött Rehumnak, a helytartónak és Simsainak, a kanczellárnak és többi társaiknak, a kik Samariában laknak vala, és minden folyóvizen túl lakozóknak: „Békesség és a többi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, 'A levél, melyet hozzánk küldtetek, világosan felolvastatott előttem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'És megparancsolám, hogy nézzenek utána, és úgy találák, hogy ez a város eleitől fogva királyok ellen támadó volt, és hogy pártütés és lázadás történt vala benne;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'És hogy hatalmas királyok voltak Jeruzsálemben és uralkodtak minden a folyóvizen túl lakókon, és adó, rovás és úti vám fizettetett nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'Mostan azért parancsoljátok meg, hogy akadályozzák meg a férfiakat, s e város ne építtessék addig, míg tőlem parancsolat nem jövend;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'És meglássátok, hogy ebben valami mulasztást el ne kövessetek, hogy ne nevekedjék a veszedelem a királyok megkárosítására!”');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'Mihelyt Artaxerxes király levelének mássa felolvastaték Rehum és Simsai, a kanczellár és társaik előtt, menének nagy hamarsággal Jeruzsálembe a zsidókhoz, és megakadályozák őket erővel és hatalommal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'Akkor megszünék az Úr házának építése, mely Jeruzsálemben van, és szünetelt Dárius, Persia királya uralkodásának második esztendejéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, 'És prófétálának a próféták, Aggeus, a próféta és Zakariás az Iddó fia a zsidóknak, a kik valának Júdában és Jeruzsálemben, szólván nékik az Izráel Istenének nevében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'Akkor fölkelének Zorobábel, Sealtiél fia és Jésua, a Jósádák fia, és hozzá kezdének Isten háza építéséhez, mely Jeruzsálemben van, s velök valának Isten prófétái, támogatván őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'Abban az időben jöve hozzájok Tattenai folyóvizen túli helytartó, és Sethar-bóznai és társaik, és így szólának nékik: Ki adott néktek szabadságot, hogy e házat építsétek s e kőfalat készítsétek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'Ekkor megmondánk nékik ily módon, hogy kik ama férfiak névszerint, kik ez épületet építik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'És az ő Istenök szeme vala a zsidók vénein, hogy nem akadályozzák meg őket az építésben, míg az ügy Dárius elébe jutand, a mikor is levélben fognak felelni e dologra nézve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, 'Mássa a levélnek, melyet küldött Tattenai folyóvizen túli helytartó, és Sethar-bóznai és az ő társai, az Afarsakeusok, a kik a folyóvizen túl lakának, Dárius királyhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'Tudósítást küldének ugyanis hozzá, ekként levén az írva: „Dárius királynak minden békesség!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, 'Tudtára legyen a királynak, hogy elmentünk Júda tartományába, a nagy Istennek házához, és az építtetik nagy kövekből, és fa rakatik a falakra, és e munka szorgalmatosan folyik, és jó szerencsés lészen az ő kezök által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'Ekkor megkérdénk azokat a véneket, ily módon szólván hozzájok: Ki adott néktek szabadságot, hogy e házat építsétek, s hogy e kőfalat készítsétek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'Sőt még neveiket is megkérdeztük tőlük, hogy tudassuk veled, hogy megírhassuk azon férfiak nevét, kik fejeik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'És ekképen felelének nékünk, mondván: Mi az Ő, a menny és föld Istenének szolgái vagyunk, és építjük e házat, mely ennekelőtte sok esztendőkön át meg vala építve, és Izráelnek egy nagy királya építé és végezé be azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'De minekutána haragra ingerelték volt atyáink a mennynek Istenét, adá őket a Babilóniabeli Káldeus királynak, Nabukodonozornak kezébe, a ki e házat lerontotta, és a népet Babilóniába rabságra vitte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'Azonban Czírusnak, Babilónia királyának első esztendejében Czírus király szabadságot adott, hogy Istennek ezt a házát megépítenék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'Sőt az Isten házához való arany és ezüst edényeket is, a melyeket Nabukodonozor hozott vala el a jeruzsálemi templomból s bevitte volt azokat a babilóniai templomba, kihozatá Czírus király a babilóniai templomból s adatá azokat annak a Sesbassár nevűnek, a kit helytartóul rendelt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'És monda néki: Vedd ez edényeket, menj és helyezd el azokat a jeruzsálemi templomba, és az Isten háza építtessék meg előbbi helyén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'Ekkor ez a Sesbassár eljött, letevé az Isten házának alapkövét, mely Jeruzsálemben van, és attól fogva mindeddig építtetik, és még sem végződött be.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'Mostan azért, ha tetszik a királynak, nézzen utána valaki a király kincstartó házában, ott Babilóniában, ha úgy van-é, hogy Czírus király szabadságot adott az Isten házának megépítésére, mely Jeruzsálemben van, s a király akaratját erre nézve küldje hozzánk.”');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'Ekkor Dárius király megparancsolá, hogy nézzenek utána a könyvek tárházában, hol a kincseket tartják vala Babiloniában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'És találtaték Akhméta várában, a mely Média tartományában van, egy tekercs, melyre emlékezetül ez vala írva:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, '„Czírus király első esztendejében, Czírus király parancsolatot adott Isten házára nézve, mely Jeruzsálemben van, hogy e ház építtessék meg, oly helyül, hol áldozatokat áldoznak; s alapzati felemeltetvén, magassága hatvan sing, szélessége is hatvan sing legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, 'A nagy kövek rétege három s a fa rétege legyen egy, a költség pedig a király házából adassék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'Sőt az Isten házának arany és ezüst edényeit is, a melyeket Nabukodonozor hozott vala el a jeruzsálemi templomból s vitt vala Babilóniába, adják vissza, hogy jussanak el azok a jeruzsálemi templomba, helyökre, s te helyezd el azokat az Isten házába.”');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, 'Mostan azért Tattenai folyóvizen túli helytartó, Sethar-bóznai és társaik, és az Afarsakeusok, a kik a folyóvizen túl laknak, távol legyetek onnan!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'Hagyjátok, hadd épüljön meg Istennek ama háza! A zsidók helytartója és a zsidók vénei építsék meg Isten ama templomát a maga helyén!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, 'És megparancsolom azt is, hogy mit cselekedjetek a zsidók ama véneivel, hogy megépítsék Isten ama házát; tudniillik a király folyóvizen túl való adójának kincseiből pontosan költség adassék ama férfiaknak, és pedig félbeszakítás nélkül,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'És a mik szükségesek, tulkok, kosok, bárányok, égőáldozatra a menny Istenének, búza, só, bor, és olaj, a jeruzsálemi papok szava szerint adassanak nékik naponként és pedig mulasztás nélkül,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'Hogy vihessenek jó illatú áldozatot a menny Istenének, és könyörögjenek a királynak és fiainak életéért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'És megparancsolom azt is, hogy valaki e rendelést megszegi, annak házából szakíttassék ki egy gerenda s felállíttatván szegeztessék reá, háza pedig szemétdombbá tétessék e miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'Az Isten pedig, a ki nevének ott szerze lakást, megrontson minden királyt és népet, a ki felemelendi kezét, hogy megszegje e rendelést, hogy elpusztítsa Istennek ama házát, mely Jeruzsálemben van. Én, Dárius parancsoltam, pontosan megtörténjék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'Akkor Tattenai folyóvizen túli helytartó, Sethar-bóznai és társaik, miután Dárius ily rendelést küldött, ahhoz képest cselekedének pontosan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'És a zsidók vénei építének és jó szerencsések valának Aggeus próféta és Zakariás, Iddó fia prófétálása folytán, és megépítették és elvégezték Izráel Istenének akaratjából, és Czírus, Dárius és Artaxerxes, persiai királyok parancsolatjából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'Bevégezteték pedig e ház az Adár hó harmadik napjáig, mely Dárius király országlásának hatodik esztendejében vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'És megtarták Izráel fiai, a papok, a Léviták és a fogságból visszajött többiek Isten házának felszentelését örömmel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'Vivének pedig Isten házának felszentelésénél áldozatul száz bikát, kétszáz kost, négyszáz bárányt és tizenkét kecskebakot bűnért való áldozatra egész Izráelért, Izráel nemzetségeinek száma szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'És rendelék a papokat az ő osztályaik és a Lévitákat az ő rendjeik szerint Istennek szolgálatára Jeruzsálemben, Mózes könyvének rendelése szerint,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'És megtarták a rabságból visszajöttek a páskhát az első hó tizennegyedik napján;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, 'Mert megtisztultak vala a papok és Léviták: egyetemben mindnyájan tiszták valának, és megölék a húsvéti bárányt mindazokért, a kik a rabságból megjöttek, és atyjokfiaiért a papokért és önmagokért;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'És megevék azt Izráel fiai, a kik a rabságból visszajöttek vala, és mindazok, a kik elkülönítették vala magokat a föld népeinek tisztátalanságától s hozzájok állottak vala, hogy keressék az Urat, Izráel Istenét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'És azután megtarták a kovásztalan kenyerek ünnepét hét napon örömmel, mert megvidámította vala őket az Úr, hozzájok hajtván az Assiriabeli király szívét, hogy erősítse kezöket az Istennek, Izráel Istenének háza építésében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, 'És ezek után Artaxerxes persa király uralkodásakor Ezsdrás, a Serája fia, ki Azariás fia, ki Hilkiás fia,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'Ki Sallum fia, ki Sádók fia, ki Ahitub fia,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'Ki Amária fia, ki Azariás fia, ki Mérájóth fia,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'Ki Zerahja fia, ki Uzzi fia, ki Bukki fia,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'Ki Abisua fia, ki Fineás fia, ki Eleázár fia, ki pedig Áronnak, a főpapnak fia volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, 'Ez az Ezsdrás feljöve Babilóniából, (ő, a ki bölcs írástudó vala a Mózes törvényében, melyet az Úr, Izráel Istene adott vala) és megadá néki a király az Úrnak, az ő Istenének rajta nyugovó kegyelme szerint minden kérését.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, 'Feljövének pedig az Izráel fiai, a papok, a Léviták, az énekesek, a kapunállók és a Léviták szolgái közül többen Jeruzsálembe Artaxerxes király hetedik esztendejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'És Ezsdrás megérkezék velök Jeruzsálembe az ötödik hónapban, a király hetedik esztendejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'Ugyanis az első hónak első napján határozá el a Babilóniából való feljövetelt, és az ötödik hó első napján érkezett Jeruzsálembe, az ő Istenének rajta nyugvó jó kegyelme szerint;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'Mert Ezsdrás erős szívvel törekedett keresni és cselekedni az Úr törvényét, és tanítani Izráelben a rendeléseket és ítéleteket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'És ez mássa a levélnek, melyet adott vala Artaxerxes király Ezsdrásnak, az írástudó papnak, a ki írástudó vala az Úr parancsolatainak beszédiben, Izráelnek adott rendeléseiben:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, '„Artaxerxes, a királyok királya Ezsdrás papnak, ki a menny Istenének törvényében bölcs írástudó és a többi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, 'Szabadságot adok, hogy valaki országomban Izráel népe, papjai és a Léviták közül Jeruzsálembe akar menni, veled elmehet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'Minthogy te elbocsáttatol a királytól és hét tanácsosától, hogy utána nézz Júdának és Jeruzsálemnek, a te Istened törvénye szerint, mely kezedben van,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'És hogy elvigyed az ezüstöt és aranyat, melyet a király és tanácsosai önkénytesen ajándékoznak Izráel Istenének, kinek hajléka Jeruzsálemben van,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, 'És mindazt az ezüstöt és aranyat, melyet kapni fogsz Babilónia egész tartományában, együtt a nép és a papok önkénytes ajándékával, mit ezek önkénytesen ajándékoznak az ő Istenök házának, mely Jeruzsálemben van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, 'Annálfogva gondosan végy e pénzen bikákat, kosokat és bárányokat s hozzájok való étel- és italáldozatokat, s áldozd meg azokat Istenetek házának oltárán, mely Jeruzsálemben van:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, 'A megmaradott ezüsttel és arannyal pedig, a mit jónak láttok cselekedni te és atyádfiai, Istenetek akaratja szerint, azt cselekedjétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, 'És az edényekkel, melyek néked adattak át a te Istened házának szolgálatára, számolj be Isten előtt Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, 'Egyéb szükségét pedig Istened házának, mit csak teljesítened kell, teljesítsd a király kincstartó házából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, 'És én, Artaxerxes, a király, parancsolom minden a folyóvizen túl lakó kincstartóimnak, hogy minden, a mit csak kérend tőletek Ezsdrás pap, ki a menny Istenének törvényében írástudó, pontosan teljesíttessék,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, 'És pedig száz tálentom ezüstig, száz kór búzáig, száz báth borig, száz báth olajig és sóban, a mennyi elég.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, 'Minden, mi a menny Istenének akaratja szerint való, pontosan teljesíttessék a menny Istenének házáért, hogy meg ne haragudjék a királynak és fiainak országára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, 'Veletek pedig tudatjuk, hogy sem a papokra, sem a Lévitákra, sem az énekesekre, sem a kapunállókra, sem a Léviták szolgáira, sem Isten e háza szolgáira, adót, rovást és úti vámot senkinek vetni nem szabad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, 'És te Ezsdrás, a te Istened bölcs törvénye szerint, a mely kezedben van, rendelj ítélőket és birákat, a kik törvényt tegyenek minden a folyóvizen túl lakó nép között, mindazok között, a kik tudják Istenednek törvényeit, és a kik nem tudják, azokat tanítsátok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, 'Valaki pedig nem fogja cselekedni a te Istenednek törvényét és a király törvényét, ítélet hozassék felette pontosan, vagy halálra, vagy számkivetésre, vagy jószágvesztésre, vagy fogságra.”');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, 'Áldott az Úr, atyáink Istene, a ki erre indítá a király szívét, hogy megékesítse az Úr házát, mely Jeruzsálemben van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, 'És a ki hozzám fordítá irgalmasságát a király előtt és tanácsosai előtt és a király minden hatalmas fejedelmei előtt! És én megerősödvén az Úrnak az én Istenemnek rajtam nyugovó kegyelme által, családfőket gyűjték össze Izráelből, hogy feljönnének velem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'Ezek pedig családfőik és nemzetségi eredetök azoknak, a kik feljövének velem Artaxerxes uralkodásakor Babilóniából:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'Fineás fiai közül: Gersóm; Ithamár fiai közül: Dániel; Dávid fiai közül: Hattus;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, 'A Sekánia fiai közül, Parós fiai közül: Zakariás s vele egy nemzetségben másfélszáz férfi;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'Pahath-Moáb fiai közül: Eljóénai, Zerahia fia s vele kétszáz férfi;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'Sekánia fiai közül a Jaháziel fia s ő vele háromszáz férfi;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'Ádin fiai közül: Ebed, Jónathán fia és vele ötven férfi;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'Élám fiai közül: Ésaiás, Athália fia és vele hetven férfi;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'Sefátia fiai közül: Zebádia, Mikháel fia és ő vele nyolczvan férfi;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, 'Joáb fiai közül: Obádia, Jéhiel fia és vele kétszáztizennyolcz férfi;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'Selómith fiai közül a Jószifia fia és vele százhatvan férfi;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'Bébai fiai közül: Zakariás, Bébai fia és vele huszonnyolcz férfi;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'Azgád fiai közül: Jóhanán, Hakkátán fia és vele száztíz férfi;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'Adónikám fiai közül az utódok s neveik: Elifélet, Jeiél és Semája és velök hatvan férfi;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'És Bigvai fiai közül: Uthai és Zabbud és velök hetven férfi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'Mikor pedig összegyűjtém őket az Aháva felé folyó folyóvízhez, hol három napig valánk, megnéztem jól a népet és a papokat, s a Lévi fiai közül nem találtam közöttük senkit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'Elküldém annakokáért Eliézert, Arielt, Semáját, Elnáthánt, Járibot, Elnáthánt, Náthánt, Zakariást, Mesullámot, mint családfőket, és Jójáribot és Elnáthánt, mint eszes embereket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'És rendelém őket Iddóhoz, a ki fő vala a Kászifia nevű helyen, és betanítám őket, hogy mit szóljanak Iddónak és az ő atyjafiainak, a Léviták szolgáinak a Kászifia nevű helyen, – hogy hozzanak szolgákat a mi Istenünk házához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'És elhozák nékünk, Istenünknek rajtunk nyugvó jó kegyelme szerint, Is-szekhelt, a Mahli fiai közül, a ki Lévi fia, a ki meg Izráel fia vala, és Serébiát, fiaival és tizennyolcz testvérével együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'És Hasábiát s vele Ésaiást, a Mérári fiai közül, testvéreivel és húsz fiával együtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'És a Léviták szolgái közül, a kiket Dávid és a fejedelmek adának a Léviták szolgálatába, kétszázhuszat; mindnyájok nevei feljegyeztettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'Ekkor bőjtöt hirdeték ott az Aháva folyóvíz mellett, hogy megaláznók magunkat a mi Istenünk előtt, hogy kérnénk tőle szerencsés utat magunknak, családainknak és minden marháinknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'Mert szégyeltem vala a királytól kérni sereget és lovagokat oltalmunkra a mi ellenségeink ellen ez útban, mert ezt mondtuk volt a királynak, mondván: A mi Istenünk kegyelme van mindazokon, a kik őt keresik, az ő javukra, és az ő hatalma és haragja mindazokon, a kik elhagyják őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'És bőjtölénk és a mi Istenünkhöz könyörgénk annakokáért, és meghallgatott minket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'Ekkor különválaszték a papi fejedelmek közül tizenkettőt Serébiához és Hasábiához és hozzájok atyjokfiai közül tízet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, 'És átmérém nékik az ezüstöt és aranyat és az edényeket, a mi Istenünk házának ajándékait, a melyeket a király és tanácsosai és fejedelmei és minden Babilóniában élő Izráeliták ajándékozának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'Kezökhöz mérék pedig hatszázötven tálentom ezüstöt, száz tálentomot érő ezüst edényeket és száz tálentom aranyat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'Húsz arany poharat, melyek ezer dárikot érnek vala, és két szép ragyogású rézedényt, melyek oly becsesek, mint az arany.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'És mondék nékik: Ti az Úrnak szentei vagytok, ez edények is szentek, és ez az ezüst és arany az Úrnak, atyáitok Istenének önkénytesen adott ajándék:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'Vigyázzatok azért reá és megőrizzétek, míg átméritek a papi fejedelmek, a Léviták és Izráel családainak fejedelmei előtt Jeruzsálemben az Úr házának kamaráiban!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'És átvevék a papok és a Léviták az ezüstöt, aranyat és az edényeket súly szerint, hogy vigyék Jeruzsálembe Istenünk házához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'Elindulánk pedig az Aháva folyóvíz mellől az első hó tizenkettedik napján, hogy Jeruzsálembe menjünk; s a mi Istenünk kegyelme nyugodott rajtunk, megszabadítván minket a ránk leselkedő ellenségnek kezéből ez úton.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'És megérkezénk Jeruzsálembe, és pihenénk ott három napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'Negyednap pedig átméretett az ezüst, az arany és az edények a mi Istenünk házában, Merémóth papnak Uriás fiának kezéhez, vele lévén Eleázár, a Fineás fia, és velök Józadáb, a Jésua fia és Nóadia, a Binnui fia, Léviták,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'Minden szám és súly szerint, s feljegyeztetett az egész súly abban az időben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'A kik pedig megérkeztek a fogságból, a rabságnak fiai, égőáldozatokat vivének Izráel Istenének: tizenkét tulkot egész Izráelért, kilenczvenhat kost, hetvenhét bárányt, tizenkét bakot bűnért való áldozatra, mindezt egészen égőáldozatul az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'És átadák a király parancsolatait a király helytartóinak, s a vizen túl lévő helytartóknak, és ezek segíték a népet és az Isten házát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, 'Minekutána ezek elvégeződének, jövének hozzám a főemberek, mondván: Izráel népe és a papok és a Léviták nem különíték el magokat e tartományok népeitől, a miképen pedig azoknak, a Kananeusoknak, Hitteusoknak, Perizeusoknak, Jebuzeusoknak, Ammonitáknak, Moábitáknak, Égyiptomiaknak és Emoreusoknak útálatos vétke szerint el kellett volna,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'Mert ezek leányai közül vettek vala feleséget magoknak és fiaiknak, és megelegyedett a szent mag e tartományok népeivel; és pedig a fejedelmek és főemberek valának elsők e bűnben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'Mihelyt e dolgot meghallottam, megszaggatám alsó- és felső ruhámat, s téptem fejem hajszálait és szakállamat, és veszteg ültem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'És hozzám gyűlének mindnyájan, a kik reszketve gondoltak Izráel Istenének beszédeire azoknak vétke miatt, a kik a fogságból megjöttek vala; és én veszteg ülök vala mind az estvéli áldozatig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'Az estvéli áldozatkor pedig felkeltem sanyargatásomból, megszaggatván alsó- és felső ruhámat; és térdeimre esvén, kiterjesztém kezeimet az Úrhoz, az én Istenemhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'És mondék: Én Istenem, szégyenlem és átallom felemelni, én Istenem, az én orczámat te hozzád, mert a mi álnokságaink felülhaladtak fejünk fölött és a mi vétkeink mind az égig nevekedtek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'A mi atyáink napjaitól fogva nagy vétekben vagyunk mi mind e mai napig, és a mi álnokságainkért adattunk vala mi, a mi királyaink és a mi papjaink a földi királyok kezébe, fegyver által rabságra és ragadományra és orczapirulásra, a mint ez a mai nap is van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'És most nem sok ideje, hogy az Úr, a mi Istenünk rajtunk könyörült, hogy hagyjon minékünk maradékot, és hogy adjon nékünk egy szeget az ő szent helyén, hogy így megvilágosítsa szemeinket a mi Istenünk, s hogy megelevenítsen bennünket egy kissé a mi szolgaságunkban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'Mert szolgák vagyunk mi, de szolgaságunkban nem hagyott el minket a mi Istenünk, hanem hozzánk fordítá irgalmasságát Persiának királyai előtt, hogy megelevenítene bennünket, hogy felemelhessük a mi Istenünk házát s megépíthessük annak romjait, és hogy adjon nékünk bátorságos lakást Júdában és Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'És most mit mondjunk, óh mi Istenünk, mindezek után? Azt, hogy mi mégis elhagytuk parancsolataidat,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'A melyeket parancsoltál szolgáid, a próféták által, mondván: A föld, melyre bementek, hogy bírjátok azt, tisztátalan föld, a tartományok népeinek tisztátalansága miatt, útálatosságaik miatt, melyekkel betölték azt egyik végétől a másikig tisztátalanságukban;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'Annakokáért leányaitokat ne adjátok az ő fiaiknak és az ő leányaikat ne vegyétek fiaitoknak, és ne keressétek barátságukat, sem javokat soha, hogy megerősödjetek és éljetek e föld javaival, és örökségképen adhassátok azt fiaitoknak mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'Mindazok után pedig, a mik reánk jövének gonosz cselekedeteinkért és nagy vétkünkért, hiszen te, mi Istenünk, jobban kedveztél nékünk, sem mint bűneink miatt érdemeltünk volna, s adád nékünk e maradékot,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, 'Hát megrontjuk-é ismét parancsolataidat s összeházasodunk-é ez útálatos népekkel? Nem fogsz-é haragudni reánk mindaddig, míg megemésztetünk, hogy sem maradékunk, sem hírmondónk ne legyen?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'Oh Uram, Izráel Istene! igaz vagy te, mert meghagytál minket, maradék gyanánt, mint e mai nap bizonyítja. Ímé előtted vagyunk vétkünkben, és nem állhatunk meg előtted e miatt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, 'És mikor imádkozék Ezsdrás és vallást tőn, sírva és földre borulva az Isten háza előtt, sereglének ő hozzá Izráelből igen nagy gyülekezetben férfiak és asszonyok és gyermekek, mert síra a nép is sokat és keservesen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, 'És szóla Sekhánia, Jéhielnek fia, az Élám fiai közül, és monda Ezsdrásnak: Mi vétkeztünk a mi Istenünk ellen, hogy idegen feleségeket vettünk magunknak e föld népei közül: mindazáltal van reménysége Izráelnek, mind e mellett is!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, 'Vessünk ugyanis frigyet a mi Istenünkkel, hogy elbocsátjuk mindazon asszonyokat és a tőlük szülötteket az én Uramnak és azoknak akaratja szerint, a kik reszketve gondolnak a mi Istenünk parancsolatára, és a törvény szerint cselekedjünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, 'Kelj fel! mert reád néz e dolog, s mi veled leszünk: légy erős és láss hozzá!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, 'Fölkele annakokáért Ezsdrás, és megesketé a papoknak, a Lévitáknak és az egész Izráelnek fejedelmeit, hogy e beszéd szerint fognak cselekedni; és megesküvének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, 'És fölkele Ezsdrás az Isten háza elől, és elméne Jóhanánnak, Eliásib fiának szobájához s bemenvén abba, kenyeret nem evék, sem vizet nem ivék, mert gyászol vala a rabságból hazajöttek vétke miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, 'És meghirdeték Júdában és Jeruzsálemben mindazoknak, a kik a rabságból hazajöttek, hogy Jeruzsálembe gyűljenek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, 'Valaki pedig el nem jön harmadnapra, a fejedelmek és vének tanácsa szerint, adassék minden vagyona a templomnak, és ő maga vettessék ki a rabságból hazajötteknek gyülekezetéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, 'Összegyűlének azért Júdának és Benjáminnak minden férfiai harmadnapra Jeruzsálembe a kilenczedik hóban, e hó huszadik napján, és leüle az egész nép az Isten házának piaczán, aggódván e dolog és az esőzések miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, 'Ekkor fölkele Ezsdrás, a pap, és monda nékik: Ti vétkeztetek, hogy idegen feleségeket vettetek magatoknak, hogy ezzel is többítenétek Izráel vétkét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, 'Annakokáért tegyetek vallást az Úr előtt, atyáitoknak Istene előtt, és cselekedjetek az ő akaratja szerint, elkülönítvén magatokat e föld népeitől és az idegen feleségektől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, 'És felele az egész gyülekezet, és monda felszóval: Ekképen, a te beszéded szerint kell minékünk cselekednünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, 'De e nép igen sok és az esős idő miatt kivül nem állhatunk; annak felette ez nem egy, sem nem két napi munka, mert sokan vagyunk, a kik vétkeztünk e dologban;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, 'Hadd álljanak hát elő fejedelmeink, az egész gyülekezeté, és mindenki, a ki idegen feleséget vett magának, városonként jőjjön elő bizonyos időben s velök a városoknak vénei és birái, hogy elfordítsuk magunkról a mi Istenünknek e dolog miatt való búsulásának haragját!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, 'Csak Jónathán, az Asáhel fia és Jahzéja, a Tikva fia állának fel ez ellen és Mésullám és Sabbethai, a Léviták támogaták őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, 'És cselekedének ekképen azok, a kik a rabságból hazajöttek; és választa magának Ezsdrás, a pap férfiakat, a családfőket, családjuk szerint, s mindnyájok nevei feljegyeztettek. És összeülének a tizedik hó első napján, hogy nyomozzák e dolgot;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, 'És bevégezék azt mindazon férfiakra nézve, a kik idegen feleséget vettek vala magoknak, az első hónak első napjáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, 'Találtatának pedig a papok fiai közül, a kik idegen feleségeket vettek vala magoknak, Jésuának, a Jósádák fiának és az ő testvéreinek fiai közül: Maaséja, Eliézer, Járib és Gedálja;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, 'És kezöket adák, hogy elbocsátják feleségeiket és egy kos áldozására ítéltetének vétkükért;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, 'Immér fiai közül pedig: Hanáni és Zebádja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, 'Hárim fiai közül: Maaszéja, Elija, Semája, Jéhiel és Uzzia,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, 'Pashur fiai közül: Eljoénaj, Maaszéja, Ismáel, Nethanéel, Józabád és Elásza;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, 'Továbbá a Léviták közül: Józabád, Simei és Kélája. (az a Kelita), Pethahja, Júda és Eliézer;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, 'Az énekesek közül pedig: Eliásib, s a kapunállók közül: Sallum, Telem és Uri;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, 'Továbbá Izráel népéből: Parós fiai közül: Ramia, Jezija, Malkija, Mijámin, Eleázár, Malkija és Benája;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, 'Elám fiai közül: Mattánia, Zakariás, Jéhiel, Abdi, Jerémóth és Élija;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, 'Zattu fiai közül: Eljóénai, Eljásib, Mattánia, Jerémóth, Zabád és Aziza;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, 'Bébai fiai közül: Jóhanán, Hanánia, Zabbai és Athlai;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, 'Báni fiai közül: Mesullám, Mallukh, Adája, Jásub, Seál és Rámóth;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, 'Pahath-Moáb fiai közül: Adna, Kelál, Benája, Maaszéja, Mattánia, Besaléel, Binnui és Manasse;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, 'A Hárim fiai pedig: Eliézer, Jissija, Malkija, Semája, Simeon;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, 'Benjámin, Mallukh, Semarja;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, 'Hásum fiai közül: Mattenai, Mattattá, Zabád, Elifélet, Jerémai, Manasse, Simei,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, 'Báni fiai közül: Maádai, Amrám és Uél;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, 'Benája, Bédéja, Keluhu;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, 'Vanja, Merémóth, Eliásib;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, 'Mattánia, Mattenai és Jaaszái;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, 'Báni, Binnui, Simei;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, 'Selemia, Náthán és Adája;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, 'Makhnadbai, Sásai, Sárai;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, 'Azareél, Selemia és Semária;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, 'Sallum, Amaria, József:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, 'A Nebó fiai közül: Jéiel, Mattithja, Zabád, Zebina, Jaddai, Jóel, Benája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, 'Mindezek idegen feleségeket vettek vala magoknak. És valának e feleségek között olyanok is, a kik már fiakat szültek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'Nehémiásnak, a Hakália fiának beszédei. És lőn a Kislév nevű hóban, a huszadik esztendőben, hogy én Susán várában valék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'És jöve hozzám Hanáni, egy az én atyámfiai közül, és vele együtt férfiak Júdából, és tudakozódtam tőlök a fogságból megszabadult maradék zsidók felől és Jeruzsálem felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'És mondának nékem: A fogságból megszabadult maradék zsidók ott abban a tartományban nagy nyomorúságban és gyalázatban vannak; és azonfelül Jeruzsálem kőfala lerontatott, s kapui tűzben égtek meg!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'Hogy pedig meghallám e beszédeket, leültem és sírtam és keseregtem napokon át, s bőjtölék és imádkozám a mennynek Istene előtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'És mondék: Kérlek Uram, mennynek Istene, nagy és rettenetes Isten! Ki megtartja a szövetséget és irgalmasságot az őt szeretőknek és az ő parancsolatait megtartóknak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'Oh, legyen figyelmetes a te füled, és szemeid legyenek nyitva, hogy meghallgassad a te szolgádnak könyörgését, melylyel én könyörgök most előtted nappal és éjjel Izráel fiaiért, szolgáidért, és vallást tészek az Izráel fiainak bűneiről, melyekkel vétkeztünk te ellened, én is s az én atyámnak háza vétkeztünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'Felette igen vétkeztünk ellened, és nem tartottuk meg a parancsolatokat, és a rendeléseket és a törvényeket, melyeket parancsoltál volt Mózesnek a te szolgádnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'Oh, emlékezzél meg arról a beszédről, melyet parancsoltál Mózesnek, a te szolgádnak, mondván: Ha ti vétkeztek, én meg elszélesztelek titeket a népek között;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'Ha pedig megtérendetek hozzám és megtartjátok parancsolataimat és cselekeszitek azokat: még ha az égnek utolsó szélén volnának is szétszórt gyermekeitek, onnan is összegyűjtöm őket és beviszem arra a helyre, melyet választottam, hogy lakozzék ott az én nevem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'És ők a te szolgáid és a te néped, a kiket megszabadítottál a te nagy erőd által és a te erős kezed által!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'Kérlek oh Uram, legyen figyelmetes a te füled a te szolgádnak könyörgésére és szolgáidnak könyörgésökre, a kik kívánják félni a te nevedet, és adj, kérlek, jó szerencsét most a te szolgádnak, és engedd, hogy kegyelmet találjon ama férfiú előtt. Én ugyanis a királynak pohárnoka voltam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'És lőn a Niszán nevű hóban, Artaxerxes királynak huszadik esztendejében, bor vala ő előtte és én fölvevém a bort, adám a királynak; azelőtt pedig nem voltam szomorú ő előtte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'És monda nékem a király: Miért szomorú a te orczád, holott te beteg nem vagy? Nem egyéb ez, hanem szívednek szomorúsága! És felette igen megfélemlém.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'Akkor mondék a királynak: Örökké éljen a király! Miért nem volna szomorú az én orczám, hiszen a város, az én atyáim sírjainak helye, pusztán hever és kapui megemésztettek tűzben?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'És monda nékem a király: Mi az, a mit kívánsz? És könyörgék a menny Istenéhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'És mondék a királynak: Ha tetszik a királynak és ha kedves előtted a te szolgád, azt kérem, hogy bocsáss el engem Júdába, atyáim sírjainak városába, hogy megépítsem azt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'És monda nékem a király (felesége pedig mellette ül vala): Meddig lészen utazásod és mikorra jösz vissza? És tetszék a királynak engem elbocsátani, miután én tudattam vele az időt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'És mondék a királynak: Ha tetszik a királynak, adasson nékem leveleket a folyóvizen túl lakó tiszttartókhoz, hogy hagyjanak engem utazni, míg Júdába érek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'És adasson egy levelet Ászáfhoz, a király erdeje őréhez, hogy adjon nékem fákat gerendákul a templom várának kapuihoz, és a város kőfalához, és a házhoz, melybe költözni fogok. És megadá nékem a király, az én Istenemnek rajtam nyugvó jó kegyelme szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'És megérkezém a folyóvizen túl való tiszttartókhoz és átadám nékik a király leveleit. Bocsátott vala pedig velem a király főembereket a seregből és lovagokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'Mikor pedig a Horonból való Szanballat és az Ammonita Tóbiás, a szolga, meghallották ezt, nagy bosszúságot okozott nékik, hogy jött valaki, a ki Izráel fiainak javokat keresi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'Azután elmenék Jeruzsálembe, és ott pihenék három napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'És fölkelék éjszaka, én és velem néhány férfi, mert nem jelentém meg senkinek, hogy mire indítá az én Istenem az én szívemet, hogy azt Jeruzsálemért megcselekedjem, és barom sem vala velem, csak az, melyen ülök vala,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'És kimenék a völgynek kapuján éjjel, és pedig a sárkányok forrása felé, majd a szemét-kapuhoz, és vizsgálgatám Jeruzsálem kőfalait, melyek elrontattak vala, és kapuit, melyek tűz által megemésztetének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'Azután átmenék a forrás kapujához és a király tavához, holott nem vala hely a baromnak, hogy velem átmenjen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'Azért gyalog menék fel a völgyben éjjel és vizsgálgatám a kőfalat, azután megfordultam és bementem a völgy kapuján, és hazatértem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'A főemberek pedig nem tudták vala, hova mentem, és hogy mit akarok cselekedni, és sem a zsidóknak, sem a papoknak, sem az előljáróknak, sem a főembereknek, sem a többi munkásoknak ez ideig nem jelentettem meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'Ekkor mondék nékik: Ti látjátok a nyomorúságot, a melyben mi vagyunk, hogy Jeruzsálem pusztán hever és kapui tűzben égtek meg; jertek, építsük meg Jeruzsálem kőfalát, és ne legyünk többé gyalázatul!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'És megjelentém nékik az én Istenemnek rajtam nyugvó jó kegyelmét, és a király beszédit is, a melyeket nékem szólt, és mondának: Keljünk fel és építsük meg! És megerősíték kezeiket a jóra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'Mikor meghallák ezt a Horonból való Szanballat és az Ammonita Tóbiás, a szolga, és az arab Gesem, gúnyoltak és lenéztek minket, mondván: Micsoda ez, a mit míveltek? Talán bizony a király ellen akartok pártot ütni?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'Kiknek felelék, és mondék: A mennynek Istene, ő ad jó szerencsét nékünk, és mi mint az ő szolgái kelünk föl és építünk, néktek pedig részetek és jogotok és emlékezetetek nincsen Jeruzsálemben!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'És fölkele Eliásib, a főpap és atyjafiai, a papok és építék a juhok kapuját; ők szentelék meg azt és állíták fel annak ajtait; építék pedig a kőfalat a Meáh toronyig, a melyet megszentelének, s azután Hanánel tornyáig;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'És ő mellette építének a Jerikóbeliek, ezek mellett pedig épített Zakkur az Imri fia;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'A halaknak kapuját pedig építék a Hasszenáa fiai, ők gerendázák be azt és állíták fel annak ajtait, kapcsait és závárait;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'Mellettök javítgatá a kőfalat Merémóth, Uriásnak, a Hakkós fiának fia, mellette pedig javítgatott Mesullám, Berekiásnak, a Mesézabéel fiának a fia, és ő mellette javítgatott Sádók, Baána fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'Ezek mellett pedig javítgatának a Tékoabeliek, a kiknek előkelői azonban nem hajták nyakukat az ő Urok munkájának jármába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'Az ó-város kapuját pedig javítgaták Jójada, a Pászéah fia és Mesullám, a Beszódia fia; ők gerendázák be azt és állíták fel annak ajtait, kapcsait és závárait;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'És mellettök javítgatott a Gibeonból való Melátia és a Meronothból való Jádón, Gibeonnak és Mispának lakosai, a folyóvizen túl való helytartónak hivatala helyéig;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'Mellettök javítgatott Uzziel, Harhajának fia az ötvösökkel, és ő mellette javítgatott Hanánia, a kenet-készítők egyike, és megerősíték Jeruzsálemet mind a széles kőfalig;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'Mellettök javítgatott Refája, Húr fia, a ki a Jeruzsálemhez tartozó tartomány felének fejedelme vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'Mellette javítgatott Jedája, Harumáf fia, és pedig a maga háza ellenébe, és mellette javítgatott Hattus, Hasabneja fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'A kőfal másik darabját javítgatá Malkija, Hárim fia és Hassub, a Pahath-Moáb fia, és a kemenczéknek tornyát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'És mellettök javítgatott Sallum, Hallóhés fia, a ki fejedelme vala a Jeruzsálemhez tartozó tartomány másik felének, ő és az ő leányai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'A völgy kapuját javítgaták Hánun és Zánoah lakói, ők építék meg azt és állíták fel annak ajtait, kapcsait és závárait; és a kőfalból ezer singet a szemét-kapuig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, 'A szemét-kaput pedig javítgatá Malkija, Rékáb fia, Beth-Hakkerem tartományának fejedelme, ő építé meg azt és állítá fel ajtait, kapcsait és závárait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, 'És a forrásnak kapuját javítgatá Sallum, a Kól-Hóze fia, Mispa tartományának fejedelme, ő építé meg és héjazá be azt és állítá fel ajtait, kapcsait és závárait; és a Selah tó kőfalát a király kertje felé, mind a garádicsokig, melyeken a Dávid városából alájőnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, 'Ő utána javítgata Nehémiás, Azbuk fia, Béth-Sur tartománya felének fejedelme, a Dávid sírjai ellenébe való helyig, és az újonnan készült tóig, és a vitézek házáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, 'Ő utána javítgatának a Léviták: Rehum, Báni fia, a ki mellett javítgata Hasábia, Kéila tartománya felének fejedelme, tartománya lakosaival;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, 'Ő utána javítgatának atyjokfiai: Bavvai, a Hénadád fia, Kéila tartománya másik felének fejedelme;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, 'Javítgatá pedig ő mellette Ézer, Jésuának fia, Mispa fejedelme, a kőfal egy másik darabját, a szegleten levő fegyveresház felmenetelének ellenébe;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, 'Ő utána Bárukh, Zakkai fia javítgatá buzgósággal a kőfal egy másik darabját, a szeglettől fogva Eliásib főpap házának ajtajáig:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, 'Ő utána javítgata Merémóth Uriásnak fia, a ki Hakkós fia vala, egy másik darabot, Eliásib házának ajtajától Eliásib házának végéig;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, 'Ő utána javítgatának a papok, a környék férfiai;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, 'Ezek után javítgata Benjámin és Hassub, az ő házok ellenébe, utánok pedig javítgata Azariás, Maaséja fia – a ki Ananiás fia vala – az ő háza mellett;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, 'Ő utánok javítgata Binnui, a Hénadád fia egy másik darabot, Azáriás házától mind a zugig és szegletig;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, 'Továbbá Palál, az Uzai fia, a szegletnek és a felső toronynak ellenébe, mely a király házából a tömlöcz udvaránál emelkedik ki; utána pedig Pedája, a Parós fia;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, '(A Léviták szolgái pedig laknak vala az Ófelben, a vizek kapujának ellenéig napkelet felé és a kiemelkedő torony ellenéig;)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, 'Ő utána javítgatának a Tékoabeliek egy másik darabot a kiemelkedő nagy toronynak ellenétől fogva az Ófel kőfaláig;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, 'A lovak kapuján felül javítgatának a papok, kiki az ő házának ellenébe;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, 'Utánok javítgata Sádók, Immér fia az ő háza ellenébe; és ő utána javítgata Semája, Sekaniás fia, a napkeleti kapu őrizője;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, 'Ő utána javítgata Hananiás, Selemiás fia és Hánun, Sáláfnak hatodik fia egy másik darabot; utánok javítgata Mesullám, Berekiás fia, az ő szobája ellenébe;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, 'Utána javítgata Malkija, az ötvösök egyike, a Léviták szolgáinak és a kereskedőknek házáig, a törvénytevő ház kapujának ellenébe, a szegletnek hágójáig;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 32, 'A szeglet hágója és a juhok kapuja között pedig javítgatának az ötvösök és a kereskedők.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'Lőn pedig, mikor meghallotta Szanballat, hogy mi építjük a kőfalat, haragra gerjede és felette igen bosszankodék, és gúnyolá a zsidókat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'És szóla az ő atyjafiai és a samáriai sereg előtt, és ezt mondá: Mit művelnek e nyomorult zsidók? Vajjon megengedik-é ezt nékik? Talán áldozni fognak? Hát bevégezik ma? Avagy megelevenítik a köveket a porhalmazból, holott azok elégtek?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'Az Ammonita Tóbiás pedig mellette állván, mondá: Bármit építsenek, ha egy róka lép fel reá, összezúzza köveiknek falát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, 'Halld meg, oh mi istenünk! hogy csúffá lettünk, fordítsad gyalázásukat az ő fejökre, és add őket prédára a rabságnak földében;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'Ne fedezd el az ő hamisságokat és az ő bűnök a te orczád elől el ne töröltessék, mert téged bosszantának az építők előtt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'És építők a falat annyira, hogy elkészült az egész fal félmagasságban, mert a nép nagy kedvvel dolgozott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'Mikor pedig meghallotta Szanballat és Tóbiás, továbbá az Arábiabeliek, az Ammoniták és az Asdódeusok, hogy javítgattatnak Jeruzsálem kőfalai, és hogy a törések betömése megkezdődött, felette nagy haragra gerjedének;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'És összeesküvének mindnyájan egyenlő akarattal, hogy eljőnek Jeruzsálemet megostromolni és népét megrémíteni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'De mi imádkozánk a mi Istenünkhöz, és állítánk ellenök őrséget nappal és éjjel, mivelhogy féltünk tőlök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'És mondák a zsidók: Fogytán van ereje a tereh-hordónak, a rom pedig sok, és mi képtelenek vagyunk építeni a kőfalat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'A mi ellenségeink pedig ezt mondották: Ingyen se tudják meg, se ne lássák, míg közikbe bemegyünk és őket leöljük, és megszüntetjük a munkát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'És lőn, hogy eljöttek hozzánk mindenfelől a zsidók, a kik ő mellettök laknak vala és nékünk tízszer is mondották: Térjetek haza!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'Azért állítám a hely alsó és nyilt részeire a kőfal mögé, odaállítám a népet nemzetségek szerint, fegyvereikkel, dárdáikkal és kézíveikkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'És körültekintvén, fölkeltem és így szóltam az előljárókhoz, a főemberekhez és a többi néphez: Ne féljetek tőlök! A nagy és rettenetes Úrra emlékezzetek, és harczoljatok testvéreitekért, fiaitokért, leányaitokért, feleségeitekért és házaitokért!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'És lőn, hogy meghallották a mi ellenségeink, hogy megtudtuk az ő szándékukat, és hogy Isten semmivé tette az ő tanácsokat: megtérénk mi mindnyájan a kőfalhoz, kiki az ő munkájához;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'De azon naptól fogva legényeim egyik része munkálkodik vala, a másik része pedig tart vala dárdákat, paizsokat, kézíveket és pánczélokat, és a fejedelmek ott állának az egész Júda háznépe mögött.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'A kőfalon munkálkodók közül a tehernek hordói egyik kezökkel, a mely a munkát végezé, rakodának, másik kezök pedig a fegyvert tartja vala,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 18, 'A kik pedig építének, azoknak fegyverök derekokra vala felkötve és így építének; a trombitás pedig mellettem állt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 19, 'És így szóltam az előljárókhoz, a főemberekhez és a többi néphez: A munka felette sok és messzeterjedő és mi elszéledvén a kőfalon, egymástól messze esünk;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 20, 'Azért oda gyűljetek hozzánk, hol a trombita szavát hallándjátok, a mi Istenünk hadakozik érettünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 21, 'Ekképen munkálkodunk vala; és legényeimnek fele dárdákat tart vala hajnalhasadtától fogva mind a csillagoknak feltámadásáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 22, 'Ugyanekkor megparancsolám a népnek, hogy minden ember legényével Jeruzsálemben háljon, hogy éjszaka őrködjenek felettünk és nappal dolgozzanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 23, 'És sem én, sem az én atyámfiai, sem legényeim, sem az őrizők, a kik én utánam valának, nem vetjük vala le ruháinkat; kiki csak mosódáskor teszi vala le fegyverét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'Lőn pedig nagy kiáltása a népnek és feleségeiknek az ő atyjokfiai, a zsidók ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Valának, a kik ezt mondják vala: Fiainkkal és leányainkkal együtt sokadmagunkkal vagyunk, nékünk gabona kell, hogy együnk és éljünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'És valának, a kik ezt mondják vala: Mind mezeinket, mind szőlőinket, mind házainkat zálogba kell adogatnunk, nékünk gabona kell, mert éhezünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'Viszontag valának, a kik ezt mondják vala: Kölcsön vettünk pénzt a király adójáért a mi mezeinkre és szőlőinkre;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'És ímé, bár a mi testünk épen olyan, mint a mi atyánkfiainak testök, s a mi fiaink olyanok, mint az ő fiaik, mi nékünk mégis rabság alá kell adnunk fiainkat és leányainkat, sőt vannak már rabszolga leányaink is, és nincs erőnk arra, hogy őket megválthatnók, hisz mezeink és szőlőink másokéi már!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'Felette nagy haragra gerjedtem azért, mikor kiáltásukat s e dolgokat hallottam;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'És magamba szállva, gondolkodtam erről, és megfeddém az előljárókat és főembereket, ezt mondván nékik: Ti a ti atyátokfiaival szemben uzsoráskodtok! És szerzék ő ellenök nagy gyűlést;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'És mondám nékik: Mi megváltottuk a mi atyánkfiait, a zsidókat, a kik a pogányoknak eladattak vala, a mi tehetségünk szerint; és ti is meg akarjátok venni a ti atyátokfiait, s ők nékünk adják el magokat?! És hallgatának és nem tudának felelni semmit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'És mondék: Nem jó dolog ez, a mit ti cselekesztek. Hát nem fogtok a mi Istenünk félelmében járni, hogy valahára ne gyalázzanak már minket a pogányok, a mi ellenségeink?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'Hiszen én, atyámfiai és legényeim is pénzt és gabonát kölcsönöztünk nékik; engedjük el, kérlek, e tartozást!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'Adjátok vissza, kérlek, nékik még ma az ő mezeiket, szőlőiket, olajkerteiket és házaikat; ennekfelette, a kölcsönadott pénznek, gabonának, bornak és olajnak századát engedjétek el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'És felelének: Visszaadjuk és tőlök nem veszünk semmit; úgy cselekszünk, a mint te mondod. Ekkor egybehívám a papokat és megeskettetém őket, hogy e beszéd szerint fognak cselekedni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'Ruhámat is megrázám és mondék: Épen így rázzon ki az Isten minden embert az ő házából és vagyonából, és épen így legyen kirázatott és üres, valaki meg nem teljesíti e beszédet. És monda az egész gyülekezet: Ámen. És dícsérék az Urat, és e beszéd szerint cselekedett a nép.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'Sőt azon naptól fogva, melyen Júdának földére helytartójukul rendeltettem, Artaxerxes királynak huszadik esztendejétől fogva harminczkettedik esztendejéig, azaz tizenkét esztendeig, sem én, sem az én atyámfiai a helytartónak járó kenyeret nem evénk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'Holott az előbbi helytartók, a kik én előttem valának, terhelék a népet és vevének tőlök kenyérért és borért negyven ezüst sikluson felül; sőt még legényeik is zsarnokoskodának a népen. De én nem cselekedém így az Isten félelme miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'Sőt még e kőfalon is dolgoztam; mezőt sem szereztünk; s minden én legényeim egybegyűltenek ott a munkára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'Annakfelette a zsidók, továbbá a másfélszáz főember és a kik jőnek vala mi hozzánk a körültünk lakó pogányok közül, az én asztalomnál esznek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, 'A mit minden napra készítenek vala: egy ökröt, hat kövér juhot, és madarakat is készítének nékem, minden tíz napra vala mindenféle bor bőségesen; és mindemellett sem kivántam be a helytartó kenyerét, mert nehéz vala a szolgálat ezen a népen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, 'Emlékezzél meg rólam, én Istenem, javamra, mindarról, a mit én e néppel cselekedtem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'És lőn, hogy mikor meghallá Szanballat, Tóbiás, az Arábiabeli Gesem és a mi többi ellenségeink, hogy megépítettem a kőfalat, s hogy nem maradt azon semmi romlás, jóllehet még az ideig ajtókat nem állíttattam a kapukra:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'Külde Szanballat és Gesem hozzám ilyen izenettel: Jer és találkozzunk a faluk egyikében, az Onó-völgyében; holott ők gonoszt gondoltak ellenem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'Küldék azért követeket hozzájok ilyen izenettel: Nagy dolgot cselekszem én, azért nem mehetek alá; megszünnék e munka, ha attól eltávozván, hozzátok mennék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'És küldének hozzám ilyen módon négy ízben, és én ilyen módon felelék nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'Küldé továbbá hozzám Szanballat ilyen módon ötödször az ő legényét, a kinek kezében egy felnyitott levél vala,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'Melyben ez vala írva: A szomszéd népek közt ez a hír és Gasmu is mondja, hogy te és a zsidók pártot akartok ütni, annakokáért építed te a kőfalat; és hogy te leszel az ő királyok, e beszédek szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'Sőt még prófétákat is rendelél, a kik hirdetnék te felőled Jeruzsálemben, ezt mondván: Király van Júdában! És most e dolgoknak híre a királyhoz is elérkezik, annakokáért jer és tanácskozzunk együtt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'Én pedig küldék ő hozzá ilyen izenettel: Nem történt semmi olyan, a minőt te mondasz, hanem csak magadtól gondoltad mindazt a te szívedben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'Mert mindezek el akarnak vala minket rettenteni, ezt mondván: Leveszik kezöket a munkáról és az félben marad! Azért hát, oh Uram! erősítsd meg az én kezeimet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'És én elmentem Semájának, a Delája fiának házába, a ki Mehétabeél fia vala, és őt bezárkózva találtam, és monda: Menjünk az Isten házába, a templom belsejébe és zárjuk be a templomnak ajtait, mert eljőnek, hogy megöljenek téged, és pedig éjjel jőnek el, hogy megöljenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'Én pedig mondék: Avagy ily férfiúnak, mint én vagyok, illik-é futni? Hát ilyen lévén mint én, beléphet-é valaki a templomba, élvén? Nem megyek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'És megismerém, hogy nem az Isten küldötte őt, hanem azt a prófécziát azért mondá nékem, mert Tóbiás és Szanballat felbérelték őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'Azért vala pedig felbérelve, hogy én megrettenjek és akképen cselekedvén, vétkezzem, hogy így rossz híremet költhessék és rágalmazhassanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'Emlékezzél meg én Istenem Tóbiásról és Szanballatról ezen cselekedeteik szerint, és a jövendőmondó Noádja asszonyról és a többi jövendőmondókról is, a kik rémítgetének engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'Elvégezteték pedig a kőfal Elul hónap huszonötödik napján, ötvenkét nap alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'És lőn, hogy midőn meghallák minden mi ellenségeink, megfélemlének minden pogányok, a kik körültünk valának, és igen összeestek a saját szemeikben, és megismerék, hogy a mi Istenünktől vitetett végbe e munka.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'E napokban is sok levelet küldének némely zsidó előljárók Tóbiásnak, és viszont Tóbiástól sok jöve hozzájok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'Mert sokan Júdában ő hozzá esküdtek, mivelhogy ő veje vala Sekániának, az Arah fiának, és Jóhanán, az ő fia, Mesullámnak, a Berékia fiának leányát vette volt el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'Sőt még jó szándékait is emlegetik vala előttem, és az én beszédeimet megvivék néki. Leveleket pedig Tóbiás folyton küldött, hogy engem elrettentene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'És lőn, hogy midőn megépítteték a kőfal, felállítám az ajtókat és kirendeltetének a kapunállók, az énekesek és a Léviták őrizetre;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'És hadnagyokká tevém Jeruzsálem fölött Hanánit, testvéremet és Hanániást, a vár fejedelmét, mivel hogy ő hűségesebb és istenfélőbb vala sokaknál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'És mondék nékik: Meg ne nyittassanak Jeruzsálem kapui mindaddig, míg a nap melegen nem süt, és míg az őrök ott állanak, addig tegyék be az ajtókat és zárjátok be azokat; azután állítsatok őrizőket Jeruzsálem lakosai közül, némelyeket az ő vigyázó helyökre, s másokat az ő házok ellenébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'A város pedig felette igen széles vala és nagy, s a nép kevés lévén benne, házak nem épültek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'Felindítá azért az én Istenem szívemet, hogy egybegyűjtsem az előljárókat, a főembereket és a népet, hogy felírattassanak; és megtalálám azok nemzetségének könyvét, a kik először jöttek vala fel Babilóniából, melyben ily írást találék:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, 'Ezek a tartománynak fiai, a kik feljöttek vala a rabság foglyai közül, a kiket fogva vitetett Nabukodonozor, Babilónia királya, s most visszajövének Jeruzsálembe és Júdába, kiki az ő városába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'Kik jövének Zorobábellel: Jésua, Nehémiás, Azariás, Raámia, Nahamáni, Mordokhai, Bilsán, Miszpereth, Bigvai, Nehum, Baána. Izráel népe férfiainak számok ez:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'Parós fiai: kétezerszázhetvenkettő;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'Sefátja fiai: háromszázhetvenkettő;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'Arah fiai: hatszázötvenkettő;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'Pahath-Moáb fiai, Jésua és Joáb fiaitól: kétezernyolczszáztizennyolcz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'Elám fiai: ezerkétszázötvennégy;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'Zattu fiai: nyolczszáznegyvenöt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'Zakkai fiai: hétszázhatvan;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'Binnui fiai: hatszáznegyvennyolcz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'Bébai fiai: hatszázhuszonnyolcz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'Azgád fiai: kétezerháromszázhuszonkettő;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'Adónikám fiai: hatszázhatvanhét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'Bigvai fiai: kétezerhatvanhét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'Adin fiai: hatszázötvenöt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'Áter fiai, Ezékiástól: kilenczvennyolcz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'Hásum fiai: háromszázhuszonnyolcz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'Bésai fiai: háromszázhuszonnégy;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'Hárif fiai: száztizenkettő;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'Gibeon fiai: kilenczvenöt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'Bethlehem és Netófa férfiai: száznyolczvannyolcz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'Anathóth férfiai: százhuszonnyolcz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'Beth-Azmáveth férfiai: negyvenkettő;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, 'Kirjáth-Jeárim, Kefira és Beéróth férfiai: hétszáznegyvenhárom;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, 'Ráma és Géba férfiai: hatszázhuszonegy;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, 'Mikmás férfiai: százhuszonkettő;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, 'Béthel és Ai férfiai: százhuszonhárom;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 33, 'A másik Nébó férfiai: ötvenkettő;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, 'A másik Elám fiai: ezerkétszázötvennégy;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, 'Hárim fiai: háromszázhúsz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, 'Jerikó fiai: háromszáznegyvenöt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, 'Lód, Hádid és Ónó fiai: hétszázhuszonegy;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, 'Szenáa fiai: háromezerkilenczszázharmincz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, 'A papok: Jedája fiai Jésua családjából: kilenczszázhetvenhárom;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, 'Immér fiai: ezerötvenkettő;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, 'Pashur fiai: ezerkétszáznegyvenhét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, 'Hárim fiai: ezertizenhét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, 'A Léviták: Jésua és Kadmiel fiai, Hódávia fiaitól: hetvennégy;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, 'Az énekesek: Asáf fiai: száznegyvennyolcz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, 'A kapunállók: Sallum fiai, Áter fiai, Talmón fiai, Akkub fiai, Hatita fiai, Sóbai fiai: százharmincznyolcz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, 'A Léviták szolgái: Siha fiai, Hasufa fiai, Tabbaóth fiai,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, 'Kérósz fiai, Szia fiai, Pádón fiai,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, 'Lebána fiai, Hagába fiai, Salmai fiai,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, 'Hanán fiai, Giddél fiai, Gahar fiai,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, 'Reája fiai, Resin fiai, Nekóda fiai,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, 'Gazzám fiai, Uzza fiai, Pászéah fiai,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, 'Bészai fiai, Meunim fiai, Nefiszim fiai,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, 'Bakbuk fiai, Hakufa fiai, Harhur fiai,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, 'Basluth fiai, Mehida fiai, Harsa fiai,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, 'Barkósz fiai, Sziszera fiai, Temah fiai,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, 'Nesiah fiai, Hatifa fiai;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, 'A Salamon szolgáinak fiai: Szótai fiai, Szófereth fiai, Perida fiai,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, 'Jaalá fiai, Darkón fiai, Giddél fiai,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, 'Sefátia fiai, Hattil fiai, Pókhereth-Hassebaim fiai, Ámon fiai;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, 'Összesen a Léviták szolgái és a Salamon szolgáinak fiai, háromszázkilenczvenkettő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, 'És ezek, a kik feljövének Tel-Melahból, Tel-Harsából, Kerub-Addán-Immérből, de nem mondhatták meg családjukat és eredetüket, hogy Izráelből valók-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, 'Delája fiai, Tóbiás fiai, Nekóda fiai, hatszáznegyvenkettő;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, 'És a papok közül: Habája fiai, Hakkós fiai, Barzillai fiai, a ki a Gileádbeli Barzillai leányai közül vett magának feleséget és ezek nevéről nevezteték;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, 'Ezek keresték írásukat, tudniillik nemzetségök könyvét, de nem találák, miért is kirekesztetének a papságból;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, 'És megmondá nékik a király helytartója, hogy ne egyenek a szentséges áldozatból, mígnem a pap ítél az Urimmal és Tummimmal;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, 'Mind az egész gyülekezet együtt negyvenkétezerháromszázhatvan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, 'Szolgáikon és szolgálóikon kivül – ezek valának hétezerháromszázharminczheten – valának nékik énekes férfiaik és asszonyaik kétszáznegyvenöten;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, 'Lovaik hétszázharminczhat, öszvéreik kétszáznegyvenöt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, 'Tevéik négyszázharminczöt, szamaraik hatezerhétszázhúsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, 'Némelyek pedig a családfők közül adakozának az építésre: a király helytartója ada a kincsekhez aranyban ezer dárikot, ötven medenczét, ötszázharmincz papi ruhát;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, 'A többi családfők pedig adának az építés költségére aranyban húszezer dárikot, és ezüstben kétezerkétszáz mánét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, 'És a mit a többi nép ada, az aranyban húszezer dárik, és ezüstben kétezer máne, és hatvanhét papiruha vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, 'És lakozának mind a papok, mind a Léviták, mind a kapunállók, mind az énekesek, mind a nép fiai, mind a Léviták szolgái, szóval az egész Izráel a magok városaikban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'Mikor pedig eljöve a hetedik hónap, és Izráel fiai az ő városaikban lakozának; felgyűle az egész nép egyenlőképen a piaczra, mely a vizek kapuja előtt vala, és mondák az írástudó Ezsdrásnak, hogy hozza elő a Mózes törvényének könyvét, melyet parancsolt vala az Úr Izráelnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'Előhozá azért Ezsdrás pap a törvényt a gyülekezet eleibe, melyben együtt valának férfiak és asszonyok és mindazok, a kik azt értelemmel hallgathaták, a hetedik hónap első napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'És olvasa abból a piaczon, mely a vizek kapuja előtt vala, kora reggeltől fogva mind délig, a férfiak és az asszonyok előtt és mindazok előtt, a kik azt érthetik vala, mivel az egész nép nagy figyelemmel hallgatá a törvényt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'Áll vala pedig az írástudó Ezsdrás egy ezen czélra csinált faemelvényen, és mellette álla jobb keze felől Mattithia, Sema, Anája, Uriás, Hilkiás, Maaszéja, balkeze felől pedig: Pedája, Misáel, Malkija, Hásum, Hasbaddána, Zakariás, Mesullám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'És felnyitá Ezsdrás a könyvet az egész nép szemei előtt, mert fölötte vala az egész népnek; és mikor fölnyitá, felálla az egész nép.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'És áldá Ezsdrás az Urat, a nagy Istent, és felele rá az egész nép felemelt kezekkel: Ámen! Ámen! És meghajtván magukat, leborulának az Úr előtt arczczal a földre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'Jésua, Báni, Serébia, Jámin, Akkub, Sabbethai, Hódija, Maaszéja, Kelita, Azáriás, Józabád, Hanán, Pelája Léviták pedig magyarázzák vala a népnek a törvényt, s a nép a maga helyén áll vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'Olvasának pedig a könyvből, Isten törvényéből világosan, s azután magyarázának, és a nép megérté az olvasottakat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'Ekkor Nehémiás, a király helytartója és Ezsdrás, a pap, az írástudó és a Léviták, a kik magyaráznak vala a népnek, így szólának az egész néphez: E nap szent az Úrnak, a ti Isteneteknek, ne keseregjetek és ne sírjatok, mert sír vala az egész nép, mikor a törvény beszédeit hallá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'És ő mondá nékik: Menjetek, egyetek kövért és igyatok édest és küldjetek belőle részt annak, a kinek semmi nem készíttetett, mert szent e nap a mi Urunknak, és ne bánkódjatok, mert az Úrnak öröme a ti erősségtek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'A Léviták is csendesíték vala az egész népet, mondván: Hallgassatok, mert e nap szent és ne bánkódjatok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'Elméne azért mind az egész nép enni és inni és részt küldeni és szerezni nagy vígasságot, mert megértették a beszédeket, a melyekre őket tanították vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'Másod napon pedig összegyűlének az egész népnek, a papoknak és Lévitáknak családfői Ezsdráshoz, az írástudóhoz, hogy megértenék a törvénynek beszédit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'Találák pedig írva a törvényben, melyet parancsolt vala az Úr Mózes által, hogy Izráel fiainak leveles színekben kell lakozniok az ünnepen, a hetedik hónapban,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'És hogy nékik tudatniok kell és ki kell hirdettetniök minden városaikban és Jeruzsálemben ezt: Menjetek ki a hegyre, és hozzatok lombokat a nemes és vad olajfáról, mirtus és pálmalombokat, szóval akármely sűrű levelű fáról lombokat, hogy csináljatok leveles színeket, a mint meg van írva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'Kiméne azért a nép, és hozának lombokat, és csinálának magoknak leveles színeket, kiki a maga háza tetején és pitvaraikban, továbbá az Isten háza pitvariban, a vizek kapujának piaczán és Efraim kapujának piaczán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'Csinála pedig az egész gyülekezet, mely hazatért a fogságból, leveles színeket, és lakának a leveles színekben; mert nem cselekedtek vala így Józsuénak, a Nún fiának idejétől fogva Izráel fiai mind az napiglan, és lőn felette igen nagy örömük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'És olvasának az Isten törvényének könyvéből minden napon, az első naptól fogva mind az utolsó napig, és ünneplének hét napon át; a nyolczadik napon pedig egybegyülekezés tartatott a törvény szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'Azután ugyanezen hónak huszonnegyedik napján egybegyűlének Izráel fiai és bőjtölének, gyászba öltözvén és port hintvén fejökre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'És elválának az Izráel magvából valók minden idegenektől, és előállván, vallást tőnek az ő bűneikről és atyáik hamisságairól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'És megállának helyökön, és olvasának az Úrnak, az ő Istenöknek törvénye könyvéből a nap negyedrésze alatt, negyedrésze alatt pedig vallást tőnek és leborulának az Úr előtt, az ő Istenök előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'És felálla a Léviták emelvényére Jésua, Báni, Kadmiel, Sebánia, Bunni, Serébia, Báni és Kenáni és kiáltának nagy felszóval az Úrhoz, az ő Istenökhöz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'És mondának a Léviták, Jésua, Kadmiel, Báni, Hasabnéja, Serébia, Hódija, Sebánia, Petáhia: Nosza áldjátok az Urat, a ti Isteneteket öröktől fogva mindörökké; és áldják a te dicsőséges nevedet, mely magasabb minden áldásnál és dícséretnél!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'Te vagy egyedül az Úr! Te teremtetted az eget, az egeknek egeit és minden seregöket, a földet és mindent, a mi rajta van, a tengereket minden bennök valókkal együtt; és te adsz életet mindnyájoknak, és az égnek serege előtted borul le.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'Te vagy az Úr, az Isten, a ki választottad Ábrámot és kihozád őt a Káldeusoknak Úr nevű városából, és nevezéd őt Ábrahámnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'És találád az ő szívét hűnek te előtted és szerzél vele szövetséget, hogy adod a Kananeusok, Hitteusok, Emoreusok, Perizeusok, Jebuzeusok, Girgázeusok földét, hogy adod az ő magvának; és megteljesítéd beszédeidet, mert igaz vagy te!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'Megtekintéd annakfelette a mi atyáinknak Égyiptomban való nyomorúságát, és az ő kiáltásukat meghallád a Veres tengernél,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'És tevél jeleket és csodákat a Faraón és minden szolgáin és földének egész népén, mert tudtad, hogy kevélyen cselekedtek a te néped ellen; és szerzél magadnak nevet, mint e mai napság is van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'És a tengert kétfelé választád ő előttök és szárazon menének át a tenger közepén; üldözőiket pedig mélységbe borítád, mint követ nagy vizekbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'És felhőnek oszlopában vezetéd őket nappal s tűznek oszlopában éjjel, hogy megvilágosítsd nékik az utat, melyen menjenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'És a Sinai hegyre leszállál, s szólál velök az égből, s adál nékik helyes végzéseket, igaz törvényeket, jó rendeléseket és parancsolatokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'A te szent szombatodat is megjelentéd nékik, és parancsolatokat, rendeléseket és törvényt parancsolál nékik szolgád, Mózes által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'És kenyeret az égből adál nékik éhségökben, és vizet a kősziklából hozál ki nékik szomjúságokban; és mondád nékik, hogy menjenek be és bírják a földet, melyre nézve fölemelted kezedet, hogy nékik adod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, 'Ők pedig, a mi atyáink, felfuvalkodának, és megkeményíték nyakukat és nem hallgaták parancsolataidat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, 'És vonakodának engedelmeskedni, és meg nem emlékezének a te csudatételeidről, a melyeket velök cselekedtél, hanem megkeményíték nyakukat, és arra adák fejöket, hogy visszatérnek rabságukba az ő makacskodásukban; de te bűnbocsánatnak Istene vagy, könyörülő és irgalmas, hosszútűrő és nagy kegyelmességű, és el nem hagytad őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, 'Sőt még borjúképet is csinálának magoknak, és ezt mondják: Ez a te Istened, a ki kihozott téged Égyiptomból, és nagy bosszúsággal illettek téged;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, 'És te nagy irgalmasságodban nem hagyád el őket a pusztában; a felhőnek oszlopa nem távozék el felőlök nappal, hogy vezérlené őket az úton, és a tűznek oszlopa éjjel, hogy világítana nékik az úton, melyen menének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, 'És a te jó lelkedet adád nékik, hogy őket oktatná; és mannádat nem vonád meg szájoktól, s vizet adál nékik szomjúságokban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, 'És negyven esztendeig tápláltad őket a pusztában, fogyatkozásuk nem vala, ruháik el nem nyűttenek és lábaik meg nem dagadának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, 'Adál annakfelette nékik országokat és népeket, és elosztád ezeket határok szerint és ők elfoglalák Sihón földét, és Hesbon királyának földét, és Ógnak, Básán királyának földét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, 'Fiaikat pedig megsokasítád, mint az ég csillagait, és bevivéd őket a földre, mely felől megmondád atyáiknak, hogy bemennek arra, hogy bírják azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, 'És bemenének a fiak és elfoglalák a földet, és megalázád előttök a földnek lakóit, a Kananeusokat, s kezökbe adád őket, mind királyaikat, mind a föld népeit, hogy cselekedjenek velök kedvök szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, 'És megvevének erős városokat és kövér földet, s elfoglalának minden jóval teljes házakat, kőből vágott kutakat, szőlős és olajfás kerteket és sok gyümölcsfát, s evének és megelégedének és meghízának, s gyönyörködének a te nagy jóvoltodban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, 'Makacskodának pedig és pártot ütének ellened, és veték törvényedet hátuk mögé; prófétáidat is meggyilkolák, a kik bizonyságot tőnek ellenök, hogy őket te hozzád térítenék, és nagy bosszúsággal illettek téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, 'Annakokáért adád őket nyomorgatóik kezébe és megnyomorgaták őket; de nyomorúságok idején hozzád kiáltának, és te az égből meghallgatád és nagy irgalmasságod szerint adál nékik szabadítókat, és megszabadíták őket nyomorgatóik kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, 'És mikor megnyugodtak vala, ismét gonoszt cselekvének előtted, és te átadád őket ellenségeik kezébe, a kik uralkodának rajtok; s midőn ismét hozzád kiáltának, te az égből meghallgatád és megszabadítád őket irgalmasságod szerint sokszor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, 'És bizonyságot tevél ellenök, hogy visszatérítsd őket törvényedhez; de ők felfuvalkodának s nem hallgaták parancsolatidat, és végzéseid ellen vétkezének, melyeket ha valaki megtart, él azok által; és makacskodva hátat fordítának, s nyakukat megkeményíték és nem engedelmeskedének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, 'És mégis meghosszabbítád felettök kegyelmedet sok esztendőkön át, s bizonyságot tevél ellenök lelkeddel, prófétáid által, de nem figyelmezének; annakokáért adád őket a föld népeinek kezébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, 'De nagy irgalmasságod szerint meg nem emésztéd őket, sem el nem hagyád őket, mert te könyörülő és irgalmas Isten vagy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, 'Most annakokáért, oh mi Istenünk, nagy, erős és rettenetes Isten, a ki megőrized a szövetséget és irgalmasságot, ne legyen kicsiny előtted mindaz a nyomorúság, a mely utolért minket, királyainkat, fejedelmeinket, papjainkat, prófétáinkat, atyáinkat és egész népedet, Assiria királyainak napjaitól fogva mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, 'Hiszen te igaz vagy mindenekben, valamelyek reánk jövének; mert te igazságot műveltél, mi pedig hamisságot cselekvénk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, 'Hiszen a mi királyaink, fejedelmeink, papjaink és atyáink nem cselekedték törvényedet és nem figyelmeztek parancsolataidra és bizonyságtételeidre, melyek által bizonyságot tettél ő ellenök;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, 'És ők az ő országokban s a te nagy jóvoltodban, melylyel megáldád őket, s a széles és kövér földön, melyet nékik adál, nem akartak szolgáid lenni; és nem tértek meg gonosz cselekedeteikből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, 'És ímé mi most szolgák vagyunk azon a földön, melyet a mi atyáinknak adál, hogy ennék annak gyümölcsét és javát, ímé mi szolgák vagyunk azon;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, 'És termését bőven hozza a királyoknak, a kiket fölibünk helyezél a mi bűneinkért, s testeinken uralkodnak és barmainkon az ő kedvök szerint; és mi nagy nyomorúságban vagyunk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 38, 'És mindemellett mi erős kötést szerzénk és azt aláírtuk, melyet megpecsételének a mi fejedelmeink, Lévitáink és papjaink.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, 'A megpecsételt kötéseken pedig ott valának: Nehémiás, a király helytartója, a Hakhalia fia és Sédékiás;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'Serája, Azariás, Jeremiás,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'Pashur, Amaria, Malakiás,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Hattus, Sebánia, Malluk,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'Hárim, Merémóth, Abdiás,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'Dániel, Ginnethón, Bárukh,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'Mesullám, Abija, Mijámin,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'Maazia, Bilgai, Semája; ezek papok voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'A Léviták pedig ezek: Jésua, Azania fia, Binnui, a Hénadád fiai közül, Kadmiel,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'És atyjafiaik: Sebánia, Hódija, Kelita, Pelája, Hanán,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'Mika, Rehób, Hasábia,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'Zakkur, Serébia, Sebánia,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Hódija, Báni, Beninu.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'A nép fejei pedig ezek: Parós Pahath-Moáb, Elám, Zattu, Báni,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'Bunni, Azgád, Bébai,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'Adonija, Bigvai, Adin,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'Áter, Ezékiás, Azzur,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'Hódija, Hásum, Bésai,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'Hárif, Anathóth, Nébai,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'Magpiás, Mesullám, Hézir,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'Mesézabel, Sádók, Jaddua,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Pelátia, Hanán, Anája,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'Hóseás, Hanánia, Hásub,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'Hallóhes, Pilha, Sóbek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'Rehum, Hasabná, Maaszéja,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'És Ahija, Hanán, Anán,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'Mallukh, Hárim, Baána.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'És a nép többi része, a papok, a Léviták, a kapunállók, az énekesek, a Léviták szolgái és mindenki, a ki elkülöníté magát a tartományok népeitől, az Isten törvényéhez állván, feleségeik, fiaik, leányaik, mindenki, a kinek értelme és okossága vala,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'Csatlakozának atyjokfiaihoz, előljáróikhoz, és átok mellett esküt tevének, hogy az Isten törvényében járnak, a mely Mózes által az Isten szolgája által adatott vala ki; s hogy megőrzik és cselekeszik az Úrnak, a mi Urunknak minden parancsolatait, végzéseit és rendeléseit;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'És hogy nem fogjuk adni leányainkat feleségül a föld népeinek, sem az ő leányaikat nem fogjuk venni a mi fiainknak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'És hogy a föld népeitől, akik árúkat és mindenféle gabonát hoznak szombatnapon eladni, nem fogunk venni tőlök szombaton és egyéb szent napon, és hogy nem fogjuk bevetni a földet a hetedik esztendőben, és elengedünk minden tartozást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'És megállapítánk magunkra nézve parancsolatokat: hogy vetünk magunkra harmadrész siklust esztendőnként a mi Istenünk házának szolgálatára,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'A szent kenyerekre, a szüntelen való ételáldozatra és a szüntelen való égőáldozatra, a szombatokon, újholdak napján viendő áldozatokra, az ünnepnapokra, a szent dolgokra, a bűnért való áldozatokra, hogy mindezek megtisztítsák Izráelt; és a mi Istenünk házának minden munkájára;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'Sorsot veténk továbbá a fa hozása felől a papok, Léviták és a nép között, hogy hordjuk azt a mi Istenünk házába családaink szerint bizonyos időkben esztendőnként, hogy égjen az Úrnak, a mi Istenünknek oltárán, a mint meg van írva a törvényben,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'És hogy felviszszük földünknek első zsengéjét és minden fa gyümölcsének első zsengéjét esztendőnként az Úr házába;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'Annakfelette fiainknak, barmainknak első fiait, a mint meg van írva a törvényben; továbbá, hogy elviszszük szarvasmarháinknak és juhainknak első fajzásait a mi Istenünk házába a papoknak, a kik szolgálnak a mi Istenünk házában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'És a mi lisztjeinknek, felemelt áldozatainknak, minden fa gyümölcsének, mustnak és olajnak zsengéjét felviszszük a papoknak, a mi Istenünk házának kamaráiba, földünknek tizedét pedig a Lévitákhoz; mert ők, a Léviták szedik be a tizedet minden földműveléssel foglalatoskodó városainkban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'És legyen a pap, Áron fia a Lévitákkal, midőn a Léviták a tizedet beszedik; és a Léviták vigyék fel a tizednek tizedét a mi Istenünk házába, a tárháznak kamaráiba;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, 'Mert a kamarákba kell hozniok Izráel fiainak és Lévi fiainak a gabonának, a mustnak és az olajnak ajándékát, holott vannak a szent edények és az Istennek szolgáló papok, a kapunállók és az énekesek; és mi nem hagyjuk el a mi Istenünknek házát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, 'És lakozának a nép fejedelmei Jeruzsálemben, a többi nép pedig sorsot vete, hogy minden tíz emberből vinnének egyet Jeruzsálembe, a szent városba lakóul, a többi kilencz pedig marad a maga városában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, 'És áldá a nép mindazon férfiakat, a kik önkéntesen vállalkozának arra, hogy Jeruzsálemben lakoznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, 'Ezek pedig a tartomány fejei, a kik Jeruzsálemben megtelepedének; de Júda városaiban lakozék kiki az ő örökségében, városaikban: az Izráel, a papok, a Léviták, a Léviták szolgái és Salamon szolgáinak fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, 'Jeruzsálemben azért megtelepedének a Júda fiai közül és Benjámin fiai közül: Júda fiai közül: Athája, Uzzija fia, ki Zakariás fia, ki Amaria fia, ki Sefátia fia, ki Mahalalél fia vala, a Pérecz fiai közül,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, 'És Maaszéja, Báruk fia, ki Kolhóze fia, ki Hazája fia, ki Adája fia, ki Jójárib fia, ki Zakariás fia, ki Hasilóni fia vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, 'Pérecz fiai összesen, a kik Jeruzsálemben laknak vala, négyszázhatvannyolcz erős férfi;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, 'Benjámin fiai pedig ezek: Szallu, Mesullám fia, ki Jóed fia, ki Pedája fia, ki Kólája fia, ki Maaszéja fia, ki Ithiel fia, ki Ézsaiás fia vala,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, 'És ő utána Gabbai, Szallai, kilenczszázhuszonnyolczan;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, 'És Jóel, a Zikri fia előljárójok volt ezeknek, Júda pedig, a Hasszenua fia, a város másodrendű előljárója.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, 'A papok közül: Jedája, Jójárib fia, Jákhin,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, 'Serája pedig, a Hilkiás fia, ki Mesullám fia, ki Sádók fia, ki Merájóth fia, ki Akhitúb fia volt, az Isten házának fejedelme vala,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, 'És atyjokfiai, a kik a ház munkáját teljesítik vala, nyolczszázhuszonketten; és Adája, a Jeróhám fia, ki Pelália fia, ki Amsi fia, ki Zakariás fia, ki Pashur fia, ki Malkija fia vala,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, 'És az ő atyjafiai, a családfők kétszáznegyvenketten, és Amasszai, Azarél fia, ki Ahzai fia, ki Mesillémóth fia, ki Immér fia vala,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, 'És az ő atyjokfiai, vitéz férfiak, százhuszonnyolczan, előljárójok volt pedig Zabdiel, a Haggedólim fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, 'A Léviták közül pedig: Semája, Hassub fia, ki Azrikám fia, ki Hasábia fia, ki Bunni fia vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, 'És Sabbethai és Józabád, az Isten házának külső munkája felett felügyelők valának a Léviták fejei közül,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, 'És Mattánia, – a Mika fia, ki Zabdi fia, ki Asáf fia vala, – a ki vezetője volt a hálaadó éneklésnek, s elkezdé azt az imádság után, és Bakbukia, a ki másodrendű vala atyjafiai között, és Abda, Sammua fia, ki Gálál fia, ki Jeduthun fia vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, 'A Léviták összesen a szent városban: kétszáznyolczvannégyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, 'A kapunállók pedig: Akkub, Talmón és atyjokfiai, a kapukat őrizők százhetvenketten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, 'A többi Izráeliták pedig, a papok, a Léviták lakozának Júdának minden városaiban, kiki az ő örökségében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, 'A Léviták szolgái pedig lakozának az Ófelben, és Siha és Gipsa valának előljáróik a Léviták szolgáinak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, 'A Léviták előljárója vala Jeruzsálemben, az Isten háza szolgálatjánál, Uzzi, a Báni fia, – ki Hasábia fia, ki Mattánia fia, ki Mika fia volt, – Asáf fiai, az énekesek közül;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, 'Mert ők, a Léviták, a király parancsolata szerint, az énekesek pedig kötés szerint végezék naponként való teendőjüket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, 'Petáhja pedig, a Mesézabel fia, Júda fiának, Zerahnak fiai közül, a király oldala mellett vala a nép minden dolgában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, 'A falukban, ezek határaiban pedig Júda fiai közül lakozának Kirjáth-Arbában és mezővárosaiban, Dibonban és mezővárosaiban, Jekabseélben és faluiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, 'Jésuában, Móladában és Beth-Péletben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, 'Hasár-Suálban, Beér-Sebában és mezővárosaiban,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, 'Siklágban, Mekónában és mezővárosaiban,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, 'En-Rimmonban, Sorában, Jarmuthban,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, 'Zánoáhban, Adullámban és faluiban, Lákisban és határaiban, Azékában és mezővárosaiban, – ekként laknak vala Beér-Sebától mind a Hinnóm völgyéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, 'Benjámin fiai pedig laknak vala Gebától fogva Mikmásban, Ajában, Béthelben és mezővárosaiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, 'Anatótban, Nóbban, Anániában,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, 'Hásórban, Rámában, Gittajimban,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, 'Hádidban, Sebóimban, Neballátban,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, 'Lódban, Onóban, s a mesteremberek völgyében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, 'A Léviták közül pedig némely júdai osztályok Benjáminhoz csatlakozának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, 'Ezek pedig a papok és Léviták, a kik feljövének Zorobábellel, Sealtiél fiával és Jésuával: Serája, Jeremiás, Ezsdrás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, 'Amária, Mallukh, Hattus,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, 'Sekánia, Rehum, Meremóth,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, 'Iddó, Ginnethói, Abija,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, 'Mijámin, Maádia, Bilga,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, 'Semája, Jójárib, Jedája,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, 'Szallu, Ámók, Hilkija, Jedája, – ezek valának fejei a papoknak és atyjokfiainak Jésua napjaiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, 'A Léviták pedig ezek: Jésua, Binnui, Kadmiel, Serébia, Jehuda, Mattánia, – ki vezetője vala hálaadó éneklésnek, atyjafiaival.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, 'És Bakbukia, s Unni, az ő atyjokfiai velök szemben, tisztök szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, 'És Jésua nemzé Jojákimot, s Jojákim nemzé Eliásibot, s Eliásib nemzé Jójadát,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, 'És Jójada nemzé Jónathánt, s Jónathán nemzé Jadduát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, 'Jójákim napjaiban pedig papok, családfők valának: Serája családjában Merája, Jerémiáséban Hanánia,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, 'Ezsdráséban Mesullám, Amáriáéban Jóhanán,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, 'Melikuéban Jónathán, Sebaniáéban József,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, 'Háriméban Adna, Merajóthéban Helkai,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, 'Iddóéban Zakhariás, Ginnethónéban Mesullám,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, 'Abijáéban Zikri, Minjáminéban és Móadiáéban Piltai,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, 'Bilgáéban Sammua, Semájáéban Jónathán,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, 'Jójáribéban Mattenai, Jedajáéban Uzzi,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, 'Szallaiéban Kallai, Amókéban Éber,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, 'Hilkijáéban Hasábia, Jedajáéban Nethanéel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, 'A Léviták közül Eliásib, Jójada, Jóhanán és Jaddua napjaiban felírattak a családfők, a papok pedig mind a persiai Dárius országlásáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, 'A Léviták családfői felírattattak a krónikák könyvében Jóhanánnak, Eliásib fiának napjaiig;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, 'A Léviták családfői valának: Hasábia, Serébia, Jésua a Kadmiel fia, és az ő atyjokfiai velök szemben a dícsérő és hálaadó éneklésre, Dávidnak, az Isten emberének parancsolata szerint, mint egy éneklő sereg együtt a másikkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, 'Mattánia, Bakbukia, Obádia, Mesullám, Talmón, Akkub pedig kapunállók, őrt állván a kapuk kincses házainál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, 'Ezek valának Jojákim napjaiban, ki Jésua fia, ki Jósadák fia volt, és Nehémiásnak, a helytartónak és Ezsdrásnak, a törvénytudó papnak napjaiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, 'Jeruzsálem kőfalának felszentelésekor pedig fölkeresék a Lévitákat minden ő helyeiken, hogy behozzák őket Jeruzsálembe, hogy véghezvigyék a felszentelést örömmel és hálaadással és énekléssel, czimbalmokkal, lantokkal és cziterákkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, 'És összegyűlének az énekesek fiai mind Jeruzsálem környékéről, mind pedig a Netófátiak faluiból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'Mind Beth-Gilgálból, mind Geba és Azmáveth határaiból, mert falukat építének magoknak az énekesek Jeruzsálem körül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, 'És minekutána megtisztíták magokat a papok és a Léviták, megtisztíták a népet is, s a kapukat és a kőfalat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, 'Azután felvivém Júda fejedelmeit a kőfalhoz és rendelék két nagy hálaadást éneklő sereget és csapatokat; az egyik jobbkéz felé méne a kőfal mellett a szemétkapu felé,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, 'És utánok méne Hósaája és Júda fejedelmeinek fele,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, 'És Azária, Ezsdrás és Mesullám,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, 'Júda és Benjámin, Semája és Jeremiás,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, 'A papok fiai közül kürtökkel; és Zakariás, a Jónathán fia, ki Semája fia, ki Mattánia fia, ki Mikája fia, ki Zakkur fia, ki Asáf fia vala,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, 'És az ő atyjafiai: Semája, Azarél, Milalai, Gilalai, Máaj, Nethanéel, Júda és Hanáni, Dávidnak, az Isten emberének éneklőszerszámaival; Ezsdrás pedig, az írástudó előttök megy vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, 'Méne pedig e sereg a forrás kapuja felé, s egyenesen fölmenének Dávid városának lépcsőin a kőfalhoz vezető lépcsőre, s menének Dávid háza mellett s a vizek kapujáig napkelet felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, 'A hálaadást éneklő második sereg pedig, mely átellenben megy vala – én pedig és a népnek fele utánok – méne a kőfal mellett, a kemenczék tornya mellett, mind a széles kőfalig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, 'És az Efraim kapuja mellett és az ó város kapuja mellett és a halaknak kapuja mellett és a Hananél tornya és a Meáh torony mellett mind a juhok kapujáig, s megállának a tömlöcz kapujában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, 'És megálla a hálaadást éneklő mindkét sereg az Isten házánál, és én s a fejedelmeknek fele velem,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, 'És a papok: Eljákim, Maaséja, Minjámin, Mikája, Eljoénai, Zakariás, Hanánia kürtökkel,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, 'És Maaséja, Semája, Eleázár, Uzzi, Jóhanán, Malkija, Elám és Ezer; és zengedeznek vala az énekesek, és Jizrahia az előljáró.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, 'És áldozának azon napon nagy áldozatokkal, és vigadának, mert az Isten megvidámítá őket nagy örömmel, sőt az asszonyok és gyermekek is vigadának; és Jeruzsálemnek öröme nagy messze hallatott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, 'És rendeltetének ama napon férfiak a kincseknek, felemelt áldozatoknak, első zsengéknek és a tizedeknek tárházai fölé, hogy összegyűjtsék azokba a városok határaiból a törvény szerint való részöket a papoknak és a Lévitáknak, mert örvendeze Júda a papokon és a Lévitákon, a kik ott állának tisztökben,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, 'Mint a kik megőrzik Istenök rendtartását s a tisztaság rendtartását, és az énekesek és a kapunállók is ott állának tisztökben, Dávidnak és az ő fiának, Salamonnak parancsolatja szerint;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, 'Mert Dávidnak napjaiban Asáf vala régtől fogva az énekesek és az Istennek hálát adó és őt dícsérő éneklésnek vezetője.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 47, 'És a Zorobábel és Nehémiás napjaiban megadja vala az egész Izráel az énekeseknek és kapunállóknak az ő részöket naponként, nevezetesen oda szentelik vala azt a Lévitáknak, a Léviták pedig az Áron fiainak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, 'Azon a napon olvasának a Mózes könyvéből a népnek hallatára és írva találák benne, hogy Ammón és Moáb soha be ne menjen az Isten gyülekezetébe,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, 'Mivelhogy nem mentek vala eleikbe Izráel fiainak kenyérrel és vízzel, sőt bérbe fogadták ellenök Bálámot, hogy őket megátkozná, de a mi Istenünk az átkot áldásra fordítá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, 'És lőn, hogy mikor hallották e törvényt, kirekesztének Izráel közül minden elegy-belegy népet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, 'Ennekelőtte pedig Eliásib, a pap, ki Istenünk házának kamarái fölé rendelteték, rokonságba jutott Tóbiással;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, 'És átengedett néki egy nagy kamarát, holott abban annakelőtte az ételáldozatot, a tömjént, az edényeket és az olajnak, mustnak és gabonának tizedét, mint a kapunállóknak, énekeseknek és Lévitáknak törvény szerint való részét és a papoknak ajándékát helyeztetik vala el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, 'Mind ennek történtekor én nem valék Jeruzsálemben, mert Artaxerxes babilóniai királynak harminczkettedik esztendejében visszamentem vala a királyhoz, s napok múltán újra szabadságot kértem a királytól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, 'És visszatérék Jeruzsálembe, és megértém e gonoszt, melyet Eliásib cselekedett vala Tóbiásért, hogy átengedett néki egy kamarát az Isten házának pitvaraiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, 'Igen gonosznak tetszék pedig ez nékem s kivettetém Tóbiás házának minden edényeit abból a kamarából;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, 'És parancsolatomra megtisztíták a kamarákat, és visszahordatám azokba Isten házának edényeit, az ételáldozatot és a tömjént.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, 'Megtudtam azt is, hogy a Léviták részeit nem adták meg; ennek miatta kiki az ő mezejére szélede el az Isten házában szolgáló Léviták és énekesek közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, 'És megfeddém a fejedelmeket, és mondék: Miért hagyatott el az Isten háza? És egybegyűjtvén a Lévitákat, helyökre állítám őket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, 'Az egész Júda pedig meghozá az olajnak, a mustnak és a gabonának tizedét a tárházakba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, 'És felügyelőkké rendelém a tárházak fölé Selemiát, a papot, Sádókot, az írástudót és Pedáját a Léviták közül, és melléjök Hanánt, ki Zakkur fia, ki Mattánia fia vala, mivelhogy híveknek ítéltettek volt és az ő tisztök vala kiosztani atyjokfiainak részét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, 'Emlékezzél meg én rólam én Istenem ezért, és ne engedd, hogy eltöröltessenek az én jótéteményeim, melyeket cselekedtem vala az én Istenem házával és rendtartásaival!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, 'Azon napokban láttam Júdában, hogy sajtót taposnak szombaton és gabonát hoznak be, szamarakra rakván, sőt bort, szőlőt és olajat is és mindenféle terhet behoznak Jeruzsálembe szombat napon, és bizonyságot tevék ellenök, a mely napon eleséget árulnak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, 'Tírusiak is lakozának a városban, a kik hoznak vala halat és mindenféle árút, melyeket eladnak vala szombat napon Júda fiainak Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, 'Annakokáért megfeddém Júda előljáróit, és mondám nékik: Micsoda gonosz dolog ez, a mit ti cselekesztek, hogy megfertőztetitek a szombatnak napját?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, 'Avagy nem így cselekedtek-é a ti atyáitok, s a mi Istenünk reánk hozá mindezen gonoszt és e városra?! És ti mégis növelitek Isten haragját Izráel fölött, megfertőztetvén a szombatot!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, 'Lőn annakokáért, hogy midőn megárnyékosodtak Jeruzsálem kapui a szombat előtt, parancsolatomra bezáratának az ajtók, s megparancsolám, hogy meg ne nyissák azokat szombat utánig, annakfelette legényeim közül a kapukhoz rendelék, mondván: Nem fog bejőni teher a szombatnak napján!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, 'Annakokáért a kereskedők és minden árúk árúsai kivül hálának Jeruzsálemen egyszer vagy kétszer;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, 'És bizonyságot tevék ellenök, és mondám nékik: Miért háltok ti e kőfal előtt? Ha ezt ismételitek, kezet vetek reátok! Az időtől fogva nem jöttenek szombaton.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, 'És megparancsolám a Lévitáknak, hogy magokat megtisztítsák, s hogy menjenek el és őrizzék a kapukat, hogy megszenteljék a szombatot. Ezért is emlékezzél meg rólam én Istenem és kedvezz nékem, kegyelmességednek nagy volta szerint!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, 'Ugyanazon napokban meglátogatám azokat a zsidókat, kik asdódi, Ammonita és Moábita asszonyokat vettek feleségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, 'És fiaik felerésze asdódi nyelven beszél vala, és nem tudnak vala beszélni zsidóul, hanem egyik vagy másik nép nyelvén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, 'Annakokáért feddődém velök, és megátkozám őket, és megverék közülök néhányat, és megtépém őket, és megesketém őket Istenre: Bizony ne adjátok leányaitokat az ő fiaiknak, és ne vegyetek leányaik közül feleséget fiaitoknak és magatoknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, 'Avagy nem ebben vétkezett-é Salamon Izráel királya? Noha nem volt sok nép között hozzá hasonlatos király, a kit szeret vala az ő Istene és királylyá tette vala őt Isten egész Izráel fölött; őt is bűnre vivék az idegen asszonyok:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, 'És néktek engedjünk-é, hogy cselekedjétek mindezen nagy gonoszságot, vétkezzetek Istenünk ellen, idegen asszonyokat vévén feleségül?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, 'Jójadának (ki Eliásib főpapnak fia vala) fiai közül is egy veje vala a Horonitbeli Szanballatnak, elűzém azért őt tőlem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, 'Emlékezzél meg ő rólok én Istenem, a papságnak és a papság szövetségének és a Lévitáknak ilyen megfertőztetéséért!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, 'És megtisztítám őket minden idegenektől és rendtartást szabék a papoknak és a Lévitáknak, kinek-kinek az ő dolgában,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, 'A fa hozására is bizonyos időkben és az első zsengékre. Emlékezzél meg én Istenem az én javamra!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'Ahasvérus idejében történt (ez az Ahasvérus az, a ki uralkodott Indiától fogva Szerecsenországig százhuszonhét tartományon),');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'Azokban a napokban, a mikor Ahasvérus király üle királyi székében, a mely Susán várában volt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'Uralkodása harmadik évében lakomát szerze minden fejedelmének és szolgáinak: Persia és Média hatalmasai, főemberei és a tartományok fejedelmei előtte valának,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'Midőn mutogatá országa dicsőségének gazdagságát és az ő méltóságának fényes díszét sok napon át, száznyolczvan napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'És mikor elmultak ezek a napok, tőn a király az egész népnek, mely Susán várában találtaték, kicsinytől nagyig, hét napig tartó lakomát, a király palotája kertjének udvarán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, 'Fehér gyapjú és kék bíbor szőnyegek valának megerősítve a fehér gyapjúból és bíborból való köteleken, ezüst karikákon és fehér márványból való oszlopokon. Aranyból és ezüstből való kerevetek voltak az alabástromból, fehér márványból, gyöngykőből és vörös márványból való padozaton.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'Ittak pedig arany poharakból és különb-különbféle poharakból, és királyi bor bőven vala, királyi módon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'És az ivás, rendelet folytán, kényszer nélkül történt; mert így hagyta meg a király háza minden gondviselőjének, hogy kinek-kinek akarata szerint cselekedjenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'Vásti királyné is lakomát szerze a nőknek, a királyi házban, mely Ahasvérus királyé vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'Hetedik napon, mikor megvídámult a király szíve a bortól, mondá Méhumánnak, Biztának, Hárbonának, Bigtának és Abagtának, Zetárnak és Karkásnak, a hét udvarmesternek, a kik szolgálának Ahasvérus király előtt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'Hogy hozzák el Vástit, a királynét a király elé, királyi koronával, hogy megmutassa a népeknek és fejedelmeknek az ő szépségét; mert szép arczú vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, 'De Vásti királyné nem akara menni a király szavára, mely vala az udvarmesterek által. Erre igen megharagudott a király, és az ő haragja felgerjede benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, 'És monda a király az időket mérő bölcseknek, (mert a királynak összes dolgai a jog- és törvénytudók elé tartoznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, 'Legközelebb valának pedig hozzá: Karséna, Sétár, Admata, Társis, Méres, Marséna, Mémukán, Persiának és Médiának hét fejedelme, a kik láták a király arczát, és elől ülének az országban):');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, 'Törvény szerint mit kellene cselekedni Vásti királynéval, mivelhogy nem teljesíté Ahasvérus királynak az udvarmesterek által üzent beszédét?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, 'Akkor monda Mémukán a király és a fejedelmek előtt: Nemcsak a király ellen vétkezett Vásti királyné; de valamennyi fejedelem és minden nép ellen, Ahasvérus király minden tartományában;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, 'Mert a királyné cselekedetének híre fut minden asszonyhoz, úgy, hogy megvetik férjeiket szemeik előtt, és azt mondják: Ahasvérus király megparancsolá, hogy Vásti királyné hozzá menjen, és nem ment.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, 'És e napon ugyanazt fogják mondani Persia és Média fejedelemasszonyai, a kik meghallják a királyné cselekedetét, a király minden fejedelmének, és lesz elég megvetés és harag.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, 'Ha azért a királynak tetszik, bocsásson ki királyi parancsot a maga részéről és irattassék a Persa-Méd törvények közé, visszavonhatatlanul, hogy ne jőjjön többé Vásti Ahasvérus király színe elé, és hogy az ő királyságát adja a király másnak, a ki jobb ő nálánál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, 'És hallják meg a király rendeletét, a melyet teend, egész országában, mert igen nagy az, hogy minden asszony adja meg a tiszteletet az ő férjének, a legnagyobbtól a legkisebbig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, 'És tetszett a szó a királynak és a fejedelmeknek, és a király Mémukán beszéde szerint cselekedék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, 'És leveleket külde a királynak minden tartományába, tartományról tartományra, annak saját írása szerint, és népről-népre, annak nyelve szerint, hogy legyen minden férfi úr az ő házában és beszéljen az ő népének nyelvén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'Ezek után, a mint megszünt Ahasvérus király haragja, megemlékezék Vástiról, és arról a mit cselekedett, és arról a mit végeztek felőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'És mondának a király apródai, a kik néki szolgálának: Keressenek a királynak szép ábrázatú szűz leányokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'És rendeljen a király tiszteket országának minden tartományába, a kik gyűjtsenek össze minden szép ábrázatú szűz leányt Susán várába, az asszonyok házába, Hégainak, a király kamarásának, az asszonyok őrzőjének keze alá, és adjanak nékik szépítő szereket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'És az a leány, a ki tetszik a király szemeinek, uralkodjék Vásti helyett. És tetszett a dolog a királynak, és úgy cselekedék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'Vala egy zsidó férfiú Susán várában, a kinek neve Márdokeus, Jáirnak fia, a ki Simei fia, a ki Kis fia, Benjámin nemzetségéből,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'A ki Jeruzsálemből fogva vitetett el a száműzött néppel, a mely elvitetett Jekóniással, Júda királyával együtt, a kit rabságba vitt el Nabukodonozor, babilóniai király.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'És ez gondviselője volt Hadassának, azaz Eszternek az ő nagybátyja leányának; mert sem atyja, sem anyja nem volt, és a leány szép alakú és szép ábrázatú vala, s mikor meghalt az ő atyja és anyja, Márdokeus leánya gyanánt magához fogadá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'Lőn pedig, mikor a király parancsa és rendelete kihirdettetett és sok leány gyűjtetett Susán várába, Hégai keze alá, akkor felvétetett Eszter is a király házába, Hégainak, az asszonyok őrének keze alá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'És tetszett a leány az ő szemeinek és kegyébe fogadá, és siete néki szépítő szereket adni, és kiadni az ő részét és hét leányzót, a kit néki a király házából kelle kiszemelni, és vivé őt és az ő szolgálóleányait az asszonyok legjobb házába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'Meg nem mondá Eszter az ő nemzetségét és származását; mert Márdokeus meghagyta néki, hogy meg ne mondja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'Márdokeus pedig minden nap járt az asszonyok házának pitvara előtt, hogy tudakozódjék Eszter hogyléte felől, és hogy mi történik vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'Mikor pedig eljött az ideje minden leánynak, hogy bemenne Ahasvérus királyhoz, miután asszonyok törvénye szerint tizenkét hónapig bántak vele (mert ennyi időbe telik az ő szépítésök, hat hónapig mirtusolajjal és hat hónapig illatos szerekkel és asszonyi szépítő szerekkel):');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'Akkor így ment a leány a királyhoz: Mindent, a mit kivánt, megadtak néki, hogy menjen azzal az asszonyok házából a király házáig;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'Este bement és reggel visszatért az asszonyok második házába, Sahásgáznak, a király udvarmesterének, a hálótársak őrzőjének kezei alá; nem jött többé a királyhoz, csak ha kivánta őt a király, és nevén hívták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'Mikor azért eljött az ideje Eszternek, a Márdokeus nagybátyja, Abihail leányának, a kit leánya gyanánt fogadott, hogy bemenne a királyhoz, nem kivánt mást, mint a mit Hégai, a király udvarmestere, az asszonyok őrzője mondott néki, és kedves vala Eszter mindenki szemei előtt, a ki őt látá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'És felviteték Eszter Ahasvérus királyhoz, az ő királyi házába, a tizedik hónapban, ez a Tébet hónapja, országlásának hetedik évében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'És a király Esztert minden asszonynál inkább szereté, és minden leánynál nagyobb kedvet és kegyelmet nyert ő előtte, és tette a királyi koronát az ő fejére, és királynévá tette Vásti helyett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'És nagy lakomát adott a király minden ő fejedelmének és szolgáinak, az Eszter lakomáját, és a tartományoknak nyugalmat adott, és ajándékokat osztogata király módjára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, 'És mikor összegyűjték a szűzeket másodszor, Márdokeus üle a király kapujában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, 'És Eszter nem mondá meg sem származását, sem nemzetségét, miképen megparancsolá néki Márdokeus; mert Márdokeus szavát Eszter úgy fogadá, mint mikor gyámja volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 21, 'Azokban a napokban pedig, mikor Márdokeus üle a király kapujában, megharagudott Bigtán és Téres, a király két udvarmestere, a kapu őrei, és azon voltak, hogy rávetik kezeiket Ahasvérus királyra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 22, 'Tudtára esett e dolog Márdokeusnak, és megmondá Eszter királynénak, és Eszter elmondá a királynak Márdokeus nevében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 23, 'És megvizsgálták a dolgot és úgy találták, és mind a kettőt fára akasztották. És megírattaték a krónikák könyvébe a király előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'Ezek után nagy méltóságra emelé Ahasvérus király Hámánt, a Hammedáta fiát, az Agágibelit, és felmagasztalá őt, és feljebb helyezteté székét minden fejedelménél, a kik vele valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'És a király minden szolgái, a kik a király kapujában valának, térdet hajtottak és leborultak Hámán előtt; mert úgy parancsolta meg nékik a király; de Márdokeus nem hajtott térdet és nem borult le.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'Mondának azért a király szolgái, a kik a király kapujában valának, Márdokeusnak: Miért szeged meg a király parancsát?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'Lőn pedig, mikor így szólnának néki minden nap és nem hallgata rájok, feljelenték Hámánnak, hogy lássák, megállnak-é Márdokeus dolgai, mert azt jelenté nékik, hogy ő zsidó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'És látván Hámán, hogy Márdokeus térdet nem hajt és nem borul le előtte, megtelék Hámán haraggal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'De kevés volt előtte, hogy csakis Márdokeusra magára vesse rá kezét, (mert megmondták néki Márdokeus nemzetségét) azért igyekezett Hámán elveszteni minden zsidót, a ki Ahasvérus egész országában vala, a Márdokeus nemzetét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'Az első hónapban, ez Nisán hónapja, Ahasvérus királyságának tizenkettedik évében, Púrt, azaz sorsot vetének Hámán előtt napról-napra és hónapról-hónapra a tizenkettedikig, s ez Adár hónapja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'És monda Hámán Ahasvérus királynak: Van egy nép, elszórva és elkülönítve a népek között, országod minden tartományában, és az ő törvényei különböznek minden nemzetségtől, és a király törvényeit nem teljesíti; a királynak bizony nem illik úgy hagyni őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'Ha a királynak tetszik, írja meg, hogy ők elvesztessenek, és én tízezer tálentom ezüstöt mérek a hivatalnokok kezeibe, hogy a király kincstárába vigyék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'Akkor lehúzá a király az ő gyűrűjét a maga kezéről, és adá azt az Agágibeli Hámánnak, Hammedáta fiának, a zsidók ellenségének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'És monda a király Hámánnak: Az ezüst tied legyen s a nép is, hogy azt cselekedjed vele, a mi néked tetszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'Előhivatának azért a király irnokai az első hónap tizenharmadik napján, és megiraték minden úgy, a miként Hámán parancsolá, a király fejedelmeinek és a kormányzóknak, a kik az egyes tartományokban valának, és minden egyes nép fejeinek; minden tartománynak annak írása szerint, és minden egyes népnek az ő nyelve szerint, Ahasvérus király nevében iratott és megpecsételtetett a király gyűrűjével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'És elküldettek a levelek futárok által a király minden tartományába, hogy kipusztítsák, megöljék és megsemmisítsék mind a zsidókat, ifjútól a vénig, gyermekeket és asszonyokat egy napon, tizenharmadik napján a tizenkettedik hónapnak, (ez Adár hónapja) és hogy javaikat elragadják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'Az írásnak mássa, hogy tétessék törvény minden egyes tartományban, meghirdettetett minden népnek, hogy legyenek készen azon a napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'A futárok kimenének gyorsan a király parancsával. És a törvény Susán várában is kiadatott; a király pedig és Hámán leültek, hogy igyanak; de Susán városa felháborodott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'Márdokeus pedig megtudta mindazt, a mi történt; és Márdokeus megszaggatá ruháit, zsákba és hamuba öltözék, és a város közepére méne és kiálta nagy és keserves kiáltással.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'És eljött a királynak kapuja elé; mert nem volt szabad bemenni a király kapuján zsákruhában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'És minden egyes tartományban, azon helyen, a hová a király parancsa és törvénye eljutott, nagy gyásza volt a zsidóknak, bőjt és siralom és jajgatás; zsák és hamu vala terítve sokak alá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'Eljöttek azért Eszternek leányai és udvarmesterei és megmondák néki, és megszomorodék a királyasszony nagyon, és külde ruhákat, hogy felöltöztetnék Márdokeust, és hogy vesse le a zsákot magáról; de nem fogadá el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'Akkor előhivatá Eszter Hatákot, a király udvarmesterei közül a ki az ő szolgálatára volt rendelve, és kiküldé őt Márdokeushoz, hogy megtudja, mi az és miért van az?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'Kiméne tehát Haták Márdokeushoz a város utczájára, mely a király kapuja előtt vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'És elmondá néki Márdokeus mindazt, a mi érte őt, és az ezüst összegét, a melyet Hámán mondott, hogy juttat a király kincséhez a zsidókért, hogy elvesztessenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'És az írott rendeletnek mássát is, a melyet Susánban adtak ki eltöröltetésökre, átadá néki, hogy mutassa meg Eszternek, és jelentse és hagyja meg néki, hogy menjen a királyhoz, könyörögni néki és esedezni előtte az ő nemzetségéért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'Elméne azért Haták, és elmondá Eszternek Márdokeus szavait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'És monda Eszter Hatáknak, és meghagyá néki, hogy tudassa Márdokeussal:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, 'A király minden szolgája és a király tartományainak népe tudja, hogy minden férfinak és asszonynak, a ki bemegy a királyhoz a belső udvarba hivatlanul, egy a törvénye, hogy megölettessék, kivévén, a kire a király aranypálczáját kinyujtja, az él; én pedig nem hívattam, hogy a királyhoz bemenjek, már harmincz napja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'És megmondák Márdokeusnak Eszter szavait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'És monda Márdokeus visszaüzenve Eszternek: Ne gondold magadban, hogy te a király házában megmenekülhetsz a többi zsidó közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'Mert ha e mostani időben te hallgatsz, másunnan lészen könnyebbségök és szabadulások a zsidóknak; te pedig és atyád háza elvesztek. És ki tudja, talán e mostani időért jutottál királyságra?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'És monda Eszter visszaüzenve Márdokeusnak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, 'Menj el és gyűjts egybe minden zsidót, a ki Susánban találtatik, és bőjtöljetek érettem és ne egyetek és ne igyatok három napig se éjjel se nappal, én is és leányaim így bőjtölünk és ekképen megyek be a királyhoz, noha törvény ellenére; ha azután elveszek, hát elveszek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'Elméne azért Márdokeus, és úgy cselekedett mindent, a mint néki Eszter parancsolá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'Történt pedig harmadnapon, hogy Eszter felöltözött királyiasan, és megállt a király házának belső udvarában, a király háza ellenében, és a király üle királyiszékében, a királyi házban, a ház ajtajának átellenében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'És lőn, a mint meglátá a király Eszter királynét, hogy áll az udvarban, kegyet talála szemei előtt, és kinyujtá a király Eszterre az arany pálczát, a mely kezében vala, akkor oda méne Eszter, és megilleté az arany pálcza végét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'És monda néki a király: Mi kell néked Eszter királyné? És mi a kérésed? Ha az ország fele is, megadatik néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'És felele Eszter: Ha a királynak tetszik, jőjjön a király és Hámán ma a lakomára, melyet néki készítettem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'És monda a király: Gyorsan elő Hámánt, hogy teljesítse Eszter kívánságát. És elment a király és Hámán a lakomára, a melyet Eszter készített vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'Monda pedig a király Eszternek borivás közben: Mi a te kivánságod? Megadatik néked. És mi a te kérésed? Ha az ország fele is, meglészen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'És felele Eszter, és monda: Az én kivánságom és kérésem ez:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'Ha kegyet találtam a király szemei előtt, és ha a királynak tetszik megadni kivánságomat és teljesíteni kérésemet: jőjjön el a király és Hámán a lakomára, a melyet készítek nékik, és holnap a király beszéde szerint cselekszem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'És kiment Hámán azon a napon vígan és jó kedvvel. De a mint meglátá Hámán Márdokeust a király kapujában, és ez fel nem kelt és nem mozdult meg előtte, megtelék Hámán haraggal Márdokeus ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'De megtartóztatá magát Hámán, és haza ment, és elküldvén, magához hivatá barátait és Zérest, az ő feleségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'És elbeszélé nékik Hámán gazdagságának dicsőségét, fiainak sokaságát és mindazt, a mivel felmagasztalta őt a király, és hogy feljebb emelte őt a fejedelmeknél és a király szolgáinál;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'És monda Hámán: Nem is hívott Eszter királyné mást a királylyal a lakomára, a melyet készített, hanem csak engem, és még holnapra is meghivattattam hozzá a királylyal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'De mindez semmit sem ér nékem, valamíg látom a zsidó Márdokeust ülni a király kapujában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'És monda néki Zéres, az ő felesége és minden barátja: Csináljanak ötven könyöknyi magas fát, és reggel mondd meg a királynak, hogy Márdokeust akaszszák reá, és akkor menj a királylyal a lakomára vígan. És tetszett a dolog Hámánnak, és megcsináltatta a fát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'Azon éjjel kerülte az álom a királyt, és megparancsolá, hogy hozzák elő a történetek emlékkönyvét, és ezek olvastattak a király előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'És írva találák, a mint Márdokeus feljelenté Bigtánát és Térest, a király két udvarmesterét, a küszöb őrzőit, a kik azon voltak, hogy rávetik kezöket Ahasvérus királyra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'És monda a király: Micsoda tisztességet és méltóságot adtak azért Márdokeusnak? És felelének a király apródjai, az ő szolgái: Semmit sem juttattak néki azért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'Akkor monda a király: Ki van az udvarban? (Mert Hámán jöve a királyi ház külső udvarába, hogy megmondja a királynak, hogy akasztassa fel Márdokeust a fára, a melyet készittetett néki.)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'És felelének néki a király apródjai: Ímé Hámán áll az udvarban. És mondja a király: Jőjjön be!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'És beméne Hámán, és monda néki a király: Mit kell cselekedni azzal a férfiúval, a kinek a király tisztességet kiván? (Hámán pedig gondolá az ő szívében: Kinek akarna a király nagyobb tisztességet tenni, mint én nékem?)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'És monda Hámán a királynak: A férfiúnak, a kinek a király tisztességet kiván,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'Hozzanak királyi ruhát, a melyben a király jár, és lovat, a melyen a király szokott ülni és a melynek fejére királyi koronát szoktak tenni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'És adják azt a ruhát és lovat a király egyik legelső fejedelmének a kezébe, és öltöztessék fel azt a férfiút, a kinek a király tisztességet kiván, és hordozzák őt a lovon a város utczáin, és kiáltsák előtte: Így cselekesznek a férfiúval, a kinek a király tisztességet kiván.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'Akkor monda a király Hámánnak: Siess, hozd elő azt a ruhát és azt a lovat, a mint mondád, és cselekedjél úgy a zsidó Márdokeussal, a ki a király kapujában ül, és semmit el ne hagyj mindabból, a mit szóltál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'Előhozá azért Hámán a ruhát és a lovat, és felöltözteté Márdokeust, és lovon hordozá őt a város utczáján, és kiáltá előtte: Így cselekesznek a férfiúval, a kinek a király tisztességet kiván.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'És Márdokeus megtére a király kapujához. Hámán pedig siete házába, búsulva és fejét betakarva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'És elbeszélé Hámán Zéresnek, az ő feleségének és minden barátjának mindazt, a mi vele történt. És mondának néki az ő bölcsei és Zéres, az ő felesége: Ha Márdokeus, a ki előtt kezdtél hanyatlani, a zsidók magvából való: nem bírsz vele, hanem bizony elesel előtte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'És a míg így beszélének vele, eljövének a király udvarmesterei, és siettek Hámánt a lakomára vinni, a melyet készített vala Eszter.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'És elméne a király és Hámán a lakomára, Eszter királynéhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'És monda a király Eszternek másodnapon is, borivás közben: Mi a te kivánságod Eszter királyné? Megadatik. És micsoda a te kérésed? Ha az országnak fele is, meglészen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'És felele Eszter királyné, és monda: Ha kegyet találtam szemeid előtt, oh király! és ha a királynak tetszik, add meg nékem életemet kivánságomra, és nemzetségemet kérésemre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'Mert eladattunk, én és az én nemzetségem, hogy kipusztítsanak, megöljenek és megsemmisítsenek minket; ha csak szolgákul, vagy szolgálókul adattunk volna el, akkor hallgatnék, jóllehet az ellenség nem adna kárpótlást a király veszteségéért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'És szóla Ahasvérus király, és monda Eszternek, a királynénak: Ki az és hol van az, a kit az ő szíve erre vitt, hogy azt cselekedné?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'És monda Eszter: Az ellenség és gyűlölő, ez a gonosz Hámán! Akkor Hámán megrettene a király és királyné előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'A király pedig felkele haragjában a borivástól és méne a palotakertbe; Hámán pedig ott maradt, hogy életéért könyörögjön Eszter királynénál; mert látta, hogy a király részéről elvégeztetett az ő veszte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'És mikor a király visszatért a palota kertjéből a borivás házába, Hámán a kerevetre esék, a melyen Eszter vala. Akkor monda a király: Erőszakot is akar elkövetni a királynén én nálam a házban?! A mint e szó kijött a király szájából, Hámán arczát befedék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'És monda Harbona, az udvarmesterek egyike a király előtt: Ímé a fa is, a melyet készített Hámán Márdokeusnak, a ki a király javára szólott vala, ott áll Hámán házában, ötven könyöknyi magas. És monda a király: Akasszátok őt magát reá!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'Felakaszták azért Hámánt a fára, a melyet készített Márdokeusnak, és megszünék a király haragja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'Azon a napon adá Ahasvérus király Eszter királynénak Hámánnak, a zsidók ellenségének házát, és Márdokeus beméne a király elébe, mert elmondotta Eszter, micsodája ő néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'Lehúzá azért a király az ő gyűrűjét, a melyet Hámántól elvett, és adá azt Márdokeusnak. Eszter pedig Márdokeust tette Hámán házának fejévé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'És tovább szóla Eszter a király előtt, és leborult annak lábaihoz és sírt és könyörgött, hogy semmisítse meg az agági Hámán gonoszságát és tervét, a melyet kigondolt a zsidók ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'És a király kinyujtá Eszterre az arany pálczát, és Eszter felkelt és megálla a király előtt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, 'És monda: Ha a királynak tetszik, és ha kegyet találtam ő előtte, és ha helyes a dolog a király előtt, és én kedves vagyok szemei előtt: írassék meg, hogy vonassanak vissza az agági Hámánnak, Hammedáta fiának tervéről szóló levelek, a melyeket írt, hogy elveszessék a zsidókat, a kik a király minden tartományában vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'Mert hogyan tudnám nézni azt a nyomorúságot, mely érné az én nemzetségemet, és hogyan tudnám nézni az én atyámfiainak veszedelmét?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'Monda pedig Ahasvérus király Eszter királynénak és a zsidó Márdokeusnak: Ímé Hámán házát Eszternek adtam, és őt felakasztották a fára azért, mert a zsidókra bocsátotta kezét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'Ti pedig írjatok a zsidóknak, a mint tetszik néktek a király nevében és pecsételjétek meg a király gyűrűjével; mert az írás, a mely a király nevében van írva és a királynak gyűrűjével van megpecsételve, vissza nem vonható.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'Hivattatának azért a király irnokai azonnal, a harmadik hónapban (ez a Siván hónap), annak huszonharmadik napján, és megírák úgy, a miként Márdokeus parancsolá a zsidóknak és a fejedelmeknek, a kormányzóknak és a tartományok fejeinek, Indiától fogva Szerecsenországig százhuszonhét tartományba; minden tartománynak annak írása szerint, és minden nemzetségnek az ő nyelvén, és a zsidóknak az ő írások és az ő nyelvök szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'És megírá Ahasvérus király nevében, és megpecsételé a király gyűrűjével. És külde leveleket lovas futárok által, a kik lovagolnak a királyi ménes gyors paripáin,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, 'Hogy megengedte a király a zsidóknak, a kik bármely városban vannak, hogy egybegyűljenek és keljenek fel életökért, és hogy kipusztítsák, megöljék és megsemmisítsék minden népnek és tartománynak seregét, a mely őket nyomorgatja, kicsinyeket és nőket, és hogy javaikat elragadják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'Egy napon, Ahasvérus királynak minden tartományában, tizenharmadik napján a tizenkettedik hónapnak (ez Adár hónapja).');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'Az írásnak mássa, hogy adassék törvény minden egyes tartományban, meghirdettetett minden népnek, hogy a zsidók készen legyenek azon a napon, hogy megbosszulják magokat ellenségeiken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'A futárok a királyi gyors paripákon kimenének sietve és sürgősen a király parancsolata szerint; és kiadatott a törvény Susán várában is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'Márdokeus pedig kiméne a király elől kék bíbor és fehér királyi ruhában, és nagy arany koronával, és bíborbársony palástban, és Susán városa vígada és örvendeze.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'A zsidóknak világosság támada, öröm, vigasság és tisztesség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'És minden tartományban és minden városban, a hová a király szava és rendelete eljuta, öröme és vigalma lőn a zsidóknak, lakoma és ünnep, és sokan a föld népei közül zsidókká lettek; mert a zsidóktól való félelem szállta meg őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'A tizenkettedik hónapban azért (ez az Adár hónap), annak tizenharmadik napján, a mikor eljött az ideje a király szavának és végzésének, hogy akkor teljesíttessék, azon a napon, a melyen a zsidók ellenségei remélték, hogy hatalmat vesznek rajtok, ellenkezőleg fordult; mert magok a zsidók vőnek hatalmat azokon, a kik őket gyűlölék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'Egybegyűlének a zsidók városaikban, Ahasvérus király minden tartományában, hogy rávessék kezöket azokra, a kik vesztöket keresték, és senki sem állhatott meg előttük; mert miattok való félelem szállott minden népre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'És a tartományok minden feje, fejedelmek, kormányzók és a király hivatalnokai magasztalták a zsidókat; mert a Márdokeustól való félelem szállott rájok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'Mert nagy volt Márdokeus a király házában, és híre elment minden tartományba; mert ez a férfiú, Márdokeus, emelkedett és nagyobbodott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'És leverték a zsidók minden ellenségeiket fegyverrel, megölvén és megsemmisítvén azokat, és akaratok szerint cselekedének gyűlölőikkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'És Susán várában megölének és megsemmisítének a zsidók ötszáz férfiút.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'Parsandátát, Dalpont és Aspatát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'Porátát, Adáliát és Aridátát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'Parmástát, Arisait, Aridait és Vajzátát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'Tíz fiát Hámánnak, Hammedáta fiának, a zsidók ellenségének megölték; de zsákmányra nem tették rá kezöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'Azon a napon megtudá a király a Susán várában megöletteknek számát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, 'És monda a király Eszter királynénak: Susán várában megöltek a zsidók és megsemmisítettek ötszáz férfiút és Hámán tíz fiát; a király többi tartományaiban mit cselekesznek? Mi a kivánságod? és megadatik néked. És mi még a te kérésed? és meglészen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'És monda Eszter: Ha a királynak tetszik, engedje meg holnap is a zsidóknak, a kik Susánban laknak, hogy cselekedjenek a mai parancsolat szerint, és Hámán tíz fiát akaszszák fel a fára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, 'És szóla a király, hogy úgy tegyenek. És kiadaték a parancs Susánban, és Hámán tíz fiát felakasztották.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'És összegyűltek a zsidók, a kik Susánban valának, Adár havának tizennegyedik napján is, és megölének Susánban háromszáz férfiút; de zsákmányra nem tették rá kezöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, 'És a többi zsidók is, a kik a király tartományaiban voltak, összegyűlének és feltámadtak életökért, és békében maradtak ellenségeiktől; megölének pedig gyűlölőikből hetvenötezeret; de zsákmányra nem tették rá kezöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, 'Történt ez az Adár hónapjának tizenharmadik napján, és megnyugovának a tizennegyedik napon, és tették azt vigalom és öröm napjává.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'De a zsidók, a kik Susánban valának, egybegyűlének azon hónap tizenharmadik és tizennegyedik napján, és megnyugovának azon hónap tizenötödik napján, és azt tették vigalom és öröm napjává.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'Azért a vidéki zsidók, a kik kerítetlen falvakban laktak, Adár hónapjának tizennegyedik napját tették öröm és vigalom napjává és ünneppé, a melyen ajándékokat küldözgetnek egymásnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'És megírá Márdokeus e dolgokat, és leveleket külde minden zsidónak, a ki Ahasvérus király minden tartományában, közel és távol, vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'Meghagyva nékik, hogy tartsák meg az Adár hónapnak tizennegyedik napját és annak tizenötödik napját évről-évre,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'Mint olyan napokat, a melyeken megnyugovának a zsidók ellenségeiktől, és mint olyan hónapot, a melyben keserűségök örömre és siralmuk ünnepre fordult; hogy tartsák meg azokat vigalom és öröm napjaiul, és küldjenek adjándékot egymásnak és adományokat a szegényeknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'És felfogadák a zsidók, hogy megcselekszik, a mit kezdettek és a mit Márdokeus íra nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'Mert az agági Hámán, Hammedátának fia, minden zsidónak ellensége, szándékozott a zsidókat elveszteni, és Púrt, azaz sorsot vetett, hogy őket megrontsa és megsemmisítse;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'De mikor a király tudomására jutott, megparancsolá levélben, hogy gonosz szándéka, a melyet gondolt a zsidók ellen, forduljon az ő fejére, és felakaszták őt és fiait a fára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'Annakokáért elnevezék e napokat Púrimnak a Púr nevétől. És azért ezen levél minden szava szerint, és a mit láttak erre nézve, és a mi érte őket:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'Elhatározák és elfogadák a zsidók mind magokra, mind ivadékokra és mindazokra, a kik hozzájok csatlakoznak, örök időkre, hogy megtartják e két napot, írásuk és határozatuk szerint, minden esztendőben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'És ezen napok emlékezetben lesznek és megülik azokat nemzedékről-nemzedékre, családról-családra, tartományról-tartományra és városról-városra. És ezek a Púrim napjai el nem múlnak a zsidók között, és emlékök ki nem vész ivadékaik közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'Ira pedig Eszter királyné, Abihail leánya és a zsidó Márdokeus egész hatalommal, hogy megerősítsék e második levelet a Púrimról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'És külde leveleket minden zsidónak Ahasvérus országának százhuszonhét tartományába, békességes és igazságos szavakkal;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, 'Hogy megerősíttessenek ezek a Púrim napjai, meghatározott idejökben, a miképen meghagyta nékik a zsidó Márdokeus és Eszter királyné, és a mint elrendelték magokra és ivadékaikra a bőjtölés és jajkiáltás dolgát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'És Eszter beszéde megerősíté ezt a Púrim történetét, és könyvbe iraték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'És Ahasvérus király adót vettete a földre és a tenger szigeteire.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'Az ő erejének és hatalmának minden cselekedete pedig és Márdokeus nagy méltóságának története, a mellyel felmagasztalá őt a király, avagy nincsenek-é megírva Média és Persia királyainak évkönyveiben,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'Mert a zsidó Márdokeus második volt Ahasvérus király után, nagy a zsidók között, és kedves az ő atyjafiai sokasága előtt, a ki javát keresé népének, és békességet szerze minden ivadékának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'Vala Úz földén egy ember, a kinek Jób vala a neve. Ez az ember feddhetetlen, igaz, istenfélő vala és bűn-gyűlölő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'Születék pedig néki hét fia és három leánya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'És vala az ő marhája: hétezer juh, háromezer teve és ötszáz igabarom és ötszáz szamár; cselédje is igen sok vala, és ez a férfiú nagyobb vala keletnek minden fiánál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'Eljártak vala pedig az ő fiai egymáshoz és vendégséget szerzének otthon, kiki a maga napján. Elküldtek és meghívták vala az ő három hugokat is, hogy együtt egyenek és igyanak velök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'Mikor pedig a vendégség napjai sorra lejártak vala, elkülde értök Jób és megszentelé őket, és jóreggel felserkene és áldozik vala égőáldozattal mindnyájuk száma szerint; mert ezt mondja vala Jób: Hátha vétkeztek az én fiaim és gonoszt gondoltak az Isten ellen az ő szivökben! Így cselekedik vala Jób minden napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'Lőn pedig egy napon, hogy eljövének az Istennek fiai, hogy udvaroljanak az Úr előtt; és eljöve a Sátán is közöttök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'És monda az Úr a Sátánnak: Honnét jösz? És felele a Sátán az Úrnak és monda: Körülkerültem és át meg át jártam a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'És monda az Úr a Sátánnak: Észrevetted-é az én szolgámat, Jóbot? Bizony nincs hozzá hasonló a földön: feddhetetlen, igaz, istenfélő, és bűngyűlölő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'Felele pedig az Úrnak a Sátán, és monda: Avagy ok nélkül féli-é Jób az Istent?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'Nem te vetted-é körül őt magát, házát és mindenét, a mije van? Keze munkáját megáldottad, marhája igen elszaporodott e földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'De bocsássad csak rá a te kezedet, verd meg mindazt, a mi az övé, avagy nem átkoz-é meg szemtől-szembe téged?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'Az Úr pedig monda a Sátánnak: Ímé, mindazt, a mije van, kezedbe adom; csak ő magára ne nyujtsd ki kezedet. És kiméne a Sátán az Úr elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, 'Lőn pedig egy napon, hogy az ő fiai és leányai esznek és bort isznak vala az ő elsőszülött bátyjoknak házában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, 'És követ jöve Jóbhoz, és monda: Az ökrök szántanak, a szamarak pedig mellettök legelésznek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'De a Sabeusok rajtok ütének és elhajták azokat, a szolgákat pedig fegyverrel ölék meg. Csak én magam szaladék el, hogy hírt adjak néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, 'Még szól vala ez, mikor jöve egy másik, és monda: Istennek tüze esék le az égből, és megégeté a juhokat és a szolgákat, és megemészté őket. Csak én magam szaladék el, hogy hírt adjak néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, 'Még ez is szól vala, mikor jöve egy másik, és monda: A Káldeusok három csapatot alkotának és ráütének a tevékre, és elhajták azokat; a szolgákat pedig fegyverrel ölék meg, csak én magam szaladék el, hogy hírt adjak néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, 'Még ez is szól vala, mikor jöve egy másik, és monda: A te fiaid és leányaid esznek és bort isznak vala az ő elsőszülött bátyjoknak házában;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, 'És ímé nagy szél támada a puszta felől, megrendíté a ház négy szegeletét, és rászakada az a gyermekekre és meghalának. Csak én magam szaladék el, hogy hírt adjak néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, 'Akkor felkele Jób, megszaggatá köntösét, megberetválá a fejét, és a földre esék és leborula.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, 'És monda: Mezítelen jöttem ki az én anyámnak méhéből, és mezítelen térek oda, vissza. Az Úr adta, az Úr vette el. Áldott legyen az Úrnak neve!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, 'Mindezekben nem vétkezék Jób, és Isten ellen semmi illetlent nem cselekedék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'Lőn pedig, hogy egy napon eljövének az Istennek fiai, hogy udvaroljanak az Úr előtt. Eljöve a Sátán is közöttök, hogy udvaroljon az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'És monda az Úr a Sátánnak: Honnét jösz? És felele a Sátán az Úrnak, és monda: Körülkerültem és át meg átjártam a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'Monda pedig az Úr a Sátánnak: Észrevetted-é az én szolgámat, Jóbot? Bizony nincs a földön olyan, mint ő; feddhetetlen, igaz, istenfélő, bűngyűlölő. Még erősen áll a ő feddhetetlenségében, noha ellene ingereltél, hogy ok nélkül rontsam meg őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'És felele a Sátán az Úrnak, és monda: Bőrt bőrért; de mindent a mije van, odaad az ember az életéért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, 'Azért bocsásd ki csak a te kezedet, és verd meg őt csontjában és testében: avagy nem átkoz-é meg szemtől-szembe téged?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'Monda pedig az Úr a Sátánnak: Ímé kezedbe van ő, csak életét kiméld.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'És kiméne a Sátán az Úr elől, és megveré Jóbot undok fekélylyel talpától fogva a feje tetejéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'És vőn egy cserepet, hogy azzal vakarja magát, és így ül vala a hamu közepett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'Monda pedig ő néki az ő felesége: Erősen állasz-é még mindig a te feddhetetlenségedben? Átkozd meg az Istent, és halj meg!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'Ő pedig monda néki: Úgy szólsz, mint szól egy a bolondok közül. Ha már a jót elvettük Istentől, a rosszat nem vennők-é el? Mindezekben sem vétkezék Jób az ő ajkaival.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'Mikor pedig meghallá Jóbnak három barátja mind ezt a nyomorúságot, a mely esett vala rajta: eljöve mindenik az ő lakó helyéből: a témáni Elifáz, a sukhi Bildád és a naamai Czófár; és elvégezék, hogy együtt mennek be, hogy bánkódjanak vele és vigasztalják őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'És a mint ráveték szemöket távolról, nem ismerék meg őt, és fenhangon zokognak vala; azután pedig megszaggatá kiki a maga köntösét, és port hintének fejökre ég felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'És ülének vele hét napon és hét éjszakán a földön, és nem szóla egyetlen egy szót egyik sem, mert látják vala, hogy igen nagy az ő fájdalma.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'Ezután megnyitá Jób az ő száját, és megátkozá az ő napját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'És szóla Jób, és monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, 'Veszszen el az a nap, a melyen születtem, és az az éjszaka, a melyen azt mondták: fiú fogantatott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'Az a nap legyen sötétség, ne törődjék azzal az Isten onnét felül, és világosság ne fényljék azon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Tartsa azt fogva sötétség és a halál árnyéka; a felhő lakozzék rajta, nappali borulatok tegyék rettenetessé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'Az az éjszaka! Sűrű sötétség fogja be azt; ne soroztassék az az esztendőnek napjaihoz, ne számláltassék a hónapokhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Az az éjszaka! Legyen az magtalan, ne legyen örvendezés azon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'Átkozzák meg azt, a kik a nappalt átkozzák, a kik bátrak felingerelni a leviathánt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'Sötétüljenek el az ő estvéjének csillagai; várja a világosságot, de az ne legyen, és ne lássa a hajnalnak pirját!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'Mert nem zárta be az én anyám méhének ajtait, és nem rejtette el szemeim elől a nyomorúságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'Mért is nem haltam meg fogantatásomkor; mért is ki nem multam, mihelyt megszülettem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'Mért vettek fel engem térdre, és mért az emlőkre, hogy szopjam?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'Mert most feküdném és nyugodnám, aludnám és akkor nyugton pihenhetnék –');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 'Királyokkal és az ország tanácsosaival, a kik magoknak kőhalmokat építenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'Vagy fejedelmekkel, a kiknek aranyuk van, a kik ezüsttel töltik meg házaikat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 16, 'Vagy mért nem lettem olyan, mint az elásott, idétlen gyermek, mint a világosságot sem látott kisdedek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 17, 'Ott a gonoszok megszünnek a fenyegetéstől, és ott megnyugosznak, a kiknek erejök ellankadt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 18, 'A foglyok ott mind megnyugosznak, nem hallják a szorongatónak szavát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 19, 'Kicsiny és nagy ott egyenlő, és a szolga az ő urától szabad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 20, 'Mért is ad Isten a nyomorultnak világosságot, és életet a keseredett szivűeknek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 21, 'A kik a halált várják, de nem jön az, és szorgalmasabban keresik mint az elrejtett kincset.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 22, 'A kik nagy örömmel örvendeznek, vigadnak, mikor megtalálják a koporsót.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 23, 'A férfiúnak, a ki útvesztőbe jutott, és a kit az Isten bekerített köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 24, 'Mert kenyerem gyanánt van az én fohászkodásom, és sóhajtásaim ömölnek, mint habok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 25, 'Mert a mitől remegve remegtem, az jöve reám, és a mitől rettegtem, az esék rajtam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 26, 'Nincs békességem, sem nyugtom, sem pihenésem, mert nyomorúság támadt reám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, 'És felele a témáni Elifáz, és monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, 'Ha szólni próbálunk hozzád, zokon veszed-é? De hát ki bírná türtőztetni magát a beszédben?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'Ímé sokakat oktattál, és a megfáradott kezeket megerősítetted;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'A tántorgót a te beszédeid fentartották, és a reszkető térdeket megerősítetted;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'Most, hogy rád jött a sor, zokon veszed; hogy téged ért a baj, elrettensz!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, 'Nem bizodalmad-é a te istenfélelmed, s nem reménységed-é utaidnak becsületessége?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'Emlékezzél, kérlek, ki az, a ki elveszett ártatlanul, és hol töröltettek el az igazak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'A mint én láttam, a kik hamisságot szántanak és gonoszságot vetnek, ugyanazt aratnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'Az Istennek lehelletétől elvesznek, az ő haragjának szelétől elpusztulnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'Az oroszlán ordítása, a sakál üvöltése, és az oroszlán-kölykök fogai megsemmisülnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'Az agg oroszlán elvész, ha nincs martaléka, a nőstény oroszlán kölykei elszélednek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, 'Szó lopódzék hozzám, s valami nesz üté meg abból fülemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'Éjjeli látásokon való töprengések között, mikor mély álom fogja el az embereket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'Félelem szálla rám, és rettegés, s megreszketteté minden csontomat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'Valami szellem suhant el előttem, s testemnek szőre felborzolódék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'Megálla, de ábrázatját föl nem ismerém, egy alak vala szemeim előtt, mély csend, és ilyen szót hallék:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, 'Vajjon a halandó igaz-é Istennél: az ő teremtője előtt tiszta-é az ember?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 18, 'Ímé az ő szolgáiban sem bízhatik és az ő angyalaiban is talál hibát:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 19, 'Mennyivel inkább a sárházak lakosaiban, a kiknek fundamentumok a porban van, és könnyebben szétnyomhatók a molynál?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 20, 'Reggeltől estig gyötrődnek, s a nélkül, hogy észrevennék, elvesznek örökre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 21, 'Ha kiszakíttatik belőlök sátoruk kötele, nem halnak-é meg, és pedig bölcsesség nélkül?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, 'Kiálts csak! Van-é, a ki felelne néked? A szentek közül melyikhez fordulsz?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, 'Mert a bolondot boszúság öli meg, az együgyűt pedig buzgóság veszti el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'Láttam, hogy egy bolond gyökerezni kezdett, de nagy hamar megátkoztam szép hajlékát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'Fiai messze estek a szabadulástól: a kapuban megrontatnak, mert nincs, a ki kimentse őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, 'A mit learatnak néki, az éhező eszi meg, a töviskerítésből is elviszi azt, kincseiket tőrvetők nyelik el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'Mert nem porból támad a veszedelem s nem földből sarjad a nyomorúság!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, 'Hanem nyomorúságra születik az ember, a mint felfelé szállnak a parázs szikrái.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'Azért én a Mindenhatóhoz folyamodnám, az Istenre bíznám ügyemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'A ki nagy, végére mehetetlen dolgokat művel, és csudákat, a miknek száma nincsen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'A ki esőt ad a földnek színére, és a mezőkre vizet bocsát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'Hogy az alázatosokat felmagasztalja, és a gyászolókat szabadulással vidámítsa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'A ki semmivé teszi a csalárdok gondolatait, hogy szándékukat kezeik véghez ne vihessék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'A ki megfogja a bölcseket az ő csalárdságukban, és a hamisak tanácsát hiábavalóvá teszi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'Nappal sötétségre bukkannak, és délben is tapogatva járnak, mint éjszaka.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, 'A ki megszabadítja a fegyvertől, az ő szájoktól, és az erősnek kezéből a szegényt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, 'Hogy legyen reménysége a szegénynek, és a hamisság befogja az ő száját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, 'Ímé, boldog ember az, a kit Isten megdorgál; azért a Mindenhatónak büntetését meg ne utáljad!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, 'Mert ő megsebez, de be is kötöz, összezúz, de kezei meg is gyógyítanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, 'Hat bajodból megszabadít, és a hetedikben sem illet a veszedelem téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, 'Az éhínségben megment téged a haláltól, és a háborúban a fegyveres kezektől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, 'A nyelvek ostora elől rejtve leszel, és nem kell félned, hogy a pusztulás rád következik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, 'A pusztulást és drágaságot neveted, és a fenevadaktól sem félsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, 'Mert a mezőn való kövekkel is frigyed lesz, és a mezei vad is békességben lesz veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, 'Majd megtudod, hogy békességben lesz a te sátorod, s ha megvizsgálod a te hajlékodat, nem találsz benne hiányt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 25, 'Majd megtudod, hogy a te magod megszaporodik, és a te sarjadékod, mint a mezőn a fű.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 26, 'Érett korban térsz a koporsóba, a mint a maga idején takaríttatik be a learatott gabona.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 27, 'Ímé ezt kutattuk mi ki, így van ez. Hallgass erre, jegyezd meg magadnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'Jób pedig felele, és monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, 'Oh, ha az én bosszankodásomat mérlegre vetnék, és az én nyomorúságomat vele együtt tennék a fontba!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'Bizony súlyosabb ez a tenger fövenyénél; azért balgatagok az én szavaim.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'Mert a Mindenható nyilai vannak én bennem, a melyeknek mérge emészti az én lelkemet, és az Istennek rettentései ostromolnak engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'Ordít-é a vadszamár a zöld füvön, avagy bőg-é az ökör az ő abrakja mellett?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'Vajjon ízetlen, sótalan étket eszik-é az ember; avagy kellemes íze van-é a tojásfehérnek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'Lelkem iszonyodik érinteni is; olyanok azok nékem, mint a megromlott kenyér!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, 'Oh, ha az én kérésem teljesülne, és az Isten megadná, amit reménylek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, 'És tetszenék Istennek, hogy összetörjön engem, megoldaná kezét, hogy szétvagdaljon engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'Még akkor lenne valami vigasztalásom; újjonganék a fájdalomban, a mely nem kimél, mert nem tagadtam meg a Szentnek beszédét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'Micsoda az én erőm, hogy várakozzam; mi az én végem, hogy türtőztessem magam?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'Kövek ereje-é az én erőm, avagy az én testem aczélból van-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'Hát nincsen-é segítség számomra; avagy a szabadulás elfutott-é tőlem?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, 'A szerencsétlent barátjától részvét illeti meg, még ha elhagyja is a Mindenhatónak félelmét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, 'Atyámfiai hűtlenül elhagytak mint a patak, a mint túláradnak medrükön a patakok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, 'A melyek szennyesek a jégtől, a melyekben olvadt hó hömpölyög;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, 'Mikor átmelegülnek, elapadnak, a hőség miatt fenékig száradnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, 'Letérnek útjokról a vándorok; felmennek a sivatagba utánok és elvesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, 'Nézegetnek utánok Téma vándorai; Sébának utasai bennök reménykednek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, 'Megszégyenlik, hogy bíztak, közel mennek és elpirulnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, 'Így lettetek ti most semmivé; látjátok a nyomort és féltek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 22, 'Hát mondtam-é: adjatok nékem valamit, és a ti jószágotokból ajándékozzatok meg engem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 23, 'Szabadítsatok ki engem az ellenség kezéből, és a hatalmasok kezéből vegyetek ki engem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 24, 'Tanítsatok meg és én elnémulok, s a miben tévedek, értessétek meg velem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 25, 'Oh, mily hathatósak az igaz beszédek! De mit ostoroz a ti ostorozásotok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 26, 'Szavak ostorozására készültök-é? Hiszen a szélnek valók a kétségbeesettnek szavai!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 27, 'Még az árvának is néki esnétek, és sírt ásnátok a ti barátotoknak is?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 28, 'Most hát tessék néktek rám tekintenetek, és szemetekbe csak nem hazudom?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 29, 'Kezdjétek újra kérlek, ne legyen hamisság. Kezdjétek újra, az én igazságom még mindig áll.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 30, 'Van-é az én nyelvemen hamisság, avagy az én ínyem nem veheti-é észre a nyomorúságot?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, 'Nem rabszolga élete van-é az embernek a földön, és az ő napjai nem olyanok-é, mint a béresnek napjai?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'A mint a szolga kívánja az árnyékot, és a mint a béres reményli az ő bérét:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, 'Úgy részesültem én keserves hónapokban, és nyomorúságnak éjszakái jutottak számomra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'Ha lefekszem, azt mondom: mikor kelek föl? de hosszú az estve, és betelek a hánykolódással reggeli szürkületig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'Testem férgekkel van fedve és a pornak piszokjával; bőröm összehúzódik és meggennyed.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'Napjaim gyorsabbak voltak a vetélőnél, és most reménység nélkül tünnek el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'Emlékezzél meg, hogy az én életem csak egy lehellet, és az én szemem nem lát többé jót.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'Nem lát engem szem, a mely rám néz; te rám veted szemed, de már nem vagyok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, 'A felhő eltünik és elmegy, így a ki leszáll a sírba, nem jő fel többé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'Nem tér vissza többé az ő hajlékába, és az ő helye nem ismeri őt többé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, 'Én sem tartóztatom hát meg az én számat; szólok az én lelkemnek fájdalmában, és panaszkodom az én szívemnek keserűségében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, 'Tenger vagyok-é én, avagy czethal, hogy őrt állítasz ellenem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, 'Mikor azt gondolom, megvigasztal engem az én nyoszolyám, megkönnyebbíti panaszolkodásomat az én ágyasházam:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, 'Akkor álmokkal rettentesz meg engem és látásokkal háborítasz meg engem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, 'Úgy, hogy inkább választja lelkem a megfojtatást, inkább a halált, mint csontjaimat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, 'Utálom! Nem akarok örökké élni. Távozzál el tőlem, mert nyomorúság az én életem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, 'Micsoda az ember, hogy őt ily nagyra becsülöd, és hogy figyelmedet fordítod reá?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, 'Meglátogatod őt minden reggel, és minden szempillantásban próbálod őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, 'Míglen nem fordítod el tőlem szemedet, nem távozol csak addig is tőlem, a míg nyálamat lenyelem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, 'Vétkeztem! Mit cselekedjem én néked, oh embereknek őrizője? Mért tettél ki czéltáblául magadnak? Mért legyek magamnak is terhére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, 'És mért nem bocsátod meg vétkemet és nem törlöd el az én bűnömet? Hiszen immár a porban fekszem, és ha keresel engem, nem leszek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, 'Akkor felele a sukhi Bildád, és monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, 'Meddig szólasz még efféléket, és lesz a te szádnak beszéde sebes szél?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'Elforgatja-é Isten az ítéletet, avagy a Mindenható elforgatja-é az igazságot?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'Ha a te fiaid vétkeztek ellene, úgy az ő gonoszságuk miatt vetette el őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'De ha te az Istent buzgón keresed, és a Mindenhatóhoz bocsánatért könyörögsz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'Ha tiszta és becsületes vagy, akkor legott felserken éretted, és békességessé teszi a te igazságodnak hajlékát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'És ha előbbi állapotod szegényes volt, ez utáni állapotod boldog lesz nagyon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, 'Mert kérdezd meg csak az azelőtti nemzedéket, és készülj csak fel az ő atyáikról való tudakozódásra!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, 'Mert mi csak tegnapiak vagyunk és semmit nem tudunk, mert a mi napjaink csak árnyék e földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'Nem tanítanak-é meg azok téged? Nem mondják-é meg néked, és nem beszélik-é meg szívök szerint néked?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, 'Felnövekedik-é a káka mocsár nélkül, felnyúlik-é a sás víz nélkül?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'Még gyenge korában, ha fel nem szakasztják is, minden fűnél elébb elszárad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'Ilyenek az ösvényeik mindazoknak, a kik Istenről elfeledkeznek, és a képmutatónak reménysége is elvész.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'Mivel szétfoszol bizakodása, és bizodalma olyan lesz, mint a pókháló.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'Házára támaszkodik, és nem áll meg; kapaszkodik belé, és nem marad meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'Bő nedvességű ez a napfényen is, és ágazata túlnő a kertjén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'Gyökerei átfonódnak a kőhalmon; átfúródnak a szikla-rétegen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, 'Ámha kiirtják helyéről, megtagadja ez őt: Nem láttalak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, 'Ímé ez az ő pályájának öröme! És más hajt ki a porból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, 'Ímé az Isten nem veti meg az ártatlant, de a gonoszoknak sem ád előmenetelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, 'Még betölti szádat nevetéssel, és ajakidat vigassággal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, 'Gyűlölőid szégyenbe öltöznek, és a gonoszok sátora megsemmisül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'Felele pedig Jób, és monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, 'Igaz, jól tudom, hogy így van; hogyan is lehetne igaz a halandó ember Istennél?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'Ha perelni akarna ő vele, ezer közül egy sem felelhetne meg néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'Bölcs szívű és hatalmas erejű: ki szegülhetne ellene, hogy épségben maradjon?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, 'A ki hegyeket mozdít tova, hogy észre se veszik, és megfordítja őket haragjában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, 'A ki kirengeti helyéből a földet, úgy hogy oszlopai megrepedeznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'A ki szól a napnak és az fel nem kél, és bepecsételi a csillagokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'A ki egymaga feszítette ki az egeket, és a tenger hullámain tapos.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'A ki teremtette a gönczölszekeret, a kaszás csillagot és a fiastyúkot és a délnek titkos tárait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, 'A ki nagy dolgokat cselekszik megfoghatatlanul, és csudákat megszámlálhatatlanul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'Ímé, elvonul mellettem, de nem látom, átmegy előttem, de nem veszem észre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'Ímé, ha elragad valamit, ki akadályozza meg; ki mondhatja néki: Mit cselekszel?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, 'Ha az Isten el nem fordítja az ő haragját, alatta meghajolnak Ráháb czinkosai is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'Hogyan felelhetnék hát én meg ő néki, és lelhetnék vele szemben szavakat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, 'A ki, ha szinte igazam volna, sem felelhetnék néki; kegyelemért könyörögnék ítélő birámhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, 'Ha segítségül hívnám és felelne is nékem, még sem hinném, hogy szavamat fülébe vevé;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, 'A ki forgószélben rohan meg engem, és ok nélkül megsokasítja sebeimet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, 'Nem hagyna még lélekzetet se vennem, hanem keserűséggel lakatna jól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, 'Ha erőre kerülne a dolog? Ímé, ő igen erős; és ha ítéletre? Ki tűzne ki én nékem napot?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, 'Ha igaznak mondanám magamat, a szájam kárhoztatna engem; ha ártatlannak: bűnössé tenne engemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, 'Ártatlan vagyok, nem törődöm lelkemmel, útálom az életemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, 'Mindegy ez! Azért azt mondom: elveszít ő ártatlant és gonoszt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, 'Ha ostorával hirtelen megöl, neveti a bűntelenek megpróbáltatását.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, 'A föld a gonosz kezébe adatik, a ki az ő biráinak arczát elfedezi. Nem így van? Kicsoda hát ő?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, 'Napjaim gyorsabbak valának a kengyelfutónál: elfutának, nem láttak semmi jót.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, 'Ellebbentek, mint a gyorsan járó hajók, miként zsákmányára csap a keselyű.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, 'Ha azt mondom: Nosza elfelejtem panaszomat, felhagyok haragoskodásommal és vidám leszek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, 'Megborzadok az én mindenféle fájdalmamtól; tudom, hogy nem találsz bűntelennek engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, 'Rossz ember vagyok én! Minek fáraszszam hát magamat hiába?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, 'Ha hóvízzel mosakodom is meg, ha szappannal mosom is meg kezeimet:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, 'Akkor is a posványba mártanál engem és az én ruháim is útálnának engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, 'Mert nem ember ő, mint én, hogy néki megfelelhetnék, és együtt pörbe állanánk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, 'Nincs is közöttünk igazlátó, a ki kezét közbe vethesse kettőnk között!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, 'Venné csak el rólam az ő veszszejét, és az ő rettentésével ne rettegtetne engem:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, 'Akkor szólanék és nem félnék tőle: mert nem így vagyok én magammal!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, 'Lelkemből útálom az életemet, megeresztem felőle panaszomat; szólok az én lelkem keserűségében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'Azt mondom az Istennek: Ne kárhoztass engem; add tudtomra, miért perlesz velem?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'Jó-é az néked, hogy nyomorgatsz, hogy megútálod kezednek munkáját, és a gonoszok tanácsát támogatod?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, 'Testi szemeid vannak-é néked, és úgy látsz-é te, a mint halandó lát?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'Mint a halandónak napjai, olyanok-é a te napjaid, avagy a te éveid, mint az embernek napjai?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, 'Hogy az én álnokságomról tudakozol, és az én vétkem után kutatsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'Jól tudod te azt, hogy én nem vagyok gonosz, még sincs, a ki kezedből kiszabadítson!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, 'Kezeid formáltak engem és készítének engem egészen köröskörül, és mégis megrontasz engem?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, 'Emlékezzél, kérlek, hogy mint valami agyagedényt, úgy készítettél engem, és ismét porrá tennél engem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, 'Nem úgy öntél-é engem, mint a tejet és mint a sajtot, megoltottál engem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, 'Bőrrel és hússal ruháztál fel engem, csontokkal és inakkal befedeztél engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, 'Életet és kegyelmet szerzettél számomra, és a te gondviselésed őrizte az én lelkemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, 'De ezeket elrejtetted a te szívedben, és tudom, hogy ezt tökélted el magadban:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, 'Ha vétkezem, mindjárt észreveszed rajtam, és bűnöm alól nem mentesz föl engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, 'Ha istentelen vagyok, jaj nékem; ha igaz vagyok, sem emelem föl fejemet, eltelve gyalázattal, de tekints nyomorúságomra!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, 'Ha pedig felemelkednék az, mint oroszlán kergetnél engem, és ismét csudafájdalmakat bocsátanál reám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, 'Megújítanád a te bizonyságidat ellenem, megöregbítenéd a te boszúállásodat rajtam; váltakozó és állandó sereg volna ellenem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, 'Miért is hoztál ki engem anyámnak méhéből? Vajha meghaltam volna, és szem nem látott volna engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, 'Lettem volna, mintha nem is voltam volna; anyámnak méhéből sírba vittek volna!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, 'Hiszen kevés napom van még; szünjék meg! Forduljon el tőlem, hadd viduljak fel egy kevéssé,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 21, 'Mielőtt oda megyek, honnét nem térhetek vissza: a sötétségnek és a halál árnyékának földébe;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 22, 'Az éjféli homálynak földébe, a mely olyan, mint a halál árnyékának sürű setétsége; hol nincs rend, és a világosság olyan, mint a sürű setétség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, 'Felele a Naamából való Czófár, és monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, 'A sok beszédre ne legyen-é felelet? Avagy a csácsogó embernek legyen-é igaza?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, 'Fecsegéseid elnémítják az embereket, és csúfolódol is és ne legyen, a ki megszégyenítsen?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, 'Azt mondod: Értelmes az én beszédem, tiszta vagyok a te szemeid előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, 'De vajha szólalna meg maga az Isten, és nyitná meg ajkait te ellened!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, 'És jelentené meg néked a bölcsességnek titkait, hogy kétszerte többet ér az az okoskodásnál, és tudnád meg, hogy az Isten még el is engedett néked a te bűneidből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, 'Az Isten mélységét elérheted-é, avagy a Mindenhatónak tökéletességére eljuthatsz-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, 'Magasabb az égnél: mit teszel tehát? Mélyebb az alvilágnál; hogy ismerheted meg?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, 'Hosszabb annak mértéke a földnél, és szélesebb a tengernél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, 'Ha megtapos, elzár és ítéletet tart: ki akadályozhatja meg?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, 'Mert ő jól ismeri a csalárd embereket, látja az álnokságot, még ha nem figyelmez is arra!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, 'És értelmessé teheti a bolond embert is, és emberré szülheti a vadszamár csikóját is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, 'Ha te a te szívedet felkészítenéd, és kezedet felé terjesztenéd;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, 'Ha a hamisságot, a mely a te kezedben van, távol tartanád magadtól, és nem lakoznék a te hajlékodban gonoszság;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, 'Akkor a te arczodat fölemelhetnéd szégyen nélkül, erős lennél és nem félnél;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, 'Sőt a nyomorúságról is elfelejtkeznél, és mint lefutott vizekről, úgy emlékeznél arról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, 'Ragyogóbban kelne időd a déli fénynél, és az éjféli sötétség is olyan lenne, mint a kora reggel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, 'Akkor bíznál, mert volna reménységed; és ha széttekintenél, biztonságban aludnál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, 'Ha lefeküdnél, senki föl nem rettentene, sőt sokan hizelegnének néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, 'De a gonoszok szemei elepednek, menedékök eltünik előlök, és reménységök: a lélek kilehellése!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, 'Felele erre Jób, és monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, 'Bizonyára ti magatok vagytok a nép, és veletek kihal a bölcseség!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, 'Nékem is van annyi eszem, mint néktek, és nem vagyok alábbvaló nálatok, és ki ne tudna ilyenféléket?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, 'Kikaczagják a saját barátai azt, mint engem, a ki Istenhez kiált és meghallgatja őt. Kikaczagják az igazat, az ártatlant!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, 'A szerencsétlen megvetni való, gondolja, a ki boldog; ez vár azokra, a kiknek lábok roskadoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, 'A kóborlók sátrai csendesek és bátorságban vannak, a kik ingerlik az Istent, és a ki kezében hordja Istenét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, 'Egyébiránt kérdezd meg csak a barmokat, majd megtanítanak, és az égnek madarait, azok megmondják néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, 'Avagy beszélj a földdel és az megtanít téged, a tengernek halai is elbeszélik néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, 'Mindezek közül melyik nem tudja, hogy az Úrnak keze cselekszi ezt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, 'A kinek kezében van minden élő állatnak élete, és minden egyes embernek a lelke.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, 'Nemde nem a fül próbálja-é meg a szót, és az íny kóstolja meg az ételt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, 'A vén emberekben van-é a bölcseség, és az értelem a hosszú életben-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, 'Ő nála van a bölcseség és hatalom, övé a tanács és az értelem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, 'Ímé, a mit leront, nem épül föl az; ha valakire rázárja az ajtót, nem nyílik föl az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, 'Ímé, ha a vizeket elfogja, kiszáradnak; ha kibocsátja őket, felforgatják a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, 'Ő nála van az erő és okosság; övé az eltévelyedett és a ki tévelygésre visz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, 'A tanácsadókat fogságra viszi, és a birákat megbolondítja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, 'A királyok bilincseit feloldja, és övet köt derekukra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, 'A papokat fogságra viszi, és a hatalmasokat megbuktatja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, 'Az ékesen szólótól eltávolítja a beszédet és a vénektől elveszi a tanácsot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 21, 'Szégyent zúdít az előkelőkre, és a hatalmasok övét megtágítja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 22, 'Feltárja a sötétségből a mélységes titkokat, és a halálnak árnyékát is világosságra hozza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 23, 'Nemzeteket növel fel, azután elveszíti őket; nemzeteket terjeszt ki messzire, azután elűzi őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 24, 'Elveszi eszöket a föld népe vezetőinek, és úttalan pusztában bujdostatja őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 25, 'És világtalan setétben tapogatóznak, és tántorognak, mint a részeg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, 'Ímé, mindezeket látta az én szemem, hallotta az én fülem és megértette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, 'A mint ti tudjátok, úgy tudom én is, és nem vagyok alábbvaló nálatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, 'Azonban én a Mindenhatóval akarok szólani; Isten előtt kivánom védeni ügyemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, 'Mert ti hazugságnak mesterei vagytok, és mindnyájan haszontalan orvosok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, 'Vajha legalább mélyen hallgatnátok, az még bölcseségtekre lenne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, 'Halljátok meg, kérlek, az én feddőzésemet, és figyeljetek az én számnak pörlekedéseire.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, 'Az Isten kedvéért szóltok-é hamisságot, és ő érette szóltok-é csalárdságot?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, 'Az ő személyére néztek-é, ha Isten mellett tusakodtok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, 'Jó lesz-é az, ha egészen kiismer benneteket, avagy megcsalhatjátok-é őt, a mint megcsalható az ember?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, 'Keményen megbüntet, ha titkon vagytok is személyválogatók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, 'Az ő fensége nem rettent-é meg titeket, a tőle való félelem nem száll-é rátok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, 'A ti emlékezéseitek hamuba írott példabeszédek, a ti menedékváraitok sárvárak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, 'Hallgassatok, ne bántsatok: hadd szóljak én, akármi essék is rajtam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, 'Miért szaggatnám fogaimmal testemet, és miért szorítanám markomba lelkemet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, 'Ímé, megöl engem! Nem reménylem; hiszen csak utaimat akarom védeni előtte!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, 'Sőt az lesz nékem segítségül, hogy képmutató nem juthat elébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, 'Hallgassátok meg figyelmetesen az én beszédemet, vegyétek füleitekbe az én mondásomat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, 'Ímé, előterjesztem ügyemet, tudom, hogy nékem lesz igazam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, 'Ki az, a ki perelhetne velem? Ha most hallgatnom kellene, úgy kimulnék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, 'Csak kettőt ne cselekedj velem, szined elől akkor nem rejtőzöm el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 21, 'Vedd le rólam kezedet, és a te rettentésed ne rettentsen engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 22, 'Azután szólíts és én felelek, avagy én szólok hozzád és te válaszolj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 23, 'Mennyi bűnöm és vétkem van nékem? Gonoszságomat és vétkemet add tudtomra!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 24, 'Mért rejted el arczodat, és tartasz engemet ellenségedül?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 25, 'A letépett falevelet rettegteted-é, és a száraz pozdorját üldözöd-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 26, 'Hogy ily sok keserűséget szabtál reám, és az én ifjúságomnak vétkét örökölteted velem?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 27, 'Hogy békóba teszed lábaimat, vigyázol minden én utamra, és vizsgálod lábomnak nyomait?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 28, 'Az pedig elsenyved, mint a redves fa, mint ruha, a melyet moly emészt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, 'Az asszonytól született ember rövid életű és háborúságokkal bővelkedő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, 'Mint a virág, kinyílik és elhervad, és eltünik, mint az árnyék és nem állandó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, 'Még az ilyen ellen is felnyitod-é szemeidet, tennen magaddal törvénybe állítasz-é engem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, 'Ki adhat tisztát a tisztátalanból? Senki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, 'Nincsenek-é meghatározva napjai? Az ő hónapjainak számát te tudod; határt vetettél néki, a melyet nem hághat át.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, 'Fordulj el azért tőle, hogy nyugodalma legyen, hogy legyen napjában annyi öröme, mint egy béresnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, 'Mert a fának van reménysége; ha levágják, ismét kihajt, és az ő hajtásai el nem fogynak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, 'Még ha megaggodik is a földben a gyökere, és ha elhal is a porban törzsöke:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, 'A víznek illatától kifakad, ágakat hajt, mint a csemete.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, 'De ha a férfi meghal és elterül; ha az ember kimúlik, hol van ő?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, 'Mint a víz kiapad a tóból, a patak elapad, kiszárad:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, 'Úgy fekszik le az ember és nem kél fel; az egek elmúlásáig sem ébrednek, nem költetnek föl az ő álmukból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, 'Vajha engem a holtak országában tartanál; rejtegetnél engemet addig, a míg elmúlik a te haragod; határt vetnél nékem, azután megemlékeznél rólam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, 'Ha meghal az ember, vajjon feltámad-é? Akkor az én hadakozásom minden idejében reménylenék, míglen elkövetkeznék az én elváltozásom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, 'Szólítanál és én felelnék néked, kivánkoznál a te kezednek alkotása után.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, 'De most számlálgatod az én lépéseimet, és nem nézed el az én vétkeimet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, 'Gonoszságom egy csomóba van lepecsételve, és hozzáadod bűneimhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, 'Még a hegy is szétomlik, ha eldől; a szikla is elmozdul helyéről;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 19, 'A köveket lekoptatja a víz, a földet elsodorja annak árja: az ember reménységét is úgy teszed semmivé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 20, 'Hatalmaskodol rajta szüntelen és ő elmegy; megváltoztatván az arczát, úgy bocsátod el őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 21, 'Ha tisztesség éri is fiait, nem tudja; ha megszégyenülnek, nem törődik velök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 22, 'Csak őmagáért fáj még a teste, és a lelke is őmagáért kesereg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, 'Majd felele a Témánból való Elifáz és monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, 'Vajjon a bölcs felelhet-é ilyen szeles tudománynyal, és megtöltheti-é a hasát keleti széllel?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, 'Vetekedvén oly beszéddel, a mely nem használ, és oly szavakkal, a melyekkel semmit sem segít.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, 'Te már semmivé akarod tenni az Isten félelmét is; és megkevesbíted az Isten előtt való buzgólkodást is!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, 'Mert gonoszságod oktatja a te szádat, és a csalárdok nyelvét választottad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, 'A te szád kárhoztat téged, nem én, és a te ajakaid bizonyítanak ellened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, 'Te születtél-é az első embernek; elébb formáltattál-é, mint a halmok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, 'Az Isten tanácsában hallgatóztál-é, és a bölcseséget magadhoz ragadtad-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, 'Mit tudsz te, a mit mi nem tudunk, és mit értesz olyat, a mi nálunk nem volna meg?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, 'Ősz is, agg is van közöttünk, jóval idősebb a te atyádnál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, 'Csekélységek-é előtted Istennek vigasztalásai, és a beszéd, a mely szeliden bánt veled?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, 'Merre ragadt téged a szíved, és merre pillantottak a te szemeid?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, 'Hogy Isten ellen fordítod a te haragodat, és ilyen szavakat eresztesz ki a szádon?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, 'Micsoda a halandó, hogy tiszta lehetne, és hogy igaz volna, a ki asszonytól születik?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 15, 'Ímé, még az ő szenteiben sem bízok, az egek sem tiszták az ő szemében:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 16, 'Mennyivel kevésbbé az útálatos és a megromlott ember, a ki úgy nyeli a hamisságot, mint a vizet?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 17, 'Elmondom néked, hallgass rám, és a mint láttam, úgy beszélem el;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 18, 'A mit a bölcsek is hirdettek, és nem titkoltak el, mint atyáiktól valót;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 19, 'A kiknek egyedül adatott vala a föld, és közöttük idegen nem megy vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 20, 'Az istentelen kínozza önmagát egész életében, és az erőszakoskodó előtt is rejtve van az ő esztendeinek száma.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 21, 'A félelem hangja cseng az ő füleiben; a békesség idején tör rá a pusztító!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 22, 'Nem hiszi, hogy kijut a sötétségből, mert kard hegyére van ő kiszemelve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 23, 'Kenyér után futkos, hogy hol volna? Tudja, hogy közel van hozzá a sötétség napja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 24, 'Háborgatják őt a nyomorúság és rettegés; leverik őt, mint valami háborúra felkészült király.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 25, 'Mert az Isten ellen nyujtotta ki kezét, és erősködött a Mindenható ellen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 26, 'Kinyujtott nyakkal rohant ellene, domború pajzsainak fellege alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 27, 'Mivel befedezte az arczát kövérséggel, és hájat borított tomporára;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 28, 'És lakozott elrombolt városokban; lakatlan házakban, a melyek dűlőfélben vannak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 29, 'Meg nem gazdagodik, vagyona meg nem marad, jószága nem lepi el a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 30, 'Nem menekül meg a setétségtől, sarjadékát láng perzseli el, és szájának lehelletétől pusztul el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 31, 'Ne higyjen a hívságnak, a ki megcsalatott, mert hívság lészen annak jutalma.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 32, 'Nem idejében telik el élete, és az ága ki nem virágzik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 33, 'Lehullatja, mint a szőlővessző az ő egresét, elhányja, mint az olajfa az ő virágát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 34, 'Mert a képmutató házanépe meddő, és tűz emészti meg az ajándékból való sátrakat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 35, 'Nyomorúságot fogan, álnokságot szül, és az ő méhök csalárdságot érlel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, 'Felele pedig Jób, és monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, 'Efféle dolgokat sokat hallottam. Nyomorult vigasztalók vagytok ti mindnyájan!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, 'Vége lesz-é már a szeles beszédeknek, avagy mi ingerel téged, hogy így felelsz?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, 'Én is szólhatnék úgy mint ti, csak volna a ti lelketek az én lelkem helyén! Szavakat fonhatnék össze ellenetek; csóválhatnám miattatok a fejemet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, 'Erősíthetnélek titeket csak a szájammal és ajakim mozgása kevesbítené fájdalmatokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, 'Ha szólnék is, nem kevesbbednék a keserűségem; ha veszteglek is: micsoda távozik el tőlem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, 'Most pedig már fáraszt engemet. Elpusztítád egész házam népét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, 'Hogy összenyomtál engem, ez bizonyság lett; felkelt ellenem az én ösztövérségem is, szemtől-szembe bizonyít ellenem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, 'Haragja széttépett és üldöz engem. Fogait csikorgatta rám, ellenségemként villogtatja felém tekintetét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, 'Feltátották ellenem szájokat, gyalázatosan arczul csapdostak engem, összecsődültek ellenem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, 'Adott engem az Isten az álnoknak, és a gonoszok kezébe ejte engemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, 'Csendességben valék, de szétszaggata engem; nyakszirten ragadott és szétzúzott engem, czéltáblává tűzött ki magának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, 'Körülvettek az ő íjászai; veséimet meghasítja és nem kimél; epémet a földre kiontja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, 'Rést rés után tör rajtam, és rám rohan, mint valami hős.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, 'Zsák-ruhát varrék az én fekélyes bőrömre, és a porba fúrtam be az én szarvamat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, 'Orczám a sírástól kivörösödött, szempilláimra a halál árnyéka szállt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, 'Noha erőszakosság nem tapad kezemhez, és az én imádságom tiszta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, 'Oh föld, az én véremet el ne takard, és ne legyen hely az én kiáltásom számára!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, 'Még most is ímé az égben van az én bizonyságom, és az én tanuim a magasságban!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, 'Csúfolóim a saját barátaim, azért az Istenhez sír fel az én szemem,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, 'Hogy ítélje meg az embernek Istennel, és az ember fiának az ő felebarátjával való dolgát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, 'Mert a kiszabott esztendők letelnek, és én útra kelek és nem térek vissza. Lelkem meghanyatlott, napjaim elfogynak, vár rám a sír.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 1, 'Még mindig csúfot űznek belőlem! Szemem az ő patvarkodásuk között virraszt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 2, 'Kezest magadnál rendelj, kérlek, nékem; különben ki csap velem kezet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 3, 'Minthogy az ő szívöket elzártad az értelem elől, azért nem is magasztalhatod fel őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 4, 'A ki prédává juttatja barátait, annak fiainak szemei elfogyatkoznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 5, 'Példabeszéddé tőn engem a népek előtt, és ijesztővé lettem előttök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 6, 'A bosszúság miatt szemem elhomályosodik, és minden tagom olyan, mint az árnyék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 7, 'Elálmélkodnak ezen a becsületesek, és az ártatlan a képmutató ellen támad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 8, 'Ám az igaz kitart az ő útján, és a tiszta kezű ember még erősebbé lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 9, 'Nosza hát, térjetek ide mindnyájan; jőjjetek, kérlek, úgy sem találok bölcset köztetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 10, 'Napjaim elmulának, szívemnek kincsei: terveim meghiusulának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 11, 'Az éjszakát nappallá változtatják, és a világosság csakhamar sötétséggé lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 12, 'Ha reménykedem is, a sír már az én házam, a sötétségben vetettem az én ágyamat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 13, 'A sírnak mondom: Te vagy az én atyám; a férgeknek pedig: Ti vagytok az én anyám és néném.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 14, 'Hol tehát az én reménységem, ki törődik az én reménységemmel?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 15, 'Leszáll az majd a sír üregébe, velem együtt nyugoszik a porban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 16, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 1, 'Felele pedig a sukhi Bildád, és monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 2, 'Mikor akartok a beszédnek véget vetni? Értsétek meg a dolgot, azután szóljunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 3, 'Miért állíttatunk barmoknak, és miért vagyunk tisztátalanok a ti szemeitekben?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 4, 'Te éretted, a ki szaggatja lelkét haragjában, vajjon elhagyattatik-é a föld, és felszakasztatik-é a kőszikla helyéről?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 5, 'Sőt inkább a gonoszok világa kialuszik, és nem fénylik az ő tüzöknek szikrája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 6, 'A világosság elsötétedik az ő sátorában, szövétneke kialszik felette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 7, 'Erős léptei aprókká lesznek, saját tanácsa rontja meg őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 8, 'Mert lábaival hálóba bonyolódik, és ó-verem felett jár.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 9, 'A sarka tőrbe akad, és kelepcze fogja meg őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 10, 'Hurok rejtetett el a földbe ellene, és zsineg az ő szokott ösvényén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 11, 'Mindenfelől félelmek rettentik őt, és üldözik őt léptennyomon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 12, 'Éhség emészti fel az ő erejét, és nyomorúság leselkedik oldala mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 13, 'Megemészti testének izmait, megemészti izmait a halál zsengéje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 14, 'Eltünik sátorából az ő bátorsága, és a félelmek királyához folyamodik ő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 15, 'Az lakik sátorában, a ki nem az övé, és hajlékára kénkövet szórnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 16, 'Alant elszáradnak gyökerei, és felülről levágatik az ága.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 17, 'Emlékezete elvész a földről, még az utczákon sem marad fel a neve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 18, 'A világosságról a sötétségbe taszítják, a föld kerekségéről elüldözik őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 19, 'Sem fia, sem unokája nem lesz az ő népében, és semmi maradéka az ő tanyáján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 20, 'Az ő pusztulásától megborzadnak, a kik következnek és rettegés fogja el a most élő embereket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 21, 'Ilyenek az álnok embernek hajlékai, és ilyen annak lakóhelye, a ki nem tiszteli Istent.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 1, 'Felele pedig Jób, és monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 2, 'Meddig búsítjátok még a lelkemet, és kínoztok engem beszéddel?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 3, 'Tízszer is meggyaláztatok már engem; nem pirultok, hogy így erősködtök ellenem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 4, 'Még ha csakugyan tévedtem is, tévedésem énmagamra hárul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 5, 'Avagy csakugyan pöffeszkedni akartok ellenem, és feddődni az én gyalázatom felett?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 6, 'Tudjátok meg hát, hogy Isten alázott meg engem, és az ő hálójával ő vett engem körül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 7, 'Ímé, kiáltozom az erőszak miatt, de meg nem hallgattatom, segélyért kiáltok, de nincsen igazság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 8, 'Utamat úgy elgátolta, hogy nem mehetek át rajta, és az én ösvényemre sötétséget vetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 9, 'Tisztességemből kivetkőztetett, és fejemnek koronáját elvevé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 10, 'Megronta köröskörül, hogy elveszszek, és reménységemet, mint a fát, letördelé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 11, 'Felgerjesztette haragját ellenem, és úgy bánt velem, mint ellenségeivel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 12, 'Seregei együtt jövének be és utat csinálnak ellenem, és az én sátorom mellett táboroznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 13, 'Atyámfiait távol űzé mellőlem, barátaim egészen elidegenedtek tőlem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 14, 'Rokonaim visszahúzódtak, ismerőseim pedig elfelejtkeznek rólam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 15, 'Házam zsellérei és szolgálóim idegennek tartanak engem, jövevény lettem előttök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 16, 'Ha a szolgámat kiáltom, nem felel, még ha könyörgök is néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 17, 'Lehelletem idegenné lett házastársam előtt, s könyörgésem az én ágyékom magzatai előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 18, 'Még a kisdedek is megvetnek engem, ha fölkelek, ellenem szólnak nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 19, 'Megútált minden meghitt emberem; a kiket szerettem, azok is ellenem fordultak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 20, 'Bőrömhöz és húsomhoz ragadt az én csontom, csak fogam húsával menekültem meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 21, 'Könyörüljetek rajtam, könyörüljetek rajtam, oh ti barátaim, mert az Isten keze érintett engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 22, 'Miért üldöztök engem úgy, mint az Isten, és mért nem elégesztek meg a testemmel?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 23, 'Oh, vajha az én beszédeim leirattatnának, oh, vajha könyvbe feljegyeztetnének!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 24, 'Vasvesszővel és ónnal örökre kősziklába metszetnének!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 25, 'Mert én tudom, hogy az én megváltóm él, és utoljára az én porom felett megáll.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 26, 'És miután ezt a bőrömet megrágják, testem nélkül látom meg az Istent.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 27, 'A kit magam látok meg magamnak; az én szemeim látják meg, nem más. Az én veséim megemésztettek én bennem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 28, 'Mert ezt mondjátok: Hogyan fogjuk őt üldözni! látva, hogy a dolog gyökere én bennem rejlik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 29, 'Féljetek a fegyvertől, mert a fegyver a bűnök miatt való büntetés, hogy megtudjátok, hogy van ítélet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 1, 'Felele pedig a Naamából való Czófár, és monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 2, 'Mindamellett az én gondolataim feleletre kényszerítenek engem, és e miatt nagy az izgatottság bennem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 3, 'Hallom gyalázatos dorgáltatásomat, de az én értelmes lelkem megfelel majd értem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 4, 'Tudod-é azt, hogy eleitől fogva, mióta az embert e földre helyheztette,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 5, 'Az istentelenek vígassága rövid ideig tartó, és a képmutató öröme egy szempillantásig való?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 6, 'Ha szinte az égig érne is az ő magassága, és a felleget érné is a fejével:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 7, 'Mint az emésztete, úgy vész el örökre, és a kik látták, azt mondják: Hol van ő?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 8, 'Mint az álom, úgy elrepül és nem találják őt; eltünik, mint az éjjeli látomás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 9, 'A szem, a mely rá ragyogott, nem látja többé, és az ő helye sem törődik már vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 10, 'Fiai a szegények kedvében járnak, és kezei visszaadják az ő rablott vagyonát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 11, 'Csontjai, ha megtelnek is ifjú erővel, de vele együtt roskad az a porba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 12, 'Ha édes az ő szájában a gonoszság, és elrejti azt az ő nyelve alá;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 13, 'És kedvez annak és ki nem veti azt, hanem ott tartogatja ínyei között:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 14, 'Az ő étke elváltozik az ő gyomrában, vipera mérgévé lesz a belében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 15, 'Gazdagságot nyelt el, de kihányja azt, az ő hasából kiűzi azt az Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 16, 'A viperának mérgét szopta és a siklónak fulánkja öli meg őt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 17, 'Hogy ne lássa a folyóvizeket, a tejjel és mézzel folyó patakokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 18, 'A mit másoktól szerzett, vissza kell adnia, nem nyelheti el, ép így az ő cserébe kapott vagyonát is, hogy ne örvendezhessen annak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 19, 'Mert megrontotta és ott hagyta a szegényeket, házat rabolt, de nem építi meg azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 20, 'Mivel gyomra nem tudott betelni, nem is mentheti meg semmi drágaságát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 21, 'Az ő falánksága elől semmi sem maradt meg, azért nem lesz tartós az ő jóléte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 22, 'Mikor teljes az ő bősége, akkor is szükséget lát, és mindenféle nyomorúság támad reá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 23, 'Mikor meg akarja tölteni a hasát, reá bocsátja haragjának tüzét, és azt önti rá étele gyanánt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 24, 'Mikor vasból csinált fegyver elől fut, aczélból csinált íj veri át.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 25, 'Kihúzza és az kijön a testéből és kivillan az epéjéből; rettegés támad felette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 26, 'Mindenféle titkos sötétség van az ő vagyonán; fúvás nélkül való tűz emészti meg őt; elpusztíttatik az is, a mi sátrában megmaradt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 27, 'Megjelentik álnokságát az egek, és a föld ellene támad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 28, 'Házának jövedelme eltünik, szétfoly az az ő haragjának napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 29, 'Ez a gonosz ember fizetése Istentől, és az ő beszédének jutalma a Mindenhatótól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 1, 'Felele pedig Jób, és monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 2, 'Jól hallgassátok meg az én beszédemet, és legyen ez a ti vigasztalástok helyett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 3, 'Szenvedjetek el engem, a míg szólok, azután gúnyoljátok ki beszédemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 4, 'Avagy én embernek panaszolkodom-é? Miért ne volna hát keserű a lelkem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 5, 'Tekintsetek reám és álmélkodjatok el, és tegyétek kezeteket szátokra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 6, 'Ha visszaemlékezem, mindjárt felháborodom, és reszketés fogja el testemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 7, 'Mi az oka, hogy a gonoszok élnek, vénséget érnek, sőt még meg is gyarapodnak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 8, 'Az ő magvok előttök nő fel ő velök, és az ő sarjadékuk szemeik előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 9, 'Házok békességes a félelemtől, és az Isten vesszeje nincsen ő rajtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 10, 'Bikája folyat és nem terméketlen, tehene megellik és el nem vetél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 11, 'Kieresztik, mint nyájat, kisdedeiket, és ugrándoznak az ő magzataik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 12, 'Dobot és hárfát ragadnak, és örvendeznek a síp zengésének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 13, 'Jóllétben töltik el napjaikat, és egy pillanat alatt szállnak alá a sírba;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 14, 'Noha azt mondják Istennek: Távozzál el tőlünk, mert a te utaidnak tudásában nem gyönyörködünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 15, 'Micsoda a Mindenható, hogy tiszteljük őt, és mit nyerünk vele, ha esedezünk előtte?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 16, 'Mindazáltal az ő javok nincsen hatalmukban, azért a gonoszok tanácsa távol legyen tőlem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 17, 'Hányszor aluszik el a gonoszok szövétneke, és jő rájok az ő veszedelmök! Hányszor osztogatja részöket haragjában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 18, 'Olyanok lesznek, mint a pozdorja a szél előtt, és mint a polyva, a melyet forgószél ragad el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 19, 'Isten az ő fiai számára tartja fenn annak büntetését. Megfizet néki, hogy megérzi majd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 20, 'Maga látja meg a maga veszedelmét, és a Mindenható haragjából iszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 21, 'Mert mi gondja van néki házanépére halála után, ha az ő hónapjainak száma letelt?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 22, 'Ki taníthatja Istent bölcseségre, hisz ő ítéli meg a magasságban levőket is!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 23, 'Ez meghal az ő teljes boldogságában, egészen megelégedetten és nyugodtan;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 24, 'Fejőedényei tejjel vannak tele, csontjainak velője nedvességtől árad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 25, 'Amaz elkeseredett lélekkel hal meg, mert nem élhetett a jóval.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 26, 'Együtt feküsznek a porban, és féreg lepi őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 27, 'Ímé, jól tudom a ti gondolatitokat és a hamisságokat, a melyekkel méltatlankodtok ellenem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 28, 'Mert ezt mondjátok: Hol van ama főembernek háza, hol van a gonoszok lakozásának sátora?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 29, 'Avagy nem kérdeztétek-é meg azokat, a kik sokat utaznak és jeleiket nem ismeritek-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 30, 'Bizony a veszedelemnek napján elrejtetik a gonosz, a haragnak napján kiszabadul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 31, 'Kicsoda veti szemére az ő útját, és a mit cselekedett, kicsoda fizet meg néki azért?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 32, 'Még ha a sírba vitetik is ki, a sírdomb felett is él.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 33, 'Édesek lesznek néki a sírnak hantjai, és maga után vonsz minden embert, a mint számtalanok mentek el előtte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 34, 'Hogyan vigasztalnátok hát engem hiábavalósággal? Feleselésetek igazságtalanság marad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 1, 'Felele pedig a Témánból való Elifáz, és monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 2, 'Az Istennek használ-é az ember? Sőt önmagának használ az okos!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 3, 'Gyönyörűségére van-é az a Mindenhatónak, ha te igaz vagy; avagy nyereség-é, hogy feddhetetlenül jársz?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 4, 'A te isteni félelmedért fedd-é téged, és azért perel-é veled?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 5, 'Avagy nem sok-é a te gonoszságod, és nem véghetetlen-é a te hamisságod?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 6, 'Hiszen zálogot vettél a te atyádfiától méltatlanul, és a szegényeket mezítelenekké tetted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 7, 'Az eltikkadtnak vizet sem adtál inni, és az éhezőtől megtagadtad a kenyeret.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 8, 'A ki hatalmas volt, azé vala az ország, és a ki nagytekintélyű volt, az lakik vala rajta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 9, 'Az özvegyeket üres kézzel bocsátottad el, és az árváknak karjai eltörettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 10, 'Azért vett körül téged a veszedelem, és rettegtet téged hirtelen való rettegés;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 11, 'Avagy a setétség, hogy ne láthass, és a vizek árja, a mely elborít!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 12, 'Hát nem olyan magas-é Isten, mint az egek? És lásd, a csillagok is ott fent mily igen magasak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 13, 'És mégis azt mondod: Mit tud az Isten; megítélheti-é, a mi a homály mögött van?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 14, 'Sűrű felhők leplezik el őt és nem lát, és az ég körületén jár.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 15, 'Az ősvilág ösvényét követed-é, a melyen az álnok emberek jártak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 16, 'A kik időnap előtt ragadtattak el, és alapjokat elmosta a víz?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 17, 'A kik azt mondják vala Istennek: Távozzál el tőlünk! És mit cselekedék velök a Mindenható?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 18, 'Ő pedig megtöltötte házaikat jóval. De az istentelenek tanácsa távol legyen tőlem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 19, 'Látják ezt az igazak és örülnek rajta, az ártatlan pedig csúfolja őket:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 20, 'Valósággal kigyomláltatott a mi ellenségünk, és az ő maradékjokat tűz emészti meg!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 21, 'Bízd csak azért magadat ő reá és légy békességben: ezekből jó származik reád.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 22, 'Végy csak oktatást az ő szájából, és vésd szívedbe az ő beszédeit!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 23, 'Ha megtérsz a Mindenhatóhoz, megépíttetel, és az álnokságot távol űzöd a te sátorodtól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 24, 'Vesd a porba a nemes érczet, és a patakok kavicsába az ofiri aranyat:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 25, 'És akkor a Mindenható lesz a te nemes érczed és a te ragyogó ezüstöd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 26, 'Bizony akkor a Mindenhatóban gyönyörködöl, és a te arczodat Istenhez emeled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 27, 'Hozzá könyörögsz és meghallgat téged, és lefizeted fogadásaidat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 28, 'Mihelyt valamit elgondolsz, sikerül az néked, és a te utaidon világosság fénylik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 29, 'Hogyha megaláznak, felmagasztalásnak mondod azt, és ő az alázatost megtartja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 30, 'Megszabadítja a nem ártatlant is, és pedig a te kezeidnek tisztaságáért szabadul meg az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 1, 'Felele pedig Jób, és monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 2, 'Még most is keserű az én beszédem; súlyosabb rajtam a csapás, ha panaszkodom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 3, 'Oh ha tudnám, hogy megtalálom őt, elmennék szinte az ő székéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 4, 'Elébe terjeszteném ügyemet, számat megtölteném mentő erősségekkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 5, 'Hadd tudnám meg, mely szavakkal felelne nékem; hadd érteném meg, mit szólana hozzám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 6, 'Vajjon erejének nagy volta szerint perelne-é velem? Nem; csak figyelmezne reám!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 7, 'Ott egy igaz perelne ő vele; azért megszabadulhatnék birámtól örökre!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 8, 'Ámde kelet felé megyek és nincsen ő, nyugot felé és nem veszem őt észre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 9, 'Bal kéz felől cselekszik, de meg nem foghatom; jobb kéz felől rejtőzködik és nem láthatom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 10, 'De ő jól tudja az én utamat. Ha megvizsgálna engem, úgy kerülnék ki, mint az arany.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 11, 'Lábam az ő nyomdokát követte; utát megőriztem és nem hajoltam el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 12, 'Az ő ajakinak parancsolatától sem tértem el; szájának beszédeit többre becsültem, mint életem táplálékát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 13, 'Ő azonban megmarad egy mellett. Kicsoda téríthetné el őt? És a mit megkiván lelke, azt meg is teszi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 14, 'Bizony végbe viszi, a mi felőlem elrendeltetett, és ilyen még sok van ő nála.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 15, 'Azért rettegek az ő színe előtt, és ha csak rá gondolok is, félek tőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 16, 'Mert Isten félemlítette meg az én szívemet, a Mindenható rettentett meg engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 17, 'Miért is nem pusztultam el e sötétség előtt, vagy miért nem takarta el előlem e homályt?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 1, 'Miért is nem titkolja el a Mindenható az ő büntetésének idejét, és miért is nem látják meg az őt ismerők az ő ítéletének napjait?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 2, 'A határokat odább tolják, a nyájat elrabolják és legeltetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 3, 'Az árvák szamarát elhajtják, és az özvegynek ökrét zálogba viszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 4, 'Lelökik az útról a szegényeket, és a föld nyomorultjai együtt lappanganak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 5, 'Ímé, mint a vad szamarak a sivatagban, úgy mennek ki munkájukra élelmet keresni; a puszta ad nékik kenyeret fiaik számára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 6, 'A mezőn a más vetését aratják, és a gonosznak szőlőjét szedik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 7, 'Mezítelenül hálnak, testi ruha nélkül, még a hidegben sincs takarójuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 8, 'A hegyi zápor csurog le rólok, s hajlékuk nem lévén, a sziklát ölelik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 9, 'Elszakítják az emlőtől az árvát, és a szegényen levőt zálogba viszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 10, 'Mezítelenül járnak, ruha nélkül, és éhesen vonszolják a kévét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 11, 'Az ő kerítéseik közt ütik az olajat, és tapossák a kádakat, de szomjuhoznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 12, 'A városból haldoklók rimánkodnak, a megsebzettek lelke kiált, de Isten nem törődik e méltatlansággal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 13, 'Ezek pártot ütöttek a világosság ellen, utait nem is ismerik, nem ülnek annak ösvényein.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 14, 'Napkeltekor fölkel a gyilkos, megöli a szegényt és szűkölködőt, éjjel pedig olyan, mint a tolvaj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 15, 'A paráznának szeme pedig az alkonyatot lesi, mondván: Ne nézzen szem reám, és arczára álarczot teszen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 16, 'Setétben tör be a házakba; nappal elzárkóznak, nem szeretik a világosságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 17, 'Sőt inkább a reggel nékik olyan, mint a halálnak árnyéka, mert megbarátkoztak a halál árnyékának félelmeivel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 18, 'Könnyen siklik tova a víz színén, birtoka átkozott a földön, nem tér a szőlőkbe vivő útra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 19, 'Szárazság és hőség nyeli el a hó vizét, a pokol azokat, a kik vétkeznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 20, 'Elfelejti őt az anyaméh, féregnek lesz édességévé, nem emlékeznek róla többé, és összetörik, mint a reves fa,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 21, 'A ki megrontotta a meddőt, a ki nem szül, és az özvegygyel jót nem tett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 22, 'De megtámogatja erejével a hatalmasokat; felkel az, pedig nem bízott már az élethez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 23, 'Biztonságot ad néki, hogy támaszkodjék, de szemei vigyáznak azoknak útjaira.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 24, 'Magasra emelkednek, egy kevés idő és már nincsenek! Alásülylyednek, mint akárki és elenyésznek; és levágattatnak, mint a búzakalász.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 25, 'Avagy nem így van-é? Ki hazudtolhatna meg engem, és tehetné semmivé beszédemet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 1, 'Felele pedig a Sukhból való Bildád, és monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 2, 'Hatalom és fenség az övé, a ki békességet szerez az ő magasságaiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 3, 'Van-é száma az ő sereginek, és kire nem kél fel az ő világossága?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 4, 'Hogy-hogy lehetne igaz a halandó Isten előtt, hogyan lehetne tiszta, a ki asszonytól született?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 5, 'Nézd a holdat, az sem ragyogó, még a csillagok sem tiszták az ő szemei előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 6, 'Mennyivel kevésbé a halandó, a ki féreg, és az embernek fia, a ki hernyó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 1, 'Jób pedig felele, és monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 2, 'Bezzeg jól segítettél a tehetetlenen, meggyámolítottad az erőtelen kart!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 3, 'Bezzeg jó tanácsot adtál a tudatlannak, és sok értelmet tanusítottál!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 4, 'Kivel beszélgettél, és kinek a lelke jött ki belőled?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 5, 'A halottak is megremegnek tőle; a vizek alatt levők és azok lakói is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 6, 'Az alvilág mezítelen előtte, és eltakaratlan a holtak országa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 7, 'Ő terjeszti ki északot az üresség fölé és függeszti föl a földet a semmiség fölé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 8, 'Ő köti össze felhőibe a vizeket úgy, hogy a felhő alattok meg nem hasad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 9, 'Ő rejti el királyi székének színét, felhőjét fölibe terítvén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 10, 'Ő szab határt a víz színe fölé – a világosságnak és setétségnek elvégződéséig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 11, 'Az egek oszlopai megrendülnek, és düledeznek fenyegetéseitől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 12, 'Erejével felriasztja a tengert, és bölcseségével megtöri Ráhábot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 13, 'Lehelletével megékesíti az eget, keze átdöfi a futó kígyót.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 14, 'Ímé, ezek az ő útainak részei, de mily kicsiny rész az, a mit meghallunk abból! Ám az ő hatalmának mennydörgését ki érthetné meg?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 1, 'Jób pedig folytatá az ő beszédét, monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 2, 'Él az Isten, a ki az én igazamat elfordította, és a Mindenható, a ki keserűséggel illette az én lelkemet,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 3, 'Hogy mindaddig, a míg az én lelkem én bennem van, és az Istennek lehellete van az én orromban;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 4, 'Az én ajakim nem szólnak álnokságot, és az én nyelvem nem mond csalárdságot!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 5, 'Távol legyen tőlem, hogy igazat adjak néktek! A míg lelkemet ki nem lehelem, ártatlanságomból magamat ki nem tagadom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 6, 'Igazságomhoz ragaszkodom, róla le nem mondok; napjaim miatt nem korhol az én szívem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 7, 'Ellenségem lesz olyan, mint a gonosz, és a ki ellenem támad, mint az álnok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 8, 'Mert micsoda reménysége lehet a képmutatónak, hogy telhetetlenkedett, ha az Isten mégis elragadja az ő lelkét?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 9, 'Meghallja-é kiáltását az Isten, ha eljő a nyomorúság reá?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 10, 'Vajjon gyönyörködhetik-é a Mindenhatóban; segítségül hívhatja-é mindenkor az Istent?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 11, 'Megtanítlak benneteket Isten dolgaira; a mik a Mindenhatónál vannak, nem titkolom el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 12, 'Ímé, ti is mindnyájan látjátok: miért van hát, hogy hiábavalósággal hivalkodtok?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 13, 'Ez a gonosz embernek osztályrésze Istentől, és a kegyetlenek öröksége a Mindenhatótól, a melyet elvesznek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 14, 'Ha megsokasulnak is az ő fiai, a kardnak sokasulnak meg, és az ő magzatai nem lakhatnak jól kenyérrel sem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 15, 'Az ő maradékai dögvész miatt temettetnek el, és az ő özvegyeik meg sem siratják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 16, 'Ha mint a port, úgy halmozná is össze az ezüstöt, és úgy szerezné is össze ruháit, mint a sarat:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 17, 'Összeszerezheti ugyan, de az igaz ruházza magára, az ezüstön pedig az ártatlan osztozik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 18, 'Házát pók módjára építette föl, és olyanná, mint a csősz-csinálta kunyhó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 19, 'Gazdagon fekszik le, mert nincsen kifosztva; felnyitja szemeit és semmije sincsen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 20, 'Meglepi őt, mint az árvíz, a félelem, éjjel ragadja el a zivatar.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 21, 'Felkapja őt a keleti szél és elviszi, elragadja őt helyéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 22, 'Nyilakat szór reá és nem kiméli; futva kell futnia keze elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 23, 'Csapkodják felette kezeiket, és kisüvöltik őt az ő lakhelyéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 1, 'Bizony az ezüstnek bányája van, és helye az aranynak, a hol tisztítják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 2, 'A vasat a földből hozzák elő, a követ pedig érczczé olvasztják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 3, 'Határt vet az ember a setétségnek, és átkutatja egészen és végig a homálynak és a halál árnyékának kövét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 4, 'Aknát tör távol a lakóktól: mintha lábukról is megfelejtkeznének, alámerülnek és lebegnek emberektől messze.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 5, 'Van föld, a melyből kenyér terem, alant pedig fel van forgatva, mintegy tűz által;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 6, 'Köveiben zafir található, göröngyeiben arany van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 7, 'Van ösvény, a melyet nem ismer a sas, sem a sólyom szeme nem látja azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 8, 'Nem tudják azt büszke vadak, az oroszlán sem lépked azon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 9, 'Ráveti kezét az ember a kovakőre, a hegyeket tövükből kiforgatja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 10, 'A sziklákban tárnákat hasít, és minden drága dolgot meglát a szeme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 11, 'Elköti a folyók szivárgását, az elrejtett dolgot pedig világosságra hozza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 12, 'De a bölcseség hol található, és az értelemnek hol van a helye?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 13, 'Halandó a hozzá vivő utat nem ismeri, az élők földén az nem található.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 14, 'A mélység azt mondja: Nincsen az bennem; a tenger azt mondja: én nálam sincsen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 15, 'Színaranyért meg nem szerezhető, ára ezüsttel meg nem fizethető.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 16, 'Nem mérhető össze Ofir aranyával, nem drága onikszszal, sem zafirral.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 17, 'Nem ér fel vele az arany és gyémánt, aranyedényekért be nem cserélhető.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 18, 'Korall és kristály említni sem való; a bölcseség ára drágább a gyöngyöknél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 19, 'Nem ér fel vele Kúsnak topáza, színaranynyal sem mérhető össze.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 20, 'A bölcseség honnan jő tehát, és hol van helye az értelemnek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 21, 'Rejtve van az minden élő szemei előtt, az ég madarai elől is fedve van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 22, 'A pokol és halál azt mondják: Csak hírét hallottuk füleinkkel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 23, 'Isten tudja annak útját, ő ismeri annak helyét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 24, 'Mert ő ellát a föld határira, ő lát mindent az ég alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 25, 'Mikor a szélnek súlyt szerzett, és a vizeket mértékre vette;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 26, 'Mikor az esőnek határt szabott, és mennydörgő villámoknak útat:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 27, 'Akkor látta és kijelentette azt, megalapította és meg is vizsgálta azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 28, 'Az embernek pedig mondá: Ímé az Úrnak félelme: az a bölcseség, és az értelem: a gonosztól való eltávozás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 1, 'Jób pedig folytatá az ő beszédét, és monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 2, 'Oh, vajha olyan volnék, mint a hajdani hónapokban, a mikor Isten őrzött engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 3, 'Mikor az ő szövétneke fénylett fejem fölött, s világánál jártam a setétet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 4, 'A mint java-korom napjaiban valék, a mikor Isten gondossága borult sátoromra!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 5, 'Mikor még a Mindenható velem volt, és körültem voltak gyermekeim;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 6, 'Mikor lábaimat édes tejben mostam, és mellettem a szikla olajpatakokat ontott;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 7, 'Mikor a kapuhoz mentem, fel a városon; a köztéren székemet fölállítám:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 8, 'Ha megláttak az ifjak, félrevonultak, az öregek is fölkeltek és állottak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 9, 'A fejedelmek abbahagyták a beszédet, és tenyeröket szájukra tették.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 10, 'A főemberek szava elnémult, és nyelvök az ínyökhöz ragadt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 11, 'Mert a mely fül hallott, boldognak mondott engem, és a mely szem látott, bizonyságot tett én felőlem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 12, 'Mert megmentém a kiáltozó szegényt, és az árvát, a kinek nem volt segítsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 13, 'A veszni indultnak áldása szállt reám, az özvegynek szívét megörvendeztetém.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 14, 'Az igazságot magamra öltém és az is magára ölte engem; palást és süveg gyanánt volt az én ítéletem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 15, 'A vaknak én szeme valék, és a sántának lába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 16, 'A szűkölködőknek én atyjok valék, az ismeretlennek ügyét is jól meghányám-vetém.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 17, 'Az álnoknak zápfogait kitördösém, és fogai közül a prédát kiütém vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 18, 'Azt gondoltam azért: fészkemmel veszek el, és mint a homok, megsokasodnak napjaim.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 19, 'Gyökerem a víznek nyitva lesz, és ágamon hál meg a harmat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 20, 'Dicsőségem megújul velem, és kézívem erősebbé lesz kezemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 21, 'Hallgattak és figyeltek reám, és elnémultak az én tanácsomra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 22, 'Az én szavaim után nem szóltak többet, s harmatként hullt rájok beszédem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 23, 'Mint az esőre, úgy vártak rám, és szájukat tátották, mint tavaszi záporra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 24, 'Ha rájok mosolyogtam, nem bizakodtak el, és arczom derüjét nem sötétíték be.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 25, 'Örömest választottam útjokat, mint főember ültem ott; úgy laktam ott, mint király a hadseregben, mint a ki bánkódókat vigasztal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 1, 'Most pedig nevetnek rajtam, a kik fiatalabbak nálam a kiknek atyjokat az én juhaimnak komondorai közé sem számláltam volna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 2, 'Mire való lett volna nékem még kezök ereje is? Rájok nézve a vénség elveszett!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 3, 'Szükség és éhség miatt összeaszottak, a kik a kopár földet futják, a sötét, sivatag pusztaságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 4, 'A kik keserű füvet tépnek a bokor mellett, és rekettyegyökér a kenyerök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 5, 'Az emberek közül kiűzik őket, úgy hurítják őket, mint a tolvajt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 6, 'Félelmetes völgyekben kell lakniok, a földnek és szikláknak hasadékaiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 7, 'A bokrok között ordítanak, a csalánok alatt gyülekeznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 8, 'Esztelen legények, sőt becstelen fiak, a kiket kivertek az országból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 9, 'És most ezeknek lettem gúnydalává, nékik levék beszédtárgyuk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 10, 'Útálnak engem, messze távoznak tőlem, és nem átalanak pökdösni előttem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 11, 'Sőt leoldják kötelöket és bántalmaznak engem, és a zabolát előttem kivetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 12, 'Jobb felől ifjak támadnak ellenem, gáncsot vetnek lábaimnak, és ösvényt törnek felém, hogy megrontsanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 13, 'Az én útamat elrontják, romlásomat öregbítik, nincsen segítség ellenök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 14, 'Mint valami széles résen, úgy rontanak elő, pusztulás között hömpölyögnek ide.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 15, 'Rettegések fordultak ellenem, mint vihar űzik el tisztességemet, boldogságom eltünt, mint a felhő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 16, 'Mostan azért enmagamért ontja ki magát lelkem; nyomorúságnak napjai fognak meg engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 17, 'Az éjszaka meglyuggatja csontjaimat bennem, és nem nyugosznak az én inaim.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 18, 'A sok erőlködés miatt elváltozott az én ruházatom; úgy szorít engem, mint a köntösöm galléra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 19, 'A sárba vetett engem, hasonlóvá lettem porhoz és hamuhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 20, 'Kiáltok hozzád, de nem felelsz; megállok és csak nézel reám!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 21, 'Kegyetlenné változtál irántam; kezed erejével harczolsz ellenem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 22, 'Felemelsz, szélnek eresztesz engem, és széttépsz engem a viharban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 23, 'Hiszen tudtam, hogy visszatérítesz engem a halálba, és a minden élő gyülekező házába;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 24, 'De a roskadóban levő ne nyujtsa-é ki kezét? Avagy ha veszendőben van, ne kiáltson-é segítségért?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 25, 'Avagy nem sírtam-é azon, a kinek kemény napja volt; a szűkölködő miatt nem volt-é lelkem szomorú?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 26, 'Bizony jót reméltem és rossz következék, világosságot vártam és homály jöve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 27, 'Az én bensőm forr és nem nyugoszik; megrohantak engem a nyomorúságnak napjai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 28, 'Feketülten járok, de nem a nap hősége miatt; felkelek a gyülekezetben és kiáltozom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 29, 'Atyjok fiává lettem a sakáloknak, és társokká a strucz madaraknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 30, 'Bőröm feketülten hámlik le rólam, és csontom elég a hőség miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 31, 'Hegedűm sírássá változék, sípom pedig jajgatók szavává.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 1, 'Szövetségre léptem szemeimmel, és hajadonra mit sem ügyeltem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 2, 'És mi volt jutalmam Istentől felülről; vagy örökségem a Mindenhatótól a magasságból?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 3, 'Avagy nem az istentelent illeti-é romlás, és nem a gonosztevőt-é veszedelem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 4, 'Avagy nem láthatta-é utaimat, és nem számlálhatta-é meg lépéseimet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 5, 'Ha én csalárdsággal jártam, vagy az én lábam álnokságra sietett:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 6, 'Az ő igazságának mérlegével mérjen meg engem, és megismeri Isten az én ártatlanságomat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 7, 'Ha az én lépésem letért az útról és az én lelkem követte szemeimet, vagy kezeimhez szenny tapadt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 8, 'Hadd vessek én és más egye meg, és tépjék ki az én maradékaimat gyökerestől!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 9, 'Ha az én szívem asszony után bomlott, és leselkedtem az én felebarátomnak ajtaján:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 10, 'Az én feleségem másnak őröljön, és mások hajoljanak rája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 11, 'Mert gyalázatosság volna ez, és birák elé tartozó bűn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 12, 'Mert tűz volna ez, a mely pokolig emésztene, és minden jövedelmemet tövestől kiirtaná.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 13, 'Ha megvetettem volna igazát az én szolgámnak és szolgálómnak, mikor pert kezdtek ellenem:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 14, 'Mi tevő lennék, ha felkelne az Isten, és ha meglátogatna: mit felelnék néki?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 15, 'Nem az teremtette-é őt is, a ki engem teremtett anyám méhében; nem egyugyanaz formált-é bennünket anyánk ölében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 16, 'Ha a szegények kivánságát megtagadtam, és az özvegy szemeit epedni engedtem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 17, 'És ha falatomat egymagam ettem meg, és az árva abból nem evett;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 18, 'Hiszen ifjúságom óta, mint atyánál nevekedett nálam, és anyámnak méhétől kezdve vezettem őt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 19, 'Ha láttam a ruhátlant veszni indulni, és takaró nélkül a szegényt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 20, 'Hogyha nem áldottak engem az ő ágyékai, és az én juhaim gyapjából fel nem melegedett;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 21, 'Ha az árva ellen kezemet felemeltem, mert láttam a kapuban az én segítségemet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 22, 'A lapoczkájáról essék ki a vállam, és a forgócsontról szakadjon le karom!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 23, 'Hiszen úgy rettegtem Isten csapásától, és fensége előtt tehetetlen valék!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 24, 'Ha reménységemet aranyba vetettem, és azt mondtam az olvasztott aranynak: Én bizodalmam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 25, 'Ha örültem azon, hogy nagy a gazdagságom, és hogy sokat szerzett az én kezem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 26, 'Ha néztem a napot, mikor fényesen ragyogott, és a holdat, mikor méltósággal haladt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 27, 'És az én szívem titkon elcsábult, és szájammal megcsókoltam a kezemet:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 28, 'Ez is biró elé tartozó bűn volna, mert ámítottam volna az Istent oda fent!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 29, 'Ha örvendeztem az engem gyűlölőnek nyomorúságán, és ugráltam örömömben, hogy azt baj érte;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 30, '(De nem engedtem, hogy szájam vétkezzék azzal, hogy átkot kérjek az ő lelkére!)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 31, 'Ha nem mondták az én sátorom cselédei: Van-é, a ki az ő húsával jól nem lakott?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 32, '(A jövevény nem hált az utczán, ajtóimat az utas előtt megnyitám.)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 33, 'Ha emberi módon eltitkoltam vétkemet, keblembe rejtve bűnömet:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 34, 'Bizony akkor tarthatnék a nagy tömegtől, rettegnem kellene nemzetségek megvetésétől; elnémulnék és az ajtón sem lépnék ki!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 35, 'Oh, bárcsak volna valaki, a ki meghallgatna engem! Ímé, ez a végszóm: a Mindenható feleljen meg nékem; és írjon könyvet ellenem az én vádlóm.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 36, 'Bizony én azt a vállamon hordanám, és korona gyanánt a fejemre tenném!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 37, 'Lépteimnek számát megmondanám néki, mint egy fejedelem, úgy járulnék hozzá!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 38, 'Ha földem ellenem kiáltott és annak barázdái együtt siránkoztak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 39, 'Ha annak termését fizetés nélkül ettem, vagy gazdájának lelkét kioltottam:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 40, 'Búza helyett tövis teremjen és árpa helyett konkoly! Itt végződnek a Jób beszédei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 1, 'Miután ez a három ember megszünt vala felelni Jóbnak, mivel ő igaz vala önmaga előtt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 2, 'Haragra gerjede Elihu, a Barakeél fia, a ki Búztól való vala, a Rám nemzetségéből. Jób ellen gerjedt föl haragja, mivel az igazabbnak tartotta magát Istennél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 3, 'De felgerjedt haragja az ő három barátja ellen is, mivelhogy nem találják vala el a feleletet, mégis kárhoztatják vala Jóbot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 4, 'Elihu azonban várakozott a Jóbbal való beszéddel, mert amazok öregebbek valának ő nála.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 5, 'De mikor látta Elihu, hogy nincs felelet a három férfiú szájában, akkor gerjede föl az ő haragja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 6, 'És felele a Búztól való Elihu, Barakeél fia, és monda: Napjaimra nézve én még csekély vagyok, ti pedig élemedett emberek, azért tartózkodtam és féltem tudatni veletek véleményemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 7, 'Gondoltam: Hadd szóljanak a napok; és hadd hirdessen bölcseséget az évek sokasága!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 8, 'Pedig a lélek az az emberben és a Mindenható lehellése, a mi értelmet ad néki!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 9, 'Nem a nagyok a bölcsek, és nem a vének értik az ítéletet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 10, 'Azt mondom azért: Hallgass reám, hadd tudassam én is véleményemet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 11, 'Ímé, én végig vártam beszédeiteket, figyeltem, a míg okoskodtatok, a míg szavakat keresgéltetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 12, 'Igen ügyeltem reátok és ímé, Jóbot egyikőtök sem czáfolá meg, sem beszédére meg nem felelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 13, 'Ne mondjátok azt: Bölcseségre találtunk, Isten győzheti meg őt és nem ember!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 14, 'Mivel én ellenem nem intézett beszédet, nem is a ti beszédeitekkel válaszolok hát néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 15, 'Megzavarodának és nem feleltek többé; kifogyott belőlök a szó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 16, 'Vártam, de nem szóltak, csak álltak és nem feleltek többé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 17, 'Hadd feleljek hát én is magamért, hadd tudassam én is véleményemet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 18, 'Mert tele vagyok beszéddel; unszolgat engem a bennem levő lélek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 19, 'Ímé, bensőm olyan, mint az új bor, a melynek nyílása nincsen; miként az új tömlők, csaknem szétszakad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 20, 'Szólok tehát, hogy levegőhöz jussak; felnyitom ajkaimat, és felelek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 21, 'Nem leszek személyválogató senki iránt; nem hizelkedem egy embernek sem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 22, 'Mert én hizelkedni nem tudok; könnyen elszólíthatna engem a teremtőm!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 1, 'No azért halld meg csak Jób az én szavaimat, és vedd füledbe minden beszédemet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 2, 'Ímé, megnyitom már az én szájamat, és a beszéd nyelvem alatt van már.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 3, 'Igaz szívből származnak beszédeim, tiszta tudományt hirdetnek ajkaim.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 4, 'Az Istennek lelke teremtett engem, és a Mindenhatónak lehellete adott nékem életet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 5, 'Ha tudsz, czáfolj meg; készülj fel ellenem és állj elő!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 6, 'Ímé, én szintúgy Istené vagyok, mint te; sárból formáltattam én is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 7, 'Ímé, a tőlem való félelem meg ne háborítson; kezem nem lészen súlyos rajtad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 8, 'Csak az imént mondtad fülem hallatára, hallottam a beszédnek hangját:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 9, 'Tiszta vagyok, fogyatkozás nélkül: mocsoktalan vagyok, bűn nincsen bennem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 10, 'Ímé, vádakat talál ki ellenem, ellenségének tart engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 11, 'Békóba veti lábaimat, és őrzi minden ösvényemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 12, 'Ímé, ebben nincsen igazad – azt felelem néked – mert nagyobb az Isten az embernél!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 13, 'Miért perelsz vele? Azért, hogy egyetlen beszédedre sem felelt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 14, 'Hiszen szól az Isten egyszer vagy kétszer is, de nem ügyelnek rá!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 15, 'Álomban, éjjeli látomásban, mikor mély álom száll az emberre, és mikor ágyasházokban szenderegnek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 16, 'Akkor nyitja meg az emberek fülét, és megpecsételi megintetésökkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 17, 'Hogy eltérítse az embert a rossz cselekedettől, és elrejtse a kevélységet a férfi elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 18, 'Visszatartja lelkét a romlástól, és életét hogy azt fegyver ne járja át.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 19, 'Fájdalommal is bünteti az ő ágyasházában, és csontjainak szüntelen való háborgásával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 20, 'Úgy, hogy az ő ínye undorodik az ételtől, és lelke az ő kedves ételétől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 21, 'Húsa szemlátomást aszik le róla; csontjai, a melyeket látni nem lehetett, kiülnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 22, 'És lelke közelget a sírhoz, s élete a halál angyalaihoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 23, 'Ha van mellette magyarázó angyal, egy az ezer közül, hogy az emberrel tudassa kötelességét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 24, 'És az Isten könyörül rajta, és azt mondja: Szabadítsd meg őt, hogy ne szálljon a sírba; váltságdíjat találtam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 25, 'Akkor teste fiatal, erőtől duzzad, újra kezdi ifjúságának napjait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 26, 'Imádkozik Istenhez és ő kegyelmébe veszi, hogy az ő színét nézhesse nagy örömmel, és az embernek visszaadja az ő igazságát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 27, 'Az emberek előtt énekel és mondja: Vétkeztem és az igazat elferdítettem vala, de nem e szerint fizetett meg nékem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 28, 'Megváltotta lelkemet a sírba szállástól, és egész valóm a világosságot nézi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 29, 'Ímé, mindezt kétszer, háromszor cselekszi Isten az emberrel,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 30, 'Hogy megmentse lelkét a sírtól, hogy világoljon az élet világosságával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 31, 'Figyelj Jób, és hallgass meg engem; hallgass, hadd szóljak én!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 32, 'Ha van mit mondanod, czáfolj meg; szólj, mert igen szeretném a te igazságodat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 33, 'Ha pedig nincs, hallgass meg engem, hallgass és megtanítlak téged a bölcseségre!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 1, 'És szóla Elihu, és monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 2, 'Halljátok meg bölcsek az én szavaimat, és ti tudósok hajtsátok hozzám füleiteket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 3, 'Mert a fül próbálja meg a szót, mint az íny kóstolja meg az ételt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 4, 'Keressük csak magunk az igazságot, értsük meg magunk között, mi a jó?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 5, 'Mert Jób azt mondá: Igaz vagyok, de Isten megtagadja igazságomat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 6, 'Igazságom ellenére kell hazugnak lennem; halálos nyíl talált hibám nélkül!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 7, 'Melyik ember olyan, mint Jób, a ki iszsza a csúfolást, mint a vizet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 8, 'És egy társaságban forog a gonosztevőkkel, és az istentelen emberekkel jár!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 9, 'Mert azt mondja: Nem használ az az embernek, ha Istennel békességben él.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 10, 'Azért, ti tudós emberek, hallgassatok meg engem! Távol legyen Istentől a gonoszság, és a Mindenhatótól az álnokság!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 11, 'Sőt inkább, a mint cselekszik az ember, úgy fizet néki, és kiki az ő útja szerint találja meg, a mit keres.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 12, 'Bizonyára az Isten nem cselekszik gonoszságot, a Mindenható el nem ferdíti az igazságot!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 13, 'Kicsoda bízta reá a földet és ki rendezte az egész világot?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 14, 'Ha csak ő magára volna gondja, lelkét és lehellését magához vonná:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 15, 'Elhervadna együtt minden test és az ember visszatérne a porba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 16, 'Ha tehát van eszed, halld meg ezt, és a te füledet hajtsd az én beszédeimnek szavára!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 17, 'Vajjon, a ki gyűlöli az igazságot, kormányozhat-é? Avagy az ellenállhatatlan igazat kárhoztathatod-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 18, 'A ki azt mondja a királynak: Te semmirevaló! És a főembereknek: Te gonosztevő!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 19, 'A ki nem nézi a fejedelmek személyét és a gazdagot a szegénynek fölibe nem helyezteti; mert mindnyájan az ő kezének munkája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 20, 'Egy pillanat alatt meghalnak; éjfélkor felriadnak a népek és elenyésznek, a hatalmas is eltűnik kéz nélkül!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 21, 'Mert ő szemmel tartja mindenkinek útját, és minden lépését jól látja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 22, 'Nincs setétség és nincs a halálnak árnyéka, a hova elrejtőzhessék a gonosztevő;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 23, 'Mert nem sokáig kell szemmel tartania az embert, hogy az Isten elé kerüljön ítéletre!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 24, 'Megrontja a hatalmasokat vizsgálat nélkül, és másokat állít helyökbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 25, 'Ekképen felismeri cselekedeteiket, és éjjel is ellenök fordul és szétmorzsoltatnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 26, 'Gonosztevők gyanánt tapodja meg őket olyan helyen, a hol látják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 27, 'A kik azért távoztak el, és azért nem gondoltak egyetlen útjával sem,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 28, 'Hogy a szegény kiáltását hozzájok juttatja, és ő a nyomorultak kiáltását meghallja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 29, 'Ha ő nyugalmat ád, ki kárhoztatja őt? Ha elrejti arczát, ki láthatja meg azt? Akár nép elől, akár ember elől egyaránt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 30, 'Hogy képmutató ember ne uralkodjék, és ne legyen tőre a népnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 31, 'Bizony az Istenhez így való szólani: Elszenvedem, nem leszek rossz többé;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 32, 'A mit át nem látok, arra te taníts meg engemet; ha gonoszságot cselekedtem, többet nem teszem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 33, 'Avagy te szerinted fizessen-é csak azért, mert ezt megveted, és hogy te szabd meg és nem én? Nos, mit tudsz? Mondd!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 34, 'Az okos emberek azt mondják majd nékem, és a bölcs férfiú, a ki reám hallgat:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 35, 'Jób tudatlanul szól, és szavai megfontolás nélkül valók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 36, 'Óh, bárcsak megpróbáltatnék Jób mind végiglen, a miért úgy felel, mint az álnok emberek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 37, 'Mert vétkét gonoszsággal tetézi, csapkod közöttünk, és Isten ellen szószátyárkodik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 1, 'Tovább is felele Elihu, és monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 2, 'Azt gondolod-é igaznak, ha így szólsz: Az én igazságom nagyobb, mint Istené?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 3, 'Hogyha ezt mondod: Mi hasznod belőle? Mivel várhatok többet, mintha vétkezném?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 4, 'Én megadom rá néked a feleletet, és barátaidnak te veled együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 5, 'Tekints az égre és lásd meg; és nézd meg a fellegeket, milyen magasan vannak feletted!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 6, 'Hogyha vétkezel, mit tehetsz ellene; ha megsokasítod bűneidet, mit ártasz néki?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 7, 'Ha igaz vagy, mit adsz néki, avagy mit kap a te kezedből?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 8, 'Az olyan embernek árt a te gonoszságod, mint te vagy, és igazságod az ilyen ember fiának használ.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 9, 'A sok erőszak miatt kiáltoznak; jajgatnak a hatalmasok karja miatt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 10, 'De egy sem mondja: Hol van Isten, az én teremtőm, a ki hálaénekre indít éjszaka;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 11, 'A ki többre tanít minket a mezei vadaknál, és bölcsebbekké tesz az ég madarainál?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 12, 'Akkor azután kiálthatnak, de ő nem felel a gonoszok kevélysége miatt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 13, 'Mert a hiábavalóságot Isten meg nem hallgatja, a Mindenható arra nem tekint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 14, 'Hátha még azt mondod: Te nem látod őt; az ügy előtte van és te reá vársz!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 15, 'Most pedig, mivel nem büntet haragja, és nem figyelmez a nagy álnokságra:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 16, 'Azért tátja fel Jób hívságra a száját, és szaporítja a szót értelem nélkül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 1, 'És folytatá Elihu, és monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 2, 'Várj még egy kevéssé, majd felvilágosítlak, mert az Istenért még van mit mondanom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 3, 'Tudásomat messzünnen veszem, és az én teremtőmnek igazat adok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 4, 'Mert az én beszédem bizonyára nem hazugság; tökéletes tudású ember áll melletted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 5, 'Ímé, az Isten hatalmas, még sem vet meg semmit; hatalmas az ő lelkének ereje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 6, 'Nem tartja meg a gonosznak életét, de a szegénynek igaz törvényt teszen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 7, 'Nem veszi le az igazról szemeit, sőt a királyok mellé, a trónba ülteti őket örökre, hogy felmagasztaltassanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 8, 'És ha békókba veretnek, és fogva tartatnak a nyomorúság kötelein:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 9, 'Tudtokra adja cselekedetöket, és vétkeiket, hogyha elhatalmaztak rajtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 10, 'Megnyitja füleiket a feddőzésnek és megparancsolja, hogy a vétekből megtérjenek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 11, 'Ha engednek és szolgálnak néki, napjaikat jóban végzik el, és az ő esztendeiket gyönyörűségekben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 12, 'Ha pedig nem engednek, fegyverrel veretnek által, és tudatlanságban múlnak ki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 13, 'De az álnok szívűek haragot táplálnak, nem kiáltanak, mikor megkötözi őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 14, 'Azért ifjúságukban hal meg az ő lelkök, és életök a paráznákéhoz hasonló.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 15, 'A nyomorultat megszabadítja az ő nyomorúságától, és a szorongattatással megnyitja fülöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 16, 'Téged is kiszabadítana az ínség torkából tág mezőre, a hol nincs szorultság, és asztalod étke kövérséggel lenne rakva;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 17, 'De ha gonosz ítélettel vagy tele, úgy utolérnek az ítélet és igazság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 18, 'Csakhogy a harag ne ragadjon téged csúfkodásra, és a nagy váltságdíj se tántorítson el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 19, 'Ad-é valamit a te gazdagságodra? Sem aranyra, sem semmiféle erőfeszítésre!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 20, 'Ne kívánjad az éjszakát, a mely népeket mozdít ki helyökből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 21, 'Vigyázz! ne pártolj a bűnhöz, noha azt a nyomorúságnál jobban szereted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 22, 'Ímé, mily fenséges az Isten az ő erejében; kicsoda az, a ki úgy tanítson, mint ő?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 23, 'Kicsoda szabta meg az ő útjait, vagy ki mondhatja azt: Igazságtalanságot cselekedtél?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 24, 'Legyen rá gondod, hogy magasztaljad az ő cselekedetét, a melyről énekelnek az emberek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 25, 'Minden ember azt szemléli; a halandó távolról is látja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 26, 'Ímé, az Isten fenséges, mi nem ismerhetjük őt! esztendeinek száma sem nyomozható ki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 27, 'Hogyha magához szívja a vízcseppeket, ködéből mint eső cseperegnek alá,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 28, 'A melyet a fellegek özönnel öntenek, és hullatnak le temérdek emberre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 29, 'De sőt értheti-é valaki a felhő szétoszlását, az ő sátorának zúgását?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 30, 'Ímé, szétterjeszti magára az ő világosságát, és ráborítja a tengernek gyökereit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 31, 'Mert ezek által ítéli meg a népeket, ád eledelt bőségesen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 32, 'Kezeit elborítja villámlással, és kirendeli a lázadó ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 33, 'Az ő dörgése ad hírt felőle, mint a barom a közeledő viharról. Ezért remeg az én szívem, és csaknem kiszökik helyéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 1, 'Halljátok meg figyelmetesen az ő hangjának dörgését, és a zúgást, a mely az ő szájából kijön!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 2, 'Az egész ég alatt szétereszti azt, és villámát is a földnek széléig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 3, 'Utána hang zendül, az ő fenségének hangjával mennydörög, s nem tartja vissza azt, ha szava megzendült.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 4, 'Isten az ő szavával csudálatosan mennydörög, és nagy dolgokat cselekszik, úgy hogy nem érthetjük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 5, 'Mert azt mondja a hónak: Essél le a földre! És a zápor-esőnek és a zuhogó zápornak: Szakadjatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 6, 'Minden ember kezét lepecsétli, hogy megismerje minden halandó, hogy az ő műve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 7, 'Akkor a vadállat az ő tanyájára húzódik, és az ő barlangjában marad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 8, 'Rejtekéből előjön a vihar, és az északi szelektől a fagy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 9, 'Isten lehellete által támad a jég, és szorul össze a víznek szélessége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 10, 'Majd nedvességgel öntözi meg a felleget, s áttöri a borulatot az ő villáma.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 11, 'És az köröskörül forog az ő vezetése alatt, hogy mindazt megtegyék, a mit parancsol nékik, a föld kerekségének színén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 12, 'Vagy ostorul, ha földjének úgy kell, vagy áldásul juttatja azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 13, 'Vedd ezt füledbe Jób, állj meg és gondold meg az Istennek csudáit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 14, 'Megtudod-é, mikor rendeli azt rájok az Isten, hogy villanjon az ő felhőjének villáma?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 15, 'Tudod-é, hogy miként lebegnek a felhők, vagy a tökéletes tudásnak csudáit érted-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 16, 'Miképen melegülnek át ruháid, mikor nyugton van a föld a déli széltől?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 17, 'Vele együtt terjesztetted-é ki az eget, a mely szilárd, mint az aczéltükör?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 18, 'Mondd meg nékünk, mit szóljunk néki? A setétség miatt semmit sem kezdhetünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 19, 'Elbeszélik-é néki, ha szólok? Ha elmondaná valaki: bizony vége volna!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 20, 'Néha nem látják a napot, bár az égen ragyog; de szél fut át rajta és kiderül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 21, 'Észak felől aranyszínű világosság támad, Isten körül félelmetes dicsőség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 22, 'Mindenható! Nem foghatjuk meg őt; nagy az ő hatalma és ítélő ereje, és a tiszta igazságot el nem nyomja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 23, 'Azért rettegjék őt az emberek; a kevély bölcsek közül nem lát ő egyet sem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 24, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 1, 'Majd felele az Úr Jóbnak a forgószélből és monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 2, 'Ki az, a ki elhomályosítja az örök rendet tudatlan beszéddel?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 3, 'Nosza övezd fel, mint férfiú derekadat, én majd kérdezlek, te meg taníts engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 4, 'Hol voltál, mikor a földnek alapot vetettem? Mondd meg, ha tudsz valami okosat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 5, 'Ki határozta meg mértékeit, ugyan tudod-é; avagy ki húzta el felette a mérő zsinórt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 6, 'Mire bocsátották le oszlopait, avagy ki vetette fel szegeletkövét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 7, 'Mikor együtt örvendezének a hajnalcsillagok, és Istennek minden fiai vigadozának?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 8, 'És kicsoda zárta el ajtókkal a tengert, a mikor előtünt, az anyaméhből kijött;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 9, 'Mikor ruházatává a felhőt tevém, takarójául pedig a sürű homályt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 10, 'Mikor reávontam törvényemet, zárat és ajtókat veték eléje:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 11, 'És azt mondám: Eddig jőjj és ne tovább; ez itt ellene áll kevély habjaidnak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 12, 'Parancsoltál-é a reggelnek, a mióta megvagy? Kimutattad-é a hajnalnak a helyét?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 13, 'Hogy belefogózzék a földnek széleibe, és lerázassanak a gonoszok róla.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 14, 'Hogy átváltozzék mint a megpecsételt agyag, és előálljon, mint egy ruhában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 15, 'Hogy a gonoszoktól elvétessék világosságuk, és a fölemelt kar összetöressék?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 16, 'Eljutottál-é a tenger forrásáig, bejártad-é a mélységnek fenekét?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 17, 'Megnyíltak-é néked a halálnak kapui; a halál árnyékának kapuit láttad-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 18, 'Áttekintetted-é a föld szélességét, mondd meg, ha mindezt jól tudod?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 19, 'Melyik út visz oda, hol a világosság lakik, és a sötétségnek hol van a helye?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 20, 'Hogy visszavinnéd azt az ő határába, és hogy megismernéd lakása útjait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 21, 'Tudod te ezt, hiszen már akkor megszülettél; napjaidnak száma nagy!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 22, 'Eljutottál-é a hónak tárházához; vagy a jégesőnek tárházát láttad-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 23, 'A mit fentartottam a szükség idejére, a harcz és háború napjára?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 24, 'Melyik út visz oda, a hol szétoszlik a világosság, és szétterjed a keleti szél a földön?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 25, 'Ki hasított nyílást a záporesőnek, és a mennydörgő villámnak útat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 26, 'Hogy aláessék az ember nélkül való földre, a pusztaságra, holott senki sincsen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 27, 'Hogy megitasson pusztát, sivatagot, és hogy sarjaszszon zsenge pázsitot?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 28, 'Van-é atyja az esőnek, és ki szülte a harmat cseppjeit?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 29, 'Kinek méhéből jött elő a jég, és az ég daráját kicsoda szülte?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 30, 'Miként rejtőznek el a vizek mintegy kő alá, és mint zárul be a mély vizek színe?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 31, 'Összekötheted-é a fiastyúk szálait; a kaszáscsillag köteleit megoldhatod-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 32, 'A hajnalcsillagot előhozhatod-é az ő idejében, avagy a gönczölszekeret forgathatod-é fiával együtt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 33, 'Ismered-é az ég törvényeit, vagy te határozod-é meg uralmát a földön?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 34, 'Felemelheted-é szavadat a felhőig, hogy a vizeknek bősége beborítson téged?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 35, 'Kibocsáthatod-é a villámokat, hogy elmenjenek, vagy mondják-é néked: Itt vagyunk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 36, 'Ki helyezett bölcseséget a setét felhőkbe, vagy a tüneményeknek ki adott értelmet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 37, 'Ki számlálta meg a bárányfelhőket bölcseséggel, és ki üríti ki az égnek tömlőit;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 38, 'Mikor a por híg sárrá változik, és a göröngyök összetapadnak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 1, 'Vadászol-é prédát a nőstény oroszlánnak, és az oroszlánkölykök éhségét kielégíted-é;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 2, 'Mikor meglapulnak tanyáikon, és a bokrok közt lesben vesztegelnek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 3, 'Ki szerez a hollónak eledelt, mikor a fiai Istenhez kiáltoznak; kóvályognak, mert nincs mit enniök?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 4, 'Tudod-é a kőszáli zergék ellésének idejét; megvigyáztad-é a szarvasok fajzását?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 5, 'Megszámláltad-é a hónapokat, a meddig vemhesek; tudod-é az ellésök idejét?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 6, 'Csak összegörnyednek, elszülik magzataikat, vajudásaiktól megszabadulnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 7, 'Fiaik meggyarapodnak, a legelőn nagyranőnek, elszélednek és nem térnek vissza hozzájok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 8, 'Ki bocsátotta szabadon a vadszamarat, ki oldozta el e szamárnak kötelét,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 9, 'A melynek házául a pusztát rendelém, és lakóhelyéül a sósföldet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 10, 'Kineveti a városbeli sokadalmat, nem hallja a hajtsár kiáltozását.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 11, 'A hegyeken szedeget, az ő legelőjén mindenféle zöld gazt felkeres.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 12, 'Akar-é szolgálni néked a bölény? Avagy meghál-é a te jászolodnál?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 13, 'Oda kötheted a bölényt a barázdához kötelénél fogva? Vajjon boronálja-é a völgyeket utánad?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 14, 'Bízhatol-é benne, mivelhogy nagy az ereje, és munkádat hagyhatod-é reá?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 15, 'Hiszed-é róla, hogy vetésedet behordja, és szérűdre betakarítja?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 16, 'Vígan leng a struczmadár szárnya: vajjon az eszterág szárnya és tollazata-é az?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 17, 'Hiszen a földön hagyja tojásait, és a porral költeti ki!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 18, 'És elfeledi, hogy a láb eltiporhatja, és a mezei vad eltaposhatja azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 19, 'Fiaival oly keményen bánik, mintha nem is övéi volnának; ha fáradsága kárba vész, nem bánja;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 20, 'Mert Isten a bölcseséget elfeledtette vele, értelmet pedig nem adott néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 21, 'De hogyha néki ereszkedik, kineveti a lovat és lovagját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 22, 'Te adsz-é erőt a lónak, avagy a nyakát sörénynyel te ruházod-é fel?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 23, 'Felugraszthatod-é, mint a sáskát? Tüsszögése dicső, félelmetes!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 24, 'Lábai vermet ásnak, örvend erejének, a fegyver elé rohan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 25, 'Neveti a félelmet; nem remeg, nem fordul meg a fegyver elől;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 26, 'Csörög rajta a tegez, ragyog a kopja és a dárda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 27, 'Tombolva, nyihogva kapálja a földet, és nem áll veszteg, ha trombita zeng.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 28, 'A trombitaszóra nyerítéssel felel; messziről megneszeli az ütközetet, a vezérek lármáját és a csatazajt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 29, 'A te értelmed miatt van-é, hogy az ölyv repül, és kiterjeszti szárnyait dél felé?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 30, 'A te rendelésedre száll-é fent a sas, és rakja-é fészkét a magasban?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 31, 'A kősziklán lakik és tanyázik, a sziklák párkányain és bércztetőkön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 32, 'Onnét kémlel enni való után, messzire ellátnak szemei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 33, 'Fiai vért szívnak, és a hol dög van, mindjárt ott terem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 34, 'Szóla továbbá az Úr Jóbnak, és monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 35, 'A ki pert kezd a Mindenhatóval, czáfolja meg, és a ki az Istennel feddődik, feleljen néki!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 36, 'És szóla Jób az Úrnak, és monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 37, 'Ímé, én parányi vagyok, mit feleljek néked? Kezemet a szájamra teszem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 38, 'Egyszer szóltam, de már nem szólok, avagy kétszer, de nem teszem többé!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 1, 'Ekkor szóla az Úr Jóbnak a forgószélből, és monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 2, 'Nosza! övezd fel, mint férfi, derekadat; én kérdezlek, te pedig taníts engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 3, 'Avagy semmivé teheted-é te az én igazságomat; kárhoztathatsz-é te engem azért, hogy te igaz légy?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 4, 'És van-é ugyanolyan karod, mint az Istennek, mennydörgő hangon szólasz-é, mint ő?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 5, 'Ékesítsd csak fel magadat fénynyel és méltósággal, ruházd fel magadat dicsőséggel és fenséggel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 6, 'Öntsd ki haragodnak tüzét, és láss meg minden kevélyt és alázd meg őket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 7, 'Láss meg minden kevélyt és törd meg őket, és a gonoszokat az ő helyükön tipord le!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 8, 'Rejtsd el őket együvé a porba, orczájukat kösd be mélységes sötéttel:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 9, 'Akkor én is dicsőítlek, hogy megtartott téged a te jobbkezed!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 10, 'Nézd csak a behemótot, a melyet én teremtettem, a miként téged is, fűvel él, mint az ökör!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 11, 'Nézd csak az erejét az ő ágyékában, és az ő erősségét hasának izmaiban!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 12, 'Kiegyenesíti farkát, mint valami czédrust, lágyékának inai egymásba fonódnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 13, 'Csontjai érczcsövek, lábszárai, mint a vasrudak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 14, 'Az Isten alkotásainak remeke ez, az ő teremtője adta meg néki fegyverét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 15, 'Mert füvet teremnek számára a hegyek, és a mező minden vadja ott játszadozik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 16, 'Lótuszfák alatt heverész, a nádak és mocsarak búvóhelyein.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 17, 'Befedezi őt a lótuszfák árnyéka, és körülveszik őt a folyami fűzfák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 18, 'Ha árad is a folyó, nem siet; bizton van, ha szájához a Jordán csapna is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 19, 'Megfoghatják-é őt szemei láttára, vagy átfúrhatják-é az orrát tőrökkel?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 20, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 21, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 22, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 23, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 24, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 25, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 26, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 27, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 28, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 1, 'Kihúzhatod-é a leviáthánt horoggal, leszoríthatod-é a nyelvét kötéllel?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 2, 'Húzhatsz-é gúzst az orrába, az állát szigonynyal átfurhatod-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 3, 'Vajjon járul-é elődbe sok könyörgéssel, avagy szól-é hozzád sima beszédekkel?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 4, 'Vajjon frigyet köt-é veled, hogy fogadd őt örökös szolgádul?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 5, 'Játszhatol-é vele, miként egy madárral; gyermekeid kedvéért megkötözheted-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 6, 'Alkudozhatnak-é felette a társak, vagy a kalmárok közt feloszthatják-é azt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 7, 'Tele rakhatod-é nyársakkal a bőrét, avagy szigonynyal a fejét?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 8, 'Vesd rá a kezedet, de megemlékezzél, hogy a harczot nem ismételed.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 9, 'Ímé, az ő reménykedése csalárd; puszta látása is halálra ijeszt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 10, 'Nincs oly merész, a ki őt felverje. Ki hát az, a ki velem szállna szembe?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 11, 'Ki adott nékem elébb, hogy azt visszafizessem? A mi az ég alatt van, mind enyém!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 12, 'Nem hallgathatom el testének részeit, erejének mivoltát, alkotásának szépségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 13, 'Ki takarhatja fel ruhája felszínét; két sor foga közé kicsoda hatol be?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 14, 'Ki nyitotta fel orczájának ajtait? Fogainak sorai körül rémület lakik!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 15, 'Büszkesége a csatornás pajzsok, összetartva mintegy szorító pecséttel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 16, 'Egyik szorosan a másikhoz lapul, hogy közéje levegő se megy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 17, 'Egyik a másikhoz tapad, egymást tartják, egymástól elszakadhatatlanok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 18, 'Tüsszentése fényt sugároz ki, és szemei, mint a hajnal szempillái.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 19, 'A szájából szövétnekek jőnek ki, és tüzes szikrák omlanak ki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 20, 'Orrlyukaiból gőz lövel elő, mint a forró fazékból és üstből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 21, 'Lehellete meggyujtja a holt szenet, és a szájából láng lövel elő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 22, 'Nyakszirtjén az erő tanyáz, előtte félelem ugrándozik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 23, 'Testének részei egymáshoz tapadtak; kemény önmagában és nem izeg-mozog.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 24, 'Szíve kemény, mint a kő, oly kemény, mint az alsó malomkő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 25, 'Hogyha felkél, hősök is remegnek; ijedtökben veszteg állnak. Ha éri is a fegyver, nem áll meg benne, legyen bár dárda, kopja vagy kelevéz. Annyiba veszi a vasat, mint a pozdorját, az aczélt, mint a korhadt fát. A nyíl vesszője el nem űzi őt, a parittyakövek pozdorjává változnak rajta. Pozdorjának tartja a buzogányütést is, és kineveti a bárd suhogását. Alatta éles cserepek vannak; mint szeges borona hentereg az iszap felett. Felkavarja a mély vizet, mint a fazekat, a tengert olyanná teszi, mint a festékedény. Maga után világos ösvényt hagy, azt hinné valaki, a tenger megőszült. Nincs e földön hozzá hasonló, a mely úgy teremtetett, hogy ne rettegjen. Lenéz minden nagy állatot, ő a király minden ragadozó felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 1, 'Jób pedig felele az Úrnak, és monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 2, 'Tudom, hogy te mindent megtehetsz, és senki téged el nem fordíthat attól, a mit elgondoltál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 3, 'Ki az – mondod – a ki gáncsolja az örök rendet tudatlanul? Megvallom azért, hogy nem értettem; csodadolgok ezek nékem, és fel nem foghatom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 4, 'Hallgass hát, kérlek, én hadd beszéljek; én kérdezlek, te pedig taníts meg engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 5, 'Az én fülemnek hallásával hallottam felőled, most pedig szemeimmel látlak téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 6, 'Ezért hibáztatom magam és bánkódom a porban és hamuban!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 7, 'Miután pedig e szavakat mondotta vala az Úr Jóbnak, szóla a Témánból való Elifáznak: Haragom felgerjedt ellened és két barátod ellen, mert nem szóltatok felőlem igazán, mint az én szolgám, Jób.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 8, 'Most azért vegyetek magatokhoz hét tulkot és hét kost, és menjetek el az én szolgámhoz Jóbhoz, és áldozzatok magatokért égőáldozatot; Jób pedig, az én szolgám, imádkozzék ti érettetek; mert csak az ő személyére tekintek, hogy retteneteset ne cselekedjem veletek, mivelhogy nem szóltatok felőlem igazán, mint az én szolgám Jób.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 9, 'Elmenének azért a Témánból való Elifáz, a Sukhból való Bildád és a Naamából való Czófár, és úgy cselekedének, a miképen mondotta vala nékik az Úr, és az Úr tekinte Jóbnak személyére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 10, 'Azután eltávolítá Isten Jóbról a csapást, miután imádkozott vala az ő barátaiért, és kétszeresen visszaadá az Úr Jóbnak mindazt, a mije volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 11, 'És beméne hozzá minden fiútestvére és minden leánytestvére és minden előbbi ismerőse, és evének ő vele együtt kenyeret az ő házában; sajnálkozának felette és vigasztalák őt mindama nyomorúság miatt, a melyet az Úr reá bocsátott vala, és kiki ada néki egy-egy pénzt, és kiki egy-egy aranyfüggőt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 12, 'Az Úr pedig jobban megáldá a Jób életének végét, mint kezdetét, mert lőn néki tizennégyezer juha, hatezer tevéje, ezer igás ökre és ezer szamara.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 13, 'És lőn néki hét fia és három leánya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 14, 'És az elsőnek neve vala Jémima, a másodiké Kecziha, a harmadiké Kéren-Happuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 15, 'És nem találtatnak vala olyan szép leányok, mint a Jób leányai, abban az egész tartományban, és az ő atyjok örökséget is ada nékik az ő fiútestvéreik között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 16, 'Jób pedig él vala ezután száznegyven esztendeig, és látja vala az ő fiait és unokáit negyedízig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 17, 'És meghala Jób jó vénségben és betelve az élettel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'Boldog ember az, a ki nem jár gonoszok tanácsán, bűnösök útján meg nem áll, és csúfolódók székében nem ül;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'Hanem az Úr törvényében van gyönyörűsége, és az ő törvényéről gondolkodik éjjel és nappal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'És olyan lesz, mint a folyóvizek mellé ültetett fa, a mely idejekorán megadja gyümölcsét, és levele nem hervad el; és minden munkájában jó szerencsés lészen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Nem úgy a gonoszok, hanem, mint a polyva, a mit szétszór a szél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'Azért nem állhatnak meg a gonoszok az ítéletben; sem a bűnösök az igazak gyülekezetében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'Mert tudja az Úr az igazak útját; a gonoszok útja pedig elvész.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'Miért dühösködnek a pogányok, és gondolnak hiábavalóságot a népek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'A föld királyai felkerekednek és a fejedelmek együtt tanácskoznak az Úr ellen és az ő felkentje ellen:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, 'Szaggassuk le az ő bilincseiket, és dobjuk le magunkról köteleiket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'Az egekben lakozó neveti, az Úr megcsúfolja őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'Majd szól nékik haragjában, és megrettenti őket gerjedelmében:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, 'Én kentem ám fel az én királyomat a Sionon, az én szent hegyemen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, 'Törvényül hirdetem: Az Úr mondá nékem: Én fiam vagy te; én ma nemzettelek téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'Kérjed tőlem és odaadom néked a pogányokat örökségül, és birtokodul a föld határait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'Összetöröd őket vasvesszővel: széjjelzúzod őket, mint cserépedényt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'Azért, királyok, legyetek eszesek, és okuljatok földnek bírái!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'Szolgáljátok az Urat félelemmel, és örüljetek reszketéssel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'Csókoljátok a Fiút, hogy meg ne haragudjék és el ne veszszetek az úton, mert hamar felgerjed az ő haragja. Boldogok mindazok, a kik ő benne bíznak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, 'Dávid zsoltára; fia, Absolon elől való futásakor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'Uram! mennyire megsokasodtak ellenségeim! sokan vannak a reám támadók!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'Sokan mondják az én lelkem felől: Nincs számára segítség Istennél, Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'De te, oh Uram! paizsom vagy nékem, dicsőségem, az, a ki felmagasztalja az én fejemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'Felszóval kiálték az Úrhoz, és ő meghallgata engemet, az ő szentsége hegyéről. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, 'Én lefekszem és elalszom; felébredek, mert az Úr támogat engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'Nem félek sok ezernyi néptől sem, a mely köröskörül felállott ellenem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, 'Kelj fel Uram, tarts meg engem Istenem, mert te verted arczul minden ellenségemet; a gonoszok fogait összetörted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 9, 'Az Úré a szabadítás; legyen a te népeden a te áldásod. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, 'Az éneklőmesternek a neginóthra, Dávid zsoltára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, 'Mikor kiáltok, hallgass meg engem, igazságomnak Istene; szorultságomban tág tért adtál nékem; könyörülj rajtam és halld meg az én imádságomat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, 'Emberek fiai! Meddig lesz gyalázatban az én dicsőségem? Meddig szerettek hiábavalóságot, és kerestek hazugságot? Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, 'Tudjátok meg hát, hogy kedveltjévé választott az Úr; meghallja az Úr, ha hozzá kiáltok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, 'Haragudjatok, de ne vétkezzetek: beszéljetek szívetekkel a ti ágyasházatokban és csillapodjatok! Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, 'Igazságnak áldozatával áldozzatok, és bízzatok az Úrban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, 'Sokan mondják: Kicsoda láttat velünk jót? Hozd fel reánk arczodnak világosságát, oh Uram!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, 'Nagyobb örömöt adsz így szívembe, mint a mikor sok az ő búzájok és boruk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 9, 'Békességben fekszem le és legott elaluszom; mert te, Uram, egyedül adsz nékem bátorságos lakozást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, 'Az éneklőmesternek a nehilótra, Dávid zsoltára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, 'Uram, figyelmezz szavaimra; értsd meg az én sóhajtásomat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, 'Ügyelj az én kiáltásom szavára, én Királyom és én Istenem; mert én hozzád imádkozom!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, 'Uram, jó reggel hallgasd meg az én szómat; jó reggel készülök hozzád és vigyázok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, 'Mert nem olyan Isten vagy te, a ki hamisságban gyönyörködnél; nem lakhatik tenálad gonosz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, 'Nem állhatnak meg szemeid előtt a kevélyek, gyűlölsz te minden bűnt cselekedőt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, 'Elveszted, a kik hazugságot szólnak; a vérszopó és álnok embert útálja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, 'Én pedig a te kegyelmed sokaságából házadba mehetek; leborulok szent templomodban a te félelmedben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, 'Uram, vezess engem a te igazságodban az én ellenségeim miatt; egyengesd előttem a te útadat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, 'Mert nincsen az ő szájokban egyenesség, belsejök csupa romlottság; nyitott sír az ő torkuk, nyelvökkel hizelkednek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, 'Kárhoztasd őket, oh Isten; essenek el saját tanácsaik által; taszítsd el őket vétkeik sokasága miatt, mert fellázadtak ellened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, 'És majd örülnek mindnyájan, a kik bíznak benned; mindörökké vígadjanak, és te megoltalmazod őket, és örvendeznek te benned, a kik szeretik a te nevedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 13, 'Mert te, Uram, megáldod az igazat, körülveszed a te jóvoltoddal, mint egy paizszsal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, 'Az éneklőmesternek a neginóthra, a seminith szerint; Dávid zsoltára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, 'Uram, ne feddj meg engem haragodban, és ne ostorozz engem búsulásodban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, 'Könyörülj rajtam Uram, mert ellankadtam: gyógyíts meg engem Uram, mert megháborodtak csontjaim!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, 'Lelkem is igen megháborodott, és te, oh Uram, míglen?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, 'Térj vissza Uram, mentsd ki lelkemet, segíts meg engem kegyelmedért;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, 'Mert nincs emlékezés rólad a halálban, a seolban kicsoda dicsőít téged?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, 'Elfáradtam sóhajtozásomban, egész éjjel áztattam ágyamat, könyhullatással öntöztem nyoszolyámat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, 'Szemem a bánattól elbágyadt, megvénhedett minden szorongatóm miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, 'Távozzatok tőlem mind, ti bűnt cselekedők, mert meghallgatja az Úr az én siralmam szavát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, 'Meghallgatja az Úr az én könyörgésemet, elfogadja az Úr az én imádságomat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 11, 'Megszégyenül majd és igen megháborodik minden ellenségem; meghátrálnak és megszégyenülnek hirtelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'Dávid siggajonja, a melyet az Úrhoz énekelt a Benjáminita Kús beszéde miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, 'Én Uram Istenem, benned bízom; oltalmazz meg engem minden üldözőmtől, és szabadíts meg engem,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, 'Hogy szét ne tépje, mint az oroszlán az én lelkemet, szét ne szaggassa, ha nincsen szabadító.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, 'Én Uram Istenem, ha cselekedtem ezt, ha hamisság van az én kezeimben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, 'Ha gonoszszal fizettem jó emberemnek, és háborgattam ok nélkül való ellenségemet:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, 'Akkor ellenség üldözze lelkemet s érje el és tapodja földre az én életemet, és sujtsa porba az én dicsőségemet. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, 'Kelj fel, Uram, haragodban, emelkedjél fel ellenségeim dühe ellen; serkenj fel mellettem, te, a ki parancsoltál ítéletet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, 'És népek gyülekezete vegyen téged körül, és felettök térj vissza a magasságba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, 'Az Úr ítéli meg a népeket. Bírálj meg engem Uram, az én igazságom és ártatlanságom szerint!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, 'Szünjék meg, kérlek, a gonoszok rosszasága és erősítsd meg az igazat; mert az igaz Isten vizsgálja meg a szíveket és veséket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, 'Az én paizsom az Istennél van, a ki megszabadítja az igazszívűeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, 'Isten igaz biró; és olyan Isten, a ki mindennap haragszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, 'Ha meg nem tér a gonosz, kardját élesíti, kézívét felvonja és felkészíti azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, 'Halálos eszközöket fordít reá, és megtüzesíti nyilait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, 'Ímé, álnoksággal vajúdik a gonosz, hamisságot fogan és hazugságot szül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, 'Gödröt ás és mélyre vájja azt; de beleesik a verembe, a mit csinált.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, 'Forduljon vissza fejére az, a mit elkövetett, és szálljon feje tetejére az ő erőszakossága.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 18, 'Dicsérem az Urat az ő igazsága szerint, és éneklek a felséges Úr nevének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'Az éneklőmesternek a gittithre; Dávid zsoltára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'Mi Urunk Istenünk, mily felséges a te neved az egész földön, a ki az egekre helyezted dicsőségedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'A csecsemők és csecsszopók szájával erősítetted meg hatalmadat a te ellenségeid miatt, hogy a gyűlölködőt és bosszúállót elnémítsd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'Mikor látom egeidet, a te újjaidnak munkáját; a holdat és a csillagokat, a melyeket teremtettél:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'Micsoda az ember – mondom – hogy megemlékezel róla? és az embernek fia, hogy gondod van reá?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'Hiszen kevéssel tetted őt kisebbé az Istennél, és dicsőséggel és tisztességgel megkoronáztad őt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'Úrrá tetted őt kezeid munkáin, mindent lábai alá vetettél;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'Juhokat és mindenféle barmot, és még a mezőnek vadait is;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'Az ég madarait és a tenger halait, mindent, a mi a tenger ösvényein jár.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 10, 'Mi Urunk Istenünk, mily felséges a te neved az egész földön!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, 'Az éneklőmesternek a múthlabbén szerint; Dávid zsoltára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'Dicsérlek Uram teljes szívemmel, hirdetem minden csudatételedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'Örülök és örvendezek tebenned, zengedezem, oh Magasságos, a te nevedet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'Hogy az én ellenségeim meghátráltak, elbuktak és elvesztek a te orczád előtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'Hogy véghezvitted ítéletemet és ügyemet: az ítélő-székben ültél, mint igaz bíró.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, 'Megdorgáltad a pogányokat, elvesztetted a gonoszt: nevöket mindörökre kitörölted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, 'Az ellenség megszünt, elpusztult örökre; és a városoknak, a miket feldúltál még az emlékezetök is elveszett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'Az Úr pedig örökké trónol, ítéletre készítette el az ő székét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'És ő megítéli a világot igazsággal, törvényt tesz a népeknek méltányosan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, 'És lesz az Úr nyomorultak kővára, kővár a szükség idején.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'Azért te benned bíznak, a kik ismerik a te nevedet; mert nem hagytad el, Uram, a kik keresnek téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, 'Zengjetek az Úrnak, a ki Sionban lakik; hirdessétek a népek között az ő cselekedeteit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, 'Mert számon kéri a kiontott vért, megemlékezik rólok, nem feledkezik el a szegények kiáltásáról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'Könyörülj rajtam, Uram! lásd meg az én nyomorúságomat, a mely gyűlölőim miatt van, a ki felemelsz engem a halál kapuiból;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, 'Hogy hirdessem minden dicséretedet Sion leányának kapuiban; hadd örvendjek a te szabadításodban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, 'Besülyedtek a pogányok a verembe, a melyet ástak; a hálóban, a melyet elrejtettek, megakadt a lábok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, 'Megismertetett az Úr, ítéletet hozott; a gonoszt annak kezemunkájával ejtette el. Higgajon. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, 'Seolba jutnak a gonoszok, oda minden nép, a mely elfeledkezik Istenről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, 'Mert a szegény nem lesz végképen elfelejtve, a nyomorultak reménye sem vész el örökre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, 'Kelj fel Uram, ne hatalmasodjék el a halandó; ítéltessenek meg a pogányok te előtted!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 21, 'Rettentsd meg, Uram, őket; tudják meg a pogányok, hogy halandók ők! Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'Uram, miért állasz távol? Miért rejtőzöl el a szükség idején?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'A gonosznak kevélysége miatt sanyarog a szegény. Essenek foglyul a cseleknek, a miket koholtak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'Mert dicsekszik a gonosz az ő lelkének kivánságával, és a fösvény megveti és szidja az Urat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'A gonosz az ő haragos kevélységében senkit sem tudakoz; nincs Isten, ez minden gondolatja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'Szerencsések az ő útai minden időben; messze vannak tőle ítéleteid, elfújja minden ellenségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'Azt mondja szívében: Nem rendülök meg soha örökké, mert nem esem bajba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'Szája telve átkozódással, csalárdsággal és erőszakossággal; nyelve alatt hamisság és álnokság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'Az utczák zugaiban lappang, a rejtekhelyeken megöli az ártatlant, szemei lesnek az ügyefogyottra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, 'Leselkedik a rejtekhelyen, leselkedik, mint az oroszlán az ő barlangjában, hogy elragadja a szegényt; elragadja a szegényt, mihelyt hálójába foghatja azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'Lenyomja, tiporja, és erejétől elesnek az ügyefogyottak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, 'Azt mondja szívében: Elfelejtkezett Isten, elrejtette arczát: nem is látott soha!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'Kelj fel Úr-Isten, emeld fel kezedet; ne feledkezzél el a szegényekről!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, 'Miért szidja Istent a gonosz? Miért mondja szívében: Nem keresed rajta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, 'Te látod ezt, mert te megnézed a hamisságot és a fájdalmat, hogy rávessed kezed. Te reád hagyja magát az ügyefogyott, az árvának is te vagy segedelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, 'Törd össze a gonosznak karját; és keressed a rosszon az ő gonoszságát, míg már nem találsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, 'Az Úr király mindenha és mindörökké; a pogányok kivesznek az ő földjéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, 'A szegények kivánságát meghallgatod, oh Uram! Megerősíted szívöket, füleiddel figyelmezel,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, 'Hogy ítéletet tégy az árvának és nyomorodottnak, hogy többé már ne rettentsen a földből való ember.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, 'Az éneklőmesternek; Dávidé. Az Úrban bízom; hogy mondhatjátok az én lelkemnek: fuss a ti hegyetekre, mint a madár?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, 'Mert ímé, a gonoszok megvonják az íjat, ráillesztették nyilokat az idegre, hogy a sötétségben az igazszívűekre lövöldözzenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, 'Mikor a fundamentomok is elrontattak, mit cselekedett az igaz?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'Az Úr az ő szent templomában, az Úr trónja az egekben; az ő szemei látják, szemöldökei megpróbálják az emberek fiait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'Az Úr az igazat megpróbálja, a gonoszt pedig, az álnokság kedvelőjét, gyűlöli az ő lelke.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, 'Hálókat hullat a gonoszokra; tűz, kénkő és égető szél az ő osztályrészök!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'Mert az Úr igaz; igazságot szeret, az igazak látják az ő orczáját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, 'Az éneklőmesternek a seminithre; Dávid zsoltára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, 'Segíts Uram, mert elfogyott a kegyes, mert eltüntek a hívek az emberek fiai közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, 'Hamisságot szól egyik a másiknak; hizelkedő ajakkal kettős szívből szólnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, 'Vágja ki az Úr mind a hizelkedő ajkakat, a nyelvet, a mely nagyokat mond.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, 'A kik ezt mondják: Nyelvünkkel felülkerekedünk, ajkaink velünk vannak; ki lehetne Úr felettünk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, 'A szegények elnyomása miatt, a nyomorultak nyögése miatt legott felkelek, azt mondja az Úr; biztosságba helyezem azt, a ki arra vágyik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, 'Az Úr beszédei tiszta beszédek, mint földből való kohóban megolvasztott ezüst, hétszer megtisztítva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, 'Te Uram, tartsd meg őket; őrizd meg őket e nemzetségtől örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 9, 'Köröskörül járnak a gonoszok, mihelyt az alávalóság felmagasztaltatik az emberek fiai közt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, 'Az éneklőmesternek; Dávid zsoltára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'Uram, meddig felejtkezel el rólam végképen? Meddig rejted el orczádat tőlem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'Meddig tanakodjam lelkemben, bánkódjam szívemben naponként? Meddig hatalmaskodik az én ellenségem rajtam?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'Nézz ide, felelj nékem, Uram Istenem; világosítsd meg szemeimet, hogy el ne aludjam a halálra;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'Hogy ne mondja ellenségem: meggyőztem őt; háborgatóim ne örüljenek, hogy tántorgok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'Mert én a te kegyelmedben bíztam, örüljön a szívem a te segítségednek; hadd énekeljek az Úrnak, hogy jót tett velem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, 'Az éneklőmesternek; Dávidé. Azt mondja a balgatag az ő szívében: Nincs Isten. Megromlottak, útálatosságot cselekedtek; nincs, a ki jót cselekedjék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'Az Úr letekintett a mennyből az emberek fiaira, hogy meglássa, ha van-é értelmes, Istent kereső?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'Mindnyájan elhajlottak; egyetemben elromlottak, nincs, a ki jót cselekedjék, nincsen csak egy sem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, 'Nem tudják-é ezt mind a gonosztévők, a kik megeszik az én népemet, mintha kenyeret ennének, az Urat pedig segítségül nem hívják?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, 'Majd rettegnek rettegéssel, mert Isten az igaz nemzetséggel van!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'A szegénynek tanácsát kicsúfoljátok, mert az Úr az ő bizodalma.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'Vajha eljőne Sionból Izráelnek a szabadítás! Mikor az Úr visszahozza népének foglyait, Jákób örül majd és vigad Izráel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, 'Dávid zsoltára. Uram, kicsoda tartózkodhatik sátorodban, kicsoda lakozhatik szent hegyeden?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, 'A ki tökéletességben jár, igazságot cselekszik, és igazat szól az ő szívében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'Nem rágalmaz nyelvével; nem tesz rosszat felebarátjának, és nem szerez gyalázatot rokonainak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, 'A megbélyegzett útálatos az ő szemeiben, de az Urat félőket tiszteli: a ki kárára esküszik, és meg nem változtatja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, 'Pénzét nem adja uzsorára, és nem vesz el ajándékot az ártatlan ellen. A ki ezeket cselekszi, nem rendül meg soha örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, 'Dávid miktámja. Tarts meg engem Istenem, mert benned bízom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'Ezt mondom az Úrnak: Én Uram vagy te; feletted való jóm nincsen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, 'A szentekben, a kik e földön vannak és a felségesekben, bennök van minden gyönyörűségem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'Megsokasodnak fájdalmaik, a kik más isten után sietnek; nem áldozom meg véres italáldozatjokat és nem veszem nevöket ajkaimra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'Az Úr az én osztályos részem és poharam; te támogatod az én sorsomat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, 'Az én részem kies helyre esett, nyilván szép örökség jutott nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'Áldom az Urat, a ki tanácsot adott nékem; még éjjel is oktatnak engem az én veséim.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'Az Úrra néztem szüntelen; mert jobb kezem felől van, meg nem rendülök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'Azért örül az én szívem és örvendez az én lelkem; testem is biztosságban lakozik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'Mert nem hagyod lelkemet a Seolban; nem engeded, hogy a te szented rothadást lásson.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'Te tanítasz engem az élet ösvényére, teljes öröm van tenálad; a te jobbodon gyönyörűségek vannak örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 1, 'Dávid imádsága. Hallgasd meg, Uram, az igazságot, vedd észre könyörgésemet, figyelmezzél imádságomra, mely nem jő csalárd ajakról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 2, 'A te orczádtól jőjjön ki ítéletem, a te szemeid hadd lássanak igazat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 3, 'Megpróbáltad az én szívemet, meglátogattál éjjel; próbáltál engem, nem találtál semmi rosszat; ha tán gondoltam is, nem jött ki a számon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 4, 'Az emberek cselekedeteinél a te ajkad igéjével vigyáztam az erőszakosnak ösvényeire.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 5, 'Ragaszkodtak lépteim a te ösvényeidhez, nem ingadoztak lábaim.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 6, 'Hívtalak én, mert te felelhetsz nékem, Istenem! Hajtsd hozzám füledet, hallgasd meg az én beszédemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 7, 'Mutasd meg csudálatosan a te kegyelmedet, a ki megszabadítod jobboddal a te benned bízókat a támadóktól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 8, 'Tarts meg engemet, mint szemed fényét; szárnyaid árnyékába rejts el engemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 9, 'A gonoszok elől, a kik pusztítanak engem; ellenségeim elől, a kik lelkendezve vesznek körül engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 10, 'Megkövéredett szívöket elzárták, szájokkal kevélyen szólanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 11, 'Körülvettek most minket mentünkben; szemeiket ránk szegzik, hogy földre terítsenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 12, 'Hasonlók az oroszlánhoz, a mely zsákmányra szomjaz, és a rejtekhelyen ülő oroszlánkölyökhöz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 13, 'Kelj fel, oh Uram! Szállj vele szembe, terítsd le őt, szabadítsd meg lelkemet a gonosztól fegyvereddel;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 14, 'Az emberektől, oh Uram, kezeddel, a világ embereitől! Az ő osztályrészük az életben van; megtöltötted hasukat javaiddal, bővölködnek fiakkal, a miök pedig marad, gyermekeikre hagyják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 15, 'Én igazságban nézem a te orczádat, megelégszem a te ábrázatoddal, midőn felserkenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 1, 'Az éneklőmesternek, az Úr szolgájától, Dávidtól, a ki az Úrhoz ez ének szavait azon a napon mondotta, a melyen az Úr megszabadította őt minden ellenségének kezéből, és a Saul kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 2, 'És monda: Szeretlek Uram, én erősségem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 3, 'Az Úr az én kősziklám, váram és szabadítóm; az én Istenem, az én kősziklám, ő benne bízom: az én paizsom, idvességem szarva, menedékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 4, 'Az Úrhoz kiáltok, a ki dicséretre méltó, és megszabadulok ellenségeimtől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 5, 'Halál kötelei vettek körül, s az istentelenség árjai rettentettek engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 6, 'A Seol kötelei vettek körül; a halál tőrei fogtak meg engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 7, 'Szükségemben az Urat hívtam, és az én Istenemhez kiáltottam; szavamat meghallá templomából, és kiáltásom eljutott füleibe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 8, 'Megindult, megrendült a föld, s a hegyek fundamentomai inogtak; és megindultak, mert haragra gyúlt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 9, 'Füst szállt fel orrából, és szájából emésztő tűz; izzó szén gerjedt belőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 10, 'Lehajtotta az eget és leszállt, és homály volt lábai alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 11, 'Kérubon haladt és röpült, és a szelek szárnyain suhant.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 12, 'A sötétséget tette rejtekhelyévé; sátora körülötte a sötét felhők és sűrű fellegek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 13, 'Az előtte lévő fényességből felhőin jégeső tört át és eleven szén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 14, 'És dörgött az Úr a mennyekben, és a Magasságos zengett; és jégeső hullt és eleven szén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 15, 'És kibocsátá nyilait és elszéleszté azokat, villámokat szórt és megháborította azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 16, 'És meglátszottak a vizek medrei s megmutatkoztak a világ fundamentomai; a te feddésedtől, Uram, a te orrod leheletének fuvásától.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 17, 'Lenyúlt a magasból és felvett engem; kivont engem nagy vizekből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 18, 'Megszabadított engem az én erős ellenségemtől, s az én gyűlölőimtől, a kik hatalmasabbak voltak nálamnál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 19, 'Rám jöttek veszedelmem napján; de az Úr volt az én támaszom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 20, 'És kivitt engem tágas helyre; kiragadt engem, mert kedvét leli bennem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 21, 'Az Úr megfizetett nékem igazságom szerint, kezeimnek tisztasága szerint fizetett meg nékem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 22, 'Mert megőriztem az Úrnak útait, és gonoszul nem távoztam el az én Istenemtől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 23, 'Mert minden ítélete előttem, és rendeléseit nem hánytam el magamtól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 24, 'És tökéletes voltam előtte, őrizkedtem az én vétkemtől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 25, 'És megfizetett nékem az Úr az én igazságom szerint; kezeim tisztasága szerint, a mi szemei előtt van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 26, 'Az irgalmashoz irgalmas vagy: a tökéleteshez tökéletes vagy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 27, 'A tisztával tiszta vagy; s a visszáshoz visszás vagy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 28, 'Mert te megtartod a nyomorult népet, és a kevély szemeket megalázod;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 29, 'Mert te gyujtod meg az én szövétnekemet; az Úr az én Istenem megvilágosítja az én sötétségemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 30, 'Mert általad táboron is átfutok, és az én Istenem által kőfalon is átugrom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 31, 'Az Istennek útja tökéletes; az Úrnak beszéde tiszta; paizsuk ő mindazoknak, a kik bíznak benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 32, 'Mert kicsoda Isten az Úron kivül? És kicsoda kőszikla a mi Istenünkön kivül?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 33, 'Az Isten, a ki felövez engem erővel, és tökéletessé teszi útamat:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 34, 'Olyanná teszi lábamat, mint a szarvasé, és az én magas helyeimre állít engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 35, 'Ő tanítja kezemet a harczra, karjaim meghajlítják az érczíjat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 36, 'És adtad nékem a te idvességednek paizsát, és a te jobbod megszilárdított engem, és a te jóvoltod felmagasztalt engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 37, 'Kiszélesítetted lépésemet alattam, és nem tántorogtak lábaim.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 38, 'Üldözöm ellenségeimet és elérem őket, és nem térek vissza, míg meg nem semmisültek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 39, 'Összetöröm őket, hogy fel sem kelhetnek; lábaim alá hullanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 40, 'Mert te öveztél fel engem erővel a harczra, alám görbeszted az ellenem felkelőket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 41, 'És megadtad, hogy ellenségeim meghátráltak, és az én gyűlölőimet elpusztíthattam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 42, 'Kiáltottak, de nem volt szabadító, az Úrhoz és nem felelt nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 43, 'És apróra törtem őket, a milyen a szél elé való por, és megtapodtam őket mint utcza sarát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 44, 'Megmentettél engem a nép pártoskodásaitól; nemzetek fejévé tettél engem; oly nép szolgál nékem, a melyet nem ismertem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 45, 'A mint hall a fülök, engedelmeskednek, és idegenek is hizelegnek nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 46, 'Az idegenek elepedtek, és reszketve jőnek elő zárt helyeikből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 47, 'Él az Úr és áldott az én kősziklám, magasztaltassék hát az én idvességemnek Istene!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 48, 'Az Isten, a ki bosszút áll értem, és népeket hajlít alám;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 49, 'A ki megment engem ellenségeimtől. Még az ellenem felkelők fölött is felmagasztalsz engem, az erőszakos embertől megszabadítasz engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 50, 'Azért dicsérlek téged, Uram, a nemzetek között, és éneket zengek a te nevednek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 51, 'Nagy segítséget ád az ő királyának és irgalmasságot cselekszik az ő felkentjével, Dáviddal és az ő magvával mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 1, 'Az éneklőmesternek; Dávid zsoltára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 2, 'Az egek beszélik Isten dicsőségét, és kezeinek munkáját hirdeti az égboltozat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 3, 'Nap napnak mond beszédet; éj éjnek ad jelentést.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 4, 'Nem olyan szó, sem olyan beszéd, a melynek hangja nem hallható:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 5, 'Szózatuk kihat az egész földre, és a világ végére az ő mondásuk. A napnak csinált bennök sátort.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 6, 'Olyan ez, mint egy vőlegény, a ki az ő ágyasházából jön ki; örvend, mint egy hős, hogy futhatja a pályát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 7, 'Kijövetele az ég egyik szélétől s forgása a másik széléig; és nincs semmi, a mi elrejtőzhetnék hevétől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 8, 'Az Úrnak törvénye tökéletes, megeleveníti a lelket; az Úrnak bizonyságtétele biztos, bölcscsé teszi az együgyűt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 9, 'Az Úrnak rendelései helyesek, megvidámítják a szívet; az Úrnak parancsolata világos, megvilágosítja a szemeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 10, 'Az Úrnak félelme tiszta, megáll mindörökké; az Úrnak ítéletei változhatatlanok s mindenestől fogva igazságosak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 11, 'Kivánatosabbak az aranynál, még a sok színaranynál is; és édesebbek a méznél, még a színméznél is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 12, 'Szolgádat is intik azok; a ki megtartja azokat, nagy jutalma van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 13, 'Ki veheti észre a tévedéseket? Titkos bűnöktől tisztíts meg engemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 14, 'Tartsd távol a te szolgádat a szándékosoktól; ne uralkodjanak rajtam; akkor ártatlan leszek, és tiszta leszek, sok vétektől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 15, 'Legyenek kedvedre valók szájam mondásai, és az én szívem gondolatai előtted, legyenek, oh Uram, kősziklám és megváltóm.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 1, 'Az éneklőmesternek; Dávid zsoltára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 2, 'Hallgasson meg téged az Úr a szükség idején; oltalmazzon meg téged a Jákób Istenének neve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 3, 'Küldjön néked segítséget a szent helyről; és a Sionból támogasson téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 4, 'Emlékezzék meg minden ételáldozatodról, és égőáldozataidat találja kövéreknek. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 5, 'Cselekedjék veled szíved szerint, és teljesítse minden szándékodat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 6, 'Hogy örvendhessünk a te szabadulásodban, és a mi Istenünk nevében zászlót lobogtassunk: teljesítse az Úr minden kérésedet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 7, 'Most tudom, hogy az Úr megsegíti felkentjét; meghallgatja őt szent egeiből jobbjának segítő erejével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 8, 'Ezek szekerekben, amazok lovakban bíznak; mi pedig az Úrnak, a mi Istenünknek nevéről emlékezünk meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 9, 'Azok meghanyatlanak és elesnek; mi pedig felkelünk és megállunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 10, 'Uram, segítsd meg a királyt! Hallgasson meg minket, mikor kiáltunk hozzá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 1, 'Az éneklőmesternek; Dávid zsoltára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 2, 'Uram, a te erősségedben örül a király, és a te segítségedben felette örvendez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 3, 'Szívének kivánságát megadtad néki; és ajkainak kérését nem tagadtad meg. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 4, 'Sőt eléje vitted javaidnak áldásait; szín-arany koronát tettél fejére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 5, 'Életet kért tőled: adtál néki hosszú időt, örökkévalót és végtelent.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 6, 'Nagy az ő dicsősége a te segítséged által; fényt és méltóságot adtál reája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 7, 'Sőt áldássá tetted őt örökké, megvidámítottad őt színed örömével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 8, 'Bizony a király bízik az Úrban, és nem inog meg, mert vele a Magasságosnak kegyelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 9, 'Megtalálja kezed minden ellenségedet; jobbod megtalálja gyűlölőidet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 10, 'Tüzes kemenczévé teszed őket megjelenésed idején; az Úr az ő haragjában elnyeli őket és tűz emészti meg őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 11, 'Gyümölcsüket kiveszted e földről, és magvokat az emberek fiai közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 12, 'Mert gonoszságot terveztek ellened, csalárdságot gondoltak, de nem vihetik ki;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 13, 'Mert meghátráltatod őket, íved húrjait arczuknak feszíted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 14, 'Emelkedjél fel Uram, a te erőddel, hadd énekeljünk, hadd zengedezzük hatalmadat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, 'Az éneklőmesternek az ajjelethassakhar szerint; Dávid zsoltára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, 'Én Istenem, én Istenem, miért hagytál el engemet? Távol van megtartásomtól jajgatásomnak szava.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, 'Én Istenem, kiáltok nappal, de nem hallgatsz meg; éjjel is és nincs nyugodalmam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, 'Pedig te szent vagy, a ki Izráel dícséretei között lakozol.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, 'Benned bíztak atyáink; bíztak és te megszabadítottad őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, 'Hozzád kiáltottak és megmenekültek; benned bíztak és nem szégyenültek meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, 'De én féreg vagyok s nem férfiú; embereknek csúfja és a nép útálata.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, 'A kik engem látnak, mind csúfolkodnak rajtam, félrehúzzák ajkaikat és hajtogatják fejöket:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, 'Az Úrra bízta magát, mentse meg őt; szabadítsa meg őt, hiszen gyönyörködött benne!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, 'Mert te hoztál ki engem az anyám méhéből, és biztattál engem anyámnak emlőin.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, 'Születésem óta a te gondod voltam; anyám méhétől fogva te voltál Istenem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, 'Ne légy messze tőlem, mert közel a nyomorúság, és nincs, a ki segítsen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, 'Tulkok sokasága kerített be engem, körülfogtak engem Básán bikái.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, 'Feltátották rám szájokat, mint a ragadozó és ordító oroszlán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, 'Mint a víz, úgy kiöntettem; csontjaim mind széthullottak; szívem olyan lett, mint a viasz, megolvadt belső részeim között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, 'Erőm kiszáradt, mint cserép, nyelvem ínyemhez tapadt, és a halál porába fektetsz engemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, 'Mert ebek vettek körül engem, a gonoszok serege körülfogott; átlyukasztották kezeimet és lábaimat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, 'Megszámlálhatnám minden csontomat, ők pedig csak néznek s bámulnak rám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, 'Megosztoznak ruháimon, és köntösömre sorsot vetnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, 'De te, Uram, ne légy messze tőlem; én erősségem, siess segítségemre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, 'Szabadítsd meg lelkemet a kardtól, s az én egyetlenemet a kutyák körmeiből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, 'Ments meg engem az oroszlán torkából, és a bivalyok szarvai közül hallgass meg engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, 'Hadd hirdessem nevedet atyámfiainak, és dicsérjelek téged a gyülekezetben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, 'Ti, a kik félitek az Urat, dicsérjétek őt! Jákób minden ivadékai dicsőítsétek őt, és féljétek őt Izráel minden magzata!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, 'Mert nem veti meg és nem útálja meg a szegény nyomorúságát; és nem rejti el az ő orczáját előle, és mikor kiált hozzá, meghallgatja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, 'Felőled lesz dicséretem a nagy gyülekezetben. Az én fogadásaimat megadom azok előtt, a kik félik őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, 'Esznek a nyomorultak és megelégesznek, dicsérik az Urat, a kik őt keresik. Éljen szívetek örökké!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, 'Megemlékeznek és megtérnek az Úrhoz a föld minden határai, és leborul előtted a pogányok minden nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, 'Mert az Úré a királyi hatalom, uralkodik a pogányokon is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, 'Esznek és leborulnak a föld gazdagai mind; ő előtte hajtanak térdet, a kik a porba hullanak, és a ki életben nem tarthatja lelkét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, 'Őt szolgálják a fiak, az Úrról beszélnek az utódoknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 32, 'Eljőnek s hirdetik az ő igazságát az ő utánok való népnek, hogy ezt cselekedte!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, 'Dávid zsoltára. Az Úr az én pásztorom; nem szűkölködöm.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'Fűves legelőkön nyugtat engem, és csendes vizekhez terelget engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'Lelkemet megvidámítja, az igazság ösvényein vezet engem az ő nevéért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, 'Még ha a halál árnyékának völgyében járok is, nem félek a gonosztól, mert te velem vagy; a te veszsződ és botod, azok vigasztalnak engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'Asztalt terítesz nékem az én ellenségeim előtt; elárasztod fejem olajjal; csordultig van a poharam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'Bizonyára jóságod és kegyelmed követnek engem életem minden napján, s az Úr házában lakozom hosszú ideig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, 'Dávid zsoltára. Az Úré a föld s annak teljessége; a föld kereksége s annak lakosai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, 'Mert ő alapította azt a tengereken, és a folyókon megerősítette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, 'Kicsoda megy fel az Úr hegyére? És kicsoda áll meg az ő szent helyén?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, 'Az ártatlan kezű és tiszta szívű, a ki nem adja lelkét hiábavalóságra, és nem esküszik meg csalárdságra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, 'Áldást nyer az Úrtól, és igazságot az idvesség Istenétől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, 'Ilyen az őt keresők nemzetsége, a Jákób nemzetsége, a kik a te orczádat keresik. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, 'Ti kapuk, emeljétek fel fejeiteket, és emelkedjetek fel ti örökkévaló ajtók; hadd menjen be a dicsőség királya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, 'Kicsoda ez a dicsőség királya? Az erős és hatalmas Úr, az erős hadakozó Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, 'Ti kapuk, emeljétek fel fejeiteket, és emelkedjetek fel örökkévaló ajtók, hadd menjen be a dicsőség királya!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, 'Kicsoda ez a dicsőség királya? A seregek Ura, ő a dicsőség királya. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 1, 'Dávidé. Hozzád emelem, Uram, lelkemet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 2, 'Istenem, benned bízom; ne szégyenüljek meg; ne örüljenek rajtam ellenségeim.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 3, 'Senki se szégyenüljön meg, a ki téged vár; szégyenüljenek meg, a kik ok nélkül elpártolnak tőled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 4, 'Útjaidat, Uram, ismertesd meg velem, ösvényeidre taníts meg engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 5, 'Vezess engem a te igazságodban és taníts engem, mert te vagy az én szabadító Istenem, mindennap várlak téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 6, 'Emlékezzél meg, Uram, irgalmasságodról és kegyelmedről, mert azok öröktől fogva vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 7, 'Ifjúságomnak vétkeiről és bűneimről ne emlékezzél meg; kegyelmed szerint emlékezzél meg rólam, a te jóvoltodért, Uram!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 8, 'Jó és igaz az Úr, azért útba igazítja a vétkezőket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 9, 'Igazságban járatja az alázatosokat, és az ő útjára tanítja meg az alázatosokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 10, 'Az Úrnak minden útja kegyelem és hűség azoknak, a kik szövetségét és bizonyságait megtartják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 11, 'A te nevedért, Uram, bocsásd meg bűnömet, mert sok az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 12, 'Kicsoda az, a ki féli az Urat? Megmutatja annak az útat, a melyet válaszszon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 13, 'Annak lelke megmarad a jóban, és magzatja örökli a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 14, 'Az Úr bizodalmas az őt félőkhöz, és szövetségével oktatja őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 15, 'Szemeim mindenha az Úrra néznek, mert ő húzza ki a tőrből lábamat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 16, 'Tekints reám és könyörülj rajtam, mert árva és szegény vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 17, 'Eláradtak szívemnek szorongásai, nyomorúságaimból szabadíts meg engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 18, 'Lásd meg szegénységemet és gyötrelmemet; bocsásd meg minden bűnömet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 19, 'Lásd meg ellenségeimet, mert megsokasodtak, és gyilkos gyűlölséggel gyűlölnek engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 20, 'Őrizd meg lelkemet és szabadíts meg engem; ne szégyenüljek meg, hogy benned bíztam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 21, 'Ártatlanság és becsület védelmezzenek meg engem, mert téged várlak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 22, 'Mentsd ki, Isten, Izráelt minden bajából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 1, 'Dávidé. Ítélj meg engem, Uram! mert én ártatlanságban éltem és az Úrban bíztam ingadozás nélkül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 2, 'Próbálj meg, Uram, és kisérts meg, és vizsgáld meg veséimet és szívemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 3, 'Mert kegyelmed szemem előtt van, és hűségedben járok-kelek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 4, 'Nem ültem együtt hivalkodókkal, és alattomosokkal nem barátkoztam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 5, 'Gyűlölöm a rosszak társaságát, és a gonoszokkal együtt nem ülök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 6, 'Ártatlanságban mosom kezemet, és oltárodat gyakorlom Uram!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 7, 'Hogy hallatós szóval dicsérjelek téged, és elbeszéljem minden csodatettedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 8, 'Uram, szeretem a te házadban való lakozást, és a te dicsőséged hajlékának helyét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 9, 'Ne sorozd a bűnösökkel együvé lelkemet, sem életemet a vérszopókkal együvé,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 10, 'A kiknek kezében vétek van, és jobbjuk telve vesztegetéssel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 11, 'Én pedig ártatlanságban élek; ments meg és könyörülj rajtam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 12, 'Lábam megáll igazsággal; áldom az Urat a gyülekezetekben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, 'Dávidé. Az Úr az én világosságom és üdvösségem: kitől féljek? Az Úr az én életemnek erőssége: kitől remegjek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, 'Ha gonoszok jőnek ellenem, hogy testemet egyék: szorongatóim és elleneim – ők botlanak meg és hullanak el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, 'Ha tábor fog körül, nem fél szívem; habár had támad reám, mégis ő benne bízom én.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, 'Egyet kérek az Úrtól, azért esedezem: hogy lakhassam az Úr házában életemnek minden idejében; hogy nézhessem az Úrnak szépségét és gyönyörködhessem az ő templomában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, 'Bizony elrejt engem az ő hajlékába a veszedelem napján; eltakar engem sátrának rejtekében, sziklára emel fel engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, 'Most is felül emeli fejemet ellenségeimen, a kik körültem vannak, és én az ő sátorában örömáldozatokkal áldozom, énekelek és zengedezek az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, 'Halld meg, Uram, hangomat – hívlak! Irgalmazz nékem és hallgass meg engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, 'Helyetted mondja a szívem: Az én orczámat keressétek! A te orczádat keresem, oh Uram!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, 'Ne rejtsd el orczádat előlem; ne utasítsd el szolgádat haraggal; te voltál segítőm, ne taszíts el és ne hagyj el engem, üdvösségemnek Istene!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, 'Ha atyám és anyám elhagynának is, az Úr magához vesz engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, 'Taníts meg engem a te útadra, oh Uram! Vezérelj engem egyenes ösvényen, az én üldözőim miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, 'Ne adj át engem szorongatóim kivánságának, mert hamis tanúk támadnak ellenem, és erőszakot lihegnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, 'Bizony hiszem, hogy meglátom az Úr jóságát az élőknek földén!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, 'Várjad az Urat, légy erős; bátorodjék szíved és várjad az Urat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 1, 'Dávidé. Hozzád kiáltok, Uram, én szirtem; ne fordulj el szótlanul tőlem, hogy ne legyek, ha néma maradnál, a sírba szállókhoz hasonló.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 2, 'Halld meg esedezéseimnek szavát, mikor kiáltok hozzád, és mikor felemelem kezeimet a te szentséged lakhelye felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 3, 'Ne számlálj engem a hitetlenek és gonosztevők közé, a kik békességgel szólnak felebarátaikhoz, pedig gonoszság van szívökben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 4, 'Fizess meg nékik az ő cselekedeteik és igyekezetök rosszasága szerint; kezök munkája szerint fizess meg nékik; add meg nékik jutalmukat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 5, 'Minthogy nem figyelnek az Úr cselekedeteire és kezének munkáira, lerontja őket és föl nem építi őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 6, 'Áldott az Úr, hogy meghallgatta esedezéseimnek szavát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 7, 'Az Úr az én erőm és paizsom, ő benne bízott szívem és megsegíttettem; örvend szívem és énekemmel dicsérem őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 8, 'Az Úr az ő népének ereje, és az ő fölkentjének megtartó erőssége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 9, 'Tartsd meg a te népedet és áldd meg a te örökségedet, legeltesd és magasztald fel őket mindörökké!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 1, 'Dávid zsoltára. Adjatok az Úrnak, ti fejedelmeknek fiai, adjatok az Úrnak tiszteletet és dicséretet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 2, 'Adjátok az Úrnak neve tiszteletét, imádjátok az Urat szent ékességben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 3, 'Az Úr szava zeng a vizek fölött, a dicsőség Istene mennydörög, az Úr ott van a nagy vizek felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 4, 'Az Úr szava erős; az Úr szava fenséges.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 5, 'Az Úr szava czédrusokat tördel, összetöri az Úr a Libánon czédrusait is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 6, 'És ugrándoztatja azokat, mint a borjút, a Libánont és a Szirjónt, mint a bivalyfiat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 7, 'Az Úr szava tűzlángokat szór.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 8, 'Az Úr szava megrengeti a pusztát, megrengeti az Úr Kádesnek pusztáját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 9, 'Az Úr szava megborjaztatja a nőstény szarvasokat, lehántja az erdőket, és az ő hajlékában mindene azt mondja: dicső!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 10, 'Az Úr trónolt az özönvíz felett; így trónol az Úr, mint király, mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 11, 'Az Úr ad erőt népének, az Úr megáldja népét békességgel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 1, 'Dávid zsoltára. Templomszentelési ének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 2, 'Magasztallak Uram, hogy felemeltél engem, és nem engedted, hogy ellenségeim örüljenek rajtam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 3, 'Uram, Istenem, hozzád kiáltottam, és te meggyógyítottál engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 4, 'Uram, felhoztad a Seolból az én lelkemet, fölélesztettél a sírbaszállók közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 5, 'Zengedezzetek az Úrnak, ti hívei! Dicsőítsétek szent emlékezetét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 6, 'Mert csak pillanatig tart haragja, de élethossziglan jóakarata; este bánat száll be hozzánk, reggelre öröm.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 7, 'Azt mondtam azért én jó állapotomban: Nem rendülhetek meg soha.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 8, 'Uram, jókedvedből erősséget állítottál föl hegyemre; de elrejtéd orczádat, és megroskadtam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 9, 'Hozzád kiáltok, Uram! Az én Uramnak irgalmáért könyörgök!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 10, 'Mit használ vérem, ha sírba szállok? Dicsér-e téged a por; hirdeti-é igazságodat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 11, 'Hallgass meg, Uram, könyörülj rajtam! Uram, légy segítségem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 12, 'Siralmamat vígságra fordítottad, leoldoztad gyászruhámat, körülöveztél örömmel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 13, 'Hogy zengjen néked és el ne hallgasson felőled a dicséret: Uram, én Istenem, örökké dicsőítlek téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, 'Az éneklőmesternek, Dávid zsoltára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, 'Te benned bíztam, Uram! Ne szégyenüljek meg soha; igazságoddal szabadíts meg engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, 'Hajtsd hozzám füledet, hamar szabadíts meg; légy nékem erős kőszálam, erődített házam, hogy megtarts engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, 'Mert kősziklám és védőváram vagy te; vezess hát engem a te nevedért és vezérelj engemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, 'Ments ki engem a hálóból, a melyet titkon vetettek nékem; hiszen te vagy az én erősségem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, 'Kezedre bízom lelkemet, te váltasz meg engemet, oh Uram, hűséges Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, 'Gyűlölöm a hazug hiúságok híveit, és az Úrban bízom én.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, 'Hadd vigadjak és örüljek a te kegyelmednek, a miért meglátod nyomorúságomat és megismered a háborúságokban lelkemet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, 'És nem rekesztesz be engem ellenség kezébe, sőt tágas térre állatod lábaimat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, 'Könyörülj rajtam, Uram, mert szorongattatom; elsenyved a búbánat miatt szemem, lelkem, testem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, 'Mert bánatban enyészik életem, és sóhajtásban múlnak éveim; bűnöm miatt roskadoz erőm, és kiasznak csontjaim.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, 'Temérdek üldözőm miatt csúfsággá lettem, kivált szomszédaimé, és ismerőseimnek félelmévé; a kik az utczán látnak, elfutnak tőlem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, 'Töröltettem, akár a halott, az emlékezetből; olyanná lettem, mint az elroshadt edény.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, 'Mert hallottam sokak rágalmát, iszonyatosságot mindenfelől, a mint együtt tanácskoztak ellenem, és tervezték, hogy elrabolják lelkemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, 'De én benned bízom, Uram! Azt mondom: Te vagy Istenem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, 'Életem ideje kezedben van: szabadíts meg ellenségeim kezéből és üldözőimtől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, 'Világosítsd meg orczádat a te szolgádon, tarts meg engem jóvoltodból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, 'Uram, ne szégyenüljek meg, mivelhogy hívlak téged; a gonoszok szégyenüljenek meg és pusztuljanak a Seolba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, 'A hazug ajkak némuljanak el, a melyek vakmerően szólnak az igaz ellen, kevélységgel és megvetéssel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, 'Mily bőséges a te jóságod, a melyet fentartasz a téged félőknek, és megbizonyítasz a te benned bízókon az emberek fiai előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, 'Elrejted őket a te orczádnak rejtekében az emberek zendülései elől; sátorban őrzöd őket a perpatvarkodó nyelvektől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, 'Áldott az Úr, hogy csodálatossá tette kegyelmét rajtam, mint egy megerősített városon!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, 'Én ugyan azt gondoltam ijedtemben: Elvettettem szemeid elől; de mégis, meghallgattad esedezéseimnek szavát, mikor kiáltottam hozzád.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, 'Szeressétek az Urat mind ti ő kedveltjei; a híveket megőrzi az Úr és bőven megfizet a kevélyen cselekvőknek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 25, 'Legyetek erősek és bátorodjék a ti szívetek mindnyájan, a kik várjátok az Urat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, 'Dávid tanítása. Boldog az, a kinek hamissága megbocsáttatott, vétke elfedeztetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, 'Boldog ember az, a kinek az Úr bűnt nem tulajdonít, és lelkében csalárdság nincsen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, 'Míg elhallgatám, megavultak csontjaim a napestig való jajgatás miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, 'Míg éjjel-nappal rám nehezedék kezed, életerőm ellankadt, mintegy a nyár hevében. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, 'Vétkemet bevallám néked, bűnömet el nem fedeztem. Azt mondtam: Bevallom hamisságomat az Úrnak – és te elvetted rólam bűneimnek terhét. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, 'Azért hozzád fohászkodjék minden kegyes, alkalmas időben. Bár a nagy vizek áradnának, nem juthatnak azok el ő hozzá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, 'Te vagy oltalmam, te mentesz meg veszedelemtől; végy körül engem a szabadulás örömével! Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, 'Bölcscsé teszlek és megtanítlak téged az útra, a melyen járj; szemeimmel tanácsollak téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, 'Ne legyetek oktalanok, mint a ló, mint az öszvér, a melyeknek kantárral és zabolával kell szorítani az állát, mert nem közelít hozzád.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, 'Sok bánata van a gonosznak, de a ki bízik az Úrban, kegyelemmel veszi azt körül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, 'Örüljetek az Úrban, vigadozzatok ti igazak! Örvendezzetek mindnyájan ti egyeneslelkűek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 1, 'Örvendezzetek ti igazak, az Úrban; a hívekhez illik a dícséret.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 2, 'Dicsérjétek az Urat cziterával; tízhúrú hárfával zengjetek néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 3, 'Énekeljetek néki új éneket, lantoljatok lelkesen, harsogón.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 4, 'Mert az Úr szava igaz, és minden cselekedete hűséges.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 5, 'Szereti az igazságot és törvényt; az Úr kegyelmével telve a föld.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, 'Az Úr szavára lettek az egek, és szájának leheletére minden seregök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 7, 'Összegyűjti a tenger vizeit, mintegy tömlőbe; tárházakba rakja a hullámokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 8, 'Féljen az Úrtól mind az egész föld, rettegjen tőle minden földi lakó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 9, 'Mert ő szólt és meglett, ő parancsolt és előállott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 10, 'Az Úr elforgatja a nemzetek tanácsát, meghiúsítja a népek gondolatait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 11, 'Az Úr tanácsa megáll mindörökké, szívének gondolatai nemzedékről-nemzedékre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 12, 'Boldog nép az, a melynek Istene az Úr, az a nép, a melyet örökségül választott magának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 13, 'Az égből letekint az Úr, látja az emberek minden fiát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 14, 'Székhelyéről lenéz a föld minden lakosára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 15, 'Ő alkotta mindnyájok szivét, és jól tudja minden tettöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 16, 'Nem szabadul meg a király nagy sereggel; a hős sem menekül meg nagy erejével;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 17, 'Megcsal a ló a szabadításban, nagy erejével sem ment meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 18, 'Ámde az Úr szemmel tartja az őt félőket, az ő kegyelmében bízókat,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 19, 'Hogy kimentse lelköket a halálból, és az éhségben is eltartsa őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 20, 'Lelkünk az Urat várja, segítségünk és paizsunk ő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 21, 'Csak ő benne vigad a mi szívünk, csak az ő szent nevében bízunk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 22, 'Legyen, Uram, a te kegyelmed rajtunk, a miképen bíztunk te benned.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 1, 'Dávidé, mikor elváltoztatta értelmét Abimélek előtt, és mikor ez elűzte őt és elment.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 2, 'Áldom az Urat minden időben, dicsérete mindig ajkamon van!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 3, 'Dicsekedik lelkem az Úrban; s hallják ezt a szegények és örülnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 4, 'Dicsőítsétek velem az Urat, és magasztaljuk együtt az ő nevét!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 5, 'Megkerestem az Urat és meghallgatott engem, és minden félelmemből kimentett engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 6, 'A kik ő reá néznek, azok felvidulnak, és arczuk meg nem pirul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 7, 'Ez a szegény kiáltott, és az Úr meghallgatta, és minden bajából kimentette őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 8, 'Az Úr angyala tábort jár az őt félők körül és kiszabadítja őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 9, 'Érezzétek és lássátok meg, hogy jó az Úr! Boldog az az ember, a ki ő benne bízik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 10, 'Féljétek az Urat, ti szentjei! Mert a kik őt félik, nincs fogyatkozásuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 11, 'Az oroszlánok szűkölködnek, éheznek; de a kik az Urat keresik, semmi jót sem nélkülöznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 12, 'Jőjjetek fiaim, hallgassatok rám, megtanítlak titeket az Úr félelmére!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 13, 'Ki az az ember, a kinek tetszik az élet, és szeret napokat, hogy jót láthasson?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 14, 'Tartóztasd meg nyelvedet a gonosztól, és ajkadat a csalárd beszédtől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 15, 'Kerüld a rosszat és cselekedjél jót; keresd a békességet és kövesd azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 16, 'Az Úr szemei az igazakon vannak, és az ő fülei azoknak kiáltásán;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 17, 'Az Úr orczája pedig a gonosztevőkön van, hogy kiirtsa, emlékezetöket a földről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 18, 'Ha igazak kiáltnak, az Úr meghallgatja, és minden bajukból kimenti őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 19, 'Közel van az Úr a megtört szívekhez, és megsegíti a sebhedt lelkeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 20, 'Sok baja van az igaznak, de valamennyiből kimenti az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 21, 'Megőrzi minden csontját, egy sem töretik meg azokból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 22, 'A gonoszt gonoszság öli meg, és meglakolnak, a kik gyűlölik az igazat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 23, 'Az Úr kimenti az ő szolgái lelkét, és senki meg nem lakol, a ki ő benne bízik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 1, 'Dávidé. Perelj Uram a velem perlőkkel; harczolj a velem harczolókkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 2, 'Ragadj paizst és vértet, és kelj föl segítségemre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 3, 'Szegezz dárdát és rekeszd el üldözőim útját, mondd lelkemnek: Én vagyok segítséged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 4, 'Szégyen, gyalázat érje azokat, a kik lelkemet keresik; vettessenek hátra és piruljanak, a kik vesztemet koholják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 5, 'Legyenek olyanok, mint a polyva a szél előtt; az Úrnak angyala verdesse őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 6, 'Legyen útjok sötét, csuszamlós, s az Úrnak angyala kergesse őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 7, 'Mert ok nélkül vetették elém titkon vont hálójokat, és ok nélkül ástak vermet az én lelkemnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 8, 'Érje őt romlás váratlanul, fogja meg hálója, a melyet kivetett, essék belé a veszedelembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 9, 'Az én lelkem pedig vigad majd az Úrban, örvendezve szabadításában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 10, 'Minden tetemem ezt mondja majd: Kicsoda olyan, mint te, Uram?! A ki megszabadítod a nyomorultat a nála erősebbtől, a szegényt és szűkölködőt az ő megrablójától.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 11, 'Erőszakos tanúk állnak elő; azt kérdezik tőlem, a miről nem tudok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 12, 'Jóért roszszal fizetnek meg nékem, megrabolják lelkemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 13, 'Pedig én az ő betegségökben gyászba öltöztem, bőjttel gyötörtem lelkemet, imádságom kebelemre vissza-vissza szállt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 14, 'Mintha barátom, testvérem volna, úgy jártam-keltem érte; mintha anyámat siratnám, úgy jártam bútól meghajolva:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 15, 'Ők pedig örültek az én bukásomon és összegyűltek; összegyűltek ellenem a rágalmazók, tudtom nélkül gyaláztak és nem nyugodtak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 16, 'Ingyenélők léha csúfkodásai közt fogaikat vicsorgatva rám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 17, 'Oh Uram, meddig nézed? Szabadítsd meg lelkemet tombolásaiktól, az oroszlánkölyköktől az én egyetlenemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 18, 'Dicsérlek a nagy gyülekezetben, az erős nép között magasztallak téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 19, 'Ne örüljenek rajtam az én hazug ellenségeim, méltatlan gyűlölőim se hunyorgassanak rám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 20, 'Mert nem beszélnek békességet, hanem a kik békességesek e földön, azok ellen álnok dolgokat koholnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 21, 'Föltátották rám szájokat, azt mondták: Haha! Haha! Látta a szemünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 22, 'Láttad, oh Uram – ne hallgass, oh Uram; ne légy távol tőlem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 23, 'Serkenj föl, ébredj ítéletemre, oh Uram, Istenem, az én ügyemért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 24, 'Ítélj meg engem a te igazságod szerint, oh Uram, Istenem, hogy ne öröljenek rajtam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 25, 'Ne mondhassák szívökben: Örülj mi lelkünk! Ne mondhassák: Elnyeltük őt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 26, 'Szégyenüljenek meg, piruljanak együttesen, a kik bajomnak örülnek; szégyen és gyalázat borítsa be őket, a kik felfuvalkodtak ellenem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 27, 'Vigadjanak és örüljenek, a kik kivánják az én igazságomat, hadd mondják mindenkor: Nagy az Úr, a ki kivánja az ő szolgájának békességét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 28, 'Az én nyelvem pedig hirdetni fogja a te igazságodat, a te dicsőségedet minden napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 1, 'Az éneklőmesternek; az Úr szolgájáé, Dávidé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 2, 'A gonosznak hamissága felől így gondolkozom szívemben: nincs ő előtte isten-félelem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 3, 'Mert hízeleg néki önmagának, ha bűnét elkövetheti, ha gyűlölködhetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 4, 'Szájának beszéde hiábavalóság és hamisság; megszünt bölcs lenni és jót cselekedni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 5, 'Hiábavalóságot gondol ágyában; nem a jó útra áll, és nem veti meg a rosszat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 6, 'Uram, az égig ér a te kegyelmességed; a te hűséged a felhőkig!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 7, 'Igazságod, mint Isten hegyei; ítéleteid, mint a nagy mélységek; az embert és barmot te tartod meg, Uram!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 8, 'Oh Isten, milyen drága a te kegyelmességed; az embernek fiai a te szárnyaidnak árnyékába menekülnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 9, 'Dúslakodnak házadnak bőséges javaiban; megitatod őket gyönyörűségeid folyóvizéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 10, 'Mert nálad van az életnek forrása; a te világosságod által látunk világosságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 11, 'Terjeszd ki kegyelmességedet a te ismerőidre, és igazságodat az igaz szívűekre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 12, 'Ne támadjon engem a kevélynek lába, és ne üldözzön engem a gonosznak keze.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 13, 'Hullnak már a gonosztevők; eltaszíttatnak és nem állhatnak fel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, 'Dávidé. Ne bosszankodjál az elvetemültekre, ne irígykedjél a gonosztevőkre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, 'Mert hirtelen levágattatnak, mint a fű, s mint a gyönge növény elfonnyadnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, 'Bízzál az Úrban és jót cselekedjél; e földön lakozzál és hűséggel élj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, 'Gyönyörködjél az Úrban, és megadja néked szíved kéréseit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, 'Hagyjad az Úrra a te útadat, és bízzál benne, majd ő teljesíti.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, 'Felhozza a te igazságodat, mint a világosságot, és a te jogodat, miként a delet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, 'Csillapodjál le az Úrban és várjad őt; ne bosszankodjál arra, a kinek útja szerencsés, se arra, a ki álnok tanácsokat követ.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, 'Szünj meg a haragtól, hagyd el heveskedésedet; ne bosszankodjál, csak rosszra vinne!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, 'Mert az elvetemültek kivágattatnak; de a kik az Urat várják, öröklik a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, 'Egy kevés idő még és nincs gonosz; nézed a helyét és nincsen ott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, 'A szelidek pedig öröklik a földet, és gyönyörködnek nagy békességben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, 'Fondorkodik a gonosz az igaz ellen, és fogait csikorgatja rá:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, 'Az Úr neveti őt, mert látja, hogy eljő az ő napja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, 'Fegyvert vonnak a gonoszok; felvonják ívöket, hogy a szegényt és nyomorultat elejtsék, és leöljék az igazán élőket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, 'De fegyverök saját szívökbe hat, és ívök eltörik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, 'Jobb a kevés az igaznak, mint a sok gonosznak az ő gazdagsága.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, 'Mert a gonoszok karja eltörik, de az igazakat támogatja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, 'Jól tudja az Úr a feddhetetleneknek napjait, és hogy örökségök mindörökké meglesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, 'Nem szégyenülnek meg a veszedelmes időben, és jóllaknak az éhség napjaiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, 'De a gonoszok elvesznek, és az Úrnak ellensége, mint a liget ékessége, elmúlik, füstként múlik el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, 'Kölcsön kér a gonosz és meg nem fizet, de az igaz irgalmas és adakozó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, 'Mert a kiket ő megáld, öröklik a földet, és a kiket ő megátkoz, kivágattatnak azok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, 'Az Úr szilárdítja meg az igaz ember lépteit, és útját kedveli.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, 'Ha elesik, nem terül el, mert az Úr támogatja kezével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, 'Gyermek voltam, meg is vénhedtem, de nem láttam, hogy elhagyottá lett volna az igaz, a magzatja pedig kenyérkéregetővé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, 'Mindennapon irgalmatoskodik és kölcsön ad, és az ő magzatja áldott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, 'Kerüld a rosszat és jót cselekedjél, és megmaradsz mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, 'Mert az Úr szereti az ítéletet, és el nem hagyja az ő kegyeseit; megőrzi őket mindörökké, a gonoszok magvát pedig kiirtja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, 'Az igazak öröklik a földet, és mindvégig rajta lakoznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, 'Bölcseséget beszél az igaznak szája, és a nyelve ítéletet szól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, 'Istenének törvénye van szívében, lépései nem ingadoznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, 'Leselkedik a gonosz az igazra, és halálra keresi azt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, 'De az Úr nem hagyja azt annak kezében, sem nem kárhoztatja, mikor megítéltetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, 'Várjad az Urat, őrizd meg az ő útját; és fölmagasztal téged, hogy örököld a földet; és meglátod, a mikor kiirtatnak a gonoszok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, 'Láttam elhatalmasodni a gonoszt és szétterjeszkedett az, mint egy gazdag lombozatú vadfa;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, 'De elmult és ímé nincsen! kerestem, de nem található.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, 'Ügyelj a feddhetetlenre, nézd a becsületest, mert a jövendő a béke emberéé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, 'De a bűnösök mind elvesznek; a gonosznak vége pusztulás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, 'Az igazak segedelme pedig az Úrtól van; ő az ő erősségök a háborúság idején.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, 'Megvédi őket az Úr és megszabadítja őket; megszabadítja őket a gonoszoktól és megsegíti őket, mert ő benne bíznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 1, 'Dávid zsoltára emlékeztetőül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 2, 'Uram, haragodban ne fenyíts meg engem; felgerjedésedben ne ostorozz meg engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 3, 'Mert nyilaid belém akadtak, és kezed rám nehezült.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 4, 'Nincs épség testemben a te haragodtól; nincs békesség csontjaimban vétkeim miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 5, 'Mert bűneim elborítják fejemet; súlyos teherként, erőm felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 6, 'Megsenyvedtek, megbűzhödtek sebeim oktalanságom miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 7, 'Lehorgadtam, meggörbedtem nagyon; naponta szomorúan járok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 8, 'Mert derekam megtelt gyulladással, és testemben semmi ép sincsen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 9, 'Erőtlen és összetört vagyok nagyon, s szívem keserűsége miatt jajgatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 10, 'Uram, előtted van minden kívánságom, és nincs előled elrejtve az én nyögésem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 11, 'Szívem dobogva ver, elhágy erőm, s szemem világa – az sincs már velem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 12, 'Szeretteim és barátaim félreállanak csapásomban; rokonaim pedig messze állanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 13, 'De tőrt vetnek, a kik életemre törnek, és a kik bajomra törnek; hitványságokat beszélnek, és csalárdságot koholnak mindennap.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 14, 'De én, mint a siket, nem hallok, és olyan vagyok, mint a néma, a ki nem nyitja föl száját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 15, 'És olyanná lettem, mint az, a ki nem hall, és szájában nincsen ellenmondás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 16, 'Mert téged vártalak Uram, te hallgass meg Uram, Istenem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 17, 'Mert azt gondolom: csak ne örülnének rajtam; mikor lábam ingott, hatalmaskodtak ellenem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 18, 'És bizony közel vagyok az eleséshez, és bánatom mindig előttem van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 19, 'Sőt bevallom bűneimet, bánkódom vétkem miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 20, 'De ellenségeim élnek, erősödnek; megsokasodtak hazug gyűlölőim,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 21, 'És a kik jóért roszszal fizetnek; ellenem törnek, a miért én jóra törekszem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 22, 'Ne hagyj el Uram Istenem, ne távolodjál el tőlem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 23, 'Siess segítségemre, oh Uram, én szabadítóm!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 1, 'Az éneklőmesternek Jeduthunnak, Dávid zsoltára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 2, 'Mondám: nosza vigyázok útaimra, hogy ne vétkezzem nyelvemmel; megzabolázom szájamat, a míg előttem van a hitetlen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 3, 'Elnémultam, vesztegléssel hallgattam a jóról, de fájdalmam felzaklatódott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 4, 'Fölhevült bennem az én szívem, gondolatomban tűz gerjede fel, így szólék azért az én nyelvemmel:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 5, 'Jelentsd meg Uram az én végemet és napjaim mértékét, mennyi az? Hadd tudjam, hogy milyen múlandó vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 6, 'Ímé tenyérnyivé tetted napjaimat, és az én életem te előtted, mint a semmi. Bizony merő hiábavalóság minden ember, akárhogyan áll is! Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 7, 'Bizony árnyékként jár az ember; bizony csak hiába szorgalmatoskodik; rakásra gyűjt, de nem tudja, ki takarítja be azokat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 8, 'Most azért, mit reméljek, oh Uram?! Te benned van bizodalmam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 9, 'Ments ki engem minden álnokságomból; ne tégy engem bolondok csúfjává!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 10, 'Megnémultam, nem nyitom fel szájamat, mert te cselekedted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 11, 'Vedd le rólam a te ostorodat; kezed fenyítéke miatt elenyészem én.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 12, 'Mikor a bűn miatt büntetéssel fenyítesz valakit, elemészted, mint moly, az ő szépségét. Bizony merő hiábavalóság minden ember. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 13, 'Halld meg Uram az én könyörgésemet, figyelmezzél kiáltásomra, könyhullatásomra ne vesztegelj; mert én jövevény vagyok te nálad, zsellér, mint minden én ősöm.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 14, 'Ne nézz reám, hadd enyhüljek meg, mielőtt elmegyek és nem leszek többé!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, 'Az éneklőmesternek; Dávid zsoltára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, 'Várván vártam az Urat, és hozzám hajolt, és meghallgatta kiáltásomat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, 'És kivont engem a pusztulás gödréből, a sáros fertőből, és sziklára állította fel lábamat, megerősítvén lépteimet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, 'És új éneket adott szájamba, a mi Istenünknek dicséretét; sokan látták és megfélemlettek, és bíztak az Úrban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, 'Boldog ember az, a ki az Úrba vetette bizodalmát, és nem fordul a kevélyekhez és a hazugságra vetemedettekhez!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, 'Sokat cselekedtél te, Uram Istenem, a te csodáiddal és terveiddel mi érettünk; semmi sem hasonlítható hozzád; hirdetném és elbeszélném, de többek, semhogy elszámlálhatnám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, 'Véres áldozatot és ételáldozatot nem kedveltél; füleimet fölnyitottad; égőáldozatot és bűnért való áldozatot sem kívántál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, 'Akkor azt mondtam: Ímé jövök; a könyvtekercsben írva van felőlem,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, 'Hogy teljesítsem a te akaratodat; ezt kedvelem, én Istenem, a te törvényed keblem közepette van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, 'Vígan hirdetem az igazságosságot a nagy gyülekezetben; ímé, nem tartom vissza ajkamat, te tudod, óh Uram!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, 'Igazságosságodat nem rejtem el szívemben, elmondom a te hűségedet és segítségedet; nem titkolom el kegyelmedet és igazságodat a nagy gyülekezetben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, 'Te, Uram, ne tartsd vissza tőlem irgalmadat; kegyelmed és igazságod mindig megóvnak engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, 'Mert bajok vettek engem körül, a melyeknek számuk sincsen; utolértek bűneim, a melyeket végig sem nézhetek; számosabbak a fejem hajszálainál, és a szívem is elhagyott engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, 'Tessék Uram néked, hogy megments engemet; siess Uram segítségemre!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, 'Szégyenüljenek meg és piruljanak mind, a kik életemre törnek, hogy elragadják azt; riadjanak vissza, gyalázat érje, a kik bajomat kívánják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, 'Pusztuljanak el az ő gyalázatosságuk miatt, a kik azt mondják nékem: Hehé, hehé!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, 'Örülnek és örvendeznek majd mindazok, a kik téged keresnek; azt mondják mindenha: Magasztaltassék fel az Úr, a kik szeretik a te szabadításodat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 18, 'Rólam is, noha én szegény és nyomorult vagyok, az én Uram visel gondot. Te vagy segítségem, szabadítóm, oh Istenem, ne késsél!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 1, 'Az éneklőmesternek; Dávid zsoltára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 2, 'Boldog, a ki a nyomorultra gondol; a veszedelem napján megmenti azt az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 3, 'Az Úr megőrzi azt és élteti azt; boldog lesz e földön, és nem adhatod oda ellenségei kivánságának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 4, 'Az Úr megerősíti őt az ő betegágyán; bármilyen az ágya, megkönnyíted betegségében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 5, 'Én azt mondtam: Uram kegyelmezz nékem, gyógyítsd meg lelkemet, mert vétkeztem ellened!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 6, 'Ellenségeim rosszat mondanak felőlem: Mikor hal meg és vész ki a neve?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 7, 'Ha látogatni jön be valaki, hiábavalóságot beszél; szíve álnokságot gyűjt össze magának, kimegy az utczára és beszél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 8, 'Minden gyűlölőm együtt suttog reám, gonoszat koholnak ellenem:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 9, 'Istennek átka szállott ő reá, s mivelhogy benne fekszik, nem kél fel többé!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 10, 'Még az én jóakaróm is, a kiben bíztam, a ki kenyeremet ette, fölemelte sarkát ellenem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 11, 'De te Uram, könyörülj rajtam és emelj föl engemet, hadd fizessek meg nékik!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 12, 'Abból tudom meg, hogy kedvelsz engemet, ha ellenségem nem ujjong felettem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 13, 'Engem pedig feddhetetlenségemben támogatsz, és színed elé állatsz mindenha.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 14, 'Áldott az Úr, Izráelnek Istene öröktől fogva mindörökké. Ámen, ámen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, 'Az éneklőmesternek; Kóráh fiainak tanítása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, 'Mint a szarvas kivánkozik a folyóvizekre, úgy kivánkozik az én lelkem hozzád, oh Isten!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, 'Szomjuhozik lelkem Istenhez, az élő Istenhez; mikor mehetek el és jelenhetek meg Isten előtt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, 'Könyhullatásom volt kenyerem éjjel és nappal, mikor mindennap azt mondták nékem: „Hol van a te Istened?”');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, 'Mikor ezekről emlékezem, megkeseredem lelkemben; mert nagy csoportban vonultam ezelőtt és ujjongó örömmel és hálaadással vezettem őket, az ünneplő sokaságot, az Isten házáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, 'Miért csüggedsz el lelkem és nyughatatlankodol bennem? Bízzál Istenben, mert még hálát adok én néki az ő orczájának szabadításáért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 7, 'Istenem! elcsügged bennem az én lelkem; azért emlékezem reád a Jordán és Hermon földjéről, a Miczár hegyéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 8, 'Örvény örvényt hív elő zuhatagjaid hangjára; minden vízáradásod és hullámod összecsap fölöttem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 9, 'Nappal kiküldte kegyelmét az Úr, éjjel éneke volt velem, imádság az én életem Istenéhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 10, 'Hadd mondjam Istennek, az én kőszálamnak: Miért felejtkeztél el rólam? Miért kell gyászban járnom ellenség háborgatása miatt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 11, 'Mintha zúzódás volna csontjaimban, mikor gyaláznak engem az én szorongatóim, naponként ezt mondván nékem: Hol van a te Istened?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 12, 'Miért csüggedsz el lelkem, és miért nyughatatlankodol bennem? Bízzál Istenben, mert még hálát adok én néki, az én szabadítómnak és Istenemnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 1, 'Ítélj meg engem oh Isten! és oltalmazd meg ügyemet az irgalmatlan nemzetség ellen; az álnok és hamis embertől szabadíts meg engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 2, 'Hiszen te vagy oltalmam Istene, miért vetettél hát meg engemet? Miért kell gyászban járnom ellenség háborgatása miatt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 3, 'Küldd el világosságodat és igazságodat, azok vezessenek engem; vigyenek el a te szent hegyedre és hajlékaidba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 4, 'Hadd menjek be Isten oltárához, vígasságos örömömnek Istenéhez, és hadd dicsérjelek téged cziterával, Isten, én Istenem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 5, 'Miért csüggedsz el lelkem, miért nyughatatlankodol bennem? Bízzál Istenben, mert még hálát adok én néki, az én szabadítómnak és Istenemnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 1, 'Az éneklőmesternek; a Kóráh fiainak tanítása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 2, 'Oh Isten! füleinkkel hallottuk, atyáink beszélték el nékünk a dolgot, a melyet napjaikban, a hajdankor napjaiban cselekedtél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 3, 'Nemzeteket űztél te ki saját kezeddel, őket pedig beplántáltad; népeket törtél össze, őket pedig kiterjesztetted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 4, 'Mert nem az ő fegyverökkel szereztek földet, és nem az ő karjok segített nékik; hanem a te jobbod, a te karod és a te orczád világossága, mert kedvelted őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 5, 'Te magad vagy az én királyom oh Isten! Rendelj segítséget Jákóbnak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 6, 'Általad verjük le szorongatóinkat; a te neveddel tapodjuk le támadóinkat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 7, 'Mert nem az ívemben bízom, és kardom sem védelmez meg engem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 8, 'Hanem te szabadítasz meg minket szorongatóinktól, és gyűlölőinket te szégyeníted meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 9, 'Dicsérjük Istent mindennap, és mindörökké magasztaljuk nevedet. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 10, 'Mégis megvetettél, meggyaláztál minket, és nem vonulsz ki seregeinkkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 11, 'Megfutamítottál minket szorongatóink előtt, és a kik gyűlölnek minket, fosztogattak magoknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 12, 'Oda dobtál minket vágó-juhok gyanánt, és szétszórtál minket a nemzetek között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 13, 'Eladtad a te népedet nagy olcsón, és nem becsülted az árát magasra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 14, 'Csúfságul vetettél oda minket szomszédainknak, gúnyra és nevetségre a körültünk levőknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 15, 'Példabeszédül vetettél oda a pogányoknak, fejcsóválásra a népeknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 16, 'Gyalázatom naponta előttem van, és orczám szégyene elborít engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 17, 'A csúfolók és káromlók szaváért, az ellenség és a bosszúálló miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 18, 'Mindez utolért minket, mégsem feledtünk el téged, és nem szegtük meg a te frigyedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 19, 'Nem pártolt el tőled a mi szívünk, sem lépésünk nem tért le a te ösvényedről:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 20, 'Noha kiűztél minket a sakálok helyére, és reánk borítottad a halál árnyékát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 21, 'Ha elfeledtük volna Istenünk nevét, és kiterjesztettük volna kezünket idegen istenhez:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 22, 'Nemde kifürkészte volna ezt Isten? Mert ő jól ismeri a szívnek titkait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 23, 'Bizony te éretted gyilkoltak minket mindennapon; tekintettek bennünket, mint vágó-juhokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 24, 'Serkenj fel! Miért alszol Uram?! Kelj fel, ne vess el minket örökké!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 25, 'Miért rejted el orczádat, és felejted el nyomorúságunkat és háborúságunkat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 26, 'Bizony porba hanyatlik lelkünk, a földhöz tapad testünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 27, 'Kelj fel a mi segítségünkre, ments meg minket a te kegyelmedért!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 1, 'Az éneklőmesternek a sosannimra, Kóráh fiainak tanítása; ének a szerelmetesről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 2, 'Fölbuzog szívem szép beszédre. Mondom: művem a királynak szól. Nyelvem gyors írónak tolla.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 3, 'Szebb, szebb vagy az ember fiainál, kedvesség ömledez ajakidon, azért áldott meg az Isten örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 4, 'Kösd derekadra kardodat vitéz! Dicsőségedet és ékességedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 5, 'És ékességedben haladj diadallal az igazságért, a szelidségért és jogért, és rettenetesre tanítson meg téged a te jobb kezed.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 6, 'Nyilaid élesek; népek hullanak alád; a király ellenségeinek szívében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 7, 'Trónod oh Isten örökkévaló; igazságnak pálczája a te királyságodnak pálczája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 8, 'Szereted az igazságot, gyűlölöd a gonoszságot, azért kent fel Isten, a te Istened öröm olajával társaid fölé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 9, 'Mirrha, áloe, kácziaillatú minden öltözeted; elefántcsont palotából zeneszóval vidámítnak téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 10, 'Királyok leányai a te ékességeid; jobb kezed felől királyné áll ofiri aranyban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 11, 'Halld csak leány, nézd csak; hajtsd ide füledet! Feledd el népedet és az atyád házát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 12, 'Szépségedet a király kivánja; hiszen urad ő, hódolj hát néki!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 13, 'Tyrus leánya is, a nép dúsai, ajándékkal hizelegnek néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 14, 'Csupa ékesség a király leánya bent, vont aranyból van a ruhája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 15, 'Hímes öltözetben viszik a királyhoz, szűzek vonulnak utána, az ő társnői; néked hozzák őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 16, 'Bevezetik őket örömmel, vígsággal; bemennek a király palotájába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 17, 'Atyáid helyett fiaid lesznek, megteszed őket fejedelmekké mind az egész földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 18, 'Hadd hirdessem a te nevedet nemzedékről nemzedékre; örökkön örökké dicsérnek majd téged a népek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, 'Az éneklőmesternek, a Kóráh fiainak éneke, a halamothra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, 'Isten a mi oltalmunk és erősségünk! igen bizonyos segítség a nyomorúságban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, 'Azért nem félünk, ha elváltoznék is a föld, ha hegyek omlanának is a tenger közepébe:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, 'Zúghatnak, tajtékozhatnak hullámai; hegyek rendülhetnek meg háborgásától. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, 'Forrásainak árja megörvendezteti Isten városát, a Felségesnek szent hajlékait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, 'Az Isten ő közepette van, nem rendül meg; megsegíti Isten virradatkor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, 'Nemzetek zajongnak, országok mozognak; kiereszti hangját, megszeppen a föld.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, 'A Seregek Ura velünk van, Jákób Istene a mi várunk. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, 'Jőjjetek, lássátok az Úr tetteit, a ki pusztaságokat szerez a földön;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, 'Hadakat némít el a föld széléig; ívet tör, kopját ront, hadi szekereket éget el tűzben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, 'Csendesedjetek és ismerjétek el, hogy én vagyok az Isten! Felmagasztaltatom a nemzetek közt, felmagasztaltatom a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 12, 'A Seregek Ura velünk van, Jákób Istene a mi várunk! Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 1, 'Az éneklőmesternek, a Kóráh fiainak zsoltára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 2, 'Ti népek mind tapsoljatok, harsogjatok Istennek vígságos szóval.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 3, 'Mert az Úr felséges, rettenetes; nagy király az egész földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 4, 'Alánk veti a népeket, a nemzeteket lábaink alá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 5, 'Kiválasztja nékünk örökségünket, Jákób dicsőségét, a kit szeret. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 6, 'Felvonul Isten harsona-szónál, kürtzengés közt az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 7, 'Énekeljetek Istennek, énekeljetek; énekeljetek királyunknak, énekeljetek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 8, 'Mert az egész föld királya az Isten: énekeljetek bölcseséggel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 9, 'Isten uralkodik a nemzetek fölött; Isten ott ül az ő szentségének trónján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 10, 'Népek fejedelmei gyülekeztek össze, mint Ábrahám Istenének népe, mert Istené a földnek pajzsai; magasságos ő igen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 1, 'A Kóráh fiainak zsoltáréneke.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 2, 'Nagy az Úr és igen dicséretes a mi Istenünknek városában, az ő szentséges hegyén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 3, 'Szépen emelkedik az egész föld öröme, a Sion hegye, a szélső észak felé, a nagy királynak városa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 4, 'Isten van az ő palotáiban, ismeretes ott, mint menedék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 5, 'Mert ímé, a királyok összegyűltek, de tovatüntek együttesen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 6, 'Meglátták ők, legott elcsodálkoztak; megijedtek, elriadtak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 7, 'Rémület fogta el ott őket, fájdalom, a milyen a szülőasszonyé;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 8, 'A keleti széllel összezúzod Tarsis hajóit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 9, 'A miként hallottuk, akként láttuk a Seregek Urának városában, a mi Istenünk városában; örökre megerősítette azt az Isten! Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 10, 'A te kegyelmedről elmélkedünk oh Isten a te templomodnak belsejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 11, 'A milyen a neved oh Isten, olyan a te dicséreted a föld határáig; igazsággal teljes a te jobbod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 12, 'Örül Sion hegye, ujjonganak Júda leányai a te ítéletedért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 13, 'Vegyétek körül a Siont, kerüljétek meg azt, számláljátok meg tornyait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 14, 'Jól nézzétek meg sánczait, járjátok be palotáit, hogy elmondhassátok a jövendő nemzedéknek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 15, 'Bizony ez az Isten a mi Istenünk mindörökké, ő vezet minket mindhalálig!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 1, 'Az éneklőmesternek, a Kóráh fiainak zsoltára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 2, 'Halljátok meg ezt mind ti népek, figyeljetek mind ti, e világ lakói!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 3, 'Akár közemberek fiai, akár főemberek fiai, együtt a gazdag és szegény.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 4, 'Az én szájam bölcsességet beszél, szívemnek elmélkedése tudomány.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 5, 'Példabeszédre hajtom fülemet, hárfaszóval nyitom meg mesémet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 6, 'Miért féljek a gonoszság napjain, mikor nyomorgatóim bűne vesz körül,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 7, 'A kik gazdagságukban bíznak, és nagy vagyonukkal dicsekesznek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 8, 'Senki sem válthatja meg atyjafiát, nem adhat érte váltságdíjat Istennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 9, 'Minthogy lelköknek váltsága drága, abba kell hagynia örökre;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 10, 'Még ha örökké élne is és nem látná meg a sírgödört.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 11, 'De meglátja! A bölcsek is meghalnak; együtt vész el bolond és ostoba, és gazdagságukat másoknak hagyják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 12, 'Gondolatjok ez: az ő házok örökkévaló, lakóhelyeik nemzedékről-nemzedékre szállnak, nevöket hangoztatják a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 13, 'Pedig az ember, még ha tisztességben van, sem marad meg; hasonlít a barmokhoz, a melyeket levágnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 14, 'Ez az ő sorsuk bolondság nékik; de azért gyönyörködnek szavokban az ő követőik. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 15, 'Mint juhok, a Seolra vettetnek, a halál legelteti őket, és az igazak uralkodnak rajtok reggel; alakjokat elemészti a Seol, távol az ő lakásuktól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 16, 'Csak Isten válthatja ki lelkemet a Seol kezéből, mikor az megragad engem. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 17, 'Ne félj, ha valaki meggazdagszik, ha megöregbül házának dicsősége;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 18, 'Mert semmit sem vihet el magával, ha meghal; dicsősége nem száll le utána.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 19, 'Ha életében áldottnak vallja is magát, s ha dicsérnek is téged, hogy jól tettél magaddal:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 20, 'Mégis az ő atyáinak nemzetségéhez jut, a kik soha sem látnak világosságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 21, 'Az ember, még ha tisztességben van is, de nincs okossága: hasonlít a barmokhoz, a melyeket levágnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, 'Asáf zsoltára. Az Istenek Istene, az Úr szól, és hívja a földet a nap keltétől lenyugtáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 2, 'A Sionról, a melynek szépsége tökéletes, fényeskedik Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 3, 'Eljön a mi Istenünk és nem hallgat; emésztő tűz van előtte, s körülte erős forgószél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 4, 'Hívja az egeket onnan felül, és a földet, hogy megítélje népét:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 5, 'Gyűjtsétek elém kegyeseimet, a kik áldozattal erősítik szövetségemet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 6, 'És az egek kijelentik az ő igazságát, mert az Isten biró. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 7, 'Hallgass én népem, hadd szóljak! Te Izráel, hadd tegyek bizonyságot rólad; Isten vagyok én, a te Istened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 8, 'Nem feddlek én téged áldozataidért, és hogy égőáldozataid szüntelen előttem vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 9, 'De nem fogadhatok el tulkot a te házadból, vagy bakokat a te aklaidból;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 10, 'Mert enyém az erdőnek minden vadja, a barmok az ezernyi hegyeken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 11, 'Ismerem a hegyeknek minden szárnyasát, és a mező állatai tudva vannak nálam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 12, 'Ha megéhezném, nem mondanám meg néked, mert enyém e világ és ennek mindene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 13, 'Avagy eszem-é én a bikák húsát, és a bakoknak vérét iszom-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 14, 'Hálával áldozzál az Istennek, és teljesítsd a felségesnek fogadásidat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 15, 'És hívj segítségül engem a nyomorúság idején, én megszabadítlak téged és te dicsőítesz engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 16, 'A gonosznak pedig ezt mondja Isten: Miért beszélsz te rendeléseimről, és veszed szádra az én szövetségemet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 17, 'Hiszen te gyűlölöd a fenyítést, és hátad mögé veted rendelésimet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 18, 'Ha lopót látsz, mellé adod magad, és ha paráznákat, társalkodol velök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 19, 'A szádat gonoszságra tátod, és a nyelved csalárdságot sző.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 20, 'Leülsz és felebarátodra beszélsz, anyád fiát is megszidalmazod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 21, 'Ezeket teszed és én hallgassak? Azt gondolod, olyan vagyok, mint te? Megfeddelek téged, és elédbe sorozom azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 22, 'Értsétek meg ezt, ti Istent felejtők, hogy el ne ragadjalak menthetetlenül:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 23, 'A ki hálával áldozik, az dicsőít engem, és a ki az útra vigyáz, annak mutatom meg Istennek szabadítását.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, 'Az éneklőmesternek; Dávid zsoltára;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, 'Mikor ő hozzá ment Nátán, a próféta, minekutána Bethsabéval vétkezett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, 'Könyörülj rajtam én Istenem a te kegyelmességed szerint; irgalmasságodnak sokasága szerint töröld el az én bűneimet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, 'Egészen moss ki engemet az én álnokságomból, és az én vétkeimből tisztíts ki engemet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, 'Mert ismerem az én bűneimet, és az én vétkem szüntelen előttem forog.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, 'Egyedül te ellened vétkeztem, és cselekedtem azt, a mi gonosz a te szemeid előtt; hogy igaz légy beszédedben, és tiszta ítéletedben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, 'Ímé én vétekben fogantattam, és bűnben melengetett engem az anyám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, 'Ímé te az igazságban gyönyörködöl, a mely a vesékben van, és bensőmben bölcseségre tanítasz engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, 'Tisztíts meg engem izsóppal, és tiszta leszek; moss meg engemet, és fehérebb leszek a hónál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, 'Hallass örömet és vígasságot velem, hogy örvendezzenek csontjaim, a melyeket összetörtél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, 'Rejtsd el orczádat az én vétkeimtől, és töröld el minden álnokságomat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, 'Tiszta szívet teremts bennem, oh Isten, és az erős lelket újítsd meg bennem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, 'Ne vess el engem a te orczád elől, és a te szent lelkedet ne vedd el tőlem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, 'Add vissza nékem a te szabadításodnak örömét, és engedelmesség lelkével támogass engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, 'Hadd tanítsam a bűnösöket a te útaidra, hogy a vétkezők megtérjenek hozzád.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, 'Szabadíts meg engemet a vérontástól, oh Isten, szabadításomnak Istene! hogy harsogja nyelvem a te igazságodat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, 'Uram, nyisd meg az én ajakimat, hogy hirdesse szájam a te dicséretedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, 'Mert nem kivánsz te véresáldozatot, hogy adnék azt, égőáldozatban sem gyönyörködöl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, 'Isten előtt kedves áldozatok: a töredelmes lélek; a töredelmes és bűnbánó szívet oh Isten nem veted te meg!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 20, 'Tégy jól a te kegyelmedből a Sionnal; és építsd meg Jeruzsálem kőfalait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 21, 'Akkor kedvesek lesznek előtted az igazságnak áldozatai; az égő és egész áldozat: akkor a te oltárodon áldoznak néked tulkokkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 1, 'Az éneklőmesternek; Dávid tanítása;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 2, 'Mikor az Idumeus Dóeg eljött és hírt vitt Saulnak, és ezt mondá néki: Dávid az Akhimélek házába ment be.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 3, 'Mit dicsekedel gonoszságban, oh te magabíró? Az Istennek kegyelme szüntelen való!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 4, 'Nyelved ártalmakon elmélkedik, s olyan mint az éles olló, te álnokságnak mestere!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 5, 'Szereted a gonoszt inkább, hogy nem a jót, és a hazugságot inkább, mint igazságot szólni. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 6, 'Szeretsz minden ártalmas beszédet, és az álnok nyelvet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 7, 'Meg is ront az Isten téged, teljesen eltakarít, kigyomlál téged a te hajlékodból, és kiszaggat téged az élők földéről. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 8, 'És látják ezt az igazak, és félnek, és nevetnek rajta:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 9, 'Ímé az a férfiú, a ki nem Istent fogadta erősségévé, hanem az ő gazdagságának sokaságában bízott, és ereje az ő gonoszságában volt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 10, 'Én pedig mint zöldelő olajfa Isten házában, bízom Isten kegyelmében mind örökkön örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 11, 'Áldlak téged örökké, hogy így cselekedtél; nevedben remélek, mert jóságos vagy, a te híveid előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 1, 'Az éneklőmesternek a mahalathra, Dávid tanítása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 2, 'Ezt mondta a balgatag az ő szívében: Nincs Isten. Megromlottak és útálatos hamisságot cselekedtek, nincs a ki jót cselekedjék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 3, 'Isten letekint a mennyből az emberek fiaira, hogy meglássa, ha van-é értelmes, Istent kereső?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 4, 'Mindnyájan elhajlottak, és valamennyien megromlottak, nincsen a ki jót cselekedjék, nincsen csak egy is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 5, 'Avagy nincs értelem a hamisságnak cselekvőiben, a kik az én népemet megeszik, mintha kenyeret ennének, a kik az Istent segítségül nem hívják?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 6, 'Ott félnek nagy félelemmel, a hol nincsen félelem; mert az Isten elszéleszti azoknak tetemeit, a kik tábort járnak ellened; megszégyeníted azokat, mert az Isten megveti őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 7, 'Oh, vajha eljönne Sionból Izráelnek a szabadítás! Mikor az Úr visszahozza az ő népének foglyait, örül majd Jákób és vigad Izráel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 1, 'Az éneklőmesternek, hangszerekkel; Dávid tanítása;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 2, 'Mikor a Zifeusok eljöttek, és azt mondák Saulnak: Nem mi nálunk lappang-é Dávid?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 3, 'Isten, a te neveddel szabadíts meg engemet, és a te hatalmasságoddal állj bosszút értem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 4, 'Isten, hallgasd meg az én imádságomat, figyelmezz az én szájam beszédeire.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 5, 'Mert idegenek támadtak ellenem, és kegyetlenek keresik lelkemet, a kik nem is gondolnak Istenre. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 6, 'Ímé, Isten segítőm nékem, az Úr az én lelkemnek támogatója.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 7, 'Bosszút áll az utánam leselkedőkön; a te igazságod által rontsd meg őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 8, 'Kész szívvel áldozom néked: áldom a te nevedet, Uram, mert jó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 9, 'Mert minden nyomorúságból megszabadított engem, s megpihentette szemeimet ellenségeimen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 1, 'Az éneklőmesternek, hangszerekkel; Dávid tanítása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 2, 'Hallgasd meg, Isten, az én imádságomat, és ne rejtsd el magadat az én könyörgésem elől;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 3, 'Figyelmezz én reám és hallgass meg engemet; mert keseregve bolyongok és jajgatok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 4, 'Az ellenségnek szaváért és a hitetlenek nyomorgatásáért: mert hazugságot hárítanak reám, és nagy dühösséggel ellenkeznek velem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 5, 'Az én szívem reszket bennem, és a halál félelmei körülvettek engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 6, 'Félelem és rettegés esett én reám, és borzadály vett körül engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 7, 'Mondám: Vajha szárnyam volna, mint a galambnak! Elrepülnék és nyugodnám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 8, 'Ímé, messze elmennék és a pusztában lakoznám. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 9, 'Sietnék kiszabadulni e sebes szélből, e forgószélből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 10, 'Rontsd meg Uram, és oszlasd meg az ő nyelvöket; mert erőszakot és háborgást látok a városban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 11, 'Nappal és éjjel körüljárják azt annak kőfalainál, bent hamisság és ártalom van abban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 12, 'Veszedelem van bensejében; s nem távozik annak teréről a zsarnokság és csalárdság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 13, 'Mert nem ellenség szidalmazott engem, hisz azt elszenvedném; nem gyűlölőm emelte fel magát ellenem, hiszen elrejtettem volna magamat az elől:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 14, 'Hanem te, hozzám hasonló halandó, én barátom és ismerősöm,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 15, 'A kik együtt édes bizalomban éltünk; az Isten házába jártunk a tömegben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 16, 'A halál vegye őket körül, elevenen szálljanak a Seolba; mert gonoszság van lakásukban, kebelökben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 17, 'Én az Istenhez kiáltok, és az Úr megszabadít engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 18, 'Estve, reggel és délben panaszkodom és sóhajtozom, és ő meghallja az én szómat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 19, 'Megszabadítja lelkemet békességre a rám támadó hadtól, mert sokan vannak ellenem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 20, 'Meghallja Isten és megfelel nékik, (mivelhogy ő eleitől fogva trónol, Szela), a kik nem akarnak megváltozni és nem félik az Istent.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 21, 'Kezeit felemelte a vele békességben lévőkre; megszegte az ő szövetségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 22, 'A vajnál simább az ő szája, pedig szívében háborúság van; lágyabbak beszédei az olajnál, pedig éles szablyák azok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 23, 'Vessed az Úrra a te terhedet, ő gondot visel rólad, és nem engedi, hogy valamikor ingadozzék az igaz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 24, 'Te, Isten, a veszedelem vermébe taszítod őket; a vérszopó és álnok emberek életüknek felét sem élik meg; én pedig te benned bízom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 1, 'Az éneklőmesternek a Jónathelem rehokimra; Dávidnak miktámja; mikor megragadták őt a filiszteusok Gáthban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 2, 'Könyörülj rajtam Istenem, mert halandó tátog ellenem és mindennap hadakozván, nyomorgat engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 3, 'Ellenségeim minden napon tátognak reám: bizony sokan hadakoznak ellenem, oh magasságos Isten!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 4, 'Mikor félnem kellene is, én bízom te benned.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 5, 'Isten által dicsekedem az ő igéjével; az Istenben bizom, nem félek; ember mit árthatna nékem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 6, 'Minden nap elforgatják beszédeimet; minden gondolatjok ellenem van, ártalomra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 7, 'Egybegyűlnek, elrejtőznek, sarkaimat lesik, mert kivánják az én lelkemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 8, 'Gonoszsággal menekedhetnének? Haraggal rontsd meg, oh Isten, a népeket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 9, 'Bujdosásomnak számát jól tudod: szedd tömlődbe könnyeimet! Avagy nem tudod-é azoknak számát?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 10, 'Meghátrálnak majd ellenségeim, mikor kiáltok; így tudom meg, hogy velem van az Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 11, 'Dicsérem Istent, az ő ígéretéért, dicsérem az Urat az ő igéretéért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 12, 'Istenben bízom, nem félek; ember mit árthatna nékem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 13, 'Tartozom, oh Isten, az én néked tett fogadásaimmal; megadom néked a hálaáldozatokat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 14, 'Mert megszabadítottad lelkemet a haláltól, bizony az én lábaimat az eleséstől; hogy járjak Isten előtt az életnek világosságában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 1, 'Az éneklőmesternek az altashétre; Dávid miktámja; mikor Saul elől a barlangba menekült.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 2, 'Könyörülj rajtam, oh Isten könyörülj rajtam, mert benned bízik az én lelkem; és szárnyaid árnyékába menekülök, a míg elvonulnak a veszedelmek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 3, 'A magasságos Istenhez kiáltok; Istenhez, a ki jót végez felőlem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 4, 'Elküld a mennyből és megtart engem: meggyalázza az engem elnyelőt. Szela. Elküldi Isten az ő kegyelmét és hűségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 5, 'Az én lelkem oroszlánok között van, tűzokádók között fekszem; emberek között, a kiknek foguk dárda és nyilak, nyelvök pedig éles szablya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 6, 'Magasztaltassál fel az egek felett, oh Isten! Mind az egész földön legyen a te dicsőséged!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 7, 'Hálót készítettek lábaimnak, lelkem meggörnyedett; vermet ástak én előttem, de ők estek abba. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 8, 'Kész az én szívem, oh Isten, kész az én szívem; hadd énekeljek és zengedezzek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 9, 'Serkenj fel én dicsőségem, serkenj fel te lant és hárfa, hadd költsem fel a hajnalt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 10, 'Hálát adok néked, én Uram, a népek között, és zengedezek néked a nemzetek között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 11, 'Mert nagy az egekig a te kegyelmed, és a felhőkig a te hűséged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 12, 'Magasztaltassál fel az egek felett, oh Isten! Mind az egész földön legyen a te dicsőséged!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 1, 'Az éneklőmesternek az altashétre; Dávid miktámja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 2, 'Avagy valóban a néma igazságot szólaltatjátok-é meg? Avagy igazán ítéltek-é ti embernek fiai?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 3, 'Sőt inkább hamisságot forgattok a ti szívetekben! a ti kezeiteknek hamisságát méritek e földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 4, 'Eltértek a gonoszok fogantatásuk óta; tévelygenek a hazugok anyjok méhétől kezdve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 5, 'Mérgök olyan, mint a kígyónak mérge; mint a siket áspisé, a mely füleit bedugja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 6, 'A mely nem hallja a bűbájosoknak szavát, sem a bűvölőét, a ki bűbájakban jártas.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 7, 'Isten, rontsd meg az ő fogaikat az ő szájokban; az oroszlánoknak zápfogait törd össze, Uram!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 8, 'Olvadjanak el, folyjanak széllyel, mint a víz; ha felteszi nyilait, legyenek tompultak azok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 9, 'Legyenek mint a csiga, a mely szétfolyván, elmúlik; mint az aszszonynak idétlen szülötte, a mely nem látta a napot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 10, 'Mielőtt megéreznék fazekaitok a tövist, mind nyersen, mind égőn elragadja azt a forgószél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 11, 'Örül az igaz, mikor látja a bosszúállást; lábait mossa a gonosznak vérében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 12, 'És azt mondja az ember: Bizonyára van jutalma az igaznak; bizony van ítélő Isten e földön!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 1, 'Az éneklőmesternek az altashétre. Dávid miktámja; midőn embereket külde Saul, és őrizék az ő házát, hogy megöljék őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 2, 'Szabadíts meg engemet az én ellenségeimtől, Istenem; a reám támadóktól ments meg engemet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 3, 'Szabadíts meg engemet a gonosztevőktől, és a vérontó emberek ellen tarts meg engemet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 4, 'Mert ímé lelkem után leselkednek, egybegyűltek ellenem az erősek; a nélkül, hogy hibás vagy vétkes volnék, Uram!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 5, 'Bűnöm nélkül egybegyűlnek és készülnek ellenem: serkenj fel előmbe és lásd meg ezeket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 6, 'Te, oh Uram, Seregek Istene, Izráel Istene, serkenj fel! Büntesd meg mind e pogányokat, ne könyörülj senkin, a ki hamisságot cselekszik. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 7, 'Estenden megjelennek, ordítnak, mint az eb; körüljárják a várost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 8, 'Ímé, szájokkal csácsognak, ajkaikon szablyák vannak: hisz, úgy mond, kicsoda hallja meg?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 9, 'Te pedig, Uram, neveted őket, és megcsúfolod mind e pogány népet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 10, 'Hatalmával szemben te reád vigyázok; mert Isten az én váram.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 11, 'Előmbe jön az én kegyelmes Istenem; látnom engedi Isten az én ellenségeim romlását.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 12, 'Ne öld meg őket, hogy népem meg ne felejtkezzék; bujdosókká tedd őket a te hatalmaddal, és alázd meg őket Uram, mi paizsunk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 13, 'Szájuknak vétke az ő ajkaiknak beszéde, fogattassanak meg kevélységükben; mert csak átkot és hazugságot szólnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 14, 'Veszítsd el őket búsulásodban, veszítsd el őket, hogy ne legyenek; és tudják meg, hogy Isten uralkodik a Jákób fölött, mind a földnek határáig. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 15, 'Estenden megjelennek, ordítnak, mint az eb, körüljárják a várost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 16, 'Étel után barangolnak, és ha nem laknak jól, virrasztanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 17, 'Én pedig éneklem a te hatalmadat, és reggelenkint zengem a te kegyelmességedet; mert váram voltál és menedékem az én nyomorúságom napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 18, 'Én erősségem! Te néked éneklek, mert Isten az én váram: ő az én kegyelmes Istenem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 1, 'Az éneklőmesternek a susanheduthra, Dávidnak tanító miktámja;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 2, 'Mikor harczolt a mesopotámiai szirusokkal és a czóbai szirusokkal; és visszafordult Joáb és megverte az Edomitákat a Sóvölgyben, tizenkétezeret.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 3, 'Isten, elvetettél minket, elszélesztettél minket; megharagudtál, hozz vissza minket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 4, 'Megrendítetted ez országot, ketté szakasztottad; építsd meg romlásait, mert megindult.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 5, 'A te népeddel nehéz dolgokat láttattál: bódító borral itattál minket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 6, 'Adtál a téged félőknek zászlót, melyet felemeljenek az igazságért. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 7, 'Hogy megszabaduljanak a te kedveltjeid: segíts jobboddal és hallgass meg minket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 8, 'Az ő szent helyén mondotta Isten: Örvendezek, kiosztom Sikemet és kimérem a Szukkót völgyét:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 9, 'Enyim Gileád és enyim Manasse, Efraim az én fejemnek oltalma: Júda az én törvény-rendelőm.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 10, 'Moáb az én mosdómedenczém, Edomra vetem az én sarumat; te Filisztea nékem örülj!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 11, 'Kicsoda vezet engem az erős városba? Kicsoda kisért el Edomig engem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 12, 'Nem te-é, oh Isten, a ki megvetettél minket, s nem vonultál ki, oh Isten, a mi seregeinkkel?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 13, 'Segíts ki minket a nyomorúságból, mert emberi segítség hiábavaló.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 14, 'Istennel győzedelmet nyerünk, s ő tapodja el ellenségeinket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, 'Az éneklőmesternek hangszerre: Dávidé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, 'Hallgasd meg, oh Isten, az én kiáltásomat; figyelmezzél az én könyörgésemre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, 'E föld széléről kiáltok te hozzád; mert szívem elepedt: Vígy el engem innen a sziklára, a hova én nem jutok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, 'Mert te vagy az én menedékem, s erős tornyom az ellenség ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, 'Hadd lakozzam a te sátorodban mindörökké; hadd meneküljek a te szárnyaid árnyéka alá! Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, 'Mert te, oh Isten, meghallgattad az én fogadásaimat; a te neved tisztelőinek örökségét megadtad nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, 'Adj napokat a király napjaihoz, esztendeit nemzedékről nemzedékre nyujtsd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, 'Isten előtt lakozzék örökké; kegyelmedet és hűségedet rendeld ki, hogy őrizzék meg őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 9, 'Így éneklem majd a te nevedet szüntelen, hogy beteljesítsem az én fogadásaimat minden napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, 'Az éneklőmesternek, Jedutun szerint; Dávid zsoltára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, 'Csak Istenben nyugoszik meg lelkem; tőle van az én szabadulásom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, 'Csak ő az én kősziklám és szabadulásom; ő az én oltalmam, azért nem rendülök meg felettébb.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, 'Meddig támadtok még egy ember ellen; meddig törtök ellene valamennyien, mint meghanyatlott fal és dűlő kerítés ellen?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 5, 'Csak arról tanácskoznak, mimódon vessék őt le méltóságából; szeretik a hazugságot; szájukkal áldanak, szívükben átkoznak. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 6, 'Csak Istenben nyugodjál meg lelkem, mert tőle van reménységem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 7, 'Csak ő az én kősziklám és szabadulásom; ő az én oltalmam, azért nem rendülök meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 8, 'Istennél van szabadulásom és dicsőségem; az én erős kősziklám, az én menedékem Istenben van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 9, 'Bízzatok ő benne mindenkor, ti népek; öntsétek ki előtte szíveteket; Isten a mi menedékünk. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 10, 'Bizony hiábavalók a közembernek fiai és hazugok a főembernek fiai; ha mérőserpenyőbe vettetnek, mind alábbvalók a semminél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 11, 'Ne bízzatok zsarolt javakban, és rablott jószággal ne kevélykedjetek; a vagyonban, ha nő, ne bizakodjatok;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, 'Egyszer szólott az Isten, kétszer hallottam ugyanazt, hogy a hatalom az Istené.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 13, 'Tiéd Uram a kegyelem is. Bizony te fizetsz meg mindenkinek az ő cselekedete szerint!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, 'Dávid zsoltára, mikor a Júda pusztájában volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, 'Isten! én Istenem vagy te, jó reggel kereslek téged; téged szomjúhoz lelkem, téged sóvárog testem a kiaszott, elepedt földön, a melynek nincs vize;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, 'Hogy láthassalak téged a szent helyen, szemlélvén a te hatalmadat és dicsőségedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, 'Hiszen a te kegyelmed jobb az életnél: az én ajakim hadd dicsérjenek téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, 'Áldanálak ezért életem fogytáig; a te nevedben emelném fel kezeimet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, 'Mintha zsírral és kövérséggel telnék meg lelkem, mikor víg ajakkal dicsérhet téged az én szájam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, 'Ha reád gondolok ágyamban: őrváltásról őrváltásra rólad elmélkedem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, 'Mert segítségem voltál, és a te szárnyaidnak árnyékában örvendeztem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, 'Ragaszkodik hozzád az én lelkem; a te jobbod megtámogat engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, 'Azok pedig, a kik veszedelemre keresik lelkemet, a föld mélységeibe jutnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, 'Szablya martalékaiul esnek el, és a rókáknak lesznek eledelei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 12, 'A király pedig örvendezni fog Istenben; dicséri őt mindaz, a ki ő reá esküszik; mert bedugatik a hazugok szája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, 'Az éneklőmesternek; Dávid zsoltára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 2, 'Hallgasd meg, Isten, az én szómat, mikor panaszkodom; az ellenségtől való félelemtől mentsd meg éltemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 3, 'Rejts el engem a rosszakaróknak tanácsa elől, a gonosztevőknek gyülekezetétől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 4, 'A kik megélesítik nyelvöket, mint a szablyát; irányozzák nyilokat, keserű beszédöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 5, 'Hogy lövöldözzék titkon az ártatlant; nagy hirtelenséggel lövöldözik azt, és nem félnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 6, 'Megátalkodottak gonosz szándékukban; megegyeztek, hogy tőrt vetnek titkon, mondják: ki látja őket?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 7, 'Álnokságokat koholnak; a kikoholt tervet végrehajták; mindenikök keble és szíve kikutathatatlan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 8, 'De meglövi őket az Isten; hirtelen nyíl üt rajtok sebet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 9, 'És megejtik őket, a nyelvök lesz ellenök; iszonyodik mindenki, a ki őket látja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 10, 'Akkor megfélemlenek mind az emberek; hirdetni fogják Istennek dolgát, és megértik cselekedetét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 11, 'Örvendeni fog az igaz Istenben, és hozzá menekül; és dicsekedni fognak minden egyenesszívűek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 1, 'Az éneklőmesternek; zsoltár; Dávid éneke.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 2, 'Tied a hódolat, a dicséret, oh Isten, a Sionon; és néked teljesítik ott a fogadást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 3, 'Oh könyörgést meghallgató, hozzád folyamodik minden test.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 4, 'Bűneim erőt vettek rajtam; vétkeinket te bocsásd meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 5, 'Boldog az, a kit te kiválasztasz és magadhoz fogadsz, hogy lakozzék a te tornáczaidban; hadd teljesedjünk meg a te házadnak javaival, a te templomodnak szentségével!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 6, 'Csodálatos dolgokat szólasz nékünk a te igazságodban, idvességünknek Istene; e föld minden szélének és a messze tengernek bizodalma;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 7, 'A ki hegyeket épít erejével, körül van övezve hatalommal;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 8, 'A ki lecsillapítja a tengerek zúgását, habjaik zúgását, és a népek háborgását.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 9, 'Félnek is jeleidtől a szélek lakói; a napkelet és nyugot határait megörvendezteted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 10, 'Meglátogatod a földet és elárasztod; nagyon meggazdagítod azt. Istennek folyója tele van vizekkel; gabonát szerzesz nékik, mert úgy rendelted azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 11, 'Megitatod barázdáit, göröngyeit meglapítod; záporesővel meglágyítod azt, termését megáldod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 12, 'Megkoronázod az esztendőt jóvoltoddal, és a te nyomdokaidon kövérség fakad;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 13, 'Csepegnek a puszta legelői és a halmokat vígság övezi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 14, 'A legelők megtelnek juhokkal, és a völgyeket gabona borítja; örvendeznek és énekelnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, 'Az éneklőmesternek; zsoltár, ének. Örvendezz Istennek, oh te egész föld.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, 'Énekeljétek az ő nevének dicsőségét; dicsőítsétek az ő dicséretét!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, 'Mondjátok Istennek: Mily csudálatosak a te műveid: a te hatalmad nagy volta miatt hízelegnek néked ellenségeid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, 'Az egész föld leborul előtted; énekel néked, énekli a te nevedet. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, 'Jőjjetek és lássátok az Isten dolgait; csudálatosak az ő cselekedetei az emberek fiain.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, 'A tengert szárazzá változtatta, a folyamon gyalog mentek át: ott örvendeztünk ő benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, 'A ki uralkodik az ő hatalmával örökké, szemmel tartja a pogányokat, hogy az engedetlenek fel ne fuvalkodjanak magukban. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, 'Áldjátok népek a mi Istenünket, és hallassátok az ő dicséretének szavát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, 'A ki megeleveníti lelkünket, s nem engedi, hogy lábaink megtántorodjanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, 'Mert megpróbáltál minket, oh Isten, megtisztítottál, a mint tisztítják az ezüstöt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, 'Hálóba vittél be minket, megszorítottad derekainkat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, 'Embert ültettél fejünkre, tűzbe-vízbe jutottunk: de kihoztál bennünket bőségre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, 'Elmegyek házadba égőáldozatokkal, lefizetem néked fogadásaimat,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, 'A melyeket ajakim igértek és szájam mondott nyomorúságomban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, 'Hízlalt juhokat áldozom néked égőáldozatul, kosok jóillatú áldozatával; ökröket bakokkal együtt áldozom néked. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, 'Jőjjetek el és halljátok meg, hadd beszélem el minden istenfélőnek: miket cselekedett az én lelkemmel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, 'Hozzá kiálték az én szájammal, és magasztalás volt nyelvem alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, 'Ha hamisságra néztem volna szívemben, meg nem hallgatott volna az én Uram.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, 'Ámde meghallgatott Isten, figyelmezett könyörgésem szavára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, 'Áldott az Isten, a ki nem vetette meg könyörgésemet, és kegyelmét nem vonta meg tőlem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, 'Az éneklőmesternek, hangszerekkel; zsoltár; ének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, 'Az Isten könyörüljön rajtunk és áldjon meg minket; világosítsa meg az ő orczáját rajtunk. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, 'Hogy megismerjék e földön a te útadat, minden nép közt a te szabadításodat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, 'Dicsérnek téged a népek, oh Isten, dicsérnek téged a népek mindnyájan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, 'Örvendnek és vígadnak a nemzetek, mert igazsággal ítéled a népeket, és a nemzeteket e földön te igazgatod. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, 'Dicsérnek téged a népek, oh Isten, dicsérnek téged a népek mindnyájan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, 'A föld megadta az ő gyümölcsét: megáld minket az Isten, a mi Istenünk;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 8, 'Megáld minket az Isten, és féli őt a földnek minden határa!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 1, 'Az éneklőmesternek; Dávid zsoltára, éneke.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 2, 'Felkél az Isten, elszélednek ellenségei; és elfutnak előle az ő gyűlölői.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 3, 'A mint a füst elszéled, úgy széleszted el őket; a mint elolvad a viasz a tűz előtt, úgy vesznek el a gonoszok Isten elől;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 4, 'Az igazak pedig örvendeznek és vígadnak az Isten előtt, és ujjongnak örömmel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 5, 'Énekeljetek Istennek, zengedezzetek az ő nevének; csináljatok útat annak, a ki jön a pusztákon át, a kinek Jah a neve, és örüljetek előtte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 6, 'Árváknak atyja, özvegyeknek bírája az Isten az ő szentséges hajlékában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 7, 'Isten hozza vissza a száműzötteket, kihozza boldogságra a foglyokat; csak az engedetlenek lakoznak sivatag helyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 8, 'Oh Isten, mikor kivonultál a te néped előtt, mikor a pusztába beléptél: Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 9, 'A föld reng vala, az egek is csepegnek vala Isten előtt, ez a Sinai hegy is az Isten előtt, az Izráel Istene előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 10, 'Bő záport hintesz vala, oh Isten, a te örökségedre, s a lankadót megújítod vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 11, 'Benne tanyázott a te gyülekezeted: te szerzéd jóvoltodból a szegénynek, oh Isten!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 12, 'Az Úr ad vala szólniok az örömhírt vivő asszonyok nagy csapatának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 13, 'A seregek királyai futnak, futnak: s a házi asszony zsákmányt osztogat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 14, 'Ha cserények között hevertek is: olyanok lesztek, mint a galambnak szárnyai, a melyeket ezüst borít, vagy mint vitorla-tollai, a melyek színarany fényűek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 15, 'Mikor a Mindenható szétszórta benne a királyokat, mintha hó esett volna a Salmonon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 16, 'Isten hegye a Básán hegye; sok halmú hegy a Básán hegye;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 17, 'Mit kevélykedtek ti sok halmú hegyek? Ezt a hegyet választotta Isten lakóhelyéül; bizony ezen lakozik az Úr mindörökké!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 18, 'Az Isten szekere húszezer, ezer meg ezer; az Úr közöttük van, mint a Sinai hegyen az ő szent hajlékában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 19, 'Felmentél a magasságba, foglyokat vezettél, adományokat fogadtál emberekben: még a pártütők is ide jönnek lakni, oh Uram Isten!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, 'Áldott legyen az Úr! Napról-napra gondoskodik rólunk a mi szabadításunk Istene! Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, 'Ez a mi Istenünk a szabadításnak Istene, és az Úr Isten az, a ki megszabadít a haláltól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 22, 'Csak Isten ronthatja meg az ő ellenségeinek fejét, a bűneiben járónak üstökös koponyáját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 23, 'Azt mondta vala az Úr: Básánból visszahozlak, a tenger mélységéből is kihozlak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 24, 'Hogy lábadat veresre fessed a vérben, ebeidnek nyelve az ellenségből lakomázzék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 25, 'Látták a te bevonulásodat, oh Isten! Az én Istenem, királyom bevonulását a szentélybe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 26, 'Elől mennek vala az éneklők, utánok a húrpengetők, középen a doboló leányok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 27, 'A gyülekezetekben áldjátok az Istent, az Urat áldjátok, ti Izráel magvából valók!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 28, 'Ott a kis Benjámin, a ki uralkodik rajtok, a Júda fejedelmei és az ő gyülekezetök; a Zebulon fejedelmei és a Nafthali fejedelmei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 29, 'Istened rendelte el a te hatalmadat: erősítsd meg, oh Isten, azt, a mit számunkra készítettél!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 30, 'A te Jeruzsálem felett álló hajlékodból királyok hoznak majd néked ajándékokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 31, 'Fenyítsd meg a nádasnak vadját, a bikák csordáját a népek tulkaival egybe, a kik ezüst-rudakkal terpeszkednek; szórd szét a népeket, a kik a háborúban gyönyörködnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 32, 'Eljőnek majd a főemberek Égyiptomból; Szerecsenország hamar kinyujtja kezeit Istenhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 33, 'E földnek országai mind énekeljetek Istennek: zengjetek dicséretet az Úrnak! Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 34, 'A ki kezdettől fogva az egek egein ül; ímé, onnét szól nagy kemény szóval.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 35, 'Tegyetek tisztességet Istennek, a kinek dicsősége az Izráelen és az ő hatalma a felhőkben van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 36, 'Rettenetes vagy, oh Isten, a te szent hajlékodból; az Izráelnek Istene ád erőt és hatalmat a népnek. Áldott legyen az Isten!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 1, 'Az éneklőmesternek a sósannimra; Dávidé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 2, 'Szabadíts meg engemet, oh Isten, mert a vizek lelkemig hatottak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 3, 'Mély sárba estem be, hol meg nem állhatok; feneketlen örvénybe jutottam, és az áradat elborít engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 4, 'Elfáradtam a kiáltásban, kiszáradt a torkom; szemeim elbágyadtak, várván Istenemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 5, 'Többen vannak fejem hajszálainál, a kik ok nélkül gyűlölnek engem; hatalmasok a vesztemre törők, a kik ellenségeim alap nélkül; a mit nem ragadtam el, azt kell megfizetnem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 6, 'Oh Isten, te tudod az én balgatagságomat, és az én bűneim nyilván vannak te előtted:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 7, 'Ne szégyenüljenek meg miattam, a kik te benned remélnek, Uram, Seregeknek Ura! Ne pironkodjanak miattam, a kik téged keresnek, oh Izráelnek Istene!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 8, 'Mert te éretted viselek gyalázatot, és borítja pironság az én orczámat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 9, 'Atyámfiai előtt idegenné lettem, és anyám fiai előtt jövevénynyé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 10, 'Mivel a te házadhoz való féltő szeretet emészt engem, a te gyalázóidnak gyalázásai hullanak reám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 11, 'Ha sírok és bőjtöléssel gyötröm lelkemet, az is gyalázatomra válik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 12, 'Ha gyászruhába öltözöm, akkor példabeszédül vagyok nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 13, 'A kapuban ülők rólam szólanak, és a borozók rólam énekelnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 14, 'Én pedig néked könyörgök, oh Uram; jókedvednek idején, oh Isten, a te kegyelmed sokaságához képest hallgass meg engem a te megszabadító hűségeddel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 15, 'Ments ki engem az iszapból, hogy el ne sülyedjek; hadd szabaduljak meg gyűlölőimtől és a feneketlen vizekből;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 16, 'Hogy el ne borítson a vizek árja, és el ne nyeljen az örvény, és a veremnek szája be ne záruljon felettem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 17, 'Hallgass meg engem, Uram, mert jó a te kegyelmességed! A te irgalmasságodnak sokasága szerint tekints én reám;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 18, 'És ne rejtsd el orczádat a te szolgádtól; mert szorongattatom nagyon: siess, hallgass meg engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 19, 'Légy közel az én lelkemhez és váltsd meg azt; az én ellenségeimért szabadíts meg engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 20, 'Te tudod az én gyalázatomat, szégyenemet és pirulásomat; jól ismered minden szorongatómat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 21, 'A gyalázat megtörte szívemet és beteggé lettem; várok vala részvétre, de hiába; vigasztalókra, de nem találék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 22, 'Sőt ételemben mérget adnak vala, és szomjúságomban eczettel itatnak vala engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 23, 'Legyen az ő asztalok előttök tőrré, és a bátorságosoknak hálóvá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 24, 'Setétüljenek meg az ő szemeik, hogy ne lássanak; és az ő derekukat tedd mindenkorra roskataggá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 25, 'Öntsd ki a te haragodat reájok, és a te haragodnak búsulása érje utól őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 26, 'Legyen az ő palotájok puszta, és az ő hajlékukban ne legyen lakos;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 27, 'Mert a kit te megvertél, azt üldözik, és a tőled sujtottak fájdalmát szólják meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 28, 'Szedd össze álnokságaikat, és a te igazságodra ne jussanak el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 29, 'Töröltessenek ki az élők könyvéből, és az igazak közé ne irattassanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 30, 'Engem pedig, a ki nyomorult és szenvedő vagyok, emeljen fel, oh Isten, a te segedelmed!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 31, 'Dicsérem az Istennek nevét énekkel, és magasztalom hálaadással.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 32, 'És kedvesebb lesz az Úr előtt az ökörnél, a szarvas és hasadt körmű tuloknál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 33, 'Látják ezt majd a szenvedők és örülnek; ti Istent keresők, elevenedjék a ti szívetek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 34, 'Mert meghallgatja az Úr a szegényeket, és az ő foglyait nem veti meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 35, 'Dicsérjék őt az egek és a föld; a tengerek és a mi csak mozog azokban!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 36, 'Mert megtartja Isten a Siont, és megépíti Júdának városait; és ott lakoznak majd és bírni fogják azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 37, 'És az ő szolgáinak maradékai öröklik azt, és abban laknak majd, a kik szeretik az ő nevét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 1, 'Az éneklőmesternek, Dávidtól, emlékeztetésre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 2, 'Isten, az én szabadításomra, Uram, az én segítségemre siess!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 3, 'Szégyenüljenek meg és piruljanak, a kik életemre törnek; riadjanak vissza és gyalázat érje őket, a kik bajomat kivánják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 4, 'Hátráljanak meg gyalázatosságuk miatt, a kik azt mondják nékem: Hehé, hehé!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 5, 'Örülnek és örvendeznek majd benned mindazok, a kik keresnek tégedet, és ezt mondják majd szüntelen, a kik szeretik a te szabadításodat: Magasztaltassék fel az Isten!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 6, 'Én pedig szegény és nyomorult vagyok: siess hozzám, oh Isten; segedelmem és szabadítóm vagy te Uram: ne késsél!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 1, 'Te benned bízom, Uram! Ne szégyenüljek meg soha.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 2, 'A te igazságod szerint ments meg és szabadíts meg engem; hajtsd hozzám füledet és tarts meg engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 3, 'Légy sziklaváram, a hova menekülhessek szüntelen; rendelkezzél megtartásom felől, mert kőszálam és erősségem vagy te.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 4, 'Én Istenem, szabadíts meg engem a gonosznak kezéből; a hamisnak és kegyetlennek markából!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 5, 'Mert te vagy az én reménységem, oh Uram, Istenem, én bizodalmam gyermekségemtől fogva!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 6, 'Reád támaszkodom születésem óta; anyámnak méhéből te vontál ki engem; rólad szól az én dicséretem szüntelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 7, 'Mintegy csudává lettem sokaknak; de te vagy az én erős bizodalmam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 8, 'Megtelik szájam dicséreteddel, minden napon a te dicsőségeddel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 9, 'Ne vess el engem az én vénségemnek idején; mikor elfogy az én erőm, ne hagyj el engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 10, 'Mert felőlem szólanak elleneim, és a kik életemre törnek, együtt tanácskoznak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 11, 'Mondván: Az Isten elhagyta őt! Kergessétek és fogjátok meg, mert nincs, a ki megszabadítsa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 12, 'Oh Isten, ne távozzál el tőlem! Én Istenem, siess segítségemre!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 13, 'Szégyenüljenek meg és enyészszenek el életemnek ellenségei; borítsa szégyen és gyalázat azokat, a kik vesztemre törnek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 14, 'Én pedig szüntelen reménylek, és szaporítom minden te dicséretedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 15, 'Szájam beszéli a te igazságodat, minden nap a te szabadításodat, mert számát sem tudom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 16, 'Az Úr Istennek nagy tetteivel járok; csak a te igazságodról emlékezem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 17, 'Oh Isten, gyermekségemtől tanítottál engem; és mind mostanig hirdetem a te csudadolgaidat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 18, 'Vénségemig és megőszülésemig se hagyj el engem, oh Isten, hogy hirdessem a te karodat e nemzetségnek, és minden következendőnek a te nagy tetteidet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 19, 'Hisz a te igazságod, oh Isten, felhat az égig, mert nagyságos dolgokat cselekedtél; kicsoda hasonló te hozzád, oh Isten?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 20, 'A ki sok bajt és nyomorúságot éreztettél velünk, de ismét megelevenítesz, és a föld mélységéből ismét felhozol minket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 21, 'Megsokasítod az én nagyságomat; hozzám fordulsz és megvigasztalsz engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 22, 'Én is tisztellek téged lanttal a te hűségedért, én Istenem! Éneklek néked hárfával, oh Izráelnek szentje!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 23, 'Örvendeznek az én ajakim, hogy énekelhetek néked, és lelkem is, a melyet megváltottál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 24, 'Nyelvem is minden napon hirdeti a te igazságodat, mert megszégyenültek és gyalázattal illettettek, a kik vesztemre törnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 1, 'Salamoné. Isten, a te ítéletidet add a királynak, és a te igazságodat a király fiának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 2, 'Hadd ítélje népedet igazsággal, és a te szegényeidet méltányossággal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 3, 'Teremjenek a hegyek békességet a népnek, és a halmok igazságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 4, 'Legyen birája a nép szegényeinek, segítsen a szűkölködőnek fiain, és törje össze az erőszakoskodót.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 5, 'Féljenek téged, a míg a nap áll és a meddig a hold fénylik, nemzedékről nemzedékre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 6, 'Szálljon alá, mint eső a rétre, mint zápor, a mely megöntözi a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 7, 'Virágozzék az ő idejében az igaz és a béke teljessége, a míg nem lesz a hold.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 8, 'És uralkodjék egyik tengertől a másik tengerig, és a nagy folyamtól a föld határáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 9, 'Boruljanak le előtte a pusztalakók, és nyalják ellenségei a port.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 10, 'Tarsis és a szigetek királyai hozzanak ajándékot; Seba és Szeba királyai adománynyal járuljanak elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 11, 'Hajoljanak meg előtte mind a királyok, és minden nemzet szolgáljon néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 12, 'Mert megszabadítja a kiáltó szűkölködőt; a nyomorultat, a kinek nincs segítője.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 13, 'Könyörül a szegényen és szűkölködőn, s a szűkölködők lelkét megszabadítja;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 14, 'Az elnyomástól és erőszaktól megmenti lelköket, és vérök drága az ő szemében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 15, 'És éljen ő és adjanak néki Seba aranyából; imádkozzanak érte szüntelen, és áldják őt minden napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 16, 'Bő gabona legyen az országban a hegyek tetején is; rengjen gyümölcse, mint a Libanon, s viruljon a városok népe, mint a földnek füve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 17, 'Tartson neve mindörökké; viruljon neve, míg a nap lesz; vele áldják magokat mind a nemzetek, és magasztalják őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 18, 'Áldott az Úr Isten, Izráelnek Istene, a ki csudadolgokat cselekszik egyedül!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 19, 'Áldott legyen az ő dicsőséges neve mindörökké, és teljék be dicsőségével az egész föld. Ámen! Ámen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 20, 'Itt végződnek Dávidnak, az Isai fiának könyörgései.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, 'Aszáf zsoltára. Bizony jó Izráelhez az Isten, azokhoz, a kik tiszta szívűek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, 'De én?! Már-már meghanyatlottak lábaim; és kis híjja, hogy lépteim el nem iszamodtak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, 'Mert irígykedtem a kevélyekre, látván a gonoszok jó szerencséjét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, 'Mert halálukig nincsenek kínjaik, és az ő erejök állandó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, 'A halandók nyomorúságában nincs részök, és az emberekkel nem ostoroztatnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, 'Ezért nyakuknak ékessége kevélység, ruha gyanánt erőszak borítja őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, 'A kövérség miatt kinn ülnek az ő szemeik, elméjök gondolatjai csaponganak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, 'Gúnyolódnak és gonoszságot szólnak; elnyomásról beszélnek fennhéjázással.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, 'Az égre tátogatják szájokat, és nyelvök eljárja a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, 'Azért fordul az ő népe ide, hogy tele pohár vizet szürcsölnek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, 'És mondják: Mint tudhatná ezt az Isten, s van-é a Magasságosban értelem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, 'Ímé, ezek gonoszok, és örök biztonságban vagyont gyűjtenek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, 'Bizony hiába tartottam én tisztán szívemet, és mostam ártatlanságban kezeimet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, 'Mert nyomorgattatom minden napon, és ostoroztatom minden reggel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, 'Ha azt mondom: Ilyen módon szólok: Ímé, a te fiaid nemzedékét árulom el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, 'Gondolkodom, hogy ezt megérthessem; de nehéz dolog ez szemeimben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, 'Mígnem bemenék az Isten szent helyébe: megértém azoknak sorsát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, 'Bizony síkos földön helyezted el őket; pusztaságokra vetetted ki őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, 'Mind elpusztulnak egy szempillantásban! Elvesznek, elenyésznek a rettegéstől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, 'Mint álmot, ha felserkenünk: te Uram, ha felserkensz, úgy veted meg képöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, 'Hogyha keseregne szívem, és háborognának veséim:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, 'Akkor balgatag és tudatlan volnék én, oktalan állat volnék te irántad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, 'De én mindenkor veled vagyok, te fogod az én jobb kezemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, 'Tanácsoddal igazgatsz engem, és azután dicsőségbe fogadsz be engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, 'Kicsodám van az egekben? Náladnál egyébben nem gyönyörködöm e földön!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, 'Ha elfogyatkozik is testem és szívem: szívemnek kősziklája és az én örökségem te vagy, oh Isten, mindörökké!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, 'Mert ímé, a kik eltávoznak tőled, elvesznek; mind kiirtod azokat, a kik elhajolnak tőled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, 'De én? Isten közelsége oly igen jó nékem. Az Úr Istenben vetem reménységemet, hogy hirdessem minden te cselekedetedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 1, 'Aszáf tanítása. Miért vetettél el, oh Isten, teljesen? Miért füstölög haragod a te legelődnek juhai ellen?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 2, 'Emlékezzél meg a te gyülekezetedről, a melyet régen szerzettél és a melyet megváltottál: a te örökségednek részéről, a Sion hegyéről, a melyen lakozol!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 3, 'Lépj fel a teljes pusztaságba; mindent tönkre tett az ellenség a szent helyen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 4, 'Támadóid a te gyülekezeted hajlékában ordítanak: jeleiket tűzték fel jelekké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 5, 'Úgy tünnek fel, mint mikor valaki fejszéjét emelgeti az erdőnek sűrű fáira.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 6, 'Faragványait már mind összetördelték: fejszékkel és pőrölyökkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 7, 'Szent helyedet lángba borították; neved hajlékát földig megfertőztették.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 8, 'Ezt mondották szívökben: Dúljuk fel őket mindenestől! Felgyújtották Istennek minden hajlékát az országban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 9, 'Jeleinket nem látjuk, próféta nincs többé, és nincs közöttünk, a ki tudná: meddig tart ez?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 10, 'Meddig szidalmaz, oh Isten, a sanyargató? Örökké gyalázza-é az ellenség a te nevedet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 11, 'Miért húzod vissza kezedet, jobbodat? Vond ki kebeledből: végezz!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 12, 'Pedig Isten az én királyom eleitől fogva, a ki szabadításokat mível e föld közepette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 13, 'Te hasítottad ketté a tengert erőddel; te törted össze a czethalak fejeit a vizekben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 14, 'Te rontottad meg a leviathánnak fejét, s adtad azt eledelül a pusztai népnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 15, 'Te fakasztottad fel a forrást és patakot, te száraztottad meg az örök folyókat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 16, 'Tiéd a nappal, az éjszaka is tiéd; te formáltad a világosságot és a napot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 17, 'Te szabtad meg a földnek minden határát: a nyarat és a telet te formáltad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 18, 'Emlékezzél meg erről: ellenség szidalmazta az Urat, s bolond nép káromolta a te nevedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 19, 'Ne adjad a fenevadnak a te gerliczédnek lelkét; szegényeidnek gyülekezetéről ne feledkezzél meg végképen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 20, 'Tekints a szövetségre; mert telve vannak e földnek rejtekhelyei zsaroló tanyákkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 21, 'A megrontott ne térjen szégyenvallással vissza; a nyomorult és szűkölködő dicsérje a te nevedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 22, 'Kelj fel, oh Isten, és védd a te ügyedet; emlékezzél meg a te gyaláztatásodról, a melylyel naponként illet téged a bolond!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 23, 'Ne felejtkezzél el ellenségeidnek szaváról, és az ellened támadók háborgatásáról, a mely szüntelen nevekedik!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 1, 'Az éneklőmesternek, az altashétre, Aszáf zsoltára, ének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 2, 'Tisztelünk téged, oh Isten, tisztelünk; neved közel van, hirdetik csodatetteid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 3, 'Ha megszabom a határidőt, én méltányosan ítélek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 4, 'A föld és annak minden lakosa elcsügged; én erősítem meg annak oszlopait. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 5, 'A kérkedőknek azt mondom: Ne kérkedjetek; és a gonoszoknak: Ne emeljetek szarvat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 6, 'Ne emeljétek magasra szarvatokat, ne szóljatok megkeményedett nyakkal;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 7, 'Mert nem napkelettől, sem napnyugattól, s nem is a puszta felől támad a felmagasztalás;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 8, 'Hanem Isten a biró, a ki egyet megaláz, mást felmagasztal!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 9, 'Mert pohár van az Úr kezében, bortól pezseg, nedvvel tele; ha tölt belőle, még seprejét is iszsza és szopja a föld minden gonosztevője.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 10, 'Én pedig hirdetem ezt mindörökké, és éneket mondok a Jákób Istenének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 11, 'És a gonoszoknak szarvait mind letördelem; az igaznak szarvai pedig felmagasztaltatnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 1, 'Az éneklőmesternek hangszerekkel; Aszáf zsoltára, ének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 2, 'Ismeretes az Isten Júdában, nagy az ő neve Izráelben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 3, 'Mert hajléka van Sálemben, és lakhelye Sionban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 4, 'Ott törte össze a kézív villámait, paizst, szablyát és a hadat. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 5, 'Ragyogó vagy te, felségesebb, mint a zsákmányadó hegyek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 6, 'Kifosztattak a bátor szívűek, álmukat aluszszák, és minden hős kezének ereje veszett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 7, 'A te dorgálásodtól, oh Jákób Istene, megzsibbadt mind szekér, mind ló.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 8, 'Te, te rettenetes vagy, és ki állhat meg orczád előtt, mikor haragszol?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 9, 'Az egekből jelentetted ki ítéletedet; a föld megrettent és elcsendesedett,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 10, 'Mikor felkelt Isten az ítéletre, hogy megszabadítsa a föld minden nyomorultját! Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 11, 'Mert az emberek haragja megdicsőít téged, miután felövezed végső haragodat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 12, 'Tegyetek fogadást és adjátok meg azokat az Úrnak, a ti Isteneteknek; mindnyájan, a kik ő körülte laknak, hozzanak ajándékot a Rettenetesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 13, 'Mert a fejedelmek gőgjét megtöri, rettenetes a föld királyaihoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 1, 'Az éneklőmesternek, Jedutunnak; Aszáfé, zsoltár.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 2, 'Szavamat Istenhez emelem és kiáltok; szavamat Istenhez emelem, hogy figyelmezzen reám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 3, 'Nyomorúságom idején az Urat keresem; kezem feltartom éjjel szünetlenül; lelkem nem akar vigasztalást bevenni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 4, 'Istenről emlékezem és sóhajtok; róla gondolkodom, de elepedt az én lelkem. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 5, 'Szemeimet ébren tartod; hánykolódom, de nem szólhatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 6, 'Elmélkedem a régi napokról, a hajdankor éveiről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 7, 'Megemlékezem éjjel az én énekeimről; szívemben elgondolkodom és azt kutatja lelkem:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 8, 'Avagy mindörökké elvet-é az Úr? és nem lesz-é többé jóakaró?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 9, 'Avagy végképen elfogyott-é az ő kegyelme? vagy megszűnik-é igérete nemzedékről nemzedékre?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 10, 'Avagy elfelejtkezett-é könyörülni Isten? avagy elzárta-é haragjában az ő irgalmát? Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 11, 'És mondám: Ez az én betegségem, hogy a Fölségesnek jobbja megváltozott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 12, 'Megemlékezem az Úrnak cselekedeteiről, sőt megemlékezem hajdani csodáidról;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 13, 'És elmélkedem minden cselekedetedről, és tetteidről gondolkozom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 14, 'Oh Isten, a te utad szentséges; kicsoda olyan nagy Isten, mint az Isten?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 15, 'Te vagy az Isten, a ki csodát mívelsz; megmutattad a népek között a te hatalmadat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 16, 'Megváltottad népedet karoddal a Jákób és a József fiait. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 17, 'Láttak téged a vizek, oh Isten, láttak téged a vizek és megfélemlének; a mélységek is megrázkódának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 18, 'A felhők vizet ömlesztének; megzendülének a fellegek, és a te nyílaid széllyel futkostanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 19, 'Mennydörgésed zúgott a forgószélben; villámlásaid megvilágosították a mindenséget; megrázkódott és megindult a föld.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 20, 'Utad a tengeren volt és ösvényed a nagy vizeken; és nyomaid nem látszottak meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 21, 'Vezetted mint nyájat, a te népedet, Mózesnek és Áronnak kezével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 1, 'Aszáf tanítása. Figyelj én népem az én tanításomra; hajtsátok füleiteket számnak beszédeire.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 2, 'Megnyitom az én számat példabeszédre; rejtett dolgokat szólok a régi időből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 3, 'A miket hallottunk és tudunk; és a miket atyáink beszéltek nékünk,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 4, 'Nem titkoljuk el azokat az ő fiaiktól; a jövő nemzedéknek is elbeszéljük az Úr dicséretét, hatalmát és csodáit, a melyeket cselekedett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 5, 'Mert bizonyságot állított Jákóbban, és törvényt rendelt Izráelben; a melyek felől megparancsolta atyáinknak, hogy megtanítsák azokra fiaikat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 6, 'Hogy megtudja azokat a jövő nemzedék, a fiak, a kik születnek; és felkeljenek és hirdessék azokat fiaiknak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 7, 'Hogy Istenbe vessék reménységüket és el ne felejtkezzenek Isten dolgairól, hanem az ő parancsolatait megtartsák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 8, 'Hogy ne legyenek olyanok, mint apáik: szilaj és makacs nemzedék, olyan nemzedék, a melynek szíve nem volt szilárd, és lelke sem volt hű Isten iránt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 9, 'Efraim fiai, a fegyveres íjászok hátat fordítottak az ütközet napján;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 10, 'Nem őrizték meg az Isten szövetségét, és nem akartak járni az ő törvényében;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 11, 'Sőt elfelejtkeztek az ő tetteiről, csodáiról, a melyeket mutatott nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 12, 'Apáik előtt csodát mívelt Égyiptom földjén, a Czoán mezején.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 13, 'Ketté választotta a tengert s átvitte őket; és felállította a vizeket fal gyanánt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 14, 'Vezette őket nappal felhőben, és egész éjen át tűznek világosságában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 15, 'Sziklákat hasított meg a pusztában, és inniok adott bőségesen, akárcsak a mélységes vizekből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 16, 'Patakokat fakasztott a kősziklából, és folyamok módjára vizeket ömlesztett:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 17, 'Mégis folyvást vétkeztek ellene, és haragították a Felségest a pusztában;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 18, 'És megkísérték Istent az ő szívökben, enni valót kérvén az ő kivánságuk szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 19, 'És szólának Isten ellen, mondván: Avagy tudna-é Isten asztalt teríteni a pusztában?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 20, 'Ímé, megcsapta a kősziklát és víz ömlött és patakok özönlöttek; de vajjon tud-é kenyeret is adni? avagy készíthet-é húst az ő népének?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 21, 'Meghallotta az Úr és megharagudott ezért, és tűz gyulladt fel Jákób ellen, és harag gerjedt fel Izráel ellen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 22, 'Mert nem hittek Istenben, és nem bíztak az ő segedelmében,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 23, 'És ráparancsolt a felhőkre ott fenn, és az egek ajtait megnyitotta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 24, 'És hullatott reájuk mannát eledelül, és mennyei gabonát adott nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 25, 'Angyalok kenyerét ette az ember, bőséggel vetett nékik eleséget,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 26, 'Megindítá a keleti szelet az egekben, és elhozá erejével a déli szelet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 27, 'És hullata rájuk annyi húst, mint a por, és annyi madarat, mint a tenger fövénye.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 28, 'És leszállítá azokat az ő táboruk közepére, az ő sátoraikhoz köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 29, 'Evének azért és igen megelégedének, és a mit kivántak, azt hozá nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 30, 'Még fel sem hagytak a kivánságukkal; az étel még a szájukban vala:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 31, 'Mikor az Isten haragja felgerjede ellenök, és főbbjeik közül sokakat megöle, és Izráelnek ifjait levágá;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 32, 'Mindamellett is újra vétkezének, és nem hivének az ő csodadolgaiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 33, 'Azért hiábavalóságban töltette el napjaikat, éveiket pedig rettegésben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 34, 'Ha ölte őket, hozzá fordultak, megtértek és Istent keresék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 35, 'És eszökbe vevék, hogy Isten az ő sziklájok, és a felséges Isten az ő megváltójok;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 36, 'És hízelkedének néki szájokkal, nyelvökkel pedig hazudozának néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 37, 'De szívök nem volt tökéletes iránta, és nem voltak hűségesek az ő szövetségéhez;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 38, 'Ő azonban irgalmas és bűnbocsátó, nem semmisít meg, sőt sokszor elfordítja haragját, és nem önti ki teljes búsulását.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 39, 'Azért eszébe vevé, hogy test ők, és olyanok, mint az ellebbenő szél, a mely nem tér vissza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 40, 'Hányszor keserítették őt a pusztában, hányszor illették fájdalommal a kietlenben?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 41, 'És újra kísértették az Istent, és ingerelték Izráel szentjét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 42, 'Nem emlékeztek meg az ő kezéről, sem a napról, a melyen megváltotta őket a nyomorgatótól;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 43, 'Midőn kitűzte jeleit Égyiptomban, és csodáit a Czoán mezején.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 44, 'És vérré változtatta folyóikat, hogy nem ihatták patakjaikat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 45, 'Legyeket bocsáta reájok, a melyek emészték őket, és békát, a mely pusztítá őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 46, 'Odaadta termésöket a szöcskének, s munkájuk gyümölcsét a sáskának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 47, 'Jégesővel pusztítá el szőlőjüket, s figefáikat kőesővel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 48, 'Odaveté barmaikat a jégesőnek, marháikat pedig a mennyköveknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 49, 'Rájok bocsátá haragjának tüzét, mérgét, búsulását és a szorongatást: a gonosz angyalok seregét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 50, 'Utat tört haragjának, s nem tartotta meg a haláltól lelköket, és életöket döghalálnak veté.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 51, 'És megöle minden elsőszülöttet Égyiptomban, az erő zsengéjét Khám sátoraiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 52, 'Elindítá mint juhokat, az ő népét, s vezeté őket, mint nyájat a pusztában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 53, 'És vezeté őket biztonságban, és nem félének, ellenségeiket pedig elborítá a tenger.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 54, 'És bevivé őket az ő szent határába, arra a hegyre, a melyet szerzett az ő jobbkezével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 55, 'És kiűzé előlük a pogányokat, és elosztá nékik az örökséget sorsvetéssel; és letelepíté azok sátoraiban az Izráel törzseit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 56, 'De megkisérték és megharagíták a magasságos Istent, és nem őrizék meg bizonyságait;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 57, 'Elfordulának ugyanis és hűtlenek levének, mint apáik; visszafelé fordulának, mint a csalfa kézív.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 58, 'Haragra ingerelték őt magaslataikkal, és bosszantották faragott bálványaikkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 59, 'Meghallá ezt Isten és felgerjede; és az Izráelt felette megútálá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 60, 'És elveté magától Silói hajlékát, a sátort, a melyben lakott vala az emberek között;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 61, 'Sőt fogságba viteté erejét, dicsőségét pedig ellenség kezébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 62, 'És fegyver alá rekeszté az ő népét; és az ő öröksége ellen felgerjede.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 63, 'Ifjait tűz emészté meg, és szüzei nem énekeltettek meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 64, 'Papjai fegyver miatt hullottak el, és özvegyei nem végezheték a siratást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 65, 'Akkor felserkene az Úr, mintegy álomból; mint hős, a ki bortól vigadoz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 66, 'És visszaveré ellenségeit; s örök gyalázatot vete reájok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 67, 'Azután megútálá a József sátorát, és nem választá Efraim törzsét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 68, 'Hanem a Júda törzsét választá; a Sion hegyét, a melyet szeret.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 69, 'És megépíté szent helyét, mint egy magas várat; mint a földet, a melyet örök időre fundált.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 70, 'És kiválasztá Dávidot, az ő szolgáját, és elhozá őt a juhok aklaiból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 71, 'A szoptatós juhok mellől hozá el őt, hogy legeltesse Jákóbot, az ő népét, és Izráelt, az ő örökségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 72, 'És legelteté őket szívének tökéletessége szerint, és vezeté őket bölcs kezeivel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 1, 'Aszáf zsoltára. Oh Isten, pogányok jöttek be örökségedbe, megfertőztették szent templomodat, Jeruzsálemet kőhalommá tették.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 2, 'Szolgáid holttestét az ég madarainak adták eledelül, szenteid húsát a föld vadjainak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 3, 'Ontották véröket, mint a vizet Jeruzsálem körül, s nem volt, a ki eltemette volna őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 4, 'Gyalázattá lettünk szomszédaink előtt, csúfságul és nevetségül a körültünk lakóknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 5, 'Meddig haragszol Uram, szüntelen? meddig gerjedez féltő szerelmed, mint a tűz?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 6, 'Ontsd ki haragodat a pogányokra, a kik nem ismernek téged, és az országokra, a melyek nem hívják segítségül a te nevedet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 7, 'Mert megemésztették Jákóbot, és hajlékát elpusztították.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 8, 'Ne emlékezzél meg rovásunkra elődeink vétkéről; siess elénk irgalmasságoddal, mert megnyomorodunk nagyon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 9, 'Segíts meg bennünket, szabadító Istenünk, a te nevednek dicsőségéért; ments meg minket és bocsásd meg vétkeinket a te nevedért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 10, 'Minek mondanák a pogányok: Hol az ő Istenök? Legyen nyilvánvaló a pogányokon szemeink láttára a te szolgáid kiontott véréért való bosszúállásod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 11, 'Jusson elődbe a foglyok könyörgése; karod hatalmával tartsd meg a halálnak eme fiait;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 12, 'És fizess meg szomszédaink keblébe hétszeresen a gyalázatért, a melylyel illettek téged, oh Uram!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 13, 'Mi pedig, a te néped és a te legelőd nyája, hálát adunk néked mindörökké, s nemzedékről-nemzedékre hirdetjük a te dicséretedet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 1, 'Az éneklőmesternek a sosannim-éduthra; Aszáf zsoltára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 2, 'Oh Izráelnek pásztora, hallgass meg, a ki vezérled Józsefet, mint juhnyájat; a ki Kérubokon ülsz, jelenj meg fényeddel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 3, 'Efraim, Benjámin és Manasse előtt támaszd fel a te hatalmadat, és jőjj el, hogy szabadíts meg minket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 4, 'Oh Isten, állíts helyre minket, és világoltasd a te orczádat, hogy megszabaduljunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 5, 'Seregeknek Ura, Istene: meddig haragszol a te népednek könyörgésére?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 6, 'Könyhullatásnak kenyerével éteted őket, s könyhullatások árjával itatod meg őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 7, 'Perpatvarrá tevél minket szomszédaink között, és a mi ellenségeink csúfkodnak rajtunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 8, 'Seregek Istene, állíts helyre minket; világoltasd a te orczádat, hogy megszabaduljunk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 9, 'Égyiptomból szőlőt hozál ki, kiűzéd a pogányokat és azt elültetéd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 10, 'Helyet egyengettél előtte, és gyökeret eresztett, és ellepé a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 11, 'Hegyeket fogott el az árnyéka, és a vesszei olyanok lettek, mint az Isten czédrusfái.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 12, 'Sarjait a tengerig ereszté, és hajtásait a folyamig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 13, 'Miért rontottad el annak gyepűit, hogy szaggathassa minden járókelő?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 14, 'Pusztítja azt a vaddisznó, és legeli a mezei vad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 15, 'Oh Seregek Istene! kérlek, térj vissza, tekints alá az egekből és lásd és tekintsd meg e szőlőtőt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 16, 'És a csemetét, a mit jobbod ültetett, a sarjat, melyet felneveltél!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 17, 'Elégett a tűzben, levágatott; arczod haragjától elvesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 18, 'Legyen a te kezed a te jobbodnak férfián, és az embernek fián, a kit megerősítettél magadnak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 19, 'Hogy el ne térjünk tőled. Eleveníts meg minket és imádjuk a te nevedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 20, 'Seregek Ura, Istene! állíts helyre minket; világoltasd a te orczádat, hogy megszabaduljunk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 1, 'Az éneklőmesternek, a gittithre. Aszáfé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 2, 'Örvendezzetek Istennek, a mi erősségünknek; ujjongjatok a Jákób Istenének!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 3, 'Dalt zengjetek és dobot pergessetek, gyönyörű hárfát cziterával együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 4, 'Fújjatok kürtöt új holdra, holdtöltekor, a mi ünnepünk napján;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 5, 'Mert végzett dolog ez Izráelnél, a Jákób Istenének rendelése.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 6, 'Bizonyságul tette ő a József nemzetségében, a mikor kijött Égyiptom földe ellen. Nyelvet hallék ott, a mit nem tudtam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 7, 'Megszabadítottam a tehertől az ő vállát, kezei megmenekültek a kosártól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 8, 'A nyomorúságban segítségül hívtál és én megszabadítottalak téged; meghallgattalak téged a mennydörgésnek rejtekében; megpróbáltalak téged a versengések vizénél. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 9, 'Hallgass én népem, hadd tegyek bizonyságot ellened! Oh Izráel, ha te meghallgatnál engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 10, 'Ne legyen te nálad idegen isten, és az idegen isten előtt meg ne hajolj!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 11, 'Én, az Úr vagyok a te Istened, a ki kihoztalak téged Égyiptom földéről: nyisd szét a te szájad és betöltöm azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 12, 'De nem hallgatott népem az én szómra, és Izráel nem engedelmeskedett nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 13, 'Ott hagytam azért őt szívöknek keménységében, hogy járjanak a magok tanácsa szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 14, 'Oh, ha az én népem hallgatna reám, s Izráel az én utaimon járna!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 15, 'Legott megaláznám ellenségeit, s szorongatói ellen fordítanám kezem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 16, 'Az Úrnak gyűlölői hízelegnének néki, és örökkévaló volna az ő idejök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 17, 'És ő megelégítené őt java búzával, és sziklából folyó mézzel töltenélek be téged!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, 'Aszáf zsoltára. Isten áll az Istennek gyülekezetében, ítél az istenek között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, 'Meddig ítéltek még hamisan, és emelitek a gonoszok személyét? Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, 'Ítéljetek a szegénynek és árvának; a nyomorultnak és elnyomottnak adjatok igazságot!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, 'Mentsétek meg a szegényt és szűkölködőt; a gonoszok kezéből szabadítsátok ki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, 'Nem tudnak, nem értenek, setétségben járnak; a földnek minden fundamentoma inog.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, 'Én mondottam: Istenek vagytok ti és a Felségesnek fiai ti mindnyájan:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, 'Mindamellett meghaltok, mint a közember, és elhullotok, mint akármely főember.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, 'Kelj fel, oh Isten, ítéld meg a földet, mert néked jutnak örökségül minden népek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 1, 'Ének; Aszáf zsoltára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 2, 'Isten, ne vesztegelj, ne hallgass és ne nyugodjál, Isten!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 3, 'Mert ímé, háborognak ellenségeid, s gyűlölőid fejöket emelik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 4, 'Néped ellen álnok tanácsot gondolnak s védenczeid ellen terveket szőnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 5, 'Ezt mondják: Jertek, veszessük el őket, hogy ne legyenek nemzet, hogy ne emlegessék többé Izráel nevét!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 6, 'Mert tanácskoztak együtt, egy szívvel; szövetséget kötöttek ellened:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 7, 'Az Edomiták és Ismáeliták sátrai, a Moábiták és Hagarénusok;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 8, 'A Gebaliták, Ammoniták és Amálekiták, a Filiszteusok Tyrus lakosaival együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 9, 'Az asszir is szövetkezett velök, segítőjévé lettek a Lót fiainak. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 10, 'Úgy bánj velök, mint Midjánnal, mint Siserával, mint Jábinnal a Kison patakjánál!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 11, 'A kik elvesztek vala Endornál, és a föld szemetjévé lőnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 12, 'Tedd őket, fejedelmöket olyanokká, mint Orebet s mint Zeébet, Zebahot és Szalmunát, minden felkentjökkel,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 13, 'A kik ezt mondták: Foglaljuk el magunknak az Isten hajlékait!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 14, 'Én Istenem! Tedd őket olyanokká, a milyen a porfelhő, és a milyen a polyva a szél előtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 15, 'Olyanokká, mint a tűz, a mely meggyújtja az erdőt, és mint a láng, a mely elégeti a hegyeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 16, 'Így kergesd őket a te szélvészeddel, és forgószeleddel így rettentsd őket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 17, 'Töltsd el orczájukat gyalázattal, hogy keressék Uram a te nevedet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 18, 'Szégyenüljenek meg és rémüljenek el örökké, és piruljanak és pusztuljanak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 19, 'Hogy megtudják, hogy te, a kinek neve Jehova, egymagad vagy felséges Isten az egész földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, 'Az éneklőmesternek, a gittitre; Kóráh fiainak zsoltára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, 'Mily szerelmetesek a te hajlékaid, Seregeknek Ura!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, 'Kivánkozik, sőt emésztődik lelkem az Úrnak tornáczai után; szívem és testem ujjongnak az élő Isten felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, 'A veréb is talál házat, és a fecske is fészket magának, a hová fiait helyezhesse, – a te oltáraidnál, oh Seregeknek Ura, én Királyom és én Istenem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, 'Boldogok, a kik lakoznak a te házadban, dicsérhetnek téged szüntelen! Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, 'Boldog ember az, a kinek te vagy erőssége, s a te ösvényeid vannak szívében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, 'Átmenvén a Siralom völgyén, forrássá teszik azt; bizony áldással borítja el korai eső.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, 'Erőről erőre jutnak, míg megjelennek Isten előtt a Sionon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, 'Uram, Seregeknek Istene! hallgasd meg az én könyörgésemet; hallgasd meg Jákóbnak Istene! Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, 'Mi paizsunk! Tekints alá, oh Isten, és lásd meg a te felkented orczáját!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, 'Mert jobb egy nap a te tornáczaidban, hogysem ezer másutt; inkább akarnék az én Istenem házának küszöbén ülni, hogysem lakni a gonosznak sátorában!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, 'Mert nap és paizs az Úr Isten; kegyelmet és dicsőséget ád az Úr, nem vonja meg a jót azoktól, a kik ártatlanul élnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 13, 'Seregeknek Ura! Boldog ember az, a ki bízik benned.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 1, 'Az éneklőmesternek, Kóráh fiainak zsoltára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 2, 'Jóakarattal voltál Uram a te földedhez. Visszahoztad a Jákób nemzetségéből való foglyokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 3, 'Elengedted népednek álnokságát, elfedezted minden bűnüket. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 4, 'Elhárítottad róluk minden búsulásod, elfordítottad haragod gerjedezését.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 5, 'Hozz vissza bennünket szabadításunk Istene, és szüntesd meg ellenünk való bosszankodásodat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 6, 'Avagy mindörökké haragszol-é ránk? Nemzedékről nemzedékre tartod-é haragod?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 7, 'Avagy nem elevenítesz-é meg minket ismét, hogy néped örvendezzen benned?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 8, 'Mutasd meg nékünk Uram a te kegyelmedet, és a te szabadításodat adjad mi nékünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 9, 'Hadd halljam meg: mit szól az Úr Isten! Kétségnélkül békességet szól az ő népének és kegyeltjeinek, hogy vissza ne térjenek a bolondságra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 10, 'Bizonyára közel van az ő szabadítása az őt félőkhöz, hogy dicsőség lakozzék a mi földünkön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 11, 'Irgalmasság és hűség összetalálkoznak, igazság és békesség csókolgatják egymást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 12, 'Hűség sarjad a földből, és igazság tekint alá az égből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 13, 'Az Úr is megadja a jót, és földünk is megtermi gyümölcsét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 14, 'Igazság jár előtte és követi őt az ő lépéseinek útján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 1, 'Dávid imádsága. Hajtsd hozzám Uram füledet, hallgass meg engem, mert nyomorult és szegény vagyok én!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 2, 'Tartsd meg életemet, mert kegyes vagyok én; mentsd meg én Istenem a te szolgádat, a ki bízik benned.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 3, 'Könyörülj én rajtam Uram, mert hozzád kiáltok minden napon!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 4, 'Vidámítsd meg a te szolgádnak lelkét, mert hozzád emelem fel Uram lelkemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 5, 'Mert te Uram jó vagy és kegyelmes, és nagy irgalmasságú mindazokhoz, a kik hozzád kiáltanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 6, 'Figyelmezzél Uram az én imádságomra, és hallgasd meg az én könyörgésemnek szavát!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 7, 'Nyomorúságomnak idején hozzád kiáltok, mert te meghallgatsz engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 8, 'Nincsen Uram hozzád hasonló az istenek között, és nincsenek hasonlók a te munkáidhoz!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 9, 'Eljőnek a népek mind, a melyeket alkottál, és leborulnak előtted Uram, és dicsőítik a te nevedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 10, 'Mert nagy vagy te és csodadolgokat mívelsz; csak te vagy Isten egyedül!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 11, 'Mutasd meg nékem a te útadat, hogy járhassak a te igazságodban, és teljes szívvel féljem nevedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 12, 'Dicsérlek téged Uram, Istenem, teljes szívemből, és dicsőítem a te nevedet örökké!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 13, 'Mert nagy én rajtam a te kegyelmed, és kiszabadítottad lelkemet a mélységes pokolból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 14, 'Isten! Kevélyek támadtak fel ellenem, és kegyetlenek serege keresi lelkemet, a kik meg sem gondolnak téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 15, 'De te Uram, könyörülő és irgalmas Isten vagy, késedelmes a haragra, nagy kegyelmű és igazságú!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 16, 'Tekints reám és könyörülj rajtam! Add a te erődet a te szolgádnak, és szabadítsd meg a te szolgálóleányodnak fiát!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 17, 'Adj jelt nékem javamra, hogy lássák az én gyűlölőim és szégyenüljenek meg, a mikor te Uram megsegítesz és megvigasztalsz engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 1, 'Ének. A Kóráh fiainak zsoltára. A szent hegyeken vetette meg az ő fundamentomát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 2, 'Szereti az Úr Sionnak kapuit, jobban mint Jákóbnak minden hajlékát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 3, 'Dicsőséges dolgokat beszélnek felőled, te Istennek városa! Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 4, 'Előszámlálom Égyiptomot és Bábelt, mint ismerőimet. Ímé Filisztea és Tyrus Kússal együtt: ez ott született.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 5, 'És ezt mondják a Sion felől: Mind ez, mind amaz ott született, és ő, a Felséges, erősíti azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 6, 'Az Úr beírván, feljegyzi a népet: ez ott született! Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 7, 'És tánczolva énekelik: minden forrásaim te benned vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 1, 'Ének. A Kóráh fiainak zsoltára. Az éneklőmesternek a Mahalath-lehannóthra. Az Ezrahita Hémán tanítása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 2, 'Uram, szabadításomnak Istene! Nappal kiáltok, éjjelente előtted vagyok:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 3, 'Jusson elődbe imádságom, hajtsad füled az én kiáltozásomra!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 4, 'Mert betelt a lelkem nyomorúságokkal, és életem a Seolig jutott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 5, 'Hasonlatossá lettem a sírba szállókhoz; olyan vagyok, mint az erejevesztett ember.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 6, 'A holtak közt van az én helyem, mint a megölteknek, a kik koporsóban feküsznek, a kikről többé nem emlékezel, mert elszakasztattak a te kezedtől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 7, 'Mély sírba vetettél be engem, sötétségbe, örvények közé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 8, 'A te haragod reám nehezedett, és minden haboddal nyomtál engem. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 9, 'Elszakasztottad ismerőseimet tőlem, útálattá tettél előttök engem; berekesztettem és ki nem jöhetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 10, 'Szemem megsenyvedett a nyomorúság miatt; kiáltalak téged Uram minden napon, hozzád terjengetem kezeimet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 11, 'Avagy a holtakkal teszel-é csodát? Felkelnek-é vajjon az árnyak, hogy dicsérjenek téged? Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 12, 'Beszélik-é a koporsóban a te kegyelmedet, hűségedet a pusztulás helyén?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 13, 'Megtudhatják-é a sötétségben a te csodáidat, és igazságodat a feledékenység földén?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 14, 'De én hozzád rimánkodom, Uram, és jó reggel elédbe jut az én imádságom:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 15, 'Miért vetsz el hát Uram engem, és rejted el orczádat én tőlem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 16, 'Nyomorult és holteleven vagyok ifjúságomtól kezdve; viselem a te rettentéseidet, roskadozom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 17, 'Általmentek rajtam a te búsulásaid; a te szorongatásaid elemésztettek engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 18, 'Körülvettek engem, mint a vizek egész napon; együttesen körülöveztek engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 19, 'Elszakasztottál tőlem barátot és rokont; ismerőseim a – setétség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 1, 'Az Ezrahita Ethán tanítása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 2, 'Az Úrnak kegyelmességét hadd énekeljem örökké! Nemzetségről nemzetségre hirdetem a te hűséges voltodat az én számmal!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 3, 'Mert azt mondom: Örökké megáll a te kegyelmességed, és megerősíted a te hűséges voltodat az egekben, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 4, 'Szövetséget kötöttem az én választottammal, megesküdtem Dávidnak, az én szolgámnak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 5, 'Mindörökké megerősítem a te magodat, és nemzetségről nemzetségre megépítem a te királyi székedet. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 6, 'És az egek dicsérik a te csodadolgodat Uram; a te hűséges voltodat is a szentek gyülekezetében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 7, 'Mert a felhőkben kicsoda hasonlatos az Úrhoz, s ki olyan, mint az Úr, az istenek fiai között?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 8, 'Igen rettenetes Isten ő a szentek gyűlésében, és félelmetes mindazokra, a kik körülte vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 9, 'Uram, Seregeknek Istene! Kicsoda olyan erős, mint te vagy Uram? És a te hűséges voltod körülvesz téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 10, 'Te uralkodol a tengernek kevélységén; mikor az ő habjai felemelkednek, te csendesíted le azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 11, 'Te rontád meg Égyiptomot mintegy átdöföttet; erős karoddal elszélesztetted ellenségeidet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 12, 'Tieid az egek, a föld is a tied: e világot minden benne valóval te fundáltad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 13, 'Az északot és a délt te teremtetted, a Thábor és a Hermon a te nevednek örvendeznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 14, 'A te karod hatalommal teljes, a te kezed erős, a te jobbod méltóságos.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 15, 'Igazság és jogosság a te királyi székednek alapja; kegyelem és hűség jár a te orczád előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 16, 'Boldog nép az, a mely megérti a kürt szavát; a te orczádnak világosságánál jár ez, oh Uram!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 17, 'A te nevedben örvendeznek egész nap; és a te igazságodban felmagasztaltatnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 18, 'Mert az ő erejöknek ékessége te vagy; a te jóakaratoddal emeled fel a mi szarvunkat is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 19, 'Mert az Úr a mi paizsunk, és Izráelnek Szentje a mi királyunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 20, 'Akkor látásban szóltál a te kegyeltednek, és mondád: Segítséget adtam a vitéznek, felmagasztaltam a népből választottat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 21, 'Megtaláltam Dávidot, az én szolgámat; szent olajommal kentem fel őt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 22, 'A kivel állandóan vele lesz az én kezem, sőt az én karom erősíti meg őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 23, 'Nem nyomhatja őt el az ellenség, és a gonosz ember sem nyomorgatja meg őt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 24, 'Mert ő előtte rontom meg az ő szorongatóit, és verem meg az ő gyűlölőit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 25, 'És vele lesz az én hűségem és kegyelmem, és az én nevemmel magasztaltatik fel az ő szarva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 26, 'És rávetem az ő kezét a tengerre, és az ő jobbját a folyóvizekre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 27, 'Ő így szólít engem: Atyám vagy te; én Istenem és szabadításom kősziklája!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 28, 'Én meg elsőszülöttemmé teszem őt és felebbvalóvá a föld királyainál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 29, 'Örökké megtartom néki az én kegyelmemet, és az én szövetségem bizonyos marad ő vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 30, 'És az ő magvát örökkévalóvá teszem, és az ő királyi székét, mint az egeknek napjait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 31, 'Ha az ő fiai elhagyják az én törvényemet, és nem járnak az én végzéseim szerint;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 32, 'Ha az én rendeléseimet megtörik, és meg nem tartják az én parancsolatimat:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 33, 'Akkor vesszővel látogatom meg az ő bűnöket, és vereségekkel az ő álnokságukat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 34, 'De az én kegyelmemet nem vonom meg tőle, és az én hűséges voltomban nem hazudom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 35, 'Nem töröm meg az én szövetségemet, és a mi kijött az én számból, el nem változtatom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 36, 'Megesküdtem egyszer az én szentségemre: vajjon megcsalhatnám-é Dávidot?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 37, 'Az ő magva örökké megmarad, és az ő királyi széke olyan előttem, mint a nap.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 38, 'Megáll örökké, mint a hold, és bizonyos, mint a felhőben lévő bizonyság. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 39, 'De te mégis elvetetted és megútáltad őt, és megharagudtál a te felkentedre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 40, 'Felbontottad a te szolgáddal kötött szövetséget, földre tiportad az ő koronáját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 41, 'Lerontottad az ő kőfalait mind; romokká tetted erősségeit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 42, 'Zsákmányolták őt mind az úton járók; gyalázattá lőn az ő szomszédai előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 43, 'Felmagasztaltad az ő szorongatóinak jobbját, és megvidámítottad minden ellenségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 44, 'Még fegyverének élét is elvetted, és nem segítetted őt a harczban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 45, 'Eltörlötted az ő fényességét, és az ő királyi székét a földre vetetted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 46, 'Az ő ifjúságának napjait megrövidítetted, gyalázatot borítottál reá. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 47, 'Meddig rejtegeted még magad, oh Uram, szüntelen, és ég a te haragod, mint a tűz?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 48, 'Emlékezzél meg rólam: mily rövid az élet! Mily semmire teremtetted te mind az embernek fiait!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 49, 'Kicsoda oly erős, hogy éljen és ne lásson halált s megszabadítsa magát a Seolnak kezéből? Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 50, 'Hol van a te előbbi kegyelmességed, Uram? Megesküdtél Dávidnak a te hűséges voltodra!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 51, 'Emlékezzél meg Uram a te szolgáidnak gyalázatjokról! hogy sok népnek gyalázatját hordozom keblemben,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 52, 'A melyekkel gyaláztak a te ellenségeid Uram, a melyekkel gyalázták a te felkentednek lépéseit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 53, 'Áldott legyen az Úr mindörökké! Ámen és Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 1, 'Mózesnek, az Isten emberének imádsága. Uram, te voltál nékünk hajlékunk nemzedékről nemzedékre!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 2, 'Minekelőtte hegyek lettek és föld és világ formáltaték, öröktől fogva mindörökké te vagy Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 3, 'Te visszatéríted a halandót a porba, és ezt mondod: Térjetek vissza embernek fiai!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 4, 'Mert ezer esztendő annyi előtted, mint a tegnapi nap, a mely elmúlt, és mint egy őrjárási idő éjjel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 5, 'Elragadod őket; olyanokká lesznek, mint az álom; mint a fű, a mely reggel sarjad;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 6, 'Reggel virágzik és sarjad, és estvére elhervad és megszárad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 7, 'Bizony megemésztetünk a te haragod által, és a te búsulásod miatt megromlunk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 8, 'Elédbe vetetted a mi álnokságainkat; titkos bűneinket a te orczádnak világa elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 9, 'Bizony elmúlik minden mi napunk a te bosszúállásod miatt; megemésztjük a mi esztendeinket, mint a beszédet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 10, 'A mi esztendeinknek napjai hetven esztendő, vagy ha feljebb, nyolczvan esztendő, és nagyobb részök nyomorúság és fáradság, a mely gyorsan tovatünik, mintha repülnénk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 11, 'Ki tudhatja a te haragodnak erejét, és a te félelmetességed szerint való bosszúállásodat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 12, 'Taníts minket úgy számlálni napjainkat, hogy bölcs szívhez jussunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 13, 'Térj vissza Uram! meddig késel? és könyörülj a te szolgáidon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 14, 'Jó reggel elégíts meg minket a te kegyelmeddel, hogy örvendezzünk és vígadjunk minden mi időnkben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 15, 'Vidámíts meg minket a mi nyomorúságunk napjaihoz képest, az esztendőkhöz képest, a melyekben gonoszt láttunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 16, 'Láttassék meg a te műved a te szolgáidon, és a te dicsőséged azoknak fiain.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 17, 'És legyen az Úrnak, a mi Istenünknek jó kedve mi rajtunk, és a mi kezünknek munkáját tedd állandóvá nékünk, és a mi kezünknek munkáját tedd állandóvá!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, 'Aki a Felségesnek rejtekében lakozik, a Mindenhatónak árnyékában nyugoszik az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, 'Azt mondom az Úrnak: Én oltalmam, váram, Istenem ő benne bízom!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, 'Mert ő szabadít meg téged a madarásznak tőréből, a veszedelmes dögvésztől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, 'Tollaival fedez be téged, és szárnyai alatt lészen oltalmad; paizs és pánczél az ő hűsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, 'Nem félhetsz az éjszakai ijesztéstől, a repülő nyíltól nappal;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, 'A dögvésztől, a mely a homályban jár; a döghaláltól, a mely délben pusztít.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, 'Elesnek mellőled ezeren, és jobb kezed felől tízezeren; és hozzád nem is közelít.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, 'Bizony szemeiddel nézed és meglátod a gonoszoknak megbüntetését!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, 'Mert azt mondtad te: Az Úr az én oltalmam; a Felségest választottad a te hajlékoddá:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, 'Nem illet téged a veszedelem, és csapás nem közelget a sátorodhoz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, 'Mert az ő angyalainak parancsolt felőled, hogy őrizzenek téged minden útadban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, 'Kézen hordoznak téged, hogy meg ne üssed lábadat a kőbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, 'Oroszlánon és áspiskígyón jársz, megtaposod az oroszlánkölyköt és a sárkányt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, 'Mivelhogy ragaszkodik hozzám, megszabadítom őt, felmagasztalom őt, mert ismeri az én nevemet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, 'Segítségül hív engem, ezért meghallgatom őt; vele vagyok háborúságában: megmentem és megdicsőítem őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, 'Hosszú élettel elégítem meg őt, és megmutatom néki az én szabadításomat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, 'Zsoltár, ének szombat napra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, 'Jó dolog dicsérni az Urat, és éneket mondani a te nevednek, oh Felséges!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, 'Hirdetni jó reggel a te kegyelmedet, és éjjelente a te hűséges voltodat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, 'Tíz húrú hegedűvel és lanttal, hárfán való zengedezéssel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, 'Mert megvidámítottál engem Uram a te cselekedeteddel, a te kezednek műveiben örvendezem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 6, 'Mely nagyok Uram a te műveid, igen mélységesek a te gondolataid!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 7, 'A balgatag ember nem tudja, a bolond pedig nem érti meg ezt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 8, 'Hogy mikor felsarjaznak a gonoszok, mint a fű, és virágoznak mind a hamisság cselekedők, mindörökké elveszszenek ők;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 9, 'Te pedig Uram, magasságos vagy örökké!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 10, 'Mert ímé, a te ellenségeid elvesznek, és elszélednek mind a hamisság cselekedők!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 11, 'De magasra növeszted az én szarvamat, mint az egyszarvúét; elárasztatom csillogó olajjal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 12, 'És legeltetem szememet az én ellenségeimen, és az ellenem támadó gonosztevőkön mulat majd a fülem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 13, 'Az igaz virágzik, mint a pálmafa, növekedik, mint a czédrus a Libánonon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 14, 'Plánták ők az Úrnak házában; a mi Istenünknek tornáczaiban virágzanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 15, 'Még a vén korban is gyümölcsöznek; kövérek és zöldellők lesznek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 16, 'Hogy hirdessék, hogy igazságos az Úr, az én kősziklám, és hogy nincsen hamisság benne!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, 'Uralkodik az Úr, méltóságot öltözött fel; felöltözött az Úr: hatalmat övezett magára; megerősítette a földet is, hogy meg ne induljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, 'Állandó a te királyi széked eleitől kezdve; öröktől fogva vagy te!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, 'A folyóvizek Uram, a folyóvizek zúgnak, a folyóvizek hullámokat hánynak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, 'A nagy vizek zúgásainál, a tengernek felséges morajlásánál felségesebb az Úr a magasságban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, 'A te bizonyságaid igen bizonyosak, a te házadat illeti Uram szentség, napok hosszáig!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 1, 'Uram, bosszúállásnak Istene! Bosszúállásnak Istene, jelenj meg!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 2, 'Emelkedjél fel te, földnek birája, fizess meg a kevélyeknek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 3, 'A hitetlenek, Uram, meddig még, meddig örvendeznek még a hitetlenek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 4, 'Piszkolódnak, keményen szólnak; kérkednek mindnyájan a hamisság cselekedői.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 5, 'A te népedet Uram tapossák, és nyomorgatják a te örökségedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 6, 'Az özvegyet és jövevényt megölik, az árvákat is fojtogatják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 7, 'És ezt mondják: Nem látja az Úr, és nem veszi észre a Jákób Istene!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 8, 'Eszméljetek ti bolondok a nép között! És ti balgatagok, mikor tértek eszetekre?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 9, 'A ki a fület plántálta, avagy nem hall-é? És a ki a szemet formálta, avagy nem lát-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 10, 'A ki megfeddi a népeket, avagy nem fenyít-é meg? Ő, a ki az embert tudományra tanítja:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 11, 'Az Úr tudja az embernek gondolatjait, hogy azok hiábavalók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 12, 'Boldog ember az, a kit te megfeddesz Uram, és a kit megtanítasz a te törvényedre;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 13, 'Hogy nyugalmat adj annak a veszedelem napján, míg megásták a vermet a hitetlennek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 14, 'Bizony nem veti el az Úr az ő népét, és el nem hagyja az ő örökségét!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 15, 'Mert igazságra fordul vissza az ítélet, és utána mennek mind az igazszívűek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 16, 'Kicsoda támad fel én mellettem a gonoszok ellen? Kicsoda áll mellém a hamisság cselekedők ellen?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 17, 'Ha az Úr nem lett volna segítségül nékem: már-már ott lakoznék lelkem a csendességben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 18, 'Mikor azt mondtam: Az én lábam eliszamodott: a te kegyelmed, Uram, megtámogatott engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 19, 'Mikor megsokasodtak bennem az én aggódásaim: a te vígasztalásaid megvidámították az én lelkemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 20, 'Van-é köze te hozzád a hamisság székének, a mely nyomorúságot szerez törvény színe alatt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 21, 'Egybegyülekeznek az igaznak lelke ellen, és elkárhoztatják az ártatlannak vérét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 22, 'De kőváram lőn én nékem az Úr, és az én Istenem az én oltalmamnak kősziklája;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 23, 'És visszafordítja reájok az ő álnokságukat, és az ő gonoszságukkal veszti el őket; elveszti őket az Úr, a mi Istenünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, 'Jőjjetek el, örvendezzünk az Úrnak; vígadozzunk a mi szabadításunk kősziklájának!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, 'Menjünk elébe hálaadással; vígadozzunk néki zengedezésekkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, 'Mert nagy Isten az Úr, és nagy király minden istenen felül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, 'A kinek kezében vannak a földnek mélységei, és a hegyeknek magasságai is az övéi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, 'A kié a tenger, és ő alkotta is azt, és a szárazföldet is az ő kezei formálták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, 'Jőjjetek, hajoljunk meg, boruljunk le; essünk térdre az Úr előtt, a mi alkotónk előtt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, 'Mert ő a mi Istenünk, mi pedig az ő legelőjének népei és az ő kezének juhai vagyunk; vajha ma hallanátok az ő szavát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, 'Ne keményítsétek meg a ti szíveteket, mint Meribáhnál, mint Maszszáh napján a pusztában:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, 'A hol megkisértettek engem a ti atyáitok; próbára tettek engem, jóllehet látták az én cselekedetemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, 'Negyven esztendeig bosszankodtam e nemzetségen, és mondám: Tévelygő szívű nép ők, és nem tudják ők az én útamat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, 'A kiknek megesküdtem haragomban: Nem mennek be az én nyugalmam helyére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 1, 'Énekeljetek az Úrnak új éneket; énekelj az Úrnak te egész föld!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 2, 'Énekeljetek az Úrnak, áldjátok az ő nevét; hirdessétek napról-napra az ő szabadítását.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 3, 'Beszéljétek a népek között az ő dicsőségét, minden nemzet között az ő csodadolgait;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 4, 'Mert nagy az Úr és igen dicséretes, rettenetes minden isten felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 5, 'Mert a nemzeteknek minden istene bálvány, az Úr pedig egeket alkotott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 6, 'Ékesség és fenség van előtte; tisztesség és méltóság az ő szent helyén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 7, 'Adjatok az Úrnak népeknek nemzetségei: adjatok az Úrnak dicsőséget és tisztességet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 8, 'Adjátok az Úrnak neve dicsőségét; hozzatok ajándékot és jőjjetek be az ő tornáczaiba!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 9, 'Hajoljatok meg az Úr előtt szent ékességben; rettegjen előtte az egész föld!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 10, 'Mondjátok a népek között: Az Úr uralkodik; megerősítette a földet, hogy meg ne induljon; ő ítéli meg a népeket igazsággal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 11, 'Örüljenek az egek és örvendezzen a föld; harsogjon a tenger és minden benne való!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 12, 'Viduljon a mező és minden, a mi rajta van; örvend akkor az erdő minden fája is,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 13, 'Az Úrnak orczája előtt, mert eljön, mert eljön, hogy megítélje e földet. Megítéli majd a világot igazsággal, és a népeket az ő hűségével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, 'Az Úr uralkodik, örüljön a föld; örvendezzenek a temérdek szigetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 2, 'Felhő és homályosság van körülte; igazság és jogosság az ő székének erőssége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 3, 'Tűz jár előtte, és köröskörül elégeti az ő szorongatóit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 4, 'Megvilágosítják az ő villámai a világot; látja és megretteg a föld.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 5, 'A hegyek, mint a viasz megolvadnak az Úr előtt, az egész földnek Ura előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 6, 'Az egek hirdetik az ő igazságát, és minden nép látja az ő dicsőségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 7, 'Megszégyenülnek mind a faragott képek szolgái, a kik bálványokkal dicsekednek; meghajolnak előtte mind az istenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 8, 'Hallotta és örvendeze Sion, és örülének Júdának leányai a te ítéleteidnek Uram!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 9, 'Mert te felséges vagy Uram az egész földön, és igen felmagasztaltattál minden isten felett!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 10, 'A kik szeretitek az Urat, gyűlöljétek a gonoszt! Megőrzi ő az ő kegyeltjeinek lelkét; a gonoszok kezéből megszabadítja őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 11, 'Világosság támad fel az igazra, és az egyenesszívűekre öröm.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 12, 'Örüljetek igazak az Úrban, és tiszteljétek az ő szentséges emlékezetét!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 1, 'Zsoltár. Énekeljetek az Úrnak új éneket, mert csodadolgokat cselekedett; megsegítette őt az ő jobbkeze és az ő szentséges karja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 2, 'Tudtul adta az Úr az ő szabadítását; a népek előtt megjelentette az ő igazságát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 3, 'Megemlékezett az ő kegyelméről és Izráel házához való hűségéről; látták a föld határai mind a mi Istenünknek szabadítását.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 4, 'Vígan énekelj az Úrnak te egész föld; harsanjatok fel, örvendezzetek és zengedezzetek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 5, 'Zengedezzetek az Úrnak hárfával, hárfával és hangos énekléssel;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 6, 'Trombitákkal és kürtzengéssel vígadozzatok a király, az Úr előtt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 7, 'Harsogjon a tenger és minden benne való, a világ és a kik lakoznak benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 8, 'A folyóvizek tapsoljanak, a hegyek együttesen örvendezzenek');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 9, 'Az Úr előtt, mert eljön megítélni a földet; megítéli a világot igazsággal és a népeket méltányossággal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 1, 'Az Úr uralkodik, reszkessenek a népek; Kérubokon ül, remegjen a föld!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 2, 'Nagy az Úr a Sionon, és magasságos ő minden nép felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 3, 'Tiszteljék a te nagy és rettenetes nevedet, – szent az!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 4, 'És tisztesség a királynak, a ki szereti a jogosságot! Te megerősítetted az egyenességet; jogosságot és igazságot szereztél Jákóbban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 5, 'Magasztaljátok az Urat, a mi Istenünket, és boruljatok le az ő lábainak zsámolya elé; szent ő!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 6, 'Mózes és Áron az ő papjaival, és Sámuel az ő nevét segítségül hívókkal egybe, segítségül hívják vala az Urat, és meghallgatá őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 7, 'Felhő-oszlopban szólt vala hozzájok; megőrizték az ő bizonyságtételét és rendeletét, a melyet adott vala nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 8, 'Uram, mi Istenünk! Te meghallgattad őket, kegyelmes Isten voltál hozzájok; de bosszúálló az ő hiábavalóságaik miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 9, 'Magasztaljátok az Urat, a mi Istenünket, és boruljatok le az ő szent hegyén; mert szent az Úr, a mi Istenünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, 'Hálaadó zsoltár. Vígan énekelj az Úrnak te egész föld!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, 'Szolgáljatok az Úrnak örvendezéssel; menjetek eléje vígassággal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, 'Tudjátok meg, hogy az Úr az Isten; ő alkotott minket és nem magunk; az ő népe és az ő legelőinek juhai vagyunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, 'Menjetek be az ő kapuin hálaadással, tornáczaiba dicséretekkel; adjatok hálákat néki, áldjátok az ő nevét!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, 'Mert jó az Úr, örökkévaló az ő kegyelme, és nemzedékről nemzedékre való az ő hűsége!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 1, 'Dávid zsoltára. Kegyelmet és igazságot énekelek; te néked zengek éneket, Uram!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 2, 'Gondom van a tökéletes útra: mikor jössz el hozzám? Szívemnek tökéletessége szerint járok én az én házamban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 3, 'Nem vetem a szemem hiábavaló dologra; a pártoskodók cselekedetét gyűlölöm: nincs köze hozzám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 4, 'A csalárd szív távol van én tőlem, gonoszt nem ismerek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 5, 'A ki titkon rágalmazza az ő felebarátját, elvesztem azt; a nagyralátót és a kevélyszívűt, azt el nem szenvedem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 6, 'Szemmel tartom a föld hűségeseit, hogy mellettem lakozzanak; a tökéletesség útjában járó, az szolgál engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 7, 'Nem lakozik az én házamban, a ki csalárdságot mível; a ki hazugságot szól, nem állhat meg szemeim előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 8, 'Reggelenként elvesztem e földnek latrait, hogy kigyomláljak az Úrnak városából minden gonosztevőt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 1, 'A nyomorultnak imádsága, a mikor eleped és kiönti panaszát az Úr elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 2, 'Uram, hallgasd meg az én imádságomat, és kiáltásom jusson te hozzád!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 3, 'Ne rejtsd el a te orczádat tőlem; mikor szorongatnak engem, hajtsd hozzám a te füledet; mikor kiáltok, hamar hallgass meg engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 4, 'Mert elenyésznek az én napjaim, mint a füst, és csontjaim, mint valami tűzhely, üszkösök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 5, 'Letaroltatott és megszáradt, mint a fű az én szívem; még kenyerem megevéséről is elfelejtkezem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 6, 'Nyögésemnek szavától csontom a húsomhoz ragadt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 7, 'Hasonló vagyok a pusztai pelikánhoz; olyanná lettem, mint a bagoly a romokon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 8, 'Virrasztok és olyan vagyok, mint a magános madár a háztetőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 9, 'Minden napon gyaláznak engem ellenségeim, csúfolóim esküsznek én reám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 10, 'Bizony a port eszem kenyér gyanánt, és italomat könyekkel vegyítem,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 11, 'A te felindulásod és búsulásod miatt; mert felemeltél engem és földhöz vertél engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 12, 'Napjaim olyanok, mint a megnyúlt árnyék; magam pedig, mint a fű, megszáradtam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 13, 'De te Uram örökké megmaradsz, és a te emlékezeted nemzetségről nemzetségre áll.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 14, 'Te kelj fel, könyörülj a Sionon! Mert ideje, hogy könyörülj rajta, mert eljött a megszabott idő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 15, 'Mert kedvelik a te szolgáid annak köveit, és a porát is kímélik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 16, 'És félik a népek az Úrnak nevét, és e földnek minden királya a te dicsőségedet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 17, 'Mivelhogy az Úr megépítette a Siont, megláttatta magát az ő dicsőségében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 18, 'Oda fordult a gyámoltalanok imádsága felé, és azoknak imádságát meg nem útálta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 19, 'Irattassék meg ez a következő nemzedéknek, és a teremtendő nép dicsérni fogja az Urat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 20, 'Mert alátekintett az ő szentségének magaslatáról; a mennyekből a földre nézett le az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 21, 'Hogy meghallja a fogolynak nyögését, és hogy feloldozza a halálnak fiait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 22, 'Hogy hirdessék a Sionon az Úrnak nevét, és az ő dicséretét Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 23, 'Mikor egybegyűlnek a népek mindnyájan, és az országok, hogy szolgáljanak az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 24, 'Megsanyargatta az én erőmet ez útban, megrövidítette napjaimat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 25, 'Ezt mondám: Én Istenem! Ne vígy el engem az én napjaimnak felén; a te esztendeid nemzedékek nemzedékéig tartanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 26, 'Régente fundáltad a földet, s az egek is a te kezednek munkája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 27, 'Azok elvesznek, de te megmaradsz; mindazok elavulnak, mint a ruha; mint az öltözetet, elváltoztatod azokat, és elváltoznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 28, 'De te ugyanaz vagy, és a te esztendeid el nem fogynak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 29, 'A te szolgáidnak fiai megmaradnak, és az ő magvok erősen megáll előtted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, 'A Dávidé. Áldjad én lelkem az Urat, és egész bensőm az ő szent nevét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, 'Áldjad én lelkem az Urat, és el ne feledkezzél semmi jótéteményéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, 'A ki megbocsátja minden bűnödet, meggyógyítja minden betegségedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, 'A ki megváltja életedet a koporsótól; kegyelemmel és irgalmassággal koronáz meg téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, 'A ki jóval tölti be a te ékességedet, és megújul a te ifjúságod, mint a sasé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, 'Igazságot cselekszik az Úr, és ítéletet minden elnyomottal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, 'Megismertette az ő útait Mózessel; Izráel fiaival az ő cselekedeteit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, 'Könyörülő és irgalmas az Úr, késedelmes a haragra és nagy kegyelmű.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, 'Nem feddődik minduntalan, és nem tartja meg haragját örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, 'Nem bűneink szerint cselekszik velünk, és nem fizet nékünk a mi álnokságaink szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, 'Mert a milyen magas az ég a földtől, olyan nagy az ő kegyelme az őt félők iránt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, 'A milyen távol van a napkelet a napnyugattól, olyan messze veti el tőlünk a mi vétkeinket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, 'A milyen könyörülő az atya a fiakhoz, olyan könyörülő az Úr az őt félők iránt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, 'Mert ő tudja a mi formáltatásunkat; megemlékezik róla, hogy por vagyunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, 'Az embernek napjai olyanok, mint a fű, úgy virágzik, mint a mezőnek virága.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, 'Hogyha általmegy rajta a szél, nincsen többé, és az ő helye sem ismeri azt többé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, 'De az Úr kegyelme öröktől fogva való és örökkévaló az őt félőkön, és az ő igazsága a fiaknak fiain;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, 'Azokon, a kik megtartják az ő szövetségét és megemlékeznek az ő parancsolatjairól, hogy azokat megcselekedjék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, 'Az Úr a mennyekbe helyheztette az ő székét és az ő uralkodása mindenre kihat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, 'Áldjátok az Urat ő angyalai, ti hatalmas erejűek, a kik teljesítitek az ő rendeletét, hallgatván az ő rendeletének szavára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, 'Áldjátok az Urat minden ő serege: ő szolgái, akaratának teljesítői!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, 'Áldjátok az Urat minden ő teremtményei, az ő uralkodásának minden helyén! Áldjad én lelkem az Urat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, 'Áldjad én lelkem az Urat! Uram én Istenem, nagy vagy te igen, ékességet és fenséget öltöztél magadra!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, 'A ki körülvette magát világossággal, mint egy öltözettel, és kiterjesztette az egeket, mint egy kárpitot;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, 'A ki vizeken építi fel az ő palotáját, a felhőket rendeli az ő szekerévé, jár a szeleknek szárnyain;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, 'A ki a szeleket teszi követeivé, a lángoló tüzet szolgáivá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, 'Ő fundálta a földet az ő oszlopain, nem mozdul az meg soha örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, 'Vízáradattal, mint egy ruhával borítottad be azt, a hegyek felett is vizek állottak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, 'Egy kiáltásodtól eloszlának, és mennydörgésednek szavától szétriadának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, 'Hegyek emelkedének fel és völgyek szállának alá arra a helyre, a melyet fundáltál nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, 'Határt vetettél, a melyet át nem hágnak, nem térnek vissza a földnek elborítására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, 'A ki elbocsátja a forrásokat a völgyekbe, hogy folydogáljanak a hegyek között;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, 'Megitassák a mezőnek minden állatát; a vadszamarak is megoltsák szomjúságukat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, 'Mellettök lakoznak az égnek madarai, az ágak közül hangicsálnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, 'A ki megöntözi a hegyeket az ő palotájából; a te munkáidnak gyümölcséből megelégíttetik a föld.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, 'A ki füvet sarjaszt a barmoknak és növényeket az embereknek hasznára, hogy eledelt vegyenek a földből,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, 'És bort, a mely megvidámítja a halandónak szívét, fényesebbé teszi az orczát az olajnál; és kenyeret, a mely megerősíti a halandónak szívét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, 'Megelégíttetnek az Úrnak fái, a Libánonnak czédrusai, a melyeket plántált;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, 'A melyeken madarak fészkelnek: az eszterág, a melynek a cziprusok a háza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, 'A magas hegyek a vadkecskéknek, a sziklák hörcsögöknek menedéke.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, 'Teremtett holdat ünnepeknek mutatására; a napot, a mely lenyugovását tudja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, 'Szerzett setétséget, hogy éjszaka legyen, a melyben szétjárjanak a mezőnek összes vadai;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, 'Az oroszlánkölykök, a melyek ordítanak a prédáért, sürgetvén Istentől eledelöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, 'Ha felkél a nap, elrejtőznek és hajlékaikban heverésznek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, 'Az ember munkájára megy ki, és az ő dolgára mind estvéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, 'Mily számtalanok a te műveid, Uram! Mindazokat bölcsen alkottad meg, és betelt a föld a te gazdagságoddal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, 'Ez a nagy és széles tenger! Itt vannak benne a megszámlálhatatlan csúszók; apró állatok nagyokkal együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, 'Amott gályák járnak s czethal, a melyet azért formáltál, hogy játszadozzék benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, 'Mindazok te reád néznek, hogy megadjad eledelüket alkalmas időben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, 'Adsz nékik és ők takarnak; megnyitod kezedet, és megtelnek a te jóvoltoddal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, 'Elfordítod orczádat, megháborodnak; elveszed a lelköket, kimulnak és porrá lesznek újra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, 'Kibocsátod a te lelkedet, megújulnak, és újjá teszed a földnek színét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, 'Legyen az Úrnak dicsőség örökké; örvendezzen az Úr az ő teremtményeiben;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, 'A ki, ha rátekint e földre, megrendül az; megilleti a hegyeket, és füstölögnek azok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, 'Éneklek az Úrnak egész életemben; zengedezek az én Istenemnek, a míg vagyok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, 'Legyen kedves néki az én rebegésem; örvendezem én az Úrban;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, 'Veszszenek el a bűnösök a földről, és a hitetlenek ne legyenek többé! Áldjad én lelkem az Urat; dicsérjétek az Urat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 1, 'Magasztaljátok az Urat, hívjátok segítségül az ő nevét, hirdessétek a népek között az ő cselekedeteit!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 2, 'Énekeljetek néki, zengedezzetek néki, beszéljétek el minden ő csodatételét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 3, 'Dicsekedjetek az ő szent nevével; örvendezzen azoknak a szívök, a kik keresik az Urat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 4, 'Kivánjátok az Urat és az ő erejét; keressétek az ő orczáját szüntelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 5, 'Emlékezzetek meg az ő csodáiról, a melyeket cselekedett; jeleiről és az ő szájának ítéleteiről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 6, 'Oh Ábrahámnak, az ő szolgájának magva; oh Jákóbnak, az ő választottának fiai!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 7, 'Ő, az Úr a mi Istenünk, az egész földre kihat az ő ítélete.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 8, 'Megemlékezik az ő szövetségéről mindörökké; az ő rendeletéről, a melyet megszabott ezer nemzetségiglen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 9, 'A melyet kötött Ábrahámmal, és az ő Izsáknak tett esküvéséről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 10, 'És odaállatta azt Jákóbnak szabályul, Izráelnek örök szövetségül,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 11, 'Mondván: Néked adom Kanaán földét, sors szerint való örökségetekül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 12, 'Mikor még csekély számmal valának, igen kevesen és mintegy zsellérek abban,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 13, 'És egyik nemzettől a másikhoz bujdosának, egyik országból a másik néphez:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 14, 'Nem engedé, hogy valaki nyomorgassa őket, sőt királyokat is megfenyített miattok, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 15, 'Meg ne illessétek az én felkentjeimet, és az én prófétáimnak ne ártsatok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 16, 'Mikor éhséget idéze elő a földön; és a kenyérnek minden botját eltöré,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 17, 'Elküldött előttük egy férfiút, Józsefet, a ki rabul adatott vala el;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 18, 'A lábait békóba szorították, ő maga vasban járt vala,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 19, 'Mindazideig, a míg szava beteljesedett. Az Úr beszéde megpróbálta őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 20, 'Elküldött a király és feloldotta őt, a népeken uralkodó, és szabaddá tette őt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 21, 'Úrrá tevé őt az ő házán, és uralkodóvá minden jószágán;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 22, 'Hogy főembereit tetszése szerint kötöztetheté, és véneit is bölcsességre taníthatá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 23, 'És beméne Izráel Égyiptomba, s Jákób a Khám földén zsellérkedék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 24, 'És igen megszaporítá az ő népét, és erősebbé tevé elnyomóinál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 25, 'Elváltoztatá azoknak szívét, hogy gyűlöljék az ő népét, és álnokul cselekedjenek az ő szolgáival.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 26, 'Elküldte Mózest, az ő szolgáját, és Áront, a kit választott vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 27, 'Elvégezék azok között az ő jeleit, és a csodákat a Khám földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 28, 'Sötétséget bocsátott és elsötétítette azt, és azok nem engedetlenkedtek az ő rendeleteinek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 29, 'Vizeiket vérré változtatá, és megölé az ő halaikat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 30, 'Földjük békáktól hemzsege, még a királyuk termeiben is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 31, 'Szólt, és támadának legyek és szúnyogok minden ő határukon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 32, 'Adott nékik eső gyanánt jégesőt, és lángoló tüzet a földjökre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 33, 'És elvevé szőlőjüket és fügefájokat, és széttördelé határuknak élő fáit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 34, 'Szólt és támada sáska, és megszámlálhatatlan cserebogár.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 35, 'És megemészte minden növényt az ő földjökön, és az ő szántóföldjöknek gyümölcsét megemészté.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 36, 'És megöle minden elsőszülöttet földjökön, minden erejöknek zsengéjét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 37, 'És kihozá őket ezüsttel és arannyal, és nemzetségeikben nem volt beteges.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 38, 'Örült Égyiptom, mikor kijövének, mert a tőlök való félelem megszállta őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 39, 'Felhőt terjeszte ki, hogy befedezze őket, és tüzet, hogy világítson éjjel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 40, 'Könyörgött és fürjeket hoza, és mennyei kenyérrel elégítette meg őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 41, 'Megnyitotta a kősziklát és víz zúdula ki, folyóként futott a sivatagon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 42, 'Mert megemlékezett az ő szentséges igéretéről, a melyet tőn Ábrahámnak, az ő szolgájának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 43, 'Kihozá azért az ő népét örömmel, és az ő választottait vígassággal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 44, 'És nékik adá a pogányok földét, és öröklék a népek fáradságos szerzeményét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 45, 'Azért, hogy megtartsák az ő rendeleteit, és törvényeit megőrizzék. Dicsérjétek az Urat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 1, 'Dicsérjétek az Urat. Magasztaljátok az Urat, mert jó; mert örökkévaló az ő kegyelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 2, 'Ki beszélhetné el az Úr nagy tetteit? és jelenthetné ki minden dicsőségét?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 3, 'Boldog, a ki megtartja a törvényt, és igazán cselekszik minden időben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 4, 'Emlékezzél reám, Uram, népedhez való jóságodért; jőjj el hozzám szabadításoddal,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 5, 'Hogy láthassam választottaidhoz való jóvoltodat, és örvendezhessek néped örömében; hogy dicsekedjem a te örökségeddel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 6, 'Vétkeztünk atyáinkkal együtt; bűnösök, gonoszok valánk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 7, 'Atyáink nem értették meg Égyiptomban csodáidat, nem emlegették meg kegyelmed nagyságát, hanem daczoskodtak a tengernél, a veres tengernél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 8, 'De ő megsegíté őket az ő nevéért, hogy megismertesse a maga erejét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 9, 'Rákiálta a veres tengerre és kiszáradt, s úgy vivé őket a mélységeken, mint egy síkon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 10, 'És kisegíté őket a gyűlölő kezéből; kimentette őket ellenség kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 11, 'Szorongatóikat víz borította el, egy sem maradt meg belőlük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 12, 'És hittek az ő beszédeinek, és énekelték az ő dicséretét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 13, 'Hirtelen elfeledék cselekedeteit; nem várák az ő tanácsát!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 14, 'Epekedés epeszté őket a pusztában, és próbára tevék Istent a sivatagon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 15, 'És megadá nékik, a mit kivántak; és ösztövérséget bocsáta lelkökbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 16, 'És irigységre indulának Mózes ellen a táborban, az Úr szentje, Áron ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 17, 'Megnyilt a föld és elnyelé Dátánt, és beborítá Abirám seregét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 18, 'És tűz gyulladt fel azok seregében, láng égeté el a gonoszokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 19, 'Borjút csináltak a Hóreb alatt, és hajlongtak az öntött bálvány előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 20, 'Felcserélték az ő dicsőségöket: ökörnek képével, a mely füvet eszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 21, 'Elfeledkezének Istenről, szabadítójokról, a ki nagy dolgokat művelt Égyiptomban,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 22, 'Csodákat a Khám országában, félelmetes dolgokat a veres tenger mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 23, 'Gondolta, hogy kipusztítja őket; de Mózes, az ő választottja, elébe állott a résre, hogy elfordítsa haragját, hogy el ne veszítse őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 24, 'És becsmérelték a kivánatos földet, nem hittek az ő igéretének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 25, 'És morgolódtak sátraikban, és nem hallgattak az Úr szavára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 26, 'De ő felemelé kezét reájok, hogy lesújtsa őket a pusztában;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 27, 'S hogy a pogányok közé dobja magvaikat, és szétszórja őket a tartományokban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 28, 'Majd hozzácsapódtak a Baál-Peorhoz, és ették a holtak áldozatait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 29, 'És felingerelték cselekedeteikkel, és zúdult reájok a csapás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 30, 'Ekkor felállott Fineás és ítélt; és a csapásnak vége lőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 31, 'És igazságul tulajdoníttaték néki firól-fira mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 32, 'Megharagíták a Meribáh vizeinél is, és baja támadt Mózesnek miattok,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 33, 'Mert megkeseríték az ő szívét, és gondatlanul szólt ajkaival.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 34, 'Nem irtották ki a népeket sem, a mint utasította őket az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 35, 'Sőt összeelegyedtek a pogányokkal, és eltanulták cselekedeteiket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 36, 'És tisztelték azoknak bálványait, és tőrré levének azok reájok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 37, 'És feláldozák fiaikat és leányaikat az ördögöknek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 38, 'És ártatlan vért ontának: fiaik és leányaik vérét, a kiket Kanaán bálványainak áldoztak, és megfertőzteték a föld öldökléssel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 39, 'És tisztátalanokká lőnek cselekedeteikben, és paráznákká tetteikben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 40, 'De felgyúlt az Úr haragja népe ellen, és megútálta az ő örökségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 41, 'És odaadá őket pogányok kezébe, és gyűlölőik uralkodtak rajtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 42, 'És sanyargatták őket ellenségeik, és görnyedtek azoknak hatalma alatt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 43, 'Számtalanszor megmentette őket, de ők felháboríták szándékaikkal, és mélyebben merültek bűneikbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 44, 'De reájok tekintett a nyomorúság napján, mikor meghallgatá rimánkodásukat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 45, 'És megemlékezett velök kötött szövetségéről, és nagy kegyelmessége szerint megengesztelődék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 46, 'És könyörületességre indítá irántok mindazokat, a kik őket fogva elvivék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 47, 'Segíts meg minket, Urunk Istenünk, és gyűjts össze minket a pogányok közül, hogy dicsőítsük a te szent nevedet, és dicsekedjünk a te dicséreteddel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 48, 'Áldott legyen az Úr, Izráel Istene örökkön örökké, és minden nép mondja: Ámen. Dicsérjétek az Urat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 1, 'Magasztaljátok az Urat, mert jó, mert örökkévaló az ő kegyelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 2, 'Ezt mondják az Úrnak megváltottai, a kiket megváltott a szorongatónak kezéből;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 3, 'És a kiket összegyűjtött a különböző földekről: napkelet és napnyugot felől, északról és a tenger felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 4, 'Bujdostak a pusztában, a sivatagban; lakó-város felé utat nem találtak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 5, 'Éhesek és szomjasok valának; lelkök is elepedt bennök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 6, 'De az Úrhoz kiáltának szorultságukban; sanyarúságukból megmenté őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 7, 'És vezeté őket egyenes útra, hogy lakó-városhoz juthassanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 8, 'Adjanak hálát az Úrnak az ő kegyelméért, és az emberek fiai iránt való csodadolgaiért,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 9, 'Hogy megelégíté a szomjúhozó lelket, és az éhező lelket betölté jóval!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 10, 'A kik setétségben és a halálnak árnyékában ülnek, megkötöztetvén nyomorúsággal és vassal;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 11, 'Mert ellenszegültek az Isten beszédének, és a Felségesnek tanácsát megútálták;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 12, 'Azért megalázta az ő szívöket nyomorúsággal: elestek és nem volt segítségök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 13, 'De az Úrhoz kiáltának szorultságukban, sanyarúságukból kiszabadítá őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 14, 'Kihozá őket a setétségből és a halálnak árnyékából, köteleiket pedig elszaggatá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 15, 'Adjanak hálát az Úrnak az ő kegyelméért, és az emberek fiai iránt való csodadolgaiért,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 16, 'Hogy összetöré az ércz-kapukat, és a vas-zárakat letördelé!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 17, 'A balgatagok az ő gonoszságuknak útjáért, és az ő hamisságukért nyomorgattattak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 18, 'Minden étket útála az ő lelkök, és a halál kapujához közelgetének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 19, 'De az Úrhoz kiáltának szorultságukban: sanyarúságukból kiszabadította őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 20, 'Kibocsátá az ő szavát és meggyógyítá őket, és kimenté őket az ő vermeikből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 21, 'Adjanak hálát az Úrnak az ő kegyelméért, és az emberek fiai iránt való csodadolgaiért,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 22, 'És áldozzanak hálaadásnak áldozataival, és hirdessék az ő cselekedeteit örvendezéssel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 23, 'A kik hajókon tengerre szállnak, és a nagy vizeken kalmárkodnak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 24, 'Azok látták az Úrnak dolgait, és az ő csodáit a mélységben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 25, 'Szólott ugyanis és szélvészt támaszta, a mely felduzzasztá a habokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 26, 'Az égig emelkedének, a fenékig sülyedének; lelkök elolvada az inségben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 27, 'Szédülének és tántorgának, mint a részeg, és minden bölcsességöknek esze vész vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 28, 'De az Úrhoz kiáltának az ő szorultságukban, és sanyarúságukból kivezeté őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 29, 'Megállítá a szélvészt, hogy csillapodjék, és megcsendesedtek a habok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 30, 'És örülének, hogy lecsillapodtak vala, és vezérlé őket az ő kivánságuknak partjára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 31, 'Adjanak hálát az Úrnak az ő kegyelméért, és az emberek fiai iránt való csodadolgaiért!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 32, 'És magasztalják fel őt a népnek gyülekezetében, és dicsérjék őt a vének ülésében!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 33, 'Folyóvizeket tett vala pusztává, és vízforrásokat szárazzá;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 34, 'Gyümölcstermő földet meddő földdé, a rajta lakó népnek gonoszsága miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 35, 'Pusztaságot tett vala álló tavakká, és kiaszott földet vízforrásokká.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 36, 'És telepített oda éhezőket, hogy lakó-városokat építsenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 37, 'És mezőket vetének be és szőlőket plántálának, hogy hasznos gyümölcsöt szerezzenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 38, 'És megáldá őket és igen megszaporodának, és barmaikat sem kevesbítette meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 39, 'De megkevesedtek és meggörnyedtek vala ínség, nyomorúság és keserűség miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 40, 'Gyalázatot zúdított a fejedelmekre, és bujdostatta őket út nélkül való kietlenben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 41, 'De felemelé a nyomorultat az ínségből, és hasonlóvá tette a nemzetségeket a juhnyájhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 42, 'Látják az igazak és örvendeznek, és minden gonoszság megtartóztatja az ő száját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 43, 'A bölcs, az eszébe veszi ezeket, és meggondolják az Úrnak kegyelmességét!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 1, 'Ének. Dávid zsoltára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 2, 'Kész az én szívem, oh Isten, hadd énekeljek és zengedezzek; az én dicsőségem is kész.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 3, 'Serkenj fel te lant és hárfa, hadd keltsem fel a hajnalt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 4, 'Hálát adok néked a népek között Uram, és zengedezek néked a nemzetek között!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 5, 'Mert nagy, egek felett való a te kegyelmed, és a felhőkig ér a te hűséges voltod!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 6, 'Magasztaltassál fel, oh Isten, az egek felett, és dicsőséged legyen az egész földön!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 7, 'Hogy megszabaduljanak a te szeretteid, segíts a te jobb kezeddel és hallgass meg engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 8, 'Az ő szentélyében szólott az Isten: Örvendezek, hogy eloszthatom Sikhemet, és felmérhetem Sukkothnak völgyét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 9, 'Enyém Gileád, enyém Manassé; Efraim az én fejemnek védelme, Júda az én törvényrendelőm.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 10, 'Moáb az én mosdómedenczém, Edomra az én saruimat vetem, Filistea felett kaczagok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 11, 'Kicsoda visz el engem a kerített városba? kicsoda vezérel engem Edomig?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 12, 'Nem te vagy-é, oh Isten, a ki megvetettél minket, hogy ki ne menj, oh Isten, a mi seregeinkkel?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 13, 'Adj szabadulást nékünk az ellenségtől, mert hiábavaló az emberi segítség!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 14, 'Istennel hatalmasan cselekszünk, és ő megtapodja ellenségeinket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 1, 'Az éneklőmesternek, Dávidé; zsoltár. Én dicséretemnek Istene, ne hallgass!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 2, 'Mert a gonosznak szája és az álnokságnak szája felnyilt ellenem, hazug nyelvvel beszélnek én velem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 3, 'És körülvesznek engem gyűlölséges beszédekkel, és ostromolnak engem ok nélkül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, 'Szeretetemért ellenkeznek velem, én pedig imádkozom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, 'Roszszal fizetnek nékem a jóért, és gyűlölséggel az én szeretetemért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, 'Állíts fölibe gonoszt, és vádló álljon az ő jobb keze felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, 'Mikor törvénykezik, mint gonosz jőjjön ki; még az imádsága is bűnné legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, 'Életének napjai kevesek legyenek, és a hivatalát más foglalja el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 9, 'Fiai legyenek árvákká, a felesége pedig özvegygyé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 10, 'És bujdossanak az ő fiai és kolduljanak, és elpusztult helyeiktől távol keressenek eledelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 11, 'Foglalja le minden jószágát az uzsorás, és idegenek ragadozzák el szerzeményét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 12, 'Ne legyen néki, a ki kegyelmet mutasson iránta, és ne legyen, a ki könyörüljön az ő árváin!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 13, 'Veszszen ki az ő maradéka; a második nemzedékben töröltessék el a nevök!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 14, 'Atyáinak álnoksága emlékezetben legyen az Úr előtt, és anyjának bűne el ne töröltessék!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 15, 'Mindenkor az Úr előtt legyenek, és emlékezetök is veszszen ki e földről,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 16, 'A miatt, hogy nem gondolt arra, hogy kegyelmet gyakoroljon és üldözte a szegény és nyomorult embert, és a megkeseredett szívűt, hogy megölje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 17, 'Mivelhogy szerette az átkot, azért érte el őt; és mivel nem volt kedve az áldáshoz, azért távozék az el ő tőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 18, 'Úgy öltözte fel az átkot, mint a ruháját, azért ment beléje, mint a víz, és az ő csontjaiba, mint az olaj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 19, 'Legyen az néki palástul, a melybe beburkolódzik, és övül, a melylyel mindenkor övezze magát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 20, 'Ez legyen jutalmok az Úrtól az én vádolóimnak, és a kik rosszat beszélnek az én lelkemre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 21, 'De te, én Uram, Istenem, bánj velem a te nevedért; mivelhogy jó a te kegyelmed, szabadíts meg engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 22, 'Mert szegény és nyomorult vagyok én, még a szívem is megsebesíttetett én bennem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 23, 'Úgy hanyatlom el, mint az árnyék az ő megnyúlásakor; ide s tova hányattatom, mint a sáska.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 24, 'Térdeim tántorognak az éhségtől, és testem megfogyatkozott a kövérségtől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 25, 'Sőt gyalázatossá lettem előttök; ha látnak engem, fejöket csóválják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 26, 'Segíts meg engem, Uram Isten; szabadíts meg engem a te kegyelmed szerint!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 27, 'Hadd tudják meg, hogy a te kezed munkája ez, hogy te cselekedted ezt, Uram!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 28, 'Átkozzanak ők, de te áldj meg! Feltámadnak, de szégyenüljenek meg és örvendezzen a te szolgád.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 29, 'Öltözzenek az én vádlóim gyalázatba, és burkolózzanak szégyenökbe, mint egy köpenybe!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 30, 'Hálát adok az Úrnak felettébb az én számmal, és dicsérem őt a sokaság közepette!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 31, 'Mert jobb keze felől áll a szegénynek, hogy megszabadítsa azoktól, a kik elítélik annak lelkét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, 'Dávidé; zsoltár. Monda az Úr az én uramnak: Ülj az én jobbomon, a míg ellenségeidet zsámolyul vetem a te lábaid alá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, 'A te hatalmad pálczáját kinyújtja az Úr Sionból, mondván: Uralkodjál ellenségeid között!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, 'A te néped készséggel siet a te sereggyűjtésed napján, szentséges öltözetekben; hajnalpir méhéből leszen ifjaidnak harmatja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, 'Megesküdt az Úr és meg nem másítja: Pap vagy te örökké Melkhisedek rendje szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, 'Az Úr a te jobbod felől; megrontja az ő haragja napján a királyokat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, 'Ítéletet tart a nemzetek között; telve lesz holttestekkel; összezúz messze földön minden főt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, 'Az út mellett való patakból iszik; ezért emeli fel az ő fejét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 1, 'Dícsérjétek az Urat. Dicsérem az Urat teljes szívből: az igazak környezetében és a gyülekezetben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 2, 'Nagyok az Úrnak cselekedetei; kivánatosak mindazoknak, a kik gyönyörködnek azokban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 3, 'Dicsőség és méltóság az ő cselekedete, és igazsága megmarad mindvégig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 4, 'Emlékezetet szerzett az ő csudálatos dolgainak; kegyelmes és irgalmas az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 5, 'Eledelt ad az őt félőknek; megemlékezik az ő szövetségéről örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 6, 'Cselekedeteinek erejét tudtul adta az ő népének, nékik adván a pogányok örökségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 7, 'Kezeinek cselekedetei hűség és igazság; minden ő végzése tökéletes.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 8, 'Megingathatlanok örökké és mindvégig; hívségből és egyenességből származottak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 9, 'Váltságot küldött az ő népének, elrendelte szövetségét örökre; szent és rettenetes az ő neve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 10, 'A bölcseség kezdete az Úrnak félelme; jó belátása van mindenkinek, a ki ezt gyakorolja; annak dicsérete megmarad mindvégig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 1, 'Dicsérjétek az Urat. Boldog az ember, a ki féli az Urat, és az ő parancsolataiban igen gyönyörködik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 2, 'Hős lesz annak magva a földön; a hívek nemzedéke megáldatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 3, 'Gazdagság és bőség lesz annak házában, s igazsága mindvégig megmarad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 4, 'Az igazakra világosság fénylik a sötétben: attól a ki irgalmas, kegyelmes és igaz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 5, 'Jó annak az embernek, a ki könyörül és kölcsön ad; dolgait pedig igazán végezi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 6, 'Mivelhogy soha sem ingadoz: örök emlékezetben lesz az igaz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 7, 'Semmi rossz hírtől nem fél; szíve erős, az Úrban bizakodó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 8, 'Rendületlen az ő szíve; nem fél, míglen ellenségeire lenéz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 9, 'Osztogat, adakozik a szegényeknek; igazsága megmarad mindvégig; az ő szarva felemeltetik dicsőséggel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 10, 'Látja ezt a gonosz és dühöng; fogait csikorgatja és eleped; a gonoszok kivánsága semmivé lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, 'Dicsérjétek az Urat. Dicsérjétek az Úrnak szolgái! dicsérjétek az Úrnak nevét,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, 'Áldott legyen az Úr neve mostantól fogva és örökké!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, 'Napkelettől fogva napnyugotig dicsértessék az Úr neve!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, 'Felmagasztaltatott az Úr minden pogány nép felett; dicsősége túl van az egeken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, 'Kicsoda hasonló az Úrhoz, a mi Istenünkhöz, a ki a magasságban lakozik?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, 'A ki magát megalázva, tekint szét mennyen és földön;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, 'A ki felemeli az alacsonyt a porból, és a szűkölködőt kivonszsza a sárból,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, 'Hogy odaültesse őket a főemberek közé, az ő népének főemberei közé;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, 'A ki beülteti a meddőt a házba, mint magzatoknak anyját, nagy örömre. Dicsérjétek az Urat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 1, 'Mikor Izráel népe kijöve Égyiptomból, Jákóbnak házanépe az idegen nép közül:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 2, 'Júda lőn az ő szentséges népe és Izráel az ő királysága.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 3, 'A tenger látá őt és elfutamodék; a Jordán hátrafordula.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 4, 'A hegyek szöknek vala, mint a kosok, s a halmok, mint a juhoknak bárányai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 5, 'Mi a bajod, te tenger, hogy megfutamodál, és te Jordán, hogy hátrafordulál?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 6, 'Hegyek, hogy szöktök vala, mint a kosok? Ti halmok, mint a juhoknak bárányai?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 7, 'Indulj meg te föld az Úr orczája előtt, a Jákób Istene előtt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 8, 'A ki átváltoztatja a kősziklát álló tóvá, és a szirtet vizek forrásává.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 1, 'Nem nékünk Uram, nem nékünk, hanem a te nevednek adj dicsőséget, a te kegyelmedért és hívségedért!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 2, 'Miért mondanák a pogányok: Hol van hát az ő Istenök?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 3, 'Pedig a mi Istenünk az égben van, és a mit akar, azt mind megcselekszi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 4, 'Azoknak bálványa ezüst és arany, emberi kezek munkája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 5, 'Szájok van, de nem szólanak; szemeik vannak, de nem látnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 6, 'Füleik vannak, de nem hallanak; orruk van, de nem szagolnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 7, 'Kezeik vannak, de nem tapintanak, lábaik vannak, de nem járnak, nem szólanak az ő torkukkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 8, 'Hasonlók legyenek azokhoz készítőik, és mindazok, a kik bíznak bennök!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 9, 'Izráel! te az Úrban bízzál; az ilyenek segítsége és paizsa ő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 10, 'Áronnak háza! az Úrban bízzál; az ilyenek segítsége és paizsa ő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 11, 'A kik félitek az Urat, az Úrban bízzatok; az ilyenek segítsége és paizsa ő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 12, 'Az Úr megemlékezik mi rólunk és megáld minket; megáldja Izráel házát, megáldja Áronnak házát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 13, 'Megáldja azokat, a kik félik az Urat, a kicsinyeket és a nagyokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 14, 'Szaporítson titeket az Úr, titeket és a ti fiaitokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 15, 'Áldottai vagytok ti az Úrnak, a ki teremtette a mennyet és a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 16, 'Az egek az Úrnak egei, de a földet az ember fiainak adta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 17, 'Nem a meghaltak dicsérik az Urat, sem nem azok, a kik alászállanak a csendességbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 18, 'De mi áldjuk az Urat mostantól fogva mindörökké. Dicsérjétek az Urat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 1, 'Szeretem az Urat, mert meghallgatja esedezéseim szavát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 2, 'Mert az ő fülét felém fordítja, azért segítségül hívom őt egész életemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 3, 'Körülvettek engem a halál kötelei, és a pokol szorongattatásai támadtak meg engem; nyomorúságba és ínségbe jutottam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 4, 'És az Úrnak nevét segítségül hívám: Kérlek Uram, szabadítsd meg az én lelkemet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 5, 'Az Úr kegyelmes és igaz, és a mi Istenünk irgalmas.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 6, 'Az Úr megőrzi az alázatosokat; én ügyefogyott voltam és megszabadított engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 7, 'Térj meg én lelkem a te nyugodalmadba, mert az Úr jól tett teveled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 8, 'Minthogy megszabadítottad lelkemet a haláltól, szemeimet a könyhullatástól és lábamat az eséstől:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 9, 'Az Úr orczája előtt fogok járni az élőknek földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 10, 'Hittem, azért szóltam; noha igen megaláztatott valék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 11, 'Csüggedezésemben ezt mondtam én: Minden ember hazug.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 12, 'Mivel fizessek az Úrnak minden hozzám való jótéteményéért?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 13, 'A szabadulásért való poharat felemelem, és az Úrnak nevét hívom segítségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 14, 'Az Úr iránt való fogadásaimat megadom az ő egész népe előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 15, 'Az Úr szemei előtt drága az ő kegyeseinek halála.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 16, 'Uram! én bizonyára a te szolgád vagyok; szolgád vagyok én, a te szolgáló leányodnak fia, te oldoztad ki az én köteleimet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 17, 'Néked áldozom hálaadásnak áldozatával, és az Úr nevét hívom segítségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 18, 'Az Úr iránt való fogadásaimat megadom az ő egész népe előtt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 19, 'Az Úr házának tornáczaiban, te benned, oh Jeruzsálem! Dicsérjétek az Urat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'Dicsérjétek az Urat mind, ti pogányok; magasztalják őt mind a népek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'Mert nagy az ő kegyelmessége mi hozzánk, és az Úrnak igazsága megmarad örökké. Dicsérjétek az Urat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'Magasztaljátok az Urat, mert jó, mert örökkévaló az ő kegyelme!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'Mondja hát Izráel, hogy örökkévaló az ő kegyelme!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'Mondja hát az Áron háza, hogy örökkévaló az ő kegyelme!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'Mondják hát, a kik félik az Urat, hogy örökkévaló az ő kegyelme!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'Szükségemben segítségül hívám az Urat, meghallgatott és tágas térre tett engem az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'Velem van az Úr, nem félek; mit árthat nékem ember?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'Velem van az Úr az én segítőim közt, és nézni fogok az én gyűlölőimre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'Jobb az Úrban bízni, mint emberekben reménykedni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'Jobb az Úrban bízni, mint főemberekben reménykedni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'Körülvettek engem mind a pogányok, de az Úr nevében elvesztém őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'Körülvettek, bizony körülvettek engem, de az Úr nevében elvesztém őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'Körülvettek engem, mint méhek; eloltattak, mint tövis-tűz, mert az Úr nevében elvesztém őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, 'Igen taszítottál engem, hogy elessem; de az Úr megsegített engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'Erősségem és énekem az Úr, és ő lőn nékem szabadulásul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, 'Vígasságnak és szabadulásnak szava van az igazak sátoraiban: Az Úrnak jobbkeze hatalmasan cselekedett!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'Az Úrnak jobbkeze felmagasztaltatott; az Úrnak jobbkeze hatalmasan cselekedett!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'Nem halok meg, hanem élek, és hirdetem az Úrnak cselekedeteit!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'Keményen megostorozott engem az Úr; de nem adott át engem a halálnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'Nyissátok meg nékem az igazságnak kapuit, hogy bemenjek azokon és dicsérjem az Urat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, 'Ez az Úrnak kapuja; igazak mennek be azon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, 'Magasztallak téged, hogy meghallgattál, és szabadításomul lettél!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, 'A kő a melyet az építők megvetettek, szegeletkővé lett!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'Az Úrtól lett ez, csodálatos ez a mi szemeink előtt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'Ez a nap az, a melyet az Úr rendelt; örvendezzünk és vígadjunk ezen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, 'Oh Uram, segíts most; oh Uram, adj most jó előmenetelt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, 'Áldott, a ki jő az Úrnak nevében; áldunk titeket, a kik az Úr házából valók vagytok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, 'Isten az Úr és ő világosított meg minket. Kötelekkel kössétek az ünnepi áldozatot az oltár szarvához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, 'Istenem vagy te, azért hálát adok néked! Én Istenem, magasztallak téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'Magasztaljátok az Urat, mert jó; mert örökkévaló az ő kegyelme!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, 'Boldogok, a kiknek útjok feddhetetlen, a kik az Úr törvényében járnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, 'Boldogok, a kik megőrzik az ő bizonyságait, és teljes szívből keresik őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, 'És nem cselekesznek hamisságot; az ő útaiban járnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, 'Te parancsoltad Uram, hogy határozataidat jól megőrizzük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, 'Vajha igazgattatnának az én útaim a te rendeléseid megőrzésére!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, 'Akkor nem szégyenülnék meg, ha figyelnék minden parancsolatodra!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, 'Hálát adok néked tiszta szívből, hogy megtanítottál engem a te igazságod ítéleteire.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, 'A te rendeléseidet megőrzöm; soha ne hagyj el engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, 'Mi módon őrizheti meg tisztán az ifjú az ő útát, ha nem a te beszédednek megtartása által?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, 'Teljes szívből kerestelek téged: ne engedj eltévedeznem a te parancsolataidtól!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, 'Szívembe rejtettem a te beszédedet, hogy ne vétkezzem ellened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, 'Áldott vagy te, Uram! Taníts meg engem a te rendeléseidre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, 'Ajkaimmal hirdetem a te szádnak minden ítéletét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, 'Inkább gyönyörködöm a te bizonyságaidnak útjában, mint minden gazdagságban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, 'A te határozataidról gondolkodom, és a te ösvényeidre nézek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, 'Gyönyörködöm a te rendeléseidben; a te beszédedről nem feledkezem el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, 'Tégy jól a te szolgáddal, hogy éljek és megtartsam a te beszédedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, 'Nyisd meg az én szemeimet, hogy szemléljem a te törvényednek csodálatos voltát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 19, 'Jövevény vagyok e földön, ne rejtsd el tőlem a te parancsolataidat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 20, 'Elfogyatkozik az én lelkem, a te ítéleteid után való szüntelen vágyódás miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 21, 'Megdorgálod a kevélyeket; átkozottak, a kik elhajolnak parancsolataidtól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 22, 'Fordítsd el rólam a szidalmat és gyalázatot, mert megőriztem a te bizonyságaidat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 23, 'Még ha fejedelmek összeülnek, ellenem beszélnek is; a te szolgád a te rendeléseidről gondolkodik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 24, 'A te bizonyságaid én gyönyörűségem, és én tanácsadóim.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 25, 'Lelkem a porhoz tapad; eleveníts meg engem a te igéreted szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 26, 'Útaimat elbeszéltem előtted és te meghallgattál engem; taníts meg a te rendeléseidre!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 27, 'Add értenem a te határozataidnak útát, hogy gondolkodjam a te csodálatos dolgaidról!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 28, 'Sír a lelkem a keserűség miatt; vigasztalj meg a te igéd szerint!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 29, 'A hamisságnak útját távoztasd el tőlem, és a te törvényeddel ajándékozz meg engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 30, 'Az igazság útját választottam; a te ítéleteid forognak előttem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 31, 'Ragaszkodom a te bizonyságaidhoz; Uram, ne hagyj megszégyenülni!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 32, 'A te parancsolataidnak útján járok, ha megvigasztalod az én szívemet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 33, 'Taníts meg Uram a te rendeléseidnek útjára, hogy megőrizzem azt mindvégig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 34, 'Oktass, hogy megőrizzem a te törvényedet, és megtartsam azt teljes szívemből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 35, 'Vezérelj a te parancsolataidnak útján, mert gyönyörködöm abban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 36, 'Hajtsd szívemet a te bizonyságaidhoz, és ne a telhetetlenségre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 37, 'Fordítsd el az én szemeimet, hogy ne lássanak hiábavalóságot; a te útadon éltess engemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 38, 'Teljesítsd igéretedet a te szolgádnak, a ki fél téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 39, 'Fordítsd el tőlem a gyalázatot, a mitől félek; hiszen jók a te ítéleteid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 40, 'Ímé, kivánkozom a te határozataid után; éltess engem a te igazságod által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 41, 'És szálljon reám, Uram, a te kegyelmed, a te szabadításod, a mint megigérted,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 42, 'Hogy megfelelhessek az engem gyalázónak, hiszen bizodalmam van a te igédben!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 43, 'És az igazságnak beszédét se vedd el soha az én számtól, mert várom a te ítéleteidet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 44, 'És megtartom a te törvényedet mindenkor és mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 45, 'És tágas téren járok, mert a te határozataidat keresem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 46, 'És a királyok előtt szólok a te bizonyságaidról, és nem szégyenülök meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 47, 'És gyönyörködöm a te parancsolataidban, a melyeket szeretek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 48, 'És felemelem kezeimet a te parancsolataidra, a melyeket szeretek, és gondolkodom a te rendeléseidről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 49, 'Emlékezzél meg a te szolgádnak adott igédről, a melyhez nékem reménységet adtál!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 50, 'Ez vigasztalásom nyomorúságomban, mert a te beszéded megelevenít engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 51, 'A kevélyek szerfelett gúnyoltak engem; nem hajlottam el a te törvényedtől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 52, 'Megemlékezem a te öröktől fogva való ítéleteidről Uram, és vigasztalódom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 53, 'Harag vett rajtam erőt az istentelenek miatt, a kik elhagyták a te törvényedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 54, 'Ének volt rám nézve minden parancsolatod bujdosásomnak hajlékában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 55, 'Uram! a te nevedről emlékezem éjjel, és megtartom a te törvényedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 56, 'Ez jutott nékem, hogy a te határozataidat megőriztem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 57, 'Azt mondám Uram, hogy az én részem a te beszédeidnek megtartása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 58, 'Teljes szívből könyörgök a te színed előtt: könyörülj rajtam a te igéreted szerint!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 59, 'Meggondoltam az én útaimat, és lábaimat a te bizonyságaidhoz fordítom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 60, 'Sietek és nem mulasztom el, hogy megtartsam a te parancsolataidat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 61, 'Az istentelenek kötelei körülkerítettek engem; de a te törvényedről el nem feledkezem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 62, 'Éjfélkor felkelek, hogy hálát adjak néked, igazságod ítéleteiért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 63, 'Társok vagyok mindazoknak, a kik félnek téged, és a kik határozataidat megtartják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 64, 'A te kegyelmeddel, oh Uram, teljes e föld: taníts meg engem rendeléseidre!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 65, 'Jót cselekedtél a te szolgáddal, Uram, a te igéd szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 66, 'Az okosságnak és tudománynak drága voltára taníts meg engem, mert hiszek a te parancsolataidnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 67, 'Minekelőtte megaláztattam, tévelyegtem vala; most pedig vigyázok a te szódra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 68, 'Jó vagy te és jóltevő, taníts meg engem a te rendeléseidre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 69, 'A kevélyek hazugságot költöttek reám, de én teljes szívből megtartom a te parancsolataidat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 70, 'Kövér az ő szívök, mint a háj; de én a te törvényedben gyönyörködöm.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 71, 'Jó nékem, hogy megaláztál, azért, hogy megtanuljam a te rendeléseidet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 72, 'A te szádnak törvénye jobb nékem, mint sok ezer arany és ezüst.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 73, 'A te kezeid teremtettek és erősítettek meg engem; oktass, hogy megtanuljam parancsolataidat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 74, 'A kik téged félnek, látnak engem és örvendeznek, mivel a te igédben van az én reménységem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 75, 'Tudom Uram, hogy a te ítéleteid igazak, és igazságosan aláztál meg engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 76, 'Legyen velem a te kegyelmed, hogy megvígasztalódjam a te szolgádnak tett igéreted szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 77, 'Szálljon reám a te irgalmasságod, hogy éljek, mert a te törvényedben gyönyörködöm.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 78, 'Szégyenüljenek meg a kevélyek, a kik csalárdul elnyomtak engem, holott én a te határozataidról gondolkodom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 79, 'Forduljanak hozzám, a kik téged félnek, és ismerik a te bizonyságaidat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 80, 'Legyen az én szívem feddhetetlen a te rendeléseidben, hogy meg ne szégyenüljek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 81, 'Elfogyatkozik az én lelkem a te szabadításod kivánása miatt; a te igédben van az én reménységem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 82, 'A te beszéded kivánása miatt elfogyatkoznak az én szemeim, mondván: mikor vígasztalsz meg engem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 83, 'Noha olyanná lettem, mint a füstön levő tömlő; a te rendeléseidről el nem feledkezem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 84, 'Mennyi a te szolgádnak napja, és mikor tartasz ítéletet az én üldözőim felett?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 85, 'Vermet ástak nékem a kevélyek, a kik nem a te törvényed szerint élnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 86, 'Minden parancsolatod igaz; csalárdul üldöznek engem; segíts meg engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 87, 'Csaknem semmivé tettek engem e földön, de én nem hagytam el a te határozataidat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 88, 'A te kegyelmed szerint eleveníts meg engem, hogy megőrizhessem a te szádnak bizonyságait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 89, 'Uram! örökké megmarad a te igéd a mennyben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 90, 'Nemzedékről nemzedékre van a te igazságod, te erősítetted meg a földet és áll az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 91, 'A te ítéleteid szerint áll minden ma is; mert minden, a mi van, te néked szolgál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 92, 'Ha nem a te törvényed lett volna az én gyönyörűségem, akkor elvesztem volna az én nyomorúságomban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 93, 'Soha sem feledkezem el a te határozataidról, mert azok által elevenítettél meg engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 94, 'Tied vagyok, tarts meg engem, mert a te határozataidat keresem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 95, 'Vártak rám a gonoszok, hogy elveszessenek, de én a te bizonyságaidra figyelek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 96, 'Látom, minden tökéletes dolognak vége van, de a te parancsolatodnak nincs határa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 97, 'Mely igen szeretem a te törvényedet, egész napestig arról gondolkodom!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 98, 'Az én ellenségeimnél bölcsebbé teszel engem a te parancsolataiddal, mert mindenkor velem vannak azok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 99, 'Minden tanítómnál értelmesebb lettem, mert a te bizonyságaid az én gondolataim.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 100, 'Előrelátóbb vagyok, mint az öreg emberek, mert vigyázok a te határozataidra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 101, 'Minden gonosz ösvénytől visszatartóztattam lábaimat, hogy megtartsam a te beszédedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 102, 'Nem távoztam el a te ítéleteidtől, mert te oktattál engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 103, 'Mily édes az én ínyemnek a te beszéded; méznél édesbb az az én számnak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 104, 'A te határozataidból leszek értelmes, gyűlölöm azért a hamisságnak minden ösvényét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, 'Az én lábamnak szövétneke a te igéd, és ösvényemnek világossága.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, 'Megesküdtem és megállom, hogy megtartom a te igazságodnak ítéleteit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 107, 'Felette nagy nyomorúságban vagyok; Uram, eleveníts meg a te igéd szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 108, 'Szájamnak önkéntes áldozatai legyenek kedvesek előtted Uram! és taníts meg a te ítéleteidre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 109, 'Lelkem mindig veszedelemben van, mindazáltal a te törvényedről el nem feledkezem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 110, 'Tőrt vetettek ellenem az istentelenek, de a te határozataidtól el nem tévelyedtem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 111, 'A te bizonyságaid az én örökségem mindenha, mert szívemnek örömei azok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 112, 'Az én szívem hajlik a te rendeléseid teljesítésére mindenha és mindvégig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 113, 'Az állhatatlanokat gyűlölöm, de a te törvényedet szeretem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 114, 'Menedékem és paizsom vagy te; igédben van az én reménységem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 115, 'Távozzatok tőlem gonoszok, hogy megőrizzem az én Istenemnek parancsolatait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 116, 'Támogass engem a te beszéded szerint, hogy éljek, és ne engedd, hogy megszégyenüljek reménységemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 117, 'Segélj, hogy megmaradjak, és gyönyörködjem a te rendeléseidben szüntelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 118, 'Megtapodod mindazokat, a kik rendeléseidtől elhajolnak, mert az ő álnokságuk hazugság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 119, 'Mint salakot mind elveted e földnek istenteleneit, azért szeretem a te bizonyságaidat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 120, 'Borzad testem a tőled való félelem miatt, és félek a te ítéleteidtől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 121, 'Méltányosságot és igazságot cselekedtem; ne adj át nyomorgatóimnak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 122, 'Légy kezes a te szolgádért az ő javára, hogy a kevélyek el ne nyomjanak engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 123, 'Szemeim epekednek a te szabadításod és a te igazságod beszéde után.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 124, 'Cselekedjél a te szolgáddal a te kegyelmességed szerint, és a te rendeléseidre taníts meg engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 125, 'Szolgád vagyok, oktass, hogy megismerjem a te bizonyságaidat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 126, 'Ideje, hogy az Úr cselekedjék; megrontották a te törvényedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 127, 'Inkább szeretem azért a te parancsolataidat, mint az aranyat, mint a legtisztább aranyat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 128, 'Igaznak tartom azért minden határozatodat, és a hamisságnak minden ösvényét gyűlölöm.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, 'Csodálatosak a te bizonyságaid, azért az én lelkem megőrzi azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, 'A te beszéded megnyilatkozása világosságot ad, és oktatja az együgyűeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 131, 'Szájamat feltátom és lihegek, mert kivánom a te parancsolataidat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 132, 'Tekints reám és könyörülj rajtam, a miképen szoktál a te nevednek kedvelőin.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 133, 'Vezéreld útamat a te igéd szerint, és ne engedd, hogy valami hamisság uralkodjék rajtam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 134, 'Oltalmazz meg az emberek erőszakosságától, hogy megőrizzem a te határozataidat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 135, 'A te orczádat világosítsd meg a te szolgádon, és taníts meg a te rendeléseidre!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 136, 'Víznek folyásai erednek az én szemeimből azok miatt, a kik nem tartják meg a te törvényedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 137, 'Igaz vagy Uram, és a te ítéleted igazságos.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 138, 'A te bizonyságaidat igazságban és hűségben jelentetted meg, és mindenek felett való egyenességben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 139, 'Buzgóságom megemészt engem, mert elfeledkeztek a te beszédedről az én ellenségeim.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 140, 'Felettébb tiszta a te beszéded, és a te szolgád szereti azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 141, 'Kicsiny vagyok én és megvetett, de a te határozataidról el nem feledkezem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 142, 'A te igazságod igazság örökké, és a te törvényed igaz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 143, 'Nyomorúság és keserűség ért engem, de a te parancsolataid gyönyörűségeim nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 144, 'A te bizonyságaidnak igazsága örökkévaló; oktass, hogy éljek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 145, 'Teljes szívből kiáltok hozzád, hallgass meg, Uram! megtartom a te rendeléseidet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 146, 'Segítségül hívlak: tarts meg engem, és megőrzöm a te bizonyságaidat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 147, 'Hajnal előtt felkelek, kiáltok hozzád; a te beszédedben van reménységem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 148, 'Szemeim megelőzik az éjjeli őrséget, hogy a te beszédedről gondolkodjam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 149, 'Hallgasd meg az én szómat a te kegyelmességed szerint, Uram! Eleveníts meg a te jóvoltod szerint!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 150, 'Közelgetnek hozzám az én gonosz háborgatóim, a kik a te törvényedtől messze távoztak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 151, 'Közel vagy te, Uram! és minden te parancsolatod igazság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 152, 'Régtől fogva tudom a te bizonyságaid felől, hogy azokat örökké állandókká tetted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 153, 'Lásd meg az én nyomorúságomat és szabadíts meg engem; mert a te törvényedről nem felejtkezem el!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 154, 'Te perelj peremben és ments meg; a te beszéded szerint eleveníts meg engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 155, 'Távol van a gonoszoktól a szabadítás, mert nem törődnek a te rendeléseiddel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 156, 'Nagy a te irgalmasságod, Uram! A te ítéletid szerint eleveníts meg engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 157, 'Sokan vannak az én háborgatóim és üldözőim, de nem térek el a te bizonyságaidtól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 158, 'Láttam a hűteleneket és megundorodtam, hogy a te mondásodat meg nem tartják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 159, 'Lásd meg Uram, hogy a te határozataidat szeretem; a te kegyelmességed szerint eleveníts meg engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 160, 'A te igédnek summája igazság, és a te igazságod ítélete mind örökkévaló.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 161, 'A fejedelmek ok nélkül üldöztek engem; de a te igédtől félt az én szívem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 162, 'Gyönyörködöm a te beszédedben, mint a ki nagy nyereséget talált.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 163, 'A hamisságot gyűlölöm és útálom; a te törvényedet szeretem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 164, 'Naponként hétszer dicsérlek téged, a te igazságodnak ítéleteiért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 165, 'A te törvényed kedvelőinek nagy békességök van, és nincs bántódásuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 166, 'Várom a te szabadításodat, oh Uram! és a te parancsolataidat cselekszem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 167, 'Az én lelkem megtartja a te bizonyságaidat, és azokat igen szeretem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 168, 'Megtartom a te határozataidat és bizonyságaidat, mert minden útam nyilván van előtted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 169, 'Oh Uram! hadd szálljon az én könyörgésem a te színed elé; tégy bölcscsé engem a te igéd szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 170, 'Jusson elődbe az én imádságom; a te beszéded szerint szabadíts meg engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 171, 'Ajkaim dicséretet zengjenek, mert megtanítasz a te rendeléseidre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 172, 'Nyelvem a te beszédedről énekel, mert minden parancsolatod igaz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 173, 'Legyen segítségemre a te kezed, mert a te határozataidat választottam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 174, 'Uram! vágyódom a te szabadításod után, és a te törvényed nékem gyönyörűségem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 175, 'Éljen az én lelkem, hogy dicsérjen téged, és a te ítéleteid segítsenek rajtam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 176, 'Tévelygek, mint valami elveszett juh: keresd meg a te szolgádat; mert a te parancsolataidat nem felejtettem el!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, 'Grádicsok éneke. Nyomorúságomban az Úrhoz kiálték, és meghallgata engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, 'Mentsd meg, Uram, lelkemet a hazug ajaktól és a csalárd nyelvtől!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, 'Mit adjanak néked, vagy mit nyujtsanak néked, te csalárd nyelv?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, 'Vitéznek hegyes nyilait fenyőfa parázsával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, 'Jaj nékem, hogy Mésekben bujdosom és a Kédár sátrai közt lakom!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, 'Sok ideje lakozik az én lelkem a békességnek gyűlölőivel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, 'Magam vagyok a békesség, de mihelyt megszólalok, ők viadalra készek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, 'Grádicsok éneke. Szemeimet a hegyekre emelem, onnan jön az én segítségem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, 'Az én segítségem az Úrtól van, a ki teremtette az eget és földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, 'Nem engedi, hogy lábad inogjon; nem szunnyad el a te őriződ.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, 'Ímé, nem szunnyad és nem alszik az Izráelnek őrizője!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, 'Az Úr a te őriződ, az Úr a te árnyékod a te jobbkezed felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, 'Nappal a nap meg nem szúr téged, sem éjjel a hold.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, 'Az Úr megőriz téged minden gonosztól, megőrzi a te lelkedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, 'Megőrzi az Úr a te ki- és bemeneteledet, mostantól fogva mindörökké!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 1, 'Grádicsok éneke, Dávidtól. Örvendezek, mikor mondják nékem: Menjünk el az Úr házába!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 2, 'Ott álltak a mi lábaink a te kapuidban, oh Jeruzsálem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 3, 'Jeruzsálem, te szépen épült, mint a jól egybeszerkesztett város!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 4, 'A hová feljárnak a nemzetségek, az Úrnak nemzetségei, bizonyságul Izráelnek, az Úr nevének tiszteletére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 5, 'Mert ott ülnek az ítélőszékek, Dávid házának székei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 6, 'Könyörögjetek Jeruzsálem békességéért; legyenek boldogok a téged szeretők!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 7, 'Békesség legyen a te várfalaid között, csendesség a te palotáidban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 8, 'Atyámfiaiért és barátaimért hadd mondhassam: béke veled!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 9, 'Az Úrnak, a mi Istenünknek házáért hadd kivánhassak jót tenéked!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 1, 'Grádicsok éneke. Hozzád emelem szemeimet, oh te egekben lakozó!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 2, 'Ímé, mint a szolgák szemei uroknak kezére, mint a szolgalány szemei asszonya kezére: úgy néznek szemeink az Úrra, a mi Istenünkre, mígnem megkönyörül rajtunk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 3, 'Könyörülj rajtunk, Uram, könyörülj rajtunk! Mert igen elteltünk gyalázattal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 4, 'Lelkünk igen eltelt a gazdagok csúfolkodásával, és a kevélyek gyalázkodásával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 1, 'Grádicsok éneke, Dávidtól. Ha nem az Úr az, a ki velünk volt, így szóljon Izráel,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 2, 'Ha nem az Úr az, a ki velünk volt, mikor ránk támadtak az emberek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 3, 'Akkor elevenen nyeltek volna el minket, a mint felgerjedt haragjok ellenünk;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 4, 'Akkor elborítottak volna minket a vizek, patak futott volna át felettünk;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 5, 'Akkor átfutottak volna rajtunk a felbőszült vizek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 6, 'Áldott az Úr, a ki nem adott minket fogaik prédájául!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 7, 'Lelkünk megszabadult, mint a madár, a madarásznak tőréből. A tőr elszakadt, mi pedig megszabadultunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 8, 'A mi segítségünk az Úr nevében van, a ki teremtette az eget és földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 1, 'Grádicsok éneke. A kik bíznak az Úrban, olyanok, mint a Sion hegye, a mely meg nem inog, örökké megáll.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 2, 'Jeruzsálemet hegyek veszik körül, az Úr pedig körülveszi az ő népét mostantól fogva mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 3, 'Mert nem pihen meg a gonoszság pálczája az igazak részén, hogy rosszra ne nyújtsák ki kezeiket az igazak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 4, 'Tégy jól, Uram, a jókkal, és a szívök szerint igazakkal!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 5, 'A görbe utakra tévedezőket pedig ragadtassa el az Úr, együtt a gonosztevőkkel; békesség legyen Izráelen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, 'Grádicsok éneke. Mikor visszahozta az Úr Sionnak foglyait, olyanok voltunk, mint az álmodók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, 'Akkor megtelt a szánk nevetéssel, nyelvünk pedig vígadozással. Akkor így szóltak a pogányok: Hatalmasan cselekedett ezekkel az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, 'Hatalmasan cselekedett velünk az Úr, azért örvendezünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, 'Hozd vissza, Uram, a mi foglyainkat, mint patakokat a déli földön!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, 'A kik könyhullatással vetnek, vígadozással aratnak majd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, 'A ki vetőmagját sírva emelve megy tova, vígadozással jő elő, kévéit emelve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 1, 'Grádicsok éneke Salamontól. Ha az Úr nem építi a házat, hiába dolgoznak azon annak építői. Ha az Úr nem őrzi a várost, hiába vigyáz az őriző.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 2, 'Hiába néktek korán felkelnetek, későn feküdnötök, fáradsággal szerzett kenyeret ennetek! Szerelmesének álmában ád eleget.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 3, 'Ímé, az Úrnak öröksége, a fiak; az anyaméh gyümölcse: jutalom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 4, 'Mint a nyilak a hősnek kezében, olyanok a serdülő fiak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 5, 'Boldog ember, a ki ilyenekkel tölti meg tegzét; nem szégyenülnek meg, ha ellenséggel szólnak a kapuban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 1, 'Grádicsok éneke. Mind boldog az, a ki féli az Urat; a ki az ő útaiban jár!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 2, 'Bizony, kezed munkáját eszed! Boldog vagy és jól van dolgod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 3, 'Feleséged, mint a termő szőlő házad belsejében; fiaid, mint az olajfacsemeték asztalod körül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 4, 'Ímé, így áldatik meg a férfiú, a ki féli az Urat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 5, 'Megáld téged az Úr a Sionról, hogy boldognak lássad Jeruzsálemet életednek minden idejében;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 6, 'És meglássad fiaidnak fiait; békesség legyen Izráelen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 1, 'Grádicsok éneke. Sokat szorongattak engem ifjúságom óta! mondja most Izráel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 2, 'Sokat szorongattak engem ifjúságom óta, még sem bírtak velem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 3, 'Szántók szántottak hátamon, hosszúra nyujtották barázdáikat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 4, 'Igaz az Úr! Elszaggatja a gonoszok kötelét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 5, 'Megszégyenülnek és hátraszorulnak mindazok, a kik gyűlölik a Siont.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 6, 'Olyanok lesznek, mint a háztetőn a fű, a mely kiszárad, mielőtt letépnék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 7, 'A melyet sem arató nem szed markába, sem kévekötő az ölébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 8, 'Az átutazók se mondják: Az Úr áldása rátok! Áldunk benneteket az Úrnak nevében!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 1, 'Grádicsok éneke. A mélységből kiáltok hozzád, Uram!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 2, 'Uram, hallgasd meg az én szómat; legyenek füleid figyelmetesek könyörgő szavamra!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 3, 'Ha a bűnöket számon tartod, Uram: Uram, kicsoda maradhat meg?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 4, 'Hiszen te nálad van a bocsánat, hogy féljenek téged!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 5, 'Várom az Urat, várja az én lelkem, és bízom az ő igéretében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 6, 'Várja lelkem az Urat, jobban, mint az őrök a reggelt, az őrök a reggelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 7, 'Bízzál Izráel az Úrban, mert az Úrnál van a kegyelem, és bőséges nála a szabadítás!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 8, 'Meg is szabadítja ő Izráelt minden ő bűnéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 1, 'Grádicsok éneke; Dávidtól. Uram, nem fuvalkodott fel az én szívem, szemeim sem láttak magasra, és nem jártam nagy dolgok után, erőmet haladó csodadolgok után;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 2, 'Sőt lecsendesítém és elnémítám lelkemet. A milyen az elválasztott gyermek az anyjánál; mint az elválasztott gyermek, olyan bennem az én lelkem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 3, 'Bízzál Izráel az Úrban mostantól fogva mindörökké!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 1, 'Grádicsok éneke. Emlékezzél meg, Uram, Dávid minden nyomorúságáról;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 2, 'A ki megesküdt az Úrnak, fogadást tőn a Jákób Istenének:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 3, 'Nem megyek be sátoros házamba, nem hágok fel háló-nyoszolyámba;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 4, 'Nem bocsátok álmot szemeimre s pilláimra szendert;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 5, 'Míg helyet nem találok az Úrnak, Jákób Istenének hajlékot!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 6, 'Ímé, hallottunk róla Efratában; rátaláltunk Jaar térségein:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 7, 'Hadd menjünk be az ő hajlékaiba, boruljunk le lábainak zsámolyához!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 8, 'Indulj Uram, a te nyugvóhelyedre: te és a te hatalmadnak ládája!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 9, 'Papjaid öltözködjenek igazságba, kegyeltjeid pedig örvendezzenek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 10, 'Dávidért, a te szolgádért, ne fordulj el felkented színétől!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 11, 'Hűséget esküdött az Úr Dávidnak, nem tér el attól: Ágyékod gyümölcsét ültetem székedbe;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 12, 'Ha megtartják fiaid szövetségemet és bizonyságomat, a melyekre megtanítom őket, fiaik is mindörökké székedben ülnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 13, 'Mert a Siont választotta ki az Úr, azt szerette meg magának lakhelyül:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 14, 'Ez lesz nyugovóhelyem örökre; itt lakozom, mert ezt szeretem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 15, 'Eleséggel megáldom gazdagon, szegényeit jóltartom kenyérrel;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 16, 'Papjait meg felruházom szabadítással, és vígan örvendeznek kegyeltjei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 17, 'Megnövesztem ott Dávidnak hatalmát, szövétneket szerzek az én felkentemnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 18, 'Ellenségeire szégyent borítok, rajta pedig koronája ragyog.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, 'Grádicsok éneke Dávidtól. Ímé, mily jó és mily gyönyörűséges, a mikor együtt lakoznak az atyafiak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, 'Mint a drága olaj a fejen, a mely aláfoly a szakállon, az Áron szakállán; a mely lefoly köntöse prémjére;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, 'Mint a Hermon harmatja, a mely leszáll Sion hegyeire. Csak oda küld áldást az Úr és életet örökké!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, 'Grádicsok éneke. Nosza, áldjátok az Urat mind, ti szolgái az Úrnak, a kik az Úr házában álltok éjjelente!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, 'Emeljétek fel kezeiteket a szenthelyen, és áldjátok az Urat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, 'Áldjon meg téged az Úr a Sionról, a ki teremtette az eget és a földet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 1, 'Dicsérjétek az Urat! Dicsérjétek az Úrnak nevét, dicsérjétek szolgái az Úrnak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 2, 'A kik álltok az Úrnak házában, Istenünk házának pitvaraiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 3, 'Dicsérjétek az Urat, mert jó az Úr; zengjétek nevét, mert gyönyörűséges!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 4, 'Mert kiválasztá magának az Úr Jákóbot, Izráelt a saját örökségéül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 5, 'Én bizony tudom, hogy nagy az Úr, és a mi Urunk minden istennél különb.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 6, 'Mind megteszi az Úr, a mit akar: az egekben és a földön, a vizekben és minden mélységben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 7, 'Felemeli a felhőket a földnek széléről; villámlást készít, hogy eső legyen, s szelet hoz elő tárházaiból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 8, 'A ki megverte Égyiptom elsőszülötteit, az emberétől a baroméig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 9, 'Jeleket és csodákat küldött rád, oh Égyiptom, Faraóra és összes szolgáira.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 10, 'A ki megvert sok népet, és megölt erős királyokat:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 11, 'Szíhont, az Emoreusok királyát, meg Ógot, a Básán királyát, és Kanaánnak minden királyát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 12, 'És odaadta földüket örökségül; örökségül saját népének, Izráelnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 13, 'Uram! Örökkévaló a te neved; nemzedékről nemzedékre emlegetnek téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 14, 'Mert birája az Úr az ő népének, és könyörületes az ő szolgái iránt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 15, 'A pogányok bálványai ezüst és arany, emberi kezek alkotásai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 16, 'Szájok van, de nem beszélnek, szemeik vannak, de nem látnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 17, 'Füleik vannak, de nem hallanak, és lehellet sincsen szájokban!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 18, 'Hasonlók lesznek hozzájuk alkotóik is, és mindazok, a kik bíznak bennök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 19, 'Izráel háznépe: áldjátok az Urat! Áronnak háznépe: áldjátok az Urat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 20, 'Lévinek háznépe: áldjátok az Urat! Kik félik az Urat: áldjátok az Urat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 21, 'Áldott az Úr a Sionon, a ki Jeruzsálemben lakozik! Dicsérjétek az Urat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 1, 'Magasztaljátok az Urat, mert jó; mert örökkévaló az ő kegyelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 2, 'Magasztaljátok az istenek Istenét; mert örökkévaló az ő kegyelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 3, 'Magasztaljátok az uraknak Urát; mert örökkévaló az ő kegyelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 4, 'A ki nagy csodákat művel egyedül; mert örökkévaló az ő kegyelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 5, 'A ki teremtette az egeket bölcseséggel; mert örökkévaló az ő kegyelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 6, 'A ki kiterjesztette a földet a vizek fölé; mert örökkévaló az ő kegyelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 7, 'A ki teremtette a nagy világító testeket; mert örökkévaló az ő kegyelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 8, 'A napot, hogy uralkodjék nappal; mert örökkévaló az ő kegyelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 9, 'A holdat és csillagokat, hogy uralkodjanak éjszaka; mert örökkévaló az ő kegyelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 10, 'A ki megverte az égyiptomiakat elsőszülötteikben; mert örökkévaló az ő kegyelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 11, 'A ki kihozta Izráelt azok közül; mert örökkévaló az ő kegyelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 12, 'Hatalmas kézzel és kifeszített karral; mert örökkévaló az ő kegyelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 13, 'A ki kétfelé választotta a veres tengert; mert örökkévaló az ő kegyelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 14, 'És átvitte Izráelt annak közepén; mert örökkévaló az ő kegyelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 15, 'Faraót pedig és seregét a veres tengerbe meríté; mert örökkévaló az ő kegyelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 16, 'A ki vezérlette népét a pusztában; mert örökkévaló az ő kegyelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 17, 'A ki nagy királyokat vert le; mert örökkévaló az ő kegyelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 18, 'És megvert hatalmas királyokat; mert örökkévaló az ő kegyelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 19, 'Szíhont, az Emoreusok királyát; mert örökkévaló az ő kegyelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 20, 'Meg Ógot, a Básán királyát; mert örökkévaló az ő kegyelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 21, 'És örökségül adta az ő földjüket; mert örökkévaló az ő kegyelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 22, 'Örökségül szolgájának, az Izráelnek; mert örökkévaló az ő kegyelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 23, 'A ki megemlékezett rólunk alacsonyságunkban; mert örökkévaló az ő kegyelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 24, 'És megszabadított minket elleneinktől; mert örökkévaló az ő kegyelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 25, 'A ki eledelt ad minden testnek; mert örökkévaló az ő kegyelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 26, 'Magasztaljátok az egek Istenét; mert örökkévaló az ő kegyelme!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 1, 'Babilon folyóvizeinél, ott ültünk és sírtunk, mikor a Sionról megemlékezénk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 2, 'A fűzfákra, közepette, oda függesztettük hárfáinkat,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 3, 'Mert énekszóra nógattak ott elfogóink, kínzóink pedig víg dalra, mondván: Énekeljetek nékünk a Sion énekei közül!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 4, 'Hogyan énekelnők az Úrnak énekét idegen földön?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 5, 'Ha elfelejtkezem rólad, Jeruzsálem felejtkezzék el rólam az én jobbkezem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 6, 'Nyelvem ragadjon az ínyemhez, ha meg nem emlékezem rólad; ha nem Jeruzsálemet tekintem az én vígasságom fejének!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 7, 'Emlékezzél meg, Uram, az Edom fiairól, a kik azt mondták Jeruzsálem napján: Rontsátok le, rontsátok le fenékig!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 8, 'Babilon leánya, te pusztulóra vált! Áldott legyen a ki megfizet néked gonoszságodért, a melylyel te fizettél nékünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 9, 'Áldott legyen, a ki megragadja és sziklához paskolja kisdedeidet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 1, 'Dávidé. Magasztallak téged teljes szívemből; énekkel áldlak az istenek előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 2, 'Szent templomod felé hajolok, s magasztalom nevedet kegyelmedért és igazságodért; mert minden neveden felül felmagasztalád a te beszédedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 3, 'Mikor kiáltottam, meghallgattál engem, felbátorítottál engem, lelkemben erő támadt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 4, 'Magasztal téged, Uram, e földnek minden királya, mikor meghallják szádnak beszédeit,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 5, 'És énekelnek az Úrnak útairól, mert nagy az Úr dicsősége!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 6, 'Noha felséges az Úr, mégis meglátja az alázatost, a kevélyt pedig távolról ismeri.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 7, 'Ha nyomorúságban vergődöm, megelevenítesz; ellenségeim haragja ellen kinyújtod kezedet, és a te jobbkezed megment engemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 8, 'Elvégzi értem az Úr. Uram, a te kegyelmed örökkévaló: ne hagyd el a te kezeidnek alkotásait!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, 'Az éneklőmesternek, Dávid zsoltára. Uram, megvizsgáltál engem, és ismersz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, 'Te ismered ülésemet és felkelésemet, messziről érted gondolatomat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, 'Járásomra és fekvésemre ügyelsz, minden útamat jól tudod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, 'Mikor még nyelvemen sincs a szó, immár egészen érted azt Uram!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, 'Elől és hátul körülzártál engem, és fölöttem tartod kezedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, 'Csodálatos előttem e tudás, magasságos, nem érthetem azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, 'Hová menjek a te lelked elől és a te orczád elől hova fussak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, 'Ha a mennybe hágok fel, ott vagy; ha a Seolba vetek ágyat, ott is jelen vagy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, 'Ha a hajnal szárnyaira kelnék, és a tenger túlsó szélére szállanék:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, 'Ott is a te kezed vezérelne engem, és a te jobbkezed fogna engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, 'Ha azt mondom: A sötétség bizonyosan elborít engem és a világosság körülöttem éjszaka lesz,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, 'A sötétség sem borít el előled, és fénylik az éjszaka, mint a nappal; a sötétség olyan, mint a világosság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, 'Bizony te alkottad veséimet, te takargattál engem anyám méhében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, 'Magasztallak, hogy csodálatosan megkülönböztettél. Csodálatosak a te cselekedeteid! és jól tudja ezt az én lelkem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, 'Nem volt elrejtve előtted az én csontom, mikor titokban formáltattam és idomíttattam, mintegy a föld mélyében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, 'Látták szemeid az én alaktalan testemet, és könyvedben ezek mind be voltak írva: a napok is, a melyeken formáltatni fognak; holott egy sem volt még meg közülök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, 'És nékem milyen kedvesek a te gondolataid, oh Isten! Mily nagy azoknak summája!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, 'Számlálgatom őket: többek a fövénynél; felserkenek s mégis veled vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, 'Vajha elvesztené Isten a gonoszt! Vérszopó emberek, fussatok el tőlem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, 'A kik gonoszul szólnak felőled, és nevedet hiába veszik fel, a te ellenségeid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, 'Ne gyűlöljem-é, Uram, a téged gyűlölőket? Az ellened lázadókat ne útáljam-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, 'Teljes gyűlölettel gyűlölöm őket, ellenségeimmé lettek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, 'Vizsgálj meg engem, oh Isten, és ismerd meg szívemet! Próbálj meg engem, és ismerd meg gondolataimat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, 'És lásd meg, ha van-e nálam a gonoszságnak valamilyen útja? és vezérelj engem az örökkévalóság útján!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 1, 'Az éneklőmesternek, Dávid zsoltára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 2, 'Szabadíts meg engem, Uram, a gonosz embertől; a zsarnok férfitól védj meg engemet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 3, 'A kik gonoszt gondolnak szívökben, és minden nap háborút kezdenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 4, 'Nyelvöket élesítik, mint a kígyó; áspiskígyó mérge van ajkaik alatt. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 5, 'Ments meg, oh Uram, a gonosz kezétől; a zsarnok férfitól védj meg engemet! A kik megejteni szándékoznak lépéseimet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 6, 'Tőrt hánytak elém titkon a kevélyek és köteleket; hálót terítettek ösvényem szélére, hurkokat vetettek elém! Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 7, 'Mondám az Úrnak: Istenem vagy te! Hallgasd meg Uram könyörgésem szavát!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 8, 'Én Uram, Istenem, szabadításom ereje: fedezd be fejemet a háború napján!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 9, 'Ne add meg Uram, a mit a gonosz kíván; rossz szándékát ne segítsd elő, mert felfuvalkodik! Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 10, 'A körültem ólálkodóknak fejét borítsa be ajkaiknak átka.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 11, 'Eleven szenek hulljanak reájok; tűzbe vesse őket, örvényekbe, fel ne keljenek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 12, 'A nyelves ember meg ne maradjon e földön; a zsarnok embert űzze a veszedelem, míg nyaka szakad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 13, 'Tudom, hogy felfogja az Úr a szegények ügyét, a nyomorultaknak jogát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 14, 'Csak az igazak magasztalják a te nevedet, s orczád előtt lakoznak az igazságosak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 1, 'Dávid zsoltára. Uram! hívlak téged: siess én hozzám; figyelmezz szavamra, mikor hívlak téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 2, 'Mint jóillatú füst jusson elődbe imádságom, s kezem felemelése estvéli áldozat legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 3, 'Tégy Uram závárt az én szájamra; őriztessed az én ajkaim nyílását!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 4, 'Ne engedd szívemet rosszra hajlani, hogy istentelenül ne cselekedjem a gonosztevő emberekkel egybe; és ne egyem azoknak kedvelt ételéből!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 5, 'Ha igaz fedd engem: jól van az; ha dorgál engem: mintha fejem kenné. Nem vonakodik fejem, sőt még imádkozom is értök nyavalyájokban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 6, 'Ha sziklához paskoltatnak az ő bíráik, akkor hallgatják az én beszédeimet, mert gyönyörűségesek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 7, 'Mint a ki a földet vágja és hányja, úgy szóratnak szét csontjaik a Seol torkában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 8, 'De az én szemeim, Uram Isten, rajtad csüggenek; hozzád folyamodom: ne oltsd el életemet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 9, 'Őrizz meg a tőrtől, a mit elém hánytak, és a gonosztevőknek hálóitól!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 10, 'Essenek az álnokok saját tőreikbe; míg én egyben általmegyek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 1, 'Dávid tanítása; imádság a barlangban létekor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 2, 'Fenszóval hívom az Urat, fenszóval könyörgök az Úrhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 3, 'Kiöntöm előtte panaszomat, kitárom előtte nyomorúságomat,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 4, 'Mikor elcsügged bennem a lelkem. Te pedig tudod az én ösvényemet, hogy az úton, a melyen járok, tőrt hánytak elém.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 5, 'Tekints jobbra és lásd meg, hogy senki sincsen, a ki ismerne; nincsen számomra menedék; senki sem tudakozódik felőlem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 6, 'Hívlak téged, oh Uram; s ezt mondom: Te vagy oltalmam és örökségem az élőknek földén;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 7, 'Figyelmezz esedezésemre, mert igen nyomorult vagyok! Szabadíts meg engem üldözőimtől, mert hatalmasabbak nálamnál!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 8, 'Vezesd ki lelkemet a börtönből, hogy magasztaljam a te nevedet! Az igazak vegyenek engem körül, mikor jól teszel majd velem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, 'Dávid zsoltára. Uram, hallgasd meg könyörgésemet, figyelmezzél imádságomra; hűséged és igazságod szerint hallgass meg engemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, 'Ne szállj perbe a te szolgáddal, mert egy élő sem igaz előtted!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, 'Ímé, ellenség üldözi lelkemet, a földhöz paskolja éltemet; betaszít engem a sötétségbe a milyen a régen megholtaké!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, 'Elcsügged bennem a lelkem, felháborodik bennem a szívem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, 'Megemlékezem a régi időkről, elgondolom minden te dolgodat; kezed munkáiról elmélkedem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, 'Feléd terjesztgetem kezeimet; lelkem, mint szomjú föld, úgy eped utánad. Szela.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, 'Siess, hallgass meg engem Uram! Elfogyatkozik az én lelkem. Ne rejtsd el orczádat előlem, hogy ne legyek hasonló a sírba szállókhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, 'Korán hallasd velem kegyelmedet, mert bízom benned! Mutasd meg nékem az útat, melyen járjak, mert hozzád emelem lelkemet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, 'Szabadíts meg engem ellenségeimtől, Uram; hozzád menekülök!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, 'Taníts meg engem a te akaratodat teljesítenem, mert te vagy Istenem! A te jó lelked vezéreljen engem az egyenes földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, 'Eleveníts meg engem, Uram, a te nevedért; vidd ki lelkemet a nyomorúságból a te igazságodért!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, 'És kegyelmedből rontsd meg ellenségeimet, és veszítsd el mindazokat, a kik szorongatják lelkemet; mert szolgád vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 1, 'Dávidé. Áldott az Úr, az én kőváram, a ki hadakozásra tanítja kezemet, s viadalra az én ujjaimat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 2, 'Jóltevőm és megoltalmazóm, mentőváram és szabadítóm nékem; paizsom, és az, a kiben én bízom: ő veti alám népemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 3, 'Uram! Micsoda az ember, hogy tudsz felőle, és az embernek fia, hogy gondod van reá?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 4, 'Olyan az ember, mint a lehellet; napjai, mint az átfutó árnyék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 5, 'Uram, hajlítsd meg egeidet és szállja alá; illesd meg a hegyeket, hogy füstölögjenek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 6, 'Lövelj villámot és hányd szerte őket; bocsásd ki nyilaidat és vedd el eszöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 7, 'Nyújtsd le kezeidet a magasból; ragadj ki és ments meg engem a nagy vizekből, az idegen-fiak kezéből;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 8, 'A kiknek szájok hazugságot beszél, s jobb kezök a hamisság jobb keze.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 9, 'Isten! Új éneket éneklek néked; tízhúrú hangszerrel zengedezlek téged;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 10, 'Ki segítséget ád a királyoknak, s megmenti Dávidot, az ő szolgáját a gonosz szablyától.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 11, 'Ragadj ki és ments meg engem az idegen-fiak kezéből, a kiknek szájok hazugságot beszél, s jobbkezök a hamisság jobbkeze.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 12, 'Hogy fiaink olyanok legyenek, mint a plánták, nagyokká nőve ifjú korukban; leányaink, mint a templom mintájára kifaragott oszlopok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 13, 'Legyenek telve tárházaink, eledelt eledelre szolgáltassanak; juhaink százszorosodjanak, ezerszeresedjenek a mi legelőinken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 14, 'Ökreink megrakodva legyenek; sem betörés, sem kirohanás, sem kiáltozás ne legyen a mi utczáinkon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 15, 'Boldog nép az, a melynek így van dolga; boldog nép az, a melynek az Úr az ő Istene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, 'Dávid dicsérő éneke. Magasztallak téged, Istenem, királyom, és áldom nevedet örökkön örökké!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, 'Minden napon áldalak téged, és dicsérem neved örökkön örökké!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, 'Nagy az Úr és igen dicséretes, és az ő nagysága megfoghatatlan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, 'Nemzedék nemzedéknek dícséri műveidet, s jelentgeti a te hatalmasságodat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, 'A te méltóságod dicső fényéről, és csodálatos dolgaidról elmélkedem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, 'Rettenetes voltod hatalmát beszélik, és én a te nagyságos dolgaidat hirdetem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, 'A te nagy jóságod emlékeiről áradoznak, és a te igazságodnak örvendeznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, 'Irgalmas és könyörületes az Úr, késedelmes a haragra és nagy kegyelmű.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, 'Jó az Úr mindenki iránt, és könyörületes minden teremtményéhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, 'Dicsér téged, Uram minden teremtményed és áldanak téged a te kegyeltjeid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, 'Országodnak dicsőségéről szólnak, és a te hatalmadat beszélik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, 'Hogy tudtul adják az ember fiainak az ő hatalmát, és az ő országának fényes dicsőségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, 'A te országod örökre fennálló ország, és a te uralkodásod nemzedékről nemzedékre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, 'Az Úr megtámogat minden elesendőt, és felegyenesít minden meggörnyedtet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, 'Mindenki szemei te reád vigyáznak, és te idejében megadod eledelöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, 'Megnyitod a te kezedet, és megelégítesz minden élőt ingyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, 'Igaz az Úr minden ő útában, és minden dolgában kegyelmes.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, 'Közel van az Úr minden őt hívóhoz; mindenkihez, a ki hűséggel hívja őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, 'Beteljesíti az őt félőknek kivánságát; kiáltásukat meghallgatja és megsegíti őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, 'Megőrzi az Úr mindazokat, a kik őt szeretik; de a gonoszokat mind megsemmisíti.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, 'Az Úr dicséretét beszélje ajkam, és az ő szent nevét áldja minden test örökkön örökké!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, 'Dicsérjétek az Urat! Dicsérd én lelkem az Urat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, 'Dicsérem az Urat, a míg élek; éneklek az én Istenemnek, a míg vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, 'Ne bízzatok a fejedelmekben, emberek fiában, a ki meg nem menthet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, 'Kimegyen a lelke; visszatér földébe, és aznapon elvesznek az ő tervei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, 'Boldog, a kinek segítsége a Jákób Istene, és reménysége van az Úrban, az ő Istenében;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, 'A ki teremtette az eget és földet, a tengert és mindent, a mi bennök van. A ki megtartja a hűségét örökké;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, 'Igazságot szolgáltat az elnyomottaknak, eledelt ád az éhezőknek. Az Úr megszabadítja az elfogottakat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, 'Az Úr megnyitja a vakok szemeit, az Úr felegyenesíti a meggörnyedteket; szereti az Úr az igazakat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, 'Megoltalmazza az Úr a jövevényeket; árvát és özvegyet megtart, és a gonoszok útját elfordítja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, 'Uralkodni fog az Úr örökké, a te Istened, oh Sion, nemzedékről nemzedékre! Dicsérjétek az Urat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 1, 'Dicsérjétek az Urat! Hiszen Istenünkről énekelni jó; hiszen őt dicsérni gyönyörűséges és illendő dolog!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 2, 'Az Úr építi Jeruzsálemet, összegyűjti Izráelnek elűzötteit;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 3, 'Meggyógyítja a megtört szívűeket, és bekötözi sebeiket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 4, 'Elrendeli a csillagok számát, és mindnyájokat nevéről nevezi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 5, 'Nagy a mi Urunk és igen hatalmas, s bölcseségének nincsen határa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 6, 'Megtartja az Úr a nyomorultakat; a gonoszokat földig megalázza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 7, 'Énekeljetek az Úrnak hálaadással, pengessetek hárfát a mi Istenünknek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 8, 'A ki beborítja az eget felhővel, esőt készít a föld számára, és füvet sarjaszt a hegyeken;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 9, 'A ki megadja táplálékát a baromnak, a holló-fiaknak, a melyek kárognak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 10, 'Nem paripák erejében telik kedve, nem is a férfi lábszáraiban gyönyörködik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 11, 'Az őt félőkben gyönyörködik az Úr, a kik kegyelmében reménykednek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 12, 'Dicsőitsd Jeruzsálem az Urat! Dicsérd, oh Sion, a te Istenedet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 13, 'Mert erősekké teszi kapuid zárait, s megáldja benned a te fiaidat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 14, 'Békességet ád határaidnak, megelégít téged a legjobb búzával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 15, 'Leküldi parancsolatát a földre, nagy hirtelen lefut az ő rendelete!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 16, 'Olyan havat ád, mint a gyapjú, és szórja a deret, mint a port.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 17, 'Darabokban szórja le jegét: ki állhatna meg az ő fagya előtt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 18, 'Kibocsátja szavát s szétolvasztja őket; megindítja szelét s vizek folydogálnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 19, 'Közli igéit Jákóbbal, törvényeit s végzéseit Izráellel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 20, 'Nem tesz így egyetlen néppel sem; végzéseit sem tudatja velök. Dicsérjétek az Urat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, 'Dicsérjétek az Urat! Dicsérjétek az Urat az égből; dicsérjétek őt a magas helyeken!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, 'Dicsérjétek őt angyalai mind; dicsérjétek őt minden ő serege!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, 'Dicsérjétek őt: nap és hold; dicsérjétek őt mind: fényes csillagai!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, 'Dicsérjétek őt egeknek egei, és ti vizek, a melyek az ég felett vagytok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, 'Dicsérjék ők az Úrnak nevét, mert parancsolt és előállottak ők.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, 'Örök időre állította fel őket; törvényt szabott és nem tér el attól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, 'Dicsérjétek az Urat a földről: viziszörnyek és mély vizek ti mind!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, 'Tűz és jégeső, hó és köd, szélvihar, a melyek az ő rendelését cselekszik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, 'Ti hegyek és halmok mindnyájan, minden gyümölcsfa s mind ti czédrusok;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, 'Vadak és minden barmok, férgek és szárnyas állatok;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, 'Földi királyok és minden nemzet, fejedelmek és mind ti földi bírák!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, 'Ifjak és szűzek, vének gyermekekkel:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, 'Dicsérjék az Úrnak nevét, mert az ő neve dicső egyedül; az ő dicsősége égre-földre kihat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, 'És felemelte az ő népének szarvát. Dicsőítse minden ő kegyeltje: Izráel fiai, a hozzá közel való nép. Dicsérjétek az Urat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 1, 'Dicsérjétek az Urat! Énekeljetek az Úrnak új éneket; dicsérje őt a kegyesek gyülekezete!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 2, 'Örvendezzen Izráel az ő teremtőjében: Sionnak fiai örüljenek az ő királyukban!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 3, 'Dicsérjék az ő nevét tánczczal; dobbal és hárfával zengjenek néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 4, 'Mert kedveli az Úr az ő népét, a szenvedőket szabadulással dicsőíti meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 5, 'Vígadozzanak a kegyesek tisztességben; ujjongjanak nyugvó helyökön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 6, 'Isten-dicsőítés legyen torkukban, kétélű fegyver kezeikben;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 7, 'Hogy bosszút álljanak a pogányokon, és megfenyítsék a nemzeteket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 8, 'Hogy lánczra fűzzék királyaikat, főembereiket pedig vas-bilincsekbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 9, 'Hogy végrehajtsák rajtok a megírott ítéletet. Dicsőség ez az ő minden kegyeltjére! Dicsérjétek az Urat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 1, 'Dicsérjétek az Urat! Dicsérjétek Istent az ő szent helyén; dicsérjétek őt az ő hatalmának boltozatán!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 2, 'Dicsérjétek őt hősi tetteiért, dicsérjétek őt nagyságának gazdagsága szerint!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 3, 'Dicsérjétek őt kürt-zengéssel; dicsérjétek őt hárfán és cziterán;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 4, 'Dicsérjétek őt dobbal és tánczczal, dicsérjétek őt hegedűkkel és fuvolával;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 5, 'Dicsérjétek őt hangos czimbalommal, dicsérjétek őt harsogó czimbalommal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 6, 'Minden lélek dicsérje az Urat! Dicsérjétek az Urat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, 'Salamonnak, Dávid fiának, Izráel királyának példabeszédei,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'Bölcseség és erkölcsnek tanulására, értelmes beszédek megértésére;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'Okos fenyítéknek, igazságnak és ítéletnek és becsületességnek megnyerésére;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, 'Együgyűeknek eszesség, gyermeknek tudomány és meggondolás adására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, 'Hallja a bölcs és öregbítse az ő tanulságát, és az értelmes szerezzen érett tanácsokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, 'Példabeszédnek és példázatnak, bölcsek beszédeinek és találós meséinek megértésére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'Az Úrnak félelme feje a bölcseségnek; a bölcseséget és erkölcsi tanítást a bolondok megútálják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, 'Hallgasd, fiam, a te atyádnak erkölcsi tanítását, és a te anyádnak oktatását el ne hagyd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'Mert kedves ékesség lesz a te fejednek, és aranyláncz a te nyakadra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'Fiam, ha a bűnösök el akarnak csábítani téged: ne fogadd beszédöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, 'Ha azt mondják: jere mi velünk, leselkedjünk vér után, rejtezzünk el az ártatlan ellen ok nélkül;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, 'Nyeljük el azokat, mint a sír elevenen, és egészen, mint a kik mélységbe szállottak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'Minden drága marhát nyerünk, megtöltjük a mi házainkat zsákmánnyal;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, 'Sorsodat vesd közénk; egy erszényünk legyen mindnyájunknak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, 'Fiam, ne járj egy úton ezekkel, tartóztasd meg lábaidat ösvényüktől;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'Mert lábaik a gonoszra futnak, és sietnek a vérnek ontására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, 'Mert hiába vetik ki a hálót minden szárnyas állat szemei előtt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, 'Ezek mégis vérök árán is ólálkodnak, lelkök árán is leselkednek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, 'Ilyen az útja minden kapzsi embernek: gazdájának életét veszi el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, 'A bölcseség künn szerül-szerte kiált; az utczákon zengedezteti az ő szavát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, 'Lármás utczafőkön kiált a kapuk bemenetelin, a városban szólja az ő beszédit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, 'Míglen szeretitek, oh ti együgyűek az együgyűséget, és gyönyörködnek a csúfolók csúfolásban, és gyűlölik a balgatagok a tudományt?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 23, 'Térjetek az én dorgálásomhoz; ímé közlöm veletek az én lelkemet, tudtotokra adom az én beszédimet néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 24, 'Mivelhogy hívtalak titeket, és vonakodtatok, kiterjesztém az én kezemet, és senki eszébe nem vette;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 25, 'És elhagytátok minden én tanácsomat, és az én feddésemmel nem gondoltatok:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 26, 'Én is a ti nyomorúságtokon nevetek, megcsúfollak, mikor eljő az, a mitől féltek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 27, 'Mikor eljő, mint a vihar, az, a mitől féltek, és a ti nyomorúságtok, mint a forgószél elközelget: mikor eljő ti reátok a nyomorgatás és a szorongatás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 28, 'Akkor segítségül hívnak engem, de nem hallgatom meg: keresnek engem, de meg nem találnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 29, 'Azért hogy gyűlölték a bölcseséget, és az Úrnak félelmét nem választották.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 30, 'Nem engedtek az én tanácsomnak; megvetették minden én feddésemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 31, 'Esznek azért az ő útjoknak gyümölcséből, és az ő tanácsokból megelégednek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 32, 'Mert az együgyűeknek pártossága megöli őket, és a balgatagoknak szerencséje elveszti őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 33, 'A ki pedig hallgat engem, lakozik bátorságosan, és csendes lesz a gonosznak félelmétől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, 'Fiam! ha beveszed az én beszédimet, és az én parancsolatimat elrejted magadnál,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, 'Ha figyelmeztetvén a bölcsességre a te füleidet, hajtod a te elmédet az értelemre,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'Igen, ha a bölcseségért kiáltasz, és az értelemért a te szódat felemeled,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, 'Ha keresed azt, mint az ezüstöt, és mint a kincseket kutatod azt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, 'Akkor megérted az Úrnak félelmét, és az Istennek ismeretére jutsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, 'Mert az Úr ád bölcseséget, az ő szájából tudomány és értelem származik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, 'Az igazaknak valóságos jót rejteget, paizst a tökéletesen járóknak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'Hogy megőrizze az igazságnak útait, és kegyeseinek útját megtartja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'Akkor megérted az igazságot, és törvényt és becsületességet, és minden jó útat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'Mert bölcseség megy a te elmédbe, és a tudomány a te lelkedben gyönyörűséges lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'Meggondolás őrködik feletted, értelem őriz téged,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, 'Hogy megszabadítson téged a gonosznak útától, és a gonoszságszóló férfiútól;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, 'A kik elhagyják az igazságnak útát, hogy járjanak a setétségnek útain.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, 'A kik örülnek gonoszt cselekedvén, vígadnak a gonosz álnokságokon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 15, 'A kiknek ösvényeik görbék, és a kik az ő útaikban gonoszok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 16, 'Hogy megszabadítson téged a nem hozzád tartozó asszonytól, az idegentől, a ki az ő beszédével hizelkedik,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 17, 'A ki elhagyja az ő ifjúságának férjét, és az ő Istenének szövetségéről elfelejtkezik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 18, 'Mert a halálra hanyatlik az ő háza, és az ő ösvényei az élet nélkül valókhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 19, 'Valakik mennek ahhoz, nem térnek meg, sem meg nem nyerhetik az életnek útait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 20, 'Hogy járj a jóknak útjokon, és az igazaknak ösvényeit kövessed.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 21, 'Mert az igazak lakják a földet, és a tökéletesek maradnak meg rajta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 22, 'A gonoszok pedig a földről kivágattatnak, és a hitetlenül cselekedők kiszaggattatnak abból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, 'Fiam! az én tanításomról el ne felejtkezzél, és az én parancsolatimat megőrizze a te elméd;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'Mert napoknak hosszú voltát, és sok esztendős életet, és békességet hoznak néked bőven.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, 'Az irgalmasság és igazság ne hagyjanak el téged: kösd azokat a te nyakadra, írd be azokat a te szívednek táblájára;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'Így nyersz kedvességet és jó értelmet Istennek és embernek szemei előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, 'Bizodalmad legyen az Úrban teljes elmédből; a magad értelmére pedig ne támaszkodjál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, 'Minden te útaidban megismered őt; akkor ő igazgatja a te útaidat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, 'Ne légy bölcs a te magad ítélete szerint; féld az Urat, és távozzál el a gonosztól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'Egészség lesz ez a te testednek, és megújulás a te csontaidnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, 'Tiszteld az Urat a te marhádból, a te egész jövedelmed zsengéjéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'Eképen megtelnek a te csűreid elégséggel, és musttal áradnak el sajtód válúi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, 'Az Úrnak fenyítését fiam, ne útáld meg, se meg ne únd az ő dorgálását.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'Mert a kit szeret az Úr, megdorgálja, és pedig mint az atya az ő fiát, a kit kedvel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, 'Boldog ember, a ki megnyerte a bölcseséget, és az ember, a ki értelmet szerez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'Mert jobb ennek megszerzése az ezüstnek megszerzésénél, és a kiásott aranynál ennek jövedelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, 'Drágább a fényes kárbunkulusoknál, és minden te gyönyörűségeid nem hasonlíthatók hozzá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, 'Napoknak hosszúsága van jobbjában, baljában gazdagság és tisztesség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, 'Az ő útai gyönyörűséges útak, és minden ösvényei: békesség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 18, 'Életnek fája ez azoknak, a kik megragadják, és a kik megtartják boldogok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 19, 'Az Úr bölcseséggel fundálta a földet, erősítette az eget értelemmel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 20, 'Az ő tudománya által fakadtak ki a mélységből a vizek, és a felhők csepegnek harmatot,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 21, 'Fiam, ne távozzanak el a te szemeidtől, őrizd meg az igaz bölcseséget, és a meggondolást!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 22, 'És lesznek ezek élet a te lelkednek, és kedvesség a te nyakadnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 23, 'Akkor bátorsággal járod a te útadat, és a te lábadat meg nem ütöd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 24, 'Mikor lefekszel, nem rettegsz; hanem lefekszel és gyönyörűséges lesz a te álmod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 25, 'Ne félj a hirtelen való félelemtől, és a gonoszok pusztításától, ha eljő;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 26, 'Mert az Úr lesz a te bizodalmad és megőrzi a te lábadat a fogságtól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 27, 'Ne fogd meg a jótéteményt azoktól, a kiket illet, ha hatalmadban van annak megcselekedése.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 28, 'Ne mondd a te felebarátodnak: menj el, azután térj meg, és holnap adok; holott nálad van, a mit kér.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 29, 'Ne forralj a te felebarátod ellen gonoszt, holott ő együtt ül bátorságosan te veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 30, 'Ne háborogj egy emberrel is ok nélkül, ha nem illetett gonoszszal téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 31, 'Ne irígykedjél az erőszakos emberre, és néki semmi útát ne válaszd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 32, 'Mert útálja az Úr az engedetlent; és az igazakkal van az ő titka.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 33, 'Az Úrnak átka van a gonosznak házán; de az igazaknak lakhelyét megáldja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 34, 'Ha kik csúfolók, ő megcsúfolja azokat; a szelídeknek pedig ád kedvességet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 35, 'A bölcsek tisztességet örökölnek; a bolondok pedig gyalázatot aratnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, 'Halljátok meg, fiaim, atyátok erkölcsi tanítását, és figyelmezzetek az értelemnek megtudására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'Mert jó tanulságot adok néktek; az én tudományomat el ne hagyjátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'Mert én atyámnak fia voltam, gyenge és egyetlenegy az én anyám előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, 'Tehát tanított engem, és mondá nékem: tartsa meg az én beszédemet a te elméd, hogy megtartván az én parancsolatimat, élj;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, 'Szerezz bölcseséget, szerezz eszességet; ne felejtkezzél el, se el ne hajolj az én számnak beszéditől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, 'Ne hagyd el azt, és megtart téged; szeresd azt, és megőriz téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, 'A bölcseség kezdete ez: szerezz bölcseséget, és minden keresményedből szerezz értelmet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, 'Magasztald fel azt, és felmagasztal téged; tiszteltté tesz téged, ha hozzád öleled azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'Ád a te fejednek kedvességnek koszorúját; igen szép ékes koronát ád néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, 'Hallgasd, fiam, és vedd be az én beszédimet; így sokasulnak meg néked a te életednek esztendei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, 'Bölcseségnek útára tanítottalak téged, vezettelek téged az igazságnak ösvényin.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, 'Mikor jársz, semmi nem szorítja meg a te járásodat; és ha futsz, nem ütközöl meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, 'Ragaszkodjál az erkölcsi tanításhoz, ne hagyd el; őrizd meg azt, mert az a te életed.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, 'A hitetleneknek útjára ne menj, se ne járj a gonoszok ösvényén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'Hagyd el, át ne menj rajta; térj el tőle, és menj tovább.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, 'Mert nem alhatnak azok, ha gonoszt nem cselekesznek: és kimegy szemükből az álom, ha mást romlásra nem juttatnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, 'Mert az istentelenségnek étkét eszik, és az erőszaktételnek borát iszszák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, 'Az igazak ösvénye pedig olyan, mint a hajnal világossága, mely minél tovább halad, annál világosabb lesz, a teljes délig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, 'Az istentelenek útja pedig olyan, mint a homály, nem tudják miben ütköznek meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, 'Fiam, az én szavaimra figyelmezz, az én beszédimre hajtsad füledet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, 'Ne távozzanak el a te szemeidtől, tartsd meg ezeket a te elmédben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 22, 'Mert életök ezek azoknak, a kik megnyerik, és egész testöknek egészség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 23, 'Minden féltett dolognál jobban őrizd meg szívedet, mert abból indul ki minden élet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 24, 'Vesd el tőled a száj hamisságát, és az ajkak álnokságát távoztasd el magadtól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 25, 'A te szemeid előre nézzenek, és szemöldökid egyenest magad elé irányuljanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 26, 'Egyengesd el lábaid ösvényit, s minden te útaid állhatatosak legyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 27, 'Ne térj jobbra, se balra, fordítsd el a te lábadat a gonosztól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, 'Fiam! az én bölcseségemre figyelmezz, az én értelmemre hajtsd a te füledet,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'Hogy megtartsd a meggondolást, és a tudományt a te ajakid megőrizzék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, 'Mert színmézet csepeg az idegen asszony ajka, és símább az olajnál az ő ínye.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'De annak vége keserű, mint az üröm, éles, mint a kétélű tőr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'Az ő lábai a halálra mennek, az ő léptei a sírba törekszenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, 'Az életnek útát hogy ne követhesse, ösvényei változókká lettek, a nélkül, hogy ő eszébe venné.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, 'Most azért, fiaim, hallgassatok engem, és ne távozzatok el számnak beszéditől!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, 'Távoztasd el attól útadat, és ne közelgess házának ajtajához,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, 'Hogy másoknak ne add a te ékességedet, és esztendeidet a kegyetlennek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, 'Hogy ne az idegenek teljenek be a te marháiddal, és a te keresményed más házába ne jusson.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, 'Hogy nyögnöd kelljen életed végén, a mikor megemésztetik a te húsod és a te tested,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'És azt kelljen mondanod: miképen gyűlöltem az erkölcsi tanítást, és a fenyítéket útálta az én elmém,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, 'És nem hallgattam az én vezetőim szavát, és az én tanítóimhoz nem hajtottam fülemet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, 'Kevés híja volt, hogy minden gonoszságba nem merültem a gyülekezetnek és községnek közepette!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, 'Igyál vizet a te kútadból, és a te forrásod közepiből folyóvizet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, 'Kifolyjanak-é a te forrásid, az utczákra a te vized folyásai?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, 'Egyedül tied legyenek, és nem az idegenekéi veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, 'Legyen a te forrásod áldott, és örvendezz a te ifjúságod feleségének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, 'A szerelmes szarvas, és kedves zerge; az ő emlői elégítsenek meg téged minden időben, az ő szerelmében gyönyörködjél szüntelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, 'És miért bujdosnál, fiam, az idegen után, és ölelnéd keblét az idegennek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, 'Mert az Úrnak szemei előtt vannak mindenkinek útai, és minden ösvényeit ő rendeli.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, 'A maga álnokságai fogják meg az istentelent, és a saját bűnének köteleivel kötöztetik meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, 'Ő meghal fenyíték híján, és bolondságának sokasága miatt támolyog.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, 'Fiam! ha kezes lettél a te barátodért, és kezedet adván, kötelezted magadat másért:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, 'Szádnak beszédei által estél tőrbe, megfogattattál a te szádnak beszédivel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, 'Ezt míveld azért fiam, és mentsd ki magadat, mert a te felebarátodnak kezébe jutottál; eredj, alázd meg magadat, és kényszerítsd felebarátodat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, 'Még álmot se engedj szemeidnek, se szunnyadást szemöldökidnek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'Szabadítsd ki magadat, mint a zerge a vadász kezéből, és mint a madár a madarásznak kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, 'Eredj a hangyához, te rest, nézd meg az ő útait, és légy bölcs!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, 'A kinek nincs vezére, igazgatója, vagy ura,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, 'Nyárban szerzi meg az ő kenyerét, aratáskor gyűjti eledelét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, 'Oh te rest, meddig fekszel? mikor kelsz fel a te álmodból?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, 'Még egy kis álom, még egy kis szunnyadás, még egy kis kéz-összefonás, hogy pihenjek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'Így jő el, mint az útonjáró, a te szegénységed, és a te szűkölködésed, mint a paizsos férfiú!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, 'Haszontalan ember, hamis férfiú, a ki álnok szájjal jár,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, 'A ki hunyorgat szemeivel; lábaival is szól, és ujjaival jelt ád.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, 'Álnokság van az ő szívében, gonoszt forral minden időben, háborúságot indít.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, 'Annakokáért hirtelen eljő az ő nyomorúsága, gyorsan megrontatik, s nem lesz gyógyulása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, 'E hat dolgot gyűlöli az Úr, és hét dolog útálat az ő lelkének:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, 'A kevély szemek, a hazug nyelv, és az ártatlan vért ontó kezek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, 'Az álnok gondolatokat forraló elme, a gonoszra sietséggel futó lábak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, 'A hazugságlehelő hamis tanú, és a ki szerez háborúságokat az atyafiak között!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 20, 'Őrizd meg, fiam, atyád parancsolatját, és anyád tanítását el ne hagyd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 21, 'Kösd azokat szívedre mindenkor, fűzd a nyakadba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 22, 'Valahová mégysz, vezérel téged, mikor aluszol, őriz téged, mikor felserkensz, beszélget te veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 23, 'Mert szövétnek a parancsolat, és a tudomány világosság, és életnek úta a tanító-feddések.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 24, 'Hogy a gonosz asszonytól téged megőrizzenek, az idegen asszony nyelvének hizelkedésétől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 25, 'Ne kivánd az ő szépségét szivedben, és meg ne fogjon téged szemöldökeivel;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 26, 'Mert a parázna asszony miatt jut az ember egy darab kenyérre, és más férfi felesége drága életet vadász!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 27, 'Vehet-é valaki tüzet az ő kebelébe, hogy ruhái meg ne égnének?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 28, 'Vagy járhat-é valaki elevenszénen, hogy lábai meg ne égnének?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 29, 'Így van, valaki bemegy felebarátjának feleségéhez, nem marad büntetlen, valaki illeti azt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 30, 'Nem útálják meg a lopót, ha lop az ő kivánságának betöltésére, mikor éhezik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 31, 'És ha rajta kapatik, hétannyit kell adnia, az ő házának minden marháját érette adhatja;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 32, 'A ki pedig asszonynyal paráználkodik, bolond; a ki magát el akarja veszteni, az cselekszi ezt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 33, 'Vereséget és gyalázatot nyer, és az ő gyalázatja el nem töröltetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 34, 'Mert a féltékenység a férfiú haragja, és nem cselekszik kegyelmességgel a bosszúállásnak napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 35, 'Nem gondol semmi váltsággal, nem nyugszik meg rajta, még ha nagy sok ajándékot adsz is néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, 'Fiam, tartsd meg az én beszédeimet, és az én parancsolataimat rejtsd el magadnál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, 'Az én parancsolatimat tartsd meg, és élsz; és az én tanításomat mint a szemed fényét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'Kösd azokat ujjaidra, írd fel azokat szíved táblájára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'Mondd ezt a bölcseségnek: Én néném vagy te; és az eszességet ismerősödnek nevezd,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'Hogy megőrizzen téged a nem hozzád tartozó asszonytól, és az ő beszédivel hizelkedő idegentől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'Mert házam ablakán, a rács mögül néztem,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, 'És láték a bolondok között, eszembe vevék a fiak között egy bolond ifjat,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, 'A ki az utczán jár, annak szeglete mellett, a házához menő úton lépeget,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, 'Alkonyatkor, nap estjén, és setét éjfélben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, 'És ímé, egy asszony eleibe jő, paráznának öltözetében, álnok az ő elméjében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, 'Mely csélcsap és vakmerő, a kinek házában nem maradhatnak meg az ő lábai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, 'Néha az utczán, néha a tereken van, és minden szegletnél leselkedik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, 'És megragadá őt és megcsókolá őt, és szemtelenségre vetemedvén, monda néki:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, 'Hálaáldozattal tartoztam, ma adtam meg fogadásimat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, 'Azért jövék ki elődbe, szorgalmatosan keresni a te orczádat, és reád találtam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, 'Paplanokkal megvetettem nyoszolyámat, égyiptomi szövésű szőnyegekkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, 'Beillatoztam ágyamat mirhával, áloessel és fahéjjal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, 'No foglaljuk magunkat bőségesen mind virradtig a szeretetben; vígadjunk szerelmeskedésekkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 19, 'Mert nincs otthon a férjem, elment messze útra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 20, 'Egy erszény pénzt vőn kezéhez; holdtöltére jő haza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 21, 'És elhiteté őt az ő mesterkedéseinek sokaságával, ajkainak hizelkedésével elragadá őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 22, 'Utána megy; mint az ökör a vágóhídra, és mint a bolond, egyszer csak fenyítő békóba;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 23, 'Mígnem átjárja a nyíl az ő máját. Miképen siet a madár a tőrre, és nem tudja, hogy az az ő élete ellen van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 24, 'Annakokáért most, fiaim, hallgassatok engem, és figyelmezzetek az én számnak beszédeire.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 25, 'Ne hajoljon annak útaira a te elméd, és ne tévelyegj annak ösvényin.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 26, 'Mert sok sebesültet elejtett, és sokan vannak, a kik attól megölettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 27, 'Sírba vívő út az ő háza, a mely levisz a halálnak hajlékába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, 'Avagy a bölcsesség nem kiált-é, és az értelem nem bocsátja-é ki az ő szavát?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, 'A magas helyeknek tetein az úton, sok ösvény összetalálkozásánál áll meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, 'A kapuk mellett a városnak bemenetelin, az ajtók bemenetelinél zeng.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, 'Tinéktek kiáltok, férfiak; és az én szóm az emberek fiaihoz van!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, 'Értsétek meg ti együgyűek az eszességet, és ti balgatagok vegyétek eszetekbe az értelmet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, 'Halljátok meg; mert jeles dolgokat szólok és az én számnak felnyitása igazság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, 'Mert igazságot mond ki az én ínyem, és útálat az én ajkaimnak a gonoszság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'Igaz én számnak minden beszéde, semmi sincs ezekben hamis, vagy elfordult dolog.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, 'Mind egyenesek az értelmesnek, és igazak azoknak, kik megnyerték a tudományt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'Vegyétek az én tanításomat, és nem a pénzt; és a tudományt inkább, mint a választott aranyat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, 'Mert jobb a bölcseség a drágagyöngyöknél; és semmi gyönyörűségek ehhez egyenlők nem lehetnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, 'Én bölcsesség lakozom az eszességben, és a megfontolás tudományát megnyerem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, 'Az Úrnak félelme a gonosznak gyűlölése; a kevélységet és felfuvalkodást és a gonosz útat, és az álnok szájat gyűlölöm.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, 'Enyém a tanács és a valóság, én vagyok az eszesség, enyém az erő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, 'Én általam uralkodnak a királyok, és az uralkodók végeznek igazságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, 'Én általam viselnek a fejedelmek fejedelemséget, és a nemesek, a földnek minden birái.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'Én az engem szeretőket szeretem, és a kik engem szorgalmasan keresnek, megtalálnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, 'Gazdagság és tisztesség van nálam, megmaradandó jó és igazság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, 'Jobb az én gyümölcsöm a tiszta aranynál és színaranynál, és az én hasznom a válogatott ezüstnél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, 'Az igazságnak útán járok, és az igazság ösvényének közepén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, 'Hogy az engem szeretőknek valami valóságost adjak örökségül, és erszényeiket megtöltsem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 22, 'Az Úr az ő útának kezdetéül szerzett engem; az ő munkái előtt régen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 23, 'Örök időktől fogva felkenettem, kezdettől, a föld kezdetétől fogva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 24, 'Még mikor semmi mélységek nem voltak, születtem vala; még mikor semmi források, vízzel teljesek nem voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 25, 'Minekelőtte a hegyek leülepedtek volna, a halmoknak előtte születtem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 26, 'Mikor még nem csinálta vala a földet és a mezőket, és a világ porának kezdetét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 27, 'Mikor készíté az eget, ott valék; mikor felveté a mélységek színén a kerekséget;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 28, 'Mikor megerősíté a felhőket ott fenn, mikor erősekké lőnek a mélységeknek forrásai;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 29, 'Mikor felveté a tengernek határit, hogy a vizek át ne hágják az ő parancsolatját, mikor megállapítá e földnek fundamentomait:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 30, 'Mellette valék mint kézmíves, és gyönyörűsége valék mindennap, játszva ő előtte minden időben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 31, 'Játszva az ő földének kerekségén, és gyönyörűségemet lelve az emberek fiaiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 32, 'És most fiaim, hallgassatok engemet, és boldogok, a kik az én útaimat megtartják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 33, 'Hallgassátok a tudományt és legyetek bölcsek, és magatokat el ne vonjátok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 34, 'Boldog ember, a ki hallgat engem, az én ajtóm előtt virrasztván minden nap, az én ajtóim félfáit őrizvén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 35, 'Mert a ki megnyer engem, nyert életet, és szerzett az Úrtól jóakaratot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 36, 'De a ki vétkezik ellenem, erőszakot cselekszik az ő lelkén; minden, valaki engem gyűlöl, szereti a halált!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, 'Bölcseség megépítette az ő házát, annak hét oszlopát kivágván.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'Megölte vágnivalóit, kitöltötte borát, asztalát is elkészítette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'Elbocsátá az ő leányit, hivogat a város magas helyeinek tetein.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, 'Ki tudatlan? térjen ide; az értelem nélkül valónak ezt mondja:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, 'Jőjjetek, éljetek az én étkemmel, és igyatok a borból, melyet töltöttem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, 'Hagyjátok el a bolondokat, hogy éljetek, járjatok az eszességnek útán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, 'A ki tanítja a csúfolót, nyer magának szidalmat: és a ki feddi a latrot, szégyenére lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, 'Ne fedd meg a csúfolót, hogy ne gyűlöljön téged; fedd meg a bölcset, és szeret téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, 'Adj a bölcsnek, és még bölcsebb lesz; tanítsd az igazat, és öregbíti a tanulságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, 'A bölcseségnek kezdete az Úrnak félelme; és a Szentnek ismerete az eszesség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, 'Mert én általam sokasulnak meg a te napjaid, és meghosszabbítják néked életednek esztendeit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, 'Ha bölcs vagy, bölcs vagy te magadnak; ha pedig csúfoló vagy, magad vallod kárát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, 'Balgaság asszony fecsegő, bolond és semmit nem tud.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, 'És leült az ő házának ajtajába, székre a városnak magas helyein,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, 'Hogy hívja az útonjárókat, a kik egyenesen mennek útjokon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, 'Ki együgyű? térjen ide, és valaki esztelen, annak ezt mondja:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, 'A lopott víz édes, és a titkon való étel gyönyörűséges!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, 'És az nem tudja, hogy ott élet nélkül valók vannak; és a pokol mélyébe esnek az ő hivatalosai!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, 'Salamon bölcs mondásai. A bölcs fiú örvendezteti az ő atyját; a bolond fiú pedig szomorúsága az ő anyjának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, 'Nem használnak a gonoszság kincsei; az igazság pedig megszabadít a halálból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, 'Az Úr nem hagyja éhezni az igaznak lelkét; az istenteleneknek kivánságát pedig elveti.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, 'Szegénynyé lesz, a ki cselekszik rest kézzel; a gyors munkások keze pedig meggazdagít.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, 'Gyűjt nyárban az eszes fiú; álomba merül az aratás idején a megszégyenítő fiú.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, 'Áldások vannak az igaznak fején; az istentelenek szája pedig erőszaktételt fed be.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, 'Az igaznak emlékezete áldott; a hamisaknak neve pedig megrothad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, 'A bölcs elméjű beveszi a parancsolatokat; a bolond ajkú pedig elveszti magát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, 'A ki tökéletességben jár, bátorsággal jár; a ki pedig elferdíti az ő útát, kiismertetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, 'A ki szemmel hunyorgat, bántást szerez; és a bolond ajkú elesik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, 'Életnek kútfeje az igaznak szája; az istenteleneknek szája pedig erőszaktételt fedez el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, 'A gyűlölség szerez versengést; minden vétket pedig elfedez a szeretet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, 'Az eszesek ajkain bölcseség találtatik; a vessző pedig a bolond hátának való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, 'A bölcsek tudományt rejtegetnek; a bolondnak szája pedig közeli romlás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 15, 'A gazdagnak marhája az ő megerősített városa; szűkölködőknek romlása az ő szegénységök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 16, 'Az igaznak keresménye életre, az istentelennek jövedelme bűnre van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 17, 'A bölcseség megőrizőnek útja életre van; a fenyítéket elhagyó pedig tévelyeg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 18, 'A ki elfedezi a gyűlölséget, hazug ajkú az; és a ki szól gyalázatot, bolond az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 19, 'A sok beszédben elmaradhatatlan a vétek; a ki pedig megtartóztatja ajkait, az értelmes.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 20, 'Választott ezüst az igaznak nyelve; a gonoszok elméje kevés érő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 21, 'Az igaznak ajkai sokakat legeltetnek; a bolondok pedig esztelenségökben halnak meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 22, 'Az Úrnak áldása, az gazdagít meg, és azzal semmi nem szerez bántást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 23, 'Miképen játék a bolondnak bűnt cselekedni, azonképen az eszes férfiúnak bölcsen cselekedni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 24, 'A mitől retteg az istentelen, az esik ő rajta; a mit pedig kivánnak az igazak, meg lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 25, 'A mint a forgószél ráfuvall, már oda van az istentelen; az igaznak pedig örökké való fundamentoma van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 26, 'Minémű az eczet a fogaknak és a füst a szemeknek, olyan a rest azoknak, a kik azt elküldötték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 27, 'Az Úrnak félelme hosszabbítja meg a napokat; az istenteleneknek pedig esztendeik megrövidülnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 28, 'Az igazaknak reménysége öröm; az istenteleneknek várakozása pedig elvész.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 29, 'Erősség a tökéletesnek az Úrnak úta: de romlás a hamisság cselekedőinek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 30, 'Az igaz soha meg nem mozdul; de az istentelenek nem lakják a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 31, 'Az igaznak szája bőségesen szól bölcsességet; a gonoszság nyelve pedig kivágatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 32, 'Az igaznak ajkai azt tudják, a mi kedves; az istenteleneknek szája pedig a gonoszságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, 'Az álnok font útálatos az Úrnál; az igaz mérték pedig kedves néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, 'Kevélység jő: gyalázat jő; az alázatosoknál pedig bölcseség van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, 'Az igazakat tökéletességök vezeti; de a hitetleneket gonoszságuk elpusztítja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, 'Nem használ a vagyon a haragnak idején; az igazság pedig kiragad a halálból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, 'A tökéletesnek igazsága igazgatja az ő útát; de önnön istentelenségében esik el az istentelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, 'Az igazaknak igazságok megszabadítja őket; de az ő kivánságokban fogatnak meg a hitetlenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, 'Mikor meghal az istentelen ember, elvész az ő reménysége; a bűnösök várakozása is elvész.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, 'Az igaz a nyomorúságból megszabadul; az istentelen ő helyette beesik abba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, 'Szájával rontja meg a képmutató felebarátját; de az igazak a tudomány által megszabadulnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, 'Az igazak javán örül a város; és mikor elvesznek az istentelenek, örvendezés van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, 'Az igazaknak áldása által emelkedik a város; az istentelenek szája által pedig megromol.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, 'Megútálja felebarátját a bolond; az eszes férfiú pedig hallgat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, 'A rágalmazó megjelenti a titkot; de a hűséges lelkű elfedezi a dolgot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, 'A hol nincs vezetés, elvész a nép; a megmaradás pedig a sok tanácsos által van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, 'Teljességgel megrontatik, a ki kezes lesz idegenért; a ki pedig gyűlöli a kezességet, bátorságos lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, 'A kedves asszony megtartja a tiszteletet, a hatalmaskodók pedig megtartják a gazdagságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, 'Ő magával tesz jól a kegyes férfiú; a kegyetlen pedig öntestének okoz fájdalmat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, 'Az istentelen munkál álnok keresményt; az igazságszerzőnek pedig jutalma valóságos.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, 'A ki őszinte az igazságban, az életére -, a ki pedig a gonoszt követi, az vesztére míveli azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 20, 'Útálatosok az Úrnál az álnok szívűek; kedvesek pedig ő nála, a kik az ő útjokban tökéletesek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 21, 'Kézadással erősítem, hogy nem marad büntetlen a gonosz; az igazaknak pedig magva megszabadul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 22, 'Mint a disznó orrában az aranyperecz, olyan a szép asszony, a kinek nincs okossága.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 23, 'Az igazaknak kivánsága csak jó, az istentelenek várakozása pedig harag.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 24, 'Van olyan, a ki bőven adakozik, és annál inkább gazdagodik; és a ki megtartóztatja a járandóságot, de ugyan szűkölködik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 25, 'A mással jóltevő ember megkövéredik; és a ki mást felüdít, maga is üdül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 26, 'A ki búzáját visszatartja, átkozza azt a nép; annak fején pedig, a ki eladja, áldás van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 27, 'A ki jóra igyekezik, jóakaratot szerez: a ki pedig gonoszt keres, ő magára jő az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 28, 'A ki bízik az ő gazdagságában, elesik; de mint a fa ága, az igazak kivirágoznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 29, 'A ki megháborítja az ő házát, annak öröksége szél lesz; és a bolond szolgája a bölcs elméjűnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 30, 'Az igaznak gyümölcse életnek fája; és lelkeket nyer meg a bölcs.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 31, 'Ímé, az igaz e földön megnyeri jutalmát; mennyivel inkább az istentelen és a bűnös! A ki szereti a dorgálást, szereti a tudományt; a ki pedig gyűlöli a fenyítéket, oktalan az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, 'A jó ember jóakaratot nyer az Úrtól; de a gonosz embert kárhoztatja ő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, 'Nem erősül meg ember az istentelenséggel; az igazaknak pedig gyökerök ki nem mozdul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, 'A derék asszony koronája az ő férjének; de mint az ő csontjaiban való rothadás, olyan a megszégyenítő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, 'Az igazaknak gondolatjaik igazak; az istentelenek tanácsa csalás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, 'Az istenteleneknek beszédei leselkednek a vér után; az igazaknak pedig szája megszabadítja azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, 'Leomlanak az istentelenek, és oda lesznek; az igazak háza pedig megáll.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, 'Az ő értelme szerint dicsértetik a férfiú; de az elfordult elméjű útálatos lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, 'Jobb, a kit kevésre tartanak, és szolgája van, mint a ki magát felmagasztalja, és szűk kenyerű.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, 'Az igaz az ő barmának érzését is ismeri, az istentelenek szíve pedig kegyetlen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, 'A ki míveli az ő földét, megelégedik eledellel; a ki pedig követ hiábavalókat, bolond az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, 'Kivánja az istentelen a gonoszok prédáját; de az igaznak gyökere ád gyümölcsöt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, 'Az ajkaknak vétkében gonosz tőr van, de kimenekedik a nyomorúságból az igaz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, 'Az ő szájának gyümölcséből elégedik meg a férfi jóval; és az ő cselekedetének fizetését veszi az ember önmagának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, 'A bolondnak úta helyes az ő szeme előtt, de a ki tanácscsal él, bölcs az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, 'A bolondnak haragja azon napon megismertetik; elfedezi pedig a szidalmat az eszes ember.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, 'A ki igazán szól, megjelenti az igazságot, a hamis bizonyság pedig az álnokságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, 'Van olyan, a ki beszél hasonlókat a tőrszúrásokhoz; de a bölcseknek nyelve orvosság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, 'Az igazmondó ajak megáll mind örökké; a hazugságnak pedig nyelve egy szempillantásig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, 'Álnokság van a gonosz gondolóknak szívében; a békességnek tanácsosiban pedig vígasság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, 'Nem vettetik az igaz semmi bántásba; az istentelenek pedig teljesek nyavalyával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, 'Útálatosok az Úrnál a csalárd beszédek; a kik pedig cselekesznek hűségesen, kedvesek ő nála.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'Az eszes ember elfedezi a tudományt; a bolondok elméje pedig kikiáltja a bolondságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 23, 'A gyorsaknak keze uralkodik; a rest pedig adófizető lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 24, 'A férfiúnak elméjében való gyötrelem megalázza azt; a jó szó pedig megvidámítja azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, 'Útba igazítja az ő felebarátját az igaz; de az istentelenek útja eltévelyíti őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 26, 'Nem süti meg a rest, a mit vadászásával fogott; de drága marhája az embernek serénysége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 27, 'Az igazságnak útjában van élet; és az ő ösvényének úta halhatatlanság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 28, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, 'A bölcs fiú enged atyja intésének; de a csúfoló semmi dorgálásnak helyt nem ád.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, 'A férfi az ő szájának gyümölcséből él jóval; a hitetlenek lelke pedig bosszúságtétellel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, 'A ki megőrzi az ő száját, megtartja önmagát; a ki felnyitja száját, romlása az annak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, 'Kivánsággal felindul, de hiába, a restnek lelke; a gyorsak lelke pedig megkövéredik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, 'A hamis dolgot gyűlöli az igaz; az istentelen pedig gyűlölségessé tesz és megszégyenít.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, 'Az igazság megőrzi azt, a ki útjában tökéletes; az istentelenség pedig elveszíti a bűnöst.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, 'Van, a ki hányja gazdagságát, holott semmije sincsen; viszont tetteti magát szegénynek, holott sok marhája van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, 'Az ember életének váltsága lehet az ő gazdagsága; a szegény pedig nem hallja a fenyegetést.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, 'Az igazak világossága vígassággal ég; de az istenteleneknek szövétneke kialszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, 'Csak háborúság lesz a kevélységből: azoknál pedig, a kik a tanácsot beveszik, bölcseség van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, 'A hiábavalóságból keresett marha megkisebbül; a ki pedig kezével gyűjt, megőregbíti azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, 'A halogatott reménység beteggé teszi a szívet; de a megadatott kivánság életnek fája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, 'Az igének megútálója megrontatik; a ki pedig féli a parancsolatot, jutalmát veszi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, 'A bölcsnek tanítása életnek kútfeje, a halál tőrének eltávoztatására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, 'Jó értelem ád kedvességet; a hitetleneknek pedig útja kemény.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, 'Minden eszes cselekszik bölcseséggel; a bolond pedig kijelenti az ő bolondságát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, 'Az istentelen követ bajba esik; a hívséges követ pedig gyógyulás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, 'Szegénység és gyalázat lesz azon, a ki a fenyítéktől magát elvonja; a ki pedig megfogadja a dorgálást, tiszteltetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, 'A megnyert kivánság gyönyörűséges a léleknek, és útálatosság a bolondoknak eltávozniok a gonosztól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 20, 'A ki jár a bölcsekkel, bölcs lesz; a ki pedig magát társul adja a bolondokhoz, megromol.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 21, 'A bűnösöket követi a gonosz; az igazaknak pedig jóval fizet Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 22, 'A jó örökséget hágy unokáinak; a bűnösnek marhái pedig eltétetnek az igaz számára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 23, 'Bő étele lesz a szegényeknek az új törésen; de van olyan, a ki igazságtalansága által vész el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 24, 'A ki megtartóztatja az ő vesszejét, gyűlöli az ő fiát; a ki pedig szereti azt, megkeresi őt fenyítékkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 25, 'Az igaz eszik az ő kivánságának megelégedéséig; az istentelenek hasa pedig szűkölködik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, 'A bölcs asszony építi a maga házát; a bolond pedig önkezével rontja el azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, 'A ki igazán jár, féli az Urat; a ki pedig elfordult az ő útaiban, megútálja őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, 'A bolondnak szájában van kevélységnek pálczája; a bölcseknek pedig beszéde megtartja őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, 'Mikor nincsenek ökrök: tiszta a jászol; a gabonának bősége pedig az ökörnek erejétől van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, 'A hűséges tanú nem hazud; a hamis tanú pedig hazugságot bocsát szájából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, 'A csúfoló keresi a bölcseséget, és nincs; a tudomány pedig az eszesnek könnyű.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, 'Menj el a bolond férfiú elől; és nem ismerted meg a tudománynak beszédét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, 'Az eszesnek bölcsesége az ő útának megértése; a bolondoknak pedig bolondsága csalás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, 'A bolondokat megcsúfolja a bűnért való áldozat; az igazak között pedig jóakarat van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, 'A szív tudja az ő lelke keserűségét; és az ő örömében az idegen nem részes.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, 'Az istenteleneknek háza elvész; de az igazaknak sátora megvirágzik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, 'Van olyan út, mely helyesnek látszik az ember előtt, és vége a halálra menő út.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, 'Nevetés közben is fáj a szív; és végre az öröm fordul szomorúságra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, 'Az ő útaiból elégszik meg az elfordult elméjű; önmagából pedig a jó férfiú.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, 'Az együgyű hisz minden dolognak; az eszes pedig a maga járására vigyáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 16, 'A bölcs félvén, eltávozik a gonosztól; a bolond pedig dühöngő és elbizakodott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 17, 'A hirtelen haragú bolondságot cselekszik, és a cselszövő férfi gyűlölséges lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 18, 'Bírják az esztelenek a bolondságot örökség szerint; az eszesek pedig fonják a tudománynak koszorúját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 19, 'Meghajtják magokat a gonoszok a jók előtt, és a hamisak az igaznak kapujánál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 20, 'Még az ő felebarátjánál is útálatos a szegény; a gazdagnak pedig sok a barátja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 21, 'A ki megútálja az ő felebarátját, vétkezik; a ki pedig a szegényekkel kegyelmességet cselekszik, boldog az!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 22, 'Nemde tévelyegnek, a kik gonoszt szereznek? kegyelmesség pedig és igazság a jó szerzőknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 23, 'Minden munkából nyereség lesz; de az ajkaknak beszédéből csak szűkölködés.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 24, 'A bölcseknek ékességök az ő gazdagságuk; a tudatlanok bolondsága pedig csak bolondság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 25, 'Lelkeket szabadít meg az igaz bizonyság; hazugságokat szól pedig az álnok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 26, 'Az Úrnak félelmében erős a bizodalom, és az ő fiainak lesz menedéke.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 27, 'Az Úrnak félelme az életnek kútfeje, a halál tőrének eltávoztatására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 28, 'A nép sokasága a király dicsősége; a nép elfogyása pedig az uralkodó romlása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 29, 'A haragra késedelmes bővelkedik értelemmel; a ki pedig elméjében hirtelenkedő, bolondságot szerez az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 30, 'A szelíd szív a testnek élete; az irígység pedig a csontoknak rothadása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 31, 'A ki elnyomja a szegényt, gyalázattal illeti annak teremtőjét; az pedig tiszteli, a ki könyörül a szűkölködőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 32, 'Az ő nyavalyájába ejti magát az istentelen; az igaznak pedig halála idején is reménysége van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 33, 'Az eszesnek elméjében nyugszik a bölcseség; a mi pedig a tudatlanokban van, magát hamar megismerheti.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 34, 'Az igazság felmagasztalja a nemzetet; a bűn pedig gyalázatára van a népeknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 35, 'A királynak jóakaratja van az eszes szolgához; haragja pedig a megszégyenítőhöz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 1, 'Az engedelmes felelet elfordítja a harag felgerjedését; a megbántó beszéd pedig támaszt haragot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 2, 'A bölcsek nyelve beszél jó tudományt: a tudatlanoknak száján pedig bolondság buzog ki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 3, 'Minden helyeken vannak az Úrnak szemei, nézvén a jókat és gonoszokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 4, 'A nyelv szelídsége életnek fája; az abban való hamisság pedig a léleknek gyötrelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 5, 'A bolond megútálja az ő atyjának tanítását; a ki pedig megbecsüli a dorgálást, igen eszes.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 6, 'Az igaznak házában nagy kincs van; az istentelennek jövedelmében pedig háborúság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 7, 'A bölcseknek ajkaik hintegetnek tudományt; a bolondoknak pedig elméje nem helyes.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 8, 'Az istentelenek áldozatja gyűlölséges az Úrnak; az igazak könyörgése pedig kedves néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 9, 'Utálat az Úrnál az istentelennek úta; azt pedig, a ki követi az igazságot, szereti.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 10, 'Gonosz dorgálás jő arra, a ki útját elhagyja; a ki gyűlöli a fenyítéket, meghal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 11, 'A sír és a pokol az Úr előtt vannak; mennyivel inkább az emberek szíve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 12, 'Nem szereti a csúfoló a feddést, és a bölcsekhez nem megy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 13, 'A vidám elme megvidámítja az orczát; de a szívnek bánatja miatt a lélek megszomorodik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 14, 'Az eszesnek elméje keresi a tudományt; a tudatlanok szája pedig legel bolondságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 15, 'Minden napjai a szegénynek nyomorúságosak; a vidám elméjűnek pedig szüntelen lakodalma van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 16, 'Jobb a kevés az Úrnak félelmével, mint a temérdek kincs, a hol háborúság van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 17, 'Jobb a paréjnak étele, a hol szeretet van, mint a hízlalt ökör, a hol van gyűlölség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 18, 'A haragos férfiú szerez háborúságot; a hosszútűrő pedig lecsendesíti a háborgást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 19, 'A restnek útja olyan, mint a tövises sövény; az igazaknak pedig útja megegyengetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 20, 'A bölcs fiú örvendezteti az atyját; a bolond ember pedig megútálja az anyját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 21, 'A bolondság öröme az esztelennek; de az értelmes férfiú igazán jár.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 22, 'Hiábavalók lesznek a gondolatok, mikor nincs tanács; de a tanácsosok sokaságában előmennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 23, 'Öröme van az embernek szája feleletében; és az idejében mondott beszéd, oh mely igen jó!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 24, 'Az életnek úta felfelé van az értelmes ember számára, hogy eltávozzék a pokoltól, mely aláfelé van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 25, 'A kevélyeknek házát kiszakgatja az Úr; megerősíti pedig az özvegynek határát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 26, 'Útálatosak az Úrnak a gonosz gondolatok; de kedvesek a tiszta beszédek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 27, 'Megháborítja az ő házát, a ki követi a telhetetlenséget; a ki pedig gyűlöli az ajándékokat, él az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 28, 'Az igaznak elméje meggondolja, mit szóljon; az istenteleneknek pedig szája ontja a gonoszt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 29, 'Messze van az Úr az istentelenektől; az igazaknak pedig könyörgését meghallgatja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 30, 'A szemek világa megvidámítja a szívet; a jó hír megerősíti a csontokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 31, 'A mely fül hallgatja az életnek dorgálását, a bölcsek között lakik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 32, 'A ki elvonja magát az erkölcsi tanítástól, megútálja az ő lelkét; a ki pedig hallgatja a feddést, értelmet szerez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 33, 'Az Úrnak félelme a bölcseségnek tudománya, és a tisztességnek előtte jár az alázatosság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 1, 'Az embernél vannak az elme gondolatjai; de az Úrtól van a nyelv felelete.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 2, 'Minden útai tiszták az embernek a maga szemei előtt; de a ki a lelkeket vizsgálja, az Úr az!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 3, 'Bízzad az Úrra a te dolgaidat; és a te gondolatid véghez mennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 4, 'Mindent teremtett az Úr az ő maga czéljára; az istentelent is a büntetésnek napjára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 5, 'Útálatos az Úrnak minden, a ki elméjében felfuvalkodott, kezemet adom rá, hogy nem marad büntetetlen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 6, 'Könyörületességgel és igazsággal töröltetik el a bűn; és az Úrnak félelme által távozhatunk el a gonosztól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 7, 'Mikor jóakarattal van az Úr valakinek útaihoz, még annak ellenségeit is jóakaróivá teszi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 8, 'Jobb a kevés igazsággal, mint a gazdag jövedelem hamissággal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 9, 'Az embernek elméje gondolja meg az ő útát; de az Úr igazgatja annak járását.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 10, 'Jósige van a király ajkain; az ítéletben ne szóljon hamisságot az ő szája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 11, 'Az Úré az igaz mérték és mérőserpenyő, az ő műve minden mérőkő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 12, 'Útálatos legyen a királyoknál istentelenséget cselekedni; mert igazsággal erősíttetik meg a királyiszék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 13, 'Kedvesek a királyoknak az igaz beszédek; és az igazmondót szereti a király.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 14, 'A királynak felgerjedt haragja olyan, mint a halál követe; de a bölcs férfiú leszállítja azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 15, 'A királynak vidám orczájában élet van; jóakaratja olyan, mint a tavaszi eső fellege.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 16, 'Szerzeni bölcseséget, oh menynyivel jobb az aranynál; és szerzeni eszességet, kivánatosb az ezüstnél!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 17, 'Az igazak országútja eltávozás a gonosztól; megtartja magát az, a ki megőrzi az ő útát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 18, 'A megromlás előtt kevélység jár, és az eset előtt felfuvalkodottság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 19, 'Jobb alázatos lélekkel lenni a szelídekkel, mint zsákmányon osztozni a kevélyekkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 20, 'A ki figyelmez az igére, jót nyer; és a ki bízik az Úrban, oh mely boldog az!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 21, 'A ki elméjében bölcs, hívatik értelmesnek; a beszédnek pedig édessége neveli a tudományt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 22, 'Életnek kútfeje az értelem annak, a ki bírja azt; de a bolondok fenyítéke bolondságuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 23, 'A bölcsnek elméje értelmesen igazgatja az ő száját, és az ő ajkain öregbíti a tudományt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 24, 'Lépesméz a gyönyörűséges beszédek; édesek a léleknek, és meggyógyítói a tetemeknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 25, 'Van oly út, mely igaz az ember szeme előtt, de vége a halálnak úta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 26, 'A munkálkodó lelke magának munkálkodik; mert az ő szája kényszeríti őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 27, 'A haszontalan ember gonoszt ás ki, és az ő ajkain mintegy égő tűz van;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 28, 'A gonosz ember versengést szerez, és a susárló elválasztja a jó barátokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 29, 'Az erőszakos ember elhiteti az ő felebarátját, és nem jó úton viszi őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 30, 'A ki behúnyja szemeit, azért teszi, hogy álnokságot gondoljon; a ki összeszorítja ajkait, már véghez vitte a gonoszságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 31, 'Igen szép ékes korona a vénség, az igazságnak útában találtatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 32, 'Jobb a hosszútűrő az erősnél; és a ki uralkodik a maga indulatján, annál, a ki várost vesz meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 33, 'Az ember kebelében vetnek sorsot; de az Úrtól van annak minden ítélete.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 1, 'Jobb a száraz falat, melylyel van csendesség; mint a levágott barmokkal teljes ház, melyben háborúság van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 2, 'Az értelmes szolga uralkodik a gyalázatos fiún, és az atyafiak között az örökségnek részét veszi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 3, 'Az olvasztótégely az ezüst számára van, és a kemencze az aranyéra; a szívek vizsgálója pedig az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 4, 'A gonosztevő hallgat az álnok beszédekre, a csalárd hallgat a gonosz nyelvre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 5, 'A ki megcsúfolja a szegényt, gyalázattal illeti annak Teremtőjét; a ki gyönyörködik másnak nyomorúságában, büntetlen nem lészen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 6, 'A véneknek ékessége az unokák, és a fiaknak ékessége az atyák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 7, 'Nem illik a bolondnak az ékes beszéd; még kevésbbé a tisztességesnek a hazug beszéd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 8, 'Drága kő az ajándék elfogadójának szemei előtt; mindenütt, a hova csak fordul, okosan cselekszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 9, 'Elfedezi a vétket, a ki keresi a szeretetet; a ki pedig ismétlen előhoz egy dolgot, elszakasztja egymástól a barátságosokat is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 10, 'Foganatosb a dorgálás az eszesnél, mint ha megvernéd a bolondot százszor is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 11, 'Csak ellenkezést keres a gonosz, végre kegyetlen követ bocsáttatik ellene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 12, 'Találjon valakire a fiától megfosztott medve, csak ne a bolond az ő bolondságában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 13, 'A ki fizet gonoszt a jóért, nem távozik el a gonosz annak házától.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 14, 'Mint a ki árvizet szabadít el, olyan a háborúság kezdete; azért minekelőtte kihatna, hagyd el a versengést.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 15, 'A ki igaznak mondja a bűnöst, és kárhoztatja az igazat, útálatos az Úrnak egyaránt mind a kettő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 16, 'Miért van a vétel ára a bolondnak kezében a bölcseség megszerzésére, holott nincsen néki elméje?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 17, 'Minden időben szeret, a ki igaz barát, és testvérül születik a nyomorúság idejére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 18, 'Értelmetlen ember az, a ki kezét adja, fogadván kezességet barátja előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 19, 'Szereti a gonoszt, a ki szereti a háborúságot; a ki magasbítja kapuját, romlást keres.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 20, 'Az elfordult szívű ember nem nyerhet jót, és a ki az ő nyelvével gonosz, esik nyomorúságba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 21, 'A ki szül bolondot, szüli ő magának bánatra; és nem örvendez a bolondnak atyja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 22, 'A vidám elme jó orvosságul szolgál; a szomorú lélek pedig megszáraztja a csontokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 23, 'A kebelből kivett ajándékot az istentelen elveszi, a törvény útának elfordítására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 24, 'Az eszesnek orczájából kitetszik a bölcseség; a bolondnak pedig szemei országolnak a földnek végéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 25, 'Búsulása az ő atyjának a bolond fiú, és az ő szülőjének keserűsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 26, 'Még megbirságolni is az igazat nem jó, a tisztességest megverni igazságáért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 27, 'A ki megtartóztatja beszédét, az tudós ember, és a ki higgadt lelkű, az értelmes férfiú.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 28, 'Még a bolond is, amikor hallgat, bölcsnek ítéltetik; mikor ajkait bezárja, eszesnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 1, 'A maga kivánsága után megy az agyas ember, minden igaz bölcseség ellen dühösködik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 2, 'Nem gyönyörködik a bolond az értelemben, hanem abban, hogy az ő elméje nyilvánvalóvá legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 3, 'Mikor eljő az istentelen, eljő a megútálás; és a szidalommal a gyalázat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 4, 'Mély víz az ember szájának beszéde, buzogó patak a bölcseségnek kútfeje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 5, 'A gonosz személyének kedvezni nem jó, elfordítani az igazat az ítéletben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 6, 'A bolondnak beszédei szereznek versengést, és az ő szája ütésekért kiált.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 7, 'A bolondnak szája az ő romlása, és az ő beszédei az ő életének tőre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 8, 'A susárlónak beszédei hizelkedők; és azok a szív belsejét áthatják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 9, 'A ki lágyan viseli magát az ő dolgában, testvére annak, a ki tönkre tesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 10, 'Erős torony az Úrnak neve, ahhoz folyamodik az igaz, és bátorságos lészen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 11, 'A gazdagnak vagyona az ő erős városa, és mint a magas kőfal, az ő gondolatja szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 12, 'A megromlás előtt felfuvalkodik az ember elméje; a tisztesség előtt pedig alázatosság van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 13, 'A ki felel valamit, míg meg nem hallja, ez bolondság és gyalázatos rá nézve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 14, 'A férfiú lelke elviseli a maga erőtlenségét; de a megtört lelket ki viseli el?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 15, 'Az eszesnek elméje tudományt szerez, és a bölcseknek füle tudományt keres.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 16, 'Az embernek ajándéka szabad útat szerez néki, és a nagyoknak orczája elé viszi őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 17, 'Igaza van annak, a ki első a perben; mígnem eljő az ő peresfele, és megvizsgálja őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 18, 'A versengéseket megszünteti a sorsvetés, és az erőseket elválasztja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 19, 'A felingerelt atyafiú erősb az erős városnál, és az ilyen versengések olyanok, mint a vár zárja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 20, 'A férfi szájának hasznával elégedik meg az ő belseje; az ő beszédének jövedelmével lakik jól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 21, 'Mind a halál, mind az élet a nyelv hatalmában van, és a miképen kiki szeret azzal élni, úgy eszi annak gyümölcsét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 22, 'Megnyerte a jót, a ki talált feleséget, és vett jóakaratot az Úrtól!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 23, 'Alázatos kérést szól a szegény; a gazdag pedig keményen felel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 24, 'Az ember, a kinek sok barátja van, széttöretik; de van barát, a ki ragaszkodóbb a testvérnél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 1, 'Jobb a tökéletesen járó szegény a gonosz nyelvűnél, a ki bolond.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 2, 'A lélek sem jó tudomány nélkül; és a ki csak a lábával siet, hibázik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 3, 'Az embernek bolondsága fordítja el az ő útát, és az Úr ellen haragszik az ő szíve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 4, 'A gazdagság szaporítja a sok barátot; a szegénytől pedig az ő barátja elválik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 5, 'A hamis tanú büntetetlen nem marad, és a hazugságoknak szólója meg nem szabadul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 6, 'Sokan hizelegnek a nemeslelkű embernek, és minden barát az adakozóé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 7, 'A szegényt minden atyjafia gyűlöli, még barátai is eltávolodnak tőle; unszolja szavakkal, de ők eltünnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 8, 'A ki értelmet szerez, szereti az életét, a ki megőrzi az értelmességet, jót nyer.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 9, 'A hamis bizonyság nem marad büntetlen, és a ki hazugságokat beszél, elvész.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 10, 'Nem illik a bolondhoz a gyönyörködés; sokkal inkább nem illik a szolgának uralkodni a fejedelmeken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 11, 'Az embernek értelme hosszútűrővé teszi őt; és ékességére van néki elhallgatni a vétket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 12, 'Mint az ifjú oroszlánnak ordítása, olyan a királynak haragja; mint a harmat pedig a füvön, az ő jóakaratja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 13, 'Romlása az ő atyjának a bolond fiú, és mint a szüntelen csepegés, az asszonynak zsémbelődése.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 14, 'A ház és marha atyától való örökség; az Úrtól van pedig az értelmes feleség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 15, 'A restség álomba merít, és a lomha lélek megéhezik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 16, 'A ki megtartja a parancsolatot, megtartja ő magát; a ki nem vigyáz útaira, meghal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 17, 'Kölcsön ád az Úrnak, a ki kegyelmes a szegényhez; és az ő jótéteményét megfizeti néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 18, 'Fenyítsd meg a te fiadat, mert még van remény felőle; de annyira, hogy őt megöld, ne vigyen haragod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 19, 'A nagy haragú ember büntetést szenvedjen, mert ha menteni akarod, még növeled haragját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 20, 'Engedj a tanácsnak, és vedd be az erkölcsi oktatást; hogy bölcs légy végre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 21, 'Sok gondolat van az ember elméjében; de csak az Úrnak tanácsa áll meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 22, 'A mit leginkább kell embernek kivánni, az irgalmasság az, és jobb a szegény a hazug férfiúnál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 23, 'Az Úrnak félelme életre visz; és az ilyen megelégedve tölti az éjet, gonoszszal nem illettetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 24, 'Bemártja a rest az ő kezét a tálba, de már a szájához nem viszi vissza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 25, 'Ha a csúfolót megvered, az együgyű lesz okosabb; és ha megdorgálod az eszest, megérti a tudományt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 26, 'A ki atyjával erőszakoskodik, anyját elűzi: gyalázatos és megszégyenítő fiú az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 27, 'Szünjél meg, fiam, hallgatni az olyan tanítást, mely téged arra visz, hogy a bölcseségnek igéjétől eltévedj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 28, 'A semmirevaló bizonyság csúfolja a törvényt; az istentelenek szája elnyeli a gonoszságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 29, 'A csúfolóknak készíttettek a büntetések, és az ütések a bolondok hátának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 1, 'A bor csúfoló, a részegítő ital háborgó, és valaki abba beletéved, nem bölcs!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 2, 'Mint a fiatal oroszlán ordítása, olyan a királynak rettentése; a ki azt haragra ingerli, vétkezik a maga élete ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 3, 'Tisztesség az embernek elmaradni a versengéstől; valaki pedig bolond, patvarkodik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 4, 'A hideg miatt nem szánt a rest; aratni akar majd, de nincs mit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 5, 'Mély víz a férfiúnak elméjében a tanács; mindazáltal a bölcs ember kimeríti azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 6, 'A legtöbb ember talál valakit, a ki jó hozzá; de hű embert, azt ki találhat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 7, 'A ki az ő tökéletességében jár, igaz ember; boldogok az ő fiai ő utána!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 8, 'A király, ha az ő ítélőszékiben ül, tekintetével minden gonoszt eltávoztat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 9, 'Ki mondhatná azt: megtisztítottam szívemet, tiszta vagyok az én bűnömtől?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 10, 'A kétféle font és a kétféle mérték, útálatos az Úrnál egyaránt mind a kettő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 11, 'Az ő cselekedetiből ismerteti meg magát még a gyermek is, ha tiszta-é, és ha igaz-é az ő cselekedete.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 12, 'A halló fület és a látó szemet, az Úr teremtette egyaránt mindkettőt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 13, 'Ne szeresd az álmot, hogy ne légy szegény; nyisd fel a te szemeidet, és megelégszel kenyérrel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 14, 'Hitvány, hitvány, azt mondja a vevő; de mikor elmegy, akkor dicsekedik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 15, 'Van arany és drágagyöngyök sokasága; de drága szer a tudománynyal teljes ajak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 16, 'Vedd el ruháját, mert kezes lett másért, és az idegenért vedd el zálogát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 17, 'Gyönyörűséges az embernek az álnokságnak kenyere; de annakutána betelik az ő szája kavicsokkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 18, 'A gondolatok tanácskozással erősek; és bölcs vezetéssel folytass hadakozást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 19, 'Megjelenti a titkot, a ki rágalmazó; tehát a ki fecsegő szájú, azzal ne barátkozzál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 20, 'A ki az ő atyját vagy anyját megátkozza, annak kialszik szövétneke a legnagyobb setétségben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 21, 'A mely örökséget először siettetnek, annak vége meg nem áldatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 22, 'Ne mondd: bosszút állok rajta! Várjad az Urat, és megszabadít téged!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 23, 'Útálatos az Úrnál a kétféle súly; és a hamis fontok nem jó dolgok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 24, 'Az Úrtól vannak a férfi lépései; az ember pedig mit ért az ő útában?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 25, 'Tőr az embernek meggondolatlanul mondani: szent, és a fogadástétel után megfontolni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 26, 'Szétszórja a gonoszokat a bölcs király, és fordít reájok kereket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 27, 'Az Úrtól való szövétnek az embernek lelke, a ki megvizsgálja a szívnek minden rejtekét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 28, 'A kegyelmesség és az igazság megőrzik a királyt, megerősíti irgalmasság által az ő székét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 29, 'Az ifjaknak ékessége az ő erejök; és a véneknek dísze az ősz haj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 30, 'A kékek és a sebek távoztatják el a gonoszt, és a belső részekig ható csapások.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 1, 'Mint a vizeknek folyásai, olyan a királynak szíve az Úrnak kezében, valahová akarja, oda hajtja azt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 2, 'Az embernek minden úta igaz a maga szemei előtt; de a szívek vizsgálója az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 3, 'Az igazságnak és igaz ítéletnek gyakorlását inkább szereti az Úr az áldozatnál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 4, 'A szemnek fenhéjázása és az elmének kevélysége: az istentelenek szántása, bűn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 5, 'A szorgalmatosnak igyekezete csak gyarapodásra van; valaki pedig hirtelenkedik, csak szükségre jut.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 6, 'A hamisságnak nyelvével gyűjtött kincs elveszett hiábavalósága azoknak, a kik a halált keresik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 7, 'Az istentelenek pusztítása magával ragadja őket; mert nem akartak igazságot cselekedni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 8, 'Tekervényes a bűnös embernek úta; a tisztának cselekedete pedig igaz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 9, 'Jobb a tető ormán lakni, mint háborgó asszonynyal, és közös házban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 10, 'Az istentelennek lelke kiván gonoszt; és az ő szeme előtt nem talál könyörületre az ő felebarátja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 11, 'Mikor a csúfolót büntetik, az együgyű lesz bölcs; mikor pedig a bölcset oktatják, ő veszi eszébe a tudományt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 12, 'Nézi az igaz az istentelennek házát, hogy milyen veszedelembe jutottak az istentelenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 13, 'A ki bedugja fülét a szegény kiáltására; ő is kiált, de meg nem hallgattatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 14, 'A titkon adott ajándék elfordítja a haragot; és a kebelben való ajándék a kemény búsulást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 15, 'Vígasság az igaznak igazat cselekedni; de ijedelem a hamisság cselekedőinek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 16, 'Az ember, a ki eltévelyedik az értelemnek útáról, az élet nélkül valók gyülekezetiben nyugszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 17, 'Szűkölködő ember lesz, a ki szereti az örömet; a ki szereti a bort és az olajat, nem lesz gazdag!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 18, 'Az igazért váltságdíj az istentelen, és az igazak helyett a hitetlen büntettetik meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 19, 'Jobb lakozni a pusztának földén, mint a feddődő és haragos asszonynyal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 20, 'Kivánatos kincs és kenet van a bölcsnek házában; a bolond ember pedig eltékozolja azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 21, 'A ki követi az igazságot és az irgalmasságot, nyer életet, igazságot és tisztességet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 22, 'A hősök városába felmegy a bölcs, és lerontja az ő bizodalmoknak erejét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 23, 'A ki megőrzi száját és nyelvét, megtartja életét a nyomorúságtól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 24, 'A kevély dölyfösnek csúfoló a neve, a ki haragjában kevélységet cselekszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 25, 'A restnek kivánsága megemészti őt; mert az ő kezei nem akarnak dolgozni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 26, 'Egész nap kivánságtól gyötretik; az igaz pedig ád, és nem tartóztatja meg adományát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 27, 'Az istentelenek áldozatja útálatos; kivált mikor gonosz tettért viszi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 28, 'A hazug bizonyság elvész; a ki pedig jól figyelmez, örökké szól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 29, 'Megkeményíti az istentelen ember az ő orczáját; az igaz pedig jól rendeli az ő útát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 30, 'Nincs bölcseség, és nincs értelem, és nincs tanács az Úr ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 31, 'Készen áll a ló az ütközetnek napjára; de az Úré a megtartás!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 1, 'Kivánatosb a jó hírnév nagy gazdagságnál; ezüstnél és aranynál a kedvesség jobb.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 2, 'A gazdag és szegény összetalálkoznak, mindkettőt pedig az Úr szerzi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 3, 'Az eszes meglátja a bajt és elrejti magát; a bolondok pedig neki mennek és kárát vallják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 4, 'Az alázatosságnak bére az Úr félelme, gazdagság és tisztesség és élet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 5, 'Tövisek és tőrök vannak a gonosznak útában; a ki megőrzi a maga lelkét, távol jár azoktól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 6, 'Tanítsd a gyermeket az ő útjának módja szerint; még mikor megvénhedik is, el nem távozik attól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 7, 'A gazdag a szegényeken uralkodik, és szolgája a kölcsönvevő a kölcsönadónak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 8, 'A ki vet álnokságot, arat nyomorúságot; és az ő haragjának vesszeje megtöretik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 9, 'Az irgalmas szemű ember megáldatik, mert adott az ő kenyeréből a szegénynek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 10, 'Űzd el a csúfolót, és elmegy a háborgás is, és megszünik a patvarkodás és a szidalmazás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 11, 'A ki szereti a szívnek tisztaságát, beszéde kedvesség: annak barátja a király.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 12, 'Az Úrnak szemei megőrzik a tudományt; a hitetlennek beszédét pedig felforgatja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 13, 'A rest azt mondja: oroszlán van ottkin, az utczák közepén megölettetném.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 14, 'Mély verem az idegen asszonyoknak szája; a kire haragszik az Úr, oda esik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 15, 'A gyermek elméjéhez köttetett a bolondság; de a fenyítés vesszeje messze elűzi ő tőle azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 16, 'A ki elnyomja a szegényt, hogy szaporítsa az ő marháját; a ki ád a gazdagnak: végre szűkölködésre jut.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 17, 'Hajtsd füledet, és hallgasd a bölcseknek beszédeit; és a te elmédet figyelmeztesd az én tudományomra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 18, 'Mert gyönyörűséges lesz, ha megtartod azokat szívedben; legyenek együtt állandók a te ajkaidon!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 19, 'Hogy az Úrban legyen a te bizodalmad, arra tanítottalak ma téged, igen, téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 20, 'Nem írtam-é néked drága szép tanulságokat, tanácsokban és tudományban?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 21, 'Hogy tudtodra adjam néked az igazság beszédinek bizonyos voltát: hogy igaz beszédet vígy válaszul elküldőidnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 22, 'Ne rabold ki a szegényt, mert szegény ő; és meg ne rontsd a nyomorultat a kapuban;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 23, 'Mert az Úr forgatja azoknak ügyét, és az ő kirablóik életét elragadja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 24, 'Ne tarts barátságot a haragossal, és a dühösködővel ne menj;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 25, 'Hogy el ne tanuld az ő útait, és tőrt ne keress tennen magadnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 26, 'Ne légy azok közt, a kik kézbe csapnak, a kik adósságért kezeskednek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 27, 'Ha nincs néked miből megadnod; miért vegye el a te ágyadat te alólad?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 28, 'Ne bontsd el a régi határt, melyet csináltak a te eleid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 29, 'Láttál-é az ő dolgában szorgalmatos embert? A királyok előtt álland, nem marad meg az alsó rendűek között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 1, 'Mikor leülsz enni az uralkodóval, szorgalmasan reá vigyázz, ki van előtted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 2, 'És kést tégy a torkodra, ha mértékletlen vagy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 3, 'Ne kivánd az ő csemegéit; mert ezek hazug étkek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 4, 'Ne fáraszd magadat ebben, hogy meggazdagulj; ez ilyen testi eszességedtől szünjél meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 5, 'Avagy a te szemeidet veted-é arra? holott az semmi, mert olyan szárnyakat szerez magának nagy hamar, mint a saskeselyű, és az ég felé elrepül!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 6, 'Ne egyél az irígy szeműnek étkéből, és ne kivánd az ő csemegéit;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 7, 'Mert mint a ki számítgatja a falatot magában, olyan ő: egyél és igyál, azt mondja te néked; de azért nem jó akarattal van tehozzád.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 8, 'A te falatodat, a melyet megettél, kihányod; és a te ékes beszédidet csak hiába vesztegeted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 9, 'A bolondnak hallására ne szólj; mert megútálja a te beszédidnek bölcseségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 10, 'Ne mozdítsd meg a régi határt, és az árváknak mezeibe ne kapj;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 11, 'Mert az ő megváltójuk erős, az forgatja az ő ügyöket ellened!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 12, 'Add a te elmédet az erkölcsi tanításra, és a te füleidet a bölcs beszédekre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 13, 'Ne vond el a gyermektől a fenyítéket; ha megvered őt vesszővel, meg nem hal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 14, 'Te vesszővel vered meg őt: és az ő lelkét a pokolból ragadod ki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 15, 'Szerelmes fiam, ha bölcs lesz a te elméd, örvendez a lelkem nékem is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 16, 'És vígadoznak az én veséim, a te ajkaidnak igazmondásán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 17, 'Ne irígykedjék a te szíved a bűnösökre; hanem az Úr félelmében légy egész napon;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 18, 'Mert ennek bizonyos vége van; a te várakozásod meg nem csalatkozik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 19, 'Hallgass te, fiam, engem, hogy légy bölcs, és jártasd ez úton szívedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 20, 'Ne légy azok közül való, a kik borral dőzsölnek; azok közül, a kik hússal dobzódnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 21, 'Mert a részeges és dobzódó szegény lesz, és rongyokba öltöztet az aluvás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 22, 'Hallgasd a te atyádat, a ki nemzett téged; és meg ne útáld a te anyádat, mikor megvénhedik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 23, 'Szerezz igazságot, és el ne adj; bölcseséget és erkölcsöt és eszességet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 24, 'Igen örül az igaznak atyja, és a bölcsnek szülője annak vígadoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 25, 'Vígadjon a te atyád és a te anyád, és örvendezzen a te szülőd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 26, 'Adjad, fiam, a te szívedet nékem, és a te szemeid az én útaimat megőrizzék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 27, 'Mert mély verem a tisztátalan asszony, és szoros kút az idegen asszony.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 28, 'És az, mint a tolvaj leselkedik, és az emberek közt a hitetleneket szaporítja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 29, 'Kinek jaj? kinek oh jaj? kinek versengések? kinek panasz? kinek ok nélkül való sebek? kinek szemeknek veressége?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 30, 'A bornál mulatóknak, a kik mennek a jó bor kutatására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 31, 'Ne nézd a bort, mily veres színt játszik, mint mutatja a pohárban az ő csillogását; könnyen alá csuszamlik,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 32, 'Végre, mint a kígyó, megmar, és mint a mérges kígyó, megcsíp.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 33, 'A te szemeid nézik az idegen asszonyt, és a te elméd gondol gonoszságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 34, 'És olyan leszel, mint a ki fekszik a tenger közepiben, és a ki fekszik az árbóczfának tetején.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 35, 'Ütöttek engem, nékem nem fájt; vertek, nem éreztem! Mikor ébredek fel? Akkor folytatom, ismét megkeresem azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 1, 'Ne irígykedjél a gonosztevőkre, se ne kivánj azokkal lenni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 2, 'Mert pusztítást gondol az ő szívök, és bajt szólnak az ő ajkaik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 3, 'Bölcseség által építtetik a ház, és értelemmel erősíttetik meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 4, 'És tudomány által telnek meg a kamarák minden drága és gyönyörűséges marhával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 5, 'A bölcs férfiú erős, és a tudós ember nagy erejű.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 6, 'Mert az eszes tanácsokkal viselhetsz hadat hasznodra; és a megmaradás a tanácsosok sokasága által van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 7, 'Magas a bolondnak a bölcseség; a kapuban nem nyitja meg az ő száját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 8, 'A ki azon gondolkodik, hogy gonoszt cselekedjék, azt cselszövőnek hívják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 9, 'A balgatag dolognak gondolása bűn; és a rágalmazó az ember előtt útálatos.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 10, 'Ha lágyan viselted magadat a nyomorúságnak idején: szűk a te erőd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 11, 'Szabadítsd meg azokat, a kik a halálra vitetnek, és a kik a megöletésre tántorognak, tartóztasd meg!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 12, 'Ha azt mondanád: ímé, nem tudtuk ezt; nemde, a ki vizsgálja az elméket, ő érti, és a ki őrzi a te lelkedet, ő tudja? és kinek-kinek az ő cselekedetei szerint fizet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 13, 'Egyél, fiam, mézet, mert jó; és a színméz édes a te ínyednek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 14, 'Ilyennek ismerd a bölcseséget a te lelkedre nézve: ha azt megtalálod, akkor lesz jó véged, és a te reménységed el nem vész!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 15, 'Ne leselkedjél, oh te istentelen, az igaznak háza ellen, ne pusztítsd el az ő ágyasházát!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 16, 'Mert ha hétszer elesik is az igaz, ugyan felkél azért; az istentelenek pedig csak egy nyavalyával is elvesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 17, 'Mikor elesik a te ellenséged: ne örülj; és mikor megütközik: ne vígadjon a te szíved,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 18, 'Hogy az Úr meg ne lássa és gonosz ne legyen szemeiben, és el ne fordítsa arról az ő haragját te reád.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 19, 'Ne gerjedj haragra a gonosztevők ellen, ne irígykedjél az istentelenekre;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 20, 'Mert a gonosznak nem lesz jó vége, az istentelenek szövétneke kialszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 21, 'Féld az Urat, fiam, és a királyt; a pártütők közé ne elegyedjél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 22, 'Mert hirtelenséggel feltámad az ő nyomorúságok, és e két rendbeliek büntetését ki tudja?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 23, 'Ezek is a bölcsek szavai. Személyt válogatni az ítéletben nem jó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 24, 'A ki azt mondja az istentelennek: igaz vagy, ezt megátkozzák a népek, megútálják a nemzetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 25, 'A kik pedig megfeddik a bűnöst, azoknak gyönyörűségökre lesz, és jó áldás száll reájok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 26, 'Ajkakat csókolgat az, a ki igaz beszédeket felel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 27, 'Szerezd el kivül a te dolgodat, és készíts elő a te meződben; annakutána építsd a házadat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 28, 'Ne légy bizonyság ok nélkül a te felebarátod ellen; avagy ámítanál-é valakit a te ajkaiddal?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 29, 'Ne mondd ezt: a miképen cselekedett én velem, úgy cselekszem ő vele; megfizetek az embernek az ő cselekedete szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 30, 'A rest embernek mezejénél elmenék, és az esztelennek szőleje mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 31, 'És ímé, mindenütt felverte a tövis, és színét elfedte a gyom; és kőgyepüje elromlott vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 32, 'Melyet én látván gondolkodám, és nézvén, ezt a tanulságot vevém abból:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 33, 'Egy kis álom, egy kis szunynyadás, egy kis kézösszetevés az alvásra,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 34, 'És így jő el, mint az útonjáró, a te szegénységed, és a te szükséged, mint a paizsos férfiú.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 1, 'Még ezek is Salamon példabeszédei, melyeket összeszedegettek Ezékiásnak, a Júda királyának emberei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 2, 'Az Istennek tisztességére van a dolgot eltitkolni; a királyoknak pedig tisztességére van a dolgot kikutatni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 3, 'Az ég magasságra, a föld mélységre, és a királyoknak szíve kikutathatatlan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 4, 'Távolítsd el az ezüstből a salakot, és abból edény lesz az ötvösnek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 5, 'Távolítsd el a bűnöst a király elől, és megerősíttetik igazsággal az ő széke.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 6, 'Ne dicsekedjél a király előtt, és a nagyok helyére ne állj;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 7, 'Mert jobb, ha azt mondják néked: jer ide fel; hogynem mint levettetned néked a tisztességes előtt, a kit láttak a te szemeid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 8, 'Ne indulj fel a versengésre hirtelen, hogy azt ne kelljen kérdened, mit cselekedjél az után, mikor gyalázattal illet téged a te felebarátod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 9, 'A te ügyedet végezd el felebarátoddal; de másnak titkát meg ne jelentsd;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 10, 'Hogy ne gyalázzon téged, a ki hallja; és a te gyalázatod el ne távozzék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 11, 'Mint az arany alma ezüst tányéron: olyan a helyén mondott ige!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 12, 'Mint az arany függő és színarany ékesség: olyan a bölcs intő a szófogadó fülnél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 13, 'Mint a havas hideg az aratásnak idején: olyan a hív követ azoknak, a kik őt elbocsátják; mert az ő urainak lelkét megvidámítja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 14, 'Mint a felhő és szél, melyekben nincs eső: olyan a férfiú, a ki kérkedik hamis ajándékkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 15, 'Tűrés által engeszteltetik meg a fejedelem, és a szelíd beszéd megtöri a csontot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 16, 'Ha mézet találsz, egyél a mennyi elég néked; de sokat ne egyél, hogy ki ne hányd azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 17, 'Ritkán tedd lábadat a te felebarátodnak házába; hogy be ne teljesedjék te veled, és meg ne gyűlöljön téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 18, 'Pőröly és kard és éles nyíl az olyan ember, a ki hamis bizonyságot szól felebarátja ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 19, 'Mint a romlott fog és kimarjult láb: olyan a hitetlennek bizodalma a nyomorúság idején.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 20, 'Mint a ki leveti ruháját a hidegnek idején, mint az eczet a sziksón: olyan, a ki éneket mond a bánatos szívű ember előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 21, 'Ha éhezik, a ki téged gyűlöl: adj enni néki kenyeret; és ha szomjúhozik: adj néki inni vizet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 22, 'Mert elevenszenet gyűjtesz az ő fejére, és az Úr megfizeti néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 23, 'Az északi szél esőt szül; és haragos ábrázatot a suttogó nyelv.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 24, 'Jobb lakni a tetőnek ormán, mint a háborgó asszonynyal, és közös házban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 25, 'Mint a hideg víz a megfáradt embernek, olyan a messze földről való jó hírhallás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 26, 'Mint a megháborított forrás és megromlott kútfő, olyan az igaz, a ki a gonosz előtt ingadozik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 27, 'Igen sok mézet enni nem jó; hát a magunk dicsőségét keresni dicsőség?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 28, 'Mint a megromlott és kerítés nélkül való város, olyan a férfi, a kinek nincsen birodalma az ő lelkén!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 1, 'Mint a hó a nyárhoz és az eső az aratáshoz, úgy nem illik a bolondhoz a tisztesség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 2, 'Miképen a madár elmegy és a fecske elrepül, azonképen az ok nélkül való átok nem száll az emberre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 3, 'Ostor a lónak, fék a szamárnak; és vessző a bolondok hátának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 4, 'Ne felelj meg a bolondnak az ő bolondsága szerint, hogy ne légy te is ő hozzá hasonlatos;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 5, 'Felelj meg a bolondnak az ő bolondsága szerint, hogy ne legyen bölcs a maga szemei előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 6, 'A ki bolond által izen valamit, lábait vagdalja el magának, és bosszúságot szenved.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 7, 'Mint a sántának lábai lógnak, úgy a bölcsmondás a bolondoknak szájában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 8, 'Mint a ki követ köt a parittyába, úgy cselekszik, a ki a bolondnak tisztességet tesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 9, 'Mint a részeg ember kezébe akad a tövis, úgy akad az eszes mondás a bolondoknak szájába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 10, 'Mint a lövöldöző, a ki mindent megsebez, olyan az, a ki bolondot fogad fel, és a ki csavargókat fogad fel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 11, 'Mint az eb megtér a maga okádására, úgy a bolond megkettőzteti az ő bolondságát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 12, 'Láttál-é oly embert, a ki a maga szemei előtt bölcs? A bolond felől jobb reménységed legyen, hogynem mint a felől!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 13, 'Azt mondja a rest: ordító oroszlán van az úton! oroszlán van az utczákon!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 14, 'Mint az ajtó forog az ő sarkán, úgy a rest az ő ágyában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 15, 'Ha a rest az ő kezét a tálba nyujtotta, resteli azt csak szájához is vinni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 16, 'Bölcsebb a rest a maga szemei előtt, mint hét olyan, a ki okos feleletet ád.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 17, 'Kóbor ebet ragad fülön, a ki felháborodik a perpatvaron, a mely őt nem illeti.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 18, 'Mint a balga, a ki tüzet, nyilakat és halálos szerszámokat lövöldöz,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 19, 'Olyan az, a ki megcsalja az ő felebarátját, és azt mondja: csak tréfáltam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 20, 'Ha a fa elfogy, kialuszik a tűz; ha nincs súsárló, megszűnik a háborgás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 21, 'Mint az elevenszénre a holtszén, és a fa a tűzre, olyan a háborúságszerző ember a patvarkodásnak felgyujtására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 22, 'A fondorlónak beszédei hízelkedők, és azok áthatják a szív belsejét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 23, 'Mint a meg nem tisztított ezüst, melylyel valami agyagedényt beborítottak, olyanok a gyulasztó ajkak a gonosz szív mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 24, 'Az ő beszédeivel másnak tetteti magát a gyűlölő, holott az ő szívében gondol álnokságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 25, 'Mikor kedvesen szól, ne bízzál ő hozzá; mert hét iszonyatosság van szívében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 26, 'Elfedeztethetik a gyűlölség csalással; de nyilvánvalóvá lesz az ő gonoszsága a gyülekezetben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 27, 'A ki vermet ás másnak, abba belé esik; és a ki felhengeríti a követ, arra gurul vissza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 28, 'A hazug nyelv gyűlöli az általa megrontott embert, és a hízelkedő száj romlást szerez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 1, 'Ne dicsekedjél a holnapi nappal; mert nem tudod, mit hoz a nap tereád.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 2, 'Dicsérjen meg téged más, és ne a te szájad; az idegen, és ne a te ajkaid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 3, 'Nehézség van a kőben, és teher a fövényben; de a bolondnak haragja nehezebb mind a kettőnél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 4, 'A búsulásban kegyetlenség van, és a haragban áradás; de ki állhatna meg az irígység előtt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 5, 'Jobb a nyilvánvaló dorgálás a titkos szeretetnél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 6, 'Jószándékból valók a barátságos embertől vett sebek; és temérdek a gyűlölőnek csókja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 7, 'A jóllakott ember még a lépesmézet is megtapodja; de az éhes embernek minden keserű édes.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 8, 'Mint a madárka, ki elbujdosott fészkétől, olyan az ember, a ki elbujdosott az ő lakóhelyétől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 9, 'Mint a kenet és jó illat megvídámítja a szívet: úgy az ő barátjának édes szavai is, melyek lelke tanácsából valók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 10, 'A te barátodat, és a te atyádnak barátját el ne hagyd, és a te atyádfiának házába be ne menj nyomorúságodnak idején. Jobb a közel való szomszéd a messze való atyafinál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 11, 'Légy bölcs fiam, és vídámítsd meg az én szívemet; hogy megfelelhessek annak, a ki engem ócsárol.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 12, 'Az eszes meglátja a bajt, elrejti magát; az esztelenek neki mennek, kárát vallják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 13, 'Vedd el a ruháját, mert kezes lett másért, és az idegenért zálogold meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 14, 'A ki nagy hangon áldja az ő barátját, reggel jó idején felkelvén; átokul tulajdoníttatik néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 15, 'A sebes záporeső idején való szüntelen csepegés, és a morgó asszonyember hasonlók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 16, 'Valaki el akarja azt rejteni, szelet rejt el, és az ő jobbja olajjal találkozik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 17, 'Miképen egyik vassal a másikat élesítik, a képen az ember élesíti az ő barátjának orczáját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 18, 'Mint a ki őrzi a fügét, eszik annak gyümölcséből, úgy a ki az ő urára vigyáz, tiszteltetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 19, 'Mint a vízben egyik orcza a másikat megmutatja, úgy egyik embernek szíve a másikat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 20, 'Mint a sír és a pokol meg nem elégednek, úgy az embernek szemei meg nem elégednek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 21, 'Mint az ezüst a tégelyben, és az arany a kemenczében próbáltatik meg, úgy az ember az ő híre-neve szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 22, 'Ha megtörnéd is a bolondot mozsárban mozsártörővel a megtört gabona között, nem távoznék el ő tőle az ő bolondsága.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 23, 'Szorgalmasan megismerd a te juhaid külsejét, gondolj a nyájakra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 24, 'Mert nem örökkévaló a gazdagság, és vajjon a korona nemzetségről nemzetségre lesz-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 25, 'Mikor levágatott a szénafű, és megtetszett a sarjú, és begyűjtettek a hegyekről a fűvek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 26, 'Vannak juhaid a te ruházatodra, és kecskebakok mezőnek árául,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 27, 'És elég kecsketej a te ételedre, a te házadnépének ételére, és szolgálóleányaidnak ételül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 1, 'Minden istentelen fut, ha senki nem üldözi is; az igazak pedig, mint az ifjú oroszlán, bátrak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 2, 'Az ország bűne miatt sok annak a fejedelme; az eszes és tudós ember által pedig hosszabbodik fennállása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 3, 'A szegény emberből támadott elnyomója a szegényeknek hasonló a pusztító esőhöz, mely nem hágy kenyeret.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 4, 'A kik elhagyják a törvényt, dicsérik a latrokat; de a kik megtartják a törvényt, harczolnak azokkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 5, 'A gonoszságban élő emberek nem értik meg az igazságot; a kik pedig keresik az Urat, mindent megértenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 6, 'Jobb a szegény, a ki jár tökéletesen, mint a kétfelé sántáló istentelen, a ki gazdag.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 7, 'A ki megőrzi a törvényt, eszes fiú az; a ki pedig társalkodik a dobzódókkal, gyalázattal illeti atyját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 8, 'A ki öregbíti az ő marháját kamattal és uzsorával, annak gyűjt, a ki könyörül a szegényeken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 9, 'Valaki elfordítja az ő fülét a törvénynek hallásától, annak könyörgése is útálatos.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 10, 'A ki elcsábítja az igazakat gonosz útra, vermébe maga esik bele; a tökéletesek pedig örökség szerint bírják a jót.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 11, 'Bölcs az ő maga szemei előtt a gazdag ember; de az eszes szegény megvizsgálja őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 12, 'Mikor örvendeznek az igazak, nagy ékesség az; mikor pedig az istentelenek feltámadnak, keresni kell az embert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 13, 'A ki elfedezi az ő vétkeit, nem lesz jó dolga; a ki pedig megvallja és elhagyja, irgalmasságot nyer.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 14, 'Boldog ember, a ki szüntelen retteg; a ki pedig megkeményíti az ő szívét, bajba esik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 15, 'Mint az ordító oroszlán és éhező medve, olyan a szegény népen uralkodó istentelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 16, 'Az értelemben szűkölködő fejedelem nagy elnyomó is; de a ki gyűlöli a hamis nyereséget, meghosszabbítja napjait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 17, 'Az ember, a kit ember-vér terhel, a sírig fut; senki ne támogassa őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 18, 'A ki jár tökéletesen, megtartatik; a ki pedig álnokul két úton jár, egyszerre elesik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 19, 'A ki munkálja az ő földét, megelégedik étellel; a ki pedig hiábavalóságok után futkos, megelégedik szegénységgel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 20, 'A hivő ember bővelkedik áldásokkal; de a ki hirtelen akar gazdagulni, büntetlen nem marad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 21, 'Személyt válogatni nem jó; mert még egy falat kenyérért is vétkezhetik az ember.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 22, 'Siet a marhakeresésre a gonosz szemű ember; és nem veszi észre, hogy szükség jő reá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 23, 'A ki megfeddi az embert, végre is inkább kedvességet talál, mint a sima nyelvű.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 24, 'A ki megrabolja az atyját, és anyját és azt mondja: nem vétek! társa a romboló embernek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 25, 'A telhetetlen lélek háborúságot szerez; a ki pedig bízik az Úrban, megerősödik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 26, 'A ki bízik magában, bolond az; a ki pedig jár bölcsen, megszabadul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 27, 'A ki ád a szegénynek, nem lesz néki szüksége; a ki pedig elrejti a szemét, megsokasulnak rajta az átkok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 28, 'Mikor felemeltetnek az istentelenek, elrejti magát az ember; de mikor azok elvesznek, öregbülnek az igazak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 1, 'A ki a feddésekre is nyakas marad, egyszer csak összetörik, gyógyíthatatlanul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 2, 'Mikor öregbülnek az igazak, örül a nép; mikor pedig uralkodik az istentelen, sóhajt a nép.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 3, 'A bölcseség-szerető ember megvidámítja az ő atyját; a ki pedig a paráznákhoz adja magát, elveszti a vagyont.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 4, 'A király igazsággal erősíti meg az országot; a ki pedig ajándékot vesz, elrontja azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 5, 'A férfiú, a ki hizelkedik barátjának, hálót vet annak lábai elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 6, 'A gonosz ember vétkében tőr van; az igaz pedig énekel és vígad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 7, 'Megérti az igaz a szegényeknek ügyét; az istentelen pedig nem tudja megérteni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 8, 'A csúfoló férfiak fellobbantják a várost; de a bölcsek elfordítják a haragot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 9, 'Az eszes ember, ha vetekedik a bolonddal, akár felháborodik, akár nevet, nincs nyugodalom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 10, 'A vérszomjasak gyűlölik a tökéletes embert; az igazak pedig oltalmazzák annak életét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 11, 'Az ő egész indulatját előmutatja a bolond; de a bölcs végre megcsendesíti azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 12, 'A mely uralkodó a hamisságnak beszédire hallgat, annak minden szolgái latrok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 13, 'A szegény és az uzsorás ember összetalálkoznak; mind a kettőnek pedig szemeit az Úr világosítja meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 14, 'A mely király hűségesen ítéli a szegényeket, annak széke mindörökké megáll.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 15, 'A vessző és dorgálás bölcseséget ád; de a szabadjára hagyott gyermek megszégyeníti az ő anyját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 16, 'Mikor nevekednek az istentelenek, nevekedik a vétek; az igazak pedig azoknak esetét megérik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 17, 'Fenyítsd meg a te fiadat, és nyugodalmat hoz néked, és szerez gyönyörűséget a te lelkednek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 18, 'Mikor nincs mennyei látás, a nép elvadul; ha pedig megtartja a törvényt, oh mely igen boldog!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 19, 'Csak beszéddel nem tanul meg a szolga, mert tudna, de még sem felel meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 20, 'Láttál-é beszédeiben hirtelenkedő embert? a bolond felől több reménység van, hogynem a felől!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 21, 'A ki lágyan neveli gyermekségétől fogva az ő szolgáját, végre az lesz a fiú.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 22, 'A haragos háborgást szerez; és a dühösködőnek sok a vétke.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 23, 'Az embernek kevélysége megalázza őt; az alázatos pedig tisztességet nyer.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 24, 'A ki osztozik a lopóval, gyűlöli az magát; hallja az esküt, de nem vall.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 25, 'Az emberektől való félelem tőrt vet; de a ki bízik az Úrban, kiemeltetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 26, 'Sokan keresik a fejedelemnek orczáját; de az Úrtól van kinek-kinek ítélete.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 27, 'Iszonyat az igazaknak a hamis ember; és iszonyat az istentelennek az igaz úton járó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 1, 'Agurnak, a Jáké fiának beszédei, próféczia, melyet mondott a férfiú Itielnek, Itielnek és Ukálnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 2, 'Minden embernél tudatlanabb vagyok én, és nincs emberi értelem én bennem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 3, 'És nem tanultam a bölcseséget, hogy a Szentnek ismeretét tudnám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 4, 'Kicsoda ment fel az égbe, hogy onnan leszállott volna? Kicsoda fogta össze a szelet az ő markába? Kicsoda kötötte a vizet az ő köntösébe? Ki állapította meg a földnek minden határit? Kicsoda ennek neve? Avagy kicsoda ennek fiának neve, ha tudod?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 5, 'Az Istennek teljes beszéde igen tiszta, és paizs az ahhoz folyamodóknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 6, 'Ne tégy az ő beszédéhez; hogy meg ne feddjen téged, és hazug ne légy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 7, 'Kettőt kérek tőled; ne tartsd meg én tőlem, mielőtt meghalnék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 8, 'A hiábavalóságot és a hazugságot messze távoztasd tőlem; szegénységet vagy gazdagságot ne adj nékem; táplálj engem hozzám illendő eledellel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 9, 'Hogy megelégedvén, meg ne tagadjalak, és azt ne mondjam: kicsoda az Úr? Se pedig megszegényedvén, ne lopjak, és gonoszul ne éljek az én Istenem nevével!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 10, 'Ne rágalmazd a szolgát az ő uránál, hogy meg ne átkozzon téged, és bűnhődnöd ne kelljen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 11, 'Van oly nemzetség, a ki az ő atyját átkozza, és az ő anyját nem áldja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 12, 'Van nemzetség, a ki a maga szemei előtt tiszta, pedig az ő rútságából ki nem tisztíttatott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 13, 'Van kevély szemű nemzetség, és a kinek szemöldökei igen fellátnak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 14, 'Van olyan nemzetség, a kinek fogai fegyverek, és a kinek zápfogai kések; hogy a szegényeket kiemészszék e földről, és az emberek közül a szűkölködőket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 15, 'A nadálynak két leánya van: addsza, addsza! E három nem elégszik meg; négyen nem mondják: elég;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 16, 'A sír és a meddő asszony, a föld meg nem elégszik a vízzel, és a tűz nem mondja: elég!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 17, 'A szemet, mely megcsúfolja atyját, vagy megútálja az anyja iránt való engedelmességet, kivágják a völgynek hollói, vagy megeszik a sasfiak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 18, 'E három megfoghatatlan előttem, és e négy dolgot nem tudom:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 19, 'A keselyűnek útát az égben, a kígyónak útát a kősziklán, a hajónak nyomát a mély tengerben, és a férfiúnak útát a leányzóval.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 20, 'Ilyen a paráználkodó asszonynak úta; eszik, azután megtörli száját és azt mondja: nem cselekedtem semmi gonoszt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 21, 'Három dolog alatt indul meg a föld, és négyet nem szenvedhet el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 22, 'A szolga alatt, mikor uralkodik, és a bolond alatt, mikor elég kenyere van,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 23, 'A gyűlölt asszony alatt, ha mégis férjhez megy; és a szolgáló alatt, ha örököse lesz az ő asszonyának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 24, 'E négy apró állata van a földnek, a melyek bölcsek, elmések:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 25, 'A hangyák erőtlen nép, mégis megkeresik nyárban a magok eledelét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 26, 'A marmoták nem hatalmas nép, mégis kősziklán csinálják az ő házokat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 27, 'Királyuk nincs a sáskáknak, mindazáltal mindnyájan szép renddel mennek ki;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 28, 'A pókot kézzel megfoghatod, mégis ott van a királyok palotáiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 29, 'Három állat van, a mely szépen jár, sőt négy, a mely jól jár.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 30, 'Az oroszlán, a hős a vadak között, mely el nem fut senki elől;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 31, 'A harczra felékesített ló, vagy a kecskebak, és a király, a kinek senki nem mer ellene állani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 32, 'Ha bolond voltál felfuvalkodásodban, vagy ha meggondoltad: kezedet szájadra vessed.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 33, 'Mert miképen a ki tejet köpül, vajat csinál; és a ki keményen fújja ki az ő orrát, vért hoz ki: úgy a ki a haragot ingerli, háborúságot szerez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 1, 'Lemuel király beszédei, próféczia, melylyel tanította vala őt az anyja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 2, 'Mit szóljak, fiam? mit, én méhem gyermeke? mit, én fogadásimnak gyermeke?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 3, 'Ne add asszonyoknak a te erődet, és a te útaidat a királyok eltörlőinek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 4, 'Távol legyen a királyoktól, oh Lemuel, távol legyen a királyoktól a bornak itala; és az uralkodóktól a részegítő ital keresése.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 5, 'Hogy mikor iszik, el ne felejtkezzék a törvényről, és el ne fordítsa valamely nyomorultnak igazságát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 6, 'Adjátok a részegítő italt az elveszendőnek, és a bort a keseredett szívűeknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 7, 'Igyék, hogy felejtkezzék az ő szegénységéről, és az ő nyavalyájáról ne emlékezzék meg többé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 8, 'Nyisd meg a te szádat a mellett, a ki néma, és azoknak dolgában, a kik adattak veszedelemre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 9, 'Nyisd meg a te szádat, ítélj igazságot; forgasd ügyét a szegénynek és a szűkölködőnek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 10, 'Derék asszonyt kicsoda találhat? Mert ennek ára sokkal felülhaladja az igazgyöngyöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 11, 'Bízik ahhoz az ő férjének lelke, és annak marhája el nem fogy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 12, 'Jóval illeti őt és nem gonosszal, az ő életének minden napjaiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 13, 'Keres gyapjat vagy lent, és megkészíti azokat kezeivel kedvvel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 14, 'Hasonló a kereskedő hajókhoz, nagy messziről behozza az ő eledelét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 15, 'Felkel még éjjel, eledelt ád az ő házának, és rendel ételt az ő szolgálóleányinak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 16, 'Gondolkodik mező felől, és megveszi azt; az ő kezeinek munkájából szőlőt plántál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 17, 'Az ő derekát felövezi erővel, és megerősíti karjait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 18, 'Látja, hogy hasznos az ő munkálkodása; éjjel sem alszik el az ő világa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 19, 'Kezeit veti a fonókerékre, és kezeivel fogja az orsót.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 20, 'Markát megnyitja a szegénynek, és kezeit nyújtja a szűkölködőnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 21, 'Nem félti az ő házanépét a hótól; mert egész házanépe karmazsinba öltözött.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 22, 'Szőnyegeket csinál magának; patyolat és bíbor az ő öltözete.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 23, 'Ismerik az ő férjét a kapukban, mikor ül a tartománynak véneivel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 24, 'Gyolcsot sző, és eladja; és övet, melyet ád a kereskedőnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 25, 'Erő és ékesség az ő ruhája; és nevet a következő napnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 26, 'Az ő száját bölcsen nyitja meg, és kedves tanítás van nyelvén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 27, 'Vigyáz a házanépe dolgára, és restségnek étkét nem eszi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 28, 'Felkelnek az ő fiai, és boldognak mondják őt; az ő férje, és dicséri őt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 29, 'Sok leány munkálkodott serénységgel; de te meghaladod mindazokat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 30, 'Csalárd a kedvesség, és hiábavaló a szépség; a mely asszony féli az Urat, az szerez dicséretet magának!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 31, 'Adjatok ennek az ő keze munkájának gyümölcséből, és dicsérjék őt a kapukban az ő cselekedetei!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, 'A prédikátornak, Dávid fiának, Jeruzsálem királyának beszédei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, 'Felette nagy hiábavalóság, azt mondja a prédikátor; felette nagy hiábavalóság! Minden hiábavalóság!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, 'Micsoda haszna van az embernek minden ő munkájában, melylyel munkálkodik a nap alatt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, 'Egyik nemzetség elmegy, és a másik eljő; a föld pedig mindörökké megmarad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, 'És a nap feltámad, és elnyugszik a nap; és az ő helyére siet, a hol ő ismét feltámad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, 'Siet délre, és átmegy észak felé; körbe-körbe siet a szél, és a maga keringéséhez visszatér a szél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 7, 'Minden folyóvíz siet a tengerbe; mindazáltal a tenger mégis meg nem telik: akármicsoda helyre a folyóvizek siessenek, ugyanazon helyre térnek vissza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 8, 'Minden dolgok mint fáradoznak, senki ki nem mondhatja; nem elégednék meg a szem látván, sem be nem teljesednék hallásával a fül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 9, 'A mi volt, ugyanaz, a mi ezután is lesz, és a mi történt, ugyanaz, a mi ezután is történik; és semmi nincs új dolog a nap alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 10, 'Van valami, a miről mondják: nézd ezt, új ez; régen volt már száz esztendőkön át, melyek mi előttünk voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 11, 'Nincs emlékezet az előbbiekről; azonképen az utolsó dolgokról is, melyek jövendők, nem lesz emlékezet azoknál, a kik azután lesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 12, 'Én prédikátor, királya voltam Izráelnek Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 13, 'És adám az én elmémet mindazok vizsgálására és bölcsen való tudakozására, melyek lesznek az ég alatt. Ez gonosz hiábavaló foglalatosság, melyet adott Isten az emberek fiainak, hogy gyötrődjenek vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 14, 'Láttam minden dolgokat, melyek lesznek a nap alatt, és ímé minden csak hiábavalóság, és a léleknek gyötrelme!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 15, 'Az egyenetlen meg nem egyenesíthető, és a fogyatkozás meg nem számlálható.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 16, 'Szóltam az én elmémmel, mondván: ímé, én nagygyá lettem, és gyűjtöttem bölcseséget mindazok felett, a kik fők voltak én előttem Jeruzsálemben, és az én elmém bőven látott bölcseséget és tudományt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 17, 'Adtam annakfelette az én elmémet a bölcseségnek tudására, és az esztelenségnek és bolondságnak megtudására. Megtudtam, hogy ez is a lélek gyötrelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 18, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, 'Mert a bölcsességnek sokaságában sok búsulás van, és valaki öregbíti a tudományt, öregbíti a gyötrelmet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, 'Mondék az én szívemben: no, megpróbállak téged a vígan való lakásban, hogy lásd meg, mi a jó! És ímé, az is hiábavalóság!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, 'A nevetésről azt mondom: bolondság! a vígasságról pedig: mit használ az?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, 'Elvégezém az én szívemben, hogy boritalra adom magamat, (pedig szívem a bölcseséget követé) és előveszem ezt a bolondságot, mígnem meglátom, hogy az emberek fiainak mi volna jó, a mit cselekedjenek az ég alatt, az életök napjainak száma szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, 'Felette nagy dolgokat cselekedtem; építék magamnak házakat; ülteték magamnak szőlőket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, 'Csinálék magamnak kerteket és ékességre való kerteket, és ülteték beléjök mindenféle gyümölcstermő fákat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, 'Csinálék magamnak víztartó tavakat, hogy azokból öntözzem a fáknak sarjadó erdejét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, 'Szerzék szolgákat és szolgálókat, házamnál nevekedett szolgáim is voltak nékem; öreg és apró barmoknak nyájaival is többel bírtam mindazoknál, a kik voltak én előttem Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, 'Gyűjték magamnak ezüstöt és aranyat is, és királyok drágaságait és tartományokat; szerzék magamnak éneklő férfiakat és éneklő asszonyokat, és az emberek fiainak gyönyörűségit, asszonyt és asszonyokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, 'És nagygyá levék és megnevekedém mindazok felett, a kik előttem voltak Jeruzsálemben; az én bölcseségem is helyén volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, 'Valamit kivánnak vala az én szemeim: meg nem fogtam azoktól, meg sem tartóztattam az én szívemet semmi vígasságtól, hanem az én szívem örvendezett minden én munkámmal gyűjtött jókban; mivelhogy ez volt az én részem minden én munkáimból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, 'És tekinték minden dolgaimra, melyeket cselekedtek vala az én kezeim, és az én munkámra, mit fáradsággal végeztem vala; és ímé, az mind hiábavalóság és a léleknek gyötrelme, és nincsen annak semmi haszna a nap alatt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, 'Azért fordulék én, hogy lássak bölcseséget és bolondságot és esztelenséget, az az hogy mit cselekesznek az emberek, a kik a király után következnek: azt, a mit régen cselekedtek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 14, 'És látám, hogy hasznosb a bölcseség a bolondságnál, miképen hasznosb a világosság a setétségnél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 15, 'A bölcsnek szemei vannak a fejében; a bolond pedig setétben jár; de ugyan én megismerém, hogy ugyanazon egy végök lesz mindezeknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 16, 'Annakokáért mondám az én elmémben: bolondnak állapotja szerint lesz az én állapotom is, miért valék tehát én is bölcsebb? és mondék az én elmémben: ez is hiábavalóság!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 17, 'Mert nem lesz emlékezete sem a bölcsnek, sem a bolondnak mindörökké; mivelhogy a következendő időkben már mind elfelejtetnek: és miképen meghal a bölcs, azonképen meghal a bolond is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 18, 'Azért gyűlöltem az életet; mert gonosznak látszék nékem a dolog, a mi történik a nap alatt; mert mindez hiábavalóság, és a léleknek gyötrelme!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 19, 'Gyűlöltem én minden munkámat is, melyet munkálkodom a nap alatt; mivelhogy el kell hagynom azt oly embernek, a ki én utánam lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 20, 'És ki tudja, ha bölcs lesz-é vagy bolond? és mégis uralkodik minden munkámon, a mit cselekedtem és bölcsen szerzettem a nap alatt! Ez is hiábavalóság!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 21, 'Annakokáért elfordulék én, megfogván reménységtől az én szívemet minden munkám felől, melylyel munkálódtam a nap alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 22, 'Mert van oly ember, a kinek munkája elvégeztetett bölcseséggel, tudománynyal és jó kimenetellel; és oly embernek adja azt örökségül, a ki abban semmit sem munkálkodott. Ez is hiábavalóság és nagy gonosz!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 23, 'Mert micsoda marad meg az embernek minden ő munkájából és elméjének nyughatatlan fáradozásából, melylyel ő munkálódott a nap alatt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 24, 'Holott minden napja bánat, és búsulás az ő foglalatossága, még éjjel is nem nyugodott az ő elméje. Ez is hiábavalóság!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 25, 'Nincsen csak e jó is az embernek hatalmában, hogy egyék, igyék, és azt cselekedje, hogy az ő szíve lakozzék gyönyörűséggel az ő munkájából; ezt is láttam én, hogy az Istennek kezében van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 26, 'Mert kicsoda ehetnék és élhetne gyönyörűségére rajtam kivül? Mert az embernek, a ki jó az ő szemei előtt, adott Isten bölcseséget és tudományt és örömöt; a bűnösnek pedig adott foglalatosságot az egybegyűjtésre és az egybehordásra, hogy adja annak, a ki jó az Isten előtt. Ez is hiábavalóság és az elmének gyötrelme!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, 'Mindennek rendelt ideje van, és ideje van az ég alatt minden akaratnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, 'Ideje van a születésnek és ideje a meghalásnak; ideje az ültetésnek, ideje annak kiszaggatásának, a mi ültettetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, 'Ideje van a megölésnek és ideje a meggyógyításnak; ideje a rontásnak és ideje az építésnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, 'Ideje van a sírásnak és ideje a nevetésnek; ideje a jajgatásnak és ideje a szökdelésnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, 'Ideje van a kövek elhányásának és ideje a kövek egybegyűjtésének; ideje az ölelgetésnek és ideje az ölelgetéstől való eltávozásnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, 'Ideje van a keresésnek és ideje a vesztésnek; ideje a megőrzésnek és ideje az eldobásnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, 'Ideje van a szakgatásnak és ideje a megvarrásnak; ideje a hallgatásnak és ideje a szólásnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, 'Ideje van a szeretésnek és ideje a gyűlölésnek; ideje a hadakozásnak és ideje a békességnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, 'Micsoda haszna van a munkásnak abban, a miben ő munkálkodik?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 10, 'Láttam a foglalatosságot, melyet adott Isten az emberek fiainak, hogy fáradozzanak benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 11, 'Mindent szépen csinált az ő idejében, e világot is adta az emberek elméjébe, csakhogy úgy, hogy az ember meg nem foghatja mindazt a dolgot, a mit az Isten cselekszik kezdettől fogva mindvégig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 12, 'Megismertem, hogy nem tehetnek jobbat, mint hogy örvendezzen kiki, és hogy a maga javát cselekedje az ő életében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 13, 'De még az is, hogy az ember eszik és iszik, és jól él az ő egész munkájából, az Istennek ajándéka.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 14, 'Tudom, hogy valamit Isten cselekszik, az lesz örökké, ahhoz nincs mit adni és abból nincs mit elvenni; és az Isten ezt a végre míveli, hogy az ő orczáját rettegjék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 15, 'A mi most történik, régen megvan, és a mi következik, immár megvolt, és az Isten visszahozza, a mi elmult.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 16, 'Láttam annakfelette a nap alatt, hogy az ítéletnek helyén hamisság, és az igazságnak helyén latorság van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 17, 'És mondék magamban: az igazat és a hamisat megítéli az Isten; mert minden ember akaratjának ideje van, és minden dolognak ő nála.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 18, 'Így szólék azért magamban: az emberek fiai miatt van ez így, hogy kiválogassa őket az Isten, és hogy meglássák, hogy ők magokban véve az oktalan állatokhoz hasonlók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 19, 'Az emberek fiainak vége hasonló az oktalan állatnak végéhez, és egyenlő végök van azoknak; a mint meghal egyik, úgy meghal a másik is, és ugyanazon egy lélek van mindenikben; és az embernek nagyobb méltósága nincs az oktalan állatoknál, mert minden hiábavalóság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 20, 'Mindenik ugyanazon egy helyre megy; mindenik a porból való, és mindenik porrá lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 21, 'Vajjon kicsoda vette eszébe az ember lelkét, hogy felmegy-é; és az oktalan állat lelkét, hogy a föld alá megy-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 22, 'Azért úgy láttam, hogy semmi sincs jobb, mint hogy az ember örvendezzen az ő dolgaiban, mivelhogy ez az ő része e világban: mert ki hozhatja őt vissza, hogy lássa, mi lesz ő utána?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, 'Viszont látám én mind a nyomorgatásokat, a melyek a nap alatt történnek, és ímé, nyilván van azoknak, a kik nyomorgattatnak, könnyhullatások, és vígasztalójok nincs nékik; és az őket nyomorgatóknak kezekből erőszaktételt szenvednek, és vígasztalójuk nincs nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, 'És dicsérém én a megholtakat, a kik már meghaltak vala, az élők felett, a kik még élnek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, 'De mind a kettőnél boldogabbnak azt, a ki még nem lett, a ki nem látta azt a gonosz dolgot, a mely a nap alatt történik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, 'És látám én, hogy minden dolgát és minden ügyes cselekedetét az ember az ő felebarátja iránt való irígységből rendeli; annakokáért ez is hiábavalóság és lélek-fájdalom!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, 'A bolond egybekapcsolja a kezeit, és megemészti a maga testét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, 'Jobb egy teljes marok nyugalommal, mint mind a két maroknak teljessége nagy munkával és lelki gyötrelemmel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, 'Viszont láték a nap alatt más hiábavalóságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, 'Van oly ember, a ki egymaga van és nincs vele másik, sem fia, sem atyjafia nincs; mindazáltal nincs vége minden ő fáradságának, és az ő szeme is meg nem elégszik gazdagsággal, hogy azt mondaná: vajjon kinek munkálkodom, hogy az én lelkemet minden jótól megfosztom? Ez is hiábavalóság és gonosz foglalatosság!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, 'Sokkal jobban van dolga a kettőnek, hogynem az egynek; mert azoknak jó jutalmok vala az ő munkájokból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, 'Mert ha elesnek is, az egyik felemeli a társát. Jaj pedig az egyedülvalónak, ha elesik, és nincsen, a ki őt felemelje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 11, 'Hogyha együtt feküsznek is ketten, megmelegszenek; az egyedülvaló pedig mimódon melegedhetik meg?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 12, 'Ha az egyiket megtámadja is valaki, ketten ellene állhatnak annak; és a hármas kötél nem hamar szakad el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 13, 'Jobb a szűkölködő, de bölcs gyermek a vén és bolond királynál, a ki nem szenvedi el az intést többé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 14, 'Mert az a fogságból is uralkodásra megy, holott ennek országában szegénységben született.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 15, 'Láttam a nap alatt járó minden élőket a második gyermek mellett; a ki amannak helyére lépendő vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 16, 'És hogy az egész sokaságnak nincs vége, mindazoknak, a kiknek ő élén volt; mindazáltal az utánok valók már semmit nem örvendeztek ő benne. Mert ez is hiábavalóság és lelki gyötrelem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, 'Őrizd meg lábaidat, mikor az Istennek házához mégy, mert hallgatás végett közeledned jobb, hogynem a bolondok módja szerint áldozatot adni; mert ezek nem tudják, hogy gonoszt cselekesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, 'Ne gyorsalkodjál a te száddal, és a te elméd ne siessen valamit szólni Isten előtt; mert az Isten mennyben van, te pedig e földön, azért a te beszéded kevés legyen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, 'Mert álom szokott következni a sok foglalatosságból; és a sok beszédből bolond beszéd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, 'Mikor Istennek fogadást téssz, ne halogasd annak megadását; mert nem gyönyörködik a bolondokban. A mit fogadsz, megteljesítsd!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, 'Jobb hogy ne fogadj, hogynem mint fogadj és ne teljesítsd be.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, 'Ne engedd a te szádnak, hogy bűnre kötelezze testedet, és ne mondd az angyal előtt, hogy tévedésből esett ez; hogy az Isten a te beszéded miatt fel ne háborodjék, és el ne veszesse a te kezeidnek munkáját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, 'Mert a sok álomban a hiábavalóság is és a beszéd is sok; hanem az Istent féljed.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, 'Ha a szegényeknek nyomoríttatását, és a törvénynek és igazságnak elfordíttatását látod a tartományban: ne csudálkozzál e dolgon; mert egyik felsőrendű vigyáz a másik felsőrendűre, és ezek felett még felsőbbrendűek vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, 'Az ország haszna pedig mindenekfelett a földmívelést kedvelő király.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, 'A ki szereti a pénzt, nem telik be pénzzel, és a ki szereti a sokaságot nem telik be jövedelemmel. Ez is hiábavalóság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, 'Mikor megszaporodik a jószág, megszaporodnak annak megemésztői is; mi haszna van azért benne urának, hanem hogy csak reá néz szemeivel?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, 'Édes az álom a munkásnak, akár sokat, akár keveset egyék; a gazdagnak pedig bővölködése nem hagyja őt aludni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, 'Van gonosz nyavalya, a melyet láttam a nap alatt: az ő urának veszedelmére tartott gazdagság;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 14, 'Ugyanis az a gazdagság elvész valami szerencsétlen eset miatt, és ha fia született néki, annak kezében nem lesz semmi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 15, 'A mint kijött az ő anyjának méhéből, mezítelen megy ismét el, a mint jött vala: és semmit nem vesz el munkájáért, a mit kezében elvinne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 16, 'Annakokáért ez is gonosz nyavalya, hogy a mint jött, a képen megy el. Mi haszna van néki abban, hogy a szélnek munkálkodott?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 17, 'És hogy az ő teljes életében a setétben evett, sokszori haraggal, keserűséggel és búsulással?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 18, 'Ez azért a jó, a melyet én láttam, hogy szép dolog enni és inni, és jól élni minden ő munkájából, a melylyel fárasztotta magát a nap alatt, az ő élete napjainak száma szerint, a melyeket adott néki az Isten; mert ez az ő része.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 19, 'És a mely embernek adott Isten gazdagságot és kincseket, és a kinek megengedte, hogy egyék abból és az ő részét elvegye, és örvendezzen az ő munkájának: ez az Istennek ajándéka!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 20, 'Mert nem sokat emlékezik meg az ilyen az ő élete napjainak számáról, mivelhogy az ő szívének örömét az Isten kedveli.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, 'Van egy gonosz, a melyet láttam a nap alatt, és nagy baj az az emberen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, 'Mikor valakinek az Isten ád gazdagságot és kincseket és tisztességet, és semmi nélkül nem szűkölködik, valamit kivánhat lelkének, és az Isten nem engedi néki, hogy éljen azzal, hanem más ember él azzal: ez hiábavalóság és gonosz nyavalya!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, 'Ha száz gyermeket szül is valaki, és sok esztendeig él, úgy hogy az ő esztendeinek napja sok, de az ő lelke a jóval meg nem elégszik, és nem lesz temetése néki: azt mondom, hogy jobb annál az idétlen gyermek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, 'Mert hiábavalóságra jött, setétségben megy el, és setétséggel fedeztetik be neve,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, 'A napot sem látta és nem ismerte; tűrhetőbb ennek állapotja, hogynem amannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, 'Hogyha kétezer esztendőt élt volna is, és a jóval nem élt: avagy nem ugyanazon egy helyre megy-é minden?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, 'Az embernek minden munkája szájáért van; mindazáltal az ő kívánsága be nem telik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, 'Mert miben különbözik a bölcs a bolondtól, és miben a szegény, a ki az élők előtt járni tud?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, 'Jobb, a mit ember szemmel lát, hogynem a lélek kivánsága; ez is hiábavalóság és a léleknek gyötrelme!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, 'Valami van, régen ráadatott nevezete, és bizonyos dolog, hogy mi lesz az ember, és nem perlekedhetik azzal, a ki hatalmasb nálánál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, 'Mert van sok beszéd, a mely a hiábavalóságot szaporítja; és mi haszna van az embernek abban?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 12, 'Mert kicsoda tudhatja, mi legyen az embernek jó e világon, az ő hiábavaló élete napjainak száma szerint, a melyeket mintegy árnyékot tölt el? Kicsoda az, a ki megmondhatná az embernek, mi következik ő utána a nap alatt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, 'Jobb a jó hír a drága kenetnél; és a halálnak napja jobb az ő születésének napjánál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, 'Jobb a siralmas házhoz menni, hogynem a lakodalomnak házához menni; mivelhogy minden embernek ez a vége, és az élő ember megemlékezik arról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, 'Jobb a szomorúság a nevetésnél; mert az orczának szomorúsága által jobbá lesz a szív.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, 'A bölcseknek elméje a siralmas házban van, a bolondoknak pedig elméje a vígasságnak házában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, 'Jobb a bölcsnek dorgálását hallani, hogynem valaki hallja a bolondoknak éneklését.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, 'Mert olyan a bolondnak nevetése, mint a tövisnek ropogása a fazék alatt; ez is hiábavalóság!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, 'Mert a zsarolás megbolondítja a bölcs embert is, és az elmét elveszti az ajándék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, 'Jobb akármi dolognak vége annak kezdetinél; jobb a tűrő, hogynem a kevély.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, 'Ne légy hirtelen a lelkedben a haragra; mert a harag a bolondok kebelében nyugszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, 'Ne mondd ezt: mi az oka, hogy a régi napok jobbak voltak ezeknél? mert nem bölcseségből származik az ilyen kérdés.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, 'Jó a bölcseség az örökséggel, és előmenetelökre van az embereknek, a kik a napot látják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, 'Mert a bölcseségnek árnyéka alatt, és a gazdagságnak árnyéka alatt egyformán nyugszik az ember! de a tudomány hasznosb, mivelhogy a bölcseség életet ád az ő urainak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, 'Tekintsd meg az Istennek cselekedetit; mert kicsoda teheti egyenessé, a mit ő görbévé tett?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, 'A jó szerencsének idején élj a jóval; a gonosz szerencsének idején pedig jusson eszedbe, hogy ezt is, épen úgy, mint azt, Isten szerzette, a végre, hogy az ember semmit abból eszébe ne vegyen, a mi reá következik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, 'Mindent láttam az én hiábavalóságomnak napjain: van oly igaz, a ki az ő igazságában elvész; és van gonosz ember, a ki az ő életének napjait meghosszabbítja az ő gonoszságában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, 'Ne légy felettébb igaz, és felettébb ne bölcselkedjél; miért keresnél magadnak veszedelmet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, 'Ne légy felettébb gonosz, és ne légy balgatag; miért halnál meg időd előtt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, 'Jobb, hogy ezt megfogd, és amattól is a te kezedet meg ne vond; mert a ki az Istent féli, mind ezektől megszabadul!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 19, 'A bölcseség megerősíti a bölcset inkább, mint tíz hatalmas, a kik a városban vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 20, 'Mert nincs egy igaz ember is a földön, a ki jót cselekednék és nem vétkeznék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 21, 'Ne figyelmezz minden beszédre, melyet mondanak, hogy meg ne halld szolgádat, hogy átkoz téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 22, 'Mert sok esetben tudja a te lelked is, hogy te is gonoszt mondottál egyebeknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 23, 'Mind ezeket megpróbáltam az én bölcseségem által. Mikor azt gondolám, hogy bölcs vagyok, én tőlem a bölcseség távol vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 24, 'Felette igen messze van, a mi van, és felette mélységes; kicsoda tudhatja meg azt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 25, 'Fordítám én magamat és az én szívemet a bölcseségnek és az okoskodásnak tudására, kutatására és keresésére; azonképen hogy megtudjam a bolondságnak gonoszságát, és a tévelygésnek balgatagságát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 26, 'És találtam egy dolgot, mely keservesb a halálnál; tudniillik az olyan asszonyt, a kinek a szíve olyan, mint a tőr és a háló, kezei pedig olyanok, mint a kötelek. A ki Isten előtt kedves, megszabadul attól; a bűnös pedig megfogattatik attól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 27, 'Lásd, ezt találtam, azt mondja a prédikátor; mikor gyakorta nagy szorgalmassággal keresém a megfejtést,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 28, 'A mit az én lelkem folyton keresett, és nem találtam. Ezer közül egy embert találtam; de asszonyt mind ezekben nem találtam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 29, 'Hanem lásd, ezt találtam, hogy az Isten teremtette az embert igaznak; ők pedig kerestek sok kigondolást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, 'Kicsoda hasonló a bölcshöz, és ki tudja a dolgok magyarázatát? Az embernek bölcsesége megvilágosítja az ő orczáját; és az ő ábrázatjának erőssége megváltozik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, 'Én mondom, hogy a királynak parancsolatját meg kell őrizni, és pedig az Istenre való esküvés miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, 'Ne siess elmenni az ő orczája elől, ne állj rá a gonosz dologra; mert valamit akar, megcselekszi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, 'Mivelhogy a király szava hatalmas; és kicsoda merné néki ezt mondani: mit mívelsz?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, 'A ki megtartja a parancsolatot, nem ismer nyomorúságot, és a bölcsnek elméje megért mind időt, mind ítéletet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, 'Mert minden akaratnak van ideje és ítélete; mert az embernek nyomorúsága sok ő rajta;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, 'Mert nem tudja azt, a mi következik; mert ki mondja meg néki, mimódon lesz az?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, 'Egy ember sem uralkodhatik a szélen, hogy feltartsa a szelet; és semmi hatalmasság nincs a halálnak napja felett, és az ütközetben senkit el nem bocsátanak; és a gonoszság nem szabadítja meg azt, a ki azzal él.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, 'Mindezt láttam, és megfigyeltem minden dolgot, a mely történik a nap alatt, oly időben, a melyben uralkodik az ember az emberen maga kárára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, 'És azután láttam, hogy a gonoszok eltemettettek és nyugalomra mentek; viszont a szent helyről kimentek, és elfelejttettek a városban olyanok, a kik becsületesen cselekedtek. Ez is hiábavalóság!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 11, 'Mivelhogy hamar a szentenczia nem végeztetik el a gonoszságnak cselekedőjén, egészen arra van az emberek fiainak szíve ő bennök, hogy gonoszt cselekedjenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 12, 'Bár meghosszabbítja életét a bűnös, a ki százszor is vétkezik; mégis tudom én, hogy az istenfélőknek lészen jól dolgok, a kik az ő orczáját félik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 13, 'A hitetlennek pedig nem lesz jó dolga, és nem hosszabbítja meg az ő életét, olyan lesz, mint az árnyék, mert nem rettegi az Istennek orczáját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 14, 'Van hiábavalóság, a mely e földön történik; az, hogy vannak oly igazak, a kiknek dolga a gonoszoknak cselekedetei szerint lesz; és vannak gonoszok, a kiknek dolga az igazaknak cselekedetei szerint lesz; mondám, hogy ez is hiábavalóság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 15, 'Annakokáért dicsérem vala én a vígasságot, hogy nincsen embernek jobb e világon, hanem hogy egyék, igyék és vígadjon; és ez kisérje őt munkájában az ő életének napjaiban, a melyeket ád néki Isten a nap alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 16, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 17, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, 'Mikor adám az én szívemet a bölcseségnek megtudására, és hogy megvizsgáljak minden fáradságot, a mely e földön történik, (mert sem éjjel, sem nappal az emberek szeme álmot nem lát):');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, 'Akkor eszembe vevém az Istennek minden dolgát, hogy az ember nem mehet végére a dolognak, a mely a nap alatt történik; mert fáradozik az ember, hogy annak végére menjen, de nem mehet végére: sőt ha azt mondja is a bölcs ember, hogy tudja, nem mehet végére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, 'Mert mindezt szívemre vettem, és pedig azért, hogy megvizsgáljam mindezt: hogy az igazak és bölcsek és azoknak minden cselekedetei Isten kezében vannak; szeretet is, gyűlölet is, nem tudják az emberek, mind ez előttük van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, 'Minden olyan, hogy mindenkit érhet, egyazon szerencséje van az igaznak és gonosznak, jónak vagy tisztának és tisztátalannak, mind annak, a ki áldozik, mind a ki nem áldozik, úgy a jónak, mint a bűnösnek, az esküvőnek úgy, mint a ki féli az esküvést.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, 'Mind az ég alatt való dolgokban e gonosz van, hogy mindeneknek egyenlő szerencséjök van; és az emberek fiainak szíve is teljes gonoszsággal, és elméjökben minden bolondság van, a míg élnek, azután pedig a halottak közé mennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, 'Mert akárkinek, valaki minden élők közé csatlakozik, van reménysége; mert jobb az élő eb, hogynem a megholt oroszlán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, 'Mert az élők tudják, hogy meghalnak; de a halottak semmit nem tudnak, és azoknak semmi jutalmok nincs többé; mivelhogy emlékezetök elfelejtetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, 'Mind szeretetök, mind gyűlöletök, mind gerjedezésök immár elveszett; és többé semmi részök nincs semmi dologban, a mely a nap alatt történik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, 'No azért egyed vígassággal a te kenyeredet, és igyad jó szívvel a te borodat; mert immár kedvesek Istennek a te cselekedetid!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, 'A te ruháid mindenkor legyenek fejérek, és az olaj a te fejedről el ne fogyatkozzék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, 'Éld életedet a te feleségeddel, a kit szeretsz, a te hiábavaló életednek minden napjaiban, a melyeket Isten adott néked a nap alatt, a te hiábavalóságodnak minden napjaiban; mert ez a te részed a te életedben és a te munkádban, melylyel munkálódol a nap alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, 'Valamit hatalmadban van cselekedni erőd szerint, azt cselekedjed; mert semmi cselekedet, okoskodás, tudomány és bölcseség nincs a Seolban, a hová menendő vagy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, 'Fordítván magamat látám a nap alatt, hogy nem a gyorsaké a futás, és nem az erőseké a viadal, és nem a bölcseké a kenyér, és nem az okosoké a gazdagság, és nem a tudósoké a kedvesség; hanem idő szerint és történetből lesznek mindezek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, 'Mert nem is tudja az ember az ő idejét; mint a halak, melyek megfogatnak a gonosz hálóban, és mint a madarak, melyek megfogatnak a tőrben, miképen ezek, azonképen megfogatnak az emberek fiai a gonosznak idején, mikor az eljő reájok hirtelenséggel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, 'Ezt is bölcseségnek láttam a nap alatt, és ez én előttem nagy volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, 'Tudniillik, hogy egy kicsiny város volt, és abban kevés ember volt, és eljött az ellen hatalmas király, és azt körülvette, és az ellen nagy erősségeket épített.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, 'És találtatott abban egy szegény ember, a ki bölcs volt, és az ő bölcseségével a várost megszabadította; de senki meg nem emlékezett arról a szegény emberről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, 'Akkor én azt mondám: jobb a bölcseség az erősségnél; de a szegénynek bölcsesége útálatos, és az ő beszédit nem hallgatják meg. A bölcseknek nyugodt beszédét inkább meghallgatják, mint a bolondok közt uralkodónak kiáltását. Jobb a bölcsesség a hadakozó szerszámoknál; és egy bűnös sok jót veszt el. A megholt legyek a patikáriusnak kenetit megbüdösítik, megerjesztik; azonképen hathatósabb a bölcseségnél, tisztességnél egy kicsiny balgatagság. A bölcs embernek szíve az ő jobbkezénél van; a bolondnak pedig szíve balkezénél. A bolond, mikor az úton jár is, az ő elméje hiányos, és mindennek hirdeti, hogy ő bolond.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, 'Mikor a fejedelemnek haragja felgerjed te ellened, a te helyedet el ne hagyjad; mert a szelídség nagy bűnöket lecsendesít.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, 'Van egy gonosz, a melyet láttam a nap alatt, mintha tévedés volna, a mely a fejedelemtől származik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, 'Hogy a bolondság nagy méltóságra helyeztetett, a gazdagok pedig alacsony sorsban ülnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, 'Láttam, hogy a szolgák lovakon ültek; a fejedelmek pedig gyalog mentek a földön, mint a szolgák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, 'A ki vermet ás, abba beesik; és a ki a gyepűt elhányja, megmarja azt a kígyó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, 'A ki a köveket helyökből kihányja, fájdalmat szenved azok miatt; a ki hasogatja a fát, veszedelemben forog a miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, 'Ha a vas megtompul, és annak élit meg nem köszörüli az ember, akkor erejét kell megfeszíteni; a bölcseség pedig minden dolognak eligazítására nagy előmenetel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, 'Ha megharap a kígyó, a míg meg nem varázsoltatott, azután semmi haszna nincsen a varázslónak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 9, 'A bölcs ember szájának beszédei kedvesek; a bolondnak pedig ajkai elnyelik őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 10, 'Az ő szája beszédinek kezdete bolondság, és az ő szája beszédinek vége gonosz balgatagság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 11, 'És a bolond szaporítja a szót, pedig nem tudja az ember, a mi következik, és a mi utána lesz, kicsoda mondja meg azt néki?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 12, 'A bolondnak munkája elfárasztja őt, mert a városba sem tud menni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 13, 'Jaj néked ország, kinek a te királyod gyermek; és a te fejedelmid reggel esznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 14, 'Boldog vagy te ország, kinek a te királyod nemes ember, és a te fejedelmid idejében esznek a testnek erejéért és nem az italért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 15, 'A restség miatt elhanyatlik a házfedél, és a kezek restsége miatt csepeg a ház.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 16, 'Vígasságnak okáért szereznek lakodalmat, és a bor vídámítja meg az élőket: és a pénz szerzi meg mindezeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 17, 'Még a te gondolatodban is a királyt ne átkozd, és a te ágyasházadban is gonoszt a gazdagnak ne mondj: mert az égi madár is elviszi a szót, és a szárnyas állat is bevádolná a te beszédedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 18, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 19, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 20, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, 'Vesd a te kenyeredet a víz színére, mert sok nap mulva megtalálod azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, 'Adj részt hétnek vagy nyolcznak is; mert nem tudod, micsoda veszedelem következik a földre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, 'Mikor a sűrű fellegek megtelnek, esőt adnak a földre; és ha leesik a fa délre vagy északra, a mely helyre leesik a fa, ott marad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, 'A ki a szelet nézi, nem vet az; és a ki sűrű fellegre néz, nem arat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, 'Miképen hogy nem tudod, melyik a szélnek útja, és miképen vannak a csontok a terhes asszony méhében; azonképen nem tudod az Istennek dolgát, a ki mindeneket cselekszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, 'Reggel vesd el a te magodat, és este se pihentesd kezedet; mert nem tudod, melyik jobb, ez-é vagy amaz, vagy ha mind a kettő jó lesz egyszersmind.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, 'Valóban, édes a világosság és jó a mi szemeinkkel néznünk a napot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, 'Mert ha sok esztendeig él is az ember, mindazokban örvendezzen; és megemlékezzék a setétségnek napjairól, mert az sok lesz. Valami eljövendő, mind hiábavalóság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, 'Örvendezz a te ifjuságodban, és vídámítson meg téged a te szíved a te ifjúságodnak idejében, és járj a te szívednek útaiban, és szemeidnek látásiban; de megtudd, hogy mindezekért az Isten tégedet ítéletre von!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, 'Vesd el a haragot a te szívedből, és vesd el a gonoszt a te testedből; mert az ifjúság és a hajnal hiábavalóság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, 'És emlékezzél meg a te Teremtődről a te ifjúságodnak idejében, míg a veszedelemnek napjai el nem jőnek, és míg el nem jőnek az esztendők, melyekről azt mondod: nem szeretem ezeket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, 'A míg a nap meg nem setétedik, a világossággal, a holddal és csillagokkal egybe; és a sűrű felhők ismét visszatérnek az eső után.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, 'Az időben, mikor megremegnek a háznak őrizői, és megrogynak az erős férfiak, és megállanak az őrlő leányok, mert megkevesbedtek, és meghomályosodnak az ablakon kinézők.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, 'És az ajtók kivül bezáratnak, a mikor is a malom zúgása halkabbá lesz; és felkelnek a madár szóra, és halkabbakká lesznek minden éneklő leányok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 7, 'Minden halmocskától is félnek, és mindenféle ijedelmek vannak az úton, és a mandolafa megvirágzik, és a sáska nehezen vonszolja magát, és kipattan a kapor; mert elmegy az ember az ő örökös házába, és az utczán körül járnak a sírók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 8, 'Minekelőtte elszakadna az ezüst kötél és megromolna az arany palaczkocska, és a veder eltörnék a forrásnál, és beletörnék a kerék a kútba,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 9, 'És a por földdé lenne, mint azelőtt volt; a lélek pedig megtérne Istenhez, a ki adta volt azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 10, 'Felette nagy hiábavalóságok, azt mondja a prédikátor, mindezek hiábavalóságok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 11, 'És azonfelül, hogy a prédikátor bölcs volt, még a népet is tudományra tanította, és fontolgatott, és tudakozott, és írt sok bölcs mondást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 12, 'És igyekezett a prédikátor megtudni sok kivánságos beszédeket, igaz írást és igaz beszédeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 13, 'A bölcseknek beszédei hasonlatosak az ösztökéhez, és mint a szegek, erősen le vannak verve a gyülekezetek tanítóinak szavai; melyek egy pásztortól adattak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 14, 'Mindezekből, fiam, intessél meg: a sok könyvek írásának nincs vége, és a sok tanulás fáradságára van a testnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 15, 'A dolognak summája, mindezeket hallván, ez: az Istent féljed, és az ő parancsolatit megtartsad; mert ez az embernek fődolga!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 16, 'Mert minden cselekedetet az Isten ítéletre előhoz, minden titkos dologgal, akár jó, akár gonosz legyen az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'Énekek éneke, mely Salamoné.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, 'Csókoljon meg engem az ő szájának csókjaival; mert a te szerelmeid jobbak a bornál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, 'A te drága kenetid jók illatozásra; a te neved kiöntött drága kenet; azért szeretnek téged a leányok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, 'Vonj engemet te utánad, hadd fussunk! Bevitt engem a király az ő ágyasházába; örvendezünk és vígadunk te benned, előszámláljuk a te szerelmeidet, melyek jobbak a bornál, méltán szeretnek téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, 'Fekete vagyok, de szép, Jeruzsálem leányai; mint Kédár sátrai és Salamon szőnyegei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'Ne nézzetek engem, hogy én fekete vagyok, hogy a nap lesütött engem; az én anyámnak fiai ellenem megharagudtak, a szőlőknek őrizőjévé tettek engem, – a magam szőlőjét nem őriztem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, 'Mondd meg nékem, te, a kit az én lelkem szeret, hol legeltetsz, hol deleltetsz délben; mert miért legyek én olyan, mint a ki elfátyolozza magát, társaid nyájainál?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, 'Mivelhogy nem tudod, oh asszonyok között legszebb! jőjj ki a nyájnak nyomdokain, és őrizd a te kecskéidet a pásztoroknak sátorai körül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, 'A Faraó szekereiben való paripákhoz hasonlítlak téged, én mátkám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'Szépek a te orczáid a halántékra valólánczokban, a te nyakad a gyöngysorokban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'Arany lánczokat csinálunk néked, ezüstből csinált gyöngyökkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, 'Mikor a király az ő asztalánál ül, nárdusnak jóillatja származik én tőlem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'Olyanaz én szerelmesem nékem, mint egy kötés mirha, mely az én kebeleim között hál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'Mint az Engedi szőlőiben a cziprusfürt, olyannékem az én szerelmesem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, 'Ímé, szép vagy én mátkám, ímé, szép vagy, a te szemeid olyanok, mint a galambok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, 'Ímé, te is szép vagy én szerelmesem, gyönyörűséges, és a mi nyoszolyánk zöldellő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'A mi házainknak gerendái czédrusfák, és a mi mennyezetünk cziprusfa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, 'Én Sáronnak rózsája vagyok, és a völgyek lilioma.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, 'Mint a liliom a tövisek közt, olyan az én mátkám a leányok közt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, 'Mint az almafa az erdőnek fái közt, olyan az én szerelmesem az ifjak közt. Az ő árnyékában felette igen kivánok ülni; és az ő gyümölcse gyönyörűséges az én ínyemnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'Bevisz engem a borozó házba, és zászló felettem a szerelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, 'Erősítsetek engem szőlővel, üdítsetek fel engem almákkal; mert betege vagyok a szerelemnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, 'Az ő bal keze az én fejem alatt van, és jobb kezével megölel engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, 'Kényszerítlek titeket, Jeruzsálemnek leányai, a vadkecskékre és a mezőnek szarvasira: fel ne költsétek és fel ne serkentsétek a szerelmet addig, a míg akarja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, 'Az én szerelmesemnek szavát hallom, ímé, ő jő, ugrálva a hegyeken, szökellve a halmokon!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'Hasonlatos az én szerelmesem az őzhöz, vagy a szarvasoknak fiához. Ímé, ott áll a mi falunkon túl, néz az ablakon keresztül, tekintget a rostélyokon keresztül,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'Szóla az én szerelmesem nékem, és monda: kelj fel én mátkám, én szépem, és jöszte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'Mert ímé a tél elmult, az eső elmult, elment.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'Virágok láttatnak a földön, az éneklésnek ideje eljött, és a gerliczének szava hallatik a mi földünkön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'A fügefa érleli első gyümölcsét, és a szőlők virágzásban vannak, jóillatot adnak; kelj fel én mátkám, én szépem, és jőjj hozzám!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, 'Én galambom, a kősziklának hasadékiban, a magas kőszálnak rejtekében, mutasd meg nékem a te orczádat, hadd halljam a te szódat; mert a te szód gyönyörűséges, és a te tekinteted ékes!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, 'Fogjátok meg nékünk a rókákat, a rókafiakat, a kik a szőlőket elpusztítják; mert a mi szőlőink virágban vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, 'Az én szerelmesem enyém, és én az övé, a ki a liliomok közt legeltet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, 'Míglen meghűsül a nap és az árnyékok elmúlnak: térj meg és légy hasonló, én szerelmesem, az őzhöz, vagy a szarvasoknak fiához a Béther hegyein.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, 'Az én ágyasházamban éjjeleken keresém azt, a kit szeret az én lelkem, keresém őt, és meg nem találtam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, 'Immár felkelek és eljárom a várost, a tereket és az utczákat, keresem azt, a kit szeret az én lelkem; keresém őt, és nem találám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, 'Megtalálának engem az őrizők, a kik a várost kerülik. Mondék nékik: Láttátok-é azt, a kit az én lelkem szeret?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'Alig mentem vala el azoktól, mikor megtaláltam azt, a kit az én lelkem szeret. Megragadám őt, el sem bocsátám, mígnem bevivém őt anyám házába, és az én szülőmnek ágyasházába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'Kényszerítelek titeket, Jeruzsálemnek leányai, a vadkecskékre, és a mezőnek szarvasira, fel ne költsétek és fel ne serkentsétek a szerelmet, valamíg ő akarja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, 'Kicsoda az, a ki feljő a pusztából, mint a füstnek oszlopa? Mirhától és tömjéntől illatos, a patikáriusnak minden jó illatú porától.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, 'Ímé, ez a Salamon gyaloghintaja, hatvan erős férfi van körülötte, Izráelnek erősei közül!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'Mindnyájan fegyverfogók, hadakozásban bölcsek, kinek-kinek oldalán fegyvere, az éjszakának félelme ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'Hálóágyat csinált magának Salamon király a Libánus fáiból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'Oszlopait ezüstből csinálta, oldalát aranyból, ágyát biborból, belső része ki van rakva szeretettel, a Jeruzsálemnek leányi által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'Jőjjetek ki, és nézzétek, Sionnak leányai, Salamon királyt a koronában, melylyel megkoronázta őt az anyja, az ő eljegyzésének napjára, és az ő szíve vígasságának napjára!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, 'Ímé szép vagy, én mátkám, ímé szép vagy, a te szemeid galambok a te fátyolod mögött; a te hajad hasonló a kecskéknek nyájához, melyek a Gileád hegyéről szállanak alá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, 'A te fogaid hasonlók a megnyirt juhoknyájához, melyek a fördőből feljőnek, melyek mind kettősöket ellenek, és nincsen azok között meddő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'Mint a karmazsin czérna, a te ajkaid, és a te beszéded kedves, mint a pomagránátnak darabja, olyan a te vakszemed a te fátyolod alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, 'Hasonló a te nyakad a Dávid tornyához, a mely építtetett fegyveres háznak, a melyben ezer paizs függesztetett fel, mind az erős vitézek paizsai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'A te két emlőd olyan, mint két vadkecske, egy zergének kettős fia, a melyek a liliomok közt legelnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, 'Míg meghűsül a nap, és elmulnak az árnyékok, elmegyek a mirhának hegyére, és a tömjénnek halmára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, 'Mindenestől szép vagy, én mátkám, és semmi szeplő nincs benned!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, 'Én velem a Libánusról, én jegyesem, én velem a Libánusról eljőjj; nézz az Amanának hegyéről, a Sénirnek és Hermonnak tetejéről, az oroszlánoknak barlangjokból, a párduczoknak hegyeiről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, 'Megsebesítetted az én szívemet, én húgom, jegyesem, megsebesítetted az én szívemet a te szemeidnek egy tekintésével, a te nyakadon való egy aranylánczczal!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'Mely igen szépek a te szerelmeid, én húgom, jegyesem! mely igen jók a te szerelmeid! jobbak a bornál, és a te keneteidnek illatja minden fűszerszámnál!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, 'Színmézet csepegnek a te ajkaid, én jegyesem, méz és tej van a te nyelved alatt, és a te ruháidnak illatja, mint a Libánusnak illatja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, 'Olyan, mint a berekesztett kert az én húgom, jegyesem! mint a befoglaltatott forrás, bepecsételt kútfő!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'A te csemetéid gránátalmás kert, édes gyümölcsökkel egybe, cziprusok nárdusokkal egybe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'Nárdus és sáfrány, jóillatú nád és fahéj, mindenféle temjéntermő fákkal, mirha és áloes, minden drága fűszerszámokkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'Kerteknek forrása, élő vizeknek kútfeje, melyek folynak a Libánusról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, 'Serkenj fel északi szél, és jőjj el déli szél, fújj az én kertemre, folyjanak annak drága illatú szerszámai, jőjjön el az én szerelmesem az ő kertébe, és egye annak drágalátos gyümölcsét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, 'Bementem az én kertembe, én húgom, jegyesem, szedem az én mirhámat, az én balzsamommal, eszem az én lépesmézemet az én mézemmel, iszom az én boromat az én tejemmel. Egyetek barátim, igyatok, és részegedjetek meg, szerelmesim!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, 'Én elaludtam, de lelkemben vigyázok vala, és ímé az én szerelmesemnek szava, a ki zörget, mondván: Nyisd meg nékem, én húgom, én mátkám, én galambom, én tökéletesem; mert az én fejem megrakodott harmattal, az én hajam az éjszakának harmatjával!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, 'Felelék én: Levetettem ruhámat, hogy-hogy öltözhetném fel? Megmostam lábaimat, mi módon keverném azokat a porba?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'Az én szerelmesem kezét benyujtá az ajtónakhasadékán, és az én belső részeim megindulának ő rajta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'Felkelék én, hogy az én szerelmesemnek megnyissam, és az én kezeimről mirha csepeg vala, és az én ujjaimról folyó mirha a závár kilincsére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, 'Megnyitám az én szerelmesemnek; de az én szerelmesem elfordult, elment; az én lelkem megindult az ő beszédén: keresém őt, de nem találám, kiáltám őt, de nem felele nékem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, 'Megtalálának engem az őrizők, a kik a várost kerülik, megverének engem, megsebesítének engem, elvevék az én felöltőmet tőlem a kőfalnak őrizői.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, 'Kényszerítelek titeket, Jeruzsálemnek leányai, ha megtaláljátok az én szerelmesemet, mit mondotok néki? hogy én a szerelem betege vagyok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, 'Micsoda a te szerelmesed egyéb szerelmesek felett, oh asszonyoknak szépe? Micsoda a te szerelmesed egyéb szerelmesek felett, hogy minket ilyen igen kényszerítesz?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, 'Az én szerelmesem fejér és piros, tízezer közül is kitetszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'Az ő feje, mint a választott drága megtisztított arany; fodor haja fekete, mint a hollónak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'Az ő szemei mint a vízfolyás mellett való galambok, melyek tejben fürödnek, szépteljesen helyheztettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'Az ő orczája hasonlatos a drága füveknek táblájához, a melyek illatos plántákat nevelnek; az ő ajkai liliomok, melyekről csepegő mirha foly.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'Az ő kezei aranyhengerek; melyek befoglaltattak topázba; az ő teste elefántcsontból való mű, zafirokkal megrakva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'Az ő szárai márványoszlopok; melyek tiszta arany talpakra fundáltattak; az ő tekinteti, mint a Libánus; tetszetes mint a czédrusfa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'Az ő ínye édességek, és ő mindenestől fogva kívánatos! Ez az én szerelmesem, és ez az én barátom, oh Jeruzsálemnek leányai! Hová ment a te szerelmesed, oh asszonyoknak szépe? hová fordult a te szerelmesed, hogy keressük őt veled együtt? Az én szerelmesem, elment az ő kertébe, a drága füveknek táblái közé, hogy lakozzék a kertekben, és liliomokat szedjen. Én az én szerelmesemé vagyok, és az én szerelmesem enyim, a ki a liliomok közt legeltet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, 'Szép vagy én mátkám, mint Tirsa városa, kedves, mint Jeruzsálem, rettenetes, mint a zászlós tábor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, 'Fordítsd el a te szemeidet én tőlem, mert azok megzavarnak engem. A te hajad olyan, mint a kecskéknek nyája, melyek a Gileádról szállanak alá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, 'A te fogaid hasonlók a juhok nyájához, melyek feljőnek a fördőből, melyek mind kettősöket ellenek, és meddő azok között nincsen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, 'Mint a pomagránát darabja a te vakszemed, a te fátyolod alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'Hatvanan vannak a királynék, és nyolczvanan az ágyasok és számtalan a leányzó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'És az én galambom, az én tökéletesem, az ő anyjának egyetlenegye, az ő szülőjének választottja. Látják a leányok, és boldognak mondják őt, a királynéasszonyok és az ágyasok, és dicsérik őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'Kicsoda az, a ki úgy láttatik mintegy hajnal, szép, mint a hold, tiszta, mint a nap, rettenetes, mint a zászlós tábor?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, 'A diófás kertekbe mentem vala alá, hogy a völgynek zöld fűveit lássam; hogy megnézzem, ha fakad-é a szőlő, és a pomagránátfák virágzanak-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'Nem tudtam, hogy az én elmém ültete engem az én nemes népemnek díszhintajába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, 'Térj meg, oh Sulamit! térj meg, térj meg, hogy nézzünk téged! Mit néztek Sulamiton? mintegy Machanaimbeli körtánczot!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 13, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, 'Oh mely szépek a te lépéseid a sarukban, oh fejedelem leánya! A te csípőd hajlásai olyanok, mint a kösöntyűk, mesteri kezeknek míve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, 'A te köldököd, mint a kerekded csésze, nem szűkölködik nedvesség nélkül; a te hasad mint a gabonaasztag, liliomokkal körül kerítve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'A te két emlőd, mintkét őzike, a vadkecskének kettős fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'A te nyakad, mint az elefánttetemből csinált torony; a te szemeid, mint a Hesbonbeli halastók, a sok népű kapunál; a te orrod hasonló a Libánus tornyához, mely néz Damaskus felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'A te fejed hasonló rajtad a Kármelhez, és a te fejeden hajadnak fonatékja a biborhoz, a király is megköttetnék fürteid által!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, 'Mely igen szép vagy és mely kedves, oh szerelem, a gyönyörűségek közt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, 'Ez a te termeted hasonló a pálmafához, és a te emlőid a szőlőgerézdekhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'Azt mondám: felhágok a pálmafára, megfogom annak ágait: és lesznek a te emlőid, mint a szőlőnek gerézdei, és a te orrodnak illatja, mint az almának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, 'És a te ínyed, mint a legjobb bor, melyet szerelmesem kedvére szürcsöl, mely szóra nyitja az alvók ajkait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, 'Én az én szerelmesemé vagyok, és engem kiván ő!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, 'No, én szerelmesem, menjünk ki a mezőre, háljunk a falukban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, 'Felkelvén menjünk a szőlőkbe, lássuk meg, ha fakad-é a szőlő, ha kinyílott-é virágja, ha virágzanak-é a gránátalmafák: ott közlöm az én szerelmimet veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, 'A mandragórák illatoznak, és a mi ajtónk előtt vannak minden drágalátos gyümölcsök, ók és újak, melyeket ohén szerelmesem, néked megtartottam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, 'Vajha lennél nékem én atyámfia, ki az én anyámnak emlőjét szopta, hogy téged kivül találván megcsókolnálak; még sem útálnának meg engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, 'Elvinnélek, bevinnélek anyámnak házába, te oktatgatnál engem, én meg borral itatnálak, fűszeressel, gránátalma borral.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, 'Az ő balkeze az én fejem alatt, és jobbkezével megölel engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, 'Kényszerítlek titeket, Jeruzsálemnek leányai, miért költenétek és miért serkentenétek fel a szerelmet, mígnem ő akarja?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, 'Kicsoda ez a ki feljő a pusztából, a ki az ő szerelmeséhez támaszkodik? Az almafa alatt költöttelek fel téged, ott szült téged a te anyád, ott szült téged a te szülőd!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, 'Tégy engem mintegy pecsétet a te szívedre, mintegy pecsétet a te karodra; mert erős a szeretet, mint a halál, kemény, mint a sír a buzgó szerelem; lángjai tűznek lángjai, az Úrnak lángjai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, 'Sok vizek el nem olthatnák e szeretetet: a folyóvizek sem boríthatnák azt el: ha az ember minden házabeli marháját adná is e szeretetért, mégismegvetnék azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, 'Kicsiny húgunk van nékünk, a kinek nincsen még emlője; mit cselekedjünk a mi húgunk felől, a napon, melyen arról szót tesznek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, 'Ha ő kőfal, építünk azon ezüstből palotát; ha pedig ajtó ő, elrekesztjük őt czédrus-deszkával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, 'Mikor én olyan leszek, minta kőfal, és az én emlőim, mint a tornyok; akkor olyan leszek ő előtte, mint a ki békességet nyer.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, 'Szőlője volt Salamonnak Baálhamonban, adta az ő szőlejét a pásztoroknak, kiki annak gyümölcséért hoz ezer-ezer ezüst siklust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, 'Az én szőlőmre, mely én reám néz, nékem gondom lesz: az ezer siklus, Salamon, tiéd legyen, a kétszáz annak gyümölcsének őrizőié.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, 'Oh te, a ki lakol a kertekben! A te társaid a te szódra figyelmeznek; hadd halljam én is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, 'Fuss én szerelmesem, és légy hasonló a vadkecskéhez, vagy a szarvasnak fiához, a drága füveknek hegyein!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'Ésaiásnak, Ámós fiának látása, melyet látott Júda és Jeruzsálem felől, Uzziásnak, Jóthámnak, Akháznak és Ezékiásnak, a Júda királyainak napjaiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'Halljátok egek, és vedd füleidbe föld! mert az Úr szól: Fiakat neveltem, s méltóságra emeltem, és ők elpártolának tőlem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'Az ökör ismeri gazdáját, és a szamár az ő urának jászlát; Izráel nem ismeri, az én népem nem figyel reá!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'Oh gonosz nemzetség, hamissággal megterheltetett nép, gonosz mag, nemtelen fiak! elhagyták az Urat, megútálták az Izráel Szentjét, és elfordultak tőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'Miért ostorozzalak tovább, holott a bűnt növelitek? Minden fej beteg, és minden szív erőtelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'Tetőtől talpig nincs e testben épség, csupa seb és dagadás és kelevény, a melyeket ki sem nyomtak, be sem kötöztek, olajjal sem lágyítottak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, 'Országtok pusztaság, városaitokat tűz perzselé föl, földeteket szemetek láttára idegenek emésztik, és pusztaság az, mint a hol idegenek dúltak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, 'És úgy maradt a Sion leánya, mint kunyhó a szőlőben, mint kaliba az ugorkaföldön, mint megostromlott város.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, 'Ha a seregeknek Ura valami keveset meg nem hagyott volna bennünk, úgy jártunk volna mint Sodoma, és Gomorához volnánk hasonlók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, 'Halljátok az Úrnak beszédét, Sodoma fejedelmei, és vedd füleidbe Istenünk tanítását, Gomora népe!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, 'Mire való nékem véres áldozataitoknak sokasága? ezt mondja az Úr; megelégeltem a kosok egészen égőáldozatait és a hízlalt barmok kövérét; s a tulkok, bárányok és bakok vérében nem gyönyörködöm;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, 'Ha eljöttök, hogy színem előtt megjelenjetek, ki kivánja azt tőletek, hogy pitvarimat tapossátok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, 'Ne hozzatok többé hazug ételáldozatot, a jó illattétel útálat előttem; újhold, szombat s ünnepre-felhívás: bűnt és ünneplést el nem szenvedhetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, 'Újholdaitokat és ünnepeiteket gyűlöli lelkem; terhemre vannak, elfáradtam viselni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, 'És ha kiterjesztitek kezeiteket, elrejtem szemeimet előletek; sőt ha megsokasítjátok is az imádságot, én meg nem hallgatom: vérrel rakvák kezeitek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, 'Mosódjatok, tisztuljatok meg, távoztassátok el szemeim elől cselekedeteitek gonoszságát, szünjetek meg gonoszt cselekedni;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, 'Tanuljatok jót tenni; törekedjetek igazságra, vezessétek jóra az erőszakoskodót, pártoljátok az árvák és özvegyek ügyét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, 'No jertek, törvénykezzünk, azt mondja az Úr! ha bűneitek skárlátpirosak, hófehérek lesznek, és ha vérszínűek, mint a karmazsin, olyanok lesznek, mint a gyapjú.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 19, 'Ha engedelemmel hallgatándotok, e föld javaival éltek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 20, 'És ha vonakodtok, sőt pártot üttök, fegyver emészt meg; mert az Úr szája szólt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, 'Mint lett paráznává a hív város! teljes vala jogossággal, igazság lakozott benne, és most gyilkosok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, 'Ezüstöd salakká lett, tiszta borod vízzel elegyítve:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, 'Fejedelmid megátalkodottak és lopóknak társai; mind szereti az ajándékot és vesztegetést hajhász, árvát nem pártolnak, és az özvegy ügye nem kerül eléjök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, 'Ezért azt mondja az Úr, a seregeknek Ura, Izráel erős Istene: Jaj! mert vígasztalást veszek háborgatóimon, és bosszút állok ellenségimen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, 'És kezemet ellened fordítom, és kiolvasztom mintegy lúggal salakodat, és eltávolítom minden ólmodat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, 'És adok néked oly birákat, mint régen, és oly tanácsosokat, mint kezdetben, s ekkor azt mondják te néked: ez igaz város, ez hív város.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, 'Sion jogosság által váltatik meg, és megtérői igazság által;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 28, 'De elvesznek a bűnösök és gonoszok egyetemben, s megemésztetnek, a kik az Urat elhagyták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 29, 'Mert szégyen éri őket a cserfákért, a melyekben gyönyörködétek, és pirulni fogtok a kertek miatt, a melyeket kedveltek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 30, 'És hasonlatosok lesztek az elhullott levelű terpentinfához, és a víz nélkül való kerthez:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 31, 'És csepüvé lesz az erős, és munkája szikrává: mindketten égni fognak, és oltójok nem lészen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, 'Ésaiásnak, Ámós fiának beszéde, a melyet látott Júda és Jeruzsálem felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'Lészen az utolsó időkben, hogy erősen fog állani az Úr házának hegye, hegyeknek felette, és magasabb lészen a halmoknál, és özönleni fognak hozzá minden pogányok;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'És eljönnek sok népek, mondván: Jertek menjünk fel az Úr hegyére, Jákób Istenének házához, hogy megtanítson minket az Ő útaira, és mi járjunk az Ő ösvényein, mert tanítás Sionból jő, és Jeruzsálemből az Úrnak beszéde;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'Ki ítéletet tesz a pogányok között, és bíráskodik sok nép felett; és csinálnak fegyvereikből kapákat, és dárdáikból metszőkéseket, és nép népre kardot nem emel, és hadakozást többé nem tanul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'Jákóbnak háza! jertek járjunk az Úrnak világosságában!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, 'Mert elhagytad, Uram, a Te népedet, Jákób házát; mivel telvék napkeleti erkölcsökkel, és szemfényvesztők, mint a Filiszteusok, és idegenek fiaival kötnek szövetséget;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'És betelt földje ezüsttel és aranynyal, és nincs szere-száma kincseinek; betelt földje lovakkal, és nincs szere-száma szekereinek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'És betelt földje bálványokkal, és kezeik csinálmányának hajolnak meg, mit ujjaik csináltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'Ezért porba hajtatik a közember, és megaláztatik a főember, és meg nem bocsátsz nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'Menj be a kősziklába, és rejtőzzél el a porba az Úr félelme elől, és az Ő nagyságának dicsősége előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'A kevély szemű közember megaláztatik, és a főemberek magassága porba hajtatik, és csak az Úr magasztaltatik fel ama napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'Mert a seregek Urának napja eljő minden kevély és magas ellen, és minden felemelkedett ellen, és az megaláztatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, 'És Libánon minden czédrusai ellen, a melyek magasak és felemelkedettek, s Básánnak minden tölgyfái ellen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, 'Minden magas hegyek ellen, és minden felemelkedett halmok ellen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, 'Minden magas torony ellen, és minden erős kőfal ellen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, 'És Társisnak minden hajói ellen, és minden gyönyörűséges drágaságok ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, 'És porba hajtatik a közember kevélysége, és megaláztatik a főemberek magassága, és egyedül az Úr magasztaltatik fel ama napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, 'És a bálványokat teljességgel elveszti.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, 'És bemennek a sziklák barlangjaiba és a föld hasadékaiba, az Úr félelme elől és nagyságának dicsősége előtt, mikor felkél, hogy megrettentse a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, 'Ama napon odadobja az ember ezüst bálványait és arany bálványait, miket magának csinált, hogy azok előtt meghajoljon, a vakondokoknak és denevéreknek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, 'Hogy elmenjen a sziklák lyukaiba és a hegyek hasadékiba, az Úr félelme elől és az Ő nagyságának dicsősége előtt, mikor felkél, hogy megrettentse a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'Oh szünjetek meg hát az emberben bízni, a kinek egy lehellet van orrában, mert hát ugyan mire becsülhető ő?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'Mert ímé az Úr, a seregeknek Ura elveszi Jeruzsálemből és Júdából a támaszt és a táplálót, a kenyérnek minden erejét és a víznek minden erejét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'Az erőst és hadakozót, birót és prófétát, jóst és öreget;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, 'Az ötvenedes hadnagyot, a tisztes embert, a tanácsost, az ügyes mestert és a varázsláshoz értőt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'És adok nékik gyerkőczöket fejedelmekül, és gyermekek uralkodnak rajtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'És nyomorba jut a nép; egyik a másik ellen, ki-ki az ő társa ellen támad, a gyermek az öreg ellen, becstelen a tisztes ellen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'És ha valaki megragadja atyja nemzetségéből való rokonát, mondván: Néked ruhád van, légy fejedelmünk és e romlás kezed alatt legyen:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'Ez ama napon így fog felkiáltani: Nem leszek sebkötöző, házamban is nincsen kenyér és nincs ruha; ne tegyetek engem e nép fejedelmévé!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'Mert megromlott Jeruzsálem, és Júda elesett, mert nyelvök és cselekedeteik az Úr ellen vannak, hogy az Ő dicsőséges szemeit ingereljék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, 'Arczuk tekintete tesz ellenök bizonyságot, bűneikkel Sodoma módjára kérkednek, nemhogy eltitkolnák; jaj lelköknek! mert magok szereztek magoknak gonoszt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, 'Mondjátok az igaznak, hogy jól lészen dolga, mert cselekedeteik gyümölcsével élnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, 'Jaj a gonosznak, gonoszul lesz dolga, mert kezeinek cselekedete szerint fizetnek néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, 'Népem nyomorgatói gyermekek, és asszonyok uralkodnak rajta; népem! a te vezéreid hitetők, és ösvényidnek útját elrejtik előled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, 'Előálla perelni az Úr, és itt áll ítélni népeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, 'Az Úr törvénybe megy népe véneivel és fejedelmivel: Hiszen ti lelegeltétek a szőlőt, szegénytől rablott marha van házaitokban:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, 'Mi dolog, hogy népemet összezúzzátok, és a szegények orczáját összetöritek? ezt mondja az Úr, a seregeknek Ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, 'És szól az Úr: Mivel Sion leányai felfuvalkodtak, és felemelt nyakkal járnak, szemeikkel pillognak, és aprókat lépve járnak, és lábokkal nagy zengést bongást szereznek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, 'Megkopaszítja az Úr Sion leányainak fejtetőjét, és az ő szemérmöket megmezteleníti.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, 'Ama napon eltávolítja az Úr az ő lábaik zengő ékességét, a napocskákat és holdacskákat,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, 'A fülönfüggőket, a karpereczeket és a fátyolokat,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, 'A pártákat, a láblánczokat, az öveket, a jóillattartókat és az ereklyéket,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, 'A gyűrűket és az orrpereczeket,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 23, 'Az ünneplő ruhákat, a palástokat, a nagy kendőket és az erszényeket,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 24, 'A tükröket, a gyolcsingeket, a főkötőket és a keczeléket:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 25, 'És lesz a balzsamillat helyén büdösség, az öv helyén kötél, és a felfodrozott haj helyén kopaszság, a szép köpenynek helyén zsákruha, és a szépség helyén homlokra sütött bélyeg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 26, 'Férfiaid fegyver által hullnak el, és vitézeid harczban: És sírnak és gyászolnak kapui, és ő elpusztíttatván, a földön ül; És megragad hét asszony egy férfit ama napon, mondván: A magunk kenyerét eszszük és a mi ruhánkba öltözködünk, csak hadd neveztessünk a te nevedről, és vedd le rólunk gyalázatunkat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'És ama napon az Úrnak csemetéje ékes és dicsőséges lészen, és a földnek gyümölcse nagyságos és díszes Izráel maradékának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'És lészen, hogy a ki Sionban meghagyatik, és Jeruzsálemben megmarad, szentnek mondatik, minden, valaki Jeruzsálemben az élők közé beiratott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'Ha elmosta az Úr Sion leányainak undokságát, és Jeruzsálem vérét eltisztítá belőle az ítélet lelkével, a megégetés lelkével:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'Akkor teremteni fog az Úr Sion hegyének minden helye fölé és gyülekezetei fölé nappal felhőt és ködöt, s lángoló tűznek fényességét éjjel; mert ez egész dicsőségen oltalma lészen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'És sátor lészen árnyékul nappal a hőség ellen, s oltalom és rejtek szélvész és eső elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'Hadd énekelek kedvesemről, szerelmesemnek énekét az Ő szőlőjéről! Kedvesemnek szőlője van nagyon kövér hegyen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'Felásta és megtisztítá kövektől, nemes vesszőt plántált belé, és közepére tornyot építtetett, sőt benne már sajtót is vágatott; és várta, hogy majd jó szőlőt terem, és az vadszőlőt termett!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'Mostan azért, Jeruzsálem lakosi és Juda férfiai: ítéljetek köztem és szőlőm között!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'Mit kellett volna még tennem szőlőmmel; mit meg nem tettem vele? Miért vártam, hogy jó szőlőt terem, holott vadat termett?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'Azért most tudatom veletek, hogy mit teszek szőlőmmel; elvonszom kerítését, hogy lelegeltessék, elrontom kőfalát, hogy eltapodtassék;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'És parlaggá teszem; nem metszetik és nem kapáltatik meg, tövis és gaz veri föl, és parancsolok a fellegeknek, hogy rá esőt ne adjanak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'A seregek Urának szőlője pedig Izráel háza, és Júda férfiai az Ő gyönyörűséges ültetése; és várt jogőrzésre, s ím lőn jogorzás; és irgalomra, s ím lőn siralom!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'Jaj azoknak, a kik a házhoz házat ragasztanak, és mezőt foglalnak a mezőkhöz, míg egy helyecske sem marad, és csak ti magatok laktok itt e földön!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, 'Hallásomra megesküdt a seregeknek Ura, hogy sok házak pusztasággá lesznek, a nagyok és szépek lakos nélkül,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'Mert tíz hold szőlő egy báth bort ereszt, és egy hómer mag egy efát terem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'Jaj azoknak, a kik jó reggelen részegítő ital után futkosnak, és mulatnak estig, és bor hevíti őket:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'És czitera, lant, dob, síp és bor van lakodalmokban, de az Úrnak dolgát nem tekintik meg, és nem látják kezeinek cselekedetét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'Ezért fogságba megy népem, mivelhogy tudomány nélkül való, és főemberei éhen halnak, és sokasága szomjú miatt eped meg;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, 'Azért a sír kiszélesíti torkát és feltátja száját szertelen, és leszállnak abba népem főemberei, és zajongó sokasága, és minden örvendezői;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, 'És porba hajtatik a közember, és megaláztatik a főember, és a nagyok szemei megaláztatnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, 'És felmagasztaltatik a seregeknek Ura az ítéletben, s a szent Isten megszenteli magát igazságban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, 'És bárányok legelnek ott, mint legelőjükön, s a gazdagoknak romjain idegenek élnek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, 'Jaj azoknak, a kik a vétket hazugságnak kötelein vonszák, és a bűnt mint szekeret köteleken;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, 'A kik ezt mondják: siessen és tegye hamar munkáját, hogy lássuk, s közelítsen és jőjjön el Izráel Szentjének tanácsa, hogy tudjuk meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 20, 'Jaj azoknak, a kik a gonoszt jónak mondják és a jót gonosznak; a kik a sötétséget világossággá s a világosságot sötétséggé teszik, és teszik a keserűt édessé, s az édest keserűvé!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 21, 'Jaj azoknak, a kik magoknak bölcseknek látszanak, és eszesek önnön magok előtt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 22, 'Jaj azoknak, a kik hősök borivásban és híresek részegítő ital vegyítésében;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 23, 'A kik a gonoszt ajándékért igaznak mondják, és az igazak igazságát elfordítják tőlük:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 24, 'Ezért, mint a polyvát megemészti a tűznek nyelve, és az égő széna összeomlik: gyökerök megrothad, virágjok mint a por elszáll, mert a seregek Urának törvényét megvetették, és Izráel szentjének beszédét megútálták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 25, 'Ezért gerjedt fel az Úrnak haragja népe ellen, és felemelé rá kezét, és megveri, hogy a hegyek megrendülnek, és holttestök szemétként fekszik az utczán. Mindezekkel haragja el nem mult, és keze még felemelve van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 26, 'És zászlót emel a távoli népeknek, és süvölt a föld határán lakozóknak, és ímé hamarsággal könnyen eljőnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 27, 'Nem lesz köztük egy is elfáradott, sem tántorgó; nem szunnyad, és nem aluszik; derekának öve sem oldódik meg, és nem szakad el saruja szíja sem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 28, 'Nyilai élesek, és minden ő kézívei felvonvák, lovai körme, miként a kova, és kerekei mint a forgószél;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 29, 'Ordítása, mint az oroszláné, és ordít, mint az oroszlán-kölykök, és morog s prédát ragad s elviszi, és nincs, a ki elvegye tőle;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 30, 'És rámordul ama napon, mint tenger mormolása; és ő a földre néz, de ímé ott sűrű sötétség; és a nap meghomályosodik a ráborult homályban!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, 'A mely esztendőben meghala Uzziás király, látám az Urat ülni magas és felemeltetett székben, és palástja betölté a templomot;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'Szeráfok állanak vala felette: mindeniknek hat-hat szárnya vala: kettővel orczáját fedé be, kettővel lábait fedé be, és kettővel lebegett;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'És kiált vala egy a másiknak, és mondá: Szent, szent, szent a seregeknek Ura, teljes mind a széles föld az ő dicsőségével!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'És megrendülének az ajtó küszöbei a kiáltónak szavától, és a ház betelt füsttel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'Akkor mondék: Jaj nékem, elvesztem, mivel tisztátalan ajkú vagyok és tisztátalan ajkú nép közt lakom: hisz a királyt, a seregeknek Urát láták szemeim!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'És hozzám repült egy a szeráfok közül, és kezében eleven szén vala, a melyet fogóval vett volt az oltárról;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'És illeté számat azzal, és mondá: Ímé ez illeté ajkaidat, és hamisságod eltávozott, és bűnöd elfedeztetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'És hallám az Úrnak szavát, a ki ezt mondja vala: Kit küldjek el és ki megyen el nékünk? Én pedig mondék: Ímhol vagyok én, küldj el engemet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'És monda: Menj, és mondd ezt e népnek: Hallván halljatok és ne értsetek, s látván lássatok és ne ismerjetek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'Kövérítsd meg e nép szívét, és füleit dugd be, és szemeit kend be: ne lásson szemeivel, ne halljon füleivel, ne értsen szívével, hogy meg ne térjen, és meg ne gyógyuljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'És én mondék: Meddig lészen ez Uram?! És monda: Míg a városok pusztán állanak lakos nélkül, és a házak emberek nélkül, s a föld is puszta lészen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 12, 'És az Úr az embert messze elveti, s nagy pusztaság lészen a földön;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 13, 'És ha megmarad még rajta egy tizedrész, ismétlen elpusztul ez is; de mint a terpentinfának és cserfának törzsük marad kivágatás után: az ő törzsük szent mag lészen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'És lőn a Júda királyának, Akháznak, az Uzziás fiának, Jóthám fiának napjaiban, eljöve Reczin, Sziriának királya, és Remaljának fia, Pékah, Izráelnek királya Jeruzsálem ellen, hogy azt megostromolja; de nem veheté meg azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'És hírül vivék a Dávid házának, mondván: Sziria Efraimmal egyesült! és megindula szíve s népének szíve, a mint megindulnak az erdő fái a szél miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'És mondá az Úr Ésaiásnak: Menj ki, kérlek, Akház eleibe te és Seár-Jásub fiad, a felső tó csatornájának végéhez, a ruhafestők mezejének útján;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'És mondd néki: Vigyázz és légy nyugodt; ne félj! és meg ne lágyuljon szíved e két füstölgő üszögdarab miatt, Reczinnek és Sziriának, és Remalja fiának felgerjedett haragja miatt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'Mivelhogy gonosz tanácsot tartott ellened Sziria, Efraim és Remalja fia, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, 'Menjünk el Júda ellen, s reszkettessük meg, és kapcsoljuk magunkhoz, és tegyük királylyá benne Tábeal fiát,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'Így szól az Úr Isten: Nem áll meg és nem lészen ez!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'Mert Sziria feje Damaskus, és Damaskusnak feje Reczin, és még hatvanöt esztendő, s megromol Efraim és nép nem lészen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'Efraim feje pedig Samaria, és Samaria feje a Remalja fia: ha nem hisztek, bizony meg nem maradtok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'És szóla ismét az Úr Akházhoz, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, 'Kérj jelt magadnak az Úrtól, a te Istenedtől, kérj a mélységben vagy fent a magasban!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'És mikor szóla Akház: Nem kérek s nem kisértem az Urat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'Akkor monda a próféta: Halld meg hát, Dávid háza! hát nem elég embereket bosszantanotok, hogy még az én Istenemet is bosszantjátok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'Ezért ád jelt néktek az Úr maga: Ímé, a szűz fogan méhében, és szül fiat, s nevezi azt Immánuelnek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'Ki vajat és mézet eszik, míg megtanulja a gonoszt megvetni, és a jót választani;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'Mert mielőtt e gyermek megtanulná megvetni a gonoszt, és a jót választani, elpusztul a föld, melynek két királyától te reszketsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'És hozni fog az Úr reád és népedre és atyád házára oly napokat, milyenek még nem jöttenek, mióta Efraim elszakadott Júdától: Assiria királyát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, 'És lesz ama napon: süvölt az Úr az Égyiptom folyóvize mellett való legyeknek, s Assiria földje méheinek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, 'S mind eljönnek, és letelepszenek a meredek völgyekben és sziklák hasadékaiban, minden töviseken és minden legelőkön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, 'Ama napon leberetválja az Úr a folyón túl bérlett beretvával, Assiria királya által a főt s a lábak szőrét, a mely a szakált is leveszi;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, 'És lesz ama napon, hogy kiki egy fejőstehenet tart és két juhot,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, 'És lészen, hogy a tej bősége miatt vajat eszik; mert vajat és mézet eszik, valaki csak megmaradott e földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, 'S lészen ama napon, hogy minden helyet, a hol ezer szőlőtő ezer siklust érő vala, tövis és gaz ver fel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 24, 'Nyilakkal és kézívvel mehet oda az ember, mivel tövis és gaz verte fel mind az egész földet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 25, 'Sőt a hegyekre, a melyeket kapával kapáltanak, sem fogsz felmenni, félvén a tövistől és gaztól; hanem barmok legelőjévé lesznek és juhok járásává.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'És monda nékem az Úr: Végy magadnak egy nagy táblát, és írd fel reá közönséges betűkkel: siess zsákmányra és gyorsan prédára;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'És én hív tanúkul választom magamnak Úriást, a papot és Zakariást, Jeberekiás fiát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'És bementem a prófétaasszonyhoz, a ki fogant, és szült fiat; és mondá az Úr nékem: Nevezd nevét: siess zsákmányra és gyorsan prédára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'Mert mielőtt e gyermek ezt ki tudja mondani: apám és anyám, Damaskus gazdagságát és Samaria prédáját Assiria királyának szolgája elviszi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'Ismét szólott az Úr hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, 'Mivel megútálta e nép Siloahnak lassan folyó vizét, és Reczinben és Remalja fiában gyönyörködik:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, 'Azért ímé rájok hozza az Úr a folyónak erős és sok vizét, Assiria királyát és minden ő hatalmát, és feljő minden medre fölé, és foly minden partjai felett,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'És becsap Júdába, és megáradván átmegy rajta, s torkig ér, és elterjesztett szárnyai ellepik földednek szélességét, oh Immánuel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'Fenekedjetek csak népek és romoljatok meg; figyeljetek, valakik messze laktok; készüljetek és megrontattok; készüljetek és megrontattok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'Tanácskozzatok, de haszontalan lesz, beszéljetek beszédet, de nem áll meg, mert Isten van mi velünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 11, 'Mert így szólott hozzám az Úr, rajtam lévén erős keze, hogy tanítson engem, hogy e népnek útján ne járjak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 12, 'Ti ne mondjátok összeesküvésnek, valamit e nép összeesküvésnek mond, és félelme szerint ne féljetek és ne rettegjetek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 13, 'A seregek Urát: Őt szenteljétek meg, Őt féljétek, és Őt rettegjétek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 14, 'És Ő néktek szenthely lészen; de megütközés köve és botránkozás sziklája Izráel két házának, s tőr és háló Jeruzsálem lakosainak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 15, 'És megütköznek köztük sokan, s elesnek és összetöretnek; tőrbe esnek és megfogatnak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 16, 'Kösd be e bizonyságtételt, és pecsételd be e tanítást tanítványaimban!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 17, 'Én pedig várom az Urat, a ki elrejté orczáját Jákób házától, és benne bízom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 18, 'Ímhol vagyok én és a fiak, kiket adott nékem az Úr jelekül és csodákul Izráelben: a Sion hegyén lakozó seregeknek Urától vagyunk mi!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 19, 'És ha ezt mondják tinéktek: Tudakozzatok a halottidézőktől és a jövendőmondóktól, a kik sipognak és suttognak: hát nem Istenétől tudakozik-é a nép? az élőkért a holtaktól kell-é tudakozni?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 20, 'A tanításra és bizonyságtételre hallgassatok! Ha nem ekként szólnak azok, a kiknek nincs hajnalok:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 21, 'Úgy bolyongani fognak a földön, szorongva és éhezve; és lészen, hogyha megéhezik, felgerjed és megátkozza királyát és Istenét, s néz fölfelé,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 22, 'És azután a földre tekint, és ímé mindenütt nyomor és sötétség, és szorongatásnak éjszakája, ő pedig a sűrű sötétben elhagyatva!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 23, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, 'De nem lesz mindig sötét ott, a hol most szorongatás van; először megalázta Zebulon és Nafthali földjét, de azután megdicsőíti a tenger útját, a Jordán túlsó partját és a pogányok határát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, 'A nép, a mely sötétségben jár vala, lát nagy világosságot; a kik lakoznak a halál árnyékának földében, fény ragyog fel fölöttök!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, 'Te megsokasítod e népet, nagy örömöt szerzesz néki, és örvendeznek előtted az aratók örömével, és vígadoznak, mint mikoron zsákmányt osztanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, 'Mert terhes igáját és háta vesszejét, az őt nyomorgatónak botját összetöröd, mint a Midián napján;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, 'Mert a vitézek harczi saruja és a vérbe fertőztetett öltözet megég, és tűznek eledele lészen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, 'Mert egy gyermek születik nékünk, fiú adatik nékünk, és az uralom az ő vállán lészen, és hívják nevét: csodálatosnak, tanácsosnak, erős Istennek, örökkévalóság atyjának, békesség fejedelmének!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, 'Uralma növekedésének és békéjének nem lesz vége a Dávid trónján és királysága felett, hogy fölemelje és megerősítse azt jogosság és igazság által mostantól mindörökké. A seregek Urának buzgó szerelme mívelendi ezt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, 'Beszédet küldött az Úr Jákóbnak, és leesett Izráelben,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, 'Hogy megértse az egész nép: Efraim és Samaria lakosa, a kik ezt mondják kevélyen és felfuvalkodva:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, 'Téglák omlottak le, és mi faragott kőből építünk; fügefák vágattak ki, és mi czédrusokat ültetünk helyökre!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, 'De az Úr ellenök hozza Reczin szorongatóit, és ellenségeiket rájok uszítja;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, 'A Sziriabeliek elől, és a Filiszteusok hátul, s falják Izráelt feltátott torokkal. Mindezekkel azonban haragja el nem múlt, és keze még felemelve van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, 'Hiszen e nép nem tért meg az őt verő Istenhez, és a seregeknek Urát nem keresték;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, 'Ezért kivágja az Úr Izráelből a főt és farkat, a pálmaágat és a kákát egy napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, 'A fő: a vén és a főember, a fark pedig a próféta, a ki hazugságot szól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, 'Mert e nép vezérei hitetőkké lettek, és a kiket vezetének, elvesztek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, 'Ezért ifjaiban sem gyönyörködik az Úr, s árváin és özvegyein sem könyörül; mert mindnyájan istentelenek és gonosztevők, és minden száj bolondságot beszél. Mindezekkel haragja el nem múlt, és keze még felemelve van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, 'Mert a gonoszság felgerjedt, mint a tűz, s tövist és gazt emészt, és meggyújtja a sűrű erdőt, és felgomolyg az füst oszlopában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, 'A seregek Urának haragja miatt kiégett a föld, és a nép a tűznek eledele lőn: Senki atyjafián nem könyörül,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, 'Jobbkézre vág és megéhezik, eszik balkézre és nem elégszik meg; mindnyájan karjoknak húsát eszik, Manassé Efraimot és Efraim Manassét; s mindketten Júda ellen kelnek. Mindezekkel haragja el nem múlt, és keze még felemelve van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, 'Jaj a hamis határozatok határozóinak, és a jegyzőknek, a kik gonoszt jegyeznek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'Hogy elriaszszák a gyöngéket a törvénykezéstől, s elrabolják népem szegényeinek igazságát, hogy legyenek az özvegyek az ő prédájok, és az árvákban zsákmányt vessenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'S vajjon mit míveltek a meglátogatásnak és a messzünnen rátok jövő pusztulásnak napján? Kihez futtok segítségért, és hol hagyjátok dicsőségeteket?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, 'Bizony csak: a foglyok alá hanyatlanak és a megölettek alá hullanak; mind ezekkel haragja el nem múlt, és keze még felemelve van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, 'Jaj Assiriának, haragom botjának, mert pálcza az ő kezében az én búsulásom!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'Istentelen nemzetség ellen küldtem őt, és haragom népe ellen rendelém, hogy prédáljon és zsákmányt vessen, és eltapodja azt, mint az utczák sarát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, 'De ő nem így vélekedik, és szíve nem így gondolkozik, mert ő pusztítani akar, és kigyomlálni sok népeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'Mert így szól: Vajjon vezéreim nem mind királyok-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'Nem úgy megvettem-é Kalnót, mint Kárkemist? És Hamáthot, mint Arphádot? És Samariát, mint Damaskust?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'Miképen megtalálta volt kezem a bálványok országait, holott pedig több faragott képük volt, mint Jeruzsálemnek és Samariának,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'Avagy a mint cselekedtem Samariával és az ő bálványaival; nem úgy cselekedhetem-é Jeruzsálemmel és bálványképeivel?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, 'Ezért ha majd elvégezi az Úr minden dolgát Sion hegyén és Jeruzsálemben, meglátogatom az Assiriabeli király nagyakaró szíve gyümölcsét és nagyralátó szeme kevélységét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'Mert ezt mondá: Kezem erejével míveltem ezt és bölcseségemmel, mivel okos vagyok; elvetettem sok népeknek határit, és kincseikben zsákmányt vetettem, és leszállítám, mint erős, a magasan ülőket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, 'És kezem úgy találta mintegy fészket a népek gazdagságát; és a mily könnyen elszedik az elhagyott tojásokat, azonképen foglaltam én el az egész földet; és nem volt senki, a ki szárnyát mozdította, vagy száját megnyitotta, vagy csak sipogott volna is!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, 'Avagy dicsekszik-é a fejsze azzal szemben, a ki vele vág? vagy a fűrész felemeli-é magát az ellen, a ki vonsza azt? Mintha a bot forgatná azt, a ki őt felemelé, és a pálcza felemelné azt, a mi nem fa!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'Azért az Úr, a seregek Ura kövéreire ösztövérséget bocsát, és az ő dicsősége alatt égés ég, miként a tűz égése;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, 'És lészen Izráel világossága tűz gyanánt, és annak Szentje láng gyanánt, és ég és megemészti gazzát és tövisét egy napon;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, 'Az ő erdejének és kertjének ékességét pedig lelkétől mind testéig megemészti, és lesorvad, mint a sorvadozó;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 19, 'Erdője fáinak maradéka kicsiny lészen, és azokat egy gyermek is felírhatja!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 20, 'És lészen ama napon, hogy többé nem támaszkodik Izráel maradéka és a ki megmaradt Jákób házából, az őt nyomorgatóhoz, hanem támaszkodik az Úrhoz, Izráel Szentjéhez hűségesen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 21, 'A maradék megtér, a Jákób maradéka az erős Istenhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 22, 'Mert ha néped Izráel számszerint annyi lenne is, mint a tenger fövenye, csak maradéka tér meg; az elvégezett pusztulás elárad igazsággal!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 23, 'Mert elvégezett pusztítást cselekszik az Úr, a seregek Ura, mind az egész földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 24, 'Azért így szól az Úr, a seregeknek Ura: Ne félj népem, Sionnak lakosa, az Assiriabeli királytól! bár botjával megver tégedet és pálczáját felemeli rád, miként Égyiptom egykoron;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 25, 'Mert még csak egy kevés idő van: és elfogy búsulásom, és haragom az ő megemésztésökre lészen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 26, 'És a seregeknek Ura ostort emel ő ellenök, miként a Midián levágatása idején az Oreb kőszikláján, és pálczáját a tenger fölé emeli, mint Égyiptomban egykoron.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 27, 'És lesz ama napon: eltávozik az ő terhe válladról és igája nyakadról, és megromol az iga a kövérségnek miatta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 28, 'Ajjáthba jő, Migronba átsiet, Mikhmásnál rakja le hadakozó szerszámait;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 29, 'Átmennek a szoroson, Gébában lesz hálóhelyünk; megrémül Ráma, Gibea, Saulnak városa elfut.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 30, 'Kiálts Gallim leánya, és vedd füleidbe Laisa, és szegény Anathóth!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 31, 'Madména megindul, Gébim lakosai mentik övéiket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 32, 'Még Nóbba megyen ma, hogy ott megálljon, és emeli már kezét Sion leányának hegye és Jeruzsálemnek halma ellen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 33, 'De ímé az Úr, a seregeknek Ura: levagdalja az ágakat rémítő hatalommal, és a magas termetűek kivágattatnak, és a magasságosak megaláztatnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 34, 'Az erdő sűrű ágait levágja vassal, és megdől a Libánon egy hatalmas által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'És származik egy vesszőszál Isai törzsökéből, s gyökereiből egy virágszál nevekedik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'A kin az Úrnak lelke megnyugoszik: bölcseségnek és értelemnek lelke, tanácsnak és hatalomnak lelke, az Úr ismeretének és félelmének lelke.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, 'És gyönyörködik az Úrnak félelmében, és nem szemeinek látása szerint ítél, és nem füleinek hallása szerint bíráskodik:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, 'Igazságban ítéli a gyöngéket, és tökéletességben bíráskodik a föld szegényei felett; megveri a földet szájának vesszejével, és ajkai lehével megöli a hitetlent.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, 'Derekának övedzője az igazság lészen, és veséinek övedzője a hűség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'És lakozik a farkas a báránynyal, és a párducz a kecskefiúval fekszik, a borjú és az oroszlán-kölyök és a kövér barom együtt lesznek, és egy kis gyermek őrzi azokat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, 'A tehén és medve legelnek, és együtt feküsznek fiaik, az oroszlán, mint az ökör, szalmát eszik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 8, 'És gyönyörködik a csecsszopó a viperák lyukánál, és a csecstől elválasztott a baziliskus lyuka felett terjengeti kezét:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 9, 'Nem ártanak és nem pusztítnak sehol szentségemnek hegyén, mert teljes lészen a föld az Úr ismeretével, mint a vizek a tengert beborítják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 10, 'És lesz ama napon, hogy Isai gyökeréhez, a ki a népek zászlója lészen, eljőnek a pogányok, és az ő nyugodalma dicsőség lészen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 11, 'És lesz ama napon: az Úr másodszor nyujtja ki kezét, hogy népe maradékát megvegye, a mely megmaradt Assiriától, Égyiptomtól, Pathrosztól, Szerecsenországtól, Elámtól, Sinártól, Hamáthtól és a tenger szigeteitől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 12, 'És zászlót emel a pogányok előtt, és összegyűjti Izráel elszéledt fiait, és Júdának szétszórt leányait egybegyűjti a földnek négy szárnyairól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 13, 'Megszünik Efraimnak irígysége, és Júdából a gyűlölködők kivágattatnak; Efraim nem irígykedik Júdára, és Júda sem támad többé Efraimra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 14, 'És repülnek a Filiszteusoknak hátára napnyugot felé, és kelet fiaiban együtt vetnek zsákmányt, és kezet vetnek Edomra és Moábra, és az Ammoniták engednek nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 15, 'És az Úr megátkozza Égyiptom tengerének nyelvét, és kezét felemeli az Eufráth fölé erős száraztó szélben, és hét patakra csapja azt, és népét sarus lábbal vezeti át,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 16, 'És csinált út lészen népe maradékának, a mely megmaradt Assiriától, a mint volt Izráelnek, mikor kijött Égyiptomnak földéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'És így szólsz ama napon: Hálákat adok néked, oh Uram! mert jóllehet haragudtál reám, de elfordult haragod, és megvígasztaltál engemet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, 'Ímé, az Isten az én szabadítóm! bízom és nem félek; mert erősségem és énekem az Úr, az Úr, és lőn nékem szabadítóm!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, 'S örömmel merítetek vizet a szabadító kútfejéből,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'És így szólotok ama napon: Adjatok hálát az Úrnak, magasztaljátok az Ő nevét, hirdessétek a népek közt nagyságos dolgait, mondjátok, hogy nagy az Ő neve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, 'Mondjatok éneket az Úrnak, mert nagy dolgot cselekedett; adjátok tudtára ezt az egész földnek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, 'Kiálts és örvendj, Sionnak lakosa, mert nagy közötted Izráelnek Szentje!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, 'Jövendölés Babilonia ellen, a melyet látott Ésaiás, Ámós fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, 'Emeljetek zászlót kopasz hegyen, kiáltsatok nékik, kézzel intsetek, hogy bevonuljanak a fejedelmek kapuin!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, 'Én parancsoltam felszentelt vitézeimnek, és elhívtam erősimet haragomnak véghezvitelére, a kik én bennem büszkén örvendenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, 'Hah! zsibongás a hegyeken, mint nagy néptömegé; hah! összegyűlt népek országainak zúgása; a seregek Ura harczi sereget számlál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, 'Jőnek messze földről, az égnek végéről, az Úr, és haragjának eszközei, elpusztítani mind az egész földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, 'Jajgassatok, mert közel van az Úrnak napja, mint pusztító hatalom jő a Mindenhatótól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 7, 'Ezért megerőtlenülnek minden kezek, és elolvad minden embernek szíve;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 8, 'És megrémülnek, kínok és fájdalmak fogják el őket, és szenvednek, mint a szülőasszony; egyik a másikon csodálkozik, és arczuk lángba borul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 9, 'Ímé az Úrnak napja jő kegyetlen búsulással és felgerjedt haraggal, hogy a földet pusztasággá tegye, és annak bűnöseit elveszesse arról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 10, 'Mert az ég csillagai és csillagzatai nem ragyogtatják fényöket, sötét lesz a nap támadásakor, és a hold fényét nem tündökölteti.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 11, 'És meglátogatom a földön a bűnt, és a gonoszokon vétküket, és megszüntetem az istentelenek kevélységét, és az erőszakoskodóknak gőgjét megalázom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 12, 'Drágábbá teszem az embert a színaranynál, és a férfit Ofir kincsaranyánál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 13, 'Ezért az egeket megrendítem, és megindul helyéről a föld is, a seregek Urának búsulása miatt, és felgerjedett haragjának napján,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 14, 'És mint az űzött zerge, és mint a pásztor nélkül való nyáj, kiki népéhez tér meg, és kiki az ő földére fut;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 15, 'Valaki ott találtatik, átveretik, és valaki megfogatik, fegyver miatt hull el,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 16, 'Kisdedeiket szemök előtt zúzzák szét, házaikat elzsákmányolják, és feleségeiket megszeplősítik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 17, 'Ímé, én feltámasztom ellenök a Médiabelieket, a kik ezüsttel nem gondolnak, és aranyban nem gyönyörködnek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 18, 'Kézíveik szétzúznak ifjakat, és nem könyörülnek a méh gyümölcsén, a fiaknak nem irgalmaz szemök:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 19, 'És olyan lesz Babilon, a királyságok ékessége, a Khaldeusok dicsekvésének dísze, mint a hogyan elpusztítá Isten Sodomát és Gomorát;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 20, 'Nem ülik meg soha, és nem lakják nemzetségről nemzetségre, nem von sátort ott az arábiai, és pásztorok sem tanyáznak ott;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 21, 'Hanem vadak tanyáznak ott, és baglyok töltik be házaikat, és struczok laknak ott, és bakok szökdelnek ott;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 22, 'És vad ebek üvöltenek palotáikban, és mulató házaikban sakálok; és ideje nem sokára eljő, és napjai nem késnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, 'Mert könyörül az Úr Jákóbon, és ismét elválasztja Izráelt, és megnyugotja őket földjükön; és a jövevény hozzájok adja magát, és a Jákób házához csatlakoznak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, 'És felveszik őket a népek, és elviszik őket lakhelyökre, és Izráel háza bírni fogja őket az Úr földén, szolgák és szolgálók gyanánt; és foglyaik lesznek foglyul vivőik, és uralkodnak nyomorgatóikon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, 'És majd ama napon, a melyen nyugalmat ád néked az Úr fáradságodtól és nyomorúságodtól és ama kemény szolgálattól, a melylyel szolgálnod kellett,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, 'E gúnydalt mondod Babilon királya felett, és szólsz: Miként lőn vége a nyomorgatónak, a szolgaság házának vége lőn!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, 'Eltörte az Úr a gonoszok pálczáját, az uralkodóknak vesszejét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, 'A ki népeket vert dühében szüntelen való veréssel, leigázott népségeket haraggal, kergettetik feltartózhatlanul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, 'Nyugszik, csöndes az egész föld. Ujjongva énekelnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 8, 'Még a cziprusok is örvendenek rajtad: a Libánon czédrusai ezt mondják: Mióta te megdőltél, nem jő favágó ellenünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 9, 'Alant a sír megindul te miattad megérkezésedkor, miattad felriasztja árnyait, a föld minden hatalmasit, felkölti székeikről a népek minden királyait;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 10, 'Mind megszólalnak, és ezt mondják néked: Erőtlenné lettél te is, miként mi; hozzánk hasonlatos levél!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 11, 'Kevélységed és lantjaid zengése a sírba szállt; fekvő ágyad férgek, és takaró lepled pondrók!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 12, 'Miként estél alá az égről fényes csillag, hajnal fia!? Levágattál a földre, a ki népeken tapostál!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 13, 'Holott te ezt mondád szívedben: Az égbe megyek fel, az Isten csillagai fölé helyezem ülőszékemet, és lakom a gyülekezet hegyén messze északon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 14, 'Felibök hágok a magas felhőknek, és hasonló leszek a Magasságoshoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 15, 'Pedig a sírba szállsz alá, sírgödör mélységébe!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 16, 'A kik látnak, rád tekintenek, és elgondolják: Ez-é a föld ama háborgatója, a ki királyságokat rendített meg?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 17, 'A ki a föld kerekségét pusztasággá tette, városait lerontá, és foglyait nem bocsátá haza!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 18, 'A népeknek minden királyai dicsőségben nyugosznak, kiki az ő sírjában,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 19, 'Te pedig messze vettetel sírodtól, mint valami hitvány gally, takarva megölettekkel, fegyverrel átverettekkel, sziklasírba leszállókkal, mint valami eltapodott holttest!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 20, 'Nem egyesülsz velök a sírban, mert elpusztítád földedet, megölted népedet: nem él sokáig a gonoszok magva sem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 21, 'Készítsetek öldöklést az ő fiainak atyáik vétkéért, hogy fel ne keljenek, és örökségül bírják e földet, és városokkal töltsék be e földnek színét!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 22, 'És felkelnek ő ellenök, szóla a seregeknek Ura, és kivágom Babilon nevét és maradékát, fiait és unokáit, szól az Úr;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 23, 'És a sündisznónak örökségévé és álló vizek tavává teszem azt, és elsöpröm azt a pusztítás seprőjével, szól a seregeknek Ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 24, 'Megesküdött a seregeknek Ura, mondván: Úgy lészen, mint elgondolám, úgy megy véghez, mint elvégezém:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 25, 'Megrontom Assiriát földemen, és megtapodom hegyeimen, és eltávozik róluk igája, és terhe válláról eltávozik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 26, 'Ez az elvégezett tanács az egész föld felől, és ez ama felemelt kéz minden népek fölött.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 27, 'Mert a seregek Ura végezte, és ki teszi azt erőtelenné? Az ő keze fel van emelve; ki fordítja el azt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 28, 'A mely esztendőben meghalt Akház király, akkor lőn e jövendölés.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 29, 'Ne örvendj oly nagyon Filisztea, hogy eltört a téged verőnek vesszeje, mert a kígyó magvából baziliskus jő ki, a melytől szárnyas sárkány származik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 30, 'És legelnek a szegényeknek elsőszülöttei, és a szűkölködők bátorsággal nyugosznak; és én kivesztem gyökeredet éhséggel, és maradékodat megölik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 31, 'Jajgass kapu, kiálts város! remeg egész Filisztea, mivel füst jő észak felől; és nem marad el seregeiből egy sem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 32, 'És mit felelnek a népek követei? Azt, hogy az Úr veté meg a Sion alapját, és abban bíznak népe szegényei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, 'Jövendölés Moáb ellen. Igen, a pusztulás éjjelén megsemmisült Ar-Moáb; igen, a pusztulás éjjelén megsemmisült Kir-Moáb!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, 'Felmennek a templomba, és Dibon a magaslatokra megy sírni, Nebón és Médebán jajgat Moáb, minden fejen kopaszság, minden szakál lenyírva!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, 'Utczáin gyászruhába öltöznek, házfedelein és piaczain jajgat minden, és könyekben olvad el!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, 'És kiált Hesbon és Eleálé, szavok Jáháczig hallatik; ezért ordítanak Moáb vitézei, és lelke reszket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, 'Szívem kiált Moábért, a melynek végvárai Zoárig, a három éves üszőig nyúltanak; mert Luhith hágóján sírással mennek fel, és mert Horonaim útján romlásuknak kiáltását hallatják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 6, 'Mert Nimrim vizei pusztasággá lesznek, mert elszáradt a pázsit, elfogyott a fű, és semmi zöld nem lészen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 7, 'Ezért a mit megmenthettek és jószágukat a fűzfáknak patakja mellé hordják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 8, 'Mert kiáltás zengé körül Moáb határát, jajgatása Eglaimig, és Beér-Élimig hallatik jajgatása!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 9, 'Mert Dimon vizei megteltek vérrel, mert új romlást hozok Dimonra: Moáb menekültjeire oroszlánt, és a földnek maradékira.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, 'Küldjétek a föld Urának bárányát Szelából a pusztán át Sion leányának hegyére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, 'Mert mint a bujdosó madár szétszórt fészek körül, olyanok lőnek Moáb leányai az Arnon gázlóin:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, 'Adj tanácsot, tarts ítéletet; tegyed árnyékodat délben olyanná, mint az éjszaka, rejtsd el a kiűzötteket, és a bujdosót ne add ki!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, 'Lakozzanak benned menekültjeim, és Moábnak te légy oltalom a pusztító ellen! Mert vége a nyomorgatónak, megszünt a pusztítás, és elfogytak a földről a tapodók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, 'És Isten kegyelme megerősített egy ülőszéket, és ül azon igazsággal Dávid sátorában egy bíró, jogosság keresője, igazság ismerője.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, 'Hallottuk volt Moáb kevélységét, a felettébb kevélyét, gőgjét, kevélységét, dühét, és üres kérkedését.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, 'Ezért jajgatni fog Moáb Moábért, minden jajgatni fog, és nyögtök Kir-Háresethnek romjain egészen megtörve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, 'Mert Hesbon földei elhervadának, és Sibma szőlőjének drága vesszőit a népek fejedelmei levágták. Jáézerig értek azok, a pusztát bejárták, kacsai szétterjedtek, és a tengeren túlnyúltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, 'Ezért siratom Jáézer siralmával Sibma szőlőjét, megnedvesítlek könyeimmel Hesbon és Eleálé, mert szüretedről és aratásodról a víg éneklés elmaradt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, 'Elvétetett a vígság és öröm a kertből, és a szőlőkben nem vígadnak és nem kiáltanak, bort sajtókban nem nyom a bornyomó, véget vetettem a víg éneklésnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, 'Ezért bensőm Moábért, mint a czitera sír, és szívem Kir-Heresért!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 12, 'És lesz, hogy meg fog tetszeni, hogy Moáb a magaslaton elfáradt, és hogy templomába megy imádkozni, de nem mehet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 13, 'Ez a beszéd, a melyet szólott az Úr Moáb felől már régen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 14, 'És most szól az Úr, mondván: Három esztendő alatt, melyek, mint napszámos esztendői, megaláztatik Moáb dicsősége egész nagy népével együtt, és maradéka kicsiny, kevés és erőtelen lészen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, 'Jövendölés Damaskus ellen. Ímé Damaskus városa elpusztíttatik, és romok halmává lesz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, 'Aróer városai elhagyatnak, és barmokéi lesznek, a melyek ott fognak nyugodni háborítatlanul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, 'És vége lesz Efraim erősségének, és Damaskus királyságának; Siria maradéka úgy jár, mint az Izráeliták dicsősége, ezt mondja a seregeknek Ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, 'És lesz ama napon: megvékonyul a Jákób dicsősége, és húsa kövérsége megösztövéredik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, 'És lészen, mint mikor az arató összefogja a gabonát és a kalászokat kezével learatja, és lészen, mint mikor valaki kalászokat szed össze a Refáim völgyében;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, 'És csak mezgérlés marad belőlök, mint az olajfa megrázásakor két-három bogyó az ágak hegyén, négy-öt a gyümölcsfának lombjai közt, így szól az Úr, Izráel Istene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, 'Ama napon Teremtőjére tekint az ember, és szemei Izráel Szentjére néznek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, 'És nem tekint az oltárokra, kezeinek alkotmányára, és a miket ujjai csináltak, nem nézi azokat, a berkeket és a nap-oszlopokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, 'Erős városai olyanok lesznek ama napon, mint elhagyott erdő és hegytető, a melyeket elhagytak volt Izráel fiai előtt, és pusztasággá lesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, 'Mert elfelejtkeztél megszabadító Istenedről, és nem emlékeztél meg erős kőszáladról, ez okért ültetél gyönyörűséges ültetéseket, és idegen vesszőt plántáltál beléjök;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, 'A mely napon elültetted, körül sövényezéd és reggelre magodat felvirágoztatád: de nem lészen aratás sebeidnek és nagy fájdalmadnak napján!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, 'Jaj a sok nép zúgásának, a kik úgy zúgnak, mint a tenger zúgása, és a népségek háborgásának, a kik háborognak, mint erős vizek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, 'A népségek, mint sok vizek háborgása, úgy háborognak, de megdorgálja azt és elfut messzire, és elragadtatik, mint a hegyek polyvája szél előtt és mint pozdorja a forgószél előtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, 'Estvének idején rémülés száll reájok és minekelőtte megvirrad, nem lesznek: ez jutalmok pusztítóinknak és sorsok rablóinknak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, 'Jaj a szárnysuhogás országának, a mely Szerecsenország folyóin túl van;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, 'A mely követeket küld a tengeren gyékényből csinált tutajokon, vizek színén. Menjetek el gyors hírnökök, a magas és derék néphez, a néphez, a mely rettenetes mióta van és ezután is; a hatalmas és hódító néphez, a melynek földét folyók hasítják át.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, 'Föld kerekségének minden lakói és földnek lakosai meglássátok, mikor a hegyeken zászló emelkedik, és hallgassatok, ha kürt szól!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, 'Mert ezt mondá az Úr nékem: Nyugodtan nézem sátoromból verőfényes melegnél, harmatozó felhőnél aratás hévségében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, 'Mert aratás előtt, ha a virágzás véget ér, és a virág érő fürtté lészen, levágja a vesszőket metszőkésekkel, és a kacsokat eltávolítja és lemetszi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, 'Mind ott hagyatnak a hegyek madarainak és a föld állatainak, és a madarak rajtok nyaralnak, és a föld minden állatai rajtok telelnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, 'Abban az időben ajándékot viszen a seregek Urának a magas és derék nép; a nép, a mely rettenetes, mióta van és ezután is, a hatalmas és hódító nép, a melynek földét folyók hasítják át; a seregek Ura nevének helyére, Sion hegyére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, 'Jövendölés Égyiptom ellen. Ímé az Úr könnyű felhőre ül, és bemegy Égyiptomba, és megháborodnak előtte Égyiptomnak bálványai, és az égyiptomiak szíve megolvad ő bennök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, 'És összeveszítem az égyiptomiakat az égyiptomiakkal, és egyik hadakozik a másik ellen, kiki felebarátja ellen, város város ellen, és ország ország ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, 'És elfogyatkozik az égyiptomiak lelke ő bennök, és az ő tanácsát elnyelem, és tudakoznak a bálványoktól, szemfényvesztőktől, halottidézőktől és jövendőmondóktól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, 'És adom az égyiptomiakat kemény úrnak kezébe, és kegyetlen király uralkodik rajtok, szól az Úr, a seregeknek Ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, 'És elfogyatkoznak a tenger vizei, és a folyam kiszárad és elapad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, 'És büdösséget árasztanak a folyamok, elfogynak és kiszáradnak Égyiptomnak patakjai; nád és sás ellankadnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, 'A pázsit a folyó mellett, a folyónak partján, és a folyónak minden veteménye megszárad, elporlik és nem lészen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, 'És keseregnek a halászok, és gyászolnak mind, a kik a folyóba horgot vetni szoktak, és a kik a vizek színén hálót vetnek ki, búsulnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, 'És megszégyenülnek a fésült len készítői és a gyolcs szövői.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, 'Hatalmasaik megtöretnek, és minden napszámosaik bánkódnak lelkökben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, 'Bizony bolondok Zoán fejedelmei, a Faraó bölcs tanácsosai egy eszét veszített tanács; mimódon mondjátok a Faraónak: bölcsek fia vagyok, régi királyoknak fia?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, 'Ugyan hol vannak bölcseid? hogy megjelentsék néked és tudják, hogy mit végzett a seregeknek Ura Égyiptom felől?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, 'Megbolondultak Zoán fejedelmei, és csalódtak Nóf fejedelmei, és elámíták az Égyiptomiakat törzseik szegletkövei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, 'Az Úr beléje önté a szédelgés lelkét, hogy Égyiptomot elhitessék minden dolgaiban; miként a részeg tántorog az ő okádása felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, 'És nem lesz Égyiptomnak semmi munkája, a melyet cselekednék a fő és fark, a pálmaág és a káka.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 16, 'Ama napon olyan lesz Égyiptom, mint az asszonyok, retteg és fél a seregek Ura kezének felemelésétől, a melyet fölemel ellene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 17, 'És Júda földe félelmére lesz Égyiptomnak, valaki csak említi azt előtte, már fél, a seregek Urának tanácsáért, a melyet Ő végzett felőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 18, 'Ama napon lesz öt város Égyiptomnak földén, a melyek Kanaán nyelvén szólanak, és esküsznek a seregeknek Urára; az egyik „pusztulás városának” neveztetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 19, 'Ama napon oltára lesz az Úrnak Égyiptom földének közepette és határán egy oszlop az Úrnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 20, 'És lesz jegyül és bizonyságul a seregek Urának Égyiptom földén, hogy ha kiáltanak az Úrhoz a nyomorgatók előtt, hogy küldjön nékik megtartót és fejedelmet, és őket megszabadítsa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 21, 'És megismerteti magát az Úr Égyiptommal, és megismeri Égyiptom az Urat ama napon, és szolgálják véres áldozattal és ételáldozattal, és fogadnak fogadást az Úrnak, és teljesítik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 22, 'De ha megveri az Úr Égyiptomot, megvervén, meggyógyítja, és megtérnek az Úrhoz, és Ő meghallgatja és meggyógyítja őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 23, 'Ama napon út lesz Égyiptomból Assiriába, és Assiria megy Égyiptomba, Égyiptom meg Assiriába, és Égyiptom Assiriával az Urat tiszteli.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 24, 'Ama napon Izráel harmadik lesz Égyiptom és Assiria mellett; áldás a földnek közepette;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 25, 'Melyet megáld a seregeknek Ura, mondván: Áldott népem, Égyiptom! és kezem munkája, Assiria! és örökségem Izráel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, 'Amely esztendőben Asdódba ment a Tartán, Szargon Assiria királya küldvén őt, és vívá Asdódot és azt elfoglalá:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, 'Ez időben szólott az Úr Ésaiás, Ámos fia által, mondván: Menj és oldd le a gyászruhát derekadról, és sarudat vond le lábadról! És úgy cselekedett, járván ruha és saru nélkül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, 'És mondá az Úr: A mint szolgám Ésaiás ruha és saru nélkül jár három esztendeig jegyül és jelenségül Égyiptomra és Szerecsenországra nézve:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, 'Úgy viszi el Assiria királya Égyiptom foglyait és Szerecsenország rabjait, ifjakat és véneket, ruha és saru nélkül és mezítelen alfellel, Égyiptomnak gyalázatára;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, 'S megrettennek és megszégyenülnek Szerecsenország miatt, a melyben reménykedtek, és Égyiptom miatt, a melyben dicsekedtek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, 'És szól e partvidék lakosa ama napon: Ímé így járt reménységünk, hova segítségért futottunk, hogy Assiria királyától megszabaduljunk; hát mi miként menekülhetnénk meg?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, 'Jövendölés a tenger pusztasága ellen. Mint szélvészek, délen tombolók, úgy jő a pusztából, rettenetes földről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, 'Kemény látás jelentetett meg nékem: a csalárd csal, a pusztító pusztít. Jőjj fel Élám, szálld meg Madai, minden ő fohászkodásának véget vetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, 'Ezért ágyékim telvék fájdalommal, és kínok fogtak el, mint a szűlő asszony kínjai; gyötrődöm hallása miatt, és megrémültem látása miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, 'Reszket szívem, iszonyúság rettent, a kedves éjszakát remegéssé tevé nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, 'Teríts asztalt, vigyázzon a vigyázó, egyetek, igyatok; föl fejedelmek, kenjétek a paizst!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, 'Mert így szólott hozzám az Úr: Menj és állass őrállót, a mit lát, mondja meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, 'És látott lovas csapatot, páros lovagokat, szamaras csapatot, tevés csapatot, és nagy figyelmesen hallgatott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, 'És kiálta, mint oroszlán: Uram, az őrtoronyban állok szüntelen napestig, és őrhelyemen állok egész éjszakákon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, 'És ímé, lovas csapat jött, páros lovagok, és szólott és mondá: Elesett, elesett Babilon, s isteneinek minden faragott képeit a földre zúzták le.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, 'Oh én cséplésem és szérűmnek fia, a mit hallottam a seregek Urától, Izráel Istenétől, azt jelentém meg néktek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, 'Jövendölés Dúma ellen: Seirből így kiáltnak hozzám: Vigyázó! meddig még az éjszaka, meddig még ez éj?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, 'Szólt a vigyázó: Eljött a reggel, az éjszaka is; ha kérdeni akartok, kérdjetek, forduljatok vissza és jertek el!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, 'Jövendölés Arábia ellen: Az erdőben háltok Arábiában, Dédán utazó seregei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, 'A szomjazó elé hozzatok vizet! Témá földének lakosi kenyerökkel jönnek a bujdosó elébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 15, 'Mert az ellenség fegyvere előtt bujdosnak, a kivont fegyver előtt és a felvont kézívek előtt és a nehéz harcz előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 16, 'Mert így szólott hozzám az Úr: Még egy esztendő, mely mint a béresnek esztendeje, és elvész Kédárnak minden dicsősége;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 17, 'És Kédár vitéz fiainak kézíve számának maradéka megkevesedik; mert az Úr, Izráel Istene mondá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, 'Jövendölés a látás völgye ellen. Mi lelt most, hogy mindenestől felmenél a házak tetejére?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, 'Te lármával teljes, zajos város, örvendező város, megöletteid nem fegyverrel ölettek meg, és nem harczon hullottak el!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, 'Hadnagyaid mind elszaladtak a kézív előtt, de megkötöztettek; a kik benned találtattak, mind megkötöztettek, midőn futni akartak messzire.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, 'Ezért mondom: Ne nézzetek reám, hadd kesergessem magamat sírással; ne siessetek vígasztalni engem, népem leánya romlása felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, 'Mert rémülésnek és eltapodtatásnak és zavarnak napja jő Istentől, a seregeknek Urától a látás völgyére, a mely ledönti a kőfalat, és a hegyeken kiáltás hallatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, 'És Élám fölvette a tegezt, és jő szekeren emberekkel és lovagokkal, és Kir paizst meztelenít.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, 'És lészen, hogy szép völgyeid betelnek szekerekkel, és a lovagok nyomulnak a kapu felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, 'És fölfedi Júdának fátyolát, és tekintesz ama napon az erdő házának fegyverzetére,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, 'És meglátjátok, hogy Dávid városán sok repedés van, és összegyűjtitek az alsó tó vizét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, 'És megszámláljátok Jeruzsálem házait, és némely házat lerontotok, hogy a kőfalat megerősíthessétek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, 'És árkot csináltok a két kőfal között a régi tó vizének; és nem tekintetek arra, a ki ezt cselekvé, és a ki régen elvégzé ezt, Őt nem látjátok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, 'És fölhív az Úr, a seregek Ura ama napon sírásra és gyászolásra, ti magatok megkopaszítására és gyászruha-öltésre,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, 'És ímé öröm és vígasság; barmok ölése, juhok levágása, húsevés és borivás; együnk, igyunk, mert holnap meghalunk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, 'És megjelenté magát füleimben a seregek Ura: Meg nem bocsáttatik e bűn tinéktek, míg meg nem haltok; szól az Úr, a seregek Ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, 'Így szólt az Úr, a seregek Ura: No, menj el a kormányzóhoz, Sébnához, a királyi ház főemberéhez, és mondd meg néki:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, 'Mi dolgod itt, és ki lesz itten tied, hogy sírt vágatsz itten magadnak? mint a ki sírját magas helyen vágatja, és sziklába véset hajlékot magának!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, 'Ímé az Úr elhajít téged erős hajítással, és megragadván megragad,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, 'Hempelygetvén hempelyget, mint gombolyagot, mint labdát, nagy messze földre, ott halsz meg, oda mennek dicsőséged szekerei, te, urad házának gyalázata!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, 'És kivetlek állásodból és lerántlak helyedről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, 'És lesz ama napon, hogy elhívom szolgámat, Eliákimot, a Hilkiás fiát,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, 'S felöltöztetem őt öltözetedbe, és öveddel megerősítem, és uralmadat kezébe adom, és ő lesz atyjok Jeruzsálem lakosainak és a Júda házának;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, 'S az ő vállára adom a Dávid házának kulcsát, és a mit megnyit, senki be nem zárja, és a mit bezár, nem nyitja meg senki;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, 'S beverem őt, mint szeget erős helyre, és lészen dicsőséges székül az ő atyja házának;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, 'S reá függesztik atyja házának minden dicsőségét: fiakat és unokákat, minden kicsiny edényt, a csészeedényektől a tömlőknek minden edényeiig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, 'Ama napon, azt mondja a seregeknek Ura, kiesik a szeg, mely erős helyre veretett, és levágatik és leesik és összetörik a teher, mely rajta volt, mert az Úr mondá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, 'Jövendölés Tírus ellen. Jajgassatok Tarsis hajói, mert elpusztíttatott, úgy hogy nincs benne ház és abba bemenet! A Kitteusok földéről jelentetett meg nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, 'Némuljatok meg lakosi e partvidéknek, a melyet Sidon kalmárai, a kik tengeren járnak, töltöttek be egykor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, 'Melynek sok vizeken át a Sihór veteménye és a Nilus aratása vala jövedelme, úgy hogy népek vására volt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, 'Pirulj Sidon, mert szól a tenger és a tenger erőssége, mondván: Nem vajudtam, nem is szültem, és nem tápláltam ifjakat, és nem neveltem szűzeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, 'Mihelyt e hír Égyiptomba eljut, Tírus e híre miatt szenvednek ott is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, 'Menjetek át Tarsisba, és jajgassatok ti partvidék lakói!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 7, 'Ez-é a ti örvendező várostok? melynek eredete ősidőkből való; és most lábai viszik őt, bujdosni messzire!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 8, 'Ki végezé ezt a koronás Tírus felől? melynek kereskedői fejedelmek, és kalmárai a földnek tiszteletesei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 9, 'A seregeknek Ura végezé ezt, hogy meggyalázza minden dicsőségnek kevélységét, és hogy megalázza a föld minden tiszteleteseit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 10, 'Terülj el földeden, mint a folyóvíz, Tarsis leánya, nincs többé megszorító öv!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 11, 'Kezét kinyujtá a tenger fölé, országokat rettentett meg, az Úr parancsolt Kanaán felől, hogy elpusztítsák erősségeit;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 12, 'És szólt: Nem fogsz többé örvendezni, te megszeplősített szűz, Sidon leánya; kelj és menj át Kittimbe, de ott sem lészen nyugodalmad!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 13, 'Ímé, a Káldeusok földe; a nép, mely eddig nem vala; Assiria adá azt a puszta lakosainak; felállítá őrtornyait, lerombolá Tírus palotáit, rommá tevé azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 14, 'Jajgassatok Tarsis hajói, mert erősségtek elpusztíttatott!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 15, 'És lesz ama napon, hogy Tírus elfelejtetik hetven esztendeig egy király napjai szerint; hetven esztendő multán Tírus sorsa a parázna nő éneke szerint lészen:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 16, 'Végy cziterát, járd be a várost, elfeledett parázna nő; pengesd szépen, dalolj sokat, hogy így emlékezetbe jőjj!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 17, 'És lesz hetven esztendő multán, meglátogatja az Úr Tírust, és az ismét megkapja a maga keresetét, és paráználkodik a föld minden országaival a földnek színén!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 18, 'S lészen az ő nyeresége és keresete szent az Úrnak, mely nem halmoztatik fel, sem el nem rejtetik, mert az Úr előtt lakozóké lészen az ő nyeresége, hogy egyenek eleget, és szép ruházatuk legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, 'Ímé az Úr megüresíti a földet és elpusztítja azt, és elfordítja színét és elszéleszti lakóit!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, 'S olyan lesz a nép, mint a pap; a szolga, mint az ő ura; a szolgáló, mint asszonya; a vevő, mint az eladó; a kölcsönadó, mint a kölcsönkérő; a hitelező, mint az, a kinek hitelez;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, 'Megüresíttetvén megüresíttetik a föld, és elpusztíttatván elpusztíttatik; mert az Úr szólá e beszédet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, 'Gyászol és megromol a föld, elhervad és megromol a földnek kereksége, elhervadnak a föld népének nagyjai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, 'A föld megfertőztetett lakosai alatt, mert áthágták a törvényeket, a rendelést megszegték, megtörték az örök szövetséget.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, 'Ezért átok emészti meg a földet, és lakolnak a rajta lakók; ezért megégnek a földnek lakói, és kevés ember marad meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, 'Gyászol a must, elhervad a szőlő, és sóhajtnak minden vidám szívűek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, 'Megszünt a dobok vidámsága, elcsöndesült az örvendők zajgása, a cziterának vídámsága megszünt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, 'Énekléssel nem isznak bort; keserű a részegítő ital az ívónak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, 'Rommá lőn az álnokság városa, bezároltatott minden ház, senki be nem mehet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 11, 'Az utczákon panaszkodás hallik a bor miatt; minden öröm alkonyra szállt, a föld vígassága elköltözött.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 12, 'A városban csak pusztaság maradt és rommá zúzatott a kapu.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 13, 'Mert így lesz a föld közepette, a népek között, mint az olajfa megrázásakor, mint mezgérléskor, midőn a szüret elmult.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 14, 'Ők felemelik szavokat, ujjongnak, az Úr nagyságáért rivalgnak a tenger felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 15, 'Ezért dícsérjétek az Urat keleten, a tenger szigetein az Úrnak, Izráel Istenének nevét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 16, 'A föld széléről énekeket hallánk: dicsőség az igaznak! S én mondék: végem van, végem van, jaj nékem! A hitetlenek hitetlenül cselekesznek és hitetlenséggel a hitetlenek hitetlenséget cselekesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 17, 'Rettegés, verem és tőr vár rád földnek lakója!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 18, 'És lesz, hogy a ki fut a rettegésnek szavától, verembe esik, és a ki kijő a veremből, megfogatik a tőrben, mert az egek csatornái megnyílnak, és megrendülnek a föld oszlopai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 19, 'Romlással megromol a föld, töréssel összetörik a föld, rengéssel megrendül a föld;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 20, 'Inogva meging a föld, miként a részeg, és meglódul, mint a kaliba, és reá nehezedik bűne és elesik; és nem kél fel többé!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 21, 'És lesz ama napon: meglátogatja az Úr a magasság seregét a magasságban, és a föld királyait a földön:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 22, 'És összegyűjtve összegyűjtetnek gödörbe, mint a foglyok, és bezáratnak tömlöczbe, és sok napok után meglátogattatnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 23, 'És elpirul a hold, és megszégyenül a nap, mikor a seregek Ura uralkodik Sion hegyén és Jeruzsálemben: s vénei előtt dicsőség lészen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, 'Uram, te vagy Istenem, magasztallak, dícsérem nevedet! Mivel csodát cselekvél, örök tanácsaid hűség és igazság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, 'Mert a városból kőrakást csináltál, az erős városból romot, az idegenek palotáját olyanná tetted, hogy nincs többé város; soha örökké meg nem épül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, 'Ezért dicsőítnek téged erős népek, erőszakos pogányok városai félnek téged!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, 'Mert erőssége voltál a gyöngének, erőssége a szegénynek szorongásában; a szélvész ellen oltalom, árnyék a hévség ellen, mikor az erőszakosok haragja olyan volt, mint kőfalrontó szélvész.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, 'Mint hévséget száraz földön, megalázod az idegeneknek háborgását, mint a hévség sűrű felleg miatt, megszünt a pogányoknak éneke.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, 'És szerez a seregek Ura minden népeknek e hegyen lakodalmat kövér eledelekből, lakodalmat erős borból; velős, kövér eledelekből, megtisztult erős borból;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, 'S elveszi e hegyen a fátyolt, mely beboríta minden népeket, és a takarót, mely befödött vala minden népségeket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, 'Elveszti a halált örökre, és letörli az Úr Isten a könyhullatást minden orczáról: és népe gyalázatát eltávolítja az egész földről; mert az Úr szólott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, 'És szólnak ama napon: Ímé Istenünk, a kit mi vártunk és a ki megtart minket; ez az Úr, a kit mi vártunk, örüljünk és örvendezzünk szabadításában!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, 'Mert az Úr keze nyugszik e hegyen, és eltapostatik Moáb az ő földében, mint eltapostatik a szalma a ganaj levében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, 'És kiterjeszti kezeit abban, mint kiterjeszti az úszó, hogy ússzék; de az Úr megalázza kevélységét és kezei csalárdságát;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, 'És magas falaid erősségét lerontja, megalázza, a földre, porba dobja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, 'Ama napon ez éneket énekelik Júda földén: Erős városunk van nékünk, szabadítását adta kőfal és bástya gyanánt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, 'Nyissátok fel a kapukat, hogy bevonuljon az igaz nép, a hűség megőrzője.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, 'Kinek szíve reád támaszkodik, megőrzöd azt teljes békében, mivel Te benned bízik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, 'Bízzatok az Úrban örökké, mert az Úrban, Jehovában, örök kőszálunk van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, 'Mert meghorgasztá a magasban lakozókat: a magas várost, megalázá azt, megalázá azt a földig, és a porba dobta azt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, 'Láb tapodja azt, a szegény lábai, a gyöngék talpai!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, 'Az igaznak ösvénye egyenes, egyenesen készíted az igaznak útját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, 'Mi is vártunk Téged, ítéleted ösvényén, oh Uram! neved és emlékezeted után vágyott a lélek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, 'Szívem utánad vágyott éjszaka, az én lelkem is bensőmben Téged keresett, mivel ha ítéleteid megjelennek a földön, igazságot tanulnak a földnek lakosai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, 'Ha kegyelmet nyer a gonosz, nem tanul igazságot, az igaz földön is hamisságot cselekszik, és nem nézi az Úr méltóságát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, 'Uram! magas a Te kezed, de nem látják! de látni fogják, és megszégyenülnek, néped iránt való buzgó szerelmedet; és tűz emészti meg ellenségeidet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, 'Uram! Te adsz nékünk békességet, hisz minden dolgainkat megcselekedted értünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 13, 'Uram! mi Istenünk! urak parancsoltak nékünk kívüled; de általad dicsőítjük neved!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 14, 'A meghaltak nem élnek, az árnyak nem kelnek föl: ezért látogatád meg és vesztéd el őket, és eltörléd emlékezetöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 15, 'Megszaporítád e népet, Uram! megszaporítád e népet, magadat megdicsőítéd, kiterjesztetted a földnek minden határait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 16, 'Oh Uram! a szorongásban kerestek Téged, és halk imádságot mondtanak, mikor rajtuk volt ostorod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 17, 'Miként a terhes asszony, a ki közel a szűléshez, vajudik, felkiált fájdalmiban, előtted olyanok voltunk, Uram!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 18, 'Mint terhesek vajudtunk, de csak szelet szűltünk: szabadulása nem lőn e földnek, és nem hulltak el a föld kerekségének lakói.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 19, 'Megelevenednek halottaid és holttesteim fölkelnek: serkenjetek föl és énekeljetek, a kik a porban lakoztok, mert harmatod az élet harmata, és visszaadja a föld az árnyakat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 20, 'Menj be népem, menj be szobáidba, és zárd be ajtóidat utánad, és rejtsd el magad rövid szempillantásig, míg elmúlik a bús harag!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 21, 'Mert ímé az Úr kijő helyéről, hogy meglátogassa a föld lakóinak álnokságát, s felmutatja a föld a vért, és el nem fedi megöletteit többé!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, 'Ama napon meglátogatja az Úr kemény, nagy és erős kardjával Leviatánt, a futó kígyót, Leviatánt, a keringő kígyót, és megöli a sárkányt, mely a tengerben van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, 'Ama napon a színború szőlőről énekeljetek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, 'Én, az Úr, őrízem azt, minden szempillantásban öntözöm, hogy senki meg ne látogassa, éjjel-nappal megőrzöm azt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, 'Nincsen haragom, de ha tövis és gaz jő elém, csatára megyek ellene, és meggyújtom azt mind együtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, 'Avagy fogja meg erősségemet, kössön békét velem, békét kössön velem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, 'Jövendőben Jákób meggyökerezik, virágzik és virul Izráel, és betöltik a földnek színét gyümölcscsel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, 'Avagy az őt verőnek verése szerint verte őt? vagy ellenségei megöletteinek megölése szerint öletett-é meg?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, 'Mérték szerint ítélted őt, midőn elvetetted! Reájok fútt kemény lehelletével a keleti szél napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, 'Ezért így tisztíttatik el a Jákób hamissága, és épen ez a gyümölcse bűne elvételének, hogy olyanná teszi az oltárnak minden kövét, minők a széttört mészkövek: nem kelnek fel többé a berkek és naposzlopok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, 'Mert az erős város magánosan álland, üres és elhagyott hely, miként a puszta, ott legel a borjú és ott hever, és megemészti annak ágait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, 'És ha megszáradnak gallyai, összetöretnek, az asszonyok előjövén, megégetik azokat; mert értelem nélkül való e nép, ezért nem könyörül meg rajta Teremtője, és nem kegyelmez néki alkotója.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, 'És lesz ama napon: cséplést tart az Úr az Eufrátes folyóvizétől Égyiptom patakjáig, és ti egyenként összeszedettek, Izráel fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, 'És lesz ama napon: megfújják a nagy kürtöt, és eljőnek, a kik elvesztek Assiria földében és a kik kiűzettek Égyiptom földébe, és leborulnak az Úr előtt a szent hegyen, Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, 'Jaj Efraim részegei kevély koronájának és dicsőséges ékessége hervadó virágának, mely a bortól megverettek kövér völgye fején van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, 'Ímé, egy erős és hatalmas jő az Úrtól, mint jégfergeteg, veszedelmes szélvész, mint özönlő erős vizeknek áradása: földhöz veri kezével azt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, 'Lábbal tapodtatik meg Efraim részegeinek kevély koronája,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, 'És úgy jár dicsőséges ékességének hervadó virága, a mely a kövér völgynek fején van, mint a korai füge a gyümölcsszedés előtt, a melyet mihelyt valaki meglát, alig veszi kezébe, lenyeli.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, 'Ama napon a seregek Ura lesz ékes koronája és dicsőséges koszorúja népe maradékának;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, 'És ítéletnek lelke annak, a ki az ítélőszékben ül, és erősség azoknak, a kik visszanyomják a kapuig az ellenséget.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, 'De ezek is tántorognak a bor miatt, és szédülnek a részegítő italtól: pap és próféta tántorog részegítő ital miatt, a bor elnyelte őket, szédülnek a részegítő ital miatt, tántorognak a jövendőlátásban, és inognak az ítéletmondásban;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, 'Mert minden asztal telve undok okádással, úgy hogy hely sincs a nélkül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, 'Kit tanít tudományra? A tanítást kivel érteti meg? A tejtől elszakasztottakkal-é és a csecstől elválasztottakkal-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 10, 'Mivel parancsra új parancs, parancsra új parancs, szabályra új szabály, szabályra új szabály; itt egy kicsi, ott egy kicsi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 11, 'Ezért dadogó ajakkal és idegen nyelven fog szólni e néphez,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 12, 'Ő, a ki ezt mondá nékik: Ez a nyugalom, hogy nyugtassátok meg a megfáradottat, és ez a pihenés! És nem akarták hallani!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 13, 'És lőn nékik az Úr beszéde parancsra új parancs, parancsra új parancs, szabályra új szabály, szabályra új szabály; itt egy kicsi, ott egy kicsi; hogy járjanak és hátra essenek és összetöressenek és tőrbe jussanak és megfogassanak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 14, 'Ezért halljátok az Úrnak beszédét, csúfoló férfiak, a kik uralkodtok e népen, a mely Jeruzsálemben lakik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 15, 'Mert így szóltok: Frigyet kötöttünk a halállal, a sírral meg szövetséget csináltunk; az ostorozó áradat ha jő, nem ér el minket; mert a hazugságot választók oltalmunkul, és csalásba rejtezénk el!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 16, 'Ezért így szól az Úr Isten: Ímé, Sionban egy követ tettem le, egy próbakövet, drága szegletkövet, erős alappal, a ki benne hisz, az nem fut!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 17, 'És a jogosságot mérőkötéllé tevém, és az igazságot színlelővé, és jég söpri el a hazugság oltalmát, és vizek ragadják el a rejteket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 18, 'És eltöröltetik a halállal való frigyetek, és a sírral való szövetségtek meg nem áll; az ostorozó áradat ha eljő, eltapod titeket,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 19, 'S a hányszor eljő, elragad titeket; mert minden reggel eljő, nappal és éjszaka; borzalom megértetni e tanítást;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 20, 'Mert rövid lesz az ágy, hogy benne kinyujtózhassék, és a takaró szűk lesz az elrejtőzéskor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 21, 'Mert mint a Perázim hegyén, felkel az Úr, és mint Gibeon völgyében, megharagszik, hogy megtegye munkáját, a mely szokatlan lesz, és hogy cselekedje dolgát a mely hallatlan lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 22, 'És most ne csúfolódjatok, hogy köteleitek szorosabbak ne legyenek; mert elvégzett pusztítást hallottam az Úrtól, a seregek Urától, az egész föld felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 23, 'Vegyétek füleitekbe és halljátok szavam`, figyeljetek és hallgassátok beszédem`!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 24, 'Hát mindig szánt-é a szántó, hogy vessen, és barázdálja és boronálja-é földét?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 25, 'Nemde, mikor elegyengette színét, hint fekete köményt, és szór illatos köményt, s vet sorban búzát és árpát a kijelölt földbe, és tönkölyt a szélére?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 26, 'Így szoktatá őt rendre és tanítá Istene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 27, 'Mert nem cséplő szánkával csépelik a fekete köményt, és nem szekér kerekével tapodják az illatos köményt; a fekete köményt bottal verik ki, és az illatost pálczával;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 28, 'A búzát csépelik; de nem örökre csépli azt, és bár hajtja rajta szekere kerekét és lovait, de szét nem töreti.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 29, 'Ez is a seregek Urától származott: Ő ád csodás tanácsot és nagyságos bölcseséget!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, 'Jaj Árielnek, Árielnek, a városnak, a hol Dávid lakott! Esztendőt esztendőhöz adjatok, és forogjanak az ünnepek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, 'És én megszorítom Árielt, és lesz fájdalom és siralom, és lesz nékem, mint Áriel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, 'Körülveszlek táborral, és bezárlak tornyokkal, és erősségeket állatok ellened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, 'És megaláztatván, a földből szólsz és porból morog beszéded, szavad olyan lesz, mint halottidézőé, a földből, és porból sipog beszéded.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, 'Ellenségidnek sokasága olyan lesz, mint az apró por, és mint a repülő polyva az erőszakosok sokasága, és lesz hamar és hirtelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, 'A seregek Urától látogattatik meg, mennydörgéssel, földindulással, nagy zúgással, forgószéllel, viharral és emésztő tűzi lánggal;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, 'Mint éjjeli álomlátás, olyan lesz minden pogányoknak sokasága, a kik hadakoznak Áriel ellen, s a kik hadakoznak ellene és vára ellen, és őt megszorítják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, 'És lesz, mint mikor álmodik az éhező, és ímé eszik, és midőn fölserken, üres a hasa, és mint mikor álmodik a szomjazó, és ímé iszik, és midőn fölserken, ímé szomjas és lelke eped: így lesz minden pogányoknak sokasága, a kik hadakoznak Sion hegye ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, 'Ámuljatok és bámuljatok, vakítsátok magatokat és megvakultok! részegek, de nem bortól, tántorognak, de nem részegítő italtól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, 'Mert rátok önté az Úr a mély álomnak lelkét, és bezárta szemeiteket, a prófétákat, és fejeiteket, a nézőket befedezte;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, 'És lesz mind e látás néktek, mintegy bepecsételtetett írás beszédei, a melyet oda adnak egy írástudónak, mondván: Olvasd, kérlek, és ő szól: Nem tudom, mert bepecsételtetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 12, 'És ha e levelet annak adják, a ki nem tud írást, mondván: Olvasd el, kérlek! ő így szól: Nem tudok írást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 13, 'És szólt az Úr: Mivel e nép szájjal közelget hozzám, és csak ajkaival tisztel engem, szíve pedig távol van tőlem, úgy hogy irántam való félelmök betanított emberi parancsolat lőn:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 14, 'Ezért én is csodásan cselekszem ismét e néppel, nagyon csodálatosan, és bölcseinek bölcsesége elvész, és értelmeseinek értelme eltűnik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 15, 'Jaj azoknak, a kik az Úrtól mélységesen elrejtik tanácsukat, és a kik a sötétségben szoktak cselekedni, mondván: Ki lát minket és ki ismer minket?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 16, 'Mily együgyűek vagytok! Avagy a fazekas olyan, mint az agyag, hogy így szóljon a csinálmány csinálójának: Nem csinált engem! és az alkotmány ezt mondja alkotójának: Értelmetlen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 17, 'Nemde kevés idő multán a Libánon termőfölddé lesz, és a termőföld erdőnek tartatik?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 18, 'És meghallják ama napon a siketek az írás beszédeit, és a homályból és sötétből a vakoknak szemei látni fognak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 19, 'És nagy örömük lesz a szenvedőknek az Úrban, és a szegény emberek vígadnak Izráel Szentjében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 20, 'Mert a kegyetlen elveszett, és a csúfoló elpusztult, és kivágattak a hamisságnak minden őrei,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 21, 'Kik az embert elítélik egy szóért, és tőrt vetnek annak, a ki őket a kapuban megfeddi, és elejtik csalárdul az igazat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 22, 'Ezért így szól az Úr Jákób házáról, Ő, a ki megváltá Ábrahámot: Nem szégyenül meg többé Jákób, és nem sáppad meg többé az ő orczája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 23, 'Ha látni fogják gyermekei kezeim munkáját közöttük, megszentelik nevemet, megszentelik Jákób Szentjét, és félik Izráel Istenét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 24, 'És megismerik a tévelygő lelkűek az értelmet, és a kik zúgolódnak, tanulságot tanulnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, 'Jaj a pártos fiaknak, így szól az Úr, a kik tervet visznek véghez nélkülem, és szövetséget kötnek, de nem lelkem által, hogy bűnre bűnt halmozzanak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, 'A kik Égyiptomba szállanak alá, és számat nem kérdezik meg, hogy meneküljenek a Faraónak oltalmába, és Égyiptom árnyékába rejtőzködjenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, 'És lesz néktek a Faraó oltalma szégyentekre, és az elrejtőzködés Égyiptom árnyékában gyalázatotokra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, 'Mert már Zoánban voltak fejedelmei, és követei Hánesig érkezének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, 'Megszégyenülnek mind a nép miatt, a mely nem használ nékik, a mely nem segít és nem használ, sőt szégyenökre és gyalázatukra lesz!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, 'Jövendölés dél barma ellen: A nyomor és szorongatás földén keresztül, a honnan nőstény és hím oroszlán és viperák és szárnyas sárkányok jőnek ki; viszik szamárcsikók hátán gazdagságukat, és a tevéknek púpján kincsöket a népnek, a mely pedig nem használ.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, 'Hitvány és üres Égyiptom segítsége, ezért nevezem őt nagyszájúnak, a ki veszteg ül,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, 'Most menj, írd ezt táblára nálok, és jegyezd föl könyvbe ezt, hogy megmaradjon az utolsó napra bizonyságul örökre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, 'Mert pártütő nép ez, apát megtagadó fiak, fiak, kik nem akarják hallani az Úr törvényét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, 'Kik ezt mondják a látóknak: Ne lássatok; és a prófétáknak: Ne prófétáljatok nékünk igazat, beszéljetek kedvünk szerint valókat, prófétáljatok csalárdságokat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, 'Hagyjátok el az útat, térjetek le már ez ösvényről, vigyétek el előlünk Izráelnek Szentjét!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, 'Azért így szól Izráel Szentje: Mivel megútáltátok e beszédet, és bíztok a nyomorgatásban és a hamisságban, és ezekre támaszkodtok:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, 'Azért e bűn olyan lesz tinéktek, mint a leesendő falhasadék, a mely már kiáll a magas kőfalon, a melynek aztán nagy hirtelen jő el romlása;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 14, 'És romlása olyan lesz, mint a fazekasok edényének romlása, a mely kimélés nélkül eltöretik, és nem találni töredéki közt oly cserepet, a melyen tűzhelyről tüzet lehetne vinni, avagy vizet meríteni a tócsából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 15, 'Mert így szól az Úr Isten, Izráelnek Szentje: Megtérve és megnyugodva megmaradhattatok volna; csöndességben és reménységben erősségtek lett volna; de ti nem akarátok;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 16, 'Hanem ezt mondátok: Nem, sőt lóra ülvén, futunk; ezért futnotok kell; és gyors paripán elvágtatunk; ezért gyorsak lesznek üldözőitek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 17, 'Ezer fut egynek riasztására, ötnek riasztására mind elfuttok, mígnem úgy maradtok, mint egy szál fenyő a hegytetőn, mint egy zászló a halmon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 18, 'S azért vár az Úr, hogy könyörüljön rajtatok, és azért felséges ő, hogy megkegyelmezzen néktek, mert az ítélet Istene az Úr; boldogok mindazok, a kik Őt szolgálják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 19, 'Mert te nép, mely Sionon Jeruzsálemben lakol, nem fogsz te sírni többé, bizton könyörül rajtad Ő kiáltásod szavára, mihelyt meghallja, megfelel néked;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 20, 'És ad néktek az Úr kenyeret a keserűségben, és a nyomorban vizet, és nem kell többé elrejtőzködniök tanítóidnak, hanem szemeid tanítóidra néznek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 21, 'És füleid meghallják a kiáltó szót mögötted: ez az út, ezen járjatok; ha jobbra és ha balra elhajoltok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 22, 'És megútáljátok megezüstözött bálványaitokat és megaranyozott képeiteket; kiszórod őket, mint az undokságot: ki innen! szólsz nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 23, 'És ad esőt a magra, a melylyel a földet beveted, és a kenyér, a föld termése, bő és tápláló lesz, és széles mezőn legelnek nyájaid ama napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 24, 'A barmok és a szamarak, a melyek a földet szántják, sózott abrakkal élnek, a melyet megszórtak lapáttal és villával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 25, 'És lesznek minden magas hegyen és emelkedettebb halmon patakok, folyamok a nagy öldöklés napján, mikor a tornyok leomlanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 26, 'És a holdnak fénye olyan lesz, mint a napnak fénye, és a napnak fénye hétszer nagyobb lesz, olyan, mint hét napnak napfénye; ama napon, a melyen az Úr beköti népe romlását, és vereségének sebét meggyógyítja!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 27, 'Ímé, az Úr neve jő messziről, haragja ég és sötét gomolygó füstje; ajkai rakvák haraggal, és nyelve, mint emésztő tűz!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 28, 'Lehellete, mint megáradott patak, a mely torkig ér, hogy megrostálja a népeket pusztulás rostájában, és tévelygés zabláját vesse a népségek szájába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 29, 'És fölzendül éneketek, mint a szent ünnepnek éjszakáján, és örvendez szívetek, mint azé, a ki sípolva megy az Úr hegyére, Izráel kőszálához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 30, 'És megzendíti az Úr dicsőséges szavát, karjának lesujtását megmutatja megbúsult haragjában és emésztő tűz lángjában, vízáradással, zivatarral és jégeső kövével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 31, 'Mert az Úrnak szavától megretten Assiria, veri azt akkor vesszővel;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 32, 'És a büntető vessző minden sujtását, a melyet az Úr mérend reá, dobokkal és cziterákkal fogjátok kisérni, és Ő kezét fel-felemelvén, harczol ellene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 33, 'Mert készen van a szörnyű tűzhely régen, készen áll az már a királynak is, mélyen és szélesen csinálta azt, máglyájában tűz és fa bőven; az Úr fuvallata gyújtja meg azt, mint kénköves patak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, 'Jaj nékik, a kik Égyiptomba mennek segítségért, lovakra támaszkodnak, és a szekerek sokaságában bíznak, és a nagyon erős lovagokban; és nem néznek Izráelnek Szentjére, és az Urat nem keresik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, 'De Ő is bölcs, és hoz veszedelmet, és beszédeit nem változtatja meg; hanem fölkel a gonoszoknak háza ellen és a bűnt cselekvők segítsége ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, 'Hiszen Égyiptom ember és nem Isten, és lovai hús és nem lélek, és ha az Úr kinyújtja kezét, megtántorodik a segítő, és elesik a megsegített, és együtt mind elvesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, 'Mert így szólott az Úr hozzám: A mint mormol az oroszlán és az oroszlánkölyök zsákmánya mellett, a mely ellen összehívatnak a pásztorok sereggel, és szavoktól ő meg nem retten, és meg nem ijed sokaságuktól: így száll alá a seregek Ura, hogy hadakozzék a Sion hegyén és halmán!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, 'Mint repeső madarak, úgy oltalmazza a seregek Ura Jeruzsálemet, oltalmazván megszabadítja, kimélvén megmenti.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, 'Térjetek vissza hát hozzá, a kitől oly nagyon elpártolátok, Izráelnek fiai!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, 'Mivel ama napon megveti mindenki ezüst bálványait és arany bálványait, a melyeket kezeitek csináltak néktek bűnre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, 'És elesik Assiria, nem férfiú kardjától, és nem ember kardja emészti meg azt; és fut egy kard előtt, és ifjai adófizetők lesznek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, 'És kőszála félelem miatt menekül, és a zászlótól fejedelmei elfutnak, szól az Úr, a kinek tüze Sionban van, és kemenczéje Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, 'Ímé, igazság szerint uralkodik a király, és a fejedelmek fők lesznek az ítélettételben;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, 'Olyan lesz mindegyik, mint a rejtek szél ellen, mint oltalom zivatar ellen, mint patakok száraz vidéken, mint nagy kőszál árnyéka a szomjúhozó földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, 'És nem lesznek zárva többé a látóknak szemei, és a hallók fülei figyelmeznek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, 'A hebehurgyák szíve ismerni tanul, és a dadogóknak nyelve gyorsan és világosan szól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, 'Nem nevezik a bolondot többé nemesnek, és a csalárdot sem hívják nagylelkűnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, 'Mert a bolond csak bolondot beszél, és az ő szíve hamisságot forral, hogy istentelenséget cselekedjék, és szóljon az Úr ellen tévelygést, hogy az éhező lelkét éhen hagyja, és a szomjazó italát elvegye.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, 'A csalárdnak eszközei csalárdok, ő álnokságot tervel, hogy elveszesse az alázatosokat hazug beszéddel, ha a szegény igazat szólna is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, 'De a nemes nemes dolgokat tervel, és a nemes dolgokban meg is marad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, 'Ti gondtalan asszonyok, keljetek fel, halljátok szavam`, és ti elbizakodott leányzók, vegyétek füleitekbe beszédem`!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, 'Kevés idő multán megháborodtok ti elbizakodottak, mert elvész a szüret, és gyümölcsszedés sem lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, 'Reszkessetek, ti gondtalanok, rettenjetek meg, ti elbizakodottak; vetkezzetek mezítelenre és övezzétek fel ágyékaitokat gyászruhával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 12, 'Gyászolják az emlőket, a szép mezőket, a termő szőlőtőket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 13, 'Népemnek földét tüske, tövis verte fel, és az örvendő városnak minden öröm-házait;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 14, 'A paloták elhagyatvák, a város zaja elnémult, torony és bástya barlangokká lettek örökre, hol a vadszamár kedvére él, a nyájak meg legelnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 15, 'Míglen kiöntetik reánk a lélek a magasból, és lészen a puszta termőfölddé, és a termőföld erdőnek tartatik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 16, 'És lakozik a pusztában jogosság, és igazság fog ülni a termőföldön;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 17, 'És lesz az igazság műve békesség, és az igazság gyümölcse nyugalom és biztonság mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 18, 'Népem békesség hajlékában lakozik, biztonság sátraiban, gondtalan nyugalomban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 19, 'De jégeső hull és megdől az erdő, és a város elsülyedve elsülyed!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 20, 'Oh boldogok ti, a kik minden vizek mellett vettek, és szabadon eresztitek a barmok és szamarak lábait!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, 'Jaj néked pusztító és el nem pusztított, te csalárd, a kit még meg nem csaltak! Ha bevégzed a pusztítást, el fogsz pusztíttatni; ha készen leszel csalárdságoddal, téged fognak megcsalni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, 'Uram, könyörülj rajtunk! Téged várunk; légy karjuk reggelenként, és szabadítónk a szorongatásnak idején!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, 'Egy zendülő szózattól elfutnak a népek; ha te felemelkedel, elszélednek a népségek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, 'És elpusztítják zsákmánytokat sáska pusztításával, szöcske-ugrással ugrálnak reá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, 'Felmagasztaltatott az Úr, mert magasságban lakozik, betölté Siont ítélettel és igazsággal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, 'És békés lesz a te időd, gazdag boldogságban, bölcseségben és tudományban; az Úr félelme lesz kincse.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, 'Ímé, erőseik ott künn kiáltanak, a békesség követei keservesen sírnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, 'Puszták az ösvények, megszünt az úton járó; megszegte a frigyet, lenézte a városokat, nem gondolt az emberrel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, 'Sírt, meghervadt a föld, a Libánon megszégyenült, ellankadt; olyan lett Sáron, mint egy puszta, és lombtalan Básán és Karmel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, 'Most fölkelek, így szól az Úr, most föltámadok, most fölemelkedem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, 'Fogantok szalmát, szültök polyvát, dühötök tűz, megemészt titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, 'A népek égetett mészszé lesznek, levágott tövisekké; tűzben hamvadnak el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, 'Halljátok meg távol valók, a mit cselekedtem, és tudjátok meg közel valók az én hatalmamat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, 'Megrettentek a bűnösök Sionban, félelem fogja el a gazokat: ki lakhatik közülünk megemésztő tűzzel, ki lakhatik közülünk örök hőséggel?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, 'A ki igazságban jár és egyenesen beszél, a ki megveti a zsarolt nyereséget, a ki kezeit rázván, nem vesz ajándékot, a ki fülét bedugja, hogy véres tervet ne halljon, és szemeit befogja, hogy gonoszt ne lásson:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, 'Az magasságban lakozik, kőszálak csúcsa a bástyája, kenyerét megkapja, vize el nem fogy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, 'A királyt ékességében látják szemeid; látnak széles országot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, 'Szíved elgondolja a mult félelmét: hol az író, hol a mérlegelő, hol a tornyok összeírója?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, 'A gőgös népet nem látod, a homályos, érthetetlen ajkú népet, dadogó nyelve meg nem érthető.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, 'Lássad Siont, ünnepeinknek városát, szemeid nézzék Jeruzsálemet, mint nyugalom hajlékát, mint sátort, mely nem vándorol, melynek szegei soha ki nem húzatnak, s kötelei soha el nem szakadnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, 'Sőt az Úr, a dicsőséges lesz ott nékünk folyók és széles vizek gyanánt, a melyekbe nem jő evezős hajó, és nehéz gálya rajtok át nem megy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, 'Mert az Úr a mi bíránk, az Úr a mi vezérünk, az Úr a mi királyunk, Ő tart meg minket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 23, 'Megtágultak köteleid, árbóczfájok alapját nem tartják erősen, vitorlát nem feszítenek: akkor sok rablott prédát osztanak, még a sánták is zsákmányt vetnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 24, 'És nem mondja a lakos: beteg vagyok! a nép, a mely benne lakozik, bűnbocsánatot nyer.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, 'Jőjjetek népek és halljátok, nemzetségek figyeljetek, hallja a föld és teljessége, e föld kereksége és minden szülöttei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, 'Mert haragszik az Úr minden népekre, és megbúsult minden ő seregökre; megátkozá, halálra adta őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, 'Megöltjeik temetetlen maradnak, hulláik bűze felszáll, és hegyek olvadnak meg vérök miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, 'Elporhad az ég minden serege, és az ég mint írás egybehajtatik, és minden serege lehull, miként lehull a szőlő levele és a fügefáról a hervadó lomb.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, 'Mert megrészegült fegyverem az égben, és ímé leszáll Edomra, átkom népére, ítéletre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, 'Az Úr fegyvere telve vérrel, megrakva kövérrel, bárányoknak és bakoknak vérével, a kosoknak vesekövérével; mert áldozatja lesz az Úrnak Boczrában, és nagy öldöklés Edom földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, 'Elhullnak a bivalyok is velök, és a tulkok a bikákkal, és megrészegedik földük vértől, és poruk borítva lesz kövérrel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, 'Mert bosszúállás napja ez az Úrnak, a megfizetés esztendeje Sionnak ügyéért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, 'És változnak patakjai szurokká, és pora kénkővé, és lészen földe égő szurokká.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, 'Éjjel és nappal el nem alszik, örökre fölgomolyog füstje, nemzetségről nemzetségre pusztán marad, soha örökké senki át nem megy rajta;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, 'És örökségül bírándja azt ökörbika, sündisznó; és gém és holló lakja azt, és fölvonják rá a pusztaság mérőkötelét és a semmiségnek köveit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, 'Nemesei nem választanak többé királyt, és minden fejedelmei semmivé lesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, 'És fölveri palotáit tövis, csalán és bogács a bástyáit, és lesz sakálok hajléka és struczok udvara.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, 'És találkozik vadmacska a vadebbel, és a kisértet társára talál, csak ott nyugszik meg az éji boszorkány és ott lel nyughelyet magának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, 'Oda rak fészket a bagoly és tojik és ül tojáson és költ árnyékában, csak ott gyűlnek együvé a sasok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, 'Keressétek meg majd az Úr könyvében, és olvassátok: ezeknek egy hijjok sem lesz, egyik a másiktól el nem marad; mert az Ő szája parancsolta, és az Ő lelke gyűjté össze őket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, 'Ő vetett sorsot köztök, és keze osztá ki azt nékik mérőkötéllel; örökre bírni fogják azt, nemzetségről nemzetségre lakoznak abban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, 'Örvend a puszta és a kietlen hely, örül a pusztaság és virul mint őszike.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, 'Virulva virul és örvend ujjongva, a Libánon dicsősége adatott néki, Karmel és Sáron ékessége; meglátják ők az Úrnak dicsőségét, Istenünk ékességét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, 'Erősítsétek a lankadt kezeket, és szilárdítsátok a tántorgó térdeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, 'Mondjátok a remegő szívűeknek: legyetek erősek, ne féljetek! Ímé, Istenetek bosszúra jő, az Isten, a ki megfizet, Ő jő, és megszabadít titeket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, 'Akkor a vakok szemei megnyílnak, és a süketek fülei megnyittatnak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, 'Akkor ugrándoz, mint szarvas a sánta, és ujjong a néma nyelve, mert a pusztában víz fakad, és patakok a kietlenben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, 'És tóvá lesz a délibáb, és a szomjú föld vizek forrásivá; a sakálok lakhelyén, a hol feküsznek, fű, nád és káka terem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, 'És lesz ott ösvény és út, és szentség útának hívatik: tisztátalan nem megy át rajta; hisz csak az övék az; a ki ez úton jár, még a bolond se téved el;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, 'Nem lesz ott oroszlán, és a kegyetlen vad nem jő fel reá, nem is található ott, hanem a megváltottak járnak rajta!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, 'Hisz az Úr megváltottai megtérnek, és ujjongás között Sionba jönnek; és örök öröm fejökön, vígasságot és örömöt találnak; és eltűnik fájdalom és sóhaj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, 'És lőn Ezékiás király tizennegyedik esztendejében, feljöve Szanhérib assir király Júdának minden erős városai ellen, és azokat megvevé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, 'És elküldé Assiria királya Rabsakét Lákisból Jeruzsálembe, Ezékiás királyhoz nagy sereggel, ki is megállt a felső tó folyásánál, a ruhamosók mezejének útján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, 'És kijöve hozzá Eljákim a Hilkiás fia az udvarnagy, és Sebna az íródeák, és Jóák Asáfnak fia az emlékíró.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, 'És mondá nékik Rabsaké: Mondjátok meg kérlek Ezékiásnak, így szól a nagy király, Assiria királya: Micsoda bizodalom ez, melyre támaszkodol?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, 'Azt mondom, hogy csak szóbeszéd az, hogy ész és erő van nálatok a háborúhoz; no hát kiben bízol, hogy ellenem feltámadál?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, 'Ímé te e megtört nádszálban bízol, Égyiptomban, melyre a ki támaszkodik, tenyerébe megy és átfúrja azt; ilyen a Faraó, Égyiptomnak királya, minden benne bízóknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, 'És ha azt mondod nékem: az Úrban, a mi Istenünkben bízunk: vajjon nem Ő-é az, a kinek magaslatait és oltárait elrontotta Ezékiás, és ezt mondá Júdának és Jeruzsálemnek: Ez előtt az oltár előtt hajoljatok meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, 'Most azért harczolj meg, kérlek, az én urammal, az assir királylyal, és adok néked két ezer lovat, ha ugyan tudsz lovagokat ültetni reájok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, 'Miképen állasz ellene egyetlen helytartónak is, a ki legkisebb az uram szolgái közt? De hisz Égyiptomban van bizalmad, a szekerekért és lovagokért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, 'És most talán az Úr nélkül jöttem én e földre, hogy elpusztítsam azt? Az Úr mondá nékem: Menj a földre, és pusztítsd el azt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, 'És mondá Eljákim és Sebna és Jóák Rabsakénak: Szólj, kérünk, szolgáidhoz arám nyelven, mert értjük azt, és ne zsidóul szólj hozzánk, e kőfalon levő nép füle hallatára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, 'És mondá Rabsaké: Avagy a te uradhoz, vagy te hozzád küldött engem az én uram, hogy ezeket elmondjam? és nem az emberekhez-é, a kik ülnek a kőfalon, hogy egyék ganéjokat és igyák vizeletöket veletek együtt?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, 'És odaálla Rabsaké, és kiálta felszóval zsidóul, és mondá: Halljátok a nagy királynak, Assiria királyának beszédit!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 14, 'Ezt mondja a király: Meg ne csaljon benneteket Ezékiás, mert nem szabadíthat meg titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 15, 'És ne biztasson titeket Ezékiás az Úrral, mondván: Kétségtelen megszabadít az Úr minket, nem adatik e város az assiriai király kezébe!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 16, 'Ezékiásra ne hallgassatok, mert azt mondja Assiria királya: Tegyetek velem szövetséget és jőjjetek ki hozzám, és akkor kiki ehetik szőlőjéből és az ő olajfájáról, és ihatja kútjának vizét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 17, 'Míg eljövök és elviszlek titeket oly földre, minő a ti földetek, gabona és must földére, kenyér és szőlő földére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 18, 'Rá ne szedjen titeket Ezékiás, mondván: Az Úr megszabadít minket! Avagy megszabadították-é a népek istenei, kiki az ő földét Assiria királyának kezéből?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 19, 'Hol vannak Hamáth és Arphádnak istenei? hol Sefarvaimnak istenei? talán bizony megmentették Samariát kezemből?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 20, 'Kicsoda e földek minden istenei között, a ki megszabadította volna földét kezemből, hogy az Úr megszabadítsa Jeruzsálemet az én kezemből?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 21, 'Ők pedig hallgatának, és egy szót sem feleltek, mert a király parancsolá így, mondván: Ne feleljetek néki!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 22, 'Akkor elmenének Eljákim a Hilkiás fia az udvarnagy, és Sebna az íródeák, és Jóák Asáf fia az emlékíró, Ezékiáshoz meghasogatott ruhákban, és hírül adák néki a Rabsaké beszédeit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, 'És lőn, hogy meghallá Ezékiás, a király, meghasogatá ruháit, gyászba öltözött, és bement az Úr házába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, 'És elküldé Eljákimot az udvarnagyot, és Sebnát az íródeákot, és a papoknak gyászruhába öltözött véneit Ésaiáshoz, Ámós fiához, a prófétához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, 'Kik mondának néki: Így szól Ezékiás: nyomornak, büntetésnek és káromlásnak napja e nap, mert szülésig jutottak a fiak, és erő nincs a szüléshez!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, 'Talán meghallja az Úr, a te Istened, a Rabsaké beszédeit, a kit elküldött az ő ura, az assiriai király, hogy káromolja az élő Istent, és szidalmazza azon beszédekkel, a melyeket hallott az Úr, a te Istened; és te könyörögj a maradékért, a mely megvan!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, 'Így menének el Ezékiás király szolgái Ésaiáshoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, 'És monda nékik Ésaiás: Így szóljatok uratoknak: ezt mondja az Úr: Ne félj a beszédektől, a melyeket hallottál, a melyekkel szidalmaztak engem az assiriai király szolgái.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, 'Ímé, én oly lelket adok beléje, hogy hírt hallván, térjen vissza földére, és elejtem őt fegyver által az ő földében!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, 'Rabsaké pedig visszatérvén, találá az assiriai királyt Libna ellen harczolni, mivel hallotta volt, hogy Lákistól elindult.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, 'És meghallván Tirháka, Kús királya felől e hírt: eljött, hogy ellened harczoljon; ezt meghallván, követeket külde Ezékiáshoz, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, 'Így szóljatok Ezékiáshoz, Júda királyához: Meg ne csaljon Istened, a kiben bízol, mondván: nem adatik Jeruzsálem az assiriai király kezébe!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, 'Hiszen te hallottad, mit műveltek Assiria királyai minden országokkal, eltörölvén azokat, és te megszabadulnál?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, 'Hát megszabadíták-é azokat a népek istenei, a melyeket eleim elpusztítának? Gózánt, Háránt, Resefet és Telassárban Eden fiait?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, 'Hol van Hamáth királya és Arphádnak királya, Sefarvaim városának királya, Héna és Ivva?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, 'És elvevé Ezékiás a levelet a követek kezéből, és olvasá azt, és felmenvén az Úr házába, kiterjeszté Ezékiás azt az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, 'És könyörge Ezékiás az Úrhoz, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, 'Seregeknek Ura, Izráel Istene, ki a Kerubokon ülsz! Te, csak Te vagy a föld minden országainak Istene, Te teremtéd a mennyet és a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, 'Hajtsd ide Uram füledet és halljad, nyisd meg Uram szemeidet és lássad! Halld meg Szanhéribnek minden beszédit, a melyeket izent az élő Isten káromlására!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, 'Bizony, Uram, Assiria királyai elpusztítottak minden országokat és azoknak földjét,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, 'És isteneiket tűzbe veték, mert nem istenek voltak, hanem emberi kéznek csinálmánya, fa és kő; így veszthették el azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, 'És most Uram, mi Istenünk! szabadíts meg minket az ő kezéből, hogy megtudják a föld minden országai, hogy Te vagy, Uram, Isten egyedül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, 'És külde Ésaiás, Ámós fia Ezékiáshoz, mondván: Így szól az Úr, Izráel Istene: mivel hozzám könyörögtél Szanhérib miatt, Assiria királya miatt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, 'Ez a beszéd, a melyet az Úr felőle szól: Megútál téged, gúnyt űz belőled Sionnak szűz leánya, fejét rázza utánad Jeruzsálem leánya;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, 'Kit káromoltál és szidalmazál, és ki ellen emeltél szót, hogy oly magasra látsz? Izráel Szentje ellen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, 'Szolgáid által megkáromlád az Urat, és ezt mondád: Temérdek szekeremmel fölmentem e hegyek magaslatára, a Libánon csúcsára, és kivágom magas czédrusait, válogatott cziprusait, és behatolok végső magaslatába és kertjének erdejébe!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, 'Én ástam és vizet ittam, és kiszáraztom lábam talpával Égyiptom minden folyóit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, 'Hát nem hallottad-é, hogy régtől fogva én tevém ezt, az őskor napjaiban elvégzém ezt, és most előhozám, hogy puszta kőrakássá tégy erős városokat?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, 'És lakóik elájultak és megrendültek és megszégyenültek, és lőnek mint a mező füve és gyönge zöldség, és mint a virág a háztetőn, mint szárba nem indult vetés!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, 'Ülésedet, kimentedet, bejöttödet tudom, és ellenem való haragodat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, 'Ellenem való haragodért, és mert kevélységed fülembe jutott, vetem orrodba horgomat és szádba zabolámat, és visszaviszlek az úton, a melyen jövél!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, 'S ez legyen jelül néked: ez évben ugartermést esztek és a másik évben sarjut, és a harmadik évben vessetek, arassatok és szőlőt ültessetek, és egyétek gyümölcsét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, 'Júda házának maradványa pedig, a mely megszabadult, ismét gyökeret ver alul, és gyümölcsöt terem felül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, 'Mert Jeruzsálemből megy ki a maradék és a maradvány Sion hegyéről; a seregek Urának buzgó szerelme művelendi ezt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, 'Azért így szól az Úr Assiria királyáról: Nem jő be e városba, nyilat sem lő reá, és nem szállja meg paizszsal azt, és töltést sem készít ellene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, 'Az úton, a melyen jött, visszatér, de e városba be nem jő, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, 'És megoltalmazom e várost, hogy megtartsam azt én magamért és szolgámért, Dávidért!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, 'Akkor kijött az Úrnak angyala, és levágott az assir táborban száznyolczvanötezeret, és midőn reggel az emberek felköltek, ímé azok mindnyájan holt hullák valának!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, 'Elindula azért és ment és visszatért Szanhérib, az assiriai király, és lakozék Ninivében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, 'És lőn, hogy mikor imádkozék, Nisróknak, az ő istenének templomában, fiai: Adramélek és Saréser levágák őt karddal; és ezek Ararát földére menekülvén, fia, Esárhaddon uralkodék helyette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, 'Azon napokban halálos betegségbe esék Ezékiás, és eljött hozzá Ésaiás Ámós fia, a próféta, és mondá néki: Ezt mondja az Úr: rendeld el házadat, mert meghalsz és meg nem gyógyulsz!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, 'És Ezékiás arczczal a falnak fordulván, könyörge az Úrnak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, 'És monda: Oh Uram, emlékezzél meg arról, hogy én előtted jártam, igazságban és egész szívvel, és hogy a mi jó előtted, azt műveltem! és sírt Ezékiás keservesen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, 'És lőn az Úr beszéde Ésaiáshoz, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, 'Menj el, és mondd Ezékiásnak: így szól az Úr, Dávidnak, atyádnak Istene: Hallottam imádságodat, láttam könyeidet, ímé, még napjaidhoz tizenöt esztendőt adok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, 'És az assiriai király kezéből megszabadítlak téged és e várost; megoltalmazom e várost!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, 'Ez legyen jel néked az Úrtól, hogy teljesíti azt az Úr, a mit mondott:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, 'Ímé, visszatérítem az árnyékot, azokon a fokokon, a melyeken az Akház napóráján a nap már átvonult, tíz fokkal; és visszatért az árnyék tíz fokkal azokon a fokokon, a melyeken már átvonult.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, 'Ezékiásnak, Júda királyának följegyzése, mikor megbetegedett, és betegségéből fölgyógyult.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, 'Én azt mondám: hát napjaimnak nyugalmában kell alászállanom a sír kapuihoz, megfosztva többi éveimtől!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, 'Mondám: nem látom az Urat, az Urat az élők földében, nem szemlélek embert többé a nyugalom lakói közt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, 'Porsátorom lerontatik, és elmegy tőlem, mint a pásztor hajléka! Összehajtám, mint a takács, életemet; hiszen levágott a fonalról engem; reggeltől estig végzesz velem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, 'Reggelig nyugton vártam; mint oroszlán, úgy törte össze minden csontjaimat; reggeltől estig végzesz velem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, 'Mint a fecske és a daru, sipogtam, nyögtem mint a galamb, szemeim a magasságba meredtek: Uram! erőszak rajtam, szabadíts meg!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, 'Mit mondjak? hogy szólott nékem és Ő azt meg is cselekedé! Nyugton élem le éveimet lelkem keserűsége után!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, 'Oh Uram! ezek által él minden! és ezekben van teljességgel lelkem élete. Te meggyógyítasz és éltetsz engemet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, 'Ímé, áldásul volt nékem a nagy keserűség, és Te szeretettel kivontad lelkemet a pusztulásnak verméből, mert hátad mögé vetetted minden bűneimet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, 'Mert nem a sír dicsőít Téged, és nem a halál magasztal Téged, hűségedre nem a sírverembe szállók várnak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, 'Ki él, ki él, csak az dicsőít Téged, mint ma én! Az atya a fiaknak hirdeti hűségedet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, 'Az Úr szabadított meg engemet; azért énekeljük énekimet éltünk minden napjaiban az Úrnak házában!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, 'Akkor mondá Ésaiás, hogy vegyenek egy fügekalácsot, és dörzsöljék rá a fekélyre, hogy meggyógyuljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, 'És mondá Ezékiás: Mi lesz a jele, hogy fölmegyek az Úr házába?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, 'Abban az időben levelet és ajándékot küldött a babilóniai király, Meródák Baladán, Baladán fia, Ezékiás királyhoz, mert hallotta, hogy beteg volt és meggyógyult.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, 'És örvende rajtok Ezékiás, és megmutatá nékik tárházát, az ezüstöt, az aranyat, a fűszereket, a drága kenetet, s egész fegyvertárát, és mindent, a mi kincsei közt található volt. Semmi nem volt, a mit meg nem mutatott volna nékik Ezékiás házában és egész birodalmában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, 'És eljött Ésaiás, a próféta, Ezékiás királyhoz, és monda néki: Mit szólának ez emberek, és honnan jöttek te hozzád? És monda Ezékiás: Messze földről jöttek hozzám, Bábelből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, 'És monda: Mit látának házadban? És monda Ezékiás: Mindent láttak, a mi csak házamban van, semmi nincs, a mit meg nem mutattam volna nékik kincseim közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, 'És monda Ésaiás Ezékiásnak: Halld a seregek Urának beszédét:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, 'Ímé napok jőnek, és elvitetik, valami házadban van, és a mit csak e mai napig gyűjtöttek eleid, Bábelbe; nem marad semmi meg, ezt mondja az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, 'És fiaid közül, a kik tőled származnak, a kiket te nemzesz, el fognak hurczolni, és lesznek komornyikok Bábel királyának palotájában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, 'Akkor monda Ezékiás Ésaiásnak: Jóságos az Úrnak beszéde, a melyet te szóltál! és monda: Csak napjaimban legyen béke és állandóság!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, 'Vígasztaljátok, vígasztaljátok népemet, így szól Istenetek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, 'Szóljatok Jeruzsálem szívéhez, és hirdessétek néki, hogy vége van nyomorúságának, hogy bűne megbocsáttatott; hiszen kétszeresen sujtotta őt az Úr keze minden bűneiért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, 'Egy szó kiált: A pusztában készítsétek az Úrnak útát, ösvényt egyengessetek a kietlenben a mi Istenünknek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, 'Minden völgy fölemelkedjék, minden hegy és halom alászálljon, és legyen az egyenetlen egyenessé és a bérczek rónává.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, 'És megjelenik az Úr dicsősége, és minden test látni fogja azt; mert az Úr szája szólt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, 'Szózat szól: Kiálts! és monda: Mit kiáltsak? Minden test fű, és minden szépsége, mint a mező virága!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, 'Megszáradt a fű, elhullt a virág, ha az Úrnak szele fuvallt reá; bizony fű a nép.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, 'Megszáradt a fű, elhullt a virág; de Istenünk beszéde mindörökre megmarad!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, 'Magas hegyre menj fel, örömmondó Sion! emeld föl szódat magasan, örömmondó Jeruzsálem! emeld föl, ne félj! mondjad Júda városinak: Ímhol Istenetek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, 'Ímé, az Úr Isten jő hatalommal, és karja uralkodik! Ímé, jutalma vele jő, és megfizetése Ő előtte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, 'Mint pásztor, nyáját úgy legelteti, karjára gyűjti a bárányokat és ölében hordozza, a szoptatósokat szelíden vezeti.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, 'Ki mérte meg markával a vizeket, és ki mértéklé az egeket arasszal, a föld porát ki foglalá mérczébe, és a hegyeket ki tette körtefontra, és a halmokat a mérlegserpenyőbe?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, 'Kicsoda igazgatta az Úr lelkét, és ki oktatta Őt, mint tanácsosa?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, 'Kivel tanácskozott, hogy felvilágosítsa Őt, és tanítsa Őt igazság ösvényére, és tanítsa ismeretre, és oktassa Őt az értelem útára?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, 'Ím a népek, mint egy csöpp a vederben, és mint egy porszem a mérlegserpenyőben, olyanoknak tekintetnek; ímé a szigeteket mint kis port emeli föl!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, 'És a Libánon nem elég a tűzre, és vada sem elég az áldozatra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, 'Minden népek semmik Ő előtte, a semmiségnél és ürességnél alábbvalóknak tartja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, 'És kihez hasonlítjátok az Istent, és minő képet készítetek Ő róla?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 19, 'A bálványt a mester megönti, és az ötvös megaranyozza azt, és olvaszt ezüst lánczot reá;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 20, 'A ki szegény ily áldozatra, oly fát választ, a mely meg nem rothad; okos mestert keres, hogy oly bálványt állítson, a mely nem ingadoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 21, 'Hát nem tudjátok és nem hallottátok-é, hát nem hirdettetett néktek eleitől fogva, hát nem értettétek-é meg a föld fundamentomait?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 22, 'Ki ül a föld kereksége fölött, a melynek lakói mint sáskák előtte, ki az egeket kiterjeszti mint egy kárpitot, és kifeszíti, mint a sátort, lakásra;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 23, 'Ki a fejedelmeket semmivé teszi, és a föld biráit hiábavalókká változtatja;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 24, 'Még alig plántáltattak, még alig vettetének el, alig vert gyökeret a földben törzsük, és Ő csak rájok fuvall, és kiszáradnak és őket, mint polyvát, forgószél ragadja el:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 25, 'Kihez hasonlíttok hát engem, hogy hasonló volnék? szól a Szent.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 26, 'Emeljétek föl a magasba szemeiteket, és lássátok meg, ki teremté azokat? Ő, a ki kihozza seregöket szám szerint, mindnyáját nevén szólítja; nagy hatalma és erőssége miatt egyetlen híjok sincsen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 27, 'Miért mondod Jákób és szólsz ekként Izráel: Elrejtetett az én útam az Úrtól, és ügyemmel nem gondol Istenem?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 28, 'Hát nem tudod-é és nem hallottad-é, hogy örökkévaló Isten az Úr, a ki teremté a föld határait? nem fárad és nem lankad el; végére mehetetlen bölcsesége!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 29, 'Erőt ad a megfáradottnak, és az erőtlen erejét megsokasítja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 30, 'Elfáradnak az ifjak és meglankadnak, megtántorodnak a legkülönbek is;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 31, 'De a kik az Úrban bíznak, erejök megújul, szárnyra kelnek, mint a saskeselyűk, futnak és nem lankadnak meg, járnak és nem fáradnak el!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, 'Hallgassatok reám, ti szigetek, és a népek vegyenek új erőt, közelgjenek, majd szóljanak, együtt hadd szálljunk perbe!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, 'Ki támasztá fel azt keletről, a kit igazságban hív az ő lábához? A népeket kezébe adja és királyok felett uralkodóvá teszi, kardjával mint port szórja szét, mint repülő polyvát kézíve által!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, 'Kergeti őket, békességgel vonul az úton, a melyen lábaival nem járt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, 'Ki tette és vitte végbe ezt? A ki elhívja eleitől fogva a nemzetségeket: én, az Úr, az első és utolsókkal is az vagyok én!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, 'Látták a szigetek és megrémülének, a földnek végei reszkettek, közelegtek és egybegyűltek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, 'Kiki társát segíti, és barátjának ezt mondja: Légy erős!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, 'És bátorítja a mester az ötvöst, és a kalapácscsal simító azt, a ki az ülőt veri; így szól a forrasztásról: jó az, és megerősíti szegekkel, hogy meg ne mozduljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, 'De te Izráel, én szolgám, Jákób, a kit én elválasztottam, Ábrahámnak, az én barátomnak magva;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, 'Te, a kit én a föld utolsó részéről hoztalak és véghatárairól elhívtalak, és ezt mondám néked: Szolgám vagy te, elválasztottalak és meg nem útállak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, 'Ne félj, mert én veled vagyok; ne csüggedj, mert én vagyok Istened; megerősítelek, sőt megsegítlek, és igazságom jobbjával támogatlak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, 'Ímé, megszégyenülnek és meggyaláztatnak, a kik fölgerjednek ellened, semmivé lesznek és elvesznek, a kik veled perlekednek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, 'Keresed őket és meg nem találod a veled versengőket; megsemmisülnek teljesen, a kik téged háborgatnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, 'Mivel én vagyok Urad, Istened, a ki jobbkezedet fogom, és a ki ezt mondom néked: Ne félj, én megsegítelek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, 'Ne félj, férgecske Jákób, maroknyi Izráel, én megsegítlek, szól az Úr, a te megváltód, Izráelnek Szentje!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 15, 'Ímé, én teszlek éles, új cséplőhengerré, a melynek két éle van; hegyeket csépelj és zúzz össze, és a halmokat pozdorjává tegyed.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 16, 'Te szórd, és a szél vigye el őket, és elszéleszsze őket a forgószél, és te örülsz az Úrban, és dicsekedel Izráelnek Szentjében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 17, 'A nyomorultak és szegények keresnek vizet, de nincs, nyelvök a szomjúságban elepedt: én, az Úr meghallgatom őket, én, Izráel Istene, nem hagyom el őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 18, 'Kopasz hegyeken folyókat nyitok és a rónák közepén forrásokat; a pusztát vizek tavává teszem és az aszú földet vizeknek forrásivá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 19, 'A pusztában czédrust, akáczot nevelek és mirtust és olajfát, plántálok a kietlenben cziprust, platánt, sudarczédrussal együtt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 20, 'Hogy lássák, megtudják, eszökbe vegyék és megértsék mindnyájan, hogy az Úrnak keze mívelte ezt, és Izráel Szentje teremtette ezt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 21, 'Hozzátok ide ügyeteket, szól az Úr, adjátok elő erősségeiteket, így szól Jákób királya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 22, 'Adják elő és jelentsék meg nékünk, a mik történni fognak; a mik először lesznek, jelentsétek meg, hogy eszünkbe vegyük és megtudjuk végöket, vagy a jövendőket tudassátok velünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 23, 'Jelentsétek meg, mik lesznek ezután, hogy megtudjuk, hogy ti Istenek vagytok; vagy hát míveljetek jót vagy gonoszt, hogy mérkőzzünk és majd lássuk együtt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 24, 'Ímé, ti semmiből valók vagytok, és dolgotok is semmiből való; útálat az, a ki titeket szeret.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 25, 'Feltámasztám északról, és eljött napkelet felől; hirdeti nevemet, és tapodja a fejedelmeket, mint az agyagot, és mint a fazekas a sarat tapossa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 26, 'Ki jelenté meg ezt eleitől fogva, hogy megtudnók? vagy régen, hogy ezt mondanók: Igaz? De nem jelenté meg, de nem tudatá senki, nem hallá szavatokat senki sem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 27, 'Sionnak először én hirdetém, ímé itt vannak a tanúk, és örömmondót adtam Jeruzsálemnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 28, 'És néztem és nem volt senki, ezek közül nem volt tanácsadó, hogy megkérdezzem őket és feleljenek nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 29, 'Ímé, mindnyájan semmik ők, semmiség cselekedetök, szél és hiábavalóság képeik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, 'Ímé az én szolgám, a kit gyámolítok, az én választottam, a kit szívem kedvel, lelkemet adtam ő belé, törvényt beszél a népeknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, 'Nem kiált és nem lármáz, és nem hallatja szavát az utczán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, 'Megrepedt nádat nem tör el, a pislogó gyertya belet nem oltja ki, a törvényt igazán jelenti meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, 'Nem pislog és meg nem reped, míg a földön törvényt tanít, és a szigetek várnak tanítására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, 'Így szól az Úr Isten, a ki az egeket teremté és kifeszíté, és kiterjeszté termésivel a földet, a ki lelket ád a rajta lakó népnek, és leheletet a rajta járóknak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, 'Én, az Úr, hívtalak el igazságban, és fogom kezedet, és megőrizlek és népnek szövetségévé teszlek, pogányoknak világosságává.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, 'Hogy megnyisd a vakoknak szemeit, hogy a foglyot a tömlöczből kihozzad, és a fogházból a sötétben ülőket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, 'Én vagyok az Úr, ez a nevem, és dicsőségemet másnak nem adom, sem dicséretemet a bálványoknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, 'A régiek ímé beteltek, és most újakat hirdetek, mielőtt meglennének, tudatom veletek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, 'Énekeljetek az Úrnak új éneket, és dicséretét a földnek határairól, ti, a tenger hajósai és teljessége, a szigetek és azoknak lakói.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, 'Emeljék fel szavokat a puszta és annak városai, a faluk, a melyekben Kédár lakik, ujjongjanak a kősziklák lakói, a hegyeknek tetejéről kiáltsanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, 'Adják az Úrnak a dicsőséget, és dicséretét hirdessék a szigetekben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 13, 'Az Úr, mint egy hős kijő, és mint hadakozó felkölti haragját, kiált, sőt rivalg és ellenségein erőt vesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 14, 'Régtől fogva hallgattam, néma voltam, magamat megtartóztatám: most mint a szülő nő nyögök, lihegek és fúvok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 15, 'Elpusztítok hegyeket és halmokat, és megszáraztom minden fűvöket, szigetekké teszek folyamokat, és tavakat kiszáraztok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 16, 'A vakokat oly úton vezetem, a melyet nem ismernek, járatom őket oly ösvényeken, a melyeket nem tudnak; előttök a sötétséget világossággá teszem, és az egyenetlen földet egyenessé; ezeket cselekszem velök, és őket el nem hagyom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 17, 'Meghátrálnak és mélyen megszégyenülnek, a kik a bálványban bíznak, a kik ezt mondják az öntött képnek: Ti vagytok a mi isteneink!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 18, 'Oh, ti süketek, halljatok, és ti vakok, lássatok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 19, 'Kicsoda vak, ha nem az én szolgám? és olyan süket, mint az én követem, a kit elbocsátok? Ki olyan vak, mint a békességgel megajándékozott, és olyan vak, mint az Úr szolgája?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 20, 'Sokat láttál, de nem vetted eszedbe; fülei nyitvák, de nem hall.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 21, 'Az Úr igazságáért azt akarta, hogy a törvényt nagygyá teszi és dicsőségessé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 22, 'De e nép kiraboltatott és eltapodtatott, bilincsbe verve tömlöczben mindnyájan, és fogházakban rejtettek el, prédává lettek és nincs szabadító; ragadománynyá lettek és nincsen, a ki mondaná: add vissza!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 23, 'Ki veszi ezt közületek fülébe? a ki figyelne és hallgatna ezután!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 24, 'Ki adta ragadományul Jákóbot és Izráelt a prédálóknak? Avagy nem az Úr-é, a ki ellen vétkezénk, és nem akartak járni útain és nem hallgattak az Ő törvényére?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 25, 'Ezért ontá ki reá búsulásának haragját és a had erejét; körülte lángolt az, de ő nem értett; és égett benne, de nem tért eszére!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, 'És most, oh Jákób, így szól az Úr, a te Teremtőd, és a te alkotód, Izráel: Ne félj, mert megváltottalak, neveden hívtalak téged, enyém vagy!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, 'Mikor vizen mégy át, én veled vagyok, és ha folyókon, azok el nem borítnak, ha tűzben jársz, nem égsz meg, és a láng meg nem perzsel téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, 'Mert én vagyok az Úr, a te Istened, Izráelnek Szentje, a te megtartód, adtam váltságodba Égyiptomot, Kúst és Sebát helyetted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, 'Mivel kedves vagy az én szemeimben, becses vagy és én szeretlek: embereket adok helyetted, és népeket a te életedért:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, 'Ne félj, mert én veled vagyok, napkeletről meghozom magodat, és napnyugotról egybegyűjtelek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 6, 'Mondom északnak: add meg; és délnek: ne tartsd vissza, hozd meg az én fiaimat messzünnen, és leányimat a földnek végéről,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 7, 'Mindent, a ki csak az én nevemről neveztetik, a kit dicsőségemre teremtettem, a kit alkottam és készítettem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 8, 'Hozd ki a vak népet, a melynek szemei vannak, és a süketeket, a kiknek füleik vannak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 9, 'Minden népek gyűljenek egybe, és seregeljenek össze a népségek: ki hirdethet közülök ilyet? Vagy a régieket tudassák velünk, állítsák elő tanuikat, hogy igazuk legyen, hogy ezek hallván, ezt mondják: Igaz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 10, 'Ti vagytok az én tanuim, így szól az Úr; és szolgám, a kit elválasztottam, hogy megtudjátok és higyjetek nékem és megértsétek, hogy én vagyok az, előttem Isten nem alkottatott, és utánam nem lesz!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 11, 'Én, én vagyok az Úr, és rajtam kivül nincsen szabadító!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 12, 'Én hirdettem, és megtartottam, és megjelentettem, és nem volt idegen isten köztetek, és ti vagytok az én tanuim, így szól az Úr, hogy én Isten vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 13, 'Mostantól fogva is én az leszek, és nincs, a ki az én kezemből kimentsen; cselekszem, és ki változtatja azt meg?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 14, 'Így szól az Úr, a ti megváltótok, Izráel Szentje. Ti értetek küldöttem el Bábelbe, és leszállítom mindnyájokat, mint menekülőket a Káldeusokkal együtt vídámságuk hajóiba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 15, 'Én az Úr vagyok, szent Istenetek, Izráelnek teremtője, királyotok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 16, 'Így szól az Úr, a ki a tengeren utat csinál, és a hatalmas vizeken ösvényt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 17, 'A ki kihozott szekeret és lovat, sereget és vitézt; együtt hevernek ottan, nem kelnek föl, kialudtak, mint gyertyabél elhamvadának!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 18, 'Ne emlékezzetek a régiekről, és az előbbiekről ne gondolkodjatok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 19, 'Ímé, újat cselekszem; most készül, avagy nem tudjátok még? Igen, a pusztában utat szerzek, és a kietlenben folyóvizeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 20, 'Dicsőítni fog engem a mező vada, a sakálok és struczok, hogy vizet szereztem a pusztában; a kietlenben folyóvizeket, hogy választott népemnek inni adjak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 21, 'A nép, a melyet magamnak alkoték, hirdesse dicséretemet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 22, 'És még sem engem hívtál segítségül Jákób, hanem megfáradtál én bennem Izráel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 23, 'Nem adtad nékem égőáldozatul bárányaidat, és áldozataiddal nem dicsőítettél engem; nem terheltelek ételáldozattal, és tömjénnel nem fárasztottalak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 24, 'Nem vettél pénzen nékem jóillatú nádat, és áldozataid kövérével jól nem tartottál, csak bűneiddel terhelél, vétkeiddel fárasztál engemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 25, 'Én, én vagyok, a ki eltörlöm álnokságaidat enmagamért, és bűneidről nem emlékezem meg!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 26, 'Juttasd eszembe, no pereljünk együtt, beszéld el, hogy igaznak találtassál!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 27, 'Az első atyád vétkezett, és tanítóid elpártoltak tőlem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 28, 'Ezért én is megfertőztettem a szent fejedelmeket, és veszedelemre adám Jákóbot, és gyalázatra Izráelt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, 'És most hallgass Jákób, én szolgám, és Izráel, a kit én elválasztottam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, 'Így szól az Úr, teremtőd és alkotód anyád méhétől fogva, a ki megsegít: Ne félj, én szolgám Jákób, és te igaz nép, a kit elválasztottam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, 'Mert vizet öntök a szomjúhozóra, és folyóvizeket a szárazra; kiöntöm lelkemet a te magodra, és áldásomat a te csemetéidre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, 'És nevekednek mint fű között, és mint a fűzfák vizek folyásinál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, 'Ez azt mondja: én az Úré vagyok, amaz Jákób nevét emlegeti, és a másik önkezével írja: az Úré vagyok, és hízelegve Izráel nevét említi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, 'Így szól az Úr, Izráelnek királya és megváltója, a seregeknek Ura: Én vagyok az első, én az utolsó, és rajtam kivül nincsen Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, 'És ki hirdetett hozzám hasonlóan? jelentse meg és hozza azt elém, mióta e világ népét teremtém; és jelentsék meg a közeli és távoli jövőt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, 'Ne féljetek és ne rettegjetek! Hát nem mondtam-é meg és nem jelentém előre? Ti vagytok tanuim! Hát van-é rajtam kivül Isten? Nincs kőszál, nem tudok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, 'A bálványok csinálói mind hiábavalók, és kedvenczeik mit sem használnak, és tanuik nem látnak és nem tudnak, hogy megszégyenüljenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'Ki alkotott istent, és bálványt ki öntött? a mely semmit sem használ!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, 'Ímé, minden barátaik megszégyenülnek, és a mesterek magok is emberek; gyűljenek össze mind és álljanak elő; féljenek, szégyenüljenek meg együtt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, 'A kovács fejszét készít, és munkálkodik a szénnél, és alakítja azt pőrölylyel, és munkálja azt erős karjával, és megéhezik és ereje nincsen, és vizet sem iszik és elfárad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, 'Az ács mérőzsinórt von, és lefesti azt íróvesszővel, és meggyalulja azt, a czirkalommal alakítja, és csinálja azt férfiú formájára, ember ékességére, hogy házában lakjék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'Czédrusfát vág magának, tölgy- és cserfát hoz, és válogat az erdő fáiban, fenyőt plántál, a melyet az eső fölnevel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, 'Azokból az ember tüzet gerjeszt, vesz belőlök és melegszik, meggyújtja és kenyeret süt; sőt istent is csinál abból és imádja, bálványt készít és előtte leborul;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'Felét tűzben megégeti, felénél húst eszik: pecsenyét süt és megelégszik, és aztán melengeti magát és szól: Bezzeg melegem van, tűznél valék!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, 'Maradékából istent készít, bálványát; leborulva imádja azt és könyörög hozzá, és így szól: Szabadíts meg, mert te vagy istenem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'Nem tudnak és nem értenek, mert bekenvék szemeik és nem látnak, és szívök nem eszmél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, 'És nem veszi eszébe, nincs ismerete és értelme, hogy mondaná: Felét tűzben megégetém és kenyeret sütöttem annak szenénél, sütöttem húst és megettem; és maradékából útálatosságot csináljak-é, és leboruljak a fa-galy előtt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'Ki hamuban gyönyörködik, megcsalt szíve vezette félre azt, hogy meg ne szabadítsa lelkét és ezt mondja: Hát nem hazugság van-é jobbkezemben?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, 'Oh emlékezzél meg Jákób ezekről és Izráel, mert az én szolgám vagy te, én alkottalak téged, én szolgám vagy, Izráel! nem feledlek el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, 'Eltöröltem álnokságaidat, mint felleget, és mint felhőt bűneidet; térj én hozzám, mert megváltottalak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, 'Örüljetek egek, mert az Úr végbe vitte, kiáltsatok földnek mélységei, ujjongva énekeljetek hegyek, erdő és benne minden fa; mert megváltá az Úr Jákóbot, és Izráelben megdicsőíti magát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, 'Így szól az Úr, megváltód és alkotód anyád méhétől fogva: Én vagyok az Úr, a ki mindent cselekszem, a ki az egeket egyedül kifeszítem, és kiszélesítem a földet magamtól;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, 'Ki a hazugok jeleit megrontja, és a varázslókat megbolondítja, a bölcseket megszégyeníti, és tudományukat bolondsággá teszi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, 'A ki szolgája beszédét beteljesíti, és véghez viszi követei tanácsát, a ki így szól Jeruzsálemnek: Lakjanak benne! és Júda városainak: Megépíttessenek! és romjait felállatom!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, 'Ki ezt mondja a mélységnek: Száradj ki! és kiapasztom folyóvizeidet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 28, 'Ki Czírusnak ezt mondja: Pásztorom! ki véghez viszi minden akaratomat, és ezt mondja Jeruzsálemnek: Megépíttessék! és a templomnak: Alapja vettessék!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, 'Így szól az Úr felkentjéhez, Czírushoz, kinek jobbkezét megfogám, hogy meghódoltassak előtte népeket, és a királyok derekának övét megoldjam, ő előtte megnyissam az ajtókat, és a kapuk be ne zároltassanak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, 'Én menéndek előtted, és az egyenetleneket megegyenesítem, az érczajtókat összetöröm, és leütöm a vaszárakat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, 'Néked adom a sötétségnek kincseit és a rejtekhelyek gazdagságait, hogy megtudjad, hogy én vagyok az Úr, a ki téged neveden hívtalak, Izráel Istene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, 'Az én szolgámért, Jákóbért, és elválasztott Izráelemért neveden hívtalak el, szeretettel szólítálak, noha nem ismerél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, 'Én vagyok az Úr és több nincs, rajtam kivül nincs Isten! felöveztelek téged, bár nem ismerél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, 'Hogy megtudják napkelettől és napnyugattól fogva, hogy nincsen több rajtam kivül; én vagyok az Úr és több nincsen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, 'Ki a világosságot alkotom és a sötétséget teremtem, ki békességet szerzek és gonoszt teremtek; én vagyok az Úr, a ki mindezt cselekszem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, 'Egek harmatozzatok onnan felül, és a felhők folyjanak igazsággal, nyiljék meg a föld és viruljon fel a szabadulás, és igazság sarjadjon fel vele együtt; én az Úr teremtettem azt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, 'Jaj annak, a ki alkotójával perbe száll, holott cserép a föld többi cserepeivel! Vajjon mondja-é az agyag alkotójának: Mit csinálsz? és csinálmányod ezt: Nincsenek kezei?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, 'Jaj annak, a ki atyjának mondja: Miért nemzesz? és az asszonynak: Miért szülsz?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, 'Így szól az Úr, Izráelnek Szentje és Teremtője: Kérdezzétek meg a jövendőt tőlem, fiaimat és kezeim munkáját csak bízzátok reám!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, 'Én alkotám a földet, és az embert rajta én teremtém, én terjesztém ki kezeimmel az egeket, és minden seregöket én állatám elő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, 'Én támasztottam őt fel igazságban, és minden útait egyengetem, ő építi meg városomat, és foglyaimat elbocsátja, nem pénzért, sem ajándékért, szóla a seregek Ura!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, 'Így szól az Úr: Égyiptom gyűjtött kincse és Kús nyeresége és a nagy termetű Szabeusok hozzád mennek és tieid lesznek, téged követnek, békókban járnak, előtted leborulnak és hozzád könyörögnek: Csak közted van az Isten és nincsen több Isten!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, 'Bizony Te elrejtőzködő Isten vagy, Izráelnek Istene, szabadító!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, 'Szégyent vallanak és gyalázatot mind, egyetemben gyalázatban járnak a bálványok faragói;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'És Izráel megszabadul az Úr által örök szabadulással, nem vallotok szégyent és gyalázatot soha örökké;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, 'Mert így szól az Úr, a ki az egeket teremté; Ő az Isten, a ki alkotá a földet és teremté azt és megerősíté; nem hiába teremté azt, hanem lakásul alkotá: Én vagyok az Úr és több nincsen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 19, 'Nem titkon szóltam, a sötétség földének helyén; nem mondtam Jákób magvának: hiába keressetek engem! én, az Úr, igazságot szólok, és megjelentem, a mik igazak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 20, 'Gyűljetek egybe és jőjjetek elő, közelegjetek mind, a kik a népek közül megszabadultatok; nem tudnak semmit, a kik bálványuk fáját hordják, és könyörögnek oly istenhez, a ki meg nem tart!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 21, 'Jelentsétek meg és hozzátok elő, sőt egyetemben tanácskozzanak: ki mondta meg ezt régtől fogva és jelenté meg előre? Vajjon nem én, az Úr? És nincs több Isten nálam, igaz Isten és megtartó nincs kívülem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 22, 'Térjetek én hozzám, hogy megtartassatok földnek minden határai, mert én vagyok az Isten, és nincsen több!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 23, 'Magamra esküdtem és igazság jött ki számból, egy szó, mely vissza nem tér: hogy minden térd nékem hajol meg, rám esküszik minden nyelv!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 24, 'Csak az Úrban van, így szólnak felőlem, minden igazság és erő, Ő hozzá mennek, és megszégyenülnek mindazok, a kik reá haragusznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 25, 'Az Úrban igazul meg és dicsekszik Izráelnek egész magva!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, 'Ledől Bél, elesik Nebó, oktalan barmokra kerülnek szobraik, és miket ti hordoztatok, felrakatnak, terhéül a megfáradott állatnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, 'Elesnek, összerogynak együtt, nem menthetik meg a terhet; és ők magok fogságba mennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, 'Hallgassatok rám, Jákób háza és Izráel házának minden maradéka, a kiket magamra raktam anyátok méhétől fogva, és hordoztalak születésetek óta;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, 'Vénségtekig én vagyok az, és megőszüléstekig én visellek; én teremtettem és én hordozom, én viselem és megszabadítom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'Kihez hasonlíttok engem, és kivel tesztek egyenlővé? És kivel vettek egybe, hogy hasonlók volnánk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, 'Kitöltik az aranyat az erszényből, és ezüstöt mérnek a mértékkel, és ötvöst fogadnak, hogy abból istent csináljon; meghajolnak, leborulnak előtte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, 'Vállukra veszik azt és hordozzák, majd állványára helyezik és veszteg áll, helyéről meg nem mozdul, ha kiáltasz is hozzá, nem felel, nyomorúságodból nem szabadít meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, 'Emlékezzetek meg erről, és legyetek erősek, vegyétek eszetekbe, pártütők!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, 'Emlékezzetek meg a messze régi dolgokról, hogy én vagyok Isten és nincsen több; Isten vagyok, és nincs hozzám hasonlatos.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, 'Ki megjelentem kezdettől fogva a véget, és előre azokat, a mik még meg nem történtek, mondván: tanácsom megáll, és véghez viszem minden akaratomat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, 'Ki elhívom napkeletről a sast, meszsze földről tanácsom férfiát; nem csak szóltam, ki is viszem, elvégezem, meg is cselekszem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, 'Hallgassatok reám, kemény szívűek, a kik távol vagytok az igazságtól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 13, 'Elhoztam igazságomat, nincs messze, és az én szabadításom nem késik, Sionban lesz szabadításom, és Izráelen dicsőségem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, 'Szállj le és ülj a porba, Babilon szűz leánya, ülj a földre királyi szék nélkül, te a Káldeusok leánya, mert nem hívnak többé téged gyöngének és elkényeztetettnek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, 'Vedd a malmot és őrölj lisztet, född fel fátyolodat, emeld föl a hosszú ruhát, född fel czombodat és menj át a folyókon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, 'Födöztessék föl meztelenséged és láttassék meg szemérmed; bosszút állok és embert nem kímélek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, 'Így szól a mi Megváltónk, seregeknek Ura az Ő neve, Izráel Szentje!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, 'Ülj némán és menj a sötétre, te a Káldeusok leánya, mert nem hívnak többé téged országok úrnőjének!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, 'Fölgerjedtem volt népem ellen; megfertőztettem örökségemet és kezedbe adtam azt: te nem cselekedtél velök irgalmasságot, az öregre nehéz igát vetettél!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, 'És ezt mondád: Örökre úrnő leszek! úgy hogy ezekre nem is gondolál, és nem emlékeztél meg annak végéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, 'És most halld meg ezt, bujálkodó, a ki bátorságban ülsz, a ki ezt mondja szívében: Én vagyok és nincs senki több, nem ülök özvegységben, és a gyermektelenséget nem ismerem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, 'És mind e kettő eljő reád nagy hamar egy napon: gyermektelenség és özvegység, teljességökben jőnek el reád, noha gazdag vagy a varázslásban, és sok nagyon igéző szózatod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, 'Gonoszságodban bíztál, és ezt mondád: Nem lát senki engem! Bölcseséged és tudományod csalt meg téged, és ezt mondád szívedben: Én vagyok és nincs senki több.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 11, 'Azért jő te reád a gonosz, a melynek keletkezését nem tudod, és romlás sújt le rád, a melyet meg nem engesztelhetsz, és hirtelen jő pusztulás reád, nem is tudod!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 12, 'No állj elő hát igéző szózatiddal és varázslásodnak sokaságával, a melyekkel ifjúságodtól fogva vesződtél, talán segíthetsz valamit, talán visszariaszthatod a veszedelmet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 13, 'Tanácsaid sokaságában megfáradtál; no álljanak elő és tartsanak meg az égnek vizsgálói, a kik a csillagokat nézik, a kik megjelentik az újholdak napján, hogy mi jövend reád.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 14, 'Ímé, olyanok lettek, mint a polyva, tűz emészté meg őket, nem mentik meg életöket a lángból, még szén sem marad belőlök melegülésre, sem körülülhető parázs!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 15, 'Így járnak azok, a kikkel vesződtél; és a kik kereskedő társaid voltak ifjúságodtól fogva, futnak, kiki a maga útján; senki nem segít néked!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, 'Halljátok ezt Jákób háza, a kik Izráel nevéről neveztettek, és Júda forrásából származának, a kik az Úr nevére esküsznek, és Izráel Istenét emlegetik; de nem híven és nem igazán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, 'Mert a szent várostól nevezik magokat, és Izráel Istenéhez támaszkodnak, a kinek neve seregeknek Ura!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, 'Mik eddig történtek, előre megjelentém, szám hirdeté és tudatá azokat, gyorsan véghez vivém, és bekövetkezének,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, 'Mert tudtam, hogy te kemény vagy, és vasinakból van nyakad és homlokod ércz:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, 'Tehát előre megjelentém néked, mielőtt bekövetkezett, tudtodra adtam, hogy ezt ne mondd: Faragott képem mívelé ezeket, bálványom és öntött képem parancsolá ezeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, 'Hallottad volt, és most lásd mindezt; avagy ti nem tesztek-é erről bizonyságot? Mostantól fogva újakat tudatok veled: titkoltakat, a melyeket nem tudtál;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, 'Mostan rendeltettek el és nem régen, és ezelőtt nem hallottál felőlök, hogy ezt ne mondd: Ímé, tudtam én azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, 'Nem is hallottad, nem is tudtad, füled sem vala nyitva régen, mivel tudtam, hogy nagyon hűtelen vagy, és pártütőnek hívatál anyád méhétől fogva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, 'Nevemért elhalasztom haragomat, és dicséretemért fékezem magamat veled szemben, hogy ki ne vágjalak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, 'Ímé, megtisztítottalak, de nem úgy, mint ezüstöt, megpróbáltalak a nyomor kemenczéjében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, 'Enmagamért, enmagamért cselekszem; mert hogyan szentségteleníttetnék meg nevem?! És dicsőségemet másnak nem adom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, 'Hallgass rám Jákób és Izráel, én elhívottam, én vagyok az első és én az utolsó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, 'Hiszen kezem veté e föld alapját, és jobbom terjeszté ki az egeket, ha én szólítom őket, mind itt állnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, 'Gyűljetek egybe mind, és halljátok meg: ki jelenté meg közülök ezeket? az, kit az Úr szeret, elvégzi akaratját Bábelen, és karja lészen a Káldeusokon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, 'Én, én szóltam, és őt el is hívtam, elhoztam őt, és szerencsés lesz útja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 16, 'Közelgjetek hozzám, halljátok ezt, nem szóltam eleitől fogva titkon! mióta ez történik, ott vagyok! És most az Úr Isten engem küldött, és az ő lelkét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 17, 'Így szól az Úr, Megváltód, Izráelnek Szentje: Én vagyok az Úr, Istened, ki tanítlak hasznosra, és vezetlek oly úton, a melyen járnod kell.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 18, 'Vajha figyelmeztél volna parancsolataimra! olyan volna békességed, mint a folyóvíz, és igazságod, mint a tenger habjai;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 19, 'És olyan volna magod, mint a tengernek fövénye, és méhednek gyümölcsei, mint annak kövecskéi; nem vágatnék ki és nem pusztulna el neve orczám elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 20, 'Menjetek ki Bábelből, fussatok el Káldeából ujjongásnak szavával! jelentsétek meg, tudassátok ezt, terjesszétek a föld végső határáig; mondjátok: Megváltotta az Úr szolgáját, Jákóbot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 21, 'Nem szomjaznak, bárha pusztaságon vezeti is őket: kősziklából vizet fakaszt nékik, és meghasítja a sziklát és víz ömöl belőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 22, 'Nincs békesség, így szól az Úr, az istenteleneknek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, 'Hallgassatok reám, ti szigetek, és figyeljetek távol való népek: anyám méhétől hívott el az Úr, anyámnak szíve alatt már emlékezett nevemről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, 'Hasonlóvá tevé számat az éles kardhoz, keze árnyékában rejtett el engem, és fényes nyíllá tett engemet, és tegzébe zárt be engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, 'És mondá nékem: Szolgám vagy te, Izráel, a kiben én megdicsőülök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, 'És én mondám: Hiába fáradoztam, semmire és haszontalan költöttem el erőmet; de az Úrnál van ítéletem, és jutalmam Istenemnél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, 'És most így szól az Úr, a ki engem anyám méhétől szolgájává alkotott, hogy Jákóbot Ő hozzá megtérítsem és hogy Izráel hozzá gyűjtessék; hiszen tisztelt vagyok az Úr szemeiben és erősségem az én Istenem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, 'Így szól: Kevés az, hogy nékem szolgám légy, a Jákób nemzetséginek megépítésére és Izráel megszabadultjainak visszahozására: sőt a népeknek is világosságul adtalak, hogy üdvöm a föld végéig terjedjen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, 'Így szól az Úr, Izráel megváltója, Szentje, a megvetett lelkűhöz, a nép undorához, a zsarnokok szolgájához: Látjátok királyok! és majd fölkelnek, fejedelmek, és leborulnak az Úrért, a ki hű, Izráel Szentjéért, a ki téged elválasztott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, 'Így szól az Úr: Jókedvem idején én meghallgattalak, és a szabadulás napján segítettelek; megtartlak és nép szövetségévé teszlek, hogy megépítsd a földet, és kioszd az elpusztult örökségeket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, 'Így szólván a foglyoknak: Jőjjetek ki! és azoknak, a kik sötétben ülnek: Lépjetek elő! Az utakon legelnek, és minden halmokon legelőjük lesz:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, 'Nem éheznek, nem szomjúhoznak, nem bántja őket délibáb és a nap; mert a ki rajtok könyörült, vezeti őket, és őket vizek forrásaihoz viszi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, 'És teszem minden hegyemet úttá, és ösvényeim magasak lesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, 'Ímé, ezek messziről jönnek ímé, amazok észak és a tenger felől, és amazok Sinnek földéről!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, 'Ujjongjatok egek, és föld örvendezz, ujjongva énekeljetek hegyek; mert megvígasztalá népét az Úr, és könyörül szegényein!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, 'És szól Sion: Elhagyott az Úr engem, és rólam elfeledkezett az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, 'Hát elfeledkezhetik-é az anya gyermekéről, hogy ne könyörüljön méhe fián? És ha elfeledkeznének is ezek: én te rólad el nem feledkezem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, 'Ímé, az én markaimba metszettelek fel téged, kőfalaid előttem vannak szüntelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, 'Elősietnek fiaid, rombolóid és pusztítóid eltávoznak belőled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, 'Emeld fel köröskörül szemeidet, és lássad, mindnyájan egybegyűlnek, hozzád jönnek. Élek én, így szól az Úr, hogy fölrakod mindnyájokat, mint ékszert, és felkötöd, mint menyasszony.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, 'Mert romjaid és pusztaságaid és elpusztult földed, mindez szűk lesz most a lakosságnak, és messze távoznak elpusztítóid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, 'Gyermektelenségednek fiai még ezt mondják majd füled hallatára: Szoros e hely nékem, menj el, hogy itt lakhassam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, 'És te így szólsz szívedben: Ki szűlte nékem ezeket? hisz én gyermektelen és terméketlen voltam, fogoly és számkivetett; és ezeket ki nevelte föl? Ímé, én egyedül maradtam meg; ezek hol voltak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 22, 'Így szól az Úr Isten: Ímé, fölemelem kezemet a népekhez, és előttök zászlómat felállatom, és elhozzák fiaidat ölükben, és leányaid vállukon hordoztatnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 23, 'És királyok lesznek dajkálóid, fejedelmi asszonyaik dajkáid, arczczal a földre borulnak előtted és lábaid porát nyalják; és megtudod, hogy én vagyok az Úr, kit a kik várnak, meg nem szégyenülnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 24, 'Elvétethetik-é a préda az erőstől, és megszabadulhatnak-é az igazak foglyai?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 25, 'Igen, így szól az Úr, az erőstől elvétetnek a foglyok is, és megszabadul a kegyetlen zsákmánya, és háborgatóidat én háborítom meg, és én tartom meg fiaidat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 26, 'És etetem nyomorgatóiddal az önnön húsokat, és mint a musttól, véröktől megrészegednek, és megtudja minden test, hogy én vagyok az Úr; megtartód és megváltód, Jákóbnak erős Istene!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, 'Így szól az Úr: Hol van anyátok elválólevele, a melylyel őt elbocsátám? vagy hol van egy kölcsönadóim közül, a kinek titeket eladtalak? Ímé, a ti vétkeitekért adattatok el, és bűneitekért bocsáttatott el anyátok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, 'Miért jöttem, holott nem volt ott senki? hívtam és nem felelt senki sem! vagy olyan rövid már a kezem, hogy meg nem válthat? vagy nincs bennem megszabadításra való erő? Ímé, én dorgálásommal kiszáraztom a tengert, a folyókat pusztává teszem, megbűzhödnek halaik, hogy nincsen víz, és szomjúságtól meghalnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, 'Felöltöztetem az egeket sötétségbe, és gyászruhával födöm be azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, 'Az Úr Isten bölcs nyelvet adott én nékem, hogy tudjam erősítni a megfáradtat beszéddel, fölserkenti minden reggel, fölserkenti fülemet, hogy hallgassak, miként a tanítványok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, 'Az Úr Isten megnyitotta fülemet, és én nem voltam engedetlen, hátra nem fordultam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, 'Hátamat odaadám a verőknek, és orczámat a szaggatóknak, képemet nem födöztem be a gyalázás és köpdösés előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, 'És az Úr Isten megsegít engemet, azért nem szégyenülök meg, ezért olyanná tettem képemet, mint a kova, és tudtam, hogy szégyent nem vallok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, 'Közel van, a ki engem megigazít, ki perel én velem? Álljunk együtt elő! Kicsoda peresem? közelegjen hozzám!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, 'Ímé, az Úr Isten megsegít engem, kicsoda kárhoztatna engem? Ímé, mindnyájan, mint a ruha megavulnak, moly emészti meg őket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, 'Ki féli közületek az Urat? és ki hallgat az ő szolgája szavára? ő, a ki sötétségben jár és nincs fényesség néki, bízzék az Úr nevében, és támaszkodjék Istenhez!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, 'Ímé, ti mind, a kik tüzet gyujtotok, felövezvén magatokat tüzes nyilakkal, vettessetek tüzeteknek lángjába és a tüzes nyilakba, a melyeket meggyújtottatok! Kezemből jő ez rátok; fájdalomban fogtok feküdni!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, 'Hallgassatok reám, kik az igazságot követitek, kik az Urat keresitek; tekintsetek a kőszálra, a melyből kivágattattatok, és a kútfő nyílására, a melyből kiásattatok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, 'Tekintsetek Ábrahámra, atyátokra, és Sárára, a ki titeket szűlt, hogy egymagát hívtam el őt, és megáldám és megszaporítám őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, 'Mert megvígasztalja az Úr Siont, megvígasztalja minden romjait, és pusztáját olyanná teszi, mint az Éden, és kietlenjét olyanná, mint az Úrnak kertje, öröm és vígasság találtatik abban, hálaadás és dicséret szava!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, 'Figyeljetek reám, én népem, és reám hallgassatok, én nemzetem! mert tanítás megy ki tőlem, és törvényemet a népek megvilágosítására megalapítom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, 'Közel igazságom, kijő szabadításom, és karjaim népeket ítélnek: engem várnak a szigetek, és karomba vetik reménységüket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, 'Emeljétek az égre szemeiteket, és nézzetek a földre ide alá, mert az egek mint a füst elfogynak, és a föld, mint a ruha megavul, és lakosai hasonlókép elvesznek; de szabadításom örökre megmarad, és igazságom meg nem romol.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, 'Hallgassatok rám, kik tudjátok az igazságot, te nép, kinek szívében van törvényem! ne féljetek az emberek gyalázatától, és szidalmaik miatt kétségbe ne essetek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, 'Mert mint a ruhát, moly emészti meg őket, és mint a gyapjat, féreg eszi meg őket, és igazságom örökre megmarad, és szabadításom nemzetségről nemzetségre!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, 'Kelj föl, kelj föl, öltözd fel az erőt, oh Úrnak karja! kelj föl, mint a régi időben, a messze hajdanban! Avagy nem te vagy-é, a ki Ráhábot kivágta, és a sárkányt átdöfte?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, 'Nem te vagy-é, a ki a tengert megszáraztotta, a nagy mélység vizeit; a ki a tenger fenekét úttá változtatta, hogy átmenjenek a megváltottak?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, 'Így térnek meg az Úrnak megváltottai, és ujjongás között Sionba jőnek, és örökös öröm fejökön; vígasságot és örömöt találnak, eltünik a fájdalom és sóhaj!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, 'Én, én vagyok megvigasztalótok! Ki vagy te, hogy félsz halandó embertől? ember fiától, a ki olyan lesz, mint a fű?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, 'Hogy elfeledkeztél az Úrról, Teremtődről, a ki az eget kiterjeszté és a földet megalapítá, és hogy félsz szüntelen minden napon nyomorgatódnak haragjától, a ki igyekszik elveszteni? De hol van a nyomorgató haragja?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, 'Hirtelen megszabadul a fogoly, és nem hal meg a veremben, kenyere sem fogy el:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, 'Hiszen én vagyok az Úr, a te Istened, a ki megreszkettetem a tengert és zúgnak habjai; seregeknek Ura az Én nevem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, 'És adtam beszédemet a te szádba, és kezem árnyékával födöztelek be, hogy újonnan plántáljam az egeket, és megalapítsam a földet, és ezt mondjam Sionnak: Én népem vagy te!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, 'Serkenj föl, serkenj föl, kelj föl Jeruzsálem, ki megittad az Úr kezéből haragja poharát; a tántorgás öblös kelyhét megittad, kiürítéd!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, 'Nem vala vezetője minden fiai közül, a kiket szűlt, nem fogta senki őt kézen minden fiai közül, a kiket fölnevelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, 'E kettő esett rajtad! Kicsoda szánt meg téged? A pusztulás, a romlás, az éhség és a fegyver; miként vígasztaljalak téged?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, 'Fiaid elájultan ott feküdtek minden utczáknak fejeinél, mint a hálóba esett zerge, megrészegedve az Úr haragjától, Istenednek feddésétől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, 'Ezért halld meg ezt, szenvedő, ki részeg vagy, de nem bortól!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 22, 'Így szól Urad, az Úr, és Istened, a ki népéért bosszút áll: Ímé, kiveszem kezedből a tántorgás poharát, haragom öblös kelyhét, nem iszod többé azt meg!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 23, 'És adom azt nyomorgatóid kezébe, a kik azt mondották lelkednek: Hajolj meg, hogy átmenjünk te rajtad, és a te hátadat olyanná tetted, mint a föld, és mint a minő az utcza a járóknak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, 'Serkenj föl, serkenj föl, öltözd fel erősségedet, Sion, öltözzél fel ékességed ruháiba, Jeruzsálem, szent város, mert nem lép te beléd többé körülmetéletlen, tisztátalan!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, 'Rázd ki magad a porból, kelj fel, ülj fel Jeruzsálem, oldd ki magadat nyakad bilincseiből, Sion fogoly leánya!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, 'Mert így szól az Úr Isten: Ingyen adattatok el, és nem pénzen váltattok meg!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, 'Mert így szól az Úr Isten: Égyiptomba ment alá népem először, hogy ott bujdossék, és azután Assiria nyomorgatá őt ok nélkül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, 'És most mit tegyek itt? szól az Úr, hiszen népem elvitetett ok nélkül, és a rajta uralkodók ujjonganak, szól az Úr, és nevem szüntelen mindennap gúnyoltatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, 'Ezért hadd ismerje meg népem az én nevemet, ezért ama napon! Hogy én vagyok, a ki mondom: Ímé, itt vagyok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, 'Mily szépek a hegyeken az örömmondónak lábai, a ki békességet hirdet, jót mond, szabadulást hirdet, a ki ezt mondja Sionnak: Uralkodik a te Istened!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, 'Halld őrállóidat! felemelik szavokat, ujjonganak egyetemben, mert szemtől-szembe látják, hogy mint hozza vissza Siont az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, 'Ujjongva énekeljetek mindnyájan, Jeruzsálem romjai, mert megvígasztalá az Úr népét, megváltá Jeruzsálemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, 'Feltűrte az Úr szent karját minden népeknek szemei előtt, hogy lássák a föld minden határai Istenünk szabadítását!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, 'Távozzatok, távozzatok, jertek ki, onnan, tisztátalant ne illessetek, jertek ki közülök, tisztítsátok meg magatokat, a kik az Úr edényeit hordozzátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 12, 'Mert ne sietséggel jertek ki, és ne futással menjetek; mert előttetek megy az Úr, és követni fog Izráel Istene!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 13, 'Ímé, jó szerencsés lesz szolgám, magasságos, felséges és dicső lesz nagyon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 14, 'Miképen eliszonyodtak tőled sokan, oly rút, nem emberi volt ábrázatja, és alakja sem ember fiaié volt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 15, 'Akképen ejt ámulatba sok népeket; fölötte a királyok befogják szájokat, mert a mit nékik nem beszéltek volt, azt látják, és mit nem hallottak volt, arra figyelnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, 'Ki hitt a mi tanításunknak, és az Úr karja kinek jelentetett meg?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, 'Felnőtt, mint egy vesszőszál Ő előtte, és mint gyökér a száraz földből, nem volt néki alakja és ékessége, és néztünk reá, de nem vala ábrázata kivánatos!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, 'Útált és az emberektől elhagyott volt, fájdalmak férfia és betegség ismerője! mint a ki elől orczánkat elrejtjük, útált volt; és nem gondoltunk vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, 'Pedig betegséginket ő viselte, és fájdalmainkat hordozá, és mi azt hittük, hogy ostoroztatik, verettetik és kínoztatik Istentől!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, 'És ő megsebesíttetett bűneinkért, megrontatott a mi vétkeinkért, békességünknek büntetése rajta van, és az ő sebeivel gyógyulánk meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, 'Mindnyájan, mint juhok eltévelyedtünk, kiki az ő útára tértünk; de az Úr mindnyájunk vétkét ő reá veté.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, 'Kínoztatott, pedig alázatos volt, és száját nem nyitotta meg, mint bárány, mely mészárszékre vitetik, és mint juh, mely megnémul az őt nyírők előtt; és száját nem nyitotta meg!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 8, 'A fogságból és ítéletből ragadtatott el, és kortársainál ki gondolt arra, hogy kivágatott az élők földéből, hogy népem bűnéért lőn rajta vereség?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 9, 'És a gonoszok közt adtak sírt néki, és a gazdagok mellé jutott kínos halál után: pedig nem cselekedett hamisságot, és álnokság sem találtatott szájában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 10, 'És az Úr akarta őt megrontani betegség által; hogyha önlelkét áldozatul adja, magot lát, és napjait meghosszabbítja, és az Úr akarata az ő keze által jó szerencsés lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 11, 'Mert lelke szenvedése folytán látni fog, és megelégszik, ismeretével igaz szolgám sokakat megigazít, és vétkeiket ő viseli.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 12, 'Azért részt osztok néki a nagyokkal, és zsákmányt a hatalmasokkal oszt, mivelhogy életét halálra adta, és a bűnösök közé számláltatott; pedig ő sokak bűnét hordozá, és a bűnösökért imádkozott!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, 'Ujjongj te meddő, ki nem szűltél, ujjongva énekelj és kiálts, ki nem vajudtál, mert többek az elhagyottnak fiai a férjnél való fiainál, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, 'Szélesítsd ki a sátorod helyét, és hajlékidnak kárpitjait terjeszszék ki; ne tiltsd meg; nyújtsd meg köteleidet, és erősítsd meg szegeidet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, 'Mert mind jobb-, mind balkézre kiterjedsz, és magod népeket vesz örökségbe, és puszta városokat megnépesítnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, 'Ne félj, mert meg nem szégyenülsz, és ne pirulj, mert meg nem gyaláztatol, mert ifjúságod szégyenéről elfeledkezel, és özvegységednek gyalázatáról többé meg nem emlékezel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, 'Mert férjed a te Teremtőd, seregeknek Ura az Ő neve, és megváltód Izráelnek Szentje, az egész föld Istenének hívattatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, 'Mert mint elhagyott és fájó lelkű asszonyt hív téged az Úr, és mint megvetett ifjú asszonyt; ezt mondja Istened:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, 'Egy rövid szempillantásig elhagytalak, és nagy irgalmassággal egybegyűjtlek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, 'Búsulásom felbuzdultában elrejtém orczámat egy pillantásig előled, és örök irgalmassággal könyörülök rajtad; ezt mondja megváltó Urad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, 'Mert úgy lesz ez nékem, mint a Noé özönvize; miként megesküvém, hogy nem megy át többé Noé özönvize e földön, úgy esküszöm meg, hogy rád többé nem haragszom, és téged meg nem feddelek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 10, 'Mert a hegyek eltávoznak, és a halmok megrendülnek; de az én irgalmasságom tőled el nem távozik, és békességem szövetsége meg nem rendül, így szól könyörülő Urad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 11, 'Oh te szegény, szélvésztől hányt, vígasztalás nélkül való! Ímé, ólomporba rakom köveidet, és zafirokra alapítalak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 12, 'Rubinból csinálom falad párkányzatát, és kapuidat gránátkövekből, és egész határodat drágakövekből;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 13, 'És minden fiaid az Úr tanítványai lesznek, és nagy lesz fiaid békessége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 14, 'Igazság által leszel erős, ne gondolj a nyomorral, mert nincsen mit félned, és a rettegéssel, mert nem közelg hozzád.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 15, 'És ha összegyűlvén összegyűlnek, ez nem én tőlem lesz! A ki ellened összegyűl, elesik általad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 16, 'Ímé, én teremtettem a kovácsot, a ki a parazsat éleszti és fegyvert készít mestersége szerint: és én teremtém a pusztítót is a vesztésre!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 17, 'Egy ellened készült fegyver sem lesz jó szerencsés, és minden nyelvet, mely ellened perbe száll, kárhoztatsz: ez az Úr szolgáinak öröksége, és az ő igazságuk, mely tőlem van, így szól az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, 'Oh mindnyájan, kik szomjúhoztok, jertek e vizekre, ti is, kiknek nincs pénzetek, jertek, vegyetek és egyetek, jertek, vegyetek pénz nélkül és ingyen, bort és tejet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, 'Miért adtok pénzt azért, a mi nem kenyér, és gyűjtött kincseteket azért, a mi meg nem elégíthet? Hallgassatok, hallgassatok reám, hogy jót egyetek, és gyönyörködjék lelketek kövérségben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, 'Hajtsátok ide füleiteket és jertek hozzám; hallgassatok, hogy éljen lelketek, és szerzek veletek örök szövetséget, Dávid iránt való változhatatlan kegyelmességem szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, 'Ímé, bizonyságul adtam őt a népeknek, fejedelmül és parancsolóul népeknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, 'Ímé, nem ismert népet hívsz elő, és a nép, a mely téged nem ismert, hozzád siet az Úrért, Istenedért és Izráel Szentjéért, hogy téged megdicsőített.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, 'Keressétek az Urat, a míg megtalálható, hívjátok őt segítségül, a míg közel van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, 'Hagyja el a gonosz az ő útát, és a bűnös férfiú gondolatait, és térjen az Úrhoz, és könyörül rajta, és a mi Istenünkhöz, mert bővelkedik a megbocsátásban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, 'Mert nem az én gondolataim a ti gondolataitok, és nem a ti útaitok az én útaim, így szól az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, 'Mert a mint magasabbak az egek a földnél, akképen magasabbak az én útaim útaitoknál, és gondolataim gondolataitoknál!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, 'Mert mint leszáll az eső és a hó az égből, és oda vissza nem tér, hanem megöntözi a földet, és termővé, gyümölcsözővé teszi azt, és magot ád a magvetőnek és kenyeret az éhezőnek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, 'Így lesz az én beszédem, a mely számból kimegy, nem tér hozzám üresen, hanem megcselekszi, a mit akarok, és szerencsés lesz ott, a hová küldöttem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, 'Mert örömmel jöttök ki, és békességben vezéreltettek; a hegyek és halmok ujjongva énekelnek ti előttetek, és a mező minden fái tapsolnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, 'A tövis helyén cziprus nevekedik, és bogács helyett mirtus nevekedik, és lesz ez az Úrnak dicsőségül és örök jegyül, a mely el nem töröltetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, 'Így szól az Úr: Őrizzétek meg a jogosságot, és cselekedjetek igazságot, mert közel van szabadításom, hogy eljőjjön, és igazságom, hogy megjelenjék:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, 'Boldog ember, a ki ezt cselekszi, és az ember fia, a ki ahhoz ragaszkodik! a ki megőrzi a szombatot, hogy meg ne fertőztesse azt, és megőrzi kezét, hogy semmi gonoszt ne tegyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, 'És ne mondja ezt az idegen, a ki az Úrhoz adá magát: Bizony elszakaszt az Úr engem az Ő népétől! ne mondja a herélt sem: Ímé, én megszáradt fa vagyok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, 'Mert így szól az Úr a herélteknek: A kik megőrzik szombatimat és szeretik azt, a miben gyönyörködöm, és ragaszkodnak az én szövetségemhez:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, 'Adok nékik házamban és falaimon belül helyet, és oly nevet, a mely jobb, mint a fiakban és lányokban élő név; örök nevet adok nékik, a mely soha el nem vész;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, 'És az idegeneket, a kik az Úrhoz adák magukat, hogy néki szolgáljanak és hogy szeressék az Úr nevét, hogy Ő néki szolgái legyenek; mindenkit, a ki megőrzi a szombatot, hogy meg ne fertőztesse azt, és a szövetségemhez ragaszkodókat:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, 'Szent hegyemre viszem föl ezeket, és megvídámítom őket imádságom házában; egészen égő és véres áldozataik kedvesek lesznek oltáromon; mert házam imádság házának hivatik minden népek számára!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, 'Így szól az Úr Isten, a ki összegyűjti Izráel elszéledt fiait: Még gyűjtök ő hozzá, az ő egybegyűjtötteihez!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, 'Mezőnek minden vadai! jertek el enni, erdőnek minden vadai!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, 'Őrállói vakok mindnyájan, mitsem tudnak, mindnyájan néma ebek, nem tudnak ugatni; álmodók, heverők, szunnyadni szeretők!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, 'És ez ebek telhetetlenek, nem tudnak megelégedni, pásztorok ők, a kik nem tudnak vigyázni; mindnyájan a magok útára tértek, kiki nyeresége után, mind együtt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, 'Jertek, hadd hozzak bort, és igyunk részegítő italt! és legyen a holnap olyan, mint a ma, nagy és dicső felettébb!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, 'Az igaz elvész és nem veszi eszébe senki, és az irgalmasságtevők elragadtatnak és senki nem gondolja fel, hogy a veszedelem elől ragadtatik el az igaz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, 'Bemegy békességbe, nyugosznak ágyaikon, a kik egyenes útaikon járának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, 'És ti közelgjetek ide, szemfényvesztő fiai, paráznának magva, a ki paráználkodol.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, 'Ki felett örvendeztek? Ki ellen tátjátok fel szátokat és öltitek ki nyelveteket? nem ti vagytok-é a bűn gyermekei, a hazugságnak magva?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, 'A kik lángoltok a bálványokért minden zöld fa alatt, megöltök gyermekeket a völgyekben, a hegyek hasadékai alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, 'A folyónak sima köveiben van örökséged; azok, azok a te részed, töltöttél nékik italáldozatot is, vivél ételáldozatot és én jó néven vegyem-é ezeket?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, 'Magas és felemelkedett hegyen helyezted ágyadat, fel is menél oda áldozni áldozatot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, 'Az ajtó és ajtófél mögé tetted bálványjeleidet, és tőlem eltávozván, fölfedted ágyadat, fölmentél rá, és megszélesítéd, és szövetséget szerzél velök, szeretted ágyukat, a merre csak láttad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, 'És menél a királyhoz olajjal, és megsokasítád keneteidet, és elküldéd követeidet messze földre, és megaláztad magadat a sírig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, 'Nagy útadon megfáradál, és még sem mondád: mind hasztalan! erőd megújulását érezéd, így nem levél beteg!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, 'Kitől féltél és rettegtél, hogy hazudtál és rólam meg nem emlékezél, szívedre sem vevéd? vagy azért nem félsz engem, hogy hallgatok már régtől fogva?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, 'Én jelentem meg igazságodat, és csinálmányaid nem használnak néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 13, 'Ha kiáltasz: szabadítson meg téged bálványid raja; mindnyájokat szél viszi el, lehelet kapja fel, és a ki bennem bízik, örökségül bírja a földet, és örökli szent hegyemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 14, 'És szól egy szó: Töltsétek, töltsétek, készítsétek az útat, vegyetek el minden botránkozást népem útáról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 15, 'Mert így szól a magasságos és felséges, a ki örökké lakozik, és a kinek neve szent: Magasságban és szentségben lakom, de a megrontottal és alázatos szívűvel is, hogy megelevenítsem az alázatosok lelkét, és megelevenítsem a megtörtek szívét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 16, 'Mert nem örökké perlek, és nem mindenha haragszom, mert a lélek előttem megepedne, és a leheletek, a kiket én teremtettem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 17, 'Mert a telhetetlenségnek vétkéért haragudtam meg, és megvertem őt, elrejtém magamat és megharagudtam; és ő elfordulva, szíve útjában járt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 18, 'Útait láttam, és meggyógyítom őt; vezetem őt, és vígasztalást nyujtok néki és gyászolóinak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 19, 'Megteremtem ajkaikon a hálának gyümölcsét. Békesség, békesség a messze és közel valóknak, így szól az Úr; én meggyógyítom őt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 20, 'És a hitetlenek olyanok, mint egy háborgó tenger, a mely nem nyughatik, és a melynek vize iszapot és sárt hány ki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 21, 'Nincs békesség, szól Istenem, a hitetleneknek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, 'Kiálts teljes torokkal, ne kiméld; mint trombita emeld fel hangodat, és hirdesd népemnek bűneiket, és Jákób házának vétkeit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, 'Holott ők engem mindennap keresnek, és tudni kivánják útaimat, mint oly nép, a mely igazságot cselekedett és Istene törvényét el nem hagyta; kérik tőlem az igazságnak ítéleteit, és Istennek elközelgését kivánják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, 'Mért bőjtölünk és Te nem nézed, gyötörjük lelkünket és Te nem tudod? Ímé, bőjtöléstek napján kedvtelésteket űzitek, és minden robotosaitokat szorongatjátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, 'Ímé perrel és versengéssel bőjtöltök, és sújtotok a gazságnak öklével; nem úgy bőjtöltök mostan, hogy meghallassék szavatok a magasságban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, 'Hát ilyen a bőjt, a melyet én kedvelek, és olyan a nap, a melyen az ember lelkét gyötri? Avagy ha mint káka lehajtja fejét, és zsákot és hamvat terít maga alá: ezt nevezed-é bőjtnek és az Úr előtt kedves napnak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, 'Hát nem ez-é a bőjt, a mit én kedvelek: hogy megnyisd a gonoszságnak bilincseit, az igának köteleit megoldjad, és szabadon bocsásd az elnyomottakat, és hogy minden igát széttépjetek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, 'Nem az-é, hogy az éhezőnek megszegd kenyeredet, és a szegény bujdosókat házadba bevigyed, ha meztelent látsz, felruházzad, és tested előtt el ne rejtsd magadat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, 'Akkor felhasad, mint hajnal a te világosságod, és meggyógyulásod gyorsan kivirágzik, és igazságod előtted jár; az Úr dicsősége követ.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, 'Akkor kiáltasz, és az Úr meghallgat, jajgatsz, és ő azt mondja: Ímé, itt vagyok. Ha elvetended közüled az igát, és megszünsz ujjal mutogatni és hamisságot beszélni;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, 'Ha odaadod utolsó falatodat az éhezőnek, és az elepedt lelkűt megelégíted: feltámad a setétségben világosságod, és homályosságod olyan lesz, mint a dél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, 'És vezérel téged az Úr szüntelen, megelégíti lelkedet nagy szárazságban is, és csontjaidat megerősíti, és olyan leszel, mint a megöntözött kert, és mint vízforrás, a melynek vize el nem fogy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, 'És megépítik fiaid a régi romokat, az emberöltők alapzatait felrakod, és neveztetel romlás építőjének, ösvények megújítójának, hogy ott lakhassanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 13, 'Ha megtartóztatod szombaton lábadat, és nem űzöd kedvtelésedet szent napomon, és a szombatot gyönyörűségnek hívod, az Úr szent és dicsőséges napjának, és megszenteled azt, dolgaidat nem tevén, foglalkozást sem találván, hamis beszédet sem szólván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 14, 'Akkor gyönyörűséged lesz az Úrban; és én hordozlak a föld magaslatain, és azt mívelem, hogy Jákóbnak, atyádnak örökségével élj; mert az Úr szája szólt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, 'Ímé, nem oly rövid az Úr keze, hogy meg ne szabadíthatna, és nem oly süket az ő füle, hogy meg nem hallgathatna;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, 'Hanem a ti vétkeitek választanak el titeket Istenetektől, és bűneitek fedezték el orczáját ti előttetek, hogy meg nem hallgatott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, 'Mert kezeitek bemocskolvák vérrel, és ujjaitok vétekkel, ajkaitok hazugságot szólnak, nyelvetek gonoszt suttog.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, 'Nincsen, a ki az igazság mellett szólna, és nincsen, a ki igazságosan perelne, haszontalanban bíznak és hazugságot beszélnek, gonoszt fogadnak és vétket szűlnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, 'Vipera tojásait költik ki, és pókhálót szőnek; a ki tojásaikból eszik, meghal, és ha egyre rátapodsz, vipera kél ki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, 'Pókhálójukból nem lesz ruha, csinálmányok nem felvehető; cselekedeteik hamisságnak cselekedetei, és erőszak tette van kezeikben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, 'Lábaik a gonoszra futnak; és sietnek, hogy ártatlan vért ontsanak; gondolataik hamisságnak gondolatai, pusztítás és romlás ösvényeiken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, 'A békesség útját nem ismerik, és nincsen jogosság kerékvágásukban, ösvényeiket elgörbítik, a ki azon jár, nem ismeri a békességet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, 'Ezért van távol tőlünk az ítélet, és nem ér el minket az igazság, várunk világosságra, és ímé, sötétség, és fényességre, és ímé, homályban járunk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, 'Tapogatjuk, mint vakok a falat, és tapogatunk, mint a kiknek szemök nincs, megütközünk délben, mint alkonyatkor, és olyanok vagyunk, mint a halottak az egészségesek közt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, 'Morgunk, mint a medvék mindnyájan, és nyögvén nyögünk, mint a galambok, várjuk az ítéletet és nem jő, a szabadulást és távol van tőlünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, 'Mert sokak előtted gonoszságaink, és bűneink bizonyságot tesznek mi ellenünk, mert gonoszságaink velünk vannak, és vétkeinket ismerjük:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, 'Elpártoltunk és megtagadtuk az Urat, és eltávozánk a mi Istenünktől, szóltunk nyomorgatásról és elszakadásról, gondoltunk és szóltunk szívünkből hazug beszédeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, 'És eltávozott a jogosság, és az igazság messze áll, mivel elesett a hűség az utczán, és az egyenesség nem juthat be.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, 'És a hűség hiányzik, és a ki a gonoszt kerüli, prédává lesz. És látta ezt az Úr és nem tetszék szemeinek, hogy jogosság nincsen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, 'És látá, hogy nincsen senki, és álmélkodott, hogy nincsen közbenjáró; ezért karja segít néki, és igazsága gyámolítja őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, 'És felölté az igazságot, mint pánczélt, és a szabadítás sisakja van fején; felölté a bosszúállás ruháit, mint köpenyt, és búsulással vevé magát körül, mint egy palásttal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, 'A cselekedetek szerint fog megfizetni: haraggal ellenségeinek, büntetéssel szorongatóinak, büntetéssel fizet a szigeteknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 19, 'És félik napnyugottól fogva az Úrnak nevét, és naptámadattól az ő dicsőségét, mikor eljő, mint egy sebes folyóvíz, a melyet az Úr szele hajt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 20, 'És eljő Sionnak a megváltó, és azoknak, a kik Jákóbban megtérnek hamisságokból, szól az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 21, 'És én ő velök ily szövetséget szerzek, szól az Úr: lelkem, a mely rajtad nyugoszik, és beszédeim, a melyeket szádba adtam, el nem távoznak szádból, és magodnak szájából, és magod magvának szájából, így szól az Úr, mostantól mind örökké!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, 'Kelj fel, világosodjál, mert eljött világosságod, és az Úr dicsősége rajtad feltámadt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, 'Mert ímé, sötétség borítja a földet, és éjszaka a népeket, de rajtad feltámad az Úr, és dicsősége rajtad megláttatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'És népek jönnek világosságodhoz, és királyok a néked feltámadt fényességhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, 'Emeld fel köröskörül szemeidet és lásd meg: mindnyájan egybegyűlnek, hozzád jönnek, fiaid messziről jönnek, és leányaid ölben hozatnak el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'Akkor meglátod és ragyogsz örömtől, és remeg és kiterjed szíved, mivel hozzád fordul a tenger kincsözöne, és hozzád jő a népeknek gazdagsága.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'A tevék sokasága elborít, Midján és Éfa tevecsikói, mind Sebából jönnek, aranyat és tömjént hoznak, és az Úr dicséreteit hirdetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, 'Kédár minden juhai hozzád gyűlnek, Nebajóth kosai néked szolgálnak, felmennek kedvem szerint oltáromra, és dicsőségem házát megdicsőítem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, 'Kik ezek, kik repülnek, mint a felleg, s mint a galambok dúczaikhoz?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, 'Igen, engem várnak a szigetek; és elől jönnek Társis hajói, hogy elhozzák fiaidat messziről, és ezüstjöket és aranyokat azokkal együtt, a te Urad és Istened nevének és Izráel Szentjének, hogy téged megdicsőített.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, 'Az idegenek megépítik kőfalaidat, és királyaik szolgálnak néked; mivel haragomban megvertelek, és kegyelmemben megkönyörültem rajtad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, 'És nyitva lesznek kapuid szüntelen, éjjel és nappal be nem zároltatnak, hogy behozzák hozzád a népek gazdagságát, és királyaik is bevitetnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, 'Mert a nép és az ország, a mely néked nem szolgáland, elvész, és a népek mindenestől elpusztulnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, 'A Libánon ékessége hozzád jő, cziprus, platán, sudar czédrus, mind együtt szenthelyemnek megékesítésére, hogy lábaim helyét megdicsőítsem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, 'És meghajolva hozzád mennek a téged nyomorgatók fiai, és leborulnak lábad talpainál minden megútálóid, és neveznek téged az Úr városának, Izráel Szentje Sionának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 15, 'A helyett, hogy elhagyott és gyűlölt valál és senki rajtad át nem ment, örökkévaló ékességgé teszlek, és gyönyörűséggé nemzetségről nemzetségre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 16, 'És szopod a népek tejét, és a királyok emlőjét szopod, és megtudod, hogy én vagyok az Úr, megtartód és megváltód, Jákóbnak erős Istene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 17, 'Réz helyett aranyat hozok, vas helyett ezüstöt hozok, és a fák helyett rezet, és a kövek helyett vasat, és teszem fejedelmeiddé a békességet, és előljáróiddá az igazságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 18, 'Nem hallatik többé erőszaktétel földeden, pusztítás és romlás határaidban, és a szabadulást hívod kőfalaidnak, és kapuidnak a dicsőséget.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 19, 'Nem a nap lesz néked többé nappali világosságod, és fényességül nem a hold világol néked, hanem az Úr lesz néked örök világosságod, és Istened lesz ékességed,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 20, 'Napod nem megy többé alá, és holdad sem fogy el, mert az Úr lesz néked örök világosságod, és gyászod napjainak vége szakad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 21, 'És néped mind igaz lesz, és a földet mindörökké bírják, plántálásom vesszőszála ők, kezeim munkája dicsőségemre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 22, 'A legkisebb ezerre nő, és a legkevesebb hatalmas néppé. Én az Úr, idején, hamar megteszem ezt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, 'Az Úr Isten lelke van én rajtam azért, mert fölkent engem az Úr, hogy a szegényeknek örömöt mondjak; elküldött, hogy bekössem a megtört szívűeket, hogy hirdessek a foglyoknak szabadulást, és a megkötözötteknek megoldást;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, 'Hogy hirdessem az Úr jókedvének esztendejét, és Istenünk bosszúállása napját; megvígasztaljak minden gyászolót;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, 'Hogy tegyek Sion gyászolóira, adjak nékik ékességet a hamu helyett, örömnek kenetét a gyász helyett, dicsőségnek palástját a csüggedt lélek helyett, hogy igazság fáinak neveztessenek, az Úr plántáinak, az Ő dicsőségére!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, 'És megépítik a régi romokat, az ősi pusztaságokat helyreállítják, és a puszta városokat megújítják, és a régi nemzetségek pusztaságait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, 'És ott állnak az idegenek, és legeltetik juhaitokat, és a jövevények szántóitok és vinczelléreitek lesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, 'Ti pedig az Úr papjainak hívattattok, Istenünk szolgáinak neveztettek; a népek gazdagságát eszitek, és azok dicsőségével dicsekedtek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, 'Gyalázatotokért kettős jutalmat vesztek, és a szidalom helyett örvendenek örökségükben; ekként két részt öröklenek földükben, örökös örömük lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, 'Mert én, az Úr, a jogosságot szeretem, gyűlölöm a gazsággal szerzett ragadományt; és megadom híven jutalmukat, és örök szövetséget szerzek velök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, 'És ismeretes lesz magvok a népek közt, és ivadékaik a népségek között, valakik látják őket, megismerik őket, hogy ők az Úrtól megáldott magok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 10, 'Örvendezvén örvendezek az Úrban, örüljön lelkem az én Istenemben; mert az üdvnek ruháival öltöztetett fel engem, az igazság palástjával vett engemet körül, mint vőlegény, a ki pap módon ékíti fel magát, és mint menyasszony, a ki felrakja ékességeit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 11, 'Mert mint a föld megtermi csemetéjét, és mint a kert kisarjasztja veteményeit, akként sarjasztja ki az Úr Isten az igazságot s a dicsőséget minden nép előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, 'Sionért nem hallgatok és Jeruzsálemért nem nyugszom, míg földerül, mint fényesség az Ő igazsága, és szabadulása, mint a fáklya tündököl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, 'És meglátják a népek igazságodat, és minden királyok dicsőségedet, és új nevet adnak néked, a melyet az Úr szája határoz meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, 'És leszel dicsőség koronája az Úr kezében, és királyi fejdísz Istened kezében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, 'Nem neveznek többé elhagyatottnak, és földedet sem nevezik többé pusztának, hanem így hívnak: én gyönyörűségem, és földedet így: férjhez adott; mert az Úr gyönyörködik benned, és földed férjhez adatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, 'Mert mint elveszi a legény a szűzet, akként vesznek feleségül téged fiaid, és a mint örül a vőlegény a menyasszonynak, akként fog néked Istened örülni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, 'Kőfalaidra, Jeruzsálem, őrizőket állattam, egész nap és egész éjjel szüntelen nem hallgatnak; ti, kik az Urat emlékeztetitek, ne nyugodjatok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, 'És ne hagyjatok nyugtot néki, míg megújítja és dicsőségessé teszi Jeruzsálemet e földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, 'Megesküdt az Úr jobbjára s erőssége karjára: nem adom többé gabonádat eleségül ellenségeidnek, s idegenek nem iszszák mustodat, a melyért munkálódtál,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, 'Hanem a betakarók egyék azt meg, és dicsérjék az Urat, s a beszűrők igyák meg azt szentségem pitvaraiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, 'Menjetek át, menjetek át a kapukon, készítsétek a népnek útát, töltsétek, töltsétek az ösvényt, hányjátok el a köveket, emeljetek zászlót a népek fölé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, 'Ímé, az Úr hirdette mind a föld határáig: Mondjátok meg Sion leányának, ímé, eljött szabadulásod, ímé, jutalma vele jő, és megfizetése ő előtte!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, 'És hívják őket szent népnek, az Úr megváltottainak, és téged hívnak: keresett és nem elhagyott városnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, 'Ki ez, ki jő Edomból, veres ruhákban Boczrából, a ki ékes öltözetében, ereje sokaságában büszke? Én, a ki igazságban szólok, elégséges vagyok a megtartásra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, 'Miért veres öltözeted, és ruháid, mint a bornyomó ruhái?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, 'A sajtót egyedül tapostam, és a népek közül nem volt velem senki, és megtapodtam őket búsulásomban, és széttapostam őket haragomban: így fecscsent vérök ruháimra, és egész öltözetemet bekevertem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, 'Mert bosszúállás napja volt szívemben, és megváltottaim esztendeje eljött.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, 'Körültekinték és nem vala segítő, s álmélkodám és nem vala gyámolító, és segített nékem karom, és haragom gyámolított engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, 'És megtapodtam népeket búsulásomban, és megrészegítem őket haragomban, és ontám a földre véröket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, 'Az Úrnak kegyelmességeiről emlékezem, az Úr dicséreteiről mind a szerint, a mit az Úr velünk cselekedett; az Izráel házához való sok jóságáról, a melyet velök cselekedett irgalma és kegyelmének sokasága szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, 'És ő mondá: Bizony az én népem ők, fiak, a kik nem hazudnak; és lőn nékik megtartójok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, 'Minden szenvedésöket Ő is szenvedte, és orczájának angyala megszabadítá őket, szerelmében és kegyelmében váltotta Ő meg őket, fölvette és hordozá őket a régi idők minden napjaiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, 'Ők pedig engedetlenek voltak és megszomoríták szentségének lelkét, és ő ellenségükké lőn, hadakozott ellenök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, 'S megemlékezék népe a Mózes régi napjairól: hol van, a ki őket kihozá a tengerből nyájának pásztorával? hol van, a ki belé adá az ő szentséges lelkét?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, 'Ki Mózes jobbján járatá dicsőségének karját, a ki a vizeket ketté választá előttök, hogy magának örök nevet szerezzen?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 13, 'Ki járatá őket mélységekben, mint a lovat a síkon, és meg nem botlottanak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 14, 'Mint a barmot, a mely völgybe száll alá, nyugodalomba vitte őket az Úr lelke: így vezérletted népedet, hogy magadnak dicső nevet szerezz!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 15, 'Tekints alá az égből, és nézz le szentséged és dicsőséged hajlékából! Hol van buzgó szerelmed és hatalmad? Szívednek dobogása és irgalmad megtartóztatják magokat én tőlem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 16, 'Hiszen Te vagy Atyánk, hiszen Ábrahám nem tud minket, és Izráel nem ismer minket, Te, Uram, vagy a mi Atyánk, megváltónk, ez neved öröktől fogva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 17, 'Miért engedél eltévelyedni minket útaidról, oh Uram! miért keményítéd meg szívünket, hogy ne féljünk tégedet? Térj meg szolgáidért, örökséged nemzetségeiért!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 18, 'Kevés ideig bírta szentségednek népe földét, ellenségink megtapodták szent helyedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 19, 'Olyanok lettünk, mint a kiken eleitől fogva nem uralkodtál, a kik felett nem neveztetett neved.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, 'Oh, vajha megszakasztanád az egeket és leszállnál, előtted a hegyek elolvadnának; mint a tűz meggyújtja a rőzsét, a vizet a tűz felforralja; hogy nevedet ellenségidnek megjelentsd, hogy előtted reszkessenek a népek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, 'Hogy cselekednél rettenetes dolgokat, a miket nem vártunk; leszállnál és előtted a hegyek elolvadnának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, 'Hiszen öröktől fogva nem hallottak és fülökbe sem jutott, szem nem látott más Istent te kívüled, a ki így cselekszik azzal, a ki Őt várja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, 'Elébe mégy annak, a ki örvend és igazságot cselekszik, a kik útaidban rólad emlékeznek! Ímé, Te felgerjedtél, és mi vétkezénk; régóta így vagyunk; megtartatunk-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, 'És mi mindnyájan olyanok voltunk, mint a tisztátalan, és mint megfertéztetett ruha minden mi igazságaink, és elhervadánk, mint a falomb mindnyájan, és álnokságaink, mint a szél, hordának el bennünket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, 'S nem volt, a ki segítségül hívta volna nevedet, a ki felserkenne és beléd fogóznék, mert orczádat elrejtéd tőlünk, és álnokságainkban minket megolvasztál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, 'Most pedig, Uram, Atyánk vagy Te, mi sár vagyunk és Te a mi alkotónk, és kezed munkája vagyunk mi mindnyájan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, 'Oh ne haragudjál Uram felettébb, és ne mindörökké emlékezzél meg álnokságinkról; ímé lásd, kérünk, mindnyájan a Te néped vagyunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, 'Szentségednek városai pusztává lettenek, Sion pusztává lőn, Jeruzsálem kietlenné.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, 'Szentségünk és ékességünk házát, hol téged atyáink dicsértenek, tűz perzselé föl, és minden a miben gyönyörködénk, elpusztult.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, 'Hát megtartóztatod-é magad mind e mellett is, Uram; hallgatsz-é és gyötörsz minket felettébb?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 12, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, 'Megkeresni hagytam magamat azoktól, a kik nem is kérdeztenek; megtaláltattam magamat azokkal, a kik nem is kerestenek. Ezt mondám: Ímhol vagyok, ímhol vagyok, a népnek, a mely nem nevemről neveztetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, 'Kiterjesztém kezeimet egész napon a pártos nép után, a mely nem jó úton járt gondolatainak nyomán;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, 'A nép után, mely ingerel engem szemtől szembe, szünetlenül, kertekben áldozik, és téglákon szerez jóillatot,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, 'Mely a sírokhoz ül, és a barlangokban hál, a disznóhúst eszi, és fertelmes leves van tálaiban,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, 'Mely ezt mondja: Maradj otthon, ne jőjj hozzám, mert szent vagyok néked; e nép füst az orromban és szüntelen égő tűz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, 'Ímé, feliratott előttem: nem hallgatok, csak ha előbb megfizetek, megfizetek keblökben:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'Vétkeitekért és atyáitok vétkeiért mind együtt, szól az Úr, a kik hegyeken tettek jóillatot és halmokon csúfoltak engemet meg, és visszamérem először jutalmokat keblökre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, 'Így szól az Úr: Mint a mikor mustot lelnek a fürtben, ezt mondják: ne veszesd el, mert áldás van benne, ekként cselekszem szolgáimért, és nem vesztek mindent el!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, 'És nevelek Jákóbból magot, és Júdából, a ki hegyeimnek örököse legyen, és bírják azt választottaim, és szolgáim lakjanak ott!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, 'És lesz Sáron nyájak legelőjévé, és Ákhor völgye barmok fekvőhelyévé népem számára, a mely engem keresett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, 'Ti pedig, a kik az Urat elhagyátok, a kik szent hegyemről elfeledkezétek, ti, kik Gádnak asztalt készítetek, és Meninek italáldozatot töltötök,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, 'Titeket én a kard alá számlállak, és mindnyájan leborultok megöletésre: mert hívtalak és nem feleltetek, szóltam és nem hallottátok: a gonoszt cselekedtétek szemeim előtt, és a mit nem szerettem, azt választottátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, 'Azért így szól az Úr Isten: Ímé, szolgáim esznek, ti pedig éheztek, ímé, szolgáim isznak, ti pedig szomjúhoztok, ímé, szolgáim örvendnek, de ti megszégyenültök!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, 'Ímé, szolgáim vígadnak szívök boldogságában, és ti kiáltani fogtok szívetek fájdalmában, és megtört lélekkel jajgatni fogtok;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 15, 'És átok gyanánt hagyjátok itt neveteket az én választottaimnak, és megöl titeket az Úr Isten, és szolgáit más névvel nevezi,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 16, 'Hogy a ki magát áldja e földön, áldja magát az igaz Istenben, és a ki esküszik e földön, esküdjék az igaz Istenre, mert elfeledvék a régi nyomorúságok, és mert elrejtvék szemeim elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 17, 'Mert ímé, új egeket és új földet teremtek, és a régiek ingyen sem emlittetnek, még csak észbe sem jutnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 18, 'Hanem örüljetek és örvendjetek azoknak mindörökké, a melyeket én teremtek; mert ímé, Jeruzsálemet vígassággá teremtem, és az ő népét örömmé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 19, 'És vígadok Jeruzsálem fölött, és örvendek népem fölött, és nem hallatik többé abban siralomnak és kiáltásnak szava!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 20, 'Nem lesz ott többé csupán néhány napot ért gyermek, sem vén ember, a ki napjait be nem töltötte volna, mert az ifjú száz esztendős korában hal meg és a bűnös száz esztendős korában átkoztatik meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 21, 'Házakat építnek és bennök lakoznak, és szőlőket plántálnak és eszik azok gyümölcsét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 22, 'Nem úgy építnek, hogy más lakjék benne; nem úgy plántálnak, hogy más egye a gyümölcsöt, mert mint a fáké, oly hosszú lesz népem élete, és kezeik munkáját elhasználják választottaim.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 23, 'Nem fáradnak hiába, nem nemzenek a korai halálnak, mivel az Úr áldottainak magva ők, és ivadékaik velök megmaradnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 24, 'És mielőtt kiáltanának, én felelek, ők még beszélnek, és én már meghallgattam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 25, 'A farkas és bárány együtt legelnek, az oroszlán, mint az ökör, szalmát eszik, és a kígyónak por lesz az ő kenyere. Nem ártanak és nem pusztítnak sehol szentségemnek hegyén; így szól az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, 'Így szól az Úr: Az egek nékem ülőszékem, és a föld lábaimnak zsámolya: minő ház az, a melyet nékem építeni akartok, és minő az én nyugalmamnak helye?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, 'Hiszen mindezeket kezem csinálta, így álltak elő mindezek; így szól az Úr. Hanem erre tekintek én, a ki szegény és megtörött lelkű, és a ki beszédemet rettegi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, 'A ki bikát öl, embert üt agyon; a ki juhval áldozik, az ebet öl; a ki ételáldozattal jő, disznóvért hoz elém; a ki tömjént gyújt, bálványt imád! Miként ők így választák útaikat, és lelkök útálatosságaikban gyönyörködött:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, 'Akképen választom én is az ő megcsúfolásukat, és rájok hozom, a mitől félnek; mivel hívtam és senki nem felelt, szóltam és nem hallották, és a gonoszt cselekedték szemeim előtt, s a mit nem szerettem, azt választák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, 'Halljátok az Úrnak beszédét, a kik rettegtek az ő beszédére: így szólnak testvéreitek, a kik titeket gyűlölnek, nevemért eltaszítanak: Jelenjék meg az Úrnak dicsősége, hogy lássuk örömötöket; de ők megszégyenülnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, 'Halld! zúgás a város felől, hah! a templom felől, hah! az Úr, a ki megfizet ellenségeinek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, 'Mielőtt vajudott volna, szült, mielőtt fájdalom jött rá, fiút hozott világra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, 'Ki hallott olyat, mint ez, ki látott hasonló dolgokat? Hát egy ország egy nap jön-é világra, és egy nép egyszerre születik-é? mert vajudott és meg is szűlé Sion az ő fiait!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, 'Hát én csak megindítsam és ne vigyem véghez a szűlést? szól az Úr, vagy én, a ki szűletek, bezárjam-é a méhet? így szól Istened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, 'Örüljetek Jeruzsálemmel, és örvendjetek fölötte mind, a kik őt szeretitek; vígadjatok vele örvendezéssel mindnyájan, a kik gyászoltatok miatta!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, 'Hogy szopjatok és megelégedjetek megvígasztaltatásának emlőjén, hogy igyatok és örvendjetek dicsőségének bőségén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, 'Mivel így szól az Úr: Ímé kiterjesztem rá a békességet, mint egy folyóvizet, és mint kiáradott patakot a népek dicsőségét, hogy szopjátok; ölben fognak hordozni, és térdeiken czirógatnak titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, 'Mint férfit, a kit anyja vígasztal, akként vígasztallak titeket én, és Jeruzsálemben vesztek vígasztalást!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, 'Meglátjátok és örül szívetek, csontjaitok, mint a zöld fű, virágoznak, és megösmerik az Úr kezét az Ő szolgáin, és haragját ellenségei fölött.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, 'Mert ímé, az Úr eljő tűzben, s mint forgószél az ő szekerei, hogy megfizesse búsulásában az Ő haragját, és megfeddését sebesen égő lánggal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, 'Mert az Úr tűzzel ítél és kardjával minden testet, és sokan lesznek az Úrtól megöltek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, 'A kik magokat megszentelik és mossák a bálvány kertekért, egy pap megett, a középen; a kik disznóhúst esznek és férget és egeret, együtt pusztulnak el mind, mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, 'És én cselekedeteiteket és gondolataitokat megbüntetem! Eljő az idő, hogy minden népeket és nyelveket egybegyűjtsek, hogy eljövén, meglássák az én dicsőségemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, 'És teszek köztök jelt, és küldök közülök megszabadultakat a népekhez, Tarsisba, Pulba és Ludba, az íjjászokhoz, Tubálhoz és Jávánhoz; a messze szigetekbe, a melyek rólam nem hallottak, és nem látták dicsőségemet, és hirdetik dicsőségemet a népek között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, 'És elhozzák minden testvéreiteket minden népek közül ajándékul az Úrnak, lovakon, szekereken, hintókban, öszvéreken és tevéken szentségemnek hegyére Jeruzsálembe, így szól az Úr, a mint hozzák Izráelnek fiai az ajándékot tiszta edényben az Úrnak házába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 21, 'És ezek közül is választok a papok közé, a Léviták közé, így szól az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 22, 'Mert mint az új egek és az új föld, a melyeket én teremtek, megállnak én előttem, szól az Úr, azonképen megáll a ti magvatok és nevetek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 23, 'És lesz, hogy hónapról-hónapra és szombatról-szombatra eljő minden test engem imádni, szól az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 24, 'És kimenvén, látni fogják azoknak holttesteit, a kik ellenem vétkeztek, mert az ő férgök meg nem hal és tüzök el nem aluszik, és minden test előtt borzadásul lesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'Jeremiásnak, Hilkiás fiának beszédei, a ki az Anatótban, Benjámin földén lakó papok közül vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'A kihez szóla az Úr Jósiásnak, az Ammon fiának, Júda királyának napjaiban, az ő uralkodásának tizenharmadik esztendejében;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'Továbbá Jójakimnak, a Jósiás fiának, Júda királyának napjaiban, Sedékiásnak, a Jósiás fiának, Júda királyának egészen tizenegyedik esztendejéig, Jeruzsálem fogságba viteléig, a mi az ötödik hónapban vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'Szóla pedig az Úr nékem, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, 'Mielőtt az anyaméhben megalkottalak, már ismertelek, és mielőtt az anyaméhből kijövél, megszenteltelek; prófétának rendeltelek a népek közé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'És mondék: Ah, ah Uram Isten! Ímé, én nem tudok beszélni; hiszen ifjú vagyok én!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'Az Úr pedig monda nékem: Ne mondd ezt: Ifjú vagyok én; hanem menj mind azokhoz, a kikhez küldelek téged, és beszéld mindazt, a mit parancsolok néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'Ne félj tőlök, mert én veled vagyok, hogy megszabadítsalak téged! mond az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'És kinyújtá az Úr az ő kezét, és megilleté számat, és monda nékem az Úr: Ímé, az én igéimet adom a te szádba!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'Lásd, én e mai napon népek fölé és országok fölé rendellek téged, hogy gyomlálj, irts, pusztíts, rombolj, építs és plántálj!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'Szóla továbbá nékem az Úr, mondván: Mit látsz te, Jeremiás? És mondék: Mandulavesszőt látok én.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'És monda nékem az Úr: Jól láttál, mert gondom van az én igémre, hogy beteljesítsem azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'És másodszor is szóla hozzám az Úr, mondván: Mit látsz te? És felelék: Forró fazekat látok én, és pedig a szája észak felől van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'És monda nékem az Úr: Észak felől támad a veszedelem e földnek minden lakosára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'Mert ímé, előhívom én az északi országok minden nemzetségét, mondja az Úr, és eljőnek, és kiki felállítja az ő királyi székét Jeruzsálem kapui előtt, és köröskörül minden kerítése ellen, és Júdának minden városa ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'És kimondom ítéleteimet felettök az ő mindenféle gonoszságukért, minthogy elszakadtak tőlem, és idegen isteneknek áldoztak, és tulajdon kezeik munkáit imádták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, 'Te azért övezd fel derekadat, és kelj fel, és mondd meg nékik mindazt, a mit én parancsolok néked; meg ne riadj tőlök, különben én riasztalak el téged előlök!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, 'Mert ímé én erősített várossá, vasoszloppá és érczbástyává teszlek ma téged mind ez egész földön, Júda királyai, fejedelmei és papjai ellen és a föld népe ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, 'Viaskodni fognak ugyan ellened, de nem győznek meg téged, mert én veled vagyok, azt mondja az Úr, hogy megszabadítsalak téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'Majd szóla az Úr nékem, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, 'Menj el, és kiálts Jeruzsálem füleibe, mondván: Ezt mondja az Úr: Emlékezem reád gyermekkorod ragaszkodására, mátkaságod szeretetére, a mikor követtél engem a pusztában, a még be nem vetett földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'Szent volt Izráel az Úrnak, az ő termésének zsengéje; a kik emésztik vala őt, mind vétkeznek vala, veszedelem támada rájok, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'Halljátok meg az Úr szavát, Jákób háza és Izráel házának minden nemzetsége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'Így szól az Úr: Micsoda hamisságot találtak bennem a ti atyáitok, hogy elidegenedtek tőlem, és hiábavalóság után jártak, és hiábavalókká lettek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'Még csak azt sem mondták: Hol van az Úr, a ki felhozott minket Égyiptom földéről, a ki vezérelt minket a pusztában, a kietlen és járatlan földön, a szomjúságnak és a halál árnyékának földén, a melyen nem vonult át ember, és a hol halandó nem lakott?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'És bevittelek titeket a bőség földébe, hogy annak gyümölcseivel és javaival éljetek; és bementetek, és megfertőztettétek az én földemet, és az én örökségemet útálatossá tevétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'A papok nem mondták: Hol van az Úr? A törvény magyarázói nem ismertek engem, és a pásztorok hűtelenekké lettek hozzám, a próféták pedig a Baál által prófétáltak, és azok után jártak, a kik tehetetlenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'Azért még perbe szállok veletek, mondja az Úr, és perelni fogok a ti fiaitok fiaival is!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, 'Menjetek csak át a Kittim szigeteire, és lássátok meg; és küldjetek Kédárba is és szorgalmasan vizsgálódjatok, és lássátok meg, ha volt-é ott ehhez hasonló?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'Ha cserélt-é valamely nemzet isteneket? noha azok nem istenek. Az én népem pedig felcserélte az ő dicsőségét tehetetlenséggel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'Álmélkodjatok ezen, oh egek, és borzadjatok és rémüljetek meg igen! azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, 'Mert kettős gonoszságot követett el az én népem: Elhagytak engem, az élő vizek forrását, hogy kútakat ássanak magoknak; és repedezett kútakat ástak, a melyek nem tartják a vizet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, 'Szolga-é Izráel, a vagy otthon szülött-é ő? Miért lett prédává?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'Oroszlánok ordítanak reá, megeresztik hangjokat, és sivataggá teszik földjét; városai szétromboltatnak, lakatlanok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'Nóf és Tahpan fiai is betörik koponyádat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, 'Vajjon nem te szerezted-é ezt magadnak? Elhagytad az Urat, a te Istenedet, a mikor vezérelt téged az úton!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, 'Most is mi dolgod van néked Égyiptom útjával? Hogy Nilus-vizet igyál? Vagy mi dolgod van néked Assúr útjával? Hogy a folyam vizét igyad?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, 'A magad gonoszsága fenyít meg téged, és a te elpártolásod büntet meg téged. Tudd meg hát és lásd meg: mily gonosz és keserves dolog, hogy elhagytad az Urat, a te Istenedet, és hogy nem félsz engemet, ezt mondja az Úr, a Seregeknek Ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, 'Bizony régóta széttörtem a te igádat, és letéptem köteleidet, és azt mondtad: Nem leszek rabszolga; mindamellett minden magas halmon és minden lombos fa alatt bujkálsz vala te, mint egy parázna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, 'Pedig én úgy plántállak vala el téged, mint nemes szőlővesszőt, mindenestől hűséges magot: mimódon változtál hát nékem idegen szőlőtőnek fattyú hajtásává?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, 'Még ha lúgban mosakodnál is, vagy szappanodat megsokasítanád is, feljegyezve marad a te álnokságod előttem, mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 23, 'Mimódon mondhatnád: Nem undokíttattam meg, nem jártam a Baálok után?! Lásd meg a te útadat a völgyben, ismerd meg csak: mit cselekedtél! Gyorslábú kancza-teve, a mely ide-oda futkos útain.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 24, 'Pusztához szokott nőstény vadszamár, a mely érzékiségének kívánságában levegő után kapkod. Gerjedelmét kicsoda csillapíthatja le? Senki ne fáraszsza magát, a ki ezt keresi, megtalálja ezt a maga hónapjában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 25, 'Tartóztasd meg lábadat a mezítelenségtől, és torkodat a szomjúságtól! És te azt mondod: Hiába, nem lehet! mert idegeneket szeretek, és utánok járok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 26, 'A miképen megszégyenül a tolvaj, ha rajtakapják, akképen szégyenül meg Izráel háza: ő maga, az ő királyai, fejedelmei, papjai és prófétái,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 27, 'A kik azt mondják a fának: Te vagy az én atyám! a kőnek pedig: Te szűltél engem! Bizony háttal fordulnak felém és nem arczczal, de nyomorúságuk idején azt mondják majd: Kelj föl és szabadíts meg minket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 28, 'De hol vannak a te isteneid, a melyeket magadnak készítél? Keljenek fel, ha megszabadíthatnak téged a te nyomorúságod idején; hiszen annyi istened volt, oh Júda, a hány városod!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 29, 'Miért perlekedtek velem? Mindnyájan hűtelenekké lettetek hozzám, mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 30, 'Hiába ostoroztam fiaitokat, a fenyítés nem fogott rajtok; fegyveretek úgy emésztette prófétáitokat, mint pusztító oroszlán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 31, 'Oh te nemzetség! Lásd meg az Úr dolgát! A puszta voltam-é én Izráelnek, avagy a setétség földje? Miért mondotta az én népem: Szabadok vagyunk, nem megyünk többé hozzád!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 32, 'Vajjon elfelejtkezik-é a lány az ő ékszereiről; a menyasszony az ő nyaklánczairól? Az én népem pedig számtalan napokon elfelejtett engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 33, 'Mit szépíted a te útadat, hogy te szeretetet keresel; holott még a gonoszokat is tanítod a te útaidra!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 34, 'Még ruháid szélén is található szegény, ártatlan emberek vére, nem azért, hogy betörésen kaptad őket, hanem mindamazokért!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 35, 'És azt mondod: Bizonyára ártatlan vagyok, hiszen elfordult tőlem az ő haragja! Ímé, én törvénybe szállok veled, mivelhogy azt mondod: Nem vétkeztem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 36, 'Mit futkosol oly igen, változtatván útadat? Égyiptom miatt is megszégyenülsz, a mint megszégyenültél Assúr miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 37, 'Még ettől is elszakadsz s kezeidet fejedre kulcsolod, mert útálja az Úr a te bizodalmasaidat, és nem leszel velök szerencsés.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, 'Nos hát! Ha elbocsátja valaki az ő feleségét, és ez eltávozik tőle és más férfiúé lesz: vajjon visszamehet-é még a férfi ő hozzá? Nem lenne-é az a föld fertelmesen megfertőztetve? Te pedig sok szeretővel paráználkodtál, és visszajönnél hozzám? mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, 'Emeld fel szemeidet a magaslatokra, és lásd meg: hol nem szeplősítettek meg téged? Az útakon vártál reájok, mint az arab a pusztában, és megfertőztetted a földet paráznaságaiddal és gonoszságoddal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'Noha megvonattak a korai záporok, és késői eső sem volt: mégis parázna asszony homlokúvá lettél, szégyenkezni nem akartál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'Nemde mostantól így kiáltasz nékem: Atyám! Ifjúságomnak te vagy vezére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, 'Mindörökké haragszik-é, mindvégig bosszankodik-é? Ímé, ezt mondod, de cselekszed a gonoszságokat, a mint tőled telik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'És monda az Úr nékem Jósiás király napjaiban: Láttad-é, a mit az elpártolt Izráel cselekedett? Elment ő minden magas hegyre és minden zöldelő fa alá, és ott paráználkodott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'És mondám, miután mindezt megcselekedte: Térj vissza hozzám! de nem tért vissza. És látta ezt az ő hitszegő húga, a Júda.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'És láttam, hogy mindamellett is, hogy elbocsátottam az elpártolt parázna Izráelt, és adtam néki elválásról való levelet: nem félt a hitszegő Júda, az ő húga, hanem elment, és ő is paráználkodott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'És lőn, hogy az ő paráznaságának hírével megfertőztette a földet; mert kővel és fával paráználkodott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, 'És mindez után sem tért vissza hozzám az ő hitszegő húga, a Júda, az ő szíve teljességével, hanem csak képmutatással, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'És monda nékem az Úr: Igazabb lelkű az elpártolt Izráel, mint a hitszegő Júda.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, 'Menj el, és kiáltsd e szókat észak felé, és mondjad: Térj vissza, elpártolt Izráel, ezt mondja az Úr, és nem bocsátom reátok haragomat, mert kegyelmes vagyok én, ezt mondja az Úr, nem haragszom mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, 'Csakhogy ismerd el a te hamisságodat, hogy hűtelenné lettél az Úrhoz, a te Istenedhez, és szertefutottál útaidon az idegenekhez mindenféle zöldelő fa alá, és az én szómra nem hallgattatok, ezt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, 'Térjetek meg, szófogadatlan fiak, azt mondja az Úr, mert én férjetekké lettem néktek, és magamhoz veszlek titeket, egyet egy városból, kettőt egy nemzetségből, és beviszlek titeket Sionba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, 'És adok néktek szívem szerint való pásztorokat, és legeltetnek tudománynyal és értelemmel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, 'És ha majd megsokasodtok és megszaporodtok a földön azokban a napokban, azt mondja az Úr, nem mondják többé: Az Úr szövetségének ládája! Szívére se veszi senki, rá se gondolnak, meg sem látogatják, és nem készítik meg újra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, 'Abban az időben Jeruzsálemet hívják majd az Úr királyiszékének, és minden nemzet oda gyülekezik az Úr nevéért Jeruzsálembe, és nem követik többé gonosz szívöknek makacsságát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, 'Azokban a napokban a Júda háza Izráel házával fog járni, és együtt mennek be az északi földről abba a földbe, a melyet örökségül adtam a ti atyáitoknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, 'Azt mondám ugyanis magamban: Miképen tegyelek téged a fiak közé, és adjam néked a kivánatos földet, a pogányok seregének drága örökségét? És azt végezém: Hívj engem atyámnak, és ne pártolj el tőlem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, 'Mindamellett a mint hitszegővé lesz az asszony az ő társa iránt: úgy lettetek hitszegőkké irántam, Izráel háza, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, 'Szó hallatszik a magaslatokon, Izráel fiainak esdeklő sírása, mert elfordították útjokat, elfelejtkeztek az Úrról, az ő Istenökről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 22, 'Térjetek vissza, szófogadatlan fiak, és meggyógyítom a ti elpártolástokat! Ímé, mi hozzád járulunk, mert te vagy az Úr, a mi Istenünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 23, 'Bizony hiábavaló a halmokról, a hegyekről való zajongás; bizony az Úrban, a mi Istenünkben van Izráel megmaradása!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 24, 'És ez a gyalázatosság emésztette a mi atyáink szerzeményét gyermekségünk óta: juhaikat, szarvasmarháikat, fiaikat és leányaikat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 25, 'Gyalázatunkban heverünk, és elborít minket a mi szégyenünk; mert vétkeztünk az Úr ellen, a mi Istenünk ellen: mi és a mi atyáink gyermekségünk óta mind e mai napig, és nem hallgattunk az Úrnak, a mi Istenünknek szavára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, 'Ha visszatérsz, Izráel, ezt mondja az Úr, hozzám térj vissza, és ha eltávolítod a te útálatosságaidat előlem és nem ingadozol;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'És így esküszöl: Él az Úr! hűségben, egyenességben és igazságban: akkor ő benne áldják majd magokat a nemzetek, és benne dicsekesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'Mert ezt mondja az Úr Júda és Jeruzsálem férfiainak: Szántsatok magatoknak új ugart, és ne vessetek tövisek közé!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'Metéljétek magatokat körül az Úrnak, és távolítsátok el szívetek előbőreit, Júda férfiai és Jeruzsálem lakosai, hogy fel ne gyúladjon az én haragom, mint a tűz, és olthatatlanul ne égjen a ti cselekedeteitek gonoszsága miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'Adjátok hírül Júdában, és hallassátok Jeruzsálemben és mondjátok, és kürtöljétek az országban; kiáltsátok teljes erővel, és mondjátok: Gyűljetek össze és menjünk be az erősített városokba!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'Emeljetek zászlót a Sion felé; fussatok, meg ne álljatok, mert veszedelmet hozok észak felől és nagy romlást!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'Felkelt az oroszlán az ő tanyájából, és a népek pusztítója elindult; kijött helyéből, hogy elpusztítsa a te földedet; városaid lerontatnak, lakatlanokká lesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'Öltözzetek azért gyászba, sírjatok és jajgassatok, mert az Úr haragjának tüze nem távozott el rólunk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, 'Azon a napon pedig, ezt mondja az Úr, elvész a király bátorsága és a főemberek bátorsága, és a papok elálmélkodnak, és a próféták elcsodálkoznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, 'Én pedig ezt mondom: Oh Uram Isten! Bizony igen megcsaltad ezt a népet, és Jeruzsálemet, ezt mondván: Békességtek lesz! holott a szablya lelkünkig hatott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, 'Abban az időben azt mondják e népnek és Jeruzsálemnek: Száraztó szél jő a magas helyekről a pusztában, az én népem leányának útján; nem szóráshoz és nem tisztításhoz való!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'Erős szél jő onnan reám is; azért hát ítéletet mondok ellenök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'Ímé! úgy jő fel, mint a felleg, és szekerei olyanok, mint a szélvész, lovai gyorsabbak a saskeselyűknél. Jaj nékünk, mert elvesztünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, 'Jeruzsálem, tisztítsd meg szívedet a gonoszságtól, hogy megtartassál! Meddig maradnak még te benned a te bűnös gondolataid?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'Mert hírmondó szava hangzik Dán felől, és Efraim hegyéről vészhirdető.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, 'Mondjátok meg a nemzeteknek; nosza, hirdessétek Jeruzsálem ellen: Őrizők jönnek messze földről, és kiáltoznak Júda városai ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, 'Mint a mezőnek őrizői, úgy lesznek ellene köröskörül, mert daczoskodott velem! mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, 'A te magad viselete és a te cselekedeteid szerezték ezeket néked; ez a gonoszságod bizony keserű, bizony egész a szívedig hatott!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, 'Oh én belsőm, oh én belsőm! Aléldozom, oh én szívemnek rekeszei! Háborog a szívem, nem hallgathatok! Hiszen hallottad én lelkem a kürt szavát, a harczi riadót!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, 'Vészre vészt jelentenek; bizony elpusztul az egész föld, nagy hamarsággal elpusztulnak az én sátraim, kárpitjaim egy pillantás alatt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, 'Meddig látok még hadi zászlót, és hallom a kürt szavát?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, 'Bizony bolond az én népem: engem nem ismernek, balgatag fiak ők, és nem értelmesek! Bölcsek ők a gonoszra, jót cselekedni pedig tudatlanok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, 'Nézek a földre, de ímé kietlen és puszta; és az égre, de nincsen világossága!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, 'Nézek a hegyekre is, ímé reszketnek; és a halmokra, de mind ingadoznak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, 'Nézek és ímé egy ember sincsen; és az ég madarai is mind elmenekültek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, 'Nézek, és ímé a bő termő föld pusztává lőn; és minden városa összeomlott az Úr előtt, az ő haragjának tüze előtt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 27, 'Bizony ezt mondja az Úr: Pusztasággá lesz az egész ország, de nem vetem végét!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 28, 'Azért gyászol a föld, és homályosodik el oda fenn az ég, mert szólottam, határoztam, és meg nem bánom és el nem térek attól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 29, 'A lovasoknak és a kézíveseknek kiáltozása elől elfut minden város, elrejtőznek a sűrűségekbe, és felmásznak a sziklákra: minden város elhagyottá lett, és egyetlen ember sem lakik azokban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 30, 'És te, elpusztult, mit cselekszel akkor? Ha bíborba öltözöl, ha arany kösöntyűkkel ékesíted magadat, és ha festékkel mázolod is ki szemeidet: hiába szépítgeted magadat! Megvetnek téged a szeretőid, életedre törnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 31, 'Mert mintha vajudó asszony szavát hallanám, mintha az először szűlőnek sikoltozását: olyan Sion leányának hangja; nyög, csapkodja kezeit: Jaj nékem! mert roskadozik lelkem a gyilkosok előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, 'Járjátok el Jeruzsálem utczáit, és nézzétek csak és tudjátok meg és tudakozzátok meg annak piaczain, ha találtok-é egy embert; ha van-é valaki, a ki igazán cselekszik, hűségre törekszik, és én megbocsátok néki!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'Még ha azt mondják is: Él az Úr! bizony hamisan esküsznek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'Uram! a te szemeid avagy nem a hűségre néznek-é? Megverted őket, de nem bánkódtak; tönkre tetted őket, de nem akarják felvenni a dorgálást; orczáik keményebbekké lettek a kősziklánál; nem akartak megtérni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'Én pedig ezt mondom vala: Bizony szerencsétlenek ezek; bolondok, mert nem ismerik az Úrnak útját, Istenöknek ítéletét!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'Elmegyek azért a főemberekhez, és beszélek velök; hiszen ők ismerik az Úrnak útját, Istenöknek ítéletét! Ámde ők törték össze egyetemlegesen az igát, és tépték le a köteleket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'Azért széttépi őket az oroszlán az erdőből, elpusztítja őket a puszták farkasa, párducz ólálkodik az ő városaik körül; a ki kijön azokból, mind szétszaggattatik; mert megsokasodtak az ő bűneik, és elhatalmasodtak az ő hitszegéseik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, 'Oh, miért bocsátanék meg néked? Fiaid elhagytak engem, és azokra esküsznek, a kik nem istenek; noha jól tartottam őket, mégis paráználkodtak és tolongtak a parázna házába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'Mint a hizlalt lovak, viczkándozókká lettek; kiki az ő felebarátjának feleségére nyerít.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'Avagy ne büntessem-é meg az ilyeneket, mondja az Úr, és az e féle népen, mint ez, ne álljon-é bosszút az én lelkem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, 'Menjetek fel az ő kerítéseire és rontsátok, de ne tegyétek semmivé egészen! Távolítsátok el az ágait, mert nem az Úréi azok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'Mert igen hűtelenné lett hozzám az Izráel háza és a Júda háza, azt mondja az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'Megtagadták az Urat, és azt mondták: Nincsen ő, és nem jöhet reánk veszedelem: sem fegyvert, sem éhséget nem látunk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'A próféták is széllé lesznek, és nem lesz, a ki beszéljen bennök: így esik az ő dolguk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, 'Azért ezt mondja az Úr, a Seregeknek Istene: Miután ti ilyen szóval szóltatok: ímé tűzzé teszem az én igémet a te szádban, ezt a népet pedig fákká, hogy megemészsze őket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, 'Ímé, én hozok reátok messzünnen való nemzetet, oh Izráel háza! ezt mondja az Úr. Kemény nemzet ez, ős időből való nemzet ez; nemzet, a melynek nyelvét nem tudod, és nem érted, mit beszél!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'Tegze olyan, mint a nyitott sír; mindnyájan vitézek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, 'És megemészti aratásodat és kenyeredet; megemészti fiaidat és leányaidat; megemészti juhaidat és ökreidet; megemészti szőlődet és fügédet; erősített városaidat, a melyekben te bizakodol, fegyverrel rontja le.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, 'De még ezekben a napokban sem teszlek benneteket egészen semmivé, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, 'Ha pedig az lenne, hogy kérdeznétek: Miért cselekedte mindezt velünk az Úr, a mi Istenünk? akkor azt mondjad nékik: A miképen elhagytatok engem és idegen isteneknek szolgáltatok a ti földeteken: azonképen idegeneknek fogtok szolgálni olyan földön, a mely nem a tiétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, 'Hirdessétek ezt a Jákób házában, és hallassátok Júdában, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, 'Halljátok csak, te bolond és esztelen nép, a kiknek szemeik vannak, de nem látnak; füleik vannak, de nem hallanak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, 'Nem féltek-é engem? ezt mondja az Úr. Az én orczám előtt nem remegtek-é? Hiszen én rendeltem a fövenyet a tenger határának örök korlátul, a melyet át nem hághat, és ha megrázkódtatják is habjai, de nem bírnak vele, és ha megháborodnak, sem hághatnak át rajta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, 'De ennek a népnek szilaj és daczos szíve van; elhajlottak és elmentek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 24, 'És még szívökben sem mondják: Oh, csak félnők az Urat, a mi Istenünket, a ki esőt, korai és késői záport ad annak idejében; az aratásnak rendelt heteit megőrzi számunkra!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 25, 'A ti bűneitek fordították el ezeket tőletek, és a ti vétkeitek fosztottak meg titeket e jótól!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 26, 'Mert istentelenek vannak az én népem között; guggolva fülelnek, mint a madarászok; tőrt hánynak, embereket fogdosnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 27, 'Mint a madárral teli kalitka, úgy vannak teli az ő házaik álnoksággal; ezért lettek nagyokká és gazdagokká!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 28, 'Meghíztak, megfényesedtek; eláradtak a gonosz beszédben; az árvának ügyét nem ítélik igaz ítélettel, hogy boldoguljanak; sem a szegényeknek nem szolgáltatnak igazságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 29, 'Hát ezeket ne büntessem-é meg, ezt mondja az Úr; az ilyen nemzeten, mint ez, avagy ne álljon-é bosszút az én lelkem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 30, 'Borzadalmas és rettenetes dolgok történnek e földön:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 31, 'A próféták hamisan prófétálnak, és a papok tetszésök szerint hatalmaskodnak, és az én népem így szereti! De mit cselekesznek majd utoljára?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'Benjámin fiai, fussatok ki Jeruzsálemből, és fújjatok kürtöt Thekoában, és tűzzetek ki zászlót Beth-Hakkeremben; mert veszedelem fenyeget észak felől és nagy romlás!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, 'A szép és elkényeztetett asszonyhoz tettem hasonlóvá Sion leányát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'Pásztorok jőnek el hozzá nyájaikkal együtt; felvonják mellette a sátrakat köröskörül; kiki legelteti, a mi keze ügyébe esik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, 'Készüljetek hadba ellene; keljetek fel, és menjünk fel délben! Jaj nékünk, mert hanyatlik már a nap, mert hosszabbodnak az esteli árnyékok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, 'Keljetek fel és menjünk fel éjjel, és rontsuk le az ő palotáit!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'Mert ezt mondja a Seregeknek Ura: Vágjatok fákat és hányjatok töltést Jeruzsálem ellen; a büntetés városa ez, csupa nyomorgatás van benne!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'Mint a kút hidegen tartja meg a vizét, úgy tartja meg az ő gonoszságát: erőszakosság és önkény hallatszik benne, és betegség és vereség van előttem szüntelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'Térj eszedre, oh Jeruzsálem, hogy el ne szakadjon tőled a lelkem; hogy pusztává ne tegyelek téged, lakhatatlan földdé!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'Ezt mondja a Seregek Ura: Teljesen megszedik Izráel maradékát, mint a szőlőt. Fordítsd kezedet reájok, mint a szőlőszedő a kosarakra!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'Kinek szóljak és kiket kérjek, hogy hallják? Ímé, az ő fülök körülmetéletlen és nem figyelhetnek! Ímé, az Úr szava útálatossággá lett előttök; nem gyönyörködnek abban:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'Azért telve vagyok az Úr haragjával, elfáradtam azt visszatartani! Öntsd ki a gyermekekre az utczán, és az ifjak gyülekezetére is egyszersmind; sőt még a férj a feleséggel, az öreg az aggastyánnal szintén fogattassanak el;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'És házaik idegenekre szálljanak, mezőik és feleségeik is egyszersmind; mert kinyújtom kezemet e föld lakosaira, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, 'Mert kicsinyeiktől fogva nagyjaikig mindnyájan telhetetlenségnek adták magokat; a prófétától fogva a papig mindnyájan csalárdságot űznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, 'És hazugsággal gyógyítgatják az én népem leányának romlását, mondván: Békesség, békesség, és nincs békesség!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, 'Szégyenkezniök kellene, hogy útálatosságot cselekedtek, de szégyenkezni nem szégyenkeznek, még pirulni sem tudnak; ezért elesnek majd az elesendőkkel; az ő megfenyíttetésök idején elhullanak, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, 'Így szólt az Úr: Álljatok az utakra, és nézzetek szét, és kérdezősködjetek a régi ösvények felől, melyik a jó út, és azon járjatok, hogy nyugodalmat találjatok a ti lelketeknek! És azt mondták: Nem megyünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, 'Őrállókat is rendeltem föléjök, mondván: Figyeljetek a kürtnek szavára! És azt mondták: Nem figyelünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, 'Azért halljátok meg, ti nemzetek, és tudd meg, te gyülekezet azt, a mi következik reájok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, 'Halld meg, oh föld! Ímé, én veszedelmet hozok erre a népre: az ő gondolatainak gyümölcsét; mert nem figyeltek az én beszédeimre, és az én törvényemet megvetették.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, 'Minek nékem ez a tömjén, a mi Sébából kerül, és a messze földről való jóillatú fahéj? A ti égőáldozataitok nincsenek kedvemre, sem a ti véres áldozataitok nem tetszenek nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, 'Azért ezt mondja az Úr: Ímé, én akadályokat szerzek e népnek, és megbotlanak bennök az atyák és fiak együttesen, a szomszéd és az ő barátja elvesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, 'Így szól az Úr: Ímé, nép jön el az északi földről, és nagy nemzet serken fel a földnek végéről!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, 'Kézívet és kopját ragad, kegyetlen az és nem könyörül; szavok zúg, mint a tenger, és lovakon nyargalnak, fejenként viadalra készen te ellened, oh Sion leánya!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, 'Halljuk a hírét: kezeink elesnek; szorongás vesz erőt rajtunk, reszketés, mint a vajudó asszonyon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, 'Ki ne menjetek a mezőre, és az úton se járjatok; mert ellenség fegyvere, rémület fenyeget köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, 'Népem leánya! Ölts gyászt, és heverj a porban, sírj, mint az egyszülöttet siratják, zokogj keservesen; mert reánk tör a pusztító hamar!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, 'Próbálóvá tettelek téged az én népem között; őrállóvá, hogy megismerd és megpróbáld az ő útjokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, 'Mindnyájan igen vakmerők, rágalmazva járnak, réz és vas; mindnyájan elvetemültek ők.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, 'Megégett a fúvó a tűztől, elfogyott az ón, hiába olvaszt az olvasztó, mert gonoszok, meg nem tisztíthatók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, 'Megvetett ezüstnek hívjátok őket, mert az Úr megvetette őket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'Az a beszéd, a melyet az Úr szóla Jeremiásnak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, 'Állj az Úr házának ajtajába, és kiáltsd ott e beszédet, és mondjad: Halljátok az Úr beszédét mind, ti Júdabeliek, a kik bementek ezeken az ajtókon, hogy imádjátok az Urat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'Így szól a Seregek Ura, Izráel Istene: Jobbítsátok meg a ti útaitokat és cselekedeteiteket, és veletek lakozom e helyen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'Ne bízzatok hazug beszédekben, mondván: Az Úr temploma, az Úr temploma, az Úr temploma ez!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'Mert csak ha valóban megjobbítjátok a ti útaitokat és cselekedeteiteket; ha igazán ítéltek az ember között és felebarátja között;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'Ha jövevényt, árvát és özvegyet meg nem nyomorgattok, és ezen a helyen ártatlan vért ki nem ontotok, és idegen istenek után sem jártok a magatok veszedelmére:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'Akkor lakozom veletek ezen a helyen, a földön, a melyet a ti atyáitoknak adtam, öröktől fogva mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'Ímé, ti hisztek a hazug beszédeknek, haszon nélkül!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'Nemde loptok, öltök és paráználkodtok, hamisan esküsztök, a Baálnak áldoztok és idegen istenek után jártok, a kiket nem ismertek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'És eljőtök, és megállotok előttem e házban, a mely az én nevemről neveztetik, és ezt mondjátok: Megszabadultunk; hogy ugyanazokat az útálatosságokat cselekedhessétek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'Vajjon latrok barlangjává lett-é ez a ház ti előttetek, a mely az én nevemről neveztetik? Ímé, én is látok, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, 'Mert menjetek csak el az én helyemre, a mely Silóban van, a hol először lakoztam az én nevemmel, és lássátok meg, hogy mit cselekedtem azzal az én népemnek, Izráelnek gonoszságáért!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'Most pedig, mivelhogy mindezeket a cselekedeteket megcselekszitek, azt mondja az Úr, és mivelhogy szüntelen szóltam, és szóltam ti néktek, de nem hallottátok, és kiáltottam néktek, de nem feleltetek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, 'Azért úgy cselekszem e házzal, a mely az én nevemről neveztetik, a melyben ti bizakodtok, és e hellyel, a melyet néktek és a ti atyáitoknak adtam, a mint Silóval cselekedtem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'És elvetlek titeket színem elől, a mint elvetettem mind a ti atyátokfiait, Efraimnak minden magvát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, 'És te ne imádkozzál e népért, se jajszót, se könyörgést ne emelj érettök, és nálam közben ne járj; mert én meg nem hallgatlak téged!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, 'Nem látod-é te: mit cselekesznek ők Júda városaiban és Jeruzsálem utczáin?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, 'A fiak fát szedegetnek, az atyák gyujtják a tüzet, az asszonyok pedig dagasztanak, hogy az ég királynőjének béleseket készítsenek, és az idegen isteneknek italáldozatokkal áldoznak, hogy engem felingereljenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, 'Avagy engem ingerelnek-é ők, azt mondja az Úr, és nem magokat-é, hogy gyalázat borítsa arczukat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, 'Azért ezt mondja az Úr Isten: Ímé az én haragom és búsulásom kiömlik e helyre, az emberekre és a barmokra, a mezőnek fáira és a földnek gyümölcseire, és égni fog, és el nem aluszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, 'Ezt mondja a Seregek Ura, Izráel Istene: Égőáldozataitokat rakjátok a ti véres áldozataitokhoz, és egyetek húst!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, 'Mert nem szóltam a ti atyáitokkal, és nem rendelkeztem velök, a mikor kihoztam őket Égyiptom földéről, az égőáldozat és véres áldozat felől;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, 'Hanem ezekkel a szavakkal utasítottam őket, mondván: Hallgassatok az én szómra, és én Istenetekké leszek, ti pedig az én népemmé lesztek, és mind csak azon az úton járjatok, a melyre utasítottalak titeket, hogy jól legyen dolgotok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, 'De nem hallgattak, és fülöket sem hajtották felém, hanem az ő gonosz szívök fásultságában a magok tanácsa szerint jártak, és háttal valának felém, és nem arczczal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, 'Attól a naptól fogva, a melyen kijöttek a ti atyáitok Égyiptom földéből e mai napig küldtem hozzátok minden én szolgámat, a prófétákat napról-napra, szüntelen küldöttem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 26, 'De nem hallgattak reám, és fülöket sem hajtották felém; hanem megkeményítették nyakukat, és gonoszabbul cselekedtek, mint az ő atyáik!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 27, 'Ha elmondod nékik mind e szavakat, és nem hallgatnak reád, ha kiáltasz nékik, és nem felelnek néked:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 28, 'Akkor ezt mondd nékik: Az a nép ez, a mely nem hallgat az Úrnak, az ő Istenének szavára, sem fenyítését fel nem veszi; elveszett a hűség; kiszaggattatott az ő szájokból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 29, 'Nyírd le hajadat és vesd el, és kezdj a hegyeken gyászéneket, mert útálja az Úr és elhagyja a nemzetséget, a melyre haragszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 30, 'Mert gonoszt műveltek előttem Júdának fiai, azt mondja az Úr; útálatosságaikat bevitték abba a házba, a mely az én nevemről neveztetik, hogy megfertőztessék azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 31, 'És felépítették a Tófet magaslatait, a mely a Ben-Hinnom völgyében van, hogy megégessék fiaikat és leányaikat tűzben, a mit nem parancsoltam, és a mi gondolatomban sem volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 32, 'Azért ímé eljőnek a napok, azt mondja az Úr, a mikor nem beszélnek többé a Tófetről, sem a Ben-Hinnom völgyéről, hanem az öldöklés völgyéről; és temetkezni fognak Tófetben, és hely sem lesz elég.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 33, 'És e nép holtteste az ég madarainak és a mezei barmoknak lesz eledelökké, és nem lesz, a ki elriassza azokat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 34, 'És megszüntetem Júda városaiban és Jeruzsálem utczáin az örömnek szavát és a vígasságnak szavát, a vőlegény szavát és a menyasszony szavát; mert elpusztul a föld!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, 'Abban az időben, azt mondja az Úr, kihányják majd Júda királyainak csontjait és az ő fejedelmeinek csontjait, a papok csontjait és a próféták csontjait és Jeruzsálem lakosainak csontjait az ő sírjaikból;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'És kiterítik azokat a napra és a holdra és az égnek minden serege elé, amelyeket szerettek, és a melyeknek szolgáltak, és a melyek után jártak, és a melyeket kerestek, és a melyek előtt leborultak; nem szedetnek össze, el sem temettetnek, ganéjjá lesznek a föld színén!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'És inkább választja a halált, mint az életet az egész maradék, mindazok, a kik megmaradtak a gonosz nemzetségből, mindazokon a helyeken; a hol megmaradtak, a hová kiűztem őket; azt mondja a Seregek Ura!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, 'Ezt is mondjad nékik: Így szól az Úr: Úgy esnek-é el, hogy fel nem kelhetnek? Ha elfordulnak, nem fordulhatnak-é vissza?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'Miért fordult el ez a nép, Jeruzsálem népe, örök elfordulással? A csalárdságnak adták magokat, visszafordulni nem akarnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'Figyeltem és hallottam: nem igazán beszélnek, senki sincs, a ki megbánja az ő gonoszságát, ezt mondván: Mit cselekedtem? Mindnyájan az ő futó-pályájokra térnek, mint a harczra rohanó ló.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'Még az eszterág is tudja a maga rendelt idejét az égben, és a gerlicze, a fecske és daru is megtartják, hogy mikor kell elmenniök, de az én népem nem tudja az Úr ítéletét!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'Hogyan mondhatjátok: Bölcsek vagyunk, és az Úr törvénye nálunk van? Bizony ímé hazugságra munkál az írástudók hazug tolla!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'Megszégyenülnek a bölcsek, megrémülnek és megfogattatnak! Ímé, megvetették az Úr szavát; micsoda bölcsességök van tehát nékik?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, 'Azért az ő feleségeiket idegeneknek adom, mezőiket hódítóknak; mert kicsinytől fogva nagyig mindnyájan nyereség után nyargalnak; a prófétától fogva a papig mindnyájan hamisságot űznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, 'És hazugsággal gyógyítgatják az én népem leányának romlását, mondván: Békesség, békesség, és nincs békesség!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, 'Szégyenkezniök kellene, hogy útálatosságot cselekedtek; de szégyenkezni nem szégyenkeznek, még pirulni sem tudnak: ezért elesnek majd az elesendőkkel; az ő megfenyíttetésök idején elhullanak, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, 'Végképen véget vetek nékik, azt mondja az Úr! Nincs gerezd a szőlőtőkén, nincs füge a fügefán, a levele is elhervadt; azt teszem azért, hogy tovavigyék őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, 'Miért ülünk még? Gyűljetek össze, és menjünk be az erősített városokba, és hallgassunk ott; mert az Úr, a mi Istenünk hallgatásra juttatott minket, és mérges vizet adott innunk; mert vétkeztünk az Úr ellen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, 'Miért békességre várni, holott nincs semmi jó; gyógyító időre, holott ímé itt van az ijedelem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, 'Dántól fogva hallatszik az ő lovainak tüsszögése; méneinek nyerítő hangjától reng az egész föld; és eljőnek és megemésztik e földet és mindenét, a mije van, a várost és annak lakóit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, 'Mert ímé, én vipera-kígyókat bocsátok reátok, a melyek ellen nincsen varázslás, és megmarnak titeket, azt mondja az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, 'Megnyugodhatom-é a nyomorúság felett? Szívem eleped én bennem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, 'Ímé, az én népem leányának kiáltó szava a messze földről: Nincsen-é ott az Úr a Sionon? Nincsen-é azon az ő királya? Miért ingereltek fel engem az ő faragott bálványaikkal, az idegen semmiségekkel?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, 'Elmult az aratás, elvégződött a nyár, és mi nem szabadultunk meg!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, 'Az én népem leányának romlása miatt megromlottam, szomorkodom, iszonyat fogott el engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, 'Nincsen-é balzsamolaj Gileádban? Nincsen-é ott orvos? Miért nem gyógyíttatott meg az én népem leánya?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, 'Bárcsak a fejem vízzé változnék, a szemem pedig könyhullatásnak kútfejévé, hogy éjjel-nappal sirathatnám az én népem leányának megöltjeit!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, 'Bárcsak pusztába vinne engem valaki, utasok szállóhelyére, hogy elhagyhatnám az én népemet, és eltávozhatnám tőlök; mert mindnyájan paráznák, hitszegők gyülekezete!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, 'Felvonták nyelvöket, mint kézívöket, hazugsággal és nem igazsággal hatalmasok e földön; mert gonoszságból gonoszságba futnak, engem pedig nem ismernek, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, 'Mindenki őrizkedjék a barátjától, és egyetlen atyátokfiának se higyjetek, mert minden atyafi cselbe csal, és minden barát rágalmazva jár.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, 'Egyik a másik ellen csúfoskodik, és nem szólnak igazat; nyelvöket hazug beszédre tanítják, elfáradtak a gonosztevésben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, 'A te lakásod az álnokság közepében van; az álnokság miatt nem akarnak tudni felőlem, ezt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, 'Azért ezt mondja a Seregek Ura: Ímé, én megolvasztom őket, és megpróbálom őket, mert mit cselekedjem egyebet az én népem leánya miatt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, 'Sebző nyíl a nyelvök, álnokságot beszél; szájával békességesen szól barátjához, a szívében pedig lest hány.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'Avagy ne fenyítsem-é meg őket ezekért? azt mondja az Úr; vajjon az efféle nemzetségen ne álljon-é bosszút a lelkem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, 'A hegyeken sírást és zokogást támasztok, és a pusztai ligetekben gyászéneket; mert kiégnek úgy, hogy senki se megy keresztül rajtok, és nem hallják a nyájak bégetését; az ég madaraitól fogva a barmokig minden elköltözik és elmenekül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, 'Jeruzsálemet pedig kőhalommá teszem, sakálok tanyájává, és Júda városait sivataggá változtatom, hogy lakatlan legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, 'Kicsoda olyan bölcs férfiú, hogy értse ezeket, és a kihez az Úr szája szólt, hogy hirdesse azt, hogy miért vész el a föld, és ég ki, mint a puszta, a melyen senki se menjen keresztül?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'Monda továbbá az Úr: Mivelhogy elhagyták az én törvényemet, a melyet eléjök adtam, és nem hallgattak az én szómra, és nem jártak a szerint;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, 'Hanem jártak az ő kevély szívök után és a Baálok után, a mikre atyáik tanították őket:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'Azért, ezt mondja a Seregek Ura, Izráel Istene: Ímé, én megétetem őket, ezt a népet, ürömmel, és megitatom őket mérges vízzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, 'És szétszórom őket a nemzetek között, a melyeket nem ismertek sem ők, sem atyáik, és utánok küldöm a fegyvert, a míg megsemmisítem őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, 'Ezt mondja a Seregek Ura: Figyelmezzetek reá, és hívjátok a sirató asszonyokat, hogy jőjjenek el, és a bölcs asszonyokhoz is küldjetek, hogy jőjjenek el,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, 'És siessenek és fogjanak síráshoz miattunk, és a mi szemeink is hullassanak könyeket, és szempilláink vizet ömleszszenek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, 'Mert a Sionról siralomnak szava hallatszik: Oh, hogy elpusztultunk! Igen megszégyenültünk, mert elhagyjuk e földet, mert széthányták lakhelyeinket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, 'Bizony halljátok meg, ti asszonyok, az Úrnak szavát, és vegye be a ti fületek az ő szájának beszédét, és tanítsátok meg leányaitokat a sírásra, és egyik asszony a másikat a jajgatásra;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, 'Mert feljött a halál a mi ablakainkra, bejött a mi palotáinkba, hogy kipusztítsa a gyermekeket az útakról, az ifjakat az utczákról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, 'Szólj! ezt mondja az Úr, és az emberek holtteste hever, mint a ganéj a mezőn, és mint a kéve az arató után, és nincs, a ki összegyűjtse.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, 'Ezt mondja az Úr: Ne dicsekedjék a bölcs az ő bölcseségével, az erős se dicsekedjék az erejével, a gazdag se dicsekedjék gazdagságával;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, 'Hanem azzal dicsekedjék, a ki dicsekedik, hogy értelmes és ismer engem, hogy én vagyok az Úr, a ki kegyelmet, ítéletet és igazságot gyakorlok e földön; mert ezekben telik kedvem, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, 'Ímé, eljőnek a napok, azt mondja az Úr, és megfenyítek minden körülmetélkedettet a körülmetéletlenekkel együtt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 26, 'Égyiptomot és Júdát, Edomot és az Ammon fiait, Moábot és mindazokat, a kik nyírott üstökűek és a pusztában laknak; mert mindez a nemzet körülmetéletlen, és Izráelnek egész háza is körülmetéletlen szívű.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, 'Halljátok meg a szót, a mit az Úr szól néktek, Izráel háza!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, 'Ezt mondja az Úr: A pogányok útját el ne tanuljátok, és az égi jelektől ne féljetek, mert a pogányok félnek azoktól!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, 'Mert a népek bálványai csupa hiábavalóság, hiszen az erdő fájából vágják azt; ács-mester kezei készítik bárddal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, 'Ezüsttel és aranynyal megékesíti azt, szegekkel és pőrölyökkel megerősítik, hogy le ne essék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'Olyanok, mint az egyenes pálmafa, és nem beszélnek; viszik-hordják őket, mert mozdulni nem tudnak. Ne féljetek tőlök, mert nem tehetnek rosszat; de jót tenni se képesek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'Nincs hozzád hasonló, Uram! Nagy vagy és nagy a te neved a te hatalmadért!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, 'Ki ne félne tőled, nemzetek királya? Bizony tiéd a tisztelet, mert a nemzetek minden bölcse közt és azok minden országában sincs hozzád hasonló!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, 'Mind egyig balgatagok és bolondok; hiábavalóságokra tanít; fa az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, 'Társisból hozott lapított ezüst és Ofirból való arany; az ácsnak és az ötvös kezének munkája; öltözetök kék és piros bíbor; mesterek munkája valahány.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, 'De az Úr igaz Isten, élő Isten ő, és örökkévaló király; az ő haragja előtt reszket a föld, és a nemzetek nem szenvedhetik el az ő felindulását.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, '(Mondjátok meg hát nékik: Az istenek, a kik az eget és földet nem alkották, el fognak veszni e földről és az ég alól!)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, 'Ő teremtette a földet az ő erejével, ő alkotta a világot az ő bölcseségével, és ő terjesztette ki az egeket az ő értelmével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, 'Szavára víz-zúgás támad az égben, és felhők emelkednek fel a föld határairól; villámlásokat készít az esőnek, és kihozza a szelet az ő rejtekhelyéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, 'Minden ember bolonddá lett, tudomány nélkül, minden ötvös megszégyenül az ő öntött képével, mert hazugság az ő öntése, és nincsen azokban lélek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, 'Hiábavalók azok, nevetségre való munka, elvesznek az ő megfenyíttetésök idején!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, 'Nem ilyen a Jákób része, mint ezek; mert a mindenség alkotója ő, és Izráel az ő örökségének pálczája; Seregek Ura az ő neve!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, 'Gyűjtsd össze a földről a te árúidat, a ki erősített városban lakozol!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, 'Mert ezt mondja az Úr: Ímé, én elvetem ezúttal e föld lakosait, és megsanyargatom őket, hogy megtaláljanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, 'Jaj nékem az én romlásom miatt, gyógyíthatatlan az én sebem! De azt mondom mégis: Bizony ilyen az én vereségem, és szenvedem azt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, 'Sátorom elpusztíttatott, köteleim mind elszakadoztak, fiaim elszakadtak tőlem és oda vannak ők; nincs többé, a ki kifeszítse sátoromat, és felvonja kárpitjaimat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, 'Mert oktalanok voltak a pásztorok, és nem keresték az Urat; ezért nem lettek szerencsésekké, és minden nyájuk szétszóratott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 22, 'A hír hangja ímé megjött, és nagy zúgás kél észak földe felől, hogy pusztává tegyék Júdának városait, és sakálok tanyájává.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 23, 'Tudom Uram, hogy az embernek nincs hatalmában az ő útja, és egyetlen járókelő sem teheti, hogy irányozza a maga lépését!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 24, 'Fenyíts meg engem, Uram, de mértékkel, nem haragodban, hogy szét ne morzsolj engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 25, 'Öntsd ki haragodat ama nemzetekre, a melyek nem ismernek téged, és ama nemzetségekre, a melyek nem hívják segítségül a te nevedet; mert megették Jákóbot, bizony megették őt, és elemésztették őt, és lakóhelyét elpusztították!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, 'Az a beszéd, a melyet az Úr beszélt Jeremiásnak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, 'Halljátok meg e szövetség igéit, és beszéljétek el Júda férfiainak és Jeruzsálem lakosainak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, 'Ezt mondjad azért nékik: Így szól az Úr, Izráelnek Istene: Átkozott mindenki, a ki meg nem hallja e szövetségnek igéit,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'A melyet akkor parancsoltam a ti atyáitoknak, a mikor kihoztam őket Égyiptom földéről, a vaskemenczéből, mondván: Halljátok meg az én szómat, és cselekedjétek mindazokat, a miket én parancsolok néktek, és népemmé lesztek, én pedig Istenetekké leszek néktek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'Hogy beteljesítsem az esküvést, a melylyel megesküdtem a ti atyáitoknak, hogy nékik adom a téjjel és mézzel folyó földet, a mint most van ez! És felelék, és mondám: Ámen, Uram!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'És monda az Úr nékem: Kiáltsd mindez igéket Júda városaiban és Jeruzsálem utczáin, mondván: Halljátok e szövetség igéit, és cselekedjétek azokat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'Mert kérve kértem a ti atyáitokat, a mikor felhoztam őket Égyiptom földéről, mind e napig, szünetlenül kérvén és mondván: Halljátok meg az én szómat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, 'De nem hallották, még fülöket sem hajtották arra, hanem ment kiki az ő gonosz szívének hamissága után, és rájok szabtam e szövetségnek minden igéjét, a melyeket azért parancsoltam, hogy megcselekedjék, de nem cselekedték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'És monda az Úr nékem: Pártütés van a Júda férfiai és Jeruzsálem lakosai között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, 'Visszatértek az ő atyáiknak elébbi bűneire, a kik nem akarták hallani az én igéimet, és ők magok is idegen istenek után járnak, hogy azoknak szolgáljanak. Izráel háza és Júda háza megszegte az én szövetségemet, a melyet az ő atyáikkal kötöttem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, 'Azért ezt mondja az Úr: Ímé, én veszedelmet hozok reájok, a melyből ki nem menekülhetnek, és kiáltanak majd én hozzám, de nem hallgatom meg őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, 'És elmennek Júda városai és Jeruzsálem lakosai, és kiáltanak az istenekhez, a kiknek ők áldozni szoktak, de azok nem oltalmazzák meg őket az ő nyomorúságuk idején.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, 'Mert városaidnak száma szerint voltak néked isteneid, oh Júda, és Jeruzsálem utczáinak száma szerint készítettétek a gyalázatnak oltárait, az oltárokat, hogy áldozzatok a Baálnak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, 'Te azért ne esdekelj e népért, és egy kiáltó és esdeklő szót se ejts érettök, mert én meg nem hallgatom őket, mikor kiáltanak majd hozzám az ő nyomorúságuk miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, 'Mi köze az én kedveltemnek az én házamhoz? Temérdek istentelenséget cselekedtél; a szent húst abbahagytad; mikor gonoszságban vagy, akkor örvendezel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, 'Lombos, szép formás gyümölcsű olajfa nevet adott néked az Úr. Nagy vihar morajánál tüzet gyújta rajta, és leromlottak az ágai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, 'A Seregek Ura, a ki plántált téged, rosszat végzett felőled Izráel házának és Júda házának rosszasága miatt, a mit elkövettek magokban, hogy engemet haragra ingereljenek, áldozván a Baálnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, 'Az Úr tudtul adta nékem, és én tudtam; te láttattad meg velem az ő cselekedeteiket is!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, 'Én pedig olyan valék, mint a mészárszékre hurczolt szelíd bárány, és nem tudtam, hogy terveket szőttek ellenem, mondván: Pusztítsuk el e fát gyümölcsével együtt; irtsuk ki ezt az élők földéből, hogy még a nevét se emlegessék többé!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, 'És oh Seregek Ura, igaz biró, veséknek és szívnek vizsgálója: hadd lássam a te bosszúállásodat rajtok, mert néked jelentettem meg az én ügyemet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, 'Azért ezt mondja az Úr az Anatóthbeli embereknek, a kik életedre törnek és ezt mondják: Ne prófétálj az Úr nevében, hogy meg ne halj a mi kezünk által!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, 'Azért ezt mondja a Seregek Ura: Ímé, én megfenyítem őket; az ifjak fegyver által halnak meg, fiaik és leányaik pedig meghalnak éhen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, 'És senki sem marad meg közülök, hogyha veszedelmet hozok az Anatóthbeli emberekre, az ő büntetésök esztendejét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, 'Igaz vagy Uram, hogyha perlek is veled; éppen azért hadd beszélhessek veled peres kérdésekről! Miért szerencsés az istentelenek útja? Miért vannak békességben mindnyájan a hűtlenkedők?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, 'Beplántálod őket, meg is gyökereznek; felnevekednek, gyümölcsöt is teremnek; közel vagy te az ő szájokhoz, de távol vagy az ő szívöktől!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'Engem pedig ismersz te, Uram! látsz engem, és megvizsgáltad irántad való érzésemet: szakítsd külön őket, mint a mészárszékre való juhokat, és készítsd őket a megölésnek napjára!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'Meddig gyászoljon a föld, és meddig száradjon el minden fű a mezőn? A benne lakók gonoszsága miatt pusztul el barom és madár; mert azt mondják: Nem látja meg a mi végünket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, 'Hogyha gyalogokkal futsz, és elfárasztanak téged: mimódon versenyezhetnél a lovakkal? És ha csak békességes földön vagy bátorságban: ugyan mit cselekednél a Jordán hullámai között?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, 'Bizony még a te atyádfiai és a te atyádnak háznépe is: ők is hűtlenül bántak veled; ők is tele torokkal kiabáltak utánad! Ne higyj nékik, még ha szépen beszélgetnek is veled!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, 'Elhagytam házamat; ellöktem örökségemet, ellenségének kezébe adtam azt, a kit lelkem szeret.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, 'Az én örökségem olyanná lett hozzám, mint az oroszlán az erdőben; ordítva támadt ellenem; ezért gyűlölöm őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, 'Tarka madár-é az én örökségem nékem? Nem gyűlnek-é ellene madarak mindenfelől? Jőjjetek, seregeljetek össze mind ti mezei vadak; siessetek az evésre!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, 'Sok pásztor pusztította az én szőlőmet, taposta az én osztályrészemet; az én drága örökségemet sivatag pusztává tették!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, 'Pusztává tették, felém sír, mint puszta! Elpusztíttatik az egész föld, mert nincs senki, a ki eszére térjen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, 'A pusztában levő minden magaslatra pusztítók érkeznek, mert az Úr fegyvere emészt a föld egyik szélétől a föld másik széléig; senkinek sem lesz békessége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, 'Búzát vetettek és tövist aratnak; fáradnak, de nem boldogulnak, és szégyent vallotok a ti jövedelmetekkel az Úr haragjának búsulása miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, 'Ezt mondja az Úr minden én gonosz szomszédom felől, a kik hozzányúlnak az én örökségemhez, a melyet örökségül adtam az én népemnek, Izráelnek: Ímé, én kigyomlálom őket az ő földükből, és Júda házát is kigyomlálom közülök!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, 'És azután, ha majd kigyomlálom őket, ismét könyörülök rajtok, és visszahozom őket, kit-kit az ő örökségébe, és kit-kit az ő földére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, 'És ha megtanulják az én népemnek utait, és az én nevemre esküsznek ilyen módon: Él az Úr! a mint megtanították népemet megesküdni a Baálra: akkor felépülnek majd népem között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, 'Ha pedig nem hallgatnak meg, akkor bizony kigyomlálom azt a népet, és elvesztem, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, 'Ezt mondá az Úr nékem: Menj el, és vásárolj magadnak lenövet, és illeszd azt a derekadra, de vízbe ne vidd be azt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'És megvásároltam az övet, a mint az Úr rendelte vala, és derekamra illesztém.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'És másodszor szól vala az Úr hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, 'Vedd az övet, a melyet vásároltál, a mely a derekadon van, és kelj fel, és menj az Eufrateshez, és rejtsd el azt ott a kőszikla hasadékában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'És elmenék, és elrejtém azt az Eufratesnél, a mint megparancsolta nékem az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'Sok nap mulva pedig újra monda nékem az Úr: Kelj fel, menj az Eufrateshez, és vedd el onnan az övet, a mely felől parancsoltam, hogy ott rejtsd el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'És elmenék az Eufrateshez, és kiásám, és kivevém arról a helyről az övet, a hová elrejtettem azt, és ímé, az öv rothadt vala, egészen hasznavehetetlen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, 'És szóla az Úr nékem, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, 'Ezt mondja az Úr: Így rothasztom meg a Júda kevélységét, és a nagy Jeruzsálem kevélységét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, 'Ez a gonosz nép, a mely nem akar hallgatni az én beszédeimre, a mely a maga szívének hamisságában jár, és jár idegen istenek után, hogy azoknak szolgáljon, és azokat imádja: olyanná lesz majd, mint ez az öv, a mely egészen hasznavehetetlen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, 'Mert a miként derekára kapcsolja a férfi az övet; akként kapcsoltam magamhoz Izráelnek egész házát és Júdának egész házát, azt mondja az Úr, hogy legyenek az én népemmé, az én nevemre, dicséretemre és tisztességemre, de nem engedelmeskedtek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, 'Ilyen szókkal szólj azért nékik: Ezt mondja az Úr, Izráelnek Istene: Minden tömlőt meg kell tölteni borral! És azt mondják néked: Avagy nem tudjuk-é jól, hogy minden tömlőt borral kell megtölteni?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, 'Te pedig azt mondd nékik: Ezt mondja az Úr: Ímé betöltöm e földnek minden lakosát, és a királyokat, a kik Dávid trónján ülnek, és a papokat, a prófétákat, és Jeruzsálemnek minden lakosát részegséggel;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, 'És összeütöm őket, egyiket a másikhoz, az atyákat és a fiakat együtt, azt mondja az Úr; nem kegyelmezek meg, és nem kedvezek, és nem leszek irgalmas, hogy el ne veszítsem őket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, 'Hallgassatok és figyelmezzetek; ne fuvalkodjatok fel, mert az Úr szólott!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, 'Dicsőítsétek az Urat, a ti Isteneteket, mielőtt setétséget szerezne, és mielőtt megütnétek lábaitokat a setét hegyekben; mert világosságot vártok, és halál árnyékává változtatja azt, és sűrű homálylyá fordítja!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, 'Ha pedig nem hallgatjátok ezt: sírni fog az én lelkem a rejtekhelyeken a ti kevélységtek miatt, és zokogva zokog; a szemem pedig könyeket hullat, mert az Úr népe fogságba vitetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, 'Mondd meg a királynak és a királynéasszonynak: Alázzátok meg magatokat, és üljetek veszteg, mert leesik fejetekről a ti dicsőségtek koronája!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, 'A dél felől való városok bezároltatnak, és nem lesz, a ki megnyissa azokat; fogságra vitetik Júda egészen, fogságra vitetik mindenestül!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, 'Emeljétek fel szemeiteket, és nézzétek azokat, a kik északról jőnek! Hol van a nyáj, a mely néked adatott, a te dicsőségednek juhnyája?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, 'Mit mondasz, hogy ha megfenyít téged? Hiszen te oktattad őket magad ellen, fejedelmekké tetted fejeden! A fájdalmak nem környékeznek-é még téged, mint a szülőasszonyt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, 'És ha azt mondod a te szívedben: Miért következnének ezek reám? A te hamisságod sokaságáért takartatik fel a te ruhád, és lesznek mezítelenekké a te sarkaid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, 'Elváltoztathatja-é bőrét a szerecsen, és a párducz az ő foltosságát? Úgy ti is cselekedhettek jót, a kik megszoktátok a gonoszt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, 'Azért szétszórom őket, a mint hányja-veti a pozdorját a pusztának szele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, 'Ez a te sorsod, a te kimért részed én tőlem, ezt mondja az Úr, a ki elfelejtkeztél én rólam, és hittél a hazugságnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 26, 'Azért én is arczodra borítom fel a te ruhádat, hogy látható legyen a te gyalázatod!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 27, 'A te paráznaságaidat és nyihogásaidat, bujálkodásodnak undokságát: a halmokon, a mezőn láttam a te útálatosságaidat. Jaj néked Jeruzsálem! Nem leszel tiszta ezután se? Meddig még?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, 'Az Úrnak szava, a mit Jeremiásnak szólott a szárazság felől:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, 'Gyászol Júda, és kapui roskadoznak; szomorkodnak a földön, és Jeruzsálem kiáltása felszáll.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'Fejedelmeik is kiküldik gyermekeiket vízért: elmennek a kútakig, nem találnak vizet; visszatérnek üres edényekkel; szégyenkeznek és pironkodnak, és befedik fejöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, 'A föld miatt, a mely retteg, mert nem esett eső a földön, szégyenkeznek a szántóvetők, és befedik fejöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'Még a szarvas-üsző is megellik a mezőn, és ott hagyja fiát, mert nincsen fű.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, 'A vadszamarak pedig a sziklához állanak, levegő után kapkodnak, mint a tengeri szörnyek, szemeik eltikkadnak, mert nincs fű.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, 'Ha bűneink ellenünk tanúskodnak: cselekedjél Uram a te nevedért, mert temérdek a mi törvényszegésünk; vétkeztünk ellened!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, 'Izráel reménysége, megszabadítója a nyomorúság idején! Miért vagy e földön úgy, mint valami jövevény és mint valami utas, a ki éjjeli szállásra tér be?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, 'Miért vagy olyan, mint a megriasztott férfi; mint a vitéz, a ki nem tud segíteni? Hiszen te közöttünk vagy, Uram, és mi a te nevedről neveztetünk; ne hagyj el minket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, 'Ezt mondja az Úr e népnek: Úgy szerettek ide-oda futkározni, lábaikat meg nem tartóztatták! Azért az Úr nem kedvelte őket. Most megemlékezik az ő bűnökről, és vétkeikért megfenyíti őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, 'És mondá nékem az Úr: Ne könyörögj e népért, az ő javára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, 'Mikor bőjtölnek, én meg nem hallgatom kiáltozásukat, és ha égőáldozatot vagy ételáldozatot készítenek, nem lesznek kedvesek előttem; sőt fegyverrel, éhséggel és döghalállal irtom ki őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, 'És mondék: Ah, Uram Isten! Hiszen a próféták mondják vala nékik: Fegyvert nem láttok, éhség sem lesz rajtatok, sőt állandó békességet adok néktek ezen a helyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, 'És monda az Úr nékem: Hazugságot prófétálnak a próféták az én nevemben; nem küldtem őket, nem parancsoltam nékik, nem is beszéltem velök; hazug látomást, varázslást, hiábavalóságot és szívbeli csalárdságot jövendölnek néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, 'Azért ezt mondja az Úr a próféták felől, a kik az én nevemben prófétálnak, holott én nem küldtem őket és mégis azt mondják: fegyver és éhség nem lesz e földön: Fegyver és éhség miatt vesznek el azok a próféták!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, 'A nép pedig, a melynek ők prófétálnak, ott hever majd Jeruzsálem utczáin az éhség és a fegyver miatt, és nem lesz, a ki eltemesse őket, őket és feleségeiket, fiaikat és leányaikat; így zúdítom rájok gonoszságukat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, 'Azért e szavakat mondjad nékik: Szemeim könyeket hullatnak éjjel és nappal, és nem szünnek meg; mert nagy rontással rontatott meg a szűz, az én népemnek leánya, igen fájdalmas vereséggel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, 'Ha kimegyek a mezőre, hát ímé fegyver által levágottak; ha bemegyek a városba, hát ímé éhség miatt elepedtek vannak ott! Bizony próféta is, pap is olyan földre költöznek, a melyet nem ismernek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, 'Egészen elvetetted-é Júdát, avagy a Siont útálja-é lelked? miért vertél úgy meg, hogy semmi orvosságunk se legyen? Békességet vártunk, de nincs semmi jó; és gyógyulásnak idejét, de ímé, itt van a rettegés!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, 'Ismerjük Uram a mi gonoszságainkat, atyáink bűnét; bizony vétkeztünk ellened!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 21, 'Ne vesd meg a te nevedért; ne gyalázd meg a te dicsőségednek székét! Emlékezzél; ne rontsd meg a te velünk való szövetségedet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 22, 'Vannak-é a pogányok bálványai között, a kik esőt adhatnak? És ad-é záporokat az ég? Avagy nem te vagy-é a mi Urunk Istenünk, és nem benned kell-é bíznunk, hiszen te cselekedted mindezt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'És monda az Úr nékem: Ha Mózes és Sámuel állanának is előttem, nem hajolna lelkem e néphez; küldd ki az orczám elől, hadd menjenek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, 'Ha pedig ezt mondják néked: Hová menjünk? ezt mondjad nékik: Így szól az Úr: A ki halálra való, halálra; a ki fegyverre való, fegyverre; a ki éhségre való, éhségre, és a ki fogságra való, fogságra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'Mert négyfélével támadok reájok, ezt mondja az Úr: Fegyverrel, hogy gyilkoljon, kutyákkal, hogy tépjenek, az ég madaraival és a mezei vadakkal, hogy egyenek és pusztítsanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, 'Bújdosókká teszem őket e földnek minden országában Manasséért, Ezékiásnak, Júda királyának fiáért, azok miatt, a miket ő Jeruzsálemben cselekedett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'Mert ki könyörül meg rajtad Jeruzsálem, és ki vígasztal meg téged, és ki mozdul meg, hogy kérdezze: jól vagy-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, 'Te elhagytál engem, azt mondja az Úr, másfelé jártál; azért kinyújtom kezemet ellened, és elvesztelek téged; belefáradtam a szánakozásba!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'Elszórom őket szórólapáttal e földnek kapuiban; gyermektelenné teszem, elvesztem az én népemet; nem tértek vissza útaikról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, 'Özvegyei számosabbak lesznek a tenger fövenyénél; pusztítót viszek reájok, az ifjúság anyjára délben; bocsátok reája nagy hirtelen észvesztést és rettentéseket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, 'Elsenyved, a ki hét fiút szűl; kileheli lelkét; lehanyatlik az ő napja, mikor még nappal volna; megszégyenül és pironkodik; a maradékaikat pedig fegyverre vetem az ő ellenségeik előtt, azt mondja az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, 'Jaj nékem, anyám, mert versengés férfiává és az egész föld ellen perlekedő férfiúvá szültél engemet! Nem adtam kölcsönt és nékem sem adtak kölcsönt: mégis mindnyájan szidalmaznak engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, 'Monda az Úr: Avagy nem jóra tartalak-é meg téged? Avagy nem azt teszem-é, hogy ellenséged a baj idején és nyomorúság idején kérni fog téged?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, 'Vajjon eltöri-é a vas az északi vasat és rezet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, 'Vagyonodat és kincseidet rablónak adom, nem pénzért, hanem a te mindenféle vétkedért, minden határodban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, 'És elvitetlek ellenségeiddel olyan földre, a melyet nem ismersz, mert haragomnak tüze felgerjedt, lángra gyúlt ellenetek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, 'Te tudod, Uram! Emlékezzél meg rólam és tekints reám, és állj bosszút értem üldözőimen; a te haragodnak halogatásaival ne ejts el engem; tudd meg, hogy éretted szenvedek gyalázatot!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, 'Ha szavaidat hallattad, én élveztem azokat; a te szavaid örömömre váltak nékem és szívemnek vígasságára; mert a te nevedről neveztetem oh Uram, Seregeknek Istene!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, 'Nem ültem a nevetgélők gyülekezetében, és nem ujjongtam velök; a te hatalmad miatt egyedül ültem, mert bosszúsággal töltöttél el engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, 'Miért lett szünetlenné az én fájdalmam, és halálossá, gyógyíthatatlanná az én sebem? Olyanná lettél nékem, mint a bizonytalan vizű, csalóka patak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, 'Azért ezt mondja az Úr: Ha megtérsz, én is visszatérítelek téged, előttem állasz; és ha elválasztod a jót a hitványtól, olyanná leszel, mint az én szájam. Ők térjenek meg te hozzád, de te ne térj ő hozzájok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, 'És e nép ellen erős érczbástyává teszlek téged, és viaskodnak ellened, de nem győzhetnek meg téged, mert én veled vagyok, hogy megvédjelek és megszabadítsalak téged, azt mondja az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, 'És megszabadítlak téged a gonoszok kezeiből, és kimentelek téged a hatalmaskodók markából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, 'Majd szóla az Úr nékem, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, 'Ne végy magadnak feleséget, és ne legyenek néked fiaid és leányaid ezen a helyen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, 'Mert ezt mondja az Úr a fiak felől és leányok felől, a kik ezen a helyen születnek, és anyjaik felől, a kik szülik őket, és atyjaik felől, a kik nemzették őket e földön:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, 'Keserves halállal halnak meg, nem sirattatnak el és el sem temettetnek; ganéjjá lesznek a föld színén, s fegyver és éhség miatt pusztulnak el, és az ő holttestök az ég madarainak és a mezei vadaknak lesznek eledelül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'Mert ezt mondja az Úr: Ne menj be gyászoló házba, se sírni ne menj, se ne vígasztald őket; mert megvontam e néptől az én békességemet, azt mondja az Úr: az irgalmasságot és kegyelmet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, 'És meghalnak nagyok és kicsinyek e földön; el sem temetik, meg sem siratják őket, sem össze nem metélik magokat, sem hajokat ki nem tépik ő érettök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, 'Kenyeret sem törnek nékik a gyászoláskor, hogy vígasztalják őket a meghaltért; a vígasztalás poharával sem itatják őket az ő atyjokért és anyjokért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, 'A lakodalmas házba se menj be, hogy leülj velök enni és inni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, 'Mert azt mondja a Seregek Ura, Izráelnek Istene: Ímé, én megszüntetem e helyen, a ti szemeitek előtt, a ti napjaitokban a vigasságnak szavát és az örömnek szavát, a vőlegénynek szavát és a menyasszonynak szavát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, 'És hogyha tudtára adod e népnek mind e határozatokat, és ezt mondják néked: Miért határozta az Úr ellenünk mindezt a nagy gonoszt; és micsoda a mi bűnünk és micsoda a mi vétkünk, a melylyel vétkeztünk az Úr ellen, a mi Istenünk ellen?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, 'Akkor ezt mondd nékik: Azért, mert elhagytak engem a ti atyáitok, azt mondja az Úr, és idegen istenek után jártak, és azoknak szolgáltak és azokat imádták, engem pedig elhagytak, és az én törvényemet meg nem tartották.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, 'És ti gonoszabbul cselekedtetek, mint atyáitok; mert ímé, ti mindnyájan a ti gonosz szívetek hamisságát követitek, nem hallgatva reám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, 'Azért kivetlek titeket e földből arra a földre, a melyet sem ti nem ismertek, sem a ti atyáitok, és ott szolgáltok majd idegen isteneknek nappal és éjjel; mivelhogy nem könyörülök rajtatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, 'Azért ímé, eljőnek a napok, ezt mondja az Úr, a mikor nem mondják többé; Él az Úr, a ki felhozta Izráel fiait Égyiptom földéről;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'Hanem ezt: Él az Úr, a ki felhozta Izráel fiait északnak földéről és mindama földekről, a melyekbe elszórta őket! Mert visszaviszem őket az ő földjükre, a melyet az ő atyáiknak adtam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, 'Ímé én sok halász után küldök, ezt mondja az Úr, hogy halászszák ki őket; azután pedig elküldök sok vadász után, hogy vadászszák ki őket minden hegyből, minden halomból és a sziklák hasadékaiból is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, 'Mert szemmel tartom minden útjokat; nem rejtőzhettek el orczám elől, és nincsen elfedve az ő bűnök szemeim elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, 'Előbb azonban megfizetek nékik az ő bűneikért és vétkeikért kétszeresen, mert megszentségtelenítették az én földemet az ő útálatosságaiknak holttestével, és betöltötték az én örökségemet az ő fertelmességeikkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, 'Oh Uram, én erősségem, én bástyám és én menedékem a nyomorúság idején! Hozzád jőnek majd a nemzetek a föld határairól, és ezt mondják: Bizony hamis isteneket bírtak a mi atyáink és hiábavalókat, mert nincs köztük segíteni tudó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, 'Csinálhat-é az ember magának isteneket? Hiszen azok nem istenek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, 'Azért ímé, megismertetem velök ez úttal, megismertetem velök az én kezemet és hatalmamat, és megtudják, hogy az Úr az én nevem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, 'A Júda vétke vas tollal, gyémánt hegygyel van felírva; fel van vésve szívök táblájára és oltáraik szarvaira,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, 'Mivelhogy megemlékeznek fiaik az ő oltáraikról, Aséra bálványaikról a zöld fák mellett és a magas halmokon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, 'Oh én hegyem a síkon! Vagyonodat, minden kincsedet prédává teszem a te magaslataidért, minden határodban való vétkeidért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'És elszakíttatol, és pedig magad által, a te örökségedtől, a melyet én adtam néked, és szolgáltatni fogom veled a te ellenségeidet olyan földön, a melyet nem ismersz; mert tűzre lobbantottátok haragomat, örökké égni fog.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'Ezt mondja az Úr: Átkozott az a férfi, a ki emberben bízik és testbe helyezi erejét, az Úrtól pedig eltávozott az ő szíve!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, 'Mert olyanná lesz, mint a hangafa a pusztában, és nem látja, hogy jó következik, hanem szárazságban lakik a sivatagban, a sovány és lakhatatlan földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'Áldott az a férfi, a ki az Úrban bízik, és a kinek bizodalma az Úr;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, 'Mert olyanná lesz, mint a víz mellé ültetett fa, a mely a folyó felé bocsátja gyökereit, és nem fél, ha hőség következik, és a levele zöld marad; és a száraz esztendőben nem retteg, sem a gyümölcsözéstől meg nem szűnik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, 'Csalárdabb a szív mindennél, és gonosz az; kicsoda ismerhetné azt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, 'Én, az Úr vagyok az, a ki a szívet fürkészem és a veséket vizsgálom, hogy megfizessek kinek-kinek az ő útai szerint és cselekedeteinek gyümölcse szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, 'Mint a fogoly madár, mely fiakat gyűjt, melyeket nem ő költött, olyan, a ki gazdagságot gyűjt, de nem igazán; az ő napjainak felén elhagyja azt, a halálakor pedig bolonddá lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, 'Óh dicsőség trónja, kezdettől fogva magasságos, szentségünknek helye.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'Izráelnek reménysége, oh Uram! A kik elhagynak téged, mind megszégyenülnek! A kik elpártolnak tőlem, a porba iratnak be, mert elhagyták az élő vizeknek kútfejét, az Urat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'Gyógyíts meg engem Uram, hogy meggyógyuljak, szabadíts meg engem, hogy megszabaduljak, mert te vagy az én dicsekedésem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, 'Ímé, ők azt mondják nékem: Hol van az Úr szózata? Most jőjjön el!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, 'De én nem siettem elhagyni a te útaidnak követését, sem gonosz napot nem kívántam, te tudod; a mi ajkaimon jött ki, nyilvánvaló volt előtted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, 'Ne légy nékem rettentésemre: reménységem vagy te a háborúság napján!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, 'Szégyenüljenek meg, a kik üldöznek engem, de ne én szégyenüljek meg; ők rettegjenek és ne én rettegjek; hozz reájok háborúság napját, és kétszeres zúzással zúzd össze őket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'Ezt mondá nékem az Úr: Menj és állj meg a nép fiainak kapujában, a melyen bemennek és a melyen kijönnek Júdának királyai, és Jeruzsálemnek is minden kapujában!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, 'És ezt mondd nékik: Halljátok meg az Úrnak szavát Júdának királyai és egész Júda és Jeruzsálemnek minden lakosa, a kik bejártok e kapukon!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'Ezt mondja az Úr: Vigyázzatok a ti lelketekre, és ne hordjatok terhet szombat-napon, se Jeruzsálem kapuin be ne vigyetek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'Házaitokból se vigyetek ki terhet szombat-napon, és semmi munkát ne végezzetek, hanem szenteljétek meg a szombat-napot, úgy a mint atyáitoknak megparancsoltam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, 'De ők nem hallgattak, és fülöket sem hajtották rá, hanem megkeményítették nyakokat, hogy ne halljanak, és az oktatást be ne vehessék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, 'Pedig ha szívesen hallgattok reám, ezt mondja az Úr, és nem visztek be terhet e város kapuin szombat-napon, és megszentelitek a szombat-napot, úgy hogy semmi dolgot nem végeztek azon:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, 'Akkor e város kapuin királyok és fejedelmek fognak bevonulni, a kik a Dávid székén ülnek, szekereken és lovakon járnak, mind magok, mind fejedelmeik, Júdának férfiai és Jeruzsálemnek lakosai, és e városban lakni fognak mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, 'És bejőnek Júda városaiból, Jeruzsálem környékéről, Benjámin földéről, a lapályról, a hegyről és dél felől, hozván égőáldozatot, véres áldozatot, ételáldozatot és temjént, és hozván hálaáldozatot az Úrnak házába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, 'Ha pedig nem hallgattok reám, hogy megszenteljétek a szombat-napot, és hogy ne hordjatok terhet és ne jőjjetek be Jeruzsálem kapuin szombat-napon: tüzet gerjesztek az ő kapuiban, és megemészti Jeruzsálem palotáit, és nem lesz eloltható.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, 'Az a beszéd, a melyet az Úr beszélt Jeremiásnak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, 'Kelj fel és menj le a fazekasnak házába, és ott közlöm veled az én beszédeimet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'Lemenék azért a fazekas házába, és ímé ő edényt készít vala a korongon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'És elromla az edény, a melyet ő készít vala és a mely mint agyag volt a fazekas kezében, és azonnal más edényt készíte belőle, a mint a fazekas jobbnak látta megkészíteni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, 'És szóla az Úr nékem, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, 'Vajjon nem cselekedtem-é veletek úgy, mint ez a fazekas, oh Izráel háza? ezt mondja az Úr. Ímé, mint az agyag a fazekas kezében, olyanok vagytok ti az én kezemben, oh Izráel háza!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'Hogyha szólok egy nép ellen és ország ellen, hogy kigyomlálom, megrontom és elvesztem:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'De megtér az a nép az ő gonoszságából, a mely ellen szólottam: én is megbánom a gonoszt, a melyet rajta véghezvinni gondoltam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, 'És hogyha szólok a nép felől és ország felől, hogy felépítem, beültetem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'De a gonoszt cselekszi előttem, és nem hallgat az én szómra: akkor megbánom a jót, a melylyel vele jót tenni akartam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, 'Most azért beszélj csak a Júda férfiaival és Jeruzsálem lakosaival, mondván: Ezt mondja az Úr: Ímé, én veszedelmet készítek ellenetek és tervet tervezek ellenetek! Nosza, térjetek meg, kiki a maga gonosz útáról, és jobbítsátok meg útaitokat és cselekedeteiteket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'Ők pedig azt mondják: Hagyd el! Mert mi a magunk gondolatai után megyünk, és mindnyájan a mi gonosz szívünk hamisságát cselekeszszük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'Azért ezt mondja az Úr: Kérdezzétek csak meg a népeket: kicsoda hallott vala ilyeneket? Igen útálatosan cselekedett Izráel leánya!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'Elhagyja-é a mezőség szikláját a Libanon hava? Vajjon kiszáríthatók-é a felfakadó, csörgedező, hullámzó vizek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'Ám az én népem elfeledkezett rólam; a hiábavalónak áldozik; elcsábították őket az ő útaikról, az ősrégi nyomról, hogy ösvényeken, járatlan úton járjanak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, 'Hogy pusztasággá tegyem földjüket, örökös csúfsággá, hogy a ki átmegy rajta, elálmélkodjék és fejét csóválja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, 'Mint keleti szél szórom szét őket az ellenség előtt, háttal és nem arczczal nézek reájok az ő pusztulásuk napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, 'Ők pedig mondák: Jertek és tervezzünk terveket Jeremiás ellen, mert nem vész el a törvény a paptól, sem a tanács a bölcstől, sem az ige a prófétától! Jertek el és verjük meg őt nyelvvel, és ne hallgassunk egy szavára sem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, 'Figyelmezz reám Uram, és az én pereseimnek szavát is halld meg!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, 'Hát roszszal fizetnek-é a jóért, hogy ők vermet ásnak nékem? Emlékezzél! Előtted álltam, hogy javokra beszéljek, hogy elfordítsam rólok haragodat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, 'Azért juttasd fiaikat éhségre és hányd őket fegyver hegyére, hogy legyenek az ő asszonyaik magtalanokká és özvegyekké; férjeik pedig legyenek halál martalékává, ifjaikat fegyver verje le a harczon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, 'Kiáltás hallattassék házaikból, mikor sereggel törsz reájok hirtelen, mert vermet ástak, hogy elfogjanak engem, és tőrt vetettek lábaimnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, 'Te pedig Uram, tudod minden ellenem való gyilkos szándékukat; ne kegyelmezz meg bűneik miatt, és ne töröld ki vétkeiket orczád elől, hanem veszni valók legyenek előtted; a te haragod idején bánj el velök!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, 'Ezt mondja az Úr: Menj el és végy egy cserépkorsót a fazekastól, és némelyekkel a nép vénei közül és a papok vénei közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, 'Menj el a Ben-Hinnom völgyébe, a mely a fazekasok kapujának bejáratánál van, és kiáltsd ott azokat a szavakat, a melyeket én szólok néked;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, 'És ezt mondjad: Halljátok meg az Úr szavát Júda királyai és Jeruzsálem lakosai: Ezt mondja a Seregek Ura, Izráel Istene: Ímé, én veszedelmet hozok e helyre, úgy hogy a ki csak hallja, megcsendül bele a füle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, 'Azért, mert elhagytak engem, és idegenné tették e helyet, és idegen isteneknek áldoztak benne, a kiket sem ők nem ismertek, sem atyáik, sem Júda királyai, és eltöltötték e helyet ártatlan vérrel;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, 'És magaslatokat építének a Baálnak, hogy megégessék fiaikat a tűzben, égőáldozatul a Baálnak, a mit én nem parancsoltam, sem nem rendeltem, és a mire nem is gondoltam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, 'Azért ímé eljőnek a napok, azt mondja az Úr, és e hely nem neveztetik többé Tófetnek, sem Ben-Hinnom völgyének, hanem öldöklés völgyének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, 'És eszét vesztem e helyen Júdának és Jeruzsálemnek, és fegyverrel ejtem el őket ellenségeik előtt, és az életökre törőknek kezével; holttesteiket pedig az ég madarainak és a mezei vadaknak adom eledelül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, 'És e várost csudává teszem és nevetséggé, a ki csak átmegy rajta, álmélkodik és szörnyűködik az ő nagy romlásán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, 'És megétetem velök az ő fiaik húsát és leányaik húsát és megeszi kiki az ő barátjának húsát, a megszállás alatt és a veszedelem alatt, a melylyel megszorongatják őket ellenségeik és a kik keresik az ő lelköket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, 'Azután törd el e korsót azok szeme láttára, a kik elmennek veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 11, 'És ezt mondd nékik: Ezt mondja a Seregek Ura: Így töröm össze e népet és e várost, a mint összetörhető e cserépedény, a mely többé meg sem építhető; és Tófetben temettetnek el, mert nem lesz más hely a temetkezésre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 12, 'Így cselekszem e helylyel és ennek lakosaival, azt mondja az Úr, és olyanná teszem e várost, a milyen Tófet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 13, 'És Jeruzsálem házai és Júda királyainak házai undokokká lesznek, mint a Tófet helye; mindazok a házak, a melyeknek tetején az ég egész seregének áldoztak és italáldozatot vittek az idegen isteneknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 14, 'Azután hazajöve Jeremiás Tófetből, a hová az Úr küldte vala őt prófétálni; megálla az Úr házának pitvarában, és szóla az egész népnek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 15, 'Ezt mondja a Seregek Ura, Izráel Istene: Ímé én ráhozom e városra és ennek minden városára mindama veszedelmet, a melyről szóltam ő ellene; mert megkeményítették nyakukat, hogy ne hallják az én beszédeimet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, 'És hallá Passúr a pap, az Immár fia (ő pedig fejedelem vala az Úr házában), Jeremiást, a mint e szókat prófétálja vala:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, 'És megcsapdosá Passúr Jeremiást a prófétát, és beveté őt a tömlöczbe, a mely a Benjámin felső kapujában vala, az Úr háza mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, 'És lőn másnap, hogy kivevé Passúr Jeremiást a tömlöczből, és monda néki Jeremiás: Nem Passúrnak nevezett téged az Úr, hanem Mágor Missábibnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, 'Mert ezt mondja az Úr: Ímé, én félelembe ejtelek téged és minden barátodat, és elhullanak az ő ellenségeik fegyvere által a szemeid láttára; az egész Júdát pedig odaadom a babiloni király kezébe, és elviszi őket Babilonba, és fegyverrel vágja le őket:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, 'És odaadom e városnak minden vagyonát és minden keresményét, és minden drágaságát, és Júda királyainak minden kincsét odaadom az ő ellenségeik kezébe, és elrabolják, elhurczolják és Babilonba viszik azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, 'Te pedig Passúr és a te házadnak minden lakosa, rabságba mentek, és Babilonba jutsz és ott halsz meg és ott temettetel el, te és minden barátod, a kiknek hamisan prófétáltál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, 'Rávettél Uram engem és rávétettem, megragadtál engem és legyőztél! Nevetségessé lettem minden időre, mindenki csúfol engemet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, 'Mert a hányszor csak szólok, kiáltozom; így kiáltok: erőszak és romlás! Mert az Úr szava mindenkori gyalázatomra és csúfságomra lett nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, 'Azért azt mondom: Nem emlékezem róla, sem az ő nevében többé nem szólok; de mintha égő tűz volna szívemben, az én csontjaimba rekesztetve, és erőlködöm, hogy elviseljem azt, de nem tehetem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, 'Mert hallom sokak rágalmazását, a mindenfelől való fenyegetést: Jelentsétek fel és ezt mi is feljelentjük: mindazok is, a kik barátaim, az én tántorodásomra figyelmeznek, mondván: Talán megbotlik és megfoghatjuk őt, és bosszút állhatunk rajta;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, 'De az Úr velem van, mint hatalmas hős, azért elesnek az én kergetőim és nem bírnak velem, igen megszégyenülnek, mert nem okosan cselekesznek: örökkévaló gyalázat lesz rajtok és felejthetetlen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, 'Azért, oh Seregeknek Ura, a ki megpróbálod az igazat, látod a veséket és a szíveket, hadd lássam a te büntetésedet ő rajtok: mert néked jelentettem meg az én ügyemet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, 'Énekeljetek az Úrnak, dicsérjétek az Urat, mert a szegénynek lelkét megszabadítja a gonoszok kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, 'Átkozott az a nap, a melyen születtem; az a nap, a melyen anyám szűlt engem, ne legyen áldott!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 15, 'Átkozott ember az, a ki örömhírt vitt az én atyámnak, mondván: Fiúmagzatod született néked, igen megörvendeztetvén őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 16, 'És legyen az az ember olyan, mint azok a városok, a melyeket elvesztett az Úr és meg nem bánta; és halljon reggel kiáltozást, és harczi riadót délben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 17, 'Hogy nem ölt meg engem az én anyám méhében, hogy az én anyám nékem koporsóm lett volna, és méhe soha sem szűlt volna!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 18, 'Miért is jöttem ki az én anyámnak méhéből, hogy nyomorúságot lássak és bánatot, és hogy napjaim gyalázatban végződjenek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, 'Ez a beszéd, a melyet szóla az Úr Jeremiásnak, mikor elküldé hozzá Sedékiás király Passúrt Melkiásnak fiát, és Sofóniást a Maásiás pap fiát, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, 'Kérdezd meg most érettünk az Urat, mert Nabukodonozor, a babiloni király viaskodik ellenünk, ha cselekszik-é az Úr velünk minden ő csodái szerint, hogy elhagyjon minket?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, 'És monda nékik Jeremiás: Ezt mondjátok Sedékiásnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, 'Így szól az Úr, Izráel Istene: Ímé, én elfordítok minden hadi szerszámot, a melyek a ti kezeitekben vannak, a melyekkel ti a babiloni király ellen és a Kaldeusok ellen viaskodtok, a kik kivül a kőfalon ostromolnak titeket, és begyűjtöm őket e városnak közepébe;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, 'És én kinyujtott kézzel vívok ellenetek és nagy erős karral és haraggal, búsulással és nagy felindulással.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, 'És megverem e városnak lakosait, mind az embert, mind a barmot; nagy döghalállal halnak meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, 'És azután, azt mondja az Úr, Sedékiást a Júda királyát, és az ő szolgáit, és a népet, és a kik megmaradnak e városban a döghaláltól, a fegyvertől és az éhségtől: odaadom Nabukodonozornak, a babiloni királynak kezébe és az ő ellenségeiknek kezébe és azoknak kezébe, a kik keresik az ő lelköket, és megöli őket éles fegyverrel: nem kedvez nékik, nem enged és nem könyörül rajtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, 'Azután ezt mondjad e népnek: Ezt mondja az Úr: Ímé, én előtökbe adom néktek az élet útját és a halál útját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, 'A ki e városban lakik, fegyver, éhség és döghalál miatt kell meghalnia; a ki pedig kimegy belőle és a Kaldeusokhoz megy, a kik megostromolnak titeket, él, és az ő lelkét zsákmányul nyeri;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, 'Mert orczámat e város veszedelmére fordítottam és nem megszabadulására, azt mondja az Úr: A babiloni király kezébe adatik, és tűzzel égeti meg azt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, 'Júda királya házának mondd meg: Halljátok meg az Úr szavát!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, 'Dávidnak háza, ezt mondja az Úr: Hamarsággal tegyetek igaz ítéletet, a nyomorultat mentsétek meg a nyomorgatónak kezéből, különben az én haragom kitör, mint a tűz és felgerjed, és nem lesz, a ki megolthassa, az ő cselekedeteiknek gonoszsága miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, 'Ímé, én reátok megyek, te völgy lakója és síkságnak szirtje; azt mondja az Úr, a kik azt mondjátok: Kicsoda jön le mi ellenünk, és kicsoda jön be a mi házainkba?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, 'És a ti cselekedeteiteknek gyümölcse szerint fenyítlek meg titeket, azt mondja az Úr, és tüzet gyújtok az ő erdejében, és köröskörül az mindent megemészt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, 'Ezt mondja az Úr: Menj alá a Júda királyának házába, és beszéld el ezeket:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, 'És ezt mondd: Halld meg az Úr szavát, Júda királya, a ki a Dávid királyi székében ülsz, te és a te szolgáid, és a te néped, a kik bejártok e kapukon!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, 'Ezt mondja az Úr: Tegyetek ítéletet és igazságot, és mentsétek meg a nyomorultat a nyomorgató kezéből! A jövevényt, árvát és özvegyet pedig ne nyomorgassátok és rajta ne erőszakoskodjatok, és ártatlan vért e helyen ki ne ontsatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, 'Mert ha ezt cselekszitek, akkor királyok mennek be e háznak kapuin, a kik a Dávid székébe ülnek, szekereken és lovakon menvén ő, az ő szolgái és az ő népe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, 'Ha pedig nem hallgattok e szókra, én magamra esküszöm, azt mondja az Úr, hogy elpusztul e ház.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, 'Mert így szól az Úr a Júda királyának házához: Ha Gileád volnál nékem és a Libánon feje: mégis elpusztítlak téged, mint a városokat, a melyekben nem laknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 7, 'És felkészítem ellened a rablókat, mindeniket az ő fegyverével, és kivágják a te válogatott czédrusaidat, és a tűzre vetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 8, 'És sok nép megy át e városon, és ezt mondják egymásnak: Miért mívelte az Úr ezt e nagy várossal?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 9, 'És ezt mondják: Azért, mert elhagyták az Úrnak, az ő Istenöknek frigyét, és idegen istenek előtt borultak le és azoknak szolgáltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 10, 'Ne sirassátok a halottat és ne bánkódjatok érte, hanem azt sirassátok, a ki elment, mert nem jő vissza többé, és az ő szülőföldjét nem látja meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 11, 'Mert ezt mondja az Úr Sallum felől, Jósiásnak, a Júda királyának fia felől, a ki uralkodik az ő atyja, Jósiás helyett: A ki kimegy e helyből, nem tér többé ide vissza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 12, 'Hanem a helyen, a hová rabságra vitték, ott hal meg, és e földet nem látja többé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 13, 'Jaj annak, a ki hamisan építi házát, felházait pedig álnokul; a ki az ő felebarátjával ingyen szolgáltat, és munkájának bérét néki meg nem adja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 14, 'A ki ezt mondja: Nagy házat építek magamnak és tágas felházakat, és ablakait kiszélesíti és czédrusfával béleli meg és megfesti czinóberrel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 15, 'Király vagy-é azért, hogy czédrus után kivánkozol? A te atyád nem evett és ivott-é? De igazságot és méltányosságot cselekedett, azért jó dolga volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 16, 'Igazságosan ítélte a szegényt és a nyomorultat, azért jó volt dolga. Nem ez-é az igaz ismeret felőlem? azt mondja az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 17, 'De a te szemeid és szíved csak a te nyereségedre vágynak, és az ártatlan vérére, és ragadozásra és erőszak elkövetésére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 18, 'Azért ezt mondja az Úr Joákimnak, Jósiás, Júda királya fiának: Nem siratják őt: Jaj atyám! Jaj húgom! nem siratják őt: Jaj uram! Jaj az ő dicsőségének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 19, 'Úgy temetik el, mint a szamarat, kivonják és elvetik Jeruzsálem kapuin kivül!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 20, 'Menj fel a Libánonra és kiálts, és a Básánon emeld fel szódat és kiálts az Abarimról, mert szeretőid mind tönkre jutottak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 21, 'Szóltam néked, mikor jól volt dolgod, de ezt mondottad: Nem hallom. Ifjúságodtól fogva ez a te szokásod, hogy nem hallgattad az én szómat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 22, 'Minden pásztorodat szél emészti meg, és a szeretőid rabságra mennek; akkor szégyent vallasz majd és pironkodol minden gonoszságodért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 23, 'Te, a ki a Libánonon lakozol, a czédrusfákon fészkelsz: hogy fogsz majd nyögni, mikor fájdalmak lepnek meg, a gyermekszülő vajudása?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 24, 'Élek én, azt mondja az Úr, hogy ha Kóniás; Joákimnak, a Júda királyának fia pecsétgyűrű volna is az én jobbkezemben: mindazáltal onnan lerántanálak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 25, 'És odaadlak téged a te lelked keresőinek kezébe, és azoknak kezébe, a kiknek tekintetétől félsz, és Nabukodonozornak, a babiloni királynak kezébe és a Káldeusoknak kezébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 26, 'És elvetlek téged és a te anyádat, a ki szűlt téged, idegen földre, a melyben nem születtetek, és ott haltok meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 27, 'És nem jőnek vissza arra a földre, a melyre az ő lelkök visszajőni kivánkozik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 28, 'Avagy útálatos és elromlott edény-é ez a férfiú, ez a Kóniás, avagy oly edény-é, amelyben semmi gyönyörűség nincsen? Miért lökték el őt és az ő magvát, és dobták olyan földre, a melyet ők nem ismernek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 29, 'Föld, föld, föld! halld meg az Úrnak szavát!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 30, 'Ezt mondja az Úr: Írjátok fel ezt a férfiút, mint gyermektelent, mint olyan embert, a kinek nem lesz jó előmenetele az ő idejében; mert senkinek, a ki az ő magvából a Dávid székében ül, nem lesz jó állapotja, és nem uralkodik többé Júdában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, 'Jaj a pásztoroknak, a kik elvesztik és elszélesztik az én mezőmnek juhait, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, 'Azért ezt mondja az Úr, Izráel Istene a pásztoroknak, a kik legeltetik az én népemet: Ti szélesztettétek el az én juhaimat és űztétek el őket; és nem néztetek utánok; ímé, én megbüntetem a ti cselekedeteiteknek gonoszságát, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, 'Juhaimnak maradékát pedig összegyűjtöm minden földről, a melyekre elűztem őket, és visszahozom őket az ő legelőikre, és szaporodnak és megsokasodnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, 'És pásztorokat rendelek melléjök, hogy legeltessék őket, és többé nem félnek és nem rettegnek, sem meg nem fogyatkoznak, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, 'Ímé, eljőnek a napok, azt mondja az Úr, és támasztok Dávidnak igaz magvat, és uralkodik mint király, és bölcsen cselekszik és méltányosságot és igazságot cselekszik e földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, 'Az ő idejében megszabadul Júda, és Izráel bátorságosan lakozik, és ez lesz az ő neve, a melylyel nevezik őt: Az Úr a mi igazságunk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, 'Azért ímé elközelgetnek a napok, azt mondja az Úr, a melyekben nem mondják többé: Él az Úr, a ki kihozta Izráel fiait Égyiptom földéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, 'Hanem inkább ezt mondják: Él az Úr, a ki kihozta és a ki haza vezérlette Izráel házának magvát az északi földről és mindama földekről, a melyekre kiűztem vala őket, és lakoznak az ő földjökön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, 'A próféták miatt megkeseredett az én szívem én bennem, minden csontom reszket; olyan vagyok, mint a részeg férfi és mint a bortól elázott ember, az Úrért és az ő szent igéjéért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, 'Mert betelt a föld paráznákkal, mert a hamis esküvés miatt gyászol a föld, a pusztának legelője kiszáradt, és az ő futásuk gonosz, és az ő hatalmasságuk hamis.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 11, 'Mert mind a próféta, mind a pap istentelenek, még házamban is megtaláltam az ő gonoszságukat, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 12, 'Azért az ő útjok olyan lesz, mint a sikamlós útak a setétben, megbotlanak és elesnek: mert veszedelmet hozok reájok, az ő büntetésöknek esztendejét, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 13, 'A Samariabeli prófétákban is bolondságot láttam: a Baál nevében prófétáltak, és elcsalták az én népemet, az Izráelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 14, 'De a jeruzsálemi prófétákban is rútságot láttam: paráználkodnak és hazugságban járnak; sőt pártját fogják a gonoszoknak, annyira, hogy senki sem tér meg az ő gonoszságából; olyanok előttem mindnyájan, mint Sodoma, és a benne lakók, mint Gomora.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 15, 'Azért ezt mondja a Seregek Ura a próféták felől: Ímé, én ürmöt adok enniök és mérget adok inniok, mert a jeruzsálemi prófétáktól ment ki az istentelenség minden földre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 16, 'Ezt mondja a Seregek Ura: Ne hallgassátok azoknak a prófétáknak szavait, a kik néktek prófétálnak, elbolondítanak titeket: az ő szívöknek látását szólják, nem az Úr szájából valót.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 17, 'Szüntelen ezt mondják azoknak, a kik megvetnek engem: Azt mondta az Úr: Békességetek lesz néktek és mindenkinek, a ki az ő szívének keménysége szerint jár; ezt mondák: Nem jő ti reátok veszedelem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 18, 'Mert ki állott az Úr tanácsában, és ki látta és hallotta az ő igéjét? Ki figyelmezett az ő igéjére és hallotta azt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 19, 'Ímé, az Úrnak szélvésze nagy haraggal kitör, és a hitetlenek fejére forgószél zúdul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 20, 'Nem szünik meg az Úrnak haragja, míg meg nem valósítja és míg be nem teljesíti szívének gondolatait; az utolsó napokban értitek meg e dolog értelmét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 21, 'Nem küldöttem e prófétákat, de ők futottak, nem szólottam nékik, mégis prófétáltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 22, 'Ha tanácsomban állottak volna, akkor az én igéimet hirdették volna az én népemnek, és eltérítették volna őket az ő gonosz útaikról, és az ő cselekedetöknek gonoszságától.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 23, 'Csak a közelben vagyok-é én Isten? azt mondja az Úr, és nem vagyok-é Isten a messzeségben is?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 24, 'Vajjon elrejtőzhetik-é valaki a rejtekhelyeken, hogy én ne lássam őt? azt mondja az Úr, vajjon nem töltöm-é én be a mennyet és a földet? azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 25, 'Hallottam, a mit a próféták mondanak, a kik hazugságot prófétálnak az én nevemben, mondván: Álmot láttam, álmot láttam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 26, 'Meddig lesz ez a hazugságot prófétáló próféták szívében, a kik az ő szívök csalárdságát prófétálják?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 27, 'A kik el akarják az én népemmel felejtetni az én nevemet az ő álmaikkal, a melyeket egymásnak beszélnek, miképen az ő atyáik elfeledkeztek az én nevemről a Baálért?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 28, 'A próféta, a ki álomlátó, beszéljen álmot; a kinél pedig az én igém van, beszélje az én igémet igazán. Mi köze van a polyvának a búzával? azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 29, 'Nem olyan-é az én igém, mint a tűz? azt mondja az Úr, mint a sziklazúzó pőröly?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 30, 'Azért ímé én a prófétákra támadok, azt mondja az Úr, a kik az én beszédeimet ellopják egyik a másikától.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 31, 'Ímé, én a prófétákra támadok, azt mondja az Úr, a kik felemelik nyelvöket és azt mondják: az Úr mondja!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 32, 'Ímé, én a prófétákra támadok, a kik hazug álmokat prófétálnak, azt mondja az Úr, és beszélik azokat, és megcsalják az én népemet az ő hazugságaikkal és hízelkedéseikkel, holott én nem küldtem őket, sem nem parancsoltam nékik, és használni sem használtak e népnek, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 33, 'Mikor pedig megkérdez téged e nép, vagy a próféta, vagy a pap, mondván: Micsoda az Úrnak terhe? akkor mondd meg nékik azt: mi a teher? Az, hogy elvetlek titeket, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 34, 'A mely próféta vagy pap, vagy község azt mondja: Ez az Úrnak terhe, meglátogatom azt az embert és annak házát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 35, 'Kiki ezt mondja az ő barátjának és kiki az ő atyjafiának: Mit felel az Úr? és mit szólt az Úr?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 36, 'És az Úrnak terhét ne emlegessétek többé, mert mindenkinek terhes lesz az ő szava, ha elforgatjátok az élő Istennek, a Seregek Urának, a mi Istenünknek, beszédét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 37, 'Ezt mondjad a prófétának: Mit felelt néked az Úr és mit szólt az Úr?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 38, 'Hogyha az Úrnak terhét említitek, tehát ezt mondja az Úr: Mivelhogy ti e szót mondottátok: ez az Úrnak terhe, jóllehet küldék ti hozzátok, a kik ezt mondják: Ne mondjátok: ez az Úrnak terhe;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 39, 'Ezért ímé én elfeledlek titeket, és kigyomlállak titeket, és a várost, a melyet néktek és a ti atyáitoknak adtam, elvetem az én orczám elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 40, 'És örökkévaló szégyent és örökkévaló gyalázatot hozok ti reátok, a mely felejthetetlen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, 'Látomást mutata nékem az Úr, és ímé, két kosár füge volt letéve az Úr temploma előtt, miután Nabukodonozor babiloniai király Jékóniást, Joákimnak, a Júda királyának fiát és Júdának fejedelmeit és az ácsokat és kovácsokat fogságra hurczolá Jeruzsálemből, és elvivé őket Babilonba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, 'Az egyik kosárban igen jó fügék valának, a milyenek az először érő fügék; a másik kosárban pedig igen rossz fügék valának, sőt ehetetlenek a rosszaság miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, 'És monda az Úr nékem: Mit látsz te Jeremiás? És mondék: Fügéket. A jó fügék igen jók, de a rosszak igen rosszak, sőt rosszaságok miatt ehetetlenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, 'És szóla az Úr nékem, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, 'Ezt mondja az Úr, Izráel Istene: Mint ezeket a jó fügéket, úgy megkülönböztetem a Júda foglyait, a kiket e helyről a Kaldeusok földjére vitettem, az ő javokra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, 'És őket szemmel tartom az ő javokra, és visszahozom e földre, és megépítem és el nem rontom, és beplántálom és ki nem szaggatom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, 'És szívet adok nékik, hogy megismerjenek engemet, hogy én vagyok az Úr, és ők én népemmé lesznek, én pedig Istenökké leszek, mert teljes szívökből megtérnek hozzám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, 'És a milyenek a rossz fügék, a melyek ehetetlenek a rosszaság miatt, azt mondja az Úr, olyanná teszem Sedékiást, a Júda királyát, és az ő maradékát, és az ő fejedelmeit, és Jeruzsálem maradékát, a kik itt maradnak e földön, és azokat, a kik Égyiptom földén laknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, 'És kiteszem őket rettegésnek, veszedelemnek a föld minden országában; gyalázatnak, példabeszédnek, gúnynak és szidalomnak minden helyen, a hová kiűzöm őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, 'És fegyvert, éhséget és döghalált bocsátok reájok mindaddig, a míg elfogynak a földről, a melyet nékik adtam és az ő atyáiknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, 'Az a beszéd, a mely lőn Jeremiáshoz az egész Júda népe felől, Joákim negyedik esztendejében; a ki fia vala Jósiásnak, a Júda királyának, az első esztendejében Nabukodonozornak a babiloni királynak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, 'A melyet szóla Jeremiás próféta az egész Júda népéhez és Jeruzsálem minden lakosához, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, 'Jósiásnak tizenharmadik esztendejétől fogva, a ki fia vala Amonnak, a Júda királyának, e napig (vagyis huszonhárom esztendő óta) szóla az Úr nékem, és szólottam én néktek, jó reggel szóltam, de nem hallgattátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, 'És elküldte az Úr ti hozzátok minden ő szolgáját, a prófétákat, jó reggel elküldte, de nem hallgattátok, és fületeket sem hajtottátok a hallásra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, 'Ezt mondták: Térjetek meg már mindnyájan a ti gonosz útaitokról és a ti gonosz cselekedeteitekből, hogy lakhassatok a földön, a melyet az Úr adott néktek és a ti atyáitoknak öröktől fogva örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, 'És ne járjatok idegen istenek után, hogy szolgáljatok nékik és imádjátok őket, és ne ingereljetek fel engem a ti kezeitek munkájával, hogy veszedelmet ne hozzak rátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, 'De nem hallgattatok reám, azt mondja az Úr, hogy felingereljetek engem a ti kezeitek munkájával a ti veszedelmetekre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, 'Azért ezt mondja a Seregeknek Ura: Mivelhogy nem hallgattatok az én beszédemre:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, 'Ímé, kiküldök én és felveszem északnak minden nemzetségét, azt mondja az Úr, és Nabukodonozort, a babiloni királyt, az én szolgámat, és behozom őket e földre és ennek lakóira és mind e körül való nemzetekre, és elveszem őket és csudává és szörnyűséggé teszem őket és örökkévaló pusztasággá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, 'És elveszem tőlök az öröm szavát, a vígasság szavát, a vőlegény szavát és a menyasszony szavát, a malmok zörgését és a szövétnek világosságát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, 'És ez egész föld pusztasággá és csudává lészen, és e nemzetek a babiloni királynak szolgálnak hetven esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, 'És mikor eltelik a hetven esztendő, meglátogatom a babiloni királyon és az ő népén az ő álnokságukat, azt mondja az Úr, és a káldeai földön, és örökkévaló pusztasággá teszem azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 13, 'És végbeviszem azon a földön mindazokat, a miket szóltam felőle, mindazt, a mi megvan írva e könyvben, a melyet prófétált Jeremiás az összes nemzetek felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 14, 'Mert ő rajtok is uralkodnak majd sok nemzetek és nagy királyok, és megfizetek nékik az ő cselekedeteik szerint és az ő kezeiknek munkája szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 15, 'Mert ezt mondotta az Úr, Izráelnek Istene nékem: Vedd el kezemből e harag borának poharát, és itasd meg vele mindama nemzeteket, a kikhez én küldelek téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 16, 'Hogy igyanak, részegüljenek meg és bolondoskodjanak a fegyver miatt, a melyet én közéjök bocsátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 17, 'És elvevém a pohárt az Úr kezéből, és megitatám mindama nemzeteket, a kikhez külde engem az Úr:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 18, 'Jeruzsálemet és Júda városait, az ő királyait és fejedelmeit, hogy pusztasággá, csudává, szörnyűséggé és átokká tegyem őket, a mint e mai napon van:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 19, 'A Faraót, Égyiptom királyát, az ő szolgáit és fejedelmeit és minden ő népét,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 20, 'És minden egyveleg népet, és az Úz földének minden királyát, és a Filiszteusok földének minden királyát, és Askalont, Gázát, Akkaront és Azótusnak maradékait,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 21, 'Edomot, Moábot és az Ammon fiait,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 22, 'És Tírusnak minden királyát és Szidonnak minden királyát és a szigeteknek minden királyát, a kik túl vannak a tengeren,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 23, 'Dedánt és Témánt és Búzt és mindazokat, a kik lenyírott üstökűek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 24, 'És Arábiának minden királyát és az egyveleg nép minden királyát, a kik a pusztában laknak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 25, 'És Zimrinek minden királyát és Elámnak minden királyát és a Médusok minden királyát,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 26, 'És északnak minden királyát, mind a közelvalókat, mind a távolvalókat, egyiket a másikra, és a földnek minden országát, a melyek e föld színén vannak; Sésák királya pedig ezek után iszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 27, 'Azért ezt mondd nékik: Ezt mondja a Seregek Ura, Izráelnek Istene: Igyatok és részegüljetek meg, okádjatok és hulljatok el, és fel ne keljetek a fegyver előtt, a melyet én küldök közétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 28, 'És ha majd a te kezedből nem akarják elvenni a pohárt, hogy igyanak belőle: ezt mondd nékik: Így szól a Seregek Ura: Meg kell innotok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 29, 'Mert ímé, a város ellen, a mely az én nevemről neveztetik, az ellen veszedelmet indítok, ti pedig egészen megmenekültök-é? Nem menekesztek, mert én fegyvert hozok e földnek minden lakosára, azt mondja a Seregek Ura,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 30, 'Te pedig prófétáld meg nékik mind e szókat, és ezt mondd nékik: Az Úr a magasságból harsog, és az ő szent lakhelyéből dörög, harsanva harsog az ő házára, riogatva kiált, mint a szőlőtaposók, e föld minden lakosa ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 31, 'Elhat e harsogás a földnek végére, mert pere van az Úrnak a pogányokkal, ő minden testnek ítélő birája, a hitetleneket fegyverre veti, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 32, 'Így szól a Seregek Ura: Ímé, veszedelem indul egyik nemzettől a másik nemzetre, és nagy szélvész támad a föld széleitől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 33, 'És azon a napon az Úrtól levágatnak a föld egyik végétől fogva a föld másik végéig; nem sirattatnak meg, és össze sem hordatnak, és el sem temettetnek, olyanok lesznek a földnek színén, mint a ganéj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 34, 'Jajgassatok pásztorok, és kiáltsatok, és heverjetek a porban, ti vezérei a nyájnak, mert eljön a ti megöletéseteknek és szétszóratástoknak ideje, és elhullotok, noha drága edények vagytok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 35, 'És nincs hová futniok a pásztoroknak, és menekülniök a nyáj vezéreinek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 36, 'Hallatszik a pásztorok kiáltozása és a nyáj vezéreinek jajgatása, mert elpusztította az Úr az ő legeltető helyöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 37, 'Elpusztultak a békességes legeltető helyek az Úr felgerjedt haragja miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 38, 'Elhagyta azokat, mint az oroszlán az ő barlangját, mert pusztasággá lett az ő földjök a zsarnoknak dühe miatt és az ő felgerjedt haragja miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, 'A Jojákim uralkodásának kezdetén, a ki fia vala Jósiásnak, a Júda királyának, e szót szólá az Úr, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, 'Ezt mondja az Úr: Állj az Úr házának pitvarába, és mondd el Júdának minden városából azoknak, a kik imádkozni jőnek az Úr házába, mindazokat az igéket, a melyeket parancsoltam néked, hogy mondd el nékik. Egy szót se hagyj el!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, 'Hátha szót fogadnak, és mindenki megtér az ő gonosz útjától, akkor megbánom a veszedelmet, a melyet nékik okozni gondoltam az ő cselekedeteik gonoszsága miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, 'És mondd meg nékik: Így szól az Úr: Ha nem hallgattok reám, hogy az én törvényeim szerint járjatok, a melyet előtökbe adtam,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, 'Hogy hallgassatok a prófétáknak, az én szolgáimnak beszédére, a kiket én küldék hozzátok, és pedig jó reggel küldém, de nem hallgattatok rájok:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, 'Akkor e házat hasonlóvá teszem Silóhoz, e várost pedig a föld minden nemzetének átkává.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, 'Hallák pedig a papok és próféták és az egész község Jeremiást, a mint ez igéket szólá az Úr házában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, 'És lőn, mikor elvégezé Jeremiás a beszédet, a melyet az Úr parancsolt vala mind az egész néphez szólania, megragadák őt a papok és a próféták és az egész nép, mondván: Halállal kell lakolnod!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, 'Miért prófétáltál az Úr nevében, mondván: Olyan lesz e ház, mint Siló, és e város elpusztul, lakatlanná lesz? És összegyűle az egész nép Jeremiás ellen az Úrnak házában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, 'De meghallák ezeket a Júda fejedelmei, és felmenének a király házából az Úrnak házába, és leülének az Úr új kapujának ajtajában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, 'És szólának a papok és a próféták a fejedelmeknek és az egész népnek, mondván: Halálra méltó ez az ember, mert e város ellen prófétált, a mint füleitekkel hallottátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, 'És szóla Jeremiás mindazoknak a fejedelmeknek és az egész népnek, mondván: Az Úr küldött engem, hogy prófétáljak e ház ellen és e város ellen mind e szókkal, a melyeket hallottatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, 'Most azért jobbítsátok meg a ti útaitokat és cselekedeteiteket, és hallgassatok az Úrnak, a ti Isteneteknek szavára, és az Úr megbánja a veszedelmet, a melylyel fenyegetett titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, 'Én magam pedig ímé kezetekben vagyok, cselekedjetek velem, a mint jónak és a mint helyesnek tetszik néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 15, 'De jól tudjátok meg, hogy ha megöltök engem, ártatlan vér száll ti reátok és e városra és ennek lakosaira, mert bizony az Úr küldött el engem hozzátok, hogy a ti füleitekbe mondjam mind e szókat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 16, 'És mondák azok a fejedelmek és az egész község a papoknak és prófétáknak: Nem méltó ez az ember a halálra: mert az Úrnak, a mi Istenünknek nevében szólt nékünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 17, 'Felkelének az ország vénei közül is némely férfiak, és szólának az egész összegyűlt népnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 18, 'A móreseti Mikeás prófétált Ezékiásnak, a Júda királyának idejében, és szóla az egész Júda népének, mondván: Ezt mondja a Seregeknek Ura: A Siont megszántják, mint szántóföldet, és Jeruzsálem elpusztul, és e háznak hegyét erdő növi be;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 19, 'Megölte-é azért őt Ezékiás, Júdának királya és az egész Júda? Nem félte-é az Urat? Nem könyörgött-é az Úrnak? És nem megbánta-é az Úr a veszedelmet, a melylyel fenyegette őket? És mi olyan nagy veszedelmet vonnánk a mi lelkünkre?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 20, 'Volt egy másik ember is, a ki az Úr nevében prófétált, Uriás, Semájának fia, Kirját-Jeárimból, és prófétált e város ellen és a föld ellen, egészen a Jeremiás beszéde szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 21, 'És meghallá Jojákim király és minden vitéze és minden fejedelme az ő beszédeit, és halálra kerestette őt a király; de meghallá Uriás és megijedt, és elfutott és átment Égyiptomba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 22, 'És Jojákim király embereket küldött Égyiptomba, Elnátánt, az Akbor fiát, és más férfiakat vele együtt Égyiptomba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 23, 'És kihozák Uriást Égyiptomból és vivék Jojákim király elé, a ki megöleté őt fegyverrel, holttestét pedig a köznép temetőjébe vetteté.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 24, 'De Ahikámnak, a Sáfán fiának keze Jeremiással lőn, hogy ne adják őt a nép kezébe halálra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, 'A Jojákim uralkodásának kezdetén, a ki fia vala Jósiásnak, a Júda királyának, ilyen szavakat szóla az Úr Jeremiáshoz, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, 'Így szól az Úr nékem: Csinálj magadnak köteleket, és jármot és vedd azokat a nyakadba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, 'És küldd azokat Edom királyához és Moáb királyához, az Ammon fiainak királyához, Tírus királyához és Sidon királyához a követek által, a kik eljőnek Jeruzsálembe Sedékiáshoz, Júdának királyához,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, 'És parancsold meg nékik, hogy mondják meg az ő uraiknak: Ezt mondja a Seregek Ura, Izráelnek Istene, ezt mondjátok a ti uraitoknak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, 'Én teremtettem a földet, az embert és a barmot, a melyek e föld színén vannak, az én nagy erőmmel és az én kinyujtott karommal, és annak adom azt, a ki kedves az én szemeim előtt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, 'És most én odaadom mind e földeket Nabukodonozornak, a babiloni királynak, az én szolgámnak kezébe; sőt a mezei állatokat is néki adom, hogy néki szolgáljanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, 'És néki és az ő fiának és unokájának szolgál minden nemzet mindaddig, míg el nem jő az ő földének is ideje, és szolgálnak néki sok nemzetek és nagy királyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, 'Azt a nemzetet és azt az országot pedig, a mely nem szolgál néki, Nabukodonozornak, a babiloni királynak, és a ki nem teszi nyakát a babiloni király jármába: fegyverrel és éhséggel és döghalállal verem meg azt a nemzetet, azt mondja az Úr, míglen kiirtom őket az ő kezével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, 'Ti azért ne hallgassatok a ti prófétáitokra, se jövendőmondóitokra, se álommagyarázóitokra, se varázslóitokra, se szemfényvesztőitekre, a kik ezt mondják néktek: Ne szolgáljatok a babiloni királynak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 10, 'Mert ők hazugságot prófétálnak néktek, hogy messze vigyelek titeket a ti földetekből és kiűzzelek titeket, és elveszszetek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 11, 'Azt a nemzetet pedig, a mely nyakára veszi a babiloni király jármát és szolgál néki, az ő földében hagyom, azt mondja az Úr, és míveli azt és lakozik benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 12, 'Sőt Sedékiásnak, a Júda királyának is mind e beszédek szerint szólottam, mondván: Vegyétek nyakatokra a babiloni királynak jármát, és szolgáljatok néki és az ő népének, és éltek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 13, 'Miért halsz meg te és a te néped fegyver miatt, éhség és döghalál miatt, a mint szólott az Úr az olyan népről, a mely nem szolgál a babiloni királynak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 14, 'Ne hallgassatok hát a próféták szavaira, a kik így szólnak néktek: Ne szolgáljatok a babiloni királynak; mert ők hazugságot prófétálnak néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 15, 'Mert nem küldöttem őket, azt mondja az Úr, hanem ők az én nevemben hazugságot prófétálnak, hogy kiűzzelek titeket, és elvesszetek ti és a próféták, a kik prófétálnak néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 16, 'A papoknak és ez egész népnek is így szóltam: Ezt mondja az Úr: Ne hallgassatok a ti prófétáitok szavaira, a kik prófétálnak néktek, mondván: Ímé, az Úr házának edényei visszahozatnak Babilonból most mindjárt, mert hazugságot prófétálnak ők néktek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 17, 'Ne hallgassatok rájok; szolgáljatok a babiloni királynak, és éltek; miért legyen e város pusztasággá?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 18, 'Ha ők próféták és ha nálok van az Úrnak igéje: imádkozzanak most a Seregek Urának, hogy az edények, a melyek még az Úr házában és a Júda királyának házában és Jeruzsálemben maradtak, ne jussanak Babilonba;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 19, 'Mert ezt mondja a Seregek Ura az oszlopok felől, a tenger felől, az állványok felől és az edények maradéka felől, a melyek még e városban maradtak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 20, 'A melyeket el nem vitt Nabukodonozor, a babiloni király, mikor fogságba vivé Jékóniást, Jojákimnak, a Júda királyának fiát Jeruzsálemből Babilonba, és Júdának és Jeruzsálemnek minden fő népét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 21, 'Bizony ezt mondja a Seregek Ura, Izráelnek Istene az edények felől, a melyek megmaradtak az Úrnak házában és a Júda királyának házában és Jeruzsálemben:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 22, 'Babilonba vitetnek, és ott lesznek mindama napig, a melyen meglátogatom őket, azt mondja az Úr; és felhozom azokat, és visszahozom azokat e helyre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, 'És abban az esztendőben, Sedékiás, Júda királya uralkodásának kezdetén, a negyedik esztendőben, az ötödik hónapban monda nékem Hanániás (Azúrnak fia, a próféta, a ki Gibeonból való vala) az Úrnak házában, a papok és az egész nép szemei előtt, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, 'Ezt mondja a Seregek Ura, Izráel Istene, mondván: Eltöröm a babiloni királynak jármát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, 'Teljes két esztendő mulva visszahozom e helyre az Úr házának mindamaz edényeit, a melyeket elvitt innen Nabukodonozor, a babiloni király, és bevitt Babilonba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, 'És Jékóniást, Jojákimnak, a Júda királyának fiát és mindama júdabeli foglyokat, a kik elvitettek Babilonba, visszahozom én e helyre, azt mondja az Úr; mert eltöröm a babiloni király jármát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, 'Akkor monda Jeremiás próféta Hanániás prófétának a papok és az egész nép szemei előtt, a mely ott áll vala az Úrnak házában;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, 'Mondá pedig Jeremiás próféta: Úgy legyen, úgy cselekedjék az Úr: teljesítse az Úr a te beszédeidet, a melyekkel prófétálád, hogy az Úr házának edényei és a foglyok is mind visszahozatnak Babilonból e helyre,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, 'Mindazáltal halld csak e beszédet, a melyet én szólok néked és az egész népnek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, 'A próféták, a kik előttem és előtted eleitől fogva voltak, sok ország ellen és nagy királyságok ellen, hadról, veszedelemről és döghalálról prófétáltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, 'A mely próféta a békességről prófétál, mikor beteljesedik a próféta beszéde, akkor ismertetik meg a próféta, ha az Úr küldötte-é azt valóban?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, 'És vevé Hanániás próféta a jármot a Jeremiás próféta nyakáról, és széttöré azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, 'És szóla Hanániás az egész nép előtt, mondván: Ezt mondja az Úr: Így töröm le Nabukodonozornak, a babiloni királynak jármát két esztendei idő mulva minden nemzet nyakáról: és elméne Jeremiás próféta a maga útjára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 12, 'És szóla az Úr Jeremiásnak, miután letöré Hanániás próféta a Jeremiás próféta nyakáról a jármot, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 13, 'Menj el, és beszélj Hanániással, mondván: Ezeket mondja az Úr: A fajármot eltörted, de csináltál helyébe vasjármokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 14, 'Mert ezt mondja a Seregek Ura, Izráel Istene: Vasjármot vetettem mind e nemzetek nyakára, hogy szolgáljanak Nabukodonozornak, a babiloni királynak, és szolgálnak néki, sőt a mezei állatokat is néki adom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 15, 'És monda Jeremiás próféta Hanániás prófétának: Halld csak, Hanániás! nem az Úr küldött téged, és te hazugsággal biztatod e népet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 16, 'Azért így szól az Úr: Ímé, én elküldelek téged a föld színéről, meghalsz ez esztendőben: mert pártütőleg szóltál az Úr ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 17, 'És meghala Hanániás próféta abban az esztendőben, a hetedik hónapban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, 'Ezek ama levél szavai, a melyet Jeremiás próféta külde Jeruzsálemből a fogságban való vének maradékainak, és a papoknak és a prófétáknak, és az egész népnek, a melyet fogva vitt vala el Nabukodonozor Jeruzsálemből Babilonba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, '(Miután Jékóniás király és a királyné és az udvari szolgák, Júda és Jeruzsálem fejedelmei és az ács és a kovácsmester kijövének Jeruzsálemből.)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, 'Elasának a Sáfán fiának, és Gamariának a Hilkiás fiának keze által, a kiket Sedékiás, Júda királya küldött Nabukodonozorhoz, a babiloni királyhoz Babilonba, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, 'Ezt mondja a Seregek Ura, Izráel Istene mindama foglyoknak, a kiket Jeruzsálemből Babilonba vitettem:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, 'Építsetek házakat és lakjatok azokban, plántáljatok kerteket és egyétek azoknak gyümölcseit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, 'Vegyetek magatoknak feleségeket és szűljetek fiakat és leányokat, és a fiaitokat is házasítsátok meg, a leányaitokat pedig adjátok férjhez, és szűljenek fiakat és leányokat, és szaporodjatok meg ott, és meg ne kevesedjetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, 'És igyekezzetek a városnak jólétén, a melybe fogságra küldöttelek titeket, és könyörögjetek érette az Úrnak; mert annak jóléte lesz a ti jólétetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, 'Mert ezt mondja a Seregek Ura, Izráel Istene: Ne hitessenek el titeket a ti prófétáitok, a kik közöttetek vannak, se a ti jövendőmondóitok, és ne figyelmezzetek a ti álmaitokra, a melyeket álmodoztok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'Mert ők hamisan prófétálnak néktek az én nevemben: Nem küldöttem őket, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, 'Mert ezt mondja az Úr: Mihelyt eltelik Babilonban a hetven esztendő, meglátogatlak titeket és betöltöm rajtatok az én jó szómat, hogy visszahozzalak titeket e helyre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'Mert én tudom az én gondolatimat, a melyeket én felőletek gondolok, azt mondja az Úr; békességnek és nem háborúságnak gondolata, hogy kivánatos véget adjak néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, 'Akkor segítségre hívtok engem, és elmentek és imádtok engem, és meghallgatlak titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, 'És kerestek engem és megtaláltok, mert teljes szívetekből kerestek engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, 'És megtaláltok engem, azt mondja az Úr, és visszahozlak a fogságból, és összegyűjtlek titeket minden nemzet közül és mindama helyekről, a hová kiűztelek titeket, azt mondja az Úr, és visszahozlak e helyre, a honnan számkivetettelek titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 15, 'Mert ezt mondjátok: Támasztott nékünk az Úr prófétákat Babilonban is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 16, 'Mert ezt mondja az Úr a királynak, a ki Dávid székében ül, és az egész népnek, a mely e városban lakik, tudniillik a ti atyátok fiainak, a kik nem mentek el veletek a fogságra:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 17, 'Ezt mondja a Seregek Ura: Ímé, én reájok küldöm a fegyvert, az éhséget és a döghalált, és olyanokká teszem őket, a milyenek a keserű fügék, a melyek a rosszaság miatt ehetetlenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 18, 'És üldözöm őket fegyverrel, éhséggel és döghalállal, és rettenetessé teszem őket a föld minden országára, átokká és csudává és szörnyűséggé és mindama nemzetnek gúnyjává, a melyek közé kivetettem őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 19, 'Azért mert nem hallgattak az én beszédeimre, azt mondja az Úr, a melyeket én üzentem nékik az én szolgáim, a próféták által, jó reggel elküldvén, de nem hallgattátok, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 20, 'Ti azért, ti foglyok, halljátok meg az Úrnak szavát mindnyájan, a kiket Jeruzsálemből Babilonba küldtem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 21, 'Ezt mondja a Seregek Ura, az Izráel Istene Akhábra a Kolája fiára, és Sedékiásra a Mahásiás fiára, a kik hamisan prófétálnak néktek az én nevemben: Ímé, én odaadom őket Nabukodonozornak, Babilon királyának kezébe, és szemeitek láttára megöli őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 22, 'És mind azokról vesznek átokformát a Júdából való foglyok, a kik Babilonban vannak, mondván: Tegyen téged az Úr olyanná, mint Sedékiást és mint Akhábot, a kiket tűzzel égetett meg a babiloni király.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 23, 'Mert istentelenséget cselekedtek Izráelben, és paráználkodtak az ő felebarátjaik feleségével, és az én nevemben hazugságot szóltak, a mit nem parancsoltam nékik. Én pedig tudom azt, és bizonyság vagyok, azt mondja az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 24, 'A nehelámiti Semájának is szólj, ezt mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 25, 'Így szól a Seregek Ura, az Izráel Istene, mondván: Mivelhogy te levelet küldöttél a magad nevével az egész néphez, a mely Jeruzsálemben van, és Sofóniás paphoz, a Mahásiás fiához; és az összes papokhoz, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 26, 'Az Úr tett téged pappá Jojáda pap helyébe, hogy felügyelők legyenek az Úr házában minden bolond férfiún, és prófétálni akarón, hogy vessed ezt a tömlöczbe és a kalodába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 27, 'Most azért, miért nem dorgáltad meg az Anatóthbeli Jeremiást, a ki néktek prófétál?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 28, 'Sőt még hozzánk küldött Babilonba, ezt mondván: Hosszú lesz az! Építsetek házakat és lakjatok bennök, plántáljatok kerteket és éljetek azoknak gyümölcseivel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 29, 'És elolvasá Sofóniás pap e levelet a Jeremiás próféta hallására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 30, 'És szóla az Úr Jeremiásnak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 31, 'Küldj el mind a foglyokhoz, mondván: Ezt mondja az Úr a nehelámiti Semája felől: Mivelhogy prófétált néktek Semája, holott én nem küldtem őt, és hazugsággal biztatott titeket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 32, 'Azért ezt mondja az Úr: Ímé, én megfenyítem a nehelámiti Semáját és az ő magvát; nem lesz néki embere, a ki lakjék e nép között, és nem látja a jót, melyet én az én népemmel cselekszem, azt mondja az Úr; mert az Úr ellen való szót szólott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, 'Az a szó, a melyet szólott az Úr Jeremiásnak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, 'Ezt mondja az Úr, Izráel Istene, mondván: Mindama szókat, a melyeket mondottam néked, írd meg magadnak könyvben;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, 'Mert ímé, eljőnek a napok, azt mondja az Úr, és visszahozom az én népemet, az Izráelt és Júdát, azt mondja az Úr, és visszahozom őket arra a földre, a melyet az ő atyáiknak adtam, és bírni fogják azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, 'Ezek pedig azok a szók, a melyeket az Úr Izráel és Júda felől szólott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, 'Ezt mondta ugyanis az Úr: A félelemnek, rettentésnek szavát hallottuk, és nincs békesség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, 'Kérdjétek meg csak és lássátok, ha szűl-é a férfi? Miért látom minden férfi kezét az ágyékán, mintegy gyermekszűlőét, és miért változtak orczáik fakósárgává?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, 'Jaj! mert nagy az a nap annyira, hogy nincs hozzá hasonló; és háborúság ideje az Jákóbon; de megszabadul abból!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, 'És azon a napon, azt mondja a Seregek Ura, letöröm majd az ő igáját a te nyakadról, köteleidet leszaggatom, és nem szolgálnak többé idegeneknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, 'Hanem szolgálnak az Úrnak az ő Istenöknek, és Dávidnak az ő királyoknak, a kit feltámasztok nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, 'Te azért ne félj, oh én szolgám Jákób, azt mondja az Úr, se ne rettegj Izráel; mert ímhol vagyok én, a ki megszabadítlak téged a messze földről, és a te magodat az ő fogságának földéből; és visszatér Jákób és megnyugoszik, és bátorságban lesz, és nem lesz, a ki megháborítsa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, 'Mert veled vagyok én, azt mondja az Úr, hogy megtartsalak téged: mert véget vetek minden nemzetnek, a kik közé kiűztelek téged, csak néked nem vetek véget, hanem megfenyítelek téged ítélettel, mert nem hagylak egészen büntetés nélkül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, 'Mert ezt mondja az Úr: Veszedelmes a te sebed, gyógyíthatatlan a te sérülésed.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, 'Senki sincsen, a ki megítélje a te ügyedet, hogy bekösse sebedet, orvosságok és balzsam nincsenek számodra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, 'Elfeledkezett rólad minden szeretőd, és nem keres téged: mert megvertelek ellenséges veréssel, kegyetlen ostorozással, a te bűnödnek sokaságáért, és hogy eláradtak a te vétkeid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, 'Miért kiáltozol a te sebed miatt? veszedelmes a te sérülésed? a te bűnöd sokaságáért és vétkeidnek eláradásáért cselekedtem ezeket veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, 'Azért mindazok, a kik benyelnek téged, elnyeletnek, és valamennyi ellenséged mind fogságra jut: és a te fosztogatóidat kifosztottakká, és minden te zsákmánylóidat zsákmánynyá teszem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, 'Mert orvosságot adok néked, és kigyógyítlak a te sérülésedből, azt mondja az Úr. Mert számkivetettnek hívtak téged, Sion; nincs, a ki tudakozódjék felőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, 'Ezt mondja az Úr: Ímé, visszahozom Jákób sátorának foglyait, és könyörülök az ő hajlékain, és a város felépíttetik az ő magas helyén, és a palota a maga helyén marad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, 'És hálaadás és öröm szava jő ki belőlök, és megsokasítom őket és meg nem kevesednek, megöregbítem őket és meg nem kisebbednek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, 'És az ő fiai olyanok lesznek, mint eleintén, és az ő gyülekezete erősen megáll az én orczám előtt, de megbüntetem mindazokat, a kik nyomorgatták őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, 'És az ő fejedelme ő belőle támad, és az ő uralkodója belőle jő ki, és magamhoz bocsátom őt, hogy közeledjék hozzám: mert kicsoda az, a ki szívét arra hajtaná, hogy hozzám jőjjön, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, 'És népemmé lesztek, én pedig a ti Istenetek leszek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, 'Ímé, az Úrnak szélvésze, haragja tör elő, és a rohanó szélvész a hitetlenek fejére zúdul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, 'Nem szűnik meg az Úr felgerjedt haragja, míg végbe nem viszi, és míg meg nem valósítja az ő szívének gondolatait. Az utolsó napokban értitek meg e dolgot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, 'Az időben, monda az Úr, Izráel minden nemzetségének Istene leszek, és ők az én népemmé lesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, 'Ezt mondja az Úr: Kegyelmet talált a pusztában a fegyvertől megmenekedett nép, az Isten ő előtte menvén, hogy megnyugtassa őt, az Izráelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, 'Messzünnen is megjelent nékem az Úr, mert örökkévaló szeretettel szerettelek téged, azért terjesztettem reád az én irgalmasságomat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, 'Újra felépítlek téged, és felépülsz, oh Izráel leánya. Újra felékesíted magadat, dobokkal és vígadók seregében jösz ki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, 'Még szőlőket plántálsz Samariának hegyein; a kik plántálják a plántákat, élnek is azok gyümölcsével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, 'Mert lészen egy nap, mikor a pásztorok kiáltnak az Efraim hegyén: Keljetek fel, és menjünk fel Sionba az Úrhoz, a mi Istenünkhöz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, 'Mert ezt mondja az Úr: Énekeljetek Jákóbnak vígassággal, és ujjongjatok a nemzetek fejének. Hirdessétek dicséretét, és mondjátok: Tartsd meg Uram a te népedet, az Izráel maradékát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, 'Ímé, én elhozom őket észak földéből, és összegyűjtöm őket a földnek széleiről, közöttök lesz vak, sánta, viselős és gyermek-szűlő is lesz velök, mint nagy sereg jőnek ide vissza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, 'Siralommal jőnek és imádkozva hozom őket, vezetem őket a vizek folyásai mellett egyenes úton, hol el nem esnek, mert atyja leszek az Izráelnek, és az Efraim nékem elsőszülöttem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, 'Halljátok meg az Úrnak szavát, ti pogányok, és hirdessétek a messzevaló szigeteknek, és ezt mondjátok: A ki elszórta az Izráelt, az gyűjti őt össze, és megőrzi, mint a pásztor a maga nyáját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, 'Mert megváltotta az Úr Jákóbot, és kimentette a nálánál erősebbnek kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 12, 'És eljőnek és énekelnek a Sion ormán, és futnak az Úrnak javaihoz, búza, bor, olaj, juhok és barmok nyája felé, és az ő lelkök olyan lesz, mint a megöntözött kert, és nem bánkódnak többé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 13, 'Akkor vígadoz a szűz a seregben, és az ifjak és a vének együttesen, és az ő siralmokat örömre fordítom, és megvígasztalom és felvidámítom őket az ő bánatukból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 14, 'És a papok lelkét megelégítem kövérséggel, és az én népem eltelik javaimmal, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 15, 'Ezt mondja az Úr: Szó hallatszott Rámában, sírás és keserves jajgatás; Rákhel siratta az ő fiait, nem akart megvígasztaltatni az ő fiai felől, mert nincsenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 16, 'Ezt mondja az Úr: Tartsd vissza szódat a sírástól és szemeidet a könyhullatástól, mert meglesz a te cselekedetednek jutalma, azt mondja az Úr, hiszen az ellenség földéből térnek vissza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 17, 'Jövendődnek is jó reménysége lészen, azt mondja az Úr, mert fiaid visszajőnek az ő határaikra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 18, 'Jól hallottam, hogy panaszolkodott Efraim: Megvertél engem és megverettetém, mint a tanulatlan tulok; téríts meg engem és megtérek, mert te vagy az Úr, az én Istenem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 19, 'Mert azután, hogy megtérítettél engem, megbántam bűnömet, és miután megismertem magamat, czombomat vertem; szégyenkezem és pirulok, mert viselem az én ifjúságomnak gyalázatát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 20, 'Avagy nem kedves fiam-é nékem Efraim? Avagy nem kényeztetett gyermek-é? Hiszen valahányszor ellene szóltam, újra megemlékeztem ő róla, azért az én belső részeim megindultak ő rajta, bizony könyörülök rajta, azt mondja az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 21, 'Rendelj magadnak útjelzőket, rakj útmutató oszlopokat, vigyázz az ösvényre, az útra, a melyen mentél, jőjj vissza Izráelnek leánya, jőjj vissza ide a te városodba!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 22, 'Meddig bújdosol, oh szófogadatlan leány? Mert az Úr új rendet teremt e földön. Asszony környékezi a férfit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 23, 'Ezt mondja a Seregek Ura, Izráel Istene: Újra e szókat mondják majd a Júda földén és az ő városaiban, mikor visszahozom az ő foglyaikat: Áldjon meg téged az Úr, oh igazságnak háza, oh szent hegy!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 24, 'És ott lakoznak majd Júda és minden ő városa, a szántóvetők és baromtartók együttesen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 25, 'Mert megitatom a szomjú lelket, és minden éhező lelket megelégítek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 26, 'Ezért vagyok ébren és vigyázok, és az én álmom édes nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 27, 'Ímé, eljőnek a napok, azt mondja az Úr, és bevetem az Izráel házát és a Júda házát embernek magvával és baromnak magvával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 28, 'És a miképen gondom volt arra, hogy kigyomláljam és elrontsam, letörjem és pusztítsam és veszedelembe sodorjam őket, azonképen vigyázok arra, hogy megépítsem és beplántáljam őket, azt mondja az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 29, 'Ama napokban nem mondják többé: Az atyák ették meg az egrest, és a fiak foga vásott el bele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 30, 'Sőt inkább kiki a maga gonoszságáért hal meg; minden embernek, ki megeszi az egrest, tulajdon foga vásik el bele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 31, 'Ímé, eljőnek a napok, azt mondja az Úr; és új szövetséget kötök az Izráel házával és a Júda házával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 32, 'Nem ama szövetség szerint, a melyet az ő atyáikkal kötöttem az napon, a melyen kézen fogtam őket, hogy kihozzam őket Égyiptom földéből, de a kik megrontották az én szövetségemet, noha én férjök maradtam, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 33, 'Hanem ez lesz a szövetség, a melyet e napok után az Izráel házával kötök, azt mondja az Úr: Törvényemet az ő belsejökbe helyezem, és az ő szívökbe írom be, és Istenökké leszek, ők pedig népemmé lesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 34, 'És nem tanítja többé senki az ő felebarátját, és senki az ő atyjafiát, mondván: Ismerjétek meg az Urat, mert ők mindnyájan megismernek engem, kicsinytől fogva nagyig, azt mondja az Úr, mert megbocsátom az ő bűneiket, és vétkeikről többé meg nem emlékezem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 35, 'Ezt mondja az Úr, a ki adta a napot, hogy világítson nappal, a ki törvényt szabott a holdnak és a csillagoknak, hogy világítsanak éjjel, a ki felháborítja a tengert és annak habjai zúgnak, Seregek Ura az ő neve:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 36, 'Ha eltünnek e törvények előlem, azt mondja az Úr, az Izráelnek magva is megszakad, hogy soha én előttem nép ne legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 37, 'Ezt mondja az Úr: Ha megmérhetik az egeket ott fenn, és itt alant kifürkészhetik a föld fundamentomait: én is megútálom Izráelnek minden magvát, mindazokért, a miket cselekedtek, azt mondja az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 38, 'Ímé eljőnek a napok, azt mondja az Úr, és felépíttetik a város az Úrnak a Hanániel tornyától fogva a szeglet kapujáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 39, 'És kijjebb megy még a mérőkötél azzal átellenben a Garéb hegyéig, és lefordul Góhat felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 40, 'És a holttesteknek és a hamunak egész völgye, és az egész mező a Kidron patakáig, a lovak kapujának szegletéig kelet felé az Úr szent helye lesz, nem rontatik el, sem el nem pusztíttatik soha örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 1, 'Az a szó, a melyet szóla az Úr Jeremiásnak, Sedékiásnak, a Júda királyának tizedik esztendejében: Ez az esztendő a Nabukodonozor tizennyolczadik esztendeje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 2, 'És akkor megszállotta vala a babiloni király serege Jeruzsálemet, és Jeremiás próféta elzárva vala a tömlöcznek pitvarában, a mely a Júda királyának házában vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 3, 'Mert Sedékiás, a Júda királya záratta be őt, mondván: Miért prófétálsz te, ezt mondván: Ezt mondta az Úr: Ímé, én e várost a babiloni király kezébe adom és beveszi azt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 4, 'És Sedékiás, a Júda királya, meg nem menekszik a Káldeusok kezéből, hanem a babiloni király kezébe adatik, és ennek szája szól amannak szájával, és ennek szemei látják amannak szemeit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 5, 'És Babilonba viszi Sedékiást és ott lesz mindaddig, míg meg nem látogatom őt, azt mondja az Úr, hogyha hadakoztok a Káldeusok ellen, nem lesz jó dolgotok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 6, 'És monda Jeremiás: Szólott az Úr nékem, ezt mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 7, 'Ímé, Hanameél, Sallumnak, a te nagybátyádnak fia hozzád megy, mondván: Vedd meg az én mezőmet, a mely Anatótban van, mert téged illet vér szerint, hogy megvegyed.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 8, 'Eljöve azért hozzám Hanameél, az én nagybátyámnak fia, az Úr beszéde szerint a tömlöcz pitvarához, és monda nékem: Kérlek, vedd meg az én mezőmet, a mely Anatótban, a Benjámin földén van, mert téged illet, mint örököst, és te reád néz vér szerint is, vedd meg hát magadnak. Akkor észrevevém, hogy az Úr szava ez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 9, 'Azért megvevém Hanameéltől, az én nagybátyámnak fiától a mezőt, a mely Anatótban van, és kifizettem néki a pénzt, tizenhét ezüst siklust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 10, 'És beírám levélbe és megpecsétlém, és tanúkat is állíték, és megmérém a pénzt mérlegen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 11, 'Ezután kezembe vevém a vétel felől való levelet, a mely meg vala pecsételve a parancsolat és törvények szerint, és a közönséges levelet is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 12, 'És a vétel felől való levelet odaadám Báruknak, a Néria fiának, a ki Mahásiás fia vala, Hanameélnek, az én nagybátyám fiának szemei előtt, és a tanúk szemei előtt, a kik be valának írva a vétel felől való levélbe, mindama júdaiak szemei előtt, a kik ülnek vala a tömlöcz pitvarában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 13, 'És parancsolék Báruknak azok szemei előtt, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 14, 'Ezt mondja a Seregek Ura, az Izráel Istene: Vedd fel e leveleket, ezt a vételi levelet, mind a bepecsételtetett, mind a közönséges levelet, és tedd azokat cserépedénybe, hogy sok ideig elálljanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 15, 'Mert ezt mondja a Seregek Ura, Izráel Istene: Még házakat, mezőket és szőlőket fognak venni e földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 16, 'És könyörgék az Úrnak, miután odaadám a vétel felől való levelet Báruknak, a Néria fiának, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 17, 'Ah, ah, Uram Isten! Ímé te teremtetted a mennyet és földet a te nagy hatalmaddal és a te kiterjesztett karoddal, és semmi sincs lehetetlen előtted!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 18, 'A ki irgalmasságot cselekszel ezeríziglen, és a ki az atyák bűnéért az ő fiaik keblében fizetsz meg ő utánok, te nagy Isten, te hatalmas, a kinek neve Seregek Ura!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 19, 'Nagy tanácsú és hatalmas cselekedetű, a kinek szemei jól látják az emberek fiainak minden útait, hogy kinek-kinek megfizess az ő útai szerint, és az ő cselekedeteinek gyümölcse szerint;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 20, 'A ki jeleket és csudákat tettél Égyiptom földén és mind e napiglan mind Izráel földén, mind az embereken, és nevet szerzettél magadnak, a mint ez mai nap is megvan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 21, 'És kihoztad a te népedet, az Izráelt Égyiptom földéből jelekkel és csudákkal, és hatalmas kézzel, és kinyújtott karral, és nagy rettegtetéssel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 22, 'És nékik adtad e földet, a mely felől megesküdtél az ő atyáiknak, hogy adsz nékik tejjel és mézzel folyó földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 23, 'És bementek és birtokolták azt, mindazáltal nem hallgattak a te szódra, és nem jártak a te törvényeidben, a miket parancsoltál nékik, hogy megcselekedjék, azokból semmit sem cselekedtek, azért mind e gonoszt rájok borítottad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 24, 'Ímé, a sánczok a városhoz érnek, hogy bevegyék azt, és e város odaadatik a Káldeusok kezébe, a kik megostromolják ezt fegyverrel, éhséggel és döghalállal. És a mit szólottál, meglett, ímé látod is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 25, 'És mégis azt mondottad, Uram Isten, nékem: Végy magadnak mezőt pénzen, és legyenek tanúid felőle, holott a város a Káldeusok kezébe adatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 26, 'És szóla az Úr Jeremiásnak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 27, 'Ímé, én az Úr, Istene vagyok minden testnek, vajjon van-é valami lehetetlen nékem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 28, 'Azért ezt mondja az Úr: Ímé, én odaadom e várost a Káldeusok kezébe, és Nabukodonozornak, a babiloni királynak kezébe, hogy bevegye azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 29, 'És bemennek a Káldeusok, a kik ostromolják e várost, és e várost felgyújtják tűzzel és felégetik azt, és a házakat is, a melyeknek tetején füstöltek a Baálnak és áldoztak idegen isteneknek, hogy engem haragra ingereljenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 30, 'Mert Izráel fiai és Júda fiai ifjúságoktól fogva csak azt cselekedték, a mi gonosz az én szemeim előtt, és az Izráel fiai csak haragra gerjesztettek engem az ő kezeik cselekedeteivel, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 31, 'Mert csak bosszúságomra és búsulásomra volt e város, attól a naptól fogva, a melyen építették azt, mind ez ideig, úgy hogy el kell azt törlenem az én színem elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 32, 'Az Izráel fiainak és a Júda fiainak minden bűnéért, a melyet cselekedtek, hogy felháborítsanak engem, ők magok, az ő királyaik, fejedelmeik, papjaik és prófétáik és Júda vitézei és Jeruzsálem polgárai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 33, 'És háttal fordultak felém és nem arczczal, és tanítottam őket jó reggel, és noha tanítottam őket, nem voltak készek az intés befogadására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 34, 'Sőt az ő útálatosságaikat behelyezték a házba, a mely az én nevemről neveztetik, hogy megfertőztessék azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 35, 'És magaslatokat emeltek a Baálnak, a Ben-Hinnom völgyében, hogy megáldozzák fiaikat és leányaikat a Moloknak, a mit nem parancsoltam nékik, és még csak nem is gondoltam, hogy ez útálatosságot megcselekedjék, hogy Júdát vétekre vigyék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 36, 'És most azért azt mondja az Úr, Izráel Istene e városnak, a mely felől ti mondjátok: Odaadatik a babiloni király kezébe, fegyver, éhség és döghalál miatt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 37, 'Ímé én összegyűjtöm őket mindama földekről, a melyekre kiűztem őket haragomban, felgerjedésemben és nagy bosszankodásomban, és visszahozom őket e helyre, és lakni hagyom őket bátorságban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 38, 'És népemmé lesznek nékem, én pedig nékik Istenök leszek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 39, 'És adok nékik egy szívet és egy útat, hogy mindenkor engem féljenek, hogy jól legyen dolguk, nékik és az ő fiaiknak ő utánok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 40, 'És örökkévaló szövetséget kötök velök, hogy nem fordulok el tőlök és a velök való jótéteménytől, és az én félelmemet adom az ő szívökbe, hogy el ne távozzanak tőlem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 41, 'És örvendezek bennök, ha jót cselekedhetem velök és biztosan beplántálhatom őket e földbe, teljes szívvel és teljes lélekkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 42, 'Mert ezt mondja az Úr: A miképen ráhoztam e népre mind e nagy veszedelmet, azonképen hozom rájok mind azt a jót, a miket én ő felőlök mondok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 43, 'És vesznek még mezőt e földön, a mely felől ti ezt mondjátok: Pusztaság ez emberek nélkül, barmok nélkül, és odaadatik a Káldeusok kezébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 44, 'Pénzen vesznek mezőket, és beírják a levélbe, és megpecsételik, és tanukat állítanak a Benjámin földén, Jeruzsálem környékén és Júda városaiban, a hegyi városokban és a síkföldi városokban és a dél felé való városokban, mert visszahozom az ő foglyaikat, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 1, 'Másodszor is szóla az Úr Jeremiásnak, mikor ő még fogva vala a tömlöcz pitvarában, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 2, 'Ezt mondja az Úr, a ki megteszi azt, az Úr, a ki megvalósítja azt, hogy megerősítse azt, Úr az ő neve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 3, 'Kiálts hozzám és megfelelek, és nagy dolgokat mondok néked, és megfoghatatlanokat, a melyeket nem tudsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 4, 'Mert ezt mondja az Úr, az Izráel Istene, e városnak házai és a Júda királyának házai felől, a melyek lerontattak kosokkal és fegyverrel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 5, 'Mikor elmentek, hogy vívjanak a Káldeusokkal, és hogy megtöltsék azokat emberek holttesteivel, a kiket én haragomban és bosszúállásomban megöltem, mivelhogy elrejtettem az én orczámat a várostól az ő sok gonoszságukért:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 6, 'Ímé, én hozok néki kötést és orvosságot, és meggyógyítom őket, és megmutatom nékik a békesség és hűség kincseit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 7, 'És visszahozom Júdát és Izráelt a fogságból, és felépítem őket, mint azelőtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 8, 'És megtisztítom őket minden bűneiktől, a melyekkel vétkeztek ellenem, és megbocsátom minden bűneiket, a melyekkel vétkeztek ellenem, és a melyekkel gonoszul cselekedtek ellenem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 9, 'És ez a város lészen nékem híremre, nevemre, örömömre, tisztességemre és dicséretemre e földnek minden nemzetsége előtt, a kik hallják mindama jót, a melyet én cselekszem velök, és félni és rettegni fognak mindama jóért és mindama békességért, a melyet én szerzek nékik!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 10, 'Ezt mondja az Úr: Hallatszani fog még e helyen (a mely felől ti ezt mondjátok: Pusztaság ez, emberek nélkül és barom nélkül való), a Júda városaiban és Jeruzsálem utczáiban, a melyek elpusztíttattak és ember nélkül és lakó nélkül és oktalan állat nélkül vannak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 11, 'Örömnek szava és vígasság szava, vőlegény szava és menyasszony szava, és azoknak szava, kik ezt mondják: Dícsérjétek a Seregek Urát, mert jó az Úr, mert örökkévaló az ő kegyelme; a kik hálaáldozatot hoznak az Úr házába, mert visszahozom e föld népét a fogságból, mint annakelőtte, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 12, 'Ezt mondja a Seregek Ura: E puszta helyen, a melyen nincs ember és barom, és ennek minden városában pásztorok fognak még lakozni, a kik az ő juhaikat terelgetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 13, 'A hegyi városokban, a síkföldi városokban, a dél felől való városokban, a Benjámin földén, Jeruzsálem környékén és Júda városaiban még juhnyájak fognak átmenni a számlálónak keze alatt, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 14, 'Ímé, eljőnek a napok, azt mondja az Úr, és megbizonyítom az én jó szómat, a melyet az Izráel házának és a Júda házának szóltam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 15, 'Azokban a napokban és abban az időben sarjasztok Dávidnak igaz sarjadékot, és jogot és igazságot szerez e földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 16, 'Azokban a napokban megszabadul a Júda, és bátorságban lakozik Jeruzsálem, és így hívják majd őt: Az Úr a mi igazságunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 17, 'Mert ezt mondja az Úr: Nem vész ki a Dávid férfi sarjadéka, a ki az Izráel házának székébe üljön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 18, 'És a lévita papok férfi sarjadéka sem vész ki előlem, a ki égőáldozatot áldozzon, és ételáldozatot égessen, és véres áldozatot készítsen mindenkor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 19, 'És szóla az Úr Jeremiásnak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 20, 'Ezt mondja az Úr: Ha felbonthatjátok az én szövetségemet a nappal, és az én szövetségemet az éjszakával, hogy se nap, se éjszaka ne legyen az ő idejében:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 21, 'Az én szolgámmal, Dáviddal való szövetségem is felbomlik, hogy ne legyen fia, a ki uralkodjék az ő székében, és a lévita papokkal, az én szolgáimmal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 22, 'Mint az ég serege meg nem számlálható, és a tenger fövenye meg nem mérhető, úgy megsokasítom az én szolgámnak, Dávidnak magvát, és a Lévitákat, a kik nékem szolgálnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 23, 'És szóla az Úr Jeremiásnak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 24, 'Nem vetted észre, mit szóla e nép? mondván: A két nemzetséget, a melyet az Úr kiválasztott vala, elveté, és az én népemet megútálták úgy, hogy többé ő előttök nem nemzet az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 25, 'Ezt mondja az Úr: Ha szövetségem nem lesz a nappal és az éjszakával, és ha nem szabtam törvényeket az égnek és a földnek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 26, 'Jákóbnak és az én szolgámnak, Dávidnak magvát is elvetem, úgy hogy az ő magvából senkit fel ne vegyenek, a ki uralkodjék Ábrahámnak, Izsáknak és Jákóbnak magván: mert visszahozom őket a fogságból, és megkegyelmezek nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 1, 'Az a beszéd, a melyet szólott az Úr Jeremiásnak, (mikor Nabukodonozor a babiloni király és az egész serege és a föld minden országa, a melyek az ő hatalma alatt valának, és a népek mind vívták vala Jeruzsálemet és minden városát) mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 2, 'Ezt mondja az Úr, az Izráel Istene: Menj el, és mondd meg Sedékiásnak, a Júda királyának, és így szólj néki: Ezt mondja az Úr: Ímé, én odaadom e várost a babiloni király kezébe, és felgyújtja ezt tűzzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 3, 'És te el nem szaladsz az ő kezéből, hanem bizonynyal megfognak és kezébe adnak, és a te szemeid meglátják a babiloni királynak szemeit, és az ő szája a te száddal szól, és bemégy Babilonba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 4, 'Mindazáltal halld meg az Úrnak szavát Sedékiás, Júda királya; ezt mondja az Úr te felőled: Nem halsz meg fegyver által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 5, 'Békességben halsz meg, és a mint füstöltek a te atyáidnak, az előbbi királyoknak, a kik te előtted voltak, úgy füstölnek néked is, és így siratnak téged: Jaj uram! Mert én szóltam e szót, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 6, 'És megmondá Jeremiás próféta Sedékiásnak, a Júda királyának, mind e szavakat Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 7, 'A babiloni király serege pedig vívja vala Jeruzsálemet és Júdának minden városát, a melyek megmaradtak vala, tudniillik Lákist és Azekát, mert a Júda városai közül csak ezek maradtak vala meg, mint erősített városok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 8, 'Ez a beszéd, melyet szóla az Úr Jeremiásnak, minekutána Sedékiás király szövetséget köte az egész Jeruzsálembeli néppel, szabadságot hirdetvén köztük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 9, 'Hogy kiki bocsássa szabadon szolgáját és kiki az ő szolgálóleányát a héber férfit és a héber leányt, hogy senki ne szolgáltasson közöttük az ő Júdabeli atyjafiával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 10, 'És engedelmeskedtek mindnyájan a fejedelmek és az egész nép, a kik szövetséget kötöttek, hogy kiki szabadon bocsássa az ő szolgáját és kiki az ő szolgálóleányát, hogy senki azokkal ne szolgáltasson többé; és engedelmeskedtek és elbocsáták azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 11, 'De azután elváltozának, és visszahozák a szolgákat és szolgálóleányokat, a kiket szabadon bocsátottak vala, és őket szolgákká és szolgálóleányokká tevék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 12, 'És lőn az Úrnak szava Jeremiáshoz az Úrtól, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 13, 'Ezt mondja az Úr, Izráel Istene: Én szövetséget kötöttem a ti atyáitokkal azon a napon, a melyen kihoztam őket Égyiptom földéről, a szolgálatnak házából, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 14, 'Mikor a hét esztendő eltelik, kiki bocsássa el az ő héber atyjafiát, a ki néked eladatott vala és hat esztendeig szolgált téged; bocsássad őt magadtól szabadon. De nem hallgatának a ti atyáitok engemet, és fülöket sem hajtották erre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 15, 'És ti ma megtértetek vala, és igazat cselekedtetek vala én előttem, kiki szabadságot hirdetvén az ő atyjafiának, és én előttem szövetséget kötöttetek abban a házban, a mely az én nevemről neveztetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 16, 'De elváltoztatok, és beszennyeztétek az én nevemet, és kiki visszahozta az ő szolgáját és kiki az ő szolgálóleányát, kiket egészen szabadon bocsátottatok vala, és igába vetettétek őket, hogy néktek szolgáitok és szolgáló leányaitok legyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 17, 'Azért ezt mondja az Úr: Ti nem hallgattatok reám, hogy kiki szabadságot hirdessen az ő atyjafiának és kiki az ő felebarátjának. Ímé, én hirdetek néktek szabadságot, azt mondja az Úr, a fegyverre, a döghalálra és az éhségre, és odaadlak titeket e föld minden országainak útálatára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 18, 'És odaadom a férfiakat, a kik megszegték az én szövetségemet, a kik nem teljesítették a szövetség pontjait, a melyet előttem kötöttek vala tulokkal, a melyet ketté vágának és átmenének annak részei között,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 19, 'Júdának fejedelmeit és Jeruzsálem fejedelmeit, az udvari szolgákat és a papokat és a földnek minden népét, a kik átmentek a tulok részei között:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 20, 'Odaadom őket az ő ellenségeik kezébe, és az ő lelköket keresők kezébe, és az ő holttestök ez égi madaraknak és a föld vadainak lesznek eledelévé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 21, 'Sedékiást, a Júda királyát és az ő fejedelmeit is odaadom az ő ellenségeiknek kezébe, és az ő lelköket keresők kezébe, és a babiloni király seregének kezébe, a mely eltávozik tőletek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 22, 'Ímé, én parancsolok, azt mondja az Úr, és visszahozom őket e városra, és vívják azt, és beveszik és felgyújtják tűzzel, és pusztasággá teszem Júda városait, lakhatatlanokká.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 1, 'Az a beszéd, a melyet szóla az Úr Jeremiásnak, Jojákimnak, Jósiás, Júda királya fiának idejében, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 2, 'Menj el a Rékábiták házához, és szólj velök, és vidd be őket az Úr házába, a kamarák egyikébe, és adj nékik bort inni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 3, 'És mellém vevém Jaazániát, Jeremiásnak fiát, ki fia vala Habasániának, és az ő rokonait és minden fiait és a Rékábiták egész háznépét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 4, 'És bevivém őket az Úr házába, a Hanán fiainak a kamarájába, ki Igdaliásnak, az Isten emberének fia vala, a mely a fejedelmek kamarája mellett vala, Mahásiásnak, Sallum fiának kamaráján felül, a ki az ajtónak őrizője vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 5, 'És a Rékábiták háza népének fiai elé borral telt kancsókat és poharakat tevék, és ezt mondám nékik: Igyatok bort!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 6, 'És felelének: Nem iszunk bort, mert Jónadáb, Rékábnak fia, a mi atyánk parancsolta nékünk, mondván: Ne igyatok ti bort soha, se a ti fiaitok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 7, 'Se házat ne építsetek, se vetést ne vessetek, se szőlőt ne ültessetek, se ne tartsatok; hanem sátorokban lakjatok teljes életetekben, hogy sok ideig éljetek e földnek színén, a melyben ti jövevények vagytok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 8, 'És hallgattunk Jónadábnak a Rékáb fiának, a mi atyánknak szavára mindabban, a miket parancsolt nékünk, hogy teljes életünkben bort ne igyunk mi, a mi feleségeink, a mi fiaink és a mi leányaink.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 9, 'Se házakat ne építsünk, hogy azokban lakjunk, se szőlőnk, se mezőnk, se vetésünk ne legyen nékünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 10, 'Hanem lakozzunk sátorokban. Hallgattunk azért, és a szerint cselekedtünk, a mint nékünk Jónadáb, a mi atyánk megparancsolta vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 11, 'Mikor pedig feljöve Nabukodonozor, a babiloni király a földre, akkor ezt mondánk: Jertek el, menjünk be Jeruzsálembe a káldeai sereg előtt és a Siriabeli sereg előtt; és Jeruzsálemben lakoztunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 12, 'És szóla az Úr Jeremiásnak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 13, 'Így szól a Seregek Ura, az Izráel Istene: Menj el, mondd meg a Júda férfiainak és Jeruzsálem lakosainak: Nem veszitek-é fel az intést, hogy hallgassatok az én beszédeimre? azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 14, 'Jónadábnak, a Rékáb fiának intései teljesedtek, a melyekkel megparancsolta az ő fiainak, hogy bort ne igyanak, és mindez ideig sem ittak bort; mert hallgattak az ő atyjok parancsolatjára; én is szóltam néktek; szóltam pedig jó reggel, de nem engedtetek nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 15, 'És elküldtem hozzátok minden én szolgámat, a prófétákat, és pedig jó reggel küldém, mondván: Kérlek, kiki térjen meg az ő gonosz útjáról, jobbítsátok meg cselekedeteiteket, és idegen istenek után ne járjatok, hogy nékik szolgáljatok, és lakoztok a földön, a melyet néktek és a ti atyáitoknak adtam, de fületeket sem hajtátok reá, és nem hallgattatok reám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 16, 'Mivelhogy Jónadábnak, a Rékáb fiának fiai teljesítik az ő atyjoknak parancsolatját, melyet parancsolt vala nékik, e nép pedig nem hallgata reám;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 17, 'Azért ezt mondja az Úr, a Seregek Istene, az Izráel Istene: Ímé, én rábocsátom Júdára és Jeruzsálemnek minden lakóira mindama veszedelmet, a melyről szóltam nékik; azért mert szóltam nékik, de nem hallották, kiáltottam nékik, de nem feleltek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 18, 'A Rékábiták házának pedig monda Jeremiás: Ezt mondja a Seregek Ura, az Izráel Istene: Mivelhogy hallgattatok Jónadábnak, a ti atyátoknak parancsolatjára, és megtartottátok minden parancsolatját, és úgy cselekedtetek, a mint meghagyta volt néktek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 19, 'Azért ezt mondja a Seregek Ura, az Izráel Istene: Nem fogyatkozik el Jónadábnak, a Rékáb fiának maradéka, a ki előttem álljon mindenkor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 1, 'És Jojákimnak, a Jósiás fiának, Júda királyának negyedik esztendejében is szóla az Úr Jeremiásnak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 2, 'Végy elő egy könyvet, és mind írd belé a szókat, a miket én szóltam néked az Izráel és a Júda ellen és minden nemzet ellen, a naptól fogva, a melyen szóltam néked a Jósiás ideje óta mind e napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 3, 'Hátha meghallja a Júda háza mindazokat a veszedelmeket, a melyeket én néki szerezni szándékozom, hogy kiki megtérjen az ő gonosz útáról, és megbocsássam az ő bűnöket és vétköket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 4, 'És előhívá Jeremiás Bárukot, a Néria fiát, és megírá Báruk a Jeremiás szája után a könyvbe mindama szókat, a melyeket az Úr szólott vala néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 5, 'És parancsola Jeremiás Báruknak, mondván: Én fogoly vagyok, nem mehetek be az Úr házába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 6, 'Azért te menj be, és a könyvből, a melyet az én számból írtál, olvasd el az Úrnak szavait a népnek hallatára az Úrnak házában bőjti napon, és az egész Júdának hallatára, a kik felgyülnek az ő városaikból, olvasd el nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 7, 'Hátha az Úr elé száll könyörgésük, és mindenki megtér az ő gonosz útáról, mert nagy az Úr haragja és felháborodása, a melylyel szólott az Úr e nép ellen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 8, 'Báruk pedig, a Néria fia, mind a szerint cselekedék, a mint néki Jeremiás próféta megparancsolta vala, elolvasván a könyvből az Úrnak szavát, az Úrnak házában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 9, 'És Jojákimnak a Jósiás fiának, Júda királyának ötödik esztendejében, a kilenczedik hónapban bőjtre hívták fel az Úr elé az egész Jeruzsálem népét és az egész népet, a mely Júda városaiból jött vala fel Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 10, 'És elolvasá Báruk a könyvből Jeremiás beszédeit az Úr házában Gamáriának, az írástudó Sáfán fiának szobájában a felső pitvarban, az Úr háza új kapujának nyílásában az egész nép hallatára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 11, 'És hallá Mikeás, Gamáriának, a Sáfán fiának fia az Úrnak minden beszédét a könyvből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 12, 'És leméne a király házába az írástudó szobájába, és ímé, ott ülnek vala mind a főemberek, Elisáma, az írástudó, és Dalajás, Semájának fia, és Elnátán, Akbórnak fia, és Gamária, Sáfánnak fia, és Sedékiás, Hanániásnak fia, és a többi főember is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 13, 'És elbeszélé nékik Mikeás mindazokat, a melyeket hallott vala a könyvből, mikor olvasá Báruk a nép hallatára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 14, 'Azért elküldék mind a főemberek Jéhudit, a ki Natániának fia vala, a ki Selémiának fia vala, a ki Kusinak fia vala, Bárukhoz, mondván: A könyvet, a melyből olvastál a nép hallatára, vedd kezedbe, és jövel. És kezébe vevé Báruk, a Néria fia a könyvet, és elméne hozzájok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 15, 'És mondának néki: Ülj le csak és olvasd azt a mi fülünk hallatára, és elolvasá Báruk fülök hallatára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 16, 'És mikor meghallák mind e szókat, megrettenve tekintettek egymásra, és mondának Báruknak: Bizony megjelentjük mind e szókat a királynak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 17, 'Bárukot pedig kérdezék, mondván: Jelentsd meg csak nékünk, mimódon írtad mind e szókat az ő szájából?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 18, 'És monda nékik Báruk: Szájával mondotta nékem mind e szókat, én pedig beírtam e könyvbe tintával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 19, 'És mondának a főemberek Báruknak: Menj el, rejtőzzél el te és Jeremiás, és ne tudja senki, hol vagytok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 20, 'És elmenének a királyhoz a pitvarba (és letevék a könyvet az írástudó Elisámának szobájában) és elmondák mind e szókat a király hallatára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 21, 'És elküldé a király Jéhudit, hogy hozza el a könyvet; azért elhozá azt az írástudó Elisámának szobájából, és elolvasá azt Jéhudi a király hallatára és mindama főemberek hallatára, a kik a király előtt állnak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 22, 'A király pedig a téli házban ül vala a kilenczedik hónapban, és a tűz ég vala előtte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 23, 'És mikor Jéhudi három vagy négy levelet elolvasott vala, elmetélé azt az írástudónak késével, és a tűzbe hajítá, a mely a tűzhelyen vala, mígnem az egész könyv megége a tűzben, a mely a tűzhelyen vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 24, 'Nem rettentek meg, sem ruhájokat nem szaggatták meg a király és valamennyi szolgája, a kik hallják vala mind e szókat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 25, 'Sőt még Elnátán is és Delája és Gamária kérék a királyt, hogy a könyvet ne égesse meg, de nem hallgata rájok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 26, 'Hanem meghagyá a király Jerákmeélnek, a Hammélek fiának, és Sérajának, az Azriel fiának, és Selémiának, az Abdéel fiának, hogy fogják el Bárukot, az írástudót, és Jeremiás prófétát, de az Úr elrejté őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 27, 'Szóla pedig az Úr Jeremiásnak, miután a király megégette vala a könyvet és a beszédeket, a melyeket Báruk a Jeremiás szájából írt vala, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 28, 'Térj vissza, végy magadnak más könyvet, és írd bele mind az elébbi szókat, a melyek az elébbi könyvben valának, a melyet Jojákim, a Júda királya megégetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 29, 'És Jojákimnak, a Júda királyának mondd meg: Ezt mondja az Úr: Te égetted meg a könyvet, mondván: Miért írtál ilyen szókat bele: Bizonyosan eljő a babiloni király, és elveszti e földet, és kipusztít belőle embert és állatot?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 30, 'Azért ezt mondja az Úr Jojákim felől, a Júda királya felől: Nem lesz néki, a ki a Dávid székébe üljön, és az ő holtteste elvettetik nappal a hévre, éjszaka pedig a dérre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 31, 'És megbüntetem őt, és az ő magvát, és az ő szolgáit az ő bűneikért, és rájok bocsátom és a Jeruzsálembeli polgárokra és Júdának férfiaira mind azt a veszedelmet, a melyről szólottam nékik, de nem hallgattak meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 32, 'Azért más könyvet vőn Jeremiás, és adá azt Báruknak, az írástudó Néria fiának, és beírá abba a Jeremiásnak szájából minden szavát annak a könyvnek, a melyet Jojákim, a Júda királya megégetett vala a tűzben. És több dolgot is írának bele, hasonlókat az elébbiekhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 1, 'Uralkodott pedig Sedékiás király, Jósiásnak fia, Kónia helyett, a ki Jojákimnak fia vala, kit Nabukodonozor, a babiloni király királylyá tett vala Júdának földében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 2, 'De nem hallgatá sem ő, sem az ő szolgái, sem a föld népe az Úrnak szavát, a melyet szólott vala Jeremiás próféta által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 3, 'És elküldé Sedékiás király Júkált, Selémiának fiát, és Sofóniást, Mahásiás papnak fiát Jeremiás prófétához, mondván: Kérlek, könyörögj mi érettünk az Úrnak, a mi Istenünknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 4, 'Jeremiás pedig be- és kimegy vala a nép között, mert még nem vetették vala őt be a tömlöczbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 5, 'A Faraó serege pedig kijött Égyiptomból, és a Káldeusok, a kik megszállották Jeruzsálemet, meghallották e hírt ő felőlök, és elhagyták Jeruzsálemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 6, 'És szóla az Úr Jeremiás prófétának, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 7, 'Ezt mondja az Úr, Izráel Istene: Ezt mondjátok a Júda királyának, a ki elküldött titeket én hozzám, hogy megkérdezzetek engem: Ímé, a Faraó serege, a mely kijött a ti segítségetekre, visszamegy Égyiptom földébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 8, 'És visszatérnek a Káldeusok, és ostromolják e várost, és beveszik azt, és megégetik tűzzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 9, 'Ezt mondja az Úr: Ne csaljátok meg magatokat, mondván: Bizonyoson elmennek mi rólunk a Káldeusok; mert nem mennek el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 10, 'Mert ha a Káldeusoknak egész seregét megveritek is, a kik ostromolnak titeket, és közülök csak néhány megsebesült marad is: valamennyi felkél az ő sátorából, és megégetik e várost tűzzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 11, 'És mikor a Káldeusok serege elvonula Jeruzsálem alól a Faraó serege miatt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 12, 'Jeremiás is kiindula Jeruzsálemből, menvén a Benjámin földére, hogy osztályrészt kapjon onnan a nép között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 13, 'Mikor pedig ő a Benjámin kapujához ére és ott vala egy őr, a kinek neve Jériás vala, Selémiásnak fia, a ki Hanániásnak fia vala, megfogá az Jeremiás prófétát, és monda: Te a Káldeusokhoz szököl!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 14, 'És monda Jeremiás: Hazugság! Nem szököm a Káldeusokhoz; de nem hallgata rá. És Jériás megfogá Jeremiást, és vivé őt a fejedelmekhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 15, 'És a fejedelmek megharaguvának Jeremiásra, és megvereték őt, és veték a fogházba az írástudó Jónatán házába: mert azt rendelték vala fogháznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 16, 'Mikor Jeremiás a tömlöczbe és a börtönbe juta, és sok napig vala ott Jeremiás;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 17, 'Akkor elkülde Sedékiás király és előhozatá őt, és megkérdezé a király a maga házánál titkon, és monda: Van-é kijelentésed az Úrtól? Akkor monda Jeremiás: Van! És azt is mondá: A babiloni király kezébe adatol.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 18, 'Azután monda Jeremiás Sedékiás királynak: Mit vétettem ellened és a te szolgáid ellen és e nép ellen, hogy a fogházba vetettetek engem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 19, 'És hol vannak a ti prófétáitok, a kik prófétáltak néktek, mondván: Nem jő el a babiloni király ti ellenetek és e föld ellen?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 20, 'Most halld csak, uram király, és hallgasd meg az én könyörgésemet, és ne küldj engem vissza az írástudó Jónatán házába, hogy ott ne haljak meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 21, 'Parancsolta azért Sedékiás király, hogy vessék Jeremiást a tömlöcz pitvarába, és adjanak néki naponként egy-egy darab kenyeret a sütők utczájából, a míg minden kenyér elfogy a városból. És ott marada Jeremiás a tömlöcz pitvarában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 1, 'De meghallá Safátiás Mattánnak fia, és Gedáliás Passúrnak fia, és Jukál a Selémiás fia, és Passúr a Melékiás fia a szókat, a melyeket szólott vala Jeremiás az egész népnek, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 2, 'Ezt mondja az Úr: A ki megmarad e városban, meghal fegyver miatt, éhség miatt és döghalál miatt, a ki pedig kimegy a Káldeusokhoz, él, és az ő élete nyereség lesz néki és él.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 3, 'Ezt mondja az Úr: Bizonynyal a babiloni király seregének kezébe adatik e város, és beveszi azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 4, 'És mondának a fejedelmek a királynak: Kérünk, ölettesd meg ezt az embert, mert megerőtleníti a vitézek kezeit, a kik megmaradtak a városban, és az egész nép kezeit, hogy efféle szókat szól nékik, mert ez az ember nem a nép megmaradására igyekszik, hanem veszedelmére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 5, 'És monda Sedékiás király: Ám a ti kezetekben van, mert a király semmit sem tehet ellenetekre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 6, 'Azért elvivék Jeremiást, hogy bevessék Melkiásnak, a Hammélek fiának vermébe, a mely a tömlöcz pitvarában vala; és lebocsáták Jeremiást köteleken; a veremben pedig nem víz vala, hanem sár, és beesék Jeremiás a sárba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 7, 'És meghallotta Ebed-Melek, a szerecsen, a ki udvari szolga vala (ő pedig a király házában vala), hogy Jeremiást a verembe vetették, a király pedig a Benjámin-kapuban ül vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 8, 'Kiméne azért Ebed-Melek a király házából, és szóla a királynak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 9, 'Uram, király! gonoszul cselekedtek azok az emberek mindazzal, a mit Jeremiás prófétával cselekedtek, a kik őt a verembe vetették; mert meghal ott éhen, mert nem lesz ezután semmi kenyér e városban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 10, 'Parancsola azért a király Ebed-Meleknek, a szerecsennek, mondván: Végy magadhoz innét harmincz embert, és vedd fel Jeremiás prófétát a veremből, mielőtt meghalna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 11, 'Vőn azért Ebed-Melek magához harmincz embert, és beméne a király házába, a kincstartó ház alá, és hoza onnét régi ruhadarabokat és elszakadozott posztókat, és alábocsátá azokat Jeremiásnak köteleken a verembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 12, 'És monda Ebed-Melek, a szerecsen, Jeremiásnak: Tedd a régi és elszakadozott ruhadarabokat hónod alá, a kötelek alá; és úgy cselekedék Jeremiás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 13, 'Kivonták azért Jeremiást köteleken és kihozák őt a veremből, és lakék Jeremiás a tömlöcz pitvarában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 14, 'Elkülde pedig Sedékiás király, és magához hozatá Jeremiás prófétát a harmadik ajtóig, mely vala az Úrnak házában, és monda a király Jeremiásnak: Téged valamiről kérdelek, semmi tagadást benne ne tégy!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 15, 'Monda pedig Jeremiás Sedékiásnak: Ha megjelentem néked, avagy nem bizonyosan megölsz-é engem? és ha tanácsot adok, nem hallgatsz rám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 16, 'És megesküvék Sedékiás király Jeremiásnak titkon, mondván: Él az Úr, a ki teremtette nékünk e lelket, hogy nem öllek meg és nem adlak azoknak az embereknek kezébe, a kik keresik a te lelkedet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 17, 'Akkor monda Jeremiás Sedékiásnak: Ezt mondja az Úr, a Seregek Istene, az Izráel Istene: Ha kimégy a babiloni király fejedelmeihez, él a te lelked, és e város nem égettetik meg tűzzel, hanem élsz te és a te házad népe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 18, 'Ha pedig nem mégy ki a babiloni király fejedelmeihez, akkor e város a Káldeusok kezébe adatik, felégetik ezt tűzzel, te sem szaladsz el kezökből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 19, 'Monda Sedékiás király Jeremiásnak: Félek én a Júdabeliektől, a kik átszöktek a Káldeusokhoz, hátha azok kezébe adnak engem, és csúfoskodnak rajtam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 20, 'És monda Jeremiás: Nem adnak; kérlek, halld meg az Úrnak szavát, a melyet én mondok néked, és jó dolgod lesz, és él a te lelked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 21, 'Ha pedig te kimenni nem akarsz: ez a szó, a melyet megjelentett nékem az Úr:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 22, 'Ímé, minden asszony, a ki megmaradt vala a Júda királyának házában, kivitetik a babiloni király fejedelmeihez; és ezt mondják azok, hogy megcsaltak téged és erőt vettek rajtad a te jóakaró embereid, a te lábaid most beragadtak a sárba, ők pedig visszafordultak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 23, 'Azért minden feleségedet és gyermekedet kiviszik a Káldeusoknak, te sem menekedel meg kezökből, hanem megfogatol a babiloni király kezével, és e várost felégeti tűzzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 24, 'Monda pedig Sedékiás Jeremiásnak: Senki se tudjon e szókról, és nem halsz meg!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 25, 'Ha meghallják a fejedelmek, hogy beszéltem veled, és eljőnek hozzád és ezt mondják néked: Mondd meg csak nékünk, mit beszéltél a királynak, ne tagadj el abból tőlünk és nem ölünk meg téged, és mit monda néked a király?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 26, 'Ezt mondd nékik: Alázatosan könyörgék a királynak, hogy ne vitessen vissza Jónatán házába, hogy meg ne haljak ott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 27, 'És a fejedelmek mind elmenének Jeremiáshoz és megkérdék őt, és egészen úgy felele nékik, a mint a király parancsolta vala: és hallgatással elmenének tőle, mert nem hallották vala a beszédet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 28, 'És ott marada Jeremiás a tömlöcz pitvarában mind a napig, a melyen bevevék Jeruzsálemet, és ott vala, mikor bevevék Jeruzsálemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 1, 'Sedékiásnak, a Júda királyának kilenczedik esztendejében, a tizedik hónapban eljöve Nabukodonozor, a babiloni király és egész serege Jeruzsálem ellen, és megszállák azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 2, 'Sedékiás tizenegyedik esztendejében, a negyedik hónapban, a hónap kilenczedikén ledűle a város kőfala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 3, 'És bemenének a babiloni király fejedelmei mind és leülének a középső kapuban: Nergál-Sarézer, Samegár-Nebó, Sársekim, Rabsáris, Nergál-Sarézer, Rabmág és mind a többi fejedelmei a babiloni királynak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 4, 'És mikor meglátta vala őket Sedékiás, a Júda királya és mind a vitézlő férfiak, elfutamodának és kimenének éjjel a városból a király kertjén át az ajtón, a két kőfal között, és kimenének a pusztába vivő úton.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 5, 'És űzék őket a káldeai seregek, és elfogák Sedékiást Jerikhó pusztájában, és elhozák őt és elvivék Nabukodonozornak, a babiloni királynak Riblába, Hamát földére, és ítéletet monda rája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 6, 'És megölé a babiloni király Sedékiásnak fiait szeme láttára Riblában, és Júdának minden nemeseit is megölé a babiloni király.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 7, 'A Sedékiás szemeit pedig kitolatá, és vasba vereté őt, hogy elvigye őt Babilonba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 8, 'A király házát pedig és a nép házait felgyújták a Káldeusok tűzzel, és Jeruzsálem kőfalait leronták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 9, 'A nép többi részét pedig, a mely a városban maradt vala: és a szökevényeket, a kik hozzá szöktek vala, a nép többi részét, a még megmaradottakat elvivé Nabuzáradán, a poroszlók feje, Babilonba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 10, 'A nép szegényeit pedig, a kiknek semmijök sem vala, ott hagyá Nabuzáradán, a poroszlók feje, Júda földében, és ada nékik szőlőket és szántóföldeket azon a napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 11, 'Jeremiás felől pedig parancsot ada Nabukodonozor, a babiloni király Nabuzáradánnak, a poroszlók fejének, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 12, 'Vedd őt magadhoz, és viselj gondot reá, és semmi bajt ne okozz néki, hanem azt cselekedd vele, a mit ő akar.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 13, 'És elkülde Nabuzáradán, a poroszlók feje, és Nebusázban, Rabsáris és Nergál-Sarézer, Rabmág és a babiloni királynak több főembere.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 14, 'Elküldének, mondom, és elhozák Jeremiást a tömlöcz pitvarából, és rábízák őt Gedáliásra, Ahikámnak, a Sáfán fiának fiára, hogy haza vigye őt, és lakozzék a nép között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 15, 'Az Úr pedig szóla Jeremiáshoz, mikor ő még a tömlöcz pitvarában fogva vala, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 16, 'Menj el, és szólj Ebed-Melekkel, a szerecsennel, mondván: Ezt mondja a Seregek Ura, Izráel Istene: Ímé, én beteljesítem e város kárára és nem javára mondott beszédeimet, és azon a napon szemeid előtt lesznek azok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 17, 'És azon a napon megszabadítlak téged, azt mondja az Úr, és nem adatol amaz emberek kezébe, a kiktől félsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 18, 'Hanem bizonyára megszabadítlak téged, nem esel el fegyver miatt, és a lelked zsákmányul lesz néked, mert reménységed volt bennem, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 1, 'Az a szózat, a melyet az Úr szóla Jeremiásnak, miután Nabuzáradán, a poroszlók feje elbocsátá őt Rámából. Mikor elvitte vala őt, ő is lánczokkal vala megkötözve a jeruzsálemi és júdai mindenféle foglyok között, a kik Babilonba vitetnek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 2, 'És a poroszlók feje elvivé Jeremiást, és monda néki: Az Úr, a te Istened rendelte ezt a büntetést e hely ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 3, 'És ráhozta és megcselekedte az Úr, a mint megmondotta vala. Mert vétkeztetek az Úr ellen, és nem hallgattatok az ő szavára, azért teljesedett be ti rajtatok e dolog.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 4, 'Mostan azért ímé, én téged ma megszabadítalak a láncztól, a mely a te kezeiden van; ha tetszik néked Babilonba jőnöd, jőjj velem, nékem pedig gondom lesz reád, ha pedig nem tetszik néked, hogy eljőjj velem Babilonba, maradj itt. Ímé, az egész föld előtted van, a hova jobbnak és helyesebbnek látszik menned, menj oda.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 5, '(De ő még nem tér vala vissza.) Vagy menj vissza Gedáliáshoz, Ahikámnak, Sáfán fiának fiához, a kit a babiloni király tiszttartóvá tett Júda városaiban, és lakjál vele a nép között, vagy akárhová tetszik menned, oda menj. És ada a poroszlók feje néki étket és ajándékot, és elbocsátá őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 6, 'És elméne Jeremiás Gedáliáshoz, Ahikámnak fiához Mispába, és ott lakék vele a nép között, a kik megmaradtak a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 7, 'És mikor meghallotta a seregek minden vezetője, a kik a mezőn valának, ők magok és az ő embereik, hogy a babiloni király Gedáliást, Ahikámnak fiát tette tiszttartóvá az országban, és hogy reá bízta a férfiakat és az asszonyokat, a kisdedeket és a föld szegényeit azok közül, a kik Babilonba el nem vitettek vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 8, 'Elmenének Gedáliáshoz Mispába, tudniillik Ismáel, Natániának fia, és Jóhanán és Jónatán, Káreának fiai, és Serája, Tankumetnek fia, és a netofáti Efainak fiai, és Jazánia, Maakátnak fia, ők és az ő embereik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 9, 'És Gedáliás, Ahikámnak, Sáfán fiának fia megesküvék nékik és az ő embereiknek, mondván: Ne féljetek a Káldeusoknak szolgálni, hanem lakozzatok e földön és szolgáljatok a babiloni királynak, és jó dolgotok lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 10, 'És én ímé Mispában lakom, hogy szolgálatukra álljak a Káldeusoknak, a kik eljőnek hozzánk, ti pedig szedjetek össze bort és gyümölcsöt, és olajt is szerezzetek edényeitekbe, és lakjatok a ti városaitokban, a melyeket elfoglaltatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 11, 'És mindazok a Júdabeliek is, a kik a Moábitáknál, az Ammon fiainál, az Edomitáknál, és a kik akármely tartományban valának, meghallák, hogy a babiloni király Júdából maradékot hagyott, és hogy Gedáliást, Ahikámnak, Sáfán fiának fiát tette előttök tiszttartóvá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 12, 'Azért haza jövének mindnyájan a Júdabeliek mindenünnen, a hova elfutottak vala, és eljövének a Júda földébe Gedáliáshoz Mispába, és bort és igen sok gyümölcsöt szerzének össze.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 13, 'És Jóhanán, Káreának fia, és a seregek minden vezetője, a kik a mezőn valának, szintén elmenének Gedáliáshoz Mispába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 14, 'És mondának néki: Nem tudod-é, hogy Baálisz, az Ammoniták királya elküldötte Ismáelt, Natániának fiát, hogy téged megöljön? De nem hive azoknak Gedáliás, Ahikámnak fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 15, 'Jóhanán pedig, Káreának fia, titkolózva monda Gedáliásnak Mispában, mondván: Elmegyek és megölöm Ismáelt, Natániának fiát úgy, hogy senki se tudja. Miért oltaná el a te életedet? Hiszen a Júdabeliek, a kik te hozzád gyülekeztek vala, mind eloszlanak, és Júdának maradéka is elvész.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 16, 'És monda Gedáliás, Ahikámnak fia Jóhanánnak, a Kárea fiának: Ne cselekedd e dolgot, mert te hazugságot szólasz Ismáel felől!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 1, 'És a hetedik hónapban csakugyan eljöve Ismáel, Natániának, Elisáma fiának fia, a ki királyi nemből és a király főemberei közül való vala, és tíz férfiú vele Gedáliáshoz, Ahikámnak fiához Mispába, és együtt étkezének Mispában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 2, 'És felkele Ismáel, Natániának fia és a tíz férfiú, a kik vele valának, és megölék Gedáliást, Ahikámnak, a Sáfán fiának fiát szablyával, és megölé ő azt, a kit a babiloni király tiszttartóvá tett vala a földön!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 3, 'És mindazokat a Júdabelieket is, a kik Gedáliással valának Mispában, és a Káldeusokat is, a kik ott találtatának, tudniillik a vitézlő embereket, megölé Ismáel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 4, 'Másnap pedig a Gedáliás megölése után, még mikor senki sem tudta azt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 5, 'Férfiak jövének Sikemből, Silóból és Samariából: nyolczvan férfiú levágott szakállal, megszaggatott ruhában és bevagdalt testtel, kezökben ételáldozat és tömjén, hogy áldozzanak az Úr házában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 6, 'És kiméne eléjök Ismáel, Natániának fia Mispából, menés közben is sírván. És mikor eléjök ért vala, monda nékik: Jertek el Gedáliáshoz, Ahikámnak fiához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 7, 'És mikor bementek vala a városba, megölé őket Ismáel, Natániának fia, és hányá őket az árokba, ő és a férfiak, a kik vele valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 8, 'De tíz ember találtaték ő közöttük, a kik ezt mondák Ismáelnek: Ne ölj meg minket, mert kincsünk van nékünk a mezőn, búza és árpa, olaj és méz és megtartóztatá magát, és nem ölé meg őket az ő atyjokfiaival.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 9, 'Az árok pedig, a melybe behányá Ismáel mindamaz emberek holttestét, a kiket megöle Gedáliással együtt, az, a melyet Asa király csinált vala Baása ellen, az Izráel királya ellen. Ismáel, Natániának fia megtölté ezt a megölettekkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 10, 'És fogságra vivé el Ismáel a nép egész maradékát, a mely Mispában vala, a király leányait és az egész népet, a mely Mispában hagyatott vala, kiket Nabuzáradán, a poroszlók feje Gedáliásra, Ahikámnak fiára bízott vala; foglyul ejté azért őket Ismáel, Natániának fia, és elindula, hogy az Ammon fiaihoz menjen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 11, 'És meghallá Jóhanán, Káreának fia és a seregek minden vezetője, a ki ő vele vala, azt az egész gonoszságot, a melyet Ismáel, Natániának fia cselekedett vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 12, 'És magokhoz vevék mind az embereket, és elmenének, hogy megvívjanak Ismáellel, Natániának fiával, és elérék őt a nagy víznél, a mely Gibeonnál vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 13, 'És mikor meglátta vala az egész nép, a mely Ismáellel vala, Jóhanánt, Káreának fiát és a seregnek minden vezetőjét, a kik vele valának, megörüle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 14, 'És visszatére az egész nép, a melyet Ismáel elvitt vala Mispából, és visszatére és elméne Jóhanánhoz, Káreának fiához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 15, 'Ismáel pedig, Natániának fia nyolczadmagával szalada el Jóhanán elől, és az Ammon fiaihoz méne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 16, 'És magához vevén Jóhanán, Káreának fia, és a seregnek minden vezetője, a kik ő vele valának, a nép minden maradékát, a melyet visszahoztak vala Ismáeltől, Natániának fiától Mispából, miután ez megölé Gedáliást, Ahikámnak fiát, az erős férfiakat, vitézeket és asszonynépeket és gyermekeket és udvari szolgákat, a kiket visszahozott vala Gibeonból:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 17, 'Elindulának és megállapodának Gérut Kimhámnál, a mely közel vala Betlehemhez, hogy elmenjenek és bemenjenek Égyiptomba,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 18, 'A Káldeusok miatt, mert félnek vala tőlök, mert Ismáel, Natániának fia megölte vala Gedáliást, Ahikámnak fiát, a kit a babiloni király tiszttartóvá tett vala a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 1, 'Eljöve pedig a csapatoknak minden tisztje, és Jóhanán, Káreának fia, és Jazánia, Ozániának fia, és az egész nép kicsinytől fogva nagyig,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 2, 'És mondának Jeremiás prófétának: Hallgasd meg alázatos kérésünket, és könyörögj érettünk az Úrnak, a te Istenednek mind e maradékért; mert kevesen maradtunk meg a sokaságból, mint a te szemeid jól látnak minket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 3, 'És jelentse meg nékünk az Úr, a te Istened az útat, a melyen járjunk, és a dolgot, a mit cselekedjünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 4, 'És monda nékik Jeremiás próféta: Meghallottam. Ímé, én könyörgök az Úrnak, a ti Isteneteknek a ti beszédeitek szerint, és mindazt, a mit felel az Úr néktek, megjelentem néktek, el nem titkolok semmit tőletek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 5, 'Ők pedig mondának Jeremiásnak: Az Úr legyen ellenünk tökéletes és igaz tanúbizonyság, ha nem mind ama beszéd szerint cselekszünk, a melylyel elküld téged mi hozzánk az Úr, a te Istened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 6, 'Ha jó, ha rossz, hallgatni fogunk az Úrnak, a mi Istenünknek szavára, a melyért mi téged ő hozzá küldünk; hogy jó dolgunk legyen, mert mi hallgatunk az Úrnak, a mi Istenünknek szavára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 7, 'Lőn pedig tíz nap múlva, hogy szóla az Úr Jeremiásnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 8, 'És odahívá Jóhanánt, Káreának fiát, és a seregeknek minden tisztjét, a kik vele valának, és az egész népet kicsinytől fogva nagyig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 9, 'És monda nékik: Ezt mondja az Úr, Izráelnek Istene, a kihez küldöttetek engem, hogy megjelentsem előtte a ti könyörgésteket:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 10, 'Ha állandóan megmaradtok e földön, felépítlek titeket és el nem rontlak, és elplántállak titeket és ki nem gyomlállak: mert megbántam a gonoszt, a mit cselekedtem veletek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 11, 'Ne féljetek a babiloni királytól, a kitől most féltek, ne féljetek tőle, azt mondja az Úr; mert veletek vagyok, hogy megtartsalak és megszabadítsalak titeket az ő kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 12, 'És irgalmasságot cselekszem veletek, hogy irgalmas legyen hozzátok, és lakni hagyjon titeket a ti földeteken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 13, 'De ha ti ezt mondjátok: Nem lakunk e földön, nem hallgatván az Úrnak, a ti Isteneteknek szavára,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 14, 'Mondván: Nem! hanem Égyiptom földére megyünk be, a hol nem látunk harczot és nem hallunk trombitaszót, és kenyeret nem éhezünk, és ott lakozunk:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 15, 'Most azért halljátok meg az Úrnak szavát, Júdának maradékai! Ezt mondja a Seregek Ura, az Izráel Istene: Ha ti csak orczáitokat fordítjátok is úgy, hogy bemenjetek Égyiptomba, és bementek, hogy ott tartózkodjatok:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 16, 'Akkor a fegyver, a melytől ti féltek, legott utólér benneteket Égyiptom földén, és az éhség is, a mitől rettegtek, körülvesz titeket Égyiptomban, és ott haltok meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 17, 'Mert az lesz, hogy mindazok a férfiak, a kik úgy fordítják orczájokat, hogy bemenjenek Égyiptomba, hogy ott tartózkodjanak, meghalnak fegyver, éhség és döghalál miatt, és egy sem marad meg közülök, és nem szabadul meg a veszedelemtől, a melyet én bocsátok reájok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 18, 'Mert ezt mondja a Seregek Ura, az Izráel Istene: Miképen kiömlik az én haragom és búsulásom Jeruzsálem lakosaira, azonképen kiöntöm az én haragomat ti reátok, ha bementek Égyiptomba; és lesztek ott átok, csuda, szidalom, gyalázat, és többé nem látjátok e helyet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 19, 'Az Úr szólott hozzátok, oh Júdának maradékai! Ne menjetek Égyiptomba; jól tudjátok meg, hogy bizonyságot tettem ma ellenetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 20, 'Mert magatokat csaljátok meg a ti szívetekben: mert ti küldöttetek engem az Úrhoz, a ti Istenetekhez, mondván: Könyörögj az Úrnak, a mi Istenünknek, és a mint szól az Úr, a mi Istenünk, úgy jelentsd meg nékünk, és akképen cselekszünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 21, 'Mikor pedig ma megjelentem néktek, nem hallgattok az Úrnak, a ti Isteneteknek szavára és egyáltalán azokra, a melyekért engem ti hozzátok küldött.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 22, 'Most azért tudjátok meg jól, hogy fegyverrel, éhséggel és döghalállal haltok meg a helyen, a hová kivánkoztok menni, hogy ott tartózkodjatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 1, 'És a mint Jeremiás teljesen elmondta az egész népnek az Úr, az ő Istenök minden rendelését, melyekért az Úr, az ő Istenök küldötte vala ő hozzájok, mindazokat a rendeléseket, mondom,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 2, 'Akkor monda Azariás, Hosájának fia, Jóhanán, Káreának fia, és valamennyi kevély férfiak, mondván Jeremiásnak: Hazugságot szólsz te, nem küldött téged az Úr, a mi Istenünk, hogy ezt mondjad: Ne menjetek be Égyiptomba, hogy ott tartózkodjatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 3, 'Hanem Báruk, Nériának fia izgat téged mi ellenünk, hogy minket a Káldeusok kezébe adjon, hogy megöljenek minket, és vitessenek Babilonba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 4, 'És nem hallgata Jóhanán, Káreának fia, sem a seregnek valamennyi tisztje, sem az egész nép az Úr szavára, hogy a Júda földén maradjanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 5, 'Hanem elvivé Jóhanán, Káreának fia, és a seregnek minden tisztje Júdának egész maradékát, a kik visszajöttek vala mindama nemzetek közül, a hová kiűzettek vala, hogy lakozzanak Júdának földében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 6, 'A férfiakat és az asszonyokat, a gyermekeket és a király leányait és minden lelket, a melyet Nabuzáradán, a poroszlók feje hagyott vala Gedáliással, Ahikámnak, Sáfán fiának fiával, és Jeremiás prófétát és Bárukot, Nériának fiát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 7, 'És elmenének Égyiptomnak földébe, mert nem hallgattak az Úr szavára, és bemenének Táfnesig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 8, 'És szóla az Úr Jeremiásnak Táfnesben, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 9, 'Végy a kezedbe nagy köveket, és rejtsd el azokat a sárba, a téglaégetőkemenczébe, a mely a Faraó házának ajtajában van Táfnesben, a Júdabeli emberek szeme láttára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 10, 'És ezt mondd nékik: Ezt mondja a Seregek Ura, az Izráel Istene: Ímé, én elküldök és felhozom Nabukodonozort, a babiloni királyt, az én szolgámat, és az ő székét e kövekre teszem, melyeket elrejtettem, és azokra vonja fel az ő sátorát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 11, 'És betör, és megveri Égyiptom földét, a ki halálra való, halálra, és a ki rabságra, rabságra, és a ki fegyverre, fegyverre jut.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 12, 'És tüzet gyújtok Égyiptom isteneinek házaiban, és felégeti azokat, és foglyokká teszi őket, és magára ölti Égyiptom földét, miképen a pásztor magára ölti ruháját, és kimegy onnan békességgel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 13, 'És Bethsemesnek, a mely Égyiptom földében van, faragott képeit lerontja: és Égyiptom isteneinek házait tűzzel felégeti.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 1, 'Az a szó, a mely lőn Jeremiáshoz, minden Júdabeliek felől, a kik laknak vala Égyiptom földében, a kik laknak vala Migdolban, Táfnesben, Nófban és Pátrosz földében, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 2, 'Ezt mondja a Seregek Ura, az Izráel Istene: Ti láttátok mindazt a veszedelmet, melyet ráhoztam volt Jeruzsálemre és Júdának minden városaira, és ímé, azok most pusztává lettek, és senki sem lakozik bennök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 3, 'Az ő gonoszságokért, a melyet cselekedtek, hogy felingereljenek engem, elmenvén, hogy áldozatot vigyenek és szolgáljanak az idegen isteneknek, a kiket ők nem ismernek vala, sem ti, sem a ti atyáitok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 4, 'És elküldöttem hozzátok minden szolgámat, a prófétákat, és pedig jó reggel küldém el, mondván: Kérlek, ne cselekedjétek ez útálatos dolgot, a mit gyűlölök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 5, 'De nem hallgattak, és a fülöket sem hajtották arra, hogy megtérjenek az ő gonoszságokból, és idegen isteneknek ne áldozzanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 6, 'Azért kiömlött az én bosszúm és az én haragom, és felgerjedt Júda városaiban és Jeruzsálem utczáin, és pusztasággá és sivataggá lőnek mind e napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 7, 'Most azért ezt mondja az Úr, a Seregek Istene, az Izráel Istene: Miért szereztek nagy veszedelmet a ti lelketek ellen, hogy kipusztítsatok közületek férfit és asszonyt, gyermeket és csecsemőt Júda kebeléből, hogy magatoknak még csak maradékot se hagyjatok;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 8, 'Ingerelvén engem a ti kezeitek alkotásaival, áldozván az idegen isteneknek Égyiptom földén, a melyre ti tartózkodni jöttetek be, hogy veszedelmet szerezzetek magatoknak, és hogy átokban és gyalázatban legyetek e földnek minden nemzeténél?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 9, 'Vajjon elfelejtkeztetek-é a ti atyáitok gonoszságairól és a Júda királyainak gonoszságairól és az ő feleségeiknek gonoszságairól és a ti gonoszságaitokról, a ti feleségeiteknek gonoszságairól, a melyeket Júdának földén cselekedtetek és Jeruzsálemnek utczáin?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 10, 'Nem alázták meg magokat mind e mai napig se, és nem féltek, sem az én törvényem szerint nem jártak, sem az én parancsolataim szerint, a melyeket előtökbe és a ti atyáitok elébe adtam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 11, 'Azért ezt mondja a Seregek Ura, az Izráel Istene: Ímé, én ellenetek fordítom orczámat veszedelemre, és hogy az egész Júdát kipusztítsam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 12, 'És felveszem Júdának maradékát, a kik magok elé tűzték, hogy bemennek Égyiptom földére, hogy ott lakozzanak, és mindnyájan megemésztetnek Égyiptom földén, elesnek fegyver miatt, megemésztetnek éhség miatt, kicsinytől fogva nagyig: fegyver és éhség miatt halnak meg, és átokká, csudává, szidalommá és gyalázattá lesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 13, 'És megfenyítem azokat, a kik Égyiptom földében lakoznak, miképen megfenyítettem a Jeruzsálembelieket fegyverrel, éhséggel és döghalállal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 14, 'És a Júda maradékai közül, a kik ide jöttek, hogy Égyiptom földében tartózkodjanak, senki sem menekül és szabadul meg, hogy visszatérjen Júdának földébe, a hova lelkök hajtja őket, hogy oda visszatérjenek és ott lakozzanak; mert nem térnek vissza, hanem csak a kik menekülnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 15, 'És felelének Jeremiásnak mindama férfiak, a kik tudják vala, hogy az ő feleségeik az idegen isteneknek áldozának, és mindazok az asszonyok, a kik ott állnak vala nagy tömegben, és az egész nép, a mely Égyiptom földén, Pátroszban lakozik vala, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 16, 'Abban a dologban, a mi végett szóltál nékünk az Úr nevében, nem hallgatunk reád;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 17, 'Hanem csak azt cselekeszszük, a mit mi a mi szánkkal fogadtunk, hogy füstölő áldozatot viszünk az ég királynéjának, és néki italáldozattal áldozunk, miképen cselekedtünk mi és a mi atyáink és a mi királyaink és a mi fejedelmeink Júda városaiban és Jeruzsálemnek utczáin, mert akkor beteltünk kenyérrel, és jó dolgunk volt, és semmi rosszat nem láttunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 18, 'De a mióta nem áldozunk többé az ég királynéjának füstöléssel, és nem viszünk néki italáldozatot: mindenben szűkölködünk, és fegyver és éhség miatt emésztetünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 19, 'És hogyha mi az ég királynéjának füstölve áldozunk és néki italáldozatot viszünk: vajjon a mi férjeink híre nélkül csinálunk-é néki béleseket, hogy őt tiszteljük, és néki itali áldozatot vigyünk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 20, 'Szóla azért Jeremiás az egész népnek, a férfiaknak és az asszonyoknak és az egész népnek, a kik e szót felelték néki, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 21, 'Avagy a jó illatról, a melyet Júda városaiban és Jeruzsálem utczáin füstöltetek ti és a ti atyáitok, a ti királyaitok és a ti fejedelmeitek és a föld népe: nem arról emlékezett-é meg az Úr, és nem az jutott-é néki eszébe?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 22, 'És nem szenvedhette tovább az Úr a ti cselekedeteitek gonoszságát, az útálatosságok miatt, a melyeket cselekedtetek, és pusztasággá lett a ti földetek és csudává és átokká, annyira, hogy senki sem lakja mind e napig,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 23, 'A miatt, hogy füstölve áldoztatok, és vétkeztetek az Úr ellen, és nem hallgattatok az Úr szavára, és az ő törvénye és az ő parancsolatai és az ő tanúbizonyságai szerint nem jártatok, azért következett ti reátok ez a veszedelem mind e napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 24, 'Monda továbbá Jeremiás az egész népnek és az összes asszonyoknak: Halljátok meg az Úr szavát mind, ti Júdabeliek, kik Égyiptom földén vagytok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 25, 'Ezt mondja a Seregek Ura, az Izráel Istene, mondván: Ti és a ti feleségeitek szóltatok a ti szájatokkal, és végbevittétek a ti kezeitekkel, mondván: Bizonyára teljesítjük a mi fogadásainkat, a melyeket fogadtunk az ég királynéjának, hogy füstölve áldozzunk, és néki italáldozatot vigyünk. Megerősítvén megerősítettétek a ti fogadásaitokat, és megcselekedvén megcselekedtétek a ti fogadásaitokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 26, 'Azért halljátok meg az Úr szavát mind, ti Júdabeliek, a kik Égyiptom földében lakoztok: Ímé, én az én nagy nevemre megesküdtem, azt mondja az Úr, hogy egyetlen Júdabeli férfiú szája sem fogja az én nevemet kiejteni, mondván: Él az Úr Isten, egész Égyiptom földén!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 27, 'Ímé, én vigyázok reájok az ő kárukra és nem javukra, és megemésztetik Júdának minden férfia, a kik Égyiptom földén vannak, fegyver miatt, éhség miatt, mígnem mind elfogynak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 28, 'De a kik a fegyvertől megszabadulnak, visszatérnek Égyiptom földéről Júdának földére, szám szerint kevesen, és mind megtudják Júdának maradékai, a kik bementek Égyiptom földébe, hogy ott tartózkodjanak: melyik szó teljesedik be, az enyém-é vagy az övék?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 29, 'És ez lesz néktek a jel, azt mondja az Úr, hogy én meglátogatlak titeket ezen a helyen, hogy megtudjátok, hogy bizonyára megállanak az én beszédeim a reátok következendő veszedelem felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 30, 'Ezt mondja az Úr: Ímé, én odaadom Faraó Ofrát, Égyiptom királyát az ő ellenségeinek kezébe és az ő lelkét keresők kezébe, miképen odaadtam Sedékiást, a Júda királyát Nabukodonozornak, a babiloni királynak, az ő ellenségének és az ő lelkét keresőnek kezébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 1, 'Az a szó, a melyet Jeremiás próféta szóla Báruknak, Néria fiának, mikor ő könyvbe írá e szókat Jeremiás szájából, Jójákimnak, Jósiás, Júdabeli király fiának negyedik esztendejében, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 2, 'Ezt mondja az Úr, Izráel Istene, te néked, Báruk:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 3, 'Ezt mondottad: Jaj mostan nékem, mert az Úr az én bánatomra fájdalmat adott, elfáradtam az én fohászkodásomban, és nyugodalmat nem találtam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 4, 'Ezt mondd néki: Ezt mondja az Úr: Ímé, a kiket én felépítettem, elrontom, és a kiket én beplántáltam, kiszaggatom, és pedig az egész földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 5, 'És te kivánsz-é magadnak nagyokat? Ne kivánj; mert ímé én veszedelmet bocsátok minden testre, ezt mondja az Úr, és a te lelkedet zsákmányul adom néked, minden helyen, a hová elmégy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 1, 'Ez a szó, a melyet az Úr szólott Jeremiás prófétának a pogányok felől;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 2, 'Égyiptom felől, a Nékó Faraónak, Égyiptom királyának serege felől, a mely az Eufrátes folyó mellett, Kárkémisben vala, a melyet megvere Nabukodonozor, a babiloni király, Jójákimnak, Jósiás fiának, Júda királyának negyedik esztendejében:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 3, 'Készítsetek vértet és paizst, és induljatok a harczra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 4, 'Nyergeljétek a lovakat, és üljetek fel ti lovasok, és legyetek sisakokban. Tisztítsátok a kopjákat, öltsétek fel a pánczélokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 5, 'Mit látok? Ők megriadva hátrálni kezdenek, vitézeik leveretnek és futásnak erednek, és vissza sem tekintenek! Mindenfelől félelem, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 6, 'Nem futhat el a gyors, és az erős sem menekülhet el; észak felé, az Eufrátes folyó mellett legyőzetnek és elhullanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 7, 'Kicsoda ez, a ki növekedik, mint a folyóvíz, és olyan, mint a megháborodott vizű folyamok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 8, 'Égyiptom növekedik úgy, mint a folyóvíz és mint a megháborodott vizű folyamok, mert ezt mondja: Felmegyek, ellepem a földet, elvesztem a várost és a benne lakókat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 9, 'Jőjjetek fel lovak, és zörögjetek szekerek, jőjjenek ki a vitézek, a szerecsenek és a Libiabeliek, a kik paizst viselnek, és a Lidiabeliek, a kik kézívet viselnek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 10, 'Az a nap pedig az Úrnak, a Seregek Urának büntető napja, hogy bosszút álljon ellenségein. És a fegyver felemészt és jól lakik és megrészegül az ő vérökkel, mert áldozatja lesz az Úrnak, a Seregek Urának észak földén, az Eufrátes folyó mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 11, 'Menj föl Gileádba, és végy balzsamot te szűz, Égyiptomnak leánya: hiába sokasítod az orvosságokat, nincs gyógyír számodra!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 12, 'Hallották a pogányok a te gyalázatodat, és a te kiáltásoddal betelt a föld, mert vitéz vitézbe ütközött, és mind a ketten együtt estek el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 13, 'Az a szó, a melyet az Úr Jeremiás prófétához szólott, Nabukodonozornak, a babiloni királynak eljövetele felől az Égyiptom földének megverésére:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 14, 'Hirdessétek Égyiptomban és híreszteljétek Migdólban, híreszteljétek Nófban és Táfnesben, és ezt mondjátok: Állj elő, és készítsd fel magadat, mert fegyver emészti meg a te kerületeidet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 15, 'Miért verettek le a te erőseid? Nem állhattak meg, mert az Úr rettentette el őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 16, 'Megsokasította a tántorgót, egyik a másikra hullott, és ezt mondották: Kelj fel, és menjünk vissza a mi népünkhöz és a mi szülőföldünkre az erőszakoskodó fegyver elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 17, 'Ezt kiáltják akkor: A Faraó, Égyiptom királya, a háborúságnak királya, elhaladta a rendelt időt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 18, 'Élek én, azt mondja a király, a kinek a neve Seregek Ura, hogy mint a Táborhegy áll a hegyek között, és mint a Kármel a tenger között, úgy jő el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 19, 'Készíts magadnak elköltözésre való edényeket, Égyiptom leányának lakosa, mert Nóf elpusztul és megég, lakatlanná lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 20, 'Szép üszőtinó Égyiptom, de pusztulás tör reá észak felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 21, 'Még zsoldosai is olyanok ő közöttök, mint a hízlalt borjúk, de ők is meghátrálnak, egyetemlegesen elfutnak, meg nem állanak, mert romlásuk napja jön reájok, az ő megfenyíttetésök ideje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 22, 'Az ő szava mint a csúszó kígyóé, mert nagy sereggel indulnak, és szekerczékkel jőnek ellene, mint a favágók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 23, 'Kivágják az ő erdejét, azt mondja az Úr, mert beláthatatlanok, mert többen lesznek mint a sáskák, és megszámlálhatatlanok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 24, 'Megszégyenül Égyiptom leánya, északi nép kezébe jut.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 25, 'Ezt mondja a Seregek Ura, az Izráel Istene: Ímé, én megfenyítem Nó-Ammont és a Faraót és Égyiptomot és az ő isteneit és királyait, mind a Faraót, mind azokat, a kik bíznak benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 26, 'Odaadom őket az ő lelkök keresőinek kezébe, és Nabukodonozornak, a babiloni királynak kezébe, és az ő szolgáinak kezébe; de azután úgy lakoznak abban, mint azelőtt, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 27, 'És te ne félj, oh én szolgám Jákób, és ne rettegj Izráel, mert ímé, én megszabadítlak téged messziről, és a te magodat is az ő fogságuk földéről, és visszatér Jákób és megnyugszik és békességben lesz, és nem lesz, a ki megijeszsze.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 28, 'Ne félj te, oh én szolgám Jákób, azt mondja az Úr, mert én veled vagyok, mert véget vetek minden nemzetnek, a kik közé kivetettelek téged, néked pedig nem vetek véget, hanem megverlek téged ítélettel, mert nem hagyhatlak teljesen büntetés nélkül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 1, 'Az a szó, a melyet az Úr szóla Jeremiás prófétának a Filiszteusok felől, mielőtt megverte a Faraó Gázát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 2, 'Ezt mondja az Úr: Ímé, víz indul meg északról, és olyan lesz, mint a kiáradott folyó, és elárasztja a földet és annak mindenét, a várost és annak lakosait, és kiáltanak az emberek, és a föld minden lakosa ordít.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 3, 'Ménei patáinak csattogó hangjától, szekereinek zörgésétől, kerekeinek zúgásától nem gondolnak az atyák a fiakra erejök ellankadása miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 4, 'És a nap miatt, mely eljött, hogy elpusztítsa egész Filiszteát, kivágja Tírust és Szidont és segítségének minden megmaradt töredékét, mert az Úr elrontja Filiszteát, a Káftor szigetének maradékát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 5, 'Kopaszság lepte meg Gázát, Askalon elnémult, maradéka az ő völgyüknek: meddig vagdalod magadat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 6, 'Oh szablyája az Úrnak, meddig nem nyugszol meg? Rejtsd el magadat a te hüvelyedbe, nyugodjál meg és hallgass!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 7, 'Miképen nyughatik meg, holott az Úr parancsolt néki? Askalonra és a tenger partjára oda rendelte őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 1, 'Moáb felől ezt mondja a Seregek Ura, az Izráel Istene: Jaj Nébónak, mert elpusztíttatott; megszégyenült, bevétetett Kirjátaim, Misgáb megszégyenült és elrémült.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 2, 'Nincs már dicsősége Moábnak Hesbonban, gonoszt gondoltak ő ellene, mondván: Jertek el és veszessük el őt, ne legyen nemzetség! Madmen te is elnémulsz, fegyver jár nyomodban!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 3, 'Nagy kiáltás hallatszik Horonáimból: pusztulás és nagy romlás!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 4, 'Elnyomorodott Moáb, kicsinyei sikoltva kiáltanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 5, 'Mert a Luhit hágóján siralmat siralom ér, mert Horonáim lejtőin az ellenség hallatja vészkiáltását.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 6, 'Fussatok, mentsétek meg lelketeket, és legyetek mint a hangafa a pusztában!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 7, 'Mivelhogy a te bizodalmad marháidban és kincseidben volt, te is bevétetel, és Kámós fogságra megy papjaival, fejedelmeivel együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 8, 'És rátör a pusztító minden városra, egy város sem menekedik meg, és elvész a völgy, és feldúlatik a síkság, a mint megmondta az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 9, 'Adjatok szárnyat Moábnak, hogy repülvén elrepülhessen, mert az ő városai elpusztulnak, és senki sem lakik azokban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 10, 'Átkozott, a ki az Úrnak dolgát csalárdul cselekszi, és átkozott, a ki fegyverét kiméli a vértől!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 11, 'Nyugodtan élt Moáb gyermekségétől fogva, és pihent az ő seprejében, és edényből-edénybe nem öntötték és fogságra sem ment, azért maradt meg az íze rajta, és nem változott el az ő szaga.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 12, 'De ímé eljőnek a napok, azt mondja az Úr, és rablókat bocsátok reá, a kik megrabolják őt, és megüresítsék edényeit, palaczkjait pedig összetörjék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 13, 'És megszégyenül Moáb Kámós miatt, a mint megszégyenült Izráel háza Béthel miatt, a melyben bizodalma volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 14, 'Mimódon mondjátok: Hősök vagyunk és vitéz férfiak a harczra?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 15, 'Elpusztul Moáb, városai fellobbannak, válogatott ifjai pedig mészárszékre jutnak, azt mondja a király, a kinek neve Seregek Ura!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 16, 'Közel van Moáb veszedelme, ihol jő és igen siet az ő veszedelme!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 17, 'Bánkódjatok miatta mindnyájan, a kik körülte vagytok, és mindnyájan, a kik ismeritek az ő nevét; mondjátok: Hogy eltört az erős vessző, a dicső pálcza!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 18, 'Szállj le a dicsőségből és ülj szomjan Dibonnak megmaradt leánya, mert a Moáb pusztítója feljött ellened, elrontja a te erősségeidet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 19, 'Állj meg az úton, és nézz ide-oda Aroér lakosa, kérdezd meg a futót és a menekülőt, és ezt mondd: Mi történt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 20, 'Megszégyenült Moáb, mert megtört. Ordítsatok és kiáltsatok! Hirdessétek Arnonban, hogy elpusztíttatott Moáb!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 21, 'Mert rájött az ítélet a sík földre; Hólonra, Jására és Mefátra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 22, 'És Dibonra, Nébóra és Beth-Diblátaimra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 23, 'És Kirjáthaimra, Beth-Gámulra és Beth-Meonra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 24, 'És Kirjátra, Boczrára és Moáb földének minden messze és közel való városaira.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 25, 'Letöretett a Moáb szarva, és karja levágatott, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 26, 'Részegítsétek le őt, mert hősködött az Úr ellen, és heverjen Moáb az ő okádásában, és legyen csúfság ő is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 27, 'Vajjon nem csúfod volt-é néked az Izráel? Avagy a lopók között találtatott, hogy mikor szólottál felőle, kevélyen hánytad magadat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 28, 'Hagyjátok el a városokat, és lakjatok a kősziklákban, Moáb lakosai, és legyetek mint a galamb, a mely az odu száján belől rak fészket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 29, 'Hallottuk a Moáb kevélységét: igen kevély; az ő felfuvalkodását és kevélységét, kérkedését, és az ő szívének elbizakodottságát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 30, 'Én ismerem, azt mondja az Úr, az ő szertelenkedését, és az ő fecsegése nem igaz, és nem igaz a cselekedete sem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 31, 'Azért jajgatok Moábon, és az egész Moábért kiáltok, a Kir-Heres férfiaiért nyög az én lelkem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 32, 'Jobban siratlak téged, mint siratták Jaézert, a ki Sibmának szőlője! A te hajtásaid túlhatoltak a tengeren, a Jaézer tengeréig értek; a te nyári gyümölcseidre és a te szüretedre pusztító rontott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 33, 'És eltünik az öröm és vígasság Kármelből és a Moáb földéről, és a kádakból kifogyasztom a bort, nem sajtolnak örömzajjal; az éneklő nem énekel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 34, 'Hesbon kiáltása miatt Elealéig és Jáhásig felhat az ő szavok; Soártól fogva Horonáimig és Eglath-Selisájjáig, mert a Nimrim vize is elapad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 35, 'És kifogyasztom Moábból, azt mondja az Úr, a ki a magaslaton áldozik és füstöt gerjeszt az ő isteneinek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 36, 'Ezért zokog a szívem Moábért, mint a síp, és zokog szívem a Kir-Héres férfiaiért, mint a síp, mivelhogy a kincsek elvesztek, a miket gyűjtött.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 37, 'Mert minden fő kopasz, és minden szakál elnyiratott, minden kézen metélések, és minden derékon gyászruha.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 38, 'Moábnak minden házpadján és utczáján mindenütt siralom, mert összetörtem Moábot, mint az edényt, mely semmirekellő, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 39, 'Jajgatnak, ezt mondván: Hogy összezúzatott! Hogy fordult háttal Moáb, megszégyenülve! És csúffá lett Moáb, és rettentésére mindazoknak, a kik körülte vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 40, 'Mert ezt mondja az Úr: Ímé, mint a saskeselyű repül reá, és kiterjeszti Moábra szárnyait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 41, 'Bevétettek a városok, és az erősségek elfoglaltattak, és a Moáb vitézeinek szíve olyan volt e napon, mint a vajudó asszonynak szíve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 42, 'És Moáb elpusztul, úgy hogy nem lesz nép többé, mert az Úr ellen felemelkedett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 43, 'Félelem, verem és tőr jő te ellened, Moáb lakosa, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 44, 'A ki elfut a félelem elől, a verembe esik, és a ki kijő a veremből, a tőrben fogatik meg, mert rábocsátom Moábra az ő megfenyítésének esztendejét, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 45, 'A Hesbon árnyékában állanak meg a hatalom elől futók; de tűz jő ki Hesbonból és láng Szihonnak közepéből, és elemészti Moábnak üstökét és a háborgó fiaknak koponyáját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 46, 'Jaj néked Moáb! Elveszett Kámósnak népe, mert fiaid fogságra vitettek, és leányaid is fogságra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 47, 'De visszahozom Moábot a fogságból sok idő mulva, azt mondja az Úr. Eddig van Moáb ítélete.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 1, 'Az Ammon fiai felől ezt mondja az Úr: Nincsenek-é Izráelnek fiai? Nincsen-é örököse néki? Miért birtokolja Milkom Gádot, és az ő népe miért lakik annak városaiban?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 2, 'Azért ímé eljőnek a napok, azt mondja az Úr, és harczi riadót hallatok Rabbában az Ammon fiaival, és romhalommá lesz, és leányai tűzzel égettetnek meg, és Izráel birtokolja azokat, a kik most őt birtokolják, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 3, 'Ordíts Hesbon, mert elpusztíttatott Hái! Kiáltsatok Rabbáh leányai, öltözzetek gyászba, sírjatok és futkossatok a szorosokon, mert Milkom a fogságba megy, papjai és fejedelmei is vele együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 4, 'Mit dicsekedel völgyeddel, völgyed bőségével, engedetlen leány, a ki az ő kincseiben bízik és ezt mondja: Kicsoda támad ellenem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 5, 'Ímé én félelmet bocsátok reád, azt mondja az Úr, a Seregek Ura, minden szomszédod felől, és szétrebbentek egymástól, és nem lesz, a ki összegyűjtse az elszéledteket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 6, 'De azután visszahozom majd a fogságból az Ammon fiait, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 7, 'Ezt mondja a Seregek Ura Edom felől. Nincs bölcsesség többé Témánban? elveszett-é a tanács az értelmesektől? hiába valóvá lett-é az ő bölcsességök?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 8, 'Fussatok, forduljatok, rejtőzzetek el mélyen Dédán lakosai, mert Ézsau veszedelmét hozom ő reá az ő megfenyíttetésének idején.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 9, 'Ha szőlőszedők törnek reád, nem hagynak gerezdeket, ha éjjeli tolvajok: pusztítanak, a míg nékik tetszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 10, 'Bizony én mezítelenné teszem Ézsaut, titkait kijelentem, és el nem rejtőzhetik, magva elpusztul, és atyjafiai és szomszédai sem lesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 11, 'Hagyd el a te árváidat, én eltartom özvegyeidet is; bennem vessék reménységüket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 12, 'Mert azt mondja az Úr: Ímé, a kiknek nem kell vala meginniok a pohárt, ugyancsak megiszszák; te pedig teljesen büntetlenül maradnál-é? Nem maradsz büntetlenül, mert bizonyára megiszod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 13, 'Mert én magamra esküdtem meg, azt mondja az Úr, hogy útálattá és gyalázattá, pusztasággá és átokká lesz Boczra, és minden városa örökkévaló pusztasággá lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 14, 'Hírt hallottam az Úrtól, és követ küldetett a nemzetekhez, a ki ezt mondja: Gyűljetek össze, induljatok ellene, és keljetek fel a harczra,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 15, 'Mert ímé, kicsinynyé teszlek téged a nemzetek között, és az emberek között útálatossá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 16, 'A te könnyelműséged csalt meg téged és a te szíved kevélysége, a ki a sziklák hasadékaiban lakol, és elfoglaltad a halmok tetejét. Ha olyan magas helyen rakod is fészkedet, mint a saskeselyű, onnét is lerántalak téged, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 17, 'És pusztasággá lesz Edom, a ki csak átmegy rajta elálmélkodik, és sziszeget egész veresége felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 18, 'A mint Sodomának és Gomorának és az ő szomszédainak elsüllyedésekor volt, azt mondja az Úr, ott sem lakik több ember, és benne emberek fia nem tartózkodik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 19, 'Ímé, mint oroszlán jön fel a Jordán erdőségéből az örökzöld legelőre, de hamarsággal kiűzöm őt onnan, és a kiválasztottat teszem azon fejedelemmé, mert kicsoda hozzám hasonló, és ki szab nékem törvényt, és kicsoda az a pásztor, a ki megállhat ellenem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 20, 'Halljátok meg azért az Úr tervét, a melyet tervezett Edom felől, és az ő gondolatait, a melyeket gondolt Témán polgárai felől. Bizony elhurczolják őket, a juhnyáj kicsinyeit, bizony szörnyűködik rajtok a saját legelőjök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 21, 'Az ő romlásuk zajától megrendült a föld, az ő kiáltásuk szava elhallatszik a veres tengerig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 22, 'Ímé, feljő mint saskeselyű, és repül és szárnyait szétterjeszti Boczrán: és Edom vitézeinek szíve olyan lesz az napon, mint a vajudó asszony szíve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 23, 'Damaskus felől: Megszégyenült Emát és Arphád, mert gonosz hírt hallottak, és remegnek, mint a háborgó tenger, a mely nem nyughatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 24, 'Megrendült Damaskus, futáshoz készül és reszketés fogja el, szorongás és fájdalmak szállják meg őt, mint a szűlő asszonyt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 25, 'Miért is nem marad ki a dicsőséges város, az én örömömnek városa?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 26, 'De elhullanak az ő ifjai is az ő utczájokon, és minden harczoló ember levágatik azon a napon, azt mondja a Seregek Ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 27, 'És tüzet gyújtok Damaskus kőfalán, és megemészti a Ben-Hadád palotáit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 28, 'Kédárnak és Házornak országai felől, a melyeket megvert Nabukodonozor, a babiloni király, ezt mondja az Úr: Keljetek fel, menjetek fel Kédárra, és pusztítsátok keletnek fiait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 29, 'Sátoraikat és nyájokat elveszik, és kárpitjaikat és minden edényöket és tevéiket elviszik, és ezt kiáltják feléjök: Rettegés köröskörül!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 30, 'Fussatok el, igen siessetek, rejtőzzetek el mélyen, Házornak lakói, azt mondja az Úr, mert tervet tervezett ellenetek Nabukodonozor, a babiloni király, és ellenetek gondolatot gondolt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 31, 'Keljetek fel, menjetek a békességes nemzet közé, azok közé, a kik bátorságban lakoznak, azt mondja az Úr, sem kapujok, sem zárjok nincsen, egyedül laknak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 32, 'Tevéik prédává lesznek, és az ő sok barmaik zsákmánynyá, és elszórom őket, e nyirott üstökűeket minden szél felé, és minden oldal felől veszedelmet hozok reájok, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 33, 'És Házor sakálok lakhelyévé lesz, örökkévaló pusztasággá, senki nem lakik ott, és embernek fia nem is tartózkodik azon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 34, 'Az Úr szava, a melyet szóla Jeremiás prófétának Elám felől, Sedékiásnak, a Júda királyának országlása kezdetén, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 35, 'Ezt mondja a Seregek Ura: Ímé, én eltöröm az Elám kézívét, erejének zsengéjét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 36, 'És négy szelet hozok Elám ellen, az égnek négy határáról, és elszórom őket mindenik szél felé, és nem lesz nemzet, a kihez nem futnak az Elám szökevényei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 37, 'És megrettentem Elámot az ő ellenségei előtt és az ő lelköknek keresői előtt, és veszedelmet hozok reájok, az én felgerjedt haragomat, azt mondja az Úr, és utánok bocsátom a fegyvert mindaddig, míg meg nem emésztem őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 38, 'És az én székemet Elámba helyezem, és kivesztem onnét a királyt és a fejedelmeket, azt mondja az Úr:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 39, 'De végezetre visszahozom Elámot a fogságból, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 1, 'Az a szó, a melyet szóla az Úr Babilon felől és a Káldeusok földje felől, Jeremiás próféta által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 2, 'Hirdessétek a nemzetek között és hallassátok, emeljétek fel a zászlót: hallassátok és el ne titkoljátok; ezt mondjátok: Bevétetett Babilon, megszégyenült Bél, letöretett Merodák, megszégyenültek az ő faragott képei, letörettek az ő bálványai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 3, 'Mert északról nép jön fel ellene, pusztává teszi ez az ő földét, és nem lesz, a ki lakozzék benne; embertől fogva a baromig elfutnak, elmennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 4, 'Azokban a napokban, és abban az időben, azt mondja az Úr, eljőnek az Izráel fiai, ők és a Júda fiai együtt, sírva jönnek és mennek és keresik az Urat, az ő Istenöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 5, 'A Sion felől kérdezősködnek, arrafelé fordítják orczájokat. Eljőnek és oda adják magokat az Úrnak örök szövetségre, a mely feledhetetlen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 6, 'Elveszett juhnyáj volt az én népem, pásztorai félrevezették őket, a hegyekben bujdostatták őket, hegyről halomra jártak, elfelejtkeztek az ő tanyájukról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 7, 'A ki csak reájok talált, emésztette őket, és az ő elnyomóik ezt mondták: Nem vétkeztünk, mert vétettek az Úr ellen, pedig igazság otthona, atyáiknak reménysége volt az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 8, 'Fussatok ki Babilonból és jőjjetek ki Káldea földéből, és olyanok legyetek, mint a kecskebakok a nyáj előtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 9, 'Mert ímé, én nagy nemzetek gyülekezetét támasztom és hozom fel Babilonra északnak földéről, és sorakoznak ellene, legott bevétetik. Nyilai olyanok, mint a legyőzhetetlen vitézé, a ki nem tér vissza sikertelenül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 10, 'És Káldea prédává lesz, a kik prédára vetik őt, mind betelnek vele, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 11, 'Csak örüljetek, csak tomboljatok örökségem elpusztítói: csak ugrándozzatok, mint a nyomtató tinó, és nyerítsetek, mint a ménlovak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 12, 'Megszégyenül a ti anyátok, a ti szűlőtök igen csúffá lesz: Ímé, a nemzetek seprejévé, pusztává, szárazfölddé, sivataggá lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 13, 'Az Úr haragja miatt nem lakoznak rajta, hanem egészen pusztasággá lesz, a ki csak átmegy Babilonon, álmélkodik és sziszeget egész veresége felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 14, 'Sorakozzatok köröskörül Babilon ellen, mind ti ijjászok, lőjjetek reá, ne kiméljétek a nyilat; mert az Úr ellen vétkezett!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 15, 'Kiáltsatok reá köröskörül, kezét adta, lehullottak az ő szegletkövei, leromlottak az ő kőfalai: bizony az Úr büntetése ez; büntessétek meg őt, és a mint cselekedett, úgy cselekedjetek vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 16, 'Vágjátok ki Babilonból a magvetőt és a ki sarlót fog aratás idején; a gyilkos fegyver elől kiki az ő népéhez szalad, kiki az ő földe felé fut.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 17, 'Elszéledt juhnyáj az Izráel, oroszlánok kergették szét; először benyelte őt Assiria királya, végre pedig ez a Nabukodonozor, a babiloni király megtörte az ő csontjait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 18, 'Azért ezt mondja a Seregek Ura, az Izráel Istene: Ímé, én megfenyítem a babiloni királyt és az ő földét, miként megfenyítém az assiriai királyt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 19, 'És visszaviszem az Izráelt az ő lakhelyére, és Básánban legel és a Kármelen, és az Efraim hegyén és Gileádban megelégszik az ő lelke.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 20, 'Azokban a napokban és abban az időben, azt mondja az Úr, kerestetik az Izráel bűne, de nem lesz; a Júda vétkei, de nem találtatnak: mert kegyelmes leszek azokhoz, a kiket meghagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 21, 'A kétszer pártütők földére menj fel, és a meglátogattatás lakóit irtsd ki, öljed és irtsad őket, azt mondja az Úr, és mind a szerint cselekedjél, a mint parancsoltam néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 22, 'Harczi zaj a földön és nagy romlás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 23, 'Hogy elmúlott és összetört az egész föld pőrölye! milyen útálatossá lett Babilon a nemzetek között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 24, 'Tőrbe ejtettelek téged, és meg is fogattál Babilon, de nem tudtad, utól érettél és megragadtattál, mert pörlekedtél az Úrral.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 25, 'Felnyitotta az Úr az ő tárházát, és előhozta az ő haragjának szereit: mert e cselekedet az Úré, a Seregek Uráé Káldea földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 26, 'Törjetek reá a szélekről, nyissátok fel az ő magtárait, tapodjátok őt, mint a kévét, és irtsátok ki, hogy ne legyen maradéka.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 27, 'Döfjétek le minden tulkát, le velök a vágóhídra! Oh jaj nékik; mert eljött az ő napjok, az ő megfenyíttetésök ideje!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 28, 'A futók és a Babilon földéből menekülők zaja megjelentik majd a Sionon az Úrnak a mi Istenünknek bosszúállását, az ő templomáért való bosszúállását.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 29, 'Gyűjtsetek össze Babilon ellen igen sokat, mindenkit a ki kézívet feszít, köröskörül járjatok ellene tábort, hogy senki el ne szaladhasson: fizessetek meg néki az ő cselekedete szerint, a mint ő cselekedett, úgy cselekedjetek vele; mert az Úr ellen kevélykedett, az Izráelnek Szentje ellen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 30, 'Azért elhullanak az ő ifjai az ő utczáiban, és minden vitéze elvész azon a napon, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 31, 'Ímé, én ellened vagyok, te kevély, azt mondja az Úr, a Seregek Ura, mert eljött a te napod, a te megfenyítésed napja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 32, 'És megbotlik a kevély és elesik, és senki nem lesz, a ki felköltse őt, és tüzet gyújtok az ő városaiban, hogy megemészsze azokat, a kik körülte vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 33, 'Ezt mondja a Seregek Ura: Megnyomoríttattak az Izráel fiai és Júda fiai együtt és mindnyájan, a kik fogságra vitték őket, beléjök ragadnak, nem akarják őket elbocsátani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 34, 'De az ő megváltójok erős, Seregek Ura az ő neve, bizonynyal felveszi az ő peröket, hogy megnyugtassa e földet, és Babilon lakóit megrettentse.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 35, 'Fegyver lesz a Káldeusokon, azt mondja az Úr, és Babilon lakóin és az ő fejedelmein és az ő bölcsein.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 36, 'Fegyver lesz az ő varázslóin, és megbolondulnak; fegyver lesz az ő vitézein, és elijednek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 37, 'Fegyver lesz az ő lovain és szekerein és az egész egyveleg népen, a mely ő benne van, és hasonlók lesznek az asszonyokhoz. Fegyver lesz az ő kincsein, és elprédáltatnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 38, 'Szárazság lesz az ő vizein, és kiszáradnak, mert bálványok földe az, és faragott képekkel dicsekednek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 39, 'Azért sakálok lakoznak ott baglyokkal, és struczmadárnak fiai lakoznak benne, és soha többé nem lakják azt, és nem lesznek lakosai nemzedékről nemzedékre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 40, 'A mint felforgatta Isten Sodomát és Gomorát és az ő szomszéd városait, azt mondja az Úr, ép úgy nem lakik ott egy ember sem, és embernek fia sem lakja azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 41, 'Ímé, nép jött északról, és nagy nemzet és sok király támad fel a föld határaiból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 42, 'Ívet és paizst ragadnak, kegyetlenek azok, és semmi irgalmasság nem lesz bennök, szavok mint a tenger zúgása, és lovakon jőnek, mind viadalra készek te ellened, te Babilon leánya!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 43, 'Hallja a babiloni király az ő híröket, és kezei elesnek, szorongás fogja el őt, fájdalom, mint a gyermekszűlőt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 44, 'Ímé, mint a Jordán erdőségéből való oroszlán, úgy jön fel az örökzöld ligetre, de hamar kiűzöm őt arról, és a ki arra választatott, azt teszem azon fejedelemmé, mert kicsoda hasonlatos hozzám? és ki szab nékem törvényt, és ki az a pásztor, a ki ellenem álljon?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 45, 'Azért halljátok meg az Úr tervét, a melyet Babilon ellen tervezett, és az ő gondolatait, a melyeket Káldea ellen gondolt. Bizony elhajtják őket, a nyáj kicsinyeit, és álmélkodik felettök a legelő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 46, 'Babilon bevételének zajától megindul a föld, és kiáltása hallatszik a nemzetek között!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 1, 'Ezt mondja az Úr: Ímé, én pusztító szelet támasztok Babilon ellen és azok ellen, a kik az én ellenségem szívében lakoznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 2, 'És szórókat küldök Babilon ellen, és felszórják őt, és földét kiüresítik, mert mindenfelől ellene lesznek a veszedelem napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 3, 'A kézívesre kézíves vonja fel íjját, és arra, a ki pánczéljába öltözik. Ne kedvezzetek ifjainak, öldössétek le egész seregét:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 4, 'És essenek el megöletve a Káldeusok földén, és átverve az ő utczáin.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 5, 'Mert nem hagyatott el Izráel és Júda az ő Istenétől, a Seregek Urától, noha az ő földök rakva vétekkel az Izráelnek Szentje ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 6, 'Fussatok ki Babilonból, és kiki mentse meg az ő lelkét, ne veszszetek el az ő gonoszságáért, mert az Úr bosszúállásának ideje ez, megfizet néki érdem szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 7, 'Arany pohár volt Babilon az Úr kezében, a mely megrészegíté ez egész földet; nemzetek ittak az ő borából, azért bolondultak meg a nemzetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 8, 'Hamar elesett Babilon és összeomlott, jajgassatok felette, kössétek be balzsammal az ő sebét, hátha meggyógyul!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 9, 'Gyógyítottuk Babilont, de nem gyógyult meg. Hagyjátok el őt, és menjünk kiki a maga földére, mert az égig hatott az ő ítélete, és felemelkedett a felhőkig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 10, 'Kihozta az Úr a mi igazságainkat, jertek és beszéljük meg Sionban az Úrnak, a mi Istenünknek dolgát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 11, 'Élesítsétek a nyilakat, töltsétek meg a tegzeket; felindította az Úr a Médiabeli királyok lelkét, mert Babilon ellen van az ő gondolatja, hogy elveszesse azt, mert az Úr bosszúállása ez, az ő templomáért való bosszúállása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 12, 'Babilonnak kőfalain tűzzétek ki a zászlót, erősítsétek meg az őrséget, szerezzetek vigyázókat, rendeljétek el a leseket: mert az Úr meggondolta és meg is cselekszi azokat, a miket szólott Babilon lakói ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 13, 'Oh te, a ki lakozol a nagy vizek mellett, a kinek kincsed temérdek, eljött a te véged és a te rablásod határa!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 14, 'Megesküdt a Seregek Ura az ő lelkére, mondván: Bizony betöltelek téged emberekkel, mint sáskákkal, és diadalmas éneket énekelnek felőled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 15, 'Az, a ki teremtette a földet az ő erejével, a ki megalapította a világot az ő bölcsességével, és kiterjesztette az egeket az ő értelmével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 16, 'Egy szavával vizek zúgását szerez az égben, és felhőket visz fel a föld határairól, villámokat készít az esőhöz, és kihozza a szelet az ő tárházaiból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 17, 'Minden ember bolonddá lett tudomány nélkül, minden ötvös megszégyenül a maga bálványa miatt, mert hazugság az ő öntése és nincs benne lélek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 18, 'Hiábavalóságok ezek, nevetségre való művek, az ő megfenyíttetésök idején elvesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 19, 'Nem ilyen a Jákób osztályrésze mert mindennek teremtője és az ő örökségének pálczája, Seregek Ura az ő neve!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 20, 'Pőrölyöm vagy te nékem, hadi fegyverem, és nemzeteket zúztam össze veled, és országokat vesztettem el veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 21, 'És általad zúztam össze a lovakat és lovagjaikat, és általad zúztam össze a szekeret és a benne ülőt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 22, 'És összezúztam általad férfit és asszonyt, és összezúztam általad a vénet és a gyermeket, és összezúztam általad az ifjat és a szűzet,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 23, 'És összezúztam általad a pásztort és nyáját, és összezúztam általad a szántóvetőt és az ő igamarháját, és összezúztam általad a hadnagyokat és a főembereket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 24, 'És megfizetek Babilonnak és Káldea minden lakosának mindazokért az ő gonoszságaikért, a melyeket Sionban cselekedtek a ti szemeitek láttára, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 25, 'Ímé, én ellened fordulok, te romlásnak hegye, azt mondja az Úr, a ki az egész földet megrontottad, és kinyújtom reád kezemet, és levetlek téged a kőszikláról, és kiégett hegygyé teszlek téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 26, 'És belőled nem visznek követ a szegletre és a fundamentomra, mert örökkévaló pusztaság leszel, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 27, 'Tűzzétek ki a zászlót az országban, fújjátok meg a trombitát a nemzetek között, avassátok fel ellene a nemzeteket, gyűjtsétek össze ellene az Ararátnak, Menninek és Askenáznak országait, válaszszatok ő ellene hadvezért, hozzátok ki a lovakat mint rettenetes sáskasereget.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 28, 'Avassátok fel ellene a nemzeteket, Médiának királyait, az ő hadnagyait és minden főemberét, és az ő birodalmának egész földét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 29, 'És megrendül a föld és rázkódik, mert az Úrnak gondolatai beteljesednek Babilon ellen, hogy Babilon földét pusztasággá, lakatlanná tegye.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 30, 'Babilon vitézei felhagytak a viadallal, erősségeikben ülnek, elfogyott a vitézségök, asszonyokká lettek, felgyújtották lakhelyeit, zárait letörték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 31, 'Futár futár elé fut, és hírmondó a hírmondó elé, hogy megjelentse a babiloni királynak, hogy bevétetett az ő városa mindenfelülről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 32, 'És a révhelyek elfoglaltattak, és az álló tavak tűzzel kiszáríttattak, és a vitézek elrettentek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 33, 'Mert ezt mondja a seregek Ura, az Izráel Istene: Babilon leánya olyan, mint a szérű, itt van az ő tapostatásának ideje, egy kis híja még, és eljő az ő aratásának ideje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 34, 'Benyelt engem, megemésztett engem Nabukodonozor, a babiloni király, üres edénynyé tett engem, benyelt engem mint a sárkány, betöltötte a hasát az én csemegéimmel, és kivetett engemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 35, 'Az én rajtam esett erőszak és az én testem Babilonra térjen, azt mondja a Sionnak lakója, és az én vérem Káldeának lakosaira, azt mondja Jeruzsálem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 36, 'Azért ezt mondja az Úr: Ímé, én megítélem a te ügyedet, és bosszút állok éretted, és kiszáraztom az ő tengerét, és kiapasztom az ő forrását.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 37, 'És Babilon kőrakássá lesz, sárkányok lakhelyévé, csudává, csúfsággá és lakatlanná lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 38, 'Együtt ordítanak, mint az oroszlánok, harsognak, mint az oroszlánkölykök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 39, 'Az ő kedvöknek idején készítek nékik lakomát, és megrészegítem őket, hogy vígadjanak, és örökkévaló álmot aludjanak, és fel ne serkenjenek, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 40, 'Előhozom őket, mint a bárányokat a megmetszésre, mint a kosokat a bakokkal egyetemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 41, 'Mint bevétetett Sésák, és elfoglaltatott az egész földnek dicséreti! Milyen útálattá lett Babilon a nemzetek között!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 42, 'Feljött Babilonra a tenger, habjainak özönével elboríttatott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 43, 'Városai pusztává, sivataggá és kopár földdé lesznek, a melyen senki sem lakik, sem embernek fia át nem megy rajta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 44, 'Megfenyítem Bélt is Babilonban, és kivonom szájából, a mit benyelt, és többé nem futnak hozzá a nemzetek, Babilonnak kőfala is ledől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 45, 'Jőjjetek ki belőle, oh én népem, és kiki szabadítsa meg lelkét az Úr haragjának tüzétől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 46, 'És el ne olvadjon a ti szívetek és ne féljetek a hírtől, a mely hallatszik e földön, mikor egyik esztendőben hír jő, és a másik esztendőben is a hír, hogy erőszakosság van a földön, uralkodó tör uralkodóra!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 47, 'Azért ímé, eljőnek a napok, és meglátogatom Babilon faragott képeit, és egész földe megszégyenül, és minden ő megöltjei elhullanak ő közötte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 48, 'És örvendeznek Babilon felett az ég és a föld és minden benne valók, mert észak felől eljőnek reá a pusztítók, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 49, 'Babilon is elesik, Izráel megölöttjei, a mint Babilonban is elhullottak az egész föld megölöttjei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 50, 'Menjetek el, a kik megszabadultatok a fegyvertől, meg ne álljatok; emlékezzetek meg a távolból az Úrról, és jusson eszetekbe Jeruzsálem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 51, 'Megszégyenültünk, mert hallottuk a gyalázkodást, orczáinkat szégyen borította, mert idegenek jöttek az Úr házának szentségébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 52, 'Azért ímé, eljőnek a napok, azt mondja az Úr, és meglátogatom az ő faragott képeit, és egész földén sebesültek nyögnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 53, 'Ha az égbe hág is fel Babilon, és ha megerősíti is az ő erős magaslatát, pusztítók törnek reá tőlem, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 54, 'Kiáltás hallatszik Babilonból, és a Káldeusok földéből nagy romlás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 55, 'Mert elpusztítja az Úr Babilont, és kiveszíti belőle a nagy zajt, és zúgnak az ő habjai, mint a nagy vizek, hallatszik az ő szavok harsogása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 56, 'Mert pusztító tör reá, Babilonra, és elfogatnak vitézei, eltörik az ő kézívök, mert a megfizetésnek Istene, az Úr, bizonynyal megfizet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 57, 'És megrészegítem az ő fejedelmeit, bölcseit, hadnagyait, tiszttartóit és vitézeit, és örök álmot alusznak, és nem serkennek fel, azt mondja a király, a kinek neve Seregek Ura!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 58, 'Ezt mondja a Seregek Ura: Babilon széles kőfala földig lerontatik, és az ő büszke kapuit tűz égeti meg, és a népek hiába munkálkodnak, és a nemzetek a tűznek, és kifáradnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 59, 'Ez a szó, a melylyel Jeremiás próféta utasította Seráját, Néria fiát, a ki a Mahásiás fia volt, mikor ő Babilonba méne Sedékiással, a Júda királyával, királyságának negyedik esztendejében; Serája pedig szállásmester vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 60, 'És megírá Jeremiás egy könyvben mindazt a veszedelmet, a mely Babilont fogja érni, mindezeket a beszédeket, a melyek megirattak Babilon felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 61, 'És monda Jeremiás Serájának: Mikor Babilonba jutsz, és látod és elolvasod mind e szókat,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 62, 'Ezt mondjad: Uram, te szólottál e hely ellen, hogy elveszítsed ezt annyira, hogy lakó ne legyen benne embertől baromig, hanem örökkévaló pusztaság legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 63, 'És mikor e könyv olvasását elvégzed, köss reá követ, és hajítsd be az Eufrátes közepébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 64, 'És ezt mondd: Így merül el Babilon, és meg nem menekedik a veszedelemtől, a melyet én hozok reá, akármint fáradjanak. Eddig vannak a Jeremiás beszédei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 1, 'Huszonegy esztendős volt Sedékiás, mikor uralkodni kezde, és tizenegy esztendeig uralkodék Jeruzsálemben, és az ő anyjának neve Hammutál vala, a Libnából való Jeremiás leánya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 2, 'És gonoszt cselekedék az Úr szemei előtt, mint Jojákim cselekedett vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 3, 'Mert az Úr haragjáért vala ez Jeruzsálemen és Júdán, míglen elveté őket színe elől. Sedékiás ugyanis engedetlen lőn a babiloni királynak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 4, 'És az ő uralkodásának kilenczedik esztendejében, a tizedik hónapban, a hónapnak tizedikén eljöve Nabukodonozor, a babiloni király, ő maga és egész serege Jeruzsálemre, és tábort járának ellene, és mindenfelől sánczot vetének fel ellene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 5, 'És megszállva lőn a város Sedékiásnak tizenegyedik esztendejéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 6, 'A negyedik hónapban, a hónapnak kilenczedikén nagy éhség támada a városban, annyira, hogy a föld népének kenyere sem vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 7, 'És bevéteték a város, és a harczosok mind elfutának, és éjszaka kimenének a városból a kapu felé, a két kőfal között, a melyek a király kertjénél valának (a Káldeusok pedig a város mellett valának köröskörül) és menének az úton, a mely sík földre viszen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 8, 'A Káldeusok serege pedig űzé a királyt, és utólérék Sedékiást a jerikói síkon, mert egész serege elfuta mellőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 9, 'Megfogák azért a királyt, és vivék őt a babiloni királyhoz Riblába, a Hamát földére, a ki törvényt monda reá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 10, 'És leöleté a babiloni király a Sedékiás fiait szemei láttára, és Júda minden fejedelmét is leöleté Riblában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 11, 'Sedékiás királynak pedig szemeit tolatá ki, és lánczra vereté és viteté őt a babiloni király Babilonba, és tömlöczbe veté őt halála napjáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 12, 'Az ötödik hónapban pedig, a hónapnak tizedikén (ez az esztendő pedig a tizenkilenczedik esztendeje vala Nabukodonozornak, a babiloni királynak) Nabuzáradán, a vitézek feje, a ki áll vala a babiloni király előtt, eljöve Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 13, 'És felégeté az Úr házát és a király házát, és Jeruzsálemnek minden házait és minden nagy házat felégete tűzzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 14, 'És Jeruzsálem egész kőfalát köröskörül lerontá a Káldeusok mindenféle serege, a kik a vitézek fejével valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 15, 'A községnek szegényeiből pedig és a többi nép közül, a kik a városban megmaradtak vala, és a szökevények közül, a kik elszöktek vala a babiloni királyhoz, és a sokaságnak maradékából foglyokat vive Nabuzáradán, a vitézek feje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 16, 'De a föld szegényei közül ott hagyá Nabuzáradán, a vitézek feje, a szőlőműveseket és szántóvetőket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 17, 'A rézoszlopokat pedig, a melyek az Úr házában valának és a talpakat és a réztengert, a mely az Úr házában vala, összetörék a Káldeusok, és azoknak minden rezét elvivék Babilonba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 18, 'A fazekakat is és a lapátokat, a késeket és a medenczéket, a tömjénezőket és a rézedényeket, a melyekkel szolgálnak vala, mind elvivék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 19, 'És a csészéket, a serpenyőket, a medenczéket és a fazekakat, a gyertyatartókat, a tömjénezőket és a serlegeket, a mi arany, aranyban, a mi ezüst, ezüstben, mind elvivé a vitézek feje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 20, 'Két oszlop, egy réztenger és tizenkét rézökör vala, a melyek a talpak alatt valának, a melyeket Salamon király csináltatott vala az Úr házába. Mindezeknek az edényeknek reze megmérhetetlen vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 21, 'És az oszlopok közül az egyik oszlopnak tizennyolcz sing vala a magassága, és tizenkét sing zsinór éri vala át köröskörül, vastagsága pedig négy ujjnyi, és belől üres vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 22, 'Rézgömb vala rajta, és az egyik gömb magassága öt singnyi vala, és a hálók és gránátalmák a gömbön köröskörül mind rézből valának, és ilyen a második oszlop, és ilyenek a gránátalmák is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 23, 'A gránátalma pedig kilenczvenhat vala kifelé, összesen száz gránátalma vala a hálón felül köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 24, 'Elvivé a vitézek feje Seráját is, a főpapot, és Sofóniást a második papot, és az ajtónak három őrizőjét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 25, 'És a városból elvive egy főembert, a ki felügyelőjök vala a harczosoknak, és hetet ama férfiak közül, a kik állanak vala a király előtt, a kik a városban találtatának, és a seregek főíródeákját, a ki a föld népét besorozta vala, és hatvan férfiút a föld népe közül, a kik a városban találtatának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 26, 'És felvevé ezeket Nabuzáradán, a vitézek feje, és elvivé őket a babiloni királyhoz Riblába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 27, 'És levágatá őket a babiloni király és megöleté őket Riblában, a Hamát földén, és fogságra viteték Júda az ő földéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 28, 'Ennyi az a nép, a melyet fogságra vitete Nabukodonozor a hetedik esztendőben, háromezer és huszonhárom Júdabeli.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 29, 'A Nabukodonozor tizennyolczadik esztendejében Jeruzsálemből nyolczszáz és harminczkét lélek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 30, 'Nabukodonozor huszonharmadik esztendejében fogságba vitete Nabuzáradán, a vitézek feje hétszáznegyvenöt Júdabelit. Összesen négyezer és hatszáz lélek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 31, 'Lőn pedig Jojákin júdabeli király fogságának harminczhetedik esztendejében, a tizenkettedik hónapban, a hónak huszonötödikén, felemelé Evil-Merodák, a babiloni király az ő uralkodásának első esztendejében Jojákinnak, a Júda királyának fejét, és kivevé őt a tömlöczből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 32, 'És szépen szóla vele, és királyi székét ama királyoknak széke fölé emelte, a kik vele valának Babilonban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 33, 'És felcserélé tömlöczbeli ruháit, és mindenkor vele eszik vala ételt, életének minden napjában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 34, 'És költségére állandó költség adatik vala néki a babiloni királytól minden napra, a halála napjáig, életének minden napjában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'Jaj! de árván ül a nagy népű város! Olyanná lőn, mint az özvegyasszony! Nagy volt a nemzetek között, a tartományok közt fejedelemasszony: robotossá lőn!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, 'Sírván sír éjjelente, s könny borítja az orczáját! Senki sincs, ki vígasztalná, azok közül, kik szerették; mind megcsalták barátai, ellenségeivé lőnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'Számkivetésbe méne Júda a nyomorúság és a szolgálat sokasága miatt! Ott ül ő a pogányok közt; nem talál nyugodalmat; valamennyi üldözője utólérte a szorultságában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'Sionnak útai gyászolnak; nincsen, a ki ünnepnapra járjon; kapuja mind elpusztult; papjai sóhajtoznak, szűzei nyögnek, csak keserűsége van néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'Elnyomói főkké lettek; ellenségei boldogok! Bizony az Úr verte meg őt az ő sok bűne miatt; gyermekei rabságra mentek az elnyomó előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'És elhagyta Sion leányát minden ő ékessége; fejedelmei olyanok lettek, mint a szarvasok, a melyek nem találnak eledelt, és erőtelenül futnak az üldöző előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, 'Emlékezik Jeruzsálem az ő nyomorúságának és eltiportatásának napjain minden ő gyönyörűségéről, a melyek voltak eleitől fogva; mert az ő népe ellenség kezébe esett és nem volt segítsége. Látták őt az ellenségek; nevettek megsemmisülésén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, 'Vétkezvén vétkezett Jeruzsálem, azért lett csúfsággá, minden tisztelője megvetette, mert látták az ő mezítelenségét, ő maga pedig sóhajtoz és elfordul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, 'Szennye a ruhája szélén; nem gondolt a jövőjére; csudálatosan alásülyedt, nincs vígasztalója. Lásd meg Uram, az én nyomorúságomat, mert ellenség vett erőt rajtam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, 'Szorongató nyújtja kezét minden kincse után, sőt látta, hogy pogányok mentek be az ő szent helyébe, a kikről azt parancsoltad, hogy be ne menjenek a te községedbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, 'Egész népe sóhajtoz, futkosnak a kenyér után, odaadják drágaságaikat az ételért, hogy megéledjenek. Lásd meg Uram és tekintsd meg, mily útálatossá lettem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, 'Mindnyájatokat kérlek, ti járókelők: tekintsétek meg és lássátok meg, ha van-é oly bánat, mint az én bánatom, a mely engem ért, a melylyel engem sujtott az Úr az ő búsult haragjának napján!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, 'A magasságból tüzet bocsátott csontjaimba, és az hatalmaskodik bennök; hálót vetett lábaimnak; hátra vetett, pusztává tett engem; egész napon beteg vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, 'Saját kezével rótta össze az én vétkeim igáját; ráfonódtak nyakamra; megrendítette erőmet; oda adott engem az Úr azok kezébe, a kik előtt meg nem állhatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, 'Rakásra hányta az Úr minden vitézemet én bennem; gyűlést hívott össze ellenem, hogy összetörje ifjaimat; sajtóba taposta az Úr Júda szűz leányát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, 'Ezekért sírok én; szememből, szememből víz folyik alá, mert messze távozott tőlem a vígasztaló, a ki megélesszen engem; fiaim elvesztek, mert győzött az ellenség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 17, 'Terjesztgeti kezeit Sion: nincs vígasztalója; szorongatókat rendelt az Úr Jákób ellen köröskörül; Jeruzsálem csúfsággá lett közöttök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 18, 'Igaz ő, az Úr, mert az ő szava ellen rugódoztam! Halljátok meg kérlek, mind ti népek, és lássátok meg az én bánatomat: szűzeim és ifjaim fogságba menének!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 19, 'Kiáltottam azoknak, a kik szerettek engem de ők megcsaltak engem; papjaim és véneim a városban multak ki, a mikor étel után futkostak, hogy megéledjenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 20, 'Lásd meg Uram, hogy szorongattatom, belső részeim megháborodtak; elfordult bennem az én szívem, mert bizony pártot ütöttem; künn fegyver pusztít, benn minden olyan, mint a halál!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 21, 'Hallották, hogy sóhajtozom és nincs vígasztalóm; minden ellenségem hallotta veszedelmemet; örültek, hogy te ezt cselekedted. Hozd el a napot, a melyet hirdettél, hogy olyanok legyenek, mint én!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 22, 'Jusson elődbe minden gonoszságuk, és úgy bánj velök, a miképen én velem bántál az én minden bűnömért; mert sok az én sóhajtozásom, és beteg a szívem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'Jaj; de sűrű felhőt borított haragjában az Úr Sionnak leányára! az égből a földre veté Izráel ékességét, és nem emlékezett meg lábainak zsámolyáról az ő haragja napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, 'Elnyelte az Úr, nem kimélte Jákóbnak minden hajlékát, letörte haragjában Júda leányának erősségeit, a földre terítette; megfertőzteté az országot és fejedelmeit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, 'Felgerjedt haragjában letördelé Izráelnek minden szarvát; hátravoná jobbkezét az ellenség elől, Jákób ellen pedig mint lángoló tűz emésztett köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, 'Feszítette kézívét, mint valami ellenség, kinyújtá jobbkezét, mint támadó, és megölt mindent, a mi a szemnek kivánatos; Sion leányának sátorában, mint a tüzet önté ki búsulását.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, 'Olyan volt az Úr, mint valami ellenség; elnyelte Izráelt, elnyelte minden palotáját, elrontá erősségeit, és megsokasította Júda leányának a búját, baját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, 'És eltapodta sátorát, mint valami kertet, lerombolta gyülekezése helyét; elfeledtete az Úr a Sionon ünnepet és szombatot, és megútált haragja hevében királyt és papot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, 'Megvetette az Úr az ő oltárát, megútálta szent helyét; ellenség kezébe adá palotáinak kőfalait; zajt ütöttek az Úr házában, mint ünnepnapon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'Gondolá az Úr, hogy lerontja Sion leányának kőfalát; kiterjeszté a mérőkötelet, nem vonta vissza kezét a pusztítástól, és siralomra jutott a bástya és a kőfal, együtt búslakodnak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'Kapui besülyedtek a földbe, elveszté és összetöré annak zárait; királya és fejedelmei a pogányok közt vannak. Nincsen törvény, sőt prófétái sem nyernek kijelentést az Úrtól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'A földön ülnek, elnémultak Sion leányának vénei, port szórtak a fejökre; zsákba öltöztek, földre csüggesztették fejöket Jeruzsálemnek szűzei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'Elsenyvedtek szemeim a könyhullatástól, belső részeim háborognak, májam a földre omlik az én népem leányának romlása miatt, mikor elalélt a kis gyermek és a csecsszopó a város utczáin.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'Azt mondták anyjoknak: Hol a kenyér, meg a bor? mikor elaléltak, mint a sebesültek a város utczáin, mikor kilehelték lelköket anyjoknak kebelén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, 'Mivel bizonyítsak melletted, mihez hasonlítsalak, Jeruzsálem leánya, mivel mérjelek össze téged, hogy megvígasztaljalak, Sionnak szűz leánya?! Bizony nagy a te romlásod, mint a tenger: kicsoda gyógyít meg téged?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, 'A te prófétáid hazugságot és bolondságot hirdettek néked, és nem fedték fel a te álnokságodat, hogy elfordították volna fogságodat; hanem láttak tenéked hazug és megtévelyítő prófétálásokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, 'Összecsapják feletted kezöket minden járó-kelők; süvöltenek és csóválják fejöket Jeruzsálem leánya felett: Ez-é az a város, a melyről azt mondták: tökéletes szépség, az egész földnek öröme?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, 'Feltátották ellened szájokat minden ellenségeid; süvöltenek és csikorgatják fogukat, mondván: Nyeljük el őt! Bizony ez a nap az, a melyet vártunk; megértük, látjuk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, 'Megcselekedte az Úr, a miket gondolt; beváltotta szavát, a melyet szólt eleitől fogva; rombolt és nem kimélt, és megvidámította rajtad az ellenséget, felemelte szarvát a te szorongatóidnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, 'Kiáltott az ő szívök az Úrhoz: Oh Sion leányának kőfala! Folyjon alá könnyed mint a patak, éjjel és nappal; ne szakadjon félbe, síró szemed meg se pihenjen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, 'Kelj fel, riadj éjjel, az őrjárások kezdetén; öntsd ki, mint a vizet a te szívedet az Úr szine előtt; emeld fel hozzá kezeidet a te kisdedeidnek életéért, a kik elaléltak az éhség miatt minden utczának szegletén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, 'Lásd meg Uram és tekintsd meg, kivel cselekedtél így! Avagy megegyék-é az asszonyok az ő méhöknek gyümölcsét, dédelgetett kisdedeiket; avagy megölettessék-é az Úrnak szent helyén pap és próféta?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, 'Az utczákon a földön fekszik gyermek és vén; szűzeim és ifjaim fegyver miatt hullottak el; öldököltél haragod napján, mészároltál, nem kiméltél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, 'Egybehívtad mint valami ünnepnapra az én rettegtetőimet mindenfelől, és nem volt az Úr haragjának napján, a ki elmenekült és megszabadult volna. A kiket dédelgettem és felneveltem, ellenségem emésztette meg őket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, 'Én vagyok az az ember, a ki nyomorúságot látott az ő haragjának vesszeje miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'Engem vezérlett és járatott sötétségben és nem világosságban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'Bizony ellenem fordult, ellenem fordítja kezét minden nap.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'Megfonnyasztotta testemet és bőrömet, összeroncsolta csontjaimat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'Erősséget épített ellenem és körülvett méreggel és fáradsággal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'Sötét helyekre ültetett engem, mint az örökre meghaltakat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, 'Körülkerített, hogy ki ne mehessek, nehézzé tette lánczomat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, 'Sőt ha kiáltok és segítségül hívom is, nem hallja meg imádságomat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, 'Elkerítette az én útaimat terméskővel, ösvényeimet elforgatta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, 'Ólálkodó medve ő nékem és lesben álló oroszlán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, 'Útaimat elterelte, és darabokra vagdalt és elpusztított engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, 'Kifeszítette kézívét, és a nyíl elé czélul állított engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, 'Veséimbe bocsátotta tegzének fiait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, 'Egész népemnek csúfjává lettem, és gúnydalukká napestig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, 'Eltöltött engem keserűséggel, megrészegített engem ürömmel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, 'És kova-kővel tördelte ki fogaimat; porba tiprott engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, 'És kizártad lelkem a békességből; elfeledkeztem a jóról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, 'És mondám: Elveszett az én erőm és az én reménységem az Úrban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, 'Emlékezzél meg az én nyomorúságomról és eltapodtatásomról, az ürömről és a méregről!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 20, 'Vissza-visszaemlékezik, és megalázódik bennem az én lelkem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 21, 'Ezt veszem szívemre, azért bízom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, 'Az Úr kegyelmessége az, hogy még nincsen végünk; mivel nem fogyatkozik el az ő irgalmassága!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 23, 'Minden reggel meg-megújul; nagy a te hűséged!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 24, 'Az Úr az én örökségem, mondja az én lelkem, azért benne bízom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 25, 'Jó az Úr azoknak, a kik várják őt; a léleknek, a mely keresi őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 26, 'Jó várni és megadással lenni az Úr szabadításáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 27, 'Jó a férfiúnak, ha igát visel ifjúságában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 28, 'Egyedül ül és hallgat, mert felvette magára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 29, 'Porba teszi száját, mondván: Talán van még reménység?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 30, 'Orczáját tartja az őt verőnek, megelégszik gyalázattal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 31, 'Mert nem zár ki örökre az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 32, 'Sőt, ha megszomorít, meg is vígasztal az ő kegyelmességének gazdagsága szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 33, 'Mert nem szíve szerint veri és szomorítja meg az embernek fiát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 34, 'Hogy lábai alá tiporja valaki a föld minden foglyát;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 35, 'Hogy elfordíttassék az ember ítélete a Magasságosnak színe előtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 36, 'Hogy elnyomassék az ember az ő peres dolgában: ezt az Úr nem nézi el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 37, 'Kicsoda az, a ki szól és meglesz, ha nem parancsolja az Úr?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 38, 'A Magasságosnak szájából nem jő ki a gonosz és a jó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 39, 'Mit zúgolódik az élő ember? Ki-ki a maga bűneiért bűnhődik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 40, 'Tudakozzuk a mi útainkat és vizsgáljuk meg, és térjünk az Úrhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 41, 'Emeljük fel szíveinket kezeinkkel egyetemben Istenhez az égben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 42, 'Mi voltunk gonoszok és pártütők, azért nem bocsátottál meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 43, 'Felöltötted a haragot és üldöztél minket, öldököltél, nem kiméltél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 44, 'Felöltötted a felhőt, hogy hozzád ne jusson az imádság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 45, 'Sepredékké és útálattá tettél minket a népek között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 46, 'Feltátotta száját ellenünk minden ellenségünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 47, 'Rettegés és tőr van mi rajtunk, pusztulás és romlás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 48, 'Víz-patakok folynak alá az én szememből népem leányának romlása miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 49, 'Szemem csörgedez és nem szünik meg, nincs pihenése,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 50, 'Míg ránk nem tekint és meg nem lát az Úr az égből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 51, 'Szemem bánatba ejté lelkemet városomnak minden leányáért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 52, 'Vadászva vadásztak reám, mint valami madárra, ellenségeim ok nélkül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 53, 'Veremben fojtották meg életemet, és követ hánytak rám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 54, 'Felüláradtak a vizek az én fejem felett; mondám: Kivágattam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 55, 'Segítségül hívtam a te nevedet, oh Uram, a legalsó veremből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 56, 'Hallottad az én szómat; ne rejtsd el füledet sóhajtásom és kiáltásom elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 57, 'Közelegj hozzám, mikor segítségül hívlak téged; mondd: Ne félj!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 58, 'Pereld meg Uram lelkemnek perét; váltsd meg életemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 59, 'Láttad, oh Uram, az én bántalmaztatásomat; ítéld meg ügyemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 60, 'Láttad minden bosszúállásukat, minden ellenem való gondolatjokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 61, 'Hallottad Uram az ő szidalmazásukat, minden ellenem való gondolatjokat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 62, 'Az ellenem támadóknak ajkait, és ellenem való mindennapi szándékukat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 63, 'Tekintsd meg leülésöket és felkelésöket; én vagyok az ő gúnydaluk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 64, 'Fizess meg nékik, Uram, az ő kezeiknek munkája szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 65, 'Adj nékik szívbeli konokságot; átkodul reájok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 66, 'Üldözd haragodban, és veszesd el őket az Úr ege alól!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, 'Jaj! de meghomályosodott az arany, elváltozott a szép színarany, kiszórattak a szent hely kövei minden utcza szegletére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'Sionnak drága fiait, a kik becsesebbek valának mint a színarany, cserépedénynek tekintették, a fazekas munkájának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, 'Még a sárkányok is oda nyujtják emlőiket, szoptatják fiaikat; az én népem leánya pedig kegyetlen, mint a struczmadarak a pusztában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, 'A csecsemő nyelve az ínyéhez tapadt a szomjúság miatt; a kisdedek kenyeret kértek, és nem volt, a ki nyujtott volna nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, 'Kik pompás ételeket evének, elpusztulának az utczákon; a kik bíborban neveltetének, a szemétdombot ölelgetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, 'Bizony nagyobb az én népem leányának bűnhődése Sodoma bűnhődésénél, a mely elsülyedt egy pillanat alatt, noha kézzel sem ütöttek felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'Az ő názireusai tisztábbak valának a hónál, fehérebbek a tejnél, testök pirosabb vala, mint a korál, termetök mint a zafir.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'De most feketébb az ő ábrázatjok a koromnál, nem ismerik meg őket az utczákon; bőrük csontjaikhoz ragadt, elszáradt, mint a fa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, 'Jobban jártak, a kik fegyverrel ölettek meg, mint a kik éhen vesztek el; mert azok átveretve multak ki, ezek pedig a mező termésének hiánya miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, 'Irgalmas anyák kezei megfőzték gyermekeiket, hogy azok eledeleik legyenek az én népem leányának romlásakor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, 'Megteljesíté az Úr az ő búsulását, kiöntötte az ő felgerjedt haragját, és tüzet gyújtott a Sionban, és megemésztette annak fundamentomait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, 'Nem hitték a föld királyai, sem a föld kerekségének lakosai, hogy szorongató és ellenség vonuljon be Jeruzsálemnek kapuin.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, 'Az ő prófétáinak bűne, az ő papjainak vétke miatt van ez, a kik az igazaknak vérét ontották abban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, 'Tántorogtak, mint vakok az utczákon, vérrel bemocskolva, annyira, hogy ruháikat sem érinthették.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, 'Távozzatok! tisztátalan! kiáltották azoknak; távozzatok, távozzatok, ne illessetek! Bizony elfutottak, bujdostak is; a pogányok közt ezt mondták: Nem lakhatnak itt sokáig!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, 'Az Úr haragja oszlatta el őket; többé nem tekint reájok, mivelhogy a papok orczáját nem tisztelték, a véneken nem könyörültek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, 'Még mikor meg voltunk, elepedve néztek szemeink a hiábavaló segedelem után; esengve várakoztunk olyan népre, a mely nem szabadított meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 18, 'Vadásztak lépéseinkre úgy, hogy nem járhattunk a mi utczáinkon; elközelgetett a mi végünk, beteltek a mi napjaink, bizony eljött a mi végünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 19, 'Gyorsabbak valának a mi üldözőink az égnek saskeselyűinél; a hegyeken kergettek minket, a pusztában ólálkodtak utánunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 20, 'Orrunk lehellete, az Úr felkentje megfogattaték az ő vermeikben, a kiről azt mondottuk: az ő árnyékában élünk a pogányok között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 21, 'Örülj és vígadozz, Edom leánya, a ki Uz földjén lakozol, mert még te rád is rád kerül a pohár, megrészegedel és meztelenkedel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 22, 'Eltörültetik a te álnokságod, oh Sion leánya, nem fog téged száműzni többé; meglátogatja a te álnokságodat, Edom leánya fölfedi a te bűneidet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'Emlékezzél meg Uram, mi esett meg rajtunk; tekintsd meg és lásd meg gyalázatunkat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'A mi örökségünk idegenekre szállt; házaink a jövevényekéi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'Apátlan árvák lettünk; anyáink, mint az özvegyek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'Vizünket pénzért iszszuk, tűzifánkat áron kapjuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'Nyakunknál fogva hajtatunk; elfáradtunk, nincsen nyugtunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, 'Égyiptomnak adtunk kezet, az assziroknak, hogy jóllakjunk kenyérrel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'Apáink vétkeztek; nincsenek; mi hordozzuk vétkeiket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, 'Szolgák uralkodnak rajtunk; nincs a ki megszabadítson kezökből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, 'Életünk veszélyeztetésével szerezzük kenyerünket a pusztában levő fegyver miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, 'Bőrünk, mint a kemencze, megfeketedett az éhség lázától.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'Az asszonyokat meggyalázták Sionban, a szűzeket Júda városaiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, 'A fejedelmeket kezökkel akasztották fel; a vének orczáit nem becsülik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, 'Az ifjak a kézi malmot hordozzák, és a gyermekek a fahordásban botlanak el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, 'A vének eltüntek a kapuból, megszüntek az ifjak énekelni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, 'Oda van a mi szívünk öröme, gyászra fordult a mi körtánczunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, 'Elesett a mi fejünknek koronája, jaj most nékünk mert vétkeztünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, 'Ezért lett beteg a mi szívünk, ezekért homályosodtak meg a mi szemeink;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, 'A Sion hegyéért, hogy elpusztult; rókák futkosnak azon!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, 'Te Uram örökké megmaradsz; a te királyi széked nemzedékről nemzedékre!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 20, 'Miért feledkezel el örökre mi rólunk? miért hagysz el minket hosszú időre?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 21, 'Téríts vissza Uram magadhoz és visszatérünk; újítsd meg a mi napjainkat, mint régen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 22, 'Mert bizony-bizony megvetettél minket; megharagudtál ránk felettébb!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, 'És lőn a harminczadik esztendőben, a negyedik hónapban, a hónap ötödikén, mikor én a foglyok közt a Kébár folyó mellett voltam: megnyilatkozának az egek, és láték isteni látásokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, 'A hónap ötödikén (ez az ötödik esztendeje Jojákin király fogságba vitelének).');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, 'Valójában lőn az Úrnak beszéde Ezékiel paphoz, a Búzi fiához a Káldeusok földén, a Kébár folyó mellett, és lőn ott rajta az Úrnak keze.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, 'És látám, és ímé forgószél jött északról, nagy felhő egymást érő villámlással, a mely körül fényesség vala, közepéből pedig mintha izzó ércz látszott volna ki, tudniillik a villámlás közepéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, 'És belőle négy lelkes állat formája tetszék ki, és ez vala ábrázatjok: emberi formájok vala,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, 'És mindeniknek négy orczája vala, és négy szárnya mindenikőjöknek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'És lábaik egyenes lábak, és lábaik talpa mint a borjú lábának talpa, és szikráznak vala, mint a simított ércz színe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'Továbbá emberi kezek valának szárnyaik alatt négy oldalukon. Mind a négyőjöknek orczái és szárnyai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'Szárnyaik egymás mellé lévén szerkesztve, nem fordultak meg jártukban, mindenik az ő orczája irányában megy vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, 'És orczájok formája vala emberi orcza, továbbá oroszlán-orcza mind a négynek jobbfelől, és bika-orcza mind a négynek balfelől, és sas-orcza mind a négynek hátul;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, 'És ezek az ő orczáik. És szárnyaik felül kiterjesztve valának, mindeniknél két szárny összeér vala, kettő pedig fedezé testöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, 'És mindenik az ő orczája irányában megy vala, a hová a lélek vala menendő, oda mennek vala, meg nem fordulván jártukban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'És a lelkes állatok közt látszék, mint egy égő üszög, a mely lángolt, mint a fáklyák, ide s tova futkározva a lelkes állatok közt; és a tűznek fényessége vala, és a tűzből villámlás jöve ki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'És a lelkes állatok ide s tova mozognak vala, mint a villámlás czikázása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, 'És mikor ránéztem a lelkes állatokra, ímé egy-egy kerék vala a földön az állatok mellett mind az ő négy orczájok felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, 'A kerekek mintha tarsiskőből készültek volna, és mind a négyüknek ugyanazon egy formája vala, és úgy látszának egybeszerkesztve, mintha egyik kerék a másik kerék közepében volna;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, 'Jártukban négy oldaluk felé mentek vala; meg nem fordulnak vala jártukban;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 18, 'És talpaik magasak valának és félelmesek, és e talpak rakva valának szemekkel köröskörül mind a négynél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 19, 'És mikor járnak vala a lelkes állatok, járnak vala a kerekek is mellettök, és mikor fölemelkednek vala az állatok a földről, fölemelkednek vala a kerekek is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 20, 'A hová a lélek vala menendő, mennek vala, a hová tudniillik a lélek vala menendő, és a kerekek fölemelkednek vala mellettök, mert a lelkes állatok lelke vala a kerekekben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 21, 'Ha azok mentek, ezek is mennek vala, és ha azok álltak, ezek is állnak vala, és ha fölemelkedtek a földről, fölemelkednek vala a kerekek is mellettök, mert a lelkes állatok lelke vala a kerekekben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 22, 'És vala mintegy mennyezet az állatok feje fölött, olyan mint a csodálatos kristály, kiterjesztve felül fejök felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 23, 'És a mennyezet alatt szárnyaik egyenesek valának, egyik a másikkal összeérvén; mindegyiknek kettő vala, a melyek befedik vala innen, és mindegyiknek kettő vala, a melyek befedik vala amonnan az ő testöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 24, 'És hallám szárnyaik zúgását, mint sok vizeknek zúgását, úgy mint a Mindenhatónak hangját, mikor járnak vala, zúgás hangját, mint valami tábornak zúgását; mikor állának, leeresztik vala szárnyaikat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 25, 'És lőn kiáltás a mennyezeten felül, a mely vala fejök felett, és ők megállván, leeresztik vala szárnyaikat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 26, 'És a mennyezeten felül, a mely fejök felett vala, látszék mint valami zafirkő, királyi széknek formája, és a királyi széknek formáján látszék mint egy ember formája azon felül;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 27, 'És látám izzó érczként ragyogni, a melyet, mintha tűz vett volna körül derekának alakjától fogva és fölfelé; és derekának alakjától fogva és lefelé látám, mintha tűz volna. És fényesség vala körülötte,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 28, 'Mint a milyen a szivárvány, mely a felhőben szokott lenni esős időben, olyan vala a fényesség köröskörül. Ilyen vala az Úr dicsőségének formája, és látám, és orczámra esém, és hallám egy szólónak szavát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, 'És monda nékem: Embernek fia! állj lábaidra, és szólok veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, 'És lélek jöve én belém, a mint szóla, és állata engem lábaimra, és hallám azt, a ki szól vala nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, 'És mondá nékem: Embernek fia! küldelek én téged Izráel fiaihoz, a pártos nemzetségekhez, a kik pártot ütöttek ellenem; ők és atyáik vétkeztek ellenem mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, 'A kemény orczájú fiakhoz és makacs szívűekhez küldelek téged, és ezt mondjad nékik: Így szól az Úr Isten!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, 'Ők pedig vagy hallják, vagy nem hallják, mivelhogy pártos ház, hadd tudják meg, hogy próféta volt köztük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, 'Te pedig, embernek fia, ne félj tőlök, és az ő beszédöktől se félj; ha bogácsok és tövisek vannak is veled, és ha skorpiókkal lakol is együtt; beszédöktől ne félj, orczájoktól ne rettegj, mert ők pártos ház.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, 'És szóljad az én beszédimet nékik, vagy hallják, vagy nem, mert pártos ház.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, 'Te pedig, embernek fia, halld meg a mit én néked szólok. Ne légy pártos mint ez a pártos ház, nyisd föl szádat, és egyed, a mit én adok néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, 'És látám, és ímé egy kéz nyúlt felém, és ímé benne egy könyv türete vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, 'És kiterjeszté azt előttem, és ímé be vala írva elől és hátul, és írva valának reá gyászénekek és nyögések és jajszók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, 'És mondá nékem: Embernek fia! a mi előtted van, edd meg; edd meg ezt a türetet, és menj, szólj az Izráel házának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, 'Felnyitám azért számat, és megéteté velem azt a türetet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, 'És mondá nékem: Embernek fia! hasadat tartsd jól és belső részeidet töltsd meg ezzel a türettel, a melyet adok néked. És megevém azt, és lőn az én számban, mint az édes méz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, 'És mondá nékem: Embernek fia! eredj, menj el az Izráel házához, és szólj az én szavaimmal nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, 'Mert nem valami homályos ajkú és nehéz nyelvű néphez küldetel te, hanem az Izráel házához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, 'Nem sok népekhez, a kik homályos ajkúak és nehéz nyelvűek, kiknek nem érthetnéd beszédöket; bizony, ha ő hozzájok küldöttelek volna, ők hallgatnának reád.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, 'De az Izráel háza nem akar téged hallgatni, mert nem akarnak engem hallgatni, mert az egész Izráel háza kemény homlokú és megátalkodott szívű.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, 'Ímé keménynyé tettem orczádat, a milyen az ő orczájok, és keménynyé homlokodat, a milyen az ő homlokuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, 'Olyanná, mint a gyémánt, a mely keményebb a tűzkőnél, tettem a te homlokodat; ne félj tőlök, és meg ne rettenj tekintetöktől, mert pártos ház.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, 'És mondá nékem: Embernek fia! minden beszédimet, a melyeket szólok néked, vedd szívedbe, és füleiddel halld meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, 'És eredj, menj el a foglyokhoz, a te néped fiaihoz, és szólj és mondjad nékik: Így szól az Úr Isten, vagy hallják vagy nem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 12, 'És fölemele engem a lélek, és hallék mögöttem nagy dörgés szavát: Áldott az Úrnak dicsősége az ő helyéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 13, 'És amaz állatok szárnyainak zúgását, a melyek egymást érik vala, és mellettök a kerekek csikorgását, és nagy dörgés szavát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 14, 'És a lélek fölemele és elragada engem, és elmenék, elkeseredvén haragjában az én lelkem, az Úrnak keze pedig rajtam erős vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 15, 'És eljuték Tél-Ábibba a foglyokhoz, a kik lakoznak vala a Kébár folyó mellett, és leülék, ők is ott ülvén; és ott ülék hét nap némán ő közöttük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 16, 'És lőn hét nap mulva az Úr szava hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 17, 'Embernek fia! őrállóul adtalak én téged Izráel házának, hogy ha szót hallasz számból, intsd meg őket az én nevemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 18, 'Ha ezt mondom a hitetlennek: Halálnak halálával halsz meg, és te őt meg nem inted és nem szólasz, hogy visszatérítsd a hitetlent az ő gonosz útjáról, hogy éljen: az a gonosztevő az ő vétke miatt hal meg, de vérét a te kezedből kívánom meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 19, 'De ha te megintetted a hitetlent, és ő meg nem tért hitetlenségéből és gonosz útjáról: ő az ő vétke miatt meghal, de te megmentetted a te lelkedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 20, 'És ha elfordul az igaz az ő igazságától, és cselekszik álnokságot, és én vetek eléje botránkozást: ő meg fog halni; ha meg nem intetted őt, vétke miatt hal meg és elfelejtetnek igazságai, a melyeket cselekedett; de vérét a te kezedből kívánom meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 21, 'Ha pedig te megintetted azt az igazat, hogy az igaz ne vétkezzék, és ő nem vétkezik többé: élvén él, mert engedett az intésnek, és te a te lelkedet megmentetted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 22, 'És lőn ott az Úrnak keze rajtam, és monda nékem: Kelj fel, menj ki a völgybe, és ott szólok veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 23, 'Fölkelék azért és kimenék a völgybe és ímé ott áll vala az Úrnak dicsősége, hasonlatos ahhoz a dicsőséghez, a melyet a Kébár folyó mellett láttam, és orczámra esém.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 24, 'És jöve belém a lélek, és állata engem lábaimra, és szóla hozzám és monda nékem: Menj be és zárd be magadat a te házadban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 25, 'És te, oh embernek fia, ímé köteleket vetnek reád és azokkal megkötöznek téged, és ki nem mehetsz közikbe;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 26, 'Nyelvedet pedig én ragasztom ínyedhez, és néma leszel, hogy ne légy közöttök feddőző férfiú, mert ők pártos ház.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 27, 'Mikor pedig szólok veled, megnyitom a te szádat, és mondjad nékik: Így szól az Úr Isten; a ki hallja, hallja, a ki nem akarja, nem hallja, mert ők pártos ház.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, 'És te, embernek fia, végy magadnak egy téglát, tedd azt elődbe, és véss reá egy várost, Jeruzsálemet,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, 'És indíts ellene ostromot, és építs ellene tornyot, tölts ellene sánczot, és indíts ellene táborokat, és állass ellene faltörő kosokat köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, 'És végy magadnak egy vasserpenyőt, és állasd fel azt vasfal gyanánt te közted és a város között, és irányozd tekintetedet erősen reá, és legyen ostrom alatt, és te ostromold. Jel ez az Izráel házának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, 'Te pedig feküdj baloldaladra és vesd az Izráel háza vétkét arra; a napok száma szerint, a mennyin azon fekszel, viseljed vétköket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, 'Én pedig meghatároztam néked az ő vétkök éveit napok száma szerint, háromszázkilenczven napban; eddig viseljed az Izráel házának vétkét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, 'És ha ezeket kitöltötted, feküdj a jobboldaladra másodszor, és viseld a Júda házának vétkét negyven napig; egy-egy napot egy-egy esztendőül számítottam néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, 'És Jeruzsálem ostromára irányozd erősen tekintetedet, és karod feltűrve legyen, és prófétálj ő ellene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, 'S ímé köteleket vetettem reád, hogy meg ne fordulhass egyik oldaladról a másikra, míg betöltöd ostromodnak napjait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, 'És végy magadnak búzát és árpát és babot és lencsét és kölest és tönkölyt, és tedd ezeket egy edénybe, és ezekből csinálj magadnak kenyeret; a napok száma szerint, a míg oldaladon fekszel, háromszázkilenczven napon egyed azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, 'A te ételed pedig, a melylyel élsz, legyen súly szerint húsz siklus egy napra; időről-időre egyed azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, 'És vizet mérték szerint igyál, a hinnek hatodrészét igyad időről-időre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, 'És ételedet árpa-lepény formájában egyed, és emberi ganéj tőzegénél süssed azt szemök láttára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, 'És mondá az Úr: Így eszik az Izráel fiai tisztátalan kenyeröket a pogányok közt, a kik közé őket kiűzöm.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, 'És mondék: Ah, ah, Uram Isten! ímé az én lelkem soha meg nem fertéztetett, és dögöt és vadtól szaggatottat nem ettem ifjúságomtól fogva ez ideig, és számon be nem ment tisztátalan hús.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, 'És mondá nékem: Nézd, marhaganéjt engedek néked emberi tőzeg helyett, hogy annál süsd meg a te kenyeredet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, 'És mondá nékem: Embernek fia! ímé én eltöröm a kenyérnek botját Jeruzsálemben, és eszik kenyeröket mértékkel és rettegéssel, és vizöket mértékkel és ájulással iszszák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, 'Azért, hogy kenyér és víz nélkül szűkölködjenek, és elborzadjanak mindnyájan, és megrothadjanak az ő vétkökben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, 'És te, embernek fia, végy magadnak éles kardot, borbélyok beretvájául vedd azt magadnak, és vond el azt a te fejeden és szakálladon, és végy magadnak mérő serpenyőket, és oszd el szőrüket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, 'Harmadrészét tűzben égesd meg a város közepette, midőn betelnek a megszállásnak napjai; azután vedd a harmadrészét, vagdald apróra a karddal a város körül, és harmadrészét szórd oda a szélnek, és én kardot vonszok utánok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, 'És végy ki innét szám szerint keveset, és kösd be azokat ruhád csücskébe;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, 'És ezekből ismét végy ki, és vesd azokat a tűz közepébe és égesd meg a tűzben; ebből megyen tűz Izráel egész házára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, 'Így szól az Úr Isten: Ez Jeruzsálem, a pogányok közibe helyheztettem őt, és körülte a tartományokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, 'De pártos volt törvényeim iránt, gonoszabbul, mint a pogányok, és rendeléseim iránt inkább, mint a tartományok, a melyek körülte vannak, mert törvényeimet megútálták, és rendeléseimben nem jártak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, 'Azért így szól az Úr Isten: A miért ti pártosabbak valátok, mint a pogányok, a kik körültetek vannak, rendeléseimben nem jártatok és törvényeimet nem cselekedtétek, sőt csak a pogányok törvényei szerint is, a kik körültetek vannak, nem cselekedtetek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, 'Ezokért így szól az Úr Isten: Ímé én is ellened leszek, és teszek közötted ítéletet a pogányok szeme láttára;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, 'És cselekszem rajtad azt, mit soha nem cselekedtem és minéműt nem cselekszem többé, – minden te útálatosságidért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, 'Azért az apák egyék meg fiaikat te közötted, és a fiak egyék meg apáikat, és cselekszem rajtad ítéletet, és szétszórom minden maradékodat a szél minden irányában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, 'Ezért, élek én! szól az Úr Isten, bizonyára, mivelhogy szenthelyemet megfertéztetted minden undokságaiddal és minden útálatosságaiddal, azért én is elfordítom rólad irgalom nélkül szememet, s én sem könyörülök rajtad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, 'Harmadrészed döghalállal hal meg és éhség miatt pusztul el közötted, és harmadrészed fegyver miatt hull el körülötted, és harmadrészedet szétszórom a szél minden irányában, és kardot vonszok utánok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, 'És teljessé lesz haragom s nyugtatom rajtok búsulásomat s vígasztalást veszek; és megértik, hogy én, az Úr szóltam buzgó szerelmemben, mikor betöltöm búsulásomat rajtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, 'És teszlek pusztasággá és gyalázattá a pogányok között, a kik körülted vannak, minden melletted elmenő szeme láttára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, 'És leszel gyalázat és csúfság, példa és eliszonyodás a pogányoknak, a kik körülted vannak, mikor ítéletet tartok fölötted haraggal és búsulással és búsult feddésekkel, én, az Úr mondottam;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, 'Mikor bocsátom az éhség gonosz nyilait rájok, hogy pusztítsanak, a melyeket a ti pusztítástokra fogok bocsátani; és éhséget halmozok fölétek, és eltöröm köztetek a kenyér botját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 17, 'És bocsátok reátok éhséget és gonosz vadállatokat, hogy gyermektelenné tegyenek, és döghalál és vérontás megy át rajtad, és fegyvert hozok reád, én, az Úr mondottam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, 'És lőn az Úrnak szava én hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, 'Embernek fia, vesd tekintetedet Izráel hegyeire, és prófétálj ellenök:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, 'És mondjad: Izráel hegyei, halljátok meg az Úr Isten beszédét! Ezt mondja az Úr Isten a hegyeknek és a halmoknak, a mélységeknek és a völgyeknek: Ímé én fegyvert hozok reátok, és elvesztem a ti magaslataitokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, 'És elpusztulnak oltáraitok, és összetörnek naposzlopaitok, és elhullatom sebesültjeiteket bálványaitok előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, 'És vetem az Izráel fiainak holttesteit bálványaik elé, és szétszórom csontjaitokat oltáraitok körül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, 'Minden lakóhelyeteken a városok elpusztuljanak, és a magaslatok elveszszenek, hogy elpusztuljanak és rommá legyenek oltáraitok, és törjenek össze és legyenek semmivé bálványaitok, és kivágattassanak naposzlopaitok, és eltöröltessenek csinálmányaitok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, 'És elhulljon a sebesült közöttetek, hogy megtudjátok, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, 'De maradékot hagyok, hogy legyenek közületek, a kik megmenekedtek a fegyvertől a pogányok közt, mikor szétszórattok a tartományokban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, 'Akkor megemlékeznek én rólam menekültjeitek a pogányok közt, kik közé fogságba vitetének, mert megtörtem parázna szívöket, mely tőlem elszakadt, és bálványaikkal paráználkodó szemeiket, és megundorodnak önmagok előtt a gonoszságokért, melyeket cselekedtek minden útálatosságuk szerint;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, 'És megismerik, hogy én vagyok az Úr: nem hiába mondottam, hogy megcselekszem velök e gonoszt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, 'Így szólt az Úr Isten: Csapj tenyeredbe, toppants lábaddal és mondd: Jaj az Izráel háza minden gonosz útálatosságáért, mert fegyver, éhség és döghalál miatt hullanak el;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, 'A ki messze van, döghalál miatt hal meg, a ki közel van, fegyver miatt esik el, és a ki megmaradt biztonságban, éhség miatt hal meg; és teljessé teszem búsulásomat rajtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 13, 'És megtudjátok, hogy én vagyok az Úr, mikor sebesültjeik ott lesznek bálványaik között az ő oltáraik körül, minden magas halmon, minden hegyeknek tetein, minden zöld fa alatt és minden lombos terpentinfa alatt, a hol csak kedves illatot adának minden bálványaiknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 14, 'Kinyújtom azért kezemet reájok, és teszem a földet kietlen pusztasággá, a pusztától fogva Dibláig minden lakóhelyökön, hadd tudják meg, hogy én vagyok az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, 'És lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, 'És te, embernek fia, így szól az Úr Isten Izráel földjének: Vége! eljött a vég a föld négy szárnyára!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, 'Immár itt a vég rajtad; s bocsátom haragomat reád, és megítéllek útaid szerint, és vetem reád minden útálatosságodat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, 'És nem kedvez az én szemem néked, sem meg nem szánlak; hanem a te útaidat vetem reád, és útálatosságaid közötted lesznek és megtudjátok, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, 'Így szól az Úr Isten: Ímé veszedelem, egyetlen veszedelem; ímé eljött.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, 'Vég jött, eljött a vég, fölserkent ellened, ímé eljött!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, 'Eljött a végzet reád, földnek lakosa! eljött az idő, közel a nap, rémülés és nem víg éneklés a hegyeken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, 'Most rövid időn kiöntöm búsulásomat reád, és teljessé teszem haragomat rajtad, és megítéllek útaid szerint, és rád vetem minden útálatosságodat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, 'És nem kedvez az én szemem, sem meg nem szánlak; útaid szerint fizetek tenéked, és a te útálatosságaid közötted lesznek; és megtudjátok, hogy én vagyok az Úr, a ki ver.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, 'Ímé a nap, ímé eljött, kisarjadt a végzet, kivirágzott a vessző, kivirult a kevélység.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, 'Az erőszakosság a gonoszság veszszejévé nőtt fel, nincs semmi meg belőlök, sem sokaságukból, sem tömegökből, s nincs egy jaj is miattok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, 'Eljött az idő, elközelgett a nap; a vevő ne örüljön, az eladó ne szomorkodjék, mert harag jön minden sokaságára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, 'Mert az eladó eladott jószágához nem térhet vissza többé, még ha élve az élők közt maradna is, mert a jövendölés az ő egész sokasága ellen vissza nem tér, és vétke miatt senki sem lehet hosszú életű.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, 'Kürtöljetek a kürttel és készítsetek el mindent; ám nincsen, a ki harczra menjen, mert haragom minden ő sokasága ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 15, 'A fegyver kivül, a döghalál és éhség belül; a ki a mezőn van, fegyver miatt hal meg, és a ki a városban, azt éhség és döghalál emészti meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 16, 'És menekülnek menekültjeik, és lesznek a hegyeken, mint a völgyek galambjai: mindnyájan nyögvén, kiki vétke miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 17, 'Minden kéz elerőtlenül, és minden térd elolvad, mint a víz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 18, 'Felövezkednek zsákkal, és befedi őket rettegés, és minden orczán szégyen, és mindnyájok fején kopaszság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 19, 'Ezüstjöket az utczákra vetik, és aranyuk szenny lesz előttök; ezüstjök s aranyuk meg nem szabadíthatja őket az Úr búsulásának napján; lelköket azzal jól nem lakatják, s hasokat meg nem tölthetik; mert csábítójok volt az a vétekre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 20, 'És a belőle készült drága ékességeket kevélykedésre használják, és útálatosságuk képeit, undokságaikat abból csinálták, azért tettem előttök azt szenynyé;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 21, 'És adom azt az idegenek kezébe zsákmányul, és a föld hitetleninek prédául, hadd fertéztessék meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 22, 'És elfordítom tőlük arczomat, hadd fertéztessék meg szent helyemet; s betörjenek belé a rontók és megfertéztessék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 23, 'Készítsd a lánczot; mert a föld tele van véres ítélettel, és a város tele van erőszakossággal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 24, 'És elhozom a pogányok leggonoszabbjait, hadd foglalják el házaikat; s véget vetek a hatalmasok kevélységének, s fertézett lesz templomuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 25, 'Rettegés jött el, s keresnek békét és nincs.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 26, 'Egy romlás a másikra jő, és egy hír után más támad, s kérnek látást a prófétától, ám törvény nem lesz a papnál, sem tanács a véneknél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 27, 'A király szomorkodik, a fejedelem irtózatba öltözik; s a föld népének kezei megdermednek. Útjok szerint cselekszem velök, ítéletök szerint ítélem meg őket, hadd tudják meg, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, 'És lőn a hatodik esztendőben, a hatodik hónapban, a hónap ötödik napján: én ülök vala házamban, és Júda vénei ülnek vala előttem és esék reám ott az Úr Istennek keze.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, 'És látám, és ímé vala mintegy tűznek formája, derekának alakjától fogva lefelé tűz vala, és derekától fogva fölfelé vala mint a fényesség, mint az izzó ércz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, 'És kinyújta egy kézformát, és megragada engem fejem üstökénél fogva, és fölemelve vitt engem a lélek a föld és az ég között, és bevive engem Jeruzsálembe isteni látásokban a belső kapu bejáratához, a mely északra néz, a hol vala helye a bosszúság bálványának, a mely bosszúságra ingerel vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, 'És ímé ott vala Izráel Istenének dicsősége, a látás szerint, a melyet láttam a völgyben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, 'És monda nékem: Embernek fia! emeld föl csak szemeidet észak felé. Fölemelém azért szemeimet észak felé: és ímé északra az oltár kapujától áll vala a bosszúság ama bálványa a bejáratnál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, 'És mondá nékem: Embernek fia! látod-e mit cselekesznek? A nagy útálatosságokat, melyeket Izráel háza itt cselekszik, hogy eltávozzam az én szenthelyemtől. De még egyéb nagy útálatosságokat is fogsz látni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, 'És vive engem a pitvar bejáratához, és látám, és ímé egy lyuk vala a falban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, 'És mondá nékem: Embernek fia! ronts csak át a falon! és átronték a falon, és ímé egy ajtó vala ott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, 'És mondá nékem: Menj be és lásd meg a gonosz útálatosságokat, a melyeket ezek ott cselekesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, 'Bemenék azért és látám, és ímé az útálatos csúszó-mászó állatoknak és barmoknak mindenféle képei és Izráel házának minden bálványai vannak bevésve a falon köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, 'És hetven férfiú Izráel házának vénei közül (ezek közepette Jaazanjáhu, a Sáfán fia) áll vala előttök, mindenik a maga tömjénezőjével kezében, s a füstölőszer felhőjének illata száll vala fel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, 'És mondá nékem: Láttad-é, embernek fia, Izráel házának vénei mit cselekesznek a sötétben, kiki az ő képes házában? mert azt mondják: Nem lát minket az Úr, elhagyta az Úr ezt a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, 'És mondá nékem: Még egyéb nagy útálatosságokat is fogsz látni, miket ezek cselekesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, 'És vive engem az Úr háza kapujának bejáratához, a mely északra van, és ímé ott asszonyok ülnek vala, siratván a Tammúzt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 15, 'És mondá nékem: Láttad-é, embernek fia? még egyéb, ezeknél nagyobb útálatosságokat is fogsz látni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 16, 'És bevive engem az Úr házának belső pitvarába, és ímé az Úr templomának bejáratánál, a tornácz és az oltár között vala mintegy huszonöt férfiú, kik hátokkal az Úr templomára és orczájokkal keletre fordultak, s ezek kelet felé leborulva imádták a napot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 17, 'És mondá nékem: Láttad-é, embernek fia? avagy kevés-é Júda házának ily útálatosságokat cselekedni, a milyeneket itt cselekedtek? hogy még a földet is betöltik erőszakossággal, és engem megint haragra ingerelnek, ímé, hogy tartják a venyigét orrukhoz!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 18, 'Én is búsulásom szerint cselekszem, nem fog kedvezni szemem, sem meg nem szánom őket; s ha kiáltanak füleimbe nagy felszóval, nem hallgatom meg őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 1, 'És kiáltá füleimbe nagy felszóval, mondván: Hozzátok el a városra a meglátogatásokat, kinek-kinek a kezében legyen vesztő eszköze.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 2, 'És ímé hat férfi jő vala a felső kapu útjáról, a mely északra néz vala, mindeniknek kezében zúzó eszköze, egy férfi pedig köztük gyolcsba vala öltözve, és íróeszköz vala derekán. És bemenének és állának az érczoltár mellé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 3, 'És Izráel Istenének dicsősége elvonula a Kérubról, a mely fölött vala, a ház küszöbéhez, és kiálta a gyolcsba öltözött férfiúnak, a kinek derekán íróeszköz vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 4, 'És monda az Úr néki: Menj át a város közepén, Jeruzsálem közepén, és jegyezz egy jegyet a férfiak homlokára, a kik sóhajtanak és nyögnek mindazokért az útálatosságokért, a melyeket cselekedtek annak közepében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 5, 'És amazoknak mondá az én hallásomra: Menjetek át a városon ő utána, és vágjátok; ne kedvezzen a ti szemetek, és ne szánakozzatok:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 6, 'Vénet, ifjat, szűzet, gyermeket és asszonyokat öljetek meg mind egy lábig, de azokhoz a férfiakhoz, a kiken a jegy van, ne közelítsetek, és az én templomomon kezdjétek el. Elkezdék azért a vén férfiakon, a kik a ház előtt valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 7, 'És mondá nékik: Fertőztessétek meg a házat, és töltsétek meg a pitvarokat megölettekkel. Menjetek ki. És kimenének és öldöklének a városban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 8, 'És lőn, hogy levágák őket, és én megmaradtam és esém az én orczámra és kiálték és mondék: Ah, ah, Uram Isten, avagy ki akarod-é írtani Izráel egész maradékát, mikor kiöntöd búsulásodat Jeruzsálemre?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 9, 'És mondá nékem: Izráel és Júda házának vétke felette nagy, mivelhogy tele a föld vérontással, és a város tele van igazságtalansággal, mert azt mondották: Elhagyta az Úr ezt a földet, és az Úr nem lát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 10, 'Azért én is (nem kedvez szemem, sem meg nem szánom őket) útjokat fejökhöz verem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 11, 'És ímé a gyolcsba öltözött férfi, kinek íróeszköz vala derekán, választ hozott, mondván: Úgy cselekedtem, a mint parancsolád.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 1, 'És látám, és ímé a mennyezeten, a mely a Kérubok feje fölött vala, látszék felettök, mint valami zafirkő, olyan, mint egy királyi széknek formája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 2, 'És szóla a gyolcsba öltözött férfiúnak, és mondá: Menj be a forgókerekek közé a Kérubok alá, és töltsd meg tenyereidet égő üszöggel onnét a Kérubok közül, és szórd a városra. És beméne szemem láttára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 3, 'A Kérubok pedig állanak a háztól jobbra, mikor a férfi beméne, és a felhő betölté a belső pitvart.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 4, 'És eltávozék az Úr dicsősége a Kérubról, a ház küszöbére, és megtelék a ház a felhővel, és a pitvar betelék az Úr dicsőségének fényességével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 5, 'És a Kérubok szárnyainak csattogása meghallaték a külső pitvarig, mint az erős Isten hangja, mikor beszél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 6, 'És lőn, mikor parancsolt ama gyolcsba öltözött férfinak, mondván: Végy tüzet a forgókerekek közül, a Kérubok közül, az beméne, és álla a kerék mellé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 7, 'És kinyújtá egy Kérub a kezét a Kérubok közül a tűzhöz, mely vala a Kérubok között, és vőn és tevé a gyolcsba öltözöttnek markába, ki elvevé és kiméne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 8, 'És látszék a Kérubokon emberi kéznek formája szárnyaik alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 9, 'És látám, és ímé, négy kerék vala a Kérubok mellett, egyik kerék vala az egyik Kérub mellett és a másik kerék a másik Kérub mellett, és olyanok valának a kerekek, mintha tarsiskőből volnának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 10, 'És mintha volna mind a négyöknek ugyanazon egy formája, mintha egyik kerék a másik kerék közepében volna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 11, 'Jártokban mind a négy oldaluk felé mennek vala, meg nem fordulnak vala jártokban, hanem arra, a merre a fő fordult, mennek vala utána, meg nem fordulnak vala mentökben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 12, 'És egész testök és hátok és kezeik és szárnyaik és a kerekek rakva valának szemekkel köröskörül mind a négy kerekükön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 13, 'Hallám, hogy a kerekeket forgókerekeknek nevezték fülem hallatára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 14, 'És négy orczája vala mindeniknek, az első orcza vala Kérub-orcza, és a második orcza ember-orcza, a harmadik oroszlán-orcza és a negyedik sas-orcza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 15, 'És fölemelkedének a Kérubok. Ez ama lelkes állat, a melyet láttam a Kébár folyó mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 16, 'És mikor járnak vala a Kérubok, járnak vala a kerekek is mellettök, mikor pedig felemelék a Kérubok szárnyaikat, hogy fölemelkedjenek a földről, nem fordulának el a kerekek sem az ő oldaluktól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 17, 'Ha azok állanak vala, ezek is állának, és ha azok felemelkednek vala, fölemelkedének ezek is velök, mert a lelkes állat lelke vala bennök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 18, 'És elvonula az Úrnak dicsősége a ház küszöbétől, és álla a Kérubok fölé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 19, 'És fölemelék a Kérubok szárnyaikat, és fölemelkedének a földről szemem láttára kimentökben és a kerekek is mellettök; és megállának az Úr háza keleti kapujának bejáratánál, és Izráel Istenének dicsősége vala felül ő rajtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 20, 'Ez ama lelkes állat, a melyet láttam az Izráel Istene alatt a Kébár folyó mellett, és megismerém, hogy Kérubok valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 21, 'Négy orczája vala mindeniknek és négy szárnya mindeniknek és emberi kezek formája vala szárnyaik alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 22, 'És orczáik formája: ugyanazok az orczák valának, a melyeket a Kébár folyó mellett láttam, tudniillik formájokat és őket magokat. Mindenik a maga orczája felé megy vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 1, 'És fölemelt engem a lélek, és bevive az Úr házának keleti kapujához, a mely néz keletnek, és ímé, a kapu bejáratánál huszonöt férfi vala, kik között látám Jaazanját, Azzur fiát, és Pelatjáhut, Benájáhu fiát, a nép fejedelmeit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 2, 'És mondá nékem: Embernek fia! ezek a férfiak, a kik gonoszt eszelnek ki és rossz tanácsot adnak ebben a városban,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 3, 'Mondván: Nem egyhamar fogunk házakat építeni; ez a város a fazék, mi pedig a hús.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 4, 'Azért prófétálj ellenök; prófétálj, embernek fia!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 5, 'És esék reám az Úr lelke, és mondá nékem: Mondjad, így szól az Úr: Így szólottatok, Izráel háza! és a mi lelketekben készül, én tudom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 6, 'Sokakat öltetek meg ebben a városban, és utczáit megtöltöttétek megölettekkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 7, 'Ezért, így szól az Úr Isten: Megöletteitek, kiket a város közepére vetettetek, ezek a hús, a város pedig a fazék, és titeket kivisznek belőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 8, 'Fegyvertől féltetek, fegyvert hozok reátok, azt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 9, 'És kiviszlek titeket belőle, és adlak titeket idegenek kezébe, és tartok ítéletet fölöttetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 10, 'Fegyver miatt hulljatok el, Izráel határán ítéllek meg titeket, és megtudjátok, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 11, 'E város ne legyen fazekatok, hogy ti benne hús legyetek, Izráel határán ítéllek el titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 12, 'És megtudjátok, hogy én vagyok az Úr, mert az én végzéseimben nem jártatok, és rendeléseimet nem cselekedtétek, hanem a pogányok módja szerint cselekedtetek, a kik körültetek vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 13, 'És lőn, mikor prófétáltam, Pelatjáhu, Benájáhu fia meghala, én pedig orczámra esém és kiálték nagy felszóval, és mondék: Ah, ah, Uram Isten, te véget vetsz Izráel maradékának!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 14, 'És lőn az Úrnak szava én hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 15, 'Embernek fia! a te atyádfiai, atyádfiai, a te rokonaid és Izráel egész háza együtt azok, a kikről Jeruzsálem lakói ezt mondják: távozzatok el az Úrtól, nékünk adatott ez a föld örökségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 16, 'Ezokáért mondjad: így szól az Úr Isten: Mivelhogy távol vetettem őket a pogányok közé, és szétszórtam őket a tartományokba, tehát én leszek nékik templomul rövid időre a tartományokban, a melyekbe mentek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 17, 'Ennekokáért mondjad: Így szól az Úr Isten: Egybegyűjtelek titeket a népek közül és együvé hozlak titeket a tartományokból, a melyekben szétszórattatok, és adom néktek Izráel földjét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 18, 'És bemennek oda és eltávolítják minden ő fertelmességeit és minden útálatosságait ő belőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 19, 'És adok nékik egy szívet, és új lelket adok belétek, és eltávolítom a kőszívet az ő testökből, és adok nékik hússzívet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 20, 'Hogy az én végzéseimben járjanak és rendeléseimet megőrizzék és cselekedjék azokat, és legyenek nékem népem és én leszek nékik Istenök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 21, 'De a kiknek szívök az ő fertelmességeik és útálatosságaik szíve szerint jár, azoknak útját fejökhöz verem, mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 22, 'És fölemelék a Kérubok szárnyaikat s a kerekek mellettök, és Izráel Istenének dicsősége rajtok felül vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 23, 'És felszálla az Úrnak dicsősége a város közepéből, és álla a hegyre, mely a várostól keletre van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 24, 'A lélek pedig felvőn engem, és vive Káldeába a foglyokhoz látásban az Isten lelke által, és felszálla előlem a látás, a melyet láttam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 25, 'És elbeszélém a foglyoknak az Úrnak minden beszédét, a melyet nékem megjelentetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 1, 'És lőn az Úrnak szava énhozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 2, 'Embernek fia! pártos ház közepette lakol, kiknek szemeik vannak a látásra, de nem látnak, füleik vannak a hallásra, de nem hallanak, mert ők pártos ház.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 3, 'És te, embernek fia, készíts magadnak vándorútra való eszközöket, és vándorolj ki nappal szemeik előtt, és vándorolj ki helyedről más helyre szemök láttára; talán meglátják! mert ők pártos ház.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 4, 'És vidd ki eszközeidet, úgy, mint vándorútra való eszközöket, nappal szemök láttára, te pedig menj ki estve szemök láttára, úgy a hogy a vándorok szoktak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 5, 'Szemök láttára lyukaszd át a falat, és azon át vidd ki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 6, 'Szemök láttára emeld válladra, a sötétben vidd ki, orczádat fedd be, hogy ne lásd a földet, mert csodajelül rendeltelek az Izráel házának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 7, 'Úgy cselekedtem azért, a mint parancsolva vala nékem; eszközeimet kihordám nappal, mint vándorútra való eszközöket, és este átlyukasztám a falat kezemmel; a sötétben kivivém, vállamra emelém szemök láttára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 8, 'És lőn az Úr beszéde én hozzám reggel, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 9, 'Embernek fia! Nem mondta-é néked Izráel háza, ez a pártos ház: mit cselekszel?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 10, 'Mondjad nékik: Így szól az Úr Isten: a fejedelemnek szól ez a próféczia, ki Jeruzsálemben van, és Izráel egész házának, a mely ott lakozik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 11, 'Mondjad: Én csodajeletek vagyok; a mint én cselekedtem, úgy történik velök: fogságba, rabságra mennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 12, 'És a fejedelem, ki közöttök van, vállát megrakván a sötétben, kimegyen; a falat átlyukasztják, hogy így vigyék ki őt, orczáit befedi, hogy ne lássa szemeivel épen ő a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 13, 'És kiterjesztem hálómat ellene, és megfogatik varsámban, és elviszem őt Bábelbe a Káldeusok földére, de azt nem fogja látni, és ott fog meghalni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 14, 'És mindeneket, kik körülte vannak az ő segítségére, és minden seregeit szélnek szórom mindenfelé, és kardot vonok utánok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 15, 'És megtudják, hogy én vagyok az Úr, mikor eloszlatom őket a pogányok közé, és szétszórom őket a tartományokba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 16, 'De meghagyok közülök kevés férfiakat a fegyvertől, éhségtől s döghaláltól, hogy elbeszéljék minden útálatosságukat a pogányok közt, a kik közé mennek, s hogy megtudják, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 17, 'És lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 18, 'Embernek fia! kenyeredet rettegéssel egyed, és vizedet reszketéssel és félelemmel igyad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 19, 'És szólj a föld népének: Ezt mondja az Úr Isten Jeruzsálem lakóiról, Izráel földjéről: kenyeröket félelemmel eszik és vizöket ájulással iszszák, hogy pusztaságra vetkőzzék földje bőségéből minden lakói álnoksága miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 20, 'És a lakott városok elpusztulnak s a föld pusztaság lesz és megtudjátok, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 21, 'És lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 22, 'Embernek fia! micsoda közmondástok van néktek Izráel földjén? hogy azt mondják: a napok csak haladnak, ám semmivé lesz minden látás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 23, 'Ezokért mondd nékik: Ezt mondja az Úr Isten: Megszüntetem e közmondást és nem mondogatják azt többé Izráelben, sőt inkább mondd nékik: elközelgettek a napok, és minden látás teljesül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 24, 'Mert nem lesz többé semmi hiábavaló látás és hizelgő jövendölgetés Izráel házának közepette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 25, 'Mert én szólok, az Úr; s a mely szót szólok, meglészen, nem halad tovább. Mert a ti napjaitokban, pártos ház, szólok egy szót és megcselekszem, ezt mondja az Úr Isten!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 26, 'És lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 27, 'Embernek fia! ímé, Izráel háza ezt mondja: A látás, melyet ez lát, sok napra való, és messze időkre prófétál ő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 28, 'Ezokért mondjad nékik: Így szól az Úr Isten: Nem halad tovább semmi én beszédem; a mit szólok, az a szó meglészen, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 1, 'És lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 2, 'Embernek fia! prófétálj Izráel prófétái ellen, a kik prófétálnak, és mondjad azoknak, a kik önnön szívökből próféták: Halljátok meg az Úr beszédét!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 3, 'Így szól az Úr Isten: Jaj a bolond prófétáknak, a kik az önnön lelkök után mennek, mert semmit sem láttak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 4, 'Mint rókák a romok közt, olyanokká lettek prófétáid, oh Izráel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 5, 'Nem hágtatok fel a törésekhez, nem falaztatok falat Izráel háza körül, hogy megállhassatok a harczban az Úrnak napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 6, 'Hívságot láttak s hazug jövendölgetést, kik ezt mondják: Monda az Úr! holott az Úr nem bocsátotta őket, és még várják, hogy betelik beszédök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 7, 'Avagy nem hiábavaló látást láttatok-é, és nem hazug jövendölgetést szóltatok-é? midőn ezt mondjátok vala: Monda az Úr! holott én nem szólottam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 8, 'Ennekokáért így szól az Úr Isten: Mivelhogy hívságot szólottatok és hazugságot láttatok, azért ímé én ellenetek leszek, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 9, 'És lészen kezem a próféták ellen, kik hívságot látnak és hazugságot jövendölgetnek; az én népem gyülekezetében nem lesznek, Izráel házának könyvébe nem irattatnak, és Izráel földjére be nem mennek, és megtudjátok, hogy én vagyok az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 10, 'Azért, mert eláltatták az én népemet, mondván: béke! holott nincsen béke; és ha a nép falat épít, ímé ők bemázolják azt mázzal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 11, 'Mondjad a mázzal mázolóknak, hogy leomlik; ömlő záporeső lészen, és ti jégeső kövei hulljatok, szélvihar hasítsd!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 12, 'És ímé leomlik a fal. Avagy nem mondják-é majd néktek: hol a mázolás, a melylyel mázolátok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 13, 'Ezokáért így szól az Úr Isten: És meghasogatom szélviharral búsulásomban, és ömlő zápor lészen haragomban, és lésznek jégeső kövei búsulásomban annak elrontására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 14, 'És ledöntöm a falat, melyet mázzal mázoltatok és levetem a földre, és meztelen lesz fundamentoma; és leomlik, és ti veszszetek el közepette, és tudjátok meg, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 15, 'És teljessé teszem búsulásomat a falon és azokon, a kik mázolák azt mázzal, és mondom néktek: nincs a fal és nincsenek, a kik azt mázolák,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 16, 'Tudniillik Izráel prófétái, kik prófétálnak Jeruzsálemnek és látnak néki békességnek látását, holott nincsen békesség, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 17, 'És te, embernek fia, fordítsd orczádat néped leányaira, a kik önnön szívükből prófétálnak, és prófétálj ellenök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 18, 'És mondjad: Így szól az Úr Isten: Jaj azoknak, a kik kötéseket varrogatnak minden kézcsuklóra, és takarókat készítenek akármilyen termetűek fejére, hogy lelkeket vadászszanak! Némely lelkeket elvadásztok népemtől, másokat elevenen megtartotok a magatok hasznára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 19, 'És megszentségtelenítetek engem népem előtt néhány marok árpáért és falat kenyérért, hogy lelkeket öljetek, melyeknek nem kellene meghalniok, és hogy lelkeket elevenen megtartsatok, melyeknek nem kellene élniök, hazudozván népemnek, a mely hazugságra hallgat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 20, 'Ezokáért így szól az Úr Isten: Ímé én kötéseitek ellen leszek, a melyekkel ti a lelkeket vadászszátok, mint madarakat; és leszaggatom azokat karjaitokról, s a lelkeket, melyeket ti vadásztok, szabadon bocsátom, mint madarakat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 21, 'És elszaggatom takaróitokat, és megszabadítom népemet kezetekből, és nem lesznek többé zsákmány a ti kezetekben, s megtudjátok, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 22, 'Mivelhogy megszomorítjátok az igaznak szívét hazugsággal, holott én őt bántani nem akartam, s megerősítitek a hitetlen kezeit, hogy meg ne térjen gonosz útjáról, hogy őt életben megtartsam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 23, 'Ezokáért hívságot nem láttok és jövendőt nem jövendölgettek többé, s megszabadítom népemet a ti kezetekből, és megtudjátok, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 1, 'És jövének hozzám férfiak Izráel vénei közül, és leülének én előttem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 2, 'És lőn az Úrnak beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 3, 'Embernek fia! Ezek a férfiak fölvették bálványaikat szívökbe, és vétkeik botránkozását orczáik elé állították. Vajjon engedjem-é, hogy megkérdezzenek engem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 4, 'Ezokáért szólj velök, és mondjad nékik: Ezt mondja az Úr Isten: Valaki az Izráel házából bálványait szívébe fölveszi, és vétkének botránkozását teszi orczái elé, és megy a prófétához: én, az Úr felelek meg annak énmagam által bálványainak sokasága miatt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 5, 'Hogy megragadjam Izráel házát az ő szívökben, a kik elfordultak tőlem bálványaik miatt mindnyájan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 6, 'Ezokáért mondjad Izráel házának: Ezt mondja az Úr Isten: Térjetek meg, és forduljatok el bálványaitoktól és minden útálatosságtoktól fordítsátok el orczátokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 7, 'Mert valaki az Izráel házából és a jövevények közül, a kik Izráelben laknak, elhajlik tőlem, és az ő bálványait veszi föl szívébe, és vétkének botránkozását teszi orczája elé, és megyen a prófétához, hogy ez tanácsot kérjen ő néki én tőlem: én, az Úr felelek meg annak énmagam által;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 8, 'És ellene fordítom orczámat annak a férfiúnak, és vetem őt jegyül és közbeszédül, és kiirtom népem közül, és megtudjátok, hogy én vagyok az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 9, 'Ha pedig a próféta megtéveszteni engedi magát, hogy kijelentést adjon: én, az Úr tévesztettem meg azt a prófétát; és kinyújtom kezemet ellene, és kivesztem őt az én népem, Izráel közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 10, 'És viselik vétköket; a milyen a kérdező vétke, olyan legyen a próféta vétke is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 11, 'Azért, hogy el ne tévelyedjék többé Izráel háza én tőlem, és többé meg ne fertéztessék magokat minden ő elszakadásukkal, hanem legyenek az én népem és én legyek Istenök, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 12, 'És lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 13, 'Embernek fia! ha valamely ország vétkeznék ellenem, elpártolván tőlem, és én kinyújtván kezemet ellene, eltörném néki a kenyérnek botját, és bocsátanék reá éhséget, és kiirtanék belőle embert és barmot;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 14, 'És ha volna ez a három férfiú benne: Noé, Dániel és Jób: akkor ők az ő igazságukkal a magok lelkét megszabadítanák, azt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 15, 'Ha gonosz vadállatokat bocsátanék át az országon, hogy azt gyermektelenné tegyék, és az pusztává lenne, a melyen senki át nem menne a vadállatok miatt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 16, 'Benne ama három férfiú (élek én, az Úr Isten mondja) sem fiakat, sem leányokat meg nem szabadítana, csak magokat szabadítanák meg, az ország pedig pusztává lenne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 17, 'Avagy ha fegyvert hoznék amaz országra, és mondanám: fegyver, menj át ez országon! és kiirtanék belőle embert és barmot,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 18, 'És ama három férfiú benne volna, élek én, az Úr Isten mondja, nem szabadítana meg sem fiakat, sem leányokat, hanem csak magokat szabadítanák meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 19, 'Avagy ha döghalált bocsátanék arra az országra, és kiönteném búsulásomat reá vérben, hogy kiirtsak belőle embert és barmot,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 20, 'S Noé, Dániel és Jób benne volna: élek én, az Úr Isten mondja, nem szabadítanának meg sem fiat, sem leányt; ők igazságukkal csak a magok lelkét szabadítanák meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 21, 'Mert így szól az Úr Isten: Mennyivel inkább, ha e négy nehéz ítéletemet: a fegyvert, éhséget, vadállatot és döghalált bocsátom Jeruzsálemre, hogy kiirtsak belőle embert és barmot!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 22, 'Ímé, megmaradnak benne némely menekültek, a kiket kivezetnek, fiak és leányok; ímé ők kimennek hozzátok, hogy lássátok útjokat és cselekedeteiket, és vígasztalást vegyetek a veszedelemből, melyet Jeruzsálemre hoztam, mindarra nézve, a mit hoztam reá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 23, 'És megvígasztalnak titeket, ha látjátok útjokat és cselekedeteiket megismeritek, hogy nem hiába cselekedtem mindazt, a mit cselekedtem vele, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 1, 'És lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 2, 'Embernek fia! mire való a szőlőtőke fája egyéb fa között, a venyige, mely az erdő fái között van?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 3, 'Avagy vesznek-é abból fát, hogy valami eszközt csináljanak belőle? avagy vesznek-é belőle szeget, hogy mindenféle edényt akaszszanak reá?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 4, 'Ímé a tűznek adatott, hogy megemészsze; két végét megemésztette már a tűz, és közepe megpörkölődött, vajjon való-é valami eszközre?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 5, 'Ímé, míg ép vala, semmi eszközre nem vala jó; menynyivel kevésbbé csinálhatnak belőle valamit most, mikor a tűz megemésztette és megpörkölődött!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 6, 'Azért így szól az Úr Isten: A mint a szőlőtőke fáját az erdő fái közül a tűznek adtam megemésztésre, úgy adtam oda Jeruzsálem lakóit;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 7, 'És ellenök fordítom arczomat. A tűzből jöttek ki és a tűz emészsze meg őket, és megtudjátok, hogy én vagyok az Úr, mikor arczomat ellenök fordítom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 8, 'És teszem a földet pusztasággá, mivelhogy elpártoltak tőlem, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 1, 'És lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 2, 'Embernek fia! add tudtára Jeruzsálemnek az ő útálatosságait,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 3, 'És mondjad: Így szól az Úr Isten Jeruzsálemnek: A te származásod és születésed Kanaán földjéről való; atyád az Emoreus és anyád Hitteus asszony.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 4, 'Születésed pedig ilyen volt: a mely napon születtél, el nem metszették a köldöködet, és vízzel meg nem mostak, hogy tiszta lennél, sóval sem töröltek meg, sem be nem póláltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 5, 'Szem meg nem szánt téged, hogy ezekből valamit veled cselekedett volna, könyörülvén rajtad; hanem kivetettek a nyilt mezőre, mert útáltak, a mely napon születtél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 6, 'Ekkor elmenék melletted és látálak véredben eltapodva, és mondék néked: A te véredben élj! mondék ismét néked: A te véredben élj!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 7, 'Sok ezerekre szaporítottalak, mint a mezei füvet, és megszaporodál és fölnevekedél és jutál nagy szépségre; emlőid duzzadának s szőröd kinőtt vala, de te mezítelen és befedezetlen valál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 8, 'Ekkor elmenék melletted, és látálak, és ímé a te korod a szerelem kora vala, és kiterjesztém fölötted szárnyamat s befödözém mezítelenségedet, és megesküvém néked s frigyre léptem veled; azt mondja az Úr Isten, és lől az enyém.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 9, 'És megmosálak vízzel és elmosám rólad véredet, és megkenélek olajjal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 10, 'És felöltöztetélek hímes ruhába, és felsaruztalak borjúfóka bőrrel, s övezélek fehér gyolcscsal s befedélek selyemmel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 11, 'És felékesítélek ékeségekkel, s adtam karpereczeket kezeidre és lánczot nyakadra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 12, 'És adtam orrpereczet orrodra és függőket füleidre és ékes koronát fejedre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 13, 'És felékesítéd magadat aranynyal és ezüsttel, és öltözeted vala fehér gyolcs és selyem és hímes ruha; lánglisztet, mézet és olajat ettél, és megszépülél felette igen, s királyságra jutál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 14, 'És kiméne híred a pogányok közé a te szépségedért; mert tökéletes vala az ékességeim által, a melyeket reád tettem, azt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 15, 'De elbízád magadat szépségedben és paráznává lőn híred szerint, elárasztál paráznaságaiddal minden melletted elmenőt: legyen kedve szerint!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 16, 'És vevél a te ruháidból s csinálál magadnak magaslatokat különböző szinnel borítva, s paráználkodál azokon; ilyen még nem volt és nem is lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 17, 'És vevéd a te ékességidet az én aranyomból és ezüstömből, melyeket néked adtam, és csináltál magadnak férfiú képeket, és azokkal paráználkodál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 18, 'És vevéd hímes ruháidat és befedezéd azokat, és olajomat és füstölőszeremet vetéd eléjök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 19, 'És az én eledelemet, melyet néked adtam, – lángliszttel és olajjal és mézzel etettelek vala, – ő eléjök rakád kedves illatul; így lőn, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 20, 'És vevéd a te fiaidat és leányaidat, kiket nékem szültél vala, és megáldozád őket azoknak eledelül. Avagy nem volt-é már elég paráznaságodból,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 21, 'Hogy megölted fiaimat is, és oda adád őket, midőn tűzben nékik áldozád?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 22, 'És minden útálatosságaidban és paráznaságaidban meg nem emlékeztél a te ifjúságod napjairól mikor mezítelen és befedezetlen valál, véredben eltapodva voltál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 23, 'És lőn minden gonoszságod után, (Jaj, jaj néked! azt mondja az Úr Isten,)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 24, 'Építél magadnak tetőt, és csináltál magaslatot minden utczán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 25, 'És minden keresztútnál megépítéd magaslatodat, s útálatossá tevéd szépségedet, és kétfelé vetéd lábaidat minden melletted elmenőnek, és sokasítád paráznaságodat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 26, 'És paráználkodál Égyiptom fiaival, szomszédiddal, a nagytestűekkel, és sokasítád paráznaságodat, hogy engem ingerelj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 27, 'És ímé kinyújtottam kezemet ellened, s megkisebbítém rendelt részedet, és adálak téged a te gyűlölőidnek, a Filiszteusok leányainak csúfolásukra, a kik átallák fajtalan útadat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 28, 'S Assiria fiaival is paráználkodál, mert meg nem elégedél; paráználkodál velök, és még sem elégedél meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 29, 'És sokasítád paráznaságodat a kalmárok földje, Káldea felé, de még ezzel sem elégedél meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 30, 'Mily gyenge a szíved, azt mondja az Úr Isten, hogy mindezeket cselekedted, egy rakonczátlan rima cselekedeteit!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 31, 'Hogy állítál magadnak fedelet minden keresztúton, és magaslatokat csinálál minden utczán, de nem voltál olyan, mint a rima, kicsibe véve a bért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 32, 'Te házasságtörő asszony! férje helyett idegeneket fogad el!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 33, 'Minden rimának bért adnak, te pedig magad adtad ajándékidat minden szeretődnek, így megvásárlád őket, hogy bemenjenek hozzád mindenfelől paráznaságidért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 34, 'És lőn különbség közted és más asszonyok közt paráznaságaidban; mert utánad nem jártak a paráznák; te adál bért nékik és bért ők nem adának néked, így lőn különbséged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 35, 'Azért te rima, halld meg az Úr beszédét!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 36, 'Így szól az Úr Isten: A miatt, hogy eláradt gyalázatod és föl van takarva mezítelenséged a te szeretőiddel való paráznaságaidban; és minden útálatos bálványaid miatt és fiaid vére miatt, kiket azoknak adtál:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 37, 'Ezokáért ímé egybegyűjtöm minden szeretődet, kiknek kedves valál, és mindazokat, a kiket szerettél, együtt azokkal, a kiket gyűlöltél, és egybegyűjtöm őket ellened mindenfelől, és föltakarom mezítelenségedet előttök, hogy lássák minden te mezítelenségedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 38, 'És megítéllek téged a házasságtörő és vért ontó asszonyok ítéletével, és véredet kiontatom búsulásomban és féltő szerelmemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 39, 'És adlak téged kezökbe, és leszakítják tetődet és lerontják magaslataidat és lehúzzák rólad ruháidat és elveszik ékességeidet, és hagynak mezítelenül s ruhátalanul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 40, 'És összehoznak gyűlést ellened, és megköveznek és összevagdalnak fegyvereikkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 41, 'És megégetik házaidat tűzzel, és ítéletet cselekesznek rajtad sok asszony szeme láttára, és megszüntetem paráznaságodat, és bért sem adsz többé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 42, 'És megnyugotom búsulásomat rajtad, hogy eltávozzék féltő szerelmem te tőled, s megnyugoszom és többé nem haragszom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 43, 'Mivelhogy meg nem emlékeztél ifjúságod napjairól, és ingerlettél engem mindezekkel, azért ímé én is fejedhez verem útadat, ezt mondja az Úr Isten, és többé nem cselekszed a fajtalanságot minden útálatosságod mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 44, 'Ímé, valaki közmondással él, rólad veszi azt, mondván: A minémű az anya, olyan a leánya is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 45, 'Anyád leánya vagy te, a ki megútálta férjét s fiait, és öcséidnek nénje vagy, a kik megútálták férjeiket és fiaikat; anyátok Hitteus asszony és atyátok Emoreus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 46, 'És a te nénéd Samaria vala, ő és leányai, ki balkezed felől lakik vala; és öcséd, a ki jobbkezed felől lakik vala, Sodoma és leányai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 47, 'És nem az ő útaikon jártál, és nem az ő útálatosságaik szerint cselekedtél, de csak kevés ideig; de aztán gonoszabb valál azoknál minden útadban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 48, 'Élek én! azt mondja az Úr Isten, így nem cselekedett Sodoma, a te öcséd, ő és leányai, a mint cselekedtél te és a te leányaid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 49, 'Ímé, ez volt a vétke Sodomának, a te öcsédnek: kevélység, eledel bősége és gondtalan békesség volt nála és leányainál, de a szűkölködőnek és szegénynek kezét nem fogta meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 50, 'És felfuvalkodának s cselekedének útálatosságot előttem, és elveszítém őket, mikor ezt megláttam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 51, 'És Samaria félannyit sem vétkezett, mint te, mert többek a te útálatosságaid, mint az övék; és így nőtestvéreidet nálad igazabbaknak bizonyítád minden útálatosságiddal, a melyeket cselekvél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 52, 'Te is azért viseld gyalázatodat, a melyre pedig nénédet ítélted; a te bűneid miatt, melyekben nálok útálatosabban cselekvél, igazabbak ők nálad. Szégyenülj meg hát te is s viseld gyalázatodat, hogy nőtestvéreidet nálad igazabbaknak bizonyítád.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 53, 'És visszahozom foglyaikat, Sodomának s leányainak foglyait és Samariának s leányainak foglyait; s visszahozom a te foglyaidat is amazok közepette;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 54, 'Azért, hogy viseljed gyalázatodat és megszégyenülj mindazokért, miket cselekedtél, mikor azoknak vígasztalásukra leszel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 55, 'És nőtestvéreid, Sodoma és leányai visszatérnek előbbi állapotjokba, és Samaria s leányai visszatérnek előbbi állapotjokba, és te is és leányaid visszatértek előbbi állapototokba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 56, 'És nem vala-é öcséd, Sodoma, szóbeszéd a te szádban kevélykedésed napján,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 57, 'Minekelőtte kitudódott volna gonoszságod; a miképen te most gyalázatuk vagy Siria leányainak s minden körülötted valóknak, a Filiszteusok leányainak, kik útálnak téged köröskörül?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 58, 'Fajtalanságodat és útálatosságaidat magad viseled, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 59, 'Mert ezt mondja az Úr Isten: És ha úgy cselekedtem veled, mint te cselekedtél, midőn megvetetted az esküt, hogy megtörd a frigyet:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 60, 'Én megemlékezem frigyemről, a melyet veled ifjúságod napjaiban kötöttem, és örök frigyet vetek veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 61, 'És te megemlékezel útaidról és megszégyenled magadat, mikor hozzád veszed nőtestvéreidet, a kik nagyobbak nálad, együtt azokkal, a kik kisebbek, s adom őket néked leányaidul, de nem a te frigyedből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 62, 'És én megerősítem frigyemet veled, s megismered, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 63, 'Hogy megemlékezzél és pirulj, és meg ne nyissad többé szádat szégyenletedben, mikor megkegyelmezek néked mindenekben, valamit cselekedtél, azt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 1, 'És lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 2, 'Embernek fia, adj találós mesét, és mondj példabeszédet Izráel házának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 3, 'És mondjad: Így szól az Úr Isten: A nagyszárnyú nagy saskeselyű, melynek hosszú csapótollai valának, s mely rakva vala különféle színű tollakkal, jöve a Libanonra, és elfoglalá a czédrusfa tetejét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 4, 'Gyönge ágainak hegyét letépte, és vivé azt a kalmárok földére, az árusok városában tevé le.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 5, 'És vőn annak a földnek magvából, és elveté azt termékeny mezőbe; sok vizek mellé vivé; mint fűzfát ülteté el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 6, 'És felsarjadt, és lőn elterülő, alacsony szőlőtővé, hogy vesszőit amahhoz fordítsa s gyökerei amaz alatt legyenek, és szőlőtővé lőn, és vesszőket terme, s ágacskákat bocsáta ki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 7, 'És vala más nagy szárnyú, soktollú nagy saskeselyű, és ímé, ez a szőlőtő feléje terjeszté gyökereit s vesszeit hozzá nyújtá ültetésének ágyaiból, hogy öntözze őt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 8, 'Pedig jó földbe, sok víz mellé ültették vala el, hogy ágakat hajtson és gyümölcsöt teremjen, hogy legyen jeles szőlőtő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 9, 'Mondjad: Így szól az Úr Isten: Vajjon jó szerencsés lesz-é? Vajjon gyökereit nem szaggatja-é ki, és gyümölcsét nem vágja-é le, hogy elszáradjon, hajtásának minden ága elszáradjon, és pedig nem erős karral és sok néppel támad reá, hogy kitépje azt gyökerestől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 10, 'És ímé elplántáltatott, jó szerencsés lesz-é? Avagy ha a napkeleti szél illeti őt, nem szárad-é el teljesen, ültetésének ágyában nem szárad-é el?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 11, 'És lőn az Úr szava hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 12, 'No, mondjad a pártos háznak: Avagy nem értettétek-é mi ez? Mondjad: Ímé, eljött a babiloni király Jeruzsálembe, és fogá királyát és fejedelmeit és elvivé őket magához Babilonba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 13, 'És vőn a királyi magból, s frigyet szerze vele, s megesketé őt, de a földnek erőseit elvivé,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 14, 'Hogy alacsony királyság legyen, hogy fel ne emelkedjék, hanem frigyét megőrizze, hogy ez megálljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 15, 'De pártot üte ellene, bocsátván követeit Égyiptomba, hogy adjon néki lovakat és sok népet. Vajjon jó szerencsés lesz-é? Vajjon megszabadítja-é magát, a ki ezeket cselekszi? a ki megszegte a szövetséget, megszabadul-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 16, 'Élek én, ezt mondja az Úr Isten, hogy annak a királynak lakóhelyén, a ki őt királylyá tette, a kinek tett esküjét megvetette, s a kivel tett frigyét megszegte, ott nála, Babilonban hal meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 17, 'És a Faraó nagy haddal és nagy sokasággal vele semmit nem tesz a háborúban, mikor sánczot töltenek és tornyot építenek sok lélek kiirtására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 18, 'S ha megvetette az esküt, hogy megszegje a frigyet, pedig ímé, kezet adott rá, s mégis megcselekedte mindezeket; nem fog megszabadulni!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 19, 'Azért így szól az Úr Isten: Élek én, hogy eskümet, melyet megvetett, és frigyemet, melyet megszegett, fejéhez verem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 20, 'És kiterjesztem hálómat ellene, és megfogatik varsámban, és elviszem őt Babilonba s ott törvénykezem vele gonoszságáért, melylyel ellenem járt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 21, 'És minden menekültje minden seregéből fegyver miatt hull el, és a megmaradottak szélnek szélednek mindenfelé, és megtudjátok, hogy én, az Úr beszéltem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 22, 'Így szól az Úr Isten: És veszek én ama magas czédrus tetejéből, és elültetem; felső ágaiból egy gyönge ágat szegek le, s elplántálom én magas és fölemelt hegyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 23, 'Izráel magasságos hegyén plántálom őt, és ágat nevel és gyümölcsöt terem s nagyságos czédrussá nevekedik, hogy lakjanak alatta, mindenféle szárnyas madarak ágainak árnyékában fognak lakozni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 24, 'És megismeri a mező minden fája, hogy én, az Úr tettem a magas fát alacsonynyá, az alacsony fát magassá; megszáraztottam a zöldelő fát, és zölddé tettem az asszú fát. Én, az Úr szólottam és megcselekedtem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 1, 'És lőn az Úr szava hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 2, 'Mi dolog, hogy ezt a közbeszédet szoktátok mondani Izráel földjén, mondván: Az atyák ettek egrest, és a fiak foga vásott meg bele?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 3, 'Élek én, ezt mondja az Úr Isten, nem lesz többé helye köztetek ennek a közbeszédnek Izráelben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 4, 'Ímé, minden lélek enyém, úgy az atyának lelke, mint a fiúnak lelke enyém; a mely lélek vétkezik, annak kell meghalni!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 5, 'És ha valaki igaz lesz, és törvény szerint igazságot cselekszik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 6, 'Ha a hegyeken nem eszik, és szemeit föl nem emeli Izráel házának bálványaira, és felebarátja feleségét meg nem fertézteti, és asszonyhoz tisztátalanságában nem közeledik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 7, 'És senkit nem nyomorgat, az adósnak a zálogot visszaadja, ragadományt nem ragadoz, az éhezőnek kenyerét adja és a mezítelent ruhával befödi;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 8, 'Uzsorára nem ád, kamatot nem vesz, megvonja kezét az álnokságtól, igaz ítéletet tesz a felek közt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 9, 'Az én parancsolatimban jár és törvényeimet megőrzi, hogy igazságot cselekedjék; ez az igaz, ő élvén él, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 10, 'És ha erőszakos fiat nemz, a ki vért ont, és csak egyet is cselekszik amazokból;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 11, 'Mindezeket pedig nem cselekedte; hanem a hegyeken evett, és felebarátjának feleségét megfertéztette;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 12, 'A szűkölködőt és szegényt nyomorgatta, ragadományokat ragadozott, zálogot vissza nem adott, és a bálványokra emelte szemeit, útálatosságot cselekedett;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 13, 'Uzsorára adott és kamatot vett: és az ilyen éljen? Nem él! Mindezeket az útálatosságokat cselekedte, halállal haljon meg, az ő vére legyen ő rajta!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 14, 'S ímé, ha fiat nemz, és ez látja atyjának minden vétkét, melyeket cselekszik; látja, de nem cselekszik azok szerint:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 15, 'A hegyeken nem eszik, és szemeit nem emeli fel Izráel házának bálványaira, felebarátjának feleségét meg nem fertézteti,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 16, 'És senkit sem nyomorgat, zálogot nem vesz, ragadományt nem ragadoz, kenyerét az éhezőnek adja és a mezítelent ruhával befödi;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 17, 'A szegényre nem veti rá kezét, uzsorát és kamatot nem vesz, törvényeim szerint cselekszik, parancsolataimban jár: az ilyen ne haljon meg atyja vétkéért, hanem élvén éljen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 18, 'Atyja, mert nyomorgatást követett el, ragadományt ragadozott atyjafiától, és a mi nem jó, azt cselekedte népe között: ímé meghal a maga vétkéért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 19, 'És ti ezt mondjátok: Miért ne viselje a fiú az apa vétkét? Ám a fiú, törvény szerint és igazságot cselekedett, minden parancsolatimat megtartotta s cselekedte azokat: élvén éljen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 20, 'A mely lélek vétkezik, annak kell meghalni; a fiú ne viselje az apa vétkét, se az apa ne viselje a fiú vétkét; az igazon legyen az ő igazsága, és a gonoszon az ő gonoszsága.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 21, 'És ha a gonosztevő megtér minden vétkéből, melyeket cselekedett, és megtartja minden parancsolatimat, és törvény szerint és igazságot cselekszik: élvén éljen, és meg ne haljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 22, 'Semmi gonoszságáról, melyet cselekedett, emlékezés nem lészen; az ő igazságáért, melyet cselekedett, élni fog.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 23, 'Hát kivánva kivánom én a gonosznak halálát? ezt mondja az Úr Isten! nem inkább azt, hogy megtérjen útjáról és éljen?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 24, 'És ha az igaz elhajol az ő igazságától, és gonoszságot cselekszik, minden útálatosság szerint, melyeket a hitetlen cselekedett, cselekeszik, nemde éljen-é? Semmi igazságairól, a melyeket cselekedett, emlékezés nem lészen: gonoszságáért, melyet cselekedett, és az ő vétkéért, melylyel vétkezett, ezekért meg kell halnia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 25, 'És azt mondjátok: Nem igazságos az Úrnak útja! Oh, halljátok meg, Izráel háza: az én útam nem igazságos-é? nem inkább a ti útaitok nem igazságosak-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 26, 'Ha elhajol az igaz az ő igazságától, és gonoszságot cselekszik, és a miatt meghal: gonoszsága miatt hal meg, melyet cselekedett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 27, 'És ha a gonosztevő megtér az ő gonoszságától, melyet cselekedett, és törvény szerint és igazságot cselekszik: ez az ő lelkét megtartja életben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 28, 'Mert belátta és megtért minden gonoszságától, melyeket cselekedett: élvén éljen, ne haljon meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 29, 'És azt mondja az Izráel háza: Nem igazságos az Úrnak útja! Az én útaim nem igazságosak-é, Izráel háza? nem inkább a ti útaitok nem igazságosak-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 30, 'Ennekokáért mindeniteket az ő útai szerint ítélem, Izráel háza, ezt mondja az Úr Isten. Térjetek meg és forduljatok el minden vétkeitektől, hogy romlástokra ne legyen gonoszságotok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 31, 'Vessétek el magatoktól minden vétkeiteket, melyekkel vétkeztetek, és szerezzetek magatoknak új szívet és új lelket; Miért halnátok meg, oh Izráel háza!?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 32, 'Mert nem gyönyörködöm a meghaló halálában, ezt mondja az Úr Isten. Térjetek meg azért és éljetek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 1, 'Te pedig kezdj gyászéneket Izráel fejedelmeiről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 2, 'És mondjad: Mi volt anyád? Nőstény oroszlán; oroszlánok közt fekszik vala, fiatal oroszlánok között nevelé fel kölykeit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 3, 'És fölnevele egyet kölykei közül; fiatal oroszlánná lőn, és megtanula ragadományt ragadozni, embereket evett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 4, 'És meghallák ezt róla a népek; vermökben megfogaték, és elvivék őt horgokon Égyiptom földjére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 5, 'És mikor látta, hogy késik, hogy oda veszett reménysége, vőn egyet kölykei közül, ezt tevé fiatal oroszlánná.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 6, 'És ez jár vala az oroszlánok között, fiatal oroszlánná lőn, és megtanula ragadományt ragadozni, embereket evett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 7, 'És ismeré az ő özvegyeiket s városaikat elpusztítá, és megrettene a föld és annak teljessége, ordítása hangjától.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 8, 'És veték ellene a pogányok köröskörül a tartományokból és kiteríték reá hálójukat, vermökben megfogaték;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 9, 'És veték őt ketreczbe horgokon, s elvivék őt Babilon királyához, elvivék őt várakba, hogy többé ne hallassék szava Izráel hegyein.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 10, 'Anyád a te nyugalmadban olyan vala, mint a víz mellé ültetett szőlőtő, gyümölcscsel és vesszővel bővelkedik vala a sok víztől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 11, 'És lőnek néki erős vesszei, uralkodók pálczáinak valók, és nagy vala magassága a sűrűség között és felett, és kitetszék magasságával és vesszeinek sokaságával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 12, 'De kiszaggattaték Isten haragja által, a földre vetteték, és a napkeleti szél elszárasztá gyümölcsét; letöretének és elszáradának erős ágai; tűz emészté meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 13, 'És most a pusztában plántáltatott, száraz és szomjú földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 14, 'És tűz jött ki ágainak egyik vesszejéből, gyümölcsét megemészté, és nincs többé rajta erős vessző, nincs pálcza az uralkodásra! Gyászének ez és gyászének lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 1, 'És lőn a hetedik esztendőben, az ötödik hónap tizedikén: jövének férfiak Izráel vénei közül megkérdezni az Urat, és leülének előttem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 2, 'És lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 3, 'Embernek fia! beszélj Izráel véneivel, és mondjad nékik: Így szól az Úr Isten: Nemde engem megkérdezni jöttetek-é? Élek én, hogy nem engedem, hogy megkérdezzetek engem, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 4, 'Ítélni akarod őket, ítélni akarsz, embernek fia? add tudtokra atyáik útálatosságait!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 5, 'És mondjad nékik: Így szól az Úr Isten: Azon a napon, melyen elválasztám Izráelt, és fölemelém kezemet a Jákób háza magvának, és megismertetém magamat velök Égyiptom földjén, és kezemet fölemelém nékik, mondván: Én vagyok az Úr, a ti Istentek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 6, 'Azon a napon felemeltem kezemet nékik, hogy kihozzam őket Égyiptom földjéről a földre, a melyet kinéztem vala nékik, a mely téjjel és mézzel folyó, ékessége az minden tartománynak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 7, 'És mondék nékik: Kiki az ő szemei útálatosságait elvesse, és Égyiptom bálványaival meg ne fertéztessétek magatokat; én vagyok az Úr, a ti Istentek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 8, 'De pártot ütének ellenem, s nem akarának hallgatni reám. Senki az ő szeme útálatosságait el nem veté és Égyiptom bálványait el nem hagyá. Mondám azért, hogy kiöntöm búsulásomat rájok, teljessé teszem haragomat rajtok Égyiptom földjének közepette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 9, 'De cselekedtem az én nevemért, hogy ez meg ne gyaláztassék a pogányok szemei előtt, a kik közt ők valának, a kiknek szemei előtt megismertettem magamat velök, hogy kihozom őket Égyiptom földjéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 10, 'És kihozám őket Égyiptom földjéről, s vivém őket a pusztába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 11, 'És adám nékik parancsolatimat, és törvényeimet kijelentém nékik, melyeket az ember ha cselekszik, él azok által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 12, 'És adám nékik szombataimat is, hogy legyenek jegyül köztem és ő közöttök; hogy megtudják, hogy én vagyok az Úr, az ő megszentelőjök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 13, 'De pártot üte ellenem Izráel háza a pusztában, az én parancsolatimban nem jártak és törvényeimet megveték, a melyeket az ember ha cselekszik, él azok által; és az én szombataimat megfertéztették felette igen. Mondám azért, hogy kiöntöm búsulásomat rájok a pusztában, hogy elveszessem őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 14, 'De cselekedtem az én nevemért, hogy meg ne gyaláztassék a pogányok szemei előtt, a kiknek szeme láttára kihoztam vala őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 15, 'És föl is emelém én kezemet nékik a pusztában, hogy be nem viszem őket a földre, melyet adtam nékik, mely téjjel és mézzel folyó, ékessége az minden tartománynak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 16, 'Mivelhogy törvényeimet megvetették és parancsolataimban nem jártak, és szombataimat megfertéztették, mert bálványaik után járt vala szívök:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 17, 'Mindazáltal kedvezett szemem nékik, hogy el ne veszessem őket, és nem vetettem nékik véget a pusztában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 18, 'És mondék fiaiknak a pusztában: A ti atyáitok parancsolataiban ne járjatok, és az ő törvényeiket meg ne tartsátok, s bálványaikkal magatokat meg ne fertéztessétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 19, 'Én vagyok a ti Uratok, Istentek: az én parancsolatimban járjatok, az én törvényimet tartsátok meg, és azokat cselekedjétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 20, 'És az én szombatimat megszenteljétek, hogy legyenek jegyül én köztem és tiköztetek, hogy megtudjátok, hogy én vagyok az Úr, a ti Istenetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 21, 'De pártot ütének a fiak ellenem, parancsolataimban nem jártak, s törvényeimet meg nem tartották, hogy azokat cselekedjék, a melyeket az ember ha cselekszik, él azok által; szombataimat megfertéztették; mondám azért, hogy kiöntöm búsulásomat rájok, teljessé teszem haragomat rajtok a pusztában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 22, 'De visszavontam kezemet, s cselekedtem az én nevemért, hogy meg ne gyaláztassék a pogányok előtt, a kiknek szeme láttára kihoztam őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 23, 'Föl is emelém én kezemet nékik a pusztában, hogy elszélesztem őket a pogányok közé, és szétszórom őket a tartományokba;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 24, 'Mivelhogy törvényeimet nem cselekedték, s parancsolataimat megvetették, és szombataimat megfertéztették, s atyáik bálványai után voltak szemeik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 25, 'És én is adtam nékik nem jó parancsolatokat, s törvényeket, a melyek által ne éljenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 26, 'S megfertéztetém őket ajándékaikkal, mikor tűzön vittek át minden elsőszülöttet, hogy elpusztítsam őket, hogy megtudják, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 27, 'Azért szólj az Izráel házának, embernek fia, és mondjad nékik: Így szól az Úr Isten: Még ebben is gyalázattal illettek engem a ti atyáitok, hogy hűtlenül elszakadának tőlem:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 28, 'Mikor bevittem őket a földre, a melyért fölemeltem kezemet, hogy azt nékik adom, megtekintének minden magas halmot és minden sűrű ágú fát, és ott áldozzák vala az ő áldozatjaikat, és ott adják vala haragra ingerlő ajándékaikat; és oda teszik vala kedvelt illatjokat, és oda öntik vala italáldozataikat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 29, 'És mondék nékik: Micsoda e magaslat, a hova ti gyülekeztek? És nevezik nevét magaslatnak mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 30, 'Ennekokáért mondjad Izráel házának: Így szól az Úr Isten: Nemde a ti atyáitok módjára fertéztetitek-é meg magatokat, és az ő útálatosságaik szerint paráználkodtok-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 31, 'És ajándékaitok vitelével, mikor átviszitek fiaitokat a tűzön, fertéztetitek meg magatokat minden bálványaitok előtt mind e mai napig, és én engedjem, hogy megkérdezzetek engem, Izráel háza? Élek én, ezt mondja az Úr Isten, hogy nem engedem, hogy megkérdezzetek engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 32, 'És a mi lelketekben támadt, semmiképpen sem lesz meg, hogy azt mondjátok: Leszünk olyanok, mint a pogányok, mint a tartományok nemzetségei, szolgálván fának és kőnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 33, 'Élek én, ezt mondja az Úr Isten, hogy erős kézzel és kinyújtott karral és kiontott búsulással uralkodom rajtatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 34, 'És kiviszlek titeket a népek közül, és egybegyűjtelek titeket a tartományokból, melyekbe elszéledtetek, erős kézzel és kinyújtott karral és kiontott búsulással;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 35, 'És vezetlek titeket a népek pusztájára, hol szemtől-szembe törvénykezem veletek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 36, 'A mint törvénykeztem a ti atyáitokkal Égyiptom földének pusztájában; úgy törvénykezem veletek, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 37, 'És átviszlek titeket a vessző alatt, és hozlak titeket a frigynek kötelébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 38, 'És kitisztítom közületek a pártosokat, és az ellenem támadókat, és a földről, melyen jövevények voltak, kihozom őket, de Izráel földjére nem fognak bemenni, hogy megtudjátok, hogy én vagyok az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 39, 'Ti pedig, Izráel háza, azt mondja az Úr Isten, mindenitek járjon az ő bálványai után és szolgáljon azoknak; de azután bizony, hallgatni fogtok rám, és az én szent nevemet többé meg nem fertéztetitek ajándékitokkal és bálványaitokkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 40, 'Mert az én szent hegyemen, Izráelnek magas hegyén, ezt mondja az Úr Isten, ott fog szolgálni nékem Izráel egész háza együtt azon a földön; ott kedvelem őket, ott kivánom meg a ti áldozataitokat és ajándékitoknak első zsengéjét mindenben, mit nékem szenteltek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 41, 'Kedves illatban kedvellek titeket, mikor kihozlak titeket a népek közül és egybegyűjtelek titeket a tartományokból, melyeken elszéledtetek, és megszenteltetem ti bennetek a pogányok szemei előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 42, 'És megtudjátok, hogy én vagyok az Úr, mikor beviszlek titeket Izráel földjére, arra a földre, melyért fölemeltem kezemet, hogy adom azt a ti atyáitoknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 43, 'És ott megemlékeztek útaitokról, s minden cselekedeteitekről, melyekkel magatokat megfertéztettétek, s megútáljátok ti magatokat minden gonoszságtokért, melyeket cselekedtetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 44, 'És megtudjátok, hogy én vagyok az Úr, mikor cselekszem veletek az én nevemért, és nem a ti gonosz útaitok és romlott cselekedeteitek szerint, oh Izráel háza, ezt mondja az Úr Isten! És lőn az Úrnak beszéde hozzám, mondván: Embernek fia! fordítsd orczádat délre, és szólj dél felé és prófétálj a déli mező erdeje ellen! És mondjad a dél erdejének: Halld meg az Úr beszédét, így szól az Úr Isten: Ímé, én tüzet gyújtok benned, hogy megemészszen te benned minden zöldelő és minden aszú fát. Meg nem aluszik a lángoló láng, és megég a miatt minden orcza déltől északig. És meglátja minden test, hogy én, az Úr gyújtottam meg azt, mert meg nem aluszik. És mondék: Ah, ah, Uram Isten! ezek azt mondják nékem: Hát nem példabeszédekben beszél ez?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 1, 'És lőn az Úrnak beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 2, 'Embernek fia! fordítsd arczodat Jeruzsálem felé, és szólj a szent helyek ellen és prófétálj Izráel földje ellen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 3, 'És mondjad Izráel földjének: Így szól az Úr: Ímé, én reád megyek, és kivonszom kardomat hüvelyéből, és kivágok belőled igazat és gonoszt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 4, 'Azért, hogy kivágjak belőled igazat és gonoszt, azért megyen ki kardom hüvelyéből minden test ellen délről északig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 5, 'És megérti minden test, hogy én, az Úr vontam ki kardomat hüvelyéből, mert belé többé vissza nem tér.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 6, 'És te, embernek fia, nyögj! Derekad fájdalmában keserűséggel nyögj szemök láttára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 7, 'És lészen, mikor mondják néked: Miért nyögsz te? ezt mondjad: A hírért, mert beteljesedett: és elolvad minden szív és elerőtlenedik minden kéz és elcsügged minden lélek és minden térd elolvad mint a víz. Ímé beteljesedett és meglett, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 8, 'És lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 9, 'Embernek fia! prófétálj és mondjad: Ezt mondta az Úr: Mondjad: fegyver, fegyver! megélesített és meg is fényesített!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 10, 'Hogy öldököljön, megélesíttetett, hogy legyen villámlása, megfényesíttetett. Avagy örüljünk-é? Fiam e veszszeje megvet minden fát!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 11, 'És adta azt megfényesítésre, hogy marokba fogják; megélesíttetett az a kard s megfényesíttetett, hogy adják a megölőnek kezébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 12, 'Kiálts és jajgass, embernek fia! mert ez az én népemen lészen és Izráel minden fejedelmin: e kardra jutnak népemmel együtt, ezokért üss czombodra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 13, 'Már megpróbáltatott. De hát ha a vessző maga is vonakodnék? Nem úgy lészen, ezt mondja az Úr Isten!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 14, 'Te pedig, embernek fia, prófétálj, és csapd össze tenyeredet, mert kettős lesz a kard, most harmadszor; öldöklő kard az, a nagy öldöklő kard körüljárja őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 15, 'Hogy elolvadjon a szív és sokan elhulljanak: minden kapujokban rájok vetem a kard villámlását, hisz villámlásra készült, öldöklésre kifényesíttetett!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 16, 'Szedd össze magadat; tarts jobbra, tarts előre, tarts balra, a merre éled irányozva van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 17, 'Én is összecsapom tenyeremet, és megnyugotom haragomat. Én, az Úr szólottam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 18, 'És lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 19, 'És te, embernek fia, csinálj magadnak két útat, a melyen jőjjön a babiloni király kardja; egy földről jőjjön ki mind a kettő; s egy kezet véss föl, a városba vezető út fejénél vésd föl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 20, 'Útat csinálj, hogy jőjjön a kard az Ammon fiainak Rabbájára, aztán Júdára, a körülkerített Jeruzsálemre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 21, 'Mert megáll a babiloni király az útak kezdetén, a két út fejénél, hogy jövendőt láttasson; megrázza a nyilakat, megkérdezi a Teráfimot, megnézi a májat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 22, 'Jobbjába adta a jövendölés Jeruzsálemet, hogy állasson faltörő kosokat, hogy nyissa száját ordításra, hogy üssön zajt trombitával, hogy állasson faltörő kosokat a kapuk ellen, hogy töltsön sánczot, építsen tornyot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 23, 'De ez nékik hamis jövendölésnek látszik: szent esküik vannak nékik Istentől; ám Ő emlékezetbe hozza vétköket, hogy megfogassanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 24, 'Ezokáért ezt mondja az Úr Isten: Mivelhogy emlékezetbe hozzátok vétketeket, midőn nyilvánvalókká lesznek gonoszságaitok, hogy megláttassanak bűneitek minden cselekedeteitekben; mivelhogy eszembe juttok, kézzel megfogattok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 25, 'És te elvetemedett, te gonosztevő, Izráel fejedelme, a kinek napja eljött az utolsó vétek idején:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 26, 'Így szól az Úr Isten: El a süveggel, le a koronával! Ez nem lészen ez: az alacsony legyen magas, és a magas alacsony!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 27, 'Rommá, rommá, rommá teszem azt; ez sem lesz állandó, míg el nem jő az, a kié az uralkodás, és néki adom azt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 28, 'És te, embernek fia, prófétálj, és mondjad: Ezt mondja az Úr Isten Ammon fiairól és gyalázkodásukról, és mondjad: Fegyver, fegyver, öldöklésre kivont, megfényesíttetett, hogy ragyogjon, azért, hogy villámljék;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 29, 'De mivel felőled hiábavalóságot látnak, hazugságot jövendölnek, hogy odatesznek téged a megölt gonoszok nyakára, a kiknek napjok eljött az utolsó vétek idején:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 30, 'Tedd vissza hüvelyébe azt; a helyen, melyen teremtettél, származásod földjén ítéllek meg téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 31, 'És kiontom reád haragomat, búsulásom tüzét fúvom reád, és adlak goromba férfiak kezébe, kik mesterek, téged elveszteni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 32, 'A tűz eledele leszel; véredet benyeli a föld; emlékezetbe nem jösz többé, mert én, az Úr szóltam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 33, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 34, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 35, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 36, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 37, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 1, 'És lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 2, 'És te, embernek fia, ítélni akarsz? meg akarod-é ítélni a vérontó várost? add tudtára minden útálatosságait,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 3, 'És mondjad: Így szólt az Úr Isten: Te város, ki közepében vért ontott, hogy eljőjjön ideje, és bálványokat csinált magának önmaga megfertéztetésére;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 4, 'Véred miatt, melyet ontottál, lettél bűnös, és bálványaiddal, melyeket csináltál, fertéztetted meg magadat, s közelebb hoztad napjaidat s eljutottál esztendeidig; azért adlak gyalázatul a pogányoknak, és csúfolásul minden tartománynak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 5, 'A kik közel s távol vannak tőled, megcsúfolnak téged, te fertézett nevű, sok háborúságú!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 6, 'Ímé, Izráel fejedelmei, kiki az ő tehetsége szerint azon volt benned, hogy vért ontsanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 7, 'Apát és anyát megútáltak te benned, a jövevényen nyomorgatást cselekedtek te közepetted, árvát és özvegyet sanyargattak benned.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 8, 'A mi nékem szenteltetett, megútáltad, s szombatimat megfertéztetted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 9, 'Rágalmazók voltak benned, hogy vért ontsanak, s a hegyeken ettek benned, fajtalanságot cselekedtek közepetted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 10, 'Az atya szemérmét föltakarták benned, a havivér miatt tisztátalant erőszakolták benned.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 11, 'Egyik felebarátjának feleségével cselekedett útálatosságot, a másik meg menyét fertéztette meg fajtalanságban, s volt, a ki húgát, atyjának leányát erőszakolta benned.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 12, 'Ajándékokat vettek fel benned a vérontásra, uzsorát és kamatot szedtél, s nyerekedtél felebarátaidon csalárdsággal, s én rólam elfelejtkeztél, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 13, 'És ímé, összecsapom tenyeremet nyereségeden, a melyet csináltál, és a vérontásokon, melyek lőnek te benned.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 14, 'Vajjon megállhat-é szíved, avagy erősek lesznek-é kezeid azokban a napokban, mikor én számolok veled? Én, az Úr, szólottam és meg is cselekszem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 15, 'És eloszlatlak téged a pogányok közé, és szétszórlak a tartományokba, s véget vetek tisztátalanságodnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 16, 'S örökségül bírlak téged a pogányok szeme láttára, és megtudod, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 17, 'És lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 18, 'Embernek fia! Izráel háza salakká lett nékem; egészen réz és ón és vas és ólom a kemencze közepette; ezüstsalakká lettek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 19, 'Ennekokáért így szól az Úr Isten. Mivelhogy mindnyájan salakká lettetek, azért ímé, egybegyűjtelek titeket Jeruzsálem közepébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 20, 'A mint egybe szoktak gyűjteni ezüstöt és rezet és vasat és ólmot és ónt a kemencze közepébe, hogy tüzet gerjeszszenek rá a megolvasztásra; így gyűjtelek egybe búsulásomban és haragomban, és bevetlek s megolvasztlak titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 21, 'És egybegyűjtelek titeket, és rátok fúvom búsulásom tüzét, hogy benne megolvadjatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 22, 'A mint megolvad az ezüst a kemencze közepében, úgy olvadtok meg ő benne, és megtudjátok, hogy én, az Úr öntöttem ki haragomat reátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 23, 'És lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 24, 'Embernek fia! mondjad néki: Te vagy a föld, mely meg nem tisztult; esőt nem kapott a haragnak napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 25, 'Pártosok az ő prófétái ő közepette; olyanok, mint az ordító oroszlán, mely ragadományt ragad: lelkeket ettek, kincset és drágaságot elvesznek, özvegyeit megsokasítják őbenne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 26, 'Papjai erőszakot tettek törvényemen, s megfertéztették, a mi nékem szenteltetett! különbséget nem tettek a között, a mi szent és a mi köz, s a tisztátalan és tiszta között különbséget nem tanítottak, s szombataimtól elrejtették szemeiket, úgyhogy megszentségtelenítettek engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 27, 'Előljárói ő közepette mint a ragadományt ragadozó farkasok: vért ontani, a lelkeket elveszteni, hogy nyerekedhessenek nyereséggel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 28, 'És prófétái mázolnak nékik mázzal: hiábavalóságot látnak s jövendölnek hazugságot nékik, mondván: Így szól az Úr Isten! holott az Úr nem beszélt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 29, 'A föld népe nyomorgatást cselekszik és ragadományt ragadoz, a szűkölködőt és szegényt sanyargatja, s a jövevényt törvénytelen nyomorgatja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 30, 'És keresék közülök valakit, a ki falat falazna, és állana a törésen én előmbe az országért, hogy el ne pusztítsam azt; de senkit nem találék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 31, 'Ennekokáért kiontám haragomat reájok, megemésztém őket búsulásom tüzével, útjokat fejökhöz verém, azt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 1, 'És lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 2, 'Embernek fia! Volt két asszony, egy anyának leányai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 3, 'És paráználkodának Égyiptomban, ifjúságukban paráználkodtak; ott szorongatták emlőjüket, ott nyomogatták szűzi keblöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 4, 'És nevök: Oholá a nagyobbik, és húga Oholibá; és lőnek enyimekké, és szülének fiakat és leányokat. A mi pedig a nevöket illeti: Samaria az Oholá és Jeruzsálem az Oholibá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 5, 'És paráználkodék Oholá oldalamon, és fölgerjede szeretőihez, a közeli Assiriabeliekhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 6, 'Kik kék bíborba öltözöttek, helytartók és fejedelmek, kívánatos ifjak mindnyájan, lovagok, lovakon ülők.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 7, 'És nékik adá magát paráznaságaiban Assiria válogatott ifjainak; és mindazoknál, kikhez felgerjede, minden ő bálványaikkal megfertézteté magát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 8, 'De az Égyiptombeliektől való paráznaságait is el nem hagyá, mert vele háltak ifjúságában, s ők nyomogatták szűzi kebelét, és kiöntötték ő reá paráznaságukat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 9, 'Ennekokáért adtam őt szeretőinek kezébe, Assiria fiainak kezébe, kikhez fölgerjedett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 10, 'Azok feltakarák szemérmét, fiait és leányit elvivék s magát fegyverrel ölék meg, úgy hogy híre-neve lőn az asszonyoknál, s ítéletet cselekedének rajta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 11, 'És látá húga, Oholibá, és még gonoszabbul folytatá bujálkodását amannál, és paráznaságait nénje paráználkodásainál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 12, 'Assiria fiaihoz fölgerjedt, közeli helytartókhoz s fejedelmekhez, teljes szépségben öltözőkhöz, lovagokhoz, lovakon ülőkhöz, kik mindnyájan kivánatos ifjak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 13, 'És látám, hogy megfertéztette magát: egy az útjok kettőjöknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 14, 'És még szaporítá paráznaságait, és láta férfiakat bevésve a falon, a Káldeusok képeit, bevésve vörös festékkel,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 15, 'Kik övet viseltek derekukon, csomós süvegeket fejükön, olyanok mind, mint a szekérről harczolók, hasonlók Bábel fiaihoz, kiknek szülőföldje Káldea;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 16, 'És fölgerjedt hozzájok szemei nézésében, s bocsáta követeket hozzájok Káldeába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 17, 'És eljövének ő hozzá Bábel fiai a szerelem ágyasházába, s megfertézteték őt paráznaságukkal, úgyhogy tisztátalan lett miattok; s ekkor lelke eltávozék tőlök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 18, 'És mikor feltakarta paráznaságait és feltakarta szemérmét, eltávozék az én lelkem ő tőle, a mint az ő nénjétől lelkem eltávozott vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 19, 'És megsokasítá paráznaságait, megemlékezvén ifjúságának napjairól, mikor Égyiptom földjén paráználkodott;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 20, 'És fölgerjede azok bujálkodóihoz, kiknek teste olyan, mint a szamarak teste, és folyásuk, mint lovak folyása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 21, 'És megemlékezél ifjúságod fajtalankodására, mikor ők, az égyiptomiak, nyomogatták kebledet, hogy szorongassák ifjúságod emlőit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 22, 'Ennekokáért Oholibá, így szól az Úr Isten: Ímé, én feltámasztom a te szeretőidet ellened, kiktől pedig eltávozott lelked, s reád hozom őket mindenfelől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 23, 'Babilon fiait és minden Káldeabelit, Pekódot és Soát és Koát, Assiria minden fiát ő velük, kívánatos ifjakat, helytartókat s fejedelmeket, mindnyájokat, szekérről harczolókat s előkelőket, és lovakon ülőket, mindnyájokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 24, 'És jőnek reád szekereknek és kerekeknek tömegével s népek sokaságával, nagy és kis paizszsal és sisakkal körülvesznek téged mindenfelől, s adok nékik hatalmat az ítéletre, s megítélnek téged az ő ítéletök szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 25, 'És megmutatom rajtad féltő szerelmemet, s cselekszenek veled kegyetlenül; orrodat s füleidet elmetélik, s maradékod fegyver miatt hull el; ők fiaidat és leányaidat elviszik, s maradékodat tűz emészti meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 26, 'S megfosztanak ruháidtól, és elveszik ékességeidet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 27, 'És véget vetek fajtalanságodnak s Égyiptom földjéről való paráznaságodnak, s nem emeled föl szemeidet rájok, s Égyiptomra nem emlékezel többé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 28, 'Mert így szól az Úr Isten: Ímé, én adlak téged azoknak kezébe, a kiket gyűlölsz, azoknak kezébe, a kiktől eltávozott lelked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 29, 'És gyűlölséggel cselekesznek veled, és mindent, mit kerestél, elvesznek tőled, és mezítelen s ruhátalan hagynak, hogy feltakartassék paráznaságaid szemérme. És fajtalanságod s paráználkodásaid');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 30, 'Hozták ezeket reád; mivelhogy paráználkodtál a pogányok után, mert megfertéztetted magad azok bálványaival.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 31, 'Nénéd útján jártál, azért az ő poharát adom kezedbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 32, 'Így szól az Úr Isten: Nénéd poharát megiszod, mely mély és széles; leszen nevetségedre s csúfoltatásodra, hogy sok fér bele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 33, 'Részegséggel és bánattal megtelsz; pusztaság és elpusztulás pohara a te nénéd, Samaria pohara!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 34, 'Meg kell innod azt s fenékig hajtanod; és cserepein rágódni fogsz, emlőidet megszaggatod azokon, mert én szólottam, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 35, 'Ennekokáért ezt mondja az Úr Isten: Mivelhogy elfelejtkeztél én rólam s hátad mögé vetettél engemet, te is hordozd fajtalanságodat és paráznaságaidat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 36, 'És monda az Úr nékem: Embernek fia! avagy nem ítéled-é Oholát és Oholibát? Hirdesd nékik útálatosságaikat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 37, 'Mert házasságot törtek, és vér van kezeiken, és bálványaikkal törtek házasságot, és fiaikat is, kiket szültek vala nékem, tűzben nékik áldozák azok eledeléül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 38, 'Sőt ezt is cselekedték velem: megfertézteték az én szent helyemet azon a napon, és szombatimat megszentségteleníték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 39, 'És mikor megölték fiaikat az ő bálványaiknak, bemenének az én szenthelyembe azon a napon, hogy megszentségtelenítsék, és ímé, így cselekedtek az én házamban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 40, 'Sőt elküldöttek messzünnen jövő emberekhez, kikhez követség küldetett, és ímé eljövének, a kiknek kedvéért megmosódál, kendőzéd szemeidet, és fölékesítéd magad ékességgel;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 41, 'És ültél pompás kerevetre, s terített asztal vala az előtt, és az én füstölő szeremet és olajomat arra tevéd;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 42, 'És lőn ott örvendező sokaságnak zaja. És küldöttek az emberek sokaságából való férfiakhoz, hozatának ivótársakat a pusztából; és ezek adának karpereczeket az ő kezeikre és ékes koronát fejökre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 43, 'És mondék: Még az elaggott is házasságot tör? most már paráznaságod fog paráználkodni, és úgy lőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 44, 'És bemenének hozzá, mint a hogy a parázna asszonyhoz bemennek; így mentek be Oholához és Oholibához, e fajtalan asszonyokhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 45, 'És igaz férfiak, ezek ítélik meg őket a házasságtörők, és vérontók ítéletével, mert házasságtörők és vér van kezeiken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 46, 'Mert így szól az Úr Isten: Hozzanak rájok gyülekezetet, és adják őket bántalmazásra és ragadományra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 47, 'És kövezze meg őket a gyülekezet, és vagdalják össze őket fegyvereikkel; fiaikat és leányaikat öljék meg, és házaikat tűzzel égessék meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 48, 'És megszüntetem a fajtalanságot a földről, és tanul minden asszony, és nem cselekesznek a ti fajtalanságotok szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 49, 'És reátok vetik fajtalanságotokat, s bálványaitok vétkeit viselitek, és megtudjátok, hogy én vagyok az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 1, 'És lőn az Úr beszéde hozzám a kilenczedik esztendőben, a tizedik hónapban, a hónapnak tizedikén, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 2, 'Embernek fia! írd fel magadnak e nap nevét, épen ezen napét: Babilon királya épen ezen a napon jött Jeruzsálemre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 3, 'És mondj példabeszédet a pártos házra, és mondjad nékik: Ezt mondja az Úr Isten: Tedd föl a fazekat, tedd föl, és tölts vizet is bele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 4, 'Gyűjtsd össze a bele való darabokat, minden jó darabot, czombot, lapoczkát; válogatott csontokkal töltsd meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 5, 'Végy válogatott juhokat, és tégy máglyát a csontoknak is a fazék alá; forrald erősen, még csontjai is főjjenek benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 6, 'Ezokáért így szól az Úr Isten: Jaj a vérontó városnak, a fazéknak, a melynek rozsdája benne van, és rozsdája nem ment le róla! Darabról darabra szedd ki, a mi benne van: nem esett sors reá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 7, 'Mert vére ott van közepében, kopasz sziklára ontotta, nem a földre öntötte, hogy por fedje be.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 8, 'Hogy haragomat felindítsam és bosszút álljak, kopasz sziklára ontottam vérét, hogy be ne fedeztessék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 9, 'Azért így szól az Úr Isten: Jaj a vérontó városnak! én is nagy máglyát rakok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 10, 'Bőven rakd a fát, gyújtsd meg a tüzet, főzd meg jól a húst, forrald a levet, és a csontok szétfőjjenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 11, 'És állítsd üresen az ő szenére, hogy meghevüljön s megtüzesedjék ércze, és megolvadjon benne tisztátalansága, megemésztessék rozsdája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 12, 'A fáradozásokat kifárasztotta, és nem ment le róla az ő sok rozsdája, tűzbe hát rozsdájával!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 13, 'A te tisztátalanságodban fajtalanság van, mivelhogy tisztogattalak, de meg nem tisztultál, azért tisztátalanságodból többé meg nem tisztulsz, míg meg nem nyugotom haragomat rajtad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 14, 'Én, az Úr szólottam; jőni fog és megcselekszem, el nem engedem s nem kedvezek és nem könyörülök: a te útaid és cselekedeteid szerint ítélnek meg téged, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 15, 'És lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 16, 'Embernek fia! ímé, én elveszem tőled szemeidnek gyönyörűségét hirtelen halállal, és ne sírj és ne jajgass, se könyed ne hulljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 17, 'Fohászkodjál csöndesen, halottakért való sírást ne tégy, fejékességedet kösd fel, és saruidat vedd lábaidra, s ne fedezd be bajuszodat, és az emberek kenyerét ne egyed.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 18, 'És szólék reggel a néphez, és estére meghala feleségem, és úgy cselekedém reggel, a mint meg vala hagyva nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 19, 'És mondá nékem a nép: Avagy nem jelented-é meg nékünk, mit jelentenek ezek nékünk, hogy te így cselekszel?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 20, 'És mondék nékik: Az Úr beszéde volt én hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 21, 'Mondd meg az Izráel házának: Ezt mondja az Úr Isten: Ímé, én megfertéztetem szenthelyemet, a ti erősségteknek kevélységét, szemeitek gyönyörűségét, lelketek kívánságát, és fiaitok és leányaitok, kiket hátrahagytatok, fegyver miatt hullnak el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 22, 'És úgy cselekesztek, a mint én cselekedtem: bajuszotokat be nem fedezitek, s az emberek kenyerét nem eszitek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 23, 'S fejékességtek fejeteken, és saruitok lábaitokon lesznek; nem sírtok s nem jajgattok, hanem megrothadtok vétkeitekben, s nyögve fohászkodtok egymáshoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 24, 'És lészen néktek Ezékiel csodajelül: a mint ő cselekedett, egészen úgy cselekesztek ti is, mikor ez eljő; és megtudjátok, hogy én vagyok az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 25, 'És te, embernek fia, bizonyára azon a napon, mikor elveszem tőlök erősségöket, dicsőségök örömét, szemeik gyönyörűségét és lelkök kívánságát, fiaikat és leányaikat:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 26, 'Azon a napon, a ki megmenekült, eljő hozzád, hogy hírt mondjon néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 27, 'Azon a napon megnyílik szád ott a megmenekült előtt, és szólasz és tovább nem maradsz néma; s leszel nékik csodajelül, és megtudják, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 1, 'És lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 2, 'Embernek fia! vesd tekintetedet Ammon fiaira, és prófétálj ellenök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 3, 'És mondjad Ammon fiainak: Halljátok az Úr Isten beszédét! így szól az Úr Isten: Mivelhogy ezt mondod: Haha! az én szenthelyemre, hogy megfertéztetett; és Izráel földjére, hogy elpusztíttatott; és Júda házára, hogy fogságba mentek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 4, 'Ezokáért ímé adlak téged Kelet fiainak örökségül, hogy felüssék sátraikat benned, s felállassák benned lakóhelyeiket, ők eszik meg gyümölcsödet, s ők iszszák meg tejedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 5, 'És teszem Rabbát tevék legelőjévé, és Ammon fiait nyájak fekvőhelyévé, s megtudjátok, hogy én vagyok az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 6, 'Mert így szól az Úr Isten: Mivelhogy tapsolsz kezeddel és tombolsz lábaddal és örülsz teljes megvetéssel lelkedben Izráel földje felett:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 7, 'Ennekokáért ímé kinyújtom kezemet reád, s adlak ragadományul a népeknek, és kiváglak a népségek közül, és elvesztlek a tartományok közül, eltöröllek, hogy megtudjad, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 8, 'Azt mondja az Úr Isten: Mivelhogy Moáb és Seir ezt mondta: Ímé, Júda háza is olyan, mint a többi népek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 9, 'Ezokáért ímé megnyitom Moáb oldalát a városok felől, az ő városai felől mindenfelől, az ország ékességét Beth-Hajesimóthot, Baál-Meont és Kirjátaim felé,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 10, 'Megnyitom Kelet fiainak, Ammon fiaival együtt adom örökségül, hogy emlékezetben se legyenek többé Ammon fiai a népek között;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 11, 'Moáb fölött is ítéletet tartok: hogy megtudják, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 12, 'Így szól az Úr Isten: Mivelhogy Edom kegyetlen bosszúállást cselekedett Júda házán, és vétkezve vétkezett, hogy bosszút állott rajta:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 13, 'Azért, így szól az Úr Isten, kinyújtom az én kezemet Edomra, és kivágok belőle embert és barmot, és teszem őt pusztasággá Temántól fogva, és Dedánig fegyver miatt hulljanak el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 14, 'És bosszúmat állom Edomon népemnek, Izráelnek keze által és cselekszenek Edommal az én búsulásom és haragom szerint, s megismerik bosszúállásomat, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 15, 'Így szól az Úr Isten: Mivelhogy a Filiszteusok bosszúból cselekedtek s kegyetlen bosszút álltak lelkökben megvetéssel, hogy elveszessék Izráelt örök gyűlölséggel:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 16, 'Ezokáért ezt mondja az Úr Isten: Ímé, én kinyújtom kezemet a Filiszteusokra, és kivágom a Keréteusokat, és elvesztem a tenger partján lakók maradékát;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 17, 'És cselekszem rajtok nagy bosszúállásokat fenyítő haragomban, hogy megtudják, hogy én vagyok az Úr, ha bosszúmat állom rajtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 1, 'És lőn a tizenegyedik esztendőben, a hónap elsején, lőn az Úrnak beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 2, 'Embernek fia! mivelhogy ezt mondá Tírus Jeruzsálemre: Haha! eltört a népek kapuja, felém fordulva nyitva van; én megtelek, ha ő elpusztul;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 3, 'Ezokáért így szól az Úr Isten: Ímé én, Tírus, te reád megyek, és hozok fel ellened sok nemzetet, miként a tenger fölhozza hullámit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 4, 'És elhányják Tírus kőfalait és lerontják tornyait, s levonszom még porát is róla, s kopasz sziklává teszem őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 5, 'Hálók kivető helye lesz a tenger közepén, mert én szólottam, ezt mondja az Úr Isten, s legyen a nemzetek ragadománya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 6, 'És leányai, kik a mezőségen vannak, fegyverrel ölettessenek meg, hogy megtudják, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 7, 'Mert így szól az Úr Isten: Ímé, én hozom Tírus ellen Nabukodonozort, Babilon királyát északról, a királyok királyát; lovakkal, szekerekkel, lovagokkal, sereggel és sok néppel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 8, 'Leányaidat ott a mezőségen fegyverrel öli meg, és állat ellened tornyot, és tölt ellened sánczot, és emel ellened paizs-fedelet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 9, 'És faltörő kosával ütteti kőfalaidat, s tornyaidat lerontja fegyvereivel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 10, 'Lovainak sokasága miatt belep téged poruk; a lovagoknak, kerekeknek és szekereknek robogása miatt megrendülnek kőfalaid, mikor bemegy kapuidon, a mint be szoktak menni a megtörött városba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 11, 'Lovainak körmeivel tapodja meg minden utczádat, népedet fegyverrel öli meg, s erősséged oszlopai a földre dőlnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 12, 'És prédára hányják gazdagságodat, és elragadozzák árúidat, és letörik kőfalaidat, s gyönyörűséges házaidat lerontják, és köveidet és fáidat, s még porodat is a víz közepére hányják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 13, 'És megszüntetem éneklésed hangosságát, és cziteráid zengése nem hallatik többé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 14, 'És kopasz sziklává teszlek; hálók kivető helye leszel, hogy többé meg ne építsenek; mert én, az Úr szóltam, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 15, 'Így szól az Úr Isten Tírusnak: Bizonyára a te romlásod zuhanásától, mikor a sebesültek nyögnek, mikor a te benned valók öltön-ölettetnek, megrendülnek a szigetek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 16, 'És leszáll királyi székéről a tenger minden fejedelme, és elvetik köntöseiket, s hímes ruháikat levetik: rettegésekbe öltöznek, a földön ülnek és rettegnek minden szempillantásban, s elborzadnak miattad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 17, 'És gyászéneket kezdenek rólad, és ezt mondják néked: Mimódon veszél el te, a kit laknak a tengerekről, te híres-neves város, mely hatalmas vala a tengeren, ő és lakosai, a kik félelmökre valának minden mellettök lakozóknak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 18, 'Ímé, rettegnek a szigetek zuhanásod napján, és megfélemlenek a tengerben való szigetek ilyen véged miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 19, 'Mert azt mondja az Úr Isten: Mikor én téged elpusztult várossá teszlek, mint a mely városokat nem laknak; mikor a mélység árját felhozom reád, hogy beborítsanak a sok vizek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 20, 'Akkor levonszlak téged azokkal, kik sírgödörbe szállanak, a hajdan népéhez; és lakatlak téged a mélységek országában, a hajdan pusztaságaiban, együtt azokkal, a kik sírgödörbe szálltak, hogy többé senki ne lakjék benned. És ha megmutattam dicsőségemet az élőknek földén:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 21, 'Rémségesen cselekszem veled és nem leszel; s keresni fognak, de többé örökké meg nem találnak, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 1, 'És lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 2, 'Te pedig, embernek fia, kezdj gyászéneket Tírusról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 3, 'És mondjad Tírusnak: Ki lakol a tenger révhelyein, ki a népek között kereskedik sok sziget felé, így szól az Úr Isten: Oh Tírus, te ezt mondtad: Én tökéletes szépségben vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 4, 'A tengerek szívében vannak határaid, építőid tökéletessé tették szépségedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 5, 'Senir cziprusaiból építették mindkét oldaladat, czédrust hoztak a Libánonról, hogy árbóczfát csináljanak néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 6, 'Básán cserfáiból csinálták evezőidet; evezőpadjaidat a cziprusiak szigeteiről való sudar czédrusba foglalt elefántcsontból csinálták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 7, 'Égyiptomi hímes fehér gyolcs vala vitorlád, hogy legyen zászlód; Elisának szigeteiről való kék és piros bíbor volt sátrad borítékja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 8, 'Sidon és Arvad lakói voltak evezőid; a te bölcseid, oh Tírus, kik benned valának, azok voltak kormányosaid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 9, 'Gebal vénei és bölcsei voltak benned, kik hasadékaidat javítgaták; a tenger minden hajója és hajósa volt benned, hogy kicseréljék árúidat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 10, 'Perzsák és lidiaiak és libiaiak voltak seregedben hadakozó férfiaid, paizst és sisakot függesztettek fel benned, a mik ékessé tevének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 11, 'Arvad fiai és sereged voltak kőfalaidon köröskörül, és kemény vitézek voltak tornyaidban; paizsaikat felfüggesztették kőfalaidon köröskörül, mik tökéletessé tették szépségedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 12, 'Tarsis volt a te kereskedőtársad, sok különféle gazdagsága miatt: ezüstöt, vasat, ónt és ólmot adtak ők árúidért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 13, 'Jáván, Tubál és Mések, ezek a te kalmáraid; rabszolgákat és rézedényeket adtak cserébe árúidért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 14, 'Tógarma házából lovakat és lovagokat és öszvéreket adtak néked árúkul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 15, 'Dedán fiai a te kalmáraid, sok sziget kereskedése van hatalmad alatt, elefántcsont-szarukat és ébenfát hoztak néked adóba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 16, 'Arám a te kereskedőtársad mesterműveid sokasága miatt; gránátot, bíbort, hímes ruhákat, fehér gyolcsot, korálokat és rubint adtak ők árúidért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 17, 'Júda és Izráel földe, ezek a te kalmáraid; búzát Minnithből és édes süteményt és mézet és olajat és balzsamot adtak csereárúidért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 18, 'Damaskus a te kereskedőtársad mesterműveid sokaságában, sok különféle gazdagságod miatt, – Helbon borával és hófehér gyapjúval.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 19, 'Vedán és Jáván Uzálból adtak árúidért: kovácsolt vasat, kásiát és jó illatú nádat, ezeket csereárúidért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 20, 'Dedán a te kalmárod, lovagláshoz való nyeregtakarókkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 21, 'Arábia és Kédár fejedelmei, ők mindnyájan hatalmad alatt kereskedének; bárányokkal, kosokkal és bakokkal kereskedének veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 22, 'Séba és Raema kalmárai a te kalmáraid; mindenféle drága fűszerszámokat és mindenféle drágaköveket és aranyat adtak ők árúidért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 23, 'Hárán és Kanne és Eden, Seba kalmárai, Assiria és Kilmad mind a te kereskedőtársad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 24, 'Ezek a te kalmáraid tökéletes árúkkal, bíbor és hímes köntösökkel és drága ruháknak kötelekkel egybekötött és czédrusfából csinált szekrényeivel, a te sokadalmadban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 25, 'Tarsis hajói hordozták árúidat, és megtelél, és felette igen híressé levél a tengerek szívében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 26, 'Nagy vizekre vivének téged a te evezőid, a keleti szél összetört téged a tengerek szívében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 27, 'Gazdagságod és árúid, csereárúid, hajósaid és kormányosaid, hasadékaid javítgatói és csereárúid árúsai és minden hadakozó férfiaid, a kik benned vannak, és minden benned való sokaság, beleesnek a tengerek szívébe zuhanásod napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 28, 'Kormányosaid kiáltásának hangjára megrendülnek a mezőségek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 29, 'És kiszállnak hajóikból mindnyájan, kik az evezőt fogják, hajósok és a tengernek minden kormányosi a szárazföldre lépnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 30, 'És hallatják fölötted hangjokat, s keservesen kiáltanak, s port hintenek fejökre, hamuban fetrengenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 31, 'És kopaszra nyiratkoznak miattad, és zsákba övezkednek, és sírnak feletted lelki keserűségben keserves sírással.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 32, 'És kezdenek fölötted fájdalmukban gyászéneket, és így énekelnek rólad: Ki volt olyan, mint Tírus? mely most mint temető a tenger közepette!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 33, 'Mikor kimennek vala árúid a tengerekből, sok népet megelégítél; gazdagságod és csereárúid sokaságával meggazdagítád a földnek királyait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 34, 'Most összeomlottál a tengerekről le a vizek mélységébe, csereárúid és egész sokaságod benned elsülyedt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 35, 'A szigetek minden lakosai elborzadnak miattad, s királyaik iszonyodva megiszonyodnak, arczaik rángatóznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 36, 'A népek közt való kereskedők fütyölnek feletted. Rémségessé lettél, s többé örökké nem leszel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 1, 'És lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 2, 'Embernek fia! mondjad Tírus fejedelmének: Ezt mondja az Úr Isten: Mivelhogy felfuvalkodott szíved és ezt mondtad: Isten vagyok én, Isten székében ülök a tengerek szívében, holott csak ember vagy és nem Isten, mégis olylyá tevéd szíved, minő az Isten szíve,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 3, 'Lám, hát bölcsebb volnál te Dánielnél! Semmi elrejtett dolog nem homályos néked!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 4, 'Bölcseségeddel és értelmeddel gyűjtöttél magadnak gazdagságot, s gyűjtöttél aranyat s ezüstöt kincses házaidba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 5, 'Bölcseségednek nagy voltával kereskedésed közben megsokasítád gazdagságodat, és felfuvalkodott szíved gazdagságod miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 6, 'Ezokáért így szól az Úr Isten: Mivel olylyá tevéd szíved, minő az Isten szíve:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 7, 'Azért ímé, hozok reád idegeneket, a nemzetek legkegyetlenebbjeit, és kivonszák fegyvereiket bölcseséged szépsége ellen, és megfertéztetik fényességedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 8, 'A sírgödörbe szállítnak alá, s meghalsz a megölettek halálával a tengerek szívében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 9, 'Vajjon mondván mondod-é megölőd előtt: Isten vagyok én? holott ember vagy és nem Isten a téged átütőnek kezében!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 10, 'Körülmetéletlenek halálával halsz meg, idegeneknek keze által. Mert én szóltam, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 11, 'És lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 12, 'Embernek fia! kezdj gyászéneket Tírus királyáról, és mondd néki: Így szól az Úr Isten: Te valál az arányosság pecsétgyűrűje, teljes bölcseséggel, tökéletes szépségben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 13, 'Édenben, Isten kertjében voltál; rakva valál mindenféle drágakövekkel: karniollal, topázzal és jáspissal, társiskővel és onixxal, berillussal, zafirral, gránáttal és smaragddal; és karikáid mesterkézzel és mélyedéseid aranyból készültek ama napon, melyen teremtetél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 14, 'Valál felkent oltalmazó Kérub; és úgy állattalak téged, hogy Isten szent hegyén valál, tüzes kövek közt jártál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 15, 'Feddhetetlen valál útaidban attól a naptól fogva, melyen teremtetél, míg gonoszság nem találtaték benned.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 16, 'Kereskedésed bősége miatt belsőd erőszakossággal telt meg és vétkezél; azért levetélek téged az Isten hegyéről, és elvesztélek, te oltalmazó Kérub, a tüzes kövek közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 17, 'Szíved felfuvalkodott szépséged miatt; megrontottad bölcseségedet fényességedben; a földre vetettelek királyok előtt, adtalak szemök gyönyörűségére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 18, 'Vétkeid sokaságával kereskedésed hamisságában megfertéztetted szenthelyeidet; azért tüzet hoztam ki belsődből, ez emésztett meg téged; és tevélek hamuvá a földön mindenek láttára, a kik reád néznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 19, 'Mindnyájan, a kik ismertek a népek közt, elborzadnak miattad; rémségessé lettél, s többé örökké nem leszel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 20, 'És lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 21, 'Embernek fia! vesd tekintetedet Sidonra, és prófétálj ellene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 22, 'És mondjad: Így szól az Úr Isten: Ímé, én ellened megyek, Sidon, és megdicsőítem magamat közepetted, hogy megtudják, hogy én vagyok az Úr, mikor ítéleteket cselekszem benne, és megszentelem magamat benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 23, 'És bocsátok reá döghalált és vért utczáira, és sebesültek hullanak el benne fegyver miatt, mely reá jő mindenfelől; hogy megtudják, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 24, 'És ne legyen többé Izráel házának szúró tövise és fájdalomszerző tüskéje mindazok között, kik körülöttök vannak, kik őket megvetik, és tudják meg, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 25, 'Így szól az Úr Isten: Mikor egybegyűjtöm Izráel házát a népek közül, kik közé szétszórattak, akkor megszentelem magamat rajtok a pogányok szeme láttára, és laknak az ő földjökön, melyet adtam Jákóbnak, az én szolgámnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 26, 'És laknak azon bátorsággal, és házakat építenek s szőlőket plántálnak, és laknak bátorsággal, mikor ítéleteket cselekedtem mindazokon, kik őket megvetik vala ő körülöttök, hogy megtudják, hogy én vagyok az Úr, az ő Istenök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 1, 'A tizedik esztendőben, a tizedik hónapban, a hónap tizenkettedikén lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 2, 'Embernek fia! vesd tekintetedet a Faraóra, Égyiptom királyára, és prófétálj ellene és egész Égyiptom ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 3, 'Szólj és mondjad: Így szól az Úr Isten: Ímé, én ellened megyek, Faraó, Égyiptom királya, te nagy krokodil, a ki fekszik folyói közepette, a ki ezt mondja: Enyém az én folyóm, és én teremtettem magamnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 4, 'És horgokat vetek szádba, és azt cselekszem, hogy folyóid halai odaragadjanak pikkelyeidhez, és kivonszlak folyóid közepéből, és folyóid minden halait, melyek odaragadnak pikkelyeidhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 5, 'És kivetlek a pusztába téged és folyóid minden halát; a mező színére esel; egybe nem szedetel s nem gyűjtetel; a földi vadaknak s az égi madaraknak adlak eledelül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 6, 'És megtudják mindnyájan Égyiptom lakói, hogy én vagyok az Úr. Mivelhogy ők nádszál-bot valának Izráel házának;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 7, 'Melyet ha megfognak kezökkel, összetörsz, s felhasítod egész vállokat, és ha reád támaszkodnak, összeroppansz, s megrázod egész derekokat:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 8, 'Ezokáért így szól az Úr Isten: Ímé, hozok ellened fegyvert, és kivágok belőled embert és barmot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 9, 'És legyen Égyiptom földje pusztasággá és sivataggá, és megtudják, hogy én vagyok az Úr. Mivelhogy azt mondja: A folyó enyém, és én teremtettem:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 10, 'Ezokáért ímé, én ellened megyek, és folyóid ellen, és teszem Égyiptom földjét nagy pusztaságok pusztaságává Migdoltól fogva Siénéig, és Szerecsenország határáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 11, 'Ne menjen át azon emberi láb, se baromi láb ne menjen át rajta, és ne lakják negyven esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 12, 'És adom Égyiptom földjét pusztaságra az elpusztult földek között, s városai lesznek az elpusztult városok közt pusztaságban negyven esztendeig, és eloszlatom az égyiptomiakat a nemzetek közé, s szétszórom őket a tartományokba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 13, 'Mert így szól az Úr Isten: Negyven esztendő múlva egybegyűjtöm az égyiptomiakat a népek közül, kik közé szétszórattak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 14, 'És visszahozom Égyiptom foglyait s visszaviszem őket Pathrós földjére, az ő eredetök földjére, és ott lesznek alacsony királyság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 15, 'A többi királyságokhoz képest alacsony lészen s többé nem emeli magát a nemzetek fölé; és megkevesbítem őket, hogy el ne tapodják a nemzeteket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 16, 'És nem lesz többé Izráel házának bizodalma, mely vétekre emlékeztessen engem, midőn feléje hajlanak, és megtudják, hogy én vagyok az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 17, 'És lőn a huszonhetedik esztendőben, az első hónapban, a hónap elsején, lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 18, 'Embernek fia! Nabukodonozor Babilon királya nagy fáradsággal fárasztotta seregét Tírus ellen: minden fő megkopaszult és minden váll feltört; de jutalma nem lőn néki és seregének Tírusból a fáradságért, a melylyel miatta fáradott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 19, 'Ennekokáért így szól az Úr Isten: Ímé, én Nabukodonozornak a babiloni királynak adom Égyiptom földjét, és elviszi gazdagságát, s elragadja ragadományát, s elprédálja prédáját, és ez lesz jutalma seregének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 20, 'Fizetésül, a melyért fáradott, adom néki Égyiptom földjét, mert értem cselekedtek, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 21, 'Azon a napon szarvat sarjasztok Izráel házának, és a te szádat megnyitom közöttök, és megtudják, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 1, 'És lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 2, 'Embernek fia! prófétálj és mondd: Így szól az Úr Isten: Jajgassatok! Jaj annak a napnak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 3, 'Mert közel egy nap és közel az Úrnak napja, felhőnek napja, a pogányok ideje lesz az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 4, 'És bemegy a fegyver Égyiptomba, és lesz reszketés Szerecsenországban, mikor hullanak a sebesültek Égyiptomban, és elviszik gazdagságát, s elrontatnak fundamentomai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 5, 'A szerecsenek s a libiaiak s a lidiaiak és az egész gyülevész és Kúb és a frigy földének fiai velök együtt fegyver miatt hullnak el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 6, 'Így szól az Úr: És elessenek, a kik Égyiptomot támogatják, és alászálljon erősségének kevélysége: Migdoltól fogva Siénéig fegyver miatt hullanak el benne, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 7, 'És elpusztulnak elpusztult tartományok között, és városai elpusztult városoknak közepette lesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 8, 'És megtudják, hogy én vagyok az Úr, mikor tüzet vetek Égyiptomra, és összetörik minden segítője.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 9, 'Azon a napon követek mennek ki előttem hajókon a bátorságban lakó Szerecsenország elrémítésére, s lészen rettegés bennök Égyiptom ama napján; mert ímé jön!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 10, 'Ezt mondja az Úr Isten: És megszüntetem Égyiptom lármáját Nabukodonozor, babiloni király keze által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 11, 'Ő és az ő népe ő vele együtt, a nemzetek legkegyetlenebbjei, elhozatnak a föld elvesztésére, és kivonszák fegyveröket Égyiptom ellen, és betöltik a földet megölettekkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 12, 'És a folyóvizeket kiszárasztom, és eladom a földet gonoszok kezébe, és elpusztítom a földet s teljességét idegenek keze által, én, az Úr szólottam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 13, 'Így szól az Úr Isten: És elvesztem a bálványokat és megszüntetem a bálványképeket Nófból s a fejedelmet Égyiptom földjéről, nem lészen többé, és bocsátok félelmet Égyiptom földjére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 14, 'És elpusztítom Pathróst, s vetek tüzet Zoánra, és teszek ítéleteket Nóban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 15, 'És kiöntöm haragomat Sinre, Égyiptom erősségére, és kivágom a sokaságot Nóból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 16, 'És vetek tüzet Égyiptomra, kínok közt vergődik Sin, és Nó megtörik és Nófba betörnek fényes nappal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 17, 'Aven és Fibéseth ifjai fegyver miatt hullanak el, és ők magok fogságra mennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 18, 'És Tehafneheszben megsötétedik a nap, mikor ott összetöröm Égyiptom pálczáját, és megszünik benne erejének kevélysége, őt magát felhő takarja el, és leányai fogságra mennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 19, 'És cselekszem ítéleteket Égyiptomban, és megtudják, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 20, 'És lőn a tizenegyedik esztendőben, az első hónapban, a hónap hetedikén, lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 21, 'Embernek fia! A Faraónak, Égyiptom királyának karját eltörtem, és ímé be nem kötötték, hogy megorvosolják, hogy tegyenek körülkötést reá, hogy megerősödjék fegyverfogásra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 22, 'Ennekokáért így szól az Úr Isten: Ímé, a Faraó ellen megyek, Égyiptomnak királya ellen, és eltöröm mind a két karját, azt, amely még erős, és azt, amely már eltörött, s elejtetem vele kezéből a fegyvert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 23, 'És eloszlatom az Égyiptombelieket a nemzetek közé, és szétszórom őket a tartományokba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 24, 'És megerősítem Babilon királyának karjait, és adom az én fegyveremet kezébe, és eltöröm a Faraó karjait, és nyögni fog előtte, mint a megsebesültek szoktak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 25, 'Megerősítem azért Babilon királyának karjait, a Faraó karjai pedig leessenek, hogy megtudják, hogy én vagyok az Úr, mikor adom fegyveremet Babilon királyának kezébe, hogy azt kinyújtsa Égyiptomnak földje ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 26, 'És eloszlatom az égyiptomiakat a nemzetek közé, és szétszórom őket a tartományokba, hogy megtudják, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 1, 'És lőn a tizenegyedik esztendőben, a harmadik hónapban, a hónap elsején, lőn az Úr szava hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 2, 'Embernek fia! szólj a Faraónak, Égyiptom királyának és az ő sokaságának: Kihez vagy hasonló a te nagyságodban?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 3, 'Ímé, Assúr czédrus vala a Libánonon, szép ágakkal és sűrű galyaival árnyékot tartó s magas növésű, melynek felhőkig ért a teteje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 4, 'Víz nevelte nagygyá, a mélység vizei tették magassá, folyóikkal körüljárták ültetése földjét, s csak folyásaikat bocsáták a mező egyéb fáihoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 5, 'Ennekokáért lőn magasb növése a mező minden fájánál: s megsokasulának ágai, s hosszúra nevekedének galyai a sok víztől, midőn kiterjeszté azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 6, 'Az ő ágain csinál vala fészket minden égi madár, és galyai alatt fiadzott a mező minden vada, s árnyékában lakik vala sokmindenféle nép.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 7, 'És széppé lőn magasságával, hosszan kiterjedt ágaival, mert gyökere sok víz felé nyúlik vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 8, 'A czédrusok el nem takarák őt az Isten kertjében, a cziprusok nem valának hasonlók ágaihoz, s a platánoknak nem valának olyan galyai, mint néki; Isten kertjében egy fa sem vala hasonló hozzá az ő szépségében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 9, 'Széppé tőm őt az ő sok ágaival, úgy hogy irígykedett rá Éden minden fája az Isten kertjében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 10, 'Ennekokáért így szól az Úr Isten: Mivelhogy magasra nevekedtél, és fölemelé tetejét a felhők közé, és szíve felfuvalkodott az ő magasságában:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 11, 'Azért adom őt a nemzetek urának kezébe, bánjék el vele, gonoszságáért kiűztem őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 12, 'És kivágták őt az idegenek, a nemzetek legkegyetlenebbjei, és leterítették. A hegyekre és minden völgyekbe hullottak ágai, és összetörtek galyai a föld minden mélységében, és leszállt árnyékából a föld minden népe, és ott hagyták őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 13, 'Ledőlt törzsökén lakik vala minden égi madár, és ágaihoz gyül vala a mező minden vada;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 14, 'Azért, hogy magasra ne nevekedjék egy víz mellett való fa se, és föl ne emelje tetejét a felhők közé; hogy ne bízzék önmagában kevélyen senki a vízivók közül; mert mindnyájan halálra adattak a mélység országába az emberek fiai közt azokhoz, a kik sírgödörbe szálltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 15, 'Így szól az Úr Isten: Azon a napon, a melyen sírba aláméne, gyászba öltöztetém miatta a mélység vizeit, és megtartóztatám folyóikat, úgy hogy a sok víz elzáraték, s meggyászoltatám őt a Libánonnal, és a mező minden fája elepede miatta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 16, 'Zuhanásának hangja miatt megreszkettetém a nemzeteket, mikor leszállítám őt a sírba együtt velök, kik sírgödörbe szállnak; és vígasztalást vőn a mélység országában Éden minden fája, a Libánon szépsége és java, minden vízivó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 17, 'Ezek is alászállottak vele a sírba azokhoz, a kik fegyverrel ölettek meg, s a kik mint segítőtársai árnyékában ülének a nemzetek között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 18, 'Kihez vagy hát hasonló dicsőségben és nagyságban Éden fái közt!? Hiszen le fogsz szállíttatni Éden fáival a mélység országába; körülmetéletlenek közt feküszöl együtt a fegyverrel megölettekkel. A Faraó ez és minden sokasága, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 1, 'És lőn a tizenkettedik esztendőben, a tizenkettedik hónapban, a hónap elsején, lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 2, 'Embernek fia! kezdj gyászéneket a Faraóról, Égyiptom királyáról, és mondjad néki: Nemzetek fiatal oroszlánja, elvesztél; hiszen te olyan valál, mint a krokodil a tengerekben, mert kijövél folyóidon és megháborítád lábaiddal a vizeket és felzavartad folyóikat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 3, 'Így szól az Úr Isten: Ezért kivetem rád hálómat sok nép serege által, és kihúznak téged varsámban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 4, 'És leterítlek a földre, a mezőség színére vetlek, és reád szállítom az ég minden madarát, s megelégítem belőled az egész föld vadait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 5, 'S vetem húsodat a hegyekre, és betöltöm a völgyeket rothadásoddal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 6, 'És megitatom áradásod földjét véredből mind a hegyekig, s a mélységek megtelnek belőled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 7, 'És mikor eloltalak, beborítom az eget, s csillagait besötétítem, a napot felhőbe borítom, és a hold nem fényeskedik fényével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 8, 'Minden világító testet megsötétítek miattad az égen, és bocsátok sötétséget földedre, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 9, 'És megszomorítom sok nép szívét, ha elhíresztelem romlásodat a nemzetek között, a földeken, a melyeket nem ismersz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 10, 'És cselekszem, hogy elborzadjanak miattad a sok népek, s királyaik rémüljenek el rémüléssel miattad, mikor villogtatom fegyveremet előttök, s remegni fognak minden szempillantásban, kiki az ő életéért, zuhanásod napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 11, 'Mert így szól az Úr Isten: A babiloni király fegyvere jön reád.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 12, 'Vitézeknek fegyvereivel hullatom el sokaságodat, ők a népek legkegyetlenebbjei mindnyájan; és elpusztítják Égyiptom kevélységét, és elvész minden sokasága.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 13, 'És elvesztem minden barmát a sok vizek mellől, és nem zavarja fel azokat többé ember lába, sem barmok körme azokat föl nem zavarja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 14, 'Akkor meghiggasztom vizeiket, és folyóikat, olajként folyatom, ezt mondja az Úr Isten,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 15, 'Mikor Égyiptom földjét pusztasággá teszem, és kipusztul a föld teljességéből, mert megverek minden rajta lakót, hogy megtudják, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 16, 'Gyászének ez és sírva énekeljék; a népek leányai énekeljék sírva; Égyiptomról és minden sokaságáról énekeljék sírva, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 17, 'És lőn a tizenkettedik esztendőben, a hónap tizenötödikén, lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 18, 'Embernek fia! sírj Égyiptom sokaságán, és szállítsd alá őt te és a hatalmas nemzetek leányai a mélységek országába azokhoz, kik sírgödörbe szálltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 19, 'Kinél nem voltál volna kedvesebb? Szállj alá, hadd fektessenek a körülmetéletlenek mellé!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 20, 'A fegyverrel megölettek közt essenek el! A fegyver átadatott; húzzátok lefelé őt és minden sokaságát!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 21, 'Szólni fognak felőle a vitézek hatalmasai a sír közepéből együtt az ő segítőivel: alászállottak, hogy itt feküdjenek a körülmetéletlenek, mint fegyverrel megöltek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 22, 'Itt van Assúr és egész sokasága, körülte sírjai, mindnyájan megölettek, kik fegyver miatt hulltak el,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 23, 'A kinek sírjai a sírgödör legmélyén vannak és sokasága az ő sírja körül van, mindnyájan megölettek, fegyver miatt elestek, kik félelmére valának az élők földjének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 24, 'Itt van Elám és egész sokasága az ő sírja körül, mindnyájan megölettek, kik fegyver miatt hulltak el, kik alászálltak körülmetéletlenül a mélységek országába, kik félelmére valának az élők földjének, és viselik gyalázatukat azok mellett, kik sírgödörbe szálltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 25, 'A megölettek között vetettek néki ágyat minden sokaságával, körülte vannak ennek sírjai, mindnyájan körülmetéletlenek, fegyverrel megölettek, mert félelmére valának az élők földjének, és viselik gyalázatukat azok mellett, kik sírgödörbe szálltak; a megölettek közé vetették őket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 26, 'Itt van Mések-Tubál és minden sokasága, körülte vannak ennek sírjai, mindnyájan körülmetéletlenek, fegyverrel megölettek, mert félelmére valának az élők földjének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 27, 'És nem feküsznek együtt az erősekkel, kik elestek a körülmetéletlenek közül, kik hadiszerszámaikkal szálltak alá a sírba s kiknek az ő fegyvereiket fejük alá tették; mert lőn az ő vétkök csontjaikon, mivelhogy félelmére valának a vitézeknek az élők földjén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 28, 'Te is a körülmetéletlenek közt rontatol meg, és fekszel a fegyverrel megölettek mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 29, 'Itt van Edom királyaival és minden fejedelmével, kik vettettek erősségökben a fegyverrel megöltekhez, ők a körülmetéletlenekkel feküsznek s azokkal, a kik sírgödörbe szálltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 30, 'Ott vannak észak uralkodói mindnyájan, és minden sidoni, a kik alászálltak a megölettekkel, rettenetes voltukban, erősségökben megszégyenülve; és feküsznek körülmetéletlenül a fegyverrel megölettek mellett, és viselik gyalázatukat a sírgödörbe szálltak között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 31, 'Ezeket látni fogja a Faraó, és megvígasztalódik minden sokasága felől; fegyverrel ölettek meg a Faraó és minden ő serege, ezt mondja az Úr Isten,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 32, 'Mert félelmére adtam őt az élők földjének; ezért ott vetnek ágyat néki a körülmetéletlenek között, a fegyverrel megölettek mellett, a Faraónak és minden sokaságának, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 1, 'És lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 2, 'Embernek fia! szólj néped fiaihoz és mondjad nékik: Mikor hozándok fegyvert valamely földre, és a föld népe választ egy férfit ő magok közül, és őt őrállójokká teszik:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 3, 'És ő látja jőni a fegyvert a földre, és megfújja a trombitát, és meginti a népet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 4, 'Ha valaki hallándja a trombitaszót, de nem hajt az intésre, s aztán a fegyver eljő és őt utóléri: az ő vére az ő fején lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 5, 'Hallotta a trombitaszót, de nem hajtott az intésre, tehát az ő vére ő rajta lesz; és ha hajtott az intésre, megmentette lelkét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 6, 'Ha pedig az őrálló látja a fegyvert jőni, s nem fújja meg a trombitát, és a nép nem kap intést, és eljő a fegyver s utólér közülök valamely lelket, ez a maga vétke miatt éretett utól, de vérét az őrálló kezéből kérem elő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 7, 'És te, embernek fia, őrállóul adtalak téged Izráel házának, hogy ha szót hallasz a számból, megintsed őket az én nevemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 8, 'Ha ezt mondom a hitetlennek: Hitetlen, halálnak halálával halsz meg; és te nem szólándasz, hogy visszatérítsd a hitetlent az ő útjáról: az a hitetlen vétke miatt hal meg, de vérét a te kezedből kívánom meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 9, 'De ha te megintetted a hitetlent az ő útja felől, hogy térjen meg róla, de nem tért meg útjáról, ő vétke miatt meghal, de te megmentetted a te lelkedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 10, 'Te pedig, embernek fia, mondjad Izráel házának: Ezt mondjátok, mondván: Bizony a mi bűneink és vétkeink rajtunk vannak, és bennök mi megrothadunk, mimódon éljünk azért?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 11, 'Mondjad nékik: Élek én, ezt mondja az Úr Isten, hogy nem gyönyörködöm a hitetlen halálában, hanem hogy a hitetlen megtérjen útjáról és éljen. Térjetek meg, térjetek meg gonosz útaitokról! hiszen miért halnátok meg, oh Izráel háza!?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 12, 'Te pedig, embernek fia, szólj néped fiaihoz: Az igaznak igazsága meg nem menti őt a napon, a melyen vétkezendik, és a hitetlen hitetlensége által el nem esik a napon, melyen megtérend hitetlenségéből, és az igaz nem élhet az ő igazsága által a napon, melyen vétkezendik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 13, 'Mikor ezt mondom az igazról: Élvén éljen; és ő bízván igazságában, gonoszságot cselekszik: semmi igazsága emlékezetbe nem jő, és gonoszsága miatt, melyet cselekedett, meghal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 14, 'S ha mondom a hitetlennek: halállal halsz meg; és ő megtér bűnéből és törvény szerint s igazságot cselekszik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 15, 'Zálogot visszaad a hitetlen, rablottat megtérít, az életnek parancsolatiban jár, többé nem cselekedvén gonoszságot: élvén él, és meg nem hal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 16, 'Semmi ő vétke, melylyel vétkezett, emlékezetbe nem jön néki; törvény szerint és igazságot cselekedett, élvén él.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 17, 'És ezt mondják néped fiai: Nem igazságos az Úrnak útja; holott az ő útjok nem igazságos.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 18, 'Mikor az igaz elfordul az ő igazságától s gonoszságot cselekszik, meghal a miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 19, 'És mikor a hitetlen elfordul az ő hitetlenségétől és törvény szerint s igazságot cselekszik, él a miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 20, 'És azt mondjátok: Nem igazságos az Úrnak útja: mindeniteket az ő útja szerint ítélem meg, Izráel háza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 21, 'És lőn fogságunknak tizenkettedik esztendejében, a tizedik hónapban, a hónap ötödikén, jöve hozzám egy menekült Jeruzsálemből, mondván: Megvétetett a város!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 22, 'És az Úrnak keze lőn én rajtam este a menekült eljötte előtt, és megnyitá számat, mikorra az hozzám jöve reggel, és megnyilatkozék szám, s nem valék néma többé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 23, 'És lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 24, 'Embernek fia! azok, kik amaz elpusztított helyeket lakják Izráel földjén, ezt mondják, mondván: Egyetlen egy volt Ábrahám, mikor örökségül kapta a földet, mi pedig sokan vagyunk, nékünk a föld örökségül adatott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 25, 'Ezokáért mondjad nékik: Ezt mondja az Úr Isten: Véreset esztek, és szemeiteket bálványaitokra emelitek, és vért ontotok; és a földet örökségül kapnátok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 26, 'Fegyveretekben bíztatok, útálatosságot cselekedtetek, és mindenitek az ő felebarátja feleségét megfertéztette; és a földet örökségül kapnátok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 27, 'Ezt mondjad nékik: Így szól az Úr Isten: Élek én, hogy a kik az elpusztult helyeken vannak, fegyver miatt hullnak el; és a ki a mezőnek színén, azt a vadaknak adtam eledelül, és a kik az erősségekben és a barlangokban vannak, döghalállal halnak meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 28, 'És teszem a földet pusztaságok pusztaságává, s megszünik erősségének kevélysége, és puszták lesznek Izráel hegyei, mert nem lesz, a ki átmenjen rajtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 29, 'És megtudják, hogy én vagyok az Úr, mikor a földet pusztaságok pusztaságává teszem mindenféle útálatosságukért, melyeket cselekedtek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 30, 'És te, embernek fia, néped fiai beszélgetnek felőled a falak mellett s a házaknak ajtaiban; és egyik a másikkal szól, kiki az ő atyjafiával, mondván: Jertek, kérlek, és halljátok: micsoda beszéd az, amely az Úrtól jő ki?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 31, 'És eljőnek hozzád, a hogy a nép össze szokott jőni, s oda ülnek elődbe, mint az én népem, és hallgatják beszédidet, de nem cselekeszik, hanem szerelmeskedő énekként veszik azokat ajkokra, szívök pedig nyereség után jár.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 32, 'És ímé, te olyan vagy nékik, mint valamely szerelmeskedő ének, szép hangú, s mint valamely jó hegedűs; csak hallják beszédidet, de nem cselekszik azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 33, 'De ha beteljesednek, mert ímé beteljesednek, megtudják, hogy próféta volt közöttök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 1, 'És lőn az Úrnak beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 2, 'Embernek fia! prófétálj Izráel pásztorai felől, prófétálj és mondjad nékik, a pásztoroknak: Így szól az Úr Isten: Jaj Izráel pásztorainak, a kik önmagokat legeltették! Avagy nem a nyájat kell-é legeltetni a pásztoroknak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 3, 'A tejet megettétek, és a gyapjúval ruházkodtatok, a hízottat megöltétek; a nyájat nem legeltettétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 4, 'A gyöngéket nem erősítettétek, és a beteget nem gyógyítottátok, s a megtöröttet nem kötözgettétek, s az elűzöttet vissza nem hoztátok és az elveszettet meg nem kerestétek, hanem keményen és kegyetlenül uralkodtatok rajtok;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 5, 'Szétszóródtak hát pásztor nélkül, és lőnek mindenféle mezei vadak eledelévé, és szétszóródtak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 6, 'Tévelygett nyájam minden hegyen s minden magas halmon, és az egész föld színén szétszóródott az én nyájam, s nem volt, a ki keresné, sem a ki tudakozódnék utána.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 7, 'Annakokáért, ti pásztorok, halljátok meg az Úr beszédét:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 8, 'Élek én, ezt mondja az Úr Isten, mivelhogy az én nyájam ragadománynyá lőn, és lőn az én nyájam mindenféle mezei vadak eledelévé, pásztor hiányában, és nem keresték az én pásztoraim az én nyájamat, hanem legeltették a pásztorok önmagokat, és az én nyájamat nem legeltették;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 9, 'Ennekokáért, ti pásztorok, halljátok meg az Úr beszédét:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 10, 'Így szól az Úr Isten: Ímé, megyek a pásztorok ellen, és előkérem nyájamat az ő kezökből, s megszüntetem őket a nyáj legeltetésétől, és nem legeltetik többé a pásztorok önmagokat, s kiragadom juhaimat szájokból, hogy ne legyenek nékik ételül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 11, 'Mert így szól az Úr Isten: Ímé, én magam keresem meg nyájamat, és magam tudakozódom utána.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 12, 'Miképen a pásztor tudakozódik nyája után, a mely napon ott áll elszéledt juhai között; így tudakozódom nyájam után, és kiszabadítom őket minden helyről, a hova szétszóródtak a felhőnek s borúnak napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 13, 'És kihozom őket a népek közül s egybegyűjtöm a földekről, és beviszem őket az ő földjökre, és legeltetem őket Izráel hegyein, a mélységekben s a föld minden lakóhelyén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 14, 'Jó legelőn legeltetem őket, és Izráel magasságos hegyein leszen akluk, ott feküsznek jó akolban, s kövér legelőn legelnek Izráel hegyein.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 15, 'Én magam legeltetem nyájamat, s én nyugosztom meg őket, ezt mondja az Úr Isten;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 16, 'Az elveszettet megkeresem, s az elűzöttet visszahozom, s a megtöröttet kötözgetem, s a beteget erősítem; és a kövéret s erőset elvesztem, és legeltetem őket úgy, mint illik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 17, 'Ti pedig, én juhaim, így szól az Úr Isten, ímé én ítéletet teszek juh és juh között, a kosok és bakok közt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 18, 'Avagy kevés-é néktek, hogy a jó legelőt legelitek, hogy még legelőitek maradékát lábaitokkal eltapodjátok? és hogy a víz tisztáját iszszátok, hogy még a maradékát lábaitokkal felzavarjátok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 19, 'És az én juhaim a ti lábaitok tapodását legelik, s lábaitok zavarását iszszák!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 20, 'Annakokáért így szól az Úr Isten hozzájok: Ímé én, én teszek ítéletet kövér és ösztövér juh között,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 21, 'Mivelhogy oldallal és vállal eltaszíttok és szarvaitokkal elökleltek minden erőtelent, míg szétszórván, azokat kiűzitek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 22, 'És megtartom az én juhaimat, hogy többé ne legyenek zsákmányul, és ítéletet teszek juh és juh között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 23, 'És állatok föléjök egyetlenegy pásztort, hogy legeltesse őket: az én szolgámat, Dávidot, ő legelteti őket s ő lesz nékik pásztoruk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 24, 'Én pedig, az Úr, leszek nékik Istenök, és az én szolgám, Dávid, fejedelem közöttök. Én, az Úr mondottam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 25, 'És szerzek ő velök békességnek frigyét, és megszüntetem a gonosz vadakat a földről, hogy bátorságosan lakhassanak a pusztában és alhassanak az erdőkben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 26, 'És adok reájok és az én magaslatom környékére áldást, és bocsátom az esőt idejében; áldott esők lesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 27, 'A mező fája megadja gyümölcsét s a föld megadja termését, és lesznek földjökön bátorságosan, és megtudják, hogy én vagyok az Úr, mikor eltöröm jármok keresztfáit, és kimentem őket azok kezéből, kik őket szolgáltatják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 28, 'És nem lesznek többé prédául a pogányoknak, s a föld vadai nem eszik meg őket; és laknak bátorságosan, s nem lesz, a ki felijeszsze őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 29, 'És támasztok nékik drága plántaföldet, hogy többé meg ne emésztessenek éhség miatt a földön, s ne viseljék többé a pogányok gyalázatát;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 30, 'És megismerik, hogy én, az Úr, az ő Istenök, velök vagyok, és ők népem, Izráel háza, ezt mondja az Úr Isten;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 31, 'Ti pedig az én juhaim, legelőm nyája vagytok, emberek vagytok, én pedig Istenetek, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 1, 'És lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 2, 'Embernek fia! vesd tekintetedet Seir hegyére, és prófétálj ellene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 3, 'És mondjad néki: Ezt mondja az Úr Isten: Ímé, én ellened megyek, Seir hegye, és kinyújtom kezemet reád, s teszlek pusztaságok pusztaságává.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 4, 'Városaidat pusztaságra vetem, és te pusztulásra jutsz, és megtudod, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 5, 'Mivelhogy örökkévaló gyűlölséget tartasz, és odaadád Izráel fiait a fegyver kezébe veszedelmök idején, az utolsó vétek idején;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 6, 'Ennekokáért élek én, ezt mondja az Úr Isten, hogy vérré teszlek téged, és vér kergessen téged. Te nem gyűlölted a vért, a vér kergessen hát téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 7, 'És teszem Seir hegyét pusztaságok pusztaságává, és kiirtom belőle az átmenőt és visszatérőt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 8, 'És betöltöm hegyeit megölöttjeivel; halmaid és völgyeid és minden mélységed: fegyverrel megölöttek hullanak beléjök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 9, 'Örök pusztasággá teszlek, és városaidat ne lakják, és megtudjátok, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 10, 'Mivelhogy ezt mondod: Az a két nemzet és az a két föld enyém lesz és örökségül bírjuk, holott az Úr ott volt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 11, 'Annakokáért élek én, ezt mondja az Úr Isten, hogy a te haragod és fölgerjedésed szerint cselekszem veled, a melylyel te cselekedtél irántok való gyűlölségedből; és megjelentem magamat közöttök, mikor megítéllek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 12, 'És megtudod, hogy én, az Úr, meghallottam minden szidalmadat, melyeket Izráel hegyei ellen mondtál, mondván: Elpusztultak, nékünk adattak ételül;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 13, 'Így kérkedtetek ellenem szátokkal, s szórtátok ellenem beszédeiteket: én meghallottam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 14, 'Így szól az Úr Isten: Az egész föld örömére pusztulást hozok rád.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 15, 'A mint te örültél Izráel háza örökségén azért, hogy elpusztult, úgy cselekszem veled; pusztává légy Seir hegye és mind egészen Edom, és megtudják, hogy én vagyok az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 1, 'És te, embernek fia, prófétálj Izráel hegyei felől, és mondjad: Izráel hegyei, halljátok meg az Úr beszédét,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 2, 'Így szól az Úr Isten: Mivelhogy ezt mondja az ellenség reátok: Haha! és: Az ősi magasságok a mi örökségünk lőnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 3, 'Ennekokáért prófétálj, és mondjad: Ezt mondja az Úr Isten: Azért, mert pusztítanak, és kívánnak titeket mindenfelől, hogy legyetek öröksége a pogányok maradékának, és az emberek rágalmazó ajkára-nyelvére kerültetek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 4, 'Ezokáért, Izráel hegyei, halljátok meg az Úr Isten beszédét! Így szól az Úr Isten a hegyeknek és halmoknak, a mélységeknek és völgyeknek, és az elpusztult romoknak és az elhagyott városoknak, melyek ragadományra és csúfolásra lőnek a pogányok maradékának köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 5, 'Azért ezt mondja az Úr Isten: Bizony, féltő szerelmem tüzében beszéltem a pogányok maradékai és egész Edom ellen, kik magoknak vették az én földemet örökségül teljes szívöknek örömével és lelkök megvetésével, hogy azt néptelenül zsákmányokká tegyék;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 6, 'Ezokáért prófétálj Izráel földjéről, és mondjad a hegyeknek és halmoknak, a mélységeknek és a völgyeknek: Így szól az Úr Isten: Ímé, féltő szerelmemben és búsulásomban beszélek, mivelhogy a pogányok gyalázását viseltétek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 7, 'Ennekokáért ezt mondja az Úr Isten: Én fölemelem kezemet! Bizonyára a pogányok, kik körülöttetek vannak, ők viseljék gyalázatukat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 8, 'Ti pedig, Izráel hegyei, neveljétek ágaitokat és hozzátok gyümölcsötöket az én népemnek, Izráelnek, mert közel vannak, hogy hazajőjjenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 9, 'Mert ímé, én hozzátok hajlok és hozzátok fordulok, és megmívelnek és bevetnek titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 10, 'És megsokasítom rajtatok az embereket, Izráel házát egészen, és lakják a városokat, és a romokat megépítik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 11, 'És megsokasítom rajtatok az embereket és barmokat, hogy sokasodjanak és szaporodjanak, és lakatom őket rajtatok, mint régi időtökben, és több jóval lészek hozzátok, mint első napjaitokban, s megtudjátok, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 12, 'És járatok rajtatok embereket, az én népemet, Izráelt, és bírjanak téged, s te légy nékik örökségül, s többé nem teszed őket gyermektelenné.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 13, 'Így szól az Úr Isten: Mivelhogy mondják néktek: emberevő vagy és gyermektelenné teszed népedet:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 14, 'Ennekokáért embert nem eszel többé, és népedet gyermektelenné nem teszed többé, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 15, 'És többé nem hallatom ellened a pogányok gyalázását, és a népek szidalmát többé nem viseled, és nemzetedet többé gyermektelenné nem teszed, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 16, 'És lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 17, 'Embernek fia! mikor Izráel háza a maga földén lakott, megfertéztette azt életével és cselekedeteivel; mint a havi betegség tisztátalansága, olyan vala élete előttem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 18, 'És kiöntém haragomat reájok a vérért, a melyet ontottak a földre, és bálványaikkal megfertéztették azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 19, 'És eloszlatám őket a pogányok közé, és szétszóratának a tartományokba, életök és cselekedeteik szerint ítéltem meg őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 20, 'És bemenvén a pogányokhoz, a kikhez menének, megfertéztették az én szent nevemet, mikor ezt mondták rólok: az Úr népe ezek, és az ő földéről jöttek ki!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 21, 'Ekkor könyörültem szent nevemért, melyet megfertéztetett Izráel háza a pogányok közt, a kikhez menének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 22, 'Ennekokáért mondjad Izráel házának: Ezt mondja az Úr Isten: Nem ti érettetek cselekszem, Izráel háza, hanem az én szent nevemért, melyet ti megfertéztettetek a pogányok között, a kik közé menétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 23, 'És megszentelem az én nagy nevemet, mely megfertéztetett a pogányok között, melyet ti fertéztettetek meg köztök; és megtudják a pogányok, hogy én vagyok az Úr, ezt mondja az Úr Isten, mikor megszentelem magamat rajtatok az ő szemök láttára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 24, 'És fölveszlek titeket a pogányok közül, s egybegyűjtelek titeket minden tartományból, és beviszlek titeket a ti földetekre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 25, 'És hintek reátok tiszta vizet, hogy megtisztuljatok, minden tisztátalanságtoktól és minden bálványaitoktól megtisztítlak titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 26, 'És adok néktek új szívet, és új lelket adok belétek, és elveszem a kőszívet testetekből, és adok néktek hússzívet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 27, 'És az én lelkemet adom belétek, és azt cselekszem, hogy az én parancsolatimban járjatok és az én törvényeimet megőrizzétek és betöltsétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 28, 'És laktok azon a földön, melyet adtam atyáitoknak, és lesztek nékem népem s én leszek néktek Istenetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 29, 'És megtartalak titeket minden tisztátalanságotoktól, és előhívom a gabonát és megsokasítom azt, és nem adok reátok éhséget.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 30, 'És megsokasítom a fa gyümölcsét és a mező termését, hogy többé ne viseljétek az éhségnek gyalázatját a pogányok között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 31, 'És megemlékeztek a ti gonosz útaitokról és cselekedeteitekről, melyek nem voltak jók, és megútáljátok ti magatokat vétkeitek és útálatosságaitok miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 32, 'Nem ti érettetek cselekszem, ezt mondja az Úr Isten, tudtotokra legyen! Piruljatok és szégyenüljetek meg útaitok miatt, Izráel háza!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 33, 'Ezt mondja az Úr Isten: Azon a napon, melyen megtisztítlak titeket minden vétketektől, azt cselekszem, hogy lakják a városokat, és a romok megépíttetnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 34, 'És az elpusztult földet mívelik, a helyett, hogy pusztán hevert minden átmenő szeme láttára;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 35, 'És ezek mondják: Ez a föld, ez az elpusztult, olyanná lett, mint az Éden kertje, és a rommá lett s elpusztult s lerontott városokat megerősítve lakják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 36, 'És megtudják a pogányok, a kik körülöttetek megmaradtak, hogy én, az Úr építettem meg a lerontottakat s plántáltam be a pusztaságot. Én, az Úr mondtam és megcselekedtem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 37, 'Így szól az Úr Isten: Még arra nézve is kérni hagyom magamat Izráel házának, hogy cselekedjem ő velök: Megsokasítom őket, mint a nyájat, emberekkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 38, 'Mint az áldozatra szentelt juhok, mint a Jeruzsálem juhai az ő ünnepein, így lesznek a rommá lett városok teljesek emberek nyájával; és megtudják, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 1, 'Lőn én rajtam az Úrnak keze, és kivitt engem az Úr lélek által, és letőn engem a völgynek közepette, mely csontokkal rakva vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 2, 'És átvitt engem azok mellett köröskörül, és ímé, felette sok vala a völgy színén, és ímé, igen megszáradtak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 3, 'És monda nékem: Embernek fia! vajjon megélednek-é ezek a tetemek? és mondék: Uram Isten, te tudod!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 4, 'És monda nékem: Prófétálj e tetemek felől és mondjad nékik: Ti megszáradt tetemek, halljátok meg az Úr beszédét!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 5, 'Így szól az Úr Isten ezeknek a tetemeknek: Ímé, én bocsátok ti belétek lelket, hogy megéledjetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 6, 'És adok reátok inakat, és hozok reátok húst, és bőrrel beborítlak titeket, és adok belétek lelket, hogy megéledjetek, és megtudjátok, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 7, 'És én prófétálék, a mint parancsolva vala nékem. És mikor prófétálnék, lőn zúgás és ímé zörgés, és egybemenének a tetemek, mindenik tetem az ő teteméhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 8, 'És látám, és ímé inak valának rajtok, és hús nevekedett, és felül bőr borította be őket; de lélek nem vala még bennök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 9, 'És monda nékem: Prófétálj a léleknek, prófétálj embernek fia, és mondjad a léleknek: Ezt mondja az Úr Isten: A négy szelek felől jőjj elő lélek, és lehelj ezekbe a megölettekbe, hogy megéledjenek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 10, 'És prófétálék a mint parancsolá. És beléjök méne a lélek s megéledének, s állának lábaikra, felette igen nagy sereg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 11, 'És monda nékem: Embernek fia! ezek a tetemek az Izráel egész háza. Ímé, ezt mondják: Elszáradtak a mi csontjaink és elveszett a mi reménységünk; kivágattunk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 12, 'Annakokáért prófétálj, és mondjad nékik: Így szól az Úr Isten: Ímé, én megnyitom a ti sírjaitokat és kihozlak titeket sírjaitokból, én népem! s beviszlek titeket Izráel földjére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 13, 'És megtudjátok, hogy én vagyok az Úr, mikor megnyitándom sírjaitokat és kihozlak titeket sírjaitokból, én népem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 14, 'És adom az én lelkemet belétek, hogy megéledjetek, és leteszlek titeket a ti földetekre, és megtudjátok, hogy én, az Úr, szóltam és megcselekedtem, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 15, 'És lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 16, 'És te, embernek fia, végy magadnak fát, és írd ezt reá: Júdáé és Izráel fiaié, az ő társaié; és végy egy másik fát, és írd ezt reá: Józsefé, Efraim fája és az egész Izráel házáé, az ő társaié.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 17, 'És tedd együvé azokat, egyiket a másikhoz egy fává, hogy egygyé legyenek kezedben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 18, 'És ha mondják néked a te néped fiai, mondván: Avagy nem jelented-é meg nékünk, mit akarsz ezekkel?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 19, 'Szólj nékik: Ezt mondja az Úr Isten: Ímé, én fölveszem a József fáját, mely Efraim kezében van, és Izráel nemzetségeit, az ő társait, és teszem őket ő hozzá, a Júda fájához, és összeteszem őket egy fává, hogy egygyé legyenek az én kezemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 20, 'És ha e fák, a melyekre írsz, kezedben lesznek szemök láttára:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 21, 'Szólj nékik: Ezt mondja az Úr Isten: Ímé, én fölveszem Izráel fiait a pogányok közül, a kik közé mentek, és egybegyűjtöm őket mindenfelől, és beviszem őket az ő földjökre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 22, 'És egy néppé teszem őket azon a földön, Izráelnek hegyein, és egyetlenegy király lesz mindnyájok királya, és nem lesznek többé két néppé, és ezután nem oszolnak többé két királyságra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 23, 'És többé meg nem fertéztetik magokat bálványaikkal és útálatosságaikkal és minden bűneikkel; és megtartom őket minden oly lakóhelyöktől, a melyekben vétkeztek, és megtisztítom őket, és lesznek nékem népem és én leszek nékik istenök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 24, 'És az én szolgám, Dávid lesz a király ő rajtok, s egy pásztora lesz mindnyájoknak; és az én törvényeim szerint járnak, s parancsolataimat megőrzik és cselekszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 25, 'És laknak a földön, melyet adtam vala az én szolgámnak, Jákóbnak, a melyen laktak a ti atyáitok; és laknak azon ők és fiaik és fiaiknak fiai mindörökké, és az én szolgám, Dávid az ő fejedelmök örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 26, 'És szerzek velök békességnek frigyét, örökkévaló frigy lesz ez velök; és elültetem őket és megsokasítom, és helyheztetem az én szenthelyemet közéjök örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 27, 'És lesz az én lakhelyem felettök, és leszek nékik Istenök és ők nékem népem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 28, 'És megtudják a pogányok, hogy én vagyok az Úr, ki megszentelem Izráelt, mikor szenthelyem közöttök lesz mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 1, 'És lőn az Úr beszéde hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 2, 'Embernek fia! vesd tekintetedet Góg ellen, és Mágóg földjén, Rós, Mések és Tubál fejedelme ellen, és prófétálj felőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 3, 'És mondjad: Ezt mondja az Úr Isten: Ímé, én ellened megyek Góg, Rós, Mések és Tubál fejedelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 4, 'És elcsalogatlak, és horgokat vetek szádba, és kivezetlek téged és egész seregedet, lovakat és lovagokat, kik mindnyájan teljes fegyverzetbe öltözvék, nagy sokaságot, nagy és kis paizszsal, fegyvert viselők mindnyájan;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 5, 'Perzsák, szerecsenek, libiaiak vannak velök, mindnyájan paizszsal és sisakkal;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 6, 'Továbbá Gómer és minden serege, Tógarma háza messze északról minden seregével, sok nép van veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 7, 'Készülj hozzá és készítsd elő magadat te és minden sokaságod, kik te hozzád gyűltek, és légy nekik vezérök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 8, 'Sok idő mulva kirendeltetel: esztendők végével bejösz a földre, mely a fegyvertől már megnyugodott, melynek lakói sok nép közül gyűjtettek egybe Izráel hegyeire, melyek szüntelen való pusztulásban voltak; és e nemzetség a népek közül hozatott ki, s aztán lakozék bátorságosan mindnyája;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 9, 'És feljösz, bemégy mint a szélvész, és leszel mint a felleg, hogy beborítsd a földet, te és minden sereged s a sok nép veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 10, 'Így szól az Úr Isten: És lészen abban az időben, hogy tanácsok támadnak szívedben, és gondolsz gondolatot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 11, 'És mondasz: Felmegyek a nyilt földre, jövök azokra, kik nyugalomban vannak s bátorságosan laknak; kik laknak mindnyájan kőfal-kerítés nélkül, sem zárjok, sem kapujok nincs nékik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 12, 'Hogy zsákmányt vess és prédát prédálj, hogy fordítsd kezedet a már népes pusztaságok ellen s a nép ellen, a mely a pogányok közül gyűjtetett egybe, mely jószágot és gazdagságot szerez s lakozik a földnek köldökén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 13, 'Séba és Dedán és Társis kalmárai és minden fiatal oroszlánja ezt mondják néked: Nemde te zsákmányt vetni jöttél? Nemde prédát prédálni gyűjtötted egybe sokaságodat? hogy elvigy ezüstöt és aranyat, magadhoz végy jószágot s gazdagságot, hogy nagy zsákmányt vess.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 14, 'Annakokáért prófétálj, embernek fia, és mondd ezt Gógnak: Így szól az Úr Isten: Avagy abban az időben, mikor az én népem, Izráel bátorságosan lakik, nem tudod-é meg?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 15, 'És eljössz helyedről, a messze északról te és sok nép veled, lovon ülők mindnyájan, nagy sokaság és hatalmas sereg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 16, 'És feljössz az én népem, Izráel ellen, mint a felleg, hogy beborítsd a földet, az utolsó időkben lészen ez, és hozlak téged az én földemre, hogy a pogányok megismerjenek engem, mikor megszentelem magamat rajtad az ő szemök láttára, Góg!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 17, 'Így szól az Úr Isten: Te vagy-é hát, a kiről szólottam a régi napokban az én szolgáim, Izráel prófétái által, kik prófétáltak azokban a napokban esztendőkön át, hogy téged ő reájok hozlak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 18, 'És lészen azon a napon, a mely napon Góg eljő Izráel földje ellen, ezt mondja az Úr Isten, felszáll haragom orromban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 19, 'És féltő szerelmemben, búsulásom tüzében szólok: Bizony azon a napon nagy földindulás lesz Izráel földjén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 20, 'És megremegnek előttem a tenger halai és az ég madarai és a mező vadai és a földön csúszó-mászó mindenféle állatok és minden ember a föld színén; és leszakadnak a hegyek, és leesnek a meredek kősziklák, és minden fal a földre hull.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 21, 'És előhívom ellene minden hegyem felől a fegyvert, ezt mondja az Úr Isten; egyiknek fegyvere a másik ellen lészen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 22, 'És törvénykezem vele döghalállal és vérrel; és ömlő záporesőt, jégeső köveit, tüzet és kénkövet, mint esőt bocsátok reá és seregére s a sok népre, a mely vele lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 23, 'És nagynak s szentnek mutatom, és megjelentem magamat a pogányok sokasága előtt, hogy megtudják, hogy én vagyok az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 1, 'És te, embernek fia, prófétálj Góg ellen, és mondjad: Így szól az Úr Isten: Ímé, én ellened megyek Góg, Rós, Mések és Tubál fejedelme!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 2, 'És elcsalogatlak és vezetgetlek, és felhozlak messze északról, és beviszlek Izráel hegyeire.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 3, 'És kiütöm kézívedet balkezedből, és nyilaidat jobbkezedből kiejtem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 4, 'Izráel hegyein esel el te és minden sereged és a népek, melyek veled lesznek; a ragadozó madaraknak, minden szárnyas állatnak és a mezei vadaknak adtalak eledelül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 5, 'A mező színén esel el, mert én szóltam, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 6, 'És bocsátok tüzet Mágógra és azokra, a kik a szigeteken bátorságosan laknak, hogy megtudják, hogy én vagyok az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 7, 'És az én szent nevemet megismertetem az én népem, Izráel között, s többé nem hagyom megfertéztetni szent nevemet; és megtudják a pogányok, hogy én, az Úr, szent vagyok Izráelben!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 8, 'Ímé, eljött és meglett, ezt mondja az Úr Isten; ez az a nap, a melyről szólottam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 9, 'És kimennek Izráel városainak lakói, és feltüzelik és felégetik a fegyvereket s a kis és nagy paizsokat, a kézívet és a nyilakat és a kézbeli pálczákat és dárdákat, és tüzelnek velök hét esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 10, 'És fát nem hordanak a mezőről, sem az erdőkről nem vágnak, hanem a fegyverekből tüzelnek, és zsákmányt vetnek zsákmányolóikban, s prédálóikat elprédálják, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 11, 'És lészen azon a napon, hogy adok Gógnak helyet, hol temetője legyen Izráelben, a vándorok völgyét keletre a tengertől, ez fogja bezárni e vándor népséget; és ott temetik el Gógot és minden gyülevészét, és nevezik Góg gyülevésze völgyének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 12, 'És eltemeti őket Izráel háza, hogy a földet megtisztítsa, hét álló hónapig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 13, 'És temetni fog az ország egész népe, s lészen ez nékik dicsőségökre a napon, melyen megdicsőítem magamat, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 14, 'És választanak embereket, kik a földet szüntelen bejárják, temetgetvén ama vándor népséget, azokat, kik még a föld színén maradtak, hogy azt megtisztítsák. Hét hónap mulva indulnak keresni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 15, 'És bejárják e járók a földet, és ha ki embertetemet lát, jelt állít melléje, míg a temetgetők eltemetik azt a Góg gyülevésze völgyében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 16, 'És egy városnak is Hamóna lesz a neve, és megtisztítják a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 17, 'És te, embernek fia, így szól az Isten, mondjad a madaraknak, minden szárnyas állatnak és minden mezei vadnak: Gyűljetek egybe és jőjjetek el, seregeljetek egybe mindenfelől az én áldozatomra, mert én nagy áldozatot szerzek néktek Izráel hegyein, és egyetek húst és igyatok vért!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 18, 'Vitézek húsát egyétek, s a föld fejedelmeinek vérét igyátok, kosok, bárányok és bakok, bikák, Básánban hízottak mindnyájan;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 19, 'S egyetek kövérséget jóllakásig, és igyatok vért megrészegedésig az én áldozatomból, a melyet szerzek néktek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 20, 'És lakjatok jól az én asztalomnál lovakból és paripákból, vitézekből és minden hadakozó férfiakból, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 21, 'És megmutatom az én dicsőségemet a pogányok között, és meglátják mindazok a pogányok az én ítéletemet, melyet cselekedtem, és az én kezemet, melyet rájok vetettem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 22, 'És megtudja Izráel háza, hogy én vagyok az Úr, az ő Istenök, attól a naptól fogva és azután.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 23, 'És megtudják a pogányok, hogy az ő vétke miatt vitetett fogságra Izráel háza, mivelhogy elpártolt tőlem, s én elrejtettem orczámat tőle; azért adtam őt ellenségei kezébe, és hullottak el fegyver miatt mindnyájan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 24, 'Az ő tisztátalanságuk s bűneik szerint cselekedtem velök, és elrejtettem orczámat tőlök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 25, 'Azért így szól az Úr Isten: Most már haza hozom Jákób foglyait, és megkegyelmezek Izráel egész házának, s féltő szerelemre gyulladok szent nevemért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 26, 'És elfelejtik gyalázatukat és minden vétköket, melylyel vétkeztek ellenem, mikor laknak földjökön bátorságosan, és őket senki sem rettegteti.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 27, 'Mikor visszahozom őket a népek közül, és egybegyűjtöm őket ellenségeik földjeiről, akkor megszentelem magamat bennök sok nép szeme láttára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 28, 'És megtudják, hogy én vagyok az Úr, az ő Istenök, ki fogságra vittem őket a pogányok közé, majd egybegyűjtém őket földjökre, és senkit közülök többé ott nem hagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 29, 'És többé el nem rejtem orczámat tőlök, mivelhogy kiöntöttem lelkemet Izráel házára, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 1, 'Huszonötödik esztendejében fogságunknak, az esztendőnek kezdetén, a hónap tizedikén, a tizennegyedik esztendőben az után, hogy a város megveretett, épen ezen a napon lőn az Úr keze én rajtam, és elvitt engemet oda.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 2, 'Isteni látásokban vitt engem Izráel földjére, és letőn engem egy igen magas hegyre, s azon vala mint egy város épülete dél felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 3, 'És oda vitt engem, és ímé egy férfiú vala ott, tekintete mint az ércznek tekintete, és len-zsinór vala kezében és mérőpálcza; és a kapuban áll vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 4, 'És szóla nékem az a férfiú: Embernek fia! láss szemeiddel és füleiddel hallj, és figyelmetes légy mindarra, a mit mutatok néked; mert hogy ezeket megmutassam néked, azért hozattál ide: hirdesd mindazokat, a miket látsz, Izráel házának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 5, 'És ímé, kőfal vala a házon kivül köröskörül; és a férfiú kezében a mérőpálcza vala hat singnyi (a közsingben s egy tenyérben); és méré az épület szélességét egy pálczányira s magasságát egy pálczányira.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 6, 'És méne egy kapuhoz, mely napkeletre néz vala, és felméne grádicsain, és méré a kapu küszöbét egy pálczányi szélességre, a másik küszöböt is egy pálczányi szélességre;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 7, 'És az őrkamarát egy pálczányi hosszúságra és egy pálczányi szélességre, és az őrkamarák közét öt singnyire, és a kapu küszöbét, a kapu tornácza mellett belől, egy pálczányira.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 8, 'És méré a kapu tornáczát belől egy pálczányira.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 9, 'És méré a kapu tornáczát nyolcz singnyire, és gyámoszlopait két singnyire; vala pedig a kapu tornácza belől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 10, 'És a napkeleti kapunak mind egyfelől, mind másfelől három-három őrkamarája vala, egy mértéke mind a háromnak, és egy mértékök a gyámoszlopoknak is mind egyfelől, mind másfelől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 11, 'És méré a kapu nyílásának szélességét tíz singre, és a kapu hosszúságát tizenhárom singre;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 12, 'És az őrkamarák előtt való korlátot egy singnyire, és egy singnyire vala e korlát másfelől is; mindenik őrkamara pedig hat singnyi vala egyfelől és hat singnyi másfelől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 13, 'És méré a kaput az egyik őrkamara tetejétől a másik tetejéig; huszonöt singnyi szélességre ott, hol ajtó ajtóval vala szemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 14, 'És tevé a gyámoszlopokat hatvan singre, és a gyámoszlopokhoz nyúlik vala a pitvar a kapunál körös-körül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 15, 'És a bejárat kapujának elejétől a belső kapu tornáczának elejéig vala ötven sing.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 16, 'És az őrkamarákon szoros ablakok valának, és gyámoszlopaikon is belül a kapuban köröskörül, hasonlóképen a tornáczokon; és valának ablakok köröskörül belől, és a gyámoszlopokon pálmafaragások.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 17, 'És vitt engem a külső pitvarba, és ímé, ott kamarák és kőből rakott pádimentom vala készítve a pitvaron köröskörül; harmincz kamara vala a kőből rakott pádimentomon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 18, 'És a kőből rakott pádimentom a kapuk mellett vala a kapuk hosszúsága szerint: az alsó kőből rakott pádimentom vala ez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 19, 'És méré a szélességet az alsó kapu elejétől fogva a belső pitvar külső elejéig száz singnyire, a keleti és északi oldalon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 20, 'És a kapunak is, mely néz vala északra, a külső pitvaron, megméré hosszúságát és szélességét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 21, 'És őrkamarái valának: három egyfelől és három másfelől, és gyámoszlopai és tornácza egy mértékben valának az első kapuval: ötven sing a hosszúsága, és szélessége huszonöt sing.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 22, 'És ablakai és tornácza és pálmafaragásai annak a kapunak mértéke szerint valának, mely néz napkeletre, és hét grádicson mennek vala fel hozzá; és tornáczai, e grádicsok előtt valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 23, 'És a belső pitvarnak kapuja vala az északi és napkeleti kapu ellenében, és mére kaputól kapuig száz singet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 24, 'És vitt engem a déli útra, és ímé, egy kapu vala ott dél felé, és megméré gyámoszlopait és tornáczát ugyanama mérték szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 25, 'És ablakai valának és tornáczának is köröskörül, olyanok mint amaz ablakok; hosszúsága ötven sing, és szélessége huszonöt sing.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 26, 'És hét grádicsa vala feljáratának, és tornácza azok előtt vala; és pálmafaragásai valának egyik egyfelől, a másik másfelől gyámoszlopain.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 27, 'És kapuja vala a belső pitvarnak dél felé, és mére kaputól kapuig dél felé száz singet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 28, 'És bevitt engemet a déli kapun át a belső pitvarba, és megméré a déli kaput ugyanama mértékek szerint;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 29, 'És őrkamaráit és gyámoszlopait és tornáczát ugyanama mértékek szerint, és ablakai valának és tornáczának is köröskörül, hosszúsága ötven sing, és szélessége huszonöt sing.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 30, 'És tornáczok valának köröskörül, hosszúságuk huszonöt sing, és szélességök öt sing.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 31, 'És tornácza a külső pitvar felé vala, és pálmafaragások valának gyámoszlopain, és nyolcz grádicsa vala feljáratának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 32, 'Vitt továbbá engem a belső pitvarba kelet felé, és megméré a kaput ugyanama mértékek szerint;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 33, 'És őrkamaráit és gyámoszlopait és tornáczát ugyanama mértékek szerint, és ablakai valának és tornáczának is köröskörül, hosszúsága ötven sing, és szélessége huszonöt sing.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 34, 'És tornácza vala a külső pitvar felé, és gyámoszlopain pálmafaragások valának mind egy-, mind másfelől, és nyolcz grádicsa vala feljáratának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 35, 'És vitt engem az északi kapuhoz, és megméré ugyanama mértékek szerint;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 36, 'Őrkamaráit, gyámoszlopait és tornáczát, és ablakai valának köröskörül, hosszúsága ötven sing, és szélessége huszonöt sing.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 37, 'És tornácza a külső pitvar felé vala, és pálmafaragások valának gyámoszlopain mind egyfelől, mind másfelől, és nyolcz grádicsa vala feljáratának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 38, 'És egy kamara vala, és annak ajtaja a kapuk gyámoszlopainál; ott mossák vala meg az egészen égőáldozatot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 39, 'És a kapu tornáczában két asztal vala egyfelől, és másfelől is két asztal vala, hogy azokon öljék meg az egészen égőáldozatot és a bűnért való áldozatot és a vétekért való áldozatot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 40, 'És oldalt kivül, északra onnét, hol felmennek a kapu ajtajához, két asztal vala, és a kapu tornáczának másik oldalán is két asztal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 41, 'Négy asztal egyfelől, és másfelől is négy asztal a kapu oldalán; nyolcz asztal, ezeken ölik vala az áldozatot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 42, 'És négy asztal vala az égőáldozatra faragott kőből, másfél sing hosszú és másfél sing széles és egy sing magas; ezekre teszik a szerszámokat, melyekkel az égőáldozatot és egyéb áldozatot ölnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 43, 'És a szegek valának egy tenyérnyiek, oda erősítve belől köröskörül, s az asztalokra jöve az áldozat húsa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 44, 'A belső kapun kivül pedig vala két kamara az énekesek számára a belső pitvarban, egyik oldalt az északi kaputól, melynek eleje dél felé vala, s a másik oldalt a déli kaputól, melynek eleje észak felé vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 45, 'És szóla nékem: Ez a kamara, mely délre néz, a papoké, kik a házhoz való szolgálatban foglalatosak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 46, 'Az a kamara pedig, mely északra néz, azoké a papoké, kik az oltárhoz való szolgálatban foglalatosak, ezek a Sádók fiai, kik az Úrhoz járulnak a Lévi fiai közül, hogy szolgáljanak néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 47, 'És megméré a pitvart; hosszúsága száz sing és szélessége is száz sing, négyszögre; és az oltár vala a ház előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 48, 'És vitt engem a ház tornáczába, és a tornácz gyámoszlopát megméré egyfelől is öt singre, másfelől is öt singre; a kapu szélességét pedig három singre egyfelől s másfelől is három singre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 49, 'A tornácz hosszúsága húsz sing vala és a szélessége tizenegy sing, és tíz grádicson mennek vala föl hozzá; és oszlopok valának a gyámoszlopoknál, egyik egyfelől, másik másfelől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 1, 'És bevitt engem a templomba, és megméré a gyámoszlopokat, hat sing széles vala egyfelől és hat sing széles másfelől a gyámoszlopok szélessége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 2, 'És az ajtó szélessége tíz sing vala, és az ajtó oldalfalai öt sing egyfelől és öt sing másfelől; és megméré hosszúságát is negyven singre, szélességét pedig húsz singre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 3, 'És beméne belsejébe, és megméré az ajtó gyámoszlopait két singre, és az ajtót hat singre, és az ajtó oldalfalait hét singre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 4, 'És megméré hosszúságát húsz singre, és szélességét húsz singre a templom felé, és mondá nékem: Ez a szentek szentje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 5, 'És megméré a ház falát hat singre, és az oldalépület szélességét négy singre a ház körül mindenfelől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 6, 'És az oldalkamarák, egyik kamara a másikon, harminczan valának három sorban, és a háznak azon falához nyúlának, mely az oldalkamarák felől vala, köröskörül, hogy azon erősen álljanak, de nem magába a falba valának erősítve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 7, 'És vala kiszélesedése és megnagyobbodása az oldalkamaráknak a magasságban fölfelé, mivel megnagyobbodása vala a háznak fölfelé a magasságban köröskörül a házon, ezért lőn kiszélesedése az épületnek fölfelé. És az alsó sorról menének föl a felsőhöz és a középsőhöz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 8, 'És láték a háznál valami magasságot köröskörül, fundamentoma ez az oldalkamaráknak, egy teljes pálczányi, hat singnyire a fal tövének párkányáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 9, 'Az oldalkamara külső falának szélessége pedig öt singnyi vala. És a mi üresen maradt a ház oldalkamrái között,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 10, 'És a kamarák közt húsz singnyi szélesség vala a ház körül köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 11, 'És az oldalépületnek ajtaja az üresen maradt hely felé vala, egyik ajtó északra és a másik ajtó délre, és a szabadon hagyott hely szélessége öt singnyi vala köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 12, 'És az épület, mely az elkülönített hely előtt, nyugot felé vala, hetven singnyi széles vala, s az épület fala öt singnyi széles köröskörül, hosszúsága pedig kilenczven sing.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 13, 'És méré a háznak hosszát száz singre, és az elkülönített helyet s az épületet és falait száz sing hosszúságra;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 14, 'És a ház és az elkülönített hely elejének szélességét kelet felé száz singre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 15, 'És méré az épület hosszúságát az elkülönített hely felé, mely ennek háta mögött vala, és ennek folyosóit mind egyfelől, mind másfelől száz singre. És magában a templomban és a belső helyen és a külső tornáczban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 16, 'A küszöbök és a szoros ablakok és a folyosók valának mind hármuk körül, szemben a küszöbbel, simított fadeszkákból köröskörül. A földtől az ablakokig, az ablakok pedig befedve valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 17, 'Az ajtónak felső részéig és a belső házig és kifelé és az egész falon köröskörül a belső és külső helyen minden mérték szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 18, 'Készítve valának továbbá Kérubok és pálmafaragások, és mindenik pálmafaragás vala két Kérub között, és mindenik Kérubnak két orczája vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 19, 'És emberorcza néz vala a pálmafaragásról egyfelől, és oroszlánorcza a másik pálmára másfelől. Így vala készítve az egész házon köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 20, 'A földtől fogva az ajtó felső részéig Kérubok és pálmafaragások valának készítve a falon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 21, 'A szenthelynek ajtófélfái négyszegűek valának, és a szentek szentje előtt vala mint egy oltárnak a formája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 22, 'Fából, három sing magas és két sing hosszú, szegletei valának és talpa, és falai fából valának. És mondá nékem: Ez az asztal, mely az Úr előtt áll.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 23, 'És kettős ajtói valának a szenthelynek és a szentek szentjének,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 24, 'És kettős ajtói valának az ajtószárnyaknak, két forgó ajtóik, kettő az egyik ajtószárnyban és két ajtó a másikban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 25, 'És készítve valának rajtok, a szenthely ajtóin, Kérubok és pálmák, mint valának készítve a falakon, és faküszöb vala a tornácz előtt kivül;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 26, 'És szoros ablakok és pálmák valának mind egy- s mind másfelől a tornácz oldalfalain. Így voltak a ház oldalkamarái és a gerendák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 1, 'És kivitt engem a külső pitvarba az északi úton és vitt engem a kamarák épületéhez, mely az elkülönített hely ellenében és az épület ellenében észak felé vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 2, 'A száz sing hosszú oldal elé az északi oldalra, és vala ötven sing a szélessége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 3, 'A húsz singnek ellenében, mely a belső pitvarhoz tartozék, és a kőből rakott pádimentom ellenében, mely a külső udvarhoz tartozék, folyosó vala folyosó ellenében három sorban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 4, 'És a kamarák előtt tíz sing széles út vala befelé, hosszúsága száz sing; és ajtaik észak felé valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 5, 'És a felső kamarák rövidebbek valának az épület alsó és középső kamaráinál, mert a folyosók elvettek belőlök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 6, 'Mivelhogy három sorban valának és nem valának oszlopaik, mint a pitvaroknak; ezért lőn az alsókhoz és a középsőkhöz képest elvéve a helyből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 7, 'És egy fal, mely kivül vala, párhuzamosan a kamarákkal a külső pitvar felé, a kamarák előtt, ötven sing hosszú vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 8, 'Mert a kamarák hosszúsága, melyek a külső pitvar felé valának, ötven sing vala, és ímé, a szenthely ellenében száz sing vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 9, 'És e kamarák alatt vala a bejáró hely napkelet felől, ha beléjök a külső pitvarból méne valaki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 10, 'A pitvar falának szélességében dél felé az elkülönített hely és az épület előtt is kamarák valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 11, 'És egy út vala előttök, melyek hasonlatosak valának a kamarákhoz, melyek északra valának, olyan hosszúságúak és olyan szélességűek, mint ezek, és minden kijárásuk és elrendezésök olyan vala, mint ezeké. És valamint amazoknak ajtói,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 12, 'Akképen valának azoknak a kamaráknak ajtói is, melyek dél felé valának: egy ajtó kezdetén az útnak, annak az útnak, mely a megfelelő fal előtt kelet felé vala, ha valaki hozzájok méne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 13, 'És monda nékem: Az északi és a déli kamarák, melyek az elkülönített hely előtt vannak, azok a szent kamarák, melyekben a papok, kik az Úrhoz közelednek, eszik az igen szentséges áldozatokat, ott rakják le az igen szentséges áldozatokat, az eledeli, a bűnért való és a vétekért való áldozatot; mert szent az a hely.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 14, 'Mikor bemennek oda a papok, ki ne jőjjenek a szent helyről a külső pitvarba, hanem ott rakják le ruháikat, melyekben szolgáltak; mert szentek ezek, és más ruhába öltözzenek, úgy közeledjenek a nép helyéhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 15, 'És mikor a belső háznak méréseit véghezvitte, kivitt engem a napkelet felől való kapu útján, és megméré azt köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 16, 'Méré a keleti oldalt a mérőpálczával ötszáz singnyire, a mérőpálczával. És megfordula, és');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 17, 'Méré az északi oldalt ötszáz singnyire a mérőpálczával. És megfordula,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 18, 'A déli oldal felé, és mére ötszáz singet a mérőpálczával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 19, 'Fordula aztán a nyugoti oldal felé, és mére ötszáz singet a mérőpálczával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 20, 'Mind a négy szél irányában méré azt. Kőfala vala köröskörül, hosszúsága ötszáz, szélessége is ötszáz sing, hogy elválaszsza a szentet a köztől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 1, 'És vitt engem a kapuhoz, ahhoz a kapuhoz, a mely napkelet felé néz vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 2, 'És ímé, Izráel Istenének dicsősége jő vala napkelet felől, és zúgása, mint nagy víz zúgása, és a föld világos vala az ő dicsőségétől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 3, 'És a jelenség, melyet láttam, olyan vala, mint az a jelenség, melyet akkor láttam, mikor menék a várost elveszteni; és olyan látások valának, mint az a jelenség, melyet a Kébár folyó mellett láttam. És orczámra esém.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 4, 'És az Úr dicsősége beméne a házba a kapunak útján, mely néz napkeletre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 5, 'És fölemele engem a lélek, és bevitt engem a belső pitvarba, és ímé, az Úr dicsősége betölté a házat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 6, 'És hallám, hogy valaki beszélget hozzám a házból, holott ama férfiú mellettem áll vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 7, 'És mondá nékem: Embernek fia! ezt az én királyi székemnek helyét és lábaim talpainak helyét, a hol lakom Izráel fiai között örökké, és itt az én szent nevemet többé meg ne fertéztesse Izráel háza, ők és királyaik paráznaságukkal és királyaik holttesteivel, magaslataikkal,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 8, 'Mikor küszöbüket az én küszöböm mellé és ajtófélfáikat az én ajtófélfáim mellé tették, és csak a fal vala köztem és közöttök; és megfertéztették az én szent nevemet útálatosságaikkal, melyeket cselekedtek, ezokáért elvesztém őket haragomban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 9, 'Most már eltávoztatják paráznaságukat és királyaik holttesteit tőlem, és ő köztök lakozom mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 10, 'Te, embernek fia, hirdessed Izráel házának ezt a házat, hogy piruljanak vétkeik miatt. És mérjék utána arányosságát;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 11, 'És ha pirulni fognak mind a miatt, a mit cselekedtek: e ház formáját és berendezését, kijáratait és bejáratait és minden formáit és minden rendeléseit és minden formáit és minden törvényeit jelentsd meg nékik és írd meg szemeik előtt, hogy megtartsák minden formáját és minden rendeléseit, s azokat cselekedjék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 12, 'Ez a ház törvénye: A hegy tetején egész határa köröskörül igen szentséges. Ímé, ez a ház törvénye.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 13, 'És ezek az oltár mértékei singek szerint (egy sing tesz egy közsinget és egy tenyért): talpa vala egy sing magas és egy sing széles, korlátja pedig a szélén köröskörül egy arasznyi. És ez az oltár magassága:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 14, 'A földön való talptól az alsó bekerítésig két sing s szélessége egy sing, és a kisebb bekerítéstől a nagyobb bekerítésig négy sing és szélessége egy sing;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 15, 'És az Istenhegye négy sing, és az Isten-tűzhelyétől fölfelé a szarvak egy sing.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 16, 'És az Isten-tűzhelyének hosszúsága tizenkét sing vala tizenkét sing szélesség mellett, négyszögben négy oldala szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 17, 'És a bekerítés vala tizennégy sing hosszú, tizennégy sing szélesség mellett, négy oldala szerint; és a korlát köröskörül rajta fél sing. És talpa vala egy sing köröskörül. És grádicsai napkeletre néztek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 18, 'És mondá nékem: Embernek fia, ezt mondja az Úr Isten: Ezek az oltár rendtartásai: Azon a napon, mikor elkészül, hogy égőáldozattal áldozzanak rajta és vért hintsenek reá,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 19, 'Adj a papoknak, a Lévitáknak, kik a Sádók magvából valók, a kik járulhatnak én hozzám, ezt mondja az Úr Isten, hogy szolgáljanak nékem, egy fiatal bikát bűnért való áldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 20, 'És végy véréből, és tedd az oltár négy szarvára és a bekerítés négy szegletére és a korlátra köröskörül, és tisztísd meg azt, és szenteld meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 21, 'És vegyed a bikát, mely a bűnért való áldozat, és égesd meg azt a háznak erre rendelt helyén, a szenthelyen kivül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 22, 'Másodnap pedig vígy egy ép kecskebakot bűnért való áldozatul, és tisztítsák meg vele az oltárt, mint a fiatal bikával megtisztították.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 23, 'Mikor elvégezed az oltár megtisztítását, vígy áldozatul egy ép, fiatal bikát és egy ép kost a nyájból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 24, 'És áldozzál velök az Úr előtt, és a papok hintsenek sót reájok, és vigyék azokat égőáldozatul az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 25, 'Hét napig mindennap egy-egy bakot hozz bűnért való áldozatul, és egy fiatal bikát és egy kost a nyájból, mint épeket hozzák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 26, 'Hét napon át szenteljék és tisztítsák meg az oltárt és töltsék meg kezét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 27, 'És betöltsék e napokat; a nyolczadik napon és azután pedig áldozzák a papok az oltáron égőáldozataitokat és hálaadó áldozataitokat, és én kegyelmesen fogadlak titeket, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 1, 'És visszavitt engem a szenthely külső kapujának útjára, mely keletre néz vala; és az zárva volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 2, 'És monda nékem az Úr: Ez a kapu be lesz zárva, meg nem nyílik és senki rajta be nem megy, mert az Úr, az Izráel Istene ment be rajta, azért be lesz zárva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 3, 'A fejedelem pedig, ő a fejedelem benne üljön, hogy kenyeret egyék az Úr előtt; e kapu tornáczának útján menjen be és ennek útján menjen ki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 4, 'És bevitt engem az északi kapu útján a ház eleibe, és látám, és ímé, az Úr háza betelék az Úr dicsőségével, és orczámra esém.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 5, 'És monda nékem az Úr: Embernek fia, figyelmetes légy, és lásd szemeiddel, és füleiddel halld meg, valamiket én szólok te veled az Úr házának minden rendtartásairól és minden törvényéről, és légy figyelmetes a háznak bejáratára a szenthelynek minden kijáratánál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 6, 'És mondjad a pártosnak, Izráel házának: Így szól az Úr Isten: Elég legyen immár néktek minden útálatosságtok, Izráel háza!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 7, 'Mikor idegeneket, körülmetéletlen szívűeket és körülmetéletlen testűeket engedtetek bemenni, hogy szenthelyemen legyenek, hogy megfertéztessék azt, az én házamat; mikor áldozatra fölvittétek kenyeremet, a kövérséget és vért: ekkor megtörtétek az én frigyemet minden útálatosságtokon felül;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 8, 'És nem voltatok foglalatosak a szentségeimhez való szolgálatban, hanem azokat tettétek foglalatosakká szolgálatomban az én szenthelyemen, magatok helyett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 9, 'Így szól az Úr Isten: Senki idegen körülmetéletlen szívű és körülmetéletlen testű be ne menjen az én szenthelyemre, mindazon idegenek közül, a kik Izráel fiai között vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 10, 'Sőt még a Léviták is, kik eltávoztak én tőlem, mikor Izráel eltévelyedék (a kik eltévelyedtek én tőlem bálványaik után), viseljék vétköket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 11, 'És legyenek szenthelyemben szolgák a ház kapuinak őrizetére, és legyenek szolgák a házban: ők öljék le az égőáldozatot és egyéb áldozatot a népnek, és ők álljanak előttök, hogy szolgáljanak nékik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 12, 'Mivelhogy szolgáltak nékik bálványaik előtt, és lőnek Izráel házának vétekre csábítói: ezért emeltem föl kezemet ellenök, ezt mondja az Úr Isten, hogy viseljék vétköket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 13, 'Ne közeledjenek hozzám, hogy nékem, mint papok szolgáljanak, és hogy minden szentségemhez járuljanak, a szentségek szentségeihez; hanem viseljék gyalázatukat és útálatosságaikat, melyeket cselekedtek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 14, 'És teszem őket foglalatosakká a házhoz való szolgálatban, annak minden szolgálatánál, és mindannál, a mit abban cselekedni kell.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 15, 'De azok a lévita-papok, a Sádók fiai, a kik a szenthelyemhez való szolgálatomban foglalatosak voltak, mikor Izráel fiai eltévelyedtek tőlem, ők járuljanak én hozzám, hogy szolgáljanak nékem és álljanak én előttem, hogy áldozzanak nékem kövérséggel és vérrel, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 16, 'Ők járjanak be az én szenthelyembe, és járuljanak az én asztalomhoz, hogy szolgáljanak nékem, és legyenek foglalatosak az én szolgálatomban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 17, 'És mikor a belső pitvar kapuihoz be akarnak menni, len-ruhába öltözzenek, és gyapjú ne legyen rajtok, ha a belső pitvar kapuiban és a házban szolgálnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 18, 'Len-süveg legyen fejökön, és len alsó-nadrág derekukon; ne övezkedjenek izzadásig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 19, 'Mikor pedig kimennek a külső pitvarba, a külső udvarba a néphez, vessék le ruháikat, a melyekben szolgáltak, és tegyék le azokat a szent kamarákban, és öltözzenek más ruhákba, hogy meg ne szenteljék a népet ruháikkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 20, 'És fejöket kopaszra ne nyírják, de nagy hajat se neveljenek, hanem hajokat megegyengessék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 21, 'És senki a papok közül bort ne igyék, mikor a belső udvarba bemennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 22, 'És özvegyet vagy eltaszítottat feleségül magoknak ne vegyenek, hanem szűzeket Izráel házának magvából; de olyan özvegyet, ki papnak özvegye, elvehetnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 23, 'És az én népemet tanítsák, hogy mi a különbség szent és köz között, és a tisztátalan és tiszta között való különbséget ismertessék meg velök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 24, 'És peres ügyben ők álljanak elő ítélni, az én törvényeim szerint ítéljék meg azt; és tanításaimat s rendeléseimet megtartsák minden ünnepemen, és az én szombataimat megszenteljék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 25, 'És holt emberhez be ne menjen, hogy magát megfertéztesse, csak atyjáért és anyjáért és fiáért és leányáért és fiútestvéréért és leánytestvéréért, kinek még férje nem volt, fertéztetheti meg magát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 26, 'És megtisztulása után számláljanak néki hét napot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 27, 'És a mely napon bemegy a szenthelyre, a belső pitvarba, hogy szolgáljon a szenthelyen, mutassa be bűnért való áldozatát, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 28, 'És lészen nékik örökségök: én vagyok az ő örökségök, és birtokot ne adjatok nékik Izráelben: én vagyok az ő birtokuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 29, 'Az ételáldozat és a bűnért és vétekért való áldozat, ez legyen élésök, és valami Izráelben Istennek szenteltetik, minden az övék legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 30, 'És minden első termés zsengéje mindenből, és minden, mit áldozatra visztek mindenből, tudniillik minden áldozatotokból, legyen a papoké, és lisztjeitek zsengéjét adjátok a papnak, hogy áldás nyugodjék házadon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 31, 'Semmi döglöttet és vadtól szaggatottat, akár madár, akár egyéb állat legyen, ne egyenek a papok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 1, 'És mikor a földet sorsvetéssel elosztjátok örökségül, adjatok áldozatot az Úrnak, szent részt a földből; hosszúsága legyen huszonötezer és szélessége tízezer sing, szent legyen az egész határában köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 2, 'Ebből legyen a szenthelyé ötszáz sing, ötszáz singgel mérve egy négyszög minden oldalát, és mellette ötven sing tágasság legyen minden oldalon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 3, 'És ebből a megmért helyből mérj ki huszonötezer sing hosszúságot és tízezer sing szélességet, és ebben lesz a szenthely, mint igen szent hely.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 4, 'Szent rész ez a földből; legyen a papoké, a szenthely szolgáié, a kik ide járulnak szolgálni az Urat; és legyen ez nékik házaik helye, és szent hely a szenthely számára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 5, 'És huszonötezer sing hosszában és tízezer sing széltében legyen a Lévitáké, a ház szolgáié tulajdonukul, húszkamarául,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 6, 'És a város tulajdonául adjatok ötezer sing szélességet és huszonötezer sing hosszúságot a szent áldozat mentén; az egész Izráel házáért legyen ez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 7, 'És a fejedelem tulajdona lészen a szent áldozatnak és a város tulajdonának mind a két oldalán a szent áldozat előtt és a város tulajdona előtt a napnyugoti oldalon nyugotra és a napkeleti oldalon keletre, és hosszúsága olyan lesz, mint a részek közül egyé, a napnyugoti határtól a napkeleti határig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 8, 'Földje legyen az néki, tulajdona Izráelben; és többé ne sanyargassák fejedelmeim az én népemet, hanem adják át a többi földet Izráel házának az ő nemzetségei szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 9, 'Ezt mondja az Úr Isten: Legyen elég már néktek, Izráel fejedelmei! A törvénytelenséget és erőszaktételt távoztassátok el, és cselekedjetek törvény szerint és igazságot. Vegyétek le népemről sarczolástokat, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 10, 'Igaz mérőserpenyőitek legyenek és igaz éfátok és igaz báthotok:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 11, 'Az éfa és a báth egy mértékűek legyenek, úgy hogy a hómernek tizedét fogadja be a báth, és a hómernek tizede legyen az éfa, a hómerhez kell mértéköket igazítani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 12, 'És a sekelnek húsz gérája legyen; húsz sekel, huszonöt sekel, tizenöt sekel legyen a mina nálatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 13, 'Ez az áldozat, melyet fel kell vinnetek: egy hómer búzából egy hatodrész éfa, és egy hómer árpából is az éfa hatodrészét adjátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 14, 'És az olajból rendelt rész egy báth olajból: a báth tizede a kórból, tíz báthból, egy hómerből, mert tíz báth egy hómer.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 15, 'És egy darab a nyájból, kétszáz darab után Izráel bővizű földjéről ételáldozatra és égőáldozatra és hálaadó áldozatokra, az ő megszentelésökre, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 16, 'A földnek egész népe köteles legyen erre az áldozatra a fejedelem részére Izráelben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 17, 'A fejedelem tiszte pedig lészen, hogy vigyen egészen égőáldozatokat és ételáldozatot és italáldozatot az ünnepeken és az újholdak napján és a szombatokon, Izráel házának minden ünnepein: ő teljesítse a bűnért való áldozatot és az ételáldozatot és az egészen égőáldozatot és a hálaadó áldozatokat, hogy megszentelje Izráel házát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 18, 'Ezt mondja az Úr Isten: Az első hónapban, a hónap elsején végy egy fiatal, hibátlan bikát és tisztítsd meg a szenthelyet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 19, 'És vegyen a pap a bűnért való áldozat véréből, és hintse a ház ajtófélfáira és az oltár bekerítésének négy szegletére és a belső pitvar kapufélfáira.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 20, 'És így cselekedjél a hónap hetedik napján a tudatlanságból vétkezőért és a vigyázatlanságért, és így tisztítsátok meg a házat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 21, 'Az első hónapban, a hónap tizennegyedik napján legyen a ti páskátok; a hét napos ünnepen kovásztalan kenyeret egyetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 22, 'És a fejedelem azon a napon áldozzék ő magáért és a föld egész népéért egy bikával, bűnért való áldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 23, 'És az ünnep hét napján tegyen egészen égőáldozatot az Úrnak hét bikával és hét kossal, épekkel, naponként hét napon át, és bűnért való áldozatot egy kecskebakkal naponként;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 24, 'És ételáldozatul tegyen egy éfát a bika mellé és egy éfát a kos mellé, és az olajból egy hínt az éfához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 25, 'A hetedik hónapban, a hónap tizenötödik napján, az ünnepen hasonlóképen cselekedjék hét napon át: a bűnért való áldozattal, az egészen égőáldozattal, az ételáldozattal és az olajjal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 1, 'Ezt mondja az Úr Isten: A belső pitvar kapuja, mely keletre néz, zárva legyen a dologtevő hat napon, szombatnapon pedig nyissák ki, és újhold napján is nyissák ki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 2, 'És a fejedelem jőjjön be a kapu tornáczának útján kívülről, és álljon a kapu félfája mellé, és mikor a papok megáldozzák az ő égőáldozatát és hálaadóáldozatait, ő leborulva imádkozzék a kapu küszöbén, azután menjen ki, a kaput pedig ne zárják be estvéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 3, 'És leborulva imádkozzék az ország népe ugyanannak a kapunak bejáratánál a szombatokon és az újholdnak napjain az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 4, 'Az égőáldozat pedig, melyet a fejedelem vigyen az Úrnak szombatnapon, hat ép bárány és egy ép kos legyen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 5, 'És az ételáldozat: egy éfa a kos mellé; és a bárányok mellé ételáldozatul, a mit keze adhat, s az olajból egy hín az éfához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 6, 'Az újhold napján pedig egy ép, fiatal bika és hat bárány és egy kos, mind épek legyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 7, 'És a bika mellé egy éfát és a kos mellé egy éfát tegyen ételáldozatul; és a bárányok mellé azt, a mi kezétől telik, s az olajból egy hínt az éfához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 8, 'És mikor bemegy a fejedelem, a kapu tornáczának útján menjen be, és ezen az úton menjen ki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 9, 'Mikor pedig a föld népe megyen be az Úr eleibe az ünnepeken, a ki az északi kapu útján ment be, hogy leborulva imádkozzék, a déli kapu útján menjen ki; a ki pedig a déli kapu útján ment be, az az északi kapu útján menjen ki; ne térjen vissza azon kapu útjához, a melyen bement, hanem az annak ellenében valón menjen ki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 10, 'A fejedelem pedig, mikor bemennek, közöttök menjen be, és mikor kimennek, együtt menjen ki velök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 11, 'És az ünnepeken és a szent egybegyűléseken legyen az ételáldozat egy éfa egy bika mellé és egy éfa a kos mellé, és a bárányok mellé, a mit keze adhat, s az olajból egy hín az éfához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 12, 'Továbbá, mikor a fejedelem szabad akaratból tesz égőáldozatot, vagy hálaadó áldozatokat, szabad akaratból az Úrnak, nyissák ki néki a kaput, mely napkeletre néz, és ő vigye égőáldozatát és hálaadó áldozatait, mint a hogy szombat napon szokta tenni, és azután menjen ki, és zárják be a kaput kimenése után.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 13, 'És egy esztendős ép bárányt áldozz égőáldozatul naponként az Úrnak; minden reggel áldozz azzal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 14, 'És ételáldozatot tégy hozzá minden reggel: egy hatodrész éfát, és az olajból a hín harmadrészét a liszt megnedvesítésére, ételáldozatul az Úrnak; örökre állandó rendelések ezek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 15, 'Hozzátok azért a bárányt és az ételáldozatot és az olajat minden reggel állandó égőáldozatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 16, 'Ezt mondja az Úr Isten: Ha a fejedelem ajándékot ad valamelyik fiának a maga örökségéből, az az ő fiaié legyen tulajdonul örökségképen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 17, 'De ha örökségéből valamelyik szolgájának ad ajándékot, az a szabadság esztendejéig lesz azé, azután visszaszáll a fejedelemre; csak az ő öröksége lesz az ő fiaié.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 18, 'És a fejedelem el ne vegyen a nép örökségéből, hogy nyomorgatással kivesse őket tulajdonukból; a maga tulajdonából adjon örökséget fiainak, hogy az én népem közül senki el ne széledjen a maga tulajdonából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 19, 'És bevitt engem ahhoz a bejárathoz, mely a kapu mellett oldalaslag vala, a kamarákhoz, a papok szenthelyéhez, melyek északra néznek, és ímé, ott egy hely vala leghátul nyugotra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 20, 'És monda nékem: Ez a hely, a hol a papok főzzék a vétekért és a bűnért való áldozatot, és a hol süssék az ételáldozatot, hogy ne kelljen kivinniök a külső pitvarba a nép megszentelésére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 21, 'És kivitt engem a külső pitvarba, és elhordoza engem a pitvar négy szegletén, és ímé, a pitvar mindenik szegletében egy-egy pitvar vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 22, 'A pitvarnak négy szegletében zárt pitvarok valának, negyven sing hosszúságúak és harmincz sing szélesek; egy mértéke vala a négy szegleten való pitvaroknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 23, 'És falazások valának bennök köröskörül mind a négy körül, és a falazások alatt konyhák valának csinálva köröskörül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 24, 'És monda nékem: Ez a főzőház, a hol főzzék a háznak szolgái a nép véres áldozatát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 1, 'És visszatéríte engem a ház ajtajához, és ímé, víz jő vala ki a ház küszöbe alól napkelet felé, mert a ház eleje kelet felé vala, és a víz aláfoly vala a ház jobb oldala alól az oltártól délre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 2, 'És kivitt engem az északi kapu útján, és elhordoza engem a kivül való úton a külső kapuhoz, mely napkeletre néz, és ímé, a víz ott forr vala ki a jobb oldal alól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 3, 'Mikor kiméne az a férfiú napkelet felé, mérőzsinórral a kezében, mére ezer singet; és átvitt engem a vizen, a víz bokáig ér vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 4, 'És mére ismét ezeret, és átvitt engem a vizen, a víz pedig térdig ér vala. És mére ismét ezeret és átvitt engem s a víz derékig ér vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 5, 'És mére még ezeret, s vala olyan folyó, hogy át nem meheték rajta, mert magas vala a víz, megúszni való víz, folyó, mely meg nem lábolható.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 6, 'És monda nékem: Láttad-é, embernek fia? És visszavezete engem a folyó partján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 7, 'És mikor visszatértem, ímé, a folyó partján igen sok fa vala mindkét felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 8, 'És mondá nékem: Ez a víz a keleti tájékra foly ki, és a lapáczra megyen alá, és a tengerbe megyen be, a tengerbe szakad, és meggyógyul a víz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 9, 'És lészen, hogy minden élő állat, a mely nyüzsög, valahova e folyam bemegyen, élni fog; és a halaknak nagy bőségök lészen, mert ez a víz bement oda, és azok meggyógyulnak, és él minden, valahova e folyó bement.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 10, 'És lészen, hogy halászok állanak rajta Éngeditől Énegláimig: varsák kivető helye lészen; nemök szerint lesznek benne a halak, mint a nagy tenger halai, nagy bőséggel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 11, 'Mocsarai és tócsái pedig nem gyógyulnak meg, só helyei lesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 12, 'És a folyó mellett, mind a két partján mindenféle ennivaló gyümölcs fája nevekedik fel; leveleik el nem hervadnak és gyümölcseik el nem fogynak; havonként új meg új gyümölcsöt teremnek, mert vizök onnét a szenthelyből foly ki; és gyümölcsük eledelre és leveleik orvosságra valók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 13, 'És monda az Úr Isten: Ez a határ, a mely szerint örökségül osszátok el magatok közt a földet Izráel tizenkét törzsöke szerint, Józsefnek két örökséget.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 14, 'És vegyétek azt örökségül mindnyájan egyenlően, mivelhogy fölemeltem kezemet, hogy atyáitoknak adom azt, tehát essék néktek az a föld örökségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 15, 'És ez legyen a föld határa, észak felé a nagy-tengertől, Hetlónon át Sedádnak menve:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 16, 'Hamát, Berótha, Szibraim, mely Damaskus határa és Hamát határa közt van, a középső Hásér, mely Havrán határán van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 17, 'Így legyen a határ a tengertől Haczar-Énónig Damaskus határán és azontúl északra, és Hamát határán: ez az északi oldal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 18, 'És a keleti oldalon: Havrán és Damaskus és Gileád között és Izráel földje között a Jordán legyen; ama határtól a keleti tengerig mérjétek: ez a keleti oldal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 19, 'És a déli oldalon dél felé: Támártól a versengések vizéig Kádesben, azután a folyó felé a nagy-tengerig: ez a déli oldal dél felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 20, 'És a nyugoti oldal: a nagy-tenger, ama határtól fogva addig, a hol egyenesen Hamátba menni: ez a nyugoti oldal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 21, 'És oszszátok el ezt a földet magatok közt Izráel nemzetségei szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 22, 'És legyen, hogy sorsvetéssel oszszátok el azt magatok közt és a jövevények közt, a kik közöttetek lakoznak, a kik közöttetek fiakat nemzettek, és úgy tartsátok őket, mint a ki ott született az Izráel fiai között: veletek együtt sorsvetéssel legyen örökségök Izráel nemzetségei között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 23, 'És úgy legyen, hogy a mely nemzetséggel lakozik a jövevény, ott adjátok ki az ő örökségét. Ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 1, 'Ezek a nemzetségek nevei: az északi határon a Hetlóntól Hamáthig vezető út mentén Haczar-Énonig Damaskus határán, észak felé, Hamát mentén, és pedig legyen az övé a keleti és nyugoti oldal: Dán, egy rész;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 2, 'És Dán határa mellett a keleti oldaltól a nyugoti oldalig: Áser, egy rész;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 3, 'És Áser határa mellett a keleti oldaltól a nyugoti oldalig: Nafthali, egy rész;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 4, 'És Nafthali határa mellett a keleti oldaltól a nyugoti oldalig: Manasse, egy rész;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 5, 'És Manasse határa mellett a keleti oldaltól a nyugoti oldalig: Efraim, egy rész;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 6, 'És Efraim határa mellett a keleti oldaltól a nyugoti oldalig: Rúben, egy rész;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 7, 'És Rúben határa mellett a keleti oldaltól a nyugoti oldalig: Júda, egy rész;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 8, 'És Júda határa mellett a keleti oldaltól a nyugoti oldalig legyen a szent áldozat, melyet az Úrnak szenteltek: huszonötezer sing széles és olyan hosszú, mint egy-egy rész a keleti oldaltól a nyugoti oldalig; és a szenthely annak közepette legyen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 9, 'A szent áldozat, melyet az Úrnak szenteltek, huszonötezer sing hosszú és tízezer sing széles legyen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 10, 'És ezeké legyen ez a szent áldozat: a papoké északra huszonötezer sing és nyugotra tízezer sing szélesség és keletre tízezer sing szélesség és délre huszonötezer sing hosszúság, és az Úr szenthelye annak közepette legyen:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 11, 'A papoké, a kik megszenteltettek a Sádók fiai közül, a kik szolgálatomban foglalatosak voltak, a kik nem tévelyedtek el, mikor Izráel fiai eltévelyedtek, mint a hogy eltévelyedtek volt a Léviták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 12, 'Övék legyen ez, mint egy áldozati rész a föld áldozatából, mint igen szentséges, a Léviták határán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 13, 'A Lévitáké pedig legyen a papok határa mentén huszonötezer sing hosszúság és tízezer szélesség; az egész hosszúság legyen huszonötezer és a szélesség tízezer.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 14, 'És semmit abból el ne adjanak, se el ne cseréljék, se másra át ne szálljon a földnek e zsengéje, mert az Úrnak szenteltetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 15, 'És az ötezer sing, mely a szélességben megmaradt a huszonötezernek mentén, közhely a város számára, mint lakóhely és tágasság, és legyen a város annak a közepében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 16, 'És ezek legyenek annak méretei: az északi oldalon négyezerötszáz sing és a déli oldalon négyezerötszáz és a keleti oldalon négyezerötszáz és a nyugoti oldalon négyezerötszáz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 17, 'És a város alatt legyen tágasság észak felé kétszázötven sing és dél felé kétszázötven és keletre kétszázötven és nyugotra kétszázötven.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 18, 'A mi pedig megmaradt a hosszaságban a szent áldozat mentén, tízezer keletre és tízezer nyugotra, az ott maradjon a szent áldozat mentén, és legyen annak termése a város szántóvetőinek eledele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 19, 'És a ki szántóvető a városban, mívelje azt Izráelnek minden nemzetségéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 20, 'Az egész huszonötezer sing szent áldozatot huszonötezer sing négyszögben adjátok szent ajándékul a város tulajdonával együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 21, 'A mi pedig megmaradt, a fejedelemé lészen; a szent áldozatnak és a város tulajdonának mind a két oldalán, szemben a huszonötezer sing szent áldozattal a keleti határig és nyugot felé szemben a huszonötezer singgel egészen a nyugoti határig lészen, a kiosztott részek mentén, a fejedelemé; és legyen a szent áldozat és a ház szenthelye annak közepette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 22, 'És a Léviták tulajdonától és a város tulajdonától fogva, mely közepében van annak, a mi a fejedelemé, a Júda határa és Benjámin határa között a fejedelemé legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 23, 'És a többi nemzetségek: a keleti oldaltól a nyugoti oldalig: Benjámin, egy rész.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 24, 'És Benjámin határán a keleti oldaltól a nyugoti oldalig: Simeon, egy rész.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 25, 'És Simeon határán a keleti oldaltól a nyugoti oldalig: Issakhár, egy rész.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 26, 'És Issakhár határán a keleti oldaltól a nyugoti oldalig: Zebulon, egy rész.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 27, 'És Zebulon határán a keleti oldaltól a nyugoti oldalig: Gád, egy rész.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 28, 'És Gád határán a déli oldalon dél felé, legyen a határ Támártól a versengések vizéig Kádesben, a patak felé a nagy-tengerig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 29, 'Ez a föld, melyet sorsvetéssel örökségül eloszszatok Izráel nemzetségei közt, és ezek azoknak részei, ezt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 30, 'És ezek a város külső részei: Az északi oldalon négyezerötszáz sing mérték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 31, 'És a város kapui, Izráel nemzetségeinek nevei szerint, három kapu északra: Rúben kapuja egy, Júda kapuja egy, Lévi kapuja egy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 32, 'És a keleti oldalon négyezerötszáz sing és három kapu: József kapuja egy, Benjámin kapuja egy, Dán kapuja egy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 33, 'És a déli oldalon is négyezerötszáz sing mérték és három kapu: Simeon kapuja egy, Issakhár kapuja egy, Zebulon kapuja egy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 34, 'A nyugoti oldalon négyezerötszáz sing három kapuval: Gád kapuja egy, Áser kapuja egy, Nafthali kapuja egy:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 35, 'Köröskörül tizennyolcezer sing; és a város neve ama naptól fogva: Ott lakik az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'Jojakim, Júda királya uralkodásának harmadik esztendejében jöve Nabukodonozor, a babiloni király Jeruzsálemre, és megszállá azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'És kezébe adá az Úr Jojakimot, a Júda királyát, és az Isten háza edényeinek egy részét; és vivé azokat Sineár földére, az ő istenének házába, és az edényeket bevivé az ő istenének kincsesházába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'És mondá a király Aspenáznak, az udvarmesterek fejedelmének, hogy hozzon az Izráel fiai közül és királyi magból való s előkelő származású ifjakat,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'A kikben semmi fogyatkozás nincsen, hanem a kik ábrázatra nézve szépek, minden bölcseségre eszesek, és ismeretekkel bírnak és értenek a tudományokhoz, és a kik alkalmatosak legyenek arra, hogy álljanak a király palotájában; és tanítsák meg azokat a Káldeusok írására és nyelvére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'És rendele nékik a király mindennapi szükségletül a királyi ételből és a borból, melyből ő iszik vala, hogy így nevelje őket három esztendeig, és azután álljanak a király előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'Valának pedig ezek között a Júda fiai közül: Dániel, Ananiás, Misáel és Azariás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'És az udvarmesterek fejedelme neveket ada nékik; tudniillik elnevezé Dánielt Baltazárnak, Ananiást Sidráknak, Misáelt Misáknak, Azariást Abednegónak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'De Dániel eltökélé az ő szívében, hogy nem fertőzteti meg magát a király ételével és a borral, a melyből az iszik vala, és kéré az udvarmesterek fejedelmét, hogy ne kelljen magát megfertőztetnie.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, 'És az Isten kegyelemre és irgalomra méltóvá tevé Dánielt az udvarmesterek fejedelme előtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'És mondá az udvarmesterek fejedelme Dánielnek: Félek én az én uramtól, a királytól, a ki megrendelte a ti ételeteket és italotokat; minek lássa, hogy a ti orczátok hitványabb amaz ifjakénál, a kik egykorúak veletek? és így bűnbe kevernétek az én fejemet a királynál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, 'És mondá Dániel a felügyelőnek, a kire az udvarmesterek fejedelme bízta vala Dánielt, Ananiást, Misáelt és Azariást:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, 'Tégy próbát, kérlek, a te szolgáiddal tíz napig, és adjanak nékünk zöldségféléket, hogy azt együnk, és vizet, hogy azt igyunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'Azután mutassák meg néked a mi ábrázatunkat és amaz ifjak ábrázatát, a kik a király ételével élnek, és a szerint cselekedjél majd a te szolgáiddal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'És engede nékik ebben a dologban, és próbát tőn velük tíz napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'És tíz nap mulva szebbnek látszék az ő ábrázatuk, és testben kövérebbek valának mindazoknál az ifjaknál, a kik a király ételével élnek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'Elvevé azért a felügyelő az ő ételöket és az ő italokul rendelt bort, és ad vala nékik zöldségféléket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'És ada az Isten ennek a négy gyermeknek tudományt, minden írásban való értelmet és bölcseséget; Dániel pedig értett mindenféle látomáshoz és álmokhoz is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, 'Miután pedig elmúlt az idő, a mikorra meghagyta vala a király, hogy eléje vigyék őket, bevivé őket az udvarmesterek fejedelme Nabukodonozor elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, 'És szóla velök a király, és mindnyájok között sem találtaték olyan, mint Dániel, Ananiás, Misáel és Azariás, és állának a király előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, 'És minden bölcs és értelmes dologban, a mely felől a király tőlök tudakozódék, tízszerte okosabbaknak találá őket mindazoknál az írástudóknál és varázslóknál, a kik egész országában valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'És ott vala Dániel a Cyrus király első esztendejéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'És Nabukodonozor uralkodásának második esztendejében álmokat láta Nabukodonozor, és nyugtalan lőn az ő lelke, és álma félbeszakadt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'És mondá a király, hogy hívjanak írástudókat, varázslókat, bűbájosokat és Káldeusokat, hogy fejtsék meg a királynak az ő álmait; és bemenének azok, és állának a király elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'És monda nékik a király: Álmot láttam, és nyugtalan a lelkem megtudni az álmot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'És mondák a Káldeusok a királynak sziriai nyelven: Király, örökké élj! mondd meg az álmot a te szolgáidnak, és megjelentjük az értelmét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'Felele a király, és monda a Káldeusoknak: Az én szavam áll! Ha tehát meg nem mondjátok nékem az álmot és annak értelmét, darabokra tépettek, és a ti házaitok szemétdombokká tétetnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'Ha pedig az álmot és annak értelmét megjelentitek: ajándékokat, jutalmat és nagy tisztességet vesztek tőlem; ezért az álmot és annak értelmét jelentsétek meg nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'Felelének másodszor, és mondának: A király mondja meg az álmot az ő szolgáinak: és az értelmét megjelentjük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'Felele a király, és monda: Bizonnyal tudom én, hogy csak időt akartok ti nyerni, mert látjátok, hogy áll az én szavam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'Hogy ha az álmot meg nem mondjátok nékem, csak egy ítélet lehet felőletek: hogy hamis és tétovázó beszédet koholtok, hogy azzal tartsatok engem, míg az idő múlik. Mondjátok meg azért nékem az álmot, akkor tudom, hogy az értelmét is megjelenthetitek nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'Felelének a Káldeusok a királynak, és mondák: Nincs ember a földön, a ki a király dolgát megjelenthesse: mivelhogy bármilyen nagy és hatalmas király sem kívánt még egyetlen írástudótól, varázslótól és Káldeustól sem ilyen dolgot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'Mert a dolog, a mit a király kíván, igen nehéz, és nincs más, a ki azt megjelenthesse a király előtt, hanemha az istenek, a kik nem lakoznak együtt az emberekkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'E miatt a király megharaguvék és igen felgerjede, és meghagyá, hogy a babiloni bölcsek mind veszíttessenek el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'És a parancsolat kiméne, hogy öljék meg a bölcseket; és keresik vala Dánielt és az ő társait, hogy megölettessenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'Ekkor Dániel bölcsen és értelmesen felele Arióknak, a királyi testőrség fejének, a ki kiment vala, hogy megölesse a babiloni bölcseket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'Szóla és monda Arióknak, a király főemberének: Miért e kegyetlen parancsolat a királytól? Akkor Ariók elmondá a dolgot Dánielnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'És beméne Dániel, és kéré a királyt, hogy adjon néki időt, hogy megjelenthesse az értelmet a királynak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'Ekkor Dániel haza méne, és elmondá e dolgot Ananiásnak, Misáelnek és Azariásnak, az ő társainak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'Hogy kérjenek az egek Istenétől irgalmasságot e titok végett, hogy el ne veszszenek Dániel és az ő társai a többi babiloni bölcsekkel együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'Akkor Dánielnek megjelenteték az a titok éjjeli látásban. Áldá akkor Dániel az egek Istenét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'Szóla Dániel, és monda: Áldott legyen az Istennek neve örökkön örökké: mert övé a bölcseség és az erő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'És ő változtatja meg az időket és az időknek részeit; dönt királyokat és tesz királyokat; ád bölcseséget a bölcseknek és tudományt az értelmeseknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'Ő jelenti meg a mély és elrejtett dolgokat, tudja mi van a setétségben; és világosság lakozik vele!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, 'Néked adok hálát, atyáimnak Istene, és dicsérlek én téged, hogy bölcseséget és erőt adtál nékem, és mostan megjelentetted nékem, a mit kértünk tőled; mert a király dolgát megjelentetted nékünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, 'Beméne azért Dániel Ariókhoz, a kit rendelt vala a király, hogy elveszítse a babiloni bölcseket; elméne azért, és mondá néki: A babiloni bölcseket ne veszíttesd el; vígy engem a király elé és a megfejtést tudtára adom a királynak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 25, 'Akkor Ariók sietve bevivé Dánielt a király elébe, és mondá: Találtam férfiút Júdának fogoly fiai között, a ki a megfejtést megjelenti a királynak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 26, 'Szóla a király, és monda Dánielnek, a kit Baltazárnak nevezének: Csakugyan képes vagy megjelenteni nékem az álmot, a melyet láttam, és annak értelmét?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 27, 'Felele Dániel a király előtt, és mondá: A titkot, a melyről a király tudakozódék, a bölcsek, varázslók, írástudók, jövendőmondók meg nem jelenthetik a királynak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 28, 'De van Isten az égben, a ki a titkokat megjelenti; és ő tudtára adta Nabukodonozor királynak: mi lészen az utolsó napokban. A te álmod és a te fejed látása a te ágyadban ez volt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 29, 'Néked, oh király! gondolataid támadtak a te ágyadban a felől, hogy mik lesznek ez után, és a ki megjelenti a titkokat, megjelentette néked azt, a mi lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 30, 'Nékem pedig ez a titok nem bölcseségből, a mely bennem minden élő felett volna, jelentetett meg, hanem azért, hogy a megfejtés tudtára adassék a királynak és te megértsed a te szívednek gondolatait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 31, 'Te látád, oh király, és ímé egy nagy kép; ez a kép, mely hatalmas vala és kiváló az ő fényessége, előtted áll vala, és az ábrázata rettenetes volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 32, 'Annak az állóképnek feje tiszta aranyból, melle és karjai ezüstből, hasa és oldalai rézből,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 33, 'Lábszárai vasból, lábai pedig részint vasból, részint cserépből valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 34, 'Nézed vala, a míg egy kő leszakada kéz érintése nélkül, és letöré azt az állóképet vas- és cseréplábairól, és darabokra zúzá azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 35, 'Akkor egygyé zúzódék a vas, cserép, réz, ezüst és arany, és lőnek mint a nyári szérűn a polyva, és felkapá azokat a szél, és helyöket sem találák azoknak. Az a kő pedig, a mely leüté az állóképet nagy hegygyé lőn, és betölté az egész földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 36, 'Ez az álom, és értelmét is megmondjuk a királynak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 37, 'Te, oh király! királyok királya, kinek az egek Istene birodalmat, hatalmat, erőt és dicsőséget adott;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 38, 'És valahol emberek fiai, mezei állatok és égi madarak lakoznak, a te kezedbe adta azokat, és úrrá tett téged mindezeken: Te vagy az arany-fej.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 39, 'És utánad más birodalom támad, alábbvaló mint te; és egy másik, egy harmadik birodalom, rézből való, a mely az egész földön uralkodik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 40, 'A negyedik birodalom pedig erős lesz, mint a vas; mert miként a vas széttör és összezúz mindent; bizony mint a vas pusztít, mind amazokat szétzúzza és elpusztítja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 41, 'Hogy pedig lábakat és ujjakat részint cserépből, részint vasból valónak láttál: a birodalom kétfelé oszol, de lesz benne a vasnak erejéből, a mint láttad, hogy a vas elegy volt az agyagcseréppel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 42, 'És hogy a lába ujjai részint vas, részint cserép: az a birodalom részint erős, részint pedig törékeny lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 43, 'Hogy pedig vasat elegyülve láttál agyagcseréppel: azok emberi mag által vegyülnek össze, de egymással nem egyesülnek, minthogy a vas nem egyesül a cseréppel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 44, 'És azoknak a királyoknak idejében támaszt az egek Istene birodalmat, mely soha örökké meg nem romol, és ez a birodalom más népre nem száll át hanem szétzúzza és elrontja mindazokat a birodalmakat, maga pedig megáll örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 45, 'Minthogy láttad, hogy a hegyről kő szakad vala le kéz érintése nélkül, és szétzúzá a vasat, rezet, cserepet, ezüstöt és aranyat: a nagy Isten azt jelentette meg a királynak, a mi majd ezután lészen; és igaz az álom, és bizonyos annak értelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 46, 'Akkor Nabukodonozor király arczra borula és imádá Dánielt, és meghagyá, hogy ételáldozattal és jó illattal áldozzanak néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 47, 'Szóla a király Dánielnek, és monda: Bizonynyal a ti Istenetek, ő az isteneknek Istene, és a királyoknak ura és a titkok megjelentője, hogy te is megjelenthetted ezt a titkot!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 48, 'Akkor a király fölmagasztalá Dánielt, és sok nagy ajándékot ada néki, és hatalmat adott néki Babilonnak egész tartománya felett, és a babiloni összes bölcseknek előljárójává tevé őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 49, 'És Dániel kéré a királyt, hogy Sidrákot, Misákot és Abednégót rendelje a babiloni tartomány gondviselésére; Dániel pedig a király udvarában vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, 'Nabukodonozor király csináltata egy arany állóképet, magassága hatvan sing, szélessége hat sing; felállíttatá azt a Dura mezején, Babilon tartományában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'És Nabukodonozor király egybegyűjteté a fejedelmeket, helytartókat, kormányzókat, bírákat, kincstartókat, tanácsosokat, törvénytevőket és a tartományok minden igazgatóját, hogy jőjjenek az állóképnek felavatására, a melyet Nabukodonozor király állíttatott vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'Akkor egybegyűlének a fejedelmek, helytartók, kormányzók, bírák, kincstartók, tanácsosok, törvénytevők és a tartományok minden igazgatója az állókép felavatására, a melyet Nabukodonozor király állíttatott, és megállának az állókép előtt, a melyet Nabukodonozor állíttatott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'És a hírnök hangosan kiálta: Meghagyatik néktek, oh népek, nemzetek és nyelvek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'Mihelyt halljátok a kürtnek, sípnak, cziterának, hárfának, lantnak, dudának és mindenféle hangszernek szavát: boruljatok le, és imádjátok az arany állóképet, a melyet Nabukodonozor király állíttatott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'Akárki pedig, a ki nem borul le és nem imádja, tüstént bevettetik az égő, tüzes kemenczébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'Azért mihelyt hallák mind a népek a kürtnek, sípnak, cziterának, hárfának, lantnak és mindenféle hangszernek szavát: leborulának, mind a népek, nemzetségek és nyelvek, és imádák az arany állóképet, a melyet Nabukodonozor király állíttatott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'Elmenének azért ebben az időben káldeabeli férfiak, és vádat emelének a zsidók ellen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'Szólának pedig és mondák Nabukodonozor királynak: Király! örökké élj!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'Te, oh király! parancsolatot adtál ki, hogy minden ember, mihelyt meghallja a kürtnek, sípnak, cziterának, hárfának, lantnak, dudának és mindenféle hangszernek szavát: boruljon le, és imádja az arany állóképet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'A ki pedig nem borul le és nem imádja, vettessék be az égő, tüzes kemenczébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'Vannak zsidó férfiak, a kiket a babiloni tartomány gondviselésére rendeltél, Sidrák, Misák és Abednégó: ezek a férfiak nem becsülnek téged, oh király, a te isteneidet nem tisztelik, és az arany állóképet, a melyet felállíttattál, nem imádják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'Akkor Nabukodonozor nagy haraggal és felgerjedéssel meghagyá, hogy hozzák elő Sidrákot, Misákot és Abednégót; erre elhozák a férfiakat a király elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'Szóla Nabukodonozor, és monda nékik: Sidrák, Misák és Abednégó! Szántszándékból nem tisztelitek-é az én istenemet és nem imádjátok-é az arany állóképet, a melyet felállíttattam?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'Ha tehát készek vagytok: mihelyt halljátok a kürtnek, sípnak, cziterának, hárfának, lantnak, dudának és mindenféle hangszernek szavát, leboruljatok és imádjátok az állóképet, a melyet én csináltattam. De ha nem imádjátok, tüstént bevettettek az égő, tüzes kemenczébe; és kicsoda az az Isten, a ki kiszabadítson titeket az én kezeimből?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'Felelének Sidrák, Misák és Abednégó, és mondának a királynak: Oh Nabukodonozor! Nem szükség erre felelnünk néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'Ímé, a mi Istenünk, a kit mi szolgálunk, ki tud minket szabadítani az égő, tüzes kemenczéből, és a te kezedből is, oh király, kiszabadít minket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'De ha nem tenné is, legyen tudtodra, oh király, hogy mi a te isteneidnek nem szolgálunk, és az arany állóképet, a melyet felállíttatál, nem imádjuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'Akkor Nabukodonozor eltelék haraggal, és az ő orczájának színe elváltozék Sidrák, Misák és Abednégó ellen; azért szóla, és meghagyá, hogy fűtsék be a kemenczét hétszerte inkább, mint szokták vala befűteni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'És meghagyá a legerősebb férfiaknak az ő seregében, hogy kötözzék meg Sidrákot, Misákot és Abednégót, és vessék őket az égő, tüzes kemenczébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, 'Erre ezek a férfiak alsó ruhástul, köntösöstül, palástostul és egyéb öltönyöstül megkötöztettek, és az égő, tüzes kemenczébe vettettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, 'A miatt azonban, hogy a király parancsolata szigorú volt és a kemencze rendkivül izzó vala: azokat a férfiakat, a kik Sidrákot, Misákot és Abednégót felvitték, megölé a tűznek lángja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'Az a három férfiú pedig: Sidrák, Misák és Abednégó, az égő, tüzes kemenczébe esék megkötözve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, 'Akkor Nabukodonozor király megijedt és sietve felkele, szóla és monda az ő tanácsosainak: Nem három férfiút veténk-é a tűz közepébe megkötözve? Felelének és mondának a királynak: Bizonyára, oh király!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, 'Felele, és monda: Ímé, négy férfiút látok szabadon járni a tűz közepében, és semmi sérelem sincs bennök, és a negyediknek ábrázata olyan, mint valami istenek-fiáé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'Nabukodonozor ekkor az égő, tüzes kemencze szájához járula, és szóla és monda: Sidrák, Misák és Abednégó, a felséges Istennek szolgái, jertek ki és jőjjetek ide! Azonnal kijövének Sidrák, Misák és Abednégó a tűz közepéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, 'És egybegyűlvén a fejedelmek, helytartók és kormányzók és a király tanácsosai, nézik vala ezeket a férfiakat, hogy a tűznek semmi hatalma nem lett az ő testükön, és hogy egy hajszáluk sem égett meg, és az ő alsó ruháik meg nem változtak, és a tűz szaga sem járta át őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, 'Szóla Nabukodonozor, és monda: Áldott ezeknek Istene, a Sidrák, Misák és Abednégó Istene, a ki küldötte az ő angyalát és kiszabadította az ő szolgáit, a kik ő benne bíztak; és a király parancsolatát megszegték és veszedelemre adták az ő testöket és nem szolgáltak és nem imádtak más istent az ő Istenökön kivül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, 'Parancsolom azért, hogy minden nép, nemzetség és nyelv, a mely káromlást mond Sidrák, Misák és Abednégó Istene ellen, darabokra tépessék, és annak háza szemétdombbá tétessék: mert nincs más Isten, a ki így megszabadíthasson.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, 'Akkor a király nagy tisztességre emelé Sidrákot, Misákot és Abednégót Babilon tartományában. Nabukodonozor király minden népnek, nemzetnek és nyelveknek, a kik az egész földön lakoznak, mondá: Békességetek bőséges legyen! A jeleket és csudákat, a melyeket cselekedett velem a felséges Isten, illendő dolognak tartom megjelenteni. Mely nagyok az ő jelei és mely hatalmasak az ő csudái! az ő országa örökkévaló ország és az ő uralkodása nemzedékről nemzedékre száll.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, 'Én Nabukodonozor békében valék az én házamban, és virágzó az én palotámban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, 'Álmot láték és megrettente engem, és a gondolatok az én ágyamban, és az én fejemnek látásai megháborítának engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, 'És parancsolatot adék, hogy hozzák előmbe Babilonnak minden bölcsét, hogy az álom jelentését tudassák velem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, 'Akkor bejövének az írástudók, varázslók, Káldeusok és jövendőmondók; és én elbeszélém nékik az álmot, de az értelmét nem jelentették meg nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, 'Végezetre bejöve elém Dániel, a kinek neve Baltazár, mint az én istenemnek neve, és a kiben a szent isteneknek lelke van, és elmondám néki az álmot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, 'Baltazár, az írástudók elseje, tudom, hogy a szent isteneknek lelke van benned, és semmi titok sem homályos előtted, az én álmom látásait, a miket láttam, és azoknak jelentését beszéld el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, 'Az én fejem látásai az én ágyamban ezek voltak: Látám, hogy ímé, egy fa álla a föld közepette, és annak magassága rendkivüli volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, 'Nagy volt a fa és erős, és magassága az égig ért, és az egész föld széléig volt látható.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, 'Levelei szépek és gyümölcse sok, és táplálék vala rajta mindeneknek; alatta árnyékot talála a mező vada, és ágain lakozának az ég madarai, és róla evék minden élő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, 'Látám fejem látásaiban az én ágyamban, és ímé: egy Vigyázó és Szent szálla alá az égből;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, 'Erősen kiálta, és így szóla: Vágjátok ki a fát és vagdaljátok le az ágait, rázzátok le leveleit és hányjátok szét gyümölcseit, fussanak el a vadak alóla, és a madarak az ő ágairól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, 'De gyökerének törzsökét hagyjátok meg a földben, és vas és ércz lánczokba verve a mező füvén; égi harmattal öntöztessék, és a barmokkal legyen része a föld füvében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, 'Az ő emberi szíve változzék el, és baromnak szíve adassék néki, és hét idő múljék el felette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, 'Vigyázók határozatából van ez a rendelet, és a Szentek parancsolata ez a végzés, hogy megtudják az élők, hogy a felséges Isten uralkodik az emberek birodalmán, és a kinek akarja, annak adja azt, és az emberek között az alábbvalót emeli fel arra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, 'Ezt az álmot láttam én, Nabukodonozor király, és te, Baltazár, mondd meg annak értelmét; mivelhogy az én országomnak egyetlen bölcse sem tudta nékem megmondani a jelentését; de te tudod, mert szent isteneknek lelke van benned.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, 'Ekkor Dániel, a kinek neve Baltazár, közel egy óráig rémüldözék, és az ő gondolatai háboríták őt. Szóla a király, és monda: Baltazár, az álom és annak jelentése meg ne rettentsenek téged! Felele Baltazár, és monda: Uram, az álom szálljon a te gyűlölőidre, a magyarázata pedig a te ellenségeidre!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, 'A fa, a melyet láttál, a mely nagy és erős volt, és a melynek magassága az eget érte és ellátszék az egész földre;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, 'És levelei szépek, gyümölcse pedig sok, és táplálék rajta mindeneknek; alatta tartózkodék a mező vada, és ágain az égi madarak lakozának:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, 'Te vagy az, oh király, a ki nagygyá és erőssé lettél, a kinek nagysága megnövekedék és fölér az égig, és hatalmad a föld végéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, 'Hogy pedig láta a király Vigyázót és Szentet leszállani az égből, és azt mondá: Vágjátok le a fát és pusztítsátok el azt; de gyökereinek törzsökét a földben hagyjátok, és vas és ércz lánczokba verve a mező füvén, és égi harmattal öntöztessék és a mezei barmokkal legyen része, a míg hét idő múlik el felette;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, 'Ez a jelentése, oh király, és a felséges Isten végezése ez, a mely bekövetkezik az én uramra, a királyra,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, 'És kivetnek téged az emberek közül, és a mezei barmokkal lesz a te lakozásod, és füvet adnak enned, mint az ökröknek, és égi harmattal öntöznek téged, és hét idő múlik el feletted, mígnem megérted, hogy a felséges Isten uralkodik az emberek birodalmán, és annak adja azt, a kinek akarja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, 'Hogy pedig mondák, hogy a fa gyökereinek törzsökét hagyják meg: országod megmarad néked, mihelyest megismered, hogy az Ég uralkodik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, 'Azért, oh király, az én tanácsom tessék néked, és vétkeidtől igazság által szabadulj és a te hamisságaidtól a szegényekhez való irgalmasság által. Így talán tartós lesz a békességed.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, 'Mindez betelék Nabukodonozor királyon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, 'Tizenkét hónap mulva a babiloni királyi palotán sétála.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, 'Szóla a király és mondá: Nem ez-é ama nagy Babilon, a melyet én építettem királyság házának, az én hatalmasságom ereje által és dicsőségem tisztességére?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, 'Még a szó a király szájában volt, a mikor szózat szálla le az égből: Néked szól, oh Nabukodonozor király, a birodalom elvétetett tőled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 29, 'És kivetnek téged az emberek közül, és a mezei barmokkal lesz a lakozásod, és füvet adnak enned, mint az ökröknek, és hét idő múlik el feletted, a míg megesméred, hogy a felséges Isten uralkodik az emberek birodalmán, és annak adja azt, a kinek akarja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 30, 'Abban az órában betelék a beszéd Nabukodonozoron: és az emberek közül kivetteték, és füvet evék mint az ökrök, és égi harmattal öntözteték az ő teste, mígnem szőre megnöve, mint a saskeselyű tolla, és körmei, mint a madarakéi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 31, 'És az idő elteltével én, Nabukodonozor, szemeimet az égre emelém, és az én értelmem visszajöve, és áldám a felséges Istent, és dícsérém és dicsőítém az örökké élőt, kinek hatalma örökkévaló hatalom és országa nemzedékről-nemzedékre áll.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 32, 'És a föld minden lakosa olyan mint a semmi; és az ő akaratja szerint cselekszik az ég seregében és a föld lakosai között, és nincs, a ki az ő kezét megfoghatná és ezt mondaná néki: Mit cselekedtél?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 33, 'Abban az időben visszatére hozzám az én értelmem, és országom dicsőségére az én ékességem, és méltóságom is visszatére hozzám, és az én tanácsosaim és főembereim fölkeresének engem, és visszahelyeztettem az én országomba, és rendkívüli nagyság adatott nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 34, 'Most azért én, Nabukodonozor, dicsérem, magasztalom és dicsőítem a mennyei királyt: mert minden cselekedete igazság, és az ő utai ítélet, és azokat, a kik kevélységben járnak, megalázhatja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 35, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 36, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 37, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'Belsazár király nagy lakomát szerze az ő ezer főemberének, és az ezer előtt bort ivék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'Borozás közben mondá Belsazár, hogy hozzák elő az arany és ezüst edényeket, a melyeket elvive Nabukodonozor, az ő atyja a jeruzsálemi templomból, hogy igyanak azokból a király és az ő főemberei, az ő feleségei és az ő ágyasai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'Akkor előhozák az arany edényeket, a melyeket elvivének az Isten házának templomából, mely Jeruzsálemben vala, és ivának azokból a király és az ő főemberei, az ő feleségei és az ő ágyasai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'Bort ivának, és dicsérék az arany-, ezüst-, ércz-, vas-, fa- és kőisteneket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'Abban az órában emberi kéznek ujjai tünének fel, és írának a gyertyatartóval szemben a király palotájának meszelt falán, és a király nézé azt a kézfejet, a mely ír vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'Ekkor a király ábrázatja megváltozék, és az ő gondolatai megháboríták őt, és derekának inai megoldódának és az ő térdei egymáshoz verődének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'Erősen kiáltozék a király, hogy hozzák elő a varázslókat, a Káldeusokat és jövendölőket. Szóla a király és monda a babiloni bölcseknek: Akárki legyen az az ember, a ki elolvassa ezt az írást, és annak értelmét megjelenti nékem, bíborba öltöztetik és aranyláncz lesz a nyakában, és mint harmadik parancsol az országban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'Akkor bemenének a király bölcsei mind, de nem tudták elolvasni az írást, sem annak értelmét megfejteni a királynak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'Akkor Belsazár király igen megrettene, és az ő ábrázatja elváltozék rajta, és az ő főemberei is megzavarodának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'A királyasszony a király és az ő főembereinek beszédei miatt beméne a lakoma házába, és szóla a királyasszony, és monda: Király, örökké élj! Ne rettentsenek téged a te gondolataid, és a te ábrázatod ne változzék el!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'Van egy férfiú a te országodban, a kiben a szent isteneknek lelke van, és a te atyád idejében értelem, tudomány, és az istenek bölcseségéhez hasonló bölcseség találtaték benne, és a kit Nabukodonozor király, a te atyád, az írástudók, varázslók, Káldeusok és jövendölők fejévé tőn; igen, a te atyád, a király;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'Mivelhogy Dánielben, a kit a király Baltazárnak nevezett, nagyobb lélek, tudomány és értelem, álmoknak magyarázata és titkok megjelentése és rejtélyek megfejtése találtatott. Most azért hivattassék elő Dániel, és ő megjelenti az értelmet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'Erre Dániel a király elé viteték. Szóla a király, és monda Dánielnek: Te vagy-é ama Dániel, a ki a júdabeli foglyok fiai közül való, a kit ide hozott a király, az én atyám, Júdából?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'És a ki felől hallottam, hogy az isteneknek lelke van benned, és értelem és tudomány és kiváló bölcseség találtatott te benned?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'Csak imént hozatának elém a bölcsek és varázslók, hogy elolvassák ezt az írást és jelentését tudassák velem; de nem tudják a dolog értelmét megjelenteni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'De felőled azt hallottam, hogy te tudod az értelmet megfejteni és a titkokat megoldani; most azért, ha el tudod olvasni ezt az írást és értelmét nékem megmondani, bíborba öltöztetel és aranyláncz lesz a nyakadon, és mint harmadik uralkodol az országban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'Erre Dániel felele, és monda a királynak: Ajándékaid tiéid legyenek, és adományaidat másnak adjad, mindazáltal az írást elolvasom a királynak, és jelentését megmondom néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'Te, oh király! A felséges Isten birodalmat és méltóságot, dicsőséget és tisztességet ada Nabukodonozornak, a te atyádnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'És a méltóság miatt, a melyet ada néki, a népek, nemzetek és nyelvek mind féltek és rettegtek tőle; megölt, a kit akart; és életben tartott a kit akart; felemelt, a kit akart; és megalázott, a kit akart;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'De mikor a szíve felfuvalkodott, és a lelke megkeményedett megátalkodottan: levetteték az ő birodalmának királyi székéből, és dicsőségét elvevék tőle;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'És az emberek fiai közül kivetteték, és az ő szíve olyanná lőn, mint a barmoké; és a vadszamarakkal lőn az ő lakása, és fűvel etették őt, mint az ökröket, és a teste égi harmattal öntöztetett, míg megismeré, hogy a felséges Isten uralkodik az emberek országán, és azt helyezteti arra, a kit akar.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'És te, Belsazár, az ő fia, nem aláztad meg a szívedet, noha mindezt tudtad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'Sőt felemelkedtél az egek Ura ellen, és az ő házának edényeit elődbe hozták, és te és a te főembereid, a te feleségeid és a te ágyasaid bort ittak azokból; és az ezüst- és arany-, ércz-, vas-, fa- és kőisteneket dícséréd, a kik nem látnak, sem nem hallanak, sem nem értenek; az Istent pedig, a kinek kezében van a te lelked, és előtte minden te útad, nem dicsőítetted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, 'Azért küldetett ő általa ez a kéz, és jegyeztetett fel ez az írás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, 'És ez az írás, a mely feljegyeztetett: Mene, Mene, Tekel, Ufarszin!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, 'Ez pedig e szavaknak az értelme: Mene, azaz számba vette Isten a te országlásodat és véget vet annak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, 'Tekel, azaz megmérettél a mérlegen és híjjával találtattál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, 'Peresz, azaz elosztatott a te országod és adatott a médeknek és persáknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, 'Akkor szóla Belsazár, és öltöztették Dánielt bíborba, és aranylánczot vetének nyakába, és kikiálták felőle, hogy ő parancsol mint harmadik az országban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, 'Ugyanazon az éjszakán megöleték Belsazár, a Káldeusok királya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 31, 'És a méd Dárius foglalá el az országot mintegy hatvankét esztendős korában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'Tetszék Dáriusnak, és rendele a birodalom fölé százhúsz tiszttartót, hogy az egész birodalomban legyenek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, 'És azok fölé három igazgatót, a kik közül egy vala Dániel, hogy a tiszttartók nékik adjanak számot, és a királynak semmi károsodása ne legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'Akkor ez a Dániel felülhaladá az igazgatókat és a tiszttartókat, mivelhogy rendkivüli lélek volt benne, úgy hogy a király őt szándékozék tenni az egész birodalom fölé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, 'Akkor az igazgatók és tiszttartók igyekvének okot találni Dániel ellen a birodalom dolgai miatt; de semmi okot vagy vétket nem találhatának; mert hűséges volt, és semmi fogyatkozás, sem vétek nem találtaték benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, 'Akkor mondák azok a férfiak: Nem találunk ebben a Dánielben semmi okot, hacsak nem találhatunk ellene valamit az ő Istenének törvényében!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'Akkor azok az igazgatók és tiszttartók berohantak a királyhoz, és így szólának: Dárius király, örökké élj!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, 'Tanácsot tartottak az ország összes igazgatói: a helytartók, fejedelmek, tanácsosok és a kormányzók, hogy királyi végzés hozassék, és erős tilalom adassék, hogy ha valaki harmincz napig kér valamit valamely istentől vagy embertől, tekívüled, oh király, vettessék az oroszlánok vermébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, 'Most azért, oh király, erősítsd meg e tilalmat és add ki írásban, hogy meg ne változtassék a médek és persák vissza nem vonható törvénye szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, 'Annakokáért Dárius király adott írást és tilalmat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, 'Dániel pedig, a mint megtudta, hogy megiratott az írás, beméne az ő házába; és az ő felső termének ablakai nyitva valának Jeruzsálem felé; és háromszor napjában térdeire esék, könyörge és dícséretet tőn az ő Istene előtt, a miként azelőtt cselekszik vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, 'Akkor azok a férfiak berohantak és megtalálák Dánielt, a mint könyörge és esedezék az ő Istene előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, 'Ekkor bemenének, és mondák a királynak a király tilalma felől: Nem megírtad-é a tilalmat, hogy ha valaki kér valamit valamely istentől vagy embertől harmincz napig, tekívüled oh király, vettessék az oroszlánok vermébe? Felele a király és monda: Áll a szó! a médek és persák vissza nem vonható törvénye szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, 'Erre felelének, és mondák a királynak: Dániel, a ki a júdabeli foglyok fiai közül való, nem becsül téged, oh király, sem a tilalmat, a mit megírtál; hanem háromszor napjában elkönyörgi könyörgését.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, 'Akkor a király, a mint hallotta ezt, igen restelkedék a miatt, és szíve szerint azon volt, hogy Dánielt megszabadítsa, és napnyugotig törekedék őt megmenteni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, 'Erre azok a férfiak berohantak a királyhoz, és mondák a királynak: Tudd meg, király, hogy ez a médek és persák törvénye, hogy semmi tilalom vagy végzés, a melyet a király rendel, meg ne változtassék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, 'Erre szóla a király, és előhozák Dánielt, és veték az oroszlánok vermébe. Szóla a király, és mondá Dánielnek: A te Istened, a kinek te szüntelen szolgálsz, ő szabadítson meg téged!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, 'És hozának egy követ, és oda tevék a verem szájára, és megpecsétlé a király az ő gyűrűjével és az ő főembereinek gyűrűivel, hogy semmi meg ne változtassék Dánielre nézve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, 'Erre eltávozék a király az ő palotájába, és étlen tölté az éjszakát, és vigasságtevő szerszámokat sem hozata eléje; kerülte őt az álom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, 'Hajnalban a király azonnal felkele még szürkületkor, és sietve az oroszlánok verméhez méne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, 'És mikor közel ére a veremhez, szomorú szóval kiálta Dánielnek; szóla a király, és monda Dánielnek: Dániel! az élő Istennek szolgája, a te Istened, a kinek te szüntelen szolgálsz, meg tudott-é szabadítani téged az oroszlánoktól?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, 'Akkor Dániel szóla a királynak: Király, örökké élj!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, 'Az én Istenem elbocsátá az ő angyalát, és bezárá az oroszlánok száját és nem árthattak nékem; mert ártatlannak találtattam ő előtte és te előtted sem követtem el, oh király, semmi vétket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, 'Akkor a király igen örvende, és Dánielt kihozatá a veremből. És kivevék Dánielt a veremből, és semmi sérelem nem találtaték ő rajta: mert hitt az ő Istenében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, 'És parancsola a király, és előhozák azokat a férfiakat, a kik Dánielt vádolák, és az oroszlánok vermébe vettetének mind ők, mind fiaik és feleségeik; és még a verem fenekére sem jutának, a mikor rájok rontának az oroszlánok és minden csontjokat összezúzták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, 'Akkor Dárius király ira minden népnek, nemzetnek és nyelvnek, a kik az egész földön lakozának: Békességtek bőséges legyen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, 'Én tőlem adatott ez a végzés, hogy az én birodalmamnak minden országában féljék és rettegjék a Dániel Istenét; mert ő az élő Isten, és örökké megmarad, és az ő országa meg nem romol, és uralkodása mind végig megtart;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, 'A ki megment és megszabadít, jeleket és csodákat cselekszik mennyen és földön; a ki megszabadította Dánielt az oroszlánok hatalmából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, 'És ennek a Dánielnek jó szerencsés lőn dolga a Dárius országában és a persa Czírus országában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'Belsazárnak, a babiloni királynak első esztendejében álmot láta Dániel és fejének látásait az ő ágyában. Az álmot akkor följegyzé; a dolog velejét elmondá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'Szóla Dániel, és monda: Látám az én látásomban éjszaka, és ímé, az égnek négy szele háborút támaszta a nagy tengeren;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'És négy nagy állat jöve fel a tengerből, egyik különböző a másiktól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'Az első olyan, mint az oroszlán, és sas szárnyai valának. Nézém, míg szárnyai kitépettek, és felemelteték a földről, és mint valami ember, lábra állíttaték és emberi szív adaték néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'És ímé, más állat, a második, hasonló a medvéhez, és kele egyik oldalára, és három oldalborda vala szájában fogai között, és így szólának néki: Kelj fel és egyél sok húst!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'Ez után látám, és ímé, egy másik, olyan mint a párducz, és négy madárszárnya vala a hátán; és négy feje vala az állatnak, és hatalom adaték néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'Ezek után látám éjszakai látásokban, és ímé, negyedik állat, rettenetes és iszonyú és rendkivül erős; nagy vasfogai valának, falt és zúzott és a maradékot lábaival összetaposta, és ez különbözék mindazoktól az állatoktól, a melyek előtte valának, és tíz szarva vala néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'Mialatt a szarvakat szemlélém, ímé, másik kicsiny szarv növekedék ki azok között, és három az elébbi szarvak közül kiszakasztaték ő előtte, és ímé, emberszemekhez hasonló szemek valának ebben a szarvban, és nagyokat szóló száj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, 'Nézém, míg királyi székek tétetének, és az öreg korú leüle, ruhája hófehér, és fejének haja, mint a tiszta gyapjú; széke tüzes láng, ennek kerekei égő tűz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'Tűzfolyam foly és jő vala ki az ő színe felől; ezerszer ezeren szolgálának néki, és tízezerszer tízezeren állának előtte; ítélők ülének le, és könyvek nyittatának meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'Nézém akkor a nagyzó beszédek hangja miatt, a melyeket a szarv szóla; nézém, míg megöleték az az állat, és az ő teste elvesze, és tűzbe vetteték megégetésre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'A többi állatoktól is elvéteték az ő hatalmok; de ideig-óráig tartó élet adaték nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'Látám éjszakai látásokban, és ímé az égnek felhőiben mint valami emberfia jőve; és méne az öreg korúhoz, és eleibe vivék őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'És ada néki hatalmat, dicsőséget és országot, és minden nép, nemzet és nyelv néki szolgála; az ő hatalma örökkévaló hatalom, a mely el nem múlik, és az ő országa meg nem rontatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, 'Megrendülék én, Dániel, az én lelkemben ezek miatt, és fejem látásai megháborítának engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'Oda menék egyhez az ott állók közül, és bizonyosat kérék tőle mindezek felől, és szóla nékem, és e dolognak értelmét tudatá velem:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, 'Ezek a nagy állatok, mik négyen voltak, négy király, a kik támadnak e földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'De a magasságos egeknek szentei veszik majd az országot, és bírják az országot örökké és örökkön örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'Akkor bizonyosat kívánék tudni a negyedik állat felől, a mely különbözék mindamazoktól, és rendkivül rettenetes vala; vasfogai és érczkörmei valának, falt és zúzott, és a maradékot lábaival összetaposta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'A tíz szarv felől is, a melyek a fején valának, és a felől, a mely utóbb növekedék és három esék ki előle; és ennek a szarvnak szemei valának és nagyokat szóló szája; termete is nagyobb a társaiénál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'Látám, hogy ez a szarv hadakozék a szentek ellen, és legyőzé őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'Mígnem eljöve az öreg korú, és az ítélet adaték a magasságos egek szenteinek; és az idő eljöve, és elvevék az országot a szentek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'Így szóla: A negyedik állat negyedik ország lesz e földön, a mely különb lesz minden országnál, és megeszi az egész földet, és eltapodja és szétzúzza azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'A tíz szarv pedig ez: Ebből az országból tíz király támad, és más támad utánok, és az különb lesz mint az előbbiek, és három királyt fog megalázni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'És sokat szól a Felséges ellen és a magasságos egek szenteit megrontja, és véli, hogy megváltoztatja az időket és törvényt; és az ő kezébe adatnak ideig, időkig és fél időig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, 'De ítélők ülnek és az ő hatalmát elveszik, hogy megrontassék és végleg elveszszen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, 'Az ország pedig és a hatalom és az egész ég alatt levő országok nagysága átadatik a magasságos egek szentei népének; az ő országa örökkévaló ország, és minden hatalmasság néki szolgál és engedelmeskedik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, 'Itt vége lőn a beszédnek. Engemet, Dánielt pedig az én gondolatim igen megrettentének és az én ábrázatom elváltozék rajtam; de e beszédet megtartám szívemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, 'Belsazár király uralkodásának harmadik esztendejében látomás jelenék meg nékem, Dánielnek, annak utánna, a mely először jelent meg nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'És láték látomásban; és mikor láték, Susán várában voltam, a mely Elám tartományában van; és láték látomásban, és ímé az Ulai folyam mellett valék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'És felemelém szemeimet és látám, és ímé egy kos álla a folyam előtt, és két szarva vala; és az a két szarv magas vala, de egyik a másiknál magasabb, és a magasabb később növekedék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'Látám azt a kost szarvaival öklelkezni napnyugot, észak és dél felé; és semmi állat sem állhata meg előtte, és senki sem szabadíthata meg kezéből, és tetszése szerint cselekedék, és nagygyá lőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'És míg én szemlélém, ímé, egy kecskebak jöve napnyugot felől az egész föld színére, és nem is illeté a földet; és ennek a baknak tekintélyes szarva vala az ő szemei között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'És méne a kétszarvú koshoz, a melyet láték állani a folyam előtt; és feléje futa erejének indulatában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'És látám a koshoz érni; és néki dühödött és leüté a kost, és letöré két szarvát, és nem vala erő a kosban megállani előtte, és leüté a földre és megtapodá, és nem vala a kosnak senkije, a ki őt megmentse annak kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'A kecskebak pedig igen nagygyá lőn; de mikor elhatalmasodék, eltörék a nagy szarv, és helyébe négy tekintélyes szarv növe az égnek négy szele felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'És azok közül egyből egy kis szarv támada, és nagyon megnöve délre, napkeletre és a kívánatos föld felé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'És megnöve mind az ég seregéig; és a földre vete némelyeket ama seregből és a csillagokból, és azokat megtapodá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'És a seregnek fejedelméig növekedék, és elvette tőle a mindennapi áldozatot, és elhányattaték az ő szentségének helye.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'És sereg rendeltetett a mindennapi áldozat ellen, a vétek miatt; és földre veti az igazságot, és cselekszik, és jó szerencséje van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'És hallék egy szentet szólni; és monda egyik szent annak, a ki szól vala: Meddig tart e látomás a mindennapi áldozat és a pusztító vétek felől? s a szent hely és a sereg meddig tapostatik?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'És monda nékem: Kétezer és háromszáz estvéig és reggelig, azután kiderül a szenthely igazsága.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'És lőn, hogy mikor én, Dániel, látám e látomást és keresém az értelmét: ímé előmbe álla egy férfiúhoz hasonló alak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'És emberi szót hallék az Ulai közén; kiálta pedig és monda: Gábriel, értesd meg azzal a látást!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'És oda jöve, a hol én állék, és a mint jöve, megrettenék és orczámra esém, és monda nékem: Értsd meg, embernek fia! mert az utolsó időre szól ez a látomás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'És mikor szóla velem, ájultan esém orczámmal a földre; de megillete engem és helyemre állíta;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'És monda: Ímé, én megmondom néked, mi lesz a haragnak végén? Mert a végső időre szól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'Az a kétszarvú kos, melyet láttál, Médiának és Persiának királya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'A szőrös kecskebak Görögország királya, a nagy szarv pedig, a mely szemei között vala, az az első király.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'Hogy pedig az letöretteték, és négy álla helyébe: négy ország támad abból a nemzetből, de nem annak erejével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, 'És ezek országai után, mikor elfogynak a gonoszok, támad egy kemény orczájú, ravaszságokhoz értő király.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, 'És annak nagy ereje lesz, noha nem a maga ereje által, és csudálatosképen pusztít és jó szerencsével halad és cselekszik, és elpusztítja az erőseket és a szenteknek népét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, 'És a maga eszén jár, és szerencsés lesz az álnokság az ő kezében, és szívében felfuvalkodik és hirtelen elveszt sokakat; sőt a fejedelmek fejedelme ellen is feltámad, de kéz nélkül rontatik meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, 'És az estvéről és reggelről való látomás, a mely megmondatott, igazság; te azonban pecsételd be a látomást, mert sok napra való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, 'És én, Dániel, elájulék és beteg valék néhány napig, de felkelék és a király dolgát végezém; és álmélkodám ezen a látáson, és senki sem értette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'Dáriusnak, az Asvérus fiának első esztendejében, a ki a Médiabeliek nemzetségéből vala, a ki királylyá tétetett vala a Káldeusok országán;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'Uralkodásának első esztendejében én, Dániel, megfigyeltem a könyvekben az esztendők számát, a melyről az Úr ígéje lőn Jeremiás prófétához, hogy hetven esztendőnek kell eltelni Jeruzsálem omladékain.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'És orczámat az Úr Istenhez emelém, hogy keressem őt imádsággal, könyörgéssel, bőjtöléssel, zsákban és hamuban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'És imádkozám az Úrhoz, az én Istenemhez, és vallást tevék, és mondám: Kérlek, oh Uram, nagy és rettenetes Isten, a ki megtartja a szövetséget és a kegyességet azoknak, a kik őt szeretik és teljesítik az ő parancsolatait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'Vétkeztünk és gonoszságot míveltünk, hitetlenül cselekedtünk és pártot ütöttünk ellened, és eltávoztunk a te parancsolataidtól és ítéleteidtől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'És nem hallgatánk a te szolgáidra, a prófétákra, a kik a te nevedben szóltak a mi királyainknak, fejedelmeinknek, atyáinknak és az ország egész népének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'Tied Uram az igazság, mienk pedig orczánk pirulása, a mint ez ma van Júda férfiain, Jeruzsálem lakosain és az egész Izráelen, a közel és távol valókon, mindama földeken, a melyekre kivetetted őket az ő gonoszságuk miatt, a melylyel vétkeztek ellened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'Miénk, oh Uram, orczánk pirulása, a mi királyainké, fejedelmeinké és atyáinké, a kik vétkeztünk ellened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'A mi Urunké Istenünké az irgalmasság és a bocsánat, mert pártot ütöttünk ellene;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'És nem hallgattunk az Úrnak, a mi Istenünknek szavára, hogy járjunk az ő törvényeiben, a melyeket előnkbe adott, az ő szolgái, a próféták által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'És az egész Izráel áthágta a te törvényedet, és elhajlottak, hogy ne hallgassanak a te szódra. Ezért reánk szakad az átok és eskü, a mely meg van írva Mózesnek, az Isten szolgájának törvényében; mert vétkeztünk ellene!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'És teljesíté az ő szavait, a melyeket szóla ellenünk és a mi bíráink ellen, a kik minket ítéltek, hogy nagy veszedelmet hoz reánk; mert nem történt olyan az egész ég alatt, a milyen történt Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'A mint írva van a Mózes törvényében, az a veszedelem mind reánk jöve! És az Úrnak, a mi Istenünknek szine előtt nem esedeztünk, hogy megtértünk volna a mi álnokságainkból, és figyeltünk volna a te igazságodra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'Azért készen tartotta az Úr a veszedelmet, és azt reánk hozá: mert igaz az Úr, a mi Istenünk minden cselekedetében, melyeket cselekszik; mert nem hallgattunk az ő szavára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'Most azért, oh mi Urunk, Istenünk! a ki kihoztad a te népedet Égyiptom földéből hatalmas kézzel, és nevet szereztél magadnak, mint ma is van: vétkeztünk, gonoszul cselekedtünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'Uram, a te igazságod teljessége szerint forduljon el, kérlek, a te haragod és búsulásod a te városodtól, Jeruzsálemtől, a te szentséges hegyedtől, mert a mi bűneinkért és a mi atyáink hamisságaiért gyalázatára van Jeruzsálem és a te néped mindeneknek mi körültünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'És most hallgasd meg, oh Istenünk, a te szolgádnak könyörgését és esedezéseit, és világosítsd meg az Úrért a te orczádat a te szent helyeden, a mely elpusztíttatott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'Hajtsad, én Istenem, a te füledet hozzánk és hallgass meg; nyisd meg szemeidet és tekintsd meg a mi pusztulásunkat és a várost, a mely a te nevedről neveztetik; mert nem a mi igazságunkban, hanem a te nagy irgalmasságodban bízva terjesztjük elődbe a mi esedezéseinket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, 'Uram, hallgass meg! Uram, légy kegyelmes! Uram, légy figyelmetes, és cselekedd meg, ne késedelmezzél tennen magadért, oh én Istenem; mert a te nevedről neveztetik a te városod és a te néped.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, 'És még szólék és imádkozám, és vallást tevék az én bűnömről, és az én népemnek, az Izráelnek bűnéről; és esedezésemet az Úr elé, az én Istenem elé terjesztém az én Istenemnek szent hegyéért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, 'És még az imádságot mondom vala, mikor ama férfiú, Gábriel, a kit elébb a látomásban láttam vala, sebességgel repülvén, megillete engem az estvéli áldozat idején.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, 'És értésemre adá, és szóla nékem és monda: Dániel, most jöttem ki, hogy értelemre tanítsalak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, 'A te esedezésed kezdetén egy szózat támadt, és én eljöttem, hogy megjelentsem; mert te kedves vagy: vedd eszedbe azért a szózatot, és értsd meg a látomást!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, 'Hetven hét szabatott a te népedre és szent városodra, hogy vége szakadjon a gonoszságnak és bepecsételtessék a bűn, és hogy eltöröltessék a hamisság és elhozassék az örök igazság, és bepecsételtessék a látomás és a próféták, és felkenettessék a Szentek szente.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, 'Tudd meg azért és vedd eszedbe: A Jeruzsálem újraépíttetése felől való szózat keletkezésétől a Messiás-fejedelemig hét hét és hatvankét hét van és újra megépíttetnek az utczák és a kerítések, még pedig viszontagságos időkben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 26, 'A hatvankét hét mulva pedig kiirtatik a Messiás és senkije sem lesz. És a várost és a szenthelyet elpusztítja a következő fejedelem népe; és vége lesz mintegy vízözön által, és végig tart a háború, elhatároztatott a pusztulás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 27, 'És egy héten át sokakkal megerősíti a szövetséget, de a hét felén véget vet a véres áldozatnak és az ételáldozatnak, és útálatosságok szárnyán pusztít, a míg az enyészet és a mi elhatároztatott, a pusztítóra szakad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, 'Czírusnak, Persia királyának harmadik esztendejében egy ige jelenteték Dánielnek, a ki Baltazárnak nevezteték; igaz az ige és nagy bajról való; és figyele az igére és megérté a látomást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, 'Azokon a napokon én, Dániel, bánkódtam három egész hétig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'Kívánatos étket nem ettem, hús és bor nem ment az én számba, és soha sem kentem meg magamat, míg el nem telék az egész három hét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, 'És az első hónapnak huszonnegyedik napján, ímé én a nagy folyóvíznek, azaz a Hiddekelnek partján valék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, 'És felemelém szemeimet, és látám, és ímé: egy férfiú, gyolcsba öltözve, és dereka ufázi aranynyal övezve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'És teste olyan mint a társiskő, és orczája olyan mint a villám, és szemei olyanok mint az égő szövétnekek, karjai és lábatája mint az izzó ércznek színe, és az ő beszédének szava olyan, mint a sokaság zúgása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'És egyedül én, Dániel láttam e látomást, a férfiak pedig, a kik velem valának, nem látták a látomást; hanem nagy rettenés szálla reájok, és elfutának, hogy elrejtőzzenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, 'És én egyedül hagyattam, és látám ezt a nagy látomást, és semmi erő sem marada bennem, és orczám eltorzula, és oda lőn minden erőm.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'És hallám az ő beszédének szavát; és mikor hallám az ő beszédének szavát, én ájultan orczámra esém, és pedig orczámmal a földre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'És ímé, egy kéz illete engem, és felsegített térdeimre és tenyereimre;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'És monda nékem: Dániel, kedves férfiú! Értsd meg a beszédeket, a melyeket én szólok néked, és állj helyedre, mert most te hozzád küldettem! És mikor e szót szólá velem, felállék reszketve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'És monda nékem: Ne félj Dániel: mert az első naptól fogva, hogy szívedet adtad megértésre és sanyargatásra a te Istened előtt, meghallgattattak a te beszédid, és én a te beszédeid miatt jöttem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, 'De Persiának fejedelme ellenem állott huszonegy napig, és ímé Mihály, egyike az előkelő fejedelmeknek, eljöve segítségemre, és én ott maradék a persa királyoknál;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'Jöttem pedig, hogy tudtodra adjam, a mi a te népedre az utolsó időkben következik: mert a látomás azokra a napokra szól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'És mikor ilyen szavakkal szóla velem, orczámmal a földre esém és megnémulék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'És ímé, olyan valaki, mint egy ember-fia, megilleté ajkaimat és megnyitám a számat és szólék és mondám annak, a ki előttem álla: Uram, a látomás miatt reám fordulának az én fájdalmaim, annyira, hogy semmi erőm nincsen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'És mi módon szólhat ezzel az én Urammal ennek az én Uramnak szolgája? Hiszen bennem attól fogva nem álla meg az erő, és lélekzet sem marada bennem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'És ismét illete engem az emberhez hasonló, és megerősíte engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, 'És monda: Ne félj, te kedves férfiú; békesség néked, légy erős és bizony erős! És mikor szóla velem, megerősödém, és mondék: Szóljon az én Uram, mert megerősítél engemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'És monda: Tudod-é, miért jöttem hozzád? És most visszatérek, hogy küzdjek a persa fejedelem ellen; és ha én kimegyek, ímé Görögország fejedelme jő elő!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, 'De megjelentem néked, a mi fel van jegyezve az igazság írásában; és senki sincsen, a ki én velem tartana ezek ellenében, hanem csak Mihály a ti fejedelmetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, 'Én is a méd Dárius első esztendejében mellette állék, hogy őt támogassam és segítségére legyek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, 'És most igazságot jelentek néked: Ímé, még három király támad Persiában, és a negyedik meggazdagul nagy gazdagsággal mindenki felett, és mikor hatalomhoz jut az ő gazdagsága által, mindent megmozdít Görögország ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'És támad egy erős király és uralkodik nagy hatalommal és tetszése szerint cselekszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'De alighogy támadt, megrontatik az ő országa és elosztatik az égnek négy tája szerint, de nem száll az ő maradékira, és nem az ő hatalma szerint, a melylyel ő uralkodott, mert szétszaggattatik az ő birodalma, és másoknak adatik ezeken kivül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, 'És elhatalmasodik a déli király, de az ő vezérei közül is egyik, és ez hatalmat vesz rajta és uralkodik, nagy uralkodás lesz az ő uralkodása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, 'És esztendők mulva szövetkeznek, és a déli király leánya az északi királyhoz megy, hogy békéltessen, de a kar erejét meg nem tarthatja, és ő sem áll meg, sem az ő karja, hanem kiszolgáltatják őt és az ő kisérőit és az ő nemzőjét és azt, a ki őt egy ideig gyámolította.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, 'De támad helyébe az ő gyökerének csemetéje közül, a ki a had ellen jön majd, és tör az északi király erősségeire, és azokat megszállja és beveszi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, 'És azoknak isteneit is bálványaikkal és drága arany- és ezüstedényeikkel együtt fogságba viszi Égyiptomba, és néhány esztendeig erősebb lesz, mint az északi király.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'Ez ugyan bemegy a déli király országába, de visszatér az ő földére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'De az ő fiai fegyverkeznek és sok nagy sereget gyűjtenek, és hirtelen jön és beözönlik, és átmegy és visszatér, és hadakoznak mind az ő erősségéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'És felháborodik a déli király, és kimegy és megütközik vele, az északi királylyal, és az nagy sokaságot állít fel, de ez a sokaság annak a kezébe adatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'És a mint a sokaság elfogatott: felfuvalkodik annak szíve, és sok ezeret letipor; még sem lesz hatalmas.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'Mert az északi király visszatér, és az előbbinél nagyobb sokaságot állít; néhány esztendő mulva nagy sereggel és nagy készlettel jő bizony.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'És azokban az időkben sokan támadnak a déli király ellen, a te néped erőszakos fiai is felkelnek, hogy beteljesítsék a látomást, de elhullanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'Mert eljő észak királya, és töltést emel és beveszi az erősített várost; és délnek seregei meg nem állnak, sem az ő válogatott népe, és semmi erő nem bír ellene állni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'És az, a ki reátört, a maga tetszése szerint cselekszik, és senki sem lesz, a ki ellene álljon, és megállapodik a dicső földön, és megsemmisül az az ő kezétől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, 'Azután maga elé tűzi, hogy bemegy az ő egész országának erejével, és békés szándékot mutat, és leányasszonyt ad néki feleségül, hogy megrontsa, de az nem áll meg és nem tart vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, 'És fordítja orczáját a szigetekre, és sokat elfoglal; de az ő gyalázatosságának véget vet egy vezér, a mellett, hogy megfizet néki az ő gyalázatosságáért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'És fordítja orczáját a maga országának erősségeire, és meghanyatlik, elesik és nem találtatik meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, 'Ennek helyébe jön az, a ki adószedőt jártat végig az ország dicső földén, de rövid időn megrontatik, noha nem haraggal, sem viadalban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, 'És ennek helyébe egy útálatos áll, a kire nem teszik az ország ékességét; hanem alattomban jő, és hízelkedéssel jut az országhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, 'És a beözönlő seregek elárasztatnak az ő orczája előtt és megtöretnek; még egy szövetséges fejedelem is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, 'Mert a vele való megbarátkozás óta csalárdul cselekszik ellene, és reátör és győzedelmet vesz rajta kevés néppel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, 'Alattomban még az ország gazdag részeibe is behatol, és azt cselekszi, a mit nem cselekedtek sem az ő atyái, sem az ő atyáinak atyái: zsákmányt, prédát és gazdagságot tékozol előlők, és az erősségek ellen is cselt kohol, de csak egy ideig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, 'És felindítja az ő erejét és szívét a déli király ellen nagy sereggel, és a déli király is hadra készül nagy sereggel és igen erőssel, de meg nem állhat, mert cselt koholtak ellene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'És a kik az ő ételét eszik, megrontják őt, és az ő serege elszéled, és sokan elhullanak seb miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, 'De ennek a két királynak szíve is gonoszt forral, és egy asztalnál hazugságot szólnak egymásnak; de siker nélkül, mert a vég még bizonyos időre elmarad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, 'Azért visszatér az ő földére nagy gazdagsággal; de az ő szíve a szent szövetség ellen van, és ellene tesz, és újra visszatér az ő földére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, 'Bizonyos időben megjő, és délre megy: de nem lesz utolszor úgy, mint először volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, 'Mert kitteus hajók jőnek ellene és megijed, és visszatér és dühöng a szent szövetség ellen és cselekszik ellene; visszatér és ügyel azokra, a kik elhagyják a szent szövetséget.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, 'És seregek állanak fel az ő részéről, és megfertéztetik a szenthelyet, az erősséget, és megszüntetik a mindennapi áldozatot, és felteszik a pusztító útálatosságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 32, 'És a kik gonoszul cselekesznek a szövetség ellen, azokat hitszegésre csábítja hizelkedésekkel; ellenben az Istenét ismerő nép felbátorodik és cselekeszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 33, 'És a nép értelmesei sokakat oktatnak, de hullanak fegyver és tűz miatt, fogság és rablás miatt napokig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 34, 'És miközben elhullanak, megsegíttetnek kicsiny segítséggel, és sokan csatlakoznak hozzájok képmutató beszédekkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 35, 'És elhullanak az értelmesek közül is, hogy megpróbáltassanak, megtisztíttassanak és megfehéríttessenek a vég idejéig; mert a rendelt idő még hátra van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 36, 'És a király a maga tetszése szerint cselekszik és felfuvalkodik és felmagasztalja magát minden isten felett, és az istenek Istene ellen is vakmerőn szól, és szerencsés lesz, mígnem betelik a harag; mert a mi elhatároztatott, az végre is hajtatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 37, 'Nem gondol atyáinak isteneivel, nem gondol az asszonyok kedvenczével, és egy istennel sem; hanem mindennek fölibe magasztalja magát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 38, 'De a helyett tiszteli az erődök istenét annak helyén; és azt az istent, a kit nem ismertek az ő atyái, tiszteli aranynyal, ezüsttel, drágakövekkel és becses ajándékokkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 39, 'És az erődített városokban így teszen az idegen istenek nevében: a ki hódol, annak dicsőségét megsokasítja és sokak felett ad nékik hatalmat; a földet elosztja jutalom gyanánt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 40, 'De a vég idején összetűz vele a déli király, és mint a forgószél, úgy megy reá az északi király szekerekkel, lovasokkal és sok hajóval, és betör az országokba, elözönli és végigjárja azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 41, 'És bemegy a dicső földre, és sokan elesnek; de ezek megszabadulnak az ő kezéből: Edom, Moáb és az Ammon fiainak színe-java.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 42, 'És kezeit az országokra veti, és Égyiptom földe meg nem menekedhetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 43, 'És ura lesz Égyiptom arany- és ezüst-kincseinek és minden drágalátos javainak; libiabeliek és szerecsenek is lesznek az ő kíséretében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 44, 'De megriasztják őt napkeletről és északról való hírek, és kivonul nagy haraggal, hogy elveszessen és megöljön sokakat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 45, 'És felvonja az ő sátor-palotáját a tengerek és a dicső szent hegy között; és végére jut, és senki sem segít rajta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, 'És abban az időben felkél Mihály, a nagy fejedelem, a ki a te néped fiaiért áll, mert nyomorúságos idő lesz, a milyen nem volt attól fogva, hogy nép kezdett lenni, mindezideig. És abban az időben megszabadul a te néped; a ki csak beírva találtatik a könyvben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'És sokan azok közül, a kik alusznak a föld porában, felserkennek, némelyek örök életre, némelyek pedig gyalázatra és örökkévaló útálatosságra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'Az értelmesek pedig fénylenek, mint az égnek fényessége; és a kik sokakat az igazságra visznek, miként a csillagok örökkön örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, 'Te pedig, Dániel, zárd be e beszédeket, és pecsételd be a könyvet a végső időig: tudakozzák majd sokan, és nagyobbá lesz a tudás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'És széttekinték én, Dániel, és ímé másik kettő álla ott, egyik a folyóvíz partján innét, a másik túl a folyóvíz partján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'És mondá egyik a gyolcsba öltözött férfiúnak, a ki a folyóvíz felett vala: Mikor lesz végök e csudadolgoknak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, 'És hallám a gyolcsba öltözött férfiút, a ki a folyóvíz felett vala, hogy felemelé az ő jobb kezét és bal kezét az ég felé, és megesküvék az örökké élőre, hogy ideig, időkig és fél időig, és mikor elvégezik a szent nép erejének rontását, mindezek elvégeztetnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, 'Én pedig hallám ezt, de nem értém, és mondám: Uram, mi lesz ezeknek vége?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, 'És monda: Menj el Dániel, mert be vannak zárva és pecsételve e beszédek a vég idejéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, 'Megtisztulnak, megfehérednek és megpróbáltatnak sokan, az istentelenek pedig istentelenül cselekesznek, és az istentelenek közül senki sem érti; de az értelmesek értik,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, 'És az időtől fogva, hogy elvétetik a mindennapi áldozat, és feltétetik a pusztító útálatosság, ezerkétszáz és kilenczven nap lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, 'Boldog, a ki várja és megéri az ezerháromszáz és harminczöt napot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, 'Te pedig menj el a vég felé; és majd nyugszol, és felkelsz a te sorsodra a napoknak végén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'Az Úr igéje, a mely lőn Hóseáshoz, a Beeri fiához, Uzziás, Jótám, Ákház, Ezékiás, Júdabeli királyok idejében, és Jeroboámnak, a Joás fiának, Izráel királyának idejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'A mikor beszélni kezde az Úr Hóseással, monda az Úr Hóseásnak: Menj, végy magadnak parázna feleséget és parázna gyermekeket; mert paráználkodván paráználkodik e föld, nem követvén az Urat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'Elméne tehát és elvevé Gómert, Diblajim leányát; és az teherbe esék, és fiút szűle néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'És mondá az Úr néki: Nevezd őt Jezréelnek, mert még egy kis idő, és megbüntetem a Jehu házát a Jezréel vére miatt, és eltörlöm Izráel házának királyságát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, 'És azon a napon lészen az, hogy eltöröm az Izráel ívét a Jezréel völgyében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'Ismét teherbe esék, és leányt szűle. És mondá néki az Úr: Nevezd őt Ló-Rukhámáhnak; mert nem kegyelmezek többé az Izráel házának, hogy akármiképen könyörülnék rajtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, 'De a Júda házának megkegyelmezek, és megtartom őket az Úr, az ő Istenök által; de nem tartom meg őket ív, vagy kard, vagy háború által, sem lovak és lovasok által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'Mikor elválasztá Ló-Rukhámáht, ismét teherbe esék, és fiút szűle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'És mondá az Úr: Nevezd őt Ló-Amminak; mert ti nem vagytok az én népem, s én sem leszek a tiétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 10, 'De mégis annyi lesz az Izráel fiainak száma, mint a tenger fövenye, a mely meg nem mérettethetik és meg nem számláltathatik; és lészen, hogy a hol az mondatott nékik: Nem vagytok az én népem, ez mondatik nékik: Élő Istennek fiai!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 11, 'És összegyűlnek Júda fiai és Izráel fiai együvé, és egy fejedelmet választanak, és feljőnek az országból, mert nagy lesz a Jezréel napja! Mondjátok atyátokfiainak: Ammi! és a ti húgaitoknak: Rukhámáh!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, 'Pereljetek anyátokkal, pereljetek (mert nem feleségem ő, és én sem vagyok néki férje), hogy tüntesse el az ő bujaságát arczáról, és az ő paráznaságát emlői közül;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'Különben meztelenre vetkőztetem őt és olyanná teszem, a milyen volt születése napján, és a pusztához teszem hasonlatossá, és olyanná változtatom őt, a milyen a kiaszott föld, és megölöm őt szomjúsággal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, 'Sőt fiain sem könyörülök, mert paráznaságnak fiai ők is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, 'Mert paráználkodott az ő anyjok; gyalázatba merült, a ki őket szülte; mert ezt mondotta: Elmegyek szeretőim után, a kik megadják kenyeremet, vizemet, gyapjúmat és lenemet, olajomat és italomat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'Azért ímé tövissel rekesztem el útadat, és sövényt fonok eleibe, hogy ne találja meg ösvényeit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'És szaladgál majd szeretői után, de nem éri el őket; és mikor keresi őket és nem találja meg azokat, azt mondja majd: Elmegyek hát és visszatérek előbbi férjemhez: mert jobb dolgom volt akkor, hogynem mint mostan:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'Mert nem vette eszébe, hogy én adtam néki a búzát, a mustot és az olajat, és én sokasítottam meg ezüstjét és az aranyat, a mit ők a Baálra költöttek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'Azért visszaveszem búzámat a maga idejében és mustomat is az ő divatjában, és elragadom gyapjúmat és lenemet, a melyek meztelensége befedésére lettek volna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'És most feltárom az ő gyalázatát szeretői előtt, és senki sem szabadítja őt ki az én kezemből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'És megszüntetem minden örömét, ünnepét, újholdját, szombatját és minden ünnepe napját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'És elpusztítom szőlejét és fügefáját, a melyekről ezt mondta: Ez az én bérem, a mit az én szeretőim adtak nékem, és erdővé teszem azokat, és a mezei vad emészti meg őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'És megbüntetem őt a Baálok napjaiért, a melyeken füstölve áldozott azoknak, és felrakta gyűrűjét és nyaklánczát, és elment szeretői után, rólam pedig elfeledkezett, ezt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'Azért ímé csalogatom őt, és elviszem őt a pusztába, és szívére beszélek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, 'És onnan adom meg néki az ő szőlőjét és az Akor völgyét a reménység ajtaja gyanánt, és úgy énekel ott, mint ifjúságának idején és mint Égyiptomból lett feljövetelének napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'És azon a napon, ezt mondja az Úr, így fogsz engem hívni: Én férjem, és nem hívsz engem többé így: Baálom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, 'És kiveszítem az ő szájából a Baálok neveit, hogy azoknak neve se említtessék többé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'És azon a napon frigyet szerzek nékik a mezei vadakkal, az égi madarakkal és a föld férgével, és az ívet, kardot és háborút eltörlöm e földről, és bátorságos lakozást adok nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, 'És eljegyezlek téged magamnak örökre, és pedig igazsággal és ítélettel, kegyelemmel és irgalommal jegyezlek el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'Bizony, hittel jegyezlek el téged magamnak, és megismered az Urat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'És azon a napon meghallgatom, azt mondja az Úr, meghallgatom az egeket, azok pedig meghallgatják a földet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, 'A föld pedig meghallgatja a búzát és a mustot és az olajat; azok pedig meghallgatják Jezréelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, 'És bevetem őt magamnak a földbe, és megkegyelmezek Ló-Rukhámának, és azt mondom Ló-Amminak: Én népem vagy te; ő pedig ezt mondja: Én Istenem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'És mondá az Úr nékem: Menj el újra, szeress egy asszonyt, a kit szeret az ő társa és mégis házasságtörő; a mint az Úr is szereti Izráel fiait, bár ők idegen istenekhez fordulnak, és szeretik a szőlőskalácsokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'És megszerzém azt magamnak tizenöt ezüstön és egy hómer árpán és egy letek árpán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'És mondám néki: Sok ideig ülsz nálam; nem paráználkodol és nem leszel férfié; én is így leszek te irántad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'Mert az Izráel fiai is sok ideig maradnak király nélkül, fejedelem nélkül, áldozat nélkül, szoborkép nélkül, efód nélkül és theráfok nélkül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'Azután megtérnek Izráel fiai és keresik az Urat, az ő Istenöket, és Dávidot, az ő királyukat, és remegve folyamodnak az Úrhoz és az ő jóságához az utolsó időkben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'Halljátok meg az Úrnak beszédét Izráel fiai, mert pere van az Úrnak a földnek lakóival, mert nincs igazság és nincsen szeretet és nincsen Istennek ismerete a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'Hamisan esküsznek és hazudnak és gyilkolnak és lopnak és paráználkodnak, betörnek és egyik vér a másikat éri.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'Azért búsul a föld és elerőtlenül minden, a mi azon lakik, a mező vada és az ég madara egyaránt, bizony a tenger halai is elveszíttetnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, 'Mindazáltal senki se perlekedjék, és senki se feddőzzék! hiszen a te néped olyan, mint azok, a kik a pappal czivódnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, 'De elesel nappal, és elesik veled a próféta is éjjel; anyádat is elveszítem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'Elvész az én népem, mivelhogy tudomány nélkül való. Mivelhogy te megvetetted a tudományt, én is megvetlek téged, hogy papom ne légy. És mivelhogy elfeledkeztél Istened törvényéről, elfeledkezem én is a te fiaidról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'Mennél számosabbak lettek, annál inkább vétkeztek ellenem; de gyalázatra fordítom dicsőségöket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, 'Népem vétkéből élősködnek ők és bűneik után áhítozik lelkök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'De úgy jár a pap is, mint a nép; megbüntetem őket az ő útaikért, és megfizetek néki cselekedeteiért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'Esznek majd, de meg nem elégesznek; fajtalankodnak, de nem szaporodnak, mert megszüntek az Úrra vigyázni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, 'Paráznaság, bor és must elveszi az észt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'Népem az ő bálványát kérdezi, és az ő pálczája mond néki jövendőt; mert a fajtalanság lelke megtéveszt, és paráználkodnak az ő Istenök megett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, 'A hegyek tetején áldoznak és a halmokon füstölnek: a cserfa, a nyárfa és a tölgyfa alatt, mert kedves annak az árnyéka. Ezért paráználkodnak a ti leányaitok, és házasságtörők a ti menyeitek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'Nem büntetem meg leányaitokat, hogy paráználkodnak, menyeiteket sem, hogy házasságtörők, mert ők magok is félremennek a paráznákkal és áldoznak a kurvákkal. De az értelmetlen nép elbukik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'Ha te paráználkodol is Izráel, csak a Júda ne vétkezzék! És ne járjatok Gilgálba, és ne menjetek fel Beth-Avenbe! és ne esküdjetek így: Él az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'Mert szilajkodik Izráel mint a szilaj üsző; most tágas földön legelteti őket az Úr, mint a bárányt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'Bálványokkal szövetkezett Efraim; hagyd hát magára!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, 'Ivásuk elfajult, untalan paráználkodnak; igen szeretik pajzsaik a gyalázatot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, 'Szárnyaihoz köti őt a szélvész, és megszégyenülnek áldozataik miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, 'Halljátok meg ezt, ti papok! Figyeljetek, Izráel háza! Hallgassatok ide királynak háza; hiszen reátok vonatkozik az ítélet, mert tőrré lettetek Miczpának, és kiterített hálóvá a Táboron.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, 'Szertelen a hitehagyottak öldöklése, de én mindnyájok fenyítéke leszek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'Jól ismerem én Efraimot, és Izráel nincs elrejtve előlem; hiszen most is paráználkodol Efraim! megfertőztetett az Izráel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'Nem engedik őket az ő cselekedeteik megtérni az ő Istenökhöz, mert paráznaság lelke van közöttük, és nem ismerik az Urat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'Izráel ellen az ő büszkesége tesz tanúbizonyságot, Izráel és Efraim bűneik miatt vesznek el; velök együtt Júda is elvész.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'Juhaikkal és ökreikkel mennek keresni az Urat, de nem találják; eltávozott az ő tőlük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'Hűtlenül cselekedtek az Úr ellen, mert idegen fiakat nemzettek; most azért megemészti őket az újhold, örökségeikkel egyben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, 'Fújjátok meg a kürtöt Gibeában, a tárogatót Rámában; rivalgjatok Beth-Avenben: Utánad Benjámin.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'Efraim pusztává lesz a büntetés napján; Izráel törzsei ellen kijelentettem a változhatatlan ítéletet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'Júda fejedelmei olyanok, mint a határrontók; kiontom rájok az én haragomat, mint a vizet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'Efraim el van nyomva, összetörve az ítélettől, mert tetszett néki követni az emberi rendelést!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, 'Én pedig olyanná lettem Efraimnak, mint a moly, és a Júda házának, mint a rothadás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'Látta ugyan Efraim a maga betegségét, Júda is a maga sebét, és Efraim Assiriához folyamodott és küldött Járéb királyhoz; de az nem tud titeket meggyógyítani, és nem veszi le rólatok a sebet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'Mert olyan leszek Efraimnak, mint az oroszlán, és Júda házának, mint az oroszlán-kölyök. Én, én szaggatom szét; elmegyek, felkapom, és nem lesz, a ki megszabadítsa!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, 'Elmegyek, visszatérek helyemre, mígnem megismerik, hogy vétkeztek, és keresni fogják az én orczámat. Nyomorúságukban keresnek majd engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, 'Jertek, térjünk vissza az Úrhoz, mert ő szaggatott meg és ő gyógyít meg minket; megsebesített, de bekötöz minket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'Megelevenít minket két nap mulva, a harmadik napon feltámaszt minket, hogy éljünk az ő színe előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'Ismerjük hát el, törekedjünk megismerni az Urat. Az ő kijövetele bizonyos, mint a hajnal, és eljő hozzánk, mint az eső, mint a késői eső, a mely megáztatja a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, 'Mit cselekedjem veled Efraim? Mit cselekedjem veled Júda? Hiszen szeretetetek olyan, mint a reggeli felhő és mint a korán múló harmat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'Azért vertem meg a próféták által és megölöm őket az én számnak beszédivel. Bizony, a te ítéleteid olyanok, mint a kelő nap.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'Mert szeretetet kivánok én és nem áldozatot: az Istennek ismeretét inkább, mintsem égőáldozatokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, 'De ők, mint Ádám, áthágták a szövetséget; ott cselekedtek hűtlenül ellenem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'Gileád a gonosztevők városa, vérrel van bemocskolva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'És miképen tolvajok leselkednek, úgy tesz a papok szövetkezete; gyilkolnak a sikemi úton; bizony, gonosz dolgokat cselekesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'Rettenetes dolgokat látok Izráel házában. Ott van Efraim paráználkodása; meg van fertőztetve Izráel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'Júda! a te számodra is készített aratást, mikor fordítok az én népemnek fogságán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'A mikor gyógyítani akarnám Izráelt, akkor tudódik ki Efraim vétke és Samaria gonoszsága; mert csalárdul cselekesznek, tolvaj tör be, és rabló fosztogat az utczán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'És eszökbe sem veszik, hogy emlékezem minden gonoszságukra. Most körülvették őket az ő cselekedeteik, a melyek színem előtt vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'Gonoszságukkal gyönyörködtetik a királyt, és hazugságaikkal a fejedelmeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'Mindnyájan házasságtörők; olyanok, mint a kemencze, a melyet befűt a sütő; szünetel a tüzeléssel, a tészta bekovászolásától annak megkeléséig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'Királyunk napján a fejedelmek beteggé lesznek a bor hevétől; csúfolóknak nyújtja az ő kezét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'Mert, mint a kemencze, közelednek álnokságukban az ő szívökkel. Egész éjszaka alszik az ő sütőjök; reggel ég, mint a lángoló tűz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'Mindnyájan tüzesek, mint a sütő kemencze, és megemésztik biráikat. Királyaik mind elhullottak. Nincs köztök senki, a ki hozzám kiáltana.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'Efraim összekeveredett a népekkel. Olyanná lőn az Efraim, mint a meg nem fordított pogácsa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'Idegenek emésztik erejét, de ő nem veszi észre. Ősz hajjal is hintve van már, és azt sem veszi észre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'Izráel ellen az ő büszkesége tesz tanúbizonyságot, és még sem térnek vissza az Úrhoz, az ő Istenökhöz, és nem keresik őt mindennek daczára sem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'És olyan lett Efraim, mint az együgyű galamb: balgatag! Égyiptomhoz kiáltanak, Assiriához folyamodnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'De a mint mennek, kiterjesztem hálómat ellenök; levonszom őket, mint az ég madarát; megbüntetem őket az ő gyülekezetöknek adott kijelentés szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'Jaj nékik, mert eltávoztak én tőlem! Pusztulás reájok, mert vétkeztek ellenem. Én ugyan megszabadítanám őket; de ők hazugságot szólnak ellenem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'És nem kiáltanak hozzám szívökből, hanem ordítoznak ágyasházaikban; a búza és a must miatt gyűlnek egybe; ellenem fordulnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'Pedig én tanítottam őket, én erősítettem meg karjokat, és ők mégis gonoszt gondolnak ellenem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'Megtérnek, de nem a magasságos Istenhez. Olyanok, mint a csalárd kézív. Fegyvertől hullnak el fejedelmeik, az ő nyelvöknek mérge miatt. Ez lesz gyalázatjok Égyiptom földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, 'Szádhoz a kürtöt! Mint a sas, úgy jön az Úr házára! Mert megszegték az én frigyemet, és vétkeztek az én törvényem ellen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'Kiáltnak hozzám: Én Istenem! mi, az Izráel, ismerünk tégedet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'Megvetette Izráel a jót, kergesse hát az ellenség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'Királyt emeltek ők; de nem én általam; fejedelmet választottak, de tudtomon kivül. Ezüstjökből és aranyukból bálványokat formáltak; csak azért, hogy semmivé legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'Megútálta a te borjúdat, oh Samaria! Haragom felgerjedt ellenök. Meddig nem lehetnek még tiszták?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'Mert ez is Izráelből való! kézműves csinálta azt, és nem Isten az. Bizony forgácscsá lesz Samaria borjúja!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'Mert szelet vetnek és vihart aratnak. Nem indul szárba; termése nem ad lisztet; ha adna is, idegenek nyelik be azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'Elnyeletett Izráel! Olyan immár a népek közt, mint az edény, a melyen nincs gyönyörűség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'Mert ők Assiriához folyamodnak; Efraim magában bolygó vadszamár; szeretőket bérelnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'De ha bérelnek is a pogányok közt, most összegyűjtöm őket, és kezdenek majd lefogyni a fejedelmek királyának terhétől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'Mivel megszaporította Efraim az oltárokat a bűnre, bűnre vezették őt az oltárok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, 'Ha tízezer törvényt írnék is elébe, idegennek tekintenék azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'Nékem szánt áldozatképen húst vágnak és esznek; az Úr nem tekint azokra kedvesen. Immár megemlékezik az ő álnokságukról, és megbünteti az ő vétkeiket; Égyiptomba fognak ők visszatérni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'Most Izráel elfeledkezett az ő alkotójáról és palotákat épített; Júda megerősített városokat szaporított. De én tüzet bocsátok városaira, és az emészti meg az ő erősségeit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'Ne örvendezz Izráel oly vígan, mint a pogányok; mert paráználkodással elszakadtál a te Istenedtől, és szeretted a bűnbért minden búzaszérűn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, 'Szérű és sajtó nem tartja el őket; hiányozni fog abból a must.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'Nem maradnak az Úr földén, hanem Égyiptomba tér vissza Efraim; Assiriában tisztátalant esznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'Nem áldoznak az Úrnak borral; és nem lesznek kedvesek előtte. Áldozataik olyanok lesznek, mint a gyásztornak kenyere; mindnyájan, a kik abból esznek, megfertéztetnek, mert kenyerök csak étvágyuknak szolgál; nem jut be az Úr házába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'Mit cselekesztek majd az ünnepnek napján, az Úr ünnepnapján?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'Mert ímé elbujdosnak a pusztulás miatt; Égyiptom gyűjti be, Móf temeti el őket. Ezüst kincsöket a csalán örökli; tövis lesz sátoraikban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, 'Elérkeztek a számadásnak napjai; elérkeztek a megtorlásnak napjai; megtudja majd Izráel! Bolond a próféta, őrült a léleknek embere a te vétked sokasága miatt és mert akkora a gyűlölség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'Efraim szétnéz az én Istenem mellett. A prófétának minden útaira háló vettetett; gyűlölség van Istenének házában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'Mélyen elfajultak, mint Gibea napjaiban; de megemlékezik álnokságaikról, és megbünteti az ő gonoszságokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, 'Mint szőlőfürtöket a pusztában, úgy találtam Izráelt; mint a fügefa első termésének zsengéjét, úgy néztem a ti atyáitokat; de bementek Baál-Peorhoz és a gyalázatosnak adták magokat, és útálatossá váltak, mint a mit szerettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'Efraim! Elszáll dicsőségök, mint a madár! Nem lesz szülés, sem terhesség, sem fogamzás!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'Mert még ha felnevelnék is fiaikat, mégis gyermektelenekké teszem őket; sőt még nékik is jaj, ha elfordulok tőlök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'Efraim, a mint néztem, mint Tírus van plántálva a mezőben; de Efraimnak mégis az öldöklőhöz kell kihoznia az ő fiait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'Adj nékik oh Uram! Mit adj? Adj nékik meddő méhet és kiszáradt emlőket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, 'Minden gonoszságuk Gilgálban van, mert ott gyűlöltem meg őket. Cselekedeteik gonoszsága miatt kiűzöm őket házamból; nem szeretem őket többé; fejedelmeik mindnyájan pártütők.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'Meg van verve Efraim, gyökerök elszáradt! Nem teremnek gyümölcsöt. Még ha nemzenének is, megölöm méhöknek szerelmes magzatit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'Elveti őket az én Istenem, mert nem hallgattak reá, és bujdosókká lesznek a pogányok között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'Buja szőlőtő az Izráel, a mely termi az ő gyümölcseit. Gyümölcsének sokasága szerint sokasította meg oltárait, földének jósága szerint jó sok oszlopot állított fel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'Csalárd a szívök; de most meglakolnak! Ő maga töri le oltáraikat; elpusztítja bálványaikat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'Bizony mondják most: Nincsen királyunk, mert nem féljük az Urat, és a király mit segíthet rajtunk?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'Össze-vissza beszéltek; hamisan esküdtek; szövetséget kötöttek; de mint a bürök a mező barázdáin, úgy sarjadzik ki az ítélet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'Beth-Aven borjúi miatt aggódnak Samaria lakói. Bizony megsiratja azt az ő népe, és papjai is remegnek miatta, az ő dicsősége miatt; mert eltávozott az attól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'Azt magát is Assiriába vonszolják ajándékul Járeb királynak. Szégyent vall Efraim, és megszégyenül Izráel az ő tanácsa miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, 'Elveszett Samaria! Az ő királya, mint forgács a víz színén!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'És Aven magaslatai, az Izráel vétke, lerontatnak. Tövis és bogácskóró növi be oltáraikat, és mondják majd a hegyeknek: Borítsatok be minket! a halmoknak pedig: Omoljatok reánk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, 'Gibea napjaitól fogva vétkezél, oh Izráel! Ott maradtak; nem érte őket Gibeában a harcz a gonoszság fiai ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, 'Megfenyítem hát őket kedvemre! Népek gyülekeznek ellenök, a mikor megkötöztetnek kettős gazságukért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'Efraim szoktatott üsző, a mely szeret nyomtatni; de én rámegyek az ő szép nyakára: igába fogom Efraimot; Júda szántani fog, Jákób boronál néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'Vessetek magatoknak igazságra; arassatok kegyelem szerint! Szántsatok magatoknak új szántást; mert ideje keresnetek az Urat, mígnem eljő, hogy igazság esőjét adjon néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'Istentelenséget szántottatok, álnokságot arattatok. Eszitek a hazugság gyümölcsét, mert bíztál a te utadban és vitézeidnek sokaságában!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'Azért zendülés támad a te néped között, és minden te erősséged elpusztíttatik, a miképen elpusztította Salman Beth-Arbelt a harcznak napján; az anya gyermekeivel együtt földhöz veretik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'Így cselekszik veletek Beth-El, a ti nagy gonoszságtokért; hajnalra bizony elvész Izráel királya!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, 'Mikor még gyermek volt Izráel, megszerettem őt, és Égyiptomból hívtam ki az én fiamat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, 'A mint hívták őket, úgy mentek el előlök: a Baáloknak áldoztak és a bálványoknak füstöltek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, 'Pedig én tanítottam járni Efraimot; ő vette őket karjaira, de ők nem ismerték el, hogy én gyógyítottam meg őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'Emberi kötelékekkel vontam őket, szeretetnek köteleivel, és olyan voltam hozzájok, mint a kik leemelik szájukról az igát, és ételt adtam nyájasan eleikbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'Nem tér vissza Égyiptom földére; hanem Assiria lesz az ő királya, mert nem akarnak megtérni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, 'És fegyver száll az ő városaira, és elpusztítja az ő zárait, és felemészti őket az ő szándékaik miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, 'Mert az én népem átalkodottan hajlandó elfordulni tőlem. Ha hivogatják is őt a magasságos Istenhez, senki nem indul meg rajta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'Miképen adnálak oda Efraim, szolgáltatnálak ki Izráel!? Miként adnálak oda, mint Admát, tennélek olyanná, a milyen Seboim?! Megesett bennem az én szívem; fellángolt minden szánalmam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'Nem végzem el haragomnak hevét; nem fordulok vissza Efraim vesztére; mert Isten vagyok én és nem ember, a Szent te közötted, és nem haraggal jövök én.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'Az Urat fogják követni. Ordít, mint az oroszlán; ha ő ordít, remegve gyűlnek össze fiak napnyugot felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, 'Rettegve jőnek elő, mint a madár, Égyiptomból, és mint a galamb, Assiriának földéből; és letelepítem őket házaikba, ezt mondja az Úr! Körülvett engem Efraim hazugsággal, az Izráel háza pedig csalárdsággal; de Júda uralkodik még az Istennel és a hűséges Szenttel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, 'Széllel táplálkozik Efraim és fut a keleti szél után. Mindennap szaporítja a hazugságot és a sanyargatást, és frigyet szereznek az Assirussal és Égyiptomba visznek olajat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, 'Pere van az Úrnak a Júdával is, és megbünteti Jákóbot az ő útai szerint. Cselekedetei szerint fizet meg néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, 'Anyja méhében sarkon fogta bátyját, és mikor erős volt, küzdött az Istennel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, 'Küzdött az angyallal és legyőzte; sírt és könyörgött néki. Béthelben találta meg őt, és ott beszélt velünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'Bizony az Úr, a seregeknek Istene; az Úr az ő neve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, 'Térj hát vissza a te Istenedhez; őrizd meg az irgalmasságot és az ítéletet, és bízzál szüntelen a te Istenedben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, 'Kanaánita ő! Hamis mértékek vannak kezében; szeret mást megcsalni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, 'És Efraim ugyan ezt mondja: Bizony meggazdagodtam; vagyont szerzettem magamnak. Semmi szerzeményemben nem találnak rajtam álnokságot, a mely bűn volna!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, 'De én vagyok az Úr, a te Istened Égyiptom földétől kezdve. Újra sátorok lakójává teszlek téged, mint az ünneplés napjain.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, 'Mert én szólottam a prófétákhoz; én sokasítottam meg a látásokat, és én szólottam hasonlatokban a próféták által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, 'Ha Gileád a gonoszság városa, bizony semmivé lesznek! Gilgálban ökrökkel áldoznak; de oltáraik is olyanokká lesznek, mint a kőrakások a mező barázdáin.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, 'Jákób Aram földére bujdosott, és egy asszonyért szolgált az Izráel, és egy asszonyért pásztorkodott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, 'És próféta által hozta fel az Úr Izráelt Égyiptomból, és próféta által tartatott meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, 'Gonoszul ingerelte Efraim az Istent; de rajta szárasztja a sok vért, és gyalázatosságát megfizeti néki az ő Ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 15, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, 'Efraim szólott volt, rettegés: nagygyá lett Izráelben, de vétkezett a Baállal, és meghalt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, 'Most is többítik bűneiket és csinálnak magoknak öntött képeket az ő ezüstjökből, bálványokat az ő eszök szerint. Képfaragók csinálmánya mindaz! Róluk mondják: Emberek, a kik áldoznak, borjúkat csókolnak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, 'Azért olyanná lesznek, mint a reggeli felhő és mint a harmat, a mely korán eltűnik; mint a szérűről elsodort polyva és mint a kéménynek füstje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, 'Pedig én vagyok az Úr, a te Istened Égyiptom földétől fogva. Nem ismerhetsz más Istent kivülem, és rajtam kivül nincs más szabadító!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, 'Én ismertelek téged a pusztában, az eltikkadt földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, 'A mint legeltek: elteltek; elteltek és szívök felfuvalkodék: azért hát elfelejtkezének rólam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, 'De olyan is leszek hozzájok, mint az oroszlán; mint a párducz, úgy lesekedem az úton.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, 'Rájok rohanok, mint a kölykétől megfosztott medve, és széttépem szívök borítóját, és felfalom ott őket, mint egy nőstény oroszlán. A mezei vad szaggatja szét őket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, 'Romlásodra lett Izráel, hogy ellenem törekedtél, a te segítőd ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, 'Hol van hát a te királyod, hol van, hogy megoltalmazzon minden városodban? És biráid, a kik felől ezt mondád: Adj nékem királyt és fejedelmeket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, 'Adtam néked királyt haragomban, és elvettem az én búsulásomban!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, 'Egybe van kötve Efraim álnoksága; eltéve az ő bűne!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, 'A szülőasszony kínjai lepik meg őt; oktalan fiú ő, mert a kellő időben nem jő ki anyjának méhéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, 'Megváltom őket a Seol hatalmából! Megmentem őket a haláltól! Hol van a te veszedelmed oh halál?! Hol van a te romlásod oh Seol?! Megbánás elrejtetett én előlem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, 'Mert bár a testvérek közt ő a legvirágzóbb: feljő a keleti szél, az Úr szele támad fel a pusztából; kiszárad kútfeje, elapad forrása: az rabolja ki minden drága kincseinek tárházát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 16, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, 'Meglakol Samaria, mert daczolt az ő Istenével. Fegyver által hullanak el; csecsemőik földhöz veretnek, és terhes asszonyaik ketté vágatnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, 'Térj vissza hát Izráel az Úrhoz, a te Istenedhez, mert elbuktál álnokságod miatt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, 'Vigyetek veletek beszédeket, és térjetek vissza az Úrhoz! Mondjátok néki: Végy el minden álnokságot! És fogadd el azt, a mi jó, és ajkaink tulkaival áldozunk néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, 'Assiria nem segít meg minket; lóra sem ülünk, és nem mondjuk többé kezeink csinálmányának: Istenünk! Mert nálad talál kegyelmet az árva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, 'Kigyógyítom őket hűtlenségökből; szeretem őket ingyen kegyelemből, mert elfordult tőlök az én haragom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, 'Olyanná leszek Izráelnek, mint a harmat. Virágozni fog, mint a liliom, és gyökeret ver, mint a Libánon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, 'Kiterjednek az ő ágai, és olyan lesz az ő ékessége, mint az olajfáé, illata pedig, mint a Libánoné.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, 'Visszatérnek az ő árnyékában lakók, és felelevenednek, mint a búzamag, és virágoznak, mint a szőlőtő; híre olyan lesz, mint Libánon boráé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, 'Efraim így szól: Mi közöm nékem többé a bálványokhoz?! Én meghallgatom és figyelek reá. Olyan vagyok, mint a zöldelő cziprusfa! Tőlem származik a te gyümölcsöd! Kicsoda a bölcs, hogy értse ezeket? Kicsoda az értelmes, hogy eszébe vegye ezeket?! Bizony igazak az Úrnak útai, és az igazak járnak azokon, az istentelenek pedig elesnek rajtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'Az Úrnak igéje, a mely lőn Jóelhez, a Petuel fiához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, 'Vének! halljátok meg ezt, és hallgassátok meg, e földnek minden lakói! Történt-é ilyen a ti időtökben, vagy a ti atyáitoknak idejében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'Beszéljétek el azt a ti fiaitoknak, és a ti fiaitok az ő fiaiknak, és azoknak fiai a következő nemzetségnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'A mit a sáska meghagyott, megette a szöcskő; és a mit a szöcskő meghagyott, megette a cserebogár; és a mit a cserebogár meghagyott, megette a hernyó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'Serkenjetek fel részegek és sírjatok, és jajgassatok mind, ti borivók a mustért, mert elvétetett az a ti szátoktól!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'Mert egy nép jött fel az én földemre, erős és megszámlálhatatlan; fogai, mint az oroszlán fogai, és agyarai, mint a nőstény oroszláné.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, 'Pusztává tette szőlőmet; összetörte fügefáimat, mezítelenre hántotta és széjjelhányta; fehérlenek annak ágai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, 'Keseregj, mint a szűz, a ki gyászba öltözik az ő ifjúsága férjéért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, 'Kifogyott az étel- és italáldozat az Úrnak házából; gyászolnak a papok, az Úrnak szolgái.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, 'Elpusztíttatott a mező, gyászol a föld; mert elpusztíttatott a gabona; kiszáradt a must; kiapadt az olaj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'Szégyenüljetek meg, ti szántóvetők; jajgassatok szőlőművesek: a búzáért és az árpáért; mert elveszett a mező aratása!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, 'Elszáradt a szőlőtő; a fügefa elhervadt; a gránátfa, a datolyafa és az almafa, a mezőnek minden gyümölcsfája kiaszott. Bizony kiszáradott az öröm az emberek közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'Öltsetek gyászt és sírjatok, ti papok! Jajgassatok, ti oltár szolgái; jőjjetek és háljatok gyászruhákban, Istenem szolgái; mert megvonatott az étel- és italáldozat Isteneteknek házától.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'Szenteljetek bőjtöt, hirdessetek gyűlést; gyűjtsétek egybe a véneket, a földnek minden lakosát az Úrnak, a ti Isteneteknek házába, és kiáltsatok az Úrhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, 'Jaj ez a nap! Bizony közel van az Úrnak napja, és mint a pusztítás, úgy jön el a Mindenhatótól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, 'Hát nem szemünk láttára irtatott-é ki az élelem, az öröm és vígasság Istenünk házából?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, 'Elsenyvedtek a magvak barázdáik alatt, elpusztultak a gabonás házak, összedőltek a csűrök; mert kiaszott a gabona.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, 'Mint nyög a barom! Megháborodtak a marha-csordák, mert nincs legelőjük; bűnhődnek még a juhnyájak is!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, 'Hozzád kiáltok Uram, mert tűz emésztette meg a puszta virányait, és láng perzselte le a mező minden fáját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, 'A mező vadai is hozzád esengenek, mert kiszáradtak a vizeknek ágyai, és tűz emésztette meg a puszta virányait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, 'Fújjátok a kürtöt a Sionon, és rivalgjatok az én szent hegyemen! Rémüljenek meg e föld minden lakói; mert eljő az Úrnak napja; mert közel van az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'Sötétségnek és homálynak napja; felhőnek és borulatnak napja; mint a hegyekre ráterülő alkonyat! Nagy és hatalmas nép, a milyen nem volt öröktől fogva és nem is lesz utána többé, nemzetségről nemzetségre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, 'Előtte tűz emészt, utána láng lobog; előtte a föld olyan, mint az Éden kertje, utána pedig kietlen pusztaság; meg sem menekülhet tőle semmi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'A milyen a lovak alakja, olyan annak alakja, és száguldoznak, mint a lovasok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'Rohannak a hegyek tetején, mintha hadi szekerek robognának; mintha tarlót emésztő láng ropogna; a milyen az ütközetre kész hatalmas nép.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'Elrémülnek tőle a népek; minden arcz elsáppad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'Száguldoznak, mint a hősök, felhágnak a kőfalakra, mint a bajnokok; mindenik a maga útján halad, nem bontják meg soraikat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, 'Egymást nem szorongatják; mindenik a maga útján halad; néki rohannak a fegyvernek, és nem esik seb rajtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'Betörnek a városba, futkároznak a kőfalon, felhágnak a házakra, betörnek az ablakokon, mint a tolvaj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'Reszket előttök a föld, és megrendülnek az egek; a nap és hold elsötétednek, a csillagok is bevonják fényöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'És megzendül az Úrnak szava az ő serege előtt, mert felette nagy az ő tábora; mert hatalmas az ő rendeletének végrehajtója. Bizony nagy az Úrnak napja és igen rettenetes! Ki állhatja ki azt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, 'De még most is így szól az Úr: Térjetek meg hozzám teljes szívetek szerint; bőjtöléssel is, sírással is, kesergéssel is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'És szíveteket szaggassátok meg, ne ruháitokat, úgy térjetek meg az Úrhoz, a ti Istenetekhez; mert könyörülő és irgalmas ő; késedelmes a haragra és nagy kegyelmű, és bánkódik a gonosz miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, 'Ki tudja, hátha visszatér és megbánja, és áldást hagy maga után; étel- és italáldozatot az Úrnak, a ti Isteneteknek?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, 'Fújjatok kürtöt a Sionon; szenteljetek bőjtöt, hirdessetek gyűlést!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'Gyűjtsétek össze a népet, szenteljétek meg a gyülekezetet; hívjátok egybe a véneket, gyűjtsétek össze a kisdedeket és a csecsszopókat; menjen ki a vőlegény az ő ágyasházából és a menyasszony is az ő szobájából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, 'A tornácz és az oltár között sírjanak a papok, az Úr szolgái, és mondják: Légy kegyelmes, oh Uram, a te népedhez, és ne bocsásd szidalomra a te örökségedet, hogy uralkodjanak rajtok a pogányok. Miért mondanák a népek között: Hol az ő Istenök?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, 'Erre buzgó lőn az Úrnak szeretete az ő földe iránt, és kegyelmezett az ő népének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, 'És választ tőn az Úr, és mondá az ő népének: Ímé, adok néktek gabonát, bort és olajat, hogy megelégedtek vele, és nem adlak többé titeket szidalomra a pogányok között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, 'Az északi népet is elűzöm tőletek, és puszta és sivatag vidékre vetem azt; elejét a keleti tengerbe, hátulját a nyugoti tengerbe, és bűze magasra száll; felszáll büdössége, mert nagy dolgokat cselekedett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, 'Ne félj, te föld! Örülj és vígadozz, mert nagy dolgokat cselekeszik az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, 'Ne féljetek, ti mezei vadak! mert zöldülnek a pusztának virányai; mert a fa megtermi gyümölcsét; a füge és szőlő is kitárják gazdagságukat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 23, 'Ti is, Sionnak fiai! örvendezzetek és vígadjatok az Úrban, a ti Istenetekben; mert megadja néktek az esőt igazság szerint, és korai és kései esőt hullat néktek az első hónapban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 24, 'És megtelnek a csűrök gabonával, és bőven öntik a sajtók a mustot és az olajat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 25, 'És kipótolom néktek az esztendőket, a melyeket tönkre tett a szöcskő, a cserebogár és a hernyó és a sáska; az én nagy seregem, a melyet reátok küldöttem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 26, 'És esztek bőven és megelégesztek, és magasztaljátok az Úrnak, a ti Isteneteknek nevét, a ki csodálatosan cselekedett veletek, és soha többé nem pironkodik az én népem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 27, 'És megtudjátok, hogy az Izráel között vagyok én, és hogy én vagyok az Úr, a ti Istenetek és nincs más! És soha többé nem pironkodik az én népem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 28, 'És lészen azután, hogy kiöntöm lelkemet minden testre, és prófétálnak a ti fiaitok és leányaitok; véneitek álmokat álmodnak; ifjaitok pedig látomásokat látnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 29, 'Sőt még a szolgákra és szolgálóleányokra is kiöntöm azokban a napokban az én lelkemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 30, 'És csodajeleket mutatok az égen és a földön; vért, tüzet és füstoszlopokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 31, 'A nap sötétséggé válik, a hold pedig vérré, minekelőtte eljő az Úrnak nagy és rettenetes napja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 32, 'De mindaz, a ki az Úrnak nevét hívja segítségül, megmenekül; mert a Sion hegyén és Jeruzsálemben lészen a szabadulás, a mint megigérte az Úr, és a megszabadultak közt lesznek azok, a kiket elhí az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, 'Mert ímé, azokon a napokon és abban az időben, a mikor meghozom Júda és Jeruzsálem fogságát:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'Egybegyűjtöm akkor mind a pogányokat, és levezetem őket a Josafát völgyébe, és perbe szállok ott velök, az én népemért és örökségemért, az Izráelért, a melyet szétszórtak a pogányok közé, és megosztoztak az én földemen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'Népemre pedig sorsot vetettek; a fiút szajháért adták oda, a leányt pedig borért cserélték el, hogy ihassanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'Sőt néktek is mi közötök velem, Tírus, Sidon és Filiszteának egész környéke?! Vajjon bosszút állani jöttök-é reám? Ha bosszút akarnátok rajtam állani, nagy hirtelen fejetekre fordítom vissza bosszútokat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, 'Mivelhogy elraboltátok ezüstömet és aranyomat, és legszebb kincsemet templomaitokba vittétek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 6, 'És a Júda fiait és Jeruzsálem fiait eladtátok a Jávánok fiainak, hogy messze vessétek őket határaiktól:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 7, 'Ímé, kiindítom őket a helyből, a hova eladtátok őket, és fejetekre fordítom vissza bosszútokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 8, 'És adom a ti fiaitokat és leányaitokat a Júda fiainak kezébe; azok pedig eladják őket a Sabeusoknak, a messze lakó népnek; mert ezt végezte az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 9, 'Hirdessétek ezt a pogányok között; készüljetek harczra; indítsátok fel a hősöket. Járuljanak elé, jőjjenek fel mindnyájan a hadakozó férfiak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 10, 'Kovácsoljátok szántóvasaitokat kardokká, kaszáitokat dárdákká; mondja a beteg is: Hős vagyok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 11, 'Siessetek és jőjjetek el ti népek mindenfelől, és seregeljetek egybe! Ide vezesd Uram a te hőseidet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 12, 'Serkenjenek fel és jőjjenek fel a népek a Josafát völgyébe; mert ott ülök törvényt, hogy megítéljek minden népeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 13, 'Ereszszétek néki a sarlót, mert megérett az aratni való! Jertek el, tapossatok, mert tetézve a kád, ömlenek a sajtók! Mert megsokasult az ő gonoszságuk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 14, 'Tömegek, tömegek! az ítélet völgyében! Mert közel van az Úrnak napja az ítélet völgyében!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 15, 'A nap és hold elsötétednek; a csillagok bevonják fényöket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 16, 'Az Úr pedig megharsan a Sionról és megzendül Jeruzsálemből, és megrendülnek az egek és a föld; de az Úr az ő népének oltalma és az Izráel fiainak erőssége!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 17, 'És megtudjátok, hogy én vagyok az Úr, a ti Istenetek, a ki a Sionon lakozom, az én szent hegyemen. És szentté lészen Jeruzsálem, és idegenek nem vonulnak át többé rajta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 18, 'És majd azon a napon a hegyek musttal csepegnek és a halmok tejjel folynak, és a Júda minden medre bő vízzel ömledez, és forrás fakad az Úrnak házából, és megöntözi a Sittimnek völgyét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 19, 'Égyiptom pusztasággá lészen, Edom pedig kietlen sivataggá; a Júda fiain való erőszakosságért, mert ártatlan vért ontottak azoknak földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 20, 'De a Júda örökké megmarad; Jeruzsálem is nemzetségről nemzetségre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 21, 'És kitisztítom vérökből, a melyből még ki nem tisztítottam, és a Sion lesz az Úr lakóhelye!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'Ámós beszédei, a ki a Tékoabeli pásztorok közt volt, azokról, a miket Izráel felől látott Uzziásnak, Júda királyának idejében, és Jeroboámnak, a Jóás fiának, Izráel királyának idejében, két esztendővel a földindulás előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'És mondá: A Sionról megharsan az Úr és Jeruzsálemből megzendül, és elhervadnak a pásztorok legelői, és megszárad a Kármel teteje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'Így szól az Úr: Három bűne miatt Damaskusnak, sőt négy miatt, nem fordítom el, mert vas-cséplőkkel cséplették meg a Gileádot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'Tüzet vetek azért Hazáel házára, és az emészti meg a Ben-Hadad palotáit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, 'És összetöröm Damaskus zárját, és kivágom a lakót Avennek völgyéből és a királyi pálcza tartóját Beth-Édenből, és Aramnak népe Kirbe fogva vitetik, ezt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'Így szól az Úr: Három bűne miatt Gázának, sőt négy miatt, nem fordítom el, mert az egész népet rabságra vitték, hogy az Edomitáknak adják el őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'Tüzet vetek azért Gáza kőfalára, és az emészti meg az ő palotáit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'És kivágom a lakót Asdódból, és a királyi pálcza tartóját Askelonból, és Akronra is majd rávetem kezemet és a Filiszteusok maradéka elvész, azt mondja az én Uram, az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'Így szól az Úr: Három bűne miatt Tírusnak, sőt négy miatt, nem fordítom el, mert az egész rabnépet Edomnak adták át, és nem emlékeztek meg a testvéri frigyről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'Tüzet vetek azért Tírus kőfalára, és az emészti meg az ő palotáit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'Így szól az Úr: Három bűne miatt Edomnak, sőt négy miatt, nem fordítom el, mert fegyverrel űzte saját atyjafiát, és elfojtá szívében az irgalmasságot, és haragja szüntelen tépett, és dühösködését mindvégig fentartotta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'Tüzet vetek azért Témánra, és az emészti majd meg Boczra palotáit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'Így szól az Úr: Három bűne miatt Ammon fiainak, sőt négy miatt, nem fordítom el; mert széthasogatták Gileád terhes asszonyait, hogy kiszélesíthessék az ő határokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'Tüzet vetek azért Rabba kőfalára, és az emészti meg az ő palotáit; harczi kiáltással a háború napján, pusztító viharral a szélvésznek napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'És számkivetésbe megy az ő királyuk; ő maga és vele fejedelmei is, ezt mondja az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'Így szól az Úr: Három bűne miatt a Moábnak, sőt négy miatt, nem fordítom el; mert mészszé égette Edom királyának csontjait!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, 'Tüzet vetek azért Moábra, és az emészti meg Kerijjoth palotáit, és meghal Moáb a zajban, hadi lárma közt, a kürt zengése közben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'Kivágom a birót közüle, és minden fejedelmit megölöm vele egyetemben, ezt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'Így szól az Úr: Három bűne miatt a Júdának, sőt négy miatt, nem fordítom el; mert megvetették az Úrnak törvényét és nem tartották meg rendeléseit. Eltévelyítették őket az ő hazugságaik, a melyeket az ő atyáik követtek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'Tüzet vetek azért Júdára, és az emészti meg Jeruzsálem palotáit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'Így szól az Úr: Három bűne miatt az Izráelnek, sőt négy miatt, nem fordítom el; mert pénzért adták el az igazat, a szegényt pedig egy öltő saruért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, 'A kik a föld porát áhítják a szegények fejére, és a nyomorultak útját elfordítják. Fiú és az atyja egy leányhoz járnak, hogy megfertőztessék az én szent nevemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'Zálogos ruhákon nyujtózkodnak minden oltár mellett, és az elítéltek borát iszszák az ő istenök házában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'Pedig én irtottam ki előlük az Emoreusokat, a kik magasak voltak, mint a czédrusok, erősek, mint a cserfák. Mégis kiirtottam gyümölcsét felül és gyökerét alul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'És én hoztalak fel Égyiptom földéről, és negyven esztendeig én hordoztalak a pusztában titeket, hogy bírjátok az Emoreusok földét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'És prófétákat támasztottam a ti fiaitok közül és nazirokat ifjaitok közül. Nem így van-é vajjon, Izráel fiai? ezt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, 'De a nazirokat borral itattátok, és a prófétákra ráparancsoltatok, mondván: Ne prófétáljatok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, 'Ímé, én is lenyomlak titeket, ott a hol vagytok, mint a cséplő szekér lenyomja a kévékkel teli szérűt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, 'Elvész azért a futás a gyorstól, és nem erősíti meg az erőst az ő ereje, és a hős sem menekedhetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, 'Nem állja meg helyét az íjj-hordozó sem, nem menekülhet el még a gyorslábú sem, és a lovon ülő sem menekedhetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, 'És a bátor szívű is a hősök között meztelenül fut el azon a napon, ezt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, 'Halljátok meg e beszédet, melyet az Úr szól ti felőletek, Izráel fiai; mindama nemzetség felől, a melyet felhoztam Égyiptom földéről, ezt mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, 'Csak titeket választottalak magamnak e földnek minden nemzetségei közül; azért büntetlek meg titeket minden gonoszságtokért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'Vajjon járnak-é ketten együtt, ha nem egyeztek meg egymással?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'Ordít-é az oroszlán az erdőben, ha nincs mit ragadoznia? Hallatja-é hangját barlangjából a kölyök-oroszlán, ha semmit nem fogott?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'Tőrbe esik-é a madár a földön, ha nincs tőr vetve néki? Felpattan-é a tőr a földről, ha fogni nem fogott?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'Ha megharsan a kürt a városban, nem riad-é meg a nép? Vajjon lehet-é baj a városban, a mit nem az Úr szerezne?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'Mert semmit sem cselekszik az én Uram, az Úr, míg meg nem jelenti titkát az ő szolgáinak, a prófétáknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'Ordít az oroszlán: ki ne rettegne? Az én Uram, az Úr szólt: ki ne prófétálna?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'Adjatok hírt Asdód palotáiban és az Égyiptom földében való palotákban, és így szóljatok: Gyűljetek össze Samariának hegyein, és lássátok meg benne a sok háborgást, és az elnyomottakat az ő keblében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'Mert nem tudnak igazán cselekedni, azt mondja az Úr, ők, a kik halomra gyűjtik az erőszakosságot és zsarolást az ő palotáikban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'Annakokáért ezt mondja az Úr Isten: Ellenség jön és körülveszi e földet; ledönti hatalmadat és feldúlatnak a te palotáid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'Ezt mondja az Úr: A mint a pásztor az oroszlán szájából csak a két lábszárt menti meg, vagy a fül hegyét; akképen menekülnek meg Izráel fiai, a kik Samariában pamlag szegletében ülnek és a nyugágynak selymén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, 'Halljátok meg és adjátok tudtára a Jákób házának, azt mondja az Úr Isten, a Seregek Istene,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, 'Hogy a mely napon megbüntetem Izráelt az ő vétkeiért, Béth-El oltáraiért is büntetek, és letöretnek az oltár szarvai, és a földre omlanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'És ledöntöm a téli házat a nyári házzal együtt, és elpusztulnak az elefántcsont-házak is, megsemmisülnek a nagy házak, ezt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, 'Halljátok meg e beszédet Básánnak ünői, a kik Samaria hegyén vagytok; a kik nyomorgatjátok a szegényeket, megrontjátok az ügyefogyottakat, a kik azt mondják az ő uroknak: Hozd elő, hadd igyunk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, 'Megesküdt az Úr Isten az ő szentségére, hogy ímé napok következnek reátok, a mikor szigonyokkal visznek el titeket, és a ti maradékotokat halászó horgokkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, 'És a réseken mentek ki, mindenikőtök egyenest; és a Hermónba vettettek, ezt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, 'Menjetek Béth-Elbe és vétkezzetek, szaporítsátok a vétkeket Gilgálban. Vigyétek fel reggelente áldozataitokat, és harmad-naponként tizedeiteket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, 'Kovászosból gyújtsatok hálaáldozatot; ajánljatok önkéntes áldozatokat, híreszteljétek; mert így szeretitek, Izráel fiai, azt mondja az Úr Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, 'De én is bocsátottam rátok fogak tisztaságát minden városaitokban és kenyérszükséget minden helységeitekben, és még sem tértetek vissza hozzám, ezt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, 'De én is megvontam tőletek az esőt, három hónappal az aratás előtt, és esőt adtam egy városra, más városra pedig nem adtam esőt. Az egyik rész esőt kapott, az a rész pedig, a melyre nem esett eső, megszáradott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, 'És két-három város tántorgott egy-egy városba, vizet inni, de meg nem elégíttettek; és még sem tértetek vissza hozzám, ezt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, 'Megvertelek titeket szárazsággal és ragyával; kerteiteknek, szőlőiteknek, fügefáitoknak és olajfáitoknak nagy részét megette a sáska; és még sem tértetek vissza én hozzám, ezt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, 'Döghalált bocsátottam rátok, mint Égyiptomra; fegyverrel öltem ifjaitokat, fogságra vitettem lovaitokat; és táborotok bűzét egész orrotokig emeltem, és még sem tértetek vissza hozzám, ezt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, 'Felforgattam közületek többeket, a mint felforgatta Isten Sodomát és Gomorát, és olyanokká lettetek, mint a tűzből kikapott üszök; és még sem tértetek vissza hozzám, ezt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, 'Azért hát ekképen cselekeszem veled Izráel! Minthogy pedig ekképen cselekeszem veled, készülj Istened elé, oh Izráel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, 'Mert ímé, a ki hegyeket alkotott és a szelet teremtette, és a ki megjelenti az embernek az ő gondolatját, a ki a hajnalt sötétséggé változtatja és a föld magaslatain lépdel: az Úr ő, a Seregeknek Istene az ő neve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'Halljátok meg e beszédet, a melyet síródalként szólok ti rólatok, Izráelnek háza!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, 'Elesett, nem kel fel többé Izráelnek szűze; végig terült az ő földén, és nincs, a ki felemelné.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'Bizony így szól az Úr Isten: A mely város ezerrel indult ki, százzal marad csak meg; a mely pedig százzal indult ki, tízzel marad csak meg Izráel házául.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'Bizony így szól az Úr az Izráel házához: Engem keressetek, és éltek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'És ne keressétek Béth-Elt; Gilgálba se menjetek; Beér-Sebába se menjetek át. Mert Gilgál fogságba megy. Béth-El pedig semmivé lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'Keressétek az Urat, és éltek, különben reátör, mint a tűz, a József házára és megemészti Béth-Elt, és nem lesz, a ki megoltsa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, 'A kik ürömmé változtatják az ítéletet és az igazságot földre tiporják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, 'A ki a fiastyúkot és a kaszáscsillagot teremtette; a ki reggellé változtatja a homályt és a nappalt éjszakává sötétíti; a ki hívja a tenger vizeit és kiönti azokat a földnek színére: az Úr annak a neve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, 'A ki pusztulással sujtja a hatalmasokat, és pusztulás száll az erősségekre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, 'Gyűlölik azt, a ki feddőzik a kapuban, és útálják azt, a ki feddhetetlenül beszél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, 'Annakokáért, mivelhogy tiportátok a szegényt és gabona-ajándékot vesztek tőle: bár faragott kőből építtetek házakat, de nem lakoztok azokban, bár gyönyörűséges szőlőket plántáltok, de nem isztok azoknak borából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, 'Mert tudom, hogy sok a ti bűnötök, és nagyok a ti vétkeitek! Igazak nyomorgatói, váltságdíj-szedők vagytok; és elnyomják a szegényeket a kapuban!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, 'Azért hallgat az eszes ebben az időben, mert gonosz idő ez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, 'Keressétek a jót és ne a gonoszt, hogy éljetek, és akkor veletek lesz az Úr, a Seregek Istene, a mint mondjátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, 'Gyűlöljétek a gonoszt és szeressétek a jót; állítsátok vissza a kapuban az igazságot; talán megkegyelmez az Úr, a Seregek Istene a József maradékinak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, 'Azt mondja azért az Úr, a Seregek Istene, az én Uram: Minden térségen siralom lesz és minden utczán ezt mondják: jaj, jaj! s a szántóvetőt is gyászra hívják, s a sírni tudókat siralomra;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'És minden szőlőben siralom lesz, mert átmegyek te közötted, ezt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, 'Jaj azoknak, a kik kívánják az Úrnak napját! Mire való néktek az Úrnak napja? Sötétség az és nem világosság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, 'Mintha valaki oroszlán elől szaladna, és medve bukkanna rá; vagy pedig bemenne a házba és kezét a falhoz támasztaná, és kígyó marná meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, 'Nem sötétség lesz-é az Úrnak napja és nem világosság?! Sötétség lesz az, s még hajnalfénye sem lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, 'Gyűlölöm, megvetem a ti ünnepeiteket, és nem gyönyörködöm a ti összejöveteleitekben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, 'Még ha égőáldozatokkal áldoztok is nékem, sőt ételáldozataitokat sem kedvelem; kövér hálaáldozataitokra rá se tekintek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, 'Távoztasd el tőlem énekeid zaját, hárfáid pengését sem hallgathatom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, 'Hanem folyjon az ítélet, mint a víz, és az igazság, mint a bővizű patak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'Járultatok-é hozzám véres áldozatokkal s ételáldozatokkal a pusztában negyven éven át, oh Izráel háza?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, 'Majd viszitek hát Szikkútot, a ti királyotokat és Kijjunt, a ti képeiteket, a ti isteneitek csillagát, a melyet ti csináltatok magatoknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, 'És Damaskuson túlra száműzlek titeket, azt mondja az Úr, a kinek neve Seregeknek Istene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, 'Jaj azoknak, a kik gondtalanul élnek a Sionon, és a kik elbizakodnak Samaria hegyén; a kik a népek elejének elei, és a kikhez jő az Izráelnek háza!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'Menjetek át Kalnéba, és nézzetek szét; onnan pedig menjetek a nagy Hamátba, és szálljatok le a Filiszteusok Gáthjába; vajjon jobbak-é azok, mint ezek az országok, és vajjon szélesebb-é azoknak határa a ti határotoknál?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, 'A kik a veszedelem napját messze gondoljátok, és az erőszaknak széket emeltek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, 'A kik elefántcsont pamlagon hevernek, és az ő nyoszolyáikban elnyújtózkodnak, és a nyáj legjavából és a kihízlalt borjakból lakmároznak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, 'A kik hárfa mellett dalolgatnak, és azt hiszik, hogy hangszereik a Dávidéi;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, 'A kik a bort serlegekkel iszszák, és szín-olajjal kenegetőznek, és nem búsulnak a József romlásán:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, 'Most azért is ők vitetnek el a száműzöttek élén, és vége szakad a nyújtózkodók dáridózásának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, 'Megesküdt az Úr Isten az ő életére; ezt mondja az Úr, a Seregek Istene: Útálom a Jákób kevélységét és gyűlölöm az ő palotáit; azért prédára vetem a várost mindenestől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, 'És ha egy házban tíz ember maradna is meg, még az is meghal;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, 'És mikor felemeli őt az ő barátja és megégetője, hogy kivigye a holttetemeket a házból, azt mondja annak, a ki a ház belsejében lesz: Van-é még valaki veled? az pedig azt mondja: Nincs, és ezt is mondja: Csitt! mert nem szabad említeni az Úrnak nevét!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, 'Mert ímé, parancsol az Úr és megveri a nagy házat repedezésekkel, és a kicsiny házat hasadozásokkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, 'Vajjon futhatnak-é a lovak a sziklán? felszánthatja-é azt valaki ökrökön? hogy az ítéletet bürökké tettétek, az igazság gyümölcsét pedig ürömmé?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, 'A kik örültök a hiábavaló dolognak, és a kik ezt mondjátok: Nem a magunk erejével szereztünk-é magunknak a szarvakat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, 'Ímé, bizony népet indítok ellened, oh Izráel háza, azt mondja az Úr, a Seregek Istene, és az sanyargat titeket a hámáti úttól az Arába patakjáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, 'Ily dolgot láttatott velem az Úr Isten; Ímé, teremte sáskát a sarjúfakadás kezdetén, és ímé sarjú vala a királyi kaszálás után!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, 'És lőn, hogy a mint felemésztette a földnek füvét, azt mondám: Uram, Isten! légy kegyelmes, kérlek! Hogyan állhasson meg Jákób, hiszen kicsiny?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'Megengesztelődék az Úr e dologban: Nem lesz meg! mondá az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, 'Ily dolgot láttatott velem az Úr Isten: Ímé, tüzet híva elő ítéletre az Úr Isten, és megemészté az a nagy mélységet, és megemészté az országot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, 'De mondám: Uram, Isten! hagyd abba, kérlek! Hogyan állhatna meg Jákób; hiszen kicsiny?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'Megengesztelődék az Úr e dologban: Ez sem lészen meg, mondá az Úr Isten!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'Ily dolgot láttatott velem: Ímé, ott állott az Úr egy függőleges kőfalon, és a kezében mérő-zsinór vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, 'És monda az Úr nékem: Mit látsz Ámós? Én pedig mondám: Mérőzsinórt. És mondá az Úr: Ímé, mérőzsinórral mérek népemnek, az Izráelnek közepette, és nem bocsátok meg néki többé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'Bizony elpusztulnak Izsáknak magaslatai, és romba dőlnek Izráel szent helyei; és fegyverrel támadok a Jeroboám háza ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, 'És elkülde Amáziás, Béth-El papja Jeroboámhoz, Izráel királyához, ezt üzenvén: Pártot ütött ellened Ámós az Izráel házában; nem tűrheti az ország az ő mindenféle beszédét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, 'Mert így beszél Ámós: Fegyver által hal meg Jeroboám, az Izráel pedig fogságba vitetik az ő földéről!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, 'Ámósnak pedig így szólt Amáziás: Menj el, próféta! Fuss el a Júda földére; ott egyed kenyered és ottan prófétálj!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, 'Béth-Elben pedig ne prófétálj többé; mert a király szenthelye és az ország székháza ez!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'És felele Ámós, és mondá Amáziásnak: Nem vagyok próféta, sem prófétának fia; barom-pásztor vagyok és vad fügét szedek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, 'De elhívott engem az Úr a nyáj mellől, és mondá nékem az Úr: Menj el és prófétálj az én népemnek, az Izráelnek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, 'Most azért halld meg az Úrnak beszédét! Te azt mondod: Ne prófétálj az Izráel ellen, és ne szólj az Izsák háza ellen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, 'Azért így szól az Úr: Feleséged paráznává lesz a városban; fiaid és leányaid fegyver által hullnak el; földedet felosztják kötéllel, és te magad tisztátalan földön halsz meg; az Izráel pedig fogságba vitetik az ő földéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, 'Ily dolgot láttatott velem az Úr Isten: Ímé, egy kosár érett gyümölcs.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'És mondá: Mit látsz Ámós? És mondám: Egy kosár érett gyümölcsöt. És mondá az Úr nékem: Eljött vége az én népemnek, az Izráelnek; nem bocsátok meg néki többé!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, 'Azon a napon jajjá változnak a templomi énekek, így szól az Úr Isten, és temérdek lesz a hulla; szó nélkül hányák mindenüvé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, 'Halljátok meg ezt ti, kik a szegényre törtök, és e föld szegényeinek kipusztítására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, 'Mondván: Mikor múlik el az újhold, hogy gabonát árulhassunk? és a szombat, hogy megnyithassuk a gabonás házat? hogy megkisebbítsük a vékát, és megnagyobbítsuk az árát, és hamis mértékkel csalhassunk?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, 'Hogy megvegyük a szegényeket pénzen, és a szűkölködőt egy öltő saruért, és eladhassuk a gabona hulladékát?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'Megesküdt az Úr a Jákób büszkeségére: Soha el nem felejtem semmi cselekedetöket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, 'Ne rendüljön-é meg e miatt a föld? És ne búsuljon-é annak minden lakosa?! Bizony felindul egészen, mint a folyam, és dagad és apad, mint Égyiptom folyója.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, 'És lészen azon a napon, azt mondja az Úr Isten: Lenyugtatom a napot délben, és besötétítem a földet fényes nappal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, 'Ünnepeiteket búra változtatom; és minden dalotokat szomorú énekké! Gyászruhát borítok minden derékra, és kopaszságot minden fejre, és olyanná teszem, mint a ki egyetlen fiát siratja; a vége pedig, mint a keserűség napja!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, 'Ímé, napok jőnek, azt mondja az Úr Isten, és éhséget bocsátok e földre; nem kenyér után való éhséget, sem víz után való szomjúságot, hanem az Úr beszédének hallgatása után.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, 'És vándorolni fognak tengertől tengerig és északtól fogva napkeletig. Futkosnak, hogy keressék az Úrnak beszédét, de nem találják meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, 'Azon a napon elepednek a deli szűzek, meg az ifjak is, a szomjúság miatt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, 'A kik Samaria bűnére esküsznek, és ezt mondják: Él a te istened, oh Dán: és él a te útad, oh Beérseba! Bizony elhullanak és nem kelnek fel többé!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, 'Látám az Urat állani az oltáron, és mondá: Üsd meg az oszlop fejét, hadd rendüljenek meg a küszöbök, és döntsd azokat mindnyájok fejére. A megmaradókat pedig fegyverrel ölöm meg. Nem fog elfutni közülök a futó, és nem menekül meg közülök a menekülő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, 'Ha a Seolba ássák is be magokat, kezem onnan is kiragadja őket; és ha az égbe hágnának is fel, onnan is levonszom őket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, 'És ha a Kármel tetején rejtőznének is el, onnan is előkeresem és elhozom őket; és ha szemeim elől a tenger fenekére bújnának is, ott is parancsolok a kígyónak és megmarja őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, 'És ha fogságba mennek is ellenségeik előtt, ott is parancsolok a fegyvernek és megöli őket; és reájok fordítom szemeimet, vesztökre és nem javokra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, 'Mert az Úr, a Seregek Ura az, a ki megérinti a földet és elolvad az, és jajgat annak minden lakója, és feldagad egészen, mint a folyam, meg elapad, mint Égyiptom folyója.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, 'A ki fenn az égben építé az ő boltozatát, és annak íveit a földre alapítá; a ki előhívja a tenger vizeit s kiönti azokat a földnek színére: az Úr az ő neve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, 'Nem olyanok vagytok-é ti előttem, oh Izráel fiai, mint a Kusiták fiai?! ezt mondja az Úr. Nem én hoztam-é ki Izráelt Égyiptom földéről, és a Filiszteusokat Kaftorból, és a Siriabelieket Kirből?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, 'Ímé, az Úr Isten szemmel tartja a bűnös országot, és eltörlöm azt a földnek színéről. Mindazáltal még sem pusztítom el egészen a Jákóbnak házát, ezt mondja az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, 'Mert ímé, én parancsolok és szétrázom Izráel házát minden népek között, a mint a rostával rázogatnak; de nem esik a földre egy szemecske sem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, 'Fegyver által halnak meg az én népemnek minden bűnösei, a kik azt mondják: Nem ér el minket és nem jő reánk a veszedelem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, 'Azon a napon felemelem a Dávid leomlott sátorát, és kijavítom repedezéseit, és felemelem omladékait, és megépítem azt, mint volt hajdanán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, 'Hogy örökségképen bírják az Edom maradékát és mindama népeket, a kik az én nevemről neveztetnek, ezt mondja az Úr, a ki megcselekszi ezt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, 'Ímé, napok jőnek, ezt mondja az Úr, és ott éri a szántó az aratót, a szőlőtaposó a magvetőt. És a hegyek musttal csepegnek, a halmok pedig mind megáradnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, 'És hazahozom a fogságból az én népemet, az Izráelt, és fölépítik az elpusztult városokat, és lakoznak bennök. Szőlőket plántálnak és iszszák azok borát, és kerteket csinálnak és eszik azoknak gyümölcsét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, 'És elplántálom őket az ő földjökbe; és nem szaggattatnak ki többé az ő földjökből, a melyet adtam nékik, azt mondja az Úr, a te Istened!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, 'Abdiás látása. Így szól az Úr Isten Edomról: Hírt hallottunk az Úrtól! És hírnök küldetett a népekhez: keljetek fel és támadjunk reá haddal!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, 'Ímé, kicsinynyé tettelek a népek között; felettébb útálatos vagy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, 'Szíved kevélysége csalt meg téged, ki szikla-hasadékokban lakozol, kinek lakóhelye magasan van, a ki mondja az ő szívében: Ki vonhatna le engem a síkra?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, 'Ha oly magasra szállnál is, mint a sas, és ha a csillagok közé raknád is fészkedet: onnan is levonnálak, ezt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, 'Ha tolvajok törnének reád, avagy éjjeli rablók, (hogy elpusztíttattál!), nem annyit lopnának-é, a mennyi elegendő?! Ha szőlőszedők jönnének reád, nem hagynának-é gerezdeket?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, 'Mennyire kifosztogatták Ézsaut; felkutatták rejtett kincseit!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, 'A határig űznek ki összes frigytársaid; megcsalnak, levernek szövetségeseid; kenyeredet tőrül vetik alád. Nincsen benne okosság!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, 'Azon a napon, ezt mondja az Úr, nem vesztem-é ki a bölcseket Edomból, és az értelmet az Ézsau hegyéről?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'És megrémülnek a te vitézeid, oh Témán! hogy kiirtassék mindenki az Ézsau hegyéről az öldöklés által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, 'A Jákób öcséd ellen elkövetett erőszakért szégyen borul reád, és kivágatol mindörökre!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, 'A mikor vele szembeálltál; a mikor serege idegenek rabjává lett, és idegenek törtek be kapuján és Jeruzsálemre sorsot vetettek: olyan voltál te is, mint bármelyik közülök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, 'De ne gyönyörködjél öcsédnek napján, az ő szerencsétlenségének napján; és ne örvendj a Júda fiain az ő veszedelmök napján, és ne kérkedjél a szorongattatás napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, 'Ne törj be népem kapuján nyomorúságuk napján; ne gyönyörködjél te is a baján nyomorúsága napján; és ne nyúlj az ő jószágához nyomorúsága napján;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, 'A résre se állj fel menekülőit elveszíteni; és ne áruld el az ő megmaradottait a szorongattatás napján!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'Mert közel van az Úrnak napja minden népek ellen. A mint cselekedtél, úgy cselekesznek veled; a mit te fizettél, visszaszáll fejedre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, 'Mert a mint ti ittatok szent hegyemen, úgy isznak szüntelen az összes népek; bizony isznak és hörpengetnek, és olyanok lesznek, mintha nem lettek volna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, 'De a Sion hegyén szabadulás lészen, és szentté lészen az, és a Jákób háza birtokba veszi az ő örökségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, 'És a Jákób háza tűz lészen, és a József háza láng; az Ézsau háza pedig pozdorja; és meggyújtják és megemésztik őket, és nem marad meg senki Ézsau házából, mert az Úr szólott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, 'A déliek örökség szerint bírják az Ézsau hegyét, a síkon lakók pedig a Filiszteusokat. És örökség szerint bírják az Efraim mezőit és Samaria mezőit; Benjámin pedig a Gileádot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, 'Izráel fiainak ez a száműzött serege azokat, a melyek a Kananeusoké, mind Sarfátig; a jeruzsálemi száműzöttek pedig, a kik Szefarádban vannak, elfoglalják majd a déli városokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, 'És a Sion hegyére szabadítók mennek fel, hogy megítéljék az Ézsau hegyét; és az Úré lesz a királyság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'És lőn az Úrnak szava Jónáshoz, az Amittai fiához, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, 'Kelj fel, menj Ninivébe, a nagy városba, és kiálts ellene, mert gonoszságuk felhatolt elémbe!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'És felkele Jónás, hogy Tarsisba szaladna az Úr elől. Leméne azért Jáfóba, és talála ott egy hajót, a mely méne Tarsisba, és megadván a hajóbért, beszálla abba, hogy Tarsisba menne velök az Úr színe elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'Az Úr pedig nagy szelet bocsáta a tengerre, és nagy vihar lőn a tengeren, és a hajó már-már töredezik vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'Megfélemlének azért a hajósok és kiáltának, kiki az ő istenéhez, és a hajóban lévő holmit a tengerbe hányák, hogy könnyítsenek magukon. Jónás pedig leméne a hajó aljába, és lefeküdt és elaludt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'De hozzáméne a kormányos mester, és mondá néki: Mi lelt, te nagy alvó? Kelj fel, kiálts a te Istenedhez; hát ha gondol velünk az Isten, és nem veszünk el!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'Egymásnak pedig ezt mondák: Jertek, vessünk sorsot, hogy megtudhassuk: mi miatt van rajtunk e veszedelem? És sorsot vetének, és a sors Jónásra esék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'Mondák azért néki: Kérünk, beszéld el nékünk: mi miatt van rajtunk e veszedelem? Mi a te foglalkozásod és honnan jösz? Melyik a te hazád és miféle népből való vagy te?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'És monda nékik: Héber vagyok én, és az Urat, az egek Istenét félem én, a ki a tengert és a szárazt teremtette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'És megfélemlének az emberek nagy félelemmel, és mondák néki: Mit cselekedtél? Mert megtudták azok az emberek, hogy az Úr színe elől fut, mivelhogy elbeszélé nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'Mondák azután néki: Mit cselekedjünk veled, hogy a tenger megcsendesedjék ellenünk? Mert a tenger háborgása növekedék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'Ő pedig monda nékik: Fogjatok meg és vessetek engem a tengerbe, és megcsendesedik a tenger ellenetek; mert tudom én, hogy miattam van ez a nagy vihar rajtatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'És erőlködtek azok az emberek, hogy visszajussanak a szárazra; de nem tudtak, mert a tenger háborgása növekedék ellenök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'Kiáltának azért az Úrhoz, és mondák: Kérünk Uram, kérünk, ne veszszünk el ez ember lelkéért, és ne háríts reánk ártatlan vért; mert te, Uram, úgy cselekedtél, a mint akartad!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'És felragadák Jónást és beveték őt a tengerbe, és megszűnék a tenger az ő háborgásától.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'Azok az emberek pedig nagy félelemmel félék az Urat, és áldozattal áldozának az Úrnak, és fogadásokat fogadának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'Az Úr pedig egy nagy halat rendelt, hogy benyelje Jónást. És lőn Jónás a halnak gyomrában három nap és három éjjel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, 'És könyörge Jónás az Úrnak, az ő Istenének a halnak gyomrából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, 'És mondá: Nyomorúságomban az Úrhoz kiálték és meghallgata engem; a Seol torkából sikolték és meghallád az én szómat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, 'Mert mélységbe vetettél engem, tenger közepébe, és körülfogott engem a víz; örvényeid és habjaid mind átmentek rajtam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, 'És én mondám: Elvettettem a te szemeid elől; vajha láthatnám még szentséged templomát!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'Körülvettek engem a vizek lelkemig, mély ár kerített be engem, hinár szövődött fejemre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'A hegyek alapjáig sülyedtem alá; bezáródtak a föld závárjai felettem örökre! Mindazáltal kiemelted éltemet a mulásból, oh Uram, Istenem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'Mikor elcsüggedt bennem az én lelkem, megemlékeztem az Úrról, és bejutott az én könyörgésem te hozzád, a te szentséged templomába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, 'A kik hiú bálványokra ügyelnek, elhagyják boldogságukat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, 'De én hálaadó szóval áldozom néked; megadom, a mit fogadtam. Az Úré a szabadítás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 11, 'És szóla az Úr a halnak, és kiveté Jónást a szárazra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'És lőn az Úrnak szava Jónáshoz másodszor is, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, 'Kelj fel, menj Ninivébe, a nagy városba, és hirdesd néki azt a beszédet, a mit én parancsolok néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'És felkele Jónás, és elméne Ninivébe az Úr szava szerint. Ninive pedig nagy városa vala Istennek, három napi járó föld.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'És kezde Jónás bemenni a városba egy napi járóra, és kiálta és monda: Még negyven nap, és elpusztul Ninive!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'A niniveiek pedig hivének Istenben, és bőjtöt hirdetének, és nagyjaiktól fogva kicsinyeikig zsákba öltözének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'És eljuta a beszéd Ninive királyához, és felkele királyi székéből, és leveté magáról az ő királyi ruháját, és zsákba borítkozék, és üle a porba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'És kiáltának és szólának Ninivében, a királynak és főembereinek akaratából, mondván: Emberek és barmok, ökrök és juhok: semmit meg ne kóstoljanak, ne legeljenek és vizet se igyanak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'Hanem öltözzenek zsákba az emberek és barmok, és kiáltsanak az Istenhez erősen, és térjen meg kiki az ő gonosz útáról és az erőszakosságból, a mely az ő kezökben van!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'Ki tudja? talán visszatér és megengesztelődik az Isten és elfordul haragjának búsulásától, és nem veszünk el!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'És látá Isten az ő cselekedeteiket, hogy megtértek az ő gonosz útjokról: és megbáná az Isten azt a gonoszt, a melyről mondá, hogy végrehajtja rajtok, és nem hajtá végre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'És igen rossznak látszék ez Jónás előtt, és megharaguvék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'Könyörge azért az Úrhoz, és mondá: Kérlek, Uram! Avagy nem ez vala-é az én mondásom, mikor még az én hazámban valék? azért siettem, hogy Tarsisba futnék, mert tudtam, hogy te irgalmas és kegyelmes Isten vagy, nagy türelmű és nagy irgalmasságú és a gonosz miatt is bánkódó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'Most azért Uram, vedd el, kérlek, az én lelkemet én tőlem, mert jobb meghalnom, mintsem élnem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'Az Úr pedig mondá: Avagy méltán haragszol-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'Majd kiméne Jónás a városból, és üle a város keleti része felől, és csinála ott magának hajlékot, és üle az alatt az árnyékban, a míg megláthatná, mi lészen a városból?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'Az Úr Isten pedig egy tököt rendele, és felnöve az Jónás fölé, hogy árnyékot tartson feje fölött és megoltalmazza őt a hévség bántásától. És nagy örömmel örvendezék Jónás a tök miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'De másnapra férget rendele az Isten hajnal-költekor, és megszúrá az a tököt, és elszárada.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'És lőn napköltekor, hogy tikkasztó keleti szelet rendele Isten, és a nap rátűzött a Jónás fejére, és ő elbágyada. Kiváná azért magának a halált, és monda: Jobb halnom, mint élnem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'És monda az Isten Jónásnak: Avagy méltán haragszol-é a tök miatt? És monda: Méltán haragszom, mind halálig!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'Az Úr pedig monda: Te szánod a tököt, a melyért nem fáradtál és a melyet nem neveltél, a mely egy éjjel támadt és más éjjel elveszett:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'Én pedig ne szánjam Ninivét, a nagy várost, a melyben több van tizenkétszer tízezer embernél, a kik nem tudnak különbséget tenni jobb- és balkezük között, és barom is sok van?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, 'Az Úr igéje, a mely lőn a moreseti Mikeáshoz, Jótám, Akház és Ezékiásnak, Júda királyainak idejében, a melyet látott Samária és Jeruzsálem felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, 'Halljátok meg minden népek, figyelmezz föld és annak teljessége. És az Úr Isten legyen bizonyság ellenetek; az Úr az ő szent templomából!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'Mert ímé, kijő az Úr az ő helyéről, és leszáll és lépdel a földnek magaslatain.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'És szétmállanak alatta a hegyek, a völgyek pedig szétszakadoznak, mint a viasz a tűz előtt, mint a meredekről leszakadó vizek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'A Jákób vétkéért lészen mindez, és az Izráel házának bűnei miatt! Micsoda a Jákób vétke? Avagy nem Samária-é? És mik a Júda magaslatai? Avagy nem Jeruzsálem-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, 'De olyanná teszem Samáriát, mint a mezőben való kőrakás, szőlő-plánták helyévé; és lezúdítom a völgybe az ő köveit, és még fundamentomit is kimutatom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'Faragott képei mind összetöretnek és minden ajándékát tűz égeti meg. Minden bálványait semmivé teszem; mert paráznaság béréből gyűjtögette azokat, azért ismét paráznaság bérévé legyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, 'E miatt kesergek és jajgatok; ruhátalan és mezítelen járok. Üvöltök, mint a sakálok, és sikongok, mint a struczmadarak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'Mert halálosak az ő sebei. Bizony Júdáig ér; népem kapujáig hatol, Jeruzsálemig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, 'Gáthban hírül ne adjátok; sírván ne sírjatok; Beth-le-Afrában porba heveredtem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, 'Költözzetek el, Safirnak lakója gyalázatos meztelenül! Nem vonult ki Saanán lakosa; Beth-Eselnek siralma nem enged tartózkodni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 12, 'Mert beteg lett Marótnak lakosa az ő javai miatt; mert veszedelem szállt le az Úrtól Jeruzsálemnek kapujára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 13, 'Gyors paripához kösd a szekeret, Lákisnak lakója! ki a bűnnek kezdője valál a Sion leányánál. Bizony te benned találtatnak Izráel vétkei!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 14, 'Azért adj válólevelet Moreset-Gátnak! Akzib házai megcsalják Izráel királyait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 15, 'Még hozok én te néked örököst, Marésa lakosa; Adullámig hat el Izráel dicsősége!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 16, 'Nyírd le, kopaszítsd meg magadat a te gyönyörűséges fiaidért! Szélesítsd meg kopaszságodat, mint a keselyű; mert rabságra vitettek el tőled!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, 'Jaj azoknak, a kik hamisságot gondolnak és a kik ágyasházukban gonoszságot cselekesznek, és végrehajtják azt, mihelyt megvirrad, mert hatalmuk van hozzá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, 'Megkívánják a mezőket és elrabolják, és a házakat és elszedik; és nyomorgatják a gazdát, és az ő házanépét az embert és az ő örökségét!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, 'Annakokáért ezt mondja az Úr: Ímé, én is gonoszt gondolok e nemzetség ellen, melyből ki nem vonhatjátok a ti nyakatokat és nem jártok kevélyen, mivel gonosz idő lészen az!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'Azon a napon példabeszéd támad rólatok, és siralmat sírnak, mondván: Oda van! elpusztultunk! Népem örökségét felcserélte! Miként rabolja el tőlem; hűtelennek osztja ki mezeinket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, 'Azért nem lesz néked, a ki mérőzsinórt vessen sors szerint az Úrnak gyülekezetében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, 'Ne prófétáljatok! prófétálnak ők. Ha nem prófétálnak ezeknek, nem múlik el a gyalázat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, 'Oh te, ki Jákób házának mondatol! hát türelmetlen-é az Úrnak lelke, avagy ezek-é az ő cselekedetei? Nem javára válnak-é az én cselekedeteim annak, a ki igazán jár?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, 'A minap mint egy ellenség támadt fel az én népem; a köntösről a palástot letépik a gyanútlanul járókról, a háborútól idegenkedőkről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, 'Népem asszonyait kiűzitek boldogságuk házából; kisdedeiktől örökre elveszitek az én dicsőségemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, 'Keljetek fel és menjetek ki, mert ez nem a nyugalomnak helye; a tisztátalanság miatt, a mely elveszít, és pedig borzasztó veszedelemmel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, 'Ha valamely szélházi és csalárd így hazudoznék: Prédikálok néked borról és részegítő italról, az volna e népnek prófétája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, 'Mindenestől egybegyűjtelek téged, Jákób! Összetakarítom Izráel maradékát. Összegyűjtöm őket, mint a boczrai juhokat, mint a nyájat az ő karámja közé; hemzsegnek majd az ember-sokaság miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, 'Előttök megy fel az úttörő; kitörnek és átmennek a kapun és kivonulnak, és előttök megy a királyuk, és élükön az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, 'És mondám én: Halljátok, kérlek, Jákób fejedelmei és Izráel házának vezérei: Nem a ti tisztetek-é tudni az ítéletet?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, 'Ti, kik gyűlölitek a jót és kedvelitek a gonoszt! A kik levonszátok róluk bőrüket és csontjaikról az ő húsokat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, 'A kik megeszik az én népemnek húsát, és lenyúzzák róluk bőrüket, és összetörik csontjaikat, és feldarabolják, akár csak a fazékba, és mint húst a tálba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, 'Kiáltanak majd az Úrhoz, de nem hallgatja meg őket; sőt elrejti akkor orczáját előlök, mivelhogy gonoszokká lettek cselekedeteik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, 'Így szól az Úr a próféták ellen, a kik elámítják az én népemet, a kik, ha van mit rágniok, békességet hirdetnek, az ellen pedig, a ki nem vet valamit szájokba, hadat indítanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, 'Azért éjszaka száll rátok, hogy ne lássatok, és sötétség jő rátok, hogy ne jövendölhessetek, és a nap lemegy a próféták felett, és elsötétül rajtok a nappal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, 'És megszégyenülnek a látók, és elpirulnak a jövendőmondók, és elfedik szájokat mindnyájan, mert nem lészen felelet Istentől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, 'Én ellenben megteljesedem az Úr lelkének erejével, és ítélettel és hatalommal, hogy hirdessem Jákóbnak az ő vétkét, és Izráelnek az ő bűnét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, 'Halljátok ezt, kérlek, Jákób házának fejei és Izráel házának vezérei! a kik útáljátok az ítéletet, és minden igazságot elcsavartok;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, 'A kik vérrel építitek a Siont, és Jeruzsálemet hamissággal!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, 'Kiknek fejedelmei ajándékért ítélnek, és papjaik jutalomért tanítanak, és prófétáik pénzért jövendölnek, és mégis az Úrra támaszkodnak, mondván: Avagy nincsen-é közöttünk az Úr?! Nem következik mi reánk veszedelem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, 'Azért ti miattatok mezővé szántatik a Sion, és kőhalommá lesz Jeruzsálem, a templom hegye pedig erdős hegygyé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, 'És lészen: az utolsó időben az Úr házának hegye a hegyek fölé helyeztetik, és felülemelkedik az a halmokon, és népek özönlenek reá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, 'Pogányok is sokan mennek, és mondják: Jertek, menjünk fel az Úr hegyére és a Jákób Istenének házához, hogy megtanítson minket az ő útaira, és járjunk az ő ösvényein! Mert Sionból jő ki a törvény, és az Úr beszéde Jeruzsálemből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, 'És sok népek között ítéletet tészen, és megfedd erős nemzeteket nagy messze földig és fegyvereiket kapákká kovácsolják, dárdáikat pedig sarlókká; nép népre fegyvert nem emel, és hadakozást többé nem tanulnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, 'És kiki nyugszik az ő szőlője alatt és fügefája alatt, és senki meg nem rettenti őket, mert a Seregek Urának szája szólott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, 'Mert minden nép a maga istenének nevében jár, és mi is a mi Urunk Istenünk nevében járunk örökkön örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, 'Azon a napon, azt mondja az Úr, összegyűjtöm a sántát, és összeszedem az elszéledetteket, és a kiket megsanyargattam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'És a sántát maradékká teszem, az elszélesztettet pedig erős nemzetté, és az Úr uralkodik rajtok a Sion hegyén mostantól fogva mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, 'És te nyájnak tornya, Sion leányának vára! Eljő tehozzád és elérkezik az előbbi hatalom, a Jeruzsálem leányának birodalma.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, 'Miért kiáltasz hát kiáltva? Nincsen-é közötted király? Elveszett-é a te tanácsadód, hogy úgy elfogott a fájdalom, mint a gyermek-szűlőt?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'Gyötrődj és kinlódj, Sionnak leánya, mint a gyermek-szülő! Mert ímé, kimégy a városból, és a mezőn tanyázol, és egészen Bábelig mégysz. Ott szabadíttatol meg; ott vált ki téged az Úr, ellenségednek kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, 'Mert ímé, sok nemzetség gyűlt össze ellened, a kik ezt mondják: Legyen szentségtelen, és legeltessük szemeinket a Sionon!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, 'De ők nem tudják az Úr gondolatait és nem értik az ő szándékát, hogy összegyűjti őket, mint a kévét a szérűre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'Kelj fel és csépelj, Sionnak leánya! Mert vassá teszem a te szarvaidat, körmeidet pedig aczéllá teszem, és széttiporsz sok népeket, és rablott kincseiket az Úrnak áldozom, javaikat pedig az egész föld Urának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, 'Seregelj hát egybe, seregek leánya! Ostrommal támadt ellenünk; pálczával verjék arczul Izráel biráját!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, 'De te, Efratának Bethleheme, bár kicsiny vagy a Júda ezrei között: belőled származik nékem, a ki uralkodó az Izráelen; a kinek származása eleitől fogva, öröktől fogva van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, 'Azért odaadja őket, míg a szűlő szűl, de az ő atyjafiainak maradékai visszatérnek Izráel fiaihoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, 'És megáll, és legeltet az Úrnak erejével, az Úrnak az ő Istenének fenséges nevével, és bátorsággal lakoznak, mert ímé felmagasztaltatik a földnek határáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, 'És ő a mi békességünk. Ha az Assirus eljő a mi földünkre és megtapodja palotáinkat: állatunk ellene hét pásztort és nyolcz fejedelmi férfiút.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, 'És megrontják Assiria földjét fegyverrel Nimród földjét is az ő kapuiban; és megszabadít az Assirustól, ha a mi földünkre eljő és a mi határunkba lép.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, 'És a Jákóbnak maradéka olyan lészen a sok nép között, mint az Úrtól való harmat, mint a zápor a fűnek, mely nem emberben reménykedik, és nem bízik embernek fiaiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, 'És a Jákób maradéka a pogányok között, a sok nép között olyan lészen, mint az oroszlán az erdei vadak között; mint az oroszlán-kölyök a juhoknak nyája között, a mely ha betör, tipor és tép, és nincs, a ki tőle megszabadítson.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, 'Erőt vészen a te kezed szorongatóidon, és minden ellenségeid kivágattatnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, 'És lészen azon a napon, azt mondja az Úr, kivágom lovaidat közüled, és elvesztem hadi-szekereidet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, 'És kivágom földednek városait, és ledöntöm minden erősségeidet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, 'És kivágom kezedből a bűvszereket, és szemfényvesztőid nem lesznek néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, 'És kivágom faragott képeidet és bálványaidat közüled, és nem imádod többé kezeidnek csinálmányait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, 'És kiszaggatom a te berkeidet közüled és elpusztítom a te városaidat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 15, 'És haraggal és hévvel állok bosszút a pogányokon, a kik nem engedelmeskedtek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, 'Halljátok csak, a mit mond az Úr! Kelj fel, perelj a hegyekkel, és hallják meg szódat a halmok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, 'Halljátok meg hegyek az Úr peres dolgát, és ti, a földnek örök alapjai! Mert pere van az Úrnak az ő népével, és az Izráellel is perbe száll.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, 'Én népem! mit vétettem te ellened, és mivel fárasztottalak el téged?! Tégy vallást ellenem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, 'Hiszen felhoztalak Égyiptom földjéről, és a szolgák házából megváltottalak, és előtted küldém Mózest, Áront és Máriát!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, 'Én népem! Emlékezzél csak: mit koholt Bálák, Moábnak királya, és mit felelt néki Bálám, a Beor fia? Sittimtől fogva Gilgálig, hogy megismerjed az Úr igazságos cselekedeteit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, 'Mivel menjek eleibe az Úrnak? Hajlongjak-é a magasságos Istennek? Égőáldozatokkal menjek-é elébe, esztendős borjúkkal?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'Kedvét leli-é az Úr ezernyi kosokban, vagy tízezernyi olaj-patakokban? Elsőszülöttemet adjam-é vétkemért, vagy méhem gyümölcsét lelkemnek bűnéért?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, 'Megjelentette néked, oh ember, mi légyen a jó, és mit kiván az Úr te tőled! Csak azt, hogy igazságot cselekedjél, szeressed az irgalmasságot, és hogy alázatosan járj a te Isteneddel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, 'Az Úrnak szava kiált a városnak, és a te neved néz bölcseségre. Halljátok meg a vesszőt és ki rendeli azt?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, 'Vannak-é még a gonosznak házában hamissággal gyűjtött kincsek, és ösztövér véka, a mely útálatos?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, 'Vajjon jóváhagyom-é a hamis mértéket, és a zsákba rejtett csalárd fontokat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 12, 'Mert a gazdagok megtöltöztek köztök ragadománynyal, lakosai pedig hazugságot szólnak, és nyelvök csalárd az ő szájokban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 13, 'Én is azért megvervén, beteggé teszlek téged; elpusztítalak a te bűneid miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 14, 'Eszel te, de meg nem elégszel, és benned marad a te éhséged; és gyűjtesz, de nem takarítasz, és a mit megtakarítsz is, fegyverre hányom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 15, 'Vetsz te, de nem aratsz; olajat sajtolsz te, de nem kened magadat olajjal, és mustot is, de bort nem iszol!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 16, 'Mert az Omri parancsolataihoz szabjátok magatokat és az Ákháb házának minden dolgához, és azoknak tanácsán jártok! Hogy pusztasággá tegyelek tégedet, az ő lakosait pedig csúfsággá, és hordozzátok népemnek gyalázatát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, 'Jaj nékem, mert olyanná lettem, mint a letakarított mező, mint a megszedett szőlő: egy enni való gerezd sem maradott; pedig zsengére vágyott a lelkem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, 'Elveszett e földről a kegyes, és igaz sincs az emberek között. Mindnyájan vér után ólálkodnak, kiki hálóval vadássza atyjafiát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, 'Gonoszságra készek a kezek, hogy jól vigyék véghez; a fejedelem követelőzik, és a biró fizetésre vár; a főember is maga mondja el lelke kívánságát, és összeszövik azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, 'A ki jó közöttök, olyan mint a tüske, az igaz olyan, mint a tövisbokor. A te őrállóidnak napja, a te megítélésed eljött; most következik el az ő zűrzavaruk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, 'Ne higyjetek a barátnak; ne bízzatok a tanácsadóban; az öledben ülő előtt is zárd be szádnak ajtaját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, 'Mert a fiú bolondnak tartja atyját, a leány anyja ellen támad, a meny az ő napára; az embernek saját háznépe az ellensége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, 'De én az Úrra nézek, várom az én szabadításom Istenét; meghallgat engem az én Istenem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, 'Ne örülj, én ellenségem! Elestem ugyan, de felkelek, mert ha még a setétségben ülnék is, az Úr az én világosságom!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'Az Úr haragját hordozom, mert vétkeztem ellene; mindaddig, a míg leperli peremet és meghozza ítéletemet. Kivisz engem a világosságra, meglátom az ő igazságát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, 'De meglátja ellenségem is és szégyen borítja el, a ki ezt mondja nékem: Hol az Úr, a te Istened? Meglátják őt az én szemeim, hogy ímé széttapostatik, mint az utcza-sár.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, 'Falaid megépítésének napja! e napon távol lesz a törvény!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, 'Azon a napon eljőnek hozzád Assiriából és Égyiptom városaiból; Égyiptomtól a folyamig, tengertől tengerig és hegytől hegyig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, 'És pusztává lesz a föld az ő lakói miatt, az ő cselekedeteik gyümölcséért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, 'Legeltesd népedet a te vessződdel, a te örökségednek nyáját, a mely magánosan lakozik az erdőben, a Kármel közepén. Legeljenek Básánban és Gileádban, mint a hajdankor napjain!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, 'Mint az Égyiptom földéről kijövetelednek idején, láttatok vele csodadolgokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, 'Látják ezt a pogányok és megszégyenülnek minden erejökkel. Kezöket szájokra teszik, füleik megsiketülnek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 17, 'Nyalják a port, mint a kígyó, mint a föld férgei; reszketve jőnek rejtekeikből; remegve folyamodnak az Úrhoz, a mi Istenünkhöz, és félnek tetőled!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 18, 'Kicsoda olyan Isten, mint te, a ki megbocsátja a bűnt és elengedi öröksége maradékának vétkét?! Nem tartja meg haragját örökké, mert gyönyörködik az irgalmasságban!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 19, 'Hozzánk térvén, könyörül rajtunk; eltapodja álnokságainkat. Bizony a tenger mélységébe veted minden bűnünket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 20, 'Hűséget mutatsz a Jákóbnak, irgalmasságot Ábrahámnak, a mint megesküdtél atyáinknak még az ősidőkben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, 'Ninive terhe; az elkosi Náhum látásának könyve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'Buzgón szerető és bosszúálló Isten az Úr, bosszúálló az Úr, és telve haraggal; bosszút áll az Úr az ő ellenségein, és haragot tartó az ő gyűlölői ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'Hosszútűrő az Úr és nagyhatalmú, és nem hagy büntetlenül. Szélvészben és viharban van az Úrnak útja, és lábainak pora a felhő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, 'Megfeddi a tengert és kiapasztja azt, és minden folyamot kiszáraszt. Elfonnyad a Básán és a Kármel, és a Libánon virága elfonnyad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, 'A hegyek reszketnek előtte, és a halmok szétmállanak. Tekintetétől megrendül a föld, és a világ, és minden, a mi rajta él.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, 'Ki állhatna meg haragja előtt, és ki birhatná ki búsulásának tüzét? Heve szétfoly, mint a láng, és a kőszálak is szétporlanak tőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'Jó az Úr, erősség a szorongatás idején, és ő ismeri a benne bízókat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, 'De gáttörő árvízként pusztít annak helyén, és gyűlölőit setétség üldözi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, 'Mit koholtok az Úr ellen? Elpusztít ő, nem lészen kétszer veszedelem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, 'Ha annyira összefonódnak is, mint a tüskebokrok, és olyan ázottak is, mint az italuk: megemésztetnek, mint a teljesen megszáradt tarló.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'Belőled származott, a ki gonoszt koholt az Úr ellen, a ki álnokságot tanácsolt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, 'Így szól az Úr: Ha teljes erőben és sokan vannak is, mégis levágatnak és elenyésznek. Megaláztalak téged, de nem foglak többé megalázni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, 'Most már leveszem rólad az ő igáját, és bilincseidet leszaggatom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, 'Felőled pedig azt rendeli az Úr: Nevednek ne támadjon többé magva; isteneid házából kivesztem a faragott és öntött képeket; megásom sírodat, mert becstelen vagy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 15, 'Ímé a hegyeken örömhírhozónak lábai! Békességet hirdet. Ünnepeld Júda ünnepeidet, fizesd le fogadásaidat; mert nem vonul át rajtad többé a semmirekellő; mindenestől kiirtatott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, 'Pusztító jön fel ellened; őrizd a várat, nézzed az útat, erősítsd derekadat, keményítsd meg erődet igen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, 'Mert helyreállítja az Úr Jákób büszkeségét, mint Izráel büszkeségét; mert rablók rabolták ki őket, csemetéiket pedig kivágták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'Vitézeinek pajzsa veres, katonáinak ruházata bíborszínű, hadiszekere aczéltűzben ragyog fegyverkezése napján, és a dárdákat rengetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, 'Az utczákon robognak a szekerek, összeütköznek a piaczokon; tekintetök mint a fáklyák, futkosnak mint a villámok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, 'Emlegeti vitézlő hőseit; ingadoznak lépéseikben, sietnek a kőfalra, és felállíttatik a védősáncz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, 'A folyóvizek kapui megnyílnak, és a palota megrendül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, 'De elvégeztetett: felfedik, elvitetik, és szolgálói keseregnek, mint nyögő galambok, mellöket vervén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'Pedig Ninive olyan, mint a bővizű tó, eleitől fogva: mégis futnak ők. Álljatok meg, álljatok meg! De vissza se tekint senki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, 'Raboljatok ezüstöt, raboljatok aranyat; száma sincs a rejtett kincseknek, gazdag minden drága edényben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, 'Feldúlva, széthányva, kifosztatva! Szíve megolvadt, a térdek reszketnek, fájdalom van egész derekában, és mindnyájok arcza elvesztette pirosságát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, 'Hol van az oroszlánok tanyája, és az oroszlán-kölyköknek ama legelője, a hová járt a nőstény- és hímoroszlán, az oroszlán-kölyök, és nem volt a ki elriaszsza?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, 'Az oroszlán torkig valót ragadozott kölykeinek, és fojtogatott nőstényeinek, és megtöltötte barlangjait zsákmánynyal, tanyáit pedig prédával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, 'Ímé rád török, azt mondja a Seregek Ura, és füstté égetem szekereit. Oroszlán-kölykeidet kard emészti meg, és kiirtom e földről zsákmányodat, és nem hallatszik többé követeidnek szava.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, 'Jaj a vérszopó városnak! Mindenestől hazug és erőszakkal telve, és nem szűnik rabolni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, 'Ostor-csattogás, kerék-zörgés zaja; dobogó ló, robogó szekér;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, 'Törtető lovag, kardok villogása, dárda villanása, sebesült tömegek, holtak sokasága, nincs számok az elesetteknek; megbotlanak hulláikban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, 'A szép parázna sok paráznaságáért, a hitetésnek mesternője miatt, a ki népeket ejtett meg paráznaságával, és nemzetségeket bűbájaival:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, 'Ímé, rád török, azt mondja a Seregek Ura, és orczádra fordítom ruhádnak alját, és népeknek mutatom meg meztelenségedet, és országoknak gyalázatodat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, 'Rútságot hányatok rád, és gyalázattal illetlek téged, és olyanná teszlek, mint a kit csudálnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, 'És mind, a ki meglát, elmenekül tőled, és ezt mondja: Elpusztult Ninive! Ki bánkódik rajta? Hol keressek néked vígasztalókat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, 'Avagy jobb vagy-é Nó-Amonnál, a mely a folyamoknál fekszik, vizek veszik körül; a melynek tenger a sáncza, tenger a kőfala?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, 'Kús volt erőssége meg Égyiptom, és száma sem volt annak. Puth és Libia is segítőid voltak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, 'De ez is számkivetésbe, fogságba jutott; kisdedeik is falhoz verettek minden utcza sarkán; főembereire sorsot vetettek, és nagyjait mind bilincsekbe verték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, 'Te is megrészegedel, elfeledtté leszel; te is keresel majd menedéket a gyűlölködő elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, 'Minden erősséged olyan, mint a zsenge gyümölcsű fügefa; ha megrázatnak, az evő szájába hullnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, 'Ímé, a te néped asszonynép te benned, földednek kapui tárva kitárulnak gyűlölőidnek, tűz emészti meg záraidat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, 'Meríts magadnak ostromhoz való vizet, javítsd erősségeidet; menj be a sárba, taposd az agyagot, javítsd a tégla-vetőt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, 'Legott tűz emészt meg téged, fegyver irt ki téged, megemészt, mint a szöcske; szaporodjál bár, mint a szöcske, szaporodjál bár mint a sáska!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, 'Többen voltak kalmáraid, mint az égnek csillagai: a szöcske csapong és elrepül!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, 'Fejedelmeid mint a sáska, vezéreid mint a tücsök-raj; hideg időkben gyepűkben tanyáz, napkeletkor pedig elrepül, és helye sem tudható meg, hol volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, 'Szunnyadoznak pásztoraid, Assiria királya, feküsznek vitézlő hőseid; néped a hegyeken széledez, és nincsen, a ki összegyűjtse.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, 'Nincs enyhítés a te sebedre, gyógyíthatatlan a te nyavalyád. A kik híredet hallják, mind tapsolnak feletted, mert kire nem hatott volna ki a te gonoszságod soha?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, 'A teher, a melyet Habakuk próféta látott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, 'Meddig kiáltok még oh Uram, és nem hallgatsz meg! Kiáltozom hozzád az erőszak miatt, és nem szabadítasz meg!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, 'Miért láttatsz velem hamisságot, és szemléltetsz nyomorgatást? Pusztítás és erőszak van előttem, per keletkezik és versengés támad!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, 'Azért inog a törvény, és nem érvényesül az igaz ítélet; mert gonosz hálózza be az igazat, azért származik hamis ítélet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, 'Nézzetek szét a népek között, vizsgálódjatok és csodálkozással csodálkozzatok, mert oly dolgot cselekszem a ti napjaitokban, mit el sem hinnétek, ha beszélnék!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, 'Mert ímé, feltámasztom a Káldeusokat, a kegyetlen és vakmerő nemzetet, a mely eljárja a földet széltében, hogy hajlékokat foglaljon el, a melyek nem az övéi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, 'Rettenetes és iszonyatos ez, maga szerzi törvényét és hatalmát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, 'És lovai serényebbek a párduczoknál, és gyorsabbak az estveli farkasoknál, és előtörtetnek az ő lovasai; és az ő lovasai messziről jőnek, repülnek, mint a zsákmányra siető keselyű.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, 'Mindnyája ragadományért jön, arczuk előre néz, és annyi foglyot gyűjt, mint a föveny.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, 'Kaczag ez a királyokon, és a fejedelmek néki nevetség, minden erősséget csak nevet, töltést emel és megostromolja azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, 'Majd tovaszáll viharként és elvonul és bűnbe esik; ő kinek istene az ő hatalma.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, 'Avagy nem te vagy-é Uram, öröktől fogva az én Istenem, Szentem? Nem veszünk el! Ítéletre rendelted őt, oh Uram, fenyítőül választottad őt, én erősségem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, 'Tisztábbak szemeid, hogysem nézhetnéd a gonoszt, és a nyomorgatást nem szemlélheted: miért szemléled hát a hitszegőket? és hallgatsz, mikor a gonosz elnyeli a nálánál igazabbat?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, 'Olyanokká teszed az embert, mint a tenger halai, és mint a csúszómászó állatok, a melyeknek nincsen vezérök?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, 'Mindnyáját kivonsza horoggal, gyalomjába keríti, és hálójába takarítja be őket; ezért örül és vígad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 16, 'Ezért áldozik gyalomjának, és füstöl az ő hálójának, mert ezekkel kövér az ő része, és zsíros az ő eledele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 17, 'Vajjon azért ürítheti-é gyalmát, és szüntelen ölheti-é a nemzeteket kímélet nélkül?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, 'Őrhelyemre állok, és megállok a bástyán, és vigyázok, hogy lássam, mit szól hozzám, és mit feleljek én panaszom dolgában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'És felele nékem az Úr, és mondá: Írd fel e látomást, és vésd táblákra, hogy könnyen olvasható legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'Mert e látomás bizonyos időre szól, de vége felé siet és meg nem csal; ha késik is, bízzál benne; mert eljön, el fog jőni, nem marad el!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, 'Ímé, felfuvalkodott, nem igaz ő benne az ő lelke; az igaz pedig az ő hite által él.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, 'És bizony, a bor is megcsal: felgerjed a férfiú és nincsen nyugalma; ő, a ki tátja száját, mint a Seol, és olyan ő, mint a halál: telhetetlen, és magához ragad minden népet és magához csatol minden nemzetet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, 'Avagy nem költenek-é ezek mindnyájan példabeszédet róla, és találós mesét reá, mondván: Jaj annak, a ki rakásra gyűjti, a mi nem övé! De meddig? És a ki adóssággal terheli magát!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, 'Avagy nem támadnak-é hirtelen, a kik téged mardossanak, és nem serkennek-é fel, a kik háborgassanak téged? És zsákmányul esel nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, 'Mivelhogy kifosztogattál sok nemzetet, kifosztanak téged mind a többi népek az emberek véréért, és az országok, városok és minden bennök lakozók ellen való erőszaktételért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, 'Jaj annak, a ki bűnös szerzeményt szerez házának, hogy magasra rakhassa fészkét, hogy megszabadulhasson a gonosz hatalma elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, 'Házadnak gyalázatára tervezted a sok nép kiirtását, és bűnössé tetted lelkedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, 'Mert a kő is ellened kiált a falból, és a gerenda a fa-alkotmányból visszhangoz néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, 'Jaj annak, a ki várost épít vérengzéssel, és a ki várat emel álnoksággal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, 'Avagy ímé, nem a Seregek Urától van-é ez, hogy a népek tűznek építenek, és a nemzetek a hiábavalóságnak fáradoznak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, 'Mert az Úr dicsőségének ismeretével betelik a föld, a miképen a folyamok megtöltik a tengert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, 'Jaj annak, a ki megitatja felebarátját, epédet keverve belé, hogy megrészegítsed őt, hogy láthassad az ő szemérmöket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, 'Gyalázattal telsz meg dicsőség helyett; igyál te is és láttassék szemérmed; reád fordul az Úr jobbjának pohara, és gyalázat borítja el dicsőségedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 17, 'Bizony, a libanoni erőszakoskodás gyászba borít téged, és a vadak pusztítása, a mely rettegteté őket, az emberek véréért és az országon, a városon és annak minden lakosán űzött erőszakosságért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 18, 'Mit használ a faragott kép, hogy a faragója kifaragta azt? vagy az öntött kép és a mely hazugságot tanít, hogy a képnek faragója bízik abban, csinálván néma bálványokat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 19, 'Jaj annak, aki fának mondja: Serkenj fel! néma kőnek: Ébredj fel! Taníthat-é ez? Ímé, borítva van aranynyal és ezüsttel, lélek pedig nincs benne semmi!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 20, 'Ellenkezőleg az Úr az ő szent templomában, hallgasson előtte az egész föld!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, 'Habakuk próféta könyörgése a sigjónóth szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, 'Uram, hallám, a mit hirdettél, és megrettenék! Uram! Évek közepette keltsd életre a te munkádat, évek közepette jelentsd meg azt! Haragban emlékezzél meg kegyelmességről!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, 'Isten a Témán felől jön, és a Szent a Párán hegyéről. Szela. Dicsősége elborítja az egeket, és dícséretével megtelik a föld.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'Ragyogása, mint a napé, sugarak támadnak mellőle; és ott van az ő hatalmának rejteke.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, 'Előtte döghalál jár, és nyomaiban forró láz támad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, 'Megáll és méregeti a földet, pillant és megrendíti a népeket, az örökkévaló hegyek szétporlanak, elsüllyednek az örökkévaló halmok; az ő ösvényei örökkévalók!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, 'Bomlani látom Khusán sátrait, reszketnek a Midián-föld kárpitjai!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, 'A folyók ellen gerjedt-é fel az Úr? Vajjon a folyókra haragszol-é, vagy a tengerre bőszültél-é fel, hogy lovaidon és diadal-szekereiden robogsz?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, 'Csupasz, meztelen a te kézíved, a törzseknek esküvéssel tett igéret szerint! Szela. A föld folyókat ömleszt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, 'Látnak téged és megrendülnek a hegyek, gátat tör a víz-ár, harsog a hullám, és magasra emeli karjait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, 'A nap és hold megállnak helyökön czikázó nyilaid fényétől és ragyogó kopjád villanásától.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, 'Haragodban eltaposod a földet, búsultodban szétmorzsolod a nemzeteket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, 'Kiszállsz néped szabadítására, fölkented segítségére; szétzúzod a főt a gonosznak házában; nyakig feltakarod az alapjait. Szela!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, 'Saját dárdájával vered át az ő vezéreinek fejét, a kik berohannak, hogy szétszórjanak engem; ujjonganak, hogy rejtekében emészthetik meg a szegényt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, 'Lovaiddal megtaposod a tengert, a nagy vizek hullámait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 16, 'Hallám és reszket a bensőm, a szózatra remegnek ajkaim; porladni kezdenek csontjaim, reszketnek lábaim: hogy nyugton legyek a nyomorúság napján, a mely feljön a népre, mely megsanyargatja azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 17, 'Mert a fügefa nem fog virágozni, a szőlőkben nem lészen gyümölcs, megcsal az olajfa termése, a szántóföldek sem teremnek eleséget, kivész a juh az akolból, és nem lesz ökör az istállóban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 18, 'De én örvendezni fogok az Úrban, és vígadok az én szabadító Istenemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 19, 'Az Úr Isten az én erősségem, hasonlókká teszi lábaimat a nőstény szarvasokéihoz, és az én magas helyeimen jártat engemet! Az éneklőmesternek, az én hangszereimmel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, 'Az Úr igéje, a melyet szólt Sofóniásnak, a Kusi fiának, a ki Gedáliás fia, a ki Amariás fia, a ki Ezékiás fia, Jósiásnak az Amon fiának idejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, 'Elvesztek, mindent elvesztek e föld színéről, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, 'Elvesztek embert és barmot; elvesztem az ég madarait, és a tenger halait és a botránkoztatás eszközeit a hitetlenekkel együtt; az embert is kiirtom a föld színéről, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, 'És kinyújtom kezemet Júda ellen és Jeruzsálem minden lakója ellen, és kiirtom e helyről a Baál maradékát, a bálványpapok nevét a papokkal együtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'Azokat is, a kik a háztetőkön az ég seregének hajlonganak; és azokat, a kik hajlonganak, esküdvén az Úrra, de esküsznek az ő Molokjokra is;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'Azokat is, a kik elfordultak az Úr követésétől, és a kik nem keresik az Urat és nem tudakoznak felőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, 'Hallgass az Úr Isten orczája előtt, mert közel van az Úrnak napja, mert áldozatot készíttetett az Úr, megszentelte az ő hivatalosait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, 'És lészen az Úr áldozatának napján: megfenyítem majd a fejedelmeket és a királyok fiait és mindazokat, a kik idegen öltözetbe öltöztek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'És megfenyítem mindazt, a ki a küszöbön ugrál ama napon, a kik erőszakkal és csalárdsággal töltik meg az ő uroknak házát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, 'És lészen azon a napon, azt mondja az Úr, kiáltó szózat a hal-kaputól fogva, és jajgatás az alsó városból, és nagy recsegés a halmok felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'Jajgassatok, ti, a kik a völgyben laktok, mert elpusztul az egész kalmár nép, kivágattatik minden, a ki ezüstöt mér.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'És lészen az időben, megmotozom majd Jeruzsálemet szövétnekkel, és megfenyítem azokat, a kik saját seprejökön hevernek, a kik ezt mondják szívökben: sem jót, sem rosszat nem cselekszik az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'És gazdagságuk prédává lesz, házaik pedig pusztává. Építnek házakat, de nem lakják, és plántálnak szőlőket, de nem iszszák azoknak borát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'Közel van az Úrnak nagy napja, közel van és igen siet; az Úr napjának szava keserves, kiáltoz azon a hős is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, 'Haragnak napja az a nap, szorongatásnak és nyomorúságnak napja; pusztításnak és pusztulásnak napja; sötétségnek és homálynak napja; felhőnek és borúnak napja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, 'Kürtnek és tárogatónak napja a megerősített városok ellen és a büszke tornyok ellen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, 'És megszorongatom az embereket és járnak, mint a vakok, mert vétkeztek az Úr ellen, és kiontatik vérök, mint a por, és testök, mint szemét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, 'Sem ezüstjök, sem aranyuk nem szabadíthatja meg őket az Úr haragjának napján, és az ő féltő szeretetének tüze megemészti az egész földet; mert véget vet, bizony hirtelen vet véget e föld minden lakosának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, 'Térjetek eszetekre, s eszméljetek fel, ti, arczátlan nemzet,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, 'Mielőtt szűlne a végzés (mint a polyva száll tova az a nap!); míg rátok nem jön az Úr haragjának tüze, míg rátok nem jön az Úr haragjának napja!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, 'Keressétek az Urat mindnyájan e föld alázatosai, a kik az ő ítélete szerint cselekesztek; keressétek az igazságot, keressétek az alázatosságot: talán megoltalmaztattok az Úr haragjának napján!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, 'Mert elhagyottá lesz Gáza, Askelon pedig pusztasággá; Asdódot délben űzik el, és Ekron kiirtatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, 'Jaj a tenger vidékén lakóknak, a Kereteusok nemzetségének! Az Úr igéje ellened van, te Kanaán, Filiszteusok földje; elpusztítalak téged, lakatlanná leszel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, 'És a tenger vidéke legelőkké, pásztorok tanyáivá és juhoknak aklaivá lészen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, 'És az a vidék a Júda házának maradékáé lesz, ők legeltetnek azon; estére Askelon házaiban heverésznek, mert meglátogatja őket az Úr, az ő Istenök, és visszahozza az ő foglyaikat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, 'Hallottam Moáb gyalázkodását és Ammon fiainak szidalmait, a melyekkel gyalázták népemet, és felfuvalkodtak az ő határok ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, 'Azért élek én, mond a Seregeknek Ura, Izráelnek Istene, hogy Moáb olyanná lészen, mint Sodoma, Ammon fiai pedig, mint Gomora: tövistermő föld, só-telep és pusztaság örökre; népem maradéka prédálja fel őket, és nemzetségem ivadékai bírják majd őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, 'Ez esik meg rajtok az ő kevélységökért, a miért gyalázkodtak és felfuvalkodtak a Seregek Urának népe ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, 'Rettenetes lesz az Úr ellenök, mert elfogyatja a földnek minden istenét, és néki hódol majd kiki a maga lakhelyén, a pogányoknak is minden szigete.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, 'Ti is, kúsiak! Fegyverem öli meg őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, 'És kinyújtja kezét észak felé, és elveszti Assiriát, Ninivét pusztasággá teszi, kietlenné, mint egy sivatag.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 14, 'És nyájak heverésznek bensejében, mindenféle állatok serege: pelikán és sündisznó hálnak párkányain, az ablakban azoknak szava hangzik, a küszöbön omladék lészen, mert lefosztatott a czédrus!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 15, 'Ímé, a víg város, a bátorságban lakozó, a mely ezt mondja vala szívében: Én vagyok és nincs kívülem más! milyen pusztasággá lőn, vadak tanyájává, a ki átmegy rajta, mind süvöltöz és csapkodja kezét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, 'Jaj az ellenszegülőnek és undoknak, az erőszakos városnak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, 'Nem hallgatott a szóra, nem fogadta a fenyítéket, nem bízott az Úrban, Istenéhez nem közelített!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, 'Fejedelmei olyanok benne, mint az ordító oroszlánok, birái, mint az estve járó farkasok, nem hagynak reggelre a csonton.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, 'Prófétái hivalkodók, hitető férfiak; papjai megfertéztetik a szent helyet, erőszakot tesznek a törvényen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, 'Az Úr igaz ő benne, nem cselekszik hamisságot; reggelről reggelre napfényre hozza ítéletét; nem mulasztja el: de nem ismeri a szégyent a gonosz!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 6, 'Nemzeteket irtottam ki; elpusztultak tornyaik; feldúltam falvaikat, nincs, a ki átmenjen rajtok; elromboltattak városaik, egy ember sincs bennök, nincsen lakosuk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 7, 'Mondtam: Csak félj engem, vedd fel a fenyítéket (akkor nem irtatott volna ki lakhelye; mindaz, a mit felőle végeztem): mégis mihelyt felvirradtak, rosszra indították minden cselekedetöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 8, 'Azért várjatok rám, azt mondja az Úr, míg prédára kelek; mert elvégeztem, hogy egybegyűjtöm a népeket, hogy összeszedem az országokat, hogy kiöntsem rájok búsulásomat, haragomnak egész hevét, mert gerjedezésem tüzében emésztetik meg az egész föld!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 9, 'Akkor változtatom majd a népek ajkát tisztává, hogy mind segítségül hívják az Úr nevét, hogy egy akarattal szolgálják őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 10, 'Kús folyóvizein túlról hozzák imádóim, szétszórt népemnek leányai ételáldozatomat nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 11, 'Azon a napon nem szégyenülsz meg egyetlen cselekedetért sem, a melyekkel vétkeztél ellenem; mert akkor eltávolítom körödből azokat, a kik kérkedve örvendeznek benned, és nem kevélykedel többé az én szent hegyemen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 12, 'És marasztok közötted nyomorult és szegény népet, a kik bíznak az Úr nevében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 13, 'Izráel maradéka nem cselekszik hamisságot, nem szól hazugságot, és nem találtatik szájában álnokságnak nyelve, hanem legelésznek és lenyugosznak és nem lesz a ki felrettentse őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 14, 'Énekelj Sionnak leánya, harsogj Izráel, örvendj és teljes szívvel vígadj Jeruzsálem leánya!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 15, 'Megváltoztatta az Úr a te ítéletedet, elfordította ellenségedet; Izráel királya, az Úr, közötted van, nem látsz többé gonoszt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 16, 'Azon a napon ezt mondják Jeruzsálemnek: Ne félj! Ne lankadjanak kezeid Sion!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 17, 'Az Úr, a te Istened közötted van; erős ő, megtart; örül te rajtad örömmel, hallgat az ő szerelmében, énekléssel örvendez néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 18, 'Az ünnep miatt bánkódókat egybegyűjtöm, a kik közüled valók; gyalázat terhe van rajtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 19, 'Ímé, én elbánok minden te nyomorgatóddal abban az időben, és megtartom a sántát, és összeszedem a szétszórtakat, és híresekké és nevesekké teszem őket az ő gyalázatjoknak egész földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 20, 'Abban az időben elhozlak titeket, és akkor összeszedlek titeket, mert nevesekké és híresekké teszlek titeket a földnek minden népe között, mikor megfordítom a ti fogságotokat a ti szemetek előtt, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'Dárius király második esztendejének hatodik hónapjában, a hónapnak első napján szóla az Úr Aggeus próféta által Zorobábelnek, a Sealtiél fiának, Júda fejedelmének, és Jósuának, a Jehosadák fiának, a főpapnak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, 'Így szól a Seregeknek Ura, mondván: Ezt mondja e nép: Nem jött még el az idő, az Úr háza építésének ideje!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'Az Úr pedig így szól Aggeus próféta által, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, 'Ideje-é néktek, hogy ti mennyezetes házakban lakozzatok, holott ez a ház romban áll?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'Most azért ezt mondja a Seregeknek Ura: Gondoljátok meg jól a ti útaitokat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'Sokat vetettetek, de keveset takartok; esztek, de meg nem elégesztek; isztok, de meg nem részegesztek; ruházkodtok, de meg nem melegesztek, a bérlő is lyukas zacskóra bérel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'Ezt mondja a Seregeknek Ura: Gondoljátok meg jól a ti útaitokat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'Menjetek fel a hegyre, és hordjatok fát, és építsétek e házat, hogy gyönyörködjem benne, és dicsőíttessem, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, 'Sokat vártatok, de ímé kevés lett; haza is hordtátok, de én ráfuvallok arra! Mi okért? azt mondja a Seregeknek Ura. Az én házamért, a mely ím romban áll, ti pedig siettek, kiki a maga házához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'Azért vonták meg tőletek az egek a harmatot, vonta meg a föld az ő termését.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'És pusztulást rendeltem a sík földre és a hegyekre, a búzára és a borra, az olajra és mindarra, a mit a föld terem; sőt az emberre és a baromra és minden kézimunkára is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'És meghallá Zorobábel, a Sealtiél fia, és Jósua, a Jehosadák fia, a főpap, és a nép minden többi tagja az Úrnak, az ő Istenöknek szavát és Aggeus próféta beszédeit, a miként elküldte őt az Úr, az ő Istenök, és megfélemlék a nép az Úr előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'És szóla Aggeus, az Úr követe, az Úr küldetésében, mondván a népnek: Én veletek vagyok, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'És felindítá az Úr Zorobábelnek, a Sealtiél fiának, a Júda fejedelmének lelkét, és Jósuának, a Jehosadák fiának, a főpapnak lelkét, és a nép minden többi tagjának lelkét is, és bemenének és munkálkodának a Seregek Urának, az ő Istenöknek házában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, 'A hatodik hónapnak huszonnegyedik napján, Dárius királynak második esztendejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, 'A hetedik hónap huszonnegyedik napján szóla az Úr Aggeus próféta által, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, 'Szólj csak Zorobábelnek, a Sealtiél fiának, Júda fejedelmének, és Jósuának, a Jehosadák fiának, a főpapnak, és a nép többi tagjainak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, 'Ki van még életben köztetek, a ki látta ezt a házat az ő első dicsőségében? És milyennek látjátok ti most ezt? Avagy olyan-é ez a ti szemetekben, mintha semmi volna?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'De most légy bátor, Zorobábel, azt mondja az Úr! Légy bátor te is, Jósua, Jehosadák fia, te főpap, és légy bátor e földnek minden népe, azt mondja az Úr, és cselekedjétek, mert én veletek vagyok, azt mondja a Seregeknek Ura,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, 'Az igét, a melylyel szövetségre léptem veletek, mikor kijöttetek Égyiptomból, és az én lelkem köztetek marad. Ne féljetek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, 'Mert ezt mondja a Seregeknek Ura: Egy kevés idő van még, és én megindítom az eget és a földet, a tengert és a szárazt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'És megindítok minden népet, és eljön, a kit minden népek óhajtanak, és megtöltöm e házat dicsőséggel, azt mondja a Seregeknek Ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, 'Enyém az ezüst és enyém az arany, azt mondja a Seregeknek Ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, 'Nagyobb lészen e második háznak dicsősége az elsőnél, azt mondja a Seregeknek Ura, és e helyen adok békességet, azt mondja a Seregeknek Ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'A kilenczedik hónap huszonnegyedikén, Dáriusnak második esztendejében szóla az Úr Aggeus próféta által, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, 'Ezt mondja a Seregeknek Ura: Kérdezd meg csak a papokat a törvény felől, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, 'Ha szentelt húst visz valaki az ő köntösének szárnyában, és illeti annak szárnyával a kenyeret vagy a főzeléket, vagy a bort, vagy az olajat, vagy bármi más eleséget: vajjon szent-e az? És felelének a papok, és mondák: Nem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'Aggeus pedig mondá: Ha hulla által fertőzött illeti mindezeket, tisztátalanná lesz-é? És felelének a papok, és mondák: Tisztátalanná!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'Aggeus pedig felele, és mondá: Épp így e nép és épp így e nemzet én előttem, azt mondja az Úr, és épp így kezöknek minden munkája, és a mit ide felhoznak: tisztátalan az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, 'Most azért jól gondoljátok meg e naptól fogva az elmultakat is, mielőtt még követ kőre tettek volna az Úr hajlékában!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'Az előtt elmentek a huszas garmadához, és tíz lett; elmentek a sajtóhoz, hogy ötven vederrel merítsenek, és húsz lett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, 'Megvertelek titeket üszöggel, ragyával, és kezetek minden munkáját kőesővel, és még sem hajoltatok hozzám, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, 'Jól gondoljátok hát meg e naptól fogva az elmultakat is! A kilenczedik hónap huszonnegyedik napjától, attól a naptól fogva, a melyen letétetett az Úr hajlékának alapja. Jól meggondoljátok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, 'Van-é még mag a csűrben? És bizony, a szőlő, a füge, a gránátalma és az olajfa sem termett! E naptól fogva megáldalak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, 'Másodszor is szóla az Úr Aggeusnak a hónap huszonnegyedik napján, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, 'Mondd meg Zorobábelnek, Júda fejedelmének: Én megindítom az eget és a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, 'És felforgatom az országok királyi székét, és elfogyasztom a pogány országok erejét, és felforgatom a szekeret és a benne ülőket, és lehullanak a lovak és a rajtok ülők: kiki az ő atyjafiának fegyvere által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, 'Azon a napon, azt mondja a Seregeknek Ura, felveszlek téged Zorobábel, Sealtiélnek fia, én szolgám, azt mondja az Úr, és olyanná teszlek, mint egy pecsétgyürű, mert téged választottalak el, azt mondja a Seregeknek Ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'Dárius második esztendejében, a nyolczadik hónapban szóla az Úr Zakariáshoz, a Berekiás fiához, a ki Iddó próféta fia, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, 'Igen megharagudott az Úr a ti atyáitokra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, 'Mondjad azért nékik: Ezt mondja a Seregeknek Ura: Térjetek hozzám, szól a Seregeknek Ura, és hozzátok térek, mond a Seregeknek Ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, 'Ne legyetek olyanok, mint atyáitok, a kikhez az elébbi próféták kiáltottak, mondván: Ezt mondja a Seregeknek Ura: Térjetek meg kérlek a ti gonosz útaitokról, és a ti gonosz cselekedeteitekből, de nem hallgattak meg, és nem figyelmeztek reám, szól az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, 'Atyáitok? Hol vannak ők? És a próféták örökké élnek-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'De az én beszédeim és végzéseim, a melyeket szolgáim, a próféták által hirdettem: nem beteljesedtek-é a ti atyáitokon? És megtértek és azt mondták: A mint elhatározta vala a Seregeknek Ura, hogy a mi útaink és cselekedeteink szerint bánik velünk: úgy bánt velünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'A tizenegyedik hónapnak, azaz a Sebat hónapnak huszonnegyedik napján, Dáriusnak második esztendejében, szóla az Úr Zakariáshoz, a Berekiás fiához, a ki Iddó próféta fia, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, 'Látám éjszaka, hogy ímé, egy férfiú veres lovon ül vala, és áll vala a mirtus-fák között, a melyek egy árnyas völgyben valának; háta megett pedig veres, tarka és fehér lovak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, 'És mondám: Mik ezek Uram? És mondá nékem az angyal, a ki beszél vala nékem: Én megmutatom néked: mik ezek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'Akkor felele az a férfiú, a ki a mirtus-fák között áll vala, és mondá: Azok ezek, a kiket az Úr küldött, hogy járják be e földet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'És felelének az Úr angyalának, a ki a mirtus-fák között áll vala, és mondák: Bejártuk a földet, és ímé, az egész föld vesztegel és nyugodt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'Az Úr angyala pedig felele, és mondá: Seregeknek Ura! Meddig nem könyörülsz még Jeruzsálemen és Júdának városain, a melyekre haragszol immár hetven esztendő óta?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'És nyájas szavakkal, vígasztaló szókkal felele az Úr az angyalnak, a ki beszél vala velem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'És mondá nékem az angyal, a ki beszél vala velem: Kiálts, ezt mondván: Ezt mondja a Seregeknek Ura: szeretem Jeruzsálemet és a Siont nagy szeretettel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'De nagy haraggal haragszom én a hivalkodó népekre, a kikre kevéssé haragudtam ugyan, de ők gonoszra törtek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'Azt mondja azért az Úr: könyörületességgel fordulok Jeruzsálemhez; benne építtetik meg az én házam, szól a Seregeknek Ura, és mérőzsinór nyujtatik ki Jeruzsálem felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, 'Mégis kiálts, mondván: Ezt mondja a Seregeknek Ura: Bővelkedni fognak még városaim a jóban, mert megvígasztalja még az Úr a Siont, és magáévá fogadja még Jeruzsálemet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 18, 'Majd felemelém szemeimet, és ímé, négy szarvat láték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 19, 'És mondám az angyalnak, a ki beszél vala velem: Mik ezek? És monda nékem: Ezek azok a szarvak, a melyek szétszórták Júdát, Izráelt és Jeruzsálemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 20, 'Azután mutata nékem az Úr négy mesterembert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 21, 'És mondám: Mit jöttek ezek cselekedni? Ő pedig szóla, mondván: Ezek azok a szarvak, a melyek szétszórták Júdát annyira, hogy senki sem emelheti vala fel fejét: de eljöttek ezek, hogy elrettentsék őket, hogy letörjék a pogányok szarvait, a kik szarvakkal támadtak vala Júda földe ellen, hogy szétszórják azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, 'Felemelém ismét szemeimet, és ímé, láték egy férfiút és a kezében mérő-kötelet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, 'És mondám: Hová mégy te? És mondá nékem: Megmérni Jeruzsálemet, hogy lássam: mennyi a széle és mennyi a hossza?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, 'És ímé, az angyal, a ki beszél vala velem, kijöve, és más angyal is kijöve eléje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, 'És monda annak: Fuss, és szólj e gyermekhez, mondván: Kerítetlenül fogják lakni Jeruzsálemet a benne levő emberek és barmok sokasága miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, 'Én pedig, szól az Úr, tűz-fal leszek körülötte és megdicsőítem magamat ő benne!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, 'Jaj, jaj! Fussatok ki az északi földről, így szól az Úr, mert az ég négy szele felé szórtalak szét titeket, szól az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, 'Jaj Sion! Szabadítsd ki magadat, ki Babilon leányánál lakozol.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, 'Mert így szól a Seregeknek Ura: Dicsőség után küldött engem a pogányokhoz, a kik fosztogatnak titeket, mert a ki titeket bánt, az ő szemefényét bántja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, 'Mert ímé én felemelem kezemet ellenök, és saját szolgáik prédájává lesznek, és megtudjátok, hogy a Seregeknek Ura küldött el engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, 'Örülj és örvendezz, Sionnak leánya, mert ímé elmegyek és közötted lakozom! így szól az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, 'És sok pogány csatlakozik azon a napon az Úrhoz, és népemmé lesznek, és közötted lakozom, és megtudod, hogy a Seregeknek Ura küldött hozzád engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, 'És birtokba veszi az Úr Júdát, mint az ő osztályrészét a szent földön, és újra magáévá fogadja Jeruzsálemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, 'Hallgasson minden test az Úr előtt: mert felkelt az ő szentséges helyéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, 'Azután megmutatá nékem Jósuát, a főpapot, a ki az Úr angyala előtt álla, és a Sátánt, a ki jobb keze felől álla, hogy vádolja őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, 'És mondá az Úr a Sátánnak: Dorgáljon meg téged az Úr, te Sátán; dorgáljon meg az Úr, a ki magáévá fogadja Jeruzsálemet. Avagy nem tűzből kikapott üszög-é ez?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, 'Jósua pedig szennyes ruhába vala öltöztetve, és áll vala az angyal előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, 'És szóla és monda az előtte állóknak, mondván: Vegyétek le róla a szennyes ruhákat! És monda néki: Lásd! Levettem rólad a te álnokságodat, és ünnepi ruhákba öltöztetlek téged!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, 'Azután mondám: Tegyenek fejére tiszta süveget! Feltevék azért fejére a tiszta süveget, és ruhákba öltözteték őt, az Úrnak angyala pedig ott áll vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, 'És bizonyságot tőn az Úrnak angyala Jósuának, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, 'Ezt mondja a Seregeknek Ura: Ha az én útaimban jársz, és ha parancsolataimat magtartod: te is ítélője leszel az én házamnak, sőt őrizni fogod az én pitvaraimat, és ki- s bejárást engedek néked ez itt állók között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, 'Halld meg Jósua, te főpap; te és barátaid, a kik előtted ülnek, mert jelképes férfiak ezek: Ímé, bizony előhozom az én szolgámat, Csemetét!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, 'Mert ímé e kő az, a melyet Jósua elé helyezek; egy kövön hét szem; ímé, én faragom annak faragványait, így szól a Seregeknek Ura, és eltörlöm e földnek álnokságait egy napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, 'Azon a napon, így szól a Seregeknek Ura, kiki hívja majd a maga felebarátját a szőlőtő alá és a fügefa alá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, 'Majd visszatére az angyal, a ki beszél vala velem, és felkölte engem, mint mikor valaki álmából költetik fel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, 'És mondá nékem: Mit látsz te? És mondám: Látok ímé egy merő arany gyertyatartót, tetején az olajtartója, rajta pedig annak hét szövétneke, és hét cső a szövétnekekhez, a melyek a tetején vannak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, 'És mellette két olajfa: egyik az olajtartó jobb oldalán, a másik pedig annak bal oldalán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, 'És felelék, és mondám az angyalnak, a ki beszél vala velem, mondván: Mik ezek, Uram?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, 'És felele az angyal, a ki beszél vala velem, és mondá nékem: Hát nem tudod-é, mik ezek? És mondám: Nem, Uram!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, 'És felele, és szóla nékem, mondván: Az Úrnak beszéde ez Zorobábelhez, mondván: Nem erővel, sem hatalommal, hanem az én lelkemmel! azt mondja a Seregeknek Ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, 'Ki vagy te, te nagy hegy? Lapálylyá leszel Zorobábel előtt, és felviszi a csúcs-követ, és ilyen kiáltás támad: Áldás, áldás reá!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, 'És szóla hozzám az Úr, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, 'A Zorobábel kezei veték meg e ház alapját, és az ő kezei végzik el azt, és megtudod, hogy a Seregeknek Ura küldött el engem hozzátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, 'Mert a kik csúfolták a kicsiny kezdetet, örülni fognak, ha meglátják Zorobábel kezében az ónkövet. Hét van ilyen, az Úrnak szemei ezek, a melyek átpillantják az egész földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, 'És felelék, és mondám néki: Mi ez a két olajfa a gyertyatartó jobb és bal oldalán?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, 'És másodszor is felelék, és mondám néki: Micsoda az olajfának az a két ága, a melyek a két arany cső mellett vannak, és öntik magukból az aranyat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, 'És szóla nékem, mondván: Hát nem tudod-é, mik ezek? És mondám: Nem, Uram!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 14, 'És mondá nékem: Ezek ketten az olajjal felkenettek, a kik az egész föld Ura mellett állnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, 'Azután ismét felemelém szemeimet, és látám, hogy ímé, egy könyv repül vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 2, 'És monda nékem: Mit látsz te? És én mondám: Látok egy repülő könyvet, húsz sing a hossza és tíz sing a széle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 3, 'És monda nékem: Ez az átok, a mely kihat az egész föld színére; mert mindaz, a ki lop, ehhez képest fog innen kiirtatni, és mindaz, a ki hamisan esküszik, ehhez képest fog innen kiirtatni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 4, 'Kibocsátom ezt, szól a Seregeknek Ura, és bemegy a lopónak házába, és annak házába, a ki hamisan esküszik az én nevemre, és ott marad annak házában, és megemészti azt, s annak fáit és köveit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 5, 'Majd kijöve az angyal, a ki beszél vala velem, és monda nékem: Emeld csak fel szemeidet, és lásd meg: micsoda az, a mi kijön?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 6, 'És mondám: Micsoda ez? Ő pedig mondá: Az, a mi kijön, mérőedény. És mondá: Ilyen a formájok az egész földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 7, 'És ímé, egy kerek ón-darab repül vala, és ül vala egy asszony a mérő-edény közepében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 8, 'És mondá: Ez az istentelenség. És veté ezt a mérő-edény közepébe, a darab ónt pedig veté annak szájára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 9, 'És felemelém szemeimet, és látám, hogy ímé, két asszony jöve elő, és szél vala szárnyaikban, és szárnyaik olyanok, mint az eszterágnak szárnyai, és felemelék a mérő-edényt a föld és az ég közé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 10, 'És mondám az angyalnak, a ki beszél vala velem: Hová viszik ezek a mérő-edényt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 11, 'És mondá nékem: Hogy házat építsenek annak a Sineár földén, és oda erősítsék, és ott hagyják azt a maga helyén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 1, 'Majd megfordulék és felemelém szemeimet, és látám, hogy ímé négy szekér jön vala ki két hegy közül, és azok a hegyek ércz-hegyek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 2, 'Az első szekérben veres lovak, a második szekérben fekete lovak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 3, 'És a harmadik szekérben fehér lovak; a negyedik szekérben pedig tarka lovak, erősek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 4, 'És megszólalék, és mondám az angyalnak, a ki beszél vala velem: Mik ezek, Uram?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 5, 'Az angyal felele, és mondá nékem: Ezek az égnek négy szele, jőnek az egész föld Ura mellett való szolgálatukból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 6, 'A melyben a fekete lovak vannak, észak földére mennek, és a fehérek mennek utánok, a tarkák pedig a dél földére mennek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 7, 'Az erősek is mennek és kivánják eljárni a földet. És mondá: Menjetek, járjátok el a földet; és eljárák a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 8, 'Majd híva engem, és beszéle velem, mondván: Lásd! Az észak földére menők lecsendesíték lelkemet északnak földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 9, 'És szóla az Úr hozzám, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 10, 'Végy a számkivetésből valóktól: Heldaitól, Tóbiástól és Jedajától; és menj be azon a napon, menj be Jósiának, a Sefániás fiának házába, a kik Babilonból jöttenek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 11, 'Végy ugyanis ezüstöt és aranyat, és csinálj koronákat, és tedd Jósuának, a Jehosadák fiának, a főpapnak fejére!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 12, 'És szólj néki, mondván: Ezt mondja a Seregeknek Ura, mondván: Ímé, egy férfiú, a neve Csemete, mert csemete támad belőle, és megépíti az Úrnak templomát!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 13, 'Mert ő fogja megépíteni az Úrnak templomát, és nagy lesz az ő dicsősége, és ülni és uralkodni fog az ő székében, és pap is lesz az ő székében, és békesség tanácsa lesz kettőjük között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 14, 'És a koronák legyenek Hélemnek, Tóbiásnak, Jedajának és Hénnek, a Sefániás fiának emlékjelei az Úr templomában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 15, 'És a messzelakók eljőnek és építenek az Úr templomában, és megtudjátok, hogy a Seregeknek Ura küldött el engem hozzátok. Így lesz, ha hallgattok az Úrnak, a ti Isteneteknek szavára!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 1, 'És lőn a Dárius király negyedik esztendejében, hogy szóla az Úr Zakariáshoz a kilenczedik hónapnak, a Kiszlévnek negyedikén,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 2, 'Mikor elküldék az Isten házába Saréczert és Régem-Méleket és társait, hogy esedezzenek az Úr színe előtt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 3, 'És hogy megkérdezzék a papokat, a kik a Seregek Urának házában vannak, és megkérdezzék a prófétákat is: Sírjak-é az ötödik hónapban és bőjtöljek-é, a mint cselekedtem azt néhány esztendő óta?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 4, 'Szóla ekkor a Seregeknek Ura nékem, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 5, 'Szólj az ország minden népének és a papoknak, mondván: Mikor bőjtöltetek és gyászoltatok az ötödik és hetedik hónapban, és pedig hetven esztendeig: avagy bőjtölvén, nékem bőjtöltetek-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 6, 'És mikor ettetek, és mikor ittatok: avagy nem magatoknak ettetek és magatoknak ittatok-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 7, 'Avagy nem ezek a beszédek-é azok, a melyeket szólott vala az Úr az előbbi próféták által, mikor még Jeruzsálem népes és gazdag vala a körülte levő városokkal együtt, és mind a déli táj, mind a lapály-föld népes vala?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 8, 'És szóla az Úr Zakariásnak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 9, 'Így szólt a Seregeknek Ura, mondván: Igaz ítélettel ítéljetek, és irgalmasságot és könyörületességet gyakoroljon kiki az ő felebarátjával!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 10, 'Özvegyet és árvát, jövevényt és szegényt meg ne sarczoljatok, és egymás ellen még szívetekben se gondoljatok gonoszt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 11, 'De nem akarák meghallani, sőt vállaikat vonogaták, és bedugák füleiket, hogy ne halljanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 12, 'Szívöket is megkeményíték, hogy ne hallják a törvényt és az igéket, a melyeket a Seregeknek Ura küldött vala az ő lelke által, az elébbi próféták által. És igen felgerjedt vala a Seregeknek Ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 13, 'És lőn, hogy a mint én kiáltottam és nem hallották meg: úgy kiáltottak, de nem hallottam meg, azt mondja a Seregeknek Ura;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 14, 'Hanem szétszórtam őket mindenféle nemzetek közé, a kik nem ismerték őket, és puszta lőn utánok a föld, hogy senki azon sem át nem megy, sem meg nem tér. Így tevék pusztává a kívánatos földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 1, 'Majd szóla a Seregeknek Ura, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 2, 'Ezt mondja a Seregeknek Ura: Nagy gerjedezéssel gerjedeztem a Sionért, és nagy haragra gerjedtem ellene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 3, 'Ezt mondja az Úr: Megtértem a Sionhoz, és Jeruzsálem közepette lakozom, és Jeruzsálem igazság városának neveztetik, a Seregek Urának hegye pedig szent hegynek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 4, 'Ezt mondja a Seregeknek Ura: Agg férfiak és agg nők ülnek majd Jeruzsálem utczáin, és kinek-kinek pálcza lesz kezében a napok sokasága miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 5, 'És megtelnek a város utczái fiúkkal és leányokkal, a kik játszadoznak annak utczáin.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 6, 'Ezt mondja a Seregeknek Ura: Ha ez csoda lészen e nép maradékának szemei előtt azokban a napokban, vajjon az én szemeim előtt is csoda lészen-é? így szól a Seregeknek Ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 7, 'Ezt mondja a Seregeknek Ura: Ímé, én megszabadítom az én népemet a nap keltének földéről és a nap nyugtának földéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 8, 'És elhozom őket és Jeruzsálemben lakoznak, és népemmé lesznek, én pedig Istenökké leszek hűséggel és igazsággal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 9, 'Ezt mondja a Seregeknek Ura: Erősödjenek meg kezeitek, a kik hallottátok e napokban e beszédeket a próféták szájából, a kik szóltak, mikor megvetteték a Seregek Ura házának alapja, hogy megépíttessék a templom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 10, 'Mert e napok előtt nem volt az embernek bére, és a baromnak sem volt bére, sem a kimenőnek, sem a bejövőnek nem volt békessége a háborúság miatt, mert minden embert felindítottam: kit-kit az ő felebarátja ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 11, 'De most nem olyan leszek e nép maradékához, mint az elébbi napokban voltam, így szól a Seregeknek Ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 12, 'Mert a vetés békességes lészen, a szőlőtő megadja gyümölcsét, a föld is megadja termését, az egek is megadják harmatjokat, és örökössé teszem mindezeken e nép maradékát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 13, 'És lészen, hogy a miképen átok valátok a pogányok között, oh Júda háza és Izráel háza: azonképen megszabadítlak titeket, és áldássá lesztek. Ne féljetek! Erősödjenek meg kezeitek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 14, 'Mert ezt mondja a Seregeknek Ura: A miképen elgondoltam vala, hogy veszedelmet hozok reátok, mikor atyáitok megharagítottak vala engem, így szól a Seregeknek Ura, és nem könyörültem:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 15, 'Azonképen megtértem és elgondoltam e napokban, hogy jót teszek Jeruzsálemmel és Júda házával; ne féljetek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 16, 'Ezek azok a dolgok, a melyeket cselekedjetek: Igazságot szóljon ki-ki az ő felebarátjával: igazságos és békességes ítélettel ítéljetek a ti kapuitokban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 17, 'És senki ne gondoljon az ő szívében gonoszt az ő felebarátja ellen; s a hamis esküvést se szeressétek, mert ezek azok, a miket én mind gyűlölök, így szól az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 18, 'Majd szóla hozzám a Seregeknek Ura, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 19, 'Ezt mondja a Seregeknek Ura: A negyedik hónapnak bőjtje, az ötödiknek bőjtje, a hetediknek bőjtje és a tizediknek bőjtje vígalommá, örvendezéssé és kedves ünnepekké lesznek Júda házában. Csak a hűséget és a békességet szeressétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 20, 'Ezt mondja a Seregeknek Ura: Még lesz idő, a mikor népek jőnek el, és sok városoknak lakói.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 21, 'És egyiknek lakói a másikhoz mennek, mondván: Menten menjünk el az Úr orczájának engesztelésére, és a Seregek Urának keresésére; én is elmegyek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 22, 'És eljőnek sok népek és erős nemzetek Jeruzsálembe a Seregek Urának keresésére, és az Úr orczájának engesztelésére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 23, 'Ezt mondja a Seregeknek Ura: E napokban lesz az, hogy a minden nyelvű pogányok közül tíz ember ragad egy zsidó férfiúba s ragad annak ruhája szélébe, mondván: Hadd menjünk veletek, mert hallottuk, hogy veletek van az Isten!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 1, 'Az Úr igéjének terhe a Kadrák földe ellen; Damaskus lesz pedig annak nyugvóhelye (mert az Úr szemmel tartja az embereket és Izráelnek minden törzsét);');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 2, 'És Hámát is, a mely szomszédos vele; Tírus és Sídon, noha igen okosak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 3, 'Várat épített magának Tírus, és annyi az ezüstje rakáson, mint a por, és az aranya, mint az utczák sara.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 4, 'Ímé szegénynyé teszi őt az Úr, és megrontja hatalmát a tengeren, magát pedig tűz emészti meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 5, 'Meglátja ezt Askalon és megretten; Gáza is és igen bánkódik; Ekron is, mert megszégyenült reménységében. Mert kivész a király Gázából, és Askalon lakatlan marad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 6, 'Asdódban pedig idegenek laknak, és a Filiszteusok kevélységét megtöröm.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 7, 'Kivonszom a vért szájukból és útálatosságaikat fogaik közül, és ő is a mi Istenünké marad; és olyan lesz, mint egy fejedelem Júdában, Ekron pedig, mint a Jebuzeus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 8, 'És tábort járok házam körül, mint a sereg ellen, az ide-oda kóborlók ellen, és nem megy át többé rajtok a sarczoló, mert most szemmel tartom őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 9, 'Örülj nagyon, Sionnak leánya, örvendezz, Jeruzsálem leánya! Ímé, jön néked a te királyod; igaz és szabadító ő; szegény és szamárháton ülő, azaz nőstényszamárnak vemhén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 10, 'És kivesztem a szekeret Efraimból és a lovat Jeruzsálemből, kivesztem a harczi kézívet is, és békességet hirdet a pogányoknak; és uralkodik tengertől tengerig, és a folyamtól a föld határáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 11, 'Sőt a veled való szövetségnek véréért a te foglyaidat is kibocsátom a kútból, a melyben nincs víz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 12, 'Térjetek vissza az erősséghez, reménységnek foglyai! Ma is azt hirdetem néktek: kétszeresen megfizetek néked!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 13, 'Mert kifeszítem Júdát magamnak mintegy kézívet és megtöltöm Efraimot; és felindítom fiaidat, oh Sion, a te fiaid ellen, oh Jáván, és olyanná teszlek, mint a hős fegyvere.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 14, 'És megjelen felettök az Úr, és nyila repül mint a villámlás; az Úr Isten kürtöt fuvall, és déli szelekben nyomul elő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 15, 'A Seregeknek Ura megoltalmazza őket; megemésztik és letapossák a parittya-köveket, és isznak és zajongnak, mint a bortól, és megtelnek, mint a csészék és mint az oltár szegletei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 16, 'És megsegíti őket az Úr, az ő Istenök ama napon, mint az ő népének nyáját, és mint korona-kövek ragyognak az ő földén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 17, 'Oh, mily nagy az ő jósága és mily nagy az ő kedvessége! Ifjakat tesz virágzóvá a gabona, és leányokat a must.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 1, 'Kérjetek esőt az Úrtól a késői eső idején! Az Úr villámlást szerez, és záporesőt ad nékik, és kinek-kinek füvet a mezőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 2, 'Mert a bálványok hazugságot szólnak, a varázslók pedig hamisságot látnak és üres álmokat beszélnek, hiábavalósággal vígasztalnak; azért elszélednek, mint a juhnyáj, a mely sanyarog, mert nincs pásztora.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 3, 'Haragra gerjedtem a pásztorok ellen, és megfenyítem a bakokat. Bizony megfenyíti a Seregeknek Ura az ő nyáját, a Júda házát, és olyanokká teszi őket, a milyen a harczra felékesített ló.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 4, 'Közülök támad a szegletkő, közülök a szeg, közülök a harczi ív, közülök egyszersmind minden sarczoló.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 5, 'És olyanok lesznek, mint a hősök, a kik az utczák sarát tapodják a harczban, és harczolnak, mert velök van az Úr, és megszégyenítik a lovon ülőket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 6, 'És megerősítem a Júda házát, és a József házát megsegítem, és visszahozom őket, mert szánom őket, és olyanokká lesznek, mintha el sem vetettem volna őket; mert én vagyok az Úr, az ő Istenök, és meghallgatom őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 7, 'Efraim is olyan lesz, mint egy hős, és örvendeznek majd mintegy bortól ittasodva, és látják fiaik és örvendeznek; örvend az ő szívök az Úrban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 8, 'Süvöltök nékik és egybegyűjtöm őket, mert megszabadítom őket, és megsokasulnak, a mint megsokasultak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 9, 'És széthintem őket a népek között, hogy a messze földeken is emlegessenek engem, és fiakat neveljenek és visszatérjenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 10, 'Mert visszatérítem őket, Égyiptom földéről, Assiriából is összegyűjtöm őket, és behozom őket Gileád és Libánon földjére, és elég sem lesz nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 11, 'És átvonulnak a nyomor tengerén, és megveri a tenger hullámait, és kiszáradnak a folyam örvényei, letöretik Assiriának kevélysége, és Égyiptom királyi pálczája elvész.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 12, 'És megerősítem őket az Úrban, és az ő nevében járnak, így szól az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 1, 'Nyisd meg kapuidat, oh Libánon, hogy tűz emészszen czédrusaid közt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 2, 'Jajgass te cziprus, mert esik a czédrus, leomlott, a mi legjava! Jajgassatok ti Básán tölgyei, mert pusztul a rengeteg erdő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 3, 'Hangzik a pásztorok jajja, mert elpusztult az ő büszkeségök! Hangzik az oroszlán ordítása, mert elpusztult a Jordán kevélysége!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 4, 'Ezt mondja az Úr, az én Istenem: Legeltesd a leölésre szánt juhokat,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 5, 'A melyeket leölnek az ő tulajdonosaik, a nélkül, hogy bűnnek tartanák, eladóik pedig ezt mondják: Áldott az Úr, mert meggazdagodtam! és pásztoraik sem kimélik őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 6, 'Bizony nem kimélem többé e föld lakosait, ezt mondja az Úr; sőt ímé odaadok minden embert a felebarátja kezébe és az ő királya kezébe, és megrontják e földet, és nem szabadítom ki kezökből!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 7, 'Legeltetém hát a leölésre szánt juhokat, azaz a megnyomorgatott juhokat, és választék magamnak két pálczát, az egyiket nevezém szépségnek, a másikat nevezém egyességnek; így legeltetém a juhokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 8, 'És három pásztort vertem el egy hónap alatt, mert elkeseredék a lelkem miattok, és az ő lelkök is megútála engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 9, 'És mondám: Nem őrizlek én titeket, haljon meg a halálra való és vágattassék ki a kivágni való, a megmaradottak pedig egyék meg egymásnak húsát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 10, 'És vevém egyik pálczámat, a szépséget, és eltörém azt, hogy felbontsam az én szövetségemet, a melyet az összes népekkel kötöttem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 11, 'És felbomla az azon a napon, és így tudták meg az elsanyargatott juhok, a kik ragaszkodnak vala hozzám, hogy az Úr dolga ez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 12, 'És mondám nékik: Ha jónak tetszik néktek, adjátok meg az én béremet; ha pedig nem: hagyjátok abba! És harmincz ezüst pénzt fizettek béremül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 13, 'És monda az Úr nékem: Vesd a fazekas elé! Nagy jutalom, a melyre becsültek engem. Vevém azért a harmincz ezüst pénzt, és vetém azt az Úrnak házába, a fazekas elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 14, 'Majd eltörém a másik pálczámat is, az egyességet, hogy felbontsam a testvérséget Júda között és Izráel között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 15, 'És mondá az Úr nékem: Most már szerezz magadnak bolond pásztornak való szerszámot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 16, 'Mert ímé, én pásztort állítok e földre, a ki az elveszetteket meg nem keresi, a gyöngével nem törődik, a megtépettet meg nem gyógyítja, a jó karban levőt nem táplálja, a kövérinek húsát megeszi, és körmeiket széttördeli.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 17, 'Jaj a mihaszna pásztornak, a ki elhagyja a juhokat! Fegyver a karjára és jobb szemére. Karja szárazra száradjon és jobb szeme sötétre sötétedjék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 1, 'Az Úr igéjének terhe Izráel ellen. Így szól az Úr, a ki az egeket kiterjesztette, a földet fundálta, és az ember keblébe lelket alkotott:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 2, 'Ímé, én részegítő pohárrá teszem Jeruzsálemet minden körülte való népnek; Júdának is az lesz, mikor ostromolják Jeruzsálemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 3, 'És azon a napon lesz, hogy nyomtatókővé teszem Jeruzsálemet minden népnek; a ki emelni akarja azt, mind szakadva-szakad meg, noha összegyül ellene a föld minden pogánya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 4, 'Azon a napon, így szól az Úr, megverek minden lovat rettegéssel, a lovagját pedig őrültséggel; de a Júda házát nyitott szemmel nézem, a népeknek pedig minden lovát vaksággal verem meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 5, 'És azt mondják szívökben Júda fejedelmei: Az én erősségem Jeruzsálemnek lakói, az ő Istenökkel, a Seregek Urával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 6, 'Azon a napon olyanokká teszem Júda fejedelmeit, mint a milyen a tüzes serpenyő a fák között, és a milyen a tüzes fáklya a kévék között: megemésztenek jobb és bal felől minden körülvaló népet; de Jeruzsálem tovább is a helyén marad Jeruzsálemben!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 7, 'És megoltalmazza az Úr Júdának sátrait, mint azelőtt, hogy ne legyen nagyobb Dávid házának dicsősége és Jeruzsálem lakosának dicsősége, mint a Júdáé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 8, 'Azon a napon oltalma lészen az Úr Jeruzsálem lakosának, és azon a napon olyan lesz köztök a legalábbvaló, mint Dávid, a Dávid háza pedig, mint az Isten, mint az Úrnak angyala ő előttök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 9, 'És azon a napon lesz, hogy kész leszek elveszteni minden pogányt, a kik Jeruzsálemre támadnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 10, 'A Dávid házára és Jeruzsálem lakosaira pedig kiöntöm a kegyelemnek és könyörületességnek lelkét, és reám tekintenek, a kit átszegeztek, és siratják őt, a mint siratják az egyetlen fiút, és keseregnek utána, a mint keseregnek az elsőszülött után.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 11, 'Azon a napon nagy siralom lesz Jeruzsálemben, a milyen volt a hadadrimmoni siralom a Megiddo völgyében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 12, 'És sír a föld: nemzetségek és nemzetségek külön; külön a Dávid házának nemzetsége, feleségeik is külön; külön a Nátán házának nemzetsége, és feleségeik is külön;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 13, 'Külön a Lévi házának nemzetsége, és feleségeik is külön; külön a Sémei nemzetsége, feleségeik is külön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 14, 'A többi nemzetségek mind; nemzetségek és nemzetségek külön, feleségeik is külön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 1, 'Azon a napon kútfő fakad a Dávid házának és Jeruzsálem lakosainak a bűn és tisztátalanság ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 2, 'És lészen azon a napon, így szól a Seregeknek Ura: Kivesztem a bálványok neveit e földről, és emlegetni sem fogják többé; sőt a prófétákat és a fertelmes lelket is kiszaggatom e földről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 3, 'És úgy lesz, ha prófétálni fog még valaki, azt mondják annak az ő apja és anyja, az ő szülői: Ne élj, mert hazugságot szóltál az Úr nevében! És általverik őt az ő apja és anyja, az ő szülői, az ő prófétálása közben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 4, 'És azon a napon megszégyenülnek a próféták, kiki az ő látása miatt az ő prófétálásaik közben, és nem öltözködnek szőrös ruhába, hogy hazudjanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 5, 'Hanem ezt mondja kiki: Nem vagyok én próféta, szántóvető ember vagyok én, sőt más szolgájává lettem én gyermekségem óta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 6, 'És ha mondja néki valaki: Micsoda ütések ezek a kezeiden? azt mondja: A miket az én barátaim házában ütöttek rajtam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 7, 'Fegyver, serkenj fel az én pásztorom ellen és a férfiú ellen, a ki nékem társam! így szól a Seregeknek Ura. Verd meg a pásztort és elszélednek a juhok, én pedig a kicsinyek ellen fordítom kezemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 8, 'És lészen az egész földön, így szól az Úr: a két rész kivágattatik azon és meghal, de a harmadik megmarad rajta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 9, 'És beviszem a harmadrészt a tűzbe, és megtisztítom őket, a mint tisztítják az ezüstöt és megpróbálom őket, a mint próbálják az aranyat; ő segítségül hívja az én nevemet és én felelni fogok néki; ezt mondom: Népem ő! Ő pedig ezt mondja: Az Úr az én Istenem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 1, 'Ímé, eljön az Úrnak napja, és a te prédádat felosztják benned.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 2, 'Mert minden népet ütközetre gyűjtök Jeruzsálemhez, és megszállják a várost, és kirabolják a házakat, megszeplősítik az asszonyokat; és a város fele számkivetésbe megy, de a nép maradéka nem gyomláltatik ki a városból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 3, 'Mert eljön az Úr, és harczol azok ellen a népek ellen, a mint harczolt vala ama napon, a harcznak napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 4, 'És azon a napon az Olajfák hegyére veti lábait, a mely szemben van Jeruzsálemmel napkelet felől, és az Olajfák hegye közepén ketté válik, kelet felé és nyugot felé, igen nagy völgygyé, és a hegynek fele észak felé, fele pedig dél felé szakad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 5, 'És az én hegyem völgyébe futtok, mert a hegyközi völgy Azálig nyúlik, és úgy futtok, a mint futottatok a földindulás elől Uzziásnak, Júda királyának napjaiban. Bizony eljő az Úr, az én Istenem, és minden szent vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 6, 'És úgy lesz azon a napon: Nem lesz világosság, a ragyogó testek összezsugorodnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 7, 'De lesz egy nap, a melyet az Úr tud, se nappal, se éjszaka, és világosság lesz az estvének idején.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 8, 'És e napon lesz, hogy élő vizek jőnek ki Jeruzsálemből, felerészök a napkeleti tenger felé, felerészök pedig a nyugoti tenger felé, és nyárban és télben is úgy lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 9, 'És az Úr lesz az egész földnek királya, e napon egy Úr lészen, és a neve is egy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 10, 'Az egész föld síksággá változik Gebától kezdve Rimmonig, déli irányban Jeruzsálem felé, és felmagasztaltatik és a maga helyén marad a Benjámin kapujától az első kapu helyéig, a szegletkapuig, és a Hananéel tornyától a király sajtójáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 11, 'És lakni fognak benne, és nem éri többé pusztulás, és bátorságban lakoznak Jeruzsálemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 12, 'És ez lesz a csapás, a melylyel megcsapkod az Úr minden népet, a melyek Jeruzsálem ellen gyülekeznek: Megsenyved a húsok és pedig a míg lábaikon állnak, szemeik is megsenyvednek gödreikben, nyelvök is megsenyved szájokban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 13, 'És azon a napon lesz, hogy az Úr nagy háborúságot támaszt közöttök, úgy, hogy kiki a maga társának kezét ragadja meg, és a maga társának keze ellen emeli fel kezét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 14, 'Sőt még Júda is harczolni fog Jeruzsálem ellen, és összegyűjtetik a köröskörül lakó népek minden gazdagsága: arany, ezüst és igen sok ruha.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 15, 'És éppen olyan csapás lesz a lovakon, öszvéreken, tevéken, szamarakon és mindenféle barmokon, a melyek e táborban lesznek, a milyen ez a csapás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 16, 'És lészen, hogy a kik megmaradnak mindama népek közül, a melyek Jeruzsálem ellen jőnek: esztendőről esztendőre mind felmennek, hogy hódoljanak a királynak, a Seregek Urának, és megünnepeljék a sátorok ünnepét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 17, 'És lészen, hogy a ki nem megy fel e föld nemzetségei közül Jeruzsálembe, hogy hódoljon a királynak, a Seregek Urának: nem lészen azokra eső.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 18, 'És ha nem megy fel, vagy nem jön fel az égyiptomi nemzetség, ő rájok sem lészen; de lészen az a csapás, a melylyel megcsapkodja az Úr a népeket, a kik nem mennek fel a sátorok ünnepét megünnepelni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 19, 'Ez lészen Égyiptomnak büntetése, és mindama népek büntetése, a kik nem mennek fel a sátorok ünnepét megünnepelni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 20, 'Azon a napon a lovak csengettyűin is ez lesz: Az Úrnak szenteltetett. És a fazekak az Úrnak házában olyanokká lesznek, mint az oltár előtt való medenczék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 21, 'És Jeruzsálemben és Júdában minden fazék a Seregek Urának szenteltetik, és eljőnek mind, a kik áldozni akarnak, és választanak közülök és főznek azokban; és nem lészen többé Kananeus a Seregek Urának házában e napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'Az Úr igéjének terhe Izráel ellen, Malakiás által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, 'Szerettelek titeket, azt mondja az Úr, és azt mondjátok: Miben szerettél minket? Avagy nem atyjafia vala-é Ézsau Jákóbnak? azt mondja az Úr: Jákóbot pedig szerettem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'Ézsaut ellenben gyűlöltem, és az ő hegyeit pusztává tettem, örökségét pedig pusztai sakálokévá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'Ha azt mondja Edom: Elpusztultunk; de térjünk meg és építsük fel a romladékokat: ezt mondja a Seregeknek Ura: Ők építenek, de én elrontom, és elnevezik őket istentelenség határának és oly népnek, a melyre örökké haragszik az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, 'És látják ezt a ti szemeitek, és magatok is mondjátok: Nagy az Úr az Izráel határa felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, 'A fiú tiszteli atyját, a szolga is az ő urát. És ha én atya vagyok: hol az én tisztességem? És ha én úr vagyok, hol az én félelmem? azt mondja a Seregeknek Ura néktek, ti papok, a kik útáljátok az én nevemet, és ezt mondjátok: Mivel útáljuk a te nevedet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, 'Megfertéztetett kenyeret hoztok oltáromra, és azt mondjátok: Mivel fertéztetünk meg téged? Azzal, mikor azt gondoljátok, hogy az Úrnak asztala megvetni való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, 'Hogyha vakot hoztok áldozatul: Nem bűn-é az? vagy ha sántát hoztok és bénát: nem bűn-é az? Vidd csak azt a te fejedelmednek: vajjon kedvvel fogad-é, avagy reád tekint-é? azt mondja a Seregeknek Ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, 'Most azért engeszteljétek meg az Istennek orczáját, hogy könyörüljön rajtunk. Általatok van ez, elnézheti-é ezt néktek? azt mondja a Seregeknek Ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, 'Vajha valaki közületek bezárná az ajtót, hiába ne tüzelnétek az én oltáromon! Nem telik kedvem bennetek, azt mondja a Seregeknek Ura; az ételáldozatot sem kedvelem a ti kezetekből!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, 'Hiszen napkelettől fogva napnyugotig nagy az én nevem a pogányok között, és minden helyen tömjénnel áldoznak az én nevemnek és tiszta ételáldozattal! Bizony nagy az én nevem a pogányok között! azt mondja a Seregeknek Ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, 'Ti pedig meggyalázzátok azt, mikor azt mondjátok: Az Úrnak asztala megvetni való, és annak jövedelme, eledele útálatos.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, 'És azt mondjátok: Ímé, mily fáradság! és ráfújtok, azt mondja a Seregeknek Ura; pedig a rablottat hozzátok, meg a sántát és betegest; ételáldozatot is hoztok, de hát kedves-é az a ti kezetekből? azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, 'Átkozott pedig az álnok! Van ugyan a nyájában hím, és fogadást is tesz: mégis hitványnyal áldozik az Úrnak. Pedig nagy király vagyok én, azt mondja a Seregeknek Ura, és félelmetes az én nevem a pogányok között!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, 'Most azért néktek szól ez a parancsolat, ti papok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, 'Ha meg nem hallgatjátok és ha nem veszitek szívetekre, hogy dicsőséget adjatok az én nevemnek, azt mondja a Seregeknek Ura: átkot bocsátok reátok, és elátkozom a ti áldásotokat; bizony elátkozom azt, ha nem veszitek szívetekre!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, 'Ímé, én megrontom a ti vetni való magotokat, és szemetet szórok orczáitokba, a ti ünneplésteknek szemetjét, és ahhoz hordanak ki titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'És megtudjátok, hogy azért adtam néktek e parancsolatot, hogy szövetségem legyen a Lévivel, azt mondja a Seregeknek Ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, 'Szövetségem volt vele életre és békességre, és félelmül adtam azt néki és félt engemet, és megalázta magát az én nevem előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, 'Igazság törvénye volt az ő szájában, és nem találtatott álnokság az ő ajkaiban; békességben és egyenességgel járt velem, és sokakat megtérített a bűnből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, 'Mert a papnak ajkai őrzik a tudományt, és az ő szájából törvényt várnak, mivel a Seregek Urának követe ő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'De ti elhajlottatok ez útról, sokakat megbotránkoztattatok a törvénnyel, felbontottátok Lévi szövetségét, azt mondja a Seregeknek Ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, 'Azért én is szidalmasakká tettelek titeket és útálatosakká az egész nép előtt, a miatt, hogy meg nem őriztétek az én útamat, hanem személyválogatók voltatok a törvénnyel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, 'Nem egy atyánk van-é mindnyájunknak? Nem egy Isten teremtett-é minket? Miért csalja hát kiki az ő felebarátját, megrontván a mi atyáink szövetségét?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'Hűtelenné lett Júda, és útálatosság támadt Izráelben és Jeruzsálemben, mert megfertőztette Júda az Úrnak szentségét, a melyet ő szeret, és idegen istennek leányát vette el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 12, 'Elveszt az Úr mindenkit, a ki ezt cselekszi, a vigyázót és a felelőt, a Jákób sátraiból, még ha áldozatot visz is a Seregek Urának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 13, 'És ezt is cselekszitek: betöltitek az Úr oltárát könyhullatással, sírással és kesergéssel, hogy ne tekintsen többé az ételáldozatra, és ne fogadjon el szívességet a ti kezetekből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 14, 'És azt mondjátok: Miért? Azért, mert az Úr tett bizonyságot közted és a te ifjúságod felesége közt, a kit te megcsaltál, holott társad és szövetséges feleséged!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 15, 'Nem tett ilyet egy sem, a kinek még volt lelke. És mit keresett az az egy? Istentől való magvat. Őrizzétek meg azért a ti lelketeket, és a ti ifjúságotok feleségét meg ne csaljátok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 16, 'Mert gyűlölöm az elbocsátást, ezt mondja az Úr, Izráelnek Istene, és azt, a ki ruhájára kegyetlenséget borít, azt mondja a Seregeknek Ura. Őrizzétek meg azért lelketeket és ne csalárdkodjatok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 17, 'Elfárasztottátok az Urat beszédeitekkel, és azt mondjátok: Mivel fárasztottuk el? Azzal, hogy azt mondjátok: Minden gonosztevő jó az Úr szemeiben, és gyönyörködik ő azokban; vagy: Hol van az ítéletnek Istene?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, 'Ímé, elküldöm én az én követemet, és megtisztítja előttem az útat, és mindjárt eljön az ő templomába az Úr, a kit ti kerestek, és a szövetségnek követe, a kit ti kívántok; ímé, eljön, azt mondja a Seregeknek Ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, 'De kicsoda szenvedheti el az ő eljövetelének napját? És kicsoda áll meg az ő megjelenésekor? Hiszen olyan ő, mint az ötvösnek tüze, és a ruhamosóknak lúgja!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'És ül mint ötvös vagy ezüsttisztogató és megtisztítja Lévi fiait és fényessé teszi őket, mint az aranyat és ezüstöt; és igazsággal visznek ételáldozatot az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'És kedves lesz az Úrnak a Júda és Jeruzsálem ételáldozatja, mint a régi napokban és előbbi esztendőkben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, 'Mert ítéletre indulok hozzátok, és gyors tanú leszek a szemfényvesztők ellen, a paráznák és hamisan esküvők ellen, és azok ellen, a kik megrövidítik a munkásnak bérét, az özvegyet és árvát, és a kik nyomorgatják az idegent, és nem félnek engem, azt mondja a Seregeknek Ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, 'Mert én, az Úr, meg nem változom, ti pedig, Jákóbnak fiai, nem emésztettek meg!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'Atyáitok idejétől fogva eltértetek rendeléseimtől és nem tartottátok meg azokat. Térjetek hozzám, és én is hozzátok térek, azt mondja a Seregeknek Ura. De azt mondjátok: Miben térjünk meg?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'Avagy az ember csalhatja-é az Istent? ti mégis csaltatok engem. És azt mondjátok: Mivel csalunk téged? A tizeddel és az áldozni valóval.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, 'Átokkal vagytok elátkozva, mégis csaltok engem: a nép egészben!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'Hozzátok be a tizedet mind az én tárházamba, hogy legyen ennivaló az én házamban, és ezzel próbáljatok meg engem, azt mondja a Seregeknek Ura, ha nem nyitom meg néktek az egek csatornáit, és ha nem árasztok reátok áldást bőségesen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 11, 'És megdorgálom érettetek a kártevőt, és nem veszti el földetek gyümölcsét, és nem lesz a szőlőtök meddő a mezőn, azt mondja a Seregeknek Ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 12, 'És boldognak mondanak titeket mind a nemzetek; mert kívánatos földdé lesztek ti, azt mondja a Seregeknek Ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 13, 'Keményen szóltatok ellenem, azt mondja az Úr, és azt mondjátok: Mit szóltunk ellened?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 14, 'Azt mondtátok: Hiábavaló az Isten szolgálata, és mi haszna, hogy megtartjuk törvényeit, és hogy alázatosan járunk a Seregeknek Ura előtt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 15, 'Sőt inkább magunk hirdetjük boldogoknak a kevélyeket; hiszen gyarapodtak, noha gonoszságot űznek, és megszabadulnak, noha kisértik az Istent!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 16, 'Akkor tanakodtak egymással az Úrnak tisztelői, az Úr pedig figyelt és hallgatott, és egy emlékkönyv iraték ő előtte azoknak, a kik félik az Urat és becsülik az ő nevét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 17, 'És azon a napon, azt mondja a Seregeknek Ura, a melyet én szerzek, tulajdonommá lesznek és kedvezek nékik, a mint kiki kedvez a maga fiának, a ki szolgálja őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 18, 'És megtértek és meglátjátok, hogy különbség van az igaz és a gonosz között, az Isten szolgája között és a között, a ki nem szolgálja őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 1, 'Mert ímé, eljön a nap, lángoló, mint a sütő-kemencze, és olyanná lesz minden kevély és minden gonosztevő, mint a pozdorja, és megégeti őket az eljövendő nap, azt mondja a Seregeknek Ura, a mely nem hagy rajtok gyökeret, sem ágat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 2, 'És feltámad néktek, a kik félitek az én nevemet, az igazságnak napja, és gyógyulás lesz az ő szárnyai alatt, és kimentek és ugrándoztok, mint a hízlalt tulkok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 3, 'És széttapodjátok a gonoszokat, és porrá lesznek lábaitok nyomása alatt azon a napon, a melyet én szerzek, azt mondja a Seregeknek Ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 4, 'Emlékezzetek meg Mózesnek, az én szolgámnak törvényéről, a melyet rendeltem ő általa a Hóreben, az egész Izráelnek rendelésekül és ítéletekül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 5, 'Ímé, én elküldöm néktek Illyést, a prófétát, mielőtt eljön az Úrnak nagy és félelmetes napja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 6, 'És az atyák szívét a fiakhoz fordítja, a fiak szívét pedig az atyákhoz, hogy el ne jőjjek és meg ne verjem e földet átokkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Jézus Krisztusnak, Dávid fiának, Ábrahám fiának nemzetségéről való könyv.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Ábrahám nemzé Izsákot; Izsák nemzé Jákóbot; Jákób nemzé Júdát és testvéreit;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'Júda nemzé Fárest és Zárát Támártól; Fáres nemzé Esromot; Esrom nemzé Arámot;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'Arám nemzé Aminádábot; Aminádáb nemzé Naássont; Naásson nemzé Sálmónt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'Sálmón nemzé Boázt Ráhábtól; Boáz nemzé Obedet Ruthtól; Obed nemzé Isait;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'Isai nemzé Dávid királyt; Dávid király nemzé Salamont az Uriás feleségétől;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'Salamon nemzé Roboámot; Roboám nemzé Abiját; Abija nemzé Asát;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'Asa nemzé Josafátot; Josafát nemzé Jórámot; Jórám nemzé Uzziást;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'Uzziás nemzé Jóathámot; Joathám nemzé Ákházt; Ákház nemzé Ezékiást;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'Ezékiás nemzé Manassét; Manassé nemzé Ámont; Ámon nemzé Jósiást;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'Jósiás nemzé Jekoniást és testvéreit a babilóni fogságra vitelkor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'A babilóni fogságravitel után pedig Jekoniás nemzé Saláthielt; Saláthiel nemzé Zorobábelt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'Zorobábel nemzé Abiudot; Abiud nemzé Eliákimot; Eliákim nemzé Azort;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'Azor nemzé Sádokot; Sádok nemzé Akimot; Akim nemzé Eliudot;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'Eliud nemzé Eleázárt; Eleázár nemzé Matthánt; Matthán nemzé Jákóbot;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'Jákób nemzé Józsefet, férjét Máriának, a kitől született Jézus, a ki Krisztusnak neveztetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'Az összes nemzetség tehát Ábrahámtól Dávidig tizennégy nemzetség, és Dávidtól a babilóni fogságravitelig tizennégy nemzetség, és a babilóni fogságraviteltől Krisztusig tizennégy nemzetség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'A Jézus Krisztus születése pedig így vala: Mária, az ő anyja, eljegyeztetvén Józsefnek, mielőtt egybekeltek volna, viselősnek találtaték a Szent Lélektől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, 'József pedig, az ő férje, mivelhogy igaz ember vala és nem akará őt gyalázatba keverni, el akarta őt titkon bocsátani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'Mikor pedig ezeket magában elgondolta: ímé az Úrnak angyala álomban megjelenék néki, mondván: József, Dávidnak fia, ne félj magadhoz venni Máriát, a te feleségedet, mert a mi benne fogantatott, a Szent Lélektől van az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'Szűl pedig fiat, és nevezd annak nevét Jézusnak, mert ő szabadítja meg az ő népét annak bűneiből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'Mindez pedig azért lőn, hogy beteljesedjék, a mit az Úr mondott volt a próféta által, a ki így szól:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 23, 'Ímé a szűz fogan méhében és szűl fiat, és annak nevét Immanuelnek nevezik, a mi azt jelenti: Velünk az Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 24, 'József pedig az álomból felserkenvén, úgy tőn, a mint az Úr angyala parancsolta vala néki, és feleségét magához vevé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 25, 'És nem ismeré őt, míg meg nem szülé az ő elsőszülött fiát; és nevezé annak nevét Jézusnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'A mikor pedig megszületik vala Jézus a júdeai Bethlehemben, Heródes király idejében, ímé napkeletről bölcsek jövének Jeruzsálembe, ezt mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, 'Hol van a zsidók királya, a ki megszületett? Mert láttuk az ő csillagát napkeleten, és azért jövénk, hogy tisztességet tegyünk néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'Heródes király pedig ezt hallván, megháborodék, és vele együtt az egész Jeruzsálem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'És egybegyűjtve minden főpapot és a nép írástudóit, tudakozódik vala tőlük, hol kell a Krisztusnak megszületnie?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'Azok pedig mondának néki: A júdeai Bethlehemben; mert így írta vala meg a próféta:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, 'És te Bethlehem, Júdának földje, semmiképen sem vagy legkisebb Júda fejedelmi városai között: mert belőled származik a fejedelem, a ki legeltetni fogja az én népemet, az Izráelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Ekkor Heródes titkon hivatván a bölcseket, szorgalmatosan megtudakolá tőlük a csillag megjelenésének idejét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'És elküldvén őket Bethlehembe, monda nékik: Elmenvén, szorgalmatosan kérdezősködjetek a gyermek felől, mihelyt pedig megtaláljátok, adjátok tudtomra, hogy én is elmenjek és tisztességet tegyek néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'Ők pedig a király beszédét meghallván, elindulának. És ímé a csillag, a melyet napkeleten láttak, előttük megy vala mind addig, a míg odaérvén, megálla a hely fölött, a hol a gyermek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'És mikor meglátták a csillagot, igen nagy örömmel örvendezének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'És bemenvén a házba, ott találák a gyermeket anyjával, Máriával; és leborulván, tisztességet tőnek néki; és kincseiket kitárván, ajándékokat adának néki: aranyat, tömjént és mirhát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'És mivel álomban meginttettek, hogy Heródeshez vissza ne menjenek, más úton térének vissza hazájokba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'Mikor pedig azok visszatérnek vala, ímé megjelenék az Úrnak angyala Józsefnek álomban, és monda: Kelj fel, vedd a gyermeket és annak anyját, és fuss Égyiptomba, és maradj ott, a míg én mondom néked; mert Heródes halálra fogja keresni a gyermeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'Ő pedig fölkelvén, vevé a gyermeket és annak anyját éjjel, és Égyiptomba távozék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'És ott vala egész a Heródes haláláig, hogy beteljesedjék, a mit az Úr mondott a próféta által, a ki így szólt: Égyiptomból hívtam ki az én fiamat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'Ekkor Heródes látván, hogy a bölcsek megcsúfolták őt, szerfölött felháborodék, és kiküldvén, megölete Bethlehemben és annak egész környékén minden gyermeket, két esztendőstől és azon alól, az idő szerint, a melyet szorgalmasan tudakolt a bölcsektől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'Ekkor teljesedék be, a mit Jeremiás próféta mondott, a midőn így szólt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, 'Szó hallatszott Rámában: Sírás-rívás és sok keserves jajgatás. Rákhel siratta az ő fiait és nem akart megvigasztaltatni, mert nincsenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, 'Mikor pedig Heródes meghalt, ímé az Úrnak angyala megjelenék álomban Józsefnek Égyiptomban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, 'Mondván: Kelj fel, vedd a gyermeket és annak anyját, és eredj az Izráel földére; mert meghaltak, a kik a gyermeket halálra keresik vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 21, 'Ő pedig felkelvén, magához vevé a gyermeket és annak anyját, és elméne Izráel földére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 22, 'Mikor pedig hallá, hogy Júdeában Arkhelaus uralkodik, Heródesnek, az ő atyjának helyén, nem mert vala oda menni, hanem minthogy álomban meginteték, Galilea vidékeire tére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 23, 'És oda jutván, lakozék Názáret nevű városban, hogy beteljesedjék, a mit a próféták mondottak, hogy názáretinek fog neveztetni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'Azokban a napokban pedig eljöve Keresztelő János, a ki prédikál vala Júdea pusztájában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, 'És ezt mondja vala: Térjetek meg, mert elközelített a mennyeknek országa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'Mert ez az, a kiről Ésaiás próféta szólott, ezt mondván: Kiáltó szó a pusztában: Készítsétek az Úrnak útját, és egyengessétek meg az ő ösvényeit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'Ennek a Jánosnak a ruhája pedig teveszőrből vala, és bőröv vala a dereka körül, elesége pedig sáska és erdei méz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Ekkor kiméne ő hozzá Jeruzsálem és az egész Júdea és a Jordánnak egész környéke.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'És megkeresztelkednek vala ő általa a Jordán vizében, vallást tevén az ő bűneikről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'Mikor pedig látá, hogy a farizeusok és sadduceusok közül sokan mennek ő hozzá, hogy megkeresztelkedjenek, monda nékik: Mérges kígyóknak fajzatai! Kicsoda intett meg titeket, hogy az Istennek elkövetkezendő haragjától megmeneküljetek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Teremjetek hát megtéréshez illő gyümölcsöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'És ne gondoljátok, hogy így szólhattok magatokban: Ábrahám a mi atyánk! Mert mondom néktek, hogy Isten eme kövekből is támaszthat fiakat Ábrahámnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'A fejsze pedig immár a fák gyökerére vettetett. Azért minden fa, a mely jó gyümölcsöt nem terem, kivágattatik és tűzre vettetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Én ugyan vízzel keresztellek titeket megtérésre, de a ki utánam jő, erősebb nálamnál, a kinek saruját hordozni sem vagyok méltó; ő Szent Lélekkel és tűzzel keresztel majd titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'A kinek szóró lapát van az ő kezében, és megtisztítja az ő szérűjét; és az ő gabonáját csűrbe takarítja, a polyvát pedig megégeti olthatatlan tűzzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'Akkor eljöve Jézus Galileából a Jordán mellé Jánoshoz, hogy megkeresztelkedjék ő általa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'János azonban visszatartja vala őt, mondván: Nékem kell általad megkeresztelkednem, és te jősz én hozzám?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'Jézus pedig felelvén, monda néki: Engedj most, mert így illik nékünk minden igazságot betöltenünk. Ekkor engede néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'És Jézus megkeresztelkedvén, azonnal kijöve a vízből; és ímé az egek megnyilatkozának néki, és ő látá az Istennek Lelkét alájőni mintegy galambot és ő reá szállani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'És ímé egy égi hang ezt mondja vala: Ez amaz én szerelmes fiam, a kiben én gyönyörködöm.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Akkor Jézus viteték a Lélektől a pusztába, hogy megkisértessék az ördögtől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'És mikor negyven nap és negyven éjjel bőjtölt vala, végre megéhezék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'És hozzámenvén a kisértő, monda néki: Ha Isten fia vagy, mondd, hogy e kövek változzanak kenyerekké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'Ő pedig felelvén, monda: Meg van írva: Nemcsak kenyérrel él az ember, hanem minden ígével, a mely Istennek szájából származik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'Ekkor vivé őt az ördög a szent városba, és odahelyezé a templom tetejére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, 'És monda néki: Ha Isten fia vagy, vesd alá magadat; mert meg van írva: Az ő angyalainak parancsol felőled, és kézen hordoznak téged, hogy meg ne üsd lábadat a kőbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'Monda néki Jézus: Viszont meg van írva: Ne kisértsd az Urat, a te Istenedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'Ismét vivé őt az ördög egy igen magas hegyre, és megmutatá néki a világ minden országát és azok dicsőségét,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, 'És monda néki: Mindezeket néked adom, ha leborulva imádsz engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Ekkor monda néki Jézus: Eredj el Sátán, mert meg van írva: Az Urat, a te Istenedet imádd, és csak néki szolgálj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'Ekkor elhagyá őt az ördög. És ímé angyalok jövének hozzá és szolgálnak vala néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'Mikor pedig meghallotta Jézus, hogy János börtönbe vettetett, visszatére Galileába;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'És odahagyva Názáretet, elméne és lakozék a tengerparti Kapernaumban, a Zebulon és Naftali határain;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'Hogy beteljesedjék, a mit Ésaiás próféta mondott, így szólván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, 'Zebulonnak földje és Naftalinak földje, a tenger felé, a Jordánon túl, a pogányok Galileája,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, 'A nép, a mely sötétségben ül vala, láta nagy világosságot, és a kik a halálnak földében és árnyékában ülnek vala, azoknak világosság támada.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'Ettől fogva kezde Jézus prédikálni, és ezt mondani: Térjetek meg, mert elközelgetett a mennyeknek országa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'Mikor pedig a galileai tenger mellett jár vala Jézus, láta két testvért, Simont, a kit Péternek neveznek, és Andrást az ő testvérét, a mint a tengerbe hálót vetnek vala; mert halászok valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'És monda nékik: Kövessetek engem, és azt mívelem, hogy embereket halásszatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'Azok pedig azonnal otthagyván a hálókat, követék őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, 'És onnan tovább menve, láta más két testvért, Jakabot a Zebedeus fiát, és Jánost amannak testvérét, a mint a hajóban atyjukkal Zebedeussal a hálóikat kötözgetik vala; és hívá őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 22, 'Azok pedig azonnal otthagyván a hajót és atyjukat, követék őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 23, 'És bejárá Jézus az egész Galileát, tanítva azok zsinagógáiban, és hirdetve az Isten országának evangyéliomát, és gyógyítva a nép között minden betegséget és minden erőtlenséget.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 24, 'És elterjede az ő híre egész Siriában: és hozzávivék mindazokat, a kik rosszul valának, a különféle betegségekben és kínokban sínlődőket, ördöngösöket, holdkórosokat és gutaütötteket; és meggyógyítja vala őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 25, 'És nagy sokaság követé őt Galileából és a Tízvárosból és Jeruzsálemből és Júdeából és a Jordánon túlról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'Mikor pedig látta Jézus a sokaságot, felméne a hegyre, és a mint leül vala, hozzámenének az ő tanítványai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'És megnyitván száját, tanítja vala őket, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, 'Boldogok a lelki szegények: mert övék a mennyeknek országa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, 'Boldogok, a kik sírnak: mert ők megvígasztaltatnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, 'Boldogok a szelídek: mert ők örökségül bírják a földet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, 'Boldogok, a kik éhezik és szomjúhozzák az igazságot: mert ők megelégíttetnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, 'Boldogok az irgalmasok: mert ők irgalmasságot nyernek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, 'Boldogok, a kiknek szívök tiszta: mert ők az Istent meglátják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, 'Boldogok a békességre igyekezők: mert ők az Isten fiainak mondatnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, 'Boldogok, a kik háborúságot szenvednek az igazságért: mert övék a mennyeknek országa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, 'Boldogok vagytok, ha szidalmaznak és háborgatnak titeket és minden gonosz hazugságot mondanak ellenetek én érettem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'Örüljetek és örvendezzetek, mert a ti jutalmatok bőséges a mennyekben: mert így háborgatták a prófétákat is, a kik előttetek voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, 'Ti vagytok a földnek savai; ha pedig a só megízetlenül, mivel sózzák meg? nem jó azután semmire, hanem hogy kidobják és eltapossák az emberek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'Ti vagytok a világ világossága. Nem rejtethetik el a hegyen épített város.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'Gyertyát sem azért gyújtanak, hogy a véka alá, hanem hogy a gyertyatartóba tegyék és fényljék mindazoknak, a kik a házban vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'Úgy fényljék a ti világosságtok az emberek előtt, hogy lássák a ti jó cselekedeteiteket, és dicsőítsék a ti mennyei Atyátokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, 'Ne gondoljátok, hogy jöttem a törvénynek vagy a prófétáknak eltörlésére. Nem jöttem, hogy eltöröljem, hanem inkább, hogy betöltsem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'Mert bizony mondom néktek, míg az ég és a föld elmúlik, a törvényből egy jóta vagy egyetlen pontocska el nem múlik, a míg minden be nem teljesedik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'Valaki azért csak egyet is megront e legkisebb parancsolatok közül és úgy tanítja az embereket, a mennyeknek országában a legkisebb lészen; valaki pedig cselekszi és úgy tanít, az a mennyeknek országában nagy lészen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'Mert mondom néktek, hogy ha a ti igazságotok nem több az írástudók és farizeusok igazságánál, semmiképen sem mehettek be a mennyeknek országába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, 'Hallottátok, hogy megmondatott a régieknek: Ne ölj, mert a ki öl, méltó az ítéletre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'Én pedig azt mondom néktek, hogy mindaz, a ki haragszik az ő atyjafiára ok nélkül, méltó az ítéletre: a ki pedig azt mondja az ő atyjafiának: Ráka, méltó a főtörvényszékre: a ki pedig ezt mondja: Bolond, méltó a gyehenna tüzére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, 'Azért, ha a te ajándékodat az oltárra viszed és ott megemlékezel arról, hogy a te atyádfiának valami panasza van ellened:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, 'Hagyd ott az oltár előtt a te ajándékodat, és menj el, elébb békélj meg a te atyádfiával, és azután eljövén, vidd fel a te ajándékodat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, 'Légy jóakarója a te ellenségednek hamar, a míg az úton vagy vele, hogy ellenséged valamiképen a bíró kezébe ne adjon, és a bíró oda ne adjon a poroszló kezébe, és tömlöczbe ne vessen téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, 'Bizony mondom néked: ki nem jősz onnét, mígnem megfizetsz az utolsó fillérig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 27, 'Hallottátok, hogy megmondatott a régieknek: Ne paráználkodjál!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 28, 'Én pedig azt mondom néktek, hogy valaki asszonyra tekint gonosz kivánságnak okáért, immár paráználkodott azzal az ő szívében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 29, 'Ha pedig a te jobb szemed megbotránkoztat téged, vájd ki azt és vesd el magadtól; mert jobb néked, hogy egy vesszen el a te tagjaid közül, semhogy egész tested a gyehennára vettessék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 30, 'És ha a te jobb kezed botránkoztat meg téged, vágd le azt és vesd el magadtól; mert jobb néked, hogy egy vesszen el a te tagjaid közül, semhogy egész tested a gyehennára vettessék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 31, 'Megmondatott továbbá: Valaki elbocsátja feleségét, adjon néki elválásról való levelet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 32, 'Én pedig azt mondom néktek: Valaki elbocsátja feleségét, paráznaság okán kívül, paráznává teszi azt; és a ki elbocsátott asszonyt veszen el, paráználkodik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 33, 'Ismét hallottátok, hogy megmondatott a régieknek: Hamisan ne esküdjél, hanem teljesítsd az Úrnak tett esküidet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 34, 'Én pedig azt mondom néktek: Teljességgel ne esküdjetek; se az égre, mert az az Istennek királyi széke;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 35, 'Se a földre, mert az az ő lábainak zsámolya; se Jeruzsálemre, mert a nagy Királynak városa;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 36, 'Se a te fejedre ne esküdjél, mert egyetlen hajszálat sem tehetsz fehérré vagy feketévé;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 37, 'Hanem legyen a ti beszédetek: Úgy úgy; nem nem; a mi pedig ezeken felül vagyon, a gonosztól vagyon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 38, 'Hallottátok, hogy megmondatott: Szemet szemért és fogat fogért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 39, 'Én pedig azt mondom néktek: Ne álljatok ellene a gonosznak, hanem a ki arczul üt téged jobb felől, fordítsd felé a másik orczádat is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 40, 'És a ki törvénykezni akar veled és elvenni a te alsó ruhádat, engedd oda néki a felsőt is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 41, 'És a ki téged egy mértföldútra kényszerít, menj el vele kettőre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 42, 'A ki tőled kér, adj néki; és a ki tőled kölcsön akar kérni, el ne fordulj attól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 43, 'Hallottátok, hogy megmondatott: Szeresd felebarátodat és gyűlöld ellenségedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 44, 'Én pedig azt mondom néktek: Szeressétek ellenségeiteket, áldjátok azokat, a kik titeket átkoznak, jót tegyetek azokkal, a kik titeket gyűlölnek, és imádkozzatok azokért, a kik háborgatnak és kergetnek titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 45, 'Hogy legyetek a ti mennyei Atyátoknak fiai, a ki felhozza az ő napját mind a gonoszokra, mind a jókra, és esőt ád mind az igazaknak, mind a hamisaknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 46, 'Mert ha azokat szeretitek, a kik titeket szeretnek, micsoda jutalmát veszitek? Avagy a vámszedők is nem ugyanazt cselekeszik-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 47, 'És ha csak a ti atyátokfiait köszöntitek, mit cselekesztek másoknál többet? Nemde a vámszedők is nem azonképen cselekesznek-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 48, 'Legyetek azért ti tökéletesek, miként a ti mennyei Atyátok tökéletes.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, 'Vigyázzatok, hogy alamizsnátokat ne osztogassátok az emberek előtt, hogy lássanak titeket; mert különben nem lesz jutalmatok a ti mennyei Atyátoknál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'Azért mikor alamizsnát osztogatsz, ne kürtöltess magad előtt, a hogy a képmutatók tesznek a zsinagógákban és az utczákon, hogy az emberektől dícséretet nyerjenek. Bizony mondom néktek: elvették jutalmukat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'Te pedig a mikor alamizsnát osztogatsz, ne tudja a te bal kezed, mit cselekszik a te jobb kezed;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'Hogy a te alamizsnád titkon legyen; és a te Atyád, a ki titkon néz, megfizet néked nyilván.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'És mikor imádkozol, ne légy olyan, mint a képmutatók, a kik a gyülekezetekben és az utczák szegeletein fenállva szeretnek imádkozni, hogy lássák őket az emberek. Bizony mondom néktek: elvették jutalmukat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'Te pedig a mikor imádkozol, menj be a te belső szobádba, és ajtódat bezárva, imádkozzál a te Atyádhoz, a ki titkon van; és a te Atyád, a ki titkon néz, megfizet néked nyilván.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'És mikor imádkoztok, ne legyetek sok beszédűek, mint a pogányok, a kik azt gondolják, hogy az ő sok beszédükért hallgattatnak meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'Ne legyetek hát ezekhez hasonlók; mert jól tudja a ti Atyátok, mire van szükségetek, mielőtt kérnétek tőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'Ti azért így imádkozzatok: Mi Atyánk, ki vagy a mennyekben, szenteltessék meg a te neved;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'Jőjjön el a te országod; legyen meg a te akaratod, mint a mennyben, úgy a földön is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'A mi mindennapi kenyerünket add meg nékünk ma.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'És bocsásd meg a mi vétkeinket, miképen mi is megbocsátunk azoknak, a kik ellenünk vétkeztek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'És ne vígy minket kísértetbe, de szabadíts meg minket a gonosztól. Mert tiéd az ország és a hatalom és a dicsőség mind örökké. Ámen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'Mert ha megbocsátjátok az embereknek az ő vétkeiket, megbocsát néktek is a ti mennyei Atyátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'Ha pedig meg nem bocsátjátok az embereknek az ő vétkeiket, a ti mennyei Atyátok sem bocsátja meg a ti vétkeiteket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'Mikor pedig bőjtöltök, ne legyen komor a nézéstek, mint a képmutatóké, a kik eltorzítják arczukat, hogy lássák az emberek, hogy ők bőjtölnek. Bizony mondon néktek, elvették jutalmukat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'Te pedig mikor bőjtölsz, kend meg a te fejedet, és a te orczádat mosd meg;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'Hogy ne az emberek lássák bőjtölésedet, hanem a te Atyád, a ki titkon van; és a te Atyád, a ki titkon néz, megfizet néked nyilván.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, 'Ne gyűjtsetek magatoknak kincseket a földön, hol a rozsda és a moly megemészti, és a hol a tolvajok kiássák és ellopják;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, 'Hanem gyűjtsetek magatoknak kincseket mennyben, a hol sem a rozsda, sem a moly meg nem emészti, és a hol a tolvajok ki nem ássák, sem el nem lopják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 21, 'Mert a hol van a ti kincsetek, ott van a ti szívetek is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 22, 'A test lámpása a szem. Ha azért a te szemed tiszta, a te egész tested világos lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 23, 'Ha pedig a te szemed gonosz, a te egész tested sötét lesz. Ha azért a benned lévő világosság sötétség: mekkora akkor a sötétség?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 24, 'Senki sem szolgálhat két úrnak. Mert vagy az egyiket gyűlöli és a másikat szereti; vagy az egyikhez ragaszkodik és a másikat megveti. Nem szolgálhattok Istennek és a Mammonnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 25, 'Azért azt mondom néktek: Ne aggodalmaskodjatok a ti éltetek felől, mit egyetek és mit igyatok; sem a ti testetek felől, mibe öltözködjetek. Avagy nem több-é az élet hogynem az eledel, és a test hogynem az öltözet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 26, 'Tekintsetek az égi madarakra, hogy nem vetnek, nem aratnak, sem csűrbe nem takarnak; és a ti mennyei Atyátok eltartja azokat. Nem sokkal különbek vagytok-é azoknál?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 27, 'Kicsoda pedig az közületek, a ki aggodalmaskodásával megnövelheti termetét egy araszszal?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 28, 'Az öltözet felől is mit aggodalmaskodtok? Vegyétek eszetekbe a mező liliomait, mi módon növekednek: nem munkálkodnak, és nem fonnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 29, 'De mondom néktek, hogy Salamon minden dicsőségében sem öltözködött úgy, mint ezek közül egy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 30, 'Ha pedig a mezőnek füvét, a mely ma van, és holnap kemenczébe vettetik, így ruházza az Isten; nem sokkal inkább-é titeket, ti kicsinyhitűek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 31, 'Ne aggodalmaskodjatok tehát, és ne mondjátok: Mit együnk? vagy: Mit igyunk? vagy: Mivel ruházkodjunk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 32, 'Mert mind ezeket a pogányok kérdezik. Mert jól tudja a ti mennyei Atyátok, hogy mind ezekre szükségetek van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 33, 'Hanem keressétek először Istennek országát, és az ő igazságát; és ezek mind megadatnak néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 34, 'Ne aggodalmaskodjatok tehát a holnap felől; mert a holnap majd aggodalmaskodik a maga dolgai felől. Elég minden napnak a maga baja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, 'Ne ítéljetek, hogy ne ítéltessetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'Mert a milyen ítélettel ítéltek, olyannal ítéltettek, és a milyen mértékkel mértek, olyannal mérnek néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'Miért nézed pedig a szálkát, a mely a te atyádfia szemében van, a gerendát pedig, a mely a te szemedben van, nem veszed észre?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'Avagy mi módon mondhatod a te atyádfiának: Hadd vessem ki a szálkát a te szemedből; holott ímé, a te szemedben gerenda van?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'Képmutató, vesd ki előbb a gerendát a te szemedből, és akkor gondolj arra, hogy kivessed a szálkát a te atyádfiának szeméből!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, 'Ne adjátok azt, a mi szent, az ebeknek, se gyöngyeiteket ne hányjátok a disznók elé, hogy meg ne tapossák azokat lábaikkal, és néktek fordulván, meg ne szaggassanak titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, 'Kérjetek és adatik néktek; keressetek és találtok; zörgessetek és megnyittatik néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'Mert a ki kér, mind kap; és a ki keres, talál; és a zörgetőnek megnyittatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'Avagy ki az az ember közületek, a ki, ha az ő fia kenyeret kér tőle, követ ád néki?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'És ha halat kér, vajjon kígyót ád-e néki?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'Ha azért ti gonosz létetekre tudtok a ti fiaitoknak jó ajándékokat adni, mennyivel inkább ád a ti mennyei Atyátok jókat azoknak, a kik kérnek tőle?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'A mit akartok azért, hogy az emberek ti veletek cselekedjenek, mindazt ti is úgy cselekedjétek azokkal; mert ez a törvény és a próféták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, 'Menjetek be a szoros kapun. Mert tágas az a kapu és széles az az út, a mely a veszedelemre visz, és sokan vannak, a kik azon járnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'Mert szoros az a kapu és keskeny az az út, a mely az életre visz, és kevesen vannak, a kik megtalálják azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, 'Őrizkedjetek pedig a hamis prófétáktól, a kik juhoknak ruhájában jőnek hozzátok, de belől ragadozó farkasok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'Gyümölcseikről ismeritek meg őket. Vajjon a tövisről szednek-é szőlőt, vagy a bojtorjánról fügét?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, 'Ekképen minden jó fa jó gyümölcsöt terem; a romlott fa pedig rossz gyümölcsöt terem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, 'Nem teremhet jó fa rossz gyümölcsöt; romlott fa sem teremhet jó gyümölcsöt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'Minden fa, a mely nem terem jó gyümölcsöt, kivágattatik és tűzre vettetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'Azért az ő gyümölcseikről ismeritek meg őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, 'Nem minden, a ki ezt mondja nékem: Uram! Uram! megyen be a mennyek országába; hanem a ki cselekszi az én mennyei Atyám akaratát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, 'Sokan mondják majd nékem ama napon: Uram! Uram! nem a te nevedben prófétáltunk-é, és nem a te nevedben űztünk-é ördögöket, és nem cselekedtünk-é sok hatalmas dolgot a te nevedben?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, 'És akkor vallást teszek majd nékik: Sohasem ismertelek titeket; távozzatok tőlem, ti gonosztevők.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, 'Valaki azért hallja én tőlem e beszédeket, és megcselekszi azokat, hasonlítom azt a bölcs emberhez, a ki a kősziklára építette az ő házát:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 25, 'És ömlött az eső, és eljött az árvíz, és fújtak a szelek, és beleütköztek abba a házba; de nem dőlt össze: mert a kősziklára építtetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 26, 'És valaki hallja én tőlem e beszédeket, és nem cselekszi meg azokat, hasonlatos lesz a bolond emberhez, a ki a fövényre építette házát:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 27, 'És ömlött az eső, és eljött az árvíz, és fújtak a szelek, és beleütköztek abba a házba; és összeomlott: és nagy lett annak romlása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 28, 'És lőn, mikor elvégezte Jézus e beszédeket, álmélkodik vala a sokaság az ő tanításán:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 29, 'Mert úgy tanítja vala őket, mint a kinek hatalma van, és nem úgy, mint az írástudók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'Mikor leszállott vala a hegyről, nagy sokaság követé őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'És ímé eljövén egy bélpoklos, leborula előtte, mondván: Uram, ha akarod, megtisztíthatsz engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'És kinyújtván kezét, megilleté őt Jézus, mondván: Akarom, tisztulj meg. És azonnal eltisztult annak poklossága.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'És monda néki Jézus: Meglásd, senkinek se szólj. Hanem eredj, mutasd meg magadat a papnak, és vidd fel az ajándékot, a melyet Mózes rendelt, bizonyságul nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'Mikor pedig beméne Jézus Kapernaumba, egy százados méne hozzá, kérvén őt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, 'És ezt mondván: Uram, az én szolgám otthon gutaütötten fekszik, és nagy kínokat szenved.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, 'És monda néki Jézus: Elmegyek és meggyógyítom őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, 'És felelvén a százados, monda: Uram, nem vagyok méltó, hogy az én hajlékomba jőjj; hanem csak szólj egy szót, és meggyógyul az én szolgám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, 'Mert én is hatalmasság alá vetett ember vagyok, és vannak alattam vitézek; és mondom egyiknek: Eredj el, és elmegy; és a másiknak: Jöszte, és eljő; és az én szolgámnak: Tedd ezt, és megteszi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'Jézus pedig, a mikor ezt hallá, elcsodálkozék, és monda az őt követőknek: Bizony mondom néktek, még az Izráelben sem találtam ilyen nagy hitet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'De mondom néktek, hogy sokan eljőnek napkeletről és napnyugatról, és letelepednek Ábrahámmal, Izsákkal és Jákóbbal a mennyek országában:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'Ez ország fiai pedig kivettetnek a külső sötétségre; holott lészen sírás és fogaknak csikorgatása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'És monda Jézus a századosnak: Eredj el, és legyen néked a te hited szerint. És meggyógyult annak szolgája abban az órában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'És bemenvén Jézus a Péter házába, látá, hogy annak napa fekszik és lázas.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'És illeté annak kezét, és elhagyta őt a láz; és fölkele, és szolgála nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, 'Az est beálltával pedig vivének hozzá sok ördöngőst, és egy szóval kiűzé a tisztátalan lelkeket, és meggyógyít vala minden beteget;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'Hogy beteljesedjék, a mit Ésaiás próféta mondott, így szólván: Ő vette el a mi erőtlenségünket, és ő hordozta a mi betegségünket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'Látván pedig Jézus a nagy sokaságot maga körül, parancsolá, hogy menjenek a túlsó partra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'És hozzámenvén egy írástudó, monda néki: Mester, követlek téged, akárhova mégy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'És monda néki Jézus: A rókáknak vagyon barlangjok és az égi madaraknak fészkük; de az ember Fiának nincs hová fejét lehajtani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'Egy másik pedig az ő tanítványai közül monda néki: Uram, engedd meg nékem, hogy előbb elmenjek és eltemessem az én atyámat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, 'Jézus pedig monda néki: Kövess engem, és hagyd, hogy a halottak temessék el az ő halottaikat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, 'És mikor a hajóra szállt vala, követék őt az ő tanítványai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, 'És ímé nagy háborgás lőn a tengeren, annyira, hogy a hajót elborítják vala a hullámok; ő pedig aluszik vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, 'És az ő tanítványai hozzámenvén, felkölték őt, mondván: Uram, ments meg minket; mert elveszünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, 'És monda nékik: Mit féltek, óh kicsinyhitűek? Ekkor fölkelvén, megdorgálá a szeleket és a tengert, és lőn nagy csendesség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, 'Az emberek pedig elcsodálkozának, mondván: Kicsoda ez, hogy mind a szelek, mind a tenger engednek néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, 'És a mikor eljutott vala a túlsó partra, a Gadarénusok tartományába, két ördöngős ment eléje, a sírboltokból kijövén, igen kegyetlenek, annyira, hogy senki sem mer vala elmenni azon az úton.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 29, 'És ímé kiáltának mondván: Mi közünk te veled Jézus, Istennek fia? Azért jöttél ide, hogy idő előtt meggyötörj minket?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 30, 'Tőlük távol pedig egy nagy disznónyáj legelészik vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 31, 'Az ördögök pedig kérik vala őt mondván: Ha kiűzesz minket, engedd meg nékünk, hogy ama disznónyájba mehessünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 32, 'És monda nékik: Menjetek. Azok pedig kimenvén, menének a disznónyájba: és ímé az egész disznónyáj a meredekről a tengerbe rohana, és oda vesze a vízben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 33, 'A pásztorok pedig elfutának, és bemenvén a városba hírré adának mindent, azokat is, a mik az ördöngősökkel történtek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 34, 'És ímé az egész város kiméne Jézus elébe; és mihelyt meglátták, kérék őt, hogy távozzék az ő határukból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'És hajóra szállva átkele, és méne a maga városába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, 'És ímé hoznak vala hozzá egy ágyban fekvő gutaütött embert. És látva Jézus azoknak hitét, monda a gutaütöttnek: Bízzál fiam! Megbocsáttattak néked a te bűneid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'És ímé némelyek az írástudók közül mondának magukban: Ez káromlást szól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'És Jézus, látva az ő gondolataikat, monda: Miért gondoltok gonoszt a ti szívetekben?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'Mert mi könnyebb, ezt mondani-é: Megbocsáttattak néked a te bűneid; vagy ezt mondani: Kelj föl és járj?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'Hogy pedig megtudjátok, hogy az ember Fiának van hatalma a földön a bűnöket megbocsátani (ekkor monda a gutaütöttnek): Kelj föl, vedd a te ágyadat, és eredj haza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, 'És az felkelvén, haza méne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, 'A sokaság pedig ezt látván, elálmélkodék, és dicsőíté az Istent, hogy ilyen hatalmat adott az embereknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, 'És mikor Jézus onnét tovább méne, láta egy embert ülni a vámszedő helyen, a kinek Máté volt a neve, és monda néki: Kövess engem! És az felkelvén, követé őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, 'És lőn, a mikor ő letelepedék a házban, ímé sok vámszedő és bűnös jött oda és letelepedtek Jézussal és az ő tanítványaival az asztalhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, 'És látva ezt a farizeusok, mondának az ő tanítványainak: Miért eszik ez a ti Mesteretek a vámszedőkkel és bűnösökkel együtt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, 'Jézus pedig ezt hallván, monda nékik: Nem az egészségeseknek van szüksége orvosra, hanem a betegeknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, 'Elmenvén pedig tanuljátok meg, mi az: Irgalmasságot akarok és nem áldozatot. Mert nem az igazakat hivogatni jöttem, hanem a bűnösöket a megtérésre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, 'Akkor a János tanítványai jövének hozzá, mondván: Miért hogy mi és a farizeusok sokat bőjtölünk, a te tanítványaid pedig nem bőjtölnek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, 'És monda nékik Jézus: Vajjon szomorkodhatik-é a násznép a míg velök van a vőlegény? de eljőnek a napok, a mikor elvétetik tőlök a vőlegény, és akkor bőjtölni fognak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 16, 'Senki sem vet pedig új posztóból foltot az ócska ruhára; mert a mi azt kitoldaná, még elszakít a ruhából és nagyobb szakadás lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 17, 'Új bort sem töltenek ó tömlőkbe; máskülönben a tömlők szétszakadoznak, és a bor kiömöl, a tömlők is elvesznek; hanem az új bort új tömlőkbe töltik, és mindkettő megmarad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 18, 'Mikor ezeket mondá nékik, ímé egy főember eljövén leborula előtte, mondván: Az én leányom épen most halt meg; de jer, vesd reá kezedet, és megelevenedik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 19, 'És felkelvén Jézus követé őt tanítványaival együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 20, 'És ímé, egy asszony, a ki tizenkét év óta vérfolyásban szenved vala, hozzájárulván hátulról, illeté az ő ruhájának szegélyét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 21, 'Mert ezt mondja vala magában: Ha csak ruháját illetem is, meggyógyulok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 22, 'Jézus pedig megfordulván és reá tekintvén, monda: Bízzál leányom; a te hited megtartott téged. És meggyógyult az asszony abban az órában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 23, 'És Jézus a főember házához érvén, látván a sípolókat és a tolongó sokaságot,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 24, 'Monda nékik: Menjetek el innen, mert a leányzó nem halt meg, hanem aluszik. És kinevették őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 25, 'Mikor pedig a sokaság eltávolíttaték, bemenvén, megfogá annak kezét, és a leányzó felkelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 26, 'És elterjede ez a hír abban az egész tartományban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 27, 'És mikor Jézus tovább ment onnét, két vak követé őt, kiáltozva és ezt mondva: Könyörülj rajtunk, Dávidnak fia!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 28, 'Mikor pedig beméne a házba, oda menének hozzá a vakok, és monda nékik Jézus: Hiszitek-é, hogy én azt megcselekedhetem? Mondának néki: Igen, Uram.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 29, 'Akkor illeté az ő szemeiket, mondván: Legyen néktek a ti hitetek szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 30, 'És megnyilatkozának azoknak szemei; és rájok parancsola Jézus, mondván: Meglássátok, senki meg ne tudja!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 31, 'Azok pedig kimenvén, elterjeszték az ő hírét abban az egész tartományban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 32, 'Mikor pedig azok elmentek vala, ímé egy ördöngős néma embert hozának néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 33, 'És az ördögöt kiűzvén, megszólalt a néma; és a sokaság csudálkozik vala, mondván: Soha nem láttak ilyet Izráelben!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 34, 'A farizeusok pedig ezt mondják vala: Az ördögök fejedelme által űzi ki az ördögöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 35, 'És körüljárja vala Jézus a városokat mind, és a falvakat, tanítván azoknak zsinagógáiban, és hirdetvén az Isten országának evangyéliomát, és gyógyítván mindenféle betegséget és mindenféle erőtelenséget a nép között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 36, 'Mikor pedig látta vala a sokaságot, könyörületességre indula rajtok, mert el voltak gyötörve és szétszórva, mint a pásztor nélkül való juhok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 37, 'Akkor monda az ő tanítványainak: Az aratni való sok, de a munkás kevés.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 38, 'Kérjétek azért az aratásnak Urát, hogy küldjön munkásokat az ő aratásába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'És előszólítván tizenkét tanítványát, hatalmat ada nékik a tisztátalan lelkek felett, hogy kiűzzék azokat, és gyógyítsanak minden betegséget és minden erőtelenséget.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'A tizenkét apostol nevei pedig ezek: Első Simon, a kit Péternek hívnak, és András, az ő testvére; Jakab, a Zebedeus fia, és János az ő testvére;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'Filep és Bertalan; Tamás és Máté, a vámszedő; Jakab, az Alfeus fia, és Lebbeus, a kit Taddeusnak hívtak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'Simon a kananita, és Judás, az Iskariotes, a ki el is árulta őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'Ezt a tizenkettőt küldé ki Jézus, és megparancsolá nékik, mondván: Pogányok útjára ne menjetek, és Samaritánusok városába ne menjetek be;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'Hanem menjetek inkább Izráel házának eltévelyedett juhaihoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'Elmenvén pedig prédikáljatok, mondván: Elközelített a mennyeknek országa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, 'Betegeket gyógyítsatok, poklosokat tisztítsatok, halottakat támasszatok, ördögöket űzzetek. Ingyen vettétek, ingyen adjátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'Ne szerezzetek aranyat, se ezüstöt, se réz-pénzt a ti erszényetekbe,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'Se útitáskát, se két ruhát, se sarut, se pálczát; mert méltó a munkás az ő táplálékára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'A mely városba vagy faluba pedig bementek, tudakozzátok meg, ki abban méltó; és ott maradjatok, a míg tovább mehettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'Ha pedig bementek a házba, köszöntsétek azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'És ha méltó a ház, szálljon a ti békességtek reá; ha pedig nem méltó, a ti békességtek rátok térjen vissza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, 'És ha valaki nem fogad be titeket, és nem hallgatja a ti beszédeteket, mikor kimentek abból a házból, vagy városból, lábaitok porát is verjétek le.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, 'Bizony mondom néktek: Az ítélet napján könnyebb lesz a Sodoma és Gomora földjének dolga, mint annak a városnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, 'Ímé, én elbocsátlak titeket, mint juhokat a farkasok közé; legyetek azért okosak mint a kígyók, és szelidek mint a galambok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, 'De óvakodjatok az emberektől; mert törvényszékekre adnak titeket és az ő gyülekezeteikben megostoroznak titeket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, 'És helytartók és királyok elé visznek titeket érettem, bizonyságul ő magoknak és a pogányoknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, 'De mikor átadnak titeket, ne aggodalmaskodjatok, mi módon vagy mit szóljatok; mert megadatik néktek abban az órában, mit mondjatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, 'Mert nem ti vagytok, a kik szóltok, hanem a ti Atyátoknak Lelke az, a ki szól ti bennetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, 'Halálra adja pedig testvér testvérét, atya gyermekét; támadnak magzatok szüleik ellen, és megöletik őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 22, 'És gyűlöletesek lesztek, mindenki előtt az én nevemért; de a ki mindvégig megáll, az megtartatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 23, 'Mikor pedig abban a városban üldöznek titeket, szaladjatok a másikba. Mert bizony mondom néktek: be sem járjátok Izráel városait, míg az embernek Fia eljövend.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 24, 'Nem fölebbvaló a tanítvány a tanítónál, sem a szolga az ő uránál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 25, 'Elég a tanítványnak, ha olyan mint a mestere, és a szolga mint az ő Ura. Ha a házigazdát Belzebubnak hívták, mennyivel inkább az ő házanépét?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 26, 'Azért ne féljetek tőlök. Mert nincs oly rejtett dolog, a mi napfényre ne jőne; és oly titok, a mi ki ne tudódnék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 27, 'A mit néktek a sötétben mondok, a világosságban mondjátok; és a mit fülbe súgva hallotok, a háztetőkről hirdessétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 28, 'És ne féljetek azoktól, a kik a testet ölik meg, a lelket pedig meg nem ölhetik; hanem attól féljetek inkább, a ki mind a lelket, mind a testet elvesztheti a gyehennában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 29, 'Nemde, két verebecskét meg lehet venni egy kis fillérért? És egy sem esik azok közül a földre a ti Atyátok akarata nélkül!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 30, 'Néktek pedig még a fejetek hajszálai is mind számon vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 31, 'Ne féljetek azért; ti sok verebecskénél drágábbak vagytok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 32, 'Valaki azért vallást tesz én rólam az emberek előtt, én is vallást teszek arról az én mennyei Atyám előtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 33, 'A ki pedig megtagad engem az emberek előtt, én is megtagadom azt az én mennyei Atyám előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 34, 'Ne gondoljátok, hogy azért jöttem, hogy békességet bocsássak e földre; nem azért jöttem, hogy békességet bocsássak, hanem hogy fegyvert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 35, 'Mert azért jöttem, hogy meghasonlást támaszszak az ember és az ő atyja, a leány és az ő anyja, a meny és az ő napa közt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 36, 'És hogy az embernek ellensége legyen az ő házanépe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 37, 'A ki inkább szereti atyját és anyját, hogynem engemet, nem méltó én hozzám; és a ki inkább szereti fiát és leányát, hogynem engemet, nem méltó én hozzám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 38, 'És a ki föl nem veszi az ő keresztjét és úgy nem követ engem, nem méltó én hozzám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 39, 'A ki megtalálja az ő életét, elveszti azt; és a ki elveszti az ő életét én érettem, megtalálja azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 40, 'A ki titeket befogad, engem fogad be; és a ki engem befogad, azt fogadja be, a ki engem küldött.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 41, 'A ki befogadja a prófétát próféta nevében, prófétának jutalmát veszi; és a ki befogadja az igazat igaznak nevében, igaznak jutalmát veszi;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 42, 'És a ki inni ád egynek e kicsinyek közül, csak egy pohár hideg vizet tanítvány nevében, bizony mondom néktek, el nem vesztheti jutalmát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'És lőn, mikor elvégezé Jézus a tizenkét tanítványának adott utasítást, elméne onnan, hogy tanítson és prédikáljon azoknak városaiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'János pedig, mikor meghallotta a fogságban a Krisztus cselekedeteit, elküldvén kettőt az ő tanítványai közül,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, 'Monda néki: Te vagy-é az, a ki eljövendő, vagy mást várjunk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'És felelvén Jézus, monda nékik: Menjetek el és jelentsétek Jánosnak, a miket hallotok és láttok:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, 'A vakok látnak, és a sánták járnak; a poklosok megtisztulnak és a siketek hallanak; a halottak föltámadnak, és a szegényeknek evangyéliom hirdettetik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'És boldog, a ki én bennem meg nem botránkozik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'Mikor pedig azok elmentek vala, szólni kezde Jézus a sokaságnak Jánosról: Mit látni mentetek ki a pusztába? Nádszálat-é, a mit a szél hajtogat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'Hát mit látni mentetek ki? Puha ruhába öltözött embert-é? Ímé a kik puha ruhákat viselnek, a királyok palotáiban vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'Hát mit látni mentetek ki? Prófétát-é? Bizony, mondom néktek, prófétánál is nagyobbat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'Mert ő az, a kiről meg van írva: Ímé én elküldöm az én követemet a te orczád előtt, a ki megkészíti előtted a te útadat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'Bizony mondom néktek: az asszonyoktól szülöttek között nem támadott nagyobb Keresztelő Jánosnál; de a ki legkisebb a mennyeknek országában, nagyobb nálánál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'A Keresztelő János idejétől fogva pedig mind mostanig erőszakoskodnak a mennyek országáért, és az erőszakoskodók ragadják el azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'Mert a próféták mindnyájan és a törvény Jánosig prófétáltak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'És, ha be akarjátok venni, Illés ő, a ki eljövendő vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'A kinek van füle a hallásra, hallja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'De kihez hasonlítsam ezt a nemzetséget? Hasonlatos a gyermekekhez, a kik a piaczon ülnek, és kiáltoznak az ő társaiknak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, 'És ezt mondják: Sípoltunk néktek, és nem tánczoltatok; siralmas énekeket énekeltünk néktek, és nem sírtatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'Mert eljött János, a ki sem eszik, sem iszik, és azt mondják: Ördög van benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 19, 'Eljött az embernek Fia, a ki eszik és iszik, és ezt mondják: Ímé a nagy étü és részeges ember, a vámszedők és bűnösök barátja! És igazoltaték a bölcseség az ő fiaitól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 20, 'Ekkor elkezdé szemökre hányni ama városoknak, a melyekben legtöbb csodái lőnek, hogy nem tértek vala meg:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 21, 'Jaj néked Korazin! Jaj néked Bethsaida! Mert ha Tirusban és Sidonban történnek vala azok a csodák, a melyek bennetek lőnek, rég megtértek volna gyászruhában és hamuban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 22, 'De mondom néktek: Tirusnak és Sidonnak könnyebb dolga lesz az ítélet napján, hogynem néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 23, 'Te is Kapernaum, a ki az égig felmagasztaltattál, a pokolig fogsz megaláztatni; mert ha Sodomában történnek vala azok a csodák, a melyek te benned lőnek, mind e mai napig megmaradt volna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 24, 'De mondom néktek, hogy Sodoma földének könnyebb dolga lesz az ítélet napján, hogynem néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 25, 'Abban az időben szólván Jézus, monda: Hálákat adok néked, Atyám, mennynek és földnek Ura, hogy elrejtetted ezeket a bölcsek és az értelmesek elől, és a kisdedeknek megjelentetted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 26, 'Igen, Atyám, mert így volt kedves te előtted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 27, 'Mindent nékem adott át az én Atyám, és senki sem ismeri a Fiút, csak az Atya; az Atyát sem ismeri senki, csak a Fiú, és a kinek a Fiú akarja megjelenteni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 28, 'Jőjjetek én hozzám mindnyájan, a kik megfáradtatok és megterheltettetek, és én megnyugosztlak titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 29, 'Vegyétek föl magatokra az én igámat, és tanuljátok meg tőlem, hogy én szelid és alázatos szívű vagyok: és nyugalmat találtok a ti lelkeiteknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 30, 'Mert az én igám gyönyörűséges, és az én terhem könnyű.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'Abban az időben a vetéseken át haladt Jézus szombatnapon; tanítványai pedig megéheztek, és kezdték a kalászokat tépni és enni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'Látván pedig ezt a farizeusok, mondának néki: Ímé a te tanítványaid azt cselekszik, a mit nem szabad szombatnapon cselekedni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'Ő pedig monda nékik: Nem olvastátok-é, mit cselekedett Dávid, mikor megéhezett vala ő és a kik vele valának?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'Hogyan ment be az Isten házába, és ette meg a szentelt kenyereket, a melyeket nem vala szabad megennie néki, sem azoknak, a kik ő vele valának, hanem csak a papoknak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'Vagy nem olvastátok-é a törvényben, hogy szombatnapon megtörik a papok a szombatot a templomban és nem vétkeznek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'Mondom pedig néktek, hogy a templomnál nagyobb van itt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'Ha pedig tudnátok, mi ez: Irgalmasságot akarok és nem áldozatot, nem kárhoztattátok volna az ártatlanokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'Mert a szombatnak is Ura az embernek Fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'És távozván onnan, méne az ő zsinagógájukba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'És ímé, vala ott egy elszáradt kezű ember. És megkérdék őt, mondván: Ha szabad-é szombatnapon gyógyítani? hogy vádolhassák őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'Ő pedig monda nékik: Kicsoda közületek az az ember, a kinek van egy juha, és ha az szombatnapon a verembe esik, meg nem ragadja és ki nem vonja azt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'Mennyivel drágább pedig az ember a juhnál! Szabad tehát szombatnapon jót cselekedni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'Akkor monda annak az embernek: Nyújtsd ki a kezedet. És kinyújtá, és olyan éppé lőn, mint a másik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'A farizeusok pedig kimenvén, tanácsot tartának ellene, hogyan veszíthetnék el őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'Jézus pedig észrevévén ezt, eltávozék onnan. És követé őt nagy sokaság, és ő meggyógyítja vala mindnyájokat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'És megfenyegeté őket, hogy őt ismertté ne tegyék;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'Hogy beteljesedjék Ésaiás próféta mondása, a ki így szólt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, 'Ímé az én szolgám, a kit választottam; az én szerelmesem, a kiben az én lelkem kedvét lelé; lelkemet adom ő belé, és ítéletet hirdet a pogányoknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'Nem verseng, és nem kiált; az utczákon senki nem hallja szavát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'A megrepedezett nádat nem töri el, és a pislogó gyertyabelet nem oltja ki, mígnem diadalomra viszi az ítéletet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, 'És az ő nevében reménykednek majd a pogányok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, 'Akkor egy vak és néma ördöngőst hoztak ő eléje; és meggyógyítá azt, annyira, hogy a vak és néma mind beszél, mind lát vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 23, 'És elálmélkodék az egész sokaság, és monda: Vajjon nem ez-é Dávidnak ama Fia?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 24, 'A farizeusok pedig ezt hallván, mondának: Ez nem űzi ki az ördögöket, hanemha Belzebubbal, az ördögök fejedelmével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 25, 'Jézus pedig, tudva az ő gondolataikat, monda nékik: Minden ország, a mely magával meghasonlik, elpusztul; és egy város vagy háznép sem állhat meg, a mely meghasonlik magával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 26, 'Ha pedig a Sátán a Sátánt űzi ki, önmagával hasonlott meg; mimódon állhat meg tehát az ő országa?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 27, 'És ha én Belzebub által űzöm ki az ördögöket, a ti fiaitok ki által űzik ki? Azért ők magok lesznek a ti bíráitok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 28, 'Ha pedig én Istennek Lelke által űzöm ki az ördögöket, akkor kétség nélkül elérkezett hozzátok az Isten országa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 29, 'Avagy mi módon mehet be valaki a hatalmasnak házába és rabolhatja el annak kincseit, hanemha megkötözi előbb a hatalmast és akkor rabolja ki annak házát?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 30, 'A ki velem nincsen, ellenem van; és a ki velem nem gyűjt, tékozol.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 31, 'Azt mondom azért néktek: Minden bűn és káromlás megbocsáttatik az embereknek; de a Lélek káromlása nem bocsáttatik meg az embereknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 32, 'Még a ki az ember Fia ellen szól, annak is megbocsáttatik; de a ki a Szent Lélek ellen szól, annak sem ezen, sem a más világon meg nem bocsáttatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 33, 'Vagy legyetek jó fák, és teremjetek jó gyümölcsöt, vagy legyetek romlott fák, és teremjetek romlott gyümölcsöt; mert gyümölcséről ismerik meg a fát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 34, 'Mérges kígyóknak fajzatai, mi módon szólhattok jókat, holott gonoszak vagytok? Mert a szívnek teljességéből szól a száj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 35, 'A jó ember az ő szívének jó kincseiből hozza elő a jókat; és a gonosz ember az ő szívének gonosz kincseiből hozza elő a gonoszokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 36, 'De mondom néktek: Minden hivalkodó beszédért, a mit beszélnek az emberek, számot adnak majd az ítélet napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 37, 'Mert a te beszédidből ismertetel igaznak, és a te beszédidből ismertetel hamisnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 38, 'Ekkor felelének néki némelyek az írástudók és farizeusok közül, mondván: Mester, jelt akarnánk látni te tőled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 39, 'Ő pedig felelvén, monda nékik: E gonosz és parázna nemzetség jelt kiván; és nem adatik jel néki, hanemha Jónás prófétának jele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 40, 'Mert a miképen Jónás három éjjel és három nap volt a czethal gyomrában, azonképen az embernek Fia is három nap és három éjjel lesz a föld gyomrában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 41, 'Ninive férfiai az ítéletkor együtt támadnak majd fel ezzel a nemzetséggel, és kárhoztatják ezt: mivelhogy ők megtértek a Jónás prédikálására; és ímé nagyobb van itt Jónásnál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 42, 'Délnek királyné asszonya felkél majd az ítéletkor e nemzetséggel együtt, és kárhoztatja ezt: mert ő eljött a földnek széléről, hogy hallhassa a Salamon bölcseségét; és ímé, nagyobb van itt Salamonnál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 43, 'Mikor pedig a tisztátalan lélek kimegy az emberből, víz nélkül való helyeken jár, nyugalmat keresve, és nem talál:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 44, 'Akkor ezt mondja: Visszatérek az én házamba, a honnét kijöttem. És oda menvén, üresen, kisöpörve és fölékesítve találja azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 45, 'Akkor elmegy és vesz maga mellé más hét lelket, gonoszabbakat ő magánál, és bemenvén, ott lakoznak; és ennek az embernek utolsó állapotja gonoszabb lesz az elsőnél. Így lesz ezzel a gonosz nemzetséggel is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 46, 'Mikor pedig még szóla a sokaságnak, ímé az ő anyja és az ő testvérei állanak vala odakünn, akarván ő vele szólni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 47, 'És monda néki valaki: Ímé a te anyád és testvéreid odakünn állanak, és szólni akarnak veled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 48, 'Ő pedig felelvén, monda a hozzá szólónak: Kicsoda az én anyám; és kik az én testvéreim?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 49, 'És kinyujtván kezét az ő tanítványaira, monda: Ímé az én anyám és az én testvéreim!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 50, 'Mert a ki cselekszi az én mennyei Atyám akaratát, az nékem fitestvérem, nőtestvérem és anyám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'Azon a napon kimenvén Jézus a házból, leüle a tenger mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'És nagy sokaság gyülekezék ő hozzá, annyira, hogy ő a hajóba méne leülni; az egész sokaság pedig a parton áll vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'És sokat beszéle nékik példázatokban, mondván: Ímé kiméne a magvető vetni,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, 'És a mikor ő vet vala, némely mag az útfélre esék; és eljövén a madarak, elkapdosák azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'Némely pedig a köves helyre esék, a hol nem sok földje vala; és hamar kikele, mivelhogy nem vala mélyen a földben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'De mikor a nap felkelt, elsüle; és mivelhogy gyökere nem vala, elszáradott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'Némely pedig a tövisek közé esék, és a tövisek felnevekedvén, megfojták azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'Némely pedig a jó földbe esék, és gyümölcsöt terme, némely száz annyit, némely hatvan annyit, némely pedig harmincz annyit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, 'A kinek van füle a hallásra, hallja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'A tanítványok pedig hozzámenvén, mondának néki: Miért szólasz nékik példázatokban?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'Ő pedig felelvén, monda nékik: Mert néktek megadatott, hogy érthessétek a mennyek országának titkait, ezeknek pedig nem adatott meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'Mert a kinek van, annak adatik, és bővölködik; de a kinek nincs, az is elvétetik tőle, a mije van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'Azért szólok velök példázatokban, mert látván nem látnak, és hallván nem hallanak, sem nem értenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'És beteljesedék rajtok Ésaiás jövendölése, a mely ezt mondja: Hallván halljatok, és ne értsetek; és látván lássatok, és ne ismerjetek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'Mert megkövéredett e népnek szíve, és füleikkel nehezen hallottak, és szemeiket behunyták; hogy valami módon ne lássanak szemeikkel, és ne halljanak füleikkel, és ne értsenek szívükkel, és meg ne térjenek, és meg ne gyógyítsam őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'A ti szemeitek pedig boldogok, hogy látnak; és a ti füleitek, hogy hallanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'Mert bizony mondom néktek, hogy sok próféta és igaz kívánta látni, a miket ti láttok, és nem látták; és hallani, a miket ti hallotok, és nem hallották.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, 'Ti halljátok meg azért a magvető példázatát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, 'Ha valaki hallja az ígét a mennyeknek országáról és nem érti, eljő a gonosz és elkapja azt, a mi annak szívébe vettetett vala. Ez az, a mely az útfélre esett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, 'A mely pedig a köves helyre esett, ez az, a ki hallja az ígét, és mindjárt örömmel fogadja;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, 'De nincs gyökere benne, hanem csak ideig való; mihelyt pedig nyomorgatás vagy üldözés támad az íge miatt, azonnal megbotránkozik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, 'A mely pedig a tövisek közé esett, ez az, a ki hallja az ígét, de e világnak gondja és a gazdagságnak csalárdsága elfojtja az ígét, és gyümölcsöt nem terem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, 'A mely pedig a jó földbe esett, ez az, a ki hallja és érti az ígét; a ki gyümölcsöt is terem, és terem némely száz annyit, némely hatvan annyit, némely pedig harmincz annyit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, 'Más példázatot is adott eléjök, mondván: Hasonlatos a mennyeknek országa az emberhez, a ki az ő földébe jó magot vetett;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, 'De mikor az emberek alusznak vala, eljöve az ő ellensége és konkolyt vete a búza közé, és elméne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, 'Mikor pedig felnevekedék a vetés, és gyümölcsöt terme, akkor meglátszék a konkoly is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, 'A gazda szolgái pedig előállván, mondának néki: Uram, avagy nem tiszta magot vetettél-e a te földedbe? honnan van azért benne a konkoly?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, 'Ő pedig monda nékik: Valamely ellenség cselekedte azt. A szolgák pedig mondának néki: Akarod-é tehát, hogy elmenvén, összeszedjük azokat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, 'Ő pedig monda: Nem. Mert a mikor összeszeditek a konkolyt, azzal együtt netalán a búzát is kiszaggatjátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, 'Hagyjátok, hogy együtt nőjjön mind a kettő az aratásig, és az aratás idején azt mondom majd az aratóknak: Szedjétek össze először a konkolyt, és kössétek kévékbe, hogy megégessétek; a búzát pedig takarítsátok az én csűrömbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, 'Más példázatot is adott eléjök, mondván: Hasonlatos a mennyeknek országa a mustármaghoz, a melyet vévén az ember, elvete az ő mezejében;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 32, 'A mely kisebb ugyan minden magnál; de a mikor felnő, nagyobb a veteményeknél, és fává lesz, annyira, hogy reá szállanak az égi madarak, és fészket raknak ágain.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 33, 'Más példázatot is mondott nékik: Hasonlatos a mennyeknek országa a kovászhoz, a melyet vévén az asszony, három mércze lisztbe elegyíte, mígnem az egész megkele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 34, 'Mind ezeket példázatokban mondá Jézus a sokaságnak, és példázat nélkül semmit sem szóla nékik,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 35, 'Hogy beteljék a mit a próféta szólott, mondván: Megnyitom az én számat példázatokra; és kitárom, amik e világ alapítása óta rejtve valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 36, 'Ekkor elbocsátván a sokaságot, beméne Jézus a házba. És az ő tanítványai hozzámenének, mondván: Magyarázd meg nékünk a szántóföld konkolyáról való példázatot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 37, 'Ő pedig felelvén monda nékik: A ki a jó magot veti, az az embernek Fia;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 38, 'A szántóföld pedig a világ; a jó mag az Isten országának fiai; a konkoly pedig a gonosznak fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 39, 'Az ellenség pedig, a ki a konkolyt vetette, az ördög; az aratás pedig a világ vége; az aratók pedig az angyalok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 40, 'A miképen azért összegyűjtik a konkolyt és megégetik: akképen lesz a világnak végén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 41, 'Az embernek Fia elküldi az ő angyalait, és az ő országából összegyűjtik a botránkozásokat mind, és azokat is, a kik gonoszságot cselekesznek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 42, 'És bevetik őket a tüzes kemenczébe: ott lészen sírás és fogcsikorgatás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 43, 'Akkor az igazak fénylenek, mint a nap, az ő Atyjoknak országában. A kinek van füle a hallásra, hallja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 44, 'Ismét hasonlatos a mennyeknek országa a szántóföldben elrejtett kincshez, a melyet megtalálván az ember, elrejté azt; és a felett való örömében elmegy és eladván mindenét a mije van, megveszi azt a szántóföldet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 45, 'Ismét hasonlatos a mennyeknek országa a kereskedőhöz, a ki igazgyöngyöket keres;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 46, 'A ki találván egy drágagyöngyre, elméne, és mindenét eladván a mije volt, megvevé azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 47, 'Szintén hasonlatos a mennyeknek országa a tengerbe vetett gyalomhoz, a mely mindenféle fajtát összefogott;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 48, 'Melyet, minekutána megtelt, a partra vontak a halászok, és leülvén, a jókat edényekbe gyűjtötték, a hitványakat pedig kihányták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 49, 'Így lesz a világ végén is: Eljőnek majd az angyalok, és kiválasztják a gonoszokat az igazak közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 50, 'És a tüzes kemenczébe vetik őket; ott lészen sírás és fogcsikorgatás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 51, 'Monda nékik Jézus: Megértettétek-é mindezeket? Mondának néki: Megértettük Uram.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 52, 'Ő pedig monda nékik: Annakokáért minden írástudó, a ki a mennyeknek országa felől megtaníttatott, hasonlatos az olyan gazdához, a ki ót és újat hoz elő az ő éléstárából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 53, 'És lőn, a mikor elvégzé Jézus ezeket a példázatokat, elméne onnan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 54, 'És hazájába érve, tanítja vala őket az ő zsinagógájukban, annyira, hogy álmélkodnak és ezt mondják vala: Honnét van ebben ez a bölcseség és az erők?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 55, 'Nem ez-é amaz ácsmesternek fia? Nem az ő anyját hívják-é Máriának, és az ő testvéreit Jakabnak, Józsénak, Simonnak és Júdásnak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 56, 'És az ő nőtestvérei is nem mind minálunk vannak-é? Honnét vannak tehát ennél mindezek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 57, 'És megbotránkoznak vala ő benne. Jézus pedig monda nékik: Nincsen próféta tisztesség nélkül, hanem csak az ő hazájában és házában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 58, 'Nem is tőn ott sok csodát, az ő hitetlenségök miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'Abban az időben hírét hallá Heródes negyedes fejedelem Jézusnak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, 'És monda szolgáinak: Ez ama Keresztelő János; ő támadt fel a halálból, és azért működnek benne az erők.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'Mert Heródes elfogatta vala Jánost, és megkötöztetvén, tömlöczbe vetette vala Heródiásért, az ő testvérének, Fülöpnek feleségéért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'Mert ezt mondja vala néki János: Nem szabad néked ővele élned.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'De mikor meg akarta öletni, félt a sokaságtól, mert mint egy prófétát úgy tartják vala őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, 'Hanem mikor a Heródes születése napját ünnepelék, tánczola a Heródiás leánya ő előttük, és megtetszék Heródesnek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'Azért esküvéssel fogadá, hogy a mit kér, megadja néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'A leány pedig, anyja rábeszélésére, monda: Add ide nékem egy tálban a Keresztelő János fejét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'És megszomorodék a király, de esküjéért és a vendégek miatt parancsolá, hogy adják oda.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'És elküldvén, fejét véteté Jánosnak a tömlöczben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'És előhozák az ő fejét egy tálban, és adák a leánynak; az pedig vivé az ő anyjának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'És előjövén az ő tanítványai, elvivék a testet, és eltemeték azt; és elmenvén, megjelenték Jézusnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'És mikor ezt meghallotta Jézus, elméne onnét hajón egy puszta helyre egyedül. A sokaság pedig ezt hallva, gyalog követé őt a városokból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'És kimenvén Jézus, láta nagy sokaságot, és megszáná őket, és azoknak betegeit meggyógyítá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'Mikor pedig estveledék, hozzá menének az ő tanítványai, mondván: Puszta hely ez, és az idő már elmúlt; bocsásd el a sokaságot, hogy menjenek el a falvakba és vegyenek magoknak eleséget.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, 'Jézus pedig monda nékik: Nem szükség elmenniök; adjatok nékik ti enniök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 17, 'Azok pedig mondának néki: Nincsen itt, csupán öt kenyerünk és két halunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 18, 'Ő pedig monda: Hozzátok azokat ide hozzám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 19, 'És mikor megparancsolá a sokaságnak, hogy üljenek le a fűre, vevé az öt kenyeret és két halat, és szemeit az égre emelvén, hálákat ada; és megszegvén a kenyereket, adá a tanítványoknak, a tanítványok pedig a sokaságnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 20, 'És mindnyájan evének, és megelégedének; és felszedék a maradék darabokat, tizenkét teli kosárral.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 21, 'A kik pedig ettek vala, mintegy ötezeren valának férfiak, asszonyokon és gyermekeken kívül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 22, 'És mindjárt kényszeríté Jézus az ő tanítványait, hogy szálljanak a hajóba és menjenek át előre a túlsó partra, míg ő elbocsátja a sokaságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 23, 'És a mint elbocsátá a sokaságot, felméne a hegyre, magánosan imádkozni. Mikor pedig beestveledék, egyedül vala ott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 24, 'A hajó pedig immár a tenger közepén vala, a haboktól háborgattatva; mivelhogy a szél szembe fújt vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 25, 'Az éjszaka negyedik részében pedig hozzájuk méne Jézus, a tengeren járván.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 26, 'És mikor látták a tanítványok, hogy ő a tengeren jára, megrémülének, mondván: Ez kísértet; és a félelem miatt kiáltozának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 27, 'De Jézus azonnal szóla hozzájuk, mondván: Bízzatok; én vagyok, ne féljetek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 28, 'Péter pedig felelvén néki, monda: Uram, ha te vagy, parancsolj, hogy hozzád mehessek a vizeken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 29, 'Ő pedig monda: Jövel! És Péter kiszállván a hajóból, jár vala a vizeken, hogy Jézushoz menjen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 30, 'De látva a nagy szelet, megrémüle; és a mikor kezd vala merülni, kiálta, mondván: Uram, tarts meg engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 31, 'Jézus pedig azonnal kinyújtván kezét, megragadá őt, és monda néki: Kicsinyhitű, miért kételkedél?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 32, 'És a mikor beléptek a hajóba, elállt a szél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 33, 'A hajóban levők pedig hozzámenvén, leborulának előtte, mondván: Bizony, Isten Fia vagy!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 34, 'És általkelvén, eljutának Genezáret földére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 35, 'És mikor megismerték őt annak a helynek lakosai, szétküldének abba az egész környékbe, és minden beteget hozzá hozának;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 36, 'És kérik vala őt, hogy csak az ő ruhájának peremét illethessék. És a kik illeték vala, mindnyájan meggyógyulának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, 'Akkor írástudók és farizeusok jőnek vala Jézushoz, Jeruzsálemből, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, 'Miért hágják át a te tanítványaid a vének rendeléseit? Mert nem mossák meg a kezeiket, mikor enni akarnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, 'Ő pedig felelvén monda nékik: Ti meg miért hágjátok át az Isten parancsolatját a ti rendeléseitek által?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, 'Mert Isten parancsolta ezt, mondván: Tiszteld atyádat és anyádat, és: A ki atyját vagy anyját szidalmazza, halállal lakoljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, 'Ti pedig ezt mondjátok: A ki atyjának vagy anyjának ezt mondja: Templomi ajándék az, a mivel megsegíthetlek, az olyan akár ne is tisztelje az ő atyját vagy anyját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, 'És erőtelenné tettétek az Isten parancsolatját a ti rendeléseitek által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, 'Képmutatók, igazán prófétált felőletek Ésaiás, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, 'Ez a nép szájával közelget hozzám, és ajkával tisztel engemet; szíve pedig távol van tőlem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, 'Pedig hiába tisztelnek engem, ha oly tudományokat tanítanak, a melyek embereknek parancsolatai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, 'És előszólítván a sokaságot, monda nékik: Halljátok és értsétek meg:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, 'Nem az fertőzteti meg az embert, a mi a szájon bemegy, hanem a mi kijön a szájból, az fertőzteti meg az embert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, 'Akkor hozzájárulván az ő tanítványai, mondának néki: Tudod-é, hogy a farizeusok e beszédet hallván, megbotránkoztak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, 'Ő pedig felelvén, monda: Minden plánta, a melyet nem az én mennyei Atyám plántált, kitépetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, 'Hagyjátok őket; vakoknak vak vezetői ők: ha pedig vak vezeti a vakot, mind a ketten a verembe esnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, 'Péter pedig felelvén, monda néki: Magyarázd meg nékünk ezt a példázatot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, 'Jézus pedig monda: Ti is értelem nélkül vagytok-é még?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 17, 'Mégsem értitek-é, hogy minden, a mi a szájon bemegy, a gyomorba jut, és az árnyékszékbe vettetik?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 18, 'A mik pedig a szájból jőnek ki, a szívből származnak, és azok fertőztetik meg az embert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 19, 'Mert a szívből származnak a gonosz gondolatok, gyilkosságok, házasságtörések, paráznaságok, lopások, hamis tanubizonyságok, káromlások.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 20, 'Ezek fertőztetik meg az embert; de a mosdatlan kézzel való evés nem fertőzteti meg az embert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 21, 'És elmenvén onnét Jézus, Tirus és Sidon vidékeire tére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 22, 'És ímé egy kananeus asszony jövén ki abból a tartományból, kiált vala néki: Uram, Dávidnak fia, könyörülj rajtam! az én leányom az ördögtől gonoszul gyötörtetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 23, 'Ő pedig egy szót sem felele néki. És az ő tanítványai hozzá menvén, kérik vala őt, mondván: Bocsásd el őt, mert utánunk kiált.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 24, 'Ő pedig felelvén, monda: Nem küldettem, csak az Izráel házának elveszett juhaihoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 25, 'Az asszony pedig odaérvén, leborula előtte, mondván: Uram, légy segítségül nékem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 26, 'Ő pedig felelvén, monda: Nem jó a fiak kenyerét elvenni, és az ebeknek vetni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 27, 'Az pedig monda: Úgy van, Uram; de hiszen az ebek is esznek a morzsalékokból, a mik az ő uroknak asztaláról aláhullanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 28, 'Ekkor felelvén Jézus, monda néki: Óh asszony, nagy a te hited! Legyen néked a te akaratod szerint. És meggyógyula az ő leánya attól a pillanattól fogva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 29, 'És onnét távozva, méne Jézus a Galilea tengere mellé; és felmenvén a hegyre, ott leüle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 30, 'És nagy sokaság megy vala hozzá, vivén magokkal sántákat, vakokat, némákat, csonkákat és sok egyebeket, és odahelyezék őket a Jézus lábai elé; és meggyógyítá őket,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 31, 'Úgy hogy a sokaság álmélkodik vala, látván, hogy a némák beszélnek, a csonkák megépülnek, a sánták járnak, a vakok látnak: és dicsőíték Izráel Istenét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 32, 'Jézus pedig előszólítván az ő tanítványait, monda: Szánakozom e sokaságon, mert három napja immár, hogy velem vannak, és nincs mit enniök. Éhen pedig nem akarom őket elbocsátani, hogy valamiképen ki ne dőljenek az úton.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 33, 'És mondának néki az ő tanítványai: Honnét volna e pusztában annyi kenyerünk, hogy megelégítsünk ily nagy sokaságot?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 34, 'És monda nékik Jézus: Hány kenyeretek van? Ők pedig mondának: Hét, és néhány halunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 35, 'És parancsolá a sokaságnak, hogy telepedjenek le a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 36, 'És vevén a hét kenyeret és a halakat, és hálákat adván, megtöré, és adá az ő tanítványainak, a tanítványok pedig a sokaságnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 37, 'És mindnyájan evének, és megelégedének; és fölszedék a maradék darabokat hét teli kosárral.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 38, 'A kik pedig ettek vala, négyezeren valának férfiak, asszonyokon és gyermekeken kívül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 39, 'És elbocsátván a sokaságot, beszálla a hajóba, és elméne Magdala határaiba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, 'És hozzá menvén a farizeusok és sadduczeusok, kisértvén, kérék őt, hogy mutasson nékik mennyei jelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, 'Ő pedig felelvén, monda nékik: Mikor estveledik, azt mondjátok: Szép idő lesz; mert veres az ég.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, 'Reggel pedig: Ma zivatar lesz; mert az ég borús és veres. Képmutatók, az ég ábrázatját meg tudjátok ítélni, az idők jeleit pedig nem tudjátok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, 'E gonosz és parázna nemzetség jelt kíván; és nem adatik néki jel, hanemha a Jónás prófétának jele. És ott hagyván őket, elméne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, 'És az ő tanítványai a tulsó partra menvén, elfelejtettek kenyeret vinni magukkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, 'Jézus pedig monda nékik: Vigyázzatok és őrizkedjetek a farizeusok és sadduczeusok kovászától.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, 'Ők pedig tanakodnak vala maguk között, mondván: Nem hoztunk kenyeret magunkkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, 'Jézus pedig megértvén ezt, monda nékik: Mit tanakodtok magatok között óh kicsinyhitűek, hogy kenyeret nem hoztatok magatokkal?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, 'Mégsem értitek-é, nem is emlékeztek-é az ötezernek öt kenyerére, és hogy hány kosárt töltöttetek meg?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, 'Sem a négyezernek hét kenyerére, és hogy hány kosárt töltöttetek meg?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, 'Hogyan nem értitek, hogy nem kenyérről mondtam néktek, hogy őrizkedjetek a farizeusok és sadduczeusok kovászától!?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, 'Ekkor értették meg, hogy nem arról szólott, hogy a kenyér kovászától, hanem hogy a farizeusok és sadduczeusok tudományától őrizkedjenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, 'Mikor pedig Jézus Czézárea Filippi környékére méne, megkérdé tanítványait, mondván: Engemet, embernek Fiát, kinek mondanak az emberek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, 'Ők pedig mondának: Némelyek Keresztelő Jánosnak, mások Illésnek; némelyek pedig Jeremiásnak, vagy egynek a próféták közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, 'Monda nékik: Ti pedig kinek mondotok engem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, 'Simon Péter pedig felelvén, monda: Te vagy a Krisztus, az élő Istennek Fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, 'És felelvén Jézus, monda néki: Boldog vagy Simon, Jónának fia, mert nem test és vér jelentette ezt meg néked, hanem az én mennyei Atyám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, 'De én is mondom néked, hogy te Péter vagy, és ezen a kősziklán építem fel az én anyaszentegyházamat, és a pokol kapui sem vesznek rajta diadalmat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, 'És néked adom a mennyek országának kulcsait; és a mit megkötsz a földön, a mennyekben is kötve lészen; és a mit megoldasz a földön, a mennyekben is oldva lészen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, 'Akkor megparancsolá tanítványainak, hogy senkinek se mondják, hogy ő a Jézus Krisztus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, 'Ettől fogva kezdé Jézus jelenteni az ő tanítványainak, hogy néki Jeruzsálembe kell menni, és sokat szenvedni a vénektől és a főpapoktól és az írástudóktól, és megöletni, és harmadnapon föltámadni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, 'És Péter előfogván őt, kezdé feddeni, mondván: Mentsen Isten, Uram! Nem eshetik ez meg te véled.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, 'Ő pedig megfordulván, monda Péternek: Távozz tőlem Sátán; bántásomra vagy nékem; mert nem gondolsz az Isten dolgaira, hanem az emberi dolgokra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, 'Ekkor monda Jézus az ő tanítványainak: Ha valaki jőni akar én utánam, tagadja meg magát és vegye fel az ő keresztjét, és kövessen engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, 'Mert a ki meg akarja tartani az ő életét, elveszti azt; a ki pedig elveszti az ő életét én érettem, megtalálja azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, 'Mert mit használ az embernek, ha az egész világot megnyeri is, de az ő lelkében kárt vall? Avagy micsoda váltságot adhat az ember az ő lelkéért?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, 'Mert az embernek Fia eljő az ő Atyjának dicsőségében, az ő angyalaival; és akkor megfizet mindenkinek az ő cselekedete szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, 'Bizony mondom néktek: Azok között, a kik itt állanak, vannak némelyek, a kik nem kóstolják meg a halált, a míg meg nem látják az embernek Fiát eljőni az ő országában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 1, 'És hat nap mulva magához vevé Jézus Pétert, Jakabot és ennek testvérét Jánost, és felvivé őket magokban egy magas hegyre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 2, 'És elváltozék előttök, és az ő orczája ragyog vala, mint a nap, ruhája pedig fehér lőn, mint a fényesség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 3, 'És ímé megjelenék ő nékik Mózes és Illés, a kik beszélnek vala ő vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 4, 'Péter pedig megszólalván, monda Jézusnak: Uram, jó nékünk itt lennünk. Ha akarod, építsünk itt három hajlékot, néked egyet, Mózesnek is egyet, Illésnek is egyet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 5, 'Mikor ő még beszél vala, ímé, fényes felhő borítá be őket; és ímé szózat lőn a felhőből, mondván: Ez az én szerelmes Fiam, a kiben én gyönyörködöm: őt hallgassátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 6, 'És a tanítványok a mint ezt hallák, arczra esének és igen megrémülének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 7, 'Jézus pedig hozzájok menvén, illeté őket, és monda: Keljetek fel és ne féljetek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 8, 'Mikor pedig szemeiket fölemelék, senkit sem látának, hanem csak Jézust egyedül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 9, 'És mikor a hegyről alájövének, megparancsolá nékik Jézus, mondván: Senkinek se mondjátok el a mit láttatok, míg fel nem támadt az embernek Fia a halálból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 10, 'És megkérdezék őt az ő tanítványai, mondván: Miért mondják tehát az írástudók, hogy előbb Illésnek kell eljőnie?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 11, 'Jézus pedig felelvén, monda nékik: Illés bizony eljő előbb, és mindent helyreállít;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 12, 'De mondom néktek, hogy Illés immár eljött, és nem ismerék meg őt, hanem azt mívelék vele, a mit akarának. Ezenképen az ember Fiának is szenvednie kell majd ő tőlük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 13, 'Ekkor megértették a tanítványok, hogy Keresztelő Jánosról szóla nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 14, 'És mikor a sokasághoz értek, egy ember jöve hozzá, térdre esvén ő előtte,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 15, 'És mondván: Uram, könyörülj az én fiamon, mert holdkóros és kegyetlenül szenved; mivelhogy gyakorta esik a tűzbe, és gyakorta a vízbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 16, 'És elvittem őt a te tanítványaidhoz, és nem tudták őt meggyógyítani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 17, 'Jézus pedig felelvén, monda: Óh hitetlen és elfajult nemzetség! vajjon meddig leszek veletek? vajjon meddig szenvedlek titeket? Hozzátok őt ide nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 18, 'És megdorgálá őt Jézus, és kiméne belőle az ördög; és meggyógyula a gyermek azon órától fogva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 19, 'Ekkor a tanítványok magukban Jézushoz menvén, mondának néki: Mi miért nem tudtuk azt kiűzni?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 20, 'Jézus pedig monda nékik: A ti hitetlenségetek miatt. Mert bizony mondom néktek: Ha akkora hitetek volna, mint a mustármag, azt mondanátok ennek a hegynek: Menj innen amoda, és elmenne; és semmi sem volna lehetetlen néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 21, 'Ez a fajzat pedig ki nem megy, hanemha könyörgés és bőjtölés által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 22, 'Mikor pedig Galileában jártak vala, monda nékik Jézus: Az ember Fia emberek kezébe adatik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 23, 'És megölik őt, de harmadnapon föltámad. És felettébb megszomorodának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 24, 'Mikor pedig eljutottak vala Kapernaumba, a kétdrakma-szedők Péterhez menének és mondának néki: A ti mesteretek nem fizeti-é a kétdrakmát?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 25, 'Monda: Igen. És mikor beméne a házba, megelőzé őt Jézus, mondván: Mit gondolsz Simon? A föld királyai kiktől szednek vámot vagy adót? a fiaiktól-é, vagy az idegenektől?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 26, 'Monda néki Péter: Az idegenektől. Monda néki Jézus: Tehát a fiak szabadok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 27, 'De hogy őket meg ne botránkoztassuk, menj a tengerre, vesd be a horgot, és vond ki az első halat, a mely rá akad: és felnyitván a száját, egy státert találsz benne: azt kivévén, add oda nékik én érettem és te éretted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 1, 'Abban az órában menének a tanítványok Jézushoz, mondván: Vajjon ki nagyobb a mennyeknek országában?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 2, 'És előhíván Jézus egy kis gyermeket, közéjök állítja vala azt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 3, 'És monda: Bizony mondom néktek, ha meg nem tértek és olyanok nem lesztek mint a kis gyermekek, semmiképen nem mentek be a mennyeknek országába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 4, 'A ki azért megalázza magát, mint ez a kis gyermek, az a nagyobb a mennyeknek országában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 5, 'És a ki egy ilyen kis gyermeket befogad az én nevemben, engem fogad be.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 6, 'A ki pedig megbotránkoztat egyet e kicsinyek közül, a kik én bennem hisznek, jobb annak, hogy malomkövet kössenek a nyakára, és a tenger mélységébe vessék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 7, 'Jaj a világnak a botránkozások miatt! Mert szükség, hogy botránkozások essenek; de jaj annak az embernek, a ki által a botránkozás esik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 8, 'Ha pedig a te kezed vagy a te lábad megbotránkoztat téged, vágd le azokat és vesd el magadtól; jobb néked az életre sántán vagy csonkán bemenned, hogynem két kézzel vagy két lábbal vettetned az örök tűzre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 9, 'És ha a te szemed botránkoztat meg téged, vájd ki azt és vesd el magadtól; jobb néked félszemmel bemenned az életre, hogynem két szemmel vettetned a gyehenna tüzére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 10, 'Meglássátok, hogy eme kicsinyek közül egyet is meg ne utáljatok; mert mondom néktek, hogy az ő angyalaik a mennyekben mindenkor látják az én mennyei Atyám orczáját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 11, 'Mert az embernek Fia azért jött, hogy megtartsa, a mi elveszett vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 12, 'Mit gondoltok? Ha valamely embernek száz juha van, és egy azok közül eltévelyedik: vajjon a kilenczvenkilenczet nem hagyja-é ott, és a hegyekre menvén, nem keresi-é azt, a melyik eltévelyedett?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 13, 'És ha történetesen megtalálja azt, bizony mondom néktek, inkább örvend azon, mint a kilenczvenkilenczen, a mely el nem tévelyedett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 14, 'Ekképen a ti mennyei Atyátok sem akarja, hogy egy is elveszszen e kicsinyek közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 15, 'Ha pedig a te atyádfia vétkezik ellened, menj el és dorgáld meg őt négy szem között: ha hallgat rád, megnyerted a te atyádfiát;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 16, 'Ha pedig nem hallgat rád, végy magad mellé még egyet vagy kettőt, hogy két vagy három tanú vallomásával erősíttessék minden szó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 17, 'Ha azokra nem hallgat, mondd meg a gyülekezetnek; ha a gyülekezetre sem hallgat, legyen előtted olyan, mint a pogány és a vámszedő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 18, 'Bizony mondom néktek: A mit megköttök a földön, a mennyben is kötve lészen; és a mit megoldotok a földön, a mennyben is oldva lészen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 19, 'Ismét, mondom néktek, hogy ha ketten közületek egy akaraton lesznek a földön minden dolog felől, a mit csak kérnek, megadja nékik az én mennyei Atyám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 20, 'Mert a hol ketten vagy hárman egybegyűlnek az én nevemben, ott vagyok közöttük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 21, 'Ekkor hozzámenvén Péter, monda: Uram, hányszor lehet az én atyámfiának ellenem vétkezni, és néki megbocsátanom? még hétszer is?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 22, 'Monda néki Jézus: Nem mondom néked, hogy még hétszer is, hanem még hetvenhétszer is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 23, 'Annakokáért hasonlatos a mennyeknek országa a királyhoz, a ki számot akar vala vetni az ő szolgáival.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 24, 'Mikor pedig számot kezde vetni, hozának eléje egyet, a ki tízezer tálentommal vala adós.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 25, 'Nem tudván pedig fizetni, parancsolá annak ura, hogy adják el azt, és a feleségét és gyermekeit, és mindenét, a mije vala, és fizessenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 26, 'Leborulván azért a szolga előtte, könyörög vala néki, mondván: Uram, légy türelemmel hozzám, és mindent megfizetek néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 27, 'Az úr pedig megszánván azt a szolgát, elbocsátá őt, és az adósságot is elengedé néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 28, 'Kimenvén pedig az a szolga, találkozék egygyel az ő szolgatársai közül, a ki száz dénárral vala néki adós; és megragadván azt, fojtogatja vala, mondván: Fizesd meg nékem, a mivel tartozol.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 29, 'Leborulván azért az ő szolgatársa az ő lábai elé, könyörög vala néki, mondván: Légy türelemmel hozzám, és mindent megfizetek néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 30, 'De ő nem akará; hanem elmenvén, börtönbe veté őt, mígnem megfizeti, a mivel tartozik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 31, 'Látván pedig az ő szolgatársai, a mik történtek vala, felettébb megszomorodának; és elmenvén, mindent megjelentének az ő uroknak, a mik történtek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 32, 'Akkor előhivatván őt az ő ura, monda néki: Gonosz szolga, minden adósságodat elengedtem néked, mivelhogy könyörögtél nékem:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 33, 'Nem kellett volna-é néked is könyörülnöd a te szolgatársadon, a miképen én is könyörültem te rajtad?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 34, 'És megharagudván az ő ura, átadta őt a hóhérok kezébe, mígnem megfizeti mind, a mivel tartozik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 35, 'Ekképen cselekszik az én mennyei Atyám is veletek, ha szivetekből meg nem bocsátjátok, kiki az ő atyjafiának, az ő vétkeiket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 1, 'És lőn, mikor elvégezte Jézus e beszédeket, elméne Galileából, és méne Júdeának határaiba a Jordánon túl;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 2, 'És követé őt nagy sokaság, és meggyógyítá ott őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 3, 'És hozzá menének a farizeusok, kisértvén őt és mondván: Szabad-é az embernek az ő feleségét akármi okért elbocsátani?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 4, 'Ő pedig felelvén, monda: Nem olvastátok-é, hogy a teremtő kezdettől fogva férfiúvá és asszonynyá teremté őket,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 5, 'És ezt mondá: Annak okáért elhagyja a férfiú atyját és anyját; és ragaszkodik feleségéhez, és lesznek ketten egy testté.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 6, 'Úgy hogy többé nem kettő, hanem egy test. A mit azért az Isten egybeszerkesztett, ember el ne válaszsza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 7, 'Mondának néki: Miért rendelte tehát Mózes, hogy válólevelet kell adni, és úgy bocsátani el az asszonyt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 8, 'Monda nékik: Mózes a ti szívetek keménysége miatt engedte volt meg néktek, hogy feleségeiteket elbocsássátok; de kezdettől fogva nem így volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 9, 'Mondom pedig néktek, hogy a ki elbocsátja feleségét, hanemha paráznaság miatt, és mást vesz el, házasságtörő; és a ki elbocsátottat vesz el, az is házasságtörő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 10, 'Mondának néki tanítványai: Ha így van a férfi dolga az asszonynyal, nem jó megházasodni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 11, 'Ő pedig monda nékik: Nem mindenki veszi be ezt a beszédet, hanem a kinek adatott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 12, 'Mert vannak heréltek, a kik anyjuk méhéből születtek így; és vannak heréltek, a kiket az emberek heréltek ki; és vannak heréltek, a kik maguk herélték ki magukat a mennyeknek országáért. A ki beveheti, vegye be.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 13, 'Ekkor kis gyermekeket hozának hozzá, hogy kezeit vesse azokra, és imádkozzék; a tanítványok pedig dorgálják vala azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 14, 'Jézus pedig monda: Hagyjatok békét e kis gyermekeknek, és ne tiltsátok meg nekik, hogy hozzám jőjjenek; mert ilyeneké a mennyeknek országa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 15, 'És kezeit reájuk vetvén, eltávozék onnét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 16, 'És ímé hozzá jövén egy ember, monda néki: Jó mester, mi jót cselekedjem, hogy örök életet nyerjek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 17, 'Ő pedig monda néki: Miért mondasz engem jónak? Senki sem jó, csak egy, az Isten. Ha pedig be akarsz menni az életre, tartsd meg a parancsolatokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 18, 'Monda néki: Melyeket? Jézus pedig monda: Ezeket: Ne ölj; ne paráználkodjál; ne lopj; hamis tanubizonyságot ne tégy;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 19, 'Tiszteld atyádat és anyádat; és: Szeresd felebarátodat, mint temagadat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 20, 'Monda néki az ifjú: Mindezeket megtartottam ifjúságomtól fogva; mi fogyatkozás van még bennem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 21, 'Monda néki Jézus: Ha tökéletes akarsz lenni, eredj, add el vagyonodat, és oszd ki a szegényeknek; és kincsed lesz mennyben; és jer és kövess engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 22, 'Az ifjú pedig e beszédet hallván, elméne megszomorodva; mert sok jószága vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 23, 'Jézus pedig monda az ő tanítványainak: Bizony mondom néktek, hogy a gazdag nehezen megy be a mennyeknek országába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 24, 'Ismét mondom pedig néktek: Könnyebb a tevének a tű fokán átmenni, hogynem a gazdagnak az Isten országába bejutni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 25, 'A tanítványok pedig ezeket hallván, felettébb álmélkodnak vala, mondván: Kicsoda üdvözülhet tehát?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 26, 'Jézus pedig rájuk tekintvén, monda nékik: Embereknél ez lehetetlen, de Istennél minden lehetséges.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 27, 'Akkor felelvén Péter, monda néki: Ímé, mi elhagytunk mindent és követtünk téged: mink lesz hát minékünk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 28, 'Jézus pedig monda nékik: Bizony mondom néktek, hogy ti, a kik követtetek engem, az újjá születéskor, a mikor az embernek Fia beül az ő dicsőségének királyi székébe, ti is beültök majd tizenkét királyi székbe, és ítélitek az Izráel tizenkét nemzetségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 29, 'És a ki elhagyta házait, vagy fitestvéreit, vagy nőtestvéreit, vagy atyját, vagy anyját, vagy feleségét, vagy gyermekeit, vagy szántóföldjeit az én nevemért, mindaz száz annyit vészen, és örökség szerint nyer örök életet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 30, 'Sok elsők pedig lesznek utolsók, és sok utolsók elsők.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 1, 'Mert hasonlatos a mennyeknek országa a gazdaemberhez, a ki jó reggel kiméne, hogy munkásokat fogadjon az ő szőlejébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 2, 'Megszerződvén pedig a munkásokkal napi tíz pénzben, elküldé őket az ő szőlejébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 3, 'És kimenvén három óra tájban, láta másokat, a kik hivalkodván a piaczon álltak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 4, 'És monda nékik: Menjetek el ti is a szőlőbe, és a mi igazságos, megadom néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 5, 'Azok pedig elmenének. Hat és kilencz óra tájban ismét kimenvén, ugyanazon képen cselekedék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 6, 'Tizenegy óra tájban is kimenvén, talála másokat, a kik hivalkodva állottak vala, és monda nékik: Miért álltok itt egész napon át, hivalkodván?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 7, 'Mondának néki: Mert senki sem fogadott meg minket. Monda nékik: Menjetek el ti is a szőlőbe, és a mi igazságos, megkapjátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 8, 'Mikor pedig beestveledék, monda a szőlőnek ura az ő vinczellérjének: Hívd elő a munkásokat, és add ki nékik a bért, az utolsóktól kezdve mind az elsőkig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 9, 'És jövén a tizenegyórásak, fejenként tíz-tíz pénzt vőnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 10, 'Jövén azután az elsők, azt gondolják vala, hogy ők többet kapnak: de ők is tíz-tíz pénzt vőnek fejenként.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 11, 'A mint pedig fölvevék, zúgolódnak vala a házigazda ellen,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 12, 'Mondván: Azok az utolsók egyetlen óráig munkálkodtak és egyenlőkké tetted azokat velünk, a kik a napnak terhét és hőségét szenvedtük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 13, 'Ő pedig felelvén, monda azok közül egynek: Barátom, nem cselekszem igazságtalanul veled; avagy nem tíz pénzben szerződtél-é meg velem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 14, 'Vedd, a mi a tiéd, és menj el. Én pedig ennek az utolsónak is annyit akarok adni, mint néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 15, 'Avagy nem szabad-é nékem a magaméval azt tennem, amit akarok? avagy a te szemed azért gonosz, mert én jó vagyok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 16, 'Ekképen lesznek az utolsók elsők és az elsők utolsók; mert sokan vannak a hivatalosok, de kevesen a választottak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 17, 'És mikor felmegy vala Jézus Jeruzsálembe, útközben csupán a tizenkét tanítványt vévén magához, monda nékik:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 18, 'Ímé, felmegyünk Jeruzsálembe, és az embernek Fia átadatik a főpapoknak és írástudóknak; és halálra kárhoztatják őt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 19, 'És a pogányok kezébe adják őt, hogy megcsúfolják és megostorozzák és keresztre feszítsék; de harmadnap feltámad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 20, 'Ekkor hozzá méne a Zebedeus fiainak anyja az ő fiaival együtt, leborulván és kérvén ő tőle valamit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 21, 'Ő pedig monda néki: Mit akarsz? Monda néki: Mondd, hogy ez az én két fiam üljön a te országodban egyik jobb kezed felől, a másik bal kezed felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 22, 'Jézus pedig felelvén, monda: Nem tudjátok, mit kértek. Megihatjátok-é a pohárt, a melyet én megiszom? és megkeresztelkedhettek-é azzal a keresztséggel, a melylyel én megkeresztelkedem? Mondának néki: Meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 23, 'És monda nékik: Az én poharamat megiszszátok ugyan, és a keresztséggel, a melylyel én megkeresztelkedem, megkeresztelkedtek; de az én jobb és balkezem felől való ülést nem az én dolgom megadni, hanem azoké lesz az, a kiknek az én Atyám elkészítette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 24, 'És hallva ezt a tíz, megboszankodék a két testvérre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 25, 'Jézus pedig előszólítván őket, monda: Tudjátok, hogy a pogányok fejedelmei uralkodnak azokon, és a nagyok hatalmaskodnak rajtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 26, 'De ne így legyen közöttetek; hanem a ki közöttetek nagy akar lenni, legyen a ti szolgátok;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 27, 'És a ki közöttetek első akar lenni, legyen a ti szolgátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 28, 'Valamint az embernek Fia nem azért jött, hogy néki szolgáljanak, hanem hogy ő szolgáljon, és adja az ő életét váltságul sokakért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 29, 'És mikor Jerikóból távozának, nagy sokaság követé őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 30, 'És ímé, két vak, a ki az út mellett ül vala, meghallván, hogy Jézus arra megy el, kiált vala, mondván: Uram, Dávidnak Fia, könyörülj rajtunk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 31, 'A sokaság pedig dorgálja vala őket, hogy hallgassanak; de azok annál jobban kiáltnak vala, mondván: Uram, Dávidnak Fia, könyörülj rajtunk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 32, 'És megállván Jézus, megszólítá őket és monda: Mit akartok, hogy cselekedjem veletek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 33, 'Mondának néki: Azt, Uram, hogy megnyíljanak a mi szemeink.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 34, 'Jézus pedig megszánván őket, illeté az ő szemeiket; és szemeik azonnal megnyíltak; és követék őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 1, 'És mikor közeledtek Jeruzsálemhez, és Bethfagéba, az olajfák hegyéhez jutottak vala, akkor elkülde Jézus két tanítványt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 2, 'És monda nékik: Menjetek ebbe a faluba, a mely előttetek van, és legott találtok egy megkötött szamarat és vele együtt az ő vemhét; oldjátok el és hozzátok ide nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 3, 'És ha valaki valamit szól néktek, mondjátok, hogy az Úrnak van szüksége rájuk: és legott el fogja bocsátani őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 4, 'Mindez pedig azért lett, hogy beteljesedjék a próféta mondása, a ki így szólott:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 5, 'Mondjátok meg Sion leányának: Ímhol jő néked a te királyod, alázatosan és szamáron ülve, és teherhordozó szamárnak vemhén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 6, 'A tanítványok pedig elmenvén és úgy cselekedvén, a mint Jézus parancsolta vala nékik,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 7, 'Elhozák a szamarat és annak vemhét, és felső ruháikat rájuk teríték, és ráüle azokra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 8, 'A sokaság legnagyobb része pedig felső ruháit az útra teríté; mások pedig a fákról galyakat vagdalnak és hintenek vala az útra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 9, 'Az előtte és utána menő sokaság pedig kiált vala, mondván: Hozsánna a Dávid fiának! Áldott, a ki jő az Úrnak nevében! Hozsánna a magasságban!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 10, 'És a mikor bemegy vala Jeruzsálembe, felháborodék az egész város, mondván: Kicsoda ez?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 11, 'A sokaság pedig monda: Ez Jézus, a galileai Názáretből való próféta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 12, 'És beméne Jézus az Isten templomába, és kiűzé mindazokat, a kik árulnak és vásárolnak vala a templomban; és a pénzváltók asztalait és a galambárusok székeit felforgatá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 13, 'És monda nékik: Meg van írva: Az én házam imádság házának mondatik. Ti pedig azt latroknak barlangjává tettétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 14, 'És menének hozzá vakok és sánták a templomban; és meggyógyítá őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 15, 'A főpapok és írástudók pedig, látván a csodákat, a melyeket cselekedett vala, és a gyermekeket, a kik kiáltottak vala a templomban, és ezt mondták vala: Hozsánna a Dávid fiának; haragra gerjedének,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 16, 'És mondának néki: Hallod, mit mondanak ezek? Jézus pedig monda nékik: Hallom. Sohasem olvastátok-é: A gyermekek és csecsemők szája által szereztél dicsőséget?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 17, 'És ott hagyván őket, kiméne a városból Bethániába, és ott marada éjjel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 18, 'Reggel pedig, a városba visszajövet, megéhezék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 19, 'És meglátva egy fügefát az út mellett, oda méne hozzá, és nem talála azon semmit, hanem csak levelet; és monda annak: Gyümölcs te rajtad ezután soha örökké ne teremjen. És a fügefa azonnal elszárada.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 20, 'És látván ezt a tanítványok, elcsodálkozának, mondván: Hogyan száradt el a fügefa oly hirtelen?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 21, 'Jézus pedig felelvén, monda nékik: Bizony mondom néktek, ha van hitetek és nem kételkedtek, nemcsak azt cselekszitek, a mi e fügefán esett, hanem ha azt mondjátok e hegynek: Kelj fel és zuhanj a tengerbe, az is meglészen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 22, 'És a mit könyörgéstekben kértek, mindazt meg is kapjátok, ha hisztek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 23, 'És mikor bement vala a templomba, hozzámenének a főpapok és a nép vénei, a mint tanít vala, mondván: Micsoda hatalommal cselekszed ezeket? és ki adta néked ezt a hatalmat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 24, 'Jézus pedig felelvén, monda nékik: Én is kérdek egy dolgot tőletek, a mire ha megfeleltek nékem, én is megmondom néktek, micsoda hatalommal cselekszem ezeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 25, 'A János keresztsége honnan vala? Mennyből-é, vagy emberektől? Azok pedig tanakodnak vala magukban, mondván: Ha azt mondjuk: mennyből, azt mondja majd nékünk: Miért nem hittetek tehát néki?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 26, 'Ha pedig azt mondjuk: emberektől; félünk a sokaságtól; mert Jánost mindnyájan prófétának tartják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 27, 'És felelvén Jézusnak, mondának: Nem tudjuk. Monda nékik ő is: Én sem mondom meg néktek, micsoda hatalommal cselekszem ezeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 28, 'De mit gondoltok ti? Vala egy embernek két fia, és odamenvén az elsőhöz, monda: Eredj fiam, munkálkodjál ma az én szőlőmben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 29, 'Az pedig felelvén, monda: Nem megyek; de azután meggondolván magát, elméne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 30, 'A másikhoz is odamenvén, hasonlóképen szóla. Az pedig felelvén, monda: Én elmegyek, uram; de nem méne el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 31, 'E kettő közül melyik teljesítette az atya akaratát? Mondának néki: Az első. Monda nékik Jézus: Bizony mondom néktek: A vámszedők és a parázna nők megelőznek titeket az Isten országában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 32, 'Mert eljött hozzátok János, az igazság útján, és nem hittetek néki, a vámszedők és a parázna nők pedig hittek néki; ti pedig, a kik ezt láttátok, azután sem tértetek meg, hogy hittetek volna néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 33, 'Más példázatot halljatok: Vala egy házigazda, a ki szőlőt plántála, és azt gyepűvel körülvevé, sajtót ása le benne, és tornyot építe, és kiadá azt munkásoknak, és elutazék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 34, 'Mikor pedig a gyümölcs ideje elérkezett vala, elküldé szolgáit a munkásokhoz, hogy vegyék át az ő gyümölcsét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 35, 'És a munkások megfogván az ő szolgáit, az egyiket megverék, a másikat megölék, a harmadikat pedig megkövezék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 36, 'Ismét külde más szolgákat, többet mint előbb; és azokkal is úgy cselekedének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 37, 'Utoljára pedig elküldé azokhoz a maga fiát, ezt mondván: A fiamat meg fogják becsülni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 38, 'De a munkások, meglátván a fiút, mondának magok közt: Ez az örökös; jertek, öljük meg őt, és foglaljuk el az ő örökségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 39, 'És megfogván őt, kiveték a szőlőn kívül és megölék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 40, 'Mikor azért megjő a szőlőnek ura, mit cselekszik ezekkel a munkásokkal?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 41, 'Mondának néki: Mint gonoszokat gonoszul elveszti őket; a szőlőt pedig kiadja más munkásoknak, a kik beadják majd néki a gyümölcsöt annak idejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 42, 'Monda nékik Jézus: Sohasem olvastátok-é az írásokban: A mely követ az építők megvetettek, az lett a szegletnek feje; az Úrtól lett ez, és csodálatos a mi szemeink előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 43, 'Annakokáért mondom néktek, hogy elvétetik tőletek az Istennek országa, és oly népnek adatik, a mely megtermi annak gyümölcsét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 44, 'És a ki e kőre esik, szétzúzatik; a kire pedig ez esik reá, szétmorzsolja azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 45, 'És a főpapok és farizeusok hallván az ő példázatait, megértették, hogy róluk szól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 46, 'És mikor meg akarák őt fogni, megfélemlének a sokaságtól, mivelhogy úgy tartják vala őt mint prófétát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 1, 'És megszólalván Jézus, ismét példázatokban beszél vala nékik, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 2, 'Hasonlatos a mennyeknek országa a királyhoz, a ki az ő fiának menyegzőt szerze.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 3, 'És elküldé szolgáit, hogy meghívják azokat, a kik a menyegzőre hivatalosak valának; de nem akarnak vala eljőni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 4, 'Ismét külde más szolgákat, mondván: Mondjátok meg a hivatalosoknak: Ímé, ebédemet elkészítettem, tulkaim és hízlalt állataim levágva vannak, és kész minden; jertek el a menyegzőre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 5, 'De azok nem törődvén vele, elmenének, az egyik a maga szántóföldjére, a másik a maga kereskedésébe;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 6, 'A többiek pedig megfogván az ő szolgáit, bántalmazák és megölék őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 7, 'Meghallván pedig ezt a király, megharaguvék, és elküldvén hadait, azokat a gyilkosokat elveszté, és azoknak városait fölégeté.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 8, 'Akkor monda az ő szolgáinak: A menyegző ugyan készen van, de a hivatalosok nem valának méltók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 9, 'Menjetek azért a keresztútakra, és a kiket csak találtok, hívjátok be a menyegzőbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 10, 'És kimenvén azok a szolgák az útakra, begyűjték mind a kiket csak találtak vala, jókat és gonoszokat egyaránt. És megtelék a menyegző vendégekkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 11, 'Bemenvén pedig a király, hogy megtekintse a vendégeket, láta ott egy embert, a kinek nem vala menyegzői ruhája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 12, 'És monda néki: Barátom, mi módon jöttél ide, holott nincsen menyegzői ruhád? Az pedig hallgata.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 13, 'Akkor monda a király a szolgáknak: Kötözzétek meg a lábait és kezeit, és vigyétek és vessétek őt a külső sötétségre; ott lészen sírás és fogcsikorgatás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 14, 'Mert sokan vannak a hivatalosok, de kevesen a választottak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 15, 'Ekkor a farizeusok elmenvén, tanácsot tartának, hogy szóval ejtsék őt tőrbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 16, 'És elküldék hozzá tanítványaikat a Heródes pártiakkal, a kik ezt mondják vala: Mester, tudjuk, hogy igaz vagy és az Isten útját igazán tanítod, és nem törődöl senkivel, mert embereknek személyére nem nézel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 17, 'Mondd meg azért nékünk, mit gondolsz: Szabad-é a császárnak adót fizetnünk, vagy nem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 18, 'Jézus pedig ismervén az ő álnokságukat, monda: Mit kisértgettek engem, képmutatók?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 19, 'Mutassátok nékem az adópénzt. Azok pedig oda vivének néki egy dénárt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 20, 'És monda nékik: Kié ez a kép, és a felírás?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 21, 'Mondának néki: A császáré. Akkor monda nékik: Adjátok meg azért a mi a császáré a császárnak; és a mi az Istené, az Istennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 22, 'És ezt hallván, elcsodálkozának; és ott hagyván őt, elmenének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 23, 'Ugyanazon a napon menének hozzá a sadduczeusok, a kik a feltámadást tagadják, és megkérdezék őt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 24, 'Mondván: Mester, Mózes azt mondotta: Ha valaki magzatok nélkül hal meg, annak testvére vegye el annak feleségét, és támaszszon magot testvérének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 25, 'Vala pedig minálunk hét testvér: és az első feleséget vevén, meghala; és mivelhogy nem vala magzata, feleségét a testvérére hagyá;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 26, 'Hasonlóképen a második is, a harmadik is, mind hetediglen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 27, 'Legutoljára pedig az asszony is meghala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 28, 'A feltámadáskor azért a hét közül melyiké lesz az asszony? Mert mindeniké vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 29, 'Jézus pedig felelvén, monda nékik: Tévelyegtek, mivelhogy nem ismeritek sem az írásokat, sem az Istennek hatalmát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 30, 'Mert a feltámadáskor sem nem házasodnak, sem férjhez nem mennek, hanem olyanok lesznek, mint az Isten angyalai a mennyben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 31, 'A halottak feltámadása felől pedig nem olvastátok-é, a mit az Isten mondott néktek, így szólván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 32, 'Én vagyok az Ábrahám Istene, és az Izsák Istene, és a Jákób Istene; az Isten nem holtaknak, hanem élőknek Istene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 33, 'És a sokaság ezt hallván, csodálkozék az ő tudományán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 34, 'A farizeusok pedig, hallván, hogy a sadduczeusokat elnémította vala, egybegyűlének;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 35, 'És megkérdé őt közülök egy törvénytudó, kisértvén őt, és mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 36, 'Mester, melyik a nagy parancsolat a törvényben?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 37, 'Jézus pedig monda néki: Szeresd az Urat, a te Istenedet teljes szívedből, teljes lelkedből és teljes elmédből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 38, 'Ez az első és nagy parancsolat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 39, 'A második pedig hasonlatos ehhez: Szeresd felebarátodat, mint magadat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 40, 'E két parancsolattól függ az egész törvény és a próféták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 41, 'Mikor pedig a farizeusok összegyülekezének, kérdezé őket Jézus,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 42, 'Mondván: Miképen vélekedtek ti a Krisztus felől? kinek a fia? Mondának néki: A Dávidé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 43, 'Monda nékik: Miképen hívja tehát őt Dávid lélekben Urának, ezt mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 44, 'Monda az Úr az én Uramnak: Ülj az én jobb kezem felől, míglen vetem a te ellenségeidet a te lábaid alá zsámolyul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 45, 'Ha tehát Dávid Urának hívja őt, mi módon fia?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 46, 'És senki egy szót sem felelhet vala néki; sem pedig nem meri vala őt e naptól fogva többé senki megkérdezni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 1, 'Akkor szóla Jézus a sokaságnak és az ő tanítványainak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 2, 'Mondván: Az írástudók és a farizeusok a Mózes székében ülnek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 3, 'Annakokáért a mit parancsolnak néktek, mindazt megtartsátok és megcselekedjétek; de az ő cselekedeteik szerint ne cselekedjetek. Mert ők mondják, de nem cselekszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 4, 'Mert ők nehéz és elhordozhatatlan terheket kötöznek egybe, és az emberek vállaira vetik; de ők az ujjokkal sem akarják azokat illetni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 5, 'Minden ő dolgaikat pedig csak azért cselekszik, hogy lássák őket az emberek: mert megszélesítik az ő homlokszíjjaikat; és megnagyobbítják az ő köntöseik peremét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 6, 'És szeretik a lakomákon a főhelyet, és a gyülekezetekben az elölűlést.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 7, 'És a piaczokon való köszöntéseket, és hogy az emberek így hívják őket: Mester, Mester!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 8, 'Ti pedig ne hivassátok magatokat Mesternek, mert egy a ti Mesteretek, a Krisztus; ti pedig mindnyájan testvérek vagytok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 9, 'Atyátoknak se hívjatok senkit e földön; mert egy a ti Atyátok, a ki a mennyben van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 10, 'Doktoroknak se hivassátok magatokat, mert egy a ti Doktorotok, a Krisztus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 11, 'Hanem a ki a nagyobb közöttetek, legyen a ti szolgátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 12, 'Mert a ki magát felmagasztalja, megaláztatik; és a ki magát megalázza, felmagasztaltatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 13, 'De jaj néktek képmutató írástudók és farizeusok, mert a mennyeknek országát bezárjátok az emberek előtt; mivelhogy ti nem mentek be, a kik be akarnának menni, azokat sem bocsátjátok be.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 14, 'Jaj néktek képmutató írástudók és farizeusok, mert felemésztitek az özvegyek házát, és színből hosszan imádkoztok; ezért annál súlyosabb lesz a ti büntetéstek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 15, 'Jaj néktek képmutató írástudók és farizeusok! mert megkerülitek a tengert és a földet, hogy egy pogányt zsidóvá tegyetek; és ha azzá lett, a gyehenna fiává teszitek őt, kétszerte inkább magatoknál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 16, 'Jaj néktek vak vezérek, a kik ezt mondjátok: Ha valaki a templomra esküszik, semmi az; de ha valaki a templom aranyára esküszik, tartozik az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 17, 'Bolondok és vakok: mert melyik nagyobb, az arany-é, vagy a templom, a mely szentté teszi az aranyat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 18, 'És: Ha valaki az oltárra esküszik, semmi az; de ha valaki a rajta levő ajándékra esküszik, tartozik az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 19, 'Bolondok és vakok: mert melyik nagyobb, az ajándék-é vagy az oltár, a mely szentté teszi az ajándékot?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 20, 'A ki azért az oltárra esküszik, esküszik arra és mindazokra, a mik azon vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 21, 'És a ki a templomra esküszik, esküszik arra és Arra, a ki abban lakozik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 22, 'És a ki az égre esküszik, esküszik az Isten királyiszékére és arra, ki abban ül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 23, 'Jaj néktek képmutató írástudók és farizeusok! mert megdézsmáljátok a mentát, a kaprot és a köményt, és elhagyjátok a mik nehezebbek a törvényben, az ítéletet, az irgalmasságot és a hívséget: pedig ezeket kellene cselekedni, és amazokat sem elhagyni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 24, 'Vak vezérek, a kik megszűritek a szúnyogot, a tevét pedig elnyelitek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 25, 'Jaj néktek képmutató írástudók és farizeusok! mert megtisztítjátok a pohárnak és tálnak külsejét, belől pedig rakvák azok ragadománynyal és mértékletlenséggel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 26, 'Vak farizeus, tisztítsd meg előbb a pohár és tál belsejét, hogy külsejük is tiszta legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 27, 'Jaj néktek képmutató írástudók és farizeusok, mert hasonlatosak vagytok a meszelt sírokhoz, a melyek kívülről szépeknek tetszenek, belől pedig holtaknak csontjaival és minden undoksággal rakvák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 28, 'Épen így ti is, kívülről igazaknak látszotok ugyan az emberek előtt, de belől rakva vagytok képmutatással és törvénytelenséggel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 29, 'Jaj néktek képmutató írástudók és farizeusok! mert építitek a próféták sírjait és ékesgetitek az igazak síremlékeit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 30, 'És ezt mondjátok: Ha mi atyáink korában éltünk volna, nem lettünk volna az ő bűntársaik a próféták vérében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 31, 'Így hát magatok ellen tesztek bizonyságot, hogy fiai vagytok azoknak, a kik megölték a prófétákat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 32, 'Töltsétek be ti is a ti atyáitoknak mértékét!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 33, 'Kígyók, mérges kígyóknak fajzatai, miképen kerülitek ki a gyehennának büntetését?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 34, 'Annakokáért ímé prófétákat, bölcseket és írástudókat küldök én hozzátok: és azok közül némelyeket megöltök, és megfeszítetek, másokat azok közül a ti zsinagógáitokban megostoroztok és városról-városra üldöztök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 35, 'Hogy reátok szálljon minden igaz vér, a mely kiömlött a földön, az igaz Ábelnek vérétől Zakariásnak, a Barakiás fiának véréig, a kit a templom és az oltár között megöltetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 36, 'Bizony mondom néktek, mindezek reá következnek erre a nemzetségre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 37, 'Jeruzsálem, Jeruzsálem! Ki megölöd a prófétákat és megkövezed azokat, a kik te hozzád küldettek, hányszor akartam egybegyűjteni a te fiaidat, miképen a tyúk egybegyűjti kis csirkéit szárnya alá; és te nem akartad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 38, 'Ímé, pusztán hagyatik néktek a ti házatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 39, 'Mert mondom néktek: Mostantól fogva nem láttok engem mindaddig, mígnem ezt mondjátok: Áldott, a ki jő az Úrnak nevében!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 1, 'És kijővén Jézus a templomból, tovább méne; és hozzámenének az ő tanítványai, hogy mutogassák néki a templom épületeit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 2, 'Jézus pedig monda nékik: Nem látjátok-é mind ezeket? Bizony mondom néktek: Nem marad itt kő kövön, mely le nem romboltatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 3, 'Mikor pedig az olajfák hegyén ül vala, hozzá menének a tanítványok magukban mondván: Mondd meg nékünk, mikor lesznek meg ezek? és micsoda jele lesz a te eljövetelednek, és a világ végének?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 4, 'És Jézus felelvén, monda nékik: Meglássátok, hogy valaki el ne hitessen titeket,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 5, 'Mert sokan jőnek majd az én nevemben, a kik ezt mondják: Én vagyok a Krisztus; és sokakat elhitetnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 6, 'Hallanotok kell majd háborúkról és háborúk híreiről: meglássátok, hogy meg ne rémüljetek; mert mindezeknek meg kell lenniök. De még ez nem itt a vég.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 7, 'Mert nemzet támad nemzet ellen, és ország ország ellen; és lésznek éhségek és döghalálok, és földindulások mindenfelé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 8, 'Mind ez pedig a sok nyomorúságnak kezdete.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 9, 'Akkor nyomorúságra adnak majd benneteket, és megölnek titeket; és gyűlöletesek lesztek minden nép előtt az én nevemért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 10, 'És akkor sokan megbotránkoznak, és elárulják egymást, és gyűlölik egymást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 11, 'És sok hamis próféta támad, a kik sokakat elhitetnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 12, 'És mivelhogy a gonoszság megsokasodik, a szeretet sokakban meghidegül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 13, 'De a ki mindvégig állhatatos marad, az idvezül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 14, 'És az Isten országának ez az evangyélioma hirdettetik majd az egész világon, bizonyságul minden népnek; és akkor jő el a vég.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 15, 'Mikor azért látjátok majd, hogy az a pusztító utálatosság, a melyről Dániel próféta szólott, ott áll a szent helyen (a ki olvassa, értse meg):');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 16, 'Akkor, a kik Júdeában lesznek, fussanak a hegyekre;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 17, 'A ház tetején levő ne szálljon alá, hogy házából valamit kivigyen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 18, 'És a mezőn levő ne térjen vissza, hogy az ő ruháját elvigye.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 19, 'Jaj pedig a terhes és szoptató asszonyoknak azokon a napokon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 20, 'Imádkozzatok pedig, hogy a ti futástok ne télen legyen, se szombatnapon:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 21, 'Mert akkor nagy nyomorúság lesz, a milyen nem volt a világ kezdete óta mind ez ideig, és nem is lesz soha.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 22, 'És ha azok a napok meg nem rövidíttetnének, egyetlen ember sem menekülhetne meg; de a választottakért megrövidíttetnek majd azok a napok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 23, 'Ha valaki ezt mondja akkor néktek: Ímé, itt a Krisztus, vagy amott; ne higyjétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 24, 'Mert hamis Krisztusok és hamis próféták támadnak, és nagy jeleket és csodákat tesznek, annyira, hogy elhitessék, ha lehet, a választottakat is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 25, 'Ímé eleve megmondottam néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 26, 'Azért ha azt mondják majd néktek: Ímé a pusztában van; ne menjetek ki. Ímé a belső szobákban; ne higyjétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 27, 'Mert a miképen a villámlás napkeletről támad és ellátszik egész napnyugtáig, úgy lesz az ember Fiának eljövetele is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 28, 'Mert a hol a dög, oda gyűlnek a keselyűk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 29, 'Mindjárt pedig ama napok nyomorúságai után a nap elsötétedik, és a hold nem fénylik, és a csillagok az égről lehullanak, és az egeknek erősségei megrendülnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 30, 'És akkor feltetszik az ember Fiának jele az égen. És akkor sír a föld minden nemzetsége, és meglátják az embernek Fiát eljőni az ég felhőiben nagy hatalommal és dicsőséggel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 31, 'És elküldi az ő angyalait nagy trombitaszóval, és egybegyűjtik az ő választottait a négy szelek felől, az ég egyik végétől a másik végéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 32, 'A fügefáról vegyétek pedig a példát: mikor az ága már zsendül, és levelet hajt, tudjátok, hogy közel van a nyár:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 33, 'Azonképen ti is, mikor mindezeket látjátok, tudjátok meg, hogy közel van, az ajtó előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 34, 'Bizony mondom néktek, el nem múlik ez a nemzetség, mígnem mindezek meglesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 35, 'Az ég és a föld elmúlnak, de az én beszédeim semmiképen el nem múlnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 36, 'Arról a napról és óráról pedig senki sem tud, az ég angyalai sem, hanem csak az én Atyám egyedül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 37, 'A miképen pedig a Noé napjaiban vala, akképen lesz az ember Fiának eljövetele is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 38, 'Mert a miképen az özönvíz előtt való napokban esznek és isznak vala, házasodnak és férjhez mennek vala, mind ama napig, a melyen Noé a bárkába méne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 39, 'És nem vesznek vala észre semmit, mígnem eljöve az özönvíz és mindnyájukat elragadá: akképen lesz az ember Fiának eljövetele is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 40, 'Akkor ketten lesznek a mezőn; az egyik felvétetik, a másik ott hagyatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 41, 'Két asszony őröl a malomban; az egyik felvétetik, a másik ott hagyatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 42, 'Vigyázzatok azért, mert nem tudjátok, mely órában jő el a ti Uratok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 43, 'Azt pedig jegyezzétek meg, hogy ha tudná a ház ura, hogy az éjszakának melyik szakában jő el a tolvaj: vigyázna, és nem engedné, hogy házába törjön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 44, 'Azért legyetek készen ti is; mert a mely órában nem gondoljátok, abban jő el az embernek Fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 45, 'Kicsoda hát a hű és bölcs szolga, a kit az ő ura gondviselővé tőn az ő házanépén, hogy a maga idejében adjon azoknak eledelt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 46, 'Boldog az a szolga, a kit az ő ura, mikor haza jő, ily munkában talál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 47, 'Bizony mondom néktek, hogy minden jószága fölött gondviselővé teszi őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 48, 'Ha pedig ama gonosz szolga így szólna az ő szívében: Halogatja még az én uram a hazajövetelt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 49, 'És az ő szolgatársait verni kezdené, a részegesekkel pedig enni és inni kezdene:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 50, 'Megjő annak a szolgának az ura, a mely napon nem várja és a mely órában nem gondolja,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 51, 'És ketté vágatja őt, és a képmutatók sorsára juttatja; ott lészen sírás és fogcsikorgatás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 1, 'Akkor hasonlatos lesz a mennyeknek országa ama tíz szűzhöz, a kik elővevén az ő lámpásaikat, kimenének a vőlegény elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 2, 'Öt pedig közülök eszes vala, és öt bolond.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 3, 'A kik bolondok valának, mikor lámpásaikat elővevék, nem vivének magukkal olajat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 4, 'Az eszesek pedig lámpásaikkal együtt olajat vivének az ő edényeikben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 5, 'Késvén pedig a vőlegény, mindannyian elszunnyadának és aluvának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 6, 'Éjfélkor pedig kiáltás lőn: Ímhol jő a vőlegény! Jőjjetek elébe!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 7, 'Akkor felkelének mind azok a szűzek, és elkészíték az ő lámpásaikat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 8, 'A bolondok pedig mondának az eszeseknek: Adjatok nékünk a ti olajotokból, mert a mi lámpásaink kialusznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 9, 'Az eszesek pedig felelének, mondván: Netalán nem lenne elegendő nékünk és néktek; menjetek inkább az árúsokhoz, és vegyetek magatoknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 10, 'Mikor pedig venni járnak vala, megérkezék a vőlegény; és a kik készen valának, bemenének ő vele a menyegzőbe, és bezáraték az ajtó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 11, 'Később pedig a többi szűzek is megjövének, mondván: Uram! Uram! nyisd meg mi nékünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 12, 'Ő pedig felelvén, monda: Bizony mondom néktek, nem ismerlek titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 13, 'Vigyázzatok azért, mert sem a napot, sem az órát nem tudjátok, a melyen az embernek Fia eljő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 14, 'Mert épen úgy van ez, mint az az ember, a ki útra akarván kelni, eléhívatá az ő szolgáit, és a mije volt, átadá nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 15, 'És ada az egyiknek öt tálentomot, a másiknak kettőt, a harmadiknak pedig egyet, kinek-kinek az ő erejéhez képest; és azonnal útra kele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 16, 'Elmenvén pedig a ki az öt tálentomot kapta vala, kereskedék azokkal, és szerze más öt tálentomot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 17, 'Azonképen a kié a kettő vala, az is más kettőt nyere.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 18, 'A ki pedig az egyet kapta vala, elmenvén, elásá azt a földbe, és elrejté az ő urának pénzét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 19, 'Sok idő múlva pedig megjöve ama szolgáknak ura, és számot vete velök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 20, 'És előjövén a ki az öt tálentomot kapta vala, hoza más öt tálentomot, mondván: Uram, öt tálentomot adtál vala nékem; ímé más öt tálentomot nyertem azokon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 21, 'Az ő ura pedig monda néki: Jól vagyon jó és hű szolgám, kevesen voltál hű, sokra bízlak ezután; menj be a te uradnak örömébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 22, 'Előjövén pedig az is, a ki a két tálentomot kapta vala, monda: Uram, két tálentomot adtál volt nékem; ímé más két tálentomot nyertem azokon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 23, 'Monda néki az ő ura: Jól vagyon jó és hű szolgám, kevesen voltál hű, sokra bízlak ezután; menj be a te uradnak örömébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 24, 'Előjövén pedig az is, a ki az egy tálentomot kapta vala, monda: Uram, tudtam, hogy te kegyetlen ember vagy, a ki ott is aratsz, a hol nem vetettél, és ott is takarsz, a hol nem vetettél;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 25, 'Azért félvén, elmentem és elástam a te tálentomodat a földbe; ímé megvan a mi a tied.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 26, 'Az ő ura pedig felelvén, monda néki: Gonosz és rest szolga, tudtad, hogy ott is aratok, a hol nem vetettem, és ott is takarok, a hol nem vetettem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 27, 'El kellett volna tehát helyezned az én pénzemet a pénzváltóknál; és én, megjövén, nyereséggel kaptam volna meg a magamét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 28, 'Vegyétek el azért tőle a tálentomot, és adjátok annak, a kinek tíz tálentoma van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 29, 'Mert mindenkinek, a kinek van, adatik, és megszaporíttatik; a kinek pedig nincsen, attól az is elvétetik, a mije van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 30, 'És a haszontalan szolgát vessétek a külső sötétségre; ott lészen sírás és fogcsikorgatás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 31, 'Mikor pedig eljő az embernek Fia az ő dicsőségében, és ő vele mind a szent angyalok, akkor beül majd az ő dicsőségének királyiszékébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 32, 'És elébe gyűjtetnek mind a népek, és elválasztja őket egymástól, miként a pásztor elválasztja a juhokat a kecskéktől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 33, 'És a juhokat jobb keze felől, a kecskéket pedig bal keze felől állítja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 34, 'Akkor ezt mondja a király a jobb keze felől állóknak: Jertek, én Atyámnak áldottai, örököljétek ez országot, a mely számotokra készíttetett a világ megalapítása óta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 35, 'Mert éheztem, és ennem adtatok; szomjúhoztam, és innom adtatok; jövevény voltam, és befogadtatok engem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 36, 'Mezítelen voltam, és megruháztatok; beteg voltam, és meglátogattatok; fogoly voltam, és eljöttetek hozzám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 37, 'Akkor felelnek majd néki az igazak, mondván: Uram, mikor láttuk, hogy éheztél, és tápláltunk volna? vagy szomjúhoztál, és innod adtunk volna?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, 'És mikor láttuk, hogy jövevény voltál, és befogadtunk volna? vagy mezítelen voltál, és felruháztunk volna?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, 'Mikor láttuk, hogy beteg vagy fogoly voltál, és hozzád mentünk volna?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, 'És felelvén a király, azt mondja majd nékik: Bizony mondom néktek, a mennyiben megcselekedtétek egygyel az én legkisebb atyámfiai közül, én velem cselekedtétek meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, 'Akkor szól majd az ő bal keze felől állókhoz is: Távozzatok tőlem, ti átkozottak, az örök tűzre, a mely az ördögöknek és az ő angyalainak készíttetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, 'Mert éheztem, és nem adtatok ennem; szomjúhoztam, és nem adtatok innom;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, 'Jövevény voltam, és nem fogadtatok be engem; mezítelen voltam, és nem ruháztatok meg engem; beteg és fogoly voltam, és nem látogattatok meg engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, 'Akkor ezek is felelnek majd néki, mondván: Uram, mikor láttuk, hogy éheztél, vagy szomjúhoztál, vagy hogy jövevény, vagy mezítelen, vagy beteg, vagy fogoly voltál, és nem szolgáltunk volna néked?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, 'Akkor felel majd nékik, mondván: Bizony mondom néktek, a mennyiben nem cselekedtétek meg egygyel eme legkisebbek közül, én velem sem cselekedtétek meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, 'És ezek elmennek majd az örök gyötrelemre; az igazak pedig az örök életre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, 'És mikor mindezeket a beszédeket elvégezte vala Jézus, monda az ő tanítványainak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 2, 'Tudjátok, hogy két nap mulva a husvétnak ünnepe lészen, és az embernek Fia elárultatik, hogy megfeszíttessék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 3, 'Akkor egybegyűlének a főpapok, az írástudók és a nép vénei a főpap házába, a kit Kajafásnak hívtak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 4, 'És tanácsot tartának, hogy Jézust álnoksággal megfogják és megöljék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 5, 'De azt mondják vala: Ne az ünnepen: hogy zendülés ne legyen a nép között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 6, 'És mikor Jézus Bethániában, a poklos Simon házánál vala,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 7, 'Méne ő hozzá egy asszony, a kinél vala drága kenetnek alabástrom szelenczéje, és az ő fejére tölté, a mint az asztalnál ül vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 8, 'Látván pedig ezt az ő tanítványai, bosszankodának, mondván: Mire való ez a tékozlás?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 9, 'Mert eladhatták volna ezt a kenetet nagy áron, és adhatták volna a szegényeknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 10, 'Mikor pedig ezt eszébe vette Jézus, monda nékik: Miért bántjátok ezt az asszonyt? hiszen jó dolgot cselekedett én velem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 11, 'Mert a szegények mindenkor veletek lesznek, de én nem leszek mindenkor veletek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 12, 'Mert hogy ő ezt a kenetet testemre töltötte, az én temetésemre nézve cselekedte azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 13, 'Bizony mondom néktek: Valahol az egész világon prédikáltatik az evangyéliom, a mit ez én velem cselekedék, az is hirdettetik az ő emlékezetére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 14, 'Akkor a tizenkettő közül egy, a kit Iskariótes Júdásnak hívtak, a főpapokhoz menvén,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 15, 'Monda: Mit akartok nékem adni, és én kezetekbe adom őt? Azok pedig rendelének néki harmincz ezüst pénzt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 16, 'És ettől fogva alkalmat keres vala, hogy elárulja őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 17, 'A kovásztalan kenyerek első napján pedig Jézushoz menének a tanítványok, mondván: Hol akarod, hogy megkészítsük néked ételedre a husvéti bárányt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 18, 'Ő pedig monda: Menjetek el a városba ama bizonyos emberhez, és ezt mondjátok néki: A Mester üzeni: Az én időm közel van; nálad tartom meg a husvétot tanítványaimmal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 19, 'És úgy cselekedének a tanítványok, a mint Jézus parancsolta vala nékik; és elkészíték a husvéti bárányt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 20, 'Mikor pedig beestveledék, letelepszik vala a tizenkettővel,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 21, 'És a mikor esznek vala, monda: Bizony mondom néktek, ti közületek egy elárul engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 22, 'És felettébb megszomorodva, kezdék mindannyian mondani néki: Én vagyok-é az, Uram?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 23, 'Ő pedig felelvén, monda: A ki velem együtt mártja kezét a tálba, az árul el engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 24, 'Az embernek Fia jóllehet elmegyen, a mint meg van írva felőle, de jaj annak az embernek, a ki az embernek Fiát elárulja; jobb volna annak az embernek, ha nem született volna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 25, 'Megszólalván Júdás is, a ki elárulja vala őt, monda: Én vagyok-é az, Mester? Monda néki: Te mondád.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 26, 'Mikor pedig evének, vevé Jézus a kenyeret és hálákat adván, megtöré és adá a tanítványoknak, és monda: Vegyétek, egyétek; ez az én testem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 27, 'És vevén a poharat és hálákat adván, adá azoknak, ezt mondván: Igyatok ebből mindnyájan;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 28, 'Mert ez az én vérem, az új szövetségnek vére, a mely sokakért kiontatik bűnöknek bocsánatára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 29, 'Mondom pedig néktek, hogy: Mostantól fogva nem iszom a szőlőtőkének ebből a terméséből mind ama napig, a mikor újan iszom azt veletek az én Atyámnak országában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 30, 'És dícséretet énekelvén, kimenének az olajfák hegyére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 31, 'Akkor monda nékik Jézus: Mindnyájan ezen az éjszakán megbotránkoztok én bennem. Mert meg van írva: Megverem a pásztort, és elszélednek a nyájnak juhai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 32, 'De föltámadásom után előttetek megyek majd Galileába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 33, 'Péter pedig felelvén, monda néki: Ha mindnyájan megbotránkoznak is te benned, én soha meg nem botránkozom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 34, 'Monda néki Jézus: Bizony mondom néked, ezen az éjszakán, mielőtt megszólal a kakas, háromszor megtagadsz engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 35, 'Monda néki Péter: Ha meg kell is veled halnom, meg nem tagadlak téged. Hasonlóképen szólnak vala a többi tanítványok is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 36, 'Akkor elméne Jézus velök egy helyre, a melyet Gecsemánénak hívtak, és monda a tanítványoknak: Üljetek le itt, míg elmegyek és amott imádkozom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 37, 'És maga mellé vévén Pétert és Zebedeusnak két fiát, kezde szomorkodni és gyötrődni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 38, 'Ekkor monda nékik: Felette igen szomorú az én lelkem mind halálig! maradjatok itt és vigyázzatok én velem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 39, 'És egy kissé előre menve, arczra borula, könyörögvén és mondván: Atyám! ha lehetséges, múljék el tőlem e pohár; mindazáltal ne úgy legyen a mint én akarom, hanem a mint te.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 40, 'Akkor méne a tanítványokhoz és aluva találá őket, és monda Péternek: Így nem birtatok vigyázni velem egy óráig sem!?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 41, 'Vigyázzatok és imádkozzatok, hogy kísértetbe ne essetek; mert jóllehet a lélek kész, de a test erőtelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 42, 'Ismét elméne másodszor is, és könyörge, mondván: Atyám! ha el nem múlhatik tőlem e pohár, hogy ki ne igyam, legyen meg a te akaratod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 43, 'És mikor visszatér vala, ismét aluva találá őket; mert megnehezedtek vala az ő szemeik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 44, 'És ott hagyva őket, ismét elméne és imádkozék harmadszor, ugyanazon beszéddel szólván.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 45, 'Ekkor méne az ő tanítványaihoz, és monda nékik: Aludjatok immár és nyugodjatok. Ímé, elközelgett az óra, és az embernek Fia a bűnösök kezébe adatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 46, 'Keljetek fel, menjünk! Ímé elközelgett, a ki engem elárul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 47, 'És még mikor beszél vala, ímé Júdás, egy a tizenkettő közül, eljöve és vele együtt sok nép fegyverekkel és fustélyokkal, a főpapoktól és a nép véneitől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 48, 'A ki pedig őt elárulja vala, jelt ada nékik, mondván: A kit én majd megcsókolok, ő az, fogjátok meg őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 49, 'És mindjárt Jézushoz lépvén, monda: Üdvöz légy Mester! és megcsókolá őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 50, 'Jézus pedig monda néki: Barátom, miért jöttél? Akkor hozzámenvén, kezeiket Jézusra veték és megfogák őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 51, 'És ímé egyik azok közül, a kik a Jézussal valának, kinyújtván kezét, szablyáját kirántá, és a főpap szolgáját megcsapván, levágá annak egyik fülét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 52, 'Akkor monda néki Jézus: Tedd helyére szablyádat; mert a kik fegyvert fognak, fegyverrel kell veszniök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 53, 'Avagy azt gondolod-é, hogy nem kérhetném most az én Atyámat, hogy adjon ide mellém többet tizenkét sereg angyalnál?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 54, 'De mi módon teljesednének be az írások, hogy így kell lenni?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 55, 'Ugyanekkor monda Jézus a sokaságnak: Mint valami latorra, úgy jöttetek fegyverekkel és fustélyokkal, hogy megfogjatok engem? Naponként nálatok ültem, tanítván a templomban, és nem fogtatok meg engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 56, 'Mindez pedig azért lőn, hogy beteljesedjenek a próféták írásai. Ekkor elhagyák őt a tanítványok mind, és elfutának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 57, 'Amazok pedig megfogván Jézust, vivék Kajafáshoz, a főpaphoz, a hol az írástudók és a vének egybegyűltek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 58, 'Péter pedig követi vala őt távolról egész a főpap pitvaráig; és bemenvén, ott ül vala a szolgákkal, hogy lássa a végét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 59, 'A főpapok pedig és a vének és az egész tanács hamis bizonyságot keresnek vala Jézus ellen, hogy megölhessék őt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 60, 'És nem találának. És noha sok hamis tanú jött vala elő, még sem találának. Utoljára pedig előjövén két hamis tanú,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 61, 'Monda: Ez azt mondta: Leronthatom az Isten templomát, és három nap alatt felépíthetem azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 62, 'És fölkelvén a főpap, monda néki: Semmit sem felelsz-é? Micsoda tanúbizonyságot tesznek ezek ellened?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 63, 'Jézus pedig hallgat vala. És felelvén a főpap, monda néki: Az élő Istenre kényszerítelek téged, hogy mondd meg nékünk, ha te vagy-é a Krisztus, az Istennek Fia?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 64, 'Monda néki Jézus: Te mondád. Sőt mondom néktek: Mostantól fogva meglátjátok az embernek Fiát ülni az Istennek hatalmas jobbján, és eljőni az égnek felhőiben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 65, 'Ekkor a főpap megszaggatá a maga ruháit, és monda: Káromlást szólott. Mi szükségünk van még bizonyságokra? Ímé most hallottátok az ő káromlását.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 66, 'Mit gondoltok? Azok pedig felelvén mondának: Méltó a halálra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 67, 'Akkor szemébe köpdösének és arczul csapdosák őt, némelyek pedig botokkal verék,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 68, 'Mondván: Prófétáld meg nékünk Krisztus, kicsoda az, a ki üt téged?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 69, 'Péter pedig künn ül vala az udvaron, és hozzá menvén egy szolgálóleány, monda: Te is a Galileabeli Jézussal valál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 70, 'Ő pedig mindenkinek hallatára megtagadá, mondván: Nem tudom, mit beszélsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 71, 'Mikor pedig kiméne a tornáczra meglátá őt egy másik szolgálóleány, és monda az ott levőknek: Ez is a názáreti Jézussal vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 72, 'És ismét megtagadá esküvéssel, hogy: Nem is ismerem ezt az embert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 73, 'Kevés idő múlva pedig az ott álldogálók menének hozzá, és mondának Péternek: Bizony te is közülök való vagy; hiszen a te beszéded is elárul téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 74, 'Ekkor átkozódni és esküdözni kezde, hogy: Nem ismerem ezt az embert. És a kakas azonnal megszólala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 75, 'És megemlékezék Péter a Jézus beszédéről, ki ezt mondotta vala néki: Mielőtt a kakas szólana, háromszor megtagadsz engem; és kimenvén onnan, keservesen síra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 1, 'Mikor pedig reggel lőn, tanácsot tartának mind a főpapok és a nép vénei Jézus ellen, hogy őt megöljék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 2, 'És megkötözvén őt, elvivék, és átadák őt Ponczius Pilátusnak a helytartónak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 3, 'Akkor látván Júdás, a ki őt elárulá, hogy elítélték őt, megbánta dolgát, és visszavivé a harmincz ezüst pénzt a főpapoknak és a véneknek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 4, 'Mondván: Vétkeztem, hogy elárultam az ártatlan vért. Azok pedig mondának: Mi közünk hozzá? Te lássad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 5, 'Ő pedig eldobván az ezüst pénzeket a templomban, eltávozék; és elmenvén felakasztá magát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 6, 'A főpapok pedig felszedvén az ezüst pénzeket, mondának: Nem szabad ezeket a templom kincsei közé tennünk, mert vérnek ára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 7, 'Tanácsot ülvén pedig, megvásárlák azon a fazekasnak mezejét idegenek számára való temetőnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 8, 'Ezért hívják ezt a mezőt vérmezejének mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 9, 'Ekkor teljesedék be a Jeremiás próféta mondása, a ki így szólott: És vevék a harmincz ezüst pénzt, a megbecsültnek árát, a kit Izráel fiai részéről megbecsültek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 10, 'És adák azt a fazekas mezejéért, a mint az Úr rendelte volt nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 11, 'Jézus pedig ott álla a helytartó előtt; és kérdezé őt a helytartó, mondván: Te vagy-é a zsidók királya? Jézus pedig monda néki: Te mondod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 12, 'És mikor vádolák őt a főpapok és a vének, semmit sem felele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 13, 'Akkor monda néki Pilátus: Nem hallod-é, mily sok bizonyságot tesznek ellened?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 14, 'És nem felele néki egyetlen szóra sem, úgy hogy a helytartó igen elcsodálkozék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 15, 'Ünnepenként pedig egy foglyot szokott szabadon bocsátani a helytartó a sokaság kedvéért, a kit akarának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 16, 'Vala pedig akkor egy nevezetes foglyuk, a kit Barabbásnak hívtak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 17, 'Mikor azért egybegyülekezének, monda nékik Pilátus: Melyiket akarjátok hogy elbocsássam néktek: Barabbást-é, vagy Jézust, a kit Krisztusnak hívnak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 18, 'Mert jól tudja vala, hogy irigységből adák őt kézbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 19, 'A mint pedig ő az ítélőszékben ül vala, külde ő hozzá a felesége, ezt üzenvén: Ne avatkozzál amaz igaz ember dolgába; mert sokat szenvedtem ma álmomban ő miatta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 20, 'A főpapok és vének pedig reá beszélék a sokaságot, hogy Barabbást kérjék ki, Jézust pedig veszítsék el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 21, 'Felelvén pedig a helytartó, monda nékik: A kettő közül melyiket akarjátok, hogy elbocsássam néktek? Azok pedig mondának: Barabbást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 22, 'Monda nékik Pilátus: Mit cselekedjem hát Jézussal, a kit Krisztusnak hívnak? Mindnyájan mondának: Feszíttessék meg!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 23, 'A helytartó pedig monda: Mert mi rosszat cselekedett? Azok pedig még inkább kiáltoznak vala, mondván: Feszíttessék meg!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 24, 'Pilátus pedig látván, hogy semmi sem használ, hanem még nagyobb háborúság támad, vizet vévén, megmosá kezeit a sokaság előtt, mondván: Ártatlan vagyok ez igaz embernek vérétől; ti lássátok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 25, 'És felelvén az egész nép, monda: Az ő vére mi rajtunk és a mi magzatainkon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 26, 'Akkor elbocsátá nékik Barabbást; Jézust pedig megostoroztatván, kezökbe adá, hogy megfeszíttessék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 27, 'Akkor a helytartó vitézei elvivék Jézust az őrházba, és oda gyűjték hozzá az egész csapatot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 28, 'És levetkeztetvén őt, bíbor palástot adának reá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 29, 'És tövisből fonott koronát tőnek a fejére, és nádszálat a jobb kezébe; és térdet hajtva előtte, csúfolják vala őt, mondván: Üdvöz légy zsidóknak királya!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 30, 'És mikor megköpdösék őt, elvevék a nádszálat, és a fejéhez verdesik vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 31, 'És miután megcsúfolták, levevék róla a palástot és az ő maga ruháiba öltözteték; és elvivék, hogy megfeszítsék őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 32, 'Kifelé menve pedig találkozának egy czirénei emberrel, a kit Simonnak hívnak vala; ezt kényszeríték, hogy vigye az ő keresztjét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 33, 'És mikor eljutának arra a helyre, a melyet Golgothának, azaz koponya helyének neveznek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 34, 'Méreggel megelegyített eczetet adának néki inni; és megízlelvén, nem akara inni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 35, 'Minek utána pedig megfeszíték őt, eloszták az ő ruháit, sorsot vetvén; hogy beteljék a próféta mondása: Megosztozának az én ruháimon, és az én köntösömre sorsot vetének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 36, 'És leülvén, ott őrzik vala őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 37, 'És feje fölé illeszték az ő kárhoztatásának okát, oda írván: Ez Jézus, a zsidók királya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 38, 'Akkor megfeszítének vele együtt két latrot, egyiket jobbkéz felől, és a másikat balkéz felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 39, 'Az arramenők pedig szidalmazzák vala őt, fejüket hajtogatván.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 40, 'És ezt mondván: Te, ki lerontod a templomot és harmadnapra fölépíted, szabadítsd meg magadat; ha Isten Fia vagy, szállj le a keresztről!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 41, 'Hasonlóképen a főpapok is csúfolódván az írástudókkal és a vénekkel egyetemben, ezt mondják vala:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 42, 'Másokat megtartott, magát nem tudja megtartani. Ha Izráel királya, szálljon le most a keresztről, és majd hiszünk néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 43, 'Bízott az Istenben; mentse meg most őt, ha akarja; mert azt mondta: Isten Fia vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 44, 'A kiket vele együtt feszítének meg, a latrok is ugyanazt hányják vala szemére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 45, 'Hat órától kezdve pedig sötétség lőn mind az egész földön, kilencz óráig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 46, 'Kilencz óra körül pedig nagy fenszóval kiálta Jézus, mondván: ELI, ELI! LAMA SABAKTÁNI? azaz: Én Istenem, én Istenem! miért hagyál el engemet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 47, 'Némelyek pedig az ott állók közül, a mint ezt hallák, mondának: Illést hívja ez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 48, 'És egy közülök azonnal oda futamodván, egy szivacsot vőn, és megtöltvén eczettel és egy nádszálra tűzvén, inni ád vala néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 49, 'A többiek pedig ezt mondják vala: Hagyd el, lássuk eljő-é Illés, hogy megszabadítsa őt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 50, 'Jézus pedig ismét nagy fenszóval kiáltván, kiadá lelkét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 51, 'És ímé a templom kárpítja fölétől aljáig ketté hasada; és a föld megindula, és a kősziklák megrepedezének;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 52, 'És a sírok megnyílának, és sok elhúnyt szentnek teste föltámada.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 53, 'És kijövén a sírokból, a Jézus föltámadása után bementek a szent városba, és sokaknak megjelenének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 54, 'A százados pedig és a kik ő vele őrizték vala Jézust, látván a földindulást és a mik történtek vala, igen megrémülének, mondván: Bizony, Istennek Fia vala ez!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 55, 'Sok asszony vala pedig ott, a kik távolról szemlélődnek vala, a kik Galileából követték Jézust, szolgálván néki;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 56, 'Ezek közt volt Mária Magdaléna, és Mária a Jakab és Józsé anyja, és a Zebedeus fiainak anyja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 57, 'Mikor pedig beesteledék, eljöve egy gazdag ember Arimathiából, név szerint József, a ki maga is tanítványa volt Jézusnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 58, 'Ez Pilátushoz menvén, kéri vala a Jézus testét. Akkor parancsolá Pilátus, hogy adják át a testet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 59, 'És magához vévén József a testet, begöngyölé azt tiszta gyolcsba,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 60, 'És elhelyezé azt a maga új sírjába, a melyet a sziklába vágatott: és a sír szájára egy nagy követ hengerítvén, elméne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 61, 'Ott vala pedig Mária Magdaléna és a másik Mária, a kik a sír átellenében ülnek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 62, 'Másnap pedig, a mely péntek után következik, egybegyűlének a főpapok és a farizeusok Pilátushoz,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 63, 'Ezt mondván: Uram, emlékezünk, hogy az a hitető még életében azt mondotta volt: Harmadnapra föltámadok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 64, 'Parancsold meg azért, hogy őrizzék a sírt harmadnapig, ne hogy az ő tanítványai odamenvén éjjel, ellopják őt és azt mondják a népnek: Feltámadott a halálból; és az utolsó hitetés gonoszabb legyen az elsőnél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 65, 'Pilátus pedig monda nékik: Van őrségetek; menjetek, őríztessétek, a mint tudjátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 66, 'Ők pedig elmenvén, a sírt őrizet alá helyezék, lepecsételvén a követ, az őrséggel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 1, 'A szombat végén pedig, a hét első napjára virradólag, kiméne Mária Magdaléna és a másik Mária, hogy megnézzék a sírt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 2, 'És ímé nagy földindulás lőn; mert az Úrnak angyala leszállván a mennyből, és oda menvén, elhengeríté a követ a sír szájáról, és reá üle arra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 3, 'A tekintete pedig olyan volt, mint a villámlás, és a ruhája fehér, mint a hó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 4, 'Az őrizők pedig tőle való féltökben megrettenének, és olyanokká lőnek mint a holtak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 5, 'Az angyal pedig megszólalván, monda az asszonyoknak: Ti ne féljetek; mert tudom, hogy a megfeszített Jézust keresitek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 6, 'Nincsen itt, mert feltámadott, a mint megmondotta volt. Jertek, lássátok a helyet, a hol feküdt vala az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 7, 'És menjetek gyorsan és mondjátok meg az ő tanítványainak, hogy feltámadott a halálból; és ímé előttetek megy Galileába; ott meglátjátok őt, ímé megmondottam néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 8, 'És gyorsan eltávozván a sírtól félelemmel és nagy örömmel, futnak vala, hogy megmondják az ő tanítványainak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 9, 'Mikor pedig mennek vala, hogy megmondják az ő tanítványainak, ímé szembe jöve ő velök Jézus, mondván: Legyetek üdvözölve! Azok pedig hozzá járulván, megragadák az ő lábait, és leborulának előtte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 10, 'Akkor monda nékik Jézus: Ne féljetek; menjetek el, mondjátok meg az én atyámfiainak, hogy menjenek Galileába, és ott meglátnak engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 11, 'A mialatt pedig ők mennek vala, ímé az őrségből némelyek bemenvén a városba, megjelentének a főpapoknak mindent a mi történt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 12, 'És egybegyülekezvén a vénekkel együtt, és tanácsot tartván, sok pénzt adának a vitézeknek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 13, 'Ezt mondván: Mondjátok, hogy: Az ő tanítványai odajövén éjjel, ellopák őt, mikor mi aluvánk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 14, 'És ha ez a helytartó fülébe jut, mi elhitetjük őt, és kimentünk titeket a bajból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 15, 'Azok pedig fölvevén a pénzt, úgy cselekedének, a mint megtanították őket. És elterjedt ez a hír a zsidók között mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 16, 'A tizenegy tanítvány pedig elméne Galileába, a hegyre, a hová Jézus rendelte vala őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 17, 'És mikor megláták őt, leborulának előtte; némelyek pedig kételkedének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 18, 'És hozzájuk menvén Jézus, szóla nékik, mondván: Nékem adatott minden hatalom mennyen és földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 19, 'Elmenvén azért, tegyetek tanítványokká minden népeket, megkeresztelvén őket az Atyának, a Fiúnak és a Szent Léleknek nevében,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 20, 'Tanítván őket, hogy megtartsák mindazt, a mit én parancsoltam néktek: és ímé én ti veletek vagyok minden napon a világ végezetéig. Ámen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'A Jézus Krisztus, az Isten Fia evangyéliomának kezdete,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'A mint meg van írva a prófétáknál: Ímé én elküldöm az én követemet a te orczád előtt, a ki megkészíti a te útadat előtted;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, 'Kiáltónak szava a pusztában: Készítsétek meg az Úrnak útját, egyengessétek meg az ő ösvényeit:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'Előáll vala János, keresztelvén a pusztában és prédikálván a megtérésnek keresztségét a bűnöknek bocsánatára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'És kiméne hozzá Júdeának egész tartománya és a Jeruzsálembeliek is, és megkeresztelkedének mindnyájan ő általa a Jordán vizében, bűneikről vallást tévén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'János pedig teveszőrruhát és dereka körül bőrövet viselt vala, és sáskát és erdei mézet eszik vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'És prédikála, mondván: Utánam jő, a ki erősebb nálam, a kinek nem vagyok méltó, hogy lehajolván, sarujának szíjját megoldjam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'Én vízzel kereszteltelek titeket, de ő Szent Lélekkel keresztel titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'És lőn azokban a napokban, eljöve Jézus a galileai Názáretből, és megkeresztelteték János által a Jordánban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'És azonnal feljővén a vízből, látá az egeket megnyilatkozni, és a Lelket mint egy galambot ő reá leszállani;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'És szózat lőn az égből: Te vagy az én szerelmes fiam, a kiben én gyönyörködöm.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'És a Lélek azonnal elragadá őt a pusztába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'És ott volt a pusztában negyven napig kísértetve a Sátántól, és a vad állatokkal vala együtt; és az angyalok szolgálnak vala néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'Minekutána pedig János tömlöczbe vettetett, elméne Jézus Galileába, prédikálván az Isten országának evangyéliomát,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, 'És mondván: Bétölt az idő, és elközelített az Istennek országa; térjetek meg, és higyjetek az evangyéliomban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'Mikor pedig Galilea tengere mellett járt, látá Simont és Andrást, annak testvérét, a mint a tengerbe hálót vetének; mert halászok valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, 'És monda nékik Jézus: Kövessetek engem, és én azt mívelem, hogy embereket halászszatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 18, 'És azonnal elhagyván az ő hálóikat, követék őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 19, 'És onnan egy kevéssé elébb menve, látá Jakabot, a Zebedeus fiát és annak testvérét, Jánost, a mint a hajóban azok is a hálókat kötözgetik vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 20, 'És azonnal hívá őket. És ők atyjukat, Zebedeust a napszámosokkal a hajóban hagyva, utána menének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 21, 'És bemenének Kapernaumba; és mindjárt szombatnapon bemenvén a zsinagógába, tanít vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 22, 'És elálmélkodának az ő tanításán; mert úgy tanítja vala őket, mint a kinek hatalma van, és nem úgy mint az írástudók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 23, 'Vala pedig azok zsinagógájában egy ember, a kiben tisztátalan lélek volt, és felkiálta,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 24, 'És monda: Ah! mi dolgunk van nékünk veled, Názáreti Jézus? Azért jöttél-é, hogy elveszíts minket? Tudom, hogy ki vagy te: az Istennek Szentje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 25, 'És megdorgálá őt Jézus, mondván: Némulj meg, és menj ki belőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 26, 'És a tisztátalan lélek megszaggatá őt, és fenszóval kiáltva, kiméne belőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 27, 'És mindnyájan elálmélkodának, annyira, hogy egymás között kérdezgeték, mondván: Mi ez? Micsoda új tudomány ez, hogy hatalommal parancsol a tisztátalan lelkeknek is, és engedelmeskednek néki?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 28, 'És azonnal elméne az ő híre Galilea egész környékére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 29, 'És a zsinagógából azonnal kimenvén, a Simon és András házához menének Jakabbal és Jánossal együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 30, 'A Simon napa pedig hideglelésben fekszik vala, és azonnal szólának néki felőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 31, 'És ő odamenvén, fölemelé azt, annak kezét fogván; és elhagyá azt a hideglelés azonnal, és szolgál vala nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 32, 'Estefelé pedig, a mikor leszállt a nap, mind ő hozzá vivék a betegeseket és az ördöngősöket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 33, 'És az egész város oda gyűlt vala az ajtó elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 34, 'És meggyógyíta sokakat, a kik különféle betegségekben sínlődnek vala; és sok ördögöt kiűze, és nem hagyja vala szólni az ördögöket, mivelhogy őt ismerék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 35, 'Kora reggel pedig, még szürkületkor, fölkelvén, kiméne, és elméne egy puszta helyre és ott imádkozék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 36, 'Simon pedig és a vele lévők utána sietének;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 37, 'És a mikor megtalálák őt, mondának néki: Mindenki téged keres.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 38, 'És ő monda nékik: Menjünk a közel való városokba, hogy ott is prédikáljak, mert azért jöttem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 39, 'És prédikál vala azoknak zsinagógáiban, egész Galileában, és ördögöket űz vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 40, 'És jöve hozzá egy bélpoklos, kérvén őt és leborulván előtte és mondván néki: Ha akarod, megtisztíthatsz engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 41, 'Jézus pedig könyörületességre indulván, kezét kinyújtva megérinté őt, és monda néki: Akarom, tisztulj meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 42, 'És a mint ezt mondja vala, azonnal eltávozék tőle a poklosság és megtisztula.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 43, 'És erősen megfenyegetvén, azonnal elküldé őt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 44, 'És monda néki: Meglásd, hogy senkinek semmit ne szólj; hanem eredj el, mutasd meg magadat a papnak, és vidd fel a te tisztulásodért, a mit Mózes parancsolt, bizonyságul nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 45, 'Az pedig kimenvén, kezde sokat beszélni és terjeszteni a dolgot, annyira, hogy nyilvánosan immár be sem mehetett Jézus a városba, hanem künn puszta helyeken vala, és mennek vala hozzá mindenfelől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'Napok mulva pedig ismét beméne Kapernaumba, és meghallák, hogy otthon van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'És azonnal sokan összegyülekezének, annyira, hogy még az ajtó elébe sem fértek; és hirdeté nékik az igét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'És jövének hozzá egy gutaütöttet hozva, a kit négyen emelnek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'És mivel a sokaság miatt nem férkőzhettek azzal ő hozzá, megbonták ama háznak fedelét, a hol Ő vala, és rést törvén, leereszték a nyoszolyát, a melyben a gutaütött feküdt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'Jézus pedig azoknak hitét látván, monda a gutaütöttnek: Fiam, megbocsáttattak néked a te bűneid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'Valának pedig ott némely írástudók, a kik ott ülnek vala, szívökben így okoskodván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, 'Mi dolog, hogy ez ilyen káromlásokat szól? ki bocsáthatja meg a bűnöket, hanemha egyedül az Isten?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'És Jézus azonnal észrevevé az ő lelkével, hogy azok magukban így okoskodnak, és monda nékik: Miért gondoljátok ezeket a ti szívetekben?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'Mi könnyebb, azt mondanom-é a gutaütöttnek: Megbocsáttattak néked a te bűneid, vagy ezt mondanom: Kelj fel, vedd fel a te nyoszolyádat, és járj?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Hogy pedig megtudjátok, hogy az ember Fiának van hatalma e földön a bűnöket megbocsátani, monda a gutaütöttnek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, 'Mondom néked, kelj föl, vedd fel a te nyoszolyádat, és eredj haza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'Az pedig azonnal fölkele és felvévén nyoszolyáját, kiméne mindenkinek láttára; úgy hogy mindenki elálmélkodék, és dicsőíté az Istent, ezt mondván: Soha sem láttunk ilyet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'És ismét kiméne a tenger mellé; és az egész sokaság megy vala ő hozzá, és ő tanítja vala őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'És a mikor tovaméne, meglátá Lévit, az Alfeus fiát, a ki a vámszedő helyen ül vala, és monda néki: Kövess engemet. És felkelvén, követi vala őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'És lőn, a mikor ő ennek házában asztalhoz üle, a vámszedők és bűnösök is sokan odaülnek vala Jézussal és az ő tanítványaival; mert sokan valának, és követék őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'És a mikor látták az írástudók és a farizeusok, hogy együtt eszik a vámszedőkkel és bűnösökkel, mondának az ő tanítványainak: Mi dolog, hogy a vámszedőkkel és a bűnösökkel eszik és iszik?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'És a mikor ezt hallja vala Jézus, monda nékik: Nem az egészségeseknek van szükségök orvosra, hanem a betegeknek, nem azért jöttem, hogy igazakat, hanem hogy bűnösöket hívjak megtérésre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'A János és a farizeusok tanítványai pedig bőjtölnek vala. Odamenének azért és mondának néki: Mi az oka, hogy Jánosnak és a farizeusoknak tanítványai bőjtölnek, a te tanítványaid pedig nem bőjtölnek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, 'Jézus pedig monda nékik: Avagy bőjtölhet-é a vőlegény násznépe, a míg velök van a vőlegény? A meddig a vőlegény velök van, nem bőjtölhetnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'De jőnek majd napok, a mikor elvétetik tőlük a vőlegény, és akkor bőjtölni fognak azokon a napokon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, 'Senki sem varr pedig új posztóból foltot ó ruhára; máskülönben a mi azt kitoldaná, még kiszakít belőle, az új a régiből, és nagyobb szakadás lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, 'És senki sem tölt új bort régi tömlőkbe; különben az új bor a tömlőket szétszakítja, a bor is kiömlik, a tömlők is elpusztulnak; hanem az új bort új tömlőkbe kell tölteni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, 'És lőn, hogy szombatnapon a vetések közt megy vala által, és az ő tanítványai mentökben a kalászokat kezdék vala szaggatni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, 'Ekkor a farizeusok mondának néki: Ímé, miért művelik azt szombatnapon, a mit nem szabad?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, 'Ő pedig monda nékik: Soha sem olvastátok-é, mit mívelt Dávid, mikor megszűkült és megéhezett vala társaival egybe?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, 'Mi módon ment be az Isten házába az Abiátár főpap idejében és ette meg a szent kenyereket, a melyeket nem szabad megenni csak a papoknak; és adott a társainak is?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, 'És monda nékik: A szombat lőn az emberért, nem az ember a szombatért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, 'Annak okáért az embernek Fia a szombatnak is ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'És ismét beméne a zsinagógába, és vala ott egy megszáradt kezű ember.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'És lesik vala őt, hogy meggyógyítja-é szombatnapon; hogy vádolhassák őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'Akkor monda a megszáradt kezű embernek: Állj elő a középre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'Azoknak pedig monda: Szabad-é szombatnapon jót vagy rosszat tenni? lelket menteni, vagy kioltani? De azok hallgatnak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'Ő pedig elnézvén őket haraggal, bánkódván szívök keménysége miatt, monda az embernek: Nyújtsd ki a kezedet. És kinyújtá, és meggyógyult a keze és éppé lőn, mint a másik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'Akkor a farizeusok kimenvén, a Heródes pártiakkal mindjárt tanácsot tartának ellene, hogy elveszítsék őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'Jézus pedig elméne tanítványaival a tenger mellé; és nagy sokaság követé őt Galileából és Júdeából,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'És Jeruzsálemből és Idumeából és a Jordánon túlról; és a Tirus és a Sidon környékiek is, a mikor hallották, hogy miket mível vala, nagy sokasággal jövének ő hozzá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'És megmondá tanítványainak, hogy egy kis hajót tartsanak néki készen, a sokaság miatt, hogy ne szorongassák őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'Mert sokakat meggyógyított, úgy hogy a kiknek valami bajuk volt, reá rohanának, hogy illethessék őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'A tisztátalan lelkek is, mikor meglátták vala őt, leborulának előtte, és kiáltának, mondván: Te vagy az Istennek a Fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, 'Ő pedig erősen fenyegeti vala őket, hogy őt ki ne jelentsék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'Azután felméne a hegyre, és magához szólítá, a kiket akar vala; és hozzá menének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'És választa tizenkettőt, hogy vele legyenek, és hogy kiküldje őket prédikálni,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, 'És hatalmuk legyen a betegeket gyógyítani és az ördögöket kiűzni:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, 'Simont, a kinek Péter nevet ada;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'És Jakabot a Zebedeus fiát és Jánost a Jakab testvérét; és Boanerges nevet ada nékik, a mely azt teszi: mennydörgés fiai;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'És Andrást és Filepet, Bertalant és Mátét, Tamást és Jakabot az Alfeus fiát, Taddeust és a kananeai Simont,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'És Iskáriótes Júdást, a ki el is árulta őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 20, 'Azután haza térének. És ismét egybegyűle a sokaság, annyira, hogy még nem is ehetének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 21, 'A mint az övéi ezt meghallák, eljövének, hogy megfogják őt; mert azt mondják vala, hogy magán kívül van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 22, 'Az írástudók pedig, a kik Jeruzsálemből jöttek vala le, azt mondák, hogy: Belzebúb van vele, és: Az ördögök fejedelme által űzi ki az ördögöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 23, 'Ő pedig magához híván azokat, példázatokban monda nékik: Sátán miként tud Sátánt kiűzni?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 24, 'És ha egy ország önmagában meghasonlik, meg nem maradhat az az ország.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 25, 'És ha egy ház önmagában meghasonlik, meg nem maradhat az a ház.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 26, 'És ha a Sátán önmaga ellen támadt és meghasonlott, nem maradhat meg, hanem vége van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 27, 'Nem rabolhatja el senki az erősnek kincseit, bemenvén annak házába, hanemha elébb az erőset megkötözi és azután rabolja ki annak házát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 28, 'Bizony mondom néktek, hogy minden bűn megbocsáttatik az emberek fiainak, még a káromlások is mind, a melyekkel káromlanak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 29, 'De a ki a Szent Lélek ellen szól káromlást, nem nyer bocsánatot soha, hanem örök kárhozatra méltó;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 30, 'Mivelhogy ezt mondják vala: Tisztátalan lélek van benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 31, 'És megérkezének az ő testvérei és az ő anyja, és kívül megállva, beküldének hozzá, hivatván őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 32, 'Körülötte pedig sokaság ül vala; és mondának néki: Ímé a te anyád és a te testvéreid ott künn keresnek téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 33, 'Ő pedig felele nékik, mondván: Ki az én anyám vagy kik az én testvéreim?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 34, 'Azután elnézvén köröskörül a körülötte ülőkön, monda: Ímé az én anyám és az én testvéreim.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 35, 'Mert a ki az Isten akaratát cselekszi, az az én fitestvérem és nőtestvérem és az én anyám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'És ismét kezde tanítani a tenger mellett. És nagy sokaság gyűle ő hozzá, úgy hogy ő a hajóba lépvén, a tengeren ül vala, az egész sokaság pedig a tenger mellett a földön vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, 'És sokat tanítja vala őket példázatokban, és ezt mondja vala nékik tanításában:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, 'Halljátok: Ímé, a magvető kiméne vetni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, 'És lőn vetés közben, hogy némely az út mellé esék, és eljövének az égi madarak és megevék azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, 'Némely pedig a köves helyre esék, a hol nem sok földje vala, és hamar kikele, mivel nem vala mélyen a földben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, 'Mikor pedig fölkelt a nap, elsűle, és mivelhogy nem volt gyökere, elszárada.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, 'Némely pedig a tövisek közé esék, és felnevekedének a tövisek és megfojták azt, és nem ada gyümölcsöt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, 'Némely pedig a jó földbe esék; és ád vala nevekedő és bővölködő gyümölcsöt, és némely hoz vala harmincz annyit, némely hatvan annyit, némely pedig száz annyit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'És monda nékik: A kinek van füle a hallásra, hallja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'Mikor pedig egyedül vala, megkérdezék őt a körülötte lévők a tizenkettővel együtt a példázat felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'Ő pedig monda nékik: Néktek adatott, hogy az Isten országának titkát tudjátok, ama kívül levőknek pedig példázatokban adatnak mindenek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, 'Hogy nézvén nézzenek és ne lássanak; és hallván halljanak és ne értsenek, hogy soha meg ne térjenek és bűneik meg ne bocsáttassanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'És monda nékik: Nem értitek ezt a példázatot? Akkor mimódon értitek meg majd a többi példázatot?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, 'A magvető az ígét hinti.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, 'Az útfélen valók pedig azok, a kiknek hintik az ígét, de mihelyest hallják, azonnal eljő a Sátán és elragadja a szívökbe vetett ígét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 16, 'És hasonlóképen a köves helyre vetettek azok, a kik mihelyst hallják az ígét, mindjárt örömmel fogadják,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 17, 'De nincsen ő bennük gyökere, hanem ideig valók; azután ha nyomorúság vagy háborúság támad az íge miatt, azonnal megbotránkoznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 18, 'A tövisek közé vetettek pedig azok, a kik az ígét hallják,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 19, 'De a világi gondok és a gazdagság csalárdsága és egyéb dolgok kívánsága közbejővén, elfojtják az ígét, és gyümölcstelen lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 20, 'A jó földbe vetettek pedig azok, a kik hallják az ígét és beveszik, és gyümölcsöt teremnek, némely harmincz annyit, némely hatvan annyit, némely száz annyit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 21, 'És monda nékik: Avagy azért hozzák-é elő a gyertyát, hogy véka alá tegyék, vagy az ágy alá? És nem azért-é, hogy a gyertyatartóba tegyék?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 22, 'Mert nincs semmi rejtett dolog, a mi meg ne jelentetnék; és semmi sem volt eltitkolva, hanem hogy nyilvánosságra jusson.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 23, 'Ha valakinek van füle a hallásra, hallja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 24, 'És monda nékik: Megjegyezzétek, a mit hallotok: A milyen mértékkel mértek, olyannal mérnek néktek, sőt ráadást adnak néktek, a kik halljátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 25, 'Mert a kinek van, annak adatik; és a kinek nincs, attól az is elvétetik, a mije van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 26, 'És monda: Úgy van az Isten országa, mint mikor az ember beveti a magot a földbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 27, 'És alszik és fölkel éjjel és nappal; a mag pedig kihajt és felnő, ő maga sem tudja miképen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 28, 'Mert magától terem a föld, először füvet, azután kalászt, azután teljes buzát a kalászban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 29, 'Mihelyt pedig a gabona arra való, azonnal sarlót ereszt reá, mert az aratás elérkezett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 30, 'És monda: Mihez hasonlítsuk az Isten országát? Avagy milyen példában példázzuk azt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 31, 'A mustármaghoz, a mely mikor a földbe vettetik, minden földi magnál kisebb,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 32, 'És mikor elvettetik, felnő, és minden veteménynél nagyobb lesz és nagy ágakat hajt, úgy hogy árnyéka alatt fészket rakhatnak az égi madarak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 33, 'És sok ilyen példázatban hirdeti vala nékik az ígét, úgy a mint megérthetik vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 34, 'Példázat nélkül pedig nem szól vala nékik; maguk közt azonban a tanítványoknak mindent megmagyaráz vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 35, 'Azután monda nékik azon a napon, a mint este lőn: Menjünk át a túlsó partra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 36, 'Elbocsátván azért a sokaságot, elvivék őt, úgy a mint a hajóban vala; de más hajók is valának vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 37, 'Akkor nagy szélvihar támada, a hullámok pedig becsapnak vala a hajóba, annyira, hogy már-már megtelék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 38, 'Ő pedig a hajó hátulsó részében a fejaljon aluszik vala. És fölkelték őt és mondának néki: Mester, nem törődöl vele, hogy elveszünk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 39, 'És felkelvén megdorgálá a szelet, és monda a tengernek: Hallgass, némulj el! És elállt a szél, és lőn nagy csendesség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 40, 'És monda nékik: Miért vagytok ily félénkek? Hogy van, hogy nincsen hitetek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 41, 'És megfélemlének nagy félelemmel, és ezt mondják vala egymásnak: Kicsoda hát ez, hogy mind a szél, mind a tenger engednek néki?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'És menének a tenger túlsó partjára, a Gadarenusok földére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'És a mint a hajóból kiméne, azonnal elébe méne egy ember a sírboltokból, a kiben tisztátalan lélek volt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, 'A kinek lakása a sírboltokban vala; és már lánczokkal sem bírta őt senki sem lekötni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, 'Mert sokszor megkötözték őt békókkal és lánczokkal, de ő a lánczokat szétszaggatta, és a békókat összetörte, és senki sem tudta őt megfékezni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, 'És éjjel és nappal mindig a hegyeken és a sírboltokban volt, kiáltozva és magát kövekkel vagdosva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'Mikor pedig Jézust távolról meglátta, oda futamodék, és elébe borula,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, 'És fennhangon kiáltva monda: Mi közöm nékem te veled, Jézus, a magasságos Istennek Fia? Az Istenre kényszerítelek, ne kínozz engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, '(Mert ezt mondja vala néki: Eredj ki, tisztátalan lélek, ez emberből.)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, 'És kérdezé tőle: Mi a neved? És felele, mondván: Légió a nevem, mert sokan vagyunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'És igen kéré őt, hogy ne küldje el őket arról a vidékről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, 'Vala pedig ott a hegynél egy nagy disznónyáj, a mely legel vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, 'És az ördögök kérik vala őt mindnyájan, mondván: Küldj minket a disznókba, hogy azokba menjünk be.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'És Jézus azonnal megengedé nékik. A tisztátalan lelkek pedig kijövén, bemenének a disznókba; és a nyáj a meredekről a tengerbe rohana. Valának pedig mintegy kétezeren; és belefúlának a tengerbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, 'A kik pedig őrzik vala a disznókat, elfutának, és hírt vivének a városba és a falvakba. És kimenének, hogy lássák, mi az, a mi történt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'És menének Jézushoz, és láták, hogy az ördöngős ott ül, fel van öltözködve és eszénél van, az, a kiben a légió volt; és megfélemlének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'A kik pedig látták, elbeszélék nékik, hogy mi történt vala az ördöngőssel, és a disznókkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, 'És kezdék kérni őt, hogy távozzék el az ő határukból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'Mikor pedig a hajóba beszállott vala, a volt ördöngős kéré őt, hogy vele lehessen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, 'De Jézus nem engedé meg néki, hanem monda néki: Eredj haza a tiéidhez, és jelentsd meg nékik, mely nagy dolgot cselekedett veled az Úr, és mint könyörült rajtad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, 'El is méne, és kezdé hirdetni a Tízvárosban, mely nagy dolgot cselekedett vele Jézus; és mindnyájan elcsodálkozának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'És mikor ismét általment Jézus a hajón a tulsó partra, nagy sokaság gyűle ő hozzá; és vala a tenger mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, 'És ímé, eljöve a zsinagóga fők egyike, névszerint Jairus, és meglátván őt, lábaihoz esék,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, 'És igen kéré őt, mondván: Az én leánykám halálán van; jer, vesd reá kezedet, hogy meggyógyuljon és éljen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, 'El is méne vele, és követé őt nagy sokaság, és összeszorítják vala őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 25, 'És egy asszony, a ki tizenkét év óta vérfolyásos vala,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 26, 'És sok orvostól sokat szenvedett, és minden vagyonát magára költötte, és semmit sem javult, sőt inkább még rosszabbul lett,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 27, 'Mikor Jézus felől hallott vala, a sokaságban hátulról kerülve, illeté annak ruháját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 28, 'Mert ezt mondja vala: Ha csak ruháit illethetem is, meggyógyulok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 29, 'És vérének forrása azonnal kiszárada és megérzé testében, hogy kigyógyult bajából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 30, 'Jézus pedig azonnal észrevevén magán, hogy isteni erő áradott vala ki belőle, megfordult a sokaságban, és monda: Kicsoda illeté az én ruháimat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 31, 'És mondának néki az ő tanítványai: Látod, hogy a sokaság szorít össze téged, és azt kérdezed: Kicsoda illetett engem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 32, 'És körülnéze, hogy lássa azt, a ki ezt cselekedte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 33, 'Az asszony pedig tudva, hogy mi történt vele, félve és remegve megy vala oda és elébe borula, és elmonda néki mindent igazán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 34, 'Ő pedig monda néki: Leányom, a te hited megtartott téged. Eredj el békével, és gyógyulj meg a te bajodból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 35, 'Mikor még beszél vala, odajövének a zsinagóga fejétől, mondván: Leányod meghalt; mit fárasztod tovább a Mestert?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 36, 'Jézus pedig, a mint hallá a beszédet, a mit mondanak vala, azonnal monda a zsinagóga fejének: Ne félj, csak higyj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 37, 'És senkinek sem engedé, hogy vele menjen, csak Péternek és Jakabnak és Jánosnak, a Jakab testvérének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 38, 'És méne a zsinagóga fejének házához, és látá a zűrzavart, a sok síránkozót és jajgatót.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 39, 'És bemenvén, monda nékik: Mit zavarogtok és sírtok? A gyermek nem halt meg, hanem alszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 40, 'És nevetik vala őt. Ő pedig kiküldvén valamennyit, maga mellé vevé a gyermeknek atyját és anyját és a vele levőket, és beméne oda, a hol a gyermek fekszik vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 41, 'És megfogván a gyermeknek kezét, monda néki: Talitha, kúmi; a mi megmagyarázva azt teszi: Leányka, néked mondom, kelj föl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 42, 'És a leányka azonnal fölkele és jár vala. Mert tizenkét esztendős vala. És nagy csodálkozással csodálkozának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 43, 'Ő pedig erősen megparancsolá nékik, hogy ezt senki meg ne tudja. És mondá, hogy adjanak annak enni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'És kiméne onnét, és méne az ő hazájába, és követék őt az ő tanítványai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, 'És a mint eljött vala a szombat, tanítani kezde a zsinagógában; és sokan, a kik őt hallák, elálmélkodának vala, mondván: Honnét vannak ennél ezek? És mely bölcsesség az, a mi néki adatott, hogy ily csodadolgok is történnek általa?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, 'Avagy nem ez-é az az ácsmester, Máriának a fia, Jakabnak, Józsénak, Júdásnak és Simonnak pedig testvére? És nincsenek-é itt közöttünk az ő nőtestvérei is? És megbotránkoznak vala ő benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'Jézus pedig monda nékik: Nincs próféta tisztesség nélkül csak a maga hazájában, és a rokonai között és a maga házában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, 'Nem is tehet vala ott semmi csodát, csak nehány beteget gyógyíta meg, rájok vetvén kezeit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, 'És csodálkozik vala azoknak hitetlenségén. Aztán köröskörül járja vala a falvakat, tanítván.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'Majd magához szólítá a tizenkettőt, és kezdé őket kiküldeni kettőnként, és ada nékik hatalmat a tisztátalan lelkeken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'És megparancsolá nékik, hogy az útra semmit ne vigyenek egy pálczán kívül; se táskát, se kenyeret, se pénzt az övükben;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'Hanem kössenek sarut, de két ruhát ne öltsenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, 'És monda nékik: A hol valamely házba bementek, ott maradjatok mindaddig, a míg tovább mentek onnét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, 'A kik pedig nem fogadnak titeket, sem nem hallgatnak rátok, onnét kimenvén, verjétek le a port lábaitokról, bizonyságul ő ellenök. Bizony mondom néktek: Sodomának vagy Gomorának tűrhetőbb lesz a dolga az ítélet napján, mint annak a városnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'Kimenvén azért, prédikálják vala, hogy térjenek meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, 'És sok ördögöt űznek vala ki, és olajjal sok beteget megkennek és meggyógyítnak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'És meghallá ezeket Heródes király (mert nyilvánvalóvá lőn az ő neve) és monda: Keresztelő János támadt fel a halálból és azért működnek benne ez erők.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, 'Némelyek azt mondják vala, hogy Illés ő; mások meg azt mondják vala, hogy Próféta, vagy olyan, mint egy a próféták közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'Heródes pedig ezeket hallván, monda: A kinek én fejét vétetém, az a János ez; ő támadt fel a halálból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'Mert maga Heródes fogatta el és vettette vala börtönbe Jánost, Heródiás miatt, Fülöpnek, az ő testvérének felesége miatt, mivelhogy azt vette vala feleségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'Mert János azt mondá Heródesnek: Nem szabad néked a testvéred feleségével élned.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'Heródiás pedig ólálkodik vala utána, és meg akarja vala őt ölni; de nem teheté.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, 'Mert Heródes fél vala Jánostól, igaz és szent embernek ismervén őt, és oltalmazá őt; és ráhallgatván, sok dologban követi, és örömest hallgatja vala őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, 'De egy alkalmatos nap jöttével, mikor Heródes a maga születése ünnepén nagyjainak, vezéreinek és Galilea előkelő embereinek lakomát ad vala,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 22, 'És ennek a Heródiásnak a leánya beméne és tánczola, és megtetszék Heródesnek és a vendégeknek, monda a király a leánynak: Kérj tőlem, a mit akarsz, és megadom néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 23, 'És megesküvék néki, hogy: Bármit kérsz tőlem, megadom néked, még ha országom felét is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 24, 'Az pedig kimenvén, monda az ő anyjának: Mit kérjek? Ez pedig mondja: A Keresztelő János fejét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 25, 'És a királyhoz nagy sietve azonnal bemenvén, kéré őt mondván: Akarom, hogy mindjárt add ide nékem a Keresztelő János fejét egy tálban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 26, 'A király pedig noha igen megszomorodék, eskűje és a vendégek miatt nem akará őt elutasítani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 27, 'És azonnal hóhért küldvén a király, megparancsolá, hogy hozzák el annak fejét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 28, 'Ez pedig elmenvén, fejét vevé annak a börtönben, és előhozá a fejét egy tálban és adá a leánynak; a leány pedig az anyjának adá azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 29, 'A tanítványai pedig, a mikor ezt meghallották vala, eljövének, és elvivék a testét, és sírba tevék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 30, 'És az apostolok összegyűlekezének Jézushoz, és elbeszélének néki mindent, azt is, a miket cselekedtek, azt is, a miket tanítottak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 31, 'Ő pedig monda nékik: Jertek el csupán ti magatok valamely puszta helyre és pihenjetek meg egy kevéssé. Mert sokan valának a járó-kelők, és még evésre sem volt alkalmas idejök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 32, 'És elmenének hajón egy puszta helyre csupán ő magok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 33, 'A sokaság pedig meglátá őket, a mint mennek vala, és sokan megismerék őt; és minden városból egybefutának oda gyalog, és megelőzék őket, és hozzá gyülekezének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 34, 'És kimenvén Jézus nagy sokaságot láta, és megszáná őket, mert olyanok valának, mint a pásztor nélkül való juhok. És kezdé őket sokra tanítani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 35, 'Mikor pedig immár nagy idő vala, hozzámenvén az ő tanítványai mondának: Puszta ez a hely, és immár nagy idő van:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 36, 'Bocsásd el őket, hogy elmenvén a körülfekvő majorokba és falvakba, vegyenek magoknak kenyeret; mert nincs mit enniök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 37, 'Ő pedig felelvén, monda nékik: Adjatok nékik ti enniök. És mondának néki: Elmenvén, vegyünk-é kétszáz pénz árú kenyeret, hogy enni adjunk nékik?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 38, 'Ő pedig monda nékik: Hány kenyeretek van? Menjetek és nézzétek meg. És megtudván, mondának: Öt, és két halunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 39, 'És parancsolá nékik, hogy ültessenek le mindenkit csoportonként a zöld pázsitra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 40, 'Letelepedének azért szakaszonként, százával és ötvenével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 41, 'Ő pedig vette vala az öt kenyeret és a két halat, és az égre tekintvén, hálákat ada; és megszegé a kenyereket és adá tanítványainak, hogy tegyék azok elé; és a két halat is elosztá mindnyájok között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 42, 'Evének azért mindnyájan, és megelégedének;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 43, 'És maradékot is szedének fel tizenkét tele kosárral, és a halakból is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 44, 'A kik pedig a kenyerekből ettek, mintegy ötezeren valának férfiak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 45, 'És azonnal kényszeríté tanítványait, hogy hajóba szálljanak, és menjenek át előre a túlsó partra Bethsaida felé, a míg ő a sokaságot elbocsátja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 46, 'Minekutána pedig elbocsátotta őket, fölméne a hegyre imádkozni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 47, 'És mikor beesteledék, a hajó a tenger közepén vala, ő pedig egymaga a szárazon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 48, 'És látá őket, a mint vesződnek az evezéssel; mert a szél szembe fú vala velök; és az éj negyedik szakában hozzájuk méne a tengeren járva; és el akar vala haladni mellettük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 49, 'Azok pedig látván őt a tengeren járni, kisértetnek vélték, és felkiáltának;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 50, 'Mert mindnyájan látják vala őt és megrémülének. De ő azonnal megszólítá őket, és monda nékik: Bízzatok; én vagyok, ne féljetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 51, 'Ekkor beméne hozzájuk a hajóba, és elállt a szél; ők pedig magukban szerfölött álmélkodnak és csodálkoznak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 52, 'Mert nem okultak a kenyereken, mivelhogy a szívök meg vala keményedve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 53, 'És átkelve, eljutának a Genezáret földére, és kikötének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 54, 'De mihelyt kiszálltak a hajóból, azonnal megismerék őt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 55, 'És azt az egész környéket befutván, kezdék a betegeket a nyoszolyákon ide-oda hordozni, a merre hallják vala, hogy ő ott van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 56, 'És a hová bemegy vala a falvakba vagy városokba vagy majorokba, a betegeket letevék a piaczokon, és kérik vala őt, hogy legalább a ruhája szegélyét illethessék. És valahányan csak illeték, meggyógyulának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'És hozzá gyűlének a farizeusok és némelyek az írástudók közül, a kik Jeruzsálemből jöttek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, 'És látván, hogy az ő tanítványai közül némelyek közönséges, azaz mosdatlan kézzel esznek kenyeret, panaszkodának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, 'Mert a farizeusok és a zsidók mind, a régiek rendelését követve, nem esznek, hanemha kezöket erősen megmossák;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'És piaczról jövén sem esznek, ha meg nem mosakodnak; és sok egyéb is van, a minek megtartását átvették, poharaknak, korsóknak, rézedényeknek és nyoszolyáknak megmosását.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, 'Azután megkérdék őt a farizeusok és az írástudók: Mi az oka, hogy a te tanítványaid nem járnak a régiek rendelése szerint, hanem mosdatlan kézzel esznek kenyeret?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'Ő pedig felelvén, monda nékik: Igazán jövendölt felőletek, képmutatók felől Ésaiás próféta, a mint meg van írva: Ez a nép ajkaival tisztel engem, a szívök pedig távol van tőlem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'Pedig hiába tisztelnek engem, ha oly tudományokat tanítanak, a melyek embereknek parancsolatai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'Mert az Isten parancsolatját elhagyva, az emberek rendelését tartjátok meg, korsóknak és poharaknak mosását; és sok egyéb efféléket is cselekesztek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'És monda nékik: Az Isten parancsolatját szépen félre teszitek, azért, hogy a magatok rendelését tartsátok meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, 'Mert Mózes azt mondotta: Tiszteld atyádat és anyádat. És: A ki atyját vagy anyját szidalmazza, halállal haljon meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, 'Ti pedig azt mondjátok: Ha valaki ezt mondja atyjának vagy anyjának: Korbán (azaz: templomi ajándék) az, a mivel megsegíthetnélek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'Úgy már nem engeditek, hogy az atyjával vagy anyjával valami jót tegyen,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'Eltörölvén az Isten beszédét a ti rendelésetekkel, a melyet rendeltetek; és sok effélét is cselekesztek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, 'És előszólítván az egész sokaságot, monda nékik: Hallgassatok reám mindnyájan és értsétek meg:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, 'Nincs semmi az emberen kívülvaló, a mi bemenvén ő belé, megfertőztethetné őt; hanem a mik belőle jőnek ki, azok fertőztetik meg az embert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, 'Ha valakinek van füle a hallásra, hallja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'És mikor házba ment vala be a sokaság közül, megkérdezék őt tanítványai a példázat felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, 'És monda nékik: Ti is ennyire tudatlanok vagytok-é? Nem értitek-é, hogy a mi kívülről megy az emberbe, semmi sem fertőztetheti meg őt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'Mert nem a szívébe megy be, hanem a gyomrába; és az árnyékszékbe kerül, a mely minden eledelt megtisztít.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, 'Monda továbbá: A mi az emberből jő ki, az fertőzteti meg az embert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, 'Mert onnan belőlről, az emberek szívéből származnak a gonosz gondolatok, házasságtörések, paráznaságok, gyilkosságok,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, 'Lopások, telhetetlenségek, gonoszságok, álnokság, szemérmetlenség, gonosz szem, káromlás, kevélység, bolondság:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'Mind ezek a gonoszságok belőlről jőnek ki, és megfertőztetik az embert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'És onnét fölkelvén, elméne Tírus és Sídon határaiba; és házba menvén, nem akará, hogy valaki észrevegye, de nem titkolhatá el magát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'Mert hallván felőle egy asszony, a kinek leányában tisztátalan lélek vala, eljőve és lábaihoz borula.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, 'Ez az asszony pedig pogány vala síro-fenicziai származású. És kéré őt, hogy űzze ki az ő leányából az ördögöt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, 'Jézus pedig monda néki: Engedd, hogy először a fiak elégíttessenek meg. Mert nem jó a fiak kenyerét elvenni, és az ebeknek vetni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, 'Az pedig felele és monda néki: Úgy van Uram; de hiszen az ebek is esznek az asztal alatt a gyermekek morzsalékaiból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, 'Erre monda néki: E beszédért, eredj el; az ördög kiment a te leányodból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, 'És haza menvén, úgy találá, hogy az ördög kiment, a leány pedig az ágyon feküvék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, 'Aztán ismét kimenvén Tírus és Sídon határaiból, a galileai tengerhez méne, a Tízváros határain át.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, 'És hozának néki egy nehezen szóló siketet, és kérik vala őt, hogy vesse reá kezét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 33, 'Ő pedig, mikor kivitte vala azt a sokaság közül egy magát, az újjait annak fülébe bocsátá, és köpvén illeté annak nyelvét,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 34, 'És föltekintvén az égre, fohászkodék, és monda néki: Effata, azaz: nyilatkozzál meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 35, 'És azonnal megnyilatkozának annak fülei: és nyelvének kötele megoldódék, és helyesen beszél vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 36, 'És megparancsolá nékik, hogy senkinek se mondják el; de mennél inkább tiltja vala, annál inkább híresztelék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 37, 'És szerfelett álmélkodnak vala, ezt mondván: Mindent jól cselekedett; a siketeket is hallókká teszi, a némákat is beszélőkké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'Azokban a napokban, mivelhogy fölötte nagy volt a sokaság, és nem volt mit enniök, magához szólította Jézus az ő tanítványait, és monda nékik:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, 'Szánakozom e sokaságon, mert immár harmad napja hogy velem vannak, és nincs mit enniök;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, 'És ha éhen bocsátom haza őket, kidőlnek az úton; mert némelyek ő közülök messzünnen jöttek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, 'Az ő tanítványai pedig felelének néki: Honnan elégíthetné meg ezeket valaki kenyérrel itt e pusztában?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, 'És megkérdé őket: Hány kenyeretek van? Azok pedig mondának: Hét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'Akkor megparancsolá a sokaságnak, hogy telepedjenek le a földre. És vevén a hét kenyeret, és hálákat adván, megszegé, és adá az ő tanítványainak, hogy eléjök tegyék. És a sokaság elé tevék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'Volt egy kevés haluk is. És hálákat adván mondá, hogy tegyék eléjök azokat is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, 'Evének azért, és megelégedének; és fölszedék a maradék darabokat, hét kosárral.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, 'Valának pedig a kik ettek mintegy négyezeren; és elbocsátá őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, 'És azonnal a hajóba szálla tanítványaival, és méne Dalmánuta vidékére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'És kijövének a farizeusok, és kezdék őt faggatni, mennyei jelt kívánván tőle, hogy kísértsék őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'Ő pedig lelkében felfohászkodván, monda: Miért kíván jelt ez a nemzetség? Bizony mondom néktek: Nem adatik jel ennek a nemzetségnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'És ott hagyván őket, ismét hajóba szálla, és a túlsó partra méne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, 'De elfelejtének kenyeret vinni, és egy kenyérnél nem vala velök több a hajóban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'És ő inti vala őket, mondván: Vigyázzatok, őrizkedjetek a farizeusok kovászától és a Heródes kovászától!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, 'Ekkor egymás között tanakodván, mondának: Nincs kenyerünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'Jézus pedig észrevévén ezt, monda nékik: Mit tanakodtok, hogy nincsen kenyeretek? Még sem látjátok-é be és nem értitek-é? Mégis kemény-é a szívetek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, 'Szemeitek lévén, nem láttok-é? és füleitek lévén, nem hallotok-é? és nem emlékeztek-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, 'Mikor az öt kenyeret megszegtem az ötezernek, hány kosarat hoztatok el darabokkal tele? Mondának néki: Tizenkettőt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, 'Mikor pedig a hetet a négyezernek, hány kosarat hoztatok el darabokkal tele? Azok pedig mondának: Hetet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, 'És monda nékik: Hogy nem értitek hát?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, 'Azután Bethsaidába méne; és egy vakot vivének hozzá és kérik vala őt, hogy illesse azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, 'Ő pedig megfogván a vaknak kezét, kivezeté őt a falun kívül; és a szemeibe köpvén és kezeit reá tévén, megkérdé őt, ha lát-é valamit?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, 'Az pedig föltekintvén, monda: Látom az embereket, mint valami járkáló fákat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, 'Azután kezeit ismét ráveté annak szemeire, és feltekintete véle. És megépüle, és látá messze és világosan mindent.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, 'És haza küldé, mondván: Se a faluba be ne menj, se senkinek el ne mondd a faluban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, 'És elméne Jézus és az ő tanítványai Czézárea Filippi falvaiba; és útközben megkérdé az ő tanítványait, mondván nékik: Kinek mondanak engem az emberek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, 'Ők pedig felelének: Keresztelő Jánosnak; és némelyek Illésnek; némelyek pedig egynek a próféták közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, 'És ő monda nékik: Ti pedig kinek mondotok engem? Felelvén pedig Péter, monda néki: Te vagy a Krisztus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, 'És rájok parancsola, hogy senkinek se szóljanak felőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, 'És kezdé őket tanítani, hogy az ember Fiának sokat kell szenvedni, és megvettetni a vénektől és a főpapoktól és írástudóktól, és megöletni, és harmadnapra feltámadni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, 'És ezt nyilván mondja vala. Péter pedig magához vonván őt, kezdé dorgálni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, 'És ő megfordulván és az ő tanítványaira tekintvén, megfeddé Pétert, mondván: Távozz tőlem Sátán, mert nem gondolsz az Isten dolgaira, hanem az emberi dolgokra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, 'A sokaságot pedig az ő tanítványaival együtt magához szólítván, monda nékik: Ha valaki én utánam akar jőni, tagadja meg magát, és vegye fel az ő keresztjét, és kövessen engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, 'Mert valaki meg akarja tartani az ő életét, elveszti azt; valaki pedig elveszti az ő életét én érettem és az evangyéliomért, az megtalálja azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, 'Mert mit használ az embernek, ha az egész világot megnyeri, lelkében pedig kárt vall?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 37, 'Avagy mit adhat az ember váltságul az ő lelkéért?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 38, 'Mert valaki szégyel engem és az én beszédeimet e parázna és bűnös nemzetség között, az embernek Fia is szégyelni fogja azt, mikor eljő az ő Atyja dicsőségében a szent angyalokkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'Azután monda nékik: Bizony mondom néktek, hogy vannak némelyek az itt állók között, a kik nem kóstolnak addig halált, a míg meg nem látják, hogy az Isten országa eljött hatalommal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, 'És hat nap múlva magához vevé Jézus Pétert és Jakabot és Jánost, és felvivé őket csupán magukban egy magas hegyre. És elváltozék előttük;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, 'És a ruhája fényes lőn, igen fehér, mint a hó, mihez hasonlót a ruhafestő e földön nem fehéríthet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'És megjelenék nékik Mózes Illéssel együtt, és beszélnek vala Jézussal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, 'Péter pedig megszólalván, monda Jézusnak: Mester, jó nékünk itt lenni: csináljunk azért három hajlékot, néked egyet, Mózesnek is egyet, Illésnek is egyet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, 'De nem tudja vala mit beszél, mivelhogy megrémülének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'És felhő támada, mely őket befogá, és a felhőből szózat jöve, mondván: Ez az én szerelmes Fiam; őt hallgassátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, 'És mikor nagyhirtelen körültekintének, senkit sem látának többé maguk körül, egyedül a Jézust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, 'Mikor pedig a hegyről leszállának, megparancsolá nékik, hogy senkinek se beszéljék el, a mit láttak vala, csak a mikor az embernek Fia a halálból feltámad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, 'És ezt a szót megtarták magukban, tudakozván egymás között, mit tesz a halálból feltámadni?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'És megkérdezék őt, mondván: Miért mondják az írástudók, hogy előbb Illésnek kell eljőnie?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'Ő pedig felelvén, monda nékik: Illés ugyan előbb eljövén helyre állít mindent; de hogyan van az embernek Fiáról megírva, hogy sokat kell szenvednie és megvettetnie?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'De mondom néktek, hogy Illés is eljött, és azt cselekedték vele, a mit akartak, a mint meg van írva ő felőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, 'És mikor a tanítványokhoz ment vala, nagy sokaságot láta körülöttök, és írástudókat, a kik azokkal versengenek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 15, 'És az egész sokaság meglátván őt, azonnal elálmélkodék, és hozzásietvén köszönté őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 16, 'Ő pedig megkérdezé az írástudókat: Mit versengetek ezekkel?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 17, 'És felelvén egy a sokaságból, monda: Mester, ide hoztam hozzád az én fiamat, a kiben néma lélek van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 18, 'És a hol csak előfogja, szaggatja őt; ő pedig tajtékot túr, a fogát csikorgatja, és elfonnyad. Mondám hát tanítványaidnak, hogy űzzék ki azt, de nem tudták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 19, 'Ő pedig felelvén néki, monda: Óh hitetlen nemzetség, meddig leszek még veletek? Meddig szenvedlek még titeket? Hozzátok őt hozzám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 20, 'És hozzá vivék azt; és mihelyt ő meglátta azt, a lélek azonnal szaggatá azt; és leesvén a földre, tajtékot túrván fetreng vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 21, 'És megkérdezé az atyját: Mennyi ideje, hogy ez esett rajta? Az pedig monda: Gyermeksége óta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 22, 'És gyakorta veté őt tűzbe is, vízbe is, hogy elveszítse őt; de ha valamit tehetsz, légy segítségül nékünk, könyörülvén rajtunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 23, 'Jézus pedig monda néki: Ha hiheted azt, minden lehetséges a hívőnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 24, 'A gyermek atyja pedig azonnal kiáltván, könnyhullatással monda: Hiszek Uram! Légy segítségül az én hitetlenségemnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 25, 'Jézus pedig mikor látta vala, hogy a sokaság még inkább összetódul, megdorgálá a tisztátalan lelket, mondván néki: Te néma és siket lélek, én parancsolom néked, menj ki belőle, és többé belé ne menj!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 26, 'És kiáltás és erős szaggatás között kiméne; az pedig olyan lőn, mint egy halott, annyira, hogy sokan azt mondják vala, hogy meghalt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 27, 'Jézus pedig megfogván kezét, fölemelé; és az fölkele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 28, 'Mikor pedig bement vala a házba, tanítványai megkérdezék őt külön: Mi miért nem űzhettük ki azt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 29, 'Ő pedig monda nékik: Ez a faj semmivel sem űzhető ki, csupán könyörgéssel és bőjtöléssel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 30, 'És onnét kimenvén, Galileán mennek vala át; és nem akará, hogy valaki megtudja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 31, 'Mert tanítja vala tanítványait, és ezt mondja vala nékik: Az embernek Fia az emberek kezébe adatik, és megölik őt; de ha megölték, harmadnapra föltámad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 32, 'De ők nem értik vala e mondást, és féltek őt megkérdezni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 33, 'És elméne Kapernaumba. És odahaza megkérdezé őket: Mi felett vetekedtetek egymással az úton?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 34, 'De ők hallgatának, mert egymás között a felett vetekedtek vala az úton, ki a nagyobb?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 35, 'És leülvén, odaszólítá a tizenkettőt, és monda nékik: Ha valaki első akar lenni, legyen mindenek között utolsó és mindeneknek szolgája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 36, 'És előfogván egy gyermeket, közéjök állatá azt; és ölébe vévén azt, monda nékik:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 37, 'A ki az ilyen gyermekek közül egyet befogad az én nevemben, engem fogad be; és a ki engem befogad, nem engem fogad be, hanem azt, a ki engem elbocsátott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 38, 'János pedig felele néki, mondván: Mester, látánk valakit, a ki a te neveddel ördögöket űz, a ki nem követ minket; és eltiltók őt, mivelhogy nem követ minket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 39, 'Jézus pedig monda: Ne tiltsátok el őt; mert senki sincs, a ki csodát tesz az én nevemben és mindjárt gonoszul szólhatna felőlem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 40, 'Mert a ki nincs ellenünk, mellettünk van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 41, 'Mert a ki innotok ád egy pohár vizet az én nevemben, mivelhogy a Krisztuséi vagytok, bizony mondom néktek, el nem veszti az ő jutalmát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 42, 'A ki pedig megbotránkoztat egyet ama kicsinyek közül, a kik én bennem hisznek, jobb annak, ha malomkövet kötnek a nyakára, és a tengerbe vetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 43, 'És ha megbotránkoztat téged a te kezed, vágd le azt: jobb néked csonkán bemenned az életre, mint két kézzel menned a gyehennára, a megolthatatlan tűzre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 44, 'A hol az ő férgök meg nem hal, és tüzök el nem aluszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 45, 'És ha a te lábad botránkoztat meg téged, vágd le azt: jobb néked sántán bemenned az életre, mint két lábbal vettetned a gyehennára, a megolthatatlan tűzre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 46, 'A hol az ő férgök meg nem hal, és tüzök el nem aluszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 47, 'És ha a te szemed botránkoztat meg téged, vájd ki azt: jobb néked félszemmel bemenned az Isten országába, mint két szemmel vettetned a tüzes gyehennára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 48, 'A hol az ő férgök meg nem hal, és tüzök el nem aluszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 49, 'Mert mindenki tűzzel sózatik meg, és minden áldozat sóval sózatik meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 50, 'Jó a só: de ha a só ízét veszti, mivel adtok ízt néki? Legyen bennetek só, és legyetek békében egymással.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 51, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'Onnan pedig felkelvén Judea határaiba méne, a Jordánon túl való részen által; és ismét sokaság gyűl vala hozzá; ő pedig szokása szerint ismét tanítja vala őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, 'És a farizeusok hozzámenvén megkérdezék tőle, ha szabad-é férjnek feleségét elbocsátani, kísértvén őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, 'Ő pedig felelvén, monda nékik: Mit parancsolt néktek Mózes?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, 'Ők pedig mondának: Mózes megengedte, hogy válólevelet írjunk, és elváljunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'És Jézus felelvén, monda nékik: A ti szívetek keménysége miatt írta néktek ezt a parancsolatot;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'De a teremtés kezdete óta férfiúvá és asszonnyá teremté őket az Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, 'Annakokáért elhagyja az ember az ő atyját és anyját; és ragaszkodik a feleségéhez,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, 'És lesznek ketten egy testté! Azért többé nem két, hanem egy test.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'Annakokáért a mit az Isten egybe szerkesztett, ember el ne válaszsza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, 'És odahaza az ő tanítványai ismét megkérdezék őt e dolog felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'Ő pedig monda nékik: A ki elbocsátja feleségét és mást vesz el, házasságtörést követ el az ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'Ha pedig a feleség hagyja el a férjét és mással kel egybe, házasságtörést követ el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'Ekkor gyermekeket hozának hozzá, hogy illesse meg őket; a tanítványok pedig feddik vala azokat, a kik hozák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'Jézus pedig ezt látván, haragra gerjede és monda nékik: Engedjétek hozzám jőni a gyermekeket és ne tiltsátok el őket; mert ilyeneké az Istennek országa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'Bizony mondom néktek: A ki nem úgy fogadja az Isten országát, mint gyermek, semmiképen sem megy be abba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'Aztán ölébe vevé azokat, és kezét rájok vetvén, megáldá őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'És mikor útnak indult vala, hozzá futván egy ember és letérdelvén előtte, kérdezi vala őt: Jó Mester, mit cselekedjem, hogy az örökéletet elnyerhessem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, 'Jézus pedig monda néki: Miért mondasz engem jónak? Senki sem jó, csak egy, az Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, 'A parancsolatokat tudod: Ne paráználkodjál; ne ölj; ne lopj; hamis tanubizonyságot ne tégy, kárt ne tégy; tiszteljed atyádat és anyádat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, 'Az pedig felelvén, monda néki: Mester, mindezeket megtartottam ifjúságomtól fogva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, 'Jézus pedig rátekintvén, megkedvelé őt, és monda néki: Egy fogyatkozásod van; eredj el, add el minden vagyonodat, és add a szegényeknek, és kincsed lesz mennyben; és jer, kövess engem, felvévén a keresztet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, 'Az pedig elszomorodván e beszéden, elméne búsan; mert sok jószága vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, 'Jézus pedig körültekintvén, monda tanítványainak: Mily nehezen mennek be az Isten országába, a kiknek gazdagságuk van!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 24, 'A tanítványok pedig álmélkodának az ő beszédén; de Jézus ismét felelvén, monda nékik: Gyermekeim, mily nehéz azoknak, a kik a gazdagságban bíznak, az Isten országába bemenni!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 25, 'Könnyebb a tevének a tű fokán átmenni, hogynem a gazdagnak az Isten országába bejutni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 26, 'Azok pedig még inkább álmélkodnak vala, mondván magok között: Kicsoda idvezülhet tehát?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 27, 'Jézus pedig rájuk tekintvén, monda: Az embereknél lehetetlen, de nem az Istennél; mert az Istennél minden lehetséges.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 28, 'És Péter kezdé mondani néki: Ímé, mi elhagytunk mindent, és követtünk téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 29, 'Jézus pedig felelvén, monda: Bizony mondom néktek, senki sincs, a ki elhagyta házát, vagy fitestvéreit, vagy nőtestvéreit, vagy atyját, vagy anyját, vagy feleségét, vagy gyermekeit, vagy szántóföldeit én érettem és az evangyéliomért,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 30, 'A ki százannyit ne kapna most ebben az időben, házakat, fitestvéreket, nőtestvéreket, anyákat, gyermekeket és szántóföldeket, üldözésekkel együtt; a jövendő világon pedig örök életet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 31, 'Sok elsők pedig lesznek utolsók, és sok utolsók elsők.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 32, 'Útban valának pedig Jeruzsálembe menve fel; és előttök megy vala Jézus, ők pedig álmélkodának, és követvén őt, félnek vala. És ő a tizenkettőt ismét maga mellé vévén, kezde nékik szólni azokról a dolgokról, a mik majd vele történnek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 33, 'Mondván: Ímé, felmegyünk Jeruzsálembe, és az embernek Fia átadatik a főpapoknak és az írástudóknak, és halálra kárhoztatják őt, és a pogányok kezébe adják őt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 34, 'És megcsúfolják őt, és megostorozzák őt, és megköpdösik őt, és megölik őt; de harmadnapon feltámad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 35, 'És hozzájárulának Jakab és János, a Zebedeus fiai, ezt mondván: Mester, szeretnők, hogy a mire kérünk, tedd meg nékünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 36, 'Ő pedig monda nékik: Mit kívántok, hogy tegyek veletek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 37, 'Azok pedig mondának néki: Add meg nékünk, hogy egyikünk jobb kezed felől, másikunk pedig bal kezed felől üljön a te dicsőségedben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 38, 'Jézus pedig monda nékik: Nem tudjátok, mit kértek. Megihatjátok-é a pohárt, a melyet én megiszom; és megkeresztelkedhettek-é azzal a keresztséggel, a melylyel én megkeresztelkedem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 39, 'Azok pedig mondának néki: Megtehetjük. Jézus pedig monda nékik: A pohárt ugyan, a melyet én megiszom, megiszszátok, és a keresztséggel, a melylyel én megkeresztelkedem, megkeresztelkedtek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 40, 'De az én jobb és bal kezem felől való ülést nem az én dolgom megadni, hanem azoké lesz az, a kiknek elkészíttetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 41, 'És hallván ezt a tíz tanítvány, haragudni kezdének Jakabra és Jánosra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 42, 'Jézus pedig magához szólítván őket, monda nékik: Tudjátok, hogy azok, a kik a pogányok között fejedelmeknek tartatnak, uralkodnak felettök, és az ő nagyjaik hatalmaskodnak rajtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 43, 'De nem így lesz közöttetek; hanem, a ki nagy akar lenni közöttetek, az legyen a ti szolgátok;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 44, 'És a ki közületek első akar lenni, mindenkinek szolgája legyen:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 45, 'Mert az embernek Fia sem azért jött, hogy néki szolgáljanak, hanem hogy ő szolgáljon, és adja az ő életét váltságul sokakért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 46, 'És Jerikóba érkezének: és mikor ő és az ő tanítványai és nagy sokaság Jerikóból kimennek vala, a Timeus fia, a vak Bartimeus, ott üle az úton, koldulván.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 47, 'És a mikor meghallá, hogy ez a Názáreti Jézus, kezde kiáltani, mondván: Jézus, Dávidnak Fia, könyörülj rajtam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 48, 'És sokan feddik vala őt, hogy hallgasson; de ő annál jobban kiáltja vala: Dávidnak Fia, könyörülj rajtam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 49, 'Akkor Jézus megállván, mondá, hogy hívják elő. És előhívják vala a vakot, mondván néki: Bízzál; kelj föl, hív tégedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 50, 'Az pedig felső ruháját ledobván, és felkelvén, Jézushoz méne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 51, 'És felelvén Jézus, monda néki: Mit akarsz, hogy cselekedjem veled? A vak pedig monda néki: Mester, hogy lássak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 52, 'Jézus pedig monda néki: Eredj el, a te hited megtartott téged. És azonnal megjött a szemevilága, és követi vala Jézust az úton.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 53, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, 'És mikor Jeruzsálemhez közeledének, Bethfagé és Bethánia felé, az olajfák hegyénél, elkülde kettőt tanítványai közül,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, 'És monda nékik: Eredjetek abba a faluba, a mely előttetek van; és a mikor abba bejuttok, azonnal találtok egy megkötött vemhet, a melyen ember nem ült még soha; azt oldjátok el és hozzátok ide.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, 'És ha valaki azt mondja néktek: Miért teszitek ezt? mondjátok: Az Úrnak van szüksége reá. És azonnal elbocsátja azt ide.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, 'Elmenének azért és megtalálák a megkötött vemhet, az ajtónál kívül a kettős útnál, és eloldák azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, 'Az ott állók közül pedig némelyek mondának nékik: Mit míveltek, hogy eloldjátok a vemhet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, 'Ők pedig felelének nékik, úgy, a mint Jézus megparancsolta vala. És elbocsáták őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'És oda vivék a vemhet Jézushoz, és ráveték felső ruháikat; ő pedig felüle reá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, 'Sokan pedig felső ruháikat az útra teríték, mások pedig ágakat szegdelnek vala a fákról és az útra hányják vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'A kik pedig előtte menének, és a kik követék, kiáltának, mondván: Hozsánna! Áldott, a ki jő az Úrnak nevében!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, 'Áldott a mi Atyánknak, Dávidnak országa, a mely jő az Úrnak nevében! Hozsánna a magasságban!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, 'És beméne Jézus Jeruzsálembe, és a templomba; és mindent körülnézvén, mivelhogy az idő már késő vala, kiméne Bethániába a tizenkettővel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'És másnap, mikor Bethániából kimentek vala, megéhezék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, 'És meglátván messziről egy fügefát, a mely leveles vala, odaméne, ha talán találna valamit rajta: de odaérvén ahhoz, levélnél egyebet semmit sem talála; mert nem vala fügeérésnek ideje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'Akkor felelvén Jézus, monda a fügefának: Soha örökké ne egyék rólad gyümölcsöt senki. És hallák az ő tanítványai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, 'És Jeruzsálembe érkezének. És Jézus bemenvén a templomba, kezdé kiűzni azokat, a kik a templomban árulnak és vásárolnak vala; a pénzváltók asztalait, és a galambárúsok székeit pedig felforgatá;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'És nem engedi vala, hogy valaki edényt vigyen a templomon keresztül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'És tanít vala, mondván nékik: Nincsen-é megírva: Az én házam imádság házának neveztetik minden nép között? Ti pedig rablók barlangjává tettétek azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, 'És meghallák az írástudók és a főpapok, és tanakodnak vala, hogy mi módon veszíthetnék el őt. Mert félnek vala tőle, mivelhogy az egész sokaság álmélkodik vala az ő tanításán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, 'És mikor beestveledék, kiméne a városból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, 'Reggel pedig, a mikor mellette menének el, látják vala, hogy a fügefa gyökerestől kiszáradott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'És Péter visszaemlékezvén, monda néki: Mester nézd, a fügefa, a melyet megátkoztál, kiszáradott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, 'És Jézus felelvén, monda nékik: Legyen hitetek Istenben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, 'Mert bizony mondom néktek, ha valaki azt mondja ennek a hegynek: Kelj fel és ugorjál a tengerbe! és szívében nem kételkedik, hanem hiszi, hogy a mit mond, megtörténik, meg lesz néki, a mit mondott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 24, 'Azért mondom néktek: A mit könyörgéstekben kértek, higyjétek, hogy mindazt megnyeritek, és meglészen néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 25, 'És mikor imádkozva megállotok, bocsássátok meg, ha valaki ellen valami panaszotok van; hogy a ti mennyei Atyátok is megbocsássa néktek a ti vétkeiteket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 26, 'Ha pedig ti meg nem bocsátotok, a ti mennyei Atyátok sem bocsátja meg a ti vétkeiteket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 27, 'És ismét Jeruzsálembe menének. Mikor pedig ő a templomban körüljára, hozzámennek vala a főpapok és az írástudók és a vének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 28, 'És mondának néki: Micsoda hatalommal cselekszed ezeket? és ki adta néked a hatalmat, hogy ezeket cselekedd?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 29, 'Jézus pedig felelvén, monda nékik: Én is kérdek egy dolgot tőletek, és feleljetek meg nékem, akkor megmondom néktek, hogy miféle hatalomnál fogva cselekszem ezeket:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 30, 'A János keresztsége mennyből vala-é, vagy emberektől? feleljetek nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 31, 'Azok pedig tanakodnak vala maguk között, mondván: Ha azt mondjuk: Mennyből, azt fogja mondani: Miért nem hittetek tehát néki?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 32, 'Ha pedig azt mondjuk: Emberektől, – félnek vala a néptől. Mert mindenki azt tartja vala Jánosról, hogy valóban próféta vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 33, 'Felelvén tehát, mondának Jézusnak: Nem tudjuk. Jézus is felelvén, monda nékik: Én sem mondom meg néktek, miféle hatalomnál fogva cselekszem ezeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'És kezde nékik példázatokban beszélni: Egy ember szőlőt ültetett, és körülvevé gyepűvel, és sajtót ása, és tornyot építe, és kiadá azt munkásoknak, és elutazék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, 'És a maga idejében szolgát külde a munkásokhoz, hogy kapjon a munkásoktól a szőlő gyümölcséből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, 'Azok pedig megfogván azt, megverék, és üresen küldék vissza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, 'És ismét külde hozzájuk egy másik szolgát; azt pedig kővel dobálván meg, fejét betörék, és gyalázattal illetve, visszaküldék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'És ismét másikat külde; ezt pedig megölék: és sok másokat; némelyeket megvervén, némelyeket pedig megölvén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'Minthogy pedig még egy egyetlen szerelmes fia is vala, utoljára azt is elküldé hozzájok, ezt mondván: A fiamat meg fogják becsülni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'Azok a munkások azonban ezt mondák magok között: Ez az örökös; jertek, öljük meg őt, és a miénk lesz az örökség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, 'És megfogván azt, megölék, és a szőlőn kívül veték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'Mit cselekszik hát a szőlőnek ura? Eljő és elveszti a munkásokat, és a szőlőt másoknak adja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, 'Ezt az írást sem olvastátok-é? A mely követ az építők megvetettek, az lett a szeglet fejévé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'Az Úrtól lett ez, és csodálatos a mi szemeink előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'És igyekeznek vala őt megfogni, de féltek a sokaságtól. Mert tudták, hogy a példázatot ellenük mondotta. Azért elhagyván őt, tovább menének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'És küldének hozzá némelyeket a farizeusok és a Heródes pártiak közül, hogy megfogják őt a beszédben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'Azok pedig odamenvén, mondának néki: Mester, tudjuk hogy igaz vagy és nem gondolsz senkivel; mert nem tekintesz emberek személyére, hanem igazság szerint tanítod az Istennek útját. Szabad-é a császárnak adót fizetni vagy nem? Fizessünk-é vagy ne fizessünk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'Ő pedig ismervén az ő képmutatásukat, monda nékik: Mit kísértetek engem? Hozzatok nekem egy pénzt, hogy lássam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, 'Azok pedig hozának. És monda nékik: Kié ez a kép és a felírás? Azok pedig mondának néki: A Császáré.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'És felelvén Jézus, monda nékik: Adjátok meg a mi a Császáré, a Császárnak, és a mi az Istené, az Istennek. És elálmélkodának ő rajta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'És jövének hozzá Sadduczeusok, a kik azt mondják, hogy nincsen feltámadás. És megkérdezék őt, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, 'Mester, Mózes azt írta nékünk, hogy ha valakinek fitestvére meghalt, és feleséget hagyott hátra, gyermekeket pedig nem hagyott, akkor az ő feleségét vegye el az ő fitestvére, és támasszon magot a fitestvérének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'Heten valának tehát fitestvérek. És az első feleséget vőn, de meghalván, magot nem hagya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 21, 'És a második elvevé az asszonyt, de meghala, és magot ő sem hagya: a harmadik is hasonlóképen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 22, 'És mind a hét elvevé azt, és magot nem hagyának. Legutoljára meghalt az asszony is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 23, 'A feltámadáskor tehát, mikor feltámadnak, melyiköknek lesz a felesége? Mert mind a hétnek a felesége volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 24, 'Jézus pedig felelvén, monda nékik: Avagy nem azért tévelyegtek-é, mert nem ismeritek az írásokat, sem az Istennek hatalmát?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 25, 'Mert mikor a halálból feltámadnak, sem nem házasodnak, sem férjhez nem mennek, hanem olyanok lesznek, mint az angyalok a mennyekben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 26, 'A halottakról pedig, hogy feltámadnak, nem olvastátok-é a Mózes könyvében, a csipkebokornál, hogy mi módon szólott néki az Isten, mondván: Én vagyok Ábrahám Istene, és Izsák Istene, és Jákób Istene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 27, 'Az Isten nem holtaknak, hanem élőknek Istene. Ti tehát igen tévelyegtek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 28, 'Akkor hozzá menvén egy az írástudók közül, a ki az ő vetekedésöket hallotta vala, és tudván, hogy jól megfelele nékik, megkérdezé tőle: Melyik az első minden parancsolatok között?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 29, 'Jézus pedig felele néki: Minden parancsolatok között az első: Halljad Izráel: Az Úr, a mi Istenünk egy Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 30, 'Szeressed azért az Urat, a te Istenedet teljes szívedből, teljes lelkedből, és teljes elmédből és teljes erődből. Ez az első parancsolat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 31, 'A második pedig hasonlatos ehhez: Szeresd felebarátodat, mint magadat. Nincs más ezeknél nagyobb parancsolat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 32, 'Akkor monda néki az írástudó: Jól van, Mester, igazán mondád, hogy egy Isten van, és nincsen kívüle más.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 33, 'És szeretni őt teljes szívből, teljes elméből, teljes lélekből és teljes erőből, és szeretni embernek felebarátját, mint önmagát, többet ér minden égőáldozatnál és véres áldozatnál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 34, 'Jézus pedig látván, hogy bölcsen felelt vala, monda néki: Nem messze vagy az Isten országától. És többé senki sem meri vala őt megkérdezni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 35, 'És felele Jézus és monda, a mint a templomban tanít vala: Mi módon mondják az írástudók, hogy a Krisztus Dávidnak Fia?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 36, 'Hiszen Dávid maga mondotta a Szent Lélek által: Monda az Úr az én uramnak: ülj az én jobb kezem felől, míglen vetem a te ellenségeidet lábaid alá zsámolyul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 37, 'Tehát maga Dávid nevezi őt Urának, mimódon fia hát néki? És a nagy sokaság örömest hallgatja vala őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 38, 'Ő pedig monda nékik az ő tanításában: Őrizkedjetek az írástudóktól, a kik örömest járnak hosszú köntösökben és szeretik a piaczokon való köszöntéseket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 39, 'És a gyülekezetekben az előlüléseket, és a lakomákon a főhelyeket:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 40, 'A kik az özvegyeknek házát fölemésztik és színből hosszan imádkoznak: ezek súlyosabb ítélet alá esnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 41, 'És leülvén Jézus a templomperselynek átellenében, nézi vala, hogy a sokaság miként vet pénzt a perselybe. Sok gazdag pedig sokat vet vala abba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 42, 'És egy szegény özvegy asszony is odajövén, két fillért, azaz egy negyed pénzt vete bele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 43, 'Akkor előszólítván tanítványait, monda nékik: Bizony mondom néktek, hogy ez a szegény özvegy asszony többet vetett, hogynem mind a többi, a kik a perselybe vetettek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 44, 'Mert azok mindnyájan az ő fölöslegükből vetének; ez pedig az ő szegénységéből, a mije csak volt, mind beveté, az ő egész vagyonát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'Mikor pedig a templomból kiméne, monda néki egy az ő tanítványai közül: Mester, nézd, milyen kövek és milyen épületek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, 'Jézus pedig felelvén, monda néki: Látod ezeket a nagy épületeket? Nem marad kő kövön, a mely le nem romboltatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'Mikor pedig az olajfák hegyén ül vala, a templom átellenében, megkérdezék őt magukban Péter, Jakab, János és András:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, 'Mondd meg nékünk, mikor történnek meg ezek; és mi lesz a jel, a mikor mindezek beteljesednek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'Jézus pedig felelvén nékik, kezdé mondani: Meglássátok, hogy valaki el ne hitessen titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, 'Mert sokan jőnek majd az én nevemben, a kik azt mondják: Én vagyok: és sokakat elhitetnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, 'Mikor pedig hallani fogtok háborúkról és háborúk híreiről, meg ne rémüljetek, mert meg kell lenniök; de ez még nem a vég.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, 'Mert nemzet nemzet ellen, és ország ország ellen támad; és lesznek földindulások mindenfelé, és lesznek éhségek és háborúságok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, 'Nyomorúságoknak kezdetei ezek. Ti pedig vigyázzatok magatokra: mert törvényszékeknek adnak át titeket, és gyülekezetekben vernek meg titeket, és helytartók és királyok elé állítanak én érettem, bizonyságul ő nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'De előbb hirdettetnie kell az evangyéliomnak minden pogányok között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, 'Mikor pedig fogva visznek, hogy átadjanak titeket, ne aggodalmaskodjatok előre, hogy mit szóljatok, és ne gondolkodjatok, hanem a mi adatik néktek abban az órában, azt szóljátok; mert nem ti vagytok, a kik szólotok, hanem a Szent Lélek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, 'Halálra fogja pedig adni testvér testvérét, atya gyermekét; és magzatok támadnak szülők ellen, és megöletik őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, 'És lesztek gyűlöletesek mindenki előtt az én nevemért; de a ki mindvégig megmarad, az megtartatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, 'Mikor pedig látjátok a pusztító utálatosságot, a melyről Dániel próféta szólott, ott állani, a hol nem kellene (a ki olvassa, értse meg), akkor a kik Júdeában lesznek, fussanak a hegyekre;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, 'A háztetőn levő pedig le ne szálljon a házba, se be ne menjen, hogy házából valamit kivigyen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, 'És a mezőn levő haza ne térjen, hogy ruháját elvigye.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, 'Jaj pedig a terhes és a szoptató asszonyoknak azokban a napokban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'Imádkozzatok pedig, hogy a ti futástok ne télen legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'Mert azok a napok olyan nyomorúságosak lesznek, a milyenek a világ kezdete óta, a melyet Isten teremtett, mind ez ideig nem voltak, és nem is lesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, 'És ha az Úr meg nem rövidítette volna azokat a napokat, egyetlen test sem menekülne meg; de a választottakért, a kiket kiválasztott, megrövidítette azokat a napokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 21, 'Ha pedig akkor ezt mondja néktek valaki: Ímé itt a Krisztus, vagy: Ímé amott, ne higyjétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 22, 'Mert hamis Krisztusok és hamis próféták támadnak, és jeleket és csodákat tesznek, hogy elhitessék, ha lehet, még a választottakat is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 23, 'Ti pedig vigyázzatok; ímé előre megmondottam néktek mindent.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 24, 'De azokban a napokban, azután a nyomorúság után, a nap elsötétedik, és a hold nem fénylik,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 25, 'És az ég csillagai lehullanak, és az egekben levő hatalmasságok megrendülnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 26, 'És akkor meglátják az embernek Fiát eljőni felhőkben nagy hatalommal és dicsőséggel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 27, 'És akkor elküldi az ő angyalait, és egybegyűjti az ő választottait a négy szelek felől, a föld végső határától az ég végső határáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 28, 'A fügefáról vegyétek pedig a példát. A mikor ága már zsendül, és levelet hajt, tudjátok, hogy közel van a nyár.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 29, 'Azonképen ti is, mikor látjátok, hogy ezek meglesznek, tudjátok meg, hogy közel van, az ajtó előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 30, 'Bizony mondom néktek, hogy el nem múlik ez a nemzetség, a míg meg nem lesznek mindezek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 31, 'Az ég és a föld elmúlnak, de az én beszédeim soha el nem múlnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 32, 'Arról a napról és óráról pedig senki semmit sem tud, sem az égben az angyalok, sem a Fiú, hanem csak az Atya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 33, 'Figyeljetek, vigyázzatok és imádkozzatok; mert nem tudjátok, mikor jő el az az idő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 34, 'Úgy mint az az ember, a ki messze útra kelve, házát elhagyván, és szolgáit felhatalmazván, és kinek-kinek a maga dolgát megszabván, az ajtónállónak is megparancsolta, hogy vigyázzon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 35, 'Vigyázzatok azért, mert nem tudjátok, mikor érkezik meg a háznak ura, este-é vagy éjfélkor, vagy kakasszókor, vagy reggel?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 36, 'Hogy, ha hirtelen megérkezik, ne találjon titeket aludva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 37, 'A miket pedig néktek mondok, mindenkinek mondom: Vigyázzatok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'Két nap mulva pedig húsvét vala és a kovásztalan kenyerek ünnepe. És a főpapok és az írástudók tanakodnak vala, hogy csalárdsággal mimódon fogják meg és öljék meg őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, 'Mert azt mondják vala: Ne az ünnepen, hogy a nép fel ne zendüljön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'Mikor pedig Bethániában a poklos Simon házánál vala, a mint asztalhoz üle, egy asszony méne oda, a kinél alabástrom edény vala valódi és igen drága nárdus olajjal; és eltörvén az alabástrom edényt kitölté azt az ő fejére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'Némelyek pedig háborognak vala magok között és mondának: Mire való volt az olajnak ez a tékozlása?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'Mert el lehetett volna azt adni háromszáz pénznél is többért, és odaadni a szegényeknek. És zúgolódnak vala ellene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'Jézus pedig monda: Hagyjatok békét néki; miért bántjátok őt? jó dolgot cselekedett én velem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, 'Mert a szegények mindenkor veletek lesznek, és a mikor csak akarjátok, jót tehettek velök; de én nem leszek mindenkor veletek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, 'Ő a mi tőle telt, azt tevé: előre megkente az én testemet a temetésre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'Bizony mondom néktek: Valahol csak prédikálják ezt az evangyéliomot az egész világon, a mit ez az asszony cselekedett, azt is hirdetni fogják az ő emlékezetére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'Akkor Júdás, az Iskariotes, egy a tizenkettő közül, elméne a főpapokhoz, hogy őt azoknak elárulja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, 'Azok pedig, a mint meghallák, örvendezének, és igérék, hogy pénzt adnak néki. Ő pedig keresi vala, mimódon árulhatná el őt jó alkalommal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, 'És a kovásztalan kenyerek ünnepének első napján, mikor a húsvéti bárányt vágják vala, mondának néki az ő tanítványai: Hol akarod, hogy elmenvén megkészítsük, hogy megehesd a húsvéti bárányt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'Akkor elkülde kettőt az ő tanítványai közül, és monda nékik: Menjetek el a városba, és egy ember jő előtökbe, a ki egy korsó vizet visz; kövessétek őt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'És a hová bemegy, mondjátok a házi gazdának: A Mester kérdi: hol van az a szállás, a hol megeszem az én tanítványaimmal a húsvéti bárányt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'És ő mutat néktek egy nagy vacsoráló házat berendezve, készen: ott készítsétek el nékünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, 'Elmenének azért az ő tanítványai, és jutának a városba, és úgy találák, a mint nékik megmondotta, és elkészíték a húsvéti bárányt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, 'Mikor pedig este lőn, oda méne a tizenkettővel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, 'És a mikor leülnek és esznek vala monda Jézus: Bizony mondom néktek, egy közületek elárul engem, a ki velem eszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, 'Ők pedig kezdének szomorkodni és néki egyenként mondani: Csak nem én? A másik is: Csak nem én?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 20, 'Ő pedig felelvén, monda nékik: Egy a tizenkettő közül, a ki velem együtt márt a tálba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 21, 'Az embernek Fia jóllehet elmegy, a mint meg van írva felőle; de jaj annak az embernek, a ki az embernek Fiát elárulja; jobb lenne annak az embernek, ha nem született volna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 22, 'És mikor ők evének, vévén Jézus a kenyeret, és hálákat adván, megtöré és adá nékik, mondván: Vegyétek, egyétek; ez az én testem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 23, 'És vévén a poharat, és hálákat adván, adá nékik; és ivának abból mindnyájan;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 24, 'És monda nékik: Ez az én vérem, az új szövetség vére, a mely sokakért kiontatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 25, 'Bizony mondom néktek, nem iszom többé a szőlőtőnek gyümölcséből mind ama napig, a mikor mint újat iszom azt az Isten országában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 26, 'És dicséretet énekelve kimenének az olajfák hegyére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 27, 'És monda nékik Jézus: Ezen az éjszakán mindnyájan megbotránkoztok bennem; mert meg van írva: Megverem a pásztort, és elszélednek a juhok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 28, 'De feltámadásom után előttetek fogok felmenni Galileába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 29, 'Péter pedig monda néki: Ha mindnyájan megbotránkoznak is, de én nem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 30, 'És monda néki Jézus: Bizony mondom néked, hogy ma, ezen az éjszakán, mielőtt a kakas kétszer szólana, háromszor tagadsz meg engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 31, 'Ő pedig annál inkább erősíti vala: Ha veled együtt kell is meghalnom, semmiképen meg nem tagadlak téged. Hasonlóképen szólanak vala a többiek is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 32, 'És menének ama helyre, a melynek Gecsemáné a neve; és monda az ő tanítványainak: Üljetek le itt, a míg imádkozom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 33, 'És maga mellé vevé Pétert és Jakabot és Jánost, és kezde rettegni és gyötrődni;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 34, 'És monda nékik: Szomorú az én lelkem mind halálig; maradjatok itt, és vigyázzatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 35, 'És egy kevéssé előre menvén, a földre esék, és imádkozék, hogy, ha lehetséges, múljék el tőle ez az óra;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 36, 'És monda: Abba, Atyám! Minden lehetséges néked. Vidd el tőlem ezt a poharat; mindazáltal ne az én akaratom legyen meg, hanem a tied.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 37, 'Azután visszatére és aluva találá őket, és monda Péternek: Simon, alszol? Nem bírtál egy óráig vigyázni?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 38, 'Vigyázzatok és imádkozzatok, hogy kísértetbe ne jussatok; a lélek ugyan kész, de a test erőtelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 39, 'És ismét elmenvén, imádkozék, ugyanazon szavakkal szólván.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 40, 'A mikor pedig visszatére, ismét aluva találá őket; mert a szemeik megnehezedtek vala, és nem tudták mit feleljenek néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 41, 'Harmadszor is jöve, és monda nékik: Aludjatok immár és nyugodjatok. Elég; eljött az óra; ímé az embernek Fia a bűnösök kezébe adatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 42, 'Keljetek föl, menjünk: ímé elközelgett, a ki engem elárul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 43, 'És mindjárt még mikor ő szól vala, eljöve Júdás, egy a tizenkettő közül, és vele együtt nagy sokaság, fegyverekkel és botokkal, a főpapoktól, az írástudóktól és a vénektől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 44, 'Az ő elárulója pedig jelt ada nékik, mondván: A kit megcsókolok majd, ő az; fogjátok meg azt, és vigyétek el biztonsággal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 45, 'És odajutván, azonnal hozzáméne, és monda: Mester! Mester! és megcsókolá őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 46, 'Azok pedig ráveték kezeiket, és megfogák őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 47, 'De egy az ott állók közül az ő szablyáját kivonván, a főpap szolgájához csapa, és levágá annak fülét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 48, 'Jézus pedig felelvén, monda nékik: Mint egy rablóra, úgy jöttetek-é reám fegyverekkel és botokkal, hogy megfogjatok engem?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 49, 'Naponta nálatok valék, a templomban tanítva, és nem fogtatok meg engem; de szükség, hogy az írások beteljesedjenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 50, 'Akkor elhagyván őt, mindnyájan elfutának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 51, 'Egy ifjú pedig követé őt, a kinek testét csak egy gyolcs ing takarta; és megfogák őt az ifjak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 52, 'De ő ott hagyva az ingét, meztelenül elszalada tőlük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 53, 'És vivék Jézust a főpaphoz. És oda gyűlének mindnyájan a főpapok, a vének és az írástudók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 54, 'Péter pedig távolról követé őt, be egészen a főpap udvaráig: és ott üle a szolgákkal, és melegszik vala a tűznél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 55, 'A főpapok pedig és az egész tanács bizonyságot keresnek vala Jézus ellen, hogy megölhessék őt; de nem találnak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 56, 'Mert sokan tesznek vala ugyan hamis tanúbizonyságot ellene, de a bizonyságtételek nem valának megegyezők.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 57, 'És némelyek fölkelének és hamis tanúbizonyságot tőnek ellene, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 58, 'Mi hallottuk, mikor ezt mondá: Én lerontom ezt a kézzel csinált templomot, és három nap alatt mást építek, a mely nem kézzel csináltatott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 59, 'De még így sem vala egyező az ő bizonyságtételük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 60, 'Akkor a főpap odaállván a középre, megkérdé Jézust, mondván: Semmit sem felelsz-é? Miféle bizonyságot tesznek ezek te ellened?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 61, 'Ő pedig hallgat vala, és semmit sem felele. Ismét megkérdezé őt a főpap, és monda néki: Te vagy-é a Krisztus, az áldott Isten Fia?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 62, 'Jézus pedig monda: Én vagyok. És meglátjátok majd az embernek Fiát ülni a hatalomnak jobbján, és eljőni az ég felhőivel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 63, 'A főpap pedig megszaggatván ruháit, monda: Mi szükségünk van még tanúkra?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 64, 'Hallátok a káromlást. Mi tetszik néktek? Azok pedig halálra méltónak ítélték őt mindnyájan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 65, 'És kezdék őt némelyek köpdösni, és az ő orczáját elfedni, és őt öklözni, és mondani néki: Prófétálj! A szolgák pedig arczul csapdossák vala őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 66, 'A mint pedig Péter lent vala az udvarban, odajöve egy a főpap szolgálói közül;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 67, 'És meglátván Pétert, a mint melegszik vala, rátekintvén, monda: Te is a Názáreti Jézussal valál!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 68, 'Ő pedig megtagadá, mondván: Nem ismerem, s nem is értem, mit mondasz. És kiméne a tornáczra; és a kakas megszólala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 69, 'A szolgáló pedig meglátva őt, kezdé ismét mondani az ott állóknak: Ez közülök való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 70, 'Ő pedig ismét megtagadá. De kevés idő múlva az ott állók ismét mondják vala Péternek: Bizony közülök való vagy; mert Galileabeli is vagy, és a beszéded is hasonló.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 71, 'Ő pedig kezde átkozódni és esküdözni, hogy: Nem ismerem azt az embert, a kiről beszéltek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 72, 'És másodszor szóla a kakas. És Péternek eszébe juta a beszéd, a melyet néki Jézus mondott vala, hogy mielőtt a kakas kétszer szólana, háromszor megtagadsz engem. És sírva fakada.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, 'És mindjárt reggel tanácsot tartván a főpapok a vénekkel és írástudókkal, és az egész tanács, megkötözvén Jézust, elvivék és átadák Pilátusnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'És megkérdé őt Pilátus: Te vagy-é a zsidók királya? Ő pedig felelvén, monda néki: Te mondod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, 'És erősen vádolják vala őt a főpapok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'Pilátus pedig ismét megkérdé őt, mondván: Semmit sem felelsz-é? Ímé, mennyi tanúbizonyságot szólnak ellened!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'Jézus pedig semmit sem felele, annyira hogy Pilátus elcsudálkozék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'Ünnepenként pedig egy foglyot szokott vala elbocsátani nékik, a kit épen óhajtának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'Vala pedig egy Barabbás nevű, megkötöztetve ama lázadókkal együtt, a kik a lázadás alkalmával gyilkosságot követtek vala el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, 'És a sokaság kiáltván, kezdé kérni Pilátust arra, a mit mindenkor megtesz vala nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'Pilátus pedig felele nékik, mondván: Akarjátok-é, hogy elbocsássam néktek a zsidók királyát?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, 'Mert tudja vala, hogy irígységből adták őt kézbe a főpapok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'A főpapok azonban felindíták a sokaságot, hogy inkább Barabbást bocsássa el nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'Pilátus pedig felelvén, ismét monda nékik: Mit akartok tehát, hogy cselekedjem ezzel, a kit a zsidók királyának mondotok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, 'És azok ismét kiáltának: Feszítsd meg őt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, 'Pilátus pedig monda nékik: Mert mi rosszat cselekedett? Azok pedig annál jobban kiáltanak vala: Feszítsd meg őt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 15, 'Pilátus pedig eleget akarván tenni a sokaságnak, elbocsátá nékik Barabbást, Jézust pedig megostoroztatván, kezökbe adá, hogy megfeszítsék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 16, 'A vitézek pedig elvivék őt az udvar belső részébe, a mi az őrház; és összehívák az egész csapatot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 17, 'És bíborba öltözteték őt, és tövisből font koszorút tevének a fejére,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 18, 'És elkezdék őt köszönteni: Üdvöz légy, zsidók királya!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 19, 'És verik vala a fejét nádszállal, és köpdösik vala őt, és térdet hajtva tisztelik vala őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 20, 'Mikor pedig kicsúfolták őt, leveték róla a bíbor ruhát, és a maga ruháiba öltözteték; és kivivék őt, hogy megfeszítsék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 21, 'És kényszerítének egy mellettök elmenőt, bizonyos czirénei Simont, a ki a mezőről jő vala, Alekszándernek és Rufusnak az atyját, hogy vigye az ő keresztjét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 22, 'És vivék őt a Golgotha nevű helyre, a mely megmagyarázva annyi, mint: koponya helye.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 23, 'És mirhás bort adnak vala néki inni; de ő nem fogadá el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 24, 'És megfeszítvén őt, eloszták az ő ruháit, sorsot vetvén azokra, ki mit kapjon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 25, 'Vala pedig három óra, mikor megfeszíték őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 26, 'Az ő kárhoztatásának oka pedig így vala fölébe felírva: A zsidók királya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 27, 'Két rablót is megfeszítének vele, egyet jobb és egyet bal keze felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 28, 'És beteljesedék az írás, a mely azt mondja: És a bűnösök közé számláltaték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 29, 'Az arra menők pedig szidalmazzák vala őt, fejüket hajtogatván és mondván: Hah! a ki lerontod a templomot, és három nap alatt fölépíted;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 30, 'Szabadítsd meg magadat, és szállj le a keresztről!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 31, 'Hasonlóképen pedig a főpapok is, csúfolodván egymás között, az írástudókkal együtt mondják vala: Másokat megtartott, magát nem bírja megtartani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 32, 'A Krisztus, az Izráel királya, szálljon le most a keresztről, hogy lássuk és higyjünk. A kiket vele feszítettek meg, azok is szidalmazzák vala őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 33, 'Mikor pedig hat óra lőn, sötétség támada az egész földön kilencz óráig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 34, 'És kilencz órakor fennszóval kiálta Jézus mondván: Elói, Elói! Lamma Sabaktáni? a mi megmagyarázva annyi, mint: Én Istenem, én Istenem! miért hagyál el engemet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 35, 'Némelyek pedig meghallván ezt az ott állók közül, mondának: Ímé Illést hívja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 36, 'Egy ember pedig odafutamodék és egy szivacsot megtöltvén eczettel és azt nádszálra tűzvén, inni ada néki, mondván: Hagyjátok el, lássuk, ha eljő-é Illés, hogy levegye őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 37, 'Jézus pedig nagy fennszóval kiáltván kibocsátá lelkét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 38, 'És a templom kárpítja fölétől aljáig ketté hasada.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 39, 'Látván pedig a százados, a ki vele átellenben áll vala, hogy ekként kiáltva bocsátá ki lelkét, monda: Bizony, ez az ember Isten Fia vala!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 40, 'Valának pedig asszonyok is, a kik távolról nézik vala, a kik között vala Mária Magdaléna, és Mária, a kis Jakabnak és Józsénak anyja, és Salomé,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 41, 'A kik, mikor Galileában vala, akkor is követték vala őt, és szolgálnak vala néki; és sok más asszony, a kik vele mentek vala fel Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 42, 'És mikor immár este lőn, mivelhogy péntek vala, azaz szombat előtt való nap,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 43, 'Eljöve az arimathiai József, egy tisztességes tanácsbeli, a ki maga is várja vala az Isten országát; beméne bátran Pilátushoz, és kéré Jézusnak testét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 44, 'Pilátus pedig csodálkozék, hogy immár meghalt volna; és magához hivatva a századost, megkérdé tőle, ha régen halt-é meg?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 45, 'És megtudván a századostól, odaajándékozá a testet Józsefnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 46, 'Ő pedig gyolcsot vásárolván, és levévén őt, begöngyölé a gyolcsba, és elhelyezé egy sírboltba, a mely kősziklából vala kivágva; és követ hengeríte a sírbolt szájára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 47, 'Mária Magdaléna pedig és Mária, a Józsé anyja, nézik vala, hová helyezék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, 'Mikor pedig elmult a szombat, Mária Magdaléna, és Mária a Jakab anyja, és Salomé, drága keneteket vásárlának, hogy elmenvén, megkenjék őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, 'És korán reggel, a hétnek első napján a sírbolthoz menének napfelköltekor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, 'És mondják vala maguk között: Kicsoda hengeríti el nékünk a követ a sírbolt szájáról?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, 'És odatekintvén, láták, hogy a kő el van hengerítve; mert felette nagy vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, 'És bemenvén a sírboltba, látának egy ifjút ülni jobb felől, fehér ruhába öltözve; és megfélemlének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, 'Az pedig monda nékik: Ne féljetek. A Názáreti Jézust keresitek, a ki megfeszíttetett; föltámadott, nincsen itt; ímé a hely, a hová őt helyezék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'De menjetek el, mondjátok meg az ő tanítványainak és Péternek, hogy előttetek megyen Galileába; ott meglátjátok őt, a mint megmondotta néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, 'És nagyhamar kijövén, elfutának a sírbolttól, mert félelem és álmélkodás fogta vala el őket; és senkinek semmit sem szólának, mert félnek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, 'Mikor pedig reggel, a hétnek első napján föltámadott vala, megjelenék először Mária Magdalénának, a kiből hét ördögöt űzött vala ki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'Ez elmenvén, megjelenté azoknak, a kik vele valának és keseregnek és sírnak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, 'Azok pedig mikor hallották, hogy él és ő látta vala, nem hivék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, 'Ezután pedig közülök kettőnek jelenék meg más alakban, útközben, mikor a mezőre mennek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, 'Ezek is elmenvén, megjelenték a többieknek; ezeknek sem hivének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, 'Azután, mikor asztalnál ülnek vala megjelenék magának a tizenegynek, és szemükre hányá az ő hitetlenségöket és keményszívűségöket, hogy azoknak, a kik őt feltámadva látták vala, nem hivének,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'És monda nékik: Elmenvén e széles világra, hirdessétek az evangyéliomot minden teremtésnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, 'A ki hiszen és megkeresztelkedik, idvezül; a ki pedig nem hiszen, elkárhozik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, 'Azokat pedig, a kik hisznek, ilyen jelek követik: az én nevemben ördögöket űznek; új nyelveken szólnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, 'Kígyókat vesznek föl; és ha valami halálost isznak, meg nem árt nékik: betegekre vetik kezeiket, és meggyógyulnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, 'Az Úr azért, minekutána szólott vala nékik, felviteték a mennybe, és üle az Istennek jobbjára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, 'Azok pedig kimenvén, prédikálának mindenütt, az Úr együtt munkálván velök, és megerősítvén az ígét a jelek által, a melyek követik vala. Ámen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'Mivelhogy sokan kezdették rendszerint megírni azoknak a dolgoknak az elbeszélését, a melyek minálunk beteljesedtek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'A mint nékünk előnkbe adták, a kik kezdettől fogva szemtanúi és szolgái voltak az ígének:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, 'Tetszék énnékem is, ki eleitől fogva mindeneknek szorgalmasan végére jártam, hogy azokról rendszerint írjak néked, jó Theofilus,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'Hogy megtudhasd azoknak a dolgoknak bizonyosságát, a melyekre taníttatál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'Heródesnek, a Júdea királyának idejében vala egy Zakariás nevű pap az Abia rendjéből; az ő felesége pedig az Áron leányai közül való vala, és annak neve Erzsébet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'És mind a ketten igazak valának az Isten előtt, kik az Úrnak minden parancsolataiban és rendeléseiben feddhetetlenül jártak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'És nem volt nékik gyermekük, mert Erzsébet meddő vala, és mind a ketten immár idős emberek valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'Lőn pedig, hogy mikor ő rendjének sorában papi szolgálatot végzett az Isten előtt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'A papi tiszt szokása szerint reá jutott a sor, hogy bemenvén az Úrnak templomába, jó illatot gerjesszen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'És a népnek egész sokasága imádkozék kívül a jó illatozás idején;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'Néki pedig megjelenék az Úrnak angyala, állván a füstölő oltár jobbja felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'És láttára megrettene Zakariás, és félelem szállá meg őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'Monda pedig az angyal néki: Ne félj Zakariás; mert meghallgattatott a te könyörgésed, és a te feleséged Erzsébet szül néked fiat, és nevezed az ő nevét Jánosnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'És lészen tenéked örömödre és vigasságodra, és sokan fognak örvendezni az ő születésén;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'Mert nagy lészen az Úr előtt, és bort és részegítő italt nem iszik; és betelik Szent Lélekkel még az ő anyjának méhétől fogva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'És az Izrael fiai közül sokakat megtérít az Úrhoz, az ő Istenükhöz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, 'És ez Ő előtte fog járni az Illés lelkével és erejével, hogy az atyák szívét a fiakhoz térítse, és az engedetleneket az igazak bölcsességére, hogy készítsen az Úrnak tökéletes népet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, 'És monda Zakariás az angyalnak: Miről tudhatom én ezt meg? mert én vén vagyok, és az én feleségem is igen idős.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 19, 'És felelvén az angyal, monda néki: Én Gábriel vagyok, ki az Isten előtt állok; és küldettem, hogy szóljak veled, és ez örvendetes dolgokat jelentsem néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 20, 'És ímé megnémulsz és nem szólhatsz mindama napig, a melyen ezek meglesznek: mivelhogy nem hittél az én beszédimnek, a melyek beteljesednek az ő idejökben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 21, 'A nép pedig várja vala Zakariást, és csodálkozék, hogy a templomban késik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 22, 'És kijövén, nem szólhata nékik; eszökbe vevék azért, hogy látást látott a templomban; mert ő csak integetett nékik, és néma maradt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 23, 'És lőn, hogy mikor leteltek az ő szolgálatának napjai, elméne haza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 24, 'E napok után pedig fogada méhében Erzsébet az ő felesége, és elrejtőzék öt hónapig, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 25, 'Így cselekedett velem az Úr a napokban, a melyekben reám tekinte, hogy elvegye az én gyalázatomat az emberek között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 26, 'A hatodik hónapban pedig elküldeték Gábriel angyal Istentől Galileának városába, a melynek neve Názáret,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 27, 'Egy szűzhöz, a ki a Dávid házából való József nevű férfiúnak volt eljegyezve. A szűznek neve pedig Mária.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 28, 'És bemenvén az angyal ő hozzá, monda néki: Örülj, kegyelembe fogadott! Az Úr veled van, áldott vagy te az asszonyok között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 29, 'Az pedig látván, megdöbbene az ő beszédén, és elgondolkodék, hogy micsoda köszöntés ez?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 30, 'És monda néki az angyal: Ne félj Mária, mert kegyelmet találtál az Istennél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 31, 'És ímé fogansz a te méhedben, és szülsz fiat, és nevezed az ő nevét JÉZUSNAK.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 32, 'Ez nagy lészen, és a Magasságos Fiának hivattatik; és néki adja az Úr Isten a Dávidnak, az ő atyjának, királyi székét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 33, 'És uralkodik a Jákób házán mindörökké; és az ő királyságának vége nem lészen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 34, 'Monda pedig Mária az angyalnak: Mimódon lesz ez, holott én férfiat nem ismerek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 35, 'És felelvén az angyal, monda néki: A Szent Lélek száll te reád, és a Magasságosnak ereje árnyékoz meg téged; azért a mi születik is szentnek hivatik, Isten Fiának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 36, 'És ímé Erzsébet, a te rokonod, ő is fogant fiat az ő vénségében; és ez már a hatodik hónapja néki, a kit meddőnek hívtak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 37, 'Mert az Istennél semmi sem lehetetlen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 38, 'Monda pedig Mária: Imhol az Úrnak szolgálója; legyen nékem a te beszéded szerint. És elméne ő tőle az angyal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 39, 'Fölkelvén pedig Mária azokban a napokban, nagy sietséggel méne a hegységbe, Júdának városába;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 40, 'És beméne Zakariásnak házába, és köszönté Erzsébetet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 41, 'És lőn, mikor hallotta Erzsébet Mária köszöntését, a magzat repese az ő méhében; és betelék Erzsébet Szent Lélekkel;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 42, 'És fennszóval kiálta, mondván: Áldott vagy te az asszonyok között, és áldott a te méhednek gyümölcse.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 43, 'És honnét van ez nékem, hogy az én Uramnak anyja jön én hozzám?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 44, 'Mert ímé, mihelyt a te köszöntésednek szava füleimbe hatolt, a magzat örvendezéssel kezde repesni az én méhemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 45, 'És boldog az, a ki hitt; mert beteljesednek azok, a miket az Úr néki mondott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 46, 'Akkor monda Mária: Magasztalja az én lelkem az Urat,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 47, 'És örvendez az én lelkem az én megtartó Istenemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 48, 'Mert reá tekintett az ő szolgáló leányának alázatos állapotjára; mert ímé mostantól fogva boldognak mondanak engem minden nemzetségek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 49, 'Mert nagy dolgokat cselekedék velem a Hatalmas; és szent az ő neve!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 50, 'És az ő irgalmassága nemzetségről nemzetségre vagyon azokon, a kik őt félik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 51, 'Hatalmas dolgot cselekedék karjának ereje által, elszéleszté az ő szívök gondolatában felfuvalkodottakat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 52, 'Hatalmasokat dönte le trónjaikról, és alázatosakat magasztalt fel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 53, 'Éhezőket töltött be javakkal, és gazdagokat küldött el üresen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 54, 'Felvevé Izráelnek, az ő szolgájának ügyét, hogy megemlékezzék az ő irgalmasságáról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 55, '(A miképen szólott volt a mi atyáinknak), Ábrahám iránt és az ő magva iránt mindörökké!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 56, 'Marada pedig Mária Erzsébettel mintegy három hónapig; azután haza tére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 57, 'Erzsébetnek pedig betelék az ő szülésének ideje, és szűle fiat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 58, 'És meghallák az ő szomszédai és rokonai, hogy az Úr nagy kegyelmességet cselekedett ő vele; és együtt örülének vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 59, 'És lőn nyolczad napon, eljövének, hogy körülmetéljék a gyermeket; és az ő atyja nevéről Zakariásnak akarák őt nevezni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 60, 'És felelvén az ő anyja, monda: Nem; hanem Jánosnak neveztessék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 61, 'És mondának néki: Senki sincs a te rokonságodban, a ki ezen a néven neveztetnék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 62, 'És intének az ő atyjának, hogy minek akarja neveztetni?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 63, 'Az pedig táblát kérvén, ezt írá, mondván: János a neve. És elcsodálkozának mindnyájan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 64, 'És feloldódék az ő szája és nyelve azonnal, és szóla, áldván az Istent.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 65, 'És félelem szállott minden ő szomszédaikra; és Júdeának egész hegyes tartományában elhirdettetének mind e dolgok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 66, 'És szívökre vevék mindenek, a kik hallák, mondván: Vajjon mi lesz e gyermekből? És az Úrnak keze vala ő vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 67, 'És Zakariás, az ő atyja beteljesedék Szent Lélekkel, és prófétála mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 68, 'Áldott az Úr, Izráel Istene, hogy meglátogatta és megváltotta az ő népét,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 69, 'És felemelte az üdvösségnek szarvát nékünk az ő gyermekének, Dávidnak házában,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 70, 'A mint szólott az ő szent prófétáinak szája által, kik eleitől fogva voltak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 71, 'Hogy a mi ellenségeinktől megszabadít, és mindazoknak kezéből, a kik minket gyűlölnek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 72, 'Hogy irgalmasságot cselekedjék a mi atyáinkkal, és megemlékezzék az ő szent szövetségéről,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 73, 'Az esküvésről, a melylyel megesküdt Ábrahámnak, a mi atyánknak, hogy ő megadja nékünk,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 74, 'Hogy megszabadulván a mi ellenségeink kezéből, félelem nélkül szolgáljunk néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 75, 'Szentségben és igazságban ő előtte a mi életünknek minden napjaiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 76, 'Te pedig kis gyermek, a magasságos Isten prófétájának hivattatol; mert az Úr előtt jársz, hogy az ő útait megkészítsed;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 77, 'És az üdvösség ismeretére megtanítsad az ő népét, a bűnöknek bocsánatjában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 78, 'A mi Istenünk nagy irgalmasságáért, a melylyel meglátogatott minket a naptámadat a magasságból,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 79, 'Hogy megjelenjék azoknak, a kik a sötétségben és a halálnak árnyékában ülnek; hogy igazgassa a mi lábainkat a békességnek útjára!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 80, 'A kis gyermek pedig nevekedik és erősödik vala lélekben; és a pusztában vala mind ama napig, a melyen megmutatta magát az Izráelnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'És lőn azokban a napokban, Augusztus császártól parancsolat adaték ki, hogy mind az egész föld összeirattassék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, 'Ez az összeírás először akkor történt, mikor Siriában Czirénius volt a helytartó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'Mennek vala azért mindenek, hogy beirattassanak, kiki a maga városába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'Felméne pedig József is Galileából, Názáret városából Júdeába, a Dávid városába, mely Bethlehemnek neveztetik, mivelhogy a Dávid házából és háznépe közül való volt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'Hogy beirattassék Máriával, a ki néki jegyeztetett feleségül, és várandós vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'És lőn, hogy mikor ott valának, betelének az ő szülésének napjai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'És szülé az ő elsőszülött fiát; és bepólyálá őt, és helyhezteté őt a jászolba, mivelhogy nem vala nékik helyök a vendégfogadó háznál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'Valának pedig pásztorok azon a vidéken, a kik künn a mezőn tanyáztak és vigyáztak éjszakán az ő nyájok mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'És ímé az Úrnak angyala hozzájok jöve, és az Úrnak dicsősége körülvevé őket: és nagy félelemmel megfélemlének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'És monda az angyal nékik: Ne féljetek, mert ímé hirdetek néktek nagy örömet, mely az egész népnek öröme lészen:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'Mert született néktek ma a Megtartó, ki az Úr Krisztus, a Dávid városában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'Ez pedig néktek a jele: találtok egy kis gyermeket bepólyálva feküdni a jászolban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'És hirtelenséggel jelenék az angyallal mennyei seregek sokasága, a kik az Istent dícsérik és ezt mondják vala:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, 'Dicsőség a magasságos mennyekben az Istennek, és e földön békesség, és az emberekhez jó akarat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, 'És lőn, hogy mikor elmentek az angyalok ő tőlök a mennybe, mondának a pásztoremberek egymásnak: Menjünk el mind Bethlehemig, és lássuk meg e dolgot, a melyet az Úr megjelentett nékünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, 'Elmenének azért sietséggel, és megtalálák Máriát és Józsefet, és a kis gyermeket, ki a jászolban fekszik vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, 'És ezt látván, elhirdeték, a mi nékik a gyermek felől mondatott vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, 'És mindenek, a kik hallák, elcsodálkozának azokon, a miket a pásztorok nékik mondottak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, 'Mária pedig mind ez ígéket megtartja, és szívében forgatja vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, 'A pásztorok pedig visszatérének, dicsőítvén és dícsérvén az Istent mind azok felől, a miket hallottak és láttak, a mint nékik megmondatott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, 'És mikor betölt a nyolcz nap, hogy a kis gyermeket körülmetéljék, nevezék az ő nevét Jézusnak, a mint őt az angyal nevezte, mielőtt fogantatott volna anyja méhében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, 'Mikor pedig betöltek Mária tisztulásának napjai a Mózes törvénye szerint, felvivék őt Jeruzsálembe, hogy bemutassák az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, '(A mint megiratott az Úr törvényében, hogy: Minden elsőszülött fiú az Úrnak szenteltessék),');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 24, 'És hogy áldozatot adjanak, a szerint a mint megmondatott az Úr törvényében: Egy pár gerliczét, vagy két galambfiat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 25, 'És ímé vala Jeruzsálemben egy ember, a kinek neve Simeon volt, és ez az ember igaz és istenfélő vala, a ki várta az Izráel vigasztalását, és a Szent Lélek vala ő rajta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 26, 'És kijelentetett néki a Szent Lélek által, hogy addig halált nem lát, a míg meg nem látja az Úrnak Krisztusát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 27, 'És ő a Lélek indításából a templomba méne, és mikor a gyermek Jézust bevivék szülői, hogy ő érette a törvény szokása szerint cselekedjenek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 28, 'Akkor ő karjaiba vevé őt, és áldá az Istent, és monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 29, 'Mostan bocsátod el, Uram, a te szolgádat, a te beszéded szerint, békességben:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 30, 'Mert látták az én szemeim a te üdvösségedet,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 31, 'A melyet készítettél minden népeknek szeme láttára;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 32, 'Világosságul a pogányok megvilágosítására, és a te népednek, az Izráelnek dicsőségére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 33, 'József pedig és az ő anyja csodálkozának azokon, a miket ő felőle mondottak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 34, 'És megáldá őket Simeon, és monda Máriának, az ő anyjának: Ímé ez vettetett sokaknak elestére és feltámadására az Izráelben; és jegyül, a kinek sokan ellene mondanak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 35, 'Sőt a te lelkedet is általhatja az éles tőr; hogy sok szív gondolatai nyilvánvalókká legyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 36, 'És vala egy prófétaasszony, Anna, a Fánuel leánya, az Áser nemzetségéből (ez sok időt élt, miután az ő szűzességétől fogva hét esztendeig élt férjével,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 37, 'És ez mintegy nyolczvannégy esztendős özvegy vala), a ki nem távozék el a templomból, hanem bőjtölésekkel és imádkozásokkal szolgál vala éjjel és nappal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 38, 'Ez is ugyanazon órában oda állván, hálát adott az Úrnak, és szóla ő felőle mindeneknek, a kik Jeruzsálemben a váltságot várták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 39, 'És mikor mindent elvégeztek az Úr törvénye szerint, visszatérének Galileába, az ő városukba, Názáretbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 40, 'A kis gyermek pedig növekedék, és erősödék lélekben, teljesedve bölcsességgel; és az Istennek kegyelme vala ő rajta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 41, 'Az ő szülei pedig évenként feljártak Jeruzsálembe a húsvét ünnepére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 42, 'És mikor tizenkét esztendős lett, fölmenének Jeruzsálembe az ünnep szokása szerint;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 43, 'És mikor eltelének a napok, mikor ők visszatérének, a gyermek Jézus visszamarada Jeruzsálemben; és nem vevék észre sem József, sem az ő anyja;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 44, 'Hanem azt gondolván, hogy az úti társaságban van, egy napi járó földet menének, és keresék őt a rokonok és az ismerősök között;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 45, 'És mikor nem találák őt, visszamenének Jeruzsálembe, hogy megkeressék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 46, 'És lőn, hogy harmadnapra megtalálták őt a templomban, a doktorok között ülve, a mint őket hallgatta, és kérdezgette őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 47, 'És mindnyájan, a kik őt hallgatták, elálmélkodának az ő értelmén és az ő feleletein.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 48, 'És meglátván őt, elcsodálkozának, és monda néki az ő anyja: Fiam, miért cselekedted ezt velünk? Ímé atyád és én nagy bánattal kerestünk téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 49, 'Ő pedig monda nékik: Mi dolog, hogy engem kerestetek? Avagy nem tudjátok-é, hogy nékem azokban kell foglalatosnak lennem, a melyek az én Atyámnak dolgai?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 50, 'De ők nem érték e beszédet, a mit ő nékik szóla.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 51, 'És aláméne velök, és méne Názáretbe; és engedelmes vala nékik. És az ő anyja szívében tartá mind ezeket a dolgokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 52, 'Jézus pedig gyarapodék bölcsességben és testének állapotjában, és az Isten és emberek előtt való kedvességben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'Tibérius császár uralkodásának tizenötödik esztendejében pedig, mikor Júdeában Ponczius Pilátus volt a helytartó, és Galileának negyedes fejedelme Heródes, Iturea és Trakhónitis tartományának pedig negyedes fejedelme az ő testvére Filep, Abiléné negyedes fejedelme meg Lisániás,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, 'Annás és Kajafás főpapsága alatt, lőn az Úrnak szava Jánoshoz, a Zakariás fiához, a pusztában,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'És méne a Jordán mellett lévő minden tartományba prédikálván a megtérés keresztségét a bűnöknek bocsánatjára;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, 'A mint meg van írva Ésaiás próféta beszédeinek könyvében, ki ezt mondja: Kiáltónak szava a pusztában: Készítsétek meg az Úrnak útját, egyengessétek az ő ösvényeit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, 'Minden völgy betöltetik, minden hegy és halom megalacsonyíttatik; és az egyenetlenek egyenesekké, és a göröngyös útak símákká lesznek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, 'És meglátja minden test az Istennek szabadítását.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'Monda azért a sokaságnak, a mely kiméne hozzá, hogy általa megkereszteltessék: Viperák fajzati, kicsoda intett meg titeket, hogy a bekövetkező harag elől meneküljetek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'Teremjetek azért megtéréshez méltó gyümölcsöket, és ne mondogassátok magatokban: Ábrahám a mi atyánk! mert mondom néktek, hogy az Isten ezekből a kövekből is támaszthat fiakat Ábrahámnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, 'Immár pedig a fejsze is rávettetett a fák gyökerére: minden fa azért, a mely jó gyümölcsöt nem terem, kivágattatik és a tűzre vettetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, 'És megkérdé őt a sokaság, mondván: Mit cselekedjünk tehát?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, 'Ő pedig felelvén, monda nékik: A kinek két köntöse van, egyiket adja annak, a kinek nincs; és a kinek van eledele, hasonlókép cselekedjék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, 'És eljövének a vámszedők is, hogy megkeresztelkedjenek, és mondának néki: Mester, mit cselekedjünk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, 'Ő pedig monda nékik: Semmi többet ne követeljetek, mint a mi előtökbe rendeltetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, 'És megkérdék őt a vitézek is, mondván: Hát mi mit cselekedjünk? És monda nékik: Senkit se háborítsatok, se ne patvarkodjatok; és elégedjetek meg zsoldotokkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, 'Mikor pedig a nép várt és szívökben mind azon gondolkoztak János felől, hogy vajjon nem ő-é a Krisztus;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'Felele János mindeneknek, mondván: Én ugyan keresztellek titeket vízzel; de eljő, a ki nálamnál erősebb, a kinek nem vagyok méltó, hogy sarujának kötőjét megoldjam: az majd keresztel titeket Szent Lélekkel és tűzzel:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, 'Kinek szórólapátja kezében van, és megtisztítja szérűjét; és a gabonát az ő csűrébe takarja, a polyvát pedig megégeti olthatatlan tűzzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, 'És még sok egyebekre is intvén őket, hirdeté az evangyéliomot a népnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, 'Mikor pedig Heródes, a negyedes fejedelem, megfeddetett ő tőle Heródiásért, az ő testvérének, Filepnek feleségéért és mindama gonoszságokért, a miket Heródes cselekedett,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, 'Ez még azzal tetézte mindezeket, hogy Jánost tömlöczbe vetteté.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, 'Lőn pedig, hogy mikor az egész nép megkeresztelkedett, és Jézus is megkereszteltetett, és imádkozott, megnyilatkozék az ég,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 22, 'És leszálla ő reá a Szent Lélek testi ábrázatban mint egy galamb, és szózat lőn mennyből, ezt mondván: Te vagy amaz én szerelmes Fiam, te benned gyönyörködöm!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 23, 'Maga Jézus pedig mintegy harmincz esztendős volt, mikor tanítani kezdett, ki, a mint állítják vala, a József fia vala, ez pedig a Hélié,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 24, 'Ez Mattáté, ez Lévié, ez Melkié, ez Jannáé, ez Józsefé,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 25, 'Ez Matthatiásé, ez Ámosé, ez Naumé, ez Eslié, ez Naggaié,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 26, 'Ez Maáté, ez Matthatiásé, ez Sémeié, ez Józsefé, ez Júdáé,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 27, 'Ez Joannáé, ez Rhésáé, ez Zorobábelé, ez Saláthielé, ez Nérié,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 28, 'Ez Melkié, ez Addié, ez Hosámé, ez Elmodámé, ez Éré,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 29, 'Ez Jóséé, ez Eliézeré, ez Jórimé, ez Mattáté, ez Lévié,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 30, 'Ez Simeoné, ez Júdáé, ez Józsefé, ez Jónáné, ez Eliákimé,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 31, 'Ez Méleáé, ez Maináné, ez Mattátáé, ez Nátáné, ez Dávidé,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 32, 'Ez Jesséé, ez Obedé, ez Boázé, ez Sálmoné, ez Naássoné,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 33, 'Ez Aminádábé, ez Arámé, ez Esroné, ez Fáresé, ez Júdáé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 34, 'Ez Jákóbé, ez Izsáké, ez Ábrahámé, ez Táréé, ez Nákhoré,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 35, 'Ez Sárukhé, ez Ragávé, ez Fáleké, ez Eberé, ez Saláé,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 36, 'Ez Kajnáné, ez Arfaksádé, ez Semé, ez Noéé, ez Lámekhé,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 37, 'Ez Mathuséláé, ez Énókhé, ez Járedé, ez Mahalaléelé, ez Kajnáné,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 38, 'Ez Énósé, ez Sethé, ez Ádámé, ez pedig az Istené.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 1, 'Jézus pedig Szent Lélekkel telve, visszatére a Jordántól, és viteték a Lélektől a pusztába');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 2, 'Negyven napig, kísértetvén az ördög által. És nem evék semmit azokban a napokban; de mikor azok elmúltak, végre megéhezék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 3, 'És monda néki az ördög. Ha Isten Fia vagy, mondd e kőnek, hogy változzék kenyérré.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 4, 'Jézus pedig felele néki, mondván: Meg van írva, hogy nemcsak kenyérrel él az ember, hanem az Istennek minden ígéjével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 5, 'Majd felvivén őt az ördög egy nagy magas hegyre, megmutatá néki e föld minden országait egy szempillantásban,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 6, 'És monda néki az ördög: Néked adom mindezt a hatalmat és ezeknek dicsőségét; mert nékem adatott, és annak adom, a kinek akarom;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 7, 'Azért ha te engem imádsz, mindez a tied lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 8, 'Felelvén pedig Jézus, monda néki: Távozz tőlem, Sátán; mert meg van írva: Az Urat, a te Istenedet imádd, és csak néki szolgálj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 9, 'Azután Jeruzsálembe vivé őt, és a templom ormára állítván, monda néki: Ha Isten Fia vagy, vesd alá magad innét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 10, 'Mert meg van írva: Az ő angyalinak parancsol te felőled, hogy megőrizzenek téged;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 11, 'És: Kezökben hordoznak téged, hogy valamikép meg ne üssed lábadat a kőbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 12, 'Felelvén pedig Jézus, monda néki: Megmondatott: Ne kísértsd az Urat, a te Istenedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 13, 'És elvégezvén minden kísértést az ördög, eltávozék tőle egy időre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 14, 'Jézus pedig megtére a Léleknek erejével Galileába: és híre méne néki az egész környéken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 15, 'És ő taníta azoknak zsinagógáiban, dicsőíttetvén mindenektől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 16, 'És méne Názáretbe, a hol felneveltetett: és beméne, szokása szerint, szombatnapon a zsinagógába, és felálla olvasni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 17, 'És adák néki az Ésaiás próféta könyvét; és a könyvet feltárván, arra a helyre nyita, a hol ez vala írva:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 18, 'Az Úrnak lelke van én rajtam, mivelhogy felkent engem, hogy a szegényeknek az evangyéliomot hirdessem, elküldött, hogy a töredelmes szívűeket meggyógyítsam, hogy a foglyoknak szabadulást hirdessek és a vakok szemeinek megnyilását, hogy szabadon bocsássam a lesujtottakat,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 19, 'Hogy hirdessem az Úrnak kedves esztendejét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 20, 'És behajtván a könyvet, átadá a szolgának, és leüle. És a zsinagógában mindenek szemei ő reá valának függesztve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 21, 'Ő pedig kezde hozzájuk szólani: Ma teljesedett be ez az Írás a ti hallástokra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 22, 'És mindnyájan bizonyságot tőnek felőle, és elálmélkodának kedves beszédein, a melyek szájából származtak, és mondának: Avagy nem a József fia-é ez?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 23, 'És monda nékik: Bizonyára azt a példabeszédet mondjátok nékem: Orvos, gyógyítsd meg magadat! A miket hallottunk, hogy Kapernaumban történtek, itt a te hazádban is cselekedd meg azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 24, 'Monda pedig: Bizony mondom néktek: Egy próféta sem kedves az ő hazájában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 25, 'És igazán mondom néktek, hogy Illés idejében sok özvegy asszony volt Izráelben, mikor az ég három esztendeig és hat hónapig be volt zárva, úgy hogy az egész tartományban nagy éhség volt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 26, 'Mégis azok közül senkihez nem küldetett Illés, hanem csak Sidonnak Sareptájába az özvegy asszonyhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 27, 'És az Elizeus próféta idejében sok bélpoklos volt Izráelben; de azok közül egy sem tisztult meg, csak a Siriából való Naámán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 28, 'És betelének mindnyájan haraggal a zsinagógában, mikor ezeket hallották.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 29, 'És felkelvén, kiűzék őt a városon kívül és vivék őt annak a hegynek szélére, a melyen az ő városuk épült, hogy onnan letaszítsák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 30, 'Ő azonban közöttük átmenve, eltávozék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 31, 'És leméne Kapernaumba, Galilea városába; és tanítja vala azokat szombatnapokon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 32, 'És csodálkozának az ő tudományán, mert beszéde hatalmas vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 33, 'És a zsinagógában vala egy tisztátalan ördögi lélektől megszállt ember, a ki fennhangon kiálta,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 34, 'Mondván: Ah, mi közünk hozzád názáreti Jézus? Jöttél, hogy elveszíts minket? Ismerlek téged ki vagy: az Istennek ama Szentje!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 35, 'És megdorgálá őt Jézus, mondván: Némulj meg és menj ki ez emberből! És az ördög azt a középre vetvén, kiméne belőle, és nem árta néki semmit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 36, 'És támada félelem mindenekben, és egymással szólnak és beszélnek vala, mondván: Mi dolog ez, hogy nagy méltósággal és hatalommal parancsol a tisztátalan lelkeknek és kimennek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 37, 'És elterjede a hír ő felőle a környék minden helyén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 38, 'Azután a zsinagógából eltávozván, a Simon házába méne. A Simon napa pedig nagy hideglelésben feküdt, és könyörögtek neki érette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 39, 'És Jézus mellé állván, megdorgálá a hideglelést, és az elhagyá őt; és ő azonnal felkelvén, szolgála nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 40, 'A nap lementével pedig, mindenek, a kiknek különféle betegeik valának, ő hozzá vivék azokat; ő pedig mindegyikőjükre reávetvén kezeit, meggyógyítá őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 41, 'Sokakból pedig ördögök is mentek ki, kiáltozván és mondván: Te vagy ama Krisztus, az Isten Fia! De ő megdorgálván, nem engedé őket szólani, mivelhogy tudták, hogy ő a Krisztus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 42, 'A nap fölkeltekor pedig kimenvén, puszta helyre méne; de a sokaság felkeresé őt, és hozzámenének, és tartóztaták őt, hogy ne menjen el tőlök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 43, 'Ő pedig monda nékik: Egyéb városoknak is hirdetnem kell nékem az Istennek országát; mert azért küldettem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 44, 'És prédikál vala Galilea zsinagógáiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 1, 'És lőn, hogy mikor a sokaság hozzá tódult, hogy hallgassa az Isten beszédét, ő a Genezáret tavánál áll vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 2, 'És láta két hajót állani a vizen: a halászok pedig, miután azokból kiszállottak, mossák vala az ő hálóikat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 3, 'És ő bemenvén az egyik hajóba, a mely a Simoné vala, kéré őt, hogy vigye egy kissé beljebb a földtől: és mikor leült, a hajóból tanítá a sokaságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, 'Mikor pedig megszünt beszélni, monda Simonnak: Evezz a mélyre, és vessétek ki hálóitokat fogásra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, 'És felelvén Simon, monda néki: Mester, jóllehet az egész éjszaka fáradtunk, még sem fogtunk semmit: mindazáltal a te parancsolatodra levetem a hálót.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, 'És ezt megtévén, halaknak nagy sokaságát keríték be; szakadoz vala pedig az ő hálójuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, 'Intének azért társaiknak, a kik a másik hajóban valának, hogy jőjjenek és segítsenek nékik. És eljövén, megtölték mind a két hajót, annyira, hogy csaknem elsülyedének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, 'Látván pedig ezt Simon Péter, Jézusnak lábai elé esék, mondván: Eredj el én tőlem, mert én bűnös ember vagyok, Uram!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, 'Mert félelem fogta körül őt és mindazokat, a kik ő vele valának, a halfogás miatt, a melyet fogtak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, 'Hasonlóképen Jakabot és Jánost is, a Zebedeus fiait, a kik Simonnak társai valának. És monda Simonnak Jézus: Ne félj; mostantól fogva embereket fogsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, 'És a hajókat a szárazra vonván, elhagyák mindenöket és követék őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, 'És lőn, hogy mikor az egyik városban vala, ímé vala ott egy poklossággal teljes ember: és mikor meglátta Jézust, arczra borulva kéré őt, mondván: Uram, ha akarod, megtisztíthatsz engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, 'Jézus pedig kinyújtván kezét, illeté azt, mondván: Akarom, tisztulj meg. És azonnal eltávozék tőle a bélpoklosság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, 'És ő megparancsolá néki, hogy azt senkinek se mondja el; hanem eredj el, úgymond, mutasd meg magad a papnak, és vígy áldozatot a te megtisztulásodért, a mint Mózes parancsolta, bizonyságul ő nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, 'A hír azonban annál inkább terjedt ő felőle; és nagy sokaság gyűle egybe, hogy őt hallgassák, és hogy általa meggyógyuljanak az ő betegségeikből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, 'De ő félrevonula a pusztákba, és imádkozék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, 'És lőn egy napon, hogy ő tanít vala: és ott ülének a farizeusok és a törvénynek tanítói, a kik jöttek Galileának és Júdeának minden faluiból és Jeruzsálemből: és az Úrnak hatalma vala ő vele, hogy gyógyítson.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, 'És ímé valami férfiak ágyon egy embert hozának, a ki gutaütött vala; és igyekezének azt bevinni és ő elébe tenni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, 'De nem találván módot, hogy a sokaság miatt mikép vigyék őt be, felhágának a háztetőre, és a cseréphéjazaton át bocsáták őt alá ágyastól Jézus elé a középre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, 'És látván azoknak hitét, monda: Ember, megbocsáttattak néked a te bűneid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, 'Az írástudók pedig és a farizeusok elkezdének tanakodni, mondván: Kicsoda ez, a ki ily káromlást szól? Ki bocsáthatja meg a bűnt, hanemha egyedül az Isten?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, 'Jézus pedig észrevévén az ő tanakodásukat, felelvén, monda nékik: Mit tanakodtok a ti szívetekben?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, 'Melyik könnyebb, azt mondani: Megbocsáttattak néked a te bűneid; vagy azt mondani: Kelj fel és járj?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, 'Hogy pedig megtudjátok, hogy az ember Fiának van hatalma e földön megbocsátani a bűnöket, (monda a gutaütöttnek): Néked mondom, kelj fel, és fölvévén nyoszolyádat, eredj haza!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, 'És az rögtön felkelvén azok szemeláttára, fölvevé a min feküdt, és elméne haza, dicsőítvén az Istent.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, 'És az álmélkodás elfogá mindnyájukat, és dicsőíték az Istent, és betelének félelemmel, mondván: Bizony csodadolgokat láttunk ma!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, 'Ezek után pedig kiméne, és láta egy Lévi nevű vámszedőt, a ki a vámnál ül vala, és monda néki: Kövess engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, 'És az mindeneket elhagyván, felkele és követé őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 29, 'És Lévi nagy lakomát készíte néki az ő házánál; és vala ott nagy sokasága a vámszedőknek és egyebeknek, a kik ő velök letelepedtek volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 30, 'És köztük az írástudók és farizeusok zúgolódának az ő tanítványai ellen, mondván: Miért esztek és isztok a vámszedőkkel és a bűnösökkel?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 31, 'És felelvén Jézus, monda nékik: Az egészségeseknek nincs szükségük orvosra, hanem a betegeknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 32, 'Nem azért jöttem, hogy az igazakat hívjam, hanem a bűnösöket a megtérésre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 33, 'Azok pedig mondának néki: Mi az oka, hogy a János tanítványai gyakorta bőjtölnek és imádkoznak, valamint a farizeusokéi is; a te tanítványaid pedig esznek és isznak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 34, 'Ő pedig monda nékik: Avagy mívelhetitek-é azt, hogy a lakodalmasok bőjtöljenek, a míg a vőlegény velök van?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 35, 'De eljőnek a napok, és mikor a vőlegény elvétetik ő tőlök, akkor majd bőjtölnek azokban a napokban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 36, 'És monda nékik példabeszédet is: Senki nem toldja az új posztó foltot az ó posztóhoz; mert különben az újat is megszakasztja és az ó posztóhoz nem illik az újból való folt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 37, 'És senki sem tölti az új bort ó tömlőkbe; mert különben az új bor megszakasztja a tömlőket, és a bor kiömöl, és a tömlők is elvesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 38, 'Hanem az új bort új tömlőkbe kell tölteni, és mind a kettő megmarad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 39, 'És senki, a ki ó bort iszik, mindjárt újat nem kiván, mert azt mondja: Jobb az ó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 1, 'Lőn pedig a húsvét szombatját követő második szombaton, hogy a vetések között méne által és az ő tanítványai gabonafejeket szaggatván és azokat kezeikkel kimorzsolván, ettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 2, 'Némelyek pedig a farizeusok közül mondának nékik: Miért cselekszitek azt, a mit szombatnapokon nem szabad cselekedni?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 3, 'És felelvén Jézus, monda nékik: Nem olvastátok-é, mit cselekedett Dávid, mikor megéhezett ő és a kik vele voltak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 4, 'Mi módon ment be az Úrnak házába és vette el a szent kenyereket és ette meg és adott azoknak is, a kik vele voltak, a melyeket pedig nem szabad megenni, hanem csak a papoknak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 5, 'És monda nékik: Az embernek Fia ura a szombatnak is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 6, 'Lőn pedig más szombaton is, hogy ő a zsinagógába méne és taníta, és vala ott egy ember, a kinek a jobb keze száradt volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 7, 'Az írástudók és farizeusok pedig leselkedének ő utána, ha vajjon gyógyít-e majd szombatnapon, hogy vádat találjanak ellene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 8, 'Ő pedig tudván azoknak gondolatait, monda a száradt kezű embernek: Kelj fel és állj elő! És felkelvén, előálla.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 9, 'Monda azért nékik Jézus: Valamit kérdek tőletek: Szabad-é szombaton jót tenni, vagy rosszat tenni? az életet megtartani, vagy elveszteni?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 10, 'És körültekintve mindnyájokon, monda az embernek: Nyújtsd ki a kezedet! Az pedig úgy cselekedék, és keze oly éppé lőn, mint a másik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 11, 'Azok pedig eltelének esztelenséggel és beszélgetnek vala egymás közt, hogy mit cselekedjenek Jézussal?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 12, 'És lőn azokban a napokban, kiméne a hegyre imádkozni, és az éjszakát az Istenhez való imádkozásban tölté el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 13, 'És mikor megvirrada, előszólítá az ő tanítványait és kiválaszta azok közül tizenkettőt, a kiket apostoloknak is neveze:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 14, 'Simont, a kit Péternek is neveze, és Andrást, annak testvérét, Jakabot és Jánost, Filepet és Bertalant,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 15, 'Mátét és Tamást, Jakabot, az Alfeus fiát, és Simont, a ki Zelotesnek nevezteték,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 16, 'Júdást, a Jakab fiát és Iskariotes Júdást, a ki árulóvá is lőn;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 17, 'És alámenvén ő velök, megálla a síkságon, és az ő tanítványainak serege és a népnek nagy sokasága egész Júdeából és Jeruzsálemből és Tírusnak és Sídonnak tengermelléki határából, a kik jöttek, hogy hallgassák őt és meggyógyíttassanak betegségeikből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 18, 'És a kik tisztátalan lelkektől gyötrettek, meggyógyulának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 19, 'És az egész sokaság igyekezik vala őt illetni: mert erő származék belőle, és mindeneket meggyógyíta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 20, 'Ő pedig felemelvén szemeit az ő tanítványaira, monda: Boldogok vagytok ti szegények: mert tiétek az Isten országa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 21, 'Boldogok ti, kik most éheztek: mert megelégíttettek. Boldogok ti, kik most sírtok: mert nevetni fogtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 22, 'Boldogok lesztek, mikor titeket az emberek gyűlölnek, és kirekesztenek, és szidalmaznak titeket, és kivetik a ti neveteket, mint gonoszt, az embernek Fiáért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 23, 'Örüljetek azon a napon és örvendezzetek; mert ímé a ti jutalmatok bőséges a mennyben; hiszen hasonlóképen cselekedtek a prófétákkal az ő atyáik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 24, 'De jaj néktek, gazdagoknak, mert elvettétek a ti vigasztalástokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 25, 'Jaj néktek, kik beteltetek; mert éhezni fogtok. Jaj néktek, kik most nevettek; mert sírni és jajgatni fogtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 26, 'Jaj néktek, mikor minden ember jót mond felőletek; mert épen így cselekedtek a hamis prófétákkal az ő atyáik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 27, 'De néktek mondom, kik engem hallgattok: Szeressétek ellenségeiteket, jól tegyetek azokkal, a kik titeket gyűlölnek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 28, 'Áldjátok azokat, a kik titeket átkoznak, és imádkozzatok azokért, a kik titeket háborgatnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 29, 'A ki egyik arczodat megüti, fordítsd néki a másikat is; és attól, a ki felső ruhádat elveszi, ne vond meg alsó ruhádat se.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 30, 'Mindennek pedig, a ki tőled kér, adj; és attól, a ki elveszi a tiédet, ne kérd vissza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 31, 'És a mint akarjátok, hogy az emberek veletek cselekedjenek, ti is akképen cselekedjetek azokkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 32, 'Mert ha csak azokat szeretitek, a kik titeket szeretnek, mi jutalmatok van? Hiszen a bűnösök is szeretik azokat, a kik őket szeretik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 33, 'És ha csak azokkal tesztek jól, a kik veletek jól tesznek, mi jutalmatok van? Hiszen a bűnösök is ugyanazt cselekszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 34, 'És ha csak azoknak adtok kölcsönt, a kiktől reménylitek, hogy visszakapjátok, mi jutalmatok van? Hiszen a bűnösök is adnak kölcsönt a bűnösöknek, hogy ugyanannyit kapjanak vissza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 35, 'Hanem szeressétek ellenségeiteket, és jól tegyetek, és adjatok kölcsönt, semmit érte nem várván; és a ti jutalmatok sok lesz, és ama magasságos Istennek fiai lesztek: mert ő jóltévő a háládatlanokkal és gonoszokkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 36, 'Legyetek azért irgalmasok, mint a ti Atyátok is irgalmas.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 37, 'Ne ítéljetek és nem ítéltettek; ne kárhoztassatok és nem kárhoztattok; megbocsássatok, néktek is megbocsáttatik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 38, 'Adjatok, néktek is adatik; jó mértéket, megnyomottat és megrázottat, színig teltet adnak a ti öletekbe. Mert azzal a mértékkel mérnek néktek, a melylyel ti mértek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 39, 'Példabeszédet is monda nékik: Vajjon a vak vezetheti-é a világtalant? avagy nem mindketten a verembe esnek-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 40, 'Nem feljebb való a tanítvány az ő mesterénél; hanem mikor tökéletes lesz, mindenki olyan lesz, mint a mestere.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 41, 'Miért nézed pedig a szálkát, a mely a te atyádfia szemében van, a gerendát pedig, mely a te saját szemedben van, nem veszed észre?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 42, 'Avagy mi módon mondhatod a te atyádfiának: Atyámfia, hadd vessem ki a szálkát a te szemedből, holott te a te szemedben lévő gerendát nem látod. Te képmutató, vesd ki először a gerendát a te szemedből és azután gondolj arra, hogy kivesd a szálkát, a mely a te atyádfia szemében van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 43, 'Nem jó fa az, a mely romlott gyümölcsöt terem; és nem romlott fa az, a mely jó gyümölcsöt terem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 44, 'Mert minden fa az ő tulajdon gyümölcséről ismertetik meg; mert a tövisről nem szednek fügét, sem a szederindáról nem szednek szőlőt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 45, 'A jó ember az ő szívének jó kincséből hoz elő jót; és a gonosz ember az ő szívének gonosz kincséből hoz elő gonoszt: mert a szívnek teljességéből szól az ő szája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 46, 'Miért mondjátok pedig nékem: Uram! Uram! ha nem mívelitek, a miket mondok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 47, 'Valaki én hozzám jő és hallgatja az én beszédimet és azokat megtartja, megmondom néktek, mihez hasonló.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 48, 'Hasonló valamely házépítő emberhez, a ki leásott és mélyre hatolt, és kősziklára vetett fundamentomot: mikor aztán árvíz lett, beleütközött a folyóvíz abba a házba, de azt meg nem mozdíthatta: mert kősziklán épült.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 49, 'A ki pedig hallgatja, de nem tartja meg, hasonló ahhoz az emberhez, a ki csak a földön építette házát fundamentom nélkül: a melybe beleütközvén a folyóvíz, azonnal összeomlott; és nagy lett annak a háznak romlása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 1, 'Mikor pedig minden ő beszédeit a nép hallatára elvégezte, beméne Kapernaumba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 2, 'Egy századosnak szolgája pedig, a ki annál nagy becsületben volt, igen rosszul lévén, már halófélben vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 3, 'Az pedig, mikor hallott Jézus felől, hozzá küldé a zsidók véneit, kérvén őt, hogy jőjjön el és gyógyítsa meg az ő szolgáját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 4, 'Azok pedig Jézushoz menvén, igen kérék őt, mondván: Méltó, hogy megtedd néki;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 5, 'Mert szereti a mi nemzetünket, és a zsinagógát is ő építtette nékünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 6, 'Jézus tehát elméne velök. Mikor azonban már nem messze volt a háztól, eléje küldé a százados néhány jó barátját, izenvén néki: Uram, ne fáraszd magad; mert nem vagyok méltó, hogy hajlékomba jőjj;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 7, 'A miért is magamat sem tartottam érdemesnek arra, hogy hozzád menjek: hanem csak szóval mondd, és meggyógyul az én szolgám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 8, 'Mert én is hatalom alá vetett ember vagyok, és vitézek vannak alattam; és ha az egyiknek azt mondom: Eredj el, elmegy; vagy a másiknak: Jövel, eljő; és ha szolgámnak szólok: Tedd ezt, azt teszi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 9, 'Jézus pedig ezeket hallván, elcsudálkozék ő rajta; és hátrafordulván monda az őt követő sokaságnak: Mondom néktek, ilyen hitet Izráelben sem találtam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 10, 'És a küldöttek visszatérvén a házhoz, a beteg szolgát már egészségben találák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 11, 'És lőn másnap, hogy méne Nain nevű városba; és az ő tanítványai sokan menének ő vele, és nagy sokaság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 12, 'Mikor pedig a város kapujához közelített, ímé egy halottat hoznak vala ki, egyetlen egy fiát az anyjának, és az özvegy asszony vala; és a városból nagy sokaság volt ő vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 13, 'És látván őt az Úr, megkönyörüle rajta, és monda néki: Ne sírj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 14, 'És oda menvén, illeté a koporsót; a vivők pedig megállának. És monda: Ifjú, néked mondom, kelj föl!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 15, 'És felüle a megholt, és kezde szólni; és adá őt anyjának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 16, 'És elfogá mind azokat a félelem, és dicsőíték az Istent, mondván: Nagy próféta támadt mi köztünk; és: Az Isten megtekintette az ő népét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 17, 'És kiméne ő felőle e hír az egész Júdeába, és a körül való minden tartományba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 18, 'És Jánosnak mind ezeket elmondák a tanítványai. És János az ő tanítványai közül kettőt előszólítván,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 19, 'Elküldé Jézushoz, mondván: Te vagy-é az, a ki eljövendő vala, vagy mást várjunk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 20, 'Mikor azért azok a férfiak hozzámentek, mondának: Keresztelő János küldött minket te hozzád, mondván: Te vagy-é az, a ki eljövendő vala, vagy mást várjunk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 21, 'Azon órában pedig sokakat gyógyíta meg betegségekből, csapásokból, tisztátalan lelkektől, és sok vaknak adá meg szeme világát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 22, 'És felelvén Jézus, monda nékik: Elmenvén mondjátok meg Jánosnak, a miket láttatok és hallottatok: hogy a vakok szemeik világát veszik, a sánták járnak, a poklosok megtisztulnak, a siketek hallanak, a halottak feltámadnak, a szegényeknek az evangyéliom prédikáltatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 23, 'És boldog, valaki én bennem meg nem botránkozik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 24, 'Mikor pedig elmentek a János követei, kezdé mondani a sokaságnak János felől: Mit látni mentetek ki a pusztába? szélingatta nádszálat-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 25, 'Hát mit látni mentetek ki? puha ruhákba öltözött embert-é? Ímé a kik drága öltözetben és gyönyörűségben vannak, a királyok palotáiban vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 26, 'Hát mit látni mentetek ki? Prófétát-é? Bizony mondom néktek, prófétánál is nagyobbat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 27, 'Ez az, a ki felől meg van írva: Ímé én elküldöm az én követemet a te orczád előtt, ki elkészíti előtted a te útadat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 28, 'Mert mondom néktek, hogy azok között, a kik asszonytól születtek, egy sincs nagyobb próféta Keresztelő Jánosnál; de a ki kisebb az Isten országában, nagyobb ő nála.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 29, 'És mikor ezt hallotta az egész nép és a vámszedők, igazat adának az Istennek, megkeresztelkedvén a János keresztségével;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 30, 'A farizeusok pedig és a törvénytudók az Isten tanácsát megveték ő magokra nézve, nem keresztelkedvén meg ő tőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 31, 'Monda pedig az Úr: Mihez hasonlítsam azért e nemzetségnek embereit? és mihez hasonlók?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 32, 'Hasonlók a piaczon ülő gyermekekhez, kik egymásnak kiáltanak, és ezt mondják: Sípoltunk néktek, és nem tánczoltatok; siralmas énekeket énekeltünk néktek, és nem sírtatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 33, 'Mert eljött Keresztelő János, a ki kenyeret sem eszik, bort sem iszik, és ezt mondjátok: Ördög van benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 34, 'Eljött az embernek Fia, a ki eszik és iszik, és ezt mondjátok: Ímé a falánk és borivó ember, a vámszedők és bűnösök barátja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 35, 'És igazoltatik a bölcseség minden ő fiaitól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 36, 'Kéré pedig őt egy a farizeusok közül, hogy ő vele egyék; annakokáért bemenvén a farizeus házába, leüle enni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 37, 'És ímé a városban egy asszony a ki bűnös vala, mikor megtudta, hogy ő a farizeus házában leült enni, hoza egy alabástrom szelencze drága kenetet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 38, 'És megállván hátul az ő lábainál sírva, könnyeivel kezdé öntözni az ő lábait, és fejének hajával törlé meg, és csókolgatá az ő lábait, és megkené drága kenettel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 39, 'Mikor pedig ezt látta a farizeus, a ki őt meghívta, monda magában: Ez, ha próféta volna, tudná ki és miféle asszony az, a ki őt illeti: hogy bűnös.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 40, 'És felelvén Jézus, monda néki: Simon, van valami mondani valóm néked. És az monda: Mester, mondjad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 41, 'Egy hitelezőnek két adósa vala: az egyik adós vala ötszáz pénzzel, a másik pedig ötvennel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 42, 'És mikor nem volt nékik miből megadni, mind a kettőnek elengedé. E kettő közül azért, mondd meg, melyik szereti őt jobban?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 43, 'Felelvén pedig Simon, monda: Azt gondolom, hogy az, a kinek többet engedett el. És Jézus monda néki: Igazán ítéltél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 44, 'És az asszonyhoz fordulván, monda Simonnak: Látod-é ez asszonyt? Bejövék a te házadba, az én lábaimnak vizet nem adál: ez pedig könnyeivel öntözé az én lábaimat, és fejének hajával törlé meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 45, 'Engem meg nem csókolál: ez pedig az időtől fogva, hogy bejöttem, nem szünt meg az én lábaimat csókolgatni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 46, 'Olajjal az én fejemet meg nem kented: ez pedig drága kenettel kené meg az én lábaimat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 47, 'Minekokáért mondom néked: Néki sok bűne bocsáttatott meg; mert igen szeretett; a kinek pedig kevés bocsáttatik meg, kevésbé szeret.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 48, 'És monda annak: Megbocsáttattak néked a te bűneid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 49, 'És a kik együtt ülének vele az asztalnál, kezdék magukban mondani: Ki ez, hogy a bűnöket is megbocsátja?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 50, 'Monda pedig az asszonynak: A te hited megtartott téged. Eredj el békességgel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 1, 'És lőn ezután, hogy ő jár vala városonként és falunként, prédikálván és hirdetvén az Isten országát, és vele a tizenkettő,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 2, 'És némely asszonyok, a kiket tisztátalan lelkektől és betegségekből gyógyított meg, Mária, a ki Magdalénának neveztetik, kiből hét ördög ment ki,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 3, 'És Johanna, Khúzának, a Heródes gondviselőjének felesége, és Zsuzsánna, és sok más asszony, kik az ő vagyonukból szolgálának néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 4, 'Mikor pedig nagy sokaság gyűlt egybe, és minden városból mentek vala ő hozzá, monda példázat által:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 5, 'Kiméne a magvető, hogy elvesse az ő magvát: és magvetés közben némely esék az útfélre; és eltapostaték, és az égi madarak megevék azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 6, 'És némely esék a kősziklára; és mikor kikelt, elszárada, mert nem vala nedvessége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 7, 'Némely esék a tövis közé; és a tövisek vele együtt növekedvén, megfojták azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 8, 'Némely pedig esék a jó földbe; és mikor kikelt, százannyi hasznot hoza. Ezeket mondván, kiált vala: A kinek van füle a hallásra, hallja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 9, 'És megkérdék őt az ő tanítványai, mondván: Mi lehet e példázat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 10, 'Ő pedig monda nékik: Néktek adatott, hogy az Isten országának titkait értsétek; egyebeknek példázatokban, hogy látván ne lássanak, és hallván ne értsenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 11, 'A példázat pedig ez: A mag az Isten beszéde.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 12, 'Az útfélen valók pedig azok, a kik hallják; aztán eljő az ördög, és kikapja az ígét az ő szívökből, hogy ne higyjenek és ne idvezüljenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 13, 'És a kősziklán valók azok, a kik, mikor hallják, örömmel veszik az ígét; de ezeknek nincs gyökerük, a kik egy ideig hisznek, a kísértés idején pedig elszakadnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 14, 'És a melyik a tövis közé esett, ezek azok, a kik hallották, de elmenvén, az élet gondjaitól, és gazdagságától és gyönyörűségeitől megfojtatnak, és gyümölcsöt nem teremnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 15, 'A melyik pedig a jó földbe esett, ezek azok, a kik a hallott ígét tiszta és jó szívvel megtartják, és gyümölcsöt teremnek béketűréssel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 16, 'Senki pedig, ha gyertyát gyújt, be nem fedi azt valami edénynyel, sem az ágy alá nem rejti; hanem a gyertyatartóba teszi, hogy a kik bemennek, lássák a világot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 17, 'Mert nincs oly titok, mely nyilvánvalóvá ne lenne; és nincs oly elrejtett dolog, mely ki ne tudódnék, és világosságra ne jőne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 18, 'Meglássátok azért, mimódon hallgatjátok: mert a kinek van, annak adatik; és a kinek nincs, még a mijét gondolja is hogy van, elvétetik tőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 19, 'Jövének pedig hozzá az ő anyja és atyjafiai, de nem tudtak hozzá jutni a sokaság miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 20, 'És tudtára adák néki, mondván: A te anyád és atyádfiai künn állnak, téged akarván látni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 21, 'Ő pedig felelvén, monda nékik: Az én anyám és az én atyámfiai ezek, a kik az Isten beszédét hallgatják, és megcselekszik azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 22, 'Lőn pedig egy napon, hogy beméne a hajóba ő és az ő tanítványai; és monda nékik: Menjünk a tónak túlsó partjára. És elindulának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 23, 'De hajózásuk közben elszenderedék; és szélvész csapott le a tóra, és megmerülének, és veszedelemben valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 24, 'És hozzá menvén, felkölték őt mondván: Mester, Mester, elveszünk! Ő pedig felserkenvén, megdorgálá a szelet és a víznek habjait; és megszűnének, és lőn csendesség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 25, 'És monda nékik: Hol van a ti hitetek? És félelemmel csodálkoznak vala, mondván egymásnak: Ugyan ki ez, hogy a szeleknek is, a víznek is parancsol, és engednek néki?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 26, 'És evezének a Gaderénusok tartományaiba, mely Galileával átellenben van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 27, 'És mikor ő kiment a földre, jöve elébe a városból egy ember, kiben ördögök voltak sok időtől fogva, sem ruhába nem öltözött, sem házban nem lakott, hanem a sírboltokban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 28, 'És mikor meglátta Jézust, felkiálta és lábai elé esék néki, és fenszóval monda: Mi közöm van nékem te veled, Jézus, felséges Istennek Fia? kérlek téged, ne gyötörj engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 29, 'Mert azt parancsolá annak a tisztátalan léleknek, hogy menjen ki az emberből. Mert gyakran elragadá őt: annakokáért lánczokkal és békókkal megkötözve őrizteték; de a kötelékeket elszaggatván, az ördögtől a pusztákba hajtaték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 30, 'Megkérdé pedig őt Jézus, mondván: Mi a neved? És ő monda: Légió; mert sok ördög ment vala bele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 31, 'És kérék őt, hogy ne parancsolja nékik, hogy a mélységbe menjenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 32, 'Vala pedig ott egy nagy disznónyáj, legelészve a hegyen; és kérék őt, hogy engedje meg nékik, hogy azokba menjenek. És megengedé nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 33, 'És minekutána kimentek az ördögök az emberből, bemenének a disznókba; és a disznónyáj a meredekről a tóba rohana, és megfullada.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 34, 'A pásztorok pedig látván mi történt, elfutának, és elmenvén, hírré adák a városban és a falukban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 35, 'Kimenének azért megnézni mi történt; és menének Jézushoz, és ülve találák az embert, kiből az ördögök kimentek, felöltözve és eszénél, a Jézus lábainál; és megfélemlének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 36, 'Elbeszélék pedig nékik azok is, a kik látták, mimódon szabadult meg az ördöngős.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 37, 'És kéré őt a Gadarénusok körül való tartományok egész sokasága, hogy ő közülök menjen el, mert felette igen félnek vala: ő pedig beülvén a hajóba, visszatére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 38, 'Kéré pedig őt az az ember, a kiből az ördögök kimentek, hogy ő vele lehessen; de Jézus elbocsátá őt, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 39, 'Térj vissza házadhoz, és beszéld el, mely nagy dolgokat tett az Isten veled. Elméne azért, hirdetvén az egész városban, mely nagy dolgokat cselekedett Jézus ő vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 40, 'És lőn, hogy mikor Jézus visszatért, a nép örömmel fogadá őt; mert mindnyájan várják vala őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 41, 'És ímé eljöve egy ember, kinek Jairus vala neve, ki a zsinagógának feje volt; és Jézus lábai előtt leesvén, kéré őt, hogy menjen be az ő házába;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 42, 'Mert vala néki egy egyetlen leánya, mintegy tizenkét esztendős, és az halálán volt. Mikor pedig ő méne, a sokaság szorongatá őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 43, 'És egy asszony, ki vérfolyásban volt tizenkét esztendőtől fogva, és bár minden vagyonát az orvosokra költötte, senki meg nem tudta gyógyítani,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 44, 'Hátulról hozzá járulván, illeté az ő ruhájának peremét; és azonnal elálla vérének folyása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 45, 'És monda Jézus: Ki az, a ki engem illete? És mikor mindnyájan tagadták, monda Péter és a kik ő vele valának: Mester, a sokaság nyom és szorongat téged, és azt mondod: Ki az, a ki engem illete?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 46, 'Jézus pedig monda: Illete engem valaki; mert én észrevettem, hogy erő származék ki tőlem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 47, 'Mikor pedig látta az asszony; hogy nem maradt titokban, reszketve előjöve és előtte leesvén, megjelenté néki az egész sokaság előtt, miért illette őt, és hogy azonnal meggyógyult.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 48, 'És ő monda néki: Bízzál leányom, a te hited megtartott téged; eredj el békességgel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 49, 'Mikor még a szó szájában vala, eljöve egy ember a zsinagóga fejének házától, mondván néki: Meghalt a leányod; ne fáraszd a Mestert!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 50, 'Jézus pedig mikor ezt hallotta, felele néki, mondván: Ne félj; csak higyj, és megtartatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 51, 'Bemenvén pedig a házba, senkit nem bocsáta be, csak Pétert, Jakabot, Jánost és a leányzó atyját és anyját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 52, 'Sírának pedig mindnyájan, és gyászolák azt; ő pedig monda: Ne sírjatok; nem halt meg, hanem aluszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 53, 'És kineveték őt, tudván, hogy meghalt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 54, 'Ő pedig mindenkit kiküldvén, és a leányzó kezét megfogván, kiálta, mondván: Leányzó, kelj fel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 55, 'És visszatére annak lelke, és azonnal fölkele; és ő parancsolá, hogy adjanak néki enni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 56, 'És elálmélkodának annak szülei; ő pedig megparancsolá, hogy senkinek ne mondják, a mi történt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, 'Minekutána pedig összehívta Jézus az ő tizenkét tanítványát, ada nékik erőt és hatalmat minden ördögök ellen, és betegségek gyógyítására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, 'És elküldé őket, hogy prédikálják az Isten országát, és betegeket gyógyítsanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, 'És monda nékik: Semmit az útra ne vigyetek, se pálczákat, se táskát, se kenyeret, se pénzt; se két-két ruhátok ne legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, 'És valamely házba bementek, ott maradjatok, és onnét induljatok tovább.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, 'És valakik be nem fogadnak titeket, kimenvén abból a városból, még a port is verjétek le lábaitokról, bizonyságul ő ellenök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, 'Kimenvén annakokáért, bejárák a falukat, hirdetvén az evangyéliomot, és gyógyítván mindenütt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, 'Meghallá pedig Heródes a negyedes fejedelem, mindazokat, a mik ő általa történtek: és zavarban volt, mivelhogy némelyek azt mondák, hogy János támadt fel a halálból;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 8, 'Némelyek pedig, hogy Illés jelent meg; mások meg, hogy a régi próféták közül támadt fel valamelyik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 9, 'És monda Heródes: Jánosnak én vettem fejét: kicsoda hát ez, a ki felől én ilyen dolgokat hallok? És igyekezik vala őt látni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 10, 'Visszatérvén pedig az apostolok, elbeszélének néki mindent, a mit cselekedtek. És azokat maga mellé vévén, elvonula magánosan a Bethsaida nevű városnak puszta helyére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 11, 'A sokaság pedig ezt megtudván, követé őt: és ő örömmel fogadván őket, szóla nékik az Isten országáról, és a kiknek gyógyulásra volt szükségök, azokat meggyógyítá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 12, 'A nap pedig hanyatlani kezdett; és a tizenkettő ő hozzá járulván, monda néki: Bocsásd el a sokaságot, hogy elmenvén a körülvaló falvakba és majorokba megszálljanak, és eledelt találjanak, mert itt puszta helyen vagyunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 13, 'Ő pedig monda nékik: Adjatok nékik ti enni. Azok pedig mondának: Nincs nékünk több öt kenyerünknél és két halunknál; hanem ha elmegyünk és mi veszünk eledelt az egész sokaságnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 14, 'Mert valának ott mintegy ötezeren férfiak. Monda pedig az ő tanítványainak: Ültessétek le őket csoportokba ötvenével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 15, 'És a képen cselekedének, és leülteték valamennyit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 16, 'Minekutána pedig vette az öt kenyeret és a két halat, a mennybe emelvén szemeit, megáldá azokat, és megszegé; és adá a tanítványoknak, hogy a sokaság elé tegyék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 17, 'Evének azért és megelégedének mindnyájan; és felszedék a mi darabok maradtak tőlük, tizenkét kosárral.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 18, 'És lőn, mikor ő magában imádkozék, vele valának a tanítványok; és megkérdé őket, mondván: Kinek mond engem a sokaság?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 19, 'Ők pedig felelvén, mondának: Keresztelő Jánosnak; némelyek pedig Illésnek; némelyek pedig, hogy a régi próféták közül támadt fel valamelyik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 20, 'És monda nékik: Hát ti kinek mondotok engem? Felelvén pedig Péter, monda: Az Isten ama Krisztusának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 21, 'Ő pedig reájok parancsolván, meghagyá, hogy ezt senkinek ne mondják;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 22, 'Ezt mondván: Szükség az ember Fiának sokat szenvedni és megvettetni a vénektől, a főpapoktól és írástudóktól, és megöletni, és harmadnapon feltámadni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 23, 'Mondja vala pedig mindeneknek: Ha valaki én utánam akar jőni, tagadja meg magát, és vegye fel az ő keresztjét minden nap, és kövessen engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 24, 'Mert a ki meg akarja tartani az ő életét, elveszti azt; a ki pedig elveszti az ő életét én érettem, az megtartja azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 25, 'Mert mit használ az embernek, ha mind e világot megnyeri is, ő magát pedig elveszti vagy magában kárt vall?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 26, 'Mert valaki szégyel engem és az én beszédemet, az embernek Fia is szégyelni fogja azt, mikor eljő az ő dicsőségével, és az Atyáéval és a szent angyalokéval.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, 'Mondom pedig néktek bizonnyal, hogy vannak az itt állók közül némelyek, kik a halált meg nem kóstolják, mígnem meglátják az Istennek országát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, 'És lőn e beszédek után mintegy nyolczadnappal, hogy maga mellé vevé Pétert, Jánost és Jakabot, és felméne a hegyre imádkozni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, 'És imádkozása közben az ő orczájának ábrázata elváltozék, és az ő ruhája fehér és fénylő lőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, 'És ímé két férfiú beszél vala ő vele, kik valának Mózes és Illés;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, 'Kik dicsőségben megjelenvén, beszélik vala az ő halálát, melyet Jeruzsálemben fog megteljesíteni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, 'Pétert pedig és a vele lévőket elnyomá az álom; de mikor felébredtek, láták az ő dicsőségét, és ama két férfiút, kik vele állanak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 33, 'És lőn, mikor azok eltávoztak ő tőle, monda Péter Jézusnak: Mester, jó nékünk itt lennünk: csináljunk azért három hajlékot, egyet néked, Mózesnek is egyet, és egyet Illésnek; nem tudván mit mond.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 34, 'És mikor ő ezeket mondá, felhő támada és azokat beárnyékozá; ők pedig megfélemlének, mikor azok bementek a felhőbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 35, 'És szózat lőn a felhőből, mondván: Ez amaz én szerelmes Fiam, őt hallgassátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 36, 'És mikor a szózat lőn, találtaték Jézus csak maga. Ők pedig hallgatának, és semmit abból, a mit láttak, senkinek el nem mondának azokban a napokban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 37, 'És lőn másnap, mikor ők a hegyről leszállottak, sok nép méne elébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 38, 'És ímé egy a sokaság közül felkiálta, mondván: Mester, kérlek téged, tekints az én fiamra; mert nékem egyetlen egyem:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 39, 'És ímé a lélek megragadja őt, és hirtelen kiált; és szaggatja őt, annyira, hogy tajtékot túr, és nehezen megy el tőle, szaggatván őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 40, 'És kérem a te tanítványaidat, hogy űzzék ki azt, de nem tudták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 41, 'Felelvén pedig Jézus, monda: Óh hitetlen és elfajult nemzetség! meddig leszek köztetek, és meddig tűrlek titeket? Hozd ide a te fiadat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 42, 'A míg pedig az odaméne, azon közben az ördög földhöz üté azt, és megrángatá. De Jézus megdorgálá a tisztátalan lelket, és meggyógyítá a gyermeket, és adá azt az ő atyjának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 43, 'Elálmélkodának pedig mindnyájan az Istennek nagyságos erején. Mikor pedig mindnyájan csodálkozának mind azokon, a miket Jézus cselekedék, monda az ő tanítványainak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 44, 'Vegyétek füleitekbe ezeket a beszédeket: Mert az embernek Fia az emberek kezébe fog adatni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 45, 'De ők nem érték e mondást, és el vala rejtve előlük, hogy ne értsék azt; és féltek őt megkérdezni e mondás felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 46, 'Támada pedig bennök az a gondolat, hogy ki nagyobb közöttük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 47, 'Jézus pedig látván az ő szívök gondolatát, egy kis gyermeket megfogván, maga mellé állatá azt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 48, 'És monda nékik: Valaki e kis gyermeket befogadja az én nevemben, engem fogad be; és valaki engem befogad, azt fogadja be, a ki engem elküldött; mert a ki legkisebb mindnyájan ti közöttetek, az lesz nagy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 49, 'Felelvén pedig János, monda: Mester, láttunk valakit, a ki a te nevedben ördögöket űz; és eltiltók őt, mivelhogy téged nem követ mi velünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 50, 'És monda néki Jézus: Ne tiltsátok el: mert a ki nincs ellenünk, mellettünk van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 51, 'Lőn pedig, mikor az idő elközelgete, hogy ő felvitessék, eltökélte magát, hogy Jeruzsálembe megy,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 52, 'És követeket külde az ő orczája előtt; és azok elmenvén, bemenének egy samaritánus faluba, hogy néki szállást készítsenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 53, 'De nem fogadák be őt, mivelhogy ő Jeruzsálembe megy vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 54, 'Mikor pedig ezt látták az ő tanítványai, Jakab és János, mondának: Uram, akarod-é, hogy mondjuk, hogy tűz szálljon alá az égből, és emészsze meg ezeket, mint Illyés is cselekedett?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 55, 'De Jézus megfordulván, megdorgálá őket, mondván: Nem tudjátok minémű lélek van ti bennetek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 56, 'Mert az embernek Fia nem azért jött, hogy elveszítse az emberek lelkét, hanem hogy megtartsa. Elmenének azért más faluba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 57, 'Lőn pedig, mikor menének, valaki monda néki az úton: Követlek téged Uram, valahová mégy!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 58, 'És monda néki Jézus: A rókáknak barlangjuk van, és az égi madaraknak fészkük; de az ember Fiának nincs fejét hová lehajtania.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 59, 'Monda pedig másnak: Kövess engem. Az pedig monda: Uram, engedd meg nékem, hogy előbb elmenjek és eltemessem az én atyámat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 60, 'Monda pedig néki Jézus: Hadd temessék el a halottak az ő halottaikat: te pedig elmenvén, hirdesd az Isten országát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 61, 'Monda pedig más is: Követlek téged Uram; de előbb engedd meg nékem, hogy búcsút vegyek azoktól, a kik az én házamban vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 62, 'És monda néki Jézus: Valaki az eke szarvára veti kezét, és hátra tekint, nem alkalmas az Isten országára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, 'Ezek után pedig rendele az Úr másokat is, hetvenet, és elküldé azokat kettőnként az ő orczája előtt, minden városba és helyre, a hová ő menendő vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, 'Monda azért nékik: Az aratni való sok, de a munkás kevés; kérjétek azért az aratásnak Urát, hogy küldjön munkásokat az ő aratásába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, 'Menjetek el: Ímé én elbocsátlak titeket, mint bárányokat a farkasok közé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, 'Ne hordozzatok erszényt, se táskát, se sarut; és az úton senkit ne köszöntsetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, 'Valamely házba bementek, először ezt mondjátok: Békesség e háznak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, 'És ha lesz ott valaki békességnek fia, a ti békességtek azon marad; ha nem, ti reátok tér vissza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, 'Ugyanazon házban maradjatok pedig, azt evén és iván, a mit ők adnak: mert méltó a munkás az ő jutalmára. Ne járjatok házról-házra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, 'És valamely városba bementek, és befogadnak titeket, azt egyétek, a mit előtökbe adnak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, 'És gyógyítsátok a betegeket, a kik ott lesznek, és mondjátok nékik: Elközelített hozzátok az Isten országa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, 'Valamely városba pedig bementek, és titeket be nem fogadnak, annak utczáira kimenvén, ezt mondjátok:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, 'Még a port is, a mely reánk ragadt a ti várostokból, itt köztetek letöröljük; mindazáltal ez legyen tudtotokra, hogy az Isten országa elközelített hozzátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, 'Mondom pedig néktek, hogy a Sodomabeliek állapota tűrhetőbb lesz ama napon, hogynem azé a városé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, 'Jaj néked Korazin! Jaj néked Bethsaida! mert ha Tírusban és Sídonban lettek volna azok a csodák, melyek te benned lőnek, régen zsákban és hamuban ülve megtértek volna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 14, 'Hanem Tírusnak és Sídonnak tűrhetőbb lesz állapota az ítéletkor, hogynem néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 15, 'És te Kapernaum, mely mind az égig felmagasztaltattál, a pokolig fogsz lealáztatni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 16, 'A ki titeket hallgat, engem hallgat, és a ki titeket megvet, engem vet meg; és a ki engem vet meg, azt veti meg, a ki engem elküldött.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 17, 'Visszatére pedig a hetven tanítvány örömmel, mondván: Uram, még az ördögök is engednek nékünk a te neved által!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 18, 'Ő pedig monda nékik: Látám a Sátánt, mint a villámlást lehullani az égből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 19, 'Ímé adok néktek hatalmat, hogy a kígyókon és skorpiókon tapodjatok, és az ellenségnek minden erején; és semmi nem árthat néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 20, 'De azon ne örüljetek, hogy a lelkek néktek engednek; hanem inkább azon örüljetek, hogy a ti neveitek fel vannak írva a mennyben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 21, 'Azon órában örvendeze Jézus lelkében, és monda: Hálákat adok néked, Atyám, mennynek és földnek Ura, hogy elrejtetted ezeket a bölcsek és értelmesek elől, és a kisdedeknek megjelentetted. Igen, Atyám, mert így volt kedves te előtted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 22, 'Mindent nékem adott az én Atyám: és senki sem tudja, kicsoda a Fiú, csak az Atya; és kicsoda az Atya, hanem csak a Fiú, és a kinek a Fiú akarja megjelenteni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 23, 'És a tanítványokhoz fordulván, monda ő magoknak: Boldog szemek, a melyek látják azokat, a melyeket ti láttok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 24, 'Mert mondom néktek, hogy sok próféta és király kívánta látni, a miket ti láttok, de nem látták; és hallani, a miket hallotok, de nem hallották.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 25, 'És ímé egy törvénytudó felkele, kísértvén őt, és mondván: Mester, mit cselekedjem, hogy az örök életet vehessem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 26, 'Ő pedig monda annak: A törvényben mi van megírva? mint olvasod?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 27, 'Az pedig felelvén, monda: Szeresd az Urat, a te Istenedet teljes szívedből és teljes lelkedből és minden erődből és teljes elmédből; és a te felebarátodat, mint magadat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 28, 'Monda pedig annak: Jól felelél; ezt cselekedd, és élsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 29, 'Az pedig igazolni akarván magát, monda Jézusnak: De ki az én felebarátom?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 30, 'Jézus pedig felelvén, monda: Egy ember megy vala alá Jeruzsálemből Jerikóba, és rablók kezébe esék, a kik azt kifosztván és megsebesítvén, elmenének, és ott hagyák félholtan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 31, 'Történet szerint pedig megy vala alá azon az úton egy pap, a ki azt látván, elkerülé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 32, 'Hasonlóképen egy Lévita is, mikor arra a helyre ment, és azt látta, elkerülé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 33, 'Egy samaritánus pedig az úton menvén, odaért, a hol az vala: és mikor azt látta, könyörületességre indula.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 34, 'És hozzájárulván, bekötözé annak sebeit, olajat és bort töltvén azokba; és azt felhelyezvén az ő tulajdon barmára, vivé a vendégfogadó házhoz, és gondját viselé néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 35, 'Másnap pedig elmenőben két pénzt kivévén, adá a gazdának, és monda néki: Viselj gondot reá, és valamit ezen fölül reáköltesz, én mikor visszatérek, megadom néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 36, 'E három közül azért kit gondolsz, hogy felebarátja volt annak, a ki a rablók kezébe esett?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 37, 'Az pedig monda: Az, a ki könyörült rajta. Monda azért néki Jézus: Eredj el, és te is a képen cselekedjél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 38, 'Lőn pedig, mikor az úton menének, hogy ő beméne egy faluba; egy Mártha nevű asszony pedig befogadá őt házába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 39, 'És ennek vala egy Mária nevezetű testvére, ki is Jézus lábainál leülvén, hallgatja vala az ő beszédét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 40, 'Mártha pedig foglalatos volt a szüntelen való szolgálatban; előállván azért, monda: Uram, nincs-é arra gondod, hogy az én testvérem magamra hagyott engem, hogy szolgáljak? Mondjad azért néki, hogy segítsen nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 41, 'Felelvén pedig, monda néki Jézus: Mártha, Mártha, szorgalmas vagy és sokra igyekezel:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 42, 'De egy a szükséges dolog: és Mária a jobb részt választotta, mely el nem vétetik ő tőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, 'És lőn, mikor ő imádkozék egy helyen, minekutána elvégezte, monda néki egy az ő tanítványai közül: Uram, taníts minket imádkozni, miképen János is tanította az ő tanítványait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, 'Monda pedig nékik: Mikor imádkoztok, ezt mondjátok: Mi Atyánk, ki vagy a mennyekben, szenteltessék meg a te neved. Jőjjön el a te országod. Legyen meg a te akaratod, miképen a mennyben, azonképen e földön is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, 'A mi mindennapi kenyerünket add meg nékünk naponként.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, 'És bocsásd meg nékünk a mi bűneinket; mert mi is megbocsátunk mindeneknek, a kik nékünk adósok. És ne vígy minket kisértetbe; de szabadíts meg minket a gonosztól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, 'És monda nékik: Ki az közületek, a kinek barátja van, és ahhoz megy éjfélkor, és ezt mondja néki: Barátom, adj nékem kölcsön három kenyeret,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, 'Mert az én barátom én hozzám jött az útról, és nincs mit adjak ennie;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, 'Az pedig onnét belőlről felelvén, ezt mondaná: Ne bánts engem: immár az ajtó be van zárva, és az én gyermekeim velem vannak az ágyban; nem kelhetek fel, és nem adhatok néked?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, 'Mondom néktek, ha azért nem fog is felkelni és adni néki, mert az barátja, de annak tolakodása miatt felkél és ád néki, a mennyi kell.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, 'Én is mondom néktek: Kérjetek és megadatik néktek; keressetek és találtok; zörgessetek és megnyittatik néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, 'Mert a ki kér, mind kap; és a ki keres, talál; és a zörgetőnek megnyittatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, 'Melyik atya pedig az közületek, a kitől a fia kenyeret kér, és ő talán követ ád néki? vagy ha halat, vajjon a hal helyett kígyót ád-é néki?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, 'Avagy ha tojást kér, vajjon skorpiót ád-é néki?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, 'Ha azért ti gonosz létetekre tudtok a ti fiaitoknak jó ajándékokat adni, mennyivel inkább ád a ti mennyei Atyátok Szent Lelket azoknak, a kik tőle kérik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, 'És ördögöt űz vala ki, mely néma vala. És lőn, mikor kiment az ördög, megszólala a néma; és csodálkozék a sokaság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, 'Némelyek pedig azok közül mondának: A Belzebúb által, az ördögök fejedelme által űzi ki az ördögöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, 'Mások meg, kísértvén őt, mennyei jelt kívánának tőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, 'Ő pedig tudván azoknak gondolatát, monda nékik: Minden ország, a mely magával meghasonlik, elpusztul; és ház a házzal ha meghasonlik, leomlik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, 'És a Sátán is ha ő magával meghasonlik, mimódon állhat meg az ő országa? mert azt mondjátok, hogy én a Belzebúb által űzöm ki az ördögöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, 'És ha én a Belzebúb által űzöm ki az ördögöket, a ti fiaitok ki által űzik ki? Annakokáért ők maguk lesznek a ti bíráitok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, 'Ha pedig Isten ujjával űzöm ki az ördögöket, kétség nélkül elérkezett hozzátok az Isten országa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 21, 'Mikor az erős fegyveres őrzi az ő palotáját, a mije van, békességben van;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 22, 'De mikor a nálánál erősebb reá jövén legyőzi őt, minden fegyverét elveszi, melyhez bízott, és a mit tőle zsákmányol, elosztja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 23, 'A ki velem nincs, ellenem van; és a ki velem nem takar, tékozol.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 24, 'Mikor a tisztátalan lélek kimegy az emberből, víz nélkül való helyeken jár, nyugalmat keresvén; és mikor nem talál, ezt mondja: Visszatérek az én házamba, a honnét kijöttem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 25, 'És oda menvén, kisöpörve és felékesítve találja azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 26, 'Akkor elmegy, és maga mellé vesz más hét lelket, magánál gonoszabbakat, és bemenvén ott lakoznak; és annak az embernek utolsó állapota gonoszabb lesz az elsőnél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 27, 'Lőn pedig mikor ezeket mondá, fölemelvén szavát egy asszony a sokaság közül, monda néki: Boldog méh, a mely téged hordozott, és az emlők, melyeket szoptál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 28, 'Ő pedig monda: Sőt inkább boldogok a kik hallgatják az Istennek beszédét, és megtartják azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 29, 'Mikor pedig a sokaság hozzá gyülekezék, kezdé mondani: E nemzetség gonosz: jelt kíván, de jel nem adatik néki, hanem ha Jónás prófétának ama jele;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 30, 'Mert miképen Jónás jelül volt a Ninivebelieknek, azonképen lesz az embernek Fia is e nemzetségnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 31, 'A Délnek királynéasszonya felkél majd az ítéletkor e nemzetség férfiaival, és kárhoztatja őket: mert ő eljött a földnek széléről, hogy hallhassa a Salamon bölcseségét; és ímé nagyobb van itt Salamonnál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 32, 'Ninive férfiai az ítéletkor együtt támadnak majd fel e nemzetséggel, és kárhoztatják ezt: mivelhogy ők megtértek a Jónás prédikálására; és ímé nagyobb van itt Jónásnál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 33, 'Senki pedig, ha gyertyát gyújt, nem teszi rejtekbe, sem a véka alá, hanem a gyertyatartóba, hogy a kik bemennek, lássák a világosságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 34, 'A testnek lámpása a szem: ha azért a te szemed őszinte, a te egész tested is világos lesz; ha pedig a te szemed gonosz, a te tested is sötét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 35, 'Meglásd azért, hogy a világosság, mely te benned van, sötétség ne legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 36, 'Annakokáért ha a te egész tested világos, és semmi részében sincs homályosság, olyan világos lesz egészen, mint mikor a lámpás megvilágosít téged az ő világosságával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 37, 'Beszéd közben pedig kéré őt egy farizeus, hogy ebédeljen nála. Bemenvén azért, leüle enni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 38, 'A farizeus pedig mikor ezt látta, elcsodálkozék, hogy ebéd előtt előbb nem mosdott meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 39, 'Monda pedig az Úr néki: Ti farizeusok jóllehet a pohárnak és tálnak külső részét megtisztítjátok; de a belsőtök rakva ragadománynyal és gonoszsággal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 40, 'Bolondok, a ki azt teremtette, a mi kívül van, nem ugyanaz teremtette-é azt is, a mi belől van?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 41, 'Csak adjátok alamizsnául a mi benne van; és minden tiszta lesz néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 42, 'De jaj néktek farizeusok! mert megadjátok a dézsmát a mentától, rutától és minden paréjtól, de hátra hagyjátok az ítéletet és az Isten szeretetét: pedig ezeket kellene cselekedni, és amazokat sem elhagyni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 43, 'Jaj néktek farizeusok! mert szeretitek az előlülést a gyülekezetekben, és a piaczokon való köszöntéseket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 44, 'Jaj néktek képmutató írástudók és farizeusok! mert olyanok vagytok, mint a sírok, a melyek nem látszanak, és az emberek, a kik azokon járnak, nem tudják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 45, 'Felelvén pedig egy a törvénytudók közül, monda néki: Mester, mikor ezeket mondod, minket is bántasz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 46, 'Ő pedig monda: Jaj néktek is törvénytudók! mert elhordozhatatlan terhekkel terhelitek meg az embereket, de ti magatok egy ujjotokkal sem illetitek azokat a terheket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 47, 'Jaj néktek! mert ti építitek a próféták sírjait; a ti atyáitok pedig megölték őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 48, 'Tehát bizonyságot tesztek és jóvá hagyjátok atyáitok cselekedeteit; mert azok megölték őket, ti pedig építitek sírjaikat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 49, 'Ezért mondta az Isten bölcsesége is: Küldök ő hozzájuk prófétákat és apostolokat; és azok közül némelyeket megölnek, és némelyeket elüldöznek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 50, 'Hogy számon kéressék e nemzetségtől minden próféták vére, mely e világ fundamentomának felvettetésétől fogva kiontatott,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 51, 'Az Ábel vérétől fogva mind a Zakariás véréig, ki elveszett az oltár és a templom között: bizony, mondom néktek, számon kéretik e nemzetségtől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 52, 'Jaj néktek törvénytudók! mert elvettétek a tudománynak kulcsát: ti magatok nem mentetek be, és a kik be akartak menni, azokat meggátoltátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 53, 'Mikor pedig ezeket mondá nékik, az írástudók és farizeusok kezdének felette igen ellene állani és őt sok dolog felől kikérdezgetni,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 54, 'Ólálkodván ő utána, és igyekezvén valamit az ő szájából kikapni, hogy vádolhassák őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, 'Ezenközben mikor sok ezerből álló sokaság gyűlt egybe, annyira, hogy egymást letapossák, kezdé az ő tanítványainak mondani: Mindenekelőtt oltalmazzátok meg magatokat a farizeusok kovászától, mely a képmutatás;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, 'Mert nincs oly rejtett dolog, mely napfényre ne jőne; és oly titok, mely ki ne tudódnék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, 'Annakokáért a mit a sötétben mondtatok, a világosságban fog meghallatszani; és a mit fülbe sugtatok a rejtekházakban, azt a házak tetején fogják hirdetni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, 'Mondom pedig néktek én barátaimnak: Ne féljetek azoktól, kik a testet ölik meg, és azután többet nem árthatnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, 'De megmondom néktek, kitől féljetek: Féljetek attól, a ki minekutána megöl, van arra is hatalma, hogy a gyehennára vessen. Bizony, mondom néktek, ettől féljetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, 'Nemde öt verebet meg lehet venni két filléren? és egy sincs azok közül Istennél elfelejtve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 7, 'De néktek a fejetek hajszálai is mind számon vannak. Ne féljetek azért, sok verébnél drágábbak vagytok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 8, 'Mondom pedig néktek: Valaki vallást tesz én rólam az emberek előtt, az embernek Fia is vallást tesz arról az Isten angyalai előtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 9, 'A ki pedig megtagad engem az emberek előtt, megtagadtatik az Isten angyalai előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 10, 'És ha valaki valamit mond az embernek Fia ellen, megbocsáttatik annak; de annak, a ki a Szent Lélek ellen szól káromlást, meg nem bocsáttatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 11, 'Mikor pedig a zsinagógákba visznek benneteket, és a fejedelmek és hatalmasságok elé, ne aggodalmaskodjatok, mimódon vagy mit szóljatok védelmetekre, vagy mit mondjatok;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 12, 'Mert a Szent Lélek azon órában megtanít titeket, mit kell mondanotok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 13, 'Monda pedig néki egy a sokaság közül: Mester, mondd meg az én testvéremnek, hogy oszsza meg velem az örökséget.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 14, 'Ő pedig monda néki: Ember, ki tett engem köztetek biróvá vagy osztóvá?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 15, 'Monda azért nékik: Meglássátok, hogy eltávoztassátok a telhetetlenséget; mert nem a vagyonnal való bővölködésben van az embernek az ő élete.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 16, 'És monda nékik egy példázatot, szólván: Egy gazdag embernek bőségesen termett a földje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 17, 'Azért magában okoskodék, mondván: Mit cselekedjem? mert nincs hová takarnom az én termésemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 18, 'És monda: Ezt cselekszem: Az én csűreimet lerontom, és nagyobbakat építek; és azokba takarom minden gabonámat és az én javaimat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 19, 'És ezt mondom az én lelkemnek: Én lelkem, sok javaid vannak sok esztendőre eltéve; tedd magadat kényelembe, egyél, igyál, gyönyörködjél!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 20, 'Monda pedig néki az Isten: Bolond, ez éjjel elkérik a te lelkedet te tőled; a miket pedig készítettél, kiéi lesznek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 21, 'Így van dolga annak, a ki kincset takar magának, és nem az Istenben gazdag.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 22, 'Monda pedig az ő tanítványainak: Annakokáért mondom néktek, ne aggodalmaskodjatok a a ti éltetek felől, mit egyetek; se a ti testetek felől, mibe öltözködjetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 23, 'Az élet több, hogynem az eledel, és a test, hogynem az öltözet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 24, 'Tekintsétek meg a hollókat, hogy nem vetnek, sem nem aratnak; kiknek nincs tárházuk, sem csűrük; és az Isten eltartja őket: mennyivel drágábbak vagytok ti a madaraknál?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 25, 'Kicsoda pedig az közületek, a ki aggodalmaskodásával megnövelheti termetét egy arasszal?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 26, 'Annakokáért ha a mi legkisebb dolog, azt sem tehetitek, mit aggodalmaskodtok a többi felől?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 27, 'Tekintsétek meg a liliomokat, mimódon növekednek: nem fáradoznak és nem fonnak: de mondom néktek: Salamon minden ő dicsőségében sem öltözött úgy, mint ezek közül egy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 28, 'Ha pedig a füvet, mely ma a mezőn van, és holnap kemenczébe vettetik, így ruházza az Isten; mennyivel inkább titeket, ti kicsinyhitűek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 29, 'Ti se kérdezzétek, mit egyetek vagy mit igyatok; és ne kételkedjetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 30, 'Mert mind ezeket a világi pogányok kérdezik; a ti Atyátok pedig tudja, hogy néktek szükségetek van ezekre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 31, 'Csak keressétek az Isten országát, és ezek mind megadatnak néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 32, 'Ne félj te kicsiny nyáj; mert tetszett a ti Atyátoknak, hogy néktek adja az országot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 33, 'Adjátok el a mitek van, és adjatok alamizsnát; szerezzetek magatoknak oly erszényeket, melyek meg nem avúlnak, elfogyhatatlan kincset a mennyországban, a hol a tolvaj hozzá nem fér, sem a moly meg nem emészti.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 34, 'Mert a hol van a ti kincsetek, ott van a ti szívetek is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 35, 'Legyenek a ti derekaitok felövezve, és szövétnekeitek meggyújtva;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 36, 'Ti meg hasonlók az olyan emberekhez, a kik az ő urokat várják, mikor jő meg a menyegzőről, hogy mihelyt megjő és zörget, azonnal megnyissák néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 37, 'Boldogok azok a szolgák, kiket az úr, mikor haza megy, vigyázva talál: bizony mondom néktek, hogy felövezvén magát, leülteti azokat, és előjövén, szolgál nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 38, 'És ha megjő a második őrváltáskor, és ha a harmadik őrváltáskor jő meg, és úgy találja őket, boldogok azok a szolgák!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 39, 'Ezt pedig jegyezzétek meg, hogy ha tudná a ház gazdája, mely órában jő el a tolvaj, vigyázna, és nem engedné, hogy az ő házába törjön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 40, 'Ti is azért legyetek készek: mert a mely órában nem gondolnátok, abban jő el az embernek Fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 41, 'Monda pedig néki Péter: Uram, nékünk mondod-é ezt a példázatot, vagy mindenkinek is?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 42, 'Monda pedig az Úr: Kicsoda hát a hű és bölcs sáfár, kit az úr gondviselővé tőn az ő háza népén, hogy adja ki nékik élelmüket a maga idejében?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 43, 'Boldog az a szolga, a kit az ő ura, mikor haza jő, ilyen munkában talál!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 44, 'Bizony mondom néktek, hogy minden jószága felett gondviselővé teszi őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 45, 'Ha pedig az a szolga így szólna az ő szívében: Halogatja még az én uram a hazajövetelt; és kezdené verni a szolgákat és szolgálóleányokat, és enni és inni és részegeskedni:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 46, 'Megjő annak a szolgának az ura, a mely napon nem várja és a mely órában nem gondolja, és kettévágatja őt, és a hitetlenek sorsára juttatja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 47, 'És a mely szolga tudta az ő urának akaratát, és nem végezte el, sem annak akarata szerint nem cselekedett, sokkal büntettetik meg;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 48, 'A ki pedig nem tudta, és büntetésre méltó dolgokat cselekedett, kevesebbel büntettetik. És valakinek sokat adtak, sokat követelnek tőle; és a kire sokat bíztak, többet kívánnak tőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 49, 'Azért jöttem, hogy e világra tüzet bocsássak: és mit akarok, ha az immár meggerjedett?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 50, 'De keresztséggel kell nékem megkereszteltetnem; és mely igen szorongattatom, míglen az elvégeztetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 51, 'Gondoljátok-é, hogy azért jöttem, hogy békességet adjak e földön? Nem, mondom néktek; sőt inkább meghasonlást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 52, 'Mert mostantól fogva öten lesznek egy házban, a kik meghasonlanak, három kettő ellen, és kettő három ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 53, 'Meghasonlik az atya a fiú ellen, és a fiú az atya ellen; és az anya a leány ellen, és a leány az anya ellen; napa a menye ellen, és a menye a napa ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 54, 'Monda pedig a sokaságnak is: Mikor látjátok, hogy napnyugotról felhő támad, azonnal ezt mondjátok: Záporeső jő; és úgy lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 55, 'És mikor halljátok fúni a déli szelet, ezt mondjátok: Hőség lesz; és úgy lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 56, 'Képmutatók, az égnek és a földnek ábrázatáról tudtok ítéletet tenni; erről az időről pedig mi dolog, hogy nem tudtok ítéletet tenni?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 57, 'És mi dolog, hogy ti magatoktól is meg nem ítélitek, mi az igaz?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 58, 'Mikor pedig a te ellenségeddel a fejedelem elé mégy, igyekezzél az úton megmenekedni tőle, hogy téged ne vonjon a bíró elé, és a bíró át ne adjon téged a poroszlónak és a poroszló a tömlöczbe ne vessen téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 59, 'Mondom néked, hogy nem jősz ki onnét, mígnem megfizetsz mind az utolsó fillérig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, 'Jövének pedig ugyanazon időben némelyek, kik néki hírt mondának a Galileabeliek felől, kiknek vérét Pilátus az ő áldozatukkal elegyítette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, 'És felelvén Jézus, monda nékik: Gondoljátok-é, hogy ezek a Galileabeliek bűnösebbek voltak valamennyi Galileabelinél, mivelhogy ezeket szenvedték?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, 'Nem, mondom néktek: sőt inkább, ha meg nem tértek, mindnyájan, hasonlóképen elvesztek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, 'Vagy az a tizennyolcz, a kire rászakadt a torony Siloámban, és megölte őket, gondoljátok-é, hogy bűnösebb volt minden más Jeruzsálemben lakó embernél?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, 'Nem, mondom néktek: sőt inkább, ha meg nem tértek, mindnyájan hasonlóképen elvesztek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, 'És ezt a példázatot mondá: Vala egy embernek egy fügefája szőlejébe ültetve; és elméne, hogy azon gyümölcsöt keressen, és nem talála.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, 'És monda a vinczellérnek: Ímé három esztendeje járok gyümölcsöt keresni e fügefán, és nem találok: vágd ki azt; miért foglalja a földet is hiába?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, 'Az pedig felelvén, monda néki: Uram, hagyj békét néki még ez esztendőben, míg köröskörül megkapálom és megtrágyázom:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, 'És ha gyümölcsöt terem, jó; ha pedig nem, azután vágd ki azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, 'Tanít vala pedig szombatnapon egy zsinagógában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, 'És ímé vala ott egy asszony, kiben betegségnek lelke vala tizennyolcz esztendőtől fogva; és meg volt görbedve, és teljességgel nem tudott felegyenesedni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, 'És mikor azt látta Jézus, előszólítá, és monda néki: Asszony, feloldattál a te betegségedből!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, 'És reá veté kezeit; és azonnal felegyenesedék, és dicsőíté az Istent.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, 'Felelvén pedig a zsinagógafő, haragudva, hogy szombatnapon gyógyított Jézus, monda a sokaságnak: Hat nap van, a melyen munkálkodni kell; azokon jőjjetek azért és gyógyíttassátok magatokat, és ne szombatnapon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, 'Felele azért néki az Úr, és monda: Képmutató, szombatnapon nem oldja-é el mindenitek az ő ökrét vagy szamarát a jászoltól, és nem viszi-é itatni?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, 'Hát ezt, az Ábrahám leányát, kit a Sátán megkötözött ímé tizennyolcz esztendeje, nem kellett-é feloldani e kötélből szombatnapon?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, 'És mikor ezeket mondta, megszégyenülének mindnyájan, kik magokat néki ellenébe veték; és az egész nép örül vala mind azokon a dicsőséges dolgokon, a melyek ő általa lettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, 'Monda pedig Jézus: Mihez hasonló az Isten országa? és mihez hasonlítsam azt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 19, 'Hasonló a mustármaghoz, melyet az ember vévén, elvet az ő kertjében; és felnevelkedett, és lett nagy fává, és az égi madarak fészket raktak annak ágain.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 20, 'És ismét monda: Mihez hasonlítsam az Isten országát?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 21, 'Hasonló a kovászhoz, melyet az asszony vévén, három mércze lisztbe elegyíte, mígnem az egész megkele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 22, 'És városokon és falvakon megy vala által, tanítva, és Jeruzsálembe menve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 23, 'Monda pedig néki valaki: Uram, avagy kevesen vannak-é a kik idvezülnek? Ő pedig monda nékik:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 24, 'Igyekezzetek bemenni a szoros kapun: mert sokan, mondom néktek, igyekeznek bemenni és nem mehetnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 25, 'Mikor már a gazda felkél és bezárja az ajtót, és kezdetek kívül állani és az ajtót zörgetni, mondván: Uram! Uram! nyisd meg nékünk; és ő felelvén, ezt mondja néktek: Nem tudom honnét valók vagytok ti;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 26, 'Akkor kezditek mondani: Te előtted ettünk és ittunk, és a mi utczáinkon tanítottál;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 27, 'De ezt mondja: Mondom néktek, nem tudom honnét valók vagytok ti; távozzatok el én tőlem mindnyájan, kik hamisságot cselekesztek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 28, 'Ott lesz sírás és fogak csikorgatása, mikor látjátok Ábrahámot, Izsákot és Jákóbot, és a prófétákat mind az Isten országában, magatokat pedig kirekesztve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 29, 'És jőnek napkeletről és napnyugatról, és északról és délről, és az Isten országában letelepednek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 30, 'És ímé vannak utolsók, a kik elsők lesznek, és vannak elsők, a kik utolsók lesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 31, 'Ugyanazon napon jövének ő hozzá némelyek a farizeusok közül, mondván néki: Eredj ki és menj el innét: mert Heródes meg akar téged ölni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 32, 'És monda nékik: Elmenvén mondjátok meg annak a rókának: Ímé ördögöket űzök ki és gyógyítok ma és holnap, és harmadnapon elvégeztetem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 33, 'Hanem nékem ma és holnap és azután úton kell lennem; mert nem lehetséges, hogy a próféta Jeruzsálemen kívül vesszen el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 34, 'Jeruzsálem! Jeruzsálem! ki megölöd a prófétákat, és megkövezed azokat, a kik te hozzád küldettek, hányszor akartam egybegyűjteni a te fiaidat, miképen a tyúk az ő kis csirkéit az ő szárnyai alá, és ti nem akarátok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 35, 'Ímé pusztán hagyatik néktek a ti házatok; és bizony mondom néktek, hogy nem láttok engem, mígnem eljő az idő, mikor ezt mondjátok: Áldott, a ki jő az Úrnak nevében!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, 'És lőn mikor a főfarizeusok közül egynek házához ment szombatnapon kenyeret enni, azok leselkednek vala ő utána.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, 'És ímé egy vízkóros ember vala ő előtte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, 'És felelvén Jézus, szóla a törvénytudóknak és a farizeusoknak, mondván: Szabad-é szombatnapon gyógyítani?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, 'Azok pedig hallgatának. És ő megfogván azt, meggyógyítá és elbocsátá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, 'És felelvén nékik, monda: Ki az közületek, a kinek szamara vagy ökre a kútba esik, és nem vonja ki azt azonnal szombatnapon?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, 'És nem felelhetnek vala ő ellene semmit ezekre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, 'És egy példázatot monda a hivatalosoknak, mikor észre vevé, mimódon válogatják a fő helyeket; mondván nékik:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, 'Mikor valaki lakodalomba hív, ne ülj a fő helyre; mert netalán náladnál nagyobb tiszteletben álló embert is hivott meg az,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, 'És eljövén az, a ki mind téged, mind azt meghívta, ezt mondja majd néked: Engedd ennek a helyet! És akkor szégyennel az utolsó helyre fogsz ülni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, 'Hanem mikor meghívnak, menj el és ülj le az utolsó helyre; hogy mikor eljő az, a ki téged meghívott, ezt mondja néked: Barátom ülj feljebb! Akkor néked dicsőséged lesz azok előtt, a kik veled együtt ülnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, 'Mert mindenki, a ki magát felmagasztalja, megaláztatik; és a ki magát megalázza, felmagasztaltatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, 'Monda pedig annak is, a ki őt meghívta: Mikor ebédet vagy vacsorát készítesz, ne hívd barátaidat, se testvéreidet, se rokonaidat, se gazdag szomszédaidat; nehogy viszont ők is meghívjanak téged, és visszafizessék néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, 'Hanem mikor lakomát készítesz, hívd a szegényeket, csonkabonkákat, sántákat, vakokat:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, 'És boldog leszel; mivelhogy nem fizethetik vissza néked; mert majd visszafizettetik néked az igazak feltámadásakor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, 'Hallván pedig ezeket egy azok közül, a kik ő vele együtt ülnek vala, monda néki: Boldog az, a ki eszik kenyeret az Isten országában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, 'Ő pedig monda annak: Egy ember készíte nagy vacsorát, és sokakat meghíva;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, 'És elküldé szolgáját a vacsora idején, hogy megmondja a hivatalosoknak: Jertek el, mert immár minden kész!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, 'És mindnyájan egyenlőképen kezdék magokat mentegetni. Az első monda néki: Szántóföldet vettem, és ki kell mennem, hogy azt meglássam; kérlek téged, ments ki engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, 'És másik monda: Öt iga ökröt vettem, és elmegyek, hogy azokat megpróbáljam; kérlek téged, ments ki engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 20, 'A másik pedig monda: Feleséget vettem, és azért nem mehetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 21, 'Mikor azért az a szolga haza ment, megmondá ezeket az ő urának. Akkor megharagudván a gazda, monda az ő szolgájának: Eredj hamar a város utczáira és szorosaira, és a szegényeket, csonkabonkákat, sántákat és vakokat hozd be ide.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 22, 'És monda a szolga: Uram, meglett a mint parancsolád, és mégis van hely.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 23, 'Akkor monda az úr a szolgának: Eredj el az utakra és a sövényekhez, és kényszeríts bejőni mindenkit, hogy megteljék az én házam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 24, 'Mert mondom néktek, hogy senki azok közül a hivatalos férfiak közül meg nem kóstolja az én vacsorámat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 25, 'Megy vala pedig ő vele nagy sokaság; és megfordulván, monda azoknak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 26, 'Ha valaki én hozzám jő, és meg nem gyűlöli az ő atyját és anyját, feleségét és gyermekeit, fitestvéreit és nőtestvéreit, sőt még a maga lelkét is, nem lehet az én tanítványom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 27, 'És valaki nem hordozza az ő keresztjét, és én utánam jő, nem lehet az én tanítványom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 28, 'Mert ha közületek valaki tornyot akar építeni, nemde először leülvén felszámítja a költséget, ha van-é mivel elvégezze?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 29, 'Nehogy minekutána fundamentomot vetett, és elvégezni nem bírja, csúfolni kezdje őt mindenki, a ki látja,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 30, 'Ezt mondván: Ez az ember elkezdette az építést, és nem bírta véghez vinni!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 31, 'Vagy valamely király, mikor háborúba megy, hogy egy másik királlyal megütközzék, nemde leülvén először tanácskozik, hogy tízezerrel szembeszállhat-é azzal, a ki ő ellene húszezerrel jött?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 32, 'Mert különben még mikor amaz távol van, követséget küldvén, megkérdezi a békefeltételeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 33, 'Ezenképen azért valaki közületek búcsút nem vesz minden javaitól, nem lehet az én tanítványom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 34, 'Jó a só: de ha a só megízetlenül, mivel sózzák meg?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 35, 'Sem a földre, sem a trágyára nem alkalmas: kivetik azt. A kinek van füle a hallásra, hallja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, 'Közelgetnek vala pedig ő hozzá a vámszedők és a bűnösök mind, hogy hallgassák őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, 'És zúgolódának a farizeusok és az írástudók, mondván: Ez bűnösöket fogad magához, és velök együtt eszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, 'Ő pedig ezt a példázatot beszélé nékik, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, 'Melyik ember az közületek, a kinek ha száz juha van, és egyet azok közül elveszt, nem hagyja ott a kilenczvenkilenczet a pusztában, és nem megy az elveszett után, mígnem megtalálja azt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, 'És ha megtalálta, felveti az ő vállára, örülvén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, 'És haza menvén, egybehívja barátait és szomszédait, mondván nékik: Örvendezzetek én velem, mert megtaláltam az én juhomat, a mely elveszett vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, 'Mondom néktek, hogy ily módon nagyobb öröm lesz a mennyben egy megtérő bűnösön, hogynem kilenczvenkilencz igaz emberen, a kinek nincs szüksége megtérésre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, 'Avagy ha valamely asszonynak tíz drakhmája van, és egy drakhmát elveszt, nem gyújt-é gyertyát, és nem sepri-é ki a házat, és nem keresi-é gondosan, mígnem megtalálja?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, 'És ha megtalálta, egybehívja az ő asszonybarátait és szomszédait, mondván: Örüljetek én velem, mert megtaláltam a drakhmát, melyet elvesztettem vala!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, 'Ezenképen, mondom néktek, örvendezés van az Isten angyalainak színe előtt egy bűnös ember megtérésén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, 'Monda pedig: Egy embernek vala két fia;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, 'És monda az ifjabbik az ő atyjának: Atyám, add ki a vagyonból rám eső részt! És az megosztá köztök a vagyont.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, 'Nem sok nap mulva aztán a kisebbik fiú összeszedvén mindenét, messze vidékre költözék; és ott eltékozlá vagyonát, mivelhogy dobzódva élt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, 'Minekutána pedig mindent elköltött, támada nagy éhség azon a vidéken, és ő kezde szükséget látni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, 'Akkor elmenvén, hozzá szegődék annak a vidéknek egyik polgárához; és az elküldé őt az ő mezeire disznókat legeltetni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, 'És kívánja vala megtölteni az ő gyomrát azzal a moslékkal, a mit a disznók ettek; és senki sem ád vala néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 17, 'Mikor aztán magába szállt, monda: Az én atyámnak mily sok bérese bővölködik kenyérben, én pedig éhen halok meg!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 18, 'Fölkelvén elmegyek az én atyámhoz, és ezt mondom néki: Atyám, vétkeztem az ég ellen és te ellened.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 19, 'És nem vagyok immár méltó, hogy a te fiadnak hivattassam; tégy engem olyanná, mint a te béreseid közül egy!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 20, 'És felkelvén, elméne az ő atyjához. Mikor pedig még távol volt, meglátá őt az ő atyja, és megesék rajta a szíve, és oda futván, a nyakába esék, és megcsókolgatá őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 21, 'És monda néki a fia: Atyám, vétkeztem az ég ellen és te ellened; és nem vagyok immár méltó, hogy a te fiadnak hivattassam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 22, 'Az atyja pedig monda az ő szolgáinak: Hozzátok ki a legszebb ruhát, és adjátok fel rá; és húzzatok gyűrűt a kezére, és sarut a lábaira!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 23, 'És előhozván a hízott tulkot, vágjátok le, és együnk és vígadjunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 24, 'Mert ez az én fiam meghalt, és feltámadott; elveszett, és megtaláltatott. Kezdének azért vígadni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 25, 'Az ő nagyobbik fia pedig a mezőn vala: és mikor hazajövén, közelgetett a házhoz, hallá a zenét és tánczot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 26, 'És előszólítván egyet a szolgák közül, megtudakozá, mi dolog az?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 27, 'Az pedig monda néki: A te öcséd jött meg; és atyád levágatá a hízott tulkot, mivelhogy egészségben nyerte őt vissza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 28, 'Erre ő megharaguvék, és nem akara bemenni. Az ő atyja annakokáért kimenvén, kérlelé őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 29, 'Ő pedig felelvén, monda atyjának: Ímé ennyi esztendőtől fogva szolgálok néked, és soha parancsolatodat át nem hágtam: és nékem soha nem adtál egy kecskefiat, hogy az én barátaimmal vígadjak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 30, 'Mikor pedig ez a te fiad megjött, a ki paráznákkal emésztette föl a te vagyonodat, levágattad néki a hízott tulkot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 31, 'Az pedig monda néki: Fiam, te mindenkor én velem vagy, és mindenem a tiéd!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 32, 'Vígadnod és örülnöd kellene hát, hogy ez a te testvéred meghalt, és feltámadott; és elveszett, és megtaláltatott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, 'Monda pedig az ő tanítványainak is: Vala egy gazdag ember, kinek vala egy sáfára; és az bevádoltaték nála, hogy javait eltékozolja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, 'Hívá azért azt, és monda néki: Mit hallok felőled? Adj számot a te sáfárságodról; mert nem lehetsz tovább sáfár.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, 'Monda pedig magában a sáfár: Mit míveljek, mivelhogy az én uram elveszi tőlem a sáfárságot? Kapálni nem tudok; koldulni szégyenlek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, 'Tudom mit tegyek, hogy mikor a sáfárságtól megfosztatom, befogadjanak engem házaikba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, 'És magához hivatván az ő urának minden egyes adósát, monda az elsőnek: Mennyivel tartozol az én uramnak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, 'Az pedig monda: Száz bátus olajjal. És monda néki: Vedd a te írásodat, és leülvén, hamar írj ötvent.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, 'Azután monda másnak: Te pedig mennyivel tartozol? Az pedig monda: Száz kórus búzával. És monda annak: Vedd a te írásodat, és írj nyolczvanat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, 'És dícséré az úr a hamis sáfárt, hogy eszesen cselekedett, mert e világnak fiai eszesebbek a világosságnak fiainál a maguk nemében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, 'Én is mondom néktek, szerezzetek magatoknak barátokat a hamis mammonból, hogy mikor meghaltok, befogadjanak benneteket az örök hajlékokba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, 'A ki hű a kevesen, a sokon is hű az; és a ki a kevesen hamis, a sokon is hamis az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, 'Ha azért a hamis mammonon hívek nem voltatok, ki bízná reátok az igazi kincset?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, 'És ha a másén hívek nem voltatok, ki adja oda néktek, a mi a tiétek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, 'Egy szolga sem szolgálhat két úrnak: mert vagy az egyiket gyűlöli és a másikat szereti; vagy az egyikhez ragaszkodik, és a másikat megveti. Nem szolgálhattok az Istennek és a mammonnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, 'Hallák pedig mindezeket a farizeusok is, kik pénzszeretők valának; és csúfolák őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, 'És monda nékik: Ti vagytok, a kik az emberek előtt magatokat megigazítjátok; de az Isten ismeri a ti szíveteket: mert a mi az emberek közt magasztos, az Isten előtt útálatos.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, 'A törvény és a próféták Keresztelő Jánosig valának: az időtől fogva az Istennek országa hirdettetik, és mindenki erőszakkal tör abba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, 'Könnyebb pedig a mennynek és a földnek elmúlni, hogynem a törvényből egy pontocskának elesni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, 'Valaki elbocsátja feleségét, és mást vesz el, paráználkodik; és valaki férjétől elbocsátott asszonyt vesz feleségül, paráználkodik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, 'Vala pedig egy gazdag ember, és öltözik vala bíborba és patyolatba, mindennap dúsan vigadozván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, 'És vala egy Lázár nevű koldus, ki az ő kapuja elé volt vetve, fekélyekkel tele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, 'És kíván vala megelégedni a morzsalékokkal, melyek hullanak vala a gazdagnak asztaláról; de az ebek is eljővén, nyalják vala az ő sebeit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, 'Lőn pedig, hogy meghala a koldus, és viteték az angyaloktól az Ábrahám kebelébe; meghala pedig a gazdag is, és eltemetteték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, 'És a pokolban felemelé az ő szemeit, kínokban lévén, és látá Ábrahámot távol, és Lázárt annak kebelében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, 'És ő kiáltván, monda: Atyám Ábrahám! könyörülj rajtam, és bocsásd el Lázárt, hogy mártsa az ő ujjának hegyét vízbe, és hűsítse meg az én nyelvemet; mert gyötrettetem e lángban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 25, 'Monda pedig Ábrahám: Fiam, emlékezzél meg róla, hogy te javaidat elvetted a te életedben, hasonlóképen Lázár is az ő bajait: most pedig ez vígasztaltatik, te pedig gyötrettetel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 26, 'És mindenekfelett, mi köztünk és ti közöttetek nagy közbevetés van, úgy, hogy a kik akarnának innét ti hozzátok általmenni, nem mehetnek, sem azok onnét hozzánk át nem jöhetnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 27, 'Monda pedig amaz: Kérlek azért téged Atyám, hogy bocsásd el őt az én atyámnak házához;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 28, 'Mert van öt testvérem; hogy bizonyságot tegyen nékik, hogy ők is ide, e gyötrelemnek helyére ne jussanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 29, 'Monda néki Ábrahám: Van Mózesök és prófétáik; hallgassák azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 30, 'Ama pedig monda: Nem úgy, atyám Ábrahám; hanem ha a halottak közül megy valaki hozzájok, megtérnek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 31, 'Ő pedig monda néki: Ha Mózesre és a prófétákra nem hallgatnak, az sem győzi meg őket, ha valaki a halottak közül feltámad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 1, 'Monda pedig a tanítványoknak: Lehetetlen dolog, hogy botránkozások ne essenek; de jaj annak, a ki által esnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 2, 'Jobb annak, ha egy malomkövet vetnek a nyakába, és ha a tengerbe vettetik, hogynem mint egyet e kicsinyek közül megbotránkoztasson.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 3, 'Őrizzétek meg magatokat: ha pedig a te atyádfia vétkezik ellened, dorgáld meg őt; és ha megtér, bocsáss meg néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 4, 'És ha egy napon hétszer vétkezik ellened, és egy napon hétszer te hozzád tér, mondván: Megbántam; megbocsáss néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 5, 'És mondának az apostolok az Úrnak: Növeljed a mi hitünket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 6, 'Monda pedig az Úr: Ha annyi hitetek volna, mint a mustármag, ezt mondanátok ím ez eperfának: Szakadj ki gyökerestől, és plántáltassál a tengerbe; és engede néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 7, 'Kicsoda pedig ti közületek az, a ki, ha egy szolgája van, és az szánt vagy legeltet, tüstént azt mondja annak, mihelyt a mezőről megjő: Jer elő, ülj asztalhoz?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 8, 'Sőt nem ezt mondja-e néki: Készíts vacsorámra valót, és felövezvén magadat, szolgálj nékem, míg én eszem és iszom; és azután egyél és igyál te?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 9, 'Avagy megköszöni-é annak a szolgának, hogy azt mívelte, a mit néki parancsolt? Nem gondolom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 10, 'Ezenképen ti is, ha mindazokat megcselekedtétek, a mik néktek parancsoltattak, mondjátok, hogy: Haszontalan szolgák vagyunk; mert a mit kötelesek voltunk cselekedni, azt cselekedtük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 11, 'És lőn, mikor útban vala Jeruzsálem felé, hogy ő Samariának és Galileának közepette méne által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 12, 'És mikor egy faluba beméne, jöve elébe tíz bélpoklos férfi, kik távol megállának:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 13, 'És felemelék szavokat, mondván: Jézus, Mester, könyörülj rajtunk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 14, 'És mikor őket látta, monda nékik: Elmenvén mutassátok meg magatokat a papoknak. És lőn, hogy míg odamenének, megtisztulának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 15, 'Egy pedig ő közülök, mikor látta, hogy meggyógyult, visszatére, dicsőítvén az Istent nagy szóval;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 16, 'És arczczal leborula az ő lábainál hálákat adván néki: és az Samariabeli vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 17, 'Felelvén pedig Jézus, monda: Avagy nem tízen tisztulának-é meg? A kilencze pedig hol van?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 18, 'Nem találkoztak a kik visszatértek volna dicsőséget adni az Istennek, csak ez az idegen?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 19, 'És monda néki: Kelj föl, és menj el: a te hited téged megtartott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 20, 'Megkérdeztetvén pedig a farizeusoktól, mikor jő el az Isten országa, felele nékik és monda: Az Isten országa nem szemmel láthatólag jő el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 21, 'Sem azt nem mondják: Ímé itt, vagy: Ímé amott van; mert ímé az Isten országa ti bennetek van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 22, 'Monda pedig a tanítványoknak: Eljő az idő, mikor kívántok látni egyet az ember Fiának napjai közül, és nem láttok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 23, 'És mondják majd néktek: Ímé itt, vagy: Ímé amott van; de ne menjetek el, és ne kövessétek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 24, 'Mert miként a felvillanó villámlás az ég aljától az ég aljáig fénylik; úgy lesz az embernek Fia is az ő napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 25, 'De előbb sokat kell néki szenvednie és megvettetnie e nemzetségtől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 26, 'És miként a Noé napjaiban lett, úgy lesz az ember Fiának napjaiban is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 27, 'Ettek, ittak, házasodtak, férjhezmentek mindama napig, a melyen Noé a bárkába beméne, és eljöve az özönvíz, és mindeneket elveszte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 28, 'Hasonlóképen mint a Lót napjaiban is lett; ettek, ittak, vettek, adtak, ültettek, építettek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 29, 'De a mely napon kiment Lót Sodomából, tűz és kénkő esett az égből, és mindenkit elvesztett:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 30, 'Ezenképen lesz azon a napon, melyen az embernek Fia megjelenik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 31, 'Az nap, a ki a háztetőn lesz, és az ő holmija a házban, ne szálljon le, hogy elvigye; és a ki a mezőn, azonképen ne forduljon hátra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 32, 'Emlékezzetek Lót feleségére!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 33, 'Valaki igyekezik az ő életét megtartani, elveszti azt, és valaki elveszti azt, megeleveníti azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 34, 'Mondom néktek, azon az éjszakán ketten lesznek egy ágyban; az egyik felvétetik, és a másik elhagyatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 35, 'Két asszony őröl együtt; az egyik felvétetik, és a másik elhagyatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 36, 'Ketten lesznek a mezőn; az egyik felvétetik, és a másik elhagyatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 37, 'És felelvén, mondának néki: Hol, Uram? Ő pedig monda nékik: a hol a test, oda gyűlnek a saskeselyűk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 1, 'Monda pedig nékik példázatot is arról, hogy mindig imádkozni kell, és meg nem restülni;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 2, 'Mondván: Volt egy bíró egy városban, a ki Istent nem félt és embert nem becsült.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 3, 'Volt pedig abban a városban egy özvegyasszony, és elméne ahhoz, mondván: Állj bosszút értem az én ellenségemen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 4, 'Az pedig nem akará egy ideig; de azután monda ő magában: Jól lehet Istent nem félek és embert nem becsülök;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 5, 'Mindazáltal mivelhogy nékem terhemre van ez az özvegyasszony, megszabadítom őt, hogy szüntelen reám járván, ne gyötörjön engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 6, 'Monda pedig az Úr: Halljátok, mit mond e hamis bíró!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 7, 'Hát az Isten nem áll-é bosszút az ő választottaiért, kik ő hozzá kiáltanak éjjel és nappal, ha hosszútűrő is irántuk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 8, 'Mondom néktek, hogy bosszút áll értök hamar. Mindazáltal az embernek Fia mikor eljő, avagy talál-é hitet e földön?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 9, 'Némelyeknek pedig, kik elbizakodtak magukban, hogy ők igazak, és a többieket semmibe sem vették, ezt a példázatot is mondá:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 10, 'Két ember méne fel a templomba imádkozni; az egyik farizeus, és a másik vámszedő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 11, 'A farizeus megállván, ily módon imádkozék magában: Isten! hálákat adok néked, hogy nem vagyok olyan, mint egyéb emberek, ragadozók, hamisak, paráznák, vagy mint ím e vámszedő is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 12, 'Bőjtölök kétszer egy héten; dézsmát adok mindenből, a mit szerzek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 13, 'A vámszedő pedig távol állván, még szemeit sem akarja vala az égre emelni, hanem veri vala mellét, mondván: Isten, légy irgalmas nékem bűnösnek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 14, 'Mondom néktek, ez megigazulva méne alá az ő házához, inkább hogynem amaz: mert valaki felmagasztalja magát, megaláztatik; és a ki megalázza magát, felmagasztaltatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 15, 'Vivének pedig hozzá kis gyermekeket is, hogy illesse azokat; mikor pedig a tanítványok ezt látták, megdorgálák azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 16, 'De Jézus magához híván őket, monda: Engedjétek, hogy a kis gyermekek én hozzám jőjjenek, és ne tiltsátok el őket; mert ilyeneké az Istennek országa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 17, 'Bizony mondom néktek: A ki nem úgy fogadja az Isten országát, mint gyermek, semmiképen nem megy be abba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 18, 'És megkérdé őt egy főember, mondván: Jó Mester, mit cselekedjem, hogy az örökéletet elnyerhessem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 19, 'Monda pedig néki Jézus: Miért mondasz engem jónak? Nincs senki jó, csak egy, az Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 20, 'A parancsolatokat tudod: Ne paráználkodjál; ne ölj; ne lopj; hamis tanubizonyságot ne tégy; tiszteld atyádat és anyádat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 21, 'Az pedig monda: Mindezeket ifjúságomtól fogva megtartottam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 22, 'Jézus ezeket hallván, monda néki: Még egy fogyatkozás van benned: Add el mindenedet, a mid van, és oszd el a szegényeknek, és kincsed lesz mennyországban; és jer, kövess engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 23, 'Az pedig ezeket hallván, igen megszomorodék; mert igen gazdag vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 24, 'És mikor látta Jézus, hogy az igen megszomorodék, monda: Mily nehezen mennek be az Isten országába, a kiknek gazdagságuk van!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 25, 'Mert könnyebb a tevének a tű fokán átmenni, hogynem a gazdagnak az Isten országába bejutni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 26, 'A kik pedig ezt hallották, mondának: Ki idvezülhet tehát?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 27, 'Ő pedig monda: A mi embereknél lehetetlen, lehetséges az Istennél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 28, 'És monda Péter: Ímé mi mindent elhagytunk, és követtünk téged!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 29, 'Ő pedig monda nékik: Bizony mondom néktek, hogy senki sincs, a ki elhagyta házát, vagy szüleit, vagy testvéreit, vagy feleségét, vagy gyermekeit az Isten országáért,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 30, 'A ki sokszorta többet ne kapna ebben az időben, a jövendő világon pedig örök életet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 31, 'És maga mellé vévén a tizenkettőt, monda nékik: Ímé felmegyünk Jeruzsálembe, és beteljesedik minden az embernek Fián, a mit a próféták megírtak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 32, 'Mert a pogányok kezébe adatik, és megcsúfoltatik, és meggyaláztatik, és megköpdöstetik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 33, 'És megostorozván, megölik őt; és harmadnapon feltámad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 34, 'Ők pedig ezekből semmit nem értének; és a beszéd ő előlük el vala rejtve, és nem fogták fel a mondottakat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 35, 'Lőn pedig, mikor Jerikhóhoz közeledett, egy vak ül vala az út mellett koldulván.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 36, 'És mikor hallotta a mellette elmenő sokaságot, tudakozódék, mi dolog az?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 37, 'Megmondák pedig néki, hogy a Názáretbeli Jézus megy el arra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 38, 'És kiálta, mondván: Jézus, Dávidnak Fia, könyörülj rajtam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 39, 'A kik pedig elől mentek, dorgálák őt, hogy hallgasson; de ő annál inkább kiálta: Dávidnak Fia, könyörülj rajtam!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 40, 'És Jézus megállván, parancsolá, hogy vigyék azt hozzá; és mikor közel ért, megkérdé őt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 41, 'Mondván: Mit akarsz, hogy cselekedjem veled? Az pedig monda: Uram, hogy az én szemem világa megjőjjön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 42, 'És Jézus monda néki: Láss, a te hited téged megtartott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 43, 'És azonnal megjöve annak szeme világa, és követé őt, dicsőítvén az Istent az egész sokaság pedig ezt látván, dicsőséget ada az Istennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 1, 'És bemenvén, általméne Jerikhón.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 2, 'És ímé vala ott egy ember, a kit nevéről Zákeusnak hívtak; és az fővámszedő vala, és gazdag.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 3, 'És igyekezék Jézust látni, ki az; de a sokaságtól nem láthatá, mivelhogy termete szerint kis ember volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 4, 'És előre futván felhága egy eperfüge fára, hogy őt lássa; mert arra vala elmenendő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 5, 'És mikor arra a helyre jutott, feltekintvén Jézus, látá őt, és monda néki: Zákeus, hamar szállj alá; mert ma nékem a te házadnál kell maradnom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 6, 'És sietve leszálla, és örömmel fogadá őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 7, 'És mikor ezt látták, mindnyájan zúgolódának, mondván hogy: Bűnös emberhez ment be szállásra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 8, 'Zákeus pedig előállván, monda az Úrnak: Uram, ímé minden vagyonomnak felét a szegényeknek adom, és ha valakitől valamit patvarkodással elvettem, négy annyit adok helyébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 9, 'Monda pedig néki Jézus: Ma lett idvessége ennek a háznak! mivelhogy ő is Ábrahám fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 10, 'Mert azért jött az embernek Fia, hogy megkeresse és megtartsa, a mi elveszett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 11, 'És mikor azok ezeket hallották, folytatá és monda egy példázatot, mivelhogy közel vala Jeruzsálemhez, és azok azt gondolák, hogy azonnal megjelenik az Isten országa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 12, 'Monda azért: Egy nemes ember elméne messze tartományba, hogy országot vegyen magának, aztán visszatérjen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 13, 'Előszólítván azért tíz szolgáját, ada nékik tíz gírát, és monda nékik: Kereskedjetek, míg megjövök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 14, 'Az ő alattvalói pedig gyűlölék őt, és követséget küldének utána, mondván: Nem akarjuk, hogy ő uralkodjék mi rajtunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 15, 'És lőn, mikor megjött az ország vétele után, parancsolá, hogy az ő szolgáit, a kiknek a pénzt adta, hívják ő hozzá, hogy megtudja, ki mint kereskedett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 16, 'Eljöve pedig az első, mondván: Uram, a te gírád tíz gírát nyert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 17, 'Ő pedig monda néki: Jól vagyon jó szolgám; mivelhogy kevesen voltál hív, legyen birodalmad tíz városon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 18, 'És jöve a második, mondván: Uram, a te gírád öt gírát nyert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 19, 'Monda pedig ennek is: Néked is legyen birodalmad öt városon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 20, 'És jöve egy másik, mondván: Uram, imhol a te gírád, melyet egy keszkenőben eltéve tartottam;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 21, 'Mert féltem tőled, mivelhogy kemény ember vagy; elveszed a mit nem te tettél el, és aratod, a mit nem te vetettél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 22, 'Monda pedig annak: A te szádból ítéllek meg téged, gonosz szolga. Tudtad, hogy én kemény ember vagyok, ki elveszem, a mit nem én tettem el, és aratom, a mit nem én vetettem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 23, 'Miért nem adtad azért az én pénzemet a pénzváltók asztalára, és én megjövén, kamatostól kaptam volna azt vissza?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 24, 'És az ott állóknak monda: Vegyétek el ettől a gírát, és adjátok annak, a kinek tíz gírája van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 25, 'És mondának néki: Uram, tíz gírája van!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 26, 'És ő monda: Mert mondom néktek, hogy mindenkinek, a kinek van, adatik; a kinek pedig nincs, még a mije van is, elvétetik tőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 27, 'Sőt ennek felette amaz én ellenségeimet is, kik nem akarták, hogy én ő rajtok uralkodjam, hozzátok ide, és öljétek meg előttem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 28, 'És ezeket mondván, megy vala elől, felmenvén Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 29, 'És lőn, mikor közelgetett Béthfágéhoz és Bethániához, a hegyhez, mely Olajfák hegyének hívatik, elkülde kettőt az ő tanítványai közül,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 30, 'Mondván: Menjetek el az átellenben levő faluba; melybe bemenvén, találtok egy megkötött vemhet, melyen soha egy ember sem ült: eloldván azt, hozzátok ide.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 31, 'És ha valaki kérdez titeket: Miért oldjátok el? ezt mondjátok annak: Mert az Úrnak szüksége van reá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 32, 'És elmenvén a küldöttek, úgy találák, a mint nékik mondotta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 33, 'És mikor a vemhet eloldák, mondának nékik annak gazdái: Miért oldjátok el a vemhet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 34, 'Ők pedig mondának: Az Úrnak szüksége van reá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 35, 'Elvivék azért azt Jézushoz: és az ő felsőruháikat a vemhére vetvén, Jézust reá helyhezteték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 36, 'És mikor ő méne, az ő felsőruháikat az útra teríték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 37, 'Mikor pedig immár közelgete az Olajfák hegyének lejtőjéhez, a tanítványok egész sokasága örvendezve kezdé dicsérni az Istent fenszóval mindazokért a csodákért, a melyeket láttak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 38, 'Mondván: Áldott a Király, ki jő az Úrnak nevében! Békesség a mennyben, és dicsőség a magasságban!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 39, 'És némelyek a farizeusok közül a sokaságból mondának néki: Mester, dorgáld meg a te tanítványaidat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 40, 'És ő felelvén, monda nékik: Mondom néktek, hogyha ezek elhallgatnak, a kövek fognak kiáltani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 41, 'És mikor közeledett, látván a várost, síra azon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 42, 'Mondván: Vajha megismerted volna te is, csak e te mostani napodon is, a mik néked a te békességedre valók! de most elrejtettek a te szemeid elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 43, 'Mert jőnek reád napok, mikor a te ellenségeid te körülted palánkot építenek, és körülvesznek téged, és mindenfelől megszorítanak téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 44, 'És a földre tipornak téged, és a te fiaidat te benned; és nem hagynak te benned követ kövön; mivelhogy nem ismerted meg a te meglátogatásodnak idejét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 45, 'És bemenvén a templomba, kezdé kiűzni azokat, a kik adnak és vesznek vala abban,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 46, 'Mondván nékik: Meg van írva: Az én házam imádságnak háza; ti pedig azt latroknak barlangjává tettétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 47, 'És tanít vala minden nap a templomban. A főpapok pedig és az írástudók és a nép előkelői igyekeznek vala őt elveszteni:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 48, 'És nem találták el, mit cselekedjenek; mert az egész nép ő rajta függ vala, reá hallgatván.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 1, 'És lőn azok közül a napok közül egyen, mikor ő a népet tanítá a templomban, és és az evangyéliomot hirdeté, előállának a főpapok és az írástudók a vénekkel egybe,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 2, 'És mondának néki, így szólván: Mondd meg nékünk, micsoda hatalommal cselekszed ezeket? vagy ki az, a ki néked ezt a hatalmat adta?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 3, 'Felelvén pedig, monda nékik: Én is kérdek egy dolgot tőletek; mondjátok meg azért nékem:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 4, 'A János keresztsége mennyből vala-é, vagy emberektől?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 5, 'Azok pedig tanakodának magok közt, mondván: Ha ezt mondjuk: Mennyből; azt fogja mondani: Miért nem hittetek tehát néki?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 6, 'Ha pedig ezt mondjuk: Emberektől; az egész nép megkövez minket: mert meg van győződve, hogy János próféta volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 7, 'Felelének azért, hogy ők nem tudják, honnét vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 8, 'És Jézus monda nékik: Én sem mondom meg néktek, micsoda hatalommal cselekszem ezeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 9, 'És kezdé a népnek e példázatot mondani: Egy ember plántála szőlőt, és kiadá azt munkásoknak, és hosszú időre elutazék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 10, 'És annak idején elküldé szolgáját a munkásokhoz, hogy adjanak néki a szőlő gyümölcséből; a munkások pedig azt megvervén, üresen bocsáták el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 11, 'És még másik szolgát is külde; de azok azt is megvervén és meggyalázván, üresen bocsáták el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 12, 'És még harmadikat is külde; de azok azt is megsebesítvén, kiveték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 13, 'Monda azért a szőlőnek ura: Mit cselekedjem? Elküldöm az én szerelmes fiamat: talán azt, ha látják, megbecsülik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 14, 'De mikor azt látták a munkások, tanakodának egymás közt, mondván: Ez az örökös; jertek, öljük meg őt, hogy a miénk legyen az örökség!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 15, 'És kivetvén őt a szőlőből, megölék. Mit cselekszik azért a szőlőnek ura azokkal?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 16, 'Elmegy és elveszti azokat a munkásokat, és a szőlőt másoknak adja. És mikor ezt hallották, mondának: Távol legyen az!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 17, 'Ő pedig reájok tekintvén, monda: Mi az tehát, a mi meg van írva: A mely követ az építők megvetettek, az lett a szegelet fejévé?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 18, 'Valaki erre a kőre esik, szétzúzatik; a kire pedig ez esik reá, szétmorzsolja azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 19, 'És igyekeznek vala a főpapok és az írástudók kezeiket ő reá vetni azon órában; de félének a néptől; mert megérték, hogy ő ellenök mondta e példázatot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 20, 'Annakokáért vigyázván ő reá, leselkedőket küldének ki, a kik igazaknak tetteték magokat, hogy őt megfogják beszédében; hogy átadják a felsőbbségnek és a helytartó hatalmának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 21, 'Kik megkérdezék őt, mondván: Mester, tudjuk, hogy te helyesen beszélsz és tanítasz, és személyt nem válogatsz, hanem az Istennek útját igazán tanítod:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 22, 'Szabad-é nékünk adót fizetnünk a császárnak, vagy nem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 23, 'Ő pedig észrevévén álnokságukat, monda nékik: Mit kísértetek engem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 24, 'Mutassatok nékem egy pénzt; kinek a képe és felirata van rajta? És felelvén, mondának: A császáré.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 25, 'Ő pedig monda nékik: Adjátok meg azért a mi a császáré, a császárnak, és a mi az Istené, az Istennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 26, 'És nem tudták őt megfogni beszédében a nép előtt; és csodálkozván az ő feleletén, elhallgatának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 27, 'Hozzá menvén pedig a sadduczeusok közül némelyek, a kik tagadják, hogy van feltámadás, megkérdék őt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 28, 'Mondván: Mester, Mózes megírta nékünk, ha valakinek testvére meghal, kinek felesége volt, és magzatok nélkül hal meg, hogy annak testvére elvegye annak feleségét, és támasszon magot az ő testvérének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 29, 'Hét testvér vala azért: és az első feleséget vévén, meghalt magzatok nélkül;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 30, 'A másik vevé el azért annak feleségét, és az is magzatok nélkül halt meg;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 31, 'Akkor a harmadik vette el azt; és hasonlóképen mind a heten is; és nem hagytak magot, és meghaltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 32, 'Mind ezek után pedig meghalt az asszony is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 33, 'A feltámadáskor azért kinek a felesége lesz közülök? mert mind a hétnek felesége volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 34, 'És felelvén, monda nékik Jézus: E világnak fiai házasodnak és férjhez adatnak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 35, 'De a kik méltókká tétetnek, hogy ama világot elvegyék, és a halálból való feltámadást, sem nem házasodnak, sem férjhez nem adatnak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 36, 'Mert meg sem halhatnak többé: mert hasonlók az angyalokhoz; és az Isten fiai, mivelhogy a feltámadásnak fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 37, 'Hogy pedig a halottak feltámadnak, Mózes is megjelentette a csipkebokornál, mikor az Urat Ábrahám Istenének és Izsák Istenének és Jákób Istenének mondja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 38, 'Az Isten pedig nem a holtaknak, hanem az élőknek Istene: mert mindenek élnek ő néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 39, 'Felelvén pedig némelyek az írástudók közül, mondának: Mester, jól mondád!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 40, 'És többé semmit sem mertek tőle kérdezni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 41, 'Monda pedig nékik: Mimódon mondják, hogy a Krisztus Dávidnak fia?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 42, 'Holott maga Dávid mondja a zsoltárok könyvében: Monda az Úr az én Uramnak, ülj az én jobbkezem felől,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 43, 'Míglen vetem a te ellenségeidet a te lábaid alá zsámolyul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 44, 'Dávid azért Urának mondja őt, mimódon fia tehát néki?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 45, 'És az egész nép hallására monda az ő tanítványainak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 46, 'Oltalmazzátok meg magatokat az írástudóktól, kik hosszú köntösökben akarnak járni, és szeretik a piaczokon való köszöntéseket, és a gyülekezetekben az első űlést, és a lakomákon a főhelyeket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 47, 'Kik az özvegyeknek házát felemésztik, és színből hosszan imádkoznak; ezek súlyosabb ítélet alá esnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 1, 'És mikor feltekintett, látá, hogy a gazdagok hányják az ő ajándékaikat a perselybe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 2, 'Láta pedig egy szegény özvegy asszonyt is, hogy abba két fillért vete.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 3, 'És monda: Igazán mondom néktek, hogy e szegény özvegy mindenkinél többet vete:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 4, 'Mert mind ezek az ő fölöslegükből vetettek Istennek az ajándékokhoz: ez pedig az ő szegénységéből minden vagyonát, a mije volt, oda veté.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 5, 'És mikor némelyek mondának a templom felől, hogy szép kövekkel és ajándékokkal van felékesítve, monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 6, 'Ezekből, a miket láttok, jőnek napok, melyekben kő kövön nem marad, mely le nem romboltatnék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 7, 'Megkérdék pedig őt, mondván: Mester, mikor lesznek azért ezek? és mi lesz a jel, mikor mind ezek meglesznek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 8, 'Ő pedig monda: Meglássátok, hogy el ne hitessenek benneteket: mert sokan jőnek el az én nevemben, kik ezt mondják: Én vagyok; és: Az idő elközelgett; ne menjetek azért utánok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 9, 'És mikor hallotok háborúkról és zendülésekről, meg ne félemljetek; mert ezeknek meg kell lenni előbb, de nem jő mindjárt a vég.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 10, 'Akkor monda nékik: Nemzet nemzet ellen támad, és ország ország ellen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 11, 'És minden felé nagy földindulások lesznek, és éhségek és döghalálok; és rettegtetések és nagy jelek lesznek az égből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 12, 'De mind ezeknek előtte kezeiket reátok vetik, és üldöznek titeket, adván a gyülekezetek elé, és tömlöczökbe és királyok és helytartók elé visznek az én nevemért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 13, 'De ebből néktek lesz tanúbizonyságotok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 14, 'Tökéljétek el azért a ti szívetekben, hogy nem gondoskodtok előre, hogy mit feleljetek védelmetekre:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 15, 'Mert én adok néktek szájat és bölcseséget, melynek ellene nem szólhatnak, sem ellene nem állhatnak mind azok, a kik magokat ellenetekbe vetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 16, 'Elárulnak pedig titeket szülők és testvérek is, rokonok és barátok is; és megölnek némelyeket ti közületek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 17, 'És gyűlöletesek lesztek mindenki előtt az én nevemért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 18, 'De fejeteknek egy hajszála sem vész el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 19, 'A ti béketűréstek által nyeritek meg lelketeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 20, 'Mikor pedig látjátok Jeruzsálemet hadseregektől körülvéve, akkor tudjátok meg, hogy elközelgett az ő elpusztulása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 21, 'Akkor a kik Júdeában lesznek, fussanak a hegyekre; és a kik annak közepette, menjenek ki abból; és a kik a mezőben, ne menjenek be abba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 22, 'Mert azok a bosszúállásnak napjai, hogy beteljesedjenek mind azok, a mik megírattak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 23, 'Jaj pedig a terhes és szoptató asszonyoknak azokban a napokban; mert nagy szükség lesz e földön, és harag e népen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 24, 'És elhullanak fegyvernek éle által, és fogva vitetnek minden pogányok közé; és Jeruzsálem megtapodtatik a pogányoktól, míglen betelik a pogányok ideje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 25, 'És lesznek jelek a napban, holdban és csillagokban; és a földön pogányok szorongása a kétség miatt, mikor a tenger és a hab zúgni fog,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 26, 'Mikor az emberek elhalnak a félelem miatt és azoknak várása miatt, a mik e föld kerekségére következnek: mert az egek erősségei megrendülnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 27, 'És akkor meglátják az embernek Fiát eljőni a felhőben, hatalommal és nagy dicsőséggel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 28, 'Mikor pedig ezek kezdenek meglenni, nézzetek fel és emeljétek fel a ti fejeteket; mert elközelget a ti váltságtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 29, 'Monda pedig nékik egy példázatot: Tekintsétek meg a fügefát és minden fákat:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 30, 'Mikor immár hajtanak, és ezt látjátok, ti magatoktól tudjátok, hogy már közel van a nyár.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 31, 'Ezenképen ti is, mikor látjátok, hogy ezek meglesznek, tudjátok meg, hogy közel van az Isten országa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 32, 'Bizony mondom néktek, hogy e nemzetség el nem múlik, mígnem mind ezek meglesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 33, 'Az ég és a föld elmúlnak, de az én beszédeim semmiképen el nem múlnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 34, 'De vigyázzatok magatokra, hogy valamikor meg ne nehezedjék a ti szívetek dobzódásnak, részegségnek és ez élet gondjainak miatta, és váratlanul reátok ne jőjjön az a nap:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 35, 'Mert mintegy tőr, úgy lep meg mindeneket, a kik az egész föld színén lakoznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 36, 'Vigyázzatok azért minden időben, kérvén, hogy méltókká tétessetek arra, hogy elkerüljétek mindezeket, a mik bekövetkeznek, és megállhassatok az embernek Fia előtt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 37, 'Tanít vala pedig naponta a templomban; éjszakára pedig kimenvén, a hegyen vala, mely Olajfák hegyének neveztetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 38, 'És kora reggel hozzá megy vala az egész nép, hogy őt hallgassa a templomban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 1, 'Elközelgetett pedig a kovásztalan kenyerek ünnepe, mely husvétnak mondatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 2, 'És a főpapok és az írástudók keresnek vala módot, hogyan öljék meg őt; mert féltek a néptől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 3, 'Beméne pedig a Sátán Júdásba, ki Iskáriótesnek neveztetik, és a tizenkettőnek számából vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 4, 'És elmenvén, megbeszélé a főpapokkal és a vezérekkel, mimódon adja őt nékik kezökbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 5, 'És azok örülének, és megszerződének, hogy pénzt adnak néki;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 6, 'Ő pedig megigéré, és keres vala jó alkalmat, hogy őt nékik kezökbe adja zenebona nélkül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 7, 'Eljöve pedig a kovásztalan kenyerek napja, melyen meg kelle öletni a husvéti báránynak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 8, 'És elküldé Pétert és Jánost, mondván: Elmenvén, készítsétek el nékünk a husvéti bárányt, hogy megegyük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 9, 'Ők pedig mondának néki: Hol akarod, hogy elkészítsük?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 10, 'És ő monda nékik: Ímé, mikor bementek a városba, szembe jő veletek egy ember, ki egy korsó vizet visz; kövessétek őt abba a házba, a melybe bemegy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 11, 'És mondjátok a ház gazdájának: Ezt mondja néked a Mester: Hol van az a szállás, a hol megeszem az én tanítványaimmal a husvéti bárányt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 12, 'És ő mutat néktek egy nagy vacsoráló helyet, berendezve, ott készítsétek el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 13, 'Elmenvén pedig, úgy találák, a mint mondta nékik; és elkészíték a húsvéti bárányt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 14, 'És mikor eljött az idő, asztalhoz üle, és a tizenkét apostol ő vele egyetembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 15, 'És monda nékik: Kívánva kívántam a husvéti bárányt megenni veletek, melőtt én szenvednék:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 16, 'Mert mondom néktek, hogy többé nem eszem abból, míglen beteljesedik az Isten országában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 17, 'És a pohárt vévén, minekutána hálákat adott, monda: Vegyétek ezt, és osszátok el magatok között:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 18, 'Mert mondom néktek, hogy nem iszom a szőlőtőkének gyümölcséből, míglen eljő az Isten országa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 19, 'És minekutána a kenyeret vette, hálákat adván megszegé, és adá nékik, mondván: Ez az én testem, mely ti érettetek adatik: ezt cselekedjétek az én emlékezetemre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 20, 'Hasonlóképen a pohárt is, minekutána vacsorált, ezt mondván: E pohár amaz új szövetség az én véremben, mely ti érettetek kiontatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 21, 'De ímé annak a keze, a ki engem elárul, velem van az asztalon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 22, 'És az embernek Fia jóllehet, elmegy, mint elvégeztetett: de jaj annak az embernek, a ki által elárultatik!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 23, 'És ők kezdék egymás között kérdezni, vajjon ki lehet az ő közöttük, a ki ezt meg fogja tenni?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 24, 'Támada pedig köztük versengés is, hogy ki tekinthető köztük nagyobbnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 25, 'Ő pedig monda nékik: A pogányokon uralkodnak az ő királyaik, és a kiknek azokon hatalmuk van, jóltévőknek hivatnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 26, 'De ti nem úgy: hanem a ki legnagyobb köztetek, olyan legyen, mint a ki legkisebb; és a ki fő, mint a ki szolgál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 27, 'Mert melyik nagyobb, az-é, a ki asztalnál ül, vagy a ki szolgál? nemde a ki asztalnál ül? De én ti köztetek olyan vagyok, mint a ki szolgál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 28, 'Ti vagytok pedig azok, kik megmaradtatok én velem az én kísérteteimben;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 29, 'Én azért adok néktek, miképen az én Atyám adott nékem, országot,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 30, 'Hogy egyetek és igyatok az én asztalomon az én országomban, és üljetek királyi székeken, ítélvén az Izráelnek tizenkét nemzetségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 31, 'Monda pedig az Úr: Simon! Simon! ímé a Sátán kikért titeket, hogy megrostáljon, mint a búzát;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 32, 'De én imádkoztam érted, hogy el ne fogyatkozzék a te hited: te azért idővel megtérvén, a te atyádfiait erősítsed.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 33, 'Ő pedig monda néki: Uram, te veled kész vagyok mind tömlöczre, mind halálra menni!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 34, 'És ő monda: Mondom néked Péter: Ma nem szól addig a kakas, míg te háromszor meg nem tagadod, hogy ismersz engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 35, 'És monda nékik: Mikor elküldtelek benneteket erszény, táska és saru nélkül, volt-é valamiben fogyatkozástok? Ők pedig mondának: Semmiben sem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 36, 'Monda azért nékik: De most, a kinek erszénye van elővegye, hasonlóképen a táskát; és a kinek nincs, adja el felső ruháját, és vegyen szablyát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 37, 'Mert mondom néktek, hogy még ennek az írásnak be kell teljesülni rajtam, hogy: És a gonoszok közé számláltatott. Mert a mik reám vonatkoznak is, elvégeztetnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 38, 'Azok pedig mondának: Uram, ímé van itt két szablya. Ő pedig monda: Elég.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 39, 'És kimenvén, méne az ő szokása szerint az Olajfák hegyére; követék pedig őt az ő tanítványai is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 40, 'És mikor ott a helyen vala, monda nékik: Imádkozzatok, hogy kísértetbe ne essetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 41, 'És ő eltávozék tőlök mintegy kőhajításnyira; és térdre esvén, imádkozék,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 42, 'Mondván: Atyám, ha akarod, távoztasd el tőlem e pohárt; mindazáltal ne az én akaratom, hanem a tiéd legyen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 43, 'És angyal jelenék meg néki mennyből, erősítvén őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 44, 'És haláltusában lévén, buzgóságosabban imádkozék; és az ő verítéke olyan vala, mint a nagy vércseppek, melyek a földre hullanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 45, 'És minekutána fölkelt az imádkozástól, az ő tanítványaihoz menvén, aludva találá őket a szomorúság miatt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 46, 'És monda nékik: Mit alusztok? Keljetek fel és imádkozzatok, hogy kísértetbe ne essetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 47, 'És mikor még beszéle, ímé sokaság jöve, melynek az méne előtte, a ki Júdásnak neveztetik, egy a tizenkettő közül: és közelgete Jézushoz, hogy őt megcsókolja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 48, 'Jézus pedig monda néki: Júdás, csókkal árulod el az embernek Fiát?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 49, 'Látván pedig azok, a kik ő körülötte valának, a mi következik, mondának néki: Uram, vágjuk-é őket fegyverrel?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 50, 'És közülök valaki megvágá a főpap szolgáját, és levágá annak jobb fülét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 51, 'Felelvén pedig Jézus, monda: Elég eddig. És illetvén annak fülét, meggyógyítá azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 52, 'Monda pedig Jézus azoknak, a kik ő hozzá mentek, a főpapoknak, a templom tisztjeinek és a véneknek: Mint valami latorra, úgy jöttetek szablyákkal és fustélyokkal?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 53, 'Mikor minden nap veletek voltam a templomban, a ti kezeiteket nem vetétek én reám; de ez a ti órátok, és a sötétségnek hatalma.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 54, 'Megfogván azért őt, elvezeték, és elvivék a főpap házába. Péter pedig követi vala távol.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 55, 'És mikor tüzet gerjesztettek az udvar közepén, és ők együtt leültek, Péter is leüle ő velök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 56, 'És meglátván őt egy szolgálóleány, a mint a világosságnál ült, szemeit reá vetvén, monda: Ez is ő vele vala!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 57, 'Ő pedig megtagadá őt, mondván: Asszony, nem ismerem őt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 58, 'És egy kevéssel azután más látván őt, monda: Te is azok közül való vagy! Péter pedig monda: Ember, nem vagyok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 59, 'És úgy egy óra mulva más valaki erősíté, mondván: Bizony ez is vele vala: mert Galileából való is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 60, 'Monda pedig Péter: Ember, nem tudom, mit mondasz! És azonnal, mikor ő még beszélt, megszólalt a kakas.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 61, 'És hátra fordulván az Úr, tekinte Péterre. És megemlékezék Péter az Úr szaváról, a mint néki mondta: Mielőtt a kakas szól, háromszor megtagadsz engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 62, 'És kimenvén Péter, keservesen síra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 63, 'És azok a férfiak, a kik fogva tarták Jézust, csúfolják vala, vervén őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 64, 'És szemeit betakarván, arczul csapdosák őt, és kérdezék őt, mondván: Prófétáld meg ki az, a ki téged vere?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 65, 'És sok egyéb dolgot mondának néki, szidalmazván őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 66, 'És a mint nappal lett, egybegyűle a nép véneinek tanácsa, főpapok és írástudók: és vivék őt az ő gyülekezetükbe,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 67, 'Mondván: Ha te vagy a Krisztus, mondd meg nékünk. Monda pedig nékik: Ha mondom néktek, nem hiszitek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 68, 'De ha kérdezlek is, nem feleltek nékem, sem el nem bocsátotok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 69, 'Mostantól fogva ül az embernek Fia az Isten hatalmának jobbja felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 70, 'Mondának pedig mindnyájan: Te vagy tehát az Isten Fia? Ő pedig monda nékik: Ti mondjátok, hogy én vagyok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 71, 'Azok pedig mondának: Mi szükségünk van még bizonyságra? Hiszen mi magunk hallottuk az ő szájából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 1, 'És fölkelvén az ő egész sokaságuk, vivék őt Pilátushoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 2, 'És kezdék őt vádolni, mondván: Úgy találtuk, hogy ez a népet félrevezeti, és tiltja a császár adójának fizetését, mivelhogy ő magát ama király Krisztusnak mondja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 3, 'Pilátus pedig megkérdé őt, mondván: Te vagy-é a zsidók királya? És ő felelvén néki, monda: Te mondod!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 4, 'Monda pedig Pilátus a főpapoknak és a sokaságnak: Semmi bűnt nem találok ez emberben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 5, 'De azok erősködének, mondván: A népet felzendíti, tanítván az egész Júdeában, elkezdve Galileától mind idáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 6, 'Pilátus pedig Galileát hallván, megkérdé, vajjon galileai ember-é ő?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 7, 'És mikor megtudta, hogy ő a Héródes hatósága alá tartozik, Héródeshez küldé őt, mivelhogy az is Jeruzsálemben vala azokban a napokban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 8, 'Héródes pedig Jézust látván igen megörüle: mert sok időtől fogva kívánta őt látni, mivelhogy sokat hallott ő felőle, és reménylé, hogy majd valami csodát lát, melyet ő tesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 9, 'Kérdezé pedig őt sok beszéddel; de ő semmit nem felele néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 10, 'Ott állanak vala pedig a főpapok és az írástudók, teljes igyekezettel vádolván őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 11, 'Héródes pedig az ő katonáival egybe semminek állítván és kicsúfolván őt, minekutána felöltöztette fényes ruhába, visszaküldé Pilátushoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 12, 'És az napon lőnek barátok egymással Pilátus és Héródes; mert az előtt ellenségeskedésben valának egymással.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 13, 'Pilátus pedig a főpapokat, főembereket és a népet egybegyűjtvén,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 14, 'Monda nékik: Ide hoztátok nékem ez embert, mint a ki a népet félrevezeti: és ímé én ti előttetek kivallatván, semmi olyan bűnt nem találtam ez emberben, a mivel őt vádoljátok:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 15, 'De még Héródes sem; mert titeket ő hozzá igazítálak; és ímé semmi halálra való dolgot nem cselekedett ő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 16, 'Megfenyítvén azért őt, elbocsátom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 17, 'Kell vala pedig elbocsátania nékik ünnepenként egy foglyot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 18, 'De felkiálta az egész sokaság, mondván: Vidd el ezt, és bocsásd el nékünk Barabbást!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 19, 'Ki a városban lett valami lázadásért és gyilkosságért vettetett a tömlöczbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 20, 'Pilátus azért ismét felszólala, el akarván bocsátani Jézust;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 21, 'De azok ellene kiáltának, mondván: Feszítsd meg! Feszítsd meg őt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 22, 'Ő pedig harmadszor is monda nékik: Mert mi gonoszt tett ez? Semmi halálra való bűnt nem találtam ő benne; megfenyítvén azért őt, elbocsátom!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 23, 'Azok pedig nagy fenszóval sürgeték, kérvén, hogy megfeszíttessék; és az ő szavok és a főpapoké erőt vesz vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 24, 'És Pilátus megítélé, hogy meglegyen, a mit kérnek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 25, 'És elbocsátá nékik azt, a ki lázadásért és gyilkosságért vettetett a tömlöczbe, a kit kértek vala; Jézust pedig kiszolgáltatá az ő akaratuknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 26, 'Mikor azért elvivék őt, egy Czirénebeli Simont megragadván, ki a mezőről jöve, arra tevék a keresztfát, hogy vigye Jézus után.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 27, 'Követé pedig őt a népnek és az asszonyoknak nagy sokasága, a kik gyászolák és siraták őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 28, 'Jézus pedig hozzájok fordulván, monda: Jeruzsálem leányai, ne sírjatok én rajtam, hanem ti magatokon sírjatok, és a ti magzataitokon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 29, 'Mert ímé jőnek napok, melyeken ezt mondják: Boldogok a meddők, és a mely méhek nem szültek, és az emlők, melyek nem szoptattak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 30, 'Akkor kezdik mondani a hegyeknek: Essetek mi reánk; és a halmoknak: Borítsatok el minket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 31, 'Mert ha a zöldelő fán ezt mívelik, mi esik a száraz fán?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 32, 'Vivének pedig két másikat is, két gonosztevőt ő vele, hogy megölessenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 33, 'Mikor pedig elmenének a helyre, mely Koponya helyének mondatik, ott megfeszíték őt és a gonosztevőket, egyiket jobbkéz felől, a másikat balkéz felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 34, 'Jézus pedig monda: Atyám! bocsásd meg nékik; mert nem tudják mit cselekesznek. Elosztván pedig az ő ruháit, vetének reájok sorsot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 35, 'És a nép megálla nézni. Csúfolák pedig őt a főemberek is azokkal egybe, mondván: Egyebeket megtartott, tartsa meg magát, ha ő a Krisztus, az Istennek ama választottja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 36, 'Csúfolák pedig őt a vitézek is, odajárulván és eczettel kínálván őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 37, 'És ezt mondván néki: Ha te vagy a zsidóknak ama Királya, szabadítsd meg magadat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 38, 'Vala pedig egy felirat is fölébe írva görög, római és zsidó betűkkel: Ez a zsidóknak ama Királya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 39, 'A felfüggesztett gonosztevők közül pedig az egyik szidalmazá őt, mondván: Ha te vagy a Krisztus, szabadítsd meg magadat, minket is!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 40, 'Felelvén pedig a másik, megdorgálá őt, mondván: Az Istent sem féled-e te? Hiszen te ugyanazon ítélet alatt vagy!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 41, 'És mi ugyan méltán; mert a mi cselekedetünknek méltó büntetését vesszük: ez pedig semmi méltatlan dolgot nem cselekedett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 42, 'És monda Jézusnak: Uram, emlékezzél meg én rólam, mikor eljősz a te országodban!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 43, 'És monda néki Jézus: Bizony mondom néked: Ma velem leszel a paradicsomban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 44, 'Vala pedig mintegy hat óra, és sötétség lőn az egész tartományban mind kilencz órakorig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 45, 'És meghomályosodék a nap, és a templom kárpitja középen ketté hasada.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 46, 'És kiáltván Jézus nagy szóval, monda: Atyám, a te kezeidbe teszem le az én lelkemet. És ezeket mondván, meghala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 47, 'Látván pedig a százados, a mi történt, dicsőíté az Istent, mondván: Bizony ez ember igaz vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 48, 'És az egész sokaság, mely e dolognak látására ment oda, látván azokat, a mik történtek, mellét verve megtére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 49, 'Az ő ismerősei pedig mind, és az asszonyok, a kik Galileából követék őt, távol állának, nézvén ezeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 50, 'És ímé egy ember, kinek József vala neve, tanácsbeli, jó és igaz férfiú,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 51, 'Ki nem vala részes azoknak tanácsában és cselekedetében, Arimathiából, a zsidók városából való, ki maga is várja vala az Istennek országát;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 52, 'Ez oda menvén Pilátushoz, elkéré a Jézus testét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 53, 'És levévén azt, begöngyölé azt gyolcsba, és helyhezteté azt egy sziklába vágott sírboltba, melyben még senki sem feküdt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 54, 'És az a nap péntek vala, és szombat virrada rá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 55, 'Az őt követő asszonyok is pedig, kik vele Galileából jöttek, megnézék a sírt, és hogy miképen helyeztetett el az ő teste.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 56, 'Visszatérvén pedig, készítének fűszerszámokat és keneteket. És szombaton nyugovának a parancsolat szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 1, 'A hétnek első napján pedig kora reggel a sírhoz menének, vivén az elkészített fűszerszámokat, és némely más asszonyok is velök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 2, 'És a követ a sírról elhengerítve találák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 3, 'És mikor bementek, nem találák az Úr Jézus testét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 4, 'És lőn, hogy mikor ők e felett megdöbbenének, ímé két férfiú álla melléjök fényes öltözetben:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 5, 'És mikor ők megrémülvén a földre hajták orczájokat, azok mondának nékik: Mit keresitek a holtak között az élőt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 6, 'Nincs itt, hanem feltámadott: emlékezzetek rá, mint beszélt néktek, még mikor Galileában volt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 7, 'Mondván: Szükség az ember Fiának átadatni a bűnös emberek kezébe, és megfeszíttetni, és harmadnapon feltámadni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 8, 'Megemlékezének azért az ő szavairól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 9, 'És visszatérvén a sírtól, elmondák mindezeket a tizenegynek, és mind a többieknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 10, 'Valának pedig Mária Magdaléna, és Johanna, és a Jakab anyja Mária, és egyéb asszonyok ő velök, a kik ezeket mondák az apostoloknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 11, 'De az ő szavuk csak üres beszédnek látszék azok előtt; és nem hivének nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 12, 'Péter azonban felkelvén elfuta a sírhoz, és behajolván látá, hogy csak a lepedők vannak ott; és elméne, magában csodálkozván e dolgon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 13, 'És ímé azok közül ketten mennek vala ugyanazon a napon egy faluba, mely Jeruzsálemtől hatvan futamatnyira vala, melynek neve vala Emmaus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 14, 'És beszélgetének magok közt mindazokról, a mik történtek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 15, 'És lőn, hogy a mint beszélgetének és egymástól kérdezősködének, maga Jézus hozzájok menvén, velök együtt megy vala az úton.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 16, 'De az ő szemeik visszatartóztatának, hogy őt meg ne ismerjék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 17, 'Monda pedig nékik: Micsoda szavak ezek, a melyeket egymással váltotok jártotokban? és miért vagytok szomorú ábrázattal?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 18, 'Felelvén pedig az egyik, kinek neve Kleofás, monda néki: Csak te vagy-é jövevény Jeruzsálemben, és nem tudod minémű dolgok lettek abban e napokon?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 19, 'És monda nékik: Micsoda dolgok? Azok pedig mondának néki: A melyek esének a Názáretbeli Jézuson, ki próféta vala, cselekedetben és beszédben hatalmas Isten előtt és az egész nép előtt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 20, 'És mimódon adák őt a főpapok és a mi főembereink halálos ítéletre, és megfeszíték őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 21, 'Pedig mi azt reméltük, hogy ő az, a ki meg fogja váltani az Izráelt. De mindezek mellett ma van harmadnapja, hogy ezek lettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 22, 'Hanem valami közülünk való asszonyok is megdöbbentettek minket, kik jó reggel a sírnál valának;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 23, 'És mikor nem találták az ő testét, haza jöttek, mondván, hogy angyalok jelenését is látták, kik azt mondják, hogy ő él.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 24, 'És azok közül némelyek, kik velünk valának, elmenének a sírhoz, és úgy találák, a mint az asszonyok is mondták; őt pedig nem látták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 25, 'És ő monda nékik: Óh balgatagok és rest szívűek mindazoknak elhivésére, a miket a próféták szóltak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 26, 'Avagy nem ezeket kellett-é szenvedni a Krisztusnak, és úgy menni be az ő dicsőségébe?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 27, 'És elkezdvén Mózestől és minden prófétáktól fogva, magyarázza vala nékik minden írásokban, a mik ő felőle megirattak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 28, 'Elközelítének pedig a faluhoz, a melybe mennek vala; és ő úgy tőn, mintha tovább menne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 29, 'De kényszeríték őt, mondván: Maradj velünk, mert immár beestvéledik, és a nap lehanyatlott! Beméne azért, hogy velök maradjon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 30, 'És lőn, mikor leült velök, a kenyeret vévén, megáldá, és megszegvén, nékik adá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 31, 'És megnyilatkozának az ő szemeik, és megismerék őt; de ő eltünt előlük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 32, 'És mondának egymásnak: Avagy nem gerjedezett-é a mi szívünk mi bennünk, mikor nékünk szóla az úton, és mikor magyarázá nékünk az írásokat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 33, 'És felkelvén azon órában, visszatérének Jeruzsálembe, és egybegyűlve találák a tizenegyet és azokat, a kik velök valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 34, 'Kik ezt mondják vala: Feltámadott az Úr bizonynyal, és megjelent Simonnak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 35, 'És ezek is elbeszélék, mi történt az úton, és miképen ismerték meg ők a kenyér megszegéséről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 36, 'És mikor ezeket beszélék, megálla maga Jézus ő közöttök, és monda nékik: Békesség néktek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 37, 'Megrémülvén pedig és félvén, azt hivék, hogy valami lelket látnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 38, 'És monda nékik: Miért háborodtatok meg, és miért támadnak szívetekben okoskodások?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 39, 'Lássátok meg az én kezeimet és lábaimat, hogy én magam vagyok: tapogassatok meg engem, és lássatok; mert a léleknek nincs húsa és csontja, a mint látjátok, hogy nékem van!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 40, 'És ezeket mondván, megmutatá nékik kezeit és lábait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 41, 'Mikor pedig még nem hívék az öröm miatt, és csodálkozának, monda nékik: Van-é itt valami enni valótok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 42, 'Ők pedig adának néki egy darab sült halat, és valami lépesmézet,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 43, 'Melyeket elvőn, és előttök evék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 44, 'És monda nékik: Ezek azok a beszédek, melyeket szóltam néktek, mikor még veletek valék, hogy szükség beteljesedni mindazoknak, a mik megirattak a Mózes törvényében, a prófétáknál és a zsoltárokban én felőlem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 45, 'Akkor megnyilatkoztatá az ő elméjöket, hogy értsék az írásokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 46, 'És monda nékik: Így van megírva, és így kellett szenvedni a Krisztusnak, és feltámadni a halálból harmadnapon:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 47, 'És prédikáltatni az ő nevében a megtérésnek és a bűnök bocsánatának minden pogányok között, Jeruzsálemtől elkezdve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 48, 'Ti vagytok pedig ezeknek bizonyságai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 49, 'És ímé én elküldöm ti reátok az én Atyámnak ígéretét; ti pedig maradjatok Jeruzsálem városában, mígnem felruháztattok mennyei erővel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 50, 'Kivivé pedig őket Bethániáig; és felemelvén az ő kezeit, megáldá őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 51, 'És lőn, hogy míg áldá őket, tőlök elszakadván, felviteték a mennybe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 52, 'Ők pedig imádván őt, visszatérének nagy örömmel Jeruzsálembe;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 53, 'És mindenkor a templomban valának, dícsérvén és áldván az Istent. Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'Kezdetben vala az Íge, és az Íge vala az Istennél, és Isten vala az Íge.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'Ez kezdetben az Istennél vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'Minden ő általa lett és nála nélkül semmi sem lett, a mi lett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'Ő benne vala az élet, és az élet vala az emberek világossága;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'És a világosság a sötétségben fénylik, de a sötétség nem fogadta be azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'Vala egy Istentől küldött ember, kinek neve János.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'Ez jött tanúbizonyságul, hogy bizonyságot tegyen a világosságról, hogy mindenki higyjen ő általa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'Nem ő vala a világosság, hanem jött, hogy bizonyságot tegyen a világosságról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'Az igazi világosság eljött volt már a világba, a mely megvilágosít minden embert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'A világban volt és a világ általa lett, de a világ nem ismerte meg őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'Az övéi közé jöve, és az övéi nem fogadák be őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'Valakik pedig befogadák őt, hatalmat ada azoknak, hogy Isten fiaivá legyenek, azoknak, a kik az ő nevében hisznek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'A kik nem vérből, sem a testnek akaratából, sem a férfiúnak indulatjából, hanem Istentől születtek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'És az Íge testté lett és lakozék mi közöttünk (és láttuk az ő dicsőségét, mint az Atya egyszülöttjének dicsőségét), a ki teljes vala kegyelemmel és igazsággal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'János bizonyságot tett ő róla, és kiáltott, mondván: Ez vala, a kiről mondám: A ki utánam jő, előttem lett, mert előbb volt nálamnál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'És az ő teljességéből vettünk mindnyájan kegyelmet is kegyelemért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, 'Mert a törvény Mózes által adatott, a kegyelem pedig és az igazság Jézus Krisztus által lett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, 'Az Istent soha senki nem látta; az egyszülött Fiú, a ki az Atya kebelében van, az jelentette ki őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'És ez a János bizonyságtétele, a mikor a zsidók papokat és Lévitákat küldöttek Jeruzsálemből, hogy megkérdezzék őt: Kicsoda vagy te?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, 'És megvallá és nem tagadá; és megvallá, hogy: Nem én vagyok a Krisztus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, 'És kérdezék őt: Kicsoda tehát? Illés vagy-é te? És monda: Nem vagyok. A próféta vagy-é te? És ő felele: Nem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, 'Mondának azért néki: Kicsoda vagy? Hogy megfelelhessünk azoknak, a kik minket elküldöttek: Mit mondasz magad felől?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, 'Monda: Én kiáltó szó vagyok a pusztában. Egyengessétek az Úrnak útját, a mint megmondotta Ésaiás próféta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, 'És a küldöttek a farizeusok közül valók voltak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, 'És megkérdék őt és mondának néki: Miért keresztelsz tehát, ha te nem vagy a Krisztus, sem Illés, sem a próféta?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, 'Felele nékik János, mondván: Én vízzel keresztelek; de köztetek van, a kit ti nem ismertek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, 'Ő az, a ki utánam jő, a ki előttem lett, a kinek én nem vagyok méltó, hogy saruja szíjját megoldjam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, 'Ezek Béthabarában lettek, a Jordánon túl, a hol János keresztel vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, 'Másnap látá János Jézust ő hozzá menni, és monda: Ímé az Istennek ama báránya, a ki elveszi a világ bűneit!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, 'Ez az, a kiről én ezt mondám: Én utánam jő egy férfiú, a ki előttem lett, mert előbb volt nálamnál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, 'És én nem ismertem őt; de hogy megjelentessék Izráelnek, azért jöttem én, a ki vízzel keresztelek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, 'És bizonyságot tőn János, mondván: Láttam a Lelket leszállani az égből, mint egy galambot; és megnyugovék ő rajta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, 'És én nem ismertem őt; de a ki elkülde engem, hogy vízzel kereszteljek, az mondá nékem: A kire látod a Lelket leszállani és rajta megnyugodni, az az, a ki keresztel Szent Lélekkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, 'És én láttam, és bizonyságot tettem, hogy ez az Isten Fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, 'Másnap ismét ott állt vala János és kettő az ő tanítványai közül;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, 'És ránézvén Jézusra, a mint ott jár vala, monda: Ímé az Isten Báránya!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, 'És hallá őt a két tanítvány, a mint szól vala, és követék Jézust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, 'Jézus pedig hátrafordulván és látván, hogy követik azok, monda nékik:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 39, 'Mit kerestek? Azok pedig mondának néki: Rabbi, (a mi megmagyarázva azt teszi: Mester) hol lakol?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 40, 'Monda nékik: Jőjjetek és lássátok meg. Elmenének és megláták, hol lakik; és nála maradának azon a napon: vala pedig körülbelül tíz óra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 41, 'A kettő közül, a kik Jánostól ezt hallották és őt követték vala, András volt az egyik, a Simon Péter testvére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 42, 'Találkozék ez először a maga testvérével, Simonnal, és monda néki: Megtaláltuk a Messiást (a mi megmagyarázva azt teszi: Krisztus);');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 43, 'És vezeté őt Jézushoz. Jézus pedig reá tekintvén, monda: Te Simon vagy, a Jóna fia; te Kéfásnak fogsz hivatni (a mi megmagyarázva: Kőszikla).');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 44, 'A következő napon Galileába akart menni Jézus; és találkozék Fileppel, és monda néki: Kövess engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 45, 'Filep pedig Bethsaidából, az András és Péter városából való volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 46, 'Találkozék Filep Nátánaellel, és monda néki: A ki felől írt Mózes a törvényben, és a próféták, megtaláltuk a názáreti Jézust, Józsefnek fiát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 47, 'És monda néki Nátánael: Názáretből támadhat-é valami jó? Monda néki Filep: Jer és lásd meg!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 48, 'Látá Jézus Nátánaelt ő hozzá menni, és monda ő felőle: Ímé egy igazán Izráelita, a kiben hamisság nincsen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 49, 'Monda néki Nátánael: Honnan ismersz engem? Felele Jézus és monda néki: Mielőtt hítt téged Filep, láttalak téged, a mint a fügefa alatt voltál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 50, 'Felele Nátánael és monda néki: Rabbi, te vagy az Isten Fia, te vagy az Izráel Királya!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 51, 'Felele Jézus és monda néki: Hogy azt mondám néked: láttalak a fügefa alatt, hiszel? Nagyobbakat látsz majd ezeknél. És monda néki: Bizony, bizony mondom néktek: Mostantól fogva meglátjátok a megnyilt eget, és az Isten angyalait, a mint felszállnak és leszállnak az ember Fiára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'És harmadnapon menyegző lőn a galileai Kánában; és ott volt a Jézus anyja;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'És Jézus is meghivaték az ő tanítványaival együtt a menyegzőbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'És elfogyván a bor, a Jézus anyja monda néki: Nincs boruk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'Monda néki Jézus: Mi közöm nékem te hozzád, oh asszony? Nem jött még el az én órám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Mond az ő anyja a szolgáknak: Valamit mond néktek, megtegyétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'Vala pedig ott hat kőveder elhelyezve a zsidók tisztálkodási módja szerint, melyek közül egybe-egybe két-három métréta fér vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'Monda nékik Jézus: Töltsétek meg a vedreket vízzel. És megtölték azokat színig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'És monda nékik: Most merítsetek, és vigyetek a násznagynak. És vittek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'A mint pedig megízlelé a násznagy a borrá lett vizet, és nem tudja vala, honnét van, (de a szolgák tudták, a kik a vizet merítik vala), szólítá a násznagy a vőlegényt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'És monda néki: Minden ember a jó bort adja fel először, és mikor megittasodtak, akkor az alábbvalót: te a jó bort ekkorra tartottad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'Ezt az első jelt a galileai Kánában tevé Jézus, és megmutatá az ő dicsőségét; és hivének benne az ő tanítványai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Azután leméne Kapernaumba, ő és az ő anyja és a testvérei és tanítványai; és ott maradának néhány napig,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'Mert közel vala a zsidók husvétja, és felméne Jézus Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'És ott találá a templomban az ökrök, juhok és galambok árúsait és a pénzváltókat, a mint ülnek vala:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'És kötélből ostort csinálván, kiűzé mindnyájokat a templomból, az ökröket is a juhokat is; és a pénzváltók pénzét kitölté, az asztalokat pedig feldönté;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'És a galambárúsoknak monda: Hordjátok el ezeket innen; ne tegyétek az én Atyámnak házát kalmárság házává.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'Megemlékezének pedig az ő tanítványai, hogy meg van írva: A te házadhoz való féltő szeretet emészt engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'Felelének azért a zsidók és mondának néki: Micsoda jelt mutatsz nékünk, hogy ezeket cselekszed?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, 'Felele Jézus és monda nékik: Rontsátok le a templomot, és három nap alatt megépítem azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'Mondának azért a zsidók: Negyvenhat esztendeig épült ez a templom, és te három nap alatt megépíted azt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'Ő pedig az ő testének templomáról szól vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'Mikor azért feltámadt a halálból, megemlékezének az ő tanítványai, hogy ezt mondta; és hivének az írásnak, és a beszédnek, a melyet Jézus mondott vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'A mint pedig Jeruzsálemben vala husvétkor az ünnepen, sokan hivének az ő nevében, látván az ő jeleit, a melyeket cselekszik vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'Maga azonban Jézus nem bízza vala magát reájok, a miatt, hogy ő ismeré mindnyájokat,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 25, 'És mivelhogy nem szorult rá, hogy valaki bizonyságot tegyen az emberről; mert magától is tudta, mi volt az emberben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'Vala pedig a farizeusok közt egy ember, a neve Nikodémus, a zsidók főembere:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'Ez jöve Jézushoz éjjel, és monda néki: Mester, tudjuk, hogy Istentől jöttél tanítóul; mert senki sem teheti e jeleket, a melyeket te teszel, hanem ha az Isten van vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Felele Jézus és monda néki: Bizony, bizony mondom néked: ha valaki újonnan nem születik, nem láthatja az Isten országát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'Monda néki Nikodémus: Mimódon születhetik az ember, ha vén? Vajjon bemehet-é az ő anyjának méhébe másodszor, és születhetik-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'Felele Jézus: Bizony, bizony mondom néked: Ha valaki nem születik víztől és Lélektől, nem mehet be az Isten országába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'A mi testtől született, test az; és a mi Lélektől született, lélek az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'Ne csodáld, hogy azt mondám néked: Szükség néktek újonnan születnetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'A szél fú, a hová akar, és annak zúgását hallod, de nem tudod honnan jő és hová megy: így van mindenki, a ki Lélektől született.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'Felele Nikodémus és monda néki: Mimódon lehetnek ezek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'Felele Jézus és monda néki: Te Izráel tanítója vagy, és nem tudod ezeket?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'Bizony, bizony mondom néked, a mit tudunk, azt mondjuk, és a mit látunk, arról teszünk bizonyságot; és a mi bizonyságtételünket el nem fogadjátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'Ha a földiekről szóltam néktek és nem hisztek, mimódon hisztek, ha a mennyeiekről szólok néktek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'És senki sem ment fel a mennybe, hanemha az, a ki a mennyből szállott alá, az embernek Fia, a ki a mennyben van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'És a miképen felemelte Mózes a kígyót a pusztában, akképen kell az ember Fiának felemeltetnie.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'Hogy valaki hiszen ő benne, el ne veszszen, hanem örök élete legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'Mert úgy szerette Isten e világot, hogy az ő egyszülött Fiát adta, hogy valaki hiszen ő benne, el ne vesszen, hanem örök élete legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'Mert nem azért küldte az Isten az ő Fiát a világra, hogy kárhoztassa a világot, hanem hogy megtartassék a világ általa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'A ki hiszen ő benne, el nem kárhozik; a ki pedig nem hisz, immár elkárhozott, mivelhogy nem hitt az Isten egyszülött Fiának nevében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'Ez pedig a kárhoztatás, hogy a világosság e világra jött, és az emberek inkább szerették a sötétséget, mint a világosságot; mert az ő cselekedeteik gonoszak valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'Mert minden, a ki hamisan cselekszik, gyűlöli a világosságot és nem megy a világosságra, hogy az ő cselekedetei fel ne fedessenek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, 'A ki pedig az igazságot cselekszi, az a világosságra megy, hogy az ő cselekedetei nyilvánvalókká legyenek, hogy Isten szerint való cselekedetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, 'Ezután elméne Jézus az ő tanítványaival a Júdea földére; és ott időzék velök, és keresztele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, 'János pedig szintén keresztel vala Énonban, Sálemhez közel, mert ott sok volt a víz. És oda járulának és megkeresztelkedének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, 'Mert János még nem vetteték a tömlöczbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, 'Vetekedés támada azért a János tanítványai és a judeaiak között a mosakodás felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, 'És menének Jánoshoz és mondának néki: Mester! A ki veled vala a Jordánon túl, a kiről te bizonyságot tettél, ímé az keresztel, és hozzá megy mindenki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, 'Felele János és monda: Az ember semmit sem vehet, hanem ha a mennyből adatott néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, 'Ti magatok vagytok a bizonyságaim, hogy megmondtam: Nem vagyok én a Krisztus, hanem hogy ő előtte küldettem el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, 'A kinek jegyese van, vőlegény az; a vőlegény barátja pedig, a ki ott áll és hallja őt, örvendezve örül a vőlegény szavának. Ez az én örömem immár betelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, 'Annak növekednie kell, nékem pedig alább szállanom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, 'A ki felülről jött, feljebb való mindenkinél. A ki a földről való, földi az és földieket szól; a ki a mennyből jött, feljebb való mindenkinél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, 'És arról tesz bizonyságot, a mit látott és hallott; és az ő bizonyságtételét senki sem fogadja be.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, 'A ki az ő bizonyságtételét befogadja, az megpecsételte, hogy az Isten igaz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, 'Mert a kit az Isten küldött, az Isten beszédeit szólja; mivelhogy az Isten nem mérték szerint adja a Lelket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 35, 'Az Atya szereti a Fiút, és az ő kezébe adott mindent.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 36, 'A ki hisz a Fiúban, örök élete van; a ki pedig nem enged a Fiúnak, nem lát életet, hanem az Isten haragja marad rajta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'Amint azért megtudta az Úr, hogy a farizeusok meghallották, hogy Jézus több tanítványt szerez és keresztel, mint János,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, '(Jóllehet Jézus maga nem keresztelt, hanem a tanítványai,)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'Elhagyá Júdeát és elméne ismét Galileába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'Samárián kell vala pedig általmennie.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'Megy vala azért Samáriának Sikár nevű városába, annak a teleknek szomszédjába, a melyet Jákób adott vala az ő fiának, Józsefnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'Ott vala pedig a Jákób forrása. Jézus azért, az utazástól elfáradva, azonmód leüle a forráshoz. Mintegy hat óra vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'Jöve egy samáriabeli asszony vizet meríteni; monda néki Jézus: Adj innom!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, 'Az ő tanítványai ugyanis elmentek a városba, hogy ennivalót vegyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'Monda azért néki a samáriai asszony: Hogy kérhetsz inni zsidó létedre én tőlem, a ki samáriai asszony vagyok?! Mert a zsidók nem barátkoznak a samáriaiakkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'Felele Jézus és monda néki: Ha ismernéd az Isten ajándékát, és hogy ki az, a ki ezt mondja néked: Adj innom!; te kérted volna őt, és adott volna néked élő vizet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, 'Monda néki az asszony: Uram, nincs mivel merítened, és a kút mély: hol vennéd tehát az élő vizet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'Avagy nagyobb vagy-é te a mi atyánknál, Jákóbnál, a ki nékünk adta ezt a kutat, és ebből ivott ő is, a fiai is és jószága is?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Felele Jézus és monda néki: Mindaz, a ki ebből a vízből iszik, ismét megszomjúhozik:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'Valaki pedig abból a vízből iszik, a melyet én adok néki, soha örökké meg nem szomjúhozik; hanem az a víz, a melyet én adok néki, örök életre buzgó víznek kútfeje lesz ő benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, 'Monda néki az asszony: Uram, add nékem azt a vizet, hogy meg ne szomjúhozzam, és ne jőjjek ide meríteni!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, 'Monda néki Jézus: Menj el, hívd a férjedet, és jőjj ide!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, 'Felele az asszony és monda: Nincs férjem. Monda néki Jézus: Jól mondád, hogy: Nincs férjem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, 'Mert öt férjed volt, és a mostani nem férjed: ezt igazán mondtad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, 'Monda néki az asszony: Uram, látom, hogy te próféta vagy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, 'A mi atyáink ezen a hegyen imádkoztak; és ti azt mondjátok, hogy Jeruzsálemben van az a hely, a hol imádkozni kell.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, 'Monda néki Jézus: Asszony, hidd el nékem, hogy eljő az óra, a mikor sem nem ezen a hegyen, sem nem Jeruzsálemben imádjátok az Atyát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, 'Ti azt imádjátok, a mit nem ismertek; mi azt imádjuk, a mit ismerünk: mert az idvesség a zsidók közül támadt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, 'De eljő az óra, és az most vagyon, amikor az igazi imádók lélekben, és igazságban imádják az Atyát: mert az Atya is ilyeneket keres, az ő imádóiul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, 'Az Isten lélek: és a kik őt imádják, szükség, hogy lélekben és igazságban imádják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, 'Monda néki az asszony: Tudom, hogy Messiás jő (a ki Krisztusnak mondatik); mikor az eljő, megjelent nékünk mindent.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, 'Monda néki Jézus: Én vagyok az, a ki veled beszélek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, 'Eközben megjövének az ő tanítványai; és csodálkozának, hogy asszonnyal beszélt; mindazáltal egyik sem mondá: Mit keresel? vagy: Mit beszélsz vele?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, 'Ott hagyá azért az asszony a vedrét, és elméne a városba, és monda az embereknek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, 'Jertek, lássatok egy embert, a ki megmonda nékem mindent, a mit cselekedtem. Nem ez-é a Krisztus?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, 'Kimenének azért a városból, és hozzá menének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, 'Aközben pedig kérék őt a tanítványok, mondván: Mester, egyél!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, 'Ő pedig monda nékik: Van nékem eledelem, a mit egyem, a mit ti nem tudtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, 'Mondának azért a tanítványok egymásnak: Hozott-é néki valaki enni?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, 'Monda nékik Jézus: Az én eledelem az, hogy annak akaratját cselekedjem, a ki elküldött engem, és az ő dolgát elvégezzem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, 'Ti nem azt mondjátok-é, hogy még négy hónap és eljő az aratás? Ímé, mondom néktek: Emeljétek fel szemeiteket, és lássátok meg a tájékokat, hogy már fehérek az aratásra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, 'És a ki arat, jutalmat nyer, és az örök életre gyümölcsöt gyűjt; hogy mind a vető, mind az arató együtt örvendezzen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 37, 'Mert ebben az a mondás igaz, hogy más a vető, más az arató.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 38, 'Én annak az aratására küldtelek titeket, a mit nem ti munkáltatok; mások munkálták, és ti a mások munkájába állottatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 39, 'Abból a városból pedig sokan hivének benne a Samaritánusok közül annak az asszonynak beszédéért, a ki bizonyságot tett vala, hogy: Mindent megmondott nékem, a mit cselekedtem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 40, 'A mint azért oda mentek hozzá a Samaritánusok, kérék őt, hogy maradjon náluk; és ott marada két napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 41, 'És sokkal többen hivének a maga beszédéért,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 42, 'És azt mondják vala az asszonynak, hogy: Nem a te beszédedért hiszünk immár: mert magunk hallottuk, és tudjuk, hogy bizonnyal ez a világ idvezítője, a Krisztus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 43, 'Két nap mulva pedig kiméne onnét, és elméne Galileába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 44, 'Mert Jézus maga tett bizonyságot arról, hogy a prófétának nincs tisztessége a maga hazájában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 45, 'Mikor azért beméne Galileába, befogadták őt a Galileabeliek, mivelhogy látták vala mindazt, a mit Jeruzsálemben cselekedett az ünnepen; mert ők is elmentek vala az ünnepre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 46, 'Ismét a galileai Kánába méne azért Jézus, a hol a vizet borrá változtatta. És volt Kapernaumban egy királyi ember, a kinek a fia beteg vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 47, 'Mikor ez meghallá, hogy Jézus Júdeából Galileába érkezett, hozzá méne és kéré őt, hogy menjen el és gyógyítsa meg az ő fiát; mert halálán vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 48, 'Monda azért néki Jézus: Ha jeleket és csodákat nem láttok, nem hisztek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 49, 'Monda néki a királyi ember: Uram, jőjj, mielőtt a gyermekem meghal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 50, 'Monda néki Jézus: Menj el, a te fiad él. És hitt az ember a szónak, a mit Jézus mondott néki, és elment.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 51, 'A mint pedig már megy vala, elébe jövének az ő szolgái, és hírt hozának néki, mondván, hogy: A te fiad él.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 52, 'Megtudakozá azért tőlük az órát, a melyben megkönnyebbedett vala; és mondának néki: Tegnap hét órakor hagyta el őt a láz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 53, 'Megérté azért az atya, hogy abban az órában, a melyben azt mondá néki a Jézus, hogy: a te fiad él. És hitt ő, és az ő egész háza népe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 54, 'Ezt ismét második jel gyanánt tevé Jézus, mikor Júdeából Galileába ment.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'Ezek után ünnepök vala a zsidóknak, és felméne Jézus Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'Van pedig Jeruzsálemben a Juhkapunál egy tó, a melyet héberül Bethesdának neveznek. Öt tornácza van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'Ezekben feküvék a betegek, vakok, sánták, aszkórosok nagy sokasága, várva a víznek megmozdulását.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, 'Mert időnként angyal szálla a tóra, és felzavará a vizet: a ki tehát először lépett bele a víz felzavarása után, meggyógyult, akárminémű betegségben volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'Vala pedig ott egy ember, a ki harmincnyolcz esztendőt töltött betegségében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'Ezt a mint látta Jézus, hogy ott fekszik, és megtudta, hogy már sok idő óta úgy van; monda néki: Akarsz-é meggyógyulni?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'Felele néki a beteg: Uram, nincs emberem, hogy a mikor a víz felzavarodik, bevigyen engem a tóba; és mire én oda érek, más lép be előttem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Monda néki Jézus: Kelj fel, vedd fel a te nyoszolyádat, és járj!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'És azonnal meggyógyula az ember, és felvevé nyoszolyáját, és jár vala. Aznap pedig szombat vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'Mondának azért a zsidók a meggyógyultnak: Szombat van, nem szabad néked a nyoszolyádat hordanod!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'Felele nékik: A ki meggyógyított engem, az mondá nékem: Vedd fel a nyoszolyádat, és járj.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'Megkérdék azért őt: Ki az az ember, a ki mondá néked: Vedd fel a nyoszolyádat, és járj?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'A meggyógyult pedig nem tudja vala, hogy ki az; mert Jézus félre vonult, sokaság lévén azon a helyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'Ezek után találkozék vele Jézus a templomban, és monda néki: Ímé meggyógyultál; többé ne vétkezzél, hogy rosszabbul ne legyen dolgod!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'Elméne az az ember, és hírül adá a zsidóknak, hogy Jézus az, a ki őt meggyógyította.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'És e miatt üldözőbe vevék a zsidók Jézust, és meg akarák őt ölni, hogy ezeket művelte szombaton.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'Jézus pedig felele nékik: Az én Atyám mind ez ideig munkálkodik, én is munkálkodom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, 'E miatt aztán még inkább meg akarák őt ölni a zsidók, mivel nem csak a szombatot rontotta meg, hanem az Istent is saját Atyjának mondotta, egyenlővé tévén magát az Istennel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, 'Felele azért Jézus, és monda nékik: Bizony, bizony mondom néktek: a Fiú semmit sem tehet önmagától, hanem ha látja cselekedni az Atyát, mert a miket az cselekszik, ugyanazokat hasonlatosképen a Fiú is cselekszi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, 'Mert az Atya szereti a Fiút, és mindent megmutat néki, a miket ő maga cselekszik; és ezeknél nagyobb dolgokat is mutat majd néki, hogy ti csudálkozzatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, 'Mert a mint az Atya feltámasztja a halottakat és megeleveníti, úgy a Fiú is a kiket akar, megelevenít.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, 'Mert az Atya nem ítél senkit, hanem az ítéletet egészen a Fiúnak adta;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'Hogy mindenki úgy tisztelje a Fiút, miként tisztelik az Atyát. A ki nem tiszteli a Fiút, nem tiszteli az Atyát, a ki elküldte őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 24, 'Bizony, bizony mondom néktek, hogy a ki az én beszédemet hallja és hisz annak, a ki engem elbocsátott, örök élete van; és nem megy a kárhozatra, hanem általment a halálból az életre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 25, 'Bizony, bizony mondom néktek, hogy eljő az idő, és az most vagyon, mikor a halottak hallják az Isten Fiának szavát, és a kik hallják, élnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 26, 'Mert a miként az Atyának élete van önmagában, akként adta a Fiúnak is, hogy élete legyen önmagában:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 27, 'És hatalmat ada néki az ítélettételre is, mivelhogy embernek fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 28, 'Ne csodálkozzatok ezen: mert eljő az óra, a melyben mindazok, a kik a koporsókban vannak, meghallják az ő szavát,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 29, 'És kijőnek; a kik a jót cselekedték, az élet feltámadására; a kik pedig a gonoszt művelték, a kárhozat feltámadására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 30, 'Én semmit sem cselekedhetem magamtól; a mint hallok, úgy ítélek, és az én ítéletem igazságos; mert nem a magam akaratát keresem, hanem annak akaratát, a ki elküldött engem, az Atyáét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 31, 'Ha én teszek bizonyságot magamról, az én bizonyságtételem nem igaz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 32, 'Más az, a ki bizonyságot tesz rólam; és tudom, hogy igaz az a bizonyságtétel, a melylyel bizonyságot tesz rólam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 33, 'Ti elküldtetek Jánoshoz, és bizonyságot tett az igazságról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 34, 'De én nem embertől nyerem a bizonyságtételt; hanem ezeket azért mondom, hogy ti megtartassatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 35, 'Ő az égő és fénylő szövétnek vala, ti pedig csak egy ideig akartatok örvendezni az ő világosságában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 36, 'De nékem nagyobb bizonyságom van a Jánosénál: mert azok a dolgok, a melyeket rám bízott az Atya, hogy elvégezzem azokat, azok a dolgok, a melyeket én cselekszem, tesznek bizonyságot rólam, hogy az Atya küldött engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 37, 'A ki elküldött engem, maga az Atya is bizonyságot tett rólam. Sem hangját nem hallottátok soha, sem ábrázatát nem láttátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 38, 'Az ő ígéje sincs maradandóan bennetek: mert a kit ő elküldött, ti annak nem hisztek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 39, 'Tudakozzátok az írásokat, mert azt hiszitek, hogy azokban van a ti örök életetek; és ezek azok, a melyek bizonyságot tesznek rólam;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 40, 'És nem akartok hozzám jőni, hogy életetek legyen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 41, 'Dicsőséget emberektől nem nyerek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 42, 'De ismerlek benneteket, hogy az Istennek szeretete nincs meg bennetek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 43, 'Én az én Atyám nevében jöttem, és nem fogadtatok be engem; ha más jőne a maga nevében, azt befogadnátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 44, 'Mimódon hihettek ti, a kik egymástól nyertek dicsőséget, és azt a dicsőséget, a mely az egy Istentől van, nem keresitek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 45, 'Ne állítsátok, hogy én vádollak majd benneteket az Atyánál; van a ki vádol titeket, Mózes, a kiben ti reménykedtetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 46, 'Mert ha hinnétek Mózesnek, nékem is hinnétek; mert én rólam írt ő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 47, 'Ha pedig az ő írásainak nem hisztek, mimódon hisztek az én beszédeimnek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Ezek után elméne Jézus a galileai tengeren, a Tiberiáson túl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'És nagy sokaság követé őt, mivelhogy látják vala az ő csodatételeit, a melyeket cselekszik vala a betegeken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'Felméne pedig Jézus a hegyre, és leüle ott a tanítványaival.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'Közel vala pedig husvét, a zsidók ünnepe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Mikor azért felemelé Jézus a szemeit, és látá, hogy nagy sokaság jő hozzá, monda Filepnek: Honnan vegyünk kenyeret, hogy ehessenek ezek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, 'Ezt pedig azért mondá, hogy próbára tegye őt; mert ő maga tudta, mit akar vala cselekedni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'Felele néki Filep: Kétszáz dénár árú kenyér nem elég ezeknek, hogy mindenikök kapjon valami keveset.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'Monda néki egy az ő tanítványai közül, András, a Simon Péter testvére:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, 'Van itt egy gyermek, a kinek van öt árpa kenyere és két hala; de mi az ennyinek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'Jézus pedig monda: Ültessétek le az embereket. Nagy fű vala pedig azon a helyen. Leülének azért a férfiak, számszerint mintegy ötezeren.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'Jézus pedig vevé a kenyereket, és hálát adván, adta a tanítványoknak, a tanítványok pedig a leülteknek; hasonlóképen a halakból is, a mennyit akarnak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'A mint pedig betelének, monda az ő tanítványainak: Szedjétek össze a megmaradt darabokat, hogy semmi el ne veszszen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'Összeszedék azért, és megtöltének tizenkét kosarat az öt árpa kenyérből való darabokkal, a melyek megmaradtak vala az evők után.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'Az emberek azért látva a jelt, a melyet Jézus tőn, mondának: Bizonnyal ez ama próféta, a ki eljövendő vala a világra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'Jézus azért, a mint észrevevé, hogy jőni akarnak és őt elragadni, hogy királylyá tegyék, ismét elvonula egymaga a hegyre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'Mikor pedig estveledék, lemenének az ő tanítványai a tengerhez,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'És beszállva a hajóba, mennek vala a tengeren túl Kapernaumba. És már sötétség volt, és még nem ment vala hozzájuk Jézus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'És a tenger a nagy szél fúvása miatt háborog vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'Mikor azért huszonöt, vagy harmincz futamatnyira beevezének, megláták Jézust, a mint jár vala a tengeren és a hajóhoz közeledik vala: és megrémülének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'Ő pedig monda nékik: Én vagyok, ne féljetek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'Be akarák azért őt venni a hajóba: és a hajó azonnal ama földnél vala, a melyre menének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'Másnap a sokaság, a mely a tengeren túl állott vala, látva, hogy nem vala ott más hajó, csak az az egy, a melybe a Jézus tanítványai szállottak, és hogy Jézus nem ment be az ő tanítványaival a hajóba, hanem csak az ő tanítványai mentek el,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, 'De jöttek más hajók Tiberiásból közel ahhoz a helyhez, a hol a kenyeret ették, miután hálákat adott az Úr:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'Mikor azért látta a sokaság, hogy sem Jézus, sem a tanítványai nincsenek ott, beszállának ők is a hajókba, és elmenének Kapernaumba, keresvén Jézust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'És megtalálván őt a tengeren túl, mondának néki: Mester, mikor jöttél ide?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, 'Felele nékik Jézus és monda: Bizony, bizony mondom néktek: nem azért kerestek engem, hogy jeleket láttatok, hanem azért, mert ettetek ama kenyerekből, és jóllaktatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, 'Munkálkodjatok ne az eledelért, a mely elvész, hanem az eledelért, a mely megmarad az örök életre, a melyet az embernek Fia ád majd néktek; mert őt az Atya pecsételte el, az Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, 'Mondának azért néki: Mit csináljunk, hogy az Isten dolgait cselekedjük?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, 'Felele Jézus és monda nékik: Az az Isten dolga, hogy higyjetek abban, a kit ő küldött.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, 'Mondának azért néki: Micsoda jelt mutatsz tehát te, hogy lássuk és higyjünk néked? Mit művelsz?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, 'A mi atyáink a mannát ették a pusztában; a mint meg van írva: Mennyei kenyeret adott vala enniök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, 'Monda azért nékik Jézus: Bizony, bizony mondom néktek: nem Mózes adta néktek a mennyei kenyeret, hanem az én Atyám adja majd néktek az igazi mennyei kenyeret.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, 'Mert az az Istennek kenyere, a mely mennyből száll alá, és életet ád a világnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, 'Mondának azért néki: Uram, mindenkor add nékünk ezt a kenyeret!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, 'Jézus pedig monda nékik: Én vagyok az életnek ama kenyere; a ki hozzám jő, semmiképen meg nem éhezik, és a ki hisz bennem, meg nem szomjúhozik soha.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, 'De mondám néktek, hogy noha láttatok is engem, még sem hisztek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, 'Minden, a mit nékem ád az Atya, én hozzám jő; és azt, a ki hozzám jő, semmiképen ki nem vetem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 38, 'Mert azért szállottam le a mennyből, hogy ne a magam akaratát cselekedjem, hanem annak akaratát, a ki elküldött engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 39, 'Az pedig az Atyának akarata, a ki elküldött engem, hogy a mit nékem adott, abból semmit el ne veszítsek, hanem feltámaszszam azt az utolsó napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 40, 'Az pedig annak az akarata, a ki elküldött engem, hogy mindaz, a ki látja a Fiút és hisz ő benne, örök élete legyen; és én feltámaszszam azt azt utolsó napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 41, 'Zúgolódának azért a zsidók ő ellene, hogy azt mondá: Én vagyok az a kenyér, a mely a mennyből szállott alá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 42, 'És mondának: Nem ez-é Jézus, a József fia, a kinek mi ismerjük atyját és anyját? mimódon mondja hát ez, hogy: A mennyből szállottam alá?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 43, 'Felele azért Jézus és monda nékik: Ne zúgolódjatok egymás között!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 44, 'Senki sem jöhet én hozzám, hanemha az Atya vonja azt, a ki elküldött engem; én pedig feltámasztom azt az utolsó napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 45, 'Meg van írva a prófétáknál: És mindnyájan Istentől tanítottak lesznek. Valaki azért az Atyától hallott, és tanult, én hozzám jő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 46, 'Nem hogy az Atyát valaki látta, csak az, a ki Istentől van, az látta az Atyát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 47, 'Bizony, bizony mondom néktek: A ki én bennem hisz, örök élete van annak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 48, 'Én vagyok az életnek kenyere.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 49, 'A ti atyáitok a mannát ették a pusztában, és meghaltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 50, 'Ez az a kenyér, a mely a mennyből szállott alá, hogy kiki egyék belőle és meg ne haljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 51, 'Én vagyok amaz élő kenyér, a mely a mennyből szállott alá; ha valaki eszik e kenyérből, él örökké. És az a kenyér pedig, a melyet én adok, az én testem, a melyet én adok a világ életéért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 52, 'Tusakodának azért a zsidók egymás között, mondván: Mimódon adhatja ez nékünk a testét, hogy azt együk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 53, 'Monda azért nékik Jézus: Bizony, bizony mondom néktek: Ha nem eszitek az ember Fiának testét és nem iszszátok az ő vérét, nincs élet bennetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 54, 'A ki eszi az én testemet és iszsza az én véremet, örök élete van annak, és én feltámasztom azt az utolsó napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 55, 'Mert az én testem bizony étel és az én vérem bizony ital.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 56, 'A ki eszi az én testemet és iszsza az én véremet, az én bennem lakozik és én is abban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 57, 'A miként elküldött engem amaz élő Atya, és én az Atya által élek: akként az is, a ki engem eszik, él én általam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 58, 'Ez az a kenyér, a mely a mennyből szállott alá; nem úgy, a mint a ti atyáitok evék a mannát és meghalának: a ki ezt a kenyeret eszi, él örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 59, 'Ezeket mondá a zsinagógában, a mikor tanít vala Kapernaumban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 60, 'Sokan azért, a kik hallák ezeket az ő tanítványai közül, mondának: Kemény beszéd ez; ki hallgathatja őt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 61, 'Tudván pedig Jézus ő magában, hogy e miatt zúgolódnak az ő tanítványai, monda nékik: Titeket ez megbotránkoztat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 62, 'Hát ha meglátjátok az embernek Fiát felszállani oda, a hol elébb vala?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 63, 'A lélek az, a mi megelevenít, a test nem használ semmit: a beszédek, a melyeket én szólok néktek, lélek és élet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 64, 'De vannak némelyek közöttetek, a kik nem hisznek. Mert eleitől fogva tudta Jézus, kik azok, a kik nem hisznek, és ki az, a ki elárulja őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 65, 'És monda: Azért mondtam néktek, hogy senki sem jöhet én hozzám, hanemha az én Atyámtól van megadva néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 66, 'Ettől fogva sokan visszavonulának az ő tanítványai közül és nem járnak vala többé ő vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 67, 'Monda azért Jézus a tizenkettőnek: Vajjon ti is el akartok-é menni?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 68, 'Felele néki Simon Péter: Uram, kihez mehetnénk? Örök életnek beszéde van te nálad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 69, 'És mi elhittük és megismertük, hogy te vagy a Krisztus, az élő Istennek Fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 70, 'Felele nékik Jézus: Nem én választottalak-é ki titeket, a tizenkettőt? és egy közületek ördög.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 71, 'Értette pedig Júdás Iskáriótest, Simon fiát, mert ez akarta őt elárulni, noha egy volt a tizenkettő közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'És ezek után Galileában jár vala Jézus; mert nem akar vala Júdeában járni, mivelhogy azon igyekezének a Júdeabeliek, hogy őt megöljék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'Közel vala pedig a zsidók ünnepe, a sátoros ünnep.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'Mondának azért néki az ő atyjafiai: Menj el innen, és térj Júdeába, hogy a te tanítványaid is lássák a te dolgaidat, a melyeket cselekszel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'Mert senki sem cselekszik titkon semmit, a ki maga ismeretessé akar lenni. Ha ilyeneket cselekszel, mutasd meg magadat a világnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'Mert az ő atyjafiai sem hivének benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'Monda azért nékik Jézus: Az én időm még nincs itt; a ti időtök pedig mindig készen van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'Titeket nem gyűlölhet a világ, de engem gyűlöl; mert én bizonyságot teszek felőle, hogy az ő cselekedetei gonoszak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'Ti menjetek fel erre az ünnepre: én még nem megyek fel erre az ünnepre; mert az én időm még nem tölt be.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'Ezeket mondván pedig nékik, marada Galileában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'A mint pedig felmenének az ő atyjafiai, akkor ő is felméne az ünnepre, nem nyilvánosan, hanem mintegy titkon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'A zsidók azért keresik vala őt az ünnepen, és mondának: Hol van ő?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'És a sokaságban nagy zúgás vala ő miatta. Némelyek azt mondják vala, hogy jó ember; mások pedig azt mondják vala: Nem, hanem a népnek hitetője.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Mindamellett senki sem beszélt vala nyiltan ő felőle a zsidóktól való félelem miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'Már-már az ünnep közepén azonban felméne Jézus a templomba, és tanít vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'És csodálkozának a zsidók, mondván: Mimódon tudja ez az írásokat, holott nem tanulta?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'Felele nékik Jézus és monda: Az én tudományom nem az enyém, hanem azé, a ki küldött engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'Ha valaki cselekedni akarja az ő akaratát, megismerheti e tudományról, vajjon Istentől van-é, vagy én magamtól szólok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, 'A ki magától szól, a maga dicsőségét keresi; a ki pedig annak dicsőségét keresi, a ki küldte őt, igaz az, és nincs abban hamisság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'Nem Mózes adta-é néktek a törvényt? és senki sem teljesíti közületek a törvényt. Miért akartok engem megölni?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, 'Felele a sokaság és monda: Ördög van benned. Ki akar téged megölni?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'Felele Jézus és monda nékik: Egy dolgot cselekvém, és mindnyájan csodáljátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'Azért Mózes adta néktek a körülmetélkedést (nem mintha Mózestől való volna, hanem az atyáktól): és szombaton körülmetélitek az embert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'Ha körülmetélhető az ember szombaton, hogy a Mózes törvénye meg ne romoljon; én rám haragusztok-é, hogy egy embert egészen meggyógyítottam szombaton?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'Ne ítéljetek a látszat után, hanem igaz ítélettel ítéljetek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'Mondának azért némelyek a jeruzsálemiek közül: Nem ez-é az, a kit meg akarnak ölni?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'És ímé nyiltan szól, és semmit sem szólnak néki. Talán bizony megismerték a főemberek, hogy bizony ez a Krisztus?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'De jól tudjuk, honnan való ez; mikor pedig eljő a Krisztus, senki sem tudja, honnan való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'Kiálta azért Jézus a templomban, tanítván és mondván: Mind engem ismertek, mind azt tudjátok, honnan való vagyok; és én magamtól nem jöttem, de igaz az, a ki engem elküldött, a kit ti nem ismertek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'Én azonban ismerem őt, mert ő tőle vagyok, és ő küldött engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'Akarják vala azért őt megfogni; de senki sem veté reá a kezét, mert nem jött még el az ő órája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, 'A sokaság közül pedig sokan hivének ő benne; és azt mondják vala, hogy: A Krisztus mikor eljő, tehet-é majd több csodát azoknál, a melyeket ez tett?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, 'Meghallák a farizeusok, a mint a sokaság ezeket suttogja vala felőle; és szolgákat küldének a farizeusok és a főpapok, hogy fogják meg őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, 'Monda azért nékik Jézus: Egy kevés ideig még veletek vagyok, és majd ahhoz megyek, a ki elküldött engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, 'Kerestek majd engem, és nem találtok meg, és a hol én vagyok, ti nem jöhettek oda.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, 'Mondának azért a zsidók magok között: Hová akar ez menni, hogy mi majd nem találjuk meg őt? Vajjon a görögök közé szóródottakhoz akar-é menni, és a görögöket tanítani?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, 'Micsoda beszéd ez, a melyet monda: Kerestek majd engem, és nem találtok meg; és a hol én vagyok, ti nem jöhettek oda?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, 'Az ünnep utolsó nagy napján pedig felálla Jézus és kiálta, mondván: Ha valaki szomjúhozik, jőjjön én hozzám, és igyék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, 'A ki hisz én bennem, a mint az írás mondotta, élő víznek folyamai ömlenek annak belsejéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, 'Ezt pedig mondja vala a Lélekről, a melyet veendők valának az ő benne hívők: mert még nem vala Szent Lélek; mivelhogy Jézus még nem dicsőítteték meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, 'Sokan azért a sokaság közül, a mint hallák e beszédet, ezt mondják vala: Bizonynyal ez ama Próféta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 41, 'Némelyek mondának: Ez a Krisztus. Mások pedig mondának: Csak nem Galileából jön el a Krisztus?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 42, 'Nem az írás mondta-é, hogy a Dávid magvából, és Bethlehemből, ama városból jön el a Krisztus, a hol Dávid vala?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 43, 'Hasonlás lőn azért ő miatta a sokaságban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 44, 'Némelyek pedig közűlök akarják vala őt megfogni, de senki sem veté reá a kezét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 45, 'Elmenének azért a szolgák a főpapokhoz és farizeusokhoz; és mondának azok ő nékik: Miért nem hoztátok el őt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 46, 'Felelének a szolgák: Soha ember úgy nem szólott, mint ez az ember!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 47, 'Felelének azért nékik a farizeusok: Vajjon ti is el vagytok-é hitetve?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 48, 'Vajjon a főemberek vagy a farizeusok közül hitt-é benne valaki?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 49, 'De ez a sokaság, a mely nem ismeri a törvényt, átkozott!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 50, 'Monda nékik Nikodémus, a ki éjjel ment vala ő hozzá, a ki egy vala azok közül:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 51, 'Vajjon a mi törvényünk kárhoztatja-é az embert, ha előbb ki nem hallgatja és nem tudja, hogy mit cselekszik?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 52, 'Felelének és mondának néki: Vajjon te is Galileus vagy-é? Tudakozódjál és lásd meg, hogy Galileából nem támadt próféta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 53, 'És mindnyájan haza menének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'Jézus pedig elméne az Olajfák hegyére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'Jó reggel azonban ismét ott vala a templomban, és az egész nép hozzá méne; és leülvén, tanítja vala őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'Az írástudók és a farizeusok pedig egy asszonyt vivének hozzá, a kit házasságtörésen kaptak vala, és a középre állítván azt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, 'Mondának néki: Mester, ez az asszony tetten kapatott, mint házasságtörő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'A törvényben pedig megparancsolta nékünk Mózes, hogy az ilyenek köveztessenek meg: te azért mit mondasz?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'Ezt pedig azért mondák, hogy megkísértsék őt, hogy legyen őt mivel vádolniok. Jézus pedig lehajolván, az ujjával ír vala a földre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'De mikor szorgalmazva kérdezék őt, felegyenesedve monda nékik: A ki közületek nem bűnös, az vesse rá először a követ.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'És újra lehajolván, írt vala a földre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, 'Azok pedig ezt hallván és a lelkiismeret által vádoltatván, egymásután kimenének a vénektől kezdve mind az utolsóig; és egyedül Jézus maradt vala és az asszony a középen állva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'Mikor pedig Jézus felegyenesedék és senkit sem láta az asszonyon kívül, monda néki: Asszony, hol vannak azok a te vádlóid? Senki sem kárhoztatott-é téged?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, 'Az pedig monda: Senki, Uram! Jézus pedig monda néki: Én sem kárhoztatlak: eredj el és többé ne vétkezzél!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'Ismét szóla azért hozzájok Jézus, mondván: Én vagyok a világ világossága: a ki engem követ, nem járhat a sötétségben, hanem övé lesz az életnek világossága.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'Mondának azért néki a farizeusok: Te magadról teszel bizonyságot; a te bizonyságtételed nem igaz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Felele Jézus és monda nékik: Ha magam teszek is bizonyságot magamról, az én bizonyságtételem igaz; mert tudom honnan jöttem és hová megyek; ti pedig nem tudjátok honnan jövök és hová megyek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'Ti test szerint ítéltek, én nem ítélek senkit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'De ha ítélek is én, az én ítéletem igaz; mert én nem egyedül vagyok, hanem én és az Atya, a ki küldött engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'A ti törvényetekben is meg van pedig írva, hogy két ember bizonyságtétele igaz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'Én vagyok a ki bizonyságot teszek magamról, és bizonyságot tesz rólam az Atya, a ki küldött engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'Mondának azért néki: Hol van a te Atyád? Felele Jézus: Sem engem nem ismertek, sem az én Atyámat; ha engem ismernétek, az én Atyámat is ismernétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'Ezeket a beszédeket mondá Jézus a kincstartó helyen, a mikor tanít vala a templomban; és senki sem fogta meg őt, mert még nem jött el az ő órája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, 'Ismét monda azért nékik Jézus: Én elmegyek, és kerestek majd engem, és a ti bűneitekben fogtok meghalni: a hová én megyek, ti nem jöhettek oda.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, 'Mondának azért a zsidók: Avagy megöli-é magát, hogy azt mondja: A hová én megyek, ti nem jöhettek oda?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, 'És monda nékik: Ti innét alól valók vagytok, én onnét felül való vagyok; ti e világból valók vagytok, én nem vagyok e világból való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, 'Azért mondám néktek, hogy a ti bűneitekben haltok meg: mert ha nem hiszitek, hogy én vagyok, meghaltok a ti bűneitekben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, 'Mondának azért néki: Ki vagy te? És monda nékik Jézus: A mit eleitől fogva mondok is néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, 'Sok beszélni és ítélni valóm van felőletek: de igaz az, a ki küldött engem; és én azokat beszélem a világnak, a miket tőle hallottam vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, 'Nem vevék észre, hogy az Atyáról szól vala nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, 'Monda azért nékik Jézus: Mikor felemelitek az embernek Fiát, akkor megismeritek, hogy én vagyok és semmit sem cselekszem magamtól, hanem a mint az Atya tanított engem, úgy szólok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, 'És a ki küldött engem, én velem van. Nem hagyott engem az Atya egyedül, mert én mindenkor azokat cselekszem, a melyek néki kedvesek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, 'A mikor ezeket mondá, sokan hivének ő benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, 'Monda azért Jézus a benne hívő zsidóknak: Ha ti megmaradtok az én beszédemben, bizonynyal az én tanítványaim vagytok;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, 'És megismeritek az igazságot, és az igazság szabadokká tesz titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, 'Felelének néki: Ábrahám magva vagyunk, és nem szolgáltunk soha senkinek: mimódon mondod te, hogy szabadokká lesztek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, 'Felele nékik Jézus: Bizony, bizony mondom néktek, hogy mindaz, a ki bűnt cselekszik, szolgája a bűnnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, 'A szolga pedig nem marad mindörökké a házban: a Fiú marad ott mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, 'Azért ha a Fiú megszabadít titeket, valósággal szabadok lesztek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, 'Tudom, hogy Ábrahám magva vagytok; de meg akartok engem ölni, mert az én beszédemnek nincs helye nálatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, 'Én azt beszélem, a mit az én Atyámnál láttam; ti is azt cselekszitek azért, a mit a ti atyátoknál láttatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, 'Felelének és mondának néki: A mi atyánk Ábrahám. Monda nékik Jézus: Ha Ábrahám gyermekei volnátok, az Ábrahám dolgait cselekednétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, 'Ámde meg akartok engem ölni, olyan embert, a ki az igazságot beszéltem néktek, a melyet az Istentől hallottam. Ábrahám ezt nem cselekedte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, 'Ti a ti atyátok dolgait cselekszitek. Mondának azért néki: Mi nem paráznaságból születtünk; egy atyánk van, az Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, 'Monda azért nékik Jézus: Ha az Isten volna a ti atyátok, szeretnétek engem: mert én az Istentől származtam és jöttem; mert nem is magamtól jöttem, hanem ő küldött engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, 'Miért nem értitek az én beszédemet? Mert nem hallgatjátok az én szómat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, 'Ti az ördög atyától valók vagytok, és a ti atyátok kívánságait akarjátok teljesíteni. Az emberölő volt kezdettől fogva, és nem állott meg az igazságban, mert nincsen ő benne igazság. Mikor hazugságot szól, a sajátjából szól; mert hazug és hazugság atyja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, 'Mivelhogy pedig én igazságot szólok, nem hisztek nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, 'Ki vádol engem közületek bűnnel? Ha pedig igazságot szólok: miért nem hisztek ti nékem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, 'A ki az Istentől van, hallgatja az Isten beszédeit; azért nem hallgatjátok ti, mert nem vagytok az Istentől valók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, 'Felelének azért a zsidók és mondának néki: Nem jól mondjuk-é mi, hogy te Samaritánus vagy, és ördög van benned?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, 'Felele Jézus: Nincs én bennem ördög; hanem tisztelem az én Atyámat, és ti gyaláztok engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, 'Pedig én nem keresem az én dicsőségemet: van a ki keresi és megítéli.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, 'Bizony, bizony mondom néktek, ha valaki megtartja az én beszédemet, nem lát halált soha örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, 'Mondának azért néki a zsidók: Most értettük meg, hogy ördög van benned. Ábrahám meghalt, a próféták is; és te azt mondod: Ha valaki megtartja az én beszédemet, nem kóstol halált örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, 'Avagy nagyobb vagy-é te a mi atyánknál Ábrahámnál, a ki meghalt? A próféták is meghaltak: kinek állítod te magadat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, 'Felele Jézus: Ha én dicsőítem magamat, az én dicsőségem semmi: az én Atyám az, a ki dicsőít engem, a kiről ti azt mondjátok, hogy a ti Istenetek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, 'És nem ismeritek őt: de én ismerem őt; és ha azt mondom, hogy nem ismerem őt, hozzátok hasonlóvá, hazuggá leszek: de ismerem őt, és az ő beszédét megtartom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, 'Ábrahám a ti atyátok örvendezett, hogy meglátja az én napomat; látta is, és örült.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, 'Mondának azért néki a zsidók: Még ötven esztendős nem vagy, és Ábrahámot láttad?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, 'Monda nékik Jézus: Bizony, bizony mondom néktek: Mielőtt Ábrahám lett, én vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, 'Köveket ragadának azért, hogy reá hajigálják; Jézus pedig elrejtőzködék, és kiméne a templomból, átmenvén közöttük; és ilyen módon eltávozék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'És a mint eltávozék, láta egy embert, a ki születésétől fogva vak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'És kérdezék őt a tanítványai, mondván: Mester, ki vétkezett, ez-é vagy ennek szülei, hogy vakon született?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'Felele Jézus: Sem ez nem vétkezett, sem ennek szülei; hanem, hogy nyilvánvalókká legyenek benne az Isten dolgai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'Nékem cselekednem kell annak dolgait, a ki elküldött engem, a míg nappal van: eljő az éjszaka, mikor senki sem munkálkodhatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'Míg e világon vagyok, e világ világossága vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'Ezeket mondván, a földre köpe, és az ő nyálából sárt csinála, és rákené a sarat a vak szemeire,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'És monda néki: Menj el, mosakodjál meg a Siloám tavában (a mi azt jelenti: Küldött). Elméne azért és megmosakodék, és megjöve látva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'A szomszédok azért, és a kik az előtt látták azt, hogy vak vala, mondának: Nem ez-é az, a ki itt szokott ülni és koldulni?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'Némelyek azt mondák, hogy: Ez az; mások pedig, hogy: Hasonlít hozzá. Ő azt mondá, hogy: Én vagyok az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'Mondának azért néki: Mimódon nyiltak meg a te szemeid?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'Felele az és monda: Egy ember, a kit Jézusnak mondanak, sarat készíte és rákené a szemeimre, és monda nékem: Menj el a Siloám tavára és mosódjál meg; miután pedig elmenék és megmosakodám, megjöve látásom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'Mondának azért néki: Hol van az? Monda: Nem tudom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'Vivék őt, a ki előbb még vak volt, a farizeusokhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, 'Mikor pedig Jézus a sarat csinálá és felnyitá ennek szemeit, szombat vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'Szintén a farizeusok is megkérdezék azért őt, mimódon jött meg a látása? Ő pedig monda nékik: Sarat tőn szemeimre, és megmosakodám, és látok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Mondának azért némelyek a farizeusok közül: Ez az ember nincsen Istentől, mert nem tartja meg a szombatot. Mások mondának: Mimódon tehet bűnös ember ilyen jeleket? És hasonlás lőn közöttük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'Újra mondának a vaknak: Te mit szólsz ő róla, hogy megnyitá a szemeidet? Ő pedig monda: Hogy próféta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'Nem hivék azért a zsidók róla, hogy vak vala és megjöve a látása, mígnem előhívák annak szüleit, a kinek megjöve a látása,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, 'És megkérdezék azokat, mondván: Ez a ti fiatok, a kiről azt mondjátok, hogy vakon született? mimódon lát hát most?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, 'Felelének nékik annak szülei és mondának: Tudjuk, hogy ez a mi fiunk, és hogy vakon született:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, 'De mimódon lát most, nem tudjuk; vagy ki nyitotta meg a szemeit, mi nem tudjuk: elég idős már ő; őt kérdezzétek; ő beszéljen magáról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, 'Ezeket mondák annak szülei, mivelhogy félnek vala a zsidóktól: mert megegyeztek már a zsidók, hogy ha valaki Krisztusnak vallja őt, rekesztessék ki a gyülekezetből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, 'Ezért mondák annak szülei, hogy: Elég idős, őt kérdezzétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, 'Másodszor is szólíták azért az embert, a ki vak vala, és mondának néki: Adj dicsőséget az Istennek; mi tudjuk, hogy ez az ember bűnös.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, 'Felele azért az és monda: Ha bűnös-é, nem tudom: egyet tudok, hogy noha vak voltam, most látok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, 'Újra mondák pedig néki: Mit csinált veled? Mimódon nyitotta meg a szemeidet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, 'Felele nékik: Már mondám néktek és nem hallátok: miért akarjátok újra hallani? avagy ti is az ő tanítványai akartok lenni?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, 'Szidalmazák azért őt és mondának: Te vagy annak a tanítványa; mi pedig a Mózes tanítványai vagyunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, 'Mi tudjuk, hogy Mózessel beszélt az Isten: erről pedig azt sem tudjuk, honnan való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, 'Felele az ember és monda nékik: Bizony csodálatos az, hogy ti nem tudjátok honnan való, és az én szemeimet megnyitotta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, 'Pedig tudjuk, hogy az Isten nem hallgatja meg a bűnösöket; hanem ha valaki istenfélő, és az ő akaratát cselekszi, azt hallgatja meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, 'Öröktől fogva nem hallaték, hogy vakon szülöttnek szemeit valaki megnyitotta volna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, 'Ha ez nem Istentől volna, semmit sem cselekedhetnék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, 'Felelének és mondának néki: Te mindenestől bűnben születtél, és te tanítasz minket? És kiveték őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, 'Meghallá Jézus, hogy kiveték azt; és találkozván vele, monda néki: Hiszel-é te az Isten Fiában?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, 'Felele az és monda: Ki az, Uram, hogy higyjek benne?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, 'Monda pedig néki Jézus: Láttad is őt, és a ki beszél veled, az az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, 'Az pedig monda: Hiszek, Uram. És imádá Őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, 'És monda Jézus: Ítélet végett jöttem én e világra, hogy a kik nem látnak, lássanak; és a kik látnak, vakok legyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, 'És hallák ezeket némely farizeusok, a kik vele valának, és mondának néki: Avagy mi is vakok vagyunk-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, 'Monda nékik Jézus: Ha vakok volnátok, nem volna bűnötök; ámde azt mondjátok, hogy látunk: azért a ti bűnötök megmarad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, 'Bizony, bizony mondom néktek: A ki nem az ajtón megy be a juhok aklába, hanem másunnan hág be, tolvaj az és rabló.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'A ki pedig az ajtón megy be, a juhok pásztora az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'Ennek az ajtónálló ajtót nyit; és a juhok hallgatnak annak szavára; és a maga juhait nevökön szólítja, és kivezeti őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'És mikor kiereszti az ő juhait, előttök megy; és a juhok követik őt, mert ismerik az ő hangját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'Idegent pedig nem követnek, hanem elfutnak attól: mert nem ismerik az idegenek hangját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'Ezt a példázatot mondá nékik Jézus; de ők nem értették, mi az, a mit szól vala nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'Újra monda azért nékik Jézus: Bizony, bizony mondom néktek, hogy én vagyok a juhoknak ajtaja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'Mindazok, a kik előttem jöttek, tolvajok és rablók: de nem hallgattak rájok a juhok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'Én vagyok az ajtó: ha valaki én rajtam megy be, megtartatik és bejár és kijár majd, és legelőt talál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'A tolvaj nem egyébért jő, hanem hogy lopjon és öljön és pusztítson; én azért jöttem, hogy életök legyen, és bővölködjenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'Én vagyok a jó pásztor: a jó pásztor életét adja a juhokért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'A béres pedig és a ki nem pásztor, a kinek a juhok nem tulajdonai, látja a farkast jőni, és elhagyja a juhokat, és elfut: és a farkas elragadozza azokat, és elszéleszti a juhokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, 'A béres pedig azért fut el, mert béres, és nincs gondja a juhokra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'Én vagyok a jó pásztor; és ismerem az enyéimet, és engem is ismernek az enyéim,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'A miként ismer engem az Atya, és én is ismerem az Atyát; és életemet adom a juhokért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'Más juhaim is vannak nékem, a melyek nem ebből az akolból valók: azokat is elő kell hoznom, és hallgatnak majd az én szómra; és lészen egy akol és egy pásztor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'Azért szeret engem az Atya, mert én leteszem az én életemet, hogy újra felvegyem azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'Senki sem veszi azt el én tőlem, hanem én teszem le azt én magamtól. Van hatalmam letenni azt, és van hatalmam ismét felvenni azt. Ezt a parancsolatot vettem az én Atyámtól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'Újra hasonlás lőn a zsidók között e beszédek miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'És sokan mondják vala közülök: Ördög van benne és bolondozik, mit hallgattok reá?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'Mások mondának: Ezek nem ördöngősnek beszédei. Vajjon az ördög megnyithatja-é a vakok szemeit?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, 'Lőn pedig Jeruzsálemben a templomszentelés ünnepe: és tél vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, 'És Jézus a templomban, a Salamon tornáczában jár vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, 'Körülvevék azért őt a zsidók, és mondának néki: Meddig tartasz még bizonytalanságban bennünket? Ha te vagy a Krisztus, mondd meg nékünk nyilván!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, 'Felele nékik Jézus: Megmondtam néktek, és nem hiszitek: a cselekedetek, a melyeket én cselekszem az én Atyám nevében, azok tesznek bizonyságot rólam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, 'De ti nem hisztek, mert ti nem az én juhaim közül vagytok. A mint megmondtam néktek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, 'Az én juhaim hallják az én szómat, és én ismerem őket, és követnek engem:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, 'És én örök életet adok nékik; és soha örökké el nem vesznek, és senki ki nem ragadja őket az én kezemből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, 'Az én Atyám, a ki azokat adta nékem, nagyobb mindeneknél; és senki sem ragadhatja ki azokat az én Atyámnak kezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, 'Én és az Atya egy vagyunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, 'Ismét köveket ragadának azért a zsidók, hogy megkövezzék őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, 'Felele nékik Jézus: Sok jó dolgot mutattam néktek az én Atyámtól; azok közül melyik dologért köveztek meg engem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, 'Felelének néki a zsidók, mondván: Jó dologért nem kövezünk meg téged, hanem káromlásért, tudniillik, hogy te ember létedre Istenné teszed magadat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, 'Felele nékik Jézus: Nincs-é megírva a ti törvényetekben: Én mondám: Istenek vagytok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, 'Ha azokat isteneknek mondá, a kikhez az Isten beszéde lőn (és az írás fel nem bontható),');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, 'Arról mondjátok-é ti, a kit az Atya megszentelt és elküldött e világra: Káromlást szólsz; mivelhogy azt mondám: Az Isten Fia vagyok?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, 'Ha az én Atyám dolgait nem cselekszem, ne higyjetek nékem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, 'Ha pedig azokat cselekszem, ha nékem nem hisztek is, higyjetek a cselekedeteknek: hogy megtudjátok és elhigyjétek, hogy az Atya én bennem van, és én ő benne vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, 'Ismét meg akarák azért őt fogni; de kiméne az ő kezökből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, 'És újra elméne túl a Jordánon, arra a helyre, a hol János először keresztelt vala; és ott marada.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, 'És sokan menének ő hozzá és mondják vala, hogy: János nem tett ugyan semmi csodát; de mindaz, a mit János e felől mondott, igaz vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, 'És sokan hivének ott ő benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'Vala pedig egy beteg, Lázár, Bethániából, Máriának és az ő testvérének, Márthának falujából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, 'Az a Mária volt pedig az, a kinek a testvére Lázár beteg vala, a ki megkente vala az Urat kenettel és a hajával törlé meg annak lábait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'Küldének azért a testvérek ő hozzá, mondván: Uram, ímé, a kit szeretsz, beteg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'Jézus pedig, a mikor ezt hallotta, monda: Ez a betegség nem halálos, hanem az Isten dicsőségére való, hogy dicsőíttessék általa az Istennek Fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'Szereti vala pedig Jézus Márthát és annak nőtestvérét, és Lázárt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'Mikor azért meghallá, hogy beteg, akkor két napig marada azon a helyen, a hol vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'Ez után aztán monda tanítványainak: Menjünk ismét Júdeába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'Mondának néki a tanítványok: Mester, most akarnak vala téged megkövezni a Júdabeliek, és újra oda mégy?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'Felele Jézus: Avagy nem tizenkét órája van-é a napnak? Ha valaki nappal jár, nem botlik meg, mert látja e világnak világosságát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'De a ki éjjel jár, megbotlik, mert nincsen abban világosság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'Ezeket mondá; és ezután monda nékik: Lázár, a mi barátunk, elaludt; de elmegyek, hogy felköltsem őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, 'Mondának azért az ő tanítványai: Uram, ha elaludt, meggyógyul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'Pedig Jézus annak haláláról beszélt; de ők azt hitték, hogy álomnak alvásáról szól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Ekkor azért nyilván monda nékik Jézus: Lázár megholt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'És örülök, hogy nem voltam ott, ti érettetek, hogy higyjetek. De menjünk el ő hozzá!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'Monda azért Tamás, a ki Kettősnek mondatik, az ő tanítványtársainak: Menjünk el mi is, hogy meghaljunk vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'Elmenvén azért Jézus, úgy találá, hogy az már négy napja vala sírban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, 'Bethánia pedig közel vala Jeruzsálemhez, mintegy tizenöt futamatnyira;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'És a zsidók közül sokan mentek vala Márthához és Máriához, hogy vigasztalják őket az ő testvérök felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'Mártha azért, a mint hallja vala, hogy Jézus jő, elébe méne; Mária pedig otthon ül vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'Monda azért Mártha Jézusnak: Uram, ha itt lettél volna, nem halt volna meg a testvérem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, 'De most is tudom, hogy a mit csak kérsz az Istentől, megadja néked az Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'Monda néki Jézus: Feltámad a te testvéred.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, 'Monda néki Mártha: Tudom, hogy feltámad a feltámadáskor az utolsó napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'Monda néki Jézus: Én vagyok a feltámadás és az élet: a ki hisz én bennem, ha meghal is, él;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'És a ki csak él és hisz én bennem, soha meg nem hal. Hiszed-é ezt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, 'Monda néki: Igen Uram, én hiszem, hogy te vagy a Krisztus, az Istennek Fia, a ki e világra jövendő vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, 'És a mint ezeket mondotta vala, elméne, és titkon szólítá az ő testvérét Máriát, mondván: A Mester itt van és hív téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, 'Mihelyt ez hallá, felkele hamar és hozzá méne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, 'Jézus pedig nem ment vala még be a faluba, hanem azon a helyen vala, a hová Mártha elébe ment vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, 'A zsidók azért, a kik ő vele otthon valának és vigasztalák őt, látván, hogy Mária hamar felkél és kimegy vala, utána menének, ezt mondván: A sírhoz megy, hogy ott sírjon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, 'Mária azért, a mint oda ére, a hol Jézus vala, meglátván őt, az ő lábaihoz esék, mondván néki: Uram, ha itt voltál volna, nem halt volna meg az én testvérem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, 'Jézus azért, a mint látja vala, hogy az sír és sírnak a vele jött zsidók is, elbúsula lelkében és igen megrendüle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, 'És monda: Hová helyeztétek őt? Mondának néki: Uram, jer és lásd meg!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, 'Könnyekre fakadt Jézus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, 'Mondának azért a zsidók: Ímé, mennyire szerette őt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, 'Némelyek pedig mondának közülök: Nem megtehette volna-é ez, a ki a vaknak szemét felnyitotta, hogy ez ne haljon meg?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, 'Jézus pedig újra felindulva magában, oda megy vala a sírhoz. Az pedig egy üreg vala, és kő feküvék rajta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, 'Monda Jézus: Vegyétek el a követ. Monda néki a megholtnak nőtestvére, Mártha: Uram, immár szaga van, hiszen negyednapos.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, 'Monda néki Jézus: Nem mondtam-é néked, hogy ha hiszel, meglátod majd az Istennek dicsőségét?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, 'Elvevék azért a követ onnan, a hol a megholt feküszik vala. Jézus pedig felemelé szemeit az égre, és monda: Atyám, hálát adok néked, hogy meghallgattál engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, 'Tudtam is én, hogy te mindenkor meghallgatsz engem; csak a körülálló sokaságért mondtam, hogy elhigyjék, hogy te küldtél engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, 'És mikor ezeket mondá, fenszóval kiálta: Lázár, jőjj ki!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, 'És kijöve a megholt, lábain és kezein kötelékekkel megkötözve, és az orczája kendővel vala leborítva. Monda nékik Jézus: Oldozzátok meg őt, és hagyjátok menni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, 'Sokan hivének azért ő benne ama zsidók közül, a kik Máriához mentek vala, és láták, a miket cselekedett vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, 'De némelyek azok közül elmenének a farizeusokhoz, és elbeszélék nékik, a miket Jézus cselekedett vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, 'Egybegyűjték azért a papifejedelmek és a farizeusok a főtanácsot, és mondának: Mit cselekedjünk? mert ez az ember sok csodát mível.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 48, 'Ha ekképen hagyjuk őt, mindenki hinni fog ő benne: és eljőnek majd a rómaiak és elveszik tőlünk mind e helyet, mind e népet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 49, 'Egy pedig ő közülök, Kajafás, a ki főpap vala abban az esztendőben, monda nékik: Ti semmit sem tudtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 50, 'Meg sem gondoljátok, hogy jobb nékünk, hogy egy ember haljon meg a népért, és az egész nép el ne vesszen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 51, 'Ezt pedig nem magától mondta: hanem mivelhogy abban az esztendőben főpap vala, jövendőt monda, hogy Jézus meg fog halni a népért;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 52, 'És nemcsak a népért, hanem azért is, hogy az Istennek elszéledt gyermekeit egybegyűjtse.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 53, 'Ama naptól azért azon tanakodának, hogy őt megöljék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 54, 'Jézus azért nem jár vala többé nyilvánosan a zsidók között, hanem elméne onnan a vidékre, a pusztához közel, egy Efraim nevű városba; és ott tartózkodék az ő tanítványaival.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 55, 'Közel vala pedig a zsidók husvétja: és sokan menének fel Jeruzsálembe a vidékről husvét előtt, hogy megtisztuljanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 56, 'Keresék azért Jézust, és szólnak vala egymással a templomban állva: Mit gondoltok, hogy nem jön-é fel az ünnepre?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 57, 'A papi fejedelmek pedig és a farizeusok is parancsolatot adának, hogy ha valaki megtudja, hogy hol van, jelentse meg, hogy őt megfogják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, 'Jézus azért hat nappal a husvét előtt méne Bethániába, a hol a megholt Lázár vala, a kit feltámasztott a halálból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'Vacsorát készítének azért ott néki, és Mártha szolgál vala fel; Lázár pedig egy vala azok közül, a kik együtt ülnek vala ő vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'Mária azért elővévén egy font igazi, drága nárdusból való kenetet, megkené a Jézus lábait, és megtörlé annak lábait a saját hajával; a ház pedig megtelék a kenet illatával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'Monda azért egy az ő tanítványai közül, Iskáriótes Júdás, Simonnak fia, a ki őt elárulandó vala:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, 'Miért nem adták el ezt a kenetet háromszáz dénáron, és miért nem adták a szegényeknek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'Ezt pedig nem azért mondá, mintha néki a szegényekre volna gondja, hanem mivelhogy tolvaj vala, és nála vala az erszény, és amit abba tesznek vala, elcsené.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'Monda azért Jézus: Hagyj békét néki; az én temetésem idejére tartogatta ő ezt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'Mert szegények mindenkor vannak veletek, én pedig nem mindenkor vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'A zsidók közül azért nagy sokaság értesült vala arról, hogy ő ott van: és oda menének nemcsak Jézusért, hanem hogy Lázárt is lássák, a kit feltámasztott a halálból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'A papifejedelmek pedig tanácskozának, hogy Lázárt is megöljék;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'Mivelhogy a zsidók közül sokan ő miatta menének oda és hivének a Jézusban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'Másnap a nagy sokaság, a mely az ünnepre jött vala, hallván, hogy Jézus Jeruzsálembe jő,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'Pálmaágakat vőn, és kiméne elébe, és kiált vala: Hozsánna: Áldott, a ki jő az Úrnak nevében, az Izráelnek ama királya!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, 'Találván pedig Jézus egy szamarat, felüle arra, a mint meg van írva:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, 'Ne félj Sionnak leánya: Ímé a te királyod jő, szamárnak vemhén ülve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'Ezeket pedig nem értették eleinte az ő tanítványai: hanem mikor megdicsőítteték Jézus, akkor emlékezének vissza, hogy ezek ő felőle vannak megírva, és hogy ezeket mívelték ő vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'A sokaság azért, a mely ő vele vala, mikor kihívta Lázárt a koporsóból és feltámasztotta őt a halálból, bizonyságot tőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'Azért is méne ő elébe a sokaság, mivel hallá, hogy ezt a csodát mívelte vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'Mondának azért a farizeusok egymás között: Látjátok-é, hogy semmit sem értek? Ímé, mind e világ ő utána megy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, 'Néhány görög is vala azok között, a kik felmenének, hogy imádkozzanak az ünnepen:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'Ezek azért a galileai Bethsaidából való Filephez menének, és kérék őt, mondván: Uram, látni akarjuk a Jézust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, 'Megy vala Filep és szóla Andrásnak, és viszont András és Filep szóla Jézusnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, 'Jézus pedig felele nékik, mondván: Eljött az óra, hogy megdicsőíttessék az embernek Fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, 'Bizony, bizony mondom néktek: Ha a földbe esett gabonamag el nem hal, csak egymaga marad; ha pedig elhal, sok gyümölcsöt terem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, 'A ki szereti a maga életét, elveszti azt; és a ki gyűlöli a maga életét e világon, örök életre tartja meg azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, 'A ki nékem szolgál, engem kövessen; és a hol én vagyok, ott lesz az én szolgám is: és a ki nékem szolgál, megbecsüli azt az Atya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, 'Most az én lelkem háborog; és mit mondjak? Atyám, ments meg engem ettől az órától. De azért jutottam ez órára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 28, 'Atyám, dicsőítsd meg a te nevedet! Szózat jöve azért az égből: Meg is dicsőítettem, és újra megdicsőítem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 29, 'A sokaság azért, a mely ott állt és hallotta vala, azt mondá, hogy mennydörgött; mások mondának: Angyal szólt néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 30, 'Felele Jézus és monda: Nem én érettem lőn e szó, hanem ti érettetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 31, 'Most van e világ kárhoztatása; most vettetik ki e világ fejedelme:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 32, 'És én, ha felemeltetem e földről, mindeneket magamhoz vonszok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 33, 'Ezt pedig azért mondá, hogy megjelentse, milyen halállal kell meghalnia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 34, 'Felele néki a sokaság: Mi azt hallottuk a törvényből, hogy a Krisztus örökké megmarad: hogyan mondod hát te, hogy az ember Fiának fel kell emeltetnie? Kicsoda ez az ember Fia?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 35, 'Monda azért nékik Jézus: Még egy kevés ideig veletek van a világosság. Járjatok, a míg világosságotok van, hogy sötétség ne lepjen meg titeket: és a ki a sötétségben jár, nem tudja, hová megy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 36, 'Míg a világosságotok megvan, higyjetek a világosságban, hogy a világosság fiai legyetek. Ezeket mondá Jézus, és elmenvén, elrejtőzködék előlük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 37, 'És noha ő ennyi jelt tett vala előttük, mégsem hivének ő benne:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 38, 'Hogy beteljesedjék az Ésaiás próféta beszéde, a melyet monda: Uram, ki hitt a mi tanításunknak? és az Úr karja kinek jelentetett meg?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 39, 'Azért nem hihetnek vala, mert ismét monda Ésaiás:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 40, 'Megvakította az ő szemeiket, és megkeményítette az ő szívöket; hogy szemeikkel ne lássanak és szívökkel ne értsenek, és meg ne térjenek, és meg ne gyógyítsam őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 41, 'Ezeket mondá Ésaiás, a mikor látá az ő dicsőségét; és beszéle ő felőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 42, 'Mindazáltal a főemberek közül is sokan hivének ő benne: de a farizeusok miatt nem vallák be, hogy ki ne rekesztessenek a gyülekezetből:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 43, 'Mert inkább szerették az emberek dicséretét, mintsem az Istennek dicséretét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 44, 'Jézus pedig kiálta és monda: A ki hisz én bennem, nem én bennem hisz, hanem abban, a ki elküldött engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 45, 'És a ki engem lát, azt látja, a ki küldött engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 46, 'Én világosságul jöttem e világra, hogy senki ne maradjon a sötétségben, a ki én bennem hisz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 47, 'És ha valaki hallja az én beszédeimet és nem hisz, én nem kárhoztatom azt: mert nem azért jöttem, hogy kárhoztassam a világot, hanem hogy megtartsam a világot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 48, 'A ki megvet engem és nem veszi be az én beszédeimet, van annak, a ki őt kárhoztassa: a beszéd, a melyet szólottam, az kárhoztatja azt az utolsó napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 49, 'Mert én nem magamtól szóltam; hanem az Atya, a ki küldött engem, ő parancsolta nékem, hogy mit mondjak és mit beszéljek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 50, 'És tudom, hogy az ő parancsolata örök élet. A miket azért én beszélek, úgy beszélem, a mint az Atya mondotta vala nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'A husvét ünnepe előtt pedig, tudván Jézus, hogy eljött az ő órája, hogy átmenjen e világból az Atyához, mivelhogy szerette az övéit e világon, mindvégig szerette őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'És vacsora közben, a mikor az ördög belesugalta már Iskáriótes Júdásnak, a Simon fiának szívébe, hogy árulja el őt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'Tudván Jézus, hogy az Atya mindent hatalmába adott néki, és hogy ő az Istentől jött és az Istenhez megy,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'Felkele a vacsorától, leveté a felső ruháját; és egy kendőt vévén, körülköté magát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'Azután vizet tölte a medenczébe, és kezdé mosni a tanítványok lábait, és megtörleni a kendővel, a melylyel körül van kötve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'Méne azért Simon Péterhez; és az monda néki: Uram, te mosod-é meg az én lábaimat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'Felele Jézus és monda néki: A mit én cselekszem, te azt most nem érted, de ezután majd megérted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'Monda néki Péter: Az én lábaimat nem mosod meg soha! Felele néki Jézus: Ha meg nem moslak téged, semmi közöd sincs én hozzám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'Monda néki Simon Péter: Uram, ne csak lábaimat, hanem kezeimet és fejemet is!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'Monda néki Jézus: A ki megfürödött, nincs másra szüksége, mint a lábait megmosni, különben egészen tiszta; ti is tiszták vagytok, de nem mindnyájan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'Tudta ugyanis, hogy ki árulja el őt; azért mondá: Nem vagytok mindnyájan tiszták!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'Mikor azért megmosta azoknak lábait, és a felső ruháját felvette, újra leülvén, monda nékik: Értitek-é, hogy mit cselekedtem veletek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'Ti engem így hívtok: Mester, és Uram. És jól mondjátok, mert az vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'Azért, ha én az Úr és a Mester megmostam a ti lábaitokat, néktek is meg kell mosnotok egymás lábait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'Mert példát adtam néktek, hogy a miképen én cselekedtem veletek, ti is akképen cselekedjetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'Bizony, bizony mondom néktek: A szolga nem nagyobb az ő Uránál; sem a követ nem nagyobb annál, a ki azt küldte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'Ha tudjátok ezeket, boldogok lesztek, ha cselekszitek ezeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'Nem mindnyájatokról szólok; tudom én kiket választottam el; hanem hogy beteljesedjék az írás: A ki velem ette a kenyeret, a sarkát emelte fel ellenem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'Most megmondom néktek, mielőtt meglenne, hogy mikor meglesz, higyjétek majd, hogy én vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, 'Bizony, bizony mondom néktek: A ki befogadja, ha valakit elküldök, engem fogad be; a ki pedig engem befogad, azt fogadja be, a ki engem küldött.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, 'Mikor ezeket mondja vala Jézus, igen nyugtalankodék lelkében, s bizonyságot tőn, és monda: Bizony, bizony mondom néktek, hogy egy ti közületek elárul engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, 'A tanítványok ekkor egymásra tekintének bizonytalankodva, hogy kiről szól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, 'Egy pedig az ő tanítványai közül a Jézus kebelén nyugszik vala, a kit szeret vala Jézus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, 'Int azért ennek Simon Péter, hogy tudakozza meg, ki az, a kiről szól?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, 'Az pedig a Jézus kebelére hajolván, monda néki: Uram, ki az?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, 'Felele Jézus: Az, a kinek én a bemártott falatot adom. És bemártván a falatot, adá Iskáriótes Júdásnak, a Simon fiának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, 'És a falat után akkor beméne abba a Sátán. Monda azért néki Jézus: A mit cselekszel, hamar cselekedjed.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, 'Ezt pedig senki sem érté a leültek közül, miért mondta néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, 'Némelyek ugyanis állíták, mivelhogy az erszény Júdásnál vala, hogy azt mondá néki Jézus: Vedd meg, a mikre szükségünk van az ünnepre; vagy, hogy adjon valamit a szegényeknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, 'Az pedig, mihelyt a falatot elvevé, azonnal kiméne: vala pedig éjszaka.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, 'Mikor azért kiment vala, monda Jézus: Most dicsőítteték meg az embernek Fia, az Isten is megdicsőítteték ő benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, 'Ha megdicsőítteték ő benne az Isten, az Isten is megdicsőíti őt ő magában, és ezennel megdicsőíti őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, 'Fiaim, egy kevés ideig még veletek vagyok. Kerestek majd engem; de a miként a zsidóknak mondám, hogy: A hová én megyek, ti nem jöhettek; most néktek is mondom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, 'Új parancsolatot adok néktek, hogy egymást szeressétek; a mint én szerettelek titeket, úgy szeressétek ti is egymást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, 'Erről ismeri meg mindenki, hogy az én tanítványaim vagytok, ha egymást szeretni fogjátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, 'Monda néki Simon Péter: Uram, hová mégy? Felele néki Jézus: A hová én megyek, most én utánam nem jöhetsz; utóbb azonban utánam jössz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, 'Monda néki Péter: Uram, miért nem mehetek most utánad? Az életemet adom éretted!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, 'Felele néki Jézus: Az életedet adod érettem? Bizony, bizony mondom néked, nem szól addig a kakas, mígnem háromszor megtagadsz engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, 'Ne nyugtalankodjék a ti szívetek: higyjetek Istenben, és higyjetek én bennem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'Az én Atyámnak házában sok lakóhely van; ha pedig nem volna, megmondtam volna néktek. Elmegyek, hogy helyet készítsek néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'És ha majd elmegyek és helyet készítek néktek, ismét eljövök és magamhoz veszlek titeket; hogy a hol én vagyok, ti is ott legyetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'És hogy hová megyek én, tudjátok; az útat is tudjátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Monda néki Tamás: Uram, nem tudjuk hová mégy; mimódon tudhatjuk azért az útat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'Monda néki Jézus: Én vagyok az út, az igazság és az élet; senki sem mehet az Atyához, hanemha én általam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'Ha megismertetek volna engem, megismertétek volna az én Atyámat is; és mostantól fogva ismeritek őt, és láttátok őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Monda néki Filep: Uram, mutasd meg nékünk az Atyát, és elég nékünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'Monda néki Jézus: Annyi idő óta veletek vagyok, és még sem ismertél meg engem, Filep? a ki engem látott, látta az Atyát; mimódon mondod azért te: Mutasd meg nékünk az Atyát?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Nem hiszed-é, hogy én az Atyában vagyok, és az Atya én bennem van? A beszédeket, a melyeket én mondok néktek, nem magamtól mondom; hanem az Atya, a ki én bennem lakik, ő cselekszi e dolgokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'Higyjetek nékem, hogy én az Atyában vagyok, és az Atya én bennem van; ha pedig nem, magokért a cselekedetekért higyjetek nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'Bizony, bizony mondom néktek: A ki hisz én bennem, az is cselekszi majd azokat a cselekedeteket, a melyeket én cselekeszem; és nagyobbakat is cselekszik azoknál; mert én az én Atyámhoz megyek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'És akármit kértek majd az én nevemben, megcselekszem azt, hogy dicsőíttessék az Atya a Fiúban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'Ha valamit kértek az én nevemben, én megcselekszem azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'Ha engem szerettek, az én parancsolataimat megtartsátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'És én kérem az Atyát, és más vígasztalót ád néktek, hogy veletek maradjon mindörökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'Az igazságnak ama Lelkét: a kit a világ be nem fogadhat, mert nem látja őt és nem ismeri őt; de ti ismeritek őt, mert nálatok lakik, és bennetek marad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'Nem hagylak titeket árvákul; eljövök ti hozzátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'Még egy kevés idő és a világ nem lát engem többé; de ti megláttok engem: mert én élek, ti is élni fogtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'Azon a napon megtudjátok majd ti, hogy én az én Atyámban vagyok, és ti én bennem, és én ti bennetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'A ki ismeri az én parancsolataimat és megtartja azokat, az szeret engem; a ki pedig engem szeret, azt szereti az én Atyám, én is szeretem azt, és kijelentem magamat annak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'Monda néki Júdás (nem az Iskáriótes): Uram, mi dolog, hogy nékünk jelented ki magadat, és nem a világnak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'Felele Jézus és monda néki: Ha valaki szeret engem, megtartja az én beszédemet: és az én Atyám szereti azt, és ahhoz megyünk, és annál lakozunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'A ki nem szeret engem, nem tartja meg az én beszédeimet: és az a beszéd, a melyet hallotok, nem az enyém, hanem az Atyáé, a ki küldött engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, 'Ezeket beszéltem néktek, a míg veletek valék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, 'Ama vígasztaló pedig, a Szent Lélek, a kit az én nevemben küld az Atya, az mindenre megtanít majd titeket, és eszetekbe juttatja mindazokat, a miket mondottam néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'Békességet hagyok néktek; az én békességemet adom néktek: nem úgy adom én néktek, a mint a világ adja. Ne nyugtalankodjék a ti szívetek, se ne féljen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, 'Hallottátok, hogy én azt mondtam néktek: Elmegyek, és eljövök hozzátok. Ha szeretnétek engem, örvendeznétek, hogy azt mondtam: Elmegyek az Atyához; mert az én Atyám nagyobb nálamnál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, 'És most mondtam meg néktek, mielőtt meglenne: hogy a mikor majd meglesz, higyjetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, 'Nem sokat beszélek már veletek, mert jön a világ fejedelme: és én bennem nincsen semmije;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, 'De, hogy megtudja a világ, hogy szeretem az Atyát és úgy cselekszem, a mint az én Atyám parancsolta nékem: keljetek fel, menjünk el innen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, 'Én vagyok az igazi szőlőtő, és az én Atyám a szőlőműves.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'Minden szőlővesszőt, a mely én bennem gyümölcsöt nem terem, lemetsz; mindazt pedig, a mely gyümölcsöt terem, megtisztítja, hogy több gyümölcsöt teremjen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'Ti már tiszták vagytok ama beszéd által, a melyet szóltam néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'Maradjatok én bennem és én is ti bennetek. Miképen a szőlővessző nem teremhet gyümölcsöt magától, hanemha a szőlőtőkén marad; akképen ti sem, hanemha én bennem maradtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'Én vagyok a szőlőtő, ti a szőlővesszők: A ki én bennem marad, én pedig ő benne, az terem sok gyümölcsöt: mert nálam nélkül semmit sem cselekedhettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'Ha valaki nem marad én bennem, kivettetik, mint a szőlővessző, és megszárad; és egybe gyűjtik ezeket és a tűzre vetik, és megégnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'Ha én bennem maradtok, és az én beszédeim bennetek maradnak, kérjetek, a mit csak akartok, és meglesz az néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'Abban dicsőíttetik meg az én Atyám, hogy sok gyümölcsöt teremjetek; és legyetek nékem tanítványaim.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'A miképen az Atya szeretett engem, én is úgy szerettelek titeket: maradjatok meg ebben az én szeretetemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'Ha az én parancsolataimat megtartjátok, megmaradtok az én szeretetemben; a miképen én megtartottam az én Atyámnak parancsolatait, és megmaradok az ő szeretetében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, 'Ezeket beszéltem néktek, hogy megmaradjon ti bennetek az én örömem és a ti örömetek beteljék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'Ez az én parancsolatom, hogy szeressétek egymást, a miképen én szerettelek titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'Nincsen senkiben nagyobb szeretet annál, mintha valaki életét adja az ő barátaiért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'Ti az én barátaim vagytok, ha azokat cselekszitek, a miket én parancsolok néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'Nem mondalak többé titeket szolgáknak; mert a szolga nem tudja, mit cselekszik az ő ura; titeket pedig barátaimnak mondottalak; mert mindazt, a mit az én Atyámtól hallottam, tudtul adtam néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'Nem ti választottatok engem, hanem én választottalak titeket, és én rendeltelek titeket, hogy ti elmenjetek és gyümölcsöt teremjetek, és a ti gyümölcsötök megmaradjon; hogy akármit kértek az Atyától az én nevemben, megadja néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'Ezeket parancsolom néktek, hogy egymást szeressétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, 'Ha gyűlöl titeket a világ, tudjátok meg, hogy engem elébb gyűlölt ti nálatoknál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'Ha e világból volnátok, a világ szeretné azt, a mi az övé; de mivelhogy nem vagytok e világból, hanem én választottalak ki magamnak titeket e világból, azért gyűlöl titeket a világ.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, 'Emlékezzetek meg ama beszédekről, a melyeket én mondtam néktek: Nem nagyobb a szolga az ő uránál. Ha engem üldöztek, titeket is üldöznek majd; ha az én beszédemet megtartották, a tiéteket is megtartják majd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, 'De mindezt az én nevemért cselekszik veletek, mivelhogy nem ismerik azt, a ki küldött engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, 'Ha nem jöttem volna és nem beszéltem volna nékik, nem volna bűnük: de most nincs mivel menteniök az ő bűnöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, 'A ki engem gyűlöl, gyűlöli az én Atyámat is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, 'Ha ama cselekedeteket nem cselekedtem volna közöttük, a melyeket senki más nem cselekedett, nem volna bűnük; de most láttak is, gyűlöltek is, mind engem, mind az én Atyámat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, 'De azért lőn így, hogy beteljesedjék a mondás, a mely megiratott az ő törvényökben: Ok nélkül gyűlöltek engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, 'Mikor pedig eljő majd a Vígasztaló, a kit én küldök néktek az Atyától, az igazságnak Lelke, a ki az Atyától származik, az tesz majd én rólam bizonyságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, 'De ti is bizonyságot tesztek; mert kezdettől fogva én velem vagytok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, 'Ezeket beszéltem néktek, hogy meg ne botránkozzatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, 'A gyülekezetekből kirekesztenek titeket; sőt jön idő, hogy a ki öldököl titeket, mind azt hiszi, hogy isteni tiszteletet cselekszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'És ezeket azért cselekszik veletek, mert nem ismerték meg az Atyát, sem engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'Ezeket pedig azért beszéltem néktek, hogy a mikor eljő az az idő, megemlékezzetek róluk, hogy én mondtam néktek. De ezeket kezdettől fogva nem mondottam néktek, mivelhogy veletek valék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, 'Most pedig elmegyek ahhoz, a ki küldött engem; és senki sem kérdezi tőlem közületek: Hová mégy?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'Hanem, mivelhogy ezeket beszéltem néktek, a szomorúság eltöltötte a szíveteket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'De én az igazat mondom néktek: Jobb néktek, hogy én elmenjek: mert ha el nem megyek, nem jő el hozzátok a Vígasztaló: ha pedig elmegyek, elküldöm azt ti hozzátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'És az, mikor eljő, megfeddi a világot bűn, igazság és ítélet tekintetében:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'Bűn tekintetében, hogy nem hisznek én bennem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'És igazság tekintetében, hogy én az én Atyámhoz megyek, és többé nem láttok engem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'Ítélet tekintetében pedig, hogy e világnak fejedelme megítéltetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, 'Még sok mondani valóm van hozzátok, de most el nem hordozhatjátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'De mikor eljő amaz, az igazságnak Lelke, elvezérel majd titeket minden igazságra. Mert nem ő magától szól, hanem azokat szólja, a miket hall, és a bekövetkezendőket megjelenti néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'Az engem dicsőít majd, mert az enyémből vesz, és megjelenti néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'Mindaz, a mi az Atyáé, az enyém: azért mondám, hogy az enyémből vesz, és megjelenti néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, 'Egy kevés idő, és nem láttok engem; és ismét egy kevés idő, és megláttok majd engem: mert én az Atyához megyek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'Mondának azért az ő tanítványai közül egymásnak: Mi az, a mit nékünk mond: Egy kevés idő, és nem láttok engem; és ismét egy kevés idő, és megláttok majd engem; és: mert én az Atyához megyek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'Mondának azért: Mi az a kevés idő, a miről szól? Nem tudjuk, mit mond.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'Megérté azért Jézus, hogy őt akarnák megkérdezni, és monda nékik: Arról tudakozzátok-é egymást, hogy azt mondám: Egy kevés idő, és nem láttok engem; és ismét egy kevés idő, és megláttok majd engem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, 'Bizony, bizony mondom néktek, hogy sírtok és jajgattok ti, a világ pedig örül: ti szomorkodtok, hanem a ti szomorúságtok örömre fordul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'Az asszony mikor szűl, szomorúságban van, mert eljött az ő órája: de mikor megszűli az ő gyermekét, nem emlékezik többé a kínra az öröm miatt, hogy ember született e világra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'Ti is azért most ugyan szomorúságban vagytok, de ismét meglátlak majd titeket, és örülni fog a ti szívetek, és senki el nem veszi tőletek a ti örömeteket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'És azon a napon nem kérdeztek majd engem semmiről. Bizony, bizony mondom néktek, hogy a mit csak kérni fogtok az Atyától az én nevemben, megadja néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'Mostanáig semmit sem kértetek az Atyától az én nevemben: kérjetek és megkapjátok, hogy a ti örömetek teljes legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, 'Ezeket példázatokban mondottam néktek; de eljő az idő, mikor nem példázatokban beszélek majd néktek, hanem nyiltan beszélek néktek az Atyáról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'Azon a napon az én nevemben kértek majd: és nem mondom néktek, hogy én kérni fogom az Atyát ti érettetek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'Mert maga az Atya szeret titeket, mivelhogy ti szerettetek engem, és elhittétek, hogy én az Istentől jöttem ki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'Kijöttem az Atyától, és jöttem e világba: ismét elhagyom e világot, és elmegyek az Atyához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, 'Mondának néki az ő tanítványai: Ímé, most nyiltan beszélsz és semmi példázatot nem mondasz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, 'Most tudjuk, hogy te mindent tudsz, és nincs szükséged arra, hogy valaki téged megkérdezzen: erről hiszszük, hogy az Istentől jöttél ki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, 'Felele nékik Jézus: Most hiszitek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, 'Ímé eljő az óra, és immár eljött, hogy szétoszoljatok kiki az övéihez, és engem egyedül hagyjatok; de nem vagyok egyedül, mert az Atya velem van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, 'Azért beszéltem ezeket néktek, hogy békességetek legyen én bennem. E világon nyomorúságtok lészen; de bízzatok: és meggyőztem a világot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'Ezeket beszélte Jézus; és felemelé szemeit az égre, és monda: Atyám, eljött az óra; dicsőítsd meg a te Fiadat, hogy a te Fiad is dicsőítsen téged;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'A miként te hatalmat adtál néki minden testen, hogy örök életet adjon mindennek, a mit néki adtál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'Az pedig az örök élet, hogy megismerjenek téged, az egyedül igaz Istent, és a kit elküldtél, a Jézus Krisztust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'Én dicsőítettelek téged e földön: elvégeztem a munkát, a melyet reám bíztál, hogy végezzem azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'És most te dicsőíts meg engem, Atyám, te magadnál azzal a dicsőséggel, a melylyel bírtam te nálad a világ létele előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, 'Megjelentettem a te nevedet az embereknek, a kiket e világból nékem adtál: tiéid valának, és nékem adtad azokat, és a te beszédedet megtartották.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'Most tudták meg, hogy mindaz te tőled van, a mit nékem adtál:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'Mert ama beszédeket, a melyeket nékem adtál, ő nékik adtam; és ők befogadták, és igazán megismerték, hogy én tőled jöttem ki, és elhitték, hogy te küldtél engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'Én ezekért könyörgök: nem a világért könyörgök, hanem azokért, a kiket nékem adtál, mert a tiéid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, 'És az enyémek mind a tiéid, és a tiéid az enyémek: és megdicsőíttetem ő bennök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'És nem vagyok többé e világon, de ők a világon vannak, én pedig te hozzád megyek. Szent Atyám, tartsd meg őket a te nevedben, a kiket nékem adtál, hogy egyek legyenek, mint mi!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, 'Mikor velök valék a világon, én megtartám őket a te nevedben; a kiket nékem adtál, megőrizém, és senki el nem veszett közülök, csak a veszedelemnek fia, hogy az írás beteljesüljön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'Most pedig te hozzád megyek; és ezeket beszélem a világon, hogy ők az én örömemet teljesen bírják ő magokban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'Én a te ígédet nékik adtam; és a világ gyűlölte őket, mivelhogy nem e világból valók, a mint hogy én sem e világból vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'Nem azt kérem, hogy vedd ki őket e világból, hanem hogy őrizd meg őket a gonosztól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'Nem e világból valók, a mint hogy én sem e világból vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'Szenteld meg őket a te igazságoddal: A te ígéd igazság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'A miképen te küldtél engem e világra, úgy küldtem én is őket e világra;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'És én ő érettök oda szentelem magamat, hogy ők is megszenteltekké legyenek az igazságban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'De nemcsak ő érettök könyörgök, hanem azokért is, a kik az ő beszédökre hisznek majd én bennem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'Hogy mindnyájan egyek legyenek; a mint te én bennem, Atyám, és én te benned, hogy ők is egyek legyenek mi bennünk: hogy elhigyje a világ, hogy te küldtél engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, 'És én azt a dicsőséget, a melyet nékem adtál, ő nékik adtam, hogy egyek legyenek, a miképen mi egy vagyunk:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, 'Én ő bennök, és te én bennem: hogy tökéletesen egygyé legyenek, és hogy megismerje a világ, hogy te küldtél engem, és szeretted őket, a miként engem szerettél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, 'Atyám, a kiket nékem adtál, akarom, hogy a hol én vagyok, azok is én velem legyenek; hogy megláthassák az én dicsőségemet, a melyet nékem adtál: mert szerettél engem e világ alapjának felvettetése előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, 'Igazságos Atyám! És e világ nem ismert téged, de én ismertelek téged; és ezek megismerik, hogy te küldtél engem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, 'És megismertettem ő velök a te nevedet, és megismertetem; hogy az a szeretet legyen ő bennök, a mellyel engem szerettél, és én is ő bennök legyek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'Mikor ezeket mondta vala Jézus, kiméne az ő tanítványaival együtt túl a Kedron patakán, a hol egy kert vala, a melybe bemenének ő és az ő tanítványai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'Ismeré pedig azt a helyet Júdás is, a ki őt elárulja vala; mivelhogy gyakorta ott gyűlt egybe Jézus az ő tanítványaival.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'Júdás azért magához vevén a katonai csapatot, és a papi fejedelmektől és a farizeusoktól szolgákat, oda méne fáklyákkal, lámpásokkal és fegyverekkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'Jézus azért tudván mindazt, a mi reá következendő vala, előre méne, és monda azoknak: Kit kerestek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, 'Felelének néki: A názáreti Jézust. Monda nékik Jézus: Én vagyok. Ott állt pedig ő velök Júdás is, a ki elárulta őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'Mikor azért azt mondá nékik, hogy: Én vagyok; hátra vonulának és földre esének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'Ismét megkérdezé azért őket: Kit kerestek? És azok mondának: A názáreti Jézust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'Felele Jézus: Mondtam néktek, hogy én vagyok az. Azért, ha engem kerestek, ezeket bocsássátok el;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, 'Hogy beteljesüljön a beszéd, a melyet mondott: Azok közül, a kiket nékem adtál, senkit sem vesztettem el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'Simon Péter pedig, a kinek szablyája vala, kirántá azt, és megüté a főpap szolgáját, és levágá annak jobb fülét. A szolga neve pedig Málkus vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'Monda azért Jézus Péternek: Tedd hüvelyébe a te szablyádat; avagy nem kell-é kiinnom a pohárt, a melyet az Atya adott nékem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'A csapat azért és az ezredes és a zsidók szolgái megfogák Jézust, és megkötözék őt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'És vivék őt először Annáshoz; mert ipa vala ez Kajafásnak, a ki abban az esztendőben főpap vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'Kajafás pedig az vala, a ki tanácsolta vala a zsidóknak, hogy jobb, hogy egy ember veszszen el a népért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'Simon Péter pedig, és egy másik tanítvány követi vala Jézust. Ez a tanítvány pedig ismerős vala a főpappal, és beméne Jézussal együtt a főpap udvarába,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'Péter pedig kívül áll vala az ajtónál. Kiméne azért ama másik tanítvány, a ki a főpappal ismerős vala, és szóla az ajtóőrzőnek, és bevivé Pétert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'Szóla azért Péterhez az ajtóőrző leány: Nemde, te is ez ember tanítványai közül való vagy? Monda ő: Nem vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, 'A szolgák pedig és a poroszlók ott állnak vala, szítván a tüzet, mivelhogy hűvös vala, és melegszenek vala. Ott áll vala pedig Péter is ő velök együtt, és melegszik vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'A főpap azért kérdezé Jézust az ő tanítványai felől, és az ő tudománya felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'Felele néki Jézus: Én nyilván szólottam a világnak, én mindenkor tanítottam a zsinagógában és a templomban, a hol a zsidók mindenünnen összegyülekeznek; és titkon semmit sem szólottam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'Mit kérdesz engem? Kérdezd azokat, a kik hallották, mit szóltam nékik: ímé ők tudják, a miket nékik szólottam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'Mikor pedig ő ezeket mondja vala, egy a poroszlók közül, a ki ott áll vala, arczul üté Jézust, mondván: így felelsz-é a főpapnak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'Felele néki Jézus: Ha gonoszul szóltam, tégy bizonyságot a gonoszságról; ha pedig jól, miért versz engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, 'Elküldé őt Annás megkötözve Kajafáshoz, a főpaphoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'Simon Péter pedig ott áll vala és melegszik vala. Mondának azért néki: Nemde, te is ennek a tanítványai közül való vagy? Megtagadá ő, és monda: Nem vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, 'Monda egy a főpap szolgái közül, rokona annak, a kinek a fülét Péter levágta: Nem láttalak-e én téged ő vele együtt a kertben?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, 'Ismét megtagadá azért Péter; és a kakas azonnal megszólala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, 'Vivék azért Jézust Kajafástól a törvényházba. Vala pedig reggel. És ők nem menének be a törvényházba, hogy meg ne fertőztessenek, hanem hogy megehessék a husvétibárányt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, 'Kiméne azért Pilátus ő hozzájok, és monda: Micsoda vádat hoztok fel ez ember ellen?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, 'Felelének és mondának néki: Ha gonosztevő nem volna ez, nem adtuk volna őt a te kezedbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, 'Monda azért nékik Pilátus: Vigyétek el őt ti, és ítéljétek meg őt a ti törvényeitek szerint. Mondának azért néki a zsidók: Nékünk senkit sem szabad megölnünk;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, 'Hogy beteljesedjék a Jézus szava, a melyet monda, a mikor jelenti vala, hogy milyen halállal kell majd meghalnia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, 'Ismét beméne azért Pilátus a törvényházba, és szólítja vala Jézust, és monda néki: Te vagy a Zsidók királya?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, 'Felele néki Jézus: Magadtól mondod-é te ezt, vagy mások beszélték néked én felőlem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, 'Felele Pilátus: Avagy zsidó vagyok-e én? A te néped és a papifejedelmek adtak téged az én kezembe: mit cselekedtél?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, 'Felele Jézus: Az én országom nem e világból való. Ha e világból való volna az én országom, az én szolgáim vitézkednének, hogy át ne adassam a zsidóknak. Ámde az én országom nem innen való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, 'Monda azért néki Pilátus: Király vagy-é hát te csakugyan? Felele Jézus: Te mondod, hogy én király vagyok. Én azért születtem, és azért jöttem e világra, hogy bizonyságot tegyek az igazságról. Mindaz, a ki az igazságból való, hallgat az én szómra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, 'Monda néki Pilátus: Micsoda az igazság? És a mint ezt mondá, újra kiméne a zsidókhoz, és monda nékik: Én nem találok benne semmi bűnt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, 'Szokás pedig az nálatok, hogy elbocsássak néktek egyet a husvétünnepen: akarjátok-é azért, hogy elbocsássam néktek a zsidók királyát?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, 'Kiáltának azért viszont mindnyájan, mondván: Nem ezt, hanem Barabbást. Ez a Barabbás pedig tolvaj vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Akkor azért előfogá Pilátus Jézust, és megostoroztatá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'És a vitézek tövisből koronát fonván, a fejére tevék, és bíbor köntöst adának reá,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, 'És mondának: Üdvöz légy zsidók királya! És arczul csapdossák vala őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'Majd ismét kiméne Pilátus, és monda nékik: Ímé kihozom őt néktek, hogy értsétek meg, hogy nem találok benne semmi bűnt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'Kiméne azért Jézus a töviskoronát és a bíbor köntöst viselve. És monda nékik Pilátus: Ímhol az ember!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'Mikor azért látják vala őt a papifejedelmek és a szolgák, kiáltozának, mondván: Feszítsd meg, feszítsd meg! Monda nékik Pilátus: Vigyétek el őt ti és feszítsétek meg, mert én nem találok bűnt ő benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'Felelének néki a zsidók: Nékünk törvényünk van, és a mi törvényünk szerint meg kell halnia, mivelhogy Isten Fiává tette magát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'Mikor pedig ezt a beszédet hallotta Pilátus, még inkább megrémül vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'És ismét beméne a törvényházba, és szóla Jézusnak: Honnét való vagy te? De Jézus nem felelt néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'Monda azért néki Pilátus: Nékem nem szólsz-é? Nem tudod-é hogy hatalmam van arra, hogy megfeszítselek, és hatalmam van arra, hogy szabadon bocsássalak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'Felele Jézus: Semmi hatalmad sem volna rajtam, ha felülről nem adatott volna néked: nagyobb bűne van azért annak, a ki a te kezedbe adott engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'Ettől fogva igyekszik vala Pilátus őt szabadon bocsátani; de a zsidók kiáltozának, mondván: Ha ezt szabadon bocsátod, nem vagy a császár barátja; valaki magát királylyá teszi, ellene mond a császárnak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'Pilátus azért, a mikor hallja vala e beszédet, kihozá Jézust, és űle a törvénytevő székbe azon a helyen, a melyet Kőpadolatnak hívtak, zsidóul pedig Gabbathának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, 'Vala pedig a husvét péntekje; és mintegy hat óra. És monda a zsidóknak: Ímhol a ti királyotok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'Azok pedig kiáltoznak vala: Vidd el, vidd el, feszítsd meg őt! Monda nékik Pilátus: A ti királyotokat feszítsem meg? Felelének a papifejedelmek: Nem királyunk van, hanem császárunk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'Akkor azért nékik adá őt, hogy megfeszíttessék. Átvevék azért Jézust és elvivék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'És emelvén az ő keresztfáját, méne az úgynevezett Koponya helyére, a melyet héberül Golgothának hívnak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'A hol megfeszíték őt, és ő vele más kettőt, egyfelől, és másfelől, középen pedig Jézust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'Pilátus pedig czímet is íra, és feltevé a keresztfára. Ez vala pedig az írás: A NÁZÁRETI JÉZUS, A ZSIDÓK KIRÁLYA.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'Sokan olvasák azért e czímet a zsidók közül; mivelhogy közel vala a városhoz az a hely, a hol Jézus megfeszíttetett vala: és héberül, görögül és latinul vala az írva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'Mondának azért Pilátusnak a zsidók papifejedelmei: Ne írd: A zsidók királya; hanem hogy ő mondotta: A zsidók királya vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, 'Felele Pilátus: A mit megírtam, megírtam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, 'A vitézek azért, mikor megfeszítették Jézust, vevék az ő ruháit, és négy részre oszták, egy részt mindenik vitéznek, és a köntösét. A köntös pedig varrástalan vala, felülről mindvégig szövött.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, 'Mondának azért egymásnak: Ezt ne hasogassuk el, hanem vessünk sorsot reá, kié legyen. Hogy beteljesedjék az írás, a mely ezt mondja: Megosztoztak ruháimon, és a köntösömre sorsot vetettek. A vitézek tehát ezeket művelék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, 'A Jézus keresztje alatt pedig ott állottak vala az ő anyja, és az ő anyjának nőtestvére; Mária, a Kleopás felesége, és Mária Magdaléna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, 'Jézus azért, mikor látja vala, hogy ott áll az ő anyja és az a tanítvány, a kit szeret vala, monda az ő anyjának: Asszony, ímhol a te fiad!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, 'Azután monda a tanítványnak: Ímhol a te anyád! És ettől az órától magához fogadá azt az a tanítvány.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 28, 'Ezután tudván Jézus, hogy immár minden elvégeztetett, hogy beteljesedjék az írás, monda: Szomjúhozom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 29, 'Vala pedig ott egy eczettel teli edény. Azok azért szivacsot töltvén meg eczettel, és izsópra tévén azt, oda vivék az ő szájához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 30, 'Mikor azért elvette Jézus az eczetet, monda: Elvégeztetett! És lehajtván fejét, kibocsátá lelkét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 31, 'A zsidók pedig, hogy a testek szombaton át a keresztfán ne maradjanak, miután péntek vala, (mert annak a szombatnak napja nagy nap vala) kérék Pilátust, hogy törjék meg azoknak lábszárait és vegyék le őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 32, 'Eljövének azért a vitézek, és megtörék az elsőnek lábszárait és a másikét is, a ki ő vele együtt feszíttetett meg;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 33, 'Mikor pedig Jézushoz érének és látják vala, hogy ő már halott, nem törék meg az ő lábszárait;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 34, 'Hanem egy a vitézek közül dárdával döfé meg az ő oldalát, és azonnal vér és víz jöve ki abból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 35, 'És a ki látta, bizonyságot tett, és igaz az ő tanúbizonysága; és az tudja, hogy ő igazat mond, hogy ti is higyjetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 36, 'Mert azért lettek ezek, hogy beteljesedjék az írás: Az ő csontja meg ne törettessék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 37, 'Másutt ismét így szól az írás: Néznek majd arra, a kit általszegeztek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 38, 'Ezek után pedig kéré Pilátust az arimathiai József (a ki a Jézus tanítványa vala, de csak titokban, a zsidóktól való félelem miatt), hogy levehesse a Jézus testét. És megengedé Pilátus. Elméne azért és levevé a Jézus testét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 39, 'Eljöve pedig Nikodémus is (a ki éjszaka ment vala először Jézushoz), hozván mirhából és áloéból való kenetet, mintegy száz fontot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 40, 'Vevék azért a Jézus testét, és begöngyölgeték azt lepedőkbe illatos szerekkel együtt, a mint a zsidóknál szokás temetni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 41, 'Azon a helyen pedig, a hol megfeszítteték, vala egy kert, és a kertben egy új sír, a melybe még senki sem helyheztetett vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 42, 'A zsidók péntekje miatt azért, mivelhogy az a sír közel vala, abba helyhezteték Jézust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, 'A hétnek első napján pedig jó reggel, a mikor még sötétes vala, oda méne Mária Magdaléna a sírhoz, és látá, hogy elvétetett a kő a sírról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, 'Futa azért és méne Simon Péterhez és ama másik tanítványhoz, a kit Jézus szeret vala, és monda nékik: Elvitték az Urat a sírból, és nem tudjuk, hová tették őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, 'Kiméne azért Péter és a másik tanítvány, és menének a sírhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, 'Együtt futnak vala pedig mindketten: de ama másik tanítvány hamar megelőzé Pétert, és előbb juta a sírhoz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, 'És lehajolván, látá, hogy ott vannak a lepedők; mindazáltal nem megy vala be.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, 'Megjöve azután Simon Péter is nyomban utána, és beméne a sírba: és látá, hogy a lepedők ott vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, 'És a keszkenő, a mely az ő fején volt, nem együtt van a lepedőkkel, hanem külön összegöngyölítve egy helyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, 'Akkor aztán beméne a másik tanítvány is, a ki először jutott a sírhoz, és lát és hisz vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, 'Mert nem tudják vala még az írást, hogy fel kell támadnia a halálból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, 'Visszamenének azért a tanítványok az övéikhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, 'Mária pedig künn áll vala a sírnál sírva. A míg azonban siránkozék, behajol vala a sírba;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, 'És láta két angyalt fehér ruhában ülni, egyiket fejtől, másikat lábtól, a hol a Jézus teste feküdt vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, 'És mondának azok néki: Asszony mit sírsz? Monda nékik: Mert elvitték az én Uramat, és nem tudom, hova tették őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, 'És mikor ezeket mondotta, hátra fordula, és látá Jézust ott állani, és nem tudja vala, hogy Jézus az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, 'Monda néki Jézus: Asszony, mit sírsz? kit keressz? Az pedig azt gondolván, hogy a kertész az, monda néki: Uram, ha te vitted el őt, mondd meg nékem, hová tetted őt, és én elviszem őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, 'Monda néki Jézus: Mária! Az megfordulván, monda néki: Rabbóni! a mi azt teszi: Mester!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, 'Monda néki Jézus: Ne illess engem; mert nem mentem még fel az én Atyámhoz; hanem menj az én atyámfiaihoz és mondd nékik: Felmegyek az én Atyámhoz és a ti Atyátokhoz, és az én Istenemhez, és a ti Istenetekhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, 'Elméne Mária Magdaléna, hirdetvén a tanítványoknak, hogy látta az Urat, és hogy ezeket mondotta néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, 'Mikor azért estve vala, azon a napon, a hétnek első napján, és mikor az ajtók zárva valának, a hol egybegyűltek vala a tanítványok, a zsidóktól való félelem miatt, eljöve Jézus és megálla a középen, és monda nékik: Békesség néktek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, 'És ezt mondván, megmutatá nékik a kezeit és az oldalát. Örvendezének azért a tanítványok, hogy látják vala az Urat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, 'Ismét monda azért nékik Jézus: Békesség néktek! A miként engem küldött vala az Atya, én is akképen küldelek titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, 'És mikor ezt mondta, rájuk lehelle, és monda nékik: Vegyetek Szent Lelket:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, 'A kiknek bűneit megbocsátjátok, megbocsáttatnak azoknak; a kikéit megtartjátok, megtartatnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, 'Tamás pedig, egy a tizenkettő közül, a kit Kettősnek hívtak, nem vala ő velök, a mikor eljött vala Jézus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, 'Mondának azért néki a többi tanítványok: Láttuk az Urat. Ő pedig monda nékik: Ha nem látom az ő kezein a szegek helyeit, és be nem bocsátom ujjaimat a szegek helyébe, és az én kezemet be nem bocsátom az ő oldalába, semmiképen el nem hiszem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, 'És nyolcz nap múlva ismét benn valának az ő tanítványai, Tamás is ő velök. Noha az ajtó zárva vala, beméne Jézus, és megálla a középen és monda: Békesség néktek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, 'Azután monda Tamásnak: Hozd ide a te ujjadat és nézd meg az én kezeimet; és hozd ide a te kezedet, és bocsássad az én oldalamba: és ne légy hitetlen, hanem hívő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, 'És felele Tamás és monda néki: Én Uram és én Istenem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, 'Monda néki Jézus: Mivelhogy láttál engem, Tamás, hittél: boldogok, a kik nem látnak és hisznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, 'Sok más jelt is mívelt ugyan Jézus az ő tanítványai előtt, a melyek nincsenek megírva ebben a könyvben;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, 'Ezek pedig azért irattak meg, hogy higyjétek, hogy Jézus a Krisztus, az Istennek Fia, és hogy ezt hívén, életetek legyen az ő nevében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, 'Együtt valának Simon Péter, és Tamás, a kit Kettősnek hívtak, és Nátánáel, a galileai Kánából való, és a Zebedeus fiai, és más kettő is az ő tanítványai közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, 'Monda nékik Simon Péter: Elmegyek halászni. Mondának néki: Elmegyünk mi is te veled. Elmenének és azonnal a hajóba szállának; és azon az éjszakán nem fogtak semmit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, 'Mikor pedig immár reggeledék, megálla Jézus a parton; a tanítványok azonban nem ismerék meg, hogy Jézus van ott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, 'Monda azért nékik Jézus: Fiaim! Van-é valami ennivalótok? Felelének néki: Nincsen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, 'Ő pedig monda nékik: Vessétek a hálót a hajónak jobb oldala felől, és találtok. Oda veték azért, és kivonni már nem bírták azt a halaknak sokasága miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, 'Szóla azért az a tanítvány, a kit Jézus szeret vala, Péternek: Az Úr van ott! Simon Péter azért, a mikor hallja vala, hogy ott van az Úr, magára vevé az ingét (mert mezítelen vala), és beveté magát a tengerbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, 'A többi tanítványok pedig a hajón menének (mert nem messze valának a parttól, hanem mintegy kétszáz singnyire), és vonszszák vala a hálót a halakkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, 'Mikor azért a partra szállának, látják, hogy parázs van ott, és azon felül hal és kenyér.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, 'Monda nékik Jézus: Hozzatok a halakból, a melyeket most fogtatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, 'Felszálla Simon Péter, és kivoná a hálót a partra, a mely tele volt nagy halakkal, százötvenhárommal; és noha ennyi vala, nem szakadozik vala a háló.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, 'Monda nékik Jézus: Jertek, ebédeljetek. A tanítványok közül pedig senki sem meri vala tőle megkérdezni: Ki vagy te? Mivelhogy tudják vala, hogy az Úr ő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, 'Oda méne azért Jézus, és vevé a kenyeret és adá nékik, és hasonlóképen a halat is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, 'Ezzel már harmadszor jelent meg Jézus az ő tanítványainak, minekutána feltámadt a halálból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, 'Mikor aztán megebédelének, monda Jézus Simon Péternek: Simon, Jónának fia: jobban szeretsz-é engem ezeknél? Monda néki: Igen, Uram; te tudod, hogy szeretlek téged! Monda néki: Legeltesd az én bárányaimat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, 'Monda néki ismét másodszor is: Simon, Jónának fia, szeretsz-é engem? Monda néki: Igen, Uram; te tudod, hogy én szeretlek téged. Monda néki: Őrizd az én juhaimat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, 'Monda néki harmadszor is: Simon, Jónának fia, szeretsz-é engem? Megszomorodék Péter, hogy harmadszor is mondotta vala néki: Szeretsz-é engem? És monda néki: Uram, te mindent tudsz; te tudod, hogy én szeretlek téged. Monda néki Jézus: Legeltesd az én juhaimat!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, 'Bizony, bizony mondom néked, a mikor ifjabb valál, felövezéd magadat, és oda mégy vala, a hova akarád; mikor pedig megöregszel, kinyújtod a te kezedet és más övez fel téged, és oda visz, a hová nem akarod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, 'Ezt pedig azért mondá, hogy jelentse, milyen halállal dicsőíti majd meg az Istent. És ezt mondván, szóla néki: Kövess engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, 'Péter pedig megfordulván, látja, hogy követi az a tanítvány, a kit szeret vala Jézus, a ki nyugodott is ama vacsora közben az ő kebelén és mondá: Uram! ki az, a ki elárul téged?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, 'Ezt látván Péter, monda Jézusnak: Uram, ez pedig mint lészen?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, 'Monda néki Jézus: Ha akarom, hogy ő megmaradjon, a míg eljövök, mi közöd hozzá? Te kövess engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, 'Kiméne azért e beszéd az atyafiak közé, hogy az a tanítvány nem hal meg: pedig Jézus nem mondta néki, hogy nem hal meg; hanem: Ha akarom, hogy ez megmaradjon, a míg eljövök, mi közöd hozzá?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, 'Ez az a tanítvány, a ki bizonyságot tesz ezekről, és a ki megírta ezeket, és tudjuk, hogy az ő bizonyságtétele igaz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, 'De van sok egyéb is, a miket Jézus cselekedett vala, a melyek, ha egyenként megiratnának, azt vélem, hogy maga a világ sem foghatná be a könyveket, a melyeket írnának. Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'Első könyvemet írtam, Theofilus, mindazokról, a miket kezdett Jézus cselekedni és tanítani,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'Mind a napig, melyen fölviteték, minekutána parancsolatokat adott a Szent Lélek által az apostoloknak, kiket választott vala magának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'Kiknek az ő szenvedése után sok jel által meg is mutatta, hogy ő él, negyven napon át megjelenvén nékik, és szólván az Isten országára tartozó dolgokról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'És velök összejövén, meghagyá nékik, hogy el ne menjenek Jeruzsálemből, hanem várják be az Atyának ígéretét, melyet úgymond, hallottatok tőlem:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'Hogy János ugyan vízzel keresztelt, ti azonban Szent Lélekkel fogtok megkereszteltetni nem sok nap mulva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'Mikor azért azok egybegyűltek, megkérdék őt, mondván: Uram, avagy nem ez időben állítod-é helyre az országot Izráelnek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'Monda pedig nékik: Nem a ti dolgotok tudni az időket vagy alkalmakat, melyeket az Atya a maga hatalmába helyheztetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'Hanem vesztek erőt, minekutána a Szent Lélek eljő reátok: és lesztek nékem tanúim úgy Jeruzsálemben, mint az egész Júdeában és Samariában és a földnek mind végső határáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'És mikor ezeket mondotta, az ő láttokra felemelteték, és felhő fogá el őt szemeik elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'És a mint szemeiket az égre függesztették, mikor ő elméne, ímé két férfiú állott meg mellettük fehér ruhában,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'Kik szóltak is: Galileabeli férfiak, mit állotok nézve a mennybe? Ez a Jézus, a ki felviteték tőletek a mennybe, akképen jő el, a miképen láttátok őt felmenni a mennybe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'Akkor megtérének Jeruzsálembe a hegyről, mely hívatik Olajfák hegyének, mely Jeruzsálem mellett van, egy szombatnapi járóföldre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'És mikor bementek, felmenének a felsőházba, a hol szállva valának: Péter és Jakab, János és András, Filep és Tamás, Bertalan és Máté, Jakab, az Alfeus fia, és Simon, a zelóta, és Júdás, a Jakab fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Ezek mindnyájan egy szívvel-lélekkel foglalatosak valának az imádkozásban és a könyörgésben, az asszonyokkal és Máriával, Jézusnak anyjával, és az ő atyjafiaival együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'És azokban a napokban felkelvén Péter a tanítványok között, monda (vala pedig ott együtt mintegy százhúsz főnyi sokaság):');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, 'Atyámfiai, férfiak, szükség volt betelni annak az írásnak, melyet megjövendölt a Szent Lélek Dávid szája által Júdás felől, ki vezetőjük lőn azoknak, a kik megfogták Jézust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'Mert mi közénk számláltatott, és elnyerte ennek a szolgálatnak az osztályrészét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, '(Ez hát mezőt szerze hamisságának béréből; és alá zuhanván, elhasadt középen, és minden belső része kiomlott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, 'És ez tudtokra lőn mindazoknak, kik Jeruzsálemben lakoznak; úgy hogy az a mező tulajdon nyelvökön Akeldamának, azaz Vérmezőnek neveztetett el.)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, 'Mert meg van írva a Zsoltárok könyvében: Legyen az ő lakóhelye puszta, és ne legyen lakó abban. És: Az ő püspökségét más vegye el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, 'Szükség azért, hogy azok közül a férfiak közül, a kik velünk együtt jártak minden időben, míg az Úr Jézus közöttünk járt-kelt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, 'A János keresztségétől kezdve mind a napig, melyen fölviteték tőlünk, azok közül egy az ő feltámadásának bizonysága legyen mivelünk egyetemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, 'Állatának azért elő kettőt, Józsefet, ki hivatik Barsabásnak, kinek mellékneve Justus vala, és Mátyást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, 'És imádkozván, mondának: Te, Uram, ki mindeneknek szívét ismered, mutasd meg a kettő közül egyiket, a kit kiválasztottál,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, 'Hogy elnyerje az osztályrészét e szolgálatnak és apostolságnak, melytől eltévelyedék Júdás, hogy az ő saját helyére jusson.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, 'Sorsot vetének azért reájok, és esék a sors Mátyásra, és a tizenegy apostol közé számláltaték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'És mikor a pünkösd napja eljött, mindnyájan egyakarattal együtt valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'És lőn nagy hirtelenséggel az égből mintegy sebesen zúgó szélnek zendülése, és eltelé az egész házat, a hol ülnek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'És megjelentek előttük kettős tüzes nyelvek és üle mindenikre azok közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'És megtelének mindnyájan Szent Lélekkel, és kezdének szólni más nyelveken, a mint a Lélek adta nékik szólniok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'Lakoznak vala pedig Jeruzsálemben zsidók, istenfélő férfiak, minden nép közül, melyek az ég alatt vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'Minekutána pedig ez a zúgás lőn, egybegyűle a sokaság és megzavarodék, mivelhogy mindegyik a maga nyelvén hallá őket szólni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'Álmélkodnak pedig mindnyájan és csodálkoznak vala, mondván egymásnak: Nemde nem Galileusok-é ezek mindnyájan, a kik szólnak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'Mimódon halljuk hát őket, kiki közülünk a saját nyelvén, a melyben születtünk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'Párthusok és médek és elámiták, és kik lakozunk Mesopotámiában, Júdeában és Kappadócziában, Pontusban és Ázsiában,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'Frigiában és Pamfiliában, Égyiptomban és Libiának tartományiban, mely Cziréne mellett van, és a római jövevények, mind zsidók, mind prozelitusok,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'Krétaiak és arabok, halljuk a mint szólják a mi nyelvünkön az Istennek nagyságos dolgait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'Álmélkodnak vala pedig mindnyájan és zavarban valának, egymásnak ezt mondván: Vajjon mi akar ez lennie?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'Mások pedig csúfolódva mondának: Édes bortól részegedtek meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'Péter azonban előállván a tizenegygyel, felemelé szavát, és szóla nékik: Zsidó férfiak és mindnyájan, kik lakoztok Jeruzsálemben, legyen ez néktek tudtotokra, és vegyétek füleitekbe az én beszédimet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'Mert nem részegek ezek, a mint ti állítjátok; hiszen a napnak harmadik órája van;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'Hanem ez az, a mi megmondatott Jóel prófétától:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, 'És lészen az utolsó napokban, ezt mondja az Isten, kitöltök az én Lelkemből minden testre: és prófétálnak a ti fiaitok és leányaitok, és a ti ifjaitok látásokat látnak, és a ti véneitek álmokat álmodnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, 'És épen az én szolgáimra és az én szolgálóleányaimra is kitöltök azokban a napokban az én Lelkemből, és prófétálnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, 'És tészek csudákat az égben odafenn, és jeleket a földön idelenn, vért, tüzet és füstnek gőzölgését.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, 'A nap sötétséggé változik, és a hold vérré, minekelőtte eljő az Úrnak ama nagy és fényes napja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, 'És lészen, hogy mindaz, a ki az Úrnak nevét segítségül hívja, megtartatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, 'Izráelita férfiak, halljátok meg e beszédeket: A názáreti Jézust, azt a férfiút, a ki Istentől bizonyságot nyert előttetek erők, csudatételek és jelek által, melyeket ő általa cselekedett Isten ti köztetek, a mint magatok is tudjátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, 'Azt, a ki Istennek elvégezett tanácsából és rendeléséből adatott halálra, megragadván, gonosz kezeitekkel keresztfára feszítve megölétek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 24, 'Kit az Isten feltámasztott, a halál fájdalmait megoldván; mivelhogy lehetetlen volt néki attól fogvatartatnia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 25, 'Mert Dávid ezt mondja ő róla: Magam előtt láttam az Urat mindenkor, mert ő nékem jobb kezem felől van, hogy meg ne tántorodjam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 26, 'Annakokáért örvendezett az én szívem, és vígadott az én nyelvem; annakfelette az én testem is reménységben nyugszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 27, 'Mert nem hagyod az én lelkemet a sírban, és nem engeded, hogy a te szented rothadást lásson.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 28, 'Megjelentetted nékem az életnek útait; betöltesz engem örömmel a te orczád előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 29, 'Atyámfiai férfiak, szabad nyilván szólanom ti előttetek Dávid pátriárkáról, hogy ő megholt és eltemettetett, és az ő sírja mind e mai napig minálunk van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 30, 'Próféta lévén azért, és tudván, hogy az Isten néki esküvéssel megesküdött, hogy majd az ő ágyékának gyümölcséből támasztja a Krisztust test szerint, hogy helyheztesse az ő királyi székibe,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 31, 'Előre látván ezt, szólott a Krisztus feltámadásáról, hogy az ő lelke nem hagyatott a sírban, sem az ő teste rothadást nem látott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 32, 'Ezt a Jézust feltámasztotta az Isten, minek mi mindnyájan tanúbizonyságai vagyunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 33, 'Annakokáért az Istennek jobbja által felmagasztaltatván, és a megígért Szent Lelket megnyervén az Atyától, kitöltötte ezt, a mit ti most láttok és hallotok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 34, 'Mert nem Dávid ment fel a mennyországba; hiszen ő maga mondja: Monda az Úr az én Uramnak: Ülj az én jobbkezem felől,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 35, 'Míglen vetem a te ellenségeidet lábaid alá zsámolyul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 36, 'Bizonynyal tudja meg azért Izráelnek egész háza, hogy Úrrá és Krisztussá tette őt az Isten, azt a Jézust, a kit ti megfeszítettetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 37, 'Ezeket pedig mikor hallották, szívökben megkeseredének, és mondának Péternek és a többi apostoloknak: Mit cselekedjünk, atyámfiai, férfiak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 38, 'Péter pedig monda nékik: Térjetek meg és keresztelkedjetek meg mindnyájan a Jézus Krisztusnak nevében a bűnöknek bocsánatjára; és veszitek a Szent Lélek ajándékát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 39, 'Mert néktek lett az ígéret és a ti gyermekeiteknek, és mindazoknak, kik messze vannak, valakiket csak elhív magának az Úr, a mi Istenünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 40, 'Sok egyéb beszéddel is buzgón kéri és inti vala őket, mondván: Szakaszszátok el magatokat e gonosz nemzetségtől!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 41, 'A kik azért örömest vevék az ő beszédét, megkeresztelkedének; és hozzájuk csatlakozék azon a napon mintegy háromezer lélek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 42, 'És foglalatosok valának az apostolok tudományában és a közösségben, a kenyérnek megtörésében és a könyörgésekben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 43, 'Támada pedig minden lélekben félelem, és az apostolok sok csudát és jelt tesznek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 44, 'Mindnyájan pedig, a kik hivének, együtt valának, és mindenük köz vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 45, 'És jószágukat és marháikat eladogaták, és szétosztogaták azokat mindenkinek, a mint kinek-kinek szüksége vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 46, 'És minden nap egyakarattal kitartva a templomban, és megtörve házanként a kenyeret, részesednek vala eledelben örömmel és tiszta szívvel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 47, 'Dícsérve az Istent, és az egész nép előtt kedvességet találva. Az Úr pedig minden napon szaporítja vala a gyülekezetet az idvezülőkkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, 'Péter és János pedig együtt mennek vala fel a templomba az imádkozásnak órájára, kilenczre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'És hoznak vala egy embert, ki az ő anyjának méhétől fogva sánta vala, kit minden nap le szoktak tenni a templom kapujánál, melyet Ékesnek neveznek, hogy kérjen alamizsnát azoktól, a kik bemennek a temlomba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'Ez mikor látta, hogy Péter és János a templomba akarnak bemenni, kére ő tőlük alamizsnát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'Péter pedig mikor szemeit reá vetette Jánossal egyben, monda: Nézz mi reánk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'Az annakokáért figyelmez vala reájok, remélvén, hogy valamit kap tőlük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'Péter pedig monda: Ezüstöm és aranyam nincsen nékem; hanem a mim van, azt adom néked: a názáreti Jézus Krisztus nevében, kelj fel és járj!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'És őt jobbkezénél fogva felemelé, és azonnal megerősödének az ő lábai és bokái.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'És felszökvén, megálla és jár vala és beméne ő velök a templomba, járkálva és szökdelve és dícsérve az Istent.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'És látá őt az egész nép, hogy jár és dícséri az Istent:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'És megismerék őt, hogy ő volt az, a ki alamizsnáért ült a templomnak Ékeskapujában; és megtelének csodálkozással és azon való álmélkodással, a mi történt vala ő vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'Mikor pedig ragaszkodék Péterhez és Jánoshoz az a sánta, a ki meggyógyult, az egész nép álmélkodva összefuta ő hozzájok a tornáczba, mely Salamonénak neveztetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'Mikor pedig ezt látta Péter, monda a népnek: Izráel férfiai, mit csodálkoztok ezen, vagy mit néztek mi reánk, mintha tulajdon erőnkkel vagy jámborságunkkal míveltük volna azt, hogy az járjon?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, 'Az Ábrahámnak, Izsáknak és Jákóbnak Istene, a mi atyáinknak Istene megdicsőítette az ő Fiát, Jézust, kit ti elárulátok, és megtagadátok Pilátus előtt, noha ő úgy ítélt, hogy elbocsátja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, 'Ti pedig azt a szentet és igazat megtagadátok és kívánátok, hogy a gyilkos ember bocsáttassék el néktek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, 'Az életnek fejedelmét pedig megölétek; kit az Isten feltámasztott a halálból, minek mi vagyunk bizonyságai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, 'És az ő nevében való hit által erősítette meg az ő neve ezt, a kit láttok és ismertek; és a hit, mely ő általa van, adta néki ezt az épséget mindnyájan a ti szemetek láttára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, 'De most, atyámfiai, tudom, hogy tudatlanságból cselekedtetek, miképen a ti fejedelmeitek is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, 'Az Isten pedig, a mikről eleve megmondotta minden ő prófétájának szája által, hogy a Krisztus elszenvedi, ekképen töltötte be.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, 'Bánjátok meg azért és térjetek meg, hogy eltöröltessenek a ti bűneitek, hogy így eljőjjenek a felüdülés idei az Úrnak színétől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, 'És elküldje a Jézus Krisztust, a ki néktek előre hirdettetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, 'Kit az égnek kell magába fogadnia mind az időkig, míglen újjá teremtetnek mindenek, a mikről szólott az Isten minden ő szent prófétájának szája által eleitől fogva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, 'Mert Mózes ezt mondotta az atyáknak: Prófétát támaszt néktek az Úr, a ti Istenetek a ti atyátokfiai közül, mint engem; azt hallgassátok mindenben, a mit csak szólánd néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, 'Lészen pedig, hogy minden lélek, valamely nem hallgatánd arra a prófétára, ki fog irtatni a nép közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, 'De a próféták is mindnyájan Sámueltől és a következőktől fogva, a kik csak szóltak, e napokról jövendöltek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, 'Ti vagytok a prófétáknak és a szövetségnek fiai, melyet Isten szerzett a mi atyáinkkal, mondván Ábrahámnak: És a te magodban megáldatnak a földnek nemzetségei mindnyájan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, 'Az Isten az ő Fiát, Jézust első sorban néktek támasztván, elküldé őt, hogy megáldjon titeket, mindegyikőtöket megtérítvén bűneitekből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'Míg ők azonban a néphez szólottak, oda léptek hozzájuk a papok és a templom felügyelője és a sadduczeusok,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'Neheztelve a miatt, hogy ők a népet tanítják, és hirdetik a Jézusban a halálból való feltámadást;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, 'És rájuk veték kezüket, és veték őket őrizet alá másnapig, mert már este vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'Sokan pedig azok közül, kik hallgaták az ígét, hivének; és lőn a férfiak száma mintegy ötezer.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'Lőn pedig, hogy másnapra egybegyűlének azoknak fejei, vénei és írástudói Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'És Annás, a főpap, és Kajafás és János és Sándor, és a kik csak főpapi nemzetségbeliek valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'És mikor őket a középre állaták, tudakozzák vala: Micsoda hatalommal, vagy micsoda név által cselekedtétek ti ezt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'Akkor Péter, Szent Lélekkel megtelve, monda nékik: Népnek fejedelmei és Izráelnek vénei!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'Ha e mai napon mi egy nyavalyás emberrel való jótétemény felől hallgattatunk ki, mi által gyógyult meg ez:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'Legyen tudtotokra mindnyájotoknak és az Izráel egész népének, hogy a názáretbeli Jézus Krisztusnak neve által, a kit ti megfeszítettetek, kit Isten feltámasztott halottaiból, az által áll ez ti előttetek épségben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'Ez ama kő, melyet ti építők megvetettetek, mely lett a szegeletnek fejévé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'És nincsen senkiben másban idvesség: mert nem is adatott emberek között az ég alatt más név, mely által kellene nékünk megtartatnunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, 'Mikor pedig látták Péternek és Jánosnak a szólásban való bátorságukat, és megértették, hogy írástudatlan és közönséges emberek, csodálkoznak vala; meg is ismerék őket, hogy a Jézussal voltak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'Mikor azonban látták, hogy a mely ember meggyógyult vala, ő velök együtt ott áll, semmit nem bírtak ellenök szólni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, 'Mikor pedig őket a gyűlésből kiküldötték, tanácskoztak maguk közt, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, 'Mit cselekedjünk ez emberekkel? Mert hogy nyilvánvaló csoda lőn általok, mindazoknak, kik Jeruzsálemben laknak, tudtokra van, és el nem tagadhatjuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, 'De hogy tovább ne terjedjen a nép között, fenyegetéssel fenyegessük meg őket, hogy többé egy embernek se szóljanak ebben a névben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, 'Azért beszólítván őket, megparancsolák nékik, hogy teljességgel ne szóljanak és ne tanítsanak a Jézus nevében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, 'Péter és János pedig felelvén, mondának nékik: Vajjon igaz dolog-é Isten előtt, rátok hallgatnunk inkább, hogynem Istenre, ítéljétek meg!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, 'Mert nem tehetjük, hogy a miket láttunk és hallottunk, azokat ne szóljuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, 'Amazok pedig nem találván semmi módot, hogyan büntessék meg őket, még megfenyegetvén, elbocsáták őket a nép miatt, mert mindnyájan dicsőítik vala az Istent azért, a mi történt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, 'Mert több vala negyven esztendősnél az az ember, kin a gyógyításnak ez a csodája lett vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, 'Mikor pedig elbocsáttattak, menének az övéikhez, és elbeszélék, a miket a főpapok és a vének mondottak nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, 'Ezek pedig mikor hallották, egy szívvel-lélekkel felemelék szavokat az Istenhez, és mondának: Urunk, te vagy az Isten, ki teremtetted a mennyet és a földet, a tengert és minden azokban levő dolgot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, 'Ki Dávidnak, a te szolgádnak szája által ezt mondottad: Miért zúgolódtak a pogányok, és gondoltak a népek hiábavalókat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, 'Felállottak a földnek királyai, és a fejedelmek egybegyűltek az Úr ellen és az ő Krisztusa ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, 'Mert bizony egybegyűltek a te szent Fiad, a Jézus ellen, a kit felkentél, Heródes és Ponczius Pilátus a pogányokkal és Izráel népével,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, 'Hogy véghezvigyék, a mikről a te kezed és a te tanácsod eleve elvégezte volt, hogy megtörténjenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, 'Most azért, Urunk, tekints az ő fenyegetéseikre: és adjad a te szolgáidnak, hogy teljes bátorsággal szólják a te beszédedet,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, 'A te kezedet kinyújtván gyógyításra; és hogy jelek és csodák történjenek a te szent Fiadnak, a Jézusnak neve által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, 'És minekutána könyörögtek, megmozdula a hely, a hol egybegyűltek; és betelének mindnyájan Szent Lélekkel, és az Isten beszédét bátorsággal szólják vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 32, 'A hívők sokaságának pedig szíve-lelke egy vala; és senki semmi marháját nem mondá magáénak, hanem nékik mindenök köz vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 33, 'És az apostolok nagy erővel tesznek vala bizonyságot az Úr Jézus feltámadásáról; és nagy kegyelem vala mindnyájukon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 34, 'Mert szűkölködő sem vala ő közöttük senki; mert valakik földek vagy házak birtokosai voltak, eladván, elhozák az eladottak árát,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 35, 'És letevék az apostolok lábainál: aztán elosztatott az egyesek közt, a mint kinek-kinek szüksége vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 36, 'József is, ki az apostoloktól Barnabásnak neveztetett el (a mi megmagyarázva annyi, mint Vígasztalás Fia), Lévita, származása szerint ciprusi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 37, 'Mivelhogy néki mezeje vala, eladván, a pénzt elhozá, és az apostolok lábainál letevé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'Egy ember azonban, névszerint Anániás, Safirával, az ő feleségével, eladá birtokát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'És félre tőn az árából, feleségének is tudtával, és valami részét elvivén, az apostoloknak lábai elé letevé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'Monda pedig Péter: Anániás, miért foglalta el a Sátán a te szívedet, hogy megcsald a Szent Lelket, és a mezőnek árából félre tégy?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'Nemde megmaradva néked maradt volna meg, és eladva a te hatalmadban volt? Miért hogy ezt a dolgot cselekedted szívedben? Nem embereknek hazudtál, hanem Istennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'Hallván pedig Anániás e szavakat, lerogyott és meghala; és mindenekben nagy félelem támada, kik ezeket hallják vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, 'Az ifjak pedig felkelvén, begöngyölék őt, és kivivén eltemeték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, 'Történt aztán mintegy három órai szünet múlva, hogy az ő felesége, nem tudva, mi történt, beméne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'Monda pedig néki Péter: Mondd meg nékem, vajjon ennyiért adtátok-é el a földet? Ő pedig monda: Igen, ennyiért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'Péter pedig monda néki: Miért hogy megegyeztetek, hogy az Úrnak lelkét megkísértsétek? Ímé a küszöbön vannak azoknak lábaik, a kik eltemették férjedet, és kivisznek téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, 'És azonnal összerogyott lábainál, és meghala; bemenvén pedig az ifjak, halva találák őt, és kivivén eltemeték férje mellé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, 'És támada nagy félelem az egész gyülekezetben és mindazokban, kik ezeket hallják vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, 'Az apostolok kezei által pedig sok jel és csoda lőn a nép között; és egyakarattal mindnyájan a Salamon tornáczában valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, 'Egyebek közül pedig senki sem mert közéjük elegyedni: hanem a nép magasztalá őket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, 'Hívők pedig mindinkább csatlakoztak az Úrhoz, úgy férfiaknak, mint asszonyoknak sokasága.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, 'Úgyannyira, hogy az utczákra hozák ki a betegeket, és letevék ágyakon és nyoszolyákon, hogy az arra menő Péternek csak árnyéka is érje valamelyiket közülök,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 16, 'És a szomszéd városok sokasága is Jeruzsálembe gyűlt, hozva betegeket és tisztátalan lelkektől gyötretteket: kik mind meggyógyulának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 17, 'De felkelvén a főpap és mind a kik vele valának, azaz a sadduczeusok felekezete, betelének irigységgel,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 18, 'És ráveték kezöket az apostolokra, és a közönséges tömlöczbe tevék őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 19, 'Hanem az Úrnak angyala éjszaka megnyitá a tömlöcz ajtaját, és kihozván őket, monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 20, 'Menjetek el, és felállván, hirdessétek a templomban a népnek ez életnek minden beszédit!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 21, 'Azok pedig ezt hallván, bemenének jó reggel a templomba, és tanítának. A főpap pedig elmenvén és a vele levők, egybehívák a gyűlést, és Izráel fiainak egész tanácsát, és küldének a tömlöczbe, hogy azokat előhozzák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 22, 'Mikor azonban a poroszlók oda mentek, nem találák őket a tömlöczben; visszatérvén tehát, megjelenték,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 23, 'Mondván: A tömlöczöt ugyan nagy erősen bezárva találtuk, és az őröket kívül az ajtó előtt állva; mikor azonban kinyitottuk, ott benn senkit sem találánk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 24, 'A mint pedig hallották e szavakat a pap és a templom felügyelője és a főpapok, zavarban voltak azok miatt, mi lehet ez?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 25, 'Eljövén pedig valaki, hírül adá nékik, mondván: Ímé, ama férfiak, kiket a tömlöczbe vetettetek, a templomban állanak és tanítják a népet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 26, 'Akkor elmenvén a felügyelő a poroszlókkal, előhozá őket erőszak nélkül; féltek ugyanis a néptől, hogy megkövezi őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 27, 'Előhozván pedig őket, állaták a tanács elé; és megkérdé őket a főpap,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 28, 'Mondván: Nem megparancsoltuk-é néktek parancsolattal, hogy ne tanítsatok ebben a névben? És ímé betöltöttétek Jeruzsálemet tudományotokkal, és mi reánk akarjátok hárítani annak az embernek vérét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 29, 'Felelvén pedig Péter és az apostolok, mondának: Istennek kell inkább engedni, hogynem az embereknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 30, 'A mi atyáinknak Istene feltámasztotta Jézust, kit ti fára függesztve megölétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 31, 'Ezt az Isten fejedelemmé és megtartóvá emelte jobbjával, hogy adjon az Izráelnek bűnbánatot és bűnöknek bocsánatát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 32, 'És mi vagyunk néki bizonyságai ezen beszédek felől, és a Szent Lélek is, kit Isten adott azoknak, a kik néki engednek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 33, 'Azok pedig ezeket hallván, fogukat csikorgaták, és arról tanácskozának, hogy megölik őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 34, 'Felkelvén azonban a tanácsban egy farizeus, névszerint Gamáliel, az egész nép előtt tisztelt törvénytudó, parancsolá, hogy egy kis időre vezessék ki az apostolokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 35, 'És monda azoknak: Izráel férfiai, vigyázzatok magatokra ez emberekkel szemben, mit akartok cselekedni!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 36, 'Mert ez időnek előtte felkelt Theudás, azt mondván, hogy ő valaki, kihez mintegy négyszáz embernyi tömeg csatlakozott; ő megöletett, és mindnyájan, a kik csak követték őt, eloszlottak és semmivé lettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 37, 'Ezután felkelt ama Galileus Júdás az összeírás idején, és sok népet maga után csábított: ez is elveszett; és mindazok, a kik őt követték, szétszórattak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 38, 'Mostanra nézve is mondom néktek, álljatok el ez emberektől, és hagyjatok békét nékik: mert ha emberektől van e tanács, vagy e dolog, semmivé lesz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 39, 'Ha pedig Istentől van, ti fel nem bonthatjátok azt; nehogy esetleg Isten ellen harczolóknak is találtassatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 40, 'Engedének azért néki; és miután előszólították az apostolokat, megveretvén, megparancsolák, hogy a Jézus nevében ne szóljanak, és elbocsáták őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 41, 'Ők annakokáért örömmel menének el a tanács elől, hogy méltókká tétettek arra, hogy az ő nevéért gyalázattal illettessenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 42, 'És mindennap a templomban és házanként nem szűnnek vala meg tanítani és hirdetni Jézust, a Krisztust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'Azokban a napokban pedig, mikor a tanítványok szaporodának, támada a görög zsidók közt panaszolkodás a héberek ellen, hogy az ő közülük való özvegyasszonyok mellőztetnek a mindennapi szolgálatban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'Annakokáért a tizenkettő egybegyűjtvén a tanítványok sokaságát, mondának: Nem helyes, hogy mi az Isten ígéjét elhagyjuk és az asztalok körül szolgáljunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, 'Válaszszatok azért, atyámfiai, ti közületek hét férfiút, kiknek jó bizonyságuk van, kik Szent Lélekkel és bölcseséggel teljesek, kiket erre a foglalatosságra beállítsunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, 'Mi pedig foglalatosok maradunk a könyörgésben és az ígehirdetés szolgálatában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, 'És tetszék e beszéd az egész sokaságnak: és kiválaszták Istvánt, ki hittel és Szent Lélekkel teljes férfiú vala, Filepet, Prokhórust, Nikánórt, Timónt, Párménást és Nikolaust, ki Antiókhiából való prozelitus vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, 'Kiket állatának az apostolok elébe; és miután imádkoztak, kezeiket reájok veték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'És az Isten ígéje növekedék; és sokasodék nagyon a tanítványok száma Jeruzsálemben; és a papok közül is nagy sokan követék a hitet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'István pedig teljes lévén hittel és erővel, nagy csodákat és jeleket cselekszik vala a nép között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'Előállának azonban némelyek ahhoz a zsinagógához tartozók közül, mely a szabadosokénak, Czirénebeliekének, Alexandriabeliekének és a Czilicziából és Ázsiából valókénak neveztetett, kik Istvánnal vetekednek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'De nem állhattak ellene a bölcseségnek és a Léleknek, mely által szól vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'Akkor felbujtottak valami embereket, kik mondának: Hallottuk őt káromló beszédeket szólni Mózes ellen és az Isten ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'És felzendíték a népet, a véneket és az írástudókat; és reá rohanván, magukkal ragadák őt, és vivék a tanács elé;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'És állatának hamis tanúkat, kik mondának: Ez az ember nem szűnik meg káromló beszédeket szólni e szent hely ellen és a törvény ellen:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'Mert hallottuk, a mint azt mondá, hogy az a názáreti Jézus ezt a helyet elrontja, és megváltoztatja a czerimóniákat, melyeket adott nékünk Mózes.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'És szemeiket reá vetvén a tanácsban űlők mindnyájan, olyannak láták az ő orczáját, mint egy angyalnak orczáját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, 'Monda pedig a főpap: Vajjon így vannak-é hát ezek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, 'Ő pedig monda: Férfiak, atyámfiai és atyák, halljátok meg! A dicsőségnek Istene megjelenék a mi atyánknak, Ábrahámnak, mikor Mezopotámiában vala, minekelőtte Háránban lakott,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, 'És monda néki: Eredj ki a te földedből és a te nemzetséged közül, és jer arra a földre, a melyet mutatok néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, 'Akkor kimenvén a Káldeusok földéből, lakozék Háránban: és onnét, minekutána megholt az ő atyja, kihozta őt e földre, a melyen ti most laktok:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, 'És nem adott néki abban örökséget csak egy lábnyomnyit is: és azt ígérte, hogy néki adja azt birtokul és az ő magvának ő utána, holott nem vala néki gyermeke.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, 'Szólt pedig az Isten akképen, hogy az ő magva zsellér lészen idegen földön, és szolgálat alá vetik azt, és nyomorgatják, négyszáz esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, 'De azt a népet, melynek szolgálnak, én megítélem, monda az Isten: és ezek után kijőnek, és szolgálnak nékem e helyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, 'És adta néki a körülmetélés szövetségét: és így nemzé Izsákot, és körülmetélé őt nyolczadnapon; és Izsák Jákóbot, és Jákób a tizenkét pátriárkhát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, 'A pátriárkhák pedig irígységből eladák Józsefet Égyiptomba; de Isten vele vala,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, 'És megszabadítá őt minden nyomorúságából, és ada néki kedvességet és bölcseséget a Faraó előtt, Égyiptom királya előtt, ki őt Égyiptom fölé és az ő egész háza fölé kormányzóul állatá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, 'Következék pedig éhség Égyiptom és Kanaán egész földére, és nagy nyomorúság; és nem találnak vala eledelt a mi atyáink.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, 'Mikor pedig meghallotta Jákób, hogy Égyiptomban van gabona, elküldé először a mi atyáinkat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, 'És második alkalommal fölismerék Józsefet testvérei, és a Faraó megtudá a József nemzetségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, 'És József elküldvén, magához hívatá az ő atyját, Jákóbot, és egész hetvenöt lélekből álló nemzetségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 15, 'Leméne azért Jákób Égyiptomba, és meghala ő és a mi atyáink;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 16, 'És elvitetének Sikembe, és helyheztetének a sírba, melyet Ábrahám vett vala ezüstpénzen, Emmórnak, a Sikem atyjának fiaitól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 17, 'Mikor pedig elközelgetett az ígéretnek ideje, melyet Isten esküvel ígért Ábrahámnak, megnevekedék a nép és megsokasodék Égyiptomban,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 18, 'Mindaddig, mígnem más király támada, ki nem ismeri vala Józsefet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 19, 'Ez a mi nemzetségünkkel álnokul bánva nyomorgatta a mi atyáinkat, hogy magzataikat kitétesse, hogy életben ne maradjanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 20, 'Akkor születék Mózes, és ékes vala az Isten előtt. Ez három hónapig atyja házában tartaték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 21, 'Mikor pedig kitétetett, a Faraó leánya felvevé, és felnevelé őt a saját fia gyanánt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 22, 'És Mózes taníttaték az Égyiptombeliek minden bölcseségére; és hatalmas vala beszédben és cselekedetben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 23, 'Mikor pedig negyvenéves kora betölt, eszébe jutott, hogy meglátogassa atyjafiait, az Izráel fiait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 24, 'És mikor látta, hogy egyik bántalommal illettetik, megoltalmazá, és az égyiptomi embert megölvén, bosszút álla azért, a ki bosszúsággal illettetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 25, 'És azt gondolá, hogy az ő atyjafiai megértik, hogy az Isten az ő keze által ád nékik szabadulást; de azok nem értették meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 26, 'Másnap meg olyankor jelent meg köztük, mikor összevesztek, és inté őket békességre, mondván: Férfiak, testvérek vagytok ti; miért illetitek egymást bosszúsággal?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 27, 'De az, a ki felebarátját bántalmazta, elutasítá őt magától, mondván: Kicsoda tett téged fejedelemmé és bíróvá mi rajtunk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 28, 'Csak nem akarsz engem is megölni, miképen megöléd tegnap az égyiptomit?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 29, 'E beszédre aztán Mózes elfuta és lőn jövevény a Midián földén, a hol két fia születék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 30, 'És negyven esztendő elteltével megjelenék néki a Sínai hegy pusztájában az Úrnak angyala csipkebokornak tüzes lángjában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 31, 'Mózes pedig mikor meglátta, elcsodálkozék a látáson. Mikor pedig oda méne, hogy megszemlélje, lőn az Úrnak szava ő hozzá:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 32, 'Én vagyok a te atyáidnak Istene, Ábrahámnak Istene, és Izsáknak Istene, és Jákóbnak Istene. Mózes pedig megrémülvén, nem meré megnézni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 33, 'Az Úr pedig monda néki: Oldozd le sarudat lábaidról; mert a hely, a melyen állasz, szent föld.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 34, 'Látván láttam az én népemnek nyomorúságát, mely Égyiptomban van, és az ő fohászkodásukat meghallgattam, és azért szállottam le, hogy őket megszabadítsam; most azért jőjj, elküldelek téged Égyiptomba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 35, 'Ezt a Mózest, a kit megtagadának, mondván: Ki tett téged fejedelemmé és bíróvá? ezt az Isten fejedelmül és szabadítóul küldé angyal keze által, a ki megjelent néki a csipkebokorban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 36, 'Ez hozta ki őket, csodákat és jeleket tévén Égyiptomnak földében és a Verestengeren és a pusztában negyven esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 37, 'Ez ama Mózes, ki az Izráel fiainak ezt mondotta: Prófétát támaszt néktek az Úr, a ti Istentek, a ti atyátokfiai közül, mint engem: azt hallgassátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 38, 'Ez az, a ki ott volt a gyülekezetben a pusztában a Sinai hegyen vele beszélő angyallal és a mi atyáinkkal: ki élő igéket vőn, hogy nékünk adja;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 39, 'A kinek nem akartak engedni a mi atyáink, hanem eltaszíták maguktól, és szívökben Égyiptom felé fordulának,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 40, 'Ezt mondván Áronnak: Csinálj nékünk isteneket, kik előttünk járjanak: mert ez a Mózes, ki minket Égyiptom földéből kihozott, nem tudjuk, mi történt ő vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 41, 'És borjúképet csinálának azokban a napokban, és áldozatot vivének a bálványnak, és gyönyörködének az ő kezeik csinálmányaiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 42, 'Az Isten pedig elfordula, és adá őket, hogy szolgáljanak az ég seregének; a mint meg van írva a próféták könyvében: Vajjon áldozati barmokat és áldozatokat hoztatok-é nékem negyven esztendeig a pusztában, Izráelnek háza?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 43, 'Sőt inkább hordoztátok a Molok sátorát, és a ti istenteknek, Remfánnak csillagát, a képeket, melyeket csináltatok, hogy azokat imádjátok: elviszlek azért titeket Babilónon túl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 44, 'A bizonyságnak sátora a mi atyáinknál volt a pusztában, a mint parancsolta az, a ki mondotta Mózesnek, hogy azt arra a mintára csinálja, melyet látott vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 45, 'Melyet a mi atyáink átvévén, be is hoztak Józsuéval, mikor birodalmukba vették a pogányokat, kiket kiűzött az Isten a mi atyáink színe elől, mind a Dávidnak napjaiig;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 46, 'Ki kegyelmet talált az Isten előtt, és könyörgött, hogy hajlékot találhasson a Jákób Istenének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 47, 'Salamon építe pedig néki házat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 48, 'De ama Magasságos nem kézzel csinált templomokban lakik, mint a próféta mondja:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 49, 'A menny nékem ülőszékem, a föld pedig az én lábaimnak zsámolya; micsoda házat építhettek nékem? azt mondja az Úr, vagy melyik az én nyugodalmamnak helye?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 50, 'Nem az én kezem csinálta-é mindezeket?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 51, 'Kemény nyakú és körülmetéletlen szívű és fülű emberek, ti mindenkor a Szent Léleknek ellene igyekeztek, mint atyáitok, ti azonképen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 52, 'A próféták közül kit nem üldöztek a ti atyáitok? és megölték azokat, a kik eleve hirdették amaz Igaznak eljövetelét: kinek ti most árulóivá és gyilkosaivá lettetek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 53, 'Kik a törvényt angyalok rendelésére vettétek, és nem tartottátok meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 54, 'Mikor pedig ezeket hallották, szívükben dühösködnek és fogaikat csikorgatják vala ő ellene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 55, 'Mivel pedig teljes vala Szent Lélekkel, a mennybe függesztvén szemeit, látá Istennek dicsőségét, és Jézust állani az Istennek jobbja felől,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 56, 'És monda: Ímé látom az egeket megnyilni, és az embernek Fiát az Isten jobbja felől állani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 57, 'Felkiáltván pedig nagy fenszóval, füleiket bédugák, és egyakarattal reá rohanának;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 58, 'És kiűzvén a városon kívül, megkövezék: a tanúbizonyságok pedig felsőruháikat egy Saulus nevezetű ifjú lábaihoz rakták le.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 59, 'Megkövezék azért Istvánt, ki imádkozik és ezt mondja vala: Uram Jézus, vedd magadhoz az én lelkemet!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 60, 'Térdre esvén pedig, nagy fenszóval kiálta: Uram, ne tulajdonítsd nékik e bűnt! És ezt mondván, elaluvék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, 'Saulus pedig szintén javallta az ő megöletését. És támada azon a napon nagy üldözés a jeruzsálemi gyülekezet ellen, és mindnyájan eloszlának Júdeának és Samáriának tájaira, az apostolokat kivéve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, 'Istvánt pedig eltakaríták kegyes férfiak, és nagy sírást tőnek ő rajta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, 'Saulus pedig pusztítá az anyaszentegyházat, házról-házra járva, és férfiakat és asszonyokat elővonszolva, tömlöczbe veti vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, 'Amazok annakokáért eloszolván, széjjeljártak, hirdetve az ígét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, 'És Filep lemenvén Samária városába, prédikálja vala nékik a Krisztust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, 'A sokaság pedig egy szívvel-lélekkel figyelmeze azokra, a miket Filep mondott, hallván és látván a jeleket, melyeket cselekedék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, 'Mert sokakból, kikben tisztátalan lelkek voltak, nagy hangon kiáltva kimenének; sok gutaütött és sánta pedig meggyógyula.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, 'És lőn nagy öröm abban a városban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, 'Egy Simon nevű ember pedig már előbb gyakorolta abban a városban az ördögi tudományt és elámította Samária népét, magát valami nagynak állítván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, 'Kire mindnyájan figyeltek, kicsinytől nagyig, mondván: Ez az Istennek ama nagy ereje!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, 'Azért figyeltek pedig rá, mert sok időn át az ördögi mesterségekkel elámította őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, 'De miután hittek Filepnek, a ki az Isten országára és a Jézus Krisztus nevére tartozó örvendetes dolgokat hirdeti vala, megkeresztelkedének mind férfiak, mind asszonyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, 'És Simon maga is hűn, és megkeresztelkedvén, Fileppel tarta; és látván, hogy jelek és nagy erők lesznek, álmélkodik vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, 'Mikor pedig meghallották a jeruzsálemi apostolok, hogy Samária bevette az Isten ígéjét, elküldék azokhoz Pétert és Jánost;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, 'Kik mikor lementek, könyörögtek érettük, hogy vegyenek Szent Lelket:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, 'Mert még senkire azok közül nem szállott rá, csak meg voltak keresztelve az Úr Jézus nevére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, 'Akkor kezeiket reájuk veték, és vőnek Szent Lelket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, 'Mikor pedig látta Simon, hogy az apostolok kézrátétele által adatik a Szent Lélek, megkínálá őket pénzzel,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, 'Mondván: Adjátok nékem is ezt a hatalmat, hogy valakire vetem kezeimet, Szent Lelket vegyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 20, 'De Péter monda néki: A te pénzed veled együtt veszszen el, mivel azt gondoltad, hogy az Istennek ajándéka pénzen megvehető.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 21, 'Nincsen néked részed, sem örökséged e dologban, mert a te szíved nem igaz az Isten előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 22, 'Térj meg azért ezen gonoszságodból, és kérjed az Istent, ha talán megbocsáttatik néked szívednek gondolatja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 23, 'Mert látom, hogy te keserűséges méregben és álnokságnak kötelékében leledzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 24, 'Felelvén pedig Simon, monda: Könyörögjetek ti énérettem az Úrnak, hogy semmi azokból, a miket mondtatok, reám ne jőjjön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 25, 'Azok annakokáért, minekutána bizonyságot tettek, és hirdették az Úrnak ígéjét, megtérének Jeruzsálembe, és a Samaritánusoknak sok falujában prédikálák az evangyéliomot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 26, 'Az Úrnak angyala pedig szóla Filepnek, mondván: Kelj fel és menj el dél felé, arra az útra, mely Jeruzsálemből Gázába megy alá. Járatlan ez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 27, 'És felkelvén, elméne. És ímé egy szerecsen férfiú, Kandakénak, a szerecsenek királyasszonyának hatalmas komornyikja, ki az ő egész kincstárának felügyelője vala, ki feljött imádkozni Jeruzsálembe;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 28, 'És visszatérőben volt és az ő szekerén ül vala, és olvasá Ésaiás prófétát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 29, 'Monda pedig a Lélek Filepnek: Járulj oda és csatlakozzál ehhez a szekérhez!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 30, 'Filep azért oda futamodván, hallá, a mint az Ésaiás prófétát olvassa vala. És monda: Vajjon érted-é, a mit olvasol?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 31, 'Ő pedig monda: Mimódon érthetném, ha csak valaki meg nem magyarázza nékem? És kéré Filepet, hogy felhágván, üljön mellé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 32, 'Az írásnak helye pedig, melyet olvasott, ez vala: Mint juh viteték mészárszékre, és mint a bárány az ő nyírője előtt néma, azonképen nem nyitotta fel az ő száját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 33, 'Az ő megaláztatásában az ő ítélete elvétetett, az ő nemzetségét pedig kicsoda sorolja el? mert elvétetik a földről az ő élete.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 34, 'Felelvén pedig a komornyik Filepnek, monda: Kérlek téged, kiről mondja ezt a próféta? Magáról-é, vagy más valakiről?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 35, 'Filep pedig száját megnyitván, és elkezdvén ezen az íráson, hirdeté néki a Jézust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 36, 'Mikor pedig menének az úton, jutának egy vízhez; és monda a komornyik: Ímhol a víz: mi gátol, hogy megkeresztelkedjem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 37, 'Filep pedig monda: Ha teljes szívből hiszel, meglehet. Az pedig felelvén, monda: Hiszem, hogy a Jézus Krisztus az Isten Fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 38, 'És megállítá a szekeret; és leszállának mindketten a vízbe, Filep és a komornyik; és megkeresztelé őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 39, 'Mikor pedig a vízből feljöttek, az Úrnak Lelke elragadá Filepet; és többé nem látta őt a komornyik, mert tovább méne az ő útján örömmel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 40, 'Filep pedig találtaték Azótusban; és széjjeljárva hirdeté az evangyéliomot minden városnak, míglen Czézáreába juta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, 'Saulus pedig még fenyegetéstől és öldökléstől lihegve az Úrnak tanítványai ellen, elmenvén a főpaphoz,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, 'Kére ő tőle leveleket Damaskusba a zsinagógákhoz, hogy ha talál némelyeket, kik ez útnak követői, akár férfiakat, akár asszonyokat, fogva vigye Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, 'És a mint méne, lőn, hogy közelgete Damaskushoz, és nagy hirtelenséggel fény sugárzá őt körül a mennyből:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, 'És ő leesvén a földre, halla szózatot, mely ezt mondja vala néki: Saul, Saul, mit kergetsz engem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, 'És monda: Kicsoda vagy, Uram? Az Úr pedig monda: Én vagyok Jézus, a kit te kergetsz: nehéz néked az ösztön ellen rúgódoznod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, 'Remegve és ámulva monda: Uram, mit akarsz, hogy cselekedjem? Az Úr pedig monda néki: Kelj fel és menj be a városba, és majd megmondják néked, mit kell cselekedned.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, 'A vele utazó férfiak pedig némán álltak, hallva ugyan a szót, de senkit sem látva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, 'Felkele azonban Saulus a földről; de mikor felnyitá szemeit, senkit sem láta, azért kézenfogva vezeték be őt Damaskusba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, 'És három napig nem látott, és nem evett és nem ivott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, 'Vala pedig egy tanítvány Damaskusban, névszerint Ananiás, és monda annak az Úr látásban: Ananiás! Az pedig monda: Ímhol vagyok Uram!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, 'Az Úr pedig monda néki: Kelj fel és menj el az úgynevezett Egyenes utczába, és keress föl a Júdás házában egy Saulus nevű tárzusi embert, mert ímé imádkozik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, 'És látá Saulus látásban, hogy egy Ananiás nevű férfiú beméne hozzá és kezét reá veté, hogy lásson.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, 'Felele pedig Ananiás: Uram, sok embertől hallottam e férfiú felől, mily sok bosszúsággal illeté a te szenteidet Jeruzsálemben:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, 'És itt is hatalma van a főpapoktól, hogy mindazokat megkötözze, kik a te nevedet segítségül hívják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, 'Monda pedig néki az Úr: Eredj el, mert ő nékem választott edényem, hogy hordozza az én nevemet a pogányok és királyok, és Izráel fiai előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, 'Mert én megmutatom néki, mennyit kell néki az én nevemért szenvedni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, 'Elméne azért Ananiás és beméne a házba, és kezeit reá vetvén, monda: Saul atyámfia, az Úr küldött engem, Jézus, a ki megjelent néked az úton, melyen jöttél, hogy szemeid megnyiljanak és beteljesedjél Szent Lélekkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 18, 'És azonnal mintegy pikkelyek estek le szemeiről, és mindjárt visszanyeré látását; és felkelvén, megkeresztelkedék;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 19, 'És miután evett, megerősödék. Vala pedig Saulus a damaskusi tanítványokkal néhány napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 20, 'És azonnal prédikálá a zsinagógákban a Krisztust, hogy ő az Isten Fia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 21, 'Álmélkodnak vala pedig mindnyájan, a kik hallák, és mondának: Nem ez-é az, a ki pusztította Jeruzsálemben azokat, a kik ezt a nevet hívják segítségül, és ide is azért jött, hogy őket fogva vigye a főpapokhoz?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 22, 'Saulus pedig annál inkább erőt vőn, és zavarba hozta a Damaskusban lakó zsidókat, bebizonyítván, hogy ez a Krisztus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 23, 'Több nap elteltével azonban a zsidók tanácsot tartának, hogy őt megöljék:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 24, 'De tudtára esék Saulusnak az ő leselkedésök. És őrizék a kapukat mind nappal, mind éjjel, hogy őt megöljék;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 25, 'A tanítványok azért vevén őt éjjel, a kőfalon bocsáták alá, leeresztve egy kosárban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 26, 'Mikor pedig Saulus Jeruzsálembe ment, a tanítványokhoz próbált csatlakozni; de mindnyájan féltek tőle, nem hivén, hogy ő tanítvány.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 27, 'Barnabás azonban maga mellé vevén őt, vivé az apostolokhoz, és elbeszélé nékik, mint látta az úton az Urat, és hogy beszélt vele, és mint tanított Damaskusban nagy bátorsággal a Jézus nevében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 28, 'És ki- és bejáratos vala köztük Jeruzsálemben:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 29, 'És nagy bátorsággal tanítván az Úr Jézusnak nevében, beszél, sőt vetekedik vala a görög zsidókkal; azok pedig igyekeznek vala őt megölni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 30, 'Megtudván azonban az atyafiak, levivék őt Czézáreába, és elküldék őt Tárzusba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 31, 'A gyülekezeteknek tehát egész Júdeában, Galileában és Samariában békességök vala; épülvén és járván az Úrnak félelmében és a Szent Léleknek vígasztalásában, sokasodnak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 32, 'Lőn pedig, hogy Péter, mikor mindnyájukat bejárá, leméne a Liddában lakozó szentekhez is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 33, 'Talála pedig ott egy Éneás nevű embert, ki nyolcz esztendő óta ágyban fekszik vala, ki gutaütött vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 34, 'És monda néki Péter: Éneás, gyógyítson meg téged a Jézus Krisztus: kelj föl, vesd meg magad az ágyadat! És azonnal felkele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 35, 'És láták őt mindnyájan, kik laknak vala Liddában és Sáronban, kik megtérének az Úrhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 36, 'Joppéban pedig vala egy nőtanítvány, névszerint Tábitha, mely megmagyarázva Dorkásnak, azaz zergének mondatik: ez gazdag vala jó cselekedetekben és alamizsnákban, melyeket osztogatott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 37, 'Lőn pedig azokban a napokban, hogy megbetegedvén, meghala: és miután megmosták őt, kiteríték a felházban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 38, 'Mivelhogy pedig Lidda Joppéhoz közel vala, a tanítványok meghallván, hogy Péter ott van, küldének két férfiút ő hozzá, kérve, hogy késedelem nélkül menjen át hozzájuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 39, 'Felkelvén azért Péter, elméne azokkal. Mihelyt oda ére, felvezeték őt a felházba: és elébe állának néki az özvegyasszonyok mindnyájan sírva és mutogatva a ruhákat és öltözeteket, melyeket Dorkás csinált, míg velük együtt volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 40, 'Péter pedig mindenkit kiküldvén, térdre esve imádkozék; és a holt testhez fordulván, monda: Tábitha, kelj fel! Az pedig felnyitá szemeit; és meglátván Pétert, felüle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 41, 'És az kezét nyújtva néki, felemelé őt; és beszólítván a szenteket és az özvegyasszonyokat, eleikbe állatá őt elevenen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 42, 'És tudtára lőn az egész Joppénak; és sokan hivének az Úrban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 43, 'És lőn, hogy ő több napig marada Joppéban egy Simon nevű tímárnál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, 'Vala pedig Czézáreában egy Kornélius nevű férfiú, százados az úgynevezett itáliai seregből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, 'Jámbor és istenfélő egész házanépével egybe, ki sok alamizsnát osztogat vala a népnek, és szüntelen könyörög vala Istennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, 'Ez látá látásban világosan, a napnak mintegy kilenczedik órája körül, hogy az Istennek angyala beméne őhozzá, és monda néki: Kornélius!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, 'Ő pedig szemeit reá függesztve és megrémülve monda: Mi az, Uram? Az pedig monda néki: A te könyörgéseid és alamizsnáid felmentek Isten elébe emlékezetnek okáért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, 'Most azért küldj Joppéba embereket, és hivasd magadhoz Simont, ki neveztetik Péternek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, 'Ő egy Simon nevű tímárnál van szálláson, kinek háza a tenger mellett van. Ő megmondja néked, mit kell cselekedned.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, 'A mint pedig elment az angyal, a ki Kornéliussal beszélt, szólíta kettőt az ő szolgái közül, és egy kegyes vitézt azok közül, kik rendelkezésére állnak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, 'És elmondván nékik mindent, elküldé őket Joppéba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, 'Másnap pedig, míg azok menének és közelgetének a városhoz, felméne Péter a háznak felső részére imádkozni hat óra tájban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, 'Megéhezék azonban, és akara enni: míg azonban azok ételt készítének, szálla ő reá elragadtatás;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, 'És látá, hogy az ég megnyilt és leszálla ő hozzá valami edény, mint egy nagy lepedő, négy sarkánál fogva felkötve, és leeresztve a földre:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, 'Melyben valának mindenféle földi négylábú állatok, vadak, csúszómászó állatok és égi madarak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 13, 'És szózat lőn ő hozzá: Kelj fel Péter, öljed és egyél!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 14, 'Péter pedig monda: Semmiképen sem, Uram; mert sohasem ettem semmi közönségest, vagy tisztátalant.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 15, 'És ismét szózat lőn ő hozzá másodszor is: A miket az Isten megtisztított, te ne mondd tisztátalanoknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 16, 'Ez pedig három ízben történt; és ismét felviteték az edény az égbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 17, 'A mint pedig Péter magában tünődék, mi lehet az a látás, a melyet látott, ímé az férfiak, kiket Kornélius küldött, megtudakozván a Simon házát, odaérkezének a kapuhoz,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 18, 'És bekiáltván megtudakozák, vajjon Simon, ki neveztetik Péternek, ott van-é szálláson?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 19, 'És a míg Péter a látás felől gondolkodék, monda néki a Lélek: Ímé három férfiú keres téged:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 20, 'Nosza kelj fel, eredj alá, és minden kételkedés nélkül menj el ő velök: mert én küldöttem őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 21, 'Alámenvén azért Péter a férfiakhoz, kiket Kornélius küldött ő hozzá, monda: Ímé, én vagyok, a kit kerestek: mi dolog az, a miért jöttetek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 22, 'Ők pedig mondának: Kornélius százados, igaz és istenfélő férfiú, ki mellett a zsidók egész népe jó bizonyságot tesz, szent angyal által megintetett, hogy hívasson téged házához, és halljon tőled valami dolgokról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 23, 'Behíván azért őket, szállására fogadá. Másnap pedig elméne Péter ő velök, és a Joppébeli atyafiak közül is némelyek együtt menének ő vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 24, 'És másnap eljutának Czézáreába. Kornélius pedig várja vala őket, egybegyűjtvén rokonait és jó barátait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 25, 'És lőn, hogy a mint Péter beméne, Kornélius elébe menvén, lábaihoz borulva imádá őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 26, 'Péter azonban felemelé őt, mondván: Kelj fel; én magam is ember vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 27, 'És beszélgetve vele, belépett, és talála sokakat egybegyűlve;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 28, 'És monda nékik: Ti tudjátok, hogy tilalmas zsidó embernek más nemzetbelivel barátkozni, vagy hozzámenni; de nékem az Isten megmutatá, hogy senkit se mondjak közönséges, vagy tisztátalan embernek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 29, 'Annak okáért ellenmondás nélkül el is jöttem, miután meghívattam. Azt kérdem azért, mi okból hivattatok engem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 30, 'És Kornélius monda: Negyednaptól fogva mind ez óráig bőjtöltem, és kilencz órakor imádkozám az én házamban; és ímé egy férfiú álla meg előttem fényes ruhában,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 31, 'És monda: Kornélius, meghallgattatott a te imádságod, és a te alamizsnáid emlékezetbe jutottak Isten előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 32, 'Küldj el azért Joppéba, és hívasd magadhoz Simont, ki Péternek neveztetik; ez Simon tímár házában van szálláson a tenger mellett: ő, minekutána eljő, szól néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 33, 'Azonnal azért küldöttem hozzád; és te jól tetted, hogy eljöttél. Most azért mi mindnyájan az Isten előtt állunk, hogy meghallgassuk mindazokat, a miket Isten néked parancsolt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 34, 'Péter pedig megnyitván száját, monda: Bizonynyal látom, hogy nem személyválogató az Isten;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 35, 'Hanem minden nemzetben kedves ő előtte, a ki őt féli és igazságot cselekszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 36, 'Azt az ígét, melyet elkülde az Izráel fiainak, hirdetvén békességet a Jézus Krisztus által (ő mindeneknek Ura).');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 37, 'Ti ismeritek azt a dolgot, mely lőn az egész Júdeában, Galileától kezdve, az után a keresztség után, melyet János prédikált,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 38, 'A názáreti Jézust, mint kené fel őt az Isten Szent Lélekkel és hatalommal, ki széjjeljárt jót tévén és meggyógyítván mindeneket, kik az ördög hatalma alatt voltak; mert az Isten vala ő vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 39, 'És mi vagyunk bizonyságai mindazoknak, a miket mind a zsidóknak tartományában, mind Jeruzsálemben cselekedett; a kit megölének, fára feszítvén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 40, 'Ezt az Isten feltámasztá harmadnapon, és megadá, hogy ő megjelenjék nyilván,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 41, 'Nem az egész népnek, hanem az Istentől eleve választott bizonyságoknak, nékünk, kik együtt ettünk és együtt ittunk ő vele, minekutána feltámadott halottaiból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 42, 'És megparancsolta nékünk, hogy hirdessük a népnek, és tegyünk bizonyságot, hogy ő az Istentől rendelt bírája élőknek és holtaknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 43, 'Erről a próféták mind bizonyságot tesznek, hogy bűneinek bocsánatját veszi az ő neve által mindenki, a ki hiszen ő benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 44, 'Mikor még szólá Péter ez ígéket, leszálla a Szent Lélek mindazokra, a kik hallgatják vala e beszédet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 45, 'És elálmélkodának a zsidóságból való hívek, mindazok, a kik Péterrel együtt mentek, hogy a pogányokra is kitöltetett a Szent Lélek ajándéka.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 46, 'Mert hallják vala, hogy ők nyelveken szólnak és magasztalják az Istent. Akkor felele Péter:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 47, 'Vajjon eltilthatja-é valaki a vizet, hogy ezek meg ne keresztelkedjenek, kik vették a Szent Lelket miképen mi is?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 48, 'És parancsolá, hogy keresztelkedjenek meg az Úrnak nevében. Akkor kérék őt, hogy maradjon náluk néhány napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, 'Meghallák azonban az apostolok és a Júdeában levő atyafiak, hogy a pogányok is bevették az Istennek beszédét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, 'Mikor azért felment Péter Jeruzsálembe, vetekedének ő vele a zsidóságból valók,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, 'Mondván: Körülmetéletlen emberekhez mentél be, és együtt ettél velük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, 'Elkezdvén pedig Péter, megmagyarázta nékik rendre, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, 'Én Joppé városában imádkozám; és láték elragadtatásban egy látást, valami alászálló edényt, mint egy nagy lepedőt, négy sarkánál fogva leeresztve az égből; és egészen hozzám szálla:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, 'Melyre szememet rávetve megnézém, és látám a földi négylábú állatokat, a vadakat és a csúszómászókat és az égi madarakat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, 'Hallék pedig szót is, mely ezt mondja vala nékem: Kelj fel Péter, öljed és egyél!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, 'Mondék azonban: Semmiképen sem, Uram; mert soha semmi közönséges vagy tisztátalan nem ment be az én számba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, 'Felele pedig nékem a szózat másodszor az égből: A miket az Isten megtisztított, te ne mondd tisztátalanoknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, 'Ez pedig három ízben történt; és ismét felvonaték az egész az égbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, 'És ímé, azonnal három férfiú érkezék a házhoz, melyben valék, kik Czézáreából küldettek én hozzám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, 'Mondá pedig nékem a Lélek, hogy menjek el velök minden kételkedés nélkül. Eljöve pedig velem ez a hat atyafi is; és bemenénk annak az embernek a házába:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, 'És elbeszélé nékünk, mimódon látta, a mint az angyal megálla az ő házában és ezt mondá néki: Küldj embereket Joppéba, és hívasd magadhoz Simont, ki Péternek neveztetik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, 'Ő szólni fog hozzád olyan ígéket, melyek által megtartatol te és a te egész házadnépe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, 'Mikor pedig én elkezdtem szólni, leszálla a Szent Lélek ő reájok, miképen mi reánk is kezdetben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, 'Megemlékezém pedig az Úrnak ama mondásáról, a mint mondá: János ugyan vízzel keresztelt, ti azonban Szent Lélekkel fogtok megkereszteltetni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, 'Ha tehát az Isten hasonló ajándékát adta nékik, mint nékünk is, kik hittünk az Úr Jézus Krisztusban, kicsoda voltam én, hogy az Istent eltilthattam volna?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 18, 'Ezeknek hallatára aztán megnyugovának, és dicsőíték az Istent, mondván: Eszerint hát a pogányoknak is adott az Isten megtérést az életre!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 19, 'Azok tehát, a kik eloszlottak az üldözés miatt, mely Istvánért támadott, eljutának Fenicziáig, Cziprusig és Antiókhiáig, senkinek nem prédikálván az ígét, hanem csak a zsidóknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 20, 'Voltak azonban közöttük némely cziprusi és czirénei férfiak, kik mikor Antiókhiába bementek, szólának a görögöknek, hirdetve az Úr Jézust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 21, 'És az Úrnak keze vala velök; és nagy sokaság tére meg az Úrhoz, hívővé lévén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 22, 'Elhatott pedig a hír ő felőlük a jeruzsálemi gyülekezet fülébe; és kiküldék Barnabást, hogy menjen el egész Antiókhiáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 23, 'Ki mikor oda jutott és látta az Isten kegyelmét, örvendeze; és inté mindnyájukat, hogy állhatatos szívvel maradjanak meg az Úrban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 24, 'Mert jámbor és Szent Lélekkel és hittel teljes férfiú vala ő. És nagy sokaság csatlakozék az Úrhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 25, 'Elméne pedig Barnabás Tárzusba, hogy felkeresse Saulust, és rátalálván, elvivé őt Antiókhiába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 26, 'És lőn, hogy ők egy egész esztendeig forgolódtak a gyülekezetben, és tanítottak nagy sokaságot; és a tanítványokat először Antiókhiában nevezték keresztyéneknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 27, 'Ez időtájban pedig menének Jeruzsálemből Antiókhiába próféták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 28, 'Felkelvén pedig egy azok közül, névszerint Agabus, megjelenté a Lélek által, hogy az egész föld kerekségén nagy éhség lesz; a mely meg is lőn Klaudius császár idejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 29, 'A tanítványok pedig elhatározták, hogy a szerint, a mint kinek-kinek közöttük módjában áll, küldenek valamit segítségül a Júdeában lakozó atyafiaknak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 30, 'A mit meg is cselekedének, elküldvén a vénekhez Barnabás és Saulus keze által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, 'Abban az időben pedig Heródes király elkezde kegyetlenkedni némelyekkel, a gyülekezetből valók közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, 'Megöleté pedig Jakabot, Jánosnak testvérét, fegyverrel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, 'És látván, hogy ez tetszik a zsidóknak, föltette magában, hogy elfogatja Pétert is. (Valának pedig a kovásztalan kenyerek napjai.)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, 'Kit el is fogatván, tömlöczbe veté, átadván négy négyes katonai szakasznak, hogy őrizzék őt; husvét után akarván őt a nép elé vezettetni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, 'Péter azért őrizteték a fogságban; a gyülekezet pedig szüntelen könyörög vala az Istennek ő érette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, 'És ímé az Úrnak angyala eljöve, és világosság fénylék a tömlöczben: és meglökvén Péter oldalát, felkölté őt, mondván: Kelj föl hamar! És leesének a lánczok kezeiről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, 'És monda néki az angyal: Övezd fel magadat, és kösd fel saruidat. És úgy cselekedék. És monda néki: Vedd rád felsőruhádat és kövess engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, 'És kimenvén, követé őt; és nem tudta, hogy valóság az, a mi történik az angyal által, hanem azt hitte, hogy látást lát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, 'Mikor pedig általmentek az első őrsön és a másodikon, jutának a vaskapuhoz, mely a városba visz; mely magától megnyílék előttük: és kimenvén, egy utczán előremenének; és azonnal eltávozék az angyal ő tőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, 'És Péter magához térve monda: Most tudom igazán, hogy az Úr elbocsátotta az ő angyalát, és megszabadított engem Heródes kezéből és a zsidók népének egész várakozásától.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, 'És miután ezt megértette, elméne Máriának, a János anyjának házához, ki Márknak neveztetik; hol sokan valának egybegyűlve és könyörögnek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, 'És mikor Péter zörgetett a tornácz ajtaján, egy Rhodé nevű szolgálóleány méne oda, hogy hallgatózzék:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, 'És megismervén a Péter szavát, örömében nem nyitá meg a kaput, hanem befutván, hírül adá, hogy Péter áll a kapu előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 15, 'Azok pedig mondának néki: Elment az eszed. Ő azonban erősíté, hogy úgy van. Azok pedig mondának: Az ő angyala az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 16, 'Péter pedig szüntelen zörget vala: mikor azért felnyitották, megláták őt és elálmélkodának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 17, 'Miután pedig kezével hallgatást intett nékik, elbeszélé nékik, mimódon hozta ki őt az Úr a tömlöczből. És monda: Adjátok tudtára ezeket Jakabnak és az atyafiaknak. És kimenvén elméne más helyre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 18, 'Mikor pedig megvirradt, nem csekély háborúság támada a vitézek között, mi történt hát Péterrel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 19, 'Heródes pedig mikor előkérte őt és nem találta, kivallatván az őröket, parancsolá, hogy kivégeztessenek. És lemenvén Júdeából Czézáreába, ott időzött.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 20, 'Heródes pedig ellenséges indulattal vala a tirusiak és sidoniak iránt; de azok egyakarattal eljövének ő hozzá, és Blástust, a király kamarását megnyervén, békességet kérének, mivelhogy az ő tartományuk a királyéból élelmeztetik vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 21, 'Egy kitűzött napon pedig Heródes királyi ruhájába felöltözve és székibe ülve nyilvánosan szóla hozzájuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 22, 'A nép pedig felkiálta: Isten szava ez és nem emberé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 23, 'És azonnal megveré őt az Úrnak angyala, azért, hogy nem az Istennek adá a dicsőséget; és a férgektől megemésztetvén, meghala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 24, 'Az Istennek ígéje pedig növekedik és terjed vala,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 25, 'Barnabás és Saulus pedig visszatérének Jeruzsálemből, betöltvén szolgálatukat, maguk mellé véve Jánost is, kinek mellékneve Márk vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, 'Valának pedig Antiókhiában az ott levő gyülekezetben némely próféták és tanítók: Barnabás és Simeon, ki hivattatik vala Nigernek, és a Czirénei Luczius és Manaen, ki Heródessel, a negyedes fejedelemmel együtt neveltetett vala, és Saulus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, 'Mikor azért azok szolgálának az Úrnak és bőjtölének, monda a Szent Lélek: Válaszszátok el nékem Barnabást és Saulust a munkára, a melyre én őket elhívtam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, 'Akkor, miután bőjtöltek és imádkoztak, és kezeiket reájok vetették, elbocsáták őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, 'Ők annakokáért, miután kibocsáttattak a Szent Lélektől, lemenének Szeleucziába; és onnét elevezének Cziprusba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, 'És mikor Salamisba jutottak, hirdeték az Isten beszédét a zsidóknak zsinagógáiban: és János is velük vala, mint segítőtárs.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, 'És eljárván a szigetet mind Páfusig, találkozának egy ördöngős hamispróféta zsidóra, kinek neve vala Barjézus;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, 'Ki Sergius Paulus tiszttartóval, ez okos emberrel vala. Ez magához hivatván Barnabást és Saulust, kíváná hallani az Isten beszédét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, 'Elimás, az ördöngős azonban (mert így magyaráztatik az ő neve) ellenkezik vala velök, igyekezvén a tiszttartót elfordítani a hittől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, 'De Saulus, ki Pál is, megtelvén Szent Lélekkel, szemeit reá vetve,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 10, 'Monda: Ó minden álnoksággal és minden gonoszsággal teljes ördögfi, minden igazságnak ellensége, nem szűnöl-é meg az Úrnak igaz útait elfordítani?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 11, 'Most azért ímé az Úrnak keze van ellened, és vak leszel és nem látod a napot egy ideig. És azonnal homály és sötétség szálla reá; és kerengve keres vala vezetőket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 12, 'Akkor a tiszttartó, mikor látta a történt dolgot, hűn, elálmélkodván az Úrnak tudományán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 13, 'Elhajózván pedig Páfusból Pál és kisérői, Pergába, Pámfiliának városába menének. János azonban elválván tőlük, megtére Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 14, 'Ők pedig Pergából tovább menve, eljutának Antiókhiába, Pisidiának városába, és bemenvén szombatnapon a zsinagógába; leülének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 15, 'És a törvénynek és a prófétáknak felolvasása után küldének a zsinagógának előljárói ő hozzájok, mondván: Atyánkfiai, férfiak, ha van valami intőbeszédetek a néphez, szóljatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 16, 'Pál azért felkelvén és kezével intvén, monda: Izráelnek férfiai, és ti, kik félitek az Istent, halljátok meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 17, 'Ennek a népnek, Izráelnek Istene kiválasztotta a mi atyáinkat, és e népet fölemelte, mikor Égyiptomnak földében jövevények valának, és onnét kihozá őket hatalmas karja által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 18, 'És közel negyven esztendőnek idejéig tűrte az ő erkölcsöket a pusztában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 19, 'És minekutána eltörölt hét népet a Kanaán földén, azoknak földöket sorsvetés által elosztá nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 20, 'És azután mintegy négyszázötven esztendeig adott birákat mind Sámuel prófétáig;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 21, 'Annakutána pedig királyt kérének maguknak, és adá nékik az Isten Sault, a Kis fiát, a Benjamin nemzetségéből való férfiút negyven esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 22, 'És mikor őt elveté, támasztá nékik Dávidot királyul; kiről bizonyságot is tőn és monda: Találtam szívem szerint való férfiút, Dávidot, a Jesse fiát, ki minden akaratomat véghez viszi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 23, 'Ennek magvából támasztott Isten, ígérete szerint, Izráelnek szabadítót, Jézust;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 24, 'Minekutána előbb János az ő eljövetele előtt a megtérésnek keresztségét prédikálta Izráel egész népének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 25, 'És mikor be akará végezni János az ő tisztét, monda: Kinek gondoltok engem? Nem én vagyok az, hanem ímé én utánam jő, kinek nem vagyok méltó megoldani lábainak saruját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 26, 'Atyámfiai, férfiak, Ábrahám nemzetének fiai, és kik ti köztetek félik az Istent, ez idvességnek beszéde néktek küldetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 27, 'Mert a kik lakoznak Jeruzsálemben és azoknak fejei, mivelhogy őt fel nem ismerék, a prófétáknak szavait is, melyeket minden szombaton felolvasnak, ítéletükkel betöltötték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 28, 'És bár semmi halálra való okot nem találtak, kérék Pilátustól, hogy ölettessék meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 29, 'És mikor mindazokat elvégezték, a mik ő felőle megirattak, a fáról levéve sírba helyhezteték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 30, 'De az Isten feltámasztá őt halottaiból:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 31, 'És ő megjelent több napon át azoknak, kik együtt jöttek fel ő vele Galileából Jeruzsálembe, kik néki bizonyságai a nép előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 32, 'És mi hirdetjük néktek az atyáknak tett ígéretet, hogy azt az Isten betöltötte nékünk, az ő fiaiknak feltámasztván Jézust:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 33, 'Mint a második zsoltárban is meg van írva: Én Fiam vagy te; ma nemzettelek én téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 34, 'Hogy pedig feltámasztotta őt halottaiból, úgy hogy nem is fog többé az enyészetbe visszatérni, azt így mondotta: Néktek adom a Dávid biztos szent javait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 35, 'Azért mondja másutt is: Nem engeded, hogy a te Szented rothadást lásson.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 36, 'Mert Dávid, minekutána a saját idejében szolgált az Isten akaratának, elaludt, és helyhezteték az ő atyáihoz, és rothadást látott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 37, 'De a kit Isten feltámasztott, az nem látott rothadást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 38, 'Azért legyen néktek tudtotokra, atyámfiai, férfiak, hogy ez által hirdettetik néktek a bűnöknek bocsánata:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 39, 'És mindenekből, a mikből a Mózes törvénye által meg nem igazíttathattatok, ez által mindenki, a ki hisz, megigazul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 40, 'Meglássátok azért, hogy rajtatok ne essék, a mit a próféták megmondottak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 41, 'Lássátok meg, ti megvetők, és csodálkozzatok és semmisüljetek meg; mert én oly dolgot cselekszem a ti időtökben, oly dolgot, melyet nem hinnétek, ha valaki elmondaná néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 42, 'Mikor pedig kimentek a zsidók zsinagógájából, kérék a pogányok, hogy a következő szombaton prédikálják nékik ezen beszédeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 43, 'Mikor pedig eloszlott a gyülekezet, sokan a zsidók közül és az istenfélő prozelitusok közül követék Pált és Barnabást; a kik szólván hozzájuk, biztaták őket, hogy maradjanak meg az Isten kegyelmében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 44, 'A következő szombaton aztán majdnem az egész város egybegyűle az Isten ígéjének hallgatására,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 45, 'Mikor pedig látták a zsidók a sokaságot, betelének irigységgel, és ellene mondának azoknak, miket Pál mond vala, ellenkezve és káromlást szólva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 46, 'Akkor Pál és Barnabás nagy bátorsággal szólva mondának: Szükséges volt, hogy először néktek hirdettessék az Isten ígéje; de mivelhogy ti megvetitek azt, és nem tartjátok méltóknak magatokat az örök életre, ímé a pogányokhoz fordulunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 47, 'Mert így parancsolta nékünk az Úr: Rendeltelek téged világosságul a pogányoknak, hogy légy üdvösségükre a földnek széléig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 48, 'A pogányok pedig ezeket hallván, örvendezének, és magasztalják vala az Úrnak ígéjét; és a kik csak örök életre választattak vala, hivének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 49, 'Terjede pedig az Úrnak ígéje az egész tartományban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 50, 'A zsidók azonban felindíták az istenfélő és tisztességbeli asszonyokat és a városnak eleit, és üldözést támasztának Pál és Barnabás ellen, és kiűzék őket határukból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 51, 'Azok pedig lábuknak porát lerázván ellenük, elmenének Ikóniumba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 52, 'A tanítványok pedig betelnek vala örömmel és Szent Lélekkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, 'Lőn pedig Ikóniumban, hogy ők együtt menének be a zsidók zsinagógájába, és prédikálának, úgyannyira, hogy mind zsidóknak, mind görögöknek nagy sokasága lőn hívővé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, 'A kik azonban a zsidók közül nem hivének, felindíták és megharagíták a pogányoknak lelkét az atyafiak ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, 'Azért sok időt töltöttek ott, bátran prédikálva az Úrban, ki bizonyságot tesz vala az ő kegyelmének beszéde mellett, és adja vala, hogy jelek és csodák történjenek az ő kezeik által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, 'De a városnak sokasága meghasonlék; és némelyek a zsidók mellett, mások pedig az apostolok mellett valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, 'És mikor a pogányok és zsidók az ő főembereikkel egybe támadást indítának, hogy bosszúsággal illessék és megkövezzék őket,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, 'Ők megtudták, és elfutának Likaóniának városaiba, Listrába és Derbébe, és a körülvaló tartományba,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, 'És ott prédikálják vala az evangyéliomot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, 'És Listrában ül vala egy lábaival tehetetlen ember, ki az ő anyjának méhétől fogva sánta volt, és soha nem járt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, 'Ez hallá Pált beszélni: a ki szemeit reá függesztvén, és látván, hogy van hite, hogy meggyógyul,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, 'Monda nagy fenszóval: Állj fel lábaidra egyenesen! És felszökött és járt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, 'A sokaság pedig mikor látta, a mit Pál cselekedett, felkiálta, likaóniai nyelven mondván: Az istenek jöttek le mihozzánk emberi ábrázatban!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, 'És hívják vala Barnabást Jupiternek, Pált pedig Merkúriusnak, minthogy ő volt a szóvivő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, 'Jupiter papja pedig, a kinek temploma az ő városuk előtt vala, felkoszorúzott bikákat hajtva a kapukhoz, a sokasággal együtt áldozni akar vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, 'Mikor azonban ezt meghallották az apostolok, Barnabás és Pál, köntösüket megszaggatván, a sokaság közé futamodának, kiáltván');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, 'És ezt mondván: Férfiak, miért mívelitek ezeket? Mi is hozzátok hasonló természetű emberek vagyunk, és azt az örvendetes izenetet hirdetjük néktek, hogy e hiábavalóktól az élő Istenhez térjetek, ki teremtette a mennyet, a földet, a tengert és minden azokban valókat:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, 'Ki az elmúlt időkben hagyta a pogányokat mind a maguk útján haladni:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, 'Jóllehet nem hagyta magát tanúbizonyság nélkül, mert jóltevőnk volt, adván mennyből esőket és termő időket nékünk, és betöltvén eledellel és örömmel a mi szívünket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, 'És ezeket mondván, nagynehezen lecsendesíték a sokaságot, hogy nékik ne áldozzék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, 'Jövének azonban Antiókhiából és Ikóniumból zsidók, és a sokaságot eláltatván, megkövezék Pált, és kivonszolák a városból, azt gondolván, hogy meghalt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, 'De mikor körülvették őt a tanítványok, felkelvén, beméne a városba; és másnap Barnabással elméne Derbébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, 'És miután hirdették az evangyéliomot annak a városnak, és sokakat tanítványokká tettek, megtérének Listrába, Ikoniumba és Antiókhiába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 22, 'Erősítve a tanítványok lelkét, intvén, hogy maradjanak meg a hitben, és hogy sok háborúságon által kell nékünk az Isten országába bemennünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 23, 'Miután pedig választottak nékik gyülekezetenként véneket, imádkozván bőjtölésekkel egybe, ajánlák őket az Úrnak, kiben hittek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 24, 'És Pisidián általmenvén, menének Pamfiliába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 25, 'És miután Pergában hirdették az ígét, lemenének Attáliába;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 26, 'És onnét elhajózának Antiókhiába, a honnét az Isten kegyelmére bízták volt őket arra a munkára, melyet elvégeztek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 27, 'Mikor pedig megérkeztek és a gyülekezetet egybehívták, elbeszélék, mily nagy dolgokat cselekedett az Isten ő velök, és hogy a pogányoknak kaput nyitott a hitre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 28, 'Ott aztán nem kevés időt töltöttek a tanítványokkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 1, 'Némelyek pedig, kik Júdeából jöttek alá, így tanítják vala az atyafiakat: Ha körül nem metélkedtek Mózes rendtartása szerint, nem idvezülhettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 2, 'Mikor azért Pálnak és Barnabásnak nagy háborúsága és vetekedése lőn azok ellen, azt végezék, hogy Pál és Barnabás és némely mások ő közülök menjenek fel az apostolokhoz és a vénekhez Jeruzsálembe e kérdés ügyében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 3, 'Ők tehát kikísértetvén a gyülekezettől, általmentek Fenicián és Samárián, elbeszélve a pogányok megtérését; és nagy örömet szerzének az összes atyafiaknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 4, 'Mikor pedig megérkeztek Jeruzsálembe, a gyülekezet és az apostolok és a vének fogadák őket, és ők elbeszélék, mily nagy dolgokat cselekedék az Isten ő velök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 5, 'Előállának azonban némely hivők a farizeusok szerzetéből valók közül, mondván, hogy körül kell metélni őket, és megparancsolni, hogy a Mózes törvényét megtartsák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 6, 'Egybegyülének azért az apostolok és a vének, hogy e dolog felől végezzenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 7, 'És mikor nagy vetekedés támadt, felkelvén Péter, monda nékik: Atyámfiai, férfiak, ti tudjátok, hogy az Isten régebbi idő óta kiválasztott engem mi közülünk, hogy a pogányok az én számból hallják az evangyéliomnak beszédét, és higyjenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 8, 'És a szíveket ismerő Isten bizonyságot tett mellettük, mert adta nékik a Szent Lelket, miként nékünk is;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 9, 'És semmi különbséget sem tett mi köztünk és azok között, a hit által tisztítván meg azoknak szívét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 10, 'Most azért mit kísértitek az Istent, hogy a tanítványok nyakába oly igát tegyetek, melyet sem a mi atyáink, sem mi el nem hordozhattunk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 11, 'Sőt inkább az Úr Jézus Krisztus kegyelme által hiszszük, hogy megtartatunk, miképen azok is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 12, 'Elhallgatott azért az egész sokaság; és hallgatják vala Barnabást és Pált, a mint elbeszélék, mennyi jelt és csudát tett az Isten ő általok a pogányok között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 13, 'Miután pedig ők elhallgattak, felele Jakab, mondván: Atyámfiai, férfiak, hallgassatok meg engem!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 14, 'Simeon elbeszélé, mimódon gondoskodott először az Isten, hogy a pogányok közül vegyen népet az ő nevének,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 15, 'És ezzel egyeznek a próféták mondásai, mint meg van írva:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 16, 'Ezek után megtérek és felépítem a Dávidnak leomlott sátorát; és annak omladékait helyreállítom, és ismét felállatom azt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 17, 'Hogy megkeresse az embereknek többi része az Urat, és a pogányok mindnyájan, a kik az én nevemről neveztetnek. Ezt mondja az Úr, ki mindezeket megcselekszi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 18, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 19, 'Azokáért én azt mondom, hogy nem kell háborgatni azokat, kik a pogányok közül térnek meg az Istenhez;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 20, 'Hanem írjuk meg nékik, hogy tartózkodjanak a bálványok fertelmességeitől, a paráznaságtól, a fúlvaholt állattól és a vértől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 21, 'Mert Mózesnek régi nemzedékek óta városonként megvannak a hirdetői, mivelhogy a zsinagógákban minden szombaton olvassák.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 22, 'Akkor tetszék az apostoloknak és a véneknek az egész gyülekezettel egybe, hogy férfiakat válaszszanak ki magok közül és elküldjék Antiókhiába Pállal és Barnabással, Júdást, kinek mellékneve Barsabás, és Silást, kik az atyafiak között főemberek valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 23, 'Megírván azok keze által ezeket: Az apostolok, a vének, és az atyafiak az Antiókhiában, Siriában és Czilicziában levő, a pogányok közül való atyafiaknak üdvözletüket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 24, 'Mivelhogy meghallottuk, hogy némelyek mi közülünk kimenvén, megháborítottak titeket beszédeikkel, feldúlva a ti lelketeket, azt mondván, hogy körülmetélkedjetek és a törvényt megtartsátok; kiknek mi parancsot nem adtunk:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 25, 'Tetszék nékünk, miután egyértelemre jutottunk, hogy férfiakat válaszszunk ki és elküldjük ti hozzátok a mi szeretteinkkel, Barnabással és Pállal,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 26, 'Oly emberekkel, kik életüket tették koczkára a mi Urunk Jézus Krisztus nevéért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 27, 'Küldöttük azért Júdást és Silást, kik élőszóval szintén tudtotokra adják ugyanezeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 28, 'Mert tetszék a Szent Léleknek és nékünk, hogy semmi több teher ne vettessék ti reátok ezeken a szükséges dolgokon kívül,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 29, 'Hogy tartózkodjatok a bálványoknak áldozott dolgoktól, a vértől, a fúlvaholt állattól, és a paráznaságtól; melyektől ha megóvjátok magatokat, jól lesz dolgotok. Legyetek egészségben!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 30, 'Azok annakokáért elbocsáttatván, elmenének Antiókhiába; és egybegyűjtvén a sokaságot, átadák a levelet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 31, 'És mikor elolvasták, örvendezének az intésen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 32, 'Júdás és Silás pedig maguk is próféták lévén, sok beszéddel inték az atyafiakat, és megerősíték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 33, 'Miután pedig bizonyos időt eltöltöttek, elbocsáták őket az atyafiak békességgel az apostolokhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 34, 'De Silásnak tetszék ott maradni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 35, 'Pál és Barnabás is Antiókhiában időzének, tanítva és prédikálva másokkal is többekkel az Úrnak ígéjét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 36, 'Egynéhány nap mulva pedig monda Pál Barnabásnak: Visszatérve most, látogassuk meg a mi atyánkfiait minden városban, melyben hírdettük az Úrnak ígéjét, hogyan vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 37, 'És Barnabás azt tanácsolá, hogy vegyék maguk mellé Jánost, ki Márknak hívatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 38, 'Pál azonban azt tartá méltónak, hogy a ki elszakadt tőlük Pamfiliától fogva, és nem ment velök a munkára, ne vegyék maguk mellé azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 39, 'Meghasonlás támada azért, úgyhogy elszakadának egymástól, és Barnabás maga mellé véve Márkot, elhajózék Cziprusba;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 40, 'Pál pedig Silást választván maga mellé, elméne, az Isten kegyelmére bízatván az atyafiaktól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 41, 'És eljárá Siriát és Czilicziát, erősítve a gyülekezeteket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 1, 'Juta pedig Derbébe és Listrába: És ímé vala ott egy Timótheus nevű tanítvány, egy hívő zsidó asszonynak, de görög atyának fia;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 2, 'Kiről jó bizonyságot tesznek vala a Listrában és Ikóniumban levő atyafiak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 3, 'Ezt Pál magával akará vinni; és vévén, körülmetélé őt a zsidókért, kik azokon a helyeken valának: mert ismerték mindnyájan az ő atyját, hogy görög volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 4, 'És a mint általmentek a városokon, meghagyák nékik, hogy tartsák meg a rendeléseket, melyeket végeztek a Jeruzsálemben levő apostolok és vének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 5, 'A gyülekezetek azért erősödének a hitben, és gyarapodának számban naponként.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 6, 'Eljárván pedig Frigiát és Galácia tartományát, mivelhogy eltiltatának a Szent Lélektől, hogy az ígét Ázsiában hirdessék,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 7, 'Misia felé menvén, igyekeznek vala Bithiniába jutni; de nem ereszté őket a Lélek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 8, 'Áthaladván azért Misián, lemenének Tróásba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 9, 'És azon az éjszakán látás jelenék meg Pálnak: egy macedón férfiú állt előtte, kérve őt és ezt mondva: Jer által Macedóniába, és légy segítségül nékünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 10, 'Mihelyt pedig a látást látta, azonnal igyekezénk elmenni Macedóniába, megértvén, hogy oda hívott minket az Úr, hogy azoknak prédikáljuk az evangyéliomot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 11, 'Elhajózván azért Tróásból, egyenesen Sámothrákéba mentünk, és másnap Neápolisba;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 12, 'Onnét pedig Filippibe, mely Macedónia azon részének első gyarmatvárosa. És ebben a városban töltöttünk néhány napot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 13, 'És szombatnapon kimenénk a városon kívül egy folyóvíz mellé, hol az imádkozás szokott lenni; és leülvén, beszélgeténk az egybegyűlt asszonyokkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 14, 'És egy Lidia nevű, Thiatira városbeli bíborárús asszony, ki féli vala az Istent, hallgata reánk. Ennek az Úr megnyitá szívét, hogy figyelmezzen azokra, a miket Pál mond vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 15, 'Mikor pedig megkeresztelkedék mind házanépével egybe, kére minket, mondván: Ha az Úr hívének ítéltetek engem, jertek az én házamhoz, és maradjatok ott. És unszola minket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 16, 'Lőn pedig, hogy mikor mentünk a könyörgésre, egy szolgálóleányka jöve előnkbe, kiben jövendőmondásnak lelke vala, ki az ő urainak nagy hasznot hajta jövendőmondásával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 17, 'Ez követvén Pált és minket, kiált vala, mondván: Ezek az emberek a magasságos Istennek szolgái, kik néktek az idvességnek útját hirdetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 18, 'Ezt pedig több napon át mívelte. Pál azonban megbosszankodván, és hátrafordulván, mondá a léleknek: Parancsolom néked a Jézus Krisztus nevében, hogy menj ki belőle. És kiméne abban az órában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 19, 'Látván pedig annak az urai, hogy keresetüknek a reménysége elveszett, megfogva Pált és Silást, vonák a piaczra a hatóságok elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 20, 'És odavezetvén őket a bírákhoz, mondának: Ezek az emberek zsidó létükre megháborítják a mi városunkat,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 21, 'És olyan szertartásokat hirdetnek, melyeket nem szabad nékünk bevennünk, sem cselekednünk, mivelhogy rómaiak vagyunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 22, 'És velök egyben feltámada a sokaság ő ellenök. A bírák pedig letépetvén ruháikat, megvesszőzteték őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 23, 'És miután sok ütést mértek rájok, tömlöczbe veték őket, megparancsolva a tömlöcztartónak, hogy gondosan őrizze őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 24, 'Ki ilyen parancsolatot vévén, veté őket a belső tömlöczbe, és lábaikat kalodába szorítá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 25, 'Éjféltájban pedig Pál és Silás imádkozván, énekkel dicsőíték az Istent. A foglyok pedig hallgatják vala őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 26, 'És hirtelen nagy földindulás lőn, úgyannyira, hogy megrendülének a tömlöcz fundamentomai; és azonnal megnyílának az ajtók mind, és mindnyájoknak a bilincsei feloldódnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 27, 'Fölserkenvén pedig a tömlöcztartó, és látván, hogy nyitva vannak a tömlöcznek ajtai, kivonva fegyverét, meg akará magát ölni, azt gondolván, hogy elszöktek a foglyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 28, 'Pál azonban nagy fenszóval kiáltá, mondván: Semmi kárt ne tégy magadban; mert mindnyájan itt vagyunk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 29, 'Az pedig világot kérve beugrott, és remegve borult Pál és Silás elé,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 30, 'És kihozván őket, monda: Uraim, mit kell nékem cselekednem, hogy idvezüljek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 31, 'Azok pedig mondának: Higyj az Úr Jézus Krisztusban, és idvezülsz mind te, mind a te házadnépe!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 32, 'És hirdeték néki az Úrnak ígéjét, és mindazoknak, kik az ő házánál valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 33, 'És az magához vévén őket az éjszakának azon órájában, megmosá az ütésektől; és megkeresztelkedék azonnal ő és az övéi mindnyájan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 34, 'És bevivén őket házába, asztalt teríte nékik, és egész háznépével egyben örvendeze, hogy hitt az Istennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 35, 'Mikor pedig megvirradt, a bírák elküldék a poroszlókat, mondván: Bocsásd el azokat az embereket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 36, 'A tömlöcztartó pedig tudtára adá e szavakat Pálnak: A bírák ide küldöttek, hogy bocsássalak el titeket: most azért kimenvén, menjetek el békességgel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 37, 'Pál pedig monda nékik: Megvesszőztek minket nyilvánosan, ítélet nélkül, holott római emberek vagyunk, és tömlöczbe vetettek: és most alattomban akarnak bennünket kiküldeni? Nem úgy; hanem jőjjenek ők maguk és vezessenek ki minket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 38, 'A poroszlók pedig megmondák a bíráknak e beszédeket; és azok megfélemlének, mikor meghallották, hogy rómaiak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 39, 'És odamenvén, megkérlelék őket: és kivezetvén, kérék, hogy menjenek ki a városból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 40, 'Kijövén pedig a tömlöczből, bemenének Lidiához; és mikor látták az atyafiakat, vígasztalák őket, és eltávozának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 1, 'Miután pedig általmentek Ámfipolison és Apollónián, Thessalonikába érkeztek, a hol volt a zsidóknak zsinagógájok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 2, 'Pál pedig, a mint szokása vala, beméne hozzájok, és három szombaton át vetekedék velök az írásokból,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 3, 'Megmagyarázva és kimutatva, hogy a Krisztusnak szükség volt szenvedni és feltámadni a halálból; és hogy ez a Jézus a Krisztus, a kit én hirdetek néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 4, 'És némelyek azok közül hivének és csatlakozának Pálhoz és Siláshoz; úgyszintén az istenfélő görögök közül nagy sokaság, és az előkelő asszonyok közül nem kevesen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 5, 'De a zsidók, kik nem hisznek vala, írigységtől felindíttatván, és magok mellé vévén a piaczi népségből némely gonosz férfiakat, és csődületet támasztván, felháboríták a várost; és a Jáson házát megostromolván, igyekeztek őket kihozni a nép közé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 6, 'Mikor pedig őket nem találák, Jásont és némely atyafiakat vonszolák a város előljárói elé, kiáltozva, hogy ezek az országháborítók itt is megjelentek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 7, 'Kiket Jáson házába fogadott: pedig ezek mindnyájan a császár parancsolatai ellen cselekesznek, mivelhogy mást tartanak királynak, Jézust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 8, 'Fel is indíták a sokaságot és a város előljáróit, kik hallják vala ezeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 9, 'De mikor kezességet nyertek Jáson és a többiek részéről, elbocsáták őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 10, 'Az atyafiak pedig azonnal, azon éjszakán elküldék Pált Silással egyetemben Béreába; kik mikor odamentek, elmenének a zsidóknak zsinagógájába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 11, 'Ezek pedig nemesb lelkűek valának a Thessalonikabelieknél, úgymint kik bevevék az ígét teljes készséggel, naponként tudakozva az írásokat, ha úgy vannak-é ezek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 12, 'Sokan hivének azért ő közülök; sőt az előkelő görög asszonyok és férfiak közül is nem kevesen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 13, 'Mikor azonban tudtokra esett a Thessalonikából való zsidóknak, hogy Béreában is prédikálta Pál az Istennek ígéjét, elmenének, és a sokaságot ott is felháboríták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 14, 'De akkor mindjárt kibocsáták az atyafiak Pált, hogy utazzék a tenger felé; Silás és Timótheus azonban ott maradának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 15, 'A kik pedig elkísérték Pált, elvivék őt egész Athénig; és parancsát vévén Siláshoz és Timótheushoz, hogy minél hamarább menjenek ő hozzá, elmenének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 16, 'Athénben pedig, mikor azokat várá Pál, lelke háborog vala ő benne, látván, hogy a város bálványokkal van tele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 17, 'Vetekedik vala azért a zsinagógában a zsidókkal és az istenfélő emberekkel, és a piaczon mindennap azokkal, a kiket előtalált.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 18, 'Némelyek pedig az epikureus és stoikus filozófusok közül összeakadtak ő vele. És némelyek mondának: Mit akarhat ez a csacsogó mondani? Mások meg: Idegen istenségek hirdetőjének látszik. Mivelhogy a Jézust és a feltámadást hirdeti vala nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 19, 'És megragadván őt, az Areopágusra vivék, ezt mondván: Vajjon megérthetjük-é mi az az új tudomány, melyet te hirdetsz?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 20, 'Mert valami idegen dolgokat beszélsz a mi füleinknek: meg akarjuk azért érteni, mik lehetnek ezek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 21, 'Az athéniek pedig mindnyájan és az ott lakó jövevények semmi másban nem valának foglalatosok, mint valami újságnak beszélésében és hallgatásában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 22, 'Előállván pedig Pál az Areopágusnak közepette, monda: Athéni férfiak, minden tekintetben nagyon istenfélőknek látlak titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 23, 'Mert mikor bejárám és szemlélém a ti szentélyeiteket, találkozám egy oltárral is, melyre ez vala ráírva: Ismeretlen Istennek. A kit azért ti nem ismerve tiszteltek, azt hirdetem én néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 24, 'Az Isten, a ki teremtette a világot és mindazt, a mi abban van, mivelhogy ő mennynek és földnek ura, kézzel csinált templomokban nem lakik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 25, 'Sem embereknek kezeitől nem tiszteltetik, mintha valami nélkül szűkölködnék, holott ő ád mindeneknek életet, leheletet és mindent;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 26, 'És az egész emberi nemzetséget egy vérből teremtette, hogy lakozzanak a földnek egész színén, meghatározván eleve rendelt idejöket és lakásuknak határait;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 27, 'Hogy keressék az Urat, ha talán kitapogathatnák őt és megtalálhatnák, jóllehet bizony nincs messze egyikőnktől sem:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 28, 'Mert ő benne élünk, mozgunk és vagyunk; miképen a költőitek közül is mondották némelyek: Mert az ő nemzetsége is vagyunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 29, 'Mivelhogy azért az Istennek nemzetsége vagyunk, nem kell azt gondolnunk, hogy aranyhoz, vagy ezüsthöz, vagy kőhöz, emberi mesterség és kitalálás faragványához hasonlatos az istenség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 30, 'E tudatlanságnak idejét azért elnézvén az Isten, mostan parancsolja az embereknek, mindenkinek mindenütt, hogy megtérjenek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 31, 'Mivelhogy rendelt egy napot, melyen megítéli majd a föld kerekségét igazságban egy férfiú által, kit arra rendelt; bizonyságot tévén mindenkinek, az által, hogy feltámasztá őt halottaiból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 32, 'Mikor pedig a halottak feltámadásáról hallottak, némelyek gúnyolódtak; mások pedig mondának: Majd még meghallgatunk téged e felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 33, 'És ilyen módon Pál kiméne azok közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 34, 'Némely férfiak azonban csatlakozván ő hozzá, hivének; ezek között az areopágita Dienes is, és egy Damaris nevű asszony, és mások ő velök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 1, 'Ezekután Pál Athénből eltávozván, méne Korinthusba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 2, 'És mikor egy Akvila nevű, pontusi származású zsidóra talált, ki nem régen jött Itáliából, és feleségére Prisczillára (mivelhogy Klaudius megparancsolta vala, hogy a zsidók mind távozzanak Rómából): hozzájuk csatlakozék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 3, 'És mivelhogy azonféle míves vala, náluk marada és dolgozik vala. Mesterségökre nézve ugyanis sátorcsinálók valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 4, 'Vetekedék pedig minden szombaton a zsinagógában, és igyekezék mind zsidókat, mind görögöket meggyőzni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 5, 'Mikor pedig megérkeztek Maczedóniából Silás és Timótheus, szorongatá a lélek Pált, és bizonyságot tőn a zsidóknak, hogy Jézus a Krisztus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 6, 'Mikor pedig azok ellenszegülének és káromlásokat szólának, ruháit megrázva monda nékik: Véretek a fejetekre; én tiszta vagyok: mostantól fogva a pogányokhoz megyek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 7, 'És általmenvén onnét, méne egy Justus nevű, istenfélő ember házához, kinek háza szomszédos vala a zsinagógával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 8, 'Krispus pedig, a zsinagógának feje hűn az Úrban egész házanépével egybe; a Korinthusbeliek közül is sokan hallván, hisznek vala, és megkeresztelkednek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 9, 'Monda pedig az Úr látás által éjszaka Pálnak: Ne félj, hanem szólj és ne hallgass:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 10, 'Mert én veled vagyok és senki sem támad reád, hogy néked ártson; mert nékem sok népem van ebben a városban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 11, 'És ott lakozék egy esztendeig és hat hónapig, tanítva köztük az Isten ígéjét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 12, 'Mikor pedig Gallió volt Akhája tiszttartója, reátámadának a zsidók egyakarattal Pálra, és vivék őt a törvényszék elébe,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 13, 'Mondván: Ez a törvény ellen való istentiszteletre csábítja az embereket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 14, 'Mikor pedig Pál meg akará nyitni száját, monda Gallió a zsidóknak: Ha valóban valami bosszútételről, vagy gonosz cselekedetről volna szó, zsidók, igazság szerint meghallgatnálak benneteket:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 15, 'De ha tanításról, nevekről és a ti törvénytekről van kérdés, ti magatok lássátok; mert én ezekben bíró nem akarok lenni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 16, 'És elűzé őket a törvényszék elől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 17, 'A görögök pedig mindnyájan Sosthenest, a zsinagógának fejét megragadván, verik vala a törvényszék előtt; de Gallió velök semmit sem gondola.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 18, 'Pál pedig, miután még több napig ott marada, az atyafiaktól elbúcsúzván, Siriába hajózék, és vele együtt Prisczilla és Akvila, minekutána fejét megnyírta Kenkreában; mert fogadása vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 19, 'Juta pedig Efézusba, és azokat ott hagyá; ő maga pedig bemenvén a zsinagógába, vetekedék a zsidókkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 20, 'Mikor pedig azok kérék, hogy több ideig maradjon nálok, nem álla reá;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 21, 'Hanem búcsút vőn tőlük, mondván: Mindenesetre Jeruzsálemben kell nékem a következő ünnepet töltenem; de ismét megjövök hozzátok, ha Isten akarja. És elhajózék Efézusból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 22, 'És miután Czézáreába érkezék, felmenvén Jeruzsálembe és köszöntvén a gyülekezetet, leméne Antiókhiába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 23, 'És miután ott bizonyos időt eltöltött, elméne, eljárván renddel Galácia tartományát és Frigiát, erősítve a tanítványokat mind.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 24, 'Érkezék pedig Efézusba egy Apollós nevű zsidó, alekszandriai származású, ékesenszóló férfiú, ki az írásokban tudós vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 25, 'Ez meg volt tanítva az Úrnak útára; és lélekben buzgó lévén, szólja és tanítja vala nagy szorgalmatosan az Úrra tartozó dolgokat, jóllehet csak a János keresztségét tudja vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 26, 'És ez kezde nagy bátorsággal szólni a zsinagógában. Mikor pedig meghallgatta őt Akvila és Prisczilla, magok mellé vevék őt, és nyilvábban kifejtették előtte az Istennek útát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 27, 'Mikor pedig Akhájába akara átmenni, buzdítván őt az atyafiak, írának a tanítványoknak, hogy fogadják be őt. Ki mikor odajutott, sokat használa azoknak, kik hittek vala a kegyelem által:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 28, 'Mert hatalmasan meggyőzi vala a zsidókat nyilvánosan, bebizonyítva az írásokból, hogy Jézus a Krisztus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, 'Lőn pedig azonközben, míg Apollós Korinthusban volt, hogy Pál, eljárván a felsőbb tartományokat, Efézusba érkezék: és mikor némely tanítványokra talált,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, 'Monda nékik: Vajjon vettetek-é Szent Lelket, minekutána hivőkké lettetek? Azok pedig mondának néki: Sőt inkább azt sem hallottuk, hogy ha vagyon-é Szent Lélek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, 'És monda nékik: Mire keresztelkedtetek meg tehát? Azok pedig mondának: A János keresztségére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, 'Monda pedig Pál: János megtérésnek keresztségével keresztelt, azt mondván a népnek, hogy a ki ő utána jövendő, abban higyjenek, tudniillik a Krisztus Jézusban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, 'Mikor pedig ezt hallák, megkeresztelkedének az Úr Jézusnak nevére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, 'És mikor Pál reájok vetette kezét, szálla a Szent Lélek ő reájok; és szólnak vala nyelveken, és prófétálnak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, 'Valának pedig a férfiak összesen mintegy tizenketten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, 'Bemenvén pedig a zsinagógába, bátorsággal szól vala, három hónapon át vetekedvén és igyekezvén meggyőzni az Isten országára tartozó dolgokról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 9, 'Mikor pedig némelyek megkeményíték magokat és nem hivének, gonoszul szólván az Úrnak útáról a sokaság előtt, azoktól eltávozván, elszakasztá a tanítványokat, mindennap egy bizonyos Tirannus oskolájában prédikálván.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 10, 'Ez pedig lőn két esztendeig; úgyannyira, hogy mindazok, kik lakoznak vala Ázsiában, mind zsidók, mind görögök, hallgaták az Úr Jézusnak ígéjét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 11, 'És nem közönséges csodákat cselekszik vala az Isten Pál keze által:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 12, 'Annyira, hogy a betegekhez is elvivék az ő testéről a keszkenőket, vagy kötényeket, és eltávozának azoktól a betegségek, és a gonosz lelkek kimenének belőlök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 13, 'Elkezdték pedig némelyek a lézengő zsidó ördögűzők közül az Úr Jézus nevét hívni azokra, a kikben gonosz lelkek valának, mondván: Kényszerítünk titeket a Jézusra, kit Pál prédikál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 14, 'Valának pedig némelyek Skévának, egy zsidó főpapnak fiai heten, a kik ezt mívelik vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 15, 'Felelvén pedig a gonosz lélek, monda: A Jézust ismerem, Pálról is tudok; de ti kicsodák vagytok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 16, 'És reájok ugorván az az ember, a kiben a gonosz lélek vala, és legyőzvén őket, hatalmat vőn rajtuk annyira, hogy mezítelenen és megsebesülve szaladának ki abból a házból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 17, 'Ez pedig tudtokra lőn mindeneknek, mind zsidóknak, mind görögöknek, kik Efézusban laknak vala, és félelem szálla mindnyájokra, és magasztaltatik vala az Úr Jézusnak neve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 18, 'És sokan a hívők közül eljőnek vala, megvallván és megjelentvén cselekedeteiket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 19, 'Sokan pedig azok közül, kik ördögi mesterségeket gyakoroltak, könyveiket összehordva, mindeneknek láttára megégetik vala. És összeszámlálák azoknak árát, és találák ötvenezer ezüstpénznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 20, 'Ekképen az Úrnak ígéje erősen nevekedik és hatalmat vesz vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 21, 'Midőn pedig ezek elteltek, elvégezé Pál magában, hogy Maczedóniát és Akháját eljárván, Jeruzsálembe megy, mondván: Ott létem után Rómát is meg kell nékem látnom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 22, 'Elküldvén pedig Maczedóniába kettőt azok közül, kik néki szolgálnak vala, Timótheust és Erástust, ő maga egy ideig Ázsiában marada.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 23, 'Támada azonban azon időtájban nem csekély háborúság az Úrnak útárt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 24, 'Mert egy Demeter nevű ötvös, ezüstből Diána templomokat csinálván, a mesterembereknek nem csekély nyereséget ád vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 25, 'Kiket egybegyűjtvén az ilyenfélékkel foglalkozó mívesekkel egybe, monda: Férfiak, tudjátok, hogy ebből a mesterségből van a mi jóllétünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 26, 'Látjátok pedig és halljátok, hogy ez a Pál nemcsak Efézusnak, hanem közel az egész Ázsiának sok népét eláltatván, elfordította, mivelhogy azt mondja, hogy nem istenek azok, a melyek kézzel csináltatnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 27, 'Nemcsak az a veszély fenyeget pedig bennünket, hogy ez a mesterség tönkre jut, hanem hogy a nagy istenasszonynak, Diánának temploma is semmibe vétetik, és el is vész az ő nagysága, kit az egész Ázsia és a világ tisztel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 28, 'Mikor pedig ezeket hallották és haraggal megtelének, kiáltnak vala, mondván: Nagy az efézusi Diána!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 29, 'És betelék az egész város háborúsággal; és egyakarattal a színházba rohanának, megfogván Gájust és Aristárkhust, kik Maczedóniából valók és Pálnak útitársai valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 30, 'Pál pedig mikor a nép közé akara menni, nem ereszték őt a tanítványok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 31, 'És az ázsiai főpapok közül is némelyek, kik barátai valának néki, küldvén ő hozzá, kérék, hogy ne menjen a színházba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 32, 'Már most ki egyet, ki mást kiáltoz vala, mert a népgyűlés összezavarodott volt, és a többség nem tudta, miért gyűltek össze.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 33, 'A sokaság közül pedig előállaták Alekszándert, minthogy előre tuszkolták őt a zsidók. Alekszánder pedig kezével intvén, védekezni akara a nép előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 34, 'Megismervén azonban, hogy zsidó, egy kiáltás tört ki mindnyájokból, mintegy két óra hosszáig kiáltozván: Nagy az efézusi Diána!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 35, 'Miután pedig a városi jegyző lecsendesítette a sokaságot, monda: Efézusbeli férfiak, ugyan kicsoda az az ember, a ki ne tudná, hogy Efézus városa a nagy Diána istenasszonynak és a Jupitertől esett képnek templomőrzője?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 36, 'Mivelhogy azért ezeknek senki ellene nem szólhat, szükség, hogy megcsendesedjetek, és semmi vakmerő dolgot ne cselekedjetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 37, 'Mert ide hoztátok ez embereket, kik sem nem szentségrontók, sem a ti istenasszonyotok ellen káromlást nem szóltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 38, 'Ha tehát Demeternek és a hozzátartozó mesterembereknek valaki ellen panaszuk van, törvényszékek vannak, és tiszttartók vannak: pereljenek egymással.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 39, 'Ha pedig egyéb dolgok felől van valami panasztok, a törvényes népgyűlésen majd elintéztetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 40, 'Mert félő, hogy lázadással vádoltatunk a mai napért, mivelhogy semmi ok sincs, a melylyel számot tudnánk adni ezért a csődületért. És ezeket mondván, feloszlatá a gyűlést.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 1, 'Minekutána pedig megszűnt a háborúság, magához híván Pál a tanítványokat és tőlük búcsút vévén, elindula, hogy Maczedóniába menjen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 2, 'Miután pedig azokat a tartományokat eljárta, és intette őket bő beszéddel, Görögországba méne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 3, 'És ott töltött három hónapot. És mivelhogy a zsidók lest hánytak néki, a mint Siriába készült hajózni, úgy végezé, hogy Maczedónián át tér vissza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 4, 'Kíséré pedig őt Ázsiáig a béreai Sopater, a Thessalonikabeliek közül pedig Aristárkhus és Sekundus, és a derbei Gájus és Timótheus; Ázsiabeliek pedig Tikhikus és Trofimus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 5, 'Ezek előremenvén, megvárának minket Troásban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 6, 'Mi pedig a kovásztalan kenyerek napjai után kievezénk Filippiből, és menénk ő hozzájok Troásba öt nap alatt; hol hét napot tölténk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 7, 'A hétnek első napján pedig a tanítványok egybegyűlvén a kenyér megszegésére, Pál prédikál vala nékik, mivelhogy másnap el akara menni; és a tanítást megnyújtá éjfélig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 8, 'Vala pedig elegendő szövétnek abban a felházban, a hol egybe valának gyülekezve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 9, 'Egy Eutikhus nevű ifjú pedig ül vala az ablakban, mély álomba merülve: és mivelhogy Pál sok ideig prédikála, elnyomatván az álom által, aláesék a harmadik rend házból, és halva véteték föl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 10, 'Pál pedig alámenvén, reá borula, és magához ölelve monda: Ne háborogjatok; mert a lelke benne van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 11, 'Azután fölméne, és megszegé a kenyeret és evék, és sokáig, mind virradatig beszélgetvén, úgy indula el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 12, 'Felhozák pedig az ifjat elevenen, és felette igen megvigasztalódának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 13, 'Mi pedig előremenvén a hajóra, Assusba evezénk, ott akarván fölvenni Pált; mert így rendelkezett, ő maga gyalog akarván jőni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 14, 'Mikor pedig Assusban összetalálkozott velünk, felvévén őt, menénk Mitilénébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 15, 'És onnét elevezvén, másnap eljutánk Khius ellenébe; a következőn pedig áthajózánk Sámusba; és Trogilliumban megszállván, másnap mentünk Milétusba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 16, 'Mert elvégezé Pál, hogy Efézus mellett elhajózik, hogy ne kelljen néki időt múlatni Ázsiában; mert siet vala, hogy ha lehetne néki, pünkösd napjára Jeruzsálemben legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 17, 'Milétusból azonban küldvén Efézusba, magához hívatá a gyülekezet véneit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 18, 'Mikor pedig hozzá mentek, monda nékik: Ti tudjátok, hogy az első naptól fogva, melyen Ázsiába jöttem, mint viseltem magamat ti köztetek az egész idő alatt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 19, 'Szolgálván az Úrnak teljes alázatossággal és sok könnyhullatás és kisértetek közt, melyek én rajtam a zsidóknak utánam való leselkedése miatt estek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 20, 'Hogy semmitől sem vonogattam magamat, a mi hasznos, hogy hirdessem néktek, és tanítsalak titeket nyilvánosan és házanként,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 21, 'Bizonyságot tévén mind zsidóknak, mind görögöknek az Istenhez való megtérés, és a mi Urunk Jézus Krisztusban való hit felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 22, 'És most ímé én a Lélektől kényszerítve megyek Jeruzsálembe, nem tudván, mik következnek ott én reám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 23, 'Kivéve, hogy a Szent Lélek városonként bizonyságot tesz, mondván, hogy én reám fogság és nyomorúság következik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 24, 'De semmivel sem gondolok, még az én életem sem drága nékem, csakhogy elvégezhessem az én futásomat örömmel, és azt a szolgálatot, melyet vettem az Úr Jézustól, hogy bizonyságot tegyek az Isten kegyelmének evangyéliomáról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 25, 'És most íme én tudom, hogy nem látjátok többé az én orczámat ti mindnyájan, kik között általmentem, prédikálván az Istennek országát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 26, 'Azért bizonyságot teszek előttetek a mai napon, hogy én mindeneknek vérétől tiszta vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 27, 'Mert nem vonogattam magamat, hogy hirdessem néktek az Istennek teljes akaratát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 28, 'Viseljetek gondot azért magatokra és az egész nyájra, melyben a Szent Lélek titeket vigyázókká tett, az Isten anyaszentegyházának legeltetésére, melyet tulajdon vérével szerzett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 29, 'Mert én tudom azt, hogy az én eltávozásom után jőnek ti közétek gonosz farkasok, kik nem kedveznek a nyájnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 30, 'Sőt ti magatok közül is támadnak férfiak, kik fonák dolgokat beszélnek, hogy a tanítványokat magok után vonják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 31, 'Azért vigyázzatok, megemlékezvén arról, hogy én három esztendeig éjjel és nappal meg nem szüntem könnyhullatással inteni mindenkit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 32, 'És most, atyámfiai, ajánlak titeket az Istennek és az ő kegyelmessége ígéjének, a ki felépíthet és adhat néktek örökséget minden megszenteltek közt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 33, 'Senkinek ezüstjét, vagy aranyát, vagy ruháját nem kívántam:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 34, 'Sőt magatok tudjátok, hogy a magam szükségeiről és a velem valókról ezek a kezek gondoskodtak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 35, 'Mindenestől megmutattam néktek, hogy ily módon munkálkodva kell az erőtlenekről gondot viselni, és megemlékezni az Úr Jézus szavairól, mert ő mondá: Jobb adni, mint venni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 36, 'És mikor ezeket mondotta, térdre esve imádkozék mindazokkal egybe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 37, 'Mindnyájan pedig nagy sírásra fakadtak; és Pálnak nyakába borulva csókolgaták őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 38, 'Keseregve kiváltképen azon a szaván, a melyet mondott, hogy többé az ő orczáját nem fogják látni. Aztán elkísérték őt a hajóra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 1, 'A mint pedig, ő tőlük elszakadván, elindultunk, egyenesen haladva Kóusba érkezénk, másnap pedig Rhodusba, és onnét Patarába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 2, 'És mikor találtunk egy hajót, mely Fenicziába méne által, abba beülvén, elhajózánk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 3, 'És miután megláttuk Cziprust és elhagytuk azt balkézre, evezénk Siriába, és Tirusban köténk ki: mert a hajó ott rakja vala ki a terhét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 4, 'És ott maradánk hét napig, miután feltaláltuk a tanítványokat, kik Pálnak mondják vala a Lélek által, hogy ne menjen fel Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 5, 'Mikor pedig eltöltöttük azokat a napokat, kimenvén, elutazánk; kikísérvén bennünket mindnyájan feleségestől, gyermekestől egészen a városon kívülre. És a tenger partján térdre esve imádkozánk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 6, 'És egymástól elbúcsúzván, beülénk a hajóba, azok pedig megtérének az övéikhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 7, 'Mi pedig a hajózást bevégezvén, Tirusból eljutánk Ptolemaisba; és köszöntvén az atyafiakat, nálok maradánk egy napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 8, 'Másnap pedig elmenvén Pál és mi, kik ő vele valánk, érkezénk Czezáreába; és bemenvén a Filep evangyélista házába, ki ama hét közül való vala, ő nála maradánk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 9, 'Ennek pedig vala négy szűz leánya, a kik prófétálnak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 10, 'Mialatt pedig mi több napig ott maradánk, alájöve egy Júdeából való próféta, névszerint Agabus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 11, 'És mikor hozzánk jött, vevé Pálnak az övét, és megkötözvén a maga kezeit és lábait, monda: Ezt mondja a Szent Lélek: A férfiút, a kié ez az öv, ekképen kötözik meg a zsidók Jeruzsálemben, és adják a pogányoknak kezébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 12, 'Mikor pedig ezeket hallottuk, kérők, mind mi, mind az oda valók, hogy ne menjen fel Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 13, 'De Pál felele: Mit míveltek sírván és az én szívemet kesergetvén? mert én nemcsak megkötöztetni, hanem meghalni is kész vagyok Jeruzsálemben az Úr Jézusnak nevéért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 14, 'Mikor azért nem engedett, megnyugodtunk, mondván: Legyen meg az Úrnak akaratja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 15, 'E napok után pedig felkészülődvén, felmenénk Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 16, 'Jövének pedig mi velünk együtt a tanítványok közül is Czézáreából, kik elvezetének bizonyos cziprusi Mnásonhoz, egy régi tanítványhoz, hogy ott legyen szállásunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 17, 'Mikor azért Jeruzsálembe jutottunk, örömmel fogadának minket az atyafiak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 18, 'Másnap pedig beméne Pál velünk együtt Jakabhoz; és a vének mindnyájan ott valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 19, 'És köszöntvén őket, elbeszélé egyenként, a miket az Isten a pogányok között az ő szolgálata által cselekedett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 20, 'Azok pedig ezt hallván, dicsőíték az Urat; és mondának néki: Látod, atyámfia, mely sok ezeren vannak zsidók, kik hívőkké lettek; és mindnyájan buzognak a törvény mellett:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 21, 'Felőled pedig azt hallották, hogy te mindazokat a zsidókat, kik a pogányok között vannak, Mózestől való elszakadásra tanítod, azt mondván, hogy ne metéljék körül fiaikat, se a zsidó szokások szerint ne járjanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 22, 'Micsoda annakokáért? Mindenesetre össze kell gyülekezni a sokaságnak; mert meghallják, hogy ide jöttél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 23, 'Ezt míveld azért, a mit néked mondunk: Van mi köztünk négy férfiú, kik fogadalmat vettek magokra;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 24, 'Ezeket magad mellé vévén, tisztulj meg velök, és költs rájok, hogy megnyíressék fejöket: és megtudják mindenek, hogy semmi sincs azokban, a miket te felőled hallottak; hanem te magad is úgy jársz, hogy a törvényt megtartod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 25, 'A pogányokból lett hívők felől pedig mi írtunk, azt végezvén, hogy ők semmi ilyenfélét ne tartsanak meg, hanem csak oltalmazzák meg magokat mind a bálványoknak áldozott hústól, mind a vértől, mind a fúlvaholt állattól, mind a paráznaságtól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 26, 'Akkor Pál maga mellé véve azokat a férfiakat, másnap ő velök megtisztulván, beméne a templomba, bejelentvén a tisztulás napjainak eltelését, a míg mindegyikökért elvégeztetik az áldozat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 27, 'Mikor pedig a hét nap immár eltelőben volt, az Ázsiából való zsidók, meglátván őt a templomban, felindíták az egész sokaságot, és reá veték kezöket,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 28, 'Kiáltván: Izraelita férfiak, legyetek segítségül: ez az az ember, ki e nép ellen, a törvény ellen és e hely ellen tanít mindenkit mindenütt; ezen felül még görögöket is hozott be a templomba, és megfertéztette ezt a szent helyet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 29, 'Mert látták vala annakelőtte az efézusi Trofimust ő vele a városban, kiről azt vélék, hogy Pál bevitte a templomba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 30, 'Megmozdula azért az egész város, és a nép összecsődüle: és Pált megragadván, vonszolják vala ki őt a templomból: és mindjárt bezáratának az ajtók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 31, 'Mikor pedig meg akarák őt ölni, feljuta a hír a sereg ezredeséhez, hogy az egész Jeruzsálem felzendült.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 32, 'Ki azonnal vitézeket és századosokat vévén maga mellé, lefutott hozzájok. Azok pedig mikor meglátták az ezredest és a vitézeket, megszűnének Pált verni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 33, 'Akkor odaérvén az ezredes, elfogatá őt, és parancsolá, hogy kötözzék meg két lánczczal; és tudakozá, hogy kicsoda és mit cselekedett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 34, 'De ki egyet, ki mást kiált vala a sokaság között; és mikor nem értheté meg a bizonyos valóságot a zajongás miatt, parancsolá, hogy vigyék el őt a várba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 35, 'Mikor pedig a lépcsőkhöz jutott, lőn, hogy úgy vivék őt a vitézek a néptömeg erőszaktétele miatt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 36, 'Mert követi vala a népnek sokasága, kiáltozva: Öld meg őt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 37, 'És mikor immár a várba akarák bevinni Pált, monda az ezredesnek: Vajjon szabad-e nékem valamit szólanom te hozzád? Az pedig monda: Tudsz görögül?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 38, 'Hát nem te vagy az az egyiptomi, ki e napoknak előtte fellázította és kivitte a pusztába azt a négyezer orgyilkos férfiút?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 39, 'Monda pedig Pál: Én ugyan tárzusi zsidó ember vagyok, Cziliczia nem ismeretlen városának polgára; de kérlek téged, engedd meg nékem, hogy szóljak a néphez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 40, 'Mikor aztán az megengedte, Pál a lépcsőkön állva intett kezével a népnek: és mikor nagy csendesség lőn, megszólala zsidó nyelven, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 1, 'Atyámfiai, férfiak és atyák, hallgassátok meg az én beszédemet, a melylyel most magamat előttetek mentem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 2, 'Mikor pedig hallották, hogy zsidó nyelven szól hozzájok, még inkább nyugalmat tanusítottak. És monda:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 3, 'Én zsidó ember vagyok, születtem a czilicziai Tárzusban, fölneveltettem pedig ebben a városban a Gamáliel lábainál, taníttattam az atyák törvényének pontossága szerint, buzgó lévén az Istenhez, miként ti mindnyájan vagytok ma:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 4, 'És ezt a tudományt üldöztem mind halálig, megkötözvén és tömlöczbe vetvén mind férfiakat, mind asszonyokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 5, 'Miképen a főpap is bizonyságom nékem, és a véneknek egész tanácsa; kiktől leveleket is vévén az atyafiakhoz, Damaskusba menék, hogy az odavalókat is fogva hozzam Jeruzsálembe, hogy bűnhődjenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 6, 'Lőn pedig, hogy a mint menék és közelgeték Damaskushoz, déltájban nagy hirtelenséggel az égből nagy világosság sugárzott körül engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 7, 'És leesém a földre, és hallék szót, mely monda nékem: Saul, Saul, mit kergetsz engem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 8, 'Én pedig felelék: Kicsoda vagy, Uram? És monda nékem: Én vagyok a názáreti Jézus, a kit te kergetsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 9, 'A kik pedig velem valának, a világosságot ugyan látták, és megrémültek; de annak szavát, a ki velem szól vala, nem hallották.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 10, 'Én pedig mondék: Mit cselekedjem, Uram? Az Úr pedig monda nékem: Kelj fel és menj el Damaskusba; és ott megmondják néked mindazokat, a mik elrendelvék néked, hogy véghez vigyed.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 11, 'Mikor pedig nem láték annak a világosságnak dicsősége miatt, a velem valóktól kézenfogva vezettetve menék Damaskusba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 12, 'Egy bizonyos Ananiás pedig, ki a törvény szerint istenfélő férfiú, kiről az ott lakó zsidók mind jó bizonyságot tesznek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 13, 'Hozzám jöve és mellém állva monda nékem: Saul atyámfia, nyerd vissza szemed világát. És én azon szempillantásban reá tekintettem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 14, 'Ő pedig monda: A mi atyáinknak Istene választott téged, hogy megismerd az ő akaratát, és meglásd amaz Igazat, és szót hallj az ő szájából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 15, 'Mert leszel néki tanúbizonysága minden embernél azok felől, a miket láttál és hallottál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 16, 'Most annakokáért mit késedelmezel? Kelj fel és keresztelkedjél meg és mosd le a te bűneidet, segítségül híván az Úrnak nevét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 17, 'Lőn pedig, hogy mikor Jeruzsálembe megtértem és imádkozám a templomban, elragadtatám lelkemben,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 18, 'És látám őt, ki ezt mondá nékem: Siess és menj ki hamar Jeruzsálemből: mert nem veszik be a te tanúbizonyságtételedet én felőlem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 19, 'És én mondék: Uram, ők magok tudják, hogy én tömlöczbe vetettem és vertem zsinagógánként azokat, a kik hisznek vala te benned:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 20, 'És mikor ama te mártírodnak, Istvánnak vére kiontaték, én is ott állék és helyeslém az ő megöletését, és őrizém azoknak köntösét, a kik őt megölték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 21, 'És monda nékem: Eredj el, mert én téged messze küldelek a pogányok közé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 22, 'Hallgatják vala pedig őt e szóig; de most felemelék szavokat, mondván: Töröld el a földszínéről az ilyent, mert nem illik néki élni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 23, 'Mikor pedig azok kiabáltak, és köntösüket elhányák, és port szórának a levegőbe,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 24, 'Parancsolá az ezredes, hogy vigyék őt a várba, mondván, hogy korbácsütésekkel vallassák ki őt, hogy megtudhassa, mi okért kiabáltak úgy reá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 25, 'A mint azonban lekötötték őt a szíjakkal, monda Pál az ott álló századosnak: Vajjon szabad-é néktek római embert, kit el nem ítéltek, megostorozni?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 26, 'Miután pedig ezt meghallá a százados, elmenvén, megjelenté az ezredesnek, mondván: Meglásd, mit akarsz cselekedni; mert ez az ember római.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 27, 'Hozzámenvén azért az ezredes, monda néki: Mondd meg nékem, te római vagy-é? Ő pedig monda: Az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 28, 'És felele az ezredes: Én nagy összegért vettem meg ezt a polgárjogot. Pál pedig monda: Én pedig benne is születtem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 29, 'Mindjárt eltávozának azért ő tőle, a kik őt vallatni akarák. Sőt az ezredes is megijede, mikor megértette, hogy római, és hogy őt megkötöztette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 30, 'Másnap pedig meg akarván tudni a bizonyos valóságot, miben vádoltatik a zsidóktól, feloldatá őt bilincseiből, és megparancsolá, hogy a főpapok az ő egész tanácsokkal egyben hozzá menjenek; és levezetvén Pált, eleikbe állatá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 1, 'Mikor pedig a tanácsra vetette szemét Pál, monda: Atyámfiai, férfiak, én teljes jó lelkiismerettel szolgáltam az Istennek mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 2, 'Ananiás főpap pedig megparancsolá azoknak, kik ő mellette állanak vala, hogy üssék őt szájon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 3, 'Akkor Pál monda néki: Megver az Isten téged, te kimeszelt fal! És te leülsz engem a törvény szerint megítélni, és törvényellenesen cselekedve parancsolod, hogy engem verjenek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 4, 'Az ott állók pedig mondának: Az Istennek főpapját szidalmazod-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 5, 'Pál pedig monda: Nem tudtam, atyámfiai, hogy főpap. Mert meg van írva: A te néped fejedelmét ne átkozd!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 6, 'Mikor pedig Pál eszébe vette, hogy az egyik részök a sadduczeusok, a másik pedig a farizeusok közül való, felkiálta a tanács előtt: Atyámfiai, férfiak, én farizeus vagyok, farizeus fia, a halottak reménysége és feltámadása miatt vádoltatom én.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 7, 'A mint pedig ő ezt mondta, meghasonlás támada a farizeusok és a sadduczeusok között, és a sokaság megoszlott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 8, 'Mert a sadduczeusok azt mondják, hogy nincs feltámadás, sem angyal, sem lélek; a farizeusok pedig mind a kettőt vallják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 9, 'Támada azért nagy kiáltozás: és felkelvén az írástudók a farizeusok pártjából, tusakodnak vala, mondván: Semmi rosszat sem találunk ez emberben; ha pedig lélek szólott néki, vagy angyal, ne tusakodjunk Isten ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 10, 'Mikor pedig nagy hasonlás támadt, félvén az ezredes, hogy Pál szétszaggattatik azoktól, parancsolá, hogy a sereg alájővén, ragadja ki őt közülök, és vigye el a várba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 11, 'A következő éjszakán pedig melléállván néki az Úr, monda: Bízzál Pál! Mert miképen bizonyságot tettél az én felőlem való dolgokról Jeruzsálemben, azonképen kell néked Rómában is bizonyságot tenned.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 12, 'Midőn pedig nappal lőn, a zsidók közül némelyek összeszövetkezvén, átok alatt kötelezék el magokat, mondván, hogy sem nem esznek, sem nem isznak addig, míg meg nem ölik Pált.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 13, 'Többen valának pedig negyvennél, kik ezt az összeesküvést szőtték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 14, 'Ezek elmenvén a főpapokhoz és a vénekhez, mondának: Átok alatt megesküdtünk, hogy semmit nem ízlelünk addig, míg meg nem öljük Pált.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 15, 'Most azért ti jelentsétek be az ezredesnek a tanácscsal egybe, hogy holnap hozza le őt ti hozzátok, mintha az ő dolgának tüzetesebben végére akarnátok járni. Mi pedig, minekelőtte ő ide érne, készek vagyunk őt megölni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 16, 'Meghallván azonban a Pál nőtestvérének fia e cselvetést, megjelenvén és bemenvén a várba, tudtára adá Pálnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 17, 'Pál pedig egyet a századosok közül magához hívatván, monda: Ezt az ifjat vezesd az ezredeshez; mert valamit akar néki jelenteni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 18, 'Az annakokáért maga mellé vévén őt, vivé az ezredeshez, és monda: A fogoly Pál magához hivatván engem, kéré, hogy ez ifjat hozzád vezessem, mert valamit akar néked mondani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 19, 'Az ezredes pedig őt kézen fogván, és félrevonulván külön, tudakolá: Micsoda az, a mit nékem jelenteni akarsz?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 20, 'Az pedig monda: A zsidók elvégezték, hogy megkérnek téged, hogy Pált holnap vidd le a tanács elé, mintha valamit tüzetesebben meg akarnának tudakozni ő felőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 21, 'Te azért ne engedj nékik: mert közülök negyvennél több férfiú leselkedik ő utána, kik átok alatt kötelezték el magukat, hogy sem nem esznek, sem nem isznak addig, míg meg nem ölik őt. És immár készen vannak, várakozva a te izenetedre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 22, 'Az ezredes tehát elbocsátá az ifjat, meghagyván néki, hogy el ne mondd senkinek, hogy ezeket megjelentetted nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 23, 'És magához hivatván kettőt a századosok közül, monda: Készítsetek föl kétszáz vitézt, hogy induljanak Czézáreába, és hetven lovast, és kétszáz parittyást, az éjszakának harmadik órájától fogva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 24, 'És hogy barmokat is adjanak melléjük, hogy Pált felültetve békességgel vigyék Félix tiszttartóhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 25, 'Levelet is írt, melynek tartalma ez vala:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 26, 'Klaudius Lisiás a nemes Félix tiszttartónak üdvöt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 27, 'Ezt a férfiút, kit a zsidók megfogtak és meg akartak ölni, oda menvén a sereggel, kiszabadítám, megértvén, hogy római.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 28, 'Meg akarván pedig tudni az okát, miért vádolják őt, levivém őt az ő tanácsuk elébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 29, 'És úgy találtam, hogy ő az ő törvényüknek kérdései felől vádoltatik, de semmi halálra vagy fogságra méltó vétke nincs.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 30, 'Minthogy pedig nékem megjelentették, hogy a zsidók e férfiú után ólálkodni akarnak, azonnal hozzád küldém, meghagyva vádolóinak is, hogy a mi dolguk van ő ellene, te előtted mondják meg. Légy jó egészségben!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 31, 'A vitézek tehát, a mint nékik megparancsolták, Pált felvévén, elvivék azon éjszakán Antipatrisba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 32, 'Másnap pedig hagyván a lovagokat tovább menni ő vele, visszatérének a várba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 33, 'Azok pedig eljutván Czézáreába, és átadván a levelet a tiszttartónak, Pált is elébe állaták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 34, 'Mikor pedig elolvasta a tiszttartó, és megkérdezte, melyik tartományból való, és megértette, hogy Czilicziából,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 35, 'Monda: Majd kihallgatlak, mikor vádlóid is eljőnek. És parancsolá, hogy a Héródes palotájában őrizzék őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 1, 'Öt nap mulva aztán aláméne Ananiás főpap a vénekkel és egy Tertullus nevű prókátorral, kik panaszt tettek a tiszttartónál Pál ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 2, 'Mikor pedig ő előszólíttatott, Tertullus vádolni kezdé, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 3, 'Nagyságos Félix, teljes háládatossággal ismerjük el, hogy te általad nagy békességet nyerünk, és a te gondoskodásod folytán igen jó intézkedések történnek e népre nézve, minden tekintetben és mindenütt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 4, 'De hogy téged sok ideig ne tartóztassalak, kérlek hallgass meg minket röviden a te kegyelmességed szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 5, 'Mi ugyanis úgy találtuk, hogy ez veszedelmes ember, és hasonlást támaszt a föld kerekségén levő valamennyi zsidó közt, és a nazarénusok felekezetének feje,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 6, 'Ki a templomot is meg akarta fertőztetni. Meg is fogtuk őt, és a mi törvényünk szerint akartuk megítélni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 7, 'De Lisiás, az ezredes, nagy karhatalommal oda jövén, kivevé őt kezünkből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 8, 'És azt parancsolá, hogy az ő vádolói hozzád jőjjenek. Tőle te magad, ha kihallgatod, értesülhetsz mindezekről, melyekkel mi őt vádoljuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 9, 'Helybenhagyák pedig a zsidók is, mondogatván, hogy úgy vannak ezek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 10, 'Felele pedig Pál, miután intett néki a tiszttartó a szólásra: Mivelhogy tudom, hogy te sok esztendő óta vagy e népnek bírája, bátorságosabban védekezem a magam ügyében,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 11, 'Mert megtudhatod, hogy nincsen tizenkét napjánál több, mióta feljöttem imádkozni Jeruzsálembe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 12, 'És a templomban sem találtak engem, hogy valakivel vetekedtem volna, vagy hogy a népet egybezendítettem volna, sem a zsinagógákban, sem a városban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 13, 'Rám sem bizonyíthatják azokat, a mikkel most engem vádolnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 14, 'Erről pedig vallást teszek néked, hogy én a szerint az út szerint, melyet felekezetnek mondanak, úgy szolgálok az én atyáim Istenének, mint a ki hiszek mindazokban, a mik a törvényben és a prófétákban meg vannak írva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 15, 'Reménységem lévén az Istenben, hogy a mit ezek maguk is várnak, lesz feltámadásuk a halottaknak, mind igazaknak, mind hamisaknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 16, 'Ebben gyakorlom pedig magamat, hogy botránkozás nélkül való lelkiismeretem legyen az Isten és emberek előtt mindenkor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 17, 'Sok esztendő múlva pedig eljövék, hogy az én népemnek alamizsnát hozzak és áldozatokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 18, 'Ezek közben találának engem megtisztulva a templomban, nem sokasággal, sem pedig háborúságtámasztásban, némely Ázsiából való zsidók,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 19, 'Kiknek ide kellett volna te elődbe jőni és vádolni, ha valami panaszuk volna ellenem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 20, 'Avagy ezek magok mondják meg, vajjon találtak-é bennem valami hamis cselekedetet, mikor én a tanács előtt álltam;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 21, 'Hacsak ez egy szó tekintetében nem, melyet közöttük állva kiáltottam, hogy: A halottak feltámadása felől vádoltatom én tőletek e mai napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 22, 'Mikor pedig ezeket hallotta Félix, elhalasztá dolgukat, mivelhogy tüzetesebb tudomása volt e szerzet dolgai felől, és monda: Mikor Lisias ezredes alájő, dönteni fogok ügyetekben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 23, 'És megparancsolá a századosnak, hogy Pált őrizzék, de enyhébb fogságban legyen, és senkit ne tiltsanak el az övéi közül attól, hogy szolgáljon néki, vagy hozzá menjen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 24, 'Egynéhány nap mulva pedig Félix megjelenvén feleségével Drusillával egybe, ki zsidó asszony vala, maga elé hívatá Pált, és hallgatá őt a Krisztusban való hit felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 25, 'Mikor pedig ő igazságról, önmegtartóztatásról és az eljövendő ítéletről szólt, megrémülve monda Félix: Mostan eredj el; de mikor alkalmatosságom lesz, magamhoz hivatlak téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 26, 'Egyszersmind pedig azt is reményli vala, hogy Pál pénzt ad néki, hogy őt szabadon bocsássa: ezért gyakrabban is magához hivatván őt, beszélget vala véle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 27, 'Mikor pedig két esztendő elmúlt, Félix utóda Porcius Festus lőn; és a zsidóknak kedveskedni akarván Félix, Pált fogságban hagyá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 28, '');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 1, 'Festus tehát, miután bement a tartományba, három nap mulva felméne Jeruzsálembe Czézáreából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 2, 'Panaszt tőnek pedig néki a főpap és a zsidók főemberei Pál ellen, és kérék őt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 3, 'Kérvén magok számára jóindulatát ő ellene, hogy hozassa át őt Jeruzsálembe, lest vetvén, hogy megölhessék őt az úton.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 4, 'Festus azonban azt felelé, hogy Pált Czézáreában őrzik, ő maga pedig csakhamar ki fog menni:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 5, 'A kik azért köztetek, úgymond, főemberek, velem alájővén, ha valami gonoszság van abban a férfiúban, emeljenek vádat ellene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 6, 'Miután pedig tíz napnál tovább időzött közöttük, lemenvén Czézáreába, másnap ítélőszékibe üle, és Pált előhozatá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 7, 'Mikor pedig az megjelent, körülállák a zsidók, kik alámentek vala Jeruzsálemből, sok és súlyos vádat hozván fel Pál ellen, melyeket nem bírtak bebizonyítani;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 8, 'Mivelhogy ő a maga mentségére ezt feleli vala: Sem a zsidók törvénye ellen, sem a templom ellen, sem a császár ellen semmit sem vétettem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 9, 'Festus pedig a zsidóknak kedveskedni akarván, felelvén Pálnak, monda: Akarsz-é Jeruzsálembe felmenni és ott ítéltetni meg ezekről én előttem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 10, 'Pál azonban monda: A császár ítélőszéke előtt állok, itt kell nékem megítéltetnem. A zsidóknak semmit sem vétettem, miként te is jól tudod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 11, 'Mert ha vétkes vagyok és valami halálra méltót cselekedtem, nem vonakodom a haláltól; ha azonban semmi sincs azokban, a mikkel ezek vádolnak engem, senki sem ajándékozhat oda engem azoknak. A császárra appellálok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 12, 'Akkor Festus tanácsával értekezvén, felele: A császárra appelláltál, a császár elé fogsz menni!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 13, 'Néhány nap elmúltával pedig Agrippa király és Bernicé érkezék Czézáreába, hogy köszöntsék Festust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 14, 'Mikor pedig több napig időztek ott, Festus elébe adá a királynak a Pál dolgát, mondván: Van itt egy férfiú, kit Félix hagyott fogva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 15, 'Ki felől, mikor Jeruzsálembe mentem, jelentést tőnek a főpapok és a zsidóknak vénei, kérve ő ellene ítéletet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 16, 'Kiknek azt felelém, hogy nem szokásuk a rómaiaknak, hogy valamely embert halálra adjanak, mielőtt a vádlott szembe nem állíttatik vádlóival, és alkalmat nem nyer a vád felől való mentségére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 17, 'Mikor azért ők ide gyűltek, minden haladék nélkül másnap az ítélőszékbe ülvén, előhozatám azt a férfiút,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 18, 'Ki ellen, mikor vádlói előálltak, semmi bűnt nem hoztak fel azok közül, a miket én sejtettem:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 19, 'Hanem valami vitás kérdéseik valának ő vele az ő tulajdon babonaságuk felől, és bizonyos megholt Jézus felől, kiről Pál azt állítja vala, hogy él.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 20, 'Én pedig bizonytalanságban lévén az e felől való vitára nézve, kérdém, vajjon akar-é Jeruzsálembe menni, és ott ítéltetni meg ezek felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 21, 'Pál azonban appellálván, hogy ő Augustus döntésére tartassék fenn, parancsolám, hogy tartassék fogva, míg őt a császárhoz nem küldhetem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 22, 'Agrippa pedig monda Festusnak: Szeretném magam is azt az embert hallani. Ő pedig monda: Holnap meg fogod őt hallani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 23, 'Másnap tehát eljővén Agrippa és Bernicé nagy pompával, és bemenvén a kihallgatási terembe az ezredesekkel és a város főfőpolgáraival együtt, Festus parancsolatjára előhozák Pált.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 24, 'És monda Festus: Agrippa király, és ti férfiak mindnyájan, kik velünk egybe itt vagytok! Látjátok őt, ki felől a zsidóknak egész sokasága megkeresett engem, mind Jeruzsálemben, mind itt, azt kiáltva, hogy nem kell néki tovább élnie.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 25, 'Én pedig, ámbár megértém, hogy semmi halálra méltó dolgot sem cselekedett, de mivel éppen ő maga appellált Augustusra, elvégeztem, hogy elküldöm őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 26, 'Ki felől nem tudok valami bizonyost írni az én uramnak. Ezért hoztam őt előtökbe, és kiváltképen te elődbe, Agrippa király, hogy a kihallgatás megtörténtével tudjak mit írni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 27, 'Mert esztelen dolognak látszik nékem, hogy a ki foglyot küld, az ellene való vádakat is meg ne jelentse.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 1, 'Agrippa pedig monda Pálnak: Megengedtetik néked, hogy szólj a magad mentségére. Akkor Pál kinyújtván kezét, védőbeszédet tartott:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 2, 'Agrippa király! Boldognak tartom magamat, hogy mindazok felől, a mikkel a zsidóktól vádoltatom, te előtted fogok védekezni e mai napon;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 3, 'Mivel te nagyon jól ismered a zsidók minden szokását és vitás kérdését. Azért kérlek, hallgass meg engem türelmesen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 4, 'Az én ifjúságomtól fogva való életemet tehát, mely kezdetétől az én népem közt Jeruzsálemben folyt le, tudják a zsidók mindnyájan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 5, 'Kik tudják rólam eleitől fogva (ha bizonyságot akarnak tenni), hogy én a mi vallásunknak legszigorúbb felekezete szerint éltem, mint farizeus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 6, 'Most is az Istentől a mi atyáinknak tett ígéret reménységéért állok itt ítélet alatt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 7, 'Melyre a mi tizenkét nemzetségünk, éjjel és nappal buzgón szolgálva reményli, hogy eljut; mely reménységért vádoltatom, Agrippa király, a zsidóktól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 8, 'Micsoda? Hihetetlen dolognak tetszik néktek, hogy Isten halottakat támaszt fel?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 9, 'Én bizonyára elvégeztem vala magamban, hogy ama názáreti Jézus neve ellen sok ellenséges dolgot kell cselekednem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 10, 'Mit meg is cselekedtem Jeruzsálemben: és a szentek közül én sokat börtönbe vettettem, a főpapoktól való felhatalmazást megnyervén. Sőt mikor megölettetének, szavazatommal hozzájárultam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 11, 'És minden zsinagógában gyakorta büntetvén őket, káromlásra kényszerítettem; és felettébb dühösködvén ellenök, kergettem mind az idegen városokig is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 12, 'E dologban épen útban lévén Damaskus felé a főpapoktól vett felhatalmazással és engedelemmel,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 13, 'Délben látám az úton király, hogy mennyből a napnak fényességét meghaladó világosság sugárzott körül engem és azokat, kik velem együtt haladnak vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 14, 'Mikor pedig mi mindnyájan leestünk a földre, hallék szózatot, mely én hozzám szól és ezt mondja vala zsidó nyelven: Saul, Saul, mit kergetsz engem? Nehéz néked az ösztön ellen rúgódoznod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 15, 'Én pedig mondék: Kicsoda vagy, Uram? És az monda: Én vagyok Jézus, a kit te kergetsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 16, 'De kelj fel, és állj lábaidra: mert azért jelentem meg néked, hogy téged szolgává és bizonysággá rendeljelek úgy azokban, a miket láttál, mint azokban, a mikre nézve meg fogok néked jelenni;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 17, 'Megszabadítván téged e néptől és a pogányoktól, kik közé most küldelek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 18, 'Hogy megnyissad szemeiket, hogy setétségből világosságra és a Sátánnak hatalmából az Istenhez térjenek, hogy bűneiknek bocsánatát és a megszenteltettek között osztályrészt nyerjenek az én bennem való hit által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 19, 'Azért, Agrippa király, nem levék engedetlen a mennyei látás iránt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 20, 'Hanem először a Damaskusbelieknek és Jeruzsálembelieknek, majd Júdeának egész tartományában és a pogányoknak hirdettem, hogy bánják meg bűneiket és térjenek meg az Istenhez, a megtéréshez méltó cselekedeteket cselekedvén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 21, 'Ezekért akartak engem megölni a zsidók, megfogván a templomban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 22, 'De Istentől segítséget vévén, mind e mai napig állok, bizonyságot tévén mind kicsinynek, mind nagynak, semmit sem mondván azokon kívül, a mikről mind a próféták megmondották, mind Mózes, hogy be fognak teljesedni:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 23, 'Hogy a Krisztusnak szenvedni kell, hogy mint a halottak feltámadásából első, világosságot fog hirdetni e népnek és a pogányoknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 24, 'Mikor pedig ő ezeket mondá a maga mentségére, Festus nagy fenszóval monda: Bolond vagy te, Pál! A sok tudomány téged őrültségbe visz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 25, 'Ő pedig monda: Nem vagyok bolond, nemes Festus, hanem igaz és józan beszédeket szólok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 26, 'Mert tud ezekről a király, kihez bátorságosan is szólok: mert épen nem gondolom, hogy ezek közül ő előtte bármi is ismeretlen volna; mert nem valami zugolyában lett dolog ez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 27, 'Hiszel-e, Agrippa király, a prófétáknak? Tudom, hogy hiszel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 28, 'Agrippa pedig monda Pálnak: Majdnem ráveszel engem, hogy keresztyénné legyek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 29, 'Pál pedig monda: Kívánnám Istentől, hogy necsak majdnem, hanem nagyon is, ne csak te, hanem mindazok is, kik ma engem hallgatnak, lennétek olyanok, a minő én is vagyok, e bilincsektől megválva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 30, 'És mikor ő ezeket mondá, felkele a király és a tiszttartó és Bernicé és a kik velük együtt ültek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 31, 'És visszavonultokban beszélgetnek vala egymással, mondván: Semmi halálra, vagy fogságra méltó dolgot nem cselekszik ez az ember.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 32, 'Agrippa pedig monda Festusnak: Ezt az embert szabadon lehetett volna bocsátani, ha a császárra nem appellált volna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 1, 'Midőn pedig elvégeztetett, hogy mi Itáliába hajózzunk, átadák mind Pált, mind némely egyéb foglyokat egy Július nevű századosnak a császári seregből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 2, 'Beülvén azért egy Adramittiumból való hajóba, az Ázsia mentében fekvő helyeket akarván behajózni, elindulánk, velünk lévén a maczedóniai Aristárkhus, ki Thessalonikából való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 3, 'És másnap megérkezénk Sidonba. És Július emberséggel bánván Pállal, megengedé, hogy barátaihoz elmenve gondoskodásukban részesüljön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 4, 'És onnan elindulván, Ciprus alatt evezénk el, mivelhogy a szelek ellenkezők valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 5, 'És a Cziliczia és Pámfilia mellett levő tengeren átevezvén, eljutánk a licziai Mirába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 6, 'És mivel ott a százados egy Itáliába menő alexandriai hajót talált, abba szállított be minket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 7, 'Több napon át azonban lassan hajózván és nehezen érkezvén Knidushoz, mivel nem enged vala bennünket odajutni a szél, elhajózánk Kréta alatt, Salmóné mellett,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 8, 'És nagy ügygyel-bajjal elhajózván mellette, jutánk egy helyre, melyet Szépkikötőknek neveznek, melyhez közel vala Lásea városa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 9, 'Mivel pedig sok idő mult el, és a hajózás más veszedelmes vala, mivelhogy a bőjt is elmult immár, inti vala Pál őket,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 10, 'Ezt mondván nékik: Férfiak, látom, hogy nemcsak a teréhnek és a hajónak, hanem a mi életünknek is bántódásával és nagy kárával fog történni e hajózás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 11, 'De a százados inkább hisz vala a kormányosmesternek és a hajótulajdonosnak, hogynem annak, a mit Pál mond vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 12, 'Mivel pedig az a kikötő telelésre nem volt alkalmas, a többség azt határozá, hogy hajózzanak el onnan is, ha valami módon eljutva Fénixbe, Kréta kikötőjébe, mely délnyugot és északnyugot felé néz, kitelelhetnének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 13, 'Mivel pedig déli szél kezdett lassan fúni, azt gondolván, hogy feltett szándékuknak uraivá lettek, elindulván, közelebb hajóztak el Kréta mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 14, 'Nemsokára azonban viharos szélvész csapott le oda, mely Észak-keleti szélnek neveztetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 15, 'Mikor pedig a hajó elragadtatott, és nem bírt a széllel szembe menni, nekieresztvén azt, vitetünk vala tova.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 16, 'Mikor pedig egy kis sziget alá futottunk, mely Klaudának hívattatik, csak alig bírtuk hatalmunkba keríteni a csolnakot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 17, 'Melyet miután felvontak, védőeszközöket alkalmaznak vala, alól megövedzvén a hajót; és mivel félnek vala, hogy zátonyra bukkannak, lebocsátván a vitorlát, úgy vitetnek vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 18, 'Mikor pedig a szélvésztől nagyon hányattatánk, másnap a hajóterhet kihányák;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 19, 'És harmadnap tulajdon kezeinkkel hányók ki a hajó felszerelését.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 20, 'Mikor pedig több napon át sem nap, sem csillagok nem látszottak, és nem kis vihar szorongatott, továbbra minden reménységünk elvétetett életben maradásunk felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 21, 'Mikor pedig hosszas volt már az étlenség, akkor Pál felállván ő közöttük, monda: Jóllehet szükséges lett volna, óh férfiak, hogy engedelmeskedve nékem, ne indultunk volna el Krétából, és elkerültük volna ezt a bajt és kárt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 22, 'Mindazáltal mostanra nézve is intelek benneteket, hogy jó reménységben legyetek; mert egy lélek sem vész el közületek, hanem csak a hajó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 23, 'Mert ez éjjel mellém álla egy angyala az Istennek, a kié vagyok, a kinek szolgálok is,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 24, 'Ezt mondván: Ne félj Pál! A császár elé kell néked állanod. És ímé az Isten ajándékba adta néked mindazokat, kik te veled hajóznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 25, 'Annakokáért jó reménységben legyetek, férfiak! Mert hiszek az Istennek, hogy úgy lesz, a mint nékem megmondatott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 26, 'Egy szigetre kell pedig nékünk kivetődnünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 27, 'Mikor pedig a tizennegyedik éjszaka eljött, a mint ide s tova hányatánk az Ádrián, éjféltájban észrevevék a hajósok hogy valami szárazföld közelget hozzájok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 28, 'És lebocsátván a vízmérő ónt, húsz ölnyinek találák, majd egy kevéssé tovább menvén és ismét lebocsátván a vízmérő ónt, találák tizenöt ölnyinek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 29, 'És mivel féltek, hogy szirtes helyekre vetődhetnek, a hajónak hátulsó részéből négy vasmacskát vetvén ki, kívánják vala, hogy nappal legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 30, 'A hajósok pedig mikor el akarának menekülni a hajóból, és a csolnakot lebocsáták a tengerre, annak színe alatt, mintha a hajó orrából vasmacskákat akarnának vetni,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 31, 'Monda Pál a századosnak és a vitézeknek: Ha ezek a hajóban nem maradnak, ti meg nem szabadulhattok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 32, 'Akkor a vitézek elvágák a csolnak köteleit, és ki hagyák esni azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 33, 'Addig pedig, míg nappal lenne, inti vala Pál mindnyájokat, hogy egyenek, mondván: Ma tizennegyedik napja, mióta folyton étlen várakoztok, semmit sem véve magatokhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 34, 'Azért intelek benneteket, hogy egyetek, mert ez a ti javatokra szolgál. Mert közületek senkinek sem esik le egy hajszál a fejéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 35, 'Mikor pedig ezeket mondá, és kenyeret vőn kezébe, hálákat ada Istennek mindnyájok előtt, és megtörvén, kezde enni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 36, 'Felbátorodván pedig mindnyájan, szintén vevének magukhoz táplálékot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 37, 'Valánk pedig a hajóban lélekszám szerint összesen kétszázhetvenhatan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 38, 'Miután pedig megelégedtek eledellel, a hajót könnyebbítik vala, a gabonát kihányván a tengerbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 39, 'Mikor pedig megvirradt, a szárazföldet nem ismerik vala fel; hanem egy tengeröblöt sajdítanak vala, melynek síma partja van, melyre végezék, hogy kihajtják a hajót, ha bírják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 40, 'A vasmacskákat azért körös-körül elvagdalván, a tengerben hagyák, egyszersmind eloldván a kormányrudak köteleit és felvonván a nagy vitorlát a szélfúvásnak, igyekeznek vala a part felé haladni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 41, 'De mikor egy zátonyos helyre találtak, ráhajtották a hajót. És az első része ugyan megakadván, mozdíthatatlanul marad vala, a hátulsó része azonban szakadoz vala a haboknak ereje miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 42, 'A vitézeknek pedig az lőn tanácsa, hogy a foglyokat vágják le, hogy senki el ne szaladhasson, minekutána kiúszott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 43, 'De a százados meg akarván tartani Pált, eltiltá őket e szándéktól, és megparancsolá, hogy a kik úszni tudnak, először azok szökdössenek a tengerbe és meneküljenek ki a szárazföldre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 44, 'A többiek pedig ki deszkákon, ki a hajó egyéb darabjain. És így lőn, hogy mindnyájan szerencsésen kimenekültek a szárazföldre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 1, 'És miután szerencsésen megmenekültek, akkor megtudák, hogy Melitának neveztetik az a sziget.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 2, 'A barbárok pedig nem közönséges emberséget cselekesznek vala mi velünk: mert tüzet gerjesztvén, befogadának mindnyájónkat a rajtunk való záporért és a hidegért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 3, 'Mikor pedig Pál nagy sok venyigét szedett és a tűzre tette, egy vipera a melegből kimászva, az ő kezére ragada.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 4, 'Mikor pedig látták a barbárok az ő kezéről függeni a mérges kígyót, mondják vala egymásnak: Nyilván gyilkos ez az ember, kit nem hagya élni a bosszúállás, noha a tengerből megszabadult.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 5, 'De néki, minekutána a kígyót lerázta a tűzbe, semmi baja sem lőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 6, 'Azok pedig azt várják vala, hogy ő meg fog dagadni, vagy nagyhirtelenséggel halva rogyik le. Mikor azonban sok ideig várták, és látták, hogy semmi baja nem lesz, megváltoztatva értelmöket, istennek mondják vala őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 7, 'Annak a helynek környékén valának pedig a sziget főemberének, névszerint Publiusnak mezei jószágai, ki befogadván minket, három napig nagy emberségesen vendégül látott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 8, 'Lőn pedig, hogy a Publius atyja hideglelésben és vérhasban betegen feküvék. Kihez Pál beméne, és minekutána könyörgött, kezeit reá vetve meggyógyítá őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 9, 'Minekutána azért ez megtörtént, egyebek is, kik betegek valának a szigeten, ő hozzá jövének és meggyógyulának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 10, 'Kik nékünk nagy tisztességet is tőnek, és mikor elindulánk, a szükséges dolgokkal ellátának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 11, 'Három hónap mulva tudniillik egy Alexandriába való hajón elindulánk, mely a szigeten telelt, melynek czímere Kásztor és Pollux vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 12, 'És Szirakúzába eljutván, ott maradánk három napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 13, 'Onnét körülkerülvén, eljutánk Régiumba, és egy nap mulva déli szél támadván, másnap megérkezénk Puteóliba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 14, 'Hol mikor atyafiakat találtunk, kérének minket, hogy nálok maradjunk hét napig; és úgy menénk Rómába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 15, 'Onnét is az atyafiak, mikor a mi dolgainkat meghallották, nékünk előnkbe jövének Appii Forumig és Tres Tabernaeig. És mikor Pál meglátta őket, hálákat adván az Istennek, bátorságot vőn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 16, 'Mikor pedig Rómába jutottunk, a százados átadá a foglyokat a testőrsereg fővezérének. Pálnak azonban megengedteték, hogy külön lakjék az őt őriző vitézzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 17, 'Lőn pedig, hogy három nap mulva magához hívatá Pál a zsidók között való főembereket. Mikor pedig egybegyűltek, monda nékik: Atyámfiai, férfiak, én jóllehet semmit sem vétkeztem a nép ellen, vagy az ősi szokások ellen, mindazáltal foglyul adattam át Jeruzsálemből a rómaiak kezébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 18, 'Kik miután kihallgattak, el akarának engem bocsátani, mivelhogy én bennem semmi halálra méltó vétek nincsen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 19, 'De mivel a zsidók ellene mondtak, kényszeríttettem a császárra appellálni, nem mintha az én népem ellen volna valami vádam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 20, 'Ennekokáért hívattalak tehát titeket, hogy lássalak benneteket és szóljak veletek; mert az Izráelnek reménységéért vétettem körül e lánczczal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 21, 'Azok pedig mondának néki: Mi te felőled sem levelet nem vettünk Júdeából, sem pedig az atyafiak közül ide jőve valaki, nem jelentett, vagy szólott te felőled valami rosszat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 22, 'Akarnók azért tőled hallani, micsoda értelemben vagy. Mert e felekezet felől tudva van előttünk, hogy mindenütt ellene mondanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 23, 'Kitűzvén tehát néki egy napot, eljövének hozzá a szállására többen; kiknek nagy bizonyságtétellel szól vala az Istennek országa felől, igyekezvén elhitetni ő velök a Jézus felől való dolgokat, úgy a Mózes törvényéből, mint a prófétákból, reggeltől fogva mind estvéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 24, 'És némelyek hivének az ő beszédének, mások nem hivének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 25, 'Mivel pedig nem egyezének meg egymással, eloszlának, miután Pál ez egy szót mondá: Jól szólott a Szent Lélek Ésaiás próféta által a mi atyáinknak, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 26, 'Eredj el a néphez és mondd: Hallván halljátok, és ne értsetek; és nézvén nézzetek, és ne lássatok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 27, 'Mert megkövéredett e népnek szíve, és füleikkel nehezen hallanak, és szemeiket behunyják; hogy szemeikkel ne lássanak, füleikkel ne halljanak, szívükkel ne értsenek és meg ne térjenek, és meg ne gyógyítsam őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 28, 'Legyen azért néktek tudtotokra, hogy a pogány népeknek küldetett az Istennek ez idvezítése, és ők meg is hallgatják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 29, 'És mikor ezeket mondotta, elmenének a zsidók, magok között sokat vetekedve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 30, 'Marada pedig Pál két egész esztendeig az ő tulajdon bérelt szállásán, és mindazokat befogadja vala, kik ő hozzá menének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 31, 'Prédikálván az Istennek országát és tanítván az Úr Jézus Krisztus felől való dolgokat teljes bátorsággal, minden tiltás nélkül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Pál, Jézus Krisztusnak szolgája, elhívott apostol, elválasztva Isten evangyéliomának hirdetésére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, 'Melyet eleve megígért az ő prófétái által a szentírásokban,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'Az ő Fia felől, a ki Dávid magvából lett test szerint,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'A ki megbizonyíttatott hatalmasan Isten Fiának a szentség Lelke szerint, a halálból való feltámadás által, a mi Urunk Jézus Krisztus felől,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, 'A ki által vettük a kegyelmet és az apostolságot a hitben való engedelmességnek okáért, minden pogányok között, az ő nevéért;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'Kik között vagytok ti is, Jézus Krisztusnak hivatalosai:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'Mindeneknek, a kik Rómában vagytok, Isten szerelmeseinek, hivatalos szenteknek: Kegyelem néktek és békesség Istentől, a mi Atyánktól és az Úr Jézus Krisztustól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'Először hálát adok az én Istenemnek a Jézus Krisztus által mindnyájatokért, hogy a ti hiteteknek az egész világon híre van;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'Mert bizonyságom nékem az Isten, kinek lelkem szerint szolgálok az ő Fiának evangyéliomában, hogy szüntelen emlékezem felőletek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'Imádkozásaimban mindenkor könyörögvén, vajha egyszer már jó szerencsés út adódnék nékem Istennek akaratából, hogy hozzátok mehessek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'Mert kívánlak titeket látni, hogy valami lelki ajándékot közölhessek veletek a ti megerősítésetekre,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'Azaz, hogy együtt felbuzduljunk ti nálatok egymás hite által, a tiétek meg az enyém által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'Nem akarom pedig, hogy ne tudjátok atyámfiai, hogy én gyakran elvégeztem magamban, hogy elmegyek hozzátok (de mindez ideig megakadályoztattam), hogy köztetek is nyerjek valami lelki gyümölcsöt, mint a többi pogányok közt is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'Mind a görögöknek, mind a barbároknak, mind a bölcseknek, mind a tudatlanoknak köteles vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'Azért a mi rajtam áll, kész vagyok néktek is, a kik Rómában vagytok, az evangyéliomot hirdetni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'Mert nem szégyenlem a Krisztus evangyéliomát; mert Istennek hatalma az minden hívőnek idvességére, zsidónak először meg görögnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'Mert az Istennek igazsága jelentetik ki abban hitből hitbe, miképen meg van írva: Az igaz ember pedig hitből él.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, 'Mert nyilván van az Istennek haragja mennyből, az embereknek minden hitetlensége és hamissága ellen, kik az igazságot hamissággal feltartóztatják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'Mert a mi az Isten felől tudható nyilván van ő bennök; mert az Isten megjelentette nékik:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'Mert a mi Istenben láthatatlan, tudniillik az ő örökké való hatalma és istensége, a világ teremtésétől fogva az ő alkotásaiból megértetvén megláttatik; úgy, hogy ők menthetetlenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, 'Mert bár az Istent megismerték, mindazáltal nem mint Istent dicsőítették őt, sem néki hálákat nem adtak; hanem az ő okoskodásaikban hiábavalókká lettek, és az ő balgatag szívök megsötétedett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, 'Magokat bölcseknek vallván, balgatagokká lettek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 23, 'És az örökkévaló Istennek dicsőségét felcserélték a mulandó embereknek és madaraknak és négylábú állatoknak és csúszó-mászó állatoknak képmásával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 24, 'Annakokáért adta is őket az Isten szívök kivánságaiban tisztátalanságra, hogy egymás testét megszeplősítsék;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 25, 'Mint a kik az Isten igazságát hazugsággá változtatták, és a teremtett dolgokat tisztelték és szolgálták a teremtő helyett, a ki mind örökké áldott. Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 26, 'Annakokáért adta őket az Isten tisztátalan indulatokra; mert az ő asszonynépeik is elváltoztatták a természet folyását természetellenesre:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 27, 'Hasonlóképen a férfiak is elhagyván az asszonynéppel való természetes élést, egymásra gerjedtek bujaságukban, férfiak férfiakkal fertelmeskedvén, és az ő tévelygésöknek méltó jutalmát elvevén önmagokban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 28, 'És a miképen nem méltatták az Istent arra, hogy ismeretökben megtartsák, azonképen oda adták őket az Isten méltatlan gondolkozásra, hogy illetlen dolgokat cselekedjenek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 29, 'A kik teljesek minden hamissággal, paráznasággal, gonoszsággal, kapzsisággal, rosszasággal; rakvák, írigységgel, gyilkossággal, versengéssel, álnoksággal, rossz erkölcscsel;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 30, 'Súsárlók, rágalmazók, istengyűlölők, dölyfösek, kevélyek, dicsekedők, rosszban mesterkedők, szüleiknek engedetlenek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 31, 'Balgatagok, összeférhetetlenek, szeretet nélkül valók, engesztelhetetlenek, irgalmatlanok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 32, 'Kik jóllehet az Isten végzését ismerik, hogy a kik ilyeneket cselekesznek, méltók a halálra, mégis nemcsak cselekszik azokat, hanem az akképen cselekvőkkel egyet is értenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'Annakokáért menthetetlen vagy óh ember, bárki légy, a ki ítélsz: mert a miben mást megítélsz, önmagadat kárhoztatod; mivel ugyanazokat míveled te, a ki ítélsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'Tudjuk pedig, hogy az Istennek ítélete igazság szerint van azokon, a kik ilyeneket cselekesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'Vagy azt gondolod, óh ember, a ki megítéled azokat, a kik ilyeneket cselekesznek, és te is azokat cselekszed, hogy te elkerülöd az Istennek ítéletét?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'Avagy megveted az ő jóságának, elnézésének és hosszútűrésének gazdagságát, nem tudván, hogy az Istennek jósága téged megtérésre indít?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'De te a te keménységed és meg nem tért szíved szerint gyűjtesz magadnak haragot a haragnak és az Isten igaz ítélete kijelentésének napjára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'A ki megfizet mindenkinek az ő cselekedetei szerint:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'Azoknak, a kik a jó cselekedetben való állhatatossággal dicsőséget, tisztességet és halhatatlanságot keresnek, örök élettel;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'Azoknak pedig, a kik versengők és a kik nem engednek az igazságnak, hanem engednek a hamisságnak, búsulással és haraggal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'Nyomorúság és ínség minden gonoszt cselekedő ember lelkének, zsidónak először meg görögnek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'Dicsőség pedig, tisztesség és békesség minden jót cselekedőnek, zsidónak először meg görögnek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'Mert nincsen Isten előtt személyválogatás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'Mert a kik törvény nélkül vétkeztek, törvény nélkül vesznek is el: és a kik a törvény alatt vétkeztek, törvény által ítéltetnek meg,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, '(Mert nem azok igazak Isten előtt, a kik a törvényt hallgatják, hanem azok fognak megigazulni, a kik a törvényt betöltik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, 'Mert mikor a pogányok, a kiknek törvényök nincsen, természettől a törvény dolgait cselekszik, akkor ők, törvényök nem lévén, önmagoknak törvényök:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'Mint a kik megmutatják, hogy a törvény cselekedete be van írva az ő szívökbe, egyetemben bizonyságot tévén arról az ő lelkiismeretök és gondolataik, a melyek egymást kölcsönösen vádolják vagy mentegetik.)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, 'Azon a napon, melyen az Isten megítéli az emberek titkait az én evangyéliomom szerint a Jézus Krisztus által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'Ímé, te zsidónak neveztetel, és a törvényre támaszkodol, és Istennel dicsekedel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'És ismered az ő akaratát, és választást tudsz tenni azok között, a melyek különböznek attól, mivelhogy a törvényből megtaníttattál;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'És azt hiszed magadról, hogy te a vakoknak vezetője, a sötétségben levőknek világossága,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, 'A balgatagok tanítója, a kiskorúak mestere vagy, bírván a törvényben az ismeret és igazság formáját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, 'A ki azért mást tanítasz, magadat nem tanítod-é? a ki azt hirdeted, hogy ne lopj, lopsz-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, 'A ki azt mondod, ne paráználkodjál, paráználkodol-é? a ki útálod a bálványokat, szentségtörő vagy-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, 'Ki a törvényben dicsekszel, a törvénynek megrontása által az Istent gyalázod-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, 'Mert az Istennek neve miattatok káromoltatik a pogányok között, a mint meg van írva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'Mert használ ugyan a körülmetélkedés, ha a törvényt megtartod; de ha a törvényt áthágod, a te körülmetélkedésed körülmetéletlenséggé lett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, 'Ha tehát a körülmetéletlen pogány megtartja a törvénynek parancsolatait, az ő körülmetéletlensége nem körülmetélkedésül tulajdoníttatik-é néki?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, 'És a természettől fogva körülmetéletlen ember, ha a törvényt megtartja, megítél téged, a ki a betű és körülmetélkedés mellett is a törvényeknek megrontója vagy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'Mert nem az a zsidó, a ki külsőképen az; sem nem az a körülmetélés, a mi a testen külsőképen van:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, 'Hanem az a zsidó, a ki belsőképen az; és a szívnek lélekben, nem betű szerint való körülmetélése az igazi körülmetélkedés; a melynek dícsérete nem emberektől, hanem Istentől van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Mi tekintetben különb hát a zsidó? vagy micsoda haszna van a körülmetélkedésnek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, 'Minden tekintetben sok. Mindenek előtt, hogy az Isten reájok bízta az ő beszédeit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'De hát hogy ha némelyek nem hittek? Vajjon azoknak hitetlensége nem teszi-é hiábavalóvá az Istennek hűségét?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, 'Távol legyen. Sőt inkább az Isten legyen igaz, minden ember pedig hazug, a mint meg van írva: Hogy igaznak ítéltessél a te beszédeidben, és győzedelmes légy, mikor vádolnak téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'Ha pedig a mi igazságtalanságunk az Istennek igazságát mutatja meg, mit mondjunk? Vajjon igazságtalan-é az Isten, hogy minket büntet? Emberi módon szólok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, 'Távol legyen! Mert akkor mi módon ítéli meg az Isten a világot?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'Mert ha az Istennek igazsága az én hazugságom által öregbült az ő dicsőségére, miért kárhoztattatom még én is, mint bűnös?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'Sőt inkább ne cselekedjük-é a rosszat, hogy abból jó származzék? – a mint minket rágalmaznak, és a mint némelyek mondogatják, hogy mi így beszélünk, a kiknek kárhoztatása igazságos.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'Micsoda tehát? Különbek vagyunk-é? Semmiképen nem. Mert az elébb megmutattuk nyilván, hogy zsidók és görögök mindnyájan bűn alatt vannak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, 'A mint meg van írva, hogy nincsen csak egy igaz is;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, 'Nincs, a ki megértse, nincs, a ki keresse az Istent.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'Mindnyájan elhajlottak, egyetemben haszontalanokká lettek; nincs, a ki jót cselekedjék, nincsen csak egy is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, 'Nyitott sír az ő torkuk; nyelvökkel álnokságot szólnak; áspis kígyó mérge van ajkaik alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, 'Szájok telve átkozódással és keserűséggel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, 'Lábaik gyorsak a vérontásra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, 'Útjaikon romlás és nyomorúság van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, 'És a békességnek útját nem ismerik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, 'Nincs isteni félelem az ő szemök előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, 'Tudjuk pedig, hogy a mit a törvény mond, azoknak mondja, a kik a törvény alatt vannak; hogy minden száj bedugassék, és az egész világ Isten ítélete alá essék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, 'Annakokáért a törvénynek cselekedeteiből egy test sem igazul meg ő előtte: mert a bűn ismerete a törvény által vagyon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, 'Most pedig törvény nélkül jelent meg az Istennek igazsága, a melyről tanúbizonyságot tesznek a törvény és a próféták;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, 'Istennek igazsága pedig a Jézus Krisztusban való hit által mindazokhoz és mindazoknak, a kik hisznek. Mert nincs különbség,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, 'Mert mindnyájan vétkeztek, és szűkölködnek az Isten dicsősége nélkül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, 'Megigazulván ingyen az ő kegyelméből a Krisztus Jézusban való váltság által,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, 'Kit az Isten eleve rendelt engesztelő áldozatul, hit által, az ő vérében, hogy megmutassa az ő igazságát az előbb elkövetett bűnöknek elnézése miatt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, 'Az Isten hosszútűrésénél fogva, az ő igazságának megbizonyítására, a mostani időben, hogy igaz legyen Ő és megigazítsa azt, a ki a Jézus hitéből való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, 'Hol van tehát a dicsekedés? Kirekesztetett. Mely törvény által? A cselekedeteké által? Nem; hanem a hit törvénye által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, 'Azt tartjuk tehát, hogy az ember hit által igazul meg, a törvény cselekedetei nélkül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, 'Avagy Isten csak a zsidóké-e? Avagy nem a pogányoké is? Bizony a pogányoké is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, 'Mivelhogy egy az Isten, a ki megigazítja a zsidót hitből és a pogányt hit által. A törvényt tehát hiábavalóvá tesszük-é a hit által? Távol legyen! Sőt inkább a törvényt megerősítjük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Mit mondunk tehát, hogy Ábrahám a mi atyánk nyert volna test szerint?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'Mert ha Ábrahám cselekedetekből igazult meg, van mivel dicsekedjék, de nem az Isten előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'Mert mit mond az írás: Hitt pedig Ábrahám az Istennek, és tulajdoníttaték az ő néki igazságul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'Annak pedig, a ki munkálkodik, a jutalom nem tulajdoníttatik kegyelemből, hanem tartozás szerint;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'Ellenben annak, a ki nem munkálkodik, hanem hisz abban, a ki az istentelent megigazítja, az ő hite tulajdoníttatik igazságul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'A mint Dávid is boldognak mondja azt az embert, a kinek az Isten igazságot tulajdonít cselekedetek nélkül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, 'Boldogok, a kiknek megbocsáttattak az ő hamisságaik, és a kiknek elfedeztettek az ő bűneik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'Boldog ember az, a kinek az Úr bűnt nem tulajdonít.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'Ez a boldogság tehát a zsidónak, vagy a pogánynak is tulajdoníttatik-é? Mert azt mondjuk, hogy Ábrahámnak a hit tulajdoníttaték igazságul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, 'Miképen tulajdoníttaték tehát? Körülmetélt vagy körülmetéletlen állapotában? Nem körülmetélt, hanem körülmetéletlen állapotában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'És a körülmetélkedés jegyét körülmetéletlenségében tanusított hite igazságának pecsétjéül nyerte: hogy atyja legyen mindazoknak, a kik körülmetéletlen létökre hisznek, hogy azoknak is tulajdoníttassék az igazság;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'És hogy atyja legyen a körülmetélteknek is, azoknak, a kik nemcsak körülmetélkednek, hanem követik is a mi atyánknak Ábrahámnak körülmetéletlenségében tanusított hitének nyomdokait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'Mert nem a törvény által adatott az ígéret Ábrahámnak, vagy az ő magvának, hogy e világnak örököse lesz, hanem a hitnek igazsága által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'Mert ha azok az örökösök, kik a törvényből valók, hiábavalóvá lett a hit, és haszontalanná az ígéret:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'Mert a törvény haragot nemz: a hol pedig nincsen törvény, ott törvény ellen való cselekedet sincsen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'Azért hitből, hogy kegyelemből legyen; hogy erős legyen az ígéret az egész magnak; nemcsak a törvényből valónak, hanem az Ábrahám hitéből valónak is, a ki mindnyájunknak atyánk');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, '(A mint meg van írva, hogy sok nép atyjává tettelek téged) az előtt, az Isten előtt, a kiben hitt, a ki a holtakat megeleveníti, és azokat, a melyek nincsenek, előszólítja mint meglevőket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, 'A ki reménység ellenére reménykedve hitte, hogy sok népnek atyjává lesz, a szerint, a mint megmondatott: Így lészen a te magod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'És hitében erős lévén, nem gondolt az ő már elhalt testére, mintegy százesztendős lévén, sem Sárának elhalt méhére;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, 'Az Istennek ígéretében sem kételkedett hitetlenséggel, hanem erős volt a hitben, dicsőséget adván az Istennek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'És teljesen elhitte, hogy a mit ő ígért, meg is cselekedheti.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, 'Azért is tulajdoníttaték néki igazságul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, 'De nemcsak ő érette iratott meg, hogy tulajdoníttaték néki igazságul,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, 'Hanem mi érettünk is, a kiknek majd tulajdoníttatik, azoknak tudniillik, a kik hisznek Abban, a ki feltámasztotta a mi Urunkat a Jézust a halálból,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, 'Ki a mi bűneinkért halálra adatott, és feltámasztatott a mi megigazulásunkért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'Megigazulván azért hit által, békességünk van Istennel, a mi Urunk Jézus Krisztus által,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'A ki által van a menetelünk is hitben ahhoz a kegyelemhez, a melyben állunk; és dicsekedünk az Isten dicsőségének reménységében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'Nemcsak pedig, hanem dicsekedünk a háborúságokban is, tudván, hogy a háborúság békességes tűrést nemz,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, 'A békességes tűrés pedig próbatételt, a próbatétel pedig reménységet,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'A reménység pedig nem szégyenít meg; mert az Istennek szerelme kitöltetett a mi szívünkbe a Szent Lélek által, ki adatott nékünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 'Mert Krisztus, mikor még erőtelenek valánk, a maga idejében meghalt a gonoszokért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'Bizonyára igazért is alig hal meg valaki; ám a jóért talán csak meg merne halni valaki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'Az Isten pedig a mi hozzánk való szerelmét abban mutatta meg, hogy mikor még bűnösök voltunk, Krisztus érettünk meghalt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'Minekutána azért most megigazultunk az ő vére által, sokkal inkább megtartatunk a harag ellen ő általa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, 'Mert ha, mikor ellenségei voltunk, megbékéltünk Istennel az ő Fiának halála által, sokkal inkább megtartatunk az ő élete által minekutána megbékéltünk vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, 'Nemcsak pedig, hanem dicsekedünk is az Istenben a mi Urunk Jézus Krisztus által, a ki által most a megbékélést nyertük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 12, 'Annakokáért, miképen egy ember által jött be a világra a bűn és a bűn által a halál, és akképen a halál minden emberre elhatott, mivelhogy mindenek vétkeztek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 13, 'Mert a törvényig vala bűn a világon; a bűn azonban nem számíttatik be, ha nincsen törvény.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 14, 'Úgyde a halál uralkodott Ádámtól Mózesig azokon is, a kik nem az Ádám esetének hasonlatossága szerint vétkeztek, a ki ama következendőnek kiábrázolása vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 15, 'De a kegyelmi ajándék nem úgy van, mint a bűneset; mert ha amaz egynek esete miatt sokan haltak meg, az Isten kegyelme és a kegyelemből való ajándék, mely az egy ember Jézus Krisztusé, sokkal inkább elhatott sokakra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 16, 'És az ajándék sem úgy van, mint egy vétkező által; mert az ítélet egyből lett kárhozottá, az ajándék pedig sok bűnből van igazulásra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 17, 'Mert ha az egynek bűnesete miatt uralkodott a halál az egy által: sokkal inkább az életben uralkodnak az egy Jézus Krisztus által azok, kik a kegyelemnek és az igazság ajándékának bővölködésében részesültek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 18, 'Bizonyára azért, miképen egynek bűnesete által minden emberre elhatott a kárhozat: azonképen egynek igazsága által minden emberre elhatott az életnek megigazulása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 19, 'Mert miképen egy embernek engedetlensége által sokan bűnösökké lettek: azonképen egynek engedelmessége által sokan igazakká lesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 20, 'A törvény pedig bejött, hogy a bűn megnövekedjék; de a hol megnövekedik a bűn, ott a kegyelem sokkal inkább bővölködik:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 21, 'Hogy miképen uralkodott a bűn a halálra, azonképen a kegyelem is uralkodjék igazság által az örök életre a mi Urunk Jézus Krisztus által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'Mit mondunk tehát? Megmaradjunk-é a bűnben, hogy a kegyelem annál nagyobb legyen?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, 'Távol legyen: a kik meghaltunk a bűnnek, mimódon élnénk még abban?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'Avagy nem tudjátok-é, hogy a kik megkeresztelkedtünk Krisztus Jézusba, az ő halálába keresztelkedtünk meg?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'Eltemettettünk azért ő vele együtt a keresztség által a halálba: hogy miképen feltámasztatott Krisztus a halálból az Atyának dicsősége által, azonképen mi is új életben járjunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'Mert ha az ő halálának hasonlatossága szerint vele egygyé lettünk, bizonyára feltámadásáé szerint is azok leszünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, 'Tudván azt, hogy a mi ó emberünk ő vele megfeszíttetett, hogy megerőtelenüljön a bűnnek teste, hogy ezután ne szolgáljunk a bűnnek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'Mert a ki meghalt, felszabadult a bűn alól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'Hogyha pedig meghaltunk Krisztussal, hiszszük, hogy élünk is ő vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'Tudván, hogy Krisztus, a ki feltámadott a halálból, többé meg nem hal; a halál többé rajta nem uralkodik,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, 'Mert hogy meghalt, a bűnnek halt meg egyszer; hogy pedig él, az Istennek él.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, 'Ezenképen gondoljátok ti is, hogy meghaltatok a bűnnek, de éltek az Istennek a mi Urunk Jézus Krisztusban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'Ne uralkodjék tehát a bűn a ti halandó testetekben, hogy engedjetek néki az ő kívánságaiban:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'Se ne szánjátok oda a ti tagjaitokat hamisságnak fegyvereiül a bűnnek; hanem szánjátok oda magatokat az Istennek, mint a kik a halálból életre keltetek, és a ti tagjaitokat igazságnak fegyvereiül az Istennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'Mert a bűn ti rajtatok nem uralkodik; mert nem vagytok törvény alatt, hanem kegyelem alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'Mit is tehát? Vétkezzünk-é mivelhogy nem vagyunk törvény alatt, hanem kegyelem alatt? Távol legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, 'Avagy nem tudjátok, hogy a kinek oda szánjátok magatokat szolgákul az engedelmességre, annak vagytok szolgái, a kinek engedelmeskedtek: vagy a bűnnek halálra, vagy az engedelmességnek igazságra?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, 'De hála az Istennek, hogy jóllehet a bűn szolgái voltatok, de szívetek szerint engedelmeskedtek a tudomány azon alakjának, a melyre adattatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, 'Felszabadulván pedig a bűn alól, az igazságnak szolgáivá lettetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, 'Emberi módon szólok a ti testeteknek erőtlensége miatt. Mert a miképen oda szántátok a ti tagjaitokat a tisztátalanságnak és a hamisságnak szolgáiul a hamisságra: azonképen szánjátok oda most a ti tagjaitokat szolgáiul az igazságnak a megszenteltetésre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, 'Mert mikor a bűn szolgái valátok, az igazságtól szabadok valátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, 'Micsoda gyümölcsét vettétek azért akkor azoknak, a miket most szégyenletek? mert azoknak a vége halál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, 'Most pedig, minekutána felszabadultatok a bűn alól, szolgáivá lettetek pedig az Istennek: megvan a gyümölcsötök a megszenteltetésre, a vége pedig örök élet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'Mert a bűn zsoldja halál; az Isten kegyelmi ajándéka pedig örök élet a mi Urunk Krisztus Jézusban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, 'Avagy nem tudjátok-é atyámfiai, mert törvényismerőkhöz szólok, hogy a törvény uralkodik az emberen, a míg él?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, 'Mert a férjes asszony, míg él a férj, ehhez van kötve törvény szerint, de ha meghal a férj, felszabadul az asszony a férj törvénye alól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, 'Azért tehát az ő férjének életében paráznának mondatik, ha más férfihoz megy; ha azonban meghal a férje, szabaddá lesz a törvénytől, úgy hogy nem lesz parázna, ha más férfihoz megy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, 'Azért atyámfiai, ti is meghaltatok a törvénynek a Krisztus teste által, hogy legyetek máséi, azéi, a ki a halálból feltámasztatott, hogy gyümölcsöt teremjünk Istennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, 'Mert mikor a testben voltunk, a bűnök indulatai a törvény által dolgoztak a mi tagjainkban, hogy gyümölcsözzenek a halálnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, 'Most pedig megszabadultunk a törvénytől, minekutána meghaltunk arra nézve, a mely által lekötve tartattunk; hogy szolgáljunk a léleknek újságában és nem a betű óságában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, 'Mit mondunk tehát? A törvény bűn-é? Távol legyen: sőt inkább a bűnt nem ismertem, hanem csak a törvény által; mert a kívánságról sem tudtam volna, ha a törvény nem mondaná: Ne kívánjad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, 'De a bűn alkalmat vévén, a parancsolat által nemzett bennem minden kívánságot; mert törvény nélkül holt a bűn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, 'Én pedig éltem régen a törvény nélkül: de ama parancsolatnak eljövetelével felelevenedék a bűn,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, 'Én pedig meghalék; és úgy találtaték, hogy az a parancsolat, mely életre való, nékem halálomra van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, 'Mert a bűn alkalmat vévén, ama parancsolat által megcsalt engem, és megölt általa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, 'Azért ám a törvény szent, és a parancsolat szent és igaz és jó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, 'Tehát a jó nékem halálom lett-é? Távol legyen: sőt inkább a bűn az, hogy megtessék a bűn, mely a jó által nékem halált szerez, hogy felette igen bűnös legyen a bűn a parancsolat által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, 'Mert tudjuk, hogy a törvény lelki; de én testi vagyok, a bűn alá rekesztve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 15, 'Mert a mit cselekeszem, nem ismerem: mert nem azt mívelem, a mit akarok, hanem a mit gyűlölök, azt cselekeszem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 16, 'Ha pedig azt cselekszem, a mit nem akarok, megegyezem a törvénnyel, hogy jó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 17, 'Most azért már nem én cselekszem azt, hanem a bennem lakozó bűn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 18, 'Mert tudom, hogy nem lakik én bennem, azaz a testemben jó; mert az akarás megvan bennem, de a jó véghezvitelét nem találom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 19, 'Mert nem a jót cselekeszem, melyet akarok; hanem a gonoszt cselekeszem, melyet nem akarok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 20, 'Ha pedig én azt cselekeszem, a mit nem akarok, nem én mívelem már azt, hanem a bennem lakozó bűn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 21, 'Megtalálom azért magamban, ki a jót akarom cselekedni, ezt a törvényt, hogy a bűn megvan bennem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 22, 'Mert gyönyörködöm az Isten törvényében a belső ember szerint;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 23, 'De látok egy másik törvényt az én tagjaimban, mely ellenkezik az elmém törvényével, és engem rabul ád a bűn törvényének, mely van az én tagjaimban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 24, 'Óh én nyomorult ember! Kicsoda szabadít meg engem e halálnak testéből?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 25, 'Hálát adok Istennek a mi Urunk Jézus Krisztus által. Azért jóllehet én az elmémmel az Isten törvényének, de testemmel a bűn törvényének szolgálok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, 'Nincsen azért immár semmi kárhoztatásuk azoknak, a kik Krisztus Jézusban vannak, kik nem test szerint járnak, hanem Lélek szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, 'Mert a Jézus Krisztusban való élet lelkének törvénye megszabadított engem a bűn és a halál törvényétől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, 'Mert a mi a törvénynek lehetetlen vala, mivelhogy erőtelen vala a test miatt, az Isten az ő Fiát elbocsátván bűn testének hasonlatosságában és a bűnért, kárhoztatá a bűnt a testben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, 'Hogy a törvénynek igazsága beteljesüljön bennünk, kik nem test szerint járunk, hanem Lélek szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, 'Mert a test szerint valók a test dolgaira gondolnak; a Lélek szerint valók pedig a Lélek dolgaira.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, 'Mert a testnek gondolata halál; a Lélek gondolata pedig élet és békesség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, 'Mert a test gondolata ellenségeskedés Isten ellen; minthogy az Isten törvényének nem engedelmeskedik, mert nem is teheti.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, 'A kik pedig testben vannak, nem lehetnek kedvesek Isten előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, 'De ti nem vagytok testben, hanem lélekben, ha ugyan az Isten Lelke lakik bennetek. A kiben pedig nincs a Krisztus Lelke, az nem az övé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, 'Hogyha pedig Krisztus ti bennetek van, jóllehet a test holt a bűn miatt, a lélek ellenben élet az igazságért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, 'De ha Annak a Lelke lakik bennetek, a ki feltámasztotta Jézust a halálból, ugyanaz, a ki feltámasztotta Krisztus Jézust a halálból, megeleveníti a ti halandó testeiteket is az ő ti bennetek lakozó Lelke által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, 'Annakokáért atyámfiai, nem vagyunk adósok a testnek, hogy test szerint éljünk:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, 'Mert, ha test szerint éltek, meghaltok; de ha a test cselekedeteit a lélekkel megöldökölitek, éltek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, 'Mert a kiket Isten Lelke vezérel, azok Istennek fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, 'Mert nem kaptatok szolgaság lelkét ismét a félelemre, hanem a fiúságnak Lelkét kaptátok, a ki által kiáltjuk: Abbá, Atyám!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, 'Ez a Lélek bizonyságot tesz a mi lelkünkkel együtt, hogy Isten gyermekei vagyunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, 'Ha pedig gyermekek, örökösök is; örökösei Istennek, örököstársai pedig Krisztusnak; ha ugyan vele együtt szenvedünk, hogy vele együtt is dicsőüljünk meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, 'Mert azt tartom, hogy a miket most szenvedünk, nem hasonlíthatók ahhoz a dicsőséghez, mely nékünk megjelentetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, 'Mert a teremtett világ sóvárogva várja az Isten fiainak megjelenését.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, 'Mert a teremtett világ hiábavalóság alá vettetett, nem önként, hanem azért, a ki az alá vetette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, 'Azzal a reménységgel, hogy maga a teremtett világ is megszabadul a rothadandóság rabságától az Isten fiai dicsőségének szabadságára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, 'Mert tudjuk, hogy az egész teremtett világ egyetemben fohászkodik és nyög mind idáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, 'Nemcsak ez pedig, hanem magok a Lélek zsengéjének birtokosai, mi magunk is fohászkodunk magunkban, várván a fiúságot, a mi testünknek megváltását.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 24, 'Mert reménységben tartattunk meg; a reménység pedig, ha láttatik, nem reménység; mert a mit lát valaki, miért reményli is azt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 25, 'Ha pedig, a mit nem látunk, azt reméljük, békességes tűréssel várjuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 26, 'Hasonlatosképen pedig a Lélek is segítségére van a mi erőtelenségünknek. Mert azt, a mit kérnünk kell, a mint kellene, nem tudjuk; de maga a Lélek esedezik mi érettünk kimondhatatlan fohászkodásokkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 27, 'A ki pedig a szíveket vizsgálja, tudja, mi a Lélek gondolata, mert Isten szerint esedezik a szentekért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 28, 'Tudjuk pedig, hogy azoknak, a kik Istent szeretik, minden javokra van, mint a kik az ő végzése szerint hivatalosak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 29, 'Mert a kiket eleve ismert, eleve el is rendelte, hogy azok az ő Fia ábrázatához hasonlatosak legyenek, hogy ő legyen elsőszülött sok atyafi között.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 30, 'A kiket pedig eleve elrendelt, azokat el is hívta; és a kiket elhívott, azokat meg is igazította; a kiket pedig megigazított, azokat meg is dicsőítette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 31, 'Mit mondunk azért ezekre? Ha az Isten velünk, kicsoda ellenünk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 32, 'A ki az ő tulajdon Fiának nem kedvezett, hanem őt mindnyájunkért odaadta, mimódon ne ajándékozna vele együtt mindent minékünk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 33, 'Kicsoda vádolja az Isten választottait? Isten az, a ki megigazít;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 34, 'Kicsoda az, a ki kárhoztat? Krisztus az, a ki meghalt, sőt a ki fel is támadott, a ki az Isten jobbján van, a ki esedezik is érettünk:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 35, 'Kicsoda szakaszt el minket a Krisztus szerelmétől? nyomorúság vagy szorongattatás, vagy üldözés, vagy éhség, vagy meztelenség, vagy veszedelem, vagy fegyver-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 36, 'A mint megvan írva, hogy: Te éretted gyilkoltatunk minden napon; olybá tekintenek mint vágó juhokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 37, 'De mindezekben felettébb diadalmaskodunk, Az által, a ki minket szeretett,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 38, 'Mert meg vagyok győződve, hogy sem halál, sem élet, sem angyalok, sem fejedelemségek, sem hatalmasságok, sem jelenvalók, sem következendők, Sem magasság, sem mélység, sem semmi más teremtmény nem szakaszthat el minket az Istennek szerelmétől, mely vagyon a mi Urunk Jézus Krisztusban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, 'Igazságot szólok Krisztusban, nem hazudok, lelkiismeretem velem együtt tesz bizonyságot a Szent Lélek által,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, 'Hogy nagy az én szomorúságom és szüntelen való az én szívemnek fájdalma;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, 'Mert kívánnám, hogy én magam átok legyek, elszakasztva a Krisztustól az én atyámfiaiért, a kik rokonaim test szerint;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, 'A kik izráeliták, a kiké a fiúság és a dicsőség és a szövetségek, meg a törvényadás és az isteni tisztelet és az ígéretek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, 'A kiké az atyák, és a kik közül való test szerint a Krisztus, a ki mindeneknek felette örökké áldandó Isten. Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, 'Nem lehet pedig, hogy meghiúsult legyen az Isten beszéde. Mert nem mindnyájan izráeliták azok, kik Izráeltől valók;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, 'Sem nem mindnyájan fiak, kik az Ábrahám magvából valók; hanem: Izsákban neveztetik néked a te magod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, 'Azaz, nem a testnek fiai az Isten fiai; hanem az ígéret fiait tekinti magul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, 'Mert ígéretnek beszéde ez: Ez idő tájban eljövök, és Sárának fia lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, 'Nemcsak pedig, hanem Rebeka is, ki egytől fogant méhében, Izsáktól a mi atyánktól:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, 'Mert mikor még meg sem születtek, sem semmi jót vagy gonoszt nem cselekedtek, hogy az Istennek kiválasztás szerint való végzése megmaradjon, nem cselekedetekből, hanem az elhívótól,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, 'Megmondatott néki, hogy: A nagyobbik szolgál a kisebbiknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, 'Miképen meg van írva: Jákóbot szerettem, Ézsaut pedig gyűlöltem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, 'Mit mondunk tehát: Vajjon nem igazságtalanság-é ez az Istentől? Távol legyen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, 'Mert Mózesnek ezt mondja: Könyörülök azon, a kin könyörülök, és kegyelmezek annak, a kinek kegyelmezek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, 'Annakokáért tehát nem azé, a ki akarja, sem nem azé, a ki fut, hanem a könyörülő Istené.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, 'Mert azt mondja az írás a Faraónak, hogy: Azért támasztottalak téged, hogy megmutassam benned az én hatalmamat, és hogy hirdessék az én nevemet az egész földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, 'Annakokáért a kin akar könyörül, a kit pedig akar, megkeményít.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, 'Mondod azért nékem: Miért fedd hát engem? Hiszen az ő akaratának kicsoda áll ellene?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, 'Sőt inkább kicsoda vagy te óh ember, hogy versengsz az Istennel? Avagy mondja-é a készítmény a készítőnek: Miért csináltál engem így?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, 'Avagy nincsen-é a fazekasnak hatalma az agyagon, hogy ugyanazon gyuradékból némely edényt tisztességre, némelyt pedig becstelenségre csináljon?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, 'Ha pedig az Isten az ő haragját megmutatni és hatalmát megismertetni kívánván, nagy békességes tűréssel elszenvedte a harag edényeit, melyek veszedelemre készíttettek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, 'És hogy megismertesse az ő dicsőségének gazdagságát az irgalom edényein, melyeket eleve elkészített a dicsőségre, mit szólhatsz ellene?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, 'A kikül el is hívott minket nemcsak a zsidók, hanem a pogányok közül is,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, 'A mint Hóseásnál is mondja: Hívom a nem én népemet én népemnek; és a nem szerettet szeretettnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, 'És lészen, hogy azon a helyen, a hol ez mondatott nékik: Ti nem vagytok az én népem, ott az élő Isten fiainak fognak hívatni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, 'Ésaiás pedig ezt kiáltja Izráel felől: Ha Izráel fiainak száma annyi volna is, mint a tenger fövenye, a maradék tartatik meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, 'Mert a dolgot bevégezi és rövidre metszi igazságban; mivel rövidesen végez az Úr a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, 'És a mint Ésaiás előre megmondotta: Ha a Seregeknek Ura nem hagyott volna nékünk magot, olyanokká lettünk volna, mint Sodoma, és Gomorához volnánk hasonlók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, 'Mit mondunk hát? Azt, hogy a pogányok, a kik az igazságot nem követték, az igazságot elnyerték, még pedig a hitből való igazságot;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, 'Izráel ellenben, mely az igazság törvényét követte, nem jutott el az igazság törvényére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, 'Miért? Azért, mert nem hitből keresték, hanem mintha a törvény cselekedeteiből volna. Mert beleütköztek a beleütközés kövébe,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, 'A mint meg van írva: Ímé beleütközés kövét és megbotránkozás szikláját teszem Sionba; és a ki hisz benne, nem szégyenül meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, 'Atyámfiai, szívem szerint kívánom és Istentől könyörgöm az Izráel idvességét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, 'Mert bizonyságot teszek felőlök, hogy Isten iránt való buzgóság van bennök, de nem megismerés szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, 'Mert az Isten igazságát nem ismervén, és az ő tulajdon igazságukat igyekezvén érvényesíteni, az Isten igazságának nem engedelmeskedtek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, 'Mert a törvény vége Krisztus minden hívőnek igazságára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, 'Mert Mózes a törvényből való igazságról azt írja, hogy a ki azokat cselekeszi, él azok által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, 'A hitből való igazság pedig így szól: Ne mondd a te szívedben: Kicsoda megy föl a mennybe? (azaz, hogy Krisztus aláhozza;)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, 'Avagy: Kicsoda száll le a mélységbe? (azaz, hogy Krisztust a halálból felhozza.)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, 'De mit mond? Közel hozzád a beszéd, a szádban és a szívedben van: azaz a hit beszéde, a melyet mi hirdetünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, 'Mert ha a te száddal vallást teszel az Úr Jézusról, és szívedben hiszed, hogy az Isten feltámasztotta őt a halálból, megtartatol.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, 'Mert szívvel hiszünk az igazságra, szájjal teszünk pedig vallást az idvességre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, 'Mert azt mondja az írás: Valaki hisz ő benne, meg nem szégyenül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, 'Mert nincs különbség zsidó meg görög között; mert ugyanaz az Ura mindeneknek, a ki kegyelemben gazdag mindenekhez, a kik őt segítségül hívják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, 'Mert minden, a ki segítségül hívja az Úr nevét, megtartatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, 'Mimódon hívják azért segítségül azt, a kiben nem hisznek? Mimódon hisznek pedig abban, a ki felől nem hallottak? Mimódon hallanának pedig prédikáló nélkül?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, 'Mimódon prédikálnak pedig, ha el nem küldetnek? A miképen meg van írva: Mely szépek a békesség hirdetőknek lábai, a kik jókat hirdetnek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, 'De nem mindenek engedelmeskedtek az evangyéliomnak. Mert Ésaiás azt mondja: Uram! Kicsoda hitt a mi beszédünknek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, 'Azért a hit hallásból van, a hallás pedig Isten ígéje által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, 'De mondom: Avagy nem hallották-é? Sőt inkább az egész földre elhatott az ő hangjok, és a lakóföld véghatáráig az ő beszédök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, 'De mondom: Avagy nem ismerte-é Izráel? Először Mózes mondja: Én titeket felingerellek egy nem néppel, értelmetlen néppel haragítalak meg titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, 'Ésaiás pedig bátorságosan ezt mondja: Megtaláltak azok, a kik engem nem keresnek; nyilvánvaló lettem azoknak, a kik felőlem nem kérdezősködtek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, 'Az Izráelről pedig ezt mondja: Egész napon kiterjesztettem kezeimet az engedetlenkedő és ellenmondó néphez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, 'Mondom tehát: Avagy elvetette-é Isten az ő népét? Távol legyen; mert én is izráelita vagyok, az Ábrahám magvából, Benjámin nemzetségéből való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, 'Nem vetette el Isten az ő népét, melyet eleve ismert. Avagy nem tudjátok-é, mit mond az írás Illésről? a mint könyörög Istenhez Izráel ellen, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, 'Uram, a te prófétáidat megölték, és a te oltáraidat lerombolták; és csak én egyedül maradtam, és engem is halálra keresnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, 'De mit mond néki az isteni felelet? Meghagytam magamnak hétezer embert, a kik nem hajtottak térdet a Baálnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, 'Ekképen azért most is van maradék a kegyelemből való választás szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, 'Hogyha pedig kegyelemből, akkor nem cselekedetekből: különben a kegyelem nem volna többé kegyelem. Hogyha pedig cselekedetekből, akkor nem kegyelemből: különben a cselekedet nem volna többé cselekedet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, 'Micsoda tehát? A mit Izráel keres, azt nem nyerte meg: a választottak ellenben megnyerték, a többiek pedig megkeményíttettek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, 'A mint meg van írva: Az Isten kábultság lelkét adta nékik; szemeket, hogy ne lássanak, füleket, hogy ne halljanak, mind e mai napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, 'Dávid is ezt mondja: Legyen az ő asztaluk tőrré, hálóvá, botránkozássá és megtorlássá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, 'Sötétüljenek meg az ő szemeik, hogy ne lássanak, és az ő hátokat mindenkorra görbítsd meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, 'Annakokáért mondom: Avagy azért botlottak-é meg, hogy elessenek? Távol legyen; hanem az ő esetük folytán lett az idvesség a pogányoké, hogy ők felingereltessenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, 'Ha pedig az ő esetök világnak gazdagsága, és az ő veszteségök pogányok gazdagsága, mennyivel inkább az ő teljességök?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, 'Mert néktek mondom a pogányoknak, a mennyiben hát én pogányok apostola vagyok, a szolgálatomat dicsőítem,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, 'Ha ugyan felingerelhetném az én atyámfiait, és megtarthatnék közülök némelyeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, 'Mert ha az ő elvettetésök a világnak megbékélése, micsoda lesz a felvételök hanemha élet a halálból?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, 'Ha pedig a zsenge szent, akkor a tészta is; és ha a gyökér szent, az ágak is azok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, 'Ha pedig némely ágak kitörettek, te pedig vadolajfa létedre beoltattál azok közé, és részese lettél az olajfa gyökerének és zsírjának;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 18, 'Ne kevélykedjél az ágak ellenében: ha pedig kevélykedel, nem te hordozod a gyökeret, hanem a gyökér téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 19, 'Azt mondod azért: Kitörettek az ágak, hogy én oltassam be.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 20, 'Úgy van; hitetlenség miatt törettek ki, te pedig hit által állasz; fel ne fuvalkodjál, hanem félj;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 21, 'Mert ha az Isten a természet szerint való ágaknak nem kedvezett, majd néked sem kedvez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 22, 'Tekintsd meg azért az Istennek kegyességét és keménységét: azok iránt a kik elestek, keménységét; irántad pedig a kegyességét, ha megmaradsz a kegyességben; különben te is kivágatol.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, 'Sőt azok is, ha meg nem maradnak a hitetlenségben, beoltatnak; mert az Isten ismét beolthatja őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, 'Mert ha te a természet szerint való vadolajfából kivágattál, és természet ellenére beoltattál a szelid olajfába: mennyivel inkább beoltatnak ezek a természet szerint valók az ő saját olajfájokba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, 'Mert nem akarom, hogy ne tudjátok atyámfiai ezt a titkot, hogy magatokat el ne higyjétek, hogy a megkeményedés Izráelre nézve csak részben történt, a meddig a pogányok teljessége bemegyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, 'És így az egész Izráel megtartatik, a mint meg van írva: Eljő Sionból a Szabadító, és elfordítja Jákóbtól a gonoszságokat:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, 'És ez nékik az én szövetségem, midőn eltörlöm az ő bűneiket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, 'Az evangyéliomra nézve ugyan ellenségek ti érettetek; de a választásra nézve szerelmetesek az atyákért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, 'Mert megbánhatatlanok az Istennek ajándékai és az ő elhívása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, 'Mert miképen ti egykor engedetlenkedtetek az Istennek, most pedig irgalmasságot nyertetek az ő engedetlenségök miatt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, 'Azonképen ők is most engedetlenkedtek, hogy a ti irgalmasságba jutásotok folytán ők is irgalmasságot nyerjenek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, 'Mert az Isten mindeneket engedetlenség alá rekesztett, hogy mindeneken könyörüljön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 33, 'Óh Isten gazdagságának, bölcseségének és tudományának mélysége! Mely igen kikutathatatlanok az ő ítéletei s kinyomozhatatlanok az ő útai!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 34, 'Mert kicsoda ismerte meg az Úr értelmét? vagy kicsoda volt néki tanácsosa?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 35, 'Avagy kicsoda adott előbb néki, hogy annak visszafizesse azt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 36, 'Mert ő tőle, ő általa és ő reá nézve vannak mindenek. Övé a dicsőség mindörökké. Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, 'Kérlek azért titeket atyámfiai az Istennek irgalmasságára, hogy szánjátok oda a ti testeiteket élő, szent és Istennek kedves áldozatul, mint a ti okos tiszteleteteket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, 'És ne szabjátok magatokat e világhoz, hanem változzatok el a ti elméteknek megújulása által, hogy megvizsgáljátok, mi az Istennek jó, kedves és tökéletes akarata.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, 'Mert a nékem adott kegyelem által mondom mindenkinek közöttetek, hogy feljebb ne bölcselkedjék, mint a hogy kell bölcselkedni; hanem józanon bölcselkedjék, a mint az Isten adta kinek-kinek a hit mértékét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, 'Mert miképen egy testben sok tagunk van, minden tagnak pedig nem ugyanazon cselekedete van:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, 'Azonképen sokan egy test vagyunk a Krisztusban, egyenként pedig egymásnak tagjai vagyunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, 'Minthogy azért külön-külön ajándékaink vannak a nékünk adott kegyelem szerint, akár írásmagyarázás, a hitnek szabálya szerint teljesítsük;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, 'Akár szolgálat, a szolgálatban; akár tanító, a tanításban;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, 'Akár intő, az intésben; az adakozó szelídségben; az előljáró szorgalmatossággal; a könyörülő vídámsággal mívelje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, 'A szeretet képmutatás nélkül való legyen. Iszonyodjatok a gonosztól, ragaszkodjatok a jóhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, 'Atyafiúi szeretettel egymás iránt gyöngédek; a tiszteletadásban egymást megelőzők legyetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, 'Az igyekezetben ne legyetek restek; lélekben buzgók legyetek; az Úrnak szolgáljatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, 'A reménységben örvendezők; a háborúságban tűrők; a könyörgésben állhatatosak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, 'A szentek szükségeire adakozók legyetek; a vendégszeretetet gyakoroljátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, 'Áldjátok azokat, a kik titeket kergetnek; áldjátok és ne átkozzátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 15, 'Örüljetek az örülőkkel, és sírjatok a sírókkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 16, 'Egymás iránt ugyanazon indulattal legyetek; ne kevélykedjetek, hanem az alázatosakhoz szabjátok magatokat. Ne legyetek bölcsek timagatokban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 17, 'Senkinek gonoszért gonoszszal ne fizessetek. A tisztességre gondotok legyen minden ember előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 18, 'Ha lehetséges, a mennyire rajtatok áll, minden emberrel békességesen éljetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 19, 'Magatokért bosszút ne álljatok szerelmeseim, hanem adjatok helyet ama haragnak; mert meg van írva: Enyém a bosszúállás, én megfizetek, ezt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 20, 'Azért, ha éhezik a te ellenséged, adj ennie; ha szomjuhozik, adj innia; mert ha ezt míveled, eleven szenet gyűjtesz az ő fejére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, 'Ne győzettessél meg a gonosztól, hanem a gonoszt jóval győzd meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, 'Minden lélek engedelmeskedjék a felső hatalmasságoknak; mert nincsen hatalmasság, hanem csak Istentől: és a mely hatalmasságok vannak, az Istentől rendeltettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, 'Azért, a ki ellene támad a hatalmasságnak, az Isten rendelésének támad ellene; a kik pedig ellene támadnak, önmagoknak ítéletet szereznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, 'Mert a fejedelmek nem a jó, hanem a rossz cselekedetnek rettegésére vannak. Akarod-é pedig, hogy ne félj a hatalmasságtól? Cselekedjed a jót, és dícséreted lesz attól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, 'Mert Isten szolgája ő a te javadra. Ha pedig a gonoszt cselekszed, félj: mert nem ok nélkül viseli a fegyvert: mert Isten szolgája, bosszúálló a haragra annak, a ki gonoszt cselekszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, 'Annakokáért szükség engedelmeskedni, nem csak a haragért, hanem a lelkiismeretért is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, 'Mert azért fizettek adót is; mivelhogy Istennek szolgái, kik ugyanabban foglalatoskodnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, 'Adjátok meg azért mindenkinek, a mivel tartoztok: a kinek az adóval, az adót; a kinek a vámmal, a vámot; a kinek a félelemmel, a félelmet; a kinek a tisztességgel, a tisztességet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, 'Senkinek semmivel ne tartozzatok, hanem csak azzal, hogy egymást szeressétek; mert a ki szereti a felebarátját, a törvényt betöltötte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, 'Mert ez: Ne paráználkodjál, ne ölj, ne orozz, hamis tanubizonyságot ne szólj, ne kívánj, és ha valamely más parancsolat van, ebben az ígében foglaltatik egybe: Szeressed felebarátodat mint temagadat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 10, 'A szeretet nem illeti gonoszszal a felebarátot. Annakokáért a törvénynek betöltése a szeretet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 11, 'Ezt pedig cselekedjétek, tudván az időt, hogy ideje már, hogy az álomból felserkenjünk; mert most közelebb van hozzánk az idvesség, mint a mikor hívőkké lettünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 12, 'Az éjszaka elmúlt, a nap pedig elközelgett; vessük el azért a sötétségnek cselekedeteit, és öltözzük fel a világosság fegyvereit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 13, 'Mint nappal, ékesen járjunk, nem dobzódásokban és részegségekben, nem bujálkodásokban és feslettségekben, nem versengésben és írigységben:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 14, 'Hanem öltözzétek fel az Úr Jézus Krisztust, és a testet ne tápláljátok a kívánságokra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, 'A hitben erőtelent fogadjátok be, nem ítélgetvén vélekedéseit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, 'Némely ember azt hiszi, hogy mindent megehetik; a hitben erőtelen pedig zöldséget eszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, 'A ki eszik, ne vesse meg azt, a ki nem eszik; és a ki nem eszik, ne kárhoztassa azt, a ki eszik. Mert az Isten befogadta őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, 'Te kicsoda vagy, hogy kárhoztatod a más szolgáját? Az ő tulajdon urának áll vagy esik. De meg fog állani, mert az Úr által képes, hogy megálljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, 'Emez az egyik napot különbnek tartja a másiknál: amaz pedig minden napot egyformának tart. Ki-ki a maga értelme felől legyen meggyőződve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, 'A ki ügyel a napra, az Úrért ügyel: és a ki nem ügyel a napra, az Úrért nem ügyel. A ki eszik, az Úrért eszik, mert hálákat ád az Istennek: és a ki nem eszik, az Úrért nem eszik, és hálákat ád az Istennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, 'Mert közülünk senki sem él önmagának, és senki sem hal önmagának:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'Mert ha élünk, az Úrnak élünk; ha meghalunk, az Úrnak halunk meg. Azért akár éljünk, akár haljunk, az Úréi vagyunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, 'Mert azért halt meg és támadott fel és elevenedett meg Krisztus, hogy mind holtakon mind élőkön uralkodjék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, 'Te pedig miért kárhoztatod a te atyádfiát? avagy te is miért veted meg a te atyádfiát? Hiszen mindnyájan oda állunk majd a Krisztus ítélőszéke elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, 'Mert meg van írva: Élek én, mond az Úr, mert nékem hajol meg minden térd, és minden nyelv Istent magasztalja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, 'Azért hát mindenikünk maga ad számot magáról az Istennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, 'Annakokáért egymást többé ne kárhoztassuk: hanem inkább azt tartsátok, hogy a ti atyátokfiának ne szerezzetek megütközést vagy megbotránkozást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, 'Tudom és meg vagyok győződve az Úr Jézusban, hogy semmi sem tisztátalan önmagában: hanem bármi annak tisztátalan, a ki tisztátalannak tartja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, 'De ha a te atyádfia az ételért megszomorodik, akkor te nem szeretet szerint cselekszel. Ne veszítsd el azt a te ételeddel, a kiért Krisztus meghalt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, 'Ne káromoltassék azért a ti javatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, 'Mert az Isten országa nem evés, nem ivás, hanem igazság, békesség és Szent Lélek által való öröm.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, 'Mert a ki ezekben szolgál a Krisztusnak, kedves Istennek, és az emberek előtt megpróbált.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, 'Azért tehát törekedjünk azokra, a mik a békességre és az egymás épülésére valók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, 'Ne rontsd le az ételért az Isten munkáját. Minden tiszta ugyan, de rossz annak az embernek, a ki botránkozással eszi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, 'Jó nem enni húst és nem inni bort, sem semmit nem tenni, a miben a te atyádfia megütközik vagy megbotránkozik, vagy erőtelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 22, 'Te néked hited van: tartsd meg magadban Isten előtt. Boldog, a ki nem kárhoztatja magát abban, a mit helyesel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 23, 'A ki pedig kételkedik, ha eszik, kárhoztatva van, mert nem hitből eszik. A mi pedig hitből nincs, bűn az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 1, 'Tartozunk pedig mi az erősek, hogy az erőtelenek erőtlenségeit hordozzuk, és ne magunknak kedveskedjünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 2, 'Mindenikünk tudniillik az ő felebarátjának kedveskedjék annak javára, épülésére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, 'Mert Krisztus sem önmagának kedveskedett, hanem a mint meg van írva: A te gyalázóidnak gyalázásai hullottak reám.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, 'Mert a melyek régen megirattak, a mi tanulságunkra irattak meg: hogy békességes tűrés által és az írásoknak vígasztalása által reménységünk legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, 'A békességes tűrésnek és vígasztalásnak Istene pedig adja néktek, hogy ugyanazon indulat legyen bennetek egymás iránt Krisztus Jézus szerint:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, 'Hogy egy szívvel, egy szájjal dicsőítsétek az Istent és a mi Urunk Jézus Krisztusnak Atyját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, 'Azért fogadjátok be egymást, miképen Krisztus is befogadott minket az Isten dicsőségére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, 'Mondom pedig, hogy Jézus Krisztus szolgája lett a körülmetélkedésnek az Isten igazságáért, hogy megerősítse az atyák ígéreteit;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, 'A pogányok pedig irgalmasságáért dicsőítik Istent, a mint meg van írva: Annakokáért vallást teszek rólad a pogányok között, és dícséretet éneklek a te nevednek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, 'És ismét azt mondja: Örüljetek pogányok az ő népével együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, 'És ismét: Dícsérjétek az Urat minden pogányok, és magasztaljátok őt minden népek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, 'És viszont Ésaiás így szól: Lészen a Jessének gyökere, és a ki felkel, hogy uralkodjék a pogányokon; ő benne reménykednek a pogányok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, 'A reménységnek Istene pedig töltsön be titeket minden örömmel és békességgel a hivésben, hogy bővölködjetek a reménységben a Szent Lélek ereje által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 14, 'Meg vagyok pedig győződve atyámfiai én magam is ti felőletek, hogy teljesek vagytok minden jósággal, betöltve minden ismerettel, képesek lévén egymást is inteni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 15, 'Bátorságosabban írtam pedig néktek atyámfiai, részben, mintegy emlékeztetvén titeket az Istentől nékem adott kegyelem által,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 16, 'Hogy legyek a Jézus Krisztus szolgája a pogányok között, munkálkodván az Isten evangyéliomában, hogy legyen a pogányoknak áldozata kedves és a Szent Lélek által megszentelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 17, 'Van azért mivel dicsekedjem a Jézus Krisztusban, az Istenre tartozó dolgokban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 18, 'Mert nem merek szólni semmiről, a mit nem Krisztus cselekedett volna általam a pogányoknak engedelmességére, szóval és tettel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 19, 'Jelek és csodák ereje által, az Isten Lelkének ereje által; úgyannyira, hogy én Jeruzsálemtől és környékétől fogva Illyriáig betöltöttem a Krisztus evangyéliomát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 20, 'Ekképen pedig tisztességbeli dolog, hogy ne ott hirdessem az evangyéliomot, ahol neveztetett Krisztus, hogy ne más alapra építsek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, 'Hanem a mint meg van írva: A kiknek nem hirdettetett ő felőle, azok meglátják; és a kik nem hallották, megértik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, 'Annakokáért meg is akadályoztattam gyakran a hozzátok való menetelben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, 'Most pedig, mivelhogy nincs már helyem e tartományokban, vágyódván pedig sok esztendő óta, hogy elmenjek hozzátok:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, 'Ha Hispániába megyek, elmegyek ti hozzátok. Mert remélem, hogy átutazóban meglátlak titeket, és ti elkísértek oda, ha előbb részben beteljesedem veletek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, 'Most pedig megyek Jeruzsálembe, szolgálván a szenteknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, 'Mert tetszett Macedóniának és Akhájának, hogy a Jeruzsálembeli szentek szegényei részére némileg adakozzanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, 'Mert tetszett nékik, és tartoznak is vele. Mert ha a pogányok azoknak a lelki javaiban részesültek, tartoznak nékik viszont szolgálni a testiekben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, 'Ezt azért ha majd elvégezem, és nékik e gyümölcsöt átadom, elmegyek közöttetek által Hispániába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, 'Tudom pedig, hogy mikor hozzátok megyek, a Krisztus evangyélioma áldásának teljességével megyek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, 'Kérlek pedig titeket atyámfiai a mi Urunk Jézus Krisztusra és a Lélek szerelmére, tusakodjatok velem együtt az imádkozásokban, én érettem Isten előtt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, 'Hogy szabaduljak meg azoktól, a kik engedetlenek Júdeában, és hogy az én Jeruzsálemben való szolgálatom legyen kedves a szentek előtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, 'Hogy örömmel menjek hozzátok az Isten akaratából, és veletek együtt megújuljak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, 'A békességnek Istene pedig legyen mindnyájan ti veletek! Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 1, 'Ajánlom pedig néktek Fébét, a mi nénénket, ki a Kenkhréabeli gyülekezetnek szolgálója:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 2, 'Hogy fogadjátok őt az Úrban szentekhez illendően, és legyetek mellette, ha valami dologban rátok szorul. Mert ő is sokaknak pártfogója volt, nékem magamnak is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 3, 'Köszöntsétek Priscillát és Akvilát, kik nékem munkatársaim Krisztus Jézusban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 4, 'A kik az én életemért a saját nyakukat tették le; a kiknek nemcsak én mondok köszönetet, hanem a pogányok minden gyülekezete is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 5, 'És köszöntsétek azt a gyülekezetet, mely az ő házokban van. Köszöntsétek az én szerelmetes Epenétusomat, a ki Akhája zsengéje a Krisztusban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 6, 'Köszöntsétek Máriát, ki sokat munkálkodott körülöttünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 7, 'Köszöntsétek Andronikust és Juniát az én rokonaimat és az én fogolytársaimat, a kik híresek az apostolok között, a kik nálamnál is előbb voltak a Krisztusban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 8, 'Köszöntsétek Ampliást, ki nékem szerelmesem az Úrban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 9, 'Köszöntsétek Orbánt, a mi munkatársunkat a Krisztusban, és Stakhist az én szerelmesemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 10, 'Köszöntsétek Apellest, ki a Krisztusban megpróbáltatott. Köszöntsétek az Aristóbulus háznépéből valókat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 11, 'Köszöntsétek Heródiont az én rokonomat. Köszöntsétek a Nárcissus háznépéből azokat, a kik az Úrban vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 12, 'Köszöntsétek Trifénát és Trifósát, kik munkálódnak az Úrban. Köszöntsétek a szerelmetes Persist, ki sokat munkálódott az Úrban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 13, 'Köszöntsétek Rufust, ki kiválasztott az Úrban, és az ő anyját, a ki az enyém is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 14, 'Köszöntsétek Ásinkritust, Flégont, Hermást, Pátrobást, Merkuriust, és az atyafiakat, kik velök vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 15, 'Köszöntsétek Filológust és Juliát, Néreust és az ő nénjét, és Olimpást és minden szenteket, kik velök vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 16, 'Köszöntsétek egymást szent csókolással. Köszöntenek titeket a Krisztus gyülekezetei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 17, 'Kérlek pedig titeket atyámfiai, vigyázzatok azokra, a kik szakadásokat és botránkozásokat okoznak a tudomány körül, melyet tanultatok; és azoktól hajoljatok el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 18, 'Mert az ilyenek a mi Urunk Jézus Krisztusnak nem szolgálnak, hanem az ő hasuknak; és nyájas beszéddel, meg hizelkedéssel megcsalják az ártatlanoknak szívét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 19, 'Mert a ti engedelmességetek mindenekhez eljutott. Örülök azért rajtatok; de akarom, hogy bölcsek legyetek a jóban, ártatlanok pedig a rosszban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 20, 'A békességnek Istene megrontja a Sátánt a ti lábaitok alatt hamar. A mi Urunk Jézus Krisztus kegyelme veletek. Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, 'Köszöntenek titeket Timótheus, az én munkatársam, és Luczius, Jáson, és Sosipáter az én rokonaim.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, 'Köszöntelek titeket az Úrban én Tertius, ki e levelet írtam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, 'Köszönt titeket Gájus, a ki nékem és az egész gyülekezetnek gazdája. Köszönt titeket Erástus a városnak kincstartója, és Kvártus atyafi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, 'A mi Urunk Jézus Krisztus kegyelme mindnyájan ti veletek. Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 25, 'Annak pedig, a ki titeket megerősíthet az én evangyéliomom és a Jézus Krisztus hirdetése szerint, ama titoknak kijelentése folytán, mely örök időtől fogva el volt hallgatva,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 26, 'Most pedig megjelentetett a prófétai írások által, az örök Isten parancsolata szerint, a hitben való engedelmesség végett minden pogányoknak tudomására adatván,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 27, 'Az egyedül bölcs Istennek a Jézus Krisztus által dicsőség mindörökké. Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Pál, Jézus Krisztusnak Isten akaratából elhívott apostola, és Sosthenes, az atyafi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'Az Isten gyülekezetének, a mely Korinthusban van, a Krisztus Jézusban megszentelteknek, elhívott szenteknek, mindazokkal egybe, a kik a mi Urunk Jézus Krisztus nevét segítségül hívják bármely helyen, a magokén és a miénken:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'Kegyelem néktek és békesség Istentől, a mi Atyánktól, és az Úr Jézus Krisztustól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Hálát adok az én Istenemnek mindenkor ti felőletek az Isten ama kegyelméért, mely néktek a Krisztus Jézusban adatott,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'Mivelhogy mindenben meggazdagodtatok ő benne, minden beszédben és minden ismeretben,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'A mint megerősíttetett ti bennetek a Krisztus felől való bizonyságtétel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'Úgy, hogy semmi kegyelmi ajándék nélkül nem szűkölködtök, várván a mi Urunk Jézus Krisztusnak megjelenését,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'A ki meg is erősít titeket mindvégig feddhetetlenségben, a mi Urunk Jézus Krisztusnak napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'Hű az Isten, ki elhívott titeket az ő Fiával, a mi Urunk Jézus Krisztussal való közösségre,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'Kérlek azonban titeket atyámfiai, a mi Urunk Jézus Krisztus nevére, hogy mindnyájan egyképen szóljatok és ne legyenek köztetek szakadások, de legyetek teljesen egyek ugyanazon értelemben és ugyanazon véleményben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'Mert megtudtam felőletek atyámfiai a Kloé embereitől, hogy versengések vannak köztetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'Azt értem pedig, hogy mindenitek ezt mondja: Én Pálé vagyok, én meg Apollósé, én meg Kéfásé, én meg Krisztusé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Vajjon részekre osztatott-é a Krisztus? Vajjon Pál feszíttetett-é meg érettetek, vagy a Pál nevére kereszteltettetek-é meg?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Hálákat adok az Istennek, hogy senkit sem kereszteltem meg közületek, kivéve Krispust és Gájust,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'Hogy valaki azt ne mondja, hogy a magam nevére kereszteltem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'Megkereszteltem azonban Stefana házanépét is, ezenkívül nem tudom, hogy valakit mást kereszteltem volna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'Mert nem azért küldött engem a Krisztus, hogy kereszteljek, hanem hogy az evangyéliomot hirdessem; de nem szólásban való bölcseséggel, hogy a Krisztus keresztje hiábavaló ne legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'Mert a keresztről való beszéd bolondság ugyan azoknak, a kik elvesznek; de nekünk, kik megtartatunk, Istennek ereje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'Mert meg van írva: Elvesztem a bölcseknek bölcseségét és az értelmeseknek értelmét elvetem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'Hol a bölcs? hol az írástudó? hol e világnak vitázója? Nemde nem bolondsággá tette-é Isten e világnak bölcseségét?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'Mert minekutána az Isten bölcseségében nem ismerte meg a világ a bölcseség által az Istent, tetszék az Istennek, hogy az igehirdetés bolondsága által tartsa meg a hívőket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'Mert egyfelől a zsidók jelt kívánnak, másfelől a görögök bölcseséget keresnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'Mi pedig Krisztust prédikáljuk, mint megfeszítettet, a zsidóknak ugyan botránkozást, a görögöknek pedig bolondságot;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'Ámde magoknak a hivatalosoknak, úgy zsidóknak, mint görögöknek Krisztust, Istennek hatalmát és Istennek bölcseségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'Mert az Isten bolondsága bölcsebb az embereknél, és az Isten erőtelensége erősebb az embereknél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'Mert tekintsétek csak a ti hivatástokat, atyámfiai, hogy nem sokan hívattak bölcsek test szerint, nem sokan hatalmasak, nem sokan nemesek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'Hanem a világ bolondjait választotta ki magának az Isten, hogy megszégyenítse a bölcseket; és a világ erőtleneit választotta ki magának az Isten, hogy megszégyenítse az erőseket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'És a világ nemteleneit és megvetettjeit választotta ki magának az Isten, és a semmiket, hogy a valamiket megsemmisítse:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'Hogy ne dicsekedjék ő előtte egy test sem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'Tőle vagytok pedig ti a Krisztus Jézusban, ki bölcseségül lőn nékünk Istentől, és igazságul, szentségül és váltságul:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'Hogy, a mint meg van írva: A ki dicsekedik, az Úrban dicsekedjék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, 'Én is, mikor hozzátok mentem, atyámfiai, nem mentem, hogy nagy ékesszólással, avagy bölcseséggel hirdessem néktek az Isten bizonyságtételét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'Mert nem végeztem, hogy egyébről tudjak ti köztetek, mint a Jézus Krisztusról, még pedig mint megfeszítettről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, 'És én erőtlenség, félelem és nagy rettegés közt jelentem meg ti köztetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'És az én beszédem és az én prédikálásom nem emberi bölcseségnek hitető beszédiben állott, hanem léleknek és erőnek megmutatásában:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, 'Hogy a ti hitetek ne emberek bölcseségén, hanem Istennek erején nyugodjék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'Bölcseséget pedig a tökéletesek között szólunk; ámde nem e világnak, sem e világ veszendő fejedelmeinek bölcseségét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, 'Hanem Istennek titkon való bölcseségét szóljuk, azt az elrejtetett, melyet öröktől fogva elrendelt az Isten a mi dicsőségünkre;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'Melyet e világ fejedelmei közül senki sem ismert, mert ha megismerték volna, nem feszítették volna meg a dicsőség Urát:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, 'Hanem, a mint meg van írva: A miket szem nem látott, fül nem hallott és embernek szíve meg se gondolt, a miket Isten készített az őt szeretőknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, 'Nekünk azonban az Isten kijelentette az ő Lelke által: mert a Lélek mindeneket vizsgál, még az Istennek mélységeit is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'Mert kicsoda tudja az emberek közül az ember dolgait, hanemha az embernek lelke, a mely ő benne van? Azonképen az Isten dolgait sem ismeri senki, hanemha az Istennek Lelke.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, 'Mi pedig nem e világnak lelkét vettük, hanem az Istenből való Lelket; hogy megismerjük azokat, a miket Isten ajándékozott nékünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, 'Ezeket prédikáljuk is, nem oly beszédekkel, melyekre emberi bölcseség tanít, hanem a melyekre a Szent Lélek tanít; lelkiekhez lelkieket szabván.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, 'Érzéki ember pedig nem foghatja meg az Isten Lelkének dolgait: mert bolondságok néki; meg sem értheti, mivelhogy lelkiképen ítéltetnek meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'A lelki ember azonban mindent megítél, de ő senkitől sem ítéltetik meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, 'Mert ki érte fel az Úrnak értelmét, hogy megoktathatná őt? Bennünk pedig Krisztus értelme van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, 'Én sem szólhattam néktek, atyámfiai, mint lelkieknek, hanem mint testieknek, mint a Krisztusban kisdedeknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'Téjnek italával tápláltalak titeket és nem kemény eledellel, mert még nem bírtátok volna meg, sőt még most sem bírjátok meg:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, 'Mert még testiek vagytok; mert a mikor írigykedés, versengés és visszavonás van köztetek, vajjon nem testiek vagytok-é és nem ember szerint jártok-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, 'Mert mikor egyik ezt mondja: Én Pálé vagyok; a másik meg: Én Apollósé; nem testiek vagytok-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'Hát kicsoda Pál és kicsoda Apollós? Csak szolgák, kik által hívőkké lettetek, és pedig a mint kinek-kinek az Úr adta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, 'Én plántáltam, Apollós öntözött; de az Isten adja vala a növekedést.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'Azért sem a ki plántál, nem valami, sem a ki öntöz; hanem a növekedést adó Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, 'A plántáló pedig és az öntöző egyek; de mindenik a maga jutalmát veszi a maga munkája szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, 'Mert Isten munkatársai vagyunk: Isten szántóföldje, Isten épülete vagytok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, 'Az Istennek nékem adott kegyelme szerint, mint bölcs építőmester, fundamentomot vetettem, de más épít reá. Kiki azonban meglássa mimódon épít reá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, 'Mert más fundamentomot senki nem vethet azon kívül, a mely vettetett, mely a Jézus Krisztus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, 'Ha pedig valaki aranyat, ezüstöt, drágaköveket, fát, szénát, pozdorját épít rá erre a fundamentomra;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, 'Kinek-kinek munkája nyilván lészen: mert ama nap megmutatja, mivelhogy tűzben jelenik meg; és hogy kinek-kinek munkája minémű legyen, azt a tűz próbálja meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'Ha valakinek a munkája, a melyet ráépített, megmarad, jutalmát veszi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'Ha valakinek a munkája megég, kárt vall. Ő maga azonban megmenekül, de úgy, mintha tűzön keresztül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, 'Nem tudjátok-é, hogy ti Isten temploma vagytok, és az Isten Lelke lakozik bennetek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, 'Ha valaki az Isten templomát megrontja, megrontja azt az Isten. Mert az Istennek temploma szent, ezek vagytok ti.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, 'Senki se csalja meg magát. Ha valaki azt hiszi, hogy bölcs ti köztetek e világon, bolond legyen, hogy bölcscsé lehessen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'Mert e világ bölcsesége bolondság az Isten előtt. Mert meg van írva: Megfogja a bölcseket az ő csalárdságukban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'És ismét: Ismeri az Úr a bölcsek gondolatait, hogy hiábavalók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'Azért senki se dicsekedjék emberekkel. Mert minden a tiétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, 'Akár Pál, akár Apollós, akár Kéfás, akár világ, akár élet, akár halál, akár jelenvalók, akár következendők, minden a tiétek. Ti pedig Krisztusé, Krisztus pedig Istené.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, 'Úgy tekintsen minket az ember, mint Krisztus szolgáit és Isten titkainak sáfárait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, 'A mi pedig egyébiránt a sáfárokban megkívántatik, az, hogy mindenik hívnek találtassék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, 'Rám nézve pedig igen csekély dolog, hogy ti tőletek ítéltessem meg, vagy emberi ítéletnaptól; sőt magam sem ítélem meg magamat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, 'Mert semmit sem tudok magamra, de nem ebben vagyok megigazulva; a ki ugyanis engem megítél, az Úr az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, 'Azért idő előtt semmit se ítéljetek, míg el nem jő az Úr, a ki egyrészt világra hozza a sötétségnek titkait, másrészt megjelenti a szíveknek tanácsait; és akkor mindenkinek az Istentől lészen a dícsérete.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, 'Ezeket pedig, atyámfiai, példában szabtam magamra és Apollósra ti érettetek, hogy rajtunk tanuljátok meg, hogy annakfelette a mi írva van, nem kell bölcselkedni; hogy senki se fuvalkodjék fel az egyikért a másik ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, 'Mert kicsoda különböztet meg téged? Mid van ugyanis, a mit nem kaptál volna? Ha pedig úgy kaptad, mit dicsekedel, mintha nem kaptad volna?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, 'Immár beteltetek, immár meggazdagodtatok, nálunk nélkül uralkodásra jutottatok; vajha csakugyan uralkodásra jutottatok volna, hogy mi is veletek egybe uralkodhatnánk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, 'Mert úgy vélem, hogy az Isten minket, az apostolokat, utolsókul állított, mintegy halálra szántakul: mert látványossága lettünk a világnak, úgy angyaloknak, mint embereknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, 'Mi bolondok a Krisztusért, ti pedig bölcsek a Krisztusban; mi erőtlenek, ti pedig erősek; ti dicsőségesek, mi pedig gyalázatosak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, 'Mindezideig éhezünk is, szomjúhozunk is, mezítelenkedünk is, bántalmaztatunk is, bujdosunk is,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 12, 'Fáradozunk is, tulajdon kezünkkel munkálkodván; ha szidalommal illettetünk, jót kívánunk; ha háborúságot szenvedünk, békességgel tűrjük;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 13, 'Ha gyaláztatunk, könyörgünk: szinte a világ szemetjévé lettünk, mindeneknek söpredékévé egész mostanig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 14, 'Nem azért írom ezeket, hogy megszégyenítselek titeket, hanem mint szerelmes gyermekeimet intelek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 15, 'Mert ha tízezer tanítómesteretek lenne is a Krisztusban, de nem sok atyátok; mert tőlem vagytok a Krisztus Jézusban az evangyéliom által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 16, 'Kérlek azért titeket, legyetek az én követőim.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 17, 'Azért küldtem hozzátok Timótheust, ki nékem szeretett és hű fiam az Úrban, a ki eszetekbe juttatja néktek az én útaimat a Krisztusban, a mint mindenütt, minden gyülekezetben tanítok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 18, 'De mintha el se mennék ti hozzátok, úgy felfuvalkodtak némelyek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 19, 'Pedig elmegyek hamarosan hozzátok, ha az Úr akarándja; és megismerem a felfuvalkodottaknak nem a beszédjét, hanem az erejét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 20, 'Mert nem beszédben áll az Istennek országa, hanem erőben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 21, 'Mit akartok? Vesszővel menjek-é hozzátok, avagy szeretettel és szelídségnek lelkével?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, 'Általában hallatszik köztetek paráznaság, még olyan paráznaság is, a milyen a pogányok között sem említtetik, hogy valaki atyjának feleségét elvegye.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, 'És ti fel vagytok fuvalkodva, és nem keseredtetek meg inkább, hogy kivettetnék közületek, a ki ezt a dolgot cselekedte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, 'Mert én távol lévén ugyan testben, de jelen lévén lélekben, már elvégeztem, mintha jelen volnék, hogy azt, a ki ekként ezt cselekedte,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, 'Ti és az én lelkem a mi Urunk Jézus Krisztusnak nevében egybegyűlvén, a mi Urunk Jézus Krisztus hatalmával');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, 'Átadjuk az ilyent a Sátánnak a testnek veszedelmére, hogy a lélek megtartassék az Úr Jézusnak ama napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, 'Nem jó a ti dicsekedéstek. Avagy nem tudjátok-é, hogy egy kicsiny kovász az egész tésztát megposhasztja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, 'Tisztítsátok el azért a régi kovászt, hogy legyetek új tésztává, a minthogy kovász nélkül valók vagytok; mert hiszen a mi húsvéti bárányunk, a Krisztus, megáldoztatott érettünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, 'Azért ne régi kovászszal ünnepeljünk, sem rosszaságnak és gonoszságnak kovászával, hanem tisztaságnak és igazságnak kovásztalanságában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, 'Azt írtam néktek ama levelemben, hogy paráznákkal ne társalkodjatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, 'De nem általában e világ paráznáival, vagy csalóival, vagy ragadozóival, vagy bálványimádóival; mert hiszen így ki kellene e világból mennetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, 'Most azért azt írom néktek, hogy ne társalkodjatok azzal, ha valaki atyafi létére parázna, vagy csaló, vagy bálványimádó, vagy szidalmazó, vagy részeges, vagy ragadozó. Az ilyennel még együtt se egyetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, 'Mert mi közöm ahhoz, hogy a kívülvalókról is ítéletet tegyek? avagy ti nem a belüllévők fölött tesztek-é ítéletet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, 'A kívülvalókat pedig majd az Isten ítéli meg. Vessétek ki azért a gonoszt magatok közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, 'Merészel valaki ti közületek, ha peres dolga van a másikkal, az igaztalanok előtt törvénykezni, és nem a szentek előtt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, 'Nem tudjátok-é, hogy a szentek a világot ítélik meg? És ha ti ítélitek meg a világot, méltatlanok vagytok-é a legkisebb dolgokban való ítéletekre?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, 'Nem tudjátok-é, hogy angyalokat fogunk ítélni, nemhogy életszükségre való dolgokat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, 'Azért ha életszükségre való dolgok felől van törvénykezéstek, a kik a gyülekezetben legalábbvalók, azokat ültessétek le.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, 'Megszégyenítéstekre mondom: Hát nincs ti köztetek egy bölcs ember sem, a ki ítéletet tehetne az ő atyjafiai között?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, 'Hanem atyafi atyafival törvénykezik, még pedig hitetlenek előtt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, 'Egyáltalán már az is gyarlóság ti bennetek, hogy törvénykeztek egymással. Miért nem szenveditek inkább a bántalmazást? Miért nem tűritek inkább a kárt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, 'Sőt ti okoztok bántalmazást és kárt, még pedig atyátokfiainak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, 'Avagy nem tudjátok-é, hogy igazságtalanok nem örökölhetik Istennek országát? Ne tévelyegjetek; se paráznák, se bálványimádók, se házasságtörők, se pulyák, se férfiszeplősítők,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, 'Se lopók, se telhetetlenek, se részegesek, se szidalmazók, se ragadozók nem örökölhetik Isten országát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, 'Ilyenek voltatok pedig némelyek, de megmosattattatok, de megszenteltettetek, de megigazíttattatok az Úr Jézusnak nevében és a mi Istenünk Lelke által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, 'Minden szabad nékem, de nem minden használ; minden szabad nékem, de én nem adatom valakinek hatalma alá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, 'Az eledelek a hasnak és a has az eledeleknek rendeltetett. Az Isten pedig mind ezt, mind amazokat eltörli. A test azonban nem a paráznaságnak rendeltetett, hanem az Úrnak, és az Úr a testnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 14, 'Az Isten pedig az Urat is feltámasztotta, minket is feltámaszt az ő hatalma által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 15, 'Nem tudjátok-é, hogy a ti testeitek a Krisztusnak tagjai? Elszakítva hát a Krisztus tagjait, paráznának tagjaivá tegyem? Távol legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 16, 'Avagy nem tudjátok-é, hogy a ki a paráznával egyesül, egy test vele? Mert ketten lesznek, úgymond, egy testté.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 17, 'A ki pedig az Úrral egyesül, egy lélek ő vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 18, 'Kerüljétek a paráznaságot. Minden bűn, melyet az ember cselekszik, a testen kívül van, de a ki paráználkodik, a maga teste ellen vétkezik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 19, 'Avagy nem tudjátok-é, hogy a ti testetek a bennetek lakozó Szent Léleknek temploma, a melyet Istentől nyertetek; és nem a magatokéi vagytok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, 'Mert áron vétettetek meg; dicsőítsétek azért az Istent a ti testetekben és lelketekben, a melyek az Istenéi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, 'A mik felől pedig írtatok nékem, jó a férfiúnak asszonyt nem illetni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, 'De a paráznaság miatt minden férfiúnak tulajdon felesége legyen, és minden asszonynak tulajdon férje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, 'A feleségének adja meg a férj a köteles jóakaratot; hasonlóképen a feleség is a férjének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, 'A feleség nem ura a maga testének, hanem a férje; hasonlóképen a férj sem ura a maga testének, hanem a felesége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, 'Ne foszszátok meg egymást, hanemha egyenlő akaratból bizonyos ideig, hogy ráérjetek a bőjtölésre és az imádkozásra, azután ismét együvé térjetek, hogy a Sátán meg ne kísértsen titeket, mivelhogy magatokat meg nem tartóztathatjátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, 'Ezt pedig kedvezésképen mondom, nem parancsolat szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'Mert szeretném, ha minden ember úgy volna, mint én magam is; de kinek kinek tulajdon kegyelmi ajándéka vagyon Istentől, egynek így, másnak pedig úgy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, 'Mondom pedig a nem házasoknak és az özvegyasszonyoknak, hogy jó nékik, ha úgy maradhatnak, mint én is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'De ha magukat meg nem tartóztathatják, házasságban éljenek: mert jobb házasságban élni, mint égni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'Azoknak pedig, a kik házasságban vannak, hagyom nem én, hanem az Úr, hogy az asszony férjétől el ne váljék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, 'Hogyha pedig elválik is, maradjon házasság nélkül, vagy béküljön meg férjével; és a férj se bocsássa el a feleségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'Egyebeknek pedig én mondom, nem az Úr: Ha valamely atyafinak hitetlen felesége van, és ez vele akar lakni, el ne bocsássa azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'És a mely asszonynak hitetlen férje van, és ez vele akar lakni, el ne bocsássa azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'Mert meg van szentelve a hitetlen férj az ő feleségében, és meg van szentelve a hitetlen asszony az ő férjében, mert különben a ti gyermekeitek tisztátalanok volnának, most pedig szentek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, 'Ha pedig a hitetlen elválik, ám váljék el; nem vettetett szolgaság alá a keresztyén férfiú, vagy asszony az ilyen dolgokban. De békességre hívott minket az Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, 'Mert mit tudod, te asszony, ha megmentheted-e a férjedet; vagy mit tudod, te férfiú, ha megmentheted-e a feleségedet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, 'Csak a mint kinek-kinek adta az Isten, a mint kit-kit elhívott az Úr, úgy járjon. És minden gyülekezetben ekképen rendelkezem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, 'Körülmetélten hivatott el valaki? ne fedezze el azt; körülmetéletlenül hivatott el valaki? me metélkedjék körül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, 'A körülmetélkedés semmi, a körülmetéletlenség is semmi; hanem Isten parancsolatainak megtartása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, 'Kiki a mely hivatásban hívatott el, abban maradjon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'Szolgai állapotban hivattattál el? Ne gondolj vele, sőt ha szabad lehetsz is, inkább élj azzal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, 'Mert az Úrban elhívott szolga az Úrnak szabadosa; hasonlóképen a ki szabadságban hívatott el, Krisztusnak szolgája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, 'Áron vétettetek meg, ne legyetek embereknek szolgái.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, 'Kiki a miben elhívatott, atyámfiai, abban maradjon meg az Isten előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, 'A hajadonok felől nincs ugyan parancsolatom az Úrtól, de tanácsot adok úgy, mint a ki irgalmasságot nyertem az Úrtól, hogy hitelreméltó legyek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, 'Úgy ítélem azért, hogy jó ez a jelenvaló szükség miatt, hogy tudniillik jó az embernek úgy maradni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, 'Feleséghez köttettél? Ne keress elválást. Megszabadultál feleségedtől? Ne keress feleséget.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, 'De ha veszel is feleséget, nem vétkezel; és ha férjhez megy is a hajadon, nem vétkezik; de az ilyeneknek háborúságuk lesz a testben. Én pedig kedveznék néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, 'Ezt pedig azért mondom, atyámfiai, mert az idő rövidre van szabva ezentúl, azért a kiknek van is feleségök, úgy legyenek, mintha nem volna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, 'És a kik sírnak, mintha nem sírnának; és a kik vígadnak, mintha nem vígadnának; a kik vesznek, mintha semmijök sem volna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, 'És a kik élnek e világgal, mintha nem élnének: mert elmúlik e világnak ábrázatja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, 'Azt akarnám pedig, hogy ti gond nélkül legyetek. A ki házasság nélkül van, arra visel gondot, a mi az Úré, mimódon kedveskedhessék az Úrnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, 'A ki pedig feleséget vett, a világiakra visel gondot, mimódon kedveskedhessék a feleségének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, 'Különbözik egymástól az asszony és a hajadon. A ki nem ment férjhez, az Úr dolgaira visel gondot, hogy szent legyen mind testében, mind lelkében; a ki pedig férjhez ment, a világiakra visel gondot, mimódon kedveskedhessék a férjének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, 'Ezt pedig a ti hasznotokra mondom; nem hogy tőrt vessek néktek, hanem hogy illendőképen és állhatatosan ragaszkodjatok az Úrhoz háboríthatatlanul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, 'De ha valaki szégyennek tartja az ő hajadon leányára, ha virágzó idejét múlja, és úgy kell történnie, a mit akar, azt cselekedje, nem vétkezik; menjenek férjhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, 'A ki pedig szilárdan áll a szívében és a szükség nem kényszeríti, hatalma pedig van a tulajdon akarata fölött, és azt végezte el szívében, hogy megtartja hajadon leányát, jól cselekszi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, 'Azért, a ki férjhez adja, az is jól cselekszi, de a ki nem adja férjhez, még jobban cselekszi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, 'Az asszonyt törvény köti, míg férje él, de ha férje meghal, szabadon férjhez mehet, a kihez akar, csakhogy az Úrban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, 'De boldogabb, ha úgy marad, az én véleményem szerint; pedig hiszem, hogy bennem is Istennek lelke van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, 'A bálványáldozatok felől pedig tudjuk, hogy mindnyájunknak van ismeretünk. Az ismeret felfuvalkodottá tesz, a szeretet pedig épít.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, 'Ha pedig valaki azt hiszi, hogy tud valamit, még semmit sem ismer úgy, a mint ismernie kell.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, 'Hanem ha valaki az Istent szereti, az ismertetik ő tőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, 'Tehát a bálványáldozati hús evése felől tudjuk, hogy egy bálvány sincs a világon, és hogy Isten sincs senki más, hanem csak egy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, 'Mert ha vannak is úgynevezett istenek akár az égben, akár a földön, a minthogy van sok isten és sok úr;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, 'Mindazáltal nekünk egy Istenünk van, az Atya, a kitől van a mindenség, mi is ő benne; és egy Urunk, a Jézus Krisztus, a ki által van a mindenség, mi is ő általa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, 'De nem mindenkiben van meg ez az ismeret; sőt némelyek a bálvány felől való lelkiismeretök szerint mind mai napig mint bálványáldozatot eszik, és az ő lelkiismeretök, mivelhogy erőtelen, megfertőztetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, 'Pedig az eledel nem tesz minket kedvesekké Isten előtt; mert ha eszünk is, nem leszünk gazdagabbak; ha nem eszünk is, nem leszünk szegényebbek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, 'De meglássátok, hogy ez a ti szabadságtok valamiképen botránkozásukra ne legyen az erőteleneknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, 'Mert ha valaki meglát téged, a kinek ismereted van, hogy a bálványtemplomnál vendégeskedel, annak lelkiismerete, mivelhogy erőtelen, nem arra indíttatik-é, hogy megegye a bálványáldozatot?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, 'És a te ismereted miatt elkárhozik a te erőtelen atyádfia, a kiért Krisztus meghalt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, 'Így aztán, mikor az atyafiak ellen vétkeztek, és az ő erőtelen lelkiismeretüket megsértitek, a Krisztus ellen vétkeztek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, 'Annakokáért, ha eledel botránkoztatja meg az én atyámfiát, inkább soha sem eszem húst, hogy az én atyámfiát meg ne botránkoztassam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, 'Nem vagyok-é apostol? Nem vagyok-é szabad? Nem láttam-é Jézus Krisztust, a mi Urunkat? Nem az én munkám vagytok-é ti az Úrban?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, 'Ha egyebeknek nem vagyok apostoluk, de bizony néktek az vagyok, mert az én apostolságomnak pecsétje az Úrban ti vagytok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, 'Ez az én védelmem azok ellenében, a kik vádolnak engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, 'Nincsen-é arra jogunk, hogy együnk és igyunk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, 'Nincsen-é arra jogunk, hogy keresztyén feleségünket magunkkal hordozzuk, mint a többi apostolok is és az Úrnak atyjafiai és Kéfás?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, 'Avagy csak nekem és Barnabásnak nincs-é jogunk, hogy ne dolgozzunk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, 'Kicsoda katonáskodik valaha a maga zsoldján? Kicsoda plántál szőlőt, és nem eszik annak gyümölcséből? Vagy kicsoda legeltet nyájat, és nem eszik a nyájnak tejéből?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, 'Vajjon emberi módon beszélem-é ezeket? vagy nem ezeket mondja-é a törvény is?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, 'Mert a Mózes törvényében meg van írva: Ne kösd fel a nyomtató ökörnek száját. Avagy az ökrökre van-é az Istennek gondja?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, 'Avagy nem érettünk mondja-é általában? Mert mi érettünk íratott meg, hogy a ki szánt, reménység alatt kell szántania, és a ki csépel, az ő reménységében részesnek lennie reménység alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, 'Ha mi néktek a lelkieket vetettük, nagy dolog-é, ha mi a ti testi javaitokat aratjuk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, 'Ha egyebek részesülnek a ti javaitokban, mért nem inkább mi? De mi nem éltünk e szabadsággal; hanem mindent eltűrünk, hogy valami akadályt ne gördítsünk a Krisztus evangyélioma elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, 'Nem tudjátok-é, hogy a kik a szent dolgokban munkálkodnak, a szent helyből élnek, és a kik az oltár körül forgolódnak, az oltárral együtt veszik el részüket?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, 'Ekképen rendelte az Úr is, hogy a kik az evangyéliomot hirdetik, az evangyéliomból éljenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, 'De én ezek közül egygyel sem éltem. Nem azért írtam azonban ezeket, hogy velem is így történjék, mert jobb nékem meghalnom, hogysem valaki hiábavalóvá tegye az én dicsekedésemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, 'Mert ha az evangyéliomot hirdetem, nem dicsekedhetem, mert szükség kényszerít engem. Jaj ugyanis nékem, ha az evangyéliomot nem hirdetem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, 'Mert ha akaratom szerint mívelem ezt, jutalmam van; ha pedig akaratom nélkül, sáfársággal bízattam meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, 'Micsoda tehát az én jutalmam? Hogy prédikálásommal ingyenvalóvá tegyem a Krisztus evangyéliomát, hogy ne használjam ki ama szabadságomat az evangyéliom hirdetésénél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, 'Mert én, noha mindenkivel szemben szabad vagyok, magamat mindenkinek szolgájává tettem, hogy a többséget megnyerjem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, 'És a zsidóknak zsidóvá lettem, hogy zsidókat nyerjek meg; a törvény alatt valóknak törvény alatt valóvá, hogy a törvény alatt valókat megnyerjem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, 'A törvény nélkül valóknak törvénynélkülivé, noha nem vagyok Isten törvénye nélkül, hanem Krisztus törvényében való, hogy törvény nélkül valókat nyerjek meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, 'Az erőtleneknek erőtelenné lettem, hogy az erőteleneket megnyerjem. Mindeneknek mindenné lettem, hogy minden módon megtartsak némelyeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, 'Ezt pedig az evangyéliomért mívelem, hogy részestárs legyek abban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, 'Nem tudjátok-é, hogy a kik versenypályán futnak, mindnyájan futnak ugyan, de egy veszi el a jutalmat? Úgy fussatok, hogy elvegyétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, 'Mindaz pedig a ki pályafutásban tusakodik, mindenben magatűrtető; azok ugyan, hogy romlandó koszorút nyerjenek, mi pedig romolhatatlant.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, 'Én azért úgy futok, mint nem bizonytalanra; úgy viaskodom, mint a ki nem levegőt vagdos;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, 'Hanem megsanyargatom testemet és szolgává teszem; hogy míg másoknak prédikálok, magam valami módon méltatlanná ne legyek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, 'Nem akarom pedig, hogy ne tudjátok, atyámfiai, hogy a mi atyáink mindnyájan a felhő alatt voltak, és mindnyájan a tengeren mentek által;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'És mindnyájan Mózesre keresztelkedtek meg a felhőben és a tengerben;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, 'És mindnyájan egy lelki eledelt ettek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'És mindnyájan egy lelki italt ittak, mert ittak a lelki kősziklából, a mely követi vala őket, e kőszikla pedig a Krisztus volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, 'De azoknak többségét nem kedvelé az Isten, mert elhullának a pusztában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, 'Ezek pedig példáink lőnek, hogy mi ne kívánjunk gonosz dolgokat, a miképen azok kívántak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, 'Se bálványimádók ne legyetek, mint azok közül némelyek, a mint meg van írva: Leüle a nép enni és inni, és felkelének játszani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, 'Se pedig ne paráználkodjunk mint azok közül paráználkodtak némelyek, és elestek egy napon huszonháromezeren.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, 'Se a Krisztust ne kísértsük, a mint közülök kísértették némelyek, és elveszének a kígyók miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, 'Se pedig ne zúgolódjatok, miképen ő közülök zúgolódának némelyek, és elveszének a pusztító által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, 'Mindezek pedig példaképen estek rajtok; megírattak pedig a mi tanulságunkra, a kikhez az időknek vége elérkezett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, 'Azért a ki azt hiszi, hogy áll, meglássa, hogy el ne essék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, 'Nem egyéb, hanem csak emberi kísértés esett rajtatok: de hű az Isten, a ki nem hágy titeket feljebb kísértetni, mint elszenvedhetitek; sőt a kísértéssel egyetemben a kimenekedést is megadja majd, hogy elszenvedhessétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, 'Azért szerelmeseim, kerüljétek a bálványimádást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, 'Mint okosokhoz szólok, ítéljétek meg ti, a mit mondok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, 'A hálaadásnak pohara, a melyet megáldunk, nem a Krisztus vérével való közösségünk-é? A kenyér, a melyet megszegünk, nem a Krisztus testével való közösségünk-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, 'Mert egy a kenyér, egy test vagyunk sokan; mert mindnyájan az egy kenyérből részesedünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, 'Tekintsétek meg a test szerint való Izráelt! A kik az áldozatokat eszik, avagy nincsenek-é közösségben az oltárral?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, 'Mit mondok tehát? Hogy a bálvány valami, vagy hogy a bálványáldozat valami?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, 'Sőt, hogy a mit a pogányok áldoznak, ördögöknek áldozzák és nem Istennek; nem akarom pedig, hogy ti az ördögökkel legyetek közösségben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, 'Nem ihatjátok az Úr poharát és az ördögök poharát; nem lehettek az Úr asztalának és az ördögök asztalának részesei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, 'Vagy haragra ingereljük az Urat? avagy erősebbek vagyunk-é nálánál?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, 'Minden szabad nékem, de nem minden használ; minden szabad nékem, de nem minden épít.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, 'Senki ne keresse, a mi az övé, hanem kiki azt, a mi a másé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, 'Mindent, a mit a mészárszékben árulnak, megegyetek, semmit sem tudakozódván a lelkiismeret miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, 'Mert az Úré a föld és annak teljessége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, 'Ha pedig valaki meghív titeket a hitetlenek közül és el akartok menni, mindent, a mit elétek hoznak, megegyetek, semmit sem tudakozódván a lelkiismeret miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, 'De ha valaki ezt mondja néktek: Ez bálványáldozati hús, ne egyétek meg a miatt, a ki megjelentette, és a lelkiismeretért; mert az Úré a föld és annak teljessége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, 'De nem a tulajdon lelkiismeretet értem, hanem a másikét. Mert miért kárhoztassa az én szabadságomat a más lelkiismerete?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, 'Ha pedig én hálaadással veszek részt, miért káromoltatom azért, a miért én hálákat adok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, 'Azért akár esztek, akár isztok, akármit cselekesztek, mindent az Isten dicsőségére míveljetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, 'Meg ne botránkoztassátok se a zsidókat, se a görögöket, se az Isten gyülekezetét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, 'Miképen én is mindenkinek mindenben kedvében járok, nem keresvén a magam hasznát, hanem a sokaságét, hogy megtartassanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, 'Legyetek az én követőim, mint én is a Krisztusé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, 'Dícsérlek pedig titeket atyámfiai, hogy én rólam mindenben megemlékeztek, és a miképen meghagytam néktek, rendeléseimet megtartjátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, 'Akarom pedig, hogy tudjátok, hogy minden férfiúnak feje a Krisztus; az asszonynak feje pedig a férfiú; a Krisztusnak feje pedig az Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, 'Minden férfiú, a ki befedett fővel imádkozik avagy prófétál, megcsúfolja az ő fejét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, 'Minden asszony pedig, a ki befedetlen fővel imádkozik avagy prófétál, megcsúfolja az ő fejét, mert egy és ugyanaz, mintha megnyiretett volna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, 'Mert ha az asszony nem fedi be fejét, nyiretkezzék is meg, hogy ha pedig éktelen dolog asszonynak megnyiretkezni, vagy megberetváltatni, fedezze be az ő fejét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, 'Mert a férfiúnak nem kell befednie az ő fejét, mivel ő az Istennek képe és dicsősége; de az asszony a férfiú dicsősége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, 'Mert nem a férfiú van az asszonyból, hanem az asszony a férfiúból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, 'Mert nem is a férfiú teremtetett az asszonyért, hanem az asszony a férfiúért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, 'Ezért kell az asszonynak hatalmi jelt viselni a fején az angyalok miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, 'Mindazáltal sem férfiú nincs asszony nélkül, sem asszony férfiú nélkül az Úrban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, 'Mert a miképen az asszony a férfiúból van, azonképen a férfiú is az asszony által, az egész pedig az Istentől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, 'Magatokban ítéljétek meg: illendő dolog-é asszonynak fedetlen fővel imádni az Istent?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, 'Avagy maga a természet is nem arra tanít-é titeket, hogy ha a férfiú nagy hajat visel, csúfsága az néki?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, 'Az asszonynak pedig, ha nagy haja van, ékesség az néki; mert a haj fátyol gyanánt adatott néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, 'Ha pedig valakinek tetszik versengeni, nekünk olyan szokásunk nincsen, sem az Isten gyülekezeteinek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 17, 'Ezt pedig tudtotokra adván, nem dícsérlek, hogy nem haszonnal, hanem kárral gyűltök egybe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 18, 'Mert először is, mikor egybegyűltök a gyülekezetben, hallom, hogy szakadások vannak köztetek; és valami részben hiszem is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 19, 'Mert szükség, hogy szakadások is legyenek köztetek, hogy a kipróbáltak nyilvánvalókká legyenek ti köztetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 20, 'Mikor tehát egybegyűltök egyazon helyre, nincs úrvacsorájával való élés:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 21, 'Mert kiki az ő saját vacsoráját veszi elő az evésnél; és némely éhezik, némely pedig dőzsöl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 22, 'Hát nincsenek-é házaitok az evésre és ivásra? Avagy az Isten gyülekezetét vetitek-é meg, és azokat szégyenítitek-é meg, a kiknek nincsen? Mit mondjak néktek? Dícsérjelek-é titeket ebben? Nem dícsérlek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, 'Mert én az Úrtól vettem, a mit néktek előtökbe is adtam: hogy az Úr Jézus azon az éjszakán, melyen elárultaték, vette a kenyeret,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, 'És hálákat adván, megtörte és ezt mondotta: Vegyétek, egyétek! Ez az én testem, mely ti érettetek megtöretik; ezt cselekedjétek az én emlékezetemre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, 'Hasonlatosképen a pohárt is vette, minekutána vacsorált volna, ezt mondván: E pohár amaz új testamentom az én vérem által; ezt cselekedjétek, valamennyiszer isszátok az én emlékezetemre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 26, 'Mert valamennyiszer eszitek e kenyeret és isszátok e pohárt, az Úrnak halálát hirdessétek, a míg eljövend.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 27, 'Azért a ki méltatlanul eszi e kenyeret, vagy issza az Úrnak poharát, vétkezik az Úr teste és vére ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 28, 'Próbálja meg azért az ember magát, és úgy egyék abból a kenyérből, és úgy igyék abból a pohárból,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 29, 'Mert a ki méltatlanul eszik és iszik, ítéletet eszik és iszik magának, mivelhogy nem becsüli meg az Úrnak testét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 30, 'Ezért van ti köztetek sok erőtlen és beteg, és alusznak sokan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 31, 'Mert ha mi ítélnők magunkat, nem ítéltetnénk el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 32, 'De mikor ítéltetünk, az Úrtól taníttatunk, hogy a világgal együtt el ne kárhoztassunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 33, 'Azért atyámfiai, mikor egybegyűltök az evésre, egymást megvárjátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 34, 'Ha pedig valaki éhezik, otthon egyék, hogy ítéletre ne gyűljetek egybe. A többire nézve, majd ha hozzátok megyek, rendelkezem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, 'A lelki ajándékokra nézve pedig nem akarom, atyámfiai, hogy tudatlanok legyetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'Tudjátok, hogy pogányok voltatok, vitetvén, a mint vitettetek, a néma bálványokhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, 'Azért tudtotokra adom néktek, hogy senki, a ki Istennek Lelke által szól, nem mondja Jézust átkozottnak; és senki sem mondhatja Úrnak Jézust, hanem csak a Szent Lélek által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, 'A kegyelmi ajándékokban pedig különbség van, de ugyanaz a Lélek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, 'A szolgálatokban is különbség van, de ugyanaz az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, 'És különbség van a cselekedetekben is, de ugyanaz az Isten, a ki cselekszi mindezt mindenkiben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, 'Mindenkinek azonban haszonra adatik a Léleknek kijelentése.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, 'Némelyiknek ugyanis bölcseségnek beszéde adatik a Lélek által; másiknak pedig tudománynak beszéde ugyanazon Lélek szerint;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, 'Egynek hit ugyanazon Lélek által; másnak pedig gyógyítás ajándékai azon egy Lélek által;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, 'Némelyiknek csodatévő erőknek munkái; némelyiknek meg prófétálás; némelyiknek pedig lelkeknek megítélése; másiknak nyelvek nemei; másnak pedig nyelvek magyarázása;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, 'De mindezeket egy és ugyanaz a Lélek cselekszi, osztogatván mindenkinek külön, a mint akarja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, 'Mert a miképen a test egy és sok tagja van, az egy testnek tagjai pedig, noha sokan vannak, mind egy test, azonképen a Krisztus is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, 'Mert hiszen egy Lélek által mi mindnyájan egy testté kereszteltettünk meg, akár zsidók, akár görögök, akár szolgák, akár szabadok; és mindnyájan egy Lélekkel itattattunk meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, 'Mert a test sem egy tag, hanem sok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, 'Ha ezt mondaná a láb: mivelhogy nem kéz vagyok, nem vagyok a testből való; avagy nem a testből való-é azért?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, 'És ha a fül ezt mondaná: mivelhogy nem vagyok szem, nem vagyok a testből való; avagy nem a testből való-é azért?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, 'Ha az egész test szem, hol a hallás? ha az egész hallás, hol a szaglás?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, 'Most pedig az Isten elhelyezte a tagokat a testben egyenként mindeniket, a mint akarta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, 'Ha pedig az egész egy tag volna hol volna a test?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, 'Így azonban sok tag van ugyan, de egy test.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, 'Nem mondhatja pedig a szem a kéznek: Nincs rád szükségem; vagy viszont a fej a lábaknak: Nem kelletek nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, 'Sőt sokkal inkább, a melyek a test legerőtelenebb tagjainak látszanak, azok igen szükségesek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 23, 'És a melyeket a test tisztességtelenebb tagjainak tartunk, azoknak nagyobb tisztességet tulajdonítunk; és a melyek éktelenek bennünk, azok nagyobb ékességben részesülnek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 24, 'A melyek pedig ékesek bennünk, azoknak nincs erre szükségök. De az Isten szerkeszté egybe a testet, az alábbvalónak nagyobb tisztességet adván,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 25, 'Hogy ne legyen hasonlás a testben, hanem ugyanarról gondoskodjanak egymásért a tagok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 26, 'És akár szenved egy tag, vele együtt szenvednek a tagok mind; akár tisztességgel illettetik egy tag, vele együtt örülnek a tagok mind.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 27, 'Ti pedig a Krisztus teste vagytok, és tagjai rész szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 28, 'És pedig némelyeket rendelt az Isten az anyaszentegyházban először apostolokul, másodszor prófétákul, harmadszor tanítókul; azután csodatévő erőket, aztán gyógyításnak ajándékait, gyámolokat, kormányokat, nyelvek nemeit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 29, 'Avagy mindnyájan apostolok-é? Vagy mindnyájan próféták-é? Avagy mindnyájan tanítók-é? Vagy mindnyájan csodatévő erők-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 30, 'Avagy mindnyájoknak van-é gyógyításra való ajándéka? Vagy mindnyájan szólnak-é nyelveken? Vagy mindnyájan magyaráznak-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 31, 'Igyekezzetek pedig a hasznosabb ajándékokra. És ezenfelül még egy kiváltképen való útat mutatok néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, 'Ha embereknek vagy angyaloknak nyelvén szólok is, szeretet pedig nincsen én bennem, olyanná lettem, mint a zengő ércz vagy pengő czimbalom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, 'És ha jövendőt tudok is mondani, és minden titkot és minden tudományt ismerek is; és ha egész hitem van is, úgyannyira, hogy hegyeket mozdíthatok ki helyökről, szeretet pedig nincsen én bennem, semmi vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, 'És ha vagyonomat mind felétetem is, és ha testemet tűzre adom is, szeretet pedig nincsen én bennem, semmi hasznom abból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, 'A szeretet hosszútűrő, kegyes; a szeretet nem irígykedik, a szeretet nem kérkedik, nem fuvalkodik fel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, 'Nem cselekszik éktelenül, nem keresi a maga hasznát, nem gerjed haragra, nem rójja fel a gonoszt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, 'Nem örül a hamisságnak, de együtt örül az igazsággal;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, 'Mindent elfedez, mindent hiszen, mindent remél, mindent eltűr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, 'A szeretet soha el nem fogy: de legyenek bár jövendőmondások, eltöröltetnek; vagy akár nyelvek, megszünnek; vagy akár ismeret, eltöröltetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, 'Mert rész szerint van bennünk az ismeret, rész szerint a prófétálás:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, 'De mikor eljő a teljesség, a rész szerint való eltöröltetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, 'Mikor gyermek valék, úgy szóltam, mint gyermek, úgy gondolkodtam, mint gyermek, úgy értettem, mint gyermek: minekutána pedig férfiúvá lettem, elhagytam a gyermekhez illő dolgokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, 'Mert most tükör által homályosan látunk, akkor pedig színről-színre; most rész szerint van bennem az ismeret, akkor pedig úgy ismerek majd, a mint én is megismertettem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, 'Most azért megmarad a hit, remény, szeretet, e három; ezek között pedig legnagyobb a szeretet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, 'Kövessétek a szeretetet, kívánjátok a lelki ajándékokat, leginkább pedig, hogy prófétáljatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, 'Mert a ki nyelveken szól, nem embereknek szól, hanem az Istennek; mert senki sem érti, hanem lélekben beszél titkos dolgokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, 'A ki pedig prófétál, embereknek beszél épülésre, intésre és vígasztalásra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, 'A ki nyelveken szól, magát építi; de a ki prófétál, a gyülekezetet építi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, 'Szeretném ugyan, ha mindnyájan szólnátok nyelveken, de inkább, hogy prófétálnátok; mert nagyobb a próféta, mint nyelveken szóló, kivévén, ha megmagyarázza, hogy a gyülekezet épüljön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, 'Ha már most, atyámfiai, hozzátok megyek, és nyelveken szólok, mit használok néktek, ha vagy kijelentésben, vagy ismeretben, vagy prófétálásban, vagy tanításban nem szólok hozzátok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, 'Hiszen ha az élettelen hangszerek, akár fuvola, akár czitera, nem adnak megkülönböztethető hangokat, mimódon ismerjük meg, a mit fuvoláznak vagy cziteráznak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, 'Mert ha a trombita bizonytalan zengést tészen, kicsoda készül a harczra?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, 'Azonképen ti is, ha érthető nyelven nem beszéltek, mimódon értik meg, a mit szóltok? Csak a levegőbe fogtok beszélni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, 'Példa mutatja, oly sokféle szólás van a világon, és azok közül egy sem érthetetlen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, 'Hogyha azért nem tudom a szónak értelmét, a beszélőnek idegen leszek, és a beszélő is idegen előttem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, 'Azonképen ti is, minthogy lelki ajándékokat kívántok, a gyülekezet építésére igyekezzetek, hogy gyarapodjatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, 'Azért a ki nyelveken szól, imádkozzék, hogy megmagyarázza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, 'Mert ha nyelvvel könyörgök, a lelkem könyörög, de értelmem gyümölcstelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, 'Hogy van hát? Imádkozom a lélekkel, de imádkozom az értelemmel is; énekelek a lélekkel, de énekelek az értelemmel is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, 'Mert ha lélekkel mondasz áldást, az ott lévő avatatlan miképen fog a te hálaadásodra Áment mondani, mikor nem tudja, mit beszélsz?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, 'Mert jóllehet, te szépen mondasz áldást, de más nem épül abból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, 'Hálát adok az én Istenemnek, hogy mindnyájatoknál inkább tudok nyelveken szólni;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, 'De a gyülekezetben inkább akarok öt szót szólani értelemmel, hogy egyebeket is tanítsak, hogy nem mint tízezer szót nyelveken.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, 'Atyámfiai, ne legyetek gyermekek értelemben; hanem a gonoszságban legyetek gyermekek, értelemben pedig érettek legyetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, 'A törvényben meg van írva: Idegen nyelveken és idegen ajkakkal szólok e népnek, és így sem hallgatnak rám, azt mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, 'A nyelvek tehát jelül vannak, nem a hívőknek, hanem a hitetleneknek; a prófétálás pedig nem a hitetleneknek, hanem a hívőknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, 'Azért ha az egész gyülekezet egybegyűl és mindnyájan nyelveken szólnak, bemenvén az idegenek vagy hitetlenek, nem azt mondják-é, hogy őrjöngtök?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, 'De ha mindnyájan prófétálnak és bemegy egy hitetlen, vagy avatatlan, az mindenektől megfeddetik, mindenektől megítéltetik,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, 'És ilyen módon az ő szívének titkai nyilvánvalókká lesznek; és így arczra borulva imádja az Istent, hirdetvén, hogy bizonynyal az Isten lakik ti bennetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, 'Hogy van hát atyámfiai? Mikor egybegyűltök, mindeniteknek van zsoltára, tanítása, nyelve, kijelentése, magyarázata. Mindenek épülésre legyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, 'Ha valaki nyelveken szól, kettő vagy legfeljebb három legyen, mégpedig egymás után; és egy magyarázza meg:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, 'Ha pedig nincsen magyarázó, hallgasson a gyülekezetben; hanem magának szóljon és az Istennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, 'A próféták pedig ketten vagy hárman beszéljenek; és a többiek ítéljék meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, 'De ha egy másik ott ülő vesz kijelentést, az első hallgasson.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, 'Mert egyenként mindnyájan prófétálhattok, hogy mindenki tanuljon, és mindenki vígasztalást vegyen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, 'És a prófétalelkek engednek a prófétáknak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 33, 'Mert az Isten nem a visszavonásnak, hanem a békességnek Istene; miként a szentek minden gyülekezetében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 34, 'A ti asszonyaitok hallgassanak a gyülekezetekben, mert nincsen megengedve nékik, hogy szóljanak; hanem engedelmesek legyenek, a mint a törvény is mondja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 35, 'Hogyha pedig tanulni akarnak valamit, kérdezzék meg otthon az ő férjüket; mert éktelen dolog asszonynak szólni a gyülekezetben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 36, 'Avagy ti tőletek származott-é az Isten beszéde, avagy csak hozzátok jutott el?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 37, 'Ha valaki azt hiszi, hogy ő próféta, vagy lelki ajándék részese, vegye eszébe, hogy a miket néktek írok, az Úr rendeletei azok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 38, 'A ki pedig tudatlan, legyen tudatlan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 39, 'Azért atyámfiai törekedjetek prófétálásra, és a nyelveken szólást se tiltsátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 40, 'Mindenek ékesen és jó renddel legyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, 'Eszetekbe juttatom továbbá, atyámfiai, az evangyéliomot, melyet hirdettem néktek, melyet be is vettetek, melyben állotok is,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, 'A mely által üdvözültök is, ha megtartjátok, a minémű beszéddel hirdettem néktek, hacsak nem hiába lettetek hívőkké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, 'Mert azt adtam előtökbe főképen, a mit én is úgy vettem, hogy a Krisztus meghalt a mi bűneinkért az írások szerint;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, 'És hogy eltemettetett; és hogy feltámadott a harmadik napon az írások szerint;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, 'És hogy megjelent Kéfásnak; azután a tizenkettőnek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, 'Azután megjelent több mint ötszáz atyafinak egyszerre, kik közül a legtöbben mind máig élnek, némelyek azonban el is aludtak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, 'Azután megjelent Jakabnak; azután mind az apostoloknak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, 'Legutolszor pedig mindenek között, mint egy idétlennek, nékem is megjelent.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, 'Mert én vagyok a legkisebb az apostolok között, ki nem vagyok méltó, hogy apostolnak neveztessem, mert háborgattam az Istennek anyaszentegyházát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 10, 'De Isten kegyelme által vagyok, a mi vagyok; és az ő hozzám való kegyelme nem lőn hiábavaló; sőt többet munkálkodtam, mint azok mindnyájan de nem én, hanem az Istennek velem való kegyelme.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 11, 'Akár én azért, akár azok, így prédikálunk, és így lettetek ti hívőkké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 12, 'Ha azért Krisztusról hirdettetik, hogy a halottak közül feltámadott, mimódon mondják némelyek ti köztetek, hogy nincsen halottak feltámadása?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 13, 'Mert ha nincsen halottak feltámadása, akkor Krisztus sem támadott fel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 14, 'Ha pedig Krisztus fel nem támadott, akkor hiábavaló a mi prédikálásunk, de hiábavaló a ti hitetek is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 15, 'Sőt az Isten hamis bizonyságtevőinek is találtatunk, mivelhogy az Isten felől bizonyságot tettünk, hogy feltámasztotta a Krisztust; a kit nem támasztott fel, ha csakugyan nem támadnak fel a halottak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 16, 'Mert ha a halottak fel nem támadnak, a Krisztus sem támadott fel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 17, 'Ha pedig a Krisztus fel nem támadott, hiábavaló a ti hitetek; még bűneitekben vagytok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 18, 'A kik a Krisztusban elaludtak, azok is elvesztek tehát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 19, 'Ha csak ebben az életben reménykedünk a Krisztusban, minden embernél nyomorultabbak vagyunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 20, 'Ámde Krisztus feltámadott a halottak közül, zsengéjök lőn azoknak, kik elaludtak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 21, 'Miután ugyanis ember által van a halál, szintén ember által van a halottak feltámadása is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 22, 'Mert a miképen Ádámban mindnyájan meghalnak, azonképen a Krisztusban is mindnyájan megeleveníttetnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 23, 'Mindenki pedig a maga rendje szerint. Első zsenge a Krisztus; azután a kik a Krisztuséi, az ő eljövetelekor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 24, 'Aztán a vég, mikor átadja az országot az Istennek és Atyának; a mikor eltöröl minden birodalmat és minden hatalmat és erőt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 25, 'Mert addig kell néki uralkodnia, mígnem ellenségeit mind lábai alá veti.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 26, 'Mint utolsó ellenség töröltetik el a halál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 27, 'Mert mindent az ő lábai alá vetett. Mikor pedig azt mondja, hogy minden alája van vetve, nyilvánvaló, hogy azon kívül, a ki neki mindent alávetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 28, 'Mikor pedig minden alája vettetett, akkor maga a Fiú is alávettetik annak, a ki neki mindent alávetett, hogy az Isten legyen minden mindenben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 29, 'Különben mit cselekesznek azok, a kik a halottakért keresztelkednek meg, a halottak teljességgel nem támadnak fel? Miért is keresztelkednek meg a halottakért?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 30, 'Mi is miért veszélyeztetjük magunkat minden pillanatban?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 31, 'Naponként halál révén állok. A veletek való dicsekedésre mondom, mely van nékem a Krisztus Jézusban a mi Urunkban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 32, 'Ha csak emberi módon viaskodtam Efézusban a fenevadakkal, mi a hasznom abból, ha a halottak fel nem támadnak? Együnk és igyunk, holnap úgyis meghalunk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 33, 'Ne tévelyegjetek. Jó erkölcsöt megrontanak gonosz társaságok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 34, 'Serkenjetek fel igazán és ne vétkezzetek; mert némelyek nem ismerik Istent; megszégyenítéstekre mondom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 35, 'De mondhatná valaki: Mi módon támadnak fel a halottak? és minémű testtel jönnek ki?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 36, 'Balgatag! a mit te vetsz, nem elevenedik meg, hanemha megrothadánd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 37, 'És abban, a mit elvetsz, nem azt a testet veted el, a mely majd kikél, hanem puszta magot, talán búzáét, vagy más egyébét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 38, 'Az Isten pedig testet ád annak, a mint akarta, és pedig mindenféle magnak az ő saját testét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 39, 'Nem minden test azon egy test, hanem más az embereknek teste, más a barmoknak teste, más a halaké, más a madaraké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 40, 'És vannak mennyei testek és földi testek; de más a mennyeiek dicsősége, más a földieké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 41, 'Más a napnak dicsősége és más a holdnak dicsősége és más a csillagok dicsősége; mert csillag a csillagtól különbözik dicsőségre nézve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 42, 'Épenígy a halottak feltámadása is. Elvettetik romlandóságban, feltámasztatik romolhatatlanságban;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 43, 'Elvettetik gyalázatosságban, feltámasztatik dicsőségben; elvettetik erőtelenségben, feltámasztatik erőben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 44, 'Elvettetik érzéki test, feltámasztatik lelki test. Van érzéki test, és van lelki test is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 45, 'Így is van megírva: Lőn az első ember, Ádám, élő lélekké; az utolsó Ádám megelevenítő szellemmé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 46, 'De nem a lelki az első, hanem az érzéki, azután a lelki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 47, 'Az első ember földből való, földi; a második ember, az Úr, mennyből való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 48, 'A milyen ama földi, olyanok a földiek is; és a milyen ama mennyei, olyanok a mennyeiek is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 49, 'És a miképen hordtuk a földinek ábrázatját, hordani fogjuk a mennyeinek ábrázatját is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 50, 'Azt pedig állítom atyámfiai, hogy test és vér nem örökölheti Isten országát, sem a romlandóság nem örökli a romolhatatlanságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 51, 'Ímé titkot mondok néktek. Mindnyájan ugyan nem aluszunk el, de mindnyájan elváltozunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 52, 'Nagy hirtelen, egy szempillantásban, az utolsó trombitaszóra; mert trombita fog szólni, és a halottak feltámadnak romolhatatlanságban, és mi elváltozunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 53, 'Mert szükség, hogy ez a romlandó test romolhatatlanságot öltsön magára, és e halandó test halhatatlanságot öltsön magára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 54, 'Mikor pedig ez a romlandó test romolhatatlanságba öltözik, és e halandó halhatatlanságba öltözik, akkor beteljesül amaz ige, mely meg vagyon írva: Elnyeletett a halál diadalra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 55, 'Halál! hol a te fullánkod? Pokol! hol a te diadalmad?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 56, 'A halál fullánkja pedig a bűn; a bűn ereje pedig a törvény.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 57, 'De hála az Istennek, a ki a diadalmat adja nékünk a mi Urunk Jézus Krisztus által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 58, 'Azért szerelmes atyámfiai erősen álljatok, mozdíthatatlanul, buzgólkodván az Úrnak dolgában mindenkor, tudván, hogy a ti munkátok nem hiábavaló az Úrban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 1, 'Ami a szentek számára való alamizsnát illeti, a miképen Galáczia gyülekezeteinek rendeltem, ti is azonképen cselekedjetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 2, 'A hétnek első napján mindenitek tegye félre magánál, a mit sikerül összegyűjtenie, hogy ne akkor történjék a gyűjtés, a mikor odamegyek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 3, 'Mikor pedig megérkezem, a kiket javaltok leveleitek által, azokat küldöm el, hogy elvigyék Jeruzsálembe a ti ajándékotokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 4, 'Ha pedig méltó lesz, hogy én is elmenjek, velem együtt jönnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 5, 'Elmegyek pedig ti hozzátok, mikor Macedónián általmenéndek: mert Macedónián általmegyek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 6, 'Nálatok azonban talán megmaradok, vagy ott is telelek, hogy ti kísérjetek el, a hová menéndek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 7, 'Mert nem akarlak titeket épen csak átmenet közben látni, de reménylem, hogy valami ideig nálatok maradok, ha az Úr engedi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 8, 'Efézusban pedig pünkösdig maradok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 9, 'Mert nagy kapu nyílott meg előttem és hasznos, az ellenség is sok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 10, 'Hogyha pedig megérkezik Timótheus, meglássátok, hogy bátorságos maradása legyen nálatok; mert az Úrnak dolgát cselekszi, mint én is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 11, 'Senki azért őt meg ne vesse: hanem bocsássátok el őt békességgel, hogy hozzám jöhessen; mert várom őt az atyafiakkal együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 12, 'A mi pedig Apollós atyafit illeti, igen kértem őt, hogy menjen el hozzátok az atyafiakkal együtt: de semmiképpen sem volt kedve, hogy most elmenjen; de majd elmegy, mihelyt jó alkalmatossága lészen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 13, 'Vigyázzatok, álljatok meg a hitben, legyetek férfiak, legyetek erősek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 14, 'Minden dolgotok szeretetben menjen végbe!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 15, 'Intelek pedig titeket, atyámfiai, hiszen tudjátok, hogy Stefanásnak háznépe Akhája zsengéje, és ők a szenteknek való szolgálatra adták magukat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 16, 'Hogy ti is engedelmeskedjetek az ilyeneknek, és mindenkinek, a ki velök szolgál és fárad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 17, 'Örvendezek pedig a Stefanás, Fortunátus és Akhaikus eljövetelének; mert a bennetek való fogyatkozást ezek betöltötték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 18, 'Mert megnyugtatták az én lelkemet és a tiéteket is. Megbecsüljétek azért az ilyeneket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 19, 'Köszöntenek titeket Ázsia gyülekezetei; köszöntenek titeket az Úrban felette igen Akvila és Prisczilla, a házuknál levő gyülekezettel egybe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 20, 'Köszöntenek titeket az atyafiak mindnyájan. Köszöntsétek egymást szent csókkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 21, 'A köszöntés a saját kezemmel, a Páléval.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 22, 'Ha valaki nem szereti az Úr Jézus Krisztust, legyen átkozott! Maran atha.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 23, 'Az Úr Jézus Krisztusnak kegyelme veletek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 24, 'Az én szeretetem mindnyájatokkal a Jézus Krisztusban! Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Pál, Jézus Krisztus apostola az Isten akaratjából, és Timótheus az atyafi, az Isten gyülekezetének, a mely Korinthusban van, mindama szentekkel egybe, a kik egész Akhájában vannak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'Kegyelem néktek és békesség Istentől a mi Atyánktól és az Úr Jézus Krisztustól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Áldott az Isten és a mi Urunk Jézus Krisztusnak Atyja, az irgalmasságnak atyja és minden vígasztalásnak Istene;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'A ki megvígasztal minket minden nyomorúságunkban, hogy mi is megvígasztalhassunk bármely nyomorúságba esteket azzal a vígasztalással, a mellyel Isten vígasztal minket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'Mert a mint bőséggel kijutott nékünk a Krisztus szenvedéseiből, úgy bőséges a mi vígasztalásunk is Krisztus által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'De akár nyomorgattatunk, a ti vígasztalástokért és üdvösségtekért van az, mely hathatós ugyanazon szenvedések elviselésére, a melyeket mi is szenvedünk; akár megvígasztaltatunk a ti vígasztalástokért és üdvösségtekért van az. És a mi reménységünk erős felőletek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'Tudván, hogy a miképen társaink vagytok a szenvedésben, azonképen a vígasztalásban is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'Mert nem akarjuk, hogy ne tudjatok atyámfiai a mi nyomorúságunk felől, a mely Ázsiában esett rajtunk, hogy felette igen, erőnk felett megterheltettünk, úgy hogy életünk felől is kétségben valánk:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'Sőt magunk is halálra szántuk magunkat, hogy ne bizakodnánk mi magunkban, hanem Istenben, a ki feltámasztja a holtakat:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'A ki ilyen nagy halálból megszabadított és szabadít minket: a kiben reménykedünk, hogy ezután is meg fog szabadítani;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'Velünk együtt munkálkodván ti is az érettünk való könyörgésben, hogy a sokak által nékünk adatott kegyelmi ajándék sokak által háláltassék meg mi érettünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'Mert a mi dicsekedésünk ez, lelkiismeretünk bizonysága, hogy isteni őszinteséggel és tisztasággal, nem testi bölcseséggel, hanem Isten kegyelmével forgolódtunk a világon, kiváltképen pedig ti köztetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'Mert nem egyebet írunk néktek, hanem a mit olvastok, vagy el is ismertek, sőt reménylem, hogy el is fogtok ismerni mindvégig;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, 'A minthogy némi részben el is ismertétek rólunk, hogy dicsekvéstek vagyunk, a miképen ti is nékünk az Úr Jézus napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'És ezzel a bizodalommal akartam előbb hozzátok menni, hogy másodízben nyerjetek kegyelmet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'És köztetek általmenni Macedóniába, és Macedóniából ismét hozzátok térni vissza, és tőletek elkísértetni Júdeába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'Hát ezt akarva, vajjon könnyelműen cselekedtem-é? vagy a mit akarok, test szerint akarom-é, hogy nálam az igen igen, és a nem nem legyen?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'De hű az Isten, hogy a mi beszédünk hozzátok nem volt igen és nem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'Mert az Isten Fia Jézus Krisztus, a kit köztetek mi hirdettünk, én és Silvánus és Timótheus, nem volt igen és nem, hanem az igen lett ő benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'Mert Istennek valamennyi igérete ő benne lett igenné és ő benne lett Ámenné az Isten dicsőségére mi általunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'A ki pedig minket ti veletek egybe Krisztusban megerősít és megken minket, az Isten az;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'A ki el is pecsételt minket, és a léleknek zálogát adta a mi szíveinkbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, 'Én pedig az Istent hívom bizonyságul az én lelkemre, hogy titeket kímélve nem mentem el eddig Korinthusba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, 'Nem hogy uralkodnánk a ti hiteteken, hanem munkatársai vagyunk a ti örömeteknek; mert hitben állotok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'Azt tettem pedig fel magamban, hogy nem megyek közétek ismét szomorúsággal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'Mert ha én megszomorítlak titeket, ugyan ki az, a ki megvídámít engem, hanemha a kit én megszomorítok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'És azért írtam néktek éppen azt, hogy mikor oda megyek, meg ne szomoríttassam azok miatt, a kiknek örülnöm kellene; meg lévén győződve mindenitek felől, hogy az én örömöm mindnyájatoké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'Mert sok szorongattatás és szívbeli háborgás között írtam néktek sok könyhullatással, nem hogy megszomoríttassatok, hanem hogy megismerjétek azt a szeretetet, a mellyel kiváltképen irántatok viseltetem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'Ha pedig valaki megszomorított, nem engem szomorított meg, hanem részben, hogy azt ne terheljem, titeket mindnyájatokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'Elég az ilyennek a többség részéről való ilyen megbüntetése:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'Annyira, hogy éppen ellenkezőleg ti inkább bocsássatok meg néki és vígasztaljátok, hogy valamiképen a felettébb való bánat meg ne eméssze az ilyet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'Azért kérlek titeket, hogy tanusítsatok iránta szeretetet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, 'Mert azért írtam is, hogy bizonyosan megtudjam felőletek, ha mindenben engedelmesek vagytok-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'A kinek pedig megbocsáttok valamit, én is: mert ha én is megbocsátottam valamit, ha valakinek megbocsátottam, ti érettetek cselekedtem Krisztus színe előtt; hogy meg ne csaljon minket a Sátán:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, 'Mert jól ismerjük az ő szándékait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, 'Mikor pedig Troásba mentem a Krisztus evangyélioma ügyében és kapu nyittatott nékem az Úrban, nem volt lelkemnek nyugodalma, mivelhogy nem találtam Titust, az én atyámfiát;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, 'Hanem elbúcsúzván tőlük, elmentem Macedóniába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'Hála pedig az Istennek, a ki mindenkor diadalra vezet minket a Krisztusban, és az ő ismeretének illatját minden helyen megjelenti mi általunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'Mert Krisztus jó illatja vagyunk Istennek, mind az üdvözülők, mind az elkárhozók között;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'Ezeknek halál illatja halálra; amazoknak pedig élet illatja életre. És ezekre kicsoda alkalmatos?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, 'Mert mi nem olyanok vagyunk, mint sokan, a kik meghamisítják az Isten ígéjét; hanem tisztán, sőt szinte Istenből szólunk az Isten előtt a Krisztusban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'Elkezdjük-é ismét ajánlgatni magunkat? Vagy talán szükségünk van, mint némelyeknek, ajánló levelekre hozzátok, avagy tőletek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, 'A mi levelünk ti vagytok, beírva a mi szívünkbe, a melyet ismer és olvas minden ember;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'A kik felől nyilvánvaló, hogy Krisztusnak a mi szolgálatunk által szerzett levele vagytok, nem tentával, hanem az élő Isten Lelkével írva; nem kőtáblákra, hanem a szívnek hústábláira.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'Ilyen bizodalmunk pedig Isten iránt a Krisztus által van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'Nem mintha magunktól volnánk alkalmatosak valamit gondolni, úgy mint magunkból; ellenkezőleg a mi alkalmatos voltunk az Istentől van:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'A ki alkalmatosokká tett minket arra, hogy új szövetség szolgái legyünk, nem betűé, hanem léleké; mert a betű megöl, a lélek pedig megelevenít.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, 'Ha pedig a halálnak betűkkel kövekbe vésett szolgálata dicsőséges vala, úgyhogy Izráel fiai nem is nézhettek Mózes orczájára arczának elmúló dicsősége miatt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'Hogyne volna még inkább dicsőséges a léleknek szolgálata?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'Mert ha a kárhoztatás szolgálata dicsőséges, mennyivel inkább dicsőséges az igazság szolgálata?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'Sőt a dicsőített nem is dicsőséges ebben a részben az őt meghaladó dicsőség miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'Mert ha dicsőséges az elmulandó, sokkal inkább dicsőséges, a mi megmarad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, 'Azért ilyen reménységben nagy nyiltsággal szólunk;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, 'És nem, miként Mózes, a ki leplet borított az orczájára, hogy ne lássák Izráel fiai az elmulandónak végét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, 'De megtompultak az ő elméik. Mert ugyanaz a lepel mind e mai napig ott van az ó szövetség olvasásánál felfedetlenül, mivelhogy a Krisztusban tűnik el;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, 'Sőt mind máig, a mikor csak olvassák Mózest, lepel borul az ő szívökre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, 'Mikor pedig megtér az Úrhoz, lehull a lepel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, 'Az Úr pedig a Lélek; és a hol az Úrnak Lelke, ott a szabadság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 18, 'Mi pedig az Úrnak dicsőségét mindnyájan fedetlen arczczal szemlélvén, ugyanazon ábrázatra elváltozunk, dicsőségről dicsőségre, úgy mint az Úrnak Lelkétől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'Annakokáért, mivelhogy ilyen szolgálatban vagyunk, a mint a kegyelmet nyertük, nem csüggedünk el;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'Hanem lemondtunk a szégyen takargatásáról, mint a kik nem járunk ravaszságban, és nem is hamisítjuk meg az Isten ígéjét, de a nyilvánvaló igazsággal kelletjük magunkat minden ember lelkiismeretének az Isten előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'Ha mégis leplezett a mi evangyéliomunk, azoknak leplezett, a kik elvesznek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'A kikben e világ Istene megvakította a hitetlenek elméit, hogy ne lássák a Krisztus dicsőséges evangyéliomának világosságát, a ki az Isten képe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'Mert nem magunkat prédikáljuk, hanem az Úr Jézus Krisztust; magunkat pedig, mint a ti szolgáitokat, a Jézusért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'Mert az Isten, a ki szólt: setétségből világosság ragyogjon, ő gyújtott világosságot a mi szívünkben az Isten dicsősége ismeretének a Jézus Krisztus arczán való világoltatása végett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'Ez a kincsünk pedig cserépedényekben van, hogy amaz erőnek nagy volta Istené legyen, és nem magunktól való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'Mindenütt nyomorgattatunk, de meg nem szoríttatunk; kétségeskedünk, de nem esünk kétségbe;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'Üldöztetünk, de el nem hagyatunk; tiportatunk, de el nem veszünk;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'Mindenkor testünkben hordozzuk az Úr Jézus halálát, hogy a Jézusnak élete is látható legyen a mi testünkben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'Mert mi, a kik élünk, mindenkor halálra adatunk a Jézusért, hogy a Jézus élete is látható legyen a mi halandó testünkben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'Azért a halál mi bennünk munkálkodik, az élet pedig ti bennetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, 'Mivelhogy pedig a hitnek mi bennünk is ugyanaz a lelke van meg, a mint írva van: Hittem és azért szóltam; hiszünk mi is, és azért szólunk;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'Tudván, hogy a ki feltámasztotta az Úr Jézust, Jézus által minket is feltámaszt, és veletek együtt előállít.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, 'Mert minden ti érettetek van, hogy a kegyelem sokasodva sokak által a hálaadást bőségessé tegye az Isten dicsőségére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'Azért nem csüggedünk; sőt ha a mi külső emberünk megromol is, a belső mindazáltal napról-napra újul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'Mert a mi pillanatnyi könnyű szenvedésünk igen-igen nagy örök dicsőséget szerez nékünk;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, 'Mivelhogy nem a láthatókra nézünk, hanem a láthatatlanokra; mert a láthatók ideig valók, a láthatatlanok pedig örökkévalók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'Mert tudjuk, hogy ha e mi földi sátorházunk elbomol, épületünk van Istentől, nem kézzel csinált, örökké való házunk a mennyben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'Azért is sóhajtozunk ebben, óhajtván felöltözni erre a mi mennyei hajlékunkat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, 'Ha ugyan felöltözötten is mezíteleneknek nem találtatunk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'Mert a kik e sátorban vagyunk is, sóhajtozunk megterheltetvén; mivelhogy nem kívánunk levetkőztetni, hanem felöltöztetni, hogy a mi halandó, elnyelje azt az élet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'A ki pedig minket erre elkészített, az Isten az, a ki a Lélek zálogát is adta minékünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'Azért mivelhogy mindenkor bízunk, és tudjuk, hogy e testben lakván, távol vagyunk az Úrtól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, '(Mert hitben járunk, nem látásban);');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'Bizodalmunk pedig van, azért inkább szeretnénk kiköltözni e testből, és elköltözni az Úrhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, 'Azért igyekezünk is, hogy akár itt lakunk, akár elköltözünk, néki kedvesek legyünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'Mert nékünk mindnyájunknak meg kell jelennünk a Krisztus ítélőszéke előtt, hogy kiki megjutalmaztassék a szerint, a miket e testben cselekedett, vagy jót, vagy gonoszt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, 'Ismervén tehát az Úrnak félelmét, embereket térítünk, Isten előtt pedig nyilván vagyunk; reménylem azonban, hogy a ti lelkiesméretetek előtt is nyilván vagyunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, 'Mert nem ajánljuk ismét magunkat néktek, hanem alkalmat adunk ti néktek a velünk való dicsekedésre, hogy legyen mit felelnetek a színből és nem szívből dicsekedőknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, 'Ha azért bolondok vagyunk, Istenért; ha eszesek vagyunk, érettetek van az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'Mert a Krisztusnak szerelme szorongat minket,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'Úgy vélekedvén, hogy ha egy meghalt mindenkiért, tehát mindazok meghaltak; és azért halt meg mindenkiért, hogy a kik élnek, ezután ne magoknak éljenek, hanem annak, a ki érettök meghalt és feltámasztatott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'Azért mi ezentúl senkit sem ismerünk test szerint; sőt ha ismertük is Krisztust test szerint, de már többé nem ismerjük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, 'Azért ha valaki Krisztusban van, új teremtés az; a régiek elmúltak, ímé, újjá lett minden.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'Mindez pedig Istentől van, a ki minket magával megbékéltetett a Jézus Krisztus által, és a ki nékünk adta a békéltetés szolgálatát;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, 'Minthogy az Isten volt az, a ki Krisztusban megbékéltette magával a világot, nem tulajdonítván nékik az ő bűneiket, és reánk bízta a békéltetésnek ígéjét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, 'Krisztusért járván tehát követségben, mintha Isten kérne mi általunk: Krisztusért kérünk, béküljetek meg az Istennel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, 'Mert azt, a ki bűnt nem ismert, bűnné tette értünk, hogy mi Isten igazsága legyünk ő benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, 'Mint együttmunkálkodók intünk is, hogy hiába ne vettétek légyen az Isten kegyelmét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, 'Mert ő mondja: Kellemetes időben meghallgattalak, és az üdvösség napján megsegítettelek. Ímé itt a kellemetes idő, ímé itt az üdvösség napja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, 'Senkit semmiben meg ne botránkoztassunk, hogy a szolgálatunk ne szidalmaztassék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, 'Hanem ajánljuk magunkat mindenben, mint Isten szolgái; sok tűrésben, nyomorúságban, szükségben, szorongattatásban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, 'Vereségben, tömlöczben, háborúságban, küzködésben, virrasztásban, bőjtölésben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 'Tisztaságban, tudományban, hosszútűrésben, szívességben, Szent Lélekben, tettetés nélkül való szeretetben,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, 'Igazmondásban, Isten erejében; az igazságnak jobb és bal felől való fegyvereivel;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 'Dicsőség és gyalázat által, rossz és jó hír által; mint hitetők, és igazak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, 'Mint ismeretlenek, és mégis ismeretesek; mint megholtak, és ím élők; mint ostorozottak, és meg nem ölöttek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, 'Mint bánkódók, noha mindig örvendezők; mint szegények, de sokakat gazdagítók; mint semmi nélkül valók, és mindennel bírók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, 'A mi szánk megnyílt ti néktek, korinthusiak, a mi szívünk kitárult.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, 'Nem mi bennünk vagytok szorosságban, hanem szorosságban vagytok a ti szívetekben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, 'Viszonzásul (mint gyermekeimnek szólok) tárjátok ki ti is szíveteket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, 'Ne legyetek hitetlenekkel felemás igában; mert mi szövetsége van igazságnak és hamisságnak? vagy mi közössége a világosságnak a sötétséggel?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, 'És mi egyezsége Krisztusnak Béliállal? vagy mi köze hívőnek hitetlenhez?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, 'Vagy mi egyezése Isten templomának bálványokkal? Mert ti az élő Istennek temploma vagytok, a mint az Isten mondotta: Lakozom bennök és közöttük járok; és leszek nékik Istenök, és ők én népem lesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, 'Annakokáért menjetek ki közülök, és szakadjatok el, azt mondja az Úr, és tisztátalant ne illessetek; és én magamhoz fogadlak titeket,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, 'És leszek néktek Atyátok, és ti lesztek fiaimmá, és leányaimmá, azt mondja a mindenható Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, 'Mivelhogy azért ilyen ígéreteink vannak, szeretteim, tisztítsuk meg magunkat minden testi és lelki tisztátalanságtól, Isten félelmében vivén véghez a mi megszentelésünket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, 'Fogadjatok be minket; senkit meg nem bántottunk, senkit meg nem rontottunk, senkit meg nem csaltunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'Nem vádképen mondom; hisz előbb mondottam, hogy szívünkben vagytok, hogy együtt haljunk, együtt éljünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, 'Nagy az én bizodalmam hozzátok, nagy az én dicsekvésem felőletek; telve vagyok vígasztalódással, felettébb való az én örömem minden mi nyomorúságunk mellett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'Mert mikor Macedóniába jöttünk, sem volt semmi nyugodalma a mi testünknek, sőt mindenképen nyomorogtunk; kívül harcz, belől félelem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, 'De az Isten, a megalázottak vígasztalója, minket is megvígasztalt Titus megjöttével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, 'Sőt nem megjöttével csupán, hanem azzal a vígasztalással is, a melylyel ti vígasztaltátok meg, hírül hozván nékünk a ti kivánkozástokat, a ti kesergésteket, a ti hozzám való ragaszkodástokat; úgyhogy én mégjobban örvendeztem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'Hát ha megszomorítottalak is titeket azzal a levéllel, nem bánom, noha bántam; mert látom, hogy az a levél, ha ideig-óráig is, megszomorított titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, 'Most örülök, nem azért, hogy megszomorodtatok, hanem hogy megtérésre szomorodtatok meg. Mert Isten szerint szomorodtatok meg, hogy miattunk semmiben kárt ne valljatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, 'Mert az Isten szerint való szomorúság üdvösségre való megbánhatatlan megtérést szerez; a világ szerint való szomorúság pedig halált szerez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, 'Mert ímé ez a ti Isten szerint való megszomorodástok milyen nagy buzgóságot keltett ti bennetek, sőt védekezést, sőt bosszankodást, sőt félelmet, sőt kívánkozást, sőt buzgóságot, sőt bosszúállást. Mindenképen bebizonyítottátok, hogy tiszták vagytok e dologban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, 'Ha tehát írtam is néktek, nem a sértő miatt, sem a sértett miatt; hanem hogy nyilvánvaló legyen nálatok a mi irántatok való buzgóságunk Isten előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, 'Annakokáért megvígasztalódtunk a ti vígasztalástokon; de sokkal inkább örültünk a Titus örömén, hogy az ő lelkét ti mindnyájan megnyugtattátok:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, 'Mert ha dicsekedtem valamit néki felőletek, nem maradtam szégyenben; de a mint ti néktek mindent igazán szólottam, azonképen a mi Titus előtt való dicsekvésünk is igazsággá lett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, 'És ő még jobb szívvel van irántatok, visszaemlékezvén mindnyájatoknak engedelmességére, hogy félelemmel és rettegéssel fogadtátok őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, 'Örülök, hogy mindenképen bízhatom bennetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, 'Tudtotokra adjuk pedig, atyámfiai, Istennek azt a kegyelmét, a melyet Macedónia gyülekezeteivel közlött.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, 'Hogy a nyomorúság sok próbái közt is bőséges az ő örömük és igen nagy szegénységük jószívűségük gazdagságává növekedett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, 'Mert, bizonyság vagyok rá, erejük szerint, sőt erejük felett is adakoznak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, 'Sok könyörgéssel kérvén minket, hogy a szentek iránt való szolgálat jótéteményébe és közösségébe fogadjuk be őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, 'És nem a miképen reméltük, hanem önmagukat adták először az Úrnak, és nekünk is az Isten akaratjából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, 'Hogy kérnünk kellett Titust, hogy a miképen elkezdette, azonképen végezze is be nálatok ezt a jótéteményt is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, 'Azért, miképen mindenben bővölködtök, hitben, beszédben, ismeretben és minden buzgóságban és hozzánk való szeretetben, úgy e jótéteményben is bővölködjetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, 'Nem parancsképen mondom, hanem hogy a mások buzgósága által a ti szeretetetek valódiságát is kipróbáljam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, 'Mert ismeritek a mi Urunk Jézus Krisztusnak jótéteményét, hogy gazdag lévén, szegénnyé lett érettetek, hogy ti az ő szegénysége által meggazdagodjatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, 'Tanácsot is adok e dologban; mert hasznos az néktek, a kik nemcsak a cselekvést, hanem az akarást is elkezdtétek tavaly óta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, 'Most hát a cselekvést is vigyétek végbe; hogy a miképen az akarás készsége, azonképen a végrehajtás is ahhoz képest legyen, a mitek van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, 'Mert ha a készség megvan, a szerint kedves az, a mije kinek-kinek van, és nem a szerint, a mije nincs.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, 'Mert nem úgy, hogy másoknak könnyebbségük, néktek pedig nyomorúságtok legyen, hanem egyenlőség szerint; e mostani időben a ti bőségtek pótolja amazoknak fogyatkozását;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, 'Hogy amazoknak bősége is pótolhassa a ti fogyatkozástokat, hogy így egyenlőség legyen;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, 'A mint megvan írva: a ki sokat szedett, nem volt többje; és a ki keveset, nem volt kevesebbje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, 'Hála pedig az Istennek, ki ugyanazt a buzgóságot oltotta értetek a Titus szívébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, 'Mivelhogy intésünket ugyan elfogadta, de nagy buzgóságában önként ment hozzátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, 'Elküldöttük pedig vele együtt amaz atyafit is, a ki az összes gyülekezetekben dícséretes az evangyéliomért;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, 'Nemcsak pedig, hanem a gyülekezetek útitársunknak is megválaszták ebben a jó ügyben, a melyet mi szolgálunk magának az Úrnak dicsőségére és a ti készségetekre;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, 'Óvakodván, hogy senki se ócsárolhasson minket a mi szolgálatunk által való bőséges jótétemény miatt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, 'Mert gondunk van a tisztességre nemcsak az Úr előtt, hanem az emberek előtt is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, 'Sőt elküldöttük velök a mi atyánkfiát is, a kinek buzgó voltát sok dologban sokszor kipróbáltuk, most pedig még sokkal buzgóbb, irántatok való nagy bizodalmánál fogva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, 'Akár Titusról van szó, ő az én társam és ti köztetek segítségem; akár a mi atyánkfiai felől, ők a gyülekezetek követei, Krisztus dicsősége:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 24, 'Adjátok azért szereteteteknek és felőletek való dicsekvésünknek, bizonyságát irántuk a gyülekezetek előtt is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, 'A szentek iránt való szolgálatról felesleges is néktek írnom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, 'Hiszen ismerem a ti készségteket a melylyel dicsekszem felőletek a macedónoknak, hogy Akhája kész a mult esztendő óta; és a ti buzgóságtok, sokakat magával ragadt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, 'Mindamellett elküldöttem az atyafiakat, hogy a mi felőletek való dicsekedésünk ebben a részben hiábavaló ne legyen; hogy, a mint mondám, készen legyetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, 'Hogy aztán, ha a macedónok velem együtt odajutnak és titeket készületlenül találnak, valamiképen szégyent ne valljunk mi, hogy ne mondjam ti, ebben a dologban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, 'Szükségesnek véltem azért utasítani az atyafiakat, hogy előre menjenek el hozzátok, és készítsék el előre a ti előre megígért adományotokat, hogy az úgy legyen készen, mint adomány, és nem mint ragadomány.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, 'Azt mondom pedig: A ki szűken vet, szűken is arat; és a ki bőven vet, bőven is arat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, 'Kiki a mint eltökélte szívében, nem szomorúságból, vagy kénytelenségből; mert a jókedvű adakozót szereti az Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, 'Az Isten pedig hatalmas arra, hogy rátok áraszsza minden kegyelmét; hogy mindenben, mindenkor teljes elégségtek lévén, minden jótéteményre bőségben legyetek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, 'A mint meg van írva: Szórt, adott a szegényeknek; az ő igazsága örökké megmarad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, 'A ki pedig magot ád a magvetőnek és kenyeret eleségül, ád és megsokasítja a ti vetésteket és megnöveli a ti igazságtoknak gyümölcsét,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, 'Hogy mindenben meggazdagodjatok a teljes jószívűségre, a mely általunk hálaadást szerez az Istennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, 'Mert e tisztnek szolgálata nemcsak a szenteknek szükségét elégíti ki, hanem sok hálaadással bőséges az Isten előtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, 'A mennyiben e szolgálatnak próbája által dicsőítik az Istent a ti Krisztus evangyéliomát valló engedelmességtekért, és a ti hozzájuk és mindenekhez való adakozó jószívűségtekért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, 'Mikor érettetek könyörögve ők is vágyakoznak utánatok az Istennek rajtatok való bőséges kegyelme miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, 'Az Istennek pedig legyen hála az ő kimondhatatlan ajándékáért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, 'Magam pedig, én Pál, kérlek titeket a Krisztus szelídségére és engedelmességére, a ki szemtől szemben ugyan alázatos vagyok közöttetek, de távol bátor vagyok irántatok;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, 'Kérlek pedig, hogy a mikor jelen leszek, ne kelljen bátornak lennem ama bizodalomnál fogva, a melylyel úgy gondolom bátor lehetek némelyekkel szemben, a kik úgy gondolkodnak felőlünk, mintha mi test szerint élnénk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, 'Mert noha testben élünk, de nem test szerint vitézkedünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, 'Mert a mi vitézkedésünk fegyverei nem testiek, hanem erősek az Istennek, erősségek lerontására;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, 'Lerontván okoskodásokat és minden magaslatot, a mely Isten ismerete ellen emeltetett, és foglyul ejtvén minden gondolatot, hogy engedelmeskedjék a Krisztusnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, 'És készen állván megbüntetni minden engedetlenséget, mihelyst teljessé lesz a ti engedelmességtek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, 'A szem előtt valókra néztek? Ha valaki azt hiszi magáról, hogy ő a Krisztusé, viszont azt is gondolja meg önmagában, hogy a mint ő maga a Krisztusé, azonképen mi is a Krisztuséi vagyunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, 'Mert ha még egy kissé felettébb dicsekedem is a mi hatalmunkkal, a melyet az Úr a ti építéstekre és nem megrontásotokra adott, én nem vallok szégyent;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, 'Hogy ne láttassam, mintha csak ijesztgetnélek a leveleim által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, 'Mert, úgy mondják, a levelei ugyan súlyosak és kemények; de a maga jelenvolta erőtelen, és beszéde silány.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, 'Gondolja meg azt, a ki ilyen, hogy a milyenek vagyunk távol, a levelek által való beszédben, éppen olyanok leszünk, ha megjelenünk, cselekedetben is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, 'Mert nem merjük magunkat azokhoz számítani, vagy hasonlítani, a kik magukat ajánlják; de azok magukat magukhoz mérvén és magukhoz hasonlítván magukat, nem okosan cselekesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, 'De mi nem dicsekszünk mértéktelenül, hanem ama mérőzsinór mértéke szerint, a melyet Isten adott nékünk mértékül, hogy hozzátok is elérjünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, 'Mert nem feszítjük túl magunkat, mintha nem értünk volna el hozzátok; hiszen hozzátok is eljutottunk a Krisztus evangyéliomával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, 'A kik nem dicsekeszünk mértéktelenül mások munkájával, de reméljük, hogy hitetek megnőttével nagyokká leszünk köztetek a mi mérőzsinórunk szerint bőségesen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, 'Hogy rajtatok túl is hirdessük az evangyéliomot, nem dicsekedvén más mértéke szerint a készszel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, 'A ki pedig dicsekszik, az Úrban dicsekedjék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, 'Mert nem az a kipróbált, a ki magát ajánlja, hanem a kit az Úr ajánl.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, 'Vajha elszenvednétek tőlem egy kevés balgatagságot! Sőt szenvedjetek el engem is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, 'Mert isteni buzgósággal buzgok értetek; hisz eljegyeztelek titeket egy férfiúnak, hogy mint szeplőtlen szűzet állítsalak a Krisztus elé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, 'Félek azonban, hogy a miként a kígyó a maga álnokságával megcsalta Évát, akként a ti gondolataitok is megrontatnak és eltávolodnak a Krisztus iránt való egyenességtől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, 'Mert hogyha az, a ki jő, más Jézust prédikál, a kit nem prédikáltunk, vagy más lelket vesztek, a mit nem vettetek, vagy más evangyéliomot, a mit be nem fogadtatok, szépen eltűrnétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, 'Mert én azt gondolom, hogy semmiben sem vagyok alábbvaló a fő-fő apostoloknál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, 'Ha pedig avatatlan vagyok is a beszédben, de nem az ismeretben; sőt mindenben, mindenképen nyilvánvalókká lettünk előttetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, 'Avagy vétkeztem-é, mikor magamat megaláztam, hogy ti felmagasztaltassatok, hogy ingyen hírdettem néktek az Isten evangyéliomát?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, 'Más gyülekezeteket fosztottam meg, zsoldot vévén, hogy néktek szolgáljak; és mikor nálatok voltam és szűkölködtem, nem voltam terhére senkinek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, 'Mert az én szükségemet kipótolták a Macedóniából jött atyafiak; és rajta voltam és rajta is leszek, hogy semmiben se legyek terhetekre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, 'Krisztus igazsága bennem, hogy én ettől a dicsekvéstől nem esem el Akhája vidékén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, 'Miért? Hogy nem szeretlek titeket? Tudja az Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, 'De a mit cselekszem, cselekedni is fogom, hogy elvágjam az alkalmat az alkalomkeresők elől; hogy a mivel dicsekesznek, olyanoknak találtassanak abban, mint mi is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, 'Mert az ilyenek hamis apostolok, álnok munkások, a kik a Krisztus apostolaivá változtatják át magukat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, 'Nem is csoda; hisz maga a Sátán is átváltoztatja magát világosság angyalává.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, 'Nem nagy dolog azért, ha az ő szolgái is átváltoztatják magokat az igazság szolgáivá; a kiknek végök az ő cselekedeteik szerint lészen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, 'Ismét mondom: ne tartson engem senki esztelennek; de ha mégis, fogadjatok be mint esztelent is, hogy egy kicsit én is dicsekedhessem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, 'A mit mondok, nem az Úr szerint mondom, hanem mintegy esztelenül a dicsekvésnek ezzel a merészségével,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, 'Mivelhogy sokan dicsekesznek test szerint, dicsekeszem én is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, 'Hisz okosak lévén, örömest eltűritek az eszteleneket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, 'Mert eltűritek, ha valaki leigáz titeket, ha valaki felfal, ha valaki megfog, ha valaki felfuvalkodik, ha valaki arczul ver titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, 'Szégyenkezve mondom, mivelhogy mi erőtelenek voltunk; de a miben merész valaki, esztelenül szólok, merész vagyok én is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, 'Héberek ők? Én is. Izráeliták-é? Én is. Ábrahám magva-é? Én is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, 'Krisztus szolgái-é? (balgatagul szólok) én méginkább; több fáradság, több vereség, több börtön, gyakorta való halálos veszedelem által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 24, 'A zsidóktól ötször kaptam negyvenet egy híján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 25, 'Háromszor megostoroztak, egyszer megköveztek, háromszor hajótörést szenvedtem, éjt-napot a mélységben töltöttem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 26, 'Gyakorta való utazásban, veszedelemben folyó vizeken, veszedelemben rablók közt, veszedelemben népem között, veszedelemben pogányok között, veszedelemben városban, veszedelemben pusztában, veszedelemben tengeren, veszedelemben hamis atyafiak közt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 27, 'Fáradságban és nyomorúságban, gyakorta való virrasztásban, éhségben és szomjúságban, gyakorta való bőjtölésben, hidegben és mezítelenségben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 28, 'Mindezeken kívül van az én naponkénti zaklattatásom, az összes gyülekezetek gondja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 29, 'Ki beteg, hogy én is beteg ne volnék? Ki botránkozik meg, hogy én is ne égnék?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 30, 'Ha dicsekednem kell, az én gyengeségemmel dicsekszem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 31, 'Az Isten és a mi Urunk Jézus Krisztusnak Atyja, a ki mindörökké áldott, tudja, hogy nem hazudom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 32, 'Damaskusban Aretás király helytartója őrzette a damaskusiak városát, akarván engem megfogni;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 33, 'És az ablakon át, kosárban bocsátottak le a kőfalon, és megmenekültem kezei közül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, 'A dicsekvés azonban nem használ nékem; rátérek azért a látomásokra és az Úrnak kijelentéseire.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, 'Ismerek egy embert a Krisztusban, a ki tizennégy évvel ezelőtt (ha testben-é, nem tudom; ha testen kívül-é, nem tudom; az Isten tudja) elragadtatott a harmadik égig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, 'És tudom, hogy az az ember, (ha testben-é, ha testen kívül-é, nem tudom; az Isten tudja),');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, 'Elragadtatott a paradicsomba, és hallott kimondhatatlan beszédeket, a melyeket nem szabad embernek kibeszélnie.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, 'Az ilyennel dicsekeszem; magammal pedig nem dicsekeszem, ha csak az én gyengeségeimmel nem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, 'Mert ha dicsekedni akarok, nem leszek esztelen; mert igazságot mondok; de megtürtőztetem magamat, hogy valaki többnek ne tartson, mint a minek lát, vagy a mit hall tőlem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, 'És hogy a kijelentések nagysága miatt el ne bizakodjam, tövis adatott nékem a testembe, a Sátán angyala, hogy gyötörjön engem, hogy felettébb el ne bizakodjam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, 'Ezért háromszor könyörögtem az Úrnak, hogy távozzék el ez tőlem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, 'És ezt mondá nékem: Elég néked az én kegyelmem; mert az én erőm erőtlenség által végeztetik el. Nagy örömest dicsekeszem azért az én erőtelenségeimmel, hogy a Krisztus ereje lakozzék én bennem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, 'Annakokáért gyönyörködöm az erőtlenségekben, bántalmazásokban, nyomorúságokban, üldözésekben és szorongattatásokban Krisztusért; mert a mikor erőtelen vagyok, akkor vagyok erős.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, 'Dicsekedvén, balgataggá lettem; ti kényszerítettetek reá. Mert néktek kellett volna engem ajánlanotok; mert semmiben sem vagyok alábbvaló a fő-fő apostoloknál, noha semmi vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, 'Apostolságomnak jelei megbizonyosodtak közöttetek sok tűrésben, jelekben, csodákban és erőkben is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, 'Mert micsoda az, a miben megkárosodtatok a többi gyülekezetek mellett, hanem ha az, hogy én magam nem voltam néktek terhetekre? Bocsássátok meg nékem ezt az igazságtalanságot!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, 'Ímé harmadízben is kész vagyok hozzátok menni, és nem leszek terhetekre; mert nem azt keresem, a mi a tiétek, hanem titeket magatokat. Mert nem a gyermekek tartoznak kincseket gyűjteni a szülőknek, hanem a szülők a gyermekeknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, 'Én pedig nagy örömest áldozok és esem áldozatul a ti lelketekért; még ha ti, a kiket én igen szeretek, kevésbbé szerettek is engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, 'De ám legyen, hogy én nem voltam terhetekre; hanem álnok lévén ravaszsággal fogtalak meg titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, 'Avagy a kiket hozzátok küldtem, azok közül valamelyik által kifosztottalak-é titeket?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 18, 'Megkértem Titust, és vele együtt elküldtem amaz atyafit; csak nem fosztott ki titeket Titus? Nem egyazon Lélek szerint jártunk-é? Nem azokon a nyomokon-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 19, 'Azt hiszitek megint, hogy előttetek mentegetjük magunkat. Az Isten előtt Krisztusban szólunk; mindezt pedig, szeretteim, a ti épüléstekért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 20, 'Mert félek azon, hogy ha odamegyek, nem talállak majd olyanoknak, a milyeneknek szeretnélek, és engem is olyannak találtok, a milyennek nem szeretnétek; hogy valamiképen versengések, irígységek, indulatoskodások, visszavonások, rágalmazások, fondorkodások, felfuvalkodások, pártoskodások lesznek köztetek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 21, 'Hogy mikor újra odamegyek, megaláz engem az én Istenem ti köztetek, és sokakat megsiratok azok közül, a kik ezelőtt vétkeztek és meg nem tértek a tisztátalanságból, paráznaságból és bujaságból, a mit elkövettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, 'Ezúttal harmadszor megyek hozzátok. Két vagy három tanú vallomása alapján megáll minden dolog.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, 'Előre megmondtam és előre mondom, mint másodszori ottlétemkor, és most is távollétemben írom azoknak, a kik ezelőtt vétkeztek, és a többieknek mind, hogy ha ismét odamegyek, nem leszek kíméletes;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, 'Mert hát az általam szóló Krisztusnak bizonyságát keresitek, a ki irányotokban nem erőtelen, hanem erős ti bennetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, 'Mert noha megfeszíttetett erőtelenségből, mindazáltal él Istennek hatalmából. És noha mi erőtelenek vagyunk benne, de vele együtt élünk majd Isten erejéből ti nálatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, 'Kísértsétek meg magatokat, ha a hitben vagytok-é? magatokat próbáljátok meg. Avagy nem ismeritek-é magatokat, hogy a Jézus Krisztus bennetek van? Kivévén, ha méltatlanok vagytok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, 'De reménylem, hogy megismeritek, hogy mi nem vagyunk méltatlanok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, 'Az Istent pedig kérem, hogy semmi gonoszt ne cselekedjetek; nem hogy mi méltóknak láttassunk, hanem hogy ti a jót cselekedjétek, mi pedig mintegy méltatlanok legyünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, 'Mert semmit sem cselekedhetünk az igazság ellen, hanem csak az igazságért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, 'Mert örvendünk, ha mi erőtelenek vagyunk, ti meg erősek vagytok; ezt pedig kérjük is, a ti tökéletesedésetekért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, 'Azért írom ezeket távollétemben, hogy jelenlétemben ne kelljen keményen viselkednem ama hatalom szerint, a melyet az Úr adott nékem építésre és nem rontásra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, 'Végezetre, atyámfiai, legyetek jó egészségben, épüljetek, vígasztalódjatok, egy értelemben legyetek, békességben éljetek; és a szeretetnek és békességnek Istene lészen veletek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, 'Köszöntsétek egymást szent csókkal. Köszöntenek titeket a szentek mindnyájan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, 'Az Úr Jézus Krisztusnak kegyelme, és az Istennek szeretete, és a Szent Léleknek közössége mindnyájatokkal. Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'Pál, apostol (nem emberektől, sem nem ember által, hanem Jézus Krisztus által és az Atya Isten által, a ki feltámasztotta őt a halálból);');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, 'És a velem levő összes atyafiak, Galátzia gyülekezeteinek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, 'Kegyelem néktek és békesség az Atya Istentől, és a mi Urunk Jézus Krisztustól,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'A ki adta önmagát a mi bűneinkért hogy kiszabadítson minket e jelenvaló gonosz világból, az Istennek és a mi Atyánknak akarata szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'A kinek dicsőség örökkön örökké! Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'Csodálkozom, hogy Attól, a ki titeket Krisztus kegyelme által elhívott, ily hamar más evangyéliomra hajlotok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'Holott nincs más; de némelyek zavarnak titeket, és el akarják ferdíteni a Krisztus evangyéliomát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'De ha szinte mi, avagy mennyből való angyal hirdetne is néktek valamit azon kívül, a mit néktek hirdettünk, legyen átok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'A mint előbb mondottuk, most is ismét mondom: Ha valaki néktek hirdet valamit azon kívül, a mit elfogadtatok, átok legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'Mert most embereknek engedek-é, avagy az Istennek? Vagy embereknek igyekezem-é tetszeni? Bizonyára, ha még embereknek igyekezném tetszeni, Krisztus szolgája nem volnék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'Tudtotokra adom pedig atyámfiai, hogy az az evangyéliom, melyet én hirdettem, nem ember szerint való;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'Mert én sem embertől vettem azt, sem nem tanítottak arra, hanem a Jézus Krisztus kijelentése által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'Mert hallottátok, mint forgolódtam én egykor a zsidóságban, hogy én felette igen háborgattam az Isten anyaszentegyházát, és pusztítottam azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'És felülmultam a zsidóságban nemzetembeli sok kortársamat, szerfelett rajongván atyai hagyományaimért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'De mikor az Istennek tetszett, ki elválasztott engem az én anyám méhétől fogva és elhívott az ő kegyelme által,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'Hogy kijelentse az ő Fiát én bennem, hogy hirdessem őt a pogányok között: azonnal nem tanácskoztam testtel és vérrel,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'Sem nem mentem Jeruzsálembe az előttem való apostolokhoz, hanem elmentem Arábiába, és ismét visszatértem Damaskusba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'Azután három esztendő mulva fölmentem Jeruzsálembe, hogy Pétert meglátogassam, és nála maradtam tizenöt napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'Az apostolok közül pedig mást nem láttam, hanem csak Jakabot, az Úr atyjafiát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, 'A miket pedig néktek írok, ímé Isten előtt mondom, hogy nem hazudom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'Azután mentem Siriának és Ciliciának tartományaiba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'Ismeretlen valék pedig személyesen a Júdeában levő keresztyén gyülekezetek előtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'Hanem csak hallották, hogy: A ki minket üldözött egykor, most hirdeti azt a hitet, a melyet egykor pusztított.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, 'És dicsőíték bennem az Istent.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'Azután tizennégy esztendő mulva ismét fölmentem Jeruzsálembe Barnabással együtt, elvivén Titust is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, 'Fölmentem pedig kijelentés következtében és eléjök adtam az evangyéliomot, melyet hirdetek a pogányok között, de külön a tekintélyeseknek, hogy valami módon hiába ne fussak, avagy ne futottam légyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, 'De még a velem levő Titus sem kényszeríttetett a körülmetélkedésre, noha görög vala,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, 'Tudniillik a belopózkodott hamis atyafiakért, a kik alattomban közénk jöttek, hogy kikémleljék a mi szabadságunkat, melylyel bírunk a Krisztus Jézusban, hogy minket szolgákká tegyenek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, 'Kiknek egy pillanatra sem adtuk meg magunkat, hogy az evangyéliom igazsága megmaradjon számotokra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, 'A tekintélyesektől pedig, (bárminők valának régen, azzal nem törődöm; Isten nem nézi az embernek személyét): mert velem a tekintélyesek semmit sem közöltek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, 'Sőt ellenkezőleg, mikor látták, hogy én reám van bízva a körülmetéletlenség evangyélioma, mint Péterre a körülmetélésé;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, '(Mert a ki erős volt Péterben a körülmetélkedés apostolságára, bennem is erős volt a pogányok között).');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'És elismervén a nékem adatott kegyelmet, Jakab és Kéfás, meg János, kik oszlopokul tekintetnek, bajtársi jobbjukat nyujták nékem és Barnabásnak, hogy mi a pogányok között, ők pedig a körülmetélés között prédikáljunk:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, 'Csakhogy a szegényekről megemlékezzünk; a mit is én igyekeztem megcselekedni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, 'Mikor pedig Péter Antiókhiába jött, szemtől szembe ellene állottam, mivel panasz volt rá.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'Mert mielőtt némelyek oda jöttek Jakabtól, a pogányokkal együtt evett; mikor pedig oda jöttek, félrevonult és elkülönítette magát, félvén a körülmetélkedésből valóktól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, 'És vele képmutatóskodtak a többi zsidók is, úgy hogy Barnabás szintén elcsábíttatott az ő tettetésök által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'De mikor láttam, hogy nem egyenesen járnak az evangyéliom igazságához képest, mondék Péternek mindnyájok előtt: Ha te zsidó létedre pogány módra élsz és nem zsidó módra, miként kényszeríted a pogányokat, hogy zsidó módra éljenek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, 'Mi, természet szerint zsidók és nem pogányok közül való bűnösök,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, 'Tudván azt, hogy az ember nem igazul meg a törvény cselekedeteiből, hanem a Jézus Krisztusban való hit által, mi is Krisztus Jézusban hittünk, hogy megigazuljunk a Krisztusban való hitből és nem a törvény cselekedeteiből; Mivel a törvény cselekedeteiből nem igazul meg egy test sem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, 'Ha pedig Krisztusban keresvén a megigazulást, mimagunk is bűnösöknek találtatunk, avagy Krisztus bűnnek szolgája-é? Távol legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, 'Mert, ha a miket elrontottam, azokat ismét fölépítem, önmagamat teszem bűnössé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, 'Mert én a törvény által meghaltam a törvénynek, hogy Istennek éljek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, 'Krisztussal együtt megfeszíttettem. Élek pedig többé nem én, hanem él bennem a Krisztus; a mely életet pedig most testben élek, az Isten Fiában való hitben élem, a ki szeretett engem és önmagát adta érettem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, 'Nem törlöm el az Isten kegyelmét; mert ha a törvény által van az igazság, tehát Krisztus ok nélkül halt meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, 'Óh balgatag Galátziabeliek, kicsoda ígézett meg titeket, hogy ne engedelmeskedjetek az igazságnak, kiknek szemei előtt a Jézus Krisztus úgy íratott le, mintha ti köztetek feszíttetett volna meg?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, 'Csak azt akarom megtudni tőletek: a törvény cselekedeteiből kaptátok-é a Lelket, avagy a hit hallásából?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, 'Ennyire esztelenek vagytok? A mit Lélekben kezdtetek el, most testben fejeznétek be?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, 'Annyit szenvedtetek hiába? ha ugyan hiába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, 'Annakokáért, a ki a Lelket szolgáltatja néktek, és hatalmas dolgokat művel bennetek, a törvény cselekedeteiből, vagy a hit hallásából cselekeszi-é?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, 'Miképen Ábrahám hitt az Istennek, és tulajdoníttatott néki igazságul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'Értsétek meg tehát, hogy a kik hitből vannak, azok az Ábrahám fiai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, 'Előre látván pedig az Írás, hogy Isten hitből fogja megigazítani a pogányokat, eleve hirdette Ábrahámnak, hogy: Te benned fognak megáldatni minden népek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'Ekként a hitből valók áldatnak meg a hívő Ábrahámmal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'Mert a kik törvény cselekedeteiből vannak, átok alatt vannak; minthogy meg van írva: Átkozott minden, a ki meg nem marad mindazokban, a mik megirattak a törvény könyvében, hogy azokat cselekedje.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, 'Hogy pedig a törvény által senki sem igazul meg Isten előtt, nyilvánvaló, mert az igaz ember hitből él.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, 'A törvény pedig nincs hitből, hanem a mely ember cselekeszi azokat, élni fog azok által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'Krisztus váltott meg minket a törvény átkától, átokká levén érettünk; mert meg van írva: Átkozott minden, a ki fán függ:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'Hogy az Ábrahám áldása Krisztus Jézusban legyen a pogányokon, hogy a Lélek ígéretét elnyerjük hit által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, 'Atyámfiai! ember szerint szólok. Lám az embernek megerősített testámentomát senki erőtelenné nem teszi, sem ahhoz hozzá nem ád.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'Az ígéretek pedig Ábrahámnak adattak és az ő magvának. Nem mondja: És a magvaknak, mint sokról; hanem mint egyről. És a te magodnak, a ki a Krisztus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, 'Ezt mondom pedig, hogy a kötést, melyet Isten először megerősített a Krisztusra nézve, a négyszázharmincz esztendő multán keletkezett törvény nem teszi erőtelenné, hogy megsemmisítse az ígéretet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'Mert ha törvényből van az örökség, akkor többé nem ígéretből; Ábrahámnak pedig ígéret által ajándékozta azt az Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, 'Micsoda tehát a törvény? A bűnök okáért adatott, a míg eljő a Mag, a kinek tétetett az ígéret; rendeltetvén angyalok által, közbenjáró kezében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, 'A közbenjáró pedig nem egyé, Isten ellenben egy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'A törvény tehát az Isten ígéretei ellen van-é? Távol legyen! Mert ha olyan törvény adatott volna, a mely képes megeleveníteni, valóban a törvényből volna az igazság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'De az Írás mindent bűn alá rekesztett, hogy az ígéret Jézus Krisztusban való hitből adassék a hívőknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, 'Minekelőtte pedig eljött a hit, törvény alatt őriztettünk, egybezárva az eljövendő hit kinyilatkoztatásáig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'Ekként a törvény Krisztusra vezérlő mesterünkké lett, hogy hitből igazuljunk meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'De minekutána eljött a hit, nem vagyunk többé a vezérlő mester alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, 'Mert mindnyájan Isten fiai vagytok a Krisztus Jézusban való hit által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, 'Mert a kik Krisztusba keresztelkedtetek meg, Krisztust öltöztétek fel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, 'Nincs zsidó, sem görög; nincs szolga, sem szabad; nincs férfi, sem nő; mert ti mindnyájan egyek vagytok a Krisztus Jézusban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, 'Ha pedig Krisztuséi vagytok, tehát az Ábrahám magva vagytok, és ígéret szerint örökösök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, 'Mondom pedig, hogy a meddig az örökös kiskorú, semmiben sem különbözik a szolgától, jóllehet ura mindennek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, 'Hanem gyámok és gondviselők alatt van az atyjától rendelt ideig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, 'Azonképen mi is, mikor kiskorúak valánk, a világ elemei alá voltunk vettetve szolgaként:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, 'Mikor pedig eljött az időnek teljessége, kibocsátotta Isten az ő Fiát, a ki asszonytól lett, a ki törvény alatt lett,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, 'Hogy a törvény alatt levőket megváltsa, hogy elnyerjük a fiúságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, 'Minthogy pedig fiak vagytok, kibocsátotta az Isten az ő Fiának Lelkét a ti szíveitekbe, ki ezt kiáltja: Abba, Atya!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, 'Azért nem vagy többé szolga, hanem fiú; ha pedig fiú, Istennek örököse is Krisztus által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, 'Ámde akkor, mikor még nem ismertétek az Istent, azoknak szolgáltatok, a mik természet szerint nem istenek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, 'Most azonban, hogy megismertétek az Istent, sőt hogy megismert titeket az Isten, miként tértek vissza ismét az erőtelen és gyarló elemekhez, a melyeknek megint újból szolgálni akartok?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, 'Megtartjátok a napokat és hónapokat és időket, meg az esztendőket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, 'Féltelek titeket, hogy hiába fáradoztam körültetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, 'Legyetek olyanok, mint én; mert én is olyanná lettem, mint ti: atyámfiai, kérlek titeket, semmivel sem bántottatok meg engem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, 'Tudjátok pedig, hogy testem erőtelensége miatt hirdettem néktek az evangyéliomot először.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, 'És megkísértetvén testemben, nem vetettetek meg, sem nem útáltatok meg engem, hanem úgy fogadtatok, mint Istennek angyalát, mint Krisztus Jézust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, 'Hová lőn tehát a ti boldogságotok? Mert bizonyságot teszek néktek, hogy ti, ha lehetséges volt volna, szemeiteket kivájván, nékem adtátok volna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, 'Tehát ellenségetek lettem-é, megmondván néktek az igazat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, 'Nem szépen buzgolkodnak érettetek, sőt minket ki akarnak rekeszteni, hogy mellettök buzgolkodjatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, 'Szép dolog pedig fáradozni a jóban mindenkor, és nem csupán akkor, ha köztetek vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, 'Gyermekeim! kiket ismét fájdalommal szűlök, míglen kiábrázolódik bennetek Krisztus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, 'Szeretnék pedig most köztetek jelen lenni és változtatni a hangomon; mert bizonytalanságban vagyok felőletek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, 'Mondjátok meg nékem, kik a törvény alatt akartok lenni: nem halljátok-é a törvényt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, 'Mert meg van írva, hogy Ábrahámnak két fia volt; egyik a szolgálótól, és a másik a szabadostól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, 'De a szolgálótól való test szerint született; a szabadostól való pedig az ígéret által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, 'Ezek mást példáznak: mert azok az asszonyok a két szövetség, az egyik a Sinai hegyről való, szolgaságra szűlő, ez Hágár,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, 'Mert Hágár a Sinai hegy Arábiában, hasonlatos pedig a mostani Jeruzsálemhez, nevezetesen fiaival együtt szolgál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, 'De a magasságos Jeruzsálem szabad, ez mindnyájunknak anyja,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, 'Mert meg van írva: Ujjongj te meddő, ki nem szűlsz; vígadozzál és kiálts, ki nem vajudol; mert sokkal több az elhagyottnak magzatja, mint a kinek férje vagyon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, 'Mi pedig, atyámfiai, Izsák szerint, ígéretnek gyermekei vagyunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, 'De valamint akkor a test szerint született üldözte a Lélek szerint valót, úgy most is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, 'De mit mond az Írás? Űzd ki a szolgálót és az ő fiát; mert a szolgáló fia nem örököl a szabad nő fiával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, 'Annakokáért, atyámfiai, nem vagyunk a szolgáló fiai, hanem a szabadoséi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, 'Annakokáért a szabadságban, melyre minket Krisztus megszabadított, álljatok meg, és ne kötelezzétek meg ismét magatokat szolgaságnak igájával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, 'Ímé, én Pál mondom néktek, hogy ha körülmetélkedtek, Krisztus néktek semmit sem használ.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, 'Bizonyságot teszek pedig ismét minden embernek, a ki körülmetélkedik, hogy köteles az egész törvényt megtartani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, 'Elszakadtatok Krisztustól, a kik a törvény által akartok megigazulni, a kegyelemből kiestetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, 'Mert mi a Lélek által, hitből várjuk az igazság reménységét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, 'Mert Krisztus Jézusban sem a körülmetélkedés nem ér semmit, sem a körülmetélkedetlenség, hanem a szeretet által munkálkodó hit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, 'Jól futottatok; kicsoda gátolt meg titeket, hogy ne engedelmeskedjetek az igazságnak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, 'Ez a hitetés nem attól van, a ki titeket hív.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, 'Kis kovász az egész tésztát megkeleszti.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 10, 'Bizodalmam van az Úrban ti hozzátok, hogy más értelemben nem lesztek; de a ki titeket megzavar, elveszi az ítéletet, bárki legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 11, 'Én pedig atyámfiai, ha még a körülmetélést hirdetem, miért üldöztetem mégis? Akkor eltöröltetett a kereszt botránya.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 12, 'Bárcsak ki is metszetnék magukat, a kik titeket bujtogatnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 13, 'Mert ti szabadságra hivattatok atyámfiai; csakhogy a szabadság ürügy ne legyen a testnek, sőt szeretettel szolgáljatok egymásnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 14, 'Mert az egész törvény ez egy ígében teljesedik be: Szeresd felebarátodat, mint magadat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 15, 'Ha pedig egymást marjátok és faljátok, vigyázzatok, hogy egymást fel ne emészszétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 16, 'Mondom pedig, Lélek szerint járjatok, és a testnek kívánságát véghez ne vigyétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 17, 'Mert a test a lélek ellen törekedik, a lélek pedig a test ellen; ezek pedig egymással ellenkeznek, hogy ne azokat cselekedjétek, a miket akartok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 18, 'Ha azonban a Lélektől vezéreltettek, nem vagytok a törvény alatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 19, 'A testnek cselekedetei pedig nyilvánvalók, melyek ezek: házasságtörés, paráznaság, tisztátalanság, bujálkodás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 20, 'Bálványimádás, varázslás, ellenségeskedések, versengések, gyűlölködések, harag, patvarkodások, viszszavonások, pártütések,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 21, 'Irígységek, gyilkosságok, részegségek, dobzódások és ezekhez hasonlók: melyekről előre mondom néktek, a miképen már ezelőtt is mondottam, hogy a kik ilyeneket cselekesznek, Isten országának örökösei nem lesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 22, 'De a Léleknek gyümölcse: szeretet, öröm, békesség, béketűrés, szívesség, jóság, hűség, szelídség, mértékletesség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 23, 'Az ilyenek ellen nincs törvény.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 24, 'A kik pedig Krisztuséi, a testet megfeszítették indulataival és kívánságaival együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 25, 'Ha Lélek szerint élünk, Lélek szerint is járjunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 26, 'Ne legyünk hiú dicsőség kívánók, egymást ingerlők, egymásra irígykedők.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 1, 'Atyámfiai, még ha előfogja is az embert valami bűn, ti lelkiek, igazítsátok útba az olyant szelídségnek lelkével, ügyelvén magadra, hogy meg ne kísértessél te magad is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 2, 'Egymás terhét hordozzátok, és úgy töltsétek be a Krisztus törvényét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 3, 'Mert ha valaki azt véli, hogy ő valami, holott semmi, önmagát csalja meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 4, 'Minden ember pedig az ő maga cselekedetét vizsgálja meg, és akkor csakis önmagára nézve lesz dicsekedése és nem másra nézve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 5, 'Mert kiki a maga terhét hordozza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 6, 'A ki pedig az ígére taníttatik, közölje minden javát tanítójával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 7, 'Ne tévelyegjetek, Isten nem csúfoltatik meg; mert a mit vet az ember, azt aratándja is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 8, 'Mert a ki vet az ő testének, a testből arat veszedelmet; a ki pedig vet a léleknek, a lélekből arat örök életet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 9, 'A jótéteményben pedig meg ne restüljünk, mert a maga idejében aratunk, ha el nem lankadunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 10, 'Annakokáért míg időnk van, cselekedjünk jót mindenekkel, kiváltképen pedig a mi hitünknek cselédeivel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 11, 'Látjátok, mekkora betűkkel írok néktek a saját kezemmel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 12, 'A kik testre szépek szeretnének lenni, azok kényszerítenek titeket a körülmetélkedésre; csak azért, hogy a Krisztus keresztjéért ne üldöztessenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 13, 'Mert magok a körülmetélkedettek sem tartják meg a törvényt; hanem azért akarják, hogy ti körülmetélkedjetek, hogy a ti testetekkel dicsekedjenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 14, 'Nékem pedig ne legyen másban dicsekedésem, hanem a mi Urunk Jézus Krisztus keresztjében, a ki által nékem megfeszíttetett a világ, és én is a világnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 15, 'Mert Krisztus Jézusban sem a körülmetélkedés, sem a körülmetéletlenség nem használ semmit, hanem az új teremtés.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 16, 'És a kik e szabály szerint élnek, békesség és irgalmasság azokon, és az Istennek Izráelén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 17, 'Ennekutána senki nékem bántásomra ne legyen; mert én az Úr Jézusnak bélyegeit hordozom az én testemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 18, 'A mi Urunk Jézus Krisztusnak kegyelme legyen a ti lelketekkel atyámfiai! Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Pál, Jézus Krisztus apostola Isten akaratjából, az Efézusban lévő és Krisztus Jézusban hívő szenteknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'Kegyelem néktek és békesség Istentől, a mi Atyánktól és az Úr Jézus Krisztustól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'Áldott legyen az Isten, és a mi Urunknak, Jézus Krisztusnak Atyja, a ki megáldott minket minden lelki áldással a mennyekben a Krisztusban,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'A szerint, a mint magának kiválasztott minket Ő benne a világ teremtetése előtt, hogy legyünk mi szentek és feddhetetlenek Ő előtte szeretet által,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'Eleve elhatározván, hogy minket a maga fiaivá fogad Jézus Krisztus által az Ő akaratjának jó kedve szerint,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'Kegyelme dicsőségének magasztalására, a melylyel megajándékozott minket ama Szerelmesben,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'A kiben van a mi váltságunk az Ő vére által, a bűnöknek bocsánata az Ő kegyelmének gazdagsága szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'Melyet nagy bőséggel közlött velünk minden bölcsességgel és értelemmel,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'Megismertetvén velünk az Ő akaratjának titkát az Ő jó kedve szerint, melyet eleve elrendelt magában,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'Az idők teljességének rendjére nézve, hogy ismét egybeszerkeszt magának mindeneket a Krisztusban, mind a melyek a mennyekben vannak, mind a melyek e földön vannak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'Ő benne, a kiben vettük is az örökséget, eleve elrendeltetvén annak eleveelvégzése szerint, a ki mindent az ő akaratjának tanácsából cselekszik,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'Hogy legyünk mi magasztalására az Ő dicsőségének, a kik előre reménykedtünk a Krisztusban:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'A kiben ti is, minekutána hallottátok az igazságnak beszédét, idvességetek evangyéliomát, a melyben hittetek is, megpecsételtettetek az ígéretnek ama Szent Lelkével,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'A ki záloga a mi örökségünknek Isten tulajdon népének megváltatására, az Ő dicsőségének magasztalására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'Annakokáért én is, hallván a ti hiteteket az Úr Jézusban, és minden szentekhez való szerelmeteket,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'Nem szűnöm meg hálát adni tiérettetek, emlékezvén reátok az én könyörgéseimben;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'Hogy a mi Urunk Jézus Krisztusnak Istene, a dicsőségnek Atyja adjon néktek bölcseségnek és kijelentésnek Lelkét az Ő megismerésében;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'És világosítsa meg értelmetek szemeit, hogy tudhassátok, hogy mi az Ő elhívásának a reménysége, mi az Ő öröksége dicsőségének a gazdagsága a szentek között,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'És mi az Ő hatalmának felséges nagysága irántunk, a kik hiszünk, az Ő hatalma erejének ama munkája szerint,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'A melyet megmutatott a Krisztusban, mikor feltámasztotta Őt a halálból, és ültette Őt a maga jobbjára a mennyekben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'Felül minden fejedelemségen és hatalmasságon és erőn és uraságon és minden néven, mely neveztetik nemcsak e világon, hanem a következendőben is:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'És mindeneket vetett az Ő lábai alá, és Őt tette mindeneknek fölötte az anyaszentegyháznak fejévé,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'Mely az Ő teste, teljessége Ő néki, a ki mindeneket betölt mindenekkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'Titeket is megelevenített, a kik holtak valátok a ti vétkeitek és bűneitek miatt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'Melyekben jártatok egykor e világ folyása szerint, a levegőbeli hatalmasság fejedelme szerint, ama lélek szerint, mely most az engedetlenség fiaiban munkálkodik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'A kik között forgolódtunk egykor mi is mindnyájan a mi testünk kívánságaiban, cselekedvén a testnek és a gondolatoknak akaratját, és természet szerint haragnak fiai valánk, mint egyebek is:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'De az Isten gazdag lévén irgalmasságban, az Ő nagy szerelméből, melylyel minket szeretett,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'Minket, kik meg voltunk halva a vétkek miatt, megelevenített együtt a Krisztussal, (kegyelemből tartattatok meg!)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'És együtt feltámasztott és együtt ültetett a mennyekben, Krisztus Jézusban:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'Hogy megmutassa a következendő időkben az Ő kegyelmének felséges gazdagságát hozzánk való jóságából a Krisztus Jézusban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'Mert kegyelemből tartattatok meg, hit által; és ez nem tőletek van: Isten ajándéka ez;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'Nem cselekedetekből, hogy senki ne kérkedjék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'Mert az Ő alkotása vagyunk, teremtetvén Általa a Krisztus Jézusban jó cselekedetekre, a melyeket előre elkészített az Isten, hogy azokban járjunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'Annakokáért emlékezzetek meg arról, hogy egykor ti a testben pogányok, kiket körülmetéletlenségnek nevez vala amaz úgynevezett s a testen kézzel megcsinált körülmetélkedés,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'Hogy ti, mondom, abban az időben Krisztus nélkül valók voltatok, Izráel társaságától idegenek, és az ígéret szövetségeitől távolvalók, reménységetek nem vala, és Isten nélkül valók voltatok e világon;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'Most pedig a Krisztus Jézusban ti, kik egykor távol valátok, közelvalókká lettetek a Krisztus vére által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'Mert Ő a mi békességünk, ki egygyé tette mind a két nemzetséget, és lerontotta a közbevetett választófalat,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 'Az ellenségeskedést az Ő testében, a parancsolatoknak tételekben való törvényét eltörölvén; hogy ama kettőt egy új emberré teremtse Ő magában, békességet szerezvén;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'És hogy megbékéltesse az Istennel mind a kettőt, egy testben a keresztfa által, megölvén ezen az ellenségeskedést.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'És eljövén, békességet hirdetett néktek, a távol valóknak és a közel valóknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'Mert Ő általa van menetelünk mindkettőnknek egy Lélekben az Atyához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'Azért immár nem vagytok jövevények és zsellérek, hanem polgártársai a szenteknek és cselédei az Istennek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'Kik fölépíttettetek az apostoloknak és prófétáknak alapkövén, lévén a szegletkő maga Jézus Krisztus,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'A kiben az egész épület szép renddel rakattatván, nevekedik szent templommá az Úrban;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'A kiben ti is együtt építtettek Isten hajlékává a Lélek által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'Ezért vagyok én, Pál, a Krisztusnak foglya ti érettetek, a pogányokért;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, 'Ha ugyan hallottátok Isten kegyelmének rendelkezését, melyet nékem adott a ti érdeketekben;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, 'Hogy tudniillik kijelentés útján ismertette meg velem a titkot, a szerint, a mint az elébb megírám röviden,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'Melynek olvasásából megérthetitek, hogy micsoda az én értelmem a Krisztus titka felől;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'A mely egyéb időkben meg nem ismertettetett az emberek fiaival úgy, a hogy most kijelentetett az Ő szent apostolainak és prófétáinak a Lélek által:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'Hogy tudniillik a pogányok örökös társak és egyugyanazon test tagjai és részesei az ő ígéretének a Krisztus Jézusban az evangyéliom által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'A melynek szolgájává lettem az Isten ama kegyelmének ajándékából, mely adatott nékem az Ő hatalmának munkája szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'Nékem, minden szentek között a legeslegkisebbnek adatott ez a kegyelem, hogy a pogányoknak hirdessem a Krisztus végére mehetetlen gazdagságát;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'És hogy megvilágosítsam mindeneknek, hogy miképen rendelkezett Isten ama titok felől, a mely elrejtetett vala örök időktől fogva az Istenben, a ki mindeneket teremtett a Jézus Krisztus által;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'Azért, hogy megismertettessék most a mennybeli fejedelemségekkel és hatalmasságokkal az egyház által az Istennek sokféle bölcsesége,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'Amaz örök eleve-elvégezés szerint, a melyet megcselekedett a Krisztus Jézusban, a mi Urunkban:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'A kiben van a mi bátorságunk és bizodalommal való menetelünk Istenhez az Ő benne való hit által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'Azért kérlek, hogy ne csüggedjetek el az én ti érettetek való nyomorúságaim miatt, a melyek néktek dicsőségtekre vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'Ezokáért meghajtom térdeimet a mi Urunk Jézus Krisztusnak Atyja előtt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'A kiről neveztetik minden nemzetség, mennyen és földön,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'Hogy adja meg néktek az Ő dicsősége gazdagságáért, hogy hatalmasan megerősödjetek az Ő Lelke által a belső emberben;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'Hogy lakozzék a Krisztus a hit által a ti szívetekben;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'A szeretetben meggyökerezvén és alapot vevén, hogy megérthessétek minden szentekkel egybe, mi a szélessége és hosszúsága és mélysége és magassága az Isten jóvoltának,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'És megismerjétek a Krisztusnak minden ismeretet felül haladó szeretetét, hogy ekképen beteljesedjetek az Istennek egész teljességéig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'Annak pedig, a ki véghetetlen bőséggel mindeneket megcselekedhetik, feljebb hogynem mint kérjük vagy elgondoljuk, a mi bennünk munkálkodó erő szerint,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'Annak légyen dicsőség az egyházban a Krisztus Jézusban nemzetségről nemzetségre örökkön örökké. Ámen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'Kérlek azért titeket én, ki fogoly vagyok az Úrban, hogy járjatok úgy, mint illik elhívatásotokhoz, melylyel elhívattatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'Teljes alázatossággal és szelídséggel, hosszútűréssel, elszenvedvén egymást szeretetben,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'Igyekezvén megtartani a Lélek egységét a békességnek kötelében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'Egy a test és egy a Lélek, miképen elhívatástoknak egy reménységében hívattatok el is;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'Egy az Úr, egy a hit, egy a keresztség;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'Egy az Isten és mindeneknek Atyja, a ki mindeneknek felette van és mindenek által és mindnyájatokban munkálkodik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'Mindenikünknek pedig adatott a kegyelem a Krisztustól osztott ajándéknak mértéke szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'Ezokáért mondja az Írás: Fölmenvén a magasságba foglyokat vitt fogva, és adott ajándékokat az embereknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, '(Az pedig, hogy fölment, mit jelentene mást, mint hogy előbb le is szállott a föld alsóbb részeire?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'A ki leszállott vala, ugyanaz, a ki fel is ment, feljebb minden egeknél, hogy mindeneket betöltsön.)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'És Ő adott némelyeket apostolokul, némelyeket prófétákul, némelyeket evangyélistákul, némelyeket pedig pásztorokul és tanítókul:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'A szentek tökéletesbbítése czéljából szolgálat munkájára, a Krisztus testének építésére:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'Míg eljutunk mindnyájan az Isten Fiában való hitnek és az Ő megismerésének egységére, érett férfiúságra, a Krisztus teljességével ékeskedő kornak mértékére:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'Hogy többé ne legyünk gyermekek, kiket ide s tova hány a hab és hajt a tanításnak akármi szele, az embereknek álnoksága által, a tévelygés ravaszságához való csalárdság által;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'Hanem az igazságot követvén szeretetben, mindenestől fogva nevekedjünk Abban, a ki a fej, a Krisztusban;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'A kiből az egész test, szép renddel egyberakatván és egybeszerkesztetvén az Ő segedelmének minden kapcsaival, minden egyes tagnak mértéke szerint való munkássággal teljesíti a testnek nevekedését a maga fölépítésére szeretetben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'Ezt mondom annakokáért és bizonyságot teszek az Úrban, hogy ti többé ne járjatok úgy, mint egyéb pogányok is járnak az ő elméjöknek hiábavalóságában,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'Kik értelmökben meghomályosodtak, elidegenültek az isteni élettől a tudatlanság miatt, mely az ő szívök keménysége miatt van bennök;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'Kik erkölcsi érzés nélkül, önmagukat a bujálkodásra adták, minden tisztátalanságnak nagy nyereséggel való cselekedésére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'Ti pedig nem így tanultátok a Krisztust;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'Ha ugyan Őt megértettétek és Ő benne megtaníttattatok, úgy a mint az igazság a Jézusban:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'Hogy levetkezzétek ama régi élet szerint való ó embert, mely meg van romolva a csalárdság kívánságai miatt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'Megújuljatok pedig a ti elméteknek lelke szerint,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'És felöltözzétek amaz új embert, mely Isten szerint teremtetett igazságban és valóságos szentségben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'Azért levetvén a hazugságot, szóljatok igazságot, kiki az ő felebarátjával: mert egymásnak tagjai vagyunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, 'Ám haragudjatok, de ne vétkezzetek: a nap le ne menjen a ti haragotokon;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'Se pedig az ördögnek ne adjatok helyet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'A ki oroz vala, többé ne orozzon; hanem inkább munkálkodjék, cselekedvén az ő kezeivel azt, a mi jó, hogy legyen mit adnia a szűkölködőnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'Semmi rothadt beszéd a ti szátokból ki ne származzék, hanem csak a mely hasznos a szükséges építésre, hogy áldásos legyen a hallgatóknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'És meg ne szomorítsátok az Istennek ama Szent Lelkét, a ki által megpecsételtettetek a teljes váltságnak napjára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'Minden mérgesség és fölgerjedés és harag és lárma és káromkodás kivettessék közületek minden gonoszsággal együtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'Legyetek pedig egymáshoz jóságosak, irgalmasok, megengedvén egymásnak, miképen az Isten is a Krisztusban megengedett néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'Legyetek annakokáért követői az Istennek, mint szeretett gyermekek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'És járjatok szeretetben, miképen a Krisztus is szeretett minket, és adta Önmagát miérettünk ajándékul és áldozatul az Istennek, kedves jó illatul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'Paráznaság pedig és akármely tisztátalanság vagy fösvénység ne is neveztessék ti közöttetek, a mint szentekhez illik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'Sem undokság, vagy bolond beszéd, vagy trágárság, melyek nem illenek: hanem inkább hálaadás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'Mert azt jól tudjátok, hogy egy paráznának is, vagy tisztátalannak, vagy fösvénynek, ki bálványimádó, nincs öröksége a Krisztusnak és Istennek országában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'Senki titeket meg ne csaljon üres beszédekkel; mert ezekért jő az Isten haragja a hitetlenség fiaira.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'Annakokáért ne legyetek részesei ezeknek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'Mert valátok régen sötétség, most pedig világosság az Úrban: mint világosságnak fiai úgy járjatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, '(Mert a világosságnak gyümölcse minden jóságban és igazságban és valóságban van),');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'Meggondolván, mi legyen kedves az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'És ne legyen közösségtek a sötétségnek gyümölcstelen cselekedeteivel, hanem inkább meg is feddjétek azokat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'Mert a melyeket azok titokban cselekesznek, éktelen dolog csak mondani is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'Mindezek pedig megfeddetvén, a világosság által napvilágra jőnek; mert minden, a mi napvilágra jő, világosság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'Annakokáért mondja: Serkenj föl, a ki aluszol és támadj fel a halálból, és felragyogott tenéked a Krisztus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'Meglássátok annakokáért, hogy mimódon okkal járjatok, nem mint bolondok, hanem mint bölcsek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'Áron is megvegyétek az alkalmatosságot, mert a napok gonoszok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'Annakokáért ne legyetek esztelenek, hanem megértsétek, mi legyen az Úrnak akaratja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'És meg ne részegedjetek bortól, miben kicsapongás van: hanem teljesedjetek be Szent Lélekkel,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'Beszélgetvén egymás között zsoltárokban és dícséretekben és lelki énekekben, énekelvén és dícséretet mondván szívetekben az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'Hálákat adván mindenkor mindenekért a mi Urunk Jézus Krisztusnak nevében az Istennek és Atyának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'Engedelmesek legyetek egymásnak Isten félelmében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'Ti asszonyok a ti saját férjeteknek engedelmesek legyetek, mint az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'Mert a férj feje a feleségének, mint a Krisztus is feje az egyháznak, és ugyanő megtartója a testnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'De miképen az egyház engedelmes a Krisztusnak, azonképen az asszonyok is engedelmesek legyenek férjöknek mindenben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'Ti férfiak, szeressétek a ti feleségeteket, miképen a Krisztus is szerette az egyházat, és Önmagát adta azért;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'Hogy azt megszentelje, megtisztítván a víznek feredőjével az íge által,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'Hogy majd Önmaga elébe állítsa dicsőségben az egyházat, úgy hogy azon ne legyen szeplő, vagy sömörgözés, vagy valami afféle; hanem hogy legyen szent és feddhetetlen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'Úgy kell a férfiaknak szeretni az ő feleségöket, mint az ő tulajdon testöket. A ki szereti az ő feleségét, önmagát szereti.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'Mert soha senki az ő tulajdon testét nem gyűlölte; hanem táplálgatja és ápolgatja azt, miképen az Úr is az egyházat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'Mert az Ő testének tagjai vagyunk, az Ő testéből és az Ő csontjaiból valók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, 'Annakokáért elhagyja az ember atyját és anyját, és ragaszkodik az ő feleségéhez; és lesznek ketten egy testté.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'Felette nagy titok ez: de én a Krisztusról és az egyházról szólok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'Hanem azért ti is egyen-egyen, ki-ki az ő feleségét úgy szeresse, mint önmagát; az asszony pedig meglássa, hogy félje a férjét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'Ti gyermekek szót fogadjatok a ti szüleiteknek az Úrban; mert ez az igaz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, 'Tiszteljed a te atyádat és a te anyádat (a mi az első parancsolat ígérettel).');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, 'Hogy jól legyen néked dolgod és hosszú életű légy e földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'Ti is atyák ne ingereljétek gyermekeiteket, hanem neveljétek azokat az Úr tanítása és intése szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'Ti szolgák, engedelmesek legyetek a ti test szerint való uraitoknak félelemmel és rettegéssel, szíveteknek egyenességében, mint a Krisztusnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'Nem a szemnek szolgálván, mint a kik embereknek akarnak tetszeni, hanem mint Krisztus szolgái, cselekedvén az Istennek akaratját lélekből,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'Jó akarattal, mint a kik az Úrnak szolgálnak és nem embereknek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'Tudván, hogy kiki a mi jót cselekszik, azt veendi az Úrtól, akár szolga legyen, akár szabados.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'Ti is urak, ugyanazt cselekedjétek ő velök, elhegyván a fenyegetést; tudván, hogy a ti Uratok is mennyben van, és személyválogatás nincsen Ő nála.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'Végezetre, atyámfiai, legyetek erősek az Úrban, és az ő hatalmas erejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'Öltözzétek föl az Isten minden fegyverét, hogy megállhassatok az ördögnek minden ravaszságával szemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'Mert nem vér és test ellen van nékünk tusakodásunk, hanem a fejedelemségek ellen, a hatalmasságok ellen, ez élet sötétségének világbírói ellen, a gonoszság lelkei ellen, melyek a magasságban vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'Annakokáért vegyétek föl az Istennek minden fegyverét, hogy ellentállhassatok ama gonosz napon, és mindeneket elvégezvén megállhassatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'Álljatok hát elő, körül övezvén derekatokat igazlelkűséggel, és felöltözvén az igazságnak mellvasába,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'És felsarúzván lábaitokat a békesség evangyéliomának készségével;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'Mindezekhez fölvevén a hitnek paizsát, a melylyel ama gonosznak minden tüzes nyilát megolthatjátok;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'Az idvesség sisakját is fölvegyétek, és a Léleknek kardját, a mely az Isten beszéde:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'Minden imádsággal és könyörgéssel imádkozván minden időben a Lélek által, és ugyanezen dologban vigyázván minden állhatatossággal és könyörgéssel minden szentekért,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'Én érettem is, hogy adassék nékem szó számnak megnyitásakor, hogy bátorsággal ösmertessem meg az evangyéliom titkát,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, 'A melyért követséget viselek lánczok között; hogy bátran szóljak arról, a miképen kell szólanom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'Hogy pedig ti is megtudjátok dolgaimat, hogy mit cselekeszem, mindent megismertet veletek Tikhikus, a szeretett atyafi és hív szolga az Úrban;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'Kit éppen azért küldöttem hozzátok, hogy megismerjétek a mi dolgainkat, és megvígasztalja a ti szíveteket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'Békesség az atyafiaknak és szeretet hittel egybe az Atya Istentől és az Úr Jézus Krisztustól!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, 'A kegyelem legyen mindazokkal, a kik szeretik a mi Urunk Jézus Krisztust romlatlanságban. Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'Pál és Timótheus, Jézus Krisztus szolgái, minden szenteknek a Krisztus Jézusban, a kik Filippiben vannak, a püspökökkel és diakónusokkal egyetemben:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Kegyelem néktek és békesség Istentől, a mi Atyánktól és az Úr Jézus Krisztustól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Hálát adok az én Istenemnek, minden ti rólatok való emlékezésemben,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'Mindenkor minden én könyörgésemben mindenitekért nagy örömmel könyörögvén,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'Mivelhogy résztvettetek az evangyéliom ügyében az első naptól fogva mind ez ideig;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'Meg lévén győződve arról, hogy a ki elkezdette bennetek a jó dolgot, elvégezi a Krisztus Jézusnak napjáig:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'A mint hogy méltó, hogy én ilyen értelemben legyek mindenitek felől, azért, mert én szívemben hordalak titeket, mint a kik mind az én fogságomban, mind az evangyéliomnak oltalmazásában és megbizonyításában mindnyájan részestársaim vagytok a nékem adott kegyelemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'Mert bizonyságom az Isten, mely igen vágyakozom mindnyájatok után a Krisztus Jézus szerelmében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'És azért imádkozom, hogy a ti szeretetetek még jobban-jobban bővölködjék ismeretben és minden értelmességben;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'Hogy megítélhessétek, hogy mi a rossz és mi a jó; hogy legyetek tiszták és botlás nélkül valók a Krisztusnak napjára;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'Teljesek lévén az igazságnak gyümölcsével, melyet Jézus Krisztus teremt az Isten dicsőségére és magasztalására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'Tudtotokra akarom pedig adni, atyámfiai, hogy az én dolgaim inkább előmenetelére lőnek az evangyéliomnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'Annyira, hogy a Krisztusban híressé lett az én fogságom a testőrség egész házában és minden mások előtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'És többen az Úrban való atyafiak közül bízván az én fogságomban, nagyobb bátorsággal merik szólani az ígét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Némelyek ugyan irígységből és versengésből is, de mások jóakaratból is hirdetik a Krisztust.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'Némelyek versengésből prédikálják a Krisztust, nem tiszta lélekkel, azt hivén, hogy fogságom nyomorúságait így megnevelik;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'De mások szeretetből, tudván, hogy én az evangyéliomnak oltalmazására rendeltettem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Mert mit mondjak? csakhogy minden módon, akár színből, akár szívből, a Krisztus prédikáltatik: és én ennek örülök, sőt örülni is fogok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'Mert tudom, hogy ez nékem idvességemre lesz a ti könyörgéstek által és a Jézus Krisztus Lelkének segedelme által,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'Amaz én esengő várásom és reménységem szerint, hogy semmiben meg nem szégyenülök, hanem mint mindenkor, úgy most is nagy bátorsággal fog magasztaltatni Krisztus az én testemben, akár életem, akár halálom által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'Mert nékem az élet Krisztus, és a meghalás nyereség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'De ha e testben való életem munkámat gyümölcsözteti: hogy melyiket válaszszam, meg sem mondhatom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'Mert szorongattatom e kettő között, kívánván elköltözni és a Krisztussal lenni; mert ez sokkal inkább jobb;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'De e testben megmaradnom szükségesebb ti érettetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'És ebben bízva, tudom, hogy megmaradok és együtt maradok mindnyájatokkal a ti hitben való gyarapodástokra és örömötökre;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'Hogy bőven dicsekedhessetek velem Krisztus Jézusban az én ti nálatok való újabb megjelenésem által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'Csakhogy a Krisztus evangyéliomához méltóan viseljétek magatokat, hogy akár oda menvén és látván titeket, akár távol lévén, azt halljam dolgaitok felől, hogy megállotok egy lélekben, egy érzéssel viaskodván az evangyéliom hitéért;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'És meg nem félemlvén semmiben az ellenségek előtt: a mi azoknak a veszedelem jele, néktek pedig az üdvösségé, és ez az Istentől van;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'Mert néktek adatott az a kegyelem a Krisztusért, nemcsak hogy higyjetek Ő benne, hanem hogy szenvedjetek is Ő érette:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'Ugyanolyan tusakodástok lévén, a milyent láttatok én nálam, és most hallotok én felőlem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Ha annakokáért helye van Krisztusban az intésnek, ha helye van a szeretet vígasztalásának, ha helye van a Lélekben való közösségnek, ha helye van a szívnek és könyörületességnek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'Teljesítsétek be az én örömömet, hogy egyenlő indulattal legyetek, ugyanazon szeretettel viseltetvén, egy érzésben, egyugyanazon indulattal lévén;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'Semmit nem cselekedvén versengésből, sem hiábavaló dicsőségből, hanem alázatosan egymást különbeknek tartván ti magatoknál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'Ne nézze kiki a maga hasznát, hanem mindenki a másokét is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'Annakokáért az az indulat legyen bennetek, mely volt a Krisztus Jézusban is,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, 'A ki, mikor Istennek formájában vala, nem tekintette zsákmánynak azt, hogy ő az Istennel egyenlő,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'Hanem önmagát megüresíté, szolgai formát vévén föl, emberekhez hasonlóvá lévén;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'És mikor olyan állapotban találtatott mint ember, megalázta magát, engedelmes lévén halálig, még pedig a keresztfának haláláig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'Annakokáért az Isten is felmagasztalá őt, és ajándékoza néki oly nevet, a mely minden név fölött való;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'Hogy a Jézus nevére minden térd meghajoljon, mennyeieké, földieké és föld alatt valóké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'És minden nyelv vallja, hogy Jézus Krisztus Úr az Atya Isten dicsőségére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'Annakokáért, szerelmeseim, a miképen mindenkor engedelmeskedtetek, nem úgy, mint az én jelenlétemben csak, hanem most sokkal inkább az én távollétemben, félelemmel és rettegéssel vigyétek véghez a ti idvességteket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'Mert Isten az, a ki munkálja bennetek mind az akarást, mind a munkálást jó kedvéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'Mindeneket zúgolódások és versengések nélkül cselekedjetek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'Hogy legyetek feddhetetlenek és tiszták, Istennek szeplőtlen gyermekei az elfordult és elvetemedett nemzetség közepette, kik között fényletek, mint csillagok e világon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'Életnek beszédét tartván elébök; hogy dicsekedhessem majd a Krisztus napján, hogy nem futottam hiába, sem nem fáradtam hiába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'De ha kiontatom is italáldozatként a ti hitetek áldozatánál és papiszolgálatánál, mégis örülök, és együtt örülök mindnyájatokkal;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'Azonképen ti is örüljetek, és örüljetek együtt velem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'Reménylem pedig az Úr Jézusban, hogy Timótheust rövid nap elküldöm tihozzátok, hogy én is megviduljak, megértvén a ti dolgaitokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'Mert nincsen velem senki hozzá hasonló indulatú, a ki igazán szívén viselné dolgaitokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'Mert mindenki a maga hasznát keresi, nem a Krisztus Jézusét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'Az ő kipróbált voltát pedig ismeritek, hogy miképen atyjával a gyermek, együtt szolgált velem az evangyéliom ügyében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'Őt azért reménylem, hogy elküldöm, mihelyt meglátom az én dolgaimat, tüstént;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'Bízom pedig az Úrban, hogy magam is csakhamar el fogok menni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'De szükségesnek tartám, hogy Epafróditust, az én atyámfiát és munkatársamat és bajtársamat, néktek pedig követeteket és szükségemben áldozatot hozó szolgátokat hazaküldjem hozzátok;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, 'Mivelhogy vágyva vágyott mindnyájatok után, és gyötrődött a miatt, hogy meghallottátok, hogy ő beteg volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, 'Mert bizony beteg volt, halálhoz közel; de az Isten könyörült rajta, nem csak ő rajta pedig, hanem én rajtam is, hogy szomorúság ne jőjjön szomorúságomra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'Annakokáért hamarabb küldtem őt haza, hogy meglátván őt, ismét örüljetek, és nékem is kisebb legyen a szomorúságom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'Fogadjátok azért őt az Úrban teljes örömmel; és az ilyeneket megbecsüljétek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, 'Mert a Krisztus dolgáért jutott majdnem halálra, koczkára tévén életét, hogy kárpótoljon engem azért, hogy nékem tett szolgálatotoknál ti nem voltatok jelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'Továbbá atyámfiai, örüljetek az Úrban. Ugyanazokat írni néktek én nem restellem, tinéktek pedig bátorságos.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'Őrizkedjetek az ebektől, őrizkedjetek a gonosz munkásoktól, őrizkedjetek a megmetélkedéstől:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'Mert mi vagyunk a körülmetélkedés, a kik lélekben szolgálunk az Istennek, és a Krisztus Jézusban dicsekedünk, és nem a testben bizakodunk:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'Jóllehet énnékem van bizakodásom test szerint is. Ha bárki más mer testben bizakodni, én sokkal inkább;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'Körülmetéltettem nyolczadnapon, Izráel nemzetségéből, Benjámin törzséből való vagyok, zsidókból való zsidó, törvény tekintetében farizeus,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'Buzgóság tekintetében az egyházat üldöző, a törvénybeli igazság tekintetében feddhetetlen voltam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'De a melyek nékem egykor nyereségek valának, azokat a Krisztusért kárnak ítéltem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'Sőt annakfelette most is kárnak ítélek mindent az én Uram, Jézus Krisztus ismeretének gazdagsága miatt: a kiért mindent kárba veszni hagytam és szemétnek ítélek, hogy a Krisztust megnyerjem,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'És találtassam Ő benne, mint a kinek nincsen saját igazságom a törvényből, hanem van igazságom a Krisztusban való hit által, Istentől való igazságom a hit alapján:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'Hogy megismerjem Őt, és az Ő feltámadásának erejét, és az Ő szenvedéseiben való részesülésemet, hasonlóvá lévén az ő halálához;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'Ha valami módon eljuthatnék a halottak feltámadására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Nem mondom, hogy már elértem, vagy hogy már tökéletes volnék; hanem igyekezem, hogy el is érjem, a miért meg is ragadott engem a Krisztus Jézus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Atyámfiai, én enmagamról nem gondolom, hogy már elértem volna:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'De egyet cselekszem, azokat, a melyek hátam megett vannak, elfelejtvén, azoknak pedig, a melyek előttem vannak, nékik dőlvén, czélegyenest igyekszem az Istennek a Krisztus Jézusban onnét felülről való elhívása jutalmára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'Valakik annakokáért tökéletesek vagyunk, ilyen értelemben legyünk: és ha valamiben másképen értetek, az Isten azt is ki fogja jelenteni néktek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'Csakhogy a mire eljutottunk, ugyanabban egy szabály szerint járjunk, ugyanazon értelemben legyünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Legyetek én követőim, atyámfiai, és figyeljetek azokra, a kik úgy járnak, a miképen mi néktek példátok vagyunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'Mert sokan járnak másképen, kik felől sokszor mondtam néktek, most pedig sírva is mondom, hogy a Krisztus keresztjének ellenségei;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'Kiknek végök veszedelem, kiknek Istenök az ő hasok, és a kiknek dicsőségök az ő gyalázatukban van, kik mindig a földiekkel törődnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'Mert a mi országunk mennyekben van, honnét a megtartó Úr Jézus Krisztust is várjuk;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'Ki elváltoztatja a mi nyomorúságos testünket, hogy hasonló legyen az Ő dicsőséges testéhez, amaz Ő hatalmas munkája szerint, mely által maga alá is vethet mindeneket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'Annakokáért szerelmes atyámfiai, a kik után úgy vágyakozom, ti én örömöm és én koronám, ekképen álljatok meg az Úrban, én szerelmeseim!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'Evódiát intem, Sintikhét is intem, hogy egyenlő indulattal legyenek az Úrban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'Igen, kérlek téged is, igaz szolgatársam, légy segítségül ezeknek, mint a kik az evangyéliom dolgában együtt viaskodtak velem, Kelemennel is, és ama többi munkatársaimmal, kiknek neveik fölírvák az életnek könyvében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Örüljetek az Úrban mindenkor; ismét mondom, örüljetek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'A ti szelídlelkűségetek ismert legyen minden ember előtt. Az Úr közel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'Semmi felől ne aggódjatok, hanem imádságotokban és könyörgéstekben minden alkalommal hálaadással tárjátok fel kívánságaitokat az Isten előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'És az Istennek békessége, mely minden értelmet felül halad, meg fogja őrizni szíveiteket és gondolataitokat a Krisztus Jézusban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'Továbbá, Atyámfiai, a mik csak igazak, a mik csak tisztességesek, a mik csak igazságosak, a mik csak tiszták, a mik csak kedvesek, a mik csak jó hírűek; ha van valami erény és ha van valami dícséret, ezekről gondolkodjatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'A miket tanultatok is, el is fogadtatok, hallottatok is, láttatok is én tőlem, azokat cselekedjétek; és a békességnek Istene veletek lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'Felette igen örültem pedig az Úrban, hogy immár valahára megújultatok az én felőlem való gondviseléstekben; mely dologban gondoskodtatok is, de nem volt alkalmatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Nem hogy az én szűkölködésemre nézve szólnék; mert én megtanultam, hogy azokban, a melyekben vagyok, megelégedett legyek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'Tudok megaláztatni is, tudok bővölködni is; mindenben és mindenekben ismerős vagyok a jóllakással is, az éhezéssel is, a bővölködéssel is, a szűkölködéssel is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'Mindenre van erőm a Krisztusban, a ki engem megerősít.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'Mindazáltal jól tettétek, hogy nyomorúságomban részesekké lettetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'Tudjátok pedig ti is, Filippibeliek, hogy az evangyéliom hirdetésének kezdetén, mikor Macedóniából kimentem, egyetlen egyház sem volt részes velem a kölcsönös adásban és vevésben, csak ti egyedül:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'Mert már Thessalónikában is, egyszer is, másszor is, küldtetek nékem szükségemre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Nem mintha kívánnám az ajándékot; hanem kívánom azt a gyümölcsöt, mely sokasodik a ti hasznotokra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'Megkaptam pedig mindent, és bővölködöm; beteltem, vévén Epafróditustól, a mit küldöttetek, mint kedves jó illatot, kellemes, tetsző áldozatot az Istennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'Az én Istenem pedig be fogja tölteni minden szükségeteket az Ő gazdagsága szerint dicsőségesen a Krisztus Jézusban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'Az Istennek pedig és a mi Atyánknak dicsőség mind örökkön örökké. Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Köszöntsetek minden szentet a Krisztus Jézusban. Köszöntenek titeket az atyafiak, a kik velem vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Köszöntenek titeket minden szentek, mindeneknek felette pedig a császár udvarából valók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'A mi Urunk Jézus Krisztusnak kegyelme legyen mindnyájatokkal! Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Pál, Jézus Krisztusnak apostola Isten akaratjából, és Timótheus atyafi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'A Kolosséban levő szenteknek és hívő atyafiaknak a Krisztusban: kegyelem néktek és békesség Istentől, a mi Atyánktól, és az Úr Jézus Krisztustól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, 'Hálát adunk az Istennek és a mi Urunk Jézus Krisztus Atyjának, mindenkor ti értetek könyörögvén,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'Mivelhogy hallottuk a ti hiteteket a Krisztus Jézusban, és a szeretetet, a melylyel minden szentekhez vagytok,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'A mennyekben néktek eltett reménységért, a melyet már előbb hallottatok az igazság beszédében, mely az evangyéliom:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'Mely eljutott hozzátok, miképen az egész világra is, és gyümölcsöt terem, úgy mint nálatok is a naptól fogva, melyen hallottátok és megismertétek az Isten kegyelmét igazán:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'Úgy a hogy tanultátok is Epafrástól, a mi szerelmes szolgatársunktól, a ki hív szolgája ti érettetek a Krisztusnak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'A ki meg is jelentette nékünk a ti Lélekben való szereteteteket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'Azért mi is, a mely naptól fogva ezeket hallottuk, nem szűnünk meg érettetek imádkozni, és kérni, hogy betöltessetek az Isten akaratának megismerésével minden lelki bölcseségben és értelemben,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'Hogy járjatok méltóan az Úrhoz, teljes tetszésére, minden jó cselekedettel gyümölcsöt teremvén és nevekedvén az Isten megismerésében;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'Minden erővel megerősíttetvén az Ő dicsőségének hatalma szerint minden kitartásra és hosszútűrésre örömmel;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'Hálákat adván az Atyának, ki alkalmasakká tett minket a szentek örökségében való részvételre a világosságban;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'A ki megszabadított minket a sötétség hatalmából, és általvitt az Ő szerelmes Fiának országába;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, 'Kiben van a mi váltságunk az Ő vére által, bűneinknek bocsánata;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'A ki képe a láthatatlan Istennek, minden teremtménynek előtte született;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, 'Mert Ő benne teremtetett minden, a mi van a mennyekben és a földön, láthatók és láthatatlanok, akár királyi székek, akár uraságok, akár fejedelemségek, akár hatalmasságok; mindenek Ő általa és Ő reá nézve teremttettek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'És Ő előbb volt mindennél, és minden Ő benne áll fenn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'És Ő a feje a testnek, az egyháznak: a ki a kezdet, elsőszülött a halottak közül; hogy mindenekben Ő legyen az első;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, 'Mert tetszett az Atyának, hogy Ő benne lakozzék az egész teljesség;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'És hogy Ő általa békéltessen meg mindent Magával, békességet szerezvén az Ő keresztjének vére által; Ő általa mindent, a mi csak van, akár a földön, akár a mennyekben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'Titeket is, kik hajdan elidegenültek és ellenségek valátok gonosz cselekedetekben gyönyörködő értelmetek miatt, most mégis megbékéltetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'Az Ő emberi testében a halál által, hogy mint szenteket, tisztákat és feddhetetleneket állasson titeket Ő maga elé:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'Ha ugyan megmaradtok a hitben alaposan és erősen, és el nem távoztok az evangyéliom reménységétől, a melyet hallottatok, a mely hirdettetett minden teremtménynek az ég alatt; a melynek lettem én, Pál, szolgájává.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'Most örülök a ti érettetek való szenvedéseimnek, és a magam részéről betöltöm a mi híja van a Krisztus szenvedéseinek az én testemben az Ő testéért, a mi az egyház;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'A melynek lettem én szolgájává az Isten sáfársága szerint, a melyet nékem adott ti rátok nézve, hogy betöltsem az Isten ígéjét,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, 'Tudniillik ama titkot, mely el vala rejtve ősidők óta és nemzetségek óta, most pedig megjelentetett az Ő szenteinek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, 'A kikkel az Isten meg akarta ismertetni azt, hogy milyen nagy a pogányok között eme titok dicsőségének gazdagsága, az tudniillik, hogy a Krisztus ti köztetek van, a dicsőségnek ama reménysége:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, 'A kit mi prédikálunk, intvén minden embert, és tanítván minden embert minden bölcseséggel, hogy minden embert tökéletesnek állassunk elő a Krisztus Jézusban;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, 'A mire igyekezem is, tusakodván az Ő ereje szerint, mely én bennem hatalmasan munkálkodik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'Mert akarom, hogy tudtotokra legyen, hogy milyen nagy tusakodásom van ti érettetek, és azokért, kik Laodiczeában vannak, és mindazokért, a kik nem láttak engem személy szerint e testben;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'Hogy vígasztalást vegyen az ő szívök, egybeköttetvén a szeretetben, és hogy eljussanak az értelem meggyőződésének teljes gazdagságára, az Isten és az Atya és a Krisztus ama titkának megismerésére,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'A melyben van a bölcsességnek és ismeretnek minden kincse elrejtve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'Ezt pedig azért mondom, hogy valaki titeket rá ne szedjen hitető beszéddel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'Mert jóllehet testben távol vagyok tőletek, mindazáltal lélekben veletek vagyok, örülvén és látván ti köztetek a jó rendet és Krisztusba vetett hiteteknek erősségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'Azért, a miképen vettétek a Krisztus Jézust, az Urat, akképen járjatok Ő benne,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'Meggyökerezvén és tovább épülvén Ő benne, és megerősödvén a hitben, a miképen arra taníttattatok, bővölködvén abban hálaadással.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'Meglássátok, hogy senki ne legyen, a ki bennetek zsákmányt vet a bölcselkedés és üres csalás által, mely emberek rendelése szerint, a világ elemi tanításai szerint, és nem a Krisztus szerint való:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'Mert Ő benne lakozik az istenségnek egész teljessége testileg,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'És ti Ő benne vagytok bételjesedve, a ki feje minden fejedelemségnek és hatalmasságnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, 'A kiben körül is metéltettetek kéz nélkül való körülmetéléssel, levetkezvén az érzéki bűnök testét a Krisztus körülmetélésében;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 'Eltemettetvén Ő vele együtt a keresztségben, a kiben egyetemben fel is támasztattatok az Isten erejébe vetett hit által, a ki feltámasztá Őt a halálból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'És titeket, kik holtak valátok a bűnökben és a ti testeteknek körülmetéletlenségében, megelevenített együtt Ő vele, megbocsátván minden bűnötöket,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'Az által, hogy eltörölte a parancsolatokban ellenünk szóló kézírást, a mely ellenünkre volt nekünk, és azt eltette az útból, odaszegezvén azt a keresztfára;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'Lefegyverezvén a fejedelemségeket és a hatalmasságokat, őket bátran mutogatta, diadalt vévén rajtok abban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'Senki azért titeket meg ne ítéljen evésért, vagy ivásért, avagy ünnep, vagy újhold, vagy szombat dolgában:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, 'Melyek csak árnyékai a következendő dolgoknak, de a valóság a Krisztusé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'Senki tőletek a pálmát el ne vegye, kedvét találván alázatoskodásban és az angyalok tisztelésében, a melyeket nem látott, olyakat tudakozván, ok nélkül felfuvalkodván az ő testének értelmével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'És nem ragaszkodván a Főhöz, a Kiből az egész test, a kapcsok és kötelek által segedelmet vévén és egybeszerkesztetvén, nevekedik az Isten szerint való nevekedéssel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'Ha meghalván a Krisztussal, megszabadultatok e világ elemi tanításaitól, miért terheltetitek magatokat, mintha e világban élők volnátok, efféle rendelésekkel:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, 'Ne fogd meg, meg se kóstold, még csak ne is illesd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, '(A mik mind a velök való élés által elfogyasztásra vannak rendelve), az emberek parancsolatai és tanításai szerint?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, 'A melyek bölcsességnek látszanak ugyan a magaválasztotta istentiszteletben és alázatoskodásban és a test gyötrésében; de nincs bennök semmi becsülni való, mivelhogy a test hízlalására valók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'Annakokáért ha feltámadtatok a Krisztussal, az odafelvalókat keressétek, a hol a Krisztus van, az Istennek jobbján ülvén,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'Az odafelvalókkal törődjetek, nem a földiekkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'Mert meghaltatok, és a ti éltetek el van rejtve együtt a Krisztussal az Istenben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'Mikor a Krisztus, a mi életünk, megjelen, akkor majd ti is, Ő vele együtt, megjelentek dicsőségben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'Öldököljétek meg azért a ti földi tagjaitokat, paráznaságot, tisztátalanságot, bujaságot, gonosz kívánságot és a fösvénységet, a mi bálványimádás;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, 'Melyek miatt jő az Isten haragja az engedetlenség fiaira;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'Melyekben ti is jártatok régenten, mikor éltetek azokban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'Most pedig vessétek el magatoktól ti is mindazokat; haragot, fölgerjedést, gonoszságot és szátokból a káromkodást és gyalázatos beszédet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'Ne hazudjatok egymás ellen, mivelhogy levetkeztétek amaz ó embert, az ő cselekedeteivel együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'És felöltöztétek amaz új embert, melynek újulása van Annak ábrázatja szerint való ismeretre, a ki teremtette azt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'A hol nincs többé görög és zsidó: körülmetélkedés és körülmetélkedetlenség, idegen, scithiai, szolga, szabad, hanem minden és mindenekben Krisztus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'Öltözzetek föl azért mint az Istennek választottai, szentek és szeretettek, könyörületes szívet, jóságosságot, alázatosságot, szelídséget, hosszútűrést;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'Elszenvedvén egymást és megbocsátván kölcsönösen egymásnak, ha valakinek valaki ellen panasza volna; miképen a Krisztus is megbocsátott néktek, akképen ti is;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'Mindezeknek fölébe pedig öltözzétek föl a szeretetet, mint a mely a tökéletességnek kötele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'És az Istennek békessége uralkodjék a ti szívetekben, amelyre el is hívattatok egy testben; és háládatosak legyetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'A Krisztusnak beszéde lakozzék ti bennetek gazdagon, minden bölcsességben; tanítván és intvén egymást zsoltárokkal, dícséretekkel, lelki énekekkel, hálával zengedezvén a ti szívetekben az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'És mindent, a mit csak cselekesztek szóval vagy tettel, mindent az Úr Jézusnak nevében cselekedjetek, hálát adván az Istennek és Atyának Ő általa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'Ti asszonyok, engedelmeskedjetek a ti férjeteknek, a miképen illik az Úrban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'Ti férfiak, szeressétek a ti feleségeteket, és ne legyetek irántok keserű kedvűek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'Ti gyermekek, szót fogadjatok a ti szüleiteknek mindenben; mert ez kedves az Úrnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'Ti atyák, ne bosszantsátok a ti gyermekeiteket, hogy kétségbe ne essenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, 'Ti szolgák, szót fogadjatok mindenben a ti test szerint való uraitoknak, nem a szemnek szolgálván, mint a kik embereknek akarnak tetszeni, hanem szíveteknek egyenességében, félvén az Istent.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'És valamit tesztek, lélekből cselekedjétek, mint az Úrnak és nem embereknek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, 'Tudván, hogy ti az Úrtól veszitek az örökségnek jutalmát: mert az Úr Krisztusnak szolgáltok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, 'A ki pedig igazságtalanságot cselekszik, jutalmát veszi igazságtalanságának; és nincsen személyválogatás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'Ti urak, a mi igazságos és méltányos, a ti szolgáitoknak megadjátok, tudván, hogy néktek is van Uratok mennyekben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'Az imádságban állhatatosak legyetek, vigyázván abban hálaadással;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'Imádkozván egyszersmind mi érettünk is, hogy az Isten nyissa meg előttünk az íge ajtaját, hogy szólhassuk a Krisztus titkát, a melyért fogoly is vagyok;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'Hogy nyilvánvalóvá tegyem azt úgy, a mint nékem szólnom kell.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'Bölcsen viseljétek magatokat a kívül valók irányában, a jó alkalmatosságot áron is megváltván.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'A ti beszédetek mindenkor kellemetes legyen, sóval fűszerezett; hogy tudjátok, hogy mimódon kell néktek kinek-kinek megfelelnetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'Minden én dolgaimat megismerteti veletek Tikhikus, a szeretett atyafi és hív szolga és szolgatárs az Úrban;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'A kit épen a végett küldtem hozzátok, hogy megismerje a ti dolgaitokat és megvígasztalja a ti szíveteket,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'Onézimussal együtt, a hű és szeretett atyafival, ki ti közületek való; minden itt való dolgot megismertetnek ők veletek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'Köszönt titeket Aristárkhus, az én fogolytársam, és Márk, a Barnabás unokatestvére, (ki felől parancsolatokat vettetek: ha hozzátok megy, fogadjátok őt szívesen),');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'És Jézus, kit Justusnak is hívnak, kik a zsidók közül valók: csak ezek azok a munkatársaim az Isten országában, a kik nékem vígasztalásomra voltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, 'Köszönt titeket Epafrás, ki ti közületek való, Krisztusnak szolgája, mindenkor tusakodván ti érettetek imádságaiban, hogy megállhassatok tökéletesen és teljes meggyőződéssel az Istennek minden akaratjában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'Mert bizonyságot teszek ő felőle, hogy sokat fárad érettetek és azokért, kik Laodiczeában és Jerápolisban vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, 'Köszönt titeket Lukács, ama szeretett orvos, és Démás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'Köszöntsétek az atyafiakat, kik Laodiczeában vannak, és Nimfást és a gyülekezetet, mely az ő házánál van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'És mikor felolvastatik nálatok e levél, cselekedjétek meg, hogy a laodiczeaiak gyülekezetében is felolvastassék, és hogy a Laodiczeából átveendő levelet ti is felolvassátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'És mondjátok meg Arkhippusnak: Vigyázz a szolgálatra, melyre vállalkoztál az Úrban, hogy azt betöltsed!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, 'A köszöntés a saját kezemmel, a Páléval, van írva. Emlékezzetek meg az én bilincseimről! A kegyelem veletek. Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'Pál, Silvánus és Timótheus a Thessalonikabeliek gyülekezetének, a mely van az Atya Istenben és az Úr Jézus Krisztusban: kegyelem néktek és békesség Istentől, a mi Atyánktól, és az Úr Jézus Krisztustól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'Hálát adunk az Istennek mindenkor mindnyájatokért, emlékezvén rólatok a mi imádságainkban;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'Szüntelenül emlegetve a ti hitetek munkáját, és a ti szeretetetek fáradozását, és a mi Urunk Jézus Krisztus felől való reménységeteknek állhatatosságát, az Isten előtt, a mi Atyánk előtt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'Tudván, Istentől szeretett atyámfiai, hogy ti ki vagytok választva;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'Hogy a mi evangyéliomunk ti nálatok nem áll csak szóban, hanem isteni erőkben is, Szent Lélekben is, sok bizodalomban is; a miképen tudjátok, hogy milyenek voltunk közöttetek ti érettetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'És ti a mi követőinkké lettetek és az Úréi, befogadván az ígét sokféle szorongattatás között, Szent Lélek örömével;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'Úgy hogy példaképekké lettetek Maczedóniában és Akhájában minden hívőre nézve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Mert nemcsak Maczedóniában és Akhájában zendült ki tőletek az Úr beszéde, hanem minden helyen is híre terjedt a ti Istenben vetett hiteteknek, annyira, hogy szükségtelen arról valamit szólnunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'Mert azok magok hirdetik felőlünk, milyen volt a mi hozzátok való menetelünk, és miként tértetek meg az Istenhez a bálványoktól, hogy az élő és igaz Istennek szolgáljatok,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'És várjátok az Ő Fiát az égből, a kit feltámasztott a halálból, a Jézust, a ki megszabadít minket amaz eljövendő haragtól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, 'Mert magatok tudjátok, atyámfiai, hogy a mi ti hozzátok való menetelünk nem volt hiábavaló;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, 'Sőt inkább, noha elébb már háborúságot és bosszúságot szenvedtünk volt Filippiben, a mint tudjátok, volt bátorságunk a mi Istenünkben, hogy közöttetek is hirdessük az Isten evangyéliomát sok tusakodással.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, 'Mert a mi buzdításunk nem hitetésből van, sem nem tisztátalanságból, sem nem álnokságból:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, 'Hanem a miképen az Isten méltatott minket arra, hogy reánk bízza az evangyéliomot, akképen szólunk; nem úgy, hogy embereknek tessünk hanem az Istennek, a ki megvizsgálja a mi szívünket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, 'Mert sem hízelkedő beszéddel, a mint tudjátok, sem telhetetlenség színében nem léptünk fel soha, Isten a bizonyság;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'Sem emberektől való dicsőítést nem kerestünk, sem tőletek, sem másoktól, holott terhetekre lehettünk volna, mint Krisztus apostolai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, 'De szívélyesek valánk ti közöttetek, a miként a dajka dajkálgatja az ő gyermekeit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'Így felbuzdulva irántatok, készek valánk közleni veletek nemcsak az Isten evangyéliomát, hanem a mi magunk lelkét is, mivelhogy szeretteinkké lettetek nékünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, 'Emlékezhettek ugyanis atyámfiai a mi fáradozásunkra és bajlakodásunkra: mert éjjel-nappal munkálkodva hirdettük néktek az Isten evangyéliomát, csakhogy senkit meg ne terheljünk közületek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'Ti vagytok bizonyságok és az Isten, milyen szentül, igazán és feddhetetlenül éltünk előttetek, a kik hisztek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, 'Valamint tudjátok, hogy miként atya az ő gyermekeit, úgy intettünk és buzdítgattunk egyenként mindnyájatokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, 'És kérve kértünk, hogy Istenhez méltóan viseljétek magatokat, a ki az ő országába és dicsőségébe hív titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'Ugyanazért mi is hálát adunk az Istennek szüntelenül, hogy ti befogadván az Istennek általunk hirdetett beszédét, nem úgy fogadtátok, mint emberek beszédét, hanem mint Isten beszédét (a minthogy valósággal az is), a mely munkálkodik is ti bennetek, a kik hisztek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, 'Mert ti, atyámfiai, követői lettetek az Isten gyülekezeteinek, a melyek Júdeában vannak a Krisztus Jézusban, mivelhogy ugyanúgy szenvedtetek ti is a saját honfitársaitoktól, miként azok is a zsidóktól,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'A kik megölték az Úr Jézust is és a saját prófétáikat, és minket is üldöznek, és az Istennek nem tetszenek, és minden embernek ellenségei;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, 'A kik megtiltják nékünk, hogy a pogányoknak ne prédikáljunk hogy üdvözüljenek; hogy mindenkor betöltsék bűneiket; de végre utólérte őket az Isten haragja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, 'Mi pedig, atyámfiai, a mint elszakasztatánk tőletek egy kevés ideig, arczra, nem szívre nézve, annál buzgóságosabban, nagy kívánsággal igyekeztünk, hogy szemtől-szemben láthassunk titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, 'Azért menni is akartunk hozzátok, kiváltképen én Pál, egyszer is, kétszer is, de megakadályozott minket a Sátán.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, 'Mert kicsoda a mi reménységünk, örömünk és dicsekedésünk koronája? Avagy nem azok lesztek-é ti is a mi Urunk Jézus Krisztus előtt az ő eljövetelekor?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, 'Bizony ti vagytok a mi dicsőségünk és örömünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'Annakokáért, mivelhogy tovább már el nem tűrhetők, jónak ítélénk, hogy magunk maradjunk Athénében,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'És elküldöttük Timótheust, a mi atyánkfiát és Istennek szolgáját és munkatársunkat a Krisztus evangyéliomának hirdetésében, hogy erősítsen titeket és intsen titeket a ti hitetek felől;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'Hogy senki meg ne tántorodjék ama szorongattatások között; mert ti magatok tudjátok, hogy mi arra rendeltettünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, 'Mert mikor közöttetek valánk is, előre megmondtuk néktek, hogy szorongattatásnak leszünk kitéve; a mint meg is történt, és tudjátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'Annakokáért én is, mivelhogy tovább már nem tűrhetém, elküldék, hogy megismerjem a ti hiteteket, ha nem kísértett-é meg valami módon titeket a kísértő, és nem lett-é hiábavaló a mi fáradságunk?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, 'Most pedig, a mikor megérkezett hozzánk Timótheus ti tőletek, és örömhírt hozott nékünk a ti hitetek és szeretetetek felől, és arról, hogy jó emlékezéssel vagytok irántunk, mindenkor kívánván látni minket, miképen mi is titeket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, 'Ezáltal megvígasztalódtunk reátok nézve, atyámfiai, minden mi szorongattatásunk és szükségünk mellett is, a ti hitetek által:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'Mert szinte megelevenedünk, ha ti erősek vagytok az Úrban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'Mert milyen hálával is fizethetünk az Istennek ti érettetek, mindazért az örömért, a melylyel örvendezünk miattatok a mi Istenünk előtt?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'Mikor éjjel-nappal nagy buzgón esedezünk, hogy megláthassuk a ti orczátokat, és kipótolhassuk a ti hitetek hiányait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'Maga pedig az Isten és a mi Atyánk, és a mi Urunk a Jézus Krisztus egyengesse meg a mi útunkat ti hozzátok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'Titeket pedig gyarapítson az Úr és tegyen bőségesekké az egymás iránt és mindenki iránt való szeretetben, a milyenek vagyunk mi is ti irántatok;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'Hogy erősekké tegye a ti szíveteket, feddhetetlenekké a szentségben, a mi Istenünk és Atyánk előtt, a mikor eljő a mi Urunk Jézus Krisztus minden ő szenteivel egyetemben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'Továbbá pedig kérünk titeket, atyámfiai, és intünk az Úr Jézusban, hogy a szerint, a mint tőlünk tanultátok, mimódon kell forgolódnotok és Istennek tetszenetek: mindinkább gyarapodjatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, 'Mert tudjátok, milyen parancsolatokat adtunk néktek az Úr Jézus által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'Mert ez az Isten akaratja, a ti szentté lételetek, hogy magatokat a paráznaságtól megtartóztassátok;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, 'Hogy mindenitek szentségben és tisztességben tudja bírni a maga edényét,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, 'Nem kívánság gerjedelmével, mint a pogányok, a kik nem ismerik az Istent;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'Hogy senki túl ne lépjen és meg ne károsítsa valamely dologban az ő atyjafiát: mert bosszút áll az Úr mindezekért, a mint elébb is mondottuk néktek és bizonyságot tettünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, 'Mert nem tisztátalanságra, hanem szentségre hívott el minket az Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'A ki azért megveti ezeket, nem embert vet meg, hanem az Istent, a ki Szent Lelkét is közlé velünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, 'Az atyafiúi szeretetről pedig nem is szükség írnom néktek: mert titeket Isten maga tanított meg arra, hogy egymást szeressétek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'Sőt gyakoroljátok is azt mindamaz atyafiak iránt, a kik egész Maczedóniában vannak. Kérünk azonban titeket atyámfiai, hogy mindinkább gyarapodjatok;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, 'És becsületbeli dolognak tartsátok, hogy csendes életet folytassatok, saját dolgaitoknak utána lássatok, és tulajdon kezeitekkel munkálkodjatok, a miként rendeltük néktek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'Hogy a kívülvalók iránt tisztességesen viselkedjetek, és semmi szükséget ne érezzetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, 'Nem akarom továbbá, atyámfiai, hogy tudatlanságban legyetek azok felől, a kik elaludtak, hogy ne bánkódjatok, mint a többiek, a kiknek nincsen reménységök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, 'Mert ha hisszük, hogy Jézus meghalt és feltámadott, azonképen az Isten is előhozza azokat, a kik elaludtak, a Jézus által ő vele együtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, 'Mert ezt mondjuk néktek az Úr szavával, hogy mi, a kik élünk, a kik megmaradunk az Úr eljöveteléig, épen nem előzzük meg azokat, a kik elaludtak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'Mert maga az Úr riadóval, arkangyal szózatával és isteni harsonával leszáll az égből: és feltámadnak először a kik meghaltak volt a Krisztusban;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, 'Azután mi, a kik élünk, a kik megmaradunk, elragadtatunk azokkal együtt a felhőkön az Úr elébe a levegőbe; és ekképen mindenkor az Úrral leszünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, 'Annakokáért vígasztaljátok egymást e beszédekkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, 'Az időkről és időszakokról pedig, atyámfiai, nem szükség, hogy írjak néktek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, 'Mert igen jól tudjátok ti magatok, hogy az Úrnak napja úgy jő el, mint a tolvaj éjjel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, 'Mert a mikor ezt mondják: Békesség és biztonság, akkor hirtelen veszedelem jön rájok, mint a szülési fájdalom a terhes asszonyra; és semmiképen meg nem menekednek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'De ti, atyámfiai, nem vagytok sötétségben, hogy az a nap tolvaj módra lephetne meg titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'Ti mindnyájan világosság fiai vagytok és nappal fiai; nem vagyunk az éjszakáé, sem a sötétségé!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'Ne is aludjunk azért, mint egyebek, hanem legyünk éberek és józanok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, 'Mert a kik alusznak, éjjel alusznak; és a kik részegek, éjjel részegednek meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'Mi azonban, a kik nappaliak vagyunk, legyünk éberek, felöltözvén a hitnek és szeretetnek mellvasába, és sisak gyanánt az üdvösségnek reménységébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'Mert nem haragra rendelt minket az Isten, hanem arra, hogy üdvösséget szerezzünk a mi Urunk Jézus Krisztus által,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, 'A ki meghalt érettünk, hogy akár ébren vagyunk, akár aluszunk, együtt éljünk ő vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, 'Vígasztaljátok azért egymást, és építse egyik a másikat, a miképen cselekeszitek is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, 'Kérünk továbbá titeket atyámfiai, hogy becsüljétek azokat, a kik fáradoznak közöttetek, és előljáróitok az Úrban, és intenek titeket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'És az ő munkájokért viseltessetek irántok megkülönböztetett szeretettel. Egymással békességben éljetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, 'Kérünk továbbá titeket, atyámfiai, intsétek a rendetleneket, bátorítsátok a félelmes szívűeket, gyámolítsátok az erőteleneket, türelmesek legyetek mindenki iránt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, 'Vigyázzatok, hogy senki senkinek rosszért rosszal ne fizessen; hanem mindenkor jóra törekedjetek úgy egymás iránt, mint mindenki iránt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, 'Mindenkor örüljetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, 'Szüntelen imádkozzatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, 'Mindenben hálákat adjatok; mert ez az Isten akarata a Krisztus Jézus által ti hozzátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, 'A Lelket meg ne oltsátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, 'A prófétálást meg ne vessétek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, 'Mindent megpróbáljatok; a mi jó, azt megtartsátok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 22, 'Mindentől, a mi gonosznak látszik, őrizkedjetek!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 23, 'Maga pedig a békességnek Istene szenteljen meg titeket mindenestől; és a ti egész valótok, mind lelketek, mind testetek feddhetetlenül őriztessék meg a mi Urunk Jézus Krisztus eljövetelére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 24, 'Hű az, a ki elhivott titeket és ő meg is cselekszi azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 25, 'Atyámfiai, imádkozzatok érettünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 26, 'Köszöntsétek az összes atyafiakat szent csókolással.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 27, 'Kényszerítlek titeket az Úrra, hogy olvastassék fel e levél minden szent atyafi előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 28, 'A mi Urunk Jézus Krisztusnak kegyelme veletek! Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Pál és Silvánus és Timótheus a Thessalonikabeli gyülekezetnek, Istenben, a mi Atyánkban, és az Úr Jézus Krisztusban:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'Kegyelem néktek és békesség Istentől, a mi Atyánktól, és az Úr Jézus Krisztustól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'Mindenkor hálaadással tartozunk az Istennek, atyámfiai, ti érettetek, a miképen méltó is, mivelhogy felettébb megnövekedék a ti hitetek, és mindnyájatokban bővölködik az egymáshoz való szeretet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'Annyira, hogy mi magunk dicsekszünk veletek az Isten gyülekezeteiben, a ti kitartástok és hitetek felől, minden ti üldöztetéstek és szorongattatástok között, a melyeket szenvedtek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'Bizonyságául az Isten igazságos ítéletének; hogy méltóknak ítéltessetek az Isten országára, a melyért szenvedtek is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'Mert igazságos dolog az az Isten előtt, hogy szorongattatással fizessen azoknak, a kik titeket szorongatnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'Néktek pedig, a kik szorongattattok, nyugodalommal mivelünk együtt, a mikor megjelenik az Úr Jézus az égből az ő hatalmának angyalaival.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'Tűznek lángjában, ki bosszút áll azokon, a kik nem ismerik az Istent, és a kik nem engedelmeskednek a mi Urunk Jézus Krisztus evangyéliomának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'A kik meg fognak lakolni örök veszedelemmel az Úr ábrázatától, és az ő hatalmának dicsőségétől,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'A mikor eljő majd, hogy megdicsőíttessék az ő szenteiben, és csodáltassék mindazokban, a kik hisznek (mivelhogy a mi tanúbizonyságunknak hitele volt ti nálatok) ama napon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'Mivégből imádkozunk is mindenkor ti érettetek, hogy a mi Istenünk méltóknak tartson titeket az elhívásra, és töltsön be titeket a jóban való teljes gyönyörűséggel, és a hitnek hathatós munkálásával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'Hogy dicsőíttessék meg a mi Urunk Jézus Krisztusnak neve ti bennetek, és ti is ő benne, a mi Istenünknek és az Úr Jézus Krisztusnak kegyelméből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, 'Kérünk pedig titeket, atyámfiai, a mi Urunk Jézus Krisztus eljövetelére és a mi ő hozzá leendő egybegyűlésünkre nézve,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, 'Hogy ne tántoríttassatok el egyhamar a ti értelmetektől, se ne háboríttassatok meg, se lélek által, se beszéd által, se nékünk tulajdonított levél által, mintha itt volna már a Krisztusnak ama napja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, 'Ne csaljon meg titeket senki semmiképen. Mert nem jön az el addig, mígnem bekövetkezik elébb a szakadás, és megjelenik a bűn embere, a veszedelemnek fia,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, 'A ki ellene veti és fölébe emeli magát mindannak, a mi Istennek vagy istentiszteletre méltónak mondatik, annyira, hogy maga ül be mint Isten az Isten templomába, Isten gyanánt mutogatván magát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'Nem emlékeztek-é, hogy megmondtam néktek ezeket, a mikor még ti nálatok valék?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, 'És most tudjátok, mi tartja vissza, a miért csak a maga idejében fog az megjelenni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, 'Működik ugyan már a törvényszegés titkos bűne: csakhogy annak, a ki azt még most visszatartja, félre kell az útból tolatnia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'És akkor fog megjelenni a törvénytaposó, a kit megemészt az Úr az ő szájának lehelletével, és megsemmisít az ő megjelenésének feltűnésével;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, 'A kinek eljövetele a Sátán ereje által van, a hazugságnak minden hatalmával, jeleivel és csodáival,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, 'És a gonoszságnak minden csalárdságával azok között, a kik elvesznek; mivelhogy nem fogadták be az igazságnak szeretetét az ő idvességökre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'És azért bocsátja reájok Isten a tévelygés erejét, hogy higyjenek a hazugságnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'Hogy kárhoztattassanak mindazok, a kik nem hittek az igazságnak, hanem gyönyörködtek az igazságtalanságban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'Mi pedig mindenkor hálaadással tartozunk az Istennek ti érettetek atyámfiai, a kiket szeret az Úr, hogy kezdettől fogva kiválasztott titeket Isten az üdvösségre, a Lélek szentelésében és az igazság hitében;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'A mire elhívott titeket a mi evangyéliomunk által, a mi Urunk Jézus Krisztus dicsőségének elvételére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'Miért is atyámfiai, legyetek állhatatosak és tartsátok meg a tudományt, a melyre akár beszédünk, akár levelünk által taníttattatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, 'Maga pedig a mi Urunk Jézus Krisztus, és az Isten a mi Atyánk, a ki szeretett minket és kegyelméből örök vígasztalással és jó reménységgel ajándékozott meg,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 17, 'Vígasztalja meg a ti szíveteket, és erősítsen meg titeket minden tudományban és jó cselekedetben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'Végezetre imádkozzatok értünk atyámfiai, hogy az Úrnak beszéde terjedjen és dicsőíttessék, a miként ti köztetek is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'És hogy meneküljünk meg az alkalmatlan és gonosz emberektől. Mert nem mindenkié a hit!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'De hű az Úr, a ki megerősít titeket és megőriz a gonosztól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'Bízunk is az Úrban reátok nézve, hogy megteszitek és meg is fogjátok tenni azokat, a miket parancsolunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'Az Úr pedig igazgassa a ti szíveteket az Isten iránt való szeretetre, és Krisztus iránt való állhatatosságra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, 'A mi Urunk Jézus Krisztus nevében pedig, rendeljük néktek, atyámfiai, hogy vonjátok el magatokat minden atyafitól, a ki rendetlenül él, és nem ama utasítás szerint, a melyet mi tőlünk kapott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, 'Magatok is tudjátok, mimódon kell minket követni; mert nem viseltük magunkat közöttetek rendetlenül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, 'Sem ingyen kenyeret nem ettünk senkinél, hanem munkával és fáradsággal, éjjel-nappal dolgozva, hogy közületek senkinek se legyünk terhére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'Nem azért, mintha nem volna rá jogunk, hanem hogy magunkat például adjuk néktek, hogy minket kövessetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'Mert a mikor nálatok voltunk is, azt rendeltük néktek, hogy ha valaki nem akar dolgozni, ne is egyék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, 'Mert halljuk, hogy némelyek rendetlenül élnek közületek, a kik semmit nem dolgoznak, hanem nyughatatlankodnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, 'Az ilyeneknek azonban rendeljük és kérjük őket a mi Urunk Jézus Krisztusra, hogy csendesen munkálkodva, a magok kenyerét egyék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, 'Ti pedig, atyámfiai, meg ne restüljetek a jó cselekvésben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'Ha pedig valaki nem engedelmeskedik a mi levél által való beszédünknek, azt jegyezzétek meg; és ne társalkodjatok vele, hogy megszégyenüljön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, 'De ne tartsátok ellenségnek, hanem intsétek, mint atyafit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, 'Maga pedig a békességnek Ura adjon néktek mindenkor minden tekintetben békességet. Az Úr legyen mindnyájatokkal!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, 'A köszöntést én Pál írom a saját kezemmel, a mi ismertető jegye minden levelemnek. Így írok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, 'A mi Urunk Jézus Krisztusnak kegyelme mindnyájatokkal! Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'Pál, Jézus Krisztus apostola a mi megtartó Istenünknek, és Jézus Krisztusnak a mi reménységünknek rendelése szerint,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'Timótheusnak, az én igaz fiamnak a hitben: Kegyelem, irgalmasság és békesség Istentől, a mi Atyánktól, és Krisztus Jézustól, a mi Urunktól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'A miképpen Maczedóniába menetelemkor kértelek téged, hogy maradj Efézusban, hogy megmondjad némelyeknek, ne tanítsanak más tudományt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'Se mesékkel és végehossza nélkül való nemzetségi táblázatokkal ne foglalkozzanak, a melyek inkább versengéseket támasztanak, mint Istenben való épülést a hit által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'A parancsolatnak vége pedig a tiszta szívből, jó lelkiismeretből és igaz hitből való szeretet:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'Melyektől némelyek eltévelyedvén, hiábavaló beszédre hajlottak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'Kik törvénytanítók akarván lenni, nem értik, sem a miket beszélnek, sem a miket erősítgetnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'Tudjuk pedig, hogy a törvény jó, ha valaki törvényszerűen él vele,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'Tudván azt, hogy a törvény nem az igazért van, hanem a törvénytaposókért és engedetlenekért, az istentelenekért és bűnösökért, a latrokért és fertelmesekért, az atya- és anyagyilkosokért, emberölőkért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'Paráznákért, férfifertőztetőkért, emberrablókért, hazugokért, hamisan esküvőkért, és a mi egyéb csak az egészséges tudománynyal ellenkezik,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'A boldog Isten dicsőségének evangyélioma szerint, mely reám bízatott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'És hálát adok annak, a ki engem megerősített, a Krisztus Jézusnak, a mi Urunknak, hogy engem hívnek ítélt, rendelvén a szolgálatra,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'Ki előbb istenkáromló, üldöző és erőszakoskodó valék: de könyörült rajtam, mert tudatlanul cselekedtem hitetlenségben;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'Szerfelett megsokasodott pedig a mi Urunknak kegyelme a Krisztus Jézusban való hittel és szeretettel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'Igaz beszéd ez és teljes elfogadásra méltó, hogy Krisztus Jézus azért jött e világra, hogy megtartsa a bűnösöket, a kik közül első vagyok én.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'De azért könyörült rajtam, hogy Jézus Krisztus bennem mutassa meg legelőbb a teljes hosszútűrését, példa gyanánt azoknak, a kik hiendenek ő benne az örök életre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'Az örökkévaló királynak pedig, a halhatatlan, láthatatlan, egyedül bölcs Istennek tisztesség és dicsőség örökkön örökké! Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'Ezt a parancsolatot adom néked, fiam Timótheus, a rólad való korábbi jövendölések szerint, hogy vitézkedjél azokban ama jó vitézséggel,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'Megtartván a hitet és jó lelkiismeretet, melyet némelyek elvetvén, a hit dolgában hajótörést szenvedtek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'Kik közül való Himenéus és Alexander, kiket átadtam a sátánnak, hogy megtanulják, hogy ne káromkodjanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'Intelek azért mindenek előtt, hogy tartassanak könyörgések, imádságok, esedezések, hálaadások minden emberekért,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'Királyokért és minden méltóságban levőkért, hogy csendes és nyugodalmas életet éljünk, teljes istenfélelemmel és tisztességgel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'Mert ez jó és kedves dolog a mi megtartó Istenünk előtt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'A ki azt akarja, hogy minden ember idvezüljön és az igazság ismeretére eljusson.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'Mert egy az Isten, egy a közbenjáró is Isten és emberek között, az ember Krisztus Jézus,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'A ki adta önmagát váltságul mindenekért, mint tanúbizonyság a maga idejében,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'A mi végett rendeltettem én hirdetővé és apostollá (igazságot szólok a Krisztusban, nem hazudok), pogányok tanítójává hitben és igazságban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'Akarom azért, hogy imádkozzanak a férfiak minden helyen, tiszta kezeket emelvén föl harag és versengés nélkül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'Hasonlatosképen az asszonyok tisztességes öltözetben, szemérmetességgel és mértékletességgel ékesítsék magokat; nem hajfonatokkal és aranynyal vagy gyöngyökkel, vagy drága öltözékkel,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'Hanem, a mint illik az istenfélelmet valló asszonyokhoz, jó cselekedetekkel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'Az asszony csendességben tanuljon teljes engedelmességgel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'A tanítást pedig nem engedem meg az asszonynak, sem hogy a férfin uralkodjék, hanem legyen csendességben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'Mert Ádám teremtetett elsőnek, azután Éva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'És Ádám nem csalattatott meg, hanem az asszony megcsalattatván, bűnbe esett:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'Mindazáltal megtartatik a gyermekszüléskor, ha megmaradnak a hitben és szeretetben és a szent életben mértékletességgel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'Igaz ez a beszéd: Ha valaki püspökséget kiván, jó dolgot kíván.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'Szükséges annakokáért, hogy a püspök feddhetetlen legyen, egy feleségű férfiú, józan, mértékletes illedelmes, vendégszerető, a tanításra alkalmatos;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'Nem borozó, nem verekedő, nem rút nyereségre vágyó; hanem szelíd, versengéstől ment, nem pénzsóvárgó;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'Ki a maga házát jól igazgatja, gyermekeit engedelmességben tartja, minden tisztességgel;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, '(Mert ha valaki az ő tulajdon házát nem tudja igazgatni, mimódon visel gondot az Isten egyházára?)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'Ne legyen új ember, nehogy felfuvalkodván, az ördög kárhozatába essék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'Szükséges pedig, hogy jó bizonysága is legyen a kívülvalóktól; hogy gyalázatba és az ördög tőribe ne essék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'Hasonlóképpen a diakónusok tisztességesek legyenek, nem kétnyelvűek, nem sok borivásba merültek, nem rút nyereségre vágyók;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'Kiknél megvan a hit titka tiszta lelkiismerettel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'És ezek is először megpróbáltassanak, azután szolgáljanak, ha feddhetetlenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'Feleségeik hasonlóképen tisztességesek, nem patvarkodók, józanok, mindenben hívek legyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'A diakónusok egy feleségű férfiak legyenek, a kik gyermekeiket és tulajdon házaikat jól igazgatják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'Mert a kik jól szolgálnak, szép tisztességet szereznek magoknak, és sok bizodalmat a Jézus Krisztusban való hitben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'Ezeket írom néked, remélvén, hogy nem sokára hozzád megyek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'De ha késném, hogy tudd meg, mimódon kell forgolódni az Isten házában, mely az élő Istennek egyháza, az igazságnak oszlopa és erőssége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'És minden versengés nélkül nagy a kegyességnek eme titka: Isten megjelent testben, megigazíttatott lélekben, megláttatott az angyaloktól, hirdettetett a pogányok közt, hittek benne a világon, felvitetett dicsőségbe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'A Lélek pedig nyilván mondja, hogy az utolsó időben némelyek elszakadnak a hittől, hitető lelkekre és gonosz lelkek tanításaira figyelmezvén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'Hazug beszédűeknek képmutatása által, kik meg vannak bélyegezve a saját lelkiismeretökben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'A kik tiltják a házasságot, sürgetik az eledelektől való tartózkodást, melyeket Isten teremtett hálaadással való élvezésre a hívőknek és azoknak, a kik megismerték az igazságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'Mert Istennek minden teremtett állata jó, és semmi sem megvetendő, ha hálaadással élnek azzal;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'Mert megszenteltetik Istennek ígéje és könyörgés által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'Ezeket ha eleikbe adod az atyafiaknak, Krisztus Jézusnak jó szolgája leszel, táplálkozván a hitnek és jó tudománynak beszédeivel, a melyet követtél;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'A szentségtelen és vénasszonyos meséket pedig eltávoztasd. Hanem gyakorold magadat a kegyességre:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'Mert a test gyakorlásának kevés haszna van; de a kegyesség mindenre hasznos, meglévén benne a jelenvaló és a jövő életnek ígérete.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'Igaz ez a beszéd, és méltó, hogy mindenképpen elfogadjuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'Mert azért fáradunk és szenvedünk szidalmakat, mivelhogy reménységünket vetettük az élő Istenben, a ki minden embernek megtartója, kiváltképen a hívőknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'Ezeket hirdessed és tanítsad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Senki a te ifjúságodat meg ne vesse, hanem légy példa a hívőknek a beszédben, a magaviseletben, a szeretetben, a lélekben, a hitben, a tisztaságban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'A míg oda megyek, legyen gondod a felolvasásra, az intésre és a tanításra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'Meg ne vesd a kegyelemnek benned való ajándékát, a mely adatott néked prófétálás által, a presbitérium kezeinek reád tevésével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'Ezekről gondoskodjál, ezeken légy, hogy előhaladásod nyilvánvaló legyen mindenek előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'Gondot viselj magadról és a tudományról; maradj meg azokban; mert ezt cselekedvén, mind magadat megtartod, mind a te hallgatóidat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'Az idősb embert ne dorgáld meg, hanem intsed mint atyádat; az ifjabbakat mint atyádfiait;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'Az idősb asszonyokat mint anyákat; az ifjabbakat mint nőtestvéreidet, teljes tisztasággal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'Az özvegyasszonyokat, a kik valóban özvegyek, tiszteld.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'Ha pedig valamely özvegyasszonynak gyermekei vagy unokái vannak, tanulják meg, hogy első sorban a maguk háza iránt legyenek istenfélők, és adják meg szüleiknek a viszont tartozást; mert ez szép és kedves dolog Isten előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'A valóban özvegy és magára hagyatott asszony pedig reménységét az Istenben veti, és foglalatos a könyörgésekben és imádságokban éjjel és nappal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'A bujálkodó pedig élvén megholt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'És ezeket hirdesd, hogy feddhetetlenek legyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'Ha pedig valaki az övéiről és főképen az ő házanépéről gondot nem visel: a hitet megtagadta, és rosszabb a hitetlennél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'Özvegyasszonyul hatvan éven alul levő meg ne választassék; egy férj felesége lett légyen,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'A kinek jó cselekedetekről bizonysága van; ha gyermeket nevelt, ha vendéglátó volt, ha a szentek lábait mosta, ha a nyomorultakon segített, ha minden jó cselekedetben foglalatos vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'A fiatalabb özvegyasszonyokat pedig mellőzd; mert ha gerjedeznek Krisztus ellenére, férjhez akarnak menni:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'Ezeknek ítélete megvan, mivelhogy az első hitet megvetették.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'Egyszersmind pedig dologkerülők lévén, megtanulják a házról-házra való járogatást; sőt nemcsak dologkerülők, hanem fecsegők is és más dolgába avatkozók, olyanokat szólván, a miket nem kellene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'Akarom tehát, hogy a fiatalabbak férjhez menjenek, gyermekeket szűljenek, háztartást vigyenek, és semminemű alkalmat se adjanak az ellenségnek a szidalmazásra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'Mert némelyek már elhajlottak a Sátánhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'Ha valamely hívő férfinak vagy nőnek vannak özvegyei, segítse azokat, és ne terheltessék meg a gyülekezet; hogy azokat segíthesse, a kik valóban özvegyek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'A jól forgolódó presbiterek kettős tisztességre méltattassanak, főképen a kik a beszédben és tanításban fáradoznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'Mert azt mondja az Írás: A nyomtató ökörnek ne kösd be a száját; és: Méltó a munkás a maga jutalmára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'Presbiter ellen vádat ne fogadj el, hanem csak két vagy három tanúbizonyságra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'A vétkeseket mindenek előtt fedd meg, hogy a többiek is megfélemljenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Kérve kérlek az Istenre és Krisztus Jézusra és a kiválasztott angyalokra, hogy ezeket tartsd meg előítélet nélkül, semmit sem cselekedvén részrehajlásból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'A kézrátevést el ne hirtelenkedd, se ne légy részes a más bűneiben; tenmagadat tisztán tartsd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, 'Ne légy tovább vízivó, hanem élj egy kevés borral, gyomrodra és gyakori gyengélkedésedre való tekintetből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'Némely embereknek a bűnei nyilvánvalók, előttök mennek az ítéletre; némelyeket pedig hátul követnek is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'Hasonlóképen a jó cselekedetek is nyilvánvalók; és a melyek másképen vannak, azok sem titkolhatók el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'A kik iga alatt vannak mint szolgák, az ő uraikat minden tisztességre méltóknak tekintsék, hogy Isten neve és a tudomány ne káromoltassék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'A kiknek pedig hívő uraik vannak, azokat meg ne vessék, mivelhogy atyafiak; hanem annál inkább szolgáljanak, mivelhogy hívők és szeretettek, kik a jótevésben buzgólkodnak. Ezekre taníts és ints.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'Ha valaki másképen tanít, és nem követi a mi Urunk Jézus Krisztus egészséges beszédeit és a kegyesség szerint való tudományt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'Az felfuvalkodott, a ki semmit sem ért, hanem vitatkozásokban és szóharczokban szenved, a melyekből származik irígység, viszálykodás, káromlások, rosszakaratú gyanúsítások,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'Megbomlott elméjű és az igazságtól megfosztott embereknek hiábavaló torzsalkodásai a kik az istenfélelmet nyerekedésnek tekintik. Azoktól, a kik ilyenek, eltávozzál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'De valóban nagy nyereség az Istenfélelem, megelégedéssel;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'Mert semmit sem hoztunk a világra, világos, hogy ki sem vihetünk semmit;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'De ha van élelmünk és ruházatunk, elégedjünk meg vele.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'A kik pedig meg akarnak gazdagodni, kísértetbe meg tőrbe és sok esztelen és káros kívánságba esnek, melyek az embereket veszedelembe és romlásba merítik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'Mert minden rossznak gyökere a pénz szerelme: mely után sóvárogván némelyek eltévelyedtek a hittől, és magokat általszegezték sok fájdalommal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'De te, óh Istennek embere, ezeket kerüld; hanem kövessed az igazságot, az istenfélelmet, a hitet, a szeretetet, a békességes tűrést, a szelídséget.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'Harczold meg a hitnek szép harczát, nyerd el az örök életet, a melyre hívattattál, és szép vallástétellel vallást tettél sok bizonyság előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'Meghagyom néked Isten előtt, a ki megelevenít mindeneket, és Krisztus Jézus előtt, a ki bizonyságot tett Ponczius Pilátus alatt ama szép vallástétellel,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'Hogy tartsd meg a parancsolatot mocsoktalanul, feddhetetlenül a mi Urunk Jézus Krisztus megjelenéséig,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'A mit a maga idejében megmutat ama boldog és egyedül hatalmas, a királyoknak Királya és az uraknak Ura,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'Kié egyedül a halhatatlanság, a ki hozzáférhetetlen világosságban lakozik; a kit az emberek közül senki nem látott, sem nem láthat: a kinek tisztesség és örökké való hatalom. Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'Azoknak, a kik gazdagok e világon, mondd meg, hogy ne fuvalkodjanak fel, se ne reménykedjenek a bizonytalan gazdagságban, hanem az élő Istenben, a ki bőségesen megad nékünk mindent a mi tápláltatásunkra;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'Hogy jót tegyenek, legyenek gazdagok a jó cselekedetekben, legyenek szíves adakozók, közlők,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 'Kincset gyűjtvén magoknak jó alapul a jövőre, hogy elnyerjék az örök életet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, 'Óh Timótheus, őrizd meg a mi rád van bízva, elfordulván a szentségtelen üres beszédektől és a hamis nevű ismeretnek ellenvetéseitől;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, 'A melylyel némelyek kevélykedvén, a hit mellől eltévelyedtek. Kegyelem veled! Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Pál, Jézus Krisztusnak apostola, Isten akaratából, a Krisztus Jézusban való életnek ígérete szerint,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'Timótheusnak, az én szeretett fiamnak: kegyelem, irgalmasság, békesség az Atya Istentől és Krisztus Jézustól, a mi Urunktól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'Hálát adok az Istennek, a kinek szolgálok őseimtől fogva tiszta lelkiismerettel, hogy szüntelen gondolok reád könyörgéseimben éjjel és nappal,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'Kívánván téged látni, megemlékezvén a te könyhullatásaidról, hogy örömmel teljesedjem be;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'Eszembe jutván a benned levő, képmutatás nélkül való hit, a mely lakozott először a te nagyanyádban Loisban és anyádban Eunikában; meg vagyok azonban győződve, hogy benned is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'Minekokáért emlékeztetlek téged, hogy gerjeszd fel az Isten kegyelmi ajándékát, a mely benned van az én kezeimnek rád tétele által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'Mert nem félelemnek lelkét adott nékünk az Isten; hanem erőnek és szeretetnek és józanságnak lelkét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'Ne szégyeneld hát a mi Urunk bizonyságtételét, se engem az ő foglyát; hanem együtt szenvedj az evangyéliomért Istennek hatalma szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'A ki megtartott minket és hívott szent hívással, nem a mi cselekedeteink szerint, hanem az ő saját végezése és kegyelme szerint, mely adatott nékünk Krisztus Jézusban örök időknek előtte,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'Megjelentetett pedig most a mi Megtartónknak, Jézus Krisztusnak megjelenése által, a ki eltörölte a halált, világosságra hozta pedig az életet és halhatatlanságot az evangyéliom által,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'Amelyre nézve tétettem én hirdetővé és apostollá és pogányok tanítójává.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'A miért szenvedem ezeket is: de nem szégyenlem; mert tudom, kinek hittem, és bizonyos vagyok benne, hogy ő az én nála letett kincsemet meg tudja őrizni ama napra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'Az egészséges beszédeknek példáját megtartsd, a miket én tőlem hallottál, a Krisztus Jézusban való hitben és szeretetben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'A rád bízott drága kincset őrizd meg a bennünk lakozó Szent Lélek által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'Azt tudod, hogy elfordultak tőlem az Ázsiabeliek mind, kik közül való Figellus és Hermogénes.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'Az Úr legyen irgalmas az Onesiforus házanépének: mert gyakorta megvidámított engem, és az én bilincsemet nem szégyenlette;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'Sőt mikor Rómában volt, buzgón keresett engem, meg is talált.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, 'Az Úr engedje meg néki, hogy találjon irgalmasságot az Úrnál ama napon. És hogy mily nagy szolgálatot tett Efézusban, te jobban tudod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'Te annakokáért, én fiam, erősödjél meg a Krisztus Jézusban való kegyelemben;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'És a miket tőlem hallottál sok bizonyság által, azokat bízzad hív emberekre, a kik másoknak a tanítására is alkalmasak lesznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'Te azért a munkának terhét hordozzad, mint a Jézus Krisztus jó vitéze.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'Egy harczos sem elegyedik bele az élet dolgaiba; hogy tessék annak, a ki őt harczossá avatta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'Ha pedig küzd is valaki, nem koronáztatik meg, ha nem szabályszerűen küzd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'A ki munkálkodik, a földmívelőnek kell a gyümölcsökben először részesülnie.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, 'Értsd meg a mit mondok; adjon azért az Úr néked belátást mindenekben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'Emlékezzél meg, hogy Jézus Krisztus feltámadott a halálból, ki a Dávid magvából való az én evangyéliomom szerint:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'A melyért, mint egy gonosztevő, szenvedek mind a fogságig; de az Istennek beszéde nincs bilincsbe verve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'Annakokáért mindent elszenvedek a választottakért, hogy ők is elnyerjék a Krisztus Jézusban való idvességet örök dicsőséggel egyben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, 'Igaz beszéd ez. Mert ha vele együtt meghaltunk, vele együtt fogunk élni is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'Ha tűrünk, vele együtt fogunk uralkodni is: ha megtagadjuk, ő is megtagad minket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'Ha hitetlenkedünk, ő hű marad: ő magát meg nem tagadhatja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'Ezekre emlékeztesd, kérvén kérve őket az Úr színe előtt, hogy ne vitatkozzanak haszontalanul, a hallgatóknak romlására.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'Igyekezzél, hogy Isten előtt becsületesen megállj, mint oly munkás, a ki szégyent nem vall, a ki helyesen hasogatja az igazságnak beszédét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'A szentségtelen üres lármákat pedig kerüld, mert mind nagyobb istentelenségre növekednek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'És az ő beszédök mint a rákfekély terjed; közülök való Himenéus és Filétus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'A kik az igazság mellől eltévelyedtek, azt mondván, hogy a feltámadás már megtörtént, és feldúlják némelyeknek a hitét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'Mindazáltal megáll az Istennek erős fundamentoma, melynek pecséte ez: Ismeri az Úr az övéit; és: Álljon el a hamisságtól minden, a ki Krisztus nevét vallja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'Nagy házban pedig nemcsak arany- és ezüstedények vannak, hanem fából és cserépből valók is; és azok közül némelyek tisztességre, némelyek pedig gyalázatra valók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'Ha tehát valaki magát ezektől tisztán tartja, tisztességre való edény lesz, megszentelt, és hasznos a gazdának, minden jó cselekedetre alkalmas.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, 'Az ifjúkori kivánságokat pedig kerüld; hanem kövessed az igazságot, a hitet, a szeretetet, a békességet azokkal egyetembe, a kik segítségül hívják az Urat tiszta szívből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, 'A botor és gyermekes vitatkozásokat pedig kerüld, tudván, hogy azok háborúságokat szülnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, 'Az Úr szolgájának pedig nem kell torzsalkodni, hanem legyen mindenkihez nyájas, tanításra alkalmas, türelmes.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, 'A ki szelíden fenyíti az ellenszegülőket; ha talán adna nékik az Isten megtérést az igazság megismerésére,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, 'És felocsudnának az ördög tőréből, foglyokká tétetvén az Úr szolgája által az Isten akaratára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'Azt pedig tudd meg, hogy az utolsó napokban nehéz idők állanak be.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'Mert lesznek az emberek magukat szeretők, pénzsóvárgók, kérkedők, kevélyek, káromkodók, szüleik iránt engedetlenek, háládatlanok, tisztátalanok,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'Szeretet nélkül valók, kérlelhetetlenek, rágalmazók, mértékletlenek, kegyetlenek, a jónak nem kedvelői.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'Árulók, vakmerők, felfuvalkodottak, inkább a gyönyörnek, mint Istennek szeretői.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'Kiknél megvan a kegyességnek látszata, de megtagadják annak erejét. És ezeket kerüld.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, 'Mert ezek közül valók azok, a kik betolakodnak a házakba, és foglyul ejtik a bűnökkel megterhelt és sokféle kívánságoktól űzött asszonykákat,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'Kik mindenkor tanulnak, de az igazság megismerésére soha el nem juthatnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'Miképen pedig Jánnes és Jámbres ellene állottak Mózesnek, akképen ezek is ellene állanak az igazságnak; megromlott elméjű, a hitre nézve nem becsületes emberek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'De többre nem mennek: mert esztelenségök nyilvánvaló lesz mindenek előtt, a miképen amazoké is az lett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'Te pedig követted az én tanításomat, életmódomat, szándékomat, hitemet, hosszútűrésemet, szeretetemet, türelmemet,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'Üldöztetéseimet, szenvedéseimet, a melyek rajtam estek Antiókhiában, Ikóniumban, Listrában: minémű üldöztetéseket szenvedtem! de mindezekből megszabadított engem az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'De mindazok is, a kik kegyesen akarnak élni Krisztus Jézusban, üldöztetni fognak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, 'A gonosz emberek pedig és az ámítók nevekednek a rosszaságban, eltévelyítvén és eltévelyedvén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'De te maradj meg azokban, a miket tanultál és a mik reád bízattak, tudván kitől tanultad,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'És hogy gyermekségedtől fogva tudod a szent írásokat, melyek téged bölcscsé tehetnek az idvességre a Krisztus Jézusban való hit által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'A teljes írás Istentől ihletett és hasznos a tanításra, a feddésre, a megjobbításra, az igazságban való nevelésre,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'Hogy tökéletes legyen az Isten embere, minden jó cselekedetre felkészített.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'Kérlek azért az Isten és Krisztus Jézus színe előtt, a ki ítélni fog élőket és holtakat az ő eljövetelekor és az ő országában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'Hirdesd az ígét, állj elő vele alkalmatos, alkalmatlan időben, ints, feddj, buzdíts teljes béketűréssel és tanítással.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, 'Mert lesz idő, mikor az egészséges tudományt el nem szenvedik, hanem a saját kívánságaik szerint gyűjtenek magoknak tanítókat, mert viszket a fülök;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'És az igazságtól elfordítják az ő fülöket, de a mesékhez oda fordulnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'De te józan légy mindenekben, szenvedj, az evangyélista munkáját cselekedd, szolgálatodat teljesen betöltsd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'Mert én immár megáldoztatom, és az én elköltözésem ideje beállott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'Ama nemes harczot megharczoltam, futásomat elvégeztem, a hitet megtartottam:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'Végezetre eltétetett nékem az igazság koronája, melyet megád nékem az Úr ama napon, az igaz Bíró; nemcsak nékem pedig, hanem mindazoknak is, a kik vágyva várják az ő megjelenését.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'Igyekezzél hozzám jőni hamar.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'Mert Démás engem elhagyott, e jelen való világhoz ragaszkodván, és elment Thessalónikába: Kresczens Galátziába, Titus Dalmátziába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'Egyedül Lukács van velem. Márkust magadhoz vévén, hozd magaddal: mert nekem alkalmas a szolgálatra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'Tikhikust pedig Efézusba küldöttem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, 'A felsőruhámat, melyet Troásban Kárpusnál hagytam, jöttödben hozd el, a könyveket is, kiváltképen a hártyákat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'Az érczmíves Sándor sok bajt szerzett nékem: fizessen meg az Úr néki cselekedetei szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'Tőle te is őrizkedjél, mert szerfelett ellenállott a mi beszédinknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'Első védekezésem alkalmával senki sem volt mellettem, sőt mindnyájan elhagytak; ne számíttassék be nékik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'De az Úr mellettem állott, és megerősített engem; hogy teljesen bevégezzem az igehirdetést, és hallják meg azt az összes pogányok: és megszabadultam az oroszlán szájából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'És megszabadít engem az Úr minden gonosz cselekedettől, és megtart az ő mennyei országára; a kinek dicsőség örökkön örökké! Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'Köszöntsed Priszkát és Akvilát, és az Onesifórus háznépét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'Erástus Korinthusban maradt; Trófimust pedig Milétumban hagytam betegen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'Igyekezzél tél előtt eljőni. Köszönt téged Eubulus és Pudens és Linus és Klaudia, és mind az atyafiak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, 'Az Úr Jézus Krisztus a te lelkeddel. Kegyelem veletek! Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Pál, Istennek szolgája, Jézus Krisztusnak pedig apostola, az Isten választottainak hite és a kegyesség szerint való igazságnak megismerése szerint,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'Az örök élet reménységére, melyet megígért az igazmondó Isten örök időknek előtte,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'Megjelentette pedig a maga idejében az ő beszédét a prédikálás által, a mely reám bízatott a mi megtartó Istenünknek parancsolata szerint; Titusnak, a közös hit szerint való igaz fiamnak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'Kegyelem, irgalmasság és békesség az Atya Istentől és az Úr Jézus Krisztustól, a mi Megtartónktól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'A végett hagytalak téged Krétában, hogy a hátramaradt dolgokat hozd rendbe, és rendelj városonként presbitereket, a miképen én néked meghagytam;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'Ha van feddhetetlen, egy feleségű férfiú, a kinek hívő, nem kicsapongással vádolt avagy engedetlen gyermekei vannak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'Mert szükséges, hogy a püspök feddhetetlen legyen, mint Isten sáfára; nem akaratos, nem haragos, nem részeges, nem verekedő, nem rút nyerészkedő;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'Hanem vendégszerető, jónak kedvelője, mértékletes, igaz, tiszta, maga tűrtető;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'A ki a tudomány szerint való igaz beszédhez tartja magát, hogy inthessen az egészséges tudománnyal és meggyőzhesse az ellenkezőket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'Mert van sok engedetlen, hiába való beszédű és csaló, kiváltképen a körülmetélkedésből valók,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'A kiknek be kell dugni a szájokat; a kik egész házakat feldúlnak, tanítván rút nyereség okáért, a miket nem kellene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'Azt mondta valaki közülök, az ő saját prófétájok: A krétaiak mindig hazugok, gonosz vadak, rest hasak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'E bizonyság igaz: annakokáért fedd őket kímélés nélkül, hogy a hitben épek legyenek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'Nem ügyelvén zsidó mesékre, és az igazságot megvető emberek parancsolataira.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'Minden tiszta a tisztáknak: de a megfertőztetetteknek és hitetleneknek semmi sem tiszta; hanem megfertőztetett azoknak mind elméjök, mind lelkiismeretök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'Vallják, hogy Istent ismerik, de cselekedeteikkel tagadják, mivelhogy útálatosak és hitetlenek és minden jó cselekedetre méltatlanok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'Te pedig azokat szóljad, a mik az egészséges tudományhoz illenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'Hogy a vén emberek józanok legyenek, tisztességesek, mértékletesek; a hitben, szeretetben, tűrésben épek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'Hasonlóképen a vén asszonyok szentekhez illő magaviseletűek legyenek, nem patvarkodók, sem sok borivás rabjai, jóra oktatók;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'Hogy megokosítsák az ifjú asszonyokat, hogy férjöket és magzataikat szeressék,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'Legyenek mértékletesek, tiszták, háziasak, jók, férjöknek engedelmesek, hogy az Isten beszéde ne káromoltassék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'Az ifjakat hasonlóképen intsed, hogy legyenek mértékletesek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'Mindenben tenmagadat adván példaképül a jó cselekedetekben; a tudományban romlatlanságot, méltóságot mutatván,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'Egészséges, feddhetetlen beszédet; hogy az ellenfél megszégyenüljön, semmi gonoszt sem tudván rólatok mondani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, 'A szolgákat intsed, hogy az ő uraiknak engedelmeskedjenek, mindenben kedvöket keressék, ne ellenkezzenek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'Ne tolvajkodjanak, hanem teljes jó hűséget tanusítsanak; hogy a mi megtartó Istenünknek tudományát ékesítsék mindenben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, 'Mert megjelent az Isten idvezítő kegyelme minden embernek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'A mely arra tanít minket, hogy megtagadván a hitetlenséget és a világi kivánságokat, mértékletesen, igazán és szentül éljünk a jelenvaló világon:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'Várván ama boldog reménységet és a nagy Istennek és megtartó Jézus Krisztusunknak dicsősége megjelenését;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'A ki önmagát adta mi érettünk, hogy megváltson minket minden hamisságtól, és tisztítson önmagának kiváltképen való népet, jó cselekedetekre igyekezőt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'Ezeket szóljad, és ints és feddj teljes méltósággal; senki téged meg ne vessen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'Emlékeztessed őket, hogy a fejedelemségeknek és hatalmasságoknak engedelmeskedjenek, hódoljanak, minden jó cselekedetre készek legyenek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'Senkit ne szidalmazzanak, ne veszekedjenek, gyöngédek legyenek, teljes szelídséget tanusítván minden ember iránt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'Mert régenten mi is esztelenek, engedetlenek, tévelygők, különböző kívánságoknak és gyönyöröknek szolgái, gonoszságban és irígységben élők, gyűlölségesek, egymást gyűlölők valánk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'De mikor a mi megtartó Istenünknek jóvolta és az emberekhez való szeretete megjelent,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, 'Nem az igazságnak cselekedeteiből, a melyeket mi cselekedtünk, hanem az ő irgalmasságából tartott meg minket az újjászületésnek fürdője és a Szent Lélek megújítása által,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'Melyet kitöltött reánk bőséggel a mi megtartó Jézus Krisztusunk által;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'Hogy az ő kegyelméből megigazulván, örökösök legyünk az örök élet reménysége szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'Igaz ez a beszéd, és akarom, hogy ezeket erősítsed, hogy igyekezzenek jó cselekedetekkel előljárni azok, a kik Istenben hívőkké lettek. Ezek jók és hasznosak az embereknek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'A balgatag vitatkozásokat azonban és a nemzetségekről való tudakozásokat, és a civakodást és a törvény felől való harczokat kerüld; mert haszontalanok és hiábavalók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'Az eretnek embert egy vagy két intés után kerüld;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'Tudván, hogy az ilyen romlott, és vétkezik, önmaga is kárhoztatván magát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'Mikor Ártemást vagy Tikhikust hozzád küldöm, siess hozzám jőni Nikápolyba; mert elhatároztam, hogy ott töltöm a telet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'A törvénytudó Zénást és Apollóst gondosan indítsd útnak, hogy semmiben se legyen fogyatkozásuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'Tanulják meg pedig a mieink is, hogy jó cselekedetekkel járjanak elől a szükséges hasznokra, hogy ne legyenek gyümölcstelenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, 'Köszöntenek téged a velem levők mindnyájan. Köszöntsd azokat, a kik szeretnek minket hitben. Kegyelem mindnyájatokkal! Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Pál, Krisztus Jézusnak foglya, és Timótheus, az atyafi, Filemonnak, a mi szeretett munkatársunknak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'És Appiának, a szeretettnek, és Arkhippusnak, a mi bajtársunknak, és a te házadnál való gyülekezetnek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'Kegyelem néktek és békesség Istentől, a mi Atyánktól, és az Úr Jézus Krisztustól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'Hálát adok az én Istenemnek mindenkor, emlegetvén téged az én imádságaimban,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'Mert hallom a te szeretetedet és ama te hitedet, mely van benned az Úr Jézushoz, és minden szentek irányában,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'Hogy a te hitedben való közösség hathatós legyen, a Krisztus ügyében, minden bennetek levő jónak megismerése által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'Mert sok örömünk és vígasztalásunk van a te szeretetedben, hogy a szenteknek szíveik megvídámodtak te általad, atyámfia.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'Annakokáért jóllehet nagy bátorságom van a Krisztusban, megparancsolni néked azt, a mi illendő,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'A szeretetért inkább kérlek, ilyen lévén, mint Pál, a megvénhedett, most pedig foglya is a Jézus Krisztusnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'Kérlek téged az én fiamért, a kit fogságomban szűltem, Onésimusért,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'A ki egykor tenéked haszontalan volt, most pedig mind néked, mind nékem nagyon hasznos,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'Kit visszaküldöttem; te pedig őt, azaz az én szívemet, fogadd magadhoz!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'Őt én magamnál akartam tartani, hogy te helyetted szolgáljon nékem az evangyéliomért szenvedett fogságomban;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'De a te megkérdezésed nélkül semmit sem akartam cselekedni, hogy jótéteményed ne kényszerítésből, hanem szabad akaratból való legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Mert talán azért vált meg tőled ideig-óráig, hogy őt, mint örökkévalót kapd vissza;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'Nem úgy immár mint szolgát, hanem szolgánál nagyobbat, mint szeretett atyafit, kiváltképen nékem, mennyivel inkább pedig néked, mind testben, mind az Úrban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'Azért, ha engem részestársadnak tartasz, úgy fogadd őt magadhoz, mint engemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'Ha pedig valamit vétett ellened, avagy adós, ezt nekem róvd fel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'Én Pál írtam az én kezemmel, én megfizetem: hogy azt ne mondjam néked, hogy te magaddal is adós vagy ezen felül nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'Bizonyára, atyámfia, jótéteményt várnék tőled az Úrban: vídámítsd meg az én szívemet az Úrban!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'Bízván a te engedelmességedben, így írtam néked, tudván, hogy annál, a mit mondok, többet is fogsz cselekedni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'Egyúttal pedig készíts nékem szállást; mert reménylem, hogy a ti imádságaitokért néktek ajándékoztatom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'Köszönt téged Epafrás, az én fogolytársam a Krisztus Jézusban,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'Továbbá Márk, Aristárkhus, Démás és Lukács, az én munkatársaim.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, 'A mi Urunk Jézus Krisztusnak kegyelme legyen a ti lelketekkel!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Minekutána az Isten sok rendben és sokféleképen szólott hajdan az atyáknak a próféták által, ez utolsó időkben szólott nékünk Fia által,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'A kit tett mindennek örökösévé, a ki által a világot is teremtette,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'A ki az ő dicsőségének visszatükröződése, és az ő valóságának képmása, a ki hatalma szavával fentartja a mindenséget, a ki minket bűneinktől megtisztítván, üle a Felségnek jobbjára a magasságban,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'Annyival kiválóbb lévén az angyaloknál, a mennyivel különb nevet örökölt azoknál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'Mert kinek mondotta valaha az angyalok közül: Én Fiam vagy te, én ma szűltelek téged? és ismét: Én leszek néki Atyja és ő lesz nékem Fiam?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'Viszont mikor behozza az ő elsőszülöttét a világba, így szól: És imádják őt az Istennek minden angyalai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'És bár az angyalokról így szól: Ki az ő angyalait szelekké teszi és az ő szolgáit tűz lángjává,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'Ámde a Fiúról így: A te királyi széked óh Isten örökkön örökké. Igazságnak pálczája a te országodnak pálczája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'Szeretted az igazságot és gyűlölted a hamisságot: annakokáért felkent téged az Isten, a te Istened, örömnek olajával a te társaid felett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'És: Te Uram kezdetben alapítottad a földet és a te kezeidnek művei az egek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'Azok elvesznek, de te megmaradsz, és mindazok, mint a ruha megavulnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'És palástként összehajtod azokat és elváltoznak, te pedig ugyanaz vagy és a te esztendeid el nem fogynak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'Melyik angyalnak mondotta pedig valaha: Ülj az én jobbkezem felől, míglen ellenségeidet lábaidnak zsámolyává teszem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Avagy nem szolgáló lelkek-é mindazok, elküldve szolgálatra azokért, a kik örökölni fogják az idvességet?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'Annakokáért annál is inkább szükséges nékünk a hallottakra figyelmeznünk, hogy valaha el ne sodortassunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'Mert ha az angyaloktól hirdetett beszéd erős volt és minden bűn és engedetlenség elvette igazságos büntetését:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'Mimódon menekedünk meg mi, hogyha nem törődünk ily nagy idvességgel? a melyet, miután kezdetben hirdetett az Úr, azok, a kik hallották, biztosítottak számunkra,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'Velök együtt bizonyságot tevén arról az Isten, jelekkel meg csodákkal és sokféle erőkkel s a Szent Léleknek közléseivel az ő akarata szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'Mert nem angyaloknak vetette alá a jövendő világot, a melyről szólunk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'Sőt bizonyságot tett valahol valaki, mondván: Micsoda az ember, hogy megemlékezel ő róla, avagy az embernek fia, hogy gondod van reá?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'Kisebbé tetted őt rövid időre az angyaloknál, dicsőséggel és tisztességgel megkoronáztad őt és úrrá tetted kezeid munkáin,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'Mindent lábai alá vetettél. Mert azzal, hogy néki mindent alávetett, semmit sem hagyott alávetetlenül: de most még nem látjuk, hogy néki minden alávettetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'Azt azonban látjuk, hogy Jézus, a ki egy kevés időre kisebbé tétetett az angyaloknál, a halál elszenvedéséért dicsőséggel és tisztességgel koronáztatott meg, hogy az Isten kegyelméből mindenkiért megízlelje a halált.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'Mert illendő vala, hogy a kiért minden és a ki által minden, sok fiakat vezérelvén dicsőségre, az ő idvességök fejedelmét szenvedések által tegye tökéletessé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'Mert a megszentelő és a megszenteltek egytől valók mindnyájan, a mely oknál fogva nem szégyenli őket atyjafiainak hívni,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'Mondván: Hirdetem a te nevedet az én atyámfiainak, az anyaszentegyháznak közepette dícséretet mondok néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'És ismét: Én ő benne bízom; és ismét: Ímhol vagyok én és a gyermekek, a kiket az Isten nékem adott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Mivel tehát a gyermekek testből és vérből valók, ő is hasonlatosképen részese lett azoknak, hogy a halál által megsemmisítse azt, a kinek hatalma van a halálon, tudniillik az ördögöt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'És megszabadítsa azokat, a kik a haláltól való félelem miatt teljes életökben rabok valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'Mert nyilván nem angyalokat karolt fel, hanem az Ábrahám magvát karolta fel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'Annakokáért mindenestől fogva hasonlatosnak kellett lennie az atyafiakhoz, hogy könyörülő legyen és hív főpap az Isten előtt való dolgokban, hogy engesztelést szerezzen a nép bűneiért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'Mert a mennyiben szenvedett, ő maga is megkísértetvén, segíthet azokon, a kik megkísértetnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'Annakokáért szent atyafiak, mennyei elhívásnak részesei, figyelmezzetek, a mi vallásunknak apostolára és főpapjára, Krisztus Jézusra,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'A ki hű ahhoz, a ki őt rendelte, valamint Mózes is az ő egész házában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Mert ez nagyobb dicsőségre méltattatott, mint Mózes, a mennyiben a ház építőjének nagyobb a tisztessége, mint a háznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Mert minden háznak van építője, a ki pedig mindent elkészített, az Isten az.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'Mózes is hű volt ugyan az ő egész házában, mint szolga, a hirdetendőknek bizonyságára,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'Krisztus ellenben mint Fiú a maga háza felett, a kinek háza mi vagyunk, ha a bizodalmat és a reménységnek dicsekedését mind végig erősen megtartjuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'Annakokáért a mint a Szent Lélek mondja: Ma, ha az ő szavát halljátok,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'Meg ne keményítsétek a ti szíveteket, mint az elkeseredéskor, a kísértés ama napján a pusztában,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'A hol a ti atyáitok próbára tevéssel megkísértének engem és látták az én cselekedeteimet negyven esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'Azért megharagudtam arra a nemzetségre és mondám: mindig tévelyegnek szivökben; ők pedig nem ismerték meg az én útaimat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'Úgy hogy megesküdtem haragomban, hogy nem fognak bemenni az én nyugodalmamba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Vigyázzatok atyámfiai, hogy valaha ne legyen bármelyikőtöknek hitetlen gonosz szíve, hogy az élő Istentől elszakadjon;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'Hanem intsétek egymást minden napon, míg tart a ma, hogy egyikőtök se keményíttessék meg a bűnnek csalárdsága által:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'Mert részeseivé lettünk Krisztusnak, ha ugyan az elkezdett bizodalmat mindvégig erősen megtartjuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'E mondás szerint: Ma, ha az ő szavát halljátok, meg ne keményítsétek a ti szíveiteket, mint az elkeseredéskor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'Mert kik keseredtek el, mikor ezt hallák? Nemde mindazok, a kik kijövének Égyiptomból Mózes által?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'Kikre haragudott vala pedig meg negyven esztendeig? avagy nem azokra-é, a kik vétkeztek, a kiknek testei elhullottak a pusztában?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'Kiknek esküdött pedig meg, hogy nem mennek be az ő nyugodalmába, hanemha az engedetleneknek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'Látjuk is, hogy nem mehettek be hitetlenség miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'Óvakodjunk tehát, hogy mivel megvan az ő nyugodalmába való bemenetel ígérete, valaki közületek fogyatkozásban levőnek ne láttassék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'Mert nékünk is hirdettetett az evangyéliom, miképen azoknak: de nem használt nékik a hallott beszéd, mivel nem párosították hittel azok, a kik hallották.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'Mert mi, hívők, bemegyünk a nyugodalomba, miképen megmondotta: A mint megesküdtem az én haragomban, nem fognak bemenni az én nyugodalmamba; jóllehet munkáit a világ megalapításától kezdve bevégezte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'Mert valahol a hetedik napról ekképen szólott: És megnyugovék Isten a hetedik napon minden ő cselekedeteitől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'És ugyanabban ismét: Nem mennek be az én nyugodalmamba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'Mivelhogy annakokáért áll az, hogy némelyek bemennek abba, és a kiknek először hirdettetett az evangyéliom, nem mentek be engedetlenség miatt:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'Ismét határoz egy napot: Ma, szólván Dávid által annnyi idő multán, a mint előbb mondva volt. Ma, ha az ő szavát halljátok, meg ne keményítsétek a ti szíveiteket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'Mert ha őket Józsué nyugodalomba helyezte volna, nem szólana azok után más napról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'Annakokáért megvan a szombatja az Isten népének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'Mert a ki bement az ő nyugodalmába, az maga is megnyugodott cselekedeteitől, a miképen Isten is a magáéitól,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'Igyekezzünk tehát bemenni abba a nyugodalomba, hogy valaki a hitetlenségnek ugyanazon példájába ne essék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'Mert az Istennek beszéde élő és ható, és élesebb minden kétélű fegyvernél, és elhat a szívnek és léleknek, az ízeknek és a velőknek megoszlásáig, és megítéli a gondolatokat és a szívnek indulatait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'És nincsen oly teremtmény, a mely nyilvánvaló nem volna előtte, sőt mindenek meztelenek és leplezetlenek annak szemei előtt, a kiről mi beszélünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Lévén annakokáért nagy főpapunk, a ki áthatolt az egeken, Jézus, az Istennek Fia, ragaszkodjunk vallásunkhoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'Mert nem oly főpapunk van, a ki nem tudna megindulni gyarlóságainkon, hanem a ki megkísértetett mindenekben, hozzánk hasonlóan, kivéve a bűnt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'Járuljunk azért bizodalommal a kegyelem királyi székéhez, hogy irgalmasságot nyerjünk és kegyelmet találjunk, alkalmas időben való segítségül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'Mert minden főpap emberek közül választatván, emberekért rendeltetik az Isten előtt való dolgokban, hogy ajándékokat és áldozatokat vigyen a bűnökért,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'A ki képes együttérezni a tudatlanokkal és tévelygőkkel, mivelhogy maga is körül van véve gyarlósággal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'És ezért köteles, miképen a népért, azonképen önmagáért is áldozni a bűnökért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'És senki sem veszi magának e tisztességet, hanem a kit Isten hív el, miként Áront is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'Hasonnlóképen Krisztus sem maga dicsőítette meg magát azzal, hogy főpap lett, hanem az, a ki így szólott hozzá: Én Fiam vagy te, ma szűltelek téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'Miképen másutt is mondja: Te örökké való pap vagy, Melkisédek rendje szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'Ki az ő testének napjaiban könyörgésekkel és esedezésekkel, erős kiáltás és könyhullatás közben járult ahhoz, a ki képes megszabadítani őt a halálból, és meghallgattatott az ő istenfélelméért,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'Ámbár Fiú, megtanulta azokból, a miket szenvedett, az engedelmességet;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'És tökéletességre jutván, örök idvesség szerzője lett mindazokra nézve, a kik neki engedelmeskednek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'Neveztetvén az Istentől Melkisédek rendje szerint való főpapnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'A kiről nekünk sok és nehezen megmagyarázható mondani valónk van, mivel restek lettetek a hallásra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'Mert noha ez idő szerint tanítóknak kellene lennetek, ismét arra van szükségetek, hogy az Isten beszédeinek kezdő elemeire tanítson valaki titeket; és olyanok lettetek, a kiknek tejre van szükségetek és nem kemény eledelre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'Mert mindaz, a ki tejjel él, járatlan az igazságnak beszédiben, mivelhogy kiskorú:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'Az érettkorúaknak pedig kemény eledel való, mint a kiknek mivoltuknál fogva gyakorlottak az érzékeik a jó és rossz között való különbségtételre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'Annakokáért elhagyván a Krisztusról való kezdetleges beszédet, törekedjünk tökéletességre, nem rakosgatván le újra alapját a holt cselekedetekből való megtérésnek és az Istenben való hitnek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'A mosakodásoknak, tanításnak, kezek rátevésének, holtak feltámadásának és az örök ítéletnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'És ezt megcselekeszszük, ha az Isten megengedi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'Mert lehetetlen dolog, hogy a kik egyszer megvilágosíttattak, megízlelvén a mennyei ajándékot, és részeseivé lettek a Szent Léleknek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'És megízlelték az Istennek jó beszédét és a jövendő világnak erőit,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'És elestek, ismét megújuljanak a megtérésre, mint a kik önmagoknak feszítik meg az Istennek ama Fiát, és meggyalázzák őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'Mert a föld, a mely beiszsza a gyakorta reá hulló esőt és hasznos füvet terem azoknak, a kikért műveltetik, áldást nyer Istentől;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'A mely pedig töviseket és bojtorjánokat terem, megvetett és közel van az átokhoz, annak vége megégetés.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'De ti felőletek szerelmeseim, ezeknél jobb és idvességesebb dolgokról vagyunk meggyőződve, ha így szólunk is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'Mert nem igazságtalan az Isten, hogy elfelejtkezzék a ti cselekedeteitekről és a szeretetről, melyet tanúsítottatok az ő neve iránt, mint a kik szolgáltatok és szolgáltok a szenteknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'Kívánjuk pedig, hogy közületek kiki ugyanazon buzgóságot tanusítsa a reménységnek bizonyossága iránt mindvégiglen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'Hogy ne legyetek restek, hanem követői azoknak, a kik hit és békességes tűrés által öröklik az ígéreteket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'Mert az Isten, mikor ígéretet tett Ábrahámnak, mivelhogy nem esküdhetett nagyobbra, önmagára esküdött.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'Mondván: Bizony megáldván megáldalak téged, és megsokasítván megsokasítalak téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'És ekképen, békességestűrő lévén, megnyerte az ígéretet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'Mert az emberek nagyobbra esküsznek, és nálok minden versengésnek vége megerősítésül az eskü;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'Miért is az Isten, kiválóbban megakarván mutatni az ígéret örököseinek az ő végzése változhatatlan voltát, esküvéssel lépett közbe,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'Hogy két változhatatlan tény által, melyekre nézve lehetetlen, hogy az Isten hazudjon, erős vígasztalásunk legyen minékünk, mint a kik oda menekültünk, hogy megragadjuk az előttünk levő reménységet,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'Mely lelkünknek mintegy bátorságos és erős horgonya és beljebb hatol a kárpítnál,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'A hová útnyitóul bement érettünk Jézus, a ki örökké való főpap lett Melkisédek rendje szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'Mert ez a Melkisédek Sálem királya, a felséges Isten papja, a ki a királyok leveréséből visszatérő Ábrahámmal találkozván, őt megáldotta,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'A kinek tizedet is adott Ábrahám mindenből: a ki elsőben is magyarázat szerint igazság királya, azután pedig Sálem királya is, azaz békesség királya,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'Apa nélkül, anya nélkül, nemzetség nélkül való; sem napjainak kezdete, sem életének vége nincs, de hasonlóvá tétetvén az Isten Fiához, pap marad örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'Nézzétek meg pedig, mily nagy ez, a kinek a zsákmányból tizedet is adott Ábrahám, a pátriárka;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'És bár azoknak, kik a Lévi fiai közül nyerik el a papságot, parancsolatjok van, hogy törvény szerint tizedet szedjenek a néptől, azaz az ő atyafiaiktól, jóllehet ők is az Ábrahám ágyékából származtak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'De az, a kinek nemzetsége nem azok közül való, tizedet vett Ábrahámtól, és az ígéretek birtokosát megáldotta,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'Pedig minden ellenmondás nélkül való, hogy a nagyobb áldja meg a kisebbet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'És itt halandó emberek szednek tizedet, ott ellenben az, a ki bizonyság szerint él:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'És hogy úgy szóljak, Ábrahámnál fogva tized vétetett Lévitől is, a tizedszedőtől,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'Mert ő még az atyja ágyékában vala, a mikor annak elébe ment Melkisédek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'Ha tehát a lévitai papság által volna a tökéletesség (mert a nép ez alatt nyerte a törvényt): mi szükség tovább is mondogatni, hogy más pap támadjon a Melkisédek rendje szerint és ne az Áron rendje szerint?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'Mert a papság megváltozásával szükségképen megváltozik a törvény is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'Mert a kiről ezek mondatnak, az más nemzetségből származott, a melyből senki sem szolgált az oltár körül;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'Mert nyilvánvaló, hogy a mi Urunk Júdából támadott, a mely nemzetségre nézve semmit sem szólott Mózes a papságról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'És még inkább nyilvánvaló az, ha a Melkisédek hasonlatossága szerint áll elő más pap,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'A ki nem testi parancsolatnak törvénye szerint, hanem enyészhetetlen életnek ereje szerint lett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'Mert ez a bizonyságtétel: Te pap vagy örökké, Melkisédek rendje szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'Mert az előbbi parancsolat eltöröltetik, mivelhogy erőtelen és haszontalan,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, 'Minthogy a törvény semmiben sem szerzett tökéletességet; de beáll a jobb reménység, a mely által közeledünk az Istenhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'És a mennyiben nem esküvés nélkül való, mert amazok esküvés nélkül lettek papokká,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, 'De ez esküvéssel, az által, a ki azt mondá néki: Megesküdött az Úr, és nem bánja meg, te pap vagy örökké, Melkisédek rendje szerint:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'Annyiban jobb szövetségnek lett kezesévé Jézus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'És amazok jóllehet többen lettek papokká, mert a halál miatt meg nem maradhattak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'De ennek, minthogy örökké megmarad, változhatatlan a papsága.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'Ennekokáért ő mindenképen idvezítheti is azokat, a kik ő általa járulnak Istenhez, mert mindenha él, hogy esedezzék érettök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'Mert ilyen főpap illet vala minket, szent, ártatlan, szeplőtelen, a bűnösöktől elválasztott, és a ki az egeknél magasságosabb lőn,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'A kinek nincs szüksége, mint a főpapoknak, hogy napról-napra előbb a saját bűneiért vigyen áldozatot, azután a népéiért, mert ezt egyszer megcselekedte, maga-magát megáldozván.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, 'Mert a törvény gyarló embereket rendel főpapokká, de a törvény után való esküvés beszéde örök tökéletes Fiút.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, 'Fődolog pedig azokra nézve, a miket mondunk, az, hogy olyan főpapunk van, a ki a mennyei Felség királyi székének jobbjára üle,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, 'Mint a szent helynek és amaz igazi sátornak szolgája, a melyet az Úr és nem ember épített.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'Mert minden főpap ajándékok meg áldozatok vitelére rendeltetik, a miért szükséges, hogy legyen valamije ennek is, a mit áldozatul vigyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'Ha tehát a földön volna, még csak pap sem volna, lévén olyan papok, a kik a törvény szerint áldoznak ajándékokkal,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, 'A kik a mennyei dolgok ábrázolatának és árnyékának szolgálnak, a mint Isten mondotta Mózesnek, mikor be akarta végezni a sátort: Meglásd, úgymond, hogy mindeneket azon minta szerint készíts, a mely a hegyen mutattatott néked.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'Most azonban annyival kiválóbb szolgálatot nyert, a mennyivel jobb szövetségnek közbenjárója, a mely jobb ígéretek alapján köttetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'Mert ha az az első kifogástalan volt volna, nem kerestetett volna hely a másodiknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'Mert dorgálván őket, így szól: Ímé napok jőnek, ezt mondja az Úr, és az Izráel házával és Júdának házával új szövetséget kötök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'Nem azon szövetség szerint, a melyet kötöttem az ő atyáikkal ama napon, mikor kézen fogtam őket, hogy kivezessem Égyiptomból, mert ők nem maradtak meg abban az én szövetségemben, azért én sem gondoltam velök, mondja az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, 'Mert ez az a szövetség, melyet kötök az Izráel házával, ama napok multán, mond az Úr: Adom az én törvényemet az ő elméjökbe, és az ő szívökbe írom azokat, és leszek nekik Istenök és ők lesznek nekem népem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'És nem tanítja kiki az ő felebarátját és kiki az ő atyafiát, mondván: Ismerd meg az Urat; mert mindnyájan megismernek engem a kicsinytől nagyig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'Mert megkegyelmezek álnokságaiknak, és az ő bűneikről és gonoszságaikról meg nem emlékezem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'Mikor újról beszél, óvá tette az elsőt; a mi pedig megavul és megvénhedik, közel van az enyészethez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, 'Annakokáért voltak ugyan az első szövetségnek is istentiszteletei rendtartásai, mint szintén világi szenthelye.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'Mert sátor építtetett, az első, a melyben vala a gyertyatartó, meg az asztal és a kenyerek felrakása; ezt nevezték szenthelynek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'A második kárpiton túl pedig az a sátor, melyet neveztek szentek szentének,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'Melyben vala az arany füstölő oltár és a szövetség ládája beborítva minden felől aranynyal, ebben a mannás aranykorsó és Áron kihajtott vesszeje meg a szövetség táblái,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'Fölötte pedig a dicsőség kérubjai, beárnyékolva a fedelet, a mikről most nem szükséges külön szólani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'Ezek pedig ekképen levén elrendezve; az első sátorba ugyan mindenkor bejárnak a papok az istentisztelet elvégzésére,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'A másodikba azonban egy-egy évben egyszer csak maga a főpap, vérrel, melyet magáért és a nép bűneiért áldoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'Azt jelentvén ki ezzel a Szent Lélek, hogy még nem nyilt meg a szentély útja, fennállván még az első sátor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'A mi példázat a jelenkori időre, mikor áldoznak oly ajándékokkal és áldozatokkal, melyek nem képesek lelkiismeret szerint tökéletessé tenni a szolgálattevőt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, 'Csakis ételekkel meg italokkal és különböző mosakodásokkal – melyek testi rendszabályok – a megjobbulás idejéig kötelezők.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Krisztus pedig megjelenvén, mint a jövendő javaknak főpapja, a nagyobb és tökéletesebb, nem kézzel csinált, azaz nem e világból való sátoron keresztül,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'És nem bakok és tulkok vére által, hanem az ő tulajdon vére által ment be egyszer s mindenkorra a szentélybe, örök váltságot szerezve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'Mert ha a bakoknak és bikáknak a vére, meg a tehén hamva, a tisztátalanokra hintetvén, megszentel a testnek tisztaságára:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'Mennyivel inkább Krisztusnak a vére, a ki örökké való Lélek által önmagát áldozta fel ártatlanul Istennek: megtisztítja a ti lelkiismereteteket a holt cselekedetektől, hogy szolgáljatok az élő Istennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'És ezért új szövetségnek a közbenjárója ő, hogy meghalván az első szövetségbeli bűnök váltságáért, a hivatottak elnyerjék az örökkévaló örökségnek ígéretét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'Mert a hol végrendelet van, szükséges, hogy a végrendelkező halála bekövetkezzék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'Mivel a végrendelet holtak után jogerős, különben pedig, ha él a végrendelkező, épen nem érvényes.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'Innét van, hogy az első sem szenteltetett meg vér nélkül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'Mert mikor Mózes a törvény szerint minden parancsolatot elmondott az egész népnek, vevén a borjúknak és a bakoknak vérét, vízzel és vörös gyapjúval meg izsóppal együtt, magát a könyvet is és az egész népet meghintette,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, 'Mondván: Ez azon szövetség vére, a melyet Isten számotokra rendelt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'Majd a sátort is és az istentiszteletre való összes edényeket hasonlóképen meghintette vérrel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'És csaknem minden vérrel tisztíttatik meg a törvény szerint, és vérontás nélkül nincsen bűnbocsánat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'Annakokáért szükséges, hogy a mennyei dolgoknak ábrázolatai effélékkel tisztíttassanak meg, magok a mennyei dolgok azonban ezeknél különb áldozatokkal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'Mert nem kézzel csinált szentélybe, az igazinak csak másolatába ment be Krisztus, hanem magába a mennybe, hogy most Isten színe előtt megjelenjék érettünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'Nem is, hogy sokszor adja magát áldozatul, mint a hogy a főpap évenként bemegy a szentélybe idegen vérrel;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, 'Mert különben sokszor kellett volna szenvednie a világ teremtetése óta; így pedig csak egyszer jelent meg az időknek végén, hogy áldozatával eltörölje a bűnt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'És miképen elvégezett dolog, hogy az emberek egyszer meghaljanak, azután az ítélet:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'Azonképen Krisztus is egyszer megáldoztatván sokak bűneinek eltörlése végett, másodszor bűn nélkül jelen meg azoknak, a kik őt várják idvességökre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'Minthogy a törvényben a jövendő jóknak árnyéka, nem maga a dolgok képe van meg, ennélfogva azokkal az áldozatokkal, a melyeket esztendőnként szünetlenül visznek, sohasem képes tökéletességre juttatni az odajárulókat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'Különben megszűnt volna az áldozás, mivelhogy az egyszer megtisztult áldozók többé semminemű bűntudattal nem bírtak volna.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'De azok esztendőnként bűnre emlékeztetnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'Mert lehetetlen, hogy a bikák és bakok vére eltörölje a bűnöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'Azért a világba bejövetelekor így szól: Áldozatot és ajándékot nem akartál, de testet alkottál nékem,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'Égő és bűnért való áldozatokat nem kedveltél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'Akkor mondám: Ímé itt vagyok, (a könyv fejezetében írva vagyon rólam), hogy cselekedjem óh Isten a te akaratodat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'Fentebb mondván, hogy áldozatot és ajándékot és égő, meg bűnért való áldozatokat nem akartál, sem nem kedveltél a melyeket a törvény szerint visznek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, 'Ekkor ezt mondotta: Ímé itt vagyok, hogy cselekedjem a te akaratodat. Eltörli az elsőt, hogy meghagyja a másodikat,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'A mely akarattal szenteltettünk meg egyszer s mindenkorra, a Jézus Krisztus testének megáldozása által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'És minden pap naponként szolgálatban áll és gyakorta viszi ugyanazokat az áldozatokat, a melyek sohasem képesek eltörölni a bűnöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'Ő azonban, egy áldozattal áldozván a bűnökért, mindörökre űle az Istennek jobbjára,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'Várván ímmár, míg lábainak zsámolyául vettetnek az ő ellenségei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'Mert egyetlenegy áldozatával örökre tökéletesekké tette a megszentelteket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'Bizonyságot tesz pedig erről mi nékünk a Szent Lélek is, mert minekutána előre mondotta:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, 'Ez az a szövetség, melyet kötök velök ama napok után, mondja az Úr: Adom az én törvényemet az ő szíveikbe, és az ő elméjökbe írom be azokat,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, 'Azután így szól: És az ő bűneikről és álnokságaikról többé meg nem emlékezem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'A hol pedig bűnök bocsánata vagyon, ott nincs többé bűnért való áldozat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'Mivelhogy azért atyámfiai bizodalmunk van a szentélybe való bemenetelre a Jézus vére által,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'Azon az úton, a melyet ő szentelt nékünk új és élő út gyanánt, a kárpit, azaz az ő teste által,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'És lévén nagy papunk az Isten háza felett:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'Járuljunk hozzá igaz szívvel, hitnek teljességével, mint a kiknek szívök tiszta a gonosz lelkiismerettől,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'És testök meg van mosva tiszta vízzel; tartsuk meg a reménységnek vallását tántoríthatatlanul, mert hű az, a ki ígéretet tett,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'És ügyeljünk egymásra, a szeretetre és jó cselekedetekre való felbuzdulás végett,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'El nem hagyván a magunk gyülekezetét, a miképen szokásuk némelyeknek, hanem intvén egymást annyival inkább, mivel látjátok, hogy ama nap közelget.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'Mert ha szándékosan vétkezünk, az igazság megismerésére való eljutás után, akkor többé nincs bűnökért való áldozat,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'Hanem az ítéletnek valami rettenetes várása és a tűznek lángja, a mely megemészti az ellenszegülőket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'A ki megveti a Mózes törvényét, két vagy három tanubizonyságra irgalom nélkül meghal;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'Gondoljátok meg, mennyivel súlyosabb büntetésre méltónak ítéltetik az, a ki az Isten Fiát megtapodja, és a szövetségnek vérét, melylyel megszenteltetett, tisztátalannak tartja, és a kegyelemnek Lelkét bántalmazza?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'Mert ismerjük azt, a ki így szólt: Enyém a bosszúállás, én megfizetek, ezt mondja az Úr. És ismét: Az Úr megítéli az ő népét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'Rettenetes dolog az élő Istennek kezébe esni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'Emlékezzetek pedig vissza a régebbi napokra, a melyekben, minekutána megvilágosíttattatok, sok szenvedésteljes küzdelmet állottatok ki,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, 'Midőn egyfelől gyalázásokkal és nyomorgattatásokkal nyilvánosság elé hurczoltak titeket, másfelől társai lettetek azoknak, a kik így jártak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'Mert a foglyokkal is együtt szenvedtetek, és vagyonotok elrablását örömmel fogadtátok, tudván, hogy néktek jobb és maradandó vagyonotok van a mennyekben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'Ne dobjátok el hát bizodalmatokat, melynek nagy jutalma van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'Mert békességes tűrésre van szükségetek, hogy az Isten akaratát cselekedvén, elnyerjétek az ígéretet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, 'Mert még vajmi kevés idő, és a ki eljövendő, eljő és nem késik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, 'Az igaz pedig hitből él. És a ki meghátrál, abban nem gyönyörködik a lelkem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'De mi nem vagyunk meghátrálás emberei, hogy elvesszünk, hanem hitéi, hogy életet nyerjünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'A hit pedig a reménylett dolgoknak valósága, és a nem látott dolgokról való meggyőződés.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'Mert ezzel szereztek jó bizonyságot a régebbiek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'Hit által értjük meg, hogy a világ Isten beszéde által teremtetett, hogy a mi látható, a láthatatlanból állott elő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'Hit által vitt Ábel becsesebb áldozatot Istennek, mint Kain, a mi által bizonyságot nyert a felől, hogy igaz, bizonyságot tevén az ő ajándékairól Isten, és az által még holta után is beszél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, 'Hit által vitetett fel Énokh, hogy ne lásson halált, és nem találták meg, mert az Isten felvitte őt. Mert felvitetése előtt bizonyságot nyert a felől, hogy kedves volt Istennek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'Hit nélkül pedig lehetetlen Istennek tetszeni; mert a ki Isten elé járul, hinnie kell, hogy ő létezik és megjutalmazza azokat, a kik őt keresik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, 'Hit által tisztelte Istent Noé, mikor megintetvén a még nem látott dolgok felől, házanépe megtartására bárkát készített, a mely által kárhoztatá e világot és a hitből való igazságnak örökösévé lett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'Hit által engedelmeskedett Ábrahám, mikor elhívatott, hogy menjen ki arra a helyre, a melyet örökölendő vala, és kiméne, nem tudván, hová megy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'Hit által lakott az ígéret földén, mint idegenben, sátorokban lakván Izsákkal és Jákóbbal, ugyanazon ígéretnek örökös társaival.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'Mert várja vala az alapokkal bíró várost, melynek építője és alkotója az Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'Hit által nyert erőt Sára is az ő méhében való foganásra, és életkora ellenére szűlt, minthogy hűnek tartotta azt, a ki az ígéretet tette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'Azért is egytől, még pedig mintegy kihalttól annyian származtak, mint az égnek csillagai sokaságra nézve, és mint a tenger partja mellett a fövény, mely megszámlálhatatlan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'Hitben haltak meg mindezek, nem nyerve meg az ígéreteket, hanem csak távolról látva és üdvözölve azokat, és vallást tevén arról, hogy idegenek és vándorok a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'Mert a kik így szólnak, nyilván jelentik, hogy hazát keresnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'És hogyha eszökbe jutott volna az, a melyből kijöttek, volt volna idejök a visszatérésre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'Így azonban jobb után vágyódnak, tudniillik mennyei után; azért nem szégyenli őket az Isten, hogy Istenöknek neveztessék, mert készített nékik várost.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'Hit által áldozta meg Ábrahám Izsákot, próbára tétetvén, és az egyszülöttet vitte áldozatul, ő, ki az ígéreteket nyerte,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'A kinek meg volt mondva: Izsákban neveztetik néked mag;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'Úgy gondolkozván, hogy az Isten a halálból is képes feltámasztani, miért is őt példaképen visszanyerte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'Hit által áldá meg a jövendőkre nézve Izsák Jákóbot és Ézsaut.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'Hit által áldá meg a haldokló Jákób a József fiainak mindenikét, és botja végére hajolva imádkozott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'Hit által emlékezett meg élete végén József az Izráel fiainak kimeneteléről, és az ő tetemeiről rendelkezett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'Hit által rejtegették Mózest az ő szülei születése után három hónapig, mivel látták, hogy kellemes a gyermek, és nem féltek a király parancsától.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'Hit által tiltakozott Mózes, midőn felnövekedett, hogy a Faraó leánya fiának mondják,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'Inkább választván az Isten népével való együttnyomorgást, mint a bűnnek ideig-óráig való gyönyörűségét;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'Égyiptom kincseinél nagyobb gazdagságnak tartván Krisztus gyalázatát, mert a megjutalmazásra tekintett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'Hit által hagyta oda Égyiptomot, nem félvén a király haragjától; mert erős szívű volt, mintha látta volna a láthatatlant.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'Hit által rendelte a páskát és a vérnek kiontását, hogy az öldöklő ne illesse az ő elsőszülötteiket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'Hit által keltek át a veres tengeren, mint valami szárazföldön, a mit megpróbálván az égyiptomiak, elnyelettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'Hit által omlottak le Jérikónak kőfalai, midőn hét napig köröskörül járták.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, 'Hit által nem veszett el Ráháb, a parázna nő az engedetlenekkel együtt, befogadván a kémeket békességgel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'És mit mondjak még? Hiszen kifogynék az időből, ha szólnék Gedeonról, Bárákról, Sámsonról, Jeftéről, Dávidról, Sámuelről és a prófétákról;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, 'A kik hit által országokat győztek le, igazságot cselekedtek, az ígéreteket elnyerték, az oroszlánok száját betömték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 34, 'Megoltották a tűznek erejét, megmenekedtek a kard élitől, felerősödtek a betegségből, erősek lettek a háborúban, megszalasztották az idegenek táborait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 35, 'Asszonyok feltámadás útján visszanyerték halottjaikat; mások kínpadra vonattak, visszautasítván a szabadulást, hogy becsesebb feltámadásban részesüljenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 36, 'Mások pedig megcsúfoltatások és megostoroztatások próbáját állották ki, sőt még bilincseket és börtönt is;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 37, 'Megköveztettek, kínpróbát szenvedtek, szétfűrészeltettek, kardra hányattak, juhoknak és kecskéknek bőrében bujdostak, nélkülözve, nyomorgattatva, gyötörtetve,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 38, 'A kikre nem volt méltó e világ, bujdosva pusztákon és hegyeken, meg barlangokban és a földnek hasadékaiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 39, 'És mindezek, noha hit által jó bizonyságot nyertek, nem kapták meg az ígéretet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 40, 'Mivel Isten mi felőlünk valami jobbról gondoskodott, hogy nálunk nélkül tökéletességre ne jussanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'Annakokáért mi is, kiket a bizonyságoknak ily nagy fellege vesz körül, félretéve minden akadályt és a megkörnyékező bűnt, kitartással fussuk meg az előttünk levő küzdő tért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'Nézvén a hitnek fejedelmére és bevégezőjére Jézusra, a ki az előtte levő öröm helyett, megvetve a gyalázatot, keresztet szenvedett, s az Isten királyi székének jobbjára ült.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'Gondoljátok meg azért, hogy ő ily ellene való támadást szenvedett el a bűnösöktől, hogy el ne csüggedjetek lelkeitekben elalélván.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'Mert még végig nem állottatok ellent, tusakodván a bűn ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'És elfeledkeztetek-é az intésről, a mely néktek mint fiaknak szól: Fiam, ne vesd meg az Úrnak fenyítését, se meg ne lankadj, ha ő dorgál téged;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'Mert a kit szeret az Úr, megdorgálja, megostoroz pedig mindent, a kit fiává fogad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'Ha a fenyítést elszenveditek, akkor veletek úgy bánik az Isten, mint fiaival; mert melyik fiú az, a kit meg nem fenyít az apa?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'Ha pedig fenyítés nélkül valók vagytok, melyben mindenek részesültek, korcsok vagytok és nem fiak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'Aztán, a mi testi apáink fenyítettek minket és becsültük őket; avagy nem sokkal inkább engedelmeskedünk-é a lelkek Atyjának, és élünk!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'Mert ám azok kevés ideig, tetszésök szerint fenyítettek; ő pedig javunkra, hogy szentségében részesüljünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'Bármely fenyítés ugyan jelenleg nem látszik örvendetesnek, hanem keservesnek, ámde utóbb az igazságnak békességes gyümölcsével fizet azoknak, a kik általa gyakoroltatnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'Annakokáért a lecsüggesztett kezeket és az ellankadt térdeket egyenesítsétek föl,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'És lábaitokkal egyenesen járjatok, hogy a sánta el ne hajoljon, sőt inkább meggyógyuljon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'Kövessétek mindenki irányában a békességet és a szentséget, a mely nélkül senki sem látja meg az Urat:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'Vigyázván arra, hogy az Isten kegyelmétől senki el ne szakadjon; nehogy a keserűségnek bármely gyökere, fölnevekedvén, megzavarjon, és ez által sokan megfertőztettessenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'Ne legyen senki parázna vagy istentelen, mint Ézsau, a ki egy ételért eladta első szülöttségi jogát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'Mert tudjátok, hogy azután is, mikor akarta örökölni az áldást, megvettetett; mert nem találta meg a megbánás helyét, noha könyhullatással kereste azt az áldást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'Mert nem járultatok megtapintható hegyhez, és lángoló tűzhöz, és sűrű homályhoz, és sötétséghez, és szélvészhez,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'És trombita harsogásához, és a mondásoknak szavához, melyet a kik hallottak, kérték, hogy ne intéztessék hozzájok szó;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, 'Mert nem bírták ki, a mi parancsolva volt: Még ha oktalan állat ér is a hegyhez, megköveztessék, vagy nyillal lövettessék le;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'És oly rettenetes volt a látomány, hogy Mózes is mondá: Megijedtem és remegek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'Hanem járultatok Sion hegyéhez, és az élő Istennek városához, a mennyei Jeruzsálemhez, és az angyalok ezreihez,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'Az elsőszülöttek seregéhez és egyházához, a kik be vannak írva a mennyekben, és mindenek bírájához Istenhez, és a tökéletes igazak lelkeihez,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'És az újszövetség közbenjárójához Jézushoz, és a meghintésnek véréhez, mely jobbat beszél, mint az Ábel vére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'Vigyázzatok, meg ne vessétek azt, a ki szól; mert ha azok meg nem menekültek, a kik a földön szólót megvetették, sokkal kevésbbé mi, ha elfordulunk attól, a ki a mennyekből vagyon,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'Kinek szava akkor megrendítette a földet, most pedig ígéretet tesz, mondván: Még egyszer megrázom nemcsak a földet, hanem az eget is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'Az a „még egyszer” pedig jelenti az állhatatlan dolgoknak mint teremtményeknek megváltozását, hogy a rendíthetetlen dolgok maradjanak meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'Annakokáért mozdíthatatlan országot nyervén, legyünk háládatosak, melynél fogva szolgáljunk az Istennek tetsző módon kegyességgel és félelemmel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, 'Mert a mi Istenünk megemésztő tűz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'Az atyafiúi szeretet maradjon meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'A vendégszeretetről el ne felejtkezzetek, mert ez által némelyek, tudtokon kívül, angyalokat vendégeltek meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'Emlékezzetek meg a foglyokról, mint fogolytársak, a gyötrődőkről, mint a kik magatok is testben vagytok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, 'Tisztességes minden tekintetben a házasság és a szeplőtelen házaságy; a paráznákat pedig és a házasságrontókat megítéli az Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'Fösvénység nélkül való legyen a magatok viselete; elégedjetek meg azzal, a mitek van; mert Ő mondotta: Nem hagylak el, sem el nem távozom tőled;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'Úgy hogy bízvást mondjuk: Az Úr az én segítségem, nem félek; ember mit árthat én nékem?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Emlékezzetek meg a ti előljáróitokról, a kik szólották néktek az Isten beszédét, és figyelmezvén az ő életök végére, kövessétek hitöket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Jézus Krisztus tegnap és ma és örökké ugyanaz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'Különböző és idegen tudományok által ne hagyjátok magatokat félrevezettetni; mert jó dolog, hogy kegyelemmel erősíttessék meg a szív, nem ennivalókkal, a melyeknek semmi hasznát sem veszik azok, a kik azok körül járnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'Van oltárunk, a melyről nincs joguk enni azoknak, a kik a sátornak szolgálnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'Mert a mely állatok vérét a főpap beviszi a szentélybe a bűnért, azoknak testét megégetik a táboron kívül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'Annakokáért Jézus is, hogy megszentelje az ő tulajdon vére által a népet, a kapun kívül szenvedett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'Menjünk ki tehát ő hozzá a táboron kívül, az ő gyalázatát hordozván.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'Mert nincsen itt maradandó városunk, hanem a jövendőt keressük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'Annakokáért ő általa vigyünk dícséretnek áldozatát mindenkor Isten elé, azaz az ő nevéről vallást tevő ajkaknak gyümölcsét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'A jótékonyságról pedig és az adakozásról el ne felejtkezzetek, mert ilyen áldozatokban gyönyörködik az Isten.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Engedelmeskedjetek előljáróitoknak és fogadjatok szót, mert ők vigyáznak lelkeitekre, mint számadók; hogy ezt örömmel míveljék és nem bánkódva, mert ez néktek nem használ.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'Imádkozzatok érettünk. Mert úgy vagyunk meggyőződve, hogy jó lelkiismeretünk van, igyekezvén mindenekben tisztességesen forgolódni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'Kiváltképen pedig arra kérlek, hogy ezt cselekedjétek, hogy mihamarább visszaadhassam néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'A békesség Istene pedig, a ki kihozta a halálból a juhoknak nagy pásztorát, örök szövetség vére által, a mi Urunkat Jézust,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'Tegyen készségesekké titeket minden jóra, hogy cselekedjétek az ő akaratát, azt munkálván ti bennetek, a mi kedves ő előtte a Jézus Krisztus által, a kinek dicsőség örökkön örökké. Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'Kérlek pedig titeket atyámfiai, szívleljétek meg ez intő beszédet, hiszen röviden is írtam néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'Legyen tudtotokra, hogy a mi atyánkfia Timótheus kiszabadult, a kivel ha csakhamar eljő, meglátogatlak titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'Köszöntsétek minden előljárótokat és a szenteket mind. Köszöntenek titeket az Olaszországból valók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'Kegyelem mindnyájatokkal! Ámen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Jakab, Istennek és az Úr Jézus Krisztusnak szolgája, az elszórtan levő tizenkét nemzetségnek; üdvözletemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Teljes örömnek tartsátok, atyámfiai, mikor különféle kísértésekbe estek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'Tudván, hogy a ti hiteteknek megpróbáltatása kitartást szerez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'A kitartásban pedig tökéletes cselekedet legyen, hogy tökéletesek és épek legyetek minden fogyatkozás nélkül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'Ha pedig valakinek közületek nincsen bölcsessége, kérje Istentől, a ki mindenkinek készségesen és szemrehányás nélkül adja; és megadatik néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'De kérje hittel, semmit sem kételkedvén: mert a ki kételkedik, hasonlatos a tenger habjához, a melyet a szél hajt és ide s tova hány.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'Mert ne vélje az ilyen ember, hogy kaphat valamit az Úrtól;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'A kétszívű, a minden útjában állhatatlan ember.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'Dicsekedjék pedig az alacsony sorsú atyafi az ő nagyságával;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'A gazdag pedig az ő alacsonyságával: mert elmúlik, mint a fűnek virága.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'Mert felkél a nap az ő hévségével, és megszárítja a füvet; és annak virága elhull, és ábrázatának kedvessége elvész: így hervad el a gazdag is az ő útaiban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'Boldog ember az, a ki a kísértésben kitart; mert minekutána megpróbáltatott, elveszi az életnek koronáját, a mit az Úr ígért az őt szeretőknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Senki se mondja, mikor kísértetik: Az Istentől kísértetem: mert az Isten gonoszsággal nem kísérthető, ő maga pedig senkit sem kísért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'Hanem mindenki kísértetik, a mikor vonja és édesgeti a tulajdon kívánsága.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'Azután a kívánság megfoganván, bűnt szűl; a bűn pedig teljességre jutván halált nemz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'Ne tévelyegjetek szeretett atyámfiai!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'Minden jó adomány és minden tökéletes ajándék felülről való, és a világosságok Atyjától száll alá, a kinél nincs változás, vagy változásnak árnyéka.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'Az ő akarata szült minket az igazságnak ígéje által, hogy az ő teremtményeinek valami zsengéje legyünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'Azért, szeretett atyámfiai, legyen minden ember gyors a hallásra, késedelmes a szólásra, késedelmes a haragra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'Mert ember haragja Isten igazságát nem munkálja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'Elvetvén azért minden undokságot és a gonoszságnak sokaságát, szelídséggel fogadjátok a beoltott ígét, a mely megtarthatja a ti lelkeiteket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'Az ígének pedig megtartói legyetek és ne csak hallgatói, megcsalván magatokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'Mert ha valaki hallgatója az ígének és nem megtartója, az ilyen hasonlatos ahhoz az emberhez, a ki tükörben nézi az ő természet szerinti ábrázatát:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'Mert megnézte magát és elment, és azonnal elfelejtette, milyen volt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'De a ki belenéz a szabadság tökéletes törvényébe és megmarad a mellett, az nem feledékeny hallgató, sőt cselekedet követője lévén, az boldog lesz az ő cselekedetében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'Ha valaki istentisztelőnek látszik köztetek, de nem zabolázza meg nyelvét, sőt megcsalja a maga szívét, annak az istentisztelete hiábavaló.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'Tiszta és szeplő nélkül való istentisztelet az Isten és az Atya előtt ez: meglátogatni az árvákat és özvegyeket az ő nyomorúságukban, és szeplő nélkül megtartani magát e világtól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Atyámfiai ne legyen személyválogatás a ti hitetekben, a mely van a dicsőség Urában, a mi Jézus Krisztusunkban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'Mert ha a ti gyülekezetetekbe bemegy egy aranygyűrűs férfiú fényes ruhában, bemegy pedig egy szegény is szennyes ruhában;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'És rátekinttek arra, a kin a fényes ruha van, és azt mondjátok néki: Te ülj ide szépen; és a szegénynek ezt mondjátok: Te állj ott, vagy ülj ide az én zsámolyom mellé:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'Nem mondtatok-é ellent magatoknak, és nem lettetek-é gonosz gondolkozású birákká?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Halljátok meg szeretett atyámfiai, avagy nem az Isten választotta-é ki e világ szegényeit, hogy gazdagok legyenek hitben, és örökösei az országnak, a melyet azoknak ígért, a kik őt szeretik?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Ti pedig meggyaláztátok a szegényt. Avagy nem a gazdagok hatalmaskodnak-é rajtatok, és nem ők hurczolnak-é titeket a törvény elé?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'Nem ők káromolják-é azt a szép nevet, a melyről neveztettek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'Ha ellenben megtartjátok a királyi törvényt az Írás szerint: Szeressed felebarátodat, mint tenmagadat, jól cselekesztek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'De ha személyválogatók vagytok, vétkeztek, elmarasztaltatva a törvény által, mint annak megrontói.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Mert ha valaki az egész törvényt megtartja is, de vét egy ellen, az egésznek megrontásában bűnös.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'Mert a ki ezt mondotta: Ne paráználkodjál, ezt is mondotta: Ne ölj. És ha nem paráználkodol, de ölsz, törvényszegővé lettél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Úgy szóljatok és úgy cselekedjetek, mint a kiket a szabadság törvénye fog megítélni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'Mert az ítélet irgalmatlan az iránt, a ki nem cselekszik irgalmasságot; és dicsekedik az irgalmasság az ítélet ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Mi a haszna, atyámfiai, ha valaki azt mondja, hogy hite van, cselekedetei pedig nincsenek? Avagy megtarthatja-é őt a hit?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'Ha pedig az atyafiak, férfiak vagy nők, mezítelenek, és szűkölködnek mindennapi eledel nélkül,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'És azt mondja nékik valaki ti közületek: Menjetek el békességgel, melegedjetek meg és lakjatok jól; de nem adjátok meg nékik, a mikre szüksége van a testnek; mi annak a haszna?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'Azonképen a hit is, ha cselekedetei nincsenek, megholt ő magában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'De mondhatja valaki: Néked hited van, nékem pedig cselekedeteim vannak. Mutasd meg nékem a te hitedet a te cselekedeteidből, és én meg fogom néked mutatni az én cselekedeteimből az én hitemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Te hiszed, hogy az Isten egy. Jól teszed. Az ördögök is hiszik, és rettegnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Akarod-é pedig tudni, te hiábavaló ember, hogy a hit cselekedetek nélkül megholt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'Avagy Ábrahám, a mi atyánk, nem cselekedetekből igazíttatott-é meg, felvivén Izsákot, az ő fiát az oltárra?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Látod, hogy a hit együtt munkálkodott az ő cselekedeteivel, és a cselekedetekből lett teljessé a hit;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'És beteljesedett az Írás, a mely ezt mondja: Hitt pedig Ábrahám az Istennek, és tulajdoníttatott néki igazságul, és Isten barátjának neveztetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'Látjátok tehát, hogy cselekedetekből igazul meg az ember, és nem csupán hitből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'Hasonlatosképen pedig a tisztátalan Ráháb is, avagy nem cselekedetekből igazíttatott é meg, a mikor a követeket házába fogadta, és más úton bocsátotta ki?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'Mert a miképen holt a test lélek nélkül, akképen holt a hit is cselekedetek nélkül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Atyámfiai, ne legyetek sokan tanítók, tudván azt, hogy súlyosabb ítéletünk lészen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'Mert mindnyájan sokképen vétkezünk. Ha valaki beszédben nem vétkezik, az tökéletes ember, képes az egész testét is megzabolázni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'Ímé a lovaknak szájába zabolát vetünk, hogy engedelmeskedjenek nékünk, és az ő egész testöket igazgatjuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Ímé a hajók is, noha mily nagyok, és erős szelektől hajtatnak, mindazáltal igen kis kormánytól oda fordíttatnak, a hová a kormányos szándéka akarja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'Ezenképen a nyelv is kicsiny tag és nagy dolgokkal hányja magát. Ímé csekély tűz mily nagy erdőt felgyújt!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'A nyelv is tűz, a gonoszságnak összessége. Úgy van a nyelv a mi tagjaink között, hogy megszeplősíti az egész testet, és lángba borítja életünk folyását, maga is lángba boríttatván a gyehennától.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'Mert minden természet, vadállatoké, madaraké, csúszómászóké és vízieké megszelídíthető és meg is szelidíttetett az emberi természet által:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'De a nyelvet az emberek közül senki sem szelidítheti meg; fékezhetetlen gonosz az, halálos méreggel teljes.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Ezzel áldjuk az Istent és Atyát, és ezzel átkozzuk az embereket, a kik az Isten hasonlatosságára teremttettek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'Ugyanabból a szájból jő ki áldás és átok. Atyámfiai, nem kellene ezeknek így lenni!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Vajjon a forrás ugyan abból a nyílásból csörgedeztet-é édest és keserűt?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'Avagy atyámfiai, teremhet-é a fügefa olajmagvakat, vagy a szőlőtő fügét? Azonképen egy forrás sem adhat sós és édes vizet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Kicsoda köztetek bölcs és okos? Mutassa meg az ő jó életéből az ő cselekedeteit bölcsességnek szelídségével.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Ha pedig keserű irígység és czivódás van a ti szívetekben, ne dicsekedjetek és ne hazudjatok az igazság ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'Ez nem az a bölcsesség, a mely felülről jő, hanem földi, testi és ördögi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'Mert a hol irígység és czivakodás van, ott háborúság és minden gonosz cselekedet is van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'A felülről való bölcsesség pedig először is tiszta, azután békeszerető, méltányos, engedelmes, irgalmassággal és jó gyümölcsökkel teljes, nem kételkedő és nem képmutató.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'Az igazság gyümölcse pedig békességben vettetik azoknak, a kik békességesen munkálkodnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'Honnét vannak háborúk és harczok közöttetek? Nem onnan-é a ti gerjedelmeitekből, a melyek a ti tagjaitokban vitézkednek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'Kívántok valamit, és nincs néktek: gyilkoltok és irígykedtek, és nem nyerhetitek meg; harczoltok és háborúskodtok; és nincsen semmitek, mert nem kéritek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'Kéritek, de nem kapjátok, mert nem jól kéritek, hogy gerjedelmeitekre költsétek azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'Parázna férfiak és asszonyok, nem tudjátok-é, hogy a világ barátsága ellenségeskedés az Istennel? A ki azért e világ barátja akar lenni, az Isten ellenségévé lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'Vagy azt gondoljátok, hogy az Írás hiába mondja: Irígységre kívánkozik a lélek, a mely bennünk lakozik?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'De majd nagyobb kegyelmet ád; ezért mondja: Az Isten a kevélyeknek ellenök áll, az alázatosoknak pedig kegyelmet ád.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Engedelmeskedjetek azért az Istennek; álljatok ellene az ördögnek, és elfut tőletek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Közeledjetek az Istenhez, és közeledni fog hozzátok. Tisztítsátok meg kezeiteket, ti bűnösök, és szenteljétek meg szíveiteket ti kétszívűek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Nyomorkodjatok és gyászoljatok és sírjatok; a ti nevetéstek gyászra forduljon, és örömötök szomorúságra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Alázzátok meg magatokat az Úr előtt, és felmagasztal titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'Ne szóljátok meg egymást atyámfiai. A ki megszólja atyjafiát, és a ki kárhoztatja atyjafiát, az a törvény ellen szól, és a törvényt kárhoztatja. Ha pedig a törvényt kárhoztatod, nem megtartója, hanem bírája vagy a törvénynek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'Egy a törvényhozó, a ki hatalmas megtartani és elveszíteni: kicsoda vagy te, hogy kárhoztatod a másikat?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'Nosza immár ti, a kik azt mondjátok: Ma vagy holnap elmegyünk ama városba, és ott töltünk egy esztendőt, és kalmárkodunk, és nyerünk;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, 'A kik nem tudjátok mit hoz a holnap: mert micsoda a ti életetek? Bizony pára az, a mely rövid ideig látszik, azután pedig eltűnik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'Holott ezt kellene mondanotok: Ha az Úr akarja és élünk, ím ezt, vagy amazt fogjuk cselekedni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Ti ellenben elbizakodottságtokban dicsekedtek: Minden ilyen dicsekedés gonosz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'A ki azért tudna jót cselekedni, és nem cselekeszik, bűne az annak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'Nosza immár ti gazdagok, sírjatok, jajgatván a ti nyomorúságaitok miatt, a melyek elkövetkeznek reátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'Gazdagságotok megrothadt, és a ruháitokat moly ette meg;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'Aranyotokat és ezüstötöket rozsda fogta meg, és azok rozsdája bizonyság ellenetek, és megemészti a ti testeteket, mint a tűz. Kincset gyűjtöttetek az utolsó napokban!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Ímé a ti mezőiteket learató munkások bére, a mit ti elfogtatok, kiált. És az aratók kiáltásai eljutottak a Seregek Urának füleihez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'Dőzsöltetek e földön és dobzódtatok; szívetek legeltettétek mint áldozás napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'Elkárhoztattátok, megöltétek az igazat; nem áll ellent néktek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'Legyetek azért, atyámfiai, béketűrők az Úrnak eljöveteléig. Ímé a szántóvető várja a földnek drága gyümölcsét, béketűréssel várja, míg reggeli és estveli esőt kap.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'Legyetek ti is béketűrők, és erősítsétek meg szíveteket, mert az Úrnak eljövetele közel van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Ne sóhajtozzatok egymás ellen, atyámfiai, hogy el ne ítéltessetek: ímé a Bíró az ajtó előtt áll.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'Például vegyétek, atyámfiai, a szenvedésben és béketűrésben a prófétákat, a kik az Úr nevében szólottak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Ímé, boldogoknak mondjuk a tűrni tudókat. Jóbnak tűrését hallottátok, és az Úrtól való végét láttátok, hogy igen irgalmas az Úr és könyörületes.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'Mindeneknek előtte pedig ne esküdjetek, atyámfiai, se az égre, se a földre, se semmi más esküvéssel. Hanem legyen a ti igenetek igen, és a nem nem; hogy kárhoztatás alá ne essetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Szenved-é valaki köztetek? Imádkozzék. Öröme van-é valakinek? Dícséretet énekeljen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Beteg-é valaki köztetek? Hívja magához a gyülekezet véneit, és imádkozzanak felette, megkenvén őt olajjal az Úrnak nevében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'És a hitből való imádság megtartja a beteget, és az Úr felsegíti őt. És ha bűnt követett is el, megbocsáttatik néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Valljátok meg bűneiteket egymásnak és imádkozzatok egymásért, hogy meggyógyuljatok: mert igen hasznos az igaznak buzgóságos könyörgése.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Illés ember volt, hozzánk hasonló természetű; és imádsággal kéré, hogy ne legyen eső, és nem volt eső a földön három esztendeig és hat hónapig:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'És ismét imádkozott, és az ég esőt adott, és a föld megtermé az ő gyümölcsét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Atyámfiai, hogyha valaki ti köztetek eltévelyedik az igazságtól, és megtéríti őt valaki,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'Tudja meg, hogy a ki bűnöst térít meg az ő tévelygő útjáról, lelket ment meg a haláltól és sok bűnt elfedez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Péter, Jézus Krisztusnak apostola, a Pontusban, Galátziában, Kappadóciában, Ázsiában és Bithiniában elszéledt jövevényeknek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'A kik ki vannak választva az Atya Isten eleve rendelése szerint, a Lélek megszentelésében, engedelmességre és Jézus Krisztus vérével való meghintésre: kegyelem és békesség adassék néktek bőségesen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Áldott az Isten és a mi Urunk Jézus Krisztusnak Atyja, a ki az ő nagy irgalmassága szerint újonnan szűlt minket élő reménységre Jézus Krisztusnak a halálból való feltámadása által,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'Romolhatatlan, szeplőtelen és hervadhatatlan örökségre, a mely a mennyekben van fenntartva számunkra,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'A kiket Isten hatalma őriz hit által az idvességre, a mely készen van, hogy az utolsó időben nyilvánvalóvá legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'A melyben örvendeztek, noha most kissé, ha meg kell lenni, szomorkodtok különféle kísértések között,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'Hogy a ti kipróbált hitetek, a mi sokkal becsesebb a veszendő, de tűz által kipróbált aranynál, dícséretre, tisztességre és dicsőségre méltónak találtassék a Jézus Krisztus megjelenésekor;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'A kit, noha nem láttatok, szerettek; a kiben, noha most nem látjátok, de hisztek benne, kibeszélhetetlen és dicsőült örömmel örvendeztek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'Elérvén hitetek czélját, a lélek idvességét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'A mely idvesség felől tudakozódtak és nyomozódtak a próféták, a kik az irántatok való kegyelem felől jövendöltek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'Nyomozódván, hogy mely vagy milyen időre jelenté azt ki a Krisztusnak ő bennök levő Lelke, a ki eleve bizonyságot tett a Krisztus szenvedéseiről és az azok után való dicsőségről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'A kiknek megjelentetett, hogy nem magoknak, hanem nékünk szolgáltak azokkal, a melyeket most hirdetnek néktek azok, a kik prédikálták néktek az evangyéliomot az egekből küldött Szent Lélek által; a mikbe angyalok vágyakoznak betekinteni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'Annakokáért felövezvén elmétek derekait, mint józanok, tökéletesen reménykedjetek abban a kegyelemben, a melyet a Jézus Krisztus hoz néktek, mikor megjelen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'Mint engedelmes gyermekek ne szabjátok magatokat a ti előbbi kívánságaitokhoz, a melyek tudatlanságotok alatt voltak bennetek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'Hanem a miképen szent az, a ki elhívott titeket, ti is szentek legyetek teljes életetekben;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'Mert meg van írva: Szentek legyetek, mert én szent vagyok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'És ha Atyának hívjátok őt, a ki személyválogatás nélkül ítél, kinek-kinek cselekedete szerint, félelemmel töltsétek a ti jövevénységtek idejét:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'Tudván, hogy nem veszendő holmin, ezüstön vagy aranyon váltattatok meg a ti atyáitoktól örökölt hiábavaló életetekből;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'Hanem drága véren, mint hibátlan és szeplőtlen bárányén, a Krisztusén:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'A ki eleve el volt ugyan rendelve, a világ megalapítása előtt, megjelent pedig az idők végén ti érettetek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'A kik ő általa hisztek Istenben, a ki feltámasztotta őt a halálból és dicsőséget adott néki; hogy a ti hitetek reménység is legyen Istenben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Lelketeket az igazság iránt való engedelmességben képmutatás nélkül való atyafiúi szeretetre tisztítván meg a Lélek által, egymást tiszta szívből buzgón szeressétek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'Mint a kik újonnan születtetek nem romlandó magból, de romolhatatlanból, Istennek ígéje által, a mely él és megmarad örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'Mert minden test olyan, mint a fű, és az embernek minden dicsősége olyan, mint a fű virága. Megszárad a fű, és virága elhull:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'De az Úr beszéde megmarad örökké. Ez pedig az a beszéd, a mely néktek hirdettetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'Levetvén azért minden gonoszságot, minden álnokságot, képmutatást, irígykedést, és minden rágalmazást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'Mint most született csecsemők, a tiszta, hamisítatlan tej után vágyakozzatok, hogy azon növekedjetek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'Mivelhogy ízleltétek, hogy jóságos az Úr.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'A kihez járulván, mint élő, az emberektől ugyan megvetett, de Istennél választott, becses kőhöz,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'Ti magatok is mint élő kövek épüljetek fel lelki házzá, szent papsággá, hogy lelki áldozatokkal áldozzatok, a melyek kedvesek Istennek a Jézus Krisztus által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'Azért van meg az Írásban: Ímé szegeletkövet teszek Sionban, a mely kiválasztott, becses; és a ki hisz abban, meg nem szégyenül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'Tisztesség azért néktek, a kik hisztek; az engedetleneknek pedig: A kő, a melyet az építők megvetettek, az lett a szegeletnek fejévé és megütközésnek kövévé s botránkozásnak sziklájává;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'A kik engedetlenek lévén, megütköznek az ígében, a mire rendeltettek is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Ti pedig választott nemzetség, királyi papság, szent nemzet, megtartásra való nép vagytok, hogy hirdessétek Annak hatalmas dolgait, a ki a sötétségből az ő csodálatos világosságára hívott el titeket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'A kik hajdan nem nép voltatok, most pedig Isten népe vagytok; a kik nem kegyelmezettek voltatok, most pedig kegyelmezettek vagytok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Szeretteim, kérlek titeket, mint jövevényeket és idegeneket, tartóztassátok meg magatokat a testi kívánságoktól, a melyek a lélek ellen vitézkednek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'Magatokat a pogányok közt jól viselvén, hogy a miben rágalmaznak titeket mint gonosztévőket, a jó cselekedetekből, ha látják azokat, dicsőítsék Istent a meglátogatás napján.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'Engedelmeskedjetek azért minden emberi rendelésnek az Úrért: akár királynak, mint felebbvalónak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'Akár helytartóknak, mint a kiket ő küld a gonosztévők megbüntetésére, a jól cselekvőknek pedig dícsérésére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'Mert úgy van az Isten akaratja, hogy jót cselekedvén, elnémítsátok a balgatag emberek tudatlanságát;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'Mint szabadok, és nem mint a kiknél a szabadság a gonoszság palástja, hanem mint Istennek szolgái.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'Mindenkit tiszteljetek, az atyafiúságot szeressétek; az Istent féljétek; a királyt tiszteljétek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'A cselédek teljes félelemmel engedelmeskedjenek az uraknak; nem csak a jóknak és kíméleteseknek, de a szívteleneknek is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'Mert az kedves dolog, ha valaki Istenről való meggyőződéséért tűr keserűségeket, méltatlanul szenvedvén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'Mert micsoda dicsőség az, ha vétkezve és arczul veretve tűrtök? de ha jót cselekedve és mégis szenvedve tűrtök, ez kedves dolog Istennél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'Mert arra hívattatok el; hiszen Krisztus is szenvedett érettetek, néktek példát hagyván, hogy az ő nyomdokait kövessétek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, 'A ki bűnt nem cselekedett, sem a szájában álnokság nem találtatott:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'A ki szidalmaztatván, viszont nem szidalmazott, szenvedvén nem fenyegetőzött; hanem hagyta az igazságosan ítélőre:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'A ki a mi bűneinket maga vitte fel testében a fára, hogy a bűnöknek meghalván, az igazságnak éljünk: a kinek sebeivel szógyultatok meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'Mert olyanok valátok, mint tévelygő juhok; de most megtértetek lelketek pásztorához és felvigyázójához.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'Hasonlóképen az asszonyok engedelmeskedjenek az ő férjöknek, hogy ha némelyek nem engedelmeskednének is az ígének, feleségük magaviselete által íge nélkül is megnyeressenek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'Szemlélvén a ti félelemben való feddhetetlen életeteket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'A kiknek ékessége ne legyen külső, hajuknak fonogatásából és aranynak felrakásából vagy öltözékek felvevéséből való;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'Hanem a szívnek elrejtett embere, a szelíd és csendes lélek romolhatatlanságával, a mi igen becses az Isten előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'Mert így ékesítették magokat hajdan ama szent asszonyok is, a kik Istenben reménykedtek, engedelmeskedvén az ő férjöknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'Miként Sára engedelmeskedett Ábrahámnak, urának nevezvén őt, a kinek gyermekei lettetek, ha jót cselekesztek, és semmi félelemtől nem rettegtek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'A férfiak hasonlóképen, együtt lakjanak értelmes módon feleségükkel, az asszonyi nemnek, mint gyöngébb edénynek, tisztességet tévén, mint a kik örökös társaik az élet kegyelmében; hogy a ti imádságaitok meg ne hiúsuljanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'Végezetre mindnyájan legyetek egyértelműek, rokonérzelműek, atyafiszeretők, irgalmasak, kegyesek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'Nem fizetvén gonoszszal a gonoszért, avagy szidalommal a szidalomért; sőt ellenkezőleg áldást mondván, tudva, hogy arra hivattatok el, hogy áldást örököljetek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'Mert a ki akarja az életet szeretni, jó napokat látni, tiltsa meg nyelvét a gonosztól, és ajkait, hogy ne szóljanak álnokságot:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'Forduljon el a gonosztól, és cselekedjék jót; keresse a békességet, és kövesse azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'Mert az Úr szemei az igazakon vannak, és az ő fülei azoknak könyörgésein; az Úr orczája pedig a gonoszt cselekvőkön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'És kicsoda az, a ki bántalmaz titeket, ha a jónak követői lesztek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'De ha szenvedtek is az igazságért, boldogok vagytok, azoktól való félelemből pedig ne féljetek, se zavarba ne essetek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'Az Úr Istent pedig szenteljétek meg a ti szívetekben. Mindig készek legyetek megfelelni mindenkinek, a ki számot kér tőletek a bennetek levő reménységről, szelídséggel és félelemmel:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'Jó lelkiismeretetek lévén; hogy a miben rágalmaznak titeket, mint gonosztevőket, megszégyenüljenek a kik gyalázzák a ti Krisztusban való jó élteteket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'Mert jobb ha jót cselekedve szenvedtek, ha így akarja az Isten akarata, hogynem gonoszt cselekedve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'Mert Krisztus is szenvedett egyszer a bűnökért, mint igaz a nem igazakért, hogy minket Istenhez vezéreljen; megölettetvén ugyan test szerint, de megeleveníttetvén lélek szerint;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'A melyben elmenvén, a tömlöczben lévő lelkeknek is prédikált,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'A melyek engedetlenek voltak egykor, mikor egyszer várt az Isten béketűrése a Noé napjaiban, a bárka készítésekor, a melyben kevés, azaz nyolcz lélek tartatott meg víz által;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'A mi minket is megtart most képmás gyanánt, mint keresztség, a mi nem a test szenyjének lemosása, hanem jó lelkiismeret keresése Isten iránt, a Jézus Krisztus feltámadása által;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'A ki Istennek jobbján van, felmenvén a mennybe; a kinek alávettettek az angyalok, hatalmasságok és erők.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Minthogy azért Krisztus testileg szenvedett, fegyverkezzetek fel ti is azzal a gondolattal, hogy a ki testileg szenved, megszűnik a bűntől,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'Hogy többé ne embereknek kívánságai, hanem Isten akarata szerint éljétek a testben hátralevő időt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'Mert elég nékünk, hogy életünk elfolyt idejében a pogányok akaratát cselekedtük, járván feslettségekben, kívánságokban, részegségekben, dobzódásokban, ivásokban és undok bálványimádásokban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'A mi miatt csudálkoznak, hogy nem futtok velök együtt a kicsapongásnak ugyanabba az áradatába, szitkozódván.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'A kik számot adnak majd annak, a ki készen van megítélni élőket és holtakat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'Mert azért hirdettetett az evangyéliom a holtaknak is, hogy megítéltessenek emberek szerint testben, de éljenek Isten szerint lélekben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'A vége pedig mindennek közel van. Annakokáért legyetek mértékletesek és józanok, hogy imádkozhassatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'Mindenek előtt pedig legyetek hajlandók az egymás iránti szeretetre; mert a szeretet sok vétket elfedez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'Legyetek egymáshoz vendégszeretők, zúgolódás nélkül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'Kiki amint kegyelmi ajándékot kapott, úgy sáfárkodjatok azzal egymásnak, mint Isten sokféle kegyelmének jó sáfárai;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'Ha valaki szól, mintegy Isten ígéit szólja: ha valaki szolgál, mintegy azzal az erővel szolgáljon, a melyet Isten ád: hogy mindenben dícsőíttessék a Jézus Krisztus által, a kinek dicsőség és hatalom örökkön-örökké. Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'Szeretteim, ne rémüljetek meg attól a tűztől, a mely próbáltatás végett támadt köztetek, mintha valami rémületes dolog történnék veletek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'Sőt, a mennyiben részetek van a Krisztus szenvedéseiben, örüljetek, hogy az ő dicsőségének megjelenésekor is vígadozva örvendezhessetek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'Boldogok vagytok, ha Krisztus nevéért gyaláznak titeket; mert megnyugszik rajtatok a dicsőségnek és az Istennek Lelke, a mit amazok káromolnak ugyan, de ti dicsőítitek azt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'Mert senki se szenvedjen közületek mint gyilkos, vagy tolvaj, vagy gonosztévő, vagy mint más dolgába avatkozó:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'Ha pedig mint keresztyén szenved, ne szégyelje, sőt dicsőítse azért az Istent.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'Mert itt az ideje, hogy elkezdődjék az ítélet az Istennek házán: ha pedig először mi rajtunk kezdődik, mi lesz azoknak a végök, a kik nem engedelmeskednek az Isten evangyéliomának?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'És ha az igaz is alig tartatik meg, hová lesz az istentelen és bűnös?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'Annakokáért a kik az Isten akaratából szenvednek is, ajánlják néki lelköket mint hű teremtőnek, jót cselekedvén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'A köztetek lévő presbitereket kérem én, a presbitertárs, és a Krisztus szenvedésének tanuja, és a megjelenendő dicsőségnek részese;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'Legeltessétek az Istennek köztetek lévő nyáját, gondot viselvén arra nem kényszerítésből, hanem örömest; sem nem rút nyerészkedésből, hanem jóindulattal;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'Sem nem úgy, hogy uralkodjatok a gyülekezeteken, hanem mint példányképei a nyájnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'És mikor megjelenik a főpásztor, elnyeritek a dicsőségnek hervadatlan koronáját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'Hasonlatosképen ti ifjabbak engedelmeskedjetek a véneknek: mindnyájan pedig, egymásnak engedelmeskedvén, az alázatosságot öltsétek fel, mert az Isten a kevélyeknek ellene áll, az alázatosaknak pedig kegyelmet ád.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'Alázzátok meg tehát magatokat Istennek hatalmas keze alatt, hogy felmagasztaljon titeket annak idején.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'Minden gondotokat ő reá vessétek, mert néki gondja van reátok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Józanok legyetek, vigyázzatok; mert a ti ellenségetek, az ördög, mint ordító oroszlán szerte jár, keresvén, kit elnyeljen:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'A kinek álljatok ellen, erősek lévén a hitben, tudva, hogy a világban lévő atyafiságotokon ugyanazok a szenvedések telnek be.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'A minden kegyelemnek Istene pedig, a ki az ő örök dicsőségére hívott el minket a Krisztus Jézusban, titeket, a kik rövid ideig szenvedtetek, ő maga tegyen tökéletesekké, erősekké, szilárdakká és állhatatosokká,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'Övé a dicsőség és a hatalom örökkön-örökké. Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'Silvánus által, a ki, a mint gondolom, hű atyátokfia, röviden írtam, intve és bizonyságot téve, hogy az az Istennek igaz kegyelme, a melyben állotok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'Köszönt titeket a veletek együtt választott babiloni gyülekezet és Márk, az én fiam.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'Köszöntsétek egymást szeretet csókjával. Békesség mindnyájatoknak, a kik Krisztusban vagytok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Simon Péter, Jézus Krisztus szolgája és apostola, azoknak, a kik velünk egyenlő drága hitet nyertek a mi Istenünknek és megtartónknak Jézus Krisztusnak igazságában:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'Kegyelem és békesség adassék néktek bőségesen az Istennek és Jézusnak a mi Urunknak megismerésében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'Mivelhogy az ő isteni ereje mindennel megajándékozott minket, a mi az életre és kegyességre való, Annak megismerése által, a ki minket a saját dicsőségével és hatalmával elhívott;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'A melyek által igen nagy és becses ígéretekkel ajándékozott meg bennünket; hogy azok által isteni természet részeseivé legyetek, kikerülvén a romlottságot, a mely a kívánságban van e világon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'Ugyanerre pedig teljes igyekezetet is fordítván, a ti hitetek mellé ragasszatok jó cselekedetet, a jó cselekedet mellé tudományt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'A tudomány mellé pedig mértékletességet, a mértékletesség mellé pedig tűrést, a tűrés mellé pedig kegyességet,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'A kegyesség mellé pedig atyafiakhoz való hajlandóságot, az atyafiakhoz való hajlandóság mellé pedig szeretetet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'Mert ha ezek megvannak és gyarapodnak bennetek, nem tesznek titeket hivalkodókká, sem gyümölcstelenekké a mi Urunk Jézus Krisztus megismerésére nézve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'Mert a kiben ezek nincsenek meg, az vak, rövidlátó, elfelejtkezvén a régi bűneiből való megtisztulásáról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'Annakokáért, atyámfiai, igyekezzetek inkább a ti elhívatástokat és kiválasztatásotokat erőssé tenni; mert ha ezeket cselekszitek, nem ütköztök meg soha.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'Mert ekképen gazdagon adatik majd néktek a mi Urunknak és megtartónknak, a Jézus Krisztusnak örök országába való bemenetel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'Annakokáért nem mulasztom el, hogy mindenkor emlékeztesselek titeket ezekre, hogy tudjátok ezeket, és erősek vagytok a jelenvaló igazságban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'Méltónak vélem pedig, a míg ebben a sátorban vagyok, hogy emlékeztetés által ébresztgesselek titeket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'Mint a ki tudom, hogy hamar leteszem sátoromat, a miképen a mi Urunk Jézus Krisztus is megjelentette nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'De igyekezni fogok azon, hogy ti az én halálom után is mindenkor megemlékezhessetek ezekről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'Mert nem mesterkélt meséket követve ismertettük meg veletek a mi Urunk Jézus Krisztus hatalmát és eljövetelét; hanem mint a kik szemlélői voltunk az ő nagyságának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'Mert a mikor az Atya Istentől azt a tisztességet és dicsőséget nyerte, hogy hozzá a felséges dicsőség ilyen szózata jutott: Ez az én szeretett Fiam, a kiben én gyönyörködöm:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'Ezt az égből jövő szózatot mi hallottuk, együtt lévén vele a szent hegyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'És igen biztos nálunk a prófétai beszéd is, a melyre jól teszitek, ha figyelmeztek, mint sötét helyen világító szövétnekre, míg nappal virrad, és hajnalcsillag kél fel szívetekben;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'Tudván először azt, hogy az írásban egy prófétai szó sem támad saját magyarázatból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'Mert sohasem ember akaratából származott a prófétai szó; hanem a Szent Lélektől indíttatva szólottak az Istennek szent emberei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'Valának pedig hamis próféták is a nép között, a miképen ti köztetek is lesznek hamis tanítók, a kik veszedelmes eretnekségeket fognak becsempészni, és az Urat, a ki megváltotta őket, megtagadván, önmagokra hirtelen való veszedelmet hoznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'És sokan fogják követni azoknak romlottságát; a kik miatt az igazság útja káromoltatni fog.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'És a telhetetlenség miatt költött beszédekkel vásárt űznek belőletek; kiknek kárhoztatásuk régtől fogva nem szünetel, és romlásuk nem szunnyad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Mert ha nem kedvezett az Isten a bűnbe esett angyaloknak, hanem mélységbe taszítván, a sötétség lánczaira adta oda őket, hogy fenntartassanak az ítéletre;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'És ha a régi világnak sem kedvezett, de Nóét az igazság hirdetőjét, nyolczad magával megőrizte, özönvízzel borítván el az istentelenek világát;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'És ha Sodoma és Gomora városait elhamvasztotta, végromlásra kárhoztatta, például tévén azokra nézve, a kik istentelenkedni fognak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'És ha megszabadította az igaz Lótot, a ki az istenteleneknek fajtalanságban való forgolódása miatt elfáradt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, '(Mert amaz igaz, azok között lakván, a gonosz cselekedeteket látva és hallva, napról-napra gyötri vala az ő igaz lelkét):');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'Meg tudja szabadítani az Úr a kegyeseket a kísértésekből, a gonoszokat pedig az ítélet napjára büntetésre fenntartani.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'Főképen pedig azokat, a kik a testet követvén, tisztátalan kívánságban járnak, és a hatalmasságot megvetik. Vakmerők, magoknak kedveskedők, a kik a méltóságokat káromolni nem rettegnek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'Holott az angyalok, a kik erőre és hatalomra nézve nagyobbak, nem szólnak azok ellen az Úr előtt káromló ítéletet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'De ezek, mint oktalan természeti állatok, a melyek megfogatásra és elpusztításra valók, azokat, a miket nem ismernek, káromolván, azoknak pusztulásával fognak el is pusztulni,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'Megkapván gonoszságuk díját, mint a kik gyönyörűségnek tartják a naponkénti dobzódást; undokságok és fertelmek, a kik kéjelegnek az ő csalárdságukban, mikor együtt lakmároznak veletek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'A kiknek szemei paráznasággal telvék, bűnnel telhetetlenek; elhitetik az állhatatlan lelkeket, szívök gyakorlott a telhetetlenségben, átok gyermekei;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'A kik elhagyván az egyenes útat, eltévelyedtek, követvén Bálámnak, Bosor fiának útját, a ki a gonoszság díját kedvelte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'De megfeddetett az ő törvénytelenségéért: egy igavonó néma állat emberi szóval szólván, megakadályozta a próféta esztelenségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'Ezek víztelen kútfők, széltől hányatott fellegek, a kiknek a sötétség homálya van fenntartva örökre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'Mert hiábavalóság kevély szavait szólván, testi kívánsággal, bujálkodással elhitetik azokat, a kik valóban elszakadtak a tévelygésben élőktől,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'Szabadságot ígérvén azoknak, holott ők magok a romlottság szolgái; mert a kit valaki legyőzött, az annak szolgájává lett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'Mert ha az Úrnak, a megtartó Jézus Krisztusnak megismerése által a világ fertelmeit elkerülték, de ezekbe ismét belekeveredve legyőzetnek, az ő utolsó állapotjuk gonoszabbá lett az elsőnél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'Mert jobb volna rájok nézve, ha meg sem ismerték volna az igazság útját, mint hogy megismervén, elpártoljanak a nekik adott szent parancsolattól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'De betelt rajtok az igaz példabeszéd szava: Az eb visszatért a saját okádására, és a megmosódott disznó a sárnak fertőjébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Ez immár második levélírásom néktek, szeretteim, amelylyel a ti tiszta gondolkozástokat emlékeztetés által serkentgetem;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'Hogy megemlékezzetek a szent prófétáktól ezelőtt mondott beszédekről, és az Úrnak és Megtartónak általunk, az apostolok által közölt parancsolatjáról:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'Tudván először azt, hogy az utolsó időben csúfolkodók támadnak, a kik saját kívánságaik szerint járnak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'És ezt mondják: Hol van az ő eljövetelének ígérete? Mert a mióta az atyák elhunytak, minden azonképen marad a teremtés kezdetétől fogva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'Mert kész-akarva nem tudják azt, hogy egek régtől fogva voltak, és föld, mely vízből és víz által állott elő az Isten szavára;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'A melyek által az akkori világ vízzel elboríttatván elveszett:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'A mostani egek pedig és a föld, ugyanazon szó által megkíméltettek, tűznek tartatván fenn, az ítéletnek és az istentelen emberek romlásának napjára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'Ez az egy azonban ne legyen elrejtve előttetek, szeretteim, hogy egy nap az Úrnál olyan, mint ezer esztendő, és ezer esztendő mint egy nap.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'Nem késik el az ígérettel az Úr, mint némelyek késedelemnek tartják; hanem hosszan tűr érettünk, nem akarván, hogy némelyek elveszszenek, hanem hogy mindenki megtérésre jusson.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'Az Úr napja pedig úgy jő majd el, mint éjjeli tolvaj, a mikor az egek ropogva elmúlnak, az elemek pedig megégve felbomlanak, és a föld és a rajta lévő dolgok is megégnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Mivelhogy azért mindezek felbomlanak, milyeneknek kell lennetek néktek szent életben és kegyességben,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'A kik várjátok és sóvárogjátok az Isten napjának eljövetelét, a melyért az egek tűzbe borulva felbomlanak, és az elemek égve megolvadnak!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'De új eget és új földet várunk az ő ígérete szerint, a melyekben igazság lakozik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'Annakokáért szeretteim, ezeket várván, igyekezzetek, hogy szeplő nélkül és hiba nélkül valóknak találjon titeket békességben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'És a mi Urunknak hosszútűrését idvességnek tartsátok; a miképen a mi szeretett atyánkfia Pál is írt néktek a néki adott bölcsesség szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'Szinte minden levelében is, a mikor ezekről beszél azokban; a melyekben vannak némely nehezen érthető dolgok, a miket a tudatlanok és állhatatlanok elcsűrnek-csavarnak, mint egyéb írásokat is, a magok vesztére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'Ti azért szeretteim előre tudván ezt, őrizkedjetek, hogy az istentelenek tévelygéseitől elragadtatva, a saját erősségetekből ki ne essetek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'Hanem növekedjetek a kegyelemben és a mi Urunknak és megtartó Jézus Krisztusunknak ismeretében. Néki legyen dicsőség, mind most, mind örökkön-örökké. Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'A mi kezdettől fogva vala, a mit hallottunk, a mit szemeinkkel láttunk, a mit szemléltünk, és kezeinkkel illettünk, az életnek Ígéjéről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, '(És az élet megjelent és láttuk és tanubizonyságot teszünk róla és hirdetjük néktek az örök életet, a mely az Atyánál vala és megjelent nékünk;)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'A mit hallottunk és láttunk, hirdetjük néktek, hogy néktek is közösségtek legyen velünk, és pedig a mi közösségünk az Atyával és az ő Fiával, a Jézus Krisztussal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'És ezeket azért írjuk néktek, hogy örömetek teljes legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'És ez az az üzenet, a melyet tőle hallottunk és hirdetünk néktek, hogy az Isten világosság és nincsen ő benne semmi sötétség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'Ha azt mondjuk, hogy közösségünk van vele, és sötétségben járunk; hazudunk és nem az igazságot cselekeszszük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'Ha pedig a világosságban járunk, a mint ő maga a világosságban van: közösségünk van egymással, és Jézus Krisztusnak, az ő Fiának vére megtisztít minket minden bűntől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Ha azt mondjuk, hogy nincsen bűn mi bennünk, magunkat csaljuk meg és igazság nincsen mi bennünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'Ha megvalljuk bűneinket, hű és igaz, hogy megbocsássa bűneinket és megtisztítson minket minden hamisságtól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'Ha azt mondjuk, hogy nem vétkeztünk, hazuggá teszszük őt, és az ő ígéje nincsen mi bennünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Én fiacskáim, ezeket azért írom néktek, hogy ne vétkezzetek. És ha valaki vétkezik, van Szószólónk az Atyánál, az igaz Jézus Krisztus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'És ő engesztelő áldozat a mi vétkeinkért; de nemcsak a mienkért, hanem az egész világért is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'És arról tudjuk meg, hogy megismertük őt, ha az ő parancsolatait megtartjuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'A ki ezt mondja: Ismerem őt, és az ő parancsolatait nem tartja meg, hazug az, és nincs meg abban az igazság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'A ki pedig megtartja az ő beszédét, abban valósággal teljessé lett az Isten szeretete. Erről tudjuk meg, hogy ő benne vagyunk;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'A ki azt mondja, hogy ő benne marad, annak úgy kell járnia, a mint ő járt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'Atyámfiai, nem új parancsolatot írok néktek, hanem régi parancsolatot, a mely előttetek volt kezdettől fogva; a régi parancsolat az íge, a melyet hallottatok kezdettől fogva.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'Viszont új parancsolatot írok néktek, a mi igaz ő benne és ti bennetek; mert a sötétség szűnni kezd, és az igaz világosság már fénylik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'A ki azt mondja, hogy a világosságban van, és gyűlöli az ő atyjafiát az még mindig a sötétségben van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'A ki szereti az ő atyjafiát a világosságban marad, és nincs benne botránkozásra való.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'A ki pedig gyűlöli az ő atyjafiát, a sötétségben van, és a sötétségben jár, és nem tudja hová megy, mert a sötétség megvakította az ő szemeit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Írok néktek, gyermekek, mert a ti bűneitek megbocsáttattak az ő nevéért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'Írok néktek atyák, mert megismertétek azt, a ki kezdettől fogva van. Írok néktek ifjak, mert meggyőztétek a gonoszt. Írok néktek fiacskák, mert megismertétek az Atyát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Írtam néktek atyák, mert megismertétek azt, a ki kezdettől fogva van. Írtam néktek ifjak, mert erősek vagytok, és az Isten ígéje megmarad bennetek, és meggyőztétek a gonoszt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'Ne szeressétek a világot, se azokat, a mik a világban vannak. Ha valaki a világot szereti, nincs meg abban az Atya szeretete.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'Mert mindaz, a mi a világban van, a test kívánsága, és a szemek kívánsága, és az élet kérkedése nem az Atyától van, hanem a világból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'És a világ elmúlik, és annak kívánsága is; de a ki az Isten akaratát cselekszi, megmarad örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'Fiacskáim, itt az utolsó óra; és a mint hallottátok, hogy az antikrisztus eljő, így most sok antikrisztus támadt; a honnan tudjuk, hogy itt az utolsó óra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'Közülünk váltak ki, de nem voltak közülünk valók; mert ha közülünk valók lettek volna, velünk maradtak volna; de hogy nyilvánvalóvá legyen felőlük, hogy nem mindnyájan közülünk valók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'És néktek kenetetek van a Szenttől, és mindent tudtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Nem azért írtam néktek, mivel nem ismeritek az igazságot, hanem mivel ismeritek azt, és mivel semmi sincsen az igazságból, a mi hazugság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'Ki a hazug, ha nem az, a ki tagadja hogy a Jézus a Krisztus? Ez az antikrisztus, a ki tagadja az Atyát és a Fiút.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'Senkiben nincs meg az Atya, a ki tagadja a Fiút. A ki vallást tesz a Fiúról, abban az Atya is megvan.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'A mit azért ti kezdettől hallottatok, az maradjon meg bennetek. Ha bennetek marad az, a mit kezdettől fogva hallottatok, ti is az Atyában és a Fiúban maradtok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'És az az ígéret, a melyet ő ígért nékünk: az örök élet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'Ezeket írtam néktek azok felől, a kik elhitetnek titeket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'És az a kenet, a melyet ti kaptatok tőle, bennetek marad, és így nincs szükségetek arra, hogy valaki tanítson titeket; hanem a mint az a kenet megtanít titeket mindenre, úgy igaz is az és nem hazugság, és a miként megtanított titeket, úgy maradjatok ő benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'És most, fiacskáim, maradjatok ő benne; hogy mikor megjelenik, bizodalmunk legyen, és meg ne szégyenüljünk előtte az ő eljövetelekor.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'Ha tudjátok, hogy ő igaz, tudjátok, hogy a ki az igazságot cselekszi, az mind tőle született.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'Lássátok milyen nagy szeretetet adott nékünk az Atya, hogy Isten fiainak neveztetünk! A világ azért nem ismer minket, mert nem ismerte meg Őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Szeretteim, most Isten gyermekei vagyunk, és még nem lett nyilvánvalóvá, hogy mivé leszünk. De tudjuk, hogy ha nyilvánvalóvá lesz, hasonlókká leszünk Ő hozzá; mert meg fogjuk őt látni, a mint van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'És a kiben megvan ez a reménység Ő iránta, az mind megtisztítja ő magát, a miképen Ő is tiszta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Valaki a bűnt cselekszi, az a törvénytelenséget is cselekszi; a bűn pedig a törvénytelenség.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'És tudjátok, hogy ő azért jelent meg, hogy a mi bűneinket elvegye; és ő benne nincsen bűn.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'A ki ő benne marad, egy sem esik bűnbe; a ki bűnbe esik, egy sem látta őt, sem meg nem ismerte őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Fiacskáim! senki el ne hitessen benneteket: a ki az igazságot cselekszi, igaz az, a miként Ő is igaz:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'A ki a bűnt cselekszi az ördögből van; mert az ördög kezdettől fogva bűnben leledzik. Azért jelent meg az Istennek Fia, hogy az ördög munkáit lerontsa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Senki sem cselekszik bűnt, a ki az Istentől született, mert benne marad annak magva; és nem cselekedhetik bűnt, mivelhogy Istentől született.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'Erről ismerhetők meg az Isten gyermekei és az ördög gyermekei: a ki igazságot nem cselekszik, az egy sem az Istentől való, és az sem, a ki nem szereti az ő atyjafiát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'Mert ez az üzenet, a melyet kezdettől fogva hallottatok, hogy szeressük egymást;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'Nem úgy, mint Kain, aki a gonosztól vala, és meggyilkolá az ő testvérét. És miért gyilkolta meg azt? Mivel az ő cselekedetei gonoszok valának, a testvéreié pedig igazak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Ne csodálkozzatok atyámfiai, ha gyűlöl titeket a világ!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'Mi tudjuk, hogy általmentünk a halálból az életbe, mert szeretjük a mi atyánkfiait. A ki nem szereti az ő atyjafiát, a halálban marad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'A ki gyűlöli az ő atyjafiát, mind embergyilkos az: és tudjátok, hogy egy embergyilkosnak sincs örök élete, a mi megmaradhatna ő benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'Arról ismertük meg a szeretetet, hogy Ő az ő életét adta érettünk: mi is kötelesek vagyunk odaadni életünket a mi atyánkfiaiért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'A kinek pedig van miből élnie e világon, és elnézi, hogy az ő atyjafia szükségben van, és elzárja attól az ő szívét, miképen marad meg abban az Isten szeretete?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'Fiacskáim, ne szóval szeressünk, se nyelvvel; hanem cselekedettel és valósággal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'És erről ismerjük meg, hogy mi az igazságból vagyunk, és így tesszük bátorságosakká ő előtte a mi szíveinket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'Hogy ha vádol minket a szív, mivelhogy nagyobb az Isten a mi szívünknél, és mindent tud.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'Szeretteim, ha szívünk nem vádol minket, bizodalmunk van az Istenhez;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'És akármit kérjünk, megnyerjük tőle, mert megtartjuk az ő parancsolatait, és azokat cselekeszszük, a mik kedvesek előtte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'Ez pedig az ő parancsolata, hogy higyjünk az ő Fiának, a Jézus Krisztusnak nevében, és szeressük egymást, a mint megparancsolta nékünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'És a ki az ő parancsolatait megtartja, az Ő benne marad és Ő is abban; és abból ismerjük meg, hogy bennünk marad, abból a Lélekből, a melyet nékünk adott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Szeretteim, ne higyjetek minden léleknek, hanem próbáljátok meg a lelkeket, ha Istentől vannak-é; mert sok hamis próféta jött ki a világba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'Erről ismerjétek meg az Isten Lelkét: valamely lélek Jézust testben megjelent Krisztusnak vallja, az Istentől van;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'És valamely lélek nem vallja Jézust testben megjelent Krisztusnak, nincsen az Istentől: és az az antikrisztus lelke, a melyről hallottátok, hogy eljő; és most e világban van már.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'Ti az Istentől vagytok fiacskáim, és legyőztétek azokat; mert nagyobb az, a ki bennetek van, mint az, a ki e világban van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'Azok a világból valók; azért a világ szerint beszélnek, és a világ hallgat rájok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'Mi az Istentől vagyunk: a ki ismeri az Istent, hallgat reánk, a ki nincsen az Istentől, nem hallgat reánk. Erről ismerjük meg az igazságnak lelkét és a tévelygésnek lelkét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Szeretteim, szeressük egymást: mert a szeretet az Istentől van; és mindaz, a ki szeret, az Istentől született, és ismeri az Istent.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'A ki nem szeret, nem ismerte meg az Istent; mert az Isten szeretet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'Az által lett nyilvánvalóvá az Isten szeretete bennünk, hogy az ő egyszülött Fiát elküldte az Isten e világra, hogy éljünk általa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'Nem abban van a szeretet, hogy mi szerettük az Istent, hanem hogy ő szeretett minket, és elküldte az ő Fiát engesztelő áldozatul a mi bűneinkért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Szeretteim, ha így szeretett minket az Isten, nekünk is szeretnünk kell egymást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Az Istent soha senki nem látta: Ha szeretjük egymást, az Isten bennünk marad, és az ő szeretete teljessé lett bennünk:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'Erről ismerjük meg, hogy benne maradunk és ő mibennünk; mert a maga Lelkéből adott minékünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'És mi láttuk és bizonyságot teszünk, hogy az Atya elküldte a Fiút a világ üdvözítőjéül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'A ki vallja, hogy Jézus az Istennek Fia, az Isten megmarad abban, és ő is az Istenben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'És mi megismertük és elhittük az Istennek irántunk való szeretetét. Az Isten szeretet; és a ki a szeretetben marad, az Istenben marad, és az Isten is ő benne.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'Azzal lesz teljessé a szeretet közöttünk, hogy bizodalmunk van az ítélet napjához, mert a mint ő van, úgy vagyunk mi is e világban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'A szeretetben nincsen félelem; sőt a teljes szeretet kiűzi a félelmet, mert a félelem gyötrelemmel jár: a ki pedig fél, nem lett teljessé a szeretetben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'Mi szeressük őt; mert ő előbb szeretett minket!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'Ha azt mondja valaki, hogy: Szeretem az Istent, és gyűlöli a maga atyjafiát, hazug az: mert a ki nem szereti a maga atyjafiát, a kit lát, hogyan szeretheti az Istent, a kit nem lát?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'Az a parancsolatunk is van ő tőle, hogy a ki szereti az Istent, szeresse a maga atyjafiát is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Mindaz, a ki hiszi, hogy Jézus a Krisztus, Istentől született; és mindaz, a ki szereti a szülőt, azt is szereti, a ki attól született.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'Abból ismerjük meg, hogy szeretjük az Isten gyermekeit, hogyha az Istent szeretjük, és az ő parancsolatait megtartjuk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'Mert az az Isten szeretete, hogy megtartjuk az ő parancsolatait; az ő parancsolatai pedig nem nehezek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'Mert mindaz, a mi az Istentől született, legyőzi a világot; és az a győzedelem, a mely legyőzte a világot, a mi hitünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'Ki az, a ki legyőzi a világot, ha nem az, a ki hiszi, hogy Jézus az Isten Fia?!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'Ez az, a ki víz és vér által jő vala, Jézus a Krisztus; nemcsak a vízzel, hanem a vízzel és a vérrel. És a Lélek az, a mely bizonyságot tesz, mert a Lélek az igazság.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'Mert hárman vannak, a kik bizonyságot tesznek a mennyben, az Atya, az Íge és a Szent Lélek: és ez a három egy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'És hárman vannak, a kik bizonyságot tesznek a földön, a Lélek, a víz és a vér; és ez a három is egy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'Ha elfogadjuk az emberek bizonyságtételét, az Isten bizonyságtétele nagyobb: mert az Isten bizonyságtétele az, a melylyel bizonyságot tett az ő Fiáról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'A ki hisz az Isten Fiában, bizonyságtétele van önmagában. A ki nem hisz az Istennek, hazuggá tette őt; mert nem hitt abban a bizonyságtételben, a melylyel bizonyságot tett Isten az ő Fiáról.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'És ez az a bizonyságtétel, hogy örök életet adott nékünk az Isten és ez az élet az ő Fiában van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'A kié a Fiú, azé az élet: a kiben nincs meg az Isten Fia, az élet sincs meg abban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'Ezeket írtam néktek, a kik hisztek az Isten Fiának nevében, hogy tudjátok meg, hogy örök életetek van, és hogy higyjetek az Isten Fiának nevében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'És ez az a bizodalom, a melylyel ő hozzá vagyunk, hogy ha kérünk valamit az ő akarata szerint, meghallgat minket:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'És ha tudjuk, hogy meghallgat bennünket, akármit kérünk, tudjuk, hogy megvannak a kéréseink, a melyeket kértünk ő tőle.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'Ha valaki látja, hogy az ő atyjafia vétkezik, de nem halálos bűnt, könyörögjön, és az Isten életet ad annak, a ki nem halálos bűnnel vétkezik. Van halálos bűn; nem az ilyenért mondom, hogy könyörögjön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'Minden igazságtalanság bűn; de van nem halálos bűn is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'Tudjuk, hogy valaki Istentől született, nem vétkezik: hanem a ki Istentől született, megőrzi magát, és a gonosz nem illeti őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'Tudjuk, hogy Istentől vagyunk, és az egész világ a gonoszságban vesztegel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'De tudjuk azt is, hogy az Isten Fia eljött, és értelmet adott nékünk arra, hogy megismerjük az igazat, és hogy mi az igazban, az ő Fiában, a Jézus Krisztusban vagyunk. Ez az igaz Isten és az örök élet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'Fiacskáim, oltalmazzátok meg magatokat a bálványoktól. Ámen!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'A presbiter a kiválasztott asszonynak és az ő gyermekeinek, a kiket én igazán szeretek, és nem csak én, hanem mindenki, a ki megismerte az igazságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'Az igazságért, a mely megmarad bennünk, és velünk lesz mindörökké:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'Kegyelem, irgalom, békesség legyen veletek az Atya Istentől, és az Úr Jézus Krisztustól az Atyának Fiától igazsággal és szeretettel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'Felettébb örültem, hogy olyanokat találtam gyermekeid között, a kik igazságban járnak, a mint parancsolatot vettünk az Atyától.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'És most kérlek téged, Asszonyom, nem mintha új parancsolatot írnék néked, hanem, a melyet kezdettől fogva vettünk, hogy szeressük egymást!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'És ez a szeretet, hogy járjunk az ő parancsolatai szerint. Ez a parancsolat, a mint kezdettől fogva hallottátok, hogy abban járjatok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'Mert sok hitető jött e világra, a kik nem vallják a Jézust testben megjelent Krisztusnak. Ez a hitető és az antikrisztus.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'Vigyázzatok magatokra, hogy el ne veszítsük, a mit munkáltunk, hanem teljes jutalmat nyerjünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'A ki félrelép és nem marad meg a Krisztus tudománya mellett, annak egynek sincs Istene. A ki megmarad a Krisztus tudománya mellett, mind az Atya, mind a Fiú az övé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'Ha valaki elmegy hozzátok és nem ezt a tudományt viszi, ne fogadjátok azt be házatokba, és azt ne köszöntsétek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'Mert a ki köszönti azt, részes annak gonosz cselekedeteiben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'Sok írni valóm volna néktek, de nem akartam papirossal és tintával, hanem reménylem, hogy elmegyek hozzátok, és szemtől szembe beszélhetünk, hogy örömünk teljes legyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'Köszöntenek téged a te kiválasztott nőtestvérednek gyermekei. Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'A presbiter a szeretett Gájusnak, a kit én igazán szeretek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'Szeretett barátom, kívánom, hogy mindenben jól legyen dolgod, és légy egészséges, a mint jó dolga van a lelkednek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'Mert felettébb örültem, a mikor atyafiak jöttek és bizonyságot tettek a te igazságodról, úgy, a mint te az igazságban jársz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'Nincs annál nagyobb örömem, mintha hallom, hogy az én gyermekeim az igazságban járnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'Szeretett barátom, híven cselekszel mindenben, a mit az atyafiakért, és pedig az idegenekért teszel,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'A kik bizonyságot tettek a te szeretetedről a gyülekezet előtt; a kiket jól teszed, ha Istenhez méltóan bocsátasz útjokra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'Mert az ő nevéért mentek ki, semmit sem fogadván el a pogányoktól;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'Nékünk azért be kell fogadnunk az ilyeneket, hogy munkatársaikká lehessünk az igazságban.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'Írtam a gyülekezetnek; de Diotrefesz, a ki elsőséget kíván közöttük, nem fogad el minket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'Ezért, ha odamegyek, felemlítem az ő dolgait, a melyeket cselekszik, gonosz szavakkal csácsogván ellenünk; sőt nem elégedvén meg ezzel, maga sem fogadja be az atyafiakat, és a kik ezt akarnák, azokat is akadályozza, és az egyházból kiveti.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'Szeretett barátom, ne a rosszat kövesd, hanem a jót. A ki jót cselekszik, az Istentől van; a ki pedig rosszat cselekszik, nem látta az Istent.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Demeter mellett mindenki bizonyságot tett, maga az igazság is; de mi is bizonyságot teszünk, és tudjátok, hogy a mi bizonyságtételünk igaz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'Sok írni valóm volna, de nem akarok tintával és tollal írni néked:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'Hanem reménylem, hogy csakhamar meglátlak téged és szemtől szembe beszélhetünk.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 15, 'Békesség néked! Köszöntenek téged a te barátaid. Köszöntsd a barátainkat név szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Júdás, Jézus Krisztusnak szolgája, Jakabnak pedig atyafia, az elhívottaknak a kik az Atya Istentől megszenteltettek és Jézus Krisztustól megtartattak:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'Irgalmasság, békesség és szeretet adassék néktek bőségesen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'Szeretteim, mivelhogy minden igyekezettel azon vagyok, hogy írjak néktek a közös üdvösség felől, kénytelen voltam, hogy intőleg írjak néktek, hogy tusakodjatok a hitért, a mely egyszer a szenteknek adatott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'Mert belopózkodtak valami emberek, a kik régen előre beírattak ezen ítéletre, istentelenek, kik a mi Istenünknek kegyelmét bujálkodásra fordítják, és az egyedüli Urat, az Istent, és a mi Urunkat, a Jézus Krisztust megtagadják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Emlékeztetni akarlak továbbá titeket, mint a kik egyszer már tudjátok, hogy az Úr, a mikor a népet Égyiptom földéből kiszabadította, viszontag azokat, a kik nem hittek, elvesztette.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'És az angyalokat is, a kik nem tartották meg fejedelemségöket, hanem elhagyták az ő lakóhelyöket, a nagy nap ítéletére örök bilincseken, sötétségben tartotta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'Miképen Sodoma és Gomora és a körültök lévő városok is, a melyek azokhoz hasonlóan paráználkodtak, és más test után jártak, például vannak előttünk, örök tűznek büntetését szenvedvén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'Hasonlóképen mégis ezek is álomba merülvén, a testet megfertőztetik, a hatalmasságot megvetik, és a méltóságokat káromolják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'Pedig Mihály arkangyal, mikor az ördöggel vitatkozván Mózes teste felett vetélkedett, nem mert arra káromló ítéletet mondani, hanem azt mondá: Dorgáljon meg téged az Úr!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'Ezek pedig azokat káromolják, a miket nem tudnak; a miket pedig természet szerint tudnak, mint az oktalan állatok, azok által megromolnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'Jaj nékik! mert a Kain útján indultak el, és a Bálám tévelygéseivel bérért szakadtak ki, és a Kóré ellenkezésével vesztek el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'Ezek szennyfoltok a ti szeretetvendégségeiteken, tartózkodás nélkül veletek lakmároznak, magokat hízlalják; víztelen, szelektől hányt-vetett fellegek; elhervadt, gyümölcstelen, kétszer meghalt és tőből kiszaggatott fák;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'Tengernek megvadult habjai, a magok rútságát tajtékozók; tévelygő csillagok, a kiknek a sötétség homálya van fenntartva örökre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'Ezekről is prófétált pedig Énok, a ki Ádámtól fogva a hetedik volt, mondván: Ímé eljött az Úr az ő sok ezer szentjével,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'Hogy ítéletet tartson mindenek felett, és feddőzzék mindazok ellen, a kik közöttök istentelenek, istentelenségöknek minden cselekedetéért, a melyekkel istentelenkedtek, és minden kemény beszédért, a melyet az istentelen bűnösök szóltak ő ellene.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'Ezek zúgolódók, panaszolkodók, a magok kívánságai szerint járók; szájok kevélységet szól, haszonlesésből személyimádók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'Ti azonban, szeretteim, emlékezzetek meg azokról a beszédekről, a melyeket a mi Urunk Jézus Krisztus apostolai mondottak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'Mert azt mondták néktek, hogy az utolsó időben lesznek csúfolódók, a kik az ő istentelen kívánságai szerint járnak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'Ezek azok, a kik különszakadnak, érzékiek, kikben nincsen Szent Lélek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'Ti pedig szeretteim, épülvén a ti szentséges hitetekben, imádkozván Szent Lélek által,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'Tartsátok meg magatokat Istennek szeretetében, várván a mi Urunk Jézus Krisztusnak irgalmasságát az örök életre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'És könyörüljetek némelyeken, megkülönböztetvén őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, 'Másokat pedig rettentéssel mentsetek meg, kiragadva őket a tűzből, és útálva még a ruhát is, a melyet a test beszennyezett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'Annak pedig, a ki titeket a bűntől megőrízhet, és az ő dicsősége elé állíthat feddhetetlenségben nagy örömmel,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 25, 'Az egyedül bölcs Istennek, a mi megtartónknak, dicsőség, nagyság, erő és hatalom most és mind örökké. Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Jézus Krisztus kijelentése, a melyet adott néki az Isten, hogy megmutassa az ő szolgáinak, a miknek meg kell lenniök hamar: Ő pedig elküldvén azt az ő angyala által, megjelenté az ő szolgájának Jánosnak,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'A ki bizonyságot tett az Isten beszédéről és Jézus Krisztus bizonyságtételéről, mindenről, a mit látott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'Boldog, a ki olvassa, és a kik hallgatják e prófétálásnak beszédeit, és megtartják azokat, a melyek megírattak abban; mert az idő közel van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'János a hét gyülekezetnek, a mely Ázsiában van: Kegyelem néktek és békesség attól, a ki van, a ki vala és a ki eljövendő; és a hét lélektől, a mely az ő királyiszéke előtt van,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'És a Jézus Krisztustól, a ki a hű tanúbizonyság, a halottak közül az elsőszülött, és a föld királyainak fejedelme. Annak, a ki minket szeretett, és megmosott bennünket a mi bűneinkből az ő vére által,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'És tett minket királyokká és papokká az ő Istenének és Atyjának: annak dicsőség és hatalom mind örökkön örökké! Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'Ímé eljő a felhőkkel; és minden szem meglátja őt, még a kik őt által szegezték is; és siratja őt e földnek minden nemzetsége. Úgy van. Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, 'Én vagyok az Alfa és az Omega, kezdet és vég, ezt mondja az Úr, a ki van és a ki vala és a ki eljövendő, a Mindenható.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Én János, a ki néktek atyátokfia is vagyok, társatok is a Jézus Krisztus szenvedésében és királyságában és tűrésében, a szigeten valék, a mely Páthmósnak neveztetik, az Isten beszédéért és a Jézus Krisztus bizonyságtételéért.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'Lélekben valék ott az Úrnak napján, és hallék hátam megett nagy szót, mint egy trombitáét,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'A mely ezt mondja vala: Én vagyok az Alfa és az Omega, az Első és Utolsó; és: A mit látsz, írd meg könyvben, és küldd el a hét gyülekezetnek, a mely Ázsiában van, Efézusban, Smirnában, Pergámumban, Thiatirában, Sárdisban, Filadelfiában és Laodiczeában.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'Megfordulék azért, hogy lássam a szót, a mely velem beszéle; megfordulván pedig, láték hét arany gyertyatartót;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'És a hét gyertyatartó között hasonlót az ember Fiához, bokáig érő ruhába öltözve, és mellénél aranyövvel körülövezve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'Az ő feje pedig és a haja fehér vala, mint a fehér gyapjú, mint a hó; és a szemei olyanok, mint a tűzláng;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'És a lábai hasonlók valának az izzó fényű érczhez, mintha kemenczében tüzesedtek volna meg; a szava pedig olyan, mint a sok vizek zúgása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'Vala pedig a jobb kezében hét csillag; és a szájából kétélű éles kard jő vala ki; és az ő orczája, mint a nap a mikor fénylik az ő erejében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'Mikor pedig láttam őt, leesém az ő lábaihoz, mint egy holt. És reám veté az ő jobbkezét, mondván nékem: Ne félj; én vagyok az Első és az Utolsó,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, 'És az Élő; pedig halott valék, és ímé élek örökkön örökké Ámen, és nálam vannak a pokolnak és a halálnak kulcsai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'Írd meg, a miket láttál és a mik vannak és a mik ezek után lesznek:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'A hét csillag titkát, a melyet láttál az én jobb kezemben, és a hét arany gyertyatartót. A hét csillag a hét gyülekezet angyala, és a mely hét gyertyatartót láttál, az hét gyülekezet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, 'Az Efézusbeli gyülekezet angyalának írd meg: Ezeket mondja az, a ki az ő jobbkezében tartja a hét csillagot, a ki jár a hét arany gyertyatartó között:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'Tudom a te dolgaidat, és a te fáradságodat és tűrésedet, és hogy a gonoszokat nem szenvedheted, és megkísértetted azokat, a kik apostoloknak mondják magokat, holott nem azok, és hazugoknak találtad őket;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'És terhet viseltél, és béketűrő vagy, és az én nevemért fáradoztál és nem fáradtál el.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'De az a mondásom ellened, hogy az első szeretetedet elhagytad.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'Emlékezzél meg azért honnét estél ki, és térj meg, és az előbbi cselekedeteket cselekedd; ha pedig nem, hamar eljövök ellened, és a te gyertyatartódat kimozdítom helyéből, ha meg nem térsz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'De az megvan benned, hogy a Nikolaiták cselekedeteit gyűlölöd, a melyeket én is gyűlölök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'A kinek van füle, hallja, mit mond a Lélek a gyülekezeteknek. A győzedelmesnek enni adok az élet fájáról, a mely az Isten paradicsomának közepette van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'A Smirnabeli gyülekezet angyalának pedig írd meg: Ezt mondja az Első és Utolsó, a ki halott vala és él:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'Tudom a te dolgaidat és nyomorúságodat és szegénységedet (de gazdag vagy), és azoknak káromkodását, a kik azt mondják, hogy ők zsidók, és nem azok, hanem a Sátán zsinagógája.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Semmit ne félj azoktól, a miket szenvedned kell: Ímé a Sátán egynéhányat ti közületek a tömlöczbe fog vetni, hogy megpróbáltassatok; és lesz tíz napig való nyomorúságtok. Légy hív mind halálig, és néked adom az életnek koronáját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'A kinek van füle, hallja, mit mond a Lélek a gyülekezeteknek. A ki győz, annak nem árt a második halál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'A Pergámumbeli gyülekezet angyalának írd meg: Ezt mondja az, a kinél a kétélű éles kard van:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'Tudom a te dolgaidat, és hogy hol lakol, a hol a Sátán királyiszéke van; és az én nevemet megtartod, és az én hitemet nem tagadtad meg Antipásnak, az én hű bizonyságomnak napjaiban sem, a ki megöleték nálatok, a hol a Sátán lakik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'De van valami kevés panaszom ellened, mert vannak ott nálad, a kik a Bálám tanítását tartják, a ki Bálákot tanította, hogy vessen botránykövet az Izráel fiai elé, hogy egyenek a bálványáldozatokból, és paráználkodjanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'Így vannak nálad is, a kik a Nikolaiták tanítását tartják, a mit gyűlölök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'Térj meg: ha pedig nem, ellened megyek hamar, és vívok azok ellen számnak kardjával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'A kinek van füle hallja, mit mond a Lélek a gyülekezeteknek. A győzedelmesnek enni adok az elrejtett mannából, és adok annak fehér kövecskét, és a kövecskén új írott nevet, a melyet senki nem tud, csak az, a ki kapja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'A Thiatirabeli gyülekezet angyalának pedig írd meg: Ezt mondja az Isten Fia, a kinek szemei olyanok, mint a tűzláng, és a kinek lábai hasonlók az ízzó fényű érczhez:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Tudom a te dolgaidat, és szeretetedet, szolgálatodat, és hitedet és tűrésedet, és hogy a te utolsó cselekedeteid többek az elsőknél.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'De van valami kevés panaszom ellened, mert megengeded amaz asszonynak, Jézabelnek, a ki magát prófétának mondja, hogy tanítson és elhitesse az én szolgáimat, hogy paráználkodjanak és a bálványáldozatokból egyenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'Adtam néki időt is, hogy megtérjen az ő paráználkodásából; és nem tért meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'Íme én ágyba vetem őt, és azokat, a kik vele paráználkodnak, nagy nyomorúságba, ha meg nem térnek az ő cselekedeteikből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, 'És az ő fiait megölöm halállal; és megtudják a gyülekezetek mind, hogy én vagyok a vesék és szívek vizsgálója; és mindeniteknek megfizetek a ti cselekedeteitek szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, 'Néktek pedig azt mondom és mind a többi Thiatirabelieknek is, a kiknél nincsen e tudomány, és a kik nem ismerik a Sátán mélységeit, a mint ők nevezik: nem vetek reátok más terhet,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, 'Hanem a mi nálatok van, azt tartsátok meg addig, míg eljövök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, 'És a ki győz, és a ki mindvégig megőrzi az én cselekedeteimet, annak hatalmat adok a pogányokon;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 27, 'És uralkodik rajtuk vasvesszővel, mint a fazekas edényei széttöretnek; a miképen én is vettem az én Atyámtól:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 28, 'És adom annak a hajnalcsillagot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 29, 'A kinek van füle, hallja, mit mond a Lélek a gyülekezeteknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, 'A Sárdisbeli gyülekezet angyalának is írd meg: Ezt mondja az, a kinél van az isteni hét lélek és a hét csillag: Tudom a te dolgaidat, hogy az a neved, hogy élsz, és halott vagy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'Vigyázz, és erősítsd meg a többieket, a kik haló félben vannak; mert nem találtam a te cselekedeteidet Isten előtt teljeseknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'Megemlékezzél azért, hogyan vetted és hallottad; és tartsd meg, és térj meg. Hogyha tehát nem vigyázol, elmegyek hozzád, mint a tolvaj, és nem tudod, mely órában megyek hozzád.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'De van Sárdisban egy kevés neved, azoké a kik nem fertőztették meg a ruháikat: és fehérben fognak velem járni; mert méltók arra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'A ki győz, az fehér ruhákba öltözik; és nem törlöm ki annak nevét az élet könyvéből, és vallást teszek annak nevéről az én Atyám előtt és az ő angyalai előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'A kinek van füle, hallja, mit mond a Lélek a gyülekezeteknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'A Filadelfiabeli gyülekezet angyalának is írd meg: Ezt mondja a Szent, az Igaz, a kinél a Dávid kulcsa van, a ki megnyitja és senki be nem zárja, és bezárja és senki meg nem nyitja:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Tudom a te dolgaidat (ímé adtam elődbe egy nyitott ajtót, a melyet senki be nem zárhat), hogy kevés erőd van, és megtartottad az én beszédemet, és nem tagadtad meg az én nevemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Ímé én adok a Sátán zsinagógájából, azok közül, a kik zsidóknak mondják magukat és nem azok, hanem hazudnak; ímé azt mívelem, hogy azok eljőjjenek és leboruljanak a te lábaid előtt, és megtudják, hogy én szerettelek téged.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'Mivel megtartottad az én béketűrésre intő beszédemet, én is megtartalak téged a megpróbáltatás idején, a mely az egész világra eljő, hogy megpróbálja e föld lakosait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Ímé eljövök hamar: tartsd meg a mi nálad van, hogy senki el ne vegye a te koronádat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'A ki győz, oszloppá teszem azt az én Istenemnek templomában, és többé onnét ki nem jő; és felírom ő reá az én Istenemnek nevét, és az én Istenem városának nevét, az új Jeruzsálemét, a mely az égből száll alá az én Istenemtől, és az én új nevemet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'A kinek van füle, hallja, mit mond a Lélek a gyülekezeteknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'A Laodiczeabeli gyülekezet angyalának is írd meg: Ezt mondja az Ámen, a hű és igaz bizonyság, az Isten teremtésének kezdete:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'Tudom a te dolgaidat, hogy te sem hideg nem vagy, sem hév; vajha hideg volnál, vagy hév.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'Így mivel lágymeleg vagy, sem hideg, sem hév, kivetlek téged az én számból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'Mivel ezt mondod: Gazdag vagyok, és meggazdagodtam és semmire nincs szükségem; és nem tudod, hogy te vagy a nyomorult és a nyavalyás és szegény és vak és mezítelen:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'Azt tanácslom néked, hogy végy tőlem tűzben megpróbált aranyat, hogy gazdaggá légy; és fehér ruhákat, hogy öltözeted legyen, és ne láttassék ki a te mezítelenségednek rútsága; és szemgyógyító írral kend meg a te szemeidet, hogy láss.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, 'A kiket én szeretek, megfeddem és megfenyítem: légy buzgóságos azért, és térj meg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'Ímé az ajtó előtt állok és zörgetek; ha valaki meghallja az én szómat és megnyitja az ajtót, bemegyek ahhoz és vele vacsorálok, és ő én velem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, 'A ki győz, megadom annak, hogy az én királyiszékembe űljön velem, a mint én is győztem és ültem az én Atyámmal az ő királyiszékében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 22, 'A kinek van füle, hallja, mit mond a Lélek a gyülekezeteknek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Ezek után látám, és ímé egy megnyílt ajtó vala a mennyben, és az első szó, a melyet mint egy velem beszélő trombitának szavát hallék, ezt mondja vala: Jőjj fel ide, és megmutatom néked, a miknek meg kell lenni ezután.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'És azonnal elragadtatám lélekben: és ímé egy királyiszék vala letéve a mennyben, és üle valaki a királyiszékben;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'És a ki üle, tekintetére nézve hasonló vala a jáspis és sárdius kőhöz; és a királyiszék körül szivárvány vala, látszatra smaragdhoz hasonló.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'És a királyiszék körül huszonnégy királyiszék vala; és a királyiszékekben látám ülni a huszonnégy Vénet fehér ruhákba öltözve: és a fejökön arany koronák valának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'A királyiszékből pedig villámlások és mennydörgések és szózatok jőnek vala ki. És hét tűzlámpás ég vala a királyiszék előtt, a mely az Istennek hét lelke;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'És a királyiszék előtt üvegtenger vala, hasonló a kristályhoz; és a királyiszék közepette és a királyiszék körül négy lelkes állat, szemekkel teljesek elől és hátul.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'És az első lelkes állat hasonló vala az oroszlánhoz, és a második lelkes állat hasonló a borjúhoz, és a harmadik lelkes állatnak olyan arcza vala, mint egy embernek, és a negyedik lelkes állat hasonló vala a repülő sashoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'És a négy lelkes állat, a melyek közül mindeniknek hat-hat szárnya vala, köröskörül és belül teljes vala szemekkel; és meg nem szűnik vala nappal és éjjel ezt mondani: Szent, szent, szent az Úr, a mindenható Isten, a ki vala és a ki van és a ki eljövendő,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'És mikor a lelkes állatok dicsőséget, tisztességet és hálát adnak annak, a ki a királyiszékben ül, annak, a ki örökkön örökké él,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'Leesik a huszonnégy Vén az előtt, a ki a királyiszékben ül, és imádja azt, a ki örökkön örökké él, és az ő koronáit a királyiszék elé teszi, mondván:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, 'Méltó vagy Uram, hogy végy dicsőséget és tisztességet és erőt; mert te teremtettél mindent, és a te akaratodért vannak és teremttettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'És láték annak jobbkezében, a ki a királyiszékben üle, egy könyvet, a mely be volt írva belől és hátul, és le volt pecsételve hét pecséttel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'És láték egy erős angyalt, a ki nagy szóval kiálta: Ki volna méltó arra, hogy felnyissa a könyvet, és felbontsa annak pecséteit?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'És senki, sem mennyen, sem földön, sem föld alatt, nem tudta a könyvet felnyitni, sem ránézni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'Én azért igen sírok vala, hogy senki nem találtaték méltónak a könyv felnyitására és elolvasására, a ránézésre sem:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'És egy a Vének közül monda nékem: Ne sírj: ímé győzött a Júda nemzetségéből való oroszlán, Dávid gyökere, hogy felnyissa a könyvet és felbontsa annak hét pecsétét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'És láték a királyiszék és a négy lelkes állat között és a Vének között egy Bárányt állani, mint egy megölöttet, hét szarva és hét szeme vala, a mi az Istennek hét Lelke, a mely elküldetett az egész földre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'És eljöve és elvevé a könyvet a királyiszékben ülőnek jobbkezéből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'És mikor elvevé a könyvet, a négy lelkes állat és a huszonnégy Vén leborula a Bárány előtt, mindeniknél hárfák és aranypoharak lévén, jóillatokkal tele, a mik a szentek imádságai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'És éneklének új éneket, mondván: Méltó vagy, hogy elvedd a könyvet és megnyisd annak pecséteit: mert megölettél, és megváltottál minket Istennek a te véred által, minden ágazatból és nyelvből és népből és nemzetből,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'És tettél minket a mi Istenünknek királyokká és papokká; és uralkodunk a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'És látám, és hallám a királyiszék, a lelkes állatok, és a Vének körül sok angyalnak szavát; és az ő számuk tízezerszer tízezer és ezerszer ezer vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'Nagy szóval ezt mondván: Méltó a megöletett Bárány, hogy vegyen erőt és gazdagságot és bölcseséget és hatalmasságot és tisztességet és dicsőséget és áldást.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'Sőt hallám, hogy minden teremtett állat, a mely van a mennyben és a földön, és a föld alatt és a tengerben, és minden, a mi ezekben van, ezt mondja vala: A királyiszékben ülőnek és a Báránynak áldás és tisztesség és dicsőség és hatalom örökkön örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'És a négy lelkes állat monda: Ámen. És a huszonnégy Vén leborult és imádá az örökkön örökké élőt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, 'És látám, mikor a Bárány a pecsétekből egyet felnyitott, és hallám, hogy a négy lelkes állat közül egy monda, mintegy mennydörgésnek szavával: Jőjj és lásd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, 'És látám, és ímé egy fehér ló, és a rajta ülőnél íjj vala; és adaték néki korona; és kijöve győzve, és hogy győzzön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, 'És mikor a második pecsétet felnyitotta, hallám, hogy a második lelkes állat ezt mondá: Jőjj és lásd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'És előjőve egy másik, veres ló, és a ki azon üle, megadaték annak, hogy a békességet elvegye a földről, és hogy az emberek egymást öljék; és adaték annak egy nagy kard.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'És mikor felnyitotta a harmadik pecsétet, hallám, hogy a harmadik lelkes állat mondá: Jőjj és lásd. Látám azért, és ímé egy fekete ló; és annak, a ki azon üle, egy mérleg vala kezében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'És hallék a négy lelkes állat közt szózatot, a mely ezt mondja vala: A búzának mérczéje egy dénár, és az árpának három mérczéje egy dénár; de a bort és az olajt ne bántsd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'És mikor felnyitotta a negyedik pecsétet, hallám a negyedik lelkes állat szavát, a mely ezt mondja vala: Jőjj és lásd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, 'És látám, és ímé egy sárgaszínű ló; és a ki rajta üle, annak a neve halál, és a pokol követi vala azt; és adaték azoknak hatalom a földnek negyedrészén, hogy öljenek fegyverrel és éhséggel és halállal és a földnek fenevadai által.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'És mikor felnyitotta az ötödik pecsétet, látám az oltár alatt azoknak lelkeit, a kik megölettek az Istennek beszédéért és a bizonyságtételért, a melyet kaptak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'És kiáltának nagy szóval, mondván: Uram, te szent és igaz, meddig nem ítélsz még, és nem állasz bosszút a mi vérünkért azokon, a kik a földön laknak?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, 'Akkor adatának azoknak egyenként fehér ruhák; és mondaték nékik, hogy még egy kevés ideig nyugodjanak, a míg beteljesedik mind az ő szolgatársaiknak, mind az ő atyjokfiainak száma, a kiknek meg kell öletniök, a mint ők is megölettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'Azután látám, mikor a hatodik pecsétet felnyitotta, és ímé nagy földindulás lőn, és a nap feketévé lőn mint a szőrzsák, és a hold egészen olyan lőn, mint a vér;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'És az ég csillagai a földre hullának, miképen a fügefa hullatja éretlen gyümölcseit, mikor nagy szél rázza.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'És az ég eltakarodék, mint mikor a papírtekercset összegöngyölítik; és minden hegy és sziget helyéből elmozdíttaték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'És a földnek királyai és a fejedelmek és a gazdagok és a vezérek és a hatalmasak, és minden szolga és minden szabad, elrejték magokat a barlangokba és a hegyeknek kőszikláiba;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'És mondának a hegyeknek és a kőszikláknak: Essetek mi reánk és rejtsetek el minket annak színe elől, a ki a királyiszékben ül, és a Bárány haragjától:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, 'Mert eljött az ő haragjának ama nagy napja; és ki állhat meg?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 1, 'Ezek után láték négy angyalt állani a földnek négy szegletén, a földnek négy szélét tartva, hogy szél ne fújjon a földre, se a tengerre, se semmi élőfára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 2, 'És láték más angyalt feljőni napkelet felől, a kinek kezében vala az élő Istennek pecséte; és nagy szóval kiálta a négy angyalnak, a kinek adatott, hogy ártson a földnek és a tengernek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 3, 'Ezt mondván: Ne ártsatok se a földnek, se a tengernek, se a fáknak addig, míg meg nem pecsételjük a mi Istenünk szolgáit az ő homlokukon.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 4, 'És hallám a megpecsételtek számát: Száznegyvennégyezer, az Izráel fiainak minden nemzetségéből elpecsételve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 5, 'A Júda nemzetségéből tizenkétezer elpecsételt vala; a Ruben nemzetségéből tizenkétezer elpecsételt; a Gád nemzetségéből tizenkétezer elpecsételt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 6, 'Az Áser nemzetségéből tizenkétezer elpecsételt; a Nafthali nemzetségéből tizenkétezer elpecsételt; a Manassé nemzetségéből tizenkétezer elpecsételt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 7, 'A Simeon nemzetségéből tizenkétezer elpecsételt; a Lévi nemzetségéből tizenkétezer elpecsételt; az Izsakhár nemzetségéből tizenkétezer elpecsételt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 8, 'A Zebulon nemzetségéből tizenkétezer elpecsételt; a József nemzetségéből tizenkétezer elpecsételt; a Benjámin nemzetségéből tizenkétezer elpecsételt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 9, 'Azután látám, és ímé egy nagy sokaság, a melyet senki meg nem számlálhatott, minden nemzetből és ágazatból, és népből és nyelvből; és a királyiszék előtt és a Bárány előtt állnak vala, fehér ruhákba öltözve, és az ő kezeikben pálmaágak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 10, 'És kiáltanak nagy szóval, mondván: Az idvesség a mi Istenünké, a ki a királyiszékben ül, és a Bárányé!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 11, 'Az angyalok pedig mindnyájan a királyiszék, a Vének és a négy lelkes állat körül állnak vala, és a királyiszék előtt arczczal leborulának, és imádák az Istent,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 12, 'Ezt mondván: Ámen: áldás és dicsőség és bölcseség és hálaadás és tisztesség és hatalom és erő a mi Istenünknek mind örökkön örökké, Ámen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 13, 'Akkor felele egy a Vének közül, és monda nékem: Ezek, a kik a fehér ruhákba vannak öltözve, kik és honnét jöttek?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 14, 'És mondék néki: Uram, te tudod. És monda nékem: Ezek azok, a kik jöttek a nagy nyomorúságból, és megmosták az ő ruháikat, és megfehérítették ruháikat a Bárány vérében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 15, 'Ezért vannak az Isten királyiszéke előtt; és szolgálnak neki éjjel és nappal az ő templomában; és a ki a királyiszékben ül, kiterjeszti sátorát felettök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 16, 'Nem éheznek többé, sem nem szomjúhoznak többé; sem a nap nem tűz rájok, sem semmi hőség:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 17, 'Mert a Bárány, a ki a királyiszéknek közepette van, legelteti őket, és a vizeknek élő forrásaira viszi őket; és eltöröl Isten az ő szemeikről minden könyet.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 1, 'És mikor felnyitotta a hetedik pecsétet, lőn nagy csendesség a mennyben, mintegy fél óráig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 2, 'És látám azt a hét angyalt, a ki az Isten előtt álla; és adaték nékik hét trombita.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 3, 'És jöve egy másik angyal, és megálla az oltárnál, arany tömjénezőt tartva; és adaték annak sok tömjén, hogy tegye minden szenteknek könyörgéseihez az arany oltárra, a mely a királyiszék előtt vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 4, 'És felméne a tömjén füstje a szentek könyörgéseivel az angyal kezéből az Isten elébe.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 5, 'Azután vevé az angyal a tömjénezőt; és megtölté azt az oltárnak tüzével, és leveté a földre; és lőnek mennydörgések és szózatok és villámlások és földindulás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 6, 'És a hét angyal, a kinél a hét trombita vala, készüle a trombitáláshoz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 7, 'Az első angyal azért trombitála, és lőn jégeső és tűz, vérrel elegy, és vetteték a földre; és a földnek harmadrésze megége, és az élőfáknak harmadrésze megége, és minden zöldelő fű megége.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 8, 'A második angyal is trombitált, és mint egy tűzzel égő nagy hegy vetteték a tengerbe; és a tengernek harmadrésze vérré lőn;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 9, 'És meghala a tengerben lévő teremtett állatoknak harmadrésze, a melyekben élet vala; és a hajóknak harmadrésze elvesze.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 10, 'A harmadik angyal is trombitált, és leesék az égről egy nagy csillag, égve, mint egy fáklya, és esék a folyóvizeknek harmadrészére, és a vizek forrásaira;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 11, 'A csillagnak neve pedig üröm: változék azért a folyóvizek harmadrésze ürömmé; és sok ember meghala a vizektől, mivel keserűkké lőnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 12, 'A negyedik angyal is trombitált, és megvereték a napnak harmadrésze, és a holdnak harmadrésze, és a csillagoknak harmadrésze; hogy meghomályosodjék azoknak harmadrésze, és a nap az ő harmadrészében ne fényljék, és az éjszaka hasonlóképen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 13, 'És láték és hallék az égnek közepette egy angyalt repülni, a ki ezt mondja vala nagy szóval: Jaj, jaj, jaj a föld lakosainak a három angyal trombitájának többi szavai miatt, a kik még trombitálni fognak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 1, 'Az ötödik angyal is trombitált, és látám, hogy egy csillag esett le az égről a földre, és adaték annak a mélység kútjának kulcsa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 2, 'Megnyitá azért a mélységnek kútját: és füst jöve fel a kútból, mint egy nagy kemenczének füstje; és meghomályosodék a nap és a levegőég a kút füstje miatt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 3, 'A füstből pedig sáskák jövének ki a földre; és adaték azoknak hatalom, mint hatalmuk van a föld skorpióinak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 4, 'És megmondaték nékik, hogy a földnek füvét ne bántsák, se semmi zöldelőt, se semmi élőfát, hanem csak azokat az embereket, a kiknek homlokukon nincsen az Istennek pecséte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 5, 'És adaték azoknak, hogy meg ne öljék őket, hanem hogy kínoztassanak öt hónapig; és azoknak kínzása olyan, mint a skorpió kínzása, mikor megmarja az embert.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 6, 'Annakokáért azokban a napokban keresik az emberek a halált, de nem találják meg azt; és kívánnának meghalni, de a halál elmegy előlük.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 7, 'A sáskáknak formája pedig hasonló vala a viadalhoz felkészített lovakhoz; és a fejökön mintegy aranyhoz hasonló koronák valának, és az orczáik olyanok valának, mint az emberek orczái.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 8, 'És olyan hajuk vala, mint az asszonyok haja; és fogaik olyanok valának, mint az oroszlánoknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 9, 'És olyan mellvértjeik valának, mint a vas mellvértek; és az ő szárnyaik zúgása olyan vala, mint a viadalra száguldó sok lovas szekerek zúgása.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 10, 'És skorpiókhoz hasonló farkuk vala és fulánkjuk; és a farkukban vala a hatalmuk, hogy ártsanak az embereknek öt hónapig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 11, 'Királyukul pedig a mélység angyala vala felettök; annak a neve zsidóul Abaddon, görögül pedig Apollion, azaz Vesztő a neve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 12, 'Az első jaj elmúlék; ímé ezután még két jaj következik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 13, 'A hatodik angyal is trombitált, és hallék egy szózatot az arany oltárnak négy szarvától, a mely az Isten előtt van,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 14, 'Mondván a hatodik angyalnak, a kinél a trombita vala: Oldd el azt a négy angyalt, a ki a nagy folyóvíznél, az Eufrátesnél van megkötve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 15, 'Eloldaték azért a négy angyal, a ki el vala készítve az órára és napra és hónapra és esztendőre, hogy megölje az emberek harmadrészét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 16, 'És a lovas seregek száma két tízezerszer tízezer vala; hallottam a számukat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 17, 'És így látám a lovakat látásban, és a rajtuk ülőket, a kiknek tűzből és jáczintból és kénkőből való mellvértjeik valának; és a lovak feje olyan vala, mint az oroszlánok feje; és szájukból tűz és füst és kénkő jő vala ki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 18, 'E háromtól öleték meg az emberek harmadrésze, a tűztől és a füsttől és a kénkőtől, a mely azoknak szájából jő vala ki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 19, 'Mert az ő hatalmuk az ő szájukban van, és az ő farkukban; mert az ő farkaik a kígyókhoz hasonlók, a melyeknek fejeik vannak; és azokkal ártanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 20, 'A többi emberek pedig, a kik meg nem ölettek e csapásokkal, nem tértek meg az ő kezeik csinálmányaitól, hogy ne imádnák a gonosz lelkeket, és az arany és ezüst és ércz és kő és fa bálványokat, a melyek nem láthatnak, sem hallhatnak, sem járhatnak;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 21, 'És nem tértek meg az ő gyilkosságaikból, sem az ő ördöngösségeikből, sem paráználkodásaikból, sem lopásaikból.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 1, 'És láték egy másik, erős angyalt az égből leszállani, a ki felhőbe vala öltözve; és a fején szivárvány vala, és az orczája olyan vala, mint a nap, és a lábai mint a tűzoszlopok;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 2, 'És a kezében egy nyitott könyvecske vala; és tevé a jobb lábát a tengerre, a bal lábát pedig a földre;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 3, 'És kiálta nagy szóval, mint mikor az oroszlán ordít; és mikor kiálta, megszólaltatá a hét mennydörgés az ő szavát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 4, 'És mikor a hét mennydörgés megszólaltatta az ő szavát, le akarám írni; és az égből szózatot hallék, a mely ezt mondá nékem: Pecsételd be, a miket a hét mennydörgés szóla, és azokat meg ne írd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 5, 'És az angyal, a kit láték állani a tengeren és a földön, felemelé kezét az égre,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 6, 'És megesküvék arra, a ki örökkön örökké él, a ki teremtette az eget és a benne valókat, és a földet és a benne valókat, és a tengert és a benne valókat, hogy idő többé nem lészen:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 7, 'Hanem a hetedik angyal szavának napjaiban, mikor trombitálni kezd, akkor elvégeztetik az Istennek titka, a mint megmondotta az ő szolgáinak a prófétáknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 8, 'És a szózat, a melyet hallottam az égből, ismét szóla nékem, és monda: Menj el, és vedd el azt a nyitott könyvecskét, mely a tengeren és a földön álló angyal kezében van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 9, 'Elmenék azért az angyalhoz, mondván néki: Add nékem a könyvecskét. És monda nékem: Vedd el és edd meg; és megkeseríti a te gyomrodat, de a te szádban édes lesz, mint a méz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 10, 'Elvevém azért a könyvecskét az angyal kezéből, és megevém azt; és az én számban olyan édes vala mint a méz; és mikor megettem azt, megkeseredék az én gyomrom.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 11, 'És monda nékem: Ismét prófétálnod kell néked sok népek és nemzetek, és nyelvek és királyok felől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 1, 'És adának nékem vesszőhöz hasonló nádszálat, és angyal áll vala mellém és monda: Kelj fel, és mérd meg az Isten templomát és az oltárt, és azokat, a kik abban imádkoznak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 2, 'De a tornáczot, a mely a templomon kívül van, kihagyd, és azt meg ne mérd; mert a pogányoknak adatott, és a szent várost tapodják negyvenkét hónapig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 3, 'És adom az én két tanúbizonyságomnak, hogy prófétáljanak, gyászruhákba öltözve, ezer kétszáz hatvan napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 4, 'Ezek az a két olajfa, és a két gyertyatartó, a melyek a földnek Istene előtt állanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 5, 'És ha valaki akar nékik ártani, tűz származik az ő szájokból, a mely megöli az ő ellenségeiket; és ha valaki akar nékik ártani, úgy kell annak megöletni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 6, 'Ezeknek van hatalmuk arra, hogy bezárják az eget, hogy az ő prófétálásuknak idejében eső ne legyen; és hatalmuk van a vizeken, hogy azokat vérré változtassák, és megverjék a földet akármi csapással, valamennyiszer akarják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 7, 'És mikor elvégezik az ő bizonyságtételöket, a mélységből feljövő fenevad hadakozik ellenök, és legyőzi őket, és megöli őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 8, 'És az ő holttesteik feküsznek ama nagy városnak utczáin, a mely lélek szerint Sodomának és Égyiptomnak hivatik, a hol a mi Urunk is megfeszíttetett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 9, 'És a népek és ágazatok, és nyelvek és nemzetek közül valók látják azoknak holttestét három és fél nap, és azoknak holttestét nem engedik sírba tenni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 10, 'És a földnek lakosai örülnek és örvendeznek rajtok, és ajándékokat küldenek egymásnak; mivelhogy e két próféta gyötörte a földnek lakosait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 11, 'De három és fél nap mulva életnek lelke adaték Istentől ő beléjök, és lábaikra állának; és nagy félelem esék azokra, a kik őket nézik vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 12, 'És hallának nagy szózatot az égből, a mely ezt mondja vala nékik: Jőjjetek fel ide. És felmenének az égbe felhőben; és láták őket az ő ellenségeik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 13, 'És lőn abban az órában nagy földindulás, és a városnak tizedrésze elesék; és megöleték a földindulásban hétezer ember neve; és a többiek megrémülének, és a menny Istenének adának dicsőséget.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 14, 'A második jaj elmúlt; ímé a harmadik jaj hamar eljő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 15, 'A hetedik angyal is trombitála, és nagy szózatok lőnek a mennyben, a melyek ezt mondják vala: E világnak országai a mi Urunkéi és az ő Krisztusáéi lettek, a ki örökkön örökké uralkodik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 16, 'És a huszonnégy Vén, a ki az Isten előtt ül az ő királyiszékeiben, esék az ő orczájára és imádá az Istent,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 17, 'Ezt mondván: Hálát adunk néked Uram, mindenható Isten, a ki vagy és a ki valál és a ki eljövendő vagy; mert a te nagy hatalmadat kezedhez vetted, és a te országlásodat elkezdetted.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 18, 'És megharagudtak a pogányok, és eljött a te haragod, és a halottak ideje, hogy megítéltessenek, és jutalmat adj a te szolgáidnak, a prófétáknak és a szenteknek, és a kik a te nevedet félik, kicsinyeknek és nagyoknak; és elpusztítsd azokat, a kik a földet pusztítják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 19, 'És megnyilatkozék az Isten temploma a mennyben, és megláttaték az ő szövetségének ládája az ő templomában; és lőnek villámlások és szózatok és mennydörgések, és földindulás és nagy jégeső.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 1, 'És láttaték nagy jel az égben: egy asszony, a ki a napba vala felöltözve, és lábai alatt vala a hold, és az ő fejében tizenkét csillagból korona;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 2, 'A ki terhes vala, és akarván szűlni, kiált vala, és kínlódik vala a szűlésben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 3, 'Láttaték más jel is az égben, és ímé vala egy nagy veres sárkány, a kinek hét feje vala és tíz szarva, és az ő fejeiben hét korona;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 4, 'És a farka utána vonszá az ég csillagainak harmadrészét, és a földre veté azokat; és álla az a sárkány a szűlő asszony elé, hogy mikor szűl, annak fiát megegye.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 5, 'És szűle fiú-magzatot, a ki vasvesszővel legeltet minden nemzetet; és ragadtaték annak fia Istenhez és az ő királyiszékéhez.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 6, 'Az asszony pedig elfuta a pusztába, hol Istentől készített helye van, hogy ott táplálják őt ezer kétszáz hatvan napig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 7, 'És lőn az égben viaskodás: Mihály és az ő angyalai viaskodnak vala a sárkánynyal; és a sárkány is viaskodik vala és az ő angyalai;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 8, 'De nem vehetének diadalmat, és az ő helyök sem találtaték többé a mennyben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 9, 'És vetteték a nagy sárkány, ama régi kígyó, a ki neveztetik ördögnek és a Sátánnak, ki mind az egész föld kerekségét elhiteti, vetteték a földre, és az ő angyalai is ő vele levettetének.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 10, 'És hallék nagy szózatot az égben, a mely ezt mondja vala: Most lett meg az idvesség és az erő, és a mi Istenünknek országa, és az ő Krisztusának hatalma; mert a mi atyánkfiainak vádolója levettetett, ki vádolja vala őket éjjel és nappal a mi Istenünk előtt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 11, 'És ők legyőzték azt a Bárány véréért, és az ő bizonyságtételöknek beszédéért; és az ő életöket nem kímélték mind halálig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 12, 'Annakokáért örüljetek egek és a kik lakoztok azokban. Jaj a föld és a tenger lakosainak; mert leszállott az ördög ti hozzátok, nagy haraggal teljes, úgymint a ki tudja, hogy kevés ideje van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 13, 'Mikor azért látta a sárkány, hogy ő levettetett a földre, kergetni kezdé az asszonyt, a ki a fiút szűlte.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 14, 'De adaték az asszonynak két nagy sasszárny, hogy a kígyó elől elrepüljön a pusztába az ő helyére, hogy tápláltassék ott ideig, időkig, és az időnek feléig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 15, 'És bocsáta a kígyó az ő szájából az asszony után vizet, mint egy folyó vizet, hogy azt a folyóvízzel elragadtassa.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 16, 'De segítségül lőn a föld az asszonynak, és megnyitá a föld az ő száját, és elnyelé a folyóvizet, a melyet a sárkány az ő szájából bocsátott.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 17, 'Megharagvék azért a sárkány az asszonyra, és elméne, hogy hadakozzék egyebekkel az ő magvából valókkal, az Isten parancsolatainak megőrzőivel, és a kiknél vala a Jézus Krisztus bizonyságtétele;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 18, 'És álla a tengernek fövenyére.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 1, 'És láték egy fenevadat feljőni a tengerből, a melynek hét feje és tíz szarva vala, és az ő szarvain tíz korona, és az ő fejein a káromlásnak neve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 2, 'És e fenevad, a melyet láték, hasonló vala a párduczhoz, és az ő lábai, mint a medvéé, és az ő szája, mint az oroszlán szája; és a sárkány adá az ő erejét annak, és az ő királyiszékét, és nagy hatalmat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 3, 'És látám, hogy egy az ő fejei közül mintegy halálos sebbel megsebesíttetett; de az ő halálos sebe meggyógyíttaték; és csodálván, az egész föld követé a fenevadat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 4, 'És imádák a sárkányt, a ki a hatalmat adta a fenevadnak; és imádák a fenevadat, ezt mondván: Kicsoda hasonló e fenevadhoz? kicsoda viaskodhatik ő vele?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 5, 'És adaték néki nagy dolgoknak és káromlásoknak szóló szája; és adaték néki hatalom, hogy cselekedjék negyvenkét hónapig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 6, 'Megnyitá azért az ő száját Isten ellen való káromlásra, hogy szidalmazza az ő nevét és az ő sátorát, és azokat, a kik a mennyben laknak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 7, 'Az is adaték néki, hogy a szentek ellen hadakozzék, és őket legyőzze; és adaték néki hatalom minden nemzetségen, nyelven és népen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 8, 'Annakokáért imádják őt a földnek minden lakosai, a kiknek neve nincs beírva az életnek könyvébe, a mely a Bárányé, a ki megöletett, e világ alapítása óta.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 9, 'Ha van füle valakinek, hallja!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 10, 'Ha valaki fogságba visz mást, ő is fogságba megy; ha valaki fegyverrel öl, fegyverrel kell annak megöletni. Itt van a szentek békességes tűrése és hite.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 11, 'Azután láték más fenevadat feljőni a földből, a kinek két szarva vala, a Bárányéhoz hasonló, de úgy szól vala, mint a sárkány;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 12, 'És az előbbi fenevadnak minden hatalmasságát cselekszi ő előtte; és azt is cselekszi, hogy a föld és annak lakosai imádják az első fenevadat, a melynek halálos sebe meggyógyult vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 13, 'És nagy jeleket tesz, annyira, hogy tüzet is hoz alá az égből a földre, az emberek láttára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 14, 'És elhiteti a földnek lakosait a jelekkel, a melyek adatának néki, hogy cselekedje a fenevad előtt; azt mondván a föld lakosainak, hogy csinálják meg a fenevadnak képét, a ki fegyverrel megsebesíttetett vala, de megelevenedett.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 15, 'És adaték néki, hogy a fenevad képébe lelket adjon, hogy a fenevad képe szóljon is, és azt mívelje, hogy mindazok, a kik nem imádják a fenevad képét, megölessenek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 16, 'Azt is teszi mindenkivel, kicsinyekkel és nagyokkal, gazdagokkal és szegényekkel, szabadokkal és szolgákkal, hogy az ő jobb kezökre vagy a homlokukra bélyeget tegyenek;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 17, 'És hogy senki se vehessen, se el ne adhasson semmit, hanem csak a kin a fenevad bélyege van, vagy neve, vagy nevének száma.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 18, 'Itt van a bölcseség. A kinek értelme van, számlálja meg a fenevad számát; mert emberi szám: és annak száma hatszázhatvanhat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 1, 'És látám, és ímé egy Bárány áll vala Sion hegyén, és ő vele száznegyvennégy ezeren, a kiknek homlokán írva vala az ő Atyjának neve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 2, 'És hallék szózatot az égből, mint sok vizeknek zúgását és mint nagy mennydörgésnek szavát; és hallám hárfásoknak szavát, a kik az ő hárfájokkal hárfáznak vala;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 3, 'És énekelnek vala mintegy új éneket a királyiszék előtt, és a négy lelkes állat előtt és a Vének előtt; és senki meg nem tanulhatja vala azt az éneket, csak a száz negyvennégy ezer, a kik áron vétettek meg a földről.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 4, 'Ezek azok, a kik asszonyokkal nem fertőztették meg magokat; mert szűzek. Ezek azok, a kik követik a Bárányt, valahová megy. Ezek áron vétettek meg az emberek közül Istennek és a Báránynak zsengéiül.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 5, 'És az ő szájokban nem találtatott álnokság; mert az Istennek királyiszéke előtt feddhetetlenek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 6, 'És láték más angyalt az ég közepén repülni, a kinél vala az örökkévaló evangyéliom, hogy a föld lakosainak hirdesse az evangyéliomot, és minden nemzetségnek és ágazatnak, és nyelvnek és népnek,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 7, 'Ezt mondván nagy szóval: Féljétek az Istent, és néki adjatok dicsőséget: mert eljött az ő ítéletének órája; és imádjátok azt, a ki teremtette a mennyet és a földet, és a tengert és a vizek forrásait.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 8, 'És más angyal követé azt, mondván: Leomlott, leomlott Babilon, a nagy város! mert az ő paráznaságának haragborából adott inni minden pogány népnek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 9, 'És harmadik angyal is követé azokat, mondván nagy szóval: Ha valaki imádja a fenevadat és annak képét, és bélyegét felveszi vagy homlokára vagy kezére,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 10, 'Az is iszik az Isten haragjának borából, a mely elegyítetlenül töltetett az ő haragjának poharába: és kínoztatik tűzzel és kénkővel a szent angyalok előtt és a Bárány előtt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 11, 'És az ő kínlódásuknak füstje felmegy örökkön örökké; és nem lesz nyugalmuk éjjel és nappal, a kik imádják a fenevadat és annak képét, és ha valaki az ő nevének bélyegét felveszi.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 12, 'Itt van a szenteknek békességes tűrése, itt a kik megtartják az Isten parancsolatait és a Jézus hitét!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 13, 'És hallék az égből szózatot, a mely ezt mondja vala nékem: Írd meg: Boldogok a halottak, a kik az Úrban halnak meg mostantól fogva. Bizony, azt mondja a Lélek, mert megnyugosznak az ő fáradságuktól, és az ő cselekedeteik követik őket.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 14, 'És látám, és ímé vala egy fehér felhő; és a felhőn üle valaki, hasonló az embernek Fiához, a fején arany korona, és a kezében éles sarló.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 15, 'És más angyal jöve ki a templomból, nagy szóval kiáltván annak, a ki a felhőn ül vala: Indítsd a sarlódat és arass; mert a földnek aratni valója megszáradt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 16, 'Bocsátá azért, a ki a felhőn ül vala az ő sarlóját a földre; és learattaték a föld.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 17, 'És más angyal jöve ki a mennyben való templomból, s annál is éles sarló vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 18, 'Más angyal is jöve ki az oltártól, a kinek hatalma vala a tűzön, és kiálta nagy szóval annak, a kinél vala az éles sarló, ezt mondván: Bocsásd a te éles sarlódat, és szedd meg a föld szőleinek gerézdeit; mert megértek annak szőlei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 19, 'Bocsátá azért az angyal az ő éles sarlóját a földre, és a földnek szőleit megszedé, és veté az Isten haragjának nagy borsajtójába.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 20, 'És megtaposták a borsajtót a városon kívül, és vér jöve ki a borsajtóból a lovak zablájáig, ezer hatszáz futamatnyira.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 1, 'És láték mennyben más nagy és csodálatos jelt: hét angyalt, a kinél vala a hét utolsó csapás; mert az által teljesedett be az Istennek haragja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 2, 'És láték úgymint üvegtengert tűzzel elegyítve; és azokat, a kik diadalmasok a fenevadon és az ő képén, és bélyegén és az ő nevének számán, látám állani az üvegtenger mellett, a kiknek kezében valának az Istennek hárfái.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 3, 'És énekelik vala Mózesnek az Isten szolgájának énekét, és a Báránynak énekét, ezt mondván: Nagyok és csodálatosak a te dolgaid, mindenható Úr Isten; igazságosak és igazak a te útaid, óh szentek Királya!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 4, 'Ki ne félne téged, Uram! és ki ne dicsőítené a te nevedet? mert csak egyedül vagy szent. Mert eljőnek mind a pogányok és lehajolnak előtted; mert a te ítéleteid nyilvánvalókká lettek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 5, 'És ezeknek utána látám, és ímé megnyittaték a mennyben a bizonyságtétel sátorának temploma,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 6, 'És kijöve a templomból a hét angyal, a kinél a hét csapás vala, tiszta és fehér gyolcsba öltözve, és mellöknél arany övekkel körülövezve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 7, 'És egy a négy lelkes állat közül ada a hét angyalnak hét aranypoharat, a mely az örökkön örökké élő Istennek haragjával teljes vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 8, 'És megtelék a templom füsttel az Isten dicsőségének és erejének miatta, és senki a templomba be nem mehet vala, mígnem a hét angyal hét csapása bevégeztetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 1, 'És hallék nagy szózatot a templomból, a mely mondja vala a hét angyalnak: Menjetek el és töltsétek ki a földre az Isten haragjának hét poharát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 2, 'Elméne azért az első, és kitölté az ő poharát a földre; és támada gonosz és ártalmas fekély azokon az embereken, a kiken vala a fenevad bélyege, és a kik imádják vala annak képét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 3, 'A másik angyal is kitölté az ő poharát a tengerbe; és olyanná lőn, mint a halott vére; és minden élő állat meghala a tengerben.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 4, 'A harmadik angyal is kitölté az ő poharát a folyóvizekbe és a vizek forrásaiba; és lőn vér.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 5, 'És hallám, hogy a vizek angyala ezt mondja vala: Igaz vagy Uram, a ki vagy és a ki valál, te Szent, hogy ezeket ítélted;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 6, 'Mivelhogy szentek és próféták vérét ontották, vért adál nékik inni; mert méltók arra.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 7, 'És hallám, hogy más az oltárról ezt mondja vala: Jól van Uram, mindenható Isten, igazak és igazságosak a te ítéleteid.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 8, 'A negyedik angyal is kitölté az ő poharát a napra; és adaték annak, hogy az embereket tikkaszsza tűzzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 9, 'És tikkadának az emberek nagy hévséggel; és az Istennek nevét káromlák, a kinek hatalma vala e csapásokon; és nem térének meg, hogy neki dicsőséget adjanak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 10, 'Az ötödik angyal is kitölté az ő poharát a fenevad királyiszékére; és lőn az ő országa setét; és rágják vala az ő nyelvöket a kín miatt,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 11, 'És káromlák a menny Istenét az ő kínjaik és fekélyeik miatt; és meg nem térének az ő cselekedeteikből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 12, 'A hatodik angyal is kitölté az ő poharát a nagy folyóvízre, az Eufrátesre; és kiszárada annak vize, hogy a napkelet felől jövő királyoknak út készíttessék.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 13, 'És láték a sárkány szájából és a fenevad szájából és a hamis próféta szájából három tisztátalan lelket kijőni, a békákhoz hasonlókat;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 14, 'Mert ördögi lelkek azok, a kik jeleket tesznek; a kik elmennek a földnek és az egész világnak királyaihoz, hogy egybe gyűjtsék azokat a mindenható Isten ama nagy napjának viadalára.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 15, '(Imé eljövök, mint a tolvaj. Boldog, a ki vigyáz és őrzi az ő ruháit, hogy mezítelenen ne járjon, és meg ne lássák az ő rútságát.)');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 16, 'Egybegyűjték azért őket a helyre, a melyet zsidóul Armageddonnak neveznek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 17, 'A hetedik angyal is kitölté az ő poharát a levegőégre; és nagy szózat jöve ki a mennyei templomból a királyiszéktől, a mely ezt mondja vala: Meglett!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 18, 'És lőnek zendülések és mennydörgések és villámlások; és lőn nagy földindulás, a milyen nem volt, mióta az emberek a földön vannak, ilyen földindulás, ilyen nagy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 19, 'És a nagy város három részre szakada, és a pogányok városai elesének; és a nagy Babilon megemlítteték az Isten előtt, hogy adjon annak inni az ő búsult haragja borának poharából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 20, 'És minden sziget elmúlék, és hegyek nem találtatának többé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 21, 'És nagy jégeső, mint egy-egy tálentom, szálla az égből az emberekre; és káromlák az Istent az emberek a jégeső csapásáért; mert annak csapása felette nagy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 1, 'És jöve egy a hét angyal közül, a kinél a hét pohár vala, és szóla velem, mondván nékem: Jövel, és megmutatom néked a nagy paráznának kárhoztatását, a ki a sok vizen ül;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 2, 'A kivel paráználkodtak a föld királyai, és az ő paráznaságának borával megrészegedtek a föld lakosai.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 3, 'És lélekben elvitt engem egy pusztába és láték egy asszonyt ülni egy veres fenevadon, a mely teljes vala káromlásnak neveivel, a melynek hét feje és tíz szarva vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 4, 'Öltözött vala pedig az asszony bíborba és skárlátba, és megékesíttetett vala aranynyal és drágakővel és gyöngyökkel, kezében egy aranypohár vala, tele útálatosságokkal és az ő paráznaságának tisztátalanságával,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 5, 'És az ő homlokára egy név vala írva: Titok; a nagy Babilon, a paráznáknak és a föld útálatosságainak anyja.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 6, 'És látám, hogy az asszony részeg vala a szentek vérétől és a Jézus bizonyságtevőinek vérétől; és nagy csodálkozással csodálkozám, mikor látám őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 7, 'És monda nékem az angyal: Miért csodálkozol? Én megmondom néked ez asszonynak titkát és a fenevadét, a mely őt hordozza, a melynek hét feje és tíz szarva van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 8, 'A fenevad, a melyet láttál, volt és nincs; és a mélységből jő fel és megy a veszedelemre. És a föld lakosai csodálkoznak (a kiknek neve nincs beírva az életnek könyvébe e világ alapítása óta) látván a fenevadat, a mely vala és nincs, noha van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 9, 'Itt az elme, a melyben van bölcseség. A hét fő a hét hegy, a melyen az asszony ül;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 10, 'Király is hét van; az öte elesett, és az egyik van, a másik még el nem jött; és mikor eljő, kevés ideig kell annak megmaradni.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 11, 'A fenevad pedig, a mely vala és nincs, az maga a nyolczadik, és a hét közül való; és a veszedelemre megy.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 12, 'A tíz szarv pedig, a melyet láttál, tíz király, olyanok, a kik még birodalmat nem kaptak; de hatalmat kapnak mint királyok egy óráig a fenevaddal.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 13, 'Ezeknek egy a szándékuk; erejöket és hatalmokat is a fenevadnak adják.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 14, 'Ezek a Bárány ellen viaskodnak, és a Bárány meggyőzi őket, mert uraknak Ura és királyoknak Királya; és az ő vele való hivatalosok és választottak és hívek is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 15, 'És monda nékem: A vizek, a melyeket láttál, a hol a parázna ül, népek azok és sokaságok és nemzetek és nyelvek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 16, 'És a tíz szarv, a melyet láttál a fenevadon, ezek meggyűlölik a paráznát, és kifosztják és mezítelenné teszik, és eszik annak húsát, és megégetik őt tűzzel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 17, 'Mert az Isten adta azoknak szívébe, hogy az ő szándékát cselekedjék, és egy szándékon legyenek, és adják az ő birodalmukat a fenevadnak, míglen betelnek az Isten beszédei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 18, 'És az asszony, a melyet láttál, ama nagy város, a melynek királysága van a földnek királyain.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 1, 'És ezek után láték más angyalt leszállani a mennyből, a kinek nagy hatalma vala; és a föld fénylett annak dicsőségétől.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 2, 'És kiálta teljes erejéből, nagy szóval mondván: Leomlott, leomlott a nagy Babilon, és lett ördögöknek lakhelyévé, minden tisztátalan léleknek tömlöczévé, és minden tisztátalan és gyűlölséges madárnak tömlöczévé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 3, 'Mert az ő paráznasága haragjának borából ivott valamennyi nép, és a földnek királyai ő vele paráználkodtak, és a földnek kalmárai az ő dobzódásának erejéből meggazdagodtak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 4, 'És hallék más szózatot a mennyből, a mely ezt mondja vala: Fussatok ki belőle én népem, hogy ne legyetek részesek az ő bűneiben, és ne kapjatok az ő csapásaiból:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 5, 'Mert az ő bűnei az égig hatottak, és megemlékezett az Isten az ő gonoszságairól.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 6, 'Fizessetek úgy néki, a mint ő fizetett néktek, és kétszerrel kettőztessétek meg néki az ő cselekedetei szerint; a mely pohárból itatott, ugyanabból két annyit töltsetek néki.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 7, 'A mennyire dicsőítette magát és dobzódott, annyi kínnal és gyászszal fizessetek néki; mert ezt mondja az ő szívében: Úgy ülök, mint királynéasszony, és nem vagyok özvegy, és semmi gyászt nem látok.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 8, 'Ennekokáért egy nap jőnek ő reá az ő csapásai: a halál, a gyász és az éhség; és tűzzel égettetik meg; mert erős az Úr, az Isten, a ki megbünteti őt.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 9, 'És siratják őt, és jajgatnak ő rajta a föld királyai, a kik vele paráználkodtak és dobzódtak, mikor az ő égésének füstjét látják,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 10, 'Nagy távol állva az ő kínjától való félelem miatt, mondván: Jaj! jaj! te nagy város, Babilon, te hatalmas város, hogy egy órában jött el ítéleted!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 11, 'A föld kalmárai is siratják és jajgatják őt, mert az ő árúikat immár senki nem veszi;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 12, 'Arany és ezüst, és drágakő és gyöngy, és gyolcs és bíbor, és selyem és skárlátczikkeket; és minden thinfát és minden elefántcsontedényt, és drágafából és rézből és vasból és márványkőből csinált minden edényt;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 13, 'És fahajat és illatszereket, és kenetet és tömjént, és bort és olajat, és zsemlyelisztet és gabonát, és barmokat és juhokat, és lovakat és kocsikat, és rabokat és emberek lelkeit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 14, 'És a gyümölcs, a mit a te lelked kívánt, eltávozott tőled, és minden a mi ínyes és pompás, eltávozott tőled, és többé azokat meg nem találod.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 15, 'Ezeknek árosai, a kik meggazdagodtak ő tőle, távol állanak az ő kínjától való félelem miatt, sírván és jajgatván,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 16, 'És ezt mondván: Jaj! jaj! a nagy város, a mely öltözött gyolcsba és bíborba és skarlátba, és megékesíttetett aranynyal, drágakövekkel és gyöngyökkel; hogy elpusztult egy órában annyi gazdagság!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 17, 'És minden hajósmester és a hajókon levők mind, a sokaság és az evezők, és valakik a tengeren kereskednek, távol állának.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 18, 'És kiáltának, látván az ő égésének füstjét, és ezt mondják vala: Mi hasonló e nagy városhoz?');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 19, 'És port hányván az ő fejökre, kiáltának sírván és jajgatván, és ezt mondván: Jaj! jaj! az a nagy város, a melyben meggazdagodott mindenki, a kinek hajói voltak a tengeren, annak drágaságaiból, hogy elpusztult egy órában!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 20, 'Örülj ő rajta menny, és ti szent apostolok és próféták; mert az Isten büntette meg őt érettetek való büntetéssel.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 21, 'És egy erős angyal egy nagy malomkőhöz hasonló követ felvőn és a tengerbe veté, ezt mondván: Ilyen módon nagy sebességgel vettetik el Babilon, ama nagy város, és többé meg nem találtatik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 22, 'És hárfásoknak és muzsikásoknak, és síposoknak és trombitásoknak szava te benned többé nem hallatik; és semmi mesterségnek mestere nem találtatik többé te benned; és malomnak zúgása sem hallatik többé te benned;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 23, 'És szövétneknek világossága többé te benned nem fénylik; és vőlegénynek és menyasszonynak szava sem hallatik többé te benned; mert a te kalmáraid valának a földnek fejedelmei; mert a te bűvöléseidtől eltévelyedtek mind a népek.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 24, 'És abban prófétáknak és szenteknek vére találtatott, és mindeneknek, a kik megölettek a földön.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 1, 'És ezek után hallám mintegy nagy sokaságnak nagy szavát az égben, a mely ezt mondja vala: Aleluja! az idvesség és a dicsőség, és a tisztesség és a hatalom az Úré, a mi Istenünké!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 2, 'Mert igazak és igazságosak az ő ítéletei, és azt a nagy paráznát, a mely a földet megrontotta az ő paráznaságával, elítélte, és megbosszúlta az ő szolgáinak vérét annak kezén.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 3, 'És másodszor is mondának: Aleluja! és: Annak füstje felmegy örökkön örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 4, 'És leborula a huszonnégy Vén és a négy lelkes állat, és imádá az Istent, a ki a királyiszékben ül vala, mondván: Ámen! Aleluja!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 5, 'És a királyiszéktől szózat jöve ki, a mely ezt mondja vala: Dícsérjétek a mi Istenünket mindnyájan ő szolgái, a kik félitek őt, kicsinyek és nagyok!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 6, 'És hallám mintegy nagy sokaság szavát, és mintegy sok vizek zúgását, és mintegy erős mennydörgések szavát, mondván: Aleluja! mert uralkodik az Úr, a mi Istenünk, a mindenható.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 7, 'Örüljünk és örvendezzünk, és adjunk dicsőséget néki, mert eljött a Bárány menyegzője, és az ő felesége elkészítette magát,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 8, 'És adatott annak, hogy felöltözzék tiszta és ragyogó fehér gyolcsba; mert a fehér gyolcs a szenteknek igazságos cselekedetei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 9, 'És monda nékem: Írd meg: Boldogok azok, a kik a Bárány menyegzőjének vacsorájára hivatalosak. És monda nékem: Ezek az Istennek igaz beszédei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 10, 'És leborulék annak lábai előtt, hogy imádjam őt, de monda nékem: Meglásd, ne tedd; szolgatársad vagyok néked és a te atyádfiainak, a kiknél a Jézus bizonyságtétele van; Istent imádd, mert a Jézus bizonyságtétele a prófétaság lelke.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 11, 'És látám, hogy az ég megnyílt, és ímé vala egy fehér ló, és a ki azon ül vala, hivatik vala Hívnek és Igaznak, és igazságosan ítél és hadakozik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 12, 'És az ő szemei olyanok, mint a tűzláng; és az ő fején sok korona; az ő neve fel vala írva, a mit senki nem tud, csak ő maga.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 13, 'És vérrel hintett ruhába vala öltöztetve és a neve Isten ígéjének neveztetik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 14, 'És mennyei seregek követik vala őt fehér lovakon, fehér és tiszta gyolcsba öltözve.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 15, 'És az ő szájából éles kard jő vala ki, hogy azzal verje a pogányokat; és ő fogja azokat legeltetni vasvesszővel; és ő nyomja a mindenható Isten haragja hevének borsajtóját.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 16, 'És az ő ruháján és tomporán oda vala írva az ő neve: királyoknak Királya, és uraknak Ura.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 17, 'És láték egy angyalt állani a napban, és kiálta nagy szóval, mondván minden madaraknak, a melyek repdesnek vala az égnek közepette: Jőjjetek el, és gyűljetek egybe a nagy Istennek vacsorájára;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 18, 'Hogy egyétek a királyok húsát, és vezérek húsát és hatalmasok húsát, és lovaknak és rajtok űlőknek húsát, és mindenkinek húsát, szabadokét és szolgákét, és kicsinyekét és nagyokét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 19, 'És látám, hogy a fenevad és a föld királyai és az ő seregeik egybegyűltek, hogy hadakozzanak az ellen, a ki a lovon ül vala és az ő serege ellen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 20, 'És megfogaték a fenevad, és ő vele együtt a hamis próféta, a ki a csodákat tette ő előtte, a melyekkel elhitette azokat, a kik a fenevad bélyegét felvették, és a kik imádták annak képét: ők ketten elevenen a kénkővel égő tüzes tóba vettetének:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 21, 'A többiek pedig megöletének a lovon űlőnek kardjával, a mely az ő szájából jő vala ki; és a madarak mind megelégedének azoknak húsával.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 1, 'És láték egy angyalt leszállani a mennyből, a kinél vala a mélységnek kulcsa, és egy nagy láncz a kezében.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 2, 'És megfogá a sárkányt, azt a régi kígyót, a ki az ördög és Sátán, és megkötözé azt ezer esztendőre,');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 3, 'És veté őt a mélységbe, és bezárá azt és bepecsételé ő felette, hogy többé el ne hitesse a népeket, míg betelik az ezer esztendő; azután el kell néki oldoztatni egy kevés időre.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 4, 'És láték királyiszékeket, és leülének azokra, és adaték nékik ítélettétel; és látám azoknak lelkeit, a kiknek fejöket vették a Jézus bizonyságtételéért és az Isten beszédéért, és a kik nem imádták a fenevadat, sem annak képét, és nem vették annak bélyegét homlokukra és kezeikre; és éltek és uralkodtak a Krisztussal ezer esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 5, 'A többi halottak pedig meg nem elevenedének, mígnem betelik az ezer esztendő. Ez az első feltámadás.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 6, 'Boldog és szent, a kinek része van az első feltámadásban: ezeken nincs hatalma a második halálnak; hanem lesznek az Istennek és a Krisztusnak papjai, és uralkodnak ő vele ezer esztendeig.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 7, 'És mikor eltelik az ezer esztendő, a Sátán eloldatik az ő fogságából.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 8, 'És kimegy, hogy elhitesse a föld négy szegletén lévő népeket, a Gógot és a Magógot, hogy egybegyűjtse őket háborúra, a kiknek száma, mint a tenger fövenye.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 9, 'És feljövének a föld szélességére, és körülvevék a szentek táborát és a szeretett várost; és Istentől a mennyből tűz szálla alá, és megemészté azokat.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 10, 'És az ördög, a ki elhitette őket, vetteték a tűz és kénkő tavába, a hol van a fenevad és a hamis próféta; és kínoztatnak éjjel és nappal örökkön örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 11, 'És láték egy nagy fehér királyiszéket, és a rajta űlőt, a kinek tekintete elől eltűnék a föld és az ég, és helyök nem találtaték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 12, 'És látám a halottakat, nagyokat és kicsinyeket, állani az Isten előtt; és könyvek nyittatának meg, majd egy más könyv nyittaték meg, a mely az életnek könyve; és megítéltetének a halottak azokból, a mik a könyvekbe voltak írva, az ő cselekedeteik szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 13, 'És a tenger kiadá a halottakat, a kik ő benne voltak; és a halál és a pokol is kiadá a halottakat, a kik ő nálok voltak; és megítéltetének mindnyájan az ő cselekedeteik szerint.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 14, 'A pokol pedig és a halál vettetének a tűznek tavába. Ez a második halál, a tűznek tava.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 15, 'És ha valaki nem találtatott beírva az élet könyvében, a tűznek tavába vetteték.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 1, 'Ezután láték új eget és új földet; mert az első ég és az első föld elmúlt vala; és a tenger többé nem vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 2, 'És én János látám a szent várost, az új Jeruzsálemet, a mely az Istentől szálla alá a mennyből, elkészítve, mint egy férje számára felékesített menyasszony.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 3, 'És hallék nagy szózatot, a mely ezt mondja vala az égből: Ímé az Isten sátora az emberekkel van, és velök lakozik, és azok az ő népei lesznek, és maga az Isten lesz velök, az ő Istenök.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 4, 'És az Isten eltöröl minden könyet az ő szemeikről; és a halál nem lesz többé; sem gyász, sem kiáltás, sem fájdalom nem lesz többé, mert az elsők elmúltak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 5, 'És monda az, a ki a királyiszéken ül vala: Ímé mindent újjá teszek. És monda nékem: Írd meg, mert e beszédek hívek és igazak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 6, 'És monda nékem: Meglett. Én vagyok az Alfa és az Omega, a kezdet és a vég. Én a szomjazónak adok az élet vizének forrásából ingyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 7, 'A ki győz, örökségül nyer mindent; és annak Istene leszek, és az fiam lesz nékem.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 8, 'A gyáváknak pedig és hitetleneknek, és útálatosoknak és gyilkosoknak, és paráznáknak és bűbájosoknak, és bálványimádóknak és minden hazugoknak, azoknak része a tűzzel és kénkővel égő tóban lesz, a mi a második halál.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 9, 'És jöve hozzám egy a hét angyal közül, a kinél a hét utolsó csapással telt hét pohár vala, és szóla nékem, mondván: Jer, megmutatom néked a menyasszonyt, a Bárány feleségét.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 10, 'És elvive engem lélekben egy nagy és magas hegyre és megmutatá nékem azt a nagy várost, a szent Jeruzsálemet, a mely Istentől szállott alá a mennyből.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 11, 'Benne vala az Isten dicsősége; és annak világossága hasonló vala a legdrágább kőhöz, úgymint kristálytiszta jáspis kőhöz;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 12, 'És nagy és magas kőfala vala, tizenkét kapuja, és a kapukon tizenkét angyal, és felírott nevek, a melyek az Izráel fiai tizenkét törzsének nevei:');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 13, 'Napkeletről három kapu; északról három kapu; délről három kapu: napnyugotról három kapu.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 14, 'És a város kőfalának tizenkét alapja vala, és azokon a Bárány tizenkét apostolának nevei.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 15, 'A ki pedig én velem beszéle, annál vala egy arany vessző, hogy megmérje a várost, és annak kapuit és kőfalát.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 16, 'És a város négyszögben fekszik, és a hossza annyi, mint a szélessége. És megméré a várost a vesszővel tizenkétezer futamatnyira: annak hosszúsága és szélessége és magassága egyenlő.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 17, 'És megméré annak kőfalát száznegyvennégy singre, ember mértékével, azaz angyaléval.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 18, 'És kőfalának rakása jáspisból vala; a város pedig tiszta arany, tiszta üveghez hasonló.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 19, 'És a város kőfalának alapjai ékesítve valának mindenféle drágakövekkel. Az első alap jáspis; a második zafir; a harmadik kálczédon; a negyedik smaragd;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 20, 'Az ötödik sárdonix; a hatodik sárdius; a hetedik krizolitus; a nyolczadik berillus; a kilenczedik topáz; a tizedik krisopráz; a tizenegyedik jáczint; a tizenkettedik amethist.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 21, 'A tizenkét kapu pedig tizenkét gyöngy; minden egyes kapu egy-egy gyöngyből vala; és a város utczája tiszta arany, olyan mint az átlátszó üveg.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 22, 'És templomot nem láttam abban: mert az Úr, a mindenható Isten annak temploma, és a Bárány.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 23, 'És a városnak nincs szüksége a napra, sem a holdra, hogy világítsanak benne; mert az Isten dicsősége megvilágosította azt, és annak szövétneke a Bárány.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 24, 'És a pogányok, a kik megtartatnak, annak világosságában járnak; és a föld királyai az ő dicsőségöket és tisztességöket abba viszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 25, 'És annak kapui be nem záratnak nappal (éjszaka ugyanis ott nem lesz);');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 26, 'És a pogányok dicsőségét és tisztességét abba viszik.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 27, 'És nem megy abba be semmi tisztátalan, sem a ki útálatosságot és hazugságot cselekszik, hanem csak a kik beírattak az élet könyvébe, a mely a Bárányé.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 1, 'És megmutatá nékem az élet vizének tiszta folyóját, a mely ragyogó vala, mint a kristály, az Istennek és a Báránynak királyiszékéből jővén ki');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 2, 'Az ő utczájának közepén. És a folyóvízen innen és túl életnek fája vala, mely tizenkét gyümölcsöt terem vala, minden hónapban meghozván gyümölcsét; és levelei a pogányok gyógyítására valók.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 3, 'És semmi elátkozott nem lesz többé; és az Istennek és a Báránynak királyiszéke benne lesz; és ő szolgái szolgálnak néki;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 4, 'És látják az ő orczáját; és az ő neve homlokukon lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 5, 'És ott éjszaka nem lesz; és nem lesz szükségök szövétnekre és napvilágra; mert az Úr Isten világosítja meg őket, és országolnak örökkön örökké.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 6, 'És monda nékem: E beszédek hívek és igazak: és az Úr, a szent próféták Istene bocsátotta el az ő angyalát, hogy megmutassa az ő szolgáinak azokat, a miknek meg kell lenni hamar.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 7, 'Ímé eljövök hamar. Boldog, a ki megtartja e könyv prófétálásának beszédeit.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 8, 'És én János vagyok az, a ki ezeket hallottam és láttam: és mikor hallottam és láttam, leborulék az angyal lábai előtt, hogy őt imádjam, a ki nékem ezeket megmutatta vala.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 9, 'Az pedig monda nékem: Meglásd, ne tedd; mert szolgatársad vagyok néked, és a te atyádfiainak a prófétáknak, és azoknak, a kik megtartják e könyvnek beszédeit. Az Istent imádd.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 10, 'Azután monda nékem: Be ne pecsételd e könyv prófétálásának beszédeit, mert az idő közel van.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 11, 'A ki igazságtalan, legyen igazságtalan ezután is; és a ki fertelmes, legyen fertelmes ezután is; és a ki igaz, legyen igaz ezután is; és a ki szent, szenteltessék meg ezután is.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 12, 'És ímé hamar eljövök; és az én jutalmam velem van, hogy megfizessek mindenkinek, a mint az ő cselekedete lesz.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 13, 'Én vagyok az Alfa és az Omega, a kezdet és a vég, az első és utolsó.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 14, 'Boldogok, a kik megtartják az ő parancsolatait, hogy joguk legyen az életnek fájához, és bemehessenek a kapukon a városba.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 15, 'De kinn maradnak az ebek és a bűbájosok, és a paráznák és a gyilkosok, és a bálványimádók és mind a ki szereti és szólja a hazugságot.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 16, 'Én Jézus küldöttem az én angyalomat, hogy ezekről bizonyságot tegyen néktek a gyülekezetekben. Én vagyok Dávidnak ama gyökere és ága: ama fényes és hajnali csillag.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 17, 'És a Lélek és a menyasszony ezt mondják: Jövel! És a ki hallja, ezt mondja: Jövel! És a ki szomjúhozik, jőjjön el; és a ki akarja, vegye az élet vizét ingyen.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 18, 'Bizonyságot teszek pedig mindenkinek, a ki e könyv prófétálásának beszédeit hallja: Hogy ha valaki ezekhez hozzá tesz, e könyvben megírt csapásokat veti Isten arra;');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 19, 'És ha valaki elvesz e prófétálás könyvének beszédeiből, az Isten annak részét eltörli az élet könyvéből, és a szent városból, és azokból, a mik e könyvben megírattak.');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 20, 'Ezt mondja, a ki ezekről bizonyságot tesz: Bizony hamar eljövök. Ámen, bizony jövel Uram Jézus!');
INSERT INTO `HunKar_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 21, 'A mi Urunk Jézus Krisztusnak kegyelme legyen mindnyájan ti veletek. Ámen.');
